QuestTraduttoreQuestIT = QuestTraduttoreQuestIT or {}
local T = QuestTraduttoreQuestIT

T[2] = {
  title = "Sharptalon's Claw",
  desc = "Il possente ippogrifo Sharptalon è stato ucciso, e l'artiglio della bestia abbattuta testimonia la tua vittoria. Senani Thunderheart, allo Splintertree Post, vorrà senz'altro vedere questo trofeo, a prova delle tue imprese.",
  obj = "Porta lo Sharptalon's Claw a Senani Thunderheart a Splintertree Post, Ashenvale.",
  progress = "Sì, possente $C, ho percepito il tuo arrivo. Avrai altre notizie della caccia per me, immagino?",
  reward = "Notevole davvero, $N... prendere l'artiglio di Sharptalon non dev'essere stato facile! La Caccia di Ashenvale sta andando bene, per te!$B$BDa tempo Sharptalon terrorizzava i peon dei campi di taglialegna lungo il suo percorso, quando cercavano di arrivare fin qui, allo Splintertree Post. Quando si spargerà la voce che sei $Gstato:stata; tu ad abbattere la bestia, senza dubbio intorno ai falò e nelle segherie di tutta Ashenvale si sentiranno tanti canti entusiasti sul tuo coraggio!",
  en_title = "Sharptalon's Claw",
  en_obj = "Bring Sharptalon's Claw to Senani Thunderheart at Splintertree Post, Ashenvale.",
}
T[10] = {
  title = "La Redenzione di Scrimshank",
  desc = "Oh, è davvero terribile! Ho mandato il mio assistente migliore, Junior Surveyor Scrimshank, nel deserto a sud-est di qui, in una zona che chiamiamo il Gaping Chasm. Be', è scomparso, e nel suo ultimo rapporto diceva che lì intorno c'erano altri di quegli strani insetti. Possibile che ormai abbiano infestato due grandi regioni del deserto?$B$BDevi andare a cercare Scrimshank nel Gaping Chasm, per favore! Lui... o almeno la sua attrezzatura topografica, che temo sia tutto quello che resta di quel povero disgraziato.",
  obj = "Scopri la sorte di Junior Surveyor Scrimshank e riporta lui o la sua attrezzatura topografica a Senior Surveyor Fizzledowser a Gadgetzan.",
  progress = "Allora, che notizie mi porti? Sembri reduce da una bella battaglia... Scrimshank è vivo?",
  reward = "Era un bravo goblin, il giovane Scrimshank. Speriamo che non sia morto invano, grazie a quello che è riuscito a registrare con l'attrezzatura topografica.$B$BCon questi insetti, a quanto pare, abbiamo una bella grana tra le mani. Sono fin troppo astuti, e le ricerche fatte finora fanno pensare che potrebbero perfino essere controllati da qualcun altro! Se è così, è un brutto segno non solo per Gadgetzan, ma per tutto il deserto!",
}
T[17] = {
  title = "Raccolta di Reagenti a Uldaman",
  desc = "Ho sentito parlare di una pianta scoperta da poco, che chiamano magenta fungus caps. Cresce a ciuffi giù nel profondo del sito di scavo di Uldaman. Magari si trova anche da qualche altra parte, ma per ora è l'unico posto che conosco. Voglio studiare come si potrebbe usare in alchimia, ed è qui che entri in gioco tu.$B$BCerca i ciuffi di cappelli magenta e portamene una dozzina. Però ti avverto: se li scuoti, potrebbero sputare spore velenose.$B$BFammi questo favore e ti preparerò una dose di uno dei miei famosi elisir ristoratori!",
  obj = "Porta 12 Magenta Fungus Caps a Ghak Healtouch a Thelsamar.",
  progress = "Allora, li hai trovati i magenta fungus caps che mi servono per il lavoro alchemico? Niente cappelli — niente ricompensa!",
  reward = "Ben fatto, $N, hai dimostrato ancora una volta quanto vali! Studiare i cappelli sarà interessante, invero!$B$BE ora, come promesso, goditi un assaggio di una delle mie pozioni ristoratrici più potenti, presa dalla mia scorta personale...$B$BSe sei $Gun abile alchimista:un'abile alchimista;, magari potremmo fare qualche altro affare. In ogni caso, grazie dell'aiuto!",
  en_title = "Uldaman Reagent Run",
  en_obj = "Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar.",
}
T[19] = {
  title = "Tharil'zun",
  desc = "Fra qui e lo Stonewatch Keep le Blackrock Outrunners e i Rinnegati ci tendono imboscate. A capo delle Staffette c'è un orco di nome Tharil'zun — ed è lui che vogliamo. Portami la testa di Tharil'zun!",
  obj = "Porta la Tharil'zun's Head a Marshal Marris a Redridge.",
  progress = "Gli orchi Blackrock premono ancora forte. Ma almeno ci hai liberati da Tharil'zun?",
  reward = "Tharil'zun era un orco feroce e astuto. Ben fatto — di sicuro non si è lasciato abbattere facilmente. Ecco la tua ricompensa, $N.",
  en_title = "Tharil'zun",
  en_obj = "Bring Tharil'zun's Head to Marshal Marris in Redridge.",
}
T[20] = {
  title = "Minaccia Blackrock",
  desc = "Gli orchi Blackrock sono venuti dalle Burning Steppes e si sono presi lo Stonewatch Keep, a nord. Da lì partono per razziare le zone a nord di Lakeshire, e la gente è costretta a restare in città, chiusa dentro come bestiame.$B$BAiutaci a liberare Lakeshire da questa minaccia: uccidi gli orchi Blackrock e, come prova, portami dieci delle loro Battleworn Axes.$B$BI Blackrocks ci minacciano da nord, ma ci sono arrivati rapporti di altri orchi anche nell'angolo sud-orientale di Redridge. Se ne trovi, dai la caccia pure a loro.",
  obj = "Porta 10 Battleworn Axes a Marshal Marris a Lakeshire.",
  progress = "Allora, $N, hai ucciso qualche orco? Se sì, fammi vedere...",
  reward = "Grazie. Così di orchi di cui preoccuparci ne restano molti meno.",
  en_title = "Blackrock Menace",
  en_obj = "Bring 10 Battleworn Axes to Marshal Marris in Lakeshire.",
}
T[23] = {
  title = "Ursangous's Paw",
  desc = "<La zampa del possente orso Ursangous è il tuo trofeo per questa parte della Caccia di Ashenvale. Sopra c'è un piccolo emblema a forma di quarto di luna, di cui non si capisce il significato.$B$BPorta la zampa a Senani Thunderheart, allo Splintertree Post: dimostrerà che hai sconfitto la possente creatura e completato questa parte della caccia.>",
  obj = "Porta l'Ursangous's Paw a Senani Thunderheart a Splintertree Post, Ashenvale.",
  progress = "Ah — $N — pensavo proprio a te! Come procede la caccia?",
  reward = "Ah, la zampa di Ursangous! Hai un'abilità notevole, $C: a lui si attribuiscono molte uccisioni. La mezzaluna sulla zampa è senza dubbio il segno che lo hanno addestrato gli elfi della notte che si aggirano furtivi per Ashenvale. Ursangous è... era uno degli orsi più possenti che si potessero trovare da queste parti. Sconfiggere una creatura simile dimostra quanta volontà e determinazione hai.$B$BI tuoi antenati sarebbero fieri!",
  en_title = "Ursangous's Paw",
  en_obj = "Bring Ursangous's Paw to Senani Thunderheart at Splintertree Post, Ashenvale.",
}
T[24] = {
  title = "Shadumbra's Head",
  desc = "Un tempo veloce, Shadumbra ora giace immobile: hai vinto. La testa del nightsaber ucciso è un trofeo all'altezza di questo scontro della Caccia di Ashenvale. Senani Thunderheart, allo Splintertree Post, vorrà vedere un trofeo del genere per riconoscerti il merito di questa parte della Caccia di Ashenvale.",
  obj = "Porta la Shadumbra's Head a Senani Thunderheart a Splintertree Post, Ashenvale.",
  progress = "$GBen ritrovato:Ben ritrovata;, $N! Sei $Gvenuto:venuta; a mostrarmi la prova della caccia?",
  reward = "Nella Caccia di Ashenvale, una vittoria per $N! Ben fatto — la testa di Shadumbra è senza dubbio un trofeo all'altezza di uno scontro così notevole.$B$BIn tutto l'avamposto si conosceva bene la ferocia di Shadumbra. Per colpa di questa tigre ogni viaggio verso ovest era pieno di pericoli, soprattutto per chi andava a piedi fino alla Zoram Strand. Grazie a te, la minaccia è passata.",
  en_title = "Shadumbra's Head",
  en_obj = "Bring Shadumbra's Head to Senani Thunderheart at Splintertree Post, Ashenvale.",
}
T[25] = {
  title = "Stallo a Stonetalon",
  desc = "Se vuoi renderti utile, perché non fai qualcosa per quello che sta succedendo vicino al Talondeep Path?$B$BTra Ashenvale e Stonetalon i trasporti sono fermi: il lago ha preso vita e attacca qualsiasi cosa gli si avvicini... cioè chiunque passi sul sentiero. Picchiare duro sui water elementals serve, ma servirebbe ancora di più che qualcuno andasse in ricognizione al gazebo sul Mystral Lake — quello da cui si vede bene l'avamposto dell'Alleanza.$B$BTe la senti di renderti utile?",
  obj = "Elimina 12 Befouled Water Elementals al Mystral Lake, dritto a est del Talondeep Path e a sud-ovest dello Splintertree Post.$B$BEsplora il gazebo sul Mystral Lake che domina il vicino avamposto dell'Alleanza.$B$BTorna da Mastok Wrilehiss allo Splintertree Post, ad Ashenvale.",
  progress = "Sei già $Gtornato:tornata;? Com'è là fuori — tutto sistemato, grazie a te?",
  reward = "Sì, mi è arrivata voce che qualcuno ha messo sottosopra il lago là fuori, come un dust devil che attraversa le Barrens. E a sentire in giro, potremmo riuscire a sistemare laggiù una zona di osservazione per tenere d'occhio i nostri amici dell'Alleanza. Beh, sempre che riusciamo a tenerla nascosta...$B$BAlla fine, a quanto pare, ti sei $Grivelato:rivelata; piuttosto utile: i trasporti tra qui e Stonetalon dovrebbero avere vita più facile. Prendi questo — te lo sei guadagnato.",
  en_title = "Stonetalon Standstill",
  en_obj = "Dispatch 12 Befouled Water Elementals at Mystral Lake, due east of the Talondeep Path and southwest of Splintertree Post.$B$BScout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost.$B$BReturn to Mastok Wrilehiss at Splintertree Post, Ashenvale.",
}
T[26] = {
  title = "Una Lezione da Imparare",
  desc = "$N, seguo i tuoi progressi con grande gioia. Stai senza dubbio diventando $Gun:una; $Gprezioso protettore:preziosa protettrice; della natura.$B$BÈ giunto il momento che tu conosca meglio uno dei tanti aspetti animali che Cenarius ci ha concesso di assumere — quello che ti permette di muoverti nell'acqua con pieno controllo e padronanza. Per questo dovrai recarti al villaggio di Nighthaven, a Moonglade, e parlare con Dendrite Starblaze del Cenarion Circle. Da lì in poi sarà lui a guidarti.",
  obj = "Parla con Dendrite Starblaze nel villaggio di Nighthaven, Moonglade.",
  reward = "Salve, giovane $Gdruido:druida;; è giunto il momento che tu conosca la nostra forma acquatica. Ti permette di muoverti liberamente nell'acqua, per tutto il tempo che vuoi. Questo aspetto si rivelerà uno strumento utile e una benedizione... ma va guadagnato prima di poterlo padroneggiare.$B$BDovrai superare due prove. La prima valuterà la tua capacità di agire in acqua sotto pressione. La seconda saggerà la tua determinazione a comprendere i vari aspetti di questa forma.$B$BTieniti $Gpronto:pronta;, perché il tempo delle prove è ormai arrivato.",
  en_title = "A Lesson to Learn",
  en_obj = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[27] = {
  title = "Una Lezione da Imparare",
  desc = "$N, seguo i tuoi progressi con grande gioia: senza dubbio stai diventando $Gun prezioso protettore:una preziosa protettrice; della natura.$B$BÈ giunto il momento di conoscere meglio uno degli aspetti animali in cui possiamo trasformarci grazie al dono con cui ci ha benedetto Cenarius — la forma che ti dà il comando e la padronanza dell'acqua. Per questo dovrai andare al villaggio di Nighthaven, a Moonglade, e parlare con Dendrite Starblaze del Cenarion Circle. Sarà lui a guidarti.",
  obj = "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.",
  reward = "Salute a te, $Ggiovane druido:giovane druida;. È tempo che tu conosca la nostra aquatic form, una forma che ti permette di muoverti nell'acqua liberamente, senza limiti. Questo aspetto si rivelerà uno strumento utile e una benedizione... ma prima di padroneggiarlo dovrai guadagnartelo.$B$BDovrai superare due prove. La prima valuterà come sai agire in acqua sotto pressione; la seconda, la tua determinazione a comprendere gli aspetti della forma stessa.$B$BTieniti $Gpronto:pronta;, perché il tempo delle prove è giunto.",
  en_title = "A Lesson to Learn",
  en_obj = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[28] = {
  title = "Prova del Lago",
  desc = "Per la prima prova dovrai cercare una Shrine Bauble nelle profondità del Lake Elune'ara. Si deteriora in fretta, quindi portala allo Shrine of Remulos senza perdere un attimo. Al santuario usa la bolla, poi parla con Tajarri, che troverai lì; è una delle guardiane più fidate di Moonglade.$B$BIl tempo per riuscirci è limitato, e potresti dover competere con altri druidi che cercano anche loro le bolle. Per farcela saranno fondamentali la prontezza della mente e la destrezza del corpo.$B$BBuona fortuna, $N.",
  obj = "Trova una Shrine Bauble in Lake Elune'ara e portala a Shrine of Remulos, nel nord-ovest di Moonglade. Una volta lì, usa la Shrine Bauble.$B$BDopo devi parlare con Tajarri al santuario per completare la prova.",
  progress = "Per completare la Prova del Lago devi usare la Shrine Bauble dentro i confini di questo santuario. Finché non lo fai, la prova resta incompiuta e rischi di fallirla.",
  reward = "Bene, bene, a quanto pare $Gun altro druido:un'altra druida; ha superato la Prova del Lago! Ben fatto, $Gmio giovane amico:mia giovane amica; — ben fatto.$B$BCome ti ho detto, il mio nome è Tajarri. È sia un dovere che un privilegio servire come guardiana di Moonglade, e in particolare di questo santuario. Keeper Remulos guida il Cenarion Circle nel proteggere la natura e l'equilibrio, il suo santuario è un tributo eterno a questa causa. Usare la bolla qui rende omaggio all'importanza che questo luogo ha nel Circolo.",
  en_title = "Trial of the Lake",
  en_obj = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.$B$BYou must speak with Tajarri at the shrine afterwards in order to complete the trial.",
}
T[29] = {
  title = "Prova del Lago",
  desc = "Per la prima prova, cerca nelle profondità del Lake Elune'ara una Shrine Bauble. Si deteriora rapidamente, quindi portala allo Shrine of Remulos il prima possibile. Lì usa la bolla, poi parla con Tajarri: è una delle custodi più fidate di Moonglade.$B$BIl tempo per completare il compito è limitato, e potresti dover competere con altri druidi che cercano anche loro le bolle. L'agilità mentale e fisica sarà decisiva per riuscire.$B$BBuona fortuna, $N.",
  obj = "Trova una Shrine Bauble in Lake Elune'ara e portala a Shrine of Remulos, nel nord-ovest di Moonglade. Una volta lì, usa la Shrine Bauble.$B$BDopo dovrai parlare con Tajarri al santuario per completare la prova.",
  progress = "Per completare la Prova del Lago, devi usare la Shrine Bauble entro i confini di questo luogo sacro. Finché non lo farai, la prova non sarà conclusa e rischierai di fallirla.",
  reward = "Bene bene, sembra che $Gun altro druido:un'altra druida; abbia superato la Prova del Lago! Ben fatto, $Gmio giovane amico:mia giovane amica; — ben fatto.$B$BCome ho detto, mi chiamo Tajarri. Ho il dovere e il privilegio di essere custode di Moonglade, e in particolare di questo santuario. Keeper Remulos guida il Cenarion Circle nella salvaguardia della natura e dell'equilibrio, e il tempio a lui dedicato è un omaggio perenne a questa missione. Usare qui la bolla è un modo per riconoscere l'importanza che questo luogo ha per il Circolo.",
  en_title = "Trial of the Lake",
  en_obj = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.$B$BYou must speak with Tajarri at the shrine afterwards in order to complete the trial.",
}
T[30] = {
  title = "Prova del Leone Marino",
  desc = "Per la seconda prova ti serviranno le due metà che formano il Pendant of the Sea Lion. Una trae potere dall'agilità con cui l'aspetto del leone marino scivola nell'acqua; l'altra, dalla sua incredibile resistenza. I druidi attingono in egual misura a entrambe le qualità per incarnare l'aspetto della loro aquatic form.$B$BChiedi agli abitanti di Moonglade dove potrebbero trovarsi le parti, poi portale qui tutte e due per unirle. Quando il pendente sarà formato, consegnalo a Dendrite Starblaze.",
  obj = "Trova l'Half Pendant of Aquatic Agility e l'Half Pendant of Aquatic Endurance. Parla con gli abitanti di Moonglade per ottenere indizi su dove possano trovarsi questi oggetti.$B$BForma il Pendant of the Sea Lion con le due metà del pendente. Per farlo devi trovarti vicino a Shrine of Remulos.$B$BPorta il pendente completo a Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.",
  progress = "Hai formato il pendente da farmi esaminare, $N? Se ti serve una mano per trovare le parti, prova a chiedere alla gente del posto. Troverai quello che cerchi, e in più avrai un motivo per esplorare questa radura meravigliosa e sacra.",
  reward = "Hai superato la Prova del Leone Marino, $N — congratulazioni.$B$BOgni compito svolto per ottenere il pendente mostra chiaramente che agilità e resistenza sono necessarie per agire in armonia con ciò che desideri fare sott'acqua . L'una non può esistere senza l'altra, e nessuna delle due è possibile senza la tua volontà di abbracciare l'aspetto del leone marino.$B$BRicorda bene queste lezioni e fai affidamento su di esse quando avrai ottenuto la tua aquatic form.",
  en_title = "Trial of the Sea Lion",
  en_obj = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.$B$BForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.$B$BBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[31] = {
  title = "Aquatic Form",
  desc = "Hai completato le lezioni che tutti i giovani druidi devono seguire prima di poter assumere un aspetto acquatico. Ora torna dal tuo istruttore, Turak Runetotem, a Thunder Bluff. Mostragli il pendente e fagli vedere che sei $Gpronto:pronta; a imparare quello che ha da insegnarti. Sarà lui a completare il tuo addestramento e a farti diventare tutt'uno con l'acqua.$B$BArrivederci, $Ggiovane druido:giovane druida;. Ci parleremo ancora.",
  obj = "Torna a Thunder Bluff e mostra il Pendant of the Sea Lion a Turak Runetotem.",
  progress = "Il tuo ritorno a Thunder Bluff è stato annunciato, ma prima di insegnarti la tua aquatic form mi serve una prova di quello che hai imparato a Moonglade.$B$BHai il Pendant of the Sea Lion?",
  reward = "Davvero notevole, $N. I tuoi antenati sarebbero soddisfatti dei tuoi progressi! Sei $Gpronto:pronta; a imparare la tua aquatic form, e insegnartela è per me un piacere.$B$BCome riconoscimento di ciò che hai compiuto nelle due prove, ti do inoltre questo oggetto. Spero che sia un'aggiunta gradita al tuo equipaggiamento di $Gprotettore:protettrice; della natura e $Gcustode:custode; dell'equilibrio.",
  en_title = "Aquatic Form",
  en_obj = "Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion.",
}
T[32] = {
  title = "L'Ascesa dei Silithid",
  desc = "Ecco il tuo rapporto. Ti raccomando di portarlo a qualcuno che se ne intenda di queste cose.$B$BConosco uno studioso troll, si chiama Zilzibin Drumlore. Ha passato molto tempo a studiare le forme di vita che esistono solo nell'ecologia di Azeroth; e per giunta è uno storico! Se ti serve qualcuno che ti aiuti a capire cos'è esattamente questa minaccia e come fermarla, dallo a lui. Ci servirà tutto l'aiuto possibile.$B$BZil abita in una casa al secondo livello di The Drag di Orgrimmar.",
  obj = "Porta il rapporto a Zilzibin Drumlore a Orgrimmar.",
  progress = "Mi spiace, non ti conosco... però tu, a quanto pare, hai almeno sentito parlare di me. Allora, cosa posso fare per te? Hai qualcosa da darmi?",
  reward = "Questo rapporto... Con queste bestie ho già avuto a che fare. Fizzledowser è stato saggio a mandarmi questo rapporto, e anche te.$B$BQueste creature non ci metteranno molto a divorare il deserto di Tanaris; sono una delle minacce più grandi che tutti noi ci troveremo mai ad affrontare. Imparalo bene, questo nome, $N: silithid. Gli insetti di cui parla il rapporto sono i silithid, gli strumenti di uno dei pericoli più gravi che incombono sia sull'Orda sia sull'Alleanza.$B$BSe solo fossimo stati abbastanza intelligenti da capirlo prima.",
}
T[34] = {
  title = "Un Ospite Indesiderato",
  desc = "Ancora una volta mi ritrovo il giardino calpestato e saccheggiato, e so bene chi è il bruto che lo fa: quel cinghiale forsaken che Marshal Marris ha preso a chiamare Bellygrub.$B$BI narcisi, adesso, potrò ripiantarli solo la prossima stagione. Rovinato! Quel cinghiale minaccioso ha rovinato tutto. Togli di mezzo quella peste! Se mi mostri la sua zanna, sarò felice di ricompensarti. Pare che passi il tempo a cercare cibo nel campo a sud-ovest di Lakeshire, ma ogni tanto si spinge fin qui e mi entra in giardino.",
  obj = "Martie Jainrose di Lakeshire vuole che tu uccida Bellygrub. Portale la sua zanna come prova.",
  progress = "Bellygrub fa ancora danni, o sei $Griuscito:riuscita; a liberare Lakeshire da quella peste una volta per tutte?",
  reward = "Finalmente quella minaccia riposa in pace! Grazie, $N, mi hai fatto un gran favore. Questa stagione il giardino sarà tutto in fiore!",
  en_title = "An Unwelcome Guest",
  en_obj = "Martie Jainrose of Lakeshire wants you to kill Bellygrub.  Bring her his tusk as proof.",
}
T[48] = {
  title = "Dolce Ambra",
  desc = "Nella terra a sud, dove i tralci s'intrecciano e strisciano,$Bc'è un pozzo nascosto, in cui l'acqua scorre profonda.$BPura come la sacra Figlia della Luce,$Bportami ora un po' di Holy Spring Water.",
  obj = "Porta Holy Spring Water a Grimbooze Thunderbrew.",
  progress = "Hic! Oh oh! Vuoi il bis?$B$BNella terra a sud, dove i tralci s'intrecciano e strisciano,$Bc'è un pozzo nascosto, in cui l'acqua scorre profonda.$BPura come la sacra Figlia della Luce,$Bportami ora un po' di Holy Spring Water.",
  reward = "Hic! Oh Oh!",
  en_title = "Sweet Amber",
  en_obj = "Bring Holy Spring Water to Grimbooze Thunderbrew.",
}
T[49] = {
  title = "Dolce Ambra",
  desc = "Ambra è il colore del più lungo amore della mia vita,$Bcome le ultime braci del tramonto nel cielo lassù.$BProcurami, perché il mio amore possa nascere,$Bun sacco per tipo: orzo, segale e mais.",
  obj = "Grimbooze Thunderbrew vuole una Sack of Barley, una Sack of Rye e un Sack of Corn.",
  progress = "Il bis? Ma certo!$B$BAmbra è il colore del più lungo amore della mia vita,$Bcome le ultime braci del tramonto nel cielo lassù.$BProcurami, perché il mio amore possa nascere,$Bun sacco per tipo: orzo, segale e mais.",
  reward = "Hic! Oh oh!",
  en_title = "Sweet Amber",
  en_obj = "Grimbooze Thunderbrew wants a Sack of Barley, a Sack of Rye and a Sack of Corn.",
}
T[50] = {
  title = "Dolce Ambra",
  desc = "Mescolerò e rimescolerò finché il mosto avrò ottenuto,$Bsarà la nostra scorta privata, un segreto ben tenuto.$BUn alambicco di solido metallo va forgiato,$Bportami del Verargento e il canto sarà terminato.",
  obj = "Grimbooze Thunderbrew vuole del Verargento.",
  progress = "Un bis per te? Ma certo, $Gamico:amica;!$B$BMescolerò e rimescolerò finché il mosto avrò ottenuto,$Bsarà la nostra scorta privata, un segreto ben tenuto.$BUn alambicco di solido metallo va forgiato,$Bportami del Verargento e il canto sarà terminato.",
  reward = "Hic! Oh oh!",
  en_title = "Sweet Amber",
  en_obj = "Grimbooze Thunderbrew wants Truesilver.",
}
T[51] = {
  title = "Dolce Ambra",
  desc = "Non ancora filtrato, ma appena distillato,$Bcome terra senza semi che attende, già arato.$BPoi la carbonella preparerò con cura,$Bportami un a sycamore branch, ecco la tua prossima avventura.",
  obj = "Porta a Sycamore Branch a Grimbooze Thunderbrew.",
  progress = "Un bis? Beh, per te farei qualsiasi cosa!$B$BNon ancora filtrato, ma appena distillato,$Bcome terra senza semi che attende, già arato.$BPoi la carbonella preparerò con cura,$Bportami un a sycamore branch, ecco la tua prossima avventura.",
  reward = "Hic! Oh oh!",
  en_title = "Sweet Amber",
  en_obj = "Bring a Sycamore Branch to Grimbooze Thunderbrew.",
}
T[53] = {
  title = "Dolce Ambra",
  desc = "Un liquido mellifluo, limpido come lacrime d’infante,$Bcon gli anni si tinge d’ambra, profonda ed elegante.$BMa prima di sbronzarci fino a perder la ragione,$Buna botte di quercia tostata va messa in costruzione.",
  obj = "Porta a Grimbooze Thunderbrew una bundle of Charred Oak.",
  progress = "Ma certo, te la ricanto, $Gamico:amica;!$B$BUn liquido mellifluo, limpido come lacrime d’infante,$Bcon gli anni si tinge d’ambra, profonda ed elegante.$BMa prima di sbronzarci fino a perder la ragione,$Buna botte di quercia tostata va messa in costruzione.",
  reward = "Invecchiato in botte, filtrato nel carbone,$Bti sfiora le labbra e ti scuote ogni emozione.$BOra beviamo, un brindisi a te, amico mio,$Be già che ci siamo a Grimbooze Thunderbrew, cioè io!",
  en_title = "Sweet Amber",
  en_obj = "Bring Grimbooze Thunderbrew a bundle of Charred Oak.",
}
T[55] = {
  title = "Morbent Fel",
  desc = "Morbent Fel si nasconde nel suo covo, la casa arroccata in cima alla collina a est, che domina il cimitero di Raven Hill. I suoi giorni in questa terra sono contati...$B$BUsa la Morbent's Bane contro di lui. Renderà inutili le sue magie protettive.$B$BUccidilo. Uccidilo, e salvaci dalla sua malvagità. Sii lo strumento della mia vendetta, e $Gun eroe:un'eroina; di Duskwood!",
  obj = "Usa la Morbent's Bane su Morbent Fel, uccidi Morbent Fel, poi riporta la Morbent's Bane a Sven al suo accampamento.",
  progress = "Morbent Fel è stato sconfitto?!",
  reward = "Morbent Fel è stato sconfitto. I cavalieri oscuri sono ancora in libertà, ma una piccola parte delle mie vane speranze si è avverata.$B$BHai fatto l'impossibile, e le tue gesta vivranno per sempre nelle leggende di Duskwood.$B$BVa', $N. E forse, un giorno, il destino potrà riportarti da me...",
  en_title = "Morbent Fel",
  en_obj = "Use Morbent's Bane on Morbent Fel, kill Morbent Fel, then return Morbent's Bane to Sven at his camp.",
}
T[56] = {
  title = "La Night Watch",
  desc = "Come Comandante della Night Watch ho giurato di proteggere i cittadini di Darkshire. Stormwind ha richiamato le guardie che aveva mandato qui e ci ha lasciati a cavarcela da soli.$B$BAbbiamo bisogno del tuo aiuto, se ti senti $Gdegno:degna; del compito! Dai una mano alla Night Watch: spingiti nei Tranquil Gardens, appena a sud di Darkshire, e uccidi 8 Skeletal Warriors e 6 Skeletal Mages. Bisogna fermare la minaccia dei non morti!",
  obj = "Commander Althea Ebonlocke of Darkshire vuole che tu uccida 8 Skeletal Warriors e 6 Skeletal Mages.",
  progress = "Vedo che sei $Gtornato:tornata;, $N. Se vuoi dimostrare alla Night Watch che le sei utile, fatti rivedere quando avrai ucciso 8 Skeletal Warriors e 6 Skeletal Mages.",
  reward = "Splendido, $N. Hai reso un servizio alla gente di Darkshire, e per questo sarai $Gricompensato:ricompensata;.",
  en_title = "The Night Watch",
  en_obj = "Commander Althea Ebonlocke of Darkshire wants you to kill 8 Skeletal Warriors and 6 Skeletal Mages.",
}
T[57] = {
  title = "La Night Watch",
  desc = "$N, mi arriva voce che la foresta è infestata dai non morti! Se te la senti, va' al cimitero di Raven Hill e uccidi 15 di quei ripugnanti Skeletal Fiends e 15 Skeletal Horrors. Mi segnalano scheletri anche appena a sud di Darkshire, dentro e intorno al Tranquil Gardens Cemetery. I non morti vanno cacciati da Duskwood!",
  obj = "Commander Althea Ebonlocke of Darkshire vuole che tu uccida 15 Skeletal Fiends e 15 Skeletal Horrors.",
  progress = "$N, torna da me quando avrai ucciso 15 Skeletal Fiends e 15 Skeletal Horrors.",
  reward = "La gente di Darkshire ti ringrazia, $N. Ti sei $Gdimostrato:dimostrata; $Gun grande alleato:una grande alleata; della Night Watch.",
  en_title = "The Night Watch",
  en_obj = "Commander Althea Ebonlocke of Darkshire wants you to kill 15 Skeletal Fiends and 15 Skeletal Horrors.",
}
T[58] = {
  title = "La Night Watch",
  desc = "A Raven Hill la situazione resta grave, e la sicurezza di Darkshire è nelle tue mani, $N. Non ho abbastanza Guardiani per proteggere il villaggio. Ci serve che tu vada un'altra volta a Raven Hill e liberi il mausoleo orientale da 20 Plague Spreaders!",
  obj = "Commander Althea Ebonlocke of Darkshire vuole che tu uccida 20 Plague Spreaders nel mausoleo orientale di Raven Hill.",
  progress = "Mi serve il tuo aiuto, $N. Va' al cimitero a nord-ovest e libera il mausoleo orientale da 20 Plague Spreaders.$B$BQuando hai finito, torna da me.",
  reward = "A nome della gente di Darkshire e come Capo della Night Watch, ti ringrazio del coraggio e della dedizione, $N. Che la Luce illumini il tuo cammino.",
  en_title = "The Night Watch",
  en_obj = "Commander Althea Ebonlocke of Darkshire wants you to kill 20 Plague Spreaders in the eastern Raven Hill mausoleum.",
}
T[63] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Lungo la costa di Silverpine, a ovest del Sepulcher, troverai un santuario contaminato dalla pestilenza. Gli spiriti di quel luogo non parlano più al nostro popolo, e toccherà a te sconfiggere la manifestazione e purificare la pozza.$B$BPrendi i bracciali dell'elementale e mettili sul braciere insieme alle ultime gocce della pozione di Brine. Il rituale dovrebbe bastare a evocare uno spirito puro, con cui potrai comunicare.$B$BPortami la prova che hai svolto il compito, e ti ricompenserò con il tuo totem.",
  obj = "Sconfiggi Manifestation of Water Corrotta e metti i Bracciali della Manifestazione Corrotta, insieme alle Remaining Drops of Purest Water, sul Brazier of Everfount nella Silverpine Forest.",
  progress = "Il braciere riflette ancora la luce dei dintorni, e la fiamma si muove appena quando ti avvicini.$B$BPare che la corruzione, lungo le colline, si sia tenuta a distanza e, a parte i componenti che mancano, il braciere sembra pronto per il rituale che evocherà una manifestation of water purificata.",
  reward = "Metti i bracciali sopra il braciere, poi versi nella fiamma le ultime gocce della pozione di Brine. Crepitano appena la toccano, e cominci a recitare le semplici parole che ti ha insegnato Islen....",
  en_title = "Call of Water",
  en_obj = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest.",
}
T[66] = {
  title = "La Leggenda di Stalvan",
  desc = "Stanotte un'angoscia terribile mi ha gelato il sangue. Ho percepito che mia nipote, Alyssa, era in grave pericolo. Ho interrogato le carte, e dal tavolo mi ha fissata la Morte.$B$BDopo essere caduta in una lunga trance oscura, sono riuscita a trovare un indizio su questo mistero terrificante. Mi è giunto un nome, quello di Stalvan.$B$BCerca il Cancelliere nel Town Hall e vedi se riesci a scoprire qualcosa di più su questo personaggio. Temo per tutti noi.",
  obj = "Cerca Clerk Daltry in Darkshire Town Hall.",
  reward = "Ah, allora ti ha mandato Madame Eva. . . .",
  en_title = "The Legend of Stalvan",
  en_obj = "Seek out the Clerk Daltry in the Darkshire Town Hall.",
}
T[67] = {
  title = "La Leggenda di Stalvan",
  desc = "Stalvan, eh? Fammi controllare il registro cittadino.$B$BStalvan. . .Stalvan. . .vediamo. Ah, eccolo! C'è una voce a nome di un certo Mr. Stalvan Mistmantle. L'ultimo indirizzo registrato è la Moonbrook Schoolhouse. Caspita, altro che dati aggiornati!$B$BMi faresti un favore, $Gamico:amica;? Se ti capita di andare a Moonbrook, fammi sapere se scopri qualcosa di nuovo su questo tizio. Mi piace tenere i registri in ordine.",
  obj = "Vai a Moonbrook Schoolhouse e riporta a Clerk Daltry ogni informazione aggiornata su Stalvan.",
  reward = "Il vecchio baule si apre cigolando. . . .",
  en_title = "The Legend of Stalvan",
  en_obj = "Travel to the Moonbrook Schoolhouse and bring back any updated information about Stalvan to Clerk Daltry.",
}
T[68] = {
  title = "La Leggenda di Stalvan",
  desc = "Nel vecchio baule trovi un'A Dusty Unsent Letter.",
  obj = "Porta la Lettera Polverosa Mai Spedita a Clerk Daltry.",
  progress = "Ah, mi ricordo di te. Sei $Gquello:quella; che chiedeva di quel tale, Stalvan. Hai poi trovato quello che cercavi?",
  reward = "Interessante. Quindi quel tipo ha passato davvero un po' di tempo a Moonbrook, dopotutto. È piuttosto strano che la lettera non sia mai stata consegnata. Ad ogni modo, aggiornerò il registro.",
  en_title = "The Legend of Stalvan",
  en_obj = "Take the Dusty Unsent Letter to Clerk Daltry.",
}
T[69] = {
  title = "La Leggenda di Stalvan",
  desc = "Oh, cielo! Mi sarà sfuggito la prima volta. Nel registro, proprio sotto il primo indirizzo di Stalvan, ce n'è un altro, cancellato solo in parte. A quanto pare era diretto a The Lion's Pride Inn, a Goldshire. Forse ti conviene controllare lì, $N.",
  obj = "Vai a The Lion's Pride Inn e scopri se lì qualcuno ha mai sentito il nome Stalvan.",
  reward = "Stalvan? Mi dice proprio qualcosa.",
  en_title = "The Legend of Stalvan",
  en_obj = "Go to The Lion's Pride Inn to see if anyone there has heard of the name Stalvan.",
}
T[70] = {
  title = "La Leggenda di Stalvan",
  desc = "Il nome Stalvan mi dice qualcosa. Ora ricordo.$B$BMolti anni fa, in una notte di tempesta, è arrivato un messaggero in cerca di un riparo fino al mattino. Verso mezzanotte, l'uomo è corso giù per le scale urlando, con il volto pallido di paura. Ancora in camicia da notte, è sparito sotto l'acquazzone.$B$BNella fretta ha dimenticato le lettere nella cassa al piano di sopra. Non è mai tornato a riprenderle. Ne è rimasta una di quel tale, Stalvan, destinata al Canal District di Stormwind. Prendila pure.",
  obj = "Recupera dalla cassa la Lettera Non Consegnata di Stalvan e portala in Canal District, a Stormwind.",
  progress = "Che ci hai lì? Fammi dare un'occhiata. . .",
  reward = "Hai una bella faccia tosta a portare questa roba qui.",
  en_title = "The Legend of Stalvan",
  en_obj = "Retrieve Stalvan's Undelivered Letter from the chest and deliver it to the Canal District in Stormwind.",
}
T[72] = {
  title = "La Leggenda di Stalvan",
  desc = "Mio padre era il custode della tenuta molto prima di me. È toccato a lui pulire il sangue dopo il massacro. Ma questo non c'entra.$B$BIl fondo fiduciario dei Flintridge ha esaurito anche gli ultimi soldi. Ora quel che resta dei beni di famiglia finirà all'asta. Prenditela con quegli avvoltoi del fisco. Immagino che, se proprio muori dalla voglia di saperne di più, tu possa frugare tra questa robaccia. Chissà cosa potresti trovare.",
  obj = "Fruga tra i beni imballati in cerca di un indizio.",
  reward = "Fai scivolare lentamente via il coperchio della cassa. . . .",
  en_title = "The Legend of Stalvan",
  en_obj = "Search through the packed up possessions for a clue.",
}
T[74] = {
  title = "La Leggenda di Stalvan",
  desc = "Nella cassa trovi vari oggetti: cimeli ammuffiti, un ritratto di famiglia, qualche trofeo di caccia e alcuni vecchi libri. Vicino al fondo, sotto un vaso di ceramica, scopri un'A Torn Journal Page.",
  obj = "La Journal Page Strappata che hai scoperto ti fornisce il prossimo indizio.",
  progress = "Cos'hai lì? Non ci vedo. Ho la vista molto debole. Mettimelo in mano.",
  reward = "Riesco a malapena a distinguere queste lettere. Ma questa calligrafia mi ricorda qualcosa che ho visto una volta, prima che la vista mi si indebolisse così tanto.",
  en_title = "The Legend of Stalvan",
  en_obj = "The Torn Journal page you discovered provides your next clue.",
}
T[75] = {
  title = "La Leggenda di Stalvan",
  desc = "Quando mi sono trasferito qui, nel baule al piano di sopra c'era un fascio di pergamene. Ci ho dato un'occhiata appena arrivato, ma ho lasciato perdere quando la nebbia mi ha appannato gli occhietti.$B$BFa' un favore a un povero vecchio quasi cieco: controlla il baule di sopra e cerca qualcosa che possa aiutarti a scoprire di più su questo tale, Stalvan. Mi pare proprio che ci sia un'a faded journal page che potrebbe interessarti. Portamela e ti aiuterò come posso.",
  obj = "Marshal Haggard vuole che tu cerchi la Faded Journal Page nel baule al piano di sopra.",
  progress = "Hai trovato la pagina di cui ti parlavo, $N?",
  reward = "L'hai trovata!",
  en_title = "The Legend of Stalvan",
  en_obj = "Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page.",
}
T[77] = {
  title = "Una Situazione Appiccicosa",
  desc = "Possiedo i materiali d'imballaggio originali del vino dolce che cerca Dran Droffers, e ti aiuterò a imballarlo per lo scorbutico padre di Malton... in cambio di due bottiglie in più del suddetto vino dolce. Lo troverai nelle casse della base abbandonata dell'Orda, vicino a Skulk Rock.$B$BIl compito sarà arduo, vale a dire; alle rovine stanno appiccicati melme e fanghi immondi; si dice che li guidi una sorta di melma suprema. Comunque sia, procurati il vino dolce e torna qui da me per l'imballaggio.",
  obj = "Recupera 10 bottiglie di Hinterlands Honey Ripple dalle casse che si trovano intorno alla base abbandonata dell'Orda a Skulk Rock.",
  progress = "Confido che tu sia $Gvenuto:venuta; al nostro accampamento a consegnare le bottiglie di vino dolce indispensabili all'impresa in corso, sì?",
  reward = "Lavoro eseguito con finezza, $N. Sono lieto che tu abbia avuto la lungimiranza di non ammaccare la delicatezza del vino dolce. Non c'è nulla di peggio del bouquet di un vino dolce sballottato senza motivo.$B$BCi vorrà un momento perché la magia si compia su questo prezioso carico. A dire il vero, di magia non ce n'è; ho semplicemente degli imballaggi vuoti di Hinterlands Honey Ripple. Il nostro raggiro trasformerà queste bottiglie in un tesoro alcolico senza tempo.$B$BAvanti — per la buona bevuta!",
}
T[78] = {
  title = "La Leggenda di Stalvan",
  desc = "Conosco qualcuno che potrebbe aiutarti. Ai tempi in cui guidavo la Stormwind Guard, andavamo a bere qualcosa alla Scarlet Raven Tavern di Darkshire. Il Locandiere, Smitts, era un vero esperto di storie del posto. Mostragli questa pagina e senti cosa ne pensa.",
  obj = "Porta la Journal Page Sbiadita a Tavernkeep Smitts.",
  progress = "Ti manda Marshal Haggard? E perché non l'hai detto subito?$B$BAh, il buon vecchio Haggard. Poveretto, tra non molto sarà completamente cieco. Comunque, fammi vedere cos'hai lì.",
  reward = "Per la Luce! Altroché se la riconosco, questa calligrafia.",
  en_title = "The Legend of Stalvan",
  en_obj = "Take the Faded Journal Page to Tavernkeep Smitts.",
}
T[79] = {
  title = "La Leggenda di Stalvan",
  desc = "Per anni ho indagato sulla leggenda di quel tale, Stalvan. Quando, qualche anno fa, quei nobili in visita sono stati massacrati, sono andato a indagare con Haggard. Ho trovato queste pagine infangate, ma non siamo mai riusciti a collegare la calligrafia a quel pazzo che vive nei boschi. Gli indizi che hai seguito dimostrano che è colpevole. Porta subito questa pagina a Commander Ebonlocke e raccontale ciò che hai scoperto!",
  obj = "Porta la pagina infangata a Commander Ebonlocke.",
  progress = "Spero per te che ne valga la pena, $C. Fammi vedere cos'hai e raccontami la tua storia. Ma, per la Luce, sbrigati. La difesa di Darkshire è la mia priorità assoluta. Non ho tempo da sprecare dietro a piste che non portano da nessuna parte.",
  reward = "Caspita, ti sei $Gdimostrato:dimostrata; $Gun vero:una vera; detective, $C.",
  en_title = "The Legend of Stalvan",
  en_obj = "Take the muddy page to Commander Ebonlocke.",
}
T[80] = {
  title = "La Leggenda di Stalvan",
  desc = "Tengo d'occhio quel verme di Stalvan da parecchio tempo. Ma se questa pagina l'ha scritta la stessa mano, è colpevole al di là di ogni ragionevole dubbio.$B$BIn tutti gli anni passati a tenere il Registro Cittadino, Clerk Daltry è diventato un esperto nel riconoscere le calligrafie. Mostragli questo foglio e vedi se la scrittura corrisponde a quella della firma sul registro.",
  obj = "Mostra il Bloodstained Journal Page a Clerk Daltry.",
  progress = "Di nuovo qui, $N? Cosa mi porti stavolta?",
  reward = "Ma certo! La scrittura su questa pagina corrisponde davvero a quella delle firme del registro.",
  en_title = "The Legend of Stalvan",
  en_obj = "Show Clerk Daltry the Bloodstained Journal Page.",
}
T[81] = {
  title = "Consegna di Vino Dolce",
  desc = "Mi sono preso la briga di sistemare nel barile il vino dolce imballato di Dran, e anche le bottiglie in più che sta trafugando. Pur non tenendo Dran in grande considerazione, non c'è nulla di peggio di un vino dolce sballottato. Non c'è di che.$B$BOra, porta codesto barile a Dran Droffers, al suo emporio di recuperi a Orgrimmar. E di grazia, porgi i miei più calorosi saluti a Malton; digli che, se mai avesse sete di buone bevande e di compagni di bevute ancor migliori, saremmo onorati di riceverlo.",
  obj = "Consegna il barile a Dran Droffers a Orgrimmar.",
  progress = "Se non sei qui né per comprare né per consegnare qualcosa, mi stai solo facendo perdere tempo! Spero per te che tu abbia quel vino dolce!",
  reward = "Bene, vediamo che c'è in questo barile!$B$BSì, sì, mi pare che ci sia tutto. Ecco il compenso per il pacco, bel lavoro. Quando lo vendo alla taverna ci guadagno cinque volte tanto! Har har!$B$BQueste bottiglie in più di Hinterlands Honey Ripple le metto da parte per un'occasione speciale. Credo che ne berrò un po' insieme allo champagne. Lo chiamerò... champadolce.",
}
T[82] = {
  title = "Indagine sul Noxious Lair",
  desc = "Bene, allora, veniamo alle segnalazioni sugli insetti... Quello che sappiamo è che stanno prosciugando le pozze d'acqua che c'erano dove adesso si trova il Noxious Lair. Quello che NON sappiamo è, be', tutto il resto.$B$BPrima di tutto, scopriamo chi è il nostro nemico! Voglio che tu vada nel Noxious Lair a prendere qualche pezzo di quelle bestiole: recuperane cinque dai Centipaar e portali ad Alchemist Pestlezugg, così ci può smanettare un po'. Con lui al lavoro scopriremo cosa sono!",
  obj = "Porta cinque parti di insetto dei Centipaar da Noxious Lair ad Alchemist Pestlezugg a Gadgetzan.",
  progress = "Sei $Gl'Ispettore Apprendista:l'Ispettrice Apprendista; $N, giusto? Presto, c'è una situazione gravissima in corso! Le hai portate le parti di insetto, come aveva detto Fizzledowser?!",
  reward = "Ottimo lavoro — comincio subito ad analizzarle! Però una cosa posso dirtela già adesso... non somigliano a nessuna forma di insetto che abbia mai visto. È quasi come se li controllasse una forza esterna, o qualcosa del genere.$B$BDevi andare subito a parlare con Fizzledowser; pare ci sia un'emergenza e gli serve il tuo aiuto, di corsa! Non ne sono sicuro, ma credo che c'entrino altri insetti del deserto di Tanaris!",
}
T[90] = {
  title = "Seasoned Wolf Kabobs",
  desc = "I Seasoned Wolf Kabobs sono una specialità della casa! Certo che posso prepararne qualcuno per te, ma prima mi servono gli ingredienti: portami 10 Lean Wolf Flanks. Con tutti i lupi che ci sono qui nella foresta, sono sicuro che trovare i Costati non sarà un problema. Per tua fortuna mi è appena arrivata l'ultima spedizione di Erbe Aromatiche di Stormwind, quindi per cominciare mi mancano solo i costati.",
  obj = "Raccogli 10 Lean Wolf Flanks e torna dal Chef Grual a Darkshire.",
  progress = "Sei $Griuscito:riuscita; a recuperare i 10 Lean Wolf Flanks?",
  reward = "Ottimo lavoro, $N! E ora goditi una prelibatezza: il Seasoned Wolf Kabob!",
  en_title = "Seasoned Wolf Kabobs",
  en_obj = "Gather 10 Lean Wolf Flanks and Stormwind Seasoning Herbs and return to Chef Grual in Darkshire.",
}
T[91] = {
  title = "La Legge di Solomon",
  desc = "Un nemico di Stormwind si è stabilito sulle pendici orientali di Redridge. Questo malvagio furfante usa l'Arcano per seminare terrore e sofferenza nella nostra cittadina e tra la sua gente. Si fa chiamare Morganth e porta avanti i suoi loschi traffici.$B$BOra Morganth controlla lo Shadowhide Gnoll Clan e se ne serve per far eseguire i suoi ordini. Come stabilisce la Legge di Lakeshire, chi aiuta un criminale del Regno è punito con la pena capitale.$B$BQuesti spregevoli gnoll devono morire!$B$BConsegnami 10 Shadowhide Pendants e sarai $Gricompensato:ricompensata;.",
  obj = "Porta 10 Shadowhide Pendants a Bailiff Conacher in Lakeshire Town Hall.",
  progress = "Consegnami 10 Shadowhide Pendants e sarai $Gricompensato:ricompensata;.",
  reward = "Il Court of Lakeshire riconosce la tua dedizione alla giustizia, $N. Facendo rispettare le leggi del Regno, hai contribuito a difendere la giustizia in queste terre.",
  en_title = "Solomon's Law",
  en_obj = "Bring 10 Shadowhide Pendants to Bailiff Conacher in the Lakeshire Town Hall.",
}
T[94] = {
  title = "Un Occhio Vigile",
  desc = "Il mio rivale, Morganth, è un mago spietato e molto potente che vive nella Tower of Ilgalar, a Redridge. Ho escogitato un modo per spiarlo, l'Occhio di Azora, e ora posso osservarlo da lontano.$B$BMa per studiarne i pensieri... mi serve ancora una mano.$B$BSe sei $Gdisposto:disposta; ad aiutarmi, porta il mio Glyph of Azora alla Tower of Ilgalar e posalo sulla Statua del Leone che le sta accanto.$B$BFatto questo, il potere di Azora mi darà visioni dei piani futuri di Morganth.",
  obj = "Porta il Glyph of Azora alla Statua del Leone vicino a Tower of Ilgalar, a Redridge.",
  progress = "Questa Statua del Leone si trova qui da decenni e veglia solitaria sulla famigerata Tower of Ilgalar.$B$BAlla base c'è un incavo, dove si potrebbe incastonare una gemma o un glifo...",
  reward = "Posi il Glyph of Azora sulla pietra. Vi aderisce... e ne esce la voce disincarnata di Theocritus:$B$BTi sono grato, giovane $N. Ora potrai parlare con me attraverso il Glifo che hai posato qui, e forse avrò altri compiti per te... dopo aver sondato i pensieri del mio rivale.",
  en_title = "A Watchful Eye",
  en_obj = "Take the Glyph of Azora to the Lion Statue near the Tower of Ilgalar in Redridge.",
}
T[95] = {
  title = "La Vendetta di Sven",
  desc = "Un tempo lavoravo in una delle fattorie a sud-est... finché i Dark Riders del Deadwind Pass non sono piombati sulla mia fattoria e hanno massacrato la mia famiglia mentre ero via!$B$BAl mio ritorno ho visto una figura nell'ombra che si aggirava furtiva vicino al mio fienile e seppelliva qualcosa. Quell'individuo è fuggito prima che riuscissi a prenderlo, e non potevo fermarmi perché ero alle calcagna dei Dark Riders. Così non ho mai scoperto che cosa avesse nascosto.$B$BSe riuscissi a trovare ciò che ha sepolto quella figura nell'ombra, te ne sarei grato. Il nascondiglio è dietro il vecchio ceppo vicino al mio fienile.",
  obj = "Vai a Sven's Farm e trova ciò che è stato sepolto dietro il vecchio ceppo.",
  reward = "Qui c'è un cumulo di terra ammucchiata in fretta, come se qualcuno avesse dovuto nascondere qualcosa... senza avere molto tempo per farlo.",
  en_title = "Sven's Revenge",
  en_obj = "Go to Sven's Farm and find what was buried behind the old stump.",
}
T[96] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Prendi scheggia. Prendi scheggia e dai vita.$B$BDai vita e capisci. Capisci acqua è vita... corruzione ferma vita.$B$BTu proteggi e dai vita con potere di acqua.",
  obj = "Porta la Shard of Water a Islen Waterseer in Barrens.",
  progress = "Sei $Gtornato:tornata;. Splendido!$B$BCom'è andato il viaggio a Silverpine? Ci hai messo molto?$B$BMi è difficile capire se lì ce l'hai fatta, perché gran parte di quella terra è stata corrotta. Il suo fetore copre qualunque bene tu possa aver fatto. Ma a volte i piccoli successi contano quanto i grandi. Purificare l'acqua laggiù è stato fondamentale per te e per tutti gli sciamani.",
  reward = "Ecco la prova che ti avevo chiesto. Hai fatto un buon lavoro, $N.$B$BSono lieta di essere la prima a farti i complimenti e a darti questo... il tuo water totem.$B$BUsalo bene, e buona fortuna.$B$BPasserà del tempo prima della prossima prova, perciò impara bene le lezioni. L'acqua pura non ridà soltanto la vita a chi è ferito, ma può avere molti altri effetti. Quando avrai tempo, ti consiglio di cercare un istruttore degli sciamani. Potrebbe avere altri incantesimi da insegnarti.",
  en_title = "Call of Water",
  en_obj = "Bring the Shard of Water to Islen Waterseer in the Barrens.",
}
T[97] = {
  title = "La Leggenda di Stalvan",
  desc = "Fai sapere subito a Commander Ebonlocke che la calligrafia corrisponde, $N! I suoi sospetti erano fondati!",
  obj = "Riferisci la notizia a Commander Ebonlocke.",
  progress = "Sì, $N?",
  reward = "Lo sapevo! Ottimo lavoro, $N.",
  en_title = "The Legend of Stalvan",
  en_obj = "Report the news to Commander Ebonlocke.",
}
T[98] = {
  title = "La Leggenda di Stalvan",
  desc = "Stalvan Mistmantle ha condotto una vita depravata. Vittime innocenti sono morte per mano sua, ed è senza dubbio colpevole di innumerevoli crimini. Ora quel folle minaccia Darkshire. Solo la Luce sa quali turpi azioni stia tramando. $C, raggiungi la sua casetta appena a nord del paese e giustizia Stalvan una volta per tutte.$B$BQuando avrai finito, va' a mostrare il suo anello di famiglia a Madame Eva. Dopotutto, è stata la sua premonizione a portarci a questa macabra scoperta. Ma è grazie a lei se ora Darkshire è più sicura.",
  obj = "Uccidi Stalvan Mistmantle e mostra il suo anello di famiglia a Madame Eva.",
  progress = "Sì, $N?",
  reward = "Lo so, $N: Stalvan è morto. Ho sentito un'ondata di speranza attraversare la foresta corrotta. La sua sete di sangue non affliggerà mai più Duskwood. Ma la mia gioia è offuscata dal pensiero di quanti sono caduti preda di quell'orribile belva. Ciononostante, sei $Gun:una; $C $Gcoraggioso e astuto:coraggiosa e astuta;.",
  en_title = "The Legend of Stalvan",
  en_obj = "Kill Stalvan Mistmantle and show Madame Eva his family ring.",
}
T[100] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Quando finisci la formula, la luce esplode. Il suono delle gocce d'acqua che colpiscono la fiamma si è spento e, mentre gli spiriti corrotti intorno a te vengono distrutti, ne hai i sensi sopraffatti.",
  obj = "Parla con la Minor Manifestation of Water nella Silverpine Forest.",
  reward = "Grazie a te. Grazie agli sciamani.$B$BCorruzione si ritira, ma vita continua ad affievolirsi. Tocca a sciamani proteggere vita.",
  en_title = "Call of Water",
  en_obj = "Speak to the Minor Manifestation of Water in Silverpine Forest.",
}
T[101] = {
  title = "Il Totem of Infliction",
  desc = "Ora che la corruzione mistica si insinua nella foresta, non si può negare che serva proteggersi, $N. I venti mi sussurrano di un grande pericolo che ti aspetta, paziente, in un futuro vicino.$B$BSe vuoi proteggerti, nobile $C, portami 10 ghoul fangs, 10 skeleton fingers e 5 vials of spider venom. Per te incanterò un Totem of Infliction che ferirà chiunque provi a farti violenza.",
  obj = "Porta 10 Ghoul Fangs, 10 Skeleton Fingers e 5 Vials of Spider Venom a Madame Eva a Darkshire.",
  progress = "Portami 10 ghoul fangs, 10 skeleton fingers e 5 vials of spider venom. Per te incanterò un Totem of Infliction che ferirà chiunque provi a farti violenza.",
  reward = "Hai scelto con saggezza, $N. Questo Totem of Infliction ti aiuterà a difenderti dal male che si annida in tutta Azeroth e oltre. Quando ti sentirai $Gminacciato:minacciata;, stringi questo totem e lascia che la sua aura magica ti conforti. Sii $Gcoraggioso:coraggiosa;, $Gbel:bella; $C. Ti servirà tutto il coraggio che riuscirai a trovare, perché nel tuo futuro vedo scorrere molto sangue.",
  en_title = "The Totem of Infliction",
  en_obj = "Bring 10 Ghoul Fangs, 10 Skeleton Fingers and 5 Vials of Spider Venom to Madame Eva in Darkshire.",
}
T[105] = {
  title = "Ahimè, Andorhal",
  desc = "Ahimè, è giunta l'ora di attaccare Andorhal e di cacciare il lich che la tiene in pugno!$B$BIl lich — Araj the Summoner — regna fra le rovine della città. A proteggerlo ci sono molti membri dello Scourge, schierati intorno a quel che resta del centro, e accanto a sé tiene sempre una scorta di guardiani formidabile. Per avere anche solo qualche speranza di batterlo ti serviranno molti alleati.$B$BDistruggi Araj, $N, e come prova portami una scheggia del suo filatterio!",
  obj = "Porta l'Araj's Phylactery Shard a High Executor Derrington al Bulwark, Western Plaguelands.",
  progress = "Sai qual è il tuo compito, $N. Hai una scheggia del filatterio del lich, a prova che l'hai portato a termine?",
  reward = "Ce l'hai fatta! Araj... il lich è finalmente sconfitto!$B$BOggi hai reso all'Orda un servizio enorme, $N. Con il tuo coraggio e la tua perseveranza hai mostrato cosa vuol dire essere $Gun vero eroe:una vera eroina;. Ti prego — accetta questo come segno, perché tutti vedano e sappiano che hai dato all'Orda una vittoria che si ricorderà nei secoli!",
}
T[110] = {
  title = "Analisi delle Parti di Insetto",
  desc = "Mi prenderò un po' di tempo per esaminare l'attrezzatura topografica di Scrimshank... e per mettere in ordine i suoi effetti personali. Me lo sento dietro le orecchie: questa non sarà l'ultima perdita che ci costeranno questi insetti.$B$BVorrei che passassi da Alchemist Pestlezugg a vedere se è riuscito ad analizzare le parti di insetto che gli abbiamo mandato. Se sono pronte, portamele.",
  obj = "Recati da Alchemist Pestlezugg a Gadgetzan per la sua analisi delle parti di insetto.",
  reward = "Sì, i risultati ce li ho proprio qui. E sono... inquietanti, a dir poco.$B$BCrediamo che il primo sospetto fosse giusto: gli insetti sono controllati da una forza esterna. E se è così, abbiamo a che fare con qualcosa di sconosciuto, non solo molto potente ma anche maligno. Questi insetti sono stati trasformati in puri devastatori. Una cosa del genere non l'ho mai vista.",
}
T[111] = {
  title = "Parla con la Nonna",
  desc = "Ti prego, $N, parla con mia nonna. Se c'è qualcuno che può trovare il modo di farmi stare con Maybell, è lei.$B$BÈ a casa nostra, a est di qui.",
  obj = "Parla con Gramma Stonefield.",
  progress = "Non vedo l'ora di sapere come reagiranno i miei amici!$B$BNon se lo aspetteranno mai!",
  reward = "Finché le nostre famiglie si fanno la guerra, Tommy Joe e Maybell non potranno avere un futuro, ma... forse possiamo farli stare insieme almeno per un po'.$B$BMmh, cosa possiamo fare...",
}
T[113] = {
  title = "Analisi delle Parti di Insetto",
  desc = "Questo rapporto Senior Surveyor Fizzledowser deve vederlo subito. Anzi... deve vederlo chiunque sappia leggere. Abbiamo davanti una minaccia grave e seria, e non solo per Tanaris e Gadgetzan: se nessuno la ferma, per tutto il sud di Kalimdor. Accidenti, forse perfino per tutta Azeroth; finora questa cosa non ha dato nessun segno di volersi placare.$B$BFatti preparare da Fizzledowser una copia del rapporto, da far girare liberamente nella tua fazione. Tutti devono sapere di questa minaccia!",
  obj = "Consegna il rapporto a Senior Surveyor Fizzledowser a Gadgetzan. Assicurati che ti dia una copia del rapporto, come ha chiesto Alchemist Pestlezugg.",
  progress = "Allora, $GTopografo:Topografa; Junior $N, il vecchio Pestlezugg ce l'ha pronto, quel rapporto?",
  reward = "Grazie di avermi portato il rapporto, $GTopografo:Topografa; Junior $N; ecco la paga per il tuo diligente servizio alla Gadgetzan Water Company.$B$BDi solito non mi entusiasma dare le nostre preziose informazioni, carte blanche, a gente che altrimenti pagherebbe bei soldi per averle, ma ormai conosco Pestlezugg da parecchi anni. Se lui consiglia di farlo sapere a tutti, così sia. Dammi un momento e ti preparo una copia.",
}
T[115] = {
  title = "Magia delle Ombre",
  desc = "Gli orchi Blackrock hanno arruolato dei maghi d'ombra per sostenere i loro attacchi a Redridge, e hanno portato con sé strumenti di potere oscuro — i midnight orbs. I globi hanno inferto colpi pesanti ai difensori di Redridge, ed è indispensabile togliere dal campo di battaglia questi oggetti contaminati dai demoni.$B$BTrova i midnight orbs sui Blackrock shadowcasters uccisi e portameli. Poi li farò eliminare, perché il mondo starebbe meglio senza di loro!",
  obj = "Porta 3 Midnight Orbs a Marshal Marris a Lakeshire.",
  progress = "Come va la lotta contro i maghi d'ombra? Hai trovato i midnight orbs?",
  reward = "Grazie, $N. Li farò distruggere immediatamente.",
  en_title = "Shadow Magic",
  en_obj = "Bring 3 Midnight Orbs to Marshal Marris in Lakeshire.",
}
T[126] = {
  title = "Ululati sulle Colline",
  desc = "$N, gli gnoll sono ancora là fuori. Li sento latrare mentre cacciano sulle colline sopra Lakeshire. E un grido sovrasta tutti gli altri — quello di Yowler, il loro capobranco.$B$BUccidi Yowler e disperdi il branco! Portami la sua zampa come prova.$B$BE fai attenzione, non per niente questo gnoll è il loro capo. Non è un Bastardo qualunque...",
  obj = "Porta Yowler's Paw a Verner Osgood a Lakeshire.",
  progress = "Yowler è una creatura pericolosa, $N. Se non sei $Gpronto:pronta; ad affrontarlo, ti capisco.",
  reward = "Grazie ancora per l'aiuto. L'esercito di Stormwind è così impegnato con gli orchi che non ha truppe da mandare a difendere Redridge da minacce locali come gli gnoll.",
  en_title = "Howling in the Hills",
  en_obj = "Bring Yowler's Paw to Verner Osgood in Lakeshire.",
}
T[127] = {
  title = "Vendita di Pesce",
  desc = "Il Lake Everstill è famoso per lo spotted sunfish. C'è sempre richiesta... e io sono quasi a secco!$B$BPortamene una partita di 10 e te la pagherò bene. Se non sai pescare, allora... magari puoi prenderli ai murlocs!",
  obj = "Porta 10 Spotted Sunfish a Dockmaster Baren a Lakeshire.",
  progress = "Hai del pesce mola per me, eh?",
  reward = "È stato un piacere fare affari con te, compare!",
  en_title = "Selling Fish",
  en_obj = "Bring 10 Spotted Sunfish to Dockmaster Baren in Lakeshire.",
}
T[128] = {
  title = "Taglia sui Blackrock",
  desc = "Il Blackrock Clan va distrutto. Il Nemico ha invaso le nostre terre. Queste montagne rientrano nei domini sovrani del Re di Stormwind. Secondo le nostre fonti, i capi di ogni unità del Clan si chiamano Campioni. Li troverai nel loro accampamento a nord, appena a ovest della strada per le Burning Steppes.$B$BMagistrate Solomon vuole la morte di questi bruti ripugnanti. Uccidi 15 Blackrock Champions e torna da me.",
  obj = "Uccidi 15 Blackrock Champions e Guard Howe a Lakeshire ti ricompenserà.",
  progress = "Torna quando avrai ucciso 15 Blackrock Champions.",
  reward = "Vedo che hai combattuto con valore contro il Blackrock Clan, $C. Hai reso davvero un grande servizio alla nostra cittadina.",
  en_title = "Blackrock Bounty",
  en_obj = "Kill 15 Blackrock Champions and Guard Howe in Lakeshire will reward you.",
}
T[133] = {
  title = "Effigie Macabra",
  desc = "Vivo così lontano dalla protezione del paese che è un miracolo se i ghoul e i morti che camminano non mi hanno ancora mangiato! Anzi, proprio ieri un branco di Bone Chewers picchiava contro le pareti di casa mia!$B$BVoglio costruire un'effigie — una specie di \"spaventapasseri\" per i Ghoul. Per farla mi servono delle Ghoul Ribs. Puoi prenderle dai Flesh Eaters, dai Bone Chewers, dai Brain Eaters, dai Rotted Ones e dai Plague Spreaders.$B$BProcurami le costole e ti ripagherò con qualche moneta.",
  obj = "Raccogli 7 Ghoul Ribs e portale ad Abercrombie, nella sua baracca.",
  progress = "Mi pare di sentire un branco di Ghoul dietro casa — farei meglio a piazzare in fretta quell'effigie! Mi hai portato le Ghoul Ribs?",
  reward = "Ah, grazie. Queste fanno proprio al caso mio!",
  en_title = "Ghoulish Effigy",
  en_obj = "Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack.",
}
T[134] = {
  title = "Ladri Ogre",
  desc = "Qualche settimana fa stavo raccogliendo erbe lontano da casa, quando una banda di ogre mi ha attaccato! Sono scappato, e ho dovuto lasciare lì una cassa di attrezzi ed erbe preziose.$B$BDopo avermi messo in fuga, gli ogre sono tornati tutti tronfi al tumulo degli ogre, nel sud di Duskwood. Sono sicuro che la cassa è da qualche parte vicino al tumulo.$B$BTi prego, $N, recuperami quella cassa: mi manca tantissimo.",
  obj = "Riporta l'Abercrombie's Crate ad Abercrombie.",
  progress = "Hai la mia cassa? Se ce l'hai, allora ti prego... dammela, presto!",
  reward = "Sia ringraziato il Nec-...cioè, grazie a TE, $N! Ti sei più che meritato la ricompensa.$B$BAha! Felice! Mi aspettano notti felici!!",
  en_title = "Ogre Thieves",
  en_obj = "Return Abercrombie's Crate to Abercrombie.",
}
T[148] = {
  title = "Provviste da Darkshire",
  desc = "Oh, cosa può fare un povero vecchio? Mi servono delle provviste da Darkshire, ma il villaggio è così lontano e io sono così vecchio e debole... non ce la farei mai ad arrivarci.$B$BPotresti andare a Darkshire e portarmi del Ghost Hair Thread? Puoi fartelo dare da Madame Eva, nella sua casa sulla piazza di Darkshire.",
  obj = "Parla con Madame Eva.",
  reward = "Ah, quindi ti serve del Ghost Hair Thread? Purtroppo non ne ho più, ma posso fartene un po'... se mi procuri i capelli di fantasma.",
  en_title = "Supplies from Darkshire",
  en_obj = "Speak with Madame Eva.",
}
T[149] = {
  title = "Ghost Hair Thread",
  desc = "C'è un povero spirito infelice, Blind Mary, che infesta una vecchia fattoria sulle colline a sud di Darkshire.$B$BEcco, prendi questo Spectral Comb e chiedi a Blind Mary di pettinarsi. Poi riportami il pettine e ne ricaverò i Capelli Spettrali che mi servono per il filo.$B$BE fai attenzione, perché ora vicino a quella casa si aggirano creature oscure...",
  obj = "Porta lo Spectral Comb a Blind Mary.",
  progress = "<Singhiozza> Oh, ti prego, non guardarmi! Mi sono strappata gli occhi con le mie stesse mani, ma percepisco ancora il tuo sguardo!$B$BSono orribile! Orribile! Ti prego, guarda altrove!!",
  reward = "Cos'è questo? Un pettine? Che bello! Scivola tra i capelli come se non fossero l'orribile groviglio smorto che sono.$B$BOh, se solo avessi uno specchio...",
  en_title = "Ghost Hair Thread",
  en_obj = "Bring the Spectral Comb to Blind Mary.",
}
T[154] = {
  title = "Riporta il Pettine",
  desc = "NO!!!!!$B$BPrendilo, portami via questo pettine!$B$BSono un mostro, e nessuno mi troverà mai più bella!",
  obj = "Riporta il Ghost Hair Comb a Madame Eva a Darkshire.",
  progress = "Sento che hai visto Blind Mary. Hai il mio Pettine...?",
  reward = "Con questo posso fare un rocchetto di Ghost Hair Thread, e mi avanzerà anche qualche capello. Ecco qualche moneta per i capelli in più.",
  en_title = "Return the Comb",
  en_obj = "Return the Ghost Hair Comb to Madame Eva in Darkshire.",
}
T[156] = {
  title = "Raccogli Rot Blossoms",
  desc = "Se mi porti un po' di Rot Blossoms, posso prepararti un po' di Distillato di Zombi.$B$BI Rot Blossoms crescono in posti alquanto insoliti. In particolare, ho sentito dire che si trovano dentro i crani degli Skeletal Horrors e degli Skeletal Fiends... non che io mi sia mai avvicinato abbastanza da guardare!$B$BIl Raven Hill Cemetery e i Tranquil Gardens brulicano di quegli scheletri. Già che cerchi i Rot Blossoms, potresti anche sbarazzartene. La città di Darkshire te ne sarebbe grata.",
  obj = "Raccogli 8 Rot Blossoms e portali a Tavernkeep Smitts a Darkshire.",
  progress = "Ciao, $N. Hai già i Rot Blossoms per me?",
  reward = "Bene, hai preso i Rot Blossoms. E dirò ad Althea Ebonlocke dei Night Watch che hai fatto fuori un po' di scheletri.$B$BProteggere la gente di Darkshire è un fardello tetro per i Night Watch, ed è davvero una bella notizia che anche altri aiutino ad arginare l'ondata di mostri a Duskwood.",
  en_title = "Gather Rot Blossoms",
  en_obj = "Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire.",
}
T[157] = {
  title = "Consegna il Filo",
  desc = "Ecco il tuo filo, $N. Ha mille usi, dall'imprigionare gli spiriti maligni all'infondere vita negli oggetti inanimati.",
  obj = "Porta il Ghost Hair Thread ad Abercrombie, nella sua baracca a nord di Raven Hill Cemetery.",
  progress = "Devo tendere il Ghost Hair Thread davanti alla porta e alle finestre per tenere lontani gli spiriti indesiderati. Me l'hai portato?",
  reward = "Magnifico! Andrà benissimo...$B$BEcco, $Gmio buon:mia buona; $N, prendi questo come compenso per la tua nobile azione.",
  en_title = "Deliver the Thread",
  en_obj = "Bring the Ghost Hair Thread to Abercrombie, in his shack north of the Raven Hill Cemetery.",
}
T[158] = {
  title = "Distillato di Zombi",
  desc = "Mi serve una bottiglia di liquore — il Distillato di Zombi. Tavernkeep Smitts alla Scarlet Raven Tavern di Darkshire dovrebbe averne.$B$BSbrigai, ti prego, $N. Le notti si fanno sempre più fredde, e mi serve quel liquore per scaldarmi il sangue!",
  obj = "Parla con Tavernkeep Smitts.",
  reward = "Ti serve del Distillato di Zombi, eh? Mmm... è roba forte — di solito nessuno me lo chiede.",
  en_title = "Zombie Juice",
  en_obj = "Speak with Tavernkeep Smitts.",
}
T[159] = {
  title = "Consegna il Distillato",
  desc = "Ecco il tuo Distillato di Zombi...$B$B...e fai attenzione a questa roba. È così forte che farebbe risorgere i morti!",
  obj = "Porta il Distillato di Zombi ad Abercrombie, nella sua baracca.",
  progress = "Mi serve quel Distillato di Zombi per scaldarmi in queste notti fredde e buie. Me l'hai portato?",
  reward = "Mille grazie, $N. Riscaldi il cuore di un vecchio con la tua stoltez-...volevo dire...con la tua gentilezza!$B$BEcco a te, $Gamico:amica;. Prendilo come segno della mia gratitudine.",
  en_title = "Juice Delivery",
  en_obj = "Bring the Zombie Juice to Abercrombie at his shack.",
}
T[160] = {
  title = "Biglietto per il Sindaco",
  desc = "Porta questo biglietto a Ello Ebonlocke, il Sindaco di Darkshire.$B$BIo e lui siamo vecchi amici... e quando lo leggerà e scoprirà cosa hai fatto per me... sono sicuro che sarà felice quanto me! Ahahahah!",
  obj = "Porta la Letter to Ello Ebonlocke, Sindaco di Darkshire, da parte di Abercrombie.",
  progress = "Abercrombie...? Non conosco nessuno con quel nome. Dici di avere una lettera da parte di questo tizio, Abercrombie?$B$BBe', allora fammela vedere...",
  reward = "<Ello guarda la lettera...>$B$BChe lingua è questa? Sembra antica... non riesco a leggerla.",
  en_title = "Note to the Mayor",
  en_obj = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.",
}
T[162] = {
  title = "L'Ascesa dei Silithid",
  desc = "Questo rapporto ti raccomando di portarlo a qualcuno che se ne intende di queste cose.$B$BConosco una studiosa elfa della notte, si chiama Gracina Spiritmight. Ha passato molto tempo a studiare le forme di vita che esistono solo nell'ecologia di Azeroth; e per giunta è una storica! Se ti serve qualcuno che ti aiuti a capire cos'è esattamente questa minaccia e, soprattutto, come fermarla, il rapporto dallo a lei. Ci servirà aiuto.$B$BPer quel che ne so, vive nel Tempio della Luna, a Darnassus.",
  obj = "Porta l'Insect Analysis Report a Gracina Spiritmight a Darnassus.",
  progress = "Pace e tranquillità siano con te, $Gstraniero:straniera;. Per quale motivo mi hai cercata, oggi?",
  reward = "Questo rapporto... il terrore di cui parla, noi elfi della notte lo conosciamo. Fizzledowser è stato saggio a mandarmi questo rapporto, e anche te.$B$BQueste creature non ci metteranno molto a divorare il deserto di Tanaris; sono una delle minacce più grandi che tutti noi ci troveremo mai ad affrontare. Imparalo bene, questo nome, $N: silithid. Gli insetti di cui parla il rapporto sono i silithid, gli strumenti di uno dei pericoli più gravi che incombono sia sull'Orda sia sull'Alleanza.$B$BSe solo fossimo stati abbastanza intelligenti da capirlo prima.",
}
T[164] = {
  title = "Consegne per Sven",
  desc = "Conosci Sven? Lui sì che compie l'opera della Luce! Lui e i suoi seguaci si sono accampati al margine nord-occidentale di Duskwood.$B$BPurtroppo sono così pochi che non possono neanche mandare un uomo in città a prendere le provviste. Gliele porteresti tu?",
  obj = "Consegna le provviste a Sven.",
  progress = "Sembri $Grobusto:robusta;, $C. Sei $Gvenuto:venuta; per unirti alla nostra lotta?",
  reward = "Queste provviste ci saranno utilissime. L'aiuto della famiglia Carevin è sempre ben accetto. Eccoti una piccola ricompensa per il disturbo.",
  en_title = "Deliveries to Sven",
  en_obj = "Deliver the supplies to Sven.",
}
T[165] = {
  title = "L'Eremita",
  desc = "Un vecchio veniva piuttosto spesso in città a comprare provviste, ma è da un bel po' che non lo vedo. Se ricordo bene, vive in una baracca che dà sul cimitero di Raven Hill. Forse dovresti andare a controllare se c'è qualcosa che non va.",
  obj = "Va' a controllare il vecchio nella baracca vicino al cimitero di Raven Hill.",
  reward = "Elaine Carevin? Ehehe, oh sì... certo, i Carevins.$B$BNo, va tutto bene, è solo che ormai andare in città per me è dura. Le strade sono pericolose e non sono più giovane. Faresti qualche favore a un vecchio?",
  en_title = "The Hermit",
  en_obj = "Check on the old man in the shack near Raven Hill cemetery.",
}
T[166] = {
  title = "La Defias Brotherhood",
  desc = "Ti resta da portare a termine un compito solo: Edwin VanCleef va assassinato. Mi addolora condannare a morte un uomo, ma per il bene della gente di Westfall VanCleef deve riposare in pace una volta per tutte. Quando avrai finito, portami la testa di quel criminale.",
  obj = "Uccidi Edwin VanCleef e porta la sua testa a Gryan Stoutmantle.",
  progress = "A che punto è la caccia a Edwin VanCleef?",
  reward = "$N, hai un coraggio straordinario. The People's Militia ti ringrazia per il servizio che hai reso alla gente di Westfall. Con la morte di VanCleef per la Defias Brotherhood comincia la fine. Spero che presto la pace torni a benedire le pianure di questa bella terra.$B$BOnore a te, $GSignore:Signora;!",
  en_title = "The Defias Brotherhood",
  en_obj = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.",
}
T[167] = {
  title = "Oh, Fratello...",
  desc = "Eravamo giù in fondo a una grande miniera a Westfall, nascosta sotto un fienile a Moonbrook. Da dove siano spuntati questi ladri puzzolenti, non ne ho idea. Fatto sta che la galleria ci è crollata addosso. Io ne sono uscito, ma gli altri... be'... degli altri non si è più saputo niente.$B$BHai l'aria di chi là dentro potrebbe avere più fortuna. Se andassi a cercare mio fratello, te ne sarei grato. Portava sempre con sé il Distintivo dell'Explorers' League. E se lui non riesci a trovarlo, almeno quel distintivo mi metterebbe un po' il cuore in pace.",
  obj = "Porta il Distintivo di Explorers' League di Foreman Thistlenettle a Wilder Thistlenettle a Stormwind.",
  progress = "Hai trovato qualche traccia di mio fratello? Dopo tutto questo tempo, c'è ancora speranza?",
  reward = "Allora i miei sospetti erano giusti. Povero fratello mio.... Be', grazie per aver dato una risposta a questo mistero, anche se è una risposta cupa.",
  en_title = "Oh Brother. . .",
  en_obj = "Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.",
}
T[168] = {
  title = "Raccogliere Ricordi",
  desc = "Quel giorno orribile, quando la galleria è crollata, sono morti molti miei amici. Se le tue avventure ti portano in quell'ala della miniera a Moonbrook, ti prego, cerca qualcosa che permetta di riconoscerli. Se trovi qualcuno dei loro Miners' Union Cards, riportameli: farò in modo che le famiglie abbiano qualche risposta su questo terribile incidente.",
  obj = "Recupera 4 Miners' Union Cards e riportali a Wilder Thistlenettle a Stormwind.",
  progress = "Sei $Griuscito:riuscita; a ritrovare qualcuno dei Miners' Union Cards dei miei vecchi colleghi?",
  reward = "Grazie per averli raccolti, $N. Con la tua fatica, dopo questa tragedia, i morti potranno trovare pace. Penserò io ad avvisare le famiglie.",
  en_title = "Collecting Memories",
  en_obj = "Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.",
}
T[169] = {
  title = "Wanted: Gath'Ilzogg",
  desc = "Ricercato! Gath'Ilzogg, Capo degli attacchi dei Blackrock allo Stonewatch Keep e delle incursioni contro il comune di Lakeshire.$B$BGath'Ilzogg è estremamente pericoloso. Si dice che sia rintanato nel mastio da poco conquistato e che lì trami nuovi crimini del clan Blackrock contro l'umanità. L'infestazione degli orchi va repressa a ogni costo. Una generosa ricompensa attende qualunque anima coraggiosa riesca a consegnare la testa di Gath'Ilzogg a Magistrate Solomon.",
  obj = "Uccidi Gath'Ilzogg e porta la sua testa a Magistrate Solomon a Lakeshire per la ricompensa.",
  progress = "Cos'hai lì, $R?",
  reward = "Lavoro fantastico, $N! Era Gath'Ilzogg a guidare quei bruti in battaglia, e ha ucciso molti umani innocenti. Giustizia è fatta. Ed è il primo passo per restituire il mastio al regno di Stormwind!",
  en_title = "Wanted: Gath'Ilzogg",
  en_obj = "Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward.",
}
T[171] = {
  title = "Un Protettore dell'Alleanza",
  desc = "Sei $Gstato:stata; così gentile con me, $N. Non pensavo proprio che mi sarei divertito tanto durante la Settimana dei Bambini. Grazie. Non voglio essere triste per quello che mi è successo e tutto il resto — i miei mi ripetevano sempre che qualsiasi cosa brutta capiti bisogna superarla a testa alta. Sai, da grande voglio diventare un eroe... proprio come te.$B$BMi dispiace dirlo, ma è ora di tornare a casa. Torniamo indietro, così racconto alla matrona che persona fantastica sei!",
  obj = "Riporta il tuo protetto all'orfanotrofio di Stormwind consegnando l'Human Orphan Whistle a Orphan Matron Nightingale nel Cathedral District.",
  progress = "Che piacere rivederti, $N. Hai portato a termine i compiti che ti eri $Gofferto:offerta; di svolgere durante la Settimana dei Bambini?",
  reward = "Che i cieli ti benedicano, $N. Per Randis hai fatto più di quanto alla maggior parte della gente verrebbe mai in mente di fare per lui. Grazie — sei una stella splendente nei cieli dell'Alleanza.$B$BTi prego — se ti avanza un po' di tempo, torna a trovarci. So che a Randis farebbe piacere, e a me pure.$B$BCon te Randis si è divertito tantissimo, $N, e voleva regalarti uno dei suoi animali preferiti, perché ti ricordassi di lui.",
  en_title = "A Warden of the Alliance",
  en_obj = "Return your ward to the Stormwind orphanage by handing in the Human Orphan Whistle to Orphan Matron Nightingale in the Cathedral District.",
}
T[172] = {
  title = "Settimana dei Bambini",
  desc = "Vuoi darci una mano qui all'orfanotrofio? Che tu sia $Gbenedetto:benedetta;, $Gamico:amica;; durante la Settimana dei Bambini il tuo aiuto sarà prezioso.$B$BPrendi questo fischietto. Potrai usarlo solo per poco — di solito non oltre la Settimana dei Bambini. Quando lo usi, potrai parlare con il bambino di cui hai accettato di occuparti. Se lo usi un'altra volta, lo congederai.$B$BSu, $N — usa il fischietto e va' a conoscere il tuo protetto! Sono sicura che non vede l'ora di incontrarti.",
  obj = "Usa l'Orcish Orphan Whistle per parlare con il bambino di cui ti occuperai durante la Settimana dei Bambini.",
  reward = "Zug zug! Io sono Grunth. Sei tu che ti occupi di me, immagino? Sei $Gun avventuriero:un'avventuriera;, come la mia mamma e il mio papà. La matrona dice che sono morti in battaglia, con onore. Sono felice di conoscerti.$B$BSpero che faremo un sacco di cose insieme. Ce ne sono alcune che vorrei fare, e la matrona dice che questa settimana sarai come $Gun fratellone:una sorellona; per me. Mi piacerebbe tantissimo.",
  en_title = "Children's Week",
  en_obj = "Use the Orcish Orphan Whistle to talk with the child you will be looking after during Children's Week.",
}
T[173] = {
  title = "Worgen nei Boschi",
  desc = "Sembra che l'oscurità venga attirata inesorabilmente verso Duskwood. Master Carevin ha una missione: scacciare il male e l'eresia. Se la gente di Darkshire resta al sicuro, è grazie ai nostri sforzi.$B$BCredi di essere $Gdegno:degna; di unirti a noi?$B$BUn tempo anch'io la pensavo come te. La Guardia mi aveva deluso con la sua indolenza, e così mi sono unito a Master Carevin. Ma se vuoi dimostrare quanto vali, non ci riuscirai a parole.$B$BMettiti alla prova contro i Nightbane Shadow Weaver worgen nel Brightwood Grove — luminoso, ah! — e nel Rotting Orchard.",
  obj = "Uccidi 6 Nightbane Shadow Weaver worgen per Calor a Darkshire.",
  progress = "$N, come va la caccia?",
  reward = "Notevole, $N. A quanto pare sai cavartela. Forse si potrebbe trovare una sfida più adatta a una persona capace come te.$B$BPerò è strano... I worgen sembrano spuntati dal nulla. D'altra parte, con tutte le altre strane creature che hanno passato i nostri confini, immagino che siano solo una preoccupazione fra tante.",
  en_title = "Worgen in the Woods",
  en_obj = "Kill 6 Nightbane Shadow Weaver worgen for Calor in Darkshire.",
}
T[174] = {
  title = "Guarda le Stelle",
  desc = "Il mio amico Gnomo, Cog, ha promesso di darmi una mano a costruire un congegno con cui potrò scrutare le stelle. Oltre la magia esiste una verità che può spiegare la strana trasformazione nella foresta.$B$BSecondo il progetto di Cog, il primo passo è un bronze tube fatto da un ingegnere esperto: portamene uno.",
  obj = "Viktori Prism'Antras of Darkshire vuole che tu gli porti un bronze tube.",
  progress = "Hai già trovato un ingegnere esperto che ti costruisca un bronze tube?",
  reward = "Perfetto, $N. Il primo passo è fatto!",
  en_title = "Look To The Stars",
  en_obj = "Viktori Prism'Antras of Darkshire wants you to bring him a bronze tube.",
}
T[175] = {
  title = "Guarda le Stelle",
  desc = "Il progetto di Cog dice che adesso mi serve un modo per riflettere la luce. Mi ricordo di una donna, una certa Mary, che da queste parti era diventata famosa perché si portava sempre dietro uno specchio. Potresti rintracciare Mary e chiederle se ci presta una superficie riflettente per il progetto? Credo che un tempo abitasse nel sud di Duskwood...",
  obj = "Trova Mary e convincila a cedere una superficie riflettente per il progetto di Viktori.",
  reward = "Ma certo, uno specchio un tempo ce l'avevo.",
  en_title = "Look To The Stars",
  en_obj = "Locate Mary and persuade her to give up a reflective surface for Viktori's project.",
}
T[177] = {
  title = "Guarda le Stelle",
  desc = "Lo specchio era fra i miei tesori più belli, fino a... l'incidente. Dopo quello che è successo l'ho buttato dietro il fienile. Là dietro si aggirava un Insane Ghoul: forse l'ha raccolto lui. Dicono che quella bestia diabolica viva nel Tranquil Gardens Cemetery.",
  obj = "Recupera dall'Insane Ghoul il Mary's Looking Glass della Cieca e consegnalo a Viktori a Darkshire.",
  progress = "Ho fatto vedere a Cog i primi pezzi della nostra macchina per osservare le stelle, e ne è rimasto colpito. Hai trovato un oggetto riflettente, per caso?",
  reward = "Magnifico! Funzionerà alla perfezione. Grazie mille!",
  en_title = "Look To The Stars",
  en_obj = "Retrieve Blind Mary's Looking Glass from the Insane Ghoul and give it to Viktori in Darkshire.",
}
T[178] = {
  title = "Il Recupero di Theocritus",
  desc = "<Senti una voce che sembra venire dal nulla...>$B$BNon allarmarti. Sono Theocritus, Alto Mago della Tower Azora, nell'Elwynn Forest. Con il pendente che hai in mano, gli Shadowhide Gnolls e il loro padrone, Morganth, comunicano fra loro.$B$BDopo mesi di ricerche, credo di poter comunicare anch'io attraverso questi pendenti. Se senti questo messaggio, vuol dire che il mio incantesimo ha funzionato.$B$BPortami questo pendente, e ti ricompenserò per il servizio.",
  obj = "Porta il Faded Shadowhide Pendant a Theocritus the Mage.",
  progress = "Dici che ti ho parlato attraverso un pendente? Hmm... dammelo, così posso studiarlo.",
  reward = "Ti sono grato, $N. Settimane fa ho mandato quel messaggio agli Shadowhide Pendants, e pensavo che non fosse andato a buon fine. Invece pare che l'incantesimo sia arrivato almeno ad alcuni pendenti, anche se con parecchio ritardo.$B$BCol tempo spero di imparare a lanciare un attacco attraverso i pendenti, così da immobilizzare tutti gli Shadowhide Gnolls che li portano.$B$BMa per riuscirci, temo che serviranno ancora molte ricerche.",
  en_title = "Theocritus' Retrieval",
  en_obj = "Bring the Faded Shadowhide Pendant to Theocritus the Mage.",
}
T[180] = {
  title = "Wanted: Lieutenant Fangore",
  desc = "Wanted: Lieutenant Fangore$B$BNoto capo dello Shadowhide Gnoll Clan, al servizio di Morganth, nemico del Comune e del Regno. Magistrate Solomon ordina la morte di questo vile traditore di Stormwind. Mostra la sua zampa al Magistrato come prova che è morto.",
  obj = "Uccidi Lieutenant Fangore e torna da Magistrate Solomon a Lakeshire con la sua zampa.",
  progress = "Che notizie porti alla Corte?",
  reward = "Allora il malvagio Lieutenant Fangore è morto? Bene, ci siamo tolti di torno quella lurida creatura. Sei molto $Gcoraggioso:coraggiosa;, $C. Il Township of Lakeshire ti ringrazia per l'aiuto.",
  en_title = "Wanted: Lieutenant Fangore",
  en_obj = "Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw.",
}
T[181] = {
  title = "Guarda le Stelle",
  desc = "Per completare il congegno manca solo un ultimo pezzo: il progetto di Cog richiede una lente, di qualche tipo. L'unica abbastanza grande che io conosca sarà molto difficile da procurare.$B$BNel tumulo nel sud di Duskwood vive un ogre di nome Zzarc'Vul. Se ci riesci, portami il suo monocolo e lo userò come lente!",
  obj = "Trova Zzarc'Vul nel tumulo degli ogre a sud, in Duskwood, e porta il suo monocolo a Viktori a Darkshire.",
  progress = "Sei $Griuscito:riuscita; a convincere Zzarc'Vul a prestarci il monocolo per l'esperimento?",
  reward = "Finalmente! Il congegno per osservare le stelle è completo! Grazie, $N. Ora posso andare avanti con le mie ricerche...",
  en_title = "Look To The Stars",
  en_obj = "Locate Zzarc'Vul in the southern ogre mound in Duskwood and return his monocle to Viktori in Darkshire.",
}
T[185] = {
  title = "Maestria nella Caccia alla Tigre",
  desc = "Ero solo una ragazzina quando mio padre mi ha addestrata nell'arte della caccia alla tigre.$B$BI felini giovani, vedrai, sono molto più facili da seguire e da uccidere, quindi cominceremo con calma. Le tigri giovani si trovano spesso vicino al campo della spedizione.$B$BMetti alla prova la tua abilità nel seguire le tracce e vedi se riesci a stanare qualcuna di queste bestie.",
  obj = "Ajeck Rouack della Nesingwary's Expedition vuole che tu uccida 10 Young Stranglethorn Tigers.",
  progress = "Prima devi dimostrarmi di essere $Gbravo:brava; a uccidere le tigri più giovani, $N: fino ad allora non me la sento di addestrarti oltre.",
  reward = "Ben fatto, $N. Sei $Gpronto:pronta; per il passo successivo.",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers.",
}
T[186] = {
  title = "Maestria nella Caccia alla Tigre",
  desc = "Stai imparando, $C. Adesso vediamo come te la cavi con i felini adulti: questa volta uccidi 10 Stranglethorn Tigers.",
  obj = "Ajeck Rouack della Nesingwary's Expedition vuole che tu uccida 10 Stranglethorn Tigers.",
  progress = "Se aspiri a sfide più grandi, prima devi dimostrare quanto vali con il compito che hai davanti. Torna da me quando avrai ucciso 10 Stranglethorn Tigers.",
  reward = "Mi hai colpita, $C. Stai facendo ottimi progressi.",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers.",
}
T[187] = {
  title = "Maestria nella Caccia alla Tigre",
  desc = "Adesso alzo la posta e metto alla prova sul serio la tua abilità. Dimostrami che sai uccidere 10 Elder Stranglethorn Tigers. Se ce la fai, sarai $Gpronto:pronta; per la sfida finale, prima che io ti proclami $Gmaestro cacciatore:maestra cacciatrice; di tigri davanti a Master Nesingwary.$B$BLe Elder Stranglethorn Tigers non sono soltanto le più difficili da trovare: sono anche le più feroci da battere.",
  obj = "Ajeck Rouack della Nesingwary's Expedition vuole che tu uccida 10 Elder Stranglethorn Tigers.",
  progress = "Prima che io ti dia la sfida finale, quella che stabilirà se sei $Gun vero maestro cacciatore:una vera maestra cacciatrice; di tigri, devi uccidere 10 Elder Stranglethorn Tigers.",
  reward = "Davvero notevole. Direi che sei quasi $Gpronto:pronta;.",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers.",
}
T[188] = {
  title = "Maestria nella Caccia alla Tigre",
  desc = "Ecco la sfida finale che ho per te. Da settimane seguiamo le tracce di una tigre sfuggente, che chiamiamo Sin'Dall. Prova a fare quello che $Gnessun:nessuna; $R ha mai fatto: stanare e uccidere Sin'Dall. Come prova dell'impresa, portami la sua zampa.$B$BSeguire le sue tracce non sarà facile.",
  obj = "Ajeck Rouack della Nesingwary's Expedition vuole che tu uccida Sin'Dall e torni con la sua zampa.",
  progress = "Come va la caccia a Sin'Dall?",
  reward = "Davvero notevole, devo proprio dirlo! Sei $Gun vero Maestro Cacciatore:una vera Maestra Cacciatrice; di Tigri, $N!",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw.",
}
T[189] = {
  title = "Bloodscalp Ears",
  desc = "Maledetti troll! Ci stanno facendo fuori gli agenti nella giungla! Fra uno scontro e l'altro ci ho già rimesso parecchie delle mie guardie migliori. E i costi salgono! Adesso come lo spiego a Baron Revilgaz?$B$BServe un'azione decisa... Pensa, Kebok... il posto che hai oggi non te l'hanno dato per startene con le mani in mano... Ci sono! Tu... $N, giusto? Mi darai una mano, vero? C'è da guadagnarci!$B$BFacciamo così... tu mi porti le orecchie di quindici Bloodscalp Trolls e io ti ricompenso bene.",
  obj = "Procurati 15 Bloodscalp Ears e portale a Kebok a Booty Bay.",
  progress = "È andata bene, spero? Quei troll sono dappertutto. Sporchi diavoli.$B$BOh sì, a proposito! Spargi la voce anche fra i tuoi amici, d'accordo? Di aiuto ce ne servirebbe tanto!",
  reward = "Oh, ottimo, ottimo. Per ora un po' aiuterà...$B$B<Si mette a borbottare di margini di profitto e di costi, e la voce gli si spegne...>$B$BCosa? Sei ancora qui? La ricompensa? Ah, giusto... certo, ecco, prendi questo... dovrebbe bastare e avanzare.",
  en_title = "Bloodscalp Ears",
  en_obj = "Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.",
}
T[190] = {
  title = "Maestria nella Caccia alle Pantere",
  desc = "Se vuoi unirti alla caccia con la squadra d'élite che Hemet ha messo insieme, dovrai dimostrare di essere $Gun abile cacciatore:un'abile cacciatrice; di pantere. Cominceremo con qualcosa di facile — non preoccuparti. Tanto per iniziare, vediamo se riesci a uccidere 10 young panthers.$B$BE trovarle è solo metà del lavoro...",
  obj = "Sir S. J. Erlgadin della Nesingwary's Expedition vuole che tu uccida 10 Young Panthers.",
  progress = "$GUn vero cacciatore:Una vera cacciatrice; di pantere sarebbe là fuori a braccare la preda. Dimostra un po' d'impegno per il tuo obiettivo, $C, e torna a caccia.",
  reward = "Un bell'inizio, $N!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers.",
}
T[191] = {
  title = "Maestria nella Caccia alle Pantere",
  desc = "Adesso sei $Gpronto:pronta; ad alzare il tiro. Se vuoi dimostrarti $Gdegno:degna; di stare con cacciatori di grossa selvaggina come questi, dovrai far vedere che sai uccidere 10 pantere.$B$BQuei bestioni sono più tosti, mica facili come le giovani che hai ucciso prima.",
  obj = "Sir S. J. Erlgadin della Nesingwary's Expedition vuole che tu uccida 10 Pantere.",
  progress = "Va' a uccidere 10 pantere! Facci vedere di che pasta sei $Gfatto:fatta;!",
  reward = "Lavoro perfetto, $N!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers.",
}
T[192] = {
  title = "Maestria nella Caccia alle Pantere",
  desc = "Adesso viene il difficile. Un vero cacciatore di pantere dimostra quanto vale abbattendo le Shadowmaw Panthers, le più letali di Stranglethorn. Facci vedere che sei in grado di uccidere 10 di queste bestie.$B$BSe ti sembra difficile seguirne le tracce, aspetta di provare a ucciderne una....",
  obj = "Sir S. J. Erlgadin della Nesingwary's Expedition vuole che tu uccida 10 Shadowmaw Panthers.",
  progress = "Che ci fai qui, $N! Dovresti essere nella boscaglia a strisciare e a cercare di uccidere 10 Shadowmaw Panthers. Non ti credevi $Gun gran cacciatore:una gran cacciatrice; di grossa selvaggina?",
  reward = "Bel lavoro, $N!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers.",
}
T[193] = {
  title = "Maestria nella Caccia alle Pantere",
  desc = "Ti manca poco per dimostrare di essere $Gun maestro:una maestra; nella caccia alle pantere. Nella giungla si aggira una pantera di nome Bhag'thera, che finora è sfuggita alla nostra compagnia. Vediamo se hai l'abilità per uccidere il grande Bhag'thera.$B$BPortami la Fang of Bhag'thera e ti sarai $Gguadagnato:guadagnata; il mio rispetto!",
  obj = "Sir S. J. Erlgadin della Nesingwary's Expedition vuole che tu gli porti la Fang of Bhag'thera.",
  progress = "Bhag'thera sa essere una bestia sfuggente. Come va la caccia?",
  reward = "Allora il grande Bhag'thera è morto! Alla tua salute, $N. Sei $Gun:una; $C davvero potente!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera.",
}
T[194] = {
  title = "Maestria sui Raptor",
  desc = "Allora credi che le tue abilità di caccia siano in perfetta forma? Posso metterle alla prova in un baleno: addentrati in quella giungla e uccidi 10 Stranglethorn Raptors, così vediamo quanto vali come $Gcacciatore:cacciatrice; di grossa selvaggina.$B$BE no, dove trovarli non te lo dico! Scovare le bestie è metà della sfida.",
  obj = "Hemet Nesingwary vuole che tu uccida 10 Stranglethorn Raptors.",
  progress = "Non ho mai conosciuto un cacciatore che abbia abbattuto qualcosa standosene accanto al fuoco. Quegli Stranglethorn Raptors li volevi uccidere o speravi che morissero di vecchiaia?",
  reward = "Ben fatto, $Gvecchio mio:mia signora;!",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill 10 Stranglethorn Raptors.",
}
T[195] = {
  title = "Maestria sui Raptor",
  desc = "Adesso alziamo il tiro e vediamo se sei all'altezza. Addentrati nella giungla e mettiti nel carniere 10 di quei dannati Lashtail Raptors. Fammi vedere cosa sai fare!",
  obj = "Hemet Nesingwary vuole che tu uccida 10 Lashtail Raptors.",
  progress = "Un vero cacciatore resta concentrato sulla preda, mentre tu, $Gamico mio:amica mia;, mi sembri più $Ginteressato:interessata; a chiacchierare accanto al fuoco. Adesso vai là fuori e uccidi 10 Lashtails, prima che ci vada io e ne ripulisca l'intera dannata giungla in una sola battuta.",
  reward = "Così sì che si appende un trofeo o due sopra il vecchio camino! Bella caccia, $N!",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill 10 Lashtail Raptors.",
}
T[196] = {
  title = "Maestria sui Raptor",
  desc = "Vediamo come te la cavi con la prossima sfida. Là fuori c'è una razza di raptor diffidente, che noi chiamiamo Jungle Stalkers: rintracciarli e abbatterli è molto più difficile che con le altre razze su cui hai tentato la fortuna. Uccidi 10 Jungle Stalkers e ti darò una dritta sulla caccia migliore che ci sia.",
  obj = "Hemet Nesingwary vuole che tu uccida 10 Jungle Stalkers.",
  progress = "Bah! Che ci fai lì $Gimpalato:impalata;, $N! Un vero cacciatore di grossa selvaggina, quando ha la preda nel mirino, non si arrende mai. Quei Jungle Stalkers non verranno di corsa fino a questo fuoco per buttarcisi dentro. Che $Gsciocco:sciocca;.",
  reward = "Oh oh!! Ecco qui $Gun vero sterminatore:una vera sterminatrice; di raptor! Ben fatto, $Gvecchio mio:mia bella signora;!",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill 10 Jungle Stalkers.",
}
T[197] = {
  title = "Maestria sui Raptor",
  desc = "Visto quanto sei $Gstato:stata; intraprendente nella giungla, voglio parlarti di un raptor feroce che neanche io sono riuscito ad abbattere. Questo astuto raptor, Ajeck qui lo chiama Tethis.$B$BSe vuoi dimostrare di essere $Gun vero maestro:una vera maestra;, uccidi Tethis e portami il suo artiglio: sarebbe un'impresa che nessun altro cacciatore di grossa selvaggina ha mai compiuto.",
  obj = "Hemet Nesingwary vuole che tu uccida Tethis, un raptor sfuggente e pericoloso a Stranglethorn.",
  progress = "Come va la caccia a Tethis? L'hai seguito fin qui al campo, eh?",
  reward = "$GMaestro:Maestra; $N, $Gsterminatore:sterminatrice; di raptor!$B$BSuona bene, eh?",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill Tethis, an elusive, dangerous raptor in Stranglethorn.",
}
T[198] = {
  title = "Rifornimenti per Private Thorsen",
  desc = "Mmh. Sì, in effetti qualcosa da farti fare ce l'avrei. Lieutenant Doren e i suoi seguaci, su a nord, hanno bisogno dei soliti rifornimenti che gli mandiamo.$B$BNon gli sono stati consegnati, e con i troll all'attacco mi serve qualcuno che se ne occupi. L'accampamento di Doren è a nordovest della strada, dove si entra a Stranglethorn da Duskwood. Porta i rifornimenti a Private Thorsen, e se non è all'accampamento, sarà di pattuglia a sud. Ci penserà lui.$B$BBada, se fallisci dovrai risarcirmi.",
  obj = "Consegna i Miscellaneous Goblin Supplies a Private Thorsen.",
  progress = "Sì? Che vuoi? Oh, i rifornimenti dei goblin. Strano vedere $Gun:una; $R che li porta, di solito mandano uno dei loro. Non importa... non li hai toccati, vero? Bene, bene... non vorremmo che alle nostre mine succedesse qualcosa, oh no.",
  reward = "Con queste mine terrestri ci difenderemo da quell'animale di Kurzen e dai suoi uomini. Grazie di avercele portate. Se cerchi altro lavoro, probabilmente qualcosa da farti fare lo trovo. E non dovrai avere a che fare con quei goblin, eh?",
  en_title = "Supplies to Private Thorsen",
  en_obj = "Deliver the Miscellaneous Goblin Supplies to Private Thorsen.",
}
T[200] = {
  title = "Bookie Herod",
  desc = "Se Kurzen conosce il segreto di Thorsen, fra noi c'è una spia. Dobbiamo scoprire come è trapelato!$B$BNell'accampamento di Kurzen, il contatto di Thorsen era Bookie Herod. Herod è l'ufficiale che cura la logistica di Kurzen, e sa tutto di come si manda avanti il Kurzen's Compound. Se riesci a mettere le mani sugli appunti o sui registri di Herod, forse scopriremo come hanno smascherato Thorsen.$B$BQuando stavamo ancora con Kurzen, l'Allibratore aveva l'ufficio all'ultimo piano dell'unica casa a due piani dell'accampamento. I registri saranno ancora lì.",
  obj = "Trova i Bookie Herod's Records.",
  reward = "Sono gli appunti e i registri di Bookie Herod.$B$BCi si trovano: un elenco delle provviste dell'accampamento, alcune richieste di materiale di Colonel Kurzen, e lettere e corrispondenza varia.",
  en_title = "Bookie Herod",
  en_obj = "Find Bookie Herod's Records.",
}
T[201] = {
  title = "Indaga sull'Accampamento",
  desc = "Mi è stato riferito che un gruppo di cacciatori si è accampato a monte del campo minerario della Venture Company sul Lake Nazferiti. Ora, di solito non me ne importerebbe, ma ho sentito dire, per quanto sembri improbabile, che fra loro c'è Hemet Nesingwary? Uno così ha di certo conoscenze importanti, se capisci cosa intendo, e la prudenza non è mai troppa.$B$BPerché non vai a dare un'occhiata all'accampamento, $N, e vedi cosa stanno combinando?",
  obj = "Trova l'accampamento dei cacciatori e riferisci la sua posizione a Krazek a Booty Bay.",
  progress = "Allora? Sei $Griuscito:riuscita; a trovarlo, l'accampamento?",
  reward = "Mmm, allora le mie informazioni erano esatte, come sempre. Interessante. Be', non credo che rischino di intralciare i nostri affari, ma magari gli serve qualcuno dei nostri eccellenti prodotti. Mmm...",
  en_title = "Investigate the Camp",
  en_obj = "Find the hunters' camp and report its location to Krazek in Booty Bay.",
}
T[202] = {
  title = "Colonel Kurzen",
  desc = "Hai dimostrato il tuo valore più e più volte, e sembri intraprendente quanto lo stesso Kurzen. Potresti essere la salvezza della nostra banda di ribelli... se riuscirai a misurarti con Kurzen e ad avere la meglio!$B$BComanda i suoi uomini dal cuore dello Stockpile. Devi entrare in quella caverna, aprirti la strada fra i difensori e affrontare Kurzen insieme ai suoi capi.$B$BAddio, $N. Porti con te la mia speranza e il destino dei miei uomini.",
  obj = "Uccidi 6 Kurzen Elite, 4 Kurzen Subchiefs e porta la Kurzen's Head a Lieutenant Doren all'Accampamento dei Ribelli.",
  progress = "$N, posso sperare che Kurzen e i suoi difensori siano morti?",
  reward = "Non osavo credere ai rapporti, eppure ci porti la prova che... Kurzen e i suoi capi sono stati sconfitti. Ci hai salvati!$B$BIn queste giungle c'è ogni tipo di minaccia, ma nessuna aveva l'intelletto crudele di Kurzen. Ora che non c'è più, possiamo respirare tutti più tranquilli.",
  en_title = "Colonel Kurzen",
  en_obj = "Kill 6 Kurzen Elite, 4 Kurzen Subchiefs, and bring Kurzen's Head to Lieutenant Doren at the Rebel Camp.",
}
T[203] = {
  title = "La Seconda Ribellione",
  desc = "Contro Colonel Kurzen stiamo perdendo. È un tattico geniale, e per giunta ci supera in numero almeno 10 a 1! Se vogliamo sopravvivere, dobbiamo usare contro di lui i suoi stessi metodi furtivi.$B$BEntra nel suo accampamento, a est, e uccidi i suoi uomini. Tanti. Poi vattene, prima che i rinforzi ti accerchino.",
  obj = "Uccidi 15 Kurzen Jungle Fighters.$B$BTorna da Sergeant Yohwa all'Accampamento dei Ribelli.",
  progress = "Spero che la caccia sia andata bene, $N. Senza il tuo aiuto contro di lui non resisteremo a lungo.",
  reward = "Ben fatto. Con quei Jungle Fighters in meno, il nostro accampamento sarà un po' meno sotto pressione.$B$BMa ora che hai avuto un assaggio delle forze che stiamo affrontando, vuoi ancora legare il tuo destino al nostro??",
  en_title = "The Second Rebellion",
  en_obj = "Kill 15 Kurzen Jungle Fighters.$B$BReturn to Sergeant Yohwa at the Rebel Camp.",
}
T[204] = {
  title = "Cattiva Medicina",
  desc = "Se vogliamo avere una possibilità contro Kurzen, dobbiamo togliere di mezzo i suoi guaritori. Si è circondato di un gran numero di Stregoni, che curano i suoi con i Jungle Remedies e avvelenano i nostri combattenti con i Venom Fern Extracts.$B$BQuei medicinali ci servono per curare la nostra gente, e degli estratti ci serve un campione da studiare, per preparare rimedi nostri. Cercali entrambi nel Kurzen Compound — i medicinali li avranno i suoi Stregoni, mentre gli estratti sono probabilmente riposti in qualche cassa di rifornimenti dell'accampamento.",
  obj = "Porta 7 Jungle Remedies e 1 Venom Fern Extract a Sergeant Yohwa all'Accampamento dei Ribelli.",
  progress = "Aspetto ancora quei medicinali e quell'estratto, $N.",
  reward = "Ben fatto, $N. Con questi medicinali, più dei nostri resteranno vivi e potranno combattere. E gli estratti ci aiuteranno a preparare rimedi nostri.",
  en_title = "Bad Medicine",
  en_obj = "Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp.",
}
T[205] = {
  title = "Stregoneria dei Troll",
  desc = "Mentre io studio le leggende che hai trovato, tu raccoglimi qualche strumento della malvagia magia dei troll. Molto più a sud c'è un'altra tribù, i troll Skullsplitter: entra nel loro territorio e procurati dai loro Stregoni e Mistici degli Skullsplitter Fetishes.",
  obj = "Porta 4 Skullsplitter Fetishes a Brother Nimetz all'Accampamento Ribelle.",
  progress = "Hai quei feticci, $N? Forse custodiscono il segreto della degradazione di Kurzen... devo saperlo!",
  reward = "Grazie. Studierò questi feticci, e vedrò se custodiscono il segreto della caduta di Kurzen nel male.",
  en_title = "Troll Witchery",
  en_obj = "Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp.",
}
T[206] = {
  title = "Mai'Zoth",
  desc = "Kurzen sarà anche morto, ma... quello che lo ha spinto al male vive ancora! Studiando ho scoperto questo: un Ogre Mage — Mai'Zoth — vive in un Ogre Mound fra le montagne orientali di Stranglethorn. Si dice che usi una magia capace di controllare la mente, e sono certo che a corrompere Kurzen sia stato lui.$B$BSe Mai'Zoth resta in vita, il suo male potrebbe influenzare altri, e far nascere perfino un altro Kurzen.$B$BUccidilo e portami il suo Mind's Eye, l'artefatto con cui corrompe gli altri.",
  obj = "Porta il Mind's Eye a Brother Nimetz all'Accampamento Ribelle.",
  progress = "Hai la mia benedizione. Mai'Zoth è tanto forte quanto malvagio.",
  reward = "Aha! Ce l'hai fatta! Sei una grande forza del bene, $N, e che il tuo vigore non si spenga mai!$B$BStudierò questo Mind's Eye e vedrò se può servire al bene. Se no... andrà distrutto.",
  en_title = "Mai'Zoth",
  en_obj = "Bring the Mind's Eye to Brother Nimetz at the Rebel Camp.",
}
T[207] = {
  title = "Il Mistero di Kurzen",
  desc = "Un tempo Colonel Kurzen era un uomo grande e nobile — devo scoprire cosa l'ha fatto cadere nella depravazione! Forse è sotto l'influsso della magia dei troll. Per averne conferma devo studiare alcune delle loro leggende.$B$BFra le rovine dei troll di Stranglethorn sono nascoste 4 tavolette, e devo sapere cosa c'è scritto! Copiane i segni e riportami le trascrizioni.$B$BLa prima tavoletta si trova nelle Bal'lal Ruins, la seconda nella Vile Reef, la terza e la quarta nelle Ruins of Zul'Kunda.",
  obj = "Trova le 4 tavolette e riporta le loro leggende a Brother Nimetz.",
  progress = "$N! Ce le hai, le leggende dei troll? Devo conoscerne i segreti!",
  reward = "Grazie, $N. Studierò queste leggende per capire se c'è qualche legame fra i troll e il male che si è impossessato di Colonel Kurzen.",
  en_title = "Kurzen's Mystery",
  en_obj = "Find the 4 tablets and bring their legends back to Brother Nimetz.",
}
T[208] = {
  title = "$GCacciatore:Cacciatrice; di Grossa Selvaggina",
  desc = "$N, sei $Gun cacciatore degno:una cacciatrice degna; della nostra compagnia. Dai campi di battaglia di Lordaeron fino alla giungla più fitta, di rado ho visto maneggiare le armi con l'abilità che hai dimostrato tu.$B$BHai ucciso la feroce Sin'Dall, l'inafferrabile Bag'thera e l'infido Tethis, ma il vero premio è la testa di King Bangalash. È per quella tigre bianca che sono qui, e ormai è da parecchio tempo che lo tengo nel mirino. Uccidi King Bangalash e avrai dimostrato che nella caccia non sei $Gsecondo:seconda; a nessuno.",
  obj = "Hemet Nesingwary vuole che tu gli porti la testa di King Bangalash, la grande tigre bianca.",
  progress = "Vedo che sei $Gtornato:tornata;, $Gvecchio mio:ragazza mia;. King Bangalash mi ha rimandato all'accampamento strisciando parecchie volte. Tieni duro.",
  reward = "Accidenti, ottimo lavoro! Benone! Complimenti, $N: sei $Griuscito:riuscita; dove altri hanno fallito.$B$BÈ un onore averti come $Gcompagno:compagna; nella nostra grande squadra di caccia. Nessuno dubiterà mai di quanto sei $Gbravo:brava; a cacciare e a seguire le tracce!$B$BAlla tua salute, dico io! Salute!",
  en_title = "Big Game Hunter",
  en_obj = "Hemet Nesingwary wants you to bring him the head of King Bangalash, the great white tiger.",
}
T[209] = {
  title = "Skullsplitter Tusks",
  desc = "Esportiamo zanne di tigre verso le isole dei South Seas, ma ammazzare abbastanza tigri da tenere in piedi il commercio costa caro ed è difficile. Per fortuna abbiamo messo a punto una tecnica per prendere comuni oggetti simili a corna e trasformarli in falsi che nessuno potrà mai scoprire.$B$BE, incredibile ma vero, la cosa più somigliante che abbiamo trovato sono le zanne dei troll Skullsplitter.$B$BEhi, prima che tu dica qualcosa: occhio non vede, cuore non duole, giusto? Portamene un bel po', così ci mettiamo al lavoro per la spedizione del mese!",
  obj = "Procurati 18 Skullsplitter Tusks e portale a Kebok.",
  progress = "Tosti, quei disgraziati, eh? Allora, com'è andata? Scusa l'impazienza, ma questa faccenda è stata una grossa spina nel fianco! Allora?",
  reward = "Ah, bel lavoro, bel lavoro! Puah, anche se potevi pulire meglio le — Be', non importa, non importa! Grazie, $N: col tuo aiuto la nostra attività vedrà di sicuro crescere produzione e produttività! Bene bene, adesso passiamo ad altro...",
  en_title = "Skullsplitter Tusks",
  en_obj = "Acquire 18 Skullsplitter Tusks and return them to Kebok.",
}
T[210] = {
  title = "La Cucina di Krazek",
  desc = "All'accampamento cucino quasi sempre io. Ed era un lavoraccio, finché a Booty Bay non ho comprato una pentola meccanica da un mercante goblin. Una meraviglia! Non so quante ore mi ha fatto risparmiare... finché non si è rotta!$B$BPotresti riportare la pentola al goblin, così me la ripara? Si chiama Krazek.",
  obj = "Porta la Krazek's Crock Pot al goblin Krazek.",
  progress = "Ciao! Hai portato qualcosa per me?",
  reward = "Ah, ecco: una Krazek's Crock Pot! Un lavoro geniale, ma ogni tanto una molla si rompe o un ingranaggio va perso. Vediamo cos'ha questa...$B$BAha! Il caricatore a vapore è tutto arrugginito, c'è una guarnizione a snodo crepata e al fobulatore mancano dei denti. Ridotta così, mi stupisce che riuscisse anche solo a far bollire una rapa!$B$BSe posso aggiustarla? Certo che posso!$B$BMa c'è un prezzo. Oh sì, c'è sempre un prezzo...",
  en_title = "Krazek's Cookery",
  en_obj = "Bring Krazek's Crock Pot to Krazek the goblin.",
}
T[211] = {
  title = "Ahimè, Andorhal",
  desc = "Ahimè, è venuto il momento di attaccare Andorhal e di scacciare il lich che la controlla!$B$BIl lich — Araj the Summoner — regna fra le rovine della città. Lo difendono numerose forze dello Scourge, schierate attorno a quel che resta del centro, e una formidabile scorta personale di guardiani che gli sta sempre vicino. Contro di lui ti serviranno molti alleati, anche solo per avere una speranza di spuntarla.$B$BDistruggi Araj, $N, e come prova portami una scheggia del suo filatterio!",
  obj = "Porta l'Araj's Phylactery Shard a Commander Ashlam Valorfist a Chillwind Camp, nelle Western Plaguelands.",
  progress = "Ti ho già detto qual è il tuo compito, $N. Hai una scheggia del filatterio del lich, che provi che ce l'hai fatta?",
  reward = "Ce l'hai fatta! Araj... finalmente il lich è sconfitto!$B$BOggi hai reso all'Alleanza un servizio straordinario, $N. Il tuo coraggio e la tua perseveranza dimostrano cosa vuol dire essere $Gun vero eroe:una vera eroina;. Ti prego — accetta questo come segno, perché tutti vedano e sappiano che hai regalato all'Alleanza una vittoria che si ricorderà nei secoli!",
}
T[212] = {
  title = "Un Piatto Servito Freddo",
  desc = "Uno dei miei piatti più famosi è il Basilisco Ghiacciato in Vinaigrette al Lime. Ma il problema è che... tenere fresca la carne è impossibile, e stasera devo servirlo per il compleanno di un nobile!$B$BQuindi, se mi porti in fretta un Chilled Basilisk Haunch da un Cold Eye Basilisk appena ucciso, ti dovrò un banchetto da re!$B$BSi sa che i Cold Eye Basilisks girano fra le dune della spiaggia, nel nord-ovest di Stranglethorn, quindi avrai molta strada da fare. E sbrigati!",
  obj = "Uccidi un Cold Eye Basilisk, prendi un Chilled Basilisk Haunch e portalo ad Angus Stern al Blue Recluse.$B$B<Per riuscire in questa missione non devi liberare il tuo spirito.>",
  progress = "$N! Ce l'hai, quel cosciotto? Devo cominciare presto a prepararlo, altrimenti il banchetto sarà rovinato!",
  reward = "Ah, questo andrà benissimo! Grazie, grazie mille!$B$BE ora, se permetti, devo tagliare, marinare e guarnire il cosciotto per il banchetto.",
  en_title = "A Meal Served Cold",
  en_obj = "Kill a Cold Eye Basilisk, get a Chilled Basilisk Haunch, and return it to Angus Stern in the Blue Recluse.",
}
T[213] = {
  title = "Acquisizione Ostile",
  desc = "Stavolta l'ha fatta grossa! Non bastava che Gelriz scalzasse i magnati nominati dai principi mercanti: adesso cerca pure di prendersi una fetta degli affari del pirata più famigerato!$B$BRevilgaz non lo tollera, e mi ha detto di sistemare il problema a modo mio.$B$BA modo mio? Rubando. I geologi della Venture Co., vicino al Lake Nazferiti, sono molto interessati a certi strani cristalli blu che stanno trovando nelle miniere. Porta via ai geologi qualche campione della pietra e consegnalo a me: cosa dovrai fare per averlo non m'importa.",
  obj = "Recupera 8 Tumbled Crystals e portali a Kebok a Booty Bay.",
  progress = "Quelle pietre mi servono, $N. Con ogni mezzo! Fallo e basta, e risparmiami i dettagli!$B$BQuello che conta sono i risultati, $N, niente di più, niente di meno.",
  reward = "Affascinante. Se i cristalli li hanno sgretolati con questo procedimento, può voler dire solo che pensano di usarli come una specie di combustibile, o come qualche altro catalizzatore. Di più non so. Dovremo mandare dei campioni a Head Chemist Gigglefont.",
  en_title = "Hostile Takeover",
  en_obj = "Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.",
}
T[214] = {
  title = "Red Silk Bandanas",
  desc = "Non è un segreto che le Bandane Rosse siano il marchio di fabbrica della Defias Gang. Ma abbiamo scoperto che il tessuto di cui sono fatte indica il rango di chi le porta.$B$BPerciò voglio che elimini quanti più membri di alto grado dei Defias riesci. I capi più importanti si troveranno senza dubbio nel covo segreto di VanCleef. Quando hai finito, portami 10 Red Silk Bandanas come prova della loro morte e ti ricompenserò. Buona fortuna, $N.",
  obj = "Scout Riell, presso Sentinel Hill Tower, vuole che le porti 10 Red Silk Bandanas.",
  progress = "Stai riconquistando la nostra terra, strappandola alla banda dei Defias? Se è così, mostrami 10 Red Silk Bandanas come prova.",
  reward = "Ben fatto, $N! A nome di The People's Militia ti rendo onore per il tuo impegno. Presto, con l'aiuto di anime coraggiose come te, restituiremo questa terra al popolo.",
  en_title = "Red Silk Bandanas",
  en_obj = "Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.",
}
T[215] = {
  title = "Segreti della Giungla",
  desc = "Grazie di avermi salvato, $N. Lo so cosa sembra, ma... lascia che ti spieghi.$B$BÈ stato Lieutenant Doren a mandarmi di nuovo fra gli uomini di Kurzen: dovevo arruolarmi, spiarli e portare ai ribelli le informazioni di cui hanno tanto bisogno. Quello che hai visto qui doveva essere, o almeno così credevo, la mia occasione per infiltrarmi nel Kurzen's Compound. Mi sbagliavo, e ti ringrazio ancora di avermi salvato.$B$BEra una missione top secret, quindi non farne parola con nessuno. Se però vai a parlare con Doren, ti spiegherà lui.",
  obj = "Parla con Lieutenant Doren all'Accampamento Ribelle.",
  reward = "Sì, Thorsen ti ha detto la verità, e su questa faccenda devi essere $Gdiscreto:discreta;. Un tempo noi ribelli eravamo fedelissimi a Colonel Kurzen, ma Kurzen era così corrotto che la nostra passione si è trasformata in rabbia. Se venisse fuori che di recente Private Thorsen ha avuto a che fare con gli uomini di Kurzen, una notte si ritroverebbe con la gola tagliata.$B$BPer quanto ne so, della missione di Thorsen eravamo al corrente solo io, Sergeant Yohwa e Thorsen stesso. Eppure dev'esserci qualcun altro. Un traditore.",
  en_title = "Jungle Secrets",
  en_obj = "Speak with Lieutenant Doren at the Rebel Camp.",
}
T[216] = {
  title = "Tra l'Incudine e i Thistlefur",
  desc = "I furbolgs Thistlefur minacciano la nostra espansione! A est c'è il Thistlefur Village, che blocca la strada che ci collega allo Splintertree Post: una via che ci farebbe aggirare il villaggio di Astranaar. Senza, lasceremmo all'Alleanza una via d'espansione in più.$B$B$N, non possiamo permettere... un divario nelle vie d'espansione!$B$BVa' al Thistlefur Village e sfoltisci i furbolgs. Avrai un compenso per il lavoro, ma soprattutto farai il tuo dovere per l'Orda!",
  obj = "Abbatti 12 Thistlefur Avengers e 12 Thistlefur Shaman; la maggior parte si trova a est della Zoram Strand, nel Thistlefur Village. Fatto questo, torna da Karang Amakkar allo Zoram'gar Outpost, ad Ashenvale.",
  progress = "Hai dato battaglia ai Thistlefur? Con una via libera tra le nostre basi, avremo molte più possibilità di conquistare tutta Ashenvale.",
  reward = "Ben fatto, $C, ben fatto! Manderò ancora truppe a sfoltire i furbolg, ma almeno posso contare su una via diversa, libera da impicci con l'Alleanza. Ormai l'Orda è lanciata alla conquista di Ashenvale!$B$BOggi ti sei $Gguadagnato:guadagnata; la paga, $Geroe:eroina;. Ti rendo onore!",
  en_title = "Between a Rock and a Thistlefur",
  en_obj = "Take down 8 Thistlefur Avengers and 8 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village.  Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale.",
}
T[219] = {
  title = "Disperso in Combattimento",
  desc = "Finalmente, amici dell'Alleanza!$B$BAiuto... vi prego...$B$BL'ultima cosa che ricordo sono questi luridi Orchi che sopraffanno il nostro reggimento. Quasi tutti gli uomini sono stati uccisi. Io ho preso un brutto colpo in testa e ho perso i sensi, e adesso mi tengono prigioniero in questa caverna. Aiutatemi, sono gravemente ferito.$B$BHo bisogno di aiuto per tornare in città... vi prego... siete la mia ultima speranza...",
  obj = "Proteggi Corporal Keeshan durante il viaggio di ritorno a Redridge.",
  progress = "Sì?",
  reward = "Hai servito bene il Regno, $C. Grazie per aver aiutato Corporal Keeshan a scappare da quei temibili Blackrock Orcs. Sarai $Gricompensato:ricompensata; per il coraggio che hai dimostrato oggi.",
  en_title = "Missing In Action",
  en_obj = "Protect Corporal Keeshan on the journey back to Redridge.",
}
T[220] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Prima di ricompensarti con il prossimo totem, Islen avrà un altro compito per te, e qualunque sia, ti servirà la fiala d'acqua che ti ho dato.$B$BOra va' da lei. Un giorno ci rivedremo.",
  obj = "Porta la Vial of Purest Water a Islen Waterseer nelle Barrens.",
  progress = "$GBen ritrovato:Ben ritrovata;, $N. Ti vedo bene.$B$BChe cosa ti riporta qui così presto?",
  reward = "Ah, una fiala d'acqua creata e benedetta da Brine, e raccolta per di più da te.$B$BIl liquido di questa fiala sarà indispensabile per preparare la tua sapta, ma servirà anche a un altro compito.$B$BCon la sapta che creerò per te potrai vedere gli spiriti dell'acqua al santuario nella Silverpine Forest, a sud dell'Undercity. Le gocce rimaste, be', di quelle ti parlerò se pensi di essere $Gpronto:pronta;.$B$BTe la senti di partire per un altro viaggio, $N?",
  en_title = "Call of Water",
  en_obj = "Bring the Vial of Purest Water to Islen Waterseer in the Barrens.",
}
T[221] = {
  title = "Worgen nei Boschi",
  desc = "Avrai forse notato, nei boschi, dei worgen più grossi che si aggirano insieme agli Shadow Weavers? Da quel che abbiamo capito, sono questi Dark Runners il grosso dei worgen.$B$BPerlustrando la zona ho visto anche che hanno invaso il Rotting Orchard, a sud-ovest del villaggio. Sono worgen un po' più duri di quelli che hai affrontato l'ultima volta.$B$BStai in guardia.",
  obj = "Uccidi 12 Nightbane Dark Runner worgen per Calor a Darkshire.",
  progress = "Già di ritorno, $N? Spero che tu non sia $Gvenuto:venuta; a dirmi che ti sei $Garreso:arresa;.",
  reward = "Te la sei cavata bene contro i Dark Runners, $N. Però sembra che non finiscano mai. Ogni volta che facciamo un passo avanti, ne spuntano altri a riempire le loro file.$B$BQuale potere malvagio li attira qui? Perché sono venuti a turbare il nostro infelice regno...$B$BMi affiderò a Master Carevin. Sono certo che andrà a fondo della questione.",
  en_title = "Worgen in the Woods",
  en_obj = "Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire.",
}
T[222] = {
  title = "Worgen nei Boschi",
  desc = "Dopo quello che hai fatto finora, sono convinto che tu sia $Gpronto:pronta; ad affrontare i worgen più duri che infestano i boschi.$B$BFra i worgen che si sono fatti una nuova casa qui, i più pericolosi si sono rivelati le Vile Fangs e i Tainted Ones, che si sono stabiliti vicino ad alcune caverne e nella miniera a sud.$B$BPersino da lontano si vede la luce dei loro falò...",
  obj = "Uccidi 8 Nightbane Vile Fang e 8 Nightbane Tainted One worgen per Calor a Darkshire.",
  progress = "Bestie che mettono paura, vero? Ma non avere timore, $N, chi sta dalla parte della Luce non cadrà mai!",
  reward = "$N, a dirti la verità non pensavo che saresti $Garrivato:arrivata; fin qui, ma è chiaro che sei $Gun:una; $C da non sottovalutare. Anzi, se vuoi unirti ufficialmente alla lotta di Master Carevin, sarò lieto di scriverti una lettera di raccomandazione.",
  en_title = "Worgen in the Woods",
  en_obj = "Kill 8 Nightbane Vile Fang and 8 Nightbane Tainted One worgen for Calor in Darkshire.",
}
T[223] = {
  title = "Worgen nei Boschi",
  desc = "Ecco, $N. Porta questo messaggio a Master Carevin.$B$B<Tira fuori in fretta un pezzo di pergamena sbiadita e te lo porge.>$B$BAncora qualcuno come te e saremo più numerosi della Night Watch! Allora forse potremmo finire il lavoro che per ora portiamo avanti in pochi.",
  obj = "Porta il biglietto di Calor a Jonathan Carevin.",
  progress = "Sì, che c'è? Fai in fretta, ho faccende urgenti da sbrigare.",
  reward = "Perdona la fredda accoglienza, $N, ma, come avrai di certo capito, sono un uomo impegnatissimo. Vedo che hai fatto colpo su Calor — e ti assicuro che non è impresa da poco — e che ti ha raccomandato.$B$BCi sono brutti ceffi in giro, $N, e ci serve l'aiuto di chiunque abbia dimostrato il suo valore. Combattiamo i demoni, i non morti e chi vorrebbe dar loro una mano. Sta' all'erta, sii $Gcauto:cauta; e non fidarti di chi non sostiene la nostra causa.$B$BGloria sotto la Luce.",
  en_title = "Worgen in the Woods",
  en_obj = "Bring Calor's note to Jonathan Carevin.",
}
T[225] = {
  title = "La Tomba Logora",
  desc = "Sulla lapide logora c'è scritto soltanto:$B$BMORGAN LADIMORE$B$B<Guardando meglio, ti accorgi che la terra sulla tomba è stata smossa da poco e che buona parte sembra essere stata spostata...>",
  obj = "Parla con Sirra Von'Indi a Darkshire.",
  reward = "Morgan Ladimore?$B$BAhh, sì, certo. La sua è una storia lunga e dolorosa. Lo conoscevo, beh, prima che partisse per la guerra, ma da allora non l'ho più visto. Era un uomo nobile e buono, ma ha fatto una brutta fine.$B$BEcco, qui dovrei avere qualcosa che la racconta meglio di quanto possano fare i miei ricordi...",
  en_title = "The Weathered Grave",
  en_obj = "Speak with Sirra Von'Indi in Darkshire.",
}
T[226] = {
  title = "Lupi alle Calcagna",
  desc = "A Sven e a me aspettano giorni pericolosi, con il Negromante a est e tutto il resto. E qui fuori, da soli come siamo, per mangiare dobbiamo cacciare. Pare che ogni volta che torno al campo con un po' di carne escano dalla foresta metalupi affamati o rabid dire wolves in cerca di un boccone. Inutile dirlo: vivere qui fuori è un mestiere pericoloso!$B$BMa se riesci a toglierci di torno un po' di quei lupi, ce la caveremo meglio. Girano soprattutto a nord e a est di qui, vicino al fiume.",
  obj = "Uccidi 12 Starving Dire Wolves e 8 Rabid Dire Wolves, poi torna da Lars allo Sven's Camp, sul confine occidentale di Duskwood.",
  progress = "Stai ancora dando la caccia ai lupi...?",
  reward = "Oh, bene. Quel branco l'hai sfoltito parecchio, e ora che non abbiamo più quei lupi alle calcagna possiamo concentrarci su Morbent Fel.$B$BEcco, prendi un po' di questi Flash Bundles. Li fanno in città, e molti li hanno donati a Sven per sostenere la sua causa.",
  en_title = "Wolves at Our Heels",
  en_obj = "Kill 12 Starving Dire Wolves and 8 Rabid Dire Wolves, then return to Lars at Sven's Camp on the western border of Duskwood.",
}
T[227] = {
  title = "Morgan Ladimore",
  desc = "<Fruga tra gli scaffali e tira fuori un libro rilegato in pelle.>$B$BSe vuoi saperne di più, potresti chiedere ad Althea: ultimamente è lei che si occupa dei... problemi... con lui.",
  obj = "Parla con Commander Althea Ebonlocke a Darkshire.",
  reward = "Morgan Ladimore? Mai sentito...$B$BOh, vuoi dire Mor'Ladim! Non conosci la storia, immagino?$B$BBeh, te la racconto in breve. Per Duskwood vaga un non morto errante che si fa chiamare Mor'Ladim. Da quel che abbiamo scoperto, sembra sia il corpo non morto di Morgan Ladimore, di cui a quanto pare sai qualcosa. Ci crea problemi di ogni sorta: attacca le Guardie di pattuglia e uccide la gente.$B$B<Ti squadra da capo a piedi.>$B$BMi sembri abbastanza in gamba. Forse potresti essere tu a farlo riposare in pace.",
  en_title = "Morgan Ladimore",
  en_obj = "Speak with Commander Althea Ebonlocke in Darkshire.",
}
T[228] = {
  title = "Mor'Ladim",
  desc = "Da quel che mi riferiscono gli esploratori, Mor'Ladim vaga per Duskwood seguendo un percorso strano e tortuoso attraverso il cimitero. L'abbiamo sepolto oltre la casa sulla collina: sai dov'è?$B$BIo non posso aiutarti in nessun modo, ma ti auguro buona fortuna.",
  obj = "Uccidi Mor'Ladim, poi porta il suo teschio a Commander Althea Ebonlocke a Darkshire.",
  progress = "Se hai problemi con lui non ti biasimo, $N. Per colpa di Mor'Ladim abbiamo perso alcune delle nostre Vedette più forti.",
  reward = "L'hai ucciso? Non è un'impresa da poco, $N! Ti ringrazio a nome della gente di Darkshire e della Night Watch.$B$BAh... però c'è una piccola questione...",
  en_title = "Mor'Ladim",
  en_obj = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.",
}
T[229] = {
  title = "La Figlia Sopravvissuta",
  desc = "Avrei dovuto dirtelo prima...$B$BCome dire...$B$BMorgan avrà anche creduto di avere la famiglia tutta morta, ma in realtà sua figlia Sarah Ladimore adesso è una Vedetta. Le... circostanze... della morte del padre l'hanno sempre turbata. Forse potresti andare tu a darle la notizia.",
  obj = "Parla con Watcher Sarah Ladimore a Darkshire.",
  reward = "Sì? Mio padre...$B$B<Abbassa lo sguardo.>$B$BAvrei voluto... poter fare qualcosa per lui... Se solo gli avessi parlato prima che...",
  en_title = "The Daughter Who Lived",
  en_obj = "Speak with Watcher Sarah Ladimore in Darkshire.",
}
T[230] = {
  title = "Sven's Camp",
  desc = "Scavando nel cumulo, trovi un piccolo libro sporco di terra.$B$BNon ha titolo, ma... contiene informazioni che potrebbero interessare a Sven.",
  obj = "Porta il Book from Sven's Farm a Sven.",
  progress = "Hai trovato cosa?? Ti prego, fammelo vedere...",
  reward = "<Sven legge le pagine del libro, poi lo chiude di scatto.>$B$BQuella figura nell'ombra che ho visto ha assistito alla morte della mia famiglia! Avrei qualche domanda da fare a quell'uomo... se solo sapessi chi è!",
  en_title = "Sven's Camp",
  en_obj = "Bring the Book from Sven's Farm to Sven.",
}
T[231] = {
  title = "L'Amore di una Figlia",
  desc = "Ecco, prendi questo e posalo sulla sua tomba. Forse... in un modo o nell'altro, saprà che sto bene, e che nessuno di noi gli dà la colpa di quello che è successo.$B$B<Ormai ha le lacrime agli occhi. Si sfila un anello dalla mano destra e te lo preme tra le mani.>$B$BE... grazie, $N.",
  obj = "Porta l'anello di Sarah Ladimore alla tomba di Morgan Ladimore.",
  progress = "Lasciami in pace...",
  reward = "<Una voce spettrale risuona nel vento...>$B$BQuesto è...? Sarah? Possibile che sia ancora viva? Mi si è tolto un peso dalle spalle...$B$B$N. Prendi la mia spada, Archeus. Ora che la mia anima trova riposo non mi serve più. È stata forgiata per fare il bene: io mi sono dimostrato indegno di impugnarla, ma forse tu, con essa, porterai avanti la Luce. E tieni l'anello. Non ne sono più degno.$B$BLys, amore mio...",
  en_title = "A Daughter's Love",
  en_obj = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.",
}
T[232] = {
  title = "Commissione per Apothecary Zinge",
  desc = "La Royal Apothecary Society ha bisogno del tuo aiuto. Ascoltami bene e dal mio piano potremmo guadagnarci tutti e due.$B$BApothecary Keever, nella stanza accanto, sarà anche... toccato... ma se un ricercatore abile portasse avanti le sue ricerche, potrebbero dare frutti. E per fortuna io lo sono. Voglio che porti questo ordine d'acquisto ad Alessandro Luca, il proprietario di Blue Moon Odds and Ends: ti darà un kit per le analisi. Quando l'avrai, riportamelo e ti spiegherò il compito nei dettagli.",
  obj = "Porta l'ordine d'acquisto ad Alessandro Luca nell'Undercity.",
  progress = "Sì, in cosa posso esserti utile? Sei qui per affari della Royal Apothecary Society o sei $Gvenuto:venuta; solo a rallegrarmi la giornata?",
  reward = "Ah, a Zinge serve un kit, eh? Mi rattrista che Zinge non voglia onorarmi della sua dolce presenza.$B$BMolto bene, lascia che te ne procuri uno.",
}
T[238] = {
  title = "Commissione per Apothecary Zinge",
  desc = "Il kit è pronto, $N. Apothecary Zinge lo vorrà di sicuro al più presto: portaglielo subito e dille che ne aggiungerò il costo al conto dell'Ordine. E porgile i miei più calorosi saluti.$B$BBe', non startene lì $Gimpalato:impalata;. È questa la vita di un semplice corriere, vero?",
  obj = "Porta il Kit per Campionamento sul Campo ad Apothecary Zinge nell'Undercity.",
  progress = "Sì, anch'io trovo Luca inquietante quanto te. Non importa — dammi il kit per campionamento sul campo. Devo modificarlo un po' per cercare i materiali di base giusti.$B$BCe l'hai, il kit, vero?",
  reward = "Bene — è un piacere lavorare con qualcuno che si fa un vanto di non farmi perdere tempo.$B$BUna volta modificato il kit, sarai $Gpronto:pronta; a partire per il lavoro sul campo, e lo userai per raccogliere dati fondamentali per il compito che ci aspetta.$B$BMi serve solo un momento per finire le modifiche. Intanto faresti bene a cominciare a pensare a cosa portarti nel deserto.$B$BSì, ho detto il deserto.",
}
T[243] = {
  title = "Sul Campo",
  desc = "Andrai nel deserto di Tanaris a verificare la consistenza dei tessuti dei basilischi, degli scorpidi e delle iene che lo abitano. Procurati dei campioni di tessuto e usali con il kit per le analisi che hai con te, ma aspettati che una buona parte non vada bene. Mi servono otto campioni validi per ogni tipo di creatura.$B$BInoltre, i goblin di Gadgetzan hanno una fonte energetica che va usata con un kit modificato come questo. Parla con Chief Engineer Bilgewhizzle e procurane una per il kit.$B$BTorna da me solo quando ci sarai $Griuscito:riuscita;.",
  obj = "Parla con Chief Engineer Bilgewhizzle a Gadgetzan per avere una fonte energetica per il kit per le analisi.",
  reward = "Ah, le nostre model 4711-FTZ power sources! Di solito ci alimentiamo i pozzi d'acqua, ma GRAZIE A QUEI VILI NOMADI, adesso ce ne avanzano.$B$BCerto, posso procurartene una per qualunque losco esperimento scientifico tu creda di tenermi nascosto. Però non sarà mica gratis, $R. A Gadgetzan niente è gratis.",
}
T[245] = {
  title = "Minacce a Otto Zampe",
  desc = "Salute, $C. Per caso hai visto i ragni che hanno invaso il confine occidentale? Quelle minacce a otto zampe sono troppo per noi, e il Comandante non ha uomini a sufficienza da mandare così lontano da Darkshire.$B$BMi spiace chiedertelo, ma sembri in grado di affrontarli. Non posso prometterti niente di gran valore, però, se mi aiuti a sterminare quegli insetti schifosi, una ricompensa posso dartela.$B$BAh, un consiglio: se puoi, cerca di stare alla larga dal loro veleno.",
  obj = "Uccidi 15 Pygmy Venom Web Spiders, poi fai rapporto a Watcher Dodds a Duskwood.",
  progress = "Con i ragni faresti meglio a stare $Gattento:attenta;: ho perso alcuni dei miei uomini per colpa loro e, credimi, vedere un uomo appeso a testa in giù nelle loro ragnatele, dopo che il veleno ha cominciato ad ammorbidirlo, non è un bello spettacolo.$B$BNon vorrei che uno di quegli insetti ti mangiasse per pranzo.",
  reward = "Ah! Sei $Gtornato:tornata;. E nemmeno troppo $Gmalconcio:malconcia;, a quanto vedo. Certo, $N, la Night Watch ti è grata per il lavoro. Ti avevo promesso una ricompensa: eccola.",
  en_title = "Eight-Legged Menaces",
  en_obj = "Kill 15 Pygmy Venom Web Spiders, and then report back to Watcher Dodds in Duskwood.",
}
T[247] = {
  title = "La Caccia Completata",
  reward = "$N, hai ucciso tutte e tre le bestie della Caccia di Ashenvale e mi hai portato prove sufficienti della loro morte: non ci sono dubbi sulla tua forza né sulla tua tenacia. Nelle vene ti scorre il sangue di un cacciatore, e meriti di essere $Glodato:lodata;!$B$BTi prego, accetta questo ninnolo: è il mio modo di congratularmi per le grandi imprese che oggi hai compiuto ad Ashenvale per l'Orda. Che i tuoi antenati veglino su di te!",
  en_title = "The Hunt Completed",
}
T[248] = {
  title = "Uno Sguardo Più Lontano",
  desc = "Ho tenuto d'occhio la Tower of Ilgalar e percepisco che Morganth è in lotta con gli Orchi dello Stonewatch Keep. Non conosco il motivo della loro contesa, ma puoi aiutarmi a svelare questo mistero.$B$BPrendi un altro Glyph of Azora e sali in cima alla torre di guardia intatta accanto allo Stonewatch Keep.$B$BTrova un oggetto adatto su cui posare il Glifo. Un forziere o una giara — un posto dove il glifo passi inosservato — farà al caso mio.",
  obj = "Sali in cima alla torre di guardia intatta accanto a Stonewatch Keep.$B$BTrova un contenitore adatto in cui mettere il Glyph of Azora.",
  progress = "Questa giara un tempo conteneva un liquore maleodorante, ma ora giace vuota e dimenticata su un paio di barili.",
  reward = "È un recipiente adatto per il Glyph of Azora: permetterà a Theocritus di scrutare nella mente di chi si trova nello Stonewatch Keep.",
  en_title = "Looking Further",
  en_obj = "Climb the intact watch tower beside Stonewatch Keep.$B$BFind a suitable container to place the Glyph of Azora.",
}
T[249] = {
  title = "Morganth",
  desc = "Ho osservato a lungo, e alla fine ho scoperto i piani di Morganth.$B$BCerca la Falce di Elune... e forse l'ha trovata! Se è così, presto le Redridge Mountains e il regno di Stormwind ne sentiranno la potenza oscura.$B$BCon Morganth non sono in grado di misurarmi, ma temo che bisogni occuparsene subito. Per questo devi entrare tu nella Tower of Ilgalar e affrontare Morganth.$B$BSconfiggilo e portami il suo Pendant of Shadow: se ci riesci, il regno avrà con te un grande debito.",
  obj = "Sconfiggi Morganth.$B$BPorta il suo Pendant of Shadow a Theocritus, a Tower of Azora, in Elwynn Forest.",
  progress = "Presto, $N, prima che Morganth estenda il suo potere e i miei timori si avverino!",
  reward = "Ben fatto, $N. Hai sconfitto lo stregone Morganth e così hai salvato Stormwind da un grave pericolo.$B$BAccetta questa ricompensa, che ti offro con grande umiltà. Ti augurerei pace, se questi fossero tempi di pace.$B$BE invece ti auguro fortuna nelle prove e vittoria nei conflitti che verranno.",
  en_title = "Morganth",
  en_obj = "Defeat Morganth.$B$BBring his Pendant of Shadow to Theocritus at the Tower of Azora in Elwynn Forest.",
}
T[251] = {
  title = "Traduci il Biglietto di Abercrombie",
  desc = "Porta il biglietto che mi hai dato a Sirra Von'Indi. È un esperto di lingue e arti antiche — se qui c'è qualcuno in grado di tradurre questo messaggio, è lui.",
  obj = "Porta la Letter to Ello a Sirra Von'Indi.",
  progress = "Un biglietto da parte dell'eremita Abercrombie, eh? Non lo conosco, ma se vive laggiù al cimitero, allora so per certo che gli è marcito il cervello!",
  reward = "<Sirra comincia a tradurre il biglietto...>",
  en_title = "Translate Abercrombie's Note",
  en_obj = "Bring the Letter to Ello to Sirra Von'Indi.",
}
T[252] = {
  title = "Traduzione per Ello",
  desc = "Santo cielo! Se quello che dice questa lettera è vero, Abercrombie ha fatto qualcosa...di indicibile.$B$BÈ meglio che tu riporti la lettera tradotta a Ello.$B$BE fai presto, perché temo che una sciagura si stia già avvicinando a passi pesanti alla nostra città...",
  obj = "Porta la Translated Letter a Lord Ello Ebonlocke",
  progress = "Ah, la lettera è stata tradotta? Fammela vedere, ti prego...",
  reward = "<Ello legge la lettera...e impallidisce. Poi ti guarda...>$B$BForse hai aiutato Abercrombie per gentilezza, ma con le tue azioni hai condannato la nostra città.$B$B<Ello si perde nei pensieri...>",
  en_title = "Translation to Ello",
  en_obj = "Bring the Translated Letter to Lord Ello Ebonlocke",
}
T[253] = {
  title = "La Sposa dell'Imbalsamatore",
  desc = "In una delle storie che raccontiamo ai nostri bambini compare un nome: l'Imbalsamatore. Era un alchimista gentile, che la morte della moglie, Eliza, ha fatto impazzire. Per riportarla indietro è ricorso alla magia oscura e ha messo il suo stesso cuore nel petto della sposa morta.$B$BCosì Eliza è tornata in vita... ma con addosso la maledizione di una fame di carne umana, e l'Imbalsamatore non ha avuto altra scelta che tenerla sepolta.$B$BIl suo cuore è il suo potere. Trova la tomba della moglie, prendi il cuore e portamelo mentre batte ancora. Così il suo potere sarà spezzato.",
  obj = "Trova la tomba di Eliza. Recupera the Embalmer's Heart da lei, poi torna da Ello Ebonlocke.",
  progress = "Hai già trovato la tomba di Eliza? E the Embalmer's heart, ce l'hai?",
  reward = "Ce l'hai fatta! La magia del suo cuore ci proteggerà dal male dell'Imbalsamatore e stenderà sulla città di Darkshire una potente egida.$B$BPer la nostra gente hai fatto una grande cosa, $N. Il tuo nome resterà per sempre nei nostri annali.",
  en_title = "Bride of the Embalmer",
  en_obj = "Find Eliza's grave.  Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke.",
}
T[254] = {
  title = "Scavando nella Terra",
  reward = "Scavi nella terra mezza smossa sopra la tomba... e trovi i resti di una bara.$B$BDentro la bara senti i graffi vibranti di dita artigliate e il digrignare di denti marci...$B$BVuoi aprire la bara e prendere the Embalmer's heart?",
  en_title = "Digging Through the Dirt",
}
T[261] = {
  title = "Lungo il Sentiero Scarlatto",
  desc = "Sarò franco: siamo in guerra con lo Scourge, un male che corrompe la nostra gente e infetta la nostra terra. Dobbiamo fermarlo prima che ci sopraffaccia e trascini il nostro mondo nell'ombra. Noi della Scarlet Crusade abbiamo giurato di combattere lo Scourge anima e corpo.$B$BSe sei con noi, fatti coraggio e dimostraci la tua lealtà — distruggi gli undead ravagers di Desolace, giù nella Valley of Bones, a sud.$B$BSe lo farai, la Crociata ti accoglierà a braccia aperte.",
  obj = "Distruggi 30 Undead Ravagers, poi torna da Brother Anton a Nijel's Point.",
  progress = "Ogni giorno che passa lo Scourge si fa più potente. Se vuoi davvero fermarne l'avanzata, dimostramelo.",
  reward = "Hai dato prova della tua determinazione, e la Scarlet Crusade ti elogia.$B$BSe una giusta strage non ti fa tirare indietro, forse la tua strada è con noi...",
  en_title = "Down the Scarlet Path",
  en_obj = "Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point.",
}
T[262] = {
  title = "La Figura nell'Ombra",
  desc = "Devo sapere chi era la figura che si aggirava nell'ombra la notte in cui hanno ucciso la mia famiglia!$B$BTi prego, $N, hai dimostrato di essere $Gpieno:piena; di risorse. Trova quella figura nell'ombra, ti supplico. Devo scoprire quali segreti nasconde!$B$BNon ho indizi che tu non conosca già, ma ecco — prendi il libro che hai trovato alla mia fattoria. Forse qualcuno in paese saprà dirti di chi è.",
  obj = "Prendi il libro che hai trovato alla fattoria di Sven e mostralo agli abitanti di Darkshire.",
  progress = "Se hai qualcosa che appartiene alla figura nell'ombra che stai cercando, fammelo vedere. Forse riuscirò a scorgere qualcosa sul proprietario.",
  reward = "Mmm... Qualcuno ha maneggiato questo libro di recente, qualcuno spinto dalla vendetta. Ma le tracce che vi sono rimaste, almeno quelle del primo proprietario, sono deboli.$B$BPosso dirti, però, che chi l'ha posseduto per primo non è nativo di Darkshire.",
  en_title = "The Shadowy Figure",
  en_obj = "Take the book you found at Sven's farm and show it to townsfolk in Darkshire.",
}
T[265] = {
  title = "La Ricerca nell'Ombra Prosegue",
  desc = "Ecco il tuo libro, $N, e buona fortuna con la ricerca. Se chiedi in giro per il paese, forse qualcuno potrà darti altri indizi.$B$BEd ecco un altro indizio per te — anche se l'autore di questo libro non è di Darkshire, il volume è stato comprato qui.",
  obj = "Scopri se altri abitanti del paese hanno indizi sulla figura nell'ombra.",
  progress = "A volte vendo libri dalle pagine bianche a studiosi e maghi, o a chiunque voglia tenere un diario.$B$BMi ricordo bene di tutti quelli che me ne hanno comprato uno negli ultimi mesi...",
  reward = "Ah, sì. Ho venduto questo libro un mese fa a un individuo losco. Non mi ha detto come si chiamava, ma era un tipo nervoso, agitato, che si guardava sempre alle spalle.$B$BSpero che ti sia d'aiuto...",
  en_title = "The Shadowy Search Continues",
  en_obj = "See if other townsfolk have clues about the shadowy figure.",
}
T[266] = {
  title = "Indaga alla Locanda",
  desc = "Ecco il tuo libro, e buona fortuna con le indagini.$B$BPotresti allargare la ricerca alla locanda. Se la persona che cerchi si è fermata in paese, è probabile che qualcuno l'abbia vista tra i suoi tavoli.",
  obj = "Cerca indizi sulla figura nell'ombra alla locanda.",
  progress = "La Scarlet Raven non lavora più come una volta, ma ogni tanto passa ancora qualche viaggiatore.$B$BSe mi descrivi la persona che cerchi, forse me la ricorderò.",
  reward = "Oh, sì, mi ricordo di questo libro. L'uomo a cui apparteneva ha preso una stanza per qualche giorno e passava le notti al bancone, a scrivere.$B$BSe n'è andato in fretta e furia, borbottando che era braccato da... qualcosa. L'ultima volta che l'ho visto si dirigeva a ovest, fuori dal paese, in cerca di un nuovo nascondiglio.$B$BIl primo posto che incontrerebbe da quella parte è Raven Hill...",
  en_title = "Inquire at the Inn",
  en_obj = "Search the inn for clues about the shadowy figure.",
}
T[268] = {
  title = "Ritorno da Sven",
  desc = "Il libro che hai trovato era scritto solo a metà. Ho dovuto lasciarlo alla fattoria di Sven quando sono fuggito di lì...$B$BEcco. Porta il mio diario completo a Sven. Il diario racconta più nel dettaglio cosa è successo a casa sua.$B$BÈ stato la mia unica compagnia nelle ultime settimane, ma se cederlo mi evita di dover affrontare Sven e la sua collera, lo faccio volentieri!",
  obj = "Torna da Sven con il diario completo di Jitters.",
  progress = "Hai scoperto chi era la Figura nell'Ombra?",
  reward = "Questo diario mi chiarisce molte cose, e mi mette sulla strada giusta per combattere i cavalieri oscuri! Li ho avvistati a Duskwood, e li ho visti parlare con il mago Morbent Fel, a Forlorn Rowe.",
  en_title = "Return to Sven",
  en_obj = "Return to Sven with Jitters' completed journal.",
}
T[269] = {
  title = "In Cerca di Saggezza",
  desc = "Vai nella città di Stormwind e parla con Bishop Farthing nella Cathedral of Light. Dagli il diario di Jitters e digli che intendi affrontare Morbent Fel.$B$BAnche se Stormwind ha abbandonato Darkshire, Farthing è un animo gentile e molto saggio. Potrebbe aiutarti nella tua missione per salvarci.$B$BLa tua impresa è pericolosa, ma sbrigati, $N. A ogni ora che passa, le ombre di Duskwood si fanno sempre più fitte.",
  obj = "Consegna il Jitters' Completed Journal a Bishop Farthing a Stormwind.",
  progress = "Riposa, $Gfratello:sorella;. Vedo che hai viaggiato a lungo e che porti un pesante fardello. Puoi dirmi da dove viene l'ombra oscura che ti grava addosso?",
  reward = "<Dopo aver letto il diario e ascoltato le tue intenzioni...>$B$BUna corruzione malvagia ha messo radici nella già tormentata Duskwood. Ringrazio la Luce che ci sia $Gun eroe:un'eroina; come te ad affrontare questo male.$B$BMa prima devi prepararti alla prova che ti attende... perché il Necromancer Morbent Fel è immensamente potente e si è circondato di oscuri incantesimi che lo proteggono dagli attacchi fisici. Se vuoi sconfiggerlo, ti servirà un'arma contro cui queste protezioni non possano nulla.",
  en_title = "Seeking Wisdom",
  en_obj = "Give Jitters' Completed Journal to Bishop Farthing in Stormwind.",
}
T[270] = {
  title = "La Doomed Fleet",
  desc = "Anni fa la Third Fleet of Kul'Tiras è affondata lungo le coste delle Wetlands, una distesa di paludi a nord del regno Nanico di Ironforge. A bordo di una delle navi c'era un carico di Lightforge Iron.$B$BPer noi questo metallo è prezioso, perché gli oggetti che se ne ricavano colpiscono con la verità sacra. Se devi affrontare Morbent Fel, ti servirà un'arma del genere.$B$BVai a Menethil Harbor e parla con il mio collega nano Glorin Steelbrow. Se quel metallo perduto si può ritrovare, lui saprà dove cercare.",
  obj = "Vai a Menethil Harbor, in Wetlands, e parla con Glorin Steelbrow.",
  reward = "Il Lightforge Iron è un metallo prezioso, ma pare che la tua missione sia della massima urgenza. Hai fatto tanta strada, $GFratello:Sorella;. Con un po' di fortuna, potresti proprio trovare quello che cerchi!$B$BE se riesci a procurarti il ferro, conosco qualcuno che può ricavarne un'arma contro quel Negromante di Duskwood di cui parli.",
  en_title = "The Doomed Fleet",
  en_obj = "Go to Menethil Harbor in the Wetlands, and speak with Glorin Steelbrow.",
}
T[272] = {
  title = "Prova del Leone Marino",
  desc = "Per la seconda prova ti serviranno le due metà che compongono il Pendant of the Sea Lion. Una metà trae potere dall'agilità dell'aspetto del leone marino, che scivola nell'acqua; l'altra dalla sua incredibile resistenza. Per incarnare l'aspetto della forma acquatica, i druidi attingono in egual misura a tutte e due le qualità.$B$BChiedi agli abitanti di Moonglade dove potrebbero trovarsi le parti, e portale qui entrambe per unirle. Una volta composto il pendente, consegnalo a Dendrite Starblaze.",
  obj = "Trova l'Half Pendant of Aquatic Agility e l'Half Pendant of Aquatic Endurance. Parla con gli abitanti di Moonglade per avere indizi su dove possano trovarsi questi oggetti.$B$BComponi il Pendant of the Sea Lion con le due metà del pendente. Per farlo devi trovarti nei pressi di Shrine of Remulos.$B$BPorta il pendente completo a Dendrite Starblaze nel villaggio di Nighthaven, Moonglade.",
  progress = "Hai composto il pendente da farmi esaminare, $N? Se ti serve aiuto per trovare le parti, prova a chiedere informazioni alla gente del posto. Non solo troverai ciò che cerchi, ma avrai anche un motivo per esplorare questa radura meravigliosa e sacra.",
  reward = "Hai superato la Prova del Leone Marino, $N — congratulazioni.$B$BOgni passo compiuto per ottenere il pendente dimostra che servono sia l'agilità sia la resistenza perché, sott'acqua, il corpo assecondi ciò che vuoi fare. L'una non può esistere senza l'altra, e nessuna delle due si ottiene senza che tu sia $Gdisposto:disposta; ad accogliere in te l'aspetto del leone marino.$B$BRicorda bene queste lezioni, e affidati a esse una volta ottenuta la forma acquatica.",
  en_title = "Trial of the Sea Lion",
  en_obj = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.$B$BForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.$B$BBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[275] = {
  title = "Vesciche sulla Terra",
  desc = "Non so perché, ma nelle Wetlands cresce un'infezione. Sono sorte delle Fen Creepers: vesciche malate e febbricitanti sulla terra. Per far scendere la febbre bisogna eliminarle e lasciarle sprofondare di nuovo nelle paludi.$B$BTra i corsi d'acqua delle Wetlands si trascinano le Fen Creepers.",
  obj = "Uccidi 12 Fen Creepers, poi torna da Rethiel the Greenwarden in Wetlands.",
  progress = "Le Wetlands piangono ancora e le Fen Creepers sono sempre furiose. Torna da me quando avrai finito.",
  reward = "Grazie ai tuoi sforzi questa terra trova sollievo, e per questo ti concederò un dono.",
  en_title = "Blisters on The Land",
  en_obj = "Kill 8 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands.",
}
T[276] = {
  title = "Zampe che Calpestano",
  desc = "Da molti anni i Mosshide Gnolls vivono in pace nelle Wetlands, ma ora sono sempre di più. Calpestano i cespugli e i fiori della palude, e con le loro asce immonde tagliano troppa legna per alimentare i fuochi.$B$BNon sono più in equilibrio con la terra. Perché le Wetlands sopravvivano, gli Gnolls devono essere di meno.$B$BUccidi 15 Mosshide Gnolls e 10 Mosshide Mongrels: dagli la caccia a sud, vicino alla porta Nanica di Algaz. Poi torna da me.",
  obj = "Uccidi 15 Mosshide Gnolls e 10 Mosshide Mongrels, poi torna da Rethiel the Greenwarden in Wetlands.",
  progress = "Non hai ancora finito il tuo compito, giovane $C.",
  reward = "Hai ridotto il numero degli gnolls, e così ti sei $Gpreso:presa; cura della salute delle Wetlands. In passato la tua gente ha messo a dura prova la mia fiducia, $R, ma potrei ancora ritrovarla.",
  en_title = "Tramping Paws",
  en_obj = "Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands.",
}
T[277] = {
  title = "Tabù del Fuoco",
  desc = "I Mosshide tagliano gli alberi delle Wetlands e ne bruciano la carne per scaldarsi. Non sopporterò più questo dolore!$B$BTogli ai Mosshide le crude flints, gli strumenti con cui accendono il fuoco. Le portano tutti, tranne gli gnolls Mosshide più piccoli e i meticci Mosshide.",
  obj = "Porta a Rethiel the Greenwarden 9 Crude Flints.",
  progress = "Hai con te gli strumenti degli Gnolls per accendere il fuoco?",
  reward = "... grazie. Spaccherò queste pietre focaie e le getterò in mare, così nessuno potrà mai più usarle per bruciare il legno vivo.",
  en_title = "Fire Taboo",
  en_obj = "Bring Rethiel the Greenwarden 9 Crude Flints.",
}
T[279] = {
  title = "Artigli dagli Abissi",
  desc = "I Murlocs strisciano fuori dalle acque profonde e costruiscono villaggi lungo la costa. Molestano i nostri pescatori e i nostri mercanti: bisogna fermarli.$B$BUno di questi Murlocs, Gobbler, se ne va in giro di soppiatto con altri Bluegill Murlocs a tormentare i mercanti sulla strada. Poi torna sempre a ripararsi nelle capanne dei Murlocs qui vicino. I nostri mercanti sono in pericolo, e siamo disposti a pagare per proteggerli.$B$BGobbler si aggira nell'insenatura del fiume, a nord di qui. Trovalo, uccidi i suoi simili e portami la sua testa.",
  obj = "Uccidi 12 Bluegill Murlocs.$B$BUccidi Gobbler e prendine la testa.$B$BPorta la Gobbler's Head a Karl Boran a Menethil Harbor.",
  progress = "Finché non ci saremo sbarazzati di Gobbler e di quei Murlocs, i nostri mercanti non saranno al sicuro.",
  reward = "Ah, ben fatto, $N.$B$BHai rispettato il contratto con la Marina Mercantile: accetta questo compenso.",
  en_title = "Claws from the Deep",
  en_obj = "Kill 12 Bluegill Murlocs.$B$BSlay Gobbler and take his head.$B$BBring Gobbler's Head to Karl Boran in Menethil Harbor.",
}
T[281] = {
  title = "Recuperare la Merce",
  desc = "Non molto tempo fa i Murlocs hanno assaltato una nave mercantile, la Blind Princess. La nave è riuscita a fuggire intatta, ma quelle creature hanno trascinato in mare gran parte del carico, tra cui una preziosissima statuetta di Terenas Menethil. Vogliamo riaverla.$B$BPerquisisci le capanne dei Murlocs sulla costa e cerca casse, barili e ogni altra traccia del carico perduto. Trova la Menethil Statuette e riportamela.",
  obj = "Perquisisci le casse e i barili negli accampamenti dei Murlocs sulla costa.",
  reward = "Questa cassa è coperta di graffi d'artigli e dei segni lasciati dall'acqua. La apri con una leva: dentro c'è paglia fradicia e marcita, come se ci avessero riposto qualcosa di valore. Frughi nella paglia...$B$B...e trovi una bracciata di bottiglie rosse.",
  en_title = "Reclaiming Goods",
  en_obj = "Search the crates and barrels at the coastal Murloc camps.",
}
T[284] = {
  title = "La Ricerca Continua",
  desc = "Perquisisci da cima a fondo questo gruppo di capanne dei Murlocs, ma della Menethil Statuette non c'è traccia.$B$BForse troverai altri indizi in una delle due capanne vicine, a nord e a nordest.",
  obj = "Cerca la Menethil Statuette.",
  reward = "Questo barile è quasi intatto. Lo apri con una leva...$B$B...e vieni $Gassalito:assalita; da un pungente odore di formaggio. È un po' bagnato, ma ancora gustoso!",
  en_title = "The Search Continues",
  en_obj = "Search for the Menethil Statuette.",
}
T[285] = {
  title = "Perquisisci Altre Capanne",
  desc = "Ispezioni con cura questo gruppo di capanne dei Murlocs, ma non trovi niente.$B$B...eppure sei $Gsicuro:sicura; che il prossimo indizio sarà quello buono.$B$BLa Menethil Statuette deve trovarsi in una delle capanne a nord!",
  obj = "Continua a cercare la Menethil Statuette nelle capanne dei Murlocs.",
  reward = "Questo barile è mezzo sepolto nel fango e nell'erba...",
  en_title = "Search More Hovels",
  en_obj = "Continue searching the Murloc hovels for the Menethil Statuette.",
}
T[286] = {
  title = "Riporta la Statuetta",
  desc = "Liberi il barile dalla melma e lo apri: dentro, avvolta nella paglia fine, c'è una statuina argentea. Raffigura un giovane Paladino dai capelli lunghi, con il martello sollevato.$B$BQuesta dev'essere la Menethil Statuette! Adesso devi riportarla a Karl Boran, a Menethil Harbor.",
  obj = "Porta la Menethil Statuette a Karl Boran.",
  progress = "Ce l'hai, la statuetta?",
  reward = "Il capitano della Blind Princess sarà sollevato di sapere che questo prezioso carico è stato recuperato. Per i servigi che hai reso, ti sei proprio $Gguadagnato:guadagnata; questa ricompensa.$B$BFa piacere trovare gente affidabile come te, specie in tempi così difficili.",
  en_title = "Return the Statuette",
  en_obj = "Bring Karl Boran the Menethil Statuette.",
}
T[288] = {
  title = "La Terza Flotta",
  desc = "Un tempo ero Primo Ufficiale sulla Wave Mistress, vascello di linea della Kul Tiras Third Fleet. La Doomed Fleet. Condannata perché, nel suo ultimo viaggio, l'hanno attaccata i Red Dragons. E quei draghi li controllavano gli Orchi!$B$BContro il fuoco di drago non avevamo scampo... la nostra flotta è stata bruciata e affondata qui al largo. Di quelle povere navi sono rimasto vivo solo io...$B$B...Oh, la testa mi martella e mi rimbomba! Se voglio smaltire la sbornia e andare avanti col racconto, mi serve un altro bicchiere.",
  obj = "Offri un Boccale di Idromele a First Mate Fitzsimmons.",
  progress = "Oh, che sete! Non offriresti da bere a questo povero, patetico sciocco?",
  reward = "Ah! Proprio quello che ci voleva, e scioglie la lingua. Grazie, $Gamico:amica;!",
  en_title = "The Third Fleet",
  en_obj = "Buy First Mate Fitzsimmons a Flagon of Mead.",
}
T[289] = {
  title = "La Ciurma Maledetta",
  desc = "<Rinfrancato, Fitzsimmons riprende il racconto...>$B$BSono l'unico sopravvissuto della sfortunata Third Fleet of Kul Tiras, che è naufragata al largo della costa a nord. Ma se della flotta sono l'unico che respira ancora, non sono l'unico che se ne va in giro! Perché su una delle nostre navi c'era nascosto un tesoro grande e terribile, e il suo potere sinistro tiene le anime dei miei fratelli intrappolate negli scafi marci.$B$BSe però riesci a liberarne qualcuno, forse potrai spezzare la loro maledizione.",
  obj = "Uccidi 13 Cursed Sailors, 5 Cursed Marines e First Mate Snellig. Porta la Snellig's Snuffbox a First Mate Fitzsimmons a Menethil Harbor.",
  progress = "A volte, in sogno, sento i lamenti dei miei fratelli condannati! Ti prego, $Gbuon signore:buona signora;, liberali dalle catene e placa le loro grida.",
  reward = "Ti ringrazio, $N, e con me ti ringraziano anche i miei fratelli maledetti.",
  en_title = "The Cursed Crew",
  en_obj = "Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig.  Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor.",
}
T[290] = {
  title = "Spezzare la Maledizione",
  desc = "Per spezzare la maledizione e liberare tutti i miei fratelli bisogna recuperare e purificare quella... cosa... stivata sulla mia nave! Cosa fosse non lo so, ma so che la tenevano al sicuro nel forziere di bordo, che Captain Halyndor custodiva gelosamente.$B$BIl mio vecchio capitano mi compare ancora in sogno, e so che si aggira sulla mia nave condannata, l'Intrepid. Prendigli la chiave e con quella apri il forziere dell'Intrepid.$B$BPoi, quando avrai la cosa maledetta, portala al sacerdote Glorin Steelbrow, in città.",
  obj = "Prendi l'Intrepid Strongbox Key da Captain Halyndor.$B$BUsa la chiave per aprire l'Intrepid's Locked Strongbox.",
  progress = "Questa cassa è chiusa a chiave, e per bene.",
  reward = "La chiave è arrugginita, ma nella serratura entra alla perfezione.",
  en_title = "Lifting the Curse",
  en_obj = "Get the Intrepid Strongbox Key from Captain Halyndor.$B$BUse the key to open the Intrepid's Locked Strongbox.",
}
T[292] = {
  title = "L'Eye of Paleth",
  desc = "Apri la cassa e dentro trovi una sfera annerita, che pulsa di una luce sinistra: è il tesoro di cui parlava Fitzsimmons, un Cursed Eye of Paleth.$B$BPorta il Cursed Eye of Paleth al sacerdote nanico Glorin Steelbrow, a Menethil Harbor, e chiedigli come togliere la maledizione dall'Occhio.",
  obj = "Porta il Cursed Eye of Paleth a Glorin Steelbrow.",
  progress = "È stato quell'ubriacone di Fitzsimmons a mandarti da me? Beh, digli pure che birra in più non ne ho. Dovrà andare a elemosinarla da qualcun altro!",
  reward = "Un Eye of Paleth? Incredibile! Mmm... però qui c'è qualcosa che non va. L'hai trovato in uno di quei relitti? Beh, allora si spiega tutto! Ma... non sapevo che la Terza Flotta avesse un Occhio del genere...$B$BNon c'è da stupirsi se Fitzsimmons era così spaventato. Con un Cursed Eye of Paleth c'è poco da stare allegri.",
  en_title = "The Eye of Paleth",
  en_obj = "Bring the Cursed Eye of Paleth to Glorin Steelbrow.",
}
T[293] = {
  title = "Purificare l'Occhio",
  desc = "Io la maledizione dall'Eye of Paleth non posso toglierla. Gli Occhi li hanno fatti i Sacerdoti Umani, quindi l'aiuto dovrai cercarlo a Stormwind. Parla con Archbishop Benedictus, che è a capo della Cathedral of Light, a Stormwind. Lui può aiutarti.$B$BLo spero, per il tuo bene.",
  obj = "Porta il Cursed Eye of Paleth ad Archbishop Benedictus. Benedictus si trova nella Cathedral of Light, nella città di Stormwind.",
  progress = "Cos'è quella sfera che porti? Sembra... sporca.",
  reward = "Un Eye of Paleth. Ma questo ha visto molto dolore... dev'essere stato testimone di una terribile, terribile tragedia.$B$BLascia che lo purifichi: gli Occhi sono stati creati per risplendere, e quando sono contaminati come questo i loro poteri possono essere molto pericolosi.",
  en_title = "Cleansing the Eye",
  en_obj = "Bring Archbishop Benedictus the Cursed Eye of Paleth.  Benedictus is in the Cathedral of Light, in the city of Stormwind.",
}
T[294] = {
  title = "La Vendetta di Ormer",
  desc = "È una situazione grave, non c'è dubbio. Scavando queste ossa abbiamo attirato i Raptors, e quelle luride bestie hanno ucciso i miei fratelli e hanno intrappolato quassù me, Merrin e il povero Prospettore.$B$BDammi una mano a ripulire le Wetlands da questi Raptors, $N. Appena a Ovest di quella scarpata trovi i Mottled Raptors e i Mottled Screechers: se ce la fai, uccidine 10 per tipo.$B$BPer la vendetta che gli tengo in serbo sarà un buon inizio.",
  obj = "Ormer Ironbraid, a Whelgar Excavation Site, vuole che tu uccida 10 Mottled Screechers e 10 Mottled Raptors.",
  progress = "$N, uccidi 10 Mottled Raptors e 10 Mottled Screechers. I miei compagni di lavoro non meritavano di fare quella fine, ed è ora di pareggiare i conti.",
  reward = "Uccidere è una faccenda sporca, $N, ma tu hai fatto bene il tuo lavoro. Se non dovessi restare con il Prospettore e Merrin, sarei laggiù a versare sangue al tuo fianco.",
  en_title = "Ormer's Revenge",
  en_obj = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors.",
}
T[295] = {
  title = "La Vendetta di Ormer",
  desc = "Adesso è ora di far pentire sul serio quei temuti Raptors della loro sete di sangue. Proprio qui sotto ce ne sono decine, di Mottled Scytheclaws e Mottled Razormaws: uccidine 10 per tipo e fagliela pagare, a quelle creature schifose!",
  obj = "Ormer Ironbraid vuole che tu uccida 10 raptors Mottled Scytheclaw e 10 Mottled Razormaw, poi torni da lui a Whelgar Excavation Site.",
  progress = "Voglio che quei Mottled Scytheclaws e Mottled Razormaws paghino per quello che hanno fatto. Ne hai già uccisi 10 per tipo?",
  reward = "Hai ripulito la zona da quei Raptors, $N: un lavoro coi fiocchi!",
  en_title = "Ormer's Revenge",
  en_obj = "Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site.",
}
T[296] = {
  title = "La Vendetta di Ormer",
  desc = "Mentre eri laggiù ho notato una di quelle bestie che spiccava sulle altre, un esemplare più grosso e più minaccioso. Scommetto che è lui che le ha guidate fin qui a disturbare gli scavi.$B$BHo un ultimo compito per te, $N: fa' in modo che Sarltooth venga consegnato alla giustizia. E visto quanto sono gravi i suoi crimini, stavolta giustizia vuol dire morte! Come prova, portami uno dei suoi artigli.",
  obj = "Ormer Ironbraid, a Whelgar Excavation Site, vuole che tu uccida Sarltooth e torni da lui con uno dei suoi artigli una volta portato a termine il compito.",
  progress = "Sarltooth è morto? Hai riscattato la memoria dei caduti?",
  reward = "Grazie, $N. Nessuno dimenticherà quello che hai fatto qui. In questi scavi sono morti tanti Nani innocenti, che facevano solo il loro lavoro. Dopo la vendetta che hai fatto piombare su quelle creature malvagie, dovrebbero pensarci due volte prima di attaccare di nuovo i sudditi di King Magni.",
  en_title = "Ormer's Revenge",
  en_obj = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled.",
}
T[299] = {
  title = "Scoprire il Passato",
  desc = "Poco prima dell'invasione ho riportato alla luce una grande tavoletta, la Goaz Stone. La traduzione del testo si interrompe in 4 punti, ma parla di un \"piano divino\" e di una \"profezia di rovina\".$B$BHo paura che il tempo stia per scadere. Io sono troppo vecchio per scendere laggiù a vedermela con quelle bestie, ma tu sei forte.$B$BPerlustra il sito di scavo e recupera i 4 frammenti che mancano alla tavoletta: Ados, Modr, Golm e Neru. Cercali negli antichi manufatti o dove la terra è smossa, poi portameli: così potrò cominciare a svelare il mistero!",
  obj = "Prospector Whelgar vuole che tu perlustri il sito di scavo alla ricerca dei 4 frammenti mancanti della tavoletta: Ados, Modr, Golm e Neru.",
  progress = "Non hai ancora trovato i quattro frammenti, $N? Ados, Modr, Golm e Neru...",
  reward = "Ah, la Goaz Stone è completa! Ottimo lavoro, $N, davvero ottimo. Adesso posso andare avanti con la delicata traduzione di questa scrittura dei Titani, e già riesco a distinguere parole nuove! Mmh... qui c'è scritto: \"Old Gods... Incatenati Sotto la Terra.\" È l'inizio di qualcosa di epico.",
  en_title = "Uncovering the Past",
  en_obj = "Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru.",
}
T[303] = {
  title = "La Guerra dei Dark Iron",
  desc = "La guerra infuria in patria e all'estero. Mentre in territori lontani i possenti soldati Nanici danno la vita in nome dell'Alleanza, le nostre terre cadono preda delle malefatte dei Dark Iron Dwarves. Hanno devastato il Thandol Span, e poco dopo è caduta Dun Modr.$B$BCi serve che tu raduni le forze e faccia arretrare il fronte. Se riesci a uccidere 15 Dark Iron Dwarves, 5 Perforatori, 5 Saboteurs e 5 Demolitionists, la riserva potrebbe arrivare in tempo per concludere l'offensiva.$B$BOra sbrigati!",
  obj = "Motley Garmason a Dun Modr vuole che tu uccida 15 Dark Iron Dwarves, 5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs e 5 Dark Iron Demolitionists.",
  progress = "Roggo non è riuscito a mettersi in contatto con la riserva. Dobbiamo mettere sotto pressione quell'accampamento Dark Iron, $C. Ora torna là fuori e fai il tuo dovere verso King Magni!",
  reward = "Hai eseguito bene gli ordini, $C. Hai dimostrato di essere $Gun soldato valoroso:una soldatessa valorosa; e $Gun leale servitore:una leale servitrice; di King Magni, e per questo ti rendo onore! Con la pressione che hai fatto sull'accampamento Dark Iron, ora abbiamo una possibilità di cacciarli per sempre dalle nostre terre. . .se solo quella dannata riserva si facesse vedere. . . .",
  en_title = "The Dark Iron War",
  en_obj = "Motley Garmason at Dun Modr wants you to kill 10 Dark Iron Dwarves,  5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.",
}
T[304] = {
  title = "Un Compito Macabro",
  desc = "Nella battaglia di Dun Modr sono morti molti dei miei soldati, e mio fratello è perito quando è stato distrutto il West Bridge sul Thandol Span. Già, i nani Dark Iron sono una razza diabolica. Da quello che Roggo è riuscito a scoprire, a capo di questa banda di delinquenti nelle Wetlands c'è uno stregone di nome Balgaras the Foul. Un gran vigliacco, però: manda i suoi soldati a eseguire gli ordini, ma lui sfugge a tutti e si tiene alla larga dal pericolo.$B$BTrova quella feccia smidollata, se ci riesci: uccidila e portami il suo orecchio, e avrai la tua ricompensa, $C.",
  obj = "Uccidi Balgaras the Foul e porta il suo orecchio a Longbraid the Grim, fuori da Dun Modr.",
  progress = "Sei $Griuscito:riuscita; a trovare Balgaras the Foul, $C? È da parecchio tempo che ci sfugge.",
  reward = "Balgaras the Foul è morto, finalmente. Questo non riporterà in vita i tanti nani innocenti caduti inutilmente per mano sua, ma aiuterà chi è sopravvissuto a ritrovare la serenità. Senza Balgaras, la feccia Dark Iron rimasta dovrebbe essere abbastanza facile da tenere a bada. Ora dobbiamo spazzarli via prima che mandino un nuovo capo da queste parti.$B$BHai fatto un buon lavoro, $C.",
  en_title = "A Grim Task",
  en_obj = "Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr.",
}
T[305] = {
  title = "Alla Ricerca della Squadra di Scavo",
  desc = "Non sai quanto sono stato in pensiero.$B$BMia moglie Merrin lavora con la squadra del Whelgar Excavation, e da un mese mi scrive ogni settimana. Ma ormai sono quasi due settimane che non ricevo una sua lettera, e di sicuro qualcosa non va!$B$BLongbraid ha detto che, se non avessimo avuto presto notizie della squadra, avrebbe mandato un esploratore a controllare. Immagino che $Gquell'esploratore:quell'esploratrice; sia tu, $N. Va' al sito di scavo a est e trova Merrin!",
  obj = "Tarrel Rockweaver vuole che tu vada a Excavation Site e contatti Merrin Rockweaver.",
  reward = "Oh, grazie al cielo, sei qui!",
  en_title = "In Search of The Excavation Team",
  en_obj = "Tarrel Rockweaver wants you to travel to the Excavation Site and contact Merrin Rockweaver.",
}
T[306] = {
  title = "Alla Ricerca della Squadra di Scavo",
  desc = "È stato orribile! Stavamo portando alla luce dei manufatti rari, quando abbiamo cominciato a trovare delle grandi ossa.$B$BNon abbiamo fatto in tempo a capire cosa stava succedendo che questi Mottled Raptors hanno invaso il sito di scavo. In molti hanno perso la vita.$B$BOrmer, qui presente — così coraggioso — ha salvato me e il Prospettore, difendendoci mentre correvamo al riparo. Adesso siamo in trappola. E il nostro duro lavoro è andato distrutto.$B$BTieni, porta questo biglietto al mio dolce Tarrel. Gli spiegherà come stanno le cose.",
  obj = "Torna da Tarrel Rockweaver con il biglietto di Merrin.",
  progress = "Sei $Griuscito:riuscita; a trovare Merrin? Hai notizie da parte sua?",
  reward = "Che notizie orribili! Almeno 3 di loro ce l'hanno fatta. Ma quando finiranno queste uccisioni? Sogno il giorno in cui i sudditi di King Magni potranno vivere senza paura.",
  en_title = "In Search of The Excavation Team",
  en_obj = "Return to Tarrel Rockweaver with Merrin's note.",
}
T[321] = {
  title = "Lightforge Iron",
  desc = "I relitti al largo di questa costa sono quel che resta della sventurata Third Fleet of Kul'Tiras, incendiata e affondata dai Red Dragons durante l'ultima Great War.$B$BLa Flotta veniva da Lordaeron, ma con lei viaggiava anche un Destroyer Elfico: la Flying Osprey. Trasportava un carico di Lightforge Iron e si era unita alla Terza Flotta per viaggiare sotto la sua protezione. Ironia della sorte, è colata a picco per mano degli stessi draghi...$B$BBasta con la storia. Il relitto della Flying Osprey si trova a sud di Menethil Harbor. Se lì trovi il Lightforge Iron, portamelo.",
  obj = "Fruga nel relitto della Flying Osprey in Wetlands.",
  reward = "Lo scrigno è impregnato d'acqua e ha le pareti rotte. Dentro e fuori è tutto segnato da graffi di artigli... come se i Murlocs ci avessero frugato e ne avessero rubato il tesoro.$B$BMa sul fondo è rimasto un solo Lightforge Ingot. Purtroppo ne serviranno molti di più per ricavare abbastanza metallo da forgiare un'arma.",
  en_title = "Lightforge Iron",
  en_obj = "Search the wreckage of The Flying Osprey in the Wetlands.",
}
T[322] = {
  title = "Arma Benedetta",
  desc = "Nel Dwarven District of Stormwind c'è un armaiolo nano che sa lavorare il lightforge iron. Si chiama Grimand Elmore.$B$BHo messo il ferro che hai trovato in una cassa. Portala a Grimand e raccontagli la tua storia. Sono sicuro che darà una mano a chi è impegnato in un'impresa come la tua e ti forgerà un'arma — un'arma da far preoccupare persino Morbent Fel!",
  obj = "Porta la Crate of Lightforge Ingots a Grimand Elmore a Stormwind.",
  progress = "Come posso mettere la mia arte al tuo servizio, $C?",
  reward = "Hai proprio una bella storia da raccontare. E lightforge iron! Sono anni che non lavoro un metallo del genere. Sarà un onore tornare a forgiarlo. E dopo dovrai venire a raccontarmi com'è andata la battaglia contro il Negromante.$B$BMa non perdiamoci in chiacchiere. Prima, la tua arma contro Morbent Fel...",
  en_title = "Blessed Arm",
  en_obj = "Take the Crate of Lightforge Ingots to Grimand Elmore in Stormwind.",
}
T[323] = {
  title = "Dimostra il Tuo Valore",
  desc = "Morbent Fel è un negromante, alleato dei cavalieri oscuri. Vorrei che fossi tu a sfidare il suo potere, ma non ti manderò contro quel turpe demonio senza aver prima saggiato la tua forza.$B$BIl tuo coraggio me l'hai già dimostrato, ma se vuoi davvero affrontare il negromante, ora devi mettere alla prova la tua abilità contro i suoi servitori.",
  obj = "Uccidi 15 Skeletal Raiders, 3 Skeletal Healers e 3 Skeletal Warders, poi torna da Sven.",
  progress = "Combatti con tutte le tue forze, $N. E non disperare, perché la disperazione è l'arma più potente del male.",
  reward = "Nessuno può dubitare della tua abilità in combattimento, $N. Con la tua determinazione, forse riusciremo ancora a farla finita con Morbent Fel!",
  en_title = "Proving Your Worth",
  en_obj = "Kill 15 Skeletal Raiders, 3 Skeletal Healers and 3 Skeletal Warders, and then return to Sven.",
}
T[324] = {
  title = "I Lingotti Perduti",
  desc = "Hai preso dal forziere impregnato d'acqua l'unico Lightforge Ingot, ed è chiaro che i murloc hanno rubato il resto. Dai la caccia ai murloc raiders vicino al relitto del Flying Osprey per recuperare il lightforge iron perduto.",
  obj = "Raccogli 5 Lightforge Ingots, poi torna da Glorin Steelbrow in Wetlands.",
  progress = "Hai trovato il lightforge iron che ti serve?",
  reward = "Ah, li hai trovati! Adesso diamo un po' di martellate a questo lightforge iron per farne qualcosa di utile, eh?",
  en_title = "The Lost Ingots",
  en_obj = "Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands.",
}
T[325] = {
  title = "$GArmato:Armata; e $GPronto:Pronta;",
  desc = "Ecco l'arma contro il demonio di cui mi hai parlato. Sei $Gpronto:pronta;, $N. Buona fortuna, e non vedo l'ora di sentirti raccontare le tue gesta gloriose!",
  obj = "Porta la Morbent's Bane a Sven in Duskwood.",
  progress = "Salve, $N. Non sei $Gstato:stata; via molto, ma vedo nei tuoi occhi un fuoco che prima non c'era.",
  reward = "Ah, questa sarà l'arma giusta contro quel demonio di Morbent Fel! Ben fatto!$B$BSei $Gpronto:pronta;. Morbent Fel cadrà.",
  en_title = "Armed and Ready",
  en_obj = "Bring Morbent's Bane to Sven in Duskwood.",
}
T[328] = {
  title = "La Chiave Nascosta",
  desc = "In questi registri Private Thorsen non viene mai nominato, ma nella rilegatura di uno dei libri contabili di Herod c'è nascosta una small brass key.$B$BE a studiare meglio i suoi appunti, fra le varie carte saltano fuori alcuni riferimenti a un \"forziere sicuro\", che sta da qualche parte nello Stockpile — il complesso di caverne in fondo al Kurzen's Compound.$B$BSe si trova il forziere e la small brass key riesce ad aprirlo, forse si capirà come hanno scoperto Thorsen.",
  obj = "Usa la Small Brass Key per aprire il Bookie Herod's Strongbox.",
  progress = "Il forziere, rinforzato in bronzo, è molto robusto e pesa parecchio.",
  reward = "Aperto il forziere, si vede che Herod ci tiene le monete e gli oggetti più preziosi.",
  en_title = "The Hidden Key",
  en_obj = "Use the Small Brass Key to open Bookie Herod's Strongbox.",
}
T[329] = {
  title = "La Spia Smascherata!",
  desc = "Fra gli oggetti di valore del forziere c'è una scribbled note, sporca di fango. Si legge a fatica, ma sembra un itinerario di Private Thorsen: riporta nei dettagli i suoi percorsi di pattuglia, con chi parla e come passa il tempo fra i ribelli. Come firma, una sola lettera: -M.$B$BChiunque abbia scritto questa nota doveva essere molto vicino a Thorsen. E chiunque abbia scritto questa nota è il traditore dell'accampamento ribelle.",
  obj = "Porta la Muddy Note a Lieutenant Doren all'Accampamento Ribelle.",
  progress = "Hai scoperto chi conosceva il segreto di Thorsen? Abbiamo un traditore fra noi?",
  reward = "Grazie, $N. Con questa nota abbiamo l'indizio che ci serve per stanare il traditore!",
  en_title = "The Spy Revealed!",
  en_obj = "Take the Muddy Note to Lieutenant Doren at the Rebel Camp.",
}
T[330] = {
  title = "Turni di Pattuglia",
  desc = "La nota che mi hai portato è firmata \"-M\"... Non so cosa possa voler dire.$B$BPerò... la nota dice anche che la settimana scorsa questa persona ha fatto gli stessi percorsi di pattuglia di Thorsen. Quindi il traditore dev'essere chi era di pattuglia con lui!$B$BVai da Corporal Sethman: è lui che si occupa dei turni di pattuglia, e può dirti chi era con Thorsen.",
  obj = "Parla con Corporal Sethman.",
  reward = "Oh, certo, te lo controllo io. Vediamo... la settimana scorsa c'era...$B$B...ma guarda, di turno con Thorsen c'era Private Merle. Hanno fatto gli stessi orari di pattuglia per tutta la settimana.",
  en_title = "Patrol Schedules",
  en_obj = "Speak with Corporal Sethman.",
}
T[331] = {
  title = "Fai Rapporto a Doren",
  desc = "Lieutenant Doren voleva che tornassi da lui a riferirgli quello che hai saputo sulle pattuglie?",
  obj = "Parla con Lieutenant Doren.",
  reward = "Mi addolora scoprire che a tradirci è stato Merle. È sempre stato un soldato coraggioso, e lo credevo leale. Ma averlo smascherato è un gran sollievo — con una spia così fra noi... contro Colonel Kurzen non resisteremmo a lungo.",
  en_title = "Report to Doren",
  en_obj = "Speak with Lieutenant Doren.",
}
T[335] = {
  title = "Una Nobile Bevanda",
  desc = "Lord Wishock sta creando parecchio scompiglio nell'House of Nobles: è venuto a sapere del nostro piccolo \"locale\" quaggiù e preme per un'indagine completa. Ho un piano per tenere Wishock \"occupato\", ma ho bisogno del tuo aiuto.$B$BNel Garden of Stalvan, alla periferia di Darkshire, cresce un piccolo fiore bianco che chiamano Tear of Tilloa. Mi serve anche una Musquash Root, che trovi solo ai piedi delle cascate, molto più a valle della Stonewrought Dam, nelle Wetlands.",
  obj = "Zardeth the Black Claw vuole che tu gli porti una Tear of Tilloa da Darkshire e una Musquash Root dalle Wetlands.",
  progress = "Presto Wishock avrà abbastanza sostegno da crearci un sacco di guai. Sei $Griuscito:riuscita; a procurarti la Tear of Tilloa o la Musquash Root?",
  reward = "Eccellente! Questi sì che sono ottimi campioni!",
  en_title = "A Noble Brew",
  en_obj = "Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands.",
}
T[336] = {
  title = "Una Nobile Bevanda",
  desc = "Lord Wishock, come ogni uomo, ha le sue debolezze, e la sua è la passione per i liquori. Un'ipocrisia sbalorditiva: quel banale sciocco passa le giornate a cercare di far chiudere la nostra piccola \"taverna\" e le notti al piano di sopra, ad accumulare un conto che non paga mai. Bene, vediamo se a Wishock piace questa bevanda speciale che gli ho preparato: la Black Claw stout. Dà una bella botta, $N.$B$BPortagliela e senti cosa ne pensa. Probabilmente quel vecchio sciocco se ne va a zonzo per l'Hall of Petitioners.",
  obj = "Porta la Black Claw Stout a Lord Wishock in Hall of Petitioners.",
  progress = "Non vedi che ho da fare? Tutti devono ascoltarmi! Sono importantissimo per il futuro di questo Regno!$B$BOh... cos'hai lì? Ha tutta l'aria di una bevanda rinfrescante...",
  reward = "Ah, grazie di avermi portato questa birra scura dall'aria così invitante, $Gservitore:servitrice;. Tieni, una moneta di rame per te. Ora sparisci dalla mia vista e lasciami gustare la birra!",
  en_title = "A Noble Brew",
  en_obj = "Take the Black Claw Stout to Lord Wishock in the Hall of Petitioners.",
}
T[337] = {
  title = "An Old History Book",
  desc = "Questo libro ha la copertina rovinata dai graffi e incrostata di fango, ma sul dorso si legge ancora la scritta \"La Storia di Stormwind\". Se lo apri, sulla prima pagina si vede, impresso ben chiaro, il sigillo della Stormwind Library.$B$BSembra che qualcuno l'abbia preso in prestito e non l'abbia mai restituito...",
  obj = "Riporta il libro: La Storia di Stormwind, a Stormwind Library.",
  progress = "Ooh! Cos'è quel vecchio libro che hai lì? Posso vederlo??",
  reward = "Oh, cielo! Questo libro manca da questi scaffali da prima che Stormwind venisse ricostruita, anni fa. È in cattive condizioni e naturalmente andrà restaurato, ma sarei onorato di aggiungerlo alla nostra collezione di libri rari.$B$BGrazie, $Gsignore:signora;. Accetta questo compenso per averlo riportato!",
  en_title = "An Old History Book",
  en_obj = "Return the book: The History of Stormwind, to the Stormwind Library.",
}
T[338] = {
  title = "Le Green Hills of Stranglethorn",
  desc = "Se lo scopre, Master Nesingwary si arrabbierà tantissimo!$B$BMi ha affidato da correggere il manoscritto del suo romanzo, Le Green Hills of Stranglethorn. Filava tutto liscio, poi una forte raffica di vento ha attraversato l'accampamento e ha sparpagliato le pagine dappertutto!$B$BQuasi tutte sono riuscito a raccoglierle, ma parecchie sono ancora sparse per la giungla. Recuperale, così completiamo uno per uno i quattro capitoli.$B$BA metterle in ordine ti aiuto io. Quando li avrai tutti e quattro, riportami i capitoli.",
  obj = "Raccogli le pagine mancanti del manoscritto di The Green Hills of Stranglethorn. Quando tutti e quattro i capitoli saranno completi, riportali a Barnil.",
  progress = "I capitoli li hai già rimessi insieme, $N?",
  reward = "Mi hai risparmiato un mucchio di guai, $N, poco ma sicuro! Non so proprio come ringraziarti. Ormai non dovrebbe mancare molto: presto vedremo il libro di Master Nesingwary nelle biblioteche di tutto il mondo!",
  en_title = "The Green Hills of Stranglethorn",
  en_obj = "Collect the missing pages from The Green Hills of Stranglethorn manuscript.  Once all four chapters are complete, return them to Barnil.",
}
T[339] = {
  title = "Capitolo I",
  desc = "Il Capitolo I era davvero avvincente! Master Nesingwary descrive dove si svolge la storia e parla dei suoi compagni di caccia, compreso me!$B$BMa non è questo che conta. Vediamo quali pagine mancano ancora: a quanto pare la 1, la 4, la 6 e la 8 sono rimaste da qualche parte nella giungla!",
  obj = "Porta le pagine 1, 4, 6 e 8 di The Green Hills of Stranglethorn di Nesingwary a Barnil Stonepot per completare il Capitolo I.",
  progress = "Sei $Griuscito:riuscita; per caso a trovare le pagine 1, 4, 6 e 8? Ci mancano solo quelle quattro per rimettere insieme il Capitolo I.",
  reward = "Finalmente! Il Capitolo I è al completo!",
  en_title = "Chapter I",
  en_obj = "Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I.",
}
T[340] = {
  title = "Capitolo II",
  desc = "Il Capitolo II era pieno zeppo di storie emozionanti di caccia a pantere e tigri. Mi prenderei a schiaffi per essermi fatto volare via le pagine!$B$BA quanto pare le ho recuperate tutte, tranne la 10, la 11, la 14 e la 16.",
  obj = "Porta le pagine 10, 11, 14 e 16 di The Green Hills of Stranglethorn di Nesingwary a Barnil Stonepot per completare il Capitolo II.",
  progress = "Per completare il Capitolo II ci mancano ancora le pagine 10, 11, 14 e 16, $N.",
  reward = "Finalmente il Capitolo II è completo! Ben fatto!",
  en_title = "Chapter II",
  en_obj = "Bring pages 10, 11, 14 and 16 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter II.",
}
T[341] = {
  title = "Capitolo III",
  desc = "Il Capitolo III era il mio preferito. Racconta la prima preda di Sir Erlgadin e Lady Rouack con un fucile nanico. E il finale, accidenti, che suspense!$B$BPer finire il capitolo mi sembra che ci servano ancora le pagine 18, 20, 21 e 24. Sono là fuori, da qualche parte...",
  obj = "Porta le pagine 18, 20, 21 e 24 di The Green Hills of Stranglethorn di Nesingwary a Barnil Stonepot per completare il Capitolo III.",
  progress = "Novità sulle pagine 18, 20, 21 o 24? Mancano solo quelle per rimettere insieme il Capitolo III.",
  reward = "Fiu! Ottimo lavoro, $N. Il Capitolo III è di nuovo tutto intero!",
  en_title = "Chapter III",
  en_obj = "Bring pages 18, 20, 21 and 24 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter III.",
}
T[342] = {
  title = "Capitolo IV",
  desc = "Ah, il Capitolo IV; il gran finale! E che finale!$B$BDi questo capitolo ci mancano solo tre pagine. Per rimettere insieme il Capitolo IV servono la 25, la 26 e la 27.",
  obj = "Porta le pagine 25, 26 e 27 di The Green Hills of Stranglethorn di Nesingwary a Barnil Stonepot per completare il Capitolo IV.",
  progress = "Per finire il Capitolo IV bastano tre pagine, $N. Hai già trovato la 25, la 26 o la 27?",
  reward = "Magnifico! Adesso il Capitolo IV è pronto!",
  en_title = "Chapter IV",
  en_obj = "Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV.",
}
T[343] = {
  title = "Parlando di Fortezza",
  desc = "Terrò un discorso sulla Fortezza dello Spirito e vorrei recitare qualche passo di un libro di metallurgia ben preciso — \"Le Tensioni del Ferro\". Una copia dovrebbe trovarsi nella Royal Library, dentro Stormwind Keep. Potresti andarmela a prendere? Se lo farai, che le benedizioni della Luce siano con te!$B$BLa Royal Library è molto grande, ma il bibliotecario capo, Milton Sheaf, ne conosce ogni scaffale come se fosse suo figlio. Parla con lui e il libro te lo troverà.",
  obj = "Vai a Royal Library in Stormwind Keep e parla con Milton Sheaf. Può trovarti il libro di metallurgia che serve a Brother Kristoff per il suo discorso.",
  reward = "Metallurgia? Ah sì, di libri sull'argomento ne abbiamo tanti, e diamo volentieri una mano a Brother Kristoff con il suo discorso! Allora... quale libro serviva, di preciso, al buon fratello?",
  en_title = "Speaking of Fortitude",
  en_obj = "Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf.  He can find for you the book on metallurgy that Brother Kristoff needs for his speech.",
}
T[344] = {
  title = "Brother Paxton",
  desc = "Le Tensioni del Ferro? Sì, lo conosco. Un libro molto buono, l'ha scritto qualche decennio fa il minatore Nanico Margulf Blaggon, che ha passato quasi tutto il suo tempo a scavare minerale nelle profondità delle montagne di Khaz Modan. Un tipo sveglio!$B$BMa dov'ero rimasto? Ah sì, Le Tensioni del Ferro! Temo che il libro sia stato portato a Northshire Abbey: Brother Paxton, che si occupa della biblioteca dell'Abbazia, voleva farne una copia per i suoi scaffali.$B$BMa sono passati mesi. Chissà perché ci sta mettendo tanto...",
  obj = "Parla con Brother Paxton in Northshire Abbey.",
  reward = "Mr. Sheaf vuole sapere dov'è finito il suo libro? Be', la cosa è un tantino imbarazzante. Il libro ce l'ho io, ma non ho ancora finito la mia copia e non me la sento del tutto di separarmi dall'originale!",
  en_title = "Brother Paxton",
  en_obj = "Speak with Brother Paxton in the Northshire Abbey.",
}
T[345] = {
  title = "Scorte di Inchiostro",
  desc = "Volevo finire di copiare Le Tensioni del Ferro, ma...$B$BBe', vedi, l'inchiostro per i libri che copio me lo preparo io. È una ricetta mia; non cola, non sbava e asciuga molto in fretta. Purtroppo, anche troppo! L'ultima partita si è seccata prima che finissi di copiare, e non ho avuto modo di prepararne dell'altro!$B$BPer farlo mi serve Iron Ore di Rethban dalle Redridge Mountains, e di solito me lo fornisce Foreman Oslow a Lakeshire.",
  obj = "Parla con Foreman Oslow a Lakeshire e chiedigli dell'Iron Ore di Rethban.",
  reward = "Ti serve cosa?? Non so se l'hai notato, ma qui siamo impegnati a rafforzare le difese di Lakeshire e a riparare i danni degli ultimi attacchi degli orchi. L'Iron Ore di Rethban, se ti serve, dovrai procurartelo da $Gsolo:sola;!",
  en_title = "Ink Supplies",
  en_obj = "Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore.",
}
T[346] = {
  title = "Ritorno da Kristoff",
  desc = "Ho finito di copiare il libro, quindi ecco a te l'originale de Le Tensioni del Ferro. Grazie per la pazienza, e se vedi Milton, per favore digli che mi dispiace di averlo fatto aspettare tanto.",
  obj = "Torna da Brother Kristoff in Cathedral Square. Consegnagli il libro Le Tensioni del Ferro.",
  progress = "Sei $Griuscito:riuscita; a trovare il libro?",
  reward = "È proprio quello! Grazie, $N. Che la Luce risplenda sul tuo corpo e sul tuo spirito!",
  en_title = "Return to Kristoff",
  en_obj = "Return to Brother Kristoff in the Cathedral Square.  Give him the book The Stresses of Iron.",
}
T[347] = {
  title = "Rethban Ore",
  desc = "Il Rethban Ore deve il nome a Bart Rethban, il primo che l'ha trovato. Una volta fuso non è resistente come il ferro, ma il minerale ha un colore scuro e opaco che alcuni scribi usano per le tinture. Lo trovi nelle Rethban Caverns, a nord di qui.$B$BDi solito ne teniamo un po' in magazzino, ma siamo troppo presi a prepararci agli attacchi degli Orchi per andarlo a raccogliere. E poi... nelle Rethban Caverns ora ci vivono i Redridge Gnolls, e i loro Drudgers il minerale se lo raccolgono per conto loro.$B$BQuindi, se te ne serve un po', te lo dovrai procurare da $Gsolo:sola;.",
  obj = "Raccogli 5 carichi di Rethban Ore e portali a Brother Paxton in Northshire Library.",
  progress = "Ce l'hai, il Rethban Ore?",
  reward = "Oh, splendido! Con questo minerale posso fare la tintura, e così potrò finire di copiare Le Tensioni del Ferro.$B$BGrazie, $N!",
  en_title = "Rethban Ore",
  en_obj = "Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library.",
}
T[348] = {
  title = "Febbre di Stranglethorn",
  desc = "Sto...così...tanto m-m-male....$B$B...m'è presa la Febbre di Stranglethorn...v-v-virus mortale...$B$B...l'unica cura...è...è...mangiare il cuore di M-m-m-m-mokk the Savage...la sfuggente bestia bianca...$B$B...solo il taumaturgo Unbagwa...può e-e-evocarlo....$B$B...cerca Unbagwa in una grotta nascosta, sul capo meridionale...$B$B...presto...muoio...muoio....",
  obj = "Cerca Witch Doctor Unbagwa e fagli evocare Mokk the Savage. Porta l'Heart of Mokk a Fin Fizracket.",
  progress = "....mamma?$B$B...ho tanto freddo...$B$B...me ne vado verso la Twisting Nether...s-s-s-stringimi, mamma....",
  reward = "...sento tornare le forze....$B$BDove sarò finito? Booty Bay? Oh, cielo! Che sogno stranissimo ho fatto...$B$B...però non mi sono ancora ripreso del tutto....",
  en_title = "Stranglethorn Fever",
  en_obj = "Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.",
}
T[349] = {
  title = "Febbre di Stranglethorn",
  desc = "testo provvisorio 02 — descrizione",
  obj = "testo provvisorio 02 — registro",
  progress = "Witch Doctor Unbagwa sapere cosa piacere a Mokk the Savage. Sì, sì!$B$BIo parlare con spiriti e io fare venire lui, sì, io fare.$B$BMa parlare con spiriti piacere anche ad altra Bestia-Gorilla. Tu proteggere Witch Doctor Unbagwa, e io fare venire lui da te.$B$BMa prima Witch Doctor Unbagwa volere qualcosa. Tu portare 10 Gorilla Fangs, e io cominciare a parlare con spiriti!",
  reward = "Gorilla Fangs piacere a Witch Doctor Unbagwa! Io parlare con spiriti per te, fare venire Mokk the Savage.$B$BPerò tu proteggere Witch Doctor Unbagwa da altra Bestia-Gorilla, se no niente Mokk per te!",
  en_title = "Stranglethorn Fever",
  en_obj = "Speak with Witch Doctor Unbagwa.",
}
T[350] = {
  title = "Rivolgiti a un Vecchio Amico",
  desc = "Marzon che contatta uno dei Defias e che ha legami con Lescovar...$B$BOra che hai ucciso VanCleef e Thredd, portare Lescovar davanti alla giustizia sarà difficile: senza la loro testimonianza, le tue prove non valgono niente. E senza contare che Lescovar è un nobile con molte conoscenze. In pratica, è al di sopra della legge.$B$BTi servirà altro aiuto. Detesto doverlo fare, ma conosco qualcuno che ci darà una mano. Trias lo trovi nel Trade District della città.",
  obj = "Parla con Elling Trias a Stormwind.",
  reward = "Scherzi? Shaw vuole un'altra volta il mio aiuto? Che faccia tosta...$B$BLa Defias Brotherhood, dici? Be', mi porti proprio notizie meravigliose, eh? Adesso mi dirai che Deathwing è ancora vivo e sta attaccando la città.$B$BD'accordo, raccontami tutto da capo. E non tralasciare niente, nemmeno quello che ti sembra poco importante. Devo sapere tutto.",
  en_title = "Look to an Old Friend",
  en_obj = "Speak to Elling Trias in Stormwind.",
}
T[351] = {
  title = "Trova OOX-17/TN!",
  desc = "Hai trovato una sorta di strano congegno di metallo a forma di uovo. Mentre armeggi con una delle manopole, l'uovo prende vita e si apre: è una specie di aggeggio robotico degli gnomi! Da dentro l'uovo robotico una voce si accende gracchiando.$B$B\"Mi chiamo Oglethorpe e il mio robot viaggiatore è scomparso! Se lo recuperi, avrai una ricompensa! Per favore, porta al robot questo radiofaro. Eccellente, ho appena calcolato le coordinate per te! È precipitato vicino al Gaping Chasm, a Tanaris!\"",
  obj = "Porta il radiofaro di soccorso al robot viaggiatore di Oglethorpe.",
  progress = "A quanto pare hai trovato i rottami di... un pollo robotico? Dall'uovo la voce torna a gracchiare:$B$B\"Sì, ottimo lavoro! È proprio il mio robot viaggiatore, anche se i sensori dicono che gli serve una spinta per ripartire, prima di poter tornare in volo a Booty Bay a farsi riparare. Forza, metti il radiofaro dentro il robot. Al resto penserà il radiofaro!\"",
  reward = "Metti l'uovo... il radiofaro di soccorso... dentro il pollo... il robot viaggiatore.$B$BDa dentro il robot escono ronzii e fruscii, mentre fatica a rimettersi in piedi. Quando prende vita, torna la voce di Oglethorpe, che però adesso viene da dentro il robot:$B$B\"Almeno OOX-17/TN funziona, ma ha bisogno di grosse riparazioni! Pesa troppo perché tu possa portarlo... ma credo di avere un'idea. Te la senti di tenerlo d'occhio ancora un po'?\"",
}
T[373] = {
  title = "La Lettera Non Spedita",
  desc = "Perquisisci Edwin VanCleef e, fra le altre cose, trovi un'an unsent letter, indirizzata a Baros Alexston, l'Architetto Cittadino di Stormwind, City Hall, Cathedral Square.$B$BA quanto pare è stata scritta e sigillata da poco.",
  obj = "Consegna la Letter to the City Architect a Baros Alexston a Stormwind.",
  progress = "Sì? Posso fare qualcosa per te?",
  reward = "Edwin VanCleef, dici? Mi aspetterei prima una lettera da mia nonna morta... Quindi l'hai ucciso? Perdonami se te lo dico, ma sono piuttosto sorpreso. Da giovane nessuno sapeva combattere come lui. Vediamo cosa sente il bisogno di scrivermi dopo tutti questi anni.$B$B<Baros legge la lettera con attenzione.>$B$BEdwin... Vedo che gli anni non ti hanno cambiato per niente: idealista come sempre, e romantico. Non gli importa chi ferisce, $N. La vendetta l'ha consumato. Però, a pensarci bene, non so se posso fargliene una colpa.",
  en_title = "The Unsent Letter",
  en_obj = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind.",
}
T[377] = {
  title = "Delitto e Castigo",
  desc = "Come se non bastasse che gli abitanti di Duskwood siano lasciati nell'abbandono, ora l'House of Nobles sputa in faccia al Darkshire Council e decide di imprigionare Dextren Ward a Stormwind, invece di decapitare quel criminale come ha sentenziato Lord Ebonlocke.$B$BWard è stato colto mentre vendeva a Morbent Fel i cadaveri del cimitero, un crimine che si paga con la morte. Eppure Stormwind lo reclama come suo prigioniero.$B$BAssassina Ward nella Stormwind Stockade — portami la sua mano — e ti ricompenserò.",
  obj = "Councilman Millstipe of Darkshire vuole che tu gli porti la mano di Dextren Ward.",
  progress = "Finché si lascia vivere un violatore di morti come Dextren Ward, la giustizia è tradita. Torna da me quando quel profanatore di Ward avrà pagato con la morte, come ha deciso Lord Ebonlocke. Alle famiglie dei defunti daremo la pace che meritano e, cosa ancora migliore, manderemo un messaggio chiaro all'House of Nobles di Stormwind.",
  reward = "Allora Dextren Ward ha finalmente pagato per i suoi crimini contro l'umanità? Una bella liberazione, sbarazzarsi di quella feccia, dico io. E alla tua salute, $Gamico mio:amica mia;! Alle famiglie dei defunti hai dato la serenità che meritano, e in più hai mandato un messaggio incisivo a quei burocrati corrotti dell'House of Nobles. Stormwind deve dare risposta ai bisogni della gente di Duskwood, o ci libereremo della sua tirannia.",
  en_title = "Crime and Punishment",
  en_obj = "Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.",
}
T[378] = {
  title = "La Furia È Profonda",
  desc = "Hai dimostrato la tua lealtà a King Magni, $C, e odi la feccia Dark Iron quanto la odio io.$B$BC'è un compito che vorrei portare a termine di persona, ma l'onore mi obbliga a restare con Longbraid. Roggo però ha raccolto informazioni che dimostrano che Kam Deepfury era uno dei cospiratori dell'attacco al Thandol Span: è per colpa dei piani di Deepfury che Longbraid ha perso un familiare.$B$BDeepfury è rinchiuso nella Stormwind Stockade per ragioni politiche. Lo voglio morto, $N. Per Longbraid! Portami la sua testa!",
  obj = "Motley Garmason vuole che gli porti la testa di Kam Deepfury a Dun Modr.",
  progress = "Non lascerò che la stupida burocrazia degli Umani si metta in mezzo alle faccende Naniche, $N. È provato che Kam Deepfury è uno dei cospiratori dell'attacco al Thandol Span, e per l'inganno di Deepfury la brava gente di King Magni ha perso la vita. Gli Umani potranno anche accontentarsi di lasciar marcire Deepfury in The Stockade, ma io non dormirò sonni tranquilli finché Deepfury non sarà ucciso.",
  reward = "Così Kam Deepfury ha finalmente provato cosa vuol dire subire la Morte? Bene. Ben gli sta, a quella feccia Dark Iron vigliacca. Hai fatto un buon lavoro, $C. I caduti dell'attacco al Thandol Span non erano che semplici vittime, in un mondo dilaniato da guerre e disordini. Sapere che Deepfury ha avuto la punizione che meritava porterà pace alle loro famiglie. Il fratello di Longbraid è stato vendicato.",
  en_title = "The Fury Runs Deep",
  en_obj = "Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.",
}
T[379] = {
  title = "Placa la Sete",
  desc = "Vuoi una fonte energetica, e io posso aiutarti. Sai cosa voglio io? Qualcosa da bere! Portami cinque Wastewander Water Pouches e la 4711-FTZ è tua.$B$BE ora... indovina dove si trovano i Wastewander Water Pouches! Perché non vai da uno dei nomadi Wastewander, a est di qui, e gliene chiedi uno? Poi fammi sapere com'è andata.",
  obj = "Porta 5 Wastewander Water Pouches a Chief Engineer Bilgewhizzle a Gadgetzan.",
  progress = "Allora, i nomadi ti hanno dato quegli otri d'acqua \"volontariamente\"?",
  reward = "Ottimo, la fonte energetica è tua. Però non è fatta proprio per un kit scientifico come quello, quindi avrai solo un tempo limitato prima che tutti i dati che raccogli facciano kabum!$B$BQuando avrai messo insieme tutto quello che ti serve per qualunque cosa tu stia combinando, portamelo e la spegnerò come si deve. Avrai al massimo due ore per finire quello che devi finire.$B$BSe non ce la fai in tempo, posso sempre venderti un'altra fonte energetica per riprovare. Hai sentito bene: venderti!",
}
T[386] = {
  title = "Chi la Fa l'Aspetti...",
  desc = "Targorr the Dread ha servito sotto Gath'Ilzogg come Boia supremo. I suoi metodi erano spietati, perfino per un lurido orco. Torturava a suo piacimento uomini che avevano combattuto con coraggio per difendere il Regno. Ora è rinchiuso nella Stormwind Stockade, condannato a morte. Eppure qualcosa non torna. Uno dei nobili burocrati ha sospeso l'esecuzione. Sono certo che qualcuno stia tramando.$B$BElimina Targorr the Dread, $N. Raggiungi The Stockade e decapitalo prima che l'inganno abbia la meglio.",
  obj = "Porta la testa di Targorr the Dread a Guard Berton a Lakeshire.",
  progress = "Sei già $Gstato:stata; a Stormwind, a The Stockade? Temo che l'inganno che ha tenuto in vita Targorr the Dread così a lungo finirà per restituirgli la libertà. È stato condannato a morte, $N, non a fare da pedina politica per il capriccio di un nobile.",
  reward = "Targorr the Dread è finalmente andato incontro al suo destino. Quanto a me, sono lieto che quella bestia ora sappia cosa si prova a finire nella morsa spietata della Morte. Hai fatto un buon lavoro, $N. A volte la giustizia più vera si trova solo fuori dalle aule di tribunale, lontano dallo sguardo offuscato della politica.",
  en_title = "What Comes Around...",
  en_obj = "Bring the head of Targorr the Dread to Guard Berton in Lakeshire.",
}
T[387] = {
  title = "Seda la Rivolta",
  desc = "La rivolta va sedata! Ho bisogno del tuo aiuto. Se si viene a sapere che la prigione è in mano ai detenuti, perderò il posto! C'è sotto qualcosa di losco, ne sono sicuro. Ma adesso conta solo costringere questi prigionieri ad arrendersi, per la sicurezza di Stormwind.$B$BPer chi si ribella la pena è la morte. Uccidi un po' di questi degenerati! Dovrebbe bastare a rimettere le cose sotto controllo.",
  obj = "Warden Thelwater di Stormwind vuole che tu uccida 10 Defias Prisoners, 8 Defias Convicts e 8 Defias Insurgents in The Stockade.",
  progress = "I detenuti tengono ancora The Stockade! Questi Ratti dei Defias devono capire che quello che fanno non lo tollereremo. Ora torna laggiù e usa le maniere forti!",
  reward = "Ti sei $Gbattuto:battuta; con valore in The Stockade, $N. È chiaro che questo problema è più grande di noi due. Ma ti sei $Gcomportato:comportata; bene, e te ne sono grato.",
  en_title = "Quell The Uprising",
  en_obj = "Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade.",
}
T[388] = {
  title = "Il Colore del Sangue",
  desc = "L'amarezza mi scorre nelle vene come un fiume gelido. Mio nipote, Mac, era un ragazzo tanto buono, e aveva appena 14 anni. Quando hanno mandato l'esercito al fronte, Mac ha preso le armi per difendere la città: faceva la guardia in The Stockade, dove è rinchiusa la banda dei Defias. Mac ha sgridato alcuni prigionieri che strappavano le coperte di lana per farne delle sciarpe, il simbolo della loro banda. E per questo hanno pugnalato Mac alle spalle.$B$BVoglio vendetta. Portami 10 delle loro preziose Bandane di Lana: hanno il colore del sangue.",
  obj = "Nikova Raskol di Stormwind vuole che tu raccolga 10 Red Wool Bandanas.",
  progress = "Vedo che sei $Gtornato:tornata;, $C. Hai già preso 10 Red Wool Bandanas a quella Feccia dei Defias in The Stockade?",
  reward = "Dunque è per queste bandane — sudici simboli di corruzione — che il mio Mac è dovuto morire? Che spreco. Che sacrificio tragico.$B$BMa ahimè, il tempo non posso riportarlo indietro. Sappi solo, $N, che con quello che hai fatto hai reso giustizia alla mia famiglia.",
  en_title = "The Color of Blood",
  en_obj = "Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas.",
}
T[389] = {
  title = "Bazil Thredd",
  desc = "Io e VanCleef facevamo parte della Stonemasons Guild. Il nostro compito principale era ricostruire Stormwind dopo la Guerra.$B$BFinito il lavoro, ci hanno truffati: i nobili si sono rifiutati di pagarci. Ad alcuni degli Stonemasons più anziani hanno offerto un incarico nel governo, ma VanCleef ha detto di no, per lealtà verso tutti gli Stonemasons. Ha guidato una rivolta e se n'è andato dalla città giurando vendetta.$B$BSui piani di VanCleef potrebbe saperne di più il suo luogotenente, Bazil Thredd, che è rinchiuso nella Stockade.",
  obj = "Parla con Warden Thelwater in Stockade.",
  reward = "Per la Luce, che vuoi? Non lo vedi che qui siamo in piena crisi?$B$BBazil Thredd?! E perché mai vorresti parlare con quel bastardo? Chi mi dice che non sei $Guno:una; dei suoi tirapiedi, $Gvenuto:venuta; quaggiù a dargli una mano con la sua maledetta rivolta? Se le dannate celle non fossero tutte aperte, potrei sbatterti in una per un po'!",
  en_title = "Bazil Thredd",
  en_obj = "Speak with Warden Thelwater in the Stockade.",
}
T[391] = {
  title = "Rivolte in The Stockade",
  desc = "Mettiamo subito le cose in chiaro, $N: di te non mi fido. Ma per come stanno le cose, probabilmente non cambierai niente.$B$BQuindi facciamo così: scendi laggiù e fai la tua chiacchierata con Thredd. Se stai davvero dalla nostra parte, lo uccidi e, finito il lavoro, mi porti la sua testa. Se invece salta fuori che stai dalla sua, e non esci... quando ti troveremo, morirai insieme al resto di quei vermi.",
  obj = "Uccidi Bazil Thredd e porta la sua testa a Warden Thelwater in Stockade.",
  progress = "O la testa di Thredd me la porti tu, o mi prendo la tua, capito, $N?",
  reward = "Senza più Thredd a guidarli, spero che contenere le rivolte sarà più facile. Vedremo.$B$BLo ammetto: passata mezz'ora, non mi aspettavo proprio di vederti uscire. A quanto pare ti ho giudicato male.$B$BImmagino che da lui tu non abbia saputo granché di utile, vero? Io però so un paio di cose su quello che faceva Thredd che potrebbero interessarti.",
  en_title = "The Stockade Riots",
  en_obj = "Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.",
}
T[392] = {
  title = "Il Visitatore Curioso",
  desc = "I primi anni di prigionia, Thredd non ha mai ricevuto una visita. Pensavo che alla Confraternita non servisse più, e che per questo l'avessero abbandonato.$B$BComunque, qualche mese fa è cambiato tutto; ha cominciato a ricevere visite regolari... una, forse due volte a settimana. Era un uomo strano — uno di poche parole. Qualche sospetto ce l'avevo, ma aveva le carte tutte in regola.$B$BSui documenti c'era scritto che si chiamava Maelik; ecco la sua descrizione. Non credo che tornerà a trovare Thredd.",
  obj = "Porta la Sealed Description of Thredd's Visitor a Baros Alexston a Stormwind.",
  progress = "Sì, $N? Cos'hai trovato?",
  reward = "Mmm. Maelik? No, il nome non mi dice niente, e questa descrizione nemmeno. Ma potrebbe essere chiunque! Un ex Stonemason, uno della Defias Brotherhood... Però, se conosce davvero tanta gente quanto lascia intendere Thelwater, forse qualcun altro può riconoscerlo. Fammi pensare.",
  en_title = "The Curious Visitor",
  en_obj = "Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind.",
}
T[393] = {
  title = "L'Ombra del Passato",
  desc = "Davvero non ne ho idea, $N. Però c'è qualcun altro che potrebbe aiutarti, e guarda caso mi deve un favore per — be', lasciamo perdere. È Master Mathias Shaw del SI:7, e lo trovi nella caserma di Old Town. Quasi tutti gli affari loschi o sottobanco della città, Shaw li tiene sotto controllo.$B$BSe c'è qualcuno che lo sa, è lui.",
  obj = "Porta la Sealed Description of Thredd's Visitor a Master Mathias Shaw a Stormwind.",
  progress = "Saluti. Cosa posso fare per te, $C?",
  reward = "Cosa? Che cos'è? Sì, credo di sapere chi è quest'uomo, ma non si chiama Maelik. Gli assassini portano molti nomi e molte maschere, e li gettano via quando non servono più. Si sa che usa anche l'alias Marzon; ma di certo neanche quello è il suo vero nome.$B$BComunque sia, è un assassino, e di lui so parecchie cose.$B$BAl momento Marzon è al servizio di Lord Gregor Lescovar, un lord dalla reputazione dubbia perfino per la nobiltà corrotta di Stormwind.",
  en_title = "Shadow of the Past",
  en_obj = "Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind.",
}
T[394] = {
  title = "La Testa della Bestia",
  desc = "Va' da Shaw, nell'Old Town, e digli che la minaccia di Lescovar è sistemata; raccontagli anche che parte hai avuto nei complotti del Lord contro la città. Sarà di certo fiero di avere $Gun altro eroe:un'altra eroina; fra i cittadini di Stormwind.$B$BMolto probabilmente ti manderà dal Principe o da qualche altro nobile. Ma non montarti la testa, $N: i nobili credano pure quanto vogliono di governare la città, certe cose restano fuori dalla loro portata.",
  obj = "Parla con Mathias Shaw a Stormwind.",
  reward = "Quindi è morto? La tua è stata una giustizia rapida, $N. Prego la Luce di non diventare mai la tua preda!$B$B<Ride e ti dà una pacca sulla spalla.>$B$BNon è un rimprovero, $N. Come potrei, io che sono il maestro di tutti gli assassini? Ma, a dire il vero, hai reso un grande servizio alla gente di Stormwind, e te ne ringrazio.",
  en_title = "The Head of the Beast",
  en_obj = "Speak to Mathias Shaw in Stormwind.",
}
T[395] = {
  title = "La Fine della Confraternita",
  desc = "Ah, quasi me ne dimenticavo: mentre eri via è passato Alexston, voleva parlarti. Di sicuro vuole riferire ai nobili cosa succede nella Defias Brotherhood.$B$BUn consiglio, $N: se qualcuno dovesse farti domande, io racconterei ogni dettaglio, tranne che è stata la tua mano a uccidere Lescovar. Fidati. Ho una certa... familiarità... con questo genere di cose.$B$BE quanto a Trias, be', non parlarne con nessuno... mai... se puoi evitarlo.",
  obj = "Parla con Baros Alexston a Stormwind.",
  reward = "Sono lieto di vederti, $N. Ho saputo che poco fa hanno trovato morto Lord Gregor Lescovar.$B$BA quanto pare la tua missione è andata a buon fine. Ti sono grato di aver salvato me, e tanti altri, dalla vendetta di VanCleef.",
  en_title = "Brotherhood's End",
  en_obj = "Speak with Baros Alexston in Stormwind.",
}
T[396] = {
  title = "Un'Udienza con il Re",
  desc = "Ho preparato un rapporto per il Re, e credo che dovresti portarglielo tu, raccontandogli anche quello che hai scoperto. Non preoccuparti: di sicuro ti loderà per aver fatto il tuo dovere verso la gente di Stormwind.$B$BL'udienza è fra poco, perciò ti conviene sbrigarti: fino a Stormwind Keep c'è un bel po' di strada.",
  obj = "Consegna il rapporto di Baros Alexston sulla Defias Brotherhood a King Varian Wrynn in Stormwind Keep.",
  progress = "$N, sì? Baros Alexston mi aveva avvisata che saresti $Gvenuto:venuta;. Confesso che sono molto curiosa di sentire cos'hai da dirmi.",
  reward = "Per il servizio che hai reso a Stormwind meriti di essere $Glodato:lodata;, $N. Se le macchinazioni di VanCleef fossero andate in porto, avrebbe senza dubbio fatto un danno considerevole al regno — cosa che, ovviamente, dobbiamo evitare.$B$BPrendi questo, $C, in segno di gratitudine da parte del Re. Mi dispiace solo che non possa dartelo di persona, ma è via per una missione diplomatica e ci vorrà un po' prima che torni.",
  en_title = "An Audience with the King",
  en_obj = "Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.",
}
T[397] = {
  title = "Ci Hai Servito Bene",
  desc = "Mi dicono che a Lord Wishock la bevanda è piaciuta.$B$BCi hai servito bene, $N: grazie a te gli Stregoni di Stormwind potranno praticare le nostre arti indisturbati. Per il tuo impegno ho preparato per te un dono speciale. Va' a parlare con il mio servitore, Zggi, e ritira la ricompensa.",
  obj = "Parla con Zggi, il servitore di Zardeth the Blackclaw, per ritirare la ricompensa.",
  reward = "Padrone dice dare dono a $N. Zggi vuole tenere bel dono, però Zggi sa che Padrone non va tradito.",
  en_title = "You Have Served Us Well",
  en_obj = "Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward.",
}
T[401] = {
  title = "Aspetta Che Sirra Finisca",
  desc = "Mi manca poco per finire di tradurre quella lettera. Torna fra qualche istante e dovrei aver terminato.",
  obj = "Aspetta un momento, poi parla di nuovo con Sirra Von'Indi.",
  reward = "Ecco fatto. La lettera è tradotta...$B$B<L'aria diventa pesante, come se sulla terra calasse una spessa tenda nera...>",
  en_title = "Wait for Sirra to Finish",
  en_obj = "Wait a moment, then speak with Sirra Von'Indi again.",
}
T[434] = {
  title = "L'Attacco!",
  desc = "Appena avrò messo il travestimento a Spybot, andrà a parlare con Lescovar, e le guardie dovrebbero lasciarlo passare senza problemi.$B$BIntanto che mi procuravi i materiali, ci ho pensato io ad avvisare Marzon: gli ho fatto sapere che era ora di incontrarsi di nuovo con Lescovar. E ho fatto girare anche qualche informazione falsa.$B$BLescovar manderà via le guardie e aspetterà Marzon qui fuori, in giardino. Appena li senti parlare dei Defias, entra in azione: devi ucciderli tutti e due prima che le guardie tornino! Quando hai finito, va' a parlare con Trias.",
  obj = "Resta nel giardino finché Lord Gregor Lescovar e Marzon the Silent Blade non avranno finito di parlare. Poi uccidili entrambi prima di tornare da Elling Trias a Stormwind.",
  progress = "Sì, $N? Come procede con Tyrion? Mi ha messo al corrente della situazione, e gli ho dato una mano a ingannare Marzon per attirarlo al castello.$B$BMarzon è stato una spina nel fianco per tanta gente di Stormwind, e fra loro ci sono molti miei cari amici. Nessuno se la prende con i miei amici... non se ci tiene alla salute.$B$BPeccato solo che intanto, di riflesso, io stia facendo un favore a Shaw e al SI:7. Oh, pazienza, non tutti i piani possono essere perfetti.",
  reward = "Allora è fatta? Bene. Grazie davvero per la discrezione, $N. Ti sei $Gdimostrato:dimostrata; $Gdegno:degna; sotto più di un aspetto, e di sicuro terrò d'occhio te e i tuoi progressi nell'Alleanza.$B$BVedi di rigare dritto.",
  en_title = "The Attack!",
  en_obj = "Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind.",
}
T[442] = {
  title = "Assalto alla Fenris Isle",
  desc = "È ora di assaltare la roccaforte dello Scourge a Silverpine: la Fenris Isle.$B$BDevi tornare sull'Isola e distruggere Thule Ravenclaw. Voglio la sua testa!$B$BÈ una missione pericolosa quanto vitale, $N. Non devi fallire.",
  obj = "Porta la Thule's Head a High Executor Hadrec a Sepulcher.",
  progress = "Lo Scourge non può restare a Silverpine, $N: non possiamo permetterlo. Torna da me quando avrai la prova che Thule è morto.",
  reward = "La fine di Thule Ravenclaw non è stata cosa da poco, $N. Renferrel mi dice che quando hai distrutto Thule le energie liberate si sono sentite perfino al Sepulcher.$B$BQuello che hai fatto risuona tra le file dei Forsaken. Sei sempre più $Gprezioso:preziosa; per noi.",
  en_title = "Assault on Fenris Isle",
  en_obj = "Bring Thule's Head to High Executor Hadrec at the Sepulcher.",
}
T[453] = {
  title = "Alla Ricerca della Figura nell'Ombra",
  desc = "Buona fortuna, $N. Spero che tu trovi quel tipo, e che lo trovi vivo.$B$BSe ha lasciato la sicurezza di Darkshire, potrebbe finire preda delle belve delle terre selvagge.",
  obj = "Trova la Figura nell'Ombra. I tuoi indizi:$B$BNon è nativo di Darkshire.$B$BÈ una persona nervosa, agitata.$B$BHa lasciato Darkshire dirigendosi a ovest.",
  progress = "Chi sei?? Lasciami in pace!",
  reward = "<Jitters sospira...>$B$BSì, sono io l'autore di quel libro. Alla fine mi hai trovato, eh?$B$BBeh, se hai letto il diario... allora ne sai solo la metà!",
  en_title = "Finding the Shadowy Figure",
  en_obj = "Find the Shadowy Figure.  Your clues:$B$BHe is not native to Darkshire.$B$BHe is a nervous, jittery person.$B$BHe left Darkshire and headed west.",
}
T[455] = {
  title = "La Traversata di Algaz",
  desc = "Gli orchi del clan Dragonmaw hanno un rifugio nelle Wetlands.  E adesso si sono spinti fino a Dun Algaz!  Non possiamo lasciare che mettano radici qui, o Loch Modan resterà tagliato fuori da Menethil Harbor, il nostro scalo e la nostra roccaforte nelle Wetlands.$B$BFatti strada attraverso Dun Algaz fino alle Wetlands, dall'altra parte, e già che ci sei fai fuori qualche orco!  Presentati a Valstag Ironjaw a Menethil Harbor.$B$BPer arrivare a Menethil oltrepassa Dun Algaz, poi prosegui verso nord lungo la strada e al bivio gira a ovest.$B$BContiamo su di te, $N.  Non fallire.",
  obj = "Attraversa Dun Algaz.$B$BUccidi 8 Dragonmaw Scouts e 6 Dragonmaw Grunts.$B$BPresentati a Valstag Ironjaw a Menethil Harbor.",
  progress = "Vieni da Loch Modan? Com'è la situazione con gli orchi all'Algaz Gate?",
  reward = "Il tuo rapporto è pieno di cattive notizie!$B$BVedo che i Dragonmaw stanno avanzando in forze su Algaz.  Di solito se ne stanno nascosti sulle colline.  Cosa li abbia spinti a riversarsi su Algaz resta ancora un mistero...$B$BGrazie, $N.  E probabilmente ci servirà il tuo aiuto per sistemare questi orchi.",
  en_title = "The Algaz Gauntlet",
  en_obj = "Traverse Dun Algaz.$B$BKill 8 Dragonmaw Scouts and 6 Dragonmaw Grunts.$B$BReport to Valstag Ironjaw in Menethil Harbor.",
}
T[463] = {
  title = "The Greenwarden",
  desc = "Hai sentito parlare di The Greenwarden? Non lo starai cercando, vero? Be', se lo fai sei $Gmatto:matta;, te lo dico io, ma chi sono io per impedire a $Gun pazzo:una pazza; di andare incontro alla morte?$B$BSe è quella bestia che cerchi, ho sentito dire che sta nella palude a est della strada, dove si biforca verso Dun Modr. Sta in agguato là in mezzo ai coccodrilli... e a cose peggiori!$B$BE i soldi lasciali qui. Dove vai non ti serviranno... e non vorrai mica che il vecchio Verdino si scheggi un dente sul tuo oro mentre ti spezza in due con un morso, no?",
  obj = "Trova the Greenwarden.",
  reward = "Le radici e le felci parlano bene di te, $Gpiccolo:piccola;. Ho molti nomi, ma rispondo solo a pochi. Tu però puoi chiamarmi Rethiel.$B$BE devi ascoltarmi... queste terre piangono per ferite purulente, e vorrei affidare a te il compito di guarirle.",
  en_title = "The Greenwarden",
  en_obj = "Find the Greenwarden.",
}
T[464] = {
  title = "Stendardi di Guerra",
  desc = "Alla fine della Second War il clan di orchi Dragonmaw è stato quasi distrutto: aveva perso il controllo dei draghi rossi che aveva addomesticato, e i draghi, che dei loro vecchi padroni non erano troppo contenti, hanno dato ai Dragonmaw una caccia feroce. I pochi sopravvissuti sono fuggiti da Grim Batol fin sulle Montagne a est dei Whelgar's Excavation.$B$BOra si sono rimessi in forze e hanno un accampamento a nord-est di Menethil.$B$BVogliamo che tu attacchi quell'accampamento. Prendi i loro stendardi di guerra e portameli, come prova.",
  obj = "Porta 8 Dragonmaw War Banners a Captain Stoutfist.",
  progress = "Allora, l'accampamento Dragonmaw l'hai attaccato?",
  reward = "Ben combattuto, $N. Da quando non hanno più i draghi, i Dragonmaw non sono la minaccia di un tempo, ma restano avversari feroci.$B$BLi guida Nek'rosh, figlio di Nekros, che anni fa era il capo del clan. Nekros ha domato i Red Dragons con una magia potente, ma quando quella magia l'ha abbandonato... i draghi non ne sono stati contenti.$B$BNekros è stato ucciso, e suo figlio ha giurato di vendicarsi dei draghi che gli hanno ammazzato il padre.",
  en_title = "War Banners",
  en_obj = "Bring 8 Dragonmaw War Banners to Captain Stoutfist.",
}
T[465] = {
  title = "L'Azzardo di Nek'rosh",
  desc = "I Dragonmaw sono più vicini di quanto pensassimo a mettere in atto i loro piani d'attacco.$B$BNek'rosh ha costruito delle catapulte e vuole assediare Menethil! E visto che si combatte a Dun Algaz, di fatto siamo tagliati fuori dai rinforzi!$B$BQuelle catapulte le devi distruggere: sono nell'accampamento Dragonmaw.$B$BEcco, tieni quest'esca. Apriti la strada fino alle catapulte e usala per dar loro fuoco.$B$BDopodiché trova Nek'rosh e uccidilo. Dobbiamo abbattere questa bestia Dragonmaw... tagliandole il collo.",
  obj = "Distruggi le catapulte Dragonmaw.",
  progress = "Davanti a te c'è la prima catapulta. Vuoi darle fuoco?",
  reward = "Metti un po' d'esca sulla catapulta e poi ci dai fuoco con una scintilla.$B$BLe fiamme divampano e si allargano in fretta!",
  en_title = "Nek'rosh's Gambit",
  en_obj = "Destroy the Dragonmaw catapults.",
}
T[468] = {
  title = "Presentati da Mountaineer Rockgar",
  desc = "Mountaineer Rockgar cerca volontari per una missione che passa per Dun Algaz e arriva fino alle Wetlands.  $B$BSe hai voglia di bagnarti gli stivali in quella contea zuppa d'acqua a settentrione, parla con Rockgar a Dun Algaz.  Per arrivare a Dun Algaz segui la strada verso nord, oltre la torre di guardia.",
  obj = "Parla con Mountaineer Rockgar.",
  reward = "Salve, $C!  Sei qui per la missione di ricognizione, eh?  Benissimo!$B$BSpero che l'equipaggiamento sia in buono stato, perché questa \"ricognizione\" si è trasformata in qualcosa di più sporco...",
  en_title = "Report to Mountaineer Rockgar",
  en_obj = "Speak with Mountaineer Rockgar.",
}
T[469] = {
  title = "Consegna Quotidiana",
  desc = "Salute, $Gviaggiatore:viaggiatrice;!$B$BNon è che stai andando verso Menethil, vero? Se non ci stai andando, ti consiglio di farci una capatina: è un buon posto per gli acquisti, e anche per farsi una pinta e rilassarsi.$B$BOra, se per caso vai proprio da quelle parti, ti dispiacerebbe portare questo bundle of crocolisk skins a James Halloran, il conciatore?$B$BCi andrei io, ma mia moglie in questi giorni è proprio di cattivo umore, e preferirei affrontarla il più tardi possibile.",
  obj = "Consegna il Bundle of Crocolisk Skins a James Halloran, il conciatore, a Menethil Harbor.",
  progress = "Salve, $C. Ti interessa un paio di stivali? O magari qualche pelle conciata di fresco?",
  reward = "Mmh, questo me lo manda Einar, giusto? È quasi una settimana che non viene a portarmi le pelli di persona. Di sicuro ha qualche screzio con la moglie!$B$BForse prima o poi manderò la mia a parlare con Sida...",
  en_title = "Daily Delivery",
  en_obj = "Deliver the Bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor.",
}
T[470] = {
  title = "Frugando nella Melma",
  desc = "Ero all'Ironbeard's Tomb per la mia visita settimanale, quando mi hanno attaccata delle melme orribili, tutte gocciolanti! Naturalmente sono andata nel panico.$B$BHo tirato la sacca addosso a una di loro, ma non è servito a niente! La melma se l'è risucchiata e basta... Per fortuna, così ho avuto il tempo di scappare.$B$BLa brutta notizia è che devo proprio recuperare quello che c'era dentro!$B$BNon so a quale melma l'ho tirata; mi sembravano tutte uguali! L'Ironbeard's Tomb è a nord-est di qui, vicino a Dun Modr. Grazie mille!",
  obj = "Una delle melme a Ironbeard's Tomb ha la sacca di Sida, recuperala e riportagliela a Menethil Harbor.",
  progress = "L'hai trovata, la mia sacca?",
  reward = "Oh, grazie, $N! Avevo paura di averla persa per sempre!$B$B<Rovescia in fretta per terra il contenuto dell'ooze-covered bag, e poi lo raccoglie.>$B$BMm, a me questo ormai serve a poco, ma con una buona lavata sono sicura che a te tornerà utile.",
  en_title = "Digging Through the Ooze",
  en_obj = "One of the oozes at Ironbeard's Tomb has Sida's bag, retrieve it and bring it back to her in Menethil Harbor.",
}
T[471] = {
  title = "I Doveri dell'Apprendista",
  desc = "Ho mandato il mio apprendista nelle paludi a scuoiare qualcuno dei nostri famosi crocolischi giganti delle Wetlands. Visto che non tornava, sono andato a cercarlo... Diciamo solo che non è stato un bello spettacolo.$B$BLa levatrice dice che potrebbe cavarsela, ma intanto le pelli mi servono lo stesso!$B$B...Se ne uccidessi qualcun altro, di quei bestioni, dopo quello che hanno fatto non avrei niente in contrario. I crocolischi li trovi a nord lungo la costa, oltre le catapecchie dei murloc.",
  obj = "Raccogli 6 Giant Crocolisk Skins e portale a James Halloran a Menethil Harbor.",
  progress = "Il mio apprendista per me è come un figlio. Sarà dura per lui vivere con una gamba sola.$B$BAh, $N, come va? Hai le mie pelli?",
  reward = "Mmh... Non è che ti andrebbe di diventare $Gil mio apprendista:la mia apprendista;, vero?$B$BAh! No, scherzo. Tanto per cominciare, sei troppo $Gvecchio:vecchia;. E poi — a giudicare dall'aspetto, mi sa che nella vita hai altre ambizioni. Comunque, mi hai procurato delle belle pelli, e saprò farne buon uso.",
  en_title = "Apprentice's Duties",
  en_obj = "Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.",
}
T[472] = {
  title = "Caduta di Dun Modr",
  desc = "Dun Modr è caduta in mano ai Dark Iron Dwarves!$B$BSono gravemente ferito, $C. La maggior parte del reggimento è stata uccisa! Quei delinquenti dei Dark Iron ci hanno attaccati prima che riuscissimo a riorganizzarci dopo l'imboscata al Thandol Span.$B$BLongbraid, il nostro capo, ha suonato la ritirata col corno. Stavamo lasciando la città quando un'ascia vagante mi ha colpito alla schiena. Poi il buio.$B$BMi sono risvegliato qui a Menethil, ma ho paura per i miei compagni d'armi. Dentro di me la speranza arde ancora: forse Longbraid è vivo! Vedi se riesci a trovarlo nei dintorni di Dun Modr, $R!",
  obj = "Cerca Longbraid nei pressi della città di Dun Modr.",
  reward = "Quale $Gcoraggioso:coraggiosa; $C porta notizie da Menethil? Ah, ti chiamano $N.$B$BIn un momento disperato ci porti speranza. Che il giovane Harlo ce l'abbia fatta è davvero una buona notizia: durante la ritirata è stato ferito gravemente, e abbiamo avuto appena il tempo di farlo partire in groppa all'unico destriero sopravvissuto del reggimento.$B$BMa adesso siamo in pericolo. Dun Modr è caduta, e del grande reggimento che eravamo un tempo non resta che l'ombra.",
  en_title = "Fall of Dun Modr",
  en_obj = "Search for Longbraid near the town of Dun Modr.",
}
T[473] = {
  title = "Rapporto a Captain Stoutfist",
  desc = "$N. Il clan di orchi Dragonmaw fa sentire la sua forza non solo ad Algaz.$B$BCaptain Stoutfist ha chiesto di vedere chiunque sia disposto a dare una mano contro questi orchi. Lo trovi nella sala di guerra, dentro la fortezza.",
  obj = "Parla con Captain Stoutfist.",
  reward = "$N. Valstag mi ha raccontato i tuoi successi contro gli Orchi Dragonmaw a Dun Algaz. Sei $Gun nano:una nana; di valore.$B$BE ho un compito per te.",
  en_title = "Report to Captain Stoutfist",
  en_obj = "Speak with Captain Stoutfist.",
}
T[474] = {
  title = "Sconfiggi Nek'rosh",
  desc = "Le catapulte sono bruciate: adesso trova Chieftain Nek'rosh e uccidilo.",
  obj = "Uccidi Chieftain Nek'rosh.$B$BPorta la Nek'rosh's Head a Captain Stoutfist.",
  progress = "Nek'rosh l'hai ucciso?",
  reward = "Hai agito con polso, $N, e il clan di orchi Dragonmaw ha subito un colpo pesante. Forse non si riprenderanno mai più. E distruggendo le catapulte hai messo al sicuro Menethil Harbor.$B$BSei $Gun:una; $R di valore, e il regno di Ironforge ricompensa chi lo serve bene.",
  en_title = "Defeat Nek'rosh",
  en_obj = "Kill Chieftain Nek'rosh$B$BBring Nek'rosh's Head to Captain Stoutfist.",
}
T[480] = {
  title = "Il Tessitore",
  desc = "Un arcimago di grande potere sta supervisionando la riattivazione del nodo di energia ley. Visti i progressi che hanno fatto, l'unica speranza di fermarli è ucciderlo. Non sarà facile: di certo è protetto da molti altri maghi e guardiani.$B$BDevi raggiungerlo ed eliminarlo in fretta. Quando sarà morto, recuperami il suo bastone. Ora va'.",
  obj = "Uccidi l'arcimago di Dalaran, poi recupera il suo bastone per Shadow Priest Allister a Sepulcher.",
  progress = "$GSvelto:Svelta;, il tempo stringe, $N!",
  reward = "L'incantesimo dei maghi si dissolve e le energie ley tornano a sopirsi. I tuoi sforzi hanno dato frutto, $N: abbiamo inferto un duro colpo ai nostri nemici e ai prepotenti maghi di Dalaran.$B$BDobbiamo comunque restare vigili, perché quella fonte di energia è così vicina... Bisogna fare piani per il futuro.",
  en_title = "The Weaver",
  en_obj = "Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher.",
}
T[484] = {
  title = "Young Crocolisk Skins",
  desc = "Sono James Halloran, il conciatore. Le mie pelli di crocolisco conciate le cercano dappertutto, e partono via nave per porti di tutto il mondo.$B$BHai conosciuto Einar? È uno dei cacciatori che mi portano le crocolisk skins.$B$BSono un po' a corto di quelle più morbide, che si ricavano dai crocolischi giovani.$B$BVisto che ne ho poche, ti pagherò profumatamente per una pila di quelle pelli. I crocolischi giovani li trovi nelle acque appena fuori città.",
  obj = "Procurati 6 Young Crocolisk Skins per James Halloran a Menethil Harbor.",
  progress = "$N, giusto? Hai le mie pelli?",
  reward = "Bel lavoro, $N. Queste pelli sono di qualità eccellente, e dovrò metterle a conciare il prima possibile. Oh, ma prima c'è un'altra faccenda da sbrigare, e credo che potresti occupartene tu.",
  en_title = "Young Crocolisk Skins",
  en_obj = "Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor.",
}
T[485] = {
  title = "Trova OOX-09/HL!",
  desc = "Hai scoperto una specie di strano congegno di metallo a forma di uovo. Mentre armeggi con una delle manopole, l'uovo si attiva, si apre e si trasforma in una sorta di marchingegno robotico degli gnomi! Dall'interno dell'uovo robotico gracchia una voce.$B$B\"Mi chiamo Oglethorpe Obnoticus e il mio robot teleguidato si è schiantato! Se lo recuperi, ti ricompenserò: porta questo segnalatore al robot!\"$B$B\"Ho appena calcolato per te le sue coordinate: è precipitato alla sorgente del fiume, vicino a Skulk Rock!\"",
  obj = "Porta il segnalatore di soccorso al robot teleguidato di Oglethorpe, alla sorgente del fiume in Hinterlands, vicino a Skulk Rock.",
  progress = "Sembra che tu abbia trovato i rottami di... un pollo robotico? Dall'interno dell'uovo la voce gracchia di nuovo:$B$B\"Sì, ottimo lavoro! È proprio lui, il mio robot teleguidato, anche se dai sensori risulta che va rimesso in moto prima che possa tornare in volo a Booty Bay per farsi riparare. Forza, metti il segnalatore dentro il rover — al resto penserà il segnalatore!\"",
  reward = "Metti l'uovo... il segnalatore di soccorso... dentro il pollo... il robot teleguidato.$B$BDall'interno del robot arrivano ronzii e sibili, mentre si sforza di alzarsi in piedi. Appena si attiva, torni a sentire la voce di Oglethorpe, ma questa volta esce dal robot:$B$B\"Almeno OOX-09/HL funziona, ma va riparato a fondo! Pesa troppo perché tu possa portarlo... però credo di avere un'idea. Te la senti di fargli la guardia ancora un po'?\"",
}
T[490] = {
  title = "Taglia: Furbolg Gnarlpine",
  desc = "Per ordine tassativo delle Sentinelle, metto una taglia sugli Gnarlpine. Non sono più amici della foresta. La corruzione ne ha fatto minacce senza senno per il nostro popolo e per le creature della radura.$B$BCome stabilito, sarai $Gricompensato:ricompensata; per aver liberato Teldrassil dalla minaccia dei furbolg. Come prova delle tue imprese, portami le loro zanne.$B$BDi furbolg ne troverai molti nella Ban'ethil Hollow, a ovest di Dolanaar e a sud della strada, e verso est, in Starbreeze Village.",
  obj = "Shayla Nightbreeze, sulla strada fuori da Darnassus, vuole che le porti 15 Gnarlpine Fangs.",
  progress = "Finché la corruzione contamina la terra, Teldrassil non può prosperare. Caccia gli Gnarlpine da questa foresta, una volta per tutte.",
  reward = "Hai servito bene, $N, e per il tuo contributo sarai $Gricompensato:ricompensata;.",
}
T[495] = {
  title = "La Crown of Will",
  desc = "Mug'Thol e la sua banda di guerra di ogres sono stati mandati ad Alterac a recuperare la Crown of Will per Lady Sylvanas. Purtroppo quell'idiota, invece di riportarla, ha pensato bene di provarsela... Immagino che gli ogres non resistano a niente che brilli e luccichi.$B$BPerò la sua goffaggine è diventata un problema: con la Crown of Will è riuscito a sottrarsi alla possessione che gli era stata imposta per servire Lady Sylvanas.$B$BLa Dama Oscura vuole dargli una punizione esemplare. Va' a Tarren Mill, a Hillsbrad, e fai rapporto alla mia luogotenente, Melisara.",
  obj = "Fai rapporto a Melisara a Tarren Mill, nelle Hillsbrad Foothills.",
  reward = "Ti ha $Gmandato:mandata; Shalindra? Molto bene, allora: vedrai che non mi perdo in chiacchiere.$B$BMug'Thol è una seccatura, e ce ne occuperemo in fretta, a fondo e senza incidenti.",
}
T[496] = {
  title = "Elixir of Suffering",
  desc = "Ah, un'altra giornata miserabile a Tarren Mill. Con tutta quest'aria pulita sono di pessimo umore, $N.$B$BPrima appestiamo gli umani di queste parti, meglio è. Sto studiando a fondo quali agenti letali usare nei miei intrugli, ma non ho il tempo di andare a raccoglierli tutti.$B$BSe vuoi renderti utile, procurami queste cose: 10 Gray Bear Tongues e il Creeper Ichor, che è rarissimo e difficile da trovare. Gli orsi e i camminatori li trovi appena fuori da Tarren Mill.",
  obj = "Apothecary Lydon of Tarren Mill vuole 10 Gray Bear Tongues e un po' di Creeper Ichor.",
  progress = "Vedo che sei $Gtornato:tornata;. Spero che tu sia $Griuscito:riuscita; a raccogliere gli agenti che mi servono: un altro giorno senza morte e sarò di umore cupissimo.",
  reward = "Questi campioni sono perfetti. Bene, $N, in un'altra giornata miserabile sei $Griuscito:riuscita; a portarmi un briciolo di gioia. Apprezzo i tuoi sforzi.",
  en_title = "Elixir of Suffering",
  en_obj = "Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor.",
}
T[498] = {
  title = "Il Salvataggio",
  desc = "Il Capoguerra ha mandato me e altri guerrieri a recuperare un oggetto da Durnholde e a indagare su questo cosiddetto Syndicate.$B$BSiamo andati a Durnholde a dare un'occhiata in giro, ma un gran numero di umani ci ha colti di sorpresa. Abbiamo combattuto con coraggio, ma erano troppi per noi. Alcuni dei nostri li hanno fatti prigionieri, io sono riuscito a fuggire.$B$BDurnholde è poco a sud-est di qui, oltre il fiume. Lì tengono prigionieri Drull e Tog'thar: devi andare a salvarli.",
  obj = "Krusk a Tarren Mill ti chiede di liberare Drull e Tog'thar da Durnholde Keep.",
  progress = "Devi sbrigarti, $C. Rabbrividisco solo a pensare a cosa potrebbero fare gli umani a Drull e Tog'thar.",
  reward = "Così gli umani pensavano di fare schiavi i nostri guerrieri, eh? Gliela faremo vedere noi!$B$BPare che Gol'dir, il nostro capo, l'abbiano portato da un'altra parte. Dobbiamo trovarlo e salvarlo, ma per ora non abbiamo idea di dove sia...$B$BQuando avremo una pista te lo farò sapere, $N.",
  en_title = "The Rescue",
  en_obj = "Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.",
}
T[499] = {
  title = "Elixir of Suffering",
  desc = "Mi basta un attimo per mescolare questi componenti e ricavarne quello che ho chiamato Elixir of Suffering.$B$BEcco fatto! Ah, per rallegrare una giornata cupa su queste colline miserabili non c'è niente come portare un po' di sofferenza nel mondo.$B$BVediamo se la nostra pozioncina ha avuto l'effetto desiderato.$B$BFai assaggiare alla mia assistente Umpi quello che la Dama Oscura ha in serbo sia per gli umani sia per lo Scourge.",
  obj = "Dai l'Elixir of Suffering a Umpi.",
  progress = "Cra cra!",
  reward = "Croac!",
  en_title = "Elixir of Suffering",
  en_obj = "Give Umpi the Elixir of Suffering.",
}
T[500] = {
  title = "Taglia sui Crushridge",
  desc = "Gli ogres Crushridge si sono scavati una tana sulle Alterac Mountains, vicino alla città in rovina di Alterac. I miei esploratori dicono che si sono presi anche quelle rovine.$B$BNon possiamo lasciarli sistemare comodi lassù: se si credono al sicuro, la prossima mossa sarà scendere sulle colline, e allora ce li ritroveremo alla porta di casa!$B$BDirigiti a nord, sulle Alterac Mountains, e dai la caccia agli ogres. Se mi porti le Dirty Knucklebones che hanno addosso, ti spetta una bella taglia.",
  obj = "Raccogli 9 Dirty Knucklebones dagli ogres Crushridge nelle Alterac Mountains. Portale a Marshal Redpath a Southshore.",
  progress = "Ancora a caccia di ogres, $N? Ce le hai le nocche che ti ho chiesto?",
  reward = "Molto bene, $N. Per mettere insieme tutte queste nocche devi aver fatto a pezzi un bel mucchio di ogres.$B$BCosì dovremmo levarceli di torno. Almeno per un po'.",
  en_title = "Crushridge Bounty",
  en_obj = "Gather 9 Dirty Knucklebones from Crushridge ogres in the Alterac Mountains.  Bring them to Marshal Redpath in Southshore.",
}
T[501] = {
  title = "Elixir of Pain",
  desc = "Oh, $N... a Hillsbrad sbocciano i fiori e l'aria è così fresca e frizzante. Non posso fare a meno di crogiolarmi in tanta infelicità. Guardo fuori dalla finestra sudicia e sogno il giorno in cui la nostra Nuova Peste porterà a questo mondo la morte che si merita.$B$BMi piacerebbe starmene seduto a rimuginare tutto il giorno, ma il dovere verso la Dama Oscura mi chiama. Mi daresti una mano? Da quello che dicono le mie ricerche, credo che con il sangue di un Mountain Lion potrei preparare il più splendido degli infusi di morte. Portamene un po', e ci faremo due risate.",
  obj = "Porta 10 fiale di Mountain Lion Blood ad Apothecary Lydon a Tarren Mill.",
  progress = "Mi ricordo di te, $N: dovevi aiutarmi a preparare il mio ultimo elisir. Prima di portare agli abitanti di Hillsbrad la mia particolare forma di sofferenza, mi serve quel sangue.",
  reward = "Ottima raccolta, $N.",
  en_title = "Elixir of Pain",
  en_obj = "Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill.",
}
T[502] = {
  title = "Elixir of Pain",
  desc = "Ah, non c'è niente di meglio dell'odore di sangue fresco sulle colline!$B$BOra ci mescoliamo un pizzico di questo e un po' di quello, e che il vero divertimento cominci! Quello che ho ricavato da questo sangue mi piace chiamarlo Elixir of Pain. Se i miei calcoli sono giusti, questo intruglio potrebbe essere l'inizio di qualcosa di davvero bello per Lady Sylvanas. Ma ci serve una prova.$B$BPorta questo elisir alla fattoria a nord negli Hillsbrad Fields, a sud-ovest. Vediamo un po' se a Stanley, il cagnolino di Farmer Ray, piace questo \"bocconcino\".",
  obj = "Fai mangiare l'Elixir of Pain a Stanley.",
  progress = "Woof?",
  reward = "Ti versi un po' di elisir nella mano e lo tieni davanti alla bocca di Stanley.",
  en_title = "Elixir of Pain",
  en_obj = "Feed the Elixir of Pain to Stanley.",
}
T[503] = {
  title = "Gol'dir",
  desc = "Per quel che riesco a capire dai documenti che mi hai procurato, Gol'dir è prigioniero in una grande base dello Syndicate a nord, molto probabilmente nelle Alterac Mountains. Lo tengono rinchiuso da troppo tempo: va liberato.",
  obj = "Libera Gol'dir, poi torna da Krusk a Tarren Mill.",
  progress = "Dammi la chiave, $C: il lucchetto lo apro da solo.",
  reward = "Grazie, $N. Ero a capo della spedizione partita da Durotar per ordine del Capoguerra, ma come vedi i nostri piani sono andati un po' storti. Qui, in questa cittadina, mi hanno tenuto prigioniero e mi hanno costretto a lavorare, a trasportare carichi, a scavare...$B$BQuello che ho patito non conta, però. Ci sono informazioni importanti che devi portare a chi ora è alla guida del nostro gruppo.",
  en_title = "Gol'dir",
  en_obj = "Free Gol'dir then return to Krusk in Tarren Mill.",
}
T[504] = {
  title = "Crushridge Warmongers",
  desc = "Hai avuto un assaggio degli ogres Crushridge: adesso voglio che tu gli dia una bella lezione...$B$BRaggiungi le Ruins of Alterac e vai a cercare i Crushridge Warmongers. Abbattine parecchi — solo così quei bruti impareranno a starsene lontani dal territorio dell'Alleanza.",
  obj = "Uccidi 15 Crushridge Warmongers, poi torna da Marshal Redpath a Southshore.",
  progress = "Ti restano altri Warmongers da uccidere, $N. Dovresti essere su in montagna a fare il tuo dovere, non quaggiù con l'arma riposta.",
  reward = "Molto bene. Ecco la tua ricompensa.$B$BE mentre davi la caccia a quei Warmongers, com'era messa la città di Alterac? Ridotta male, immagino. Gli Ogres non sono famosi per la pulizia.$B$BPer fortuna, con i tuoi sforzi sarà più facile tenerli lontani da Southshore.",
  en_title = "Crushridge Warmongers",
  en_obj = "Slay 10 Crushridge Warmongers, then return to Marshal Redpath in Southshore.",
}
T[505] = {
  title = "Syndicate Assassins",
  desc = "Sono il nuovo magistrato di Southshore: mi hanno nominato da poco, dopo che il mio predecessore è stato ucciso. Gli assassini non sono mai stati trovati, ma dalle indagini siamo quasi certi che li abbia ingaggiati lo Syndicate — una banda di ladri guidata da nobili malvagi del regno ormai caduto di Alterac.$B$BLo Syndicate ha un accampamento a nord di Tarren Mill, che è in mano all'Orda, ed è lì che ci hanno portato gli ultimi indizi. Uccidi i membri dello Syndicate che troverai.",
  obj = "Uccidi 12 Syndicate Footpads e 8 Syndicate Thieves, poi torna da Magistrate Henry Maleb a Southshore.",
  progress = "Li hai uccisi, quei delinquenti dello Syndicate, vero?",
  reward = "Grazie, $N. Potrebbero essere ancora in giro da queste parti, ma speriamo che fra i ladri e i banditi che hai ucciso ci fosse anche qualcuno dei responsabili della morte del mio predecessore. E anche se così non fosse, lo Syndicate è una piaga per questa terra e una macchia sulla razza umana.$B$BSouthshore accoglie con favore la loro morte.",
  en_title = "Syndicate Assassins",
  en_obj = "Kill 12 Syndicate Footpads and 8 Syndicate Thieves, then return to Magistrate Henry Maleb in Southshore.",
}
T[506] = {
  title = "L'Eredità di Blackmoore",
  desc = "Un paio di giorni fa è venuto a trovarmi il capo di questo Syndicate, un certo Aliden Perenolde, che si proclamava signore di queste terre. Mi ha confidato che voleva rendere schiavi gli orchi che gli si opponevano, proprio come avevano progettato suo padre e il suo maestro, l'odiato Blackmoore.$B$BMa la cosa più importante è che si era portato dietro l'amante, un fuscello di ragazza di nome Elysa. E al collo lei aveva il ciondolo che il Capoguerra desidera.$B$BOra vai. Io me la caverò da solo, appena avrò sistemato i miei affari qui.",
  obj = "Riporta le informazioni raccolte da Gol'dir a Krusk a Tarren Mill.",
  reward = "Che sfrontatezza, quegli umani prepotenti! Gli faremo vedere che gli orchi non si piegheranno mai alla loro volontà!$B$BOra sarà questa la nostra missione, oltre a recuperare il ninnolo che il Capoguerra desidera. A quanto pare, compiendo l'una compiremo anche l'altra.",
  en_title = "Blackmoore's Legacy",
  en_obj = "Return the information gathered by Gol'dir to Krusk in Tarren Mill.",
}
T[507] = {
  title = "Lord Aliden Perenolde",
  desc = "È chiaro: Perenolde va ucciso, e il suo marciume tolto dal mondo. Il suo maniero si trova un po' più a nord di qui, sulle sponde del Lordamere Lake. Fai il tuo dovere, $N, poi prendi il ciondolo che il Capoguerra desidera e torna qui.",
  obj = "Uccidi Lord Aliden Perenolde e chiedi alla sua amante, Elysa, del ciondolo di Taretha.",
  progress = "C-cosa vuoi?",
  reward = "No, no, ti prego, non farmi del male! Non ho mai voluto nuocere al tuo popolo: mi ha tenuta con sé contro la mia volontà! Ti prego... risparmiami!",
  en_title = "Lord Aliden Perenolde",
  en_obj = "Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant.",
}
T[508] = {
  title = "Il Dono di Taretha",
  desc = "Il ciondolo? Certo, è tuo... Prendilo! Non voglio niente che me lo ricordi... ma ti prego, ti prego, vattene in pace...",
  obj = "Riporta il ciondolo di Taretha a Krusk a Tarren Mill.",
  progress = "Sei $Gtornato:tornata;, $N. Porti buone notizie?",
  reward = "Strano che il Capoguerra si dia tanto da fare per una cosa così piccola. Non pretendo di capirlo, ma lo seguirò, qualunque cosa ordini. Hai fatto bene, $N: il Capoguerra sarà senz'altro lieto di sapere che ce l'hai fatta.",
  en_title = "Taretha's Gift",
  en_obj = "Return Taretha's pendant to Krusk in Tarren Mill.",
}
T[509] = {
  title = "Elisir dell'Agonia",
  desc = "Un altro giorno, un altro elisir da preparare. Fosse per me, lascerei che quei patetici umani e lo Scourge se la sbrigassero tra loro: sembrano già decisi a uccidersi a vicenda.$B$BAhimè, la nostra Dama Oscura vuole che le cose vadano un pochino più in fretta. E allora perché non passare questi giorni lugubri spargendo un po' di morte e malattia per queste terre?$B$BEcco il piano, $N: va' alla Nethander Stead, che sta a sud di Tarren Mill e a est del fiume e di Southshore, e raccogli nel campo 6 Mudsnout Blossoms per il mio prossimo elisir.",
  obj = "Porta 6 Mudsnout Blossoms ad Apothecary Lydon a Tarren Mill.",
  progress = "Ti è andata bene alla Nethander Stead?",
  reward = "Ah, l'orribile puzzo dei Mudsnout Blossoms. Almeno a qualcosa servono, quei lerci Gnolls.",
  en_title = "Elixir of Agony",
  en_obj = "Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill.",
}
T[510] = {
  title = "Foreboding Plans",
  desc = "Fra i documenti c'è un elenco dei rifornimenti richiesti: roba comune (cibo, armi, vestiti), ma anche attrezzature più insolite (maschere, olio, veleno).$B$BA colpire più di tutto, però, è l'urgenza della richiesta — i rifornimenti servivano presto, per intraprendere quella che il documento chiama una \"missione importante contro Southshore\".",
  obj = "Porta i Foreboding Plans a Magistrate Maleb a Southshore.",
  progress = "$N, ti vedo $Gagitato:agitata;. Hai qualcosa da dirmi?",
  reward = "<Maleb legge i documenti.>$B$BQuesti documenti mi preoccupano molto, $N. Da quello che dicono, e da come si è comportato lo Syndicate in passato, dobbiamo supporre che quella banda di tagliagole abbia mosso guerra a Southshore.",
  en_title = "Foreboding Plans",
  en_obj = "Bring the Foreboding Plans to Magistrate Maleb in Southshore.",
}
T[511] = {
  title = "Encrypted Letter",
  desc = "Fra le lettere su questo tavolo ce n'è una codificata, del tutto incomprensibile.",
  obj = "Porta l'Encrypted Letter a Loremaster Dibbs a Southshore.",
  progress = "Sì, $Gsignore:signora;? Avevi bisogno di me?",
  reward = "E questa cos'è? Aspetta un momento... fammi guardare meglio.$B$B...$B$BMh, una codifica del genere non l'ho mai vista, anche se, lo ammetto, in materia le mie conoscenze sono tutt'altro che complete.",
  en_title = "Encrypted Letter",
  en_obj = "Bring the Encrypted Letter to Loremaster Dibbs in Southshore.",
}
T[512] = {
  title = "Morti Nobili",
  desc = "Temo che i capi dello Syndicate siano decisi a mandare in rovina Southshore. Dobbiamo colpirli duramente prima che riescano a mettere in atto i loro piani.$B$BVai fra le rovine di Strahnbrad, nelle Alterac Mountains, a nord: crediamo che lo Syndicate abbia lì il suo quartier generale.$B$BSappiamo che a guidare questa banda di tagliagole ci sono ex nobili di Alterac. Può darsi che si spaccino per normali agenti dello Syndicate, ma quando ne uccidi uno lo riconosci dall'anello con sigillo che porta.$B$BPortami quegli anelli con sigillo.",
  obj = "Porta 7 Alterac Signet Rings a Magistrate Maleb a Southshore.",
  progress = "Hai dato la caccia allo Syndicate? Ce li hai, quegli anelli?",
  reward = "Senza i suoi nobili, lo Syndicate non sarà più capace di agire con decisione e diventerà una semplice banda di delinquenti.$B$BServi bene la tua Alleanza, $N.",
  en_title = "Noble Deaths",
  en_obj = "Bring 7 Alterac Signet Rings to Magistrate Maleb in Southshore.",
}
T[513] = {
  title = "Elisir dell'Agonia",
  desc = "Pensavo che anche questo giorno sarebbe passato senza la minima gioia, e invece mi hai portato quei meravigliosi Mudsnout Blossoms.$B$BPer prima cosa li mescolerò fino a farne un composto fine. Poi ci servirà Master Apothecary Faranell, a Undercity, che ci aggiunga il suo colloide della decomposizione, e a quel punto saremo pronti a divertirci davvero!$B$BTieni, $N: porta subito questo Mudsnout Composite a Master Faranell.",
  obj = "Porta il Mudsnout Composite a Master Apothecary Faranell a Undercity.",
  progress = "Non vedi che sono occupato, $C? La Dama Oscura pretende una nuova pestilenza prima che lo Scourge avanzi da Northrend e ci travolga, e con la minaccia degli umani che preme da sud il tempo per me vale più di ogni altra cosa. Sarà meglio che sia importante!",
  reward = "Ti manda Apothecary Lydon? Ah, e perché non l'hai detto subito!$B$BSarà pure di carattere cupo, ma Apothecary Lydon è uno dei nostri membri più devoti e capaci.$B$BQuel brav'uomo mi manda un Mudsnout Composite! Adesso ho capito cosa sta tramando il nostro amico a Hillsbrad, e mi piace come ragiona. La Dama Oscura sarebbe molto colpita dai passi avanti che sta facendo verso la nuova pestilenza.",
  en_title = "Elixir of Agony",
  en_obj = "Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity.",
}
T[514] = {
  title = "Lettera per Stormpike",
  desc = "A Ironforge ho un collega che potrebbe aiutarci a decifrare questa lettera. Va' alla Biblioteca dell'Hall of Explorers, a Ironforge, e parla con Prospector Stormpike. Digli che ti mando io e fagli vedere la lettera. Se a nord di Blackrock Spire c'è qualcuno capace di leggerla, è lui.",
  obj = "Porta la Cleverly Encrypted Letter a Prospector Stormpike a Ironforge.",
  progress = "Ti manda Dibbs da Southshore, eh? E come se la passa quel vecchio topo di biblioteca?",
  reward = "Ah, una codifica! Pane per i miei denti. Vediamo un po'...",
  en_title = "Letter to Stormpike",
  en_obj = "Take the Cleverly Encrypted Letter to Prospector Stormpike in Ironforge.",
}
T[515] = {
  title = "Elisir dell'Agonia",
  desc = "Un mudsnout composite? Assolutamente geniale! Come ho fatto a non pensarci io?$B$BLasciami aggiungere il mio colloide della decomposizione a questa miscela diabolica.$B$BPerché gli agenti contaminanti di questa mudsnout mixture si attivino, a Lydon serviranno un troll's blood elixir forte e poi daggerspine scales e torn fin eyes della costa meridionale di Hillsbrad. Quando gli avrai procurato tutti i reagenti, saprà lui cosa fare. E, santo cielo, non vedo l'ora di sapere come andrà il suo esperimento!",
  obj = "Porta la Mudsnout Mixture, un Troll's Blood Elixir Forte, 5 Daggerspine Scales e 5 Torn Fin Eyes ad Apothecary Lydon a Tarren Mill.",
  progress = "Che piacere rivederti, $N. Qui mi stavo annoiando terribilmente: non c'era una sola cosa divertente da fare, a parte avvelenare e infettare Umpi e poi rianimarla... ancora e ancora e ancora.$B$BCom'è andato il viaggio a Undercity? Hai avuto la fortuna di massacrare qualche umano per strada?",
  reward = "Questo esperimento mi emoziona tanto che sono euforico! Mi sei $Gstato:stata; di grandissimo aiuto, $N. Insieme spargeremo morte e malattia in questa terra!",
  en_title = "Elixir of Agony",
  en_obj = "Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill.",
}
T[516] = {
  title = "Beren's Peril",
  desc = "Mi sono arrivati dei rapporti: un gruppo di non morti si sta rintanando per preparare un attacco contro di noi. Ora che lo sappiamo, possiamo ribaltare la situazione e colpirli per primi, stroncando sul nascere il loro piccolo piano.$B$BPurtroppo quello che so è a dir poco frammentario. Si dice che si nascondano in un posto chiamato Beren's Peril. Il punto esatto è ignoto, ma sembra che sia una grotta sulle colline, vicino a un gruppetto di maghi di Dalaran.$B$BConto sulla tua intraprendenza. Trovali e abbattili.",
  obj = "Trova il Beren's Peril, poi uccidi 6 Ravenclaw Drudgers e 6 Ravenclaw Guardians, quindi torna da Shadow Priest Allister al Sepulcher.",
  progress = "$N, hai già trovato la loro base? Il tempo stringe!",
  reward = "Se i nostri esploratori e i nostri agenti continueranno a portarci informazioni preziose come questa, in men che non si dica scacceremo il Lich King's Scourge dalle nostre terre.",
  en_title = "Beren's Peril",
  en_obj = "Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher.",
}
T[517] = {
  title = "Elisir dell'Agonia",
  desc = "Finalmente il nuovo elisir è pronto per la prova. Ma perché sprecare un'ottima pestilenza, per giunta altamente contagiosa, su una semplice rana o su un cane? Divertiamoci sul serio, nel nome di Lady Sylvanas.$B$BScendi a Dun Garok: conosci la caserma dove zampettano quei piccoli nani lerci. Rubami un barile della loro Shindigger Stout, e quando l'avrò io e te faremo una gran festa, $N.",
  obj = "Porta un barile di Shindigger Stout ad Apothecary Lydon a Tarren Mill.",
  progress = "Certe volte qui a Tarren Mill mi annoio così tanto che mi piace aprire il barattolo di formaldeide e lasciare che quel delizioso aroma si spanda nell'aria. Solo che Umpi si innervosisce un po'.$B$BAllora, sei $Griuscito:riuscita; a prendere un barile dai Nani? Giuro che se devo passare un altro giorno a fissare questo elisir letale senza usarlo su qualcuno, mi metto a urlare.",
  reward = "Finalmente! Ora siamo pronti ad agire!",
  en_title = "Elixir of Agony",
  en_obj = "Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill.",
}
T[518] = {
  title = "La Crown of Will",
  desc = "Mug'Thol e i suoi ogres Crushridge hanno invaso le rovine di Alterac. Senza prima sfoltirne le file, sarà difficile punirlo sul serio.$B$BAndremo avanti quando li avremo indeboliti.$B$BCapito? Bene. Ora va'.",
  obj = "Uccidi 14 Crushridge Maulers per Melisara a Tarren Mill.",
  progress = "Vedo che non hai ancora finito il tuo compito, $N. Devo informare Sharlindra della tua incompetenza?",
  reward = "La neve fiorisce rossa del sangue degli ogres, ma non possiamo fermarci finché lo spirito e il numero dei Crushridge non saranno schiacciati e macinati nella terra e nella neve.",
  en_title = "The Crown of Will",
  en_obj = "Kill 10 Crushridge Maulers for Melisara in Tarren Mill.",
}
T[519] = {
  title = "La Crown of Will",
  desc = "Targ, Muckrake e Glommus sono i luogotenenti di Mug'Thol e gli sono fedeli, anche se chissà cosa rende leale un ogre.$B$BPortami le loro teste, $N, e a quel punto resterà solo da tagliare la testa a Mug'Thol, corona compresa.",
  obj = "Uccidi Targ, Muckrake e Glommus e porta le loro teste a Melisara a Tarren Mill.",
  progress = "Voglio le loro teste, $N, non delle scuse.",
  reward = "...e io che credevo che gli ogres puzzassero già abbastanza.$B$BQuando mi porterai la testa di Mug'Thol, le farò infilzare tutte e quattro su delle picche sopra Alterac: un degno monumento per chi va contro i desideri della Dama Oscura.",
  en_title = "The Crown of Will",
  en_obj = "Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill.",
}
T[520] = {
  title = "La Crown of Will",
  desc = "Morti i luogotenenti di Mug'Thol, non resta che uccidere Mug'Thol stesso e recuperare la Crown of Will. Di sicuro non vorrà separarsene, e con ogni probabilità ti starà anche aspettando, vista la... dipartita... dei suoi compagni.$B$BTrova Mug'Thol e portami la sua testa e la Corona: sarà la fine della resistenza dei Crushridge.",
  obj = "Uccidi Mug'Thol e riporta la sua testa insieme alla Crown of Will a Melisara a Tarren Mill.",
  progress = "Tre teste ho, e me ne serve una quarta: quella di Mug'Thol, o la tua, $N. Questo te lo prometto.",
  reward = "Hai fatto bene il tuo dovere, $N. La testa di Mug'Thol ornerà la vetta più alta delle rovine di Alterac, e la Deathguard seppellirà quel che resta dei Crushridge.",
  en_title = "The Crown of Will",
  en_obj = "Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill.",
}
T[521] = {
  title = "La Crown of Will",
  desc = "Ora resta solo da consegnare la Crown of Will a Sharlindra, a Undercity: sarà lei a farla avere a Lady Sylvanas. E ti avverto di non pensare di usarla per i tuoi scopi, $N: la sorte di Mug'Thol dovrebbe bastarti come esempio.",
  obj = "Consegna la Crown of Will a Sharlindra a Undercity.",
  progress = "Sì? Hai qualcosa da riferire?",
  reward = "Dunque è questa la reliquia con cui l'ogre è sfuggito alla volontà della Dama Oscura...$B$BStrano che una cosa così semplice possa avere un potere così grande. E che sia finita in mani tanto goffe. Ben fatto, $N: consegnerò la corona a Lady Sylvanas e farò in modo che venga a sapere della tua impresa.",
  en_title = "The Crown of Will",
  en_obj = "Deliver the Crown of Will to Sharlindra in the Undercity.",
}
T[522] = {
  title = "Assassin's Contract",
  desc = "È un contratto per l'assassinio di Magistrate Henry Maleb, sigillato con ceralacca rossa e timbrato con un caratteristico anello con sigillo.",
  obj = "Porta l'Assassin's Contract a Magistrate Maleb a Southshore.",
  progress = "Mi sembri senza fiato! Devi riferirmi qualcosa?",
  reward = "<Maleb esamina il contratto.>$B$BEcco spiegato l'ultimo attacco a Southshore. Lo Syndicate deve avercela con me, proprio come ce l'aveva con chi mi ha preceduto!",
  en_title = "Assassin's Contract",
  en_obj = "Bring the Assassin's Contract to Magistrate Maleb in Southshore.",
}
T[523] = {
  title = "La Fine del Barone",
  desc = "Il contratto che hai recuperato porta la firma di Baron Vardus, un nobile dell'ex regno di Alterac noto per il cuore freddo e i metodi brutali. Che dietro a tutto questo ci fosse uno come il Barone non mi sorprende.$B$BTrova quest'uomo. Trovalo e consegnalo alla giustizia. Sarà in uno dei covi dello Syndicate — forse fra le rovine di Strahnbrad, o forse nella valle più a nord.",
  obj = "Porta l'Head of Baron Vardus a Magistrate Maleb a Southshore.",
  progress = "Baron Vardus non crederà davvero che Southshore gli lasci mandarci contro i suoi scagnozzi impunemente. Voglio la sua testa!",
  reward = "Grazie, $N. Quella canaglia ha perso la testa, e ora la mia può riposare un po' più tranquilla.",
  en_title = "Baron's Demise",
  en_obj = "Bring the Head of Baron Vardus to Magistrate Maleb in Southshore.",
}
T[524] = {
  title = "Elisir dell'Agonia",
  desc = "Qui accanto le Guardie della Morte tengono in ostaggio alcuni captured farmers. High Executor Darthalia sospettava che fra loro si nascondesse uno degli strateghi militari di Stormwind. A quanto pare, ieri notte il tizio dell'esercito è stato trovato morto nelle Plaguelands, e Darthalia, che pensa sempre a me, ha deciso di lasciare i prigionieri a mia disposizione.$B$BCredo sia arrivato il momento di dare una festa a quei contadini. Sarà proprio uno spasso!$B$BMetti questo tainted keg sul tappeto della loro stanza. Birra appestata per tutti!",
  obj = "Metti il Tainted Keg sul tappeto per i captured farmers.",
  progress = "Il tappeto manda odore di muffa.",
  reward = "Posi il tainted keg sul tappeto polveroso.",
  en_title = "Elixir of Agony",
  en_obj = "Place the Tainted Keg on the rug for the captured farmers.",
}
T[525] = {
  title = "Altri Misteri",
  desc = "La lettera l'ho decifrata, ma non so che pensarne. L'hai trovata in mezzo a dei ladri, sulle colline ai piedi di Alterac? Molto strano...$B$BFaresti bene a portarla al magistrato di Southshore. Per quanto la lettera sia criptica, la sua è la città più vicina ad Alterac: se si sta preparando una minaccia, deve saperlo.",
  obj = "Porta la Decrypted Letter a Magistrate Maleb a Southshore.",
  progress = "$N. Sei $Gtornato:tornata; a girare per le colline e le montagne? Che notizie mi porti?",
  reward = "<Maleb legge la lettera.>$B$BQuindi questa è la traduzione di una lettera che hai trovato in un accampamento dello Syndicate? Non l'ha scritta un ladro, e nemmeno un nobile di Alterac.$B$BA quanto pare lo Syndicate è legato a un'altra potenza, e rabbrividisco al pensiero di cosa possa essere.",
  en_title = "Further Mysteries",
  en_obj = "Bring the Decrypted Letter to Magistrate Maleb in Southshore.",
}
T[526] = {
  title = "Lightforge Ingots",
  desc = "Avrai anche trovato un Lightforge Ingot in quel forziere, ma non basta per forgiare niente di decente!$B$BDovresti tornare lì a cercarne altri. Magari i murloc intorno a quel relitto hanno addosso dei Lightforge Ingots.",
  obj = "Raccogli 5 Lightforge Ingots, poi torna da Glorin Steelbrow in Wetlands.",
  progress = "Hai trovato il lightforge iron che ti serve?",
  reward = "Ah, li hai trovati! Adesso diamo un po' di martellate a questo lightforge iron per farne qualcosa di utile, eh?",
  en_title = "Lightforge Ingots",
  en_obj = "Gather 5 lightforge ingots, then return to Glorin Steelbrow in the Wetlands.",
}
T[527] = {
  title = "Battaglia di Hillsbrad",
  desc = "Mettiti sull'attenti quando parli con me, $C.$B$BRispondo direttamente a Varimathras. Dobbiamo reprimere l'infestazione umana finché i nostri speziali non avranno messo a punto la nuova piaga.$B$BDalle nostre informazioni, la città di Hillsbrad sembra vulnerabile a un attacco. Con il tuo primo incarico ne colpirai le scorte di cibo e le infrastrutture.$B$BVa' a ovest e fa' irruzione nelle fattorie più a nord degli Hillsbrad Fields. E assicurati che vengano giustiziati anche i proprietari terrieri, Farmer Ray e Farmer Getz.",
  obj = "Uccidi 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray e Farmer Getz e fai rapporto a Darthalia a Tarren Mill.",
  progress = "Sono l'Alta Esecutrice di Tarren Mill e rispondo direttamente a Varimathras e alla Dama Oscura: i miei ordini sei $Gtenuto:tenuta; a eseguirli.$B$BO forse prendi alla leggera questa guerra contro l'Alleanza? Se è così, dovrei decapitarti qui e ora. Altrimenti va' a ovest, fino alla città di Hillsbrad, e combatti gli umani come ti è stato ordinato.$B$BPuoi andare.",
  reward = "Riposo, $C. Vedo che sei $Gtornato:tornata; dalla battaglia, e le mie fonti mi dicono che sul fronte di Hillsbrad hai fatto un buon lavoro.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill.",
}
T[528] = {
  title = "Battaglia di Hillsbrad",
  desc = "La notizia dell'attacco alle fattorie del nord ha seminato il panico fra i cittadini. Eccellente.$B$BI nostri Deathstalkers riferiscono che alcuni contadini stanno fuggendo verso i campi nel sud di Hillsbrad. Quegli sciocchi credono di potersi nascondere nei frutteti e sfuggire al destino.$B$BDimostra che si sbagliano, $N. Torna agli Hillsbrad Fields e stana i contadini che se ne stanno nascosti a tremare. Annientali in nome della nostra Dama Oscura.$B$BPuoi andare!",
  obj = "Uccidi 15 Hillsbrad Peasants e fai rapporto a Darthalia a Tarren Mill.",
  progress = "Gli ordini li conosci, $C. Smettila di perdere tempo qui a Tarren Mill quando c'è lavoro da fare altrove.",
  reward = "La morsa della morte si stringe intorno alla città di Hillsbrad. La battaglia va bene.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill.",
}
T[529] = {
  title = "Battaglia di Hillsbrad",
  desc = "Gli umani di Hillsbrad ci oppongono una resistenza che non ci aspettavamo. Pare che il problema sia il fabbro del posto, che sta armando i cittadini. Dobbiamo tagliare tutte le linee di rifornimento.$B$BLa tua missione sarà giustiziare Blacksmith Verringtan, e con lui i suoi apprendisti. Già che ci sei, riportami una shipment of iron dalle loro scorte: quel materiale ci tornerà utile quando avremo finito di conquistare Hillsbrad e cominceremo a radere al suolo Southshore.",
  obj = "Uccidi Blacksmith Verringtan e 4 Hillsbrad Apprentice Blacksmiths.$B$BRecupera una shipment of iron e fai rapporto a Darthalia a Tarren Mill.",
  progress = "Sei $Griuscito:riuscita; a eseguire gli ordini, $C? Verringtan e i suoi aiutanti, te ne sei $Gsbarazzato:sbarazzata;? E la spedizione di ferro, dov'è?",
  reward = "Missione compiuta, $C. E con notevole abilità, devo aggiungere.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths.$B$BRetrieve a shipment of iron and report back to Darthalia in Tarren Mill.",
}
T[532] = {
  title = "Battaglia di Hillsbrad",
  desc = "La città di Hillsbrad è allo sbando e crediamo che cadrà presto. Ma dobbiamo restare spietati finché quella feccia umana non sarà cancellata da queste colline per l'eternità.$B$BNonostante le perdite enormi, gli umani si stringono intorno a chi li guida e continuano a combattere. Dobbiamo eliminare il loro capo, Magistrate Burnside, insieme al consiglio cittadino. Distruggi anche il documento politico che tanto venerano, l'Hillsbrad Proclamation, e già che ci sei ruba il registro cittadino.",
  obj = "Uccidi Magistrate Burnside e 5 Hillsbrad Councilmen. Distruggi l'Hillsbrad Proclamation. Ruba l'Hillsbrad Town Registry. Poi fai rapporto a Darthalia a Tarren Mill.",
  progress = "Che notizie mi porti?",
  reward = "La notizia delle tue gloriose imprese a Hillsbrad si è sparsa in fretta. Hai fatto bene, $C.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill Magistrate Burnside and 4 Hillsbrad Councilmen.  Destroy the Hillsbrad Proclamation.  Steal the Hillsbrad Town Registry.  Report back to Darthalia in Tarren Mill afterwards.",
}
T[533] = {
  title = "Infiltrazione",
  desc = "Finalmente ci arrivano voci e dicerie, qualche indizio su dove sia Gol'dir. Gli umani continuano a spostarlo, ma stiamo restringendo le ricerche e ora puntiamo sul grande accampamento dello Syndicate, appena a nord di qui.$B$BVai là, $N, e riportami ogni informazione su cui riesci a mettere le mani.",
  obj = "Recupera informazioni su dove si trova Gol'dir per Krusk a Tarren Mill.",
  progress = "Hai trovato qualcosa? Ogni giorno che passa temo che per Gol'dir le cose si mettano peggio...",
  reward = "Finalmente sappiamo dove tengono prigioniero Gol'dir. Quell'accampamento non è troppo lontano da qui. Speriamo che non siano preparati come quando ci hanno catturati la prima volta.",
  en_title = "Infiltration",
  en_obj = "Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill.",
}
T[535] = {
  title = "Valik",
  desc = "Urrgh... Ferito, morente e davanti al nemico.$B$BTanto mi ucciderai lo stesso, di sicuro, ma se mi porti un po' di birra scura di Southshore — quelli come te bevono, no? — ti dirò quello che vuoi sapere.",
  obj = "Porta un boccale di Southshore Stout a Valik nell'accampamento dello Syndicate.",
  progress = "Mi hai portato da bere o sei $Gtornato:tornata; solo per finire il lavoro?",
  reward = "Tanto sto per morire, posso dirlo tranquillamente: questa è la cosa più dolce che abbia mai assaggiato... Ecco, prendi questo: da morto non mi servirà a niente.$B$BBe', sbrigati!",
  en_title = "Valik",
  en_obj = "Bring a mug of Southshore Stout to Valik in the Syndicate camp.",
}
T[536] = {
  title = "Lungo la Costa",
  desc = "Mi hanno trasferito dalla guardia cittadina di Stormwind a Southshore, una città che dall'aspetto dovrebbe essere abbandonata... E giorno e notte si sente odore di porto.$B$BPer non parlare del vecchio Redpath... Vuole che pensi io ai murlocs. Ah!$B$BNon trovo quasi la voglia di spingermi fino a qualcuno di quei gruppetti di pesci troppo cresciuti, giù lungo la Western Strand. Se ci pensassi tu al posto mio, te ne sarei grato.",
  obj = "Uccidi 10 Torn Fin Tidehunters e 10 Torn Fin Oracles per Lieutenant Farren Orinelle a Southshore.",
  progress = "Un'altra birra, per favore, che l'ultima pare proprio sparita!$B$BLuce, per quanto dovrò restare ancora inchiodato qui?$B$BOh, sei tu, $N. Li hai già fatti fuori, quei murlocs?",
  reward = "Spero che basti a convincere Redpath che ho — ah! — eseguito i suoi ordini, liberando Southshore dalla terribile, orribile minaccia dei temuti murlocs! Non esiste male più grande delle devastazioni dei pesci troppo cresciuti!",
  en_title = "Down the Coast",
  en_obj = "Kill 10 Torn Fin Tidehunters and 10 Torn Fin Oracles for Lieutenant Farren Orinelle in Southshore.",
}
T[537] = {
  title = "Consiglio Oscuro",
  desc = "La lettera che mi hai portato l'ha scritta un essere che si fa chiamare Nagaz, un membro dell'Argus Wake. Non so cosa sia quest'Argus Wake, ma se sono alleati dello Syndicate devono essere una minaccia.$B$BVoglio che trovi Nagaz e gli Argus Shadow Mages di cui parla la lettera. Trovali, e uccidili.$B$BCerca nelle Uplands, a nord di Strahnbrad: è lì che lo Syndicate è più forte.$B$BCon un po' di fortuna, lì troverai questi emissari dell'Argus Wake.",
  obj = "Uccidi 4 Argus Shadow Mages.$B$BPorta l'Head of Nagaz a Magistrate Maleb a Southshore.",
  progress = "Gli emissari dell'Argus Wake, li hai trovati?",
  reward = "Ben fatto, $N. L'Argus Wake non sembra gente che vorremmo a capo dello Syndicate.$B$BE anche se qui hai distrutto il loro capo, Nagaz non era che il servitore di qualcun altro. L'Argus Wake potrebbe avere radici profonde in tutto il continente di Azeroth.$B$BO persino nel mondo intero.",
  en_title = "Dark Council",
  en_obj = "Kill 4 Argus Shadow Mages.$B$BBring the Head of Nagaz to Magistrate Maleb in Southshore.",
}
T[538] = {
  title = "Southshore",
  desc = "$N. Se un lungo viaggio non ti pesa, avrei un compito per te: aiutare ancora Stormwind a riempire la sua biblioteca.$B$BDopo la grande guerra è caduto il vecchio regno di Alterac, che aveva una vasta collezione di libri. Che la città sia in rovina è una tragedia, ma è ancora più tragico che tutto il suo sapere sia andato perduto! Dobbiamo recuperare quello che possiamo.$B$BSouthshore è la cittadina più vicina alle Ruins of Alterac. Vai là e parla con Loremaster Dibbs: può indicarti le rovine e dirti quali libri ci potresti trovare.",
  obj = "Parla con Loremaster Dibbs a Southshore.",
  reward = "Ah sì, Milton, me lo ricordo. Un topo di biblioteca, non c'è dubbio. Che il cielo lo benedica.$B$BE ha ragione. Le Ruins of Alterac custodiscono ancora un sapere che rischia di andare perduto!$B$BAdesso ad Alterac ci vivono gli Ogres, e a loro della cultura importa ben poco.",
  en_title = "Southshore",
  en_obj = "Speak with Loremaster Dibbs in Southshore.",
}
T[539] = {
  title = "Battaglia di Hillsbrad",
  desc = "Dall'Hillsbrad Town Registry risulta che l'Azureload Mine è sotto il controllo dell'Alleanza, e che è anche una delle principali fonti di iron ore per le armerie dell'Alleanza.$B$BAbbiamo inferto un colpo decisivo alla città di Hillsbrad, ma l'Alleanza continua a sostenere e a proteggere con fervore l'Azureload Mine.$B$BLa miniera è proprio a sud di Hillsbrad. Va' lì e uccidi il caposquadra, un umano di nome Bonds, e con lui i suoi minatori. Così all'Alleanza dovrebbe arrivare un messaggio chiaro.",
  obj = "Uccidi Foreman Bonds e 10 Hillsbrad Miners e fai rapporto a Darthalia a Tarren Mill.",
  progress = "L'ordine di attaccare l'Azureload Mine l'hai ricevuto direttamente. Faresti meglio ad avere buone ragioni per startene a oziare a Tarren Mill, o ti decapiterò per tradimento.",
  reward = "La Dama Oscura sarà compiaciuta di sapere che ha una nuova miniera con cui armare i suoi soldati.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill.",
}
T[540] = {
  title = "Preservare il Sapere",
  desc = "Quegli ogres bestiali adesso vivono fra le rovine di Alterac, e rabbrividisco a pensare a cosa stiano facendo dei preziosi libri rimasti lì. Devi recuperare quello che puoi!$B$BEntra nelle Ruins of Alterac e cerca i tomi che gli ogres hanno saccheggiato. Portami tutto quello che trovi, ma cerca anche un libro in particolare: Il Braccio di Gri'lek. Contiene un antico sapere dei troll che devo apprendere, e le Ruins of Alterac sono l'ultimo posto dove, a quanto si sa, ce n'era una copia intatta.",
  obj = "Porta 5 Recovered Tomes e il Worn Leather Book che contiene Il Braccio di Gri'lek a Loremaster Dibbs a Southshore.",
  progress = "Mi piacerebbe poter cercare anch'io fra le rovine, ma temo che queste ossa non reggerebbero la salita sulle montagne. Allora, $N, come va la tua caccia al sapere?",
  reward = "Oh, li hai trovati! Splendido! Devo mettermi subito a studiare il Braccio di Gri'lek!",
  en_title = "Preserving Knowledge",
  en_obj = "Bring 5 Recovered Tomes and the Worn Leather Book containing The Arm of Gri'lek to Loremaster Dibbs in Southshore.",
}
T[541] = {
  title = "Battaglia di Hillsbrad",
  desc = "Nani che aiutano gli umani? Maledette quelle piccole bestie schifose.$B$BMetteremo alla prova la forza di questa cosiddetta Alleanza. Vedremo quanta voglia avranno quei piccoli mordicaviglie di aiutare gli umani, quando sentiranno la nostra ira. E sappiamo esattamente dove si trova la loro roccaforte da queste parti.$B$BNel sud-est di Hillsbrad, lungo il Thoradin's Wall, hanno messo su una caserma: Dun Garok. L'ultima missione di questa battaglia è assediare Dun Garok, $C. Il loro capo, Captain Ironhill, deve morire.",
  obj = "Va' a Dun Garok, uccidi 10 Montanari, 8 Riflemen, 4 Sacerdoti e Captain Ironhill e fai rapporto a Darthalia a Tarren Mill.",
  progress = "Dun Garok si rivela un ostacolo troppo grande per te, $C? E io che credevo ti fossi $Gaffermato:affermata; con valore a Hillsbrad.$B$BSe non sei all'altezza della missione che ti è stata affidata, troverò qualcun altro che sappia ottenere risultati migliori. E quanto a te, be', sono certa che alla Dama Oscura servono sempre altri becchini nelle Tirisfal Glades.",
  reward = "Le tue azioni sul campo di battaglia meritano i più alti elogi.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Travel to Dun Garok and kill 8 Mountaineers, 4 Riflemen, 2 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill.",
}
T[542] = {
  title = "Ritorno da Milton",
  desc = "Per un po' dovrò studiare il Braccio di Gri'lek, il libro che mi hai portato, ma sono sicuro che Milton non vede l'ora di aggiungere gli altri libri recuperati alla collezione di Stormwind.$B$BEcco, imballati e catalogati, i libri che hai raccolto nelle Ruins of Alterac. Riportali a Milton Sheaf a Stormwind e vedrai che te ne sarà grato.",
  obj = "Porta i Tomes of Alterac a Milton Sheaf a Stormwind.",
  progress = "$N, sei $Gtornato:tornata;! Com'è andata l'incursione ad Alterac? Hai riportato qualcosa?",
  reward = "Oh, cielo, cielo! Guarda qui! Non riesco a credere che siano sopravvissuti alla distruzione di Alterac. E pure a tutti quegli ogres!$B$BGrazie, $N. Grazie infinite! Hai aiutato a preservare il sapere umano e dai ancora più lustro alla Royal Library of Stormwind.",
  en_title = "Return to Milton",
  en_obj = "Bring the Tomes of Alterac to Milton Sheaf in Stormwind.",
}
T[543] = {
  title = "Il Perenolde Tiara",
  desc = "Il Perenolde Tiara è un antico cimelio dei \"nobili\" Perenolde — la famiglia che regnava su Alterac prima che quel regno cadesse in rovina. Si dice che l'abbiano realizzato maestri gioiellieri di Ironforge e che sia ornato con i più pregiati smeraldi.$B$BQuando Alterac è stata distrutta, il Diadema è andato perduto. Corre voce però che l'abbia trovato un Ogre Mage, Grel'borg the Miser, che ora vaga per le Ruins of Alterac in cerca di altri tesori.$B$BVorremmo che recuperassi per noi il diadema.",
  obj = "Porta il Perenolde Tiara a Remington Ridgewell a Stormwind.",
  progress = "Saluti, $N. Bada a non pestarmi i risvolti dei pantaloni. Quest'abito me l'hanno appena cucito su misura.",
  reward = "Ah, splendido. Certo, andrà pulito, ma ti sei davvero $Gsuperato:superata;, $N. Farò preparare il diadema perché trovi posto senza indugio nella nostra collezione.$B$BConverrai, ne sono certo, che la nostra gratitudine è grandiosa quanto la collezione stessa.",
  en_title = "The Perenolde Tiara",
  en_obj = "Bring the Perenolde Tiara to Remington Ridgewell in Stormwind.",
}
T[544] = {
  title = "Evasione al Contrario",
  desc = "Sono venuto a Tarren Mill a fare ricerche, ma adesso ho una crisi da risolvere. Qualche mese fa, vedi, quattro Forsaken sono fuggiti da Undercity. Hanno voltato le spalle ai loro fratelli e, peggio ancora... hanno derubato la Dama Oscura.$B$BSi sono introdotti in una camera blindata e hanno portato via quattro manufatti, oggetti che ai nostri speziali servivano per certi studi. Sylvanas li rivuole.$B$BDa Undercity sono scappati a Dalaran, e quei maghi li hanno messi in quarantena nel Lordamere Internment Camp.",
  obj = "Trova i traditori e recupera i loro manufatti, poi torna da me, $N.",
  progress = "Hai trovato i ladri? E soprattutto, hai trovato quello che hanno rubato?",
  reward = "Hai reso un grande servizio ai Forsaken, $N. Questi manufatti ci sono mancati molto.$B$BE fa piacere sapere che Kegan e gli altri traditori sono stati puniti.",
  en_title = "Prison Break In",
  en_obj = "Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill.",
}
T[545] = {
  title = "Pattuglie di Dalaran",
  desc = "La città di Dalaran, appena ricostruita, era circondata da un'enorme barriera magica, che poi è svanita misteriosamente. Cosa abbia fatto cedere una simile meraviglia poco mi importa; mi importa eccome, invece, che la loro periferia, ora scoperta, possa nascondere preziosi tesori magici: resti delle rovine su cui sorge la nuova città.$B$BMa a pattugliare la zona ci sono i maghi e i loro elemental slaves.$B$BDagli la caccia, quindi, e torna quando ne avrai ridotto abbastanza il numero.",
  obj = "Uccidi 6 Dalaran Summoners e 8 Elemental Slaves, poi torna da Magus Voidglare a Tarren Mill.",
  progress = "Hai già sfoltito le pattuglie di Dalaran attorno alle loro rovine?",
  reward = "Molto bene. Grazie, $N.$B$BAdesso siamo liberi di fare una visitina a Dalaran.",
  en_title = "Dalaran Patrols",
  en_obj = "Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill.",
}
T[546] = {
  title = "Souvenir di Morte",
  desc = "Ho sentito che Darthalia ti ha $Garruolato:arruolata; per la guerra contro gli umani di Hillsbrad. Quanto ti invidio. . .$B$BTu ti diverti — massacri umani, saccheggi il villaggio, terrorizzi gente innocente — e io me ne sto bloccato qui di guardia a Tarren Mill.$B$BMagari avrai pietà di un vecchio Deathguard come me? Vedi, colleziono human skulls, e tu con gli umani avrai da combattere ancora per un bel po'. Durante la lunga battaglia portami 30 teschi e ti ricompenserò come si deve.",
  obj = "Deathguard Samsa di Tarren Mill vuole 30 Hillsbrad Human Skulls.",
  progress = "Dunque $Gil fortunato:la fortunata; $N è di ritorno? Quanti umani hai massacrato oggi? Centinaia, spero proprio!$B$BHai qualche teschio per me?",
  reward = "Teschi preziosi! Che belli! Ecco quello che ti spetta, $N, come promesso!",
  en_title = "Souvenirs of Death",
  en_obj = "Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls.",
}
T[547] = {
  title = "Humbert's Sword",
  desc = "High Executor Darthalia mi ha mandato a tenere d'occhio Dun Garok da lontano, e avevo piantato il campo appena fuori vista. Ma la mattina, quando ho dovuto far bollire l'acqua, sono andato a raccogliere legna.$B$BQuando sono tornato, l'equipaggiamento non c'era più.$B$BA quanto pare sono passati di lì degli esploratori nani di Dun Garok e se lo sono portato via. La spada mi serve! Se riuscissi a recuperarla te ne sarei molto grato. Laggiù ci sono così tanti nani... sarà piuttosto difficile scovare il lurido ladruncolo che l'ha rubata.",
  obj = "Recupera la spada di Deathguard Humbert da Dun Garok e riportagliela a Tarren Mill.",
  progress = "Sei $Griuscito:riuscita; a riprendere la mia spada, $N? Se High Executor Darthalia scopre che stupidaggine ho fatto, mi appende alle travi.",
  reward = "L'hai trovata!$B$BAh, ora che ho di nuovo in mano la mia preziosa spada mi sento intero. Grazie mille!",
  en_title = "Humbert's Sword",
  en_obj = "Retrieve Deathguard Humbert's sword from Dun Garok and return it to him in Tarren Mill.",
}
T[549] = {
  title = "RICERCATI: Membri dello Syndicate",
  desc = "Per volere di Lady Sylvanas, tutti i membri dell'organizzazione nota come Syndicate sono ricercati, e li si vuole morti. Chiunque venga preso in custodia o fatto prigioniero sarà giustiziato sommariamente. A quanto risulta, in questo momento si stanno radunando fra le rovine di Durnholde Keep, a sud-est di Tarren Mill.$B$BChi porterà a High Executor Darthalia le prove delle proprie imprese riceverà una generosa ricompensa.",
  obj = "Uccidi 10 Syndicate Rogues e 10 Syndicate Watchmen. Torna da High Executor Darthalia a Tarren Mill per la tua ricompensa.",
  progress = "Non hai niente di meglio da fare che startene qui davanti a me, $C? Sono la Gran Esecutrice, e ho questioni più urgenti che fissare il tuo volto in putrefazione.",
  reward = "Eccellente, $C. Di questo passo, in men che non si dica queste terre saranno liberate dai parassiti dello Syndicate.",
  en_title = "WANTED: Syndicate Personnel",
  en_obj = "Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward.",
}
T[550] = {
  title = "Battaglia di Hillsbrad",
  desc = "Per il valore e la tenacia con cui hai combattuto nella Battaglia di Hillsbrad, ho scritto questo encomio che esalta le tue gesta eroiche sul campo, perché l'alto comando le riconosca.$B$BPorta questo encomio sigillato a Varimathras, nell'Undercity. Va' con orgoglio, $C.",
  obj = "Porta il Darthalia's Sealed Commendation a Varimathras nell'Undercity.",
  progress = "Cosa porta $Gun:una; $C dal campo di battaglia fin qui, nell'Undercity?",
  reward = "Dunque sei tu $Gil famigerato:la famigerata; $C che ha inferto un colpo così decisivo alle forze dell'Alleanza nelle Hillsbrad Foothills? La notizia delle tue gloriose imprese è arrivata in fretta fin qui, nell'Undercity.$B$BSe continuerai a mostrare in battaglia tanta capacità di comando e tanta perizia, nelle file della Dama Oscura ti aspetta un grande futuro.$B$BLa nostra minaccia principale resta l'esercito del Lich King's Scourge che scende da nord, ma il \"problema\" umano continua a ostacolare i nostri piani di battaglia. Tu, però, hai dimostrato che gli umani possono cadere, e cadranno.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Take Darthalia's Sealed Commendation to Varimathras in the Undercity.",
}
T[551] = {
  title = "L'Ensorcelled Parchment",
  desc = "Un sortilegio ha reso indecifrabile questa cartapecora, ma in cima al foglio si legge ancora una parola:$B$B$B      Nagaz",
  obj = "Porta l'Ensorcelled Parchment a Loremaster Dibbs a Southshore.",
  progress = "Oh. Hai qualcosa da farmi vedere? Spero qualche frammento di sapere raccolto lassù sulle montagne...",
  reward = "Altri appunti cifrati?$B$BMi piacerebbe avere il talento per decifrare tutti gli strani frammenti di scrittura che scendono alla spicciolata da Alterac. Ma temo di non saperne abbastanza.",
  en_title = "The Ensorcelled Parchment",
  en_obj = "Take the Ensorcelled Parchment to Loremaster Dibbs in Southshore.",
}
T[552] = {
  title = "La Vendetta di Helcular",
  desc = "A Master Helcular mancava poco per diventare un Lich, quando una folla di umani venuta a linciarlo ha scoperto il suo rifugio rituale sulle colline e lo ha ucciso brutalmente. E come se non bastasse, l'hanno sepolto nel cimitero di Southshore.$B$BUna simile mancanza di rispetto per il grande mago non si può accettare. Da suo apprendista, farò in modo che sulla città di Southshore cadano le piogge della vendetta.$B$BPer cominciare ci servirà l'Helcular's Rod. Gli Yeti hanno invaso il suo rifugio rituale, e di sicuro una di quelle bestie ce l'ha.",
  obj = "Recupera l'Helcular's Rod dagli Yeti e portala a Novice Thaivand a Tarren Mill.",
  progress = "Hai già recuperato l'Helcular's Rod? In questa regione gli Yeti sono così tanti che trovarla sarà molto difficile. Eppure ci serve, se vogliamo andare avanti.",
  reward = "L'hai trovata! Eccellente, $N!",
  en_title = "Helcular's Revenge",
  en_obj = "Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill.",
}
T[553] = {
  title = "La Vendetta di Helcular",
  desc = "Ecco, prendi la Rod of Helcular: ti servirà.$B$BPer il suo incantesimo più potente Helcular ha costruito 3 pire cerimoniali. La Flame of Azel e la Flame of Veraz sono nelle Foothill Caverns; la Flame of Uzel sta in una grotta sopra quelle caverne, più a nord, fra le montagne.$B$BLa Rod of Helcular va caricata con ciascuna delle tre fiamme. Finito il rituale, conficcala nella tomba di Helcular a Southshore, la città umana sorvegliatissima a sud. La vendetta sarà nostra!",
  obj = "Carica la Rod of Helcular con i poteri della Flame of Azel, della Flame of Veraz e della Flame of Uzel.$B$BConficca la verga carica nella tomba di Helcular a Southshore.",
  progress = "La tomba di Helcular brulica di energia mistica.",
  reward = "Dal terreno sale un forte rombo.",
  en_title = "Helcular's Revenge",
  en_obj = "Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel.$B$BDrive the charged rod into Helcular's grave in Southshore.",
}
T[554] = {
  title = "La Decifrazione di Stormpike",
  desc = "Prospector Stormpike è un maestro a decrittare e decifrare. Se gli porti la cartapecora che hai trovato, con un po' di fortuna ci capirà qualcosa. In questo periodo Stormpike studia al quartier generale dei Prospettori, a Ironforge.$B$BE quando lo vedi, digli che hai parlato con me — di recente gli sto mandando parecchi clienti.",
  obj = "Porta l'Ensorcelled Parchment a Prospector Stormpike a Ironforge.",
  progress = "Altre interruzioni?$B$BAh, questa cartapecora è coperta da un incantesimo molto intricato, intessuto con grande finezza. Scioglierlo posso, certo, ma ci vuole tempo. E per me il tempo è molto prezioso...$B$BE se te la comprassi?",
  reward = "Saggia decisione. Non credo che esista un altro studioso, a parte me, capace di tradurre questa cartapecora. E se quello che c'è scritto si rivelerà interessante, non temere. Ti manderò a chiamare.",
  en_title = "Stormpike's Deciphering",
  en_obj = "Take the Ensorcelled Parchment to Prospector Stormpike in Ironforge.",
}
T[555] = {
  title = "Soothing Turtle Bisque",
  desc = "Di Southshore imparerai almeno questo: abbiamo una delle cucine migliori a nord di Stormwind!$B$BPrendi ad esempio la mia ricetta segreta per la Zuppa Cremosa di Tartaruga: conosco gente che è venuta fin da Darkshire solo per gustarsene una scodella. A proposito, è da un po' che non riesco a prepararla. Una volta salivo di persona fino al Lake Lordamere, oltre Dalaran, a cacciare le Snapjaws, ma adesso è troppo pericoloso. Portami un po' di Turtle Meat delle Snapjaws del nord e delle Soothing Spices, e la preparo in un attimo!",
  obj = "Porta 10 pezzi di Turtle Meat e delle Soothing Spices al Chef Jessen a Southshore.",
  progress = "Sei $Griuscito:riuscita; a trovare gli ingredienti? Te lo dico io, questa terra non è più tranquilla come una volta. Ah, se solo questi disordini non fossero mai scoppiati. . .",
  reward = "Saranno tutti contentissimi: la Soothing Turtle Bisque del Chef Jessen torna in tavola!",
  en_title = "Soothing Turtle Bisque",
  en_obj = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Chef Jessen in Southshore.",
}
T[556] = {
  title = "Emblemi di Pietra",
  desc = "I maghi di Dalaran hanno un talento notevole: hanno dimestichezza con gli elementali, creature potenti di altre dimensioni, e li tengono sotto controllo con emblemi magici. Magus Voidglare vorrebbe studiarne qualcuno.$B$BVa' nei territori dei maghi di Dalaran, a ovest di Hillsbrad, e raccogli gli emblemi.$B$BQualsiasi cittadino di Dalaran può averli addosso, ma ti consiglio di cacciare al campo di internamento: è più sicuro di Dalaran vera e propria.",
  obj = "Porta 10 Worn Stone Tokens a Keeper Bel'varil a Tarren Mill.",
  progress = "Hai i Worn Stone Tokens, $N? Il Magus non vede l'ora di svelarne i segreti.",
  reward = "Andranno benissimo. La loro magia sembra svanita, ma sarà meglio che il Magus cominci i suoi esperimenti su campioni inerti come questi.$B$BGrazie, $N.",
  en_title = "Stone Tokens",
  en_obj = "Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill.",
}
T[557] = {
  title = "Bracciali Vincolanti",
  desc = "Il Magus avrà il suo da fare con gli emblemi di pietra che hai raccolto, ma prima o poi, lo so, vorrà qualche esemplare della loro controparte: i bracciali vincolanti. Si chiudono attorno ai polsi di elementali veri e propri e li legano al servizio del mago.$B$BVa' a caccia di elementali nelle rovine di Dalaran e prendi i loro Bracers of Earth Binding: il Magus ne sarà soddisfatto.",
  obj = "Porta 4 Bracers of Earth Binding a Keeper Bel'varil a Tarren Mill.",
  progress = "Salve, $N. Gli elementali non sono prede facili, ma so che sei all'altezza. Hai quei bracciali vincolanti?",
  reward = "Li hai trovati. Confido che gli elementali a cui hai tolto questi bracciali fossero ben disposti?$B$BMh... pare che la morte, oltre a fermarmi il cuore, mi abbia rubato anche i tempi comici.$B$BBe', grazie, $N. Servi bene il Magus, e quindi la Dama Oscura.",
  en_title = "Bracers of Binding",
  en_obj = "Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill.",
}
T[558] = {
  title = "Jaina's Autograph",
  desc = "Dicono che Lady Jaina Proudmoore di Theramore sia tra i più grandi eroi che l'Alleanza abbia mai avuto. Anch'io da grande voglio diventare un eroe dell'Alleanza!$B$BConosci Jaina, $N? Mi fai un favore, per piacere? Potresti farti fare il suo autografo per me? Io non saprei mica come chiederglielo, e poi probabilmente avrebbe troppo da fare per uno come me... ma tu! Tu sei $Gun avventuriero:un'avventuriera; proprio come lei! Scommetto che a te l'autografo lo fa subito!$B$BPer favore?",
  obj = "Vai a Theramore e cerca di ottenere l'autografo di Lady Jaina Proudmoore per il tuo pupillo.",
  progress = "Un giorno voglio essere un eroe proprio come Jaina... cioè, un eroe maschio.",
  reward = "WOW! L'autografo di Lady Jaina! Me l'hai preso! Grazie mille! E wow... ci ha scritto pure un messaggio personale — per me! Lo sapevo che era troppo forte. Magari un giorno la ringrazierò io stesso... quando sarò un eroe dell'Alleanza!$B$BSei $Gil migliore:la migliore;, $N. Grazie di essere $Gstato:stata; così $Gbuono:buona; con me.",
  en_title = "Jaina's Autograph",
  en_obj = "Travel to Theramore to see about getting Lady Jaina Proudmoore's autograph for your ward.",
}
T[559] = {
  title = "La Prova di Farren",
  desc = "Ci crederesti, $N? Tutti i murlocs che abbiamo ucciso non sono bastati a Redpath — oh, su, non fare $Gil modesto:la modesta;, mi hai dato una mano anche tu. Adesso vuole la prova che li abbiamo uccisi: devo mozzare murloc heads fredde e viscide e portargliele, perché le approvi.",
  obj = "Raccogli 10 Murloc Heads dai murlocs di Western Strand per Lieutenant Farren Orinelle a Southshore.",
  progress = "Ce le hai, quelle teste, $N?",
  reward = "Oh, per l'Amore della Luce... stanno gocciolando per terra.$B$BQuelle cose proprio non riesco a toccarle. Coi pesci non ho problemi, ma quando gli spuntano le gambe e si mettono ad andarsene in giro... Te lo dico io: è da settimane che non mangio pesce, e a Southshore vuol dire mangiare ben poco.",
  en_title = "Farren's Proof",
  en_obj = "Collect 10 Murloc Heads from the murlocs on the Western Strand for Lieutenant Farren Orinelle in Southshore.",
}
T[560] = {
  title = "La Prova di Farren",
  desc = "Sai, $N, queste teste preferirei proprio non portarle io... Già che ce le hai in mano, ti dispiacerebbe consegnarle tu a Redpath al posto mio?",
  obj = "Consegna il sack of murloc heads a Marshall Redpath a Southshore.",
  progress = "Saluti, $Gcittadino:cittadina;. Sei $Gvenuto:venuta; a dare man forte nella difesa di Southshore?",
  reward = "Sei $Gil galoppino:la galoppina; di Farren, giusto?$B$BSe hai aiutato Farren a procurarsi queste teste, ti ringrazio. Southshore, per restare al sicuro, ha bisogno di impegno e di gente che lavori sodo.",
  en_title = "Farren's Proof",
  en_obj = "Deliver the sack of murloc heads to Marshall Redpath in Southshore.",
}
T[561] = {
  title = "La Prova di Farren",
  desc = "Per favore, avverti Lieutenant Orinelle che vorrei che ora si dedicasse ai naga che infestano l'Eastern Strand. Appena avrà dei risultati, che me li venga a riferire di persona.",
  obj = "Parla con Lieutenant Farren Orinelle a Southshore.",
  reward = "I naga, eh? Redpath avrà appena ricevuto le stesse notizie che ho avuto io... Ah! Non si farà promuovere sulle mie spalle. Ti spiego.",
  en_title = "Farren's Proof",
  en_obj = "Speak with Lieutenant Farren Orinelle in Southshore.",
}
T[562] = {
  title = "Verso Stormwind!",
  desc = "Il mio vecchio mentore, nella guardia cittadina di Stormwind, mi ha mandato a dire che l'Alto Comando dell'Alleanza comincia a preoccuparsi per la minaccia dei naga. A quanto ha sentito, chi si rende utile su questo fronte ha buone probabilità di essere promosso — o almeno trasferito.$B$BSolo che c'è un piccolo problema... Ai naga non sono in grado di tenere testa, $N. Oh, certo, una rissa fra ubriachi in una taverna la saprei sedare, o un mendicante attaccabrighe lo saprei portare via, ma i naga sono troppo per me. Devi aiutarmi, $N!",
  obj = "Uccidi 10 Daggerspine Shorehunters e 10 Daggerspine Sirens per Lieutenant Farren Orinelle a Southshore.",
  progress = "Ho già pronta una lettera da spedire a Major Samuelson, a Stormwind. Mancano solo i risultati.",
  reward = "Ora che i naga sono sistemati a Southshore, il trasferimento sarà cosa fatta. Rivedrò Stormwind... e mi lascerò alle spalle questo porto forsaken dalla Luce.",
  en_title = "Stormwind Ho!",
  en_obj = "Kill 10 Daggerspine Shorehunters and 10 Daggerspine Sirens for Lieutenant Farren Orinelle in Southshore.",
}
T[563] = {
  title = "Trasferimento",
  desc = "Far leggere il rapporto non dovrebbe essere un problema. Il nuovo capitano della guardia, Major Samuelson, mi ha fatto da mentore ai tempi in cui ero di stanza a Stormwind. Gli darà una scusa più che buona, credo, per farmi rientrare in città. Però dovrai portarglielo tu... non vorrei che il vecchio Redpath se ne accorgesse.",
  obj = "Consegna il rapporto di Farren a Major Samuelson a Stormwind Keep.",
  progress = "Saluti, $Gcittadino:cittadina;. Cosa può fare per te la guardia cittadina di Stormwind?",
  reward = "Questo cos'è? Ah... così il mio allievo attento si è occupato del problema dei naga a Southshore. Grazie di avermelo portato, il mese prossimo, quando rivedrò le assegnazioni del personale, ne terrò senz'altro conto.",
  en_title = "Reassignment",
  en_obj = "Deliver Farren's report to Major Samuelson in Stormwind Keep.",
}
T[564] = {
  title = "Una Minaccia Costosa",
  desc = "Non c'è niente che mi secchi di più che perdere 'sti bei cavalli. E credimi, ne abbiamo persi parecchi, fra quei rognosi non morti schifosi, quella dannata banda dello Syndicate e tutti gli altri farabutti buoni a nulla che vengono a ficcare il naso da 'ste parti.$B$BMa lo giuro sulla tomba del mio vecchio nonno: per i nostri cavalli non c'è minaccia più grossa di quei Mountain Lions lassù ad Alterac. Non fanno che scendere giù dalle colline a rendermi la vita difficile!$B$BTi credi $Gun eroe:un'eroina;? E allora vai a fare qualcosa!",
  obj = "Darren Malvew of Southshore vuole che tu uccida 8 Mountain Lions e 10 Hulking Mountain Lions.",
  progress = "I Mountain Lions ci ammazzano i cavalli a destra e a manca, e tu stai qui a blaterare del tempo e di chissà cos'altro.$B$BDovrei andarmi a cercare un eroe vero. Più ammazzare e meno chiacchiere.",
  reward = "Questa sì che è una gran bella notizia! Per sistemare quelle bestie avrei dovuto trovarmi un eroe di guerra come si deve fin dal primo giorno. Il tuo papà sarebbe fiero di te, $N.",
  en_title = "Costly Menace",
  en_obj = "Darren Malvew of Southshore wants you to kill 8 Mountain Lions and 10 Hulking Mountain Lions.",
}
T[565] = {
  title = "Il Yeti Fur Cloak di Bartolo",
  desc = "Io, il grande Bartolo, creerò per te il Yeti Fur Cloak: famoso in tutto il mondo, rinomato in tutta l'Alleanza!$B$BFa' pure il giro del pianeta e trovane uno migliore, se ci riesci. Oh, aspetta, che dici, $Gpiccolo:piccola; $R? \"Bartolo, non esiste mantello più bello!\" Sì, sì! L'ho già sentita, questa.$B$BA Bartolo servono un Rotolo di Lana, un Hillman's Cloak fatto da un abile conciatore, del Fine Thread e naturalmente della Yeti Fur! Portami tutto e sarai $Gun cliente felice:una cliente felice;!",
  obj = "Porta a Bartolo Ginsetti di Southshore un Rotolo di Lana, un Hillman's Cloak, Fine Thread e 10 ciuffi di Yeti Fur.",
  progress = "Eccoti $Gtornato:tornata; dal grande Bartolo. Forse hai finito di raccogliere tutto il necessario per il tuo Yeti Fur Cloak? O forse ti piace soltanto crogiolarti nella grandezza di me, Bartolo!",
  reward = "È giunta l'ora che il grande Bartolo faccia le sue magie! Non mi serve un bastone da stregone, né una verga da mago. Io, il grande Bartolo, le magie le faccio con un semplice ago e filo!",
  en_title = "Bartolo's Yeti Fur Cloak",
  en_obj = "Bring Bartolo Ginsetti of Southshore a Bolt of Wool, a Hillman's Cloak, Fine Thread and 10 clumps of Yeti Fur.",
}
T[566] = {
  title = "RICERCATO: Baron Vardus",
  desc = "Per ordine di High Executor Darthalia, l'umano noto come Baron Vardus è ricercato per crimini contro i Forsaken. È noto che Vardus è un membro di alto rango dell'organizzazione chiamata Syndicate.$B$BL'ultima volta è stato avvistato nelle Uplands delle Alterac Mountains, a nord di Tarren Mill.$B$BLo si vuole morto. Per riscuotere la ricompensa, porta a High Executor Darthalia le prove che è stato ucciso.",
  obj = "Uccidi Baron Vardus e consegna la sua testa a High Executor Darthalia a Tarren Mill.",
  progress = "Ah, $N. Sei $Gvenuto:venuta; a riscuotere la taglia sulla testa di Baron Vardus, forse?",
  reward = "Un lavoro produttivo, il tuo, $N. Con Baron Vardus morto, i capi dello Syndicate sono sempre meno: la loro resistenza e il fastidio che danno hanno i giorni contati.",
  en_title = "WANTED: Baron Vardus",
  en_obj = "Kill Baron Vardus and deliver his head to High Executor Darthalia in Tarren Mill.",
}
T[567] = {
  title = "Pericolosi!",
  desc = "Pericolosi!$B$BI seguenti umani di Hillsbrad sono stati giudicati pericolosi, e High Executor Darthalia ha posto su di loro una taglia:$B$BClerk Horrace Whitesteed. Ricercato per l'omicidio di Deathguard Toma.$B$BCitizen Wilkes. Ricercato per l'omicidio di Apothecary Eli.$B$BMiner Hackett. Ricercato per l'omicidio di Deathstalker Fry.$B$BFarmer Kalaba. Ricercata per aver teso un'imboscata ai rifornimenti in arrivo da Undercity.$B$BTutti questi nemici si nascondono, e non sarà facile trovarli. La notizia della loro morte verrà ricompensata.",
  obj = "High Executor Darthalia of Tarren Mill offre una taglia su Clerk Horrace Whitesteed, su Citizen Wilkes, su Miner Hackett e su Farmer Kalaba.",
  progress = "Sì?",
  reward = "Sei proprio $Gun:una; $Gcacciatore:cacciatrice; di taglie, $C. Ben fatto.",
  en_title = "Dangerous!",
  en_obj = "High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.",
}
T[568] = {
  title = "La Difesa di Grom'gol",
  desc = "Throm'ka, $C!$B$BArrivi a Grom'gol proprio al momento giusto. Comando il campo base del Capoguerra qui nella giungla, e l'onore mi impone di proteggere ogni membro dell'Orda. Alcuni abitanti del posto ci stanno intralciando la missione: portare i rifornimenti a Stonard senza pericoli.$B$BIl tuo compito è sfoltire la popolazione di raptor fuori da Grom'gol. Quando avrai fatto buoni progressi, torna da me: ti darò un nuovo incarico.",
  obj = "Commander Aggro'gosh del campo base di Grom'gol vuole che tu uccida 15 Lashtail Raptors.",
  progress = "I raptor del posto intralciano ancora i nostri rifornimenti, $C.",
  reward = "Hai fatto il tuo dovere con onore, $C.",
  en_title = "The Defense of Grom'gol",
  en_obj = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors.",
}
T[569] = {
  title = "La Difesa di Grom'gol",
  desc = "Quando siamo arrivati in questa giungla non volevamo fare guerra alle tribù del posto. Rifornire Stonard è la nostra missione, e viene prima di tutto. Ma sono nate delle complicazioni. Una banda di ogres della zona si è presa le Mizjah Ruins, a sud-est di Grom'gol, e nonostante gli avvertimenti continua a tendere imboscate alle nostre carovane di rifornimenti.$B$BTocca a te occuparti di questi ogres poco collaborativi.$B$BRaggiungi le rovine e cerca di cacciarli dalla zona. Male che vada, sarà un avvertimento deciso.",
  obj = "Commander Aggro'gosh del campo base di Grom'gol vuole che tu uccida 10 Ogre Brutes e 5 Ogre Witch Doctors.",
  progress = "Hai già concluso qualcosa con gli ogres delle Mizjah Ruins, $C?",
  reward = "Ben fatto. Hai servito il Capoguerra con onore.",
  en_title = "The Defense of Grom'gol",
  en_obj = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors.",
}
T[570] = {
  title = "L'Incantamento di Mok'thardin",
  desc = "L'Orda deve comprendere il potere della magia della giungla, e poi imbrigliarlo. Finora i miei rituali hanno avuto successo, e posso lanciare incantamenti molto potenti. Per te, $Gvaloroso:valorosa; $C, creerò un oggetto davvero speciale.$B$BPortami alcuni artigli di Shadowmaw Panther e una zanna di Tigre. E non una zanna qualsiasi: dev'essere intatta.$B$BLe belve si aggirano per tutta la giungla, ma qui vicino, a sud-est, ne troverai alcune sulla sponda del fiume di fronte alle Mizjah Ruins.",
  obj = "Far Seer Mok'thardin, al campo base di Grom'gol, vuole 8 Shadowmaw Claws e una Pristine Tigress Fang.",
  progress = "Che notizie mi porti?",
  reward = "Conosci bene la giungla, $N: questi esemplari saranno perfetti. Ringrazierò gli spiriti per aver sacrificato belve così splendide alla causa dell'Orda.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang.",
}
T[571] = {
  title = "L'Incantamento di Mok'thardin",
  desc = "Quello che ti chiedo ora sarà molto difficile da ottenere.$B$BPer tenere fermi al loro posto tutte queste penne, gli artigli e la zanna intatta mi serve un legaccio magico, e va bene soltanto un aged gorilla sinew.$B$BLo troverai solo su un Elder Mistvale Gorilla: di solito vanno in cerca di cibo a est di Booty Bay.$B$BIl tendine dev'essere perfetto. Forse dovrai ucciderne parecchi prima di trovare quello giusto, ma la caccia varrà davvero la pena.",
  obj = "Porta un Aged Gorilla Sinew a Far Seer Mok'thardin a Grom'gol.",
  progress = "La fortuna ti ha sorriso, $N? Sei $Griuscito:riuscita; a procurarti un aged gorilla sinew?",
  reward = "È proprio un tendine ideale, $N. Presto i tuoi sforzi saranno ripagati.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Bring an Aged Gorilla Sinew to Far Seer Mok'thardin in Grom'gol.",
}
T[572] = {
  title = "L'Incantamento di Mok'thardin",
  desc = "Gli oggetti che hai raccolto dalle belve feline della Valle sono solo il primo ingrediente di un potente oggetto incantato. Questi ninnoli della giungla, uniti al mio rituale sciamanico, ti daranno uno strumento molto utile per aiutare l'Orda e il Capoguerra.$B$BOra però devi raccogliere per me delle Jungle Stalker Feathers: per tradizione, queste belve le portano sui bracciali. Subito a sud di Grom'gol, non lontano dalla grande arena, troverai una tribù di raptors.",
  obj = "Porta 10 Jungle Stalker Feathers a Far Seer Mok'thardin, al campo base di Grom'gol.",
  progress = "La raccolta ha dato i suoi frutti?",
  reward = "Davvero eccellente. Le preparo subito.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp.",
}
T[573] = {
  title = "L'Incantamento di Mok'thardin",
  desc = "Per completare l'incantamento manca solo un ultimo reagente.$B$BA sud, verso la costa occidentale, in alto sopra le scogliere, c'è un'Holy Spring, molto contesa fra studiosi religiosi e mistici: ogni razza di Azeroth sostiene che quelle acque siano state rese divine per il proprio popolo.$B$BEcco la mia ultima richiesta: portami l'Holy Spring Water. Ma fai attenzione: una spedizione di esploratori naga si è spinta fino alla sorgente, e dovrai occuparti anche di loro.",
  obj = "Far Seer Mok'thardin of Grom'gol ha bisogno dell'Holy Spring Water. Vuole anche che tu uccida 10 Naga Explorers.",
  progress = "Sono quasi pronto per completare l'incantamento. Hai eseguito i miei ordini?",
  reward = "Con quest'Holy Spring Water il girocollo cerimoniale è pronto per essere incantato.$B$BPortalo con orgoglio, $N, nel nome del Capoguerra e in difesa della possente Orda.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Far Seer Mok'thardin of Grom'gol needs Holy Spring Water.  He also wants you to kill 10 Naga Explorers.",
}
T[574] = {
  title = "Forze Speciali",
  desc = "Ora che le sue truppe regolari si sono assottigliate, devi vedertela con i suoi uomini meglio addestrati. Quando non sono nelle terre selvagge a massacrare i nostri soldati ribelli, stanno in fondo al Kurzen Compound, in una caverna che chiamano lo Stockpile.$B$BMolti dei soldati di Kurzen li conosco di persona: sono abili, leali e crudeli. Quello che ti affido non è un compito facile, $N.$B$BQuando li avrai sconfitti, fai rapporto a Lieutenant Doren, il mio comandante. Vorrà sentirlo dalla tua voce.",
  obj = "Uccidi 10 Kurzen Commandoes e 6 Kurzen Headshrinkers.$B$BFai rapporto a Lieutenant Doren all'Accampamento dei Ribelli.",
  progress = "Sergeant Yohwa mi dice che sei abile e $Gcoraggioso:coraggiosa;, $C. Hai qualcosa da riferirmi?",
  reward = "$N. Sergeant Yohwa ha creduto nelle tue capacità, e io mi fido di lei. Hai inflitto alle forze di Kurzen una sconfitta che va quasi oltre quello che osavamo sperare. Temevo che noi ribelli fossimo soli, e da soli non avremmo mai potuto tenere testa al genio del Colonnello.$B$BForse abbiamo ancora una speranza di sopravvivere.",
  en_title = "Special Forces",
  en_obj = "Kill 10 Kurzen Commandoes and 6 Kurzen Headshrinkers.$B$BReport to Lieutenant Doren at the Rebel Camp.",
}
T[575] = {
  title = "Domanda e Offerta",
  desc = "\"Il miglior conciatore dei South Seas e dei mondi vecchi e nuovi.\" Così mi chiamano. Io! Drizzlik! Il miglior con... Ehm. Dunque.$B$BI miei articoli in pelle sono famosi in lungo e in largo come i più raffinati, la scelta degli intenditori!$B$BDirector Riddlevox of the Tinkers' Union mi ha appena ordinato una dozzina dei suoi stivali preferiti della linea Excelsior. I nostri più venduti, a dire il vero.$B$BPer partire dalla forma di base mi serviranno delle crocolisk skins, prese dagli esemplari che stanno lungo il fiume, nel nord di Stranglethorn.",
  obj = "Porta 2 Large River Crocolisk Skins a Drizzlik a Booty Bay.",
  progress = "La mia attrezzatura è tutta pronta, $N: mancano solo quelle pelli. Non vorremo mica far aspettare Riddlevox.$B$BLasciare insoddisfatto il capo inventore della Tinkers' Union non conviene a nessuno.",
  reward = "Queste pelli dovrebbero andare. La qualità conta poco, visto che diventeranno lo strato interno degli stivali, ma devono comunque essere comode.$B$BSe sono un po' troppo rigide, le ammorbidirò con del sangue di tigre. Trucchi del mestiere, sai?",
  en_title = "Supply and Demand",
  en_obj = "Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay.",
}
T[576] = {
  title = "Tieni gli Occhi Aperti",
  desc = "Ohè! Chi va là?$B$BArgh, senza il mio occhio incantato speciale non valgo niente. Già perdere gli occhi in battaglia era stato brutto! Ma per un colpo di fortuna abbiamo attraccato a Menethil, e un mago di passaggio ha incantato un occhio di vetro speciale che mi ha ridato la vista.$B$BIeri sera, mentre uscivo, mi sono ritrovato addosso alcuni Bloodsail Buccaneers. E mi hanno fregato l'occhio, proprio così! Pare che quei tizi si siano spinti fino a Booty Bay.$B$BLo aiuteresti, un vecchio lupo di mare, a riprendersi l'occhio?",
  obj = "Dizzy One-Eye a Booty Bay vuole che tu recuperi il suo occhio dai Bloodsail Buccaneers.",
  progress = "Ohilà, $Gragazzo mio:ragazza mia;! Non ci vedrò, ma il tuo odore lo sento da mezzo porto di distanza.$B$BMi servirebbe proprio riaverlo, l'occhio. Quando il Capitano scoprirà che è finito nelle mani di quei lerci Bloodsail Buccaneers, mi farà passare sotto la chiglia.$B$BA che serve una vedetta che non ci vede? La coffa era casa mia... senza i miei fanali mi andrebbe già bene se mi lasciassero strofinare la sentina.",
  reward = "Corpo di mille balene e balene di mille corpi! Il mio bellissimo occhio, l'hai trovato! Vediamo se la mia bella ci sta ancora.$B$B$N in vista! Accidenti, ci vedo!!",
  en_title = "Keep An Eye Out",
  en_obj = "Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers.",
}
T[577] = {
  title = "Richiede Montaggio",
  desc = "Beh, la forma base degli stivali l'ho fatta e stanno venendo su bene, ma le pelli che mi hai portato non bastano del tutto per gli strati interni.$B$B\"E adesso che facciamo, Drizzlik?\" Di sicuro è la domanda che hai sulle labbra, e beh, che fortuna che tu stia parlando proprio con Drizzlik, perché sta per dirtelo lui che cosa faremo!$B$BTanto gli strati interni non si vedranno mai davvero, quindi per imbottire gli stivali prenderemo qualche pelle più spessa ed economica dai crocolischi intorno al Lake Nazferiti.",
  obj = "Porta 5 Pelli di Snapjaw Crocolisks a Drizzlik a Booty Bay.",
  progress = "Stivali di cuoio Excelsior di Drizzlik, lavorazione finissima, stivali in pelle di saltwater crocolisk di alta qualità al cento per cento. Migliori di così non ce ne sono!$B$BDifficile fare meglio di una descrizione così entusiasta, no?$B$BA meno che tu non abbia quelle pelli per me, magari?",
  reward = "I miei stivali... sono come le salsicce, $N. Belli da vedere, buoni da mangiare. Io ti dico che dentro ci sono solo gli ingredienti e le carni migliori, tu le mangi e ti piacciono.$B$BÈ più sicuro — e più piacevole — fidarti di me e basta, senza chiedere troppo nei dettagli cosa c'è dentro davvero.",
  en_title = "Some Assembly Required",
  en_obj = "Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay.",
}
T[578] = {
  title = "La Stone of the Tides",
  desc = "Se un mago goblin e dei water elementals infestano davvero l'isola, forse vuol dire che la Stone of the Tides può essere mia!$B$BVoglio che trovi quest'isola infestata... e che scopra cosa ci sta succedendo. Oh, e se magari vuoi saperne di più sulla Stone of the Tides, porta questo buono alla Stormwind Library, lì dovrebbero riuscire a trovarti una copia del libro dove ho letto la leggenda la prima volta.$B$BPossibile che Gazban abbia scoperto davvero la Pietra...?",
  obj = "Trova l'isola infestata per Baron Revilgaz a Booty Bay.",
  progress = "I troll avevano davvero degli oggetti magici straordinari, $N. E adesso, forse, ho l'occasione di aggiungerne uno alla mia vasta collezione. Sei $Griuscito:riuscita; a scoprire da dove viene la voce?",
  reward = "Allora le storie erano vere! Incredibile!$B$BPerò, se vogliamo recuperarla, dovremo trovare il modo di vincere la maledizione della Stone of the Tides. Quella è roba di magia, ci servirà uno di quei maghi che ci dia una mano.",
  en_title = "The Stone of the Tides",
  en_obj = "Find the haunted island for Baron Revilgaz in Booty Bay.",
}
T[580] = {
  title = "Il Grog Perduto di Whiskey Slim",
  desc = "Eravamo al largo delle Overlook Cliffs, con le vecchie Hinterlands in lontananza, e sbevazzavamo di brutto. Credevo che i mari ci ingoiavano interi.$B$BDi coraggio in bottiglia Ol' Slim sa tutto! Il Capitano aveva una cassa di Pupellyverbos Port, requisita a un corsaro che andava a Stormwind.$B$BCosì, quando al largo delle Hinterlands è arrivata quella tempesta, mi sono attaccato al grog. Un'ondata enorme ci ha presi in pieno e ha sbattuto le bottiglie fuori bordo. Se non mi aiuti a riprenderle, il Capitano mi farà assaggiare il gatto a nove code!",
  obj = "Whiskey Slim a Booty Bay vuole che tu gli porti le bottiglie di Pupellyverbos Port che ha perso.",
  progress = "Che io possa affondare! Mi sta quasi finendo la roba da bere! Il Capitano sta per levare l'ancora, e Ol' Slim resterà all'asciutto come il Tanaris Desert. E quando scoprirà che il suo porto è sparito... accidenti!",
  reward = "Corpo di mille balene! Il grog del Capitano, l'hai trovato!$B$BTi devo un favore enorme, $Gamico:amica;.$B$BFuori pare che si stia preparando una tempesta. Magari, mentre aspettiamo che passi, mi tengo al caldo con una di queste bottiglie....",
  en_title = "Whiskey Slim's Lost Grog",
  en_obj = "Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost.",
}
T[581] = {
  title = "Caccia a Yenniku",
  desc = "Una sventura, c'è. Una sventura che è caduta sul figlio minore del mio capo, Yenniku. Come vuole l'usanza del nostro popolo, l'hanno affidato ai Gurubashi Trolls of Zul'Gurub, ma poi la mia tribù, la Darkspear, se n'è andata con l'orco Thrall, e il povero Yenniku l'abbiamo perso. Dalla lontana Orgrimmar mi hanno rimandato a Stranglethorn a cercare il figlio del mio capo.$B$BE secondo me ce l'ha la tribù Bloodscalp.$B$BSe vuoi aiutarmi, dai la caccia ai Bloodscalp: li puoi trovare a nord. Raccogli le loro zanne e poi torna da me.",
  obj = "Porta 9 Bloodscalp Tusks a Nimboya a Grom'gol Base Camp.",
  progress = "$C. Fammi vedere che la tribù Bloodscalp ora è la tua preda.$B$BFammi vedere i trofei.",
  reward = "Buone zanne, queste, $N. Mi dimostri che la forza per cacciare i Bloodscalp ce l'hai.$B$BEd è un bene, perché con loro la caccia non è finita.",
  en_title = "Hunt for Yenniku",
  en_obj = "Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.",
}
T[582] = {
  title = "Caccia alle Teste",
  desc = "Dobbiamo scoprire se Yenniku è morto.$B$BUccidi i Bloodscalp Headhunters e prendigli gli Shrunken Heads. Di teschi devi portarmene molti, molti, e io li esaminerò per essere sicuro che fra questi non ci sia quello di Yenniku.$B$BE se Yenniku l'hanno ucciso i Bloodscalp, che una maledizione di 600 anni cada sullo spirito del loro capo, Gan'zulah!$B$BVa', $N. Di Headhunters ne puoi trovare molti fra le rovine di Zuuldaia e di Zul'Kunda, lungo la costa a nord.",
  obj = "Porta 20 Shrunken Heads a Nimboya a Grom'gol Base Camp.",
  progress = "$N. Temo per il figlio del nostro capo. Ce li hai gli shrunken heads da farmi esaminare?",
  reward = "Grazie, $N. Esaminerò questi teschi per essere sicuro che l'ascia del cacciatore di teste abbia risparmiato il povero Yenniku.",
  en_title = "Headhunting",
  en_obj = "Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.",
}
T[583] = {
  title = "$GBenvenuto:Benvenuta; nella Giungla",
  desc = "$GBenvenuto:Benvenuta; a Stranglethorn!$B$BForse non lo sai, ma quel nano laggiù è nientemeno che Hemet Nesingwary, celebre eroe di guerra dell'Alleanza e maestro della caccia grossa. Non è tipo da accogliere gli sconosciuti nel suo accampamento, ma tu, $C, hai l'aria di chi ha combattuto parecchio.$B$BMaster Nesingwary è un veterano di molte battaglie, e per chi è un eroe come lui ha un debole.$B$BVa' a parlargli. Magari ti dà qualche consiglio di caccia.",
  obj = "Parla con Hemet Nesingwary.",
  reward = "È davvero un gran piacere conoscerti, $N. Era da un po' che non vedevo $Gun:una; $C da queste parti.$B$BMi sono unito a questa spedizione per un solo scopo: cacciare una bestia grande e sfuggente. Visto che sei una specie di $Geroe:eroina;, sono disposto a portarti a caccia con me, ma prima dovrai dimostrare quanto vali.$B$BIo ti insegnerò l'arte di uccidere i raptor, Ajeck ti addestrerà a cacciare le tigri e Sir Erlgadin è un maestro nel seguire le tracce delle pantere.$B$BMostrami di cosa sei capace e ti lascerò unirti alla grande caccia.",
  en_title = "Welcome to the Jungle",
  en_obj = "Speak with Hemet Nesingwary",
}
T[584] = {
  title = "Teste del Bloodscalp Clan",
  desc = "Yenniku non era fra le teste, e ne ringrazio il Grande Serpente. Ma siamo ancora lontani dal trovarlo.$B$BDobbiamo sapere la verità, e temo che la sappiano solo il capo dei Bloodscalp e il suo stregone. Sono nemici della tribù Darkspear e di loro volontà non parleranno: la verità dovremo strappargliela dalle labbra morte!$B$BPortami le teste di Gan'zulah e di Nezzliok the Dire e mettile in questo calderone.$B$BStanno nel cuore di Zul'Kunda. Porta qui le loro teste... poi li faremo parlare.",
  obj = "Porta la Gan'zulah's Head e la Nezzliok's Head al calderone ribollente presso il Grom'gol Base Camp.",
  progress = "Nel calderone ribolle un brodo verdastro.",
  reward = "Metti nel calderone le teste di Gan'zulah e di Nezzliok...",
  en_title = "Bloodscalp Clan Heads",
  en_obj = "Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp.",
}
T[585] = {
  title = "A Colloquio con Nezzliok",
  desc = "<La testa di Nezzliok parla.>$B$BÈ vero. So dove è stato portato il figlio dei Darkspears. Hai avuto la meglio su di me e hai imprigionato il mio spirito, ma non dirò nulla se prima non verrò placato!$B$BI Bloodscalps sono in guerra con gli Skullsplitters. Per ottenere il mio favore, ruba agli Skullsplitters 3 dei teschi che conservano come trofei e mettili qui con noi, così il mio spirito avrà degli schiavi nel Nether. Il primo deve venire dal mucchio di trofei di Balia'mah, il secondo da Ziata'jai e l'ultimo da Zul'Mamwe.",
  obj = "Porta un Balia'mah Trophy, uno Ziata'jai Trophy e uno Zul'Mamwe Trophy al Bubbling Cauldron a Grom'gol Base Camp.",
  progress = "Attendo i teschi...",
  reward = "Sì. Questi mi serviranno bene. Quando il mio spirito sarà libero, entrerò nel Nether con tre ottimi servitori!$B$BFai onore al tuo clan $R, e mi hai placato.",
  en_title = "Speaking with Nezzliok",
  en_obj = "Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp.",
}
T[586] = {
  title = "A Colloquio con Gan'zulah",
  desc = "<La testa di Gan'zulah parla.>$B$B$GMaledetto:Maledetta; te! E maledetti i tuoi antenati!!$B$BSolo il sangue e la vendetta possono placare la mia rabbia, quindi se è questo che vuoi, allora... fai così:$B$BGettati nel cuore degli Skullsplitters, a est. Uccidi i più feroci tra loro e, se sopravvivi... allora va' a schiantarti contro il loro capo, Ana'thek the Cruel. Hah! Portami la sua armatura in frantumi, se ci riesci!$B$BChe lui ti strappi gli arti e ti lasci a marcire, $Gdivorato:divorata; dai mangiatori di carogne.",
  obj = "Uccidi 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters e 4 Skullsplitter Berserkers.$B$BPorta la Broken Armor of Ana'thek al Bubbling Cauldron a Grom'gol Base Camp.",
  progress = "Anche se la carne mi si stacca bollendo dal cranio, sento ancora l'odore della tua paura.$B$BHah! Non porterai mai a termine il mio compito...",
  reward = "Non voglio crederci, ma non posso negare quello che hai fatto. E la mia rabbia si placa, ora che Ana'thek è sconfitto.$B$BLa tua potenza ti spingerà a grandi imprese, $N. Ma un giorno... ti rivedrò nel Nether e torneremo a misurare le nostre forze.$B$BTi aspetterò.",
  en_title = "Speaking with Gan'zulah",
  en_obj = "Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers.$B$BBring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp.",
}
T[587] = {
  title = "Questione di Fiuto",
  desc = "Ah, la vita di mare. Non dico che sia la bella vita, ma è la mia.$B$BQuando sbarco in porto mi piace procurarmi una buona bottiglia di grog e del tabacco da fiuto di prima scelta. Brutte abitudini, ma un pirata senza vizi che pirata è, giusto?$B$BPuoi immaginare come mi si è spezzato il cuore quando ho scoperto che l'erborista qui in città l'ha finito. Dice che gli hanno rubato il carico quei dannati Bloodsail Raiders.$B$BScommetto che $Gun:una; $C senza paura come te saprebbe convincerli a dividere la merce, eh?",
  obj = "Deeg, a Booty Bay, vuole che gli porti 15 dosi di Snuff.",
  progress = "Allora, compare, hai avuto fortuna con la merce?",
  reward = "Ben fatto, $N! E giusto in tempo, prima che io salpi! Non so come ringraziarti, $Gvecchio amico:vecchia amica;.",
  en_title = "Up to Snuff",
  en_obj = "Deeg in Booty Bay wants you to bring him 15 shares of Snuff.",
}
T[588] = {
  title = "Il Destino di Yenniku",
  desc = "<Nezzliok parla.>$B$BHai placato me e il mio capo, perciò ti dirò quello che vuoi sapere...$B$BIl suo clan ha perso Young Yenniku.$B$BL'ha preso lo stregone Zanzil the Outcast. Ora Zanzil lo controlla anima e corpo, e solo la magia più potente potrebbe liberarlo.$B$BUna magia che tu non possiedi, $C.$B$BForse i tuoi alleati Darkspear possono dare a Yenniku una speranza di salvezza. Ma ne dubito.",
  obj = "Parla con Kin'weelay.",
  reward = "Zanzil the Outcast??$B$BSe Yenniku è prigioniero di quel troll, uno stregone malvagio e potente, temo che rimanga solo una debole speranza. Debole. E minuscola come il più piccolo degli insetti.$B$BMa pur sempre una speranza.",
  en_title = "The Fate of Yenniku",
  en_obj = "Speak with Kin'weelay.",
}
T[589] = {
  title = "I Cristalli Cantanti",
  desc = "Le leggende parlano di un gioiello nascosto nel profondo del cuore di Stranglethorn. Noi lo chiamiamo il Mind's Eye, e ha grandi poteri. Se riuscirai a impadronirti dell'Occhio, forse potremo usarlo per strappare all'oscurità Yenniku, ormai perduto.$B$BInterrogherò gli spiriti della giungla per trovare il Mind's Eye. Nel frattempo, tu entra nella Crystalvein Mine, a sud-est di qui, e raccogli le Pulsing Blue Shards dagli Ironjaw Basilisks. Le schegge sono rare, ma ci servirà la loro magia per piegare il Mind's Eye al nostro volere.",
  obj = "Porta 3 Pulsing Blue Shards a Kin'weelay, a Grom'gol Base Camp.",
  progress = "Hai le schegge, $N? Mi servono per il rituale finale, quando avremo il Mind's Eye.",
  reward = "Hai fatto un buon lavoro, $N. Queste schegge sono ben formate. Sento già che mi cantano.$B$BE mentre eri via, ho parlato con gli spiriti della giungla. So dove riposa il Mind's Eye...$B$B...E chi lo custodisce.",
  en_title = "The Singing Crystals",
  en_obj = "Bring 3 Pulsing Blue Shards to Kin'weelay at the Grom'gol Base Camp.",
}
T[591] = {
  title = "Il Mind's Eye",
  desc = "Il Mind's Eye è nelle mani di un ogre mage, a est di qui, nel profondo della collina degli ogre Mosh'Ogg. Si chiama Mai'Zoth. Lo conosco dai tempi in cui i Darkspears vivevano a Stranglethorn — è feroce, e la sua magia è potente.$B$BE se ha il Mind's Eye, i suoi poteri saranno ancora più grandi.$B$BDevi affrontare Mai'Zoth e strappargli il Mind's Eye. È un compito pericoloso, ma è l'unica speranza che abbiamo di salvare Yenniku.",
  obj = "Porta il Mind's Eye a Kin'weelay, a Grom'gol Base Camp.",
  progress = "Salute, $N. Gli spiriti cantano le lodi del tuo coraggio, eppure non mi raccontano nulla della tua impresa contro Mai'Zoth.$B$BHai l'Occhio?",
  reward = "Hai recuperato l'occhio! La tua forza è degna di una leggenda, $N!$B$BE per prendere l'Occhio devi aver sconfitto Mai'Zoth e averlo spedito nel Nether. Ecco perché prima gli spiriti non volevano parlare di lui.$B$BÈ un bene che abbia lasciato il mondo della carne e delle ossa, ma ora che si trova nel regno degli spiriti...temo che lì comincerà a imporre il suo dominio.$B$BMa a questo penseremo un'altra volta. Ora devo eseguire un rituale per piegare il Mind's Eye ai nostri scopi...",
  en_title = "The Mind's Eye",
  en_obj = "Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp.",
}
T[592] = {
  title = "Salvare Yenniku",
  desc = "Ho trasformato il Mind's Eye in una Soul Gem, che ti servirà a due cose: prima la usi per stordire Yenniku, poi, quando è stordito, gliela posi sulla testa e ne imprigioni l'anima.$B$BDopo porta la gemma a Nimboya.$B$BYenniku dimora con Zanzil the Outcast alle Ruins of Aboraz, lungo la Crystal Shore, sul lontano Cape of Stranglethorn.",
  obj = "Porta la Filled Soul Gem a Nimboya.",
  progress = "$N. Kin'weelay mi ha detto che sei $Gpartito:partita; a catturare Yenniku.$B$BÈ vero? Ce l'hai?",
  reward = "Ce l'hai fatta! Hai liberato Yenniku dalla volontà di Zanzil e hai compiuto una missione che credevo disperata.$B$BLa nostra tribù ricorderà il tuo nome nei suoi canti, $N, e incideremo la tua storia nella pietra, perché viva per sempre.",
  en_title = "Saving Yenniku",
  en_obj = "Bring the Filled Soul Gem to Nimboya.",
}
T[593] = {
  title = "Riempire la Soul Gem",
  progress = "Yenniku ti sta davanti, stordito, con la mente altrove...",
  reward = "Gli appoggi la Soul Gem sulla fronte. Rabbrividisce mentre l'anima, risucchiata nella gemma, gli abbandona il corpo e lo lascia lì, un guscio senza mente.",
  en_title = "Filling the Soul Gem",
}
T[594] = {
  title = "Message in a Bottle",
  desc = "Il biglietto è scritto con una calligrafia piuttosto buona:$B$BA chiunque possa aiutarmi —$B$BTi prego, ho disperato bisogno di aiuto. Sono prigioniera di un grande Skymane, su un'isola nei South Seas.$B$BDi notte le stelle non le riconosco, e gli alberi della giungla me le nascondono, ma nelle giornate più limpide vedo la Wild Shore a nord-ovest, e a sud-ovest quelle che sembrano grandi navi a vela.$B$BTi supplico, $Gmio possibile salvatore:mia possibile salvatrice;, aiutami.",
  obj = "Trova l'autore del message in a bottle.",
  reward = "Sei $Gvenuto:venuta; a liberarmi?",
  en_title = "Message in a Bottle",
  en_obj = "Find the author of the message in a bottle.",
}
T[595] = {
  title = "I Bloodsail Buccaneers",
  desc = "Hai una gran voglia di lavorare, $Gcompare:comare;. Cosa spinga $Gun:una; $C $R amante della terraferma a dare una mano ai Blackwater Raiders non lo so, ma non ho intenzione di mandarti via.$B$BLa nostra nave è appena entrata in porto qui a Booty Bay, e gira voce che i nostri rivali — quei maledetti, lerci Bloodsail Buccaneers — siano stati avvistati in ogni angolo del sud di Stranglethorn.$B$BI ragazzi sono tutti troppo presi a darci dentro col grog e a correre dietro alle signorine! Mi serve un esploratore.$B$BVa' a dare un'occhiata alla cala appena a nord di Booty Bay, lungo la Savage Coast, e vedi un po' cosa trovi.",
  obj = "First Mate Crazz vuole che tu controlli la cala a nord di Booty Bay.",
  reward = "Sul barile trovi una mappa con qualche frase buttata giù in fretta, e insieme un po' di monete.",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "First Mate Crazz wants you to check the cove north of Booty Bay.",
}
T[596] = {
  title = "Bloody Bone Necklaces",
  desc = "Mi hanno mandato a Grom'gol ad aiutare Nimboya nella sua impresa, ma... sono qui anche per ragioni mie.$B$BLa tribù Bloodscalp è nostra nemica, e prendendo i trofei dei nemici otteniamo potere su di loro. Puoi aiutarci dandogli la caccia.$B$BVivono a nord. Uccidi i troll Bloodscalp e prendigli le bloody bone necklaces. Raccoglierne tante e avrai una grande ricompensa.",
  obj = "Porta 25 Bloody Bone Necklaces a Kin'weelay a Grom'gol Base Camp.",
  progress = "Un giorno i Darkspears schiacceranno i Bloodscalp! Ce le hai, le collane del nostro nemico condannato?",
  reward = "Ah, molto bene. Le farò bollire, le prosciugherò, e mentre le riduco in poltiglia gli spiriti dei loro padroni si indeboliranno!$B$BEcco, $N. Con questo ripago il mio debito con te.",
  en_title = "Bloody Bone Necklaces",
  en_obj = "Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp.",
}
T[597] = {
  title = "I Bloodsail Buccaneers",
  desc = "Sulla mappa c'è Booty Bay, con una \"X\" rossa disegnata esattamente dove ti trovi.$B$BLe righe scarabocchiate dicono:$B$B\"Uomini, piantate il campo in questo punto e restate in silenzio. Prima di attaccare aspettate il segnale dal posto di comando meridionale. Chiunque si avvicini, uccidetelo.\"",
  obj = "Riferisci quello che hai scoperto a First Mate Crazz a Booty Bay.",
  reward = "Ma certo che mi ricordo di te, $C. Vedo che sei $Gtornato:tornata; dalla ricognizione....",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Report your findings to First Mate Crazz in Booty Bay.",
}
T[598] = {
  title = "Split Bone Necklace",
  desc = "Ora che hai raccolto i trofei dei Bloodscalp, ho un altro compito per te. A sud-est vive la tribù di troll Skullsplitter, con cui siamo in guerra da anni. I Darkspears non dimorano più a Stranglethorn, ma restiamo vincolati al conflitto con gli Skullsplitter.$B$BQuindi dagli la caccia. Raccogli le loro Split Bone Necklaces e torna da me. Aiutaci in questa guerra e ti guadagnerai l'amicizia dei Darkspears.",
  obj = "Porta 25 Split Bone Necklaces a Kin'weelay al campo di Grom'gol Base.",
  progress = "Gli Skullsplitter malediranno il giorno in cui ci hanno mosso guerra! Hai fatto quello che ti ho chiesto?",
  reward = "Grande è la tua forza, $N, se hai preso queste collane. Gli Skullsplitter cadono davanti a te come alberelli sotto le zampe di un Basilisco!$B$BLe tue imprese per noi sono una benedizione.",
  en_title = "Split Bone Necklace",
  en_obj = "Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp.",
}
T[599] = {
  title = "I Bloodsail Buccaneers",
  desc = "Corpo di mille balene! Allora i Bloodsail Buccaneers stanno preparando una specie di attacco contro Booty Bay? Che faccia tosta, quei furfanti. Booty Bay resterà sempre in mano ai Blackwater Raiders!$B$BLa faccenda è più grossa di quanto credessi. Corri subito a riferire tutto a Fleet Master Seahorn! Quel vecchio lupo di mare è in giro per la città, da qualche parte....",
  obj = "Informa Fleet Master Seahorn dell'attacco pianificato dai Bloodsail.",
  reward = "I Bloodsail Buccaneers all'attacco di Booty Bay? Farebbero prima a buttarsi giù dalle Overlook Cliffs. Ad ogni modo, con queste informazioni hai reso un gran servizio alla mia flotta di spadaccini. I Blackwater Raiders ti ringraziano.",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Report the planned Bloodsail attack to Fleet Master Seahorn.",
}
T[600] = {
  title = "Gli Scavi della Venture Company",
  desc = "La Venture Company ha una serie di attività sparse per Stranglethorn, e per colpa loro i goblin gran lavoratori come me non riescono a fare un po' d'oro onesto! Ti prego, devi aiutarmi!$B$BLa Venture Company sta scavando a nord, vicino alla Crystalvein Mine. Dentro la miniera non ci entrano, con tutti quei basilischi, ma i Cristalli Risonanti riescono a tirarli fuori lo stesso dalle colline intorno.$B$BPrendigli i cristalli e fagli vedere che la giungla non è roba loro.$B$BE... ehm... portami quei cristalli come prova!",
  obj = "Porta 10 Singing Blue Crystals a Crank Fizzlebub a Booty Bay.",
  progress = "Ce li hai, quei cristalli?? Mi servono!!$B$BCioè... mi serve sapere che a Stranglethorn quella malvagia Venture Company sta perdendo terreno. Perché, sai, noi gente onesta dobbiamo pur campare!",
  reward = "Grande! Magnifico! Ci posso tirar fuori un mucchio di soldi!!$B$BQuella Venture Company ha proprio sbagliato giungla per scavare, eh? Se se ne andassero, staremmo tutti meglio.$B$BGrazie, $N. Oggi hai fatto una buona azione.",
  en_title = "Venture Company Mining",
  en_obj = "Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay.",
}
T[601] = {
  title = "Water Elementals",
  desc = "I water elementals li ha evocati di sicuro Gazban, il mago goblin che si dice abbia scoperto la Stone of the Tides. Come forse saprai, la Stone of the Tides maledice chi la porta, e lo fa svanire e ricomparire...$B$BForse un modo per contrastare la maledizione si trova. Potremmo far analizzare a un mago di Dalaran il residuo magico di uno dei bracciali di un water elemental. Devi tornare sull'isola e recuperarne qualcuno.",
  obj = "Procurati 6 Water Elemental Bracers per Baron Revilgaz a Booty Bay.",
  progress = "Hai avuto fortuna, $N?",
  reward = "Mmh, non sono in grado di esaminare questi bracciali e capire se qualcuno serve a qualcosa, ma sono sicuro che almeno uno tornerà utile. Portali a Dalaran e falli vedere a un mago.$B$BDel resto, non posso mica lasciare Booty Bay solo per fare due chiacchiere con quei vecchi maghi noiosi.$B$BNon che abbia paura che qualcuno provi a farsi largo a gomitate per diventare il nuovo barone. Nessuno si mette contro Revilgaz e vive per raccontarlo.",
  en_title = "Water Elementals",
  en_obj = "Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.",
}
T[602] = {
  title = "Analisi Magica",
  desc = "A quanto ho sentito, i maghi di Dalaran sono occupati a ricostruire la loro città distrutta, ma sono sicuro che ne troverai uno disposto a dedicare un po' di tempo ai bracciali. Se c'è una cosa che so dei maghi, è che a un rompicapo magico non sanno resistere.$B$BPorta la bag of water elemental bracers e vedi se riescono a far luce sulla maledizione della Pietra. Cerca soprattutto Archmage Ansirem Runeweaver. Ci ho già avuto a che fare, ed è uno che sa moltissimo.",
  obj = "Porta i water elemental bracers ad Archmage Ansirem Runeweaver a Dalaran.",
  progress = "Se non ti dispiace, adesso sono piuttosto occupato.",
  reward = "La Stone of the Tides? Davvero interessante. Forse ti sorprenderà sapere che ho scritto un tomo — diversi anni fa — sulle leggende del Gurubashi Empire. Della Pietra so parecchio.$B$BAlmeno uno di questi bracciali sembra conservare un residuo magico che posso analizzare.$B$BVediamo un po' cosa riesco a scoprire...",
  en_title = "Magical Analysis",
  en_obj = "Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran.",
}
T[603] = {
  title = "La Chiave di Ansirem",
  desc = "Il mago che ha la Pietra ne amplifica il potere attraverso un qualche punto focale... una specie di altare. Sopraffacendolo, dovresti riuscire a bloccarlo.$B$BGuarda caso, so proprio cosa ci vuole: un pugnale antico, anche questo un cimelio troll. Solo che c'è un... piccolo problema.$B$BVedi, il pugnale l'ho trovato mentre facevo ricerche a Stranglethorn, ma l'ho dato a quella testarda di mia figlia, Catelyn, che è scappata a Booty Bay per diventare pirata.",
  obj = "Parla con Catelyn a Booty Bay.",
  reward = "Il mio pugnale? Che sei, $Gun comico:una comica;?$B$BCosa? Vuoi che ti racconti un'altra volta come sono passata da migliore combattente col coltello di Booty Bay a zimbello di tutti i pirati!$B$BUno dei Bloodsail Buccaneers — un branco di veri bastardi, ecco cosa sono! — mi ha battuta in un duello al coltello e si è preso la lama come bottino.$B$BMica posso tirare avanti come combattente col coltello solo con gli insulti e la lingua tagliente...",
  en_title = "Ansirem's Key",
  en_obj = "Talk to Catelyn in Booty Bay.",
}
T[604] = {
  title = "I Bloodsail Buccaneers",
  desc = "Crazz dice un gran bene della tua dedizione ai Blackwater Raiders. Ho una missione della massima importanza per la flotta, e la affiderò a te.$B$BI Bloodsail Buccaneers hanno allestito sulla Wild Shore quello che chiamano il loro posto di comando meridionale: infiltrati lì e fai irruzione nell'accampamento. Portami le loro carte e gli ordini scritti. Poi vedremo per bene cosa sta tramando quella feccia.",
  obj = "Fleet Master Seahorn a Booty Bay vuole che tu uccida 10 Bloodsail Swashbucklers e riporti le Bloodsail Charts e i Bloodsail Orders.",
  progress = "Ohè, $N. Che notizie mi porti sull'accampamento dei Bloodsail a sud?",
  reward = "Perfetto, $N. Ora che il loro piano lo conosciamo, è solo questione di tempo.$B$BE pensare che quegli sciocchi sono andati a gettare l'ancora proprio al largo del capo....",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders.",
}
T[605] = {
  title = "Schegge Blu Risonanti",
  desc = "I Cristalli Risonanti li trovi solo a Stranglethorn, e a certa gente valgono parecchio. Io saprei a chi piazzarli, ma con quella maledetta Venture Company fra i piedi un onesto imprenditore come me fa fatica a raccoglierne anche solo uno!$B$BVorrei assumerti.$B$BI basilischi di Stranglethorn mangiano il cristallo, ed è per questo che hanno la pelle così dura: a volte ci si ricava del cristallo di discreta qualità.$B$BVa bene un basilisco qualsiasi, ma quelli meno cattivi li trovi più a nord, lungo le rive a sud di Zul'Kunda.",
  obj = "Porta 10 Singing Crystal Shards a Crank Fizzlebub.",
  progress = "Ce le hai già, quelle schegge? Ti darò una fetta onesta dei guadagni!",
  reward = "Ah! Vanno benissimo, $N. Sì, proprio benissimo!$B$BEcco la tua parte e... è stato un piacere fare affari con te.",
  en_title = "Singing Blue Shards",
  en_obj = "Bring 10 Singing Crystal Shards to Crank Fizzlebub.",
}
T[606] = {
  title = "Spaventare Shaky",
  desc = "Se c'è una cosa che non sopporto, è la gente che non paga i debiti di gioco! E con me ne hanno in tanti. Pensi di potermi dare una mano a riscuotere?$B$BSi comincia da \"Shaky\" Phillipe, giù al porto. Dalla partita della settimana scorsa mi deve un bel po', e io rivoglio quello che mi spetta! Ma per farlo pagare dovremo spaventarlo.$B$BEsci dalla città e dai la caccia agli Elder Mistvale Gorillas. Procurati un bell'assortimento di interiora e portale a Shaky. Non fargli capire che sono di un animale: lascia che pensi al peggio.",
  obj = "Porta 5 Mistvale Giblets a \"Shaky\" Phillipe a Booty Bay.",
  progress = "Ehi! Non mi piace come mi guardi, $Gsignore:signora;.",
  reward = "Ack! E queste dove le hai prese? No, non dirmelo. Non lo voglio sapere!$B$BChi ti manda? Lupo di Mare?",
  en_title = "Scaring Shaky",
  en_obj = "Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay.",
}
T[607] = {
  title = "Ritorno da MacKinley",
  desc = "Ecco, prendi questo sacchetto e portalo a Lupo di Mare. E digli che volevo ripagarlo! Lo giuro!!$B$BAvevo solo bevuto un po' troppo e ho perso la strada, e... sai come vanno queste cose. Capirà — non c'è bisogno di fare $Gil duro:la dura;!",
  obj = "Porta lo Shaky's Payment a \"Sea Wolf\" MacKinley",
  progress = "Eccoti qua, $N. Ce l'hai lo Shaky's payment?",
  reward = "Eh eh, ben fatto! E quando gli hai fatto vedere quelle interiora, quanto ha tremato Shaky?$B$BAh! Ha tutto scritto in faccia, e quando gioco a carte con lui non posso fare a meno di vincere!$B$BGrazie dell'aiuto, $N. E adesso tocca a te riscuotere...",
  en_title = "Return to MacKinley",
  en_obj = "Bring Shaky's Payment to \"Sea Wolf\" MacKinley.",
}
T[608] = {
  title = "I Bloodsail Buccaneers",
  desc = "Al diavolo Firallon e la sua sfrontatezza! Non sarebbe capace di portare una barca a remi da una sponda all'altra del Crystal Lake, figuriamoci guidare un'intera flotta contro di noi.$B$BLa loro negligenza, i Bloodsail Buccaneers la pagheranno. Il loro piano d'attacco ormai lo conosciamo, e possiamo contrattaccare prima che se ne accorgano.$B$BMa perché scomodare tutta la flotta per un lavoro che può fare un solo gruppo di avventurieri coraggiosi? $N, prendi con te qualcuno dei tuoi compagni più abili, raggiungi il punto di sbarco di Firallon e assassina i capi dei Bloodsail. Poco dopo, la loro flotta andrà a fondo....",
  obj = "Fleet-Master Seahorn a Booty Bay vuole che tu uccida Captain Stillwater, Captain Keelhaul e Fleet Master Firallon.",
  progress = "Qualcosa non va, $N? Dobbiamo attaccare prima che lo facciano i Bloodsail Buccaneers!",
  reward = "Ah, che giornata splendida per i Blackwater Raiders! Tre urrà per te, $N!",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.",
}
T[609] = {
  title = "Debiti Voodoo",
  desc = "La lista si sta accorciando, ma c'è ancora gente che mi deve qualcosa.$B$BPoi ci sono Maury \"Club Foot\" Wilkins, Jon-Jon the Crow e Chucky \"Mani di Burro\".$B$BQuei cani rognosi hanno debiti scaduti da mesi, e pensavo che avessero lasciato la città per non pagare! Poi ho sentito che li hanno maledetti e stregati, e che adesso vagano per le rovine della giungla. Ma che fine abbiano fatto non m'importa — voglio quello che è mio!$B$BLi trovi alle Ruins of Aboraz e alle Ruins of Jubuwal, a nord-est di qui. Scovali e riscuoti.",
  obj = "Porta il Maury's Clubbed Foot, il Jon-Jon's Golden Spyglass e il Chucky's Huge Ring a \"Sea Wolf\" MacKinley a Booty Bay.",
  progress = "$N, li hai trovati, quei tre cani? Hai riscosso i loro oggetti di valore?",
  reward = "Ottimo! Li posso vendere bene, soprattutto quello che c'è dentro il piede di Maury! Grazie mille, $N!$B$BSpero che quei tre abbiano imparato la lezione: mai scommettere quello che non puoi permetterti di perdere.$B$BE forse per loro è troppo tardi, ma... dovrebbero stare attenti a scegliere con chi giocare d'azzardo.",
  en_title = "Voodoo Dues",
  en_obj = "Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay.",
}
T[610] = {
  title = "\"Pretty Boy\" Duncan",
  desc = "Ti ha mandato mio PADRE? Pensavo che quel vecchio bacucco si fosse arreso, ormai.$B$BNon è davvero colpa sua se sono scappata, solo che non avrebbe dovuto aspettarsi che accettassi di vivere una vita noiosa, a spulciare vecchi libri ammuffiti e a frequentare maghi canuti, impettiti e barbosi!$B$BSe ti serve il mio pugnale, dovrai riprenderlo da \"Pretty Boy\" Duncan, uno dei Bloodsail Buccaneers. Piantagli qualcosa tra le scapole e sono sicura che te lo darà.",
  obj = "Prendi il pugnale di Catelyn da \"Pretty Boy\" Duncan.",
  progress = "Non mi avevano mai battuta prima, sai, $N? Certo, qualche taglio me lo sono fatto — se ci sono coltelli di mezzo va a finire per forza così — ma quello mi ha semplicemente mollato un colpo in testa e mi ha fatto perdere i sensi. Quando mi sono ripresa, la mia lama era sparita.$B$BPer quanto il mio soprannome possa far pensare il contrario, ho ancora bisogno di un coltello per combattere, e io voglio proprio quello.",
  reward = "Hai battuto Duncan? Allora non sei $Gcosì inesperto:così inesperta; come sembravi a prima vista.$B$BImmagino che questo voglia dire anche che non dovrei sfidarti a duello!",
  en_title = "\"Pretty Boy\" Duncan",
  en_obj = "Get Catelyn's dagger from \"Pretty Boy\" Duncan.",
}
T[611] = {
  title = "La Maledizione delle Maree",
  desc = "Quindi stai cercando una specie di altare? Be', di rovine troll non me ne intendo quanto mio padre, ma ho sentito parlare di una città troll sommersa vicino all'isola che cerchi. Forse dovresti provare lì.$B$BIl coltello me l'hai riportato tu, quindi immagino di potertelo prestare... ma quando hai finito lo rivoglio!",
  obj = "Distruggi l'Altar of the Tides con la Catelyn's Blade, uccidi Gazban e riporta la Stone of the Tides e la Catelyn's Blade a Baron Revilgaz.",
  progress = "Mi hai recuperato la Stone of the Tides, $N? Le ho già fatto spazio e ho comprato un bel piedistallo apposta.",
  reward = "Straordinario! La Pietra delle Maree! Nella mia collezione di antichi manufatti troll avrà un posto d'onore. Hai notato che sembra quasi avere una marea intrappolata nella superficie? Magnifico!",
  en_title = "The Curse of the Tides",
  en_obj = "Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz.",
}
T[613] = {
  title = "Scardinare il Piede di Maury",
  desc = "Maledizione! Quel mozzo di Maury ha messo un lucchetto al suo piede, e io non riesco ad aprirlo! Dentro il piede c'è il suo bottino, ed è quello che mi deve!$B$BDobbiamo trovare la chiave che apre il lucchetto. Si sapeva che Maury giocava d'azzardo con gli ogres Mosh'Ogg, nel loro tumulo a nord-est. E quando era ancora vivo mi ha raccontato che l'ultima volta che c'era andato l'avevano cacciato via perché aveva vinto troppo. Forse la sua chiave ce l'ha qualcuno degli Ogres che stanno lì.$B$BMa se ce l'hanno, per trovare quello giusto potresti doverne uccidere un bel po'...",
  obj = "Porta la Maury's Key a \"Sea Wolf\" Mackinley a Booty Bay.",
  progress = "Ehilà, $N! L'hai già trovata, la Maury's Key?",
  reward = "L'hai trovata! Grazie mille, $N. Mi sei $Gstato:stata; di grande aiuto!$B$BEcco qua — te lo sei meritato!",
  en_title = "Cracking Maury's Foot",
  en_obj = "Bring Maury's Key to \"Sea Wolf\" Mackinley in Booty Bay.",
}
T[614] = {
  title = "Il Captain's Chest",
  desc = "Un tempo facevo la rotta da qui fino a Ratchet, nel Kalimdor. Ero un capitano affermato, con una reputazione senza macchia.$B$BFinché...$B$BQuei maledetti giganti del mare mi hanno rovinato! Mi hanno distrutto la nave, ucciso l'equipaggio e caricato su una scialuppa diretta a Booty Bay. E uno di loro, Gorlash, mi ha rubato il Captain's Chest. Ha detto che gli serviva come tabacchiera. Che faccia tosta!$B$BHo sentito dire che Gorlash si aggira lungo la costa, a est di qui. Trovalo e riportami il forziere! Se ce la fai, avrai la gratitudine di un capitano.",
  obj = "Porta lo Smotts' Chest a Hecklebury Smotts a Booty Bay.",
  progress = "Ohè, $N! Hai trovato Gorlash? Quel forziere era il mio preferito: c'è uno scomparto segreto dove mettevo i tesori più preziosi!",
  reward = "L'hai trovato! Oh, che giorno felice! Grazie, $N. Ora che ho di nuovo il forziere, il fuoco che ho dentro si spegne un po'.$B$BMa non ho ancora finito di vendicarmi...",
  en_title = "The Captain's Chest",
  en_obj = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.",
}
T[615] = {
  title = "La Scimitarra del Capitano",
  desc = "Per colpa di quei giganti ho perso la prima nave, così ne ho comprata un'altra. L'ho battezzata Smotts' Revenge, l'ho riempita di provviste e di marinai e sono partito a cercare quei furfanti. Li ho trovati, ma... mi hanno battuto. Hanno distrutto la Smotts' Revenge, hanno ucciso il secondo equipaggio e mi hanno messo su un'altra scialuppa di salvataggio.$B$BStavolta è stato un altro gigante, Negolash, a rubarmi la scimitarra.$B$BAffronta Negolash e riportamela!$B$BParla con Sprogger, che faceva il cuoco sulla Smotts' Revenge ed è sopravvissuto all'ultimo attacco: può aiutarti a trovare il gigante.",
  obj = "Parla con Sprogger.",
  reward = "Ehilà, ehilà, $N. Il Capitano mi ha detto che sei a caccia di Negolash, eh?",
  en_title = "The Captain's Cutlass",
  en_obj = "Speak with Sprogger.",
}
T[616] = {
  title = "L'Isola Infestata",
  desc = "Baron Revilgaz mi ha chiesto di tenere le orecchie aperte e stare attento a ogni voce su cose strane o fuori posto a Booty Bay e a Stranglethorn. Di solito alle storie di fantasmi non do molto credito, ma in taverna ho sentito alcuni marinai parlare di un'isola infestata al largo della costa. Ci sarebbero Water elementals e un fantasma goblin che delira, dicono.$B$BSe vai a parlare con Revilgaz, potresti raccontargli questa storia?",
  obj = "Parla con Baron Revilgaz a Booty Bay.",
  reward = "Interessante. Mi pare di ricordare che tempo fa ho letto un libro dove si diceva...$B$BAh, ma certo, era una leggenda dei troll. Se quello che riferisce Krazek è vero, forse presto potrò aggiungere la Stone of the Tides alla mia collezione di antichi manufatti e reliquie.",
  en_title = "The Haunted Isle",
  en_obj = "Speak with Baron Revilgaz in Booty Bay.",
}
T[617] = {
  title = "Akiris a Fasci",
  desc = "Cerchi lavoro, $N? Potrei averne, se te la senti di affrontare una piccola sfida.$B$BUn mio amico, un certo Groy, fa soldi a palate vendendo quella che i naga chiamano akiris reed, una specie di canna marina pregiata. Non so di preciso a cosa serva, ma i fasci li paga bene.$B$BPortamene dieci steli e facciamo affari. L'ultima volta i naga li hanno visti sulla spiaggia a nord di qui.",
  obj = "Porta 10 fasci di Akiris Reed a Privateer Bloads a Booty Bay.",
  progress = "Se non hai affari da trattare con me, circola, $N.",
  reward = "Ben fatto, $N. Non erano poi una gran sfida, 10 steli di akiris reed, eh? Senza offesa per i naga, ma ehi, tutti dobbiamo guadagnarci da vivere.",
  en_title = "Akiris by the Bundle",
  en_obj = "Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.",
}
T[618] = {
  title = "Affrontare Negolash",
  desc = "Negolash è un gigante affamato.$B$BQuando i giganti ci hanno distrutto la nave, Negolash è filato dritto in cucina. Gli altri giganti volevano mangiarsi l'equipaggio, lui no. Negolash voleva il vino... e le mie Barbecued Buzzard Wings. Sono la mia specialità, e per la ricetta sono dovuto arrivare fino alle Badlands!$B$BSe vuoi attirare il gigante, procurati del vino e un mucchio di ali di condor, e mettili nella nostra vecchia scialuppa, lungo la costa a sud-est di qui. Appena Negolash sentirà l'odore di tutto quel cibo, arriverà di sicuro!",
  obj = "Porta 10 Barbecued Buzzard Wings e 5 bottiglie di Junglevine Wine alla scialuppa di Captain Smotts.$B$BUccidi Negolash e porta la Smotts' Cutlass a Captain Smotts a Stranglethorn.",
  progress = "$N, mi hai riportato la scimitarra?",
  reward = "Hai strappato la mia scimitarra a Negolash! Che fortuna, $N, non ci posso credere! Da quando ti ho incontrato la sorte mi è girata in meglio, non c'è dubbio!$B$BGrazie! E se un giorno avrò una nuova nave e vorrai solcare i mari, sarai $Gil mio ospite d'onore:la mia ospite d'onore;.",
  en_title = "Facing Negolash",
  en_obj = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.$B$BKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.",
}
T[619] = {
  title = "Adescare Negolash",
  progress = "È una scialuppa di salvataggio abbandonata. Sul fianco c'è una scritta in vernice graffiata e sbiadita:$B$B\"Smotts' Revenge\"",
  reward = "Sulla zattera ammucchi cibo e bevande...",
  en_title = "Enticing Negolash",
}
T[620] = {
  title = "La Monogrammed Sash",
  desc = "Lungo l'orlo di questa elegante fascia sono ricamate le lettere \"HS\".",
  obj = "Riporta la Monogrammed Sash al suo proprietario.",
  progress = "Salve. Ti serve qualcosa?",
  reward = "Hai recuperato la mia fascia? Ma allora... devi aver ucciso Mok'rash, il sea giant! Evviva!$B$BSono contento che sia morto, quel lurido furfante — Mok'rash era uno dei tre giganti del mare che mi hanno distrutto le navi e ucciso l'equipaggio.$B$BTre volte.$B$BSei $Gun:una; $C di valore, $N.",
}
T[621] = {
  title = "Il Segreto di Zanzil",
  desc = "Zanzil the Outcast vive coi suoi seguaci a Jubuwai e nelle Aboraz Ruins, a nord-est di Booty Bay. La sua tribù l'ha esiliato. Perché? Beh...$B$BZanzil sa come piegare la mente degli altri, e i suoi capi ne hanno paura. Sui seguaci usa una mistura di piante della giungla per soffocarne la volontà e rafforzarne il corpo.$B$BQuella mistura varrebbe parecchio per chi vuole controllare gli altri.$B$BPortamene dei campioni e troverò io il modo di usarli.",
  obj = "Porta 12 campioni di Zanzil's Mixture a Crank Fizzlebub a Booty Bay.",
  progress = "Ce li hai i campioni di Zanzil's Mixture??",
  reward = "Ah, molto bene! Ecco la tua paga.$B$BE questo è un piccolo extra... per la tua discrezione.",
  en_title = "Zanzil's Secret",
  en_obj = "Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.",
}
T[622] = {
  title = "Ritorno da Corporal Kaleb",
  desc = "Mentre eri via ho riparato la pentola che mi hai portato. Ci ho aggiunto anche un fischietto a vapore in più e guarda qua! Sul fondo c'è una lama nuova che taglia perfino le ossa delle zampe!$B$BSì sì, la Krazek's Crock Pot: cuochi soddisfatti al 100%! Il suo padrone sarà contento, ne sono sicuro.",
  obj = "Porta la Krazek's Fixed Pot a Corporal Kaleb, all'Accampamento dei Ribelli.",
  progress = "Ciao, $N. Sei $Garrivato:arrivata; fino a Booty Bay? Il goblin Krazek me l'ha riparata, la pentola??",
  reward = "È riparata! Fantastico, ora posso mettermi a preparare la cena! Grazie mille, $N.$B$BSpero che a Booty Bay ti sia andato tutto liscio. Quel posto può diventare parecchio pericoloso, e... ho sentito dire che a volte i goblin trascinano i marinai ubriachi sulle loro navi di schiavi e se li portano chissà dove... a fare chissà cosa...",
  en_title = "Return to Corporal Kaleb",
  en_obj = "Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp.",
}
T[623] = {
  title = "Akiris a Fasci",
  desc = "$N, già che sei qui: mentre eri via mi è arrivato un messaggio da Groy. Dice che l'ultima spedizione arrivata l'ha soddisfatto e che ha un cliente che vuole subito dell'altra roba.$B$BA Theramore non ci vado prima di una settimana, ma se sei $Gdisposto:disposta; a fare il viaggio, non vedo perché non potresti portarla tu al posto mio.$B$BTi senti $Gavventuroso:avventurosa;? La Dustwallow Marsh sai dov'è, vero? Io però starei attento: Theramore può essere pericolosa, se sei il tipo sbagliato.",
  obj = "Porta un Bundle of Akiris Reeds a Privateer Groy a Theramore.",
  progress = "Sì?",
  reward = "Cosa?! Ho di meglio da fare che parlare con quelli come te, $C. Fa' che ne valga la pena, o levati dai piedi.$B$BEh? Ti manda Bloads, eh? Be', cos'hai per me?$B$B<Privateer Groy esamina il mucchio con attenzione.>$B$BNiente male, niente male davvero. Con un altro mucchio il mio cliente sarà molto contento.$B$BImmagino che adesso mi chiederai dei soldi, eh, $C? Certo che sì!$B$BEcco, prendi queste monete, e un consiglio: fuori dai miei moli.",
  en_title = "Akiris by the Bundle",
  en_obj = "Bring a Bundle of Akiris Reeds to Privateer Groy in Theramore.",
}
T[624] = {
  title = "Cortello's Riddle",
  desc = "C'è un ponte ornato che in molti attraversano$BA est di Deadwind e a sud di Redridge$BLà sotto c'è qualcosa che ti aspetta$BQualcuno lo chiama traccia, qualcuno indizio$BE lì resterà per infiniti domani$BAd attendere il suo momento nella Swamp of Sorrows",
  obj = "Risolvi l'indovinello!",
  reward = "Nella pergamena fradicia c'è il prossimo indizio....",
  en_title = "Cortello's Riddle",
  en_obj = "Solve the riddle!",
}
T[625] = {
  title = "Cortello's Riddle",
  desc = "Ti aspetta una terra lontana a Kalimdor$BDove il pericolo ha infranto speranze e destini$BA est di Barrens il clima si fa duro$BE la Dustwallow Marsh è segnata da oscurità e insidie$BMa lì, per chi è all'altezza della prova, c'è un indizio$BChe in una grotta a sud-ovest aspetta di essere trovato",
  obj = "Risolvi l'indovinello!",
  reward = "Trovi una musty scroll.",
  en_title = "Cortello's Riddle",
  en_obj = "Solve the riddle!",
}
T[626] = {
  title = "Cortello's Riddle",
  desc = "A Lordaeron! La grande terra dei tumulti$BDove i soldati coraggiosi lottano con la morte$BFatti strada in mezzo al grande scompiglio$BE là troverai la fine di questa impresa$BLungo la costa dell'Hinterlands, ai piedi delle grandi cascate$BSotto l'acqua il tuo tesoro ti chiama!",
  obj = "Risolvi l'indovinello!",
  reward = "Apri lo scrigno e scopri....",
  en_title = "Cortello's Riddle",
  en_obj = "Solve the riddle!",
}
T[627] = {
  title = "Un Favore per Krazek",
  desc = "Molto a nord, negli Arathi Highlands, nella Drywhisker Gorge c'è una grotta di montagna, e là dentro si trova un minerale raro: la sanguinite. Quella della grotta non è di prima qualità, ma anche la sanguinite scadente ha comunque valore... per chi sa come usarla.$B$BNe vorrei un po'.$B$BIo ti riparo la pentola a pressione, e intanto che ci lavoro... tu mi porti dei campioni di sanguinite. Portamene abbastanza e ti do anche un extra.$B$BAh, e se non sai estrarla... trova qualcuno che sappia farlo!",
  obj = "Porta 4 carichi di Lesser Bloodstone Ore a Krazek, a Booty Bay.",
  progress = "Ciao, $N. Allora, hai avuto fortuna con la sanguinite?",
  reward = "Ah, splendido! Mi hai fatto un gran favore.$B$BEcco il tuo compenso...",
  en_title = "Favor for Krazek",
  en_obj = "Bring 4 loads of Lesser Bloodstone Ore to Krazek in Booty Bay.",
}
T[628] = {
  title = "Excelsior",
  desc = "Finito l'interno, resta solo da aggiungere lo strato esterno. Lì ci vanno soltanto le migliori pelli di crocolisco anziano. Sono più resistenti e fanno da tela migliore — per così dire — per i disegni e le rifiniture che distinguono la linea Excelsior di Drizzlik.$B$BPerò la pelle perfetta è difficile da trovare: l'unica che va bene per il mio progetto è quella di un elder saltwater crocolisk. Gli anziani escono solo per difendere gli altri crocolischi d'acqua salata, quindi per stanarne uno potresti doverne uccidere qualcuno.",
  obj = "Porta un'Elder Crocolisk Skin a Drizzlik a Booty Bay.",
  progress = "Ho letto da qualche parte che i saltwater crocolisks stanno lentamente scomparendo... brutta notizia per i miei affari, no?$B$BComunque, spero che tu abbia quella pelle di elder saltwater crocolisk per me!",
  reward = "Ottimo! Con il tuo aiuto finirò quest'ordine e lo spedirò a Director Riddlevox con la prossima nave per Undermine. E pure in anticipo!$B$BPer ripagarti del duro lavoro, ecco, ne ho fatti qualcuno in più: prendine un paio, e anche qualche toppa per armatura. Offre Drizzlik.$B$BE ricorda, non c'è stivale più bello di uno della linea Excelsior di Drizzlik!",
  en_title = "Excelsior",
  en_obj = "Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay.",
}
T[629] = {
  title = "The Vile Reef",
  desc = "Molto tempo fa un grande terremoto ha fatto sprofondare un'antica città troll sotto le acque della Savage Coast, a nord-ovest. Quel luogo lo chiamiamo la Vile Reef, perché ora fra le rovine della città vivono i murlocs, che attaccano chiunque si avvicini.$B$BFra quelle rovine c'è una vecchia tavoletta che racconta l'antica storia di Gri'lek, un eroe delle leggende troll. Per la tribù Darkspear quella storia è sacra e, anche se la tavoletta è troppo grande per spostarla, ne voglio una scheggia da custodire in un santuario nella nostra nuova casa, a Orgrimmar.",
  obj = "Porta una Tablet Shard a Kin'weelay a Grom'gol Base Camp.",
  progress = "Attendo la Tablet Shard, $N.",
  reward = "Bene così. Quando tornerò a Orgrimmar metterò questa scheggia in un luogo sacro, a ricordarci la potenza e l'onore di Gri'lek.$B$BGrazie, $N. Con le tue imprese l'amicizia con la tribù Darkspear continua a crescere.",
  en_title = "The Vile Reef",
  en_obj = "Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.",
}
T[630] = {
  title = "Message in a Bottle",
  desc = "$N, mi affido a te e a chiunque riuscirai a radunare per liberarmi. Il mio carceriere è il grande Skymane King Mukla: comanda le bestie di quest'isola, e con questa catena mi tengono qui contro la mia volontà. Se riuscirai a ucciderlo e a trovare la chiave di questo ceppo, ti sarò profondamente debitrice.$B$BLo sento spesso dalla parte sud-orientale dell'isola, ma ti prego, fai attenzione: non è uno da prendere alla leggera.",
  obj = "Uccidi King Mukla e torna da Princess Poobah con la Chiave per liberarla.",
  progress = "Siano ringraziati gli antenati: qualcuno è venuto ad aiutarmi. Hai la chiave per liberarmi?",
  reward = "$N, mi hai salvata da un grande disonore. Se fosse in mio potere, ti offrirei un posto nella mia tribù. Per ora, però, posso darti solo questo pegno, per il coraggio e la nobiltà che hai dimostrato.",
  en_title = "Message in a Bottle",
  en_obj = "Slay King Mukla and return to Princess Poobah with the Key to free her.",
}
T[631] = {
  title = "Il Thandol Span",
  desc = "Un'esplosione tremenda è rimbombata fra le colline, ed è stata una cosa orribile, te lo dico io!$B$BSono morti dei bravi soldati a difendere il Thandol Span, e Longbraid dice che prima o poi la faremo pagare ai Dark Irons.$B$BMa siamo proprio messi male, e di rinforzi, all'orizzonte, nemmeno l'ombra. Longbraid ha mandato Ol' Rustlocke a perlustrare il ponte orientale, per capire se si poteva metterlo in sicurezza.$B$BSono passati giorni da allora, e con Dun Modr sotto assedio non abbiamo uomini da mandare a cercarlo.$B$BMagari tu riesci a trovarlo...",
  obj = "Rhag Garmason vuole che tu trovi Ol' Rustlocke.",
  reward = "Frughi il piccolo cadavere del nano. Sull'elmo si legge chiaramente il nome inciso: Ebenezer Rustlocke.",
  en_title = "The Thandol Span",
  en_obj = "Rhag Garmason wants you to locate Ol' Rustlocke.",
}
T[632] = {
  title = "Il Thandol Span",
  desc = "A quanto pare, il povero Ol' Rustlocke è finito in un'imboscata dei Dark Iron. Accanto al pugno serrato noti una pergamena.$B$BPorta la triste notizia a Rhag Garmason e mostragli quello che hai trovato.",
  obj = "Torna da Rhag Garmason e mostragli la pergamena che hai trovato sul cadavere di Rustlocke.",
  progress = "Hai trovato qualche traccia di Ol' Rustlocke, $N?",
  reward = "Oh, cielo, che notizia grave...",
  en_title = "The Thandol Span",
  en_obj = "Report back to Rhag Garmason and show him the parchment you found on Rustlocke's corpse.",
}
T[633] = {
  title = "Il Thandol Span",
  desc = "Per i cieli, no! Povero Rustlocke, che gran tragedia!$B$BNon possiamo permettere che sia morto invano. Secondo la pergamena che hai trovato, Kam Deepfury, che ha ideato il primo attacco, ha fatto nascondere una scorta di esplosivi appena oltre il Thandol Span, negli Arathi Highlands.$B$BSe quegli esplosivi arrivano al ponte, ci tagliano la principale linea di rifornimento verso nord! La scorta va distrutta, $N! Quando avrai portato a termine la missione, torna da me.$B$BSei la nostra unica speranza.",
  obj = "Distruggi la scorta di esplosivi.",
  progress = "Quella scorta di esplosivi va distrutta!",
  reward = "Il ponte che ci resta è salvo! Hai reso un grande servizio a King Magni e al popolo di Khaz Modan.$B$BAdesso, se solo riuscissimo a tenere duro fino all'arrivo dei rinforzi...",
  en_title = "The Thandol Span",
  en_obj = "Destroy the cache of explosives.",
}
T[634] = {
  title = "Supplica all'Alleanza",
  desc = "Avrei un altro piccolo favore da chiederti, $C. Aspettiamo le riserve da Ironforge, ma Roggo sa che c'è un accampamento dell'Alleanza a nord, a Refuge Pointe, negli Arathi Highlands.$B$BVai lì a cercare Captain Nials e chiedi alla buona Capitano se l'Alleanza può cederci qualche soldato che ci aiuti a riprendere Dun Modr e il Thandol Span.",
  obj = "Cerca Captain Nials a Refuge Pointe.",
  reward = "Le mie condoglianze a Longbraid e ai suoi valorosi soldati. Sapere della tragedia del Thandol Span e della caduta di Dun Modr mi pesa sul cuore.$B$BMa Stromgarde è caduta! È per questo che siamo qui a Refuge Pointe: dobbiamo riconquistare la nostra grande città.$B$BL'onore e il dovere ci vietano di lasciare gli Highlands finché Stromgarde non tornerà ad alzare il possente vessillo del Re. Farò sapere a Longbraid che dovrà cavarsela da solo...",
  en_title = "Plea To The Alliance",
  en_obj = "Seek out Captain Nials at Refuge Pointe.",
}
T[635] = {
  title = "Il Cristallo tra le Montagne",
  desc = "Il frammento ti pulsa in mano...$B$BNe senti venire una specie di supplica, come se qualcuno cercasse di comunicare, qualcuno che ha un disperato bisogno del tuo aiuto.$B$BNella mente ti si apre una visione — le montagne del nord di Arathi, e lassù un cristallo splendente che spunta dalla terra.$B$BTi senti $Gattratto:attratta; da quel luogo.",
  obj = "Trova il cristallo della tua visione.",
  reward = "Il cristallo pulsa, come se dentro ci fosse intrappolata una forza viva.",
  en_title = "Crystal in the Mountains",
  en_obj = "Find the crystal from your vision.",
}
T[637] = {
  title = "Sully Balloo's Letter",
  desc = "La busta, fradicia e segnata dalla guerra, si sfalda tra le tue mani, e tra le dita ti restano alcune pagine di una lettera, scritta con estrema cura.$B$BLa lettera è indirizzata a una certa Signora Sara Balloo di Ironforge e comincia con le parole \"Mia cara Sara....\"",
  obj = "Consegna la Sully Balloo's Letter a Sara Balloo.",
  progress = "Hai l'aria di chi ha viaggiato a lungo e ne ha passate tante, $C. I tempi in cui viviamo mettono a dura prova l'anima. Che notizie mi porti adesso?",
  reward = "Dici di aver visto il mio Sully intrappolato sotto le acque gelide? Dimmi che non è vero!$B$BFammi leggere quel che ha scritto....",
  en_title = "Sully Balloo's Letter",
  en_obj = "Deliver Sully Balloo's Letter to Sara Balloo.",
}
T[638] = {
  title = "Trollbane",
  desc = "Ora che Thoras Trollbane è morto e Stromgarde è in rovina, Vol'jin ha ordinato di fare di tutto per trafugare agli umani la leggendaria spada Trol'kalar, così da poterla usare nelle prossime battaglie contro i troll di Zul'Gurub.$B$BZengu, uno dei nostri cacciatori più esperti, è stato mandato a Hammerfall, nella parte nordorientale degli Arathi Highlands, per sovrintendere al recupero della spada.",
  obj = "Vai a Hammerfall in Arathi Highlands e parla con Zengu.",
  reward = "Come va, $C? Il compito che ci ha affidato Vol'jin sarà difficile: qualunque aiuto potrai darci ci servirà, e te ne saremo grati.",
  en_title = "Trollbane",
  en_obj = "Travel to Hammerfall in the Arathi Highlands and speak with Zengu.",
}
T[639] = {
  title = "Sigil of Strom",
  desc = "In tempi antichi i troll combatterono contro l'Arathorian Empire e contro il più abile dei nostri avversari, Lord Ignaeus of Strom, detto Trollbane. Andava in battaglia a cavallo, con in pugno Trol'kalar — che nella loro antica lingua vuol dire sterminatore di troll.$B$BMa adesso i figli di Trollbane si sono indeboliti, e la loro roccaforte è ridotta in rovine.$B$BA proteggere la spada ci sono diversi sigilli, divisi fra i sopravvissuti di Stromgarde, e noi dobbiamo recuperarli.$B$BIl primo se l'è preso lo Syndicate: dovrebbe averlo uno dei loro uomini a Stromgarde.",
  obj = "Ottieni il Sigil of Strom per Zengu a Hammerfall.",
  progress = "Il primo sigillo l'hai già trovato? Con ogni probabilità ce l'ha addosso uno degli agenti dello Syndicate a Stromgarde.",
  reward = "Eccellente, mon. Cominciamo bene a raccogliere i sigilli che ci serviranno per tirare fuori Trol'kalar dalla tomba di Trollbane.",
  en_title = "Sigil of Strom",
  en_obj = "Get the Sigil of Strom for Zengu in Hammerfall.",
}
T[640] = {
  title = "Il Sigillo Spezzato",
  desc = "La tomba di Thoras Trollbane è protetta da tre sigilli — il primo l'hai già preso allo Syndicate. Con gli altri due sarà più dura, perché sono in mano alla milizia di Stromgarde, che si è trincerata bene.$B$BIl sigillo di Thoradin l'ha diviso in undici frammenti Galen, il figlio di Thoras, e li ha distribuiti fra i difensori di Stromgarde. Recuperali e portali a Tor'gan, lo sciamano troll: lui potrà riunirli nel sigillo completo.",
  obj = "Recupera gli 11 Sigil Fragments dai difensori di Stromgarde e portali a Tor'gan a Hammerfall.",
  progress = "Throm'ka, $C. Mi ha detto Zengu che hai bisogno del mio aiuto?",
  reward = "Ah, vuoi che ti rimetta insieme questo sigillo? Non dovrebbe essere troppo difficile... pare che i pezzi ci siano tutti, e la struttura magica si ricomporrà senza fatica.$B$BForse ti conviene chiudere gli occhi.",
  en_title = "The Broken Sigil",
  en_obj = "Retrieve the 5 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.",
}
T[641] = {
  title = "Sigil of Thoradin",
  desc = "La ricostruzione è riuscita alla perfezione, e ora il sigillo può servire ad aprire la chiusura della tomba di Trollbane. Riportalo a Zengu: di sicuro avrà altri compiti per te.",
  obj = "Porta il Sigil of Thoradin restaurato a Zengu a Hammerfall.",
  progress = "$N! Ce l'hai, il secondo sigillo?",
  reward = "Siamo a metà strada per tirare fuori Trol'kalar dalla tomba di Trollbane. Il terzo sigillo non sappiamo bene dove sia, perché pare che chi ce l'ha giri parecchio per l'Arathi, ma ho fiducia che lo troverai.",
  en_title = "Sigil of Thoradin",
  en_obj = "Bring the restored Sigil of Thoradin to Zengu in Hammerfall.",
}
T[642] = {
  title = "La Principessa Intrappolata",
  desc = "Mi chiamo Myzrael e sono una principessa della terra. I giganti, i miei carcerieri, mi hanno intrappolata giù in profondità, sotto gli Arathi Highlands, e questi frammenti di cristallo sono l'unico modo che ho per parlare con il mondo di superficie.$B$BTi prego, aiutami. A est, nella loro Drywhisker Gorge, i Drywhisker Kobolds, alleati dei giganti, hanno un frammento come questo. Per alimentare l'ammasso devi togliere ai coboldi i Motes of Myzrael e metterglieli sopra.$B$BTi supplico, $N, aiutami!",
  obj = "Raccogli 12 Motes of Myzrael, poi portali agli Iridescent Shards nella Drywhisker Gorge.",
  progress = "Questo ammasso di frammenti somiglia molto agli Shards of Myzrael, ma dentro non ci pulsa la stessa sensazione di sicurezza.",
  reward = "Ah! Hai attivato questi frammenti, e già mi sento più me stessa!$B$BMa ahimè, sono ancora lontana dalla libertà...",
  en_title = "The Princess Trapped",
  en_obj = "Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.",
}
T[643] = {
  title = "Sigil of Arathor",
  desc = "A malapena controllano Stromgarde, figuriamoci tutti gli Arathi Highlands, eppure il principe umano fa trottare per le campagne quel che resta della sua cavalleria. Non capisco perché lo faccia, ma chi ci capisce qualcosa del modo di pensare degli umani, eh?$B$BQuali che siano le sue ragioni, quello che conta è che ha dato uno dei sigilli a Lieutenant Valorcall, il capo della loro cavalleria. Trovalo e riportami il suo sigillo.",
  obj = "Recupera il Sigil of Arathor e portalo a Zengu a Hammerfall.",
  progress = "Valorcall non sarà facile da rintracciare, $N: a cavallo si sposta in fretta. Ma il suo sigillo dobbiamo averlo lo stesso.",
  reward = "Perdere il capo della cavalleria sarà un duro colpo per i difensori di Stromgarde. E c'è di meglio: ci manca un sigillo solo, poi Trol'kalar sarà tutta nostra.",
  en_title = "Sigil of Arathor",
  en_obj = "Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall.",
}
T[644] = {
  title = "Sigil of Trollbane",
  desc = "L'ultimo sigillo che serve per aprire la tomba di Thoras Trollbane lo custodisce di persona suo figlio, che vive nel cuore di Stromgarde, in una cappella nei quartieri in mano alla milizia. Prince Galen è ben protetto e come guerriero non è certo uno sprovveduto, quindi questo compito potrebbe rivelarsi molto difficile.",
  obj = "Uccidi Prince Galen Trollbane e porta il Sigil of Trollbane a Zengu a Hammerfall.",
  progress = "Sei $Gtornato:tornata;, $N. E la stirpe di Ignaeus Trollbane, è spezzata?",
  reward = "Che giornata, $C. Il sangue di Trollbane non perseguiterà più il mio popolo, e i sigilli che servono per prendere Trol'kalar ce li abbiamo noi. Presto, molto presto, colpiremo gli odiati troll di Zul'Gurub.",
  en_title = "Sigil of Trollbane",
  en_obj = "Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall.",
}
T[645] = {
  title = "Trol'kalar",
  desc = "E questo che cos'è? Messi insieme, i quattro sigilli si sono fusi in uno solo. Senza dubbio riuscirà a spezzare le protezioni sulla tomba di Trollbane.$B$BI resti di Trollbane sono sepolti nel Sanctum dietro la cappella di Stromgarde. Recupera Trol'kalar.",
  obj = "Recupera Trol'kalar dalla tomba di Trollbane a Stromgarde.",
  progress = "Le incisioni nella pietra della facciata della tomba di Trollbane corrispondono alle linee luminose del Sigil of Ignaeus...",
  reward = "Quando allinei le incisioni sulla facciata della tomba di Trollbane con le linee luminose del Sigil of Ignaeus, un lampo di luce consuma il Sigillo, e la stretta delle mani di pietra lascia andare la leggendaria spada Trol'kalar.",
  en_title = "Trol'kalar",
  en_obj = "Retrieve Trol'kalar from Trollbane's tomb in Stromgarde.",
}
T[646] = {
  title = "Trol'kalar",
  desc = "La luce svanisce piano piano: la spada Trol'kalar, custodita in un fodero di pietra, è libera.",
  obj = "Consegna Trol'kalar a Zengu a Hammerfall.",
  progress = "$N! Ce l'hai, la spada?",
  reward = "Per generazioni le forze di Strom e di Arathor hanno messo in ginocchio i troll. Adesso la loro arma più potente ce l'abbiamo noi. Basta avanzare a passo di lumaca nelle foreste afose di Zul'Gurub.$B$BCi hai aiutato tanto, $N, e i troll Darkspear sono in debito con te.$B$BFarò in modo che la spada arrivi a Nimboya a Grom'gol.",
  en_title = "Trol'kalar",
  en_obj = "Deliver Trol'kalar to Zengu in Hammerfall.",
}
T[647] = {
  title = "MacKreel's Moonshine",
  desc = "Ieri sera ci ho dato dentro col buon vecchio Torcibudella! Se Longbraid scoprisse che sono collassato durante il turno di guardia, mi staccherebbe la testa.$B$BHo la zucca che mi fa un male cane: con tutto quel rombo, pareva che mi fosse passata sopra la testa un'intera brigata di siege engines.$B$BOh, cielo, guarda che ora s'è fatta! Avevo promesso a Brewmeister Bilger, a Southshore, di saldare il debito mandandogli un po' di Torcibudella.$B$BMa alla scadenza mancano solo 15 minuti! Gliela porteresti tu questa partita, per favore? E sbrigati!",
  obj = "Porta il MacKreel's Moonshine a Brewmeister Bilger a Southshore.",
  progress = "Che mi racconti, $R?",
  reward = "Ah, in una giornata fredda non c'è niente che ti scaldi meglio del MacKreel's Moonshine di Foggy! E io che pensavo che quel piccolo disgraziato fosse di nuovo in ritardo coi pagamenti. Grazie, $Gamico:amica;! Grazie davvero!",
  en_title = "MacKreel's Moonshine",
  en_obj = "Take MacKreel's Moonshine to Brewmeister Bilger in Southshore.",
}
T[648] = {
  title = "Salva OOX-17/TN!",
  desc = "La voce dello gnomo torna a gracchiare dal robot:$B$B\"Devo portare OOX-17/TN in un posto aperto e sicuro, dove possa cominciare una lunga procedura di decollo. Ha un sistema di occultamento incorporato, ma da qui mi ci vuole tempo per rimetterlo in funzione. Mi serve che tu scorti il robot da dove si trova adesso fino a, diciamo, Steamwheedle Port! Dovrebbe essere il posto perfetto, e la strada abbastanza lunga per riattivare tutto!\"$B$B\"Scortalo sano e salvo fino al porto, poi vieni a parlarmi a Booty Bay! Oglethorpe Obnoticus — chiudo!\"",
  obj = "Scorta OOX-17/TN fino a Steamwheedle Port, poi fai rapporto a Oglethorpe Obnoticus a Booty Bay.",
  reward = "Oh, sei TU $Gil grande salvatore:la grande salvatrice; di OOX-17/TN! Non so nemmeno da dove cominciare per ringraziarti! La mia serie di robot viaggiatori va ancora perfezionata, ma recuperandolo mi hai risparmiato ore e ore di lavoro per ricostruirlo e un bel po' di monete d'oro per rimontarlo!$B$BPer favore, scegli pure uno di questi oggetti che ho qui. Spero che ne farai buon uso. Grazie ancora per il tuo generoso aiuto: io e i miei robot siamo in debito con te!",
}
T[649] = {
  title = "Recupero del Vino Dolce",
  desc = "Ho un lavoro di recupero per te: se sei $Gun intenditore:un'intenditrice; di buon vino dolce come me, ti piacerà. Vino dolce!$B$BÈ una bevanda, $Gzuccone:zuccona;.$B$BIn un avamposto abbandonato dell'Orda c'è una scorta di Hinterlands Honey Ripple che risale a quando era ancora in attività. Un vino dolce buono così non si trova più! Uno dei soci tonti di Malton sa come si fa, perciò tu andrai lì e mi porterai una cassa di vino dolce imballato, più due bottiglie per la mia collezione! Parla con Malton, che ti darà i dettagli.",
  obj = "Parla con Malton Droffers a Orgrimmar.",
  reward = "Ah già, il vino dolce che vuole papà! Vuole venderlo a una taverna qui a Orgrimmar, ma se è nella confezione originale ci guadagneremo di più. Conosco qualcuno che può imballarlo, e sta nelle Hinterlands, dove c'è il vino. Solo che è, ehm, un alto elfo.$B$BBeh, è un alto elfo buono, visto che non fa parte dell'Alleanza. Beh, più che buono è un alto elfo ubriacone. Ama, e dico AMA, il cicchetto.",
}
T[650] = {
  title = "Recupero del Vino Dolce",
  desc = "L'elfo con cui devi parlare è Gilveradin Sunchaser. Gli basta l'odore per riconoscere qualsiasi vino, annata compresa! È lui che può imballare il vino dolce che ci serve, quindi dovrai andarlo a trovare. Ci servono sei bottiglie da imballare, più due per papà e quante ne vorrà lui... e credimi, ne vorrà. Quando avrai imballato il vino e preso le due bottiglie di papà, torna qui!$B$BL'accampamento di Gilveradin è vicino a un rifugio di alti elfi nelle Hinterlands, e quelli non sono alti elfi buoni. Fidati.",
  obj = "Parla con Gilveradin Sunchaser; il suo accampamento si trova in Hinterlands.",
  reward = "Ah, conosci dunque Malton? È un mio vecchio compagno di bevute. Vedi, ho trovato qualcosa che trascende i confini dei trattati e delle alleanze artificiali — l'alcol. Se ognuno di noi placasse la sete con le sue beate virtù, staremmo tutti molto meglio nello spirito.$B$BAhimè, qualcosa mi dice che non sei $Gvenuto:venuta; fin qui per apprendere le virtù redentrici dell'alcol, non è vero.",
}
T[651] = {
  title = "Pietre del Vincolo",
  desc = "Sparse per Arathi ci sono quattro Pietre del Vincolo: sono loro a tenermi imprigionata sotto terra.$B$BPer sbloccarle devi aprire la più potente: la Stone of Inner Binding. E per riuscirci ti servono le chiavi delle altre tre.$B$BLe pietre hanno dei guardiani a sorvegliarle, ma se sei $Gastuto:astuta;, o $Gfortunato:fortunata;, potresti trovare il modo di scacciarli.",
  obj = "Prendi la Burning Key, la Cresting Key e la Thundering Key dalla Stone of West Binding, dalla Stone of East Binding e dalla Stone of Outer Binding.$B$BPortale alla Stone of Inner Binding.",
  progress = "Questa è la Stone of Inner Binding, la più potente delle pietre del vincolo: va sbloccata perché le altre si possano aprire.",
  reward = "<Myzrael parla attraverso la pietra.>$B$BCe l'hai fatta! Hai aperto le Pietre del Vincolo! Sento le catene che mi stringono allentarsi, e la libertà è sempre più vicina.$B$BSei $Gun:una; $C nobile, $N. $GIl mio salvatore:La mia salvatrice;!",
  en_title = "Stones of Binding",
  en_obj = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.$B$BBring them to the Stone of Inner Binding.",
}
T[652] = {
  title = "Spezzare la Chiave di Volta",
  desc = "Con le Pietre del Vincolo aperte la mia prigionia si è molto allentata, ma c'è ancora una serratura che mi tiene incatenata: la Chiave di Volta che vedi in questo cerchio di pietre. E la chiave ce l'ha in mano uno dei miei carcerieri, la stone watcher Fozruk.$B$BDevi togliere a Fozruk quella chiave, che le guardie di pietra chiamano Rod of Order, e usarla per aprire la Chiave di Volta.$B$B$N, hai fatto tanto per aiutarmi. Ancora un po'... e la mia gratitudine scuoterà la terra fin dalle fondamenta!",
  obj = "Trova e uccidi Fozruk. Porta la Rod of Order alla Chiave di Volta negli Arathi Highlands.",
  progress = "La Chiave di Volta è carica di un'enorme energia geomantica.",
  reward = "Infili la verga nella chiave di volta. E senti un tremito sotto di te...",
  en_title = "Breaking the Keystone",
  en_obj = "Find and kill Fozruk.  Bring the Rod of Order to the Keystone in the Arathi Highlands.",
}
T[653] = {
  title = "Gli Alleati di Myzrael",
  desc = "<Parla Myzrael.>$B$BLibera! SONO LIBERA! Libera di raccogliere le forze, nascosta ai miei carcerieri. Se mi affrontassero adesso, mi sopraffarebbero di certo e mi imprigionerebbero di nuovo.$B$BMa verrà il tempo in cui affronterò i giganti, e allora si pentiranno di avermi tenuta prigioniera!$B$BSei $Gun nobile alleato:una nobile alleata;, $N. Prima o poi avrò ancora bisogno del tuo aiuto: quando sarò pronta, dovrai evocarmi in superficie.$B$BParla con Gerrig Bonegrip: lo trovi a Ironforge, in una bottega della Forlorn Cavern. Lui sa come evocarmi.",
  obj = "Parla con Gerrig Bonegrip nella Forlorn Cavern di Ironforge.",
  reward = "La Signora mi ha parlato del tuo arrivo, $C. $GBenvenuto:Benvenuta; nella mia dimora: anche tu, come me, servi una causa superiore.",
  en_title = "Myzrael's Allies",
  en_obj = "Speak with Gerrig Bonegrip in the Forlorn Cavern of Ironforge.",
}
T[654] = {
  title = "Campionamento sul Campo a Tanaris",
  desc = "Appena attivi la fonte di energia, la field testing kit si mette a brillare e a vibrare. A quanto pare funziona come previsto.$B$BSecondo Chief Engineer Bilgewhizzle, adesso hai due ore per raccogliere nel deserto di Tanaris i dati che ti servono. Se allo scadere delle due ore non li hai raccolti, andranno tutti persi e dovrai comprargli un'altra fonte di energia.$B$BQuando avrai finito, torna da lui.",
  obj = "Ottieni campioni validi da 8 basilischi, 8 iene e 8 scorpioni. Riporta l'attrezzatura per le analisi a Chief Engineer Bilgewhizzle a Gadgetzan prima che la fonte di energia si esaurisca.",
  progress = "Allora, hai preso tutto quello che ti serviva? Perché se non l'hai fatto e l'energia si esaurisce, si rovinerà tutto quello che c'è dentro e dovrai ricominciare da capo.$B$BEhi, non aspettarti compassione da me; a me interessa solo che la Gadgetzan Water Company faccia profitti, e se per questo devo venderti fonti di energia finché non potremo permetterci di importare l'acqua dalle sorgenti gelide di Dun Morogh, così sia!",
  reward = "D'accordo, allora, mi basta un secondo per togliere la fonte di energia. Poi con l'attrezzatura potrai fare quello che vuoi, senza paura di perdere i dati che ci sono dentro.",
}
T[655] = {
  title = "Hammerfall",
  desc = "Lo ricordo ancora bene, come fosse ieri... Tanti anni senza speranza, legato a questo posto terribile da legno e acciaio. E poi finalmente, finalmente! Ecco il Capoguerra. Doomhammer, nell'armatura color mezzanotte, con il martello da guerra alzato.$B$BÈ stato... troppo terribile... Il nostro più grande eroe abbattuto dal colpo di un codardo. Gli è piombato alle spalle a cavallo, e la lancia lo ha trapassato... Sono caduto in ginocchio. Che speranza c'era? Che speranza c'è...",
  obj = "Parla con Tor'gan a Hammerfall.",
  reward = "Ah, parli di Gor'mul. Sì, da quello che dice sembra che non si sia mai ripreso dalla morte di Doomhammer.$B$BGor'mul era prigioniero qui quando Thrall e Orgrim hanno combattuto per liberare il campo, ma mentre la terra tremava e i nostri fratelli scappavano, lui è rimasto indietro. Per anni ha vagato da solo, perduto, senza meta e senza speranza, finché non siamo tornati a stabilirci qui a Hammerfall.",
  en_title = "Hammerfall",
  en_obj = "Speak with Tor'gan in Hammerfall.",
}
T[656] = {
  title = "Evocare la Principessa",
  desc = "Devi sconfiggere Myzrael prima che si rafforzi. Altrimenti, appena avrà raccolto abbastanza potere, sfiderà i suoi carcerieri! C'è chi crede di poterla tenere sotto controllo, ma se fosse possibile, perché mai i giganti l'avrebbero incatenata??$B$BLogica da matti, eh?$B$BEvocala agli Shards of Myzrael, dove le hai parlato la prima volta, e sconfiggila. Poi prendi le sue Eldritch Shackles e legale agli Shards of Myzrael.$B$BA quel punto sarà di nuovo intrappolata.",
  obj = "Va' agli Shards of Myzrael, evocala e sconfiggila.$B$BRaccogli le sue Eldritch Shackles e legale agli Shards of Myzrael.",
  progress = "Ora gli Shards of Myzrael sono stranamente silenziosi.",
  reward = "Appena le eldritch shackles stringono i Frammenti, dalle profondità si leva un lamento disumano. Dopo l'urlo, un ruggito.$B$BGli Shards of Myzrael non danno più quel senso di calore e di sicurezza di un tempo. Adesso pulsano di una minaccia aperta... come se la cosa che sta sotto di loro covasse cattive intenzioni verso la superficie.",
  en_title = "Summoning the Princess",
  en_obj = "Go to the Shards of Myzrael, summon her and defeat her.$B$BGather her Eldritch Shackles and bind them to the Shards of Myzrael.",
}
T[657] = {
  title = "Indizi di una Nuova Pestilenza?",
  desc = "<Quae comincia a sfogliare i documenti.>$B$BQuesto È interessante. A quanto pare Apothecary Jorell sta facendo degli esperimenti letali qui a Go'Shek. Non so cosa c'entri con Hillsbrad, ma se lo lasciassimo continuare a Phin non piacerebbe.$B$BMentre non c'eri ci siamo scontrate con degli orchi, e non sono in condizioni di aiutare Kinelory. Se te la senti, le servirà qualcuno che la protegga quando scenderà al podere a rubare tutte le ricerche che Jorell non ha ancora mandato a Tarren Mill.",
  obj = "Parla con Kinelory.",
  reward = "Se servirà a dare pace a Phin, distruggerò con le mie mani ogni singolo Forsaken. Dopo la pestilenza ha fatto tanto per noi. Non avremmo mai pensato di ritrovare degli amici o una famiglia.$B$BQuando sei $Gpronto:pronta;, dimmelo. Cominceremo subito.",
  en_title = "Hints of a New Plague?",
  en_obj = "Speak to Kinelory.",
}
T[658] = {
  title = "Indizi di una Nuova Pestilenza?",
  desc = "Così Phin ti ha mandato a controllare come stiamo? Non mi stupisce — si preoccupa troppo.$B$BSono giorni che teniamo d'occhio il podere, e Kin dice di aver visto poco fa un corriere uscire da quella casetta a sud.$B$BParla tanto, ma quando siamo in zone pericolose posso sempre fidarmi dei suoi sensi.$B$BNon sarai per caso $Gun esperto:un'esperta; di tracce, vero? Pensiamo che il corriere possa portare degli appunti a Tarren Mill. Se riuscissimo a mettere le mani su quei documenti, potremmo fare luce su quello che succede a Hillsbrad.",
  obj = "Trova il Forsaken Courier e riporta i suoi Sealed Folder a Quae vicino a Go'Shek Farm.",
  progress = "Grazie di aiutarci a cercare il corriere, $N.$B$BMentre non c'eri, Kin ha visto uno speziale uscire da quella stessa casa qui a sud. Sono sicura che stanno tramando qualcosa di losco — prima di fare passi avventati, però, mi servono solo le prove.$B$BHai avuto fortuna?",
  reward = "Eccellente!$B$BVediamo un po' di che si tratta...",
  en_title = "Hints of a New Plague?",
  en_obj = "Find the Forsaken Courier and bring back her Sealed Folder to Quae near the Go'Shek Farm.",
}
T[659] = {
  title = "Indizi di una Nuova Pestilenza?",
  desc = "Salute e $Gben trovato:ben trovata;, $N. Guido un gruppo di avventurieri che indaga sugli strani avvenimenti di questa zona.$B$BPoco tempo fa mio cugino, a Hillsbrad, ha dovuto abbattere Stanley, il suo cane: una magia aveva fatto crescere l'animale fino a renderlo enorme, e lui attaccava con ferocia chiunque gli andasse vicino.$B$BSecondo me c'entrano i non morti, e stiamo cercando qualche segno che lo dimostri.$B$BQuae e Kinelory, due delle mie compagne, sono andate al Go'Shek Farm, negli Arathi Highlands, e sono giorni che non si fanno sentire. Potresti trovarle? Comincio a preoccuparmi.",
  obj = "Trova Quae e Kinelory vicino a Go'Shek Farm negli Arathi Highlands.",
  reward = "Cerca di fare meno rumore che puoi, $Gviaggiatore:viaggiatrice;.$B$BAgli orchi non piace granché essere spiati, e questo podere nasconde più di quanto sembra.",
  en_title = "Hints of a New Plague?",
  en_obj = "Find Quae and Kinelory near the Go'Shek Farm in the Arathi Highlands.",
}
T[660] = {
  title = "Indizi di una Nuova Piaga?",
  desc = "D'accordo, $N. Se tu sei $Gpronto:pronta;, lo sono anch'io.$B$BAndiamo?",
  obj = "Proteggi Kinelory finché non torna da Quae.",
  progress = "Non è più tempo di chiacchiere. Se ti sta almeno un po' a cuore la gente di Hillsbrad, proteggi Kinelory.",
  reward = "Ci hai reso un gran servizio, $N. Grazie.$B$BSpero che laggiù Kin non ti abbia dato troppo da fare. È molto socievole, ma quando sei $Gsuo nemico:sua nemica; sa essere altrettanto letale.",
  en_title = "Hints of a New Plague?",
  en_obj = "Protect Kinelory until she returns to Quae.",
}
T[661] = {
  title = "Indizi di una Nuova Piaga?",
  desc = "Dopo una notte in taverna ho visto Kinelory ridotta molto peggio di così: si vede che l'hai protetta bene.$B$BCon gli oggetti che ha riportato dalla fattoria, Phin dovrebbe almeno farsi un'idea di cosa sta succedendo qui ad Arathi. Noi resteremo qui ancora un po', per essere sicuri che al tuo attacco non segua una rappresaglia. Te la sentiresti di tornare a Southshore a parlare con Phin?",
  obj = "Trova Phin Odelic a Southshore.",
  reward = "Allora quei due combinaguai stanno bene, dopotutto? Ah ah, che piacere saperlo. Grazie delle notizie su dove sono e su come stanno — sono davvero felice che siano ancora vivi; come amici e compagni di viaggio sono insostituibili.$B$BMa... è più importante ringraziarti come si deve per l'aiuto. Ecco. Prendi questo, insieme ai ringraziamenti del mio gruppo.$B$BCon un po' di fortuna scopriremo cosa stanno tramando i Forsaken e metteremo fine ai loro piani.",
  en_title = "Hints of a New Plague?",
  en_obj = "Find Phin Odelic in Southshore.",
}
T[662] = {
  title = "Recupero in Acque Profonde",
  desc = "O'Breen ha portato le navi dentro la cala: eravamo sicuri che il tesoro fosse proprio qui. La Harbinger ha attraccato senza problemi, ma mentre si avvicinavano la Maiden's Folly e lo Spirit of Silverpine la marea ha cominciato a calare. Mai vista una cosa più strana!$B$BQuelle due navi si sono incagliate su qualcosa... una specie di tempio nella barriera corallina. Sono andate a fondo in un attimo, una vera tragedia.$B$BPrima di andarcene dobbiamo recuperare i loro Diari di Bordo e le Carte Nautiche. Non possiamo lasciare quelle informazioni a portata di occhi indiscreti!",
  obj = "First Mate Nilzlix vuole che tu recuperi le Carte Nautiche e i Diari di Bordo dalla Maiden's Folly e dallo Spirit of Silverpine.",
  progress = "A che punto è la missione di ricerca e recupero, $N? Quei Diari di Bordo e quelle Carte Nautiche della Maiden's Folly e dello Spirit of Silverpine dobbiamo riprenderceli per forza.$B$BSe quelle informazioni finissero in mani nemiche, Fleet Master Seahorn ci farebbe camminare sull'asse.$B$BSempre che riusciamo a uscirne, da questo pasticcio...",
  reward = "Il comando di Booty Bay si sentirà un po' sollevato a sapere che queste informazioni sono al sicuro. Ben fatto, $N.",
  en_title = "Deep Sea Salvage",
  en_obj = "First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine.",
}
T[663] = {
  title = "Terra in Vista!",
  desc = "Lolo vede $Gun:una; $Gpiccolo:piccola; $R! Sempre di vedetta, Lolo è!$B$B$GBenvenuto:Benvenuta; a Faldir's Cove. Captain O'Breen ha detto che qui ci saremmo fermati solo poche ore, giusto il tempo di raccogliere il tesoro e tornare a Booty Bay.$B$BMa Lolo pensa che resteremo qui molto più a lungo. Le altre due navi della nostra formazione le abbiamo perse. Povere Spirit of Silverpine e Maiden's Folly. In fondo al mare riposano, ora!$B$BSe pensi di restare da queste parti, Lolo ti consiglia di parlare con Captain O'Breen.",
  obj = "Parla con Captain O'Breen a Faldir's Cove.",
  reward = "Ahoy, compare.$B$BÈ stato un gran brutto pasticcio. Se Seahorn scopre cos'è successo, si prende la mia nave.$B$BUno degli aggeggi del Professore diceva che il tesoro perduto era vicino a questa cala. Ho portato la Harbinger in porto e ho fatto segnale allo Spirit of Silverpine e alla Maiden's Folly di fare lo stesso.$B$BPoi il mare ha brontolato. La marea è calata e le due navi si sono schiantate contro la scogliera.$B$BMa non è solo una scogliera. Là sotto c'è qualcosa....$B$BAiuta il mio equipaggio e sarai $Gricompensato:ricompensata; profumatamente.",
  en_title = "Land Ho!",
  en_obj = "Talk to Captain O'Breen in Faldir's Cove.",
}
T[664] = {
  title = "Dispiaceri Affogati",
  desc = "Argh, che vita orribile. A quest'ora dovrei starmene in fondo al mare, e invece sono qui seduto accanto al fuoco a respirare aria fresca.$B$BLa ciurma ha fatto di tutto per salvare la mia bella Maiden's Folly. Benedetti ragazzi, benedetti i loro cuori.$B$BO'Breen è arrivato a riva sano e salvo, ma a noi è andata peggio. Lo giuro, il mare ci è sprofondato sotto.$B$BUn attimo eravamo a galla e quello dopo l'acqua entrava a fiotti. E quelle bestie! Hanno ammazzato tutti i superstiti, quell'orribile feccia naga. Poi mi si è fatto tutto nero e mi sono ritrovato qui, in salvo.$B$BQuelle bestie le voglio vedere morte.",
  obj = "Captain Steelgut a Faldir's Cove vuole che tu uccida 10 Daggerspine Raiders e 3 Daggerspine Sorceresses.",
  progress = "Bah, forse quella feccia naga dovrei andare ad ammazzarla da solo. Tanto è chiaro che tu non ne hai intenzione.$B$BMagari ti rimedio un paio di ferri da maglia, così ti tieni $Goccupato:occupata;.",
  reward = "Hai fatto un bel lavoro là fuori, $N.$B$BQuella feccia ha avuto quel che si meritava. Niente mi ridarà mai la nave o la ciurma, ma la morte di quei naga mi consola un po'.",
  en_title = "Drowned Sorrows",
  en_obj = "Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.",
}
T[665] = {
  title = "Tesoro Sommerso",
  desc = "Ora che siamo Blackwater Raiders a tutti gli effetti, tocca a noi aiutare Mr. O'Breen a ritrovare il tesoro elfico perduto.$B$BSenza aiuto, trovare le gemme nel buio del mare è quasi impossibile. Per questo il dottore ha costruito degli occhialini che ci daranno una mano, ma gli serve caricarli con l'energia della pietra incantata che sta nella grotta, poco più su sulla collina.$B$BSolo che la grotta è maledetta! Appena ci avviciniamo, finiamo in un'imboscata. Tu difendimi, e io potrò incanalare l'energia della pietra negli occhialini.",
  obj = "Scorta il Professor Phizzlethorpe fino alla grotta e ritorno.",
  progress = "Non è il momento di chiacchierare! Bisogna caricare gli occhialini con il potere della pietra!",
  reward = "Adesso gli occhialini funzionano alla perfezione! Ben fatto, $N.",
  en_title = "Sunken Treasure",
  en_obj = "Escort Professor Phizzlethorpe to the cave and back.",
}
T[666] = {
  title = "Tesoro Sommerso",
  desc = "Il tesoro è rimasto così a lungo sul fondo del mare che le gemme si sono calcificate, coperte da uno spesso strato di pietra. Ma con il potere racchiuso in questi occhialini le troverai senza fatica.$B$BUn pizzico d'ingegno gnomico fa miracoli!$B$BTi presto i Goggles of Gem Hunting, $N: vedi se riesci a raccogliere un po' del tesoro perduto per Captain O'Breen.$B$BScenderei io stesso laggiù a nuoto, ma... ehm... be', quassù ho importanti faccende scientifiche da sbrigare, sulla terraferma sicura e asciutta... ehm, sì.",
  obj = "Doctor Draxlegauge, a Faldir's Cove, vuole che tu raccolga 10 Elven Gems e che restituisca i Goggles of Gem Hunting quando hai finito.",
  progress = "Allora, come sono andati gli occhialini? Ha funzionato tutto a dovere? Se c'è bisogno, posso regolarli.$B$BAh, quando hai finito me li devi restituire. Sono sicuro che più avanti a Captain O'Breen serviranno in tante occasioni.",
  reward = "Magnifico, $N! Il Capitano sarà contentissimo! E aspetta che la notizia arrivi al Contrammiraglio Seahorn!",
  en_title = "Sunken Treasure",
  en_obj = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.",
}
T[667] = {
  title = "Morte dagli Abissi",
  desc = "Brutta faccenda. A quanto pare i Daggerspines si stanno radunando per attaccare.$B$BTutti sanno che i Naga in battaglia non hanno pietà. Non smetteranno di attaccare finché non sarò morto.$B$BLa mia vita non vale più di quella dei miei uomini, ma devi aiutarmi a difendermi: senza di me, che conosco i mari, la ciurma non riuscirà a tornare a Booty Bay.$B$BI naga arriveranno dal mare. Mi serve che resti quassù con me a respingere l'attacco: mettiti al cannone e ricacciali.$B$BSei $Gpronto:pronta;, $N?",
  obj = "Proteggi Shakes O'Breen durante l'attacco.",
  reward = "Siamo sopravvissuti all'attacco!$B$BSenza di te non ce l'avremmo fatta, $N.$B$BSalpiamo appena si alza la marea. Se non fossi $Gun eroe:un'eroina; così promettente, ti prenderei nella mia ciurma, ma si vede che hai di meglio da fare.$B$BAnche se sei $Gun:una; $R $Gmingherlino:mingherlina;....",
  en_title = "Death From Below",
  en_obj = "Protect Shakes O'Breen during the attack.",
}
T[668] = {
  title = "Tesoro Sommerso",
  desc = "Non facciamo aspettare Captain O'Breen: vorrà vedere queste gemme con i suoi occhi. Dopotutto, siamo qui per questo!$B$BE poi, dopo qualche settimana in compagnia di questi pirati, il professore e io abbiamo capito che per la nostra salute non c'è niente di peggio che farci trovare con il loro tesoro in mano.$B$BEcco, $N, porta queste gemme a O'Breen.",
  obj = "Porta le Elven Gems a Captain O'Breen.",
  progress = "Ohilà, $C. Che ti porta sul ponte?",
  reward = "Allora alla fine quei piccoli gnomi hanno dimostrato quanto valgono? Lo sapevo che c'era un motivo se ci tenevamo intorno quei tappetti!",
  en_title = "Sunken Treasure",
  en_obj = "Take the Elven Gems to Captain O'Breen.",
}
T[669] = {
  title = "Tesoro Sommerso",
  desc = "Fleet Master Seahorn vorrà sapere subito della nostra scoperta.$B$BMa, come vedi, da qui non possiamo andarcene. La marea è troppo bassa, e in più quelle dannate creature che abbiamo disturbato tengono d'occhio ogni nostra mossa.$B$BRenderesti un grande servizio ai Blackwater Raiders se riuscissi a far sapere a Fleet Master Seahorn, a Booty Bay, che abbiamo trovato il tesoro e che ci stiamo dando da fare per recuperarne altro. Portagli questo campione come prova.",
  obj = "Porta la Sample Elven Gem a Fleet Master Seahorn a Booty Bay.",
  progress = "Che cosa ti porta a Booty Bay, $C?",
  reward = "Ah, sul buon vecchio Shakes O'Breen si può sempre contare! Lo sapevo che era il Capitano giusto per questa missione!",
  en_title = "Sunken Treasure",
  en_obj = "Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay.",
}
T[670] = {
  title = "Tesoro Sommerso",
  desc = "Di', $N, sembri $Gun tipo avventuroso:una tipa avventurosa;. La mia flotta resta bloccata a Booty Bay finché non riusciamo a rifornirci.$B$BCi sono cose grosse in ballo, qui e all'estero, e devo far arrivare una corrispondenza top secret a Shakes O'Breen, che è fermo al largo della costa di Arathi.$B$BPosso contare su di te per consegnare questo messaggio con sicurezza e discrezione?",
  obj = "Consegna la Seahorn's Letter a Shakes O'Breen in Arathi Highlands.",
  progress = "Allora, Seahorn è rimasto colpito? Scommetto che aveva un sorriso che andava da Booty Bay fino a Ratchet.",
  reward = "Grazie di aver affrontato un viaggio così lungo e pericoloso. I Blackwater Raiders ti sono grati.",
  en_title = "Sunken Treasure",
  en_obj = "Deliver Seahorn's Letter to Shakes O'Breen in Arathi Highlands.",
}
T[671] = {
  title = "Magie Immonde",
  desc = "Nell'aria ho sentito qualcosa di strano... una sensazione che mi sobbolle nel sangue. Avevo i miei sospetti. Sono andato a cercare da dove veniva quel turbamento e a ovest, al Northfold Manor, ho scoperto quel che restava di un'evocazione demoniaca. Più mi avvicinavo, più il sangue mi ribolliva e la rabbia mi cresceva dentro.$B$BA terra ho visto un amuleto di sanguinite, che aiuta a evocare i demoni. Quello che ho trovato io, però, era esaurito. Me ne serve un altro da esaminare, ma al maniero non oso tornarci. Me ne porteresti qualcuno?",
  obj = "Procura 10 Bloodstone Amulets per Tor'gan a Hammerfall.",
  progress = "Nelle vene mi scorre ancora il sangue che un tempo era maledetto, $N. Se qualcuno... qualcosa sta evocando demoni, bisogna fermarlo.",
  reward = "Mi ci vorrà un po' di tempo per capire cosa vuole davvero lo Syndicate, ma che abbia a che fare con la magia oscura e demoniaca è evidente, e questo mi preoccupa. Quando ne saprò di più, te lo farò sapere.",
  en_title = "Foul Magics",
  en_obj = "Get 10 Bloodstone Amulets for Tor'gan in Hammerfall.",
}
T[672] = {
  title = "Risollevare gli Spiriti",
  desc = "Abbiamo provato a farlo ambientare, a tirarlo su di morale, raccontandogli della nostra possente città, Orgrimmar, nel Kalimdor, ma non c'era niente che lo smuovesse.$B$BI racconti del nostro giovane Capoguerra, Thrall, che porta l'armatura e il martello di Orgrim... ma forse... Forse! Se gli mostrassimo la nostra magia sciamanica appena scoperta, potrebbe ritrovare la speranza. Vale la pena tentare!$B$BUn piccolo oggetto potremmo farlo per lui, sì... Portami degli occhi di raptors e vedrò cosa posso fare.",
  obj = "Procurati 10 Highland Raptor Eyes dagli Highland Striders e dagli Highland Thrashers per Tor'gan a Hammerfall.",
  progress = "Creerò un amuleto che darà a Gor'mul un po' della forza dei raptors. Forse gli risveglierà dentro qualche fiamma...",
  reward = "Eccellente. Gli spiriti dei raptors che hanno dato questi occhi daranno forza a chi porterà questo amuleto.",
  en_title = "Raising Spirits",
  en_obj = "Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall.",
}
T[673] = {
  title = "Magie Immonde",
  desc = "Non ho alcun dubbio: dentro le mura di Stromgarde vive un potente stregone. Ogni tanto, con una reliquia magica arcana, ha evocato terribili demoni in gran numero. Dobbiamo eliminare la fonte della sua energia.$B$BTrova lo stregone e uccidilo. Qualunque oggetto magico gli trovi addosso, portamelo: penserò io a distruggerlo, così nessuno userà più il suo potere per contaminare questa terra.",
  obj = "Recupera il Globo di Sanguinite di Marez Cowl e portalo a Tor'gan a Hammerfall.",
  progress = "Il bruciore nel sangue... cresce ogni giorno di più. Lo stregone va fermato.",
  reward = "Quando avrò distrutto questo globo, le mie notti agitate lasceranno il posto a sonni tranquilli. Grazie, $N. È un ricordo agghiacciante del terribile potere che i demoni avevano sugli orchi, prima che Hellscream li liberasse dalla loro maledizione.",
  en_title = "Foul Magics",
  en_obj = "Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.",
}
T[674] = {
  title = "Risollevare gli Spiriti",
  desc = "Ecco, porta questo amuleto a Gor'mul e vedi se la forza dei raptors riesce a risvegliare la fiamma del guerriero che un tempo gli ardeva nelle vene.",
  obj = "Consegna il Raptor Talon Amulet a Gor'mul.",
  progress = "Che speranza può esserci, se la mano di un codardo può uccidere il più possente dei possenti? Che speranza, te lo chiedo!",
  reward = "Cos'è questo? Osso levigato. E che me ne faccio dell'osso levigato? Sarà un ninnolo a ridare all'Orda la sua gloria?",
  en_title = "Raising Spirits",
  en_obj = "Give the Raptor Talon Amulet to Gor'mul.",
}
T[675] = {
  title = "Risollevare gli Spiriti",
  desc = "<Gor'mul getta a terra l'amuleto.>$B$BTi ha mandato Tor'gan, vero? Pah! Non capirò mai perché abbia pietà di me. La pietà me l'hanno negata quando non mi hanno lasciato morire in battaglia insieme al mio Capoguerra. Crudele, il colpo che mi ha inferto il destino...",
  obj = "Parla con Tor'gan.",
  reward = "Non ha funzionato, vedo. Eppure sento che, mostrandogli il potere degli sciamani, alla fine Gor'mul tornerà fiero come un tempo. L'amuleto era troppo debole per fargli vedere il nostro nuovo potere.",
  en_title = "Raising Spirits",
  en_obj = "Speak with Tor'gan.",
}
T[676] = {
  title = "Il Martello Potrebbe Cadere",
  desc = "Smidollati... tutti quanti. E tu, $C, che hai da guardare? Ti credi speciale, eh? E allora perché non lo dimostri?$B$BL'avamposto di Hammerfall, in Arathi, è sotto attacco, e se non gli mandiamo presto aiuti per loro sarà la fine.$B$BPrima di correre là, però, ti conviene mettere alla prova le tue capacità. In Arathi, a nord-est di Stromgarde, c'è un tumulo degli ogres dove vive la tribù Boulderfist. Quando saprai tener testa agli ogres e agli scagnozzi che stanno laggiù, presentati da Drum Fel a Hammerfall.",
  obj = "Uccidi 8 Boulderfist Ogres e 10 Boulderfist Enforcers, poi trova Drum Fel nell'avamposto di Hammerfall, in Arathi Highlands.",
  progress = "Non ho il tempo di affilare l'ascia, e tanto meno di lasciare l'avamposto per abbattere le bestie che vorrebbero uccidere la mia gente.$B$BNon sembri avere l'esperienza di un soldato semplice, figuriamoci quella di $Gun vero e proprio:una vera e propria; $C, cosa vuoi, $N?",
  reward = "Allora, ti credi abbastanza forte da aiutare Hammerfall? E sia.$B$BO Tallow ti ha $Gmandato:mandata; a quel tumulo degli ogres sperando che ti facessi ammazzare, o pensa che tu sia in grado di aiutarci. In ogni caso ormai sei qui, e mi servono altri soldati per far fronte a questi attacchi continui.$B$BSe hai intenzione di restare a Hammerfall, riposati un po' e torna da me quando sarai $Gpronto:pronta;. Le battaglie da combattere non mancano.",
  en_title = "The Hammer May Fall",
  en_obj = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands.",
}
T[677] = {
  title = "Chiamata alle Armi",
  desc = "I Witherbark trolls e gli ogres Boulderfist di Arathi si sono messi insieme per cacciarci da questa terra, ma non sarà per mano loro, né di nessun altro, che andremo incontro al nostro destino. Li uccideremo, e faremo vedere che anche noi qui abbiamo una casa.$B$BI troll ci hanno voltato le spalle; gli ogres, se glielo lasciassimo fare, ci userebbero come cibo e come giaciglio — non succederà niente di tutto questo.$B$BIl nostro attacco comincia dai Witherbark trolls, a sud di qui. Uccidili a frotte, e non tornare finché i loro accampamenti non saranno intrisi di sangue.",
  obj = "Uccidi 10 Witherbark Axe Throwers, 10 Headhunters e 8 Witch Doctors, e torna da Drum Fel nell'avamposto di Hammerfall.",
  progress = "Se non hai ancora portato a termine il compito che ti ho dato, forse oltre che $Gun novellino:una novellina; in guerra sei anche $Gun codardo:una codarda; nel cuore.",
  reward = "Hai le vesti segnate dalla guerra e il sudore che ti cola dalla fronte. Bene, molto bene.",
  en_title = "Call to Arms",
  en_obj = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost.",
}
T[678] = {
  title = "Chiamata alle Armi",
  desc = "Che tu sia forte si vede, $N. Adesso vediamo come te la cavi contro un vero nemico.$B$BI Boulderfist hanno un covo a sud-ovest di qui, verso il ponte dei nani. Se non mi sbaglio, i bruti e i magus che ci stanno saranno per te una sfida più grande — finora per noi lo sono stati.$B$BUccidine quanti più puoi e torna da me in carne e ossa se ci riuscirai, o in spirito se fallirai. Comunque vada, renderò onore alla tua tenacia in battaglia.",
  obj = "Uccidi 10 Boulderfist Brutes e 4 Boulderfist Magi, e torna da Drum Fel nell'avamposto di Hammerfall.",
  progress = "Esiti. Perché? Fino a oggi hai dato prova di una grande forza, $N. Non deludermi adesso.",
  reward = "Sei forte come un kodo, e la tua sete di battaglia fa onore al tuo popolo.",
  en_title = "Call to Arms",
  en_obj = "Kill 10 Boulderfist Brutes and 4 Boulderfist Magi, and return to Drum Fel in the Hammerfall outpost.",
}
T[679] = {
  title = "Chiamata alle Armi",
  desc = "La testa della bestia è pronta per essere tagliata... con grande forza, $N. Hai dimostrato in ogni modo che puoi aiutarci a sferrare quest'ultimo, potente colpo. I capi di questi attacchi si sono fatti un covo tra le rovine di Stromgarde, simbolo lampante della debolezza umana.$B$BTrova e uccidi i signori Boulderfist e i loro sciamani tirapiedi, quelli che vorrebbero cacciarci da queste terre.",
  obj = "Uccidi 15 Boulderfist Shaman e 10 Boulderfist Lords e torna da Drum Fel nell'avamposto di Hammerfall.",
  progress = "Vedo che alla fine il coraggio ti vacilla. Pare che il mio istinto su di te avesse ragione: la tua forza non è niente in confronto alla spavalderia.$B$BTorna da me quando avrai reciso la testa della bestia, o non tornare mai più.",
  reward = "Fai onore al tuo popolo, $N. La minaccia è molto ridotta, e sono sicuro che qui, negli Altopiani, cominceremo a prosperare.",
  en_title = "Call to Arms",
  en_obj = "Kill 7 Boulderfist Shaman and 3 Boulderfist Lords and return to Drum Fel in the Hammerfall outpost.",
}
T[680] = {
  title = "La Vera Minaccia",
  desc = "Tu servi bene mio marito, $C, ma lui non sa perché attaccano Hammerfall.$B$BAnni fa mio marito ha sconfitto Or'Kalar, la pedina di Mug'thol a Stromgarde, e lui lo odia profondamente: non desidera altro che vederlo morto.$B$BI presagi mi dicono che Or'Kalar gli ha teso una trappola, e per questo gli ho nascosto i segni della presenza dell'ogre.$B$BSe scopre dov'è l'ogre, mio marito ci correrà come uno sciocco. Per questo ti chiederei di aiutarmi a uccidere la creatura.",
  obj = "Uccidi Or'Kalar e porta la sua Testa a Korin Fel nell'avamposto di Hammerfall.",
  progress = "Or'Kalar lo trovi vicino alla Tower of Arathor--that. Con la sua morte finiranno gli attacchi a Hammerfall e la vita di mio marito sarà al sicuro.$B$BTe lo leggo negli occhi che mi ritieni debole — persino senza onore — perché taccio. Un giorno imparerai che cosa vuol dire amare come amo io. Forse allora capirai che esiste un altro tipo di forza, e di onore.$B$BIntanto fa' come ti chiedo e uccidi Or'Kalar.",
  reward = "Mi hai reso un grande servizio, $N. Sappi che grazie a quello che hai fatto la vita di mio marito e la sicurezza di Hammerfall sono salve per un altro giorno. Ti prego, accetta questa ricompensa per il tuo coraggio.",
  en_title = "The Real Threat",
  en_obj = "Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost.",
}
T[681] = {
  title = "Northfold Manor",
  desc = "Combattiamo una guerra per Stromgarde, e la stiamo perdendo. La nostra città, un tempo grande, ce la siamo spartita noi, gli ogres e lo Syndicate, e ogni fazione combatte le altre in uno stallo sanguinoso.$B$BMa mentre il nemico cresce, le nostre forze si riducono.$B$BCi serve l'aiuto della città di Southshore, ma finché lo Syndicate controlla il territorio che ci separa, ricevere rifornimenti è difficile.$B$BVa' alla base dello Syndicate nel Northfold Manor e uccidili. Forse allora i nostri convogli di rifornimenti saranno meno sotto pressione, e ne passeranno di più.",
  obj = "Uccidi 10 Syndicate Highwaymen e 6 Syndicate Mercenaries.$B$BTorna da Captain Nials a Refuge Pointe.",
  progress = "$N, a ogni ora che passa la nostra presa su Stromgarde si allenta. Fa' in fretta, o la nostra città cadrà di sicuro.",
  reward = "Molto bene, $N. Ora che quei membri dello Syndicate sono morti, dovrebbe esserci più facile ricevere rifornimenti da Southshore.$B$BForse c'è ancora speranza per la nostra causa.",
  en_title = "Northfold Manor",
  en_obj = "Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries.$B$BReturn to Captain Nials at Refuge Pointe.",
}
T[682] = {
  title = "Stromgarde Badges",
  desc = "A Stromgarde lo Syndicate combatte contro il contingente di milizia che abbiamo laggiù. Per spingere quella marmaglia ad affrontare le nostre truppe, che sono più disciplinate, i capi dello Syndicate hanno messo una taglia sui nostri soldati: pagano in oro ogni Stromgarde Badge preso a un miliziano ucciso.$B$BVogliamo riavere quei distintivi — non possiamo permettere che quei tagliagole si prendano trofei dai nostri coraggiosi caduti!$B$BEntra nella parte di Stromgarde controllata dallo Syndicate e dagli la caccia, per recuperare i nostri distintivi.",
  obj = "Porta gli Stromgarde Badges a Captain Nials a Refuge Pointe.",
  progress = "Hai recuperato degli Stromgarde Badges, $N? Lo Syndicate deve capire che non può guadagnare sui nostri morti.",
  reward = "Grazie, $N. Diremo alle famiglie di questi soldati caduti che sono morti in battaglia.$B$BSarà una notizia dura da portare, ma è meglio che restare nell'incertezza per una persona cara scomparsa.",
  en_title = "Stromgarde Badges",
  en_obj = "Bring 7 Stromgarde Badges to Captain Nials at Refuge Pointe.",
}
T[683] = {
  title = "La Sara Balloo's Plea",
  desc = "$N, ho una piccola richiesta da farti.$B$BPorta questo messaggio al nostro grande sovrano di Ironforge, King Magni Bronzebeard. Una richiesta di poco conto per uno come te, che finora ha dato grande prova di valore per la causa dell'Alleanza.$B$BPresentarmi al Re nell'attuale stato di dolore in cui mi trovo non gioverebbe alla mia causa. Sono certa che capisci.",
  obj = "Porta il messaggio di Sara Balloo a King Magni Bronzebeard, a Ironforge.",
  progress = "Quindi sei tu $N, $Gil:la; $C? Le notizie del tuo contributo all'Alleanza sono arrivate piuttosto lontano, lo sai?$B$BPer quale faccenda ti presenti oggi davanti a me?",
  reward = "Mi basterà un momento per scorrere questa lettera...",
  en_title = "Sara Balloo's Plea",
  en_obj = "Take Sara Balloo's note to King Magni Bronzebeard of Ironforge.",
}
T[684] = {
  title = "RICERCATA: Marez Cowl",
  desc = "Sulla testa di Marez Cowl, consigliera di alto rango e agente dello Syndicate, pende una taglia. L'ultima volta è stata vista nel territorio di Stromgarde in mano allo Syndicate.$B$BPer riscuotere la taglia, rivolgersi a Captain Nials.$B$BAttenzione: Marez è una Stregona abile e astuta, nota per i suoi traffici con i demoni. A chi le dà la caccia si consiglia estrema cautela.",
  obj = "Porta la Marez's head a Captain Nials a Refuge Pointe.",
  progress = "Salute, $C. Hai qualcosa da riferire?",
  reward = "Hai eliminato Marez Cowl? Ben fatto, $N. Davvero ben fatto!$B$BMarez era una minaccia per i nostri difensori di Stromgarde, e si dice che facesse da emissaria fra lo Syndicate e qualche altro potere, più oscuro. Siamo lieti di sapere che non userà più la sua magia contro di noi.",
  en_title = "Wanted!  Marez Cowl",
  en_obj = "Bring Marez's head to Captain Nials at Refuge Pointe.",
}
T[685] = {
  title = "RICERCATI: Otto e Falconcrest",
  desc = "La Stromgarde Militia ha messo delle taglie sulla testa di Lord Falconcrest e della sua guardia del corpo, Otto. Falconcrest dirige le operazioni dello Syndicate negli Arathi Highlands, e con la sua morte finirebbero in grave scompiglio.$B$BLa sua guardia del corpo, Otto, non è un obiettivo strategico, ma è un avversario feroce e ha ucciso decine dei nostri difensori.$B$BPer riscuotere le taglie, rivolgersi a Captain Nials.",
  obj = "Porta l'Otto's Head e la Falconcrest's Head a Captain Nials a Refuge Pointe.",
  progress = "Salve. Hai un rapporto da consegnarmi?",
  reward = "Falconcrest e Otto? Magnifico!$B$BEcco la tua ricompensa, $N. Te la pago con piacere.",
  en_title = "Wanted!  Otto and Falconcrest",
  en_obj = "Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.",
}
T[686] = {
  title = "Il Tributo di un Re",
  desc = "Non mi aspetto che dei bravi nani come Mrs. Balloo capiscano perché, per il bene superiore del nostro popolo, gli scempi della guerra vadano sopportati. La perdita di suo marito mi pesa sull'anima, come quella di ogni nano che combatte in nome dell'Alleanza.$B$BSuo marito non posso riportarlo indietro dalla Twisting Nether, ma posso rendergli omaggio.$B$BCommissionerò a Grand Mason Mablesten un monumento in memoria di Sully Balloo.$B$BMandagli subito un messaggio, $C. Sarai $Gil:la; custode del mio volere.",
  obj = "King Magni Bronzebeard vuole che tu parli con Grand Mason Marblesten.",
  reward = "Allora ti ha mandato King Magni Bronzebeard in persona?$B$BPerbacco, perbacco! Dev'essere una faccenda importante!",
  en_title = "A King's Tribute",
  en_obj = "King Magni Bronzebeard wants you to speak with Grand Mason Marblesten.",
}
T[687] = {
  title = "Theldurin the Lost",
  desc = "Un tempo Theldurin the Lost faceva parte del nostro ordine, il Twilight's Hammer. Poi ha perso il senno e ha disprezzato i nostri insegnamenti, e prima di fuggire ci ha rubato la pergamena di Myzrael! Non siamo riusciti a prenderlo, ma dicono che si nasconda nelle Badlands, folle e farneticante.$B$BPer riportare da noi la Signora devi recuperare la pergamena, e per recuperarla devi trovare Theldurin.",
  obj = "Trova Theldurin the Lost.",
  reward = "Ciao. Ciao, ciao ciao ciao ciao CIAO!$B$BMi dispiace — aspetta, no che non mi dispiace! Non essere $Gmaleducato:maleducata;!$B$BOh no... questi sono discorsi da pazzo.$B$BPerò... a volte essere pazzo è l'unica cosa che mi consola.",
  en_title = "Theldurin the Lost",
  en_obj = "Find Theldurin the Lost.",
}
T[688] = {
  title = "Gli Alleati di Myzrael",
  desc = "<Parla Myzrael.>$B$BLibera! SONO LIBERA! Libera di raccogliere le forze, nascosta ai miei carcerieri. Se mi affrontassero adesso, mi sopraffarebbero di certo e mi imprigionerebbero di nuovo.$B$BMa verrà il tempo in cui affronterò i giganti, e allora si pentiranno di avermi tenuta prigioniera!$B$BSei $Gun nobile alleato:una nobile alleata;, $N. Prima o poi avrò ancora bisogno del tuo aiuto: quando sarò pronta, dovrai evocarmi in superficie.$B$BVa' a Hammerfall e parla con Zaruk. Lui sa come evocarmi.",
  obj = "Parla con Zaruk a Hammerfall.",
  reward = "$GBenvenuto:Benvenuta;, $C. La Signora mi ha avvisato del tuo arrivo. Se dobbiamo riportarla in superficie, abbiamo molto da discutere...",
  en_title = "Myzrael's Allies",
  en_obj = "Speak with Zaruk in Hammerfall.",
}
T[689] = {
  title = "Il Tributo di un Re",
  desc = "Quindi il nostro buon Re vuole un memoriale in onore di un soldato di nome Sully Balloo? E tu dici che il poveretto è morto durante la tragedia del Thandol Span?$B$BBah, ci sarà mai pace su Azeroth?$B$BComunque, ogni incarico del Re è della massima importanza. Per fare un'opera davvero epica e duratura voglio lavorare con una delle pietre migliori che ci siano. Va' alla Darrow Hill, a Hillsbrad, e raccogli per me un po' di Alterac Granite.",
  obj = "Grand Mason Marblesten, a Ironforge, vuole 5 pezzi di Alterac Granite.",
  progress = "$N, $N, $N! Dimmi che hai abbastanza Alterac Granite così che io possa cominciare il mio capolavoro in onore di Sully Balloo.",
  reward = "Perfetto! Meglio di quanto potessi immaginare!$B$BE di immaginazione ne ho parecchia, sai...",
  en_title = "A King's Tribute",
  en_obj = "Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite.",
}
T[690] = {
  title = "La Richiesta di Malin",
  desc = "Salve, $N. Hai l'aria da $Gavventuriero:avventuriera;, e io ho una faccenda di cui qualcuno deve occuparsi.$B$BPoco tempo fa il mio primo maestro, l'Arcimago Trelane, è fuggito da Stromgarde, negli Arathi Highlands, e mi ha chiesto di aiutarlo a recuperare alcuni degli oggetti che ha lasciato là.$B$BLa città è stata assediata e lui ha tentato invano di difendere la Tower of Arathor. Ho già degli agenti negli Highlands, ma mi hanno chiesto di mandare altro aiuto. Ti interessa?",
  obj = "Trova Skuerto a Refuge Pointe, negli Arathi Highlands.",
  reward = "Allora, t'ha mandato Malin? Non m'importa neanche se Muradin è risorto dai morti e t'ha portato fin qui in groppa a un drago. Ho da fare! Se ti serve qualcosa, parla con Kryten.",
  en_title = "Malin's Request",
  en_obj = "Find Skuerto at Refuge Pointe in the Arathi Highlands.",
}
T[691] = {
  title = "Vale Tanto Oro Quanto Pesa",
  desc = "Archmage Malin ha mandato qui me e Skuerto a raccogliergli dei reagenti. Non sapevo proprio come procurarmeli, ma adesso che ci sei tu direi che il problema è risolto.$B$BMi servono: Witherbark tusks, Witherbark medicine pouches e uno shadow hunter knife.$B$BRiusciresti a trovarmeli? I Witherbark vivono a sud-est di Arathi.",
  obj = "Trova 10 Witherbark Tusks, 4 Witherbark Medicine Pouches e uno Shadow Hunter Knife per Apprentice Kryten a Refuge Pointe.",
  progress = "Allora, $N, finora hai avuto fortuna?$B$B<Kryten annota qualcosa sul diario mentre legge.>$B$BSe le mie ricerche sono giuste, le zanne dovresti poterle prendere da qualunque Witherbark troll. Le sacche medicinali le hanno i Witherbark witch doctors, e il coltello speciale dovrebbero portarlo i più forti fra i Witherbark shadow hunters: lo ricevono quando completano i riti di passaggio. Quali cacciatori dell'ombra lo avranno, non c'è modo di saperlo finché non li affronti in battaglia.",
  reward = "Incredibile! Ora capisco perché Malin ti ha chiesto di unirti a noi — hai fatto davvero un ottimo lavoro!$B$BDi questo passo io e Skuerto saremo di ritorno a Stormwind in men che non si dica.$B$BCredo che il mio compagno nano sia rientrato dalla ricognizione al Boulderfist Hall; quando sei $Gpronto:pronta;, va' a parlargli.$B$BMi è sembrato che abbia avuto un piccolo scontro con gli ogres. Però non dirglielo: è molto suscettibile quando qualcuno critica le sue capacità di esploratore.",
  en_title = "Worth Its Weight in Gold",
  en_obj = "Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe.",
}
T[692] = {
  title = "I Frammenti Perduti",
  desc = "La Scroll of Myzrael... la Scroll of Myzrael?! Non ti conviene! Con la sua magia si può trascinare Myzrael in superficie, e se lo fai, siamo nei guai!$B$BOppure... forse è già troppo tardi. Forse è già libera, e sta solo raccogliendo le forze prima di scatenarsi su di noi. In quel caso la pergamena ti SERVIRÀ!$B$B...peccato che sia distrutta. L'hanno rubata degli elementali infuriati, l'hanno fatta a pezzi e adesso si contendono i frammenti.$B$BMa se riesci a raccoglierli, forse possiamo ripararla...",
  obj = "Porta il Torn Scroll Fragment, il Crumpled Scroll Fragment e il Singed Scroll Fragment a Theldurin the Lost.",
  progress = "Li hai trovati, quei frammenti?!?! Se vuoi intrappolarla di nuovo prima che sia troppo tardi, ti serve la Scroll of Myzrael!",
  reward = "Ah, li hai trovati! Ottimo lavoro, $N! Forse sono l'unica possibilità che abbiamo contro il male di Myzrael!$B$BOra fammi solo trovare il cricchetto da rottami, che vedo se riesco a riattaccare questi frammenti...",
  en_title = "The Lost Fragments",
  en_obj = "Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost.",
}
T[693] = {
  title = "Bacchetta in Pugno",
  desc = "Ehi, $N. Scusami se prima sono stato così sbrigativo... e no, non è una battuta.$B$BHo scoperto dov'è finito il primo oggetto di Trelane: ce l'ha Kor'gresh, al Boulderfist Hall. E da come scagliava raffiche di ghiaccio sui suoi per tenerli in riga, dev'essere vicino a capire come sfruttarne tutti i poteri.$B$BIl Boulderfist Hall sta a sud di qui, e poi a est del Thandol Span. Trova l'ogre e riprenditi quella bacchetta.$B$BIntanto che sei via, a cosa fare con Stromgarde ci penso io.",
  obj = "Trova la Trelane's Wand of Invocation e riportala a Skuerto a Refuge Pointe.",
  progress = "La bacchetta, $N: è quello il nostro obiettivo. Per ora pensa solo a quella.",
  reward = "Magnifico, $N. Un oggetto è sistemato, e dalla mia lista ne mancano ancora altri tre. Sono tutti a Stromgarde.$B$BPrenditi una pausa e rimettiti in forze — la prossima fase del mio piano chiederà un po' più di tempo e di fatica. Torna da me quando avrai mangiato un pasto caldo e ti sarai $Griposato:riposata;.",
  en_title = "Wand over Fist",
  en_obj = "Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe.",
}
T[694] = {
  title = "Le Difese di Trelane",
  desc = "Ti sei $Griposato:riposata; per bene?$B$BAllora, la prossima mossa è questa: la Tower of Arathor, a Stromgarde, è circondata da ogres. Se vuoi avere qualche speranza contro di loro e arrivare $Gvivo:viva; agli oggetti, dovremo attivare le difese della torre. Per farlo ci servono certe gemme a cui gli sciamani Boulderfist si sono affezionati: le hanno portate via dalla torre, ma non le terranno ancora per molto.$B$BProcurati una di 'ste gemme e portala a Kryten — lui conosce l'incantesimo per farle funzionare da chiave.",
  obj = "Trova un'Azure Agate e portala ad Apprentice Kryten a Refuge Pointe.",
  progress = "Eccoti di nuovo, $N. Allora, hai già trovato un'azure agate?",
  reward = "Mi stupisci, $N. Ben fatto, ancora una volta.$B$BDammi un attimo per lanciare sulla gemma l'incantesimo giusto, e sarai $Gpronto:pronta;.",
  en_title = "Trelane's Defenses",
  en_obj = "Find an Azure Agate and bring it to Apprentice Kryten at Refuge Pointe.",
}
T[695] = {
  title = "L'Incantamento di un Apprendista",
  desc = "Ecco qui, $N. Per attivare le difese della torre basta premere la gemma contro uno dei piedistalli vicino alla base. Usala quando sarai $Gpronto:pronta; a entrare e a trovare gli oggetti rimasti di Trelane.$B$BBuona fortuna. Io aspetto il tuo ritorno qui all'accampamento. Ah, prima di partire parla con Skuerto: ti darà gli altri dettagli che ti servono.",
  obj = "Parla con Skuerto.",
  reward = "Bene, bene.$B$BSe non ci sono altri intoppi, che ne dici di cominciare?",
  en_title = "An Apprentice's Enchantment",
  en_obj = "Speak to Skuerto.",
}
T[696] = {
  title = "Attacco alla Torre",
  desc = "Ecco cosa stai cercando: il filatterio di Trelane, la sfera di Trelane e l'agata ardente di Trelane.$B$BDovrebbero essere tutti e tre nei forzieri della torre, e aprirli da $Gsolo:sola; non dovrebbe darti problemi; l'importante è stare $Gattento:attenta; agli ogres.$B$BLe difese della torre non li sistemeranno da sole; le armi dovrai tenerle pronte. Se quegli ogres ti scoprono lì a derubarli, di sicuro te le suoneranno.$B$BSta' $Gattento:attenta;, e buona fortuna.",
  obj = "Trova il Trelane's Phylactery, la Trelane's Orb e la Trelane's Ember Agate, e riportali a Skuerto a Refuge Pointe.",
  progress = "Se ci riesci, Malin sarà più che contento di te, ne sono sicuro.",
  reward = "Per venire qui ad aiutarci, Malin non avrebbe potuto chiedere a una persona più degna, $N. Hai fatto un lavoro grandioso!$B$BSarà contento di vedere che la nostra missione è stata un successo travolgente.",
  en_title = "Attack on the Tower",
  en_obj = "Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.",
}
T[697] = {
  title = "La Richiesta di Malin",
  desc = "Riporta questa lettera a Stormwind e fa' sapere a Malin che io e Kryten torneremo presto a casa. Per l'aiuto che ci hai dato qui ti ricompenserà bene, $N, su questo non ho dubbi.$B$BBuon viaggio.",
  obj = "Porta la Sealed Letter to Archmage Malin in Mage Quarter of Stormwind.",
  progress = "Sì? La tua faccia mi dice vagamente qualcosa. Chiedo scusa, ma ci siamo già conosciuti? Ho così tanto da fare che perdo il filo.",
  reward = "<Archmage Malin apre la lettera e sgrana gli occhi.>$B$BPer la Luce, ce l'hai fatta. Meraviglioso. Trelane sarà felicissimo. Sono sicuro che Kryten e Skuerto sono entusiasti quanto me di saperli sulla via del ritorno per Stormwind.$B$BGrazie, $N. Ti prego, prendi questo: ti sarà d'aiuto nei tuoi viaggi.",
  en_title = "Malin's Request",
  en_obj = "Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind.",
}
T[698] = {
  title = "Carenza di Scorte",
  desc = "Sto cercando di raccogliere delle provviste per il nostro avamposto vicino alla spiaggia, a est — Tok'kar fa quel che può, ma fra i turni di guardia e i pasti da preparare per i suoi soldati, di giorno gli resta poco tempo.$B$BUn po' di carne di sawtooth se la cucinano volentieri, quando possono, ma non ho avuto il tempo di mandargliene un'altra spedizione. Ti dispiacerebbe dargli una mano?$B$BI sawtooth giovani sono meno saporiti di quelli più vecchi, quindi stanne alla larga; lascia che crescano ancora un anno o due.",
  obj = "Porta 8 Unprepared Sawtooth Flanks a Tok'Kar in Swamp of Sorrows.",
  progress = "Lok'tar, $C. Attraversare le paludi è un rischio da non prendere alla leggera. Sei $Gcoraggioso:coraggiosa; a metterti alla prova qui.",
  reward = "Ah! Magnifico. Carne fresca per il fuoco di stanotte. Grazie, $N.$B$BCi hai aiutato a rendere più sopportabili le notti che verranno. Il fuoco arde vivace e avremo la pancia piena.$B$BChe piacevole sorpresa, vederti arrivare con una spedizione: Dar non è l'orc più attraente che si sia mai visto, ma almeno il suo carattere puzza molto meno del suo odore.",
  en_title = "Lack of Surplus",
  en_obj = "Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows.",
}
T[699] = {
  title = "Carenza di Scorte",
  desc = "Con i murlocs che minacciano la costa, siamo di stanza qui per difendere Stonard da qualunque pericolo in arrivo — o per dare l'allarme, se le forze sono troppe. Così di tempo per rilassarci ne resta poco, e un altro aiuto ci farebbe comodo, se puoi.$B$BGli artigli dei morsicatori dentesega, lavorati come si deve, diventano ottime armi. Portamene un po' e farò in modo che tu ne riceva una delle nostre, per ringraziarti della carne fresca e della buona compagnia.",
  obj = "Porta 6 Sawtooth Snapper Claws a Tok'Kar in Swamp of Sorrows.",
  progress = "Buon idromele, un fuoco caldo, un esercito di orc e un arsenale di armi... qui sulla costa non ci serve davvero altro. Non rimpiango il mio incarico a difesa di Stonard, ma un giorno sarebbe bello avere una tana, o almeno una torre.",
  reward = "Sono contento di vederti $Gvivo e vegeto:viva e vegeta;, $N.$B$BQuesti artigli andranno benissimo. Più armi teniamo pronte contro gli attacchi, meglio è per noi.$B$BMi metterò al lavoro sulla tua arma il prima possibile. Non ci vorrà molto: ormai a fabbricarle sono diventato piuttosto abile e veloce.",
  en_title = "Lack of Surplus",
  en_obj = "Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows.",
}
T[700] = {
  title = "Il Tributo di un Re",
  desc = "Ah, che bella pietra che proviene da Lordaeron. Peccato che quella terra sia così allo sfascio.$B$BMa il Memoriale è venuto proprio bene! Credo che il Re ne sarà molto soddisfatto.$B$BOra, per favore, fai sapere a Sua Maestà che il Memoriale è finito, come richiesto.",
  obj = "Fa' rapporto a King Magni Bronzebeard.",
  reward = "Il granito sembra ben poca cosa in confronto alla vita di un valoroso nano. Ma nessun nano durerà in eterno su questo pianeta.$B$BSperiamo soltanto che il memoriale resti a ricordo per chi calcherà la grande Azeroth del futuro. Non dimentichiamo che è per loro che soldati coraggiosi come Sully Balloo hanno dato la vita con tanto valore.",
  en_title = "A King's Tribute",
  en_obj = "Report to King Magni Bronzebeard.",
}
T[701] = {
  title = "L'Astuzia del Raptor",
  desc = "Con qualche altro oggetto potrò creare qualcosa che infonderà in Gor'mul l'astuzia del raptor! Quando la forza del raptor gli scorrerà dentro, Gor'mul conoscerà il nostro nuovo potere e riscoprirà il guerriero che dorme in lui!$B$BPer creare l'oggetto e l'incantesimo mi serviranno dei raptor hearts.",
  obj = "Procurati 12 Raptor Hearts dagli Highland Fleshstalkers per Tor'gan.",
  progress = "È tutto pronto, mi mancano solo i raptor hearts.",
  reward = "Sì, questi vanno benissimo. Ne trasferirò il potere, insieme allo spirito dei raptors, in questo globo, e il globo infonderà in Gor'mul la forza ardente e l'intelligenza del raptor.",
  en_title = "Guile of the Raptor",
  en_obj = "Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan.",
}
T[702] = {
  title = "L'Astuzia del Raptor",
  desc = "Prendi questo globo e usane l'energia per dare a Gor'mul l'essenza del raptor. Di sicuro gli rinvigorirà lo spirito e gli darà un nuovo scopo nella vita. Quando sarà tornato quello di prima, potremo spiegargli come stanno oggi le cose nell'Orda, e nelle nostre battaglie senza fine avremo l'aiuto di un grande guerriero.",
  obj = "Consegna il Tor'gan's Orb a Gor'mul.",
  progress = "Di nuovo $Gtornato:tornata; sei? In verità, adesso non c'è nulla che desidererei di più di un altro po' di pietà di Tor'gan.$B$BCosa mi porti stavolta? Un pezzo di spago dai colori vivaci, forse? O una corda per porre fine a questa mia sofferenza...",
  reward = "Almeno stavolta mi porti qualcosa di interessante. Ne emana uno strano potere...",
  en_title = "Guile of the Raptor",
  en_obj = "Give Tor'gan's Orb to Gor'mul.",
}
T[703] = {
  title = "Barbecued Buzzard Wings",
  desc = "Oh sì, le mie barbecued buzzard wings sono tra i piatti più amati! La salsa è ricca, la carne ha un sapore deciso. E il profumo farà correre gli affamati da miglia di distanza!$B$BPer prepararne un bel po' ho tutto l'occorrente. Tutto... tranne le buzzard wings!$B$BSe ne vuoi anche tu, procurami le buzzard wings. Portamene abbastanza e magari ti do pure la ricetta!",
  obj = "Porta 4 Buzzard Wings a Rigglefuzz.",
  progress = "Ciao, $N. Le ali me le hai portate?",
  reward = "Ah, queste ali le metto subito a cuocere. Già mi pare di sentirne il sapore!$B$BEd ecco la ricetta, se vuoi prepararle da $Gsolo:sola;!",
  en_title = "Barbecued Buzzard Wings",
  en_obj = "Bring 4 Buzzard Wings to Rigglefuzz.",
}
T[704] = {
  title = "La Sorte di Agmond",
  desc = "L'ultimo rapporto che mi ha mandato Agmond è preoccupante, e adesso che è morto ancora di più! Diceva che i suoi scavatori avevano portato alla luce delle \"urne antiche\" al sito di scavo fuori da Uldaman. Ho paura che siano state quelle urne ad aizzare i troggs, proprio come gli idoli che ho trovato qui.$B$BQuelle urne mi servono per i nostri studi. Va' al sito di Uldaman, raccoglile e riportamele.",
  obj = "Porta 4 Carved Stone Urns a Prospector Ironband a Loch Modan.",
  progress = "Allora, $N, hai trovato quelle urne? Dobbiamo capire che legame hanno con i troggs!",
  reward = "Ben fatto! Con un po' di fortuna e d'impegno scopriremo qualunque legame ci sia fra i troggs e questi antichi manufatti.$B$BHai compiuto una grande impresa per i Prospectors, $N. Non dimenticheremo i tuoi sforzi. E nemmeno Agmond.",
  en_title = "Agmond's Fate",
  en_obj = "Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan.",
}
T[705] = {
  title = "A Caccia di Perle",
  desc = "Le Badlands sono un posto crudele, pieno di predatori feroci e di mangiacarogne aggressivi. Terrificante, soprattutto per un goblin alto un metro e un barattolo. Per sopravvivere devo farmi furbo!$B$BConosco la ricetta delle Flash Bombs. Le uso per spaventare le bestiacce selvatiche. Ma sto finendo uno degli ingredienti: la polvere di Blue Pearl macinata. Procuramene un po' e ti ripagherò della fatica.$B$BHeh, e spero che i tuoi stivali siano decenti. Le Blue Pearls che mi servono si trovano nei molluschi della Vile Reef.$B$BGià, la Vile Reef, a Stranglethorn!",
  obj = "Porta 9 Blue Pearls a Rigglefuzz, in Badlands.",
  progress = "Hai preso le mie perle? Sono quasi a corto di Flash Bombs!",
  reward = "Andranno benissimo! Devo solo ridurle in polvere... e poi mischiarle con un po' di questo e un po' di quello.$B$BAttenti, mangiacarogne! Preparatevi a restare accecati!",
  en_title = "Pearl Diving",
  en_obj = "Bring 9 Blue Pearls to Rigglefuzz in the Badlands.",
}
T[706] = {
  title = "Fiery Blaze Enchantments",
  desc = "Quand'ero apprendista di Feranor Steeltoe ho imparato la sua tecnica speciale per infondere incantamenti di fuoco nelle armi. Le ultime notizie che ho avuto di lui dicevano che lavorava in una fucina con una compagnia di caccia, su a Lordaeron.$B$BSul procedimento non posso dirti troppo, ma una cosa te la dico: serve il sangue del cuore ancora pulsante di un raro cucciolo di black drake. Intanto che aspetto notizie da Ironforge non ho granché da fare. Portami un cuore dei cuccioli della Lethlor Ravine e ti faccio vedere la mia abilità!",
  obj = "Procurati un Black Drake's Heart per Sigrun Ironhew.",
  progress = "Come va con la caccia, $C?",
  reward = "Ah sì, questo andrà benissimo. Farà colpire le tue armi con un calore rovente!",
  en_title = "Fiery Blaze Enchantments",
  en_obj = "Acquire a Black Drake's Heart for Sigrun Ironhew.",
}
T[707] = {
  title = "Ironband ti Vuole!",
  desc = "$N. Mi sono arrivati dei rapporti da Prospector Ironband, dal suo sito di scavo a Loch Modan — gli serve qualcuno che si faccia un po' di strada per un altro dei nostri scavi.$B$BDi più non so, ma se ti va di sgranchirti le gambe, va' a parlare con Ironband.",
  obj = "Parla con Prospector Ironband agli Ironband's Excavation Site a Loch Modan.",
  reward = "Ti manda Stormpike, eh? Bene.$B$BHo un compito importante da affidarti...",
  en_title = "Ironband Wants You!",
  en_obj = "Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan.",
}
T[708] = {
  title = "La Scatola Nera",
  desc = "La superficie di questa scatola nera di metallo è tutta butterata, come se fosse stata immersa nell'acido — dev'essere rimasta a lungo nello stomaco del condor gigante.$B$BGirandola, scopri un simbolo impresso sul fondo, e sotto una scritta:$B$B\"Motore #19 — Ironforge Siege Brigade\"",
  obj = "Porta la Corroded Black Box a Hall of Arms, a Ironforge.",
  en_title = "The Black Box",
  en_obj = "Take the Corroded Black Box to the Hall of Arms in Ironforge.",
}
T[709] = {
  title = "Soluzione alla Rovina",
  desc = "Oh, cielo! Oh, cielo! Sta arrivando la rovina. Dammi retta! La rovina!$B$BNo, non posso parlarne... non posso dire i loro nomi, o potrebbero sentirmi! Ma se scopriamo, sì, se scopriamo qualcosa di più su di loro... forse riusciremo a capire come sventare i loro piani!$B$BForse.$B$BVa' a Uldaman. No! L'ho detto! Devi trovare... trovare la tavoletta di... Ryun'eh. Sì, trovala! E non costringermi a dire di nuovo quel nome!$B$BSta in fondo a quel posto, dentro un'antica cassa. È lì che si nasconde... in una cassa costruita prima di qualsiasi opera dei nani.",
  obj = "Porta la Tablet of Ryun'eh a Theldurin the Lost.",
  progress = "L'hai trovata, la tavoletta? Deve nascondere dei segreti! Segreti che possono salvarci!",
  reward = "Oh, la fortuna ci assiste! Grazie! Forse possiamo ancora salvarci!",
  en_title = "Solution to Doom",
  en_obj = "Bring the Tablet of Ryun'eh to Theldurin the Lost.",
}
T[710] = {
  title = "Studio degli Elementi: Roccia",
  desc = "Qui nelle Badlands mi sono fermato a lavorare al mio ultimo progetto: i ceppi del vincolo elementale.$B$BQuando saranno finiti, i maghi potranno evocare elementali ancora più potenti, da usare per compiti ancora più grandi. Per cominciare mi servono degli small stone shards, su cui provare alcuni dei miei nuovi incantesimi offensivi e qualche aggeggio che ho messo insieme.$B$BI frammenti si prendono facilmente dai lesser rock elementals, qui a ovest. Me ne porteresti un po'?",
  obj = "Trova 10 Small Stone Shards e portali a Lotwil Veriatus nelle Badlands.",
  progress = "Questa zona è perfetta per — Mi terresti fermi questi un momento? Sì, così, lungo la normale del vettore. Dunque, cosa stavo... Giusto. Perfetta per provare il mio ultimo progetto. Le materie prime, lo spazio aperto... cos'altro potrebbe chiedere un cultore delle arti intelligente e illuminato?",
  reward = "Questi vanno benissimo, $N. Grazie. Mmm, c'è un po' più di sabbia di quanto pensassi. Dovrò correggere il coefficiente di attrito. No, aspetta; con il frost oil dovrebbe essere comunque trascurabile.$B$B<Lotwil borbotta fra sé, posa un pugno nel palmo dell'altra mano e li fissa come affascinato.>",
  en_title = "Study of the Elements: Rock",
  en_obj = "Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands.",
}
T[711] = {
  title = "Studio degli Elementi: Roccia",
  desc = "$N, hai già dimostrato di essere più capace di tutti i miei apprendisti messi insieme.$B$BPer le prossime parti che mi servono ci vuole un po' più di forza. Se stai abbastanza $Gattento:attenta;, i Large stone slabs si trovano sui rock elementals: hanno corpi più grossi e robusti, quindi è più facile che contengano pezzi grandi abbastanza per i miei test. Stanno più a ovest di qui o a sud-est, lungo i bordi delle montagne.$B$BFai con calma: mi ci vorrà un po' per provare questi pezzi più piccoli che mi hai portato.",
  obj = "Porta 3 Large Stone Slabs a Lotwil Veriatus nelle Badlands.",
  progress = "Sono molto soddisfatto, $N. Sui pezzi più piccoli i miei incantesimi hanno funzionato proprio come avevo previsto. Se l'esperimento riuscirà come mi aspetto, gli elementali che potrò controllare faranno sfigurare tutto quello che è stato evocato finora.",
  reward = "$N, semplicemente incredibile! Pensavo che per portarmi tutto questo ci volesse mezza dozzina di tauren.",
  en_title = "Study of the Elements: Rock",
  en_obj = "Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands.",
}
T[712] = {
  title = "Studio degli Elementi: Roccia",
  desc = "$N, mi serve ancora una parte dagli elementali qui nelle Badlands: i bracers of rock binding dei greater rock elementals. Secondo i miei calcoli, quei bracciali dovrebbero bastare a misurare la forza dei miei ceppi.$B$BCercando i greater rock elementals con la divinazione, ne ho visto un gruppo a sud-ovest di qui, vicino ad alcuni ogres, se ricordo bene.$B$BPortami 5 dei loro bracciali, così ne tengo qualcuno di scorta: Servo ha il vizio di perdermi i reagenti e le ricerche.",
  obj = "Porta 5 Bracers of Rock Binding a Lotwil Veriatus nelle Badlands.",
  progress = "I lastroni di pietra che hai trovato erano ideali, $N. Quando avremo finito qui, Lucien riporterà quelli in più a Kharanos: dopotutto, potrebbero tornare utili.$B$BPer esempio, sarebbero una bella base per un rifugio piccolo e pratico, quando comincerò a studiare un approccio multidisciplinare agli esplosivi ad alto potenziale...$B$B<La voce di Lotwil si spegne mentre torna al suo esperimento.>",
  reward = "$N, hai mai pensato di diventare $Gun assistente:un'assistente; di ricerca? No? Non so come farò qui senza le tue capacità. Intelligenza, curiosità e forza — tutte riunite in una persona sola.",
  en_title = "Study of the Elements: Rock",
  en_obj = "Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.",
}
T[713] = {
  title = "Che Prevalgano le Teste Fredde",
  desc = "Lascia che ti dica una cosa sul Frost Oil: niente come lui impedisce a un motore o a degli ingranaggi di surriscaldarsi.$B$BRaffredda in modo straordinario, e come lubrificante non ce n'è un altro che duri tanto. E non finisce qui: aiuta pure a mantenere gli incantamenti sugli oggetti magici.$B$BMe ne serve una fiala: così posso aumentare la capacità magica dei miei ceppi e renderli abbastanza potenti da impedire al nostro amico evocato di ucciderci tutti.$B$BPuò insegnarti a prepararlo Bro'kin, un goblin mio amico. Lo trovi ad Alterac.",
  obj = "Trova del Frost Oil e portalo a Lotwil Veriatus in Badlands.",
  progress = "Hai trovato l'olio che mi serve? Se riuscissi a procurarmene un po', mi daresti un grande aiuto.",
  reward = "Stupendo! Questo dovrebbe essere il refrigerante perfetto per i miei nuovi bracciali. Se gli incantamenti non dureranno un secolo, lascerò tutti i miei averi a Servo.$B$BQuando avrò finito, tutti i maghi dell'Assemblea resteranno a bocca aperta, $N. Aspetta e vedrai.",
  en_title = "Coolant Heads Prevail",
  en_obj = "Find Frost Oil and bring it to Lotwil Veriatus in Badlands.",
}
T[714] = {
  title = "Giro... Cosa?",
  desc = "$N, il tuo lavoro è andato ben oltre ogni aspettativa.$B$B<Si vede bene che il lavoro distrae Lotwil.>$B$BSe mai ci incontreremo a Kharanos, passa pure a chiedermi un posto.$B$BOps! Presto, prendi il... sì, quello. Grazie.$B$BAdesso mi manca solo un'altra cosa, un pezzo piccolo ma, temo, indispensabile: un gyrochronatom.$B$BSe potessi andare a prendermene uno e portarmelo, dovrei essere pronto per completare l'opera.",
  obj = "Porta un Gyrochronatom a Lotwil Veriatus in Badlands.",
  progress = "Sì, sì, sì. Un momento solo.$B$B<Lotwil continua ad armeggiare con una specie di marchingegno.>",
  reward = "AH!$B$B<Lotwil ti prende di mano il gyrochronatom.>$B$BPerfetto... quasi finito. No, davvero. Adesso ho QUASI finito. Questo progetto è la mia priorità assoluta... per il momento. Lascia che lo metta al suo posto, e vedrai con i tuoi occhi cosa mi hai aiutato a creare. Mi ci vorrà solo qualche altro minuto... forse... magari di più. Beh, forse molto di più. Vedremo...",
  en_title = "Gyro... What?",
  en_obj = "Bring a Gyrochronatom to Lotwil Veriatus in the Badlands.",
}
T[715] = {
  title = "Pietra Liquida",
  desc = "Ho idea, $N, che gli oggetti che hai procurato per Lotwil saranno l'ultimo dei nostri problemi. In compenso hai dimostrato di essere più che $Gesperto:esperta; nelle scienze che Lotwil considera sacre, quindi che ne dici di darmi una mano?$B$BMi servono un'invisibility potion e un'healing potion: se lui ci riesce, potrebbero tornare utili molto presto.$B$BIn cambio ti darò questa ricetta. È una pozione che sto mettendo a punto mentre imparo da Lotwil, e si basa su alcune delle ricerche che lui sta facendo qui nelle Badlands.",
  obj = "Porta un'Healing Potion e una Lesser Invisibility Potion a Lucien Tosselwrench nelle Badlands.",
  progress = "Gli manca sempre meno per finire. Tu a che punto sei?",
  reward = "SÌ!$B$BCioè, grazie, $N. Queste torneranno utili per attraversare le Badlands.",
  en_title = "Liquid Stone",
  en_obj = "Bring a Healing Potion and a Lesser Invisibility Potion to Lucien Tosselwrench in the Badlands.",
}
T[716] = {
  title = "La Pietra È Meglio della Stoffa",
  desc = "Lo so, $N, quanto sa essere tirchio Lotwil, quindi lascia che ti ripaghi io di tutto il disturbo facendoti qualcosa. Magari ti aiuterà anche a proteggerti dall'atrocità in arrivo: la nuova invenzione di Lotwil.$B$BHo lavorato tutte le pietre in più che hai raccolto per lui, e ne posso ricavare dei bei bracciali che potrebbero farti comodo. Incantati, naturalmente.$B$BMi basta che un fabbro mi forgi dei patterned bronze bracers, così posso finire quelli che ti sto preparando.",
  obj = "Porta dei Patterned Bronze Bracers a Lucien Tosselwrench nelle Badlands.",
  progress = "Fossi in te non aspetterei troppo a procurarmi quel bracciale, $N.$B$BChissà cosa succederà adesso?",
  reward = "Ecco qua, $N. Provali.",
  en_title = "Stone Is Better than Cloth",
  en_obj = "Bring some Patterned Bronze Bracers to Lucien Tosselwrench in the Badlands.",
}
T[717] = {
  title = "Tremori della Terra",
  desc = "Ormai è chiaro: non possiamo essere certi che Blacklash e Hematus restino prigionieri a Lethlor. Dei draghi neri vi si sono stabiliti e gli ogres sono riusciti a rubare il Simbolo: vuol dire che bisognerà prendere misure più drastiche.$B$BTre pietre runiche reggono la prigione dei draghi, e solo con il Sign of the Earth si possono prendere. Con quelle pietre, poi, si potrà spezzare il sigillo che li tiene rinchiusi.$B$B$N... fa' in modo che i loro sogni siano eterni.",
  obj = "Usa il Sign of the Earth per attivare i Pilastri di Ametista, di Opale e di Diamante e ottenere le Pietre Runiche.$B$BMetti le pietre runiche nel Seal of the Earth per liberare Blacklash e Hematus.$B$BUccidili e riporta i Blacklash's Bindings, le Chains of Hematus e il Sign of the Earth a Garek.",
  progress = "Per tanto tempo la prigione dei draghi è rimasta in piedi grazie a magie e poteri potenti, ma non possiamo correre nemmeno il minimo rischio che Blacklash e Hematus vengano liberati.",
  reward = "Il Kirin Tor non dovrà più preoccuparsi dei prigionieri di Lethlor. Tornerò dal mio maestro a riferire del successo, e Krasus ne sarà senza dubbio soddisfatto.",
  en_title = "Tremors of the Earth",
  en_obj = "Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.$B$BPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.$B$BSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek.",
}
T[718] = {
  title = "Miraggi",
  desc = "Quando siamo scappati di corsa dal sito di scavo di Uldaman, abbiamo dovuto lasciare per strada molti carri e casse di provviste. Gli ogres della zona, quelli di Camp Kosh, si sono buttati sull'attrezzatura che avevamo abbandonato come avvoltoi su un cadavere in putrefazione. E non è che profumino molto meglio. Dei cadaveri, intendo.$B$BComunque, si sono presi il carro con tutte le nostre armi e il resto... e così — be', è un po' imbarazzante — non siamo riusciti a procurarci niente da mangiare.$B$BSiamo un po' nei pasticci, te la senti di darci una mano?",
  obj = "Recupera la Supply Crate per Sigrun Ironhew.",
  progress = "Te lo dico io, $Gamico mio:amica mia;, il deserto è un brutto posto per restare a pancia vuota.$B$BEhi... cos'è quello laggiù...",
  reward = "Grazie mille, $N. Mentre non c'eri, io... ehm... ho mandato giù una boccata di sabbia. Era...$B$BBe', lasciamo perdere, stasera usciamo a procurarci del cibo. Mangeremo come re!",
  en_title = "Mirages",
  en_obj = "Retrieve the Supply Crate for Sigrun Ironhew.",
}
T[719] = {
  title = "Un Nano e i Suoi Attrezzi",
  desc = "Ehi, $N. Da 'ste parti sta' $Gattento:attenta;. Ci son nani Dark Iron ovunque — a vederli, sembravano del clan Shadowforge.$B$BHanno appena attaccato il sito di scavo dove lavoravo — hanno ammazzato quasi tutti, anche il mio capo Hammertoe. Io me la son cavata per un pelo.$B$BIl sito è appena a nord di qui. Sto cercando il modo di recuperare un po' delle nostre provviste, e più di tutto il mio piccone fortunato.$B$BTe la senti di darmi una mano? Il mio piccone ce l'ha per forza uno di quei dannati Dark Iron! Può essere uno qualsiasi di loro.",
  obj = "Trova il Ryedol's Lucky Pick e riportalo a Prospector Ryedol, a sud di Hammertoe's Dig Site.",
  progress = "Non so cosa cercassero gli Shadowforge, ma di sicuro non erano lì per caso.",
  reward = "Sei $Gil mio salvatore:la mia salvatrice;, $C. Son contento che qualcuno abbia dato una lezione a quegli Shadowforge. Grazie dell'aiuto.",
  en_title = "A Dwarf and His Tools",
  en_obj = "Find Ryedol's Lucky Pick and return it to Prospector Ryedol south of Hammertoe's Dig Site.",
}
T[720] = {
  title = "Un Segno di Speranza",
  desc = "<Sulla mappa qualcuno ha scarabocchiato qualche riga col gesso.>$B$B\"Ryedol,$BMi portano a Uldaman. Manda aiuto.$B-Hammertoe\"",
  obj = "Trova Prospector Ryedol e fagli sapere che Hammertoe Grez è vivo.",
  reward = "Hammertoe è vivo?! Ma è incredibile, $N!",
  en_title = "A Sign of Hope",
  en_obj = "Find Prospector Ryedol and let him know Hammertoe Grez is alive.",
}
T[721] = {
  title = "Un Segno di Speranza",
  desc = "$N, riesci a trovarlo? A trovare Hammertoe a Uldaman?$B$BSe quei luridi Shadowforge lo tengono in ostaggio per farsi dire quello che sa degli scavi dei titani, tutta Ironforge rischia di finire in guai seri.$B$BQuei Dark Irons cercano da molto tempo magie per creare golem più potenti. Lo faceva anche Hammertoe, è ovvio, ma solo per fermarli.$B$BProbabilmente lo tengono in vita finché non scoprono cosa sa. Se vuoi salvarlo devi sbrigarti!",
  obj = "Trova Hammertoe Grez a Uldaman.",
  reward = "Sì? Mi spiace... <tosse> Sono così debole. Ti avvicini un po', $C?$B$BTi manda Ryedol? Sia lodato Muradin, quel ragazzo non è duro di comprendonio quanto credevo. <tosse>",
  en_title = "A Sign of Hope",
  en_obj = "Find Hammertoe Grez in Uldaman.",
}
T[722] = {
  title = "L'Amuleto dei Segreti",
  desc = "Sei $Gcoraggioso:coraggiosa;... <tosse>... a venire fino a Uldaman per me, $C.$B$BSe sei qui per aiutare davvero... il vecchio Hammertoe, allora... <tosse>... devi trovare... il mio amuleto.$B$BCe l'ha Deepshadow... Magregan Deepshadow. Sta qui intorno... nelle rovine, di sicuro. Quell'amuleto li porterà... <tosse>... dritti ai rotoli, se nessuno lo ferma. Ora tocca a te, $N. Ti prego... recupera quell'amuleto.$B$BCon i rotoli i Dark Irons riusciranno di sicuro a creare golem ancora più potenti. Lo so e basta. Me lo sento nelle ossa.",
  obj = "Trova l'Hammertoe's Amulet e riportaglielo a Uldaman.",
  progress = "Il clan Shadowforge... <tosse> è pericoloso. Sta' $Gattento:attenta;. <tosse> L'amuleto, devi trovarlo.",
  reward = "Ah! <tosse tosse>$B$BSapevo che il mio amuleto l'avresti trovato, $N.$B$B<respiro affannoso> Hai fatto un ottimo lavoro, $N. <tosse>",
  en_title = "Amulet of Secrets",
  en_obj = "Find Hammertoe's Amulet and return it to him in Uldaman.",
}
T[723] = {
  title = "Prospettiva di Fede",
  desc = "<Hammertoe si preme le ferite e si concede un attimo per ricomporsi, poi riprende a parlare.>$B$BTrova Ryedol, $N. Portagli il mio amuleto. <tosse tosse> Lui... <tosse> saprà cosa fare. Sa che cercavo le origini del nostro popolo, e lui... <tosse>... sa che dovevo anche fermare il clan Shadowforge. I rotoli non devono trovarli... <tosse>",
  obj = "Porta l'Hammertoe's Amulet a Prospector Ryedol nelle Badlands.",
  progress = "Direi che è una brutta giornata, ma siamo nelle Badlands: qui sono brutte tutte.",
  reward = "L'amuleto di Hammertoe? Credo di essere stato più su di morale quando lo pensavo morto. Esserne certo fa solo più male. Questo amuleto era il lavoro di tutta la sua vita. Non posso lasciare che sia morto invano.",
  en_title = "Prospect of Faith",
  en_obj = "Take Hammertoe's Amulet to Prospector Ryedol in the Badlands.",
}
T[724] = {
  title = "Prospettiva di Fede",
  desc = "Va bene, va bene... chi può sapere cosa fare?$B$BHistorian Karnik! Ma certo!$B$BSta a Ironforge. Lui potrà aiutarti. Lui e Hammertoe cercavano insieme i manufatti perduti di Uldaman.$B$BImmagino che gli Shadowforge abbiano capito che quei due ne sapevano più di quanto dessero a vedere.$B$BRacconta a Karnik cos'è successo a Hammertoe e dagli l'amuleto — ti dirà lui cosa fare dopo.",
  obj = "Porta l'Hammertoe's Amulet a Historian Karnik a Ironforge.",
  progress = "Ah, sì. $GUn altro viaggiatore:Un'altra viaggiatrice; che viene a cercare qualcosa dai nani.$B$B$GSignore:Signora;, mi dispiace davvero, ma adesso non ho tempo per le domande inutili.",
  reward = "Oh! Be', allora è tutta un'altra faccenda. Immagino che tu non ti renda ancora conto di quanto sia grave, vero?$B$BLa fine di Hammertoe mi addolora profondamente, ma se ti ha mandato qui col suo amuleto, vuol dire che aveva capito cosa c'è in gioco.$B$BPer piangerlo dovremo trovare il tempo più tardi.$B$BLascia che ti mostri uno dei motivi per cui questo amuleto è tanto prezioso.",
  en_title = "Prospect of Faith",
  en_obj = "Take Hammertoe's Amulet to Historian Karnik in Ironforge.",
}
T[725] = {
  title = "Un Avviso di Minaccia",
  desc = "$N, corri a cercare Advisor Belgrum, più in fretta che puoi: raccontagli quello che hai visto e chiedigli come vuole che ci muoviamo. Al resto ci penserà questo biglietto.$B$BIo intanto parlerò con lo spirito di Hammertoe. Magari sa qualcosa che ci aiuti a fermare quello che stanno combinando quei cretini del clan Shadowforge nelle Badlands. Non ci resta che pregare.",
  obj = "Trova Advisor Belgrum e consegnagli il biglietto.",
  progress = "Mh? Sì, $C.",
  reward = "Ah, notizie da Historian Karnik. Eccellente.$B$BPer le sue faccende il tempo lo trovo sempre.$B$B<Advisor Belgrum apre il biglietto e comincia a leggere.>",
  en_title = "Passing Word of a Threat",
  en_obj = "Find Advisor Belgrum and give him his note.",
}
T[726] = {
  title = "Un Avviso di Minaccia",
  desc = "<Advisor Belgrum legge il biglietto fino in fondo, e per un attimo spalanca gli occhi.>$B$BAccidenti, pessime nuove.$B$B$N, ti prego, torna da Historian Karnik e digli che, per autorità del re, deve servirsi subito di queste informazioni e agire con decisione: le attività del clan Shadowforge nelle Badlands vanno fermate.",
  obj = "Parla con Historian Karnik.",
  reward = "Tratti questa faccenda con l'urgenza che mi aspetterei dal re in persona, $N.$B$BBene, allora. So io cosa farà cadere il clan Shadowforge.$B$BPer rallentare la loro presenza a Uldaman possiamo colpirli dove hanno la base operativa: l'Angor Fortress.",
  en_title = "Passing Word of a Threat",
  en_obj = "Speak to Historian Karnik.",
}
T[727] = {
  title = "A Ironforge per il Yagyin's Digest",
  desc = "La Tavoletta dice molto. Ma non basta! Nemmeno lontanamente!$B$BC'è un libro, un compendio che Yagyin scrisse in tempi antichi. La... gente da cui sono scappato... lo conserva in molti luoghi, e i più dotti fra loro lo studiano. Dentro c'è un sapere immenso. Un sapere che può proteggerci!$B$BVai da Gerrig Bonegrip. Lo trovi in una bottega a Ironforge, nella Forlorn Cavern. Mostragli questo sigillo e ti prenderà per $Guno:una; di loro. Chiedigli il Yagyin's Digest... e portamelo!",
  obj = "Consegna il Sigil of the Hammer a Gerrig Bonegrip nella Forlorn Cavern a Ironforge.",
  progress = "Salve. $GBenvenuto:Benvenuta; nella mia bottega, ma $Gattento:attenta; a cosa tocchi.$B$BLa conoscenza può uccidere.",
  reward = "Oh. Salute a te, $Gfratello:sorella;.$B$BE sia lode a chi dimora nel profondo.",
  en_title = "To Ironforge for Yagyin's Digest",
  en_obj = "Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge.",
}
T[728] = {
  title = "A Undercity per il Yagyin's Digest",
  desc = "La tavoletta dice molto. Ma non basta! Nemmeno lontanamente!$B$BC'è un libro, un compendio che Yagyin scrisse in tempi antichi. La... gente da cui sono scappato... lo conserva in molti luoghi, e i più dotti fra loro lo studiano. Dentro c'è un sapere immenso. Un sapere che può proteggerci!$B$BVai da Keeper Bel'dugur a Undercity of Lordaeron. Mostragli questo sigillo e ti prenderà per $Guno:una; di loro. Chiedigli il Compendio di Yagyin... e portamelo!",
  obj = "Porta il Sigil of the Hammer a Keeper Bel'dugur a Undercity.",
  progress = "Ah, vedo che abbiamo $Gun:una; $C $Gvolenteroso:volenterosa;. Sei qui per imparare dalla mia collezione? Bene!$B$BMa ti avverto: se la conoscenza dà potere ai forti... i deboli li farà impazzire.",
  reward = "Sii $Gdiscreto:discreta; con i tuoi segni, $C. C'è chi non crede nella rettitudine del nostro giuramento.$B$BE c'è chi, se sapesse di noi, vorrebbe vederci fallire.$B$BDobbiamo essere sempre cauti. E vigili. E pazienti.",
  en_title = "To the Undercity for Yagyin's Digest",
  en_obj = "Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity.",
}
T[732] = {
  title = "Tremori della Terra",
  desc = "Ho sentito da Sigrun che gli sei $Gstato:stata; di grande aiuto: forse potrei contare su di te anch'io. Il mio maestro, Krasus of the Kirin Tor, mi ha mandato qui a mettere fine ai guai che covano nella Lethlor Ravine.$B$BNon posso rivelarti in cosa consiste di preciso il mio incarico né quali compiti devo svolgere, ma stai pur $Gcerto:certa; che è di vitale importanza.$B$BUna banda di ogres vagabondi, che ogni tanto si fa vedere vicino a Camp Boff, ha rubato un oggetto chiamato Sign of the Earth, e io devo averlo. Portamelo e ti dirò di più.",
  obj = "Recupera il Sign of the Earth per Garek.",
  progress = "La banda di ogres è nomade e si sposta da un accampamento all'altro nelle Badlands; con il calore che sale dalla terra secca e i venti che turbinano, seguirne le tracce sarà difficile. Ho sentito che ogni tanto passano da Camp Boff: se ti sei $Gperso:persa;, potresti cercare lì.",
  reward = "Liete novelle porti, recando il Simbolo, $N. Il Sign of the Earth l'hanno creato i nani Dark Iron dell'Angor Fortress per imprigionare due degli spietati luogotenenti di Deathwing: i gemelli Blacklash e Hematus.",
  en_title = "Tremors of the Earth",
  en_obj = "Retrieve the Sign of the Earth for Garek.",
}
T[733] = {
  title = "Arrangiarsi",
  desc = "Se non riesco a racimolare un po' di materiale per tirar su delle difese e tutto quello che ci serve, qui sarà dura tirare avanti. Ho notato che gli ogres della zona, a quanto pare, si portano dietro più di uno scrap metal. Forse le storie sulle siege engines nelle Badlands non erano poi tanto lontane dal vero...$B$BComunque, il Prospettore è in pensiero per lo stato del nostro piccolo accampamento, quindi, se posso, vorrei mettermi presto al lavoro.$B$BGli ogre hanno l'accampamento principale alla Dustbelch Grotto, a una bella camminata a ovest da qui.",
  obj = "Prendi 7 pezzi di Scrap Metal per Sigrun.",
  progress = "Be', mi sono arrangiato come potevo, ma... non è granché. Hai trovato altri rifornimenti?",
  reward = "È un inizio, $N, e ci dovrà bastare finché non arrivano notizie da Ironforge o dall'Explorers' League.$B$BOra, se solo trovassi un po' di sale da qualche parte per il barile di tempra...",
  en_title = "Scrounging",
  en_obj = "Get 7 pieces of Scrap Metal for Sigrun.",
}
T[734] = {
  title = "Questa Sarà Dura",
  desc = "Magnifico, magnifico.$B$B<Lotwil alza un attimo lo sguardo su di te, poi torna alle catene.>$B$BVa' a parlare con Lucien, $N: mi serve un cog #5. Me lo porti, d'accordo?",
  obj = "Parla con Lucien Tosselwrench in Badlands.",
  reward = "Cog #5, eh? Già, non promette niente di buono.",
  en_title = "This Is Going to Be Hard",
  en_obj = "Speak to Lucien Tosselwrench in the Badlands.",
}
T[735] = {
  title = "La Stella, la Mano e il Cuore",
  desc = "Il Yagyin's Digest, eh? Stai fondando un nuovo capitolo del nostro ordine da qualche parte? Non importa, non tocca a me chiederlo.$B$BTi darò una mano, visto che ne ho una copia in più. Ci si deve aiutare a vicenda, no? È così che prosperiamo.$B$BMi servono tre oggetti di potere. Portameli e il compendio è tuo.$B$BI loro nomi non li dirò ad alta voce: potrebbero esserci orecchie in ascolto. Ma ecco, te li scrivo.",
  obj = "Porta gli oggetti elencati nel Bonegrip's Note a Gerrig Bonegrip a Ironforge.",
  progress = "Hai le reliquie che ti ho chiesto?",
  reward = "Sei $Gpieno:piena; di risorse, $C. Se tocca davvero a te fondare un nuovo capitolo del nostro ordine, credo che saprai guidarlo bene.",
  en_title = "The Star, the Hand and the Heart",
  en_obj = "Return the items on the Bonegrip's Note to Gerrig Bonegrip in Ironforge.",
}
T[736] = {
  title = "La Stella, la Mano e il Cuore",
  desc = "Ti serve il Yagyin's Digest? Vuoi radunare un altro gregge, dunque? Ma certo... e certo che ti aiuterò, $Gfratello:sorella;.$B$BMa anche tu devi aiutare me.$B$BMi servono tre oggetti di potere. Portameli e il compendio sarà tuo.$B$BI loro nomi non posso pronunciarli, ma te li scriverò.$B$BProcurami gli oggetti di questa lista. Se ci riesci, sei davvero $Gdegno:degna; di aprire un tuo capitolo del nostro ordine.",
  obj = "Porta gli oggetti elencati nel Bel'dugur's Note a Keeper Bel'dugur a Undercity.",
  progress = "A che punto è la tua missione, $C?",
  reward = "Sono colpito! Per mettere le mani su queste reliquie devi avere grande abilità, o grande fortuna. Comunque sia, sei $Gprezioso:preziosa; per noi.",
  en_title = "The Star, the Hand and the Heart",
  en_obj = "Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity.",
}
T[737] = {
  title = "Conoscenza Proibita",
  desc = "Il compendio è qui per te, $N. Inutile dirti di averne gran cura. E di tenerlo lontano da mani ostili.$B$BQuesto libro racchiude molte verità...$B$B...E la verità può bruciare.",
  obj = "Porta il Yagyin's Digest a Theldurin.",
  progress = "Oh! Sei $Gstato:stata; via tanto tempo. Ce l'hai, il compendio?",
  reward = "Ce l'hai! Oh, c'è un barlume di speranza!$B$BCon i tuoi sforzi potresti ancora salvarci, $N. Dovrebbero farti un monumento! Dovrebbero costruirti un santuario! Che il tuo nome sia lodato finché i tuoi nipoti non avranno nipoti!$B$BA meno che... ESSI non vengano liberati e salgano in superficie. In quel caso, dei figli puoi scordarti.$B$BSe ESSI vengono liberati, saremo tutti cibo per i vermi.",
  en_title = "Forbidden Knowledge",
  en_obj = "Bring Yagyin's Digest to Theldurin.",
}
T[738] = {
  title = "Trova Agmond",
  desc = "Prospector Agmond era il responsabile dei nostri siti di scavo nelle Badlands, a sud-ovest. Dico \"era\" perché... be', sono settimane che non ho sue notizie. Devi trovare Agmond: mi serve il suo rapporto.$B$BStando alle ultime notizie, Agmond era al sito di scavo più a sud delle Badlands — un piccolo cantiere oltre l'Angor Fortress. Io comincerei a cercarlo da lì.",
  obj = "Trova Agmond.",
  reward = "Questo scheletro dev'essere ciò che resta dello sfortunato Agmond. Il corpo è spezzato e malridotto, le ossa spolpate.",
  en_title = "Find Agmond",
  en_obj = "Find Agmond.",
}
T[739] = {
  title = "Murdaloc",
  desc = "Le tracce di Agmond vengono da ovest. Dalle strisce di sangue sulla roccia e sulla sabbia si capisce subito che il nano si è trascinato per un bel pezzo.$B$BE qui è morto.$B$BA guardare da vicino, su un tratto di arenaria delle Badlands si legge la parola \"Murdaloc\", scarabocchiata alla meglio.$B$BScarabocchiata accanto alla mano senza vita di Agmond.",
  obj = "Uccidi l'assassino di Agmond, Murdaloc.$B$BUccidi 12 Stonevault Bonesnappers.$B$BTorna da Prospector Ironband a Loch Modan.",
  progress = "Sai qualcosa di quel che è successo ad Agmond? L'hai trovato?",
  reward = "È una notizia pesante, $N. Ma Agmond aveva il braccio forte, un colpo di martello micidiale e la testa più dura di chiunque altro! Anche se l'hanno ucciso quei maledetti troggs, sono sicuro che ne ha trascinati parecchi con sé.",
  en_title = "Murdaloc",
  en_obj = "Slay Agmond's killer, Murdaloc.$B$BSlay 12 Stonevault Bonesnappers.$B$BReport to Prospector Ironband in Loch Modan.",
}
T[762] = {
  title = "Un Ambasciatore del Male",
  desc = "È stato Ragnaros in persona a mandare Ambassador Infernus all'Angor Fortress, a sorvegliare il clan Shadowforge mentre cerca manufatti perduti a Uldaman.$B$BTutto questo è già costato perdite enormi al nostro popolo, ed è chiaro che le cose si sono messe peggio. Non oso pensare a quanti manufatti riuscirebbero a trovare e a usare contro Ironforge.$B$BQuello che dobbiamo fare è semplice, $C. Torna nelle Badlands e distruggi Ambassador Infernus. Quando la minaccia sarà eliminata, torna da Advisor Belgrum con la prova della tua vittoria.$B$BAdesso tocca a te.",
  obj = "Uccidi Ambassador Infernus in Angor Fortress e porta la prova della sua morte ad Advisor Belgrum a Ironforge.",
  progress = "Il tempo stringe, $N. Ragnaros non aspetterà che siamo pronti.",
  reward = "$N, nessuno può mettere in dubbio la tua dedizione a Ironforge e al popolo dei nani. Grazie per l'aiuto che ci hai dato in questa faccenda.$B$BManderò un messaggio a Historian Karnik per fargli sapere che ci sei $Griuscito:riuscita;, e farò mandare aiuti nelle Badlands al più presto, per aiutare a riprendere il sito di scavo. Grazie ancora.$B$BPrima che tu te ne vada, avrei un'altra cosa da chiederti in nome di King Bronzebeard.",
  en_title = "An Ambassador of Evil",
  en_obj = "Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.",
}
T[777] = {
  title = "Questa Sarà Dura",
  desc = "Ok, eccolo qua.$B$BIo me ne starò qui... al riparo.$B$BRaggiungimi, se vuoi.",
  obj = "Porta il Cog #5 a Lotwil Veriatus.",
  progress = "<Senza staccare gli occhi dalle catene, Lotwil tende una mano e agita le dita, impaziente.>$B$BL'ingranaggio, $N, l'ingranaggio!",
  reward = "Ah, perfetto. Sta' indietro, che mi preparo a scrivere un'altra pagina di storia!$B$B<Lotwil continua a lavorare febbrilmente.>",
  en_title = "This Is Going to Be Hard",
  en_obj = "Bring Cog #5 to Lotwil Veriatus.",
}
T[778] = {
  title = "Questa Sarà Dura",
  desc = "Ahah! Fatto! Le catene sono pronte!$B$BÈ il momento, Lucien. È il momento, Servo!$B$B$N, sei $Gpronto:pronta; a vedere alchimia, ingegneria e arti arcane fondersi alla perfezione?$B$BOra evocherò un potente elementale: oggi è un giorno rivoluzionario per tutti noi.",
  obj = "Sconfiggi il Fam'retor Guardian e riporta le Lotwil's Shackles of Elemental Binding a Lotwil Veriatus.",
  progress = "Non è andata proprio come mi aspettavo. Potresti recuperare le catene?",
  reward = "Grazie, $N. È stata dura, vero?$B$BNon so bene cosa possa essere andato storto. Per fortuna le mie magie hanno aiutato a rispedire la creatura nel suo piano d'origine.$B$BMagari un piccolo segno di gratitudine per tutte le tue fatiche...",
  en_title = "This Is Going to Be Hard",
  en_obj = "Defeat the Fam'retor Guardian and bring Lotwil's Shackles of Elemental Binding back to Lotwil Veriatus.",
}
T[779] = {
  title = "Seal of the Earth",
  progress = "Ecco il Seal of the Earth, con tre nicchie: una per l'Amethyst Runestone, una per l'Opal Runestone e una per la Diamond Runestone.",
  reward = "Mentre sistemi le Pietre Runiche negli incavi giusti, un boato violento scuote la terra e il Sigillo si spezza.",
  en_title = "Seal of the Earth",
}
T[782] = {
  title = "Alleanze Infrante",
  desc = "Sappiamo, dai tempi in cui l'Orda era alleata del drago Deathwing durante la Second War, che due dei suoi luogotenenti, Blacklash e Hematus, sono stati imprigionati nella Lethlor Ravine, lontano a est. Per restituire l'onore all'Orda dobbiamo mettere a tacere quei depravati che un tempo erano nostri alleati!$B$BAbbiamo assoldato Tho'grun e la sua banda di mercenari ogre perché ci aiutassero a prendere il Sign of the Earth, la chiave che serve ad aprire la prigione dei drachi. Ma Tho'grun ci ha traditi: ci ha sopraffatti e se l'è preso. Va' a Camp Boff e riprendilo!",
  obj = "Uccidi Boss Tho'grun e porta il Sign of the Earth a Gorn a Kargath.",
  progress = "Il tradimento di Tho'grun... e c'è da stupirsi se gli ogres non stanno più con l'Orda? Sarò lieto di vederlo morto e di riavere il Sign of the Earth.$B$BSe non l'hai ancora fatto fuori, non perdere tempo: va' a Camp Boff, a sud-est di Kargath.",
  reward = "Ora che Tho'grun è morto, e il suo cadavere lo spolpano i venti del deserto e gli avvoltoi in cerca di carogne, gli ogres saranno allo sbando. È una piccola vittoria, ma ne porterà una molto più grande.$B$BIl Sign of the Earth adesso è nostro, e possiamo aprire la prigione dei black drakes a Lethlor. Li libereremo dalla loro prigionia senza fine, anche se solo perché vadano incontro alla rovina!",
  en_title = "Broken Alliances",
  en_obj = "Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath.",
}
T[785] = {
  title = "Un'Alleanza Strategica",
  desc = "Thrall è un capo saggio, nobile come pochi. La sua tenacia in battaglia è pari solo alle sue capacità diplomatiche.$B$BI Darkspear Trolls si sono dimostrati alleati inestimabili per la stirpe degli orchi. Per lealtà e per onore abbiamo stretto con loro un patto di protezione.$B$BIl Capoguerra ci ha ordinato di prevenire qualsiasi minaccia incombente sui nostri amici Darkspear di Sen'jin Village. Uno dei loro esploratori più fidati, Lar Prowltusk, sorveglia da vicino il fianco occidentale del villaggio.$B$BVa' a cercare Lar e dagli una mano dove serve.",
  obj = "Trova Lar Prowltusk sul fianco occidentale di Sen'jin Village.",
}
T[793] = {
  title = "Alleanze Infrante",
  desc = "A tenere chiuso il Seal of the Earth sono tre pietre runiche, custodite nella Lethlor Ravine dentro i Pilastri di Diamante, Opale e Ametista. Con il Sign of the Earth potrai toglierle e aprire il Seal of the Earth.$B$BMa sta' in guardia, $N: con i black drakes Blacklash e Hematus non si scherza. Uccidili e riportami i loro bracciali.$B$BPer arrivare alla gola spingiti fino all'estremità orientale delle Badlands, ma fa' attenzione: laggiù vivono drachi a non finire.",
  obj = "Usa il Sign of the Earth per attivare i Pilastri di Diamante, Opale e Ametista e ottenere le Pietre Runiche.$B$BPosiziona le pietre runiche nel Seal of the Earth per liberare Blacklash e Hematus.$B$BUccidili e porta i Blacklash's Bindings, le Chains of Hematus e il Sign of the Earth a Gorn.",
  progress = "Ci sono pochi nemici letali quanto la stirpe dei draghi, e pochi draghi si sono battuti con la ferocia di Blacklash e Hematus.",
  reward = "Lo stormo dei draghi neri è ancora alleato degli orchi Blackrock rinnegati, e sia gli uni che gli altri vanno rimessi in riga, o eliminati. Ora che Blacklash e Hematus sono morti, possiamo rivolgere l'attenzione a ovest, verso Blackrock Spire.",
  en_title = "Broken Alliances",
  en_obj = "Use the Sign of the Earth to activate the Pillars of Diamond, Opal, and Amethyst and obtain the Runestones.$B$BPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.$B$BSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Gorn.",
}
T[795] = {
  title = "Seal of the Earth",
  progress = "Ecco il Seal of the Earth, con tre nicchie: una per l'Amethyst Runestone, una per l'Opal Runestone e una per la Diamond Runestone.",
  reward = "Mentre sistemi le Pietre Runiche negli incavi giusti, un boato violento scuote la terra e il Sigillo si spezza.",
  en_title = "Seal of the Earth",
}
T[822] = {
  title = "Chen's Empty Keg",
  desc = "Roba buona, la stormstout, eh?$B$BDa Chen ho imparato anche un'altra ricetta. Ti interessa? Non ci vuole molto a prepararla, e se pensi di andare ancora all'avventura potrebbe tornarti utile.$B$BPortami 5 lightning glands da uno stormhide qualsiasi, 1 thunderhawk saliva gland dai greater thunderhawks e un kodo liver da un kodo qualsiasi delle Barrens.$B$BTe l'ho detto, questa roba ha una bella botta: è la birra trogg di cui ti ho parlato prima.",
  obj = "Porta 5 Lightning Glands, 1 Thunderhawk Saliva Gland e 1 Kodo Liver a Brewmaster Drohn a Ratchet.",
  progress = "Ti dai da fare con quegli ingredienti, $N?",
  reward = "Ahah! Lo sapevo che a un po' di questa birra non avresti resistito. Quando ne vuoi ancora, torna pure, $N. Basta che mi riporti gli ingredienti che ti ho fatto raccogliere.",
  en_title = "Chen's Empty Keg",
  en_obj = "Bring 5 Lightning Glands, 1 Thunderhawk Saliva Gland and 1 Kodo Liver to Brewmaster Drohn in Ratchet.",
}
T[824] = {
  title = "Je'neu dell'Earthen Ring",
  desc = "The Earthen Ring è un gruppo di sciamani che studiano e proteggono gli elementi. Di vecchi dèi pazzi, antiche leggende e tradizioni ne hanno dimenticate più di quante ne saprà mai la maggior parte degli studiosi.$B$BPer tua fortuna, qui ad Ashenvale conosco qualcuno dell'Earthen Ring. Va' allo Zoram'gar Outpost, sulla costa della Zoram Strand, e fa' vedere a Je'neu Sancrea quello che hai trovato. Se c'è qualcuno capace di capire quanto conta quel globo, è lui.",
  obj = "Porta il Befouled Water Globe a Je'neu Sancrea a Zoram'gar Outpost, Ashenvale.",
  progress = "Ah, salve. Passo così tanto tempo a studiare l'acqua — anzi, tutti gli elementi — che a volte non mi accorgo nemmeno della gente che ho intorno.$B$BPosso aiutarti in qualcosa?",
  reward = "Questo globo... è davvero inquietante. Molti degli elementali più potenti traggono potere ed energia da congegni come questo. Trovarne uno quasi intatto è una cosa — trovarlo così contaminato è un'altra.$B$BFarò in modo che l'Earthen Ring studi il globo come si deve. Forse riusciremo a mettere fine a questa corruzione degli elementi. Ti prego — accetta questo come giusto compenso per aver segnalato il globo all'Earthen Ring.",
  en_title = "Je'neu of the Earthen Ring",
  en_obj = "Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
}
T[836] = {
  title = "Salva OOX-09/HL!",
  desc = "La voce dello gnomo gracchia di nuovo dal robot:$B$B\"Devo portare OOX-09/HL in un posto aperto e sicuro, dove possa cominciare una lunga procedura di decollo. Ha un sistema di occultamento integrato, ma per rimetterlo in funzione mi serve tempo, qui da me. Scorta il robot da dove si trova fino, diciamo, alla riva oltre l'Overlook Cliff! Dovrebbe essere il posto perfetto, e il tragitto abbastanza lungo per riattivare tutto!\"$B$B\"Portalo sano e salvo fino alla riva, e poi vieni a parlarmi a Booty Bay! Oglethorpe Obnoticus — passo e chiudo!\"",
  obj = "Scorta OOX-09/HL fino alla riva oltre Overlook Cliff, poi fai rapporto a Oglethorpe Obnoticus a Booty Bay.",
  reward = "Oh, sei TU $Gil grande salvatore:la grande salvatrice; di OOX-09/HL! Non so nemmeno da dove cominciare per ringraziarti! La mia serie di robot teleguidati è ancora da sviluppare, ma recuperandolo mi hai risparmiato ore e ore di ricostruzione, e un bel po' di monete d'oro in costi di fabbricazione!$B$BScegli pure quello che vuoi fra questi oggetti, ti prego. Grazie ancora del tuo generoso aiuto, $N: io e i miei robot siamo in debito con te!",
}
T[838] = {
  title = "Scholomance",
  desc = "Sull'isola di Caer Darrow sorge Scholomance — una scuola che fa da roccaforte allo Scourge. Il nostro nemico si è insediato lì dentro, e può portare avanti indisturbato le ricerche che ne accrescono il potere. Una porta sbarra il passaggio e, per quanto ci proviamo, senza la chiave giusta non c'è modo di entrare.$B$BApothecary Dithers conosce bene Scholomance e ha un'idea su come procurarsi una chiave. Mi hai dimostrato quanto vali: sei una persona che non lascia le cose a metà, e ora questo incarico lo affido a te. Parlane con lui.",
  obj = "Parla con Apothecary Dithers al Bulwark, Western Plaguelands.",
  reward = "Sì, $C, l'Alto Esecutore mi ha detto che forse eri la persona giusta a cui affidare la faccenda della chiave. Negli ultimi tempi ho dedicato buona parte dei miei studi a Scholomance, e credo di conoscere un modo con cui potrai procurartene una che ti permetta di varcare il portone quando vuoi.$B$BNon sarà facile, ma compiti del genere lo sono di rado. E tu hai senz'altro l'aria di chi lo sa bene.",
}
T[841] = {
  title = "Un'Altra Fonte di Energia?",
  desc = "Fammi indovinare — non sei $Griuscito:riuscita; a finire in tempo qualunque malefatta da fine del mondo stessi combinando. No, aspetta, ancora meglio... l'hai lasciata cadere nella sabbia! Be', qualunque sia il motivo, di fonti di energia da venderti ne ho altre. Però stavolta ti costerà dieci, SÌ, DIECI Wastewander Water Pouches!$B$BSono tempi duri per tutti, $N, e le fonti di energia non crescono sugli alberi! Mmh, e se invece ci crescessero? Magari potremmo CREARE un albero delle fonti di energia...",
  obj = "Porta 10 Wastewander Water Pouches a Chief Engineer Bilgewhizzle a Gadgetzan in cambio di un'altra fonte di energia.",
  progress = "Allora, i dieci otri d'acqua ce li hai?",
  reward = "Molto bene, eccoti un'altra fonte di energia. Stavolta usala come si deve, te lo consiglio vivamente, a meno che tu non abbia voglia di spendere altri dieci otri d'acqua per averne una nuova.",
}
T[843] = {
  title = "La Riconquista di Gann",
  desc = "Vago per queste strade in solitudine.$B$BI nani di Bael Modan non hanno alcun rispetto per la mia terra. Le loro esplosioni orribili scavano buchi profondi nel terreno, e le loro macchine rumorose squarciano le colline. Le terre che un tempo davano casa e sostentamento alla mia tribù ora brulicano di nani che portano distruzione.$B$BOgni tentativo di arrivare a una soluzione diplomatica è fallito. Ora bisogna agire con decisione.$B$BCaccia con la forza i nani dallo scavo di Bael Modan e portami il diario del loro capo, Prospector Khazgorm.",
  obj = "Gann Stonespire vuole che tu uccida 15 Bael'dun Excavators e 5 Bael'dun Foremen.$B$BPorta il Khazgorm's Journal a Gann Stonespire.",
  progress = "Quando sono arrivati i nani di Bael Modan, molti tauren innocenti hanno perso la vita o sono stati cacciati dalla terra natale dei loro antenati. La mia terra va riconquistata!",
  reward = "Khazgorm ha fatto la fine che meritava, e per quello sciocco non provo alcun rimorso. Era un infedele in queste terre.$B$BChe la sua morte sia un monito per chiunque minacci di sconvolgere il nostro modo di vivere.$B$BOra lasciami studiare per un momento il diario del nano...",
  en_title = "Gann's Reclamation",
  en_obj = "Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.$B$BBring Khazgorm's Journal to Gann Stonespire.",
}
T[846] = {
  title = "La Vendetta di Gann",
  desc = "È chiaro che il prospettore si affidava agli esplosivi e a quei veicoli rumorosi per squarciare il terreno. C'è da aspettarsi che presto un nuovo caposquadra prenda il comando.$B$BVoglio ripagare i nani con la loro stessa moneta. Secondo questi piani, unendo la nitroglicerina alla wood pulp e al sodium nitrate possiamo creare una carica esplosiva. Si sa che i fucilieri, i soldati e gli ufficiali della Fortezza ne tengono delle scorte.$B$BRaccogli questi materiali e portameli. Preparerò una carica che i nani non dimenticheranno!",
  obj = "Gann Stonespire vuole che tu gli porti 6 fiale di Nitroglycerin, 6 fasci di Wood Pulp e 6 campioni di Sodium Nitrate.",
  progress = "Vedo che sei $Gtornato:tornata;, $N.$B$BLa morte di Khazgorm forse rallenterà un po' gli scavi nelle terre dei miei antenati, ma non basterà certo a fermare la distruzione.$B$BLa Fortezza di Bael Modan è una minaccia militare che cresce sempre di più. L'hanno costruita per difendere il sito di scavo, ma ora è pronta anche ad attaccare.$B$BSe hai gli ingredienti che ti ho chiesto, posso preparare una carica che farà riflettere quei nani avventati su ciò che stanno facendo qui nelle Barrens.",
  reward = "Vedo che sei molto $Goperoso:operosa;, $C.$B$BPresto, senza dubbio, avremo la sorpresa giusta per quei nani.",
  en_title = "Revenge of Gann",
  en_obj = "Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate.",
}
T[847] = {
  title = "L'Astuzia del Raptor",
  desc = "Questo... questo potere.... È questo il potere degli sciamani che Tor'gan ha cercato di mostrarmi? Interessante, devo ammetterlo. Di' a Tor'gan che mi ha convinto... per ora. Sentirò quello che ha da dire.",
  obj = "Parla con Tor'gan.",
  reward = "Quando l'incantesimo sarà svanito, parlerò con Gor'mul. Grazie di avermi aiutato a riportare Gor'mul nel mondo dei vivi. Sono sicuro che anche lui ti è molto grato.",
  en_title = "Guile of the Raptor",
  en_obj = "Speak with Tor'gan.",
}
T[849] = {
  title = "La Vendetta di Gann",
  desc = "Con i piani di Khazgorm non dovrebbe essere difficile preparare una carica esplosiva.$B$BAh, ecco fatto.$B$BOra, $N, ho un compito speciale per te. Prendi questo candelotto esplosivo e fai saltare in aria la macchina volante di Bael Modan.$B$BNon è soltanto una parte fondamentale delle strutture del sito, ma anche un'arma da guerra. E soprattutto è un simbolo di potere e un insulto alla memoria della mia tribù.$B$BPorta a termine questa impresa eroica, rendimi fiero di te, e sarai $Gricompensato:ricompensata;.",
  obj = "Distruggi la macchina volante a Bael Modan e torna da Gann Stonespire.",
  progress = "Quando la macchina volante dei nani sarà distrutta, proverò la dolce soddisfazione della vendetta.",
  reward = "Hai fatto un buon lavoro, $N! Possano venerarti a Thunder Bluff come $Gdifensore:difensora; delle sacre terre dei tauren e $Gcampione:campionessa; della tribù perduta.",
  en_title = "Revenge of Gann",
  en_obj = "Destroy the flying machine at Bael Modan and return to Gann Stonespire.",
}
T[857] = {
  title = "La Tear of the Moons",
  desc = "Il potere era mio! Ce l'avevo proprio in mano! E lo rivoglio! Lo rivoglio, dico!$B$BQuegli sporchi scavatori l'hanno tirata fuori... così bella era. La chiamavano la Tear of the Moons, ed è stata la prima grande scoperta che abbiamo fatto a Bael Modan.$B$BDoveva essere mia! Mia, dico!$B$BGeneral Twinbraid si è ingelosito del potere che mi dava, e l'ha chiusa nella Rocca. Ha detto che era maledetta, ha detto! Che stupido!$B$BAltri la volevano, e bisognava fermarli! Quel bastardo di Twinbraid mi ha cacciato.$B$BOra la rivoglio. La rivoglio, dico!",
  obj = "Feegly the Exiled vuole che tu recuperi per lui la Tear of the Moons.",
  progress = "Dov'è la Tear of the Moons? Mi serve adesso! Mi serve, dico!",
  reward = "Finalmente il potere è di nuovo mio! Mio, dico!",
  en_title = "The Tear of the Moons",
  en_obj = "Feegly the Exiled wants you to retrieve for him the Tear of the Moons.",
}
T[862] = {
  title = "Dig Rat Stew",
  desc = "$GUn:Una; $C come te, qui in The Barrens, avrà una gran fame. Io, per conto mio, muoio di fame tutto il giorno.$B$BFacciamo così: ti preparo un bello stufato, mi servono solo dei dig rats.$B$BPare che quei lerci nani di Bael Modan siano invasi dal banchetto preferito di tutti. Quindi scendi a sud fino a Bael Modan e riportami un po' di dig rats.$B$BFinché non hai passato un po' di tempo ad ammazzare ratti, non puoi dirti $Gun avventuriero navigato:un'avventuriera navigata;! Ah!",
  obj = "Porta 8 Dig Rats a Grub, a est del Crossroads.",
  progress = "Hai già fatto fuori abbastanza dig rats, $N?",
  reward = "Di solito questi roditori non li mangio volentieri quando sono così... così... maturi. Mi piace lasciarli marcire qualche settimana, perché tirino fuori tutto il sapore. Ma hai un'aria così $Gaffamato:affamata;.$B$BLascia che ti prepari un po' di Dig Rat Stew. Ah, ecco fatto.$B$BEcco a te!",
  en_title = "Dig Rat Stew",
  en_obj = "Bring 8 Dig Rats to Grub east of the Crossroads.",
}
T[864] = {
  title = "Ritorno da Apothecary Zinge",
  desc = "\"Ecco qua, fonte di energia tolta senza danni e dati salvi. Be', buon viaggio e tutto il resto. Spero che il tuo malvagio esperimento scientifico ti sia riuscito, e via dicendo.\"$B$BIl goblin si volta dall'altra parte per occuparsi delle richieste della Gadgetzan Water Company. In vista del viaggio di ritorno verso Undercity, metti al sicuro l'attrezzatura sigillata: là Apothecary Zinge aspetta te e la field testing kit sigillata.",
  obj = "Porta la Field Testing Kit Sigillata ad Apothecary Zinge a Undercity.",
  progress = "$GBentornato:Bentornata;. Almeno, $Gbentornato:bentornata; se sei $Gtornato:tornata; con un'attrezzatura per le analisi sigillata. Altrimenti, farò finta di non vedere la tua totale incompetenza e ti risparmierò la mia ira finché non avrai fatto ciò che ti è stato ordinato e portato a termine il mio compito.",
  reward = "Analizzerò subito questi dati. Forse, dopotutto, la follia di Keever si rivelerà il mio genio.$B$BQuanto a te... mi sei utile, e chi resta utile lo ricompenso molto bene. Prendi questo oggetto, questa moneta e, soprattutto, i miei ringraziamenti.$B$BTorna a trovarmi ogni tanto — scommetto che su questo progetto la nostra collaborazione non è finita.",
}
T[866] = {
  title = "Root Samples",
  desc = "Le erbe delle Barrens non sono proprio uguali a quelle delle altre terre. Le proprietà sono più o meno le stesse, ma qui l'acqua delle oasi altera le piante e le rende appena un po' diverse.$B$BVoglio studiarle, queste differenze... e vedere se si possono sfruttare!$B$BSe sei $Gesperto:esperta; di erboristeria, raccogli dei root samples dalle erbe che trovi nelle Barrens e riportameli, così li confronto con le erbe delle altre regioni.",
  obj = "Porta 8 Root Samples a Mebok Mizzyrix a Ratchet.",
  progress = "Ciao, $N. Allora, ce li hai i root samples?",
  reward = "Sì sì, sono bellissimi! Da queste radici farò crescere degli esemplari e li studierò. Spero di scoprirci proprietà nuove. Nascoste, preziose...!$B$BE non preoccuparti — se le trovo, sarai $Gil primo:la prima; a saperlo. Tanto mi servirà qualcuno che me ne raccolga altri!",
  en_title = "Root Samples",
  en_obj = "Bring 8 Root Samples to Mebok Mizzyrix in Ratchet.",
}
T[868] = {
  title = "Caccia alle Uova",
  desc = "Ehi, $N. Mi hanno mandato al Crossroads per i miei padroni a Orgrimmar: devo sorvegliare la terra e prendere nota di quel che succede.$B$BTra le cose che studio ci sono le creature simili a insetti che stanno a sud, nel Field of Giants. Ne sappiamo poco, perciò mi do da fare per scoprirne di più. Sembrano più intelligenti di qualsiasi animale normale.$B$BPrendi questo digging claw e raccogli un po' delle loro uova dai monticelli. Ma fa' attenzione: se si accorgono di te, ti attaccheranno.",
  obj = "Porta 12 Silithid Eggs e il Digging Claw a Korran, al Crossroads.",
  progress = "Fa' attenzione alle uova che trovi, $N. Se si rompono, a me non servono a niente.",
  reward = "Mi fai contento, $N. Le uova e pure l'attrezzo. Ben fatto.$B$BE come ricompensa...",
  en_title = "Egg Hunt",
  en_obj = "Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads.",
}
T[873] = {
  title = "Isha Awak",
  desc = "Il grande Isha Awak è il signore di queste acque: grande è la sua forza, e solenne il suo orgoglio. Gli umani della costa lo temono, perché ne ha divorati molti.$B$BMa io non lo temo, e sono grata che sia qui: è una sfida degna, e una preda onorevole.$B$BSe sei $Gpronto:pronta;, nuota al largo e cerca Isha Awak, la Rovina degli Abissi.$B$BIl suo spirito dimora nel cuore: udirne il battito significa conoscere il tuo destino.",
  obj = "Porta l'Heart of Isha Awak a Mahren Skyseer.",
  progress = "Non temere le acque, $R.",
  reward = "Ora tu e Isha Awak siete una cosa sola, $N. Il suo spirito è con te: si cela nei tuoi occhi...$B$BOcchi che un giorno impareranno a vedere.",
  en_title = "Isha Awak",
  en_obj = "Bring the Heart of Isha Awak to Mahren Skyseer.",
}
T[874] = {
  title = "Mahren Skyseer",
  desc = "Hai cacciato le bestie delle Barrens, e il tuo spirito è forte. Ma $Gun cacciatore:una cacciatrice; deve essere sempre $Gpronto:pronta;: $Gun vero cacciatore:una vera cacciatrice; può seguire la preda per qualunque sentiero, e né le montagne né le paludi $Glo:la; fermeranno.$B$BNemmeno il mare.$B$BTrova mia sorella, Mahren: caccia le grandi bestie acquatiche lungo la costa, e sarà lei a insegnarti le loro abitudini.$B$BMa mentre la cerchi fa' attenzione, perché la costa delle Barrens è in mano agli umani.",
  obj = "Parla con Mahren Skyseer.",
  reward = "Così ti manda mio fratello, eh? Allora gli avrai dato prova del tuo valore. Se ti sei $Gguadagnato:guadagnata; il rispetto di Jorn, hai anche il mio.$B$BSei $Gpronto:pronta; a spingerti più avanti sulla via del cacciatore?",
  en_title = "Mahren Skyseer",
  en_obj = "Speak with Mahren Skyseer.",
}
T[878] = {
  title = "Tribù in Guerra",
  desc = "Devi colpire i miei nemici. <sbuffa> Devi aiutare Mangletooth e i Razormane indebolendo i Bristleback. Le due tribù sono molto spirituali — legate alla terra e al suo potere. <sbuffa> Ci dà forza in tutto... soprattutto in guerra.$B$BSe vuoi scoprire chi dà davvero tanta angoscia a Thork <sbuffa> e all'Orda, aiuta Mangletooth! Attacca i capi spirituali dei Bristleback a nord; indeboliscili, così i Razormane potranno sconfiggerli e dominare le Barrens.",
  obj = "Uccidi 6 Bristleback Water Seekers, 12 Bristleback Thornweavers e 12 Bristleback Geomancers e torna da Mangletooth a Camp Taurajo in Barrens.",
  progress = "Darò altre informazioni <sbuffa> all'Orda quando avrai ucciso i saggi dei Bristleback, $R. <sbuffa> Non un momento prima! Mangletooth non è uno sciocco.",
  reward = "Sì, sì... pieno di gioia, perché finalmente <sbuffa> i Bristleback provano il dolore della mia tribù, $R. Così dovrei sentirmi, ma <sbuffa> non è vero.$B$BTu aiuti la tua gente e loro ti rendono onore. Mangletooth aiuta la sua gente, e loro cosa fanno? Gli voltano le spalle. Lo dimenticano e lo lasciano marcire in gabbia!$B$BIo li aiuto anche chiuso qui dietro le sbarre, e loro non mandano nessuno a salvarmi!",
  en_title = "Tribes at War",
  en_obj = "Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens.",
}
T[879] = {
  title = "Tradimento dall'Interno",
  desc = "Dal Kraul sono usciti tre della mia tribù, $R, per guidare le incursioni contro l'Orda. <sbuffa> Sono spietati e astuti. Se li sconfiggi, il tuo Crossroads, e perfino gran parte delle Barrens, avranno pace... <sbuffa> almeno dalla tribù Razormane. <sbuffa>$B$BQuelli che cerchi sono Nak, Kuz e Lok Orcbane, e stanno all'estremo sud delle Barrens. Uno lancia incantesimi, l'altro segue le tracce, e il capo, quello che chiamano Orcbane, <sbuffa> è un guerriero. Uccidili, $R, come loro hanno ucciso me.",
  obj = "Uccidi Nak, Kuz e Lok Orcbane e porta i loro teschi a Mangletooth a Camp Taurajo nelle Barrens.",
  progress = "Come va la caccia, $R? <sbuffa>$B$BThork crede di sapere la verità su chi guida le incursioni contro la sua gente, <sbuffa> ma se ce la fai scoprirà quanto si sbaglia.$B$BPer me la morte non si può evitare, ma hai dato un gran dolore ai miei nemici, perciò Mangletooth non rimpiange niente. <sbuffa>",
  reward = "Allora è fatta. Meglio che finisca così, dice Mangletooth. <sbuffa> Quando mi hanno voltato le spalle avrebbero dovuto <sbuffa> accertarsi che fossi morto, invece di lasciarmi <sbuffa> qui, in questa gabbia maledetta.$B$BTi resta solo un'ultima cosa da fare, $R.",
  en_title = "Betrayal from Within",
  en_obj = "Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens.",
}
T[883] = {
  title = "Lakota'mani",
  desc = "L'Hoof of Lakota'mani è un simbolo della forza del grande kodo.",
  obj = "Porta l'Hoof of Lakota'mani a Jorn a Camp Taurajo.",
  progress = "Mentre ti avvicinavi, $N, ho visto un nuovo potere nel tuo passo. Dimmi — il tuo spirito ha incontrato il grande Lakota'mani?",
  reward = "Nella nostra lingua Lakota'mani si chiama \"Earthshaker\", e i suoi passi sono come un tuono che si raccoglie. Ora è con te, e il suo coraggio si unisce al tuo. Insieme, non c'è battaglia che tu non possa affrontare.$B$BCammina a testa alta, $N. Cammina a testa alta, Earthshaker.",
  en_title = "Lakota'mani",
  en_obj = "Bring the Hoof of Lakota'mani to Jorn at Camp Taurajo.",
}
T[884] = {
  title = "Owatanka",
  desc = "Lo spuntone della coda di Owatanka sprizza scintille appena lo tocchi.",
  obj = "Porta l'Owatanka's Tailspike a Jorn a Camp Taurajo.",
  progress = "$N, nel tuo sguardo c'è un nuovo potere! Hai incontrato il possente Owatanka, vero?",
  reward = "I tauren chiamano il thunder lizard Owatanka \"Saetta Azzurra\", perché ha una velocità che la sua mole non lascerebbe mai sospettare. Si dice che molto tempo fa un fulmine abbia colpito Saetta Azzurra e che la grande bestia, nutrita dalla furia del cielo, abbia da allora un'energia senza limiti.$B$BChe la sua energia scorra in te, $N. Perché adesso tieni il passo di Owatanka.",
  en_title = "Owatanka",
  en_obj = "Bring Owatanka's Tailspike to Jorn at Camp Taurajo.",
}
T[885] = {
  title = "Washte Pawne",
  desc = "A toccarla, la piuma di Washte Pawne fa male.",
  obj = "Porta la Washte Pawne's Feather a Jorn Skyseer a Camp Taurajo.",
  progress = "In te c'è una nuova determinazione, $N. Una determinazione nata dal dolore...$B$BPorti con te il peso della morte di Washte Pawne?",
  reward = "Il falco del tuono è una bestia rara nelle Barrens, e la sua morte può essere presagio di grande fortuna o di grande rovina.$B$BMa Washte Pawne, che in Taurahe si chiama \"Mordispirito\", non può portare né l'una né l'altra... oppure tutte e due.$B$BIl dolore che hai provato cacciando Mordispirito è la fitta che prova chiunque paghi a caro prezzo le sue grandi conquiste. La puntura che hai sentito è quella del rimpianto.$B$BMa vedo che l'hai superato. Hai imparato che il rimpianto diventa saggezza, e che dal dolore nasce la forza.$B$BHai imparato molto, $N.",
  en_title = "Washte Pawne",
  en_obj = "Bring Washte Pawne's Feather to Jorn Skyseer at Camp Taurajo.",
}
T[893] = {
  title = "Armi Preferite",
  desc = "Mi dicono che i verrospini Razormane, a sud oltre il Field of Giants, non hanno fabbri esperti, eppure pare che abbiano cominciato a fabbricare armi più robuste. Se possibile, vorrei mettere le mani su qualche arma di tipo diverso per studiarne le tecniche.$B$BSe vuoi aiutare a fare onore all'Orda, portami qualche esemplare delle loro armi: un pugnale dei cacciatori furtivi, una bacchetta dei veggenti e uno scudo dei guerrieri furiosi. Andrà benissimo!",
  obj = "Porta un Razormane Backstabber, una Charred Razormane Wand e un Razormane War Shield a Tatternack Steelforge a Camp Taurajo in Barrens.",
  progress = "Anch'io dubito che quei patetici quilboar possano diventare abili nell'arte del fabbro, ma il Capoguerra comanda e io obbedisco: imparerò tutto quello che posso sulla tribù dei Razormane.$B$BMi sono toccati compiti più umili di questo, e li svolgo volentieri, se servono al popolo degli orchi.",
  reward = "Esemplari eccellenti, davvero eccellenti.$B$BQuilboar sono più avanti di quanto mi aspettassi.$B$BTieni, $C, prendi questo e levati di torno: è meglio che esamini da vicino queste armi. Forse abbiamo sottovalutato il nemico, e non possiamo permetterci un errore del genere.",
  en_title = "Weapons of Choice",
  en_obj = "Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.",
}
T[897] = {
  title = "Il Falciatore",
  desc = "Questa strana creatura, simile a un insetto, sembra fuori dall'ordine naturale, come se non appartenesse alle Barrens.",
  obj = "Porta l'Harvester's Head a Jorn Skyseer.",
  progress = "Sembri $Gturbato:turbata;, $N. Come vanno le tue lezioni nelle Barrens? Hai trovato qualcosa che ti inquieta?",
  reward = "Della natura di questa bestia non riesco a capire nulla, perché il suo spirito è fuggito. Ma, come hai intuito, non appartiene alle Barrens. Temo che possa annunciare un futuro cupo per il nostro popolo...$B$BPer ora, però, preparati, e speriamo che il tempo sveli il mistero di questa creatura.",
  en_title = "The Harvester",
  en_obj = "Bring the Harvester's Head to Jorn Skyseer.",
}
T[906] = {
  title = "Tradimento dall'Interno",
  desc = "Porta il teschio di Lok a Thork, al Crossroads, $R. <sbuffa> Dovrebbe capire senza bisogno di parole cos'è successo alla mia tribù — ah, non che crederebbe che Mangletooth abbia dato una mano in <sbuffa> cose del genere. Ma sono sicuro che ti ricompenserà per un'impresa così grande. <sbuffa>$B$BFinché resterò in questa gabbia continuerò a benedirti con il potere di Agamaggan, $R. Fino ad allora, addio.",
  obj = "Porta il Lok's Skull a Thork al Crossroads nelle Barrens.",
  progress = "Sì, che c'è?",
  reward = "Hai trovato il capo dei Razormane e l'hai ucciso tu $Gstesso:stessa;, $N? Straordinario.$B$BMi hai lasciato senza parole, ma non senza gratitudine. La gente del Crossroads farebbe bene a rispettare la tua forza.$B$BLo ammetto, pensavo che a guidare queste incursioni contro le nostre linee di rifornimento fosse un altro quilboar. Grazie ancora, $N.",
  en_title = "Betrayal from Within",
  en_obj = "Bring Lok's Skull to Thork at the Crossroads in the Barrens.",
}
T[908] = {
  title = "Tra le Rovine",
  desc = "Il Twilight's Hammer si è stabilito nelle Moonshrine Ruins of Blackfathom Deeps, e con loro lì gli elementi saranno per forza costretti ad agire contro di noi. Se nessuno li ferma, questa regione sarà loro per sempre.$B$B$N, va' a Blackfathom e trova la pietra profonda delle rovine: dovrebbe essere lì vicino, da qualche parte nell'acqua. Dentro c'è un fathom core — un congegno che, letto nel modo giusto, racconta la storia di tutta l'attività elementale. Se riesco ad averlo, l'Earthen Ring e io forse potremo fare qualcosa per fermarli!",
  obj = "Porta il Fathom Core a Je'neu Sancrea a Zoram'gar Outpost, Ashenvale.",
  progress = "Sei $Griuscito:riuscita; a trovare il fathom core? Senza, non potremo capire cosa stia tramando di preciso il Twilight's Hammer, laggiù.",
  reward = "È proprio quello che mi serve! Un fathom core è una fonte di informazioni incredibile, e potremo ricavarne molto. Qualunque cosa stia tramando lì dentro il Twilight's Hammer — e credimi, non è niente di buono — ora i miei compagni e io lo scopriremo.$B$BOggi hai fatto un buon lavoro, e per il tuo aiuto l'Earthen Ring ti vede di buon occhio. Hai dato una mano anche a tutta l'Orda, e dovresti andarne $Gfiero:fiera;.",
}
T[909] = {
  title = "Baron Aquanis",
  desc = "Sconfitto, il water elemental ha lasciato uno strange water globe. Immagini che fosse questo oggetto, in qualche modo, a dare energia alla bestia. Dentro si agita un'acqua dall'aspetto putrido, e il globo sembra resistere a qualsiasi forza fisica.$B$BSe c'è qualcuno in grado di capirci qualcosa, è Je'neu Sancrea of the Earthen Ring, che si trova allo Zoram'gar Outpost dell'Orda, ad Ashenvale.",
  obj = "Porta lo Strange Water Globe a Je'neu Sancrea a Zoram'gar Outpost, Ashenvale.",
  progress = "Ah, $Gben ritrovato:ben ritrovata;, $N. Leggevo le onde del mare, come faccio sempre. Cosa ti porta all'avamposto?",
  reward = "Questa... questa sì che è una scoperta, $N.$B$BDici che l'hai preso a Baron Aquanis, a Blackfathom? Da tempo si crede che Baron Aquanis sia una potenza elementale corrotta, e questo globo dimostrerà cosa, di preciso, l'abbia corrotto. Non ci sarebbe da stupirsi se fosse stato il Twilight's Hammer, ma i nostri studi ci diranno anche come ci sono riusciti.$B$BHai fatto bene a portarmelo. Ti prego — accetta questo, con i più calorosi saluti dell'Earthen Ring.",
}
T[910] = {
  title = "Giù a The Docks",
  desc = "Ho sentito delle storie sulle grandi navi che fanno avanti e indietro tra Ratchet e Booty Bay! Sarebbe fichissimo navigare sull'oceano e combattere un sacco di grandi battaglie navali. Magari da grande diventerò un possente marinaio dell'Orda! Sì!$B$BMi porteresti a vedere il porto di Ratchet, per favore? Prometto che non entro in acqua e non combino guai — voglio solo vedere le navi grandi e sentire l'odore del mare, dell'acqua salata! Sì!",
  obj = "Porta il tuo protetto al porto di Ratchet, nelle Barrens.",
  progress = "Siamo arrivati?",
  reward = "Wow, l'oceano è ENORME! E c'erano pure un sacco di gabbiani e roba così — è rumoroso e pieno di vita proprio come me l'immaginavo. E qui vicino ci sono anche i pirati — fichissimo!$B$BGrazie di avermi portato a Ratchet, $N. È stato fantastico!",
  en_title = "Down at the Docks",
  en_obj = "Take your ward to the docks of Ratchet in the Barrens.",
}
T[911] = {
  title = "La Porta della Frontiera",
  desc = "Dicono che Ashenvale è la nuova frontiera, e che il Mor'shan Rampart, nelle Barrens, è la sua porta. Sarebbe fichissimo fare il pioniere e prendersi dalle terre selvagge tutto quello che ti serve! Dicono anche che è lì che in futuro l'Orda e l'Alleanza si scontreranno di più, e io voglio esserci, $N!$B$BMi porteresti al Mor'shan Rampart, per favore, così vedo com'è la frontiera? Voglio vedere dove l'Orda sta cacciando via quei puzzolenti elfi della notte!",
  obj = "Porta il tuo protetto a Mor'shan Rampart, nella parte settentrionale delle Barrens, poco prima di entrare ad Ashenvale.",
  progress = "Siamo arrivati?",
  reward = "Wow, Ashenvale è il posto delle avventure vere! Tu ci hai mai combattuto, ad Ashenvale, $N? Quando da grande diventerò un eroe, voglio venire ad Ashenvale a combattere per la gloria dell'Orda!$B$BGrazie di avermi portato alla frontiera, $N. Sei $Gil migliore:la migliore;!",
  en_title = "Gateway to the Frontier",
  en_obj = "Take your ward to the Mor'shan Rampart in the northern part of the Barrens, just before entering Ashenvale.",
}
T[912] = {
  title = "Travestimento da Stonesplinter Trogg",
}
T[914] = {
  title = "I Capi della Zanna",
  desc = "I druidi delle Wailing Caverns, i Druids of the Fang, sono un'aberrazione. Appartenevano a un ordine di nobili druidi che voleva guarire le Barrens, ma ora cercano di rifare quella terra a immagine dei loro sogni contorti.$B$BI Druids of the Fang hanno quattro capi, e ognuno ha una gemma del sogno. I loro volti mi tormentano ancora adesso! Sconfiggili e portami le gemme, e le Barrens potranno tornare a conoscere la pace.$B$BVa', $N. Li troverai in agguato nel profondo delle Wailing Caverns.",
  obj = "Porta le Gems of Cobrahn, Anacondra, Pythas e Serpentis a Nara Wildmane a Thunder Bluff.",
  progress = "Mi tormentano i ricordi dei miei incubi, $N. Hai sconfitto i capi della zanna e preso le loro gemme?",
  reward = "Ce l'hai fatta, $N. Hai ucciso i capi dei Druids of the Fang. I loro volti malvagi non abitano più i miei sogni, e hai aiutato a salvare le Barrens da un futuro maledetto.$B$BTi ringrazio, $N. Ti ringrazio a nome mio, dei druidi di Thunder Bluff e della terra.",
  en_title = "Leaders of the Fang",
  en_obj = "Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.",
}
T[915] = {
  title = "Tu Strilli, Io Strillo...",
  desc = "GELATO! Oh ti prego ti prego ti prego, mi prendi un po' di gelato?! Il mio gusto preferito è la fragola, e al mondo non esiste gelato alla fragola più buono del Gelato alla Fragola di Tigule e Foror! È il mio gelato preferito in tutto il mondo intero!$B$BL'ho mangiato una volta, tanto tempo fa, quando ero alla pista da corsa delle Shimmering Flats, ma ho sentito dire che forse adesso lo vendono in città! Per favore? Ti prego ti prego? Con sopra il Gelato alla Fragola di Tigule e Foror??!?!",
  obj = "Prendi un po' di Gelato alla Fragola per il tuo protetto. Il ragazzino sembra preferire il gelato della marca di Tigule e Foror.",
  progress = "Vorrei che facessero altri gusti di gelato oltre alla fragola, ma mi sa che mi va bene, visto che la fragola è il mio preferito!",
  reward = "Mmmmmmmmm! Il loro gelato alla fragola lo adoro! Se c'è una cosa che Tigule e Foror sanno fare, è il gelato!$B$BGrazie mille, $N — è la merenda più buona di sempre!",
  en_title = "You Scream, I Scream...",
  en_obj = "Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream.",
}
T[925] = {
  title = "Cairne's Hoofprint",
  desc = "Dicono che Cairne Bloodhoof è uno dei più grandi eroi che l'Orda abbia mai visto. Da grande voglio diventare anch'io un eroe dell'Orda!$B$BConosci Cairne, $N? Mi faresti un favore, ti prego? Riusciresti a farti dare la sua impronta di zoccolo per me? Io non so come chiederglielo, e probabilmente sarebbe troppo impegnato per uno come me... ma tu! Tu sei $Gun avventuriero:un'avventuriera; proprio come lui! Scommetto che a te la sua impronta la darebbe subito!$B$BPer favore?",
  obj = "Va' a Thunder Bluff e cerca di farti dare l'impronta di zoccolo di Cairne Bloodhoof per il tuo protetto.",
  progress = "Quando gli orchi erano soli e non avevano amici, i tauren li hanno accolti in una terra straniera e hanno diviso con loro quel che avevano, senza chiedere niente in cambio. Questo è onore, $N.",
  reward = "WOW! Mi hai portato l'impronta di zoccolo di Cairne! Grazie mille! E wow... ci ha scritto sopra un messaggio personale — per me! Lo sapevo che era fichissimo, lo sapevo e basta! Magari un giorno lo ringrazierò di persona... quando diventerò un eroe dell'Orda!$B$BSei $Gil migliore:la migliore;, $N. Grazie di essere $Gstato:stata; così gentile con me.",
  en_title = "Cairne's Hoofprint",
  en_obj = "Travel to Thunder Bluff to see about getting Cairne Bloodhoof's hoofprint for your ward.",
}
T[936] = {
  title = "Assistere l'Arcidruido Runetotem",
  desc = "Scusami, $C, se puoi vorrei rubarti solo un momento.$B$BIl Cenarion Circle di Thunder Bluff sta cercando proprio avventurieri esperti come te, che lo aiutino in una ricerca di vitale importanza. I dettagli non li conosco, ma so che a guidarla è nientemeno che Hamuul Runetotem.$B$BTi prego — se sei $Ginteressato:interessata;, va' a parlare direttamente con lui sull'Elder Rise, nella città di Thunder Bluff.",
  obj = "Parla con Arch Druid Hamuul Runetotem a Thunder Bluff.",
  reward = "Salute, $C; sono lieto che tu sia $Ginteressato:interessata; ad aiutarci nella ricerca. C'è molto da fare, e ti farei un torto se ti dicessi che non è un lavoro pericoloso. Spero che non ti spaventi... ma dal tuo aspetto direi che il pericolo lo conosci già.",
}
T[939] = {
  title = "Flute of Xavaric",
  desc = "Studi il semplice flauto di legno che hai raccolto dopo aver sconfitto Xavaric.$B$BIl legno nodoso sembra solido, ma mentre lo giri fra le mani le spirali e i disegni sulla superficie sembrano mettersi a ruotare e a muoversi. All'improvviso ti prende un senso di angoscia...$B$BScuoti la testa, $Gsicuro:sicura; che sia la mente a giocarti brutti scherzi.$B$BPuò darsi che altri satiri abbiano con sé qualche indizio su ciò che hai trovato. Porta quello che hai scoperto alla druida, Eridan Bluewind, che vive nel Felwood meridionale.",
  obj = "Porta il Flute of Xavaric e 5 campioni di Jadefire Felbind a Eridan Bluewind, nel Felwood meridionale.",
  progress = "Che succede, $C? Mi sembri $Gpreoccupato:preoccupata;.",
  reward = "Sento la sofferenza degli antichi, $N...$B$BAvere questi oggetti fra le mani è quasi insopportabile...",
}
T[943] = {
  title = "Il Prospettore Distratto",
  desc = "Il fossile originale ora ce l'ha Prospector Whelgar, al suo sito di scavo nelle Wetlands. Quando ho scoperto la Stone of Relu, ho creduto che fosse la chiave per svelare il mistero del fossile.$B$BMentre andavo da Whelgar, mi hanno assalito i raptors e ho perso la reliquia. Non so quale di quelle bestie chiazzate l'abbia inghiottita, ma se riesci a recuperarla potrò liberare il potere di questi manufatti.$B$BPortami sia la Stone of Relu sia il fossile originale custodito dal prospettore.",
  obj = "Archaeologist Flagongut, a Menethil Harbor, vuole che tu gli porti la Stone of Relu e il Flagongut's Fossil.",
  progress = "Con la Stone of Relu, $N, potrò svelare i segreti nascosti del mio fossile e anche di quello di Remtravel, arrivato da Darkshore.",
  reward = "Davvero eccellente, $N!$B$BOra vediamo se riesco a usare la pietra per scoprire i poteri dei fossili.",
  en_title = "The Absent Minded Prospector",
  en_obj = "Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil.",
}
T[959] = {
  title = "Guai ai Moli",
  desc = "Ops!$B$BCome vedi, ho avuto un piccolo incidente! Stamattina da Booty Bay è arrivato un carico enorme. Enorme, ti dico! Tante casse non le avevo mai viste. Beh, volevo sbrigarmi, così mi sono messo a scaricarne un po' più di quante riuscissi a gestirne. Ed è lì che è venuto giù tutto.$B$BNon avevo ancora capito cosa stava succedendo, che ho visto quella peste di Mad Magglish scappare con una bottiglia di 99-year-old port. Gli sono corso dietro fino alle Wailing Caverns, ma lì dentro non ci sarei mai entrato.$B$BTu forse sei abbastanza $Gcoraggioso:coraggiosa; da scovarlo?",
  obj = "Crane Operator Bigglefuzz a Ratchet vuole che tu recuperi la bottiglia di 99-Year-Old Port da Mad Magglish, che si nasconde nelle Wailing Caverns.",
  progress = "Da quando Mad Magglish se l'è filata con quel 99-year-old port, ho il capo del porto col fiato sul collo. Pare che quella bottiglia fosse un regalo per Gazlowe da parte nientemeno che di Baron Revilgaz in persona.$B$BSe sei abbastanza $Gcoraggioso:coraggiosa; e paziente da andare a cercare Mad Magglish e riportarmi quel porto, ti farò avere una bella ricompensa.",
  reward = "Magnifico! E proprio quando stavo per perderci anche il lavoro! Mi assicurerò che Gazlowe riceva subito questo regalo.$B$BGrazie, $N. Ben fatto, ti dico!",
  en_title = "Trouble at the Docks",
  en_obj = "Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns.",
}
T[962] = {
  title = "Serpentbloom",
  desc = "La Royal Apothecary Society, che ha sede nella grande Undercity of Lordaeron, mi ha mandata qui con un compito ben preciso, $N. Forse vorrai aiutare me, e quindi la Dama Oscura, nei nostri sforzi per far progredire i Forsaken.$B$BUltimamente ho studiato un raro esemplare di pianta, il Serpentbloom. Credo che quest'erba, in quantità maggiori, abbia grandi potenzialità.$B$BPurtroppo il Serpentbloom cresce solo negli angoli più bui delle Wailing Caverns, una pericolosa rete di grotte nelle Barrens.",
  obj = "Apothecary Zamah a Thunder Bluff vuole che tu raccolga 10 Serpentbloom.",
  progress = "Sono ansiosa di vedere se riuscirai a raccogliere abbastanza Serpentbloom nelle Wailing Caverns. Ne ho mandati molti a eseguire i miei ordini, e non è tornato nessuno.",
  reward = "Ah, che splendidi esemplari. Hai fatto un buon lavoro, $N.",
  en_title = "Serpentbloom",
  en_obj = "Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.",
}
T[964] = {
  title = "Skeletal Fragments",
  desc = "La chiave di Scholomance si chiama Skeleton Key. Va forgiata con i resti di uno scheletro — anzi, di parecchi — e rinforzata solo con i metalli più robusti, dentro uno stampo adatto. A farla funzionare davvero sarà il sigillo di potere di un essere capace per natura di aprire il portale di Scholomance.$B$BMa andiamo per ordine, $N. Per la forgiatura ci servono degli skeletal fragments. Gli scheletri dentro Andorhal dovrebbero fornirci il necessario, ma potrebbero andar bene anche quelli fuori dalle mura.",
  obj = "Porta 15 Skeletal Fragments ad Apothecary Dithers al Bulwark, Western Plaguelands.",
  progress = "Uccidine tanti, e senza sosta, $C — ci servirà una buona scorta di skeletal fragments adatti per lo strato esterno della chiave. Non per niente la chiamano Skeleton Key, sai.",
  reward = "Andranno bene, $N! Ora tocca a me: li tratterò con un'infusione che li tempri abbastanza da resistere all'intensa forgiatura che li aspetta.$B$BIl passo successivo sarà procurarci uno stampo adatto alla chiave. Conosco un fabbro goblin a Tanaris che in passato ha realizzato stampi per oggetti altrettanto macabri. Lavora per lo stesso padrone di quasi tutti i goblin — il miglior offerente.",
}
T[969] = {
  title = "Che la Fortuna Sia con Te",
  desc = "Ah, mi basta guardarti in faccia — tu vuoi farti un lucky charm. Mau'ari lo sa sempre!$B$BA sud troverai un canyon, con dei giganti di ghiaccio massiccio. Certe volte i frammenti li portano addosso loro, ma nel canyon li puoi sempre raccogliere da te. Hanno un grande potere riflettente, questi frammenti.$B$BPortami 10 frostmaul shards e il mio lucky charm sarà tuo.",
  obj = "Raccogli 10 Frostmaul Shards per Witch Doctor Mau'ari a Everlook.",
  progress = "Tu portami i frammenti, e io poi ti dico di più!",
  reward = "Ahh, sì... Ora te lo faccio, l'amuleto. Aspetta e vedrai!",
}
T[970] = {
  title = "La Tower of Althalaxx",
  desc = "La lettera di Balthule è allarmante. Questo Culto del Dark Strand è una spina nel fianco che va tolta. Ho avuto a che fare con un po' di quella feccia del Dark Strand a nord-est di qui, a Ordil'Aran. Uno di loro possiede una soul gem che, credo, custodisce il segreto del potere del culto.$B$BPortamela, e potrò decifrarne i misteri.",
  obj = "Raccogli una Glowing Soul Gem e riportala a Delgren the Purifier, a Maestra's Post.",
  progress = "Hai recuperato la soul gem?",
  reward = "Mmm, questa pietra dell'anima è avvolta da una magia oscura. Vediamo cosa c'è intrappolato dentro, che ne dici?",
  en_title = "The Tower of Althalaxx",
  en_obj = "Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post.",
}
T[971] = {
  title = "Sapere negli Abissi",
  desc = "Forse lo sai già: colleziono sapere. Sapere antico. Sapere potente. Sapere che apre porte, e sapere che può risvegliare Those Who Sleep.$B$BSi dice che in fondo ai Blackfathom Deeps, ad Ashenvale, ci sia un antico frammento di sapere: il Lorgalis Manuscript. Quel luogo è l'antica dimora di elfi morti da tempo, elfi che avevano un grande sapere prima che la loro città cadesse in rovina.$B$BVa' a cercare il manoscritto nei Blackfathom Deeps. Se lo farai, non lo dimenticherò. Nemmeno dopo ... la fine dei giorni.",
  obj = "Porta il Lorgalis Manuscript a Gerrig Bonegrip nella Forlorn Cavern di Ironforge.",
  progress = "La strada fino ad Ashenvale è lunga, e il compito che ti aspetta non è facile. Ma se mi porti il manoscritto, $N... allora la ricompensa sarà grande.",
  reward = "Hai trovato il manoscritto! Che giorno felice! Ne faremo delle copie e le faremo girare, e così i miei fratelli e le mie sorelle conosceranno finalmente l'antico sapere di Lorgalis!$B$BCi rendi un servizio più prezioso di quanto immagini, $N. Spero però che questo dono ti mostri quanta gratitudine riserviamo ai nostri alleati.",
  en_title = "Knowledge in the Deeps",
  en_obj = "Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge.",
}
T[972] = {
  title = "Water Sapta",
  reward = "Prendi la water sapta e va' a cercare la pozza d'acqua corrotta a Silverpine, $N. Confido molto nelle tue capacità.",
  en_title = "Water Sapta",
}
T[973] = {
  title = "La Tower of Althalaxx",
  desc = "Ilkrud Magthrull. Sì, so chi è. È un potente stregone orco e vive al Fire Scar Shrine, un luogo di grande malvagità nel sud-ovest di Ashenvale.$B$BFino a oggi non è stato che una seccatura, e l'ho lasciato perdere, ma a quanto pare è giunta la sua ora.",
  obj = "Porta l'Ilkrud Magthrull's Tome a Delgren the Purifier, a Maestra's Post.",
  progress = "Mi sembri un po' $Gscosso:scossa;, $N. Tutto bene?",
  reward = "Oggi hai fatto una grande cosa, $N. Hai affrontato uno stregone tanto potente, e dovresti andarne molto $Gfiero:fiera;.$B$BOra vediamo cosa ci possono insegnare gli scritti di Ilkrud.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post.",
}
T[974] = {
  title = "Trovare la Fonte",
  desc = "Le sorgenti termali qui intorno per me sono un mistero. Da dove viene il calore?$B$BSono così vicine a Fire Plume Ridge che mi chiedo se il vulcano non c'entri qualcosa. Ho costruito un termometro per misurarne le temperature, e vorrei scoprire qual è il punto più caldo. Misura in gradi Kraklenheit!$B$BEcco, prendilo e misura la temperatura sul rilievo ogni volta che vedi un punto caldo!",
  obj = "Krakle in Un'Goro Crater vuole che tu trovi la zona più calda di Fire Plume Ridge.$B$BOgni volta che trovi un punto caldo, fai clic destro sul termometro per controllare la temperatura. Continua a cercare finché non trovi il più caldo.",
  progress = "Ci andrei io stesso, ma... gli elementali del fuoco laggiù mi fanno un po' paura!",
  reward = "Sì, la correlazione fra la temperatura del vulcano e le sorgenti termali si vede proprio. Dovrò ricontrollare le equazioni per essere sicuro che siano esatte, ma pare che la distanza e la velocità con cui si trasmette il calore... Mmm...",
}
T[975] = {
  title = "Cache of Mau'ari",
  desc = "Allora, prima che ti do questo amuleto, è meglio che ti spiego come si usa.$B$BSe lo porti con te, vedrai che le creature che combatti lasceranno cadere certi oggetti. Se non ce l'hai addosso, quegli oggetti non li troverai. Capito?$B$BSono oggetti speciali, e li riconosci dal nome — si chiamano E'ko. Se ne trovi, portali alla vecchia Mau'ari, che lei ti dà una mano.$B$BTu aspetta qui, intanto che ti preparo l'amuleto.",
  obj = "Parla di nuovo con Witch Doctor Mau'ari tra un momento per ricevere il lucky charm.",
  reward = "Ecco qua, $N. Ricorda che devi portarlo con te. Perché non torni nelle terre selvagge a vedere cosa trovi là fuori?",
}
T[976] = {
  title = "Rifornimenti per Auberdine",
  desc = "Delgren mi ha chiesto di consegnare messaggi e rifornimenti a Sentinel Starbreeze ad Auberdine, ma non me la sento di partire da solo. Nella foresta si aggirano nemici pericolosi, e non voglio rischiare che le provviste e le informazioni finiscano in mani sbagliate.$B$BSe tu e qualcun altro poteste farmi da scorta, potrei partire subito. Con la vostra protezione, sono certo che porteremo il carico sano e salvo ad Auberdine.",
  obj = "Parla con Delgren the Purifier a Maestra's Post dopo aver scortato Feero sano e salvo attraverso Ashenvale Forest.",
  progress = "Le Sentinelle hanno un gran bisogno di rifornimenti per rafforzare le posizioni a Darkshore.",
  reward = "Oggi hai fatto un ottimo lavoro, $C. Gli aiuti che abbiamo inviato ad Auberdine serviranno subito per affrontare le minacce malvagie che infestano la foresta.$B$BAccetta questi doni, con i miei più sentiti ringraziamenti.",
  en_title = "Supplies to Auberdine",
  en_obj = "Speak with Delgren the Purifier at Maestra's Post after seeing Feero safely through Ashenvale Forest.",
}
T[977] = {
  title = "Siamo Arrivati, Yeti?",
  desc = "Adesso che ho quello che mi serve per coprire le parti meccaniche che si muovono, mi manca solo un'altra cosa. Be', anzi due. Due corni!$B$BGli ice thistle patriarchs e le matriarche hanno i corni più grandi, quindi è ovvio che voglio quelli. Quel tipo di yeti vive in una grotta a sud-est, e ce ne sono un sacco: non dovresti avere problemi a trovarli.$B$BE ricorda, voglio solo i più belli — niente corni rovinati o rotti, per favore!",
  obj = "Raccogli 2 Pristine Yeti Horns per Umi Rumplesnicker a Everlook.",
  progress = "Ho quasi finito di attaccare la pelliccia, $N. Torna presto con quei corni, per favore!",
  reward = "Non vedo l'ora di farlo vedere ai miei amici! Adesso aspetta un attimo che attacco questi...$B$BPerfetto!",
}
T[978] = {
  title = "Wildkin Toccati dalla Luna",
  desc = "Le Wildkin feathers delle Hinterlands sembrano contenere tracce di proprietà magiche. Questi poteri... a quanto pare le creature non li usano: sembrano piuttosto innati nella specie — parte della loro stessa essenza.$B$BDurante i miei studi ho sentito dire che una numerosa popolazione di wildkin abita le terre innevate di Winterspring. Che anche loro abbiano gli stessi poteri? Ti prego, aiutami a trovare una risposta, $N. Va' a Winterspring e raccogli le penne cadute a terra, poi torna da me.",
  obj = "Raccogli 10 Moontouched Feathers a Winterspring, poi torna da Erelas Ambersky a Rut'theran Village.",
  progress = "Da dove potrebbero avere origine questi poteri? Credo che siamo sulla strada giusta per trovare la risposta, $N.",
  reward = "Ora posso confrontare le penne... Vediamo...",
}
T[979] = {
  title = "Trova Ranshalla",
  desc = "Sì, sì, queste penne sembrano racchiudere lo stesso incantesimo che avevo notato in precedenza... Anche se non so con certezza cosa potremmo trovare, ti esorto a continuare a cercare risposte, $N.$B$BUna mia collega è andata da poco a Winterspring per osservare i wildkin del posto nel loro habitat. Perché non la raggiungi e vedi cosa ha scoperto?",
  obj = "Trova Ranshalla nella zona orientale di Winterspring.",
  reward = "Ciao! Ti ha mandato Erelas? Ottimo, mi stavo giusto preparando a salire alle grotte, e un po' di compagnia non mi dispiacerebbe.",
}
T[980] = {
  title = "Le Nuove Sorgenti",
  desc = "Allora, ho sentito dire che ci sono altre sorgenti termali in un posto che si chiama Winterspring, molto più a nord. La cosa strana è che lì vicino non ci sono vulcani da nessuna parte. Interessante, lo so.$B$BBe', se vuoi saperne di più, dovresti andare a Winterspring a parlare con una mia amica, Donova Snowden: in questo momento si trova vicino alle sorgenti termali.$B$BGrazie ancora per l'aiuto con il termometro! A dopo!",
  obj = "Viaggia fino a Winterspring e parla con Donova Snowden.",
  reward = "Ciao, $N. Sì, Krakle ti ha detto il vero...",
}
T[981] = {
  title = "La Tower of Althalaxx",
  desc = "Dopo tutto il lavoro che hai fatto, meriti di essere $Gricompensato:ricompensata; come si deve. Torna da Delgren e digli che Athrikus Narassin giace immobile per mano tua e che il Culto del Dark Strand è stato sconfitto e disperso.",
  obj = "Parla con Delgren the Purifier a Maestra's Post.",
  reward = "Sapevo che saresti $Gstato:stata; all'altezza del compito, $N.$B$BSento che ti aspettano grandi imprese e che raddrizzerai molti dei torti che affliggono le nostre terre. Porta con te le mie benedizioni, $N, e anche questo dono.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Talk to Delgren the Purifier at Maestra's Post.",
}
T[992] = {
  title = "Rilevamento Idrico di Gadgetzan",
  desc = "Se ti interessa, alla Gadgetzan Water Company c'è un posto libero da $Gispettore:ispettrice; apprendista, a tempo determinato!$B$BI nomadi si stanno prendendo tutti i nostri pozzi, quindi dobbiamo sfruttare altre fonti d'acqua ancora libere! Nel deserto l'acqua c'è, ma tocca solo a chi è abbastanza furbo da rilevarla per primo.$B$BPrendi questo aggeggio da rabdomante e va' a prelevare un campione d'acqua dalla pozza vicino al Sandsorrow Watch, proprio sotto gli occhi dei troll della zona. Quando hai finito, riportami l'aggeggio usato!",
  obj = "Usa l'untapped dowsing widget vicino alla pozza d'acqua presso Sandsorrow Watch. Dopo aver raccolto il campione, riporta la tapped dowsing widget a Senior Surveyor Fizzledowser a Gadgetzan.",
  progress = "$GBentornato:Bentornata;, $GIspettore Apprendista:Ispettrice Apprendista; $N! Allora, l'incarico l'hai già sbrigato?",
  reward = "E questo che cos'è? Ti ha teso un agguato una specie di bestiaccia strisciante dal brutto mojo? Oh, per la Gadgetzan Water Company questo non promette niente di buono, proprio no...$B$BForse avrei dovuto parlarti delle segnalazioni che arrivano su certe creature assurde, simili a insetti, che sembrano succhiare tutta l'acqua del deserto. All'inizio pensavo fosse solo una frottola: con i nomadi abbiamo già abbastanza guai, e credevo fosse l'ennesimo dei loro scherzi. Be', almeno adesso lo sappiamo!",
}
T[994] = {
  title = "Fuga con la Forza",
  desc = "D'accordo, $N, useremo la forza. Andiamocene da qui appena sei $Gpronto:pronta;. Ci apriremo un varco combattendo fino alla strada — Grimclaw dovrebbe essere ancora lì. Una volta arrivati, ci separeremo.$B$BTerenthis vorrà sentire subito la tua versione dei fatti, quindi, quando saremo fuori, dirigiti ad Auberdine.",
  obj = "Proteggi Volcor finché non raggiungi la strada, poi parla con Terenthis ad Auberdine.",
  reward = "$N! Sono lieto che tu sia $Gtornato:tornata; dopo aver portato a termine l'impresa. Aiutando Volcor mi hai dato fiducia: ora credo che possiamo superare le sfide che abbiamo davanti qui a Darkshore e oltre.",
  en_title = "Escape Through Force",
  en_obj = "Protect Volcor until you reach the road, then speak to Terenthis in Auberdine.",
}
T[996] = {
  title = "Corrupted Windblossom",
  progress = "Hai trovato quella che sembra una pianta di windblossom, ma malata e corrotta. Le bacche che ne pendono sembrano marce e velenose: la pianta ha un disperato bisogno di cure per tornare com'era.",
  reward = "Applichi due unguenti per piante Cenarion al windblossom, e la pianta comincia subito a perdere la forma corrotta. Torna a fiorire, rigogliosa e sana.",
}
T[998] = {
  title = "Corrupted Windblossom",
  progress = "Hai trovato quella che sembra una pianta di windblossom, ma malata e corrotta. Le bacche che ne pendono sembrano marce e velenose: la pianta ha un disperato bisogno di cure per tornare com'era.",
  reward = "Applichi due unguenti per piante Cenarion al windblossom, e la pianta comincia subito a perdere la forma corrotta. Torna a fiorire, rigogliosa e sana.",
}
T[999] = {
  title = "Quando i Sogni Diventano Incubi",
}
T[1000] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone valide e in forze che lo aiutino a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una terra desolata e proibita, piena di pericoli inimmaginabili, e il Circolo ha bisogno di rappresentanti volenterosi e integri che agiscano in suo nome.$B$BChiunque sia interessato chieda udienza al Cenarion Circle. Per maggiori informazioni, parlate con Arch Druid Hamuul Runetotem sull'Elder's Rise of Thunder Bluff!",
  obj = "Parla con Arch Druid Hamuul Runetotem su Elder Rise di Thunder Bluff dell'appello del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Salute, $C.$B$BMi fa piacere vedere quelli come te prendersi a cuore il benessere della natura; la fama delle tue grandi imprese ti precede, e qui sei $Gil benvenuto:la benvenuta;. Ora che sei qui, confido che il Cenarion Circle riceverà l'aiuto di cui ha bisogno.$B$BIl nostro legame con il Cenarion Circle di Moonglade supera le divisioni di razza e di politica. Ricordalo mentre lavori per il Circolo, e non sbaglierai.",
  en_title = "The New Frontier",
  en_obj = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.",
}
T[1004] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone valide e in forze che lo aiutino a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una terra desolata e proibita, piena di pericoli inimmaginabili, e il Circolo ha bisogno di rappresentanti volenterosi e integri che agiscano in suo nome.$B$BChiunque sia interessato chieda udienza al Cenarion Circle. Per maggiori informazioni, parlate con Arch Druid Hamuul Runetotem sull'Elder's Rise of Thunder Bluff!",
  obj = "Parla con Arch Druid Hamuul Runetotem su Elder Rise di Thunder Bluff dell'appello del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Salute, $C.$B$BMi fa piacere vedere quelli come te prendersi a cuore il benessere della natura; la fama delle tue grandi imprese ti precede, e qui sei $Gil benvenuto:la benvenuta;. Ora che sei qui, confido che il Cenarion Circle riceverà l'aiuto di cui ha bisogno.$B$BIl nostro legame con il Cenarion Circle di Moonglade supera le divisioni di razza e di politica. Ricordalo mentre lavori per il Circolo, e non sbaglierai.",
}
T[1005] = {
  title = "Ciò Che si Cela Oltre",
}
T[1006] = {
  title = "Ciò Che si Trova Oltre",
}
T[1009] = {
  title = "Ruuzel",
  desc = "Temo che i segreti dell'ancient statuette resteranno nascosti per sempre, se non trovi la chiave della sua antica serratura.$B$BLa chiave è un anello, il Ring of Zoram, che apparteneva ai sovrani di questa città prima che le onde della Separazione la sommergessero.$B$BL'anello è rimasto perduto per anni, ma di recente l'hanno ritrovato i naga.$B$BIl loro capo, Ruuzel, vive su un'isola all'estremità settentrionale di Zoram. Ti prego, $N, recupera l'anello per me!",
  obj = "Porta il Ring of Zoram a Talen vicino alla Zoram Strand.",
  progress = "Il Ring of Zoram, si dice, è la chiave di ogni serratura della città. Ce l'hai, $N?",
  reward = "Hai trovato l'anello! Grazie, $N. Accetta questo come ricompensa, ti prego, e sappi che ricorderò per sempre le tue imprese di oggi.",
  en_title = "Ruuzel",
  en_obj = "Bring the Ring of Zoram to Talen near the Zoram Strand.",
}
T[1011] = {
  title = "Malattie dei Forsaken",
  desc = "I Forsaken, il braccio non morto dell'Orda, si sono insinuati ad Ashenvale e si aggirano fra le nostre rovine e i nostri tumuli. Crediamo che vogliano diffondere malattie nelle terre degli elfi della notte. Dobbiamo averne la conferma!$B$BI Forsaken hanno un accampamento a sud di qui, vicino alla Dor'Danil Barrow Den: lì preparano veleni e malattie e li chiudono in bottiglia. Apriti la strada combattendo fin dentro l'accampamento, ruba una bottle of disease e portamela. La analizzerò e scoprirò a cosa serve.",
  obj = "Porta una Bottle of Disease a Kayneth Stillwind a Forest Song.",
  progress = "Hai trovato l'accampamento, $N? Hai con te una bottle of disease?",
  reward = "Molto bene, $N. E ora... analizzando il contenuto di questa bottiglia scopriremo che intenzioni hanno i Forsaken!",
  en_title = "Forsaken Diseases",
  en_obj = "Bring a Bottle of Disease to Kayneth Stillwind in Forest Song.",
}
T[1012] = {
  title = "Druidi Impazziti",
  desc = "Mentre combattevo contro i veleni dei Forsaken, ho avuto una visione. Ho visto i druidi della Tana dei Tumuli Dor'danil, avvelenati... assassinati dai non morti! Ora vagano come fantasmi, strappati ai loro corpi e impazziti.$B$BPerché un giorno i loro spiriti possano trovare pace, devi entrare nella Tana dei Tumuli Dor'danil e distruggere quelli che un tempo ne erano i grandi capi: Taneel Darkwood, Uthil Mooncall e Mavoris Cloudsbreak.$B$BFallo, e poi torna da me.",
  obj = "Uccidi i druidi: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; poi torna da Kayneth Stillwind a Forest Song.",
  progress = "L'angoscia dei druidi di Dor'danil mi tormenta ancora i sogni, $N. Devi distruggere i loro capi!",
  reward = "Ho sentito attenuarsi l'angoscia dei Dor'danil Barrows e ho capito che avevi portato a termine il compito.$B$BÈ stato un lavoro ingrato, $N, perché gli spiriti che hai distrutto erano solo vittime della malvagità dei Forsaken. Ma ora che non ci sono più, speriamo che gli altri spiriti impazziti trovino pace.",
  en_title = "Insane Druids",
  en_obj = "Kill the druids: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; then return to Kayneth Stillwind in Forest Song.",
}
T[1013] = {
  title = "The Book of Ur",
  desc = "$N, nello Shadowfang Keep è custodito un libro, The Book of Ur, che sarebbe un pezzo pregiato della mia collezione. Prima che arrivasse lo Scourge, Ur era un grande mago di Dalaran; i suoi studi su altri mondi valgono molto per... certe persone fra i Forsaken.$B$BEntra nello Shadowfang Keep e trova il libro. Portamelo e parlerò dei tuoi servigi alla nostra Dama Oscura...",
  obj = "Porta The Book of Ur a Keeper Bel'dugur presso Apothecarium nell'Undercity.",
  progress = "Hai trovato il libro, $N?",
  reward = "Molto bene. Questo libro sarà una bella aggiunta alle mie raccolte sulle opere di Ur. Sapeva tanto, ma la coscienza lo teneva lontano dal vero potere. Così, quando è arrivato lo Scourge a mettere alla prova la sua forza, ha ceduto.$B$BNoi Forsaken non possiamo permetterci una debolezza simile, se vogliamo sopravvivere...$B$B...Se vogliamo conquistare.",
  en_title = "The Book of Ur",
  en_obj = "Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.",
}
T[1014] = {
  title = "Arugal Deve Morire",
  desc = "Arugal è ancora allo Shadowfang Keep, e non potremo rivendicare Silverpine come roccaforte strategica per la Dama Oscura finché Arugal non sarà ucciso.$B$BAlla sua magia ci penso io, $N: farò in modo che venga estirpata. Ma il compito di dare ad Arugal la morte che si merita lo lascio a te.$B$BVa' allo Shadowfang Keep e metti fine una volta per tutte agli immondi incantesimi di Arugal. Portami la testa di quel mago spregevole!",
  obj = "Uccidi Arugal e porta la sua testa a Dalar Dawnweaver al Sepulcher.",
  progress = "Morto Arugal, potremo rafforzare il dominio della Dama Oscura su Lordaeron.",
  reward = "Finalmente la Silverpine Forest è libera dalla morsa di quel miserabile di Arugal. Hai reso un grande servigio alla Dama Oscura, $N, e la tua tenacia sarà ricompensata.",
  en_title = "Arugal Must Die",
  en_obj = "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.",
}
T[1015] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone valide e in forze che lo aiutino a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una terra desolata e proibita, piena di pericoli inimmaginabili, e il Circolo ha bisogno di rappresentanti volenterosi e integri che agiscano in suo nome.$B$BChiunque sia interessato chieda udienza al Cenarion Circle. Per maggiori informazioni, parlate con l'Arcidruido di Darnassus, Fandral Staghelm!",
  obj = "Parla con Arch Druid Fandral Staghelm a Cenarion Enclave of Darnassus dell'appello del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Cosa ti fa pensare che io voglia farmi importunare da quelli come te, $C? Aspetta — adesso interrompo gli importanti compiti che svolgo ogni giorno, così posso aiutarti a scovare un oggettino da qualche parte. Ma certo, il benessere di Darnassus — anzi, di tutto Teldrassil — deve passare in secondo piano rispetto a cianfrusaglia da aggiungere alla tua collezione.$B$BQuegli sciocchi di Moonglade mi fanno perdere tempo con le loro richieste d'aiuto, e ora devo sopportare anche questo?",
  en_title = "The New Frontier",
  en_obj = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.",
}
T[1016] = {
  title = "Polsiere Elementali",
  desc = "Prendi questa divining scroll — può scoprire chi ha creato questi elementali. Ma per concentrarne la magia ti servirà come reagente qualcosa preso da loro — le polsiere dovrebbero andare benissimo.$B$BDovrebbero bastare alcune polsiere intatte di queste creature. Le altre a noi non servono a nulla, ma se vuoi venderle, forse un mercante te le pagherà qualcosa. Quando avrai quelle intatte, prova a usare la pergamena, poi torna da me con i risultati e vedremo come procedere.",
  obj = "Raccogli 5 Intact Elemental Bracers e usa la Divining Scroll su di esse. Poi porta la Divined Scroll a Sentinel Velene Starstrike a Silverwind Refuge.",
  progress = "Per uccidere gli elementali devi distruggerne le polsiere, quindi probabilmente non sarà facile trovare proprio quelle che contengono le informazioni che servono alla divining scroll. Puoi fare scambi con altri per procurarti quelle che ti mancano, o forse la pergamena della profezia ce l'hai già?",
  reward = "Ben fatto, $N. Con questo dovremmo avere le informazioni che ci servono per scoprire il colpevole. Che ne diresti di eliminare il mago che riempie le nostre pozze di elementali corrotti? Già la corruzione di Ashenvale e delle terre più in là basta a rivoltarmi lo stomaco — che un mago si adoperi per distruggerle ancora di più mi disgusta oltre ogni limite. Gliela faremo pagare.",
  en_title = "Elemental Bracers",
  en_obj = "Collect 5 Intact Elemental Bracers and use the Divining Scroll on them. Afterwards, bring the Divined Scroll to Sentinel Velene Starstrike at the Silverwind Refuge.",
}
T[1017] = {
  title = "Mago Evocatore",
  desc = "Nelle Barrens c'è un solo mago non morto capace di corrompere così tanti water elementals, ed è anche l'unico abbastanza stupido da provarci. Sarilus Foulborne se ne starà seduto in cima al Dreadmist Peak a ridere di me.$B$B$N, devi entrare in territorio nemico e distruggere questo farabutto. Ne ho abbastanza della sua idiozia, e dobbiamo fargli vedere cosa succede a chi dà fastidio alle Sentinelle.$B$BDistruggilo e portami la sua testa. Ma sta' in guardia: l'Orda potrebbe tenerti d'occhio.",
  obj = "Uccidi Sarilus Foulborne e porta la sua testa a Sentinel Velene Starstrike a Silverwind Refuge.",
  progress = "È fatta? Sarilus Foulborne è morto?",
  reward = "Ora vedo quel sorriso ripugnante sparito per sempre dalla sua faccia. Hai fatto un ottimo lavoro, $N. Prendi questa Light of Elune e bevine quando tutto ti sembrerà perduto e la morte sarà vicina. Se la Dea vorrà, potrebbe salvarti.",
  en_title = "Mage Summoner",
  en_obj = "Slay Sarilus Foulborne and bring his head to Sentinel Velene Starstrike in Silverwind Refuge.",
}
T[1018] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone valide e in forze che lo aiutino a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una terra desolata e proibita, piena di pericoli inimmaginabili, e il Circolo ha bisogno di rappresentanti volenterosi e integri che agiscano in suo nome.$B$BChiunque sia interessato chieda udienza al Cenarion Circle. Per maggiori informazioni, parlate con Arch Druid Hamuul Runetotem sull'Elder's Rise of Thunder Bluff!",
  obj = "Parla con Arch Druid Hamuul Runetotem su Elder Rise di Thunder Bluff dell'appello del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Salute, $C.$B$BMi fa piacere vedere quelli come te prendersi a cuore il benessere della natura; la fama delle tue grandi imprese ti precede, e qui sei $Gil benvenuto:la benvenuta;. Ora che sei qui, confido che il Cenarion Circle riceverà l'aiuto di cui ha bisogno.$B$BIl nostro legame con il Cenarion Circle di Moonglade supera le divisioni di razza e di politica. Ricordalo mentre lavori per il Circolo, e non sbaglierai.",
}
T[1019] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone valide e in forze che lo aiutino a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una terra desolata e proibita, piena di pericoli inimmaginabili, e il Circolo ha bisogno di rappresentanti volenterosi e integri che agiscano in suo nome.$B$BChiunque sia interessato chieda udienza al Cenarion Circle. Per maggiori informazioni, parlate con l'Arcidruido di Darnassus, Fandral Staghelm!",
  obj = "Parla con Arch Druid Fandral Staghelm a Cenarion Enclave of Darnassus dell'appello del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Cosa ti fa pensare che io voglia farmi importunare da quelli come te, $C? Aspetta — adesso interrompo gli importanti compiti che svolgo ogni giorno, così posso aiutarti a scovare un aggeggio da qualche parte. Ma certo, il benessere di Darnassus — anzi, di tutto Teldrassil — deve passare in secondo piano rispetto a un ninnolo da aggiungere alla tua collezione.$B$BQuegli sciocchi di Moonglade mi fanno perdere tempo con le loro richieste d'aiuto, e ora devo sopportare anche questo?",
}
T[1021] = {
  title = "Satiro Infame! Driadi in Pericolo!",
  desc = "Ascolta, non so chi tu sia, ma mi serve il tuo aiuto. Le mie sorelle sono andate a riprendere il Branch of Cenarius al satiro e avevano detto che sarebbero tornate presto. Invece sono passati due giorni interi!$B$B$N, devi trovarle! Cercavano le rovine di un tempio degli elfi della notte, a Xavian, a nordest. Non so cosa pensare. Cerca Anilia: era lei a guidare la ricerca.",
  obj = "Trova Anilia a Xavian.",
  reward = "A vedere lo squarcio che ha sul fianco, Anilia è in punto di morte.",
  en_title = "Vile Satyr! Dryads in Danger!",
  en_obj = "Find Anilia in Xavian.",
}
T[1022] = {
  title = "The Howling Vale",
  desc = "Abbiamo speso molte risorse e molte energie per scacciare dal Felwood, a nord, i demoni rimasti, ma con pochi successi. Siamo riusciti a tenere lontana da Ashenvale gran parte della presenza demoniaca.$B$BA nord, vicino al confine con il Felwood, misteriosi uomini lupo hanno invaso il santuario in rovina di Mel'Thandris, e i loro richiami agghiaccianti hanno dato alla zona il nome di Howling Vale. Il Tome of Mel'Thandris, custodito nel santuario, potrebbe far luce sul motivo per cui sono arrivati questi uomini lupo.",
  obj = "Va' nell'Howling Vale e studia il Tome of Mel'Thandris, poi torna da Sentinel Melyria Frostshadow a Shrine of Aessina.",
  progress = "Il tomo del santuario è un oggetto misterioso: non è un libro nel senso comune della parola. Le sue pagine, benedette da Mel'Thandris in persona, registrano gli eventi importanti.$B$BNon è facile da spiegare. Se andrai al santuario, capirai.",
  reward = "Il Tome of Mel'Thandris funziona in modi strani. Gli eventi che registra, quelli che mostra... Nessuno capisce davvero perché faccia quello che fa.$B$BIn ogni caso, è chiaro che quello che ha ricevuto Priestess Starsong — questa Falce di Elune — va esaminato più a fondo.",
  en_title = "The Howling Vale",
  en_obj = "Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at Forest Song.",
}
T[1023] = {
  title = "La Purificazione di Raene",
  desc = "Frugando fra gli averi di Teronis, trovi un diario ancora in buono stato.$B$BLo prendi e lasci il cadavere di Teronis così com'è.$B$BOra non ti resta che trovare la gemma che Teronis cercava. Raene ha detto che si trovava da queste parti. Forse ce l'hanno i murlocs...",
  obj = "Trova la Glowing Gem e torna da Raene Wolfrunner ad Astranaar con il Teronis' Journal.",
  progress = "Ah, $Gbentornato:bentornata;, $N.",
  reward = "Che cosa terribile, $N. Teronis è morto?!$B$BVerrà il tempo del lutto, ma per ora dobbiamo concentrarci su quello che c'è da fare. Manderò al più presto alcune Sentinelle a recuperare il corpo di Teronis.$B$BHai il diario di Teronis e la gemma che cercava. Credi di poter portare a termine il suo compito? Riposerei molto più serena sapendo che non è morto invano.",
  en_title = "Raene's Cleansing",
  en_obj = "Find the Glowing Gem and return to Raene Wolfrunner in Astranaar with Teronis' Journal.",
}
T[1024] = {
  title = "La Purificazione di Raene",
  desc = "Le ricerche dovrai farle da $Gsolo:sola;, ma a giudicare dagli appunti di Teronis sembra che adesso tu debba trovare gli altri pezzi della verga che ha creato Dartol. Io partirei dal pozzo lunare a est dell'Iris Lake. Quando sei $Gpronto:pronta;, segui la strada e svolta a nord all'altezza della piccola area di sosta che trovi sulla sinistra.$B$BLì c'è una driade, Shael'dryn, che saprà guidarti meglio di me. Va' a cercarla.$B$BTieni con te la gemma — a Shael'dryn servirà per aiutarti a ricreare la verga.",
  obj = "Trova Shael'dryn al pozzo lunare a nord-est.",
  progress = "Ciao. Come stai?",
  reward = "Oh, ti manda Raene? Allora dev'essere una faccenda seria davvero. Cosa posso fare per te?",
  en_title = "Raene's Cleansing",
  en_obj = "Find Shael'dryn at the moonwell to the northeast.",
}
T[1025] = {
  title = "Una Difesa Aggressiva",
  desc = "Se vuoi mettere alla prova le tue abilità, prima di andare al pozzo lunare ho un altro compito per te, che aiuterà la gente di Ashenvale.$B$BSulla strada verso est, prima del Falfarren River, i furbolgs assalgono i viaggiatori. Le loro menti tormentate si nutrono di paura e saziano la fame con il sangue degli innocenti.$B$BAiuta le Sentinelle a proteggere queste terre: riserva a quei mostri la stessa pietà che hanno mostrato alla nostra gente.$B$BCredo che abbiano gli accampamenti a sud della strada... fai attenzione.",
  obj = "Uccidi 1 Den Watcher, 2 Ursas, 10 Totemics e 12 Guerrieri della tribù Foulweald, poi torna da Raene Wolfrunner ad Astranaar.",
  progress = "Non siamo sempre stati nemici dei furbolg, $N. Ma i tempi cambiano, e qui, in questi boschi oscuri, il tempo della pace è finito.",
  reward = "Hai lavorato bene, $N. Grazie.",
  en_title = "An Aggressive Defense",
  en_obj = "Kill 1 Den Watcher, 2 Ursas, 10 Totemics, and 12 Warriors of the Foulweald tribe, and then return to Raene Wolfrunner in Astranaar.",
}
T[1026] = {
  title = "La Purificazione di Raene",
  desc = "Vorrei tanto che mi portassi notizie migliori.$B$BRaene ha ragione, conosco la creazione di Dartol e i treants della zona — o almeno, un tempo li conoscevo. Adesso sono corrotti, con la natura distorta.$B$BSe stai cercando il prossimo pezzo della verga, dovrai trovare la chiave che apre lo scrigno in cui si trova.$B$BLa wooden key ce l'ha uno dei treants a nord-est di qui, vicino al Felwood. Quando l'avrai presa, cerca una piccola radura a ovest della strada, vicino al confine con il Felwood... lo scrigno dovrebbe essere nascosto lì intorno.",
  obj = "Trova la Wooden Key e un pezzo della Verga di Dartol prima di tornare da Shael'dryn al pozzo lunare.",
  progress = "Mi addolora tanto che i treants siano stati corrotti. Vorrei poter fare di più per aiutarli.",
  reward = "Sono felice che tu sia $Gtornato:tornata;, $N.",
  en_title = "Raene's Cleansing",
  en_obj = "Find the Wooden Key and a piece of Dartol's Rod before returning to Shael'dryn at the moonwell.",
}
T[1027] = {
  title = "La Purificazione di Raene",
  desc = "L'ultimo pezzo della verga è stato affidato in custodia ai druidi di Dor'danil, e dove l'abbiano nascosto non ne ho idea. Mi dispiace di non poterti aiutare di più.$B$BPosso solo dirti di seguire la strada verso le Barrens. I druidi si erano rifugiati a est di quella strada, ma non ti saranno di grande aiuto: sono stati uccisi da poco... e non mi piace pensarci troppo.$B$BQuando avrai trovato l'ultimo pezzo, portamelo e ti aiuterò a ricostruire la verga.",
  obj = "Trova l'ultimo pezzo della Verga di Dartol e torna da Shael'dryn al pozzo lunare.",
  progress = "Allora, $N, hai trovato l'ultimo pezzo della verga?",
  reward = "Hai trovato l'ultimo pezzo? Splendido, per te... e per Raene.$B$BOra direi che dobbiamo pensare a ripararla, non credi?",
  en_title = "Raene's Cleansing",
  en_obj = "Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell.",
}
T[1028] = {
  title = "La Purificazione di Raene",
  desc = "Ecco la verga completa, $N. Rimetterla insieme è stato facile... il difficile sarà trovare il santuario che ha il potere di ricaricarla.$B$BCon un po' di concentrazione e d'impegno non dovrebbe essere troppo difficile per qualcuno come te, che ha già fatto tanto.$B$BVa' a sud-est di qui — i sentieri sono pochissimi, quindi fa' attenzione — e tieni gli occhi verso nord. Il santuario è nascosto fra le montagne intorno a questa radura.$B$BUna volta lì, metti la verga nel santuario... il resto è magia. Eheh.",
  obj = "Trova il santuario nascosto e incanta di nuovo la Verga di Dartol.",
  progress = "Percepisci una forza sottile ma potente dentro il santuario e negli alberi tutt'intorno.$B$BCominci a mettere la verga nel santuario: intorno a te si diffonde un leggero ronzio, mentre il santuario inizia a risplendere...",
  reward = "Quando il bagliore si spegne, vedi nella vasca del santuario la verga, di nuovo incantata.",
  en_title = "Raene's Cleansing",
  en_obj = "Find the hidden shrine and re-enchant Dartol's Rod.",
}
T[1029] = {
  title = "La Purificazione di Raene",
  desc = "Ti consiglio di cercare Raene e dirle che la verga è pronta. Sono sicura che saprà indicarti la prossima mossa.$B$BBuona fortuna, $N.",
  obj = "Torna da Raene Wolfrunner ad Astranaar.",
  reward = "Hai ricreato la verga che Teronis era partito a cercare? È una notizia splendida.$B$BTeronis sarebbe fiero di vedere che la sua missione va avanti anche dopo la sua tragica morte.",
  en_title = "Raene's Cleansing",
  en_obj = "Return to Raene Wolfrunner in Astranaar.",
}
T[1030] = {
  title = "La Purificazione di Raene",
  desc = "Ahimè, non so con certezza cosa avesse in mente di fare dopo.$B$BSe quello che diceva sul potere della verga era vero, ti permetterà di prendere tutt'altra forma. Quale, non lo so.$B$BForse voleva servirsi dei suoi poteri per avvicinarsi ai furbolgs contaminati, ma se non fosse stato attento anche le creature non corrotte lo avrebbero massacrato. Trasformato dalla verga, Dartol avrebbe dovuto parlare con un furbolg rimasto al riparo dagli effetti del Fel Moss.$B$BIo comincerei a cercare a sud-est del Mystral Lake.",
  obj = "Trova un furbolg non corrotto e parlagli usando il potere della Dartol's Rod of Transformation.",
  reward = "Sì, sì... sei $Guno:una; della mia specie, ma ancora $Gintegro:integra;. Ancora $Gpuro:pura;.$B$BNon so come tu abbia fatto a sfuggire alle atrocità che gli elfi della notte hanno inflitto al nostro popolo, ma sono lieto di sapere di non essere più solo.$B$BOra la corruzione scorre nelle vene della nostra gente, giovane, e ce l'hanno portata i superbi elfi della notte. Sono stati loro a fare questo al nostro popolo... È per colpa loro che sono stato cacciato dalla mia tribù.$B$BDi notte vedo ancora i falò ardere nell'oscurità.",
  en_title = "Raene's Cleansing",
  en_obj = "Find an uncorrupted furbolg, and using the power of Dartol's Rod of Transformation, speak to him.",
}
T[1031] = {
  title = "Il Branch of Cenarius",
  desc = "Anilia ti mette le mani sulle spalle e ti tira a sé. Col fiato corto indica l'arco a nord, poi chiude gli occhi ed esala l'ultimo respiro, in un rantolo. \"L'ha preso... Geltharis...\" Sai in cuor tuo che l'ultimo desiderio di Anilia è rivedere il Branch of Cenarius nelle mani delle driadi.",
  obj = "Uccidi Geltharis e riporta il Branch of Cenarius a Illiyana a Shrine of Aessina.",
  progress = "Le hai trovate? Che cosa ha detto Anilia? Dov'è?",
  reward = "Anilia è morta? No... non può essere! Ieri stesso correvamo e giocavamo insieme nei boschi.$B$BQuei giorni, credo, sono finiti...",
  en_title = "The Branch of Cenarius",
  en_obj = "Kill Geltharis and return the Branch of Cenarius to Illiyana at Forest Song.",
}
T[1032] = {
  title = "Strage di Satiri!",
  desc = "Anilia non c'è più... non riesco a crederci. Nelle foreste giocavamo sempre insieme. Mi sento quasi... triste.$B$BSo io cosa potrebbe farmi stare meglio. Ti prego, uccidi i satiri che mi hanno portato via Anilia! Portami le loro corna a prova di quello che hai fatto e ti sarò grata per sempre.",
  obj = "Porta 16 Satyr Horns a Illiyana in Shrine of Aessina.",
  progress = "Aiutami a vendicare la morte di Anilia, ti prego.",
  reward = "Grazie, $R gentile. I tuoi sforzi danno gioia allo spirito di mia sorella.",
  en_title = "Satyr Slaying!",
  en_obj = "Bring 16 Satyr Horns to Illiyana in Forest Song.",
}
T[1033] = {
  title = "Elune's Tear",
  desc = "Speravo che la cura di Orendil salvasse Relara, ma temo che abbia solo rallentato la malattia di mia figlia. Ci serve una medicina più potente! Per fortuna Orendil mi ha parlato di altri rimedi da tentare se il primo non avesse funzionato.$B$BL'Elune's Tear è un tipo di pietra che si trova in un solo posto: l'isola sull'Iris Lake, a est di Astranaar. Orendil mi ha detto che laverà via la corruzione... ti prego, $N, portami l'Elune's Tear e prega che metta fine alla malattia di mia figlia!",
  obj = "Porta l'Elune's Tear a Pelturas ad Astranaar.",
  progress = "$N, hai trovato l'Iris Lake? Ce l'hai, la Lacrima?",
  reward = "Oh, l'hai trovata! Metterò la lacrima in uno stufato e pregherò che la guarisca.$B$BGrazie! Grazie, $N!",
  en_title = "Elune's Tear",
  en_obj = "Bring Elune's Tear to Pelturas in Astranaar.",
}
T[1034] = {
  title = "The Ruins of Stardust",
  desc = "L'Elune's Tear ha lavato via una parte della malattia di mia figlia. Gli incubi si sono attenuati, e ringrazio la dea per la sua benedizione. Ma... la febbre le infuria ancora dentro.$B$BOrendil mi ha parlato di una polvere gelata che si trova fra le Ruins of Stardust: forse farà calare la febbre a Relara. Raccoglinene un po' e poi, ti prego, torna da me.$B$BThe Ruins of Stardust sono a sud, $N. Che Elune affretti il tuo cammino.",
  obj = "Porta 5 Handfuls of Stardust a Pelturas ad Astranaar.",
  progress = "Hai già con te la Polvere di Stelle, $N?",
  reward = "Hai raccolto la polvere! Ne farò un impiastro — dovrebbe far scendere la febbre a Relara.$B$BGrazie ancora, $N. Senza il tuo aiuto mia figlia morirebbe di certo.",
  en_title = "The Ruins of Stardust",
  en_obj = "Bring 5 Handfuls of Stardust to Pelturas in Astranaar.",
}
T[1035] = {
  title = "Fallen Sky Lake",
  desc = "La febbre di Relara è passata, ma lei è ancora molto debole, e non credo che basterà il tempo a ridarle la forza che ha perso. Penso che ci vorrà il potere di una pietraluna.$B$BUn tempo andavamo a prendere le pietralune al Fallen Sky Lake, a sud-est... finché non sono arrivati gli Shadethickets.$B$BIl loro capo, uno Shadethicket Oracle, ha raccolto tutte le fallen moonstones e le custodisce gelosamente. Ora devi riprendere una pietraluna all'Oracolo.$B$BE temo che per riuscirci dovrai ucciderlo.",
  obj = "Recupera una Fallen Moonstone dallo Shadethicket Oracle, poi portala a Pelturas ad Astranaar.",
  progress = "Hai affrontato lo Shadethicket Oracle, $N? Se sì, ti prego, dammi la fallen moonstone. A Relara resta forza solo per pochi respiri ancora!",
  reward = "Oh, $N, hai salvato mia figlia! So che il potere della pietraluna le ridarà la forza!$B$BNon potrò mai ripagarti fino in fondo per l'aiuto che mi hai dato, ma... ti prego, prendi questo. Dopo Relara è la cosa più cara che ho.",
  en_title = "Fallen Sky Lake",
  en_obj = "Retrieve a Fallen Moonstone from the Shadethicket Oracle, then bring it to Pelturas in Astranaar.",
}
T[1036] = {
  title = "Alt, Canaglia",
  desc = "$N... sì, ho sentito parlare di te. Dicono in giro che non sei $Gamico:amica; di Booty Bay — proprio come noi Bloodsail Buccaneers. Fleet Master Firallon ha una missione speciale e cerca $Guomini forti e robusti:donne forti e robuste; proprio come te.$B$BSe la cosa ti interessa, va' al Crimson Veil e parlagli sottocoperta. La nave è all'ancora al largo della Wild Coast, a est di qui, accanto alla Riptide e alla Damsel's Luck.",
  obj = "Parla con Fleet Master Firallon a bordo della Crimson Vale, al largo della costa di Stranglethorn Vale.",
  reward = "Alt, canaglia. Corre voce che te sei il tipo da tirare qualche bel colpo mancino. Be', se non sei $Gamico:amica; di Booty Bay, magari tra i Bloodsail Buccaneers c'è un posto speciale per te.$B$BArrrrr...",
  en_title = "Avast Ye, Scallywag",
  en_obj = "Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale.",
}
T[1037] = {
  title = "Velinde Starsong",
  desc = "Velinde Starsong mi ha preceduta qui nell'Ashenvale Forest. All'inizio sembrava tenere sotto controllo la situazione nel Felwood, ma a poco a poco i suoi sforzi hanno cominciato a cedere, finché un giorno è semplicemente scomparsa.$B$BMi hanno mandata qui a continuare il suo lavoro, ma temo di non sapere nulla della sacerdotessa. Forse Thyn'tel Bladeweaver, una delle comandanti delle Sentinelle, conosce sulla sua scomparsa altri dettagli che a me non sono stati detti.$B$BDi certo capirà quanto contano informazioni del genere.",
  obj = "Parla con Thyn'tel Bladeweaver alla Terrazza del Guerriero a Darnassus.",
  reward = "Velinde Starsong? Che la sacerdotessa sia scomparsa tempo fa lo sanno quasi certamente tutti. Quanto ad altri dettagli su quello che è successo quando se n'è andata... per rivelarli mi servirebbe un buon motivo.",
  en_title = "Velinde Starsong",
  en_obj = "Speak with Thyn'tel Bladeweaver at the Warrior's Terrace in Darnassus.",
}
T[1038] = {
  title = "Gli Effetti Personali di Velinde",
  desc = "È questo che ti ha mostrato il Tome of Mel'Thandris? Allora non credo ci sia niente di male a lasciarti esaminare i suoi averi. Con questa chiave potrai aprire la cassa dove abbiamo riposto le sue cose, nel dormitorio delle Sentinelle. Teneva un diario dei suoi compiti: se c'è qualcosa da scoprire, lo troverai lì.$B$BDevi sapere che le Sentinelle credono che avesse i suoi motivi per andarsene, e si aspettano che possa tornare da un momento all'altro. In passato la sacerdotessa ha fatto molto per guadagnarsi la nostra fiducia.",
  obj = "Cerca il diario di Velinde nella sua cassa, poi riportalo insieme alla chiave a Thyn'tel Bladeweaver a Darnassus.",
  progress = "Che cosa hai scoperto?",
  reward = "A quanto pare la scomparsa di Velinde è più preoccupante di quanto sembrasse all'inizio. Eppure non riesco a credere che abbia fatto una brutta fine. Forse ci converrebbe metterci in contatto con lei.$B$B$N, visto che ti sei $Ginteressato:interessata; di persona a questa faccenda, vorrei chiederti aiuto.",
  en_title = "Velinde's Effects",
  en_obj = "Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus.",
}
T[1039] = {
  title = "Porto di The Barrens",
  desc = "Ratchet è l'unico porto delle Barrens. Con ogni probabilità Velinde ha trovato a Ratchet una nave mercantile che la portasse alla Blackwater Cove, in Azeroth. Con i goblin che gestiscono il porto abbiamo avuto pochi rapporti, ma il capitano del molo dovrebbe sapere chi arriva e chi parte via nave.$B$BSegui la strada verso sud-est attraverso Ashenvale e ti ritroverai nelle Barrens. Guarda bene dove metti i piedi, $N: i guerrieri dell'Orda pattugliano queste terre. Al porto, però, sarai al sicuro.",
  obj = "Parla con Wharfmaster Dizzywig a Ratchet.",
  reward = "$R, eh? Lo ammetto, da queste parti non se ne vedono molti della tua specie. Cerchi qualcuno, eh? Dammi solo un momento, sono sicuro di averlo segnato su uno dei miei registri.$B$BPerò qui passa un sacco di gente, quindi dammi solo un momento.",
  en_title = "The Barrens Port",
  en_obj = "Speak with Wharfmaster Dizzywig in Ratchet.",
}
T[1040] = {
  title = "Passaggio per Booty Bay",
  desc = "Ah, sì, eccolo, finalmente l'ho trovato. Potevi dirmelo che era passata di qui tanto tempo fa. Vediamo.$B$BVelinde. Ha prenotato un passaggio per Booty Bay sul Black Osprey. Qui non c'è niente che dica il contrario, quindi immagino che sia arrivato in porto senza problemi.$B$BDi più non posso aiutarti, ma lei chiedeva come viaggiare via terra da quella parte del mondo, e le ho parlato di Ruzzgot, un carovaniere che lavora a Booty Bay. Può darsi che questa Velinde abbia viaggiato con lui.$B$BE adesso circola. Non ho tutto il giorno da perdere con te.",
  obj = "Prendi una nave per Booty Bay e parla con Caravaneer Ruzzgot.",
  reward = "Sì? Non mi sembri il tipo con della merce da spedire, quindi o cerchi lavoro nella mia carovana — e adesso non ce n'è — o probabilmente stai parlando con il goblin sbagliato.$B$BAllora, quale delle due?",
  en_title = "Passage to Booty Bay",
  en_obj = "Take a boat to Booty Bay and speak with Caravaneer Ruzzgot.",
}
T[1041] = {
  title = "La Strada delle Carovane",
  desc = "A quanto pare mi sbagliavo su di te, e non mi succede tutti i giorni.$B$BGuarda caso, questa Velinde che cerchi me la ricordo. Non capita spesso che una sacerdotessa elfa della notte voglia viaggiare con una carovana vecchia e sporca — ma ottima per le tue spedizioni! — come la mia.$B$BCi siamo separati sulla strada verso nord: lei andava a Darkshire. Il cancelliere del posto tiene registri di ogni genere, potrebbe sapere qualcosa di utile.$B$BFa' attenzione nella giungla: è un posto mortale anche quando va tutto bene.",
  obj = "Parla con Clerk Daltry a Darkshire.",
  reward = "Con tutte le cose strane successe negli ultimi anni, registro i forestieri con tutta la cura possibile. Non si sa mai quando le registrazioni potranno tornare utili... anche se di solito, quando succede, non è per una faccenda piacevole. Non che voglia insinuare nulla su questa Velinde che stai cercando.",
  en_title = "The Caravan Road",
  en_obj = "Speak with Clerk Daltry in Darkshire.",
}
T[1042] = {
  title = "La Famiglia Carevin",
  desc = "No, nei miei registri non risulta nessuna Velinde Starsong che abbia alloggiato a Darkshire... anche se, permettimi, faccio fatica a immaginare una sacerdotessa elfa della notte che prende una stanza alla locanda, capisci cosa intendo?$B$BDegli uomini lupo di cui parli, però, ho sentito dire. Proprio l'altro giorno Calor è arrivato in città con una filza delle loro teste. Lavora con la famiglia Carevin: cacciatori di demoni, non morti e altre mostruosità. Parla con Jonathan, è il capofamiglia.",
  obj = "Parla con Jonathan Carevin a Darkshire.",
  reward = "Tempi bui, questi. Ogni ramo che ondeggia sussurra cattive notizie, e sotto ogni pietra si trova il male.$B$BE proprio in tempi come questi $Guno sconosciuto:una sconosciuta; entra in casa mia a chiedere dei worgen... Non chiederò perdono per i miei sospetti: chiederò solo risposte.$B$BE le avrò.",
  en_title = "The Carevin Family",
  en_obj = "Speak with Jonathan Carevin in Darkshire.",
}
T[1043] = {
  title = "La Falce di Elune",
  desc = "La tua storia sembra vera... Non capisco fino in fondo le tue ragioni, ma se quello che fai qui a Duskwood vuol dire liberare la foresta dai worgen, che siano pochi o tanti, mi accontento dei risultati anche senza capire.$B$BA sud c'è una miniera invasa dai worgen... Sono spuntati dal nulla, ma per quel che ne sappiamo è lì che sono stati trovati la prima volta.$B$BFa' quello che devi, ma se trovi qualcosa di importante ti chiederei di farmelo sapere. Nella nostra guerra contro il male accetteremo qualsiasi aiuto.",
  obj = "Cerca tracce della Falce di Elune, poi torna da Jonathan Carevin a Darkshire.",
  progress = "I boschi sono pericolosi per chi non è preparato. Tieni le armi a portata di mano e la mente ancora più all'erta, o il prossimo viaggio nella foresta infestata potrebbe essere il tuo ultimo.",
  reward = "Interessante, la storia che racconti, $N. L'influenza della famiglia Carevin non basta a farci trovare la radice di questi problemi e a metterci fine una volta per tutte, ma faremo il possibile per contenere il numero dei worgen a Duskwood.$B$BHo già ordinato a Calor di farne la sua priorità.",
  en_title = "The Scythe of Elune",
  en_obj = "Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire.",
}
T[1044] = {
  title = "Domande con Risposta",
  desc = "Il problema dei worgen lo terremo a bada, non preoccuparti. Il male che la tua amica ha portato nei nostri boschi verrà contenuto, e non le porto rancore per quello che ha fatto. Di questi tempi succedono cose strane, $N, e l'oscurità non conosce tregua.$B$BNon ti trattengo oltre. Ho il sospetto che anche altri dovrebbero sapere quello che hai trovato nelle miniere di Duskwood.",
  obj = "Torna da Thyn'tel Bladeweaver a Darnassus.",
  reward = "Dunque è questo il destino di Velinde, eh? L'alta sacerdotessa sarà delusa di saperlo: prima della scomparsa erano buone amiche. Eppure la Falce di Elune le era stata di certo donata dalla nostra dea, e mi turba che non sia più nelle mani dei suoi servitori.$B$BMa questa è un'altra questione, per un'altra volta. Ti sono molto grata per quello che hai fatto.",
  en_title = "Answered Questions",
  en_obj = "Return to Thyn'tel Bladeweaver in Darnassus.",
}
T[1045] = {
  title = "La Purificazione di Raene",
  desc = "Gli elfi della notte sono antichi quanto il tempo, ma con la loro arroganza distruggono il loro stesso mondo. E adesso distruggono anche le nostre vite. Ma ormai questo non si può più controllare...$B$BAgli elfi do la colpa di molte cose, ma delle nostre azioni rispondiamo noi. Anche senza la corruzione, siamo capaci di un grande male.$B$BRan Bloodtooth è uno di questi mali. Assetato di potere, bramoso... la corruzione lo ha solo reso più forte. Il mio odio per gli elfi brucia, ma non auguro del male ai loro figli: per questo dobbiamo essere noi a tenere a bada i nostri.",
  obj = "Uccidi 4 Bloodtooth Guards e recupera il Ran Bloodtooth's Skull per Krolg vicino al Lake Mystral.",
  progress = "Allora, $Gamico mio:amica mia;, hai già ucciso Ran?$B$BNemmeno gli Elfi della notte meritano davvero la sua ira. Il suo odio brucia ancora più forte del mio, ma la sua mente non è più sua. È una minaccia per tutte le creature naturali di questa foresta.",
  reward = "Hai fatto bene, $Gamico mio:amica mia;.$B$BLa foresta è ancora contaminata, ma almeno sappiamo di aver fatto la nostra piccola parte per restituirle l'antico splendore. Se vorrai tornare da me, la compagnia di qualcuno della mia specie mi farà piacere.$B$BStammi bene. Forse le nostre tribù si incontreranno di nuovo, in tempi meno violenti.",
  en_title = "Raene's Cleansing",
  en_obj = "Kill Ran Bloodtooth and 4 Bloodtooth Guards and return to Krolg near Lake Mystral.",
}
T[1046] = {
  title = "La Purificazione di Raene",
  desc = "Torna dalla tua tribù e racconta loro la vittoria che hai ottenuto qui.$B$BMostragli il tuo trofeo e goditi la gloria...",
  obj = "Porta il Ran Bloodtooth's Skull e la Dartol's Rod of Transformation a Raene Wolfrunner ad Astranaar.",
  progress = "Qui ad Ashenvale le Sentinelle fanno quel che possono, ma il terreno che abbiamo guadagnato lo dobbiamo a $Gun:una; $R come te.",
  reward = "Allora è questo il teschio della minaccia furbolg più feroce di Ashenvale?$B$BSono più che soddisfatta delle tue capacità, $N. Le Sentinelle non sapranno mai ringraziarti abbastanza, e spero che in futuro potremo contare ancora su di te per aiutare il nostro popolo.$B$BMetterò questo teschio e la Verga di Dartol in un posto d'onore, dove tutti possano vederli.$B$BTeronis sarebbe fiero. Grazie ancora.",
  en_title = "Raene's Cleansing",
  en_obj = "Bring Ran Bloodtooth's Skull and Dartol's Rod of Transformation to Raene Wolfrunner in Astranaar.",
}
T[1047] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone valide e in forze che lo aiutino a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una terra desolata e proibita, piena di pericoli inimmaginabili, e il Circolo ha bisogno di rappresentanti volenterosi e integri che agiscano in suo nome.$B$BChiunque sia interessato chieda udienza al Cenarion Circle. Per maggiori informazioni, parlate con l'Arcidruido di Darnassus, Fandral Staghelm!",
  obj = "Parla con Arch Druid Fandral Staghelm a Cenarion Enclave of Darnassus dell'appello del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Cosa ti fa pensare che io voglia farmi importunare da quelli come te, $C? Aspetta — adesso interrompo gli importanti compiti che svolgo ogni giorno, così posso aiutarti a scovare un aggeggio da qualche parte. Ma certo, il benessere di Darnassus — anzi, di tutto Teldrassil — deve passare in secondo piano rispetto a un ninnolo da aggiungere alla tua collezione.$B$BQuegli sciocchi di Moonglade mi fanno perdere tempo con le loro richieste d'aiuto, e ora devo sopportare anche questo?",
}
T[1048] = {
  title = "Dentro lo Scarlet Monastery",
  desc = "Mentre la Dama Oscura si occupa di una questione pressante, l'avanzata di The Lich King a nord, io provvedo a che i problemi a noi più vicini vengano risolti come si conviene.$B$BNon v'è dubbio: quei parassiti umani che si fanno chiamare Scarlet Crusade si stanno rivelando la spina più acuminata nel nostro fianco, qui in patria. Le Tirisfal Glades brulicano letteralmente di quelle piccole formiche rosse.$B$BRecati al Monastero, $C, e annienta High Inquisitor Whitemane insieme ai suoi luogotenenti più importanti.",
  obj = "Uccidi High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, lo Scarlet Champion e Houndmaster Loksey, poi fai rapporto a Varimathras a Undercity.",
  progress = "Forse nei miei ordini non sono stato abbastanza esplicito, $C. Voglio che High Inquisitor Whitemane muoia, una volta per tutte. E già che ci sei, fai fuori anche i suoi pezzi grossi.$B$BUccidi quel fanatico di Scarlet Commander Mograine. Annienta Herod, lo Scarlet Champion. E massacra pure Houndmaster Loksey con i suoi luridi cagnacci.$B$BOra vattene!",
  reward = "Hai servito bene la Dama Oscura, $C, e non era un compito da poco quello che ti ho chiesto.$B$BLa tua lealtà verso i Forsaken non è passata inosservata, e la tua tenacia in battaglia sarà ricordata.",
  en_title = "Into The Scarlet Monastery",
  en_obj = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.",
}
T[1049] = {
  title = "Compendium of the Fallen",
  desc = "Verso i nostri fratelli colpiti dalla piaga, The Earthen Ring aveva intenzioni pure. Ma chi può sapere cosa muove coloro che sussurrano all'orecchio dell'Elder Council?$B$BI Forsaken con cui ci siamo alleati hanno alle spalle una storia piena di inganni, e il nostro patto è stato troppo frettoloso. Forse Cairne avrebbe fatto bene a dare ascolto agli avvertimenti di Orgrimmar.$B$BIl Compendium of the Fallen si trova nel profondo dello Scarlet Monastery, sorvegliato da fanatici umani impazziti. Il loro metodo è forgiato nella follia, ma le ricerche che conducono potrebbero tornarci utili.",
  obj = "Recupera il Compendium of the Fallen dal Monastero in Tirisfal Glades e torna da Sage Truthseeker a Thunder Bluff.",
  progress = "Cairne è un capo nobile e coraggioso, e gli affiderei la vita. Con il clima politico di oggi, però, sono gli altri a non ispirarmi fiducia.$B$BQuando potrò raccogliere tutte le conoscenze disponibili, saprò dare consigli assennati al Capotribù.$B$BHai avuto modo di andare nelle Tirisfal Glades? Allo Scarlet Monastery? Il Compendium of the Fallen non è che un pezzo di questo intricato rompicapo...",
  reward = "Il Compendium of the Fallen! Cominciavo a dubitare che quel libro esistesse davvero!$B$BHai servito bene i tauren di Thunder Bluff, $N, e la tua dedizione non sarà dimenticata.",
  en_title = "Compendium of the Fallen",
  en_obj = "Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.",
}
T[1050] = {
  title = "Mythology of the Titans",
  desc = "Al futuro non si sfugge! Ci precipitiamo verso di esso come gocce di pioggia che cadono nel Great Sea.$B$BMa forse, se studiamo il passato, possiamo capire cosa ci aspetta e affrontare l'ignoto più preparati.$B$BPrima che su Lordaeron si abbattessero gravi sventure, nascosto nelle Tirisfal Glades c'era un bastione del sapere. Si dice che nella biblioteca del vecchio Monastero fosse custodito un libro chiamato Mythology of the Titans.$B$BPortamelo, e forse insieme riusciremo a svelare i segreti del passato!",
  obj = "Recupera Mythology of the Titans dal Monastero e portala a Librarian Mae Paledust a Ironforge.",
  progress = "Il Monastero era un seminario per Paladini in addestramento. Era una roccaforte della Luce, ma poi è caduto nelle mani dei folli fanatici della Scarlet Crusade.$B$BLa Crociata credeva di avere uno scopo nobile: purificare la terra dalla piaga dei non morti. Ma la follia ha contaminato la loro causa, e adesso sono nemici di tutti.$B$BPortami Mythology of the Titans: così potrò studiarla e custodirla qui a Ironforge.$B$BLe sale corrotte del Monastero non sono un posto per un tesoro storico del genere.",
  reward = "Hai salvato il testo sacro!$B$BHai fatto un lungo viaggio, e mettere le mani sul libro non è stato certo facile. Ma la tua impresa andrà a vantaggio dei nani di Ironforge.$B$BTi ringrazio a nome dell'Explorers' League, $N.",
  en_title = "Mythology of the Titans",
  en_obj = "Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.",
}
T[1051] = {
  title = "La Vendetta di Vorrel",
  desc = "Ho la volontà libera, ma la Dama Oscura non posso più servirla. Sento che il mio tempo su Azeroth è giunto al termine: la mia forza vitale è in frantumi.$B$BMi ha ridotto così Interrogator Vishas! Per settimane mi ha torturato! Mi ha preso la fede nuziale e l'ha data a sua moglie. Quel bastardo!$B$BVendetta... Voglio vendetta!$B$BQuello sciocco pomposo si vantava della sua adorata moglie, Nancy, che viveva sulle rive del Lake Lordamere. Trova quella donnaccia, uccidila e riporta la fede a mia moglie, Monika, a Tarren Mill.$B$BEsaudisci le mie ultime volontà....",
  obj = "Riporta la fede nuziale di Vorrel Sengutz a Monika Sengutz a Tarren Mill.",
  progress = "Che vuoi, $Gstraniero:straniera;?",
  reward = "Ha avuto una vita così travagliata, Vorrel. E che bravo compagno era...$B$BMaledetti quegli sporchi umani!$B$BVorrel se n'è andato, e della non-morte non godrà mai più. Almeno nella vendetta che hai compiuto in suo nome posso trovare conforto, e per questo ti ringrazio.$B$BOra lasciami piangerlo in pace....",
  en_title = "Vorrel's Revenge",
  en_obj = "Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.",
}
T[1052] = {
  title = "Lungo il Sentiero Scarlatto",
  desc = "Noi della Scarlet Crusade rivendichiamo roccaforti da Hearthglen fino alle Tirisfal Glades, e andiamo molto fieri dei nostri bastioni di purificazione sparsi in tutto Lordaeron.$B$BA Desolace hai dimostrato il tuo valore contro i non morti, ma è a Lordaeron che si trova la vera minaccia della piaga.$B$BRaggiungi la città di Southshore, negli Eastern Kingdoms, e cerca un crociato di nome Raleigh the Devout. Consegnagli questa letter of commendation con il mio sigillo, e ti scorterà a un posto d'onore nel nostro Scarlet Monastery.",
  obj = "Porta l'Anton's Letter of Commendation a Raleigh the Devout a Southshore.",
  progress = "Chi va là? Cosa vuoi da me?",
  reward = "Brother Anton sta ancora diffondendo la parola della Scarlet Crusade? Oh, cielo....",
  en_title = "Down the Scarlet Path",
  en_obj = "Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore.",
}
T[1053] = {
  title = "In Nome della Luce",
  desc = "Un tempo servivo la Scarlet Crusade con onore, lealtà e orgoglio, e credevo nobile la sua causa: liberare Azeroth dai non morti.$B$BMa mentre ero al Monastero, nelle Tirisfal Glades, mi sono accorto che stavano perdendo il contatto con la realtà. Adesso per loro chiunque non porti la tabarda della Crociata è un appestato, e uomini e donne innocenti sono stati torturati perché, si diceva, lo erano.$B$BIn nome della Luce, The Scarlet Crusade va schiacciata. Sei tu, $N, che devi distruggere questo regime folle.",
  obj = "Uccidi High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, lo Scarlet Champion e Houndmaster Loksey, poi torna da Raleigh the Devout a Southshore.",
  progress = "Finché gli ufficiali più alti in grado non saranno eliminati, la corruzione nel Monastero non avrà fine.$B$BIn nome della Luce, uccidi High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, lo Scarlet Champion e Houndmaster Loksey. Quando saranno caduti, forse la vera causa potrà riaccendersi. Fino ad allora, chiunque si trovi sulla strada della Crociata è in pericolo.$B$BParti da Southshore e fa' che accada!",
  reward = "I discepoli della Luce non gioiscono mai quando si perde una vita, ma dobbiamo accettare che a volte sacrifici simili siano necessari per il bene superiore del Regno e del pianeta.$B$BCon le tue imprese nel Monastero hai salvato molte vite innocenti, $N. Rendo omaggio alla tua tenacia.",
  en_title = "In the Name of the Light",
  en_obj = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.",
}
T[1054] = {
  title = "Ridurre la Minaccia",
  desc = "Proprio a nord di Astranaar si trovano i furbolg Thistlefur, e i miei esploratori riferiscono che negli ultimi mesi sono cresciuti molto di numero. Se diventano troppi, potrebbero trovare il coraggio di attaccare direttamente Astranaar.$B$BUccidine più che puoi, ma portami il teschio del loro capo: sarà la prova che li hai fermati... per ora.$B$BResterò qui ad Astranaar ad aspettare tue notizie. Che Elune sia con te.",
  obj = "Porta il Dal Bloodclaw's Skull a Raene Wolfrunner ad Astranaar.",
  progress = "La corruzione dei furbolgs ha fatto di Ashenvale un'ombra dell'antico splendore.",
  reward = "Ben fatto, $N.$B$BPer noi i furbolg sono una minaccia continua. Speriamo che questo basti a tenerli a bada ancora per un po'.",
  en_title = "Culling the Threat",
  en_obj = "Bring Dal Bloodclaw's Skull to Raene Wolfrunner in Astranaar.",
}
T[1055] = {
  title = "La Purificazione di Raene",
  desc = "Ora hai in mano la verga completa. Shael'dryn vorrà sapere che ce l'hai fatta.",
  obj = "Torna da Shael'dryn al pozzo lunare.",
  reward = "Ce l'hai fatta, $N! Ottimo lavoro!",
  en_title = "Raene's Cleansing",
  en_obj = "Return to Shael'dryn at the moonwell.",
}
T[1057] = {
  title = "Riconquistare la Charred Vale",
  desc = "Sono un protettore degli spiriti della foresta, e di certo puoi immaginare perché sono in allarme.$B$BPer arrivare fin quassù hai attraversato queste montagne: avrai visto lo scempio che si è abbattuto su questa terra. L'avidità ha distrutto queste colline sacre.$B$BA sud, The Charred Vale è stata data alle fiamme dall'avido esercito meccanizzato degli industriali. E come se non bastasse, le Bloodfury che hanno invaso queste terre ci sbarrano il passo e non possiamo avviare la ricrescita.$B$BScaccia quelle miserabili arpie, $N!",
  obj = "Keeper Albagorm allo Stonetalon Peak vuole che tu uccida 6 Bloodfury Harpies, 6 Bloodfury Ambushers, 6 Bloodfury Slayers e 6 Bloodfury Roguefeathers.",
  progress = "Ci vorrà molto lavoro prima che la Charred Vale torni a essere la foresta rigogliosa di un tempo.$B$BRipulisci la zona da quelle minacce immonde, $N! Solo allora potremo cominciare a riprenderci quello che appartiene alla natura.",
  reward = "Ora che le Bloodfury hanno subito una perdita tanto grave, forse può cominciare il vero lavoro per risanare la terra...",
  en_title = "Reclaiming the Charred Vale",
  en_obj = "Keeper Albagorm on Stonetalon Peak wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.",
}
T[1058] = {
  title = "La Magia della Foresta di Jin'Zil",
  desc = "Così emozionato sono io!$B$BTre gabbiette per tre elfetti! E adesso cosa ci facciamo con i nostri cari amici abbraccia-alberi? Ma certo, gli facciamo assaggiare un po' di... come la chiamano... magia della foresta!$B$BMi servirà una bella dose di linfa di Stonetalon. E da quei felini orribili portami un po' di baffi di twilight. Poi tanti courser eyes, naturalmente — di occhi non ce n'è mai abbastanza. Oh, e non dimentichiamo una preziosa scaglia di un fey dragon.$B$BCorri allo Stonetalon Peak, $N, così posso preparare un po' di magia della foresta!",
  obj = "Witch Doctor Jin'Zil a Malaka'jin vuole 5 porzioni di Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes e una Fey Dragon Scale.",
  progress = "Guardali, i nostri poveri amichetti elfi. Tutti chiusi in gabbia, senza una foresta dove saltellare!$B$BAllora, sei $Griuscito:riuscita; a procurarmi un po' di linfa? E i baffi dei corridori twilight? Non è che per caso hai con te la fey dragon scale?$B$BE gli occhi! Me ne servono tanti! Senza una bella porzione di occhi, un potente intruglio di magia della foresta non si può preparare!",
  reward = "Oh, come saranno contente queste piccole ninfe dei boschi! Con questo intruglio speciale le faremo sentire proprio a casa!",
  en_title = "Jin'Zil's Forest Magic",
  en_obj = "Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale.",
}
T[1059] = {
  title = "Riconquistare la Charred Vale",
  desc = "Le Bloodfury sono state domate, ma se nessuno interviene si riorganizzeranno presto.$B$BMolto a sud delle Barrens c'è una terra chiamata Thousand Needles. Se attraversi Thousand Needles verso ovest, fino al margine della rigogliosa foresta di Feralas, troverai un druido di nome Falfindel Waywarder.$B$BÈ grande e saggio, e sa evocare potenti spiriti della foresta che possono aiutare a riconquistare la Charred Vale.$B$BFagli sapere che abbiamo bisogno di lui! Va' a cercarlo subito!",
  obj = "Raggiungi Falfindel Waywarder al confine tra Thousand Needles e Feralas.",
  reward = "Keeper Albagorm ha fatto bene a mandarti qui con tanta urgenza.$B$BVediamo se riusciamo a invocare dalla grande foresta un aiuto che arrivi alla Charred Vale prima che sia troppo tardi.",
  en_title = "Reclaiming the Charred Vale",
  en_obj = "Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas.",
}
T[1066] = {
  title = "Blood of Innocents",
  desc = "Creerò una tossina che prosciugherà la violenza dei membri della Venture Company, lasciandoli deboli e docili. Così il problema dell'Orda a Stonetalon dovrebbe risolversi, sì?$B$BMa per farla mi servirà il blood of innocents, un ingrediente difficile da ottenere.$B$BPer fortuna lo Syndicate, una banda di briganti umani della zona, ha al suo servizio dei maghi dell'ombra... e sono proprio loro a raccogliere sangue innocente per i loro loschi scopi.$B$BI maghi dell'ombra dello Syndicate li troverai a Durnholde Keep, a sud-est.",
  obj = "Porta 5 Vials of Innocent Blood ad Apothecary Lydon a Tarren Mill.",
  progress = "Hai trovato gli Syndicate Shadow Mages? Il sangue che avevano, l'hai preso?",
  reward = "Molto bene! Lo Syndicate non ti ha creato troppi problemi, spero?$B$BCome ti dicevo, il blood of innocents non è facile da ottenere. Per fortuna i maghi dell'ombra dello Syndicate hanno fatto il lavoro difficile per noi.$B$BOra aspetta un momento, che preparo la miscela...",
  en_title = "Blood of Innocents",
  en_obj = "Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill.",
}
T[1067] = {
  title = "Ritorno a Thunder Bluff",
  desc = "Ecco la tossina. Usata contro la Venture Company dovrebbe dare risultati favorevoli, forse persino contagiosi. Devo dire che è proprio emozionante vedere il mio lavoro messo in pratica sul campo!$B$BPrima di usarla, però, portala ad Apothecary Zamah: deve trovare un modo di somministrarla che ne tiri fuori il massimo effetto.",
  obj = "Porta la Lydon's Toxin ad Apothecary Zamah a Thunder Bluff.",
  progress = "Sei $Gtornato:tornata;, $N. Porti aiuto da Apothecary Lydon?",
  reward = "Una tossina da Apothecary Lydon? Molto bene. Conoscendo Lydon, contro la Venture Company sarà davvero efficace...",
  en_title = "Return to Thunder Bluff",
  en_obj = "Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff.",
}
T[1068] = {
  title = "Macchine Trituratrici",
  desc = "Fra la magia spirituale degli sciamani e quella naturale dei druidi c'è un legame, ed è per questo che noi sciamani riusciamo a sentire la supplica degli spiriti di Stonetalon. Molti dei loro sussurri mi sfuggono, ma un messaggio, una visione, è chiaro...$B$BNella visione, due macchine a forma d'uomo abbattevano alberi a una velocità impossibile nella Windshear Crag, a nordovest della Greatwood Vale. Queste bestie di metallo vanno fermate!$B$BLe macchine che ho visto erano marchiate con strani simboli:$B$BXT:4 e XT:9.",
  obj = "Uccidi i trituratori XT:4 e XT:9, poi torna da Seereth Stonebreak al confine tra le Stonetalon Mountains e le Barrens.",
  progress = "Gli spiriti degli alberi gemono per i fratelli perduti, $N. Devi distruggere i trituratori XT:4 e XT:9, altrimenti temo che Stonetalon non guarirà mai.",
  reward = "Ora che le macchine XT:4 e XT:9 sono distrutte, molti degli spiriti di Stonetalon si sono placati, $N. La Venture Company le ha perse: speriamo che adesso se ne vada da queste montagne.$B$BPerché, se non lo farà, temo che le atrocità subite da questo luogo impallidiranno di fronte a quello che ci aspetta.",
  en_title = "Shredding Machines",
  en_obj = "Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.",
}
T[1070] = {
  title = "Di Guardia a Stonetalon",
  desc = "Salve, $N.$B$BHai tutta l'aria di essere $Gpieno:piena; di voglia di viaggiare. Sei mai $Gstato:stata; sulle Stonetalon Mountains? La Venture Co. e altri nemici degli elfi della notte tormentano quella terra.$B$BPoco tempo fa la Sentinella Wolfrunner ci ha mandato la mia amica Kaela Shadowspear, perché scoprisse cosa sta succedendo laggiù, ma ancora non ho sue notizie. E mi preoccupa ancora di più che l'Alleanza abbia mandato con lei un mago gnomo... segno sicuro che ci sono guai.$B$BPotresti trovarla e poi tornare a riferirmi?",
  obj = "Trova Kaela Shadowspear, che sorveglia la valle che porta alla Windshear Crag in Stonetalon Mountains.",
  reward = "Ah, quindi sei $Gvenuto:venuta; da Ashenvale perché te l'ha chiesto Tara — quanto mi mancano, lei, la mia terra natale e i miei amici. Se recluta avventurieri per altri incarichi, con le Sentinelle deve cavarsela bene. Sono fiera di lei.$B$BPiacere di conoscerti, $N.",
  en_title = "On Guard in Stonetalon",
  en_obj = "Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains.",
}
T[1071] = {
  title = "La Tregua di uno Gnomo",
  desc = "Vedi, $N, faccio parte dell'Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, e il mio scopo... anzi, il mio DOVERE! è dimostrare agli elfi della notte che magia, miscele e meccanismi, messi insieme, possono aiutarli a salvare le loro foreste.$B$BMa è una guerra dura, e a quanto pare i goblin si riproducono come conigli. Non ho avuto neanche il tempo di costruire le mie ultime invenzioni!$B$BMi serve un po' di tempo per studiare un piano e organizzarmi, ma per riuscirci ho bisogno che tu tenga a bada i goblin nella Windshear Crag, a est...",
  obj = "Uccidi 10 Venture Co. Loggers e 10 Venture Co. Deforesters, poi torna da Gaxim Rustfizzle a Stonetalon.",
  progress = "Come va la battaglia laggiù, $N?",
  reward = "Grazie mille dell'aiuto, $N. Anzi, sei $Gtornato:tornata; proprio al momento giusto.$B$BCredo di avere un piano perfetto... esplosivi. No, il piano non è quello, ma ne fa parte.$B$BVedi, ho usato esplosivi ad alto potenziale — non preoccuparti, non sono pericolosi come pensano tutti — per spaventare un po' i goblin e farli indietreggiare. Con qualche detonazione ben piazzata lungo i bordi delle montagne riesco a guidarli piuttosto bene, come un gregge, ma da qualche giorno sono a corto di scorte...",
  en_title = "A Gnome's Respite",
  en_obj = "Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon.",
}
T[1072] = {
  title = "Un Vecchio Collega",
  desc = "Il congegno che ho in mente è la versione più avanzata che abbia mai costruito. Per farlo funzionare, però, ci vorrà una pozione speciale. E tanto vale usare la roba buona, visto che questa potrebbe essere la tua ultima missione.$B$BPer questo ci serviranno esplosivi potenti: il Nitromirglyceronium.$B$BSolo una persona sa fare l'NG-5, ed è un mio vecchio amico: Lomac Gearstrip. Vallo a cercare a Tinker Town.$B$BTu convincilo a prepararci un po' di NG-5, e io nel frattempo penso a dove piazzare i congegni.",
  obj = "Parla con Lomac Gearstrip a Ironforge.",
  reward = "Ahhh... Così ti manda Gaxim, eh? E chi mi dice che non mi stai mentendo?! Mmh? Mmh...?",
  en_title = "An Old Colleague",
  en_obj = "Speak to Lomac Gearstrip in Ironforge.",
}
T[1073] = {
  title = "Incompetenza + Sostanze Chimiche = Divertimento",
  desc = "Ahahah... ti serve il Nitromirglyceronium per impedire ai goblin di distruggere una foresta?!$B$BChe tu conosca Gaxim o no, non m'importa... Ti darò la roba solo per vedere te o loro saltare in aria in mille pezzettini.$B$BSolo che c'è un problema: l'ho finita tutta.$B$BMa facciamo così: tu mi porti le pozioni giuste e io te ne preparo un po' all'istante.$B$BPrima che ti regali un campione della mia più grande creazione, però, dimostrami almeno di avere un po' di talento da alchimista.",
  obj = "Porta 4 Minor Mana Potions e 2 Elisir di Tempra a Lomac Gearstrip a Ironforge.",
  progress = "Senza le pozioni il Nitromirglyceronium non lo posso fare... sono fondamentali per prepararlo.",
  reward = "Andranno benissimo.$B$BSe non sapessi come stanno le cose, $Gstraniero:straniera;, direi che di alchimia te ne intendi un po'. Bene, bene... al mondo non ci sono solo spade e stregonerie, sai?",
  en_title = "Ineptitude + Chemicals = Fun",
  en_obj = "Bring 4 Minor Mana Potions and 2 Elixirs of Minor Fortitude to Lomac Gearstrip in Ironforge.",
}
T[1074] = {
  title = "Incompetenza + Sostanze Chimiche = Divertimento",
  desc = "Ecco qua, $Gstraniero:straniera;. Ma fai attenzione... è roba instabile.$B$BSe sei davvero $Gun amico:un'amica; di Gaxim, salutamelo. Altrimenti, divertiti a farti saltare in aria.",
  obj = "Riporta il Nitromirglyceronium a Gaxim Rustfizzle a Stonetalon.",
  progress = "Ah, benone benone, sei $Gtornato:tornata;.",
  reward = "Hai fatto un lavoro perfetto, $N.$B$BNella ricetta per innescare i carri di dinamite, l'NG-5 è il componente indispensabile.$B$BCosa? Sì, dinamite... carri interi. Una distrazione perfetta, te lo dico io... aspetta e vedrai.",
  en_title = "Ineptitude + Chemicals = Fun",
  en_obj = "Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon.",
}
T[1075] = {
  title = "Una Pergamena da Mauren",
  desc = "Bene, adesso veniamo alla parte del mio piano sulla detonazione a distanza... oh, ma non te l'ho ancora spiegata, vero?$B$BIn breve: con un po' di magia posso far saltare in aria gli esplosivi mentre tu sei $Glontano:lontana;. Sto montando un congegno con cui, quando sarai $Gpronto:pronta;, ti basterà premere un solo pulsante per far esplodere il NG-5.$B$BPerò mi serve un incantesimo da un amico che sta a Stormwind — si chiama Collin Mauren, e lo trovi nel quartiere dei maghi. È umano, quindi non dovresti fare fatica a notarlo.",
  obj = "Trova Collin Mauren a Stormwind.",
  reward = "Allora, ti serve un incantesimo che ti permetta di far brillare gli esplosivi a distanza... mmm.",
  en_title = "A Scroll from Mauren",
  en_obj = "Find Collin Mauren in Stormwind.",
}
T[1076] = {
  title = "Diavoli a Westfall",
  desc = "Ah, credo di averlo trovato: un incantesimo di messaggio... penso che l'effetto che cerca sia questo.$B$BDovrò creare una pergamena con sopra impresso l'incantesimo, e per farlo mi serviranno i resti di un dust devil.$B$BIntanto che raccolgo gli altri componenti, perché non vai a Westfall a cercare una di quelle creature immonde? Sono pericolose, ma se sei $Gdisposto:disposta; a sottoporti a uno degli esperimenti di Gaxim, di certo saprai cavartela.$B$BAl tuo ritorno mi troverai qui.",
  obj = "Porta i Dust Devil Debris a Collin Mauren a Stormwind.",
  progress = "Salve, $N. Il componente che mi serve, l'hai trovato?",
  reward = "Concedimi solo qualche istante, e la tua pergamena sarà pronta.",
  en_title = "Devils in Westfall",
  en_obj = "Bring Dust Devil Debris to Collin Mauren in Stormwind.",
}
T[1077] = {
  title = "Consegna Speciale per Gaxim",
  desc = "Ecco a te, $N. Questa dovrebbe andare benissimo.$B$BLa prossima volta che vedi Gaxim, portagli i miei saluti, ti prego. Quando questa avventura sarà conclusa, non vedo l'ora di sentirne parlare.$B$BStammi bene.",
  obj = "Porta la Scroll of Messaging a Gaxim Rustfizzle a Stonetalon.",
  progress = "Ah ah! Sei $Gtornato:tornata;! Ce l'hai? Hai portato l'incantesimo?",
  reward = "È perfetto, $N! Ben fatto.$B$BMescolato con l'NG-5, questo incantesimo ci darà l'esplosivo telecomandato ideale.$B$BCosì potremo prepararti il diversivo perfetto, e tu potrai intrufolarti a rubare le lettere e i progetti di ingegneria della Venture Co..$B$BIl loro disboscamento rallenterà di sicuro.",
  en_title = "Special Delivery for Gaxim",
  en_obj = "Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon.",
}
T[1078] = {
  title = "Recupero per Mauren",
  desc = "I viaggiatori non smettono di chiedermi delle Stonetalon Mountains: a quanto pare chi cerca avventure ci va molto volentieri, che sia a caccia di viverne o di elementali, o che abbia affari con la Venture Co.$B$BNella Charred Vale, nel cuore di Stonetalon, viveva una specie di basilischi: le loro scaglie, ridotte in polvere, erano un reagente meraviglioso per alcuni incantesimi che ho creato io.$B$BSe quei basilischi ci sono ancora, mi piacerebbe molto avere qualche scaglia.$B$BPrenditela con calma, non c'è fretta. Però posso pagarti bene.",
  obj = "Porta 8 Crystalized Scales a Collin Mauren a Stormwind.",
  progress = "Rieccoti, $N.$B$BSei già $Gtornato:tornata; dalla Valle di Stonetalon con quelle scaglie?",
  reward = "È perfetto, $N. Grazie infinite.$B$BForse un giorno potrò aiutarti io, come tu hai aiutato me.",
  en_title = "Retrieval for Mauren",
  en_obj = "Bring 8 Crystalized Scales to Collin Mauren in Stormwind.",
}
T[1079] = {
  title = "Operazioni Segrete — Alpha",
  desc = "Ci siamo, $N. Ascolta bene. I congegni sono finiti, pronti per l'uso.$B$BPrendi queste pagine — ti spiegheranno meglio i detonatori e gli esplosivi, e dove vanno piazzati.$B$BRicorda, la riuscita della missione non si misura da quanta distruzione causerai. Per far riuscire il Piano Alpha devi riportare i progetti ingegneristici della Venture Co. dall'interno della segheria a sud del Cragpool Lake.",
  obj = "Recupera i Progetti Ingegneristici della Venture Co. dalla segheria della Windshear Crag.",
  progress = "Allora, $N, li hai presi i progetti?",
  reward = "Incredibile, davvero! Per la Venture Co. è un colpo durissimo.$B$BPotremo scoprire i punti deboli delle loro macchine, e anche integrare i loro progetti nelle nostre creazioni. Oggi è proprio una giornata meravigliosa.",
  en_title = "Covert Ops - Alpha",
  en_obj = "Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag.",
}
T[1080] = {
  title = "Operazioni Segrete — Beta",
  desc = "Il Piano Beta è proprio come il Piano Alpha, $N.$B$BCreiamo un diversivo e poi rubiamo le loro preziose lettere.$B$BQuello che conta è prendere le lettere... ricordalo.$B$BDove piazzare gli esplosivi te lo diranno le pagine che ti ho già dato. Tu vedi di tornare qui $Gvivo:viva;, e con quelle lettere....",
  obj = "Recupera le Venture Co. Letters da Windshear Mine, all'estremità orientale della Windshear Crag.",
  progress = "Com'è andata, $N?",
  reward = "Incredibile, $N! Kaela e le Sentinelle saranno felicissime. Con la tua abilità e le mie creazioni non ci ferma nessuno.",
  en_title = "Covert Ops - Beta",
  en_obj = "Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag.",
}
T[1081] = {
  title = "L'Accoglienza di Tyrande",
  desc = "$N, sono certa che Tyrande Whisperwind in persona vorrebbe ringraziarti per la parte che hai avuto in questa missione.$B$BA prima vista forse non sembra, ma quello che hai contribuito ad avviare potrebbe benissimo rafforzare la nostra posizione nelle Stonetalon Mountains.$B$BSe ti consideri $Gnostro alleato:nostra alleata; contro queste atrocità, va' da Tyrande, nel Tempio della Luna a Darnassus.",
  obj = "Trova Tyrande Whisperwind a Darnassus.",
  reward = "Salve, $N. Conosco già il tuo nome e, anche se sei ancora nel pieno della giovinezza, sono lieta di vedere quale cammino hai scelto.$B$BAccetta questo dono in segno di riconoscenza: mi faresti un grande onore.",
  en_title = "Reception from Tyrande",
  en_obj = "Find Tyrande Whisperwind in Darnassus.",
}
T[1082] = {
  title = "Aggiornamento per Sentinel Thenysil",
  desc = "$N, qui ci hai dato una mano, ed è stata una grande impresa.$B$BSe informerai le Sentinelle di Ashenvale che io e Gaxim siamo vivi, ti ricompenseranno bene. Di' loro che siamo sulla buona strada per fermare la Venture Co. e guarire queste terre.$B$BCerca Tara Thenysil ad Astranaar; sarà felice di vederti $Gtornato:tornata; con buone notizie.",
  obj = "Torna da Sentinel Thenysil ad Ashenvale.",
  reward = "Grazie, $N. Hai reso un servizio alle Sentinelle.$B$BSono felice di vedere che Kaela... e persino Gaxim stanno bene.$B$BTi sei $Gguadagnato:guadagnata; la nostra riconoscenza.",
  en_title = "Update for Sentinel Thenysil",
  en_obj = "Return to Sentinel Thenysil in Ashenvale.",
}
T[1083] = {
  title = "Spiriti Infuriati",
  desc = "Non so bene cosa abbia fatto la Venture Co. alla Valle, ma è chiaro che le creature che la abitano li hanno sopraffatti.$B$BHanno dato fuoco alla foresta e usato le loro invenzioni distruttive per devastare la Valle più che potevano.$B$BMa nella loro ignoranza hanno liberato anche altro: burning spirits, elementali di fiamma, pietra e furia.$B$BFinché queste creature vagano libere, per la terra non c'è speranza di vedere il sorriso di Elune.$B$BPortami le loro smoldering embers, a prova che ne hai ridotto il numero.",
  obj = "Porta 8 Smoldering Embers, prese da un elementale del fuoco qualsiasi della Charred Vale, a Kaela Shadowspear, a Stonetalon.",
  progress = "Quando ho visto per la prima volta la Charred Vale ho quasi pianto, $N.",
  reward = "I resti del nostro nemico... la tua forza ci sta aiutando molto, $N. Grazie.",
  en_title = "Enraged Spirits",
  en_obj = "Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon.",
}
T[1084] = {
  title = "Antichi Feriti",
  desc = "Mi pare evidente che i protettori della Valle — i treants — abbiano contribuito a respingere la Venture Co.. Purtroppo, anche quei guardiani un tempo grandiosi ormai sono corrotti.$B$BGaxim pensa che la loro corruzione abbia in qualche modo a che fare con le armi usate dai goblin durante la ritirata.$B$BGli ho detto che avrei raccolto un campione da un treant ferito, così lui avrebbe potuto studiarlo e capire se è vero.$B$BPortami un po' di schegge, e lo gnomo potrà dirmi di più...",
  obj = "Porta un pezzo di Corroded Shrapnel a Kaela Shadowspear, a Stonetalon.",
  progress = "Ho la sensazione che Gaxim troverà un impiego per le schegge, qualunque uso ne abbia fatto la Venture Co. in passato.",
  reward = "Grazie, $N.$B$BDovrebbe bastare ampiamente perché Gaxim capisca come sono stati corrotti i treants. Glielo porto subito.",
  en_title = "Wounded Ancients",
  en_obj = "Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon.",
}
T[1085] = {
  title = "Di Guardia a Stonetalon",
  desc = "Se un'elfa della notte e uno gnomo collaborano, è chiaro che qui a Stonetalon la situazione è grave.$B$BLa Venture Co. ha devastato queste terre, e ho passato quasi tutto il tempo a fermare la distruzione.$B$BNon giudicare Gaxim troppo in fretta: sa bene che dobbiamo lavorare insieme.$B$BSe vuoi darci una mano, per prima cosa parla con Gaxim.$B$BMi spiace non poterti ancora rimandare da Tara con buone notizie. Forse fra poco.",
  obj = "Parla con Gaxim.",
  reward = "Insidiosa... insidiosa e pericolosa: ecco cos'è questa terra.$B$BMa io sono qui per dimostrare agli elfi della notte che, con l'aiuto della buona vecchia ingegneria e di un pizzico di magia, è un po' più sicura.$B$BVedi, rinunciare del tutto alla magia non li aiuterà — ne hanno bisogno. Ne ha bisogno il mondo. E se ci metti pure ingegneria e alchimia, vai sul sicuro. Le possibilità sono infinite.",
  en_title = "On Guard in Stonetalon",
  en_obj = "Speak to Gaxim.",
}
T[1086] = {
  title = "L'Aeroporto delle Macchine Volanti",
  desc = "La tossina è pronta: manca solo la consegna, e tocca a te occupartene, $N.$B$BLa Venture Company deve avere un modo per spedire messaggi e merci leggere fra il suo quartier generale e le attività a Stonetalon. Sarà probabilmente un piccolo porto aereo — troppo piccolo per uno zeppelin, ma forse abbastanza grande per una macchina volante. Devi perlustrare le zone di Stonetalon controllate dalla Venture Company e trovare questo porto aereo, se esiste. Se lo trovi, piazzaci la tossina.$B$BPiazzala e scappa.",
  obj = "Porta il Toxic Fogger al porto aereo della Venture Co., poi torna da Apothecary Zamah.",
  progress = "Devi trovare l'aeroporto della Venture Company, $N, sempre che esista.",
  reward = "Hai trovato il porto? Ben fatto, $N! Di sicuro i goblin sono rimasti piuttosto sorpresi dalla tua consegna! Speriamo che la tossina arrivi fino al loro quartier generale.$B$BHai servito bene il tuo popolo, e se provi un qualche senso di colpa per aver avvelenato la Venture Company, ti consiglio di ignorarlo. Si meritano molto di peggio.$B$BE se i Forsaken hanno un briciolo di saggezza da insegnare ai loro alleati, è questo:$B$BNon tirarti indietro davanti ai sentieri oscuri... se conducono alla vittoria.",
  en_title = "The Flying Machine Airport",
  en_obj = "Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah.",
}
T[1087] = {
  title = "L'Eredità di Cenarius",
  desc = "Non puoi immaginare quanto odio questa terra miserabile. Quelli della risma di Cenarius e i druidi kaldorei lassù sulla vetta usano i loro patetici poteri per soffocare il flusso della magia, perfino così lontano, a sud dei loro patetici possedimenti... le loro amate foreste.$B$BOh, potessi tornare a Jaedenar e inebriarmi del flusso della magia, ma il mio padrone non me lo concederà prima che il lavoro sia compiuto.$B$BSono certa che non ami gli elfi della notte e i loro alleati più di quanto li ami io. Aiutami, e potremo avere entrambi ciò che vogliamo.",
  obj = "Uccidi 4 Sons of Cenarius, 4 Daughters of Cenarius e 4 Cenarion Botanists per Braelyn Firehand presso il Sun Rock Retreat.",
  progress = "Incanalare la magia, qui, è come tirare su l'acqua da un pozzo con un secchio bucato.",
  reward = "Lo sento già... sì... che dolce potere... il fiume in piena. Sciocchi, i kaldorei, a disprezzare i doni di questo mondo e a rifiutare la magia che scorre cantando nelle vene.$B$BChe pallida parodia è la vita senza il suo abbraccio ardente!",
  en_title = "Cenarius' Legacy",
  en_obj = "Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat.",
}
T[1088] = {
  title = "Ordanus",
  desc = "Credevano di poter fermare il flusso della magia. Si sbagliavano. Credevano di poter nascondere Ordanus, ma la sua testa sarà mia!$B$BLa magia mi dona la vera vista. Sì... eccolo. Un crocevia... In cima a un grande albero nell'Ashenvale Forest. Un nome... Raynewood. È uno dei figli più antichi del dio della foresta. L'hanno portato via di nascosto dalla vetta prima che riuscissi a trovarlo, ma il suo tempo sta per scadere.$B$BPortamela e dividerò con te un dono potente.",
  obj = "Porta l'Ordanus' head a Braelyn Firehand presso il Sun Rock Retreat.",
  progress = "Quando il mio padrone mi ha mandata in cima a Stonetalon, credevo che mi sarebbe bastato sterminare gli elfi della notte che strisciavano fra le rovine sacre del nostro antico tempio di Azshara, profanandole con il loro tocco... ma Ordanus mi era sfuggito.",
  reward = "Ho conosciuto Ordanus, tanto tempo fa. Era arrogante come tutti quelli della sua specie, e si credeva superiore perfino agli Highborne.$B$BOra la sua testa non sta più così in alto, vero, $N?$B$BTi ho promesso una ricompensa, e l'avrai. Ascoltami.",
  en_title = "Ordanus",
  en_obj = "Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat.",
}
T[1089] = {
  title = "The Den",
  desc = "Sullo Stonetalon Peak i druidi hanno costruito la Talon Den, dove custodiscono molti oggetti potenti.$B$BPer tenerli lontani dalle mani sbagliate hanno escogitato un sistema complesso.$B$BPer fortuna sono riuscita a... strappare qualche dettaglio a uno di loro.$B$BIn una piccola lanterna all'ingresso di The Den troverai nascosta la Gatekeeper's Key — con quella aprirai i nascondigli intorno a The Den. Con gli oggetti dei nascondigli potrai aprire il loro tesoro, che si trova in una delle zone centrali.",
  obj = "Raggiungi The Den sullo Stonetalon Peak. Con la Gatekeeper's Key recupera gli oggetti nascosti dei druidi. Usali per aprire il Talon Den Hoard.",
  progress = "Nella pietra sono incise tre serrature.",
  reward = "Le tre chiavi scivolano ognuna nella sua apertura, e in mezzo alla luce splendente compaiono alcuni oggetti.",
  en_title = "The Den",
  en_obj = "Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard. ",
}
T[1090] = {
  title = "Gli Ordini di Gerenzo",
  desc = "Sai, una volta qui al cantiere ero il numero due. Poi il comando l'ha preso Gerenzo ed è cambiato tutto: ha licenziato il mio capo, Ziz Fizziks, e ha spedito me a lavorare giù nelle miniere. Ziz però mi ha detto di restare qui a raccogliere informazioni: se riusciamo a scoprire che piani ha Gerenzo, il suo nuovo capo ci pagherà bene.$B$BComunque, una cosa la so: Gerenzo ha ordinato di estrarre grandi quantità di questo minerale verde-oro. Posso procurarti un campione da portare a Ziz, ma mentre lo prendo tu dovrai tenere d'occhio le pattuglie.",
  obj = "Prendi il minerale misterioso da Piznik dopo che avrà finito di estrarlo.",
  reward = "Grazie, $N. Per un attimo la cosa si stava mettendo un po' male, e probabilmente ci siamo tirati addosso fin troppa attenzione.$B$BL'importante, però, è che il campione di minerale ce l'abbiamo, e dovremmo portarlo a Ziz il prima possibile.",
  en_title = "Gerenzo's Orders",
  en_obj = "Get the mysterious ore from Piznik after he finishes mining it.",
}
T[1091] = {
  title = "Aggiornamento per Kaela",
  desc = "$N, porta queste lettere a Kaela. Di sicuro vorrà saperlo. O comunque, lo vorranno le Sentinelle.$B$BE mi raccomando, dille che successo abbiamo avuto, e che senza un pizzico di magia non ce l'avremmo fatta.",
  obj = "Porta le Venture Co. Letters a Kaela Shadowspear.",
  progress = "Sì, $N? In cosa posso aiutarti?",
  reward = "Davvero interessante.$B$BTu e Gaxim avete fatto un ottimo lavoro, $N. Grazie.",
  en_title = "Kaela's Update",
  en_obj = "Bring the Venture Co. Letters to Kaela Shadowspear.",
}
T[1092] = {
  title = "Gli Ordini di Gerenzo",
  desc = "Credo che farei meglio a pensare ad andarmene anch'io. Non ci vorrà molto prima che ai pezzi grossi arrivi la notizia di quello che è successo qui, e di sicuro non sarebbero per niente contenti di rivedermi.$B$BSgattaiolerò via e raggiungerò Ziz. Speriamo che riesca a trovarmi un nuovo lavoro!$B$BIo cercherò di sistemare un po' questo pasticcio, ma tu faresti bene a portare subito il campione di minerale a Ziz. Mi ha detto che si sarebbe accampato da qualche parte sul lato occidentale della Windshear Crag. Buona fortuna.",
  obj = "Consegna l'Unidentified Ore a Ziz Fizziks in Stonetalon Mountains.",
  progress = "Posso aiutarti in qualcosa?",
  reward = "Ahhh, lo sapevo che avevo fatto bene a dire a Piznik di restare lì. Di sicuro gli ingegneri di Undermine saranno molto interessati a dare un'occhiata a questo...$B$BUn pezzetto, naturalmente, vorrò tenerlo per me, ma occhio non vede, cuore non duole, no?",
  en_title = "Gerenzo's Orders",
  en_obj = "Deliver the Unidentified Ore to Ziz Fizziks in the Stonetalon Mountains.",
}
T[1093] = {
  title = "Super Mietitore 6000",
  desc = "Terribile quello che la Venture Company ha fatto qui, eh? Ma cosa avevano in testa? Una compagnia di goblin che assume uno gnomo!$B$BPer mia fortuna, Sputtervalve riconosce un genio quando lo vede. Mi ha assunto subito dopo che mi avevano cacciato!$B$BMi dice che hanno costruito una macchina taglialegna enorme, e Sput' vuole che gli rubi i progetti. Purtroppo Gerenzo — maledetto gnomo — mi vuole morto appena mi vede... magari potresti rubare tu i progetti per me? Dovresti riuscire a trovarli addosso a uno dei loro operatori.",
  obj = "Procura i Super Reaper 6000 Blueprints a Ziz Fizziks, nelle Stonetalon Mountains.",
  progress = "Hai trovato quei progetti? Non vedo l'ora di fare colpo sul nuovo capo. Spero che, una volta convinto della mia lealtà — be', per quanto lo si possa convincere... onore da goblin, sai com'è? — non si faccia problemi a sfruttare il mio genio, che è piuttosto notevole.",
  reward = "Ehi, è quello che penso? Ottimo!$B$BAllora, vediamo. Uff... come dovrei capirci qualcosa... non riesco proprio a capire come ragionano gli gnomi. Ti dirò, mi stupisce che siano riusciti a costruire la ruota, figurarsi quelle macchine volanti che gli piacciono tanto.",
  en_title = "Super Reaper 6000",
  en_obj = "Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.",
}
T[1094] = {
  title = "Altre Istruzioni",
  desc = "Questa busta contiene tutte le informazioni che sono riuscito ad arraffare mentre mi buttavano fuori dalla porta... documenti interni della Venture Company, qualche manuale, roba tecnica... Ah, e naturalmente i progetti del Super Mietitore 6000.$B$BSputtervalve si è stabilito a Ratchet, nelle Barrens. Non dovresti far fatica a trovarlo: è un tipetto verde.",
  obj = "Consegna la Sealed Envelope a Sputtervalve, nelle Barrens.",
  progress = "Salve! Come posso aiutarti?",
  reward = "Fizziks, eh? Non posso dire di fidarmi di lui, ma queste informazioni sembrano valide quanto basta. Cosa non darei per togliermi la Venture Company dai piedi.$B$BPerò qualche bella macchina la tirano fuori... non posso negare che alcune delle migliorie che hanno messo a punto ci sono tornate utili.",
  en_title = "Further Instructions",
  en_obj = "Deliver the Sealed Envelope to Sputtervalve in the Barrens.",
}
T[1095] = {
  title = "Altre Istruzioni",
  desc = "La faccenda di questo gnomo assunto dalla Venture Company ha fatto un po' di rumore a Undermine. I principi del commercio non approvano che Razdunk si accompagni a questo Gerenzo.$B$BRiddlevox mi ha chiesto di occuparmi del problema, e sono sicuro che glielo abbiano ordinato uno o più principi del commercio. Naturalmente, il Direttore non me l'ha detto. Diciamo che ho un presentimento.$B$BComunque sia, Gerenzo va tolto di mezzo, e occuparsi di lui sarebbe una prova su misura per Fizziks.",
  obj = "Porta i nuovi ordini a Ziz Fizziks, nelle Stonetalon Mountains.",
  reward = "Eliminare Gerenzo? Ecco una prospettiva a cui non ho niente da obiettare.$B$BGli gnomi sono già abbastanza insopportabili di loro, ma quello che ho saputo di Gerenzo peggiora solo le cose. A quanto pare era uno dei capi ingegneri a Gnomeregan, dove lavorava al loro progetto segreto — non siamo mai riusciti a infiltrarci a Dun Morogh abbastanza a fondo da scoprire i dettagli precisi. È stato un fallimento. I nostri rapporti dicono che, qualunque cosa fosse, gli è letteralmente esplosa in faccia.",
  en_title = "Further Instructions",
  en_obj = "Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.",
}
T[1096] = {
  title = "Gerenzo Wrenchwhistle",
  desc = "Ho incontrato Gerenzo una volta, ma lascia che te lo dica: non è bello da vedere. La sua carne sembra marcire, e si è innestato metallo e ingranaggi sul corpo, sostituendo alcune membra con altre meccaniche.$B$BA nord-est di qui, ben al di sopra del Lago di Cragpool, lassù vicino alla ruota idraulica, Gerenzo sorveglia tutto il cantiere. Non c'è verso che io riesca a farmi strada combattendo fin là in cima, per non parlare di affrontare Gerenzo... Ma tu hai l'aria di potercela fare.$B$BSe lo uccidi per me, ti ricompenserò a dovere!",
  obj = "Porta Gerenzo's Mechanical Arm a Ziz Fizziks, nelle Stonetalon Mountains.",
  progress = "Sputtervalve vorrà una qualche prova che Gerenzo è morto. Credo che il suo braccio meccanico andrà bene.",
  reward = "Guarda quel coso... ci voleva uno gnomo per inventarsi una cosa del genere. Non riesco a capire perché uno dovrebbe tagliarsi un braccio e sostituirlo con quello, quando potrebbe benissimo tenerseli tutti e due e aggiungerne un terzo!$B$BGnomi, te lo dico io...$B$BAlmeno Gerenzo è fuori gioco. Speriamo che basti come prova e che Sputtervalve mi assegni a una delle officine del Tinkers' Union a Gadgetzan o magari perfino a Undermine.",
  en_title = "Gerenzo Wrenchwhistle",
  en_obj = "Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.",
}
T[1098] = {
  title = "Deathstalkers a Shadowfang",
  desc = "In vista dell'assalto a Shadowfang, due deathstalkers sono stati mandati alla fortezza a raccogliere informazioni. Sono passati molti giorni e non sono ancora tornati, ma se vogliamo sperare che l'attacco riesca, il loro rapporto ci serve!$B$BEcco il tuo compito, $N: va' a sud, allo Shadowfang Keep, e trova i Deathstalkers Adamant e Vincent. Se hanno bisogno di aiuto, aiutali.$B$BQuesta missione è tanto pericolosa quanto cruciale, $N. Non fallire.",
  obj = "Trova il Deathstalker Adamant e il Deathstalker Vincent.",
  reward = "Il corpo di Vincent è lì, spezzato e immobile.$B$BIl Deathstalker Adamant manderà comunque il suo rapporto a Hadrec... ma qualunque altro dettaglio avesse scoperto Vincent è destinato a restare con lui.$B$BEppure la sua mano stringe un piccolo monile...",
  en_title = "Deathstalkers in Shadowfang",
  en_obj = "Find the Deathstalker Adamant and Deathstalker Vincent.",
}
T[1099] = {
  title = "I Goblin Vincono!",
}
T[1100] = {
  title = "Lonebrow's Journal",
  desc = "Apri piano il logoro diario di Henrig Lonebrow....",
  obj = "Leggi l'Henrig Lonebrow's Journal.",
  progress = "Hai lo sguardo preoccupato, capisco che qualcosa non va....",
  reward = "Dici che questo diario l'hai trovato addosso a un nano morto? Dammi solo un momento per sfogliarlo...",
  en_title = "Lonebrow's Journal",
  en_obj = "Read Henrig Lonebrow's Journal.",
}
T[1101] = {
  title = "La Megera del Kraul",
  desc = "Povero Heralath! E questo nano... Lonebrow. Che anima coraggiosa era.$B$BNon possiamo permettere che il loro valore sia stato vano. Questa megera... Charlga Razorflank... va fermata.$B$BEntrare di nascosto nel Kraul sarà pericoloso, non c'è dubbio, e non abbiamo il tempo di avvisare Darnassus. $N, raduna un gruppo e uccidi la megera.$B$BCome prova della sua morte, portami il Razorflank's Medallion.",
  obj = "Porta il Razorflank's Medallion a Falfindel Waywarder a Thalanaar.",
  progress = "Queste terre restano in grave pericolo finché Charlga Razorflank raduna un esercito nella Razorfen Kraul.",
  reward = "Ora la megera riposa in pace: è una notizia fantastica, $N.$B$BDi questi tempi, così pericolosi, è un conforto trovare qualcuno coraggioso come te.$B$BOra che i servitori di Razorflank sono sistemati, possiamo riprendere a studiare la zona. Forse riusciremo a scoprire qualcosa di più su cosa abbia corrotto, esattamente, il luogo di riposo di Agamaggan.$B$BMa temo che anche qui la risposta sia un tradimento...",
  en_title = "The Crone of the Kraul",
  en_obj = "Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.",
}
T[1102] = {
  title = "Un Destino di Vendetta",
  desc = "Cairne è un capo nobile: è stato lui a unire il nostro popolo qui a Thunder Bluff.$B$BMa io, a differenza di altri, non riesco a perdonare così facilmente chi ci ha cacciati dalle terre dei nostri antenati. Per decenni il mio popolo ha abitato il sud delle Barrens, una terra per noi sacra. Ma molti nemici ci hanno scacciati da lì.$B$BAd attendere la vecchia megera, Charlga Razorflank, c'è un destino di vendetta: dentro Razorfen Kraul sta radunando un esercito immondo.$B$BPortami il Razorflank's heart, $N, e potrò morire in pace.",
  obj = "Porta il Razorflank's Heart ad Auld Stonespire a Thunder Bluff.",
  progress = "Il giorno in cui saprò che le immonde bestie di Razorfen Kraul sono state cacciate dalla loro immonda tana, potrò riposare in pace: la vendetta sarà compiuta.$B$BHai cacciato i verrospini dal Kraul? Mi porti buone notizie, sotto forma del Razorflank's heart?",
  reward = "Vedo che ora l'odiosa tribù di Razorfen Kraul conosce il dolore del mio popolo. Se lo sono meritato, quelle bestie immonde.$B$BScacciare qualcuno da una terra sacra è un peccato degno della vendetta più severa.$B$BGrazie, $N, di avermi aiutato nella mia sventura.",
  en_title = "A Vengeful Fate",
  en_obj = "Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.",
}
T[1103] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Salve, $Gfratello:sorella;! Sei $Gvenuto:venuta; anche tu a purificare queste acque e a far vedere a Islen che hai capito?$B$BIo lo spirito dell'acqua corrotto l'ho appena sconfitto, e stavo giusto per mettere sul braciere i bracciali e le gocce d'acqua che sono rimaste.$B$BCome dici? Ahhh. Quando qualcosa va storto, Tiev lo capisce fin troppo bene. Be', se hai bisogno di rivedere lo spirito dell'acqua puro, Tiev può darti una bella mano.$B$BPortami una water sapta da Islen, per provare che sei $Gpronto:pronta;, e io aspetterò a consegnare i pezzi.",
  obj = "Porta una Water Sapta a Tiev Mordune in Silverpine Forest se non sei $Griuscito:riuscita; a parlare con la Minor Manifestation of Water.",
  progress = "Ce l'hai la sapta, $Gfratello:sorella;?$B$BConosco uno che, dopo aver sconfitto lo spirito dell'acqua corrotto, ha avuto dei problemi — pare che abbia aspettato troppo e sia uscito dal mondo degli spiriti troppo presto per i suoi gusti. Non vorrei che capitasse a qualcun altro, perciò resto qui ancora un po', per essere sicuro che nessuno abbia bisogno del mio aiuto.",
  reward = "Ahhh, allora sei $Gpronto:pronta;...$B$BAdesso metto le cose nel braciere, e potrai parlare con lo spirito anche tu.$B$BE per guardare nel mondo degli spiriti con la sapta non devi preoccuparti per niente... il vecchio Tiev conosce qualche trucco su come funziona la magia della sapta.$B$BForza, $Gfratello:sorella;, scendi con me al santuario e parliamo insieme agli spiriti.",
}
T[1104] = {
  title = "Veleno della Piana Salata",
  desc = "Ho un sacco di progetti per la nostra auto a razzo! Un sacco! E devo provarli tutti!!$B$BSto lavorando a un nuovo tipo di carburante, uno che fa una fiamma davvero davvero davvero calda!! Non ho ancora trovato la miscela perfetta, ma credo di sapere cosa mi serve...$B$BGli scorpidi che girano per Shimmering Flats hanno un veleno pieno pieno di sale. È davvero unico! Ed è proprio quello che cercavo!$B$BPortami il veleno e fidati — la nostra auto volerà!!",
  obj = "Porta 6 Salty Scorpid Venoms a Fizzle Brassbolts a Shimmering Flats.",
  progress = "Ciao ciao ciao! Hai preso quel veleno??",
  reward = "Benissimo! Questo veleno funzionerà alla grande! Grazie, $N!$B$BAdesso devo solo farlo bollire finché non si riduce, applicare lo skipper-otomero, aggiungere un nega-catalizzatore e... Accidenti! Dove sono finiti i miei appunti!?",
  en_title = "Salt Flat Venom",
  en_obj = "Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats.",
}
T[1105] = {
  title = "Gusci Induriti",
  desc = "Mio fratello sta lavorando a un nuovo carburante per la sua auto a razzo. È geniale, davvero. Talmente geniale che... secondo me quello che sta progettando sarà abbastanza forte da mangiarsi il telaio dell'auto da parte a parte!$B$BVoglio rinforzare i serbatoi prima che succeda.$B$BLe tartarughe della piana hanno gusci durissimi, e voglio usarli per costruire nuovi serbatoi per la nostra auto a razzo: serbatoi che possano contenere il nuovo carburante di mio fratello.$B$BMi sembri abbastanza responsabile. Me li procureresti, quei gusci?",
  obj = "Porta 9 Hardened Tortoise Shells a Wizzle Brassbolts a Shimmering Flats.",
  progress = "Mio fratello sta facendo progressi con il nuovo carburante, e la cosa mi preoccupa. Devo mettermi al lavoro su un serbatoio di guscio di tartaruga il prima possibile!$B$B$N, ce li hai già quei gusci?",
  reward = "Li hai presi! Grazie, $N!$B$BCaspita, questi gusci sono più duri di quanto pensassi! Eh eh, per lavorarli mi sa che piegherò un'intera cassetta di attrezzi!",
  en_title = "Hardened Shells",
  en_obj = "Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats.",
}
T[1106] = {
  title = "Martek the Exiled",
  desc = "Sto costruendo un motore nuovo che farà andare la macchina velocissima! Così veloce che volerà, ne sono sicuro! Devo solo fare dei pistoni capaci di reggere sollecitazioni molto, molto forti. Le mie prove sono fallite tutte, perché non riesco a farli abbastanza duri!$B$BMa c'è qualcuno che forse sa come si fa.$B$BSi chiama Martek the Exiled. È un grande fabbro e di metallo ne sa più di chiunque altro. Portagli questa lettera, so che può aiutarmi!$B$BPerò è lontano lontano — in Azeroth, nelle Badlands, in un accampamento, insieme a un goblin!$B$BTrovalo!",
  obj = "Porta la Lettera di Fizzle a Martek the Exiled nelle Badlands.",
  progress = "Be', mi hai trovato. Buon per te.$B$BSei $Gvenuto:venuta; per l'ascia che ho fatto per Gath'Ilzogg? O per vendicare l'onore della Duchessa Pamay?$B$BAnzi, quale delle due non m'importa. Se vuoi combattere, facciamola finita...",
  reward = "Ti manda Fizzle? Be', allora è un'altra storia! Certo che ti aiuto. Fizzle e suo fratello sono fra i pochi che non mi vogliono morto!$B$BE così Fizzle vuole fare dei pistoni, eh? Pistoni abbastanza forti da reggere qualunque sollecitazione abbia in mente, e se conosco Fizzle, questa sua nuova macchina è un vulcano su ruote!",
  en_title = "Martek the Exiled",
  en_obj = "Bring Fizzle's Letter to Martek the Exiled in the Badlands.",
}
T[1107] = {
  title = "Encrusted Tail Fins",
  desc = "La nostra auto a razzo è la cosa più veloce della piana! Così veloce che... temo che l'attrito la farà a pezzi!$B$BPer evitarlo devo preparare un composto con cui rivestirne le parti mobili. Deve essere duro ma non fragile, e resistere alla corrosione del sale, altrimenti il tempo passato a Shimmering Flats se lo mangerà.$B$BHai sentito parlare della Vile Reef, $N? È al largo della costa di Stranglethorn Vale. Ci vivono i murlocs Saltscale, e le loro pinne di coda sono un ingrediente fondamentale del mio composto.",
  obj = "Porta 10 Encrusted Tail Fins a Wizzle Brassbolts a Shimmering Flats.",
  progress = "Hai le pinne di coda? Se non riesco a proteggere la nostra auto dalla sua stessa velocità, in queste corse non durerà a lungo.",
  reward = "Grazie, $N! Una volta macinate e fuse con qualche altro ingrediente, il composto sarà pronto, e a quel punto l'auto sarà al sicuro dalla sua stessa velocità.$B$BAl sicuro, almeno finché non va a sbattere contro qualcosa...",
  en_title = "Encrusted Tail Fins",
  en_obj = "Bring 10 Encrusted Tail Fins to Wizzle Brassbolts in the Shimmering Flats.",
}
T[1108] = {
  title = "Indurium",
  desc = "Se sto qui non è solo per tenermi lontano dalla gente. Nelle Badlands il metallo abbonda, $N, se hai il fegato di andarlo a prendere.$B$BSi chiama indurium e, per fortuna, dicono che regga molto bene il calore e le sollecitazioni. Potrebbe andar bene per la macchina di Fizzle.$B$BMa è meglio esserne sicuri. Portami dei campioni di indurium e ne metterò alla prova le proprietà.$B$BIl vero indurium ore sta nelle profondità di Uldaman, ma a volte i troggs Stonevault delle Badlands se ne portano addosso delle faville. Portami quelle faville.",
  obj = "Porta 10 Indurium Flakes a Martek the Exiled nelle Badlands.",
  progress = "Hai trovato delle indurium flakes, $N? La forgia è calda, pronta per metterle alla prova.",
  reward = "Ah sì, queste andranno benissimo. Ora mettiamole un po' sul fuoco e vediamo come se la cavano...",
  en_title = "Indurium",
  en_obj = "Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.",
}
T[1109] = {
  title = "E Uno, e Due, e Guano!",
  desc = "Come vedi, $N, qui alla Royal Apothecary Society stiamo conducendo esperimenti molto... interessanti.$B$BDa Maestro, tocca a me sovrintendere ai nostri tentativi alchemici più ambiziosi. Tanto lavoro e così poco tempo!$B$BPer essere $Gun:una; $C, sembri aver viaggiato parecchio. Forse puoi aiutarmi.$B$BMi serve una sostanza rara, un materiale ripugnante che viene da una specie di pipistrelli poco comune, presente solo in quel buco fangoso chiamato Razorfen Kraul. Portami il guano dei Kraul Bats e potremo metterci al lavoro...",
  obj = "Porta 1 mucchio di Kraul Guano a Master Apothecary Faranell a Undercity.",
  progress = "Ah, vedo che sei $Gtornato:tornata;. Ce l'hai fatta a procurarti del Kraul Guano?",
  reward = "Splendido, $N! Proprio quello che ci voleva per cominciare.",
  en_title = "Going, Going, Guano!",
  en_obj = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.",
}
T[1110] = {
  title = "Rocket Car Parts",
  desc = "Eh eh, con tutte le gare che si corrono da queste parti, non c'è da stupirsi se ogni tanto ci scappa un incidente. Fatti un giro nello Shimmering Flats e vedrai i segni dei vecchi schianti — ci sono rottami di rocket car parts sparsi dappertutto!$B$BE per gli gnomi e i goblin quelle parti valgono soldi. Sono sempre in cerca di altri aggeggi da schiaffare sulle loro macchine.$B$BQuindi va' là fuori e procurami un po' di quelle parti. Portamene un mucchio e ti pagherò bene.",
  obj = "Porta 30 Rocket Car Parts a Kravel Koalbeard in Shimmering Flats.",
  progress = "$N, sei $Gstato:stata; nella piana? Me l'hai portato, il carico di parti che volevo?",
  reward = "Wow, guarda qua! In quel mucchio di rottami c'è roba buona. Di sicuro riesco a piazzarlo per una bella somma.$B$BE... quello che vedo schiacciato fra quelle due lamiere è un orecchio?? Ahi! Eh, di sicuro non vorrei essere nei panni di quel pilota!$B$BGrazie, $N, ecco la tua paga. E in più un consiglio, gratis...$B$BSe cerchi bene, nella tragedia di qualcun altro un guadagno lo trovi sempre.",
  en_title = "Rocket Car Parts",
  en_obj = "Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats.",
}
T[1111] = {
  title = "Wharfmaster Dizzywig",
  desc = "Io di mestiere procuro alla gente quello che le serve, e agli gnomi laggiù serve qualcuno che porti a termine un ordine di pezzi. Glieli hanno spediti a Ratchet una settimana fa, ma io non ce l'ho fatta ad andarci.$B$BAllora, sei $Gpronto:pronta; per una bella camminata? Va' a Ratchet e porta quest'ordine dei pezzi a Wharfmaster Dizzywig — probabilmente lo trovi al molo.$B$BFallo per me, e di lavori per te ne avrò altri.$B$BLavori, $Gamico mio:amica mia;, che possono rendere parecchio...",
  obj = "Porta il Kravel's Parts Order a Wharfmaster Dizzywig a Ratchet.",
  progress = "Avanti, parla! Dimmi: devi consegnare o ritirare?",
  reward = "Ah, sì. Le parti per Kravel. Meno male che sei qui. Questa roba sta qui fuori da giorni, e avevo paura che arrugginisse!",
  en_title = "Wharfmaster Dizzywig",
  en_obj = "Bring Kravel's Parts Order to Wharfmaster Dizzywig in Ratchet.",
}
T[1112] = {
  title = "Parti per Kravel",
  desc = "Ecco il pacco di Kravel, $N. E quando glielo porti, digli... che se vuole altri ordini speciali, prima deve saldare il conto!",
  obj = "Porta le Kravel's Parts a Kravel Koalbeard a Shimmering Flats.",
  progress = "Allora, ce l'hai fatta ad arrivare fino a Ratchet e a prendere le parti?",
  reward = "Ottimo, ce le hai! Adesso bisogna portarle agli gnomi. Ma prima...$B$BTiriamo fuori un piccolo oggetto...",
  en_title = "Parts for Kravel",
  en_obj = "Bring Kravel's Parts to Kravel Koalbeard in the Shimmering Flats.",
}
T[1113] = {
  title = "Hearts of Zeal",
  desc = "Ti starai chiedendo perché mi serva un guano così raro. Be', con questo esperimento voglio vedere come agiscono l'una sull'altra due sostanze chimiche diametralmente opposte, soprattutto se le combino entrambe con un agente sempre tossico, per essere sicuro di ottenere i risultati più... raccapriccianti.$B$BSulle vette a nord-est delle Tirisfal Glades sorge lo Scarlet Monastery, dove si radunano i folli discepoli della Scarlet Crusade. Uccidili e portami i loro cuori zelanti.$B$BIl nostro intruglio sarà davvero malvagio!",
  obj = "Master Apothecary Faranell a Undercity vuole 20 Hearts of Zeal.",
  progress = "Sei $Gtornato:tornata; dallo Scarlet Monastery? Per questo delizioso esperimento mi serviranno molti cuori!$B$BDi certo anche Varimathras e la Dama Oscura saranno lieti di sbarazzarsi della Feccia Scarlatta...",
  reward = "Caspita, $N, quanto sangue e quante budella mi hai portato! Hai fatto davvero un lavoro eccellente!",
  en_title = "Hearts of Zeal",
  en_obj = "Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.",
}
T[1114] = {
  title = "Consegna agli Gnomi",
  desc = "Ora che ho quello che mi serve, porta questi pezzi a Fizzle Brassbolts. È da tanto che li aspetta — sono sicuro che non si accorgerà del pezzettino che ho tolto dal suo ordine...$B$BE io non starei a dirglielo. Era piccolo e non valeva niente.$B$BFidati.",
  obj = "Porta i Delicate Car Parts a Fizzle Brassbolts in Shimmering Flats.",
  progress = "Hai qualcosa per me? Fantastico! Fa' vedere!",
  reward = "Eccoli! I miei cricchetti idraulici e i miei bulloni a ripetizione! Andranno benissimo. Grazie!",
  en_title = "Delivery to the Gnomes",
  en_obj = "Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats.",
}
T[1115] = {
  title = "Il Pettegolo",
  desc = "Abbiamo reso un servizio agli gnomi: adesso è il momento di fare un favore ai goblin!$B$BHo sentito dire che il pilota da corsa goblin, Nazz Steamboil, non si è sempre chiamato così. Chissà perché ha cambiato nome. Chissà se è un segreto e... chissà se ci tiene, a quel segreto.$B$BSe c'è qualcuno che sa la verità, è Krazek of Booty Bay, sulla punta meridionale di Stranglethorn. Parla con Krazek e chiedigli del nostro pilota goblin.$B$BSe riesci a cavargli qualche informazione utile, potremmo anche guadagnarci.",
  obj = "Parla con Krazek a Booty Bay.",
  reward = "Vuoi sapere di Nazz Steamboil? Fa il pilota da corsa nelle Shimmering Flats, giusto?$B$BSì, forse qualcosa su di lui riesco a scoprirlo... ma non sarà facile. Né veloce.$B$BNé economico.",
  en_title = "The Rumormonger",
  en_obj = "Talk to Krazek in Booty Bay.",
}
T[1116] = {
  title = "Dream Dust nella Palude",
  desc = "Trovarti le informazioni su Nazz è un bel favore, $N. Sì, proprio un bel favore. Però sei $Gvenuto:venuta; fin dalle Shimmering Flats per averle... sei $Gdisposto:disposta; a viaggiare ancora un po'?$B$BIntanto che sento le mie fonti, perché non mi raccogli qualcosa, eh?$B$BUhm... vediamo, che cosa? Che ne dici della dream dust dei dragon whelps della Swamp of Sorrows? Sì, un po' di dream dust per il mio sacchetto del tabacco da fiuto mi piacerebbe proprio!$B$BPortamela, $N, e avrai le informazioni che cerchi.",
  obj = "Porta 10 Specks of Dream Dust a Krazek a Booty Bay. La Dream Dust si raccoglie dai dragon whelps della Swamp of Sorrows.",
  progress = "Già di ritorno? Ce l'hai la mia dream dust?",
  reward = "Ma guarda un po': hai trovato la dream dust!$B$BE la palude, $N, ti è piaciuta? Laggiù non è facile trovare un pasto caldo, eh?",
  en_title = "Dream Dust in the Swamp",
  en_obj = "Bring 10 Specks of Dream Dust to Krazek in Booty Bay.  Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.",
}
T[1117] = {
  title = "Voci per Kravel",
  desc = "Ho dovuto giocarmi qualche favore, separarmi da una rara bottiglia di vino elfico e fare un bel po' di deduzioni per conto mio! Ma le informazioni che cerchi le ho trovate.$B$BEcco, ti ho scritto una lettera con certi dettagli molto interessanti sul nostro amico Nazz Steamboil. Fanne quello che vuoi — per me è troppo pericolosa da usare.$B$BMa a nessuno devi dire dove l'hai presa!",
  obj = "Porta le Goblin Rumors a Kravel Koalbeard a Shimmering Flats.",
  progress = "Hai scoperto qualcosa su Nazz Steamboil? Qualcosa che vorrebbe tenere segreto??",
  reward = "Bene bene! Interessante... molto interessante. Eh eh, la prossima volta che vedo il pilota goblin forse dovrei fargli un inchino.$B$BQuesta roba vale parecchio, $N. Sono sicuro che Nazz pagherà una piccola fortuna per mantenere il suo segreto... segreto.",
  en_title = "Rumors for Kravel",
  en_obj = "Bring the Goblin Rumors to Kravel Koalbeard in the Shimmering Flats.",
}
T[1118] = {
  title = "Ritorno a Booty Bay",
  desc = "$N, sei $Gun:una; $C di cui mi posso fidare, che si tratti di portare a termine il lavoro o di tenere la bocca chiusa mentre lo fai.$B$BSto architettando un nuovo piano. È rischioso, ma se funziona potremmo farci un sacco di soldi tutti e due! E credo che tu sia proprio la persona giusta per portarlo fino in fondo.$B$BPer cominciare, devi tornare a Booty Bay. Perdonami, $Gbuon:buona; $N. Lo so che il mio ultimo incarico ti ci ha già portato. Ma stavolta parla con Crank Fizzlebub.$B$BDagli questa lettera, e se gli serve una mano, fa' del tuo meglio. Ne varrà la pena.",
  obj = "Porta il Kravel's Scheme a Crank Fizzlebub a Booty Bay.",
  progress = "Salve, salve. E che ci fa $Gun:una; nobile $R come te quaggiù a Booty Bay?",
  reward = "Capisco. Kravel ha in mente un gran piano. Ha una mente sinistra — ed è una delle cose che mi piacciono di lui.$B$BQuindi ti serve qualcosa che annebbi il cervello, eh? Qualcosa di potente...$B$BChissà se si potrebbe usare la miscela che Zanzil dà da mangiare ai suoi zombi...",
  en_title = "Back to Booty Bay",
  en_obj = "Bring Kravel's Scheme to Crank Fizzlebub in Booty Bay.",
}
T[1119] = {
  title = "Zanzil's Mixture e una Fool's Stout",
  desc = "Ho capito come fare una bevanda potente con la mistura di Zanzil e la birra scura: una Fool's Stout. Credo sia proprio quello che serve a Kravel, ma tu provala e fammi sapere come va.$B$BE, $N, non tenere questa roba troppo a lungo senza usarla. La mistura di Zanzil fa uno strano effetto al lievito della birra, lo manda su di giri, quindi non resterà fresca per sempre.",
  obj = "Riporta la Fool's Stout a Kravel nello Shimmering Flats.",
  progress = "Salve, $N. Fizzlebub ce l'ha fatta ad aiutarci?",
  reward = "Magnifico! Fizzlebub non ci ha deluso! Me ne ricorderò, la prossima volta che lo vedo.$B$BE grazie, $N. Stai facendo un ottimo lavoro, e con questa storia ci faremo un bel po' di soldi tutti e due...",
  en_title = "Zanzil's Mixture and a Fool's Stout",
  en_obj = "Bring the Fool's Stout back to Kravel in the Shimmering Flats.",
}
T[1120] = {
  title = "Fai Ubriacare gli Gnomi",
  desc = "Dobbiamo provare la Fool's Stout su una delle squadre della fossa. Se vuoi provare con gli gnomi, tieni — portala allo gnome pit boss.$B$BE non metterci troppo. Prima o poi andrà a male.",
  obj = "Porta la Fool's Stout allo Gnome Pit Boss.",
  progress = "Ciao! Hai qualcosa per me?",
  reward = "Birra scura? Che pensiero gentile! Grazie!$B$BCon la gara alle porte non dovremmo bere, ma... forse ai miei ragazzi un goccio farebbe bene. E poi non può mica essere così forte, no?",
  en_title = "Get the Gnomes Drunk",
  en_obj = "Bring the Fool's Stout to the Gnome Pit Boss.",
}
T[1121] = {
  title = "Fai Ubriacare i Goblin",
  desc = "Dobbiamo provare la Fool's Stout su una delle squadre della fossa. Se vuoi provare con i goblin, tieni — portala al boss goblin della fossa.$B$BE non metterci troppo. Prima o poi andrà a male.",
  obj = "Porta la Fool's Stout al Goblin Pit Boss.",
  progress = "Che hai da guardare?",
  reward = "E questo che cos'è? Alcol, eh?$B$BBeh, se ne beviamo solo un goccio non mi dispiace...",
  en_title = "Get the Goblins Drunk",
  en_obj = "Bring the Fool's Stout to the Goblin Pit Boss.",
}
T[1122] = {
  title = "Fai Rapporto a Fizzlebub",
  desc = "Quella Fool's Stout ha funzionato a meraviglia! Ho puntato sulla prossima corsa e... speriamo che la squadra che hai fatto ubriacare abbia conciato per bene la loro macchina!$B$BTi resta un'ultima cosa da fare — riporta questo biglietto a Crank Fizzlebub a Booty Bay. Vorrà sapere che la prova è riuscita.$B$BE speriamo di avere altra Fool's Stout per le prossime corse!",
  obj = "Porta il rapporto sulla Fool's Stout a Crank Fizzlebub a Booty Bay.",
  progress = "Ciao, $N. Allora, com'è andata con quella birra scura? Roba forte, eh?",
  reward = "Qui dice che la fool's stout è stata un successo. Bella notizia!$B$BSe mai ne vorrai ancora, fammelo sapere e ti farò raccogliere altra Zanzil's Mixture.",
  en_title = "Report Back to Fizzlebub",
  en_obj = "Bring the Fool's Stout report to Crank Fizzlebub in Booty Bay.",
}
T[1123] = {
  title = "Rabine Saturna",
  desc = "Per questo compito, il maggiordomo di Keeper Remulos a Moonglade — Rabine Saturna — cerca aiuto per esplorare le vaste terre desolate molto a ovest di Tanaris e di Un'Goro. Si trova a Nighthaven, il villaggio principale di Moonglade.$B$BVoglio farti capire quanto sia importante la tua presenza. Tra gli elfi della notte di Darnassus e il Cenarion Circle di Moonglade la tensione sta crescendo. Nei rapporti con il Circolo, laggiù, guarda oltre i confini tra le razze e attingi alla saggezza dei tuoi antenati, $N. Buona fortuna.",
  obj = "Parla con Rabine Saturna nel villaggio di Nighthaven, a Moonglade. Moonglade si trova tra Felwood e Winterspring, e si raggiunge da un sentiero che parte da Timbermaw Hold.",
  reward = "Sono Rabine Saturna, e a nome di Keeper Remulos e di tutti gli abitanti di questa radura sacra ti do il benvenuto.$B$BApprezzo il tuo interesse e il tuo desiderio di aiutare il Cenarion Circle. I tauren hanno dimostrato una straordinaria devozione ai precetti di Cenarius, e grazie a loro l'Orda trova accoglienza e sicurezza in questa radura. La salvaguardia di Azeroth è un obiettivo che abbiamo in comune.$B$BQui sei tra amici, $N.",
  en_title = "Rabine Saturna",
  en_obj = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.",
}
T[1124] = {
  title = "Landa Desolata",
  desc = "A ovest dell'Un'Goro Crater, oltre la cresta a nord-ovest, si stende una landa aspra e desolata — Silithus. Pochi sanno che lì, in tempi antichi, si combatté una guerra tra gli elfi della notte e un potere alieno e maligno. Il male fu sigillato, ma ora sospettiamo che qualcuno stia cercando di risvegliare questo... orrore indicibile.$B$BCerca Layo Starstrike, uno dei nostri agenti a Silithus; lo troverai al Valor's Rest, l'ultima dimora dei caduti di quelle terre. Consegnagli questa lettera e si fiderà di te.",
  obj = "Parla con Layo Starstrike vicino al cimitero di Valor's Rest a Silithus e mostragli la Rabine's Letter.",
  progress = "Non è il caso di aggirarsi con tanta leggerezza in una terra così pericolosa, $C. Cosa ti porta nelle lande desolate di Silithus?",
  reward = "Ti ha mandato Rabine, eh? Be', considerati $Gbenvenuto:benvenuta;... per quanto questa terra desolata e abbandonata possa accogliere qualcuno.$B$BNon ero ancora nato all'epoca delle grandi tribolazioni che si consumarono qui, ma certi angoli di questo deserto restituiscono un'immagine inquietante di quel passato dimenticato. Con il tuo aiuto, il Cenarion Circle potrebbe riuscire a porre fine una volta per tutte a una minaccia che avrebbe dovuto estinguersi generazioni fa.",
}
T[1125] = {
  title = "Gli Spiriti di Southwind",
  desc = "A sud-ovest di qui c'è un luogo tragico — le rovine di Southwind Village. È da lì che deve cominciare il nostro lavoro, $N.$B$BDa quanto abbiamo scoperto, in passato il villaggio era una base operativa degli elfi della notte a Silithus. Ormai da molto tempo è stato invaso dalle colonie di silithid che infestano queste lande. Posso solo immaginare l'orrore dei primi momenti, quando fu distrutto...$B$BGli spiriti tormentati di druidi e sentinelle caduti vagano senza meta fra i ruderi. Esplora la zona e, se serve, libera le anime di questi poveri esseri.",
  obj = "Libera gli spiriti di 8 Tortured Druids e 8 Tortured Sentinels a Southwind Village, poi torna da Layo Starstrike al cimitero di Valor's Rest a Silithus.",
  progress = "Alleanza o Orda, non importa — nessuno merita di restare intrappolato in questo mondo come uno spirito tormentato. Liberando queste anime rimetterai le cose a posto, $N.",
  reward = "Sospettavo che l'enorme alveare vorticante vicino alle rovine c'entrasse qualcosa con la fine del villaggio. Quello che hai fatto sembra confermarlo: così vicino, l'alveare minaccia qualunque attività vorremo svolgere qui in futuro.$B$BTi ringrazio per la generosità con cui hai liberato le anime dei caduti; so che non è mai un compito facile. Quando sarai $Gpronto:pronta;, però, vorrei chiederti di aiutarmi ancora una volta...",
}
T[1126] = {
  title = "Alveare nella Torre",
  desc = "Dobbiamo occuparci dell'alveare di Southwind Village, e credo di sapere come arrivarci. So per esperienza che gli alveari dei silithid sono molto sensibili a ciò che li circonda; per questo attaccano quando sentono i lamenti funebri degli spiriti.$B$BI silithid si concentrano soprattutto nella torre — quella con lo sciame di vespe che le gira intorno. Scalala e scuoti l'alveare per risvegliarlo. Riferiscimi quello che scopri, ma fa' attenzione! Se trovi qualcosa che potrebbe esserci utile, portamelo.",
  obj = "Scala la torre di Southwind Village e trova un modo per risvegliare l'alveare dei silithid. Porta a Layo Starstrike, al cimitero di Valor's Rest a Silithus, qualunque cosa insolita ti capiti di trovare nel frattempo.",
  progress = "Allora, ha funzionato? Sei ancora $Gtutto intero:tutta intera;, ed è già una buona notizia. Hai trovato qualcosa?",
  reward = "Ma che... cos'è?$B$BHa la forma di una... scatola, forse? È incrostato da far paura. Aspetta, qui c'è un punto scoperto... è un libro, quello sotto tutta questa sporcizia?$B$BCredo che tu abbia fatto per caso una bella scoperta, $N... o almeno lo spero. Forse è un diario o un registro di tempi antichi, conservato in questo guscio.$B$BPenso di sapere come capire di cosa si tratta.",
}
T[1127] = {
  title = "Fool's Stout",
  desc = "Allora vuoi un po' di Fool's Stout, eh? Hai in mente di tornare alle gare...?$B$BVa bene: portami dell'altra mistura di Zanzil e io te ne preparo ancora.",
  obj = "Porta 12 Zanzil's Mixture a Crank Fizzlebub a Booty Bay.",
  progress = "Le hai già, quelle misture di Zanzil, $N?",
  reward = "Ah, benissimo! Ecco la tua paga.$B$BE questo è un piccolo extra... per la tua discrezione.",
}
T[1130] = {
  title = "Melor Manda un Messaggio",
  desc = "$N, le tue imprese sono arrivate alle orecchie di Melor Stonehoof, e lui ha tracciato un cammino per te.$B$BSe vuoi percorrerlo, va' a Thunder Bluff e parla con Melor: lo troverai sull'Hunter's Rise.",
  obj = "Parla con Melor Stonehoof a Thunder Bluff.",
  reward = "Così sei $Gvenuto:venuta;, $N. E sei $Gpronto:pronta; a viaggiare per terre lontane?$B$BSe è così, giovane $C, continua ad ascoltare...",
  en_title = "Melor Sends Word",
  en_obj = "Speak with Melor Stonehoof in Thunder Bluff.",
}
T[1131] = {
  title = "Steelsnap",
  desc = "A volte cacciamo per nutrirci, a volte per l'onore. E a volte cacciamo per guadagnarci gli insegnamenti della Madre Terra.$B$BMa la caccia che ti affido ora non è nessuna di queste: devi uccidere una creatura che sta fuori dalla benedizione della Madre Terra.$B$BLa iena Steelsnap si aggira per Thousand Needles, a sud di Barrens. È un tiranno: attira a sé altre iene e semina paura e spargimenti di sangue fra le bestie più pacifiche.$B$BTrova Steelsnap, $N. Trovalo e sconfiggilo.",
  obj = "Porta la Steelsnap's Rib a Melor Stonehoof a Thunder Bluff.",
  progress = "$N, hai sconfitto l'immondo Steelsnap?",
  reward = "Hai sconfitto la creatura Steelsnap, e così hai purificato Thousand Needles da un'orribile contaminazione.$B$BE questa, $N, è la tua lezione di oggi.",
  en_title = "Steelsnap",
  en_obj = "Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff.",
}
T[1134] = {
  title = "I Pridewing di Stonetalon",
  desc = "Con l'Orda non siamo in guerra aperta, ma la nostra pace è fragile. Spesso sorprendiamo i loro agenti ad agire contro di noi, di nascosto.$B$BUna di queste mosse ce l'hanno rivelata fonti segrete a Theramore: dicono che gli orchi raccolgono il veleno dei pridewing presso il Mirkfallon Lake, nelle Stonetalon Mountains a sud. Poi gli assassini orchi lo usano nelle loro incursioni segrete e mortali contro l'Alleanza!$B$BSe è vero, $N, dobbiamo fermarli e togliere loro la fonte del veleno.",
  obj = "Porta 12 Pridewing Venom Sacs a Shindrell Swiftfire ad Astranaar.",
  progress = "Hai le pridewing venom sacs, $N? Non possiamo lasciare che gli orchi usino contro di noi i veleni di quelle bestie!",
  reward = "Grazie, $N. Mi rattrista ordinare il massacro di creature che forse aiutano i nostri nemici senza volerlo, ma è il mio dovere.$B$BIl tuo cuore potrà piangere per i pridewing che hai ucciso, $Gamico mio:amica mia;, ma possa poi allargarsi al pensiero che i tuoi alleati sono al sicuro dal loro veleno.",
  en_title = "Pridewings of Stonetalon",
  en_obj = "Bring 12 Pridewing Venom Sacs to Shindrell Swiftfire in Astranaar.",
}
T[1135] = {
  title = "Il Veleno di Highperch",
  desc = "Forse lo sai già: gli orchi addomesticano spesso le viverne e le usano come cavalcature. Pochi sanno, invece, che in certi ambienti il veleno di una viverna vale più della bestia stessa. Perciò, se andare un po' a caccia di viverne non ti fa paura, allora... ho un lavoro per te.$B$BNella terra di Thousand Needles, a ovest di qui, c'è un posto che si chiama Highperch. Le viverne di Highperch hanno un veleno potente. Potente, e prezioso.",
  obj = "Porta 10 Highperch Venom Sacs a Fiora Longears a Theramore.",
  progress = "Hai trovato Highperch, $N? E con le viverne laggiù, hai avuto fortuna?",
  reward = "Ah, queste sono quasi tutte sul punto di scoppiare dal veleno, $N. Di solito si trovano così solo nelle viverne giovani o nelle femmine fertili. Lassù a Highperch dev'essere stata una bella strage!",
  en_title = "Highperch Venom",
  en_obj = "Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore.",
}
T[1136] = {
  title = "Frostmaw",
  desc = "$N, è tempo che tu parta per terre lontane. Sei $Gpronto:pronta;.$B$BDarai la caccia a Frostmaw, uno yeti delle Alterac Mountains. È una creatura sfuggente: il suo pelo bianco si confonde con le nevi delle montagne in cui vive, e si mostra di rado.$B$BMa io ti insegnerò ad attirare una creatura come lui. Ecco, prendi questa pergamena: ci ho scritto come adescare Frostmaw.$B$BOra va', $N. Il viaggio è lungo e ti attendono molte sfide. Il tuo compito sarà concluso solo quando tornerai con il manto di Frostmaw.",
  obj = "Porta il Frostmaw's Mane a Melor Stonehoof a Thunder Bluff.",
  progress = "Sei $Gstato:stata; nelle Alterac Mountains, $N? Hai affrontato lo sfuggente Frostmaw?",
  reward = "Per trovare e sconfiggere Frostmaw ci volevano forza e astuzia, $N, e tu le possiedi entrambe.$B$BIl tuo sentiero ti ha portato nelle valli di Thousand Needles e sulle alte montagne di Alterac. Un giorno ti condurrà per tutte le terre della Madre Terra, perché questa è la via del cacciatore.",
  en_title = "Frostmaw",
  en_obj = "Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff.",
}
T[1137] = {
  title = "Notizie per Fizzle",
  desc = "L'indurium resiste al calore in modo incredibile! Di sicuro andrà bene per i pistoni di Fizzle. Ma gli servirà il vero indurium ore, non solo le scaglie.$B$BIl minerale bisogna estrarlo dalle profondità di Uldaman, al confine settentrionale delle Badlands. È lì la vera fonte dell'indurium.$B$BPorta i miei saluti a Fizzle Brassbolts e ripetigli quello che ti ho detto.$B$BBuon viaggio, $N. E non mi stupirei di rivederti — appena Fizzle saprà dell'indurium, probabilmente ti manderà a Uldaman a procurarlo!",
  obj = "Parla con Fizzle Brassbolts nelle Shimmering Flats.",
  reward = "$N, sei $Gtornato:tornata;! Hai trovato Martek? Gli hai parlato? Che ti ha detto? Ci può aiutare??$B$BDimmi, dimmi, dimmi!!",
  en_title = "News for Fizzle",
  en_obj = "Speak with Fizzle Brassbolts in the Shimmering Flats.",
}
T[1139] = {
  title = "Le Tablets of Will Perdute",
  desc = "Tagliando fuori il clan Shadowforge da Blackrock Spire l'abbiamo rallentato, ma la missione di Hammertoe non è ancora compiuta, e lui non può essere morto invano. Il suo sogno era trovare la Tablet of Will: un frammento di pietra su cui i titani in persona incisero una magia che li aiutava a infondere la vita nelle loro creazioni — e a dar loro una volontà propria, o almeno così raccontano le leggende.$B$BDobbiamo ancora recuperare la Tavoletta prima che la trovi il clan Shadowforge.$B$BTorna a Uldaman, trova la tavoletta e portala qui subito.",
  obj = "Trova la Tablet of Will e portala ad Advisor Belgrum a Ironforge.",
  progress = "Bisogna portare a termine la missione di Hammertoe, $N. Glielo devo.$B$BÈ indispensabile che tu torni a Uldaman, e non solo per questo: ne va della sicurezza di tutta la stirpe dei nani. Se la tavoletta finisse nelle mani dei Dark Irons, chissà quanto diventerebbe potente il loro esercito di golem.",
  reward = "<Advisor Belgrum scuote la testa, incredulo, mentre gli porgi il frammento di pietra.>$B$B$N, è straordinario. Lo farò portare al più presto ai maghi del re, che vorranno studiarlo per capire se le leggende dicono il vero. Ma di questo parleremo un'altra volta: hai aiutato il nostro popolo più di quanto avrei mai immaginato — grazie.",
  en_title = "The Lost Tablets of Will",
  en_obj = "Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.",
}
T[1140] = {
  title = "La Tower of Althalaxx",
  desc = "Gli orchi scrivono poco meglio di come scarabocchia un bambino. Molti nel mio ordine hanno riso di me quando ho deciso di imparare la loro lingua, ma conoscere meglio i miei nemici mi è tornato utile.$B$BDagli scarabocchi di Ilkrud pare che Athrikus abbia ancora due gemme dell'anima, custodite a Night Run e a Satyrnaar, zone in mano ai satiri nel nord-est di Ashenvale.$B$BLà fuori stai $Gattento:attenta;, $N, i templi dei satiri sono intrisi di sangue e possono turbare anche $Gun:una; $C $Gesperto:esperta; come te.",
  obj = "Libera le anime intrappolate degli Highborne a Night Run e a Satyrnaar, poi torna da Delgren the Purifier a Maestra's Post.",
  progress = "Una volta ho sentito dire sottovoce che la storia dei satiri è in qualche modo legata a quella degli elfi della notte, ma i miei stimati ospiti si sono dimostrati restii a parlarne.",
  reward = "Forse si è lasciato che i satiri restassero troppo a lungo nella foresta. Ne parlerò con Elissa la prossima volta che sarò ad Auberdine.$B$BIn ogni caso, ora che le gemme dell'anima sono distrutte, Athrikus avrà molto meno potere. Dobbiamo approfittarne per eliminare lui e il suo culto.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post.",
}
T[1142] = {
  title = "La Vita Svanisce",
  desc = "Mi resta poco da vivere... sono così... così... debole.$B$B...il c-c-coraggioso nano, Lonebrow, è stato mandato ad a-a-avvisare Falfindel...$B$BMa prima che io... m-m-muoia...$B$B...mia moglie, Treshala... il pendente che la lega a me... l'ha rubato... uno degli i-i-immondi aggressori...$B$BTrovalo, p-p-per favore... e riportalo a Treshala, a Darnassus...$B$B...e portale la n-n-notizia della mia solitaria... morte.",
  obj = "Trova e riporta il Treshala's Pendant a Treshala Fallowbrook a Darnassus.",
  progress = "Che cosa ti porta a casa mia, $R?",
  reward = "No!$B$BCiò non è giusto. Oh, mondo crudele e intollerabile!$B$BOra tocca a me portare questo fardello di dolore, e fare in modo che l'opera di Heralath non muoia con lui.$B$BSei $Gstato:stata; $Gcoraggioso:coraggiosa; a venire da un luogo così pericoloso, $N. Ma ora, ti prego, lasciami.$B$BPiangerò in solitudine.",
  en_title = "Mortality Wanes",
  en_obj = "Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.",
}
T[1143] = {
  title = "La Tower of Althalaxx",
  desc = "Capisco. Be', se le cose stanno come dici, allora è ora di colpire. Credo che Athrikus sia in cima alla torre. Però stai $Gattento:attenta;, intorno a lui ci sono molti stregoni potenti, ben più letali di quelli che hai affrontato finora.",
  obj = "Uccidi Athrikus Narassin e porta la sua testa a Balthule Shadowstrike vicino alla Tower of Althalaxx.",
  progress = "Athrikus Narassin è uno stregone antico e potente. Forse dovremmo aspettare l'aiuto di Delgren, ma se ti ha mandato $Gda solo:da sola;, vuol dire che si fida molto di te.",
  reward = "Ora che Athrikus è morto, spero che le forze demoniache vengano respinte da questa zona. Di sicuro si riorganizzeranno e torneranno, ma allora saremo ancora più pronti ad affrontarle.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Kill Athrikus Narassin and bring his head to Balthule Shadowstrike near the Tower of Althalaxx.",
}
T[1144] = {
  title = "Willix the Importer",
  desc = "Finalmente sono arrivati i soccorsi!$B$BNon hai idea da quanto tempo mi tengono prigioniero qui dentro. Non mi ricordo nemmeno più l'ultima volta che ho visto il mondo là fuori.$B$BVedi, io sono un imprenditore: sempre a caccia di un soldo, come si dice. Mi era arrivata voce che Mebok Mizzyrix pagava bene il Tubero Fogliarossa di questo porcile, e pensavo di entrare e uscire senza problemi. Come vedi, mi sbagliavo un pochino!$B$BComunque, se sarai così gentile da aiutarmi a uscire di qui, farò in modo che ne valga la pena.",
  obj = "Scorta Willix the Importer fuori da Razorfen Kraul.",
  reward = "Grazie ancora, $Gamico:amica;! Te l'avevo detto che ne sarebbe valsa la pena.",
  en_title = "Willix the Importer",
  en_obj = "Escort Willix the Importer out of Razorfen Kraul.",
}
T[1145] = {
  title = "Lo Sciame Cresce",
  desc = "Tanti viaggiatori passati dal Crossroads mi hanno aiutato a raccogliere uova dal Field of Giants, e molti raccontano quanto siano letali quelle creature. Ne ho sentite abbastanza da pensare che quegli insetti siano una minaccia molto più grande di quanto credessero all'inizio i miei padroni.$B$BMi serve un corriere che vada a Orgrimmar da Belgrom Rockmaul. Questa non essere cosa da poco: deve andarci qualcuno che prenda il compito sul serio.$B$BBelgrom di solito stare fuori dalla sede della gilda dei guerrieri.",
  obj = "Consegna il Korran's Sealed Note a Belgrom Rockmaul a Orgrimmar.",
  progress = "Ti invidio, $C. Hai l'aria di chi è rimasto a lungo lontano dalle mura di Orgrimmar.$B$BAnch'io viaggerei in nome del Capoguerra, se Thrall non avesse bisogno delle mie capacità qui in città. Ma ci guida bene e mi fido del suo giudizio — resto qui finché avrà bisogno di me.",
  reward = "Ah, un messaggio di Korran. È un servitore fedele ormai da tempo. Mi chiedevo come stesse andando il suo lavoro al Crossroads.",
  en_title = "The Swarm Grows",
  en_obj = "Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar.",
}
T[1146] = {
  title = "Lo Sciame Cresce",
  desc = "Allora anche Korran è arrivato a una conclusione simile su questi insetti — sembrano una minaccia più grande di quanto credessimo.$B$BQualche giorno fa mi è tornato un cacciatore da Thousand Needles, quasi morto. Era in un gruppo d'assalto mandato a cacciare una squadra di scavo nanica dalle Shimmering Flats. Durante l'attacco, altri di questi insetti sono sbucati da una grotta del sito di scavo e per poco non hanno sterminato il gruppo.$B$BA guidarlo era Moktar Krin, e si sono rifugiati al confine delle Shimmering Flats. Portagli questa lettera.",
  obj = "Consegna la Belgrom's Sealed Note a Moktar Krin a Thousand Needles.",
  progress = "È la guerra che porta me e il mio gruppo alle Shimmering Flats, $C. E tu, cosa ti porta qui?",
  reward = "Non badare agli echi che rimbombano come tuoni sulle pareti delle montagne. Là fuori, nelle Flats, goblin e gnomi fanno gare di corsa su mostruosità create da quella che chiamano scienza. Qui a Thousand Needles ci sono minacce più grandi, e una di queste ha ucciso più di metà del mio gruppo da guerra.$B$BMa restiamo qui finché non avremo notizie da Belgrom a Orgrimmar. Fino ad allora teniamo la posizione e stiamo all'erta.",
  en_title = "The Swarm Grows",
  en_obj = "Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles.",
}
T[1147] = {
  title = "Lo Sciame Cresce",
  desc = "Mmh. Pare che per Belgrom quei mostri siano una minaccia, e vuole che siano ricacciati in qualunque abisso da cui sono strisciati fuori.$B$BImmagino che uccidere i nani inviati dall'Explorers' League non sia bastato — ora tocca a me mandare un gruppo da guerra mezzo morto in un'altra battaglia. Da soli non ce la faremo, non messi così. Il sito di scavo è qui a sud, e non dovrebbero esserci altri nani da affrontare. Te la senti di impugnare una lama o un bastone e fare la tua parte per aiutarci?",
  obj = "Uccidi 5 Silithid Searchers, 5 Silithid Hive Drones e 5 Silithid Invaders e torna da Moktar Krin a Thousand Needles.",
  progress = "Con tutti i viaggiatori che vanno alle Flats per quelle corse, sono sicuro che convinceremo abbastanza avventurieri ad aiutarci a ricacciare quegli insetti. Finché non ci saremo riusciti, io e il mio gruppo non potremo andarcene.",
  reward = "Ah! Con tutto quell'icore addosso sei persino più $Gbello:bella;, $N! Però di sicuro ti fa anche puzzare. Non avvicinarti troppo ai kodo: o scateni una fuga in massa o li mandi in calore.$B$BCredo che i miei compagni sarebbero d'accordo: basta il tuo odore a provare che hai fatto la tua parte per aiutarci contro quegli insetti. Grazie, $N.",
  en_title = "The Swarm Grows",
  en_obj = "Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles.",
}
T[1148] = {
  title = "Parti dello Sciame",
  desc = "Esamini il carapace con cura. Mentre lo rigiri fra le mani, ti accorgi che le placche di chitina sono intrecciate in un modo che lo rende incredibilmente resistente. Non hai mai visto niente del genere. Guardando meglio il resto del cadavere, capisci che queste creature sono molto potenti ed estremamente evolute.$B$BRiguardando il carapace, pensi che a Korran piacerebbe studiare altre di queste creature. Potrebbe aiutarlo a capire cosa sono e da dove vengono.",
  obj = "Porta 1 Silithid Heart, 5 Silithid Talons e 3 Intact Silithid Carapaces a Korran al Crossroads.",
  progress = "Ah, $N, passato un bel po' da quando sei $Gvenuto:venuta; a trovarmi. Cosa posso fare per te oggi? Tu avere l'aria di chi da poco ha visto in faccia la battaglia. Bene... bene per l'Orda e bene per te. Più battaglie vedi, più sarai utile; e anche più forte.",
  reward = "Ahh, hai visto Moktar da poco? Lui sempre badare a me. Mi dispiace sapere che passa il tempo a sorvegliare la sua piccola banda da guerra invece di combattere, ma sono sicuro che lui provare grande gioia a uccidere quelli dell'Explorers' League.$B$BTu essere $Gstato furbo:stata furba; a portarmi questi esemplari, $N. Con le uova che noi trovare nel Field of Giants, dovrebbero essere un buon punto di partenza per capire che insetti sono e cosa loro volere.",
  en_title = "Parts of the Swarm",
  en_obj = "Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.",
}
T[1149] = {
  title = "Prova di Fede",
  desc = "Mi hai cercato tu, o è il destino a portarti da me? Non importa. Ora sei qui, e così il tuo viaggio ricomincerà.$B$BOgni essere ha molti aspetti: lo spirito, il corpo, la mente. Alcuni si possono misurare con le tradizioni di un popolo; di altri possiamo solo sperare che esistano dentro di noi. Se sei d'accordo, metterò alla prova alcuni di quelli che porti in te.$B$BSupera la prova e diventerai più forte; fallisci e comprenderai la vastità del Nether.$B$BLa prima è una Prova di Fede.",
  obj = "Se hai fede, salta dalle assi che si affacciano su Thousand Needles.",
  progress = "La fede. Conta molto più di quanto alcuni credano.$B$BA volte non importa in cosa credi, purché tu creda in qualcosa.",
  reward = "Solo davanti alle avversità che non ci aspettiamo cominciamo a vedere quanto è forte il nostro spirito. Hai fatto il salto di fede senza nessuna garanzia di sopravvivere. Hai la mente aperta, e lo spirito pronto per ciò che verrà.$B$BSe lo desideri, la prossima prova ti aspetta.",
  en_title = "Test of Faith",
  en_obj = "If you have faith, leap from the planks overlooking Thousand Needles.",
}
T[1150] = {
  title = "Prova di Resistenza",
  desc = "Mi fa piacere vedere che, dopo quello che hai già fatto, il tuo coraggio resta saldo. La tua fede è intatta: è giunto il momento di mettere alla prova il corpo.$B$BPer prima cosa, una prova di resistenza. Porta con te degli amici e vai al Roguefeather Den, a ovest di Freewind Post. Arriva fino in fondo alla loro tana e distruggi le provviste. A quel punto dovresti aver scatenato la loro furia, e se sopravvivrai abbastanza a lungo verrà a prenderti Grenka Bloodscreech in persona — uccidila e portami il suo artiglio, e la prova sarà completa.",
  obj = "Porta il Grenka's Claw a Dorn Plainstalker in Thousand Needles.",
  progress = "Alle sfide che ti aspettano devi arrivare $Gpreparato:preparata; nello spirito, nel corpo e nella mente.$B$BTroppo spesso ci lanciamo avanti prima di essere pronti. Per questo sento come un dovere preparare i giovani, di qualunque tribù siano, ai pericoli che potrebbero incontrare una volta lasciata la sicurezza di casa.",
  reward = "Grenka era potente, anche per $Gun:una; $R. Oggi dovresti essere $Gfiero:fiera; di quello che hai fatto.$B$BNella prova di fede hai mostrato forza di spirito, e ora, affrontando le arpie Roguefeather, hai dimostrato resistenza in battaglia. Ma è giunto il momento di una nuova prova.",
  en_title = "Test of Endurance",
  en_obj = "Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.",
}
T[1151] = {
  title = "Prova di Forza",
  desc = "Ai tempi degli Old Gods, gli elementali abitavano gran parte del mondo. Adoravano gli Old Gods, che con il loro potere li tenevano legati a questo mondo. Quando gli Old Gods furono banditi, gli elementali svanirono dal nostro mondo, e ora vi tornano solo al comando di maghi potenti.$B$BMa ci sono delle eccezioni: alcuni elementali erano abbastanza potenti da restare qui con le loro sole forze. Uno di questi è Rok'Alim.$B$BPer mettere alla prova la tua forza, trova Rok'Alim a Thousand Needles e uccidilo.",
  obj = "Porta i Fragments of Rok'Alim a Dorn Plainstalker in Thousand Needles.",
  progress = "Per le tribù di centauri di Thousand Needles, Rok'Alim è anche il Martellatore, per il rombo che fanno i suoi pugni quando pesta le creature tanto coraggiose, o tanto stupide, da mettersi sulla sua strada.",
  reward = "La Prova di Forza è conclusa. Hai mostrato forza e coraggio, e ora sei $Gpronto:pronta; per l'ultima prova, quella che completerà questi riti.",
  en_title = "Test of Strength",
  en_obj = "Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.",
}
T[1152] = {
  title = "Prova del Sapere",
  desc = "Con me hai quasi finito. So molte cose, ma la Prova del Sapere non spetta a me: ci sono lezioni da imparare e luoghi da visitare che sono dominio di altri.$B$BSe sei $Gpreparato:preparata;, cerca Braug Dimspirit — è uno sciamano di grande saggezza. Ti metterà di nuovo alla prova, quindi ascolta le sue parole, $N.$B$BQuando sarai $Gpronto:pronta;, trova il tunnel che collega le Stonetalon Mountains ad Ashenvale: Braug vive lì vicino. E fai attenzione, $N: gli elfi della notte potrebbero cercare di ostacolare la tua prova.",
  obj = "Trova Braug Dimspirit vicino all'ingresso del Talondeep Path, nelle Stonetalon Mountains.",
  reward = "I giorni e le notti si fanno più freddi in tutto il mondo, mentre i goblin violentano la terra e gli elfi della notte puntano il dito contro le razze più giovani. Delle sofferenze presenti in ogni angolo di Kalimdor e Lordaeron non sono colpevoli solo i Forsaken e gli orchi: molte delle razze intelligenti hanno contribuito al dolore del mondo. Dorn lo sa, e ti ha mandato da me perché hai mostrato di avere le qualità per capirlo anche tu.$B$BOra sei al cospetto di Braug.",
  en_title = "Test of Lore",
  en_obj = "Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.",
}
T[1153] = {
  title = "Un Nuovo Campione di Minerale",
  desc = "$C, in passato mi hai aiutato come si deve. Finora il capoguerra è soddisfatto dei miei risultati, e mi chiede di andare avanti con rinnovata determinazione. L'onore mi impone di darti davanti a lui il merito che ti spetta per tutto quello che hai fatto, ma prima vorrei chiederti un altro aiuto.$B$BPoco tempo fa sono arrivati da sud dei viaggiatori, da un posto chiamato Thousand Needles. Laggiù hanno ucciso un coboldo che aveva con sé uno strano campione di minerale, ma non hanno voluto venderlo. Voglio averne un campione da esaminare.",
  obj = "Trova un Unrefined Ore Sample addosso a un Gravelsnout Digger o Surveyor e portalo a Tatternack Steelforge a Camp Taurajo in Barrens.",
  progress = "Ho incontrato di nuovo i viaggiatori — quelli che non hanno voluto vendermi un campione di quel minerale. Gli ho sputato addosso, perché non aiutano il capoguerra.$B$BChe muoiano in battaglia da codardi e non da guerrieri, come dovrebbe essere diritto di chiunque si allei con l'Orda.",
  reward = "Un buon campione, $N. Davvero un buon campione.$B$BOra che ci sei $Griuscito:riuscita;, quei viaggiatori non potranno più vantarsi con me del minerale che hanno trovato.$B$BMi metto subito al lavoro. Se si rivelerà abbastanza resistente, forgerò con questo materiale un'arma da mandare al capoguerra, per mostrargli il nostro successo.$B$BNon dimenticherò il tuo aiuto, $C.",
  en_title = "A New Ore Sample",
  en_obj = "Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens.",
}
T[1154] = {
  title = "Prova del Sapere",
  desc = "Hai superato le prove di Dorn, e ora vuoi affrontare la prossima. Molto bene. Ma finora le tue sfide sono state cose da bambini. Mettere alla prova il corpo è facile — la mente è tutta un'altra faccenda.$B$BTe lo dico in parole semplici: trova il libro che ti nomino, studialo e rispondi alla mia domanda su quello che contiene.$B$BQuale libro, ti starai chiedendo? The Legacy of the Aspects. Si trova in fondo a Dor'danil, nella parte meridionale di Ashenvale, protetto dai druidi morti e da chi li ha uccisi.",
  obj = "Trova il Legacy of the Aspects e riportala a Braug Dimspirit vicino all'ingresso del Talondeep Path, nelle Stonetalon Mountains.",
  progress = "Portami il libro quando l'avrai studiato. La domanda te la farò solo dopo che me l'avrai dato.",
  reward = "Questo è il libro che ti ho nominato. C'è speranza, allora, che tu risponda bene alla mia domanda... a meno che tu non abbia dimenticato di studiarne il contenuto.$B$BQuando sarai $Gpronto:pronta;, torna a parlarmi e ti farò una domanda.",
  en_title = "Test of Lore",
  en_obj = "Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.",
}
T[1159] = {
  title = "Prova del Sapere",
  desc = "Ben fatto, $N. La prima parte della Prova del Sapere l'hai superata, ma ti resta un'altra domanda a cui rispondere. E non spetta a me fartela.$B$BCerca Parqual Fintallas nella Città di Lordaeron. Prima che la Piaga lo colpisse era un grande storico degli umani; ora cerca ancora l'illuminazione, ma di un altro tipo.$B$BPrima di farti qualunque domanda ti chiederà qualcos'altro, ma finora hai fatto un lavoro magistrale — sono sicuro che supererai il suo ostacolo.",
  obj = "Trova Parqual Fintallas a Undercity.",
  reward = "Ti ha mandato Braug? Impossibile.$B$B<Parqual ti squadra da capo a piedi.>$B$BHai sfidato Dor'Danil, hai fatto un salto di fede, hai combattuto e sopraffatto un potente elementale? Bah! Sarà tutta una farsa; sarai $Gun avventuriero:un'avventuriera; qualunque che ha sentito qualche chiacchiera in taverna. E adesso pensi di avere quello che serve per superare la mia prova. E sia... $C.",
  en_title = "Test of Lore",
  en_obj = "Find Parqual Fintallas in Undercity.",
}
T[1160] = {
  title = "Prova del Sapere",
  desc = "Ti dirò cosa cercare, e ti farò perfino la mia domanda, ma non perché tu voglia dimostrare quanto vali. La conoscenza conta molto più della forza. Anche se altri sembreranno più abili di te, quello che sai del mondo varrà di più.$B$BVai al Monastero, nel nord delle Tirisfal Glades. Nella sua biblioteca c'è un libro intitolato Beginnings of the Undead Threat: i paladini, ora corrotti, lo usavano per addestrarsi a combattere quelli come me.$B$BPortamelo.",
  obj = "Trova le Beginnings of the Undead Threat e riportale a Parqual Fintallas a Undercity.",
  progress = "Spero che tu abbia fatto soffrire un po' la Scarlet Crusade prima di rubarle il libro.$B$BNon giudico senza motivo quelli come loro. Un tempo la Crociata avrà anche seguito la Luce, ma ora cerca di distruggere qualunque creatura non si sia schierata con la sua religione. Credono che tutti i non morti, Forsaken o no, vadano purificati, e che chi viaggia nelle loro terre sia o pazzo o succube delle potenti magie dei non morti. Idioti. Idioti e sciocchi; tutti quanti.",
  reward = "Questo è il libro che ti avevo mandato a cercare.$B$B<Parqual accarezza lentamente la copertina del libro, fissandolo.>$B$BE così adesso vuoi una domanda che dimostri che la tua mente è potente quanto il corpo e lo spirito. Se hai studiato il libro abbastanza a lungo, avrai la tua domanda, e con queste prove la farai finita!",
  en_title = "Test of Lore",
  en_obj = "Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.",
}
T[1164] = {
  title = "Rubare ai Ladri",
  desc = "Quella sgualdrina! Quella lurida! Kenata è ancora viva; la sua famiglia sta bene e prospera, mentre io soffro. Forsaken, appunto!$B$BLa mia famiglia non c'è più, se l'è portata via la peste. Anche la nostra tenuta è perduta; l'hanno saccheggiata e bruciata durante la guerra. E dopo tutto questo, lei e quei suoi figli schifosi hanno avuto la sfacciataggine di rubarmi gli unici beni preziosi che mi restavano.$B$BDelle cose rubate ormai non m'importa più. Adesso voglio le loro teste!$B$BUccidili per me! Va' alla Dabyrie Farmstead nell'Arathi, a nord-est di Refuge Point.",
  obj = "Porta le Teste di Kenata, Fardel e Marcel Dabyrie a Genavie Callow nell'Undercity.",
  progress = "Uccidili tutti e portami le loro teste!",
  reward = "Ti presenti a me come $Gun vendicatore:una vendicatrice;, e io mi inchino per ringraziarti.$B$BOra che quella vacca è morta e il loro seme non si spargerà più sulla faccia di Azeroth, posso dedicare le mie energie a qualcosa che renda di più. Spero che tu abbia saccheggiato la loro fattoria, dopo averli fatti fuori.",
  en_title = "To Steal From Thieves",
  en_obj = "Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.",
}
T[1166] = {
  title = "La Preoccupazione di Overlord Mok'Morokk",
  desc = "Inchinati davanti a Overlord Mok'Morokk!$B$BRexxar fare me grande capo dello Stonemaul Clan!$B$BMe buon capo. Me tenere clan al sicuro.$B$BGrossi draghi venire e fare fuoco su vecchia casa. Me ogre furbo. Trovare qui nuova casa per clan.$B$BMe lasciare vecchia casa così veloce che dimenticare roba. $GPiccolo:Piccola; $R, tu andare prendere mie cose. Andare a sud, trovare mio buon grog, mio tabacco da fiuto e mio forziere. Tu fare questo, dopo me piacere te. Tu guardare nel Den of Flame e nelle Stonemaul Ruins... loro essere là, me sicuro!",
  obj = "Overlord Mok'Morokk a Brackenwall Village vuole che tu recuperi il suo grog, il tabacco da fiuto e il forziere in Dustwallow Swamp.",
  progress = "Me avere sete di grog. E me mancare anche tabacco da fiuto. Forziere dove essere? Tu andare prendere per Overlord Mok'Morokk.$B$BTu andare cercare a sud, in vecchia casa. Me troppo occupato a guidare ogres per andare prendere.",
  reward = "Tu $Gbuon:buona; $R. Me mancare tanto mie cose. Ora me piacere te.",
  en_title = "Overlord Mok'Morokk's Concern",
  en_obj = "Overlord Mok'Morokk in Brackenwall Village wants you to retrieve his grog, snuff and strongbox in Dustwallow Swamp.",
}
T[1167] = {
  title = "La Tower of Althalaxx",
  desc = "Prima di affrontare Athrikus, faresti bene a sentire Balthule. Sono certo che ha tenuto d'occhio la Torre, e forse ha notizie fresche su come stanno andando le cose.",
  obj = "Parla con Balthule Shadowstrike vicino alla Tower of Althalaxx.",
  reward = "Ah, che piacere rivederti, $N! Qui ne sono successe di stranissime, sono contento che tu sia $Garrivato:arrivata;!$B$BUna cosa davvero strana, $N. Sembrava tutto normale — be', normale per quanto può esserlo qualcosa da queste parti — e all'improvviso dalla stanza in cima alla torre è partito un lampo di luce accecante. Poi sono cominciate le urla. Laceravano l'aria, e ogni tanto dei fulmini si abbattevano sul terreno. Che sta succedendo?",
  en_title = "The Tower of Althalaxx",
  en_obj = "Speak with Balthule Shadowstrike near the Tower of Althalaxx.",
}
T[1168] = {
  title = "L'Esercito del Drago Nero",
  desc = "Mok'Morokk fatto Signore Supremo da Rexxar. Lui tenere più a potere che a ogre.$B$BDraghi neri uccidere tanti ogre. Uccidere moglie di Tharg. Mok'Morokk dire noi scappare. Fare noi venire qui.$B$BOgre dovere combattere. Ogre non bravi a scappare. Mok'Morokk pensare solo a Mok'Morokk.$B$BMia casa essere Stonemaul Ruins. Me piace stare a sud. Questo posto non casa.$B$BAiuta ogre combattere esercito di drago nero. Me volere vendetta. Me volere tornare a casa.",
  obj = "Tharg a Brackenwall Village vuole che tu uccida 15 Firemane Scouts, 10 Firemane Ash Tails e 5 Firemane Guards.",
  progress = "Mok'Morokk dire a tutti ogre di restare e tenere sicuro questo posto. Me pensare ogre dovere uccidere esercito di drago nero e riprendere vecchia casa.$B$BTu aiuta ogre riprendere casa. Aiuta ogre avere vendetta.",
  reward = "Tu uccidere tanti di esercito di drago nero. Tu $R $Gcoraggioso:coraggiosa;.$B$BFare Tharg contento.",
  en_title = "Army of the Black Dragon",
  en_obj = "Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes.",
}
T[1169] = {
  title = "Identificare la Covata",
  desc = "Mentre quello stolto codardo di Mok'Morokk si crogiola nel potere e Tharg lotta coi demoni del dolore e della vendetta e intanto si contende la guida del clan, a quanto pare sono l'unico a preoccuparsi di scoprire da dove è partita l'aggressione contro la nostra vecchia casa.$B$BPerché mi guardi così $Gperplesso:perplessa;, $N? Credevi che parlassi come un bruto rozzo solo perché sono un ogre?$B$BMa torniamo agli affari: portami i cuori e le lingue dei cuccioli di drago e dei piccoli appena nati. Risalirò alla radice di questo male...",
  obj = "Draz'Zilb a Brackenwall Village vorrebbe che gli portassi 15 Searing Tongues e 15 Searing Hearts.",
  progress = "Con i cuori e le lingue della prole bruciata dell'esercito dei draghi neri potrò decifrare quale bestia infame ha portato la sua progenie a casa nostra. Forse, se conosceremo meglio chi ci ha aggredito, potremo provare a distruggerli una volta per tutte e strappare lo Stonemaul Village alla rovina.$B$BCerto, già convincere Mok'Morokk a spostare la sua pigra massa di grasso fuori da questo buco fangoso sarà un'impresa epica...",
  reward = "Raccogliere tutti questi cuori e queste lingue è stata senz'altro un'impresa pericolosa. Mi addentrerò nelle profondità dell'arcano per risalire all'origine della minaccia nera che si è abbattuta sulla nostra vecchia casa.",
  en_title = "Identifying the Brood",
  en_obj = "Draz'Zilb in Brackenwall Village would like you to bring him 15 Searing Tongues and 15 Searing Hearts.",
}
T[1170] = {
  title = "La Progenie di Onyxia",
  desc = "La progenie di Onyxia ha invaso lo Stonemaul Village. Ma perché la figlia di Deathwing, il signore dei draghi neri, dovrebbe calare sulle nostre terre?$B$BLa cosa è molto preoccupante. Di certo Onyxia non è stata spinta fin qui soltanto per assediare un piccolo gruppo di ogres: c'è uno scopo che va oltre.$B$BAvvisa subito Mok'Morokk! Dobbiamo agire.",
  obj = "Parla con Overlord Mok'Morokk a Brackenwall Village.",
  reward = "Perché tu dire me di draghi? Me non piace draghi. Me piace qui. Qui niente draghi.",
  en_title = "The Brood of Onyxia",
  en_obj = "Speak with Overlord Mok'Morokk in Brackenwall Village.",
}
T[1171] = {
  title = "La Progenie di Onyxia",
  desc = "Adesso tu lasciare me in pace. Va' a dire a Draz'Zilb che noi restare qui. Qui niente drago nero.",
  obj = "Parla con Draz'Zilb a Brackenwall Village.",
  reward = "Quel codardo fannullone!$B$BQuando il nostro capo era Rexxar, Mok'Morokk dava prova di forza. Ma Rexxar se n'era andato da poco, e Mok'Morokk è caduto preda delle tentazioni del potere. Invece di guidare, pretendeva. Non serve il suo popolo: si aspetta che siamo noi a servire lui.$B$BBisogna fare qualcosa.",
  en_title = "The Brood of Onyxia",
  en_obj = "Speak with Draz'Zilb in Brackenwall Village.",
}
T[1172] = {
  title = "La Progenie di Onyxia",
  desc = "La progenie di Onyxia è sparsa per tutto il Dragonmurk, ed è fondamentale impedire che nascano altri draghetti.$B$BCorri al Wyrmbog, nel sud della Dustwallow Marsh: è lì, di certo, che ha fatto la tana. Trova le uova di quel drago malvagio e distruggile.$B$BFinché la zona intorno resterà un luogo di riproduzione, lo Stonemaul Village non lo riconquisteremo mai.$B$BQuanto a Mok'Morokk... per quel disgraziato ho altri piani.",
  obj = "Draz'Zilb a Brackenwall Village vuole che tu distrugga 5 Uova di Onyxia.",
  progress = "Devi correre al Dragonmurk, $N. Se non ci muoviamo subito, con le uova di Onyxia sparse per il Wyrmbog ci ritroveremo davanti nemici in numero schiacciante.$B$BDistruggi le sue uova! Non lasciare che la piaga dei draghi neri si diffonda nella nostra terra!",
  reward = "Splendido! Ci vorrà del tempo prima che Onyxia possa deporre altre uova.$B$BTi ringrazio a nome del mio popolo, $N.$B$BTi ho già chiesto molto, ma forse potresti rendere un ultimo servizio allo Stonemaul Clan.$B$BMok'Morokk non è adatto a guidarci. Tharg sarebbe un capo eccellente, ma le ferite e l'età lo ostacolano. Caccia Mok'Morokk da qui con la forza. Solo allora potremo nominare un nuovo capo che ci riporti nella nostra vera casa, a sud.",
  en_title = "The Brood of Onyxia",
  en_obj = "Draz'Zilb in Brackenwall Village wants you to destroy 5 Eggs of Onyxia.",
}
T[1173] = {
  title = "Sfida Overlord Mok'Morokk",
  desc = "Tu osare sfidare Overlord Mok'Morokk?$B$BAh ah!$B$BMe schiacciare $Gpiccolo:piccola; $R!$B$BTu dire a me quando essere $Gpronto:pronta; per bella batosta.",
  obj = "Sconfiggi Mok'Morokk e riferisci la notizia a Draz'Zilb a Brackenwall Village.",
  progress = "Credevo che avresti provato a cacciare Mok'Morokk dal villaggio. E invece sei $Gvenuto:venuta; qui a chiacchierare con me?",
  reward = "Quella codarda massa di grasso di Mok'Morokk è scappata come un bambino spaventato. Hai reso un grande servizio, $N.$B$BOra il mio popolo potrà nominare un nuovo capo, uno che ci aiuti a riconquistare la nostra vecchia casa una volta per tutte.",
  en_title = "Challenge Overlord Mok'Morokk",
  en_obj = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.",
}
T[1174] = {
  title = "Gli Gnomi Vincono!",
}
T[1175] = {
  title = "Un Ostacolo sul Percorso",
  desc = "Dopo il grande schianto fra il Red Thunder, il bolide dei goblin, e un basilisco, Kronkrider mi ha assunto per badare alla pista. Non so cosa mangino gli animali là fuori nelle piane per diventare così grossi, ma dobbiamo stare attenti a sfoltirli, così non ci finiscono sulla pista in piena gara.$B$BFacciamo così. Se vuoi guadagnare qualcosa, va' a eliminare i basilischi della zona.",
  obj = "Uccidi 10 Saltstone Basilisks, 10 Saltstone Crystalhides e 6 Saltstone Gazers per Trackmaster Zherin nelle Shimmering Flats.",
  progress = "Sgomberare i rottami dei bolidi basta e avanza, senza doverli pure tirare fuori da pezzi di animali bruciati.",
  reward = "Spero che tu non abbia ucciso nessun basilisco proprio sulla pista! Al sole le carcasse ci mettono parecchio a decomporsi, e preferirei non dover prendere la pala per ripulire.",
  en_title = "A Bump in the Road",
  en_obj = "Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats.",
}
T[1176] = {
  title = "Alleggerire il Carico",
  desc = "Nelle corse conta anche il più piccolo dettaglio! Una piccola regolazione della potenza, le bobine di tensione allentate un po', un telaio più leggero: devi pensare a tutto.$B$BPer tante piccole modifiche strutturali ai nostri bolidi usiamo ossa d'avvoltoio, che hanno l'equilibrio perfetto fra resistenza e peso. E in più trovarne altre è facile, visto che le distese di sale sono piene di avvoltoi.$B$BPortamene un po' e ti faccio un buon prezzo.",
  obj = "Procura 10 Hollow Vulture Bones per Pozzik in Shimmering Flats.",
  progress = "Hai le ossa per me? Stavo per mettermi ad alleggerire lo sterzo, ma non voglio aprirlo finché non ho tutti i pezzi che mi servono.",
  reward = "Ottimo! Adesso posso mettere subito la squadra al lavoro. Grazie, $N!",
  en_title = "Load Lightening",
  en_obj = "Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats.",
}
T[1177] = {
  title = "Fame!",
  desc = "Mud grosso ogre.$B$BMe fame.$B$BVa' a menare pesciolini. Porta cibo a Mud.$B$BTu dare cibo a Mud o Mud mangia te.",
  obj = "Mudcrush Durtfeet, nel nord di Dustwallow, vuole 12 Mirefin Heads.",
  progress = "Dammi cibo o me mangia te.",
  reward = "Me piace testa di pesciolino!$B$BOra me non mangia te.",
  en_title = "Hungry!",
  en_obj = "Mudcrush Durtfeet in northern Dustwallow wants 8 Mirefin Heads.",
}
T[1178] = {
  title = "Sponsorizzazione Goblin",
  desc = "La nostra squadra corse è l'orgoglio dei goblin di tutto il mondo. Ti sorprenderebbe sapere chi ci dà una mano, in un modo o nell'altro.$B$BConosci Gazlowe? Ci trova pezzi da ogni angolo del mondo, e una volta è venuto addirittura qui a lavorare su uno dei nostri bolidi!$B$BQualche settimana fa ci ha detto che avrebbe mandato un prototipo nuovo di regolatore di carburante, ma ancora non è arrivato. E dire che di solito è puntualissimo... Ti dispiacerebbe fare un salto a Ratchet a chiedergli notizie? Non insisterei tanto, ma gli gnomi ci stanno raggiungendo!",
  obj = "Parla con Gazlowe a Ratchet.",
  reward = "Ti manda Pozzik, eh? Sai, prima di ritirarsi per lavorare ai bolidi, Pozzik era uno degli inventori più rispettati di Undermine.$B$BAppena entrato in squadra, per prima cosa ha sviluppato i bolidi a due motori. Forse gli affari ne risentiranno, ora che non lavora più con la Tinkers' Union, ma chi se ne importa, no? Non c'è niente di meglio delle corse!",
  en_title = "Goblin Sponsorship",
  en_obj = "Speak to Gazlowe in Ratchet.",
}
T[1179] = {
  title = "I Fratelli Brassbolts",
  desc = "Hai mai sentito parlare delle Shimmering Flats? È una distesa di saline parecchio lontana, a Kalimdor, appena a sud del canyon di Thousand Needles. È un posto perfetto per le corse perché, be', è tutto piatto!$B$BCi sono due fratelli gnomi laggiù, amici miei, che stanno provando la loro nuova auto a razzo, e da quel che ho sentito è veloce! Eh, così veloce che i loro piloti continuano a schiantarsi. E a prendersi delle belle botte in testa.$B$BCosì mi hanno chiesto qualche elmetto da Siege Engine, ma io qui devo lavorare. Non posso mica partire!$B$BTu per caso puoi?",
  obj = "Porta la Crate of Crash Helmets a Wizzle Brassbolts, in Shimmering Flats.",
  progress = "$GAttento:Attenta; a dove metti i piedi! Occhio occhio occhio!! Qui c'è roba delicata, e se vogliamo vincere deve funzionare tutto alla perfezione!",
  reward = "Ah! Ti manda Longbeard con un carico di elmetti! Evvai!$B$BMagari adesso lo convinciamo un pilota a guidare la nostra auto...",
  en_title = "The Brassbolts Brothers",
  en_obj = "Bring the crate of crash helmets to Wizzle Brassbolts in the Shimmering Flats.",
}
T[1180] = {
  title = "Sponsorizzazione Goblin",
  desc = "Ma veniamo al motivo per cui sei qui. Sì, ho promesso a Pozzik di consegnargli un regolatore di carburante nuovo, ma a me non è ancora arrivato. Revilgaz, giù a Booty Bay, ha detto che l'avrebbe fatto spedire, però può darsi che in qualche modo si sia perso per strada.$B$BSe è andata così, c'è poco da fare. Però almeno possiamo scoprire se è partito da Booty Bay.$B$BLaggiù parla con Wharfmaster Lozgil: dovrebbe poter controllare i registri dei carichi.",
  obj = "Parla con Wharfmaster Lozgil a Booty Bay.",
  reward = "Spedizioni per Ratchet? Fammi dare un'occhiata ai registri...$B$BNo, l'ultima per Ratchet che mi risulta era un carico di stivali di Drizzlik. Per il resto poca roba, a parte materiali da costruzione e attrezzi. Pezzi da corsa, di sicuro nessuno.",
  en_title = "Goblin Sponsorship",
  en_obj = "Speak with Wharfmaster Lozgil in Booty Bay.",
}
T[1181] = {
  title = "Sponsorizzazione Goblin",
  desc = "Più di così temo di non poterti aiutare, $N. Se vuoi andare a fondo, ti consiglio di scomodare il Barone in persona: se c'è qualcuno che conosce gli affari di Revilgaz, è proprio Revilgaz.$B$BLo trovi all'ultimo piano della taverna, dall'altra parte del porto.",
  obj = "Parla con Baron Revilgaz a Booty Bay.",
  reward = "Oh, certo, so benissimo di cosa parli. Però no, non posso aiutarti. Alcuni dei miei uomini dovevano recuperare i progetti del regolatore di carburante, ma sono tornati a mani vuote.",
  en_title = "Goblin Sponsorship",
  en_obj = "Speak with Baron Revilgaz in Booty Bay.",
}
T[1182] = {
  title = "Sponsorizzazione Goblin",
  desc = "Vedi, gli shredder della Venture Company al Lake Nazferiti (nel nord di Stranglethorn) adesso montano un regolatore di carburante di nuovo modello. Pensavo che a Pozzik potesse far comodo, se fosse riuscito a scoprirne qualche dettaglio. Purtroppo Cozzle, il caposquadra di laggiù, sembra un po' più furbo di quanto credessi.$B$BMa tu, a quanto pare, potresti avere più fortuna a trovare i progetti: so che li tiene in casa, quasi di sicuro chiusi a chiave.",
  obj = "Porta i Fuel Regulator Blueprints a Baron Revilgaz a Booty Bay.",
  progress = "Mi secca ammetterlo, ma la squadra di gnomi che hanno laggiù è piuttosto brava. Ai nostri ragazzi serve tutto il vantaggio possibile.",
  reward = "Adesso lasciami fare una copia di questi progetti per i miei appunti, poi puoi portarli dritto a Pozzik. Non vorrei che pensasse che uno dei suoi sponsor lo stia abbandonando.",
  en_title = "Goblin Sponsorship",
  en_obj = "Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.",
}
T[1183] = {
  title = "Sponsorizzazione Goblin",
  desc = "Dovresti essere $Gpronto:pronta; a partire. Saluta Pozzik da parte mia e digli che, se mai avesse bisogno di qualcosa, non deve farsi problemi a chiedere. Spero di sentire presto che ha battuto il record della pista!",
  obj = "Consegna i Fuel Regulator Blueprints a Pozzik in Shimmering Flats.",
  progress = "$N! Sei $Griuscito:riuscita; a trovarlo, il regolatore di carburante?",
  reward = "Speravo di trovarlo già montato, ma così ho l'occasione unica di migliorare il progetto partendo da zero. Grazie, $N. Potrò buttare giù degli schemi perfezionati, costruire l'aggeggio e installarlo molto presto.",
  en_title = "Goblin Sponsorship",
  en_obj = "Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats.",
}
T[1184] = {
  title = "Parti dello Sciame",
  desc = "Torna da Belgrom a Orgrimmar e digli che Moktar, là fuori a Thousand Needles, sta eseguendo bene i suoi ordini. Digli anche che i miei studi andare avanti e che spero presto di saperne di più. Dovrebbe esserne molto contento.",
  obj = "Torna da Belgrom Rockmaul a Orgrimmar.",
  reward = "Apprezzo i tuoi sforzi, $C. Il capoguerra sarà lieto di sapere con quanta tenacia hai fatto il tuo dovere.$B$BOh, certo che gli farò il tuo nome. Mi parla spesso e tiene molto alle mie opinioni.$B$BOra va', ho parecchio da fare. E se presto parlerai con Korran e lui avrà notizie di queste creature, torna da me — credo che siano una minaccia da prendere sul serio.",
  en_title = "Parts of the Swarm",
  en_obj = "Return to Belgrom Rockmaul in Orgrimmar.",
}
T[1185] = {
  title = "Sotto la Chitina C'era...",
  reward = "Ehi, sei di nuovo tu! Cioè, voglio dire tu — il tu che è $N, insomma! Sì — proprio quel tu!$B$BEhi, lasciami ricominciare!$B$BQuell'oggetto che hai trovato a Silithus — era davvero un libro. Un diario, scritto in un dialetto antichissimo della lingua che oggi chiamiamo Darnassian. Ci vorrà un po', ma voglio studiarlo fino in fondo. Volevo che lo sapessi: quello che hai trovato era preziosissimo per il Circolo.$B$BLa capogruppo è tutta emozionata e via dicendo!",
}
T[1186] = {
  title = "Il Diciottesimo Pilota",
  desc = "Io avrò da fare a integrare questo nuovo regolatore di carburante nei progetti dei nostri bolidi, ma se vuoi aiutare ancora la squadra, vai a parlare con Razzeric. È il nostro pilota — be', il diciottesimo, per la precisione — e gli piace aggiungere ai bolidi qualche piccolo ritocco tutto suo.$B$BÈ un tipo un po' svitato, però, quindi cerca di non sembrare troppo $Gsorpreso:sorpresa;.",
  obj = "Parla con Razzeric in Shimmering Flats.",
  reward = "Sei $Gil:la; $R che sta aiutando Pozzik, vero? Un tempo ero come te: correvo avanti e indietro per i box e mi davo da fare in qualunque lavoro i meccanici mi lasciassero fare.$B$BE adesso guardami! Lo straordinario pilota della squadra corse goblin!",
  en_title = "The Eighteenth Pilot",
  en_obj = "Speak with Razzeric on the Shimmering Flats.",
}
T[1187] = {
  title = "Le Modifiche di Razzeric",
  desc = "Lo so, Pozzik è un gran meccanico, ma ha paura di dare tutta la potenza e tenersi forte. Io invece no.$B$BQuando Pozzik finisce un bolide, mi prendo un po' di tempo per metterci le mie modifiche — sai, allento i comandi, tolgo pezzi di telaio e gli do più carica!$B$BHo ordinato un seaforium booster a Shreev, al Gizmorium di Gadgetzan, ma a quanto pare lo zeppelin che lo portava si è schiantato nella Dustwallow Marsh! Mi serve a tutti i costi, $N!",
  obj = "Recupera il Seaforium Booster per Razzeric in Shimmering Flats.",
  progress = "Come faccio a presentarmi in pista senza una spintarella in più alla partenza? È uno scandalo, te lo dico io.",
  reward = "Guarda che bellezza! Quindici libbre di pura potenza al seaforium! Appena l'avrò fissato sul fianco del bolide, sfreccerò per la pista così veloce che gli gnomi li batterò due volte!",
  en_title = "Razzeric's Tweaking",
  en_obj = "Retrieve the Seaforium Booster for Razzeric in the Shimmering Flats.",
}
T[1188] = {
  title = "La Sicurezza Prima di Tutto",
  desc = "Ma aspetta, cos'è questo? Shreev ha lasciato la sicura inserita. Così la potenza che posso tirare fuori dal potenziatore resterà sempre limitata. Gli avevo detto che la volevo tolta! Così non va.$B$BDevi portarlo alla Gadgetzan Gizmorium, nel Tanaris Desert, e farla togliere a Shreev.",
  obj = "Porta il Seaforium Booster a Shreev a Gadgetzan.",
  progress = "Come saprai di sicuro, al Gizmorium trovi tutto quello che ti serve come $Ginventore:inventrice;! Cosa posso fare per te?",
  reward = "Solo Razzeric potrebbe guardare questo coso e dire che ci ho messo una specie di sicura. Questo potenziatore è fatto quasi tutto di esplosivo al seaforium. L'ho già modificato perché sprigioni una carica più forte quando lo usi, ma Razzeric non è mai contento finché non va oltre il massimo!",
  en_title = "Safety First",
  en_obj = "Bring the Seaforium Booster to Shreev in Gadgetzan.",
}
T[1189] = {
  title = "La Sicurezza Prima di Tutto",
  desc = "Ecco, ho fatto come voleva Razzeric. Digli solo di stare attento quando lo aziona: basta il minimo errore e, invece di andare avanti, diventerà solo una macchia bruciata sulla pista.$B$BE se succedesse sarebbe pure un peccato. Chissà se il nostro diciannovesimo pilota varrebbe qualcosa?",
  obj = "Riporta il Modified Seaforium Booster a Razzeric in Shimmering Flats.",
  progress = "Ci credi che Pozzik ha messo un secchio di sabbia sul bolide? Come faccio ad arrivare alla velocità massima con un secchio di sabbia sotto il sedile?",
  reward = "Così va meglio! Vorrei vedere che faccia fanno gli gnomi quando faccio partire questo gioiellino.$B$BPeccato che sarò troppo occupato a stabilire un nuovo record del percorso!",
  en_title = "Safety First",
  en_obj = "Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats.",
}
T[1190] = {
  title = "Tenere il Passo",
  desc = "Non c'è altra spiegazione sensata: i fratelli Brassbolts hanno scoperto un nuovo materiale da costruzione. Le loro macchine corrono più di prima, eppure i progetti e tutti gli altri dati che abbiamo raccolto alle corse sono identici.$B$BQuello che sappiamo è che Rizzle Brassbolts ha passato quasi tutto il tempo con la testa sui progetti di questa nuova scoperta.$B$BZamek può creare un diversivo per te, e così tu potrai rubargli quei progetti.",
  obj = "Fai creare un diversivo a Zamek, poi ruba i progetti di Rizzle per Pozzik in Shimmering Flats.",
  reward = "Un rotolo di appunti e progetti scarabocchiati in gran fretta, su come si raffina una materia prima.",
  en_title = "Keeping Pace",
  en_obj = "Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats.",
}
T[1191] = {
  title = "Il Diversivo di Zamek",
  reward = "Andiamo!",
  en_title = "Zamek's Distraction",
}
T[1192] = {
  title = "Indurium Ore",
  progress = "Vorrei inserire l'indurium in varie parti dei nostri bolidi, ma per fabbricare quei pezzi mi serve un sacco di indurium grezzo.$B$BL'indurium ore lo trovi negli scavi di Uldaman, nelle Badlands, oltre il mare, a Khaz Modan.$B$BGli gnomi si stanno rifornendo per conto loro, quindi, per stare al passo, è importante che ci procuriamo anche noi la nostra scorta.",
  reward = "Eccellente! Metto subito la squadra al lavoro sui pezzi che ci serviranno per la prossima gara.",
  en_title = "Indurium Ore",
}
T[1193] = {
  title = "Una Broken Trap",
  progress = "Hai davanti una grossa trappola rotta: gli ogres, a quanto pare, hanno provato a ripararla senza riuscirci. Lì accanto c'è un biglietto scritto in fretta che, cosa strana, spiega per filo e per segno cosa serve per rimetterla a posto: un thorium widget e un po' di frost oil. Se tornasse a funzionare, un ogre che ci passasse vicino potrebbe rimanerci intrappolato, e così lo si potrebbe evitare.$B$BChiaramente, il fatto che pochissimi ogres sappiano leggere sembrerebbe una fortunata coincidenza.$B$BChiaramente.",
  reward = "Il thorium widget scivola al suo posto senza fatica e apre un condotto dove versare il frost oil. Appena ci scendono dentro le ultime gocce, con uno scatto la trappola si arma.$B$BGuai a qualunque ogre incauto che capitasse da queste parti per puro caso!",
}
T[1194] = {
  title = "Gli Schemi di Rizzle",
  desc = "Gli schemi di Rizzle spiegano come si raffina l'indurium ore. Dai suoi scarabocchi si capisce chiaramente che l'indurium ore si ricava dal sito di scavo nanico di Uldaman, nelle Badlands.$B$BGran parte degli altri appunti riguarda la sua resistenza al calore.$B$BA fare da fermacarte ai progetti c'è un pezzo di quello che sembra indurium ore non raffinato.",
  obj = "Porta il Sample of Indurium Ore a Pozzik in Shimmering Flats.",
  reward = "Indurium? Interessante... Se regge il calore quanto dici, si spiegherebbe perché negli ultimi tempi gli gnomi vanno meglio.$B$BAnche questo campione che mi hai portato sarà preziosissimo: ci potrò fare qualche prova. Ma perché ci sia utile davvero, me ne servirà di più.",
  en_title = "Rizzle's Schematics",
  en_obj = "Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats.",
}
T[1195] = {
  title = "La Fiamma Sacra",
  desc = "I centauri Galak di Thousand Needles custodiscono un manufatto che risale all'epoca in cui furono creati i centauri.$B$BVorremmo recuperarlo, ma per farlo ci serve una fiala d'acqua presa da uno dei pozzi lunari degli elfi della notte.$B$BPer raccogliere l'acqua dovrai prima procurarti una delle fiale che portano le driadi vicino al Raynewood Retreat, nel cuore dell'Ashenvale Forest. Potrai riempirla in un pozzo lunare vicino alla riva occidentale del Falfarren River, a sud della strada principale.",
  obj = "Riporta una Filled Etched Phial a Zangen Stonehoof a Thunder Bluff.",
  progress = "Quando avremo la fiala piena, potremo mandarla a Rau, il mio socio, a Thousand Needles. È stato lui a chiederla, quindi saprà come usarla meglio di noi.",
  reward = "Molto bene. Questa dovrebbe essere proprio quello che Rau ha chiesto. Potresti portargliela tu? Passare un po' di tempo laggiù a Needles potrebbe farti piacere.",
  en_title = "The Sacred Flame",
  en_obj = "Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff.",
}
T[1196] = {
  title = "La Fiamma Sacra",
  desc = "Porta la fiala piena a Rau Cliffrunner, al Freewind Post, nel sud-est di Thousand Needles. Per arrivare a Thousand Needles prendi il Great Lift, al margine meridionale di Barrens.$B$BNon mi stupirei se potessi darci ancora una mano.",
  obj = "Consegna la Filled Etched Phial a Rau Cliffrunner al Freewind Post.",
  progress = "Non sarà che ti ha mandato Zangen, mh?",
  reward = "Mh, sì, questa fiala d'acqua è proprio quello che ci voleva. Le driadi e i centauri hanno antenati in comune, perciò l'acqua dei pozzi lunari ci permetterà di superare la protezione della fiamma eterna che circonda la reliquia dei centauri.",
  en_title = "The Sacred Flame",
  en_obj = "Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post.",
}
T[1197] = {
  title = "La Fiamma Sacra",
  desc = "Con l'acqua che hai portato potrai spegnere per un po' la fiamma che custodisce la reliquia dei centauri, ma l'effetto non durerà per sempre, quindi dovrai sbrigarti.$B$BA nord di qui troverai la Splithoof Crag, la roccaforte dei centauri. La fiamma è nello Splithoof Hold, una parte della rupe molto sorvegliata.$B$BMa fai attenzione: da queste parti i centauri Galak sono tantissimi, e non saranno molto disposti a cedere una cosa a cui tengono così tanto.",
  obj = "Recupera il Cloven Hoof per Rau Cliffrunner al Freewind Post.",
  progress = "Non vedo l'ora di avere fra le mani il Cloven Hoof. L'hai già recuperato?",
  reward = "Sento una strana energia provenire dallo Zoccolo... Sono certo che studiandolo scopriremo cose nuove e sorprendenti sui centauri.$B$BTi ringrazio, $N. Adesso devo mettermi a decifrare i misteri che mi hai portato.",
  en_title = "The Sacred Flame",
  en_obj = "Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post.",
}
T[1198] = {
  title = "In Cerca di Thaelrid",
  desc = "Di questi tempi circolano molte voci sull'alleanza tra il Twilight's Hammer e i naga a Blackfathom Deeps, sulle coste di Ashenvale.$B$BQui il mio compito per l'Argent Dawn è raccogliere quante più informazioni possibile, così da sapere quando e dove serve aiuto.$B$BSono ormai passate settimane da quando ho mandato un esploratore a controllare cosa succede a Blackfathom Deeps. Argent Guard Thaelrid non ha ancora fatto rapporto.$B$BGli altri esploratori sono impegnati in faccende urgenti.$B$BTrova Thaelrid e aiutalo al posto mio, $N.",
  obj = "Cerca Argent Guard Thaelrid nelle Blackfathom Deeps.",
  reward = "Dawnwatcher Shaedlass ha fatto bene a mandarti. In questo luogo corrotto è davvero in atto un piano malvagio.",
  en_title = "In Search of Thaelrid",
  en_obj = "Seek out Argent Guard Thaelrid in Blackfathom Deeps.",
}
T[1199] = {
  title = "La Caduta del Twilight",
  desc = "Forti dei riti ancestrali dei caotici Old Gods, i membri del Twilight's Hammer si adoperano per far tornare i loro oscuri signori e seminare morte e terrore nel mondo.$B$BCrediamo che il Twilight's Hammer si sia alleato con i naga e che le loro forze si stiano radunando a Blackfathom Deeps, sulla costa di Ashenvale.$B$BQualunque piano malvagio si stia tramando nelle profondità dell'antico tempio, va sventato.$B$BMuovi guerra al Martello e riportami le prove delle tue imprese. I tuoi sforzi saranno ricompensati generosamente.",
  obj = "Porta 10 Twilight Pendants ad Argent Guard Manados a Darnassus.",
  progress = "Un tempo Blackfathom Deeps era un antico tempio degli elfi della notte, che custodiva un pozzo lunare potentissimo. Chissà quale male vi sta covando ora il Twilight's Hammer.$B$BHai fatto qualche progresso nello scacciarli da lì?",
  reward = "Nelle tue vene scorre senza dubbio sangue nobile e coraggioso, $N. The Argent Dawn ti rende merito per i tuoi sforzi contro il male.",
  en_title = "Twilight Falls",
  en_obj = "Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus.",
}
T[1200] = {
  title = "Infamia a Blackfathom",
  desc = "Le forze mi hanno abbandonato. Ho bisogno del tuo aiuto!$B$BTanto tempo fa questo luogo era un grande tempio di Elune. Poi però la sventura lo ha mandato in rovina, quando la corruzione di un Old God è filtrata dalle profondità della terra e ha contaminato il sacro Moon Well.$B$BAku'Mai, servitore dell'Old God, è emerso dalle acque.$B$BI cultisti del Twilight's Hammer si sono alleati con i naga per occupare queste terre. Guidati da Kelris, sacrificano innocenti ad Aku'Mai in cambio di potere.$B$BTi prego, $N, uccidi Kelris e portane la testa a Selgorm, a Darnassus.",
  obj = "Porta la testa di Twilight Lord Kelris a Dawnwatcher Selgorm, a Darnassus.",
  progress = "Il tempo è un bene prezioso, $C.$B$BQui a Darnassus il mio compito è far prosperare l'Argent Dawn e respingere le forze malvagie che avanzano su Kalimdor.$B$BDimmi in fretta cosa vuoi, oppure va' per la tua strada.",
  reward = "Kelris ci è sfuggito per parecchio tempo.$B$BPareva che ci fosse di mezzo lui ogni volta che il male si faceva vivo da queste parti. Per un po' lo abbiamo creduto morto o disperso.$B$BMa ora tutto torna. Ponendo fine al suo dominio hai salvato la vita a molti innocenti.$B$BPer la luce! Sacrificare qualcuno al servitore di un Old God per il proprio tornaconto è a dir poco riprovevole!$B$BHai compiuto una grande impresa, $N. Ti rendo onore a nome dell'Argent Dawn.",
  en_title = "Blackfathom Villainy",
  en_obj = "Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.",
}
T[1201] = {
  title = "Spie di Theramore",
  desc = "Fra l'Orda e l'Alleanza regge una tregua precaria. Lungo i confini, però, le due parti continuano a colpirsi a vicenda con scaramucce e azioni segrete, e il nostro dovere è fare in modo che l'Orda abbia la meglio!$B$BE adesso l'occasione ce l'abbiamo.$B$BA est di Brackenwall Village si sono appostati degli infiltrati dell'Alleanza. Spiano il villaggio e riferiscono a Theramore ogni nostro movimento: non possiamo permetterlo.$B$BDai la caccia agli infiltrati e uccidili. E fai capire chiaramente ai loro superiori che le loro spie, qui, non le tollereremo!",
  obj = "Uccidi 9 Theramore Infiltrators, poi torna da Nazeer Bloodpike in Brackenwall Village.",
  progress = "Allora, $N, li hai trovati gli infiltrati?",
  reward = "Ottimo lavoro. Sanno il fatto loro, quegli infiltrati, ma non abbastanza da sfuggire all'occhio vigile dell'Orda!",
  en_title = "Theramore Spies",
  en_obj = "Kill 9 Theramore Infiltrators, then return to Nazeer Bloodpike in Brackenwall Village.",
}
T[1202] = {
  title = "I Moli di Theramore",
  desc = "$N, abbiamo mandato due delle nostre spie a rubare dei documenti da una nave ai moli di Theramore. Le carte le hanno prese, ma sono state scoperte e hanno dovuto gettarle in mare.$B$BPoi una delle due è riuscita a fuggire, ma senza recuperare il bottino. È venuta a dirmi che aveva fallito, e adesso il compito passa a te.$B$BI documenti sono in un baule, da qualche parte nelle acque sotto i moli di Theramore. Trova quei documenti, $N, e portameli.",
  obj = "Porta i Captain's Documents a Nazeer Bloodpike in Brackenwall Village.",
  progress = "Allora, $N, li hai trovati i documenti? Dentro ci sono informazioni vitali per la stabilità dell'Alleanza, e quindi per la sicurezza dell'Orda.",
  reward = "Complimenti, $N. Non era una missione facile, ma ai nostri superiori i documenti che hai recuperato stanno molto a cuore.",
  en_title = "The Theramore Docks",
  en_obj = "Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village.",
}
T[1203] = {
  title = "Jarl Ha Bisogno di una Lama",
  desc = "Ho da tagliare. Non posso dirti cosa taglierò, ma... mi serve una lama. Una certa lama...$B$BC'è chi la chiama Moonsteel Broadsword. Io la chiamo lama da fendenti.$B$BMi aiuti? Magari la trovi in città, magari parli con un fabbro e te la fa su misura.$B$BMa non dormirci sopra. Quello che devo tagliare non si conserva per sempre...",
  obj = "Porta un Moonsteel Broadsword a Jarl in Dustwallow Marsh.",
  progress = "Hai la mia lama??",
  reward = "È una bella lama. Ha un bel fendente. È proprio una bella lama da fendenti. Grazie. Grazie, grazie, grazie!!! Adesso voglio provarla....$B$BDopo. La proverò dopo. Ma come dicevo... grazie.",
  en_title = "Jarl Needs a Blade",
  en_obj = "Bring a Moonsteel Broadsword to Jarl in Dustwallow Marsh.",
}
T[1204] = {
  title = "Zuppa di Mudrock e Insetti",
  desc = "Sto mettendo a punto un piatto che ho chiamato \"Zuppa di Mudrock e Insetti.\" Mi mancano ancora gli ingredienti principali e... beh, non credo che durerei molto ad arrancare nella Dustwallow Marsh!$B$BAllora, $N, potresti andare a caccia per me? Per cominciare mi servono le lingue delle tartarughe Mudrock. Le Mudrocks le trovi lungo la costa, soprattutto intorno alla baia.$B$BMa non voglio lingue qualunque! Ho sentito dire che alcune Mudrocks hanno la lingua biforcuta...$B$BSi dice che le forked tongues abbiano un sapore particolare, ed è quello che voglio nel mio piatto...",
  obj = "Porta 8 Forked Mudrock Tongues a Morgan Stern a Theramore.",
  progress = "Allora, le hai prese le forked tongues?",
  reward = "Queste vanno benissimo! Grazie, $N!$B$BAdesso proverò a cucinare queste lingue in vari modi, per scoprire quale ne esalta di più il sapore.$B$BAlla fine ne verrà fuori un piatto degno di essere servito al Blue Recluse di Stormwind!",
  en_title = "Mudrock Soup and Bugs",
  en_obj = "Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore.",
}
T[1205] = {
  title = "Deadmire",
  desc = "Deadmire è un ancient crocolisk della palude di Dustwallow, ed è giunta per lui l'ora di morire.$B$BLe vecchie ossa gli scricchiolano mentre trascina l'enorme corpo per la palude. Si muove ancora con la forza e la velocità della giovinezza, ma quel corpo che invecchia tormenta il grande spirito che lo abita, uno spirito la cui fiamma non vacilla.$B$BEppure ora vive in un dolore che non gli dà tregua e che lo fa impazzire. Devi porre fine alla vita di questa nobile creatura, $N. Devi condurre Deadmire verso la pace.",
  obj = "Porta il Deadmire's Tooth a Melor a Thunder Bluff.",
  progress = "Hai il dente di Deadmire, $N? Hai posto fine alla sofferenza della creatura?",
  reward = "Molto bene, $N.$B$BDi certo la caccia non è stata facile, ma è bello sapere che il dolore della bestia è finalmente cessato.",
  en_title = "Deadmire",
  en_obj = "Bring Deadmire's Tooth to Melor in Thunder Bluff.",
}
T[1206] = {
  title = "Jarl Ha Bisogno di Occhi",
  desc = "Il succo d'occhio è buono da bere. Peccato che quasi tutte le bestiole abbiano due occhi soltanto.$B$BI ragni invece di occhi ne hanno un sacco. Un sacco e una sporta. E il succo degli occhi di Darkmist è saporito. Vellutato e salato! Occhi di ragno integri... già ne sento il sapore.$B$BI Darkmist spiders stanno a ovest di qui, nella Darkmist Cavern. Secondo te sono i ragni a prendere il nome dalla caverna... o il contrario?",
  obj = "Porta 40 Unpopped Darkmist Eyes a \"Swamp Eye\" Jarl presso Swamplight Manor.",
  progress = "Dove sono finiti quegli occhi?",
  reward = "Hai preso gli occhi! Hai preso gli occhi! Saporiti, saporiti occhi di ragno!$B$BCerti occhi... se li fissi, ti fissano anche loro. Quelli mangiali per ultimi. Ti fanno compagnia... là fuori, nella palude.$B$BCiao, occhietti di ragno. Ciao! Sapete di pollo. Pollo appiccicoso e salato!$B$BMmmh.",
  en_title = "Jarl Needs Eyes",
  en_obj = "Bring 20 Unpopped Darkmist Eyes to \"Swamp Eye\" Jarl at the Swamplight Manor.",
}
T[1218] = {
  title = "Soothing Spices",
  desc = "Mi piace cucinare. Buona cucina di palude: cosce di rana verde fritte, roba così.$B$BE per cucinare mi servono le spezie. Spezie esotiche. Ci faccio uno stufato, lo lascio cuocere ben bene, me lo butto giù e un po' lo do anche a te.$B$BLo stufato ti piace?",
  obj = "Porta 3 Soothing Spices a \"Swamp Eye\" Jarl in Dustwallow Marsh.",
  progress = "Spezie. Un po' di spezie nella vita farebbero comodo a tutti. Non trovi?",
  reward = "Ah, ecco le spezie! E adesso eccoti un po' di buono stufato di palude.",
  en_title = "Soothing Spices",
  en_obj = "Bring 3 Soothing Spices to \"Swamp Eye\" Jarl in Dustwallow Marsh.",
}
T[1219] = {
  title = "Il Rapporto Orchesco",
  desc = "Setacciando la terra smossa, si trova la mano mozzata di un orco, che stringe un tubo d'osso intagliato. Dentro c'è una pergamena sporca di terriccio.$B$BLa pergamena è scritta in orchesco... e sembra importante.",
  obj = "Porta lo Spy's Report a un Theramore Lieutenant.",
  progress = "Devi fare rapporto?",
  reward = "Mmh... L'orchesco non lo leggo molto bene, ma questo ha l'aria di un rapporto... scritto da una spia orchesca!",
  en_title = "The Orc Report",
  en_obj = "Bring the Spy's Report to a Theramore Lieutenant.",
}
T[1220] = {
  title = "Capitano Vimes",
  desc = "Il rapporto orchesco che hai trovato, $N, dovrebbe vederlo il Capitano Vimes. Pochi conoscono la lingua degli orchi meglio di lui. E deve sapere che vicino a Theramore ci sono spie dell'Orda!$B$BIl capitano lo trovi in caserma, sul lato nord-orientale della Theramore Isle.",
  obj = "Porta lo Spy's Report a Captain Garran Vimes.",
  progress = "Hai qualcosa per me?",
  reward = "Un rapporto di una spia orchesca! Come l'hai trovato? Lascia stare — vediamo cosa dice...",
  en_title = "Captain Vimes",
  en_obj = "Bring the Spy's Report to Captain Garran Vimes.",
}
T[1221] = {
  title = "Blueleaf Tubers",
  desc = "I Blueleaf tubers sono una prelibatezza in tutto il mondo! Ma sono rari, rarissimi. Si trovano solo qui nelle Barrens, nelle profondità della terra, a Razorfen Kraul.$B$BE anche lì è impossibile scovarli, se non sai esattamente dove cercare! Per questo ho addestrato questi snufflenose gophers a trovarli per me: hanno un ottimo fiuto, e l'odore di un tubero lo sentono da cinquanta passi.$B$BNon sarà facile, ma se mi porti un po' di tuberi ti pagherò profumatamente.",
  obj = "Prendi una Crate with Holes.$BPrendi uno Snufflenose Command Stick.$BPrendi e leggi lo Snufflenose Owner's Manual.$B$BA Razorfen Kraul, usa la Crate with Holes per evocare uno Snufflenose Gopher, e usa il Vincastro sul roditore per fargli cercare i Tuberi.$B$BPorta 6 Blueleaf Tubers, lo Snufflenose Command Stick e la Crate with Holes a Mebok Mizzyrix a Ratchet.",
  progress = "Ce li hai, i tuberi, $N?",
  reward = "Benissimo, ce li hai! Li posso vendere ai miei contatti per un bel gruzzolo!$B$BGrazie della consegna, $N! Sei $Gun ottimo socio:un'ottima socia;.",
  en_title = "Blueleaf Tubers",
  en_obj = "Grab a Crate with Holes.$BGrab a Snufflenose Command Stick.$BGrab and read the Snufflenose Owner's Manual.$B$BIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.$B$BBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.",
}
T[1222] = {
  title = "La Fuga di Stinky",
  desc = "Grande, finalmente qualcosa che non vuole mangiarmi!$B$BMi serve una mano con le bestiacce qui intorno, e tu fai proprio al caso mio, $Gamico:signora;.$B$BIl cuoco Morgan Stern sta studiando una nuova ricetta e mi ha mandato qui a raccogliere foglie di trifoglio fibrino. Gli piaceranno, immagino.$B$BComunque, mentre cercavo una pianta di trifoglio fibrino... mi sono ritrovato circondato! Mi aiuti a uscire di qui e mi guardi le spalle mentre cerco il trifoglio?",
  obj = "Scorta \"Stinky\" Ignatz, poi parla con Morgan Stern a Theramore.",
  progress = "Hai visto Mr. Ignatz? L'ho mandato nella palude un po' di tempo fa e non è ancora tornato!",
  reward = "Mr. Ignatz è appena passato con le foglie di trifoglio fibrino e mi ha detto che l'hai tirato fuori da un brutto guaio.$B$BGrazie, $N. Chiederò a mio zio di offrirti un banchetto la prossima volta che passi dal Blue Recluse a Stormwind.",
  en_title = "Stinky's Escape",
  en_obj = "Escort \"Stinky\" Ignatz, then speak with Morgan Stern in Theramore.",
}
T[1238] = {
  title = "Il Rapporto Perduto",
  desc = "Frugando nella terra smossa si trova la mano mozzata di un orco. La mano stringe un tubo di osso intagliato, e dentro il tubo c'è una pergamena sporca di terra.$B$BSi tratta del rapporto di un orco che ha passato settimane a spiare la città di Theramore.$B$BBasta scorrere la pergamena per capire che va portata al maestro delle spie orco in Brackenwall Village.",
  obj = "Porta lo Spy's Report a Nazeer Bloodpike in Brackenwall Village.",
  progress = "Hai qualcosa per me?",
  reward = "Ottimo lavoro, $N. Marg Nighteye, il nostro agente, era appostato fuori da Theramore per spiare la città.$B$BQuesto è il suo rapporto più recente, e forse sarà l'ultimo — da quello che mi racconti, temo che Marg abbia trovato la morte nella palude...",
  en_title = "The Lost Report",
  en_obj = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.",
}
T[1239] = {
  title = "La Testa Mozzata",
  desc = "Scavi con vigore e trovi la testa di un orco maschio, mozzata all'altezza del collo con un taglio frastagliato. Ha le labbra contratte in un ringhio e gli occhi scuri fissano con aria di sfida.",
  obj = "Porta la Defiant Orc Head a Nazeer Bloodpike a Brackenwall Village.",
  progress = "Hai altro da riferire, $N?",
  reward = "Questa è la testa di Marg Nighteye! È morto, proprio come temevo.$B$BGuarda la ferita sul collo! Quel taglio frastagliato può averlo fatto un'arma, o è stata una bestia a uccidere il nostro agente?$B$BÈ un mistero da risolvere, $N: dobbiamo scoprire se Marg è morto per mano dell'Alleanza!",
  en_title = "The Severed Head",
  en_obj = "Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village.",
}
T[1240] = {
  title = "Lo Stregone dei Troll",
  desc = "Dobbiamo sapere come è morto Marg! E per scoprirlo, $N, c'è un solo modo: la magia stregonesca dei troll.$B$BPorta la testa di Marg a Kin'weelay, nella Stranglethorn Vale, al Grom'gol Base Camp.$B$BKin'weelay è lo stregone più potente dei troll Darkspear: se qualcuno può parlare con lo spirito di Marg Nighteye, quello è lui.",
  obj = "Porta la Defiant Orc Head a Kin'weelay in Grom'gol Base Camp, in Stranglethorn Vale.",
  progress = "Hai uno spirito arrabbiato intorno, $Gfratello:sorella;. Cosa ti porta da Kin'weelay?",
  reward = "Ah, adesso capisco. Lo spirito di questo orco è legato al nostro mondo e ribolle di rabbia per un compito rimasto incompiuto.$B$BBene, facciamo due parole con questo orco arrabbiato...",
  en_title = "The Troll Witchdoctor",
  en_obj = "Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale.",
}
T[1241] = {
  title = "Il Diplomatico Scomparso",
  desc = "Di recente un diplomatico è stato inviato a Theramore per incontrare Jaina Proudmoore. Non è mai arrivato.$B$BCredo che dietro questo complotto ci siano i Defias, ma non so in che modo. Per ora la scomparsa del diplomatico non è trapelata, ma non resterà nascosta a lungo.$B$BGli agenti del re stanno già setacciando la città in cerca di indizi, ma vorrei coinvolgere anche i miei contatti.$B$BNella Valley of Heroes c'è un mio vecchio amico di nome Jorgen. Trovalo, consegnagli questo biglietto e segui le sue istruzioni.",
  obj = "Trova Jorgen a Stormwind City.",
  progress = "Hmph, spero per te che tu abbia un buon motivo per disturbare un uomo mentre pesca. Non mi vanno a genio i venditori ambulanti, figurarsi gli accattoni.",
  reward = "Hmm... <Jorgen ti squadra con gli occhi socchiusi.>$B$BE va bene. Ti aiuterò, non perché lo voglia, ma perché ci sono obbligato.$B$BE mettiamo subito in chiaro una cosa: già così sai molto più di quanto dovresti. Che resti il nostro piccolo segreto, e non andare a spifferare in giro per le taverne niente di quello che scopri. Capito?",
  en_title = "The Missing Diplomat",
  en_obj = "Find Jorgen in Stormwind City.",
}
T[1242] = {
  title = "Il Diplomatico Scomparso",
  desc = "Porta 'sto biglietto a Elling Trias. Non dirgli nient'altro. Limitati a essere $Geducato:educata; e aspetta che ti risponda. E non preoccuparti, lo farà.$B$BTe lo ripeto solo un'altra volta, $N: prendi questa faccenda sul serio e tieni il becco chiuso.$B$BTrias lo trovi nella sua bottega di formaggi, Trias' Cheese, nel Trade District. Buona fortuna.",
  obj = "Consegna a Trias il Sealed Note to Elling di Jorgen, a Stormwind City.",
  progress = "Salve, $N. Posso fare qualcosa per te? Ti andrebbe di assaggiare il cheddar Trias, la nostra specialità? O un pezzo di Darnassian Bleu?",
  reward = "Come, scusa? Una lettera per me? Ma guarda un po'... a uno che non fa altro che lavorare non capita spesso di ricevere qualcosa che non sia una cassa o un barile. Vediamo di che si tratta.$B$B<Elling alza lo sguardo su di te mentre apre la lettera.>$B$BSembri un po' $Gteso:tesa;, tutto bene, $N?",
  en_title = "The Missing Diplomat",
  en_obj = "Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City.",
}
T[1243] = {
  title = "Il Diplomatico Scomparso",
  desc = "Jorgen, vecchio figlio di una.... Quindi è così che stanno le cose, eh?$B$BVa bene, ci posso stare. Spero che finisca nella Twisting Nether ancora prima!$B$BEcco come andrà, $N. Io comincerò a sentire i miei contatti qui, ma il grosso del lavoro sul campo lo fai tu, così risparmio qualche moneta.$B$BVai a Darkshire, nel Duskwood, e cerca Watcher Backus — di solito pattuglia la strada a nord, appena fuori città. Digli solo che stai indagando per conto mio su eventuali attività dei Defias, e ti dirà tutto quello che sa.",
  obj = "Consegna il Sealed Note to Watcher Backus a Duskwood.",
  progress = "Non è molto sicuro andarsene in giro per i boschi, $N. Fai attenzione, e se vedi qualcosa di sospetto o pericoloso, avvisa subito The Watchers. Non cercare di affrontare niente da $Gsolo:sola;. Se ti capita qualcosa di terribile, non ne siamo responsabili.$B$BMa sappiamo tutti e due che non mi darai retta e combatterai comunque qualsiasi cosa salti fuori dal buio, vero? Haha, già, voi avventurieri... tutti uguali.",
  reward = "Oh, ti manda Trias, eh? Allora la cosa cambia un po'.$B$BCombatti pure tutte le mostruosità che sbucano dal buio per attaccarti. Se frequenti gente come lui, sono sicuro che te la caverai senza troppa fatica.$B$BAllora, cosa vuole da me il mio amico in una giornata così cupa?",
  en_title = "The Missing Diplomat",
  en_obj = "Give the Sealed Note to Watcher Backus in Duskwood.",
}
T[1244] = {
  title = "Il Diplomatico Scomparso",
  desc = "Attività dei Defias? Be', qualche attività c'è sempre: anche se se ne stanno per conto loro, li consideriamo una minaccia.$B$BPerò, ora che ci penso, di recente c'è stato un avvistamento che mi è sembrato strano. Sarà stato un paio di settimane fa: alcuni dei loro agenti si erano radunati intorno ad Addle's Stead. A giudicare dal rapporto, ho pensato che fosse successo qualcosa di grosso.$B$BPerché non cominci da lì e mi riporti quello che trovi?$B$BLa fattoria si trova a sud della strada che arriva da Westfall, appena entri a Duskwood.",
  obj = "Trova il Defias Docket e riportalo a Watcher Backus a Duskwood.",
  progress = "Stai $Gattento:attenta; là fuori, $N. So che è stato Trias a mandarti qui, ma questo non vuol dire che nei boschi non si nasconda qualcosa che può crearti dei guai... soprattutto ora che indaghi sui Defias.",
  reward = "Sei $Gtornato sano e salvo:tornata sana e salva;. Non si potrebbe chiedere di meglio, no?$B$BAllora, vediamo un po' cosa abbiamo qui. A giudicare dai documenti dei Defias che ho visto finora, questo sembra piuttosto ufficiale. Però potrebbe essere un falso, fatto apposta per sviarti da quello che stai cercando.",
  en_title = "The Missing Diplomat",
  en_obj = "Find the Defias Docket and return it to Watcher Backus in Duskwood.",
}
T[1245] = {
  title = "Il Diplomatico Scomparso",
  desc = "Accidenti, questo è fin troppo complicato per essere solo un modo per sviarti. Non dovrei nemmeno guardare queste cose. Portalo a Trias--he'll — lui saprà capirci qualcosa. E NON permettere a nessuno di ostacolarti. È una faccenda più grande di me. Forse persino più grande di lui, ma vedremo.$B$BE fammi un favore, $N, non dire a nessuno che ti ho aiutato. Se i miei superiori scoprissero che sapevo qualcosa di tutto questo e non gliel'ho riferito, probabilmente mi impiccherebbero.",
  obj = "Porta il Defias Docket a Elling Trias a Stormwind.",
  progress = "Vedo che sei $Gtornato:tornata;, e $Gtutto intero:tutta intera;. Sappiamo entrambi che non sei qui per il formaggio, quindi lasciamo perdere i convenevoli. Backus ti è stato d'aiuto, o non sei nemmeno ancora $Gpartito:partita; per Duskwood?",
  reward = "Già... è una lettura interessante. Jorgen e DeLavey hanno fatto bene a coinvolgermi.$B$BSembra che i Defias ce l'abbiano messa tutta per portare a termine questo loro piano. Mmm... e questo cos'è? \"Fist\"? È un nome che mi suona familiare.",
  en_title = "The Missing Diplomat",
  en_obj = "Bring the Defias Docket to Elling Trias in Stormwind.",
}
T[1246] = {
  title = "Il Diplomatico Scomparso",
  desc = "Sì, ora che ci penso... Dashel... Dashel qualcosa... Come si chiamava? FIST! Dashel Stonefist. In certi ambienti lo chiamano Fist — probabilmente perché gli piace fare a botte.$B$BDi solito lo trovi nell'Old Town — proprio nel bel mezzo. Va' a parlarci. Se serve, usa una spada o qualcosa di pesante e contundente per convincerlo a sbottonarsi un po'. E non esitare. Se è coinvolto quanto lasciano intendere queste carte, non ti dirà niente di sua spontanea volontà.",
  obj = "Parla con Dashel Stonefist a Stormwind.",
  reward = "Cosa?!$B$BVieni nel mio vicolo a fare domande sui fatti miei? Fatti che di sicuro non ti riguardano.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Dashel Stonefist in Stormwind.",
}
T[1247] = {
  title = "Il Diplomatico Scomparso",
  desc = "Allora, sì... ehm... forse so qualcosa di quell'incontro ad Addle's Stead. È successo qualche settimana fa, credo. Io non c'entravo proprio niente. La mia parte è finita quando è saltato il piano A... maledetti avventurieri.$B$BIl tizio che avevamo infiltrato per il piano B veniva da Menethil; uno che chiamano Slim. È tutto quello che so del loro piano di riserva.",
  obj = "Parla con Elling Trias a Stormwind.",
  reward = "Mi fa piacere vederti ancora $Gvivo:viva;, $N. Allora con Dashel è andata bene, eh?$B$BHo continuato a studiare questo loro progetto e, anche se non fa il nome del diplomatico a cui davano la caccia, parla del piano B che hanno messo in atto quando il primo tentativo di catturarlo è fallito.$B$BQui questo Slim di cui parlava Dashel non compare con altri nomi, ma se dici che si trova a Menethil, è già un inizio.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Elling Trias in Stormwind.",
}
T[1248] = {
  title = "Il Diplomatico Scomparso",
  desc = "Un mio contatto si è ritirato nelle Wetlands, nella città portuale di Menethil. Se gli dici che lavori per me, dovrebbe fidarsi della tua parola e aiutarti. Si chiama Mikhail. Prima di lasciare Stormwind, qualche anno fa, aveva detto che voleva fare il barista.$B$BParlaci, trova questo Slim e scopri se c'è altro da sapere sul diplomatico rapito. Dobbiamo capire dove l'hanno portato, o almeno chi è. Il documento non dice niente dei loro piani dopo la cattura.",
  obj = "Parla con Mikhail in Wetlands.",
  reward = "$GBenvenuto:Benvenuta;, $Gbenvenuto:benvenuta;, $Gbenvenuto:benvenuta;, $N. Che piacere averti qui. Una birra, oggi? O magari un po' di montone?$B$BDimmi cosa desideri e farò in modo che non ti manchi nulla. Mi chiamo Mikhail, e sarò felice di servirti.$B$BMmm? Come dici? Trias? Abbassa la voce, $Gamico mio:amica mia;. Non è roba che deve sentire tutta la taverna.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Mikhail in the Wetlands.",
}
T[1249] = {
  title = "Il Diplomatico Scomparso",
  desc = "Dici che ti manda Elling? Be', allora sarò dieci volte più ospitale. Qualunque cosa ti serva, chiedi pure. Farò del mio meglio per aiutarti.$B$BHmm, Slim, dici? Il nome non mi dice niente, ma terrò gli occhi aperti.$B$BNon voltarti, $N, ma il signore vicino all'uscita sta guardando da questa parte. Sta seguendo i nostri discorsi con un po' troppa attenzione, se capisci cosa voglio dire? Se fossi in te, farei il possibile per neutralizzarlo prima che si precipiti verso la porta.",
  obj = "Neutralizza Tapoke Jahn prima che fugga, poi torna da Mikhail a Menethil.",
  progress = "Ti è sfuggito? Aveva un'aria un po' losca, da come ci guardava.",
  reward = "L'hai preso, eh? Ben fatto. Mi sorprende che fosse proprio Slim.$B$BA dire il vero, non avrei mai pensato che mi sarebbe mancato il brivido dei traffici più subdoli della malavita. Il lupo perde il pelo ma non il vizio, a quanto pare. Non dirlo a Elling — se sapesse che mi manca l'azione, probabilmente cercherebbe di farmi tornare a Stormwind.$B$BSono contento di esserti stato almeno un po' utile durante la tua permanenza a Menethil. Se ti serve altro, chiedi pure.",
  en_title = "The Missing Diplomat",
  en_obj = "Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil.",
}
T[1250] = {
  title = "Il Diplomatico Scomparso",
  desc = "Quello che mi davano i Defias non bastava per farmi morire per la loro causa. Hanno preso il re. Sì, il re di Stormwind, mica un diplomatico qualunque. Stava andando a Theramore per incontrare Jaina Proudmoore — una faccenda importante, a quanto pare, e molto segreta. Ma dietro non ci sono solo i Defias: lavorano con qualcuno. Secondo me sapevano che la cosa era troppo grossa per loro.$B$BIo dovevo solo far salire il loro uomo sulla nave del re mentre era all'ormeggio. Il tizio si chiamava Hendel. Non so altro, lo giuro!",
  obj = "Parla con Mikhail in Wetlands.",
  reward = "IL RE?! Cioè... il re? Il re vero? Mi prendi in giro? Non mi avevi detto che cercavi chi ha rapito il re. Non sapevo neanche che fosse scomparso — il che spiegherebbe perché stanno per incoronare suo figlio.$B$BAvviso subito Elling: vorrà sapere che sei sulle loro tracce.$B$BNon l'avrei mai detto, che Jahn vendesse Stormwind per quattro soldi. Su certe cose anche un furfante deve avere un po' d'onore.$B$BAdesso l'importante è trovare questo Hendel, e lì credo di poterti aiutare.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Mikhail in the Wetlands.",
}
T[1251] = {
  title = "Il Black Shield",
  desc = "Al camino in rovina, uno dei pochi resti di quella che un tempo era la Shady Rest Inn, è fissato uno scudo di ferro, annerito dall'incendio che ha devastato la locanda.$B$BLo scudo si può staccare dai mattoni del camino.",
  obj = "Porta il Blackened Iron Shield a Krog a Brackenwall Village.",
  progress = "Che cos'hai lì, $N? Una prova trovata fra i resti della Shady Rest Inn?",
  reward = "Gli umani hanno gusti strani per arredare, lo ammetto, ma davvero userebbero un semplice scudo di ferro per decorare il camino? Forse ce l'hanno messo quelli che hanno bruciato la locanda.$B$BUn avvertimento? Una minaccia?",
  en_title = "The Black Shield",
  en_obj = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.",
}
T[1252] = {
  title = "Tenente Paval Reethe",
  desc = "Qualcosa luccica a terra, sotto le macerie, e attira la tua attenzione. Ripulito l'oggetto dalla cenere e dai detriti incrostati, compare l'insegna di un'ancora d'oro smaltata su fondo bianco: il simbolo di Theramore.$B$BSotto l'ancora c'è un nome in rilievo: \"Tenente Paval Reethe\".",
  obj = "Porta il Reethe's Badge a Captain Garran Vimes a Theramore.",
  progress = "Alla Shady Rest Inn hai trovato qualcosa di interessante?",
  reward = "Quando mi portano il distintivo di una guardia, non è mai una buona notizia.$B$BA volte è un uomo o una donna caduti in battaglia, e tocca a me portare la notizia alla famiglia in lutto. Altre volte non scopriamo mai che fine abbiano fatto. E altre ancora va pure peggio.",
  en_title = "Lieutenant Paval Reethe",
  en_obj = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.",
}
T[1253] = {
  title = "Il Black Shield",
  desc = "Al camino in rovina, una delle poche parti rimaste dell'edificio che un tempo era la Shady Rest Inn, è fissato uno scudo di ferro, annerito dall'incendio che ha devastato la locanda.$B$BLo scudo si può staccare dai mattoni del camino.",
  obj = "Porta il Blackened Iron Shield a Captain Garran Vimes a Theramore.",
  progress = "Sul luogo della Shady Rest Inn hai trovato delle prove?",
  reward = "Mmh, di come si fabbricano armi e armature non sono un esperto. Di come si usano sì, ma di come si fanno no.$B$BA parte i danni dell'incendio che ha divorato la locanda, questo scudo sembra uguale a tanti altri.",
  en_title = "The Black Shield",
  en_obj = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.",
}
T[1258] = {
  title = "... e Crostacei",
  desc = "Un altro ingrediente della mia nuova ricetta è una zampa di granchio gigante ancora nel guscio. E i granchi che si trovano a Dustwallow — quelli che chiamano Muckshell — proprio non vanno bene! Temo che gli unici granchi adatti allo scopo vivano molto lontano, nella Swamp of Sorrows.$B$BIl guscio della zampa è fondamentale per la presentazione del piatto, quindi mi servono zampe perfette, senza graffi né ammaccature. Un granchio adulto potrebbe averne soltanto una o due in queste condizioni, e a me ne servono parecchie per poter mettere a punto la ricetta.$B$BAllora, $N... te la senti di metterti in viaggio?",
  obj = "Porta 12 Pristine Crawler Legs a Morgan Stern, a Theramore.",
  progress = "La mia ricerca sulle lingue dei Mudrock procede a meraviglia. La caccia ai granchi va altrettanto bene?",
  reward = "Sono esemplari magnifici, $N! I gusci sono in perfette condizioni, e la carne è rosa e tenera. Ne sono convinto, hai il sangue di uno chef nelle vene!",
  en_title = "... and Bugs",
  en_obj = "Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore.",
}
T[1259] = {
  title = "Tenente Paval Reethe",
  desc = "Il nome del Tenente Paval Reethe non mi dice niente. Ti conviene chiedere ad Adjutant Tesoran, che tiene i registri di tutta la guardia di Theramore, dal personale all'equipaggiamento.$B$BCon una rapida occhiata ai suoi libri dovrebbe riuscire a dirti chi è questo Reethe.",
  obj = "Scopri di più su Reethe da Adjutant Tesoran a Theramore.",
  reward = "Salve, $N. Cerchi informazioni su un membro della guardia di Theramore? Reethe, giusto?$B$BDammi solo un momento, che trovo il libro.",
  en_title = "Lieutenant Paval Reethe",
  en_obj = "Find out more about Reethe from Adjutant Tesoran in Theramore.",
}
T[1260] = {
  title = "Morgan Stern",
  desc = "Sto preparando un nuovo menù per il ristorante, tutto di piatti rustici a tema \"bayou\". Credo che i miei clienti al Blue Recluse li adoreranno!$B$BHo mandato mio nipote Morgan a Theramore, una città ai margini della Dustwallow Marsh, a raccogliere ricette dalla gente del posto, e ora devo sapere cosa ha trovato finora.$B$BFino a Theramore c'è tanta strada, troppa per me. Ma scommetto che $Gun:una; giovane $C come te coglierebbe al volo l'occasione di mettersi in viaggio, vero?",
  obj = "Parla con Morgan Stern a Theramore.",
  reward = "Oh, ti ha mandato mio zio, vero?$B$BBeh, sto facendo ricerche sulle ricette e ho qualche pista, ma mi serve aiuto.$B$BL'aiuto di qualcuno che se la senta di bagnarsi i piedi.",
  en_title = "Morgan Stern",
  en_obj = "Speak with Morgan Stern in Theramore.",
}
T[1261] = {
  title = "Marg Parla",
  desc = "Maledetto gusciofango! Non puoi uccidere Marg! Ah, ma sono $Gmorto:morta;. Quindi dev'essere stato quel mostro a uccidermi...$B$BMa la mia missione! La mia missione! Tu, $N, devi portarla a termine.$B$BMentre mi trovavo nei pressi di Theramore, ho visto un gruppo di soldati dell'Alleanza accampati sulla spiaggia. E uno di loro portava un ciondolo... un ciondolo con più gemme di quante un soldato potrebbe mai permettersi!$B$BQuella notte mi sono $Gintrufolato:intrufolata; nell'accampamento e l'ho rubato, ma mentre tornavo alla base un uomo-granchio gusciofango mi ha tolto la vita!$B$B$N, devi trovare quel gusciofango e recuperare il ciondolo!",
  obj = "Porta il Jeweled Pendant a Nazeer, a Brackenwall Village.",
  progress = "$N, hai scoperto che fine ha fatto Marg?",
  reward = "Questo ciondolo lo portava un soldato di Stormwind??$B$BGrazie, $N. Hai svelato il segreto della morte di Marg. Ma il ciondolo è un nuovo mistero da risolvere, che potrebbe avere conseguenze terribili per l'Alleanza e per l'Orda.",
  en_title = "Marg Speaks",
  en_obj = "Bring the Jeweled Pendant to Nazeer in Brackenwall Village.",
}
T[1262] = {
  title = "Fai Rapporto a Zor",
  desc = "È strano che, prima che Marg lo rubasse, il ciondolo fosse nelle mani di semplici soldati. Forse il proprietario era travestito, o forse sono stati proprio i soldati a rubarlo!$B$BIn ogni caso, è un gioiello da nobile, e se vogliamo svelarne il mistero dobbiamo scoprire a chi appartiene davvero.$B$BPortalo a Zor Lonetree, a Orgrimmar. Conosce bene la politica dell'Alleanza e saprà dirti se il ciondolo ha un passato fra i nobili di Stormwind.",
  obj = "Porta il Jeweled Pendant a Zor Lonetree, a Orgrimmar.",
  progress = "Sei $Gvenuto:venuta; fin qui da Brackenwall Village di Dustwallow? Come sta Nazeer, e come procede il suo lavoro nella palude?",
  reward = "Chi ha fatto questo ciondolo ci ha messo grande abilità e precisione, $N. Nessun orco desidererebbe un gioiello simile...$B$BMa molti umani sì.$B$BLo farò studiare. Speriamo di scoprirne i misteri, col tempo.",
  en_title = "Report to Zor",
  en_obj = "Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar.",
}
T[1264] = {
  title = "Il Diplomatico Scomparso",
  desc = "A ogni inizio mese i Kul Tiras Marines prendono tutti la paga, e di solito lasciano Theramore e vanno altrove. Tanti vengono qui a correre dietro alle donne, a far baldoria e a spassarsela. C'è un gruppo che considero di casa, qui alla taverna, e credo che questo Hendel sia uno di loro.$B$BCommander Samaul, a Theramore, potrebbe aiutarti a trovarlo, se Hendel è ancora di stanza lì. È fedelissimo a Proudmoore, ma se gli fai il nome di Elling dovrebbe darti una mano... con discrezione.",
  obj = "Trova Commander Samaul in Dustwallow Marsh.",
  reward = "Piacere di conoscerti, $N. Sono Commander Samaul e guido le forze della Signorina Proudmoore qui a Theramore.$B$BSono molto occupato, ma se hai domande non esitare a farle. Forse dovrò essere breve, però se ti serve il mio aiuto non c'è motivo di essere scortese.$B$BSe pensi di uscire dalla città, ti consiglio di stare $Gattento:attenta;. Oltre a ogres, orchi e murlocs, la parte meridionale della palude è piena di draghi neri.",
  en_title = "The Missing Diplomat",
  en_obj = "Find Commander Samaul in Dustwallow Marsh.",
}
T[1265] = {
  title = "Il Diplomatico Scomparso",
  desc = "Hendel? Sì, lo conosco. Ma cosa vuoi da uno dei miei soldati?$B$BÈ stato Elling a mandarti a cercarlo? Mmh, non mi piace. Se la tua faccenda non fosse preoccupante, Elling non ti avrebbe fatto venire prima da me. Se non puoi dirmi di cosa si tratta lo capisco, ma sappi una cosa: proteggere queste terre è mio dovere. Se pensi di creare disordini, ti suggerisco di dirmi tutto quello che puoi.$B$BCredo che Hendel fosse di stanza alla prima torre fuori da Theramore. Sii prudente.",
  obj = "Perlustra Sentry Point in cerca di qualche traccia di Private Hendel.",
  progress = "Sì, $N?",
  reward = "L'uomo che cerchi, quello che chiamano Hendel, qui non c'è. La Lady Proudmoore ha ricevuto da altre fonti le informazioni che, credo, hai già anche tu, e mi ha chiesto di cercarti e di aiutarti nella tua impresa. Se me lo permetti, ti dirò dove trovare Private Hendel, così potremo consegnarlo alla giustizia.",
  en_title = "The Missing Diplomat",
  en_obj = "Search Sentry Point for any sign of Private Hendel.",
}
T[1266] = {
  title = "Il Diplomatico Scomparso",
  desc = "Private Hendel è a ovest di qui: in questo momento fa la guardia ad alcuni infiltrati di Theramore che si stanno riposando. Tengono d'occhio Brackenwall, la base dell'Orda, e cercano qualunque altra cosa possa minacciare i nostri confini.$B$BTrovarlo non dovrebbe essere difficile; basta cercare le tende lungo la strada.$B$BDevo sbrigare un'altra faccenda, ma ti raggiungerò presto. Se hai problemi, mi trovi sempre nella torre della Lady Proudmoore.",
  obj = "Trova Private Hendel in Dustwallow Marsh.",
  reward = "Salve, $Gcittadino:cittadina;. Da queste parti è pericoloso andare in giro: io non mi tratterrei troppo, se tieni alla vita.$B$BSe le domande sono brevi, vedrò se posso aiutarti. Fai solo attenzione a quei luridi ogres. Si dice che da qualche parte nelle paludi ci sia una base dell'Orda. Gli infiltrati fanno quel che possono per trovarla, ma si va avanti a rilento e abbiamo fatto pochi progressi.",
  en_title = "The Missing Diplomat",
  en_obj = "Find Private Hendel in Dustwallow Marsh.",
}
T[1267] = {
  title = "Il Diplomatico Scomparso",
  obj = "Parla con Jaina Proudmoore nella Dustwallow Swamp.",
  reward = "Lascia che sia io la prima a ringraziarti per tutto quello che hai fatto, $N. Sei $Gstato:stata; una benedizione incredibile per il mio popolo e per la gente di Stormwind. Mi dispiace di non averti potuto conoscere in circostanze migliori.$B$BDevi sapere anche che non posso ringraziarti apertamente per i tuoi sforzi, ma ti assicuro ancora una volta che li apprezzo.$B$BQuando in futuro ti capiterà di passare da Theramore, vieni a cercarmi: proverò a tenerti al corrente della situazione.$B$BGrazie ancora, $N.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Jaina Proudmore in Dustwallow Swamp.",
}
T[1268] = {
  title = "Impronte di Zoccoli Sospette",
  desc = "Dallo scheletro ancora fumante della Shady Rest Inn partono file di impronte di zoccoli. Almeno alcune si distinguono, mentre altre file di orme si vedono appena nel fango molle della palude.",
  obj = "Riferisci a Krog, a Brackenwall Village, delle impronte sospette trovate alla Shady Rest Inn.",
  reward = "Impronte di zoccoli... Potrebbero essere stati i quilboar, immagino. O magari persino i centauri. Nella Barrens ce ne sono parecchi, e non mi pare esagerato pensare che abbiano fatto una cosa del genere.$B$BTe l'ho detto? Non si sono limitati a bruciare la locanda... Hanno ucciso anche la donna e il cucciolo del proprietario. Brutta faccenda, questa.$B$BComunque, manderò Kagoro a scoprire dove portano le tracce.",
  en_title = "Suspicious Hoofprints",
  en_obj = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.",
}
T[1269] = {
  title = "Tenente Paval Reethe",
  desc = "Sotto le macerie, qualcosa luccica a terra e ti attira lo sguardo. Togli i detriti e la cenere che lo incrostano e scopri sulla superficie un'insegna smaltata: un'ancora d'oro su sfondo bianco, il simbolo di Theramore.$B$BSotto l'ancora c'è un nome impresso in rilievo: \"Tenente Paval Reethe\".",
  obj = "Porta il Reethe's Badge a Krog, a Brackenwall Village.",
  progress = "Hai trovato qualche indizio su cosa è successo alla Shady Rest Inn?",
  reward = "Lo conosco, questo umano, Paval Reethe. Patetico, persino per uno della sua razza. Ha abbandonato i compagni d'armi e adesso si nasconde nei boschi.$B$BHo mandato Ogron a stanarlo. Qualcuno degli altri sospetta che ci abbia rubato dalle provviste. Mi pare di aver visto Ogron andare verso sud-est.",
  en_title = "Lieutenant Paval Reethe",
  en_obj = "Bring Reethe's Badge to Krog in Brackenwall Village.",
}
T[1270] = {
  title = "La Fuga di Stinky",
  desc = "Grande, finalmente qualcosa che non vuole mangiarmi!!$B$BMi serve una mano con le bestiacce qui intorno, e tu fai proprio al caso mio, $Gamico:signora;.$B$BUn goblin di Ratchet di nome Mebok Mizzyrix ha bisogno di foglie di trifoglio fibrino per una pozione, o qualcosa del genere... Sinceramente non m'importa il perché — pagava bene e conosco questa palude, quindi eccomi qui.$B$BPeccato che mi abbiano accerchiato prima che trovassi il trifoglio! Mi aiuti a uscire di qui e mi guardi le spalle mentre cerco la pianta di Mebok?",
  obj = "Scorta \"Stinky\" Ignatz, poi parla con Mebok Mizzyrix a Ratchet.",
  reward = "Stinky è passato con le erbe che gli avevo chiesto e mi ha detto che l'hai tirato fuori da un pasticcio. Ottimo lavoro! Chi è amico di Stinky è amico mio!$B$BPoco prima di tornarsene a sud, verso la palude, mi ha chiesto di darti questo, nel caso ti avessi incontrato.",
  en_title = "Stinky's Escape",
  en_obj = "Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.",
}
T[1271] = {
  title = "Banchetto al Blue Recluse",
  reward = "Mio nipote mi ha detto che l'hai aiutato nelle sue ricerche a Dustwallow e che hai tirato fuori dai guai il suo socio. Be', noi Sterns restiamo uniti, e gli amici non li dimentichiamo!$B$BQuindi lavati le mani, $N, perché stiamo per dare una festa in tuo onore!",
  en_title = "Feast at the Blue Recluse",
}
T[1273] = {
  title = "Interrogare Reethe",
  desc = "C'è voluto tanto tempo, ma ho trovato Reethe. Lui nasconde bene, per essere umano.$B$BOgron preoccupato: lui forse matto, dopo tanto tempo in palude. Tu vieni con me, così noi andare prendere risposte da lui.",
  obj = "Va' con Ogron a parlare con Reethe, poi torna da Krog a Brackenwall Village.",
  progress = "L'hai trovato, Reethe?",
  reward = "Hmph. Meno male che Reethe non si aggira più per la palude, ma peccato che gli umani siano fatti così fragili: non si è ripreso nemmeno da una piccola ferita di freccia.$B$BA quanto pare questa pista non ci ha portato da nessuna parte: dobbiamo cercare altrove.",
  en_title = "Questioning Reethe",
  en_obj = "Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village.",
}
T[1274] = {
  title = "Il Diplomatico Scomparso",
  desc = "Scusami, $Gsignore:signora;. Bishop DeLavey mi ha chiesto di rivolgermi agli avventurieri che potrebbero aiutarlo in una questione delicata.$B$BSe potessi andare allo Stormwind Keep senza dare nell'occhio e parlargli appena possibile, sono sicuro che te ne sarebbe grato. Ti raccomando ancora una volta di essere $Gdiscreto:discreta;. È una questione di una certa importanza.",
  obj = "Trova Bishop DeLavey a Stormwind Keep.",
  reward = "Salve, $N. Sono Bishop DeLavey.$B$BSe sei qui a chiedermi dei miei affari nel forte, vuol dire che il giovane Thomas è riuscito a reclutarti per aiutare il nostro regno. È sempre stato bravo a fare quello che gli chiedo.$B$BTemo di non avere molto tempo per le spiegazioni, quindi lascia che sia schietto... e ti prego, fa' in modo che questa faccenda non diventi di dominio pubblico.",
  en_title = "The Missing Diplomat",
  en_obj = "Find Bishop DeLavey in Stormwind Keep.",
}
T[1275] = {
  title = "Ricerche sulla Corruzione",
  desc = "Quegli sciocchi degli elfi del sangue trafficano con la magia demoniaca. Non hanno visto che fine hanno fatto i naga e i satiri di Kalimdor?$B$BTemo che li attenda una deformazione simile. Azeroth non può permettersi di dare alla luce un'altra vile razza di mostri.$B$BVoglio studiare i tronchi cerebrali dei satiri e dei naga, per capire quale destino aspetta gli elfi. Troverai sia satiri sia naga nei Blackfathom Deeps, sulla costa di Ashenvale.$B$BLungo è il viaggio, $N.",
  obj = "Gershala Nightwhisper ad Auberdine vuole 8 Tronchi Cerebrali Corrotti.",
  progress = "Quando avrò campioni a sufficienza da studiare, potrà cominciare il mio vero lavoro. Con i corrupted brain stems dei satiri e dei naga dei Blackfathom Deeps potrò cercare una correlazione fra le mutazioni.$B$BForse quello che scopriremo ci permetterà di impedire agli elfi del sangue di sprofondare ancora di più nella deformità e nel male.",
  reward = "Hai fatto un lungo viaggio, e di certo hai affrontato grandi pericoli.$B$BHai agito con altruismo: aiutandomi nelle ricerche, lavori per il bene di tutta Azeroth. Ti ringrazio, $N, per tutto quello che hai fatto.$B$BOra scusami, mi aspetta molto lavoro...",
  en_title = "Researching the Corruption",
  en_obj = "Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems.",
}
T[1276] = {
  title = "Il Black Shield",
  desc = "Ah, ora ricordo! Mosarn è un fabbro di Thunder Bluff, e molto rispettato. Lo sapevo che quel nome l'avevo già sentito da qualche parte.$B$BL'Earthen Ring mi ha donato un'armatura forgiata da Mosarn, per ringraziarmi. Gran bel lavoro.$B$BMagari potrà dirti qualcosa di più sullo scudo che ha forgiato.$B$BNon è granché come pista, ma da Reethe non abbiamo cavato niente di utile, e non abbiamo altro.",
  obj = "Mostra il Blackened Iron Shield a Mosarn a Thunder Bluff.",
  progress = "Salve, $C. Hai bisogno di qualcosa?",
  reward = "Sì, hai proprio ragione: questo scudo l'ho fatto io.$B$BTemo però di non poterti dire molto altro, $N. Forgio così tanti scudi e armature, tutti diversi, che non riesco a ricordarli tutti.",
  en_title = "The Black Shield",
  en_obj = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.",
}
T[1282] = {
  title = "Lo Chiamano Smiling Jim",
  desc = "Che ci posso fare, il vecchio Jim lì mi fa pena. Non è sempre stato così. Per un po' ha mandato avanti una locanda nella palude, un posto meraviglioso.$B$BSenti, non mi va molto di parlarne. Se proprio devi, chiedi al Capitano Vimes.",
  obj = "Parla con Captain Garran Vimes a Theramore.",
  reward = "In realtà si chiama James Hyal. Ha aperto una locanda ai margini delle Barrens: voleva farne un bel posto dove i viaggiatori potessero fermarsi...$B$BForse puntava troppo in alto, ma per un po' la locanda è andata bene. Poi abbiamo perso il controllo delle strade della palude e gli ogres hanno preso il sopravvento.$B$BJames era troppo testardo per lasciare il suo sogno e mettersi al sicuro dentro le nostre mura, e la Shady Rest Inn è finita rasa al suolo dalle fiamme. Stiamo indagando, ma senza molta fortuna. Se vuoi dare una mano, vedi cosa riesci a trovare fra le macerie.",
  en_title = "They Call Him Smiling Jim",
  en_obj = "Speak with Captain Garran Vimes on the top floor of Foothold Citadel.",
}
T[1284] = {
  title = "Impronte di Zoccoli Sospette",
  desc = "Dallo scheletro ancora fumante della Shady Rest Inn partono file di impronte di zoccoli. Almeno alcune si distinguono, mentre altre file di orme si vedono appena nel fango molle della palude.",
  obj = "Riferisci a Captain Garran Vimes, a Theramore, delle impronte sospette trovate alla Shady Rest Inn.",
  reward = "Impronte di zoccoli, eh? In effetti, nelle terre intorno alla Dustwallow Marsh i centauri sono straordinariamente attivi. Durante brevi spedizioni nella Barrens abbiamo trovato i loro accampamenti e i loro possedimenti sparsi un po' per tutta la zona.$B$BManderò Falgran Hastil, uno dei nostri esploratori, a vedere se riesce a capire dove portano le tracce.",
  en_title = "Suspicious Hoofprints",
  en_obj = "Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.",
}
T[1285] = {
  title = "Gli Uomini di Daelin",
  desc = "Reddon... Redpath... Ah, eccolo! Tenente Paval Reethe.$B$BEntrato nella guardia di Theramore con la maggior parte delle reclute che hanno attraversato il mare insieme a Lady Proudmoore. Arruolato a sedici anni nei marine di Kul Tiras. Servizio encomiabile, promozioni...$B$BRisulta disperso.",
  obj = "Riporta le informazioni su Reethe a Captain Garran Vimes a Theramore.",
  reward = "Disperso? È il modo gentile che ha Tesoran per dire traditore.$B$BÈ di sicuro uno di quegli sciocchi tanto ciecamente fedeli ad Admiral Daelin da diventare un traditore. Deliziosa ironia, non trovi? I disertori accusano noi di tradire l'Alleanza.",
  en_title = "Daelin's Men",
  en_obj = "Return the information about Reethe to Captain Garran Vimes in Theramore.",
}
T[1286] = {
  title = "I Disertori",
  desc = "Restare nella palude è stata dura, ma con la nostra determinazione siamo riusciti a tenere diverse torri di guardia difensive sparse per la zona.$B$BDalle ultime informazioni e dai rapporti degli esploratori che mi sono arrivati, risulta che un gruppo di disertori ha occupato la nostra torre abbandonata al Lost Point, a sud-est della locanda.$B$BA capo dei disertori c'è un uomo di nome Jacken. Vedi se riesci a cavargli qualche informazione.$B$BTi avverto, $N. Potrebbe essere un osso duro.",
  obj = "Ottieni informazioni su Reethe da Balos Jacken e dai disertori in Dustwallow Marsh.",
  reward = "Ti ha mandato Vimes? Non ce la faceva a fare il lavoro sporco da solo, eh...",
  en_title = "The Deserters",
  en_obj = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.",
}
T[1287] = {
  title = "I Disertori",
  desc = "Reethe? Quel codardo?$B$BL'abbiamo cacciato dall'accampamento perché continuava a razziare le provviste degli ogres, su a Brackenwall Village. Siamo troppo pochi per tener testa a quei bruti senza cervello.$B$BHa passato il limite una volta di troppo, e l'abbiamo lasciato a cavarsela da solo.$B$BEcco, io ti ho aiutato... Allora perché non aiuti noi e ti dimentichi di averci incontrato?",
  obj = "Parla con Captain Garran Vimes a Theramore di Reethe.",
  reward = "Manderò Lieutenant Caldwell a occuparsi dei disertori al Lost Point, e gli ordinerò anche di trovare Reethe. La palude non è così grande e priva di sentieri da impedirgli di scovarlo.",
  en_title = "The Deserters",
  en_obj = "Speak with Captain Garran Vimes in Theramore about Reethe.",
}
T[1288] = {
  title = "Vimes's Report",
  desc = "Hai fatto un buon lavoro, $N: il migliore che abbia visto fare a $Gun:una; dilettante.$B$BLady Proudmoore mi ha chiesto di tenerla informata su questa situazione delicata, ed è un po' che non le parlo.$B$BPensavo di consegnarle il rapporto più tardi, ma mi sembra più giusto che a parlargliene sia tu. Probabilmente sai rispondere alle sue domande meglio di me.",
  obj = "Porta il Vimes's Report a Lady Jaina Proudmoore, a Theramore.",
}
T[1289] = {
  title = "Vimes's Report",
  desc = "Bene, a giudicare dal Vimes's report, sei $Gstato:stata; di grande aiuto nella sua indagine, e te ne ringrazio.$B$BSapere che la faccenda è in mani così capaci mi fa stare più $Gtranquillo:tranquilla;. Se ti va, vorrei che tornassi dal Capitano Vimes e lo aiutassi a venire a capo di questo mistero.",
  obj = "Torna da Captain Garran Vimes a Theramore.",
}
T[1301] = {
  title = "James Hyal",
  desc = "Prima di lavorare qui al Blue Recluse, ho imparato il mestiere da uno dei migliori cuochi e locandieri che abbia mai conosciuto: si chiamava James Hyal. Tutto quello che ho, e tutto quello che sono riuscito a fare nella vita, lo devo a lui.$B$BChissà come sta. Lui e suo fratello Vincent sono andati a lavorare in una taverna a Menethil Harbor, ma è un po' che non ho sue notizie.$B$BSe mai ti capitasse di passare da quelle parti, me lo potresti salutare?",
  obj = "Parla con Vincent Hyal a Menethil Harbor.",
  reward = "James? Oh, è partito già da un bel pezzo.$B$BGli si è riacceso il patriottismo, immagino. E non è difficile capire perché: con tutta la follia che c'è in Lordaeron, in molti si sono uniti a Jaina Proudmoore quando ha attraversato il mare.",
  en_title = "James Hyal",
  en_obj = "Speak with Vincent Hyal in Menethil Harbor.",
}
T[1302] = {
  title = "James Hyal",
  desc = "Mio fratello James è partito per oltremare con Lady Proudmoore. Stando alle ultime notizie, laggiù i combattimenti si erano calmati e James stava aprendo una locanda da qualche parte nel continente. Ovunque sia, sono sicuro che gli affari gli vanno bene: era un cuoco dannatamente bravo.$B$BÈ un po' che non ho sue notizie — troppo preso dalla sua locanda, scommetto — ma il cancelliere di Theramore saprà dirti dove trovarlo.",
  obj = "Parla con Clerk Lendry a Theramore.",
  reward = "James Hyal, James Hyal... Com'è che questo nome mi suona così familiare?$B$BMa certo! L'incidente di The Shady Rest Inn. Se sai qualcosa di quello che è successo lì, ti esorterei a parlarne con il Capitano Vimes: è lui che segue le indagini.",
  en_title = "James Hyal",
  en_obj = "Speak with Clerk Lendry at Foothold Citadel in Theramore.",
}
T[1318] = {
  title = "Affari Gordok in Sospeso",
  desc = "Adesso tu essere $Gil re:la regina;, così forse tu riprendi prezioso artefatto Gordok da elfo inquietante che chiama sé stesso Principe! Re prima di te fallito, come tutti altri re da quando Tortheldrin — elfo inquietante — rubato artefatto a re Gordok dei vecchi tempi!$B$BArtefatto si chiama Gauntlet of Gordok Might. Storie dei vecchi tempi dire che solo unico vero re dei Gordok può riprenderlo. E storia dei vecchi tempi dire anche che elfo inquietante ancora qui intorno — tu trova artefatto, e lui diventa potente guanto che tu porti per sempre! Yar, io faccio vedere!",
  obj = "Trova il Gauntlet of Gordok Might e riportalo a Captain Kromcrush a Dire Maul.$B$BSecondo Kromcrush, la \"storia dei vecchi tempi\" dice che Tortheldrin — un elfo \"inquietante\" che si faceva chiamare principe — lo rubò a uno dei re Gordok.",
}
T[1319] = {
  title = "Il Black Shield",
  desc = "Mi dispiace di non poterti aiutare granché, $N, ma posso mandarti da qualcuno che ci riesce. Alla fucina lavora Caz Twosprocket, uno dei nostri migliori fabbri.$B$BPortagli lo scudo e senti cosa ti sa dire.",
  obj = "Mostra il Blackened Iron Shield a Caz Twosprocket a Theramore.",
  progress = "Hai qualcosa da mostrarmi?",
  reward = "Mmh... interessante, questo pezzo di ferro. Di sicuro non viene da nessuno dei fabbri che conosco da questa parte del mare, e non è certo opera mia.",
  en_title = "The Black Shield",
  en_obj = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.",
}
T[1320] = {
  title = "Il Black Shield",
  desc = "Ah, per poco non mi sfuggiva... La cinghia di cuoio sul retro dev'essere bruciata, ma a quanto pare era fatta per una persona grossa. Anzi, direi un tauren.$B$BPiù o meno è tutto quello che posso dirti. Di' al Capitano Vimes che mi dispiace di non essere stato più d'aiuto.",
  obj = "Parla con Captain Garran Vimes a Theramore.",
  reward = "Non abbiamo molto da cui partire, ma dovremo tenerne conto. Speriamo che anche altri pezzi del mistero vadano al loro posto: ci aiuterebbero a capire meglio cos'è successo.",
  en_title = "The Black Shield",
  en_obj = "Speak with Captain Garran Vimes in Theramore.",
}
T[1321] = {
  title = "Il Black Shield",
  desc = "Hmm... In questo scudo non ci vedo niente di strano. Dovremmo farlo vedere a Do'gol, il fabbro, e sentire se sa dirci qualcosa di più. Ma non ci spererei troppo...",
  obj = "Mostra il Blackened Iron Shield a Do'gol a Brackenwall Village.",
  progress = "Qualcosa per me, $C?",
  reward = "Scudo buono, questo. Molto forte, pesante, buono. Ma Do'gol non ha bisogno. Io fa scudi, non li compra, $N.$B$BDovresti saperlo, questo.",
  en_title = "The Black Shield",
  en_obj = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.",
}
T[1322] = {
  title = "Il Black Shield",
  desc = "Hmmm, proprio qui sul bordo dello scudo c'è una scritta, ma con tutta la roba bruciata è difficile leggere.$B$BMi serve acido per farla venire chiara. Va bene il veleno dei ragni Darkfang della palude. Portami un po' delle loro sacche e lo ripulisco.",
  obj = "Procurati 6 Acidic Venom Sacs per Do'gol a Brackenwall Village.",
  progress = "Le hai prese, quelle sacche dai ragni?",
  reward = "Non mi piacciono i ragni troppo grossi per sederci sopra e schiacciarli.$B$BGrazie di averle prese, $N. Adesso le squarcio e le verso sullo scudo...",
  en_title = "The Black Shield",
  en_obj = "Acquire 5 Acidic Venom Sacs for Do'gol in Brackenwall Village.",
}
T[1323] = {
  title = "Il Black Shield",
  desc = "Oh, credo di averci fatto cadere troppo acido, sullo scudo. Fammi strofinare un po'...$B$BHm, si legge un po' male, ma sembra il nome Mosarn. Mai sentito. Forse lo sa Krog: Krog conosce tanta gente.",
  obj = "Parla con Krog a Brackenwall Village.",
  reward = "Mosarn? Mi dice qualcosa... ma non riesco a inquadrarlo. Forse mi tornerà in mente più tardi.$B$BProbabilmente non è importante. Uno scudo può venire da qualsiasi parte e non voler dire niente...",
  en_title = "The Black Shield",
  en_obj = "Talk with Krog in Brackenwall Village.",
}
T[1324] = {
  title = "Il Diplomatico Scomparso",
  desc = "Cosa?! Vieni qui ad accusarmi di essermi alleato con i Defias e credi che me ne resti fermo a farmi insultare?! Qualcosa mi dice che te la stai cercando da un pezzo.",
  obj = "Sconfiggi Private Hendel nella Dustwallow Marsh.",
  progress = "Salve di nuovo, $N. Spero non ti dispiaccia se ti abbiamo dato una mano, ma non potevamo lasciare che Hendel scappasse o, peggio, morisse.",
  reward = "Credimi, quello che sta succedendo turba molto tutti noi, ma lasciaci riportarlo a Theramore per interrogarlo, e vedremo di ritrovare il Re.$B$BSono sicuro che la mia signora Proudmore vorrà ringraziarti per l'aiuto. Va' a parlarle quando hai un momento.",
  en_title = "The Missing Diplomat",
  en_obj = "Defeat Private Hendel in Dustwallow Marsh.",
}
T[1360] = {
  title = "Tesori Recuperati",
  desc = "Avevo un bel lavoro, a scavare a Uldaman, nelle Badlands... finché non sono spuntati quei maledetti troggs. Ne sono uscito a malapena con la pelle, e con nient'altro. Nella confusione mi è rimasta lì la cosa a cui tengo di più: chiusa nel mio forziere è al sicuro dai troggs, questo sì, ma sta proprio in mezzo a loro.$B$BSe riuscissi a recuperarmela, ti sarei debitore in onore e in monete! In fondo alla North Common Hall c'è un forziere con sopra il mio nome: è quello che devi aprire.",
  obj = "Prendi il prezioso cimelio di Krom Stoutarm dal suo forziere in North Common Hall of Uldaman e portaglielo a Ironforge.",
  progress = "Allora, sei $Griuscito:riuscita; a prendere a ceffoni quei troggs quanto bastava per arrivare al mio forziere e arraffare il mio tesoro?",
  reward = "Ah, mi sento di nuovo intero — grazie di cuore.$B$BC'è chi fra i nani ama la lucentezza del metallo, e chi lo scintillio delle gemme... ma uno Stoutarm senza il suo amato boccale in mano non è uno Stoutarm per niente!",
  en_title = "Reclaimed Treasures",
  en_obj = "Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge.",
}
T[1361] = {
  title = "Regthar Deathgate",
  desc = "Regthar Deathgate, un guerriero dell'Orda, sta reclutando agenti per una missione nelle terre di Desolace. Se vuoi offrirti $Gvolontario:volontaria;, va' a parlargli: lo trovi nelle Barrens, in un gruppo di bunker a ovest del Crossroads.$B$BE affila le armi. Desolace è una terra dilaniata dalla guerra.",
  obj = "Parla con Regthar Deathgate.",
  reward = "Sì, sto reclutando. Si va a Desolace, contro i centauri di laggiù. Faccio in fretta, così puoi cominciare subito.",
  en_title = "Regthar Deathgate",
  en_obj = "Speak with Regthar Deathgate.",
}
T[1362] = {
  title = "I Kolkar di Desolace",
  desc = "I centauri Kolkar abitano a Desolace, e le loro forze si sono spinte fin nelle Barrens. Lo sanno tutti, e qui abbiamo agenti dell'Orda che se ne occupano.$B$BMa finché a Desolace i centauri saranno forti, resteranno sempre una minaccia. È ora di liberarcene.$B$BVa' a parlare con Felgur Twocuts al Ghost Walker Post, a Desolace: l'hanno mandato là a raccogliere informazioni sui centauri, e saprà come affrontare al meglio i Kolkar di Desolace.",
  obj = "Parla con Felgur Twocuts al Ghost Walker Post, a Desolace.",
  reward = "Ti manda Regthar? Allora sei qui per occuparti dei centauri. Bene.$B$BSpero che tu sia $Griposato:riposata;. Non so come andrà a finire la nostra campagna contro i centauri, ma so che sarà una lotta lunga.$B$BSiediti e ascolta.",
  en_title = "The Kolkar of Desolace",
  en_obj = "Speak with Felgur Twocuts at Ghost Walker Post in Desolace.",
}
T[1363] = {
  title = "La Richiesta di Mazen",
  desc = "Sono il custode delle opere qui, nella biblioteca dell'Accademia delle Arti e delle Scienze Arcane, e spetta a me fare in modo che tutti i tomi e le pergamene magiche stiano sempre al loro posto. Chissà quali follie succederebbero, se alcuni di questi testi incantati finissero nelle mani sbagliate?$B$BA proposito... la settimana scorsa Dellis, il mio assistente, ha fatto un errore terribile. In biblioteca se la cava piuttosto bene, ma fuori dalle porte di Stormwind è un incapace. Sii $Gun eroe:un'eroina; e dai una mano al vecchio Dellis, d'accordo?",
  obj = "Parla con Acolyte Dellis a Stormwind.",
  reward = "Non è stata colpa mia. Davvero.",
  en_title = "Mazen's Behest",
  en_obj = "Speak with Acolyte Dellis in Stormwind.",
}
T[1364] = {
  title = "La Richiesta di Mazen",
  desc = "Le istruzioni di Master Mazen non lasciavano dubbi: dovevo consegnare un saggio importantissimo a Watcher Mahar Ba, in Nethergarde Keep.$B$BMa nelle Blasted Lands non c'ero mai stato! Che viaggio spaventoso!$B$BArrivato alla Swamp of Sorrows ho sbagliato strada, e mi sono ritrovato circondato da orribili creature di palude simili a piante, che si sono mosse di scatto come per attaccarmi. Sono scappato, ma nella fretta mi è caduto il saggio. Sono sicuro che se l'è preso una di quelle bestie.$B$BPotresti cercare di recuperarlo e consegnarlo a Mahar Ba, per favore?",
  obj = "Recupera il Khadgar's Essays on Dimensional Convergence e consegnali a Watcher Mahar Ba a Nethergarde Keep.",
  progress = "Cosa ti porta a Nethergarde Keep, $R?",
  reward = "Ah, splendido, davvero!$B$BEra da tempo che temevo che Master Mazen dell'Accademia delle Arti e delle Scienze Arcane avesse trascurato la mia richiesta dei Khadgar's Essays on Dimensional Convergence.$B$BCon tutti gli strani avvenimenti in corso, sarà sommerso di richieste.$B$BOra, se permetti, devo cominciare subito le ricerche. Non so dirti quanto mi entusiasmi poter finalmente cogliere la sapienza di un grande come Khadgar.",
  en_title = "Mazen's Behest",
  en_obj = "Retrieve Khadgar's Essays on Dimensional Convergence and deliver them to Watcher Mahar Ba in Nethergarde Keep.",
}
T[1365] = {
  title = "Khan Dez'hepah",
  desc = "I Kolkar non sono gli unici centauri di Desolace. Molti clan vagano per queste pianure aride, e si combattono e muoiono gli uni per mano degli altri. Ed è un bene, perché sono forti e brutali: se i centauri si unissero contro di noi, sarebbero un nemico temibile.$B$BDobbiamo occuparci di loro prima che succeda.$B$BIl tuo primo compito sarà mettere in crisi il clan dei Kolkar uccidendone il capo, Khan Dez'hepah.$B$BIl Kolkar Village è a nord-est di qui. Va', e che la fortuna ti accompagni.",
  obj = "Porta la Khan Dez'hepah's Head a Felgur Twocuts in Desolace.",
  progress = "Hai sconfitto Khan Dez'hepah, $N?",
  reward = "Ben fatto. Un colpo rapido come questo contro i Kolkar è una dimostrazione di forza efficace, e la forza è quello che i centauri capiscono meglio.$B$BLa morte del capo dei Kolkar non metterà in crisi solo il suo clan: farà riflettere anche gli altri.",
  en_title = "Khan Dez'hepah",
  en_obj = "Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace.",
}
T[1366] = {
  title = "Taglia sui Centauri",
  desc = "Hai spaventato i clan dei centauri: ora è il momento di dissanguarli. Mentre viaggi per Desolace, dagli la caccia, di qualunque clan siano, non m'importa. Tu pensa solo a raccogliere orecchie. Un mucchio di orecchie.$B$BSe ne riduci il numero, ne indebolirai la determinazione e spegnerai in loro ogni idea di espansione.$B$BBuona caccia, $N.",
  obj = "Porta 15 Centaur Ears a Felgur Twocuts in Desolace.",
  progress = "Come va la tua collezione di orecchie, $N? È bella grande?",
  reward = "A quest'ora i centauri conosceranno il tuo nome. Anzi, ne sono sicuro: lo conoscono, lo rispettano e lo temono. E come conoscono te, conoscono anche lo stendardo sotto cui cavalchi.$B$BLo stendardo dell'Orda.",
  en_title = "Centaur Bounty",
  en_obj = "Bring 15 Centaur Ears to Felgur Twocuts in Desolace.",
}
T[1367] = {
  title = "Alleanza con i Magram",
  desc = "Se vogliamo sconfiggere i centauri, dobbiamo ritorcere contro di loro il loro stesso odio. Ci alleeremo con uno dei clan, e con il suo aiuto scopriremo come batterli tutti.$B$BSe scegli di allearti con i Magram, uccidi i Gelkis, i loro nemici: così ti guadagnerai il rispetto dei Magram. Quando ne avrai abbastanza, va' a incontrare il loro portavoce, Warug, ai margini del Magram Village, nel sud-est di Desolace.",
  obj = "Ottieni una reputazione Amichevole con i Magram, poi parla con Warug.",
  progress = "Vattene! I Magram non parlano con i deboli. I deboli li uccidiamo!$B$BVuoi parlare con me? Allora mostrami che sei forte. Torna quando avrai ucciso tanti Gelkis.",
  reward = "Quando sentono il tuo nome, $N, i Gelkis piangono. Ti temono e ti odiano. Ti odiano come odiano i Magram!$B$BForse sei forte quanto i Magram. Vedremo...",
  en_title = "Magram Alliance",
  en_obj = "Gain a Friendly reputation with the Magram, then speak with Warug.",
}
T[1368] = {
  title = "Alleanza con i Gelkis",
  desc = "Se vogliamo battere i centauri, dobbiamo rivolgere il loro odio contro loro stessi. Ci alleeremo con uno dei clan, e sarà lui a insegnarci come sconfiggerli tutti.$B$BSe scegli di allearti con i Gelkis, uccidi i Magram, i rivali che odiano di più. Quando ti sarai $Gguadagnato:guadagnata; il rispetto dei Gelkis, va' da Uthek the Wise, la sciamana dei Gelkis: la troverai ai margini del Gelkis Village, nel sud-ovest di Desolace.",
  obj = "Ottieni la reputazione Amichevole con i Gelkis, poi parla con Uthek the Wise.",
  progress = "I tuoi due piedi calpestano la terra dei Gelkis. Qui non sei $Gbenvenuto:benvenuta;!$B$BSe cerchi l'amicizia dei Gelkis, dimostralo: uccidi i centauri Magram, e torna quando il terreno sarà bagnato di sangue Magram.",
  reward = "La terra mi parla, e dice che hai ucciso molti Magram. Questo è bene.$B$BSe sei $Gun amico:un'amica; dei Gelkis, allora ascoltami: ho altri compiti per te.",
  en_title = "Gelkis Alliance",
  en_obj = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.",
}
T[1369] = {
  title = "Broken Tears",
  desc = "I Gelkis credono che Theradras, la madre di noi centauri, ci protegga. Sono stupidi. Nessuno protegge il centauro. I Magram non hanno bisogno di protezione! Siamo i più forti!$B$BMostra ai Gelkis quanto sono stupidi. Va' nella grotta del loro villaggio: lì accumulano cristalli, le lacrime di Theradras. Distruggi le lacrime e portami i pezzi rotti!",
  obj = "Mantieni la reputazione con i Magram e porta 3 Broken Tears a Warug, a Magram Village.",
  progress = "Farai quello che ti chiedo, se non sei $Gnostro nemico:nostra nemica;!",
  reward = "Hai preso le lacrime! Adesso i Gelkis sapranno che Theradras non li aiuterà. Non piangerà, quando li schiacceremo! I Magram domineranno!$B$BSei intelligente ad aiutarci, $N. Siamo i più forti.",
  en_title = "Broken Tears",
  en_obj = "Maintain your reputation with the Magram, and bring 3 Broken Tears to Warug in the Magram Village.",
}
T[1370] = {
  title = "Furto di Provviste",
  desc = "Quando non siamo in guerra, andiamo a caccia per procurarci la carne. La carne ci dà forza, e le pance piene combattono più duramente di quelle vuote.$B$BPer i Magram è lo stesso: tengono da parte un po' di carne in più, per combattere più a lungo fra una caccia e l'altra. Se fai un'incursione nel loro villaggio, a est, e porti via le loro scorte, la loro forza verrà meno.",
  obj = "Porta 6 sacchetti di Crudely Dried Meat a Uthek the Wise nel Gelkis Village.",
  progress = "Torna quando avrai dimostrato di nuovo il tuo valore ai Gelkis!",
  reward = "Bene. Da lontano, dal loro villaggio, sento brontolare forte le pance dei Magram!$B$BQuesta carne la darò ai Gelkis, e combatteremo per molti giorni senza riposo.$B$BQuello che hai fatto è bene per i Gelkis, $N.",
  en_title = "Stealing Supplies",
  en_obj = "Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village.",
}
T[1371] = {
  title = "Un Aggeggio per Warug",
  desc = "Tanto tempo fa è venuto a Desolace un piccolo gnomo. Aveva dei cavalli e un carro, e sul carro c'erano cose strane. Cose buffe. Cose che bruciavano di colori diversi. Cose che si muovevano senza essere vive. Il piccolo gnomo l'ho ucciso, ma prima... mi ha fatto ridere.$B$BDel suo carro ho tenuto la cosa che mi piaceva di più. Era un umano di legno e mi salutava con la mano, finché non gli ho dato un colpo e l'ho rotto.$B$BNe voglio uno nuovo. Portamene uno nuovo!",
  obj = "Mantieni la tua reputazione con i Magram e porta un Advanced Target Dummy a Warug, a Magram Village, in Desolace.",
  progress = "Farai quello che ti chiedo, se non sei $Gnostro nemico:nostra nemica;!",
  reward = "Sì, è proprio quello che avevo! Adesso lo faccio muovere di nuovo. Mi fa ridere!",
  en_title = "Gizmo for Warug",
  en_obj = "Maintain your reputation with the Magram, and bring an Advanced Target Dummy to Warug in the Magram Village in Desolace.",
}
T[1372] = {
  title = "Nient'Altro Che la Verità",
  desc = "È stato Varimathras a mandare il nostro corpo di spedizione a esplorare la parte meridionale di Azeroth.$B$BDurante una perlustrazione ho notato un Infiltrato umano che spiava il Beggar's Haunt. Non ho fatto in tempo a catturarlo, perché alcuni dei nostri... fratelli... orchi lo hanno preso prima di me e portato a Stonard, la loro roccaforte nella Swamp of Sorrows.$B$BVoglio... aiutare... i nostri alleati orchi. Il nostro accampamento qui non l'hanno visto, ma voglio dar loro una mano lo stesso.$B$BPrepara con Faustin, qui, un... siero della verità per il nostro amico a Stonard.",
  obj = "Parla con Apothecary Faustin a Beggar's Haunt.",
  reward = "Zraedus mi stava giusto parlando di quel piccolo Infiltrato ficcanaso, prima che arrivassi tu.$B$BUn bel problema, davvero. Un impiccione che gira a curiosare intorno al Beggar's Haunt è l'ultima cosa che ci serve.$B$BSono sicuro che gli orchi di Stonard non vedano l'ora di sentire cosa ha da dire il nostro amico. Sono nostri alleati, ehm, quindi dobbiamo aiutarli a tirar fuori dall'umano tutte le informazioni che possono.$B$BDammi una mano, $N, e porteremo a Stonard un siero della verità.$B$BPer l'Orda!$B$B...l'ho detto bene?",
  en_title = "Nothing But The Truth",
  en_obj = "Speak with Apothecary Faustin at Beggar's Haunt.",
}
T[1373] = {
  title = "Ongeku",
  desc = "Hai ancora altro da dimostrare, e il prossimo compito ti porterà lontano: per ora i Gelkis combatteranno i Magram senza di te.$B$BA chi ascolta, la terra sussurra molti segreti. Uno di quelli che sento parla di un cristallo rosso chiamato draenethyst, nuovo per la nostra terra. Viene da un luogo dove le montagne volano e regnano i demoni.$B$BPortami un frammento di draenethyst: renderà forte la mia magia! Si trova in un luogo chiamato Swamp of Sorrows, e ce l'ha il perduto Ongeku.",
  obj = "Mantieni la tua reputazione con i Gelkis e porta un Draenethyst Shard a Uthek the Wise nel Gelkis Village, in Desolace.",
  progress = "$N, mostrami che sei $Gun amico:un'amica; dei Gelkis.",
  reward = "Sì, questo è il frammento di cui sussurrava la terra. Dentro ci sento una magia forte! La userò contro i nemici dei Gelkis.$B$BHai portato a termine un altro compito per noi, $N. Presto, forse, ti chiameremo $Gamico:amica;.",
  en_title = "Ongeku",
  en_obj = "Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace.",
}
T[1374] = {
  title = "Khan Jehn",
  desc = "La terra mi parla e mi dice che i Magram si stanno indebolendo. È il momento di uccidere il loro Khan!$B$BPortami la testa di Jehn, il Khan dei Magram!",
  obj = "Porta la Khan Jehn's Head a Uthek the Wise in Gelkis Village, in Desolace.",
  progress = "Dimostrami di essere $Gun amico:un'amica; dei Gelkis, $N.",
  reward = "Khan Jehn era forte, ma stupido. Aveva molta fiducia nella sua forza e non ha visto che la magia della terra è più potente. Ora che non hanno più il loro capo, i centauri Magram cadranno, e un giorno a regnare saranno i Gelkis!",
  en_title = "Khan Jehn",
  en_obj = "Bring the Khan Jehn's Head to Uthek the Wise in the Gelkis Village in Desolace.",
}
T[1375] = {
  title = "Khan Shaka",
  desc = "Aiuti i Magram, e mi piaci. Adesso uccidi il Khan dei Gelkis! Si chiama Khan Shaka, e voglio la sua testa! Voglio fissarla e ridergli in faccia!",
  obj = "Mantieni la tua reputazione con i Magram e porta la Testa di Khan Shaka a Warug in Magram Village, in Desolace.",
  progress = "Fa' qualcosa per i Magram, e io ti aiuterò.",
  reward = "Khan Shaka è morto! Infilerò la sua testa su una picca e la terrò con me, così Shaka potrà vedere quanto sono forti i Magram!",
  en_title = "Khan Shaka",
  en_obj = "Maintain your reputation with the Magram, and bring the Head of Khan Shaka to Warug in the Magram Village in Desolace.",
}
T[1380] = {
  title = "Khan Hratha",
  desc = "$N, ci hai aiutati contro i Magram: ora aiutaci a sconfiggere i Maraudine! Uccidi Khan Hratha, il capo del loro clan!$B$BPer affrontarlo suona il Corno da Guerra dei Maraudine, che si trova in cima a un'alta rupe nella Valley of Spears.$B$BMa per suonarlo devi procurarti un bocchino per corni da guerra. Sono rari: li portano solo i centauri Maraudine più fidati.$B$BQuando avrai suonato il corno arriveranno dei centauri. Uccidili finché non comparirà Hratha.$B$BKhan Hratha ha il pezzo di... una chiave. Portamelo...",
  obj = "Mantieni la tua reputazione con i Gelkis e porta il Maraudine Key Fragment a Uthek the Wise in Gelkis Village.",
  progress = "Khan Hratha è morto? Ce l'hai, il frammento della chiave?",
  reward = "È morto! Khan Hratha è morto! E ora i Maraudine cadranno! Quando i Gelkis regneranno su questa terra, $N, ci ricorderemo di te, e gli spiriti della terra canteranno per sempre il tuo nome.",
  en_title = "Khan Hratha",
  en_obj = "Maintain your reputation with the Gelkis, and bring the Maraudine Key Fragment to Uthek the Wise in the Gelkis Village.",
}
T[1381] = {
  title = "Khan Hratha",
  desc = "Il Khan dei Gelkis è morto, e adesso cadranno i Maraudine! Uccidi il Khan dei Maraudine, Hratha!$B$BSe vuoi affrontarlo, suona il corno sull'alta rupe nella Valley of Spears. Ma senza bocchino il corno non suona, e per averne uno devi uccidere i centauri Maraudine. Continua a ucciderli finché non lo trovi, poi suona il corno.$B$BQuando lo suoni, i centauri Maraudine verranno alla torre. Uccidili finché non arriva Khan Hratha. Hratha ha con sé il frammento di una chiave. Portalo a me...",
  obj = "Mantieni la tua reputazione con i Magram e porta il Maraudine Key Fragment a Warug in Magram Village, in Desolace.",
  progress = "Fa' quello che ti chiedo. Dimostrami che sei $Gun alleato:un'alleata; dei Magram!",
  reward = "Khan Hratha è morto! Adesso i Magram sono i centauri più forti! Schiacceremo gli altri e domineremo Desolace!$B$BNon ci dimenticheremo di te, $N: quando tutti gli altri finiranno calpestati sotto i nostri zoccoli, tu sarai $Grisparmiato:risparmiata;.",
  en_title = "Khan Hratha",
  en_obj = "Maintain your Magram reputation, and bring the Maraudine Key Fragment to Warug in the Magram Village in Desolace.",
}
T[1382] = {
  title = "Strana Alleanza",
  desc = "È una fortuna che i clan dei centauri si combattano fra loro: uniti in un'unica forza, sarebbero inarrestabili. Sì, siamo fortunati, e dovremmo sfruttare questo vantaggio.$B$BUno di questi clan, quello dei Gelkis, è in guerra spietata con quello dei Magram. Se attacchiamo i Magram, forse riusciremo a stringere un'alleanza con i Gelkis.$B$BVa' a parlare con Uthek the Wise: la troverai ai margini degli accampamenti dei Gelkis, nel sud-ovest di Desolace. Grazie a lei potremmo allearci con i Gelkis.",
  obj = "Ottieni la reputazione Amichevole con i Gelkis, poi parla con Uthek the Wise.",
  progress = "Via di qui! I Gelkis non ti vogliono qui. Vattene, subito!!$B$BTorna quando avrai ucciso molti Magram, e allora parlerò con te.",
  reward = "Fra i Gelkis si sussurra il tuo nome. Sulle tue mani c'è molto sangue Magram. Questo è bene.$B$BE forse è bene anche che parliamo: di cosa puoi fare tu per i Gelkis, e di cosa possiamo fare noi per te.",
  en_title = "Strange Alliance",
  en_obj = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.",
}
T[1383] = {
  title = "Nient'Altro Che la Verità",
  desc = "Ho in mente il siero che fa proprio al caso nostro. Tratterà la verità esattamente come va trattata.$B$BPer questo intruglio mi servono diversi cuori di Shadow Panther della Palude, e anche il fungo incantato del Mire Lord che vive laggiù. Sono sicuro che $Guno:una; in gamba come te, $N, saprà convincerlo a cedertene un po'.$B$BLa parte difficile, però, sarà trovare un tumore di Deepstrider nella lontana Desolace. Capita molto di rado che i giganti di laggiù si ammalino e che si formi un tumore.$B$BE ora, va'!",
  obj = "Apothecary Faustin a Beggar's Haunt ha bisogno di 5 Shadow Panther Hearts, del Mire Lord Fungus e di un Tumore di Deep Strider.",
  progress = "Quell'Infiltrato a Stonard di sicuro si... aprirà... una volta bevuto il mio siero speciale. Ah ah!$B$BGli ingredienti che ci servono non sono affatto facili da procurare. Nella Palude le Shadow Panthers sono comuni, ma raccogliere abbastanza cuori per il nostro scopo può essere un'impresa. E il Mire Lord sa essere una bestia davvero schizzinosa.$B$BQuanto al tumore di Deepstrider, trovarlo è terribilmente difficile. Ma la reazione chimica che posso ricavarne non ha eguali.",
  reward = "Splendido, $N! E proprio in tempo, per giunta. A sentire Zraedus, l'Infiltrato si è ripreso dalle ferite ed è pronto perché gli orchi lo interroghino.$B$BDammi solo un momento per preparare il vel — volevo dire, il siero della verità.",
  en_title = "Nothing But The Truth",
  en_obj = "Apothecary Faustin at Beggar's Haunt needs 5 Shadow Panther Hearts, Mire Lord Fungus and a Deep Strider Tumor.",
}
T[1384] = {
  title = "Incursione Contro i Kolkar",
  desc = "I centauri Kolkar credono di avere una magia forte. Ma loro la magia non la conoscono! Non la riconoscerebbero neanche se li mordesse!$B$BGli mostrerai quanto è debole la loro magia. Va' a nord-est, dai Kolkar, e uccidili. Prendi i loro talismani e portameli: li getterò nel fuoco, e riderò!",
  obj = "Mantieni la tua reputazione con i Gelkis e porta 10 Crude Charms a Uthek the Wise nel Gelkis Village, in Desolace.",
  progress = "Ce li hai, i talismani? Hai fatto vedere ai Kolkar quanto sono deboli?",
  reward = "Fai una cosa buona per i Gelkis. I Kolkar sono deboli, e moriranno: la loro magia è patetica, e non li salverà. Tu gliel'hai fatto vedere, e la paura li renderà ancora più fiacchi!$B$BE nelle nostre terre chi è fiacco muore presto.",
  en_title = "Raid on the Kolkar",
  en_obj = "Maintain your reputation with the Gelkis, and bring 10 Crude Charms to Uthek the Wise in the Gelkis Village in Desolace.",
}
T[1385] = {
  title = "Politica Brutale",
  desc = "Desolace è una terra in guerra. I centauri si combattono fra loro, e crediamo che chi vincerà dilagherà fino a minacciare le nostre roccaforti. E questo non possiamo permetterlo.$B$BDobbiamo scoprire come sconfiggere i centauri e, per riuscirci... dobbiamo allearci con uno dei loro clan. I Magram sono in guerra con i Gelkis: se combatti i Gelkis, i Magram potrebbero prendere in considerazione un'alleanza.$B$BGuadagnati il favore dei Magram, poi va' a parlare con Warug, nel villaggio dei Magram, nel sud-est di Desolace.",
  obj = "Ottieni una reputazione Amichevole con i Magram, poi parla con Warug.",
  progress = "Ora vattene, o i Magram ti schiacceranno! Devi uccidere i Gelkis, se vuoi essere $Gnostro amico:nostra amica;.",
  reward = "Tanti Gelkis cadono per mano tua, e questo mi piace. Forse puoi fare altre cose che mi piacciono. Forse tu e i Magram potete essere amici.",
  en_title = "Brutal Politics",
  en_obj = "Gain a Friendly reputation with the Magram, then speak with Warug.",
}
T[1386] = {
  title = "Assalto ai Kolkar",
  desc = "I Kolkar si credono forti, ma noi ridiamo di loro! Ridiamo, e li uccidiamo! Uccidili anche tu: mostrami che sai uccidere i Kolkar come noi. Va' a nord e uccidili tutti!",
  obj = "Mantieni la reputazione con i Magram. Uccidi 12 Kolkar Centaurs, 12 Kolkar Scouts e 6 Kolkar Maulers, poi torna da Warug a Magram Village, in Desolace.",
  progress = "Hai paura dei Kolkar? Perché non li uccidi? Forse non ti ricordi più come si uccide. Sbrigati a uccidere i Kolkar, prima che siano morti!",
  reward = "Adesso i Kolkar ti temono! Spero che tu abbia riso, mentre li uccidevi. Quando uccidi è meglio ridere: così il nemico vede che è debole.",
  en_title = "Assault on the Kolkar",
  en_obj = "Maintain your reputation with the Magram. Kill 12 Kolkar Centaurs, 12 Kolkar Scouts and 6 Kolkar Maulers, then return to Warug in the Magram Village in Desolace.",
}
T[1387] = {
  title = "Taglia sui Centauri",
  desc = "I centauri sono una razza divisa in molti clan, ognuno con il suo capo e i suoi scopi, ma tutti hanno una cosa in comune. La crudeltà.$B$BSe un giorno vogliamo trovare la pace, i centauri vanno eliminati. Ed è proprio questo il compito che affido a te.$B$BMentre giri per Desolace, dai loro la caccia e prendigli le orecchie. Portamene tante, tantissime.$B$BFallo per servire l'Alleanza, $N, e ci avvicineremo di un passo alla fine della guerra.",
  obj = "Porta 15 Centaur Ears a Corporal Melkins a Nijel's Point, in Desolace.",
  progress = "Hai qualcosa da riferire, $N?",
  reward = "Ah, le orecchie. Ben fatto.$B$BNessuno può mettere in dubbio il tuo servizio all'Alleanza, $N. Il sangue che hai versato a Desolace salverà di certo innumerevoli vite.",
  en_title = "Centaur Bounty",
  en_obj = "Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace.",
}
T[1388] = {
  title = "Nient'Altro Che la Verità",
  desc = "Tutto va secondo i piani, $N. Voglio che porti questo siero della verità al Deathstalker Zraedus: sarà lui a mostrarti come somministrarlo.... a dovere.$B$BAhah!",
  obj = "Consegna il Faustin's Truth Serum al Deathstalker Zraedus a Beggar's Haunt.",
  progress = "Spero che ti sia $Greso:resa; utile al nostro caro amico, Apothecary Faustin.",
  reward = "Lo sapevo che il vecchio Faustin avrebbe tirato fuori qualcosa di buono! Non c'è dubbio, sei $Gstato:stata; di enorme aiuto.$B$BOra veniamo al dunque, che ne dici?",
  en_title = "Nothing But The Truth",
  en_obj = "Give Faustin's Truth Serum to Deathstalker Zraedus at Beggar's Haunt.",
}
T[1389] = {
  title = "Draenethyst Crystals",
  desc = "I perduti del Fallow Sanctuary hanno il nostro stesso aspetto, ma sono mostri... li hanno fatti impazzire le fatiche del nostro viaggio verso Azeroth. Un tempo erano nostri fratelli. Ora stanno nel Fallow Sanctuary, a est, e chiunque si avvicini lo catturano o lo uccidono.$B$BE ci hanno rubato una cosa per noi sacra — i draenethyst crystals.$B$BNon abbiamo la forza di entrare nel Fallow Sanctuary e di riprenderci il draenethyst che ci hanno portato via, là fra le loro capanne e i fuochi. Ma senza quei cristalli... potremmo smarrire la via anche noi.",
  obj = "Porta 6 Draenethyst crystals a Magtoor a The Harborage, in Swamp of Sorrows.",
  progress = "Hai i cristalli?",
  reward = "Grazie, $N. Siamo in debito con te.",
  en_title = "Draenethyst Crystals",
  en_obj = "Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows.",
}
T[1390] = {
  title = "Ops, li Abbiamo Uccisi di Nuovo.",
  desc = "Testo mancante",
  obj = "Testo mancante",
  reward = "Grazie per il lavoro che hai fatto!",
}
T[1391] = {
  title = "Nient'Altro Che la Verità",
  desc = "Qui ci vuole una certa discrezione. Dopotutto non puoi mica entrare lì come se niente fosse e convincere quell'idiota a bere questo intruglio di Faustin, no?$B$BMa se c'è una cosa a cui quegli umani non sanno dire di no, è l'alcol. Mescolerò il siero di Faustin in questa birra, e ti garantisco che quel povero babbeo non si farà pregare a scolarsi un boccale tutto d'un fiato.$B$BCorri a Stonard, nella Swamp of Sorrows, $N. E acqua in bocca sulla nostra piccola missione...",
  obj = "Porta la Zraedus's Brew a Infiltrator Marksen a Stonard.",
  progress = "Abbi pietà di me! Ho informazioni che vanno oltre i confini delle alleanze. Non ho simpatia per l'Orda, ma è in corso un tradimento politico che va rivelato!",
  reward = "Da bere per me? Che gentilezza. Sono giorni che non mi concedono un goccio. Lasciami mandare giù questa, e poi ti dirò cosa ho scoperto....",
  en_title = "Nothing But The Truth",
  en_obj = "Take Zraedus's Brew to Infiltrator Marksen in Stonard.",
}
T[1392] = {
  title = "Noboru the Cudgel",
  desc = "Da mesi Noboru tormenta i Draenei of the Harborage, e la sua mazza ferrata è un simbolo della brutalità che i perduti hanno inflitto loro.",
  obj = "Porta la Noboru's Cudgel al capo di The Harborage nella Swamp of Sorrows.",
  progress = "Salve. E $Gbenvenuto:benvenuta; all'Harborage.",
  reward = "Hai l'arma del temuto Noboru? Allora è morto?$B$BOggi è un giorno di gioia per l'Harborage. Noboru e la sua banda erano il nostro terrore: vagavano per le paludi e uccidevano ogni Draenei che incrociasse il loro cammino. Minacciava direttamente la nostra sopravvivenza, e non avevamo la forza di affrontarlo.$B$BÈ una fortuna averti come $Gamico:amica;, $N.",
  en_title = "Noboru the Cudgel",
  en_obj = "Bring Noboru's Cudgel to the leader of The Harborage in the Swamp of Sorrows.",
}
T[1393] = {
  title = "La Fuga di Galen",
  desc = "Aiuto, ti prego! Queste creature mi vogliono mangiare!$B$BPortami via di qui e ti darò un grande tesoro! Sta nel mio accampamento, nella palude a nord di Stonard, chiuso in un forziere che si apre con un trucco che conosco solo io.$B$BSe mi aiuti a scappare, te lo insegnerò.",
  obj = "Scorta Galen fuori pericolo, poi trova il suo accampamento in Swamp of Sorrows e apri il suo forziere.",
  progress = "La serratura del forziere è piena di resina nera. Aprirlo è impossibile.",
  reward = "La serratura del forziere è piena di resina nera. Aprirlo è impossibile.$B$BMa Galen ti ha parlato di un fermo nascosto sul fondo della cassa...$B$B...Cerchi per qualche istante e trovi il fermo. Lo fai scattare e il forziere si apre...",
  en_title = "Galen's Escape",
  en_obj = "Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.",
}
T[1394] = {
  title = "Passaggio Finale",
  desc = "Hai fatto bene, $N. Hai superato la mia prova e quelle che l'hanno preceduta. Torna da Dorn a Thousand Needles: percepirà il cambiamento dentro di te, e vedrà che hai la mente, il corpo e lo spirito così forti da meritare una ricompensa per i tuoi sforzi.$B$BResta fedele all'equilibrio che hai mostrato in queste prove, $N. Se lo farai, in futuro Dorn ti metterà di nuovo alla prova.",
  obj = "Parla con Dorn Plainstalker a Thousand Needles.",
  reward = "Ah, $N. È da molto tempo che non metti piede in casa mia. Sembrano passate tante lune da quel primo salto che ti ha messo in cammino.$B$BE ora torni da me più forte di prima... più $Gilluminato:illuminata;. Mi fa piacere. E meriti di essere $Gricompensato:ricompensata; come si deve per aver portato a termine le mie prove.",
  en_title = "Final Passage",
  en_obj = "Speak to Dorn Plainstalker in Thousand Needles.",
}
T[1395] = {
  title = "Rifornimenti per Nethergarde",
  desc = "Questa cassa di pietre del potere deve arrivare a Nethergarde Keep, nelle Blasted Lands. Le pietre non terranno il potere a lungo, quindi non possiamo affidarle alla prossima carovana.$B$BDevi portarle tu, e in fretta.$B$BConsegnale a Quartermaster Lungertz, a Nethergarde Keep. Per raggiungere la fortezza devi passare il Deadwind Pass andando a est, poi proseguire sempre verso est per la Swamp of Sorrows e infine scendere a sud nelle Blasted Lands.$B$BFai attenzione, $N. Le terre che attraverserai sono pericolose, ma non puoi permetterti di fallire.",
  obj = "Porta la Cassa di Pietre del Potere a Quartermaster Lungertz prima che le pietre del potere si esauriscano.",
  progress = "Salve! Non badare a tutta questa confusione, qui a Nethergarde Keep è la solita routine.$B$BHai qualcosa per me?",
  reward = "Ah, le pietre del potere! Ai maghi farà piacere vederle!$B$BGrazie mille, $N. Lo so che il viaggio da Darkshire non è stato facile.",
  en_title = "Supplies for Nethergarde",
  en_obj = "Bring the Crate of Powerstones to Quartermaster Lungertz, before the powerstones expire.",
}
T[1396] = {
  title = "La Fauna Selvatica Avanza",
  desc = "La mia carovana era diretta alla costa orientale, ma non ci siamo mai arrivati. I Lost Ones ci hanno attaccati: hanno ucciso le guardie e distrutto le provviste.$B$BDel loro assalto sono l'unico sopravvissuto. Ho giurato di proteggere quel che resta delle provviste, ma qui intorno si aggirano creature selvatiche. Ti prego, aiutami a difendere l'accampamento dalle bestie!",
  obj = "Uccidi 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners e 10 Swamp Jaguars, poi torna da Watcher Biggs nella Swamp of Sorrows.",
  progress = "Le creature della palude si avvicinano sempre di più, $N. Ti prego, devi difendere l'accampamento!",
  reward = "I versi degli animali ora arrivano deboli, più lontani. Grazie, $N. Adesso speriamo che non tornino!",
  en_title = "Encroaching Wildlife",
  en_obj = "Kill 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners and 10 Swamp Jaguars then return to Watcher Biggs in the Swamp of Sorrows.",
}
T[1398] = {
  title = "Rami Portati dal Mare",
  desc = "Ti devo molto, $N. In te batte un cuore nobile. E ora ho un altro compito, per cui ti chiedo umilmente aiuto.$B$BPer arrivare a Nethergarde devo riparare questo carro. E per ripararlo... mi serve del legno. Legno robusto e secco — non quello spugnoso e contorto degli alberi della palude.$B$B$N, vai verso est fino alla costa e cerca dei rami portati dal mare e seccati dal sole. Portameli.",
  obj = "Porta 8 Sundried Driftwood a Watcher Biggs nella Swamp of Sorrows.",
  progress = "Hai trovato dei rami, $N?",
  reward = "Questo legno è leggero, ma resistente. Grazie, $N. Andrà benissimo.",
  en_title = "Driftwood",
  en_obj = "Bring 8 pieces of Sundried Driftwood to Watcher Biggs in the Swamp of Sorrows.",
}
T[1418] = {
  title = "Neeka Bloodscar",
  desc = "Le Badlands sono una terra dura e stanno vicino alla regione di Loch Modan, che è in mano all'Alleanza: per questo Stonard e l'avamposto di Kargath, nelle Badlands, perdono spesso i contatti.$B$BDimostra quanto vali, $N. Va' nelle Badlands e parla con Neeka Bloodscar, la capo esploratrice dell'avamposto di Kargath, poi fammi avere il suo rapporto.",
  obj = "Parla con Neeka Bloodscar.",
  reward = "Quindi Helgrum vuole un rapporto, eh? Neanche tre giorni fa ho mandato un messaggero a Stonard. Ha fallito la missione? Se a Stonard il mio rapporto non ce l'hanno, pare proprio di sì.$B$BSperiamo che il prossimo che mando sia più abile, o più fortunato.",
  en_title = "Neeka Bloodscar",
  en_obj = "Speak with Neeka Bloodscar.",
}
T[1419] = {
  title = "Coyote Ladri",
  desc = "Hai passato molti giorni nelle Badlands, $C? Ne hai sentito il caldo? Hai affrontato le bestie che si aggirano per le sue pianure polverose? È ora di farlo.$B$BI Crag coyotes sono una razza resistente. Resistenti, e così audaci da infilarsi a Kargath per rubare il cibo dalle nostre scorte. Aiuta a liberare l'avamposto da questi ladri!$B$BDai la caccia ai crag coyotes, $N. Cacciali e portami le mandibole. Se me ne porti abbastanza, forse ti crederò quando dirai di conoscere le Badlands.",
  obj = "Porta 30 Coyote Jawbones a Neeka Bloodscar, a Kargath.",
  progress = "Ce le hai, le mandibole?",
  reward = "Che bella collezione di mandibole, $N. Quei coyote non verranno più a saccheggiare le nostre scorte in cerca di avanzi.$B$BBen fatto. Quelli delle Badlands non sono prede facili. Con questa impresa mi hai dimostrato che forse riuscirai a sopravvivere qui.",
  en_title = "Coyote Thieves",
  en_obj = "Bring 30 Coyote Jawbones to Neeka Bloodscar in Kargath.",
}
T[1420] = {
  title = "Rapporto a Helgrum",
  desc = "Ho scritto un nuovo rapporto per Helgrum, a Stonard. Portaglielo.$B$BE se ti consideri $Gun messaggero:una messaggera;, non perderti per strada. E non cadere per mano di un nemico.",
  obj = "Porta il Neeka's Report a Helgrum the Swift a Stonard.",
  progress = "Sei $Gtornato:tornata;. Porti un rapporto?",
  reward = "Grazie, $N. Dal Neeka's report vedo che anche l'Alleanza ha i suoi problemi, e potremmo scoprire di avere qualche nemico in comune.",
  en_title = "Report to Helgrum",
  en_obj = "Bring Neeka's Report to Helgrum the Swift in Stonard.",
}
T[1421] = {
  title = "La Carovana Perduta",
  desc = "Quando i Lost Ones ci hanno attaccati sono rimasto stordito, ma prima che si facesse tutto buio ho visto trascinare uno dei nostri carri verso il Fallow Sanctuary, il villaggio dei perduti a nord.$B$BSu quel carro c'era un forziere della carovana con dentro dei reagenti preziosi, indispensabili agli studi dei maghi di Nethergarde Keep. Trova il forziere e recupera quei reagenti, $N. Prendili e portameli.",
  obj = "Trova il Caravan Chest nel Fallow Sanctuary, prendi i Wizards' Reagents e portali a Watcher Biggs.",
  progress = "Hai i reagenti dei maghi, $N?",
  reward = "Ah, li hai trovati! Con questi i maghi di Nethergarde potranno andare avanti col loro lavoro. Cosa facciano non lo so, ma riguarda il Dark Portal nelle Blasted Lands, ed è fondamentale per la sicurezza dell'Alleanza.",
  en_title = "The Lost Caravan",
  en_obj = "Find the Caravan Chest in the Fallow Sanctuary, obtain the Wizards' Reagents and bring to Watcher Biggs.",
}
T[1422] = {
  title = "Minaccia dal Mare",
  desc = "Intanto che comincio a lavorare alla tua arma, perché non vai a parlare con Katar? Mi ha detto che gli serve aiuto per pattugliare la spiaggia, e preferirei vederti con la mente lucida e le armi pronte che $Gubriaco:ubriaca; in compagnia di qualche altro buono a nulla con cui divido questo accampamento.",
  obj = "Parla con Katar in Swamp of Sorrows.",
  reward = "Fa' silenzio un momento, $C. Nonostante il cupo fragore del mare, quei disgustosi gorgoglii degli uomini pesce si sentono ancora.",
  en_title = "Threat From the Sea",
  en_obj = "Speak to Katar in the Swamp of Sorrows.",
}
T[1423] = {
  title = "I Lost Supplies",
  desc = "Questo barile è piccolo ma robusto, con le giunture sigillate da una cera gialla e pungente. Sul fondo si leggono, impresse, le parole:$B$BQUARTERMASTER LUNGERTZ$B$BROCCA DI NETHERGARDE",
  obj = "Porta i Lost Supplies a Quartermaster Lungertz.",
  progress = "Hai qualcosa per me?",
  reward = "Ah, grazie, $N! Fra Darkshire e qui se ne perdono tanti, di rifornimenti. Fa piacere vedere che alcuni vengono recuperati.",
  en_title = "The Lost Supplies",
  en_obj = "Bring the Lost Supplies to Quartermaster Lungertz.",
}
T[1424] = {
  title = "Pool of Tears",
  desc = "Il Capoguerra ci ha mandati a indagare su certi strani avvenimenti a The Temple of Atal'Hakkar.$B$BI troll Atal'ai sono una tribù di dark casters, famosi per la magia proibita che praticano. Immagina il nostro stupore quando, una volta arrivati, abbiamo scoperto che il tempio era stato sommerso.$B$BAdesso a sorvegliare il luogo ci sono i draghi verdi, che dicono di essere i protettori di Azeroth.$B$BDobbiamo capire cosa è successo. Esplora i dintorni del Pool of Tears e raccogli i manufatti degli Atal'ai: con quelli potrò cominciare a mettere insieme i pezzi del rompicapo.",
  obj = "Fel'zerul a Stonard vuole che tu raccolga 10 Atal'ai Artifacts.",
  progress = "Nessuno sa quali pratiche oscure si compissero dentro The Temple of Atal'Hakkar, ma sappiamo che lì sono state usate forze magiche grandi e potenti.$B$BSu una magia del genere dobbiamo imparare tutto quello che possiamo. Forse gli incantesimi degli Atal'ai torneranno utili all'Orda.$B$BQuando avrai raccolto abbastanza manufatti degli Atal'ai nei dintorni del Pool of Tears, potrò cominciare a capire cosa sperassero di ottenere i troll e cosa sia andato così terribilmente storto.",
  reward = "Hai raccolto i manufatti degli Atal'ai con un impegno che merita lode, $C.",
  en_title = "Pool of Tears",
  en_obj = "Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts.",
}
T[1425] = {
  title = "Consegna la Prima Spedizione",
  desc = "Mentre riparo questo carro, $N, avrei un ultimo compito per te.$B$BHo impacchettato le provviste più importanti che ho salvato dagli attacchi dei Lost Ones. Portale a Nethergarde Keep. Il forte sorge tra le colline settentrionali delle Blasted Lands e fa da guardia al Dark Portal.$B$BPer arrivare a Nethergard segui la strada verso est. Dove si divide, prendi verso sud, in direzione delle Blasted Lands, poi al bivio successivo gira a sinistra. Resta sulla strada, $N, e stai in guardia.",
  obj = "Porta la Shipment to Nethergarde a Quartermaster Lungertz in Nethergarde Keep.",
  progress = "Mi cercavi?",
  reward = "Cosa? Un pacco dalla carovana di Biggs? Li davamo per perduti, lui e la carovana.$B$BGrazie, $N. Con un po' di fortuna, in queste provviste ci sarà il reagente di cui abbiamo tanto bisogno, i Cristalli Azoran. Le scorte stanno finendo...",
  en_title = "Deliver the Shipment",
  en_obj = "Bring the Shipment to Nethergarde to Quartermaster Lungertz in Nethergarde Keep.",
}
T[1426] = {
  title = "Minaccia dal Mare",
  desc = "Non ho alcun amore per il mare, né per le creature che ho visto uscire dai suoi abissi. È una padrona potente ma cieca; spietata e brutale. Se fosse in mio potere, mi piacerebbe molto uccidere gli uomini pesce a centinaia. Ma mi dà un certo piacere guardarli morire per mano di chiunque compia la volontà dell'Orda.$B$BEd è qui che entri in gioco tu, $C. Quanti ne riesci a uccidere? Ti metteresti alla prova contro i più potenti della loro specie?",
  obj = "Uccidi 10 Marsh Murlocs, 10 Marsh Inkspewer e 10 Marsh Flesheater, poi torna da Katar in Swamp of Sorrows.",
  progress = "Sono paziente. Paziente ed eterno come una vecchia pietra kank di Draenor. Gli uomini pesce non passeranno i nostri confini — non finché resto in piedi. Con un esercito, purificherei dalla loro presenza questo mondo e tutti gli altri. Solo a parlarne sento ribollire l'odio.",
  reward = "Il mare sembra vasto e implacabile, ma tu l'hai macchiato col sangue dei suoi stessi figli. Gli uomini pesce conoscono il dolore. Dopo la devastazione che hai portato, la loro stupidità li costringerà a rinforzare i ranghi, ed è un bene.$B$BChe le loro grida gorgoglianti coprano il fragore del mare fino a notte fonda. Ogni volta che ne sentirò tacere uno, sorriderò.$B$BSe vuoi uccidere altri uomini pesce, torna da me. Ti ricompenserò di nuovo volentieri.",
  en_title = "Threat From the Sea",
  en_obj = "Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows.",
}
T[1427] = {
  title = "Minaccia dal Mare",
  desc = "Prima di riposarti, torna a parlare con Tok'Kar. Credo che mentre eri via abbia finito alcune armi, e vorrebbe offrirtene una per l'aiuto che ci hai dato. Quando sarai $Gpronto:pronta;, faresti bene a provarne la forza contro gli uomini pesce... ma solo per farmi ancora più piacere.",
  obj = "Parla con Tok'Kar in Swamp of Sorrows.",
  reward = "Ah, $N, sei $Gtornato:tornata;. Bene. Ho finito di fabbricare altre armi per la nostra lotta contro i murlocs. Per la carne fresca di sawtooth che ci hai portato, e per aver strappato un piccolo sorriso a Katar, te ne offro una.",
  en_title = "Threat From the Sea",
  en_obj = "Speak with Tok'Kar in the Swamp of Sorrows.",
}
T[1428] = {
  title = "Una Minaccia Continua",
  desc = "Vedo con piacere che l'odio per gli uomini-pesce cresce in te come in me.$B$BTrovane altri lungo la spiaggia e torna da me quando sarai $Gsazio:sazia; di combattere. Allora parleremo di come ricompensarti per l'impegno.",
  obj = "Uccidi 10 Marsh Inkspewers, 10 Marsh Flesheaters e 10 Marsh Oracles, poi torna da Katar in Swamp of Sorrows.",
  progress = "Non sarò soddisfatto finché il mare e tutti i suoi figli non saranno messi a tacere... soprattutto quei disgustosi uomini-pesce.",
  reward = "Ben fatto, $C. Voglio ancora il loro sangue. Che muoiano tutti, gli uomini-pesce.",
  en_title = "Continued Threat",
  en_obj = "Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows.",
}
T[1429] = {
  title = "L'Atal'ai Exile",
  desc = "Mentre affrontavi i pericoli del Pool of Tears, uno dei miei esploratori è tornato con una pergamena scritta col sangue su carne essiccata. Ha tutta l'aria di una sentenza contro un sacerdote della tribù Atal'ai.$B$BFra gli Atal'ai, questo sacerdote è stato condannato a una sorte peggiore della morte.$B$BL'hanno esiliato lontano, a nord, nell'Hinterlands, a vivere con i Witherbark trolls.$B$BIo metterò insieme questi manufatti, e tu dovrai cercare l'esiliato e scoprire a cosa servono davvero. Quando avrai concluso il viaggio, torna da me.",
  obj = "Porta il Bundle of Atal'ai Artifacts all'Atal'ai Exile in Hinterlands.",
  progress = "Sei $Gcoraggioso:coraggiosa; a venire qui. $GCoraggioso:Coraggiosa;, o $Gsciocco:sciocca;...",
  reward = "Mi porti i manufatti di evocazione degli Atal'ai?$B$BAllora Jammal'an the Prophet sta guidando i discepoli della Chamber of Blood verso la sorte che hanno scelto, vedo. Che Hakkar sia tornato al Tempio? Il loro destino si è compiuto?",
  en_title = "The Atal'ai Exile",
  en_obj = "Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands.",
}
T[1430] = {
  title = "Carne Fresca",
  desc = "La crawler meat è succulenta e i miei clienti la chiedono molto, soprattutto quella dei monstrous crawlers.$B$BSe pensi di andare verso la costa, non mi sarebbe difficile fare in modo che ti convenga riportarmi un po' delle loro chele, da spedire a Orgrimmar.$B$BLa costa è a est di qui, e quelle creature che zampettano lungo le spiagge e sotto il mare non dovresti faticare a trovarle.",
  obj = "Porta 10 Monstrous Crawler Legs a Dar in Swamp of Sorrows.",
  progress = "Ho una botte di vino pronta per quando ce l'avrai fatta, $N. È giusto assaggiare la merce prima di spedirla ai miei clienti.",
  reward = "Ah, queste dovrebbero andare benissimo. Non vedo l'ora di assaggiarle, cotte come si deve sulla fiamma viva. Dovresti portartene un po' per il viaggio. Sono davvero una delizia.",
  en_title = "Fresh Meat",
  en_obj = "Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows.",
}
T[1431] = {
  title = "Rapporti con l'Alleanza",
  desc = "Resta $Gcalmo:calma;, $C, e lascia che ti riveli una cosa importante per il nostro popolo, anche se tutt'altro che ovvia.$B$BSiamo una razza orgogliosa, e la guerra con gli umani ha messo alla prova perfino la grande pazienza di Thrall. Vedi, il nostro Capoguerra è saggio e prudente, e per lui il suo popolo viene ancora prima di tutto. In fondo è un diplomatico, e nel tempo passato fra gli umani ha imparato molto delle loro usanze.$B$BSe la storia che ho cominciato ti incuriosisce, cerca Keldran vicino all'uscita occidentale della città. È lì che ha la sua catapecchia.",
  obj = "Parla con Keldran a Orgrimmar.",
  reward = "Putanni, nobile $C. Sono Keldran, studioso di magia... e di altre arti mistiche.$B$BPer la faccenda per cui Craven ti ha mandato da me ci vuole un po' più di finezza di quella che ti è servita finora, ma questo non ti impedisce di aiutare comunque la nostra causa.$B$BTi prego, mettiti $Gcomodo:comoda;, e ti dirò perché il Capoguerra ha bisogno del mio aiuto... e del tuo.$B$BTutto comincia dalle apparenze, $N. Da come l'Orda vede se stessa. Da come ci vedono i nostri alleati. E soprattutto, da come ci vedono i nostri nemici.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Keldran in Orgrimmar.",
}
T[1432] = {
  title = "Rapporti con l'Alleanza",
  desc = "Ora che l'Alleanza si spinge sempre più a fondo nel Kalimdor, qualcuno potrebbe concludere, sbagliando, che l'Orda stringa patti con la Burning Legion. Il Capoguerra non può permetterlo. E con la sua benedizione, sto provvedendo a farli eliminare.$B$BHo degli agenti nella zona di Desolace, al Ghost Walker Post, a nord del grande Kodo Graveyard. Scendi a sud della Charred Vale, nelle Stonetalon Mountains, e lo troverai. Appena arrivi, cerca Takata Steelblade.",
  obj = "Parla con Takata Steelblade in Desolace.",
  reward = "Salute, $C. Porti notizie da Orgrimmar; bene.$B$BI demoni che infestano questa zona la ammorbano più ancora della puzza di sterco di centauro. Gli uomini-cavallo rivendicano questa terra come loro, ma è chiaro che ci sono forze che non riescono a controllare e che li schiacceranno, se nessuno le tiene a bada.$B$BAiutare i centauri, anche solo indirettamente, non mi fa piacere, ma è per il bene dell'Orda: faccio il mio dovere per il Capoguerra, anche se vuol dire sostenere gli stregoni dell'Orda.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Takata Steelblade in Desolace.",
}
T[1433] = {
  title = "Relazioni di Alleanza",
  desc = "La Burning Blade ha molti piani, ma sappi che i suoi membri sono malvagi fino al midollo e hanno lo spirito corrotto: per sventare i loro scopi l'unica è distruggerli.$B$BKeldran ha mandato con me Maurin perché lui conosce la Blade e le sue arti da stregoni.$B$BÈ lui a guidare i nostri piani contro la Blade, mentre io mi occupo delle altre minacce demoniache qui a Desolace.$B$BVa' a parlargli: ti guiderà lui in quello che ha in mente.",
  obj = "Parla con Maurin Bonesplitter a Desolace.",
  reward = "Ah, sì. L'aiuto di chi è fedele al Capoguerra è sempre ben accetto.$B$BMi chiamo Maurin. Sono qui perché me l'hanno chiesto Keldran e quel cucciolo di Capoguerra, Thrall, e voglio aiutare il giovane capo contro i mali che minacciano il suo governo.$B$BVieni più vicino, $C, e ti spiego il mio piano per eliminare quel bubbone purulento che è la Burning Blade.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Maurin Bonesplitter in Desolace.",
}
T[1434] = {
  title = "Contaminati dai Satiri",
  desc = "Un'infestazione demoniaca non nasce da sola — c'è sempre qualcos'altro che lascia mettere radici al male.$B$BTutto può cominciare da uno spirito indebolito, da un inutile desiderio di potere; o forse dalla sete di vendetta, dalla ricerca di una giustizia definitiva. Quando il dolore ci assale, il male se ne approfitta — un male come i satiri.$B$BSi sono legati alla Burning Blade, e Thrall li vuole morti. Vai a cercarli a nord-est di qui e, quando li avrai respinti, torna da me.",
  obj = "Uccidi 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers e 7 Hatefury Hellcallers, poi torna da Takata Steelblade in Desolace.",
  progress = "Un mio compagno tauren mi ha avvertito che i satiri non sono solo quello che sembrano. Secondo lui in loro c'è qualcosa di più, e la loro malvagità è una distorsione della loro vera natura. Io però non ho mai visto niente del genere.$B$BVedo soltanto il massacro spietato dei deboli e la corruzione di chi cerca un potere oscuro.$B$BContinuerò ad annientarli, com'è mio dovere, finché il Capoguerra non mi ordinerà altrimenti. E fino ad allora, per loro nessuna pietà.",
  reward = "Buon lavoro, $C. Hai dato prova di onore e dedizione.$B$BQuando la nostra campagna a Desolace sarà conclusa, il Capoguerra saprà che ci hai aiutato qui e che hai contribuito a realizzare la sua volontà.$B$BTi ringrazio.",
  en_title = "Befouled by Satyr",
  en_obj = "Slay 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers, and 7 Hatefury Hellcallers, and return to Takata Steelblade in Desolace.",
}
T[1435] = {
  title = "Il Rogo degli Spiriti",
  desc = "A creature spregevoli come quelle, che voltano le spalle al loro signore per motivi tanto egoisti, la morte è quanto di meglio si possa augurare. Ma con chi si è consegnato all'oscurità, la morte non basta.$B$BPrendi questa gemma e attivane la magia quando uno della Burning Blade sta per morire: l'incantesimo strapperà alla vittima lo spirito corrotto, lasciando una gemma infusa.$B$BLe gemme infuse portale a me, così potrò liberarmene come si deve.$B$BOra va', e che la morte non ti prenda.",
  obj = "Riporta la Burning Gem e 15 Infused Burning Gems a Maurin Bonesplitter, a Desolace.",
  progress = "Ho fatto il possibile per rendere la magia semplice: strappare lo spirito della tua vittima dal corpo ferito dovrebbe essere un gioco da ragazzi. Però non contare sul potere della gemma per finire il nemico: devi attivarla solo quando sta per morire, altrimenti non servirà a niente.",
  reward = "Ah, sei $Gtornato:tornata;, e ce l'hai fatta. Bene. Dammi le gemme: le metterò al sicuro....$B$BDa parte mia non ho più niente da chiederti, $C. Quando ti sarai $Griposato:riposata;, va' a parlare con Takata: forse avrà altri incarichi per te, o magari ti chiederà di tornare a Orgrimmar a riferire a Keldran i nostri progressi qui a Desolace.",
  en_title = "The Burning of Spirits",
  en_obj = "Return the Burning Gem and 15 Infused Burning Gems to Maurin Bonesplitter in Desolace.",
}
T[1436] = {
  title = "Rapporti con l'Alleanza",
  desc = "La battaglia va bene, $N. Se continueremo a fare passi così grandi nella lotta contro i demoni e i loro servi, forse il Capoguerra ci lascerà tornare a casa prima che cambi la stagione.$B$BTorna da Keldran e raccontagli cosa abbiamo fatto. Di sicuro ti ricompenserà per i tuoi sforzi qui. Ci tiene molto alla sua causa, e sarà orgoglioso di sapere che il Capoguerra dà peso alle sue preoccupazioni.",
  obj = "Parla con Keldran a Orgrimmar.",
  reward = "$N, da Desolace sei $Gtornato:tornata; con un successo più che pieno. Grazie.$B$BGrazie dei tuoi sforzi, del tempo che mi hai dato e di aver capito la mia richiesta. Thrall capisce e vuole la pace fra l'Orda e l'Alleanza, e se avremo cura che il nostro aspetto sia accettabile, non provocheremo altre minacce di violenza inutile.$B$BTi devo molto.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Keldran in Orgrimmar.",
}
T[1437] = {
  title = "La Ricerca di Vahlarriel",
  desc = "Sono Vahlarriel, $N. Sono venuto qui per scoprire dove sono finiti due nobili scomparsi di una famiglia di mercanti Darnassian — la Casata Malem. Il padre della casata teme il peggio, e io devo fare tutto quello che posso per ritrovare i suoi figli. Non ho ancora cominciato a cercare Tyranis o Dalinda, ma spero di non dovermi fermare qui a lungo.$B$BSecondo le ultime notizie, qualche settimana fa sono passati per le Stonetalon Mountains.$B$BSe trovi il loro carro, ti prego, vieni subito da me.",
  obj = "Trova e ispeziona il carro di Tyranis e Dalinda Malem a Desolace.",
  reward = "Mentre frughi fra i resti del carro, diventa evidente che l'hanno attaccato con incantesimi e con armi. Pare che la battaglia sia stata rapida e a senso unico: non c'è traccia di sangue, né resti di corpi.$B$BChi ha attaccato il carro è stato rapido ed efficiente.",
  en_title = "Vahlarriel's Search",
  en_obj = "Find and search Tyranis and Dalinda Malem's wagon in Desolace.",
}
T[1438] = {
  title = "La Ricerca di Vahlarriel",
  desc = "Se puoi, trova Dalinda e Tyranis e torna a riferirmi quello che hai scoperto. Comincia a cercarli da questa fortezza. Io contatterò subito i miei superiori a Darnassus per informarli della situazione.$B$B$N, voglio che un'altra cosa ti sia ben chiara. I miei superiori hanno mostrato una certa preoccupazione per Tyranis e per i motivi che l'hanno spinto fin qui. Per loro conta di più che Dalinda sia ritrovata e riportata indietro sana e salva. Tyranis, prima di essere ricondotto a casa, dovrà essere... valutato.",
  obj = "Trova Dalinda Malem a Desolace.",
  reward = "Grazie a Elune, finalmente è arrivato qualcuno ad aiutarmi. Ti prego, $C, ho bisogno di te. La Burning Blade ha catturato me e mio fratello Tyranis e ci ha portati qui. Credo che vogliano sacrificarmi ai loro padroni demoni!$B$BLo sapevo che venire a Desolace era un errore, ma di recente Tyranis si è messo a bramare la conoscenza di ogni cosa arcana — persino contro la volontà del nostro popolo. Ha deciso di partire anche dopo aver sentito i racconti sui demoni che infestano questa terra.$B$BTemo il peggio per lui.",
  en_title = "Vahlarriel's Search",
  en_obj = "Find Dalinda Malem in Desolace.",
}
T[1439] = {
  title = "Alla Ricerca di Tyranis",
  desc = "Dopo aver massacrato tutte le nostre guardie e i nostri servitori, gli orchi ci hanno portati qui. Oh, che cose terribili gli hanno fatto! Ero sicura che ci avrebbero uccisi lì, su due piedi, ma poi è stato chiaro che avevano in mente altro.$B$BTyranis ha provato a parlare con loro. Credo volesse impressionarli con la sua conoscenza dell'arcano... non saprei dire perché.$B$BTi prego, non posso lasciare questo posto prima di sapere cosa è successo a mio fratello. Trovalo, e quando sapremo che fine ha fatto torna a prendermi.",
  obj = "Trova Tyranis Malem a Desolace.",
  progress = "Temo che Tyranis cercherà di apprendere i segreti della Burning Blade e di diventare uno di loro, se glielo lasceranno fare — ha sempre adorato il potere che la magia concede a chi se ne lascia sedurre.$B$BNon so se avrei la forza di tornare a casa dalla mia famiglia a dire che lo spirito di Tyranis flirta con simili pericoli. Per la mia gente andare in cerca di cose del genere è già un crimine terribile, ma diventare proprio ciò da cui cerchiamo di proteggerci, be', è riprovevole.",
  reward = "È terribile! Ma immagino che fosse necessario. Se non l'avessi fatto tu, l'avrebbe fatto di certo la mia gente. Forse dovrei ringraziarti — perdonami se non ti sembro sincera. Non voglio offenderti.$B$BAdesso che so che fine ha fatto mio fratello, pare sia arrivato il momento di scappare. Se sei ancora $Gdisposto:disposta;, accetterò il tuo aiuto per fuggire da questo posto orribile.$B$BQuando sei $Gpronto:pronta;, ci mettiamo in salvo.",
  en_title = "Search for Tyranis",
  en_obj = "Find Tyranis Malem in Desolace.",
}
T[1440] = {
  title = "Ritorno da Vahlarriel",
  desc = "Dunque è giunto il momento? Apprezzo il tuo impegno, e nel caso più tardi non ce ne fosse l'occasione, lascia che ti ringrazi adesso per tutto ciò che hai fatto per me e per la mia famiglia. Se sei $Gpronto:pronta;, qui non mi resta più nulla — partiremo quando lo riterrai opportuno.",
  obj = "Scorta Dalinda Malem fuori da Thunder Axe Fortress, poi torna da Vahlarriel Demonslayer in Desolace.",
  reward = "Grazie, $N. Dalinda è tornata sana e salva qui a Nijel's Point, e sta molto meglio di quanto osassi sperare. Che sia arrivata con le sue forze è stato un buon segno. E tu stai bene, spero?$B$BMi addolora che non siano tornate entrambe, Tyranis e Dalinda, ma la vergogna delle sue decisioni deve sopportarla Tyranis. Ci farà i conti al suo ritorno a Darnassus.",
  en_title = "Return to Vahlarriel",
  en_obj = "Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.",
}
T[1442] = {
  title = "Alla Ricerca della Gemma Kor",
  desc = "Saluti, $N. Cosa posso fare per chi segue un sentiero sacro?$B$BAh, sì, Stilwell, il fabbro... di tanto tempo fa. Me lo ricordo bene, anche se è da un po' che non lo sento nominare.$B$BNon mi è mai sembrato un uomo sfrontato, quindi se vuole una gemma Kor sarà per uno scopo nobile.$B$BSe vuoi davvero una di quelle gemme, devi spingerti nella parte nord-occidentale di Ashenvale. Lì, fra antiche rovine, troverai le Blackfathom Deeps. Laggiù ci sono i naga che usano ancora le gemme. Non andarci da $Gsolo:sola;, $C.",
  obj = "Porta una Gemma Kor a Thundris Windweaver a Darkshore.",
  progress = "Se a chiedermi una gemma Kor venisse qualcuno che non segue un sentiero sacro, mi fiderei di meno. Ma di quelli come te mi fido più che di certi miei simili. Non giudico tutto il tuo ordine da ciò che ha fatto un solo membro caduto.",
  reward = "È proprio la gemma che cerca Stilwell, ma prima di lasciartela portare devo purificarla dalla corruzione — è vero che quelle megere naga infondono potere nelle gemme, ma è un potere malvagio, il loro.$B$BFa' sapere a Stilwell che il potere della gemma è intatto e che dovrebbe funzionare bene per qualunque rituale in cui voglia usarla.$B$BSpero che tu sappia cosa stai facendo, $C, perché quello che hai fra le mani non è un oggetto qualunque.",
}
T[1444] = {
  title = "Torna da Fel'Zerul",
  desc = "È stato Jammal'an the Prophet a condannarmi all'esilio da The Temple of Atal'Hakkar. Un tempo vedevo nel sommo sacerdote una guida degna.$B$BLa sua fede incrollabile nella profezia porterà gli Atal'ai alla distruzione. Sempre che non sia già successo.$B$BQuando ho espresso i miei dubbi, mi hanno bollato come infedele e cacciato dal tempio.$B$BI manufatti che mi hai portato sono innocui. Ma se Jammal'an ha trovato il modo giusto di incantare i feticci per il rituale di evocazione, il mondo è in grave pericolo....",
  obj = "Torna da Fel'Zerul a Stonard.",
  reward = "Ne è passato di tempo dall'ultima volta che abbiamo parlato, $C. Spero che il viaggio sia andato a buon fine.$B$BCosa hai saputo dall'esiliato Atal'ai nell'Hinterlands?",
}
T[1445] = {
  title = "The Temple of Atal'Hakkar",
  desc = "Quindi ti ha parlato della profezia di Jammal'an?$B$BLa guida spirituale degli Atal'ai crede che, quando Hakkar sarà tornato su Azeroth dal Nether, il dio concederà l'immortalità alla tribù Atal'ai.$B$BPer me è uno sciocco inganno, che porterà la fine del mondo prima del tempo.$B$BMa l'esiliato ha parlato di feticci incantati, dici? Questo mi preoccupa molto. Se sono davvero la chiave del rituale Atal'ai che ha provocato questo pasticcio, dobbiamo capire quali poteri hanno in sé.$B$BAddentrati nel Tempio e impadronisciti dei feticci!",
  obj = "Raccogli 20 Fetishes of Hakkar e portali a Fel'Zerul a Stonard.",
  progress = "Se i feticci degli Atal'ai hanno il potere di evocare Hakkar e far avverare la profezia di Jammal'an, dobbiamo impadronircene. L'Orda deve comprendere poteri del genere!",
  reward = "Hai dimostrato di essere $Gun grande campione:una grande campionessa; dell'Orda, $Gcoraggioso:coraggiosa; $C.$B$BOra bisogna occuparsi subito di tutti questi feticci di Hakkar che hai raccolto!",
}
T[1446] = {
  title = "Jammal'an the Prophet",
  desc = "I miei compagni Witherbark non vedono di buon occhio gli stranieri vicino a casa loro.$B$BIo? Una casa non ce l'ho più. Il mio popolo, la grande tribù Atal'ai della Swamp of Sorrows, mi ha esiliato.$B$BJammal'an, il nostro capo spirituale, ha avuto quella che lui ha chiamato una profezia. È convinto che evocare il dio Hakkar porterà l'immortalità agli Atal'ai.$B$BMa io ho invitato alla prudenza. E se la profezia non fosse altro che una manipolazione?$B$BVoglio vendicarmi dell'esilio. Portami la testa di Jammal'an. Forse allora il mio popolo sarà libero.",
  obj = "L'Atal'ai Exile in The Hinterlands vuole l'Head of Jammal'an.",
  progress = "Quando Jammal'an sarà eliminato, avrò una possibilità di tornare dal mio popolo.$B$BCon Jammal'an come capo spirituale, per gli Atal'ai la distruzione è certa.",
  reward = "Jammal'an si è fidato in modo sconsiderato di false visioni, e ha condotto il mio popolo alla rovina eterna.$B$BTi ringrazio, $C, di aver vendicato il mio esilio. Piango il mio popolo. Non ho una casa a cui tornare.",
}
T[1447] = {
  title = "Il Diplomatico Scomparso",
  desc = " Già, non sei certo $Gil:la; $C più $Gsveglio:sveglia; mai $Gentrato:entrata; a Stormwind, ma stai per diventare $Guno dei più stupidi:una delle più stupide; a non uscirne mai più.$B$BHai conosciuto i miei amici?",
  obj = "Sconfiggi Dashel Stonefist a Stormwind.",
  progress = "Quella battuta sul fatto che sei $Gun:una; $C $Gstupido:stupida; non la pensavo davvero. Siamo amici, no? Senza rancore?",
  reward = "Allora, se sei $Gvenuto:venuta; da me ci sarà un motivo. Di cosa hai bisogno?",
  en_title = "The Missing Diplomat",
  en_obj = "Defeat Dashel Stonefist in Stormwind.",
}
T[1448] = {
  title = "Alla Ricerca del Tempio",
  desc = "C'è stato un tempo in cui ero giovane e pieno di vigore come te, $C.$B$BOra però sono vecchio e non posso più girare il mondo come una volta. Ah, quante cose ho visto!$B$BC'è un mistero, però, che mi è sempre sfuggito. Nella mia ultima missione l'Explorers' League mi ha mandato a cercare The Temple of Atal'Hakkar, che si diceva si trovasse nella Swamp of Sorrows.$B$BEro malandato, così l'ho cercato in volo per i cieli, in groppa a un grifone, ma non l'ho mai trovato.$B$BDaresti una mano a un vecchio nano? Magari a piedi avrai più fortuna.",
  obj = "Brohann Caskbelly a Stormwind vuole che tu cerchi il Temple of Atal'Hakkar.",
  progress = "Ho girato il mondo, dalle giungle di Azeroth alle cime innevate di Khaz Modan.$B$BIn tutte le mie avventure non avevo mai chiesto aiuto a nessuno. Ma ormai queste vecchie ossa sono stanche.$B$BNiente mi darebbe più soddisfazione che sapere di aver portato a termine la mia ultima missione per l'Explorers' League.$B$BSe fossi così gentile da aiutarmi a cercare il Temple of Atal'Hakkar, $C, te ne sarei davvero grato.$B$BVai a perlustrare la Swamp of Sorrows e torna a dirmi cosa hai scoperto!",
  reward = "The Temple of Atal'Hakkar è sprofondato sotto il Pool of Tears? E tutt'intorno c'è lo stormo dei draghi verdi?$B$BChe scoperta incredibile, $C. Però è chiaro che qualcosa è andato terribilmente storto.",
  en_title = "In Search of The Temple",
  en_obj = "Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar.",
}
T[1449] = {
  title = "Verso The Hinterlands",
  desc = "Come ti ho già detto, ho provato a perlustrare il tempio dall'alto per conto mio. Beh, non ero proprio da solo.$B$BSono andato alla famosa voliera dei grifoni di Aerie Peak, in The Hinterlands, e lì mi sono fatto aiutare da uno dei loro piloti migliori. Solo che il pilota è caduto dalla cavalcatura, giù nella palude...$B$BCon gli anni il nome di quel poveretto mi sfugge, ma il maestro della voliera se lo ricorderà di sicuro.$B$BVai là e cerca Falstad Wildhammer.$B$BDobbiamo scoprire che fine ha fatto quel pilota.",
  obj = "Parla con High Thane Falstad Wildhammer ad Aerie Peak, in Hinterlands.",
  reward = "Che vuoi, $Ggiovanotto:signorina;? Non vedi che qui ho dei problemi da risolvere? Chi ce l'ha il tempo di starsene lì a blaterare con $Gun:una; $R $Gchiacchierone:chiacchierona;?$B$BSpuntano troll da ogni buco! E vedi di sbrigarti.",
  en_title = "To The Hinterlands",
  en_obj = "Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands.",
}
T[1450] = {
  title = "Gryphon Master Talonaxe",
  desc = "Quindi sei solo $Gun:una; $Gfattorino:fattorina; di lusso al servizio di qualche vecchio bacucco dell'Explorers' League, eh?$B$BBeh, sentimi bene, $C. Non ho idea di con chi volasse il tuo vecchio amico laggiù ad Azeroth. Ti sembro forse Gryphon Master Talonaxe? Eh?$B$BSe ti interessano tanto i turni di volo, perché non vai a chiederlo al maestro dei grifoni? Se ti becco a bighellonare qui ancora a lungo, ti metto a fare un lavoro vero.$B$BOra datti una mossa.",
  obj = "Parla con Gryphon Master Talonaxe dentro Aerie Peak Aviary.",
  reward = "Ah, sì. Certo che mi ricordo di aver mandato uno dei miei cavalieri di grifoni ad aiutare Brohann Caskbelly.$B$BL'Explorers' League ha sempre avuto un posto speciale nel mio cuore. Anzi, mio padre ha dato una mano alla prima squadra di scavo che ha scoperto Uldaman.$B$BCon Brohann ho mandato quello che allora credevo il mio miglior cavaliere di grifoni, un tipo di nome Rhapsody Shindigger.$B$BE che fantino era, sui grifoni! Beh, finché...",
}
T[1451] = {
  title = "Rhapsody Shindigger",
  desc = "A Rhapsody l'alcol piaceva parecchio. Non fraintendermi — quassù alla voliera a tutti noi nani piace una buona birra al momento giusto.$B$BMa il vecchio Shindigger si è buttato sul liquore come un grifone si butta nel cielo. Ed è stato un dannato peccato, perché nessuno sapeva volare come Rhapsody.$B$BIl primo campanello d'allarme è stato quando è tornato barcollando da quella missione con il tuo amico Brohann. Da lì è andato tutto a rotoli in fretta, e ho dovuto mandarlo via.$B$BPer quel che ne so, ha piantato un accampamento a est di qui per farsi la birra...",
  obj = "Cerca Rhapsody Shindigger in The Hinterlands.",
  reward = "Hic!$B$BTi sto guardando dritto in faccia, ma tu non la smetti di andare su e giù. Mi fai girare la testa. Ohoh!$B$BHic!$B$BEhi! Hai sentito? La terra trema, $Gamico mio:amica mia;. Ci vuole un goccio.$B$BHic!",
}
T[1452] = {
  title = "Il Kocktail Kalimdor di Rhapsody",
  desc = "Hic!$B$BAllora ti ha mandato quel pazzo di Brohann? Perbacco, che avventura che abbiamo passato... Hic!$B$BSe vuoi sapere cos'è successo laggiù nella palude, mi serve qualcosa di forte da bere. Non è stato un bello spettacolo, sai. Hic!$B$BFacciamo così... tu mi porti quello che serve per un Kocktail Kalimdor e io ti racconto tutto.$B$BMi ci vorranno dei Roc gizzards da Tanaris... e poi vediamo... dei fegati di Groddoc e di Ironfur da Feralas...$B$BUn Kocktail Kalimdor bello forte... quello sì che mi scioglierà la lingua!",
  obj = "Rhapsody Shindigger in The Hinterlands vuole che tu gli porti 3 Roc Gizzards, 3 Groddoc Livers e 3 Ironfur Livers.",
  progress = "Hai mai assaggiato una Rhapsody Malt? Una delle mie migliori, modestamente. Hic!$B$BMa se devo rivivere gli orrori di quel fatidico volo sopra... hic... la palude, beh, mi ci vuole qualcosa di un tantino più forte. Hic!$B$BNon è che per caso mi hai trovato quegli stomaci e quei fegati che mi servono per dare una botta in più al mio Kocktail Kalimdor?$B$BHic!",
  reward = "Vedo che non hai avuto nessun problema a procurarmi la roba! Dev'essere stato un bel viaggio, laggiù nella lontana Kalimdor.$B$BUn attimo e tiro fuori da questi stomaci e fegati quello che serve. Hic!$B$BPoi mi distillo qualcosa di bello tosto e finalmente ti dico quello che vuoi sapere.$B$BHic!$B$BSolo a pensare a quella vecchia palude mi vengono i brividi.$B$BHic!$B$BFammi preparare un goccio, alla svelta.",
}
T[1453] = {
  title = "Affari dei Reclaimers a Desolace",
  desc = "A Desolace c'è da lavorare, $N. È un posto orribile, insozzato dai centauri e da altre brutte bestie, ma se cerchi una buona settimana di lavoro onesto vai laggiù, trova Kreldig Ungor e digli che ti mando io.$B$BSe ne sta rintanato a Nijel's Point — un piccolo accampamento accogliente, nascosto fra le montagne nel nord di Desolace. Arrivando dalle Stonetalon Mountains, basta andare verso est. È facile passarci accanto senza vederlo, quindi stai $Gattento:attenta;.",
  obj = "Parla con Kreldig Ungor a Desolace.",
  reward = "Fa piacere vedere che ai Reclaimers non mancano né il lavoro né gli avventurieri pronti a dare una mano.$B$BIo sono Kreldig, $N. Sei $Gstato furbo:stata furba; ad aiutare i Reclaimers. Di questi tempi a tutti serve qualcosa: c'è chi ha perso un cimelio di famiglia, chi un oggetto magico, chi una persona cara. Non si sa mai. Ma finché in giro ci sono i Reclaimers, al giusto prezzo chiunque può ritrovare quello che ha perso.",
  en_title = "Reclaimers' Business in Desolace",
  en_obj = "Speak to Kreldig Ungor in Desolace.",
}
T[1454] = {
  title = "Il Naufragio di Karnitol",
  desc = "Il mio primo incarico è per il mago Karnitol — una specie di nobile di Stormwind. Pare che i giganti del mare gli abbiano attaccato la nave al largo della costa nord-occidentale di Desolace. Lui e i servitori hanno provato a portare a riva una delle sue casse più preziose, ma quando i giganti hanno attaccato in massa ha deciso di abbandonarla e di teletrasportarsi al sicuro insieme a loro.$B$BVuole che ritroviamo la cassa con il suo contenuto e che gliela riportiamo a Stormwind.",
  obj = "Trova il Karnitol's Chest a Desolace.",
  reward = "Noti che l'acqua non sembra aver rovinato la cassa.$B$BPoi ti accorgi che il coperchio è stato forzato e che qualunque trappola magica la proteggesse è scattata da tempo — lo dicono i segni di bruciatura lungo i bordi.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Find Karnitol's Chest in Desolace.",
}
T[1455] = {
  title = "Il Naufragio di Karnitol",
  desc = "Ti fermi qualche istante per capire cosa abbia forzato la cassa: sui lati e sul coperchio ci sono graffi lunghi e profondi, e ti dicono che a interessarsene è stato qualcosa che non era né un uomo né un gigante. Non sembrano fatti da un pugnale o da una spada.$B$BFrughi nella cassa e scopri che è completamente vuota.$B$BNon puoi fare altro: chiudi la cassa e ti prepari ad andartene. Kreldig sarà deluso.",
  obj = "Torna da Kreldig Ungor a Desolace.",
  reward = "$GBentornato:Bentornata; a Nijel's Point, $N. Allora, dimmi, cos'hai trovato?$B$BCosa!? Niente? Temo che con una cassa vuota non ci becchiamo un soldo.$B$BRaccontami meglio di questi segni che hai visto... questi squarci.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Return to Kreldig Ungor in Desolace.",
}
T[1456] = {
  title = "Il Naufragio di Karnitol",
  desc = "Interessante.$B$BBe', forse non è ancora tutto perduto.$B$BPiù a nord lungo la stessa costa, vicino alla Ranazjar Isle, in fondo all'oceano ci sono delle rovine degli elfi della notte. Ci si è stabilita una tribù di naga, gli Slitherblade. Secondo me è la pista migliore che abbiamo.$B$BSe una squadra di esploratori si è spinta così a sud, dev'essere stata parecchio forte. Se vuoi ritrovare le cose di Karnitol, io partirei dai naga più forti: i cacciatori di maree o le streghe del mare.",
  obj = "Trova la Karnitol's Satchel e portala a Kreldig Ungor a Desolace.",
  progress = "Senza offesa per questo Nijel, chiunque sia, ma quest'accampamento non è il posto più comodo dove abbia mai dormito, se capisci cosa intendo, $N.",
  reward = "Fantastico, $N! Hai trovato le cose di Karnitol!$B$BQuei maledetti naga combinano sempre guai. Credo che passerei la vita in guerra con l'Orda piuttosto che dovermi scontrare con quelli della loro specie. Hai reso un gran servizio ai Reclaimers.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace.",
}
T[1457] = {
  title = "Il Naufragio di Karnitol",
  desc = "Porta le cose di Karnitol a Roetten, a Ironforge, e ti pagherà per il lavoro ben fatto.$B$BAhah, se non stai $Gattento:attenta;, sarà talmente contento di te che ti chiederà di unirti a noi a tempo pieno.$B$BAncora complimenti, $N.$B$BOcchio sulla strada del ritorno, e non metterci troppo — Karnitol non è il più paziente degli uomini, ma è comunque molto generoso.",
  obj = "Porta la Karnitol's Satchel a Roetten Stonehammer a Ironforge.",
  progress = "Gli affari vanno a gonfie vele, $N, e ho poco tempo per le domande. Se ti servono i Reclaimers, sentiamo. Se no, dovrò chiederti di parlare con uno dei miei sottoposti — da queste parti se la cavano piuttosto bene a sbrigare le cose.",
  reward = "Ah, la faccenda di Karnitol a Desolace. Eccellente!$B$BQuindi la cassa è andata distrutta, ma gli oggetti sono tutti qui, eh? Be', lascerò giudicare a lui. Il bello dell'affare che ho messo su è che, se non sono soddisfatti, posso mandarli a quel paese! Contano su di noi per ritrovare la loro roba... non per garantire che sia tutta bella e in buono stato quando la riavranno.$B$BBel lavoro, $N. Vediamo di farti pagare.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Bring Karnitol's Satchel to Roetten Stonehammer in Ironforge.",
}
T[1458] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "Qui fuori, fra le altre cose, devo raccogliere reagenti per Leftwitch, un mago gnomo di Kharanos. Roetten sembra convinto che siano soldi facili, visto che tanto siamo già qui, e se siamo a corto di braccia gli importa poco.$B$BLe prime cose sulla sua lista non dovrebbero essere difficili da trovare, e chi mi dà una mano si mette in tasca un bel gruzzolo.$B$BMi servono corna e artigli dei satiri Hatefury, quelli a est di qui. Portameli e poi passiamo al resto della lista.",
  obj = "Porta 10 Hatefury Claws e 10 Hatefury Horns a Kreldig Ungor in Desolace.",
  progress = "Creature spregevoli, i satiri. Dicono che abbiano qualche legame con gli elfi della notte, ma non sono poi tanto sicuro di crederci.$B$BSecondo me quella fama se la sono fatta per via dell'elfo che li ha portati in guerra qualche anno fa. Da allora il mondo non è più stato lo stesso: molto più pericoloso, e molto più spaventoso.",
  reward = "Bene bene, $N. Se sono di buona qualità non lo so, ma se Leftwitch ne voleva di un tipo particolare, doveva dirlo prima di mandare qui i Reclaimers.$B$BChe ne dici, passiamo alla prossima voce della sua lista?",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring 10 Hatefury Claws, and 10 Hatefury Horns to Kreldig Ungor in Desolace.",
}
T[1459] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "Poi, sulla lista di Leftwitch, c'è... vediamo... mmh. Ah, ecco qua.$B$BAbbastanza semplice, ma lui sulle indicazioni è molto preciso. Gli servono veleno di scorpashi e pelle di kodo, e in piccolo c'è scritto che tutti e due devono venire da creature particolari: il veleno da uno scorpashi qualsiasi, la pelle da un aged kodo, non da quelli morenti o antichi.$B$BMaghi, te lo dico io: certe cose che vogliono... sono proprio strane.",
  obj = "Porta 7 fiale di Scorpashi Venom e 3 Aged Kodo Hides a Kreldig Ungor in Desolace.",
  progress = "Scusa se non ho saputo dirti dove trovare i kodo o gli scorpashi. La zona non la conosco granché, e per esplorarla non ho avuto tempo.",
  reward = "Il tuo aiuto qui è una benedizione, $N. Come minimo mi dimezzi il tempo da passare a Desolace: grazie a te, in un attimo sarò di nuovo a Ironforge a scaldarmi i piedi.$B$BQuando avremo finito con questa lista e sarò tornato a casa, vieni a cercarmi: una birra te la offro di sicuro.$B$BMa intanto, mettiamo insieme il resto dei reagenti.",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring 7 vials of Scorpashi Venom and 3 Aged Kodo Hides to Kreldig Ungor in Desolace.",
}
T[1462] = {
  title = "Earth Sapta",
  obj = "Parla con Seer Ravenfeather per ottenere un'altra Earth Sapta.",
  reward = "Prendila, e ricorda: è sacra.",
  en_title = "Earth Sapta",
  en_obj = "Speak to Seer Ravenfeather for another Earth Sapta.",
}
T[1463] = {
  title = "Earth Sapta",
  obj = "Parla con Canaga Earthcaller per avere un'altra Earth Sapta.",
  reward = "Te ne do una in buona fede. Hai già dimostrato una volta il tuo valore, ma io pensare che d'ora in poi tu dovresti stare più $Gattento:attenta;.",
  en_title = "Earth Sapta",
  en_obj = "Speak to Canaga Earthcaller for another Earth Sapta.",
}
T[1464] = {
  title = "Fire Sapta",
  obj = "Parla con Telf Joolam per avere un'altra Fire Sapta.",
  reward = "Che il fuoco arda nel tuo cuore, $N.$B$BGli elementi ti aspettano.",
  en_title = "Fire Sapta",
  en_obj = "Speak to Telf Joolam for another Fire Sapta.",
}
T[1465] = {
  title = "La Ricerca di Vahlarriel",
  desc = "Continuando a ispezionare il carro, oltre a un pendente trovi delle impronte che si allontanano verso sud. In lontananza vedi del fumo salire da un grande forte. Viene da un fuoco tenuto acceso, non da edifici in fiamme, e l'istinto ti dice che i Malems, se sono ancora vivi, sono stati portati da quella parte.$B$BPensi che Vahlarriel, a Nijel's Point, debba vedere il pendente che hai trovato e sapere dei segni di vita a sud.",
  obj = "Riporta il Malem Pendant a Vahlarriel Demonslayer a Desolace.",
  reward = "Esasperante! Che disastro!$B$BErano stati avvertiti tutti e due che venire qui era pericoloso. E ora sono scomparsi entrambi... o peggio.$B$BHai detto di aver visto delle tracce dirette verso un forte qui vicino? Potrebbe essere la pista migliore che abbiamo.$B$BA sentire la gente del posto, la fortezza è infestata dai membri della Burning Blade — orchi votati alla causa dei demoni. Forse non rappresentano quello in cui crede la maggior parte dell'Orda, ma sono malvagi, e se vieni $Gsorpreso:sorpresa; a spiare ti uccideranno a vista.",
  en_title = "Vahlarriel's Search",
  en_obj = "Return the Malem Pendant to Vahlarriel Demonslayer in Desolace.",
}
T[1466] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "Siamo all'ultima cosa della lista e, a dirla tutta, non è roba piacevole. Immagino anche che ti ci vorrà un po' più di tempo che per le altre.$B$BAllora, basta avvertimenti, cominciamo. Leftwitch dice che gli servono: dieci cervelli di mana eaters, cacciatori di maghi o ley hunters. Dieci nether wings di una nether maiden, sorella o fattucchiera. E... dieci fiale di doomwarder blood di un doomwarder captain, o signore.$B$BAbbastanza semplice, eh? Accidenti... se questa vuoi lasciarla perdere, ti capirei.",
  obj = "Porta 10 Felhound Brains, 10 Nether Wings e 10 fiale di Doomwarder Blood a Kreldig Ungor in Desolace.",
  progress = "Non sapevo nemmeno che a Desolace ci fossero questi esseri demoniaci. Da quel che avevo letto, la regione era più o meno in mano ai centauri da quando, anni fa, gli elfi della notte avevano fatto fagotto ed erano andati via.$B$BChissà perché si sono stabiliti qui, e come.",
  reward = "Sinceramente? Non l'avrei mai detto. Sei $Gfantastico:fantastica;, $N. Affrontare dei demoni per gli esperimenti di un mago, e tornare per giunta $Gtutto:tutta; d'un pezzo. Ottimo lavoro!$B$BQuando sarò di nuovo a Ironforge parlerò di te a Roetten di persona.",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring 10 Felhound Brains, 10 Nether Wings, and 10 vials of Doomwarder Blood to Kreldig Ungor in Desolace.",
}
T[1467] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "Per la paga dovrai tornare a Ironforge e parlare con Roetten in persona. Sarà comunque ben felice di togliersi di torno il pacco di Leftwitch: dagli questo, e dovrebbe bastare per farti avere il tuo bottino.$B$BE non preoccuparti, al mio ritorno una buona parola per te la metterò lo stesso. Non dovrei fermarmi a Desolace ancora per molto.",
  obj = "Riporta il Leftwitch's Package a Roetten Stonehammer a Ironforge.",
  progress = "$GBen trovato:Ben trovata;, $N. Gli affari vanno a gonfie vele: per tutta Ironforge risuona il martellare sulle incudini, i mantici attizzano i fuochi, e mia moglie mi sta preparando una torta da mangiare stasera dopo cena. Si può chiedere di meglio alla vita?",
  reward = "Ah, il pacco da Desolace per Leftwitch. Eccellente. Apprezzo quello che hai fatto, e la tua puntualità, $C. Sono felice di averti con noi, almeno per questo lavoretto.$B$BIl tuo compenso ce l'ho qui. Che si sappia in giro: la Reclaimers Inc. paga sempre bene una dura settimana di lavoro.",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring Leftwitch's Package back to Roetten Stonehammer in Ironforge.",
}
T[1468] = {
  title = "Settimana dei Bambini",
  desc = "Vuoi darci una mano qui all'orfanotrofio? Che tu sia $Gbenedetto:benedetta;, $Gamico:amica;; durante la Settimana dei Bambini il tuo aiuto ci sarà prezioso.$B$BPrendi questo fischietto. Potrai usarlo solo per poco tempo — di solito non oltre la Settimana dei Bambini. Quando lo suoni, puoi parlare con il bambino di cui hai accettato di occuparti; suonalo un'altra volta e lo congederai.$B$BForza, $N — suona il fischietto e vai a incontrare il tuo protetto! Sono sicura che non vede l'ora di conoscerti.",
  obj = "Usa l'Human Orphan Whistle per parlare con il bambino di cui ti occuperai durante la Settimana dei Bambini.",
  reward = "Ehm... ciao. Mi chiamo Randis, e sei tu che ti occupi di me, credo? Sei $Gun avventuriero:un'avventuriera;, come lo erano la mia mamma e il mio papà. Sono contento di conoscerti.$B$BSpero che insieme ci divertiremo un sacco. C'è qualche cosa che vorrei fare, e la matrona dice che per questa settimana sarai come $Gun fratello maggiore:una sorella maggiore; per me. Mi piacerebbe tantissimo, sì $Gsignore:signora;.",
  en_title = "Children's Week",
  en_obj = "Use the Human Orphan Whistle to talk with the child you will be looking after during Children's Week.",
}
T[1469] = {
  title = "Il Racconto di Rhapsody",
  desc = "Prima del volo mi sono scolato un barile intero di birra scura. Hic!$B$BE che volo! Sfrecciavo di qua e di là, con Brohann che mi veniva dietro. Ma del tempio, manco l'ombra. Hic!$B$BBe', manco l'ombra finché non ho alzato un po' troppo il gomito e sono cascato giù dalla cavalcatura. Dritto in acqua, e mi sono sentito risucchiare verso il fondo. Mi sono ritrovato in mezzo a un branco di troll inquietanti, e via a nuoto più svelto che potevo, eccome! E mi sono pure portato via questo souvenir dei troll. Tieni, portalo a Brohann e digli che il suo tempio è proprio laggiù. Hic!",
  obj = "Porta l'Atal'ai Tablet Fragment a Brohann Caskbelly a Stormwind.",
  progress = "Finalmente sei $Gtornato:tornata;, $N. Era un pezzo che non ci parlavamo. Cominciavo a pensare che ti fossi $Gdimenticato:dimenticata; della mia missione.$B$BHai trovato quel furbo cavaliere di grifoni? Aveva qualcosa da dirmi?",
  reward = "Rhapsody Shindigger! Ma certo... come ho fatto a dimenticare un nome così?$B$BE quindi sapeva fin dall'inizio che il tempio era sprofondato? Be', ti avrebbe risparmiato un bel po' di strada, poco ma sicuro.$B$BMa questo manufatto degli Atal'ai! Perbacco, che bella scoperta!",
}
T[1470] = {
  title = "Squarciare il Velo",
  desc = "Saluti, $Gfigliolo:figliola;. Vedo che sei ancora giovane nelle vie del $C e che il potere continua a sfuggirti, ma sento la tua voglia di imparare.$B$BE imparerai.$B$BNell'ignoranza non c'è forza: la conoscenza è il nostro potere più grande. Applicandola possiamo controllare le magie caotiche e gli esseri del vuoto, e piegarli al nostro volere.$B$BTi mostrerò come vincolare a te un servitore, ma prima mi devi portare tre teschi dei rattlecage skeletons vicino alla fucina abbandonata.",
  obj = "Porta a Venya Marthand 3 Rattlecage Skulls.",
  progress = "Per ora il tuo potere è poco, anche se sospetto che tu ne intuisca già le possibilità.$B$BCon quel potere che ci scorre dentro, perfino i morti potrebbero sentirsi vivi.",
  reward = "Non sei ancora $Gstato messo:stata messa; alla prova e sei giovane nel tuo apprendimento, ma hai dimostrato capacità sufficienti per padroneggiare l'evocazione e il vincolo di un imp. Non lasciarti ingannare dalle dimensioni di un imp: non ha forza fisica, ma ha poteri e un'astuzia che ti saranno molto utili.$B$BAscoltami con molta attenzione, $N, perché questa lezione non la ripeterò, e padroneggiarla starà a te.",
  en_title = "Piercing the Veil",
  en_obj = "Bring Venya Marthand 3 Rattlecage Skulls.",
}
T[1471] = {
  title = "Il Vincolo",
  desc = "Avrai certo notato il cerchio di evocazione sotto di noi? Solo lì riuscirai a richiamare un voidwalker libero.$B$BCon queste rune potrai farlo emergere, e poi dovrai sottometterlo con la forza delle armi e della magia.$B$BUna volta domato, sarà vincolato a te. Allora torna da me e ti illustrerò l'incantesimo di evocazione, così la creatura potrà servirti per qualunque scopo tu voglia.",
  obj = "Con le Runes of Summoning evoca e sottometti un voidwalker, poi riporta le Runes of Summoning a Carendin Halgar in Magic Quarter of the Undercity.",
  progress = "Conto di ricevere notizie del tuo successo, $N. Se dovessi fallire, però, deludere le mie aspettative sarà l'ultima delle tue preoccupazioni.",
  reward = "Hai fatto un buon lavoro, $N. Ora ti trasmetterò l'incantesimo per evocare il voidwalker.$B$BIl potere che la creatura ha scatenato contro di te adesso è ai tuoi ordini. Usalo con saggezza.",
  en_title = "The Binding",
  en_obj = "Using the Runes of Summoning, summon and subdue a voidwalker, then return the Runes of Summoning to Carendin Halgar in the Magic Quarter of the Undercity.",
}
T[1472] = {
  title = "Divoratore di Anime",
  desc = "Un sayaad è un divoratore di anime, un dominatore di volontà, un tentatore di cuori: una creatura profondamente malvagia, con la mente votata a un unico scopo.$B$BNelle storie popolari, che raccontano tanto i giusti quanto i malvagi, li si chiama con il loro nome comune: succube le femmine, incubus i maschi.$B$BPer attirare il demone nel nostro mondo serve uno stimolo — i cuori di mortali puri e amorevoli. A quelli il sayaad non saprà resistere, e allora potrai dominarlo e farlo tuo.$B$BParla con Godrick Farsan, il mio assistente, dentro il tempio: ti aiuterà a trovare l'esca.",
  obj = "Parla con Godrick Farsan in Temple of the Damned.",
  reward = "È stato Carendin a mandarti? Allora sei $N.$B$BNon sottovalutarmi solo perché ho perso la vista. Adesso vedo le cose che stanno dietro, e con una chiarezza che non avevo mai conosciuto. Quella che un tempo ritenevo una maledizione, oggi è un dono.",
  en_title = "Devourer of Souls",
  en_obj = "Speak with Godrick Farsan in the Temple of the Damned.",
}
T[1473] = {
  title = "Creatura del Vuoto",
  desc = "Sembra che tutti concordino: sei $Gpronto:pronta; a imparare a evocare un voidwalker.$B$BÈ un essere nato dal caos che sta al di là del nostro mondo: se ne evochi uno ma non riesci a controllarlo, verrai $Gfatto:fatta; a pezzi.$B$BFu Egalin a evocare il primo voidwalker, e nel suo grimorio ne descrisse il procedimento.$B$BPurtroppo ce l'ha rubato un agente della Scarlet Crusade, che lo tiene nascosto nella sua base, in una torre a ovest. Portamelo e ti insegnerò quello che c'è da sapere.",
  obj = "Recupera l'Egalin's Grimoire e portalo a Carendin Halgar in Temple of the Damned.",
  progress = "Egalin è stato il mio maestro. Con appena uno sguardo riusciva a comandare il voidwalker che aveva evocato.$B$BQuando è toccato a me provarci, ho peccato di presunzione. Non prendere alla leggera i poteri che maneggi, $N: possono divorare anche chi sta all'erta.",
  reward = "Ah, eccellente. Con ogni probabilità, Perrine ignorava il vero potere del libro ammuffito che ci aveva rubato.$B$BNon ce lo lasceremo più portare via. Osserva, $N, la struttura dell'incantesimo, il modo in cui devi incanalare il tuo potere.",
  en_title = "Creature of the Void",
  en_obj = "Recover Egalin's Grimoire and bring it to Carendin Halgar in the Temple of the Damned.",
}
T[1474] = {
  title = "Il Vincolo",
  desc = "Usa questi cuori per lanciare un incantesimo sul cerchio di evocazione e aprire un varco da cui far passare la succube. I tuoi poteri ora sono cresciuti, e per sconfiggerla ti serviranno tutti.$B$B$GAttento:Attenta; al suo fascino, $N, ha piegato al suo volere molte menti forti. Quando l'avrai sconfitta tornerà nel vuoto, e io ti insegnerò l'incantesimo per evocarla quando vorrai.",
  obj = "Usando i Pure Hearts, evoca e sottometti una succube, poi riporta i Pure Hearts a Carendin Halgar nel Magic Quarter of the Undercity.",
  progress = "Fra i poteri che arrivano da oltre il vuoto, la succube è uno dei più pericolosi, perché sono i deboli quelli che rigira più facilmente a suo piacimento.$B$BRicordalo, ora e in futuro.",
  reward = "Hai fatto di nuovo un buon lavoro, $N. Era molto tempo che non vedevo $Gun giovane stregone:una giovane stregona; con il tuo potenziale. Stai $Gcerto:certa; che continuerò a seguire i tuoi progressi, a prepararti e ad assisterti nelle prove che verranno.$B$BPer ora lascia che ti mostri l'incantesimo per evocare la succube che hai appena dominato.",
  en_title = "The Binding",
  en_obj = "Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity.",
}
T[1475] = {
  title = "In The Temple of Atal'Hakkar",
  desc = "Secondo la leggenda, The Temple of Atal'Hakkar è un santuario sacro all'antico dio Hakkar the Soulflayer. Lo custodisce una feroce tribù di troll, gli Atal'ai, e si dice che sia inespugnabile.$B$BOra che è sprofondato sotto il Pool of Tears, portarne via dei manufatti è ancora più difficile. Ed è proprio quello che ti chiedo, $N.$B$BAiutami a raccogliere le Atal'ai Tablets intatte. Portamele e tornerò da eroe alla Gilda degli Esploratori. La gloria ce la divideremo insieme.",
  obj = "Raccogli 10 Atal'ai Tablets per Brohann Caskbelly a Stormwind.",
  progress = "Ora che sulla mia carriera scende lentamente il crepuscolo, è a te che mi rivolgo, $N, perché tu mi aiuti nell'ultima missione per l'Explorers' League. Se queste vecchie ossa trovassero la forza di affrontare la Swamp of Sorrows e il tempio sommerso, combatterei al tuo fianco.$B$BChiederti aiuto per raccogliere le Atal'ai Tablets mi pesa, per orgoglio. Ma la vecchiaia mi costringe.$B$BTi prego, aiutami, $N. Voglio ritirarmi dall'Explorers' League dopo averne portato a termine l'ultimo incarico.",
  reward = "Le Atal'ai Tablets! Grazie, $N!$B$BQuando le avrò consegnate all'Explorers' League, i nostri nomi entreranno insieme nella storia. Hai aiutato un vecchio nano a compiere l'ultimo dovere della sua vita, e per questo ti sarò grato in eterno.",
}
T[1476] = {
  title = "Cuori dei Puri",
  desc = "Per attirare una succube ci vogliono i cuori dei puri. Ma esiste un mortale senza vizi?$B$BMettendo insieme frammenti di storie sentite per caso, ho trovato due umani che dovrebbero andare bene.$B$BIl primo è Dalin Forgewright, che si è dedicato ad aiutare i profughi di Lordaeron respinti dalla loro stessa gente al Greymane Wall.$B$BL'altra è Corma Villard, una donna rimasta fedele al suo amore perduto, che vaga per le Wetlands in cerca di un segno di lei.$B$BConsegna i loro cuori a Carendin. Ma prima lascia che ti mostri le tue prede.",
  obj = "Porta i cuori di Dalin Forgewright e di Corma Villard a Carendin Halgar nel Temple of the Damned.",
  progress = "Finora i tuoi progressi sono stati rapidi, $N, e la cosa mi ha sorpreso piacevolmente. Portami i cuori e mi impressionerai ancora una volta.",
  reward = "A guardarli così, i cuori dei puri sembrano più o meno come tutti gli altri, non trovi?$B$BForse abbiamo un'idea un po'... diversa... della faccenda. Comunque, questi andranno bene. Sono sicuro che la loro purezza attirerebbe una succube.",
  en_title = "Hearts of the Pure",
  en_obj = "Bring the hearts of Dalin Forgewright and Comar Villard to Carendin Halgar in the Temple of the Damned.",
}
T[1477] = {
  title = "Rifornimenti Vitali",
  desc = "A Nethergarde Keep, nelle Blasted Lands, i nostri maghi stanno portando avanti ricerche vitali per comprendere i Dark Portals. I rifornimenti servono loro quasi di continuo, ma la linea che li porta a Nethergarde è fragile.$B$BDevi aiutarci a farli arrivare a Nethergard. Presentati a Watchmaster Sorigal a Darkshire e fa' quello che ti chiede. Questo compito ti porterà in terre ostili, $N. Preparati.",
  obj = "Parla con Watchmaster Sorigal.",
  reward = "Ti manda Andromath? Benissimo. Ho un compito importante per te...",
  en_title = "Vital Supplies",
  en_obj = "Speak with Watchmaster Sorigal.",
}
T[1478] = {
  title = "La Convocazione di Halgar",
  desc = "Ah, $N! Carendin Halgar mi ha appena fatto sapere che desidera vederti per proseguire il tuo addestramento.$B$BDovresti andarne $Gfiero:fiera;, $N. Non capita tutti i giorni che il Maestro Halgar ritenga opportuno istruire di persona $Gun giovane stregone:una giovane strega;.$B$BLo troverai nel Magic Quarter of the Undercity, vicino al Temple of the Damned.",
  obj = "Parla con Carendin Halgar a Undercity.",
  reward = "Bene, vedo che Ageron è riuscito a trovarti, $N. Non perdiamo tempo in chiacchiere e convenevoli: concentriamoci sul tuo addestramento. Hai ancora molto da imparare.",
  en_title = "Halgar's Summons",
  en_obj = "Speak with Carendin Halgar in the Undercity.",
}
T[1479] = {
  title = "La Bough of the Eternals",
  desc = "Ho sentito dire che gli elfi della notte tengono la banca dentro un albero — un albero che sembra un orso! Che forte! Gli elfi della notte sono simpatici, con quella loro passione per la natura e roba così, ma gli orsi sono proprio fortissimi!$B$BMi porteresti a Darnassus a vedere l'albero-orso, per favore? C'è una nave che arriva lì vicino, e non dovrebbe volerci tanto. Ti prego, ti prego, ti prego!",
  obj = "Porta l'orfano alla banca di Darnassus. La banca è scavata dentro un albero chiamato Bough of the Eternals.",
  progress = "Siamo arrivati?",
  reward = "Wow, era ancora più forte di come me la immaginavo — la Bough of the Eternals! Non pensavo che fosse così grande, e invece lo è! Hai visto pure l'uccello lassù in cima?! Chissà come hanno fatto a dare ai rami quella forma!$B$BGrazie di avermi portato a Darnassus, $N. Sei $Gfortissimo:fortissima;!",
  en_title = "The Bough of the Eternals",
  en_obj = "Take the orphan to the bank of Darnassus.  The bank itself is hollowed out of a tree known as the Bough of the Eternals.",
}
T[1480] = {
  title = "Il Corruttore",
  desc = "La pelle lacerata puzza di marcio, ed è sorprendentemente flessibile per una cosa che sembra secca e fragile.$B$BSrotolandola, su un lato vedi bene dei segni rossi scritti in una specie di lingua. In fondo alla pelle c'è un simbolo molto chiaro: immagini che sia una sorta di firma.$B$BForse Maurin saprebbe dirti qualcosa di più?",
  obj = "Porta la Flayed Demon Skin a Maurin Bonesplitter in Desolace.",
  progress = "I membri della Burning Blade cominciano a capire quanto siano deboli davvero. Hanno magie patetiche e una forza misera.$B$BL'unico potere che hanno viene da chi servono, non da una qualche comprensione del vero potere e della vera conoscenza.",
  reward = "Hmm, queste rune sono proprio una lingua, $N, e antica. Ricorda vagamente la lingua Eredun, ma le differenze sono enormi. Se non sbaglio è una specie di contratto.... Ecco, sì, questo simbolo è la firma del demone: Lord Azrethoc.",
  en_title = "The Corrupter",
  en_obj = "Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace.",
}
T[1481] = {
  title = "Il Corruttore",
  desc = "Con i reagenti giusti, credo di poter trovare questo signore dei demoni.$B$BSe è potente come sospetto, mi serviranno oggetti presi da creature letali. Ma tu agisci in nome del Capoguerra, e sono certo che accetterai il mio incarico.$B$BPer prima cosa dovrò spezzare ogni protezione che abbia contro la divinazione, e per questo mi serve lo scalpo di un satiro — non di un satiro qualsiasi, però. Dev'essere di uno shadowstalker Hatefury.$B$BCercali fra le antiche rovine, nel nord-est di Desolace.",
  obj = "Porta uno Shadowstalker Scalp a Maurin Bonesplitter in Desolace.",
  progress = "Non portarmi lo scalpo sbagliato, $C. Con i reagenti errati potremmo rimetterci la vita: il signore dei demoni potrebbe portare su di sé incantesimi pronti a scattare e uccidere chiunque tenti di scrutarlo.$B$BDi dolore, il destino me ne ha già dato abbastanza.",
  reward = "Gli shadowstalker non sono riusciti a ucciderti, $C. Notevole... davvero notevole.$B$BQuesto scalpo andrà benissimo per il mio incantesimo, e mentre eri via ho raccolto alcuni degli altri reagenti che servono.$B$BSono quasi pronto. Manca solo un focus per l'incantesimo — qualcosa che proietti un'immagine del signore dei demoni e del luogo dove si trova.",
  en_title = "The Corrupter",
  en_obj = "Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace.",
}
T[1482] = {
  title = "Il Corruttore",
  desc = "Un oracle crystal andrebbe benissimo. Li fabbricano i naga, per i loro oracoli.$B$BLungo la costa, a nord-ovest di qui, c'è un'enorme barriera corallina dove i naga hanno fatto la loro dimora quando stanno così vicini alla riva. Lì troverai i loro oracoli. Gli Slitherblade sono letali e non gradiranno le tue intrusioni: fai attenzione, e sbrigati.$B$BQuando torni, vedremo di trovare questo signore dei demoni, Azrethoc.",
  obj = "Porta un Oracle Crystal a Maurin Bonesplitter in Desolace.",
  progress = "Sono pronto per l'oracle crystal, $C. Trovare e distruggere questo Lord Azrethoc ci varrebbe a entrambi il grande favore del Capoguerra. Faremmo bene a collaborare, e in fretta, per perseguire i nostri scopi e ingraziarcelo.",
  reward = "Un prezioso oracle crystal... perfetto... bellissimo. Proprio così.$B$BCominciamo subito. Trovare questo signore dei demoni dev'essere la nostra priorità, e per ucciderlo servirà tutta la nostra attenzione.$B$BFai un passo indietro, $C, e vediamo cos'è questo demone e dove si trova.",
  en_title = "The Corrupter",
  en_obj = "Bring an Oracle Crystal to Maurin Bonesplitter in Desolace.",
}
T[1483] = {
  title = "Ziz Fizziks",
  desc = "La Venture Company ci ha rubato molte delle migliori teste goblin, ma ogni tanto ci capita l'occasione di rubargliene qualcuna a nostra volta.$B$BTempo fa la squadra della Venture Company nelle Stonetalon Mountains ha assunto Gerenzo Wrenchwhistle — uno gnomo! L'altro loro ingegnere, Ziz Fizziks, ne è rimasto così sconvolto che mi ha supplicato di trovargli un nuovo impiego nel Tinkers' Union. Gli ho affidato qualche incarico, ma potrebbe aver bisogno d'aiuto.$B$BMagari potresti andare a dargli un'occhiata per me? È di stanza sul margine occidentale della Windshear Crag.",
  obj = "Parla con Ziz Fizziks, a Windshear Crag.",
  reward = "Pensavo che i pezzi grossi della Venture Company fossero degli aguzzini, poi ho conosciuto Sputtervalve, il più crudele di tutti!$B$BAh! Anche se è sempre meglio che restare senza lavoro, immagino... O peggio, lavorare con quel Gerenzo. Se sei qui per aiutare, ho qualcosa da farti fare.",
  en_title = "Ziz Fizziks",
  en_obj = "Speak with Ziz Fizziks in Windshear Crag.",
}
T[1484] = {
  title = "Il Corruttore",
  desc = "Questa creatura è molto più pericolosa del previsto. Takata dubiterà di certo che io sia in grado di affrontarla, e tenerlo all'oscuro di quanto è appena successo sarebbe un'offesa al suo onore.$B$BVa' a parlare con lo spadaccino e digli che sei $Gdisposto:disposta; a uccidere il demone, se lui te lo permette, ma senza insistere troppo. È meglio che creda di averci pensato lui.",
  obj = "Parla con Takata Steelblade in Desolace.",
  reward = "Ho visto cos'è appena successo tra Maurin e il signore dei demoni. Anche solo come apparizione, quella creatura sembra più potente del mio compagno stregone. Chissà se è all'altezza di sconfiggere il mostro? Il Capoguerra lo servirei meglio andandoci io, ma ho delle responsabilità qui: se voltassi le spalle ai miei doveri per combattere questo male in nome del mio onore, disonorerei il mio clan.",
  en_title = "The Corrupter",
  en_obj = "Speak to Takata Steelblade in Desolace.",
}
T[1485] = {
  title = "Vile Familiars",
  desc = "Gli stregoni che ci hanno preceduti si sono guadagnati la diffidenza dell'Orda, e anche se ci tollerano, non ci amano.$B$BQuesto, però, non ci ha reso più uniti, perché molti scelgono una vita da reclusi e si dilettano di magia per conto proprio. Non cercherò di spingerti verso l'una o l'altra strada, ma solo di aiutarti a crescere.$B$BPrima di insegnarti l'arte dell'evocazione, devi portarmi sei teste dei vile familiars della grotta a nordest.",
  obj = "Porta 6 Vile Familiar Heads a Ruzan.",
  progress = "È importante che tu sappia controllare gli esseri che evochi con la magia. Sono così pochi quelli interessati a imparare l'arte del $C che non rischierei la tua vita insegnandoti qualcosa prima che tu sia $Gpronto:pronta;.",
  reward = "Durante l'addestramento da $C imparerai a richiamare esseri di ogni tipo. Alcuni forse non lo sembrano, ma sono tutti strumenti utili.$B$BNon farti ingannare dalle piccole dimensioni dell'imp. Come avrai senz'altro notato, anche se è così piccolo resta un avversario temibile.",
  en_title = "Vile Familiars",
  en_obj = "Bring 6 Vile Familiar Heads to Ruzan.",
}
T[1486] = {
  title = "Deviate Hides",
  desc = "Mentre Naralex scivolava sempre più a fondo nel suo incubo, una strana razza di bestie è emersa da sotto le Barrens nelle Wailing Caverns.$B$BSono creature degeneri, con strane proprietà ultraterrene. Per natura sono malvagie, eppure penso che dalla loro presenza qui a Kalimdor possa venire qualcosa di buono: le loro pelli, credo, saranno particolarmente utili per lavorare il cuoio.$B$BSe ti senti all'altezza, avventurati nelle grotte qui sotto e recupera un po' di deviate hides.",
  obj = "Nalpak, in Wailing Caverns, vuole 20 Deviate Hides.",
  progress = "Le pelli delle creature degeneri che hanno infestato queste grotte mi interessano molto: vorrei proprio esaminarle. Sei $Griuscito:riuscita; a raccoglierne qualcuna, $C?",
  reward = "Il tuo impegno nel raccogliere queste pelli non passerà inosservato, $N.$B$BGrazie della dedizione.",
  en_title = "Deviate Hides",
  en_obj = "Nalpak in the Wailing Caverns wants 20 Deviate Hides.",
}
T[1487] = {
  title = "Sterminio dei Degeneri",
  desc = "Lo scopo di Naralex era nobile.$B$BIl nostro grande capo voleva entrare in The Emerald Dream per aiutare queste terre aspre a ridiventare la foresta rigogliosa di un tempo. Ma qualcosa è andato terribilmente storto.$B$BIl sogno di Naralex è diventato un incubo, e le caverne hanno cominciato a popolarsi di creature corrotte.$B$BAlcuni dei Disciples of Naralex tentano di risvegliare il nostro maestro; a me, invece, preme liberare queste grotte dalle bestie malvagie.$B$BSfida le caverne, $N, e stermina la progenie degenere.",
  obj = "Ebru, in Wailing Caverns, vuole che tu uccida 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers e 7 Deviate Dreadfangs.",
  progress = "$N, a noi Disciples of Naralex serve il tuo aiuto. Da quando il nostro maestro è intrappolato nel suo incubo distorto siamo sempre di meno, e non abbiamo le forze per affrontare le creature corrotte che ora infestano queste caverne.$B$BTi supplico: entra nelle grotte e muovi guerra alle creature degeneri!",
  reward = "Come Disciple of Naralex, lodo il tuo coraggio, $N.$B$BIl tuo aiuto per liberare le caverne è il primo passo della nostra lunga lotta per risanare le Barrens.$B$BTi ringrazio. Che tu possa prosperare.",
  en_title = "Deviate Eradication",
  en_obj = "Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.",
}
T[1488] = {
  title = "Il Corruttore",
  desc = "Di questo Lord Azrethoc non so nulla, ma sono d'accordo con Maurin: va fermato, soprattutto se sta cercando di far presa sulla Burning Blade per i suoi scopi.$B$BHai già dimostrato di voler aiutare il Capoguerra, e vorrei affidare a te il compito di radunare un gruppo e uccidere il signore dei demoni e il suo servo stregone.$B$BQuando sarai $Gpronto:pronta;, dirigiti dritto a sud, e una volta eliminata la minaccia torna da me.",
  obj = "Uccidi Lord Azrethoc e Jugkar Grim'rod, poi torna da Takata Steelblade in Desolace.",
  progress = "Gloria all'Orda e morte ai nostri nemici, $N!$B$BI demoni di Desolace non sono mai stati una minaccia così grande. Più queste creature immonde sembrano moltiplicarsi, più si affievolisce la speranza di tornare dal Capoguerra.$B$BA volte vorrei che avessimo da vedercela solo con i centauri.",
  reward = "Una grande vittoria per tutti noi, $N. Festeggiamo il tuo successo. Adesso credo che il nostro futuro qui non sia così cupo come pensavo un tempo.$B$BI demoni saranno uccisi, gli sforzi della Burning Blade andranno a vuoto, e forse un giorno avremo di nuovo un posto da chiamare casa senza paura.",
  en_title = "The Corrupter",
  en_obj = "Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace.",
}
T[1489] = {
  title = "Hamuul Runetotem",
  desc = "Nelle conchiglie che mi hai portato c'è una contaminazione che non avevo mai visto. Viene dall'acqua delle Oasi, ne sono certo, e sento la confusione che le Oasi portano in questa terra. È come se la terra sognasse senza riuscire a svegliarsi.$B$BLa contaminazione deve nascere nelle Wailing Caverns. Prima di andarci, però, parla con Hamuul Runetotem, il druido anziano. Gli ho mandato notizia di quello che succede nelle Barrens. È saggio, e potrà consigliarti.$B$BLo troverai sull'Elder Rise, a Thunder Bluff.",
  obj = "Parla con Hamuul Runetotem",
  reward = "Ti porgo i miei saluti, $N. Sei $Gil benvenuto:la benvenuta; qui, ma ti consiglio di raccogliere tutte le tue forze, perché il compito che ora ti affidiamo... è terribile.",
  en_title = "Hamuul Runetotem",
  en_obj = "Speak with Hamuul Runetotem.",
}
T[1490] = {
  title = "Nara Wildmane",
  desc = "Sono entrato nella terra dei sogni e ho sognato una setta di druidi che dimora nelle Wailing Caverns. Ho visto che un tempo avevano scopi nobili, ma hanno smarrito la via. Ora servono la contaminazione che si infiltra nelle Barrens.$B$BSono vecchio, e le forze mi vengono meno. Non sono riuscito a restare a lungo in quel luogo del sogno, e dei druidi contaminati so poco di più. Nara invece è giovane, e ha uno spirito indomito. Quando sono fuggito, lei è rimasta nel sogno.$B$BVa' a parlare con Nara. La trovi nella tenda, laggiù.",
  obj = "Parla con Nara Wildmane.",
  reward = "Sì, è così. Conosco i druidi delle Wailing Caverns. Ho visto i loro volti deformi, coperti di scaglie. Conosco i loro crimini, e conosco i loro piani.$B$BDevi fermarli, $N.",
  en_title = "Nara Wildmane",
  en_obj = "Speak with Nara Wildmane.",
}
T[1491] = {
  title = "Bevande Intelligenti",
  desc = "Ok, le corna di raptor non hanno funzionato granché. Ma va bene così — nessuno è diventato ricco al primo tentativo! E poi credo di aver trovato qualcosa che nelle mie bevande intelligenti funzionerà ancora meglio!$B$BC'è una sostanza che si chiama Wailing Essence, e credo sia lei la causa delle piante e degli animali strani delle Barrens. Procuramene un po' e la provo nella mia bevanda!$B$BHo sentito dire che l'essenza si accumula nelle creature ectoplasmatiche delle Wailing Caverns, a ovest. Va' a dare la caccia a quelle creature e raccogli l'essenza.",
  obj = "Porta 6 porzioni di Wailing Essence a Mebok Mizzyrix a Ratchet.",
  progress = "E la mia wailing essence, dov'è?",
  reward = "Benissimo, ce l'hai! Non vedo l'ora di provarla: mi farà fare una fortuna, me lo sento!$B$BGrazie, $N. Prendi questo, e quando sarò ricco te ne manderò ancora, promesso!",
  en_title = "Smart Drinks",
  en_obj = "Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet.",
}
T[1498] = {
  title = "La Via della Difesa",
  desc = "Fra i compiti di un guerriero, uno dei più importanti è... proteggere. Siamo lo scudo dell'Orda, a difesa dei fratelli più deboli. Se vuoi entrare nelle nostre file, prima devi dimostrarmi quanto vali.$B$BVai alla Thunder Ridge, nel Durotar: lì vivono le lightning hides e i thunder lizards. Dai la caccia a quelle bestie! Fammi vedere che sei più $Gduro:dura; di loro! Reggi i loro attacchi e, come prova, portami un mucchio delle loro singed scales.$B$BFallo, e allora ti insegnerò.",
  obj = "Porta 5 Singed Scales a Uzzek a Far Watch Post, nelle Barrens.",
  progress = "Ce le hai, le scaglie, $N? Se non sai reggere agli attacchi dei thunder lizards, quello che ti insegno non ti servirà a niente.",
  reward = "Ah. Vedo che hai sconfitto i thunder lizards: è la prova che sei $Gduro:dura;. Adesso ti mostrerò come una pelle resistente e delle mosse accorte, messe insieme, diventano un muro di difesa impenetrabile.$B$BImpara bene questa lezione, $N, e tieniti $Gpronto:pronta; per le prossime.",
  en_title = "Path of Defense",
  en_obj = "Bring 5 Singed Scales to Uzzek at Far Watch Post in the Barrens.",
}
T[1499] = {
  title = "Vile Familiars",
  desc = "Zureetha sta mandando novizi come te a dare una mano a ridurre il numero delle creature della grotta vicino al luogo in cui hai combattuto i vile familiars.$B$BCredo che ti farebbe bene aiutarla: faresti esperienza. Ricordati di dirle che hai contribuito a risolvere il problema degli imp, perché probabilmente avrà una ricompensa per te.",
  obj = "Parla con Zureetha Fargaze.",
  reward = "Hai fatto un buon lavoro, $N.$B$BAnche se i vile familiars erano solo gli animaletti al servizio delle forze più oscure della Burning Blade, la tua vittoria su di loro è il preludio di imprese più grandi.",
  en_title = "Vile Familiars",
  en_obj = "Speak with Zureetha Fargaze.",
}
T[1500] = {
  title = "Il Risveglio di Naralex",
}
T[1501] = {
  title = "Creatura del Vuoto",
  desc = "Sono rimasti così pochi stregoni... Rischiamo molto, ma ne vale la pena. Devi far maturare in fretta le tue capacità, se vuoi essere utile all'Orda e al Capoguerra.$B$BÈ giunto il momento che tu impari un nuovo incantesimo di evocazione.$B$BPer prima cosa, devi recuperare la Tablet of Verga, rubata dagli stregoni della Burning Blade e ora custodita nel loro covo a Skull Rock, a est della città. Con quella ti mostrerò le rune necessarie per evocare un voidwalker.",
  obj = "Recupera la Tablet of Verga per Gan'rul Bloodeye a Orgrimmar.",
  progress = "Hai la Tablet of Verga, $N? Se non ce l'hai, non voglio parlarti finché non l'avrai.",
  reward = "Bene. Spero che tu abbia inflitto qualche altra perdita alla Burning Blade mentre andavi a recuperarla.$B$BSono stati una grossa spina nel fianco per il Capoguerra, e una vera piaga per tutti gli stregoni.",
  en_title = "Creature of the Void",
  en_obj = "Retrieve the Tablet of Verga for Gan'rul Bloodeye in Orgrimmar.",
}
T[1502] = {
  title = "Thun'grim Firegaze",
  desc = "Per un guerriero è fondamentale avere un'arma di qualità. E se c'è un orco che sa forgiarne di buone, quello è Thun'grim Firegaze, un eremita che vive in cima alle colline a est del Crossroads.$B$BSe vuoi un'arma, $Gguerriero:guerriera;, devi cercare Thun'grim. Per trovarlo, va' prima al Crossroads, a ovest, e da lì dirigiti a est verso le colline: il suo accampamento è lassù, in cima a un colle.",
  obj = "Parla con Thun'grim Firegaze nelle Barrens.",
  reward = "Gli occhi mi si sono seccati da tempo, a forza di fissare la fiamma della forgia, ma certe cose riesco ancora a vederle. E vedo che vuoi qualcosa.$B$BSe hai trovato la strada fin qui, non è difficile immaginare cosa desideri.",
  en_title = "Thun'grim Firegaze",
  en_obj = "Speak with Thun'grim Firegaze in the Barrens.",
}
T[1503] = {
  title = "Acciaio Forgiato",
  desc = "L'arma te la darò, $N, ma prima mi serve il tuo aiuto. Qualche notte fa i Razormane che stanno a nord-ovest sono entrati nel mio accampamento. Non hanno voluto battersi con me, ma sanno che ci vedo poco — alcuni mi hanno distratto grugnendo mentre gli altri mi derubavano! Codardi!$B$BSi sono presi un forziere di ferro con dentro dei forged steel bars. Se riesci a recuperarli, avrai l'arma che cerchi.$B$BCerca la cassa di ferro negli accampamenti dei verrospini e torna da me con i forged steel bars.",
  obj = "Porta i Forged Steel Bars a Thun'grim Firegaze nelle Barrens.",
  progress = "Allora, ce li hai i miei steel bars?",
  reward = "Li hai trovati! E ci sono tutti, i lingotti: non mi sorprende, non credevo che i Razormane sapessero che farsene di un acciaio pregiato come questo.$B$BGrazie, $N. Questa è la tua ricompensa: che ti sia utile.",
  en_title = "Forged Steel",
  en_obj = "Bring the Forged Steel Bars to Thun'grim Firegaze in the Barrens.",
}
T[1504] = {
  title = "Il Vincolo",
  desc = "Ora osserva la Tablet of Verga: contiene i glifi che ti serviranno per l'evocazione. Portali al cerchio nella tenda di Neeru Fireblade, dall'altra parte della caverna. Lì potrai chiamare a te il voidwalker.$B$BDovrai sconfiggerlo con tutti i mezzi fisici e magici a tua disposizione. Fatto questo, torna da me con i glyphs of summoning e ti mostrerò come piegare la creatura al tuo volere.",
  obj = "Usando i Glyphs of Summoning, evoca e sottometti un voidwalker, poi riporta i Glyphs of Summoning a Gan'rul Bloodeye a Orgrimmar.",
  progress = "Il voidwalker è una creatura potente. Ricordo quando ero io al tuo posto, $N. Con gli anni il mio voidwalker ha imparato a combattermi meno, anche se sospetto che lo faccia solo nella speranza che io abbassi la guardia.$B$BRicordatelo, $N.",
  reward = "Hai fatto un buon lavoro, $N. Ti mostrerò come evocare un voidwalker simile a quello che hai appena sconfitto.$B$BDevi sapere che nutriamo grandi aspettative su di te e che, finora, ne sei $Gstato:stata; all'altezza.$B$BNon montarti la testa, però: le prove che ancora ti attendono faranno sembrare tutto questo un gioco da ragazzi.",
  en_title = "The Binding",
  en_obj = "Using the Glyphs of Summoning, summon and subdue a voidwalker, then return the Glyphs of Summoning to Gan'rul Bloodeye in Orgrimmar.",
}
T[1505] = {
  title = "Il Veterano Uzzek",
  desc = "L'Orda onora i suoi guerrieri perché nessuno mette in dubbio la loro forza. Eppure i guerrieri davvero grandi sono anche grandi allievi.$B$BCerca Uzzek, un veterano di molte battaglie che oggi insegna l'arte del combattimento ai giovani guerrieri. Lo troverai a sud del Far Watch Post, la guarnigione degli orchi sul confine fra le Barrens e Durotar, a est.",
  obj = "Parla con Uzzek a Far Watch Post.",
  reward = "Salve, giovane. Sei $Gvenuto:venuta; a prendere qualche lezione, vero?",
  en_title = "Veteran Uzzek",
  en_obj = "Speak with Uzzek at Far Watch Post.",
}
T[1506] = {
  title = "La Convocazione di Gan'rul",
  desc = "Ehi, tu. $N, giusto?$B$BSpero che tu non abbia impegni, perché Gan'rul vuole vederti subito. Lo troverai con gli stregoni più esperti nella Cleft of Shadow.$B$BA giudicare da come sono andate le cose con lui in passato, questa convocazione o è un'ottima notizia o è una pessima.",
  obj = "Parla con Gan'rul Bloodeye a Orgrimmar.",
  reward = "Bene. Temevo che Ophek non riuscisse a trovarti.$B$BÈ ora di portare avanti il tuo addestramento da $Gstregone:stregona;. Qualunque faccenda tu abbia in corso dovrà aspettare.$B$BNon ci saranno problemi, vero?",
  en_title = "Gan'rul's Summons",
  en_obj = "Speak with Gan'rul Bloodeye in Orgrimmar.",
}
T[1507] = {
  title = "Divoratore di Anime",
  desc = "È ora che tu impari qualcosa di più sulle magie di evocazione. Imparerai a evocare una sayaad, una creatura dai poteri mentali incredibili. Sa cullare i deboli di mente fino a farne suoi servi — ma non temere! Sono certo che sarai all'altezza della sfida.$B$BUna sayaad si può evocare solo attirandola con un oggetto che rappresenti grande devozione e amore. Trovarne uno sta a te.$B$BUn consiglio? Parla con Cazul... A quanto pare, c'è ben poco che l'antico stregone non sappia.",
  obj = "Parla con Cazul nella Cleft of Shadow.",
  reward = "Mm... $N. Sei ancora agli inizi del tuo cammino, ma sento che puoi raggiungere la grandezza.$B$BSei $Gnato:nata; con dei doni, $N. Vedi di non sprecarli.",
  en_title = "Devourer of Souls",
  en_obj = "Speak with Cazul in the Cleft of Shadow.",
}
T[1508] = {
  title = "Cazul il Cieco",
  desc = "Se Gan'rul ti ha mandato da me, vuol dire che devi evocare una succube, una femmina della razza sayaad, e ti serve un oggetto che le faccia da esca.$B$BMmm... Se ti fidi di un cieco come guida, $N, allora ascolta. Zankaja vive sulle alture di Orgrimmar, a ovest della torre dei wind rider, e aspetta che il suo compagno torni.$B$BVa' da lei.",
  obj = "Parla con Zankaja a Orgrimmar.",
  reward = "Sei $Gvenuto:venuta; a portarmi notizie di Dogran? Doveva tornare giorni fa, e non ne so più niente...",
  en_title = "Blind Cazul",
  en_obj = "Speak with Zankaja in Orgrimmar.",
}
T[1509] = {
  title = "Notizie di Dogran",
  desc = "Il mio compagno, Dogran, è stato mandato da poco in servizio al Crossroads. Era una promozione, e ne andava molto fiero.$B$BIo ero triste, certo, ma non gliel'ho fatto capire. Ed ero anche preoccupata, perché The Barrens è un posto più pericoloso di Orgrimmar, e temevo il peggio.$B$BOra sarebbe dovuto tornare già da una settimana, e di lui non ho saputo niente...$B$BMagari potresti andare al Crossroads a sentire se sanno qualcosa? Lavorava con Gazrog, che dovrebbe essere ancora di stanza lì.",
  obj = "Parla con Gazrog al Crossroads.",
  reward = "Zankaja? La compagna di Dogran, giusto?$B$BSì, ho avuto sue notizie, ma è meglio che lei non le venga a sapere...$B$BNo, non è morto. Però è ferito, e i quilboar lo tengono prigioniero.",
  en_title = "News of Dogran",
  en_obj = "Speak with Gazrog at the Crossroads.",
}
T[1510] = {
  title = "Notizie di Dogran",
  desc = "Era di stanza a Camp Taurajo, dove stiamo cercando di estirpare i quilboar. Ha guidato alcuni grunt fino a uno dei loro accampamenti, e lì è stato ferito gravemente. Gli altri sono riusciti a tornare e hanno provato a salvarlo, ma era messo male e le ferite si erano infettate: avevano paura di spostarlo senza prima rattopparlo.$B$BCi è arrivato un messaggio: chiedevano una bevanda curativa dei troll del Malaka'jin, ai piedi delle Stonetalon Mountains. Abbiamo mandato qualcuno a prenderla, ma non è ancora tornato.",
  obj = "Parla con Ken'zigla al Malaka'jin.",
  reward = "$GUn altro orco:Un'altra orchessa;, eh? Spero che tu non sia $Gvenuto:venuta; per quell'altro. Non ce l'ha fatta: quei goblin l'hanno sistemato per bene.$B$BA parte che gli serviva una bevanda curativa, non ha detto molto.",
  en_title = "News of Dogran",
  en_obj = "Speak with Ken'zigla at the Malaka'jin.",
}
T[1511] = {
  title = "Ken'zigla's Draught",
  desc = "Immaginavo che potesse venire qualcun altro a prendere la bevanda, quindi l'ho preparata lo stesso.$B$BEcco qua, $N. Bada bene, gliene devi dare solo metà! Avrà abbastanza forza per muoversi senza dissanguarsi. Aspetta una notte, poi dagli l'altra metà.$B$BComunque, dovrai portarla a Logmar, a Camp Taurajo. Da quello che mi ha detto il primo, lui dovrebbe avere un'idea di dove sia questo Dogran.",
  obj = "Porta la Ken'zigla's Draught al Grunt Logmar a Camp Taurajo.",
  progress = "Sì, che c'è?",
  reward = "Beh, era ora! Dogran sta morendo là fuori mentre la aspetta.$B$BDobbiamo fargliela avere subito, ma la maggior parte dei grunt di stanza qui è via per una missione di approvvigionamento.",
  en_title = "Ken'zigla's Draught",
  en_obj = "Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo.",
}
T[1512] = {
  title = "Il Dono dell'Amore",
  desc = "Zankaja è giovane e bella. Restare incatenata a un invalido... non le permetterò di subire un'ingiustizia simile.$B$BLasciami, $N. E grazie. Così potrò morire in una battaglia gloriosa, e non come un guscio senza vita.$B$BE ti prego, alla mia compagna non dire niente di tutto questo... Non voglio che si senta in colpa.",
  obj = "Porta il Dirt-caked Pendant a Gan'rul Bloodeye a Orgrimmar.",
  progress = "Eccoti $Gtornato:tornata;. Sei $Gpronto:pronta; a combattere una succube?",
  reward = "Se dici che basterà, allora mi fido di te, $N. Però lascia che lo pulisca... Immacolato e splendente, a una succube potrebbe fare ancora più gola.",
  en_title = "Love's Gift",
  en_obj = "Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar.",
}
T[1513] = {
  title = "Il Vincolo",
  desc = "Porta questo al cerchio di evocazione nella tenda di Neeru, $N. Evoca una succube immonda e dimostrale che sai dominarla. Ho fiducia nella forza della tua magia. Ma come sempre stai in guardia: l'orgoglio e la troppa sicurezza hanno avuto la meglio su molti stregoni promettenti.$B$BQuando l'avrai sconfitta, riportami il pendente, così potrò dare la notizia a Zankaja.",
  obj = "Usando il Dogran's Pendant, evoca e sottometti una succube, poi riporta il Dogran's Pendant a Gan'rul Bloodeye a Orgrimmar.",
  progress = "Quando guardo una succube, il cuore mi spicca il volo... Eppure nello stesso momento sento quasi l'anima ritirarsi, scivolare via come la marea.$B$BStai in guardia, $Gamico mio:amica mia;.",
  reward = "Ce l'hai fatta! Sappi che non mi aspettavo niente di meno $Gdal mio allievo migliore:dalla mia allieva migliore;.$B$BHai dimostrato quanto vali, e sarò lieto di insegnarti a evocare la succube che hai sottomesso. Ora va', hai molto da imparare: la prossima volta che ci vedremo, mi aspetto che tu sappia dominare davvero la tua succube.$B$BIl dolore di Dogran e Zankaja lascialo a chi fra noi ha più anni, ma ricordalo e custodiscilo, che ti difenda dalle lusinghe del potere oscuro che oggi hai imparato a evocare.",
  en_title = "The Binding",
  en_obj = "Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar.",
}
T[1514] = {
  title = "Corrupted Windblossom",
  progress = "Quella che hai trovato sembra una pianta di windblossom, malata e corrotta. Le bacche che ne pendono sembrano marce e velenose. Per tornare com'era, ha un disperato bisogno di cure.",
  reward = "Sul windblossom applichi due unguenti per piante Cenarion, e la pianta comincia subito a perdere l'aspetto corrotto: rifiorisce, rigogliosa e sana.",
}
T[1515] = {
  title = "La Prigionia di Dogran",
  desc = "Sei $Garrivato:arrivata; fin qui, quindi se vuoi andare fino in fondo non sarò io a fermarti. Però non posso darti altri uomini: sarai $Gsolo:sola;.$B$BDogran è prigioniero in un accampamento quilboar a nord di qui. Cerca due capanne vicine. Sarà ben sorvegliato — sempre che non l'abbiano già ucciso, o che non sia morto per le ferite.$B$BBuona fortuna.",
  obj = "Porta la Ken'zigla's Draught a Dogran nella Barrens.",
  progress = "Urrrghhhh...",
  reward = "Che intruglio disgustoso...$B$BOra la forza ce l'ho, quanto basta per andarmene zoppicando... Ma la gamba non la recupererò mai più. E il braccio nemmeno.",
  en_title = "Dogran's Captivity",
  en_obj = "Bring Ken'zigla's Draught to Dogran in the Barrens.",
}
T[1516] = {
  title = "Il Richiamo della Terra",
  desc = "È giunto il momento, giovane $C. Sei $Gdiventato:diventata; forte e il tuo spirito resiste come la terra. Il fatto stesso di seguire il cammino dello sciamano dimostra la tua saggezza, ancor prima che tu abbia dato prova di te.$B$BL'elemento della terra guiderà il tuo destino e diventerà parte di te, se sei $Gpronto:pronta;. Ma dovrai presentarti al cospetto della terra stessa. Se sei $Gpronto:pronta;, vedrai cose che conoscono solo gli sciamani.$B$BCerca i Felstalkers a nord e prendi due dei loro zoccoli. Poi torna da me, e parleremo ancora del tuo futuro.",
  obj = "Porta 2 Felstalker Hooves a Canaga Earthcaller in Valley of Trials.",
  progress = "La pazienza è la più grande virtù della terra. La terra assiste al ciclo di tutte le cose: le montagne che si fanno deserti; i fiumi che diventano canyon. È l'elemento più testardo e più saggio di tutti, e non tollera l'impazienza.$B$BOra la terra ti chiama perché si avvicina un tempo di conflitto. Quando tornerai da me dopo esserci $Griuscito:riuscita;, sarai un passo più $Gvicino:vicina; a diventare $Gcompleto:completa;.$B$BGli altri invidieranno la tua saggezza e, nella loro ignoranza, ti odieranno.",
  reward = "Eccellente. Il tuo successo dimostra che sei $Gpronto:pronta;.$B$BFra tutti gli elementi, è la terra il fondamento di ogni cosa. È la tua forza, la tua resistenza e la tua pazienza. La terra ti proteggerà, ma solo se le mostrerai il dovuto rispetto. Come gli altri elementi, anche lei può essere volubile. È la base della vita, e osservandone le leggi acquisirai una saggezza maggiore. Non dimenticare mai i segreti che condivide con te.$B$BOra ti preparerò una sapta: accettandola, comprenderai il tuo cammino.",
  en_title = "Call of Earth",
  en_obj = "Bring 2 Felstalker Hooves to Canaga Earthcaller in the Valley of Trials.",
}
T[1517] = {
  title = "Il Richiamo della Terra",
  desc = "La sapta è una bevanda creata per legare i nostri spiriti agli elementi. Infusa di magia, la pozione permette a chi ha una volontà forte di vedere gli elementi come nessun altro può. Il tuo spirito sarà legato all'elemento per cui è stata preparata, e solo pochi sciamani eletti ne conoscono la ricetta.$B$BVa bevuta sempre in un luogo sacro, mai altrove — ricordalo.$B$BCerca la Spirit Rock a sud-ovest di qui — si trova alla fine dell'Hidden Path. Bevi lì la tua sapta, e... be', vedrai.",
  obj = "Trova Spirit Rock e bevi l'Earth Sapta.",
  reward = "Ah... $N... lieta è la terra di averti qui.$B$B$GLegato:Legata; nel corpo e nello spirito, andrai avanti sapendo che le montagne sono la tua forza; le pianure, la tua pazienza; e il mondo stesso la tua essenza.$B$BPer superare questo rito ti basta presentarti con umiltà al cospetto della terra. Ma gli altri elementi non sono altrettanto passivi. Possono essere caotici e spesso violenti, ma tale è la loro natura. Nature duali che si oppongono l'una all'altra: devi imparare a conoscerle a fondo.",
  en_title = "Call of Earth",
  en_obj = "Find Spirit Rock and drink the Earth Sapta.",
}
T[1518] = {
  title = "Il Richiamo della Terra",
  desc = "Prendi questo rough quartz e portalo a Canaga Earthcaller come prova del nostro incontro. Ti creerà un totem, e questo sassolino ne sarà il cuore. Per quanto possa sembrare minuscolo, scoprirai che le dimensioni non contano, e che anche la più piccola delle cose può durare più di molte altre.$B$BSii paziente, $N. Resta forte. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con la terra — rispettala come lei rispetterà te.",
  obj = "Porta il Rough Quartz a Canaga Earthcaller in Valley of Trials.",
  progress = "Voglio essere io, prima di chiunque altro, ad accoglierti pienamente sul primo dei quattro sentieri che guideranno per sempre il tuo destino.$B$BSe hai la pietra che ti ha dato la terra, ti consegnerò il totem che ti ha promesso.$B$BAltrimenti vattene, e non tornare finché non avrai trovato la tua strada.",
  reward = "Eccellente!$B$BIl totem che ti creerò non è solo un simbolo del tuo rango di $C — ha anche altri poteri. Tra l'altro, può fare da catalizzatore per gli incantesimi. Sono sortilegi legati alla terra, e più crescerà la tua saggezza, più poteri della terra avrai a disposizione.$B$BGli istruttori sapranno quando sarai $Gpronto:pronta; per una conoscenza più profonda.$B$BMa per ora, prendi questo totem della terra...",
  en_title = "Call of Earth",
  en_obj = "Bring the Rough Quartz to Canaga Earthcaller in the Valley of Trials.",
}
T[1519] = {
  title = "Il Richiamo della Terra",
  desc = "È giunto il momento, giovane $C. Il tuo corpo matura e si fa forte, e il tuo spirito resiste come la terra. Lo vedo dentro di te — possiedi già la saggezza.$B$BLa terra guida il nostro popolo e ci parla, come col tempo parlerà a te. Ma prima devi essere $Gmesso:messa; alla prova. Se sei $Gpronto:pronta;, vedrai cose che solo quelli della nostra stirpe conoscono.$B$BCerca gli sciamani Bristleback nel loro burrone a est e prendi loro un unguento che usano nei rituali. Torna da me solo quando ne avrai abbastanza per la tua pozione.",
  obj = "Porta 2 applicazioni di Ritual Salve a Seer Ravenfeather a Camp Narache.",
  progress = "La terra è paziente e ti aspetterà finché non sarai $Gpronto:pronta;, perché sa che col tempo ogni cosa si erode e rinasce. È il ciclo delle cose. Le montagne diventano deserti. I fiumi diventano canyon. Fra tutti gli elementi, la terra è il più ostinato e il più saggio.$B$BPrima di ogni altra cosa devi imparare la pazienza e la resistenza. Ora la terra ti chiama perché sente che sei $Gpronto:pronta;. Se ci riuscirai, sarà per te una rinascita. Dopo, non potrai mai più tornare all'ignoranza.",
  reward = "Bene, $N. Se sei $Gtornato:tornata;, vuol dire che sei davvero $Gpronto:pronta; per il passo successivo.$B$BFra tutti gli elementi, la terra è il fondamento di ogni cosa. È la tua forza, la tua resistenza e la tua pazienza. La Madre Terra ti proteggerà, ma solo se le mostrerai il dovuto rispetto. È la base della vita e, se osserverai le sue leggi, acquisirai una saggezza più grande. Non dimenticare mai i segreti che ti confida.$B$BOra preparerò la tua sapta e, quando l'accetterai, davanti a te si aprirà un nuovo sentiero.",
  en_title = "Call of Earth",
  en_obj = "Bring 2 applications of Ritual Salve to Seer Ravenfeather in Camp Narache.",
}
T[1520] = {
  title = "Il Richiamo della Terra",
  desc = "La sapta è una bevanda creata per legare i nostri spiriti agli elementi. Infusa di magia, la pozione permette a chi ha la mente aperta di vedere gli elementi come nessuno li ha mai visti. Il tuo spirito resterà legato per sempre all'elemento per cui la sapta è stata creata, e solo pochi eletti della nostra stirpe conoscono i segreti per prepararla.$B$BLa sapta si beve sempre in un luogo sacro, e mai altrove.$B$BCerca il santuario degli sciamani a est di qui e bevila lì.",
  obj = "Trova Kodo Rock e bevi l'Earth Sapta.",
  reward = "Ah... $N... lieta è la terra di averti qui.$B$B$GUnito:Unita; nel corpo e nello spirito, andrai avanti sapendo che le montagne sono la tua forza, le pianure la tua pazienza e il mondo stesso la tua essenza.$B$BPer superare questo rito devi soltanto stare con umiltà davanti alla terra. Ma gli altri elementi non sono altrettanto tranquilli. Possono essere caotici e spesso violenti, ma tale è la natura degli elementi. Nature opposte che si contrastano: dovrai imparare a conoscerle a fondo.",
  en_title = "Call of Earth",
  en_obj = "Find Kodo Rock and drink the Earth Sapta.",
}
T[1521] = {
  title = "Il Richiamo della Terra",
  desc = "Prendi questo rough quartz e portalo a Seer Ravenfeather come prova del nostro incontro. Creerà per te un totem, e questo sassolino ne sarà il cuore. Per quanto possa sembrare piccolo, scoprirai che le dimensioni non contano e che anche le cose più minute possono sopravvivere alle montagne.$B$BSii paziente, $N. Resta forte. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con lei — rispettala, come lei rispetterà te.",
  obj = "Porta il Rough Quartz a Seer Ravenfeather a Camp Narache.",
  progress = "Saluti, $N. Non saresti $Gtornato:tornata; da me se non avessi portato a termine il tuo compito. Lascia che sia io la prima a darti il benvenuto, a pieno titolo, sul primo dei quattro sentieri che guideranno per sempre i tuoi viaggi.$B$BSe hai la pietra che la terra ti ha dato, ti consegnerò il totem che ti ha promesso. Altrimenti, provo pena per te. C'è molto di cui andare fieri quando ci si è dedicati completamente agli elementi.",
  reward = "Splendido.$B$BIl totem che creerò per te è più di un simbolo — ha poteri che vanno oltre. Per esempio, serve da catalizzatore per gli incantesimi legati alla terra e, man mano che la tua saggezza crescerà, avrai accesso a sempre più poteri della terra. Gli addestratori sparsi in tutto Kalimdor sapranno quando sarai $Gpronto:pronta; per conoscenze più profonde e, quando andrai da loro, te lo diranno.$B$BMa per ora, prendi questo totem della terra...",
  en_title = "Call of Earth",
  en_obj = "Bring the Rough Quartz to Seer Ravenfeather in Camp Narache.",
}
T[1522] = {
  title = "Il Richiamo del Fuoco",
  desc = "Il fuoco sia con te, mon. Vedo che sei già forte nelle vie della terra, e secondo me sei $Gpronto:pronta; per parlare con Kranal.$B$BKranal vive nelle Barrens, a nord del Crossroads. È forte nelle vie degli elementi e può insegnarti le vie del fuoco... se pensi di essere $Gpronto:pronta;.$B$BTrovarlo è facile, basta non andare troppo lontano — se vai troppo in là, ti ritrovi nelle terre degli elfi.",
  obj = "Trova Kranal Fiss nelle Barrens.",
  reward = "Hmmm, è stato Searn a mandarti da me, eh?$B$BBene, allora. Searn è sempre stato uno di cui fidarsi, quindi vuol dire che sei $Gpronto:pronta; per il prossimo sapta — il sapta del fuoco.$B$BTe lo leggo già negli occhi, quell'ardore, quel desiderio. Hai assaggiato il potere, e adesso sei $Gpronto:pronta; a prenderne ancora. Pazienza, $N. Ricorda cosa ti ha insegnato la terra. Il potere e la distruzione arriveranno senza fatica, ma tu dovrai sapere lo stesso quando fermare la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[1523] = {
  title = "Il Richiamo del Fuoco",
  desc = "Da molto tempo non sei più $Gstato messo:stata messa; alla prova, $N. Finora hai studiato con pazienza, ma è giunto il momento di imparare di più. Il momento di conoscere la distruzione... e il caos. Puoi comprendere l'elemento del fuoco, se sei $Gpronto:pronta; a pagarne il prezzo.$B$BCerca Kranal Fiss nelle Barrens. Vive in una piccola casa a nord del Crossroads, ma fa' attenzione: se arrivi alle terre degli elfi della notte, sei $Gandato:andata; troppo lontano.",
  obj = "Trova Kranal Fiss nelle Barrens.",
  reward = "Hmmm, è stato Narm a mandarti da me, eh?$B$BBene, allora. Narm è sempre stato uno di cui fidarsi, quindi vuol dire che sei $Gpronto:pronta; per il prossimo sapta — il sapta del fuoco.$B$BTe lo leggo già negli occhi, quell'ardore, quel desiderio. Hai assaggiato il potere, e adesso sei $Gpronto:pronta; a prenderne ancora. Pazienza, $N. Ricorda cosa ti ha insegnato la terra. Il potere e la distruzione arriveranno senza fatica, ma tu dovrai sapere lo stesso quando fermare la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[1524] = {
  title = "Il Richiamo del Fuoco",
  desc = "Sei abbastanza potente da impugnare il totem del fuoco, ma non per questo sei $Gpronto:pronta;.$B$BIn Durotar, lungo il Southfury River e prima del Great Sea, c'è un sentiero nascosto che sale a una delle vette più alte della regione. Arriva in cima e troverai uno dei nostri santuari sacri, sorvegliato da Telf Joolam — lo Shrine of the Dormant Flame.$B$BPorta a lui questa torcia — è il segno che stai cercando di domare il fuoco. Accendila al braciere del santuario, riportamela, e farò in modo che tu riceva il totem del fuoco.",
  obj = "Porta la Torch of the Dormant Flame a Telf Joolam in Durotar.",
  progress = "Salute, $N. Sei $Garrivato:arrivata; allo Shrine of the Dormant Flame. I segreti di questo luogo, e il potere che custodisce, li può scoprire solo chi conosce abbastanza le arti sciamaniche. Mi dispiace rimandarti indietro dopo tanta strada — del resto il viaggio fin quassù è tutt'altro che sicuro — ma il custode del santuario sono io, e non posso lasciare che chiunque se ne vada in giro qui.",
  reward = "Ah, errore mio, $N. Ti chiedo scusa. Non avevo visto che avevi la Torcia. Lieto di conoscerti.$B$BMolti avventurieri salgono fin qui a caccia di tesori perduti, o attirati dalla promessa di creature mistiche da uccidere, ma davanti a un santuario che sembra vuoto vengono rimandati indietro. Noi però conosciamo la verità, non è vero, $N?$B$BAi semplici membri dell'Orda questo santuario nasconde un segreto più grande. Per noi è sacro.",
  en_title = "Call of Fire",
  en_obj = "Bring the Torch of the Dormant Flame to Telf Joolam in Durotar.",
}
T[1525] = {
  title = "Il Richiamo del Fuoco",
  desc = "Ma non sei $Gvenuto:venuta; qui per una lezione di storia, vero? Sei qui per l'Eternal Flame e il totem del fuoco.$B$BPer prima cosa bisogna creare un sapta e legarti alla fiamma.$B$BSe mi porti due oggetti, il fire sapta te lo posso creare io. Il primo è il fire tar, una cosa semplice che di solito hanno con sé gli incantatori Razormane nelle Barrens orientali.$B$BIl secondo sarà più pericoloso: una reagent pouch di uno dei cultisti della Burning Blade. Stanno in una grotta sopra i burroni a nord-est di Razor Hill.",
  obj = "Porta 1 Fire Tar e 1 Reagent Pouch a Telf Joolam in Durotar.",
  progress = "Se riesci a trovare la reagent pouch e un po' di fire tar, di ingredienti per un sapta del fuoco ne ho abbastanza. In quelle borse i fanatici della Burning Blade tengono i componenti giusti per quasi tutti i loro incantesimi, e di solito c'è abbastanza di quello che mi serve da non dover andare a cercare altro molto più lontano.$B$BI sapta si fanno sempre con ingredienti strettamente legati ognuno al suo elemento. Il legame degli stregoni con il fuoco ci rende il lavoro più facile.",
  reward = "Questi vanno benissimo, $N.$B$BIl fuoco non è solo caos e distruzione — ricordalo bene. È anche vita, e creazione. Così sono legate fra loro tutte le cose. Le forze si oppongono, ma al tempo stesso l'una non può esistere senza l'altra. Si spengono a vicenda, ma si danno anche un senso. Ricordalo sempre.$B$BChi sa usare insieme diversi tipi di magia mostrerà non solo vera abilità, ma grande saggezza.",
  en_title = "Call of Fire",
  en_obj = "Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar.",
}
T[1526] = {
  title = "Il Richiamo del Fuoco",
  desc = "Il fire sapta è pronto, ed è giunto il momento di misurarti con la fiamma. Usa il sapta al santuario, poi sali in cima alla montagna e affronta la manifestazione che sta lassù. Non ti attaccherà finché non sarai $Gpronto:pronta;, ma si accorgerà che riesci a vederla.$B$BAbbattila in fretta, $N, perché più ci metterai a ucciderla, più diventerà potente. Quando l'avrai sconfitta, metti le sue glowing embers nel braciere e accendi la torcia.",
  obj = "Sconfiggi la Minor Manifestation of Fire e metti la Glowing Ember nel braciere in cima a Shrine of Eternal Flame.",
  progress = "Il braciere è alto più o meno un terzo di te e sembra un braciere qualunque, se non fosse per le iscrizioni lungo le aste lisce di metallo. Le intemperie non ci hanno lasciato alcun segno di usura, e la coppa in cima è fresca al tatto.",
  reward = "Appena ci metti dentro la brace, nella coppa si accende una fiamma incandescente. Senti gli effetti magici del sapta scorrerti nel corpo, e il fuoco danza a ritmo davanti a te.$B$BMetti la punta della torcia nel bacile, e in un attimo prende fuoco.",
  en_title = "Call of Fire",
  en_obj = "Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.",
}
T[1527] = {
  title = "Il Richiamo del Fuoco",
  desc = "Con la torcia ben stretta in mano, ti allontani dal braciere e guardi dall'alto Durotar. Il vento si alza e fa danzare con violenza la fiamma, e tu senti l'eccitazione agitarti lo spirito.$B$BTi incammini lungo il sentiero che torna nelle Barrens, per cercare Kranal Fiss.",
  obj = "Porta la Torch of Eternal Flame a Kranal Fiss nelle Barrens.",
  progress = "Sì, $N? Che cos'hai lì?",
  reward = "Non ho mai visto una torcia ardere luminosa quanto il tuo spirito, $N, e devi andarne $Gfiero:fiera;.$B$BSe continui per questa strada, gli elementi saranno ai tuoi ordini, e i nostri fratelli verranno da te a cercare guida e saggezza. Lascia che sia io il primo a farti le congratulazioni e a consegnarti il nuovo totem.",
  en_title = "Call of Fire",
  en_obj = "Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens.",
}
T[1528] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Nel tuo futuro c'è l'acqua, mon. Vedo che nelle vie del fuoco sei già forte, e secondo me sei $Gpronto:pronta; per parlare con Islen.$B$BIslen abita sulla costa delle Barrens. Se scendi a sud lungo il Southfury River non puoi mancarla — cerca il grande squalo! Lei è forte nelle vie degli elementi e ti può insegnare le vie dell'acqua... se pensi di essere $Gpronto:pronta;.$B$BTrovarla è facile, basta che non vai troppo a sud — sta appena oltre Ratchet.",
  obj = "Trova Islen Waterseer nelle Barrens.",
  reward = "Il vento ti corre incontro dall'orizzonte; la terra ti regge salda sotto i piedi; e il fuoco ti ha già scaldato lo spirito — direi che è ora che tu impari la purezza dell'acqua.$B$BIl cammino ti ha portato fin qui, e lo spirito ti darà la forza di spingerti ancora più avanti. Ma il primo passo tocca a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[1529] = {
  title = "Il Richiamo dell'Acqua",
  desc = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai studiato con pazienza, ma ora è tempo che tu impari di più: è tempo che tu impari la purezza dell'acqua.$B$BCerca Islen Waterseer nelle Barrens. Sta sulla costa orientale, a sud del Southfury River e di Ratchet: la troverai lì, nella sua capanna da pesca. Buona fortuna, $N.",
  obj = "Trova Islen Waterseer nelle Barrens.",
  reward = "Il vento ti corre incontro dall'orizzonte; la terra ti regge salda sotto i piedi; e il fuoco ti ha già scaldato lo spirito — direi che è ora che tu impari la purezza dell'acqua.$B$BIl cammino ti ha portato fin qui, e lo spirito ti darà la forza di spingerti ancora più avanti. Ma il primo passo tocca a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[1530] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Se c'è una lezione da imparare sull'acqua, è questa: l'acqua è rinascita.$B$BIl suo potere scorre, scava e purifica ogni genere di cosa. Scoprirai che niente guarisce e ristora come lei, ma solo quando è pura.$B$BQuando capirai che l'acqua inquinata può devastare tutto ciò che tocca, comprenderai che risorsa vitale sia.$B$BSe vuoi la water sapta, cerca Brine nel cuore delle Southern Barrens. I quilboar della zona non danno mai tregua alla sua casa.",
  obj = "Trova Brine nelle Southern Barrens.",
  reward = "Sì?$B$BMmm, credo di sapere cosa vuoi chiedermi: perché mai qualcuno dovrebbe vivere qui, nel cuore delle Barrens, senza nessuna protezione e con la minaccia dei quilboar tutto intorno? Be', ognuno fa quel che fa per le sue ragioni. La vera domanda è: cosa porta $Gun:un'; umile troll fin negli angoli più remoti delle Barrens, a parlare con una donna che chiaramente non si preoccupa affatto della propria sicurezza?$B$BScommetto che la risposta la sappiamo $Gentrambi:entrambe;.",
  en_title = "Call of Water",
  en_obj = "Find Brine in Southern Barrens.",
}
T[1531] = {
  title = "Il Richiamo dell'Aria",
  desc = "Adesso sì che fai progressi, mon. Sei $Gpronto:pronta; a dimostrarti $Gdegno:degna; del totem dell'aria, ma prima devi trovare Prate Cloudseer a Thousand Needles. Se la tratti con abbastanza rispetto, è disposta a dirti come prenderti il totem.$B$BScendi a sud attraverso le Barrens e, quando arrivi a Thousand Needles, gira a est. La trovi nascosta in una buca col suo fidanzato — ah ah, non dirle che la sto sfottendo — non la prenderebbe tanto bene.",
  obj = "Trova Prate Cloudseer a Thousand Needles.",
  reward = "Per ora ti darò quello che ti serve per concentrare gli incantesimi e invocare gli spiriti dell'aria. Prendi questo totem e, quando sarai $Gpronto:pronta;, torna ad addestrarti con me.",
  en_title = "Call of Air",
  en_obj = "Find Prate Cloudseer in Thousand Needles.",
}
T[1532] = {
  title = "Il Richiamo dell'Aria",
  desc = "I venti di Kalimdor ti corrono incontro, e sarai $Gcontato:contata; fra $Gi nostri fratelli più potenti:le nostre sorelle più potenti;. Sono fiero di vederti $Garrivato:arrivata; fin qui, con un futuro così promettente davanti a te.$B$BL'aria è un elemento difficile da controllare, ma confido che le tue capacità supereranno qualunque ostacolo ti troverai davanti.$B$BScendi fino all'estremo sud delle Barrens ed entra a Thousand Needles. Lì, molto a est, troverai Prate Cloudseer, che ti insegnerà altro.",
  obj = "Trova Prate Cloudseer a Thousand Needles.",
  reward = "Per ora ti darò quello che ti serve per concentrare gli incantesimi e invocare gli spiriti dell'aria. Prendi questo totem, e quando sarai $Gpronto:pronta; torna da me: ci alleneremo ancora.",
  en_title = "Call of Air",
  en_obj = "Find Prate Cloudseer in Thousand Needles.",
}
T[1534] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Prendi questa borraccia e inoltrati nella foresta rigogliosa che gli elfi della notte chiamano Ashenvale, molto a nord delle Barrens.$B$BAppena $Gentrato:entrata; nella foresta, dirigiti a ovest. Lungo le montagne che dividono Stonetalon da Ashenvale, oltre il Lake Mystral, troverai un luogo sacro: le Ruins of Stardust. In mezzo al lago c'è una piccola fontana.$B$BPortami un campione dell'acqua della fontana: sarà l'ultimo componente che ti serve, prima che ti rimandi da Islen.",
  obj = "Riempi l'Empty Blue Waterskin alle Ruins of Stardust ad Ashenvale e torna da Brine nelle Barrens.",
  progress = "Hai già preso l'acqua, $N? Si racconta che a proteggere le rovine ci fossero grandi creature della natura che non amano le visite, ma potrebbero anche essere leggende per spaventare i nemici degli elfi della notte.$B$BComunque sia, fai attenzione.",
  reward = "Magnifico, $N. Ora che hai raccolto tutti e tre i campioni, posso preparare per te una fiala dell'acqua più pura che una creatura vivente possa trovare. Servirà nei prossimi passi del tuo rito di passaggio.$B$BSono felice di contarti fra i nostri, $N. Fai onore a ogni $C, e non vedo l'ora di sentir parlare delle tue imprese.",
  en_title = "Call of Water",
  en_obj = "Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens.",
}
T[1535] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Per arrivare a capire e ricevere da me la sapta, devi cercare soltanto l'acqua nelle sue forme più pure. Mentre raccogli i campioni, guardati intorno. Nota le creature che dall'acqua dipendono e che la difendono. Guarda cosa fa alle foreste e ai deserti. Osserva come la stessa sostanza che sostiene la vita costringa le creature a toglierla.$B$BCominceremo con un compito semplice: sotto la mia capanna c'è una pozza di questo prezioso liquido. Riempi questa borraccia e torna da me.",
  obj = "Riempi l'Empty Brown Waterskin alla pozza sotto la capanna di Brine e riportala a lei nelle Barrens.",
  progress = "Sono quasi pronta ad affidarti gli altri compiti. Hai già riempito la borraccia?$B$BSo quanto i quilboar possano essere protettivi: per loro anche una fonte così piccola è un tesoro immenso. Basta che sulle Barrens cada la pioggia più leggera, e fanno grandi banchetti. Per la loro specie l'acqua è sacra proprio perché ce n'è così poca. Capisci?",
  reward = "Pensavo che potesse scorrere del sangue, se avessi provato a prendere l'acqua della pozza. Peccato che i quilboar non capiscano che tutti gli esseri viventi sono legati fra loro; che con la loro avidità non fanno che prolungare il dolore e la sofferenza del loro popolo. Quante cose potrebbero ottenere, se mettessero da parte le divergenze e i loro clan si unissero.$B$BUn peccato, lo ripeto, ma con ogni probabilità una fortuna per le altre razze delle Barrens.",
  en_title = "Call of Water",
  en_obj = "Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens.",
}
T[1536] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Tanto tempo fa ho seguito alcuni compagni nelle Hillsbrad Foothills. Abbiamo tenuto testa a certi umani tenaci che vivono da quelle parti e siamo finiti in una cittadina caduta in mano ai Forsaken: Tarren Mill.$B$BLì ho trovato una cosa molto strana: in mezzo al paese c'era un piccolo pozzo d'acqua fresca di sorgente. Non sono sicura che quegli abitanti appestati ne capiscano davvero il valore — è una piccola reliquia sacra in un mare profano.$B$BPortami un campione di quell'acqua in questa borraccia.",
  obj = "Riempi l'Empty Red Waterskin al pozzo di Tarren Mill e torna da Brine nelle Barrens.",
  progress = "Quel pozzo rimasto puro in mezzo al paese mi fa tornare in mente le storie che mi raccontavano quando ero più giovane, $N. Anche nei momenti di dolore e tristezza più grandi si può trovare un barlume di speranza, un piccolo simbolo intorno a cui stringersi. Ed è così che gli orchi vedono Thrall: contro ogni previsione è sopravvissuto, ed è arrivato a guidare il nostro popolo con la forza e con l'esempio.$B$BNon so se un altro orco abbia mai sofferto quanto lui, ma non so nemmeno se ce ne sia un altro forte quanto lui.",
  reward = "Bene, $N. Ti dedichi al compito che hai davanti e sai cercare quello che serve.$B$BMi manca solo un altro campione per preparare il reagente della tua sapta. Ne sarà contenta anche Islen.",
  en_title = "Call of Water",
  en_obj = "Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens.",
}
T[1558] = {
  title = "La Stonewrought Dam",
  desc = "Tutti i nani e gli gnomi vivono a Ironforge. Lì vicino c'è un posto che si chiama Loch Modan, dove i nani hanno costruito una diga ENORME. Dicono che sia una delle cose più grandi mai fatte da qualcuno. Wow!$B$BMi porteresti a Loch Modan a vedere la diga, per favore? Mi pare che sia la Stone... ehm... Stonewrench Dam? Stonewrought? È grande — questo è sicuro. Vorrei affacciarmi sulla grande cascata. Prometto che non mi sporgo troppo!",
  obj = "Porta l'orfano alla Stonewrought Dam a Loch Modan. Dovresti portarlo al centro della diga, così potrà affacciarsi sulla cascata gigante.",
  progress = "Siamo arrivati?",
  reward = "WOW — la diga era MOLTO più grande di come pensavo! Con tutta quell'acqua che scrosciava facevo fatica pure a sentirmi parlare! Ehi, secondo te l'acqua finirà mai? Accidenti, chissà cosa succederebbe se la diga si rompesse! WOW, che paura!$B$BGrazie di avermi portato a vedere la diga. Sei $Gstato:stata; molto gentile. Te l'avevo detto che non mi sarei sporto troppo!",
  en_title = "The Stonewrought Dam",
  en_obj = "Take the orphan to the Stonewrought Dam in Loch Modan.  You should take him to the middle of the dam so he can see out over the giant waterfall.",
}
T[1559] = {
  title = "Ricetta della Flash Bomb",
  reward = "Allora sei $Gun ingegnere:un'ingegnera;, eh? Be', visto che mi hai aiutato a mettere le mani su quelle perle, ecco la ricetta delle flash bombs.$B$BBuona fortuna, e occhio a non accecarti!",
  en_title = "Flash Bomb Recipe",
}
T[1560] = {
  title = "La Missione di Tooga",
  desc = "Mi sono proprio perso!$B$BMia moglie, Torta, mi ha mandato a prendere la cena, e da qualche parte devo aver sbagliato strada.$B$BMi faresti la gentilezza di riportarmi da Torta? Mi aspetta appena a sud dello Steamwheedle Port.",
  obj = "Mostra a Tooga la strada per tornare da sua moglie, Torta.",
  progress = "Dov'è finito Tooga?",
  reward = "Allora non ce l'ha fatta a ritrovare la strada da solo? Tipico.$B$BBe', direi che ti meriti qualcosa per il disturbo....",
}
T[1578] = {
  title = "Rifornire il Fronte",
  desc = "I montanari di Loch Modan se la vedono con i troggs, e hanno un bel po' da fare! Se vogliamo tenere a bada quei troggs, gli servono di continuo armature e armi nuove.$B$BÈ per questo che il mio collega Thorvald sta lì: cerca di tenere i montanari ben equipaggiati. Quindi, se tu forgiassi delle copper axes e delle copper chain belts e le portassi a Thorvald, te ne sarebbe grato, e magari condividerebbe perfino con te quello che sa.$B$BThorvald lo trovi nella torre di guardia meridionale di Loch Modan.",
  obj = "Porta 6 Copper Axes e 6 Copper Chain Belts a Thorvald nella torre di guardia meridionale di Loch Modan",
  progress = "Non ho tempo per le chiacchiere. Ti serve qualcosa da me?",
  reward = "Ah, scusami! Non avevo capito che eri qui per darci una mano a rifornire le nostre truppe. La roba che hai fatto ci sarà di grande aiuto!$B$BEcco i progetti di un'armatura. Spero che ti tornino utili.",
  en_title = "Supplying the Front",
  en_obj = "Bring 6 Copper Axes and 6 Copper Chain Belts to Thorvald in the southern guard tower of Loch Modan.",
}
T[1579] = {
  title = "Gaffer Jacks",
  desc = "Sono venuto ad Auberdine in cerca di tranquillità. Voglio inventare le mie invenzioni in pace, perché dopo una notte di bevute non sopporto tutto il chiasso di Ironforge!$B$BCosì mi sono imbarcato per Auberdine e durante il viaggio ho bevuto un tantino troppo. Mi è caduta in mare la scatola di Gaffer Jacks! Mi servono i miei Gaffer Jacks!$B$BNon so di preciso dove mi sono caduti, ma se provi a pescarli nell'oceano, magari ti va bene...",
  obj = "Porta 8 Gaffer Jacks a Wizbang Cranktoggle ad Auberdine.",
  progress = "Hai trovato i miei Gaffer Jacks, $N? Senza i miei Gaffer Jacks non posso accordare i pioli stintle!",
  reward = "Non ci posso credere, li hai trovati! Devi essere $Gil:la; $R più $Gfortunato:fortunata; di Kalimdor!",
  en_title = "Gaffer Jacks",
  en_obj = "Bring 8 Gaffer Jacks to Wizbang Cranktoggle in Auberdine.",
}
T[1580] = {
  title = "Electropellers",
  desc = "Che hai fortuna lo sappiamo, ma... quanta ne hai davvero, $N?$B$BUna notte vagavo per le strade di Darkshore. Cercavo un bel fiume o un lago per provare il mio nuovo richiamo per anatre semovente ed esplosivo, e credo di essere stato un po' brillo... perché sono svenuto e mi sono risvegliato ore dopo ad Auberdine. Avevo i capelli bruciacchiati e la borsa degli electropellers era sparita! Devono essermi caduti in acqua!$B$BMi servono quegli electropellers! Magari riesci a ripescarli in qualche lago o torrente di Darkshore...",
  obj = "Porta 12 Electropellers a Wizbang Cranktoggle ad Auberdine.",
  progress = "Hai trovato degli electropellers? Mi servono per andare avanti con le ricerche sui richiami per anatre...",
  reward = "Non ci posso credere! Li hai trovati! Sei $Gil miglior pescatore:la miglior pescatrice; che abbia mai visto!$B$BGrazie, $N. Ecco, prendi questi. Sei così $Gbravo:brava; che probabilmente non ti servono, ma ti aiuteranno a pescare.",
  en_title = "Electropellers",
  en_obj = "Bring 12 Electropellers to Wizbang Cranktoggle in Auberdine.",
}
T[1581] = {
  title = "Elisir per i Bladeleafs",
  desc = "Il nostro negozio di erbe e alchimia va a gonfie vele, ma mio marito passa tanto di quel tempo a mescolare pozioni che per noi due non resta mai un momento.$B$BCi daresti una mano?$B$BPortami una scorta di elisir già pronti e farò volentieri uno scambio con te. Ho delle erbe rare che potrebbero tornarti utili.",
  obj = "Porta 6 Elixirs of Lion's Strength e 2 Elixirs of Minor Defense a Syral Bladeleaf a Dolanaar.",
  progress = "Ciao, $N. Hai con te gli elisir da scambiare?",
  reward = "Sono ben mescolati. Lavori con grande cura, $N, e per un alchimista è una cosa importante.$B$BEcco le tue erbe, appena raccolte. Possa tu farne buon uso.",
  en_title = "Elixirs for the Bladeleafs",
  en_obj = "Bring 6 Elixirs of Lion's Strength and 2 Elixirs of Minor Defense to Syral Bladeleaf in Dolanaar.",
}
T[1582] = {
  title = "Moonglow Vest",
  desc = "Noi di Darnassus, specialmente noi artigiani, siamo molto indaffarati. I giovani avventurieri non vedono l'ora di mettersi alla prova nelle terre selvagge e hanno sempre bisogno di rifornimenti.$B$BSe mi aiuti a evadere gli ordini di articoli in cuoio, forse potrei insegnarti una tecnica avanzata di conciatura.",
  obj = "Porta 1 Embossed Leather Glove, 5 Embossed Leather Boots e 5 Embossed Leather Cloaks a Lotherias a Darnassus.",
  progress = "Salve, $N.",
  reward = "Sì, sono pezzi ben fatti. Hai una mano abile e un occhio attento ai dettagli. Come $Gconciatore:conciatrice; hai davanti un futuro promettente.$B$BEcco, $N. Lascia che ti mostri lo schema per realizzare il Moonglow Vest.",
  en_title = "Moonglow Vest",
  en_obj = "Bring 1 Embossed Leather Gloves, 5 Embossed Leather Boots and 5 Embossed Leather Cloaks to Lotherias in Darnassus.",
}
T[1598] = {
  title = "Il Tomo Rubato",
  desc = "Ehi, tu! $N, giusto?$B$BSpero tu sia $Gsicuro:sicura; di voler diventare $Guno:una; $Gstregone:strega;, perché se non sai cavartela, è facile che tu venga $Gtrascinato:trascinata; a fondo.$B$BIl compito di istruirti spetta a me, ma prima voglio accertarmi che tu sia abbastanza forte.$B$BUn novizio che studiava all'Abbazia è fuggito per unirsi alla Defias Brotherhood. Perché la cosa mi interessa? Be', ha rubato alcuni libri importanti.$B$BFra questi c'è proprio quello che da tempo volevo per me: Powers of the Void. Rubalo per me: lo tengono nascosto nella loro tenda nei Vigneti.",
  obj = "Recupera Powers of the Void per Drusilla La Salle.",
  progress = "Rubare il libro di persona avrebbe dato troppo nell'occhio. Che fortuna che sia stata proprio una delle loro pedine a fare il lavoro sporco al posto mio.",
  reward = "Eccellente... Non sono mai riuscita a mettere le mani su questo testo: era custodito in un'ala protetta della biblioteca, e aggirarmi da quelle parti avrebbe destato sospetti.$B$BBe', hai fatto un buon lavoro a procurartelo, e penso che sapresti tenere a bada un imp tutto tuo: non vedo perché non insegnarti a evocarne uno.",
  en_title = "The Stolen Tome",
  en_obj = "Retrieve the Powers of the Void for Drusilla La Salle.",
}
T[1618] = {
  title = "Equipaggiare Redridge",
  desc = "Non siamo solo noi nani a combattere. Anche i nostri alleati umani hanno il loro bel da fare!$B$BGli orchi blackrock attaccano Redridge periodicamente, e lì l'equipaggiamento non basta mai. Se gli dessi una mano, sono sicuro che il loro fabbro, Verner Osgood, ti insegnerebbe un paio di trucchi.",
  obj = "Tormus Deepforge vuole che tu porti 4 Runed Copper Belts e 4 Heavy Copper Mauls a Verner Osgood a Redridge.",
  progress = "Spero che tu porti buone notizie da Ironforge, perché non so più che pesci prendere!",
  reward = "Grazie, $N. Mi sarà di enorme aiuto. Fra gli orchi Blackrock che attaccano dallo Stonewatch Keep e gli gnolls di Redridge appostati sulle colline a nord, non faccio altro che riparare armature e forgiare armi nuove per le nostre truppe.$B$BCon le provviste che hai portato potrò tirare il fiato un attimo, e avrò abbastanza tempo per insegnarti qualcosa...",
  en_title = "Gearing Redridge",
  en_obj = "Tormus Deepforge  wants you to bring 4 Runed Copper Belts and 4 Heavy Copper Mauls to Verner Osgood in Redridge.",
}
T[1638] = {
  title = "L'Addestramento di un Guerriero",
  desc = "Hai dimostrato di essere $Gun guerriero competente:una guerriera competente;, $N, ma sei ancora giovane e hai molto da imparare.$B$BParla con Harry Burlguard — di solito lo trovi alla taverna Pig and Whistle, nell'Old Town of Stormwind. È un vecchio veterano e un buon maestro, e può insegnarti qualche mossa che ti terrà in vita più a lungo.",
  obj = "Parla con Harry Burlguard.",
  reward = "Ohò! Bevi qualcosa con me, $Gragazzo:ragazza;. Da fuori sembri $Gun duro:una dura;, ma vediamo se lo stomaco ti regge qualche boccale della roba più forte della Pig and Whistle!!$B$BO... eri $Gvenuto:venuta; per una lezione?",
  en_title = "A Warrior's Training",
  en_obj = "Speak with Harry Burlguard.",
}
T[1639] = {
  title = "Bartleby l'Ubriacone",
  desc = "Sì, posso insegnarti, ma prima voglio vedere che mosse conosci già.$B$BVedi quell'ubriacone laggiù in fondo al bancone? Bartleby? Voglio che tu gli prenda il boccale.$B$BAh, se conosci Bartleby, sai già che non te lo darà così, senza storie.",
  obj = "Parla con Bartleby.",
  reward = "Ehi, $Gdamerino:damina;! Che ci fa $Guno smorfioso:una smorfiosa; come te alla Pig and Whistle? $GAttento:Attenta; a non romperti un'unghia...",
  en_title = "Bartleby the Drunk",
  en_obj = "Speak with Bartleby.",
}
T[1640] = {
  title = "Batti Bartleby",
  desc = "Cosa vuoi?? Ma sei $Gpazzo:pazza;!$B$BSe vuoi questo boccale, dovrai strapparmelo dalle dita fredde e morte...",
  obj = "Batti Bartleby, poi parlagli.",
  progress = "Se vuoi questo boccale, dovrai strapparmelo dalle dita fredde e morte...",
  reward = "Sei molto più $Gtosto:tosta; di quel che sembri!",
  en_title = "Beat Bartleby",
  en_obj = "Beat Bartleby, then talk to him.",
}
T[1641] = {
  title = "Il Tome of Divinity",
  reward = "Il mio compito, qui a Stormwind, è avviare i paladini sulla via di una virtù più grande, mentre si consacrano alla Luce e difendono Azeroth dallo Scourge e da altre minacce.$B$BOra è giunto il momento che tu muova il primo passo per diventare $Gdavvero virtuoso:davvero virtuosa;. Se accetti, ti darò un Libro della Divinità: studiandolo imparerai qualcosa sulla Luce e su quello che ci si aspetta da te. Se lo comprenderai, e se ne sarai capace, otterrai abilità superiori.",
  en_title = "The Tome of Divinity",
}
T[1642] = {
  title = "Il Tome of Divinity",
  desc = "Un paladino deve riflettere in ogni cosa la Luce che ci rende più forti. Per chi è della nostra specie, aspirare al divino non vuol dire voler diventare un dio — vuol dire voler essere buoni in tutto ciò che facciamo.$B$BAnche se in questi tempi duri sei $Gchiamato:chiamata; a colpire il male, non dimenticare che a distinguerti davvero dai cittadini di Azeroth sarà l'aiuto che dai agli altri. Compassione, pazienza, coraggio — per un paladino contano quanto la forza in battaglia.$B$BImparalo bene, e non scordarlo mai.",
  obj = "Parla con Duthorian Rall a Stormwind.",
  reward = "Rieccoti, $N. Come vanno i tuoi studi sul Tome of Divinity?$B$BAllora dovresti essere $Gpronto:pronta; a metterti alla prova. In città e nelle nostre terre c'è sempre qualcosa da fare; atti di compassione e di comprensione; gente che ha bisogno di aiuto; creature da uccidere.$B$BSe hai la pazienza di aiutare gli altri, soprattutto i meno fortunati, dimostri di essere $Gun servitore:una servitrice; della Luce, e di avere una mente salda.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1643] = {
  title = "Il Tome of Divinity",
  desc = "Allora, $N, il tuo compito è trovare qui a Stormwind qualcuno che abbia bisogno di aiuto. Qualcuno puro di cuore e di intenzioni: magari una persona che aiuta gli altri, o forse una che ha bisogno di una guida. Comunque sia, deve avere intenzioni nobili e contare sulla tua gentilezza.$B$BFallo e, quando avrai finito, torna da me. Allora parleremo ancora del tuo cammino e di cosa vuol dire essere un paladino della Luce.",
  obj = "Cerca Stephanie Turner in Trade District of Stormwind.",
  reward = "Oh, ciao, tesoro. Come vanno le tue avventure? Oh, sono proprio contenta di sentire che va tutto bene.$B$BOh, io? Grazie di avermelo chiesto — tutto sommato sto bene.$B$BCon tutti questi mercanti in più, di questi tempi la gente è un po' meno disposta a separarsi da cuoio e stoffa, e così fare i vestiti per i bambini dell'orfanotrofio è diventato più difficile, ma ce la caveremo. Quando dico \"noi\" parlo di me e di mio marito, che è su a Ironforge a cercare aiuto fra i cittadini.",
  en_title = "The Tome of Divinity",
  en_obj = "Search the Trade District of Stormwind for Stephanie Turner.",
}
T[1644] = {
  title = "Il Tome of Divinity",
  desc = "Poveri cari, la maggior parte ha perso la famiglia negli attacchi dello Scourge di questi ultimi dieci anni.$B$BMio marito John raccoglie i materiali per cucire camicie e pantaloni ai bambini, ma io non ho avuto neanche il tempo di mettermi al lavoro: sono stata troppo occupata a sfamarli e a dar loro un tetto sopra la testa.$B$BCome dici? Saresti $Gdisposto:disposta; ad aiutarmi? Oh, sia ringraziata la Luce, e grazie anche a te, $N.$B$BSe mi portassi un po' di linen cloth per cucire i vestiti dei bambini, mi saresti di grandissimo aiuto.",
  obj = "Porta 10 Linen Cloth a Stephanie Turner a Stormwind.",
  progress = "Spero che il mio John abbia più fortuna a Ironforge. Andare laggiù non gli piace per niente, perché io e i bambini restiamo da soli, ma sa che bisogna farlo. Ha un cuore tanto buono.$B$BCi sono stati anni più facili di altri, ma questo è stato di gran lunga il più duro. Sembra quasi che qualcosa, nell'aria, annunci un grande cambiamento. Ma chi può dirlo?",
  reward = "Grazie, $N, grazie infinite!$B$BI bambini saranno così contenti, e a me hai fatto risparmiare un mucchio di tempo. Ora potrò pensare alle altre cose di cui hanno bisogno i piccoli, e spero che il mio John possa tornare a casa prima del previsto.$B$BGrazie ancora, $N. Sapevo di poter contare sulla carità degli altri. Che la Luce sia con te.",
  en_title = "The Tome of Divinity",
  en_obj = "Bring 10 Linen Cloth to Stephanie Turner in Stormwind.",
}
T[1645] = {
  title = "Il Tome of Divinity",
  reward = "Piacere di conoscerti, $N. Io sono qui per guidare i paladini verso una virtù più alta, mentre si votano alla Luce e difendono Azeroth dallo Scourge e da altre minacce.$B$BPer te è arrivato il momento di muovere il primo passo per diventare $Gvirtuoso:virtuosa; davvero. Se accetti, ti darò un Libro della Divinità: studialo, e imparerai qualcosa sulla Luce e su quello che ci si aspetta da te. Se lo capirai, e se ne sarai capace, otterrai abilità superiori.",
  en_title = "The Tome of Divinity",
}
T[1646] = {
  title = "Il Tome of Divinity",
  desc = "In ogni cosa che fa, un paladino deve riflettere la Luce che integra la nostra forza. Per chi è della nostra specie, aspirare al divino non vuol dire voler diventare un dio — vuol dire sforzarsi di essere buoni in tutto ciò che si fa.$B$BIn tempi duri come questi sei $Gchiamato:chiamata; a colpire il male, ma ricorda sempre che a distinguerti davvero dai cittadini di Azeroth sarà l'aiuto che dai agli altri. Compassione, pazienza, coraggio — per un paladino contano quanto la forza in battaglia.$B$BSappilo bene, e non scordarlo mai.",
  obj = "Parla con Tiza Battleforge a Ironforge.",
  reward = "$GBentornato:Bentornata;, $N. Hai dedicato un po' di tempo al libro, spero?$B$BAllora dovresti essere $Gpronto:pronta; a metterti alla prova. In tutta la città e nelle nostre terre c'è sempre qualcosa da fare; atti di compassione e comprensione; gente che ha bisogno d'aiuto; creature da uccidere.$B$BSe saprai dimostrare la pazienza di aiutare gli altri, soprattutto i meno fortunati, avrai provato di essere $Gun servitore:una servitrice; della Luce e $Gsano:sana; di mente.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[1647] = {
  title = "Il Tome of Divinity",
  desc = "Allora, $N, ecco il tuo compito: trova qui a Ironforge qualcuno che abbia bisogno d'aiuto. Qualcuno puro di cuore e di intenzioni. Magari qualcuno che aiuta gli altri. Magari qualcuno che ha bisogno di una guida. Comunque sia, deve avere scopi nobili e contare sulla tua gentilezza.$B$BQuando avrai finito, torna da me: parleremo ancora del tuo cammino e di cosa vuol dire essere un paladino della Luce. Ti aspetterò qui nel tempio. Ci saranno anche altri paladini che avranno bisogno della mia guida.",
  obj = "Cerca John Turner nell'anello esterno di Ironforge.",
  reward = "L'ORFANOTROFIO DI STOR... oh, perdonami, non volevo urlarti addosso, $Gsignore:signorina;.$B$BSono John Turner. Come va?$B$BBene, bene, mi fa piacere sentire che te la passi bene. Io ho già sulle spalle una lunga giornata di lavoro, e mia moglie mi manca da morire, ma è il prezzo da pagare quando ci sono bocche da sfamare e schiene da vestire.",
  en_title = "The Tome of Divinity",
  en_obj = "Search the outer ring of Ironforge for John Turner.",
}
T[1648] = {
  title = "Il Tome of Divinity",
  desc = "Io e mia moglie mandiamo avanti un orfanotrofio a Stormwind, soprattutto per i bambini che nell'ultimo decennio hanno perso i genitori negli attacchi dello Scourge. Più o meno ogni mese vengo a Ironforge per cercare di raccogliere altre provviste dai cittadini di qui, e parlo con i vari gruppi per capire se possono fare qualcosa per noi.$B$BStavolta il viaggio è andato avanti con una lentezza straziante, e non ha reso granché.$B$BSe solo trovassi ancora un po' di lino perché mia moglie ci cucia dei vestiti, potrei finalmente spedire un carico a casa.",
  obj = "Porta 10 pezzi di Linen Cloth a John Turner a Ironforge.",
  progress = "Con tutti gli artigiani che sono arrivati qui e in tutta Azeroth, resta meno materiale per vestire i bambini del nostro orfanotrofio. È molto nobile da parte tua, $N, aiutarmi a raccogliere il lino perché mia moglie possa cucire loro abiti nuovi. Grazie.$B$BSpero di tornare presto a casa da mia moglie.",
  reward = "È davvero splendido da parte tua, $N. Grazie ancora.$B$BSei $Gun uomo:una donna; nobile, a fare questo per me. Non mi stupisce che tu abbia scelto di seguire la Luce. Vorrei poterti ripagare in qualche modo per tutto quello che hai fatto... come dici? Che era il minimo che potessi fare? Visto? È proprio questo che intendo, $N, nobile fino alla fine.$B$BSta' $Gattento:attenta;, e la Luce ti protegga nei tuoi viaggi.",
  en_title = "The Tome of Divinity",
  en_obj = "Bring 10 Linen Cloth to John Turner in Ironforge.",
}
T[1649] = {
  title = "Il Tome of Valor",
  desc = "Il valore e tutte le virtù che lo accompagnano sono come minerali rari: quando li trovi devi averne cura, perché sono preziosi, ma devi anche prenderti il tempo di estrarli... di raffinarli. Mescolati nel modo giusto, danno una lega robusta, che a volte non si spezza nemmeno sotto i colpi più potenti.$B$BQuesta forza, la tua fede, il tuo coraggio, va messa alla prova. Devi imparare a non perdere mai la fede e capire che con il potere della Luce puoi vincere ostacoli che quasi nessun altro riesce a superare.",
  obj = "Parla con Duthorian Rall a Stormwind.",
  reward = "Ah, vuoi chiedermi una prova di valore. Splendido.$B$BIn città e nelle terre qui intorno ci sono molti compiti difficili, e $Gun uomo:una donna; con le tue capacità farebbe comodo.$B$BNon è una prova da prendere alla leggera, $N. Come tante cose sul nostro cammino, potrebbe costarci la vita. La Chiesa vuole sempre rafforzare i suoi ranghi, ma sa quali sacrifici servono per essere certa che i paladini al suo servizio ne siano degni.$B$BSei $Gpronto:pronta;?",
  en_title = "The Tome of Valor",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1650] = {
  title = "Il Tome of Valor",
  desc = "Bene! Non esiti, segno chiaro che sei $Gpronto:pronta; e $Gdesideroso:desiderosa; di metterti alla prova. E così sia.$B$BProprio in fondo alla Longshore di Westfall c'è una piccola casa che guarda sull'oceano. Ci vive una coppia, gli Stilwells. Jordan, un fabbro straordinario, è andato per qualche tempo a Ironforge a incontrare i nani. Ma così sua moglie, Daphne, è rimasta sola, senza nessuno a proteggerla.$B$BDai rapporti pare che i Defias abbiano quasi preso il controllo della zona, e Daphne potrebbe aver bisogno di qualcuno che la protegga da quei furfanti. Va' laggiù.",
  obj = "Trova Daphne Stilwell a Westfall.",
  reward = "Ciao, $N. Con tutta quell'armatura e quell'arma, immagino che o sei qui per provare a prenderti la mia terra, o la Chiesa ha finalmente mandato qualcuno a proteggermi finché il mio Jordan è via.$B$BBe', lascia che mi presenti: sono Daphne Stilwell. Piacere.$B$BE non sei $Garrivato:arrivata; troppo tardi... Dall'alba ho fatto fuori solo una mezza dozzina di quella feccia. Ci hanno messo un po' a girare la curva lassù, ma ti avranno visto venire, quindi saranno qui a momenti.",
  en_title = "The Tome of Valor",
  en_obj = "Find Daphne Stilwell in Westfall.",
}
T[1651] = {
  title = "Il Tome of Valor",
  desc = "Torneranno presto, ci scommetto, quindi preparati.$B$BIn casa ho un fucile. Lo prendo e sarò pronta a darti una mano, ma per lo più dovrai cavartela $Gda solo:da sola;.$B$BNon ho idea di quanti ne manderanno, ma di sicuro saranno più dei pochi di prima.$B$BChiedi alla Luce tutte le benedizioni che puoi, perché... hai sentito? Credo che stiano arrivando.$B$BLi affronteremo qui, accanto alla casa!",
  obj = "Difendi Daphne Stilwell dall'attacco dei Defias.$B$BPerché l'impresa abbia successo, nessuno dei vostri spiriti deve abbandonare le sue spoglie mortali.$B$BUna volta $Griuscito:riuscita;, parla di nuovo con Daphne Stilwell.",
  progress = "Li affronteremo qui, accanto alla casa!",
  reward = "Ce l'abbiamo fatta, $N! Grazie dell'aiuto. Là fuori sei $Gstato:stata; davvero $Gstraordinario:straordinaria;. Non avrei mai pensato che un paladino potesse tenere testa a così tanti nemici insieme.$B$BHai dimostrato un vero coraggio contro forze soverchianti.",
  en_title = "The Tome of Valor",
  en_obj = "Defend Daphne Stilwell from the Defias attack.$B$BNeither of your spirits must be released from their mortal coils if you wish to succeed.$B$BAfter you are successful, speak to Daphne Stilwell again.",
}
T[1652] = {
  title = "Il Tome of Valor",
  desc = "Ti prego, torna da Duthorian e digli che per ora sono al sicuro. Lo devo a te e alla Chiesa.$B$BLui manderà un messaggio a Ironforge perché il mio Jordan sappia che può stare tranquillo.$B$BOh, quanto mi manca mio marito. Non vedo l'ora che torni.",
  obj = "Parla con Duthorian Rall a Stormwind.",
  reward = "Ci rivediamo, $N, e noto che sei di ottimo umore.$B$BLa casa degli Stilwell sarà al sicuro ancora per un giorno, e dal tuo racconto capisco che i pericoli non sono mancati. Ben fatto.$B$BDaphne e Jordan hanno aiutato molto la Chiesa, e mandarti a proteggere la loro proprietà — e le loro stesse vite — era il minimo che potessimo fare.$B$BPer il tuo valore, avrai una ricompensa.",
  en_title = "The Tome of Valor",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1653] = {
  title = "La Prova della Rettitudine",
  desc = "Anzi, sono certo che Jordan vorrebbe ringraziarti di persona, e visto che mi serve un messaggero per fargli sapere che sua moglie è al sicuro, direi che sei la persona giusta.$B$BJordan doveva diventare un paladino della Luce, prima che la dedizione al mestiere del padre lo portasse su un'altra strada — conosce a fondo il nostro modo di vivere e lo consideriamo uno dei più fedeli fra noi.$B$BDovrebbe essere ancora a Ironforge — di giorno gli piace lavorare fuori dalle porte, pare per via dell'aria fresca di montagna.",
  obj = "Parla con Jordan Stilwell a Ironforge",
  reward = "Buongiorno, $N. La Luce è con te, immagino?$B$BCome? Ti ha mandato Duthorian!? Mia moglie, come sta? Sapevo che ci sarebbero stati guai se fossi partito. Ti prego, dimmi che sta... oh, grazie al cielo. Sono così contento che sia al sicuro. I Defias erano una minaccia ben prima di questi attacchi, ma ora i consiglieri del Re non possono più negarlo.$B$BCos'altro ti ha detto Duthorian?$B$BSei tu $Gquello:quella; che hanno mandato a proteggere mia moglie? Allora ti ringrazio di nuovo, $N. Non saprei immaginare una prova di valore migliore.",
  en_title = "The Test of Righteousness",
  en_obj = "Speak to Jordan Stilwell in Ironforge",
}
T[1654] = {
  title = "La Prova della Rettitudine",
  desc = "Vorrei darti una ricompensa: saresti $Gdisposto:disposta; ad accettarla? Non fraintendermi, la mia generosità dipende da quanto potrai essermi d'aiuto, ma un'alleanza del genere porterebbe un grande vantaggio a entrambi.$B$BForgerò per te un'arma degna di ciò che hai compiuto, un simbolo della Luce e dei paladini, ma dovrai procurarmi tu i materiali che mi servono. Ho già cominciato a prendere appunti su quello che serve; ora manca solo qualcuno abbastanza coraggioso e abile da recuperare il tutto. Che ne dici, $C?",
  obj = "Con l'aiuto di Jordan's Weapon Notes, trova della Whitestone Oak Lumber, il Bailor's Refined Ore Shipment, il Jordan's Smithing Hammer e una Kor Gem, e portali a Jordan Stilwell a Ironforge.",
  progress = "Gli oggetti che cerchi saranno difficili da ottenere, ma ti assicuro che l'arma che ti forgerò ne varrà la pena.$B$BSarà il miglior lavoro che abbia mai fatto, e solo un piccolo compenso per il servizio che mi hai reso.",
  reward = "Fantastico! Hai trovato tutto.$B$BCon questi non dovrei avere problemi a forgiarti un'arma grandiosa. A dire il vero ne ho i progetti da un po', solo che non ho mai avuto occasione di procurarmi i materiali. Grazie, $N.$B$BChe bello riavere il martello di mio padre... e una gemma Kor, non avrei mai pensato di vederne una con i miei occhi.",
  en_title = "The Test of Righteousness",
  en_obj = "Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge.",
}
T[1655] = {
  title = "La Spedizione di Bailor's Ore",
  desc = "Ach, mi hai fatto prendere un colpo, $Gragazzo:ragazza;! Non vedi che ero perso nei miei pensieri?$B$BCome dici? La spedizione di Jordan... per Ironforge. Ahhh, sì, so di cosa parli. I Mo'grosh ogres... sono stati loro a fregare il carico di minerale del mio vecchio amico. La carovana veniva qui dalle Wetlands ed è finita in un'imboscata. La guardia che era sopravvissuta all'attacco è morta solo pochi giorni fa — il guaritore non è arrivato in tempo.$B$BSe vuoi il carico, dovrai andare a nord-est, dall'altra parte del Loch. Dev'essere da qualche parte laggiù.",
  obj = "Porta la Jordan's Ore Shipment a Bailor Stonehand in Loch Modan.",
  progress = "Allora, trovato niente? Haha, quegli ogri non hanno ancora avuto la meglio su di te, eh?",
  reward = "Sì sì, è proprio questo. Ha! Se avessi saputo che saresti $Gandato:andata; davvero laggiù a fare a botte con qualcuno di quegli ogri, ti avrei dato una lista di cose da prendere, non solo questa. Ma non sei mica qui a fare affari per me, vero?$B$BI patti sono patti; Jordan voleva un carico della mia lega, e lo avrà.$B$BSalutalo da parte mia, e stai $Gattento:attenta;, $C.",
}
T[1657] = {
  title = "Appestare Southshore",
  desc = "Festeggia Hallow's End con stile... tormentando i nostri nemici di Southshore!$B$BPrendi una di queste bombe puzzolenti preparate apposta. È piena di un tanfo così nauseabondo che nessun umano — e nessuna bestia debole di volontà, se è per questo — riesce a sopportarlo. Dovrai lanciarla proprio nel cuore di Southshore perché faccia effetto, quindi preparati a combattere contro l'Alleanza!$B$BQuando avrai portato a termine questo compito... questo tributo alla nostra liberazione, torna da me!",
  obj = "Lancia tre Bombe Puzzolenti dei Forsaken nel cuore di Southshore, in Hillsbrad, e torna da Darkcaller Yanka al Wickerman Festival in Tirisfal Glade.",
  progress = "Hai consegnato il nostro \"regalo\" agli abitanti di Southshore?$B$B<Darkcaller Yanka ride malvagia.>",
  reward = "Ah, ben fatto! Spero che l'Alleanza soffochi con il lurido regalo che le abbiamo fatto, proprio come siamo stati costretti a soffocare noi, ridotti in schiavitù dallo Scourge!$B$BSei $Grimasto:rimasta; fedele agli ideali di Hallow's End, $N, e per questo ti rendo onore. Come premio extra, lascia che divida con te alcune delle mie leccornie di Hallow's End. Credo che saranno uno svago davvero piacevole!",
  en_title = "Stinking Up Southshore",
  en_obj = "Toss three Forsaken Stink Bombs into the heart of Southshore in Hillsbrad, and return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.",
}
T[1658] = {
  title = "Imbucarsi al Wickerman Festival",
  desc = "Mi servono persone coraggiose che salgano alla Radura di Tirisfal a dare un'occhiata al Wickerman Festival. Non te lo nascondo — lassù sarà pericoloso, e le guardie del festival saranno particolarmente feroci. Però dobbiamo sapere quanto è grande il festival quest'anno e quanti guai ci daranno i Forsaken durante l'Hallow's End.$B$BSe te la senti, vai a Tirisfal e perlustra il festival. Poi torna da me con le informazioni e ti assicuro che sarai $Gricompensato:ricompensata; per bene.",
  obj = "Trova il Wickerman Festival dei Forsaken nella Radura di Tirisfal. Poi torna da Sergeant Hartman a Southshore.",
  progress = "Sei $Gsalito:salita; alla Radura di Tirisfal a dare un'occhiata? Il festival di solito lo tengono vicino a Undercity...",
  reward = "Ben fatto, $N. Finché agli abominevoli Forsaken sarà permesso di infestare i resti di Lordaeron, il Wickerman Festival continuerà a dare problemi. Te lo dico io: NON è un omaggio degno di quel regno un tempo fiero...$B$BEcco qualche moneta per le riparazioni che potrebbero servirti e, nello spirito della festa, ci ho aggiunto qualche dolcetto che forse ti piacerà. Buona Hallow's End — facciamo in modo che sia il più sicura possibile, qui a Southshore.",
  en_title = "Crashing the Wickerman Festival (PvP)",
  en_obj = "Locate the Forsaken's Wickerman Festival in Tirisfal Glade.  Return to Sergeant Hartman in Southshore once you've done so.",
}
T[1661] = {
  title = "Il Tome of Nobility",
  desc = "Ti saluto ancora una volta, $N. Mai sono stato così fiero di chiamarti $Gfratello:sorella; — la tua dedizione fa onore a tutti noi.$B$BOra è giunto il momento di farti un grande dono. Ma sappi una cosa: per adesso te lo concedo liberamente; più avanti, quando i tempi lo permetteranno, diventerà una sfida molto più grande per tutti i paladini che sceglieranno di intraprendere la mia missione.$B$BTorna a parlare con me e ti concederò un grande favore.",
  obj = "Parla con Duthorian Rall a Stormwind.",
  reward = "Congratulazioni, e che la Luce ti protegga.",
}
T[1665] = {
  title = "Bartleby's Mug",
  desc = "Ok, ecco il mio boccale. Aspetta! Prima fammi finire quello che c'è dentro... ecco fatto.",
  obj = "Porta il Bartleby's Mug a Burlguard",
  progress = "Ho visto come hai affrontato Bartleby. Ben fatto! Gli hai preso il boccale?",
  reward = "Eccolo! Di sicuro non voleva separarsene, ma sei $Gstato:stata; convincente. Ben fatto.$B$BE ora, la tua lezione...",
  en_title = "Bartleby's Mug",
  en_obj = "Bring Bartleby's Mug to Burlguard",
}
T[1666] = {
  title = "Marshal Haggard",
  desc = "Qualche mossa l'hai imparata, ma ti servirebbe un'arma come si deve. Scommetto che, se ci parlassi, Marshal Haggard potrebbe aiutarti.$B$BMarshal Haggard vive in una villa all'Eastvale Lumber Camp, nell'Elwynn Forest. Adesso è in pensione, ma nella sua carriera ha messo da parte un sacco di equipaggiamento.$B$BDigli che ti mando io: con un po' di fortuna, avrà un'arma di scorta da darti.",
  obj = "Parla con Marshal Haggard.",
  reward = "Chi è? Burlguard, sei tu? Avvicinati un po', che gli occhi non sono più quelli di una volta. Vedendoti arrivare così, ti ho $Gscambiato:scambiata; per uno gnoll!",
  en_title = "Marshal Haggard",
  en_obj = "Speak with Marshal Haggard.",
}
T[1667] = {
  title = "Dead-tooth Jack",
  desc = "Ti manda Burlguard, eh? Sì, qualche arma di scorta ce l'ho, ma prima ho un compito per te...$B$BTempo fa mi ha imbrogliato un furfante dei Defias, Dead-tooth Jack. Era buio, lui aveva addosso una tabarda di Stormwind e io ho pensato che fosse Marshal Dughan. Mi ha detto che gli serviva il mio vecchio distintivo da Maresciallo di Stormwind, e io gliel'ho dato... poi si è messo a ridere ed è scappato prima che potessi acchiapparlo!$B$BRiportami il distintivo! Probabilmente Dead-tooth Jack lo tiene nascosto nel suo accampamento, a sud.",
  obj = "Recupera il Distintivo di Haggard dall'accampamento di Dead-tooth Jack e torna da Marshal Haggard.",
  progress = "Hai il mio distintivo? Non voglio neanche pensare a che guai potrebbe combinarci Dead-tooth Jack.",
  reward = "Ottimo, l'hai trovato! Temevo di averlo perso per sempre, e che i Defias lo usassero per farsi passare per un funzionario di Stormwind. Beh, grazie a te ora non succederà.$B$BEcco alcune armi che usavo quando ero Maresciallo. Le ho tenute in ottimo stato — scegli quella che vuoi!",
  en_title = "Dead-tooth Jack",
  en_obj = "Retrieve Haggard's Badge from Dead-tooth Jack's camp, and return to Marshal Haggard.",
}
T[1678] = {
  title = "Vejrek",
  desc = "Se vuoi salire di grado tra i guerrieri, dimostra di essere $Gun:una; $Gduro:dura;. Posso insegnarti mosse nuove, ma prima dimostrami che sai cavartela contro nemici veri.$B$BVejrek è il troll più tosto che troverai da queste parti, e sarà lui il tuo avversario da battere. Ha una capanna sulle colline appena a sud del Frostmane Hold.$B$BPortami la Vejrek's Head per dimostrarmi che hai fegato.",
  obj = "Porta Vejrek's Head a Muren Stormpike a Ironforge.",
  progress = "Sei $Gstato:stata; alla capanna di Vejrek, $N? È puzza di troll quella che ti sento addosso?",
  reward = "Quant'era brutto Vejrek, eh? Ben fatto, $N! Hai la stoffa giusta; ora cominciamo la lezione...$B$BForse non lo sai, ma per $Gun:una; $C una difesa solida è importantissima. È la difesa a $Gtenerlo:tenerla; in piedi davanti a nemici più possenti, ed è proprio ciò che serve ai tuoi alleati.",
  en_title = "Vejrek",
  en_obj = "Bring Vejrek's Head to Muren Stormpike in Ironforge.",
}
T[1679] = {
  title = "Muren Stormpike",
  desc = "Salve, $Gguerriero:guerriera;! Prometti molto bene, ma hai ancora qualche trucco da imparare, e Muren Stormpike è proprio il nano giusto per insegnarteli.$B$BTroverai Muren nell'Hall of Arms, nel Military Ward of Ironforge. Parlagli quando sarai $Gpronto:pronta; a scoprire cosa significa essere $Gun guerriero:una guerriera;.",
  obj = "Parla con Muren Stormpike.",
  reward = "Ah, $N. Ho sentito i guerrieri di Dun Morogh fare il tuo nome a destra e a manca. Spero che tu non abbia passato tutto il tempo nelle birrerie!",
  en_title = "Muren Stormpike",
  en_obj = "Speak with Muren Stormpike.",
}
T[1680] = {
  title = "Tormus Deepforge",
  desc = "Adesso che hai imparato qualche mossa, è il momento di procurarti un'arma come si deve. Parla con Tormus Deepforge: può fabbricartene una che ti piacerà di sicuro.$B$BTroverai Tormus qui a Ironforge, alla Great Forge.",
  obj = "Parla con Tormus Deepforge.",
  reward = "Ti ha mandato Muren, eh? Sì, posso farti una bella arma... ma prima devo chiederti un favore.$B$BNon preoccuparti. È parecchio pericoloso e potresti lasciarci la pelle; è proprio il genere di lavoro che piace a un guerriero.",
  en_title = "Tormus Deepforge",
  en_obj = "Speak with Tormus Deepforge.",
}
T[1681] = {
  title = "Ironband's Compound",
  desc = "Il mio mentore, Sturgy Ironband, aveva un presidio a sud dell'Helm's Bed Lake, nella parte orientale di Dun Morogh. Lì insegnava l'arte del fabbro, ed era il migliore.$B$BMa un giorno uno dei suoi allievi gli ha portato un carico di uno strano materiale. Master Ironband lo chiamava Umbral Ore e non vedeva l'ora di lavorarlo, ma poco dopo che il carico era arrivato... una banda di nani Dark Iron ha attaccato il presidio. Hanno ucciso tutti!$B$BEntra nel presidio di Ironband, $N, e vendica la morte del mio maestro. E portami il carico di Umbral Ore che l'ha causata.",
  obj = "Porta un carico di Umbral Ore a Tormus Deepforge a Ironforge.",
  progress = "Sei $Gentrato:entrata; nell'Ironband's Compound? Hai trovato l'Umbral Ore?",
  reward = "L'hai trovato! Ben fatto!$B$BSpero che tu abbia fatto fuori un bel po' di nani Dark Iron mentre lo cercavi. Temo che il presidio di Ironband non sarà l'ultimo posto dove li vedremo.$B$BMa grazie per il minerale, $N. Non vedo l'ora di lavorarlo e scoprirne le proprietà.",
  en_title = "Ironband's Compound",
  en_obj = "Bring a load of Umbral Ore to Tormus Deepforge in Ironforge.",
}
T[1682] = {
  title = "Armi di Ferro Grigio",
  reward = "Ecco qualche arma appena uscita dall'incudine, forgiata con il nuovo umbral ore che mi hai portato!$B$BPrego, $N, scegli pure!",
  en_title = "Grey Iron Weapons",
}
T[1683] = {
  title = "Vorlus Vilehoof",
  desc = "Prima che io possa istruirti, dovrai dimostrarmi la tua risolutezza.$B$BIl satiro Vorlus Vilehoof ha trovato uno dei nostri pozzi lunari più isolati, a sud-est del Ban'ethil Barrow Den. Ora ci sguazza dentro e ne contamina le acque pure con la sua sozzura.$B$BTrova Vorlus al pozzo lunare e distruggilo. Portami il suo corno come prova e inizierò il tuo addestramento avanzato da $Gguerriero:guerriera;.$B$BIl sentiero che porta al pozzo è ben nascosto, $N, ma se resterai $Gconcentrato:concentrata; e vigile lo troverai.",
  obj = "Porta l'Horn of Vorlus a Elanaria, a Darnassus.",
  progress = "Hai il corno, $N? Il nostro pozzo lunare è libero dall'immondo Vorlus?",
  reward = "Ben fatto, $N. Mi rallegra sapere che Vorlus è stato sconfitto e che il pozzo lunare è di nuovo puro, ed è bello vedere giovani guerrieri tanto desiderosi di proteggere dalla corruzione il nostro amato Teldrassil.$B$BOra cominciamo l'addestramento...",
  en_title = "Vorlus Vilehoof",
  en_obj = "Bring the Horn of Vorlus to Elanaria in Darnassus.",
}
T[1684] = {
  title = "Elanaria",
  desc = "Salute, $Gguerriero:guerriera;. La tua abilità cresce, ma nel tuo mestiere c'è molto più di quanto immagini. Per progredire ancora, presto dovrai trovare un maestro.$B$BLa guerriera Elanaria dimora a Darnassus, presso la Terrazza del Guerriero. Sarà lei a istruirti.",
  obj = "Parla con Elanaria.",
  reward = "Ti porgo i miei saluti, $N. Il tuo nome risuona forte a Darnassus, perché sei promettente. Ma presto vedremo se hai la forza di volontà per seguire la via $Gdel:della; $C.",
  en_title = "Elanaria",
  en_obj = "Speak with Elanaria.",
}
T[1685] = {
  title = "La Convocazione di Gakin",
  desc = "Non va sempre così? Ti ho cercato tutto il giorno senza trovarti, e adesso che non me l'aspetto, mi vieni incontro dritto dritto.$B$BHo perso fin troppo tempo a starti dietro, quindi non ti trattengo oltre. Il Maestro Gakin ti ha convocato per proseguire l'addestramento. Secondo me dovresti andare da lui il prima possibile.$B$BLo troverai nella cantina della taverna Slaughtered Lamb. A proposito, faresti meglio a non parlare in giro di quel posto. Non vogliamo che se ne sparga la voce.",
  obj = "Presentati da Gakin the Darkbinder in Mage Quarter of Stormwind.",
  reward = "Era ora che ti facessi vedere. Anche se forse avrei dovuto mandare a cercarti qualcuno più capace di Remen.$B$BPoco importa.$B$BSei $Grimasto:rimasta; troppo tempo senza addestramento, e uno stregone che non si allena difficilmente ha vita lunga.",
  en_title = "Gakin's Summons",
  en_obj = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1686] = {
  title = "La Shade of Elura",
  desc = "Hai imparato molto, $N. Ora ti forgeremo un'arma. Un'arma da guerriero.$B$BPer farlo, devi recarti a Darkshore.$B$BMolto tempo fa una nave si è schiantata contro gli scogli vicino al faro di Auberdine, spargendo sul fondale marino molte casse di elunite ore.$B$BPrima dovrai sconfiggere la guardiana dell'elunite, la Shade of Elura. Un tempo era il capitano della nave e ha maledetto se stessa, condannandosi a vagare negli abissi e a proteggere il carico per l'eternità. Abbattila, prendile il medaglione e recupera le casse di Elunite perduta.",
  obj = "Porta 8 carichi di Elunite Ore e il Medaglione di Elura a Elanaria, a Darnassus.",
  progress = "Hai sconfitto la Shade of Elura, $N? E hai con te l'elunite ore perduto?",
  reward = "Hai agito con coraggio, $N.$B$BHai donato alla Shade of Elura la pace che tanto meritava, e con l'elunite raccolta ti forgeremo un'arma pregevole.",
  en_title = "The Shade of Elura",
  en_obj = "Bring 8 loads of Elunite Ore and the Medallion of Elura to Elanaria in Darnassus.",
}
T[1687] = {
  title = "Il Faro Spettrale",
  desc = "A volte, la sera tardi, le governanti dell'orfanotrofio ci raccontano storie di paura. Sono UNA FORZA! Ce n'è una su un fantasma che infesta un faro a Westfall. Dicono che fosse un capitano pirata a cui altri pirati avevano rubato la nave. Wow!$B$BMi porteresti al faro di Westfall, per favore? Voglio vedere se il fantasma del capitano è lì! Prometto che ti sto vicino; non scappo via né niente!",
  obj = "Porta l'orfano a vedere il faro al largo della costa di Westfall.",
  progress = "Siamo arrivati?",
  reward = "WOW, era un fantasma vero! Troppo forte — non vedo l'ora di raccontarlo a tutti all'orfanotrofio. Captain Grayson... sembrava proprio un pirata! Da grande voglio fare anch'io il pirata fantasma!$B$BGrazie di avermi portato a Westfall, $N. Lo so che là fuori, nelle terre selvagge di Westfall, ci sono cose che fanno paura, e spero di non averti dato troppo fastidio. Sei $Gfortissimo:fortissima;!",
  en_title = "Spooky Lighthouse",
  en_obj = "Take the orphan to see the lighthouse off the coast of Westfall.$B",
}
T[1688] = {
  title = "Surena Caledon",
  desc = "Avevo un'allieva di nome Surena Caledon. Era proprio qui, dove sei tu adesso, desiderosa di imparare la magia degli stregoni, e di talento ne aveva non poco. Per di più era giovane e bella da vedere. Se solo me ne fossi accorto allora, quella sgualdrina traditrice!$B$BSe n'è scappata con uno dei Defias, Erlan Drudgemoor, la ladruncola. Perderla ha poca importanza, ma le avevo regalato un bloodstone choker che devo riavere.$B$BOrmai la sua vita per me non conta nulla. La troverai al Brackwell Pumpkin Patch. Recupera ciò che è mio.",
  obj = "Recupera il Surena's Choker per Gakin the Darkbinder a Stormwind.",
  progress = "Anche chi è più anziano e più saggio può perdere la testa per le lusinghe della giovinezza e della bellezza, $N. È un consiglio che faresti bene a ricordare per tutta la vita.",
  reward = "Surena aveva talento, ma non abbastanza da padroneggiare da sola la magia degli stregoni. È un peccato vedere sprecato un talento, ma a volte è necessario.$B$BSpero che quanto ho investito su di te dia risultati diversi.",
  en_title = "Surena Caledon",
  en_obj = "Retrieve Surena's Choker for Gakin the Darkbinder in Stormwind.",
}
T[1689] = {
  title = "Il Vincolo",
  desc = "Hai recuperato il mio girocollo e sconfitto Surena, dimostrando di essere capace almeno quanto lei.$B$BDetto questo, vedo che hai un disperato bisogno di addestramento. Sai gestire i flussi della magia, sì, ma essere stregoni è molto di più.$B$BTi insegnerò a comandare un voidwalker, ma prima devi richiamarne uno in un cerchio di evocazione e sottometterlo con tutte le armi — fisiche e magiche — a tua disposizione. Usa la magia di questo girocollo nel cerchio qui sotto.",
  obj = "Usando il Bloodstone Choker, evoca e sottometti un voidwalker, poi riporta il Bloodstone Choker a Gakin the Darkbinder a Stormwind.",
  progress = "Non posso insegnarti a controllare un voidwalker finché non ne avrai sopraffatto uno.",
  reward = "Te la sei cavata meglio di quanto mi aspettassi, $N, ma proprio come speravo. Ora puoi imparare a comandare il voidwalker che hai soggiogato, un alleato che ti sarà prezioso nelle prove che di certo ti attendono.$B$BPer ora non ho altro da insegnarti, ma con te sono ben lungi dall'aver finito, $N.",
  en_title = "The Binding",
  en_obj = "Using the Bloodstone Choker, summon and subdue a voidwalker, then return the Bloodstone Choker to Gakin the Darkbinder in Stormwind.",
}
T[1690] = {
  title = "Giustizia Wastewander",
  desc = "Ehi, tu! È arrivato il momento di dare una grossa mano alla Gadgetzan Water Company.$B$BI nomadi Wastewander nel deserto di Tanaris si sono presi quasi tutti i pozzi d'acqua! Se non possiamo usarli, le nostre riserve si prosciugheranno in un attimo. Vuoi entrare nelle nostre grazie? Allora ci aiuterai a fare giustizia di quei nomadi!$B$BVai a est, abbatti dieci Wastewander Bandits e Ladri e torna subito qui da me a fare rapporto. La giustizia non aspetta $Gnessun uomo:nessuna donna;... Goblin... bah, datti da fare e basta!",
  obj = "Abbatti 10 Wastewander Bandits e Ladri a est di Gadgetzan, poi torna a fare rapporto a Chief Engineer Bilgewhizzle.",
  progress = "Già di ritorno? Allora spero che tu sia $Griuscito:riuscita; a fare giustizia in stile goblin di quei Wastewander Bandits e Ladri, come ti avevo chiesto!",
  reward = "Questa sì che è efficienza! Ci hai aiutato a sfoltire i nomadi quanto basta per cominciare a pensare a come riprenderci quei pozzi.$B$BLa Gadgetzan Water Company ti ringrazia dell'aiuto, ma con quei nomadi schifosi siamo ben lontani dall'aver finito. Ascolta bene — ecco cosa ci serve adesso...",
}
T[1691] = {
  title = "Ancora Giustizia Wastewander",
  desc = "Adesso ci serve che affronti i ranghi più forti dei nomadi Wastewander. Finora hai lavorato bene, ma se vogliamo riprenderci quei pozzi d'acqua, è logico avere contro meno nomadi possibile!$B$BStavolta devi abbattere i loro ladri, gli assassini e i maghi dell'ombra: li troverai a est e a sud-est di qui.$B$BNon ti mentirò — è brutta gente. Però fallo per noi, e saremo sulla buona strada per riprenderci quello che è nostro di diritto!",
  obj = "Abbatti 10 Wastewander Shadow Mages, 8 Wastewander Rogues e 6 Wastewander Assassins per Chief Engineer Bilgewhizzle a Gadgetzan.",
  progress = "Allora, sei $Griuscito:riuscita; a far fuori quei nomadi come ti avevo chiesto? La Gadgetzan Water Company sta facendo i suoi piani e conta sul tuo successo! Non deluderci, eh...",
  reward = "Lavoro di prim'ordine, $N... di prim'ordine! Hai sfoltito i nomadi al punto che all'attacco possiamo passare noi!$B$BSe non l'hai già fatto, parla con Spigot Operator Luglunket, qui accanto: paga una ricompensa per ogni borraccia d'acqua Wastewander che avrai trovato mentre facevi giustizia di quei nomadi!",
}
T[1692] = {
  title = "Fabbro Mathiel",
  desc = "Ho messo in una cassa l'elunite che hai raccolto. Portala al fabbro Mathiel: ti forgerà un'arma d'elunite.$B$BMathiel si trova a sud, dall'altra parte dell'edificio.",
  obj = "Porta la Case of Elunite al Fabbro Mathiel.",
  progress = "Saluti, giovane $C. In che modo la mia arte può esserti utile?",
  reward = "Ah, elunite ore. È un ottimo metallo da lavorare, perché lo ha benedetto la dea Elune in persona. Sarà un onore usarlo per forgiare armi.$B$BTi prego di attendere mentre lavoro...",
  en_title = "Smith Mathiel",
  en_obj = "Bring the Case of Elunite to Smith Mathiel. ",
}
T[1693] = {
  title = "Armi di Elunite",
  reward = "$N, ho forgiato queste armi con l'elunite che mi hai portato. Ti prego, prendi quella che fa più al caso tuo.$B$BE devo ringraziarti. Lavorare l'elunite è per me un onore e insieme un piacere.",
  en_title = "Weapons of Elunite",
}
T[1698] = {
  title = "Yorus Barleybrew",
  desc = "Yorus Barleybrew ha sfidato tutti i guerrieri capaci dell'Alleanza. Aspetta alla Lakeshire Inn, a Redridge, e promette una grande ricompensa a chi riuscirà a superare la sua prova.",
  obj = "Parla con Yorus Barleybrew.",
  reward = "Ah! Allora hai sentito della mia sfida, eh?$B$BBe', siediti e ascolta. Versati un bicchiere e goditelo... perché potrebbe essere l'ultimo.",
  en_title = "Yorus Barleybrew",
  en_obj = "Speak with Yorus Barleybrew.",
}
T[1699] = {
  title = "La Corsa di Rethban",
  desc = "Io la chiamo la Corsa di Rethban. Per superare la prova basta entrare nelle Rethban Caverns, arrivare al primo bivio e tornare qui. Facile! Solo che c'è qualche intoppo...$B$BHai un'ora di tempo per tornare.$B$BLungo la strada ci sono mucchi e mucchi di Redridge Gnolls.$B$BE prima di partire devi farti una sorsata della bevanda tipica della mia famiglia: la Barleybrew Scalder!$B$BAllora, che ne dici? Le Rethban Caverns sono sulle colline a nord di Lakeshire. Sei $Gpronto:pronta; ad affrontare la Corsa di Rethban?",
  obj = "Entra in Rethban Caverns, raggiungi il primo bivio e torna da Yorus Barleybrew entro il tempo previsto.$B$BNon devi morire né liberare lo spirito.",
  progress = "Il tempo corre, $N. Io al posto tuo mi darei una mossa...",
  reward = "Ce l'hai fatta! Ben fatto! Hip hip urrà per $N!",
  en_title = "The Rethban Gauntlet",
  en_obj = "Enter the Rethban Caverns, reach the first fork, and return to Yorus Barleybrew within the time allowed.$B$BYou must not die and release your spirit.",
}
T[1700] = {
  title = "Grimand Elmore",
  desc = "Ho ricopiato i miei appunti sulle tecniche che ho imparato lavorando alla tua armatura, e bisogna che arrivino a Grimand Elmore. Lo trovi qui nel Dwarven District, nella bottega dell'armaiolo.$B$BE quando glieli dai, preparati a schivare. Va tremendamente fiero della sua abilità, e l'idea di imparare qualcosa da me non gli andrà giù...",
  obj = "Porta il Furen's Notes a Grimand Elmore.",
  progress = "Salve, e $Gben trovato:ben trovata;. In cosa posso aiutarti?",
  reward = "Li ha scritti Furen? Come osa! Tutto quello che sa gliel'ho insegnato io, insomma! Solo l'idea che lui possa insegnare qualcosa a me è uno scandalo! Uno scandalo!$B$BHm... però nei suoi appunti c'è qualcosa che vorrei provare...",
  en_title = "Grimand Elmore",
  en_obj = "Bring Furen's Notes to Grimand Elmore.",
}
T[1701] = {
  title = "Maglia Temprata nel Fuoco",
  desc = "Allora, ti ho dato un bello scudo, ma non dobbiamo mica fermarci qui. Conosco i segreti per fabbricare armature di maglia durissime. Non è facile e servono materiali rarissimi, ma se sei $Gdisposto:disposta; a sgobbare, te ne forgerò una.$B$BChe ne dici, $N? Se sei $Gpronto:pronta; alla sfida, ti darò una lista delle cose da procurarti e di dove trovarle.",
  obj = "Raccogli i materiali che ti chiede Furen Longbeard e portaglieli a Stormwind.",
  progress = "Come va la caccia al tesoro, $N? Hai i materiali?",
  reward = "Hai trovato tutto? Incredibile! Temevo proprio che quelle chimere ti avrebbero divorato!$B$BBe', cominciamo a forgiare quell'armatura...",
  en_title = "Fire Hardened Mail",
  en_obj = "Gather the materials Furen Longbeard requires, and bring them to him in Stormwind.",
}
T[1702] = {
  title = "Il Forgiatore di Scudi",
  desc = "Hai proprio dimostrato di che pasta sei $Gfatto:fatta; quando hai affrontato la Sfida di Rethban, $N. E io sono uno di parola: ti darò la ricompensa che ti ho promesso...$B$BSolo che è a Stormwind.$B$BParla con il mio amico Furen Longbeard, nel Dwarven District of Stormwind. Non troverai un forgiatore di scudi migliore di lui, e mi deve un grosso favore.$B$BEcco, porta a Furen questo barile di Barleybrew Scalder e chiedigli uno scudo. Te ne darà uno bello.",
  obj = "Porta la Cask of Scalder a Furen Longbeard.",
  progress = "Salve! Tempi di siccità, non trovi?",
  reward = "Ah, Barleybrew Scalder. Roba eccellente! Quindi sei $Gstato:stata; da Yorus, eh?$B$BPosso procurarti uno scudo, eccome! Non ne troverai uno migliore, e non è una balla!",
  en_title = "The Shieldsmith",
  en_obj = "Bring the Cask of Scalder to Furen Longbeard.",
}
T[1703] = {
  title = "Mathiel",
  desc = "Ho ricopiato i miei appunti sulle tecniche che ho imparato forgiando la tua armatura, e devo farli avere al fabbro Mathiel. Vive a Darnassus, che è parecchio lontana, ma sono sicuro che sarà molto grato di impararle anche lui.",
  obj = "Porta il Furen's Notes a Mathiel.",
  progress = "Ti porgo i miei saluti, $C.",
  reward = "Interessanti, davvero molto interessanti. Il mio collega nano Furen ha fatto una grande scoperta!$B$BGrazie, $N. Applicare le sue nuove tecniche alle mie creazioni sarà un onore.",
  en_title = "Mathiel",
  en_obj = "Bring Furen's Notes to Mathiel.",
}
T[1704] = {
  title = "Klockmort Spannerspan",
  desc = "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato forgiando la tua armatura, e cerco qualcuno che li porti a Klockmort Spannerspan. È uno gnomo fabbro di Ironforge, e quando verrà a sapere cosa ho scoperto... scommetto che si strapperà la barba dall'entusiasmo.",
  obj = "Porta il Furen's Notes a Klockmort Spannerspan.",
  progress = "Buongiorno, o buon pomeriggio, o buonasera: da quaggiù non saprei proprio dirlo. Allora, hai qualche affare per me?",
  reward = "Oh, cielo! Che appunti straordinari! E non è tutto... sono incredibili e stupendi e mi fanno venire le ginocchia tutte molli!$B$BFuren ha fatto una scoperta! Una scoperta vera! Non vedo l'ora di provare la sua nuova tecnica!",
  en_title = "Klockmort Spannerspan",
  en_obj = "Bring Furen's Notes to Klockmort Spannerspan.",
}
T[1705] = {
  title = "Burning Blood",
  desc = "Mi secca ammetterlo, ma forse Furen ha trovato davvero qualcosa. Per esserne sicuro, però, devo provare le sue tecniche su un'armatura nuova. Aiutami a procurarmi i materiali, $N, e l'armatura sarà tua.$B$BPer farla mi servono campioni di burning blood e una burning rock.$B$BPer quel che ne so, si trovano solo a Duskwood. Il burning blood ce l'hanno i worgen Nightbane che si sono stabiliti nella miniera della Roland's Doom, mentre the rock l'avrà il loro capo, Gutspill.$B$BChe la fortuna ti renda veloce, $N.",
  obj = "Porta 20 fiale di Burning Blood e 1 Burning Rock a Grimand Elmore a Stormwind.",
  progress = "$N, hai portato il burning blood e la roccia? Senza non posso finire l'armatura.",
  reward = "Bel lavoro! Ora scusami, ma ho da fare anch'io...",
  en_title = "Burning Blood",
  en_obj = "Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind.",
}
T[1706] = {
  title = "L'Armatura di Grimand",
  reward = "Stento a crederci! La tecnica di Furen ha funzionato, e questa armatura dovrebbe reggere sollecitazioni enormi.$B$BEcco a te, $N, e grazie. Se non mi avessi raccolto i materiali che mi servivano per provarla di persona, alla scoperta di Furen non ci avrei creduto.",
  en_title = "Grimand's Armor",
}
T[1707] = {
  title = "Taglia sugli Otri d'Acqua",
  desc = "Salute, $N — mi chiamo Luglunket, e se te la senti abbiamo un lavoro importante per te! Urrà!$B$BDa esperto operatore delle valvole, niente mi piacerebbe di più che avere tutti gli otri d'acqua dei Wastewander che riesci a trovare nel deserto. Tanto l'acqua è nostra — i nomadi ce l'hanno solo rubata, tutto qui! Per ogni cinque otri che consegni, la Gadgetzan Water Company ti darà un pacco assistenza ufficiale. Ma soprattutto aiuterai Gadgetzan ad aiutarsi da sola!",
  obj = "Porta 5 Wastewander Water Pouches a Spigot Operator Luglunket a Gadgetzan.",
  progress = "Hai i cinque otri d'acqua dei Wastewander che ci servono? Se ce li hai, il Pacco Assistenza della Gadgetzan Water Company, Modello 103-XB, sarà tuo!",
  reward = "Eccellente — più otri d'acqua recuperiamo, più ci teniamo tutti lontani dal disastro! Continua a portarmeli: per ogni cinque che mi consegni, una ricompensa te la do di sicuro.",
}
T[1708] = {
  title = "Iron Coral",
  desc = "Voglio provare le nuove tecniche di Furen Longbeard su un'armatura tutta mia. E siccome tu hai aiutato Furen e lui ha aiutato me, quando l'avrò finita sarà tua!$B$BPer completarla mi occorre un corallo speciale, il searing coral, che cresce in un posto solo — lungo la costa a sud di Menethil Harbor, nelle Wetlands .$B$BPortami abbastanza searing coral e mi metterò subito al lavoro sull'armatura. E sbrigati, $N: sono così impaziente di cominciare che mi si stanno arricciando persino le dita dei piedi!",
  obj = "Porta 20 carichi di Searing Coral a Klockmort Spannerspan a Ironforge.",
  progress = "Salve, salve, $N! Hai portato il searing coral? Non vedo l'ora di mettermi al lavoro!",
  reward = "Questa sì che è roba buona! Ottimo lavoro! Adesso lo fondo e lo martello, così unisco la tecnica di Furen alla mia e vediamo cosa ne viene fuori!$B$BOh, cielo, oh, cielo! Me lo sento: l'armatura sarà molto molto molto resistente!",
  en_title = "Iron Coral",
  en_obj = "Bring 20 loads of Searing Coral to Klockmort Spannerspan in Ironforge.",
}
T[1709] = {
  title = "La Creazione di Klockmort",
  reward = "Ecco la tua armatura, $N. Il procedimento di Furen ha funzionato alla grande! Alla perfezione! Davvero a meraviglia!$B$BPotresti schiacciare quest'armatura sotto una macchina d'assedio, e riprenderebbe subito forma!",
  en_title = "Klockmort's Creation",
}
T[1710] = {
  title = "Sunscorched Shells",
  desc = "Il mio collega Furen Longbeard ha fatto una scoperta che non vedo l'ora di mettere alla prova. Desidero applicarla a una nuova armatura a cui sto lavorando, perché credo che con le tecniche di Furen otterrò risultati migliori.$B$BMi aiuterai? Se raccoglierai quello che mi serve per l'armatura, ne forgerò un pezzo in più per te.$B$BMi servono le conchiglie sbiancate dal sole, cioè i gusci delle uova delle Highperch Wyverns, che vivono a Highperch, a Thousand Needles. Cercale sotto i nidi e torna da me quando ne avrai abbastanza.",
  obj = "Porta 20 Sunscorched Shells a Mathiel, a Darnassus.",
  progress = "Hai le conchiglie, $N? Sono molto resistenti, e se ne può ricavare una lacca: la userò per rivestire gli anelli della mia nuova armatura di maglia.",
  reward = "Ah, grazie. Andranno benissimo!$B$BMi metto subito a forgiare l'armatura...",
  en_title = "Sunscorched Shells",
  en_obj = "Bring 20 Sunscorched Shells to Mathiel in Darnassus.",
}
T[1711] = {
  title = "L'Armatura di Mathiel",
  reward = "Ho finito il tuo pezzo d'armatura e ne sono piuttosto soddisfatto. Le nuove tecniche di Furen si sono fuse alla perfezione con le mie e sono certo che questa armatura si rivelerà davvero resistente.$B$BGrazie, $N. Spero che ti sia utile nelle battaglie future.",
  en_title = "Mathiel's Armor",
}
T[1712] = {
  title = "Cyclonian",
  desc = "Sorveglio questo luogo da un'eternità, e lo sorveglio per vedere un giorno cadere il grande Cyclonian. Ma un campione capace di sconfiggere il signore del vento non l'ho ancora trovato.$B$BForse $Gquel campione:quella campionessa; sei tu.$B$BDimostramelo. Raccogli gli oggetti che mi servono per evocare Cyclonian e saprò che sei $Gun grande guerriero:una grande guerriera;. Allora forse potrai sconfiggerlo e prendergli il whirlwind heart.$B$BSe andrà così, infonderò in un'arma il potere del cuore e te la darò.$B$BEcco una cartapecora con l'elenco di tutto quello che mi serve.",
  obj = "Porta gli oggetti elencati sulla Bath'rah's Parchment a Bath'rah the Windwatcher in Alterac.",
  progress = "Hai gli oggetti, $N? Raccoglierli è la prova che mi serve: così saprò che hai la forza di affrontare Cyclonian.",
  reward = "Hai raccolto gli oggetti per il mio incantesimo, e mi hai fatto vedere la tua forza e la tua astuzia. Ma il prossimo passo della nostra impresa è ancora più pericoloso.$B$BSperiamo che la forza non ti venga meno.",
  en_title = "Cyclonian",
  en_obj = "Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac.",
}
T[1713] = {
  title = "L'Evocazione",
  desc = "Sono pronto a compiere il rituale per evocare Cyclonian. Quando sarà qui, dovrai sconfiggerlo e prendergli il whirlwind heart: mi servirà per infondere in un'arma il potere di Cyclonian.$B$B$N, sei $Gpronto:pronta; ad affrontare il signore del vento?",
  obj = "Porta il Whirlwind Heart a Bath'rah Windwatcher.",
  progress = "Mi serve il whirlwind heart, $N!",
  reward = "Ce l'hai fatta! Hai sconfitto Cyclonian e il Whirlwind Heart è tuo!",
  en_title = "The Summoning",
  en_obj = "Bring the Whirlwind Heart to Bath'rah Windwatcher.",
}
T[1714] = {
  title = "Essence of the Exile",
  progress = "Il calderone ribolle. I suoi vapori ti chiamano...",
  reward = "Piano piano, gli amuleti sprofondano nel calderone...$B$BUna grossa bolla sale a galla e scoppia...$B$B...E compare un grumo ribollente di roccia fusa.",
  en_title = "Essence of the Exile",
}
T[1715] = {
  title = "The Slaughtered Lamb",
  desc = "Hmph. Una volta tutti gli stregoni di Khaz Modan si addestravano sotto la guida dei maestri di Gnomeregan. Ma ora che ci hanno costretti tutti a trasferirci in questo buco da topi a Ironforge, e Magni ha deciso di tenerci d'occhio, i nostri novizi dobbiamo mandarli ad addestrarsi a Stormwind.$B$BPer fortuna Gakin non è uno sprovveduto, quindi quello che devi sapere lo imparerai comunque. Ma mi fa ribollire il sangue!$B$BAd ogni modo, Gakin lo trovi nel seminterrato de Slaughtered Lamb, a Stormwind.",
  obj = "Presentati da Gakin the Darkbinder in Mage Quarter of Stormwind.",
  reward = "$GMandato:Mandata; da Blackwrench, eh? Quei dannati stregoni di Ironforge devono mettere ordine in casa loro. Qui a Stormwind spazio e insegnanti non sono infiniti. E con tutto questo via vai, prima o poi attireremo l'attenzione di sicuro.",
  en_title = "The Slaughtered Lamb",
  en_obj = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1716] = {
  title = "Divoratore di Anime",
  desc = "Un sayaad è un divoratore di anime, un dominatore di volontà e un tentatore di cuori, e non conosce altro che il male.$B$BNei racconti piccanti il demone ha il suo nome comune: succube la femmina, incubus il maschio.$B$BPer attirare la creatura ci vuole uno stimolo: usa come esca un simbolo d'amore e di sicuro risponderà alla tua chiamata. Poi sconfiggila e fanne il tuo strumento.$B$BUna cosa del genere, però, sarà difficile da trovare. Dovresti parlarne con Takar the Seer, che troverai nelle Barrens di Kalimdor, vicino a Camp Taurajo.",
  obj = "Parla con Takar the Seer in Barrens.",
  reward = "È stata dura la traversata, $N? Hai fatto tanta strada per parlare con me. Ma non temere: so perché Gakin ti ha mandato qui, e ha fatto bene, perché posso aiutarti nella tua ricerca.",
  en_title = "Devourer of Souls",
  en_obj = "Speak with Takar the Seer in the Barrens.",
}
T[1717] = {
  title = "La Convocazione di Gakin",
  desc = "$N! Non pensavo di incontrarti da queste parti, ma mi avevano detto di tenere gli occhi aperti, caso mai ti avessi visto passare.$B$BÈ più che ora che tu faccia un altro po' di addestramento: la prossima volta che sei a Stormwind faresti bene a passare da Gakin. Ti aspetta.",
  obj = "Presentati da Gakin the Darkbinder in Mage Quarter of Stormwind.",
  reward = "Sono contento che qualcuno sia riuscito a rintracciarti, $N: cominciavo a temere il peggio. Sarebbe un peccato perderti, con tutto il tempo che abbiamo investito su di te.$B$BMa ne parleremo più tardi. Adesso conta solo il tuo addestramento.",
  en_title = "Gakin's Summons",
  en_obj = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1718] = {
  title = "L'Isolano",
  desc = "Cresce la tua fama di $Gguerriero:guerriera;, $N, ed è venuto il momento di misurarti con i tuoi pari per scoprire quanto vali.$B$BAl largo della costa di Barrens, a sud di Ratchet, c'è un'isola che si chiama Fray Island. È lì che i guerrieri si ritrovano.$B$BSi ritrovano, e combattono.$B$BParla con Klannoc Macleod, il capo dei guerrieri della Fray Island. Se Klannoc ti riterrà $Gdegno:degna;, sarà lui a guidarti più avanti lungo la via del guerriero.$B$BPer arrivare alla Fray Island cerca le secche sabbiose lungo la Merchant Coast.",
  obj = "Parla con Klannoc Macleod.",
  reward = "Salve, $Gguerriero:guerriera;. Sono contento che tu sia $Garrivato:arrivata; alla Fray Island. Spero che ti piaccia...",
  en_title = "The Islander",
  en_obj = "Speak with Klannoc Macleod.",
}
T[1719] = {
  title = "La Mischia",
  desc = "Se vuoi imparare da me, devi prima superare la Mischia. Noi della Fray Island la proponiamo volentieri ai guerrieri in ascesa che si credono duri: se ce la fai, saprò che lo sei.$B$BPer prima cosa entra in mezzo a quella folla laggiù e sali sulla grata. Così Twiggy Flathead saprà che sei $Gpronto:pronta; e ti manderà contro degli sfidanti.$B$BQuando li avrai battuti tutti, chiamerà Big Will. Uccidi Big Will e torna da me entro il tempo concesso.",
  obj = "Uccidi Big Will, poi parla con Klannoc Macleod su Fray Island.",
  progress = "Hai portato a termine la sfida?",
  reward = "Ben fatto, $N. Hai superato la Mischia!$B$BSei $Gun:una; $Gguerriero:guerriera; $Gdegno:degna;, e per me è un onore addestrarti...",
  en_title = "The Affray",
  en_obj = "Kill Big Will, then speak to Klannoc Macleod on Fray Island.",
}
T[1738] = {
  title = "Heartswood",
  desc = "Per prepararmi al tuo arrivo ho scrutato il mondo con la mia vista, oltre le nebbie del tempo, e ho trovato quello che cerchi.$B$BNella War of the Ancients due amanti caddero insieme in battaglia. Dove esalarono l'ultimo respiro crebbe un albero conosciuto come l'heartswood, simbolo del loro amore immortale.$B$BDovrebbe bastare a tentare una succube. Lo troverai fra le rovine di Ordil'Aran, nella parte nordoccidentale della foresta di Ashenvale.",
  obj = "Recupera l'Heartswood da Ashenvale e portalo a Gakin the Darkbinder in Mage Quarter of Stormwind.",
  progress = "Allora, $N, la tua ricerca è andata a buon fine?",
  reward = "Sì, vedo già che andrà benissimo. Lasciami solo un momento per lavorarci...$B$BTakar è pieno di risorse, vero? Fa comodo averlo intorno. Se solo riuscissi a convincerlo a tornare alla civiltà.",
  en_title = "Heartswood",
  en_obj = "Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1739] = {
  title = "Il Vincolo",
  desc = "Con il nucleo di heartswood potrai lanciare un incantesimo sul cerchio di evocazione, giù nella cripta, e aprire un portale da cui far passare la succube.$B$BStai $Gattento:attenta;, $N: le succubi hanno sopraffatto perfino le menti più forti.$B$BQuando l'avrai sconfitta e rispedita nel vuoto, torna da me: ti mostrerò come richiamarla e tenerla sotto controllo.",
  obj = "Usando l'Heartswood Core, evoca e sottometti una succube, poi riporta l'Heartswood Core a Gakin the Darkbinder nello Slaughtered Lamb.",
  progress = "A volte mi chiedo se Surena non fosse una succube travestita, mandata a deformarmi e distorcermi la mente... Ah! Credo di darle troppo credito.",
  reward = "Ben fatto, ben fatto, $N. Vedo che abbiamo fatto bene ad addestrarti: non deludi di certo.$B$BNon mi faccio alcuno scrupolo a mostrarti come controllare la succube che hai appena vincolato. Guarda bene.",
  en_title = "The Binding",
  en_obj = "Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb.",
}
T[1740] = {
  title = "L'Orb of Soran'ruk",
  desc = "Quando i demoni della Legione cadono in disgrazia, i loro spiriti finiscono imprigionati in globi, che vengono poi distribuiti fra i suoi maghi e stregoni.$B$BMolti erano nelle mani dei loro servitori su Azeroth, e anche ridotti in frammenti conservano i poteri dei demoni che vi sono intrappolati.$B$BL'orb of Soran'ruk è stato spezzato in due. Uno dei due pezzi è stato ridotto in frammenti, che usano gli accoliti del Twilight's Hammer a Blackfathom Deeps. L'altro, il più grande, ce l'aveva un mago a Shadowfang Keep. Trovali e potrò ricomporlo.",
  obj = "Trova 3 Soran'ruk Fragments e 1 Large Soran'ruk Fragment e riportali a Doan Karhan in Barrens.",
  progress = "Per raccogliere i pezzi del globo di Zargain ci ho messo molti anni, ma mi è servito molto, e sono certo che l'orb of Soran'ruk servirà anche a te.",
  reward = "Sì... Il globo non era molto frammentato, e qui ci sono quasi tutti i pezzi. Ricomporli e rendere di nuovo intero Soran'ruk è semplice.$B$BHo passato la vita a studiare i globi della Burning Legion e a ricostruirli. Raccogliendo questi pezzi da studiare mi hai fatto un favore, e te li restituirò — completamente ricostruiti — nella forma che preferisci.",
  en_title = "The Orb of Soran'ruk",
  en_obj = "Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.",
}
T[1758] = {
  title = "Tome of the Cabal",
  desc = "Per far comparire un felhunter da affrontare non basta un semplice cerchio di evocazione.$B$BIo e i miei tre accoliti ti aiuteremo a creare i cerchi magici, ma ti serve una copia del Tome of the Cabal, perduto ormai da tempo. L'ha scritto il primo gruppo di stregoni che sia riuscito a evocare da solo un felhunter.$B$BForse può aiutarti Krom Stoutarm. Oggi fa lo stregone errante, e passa le giornate ad accumulare testi antichi e ad aggirarsi di nascosto per la biblioteca di Ironforge.",
  obj = "Parla con Krom Stoutarm a Ironforge.",
  reward = "Tome of the Cabal? Mmm... questo mi dice qualcosa. Qui però non l'ho mai visto — e credimi, ogni libro che leggo me lo ricordo.$B$BMmm...$B$BAh, sì! L'ho trovato citato nei cataloghi della biblioteca.",
  en_title = "Tome of the Cabal",
  en_obj = "Speak with Krom Stoutarm in Ironforge.",
}
T[1778] = {
  title = "Il Tome of Divinity",
  desc = "Vedrò di organizzarmi per tornare presto a casa. Spero che Stephanie stia bene, là a Stormwind. Non vedo l'ora di rivederla. Alla prossima, $C.",
  obj = "Parla con Tiza Battleforge a Ironforge.",
  reward = "Allora, sei già $Gtornato:tornata;, eh? E dimmi, di grazia, cos'hai concluso mentre eri via?$B$BSei $Griuscito:riuscita; a dare una mano a una nobile causa? Magari hai imparato quanto vale la carità, o qualcosa di più su quello che devi ai cittadini di Azeroth. Raccontami chi hai aiutato, e come.... Notevole, $N, queste sono senz'altro azioni da chi segue la Luce.$B$BCol tempo, un sacrificio così sarà sempre ricompensato.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[1779] = {
  title = "Il Tome of Divinity",
  desc = "Voglio che tu prenda questo, $N. Si chiama Symbol of Life.$B$BHai dimostrato di essere caritatevole e paziente, e ora devi farmi vedere quanto sei $Gdiventato:diventata; abile, sia in combattimento sia nel potere.$B$BMio marito Muiredon è appena tornato da uno scontro con dei nani Dark Iron e l'ha scampata per un pelo — ora è laggiù, e uno dei nostri sacerdoti gli sta curando le ferite.$B$BPrendi il Simbolo e va' a parlargli. Se riesci ad aiutarlo, ci rivedremo presto. La Luce splenda su di te.",
  obj = "Prendi lo Symbol of Life e parla con Muiredon Battleforge a Ironforge.",
  reward = "*coff*$B$BBuondì a te, $C. Lascia stare le mie ferite: col tempo il buon sacerdote qua si prenderà cura del vecchio Muiredon. Del potere di quello Symbol of Life che c'hai lì, per ora non ho bisogno.$B$BAllora t'ha mandato mi' moglie, eh? Ci sta. Un po' di tempo per parlarti lo trovo — ti racconto per filo e per segno cos'è successo a Muiredon e al suo migliore amico Narm, un paladino proprio come te.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life and speak to Muiredon Battleforge in Ironforge.",
}
T[1780] = {
  title = "Il Tome of Divinity",
  desc = "Li porterò ai bambini oggi stesso. Abbi cura di te, ti prego, $Gbuon:buona; $C. Non capita spesso di vedere in città $Guomini:donne; della tua tempra, ma tu hai dimostrato che i paladini qui a Stormwind non volteranno mai le spalle a chi ha bisogno.$B$BAddio.",
  obj = "Parla con Duthorian Rall a Stormwind.",
  reward = "Sei $Gtornato:tornata; presto, $N. E cos'hai fatto mentre eri $Glontano:lontana; dalla Cattedrale?$B$BHai servito una nobile causa? Forse hai imparato il valore della carità, o qualcosa di più sui tuoi doveri verso i cittadini di Azeroth. Dimmi chi hai aiutato, e come.... Be', sono colpito, $N: queste sono di certo le azioni di chi segue la Luce e mette gli altri prima di sé.$B$BCol tempo, un sacrificio simile verrà sempre ricompensato.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1781] = {
  title = "Il Tome of Divinity",
  desc = "Prendi questo, $N: si chiama Symbol of Life.$B$BTi sei $Gdimostrato:dimostrata; caritatevole e paziente, e ora è il momento di vedere se sei abbastanza potente da incanalare uno dei più grandi doni della Luce.$B$BIl mio amico Gazin è appena tornato da uno scontro con alcuni Defias a Elwynn, vicino all'Heroes' Vigil — l'ha scampata per un pelo. Lo trovi vicino all'altare, dove i nostri sacerdoti gli stanno curando le ferite.$B$BPrendi il Simbolo e va' a parlargli. Se riuscirai ad aiutarlo, ne riparleremo presto. Che tu possa crogiolarti nella gloria della Luce.",
  obj = "Porta lo Symbol of Life a Gazin Tenorm a Stormwind.",
  reward = "*cof cof*$B$BPiacere di conoscerti, $C. Lascia stare le mie ferite: stavolta del vecchio Gazin può occuparsene il buon sacerdote qui. Del potere di quello Symbol of Life che hai lì non avrò bisogno... almeno per ora.$B$BE così ti ha mandato Duthorian a parlare con me, eh? Va bene. Ti racconterò per filo e per segno cos'è successo a me e al mio amico Henze. E con un po' di fortuna, e un po' di abilità da parte tua, forse puoi ancora aiutarci tutti.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life to Gazin Tenorm in Stormwind.",
}
T[1782] = {
  title = "L'Armatura di Furen",
  reward = "Ecco la tua armatura, $N. Reggerà anche agli assalti più potenti, o non mi chiamo Furen Longbeard!$B$BE poi devo ringraziarti: lavorando con i materiali$Bche mi hai portato ho imparato molto. Credo che un giorno farò un'altra grande scoperta!$B$BQuello che ho imparato lo manderò ad altri$Bfabbri dell'Alleanza.$B$BGli dirò che mi sei $Gstato:stata; di grande aiuto: magari vorranno ricambiare il favore.",
  en_title = "Furen's Armor",
}
T[1783] = {
  title = "Il Tome of Divinity",
  desc = "Stavamo spiando un po' di nani Dark Iron che s'erano rintanati a sud dell'Helm's Bed Lake. Si sapeva che stavan tramando qualcosa, e allora io e Narm abbiam deciso d'andare a vedere più da vicino — e lì abbiam visto il loro capo che dava ordini a qualcuno dei suoi.$B$BIo e Narm n'abbiam approfittato per farne fuori qualcuno, ma eran più tosti del previsto, e altri c'hanno presi alla sprovvista. Narm m'ha detto di filar via a cercare rinforzi, ed eccomi qua.$B$BNarm ha bisogno d'aiuto, e io non mi do pace finché qualcuno non glielo dà.$B$BMi dai una mano, $N?",
  obj = "Prendi lo Symbol of Life e resuscita Narm Faulk a Dun Morogh.",
  reward = "Non so come ringraziarti, $Gfratello:sorella;.$B$BVisto che porti lo Symbol of Life, immagino che ti abbiano mandato qui Tiza e Muiredon ad aiutarmi.$B$BÈ vero, sono caduto per mano dei Dark Iron mentre cercavo di prendere uno dei documenti: ho resistito abbastanza da far fuggire Muiredon, ma quando sei $Garrivato:arrivata; tu la Luce mi aveva quasi del tutto accolto. Che tu sia $Gstato:stata; abbastanza potente da usare il Simbolo promette grandi cose per te, ma per parlarne ci sarà tempo più avanti.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh.",
}
T[1784] = {
  title = "Il Tome of Divinity",
  desc = "Prima che cadessi in battaglia, io e Muiredon eravamo quasi riusciti a sconfiggere una delle spie Dark Iron, vicino a quella casetta. Avevamo visto il loro capitano dar loro degli ordini, e avevamo provato a ucciderlo per prenderglieli.$B$BNel consiglio di Ironforge c'è ancora chi non crede che a Dun Morogh ci siano nani Dark Iron. Se ci procuriamo uno di quei documenti, avremo la prova dei loro movimenti, e forse anche un'idea di cosa stanno tramando.$B$BVa' a prenderne uno e portalo a Muiredon, $N.",
  obj = "Recupera un Dark Iron Script dai nani Dark Iron vicino a Helm's Bed e torna da Muiredon Battleforge a Ironforge.",
  progress = "Sei $Gtornato:tornata;! Che piacere vederti, $N. Le ferite son guarite, e son quasi pronto a ripartire per il lago di Helm's Bed, appena riesco a convincere mi' moglie che starò bene.",
  reward = "Ahah! Ce l'hai fatta! Hai salvato Narm e hai trovato la prova che mi' moglie deve portare al consiglio. Se c'è una benedizione della Luce, quella sei tu... a parte mi' moglie, s'intende.$B$BGrazie ancora, $N.",
  en_title = "The Tome of Divinity",
  en_obj = "Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge.",
}
T[1785] = {
  title = "Il Tome of Divinity",
  desc = "La vedo laggiù, mi' moglie, che già sprizza orgoglio da tutti i pori. Ti conviene portar le chiappe da lei, e alla svelta. M'sa che c'ha qualcosa da dirti.$B$BLa Luce sia con te, possente $C. Quando sarà il momento, ti cercherò sul campo di battaglia contro lo Scourge e quei Dark Irons.",
  obj = "Parla con Tiza Battleforge a Ironforge.",
  reward = "Oggi hai reso un gran servizio a tutta Ironforge, $N. Sono fiera di averti tra noi e, se te la senti, vorrei benedirti con questa pergamena. Lo Symbol of Life avrebbe funzionato solo nelle mani di un paladino pronto per una delle più grandi benedizioni della Luce — il potere di riportare in vita i morti.$B$BTi insegnerò l'abilità di resuscitare i compagni. Usala con saggezza, $N, e grazie da parte mia, di mio marito e di Ironforge.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[1786] = {
  title = "Il Tome of Divinity",
  desc = "Henze e io eravamo arrivati all'Heroes' Vigil, un'isola in mezzo allo Stone Cairn Lake, nel nord-est di Elwynn. Avevamo sentito che i Defias si erano infiltrati oltre i nostri confini, e volevamo procurarci delle prove da portare ai consiglieri del re.$B$BAbbiamo visto un paio di quei farabutti che esaminavano dei documenti e li abbiamo attaccati, ma purtroppo altri maghi ci hanno subito sopraffatto.$B$BHenze li ha trattenuti mentre io scappavo... quello sciocco testone, a fare l'eroe.$B$BÈ ancora là fuori, Henze. Puoi aiutarci, $N?",
  obj = "Porta lo Symbol of Life e resuscita Henze Faulk a Elwynn.",
  reward = "Grazie, $Gfratello:sorella;.$B$BSe impugni lo Symbol of Life, ti avranno mandato Duthorian o Gazin, dico bene?$B$BSono caduto per mano degli incantatori dei Defias mentre io e Gazin cercavamo di prendere i loro piani: ho tenuto duro abbastanza a lungo da permettere a Gazin di scappare, ma alla fine le loro magie mi hanno sopraffatto.$B$BMa tu sei $Griuscito:riuscita; a riportarmi indietro, e saper usare il Simbolo non è da tutti, $N. Che tu abbia saputo dargli forza con la tua fede è di buon auspicio per te.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life and resurrect Henze Faulk in Elwynn.",
}
T[1787] = {
  title = "Il Tome of Divinity",
  desc = "Del Simbolo avremo tempo di riparlare più avanti. Adesso l'importante è prendere i documenti che abbiamo visto esaminare dai Defias. Se riusciamo a metterci le mani sopra, potremo dimostrare che i Defias si sono infiltrati a Elwynn e, speriamo, capire qualcosa dei loro piani.$B$BPer ora io non sono in condizione di combattere, $N. Pensi di essere abbastanza forte da prendere quei documenti ai Defias qui sull'isola?$B$BSe ci riesci, portali a Gazin e digli che sto bene.",
  obj = "Recupera un Defias Script dai Defias Rogue Wizards a Elwynn e torna da Gazin Tenorm a Stormwind.",
  progress = "Henze è salvo, $N? Ci sei $Griuscito:riuscita;?$B$BCon la tua bravura con le armi e il potere della Luce, immagino che l'Heroes' Vigil sia al sicuro da qualsiasi minaccia dei Defias, ma questo spetta al Re e ai suoi consiglieri dirlo.",
  reward = "Magnifico! Ce l'hai fatta, e hai salvato Henze. La Luce è di certo con te, $N!",
  en_title = "The Tome of Divinity",
  en_obj = "Retrieve a Defias Script from the Defias Rogue Wizards in Elwynn, and return to Gazin Tenorm in Stormwind.",
}
T[1788] = {
  title = "Il Tome of Divinity",
  desc = "Porterò il documento ai consiglieri del Re quando Duthorian l'avrà esaminato, ma intanto dovresti andare a parlare con lui. Di sicuro vorrà darti una pacca sulla spalla!$B$BGrazie ancora, $N, e spero di rivederti. Sei senz'altro $Gun alleato:un'alleata;, e sono fiero di poterti chiamare $Gamico:amica;.",
  obj = "Parla con Duthorian Rall a Stormwind.",
  reward = "Oggi hai fatto un ottimo lavoro, $N. Dovresti andare un po' $Gfiero:fiera; di quanto hai compiuto.$B$BE ancora di più dovresti essere $Gorgoglioso:orgogliosa; delle tue capacità. Non tutti sanno usare il potere dello Symbol of Life. Se sai invocare la Luce per far tornare i morti, vuol dire che sei $Gpronto:pronta; per uno dei più grandi onori di un paladino: il potere della resurrezione.$B$BPotrai riportare in vita i compagni caduti, proprio come hai fatto con Henze.$B$BAbbi cura di te, $N. La Luce splende su di te, e dovresti accoglierla con tutto il cuore.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1789] = {
  title = "Lo Symbol of Life",
  reward = "Fa' presto, $N: se fallisci, sarà in bilico più di una vita.$B$BSe per qualche ragione non riesci ad aiutare Muiredon e Narm, torna da me: ti darò un altro Symbol of Life da portare con te nel viaggio.$B$BNon prendere il mio aiuto per semplice carità: come $Gqualsiasi altro:qualsiasi altra; $C, devi dimostrarti $Gdegno:degna;, e se continui a fallire, un giorno potrebbe ricaderti addosso.",
  en_title = "The Symbol of Life",
}
T[1790] = {
  title = "Lo Symbol of Life",
  reward = "Sbrigati, $N, perché se fallisci ci sarà in bilico più di una vita.$B$BSe per qualche motivo non riuscissi ad aiutare Gazin ed Henze, torna da me e ti darò un altro Symbol of Life per i tuoi viaggi.$B$BMa non scambiare il mio aiuto per semplice carità: devi dimostrarti $Gdegno:degna; come qualsiasi $Galtro:altra; $C, e fallire di continuo potrebbe ricaderti addosso, un giorno.",
  en_title = "The Symbol of Life",
}
T[1791] = {
  title = "The Windwatcher",
  desc = "Hai imparato la postura da berserker: ora ti servirà una bella arma per metterla in pratica.$B$BVa' a parlare con Bath'rah the Windwatcher, un eremita troll che vive tra le Alterac Mountains e le Western Plaguelands. È un armaiolo abile e uno sciamano potente.$B$BPer trovare Bath'rah, raggiungi il fiume che scorre lungo il lato est di Tarren Mill e seguilo verso nord — Bath'rah è accampato vicino a delle rovine, sulla riva orientale.",
  obj = "Parla con Bath'rah the Windwatcher.",
  reward = "Hai fatto tanta strada, $Ggiovane guerriero:giovane guerriera;. Hai il fuoco negli occhi, lo vedo. Cerchi un'arma di grande potere, sì?$B$BIo posso aiutarti nella tua impresa, e tu puoi aiutare me nella mia.",
  en_title = "The Windwatcher",
  en_obj = "Speak with Bath'rah the Windwatcher.",
}
T[1792] = {
  title = "Arma del Turbine",
  reward = "Ho qui il whirlwind heart, e sono pronto a porlo nel ricettacolo che sceglierai.$B$BScegli la tua arma, $N, e sappi che avrà il potere di Cyclonian.",
  en_title = "Whirlwind Weapon",
}
T[1793] = {
  title = "Il Tome of Valor",
  reward = "Hai dimostrato che la Luce è con te, $N, ma man mano che i tempi si fanno più pericolosi conta sapere quale forza si nasconde sotto la carne. Quando demoni, draghi o qualunque altro male metteranno piede nelle tue terre, la tua tempra sarà messa alla prova. Sarai forte abbastanza?$B$BIl coraggio, in ogni situazione, fa parte dell'essere paladino quanto la Luce, l'armatura e l'arma. Proteggere i deboli e non perdere la fede sono altre due lezioni che dovrai imparare a fondo durante i tuoi studi nella Cathedral of Light.",
  en_title = "The Tome of Valor",
}
T[1794] = {
  title = "Il Tome of Valor",
  reward = "Ormai è provato che la Luce è con te, $N. Ma i tempi si fanno sempre più pericolosi, e conta sapere quale forza si nasconde sotto la carne. Quando demoni, draghi o qualunque altro male metteranno piede nelle tue terre, la tua tempra verrà messa alla prova. Sarai forte abbastanza?$B$BIl coraggio, in ogni situazione, fa parte dell'essere paladini quanto la Luce, l'armatura e l'arma. Mentre studi nella Cathedral of Light dovrai imparare a fondo altre due lezioni: proteggere i deboli e non perdere la fede.",
  en_title = "The Tome of Valor",
}
T[1795] = {
  title = "Il Vincolo",
  desc = "Se sei $Gpreparato:preparata; a sufficienza, possiamo cominciare. Lascia che ti spieghi come procederemo.$B$BPer prima cosa creerò il cerchio di evocazione di base. Appena avrò finito, i miei accoliti useranno le rods of channeling per formare il cerchio maggiore.$B$BA quel punto leggi l'incantesimo dal Tome of the Cabal, e il felhunter verrà trascinato qui. Fai attenzione, $N: è un nemico potente, e vorrei che la testa ti restasse sulle spalle.",
  obj = "Usando il Tome of the Cabal, evoca e sottometti un felhunter, poi riporta il Tome of the Cabal a Strahad Farsan a Ratchet.",
  progress = "Ogni stregone dovrebbe avere un felhunter ai suoi ordini. Domarlo è difficile, ma i poteri che dà al padrone valgono molto più del prezzo.",
  reward = "Devo dire che sono colpito, $N. Quando ho affrontato il mio felhunter, me la sono cavata per un pelo. Sento che hai la stoffa per diventare $Guno degli stregoni più potenti:una delle streghe più potenti; di quest'epoca.",
  en_title = "The Binding",
  en_obj = "Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.",
}
T[1796] = {
  title = "Componenti per l'Enchanted Gold Bloodrobe",
  desc = "Il primo oggetto che ti aiuterò a creare è una tonaca. Tu mi porterai il necessario e lo assembleremo insieme. Dopo, se ci riuscirai, avrai il primo di molti oggetti che ti renderanno più potente e ti aiuteranno nelle tue lotte.$B$BPer cominciare ti servono delle Robes of Arcana. Puoi fartele confezionare da un sarto o magari comprarle da qualcun altro — se riuscissi a farle da $Gsolo:sola; ne sarei molto colpita — ma in ogni caso portami le vesti, e poi vedremo.",
  obj = "Porta le Robes of the Arcana a Menara Voidrender in Barrens.",
  progress = "Come procede la ricerca delle vesti, $N? Le hai fatte tu $Gstesso:stessa;? Per me infondere la magia è molto più dolce quando c'è un tocco personale: dà più soddisfazione. Ma capisco se scegli la via più rapida e te le fai fare da altri — anche una simile... ambizione ha i suoi meriti.",
  reward = "Andranno benissimo, $N.$B$BOgni oggetto magico deve partire da una base di alta qualità: più impegno e abilità ci si mettono, più magia potrà contenere. I componenti rari e più costosi la trattengono meglio. Non ti pentirai di far trasformare queste vesti in quelle che creeremo per te più avanti.",
}
T[1798] = {
  title = "In Cerca di Strahad",
  desc = "È ora che tu impari a evocare il felhunter, $N. Qui non ho i reagenti né gli oggetti che servono per insegnartelo, quindi dovrai cercare Strahad Farsan, un altro membro della nostra cerchia ristretta.$B$BVive nel porto goblin di Ratchet. Gli manderò un messaggio per avvisarlo che stai arrivando.",
  obj = "Parla con Strahad Farsan in Barrens.",
  reward = "$N? Ah, già, certo: il nostro ultimo prodigio. Temo che la realtà non regga il confronto con la leggenda.$B$BPoco importa: sei $Gvenuto:venuta; qui per imparare, non per sentirmi fare battute fra me e me.",
  en_title = "Seeking Strahad",
  en_obj = "Speak with Strahad Farsan in the Barrens.",
}
T[1799] = {
  title = "Frammenti del Globo di Orahil",
  desc = "Bene, allora cominciamo.$B$BPrima di tutto parla con i miei accoliti, qui dentro, e scegli quale delle loro vie seguire — saranno loro a spiegarti meglio.$B$BPoi devi andare a Desolace e procurarti un Infernal Orb da uno degli stregoni della Mannoroc Coven. Per purificarlo ti farai aiutare da una maga di nome Tabetha, che trovi nel profondo sud della Dustwallow Marsh. Ti aiuterà, per via dei nostri trascorsi.$B$BTe lo ripeto: non tornare prima di aver fatto tutte e due le cose che ti ho chiesto.",
  obj = "Parla con gli accoliti di Menara all'interno della torre sopra Ratchet e scegli quale delle loro vie seguire.$B$BPoi porta un Infernal Orb a Tabetha in Dustwallow Marsh.",
  progress = "E visto che è chiaro che non sei $Gun mago:una maga;, mi chiedo se posso fidarmi di te. Ti sento addosso l'odore del potere arcano, eppure pare che tu sia $Gsfuggito:sfuggita; al puzzo della corruzione che accompagna così volentieri quelli come te.$B$BSì, $Gun:una; $C... $Gun:una; $C è $Gvenuto:venuta; a chiedermi aiuto.$B$BAllora, cosa posso fare per te, $N?",
  reward = "Oh, allora ti manda Menara. E va bene... direi che per ora puoi restare come $Gmio:mia; ospite. Ma sarai qui per qualcosa di urgente — forse cerchi un potere perduto? Forse mi sbaglio. Forse, dopotutto, la corruzione non ti è poi così lontana.",
}
T[1800] = {
  title = "Lordaeron Throne Room",
  desc = "La sera, se facciamo i bravi e sbrighiamo le faccende, le matrone dell'orfanotrofio ci raccontano grandi storie di battaglie e di leggende. Una parlava della caduta di Lordaeron e di come il malvagio Arthas ha ucciso suo padre per diventare sovrano.$B$BNon aveva onore, $N! Quando sarò grande e diventerò un possente guerriero dell'Orda, a guidare la mia lama sarà l'onore — mai il male!$B$BMi porteresti a vedere la sala del trono, per favore? È appena prima del punto in cui si scende nell'Undercity.",
  obj = "Porta il tuo protetto alla vecchia Lordaeron Throne Room, che si trova poco prima di scendere nell'Undercity.",
  progress = "Siamo arrivati?",
  reward = "Faceva paura, quella sala del trono, $N! Era vuota, eppure sembrava che lì fosse successo un grande male. Mi sono arrabbiato... ma mi sono sentito anche triste. Capisco perché le matrone ci raccontano storie così; io il mio popolo non lo tradirò mai in quel modo!$B$BGrazie di avermi portato alla sala del trono, $N. Ho imparato tanto.",
  en_title = "Lordaeron Throne Room",
  en_obj = "Take your ward to the old Lordaeron Throne Room that lies just before descending into the Undercity.$B",
}
T[1801] = {
  title = "Tome of the Cabal",
  desc = "Per far comparire un felhunter da affrontare non basta un semplice cerchio di evocazione.$B$BIo e i miei tre accoliti ti aiuteremo a creare i cerchi magici, ma ti serve una copia del Tome of the Cabal, perduto ormai da tempo. L'ha scritto il primo gruppo di stregoni che sia riuscito a evocare da solo un felhunter.$B$BForse può aiutarti Jorah Annison. Oggi fa il cartografo a Undercity, ma di testi antichi continua a saperne più di chiunque altro io conosca.",
  obj = "Parla con Jorah Annison a Undercity.",
  reward = "Fare mappe! Disegni, stime della realtà. Cose del genere non mi servono a niente.$B$BNei libri, nel racconto, nella descrizione! È lì la verità. Darei tutte le mappe di questo negozio per un solo libro sull'ascesa della negromanzia, o per un racconto del trionfo della Dama Oscura.",
  en_title = "Tome of the Cabal",
  en_obj = "Speak with Jorah Annison in the Undercity.",
}
T[1802] = {
  title = "Tome of the Cabal",
  desc = "È andato perduto, ma più o meno si sa dove potrebbe essere.$B$BNe hanno fatta una copia sola, e a un certo punto qualcuno l'ha danneggiata strappando dalla rilegatura gran parte delle pagine. Si dice che quella parte sia finita, chissà come, nelle mani dei centauri di Thousand Needles.$B$BIl resto è andato perduto al largo della costa a ovest di Southshore, mentre lo portavano in nave a Menethil Harbor. Non ci è mai arrivato.$B$BIn cambio di queste informazioni ti chiedo una cosa sola: se lo trovi, portamelo, così posso vederlo.",
  obj = "Recupera il Moldy Tome e il Tattered Manuscript per Krom Stoutarm a Ironforge.",
  progress = "Allora, $N, le voci erano vere?",
  reward = "Fantastico! Ora potrò unirmi ai pochi che ne hanno sbirciato il contenuto.$B$BNon vedo l'ora di studiarlo meglio, questo testo. Oggi è un gran giorno, $N! Lascia solo che gli dia un'occhiata prima che tu parta. Di sicuro Strahad sarà disposto a mandarmene una copia.",
  en_title = "Tome of the Cabal",
  en_obj = "Retrieve the Moldy Tome and Tattered Manuscript for Krom Stoutarm in Ironforge.",
}
T[1803] = {
  title = "Tome of the Cabal",
  desc = "Ah! Vedo che sei $Guno stregone:una strega; dai gusti simili ai miei. Mettere le mani sul Tome of the Cabal è senza dubbio un obiettivo degno. Lo sapevi che un tempo lo custodivano fra le mura di Lordaeron? Però qualcuno l'ha danneggiato, strappandone quasi metà delle pagine. Chi mai potrebbe compiere un atto tanto infame?$B$BDi quella metà si sono perse le tracce, ma si dice che sia finita nelle mani dei centauri di Thousand Needles.$B$BIl resto del testo doveva essere portato a Ironforge, ma si è perso durante il viaggio, lungo la costa a ovest di Southshore.",
  obj = "Recupera il Moldy Tome e il Tattered Manuscript per Jorah Annison a Undercity.",
  progress = "Forse insegui delle favole, $N, ma anche le voci più assurde possono nascondere un fondo di verità.",
  reward = "Bene bene bene! Cosa abbiamo qui?$B$BImpressionante, $N. Non l'avrei creduto possibile, eppure eccolo qui, fra le mie mani: il Tome of the Cabal completo.$B$BLasciamelo sfogliare un momento, prima che tu riparta.",
  en_title = "Tome of the Cabal",
  en_obj = "Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity.",
}
T[1804] = {
  title = "Tome of the Cabal",
  desc = "Beh, ehm, separarmene mi costa. Ma l'hai trovato tu, e di sicuro hai cose più importanti da farci. Solo, ti prego, ricordati di dire a Strahad che ne volevo una copia.$B$BMentre eri via ti ha mandato un messaggio: mi ha chiesto di dirti che dovrai procurarti tre rods of channeling, così i suoi accoliti potranno aiutarti nell'evocazione.$B$BLui forse non sa dove trovarle, ma io sì! Gli ultimi a usarle sono stati gli orchi del clan Dragonmaw, nelle Wetlands. Io darei un'occhiata ai loro incantatori!",
  obj = "Porta il Reconstructed Tome e 3 Rods of Channeling a Strahad Farsan a Ratchet.",
  progress = "Era un po' che non ti vedevo da queste parti. Allora, li hai trovati il tomo e le verghe?",
  reward = "Ben fatto! Il Tome of the Cabal e tre perfette — un po' graffiate, direi — rods of channeling.$B$BSarà interessante: è da un po' che nessun giovane stregone affronta un felhunter per farlo suo.",
  en_title = "Tome of the Cabal",
  en_obj = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.",
}
T[1805] = {
  title = "Tome of the Cabal",
  desc = "È uno dei testi più interessanti che abbia studiato da anni a questa parte. Qui la scelta è scarsa — quasi solo libri di geografia — e li ho già letti tutti. Spero proprio che Strahad mi mandi una copia di questo tomo appena ne avrà l'occasione.$B$BA proposito, mentre eri via mi ha fatto avere un messaggio: per il tuo compito devi procurarti tre rods of channeling.$B$BVisto che mi hai lasciato dare un'occhiata a questo testo, ti svelerò un segreto: le verghe le trovi addosso agli orchi del Dragonmaw Clan, nelle Wetlands.",
  obj = "Porta il Reconstructed Tome e 3 Rods of Channeling a Strahad Farsan a Ratchet.",
  progress = "Sì, $N? Posso servirti in qualche modo?",
  reward = "Ben fatto! Il Tome of the Cabal e tre perfette — un po' graffiate, direi — rods of channeling.$B$BSarà interessante: è da un po' che nessun giovane stregone affronta un felhunter per farlo suo.",
  en_title = "Tome of the Cabal",
  en_obj = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.",
}
T[1806] = {
  title = "La Prova della Rettitudine",
  desc = "Perché non andiamo alla forgia e cominciamo? Mi preparo al tuo arrivo da tempo, quindi ci vorrà pochissimo.$B$BQuando avremo finito, sarai molto più $Gpronto:pronta; di prima a difendere la Luce, questo te lo giuro.$B$BTi confesso, $N, che vedere i frutti delle tue imprese mi rende un po' invidioso. Ma sapere che posso contribuire alle tue avventure a modo mio, e in maniera importante, mi dà una certa gioia.",
  obj = "Aspetta che Jordan Stilwell finisca di forgiare un'arma per te.",
  reward = "Eccola, $N. Un'arma degna di $Gun campione:una campionessa; della Luce come te. Le ho dato il nome di un grande paladino nanico che era mio amico. Si chiamava Verigan... Bosch Verigan. Ti prego, accettala da parte mia e di mia moglie. Abbiamo un grande debito con te, e il mondo sarà più sicuro con qualcuno abile come te che percorre queste terre.",
  en_title = "The Test of Righteousness",
  en_obj = "Wait for Jordan Stilwell to finish forging a weapon for you.",
}
T[1818] = {
  title = "Parla con Dillinger",
  desc = "Mi hanno detto che Deathguard Dillinger ha un lavoro per $Guno:una; come te. Se sei $Gdisposto:disposta; a dimostrare il tuo valore alle forze della Dama Oscura, presentati subito da Dillinger.$B$BLa postazione di Deathguard Dillinger si trova all'estremità occidentale di Brill, vicino al cimitero.",
  obj = "Parla con Deathguard Dillinger a Brill.",
  reward = "Sei qui per una missione? Bene. Ne ho una importante, che metterà alla prova la tua abilità in combattimento... e la tua determinazione nel difendere i Forsaken.",
  en_title = "Speak with Dillinger",
  en_obj = "Speak with Deathguard Dillinger in Brill.",
}
T[1819] = {
  title = "Ulag the Cleaver",
  desc = "Quando lo Scourge ha travolto le Tirisfal Glades, ne abbiamo catturato uno per studiarlo. Aveva una mente indipendente e si faceva chiamare Ulag the Cleaver. Ma, sebbene la sua volontà fosse libera, era ancora soggiogato da The Lich King.$B$BSperavamo di trovare un modo per spezzare il dominio del re su Ulag, ma abbiamo fallito. Ora, finalmente, è giunto il momento di liberarlo.  $B$BLiberalo, e uccidilo.$B$BAttiva il meccanismo della pietra a forma di teschio vicino al mausoleo a nord. Spezzerà il sigillo magico che lo tiene prigioniero.$B$BPoi... tieniti $Gpronto:pronta;, $N.",
  obj = "Uccidi Ulag the Cleaver, poi parla con Deathguard Dillinger.",
  progress = "Il tuo compito non è ancora concluso, $N. Non è saggio che un guerriero mostri paura...",
  reward = "Ben fatto, $N. Ulag non era un agente qualunque dello Scourge. Hai dimostrato ai Guardiamorte, e quindi alla Dama Oscura, di essere $Gun guerriero abile e risoluto:una guerriera abile e risoluta;, $Gdegno:degna; di ricevere altri insegnamenti.",
  en_title = "Ulag the Cleaver",
  en_obj = "Kill Ulag the Cleaver, then speak with Deathguard Dillinger.",
}
T[1820] = {
  title = "Parla con Coleman",
  desc = "Hai dimostrato il tuo valore alla Dama Oscura; ora forse puoi dare prova di te a uno dei suoi sudditi.$B$BColeman Farthing attende un guerriero disposto a essere lo strumento della sua vendetta contro i nemici dei Forsaken.$B$BLo troverai alla Gallow's End Tavern, nella parte orientale di Brill.",
  obj = "Parla con Coleman Farthing.",
  reward = "Sì, è vero. Ho bisogno delle tue capacità in combattimento. I miei mezzi sono modesti, ma il compito che ti affido aiuterà sia me sia la causa dei Forsaken. Portalo a termine e ne trarrai un doppio vantaggio.",
  en_title = "Speak with Coleman",
  en_obj = "Speak with Coleman Farthing.",
}
T[1821] = {
  title = "Cimeli degli Agamand",
  desc = "La famiglia Agamand mi dava lavoro quando ero in vita, ed è per colpa sua che sono morto! È giusto che ora gli Agamand siano servi senza mente di The Lich King.$B$BAdesso voglio strappare loro le ultime vestigia di onore. Entra nella cripta di famiglia e ruba i cimeli: una spada, un'ascia, un pugnale e una mazza. Portameli!$B$BLa cripta della famiglia Agamand si trova all'estremità settentrionale dei mulini degli Agamand, protetta da creature del flagello in agguato e dagli Agamand morti.",
  obj = "Porta a Coleman Farthing l'Agamand Family Axe, l'Agamand Family Sword, l'Agamand Family Mace e l'Agamand Family dagger.",
  progress = "Hai i cimeli, $N?",
  reward = "Ah! Li hai recuperati! Ora alle maledette terre degli Agamand è stato strappato l'ultimo segno di onore e di memoria. La famiglia è davvero finita!",
  en_title = "Agamand Heirlooms",
  en_obj = "Bring Coleman Farthing the Agamand Family Axe, the Agamand Family Sword, the Agamand Family Mace and the Agamand Family dagger.",
}
T[1822] = {
  title = "Arma di Famiglia",
  reward = "Terrò tre delle armi che mi hai riportato, come ricordo del mio dolore e della mia perdita. Ma ti prego, $N, scegli il cimelio che preferisci e tienilo per te.$B$BPossa servirti meglio di quanto abbia servito i suoi maledetti vecchi proprietari.",
  en_title = "Heirloom Weapon",
}
T[1823] = {
  title = "Parla con Ruga",
  desc = "Sei $Gun guerriero:una guerriera; abile, e la tua fama cresce. Forse sei $Gpronto:pronta; per la prova di Ruga Ragetotem? Se lo sei, cerca Ruga a Camp Taurajo, nelle Barrens.$B$BAspetta i guerrieri che rispondono al suo richiamo.",
  obj = "Parla con Ruga Ragetotem.",
  reward = "Sei qui per la mia prova, $N?",
  en_title = "Speak with Ruga",
  en_obj = "Speak with Ruga Ragetotem.",
}
T[1824] = {
  title = "Prova al Field of Giants",
  desc = "Per superare questa prova devi andare a sud, al Field of Giants, dove troverai una moltitudine di creature striscianti, simili a insetti. Sono arrivate da poco nelle Barrens, e quello che annunciano non mi piace.$B$BPortami le loro antenne mentre guizzano ancora. E non perdere tempo, $N: una volta raccolte, le antenne non guizzeranno a lungo. Se me le porterai entro il tempo concesso, supererai la prova.",
  obj = "Porta 5 antenne guizzanti a Ruga Ragetotem a Camp Taurajo",
  progress = "Hai le antenne? Allora dammele, presto: le antenne guizzanti non guizzano per sempre...",
  reward = "Ben fatto, $N! Superata la prova al Field of Giants, fai un altro passo sul cammino del $C.",
  en_title = "Trial at the Field of Giants",
  en_obj = "Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo",
}
T[1825] = {
  title = "Parla con Thun'grim",
  desc = "Thun'grim Firegaze, un famoso fabbro orco, ha sentito parlare delle imprese di valore che continui a compiere al servizio dell'Orda. Vorrebbe forgiarti un'armatura, e ti chiede di andare subito a parlargli.$B$BTrovi Thun'grim accampato a est del Crossroads, nelle Barrens.",
  obj = "Parla con Thun'grim Firegaze nelle Barrens.",
  reward = "Sì, sei $Gvenuto:venuta;. Bene: tu e io abbiamo molto di cui parlare.",
  en_title = "Speak with Thun'grim",
  en_obj = "Speak with Thun'grim Firegaze in the Barrens.",
}
T[1838] = {
  title = "Armatura Brutale",
  desc = "Ho sentito parlare della tua forza e del tuo valore, e voglio forgiarti un'armatura: una compagna che ti aiuti mentre crescono i racconti delle tue grandi imprese.$B$BMa forgiarla sarà un'impresa a sé, $N. Mi servirà il tuo aiuto, e anche quello di altri fabbri dell'Orda.$B$BEcco, prendi questa pergamena: ho passato molte notti a scriverci, a fatica e con gli occhi quasi ciechi, ciò che mi serve per l'armatura. Portami gli oggetti scritti su questa pergamena e creerò per te il primo pezzo.",
  obj = "Porta a Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars e una Vial of Phlogiston.",
  progress = "Hai gli oggetti scritti sulla mia pergamena, $N?",
  reward = "Hai portato tutto quello che ti ho chiesto. Ora faccio la mia parte...",
  en_title = "Brutal Armor",
  en_obj = "Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston.",
}
T[1839] = {
  title = "Ula'elek e i Brutal Gauntlets",
  desc = "Sarà il fabbro troll Ula'elek a forgiare per te i brutal gauntlets. Dimora a Sen'jin Village, in Durotar, con i fratelli Darkspear, e aspetta il tuo arrivo.",
  obj = "Parla con Ula'elek in Durotar.",
  reward = "Salute, $N. Il vecchio Thun'grim mi ha avvisato del tuo arrivo, ma anche se fosse stato zitto, vederti qui non mi avrebbe stupito.$B$BGli spiriti seguono i tuoi progressi, giovane $C, e mi dicono che davanti a te sono caduti molti nemici.",
  en_title = "Ula'elek and the Brutal Gauntlets",
  en_obj = "Speak with Ula'elek in Durotar.",
}
T[1840] = {
  title = "Orm Stonehoof e il Brutal Helm",
  desc = "Il brutal helm te lo forgerà Orm Stonehoof, che è molto rispettato per la sua abilità.$B$BLo trovi a Thunder Bluff, al centro della città, vicino alla pozza accanto al grande totem.",
  obj = "Parla con Orm Stonehoof a Thunder Bluff.",
  reward = "Salute, $C. Io sono Orm. Thun'grim mi ha detto che desideri farti forgiare un elmo, è così?",
  en_title = "Orm Stonehoof and the Brutal Helm",
  en_obj = "Speak with Orm Stonehoof in Thunder Bluff.",
}
T[1841] = {
  title = "Velora Nitely e i Brutal Legguards",
  desc = "Dicono che da viva Velora Nitely fosse tra le migliori fabbricanti di armature di Lordaeron, e a quanto pare la morte non le ha intaccato il talento. Parla con Velora — i tuoi brutal legguards te li fabbricherà lei.$B$BVelora lavora nell'Undercity of Lordaeron, nel quartiere del commercio.",
  obj = "Parla con Velora Nitely a Undercity.",
  reward = "Sei qui per un'armatura per le gambe? Fantastico!$B$BUhm... sono io che ti faccio l'armatura, o sei tu che la fai a me?$B$BEra una battuta. Fa ridere? Non saprei... Il senso dell'umorismo l'ho perso insieme all'olfatto, più o meno quando ho smesso di respirare.",
  en_title = "Velora Nitely and the Brutal Legguards",
  en_obj = "Speak with Velora Nitely in the Undercity.",
}
T[1842] = {
  title = "Zoccoli di Satiro",
  desc = "Posso forgiarti un paio di brutal gauntlets che racchiuderanno una grande magia. Ma prima quella magia devi raccoglierla e portarmela.$B$BI satiri dimorano nel nord-est di Ashenvale, attirati dal potere della foresta. Si nutrono della sua purezza: la succhiano e la corrompono. Quali satiri hanno attinto di più alla magia di Ashenvale lo capisci dagli zoccoli, gonfi e uniti.$B$BIn questi zoccoli è racchiuso un grande potere, e mi serviranno per forgiare i tuoi guanti.",
  obj = "Porta 7 Uncloven Satyr Hooves a Ula'elek a Sen'jin Village, in Durotar",
  progress = "Ce li hai, gli zoccoli, $N? La magia che racchiudono è forte.",
  reward = "Ah, ce li hai! Ora, come i Satiri hanno succhiato la forza di Ashenvale, io succhierò il potere racchiuso in questi zoccoli e lo imbriglierò nel mio lavoro...",
  en_title = "Satyr Hooves",
  en_obj = "Bring 7 Uncloven Satyr Hooves to Ula'elek at Sen'jin Village in Durotar.",
}
T[1843] = {
  title = "Brutal Gauntlets",
  reward = "Grazie, $N. Questi guanti sono il mio lavoro migliore. Prendili. Indossandoli, farai onore a me e ai miei antenati.",
  en_title = "Brutal Gauntlets",
}
T[1844] = {
  title = "Corno di Chimera",
  desc = "L'elmo te lo forgerò, ma devi dimostrarmi di esserne $Gdegno:degna;.$B$BNella parte nordoccidentale delle Stonetalon Mountains si nasconde la Charred Vale. Un tempo era verdeggiante; ora è profanata e coperta di cenere, e le creature che ci sono rimaste sono impazzite di dolore e disperazione.$B$BÈ lì che ti mando, $N.$B$BVa' nella Charred Vale e trova una chimaera matriarch. Uccidila e liberala così dalla sofferenza. Come prova portami il galvanized horn, e io forgerò il tuo elmo.",
  obj = "Porta un Galvanized Horn a Orm Stonehoof a Thunder Bluff.",
  progress = "Hai il corno? La matriarca ha smesso di soffrire?",
  reward = "Hai portato a termine il compito, $N, dimostrandomi valore e determinazione. L'elmo sarà tuo...",
  en_title = "Chimaeric Horn",
  en_obj = "Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff.",
}
T[1845] = {
  title = "Brutal Helm",
  reward = "Ti do questo elmo.$B$BSono state grandi imprese a portarti da me, $N, e se la Madre Terra vorrà... te ne attendono di ancora più grandi.",
  en_title = "Brutal Helm",
}
T[1846] = {
  title = "Dragonmaw Shinbones",
  desc = "Per fabbricare i brutal leg guards mi serve un paio di ossa robuste. Gli orchi Dragonmaw delle Wetlands le hanno belle spesse: mi servono le loro.$B$BMa che siano robuste, mi raccomando. Mettile alla prova mentre le raccogli: se riesci a spezzarle a mani nude, sono troppo fragili per lavorarci.",
  obj = "Porta 8 Sturdy Dragonmaw Shinbones a Velora Nitely a Undercity.",
  progress = "Aspetto ancora quelle ossa, $N. Faranno da buona struttura ai tuoi gambali.",
  reward = "Ben fatto! Mi sembrano tutte robuste, credo che andranno proprio bene. E quegli orchi come l'hanno presa, quando gli hai portato via gli stinchi, $N? Si sono lamentati tanto?$B$BEra un'altra battuta. Non ridi.$B$BNon sono molto divertente, di questi tempi, vero...",
  en_title = "Dragonmaw Shinbones",
  en_obj = "Bring 8 Sturdy Dragonmaw Shinbones to Velora Nitely in the Undercity.",
}
T[1847] = {
  title = "Brutal Legguards",
  reward = "Ecco i tuoi gambali, $N. Dimmi come ti stanno, o se c'è qualcosa da sistemare. Vivo per accontentare i clienti! O almeno, una volta era così.$B$BAdesso il mestiere non mi importa più di tanto. Ma è sempre meglio che essere una servitrice senza cervello dello Scourge!$B$BCredo.",
  en_title = "Brutal Legguards",
}
T[1848] = {
  title = "Brutal Hauberk",
  reward = "Sono certo che per il mio incarico hai sopportato molte difficoltà e versato molto sangue, $N. Ecco il frutto della tua fatica.$B$BChe tu possa farne buon uso, e tornare qui un giorno a raccontarmi come ti ha servito.",
  en_title = "Brutal Hauberk",
}
T[1858] = {
  title = "La Mano Spezzata",
  desc = "Lascio a te il compito di aprire la bisaccia di Tazan e di tornare da me con il contenuto. Il meccanismo della serratura è complesso, quindi probabilmente la cosa più semplice sarebbe procurarti la chiave.$B$BVisto che non l'hai trovata sul cadavere di Tazan, posso solo supporre che l'abbia affidata a qualcun altro... Ah, sì, ma certo. Aveva un assistente di nome Gamon. È un ubriacone: con ogni probabilità lo troverai alla taverna. Forse potresti alleggerirlo della chiave senza dare nell'occhio.",
  obj = "Ruba la chiave di Tazan, poi usala per aprire la sua Bisaccia e consegna il contenuto a Therzok nella Cleft of Shadow a Orgrimmar.",
  progress = "Non è irritante avere a un passo ciò che desideri, senza poterci arrivare?",
  reward = "Hmmm, questo sì che è interessante. Così hai più che dimostrato il tuo valore, $N. Sono davvero colpito. Da oggi considerati un membro della Mano Spezzata. E prendi questo: credo che in futuro ti sarà di grande aiuto.",
  en_title = "The Shattered Hand",
  en_obj = "Steal Tazan's key, then use it to open his Satchel and deliver its contents to Therzok in the Cleft of Shadow in Orgrimmar.",
}
T[1859] = {
  title = "Therzok",
  desc = "Abbassa la voce, $N. Sì, so come ti chiami. Mi hanno detto di cercare $Gun orco:un'orchessa; che corrisponde alla tua descrizione.$B$BDa quel che abbiamo sentito sul tuo conto, in combattimento sai cavartela, e ogni tanto un sotterfugio non ti dispiace.$B$BHo ragione?$B$BComunque, dovresti andare da Therzok a Orgrimmar. Ha una proposta da farti.",
  obj = "Parla con Therzok nella Cleft of Shadow a Orgrimmar.",
  reward = "Molto bene, sono lieto che Kaplak sia riuscito a rintracciarti.$B$BAbbiamo alcune cose di cui parlare, a cominciare dal tuo futuro nella Mano.",
  en_title = "Therzok",
  en_obj = "Speak with Therzok in the Cleft of Shadow in Orgrimmar.",
}
T[1860] = {
  title = "Parla con Jennea",
  desc = "Noi maghi abbiamo un compito da portare a termine. Un compito vitale per la sicurezza di Stormwind e della foresta di Elwynn.$B$BJennea Cannon conosce i dettagli. Studia nel santuario arcano, nel quartiere dei maghi di Stormwind. Dovresti raggiungerla senza indugio.",
  obj = "Parla con Jennea Cannon a Stormwind.",
  reward = "Sei $Gstato mandato:stata mandata; ad aiutarmi nel mio compito, $N? Bene. È confortante vedere giovani maghi desiderosi di sostenere la nostra causa...$B$BQuale causa, mi chiedi? A tempo debito, giovane. Lo saprai... a tempo debito.",
  en_title = "Speak with Jennea",
  en_obj = "Speak with Jennea Cannon in Stormwind.",
}
T[1861] = {
  title = "Mirror Lake",
  desc = "Questo mondo è stato vittima di immani lotte mistiche, che hanno strappato le correnti magiche dai canali in cui un tempo scorrevano stabili. Ci sforziamo di capire quali effetti abbiano prodotto questi cambiamenti, e alcuni di noi temono il peggio!$B$BMa ti rivelerò di più in seguito. Adesso abbiamo bisogno che tu raccolga informazioni.$B$BEcco, prendi questa fiaschetta. Va' ai piedi della cascata del Mirror Lake, a sud-ovest delle porte di Stormwind, e preleva un campione dell'acqua. Portamelo, così potrò analizzarlo in cerca di contaminazioni magiche.",
  obj = "Porta a Jennea Cannon, a Stormwind, un campione di Mirror Lake.",
  progress = "Hai il campione, $N? Il flusso della magia a Stormwind e a Elwynn è cambiato, e devo sapere se sta filtrando nell'acqua.",
  reward = "Grazie, $N. Analizzerò quest'acqua per verificarne le proprietà magiche. Speriamo che non ci sia traccia di magia, altrimenti potremmo scoprire che chi beve troppo a lungo dal Mirror Lake ne risente.$B$BEcco, $N. Prendi questo globo o questo bastone in segno di riconoscenza per il tuo servizio. Che ti sia utile.",
  en_title = "Mirror Lake",
  en_obj = "Bring a Mirror Lake sample to Jennea Cannon in Stormwind.",
}
T[1878] = {
  title = "Taglia sugli Otri d'Acqua",
  progress = "Di nuovo qui, $N? Se hai altri cinque otri d'acqua dei Wastewander, ho qui un pacco assistenza con sopra il tuo nome!",
  reward = "Eccellente — più otri d'acqua recuperiamo, più ci teniamo tutti lontani dal disastro! Continua a portarmeli: per ogni cinque che mi consegni, una ricompensa te la do di sicuro.",
}
T[1879] = {
  title = "Parla con Bink",
  desc = "$N! Bink, la mia collega gnoma a Ironforge, manda a dire che ha un compito da svolgere e non vuole affidarlo a nessuno che non sia $Gun mago:una maga;! Sei tu $Gquel mago:quella maga;, $N?$B$BSe è così, parla con Bink. Passa le giornate nell'Hall of Mysteries, nel Mystic Ward of Ironforge.",
  obj = "Parla con Bink a Ironforge.",
  reward = "Oh, vedo che hai del potenziale, sì, ne sono certa! Ma per essere $Gun buon mago:una brava maga; ci vuole più del potenziale. E se non sei $Gun buon mago:una brava maga;, allora sei $Gun pessimo mago:una pessima maga;. E i pessimi maghi fanno parte del problema, sì che ne fanno parte!$B$BOps, sto correndo troppo. Cominciamo dall'inizio!",
  en_title = "Speak with Bink",
  en_obj = "Speak with Bink in Ironforge.",
}
T[1880] = {
  title = "Mage-tastic Gizmonitor",
  desc = "Noi maghi non ci limitiamo ad agitare le dita e a fare belle scintille! Controlliamo la magia, il tessuto stesso del nostro mondo! E questo richiede grande attenzione e determinazione. E conoscenza... tanta, tantissima conoscenza!$B$BUno dei miei congegni, il Mage-tastic Gizmonitor, raccoglie e conserva enormi quantità di conoscenza! Ma l'ho perso! Quando siamo fuggiti da Gnomeregan, la nostra casa, l'ho lasciato in un forziere, dentro una delle nostre capanne fuori città, e adesso la zona brulica di leper gnomes!$B$BTi prego, $N, recuperami il gizmonitor!",
  obj = "Porta a Bink il suo Mage-tastic Gizmonitor.",
  progress = "Hai trovato il gizmonitor? Mi serve prima che si scarichi!",
  reward = "Oh, che giornata splendida! Quando ho costruito il gizmonitor non avrei mai immaginato quanto ne sarei diventata dipendente. Ora posso riprendere i miei studi!$B$BGrazie, $N! Ed ecco — questi erano i miei primi strumenti da maga. Sono un po' graffiati, ma collaudati alla perfezione. Scegli quello che vuoi — sono sicura che li troverai utili tutti e due.",
  en_title = "Mage-tastic Gizmonitor",
  en_obj = "Bring Bink her Mage-tastic Gizmonitor.",
}
T[1881] = {
  title = "Parla con Anastasia",
  desc = "$N, Anastasia Hartwell ha un compito per qualcuno con il tuo talento. Va' a parlarle nel Magic Quarter of the Undercity e preparati al tuo primo incarico per i maghi dei Forsaken.",
  obj = "Parla con Anastasia Hartwell.",
  reward = "Saluti, $N. Sei $Gstato saggio:stata saggia; a rispondere alla mia chiamata, e lo sarai ancora di più se darai ascolto a quello che sto per dirti...",
  en_title = "Speak with Anastasia",
  en_obj = "Speak with Anastasia Hartwell.",
}
T[1882] = {
  title = "La Balnir Farmstead",
  desc = "Le Plaguelands a est sono un'aberrazione. Create da The Lich King, diffondono la loro magia nel suolo, corrompendo e uccidendo tutto ciò che vive. Per quanto le forze distruttive della piaga abbiano un certo fascino, noi maghi dei Forsaken la consideriamo fuori controllo, da tenere a freno.$B$BMa prima dobbiamo misurare fin dove si è spinta in Tirisfal. Raggiungi la Balnir Farmstead, nella parte orientale di Tirisfal. Nel giardino ci sono dei fiori — bocche di leone. Raccoglile e torna qui.",
  obj = "Porta le Balnir Snapdragons ad Anastasia Hartwell in Mage Quarter of the Undercity.",
  progress = "Hai le bocche di leone? È una varietà molto ricettiva alle energie magiche: studiando gli esemplari che crescono così vicino alle Plaguelands potremo capire se la piaga è arrivata nelle Tirisfal Glades.",
  reward = "Ah, questo sì che è un bell'esemplare. Lo manderò ai nostri speziali perché lo studino e stabiliscano fin dove arriva la contaminazione delle Plaguelands.$B$BBen fatto, $N. Come ricompensa per i tuoi servigi puoi scegliere: un globo o un bastone. Qualunque sceglierai, ti tornerà molto utile.",
  en_title = "The Balnir Farmstead",
  en_obj = "Bring Balnir Snapdragons to Anastasia Hartwell in the Mage Quarter of the Undercity.",
}
T[1883] = {
  title = "Parla con Un'thuwa",
  desc = "Un'thuwa, il mago tribale di Sen'jin Village, avverte una perturbazione nelle correnti magiche di Durotar e cerca aiuto. Va' a parlare con Un'thuwa e fa' tutto quello che puoi per aiutarlo.$B$BFallo e, col tempo, altri segreti ti saranno rivelati.",
  obj = "Parla con Un'thuwa.",
  reward = "Salute, $N. Lode a te, perché ora la mia richiesta d'aiuto ha avuto risposta. Speriamo che tu sia all'altezza del compito...",
  en_title = "Speak with Un'thuwa",
  en_obj = "Speak with Un'thuwa.",
}
T[1884] = {
  title = "Cumuli di Ju-Ju",
  desc = "Lo stregone Zalazane of the Echo Isles ha sconvolto il normale flusso della magia in Durotar. Ci è riuscito con dei feticci contaminati, i cumuli di ju-ju, che ha sistemato fra le sue capanne sull'Echo Isle principale.$B$BQuesti cumuli corrompono i nostri animali e danno potere agli stregoni e alle creature infernali nascoste negli angoli bui di questa terra.$B$BDevi distruggere i cumuli di ju-ju, $N, prima che il flusso della magia resti alterato per sempre.",
  obj = "Distruggi 4 Cumuli di Ju-Ju, poi torna da Un'thuwa a Sen'jin Village.",
  progress = "Devi fare in fretta, $N. Distruggi i cumuli di ju-ju!",
  reward = "Sento che i cumuli di ju-ju di Zalazane sono stati distrutti e che, col tempo e un po' di fortuna, il flusso della magia in Durotar tornerà normale.$B$BUna grande impresa hai compiuto per il tuo popolo, $N. E a noi maghi dell'Orda hai dimostrato il tuo valore.",
  en_title = "Ju-Ju Heaps",
  en_obj = "Destroy 4 Ju-Ju Heaps, then return to Un'thuwa in Sen'jin Village.",
}
T[1885] = {
  title = "Mennet Carkad",
  desc = "$N? Non proprio quello che mi aspettavo, visto che Carkad in persona si è interessato a te. Ma l'apparenza inganna, giusto?$B$BIn ogni caso, dovresti andare da lui il prima possibile. Meglio che tu non sappia che fine hanno fatto gli ultimi che hanno deciso di ignorare la sua convocazione.",
  obj = "Parla con Mennet Carkad in Rogues' Quarter of the Undercity.",
  reward = "Hm. Di certo sei $Gvenuto:venuta; qui appena hai saputo della mia convocazione, vero? Ma certo. Non mi aspetterei niente di meno da $Gun aspirante:un'aspirante; Inseguimorte.",
  en_title = "Mennet Carkad",
  en_obj = "Speak with Mennet Carkad in the Rogues' Quarter of the Undercity.",
}
T[1886] = {
  title = "Gli Inseguimorte",
  desc = "Se vuoi unirti agli Inseguimorte, la guardia scelta di Lord Varimathras, dovrai dimostrare il tuo valore.$B$BNon ti mentirò, $N, questo compito potrebbe costarti la vita.$B$BHo alcune questioni da sistemare. Mi servono gli effetti personali di Astor Hadren, un messaggero che fa la spola tra Silverpine e Undercity. Come procurarteli, lo lascio decidere a te.$B$BMeno sai della natura di questa faccenda, meglio è per te. Se ci riesci, ti dirò di più.",
  obj = "Prendi Astor's Letter of Introduction e portala a Mennet Carkad nel Rogues' Quarter.",
  progress = "Hai buone notizie?",
  reward = "Ben fatto, $N. Hai superato la prima parte della prova. Spero che Andron non abbia avuto sentore di ciò che hai fatto e che riusciremo a convincerlo che sei davvero $Gil messaggero:la messaggera; che aspetta.",
  en_title = "The Deathstalkers",
  en_obj = "Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter.",
}
T[1898] = {
  title = "Gli Inseguimorte",
  desc = "La lettera di presentazione dovrebbe bastare a convincere Andron che sei $Gil messaggero:la messaggera; che stava aspettando. L'ho già incontrato, e non ha proprio il cervello per essere così diffidente.$B$BLord Varimathras sospetta che Andron stia aiutando un altro gruppo. Vuole sapere di quale organizzazione si tratti e ne pretende le prove.$B$BVoglio che tu vada a parlargli e ottenga queste informazioni. Lo troverai nella sua bottega, vicino all'Apothecarium.",
  obj = "Parla con Andron Gant in Undercity.",
  progress = "Salve. Posso fare qualcosa per te?",
  reward = "Ah, sì, ti stavo aspettando. Immagino che i nostri comuni conoscenti siano soddisfatti delle informazioni che ho fornito finora?$B$BSuppongo sia inutile chiederlo a te, dubito che ti caricherebbero del peso di saperlo. Perché riporre tanta fiducia nel messaggero, eh?",
  en_title = "The Deathstalkers",
  en_obj = "Speak with Andron Gant in the Undercity.",
}
T[1899] = {
  title = "Gli Inseguimorte",
  desc = "Il registro con le informazioni che cercano i tuoi datori di lavoro è sullo scaffale alle mie spalle. Consegnalo con i miei omaggi e di' loro che, se lo troveranno abbastanza prezioso da voler continuare il nostro accordo, preferirei che mandassero te.",
  obj = "Porta il registro di Astor a Mennet Carkad in Rogues' Quarter of Undercity.",
  progress = "Ce l'hai fatta, $N?",
  reward = "Be', sono decisamente più informazioni di quante pensassi di cavare da Andron. Dammi un momento per esaminarle, prima di affidarti il prossimo compito.",
  en_title = "The Deathstalkers",
  en_obj = "Bring Andron's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity.",
}
T[1918] = {
  title = "L'Elemento Contaminato",
  desc = "Dall'elementale ucciso è venuto fuori un globe of water che brilla intensamente. Quello che contiene è disgustoso, nel migliore dei casi. È molto probabile che qualunque cosa abbia contaminato le acque del Mystral Lake si trovi anche nell'acqua del globo.$B$BNon è chiaro chi potrebbe interessarsi a una scoperta del genere. Forse ne ha un'idea chi ti ha mandato al lago: Mastok Wrilehiss, allo Splintertree Post.",
  obj = "Porta il Befouled Water Globe a Mastok Wrilehiss a Splintertree Post, Ashenvale.",
  progress = "Sì, che ti serve?",
  reward = "Trovi una schifosa palla d'acqua e pensi bene di portarla a me? Ma per chi mi hai preso, per l'Earthen Ring?$B$BA pensarci bene, mi viene un'idea... forse per questa faccenda è proprio l'Earthen Ring quello che ti serve. Insomma, se aiuta a sistemare una volta per tutte la situazione al lago, ben venga.$B$BSai chi è l'Earthen Ring, $N?",
  en_title = "The Befouled Element",
  en_obj = "Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale.",
}
T[1919] = {
  title = "Presentati da Jennea",
  desc = "Le tue conoscenze dell'arte crescono, giovane $N. Ora sei $Gpronto:pronta; a cominciare le vere lezioni? Sei $Gpronto:pronta; a prendere il tuo posto nella guerra segreta che combattiamo?$B$BSe è così, parla con Jennea Cannon al santuario degli stregoni, nel quartiere dei maghi di Stormwind. Ha un compito per te che ti offrirà un primo scorcio del mondo invisibile.",
  obj = "Parla con Jennea Cannon a Stormwind.",
  reward = "$N, ho una missione per te, qui nel quartiere dei maghi. Ascolta attentamente, non c'è tempo da perdere.",
  en_title = "Report to Jennea",
  en_obj = "Speak with Jennea Cannon in Stormwind.",
}
T[1920] = {
  title = "Indaga al Blue Recluse",
  desc = "Hanno segnalato un'anomalia alla taverna Blue Recluse, nel Mage Quarter. Ora per il locale si aggirano strane creature invisibili, e temo che vi si sia aperta una fenditura di mana.$B$BVoglio che tu vada a indagare alla taverna e catturi quelle creature. Una volta dentro, usa il cantation of manifestation per renderle visibili, poi sottomettile e rinchiudile in uno scrigno di contenimento. Quando ne avrai catturate a sufficienza, torna da me con gli scrigni pieni, quelli vuoti e il canto.",
  obj = "Prendi un Cantation of Manifestation e un Chest of Containment coffers dietro Jennea Cannon. Porta 3 Filled Containment Coffers a Jennea in Wizard's Sanctum.",
  progress = "Hai catturato le creature, $N? Dobbiamo studiarle per capire perché sono arrivate.",
  reward = "Davvero ben fatto! Studierò queste creature e, con diligenza e un po' di fortuna, scoprirò come sono scivolate nel nostro mondo.$B$BPer la società dei maghi vali sempre di più, $N.",
  en_title = "Investigate the Blue Recluse",
  en_obj = "Obtain a Cantation of Manifestation and a Chest of Containment coffers from behind Jennea Cannon.  Bring 3 Filled Containment Coffers to Jennea at the Wizard's Sanctum.",
}
T[1921] = {
  title = "Raccolta di Materiali",
  desc = "Hai servito bene i tuoi confratelli maghi, e ora è il momento di indossare la veste da stregone. Wynne Larson può confezionartela, ma devi portarle i materiali necessari  $B$BSarà di lino, che si trova facilmente, ma dovrai procurarti anche delle charged rift gems, e l'unico posto noto dove trovarle è la Silver Stream Mine of Loch Modan: la lega dei minatori nanici le ha lasciate lì in alcune casse.$B$BRaccogli il lino e le gemme e portali a Wynne Larson, ai Larson Clothiers nel Mage District.",
  obj = "Porta 10 pezze di Lino e le 6 Charged Rift Gems a Wynne Larson a Stormwind.",
  progress = "Ciao, $N. Jennea mi aveva detto che saresti $Gvenuto:venuta;. Hai qualcosa per me?",
  reward = "Sì, sono ottime pezze di lino. Ci posso fare una bella veste. E dopo averci intessuto le gemme delle fenditure, avremo un abito degno di un mago!",
  en_title = "Gathering Materials",
  en_obj = "Bring 10 Linen Cloth and the 6 Charged Rift Gems to Wynne Larson in Stormwind.",
}
T[1938] = {
  title = "Ur's Treatise on Shadow Magic",
  desc = "Molto tempo fa in questa torre studiavano tre maghi, finché uno di loro ha ceduto alle arti oscure. Lo hanno esortato ad allontanarsi da quella magia malvagia, ma non è riuscito a resistere, e così è stato bandito.$B$BOra il mago caduto ha come nuovo dominio la torre di Ilgalar a Redridge, e ha portato con sé un libro potente — l'Ur's Treatise on Shadow Magic.$B$BNoi maghi di Stormwind vorremmo riavere quel libro. Entra nella torre di Ilgalar, trova il tomo nella sua biblioteca e portamelo.",
  obj = "Porta l'Ur's Treatise on Shadow Magic a High Sorcerer Andromath a Stormwind.",
  progress = "Hai il libro, $N? I suoi segreti non sono per chi non ha l'addestramento giusto: scandagliarne le profondità può portare alla perdizione e alla rovina.",
  reward = "Temevo che Morganth avesse nascosto il libro da qualche altra parte, o che avesse trovato il modo di aprirlo e leggerlo.$B$BChe sollievo vedere che non è andata così, e che i sigilli che abbiamo posto sull'Ur's Treatise on Shadow Magic reggono ancora.",
  en_title = "Ur's Treatise on Shadow Magic",
  en_obj = "Bring Ur's Treatise on Shadow Magic to High Sorcerer Andromath in Stormwind.",
}
T[1939] = {
  title = "High Sorcerer Andromath",
  desc = "High Sorcerer Andromath desidera parlarti, $N. Lo trovi in cima al santuario dei maghi, nel loro quartiere di Stormwind.$B$BSarebbe saggio andare da lui: Andromath è uno dei maghi più potenti fra quelli che non stanno rinchiusi a Dalaran, e un suo consiglio vale davvero molto.",
  obj = "Parla con High Sorcerer Andromath.",
  reward = "Saluti, $N. Sono lieto di vederti. Spero che tu abbia il tempo di ascoltare le parole di un vecchio...",
  en_title = "High Sorcerer Andromath",
  en_obj = "Speak with High Sorcerer Andromath.",
}
T[1940] = {
  title = "Pristine Spider Silk",
  desc = "Hai servito con dedizione incrollabile, $N, e credo che forse sia giunto il momento di darti un abito più raffinato, più adatto al tuo rango di $Gmago esperto:maga esperta;. Se raccoglierai tu i materiali che servono, a farti confezionare la veste penseremo noi.$B$BDevi andare a Duskwood a cacciare i ragni carrion recluse e prenderne la seta, ma va bene solo quella più fine e intatta. Quando ne avrai abbastanza, portala a Wynne Larson, ai Larson Clothiers, qui nel quartiere dei maghi: sarà lei a cucirti la veste.",
  obj = "Porta 8 pezzi di Pristine Spider Silk a Wynne Larson a Stormwind.",
  progress = "Ah, sì. I maghi del Wizard's Sanctum mi avevano detto che saresti $Gpassato:passata; da me. Hai la seta che ti hanno chiesto?",
  reward = "Begli esemplari, questi. Mi metto subito al lavoro!",
  en_title = "Pristine Spider Silk",
  en_obj = "Bring 8 Pristine Spider Silk to Wynne Larson in Stormwind.",
}
T[1941] = {
  title = "Manaweave Robe",
  reward = "Ecco la tua tonaca. È una delle migliori che abbia mai cucito! Portala con orgoglio, e quando te lo chiedono... di' che l'hai presa ai Larson Clothiers!",
  en_title = "Manaweave Robe",
}
T[1942] = {
  title = "Veste del Nodo Astrale",
  reward = "La tua veste è pronta! E la seta che hai raccolto era così bella... non ti dispiace se l'ho tagliata un po' corta per farmene avanzare un po', vero?$B$BSto scherzando. Ti starà benissimo, e sarà perfetta sia in avventura sia alle cene eleganti. Goditela!",
  en_title = "Astral Knot Garment",
}
T[1943] = {
  title = "Parla con Deino",
  desc = "$N, la maga troll Deino ha bisogno del tuo aiuto. Vive a Orgrimmar, nel Darkbriar Lodge.",
  obj = "Parla con Deino.",
  reward = "Bene, sei $Gvenuto:venuta;. Quello che devo fare non è facile, ma per la società dei maghi è vitale. Se mi darai una mano, sono sicura che ne varrà la pena.",
  en_title = "Speak with Deino",
  en_obj = "Speak with Deino.",
}
T[1944] = {
  title = "Acque di Xavian",
  desc = "Nel cuore della parte orientale dell'Ashenvale si nasconde la leggendaria città di Xavian, e fra i dotti le storie sulla sua antica sapienza sono ben note. Si dice che le acque di Xavian racchiudano immensi poteri magici.$B$BVorrei un campione di quell'acqua, preso alla fonte.$B$BPrendi questa fiaschetta e va' a Xavian: raccogli l'acqua ai piedi della cascata più alta e poi torna da me. E quando attraversi l'antica città fa' attenzione — ora le rovine sono in mano ai satiri, e ai satiri i maghi che ficcano il naso nei loro affari non piacciono.",
  obj = "Porta lo Xavian Water Sample a Deino a Orgrimmar.",
  progress = "Sono contenta che tu sia $Gtornato sano e salvo:tornata sana e salva;, $N. Ce l'hai il campione d'acqua? Non vedo l'ora di studiarne le proprietà.",
  reward = "Ah, molto bene. I satiri di Xavian non ti avranno dato troppi problemi, spero?$B$BGrazie, $N. Mi metto subito a studiare questo campione d'acqua di Xavian.",
  en_title = "Waters of Xavian",
  en_obj = "Bring the Xavian Water Sample to Deino in Orgrimmar.",
}
T[1945] = {
  title = "Laughing Sisters",
  desc = "Per ripagarti dei tuoi servigi ho fatto in modo che ti confezionino delle vesti nuove, a patto che tu riesca a procurarti i materiali...$B$BPer farle dovrai tornare nell'Ashenvale a prendere le ciocche di capelli delle laughing sisters — driadi che si radunano vicino al Raynewood Retreat.$B$BQuando avrai i capelli, portali a Kil'hala, un sarto troll che sta al Crossroads, nella Barrens: ti aspetterà e ti cucirà le vesti.",
  obj = "Porta 12 Laughing Sister's Hairs a Kil'hala al Crossroads.",
  progress = "Salute, $N. Deino mi ha detto che saresti $Gvenuto:venuta; con i capelli delle laughing sisters. Ce li hai?",
  reward = "Ah, con questi capelli verrà fuori una bella veste, $N. Peccato che le laughing sisters siano dovute morire per separarsene, anche se dubito che li avrebbero mai dati via di loro volontà.$B$BUn peccato, ma piccolo.",
  en_title = "Laughing Sisters",
  en_obj = "Bring 12 Laughing Sister's Hairs to Kil'hala at the Crossroads.",
}
T[1946] = {
  title = "Indumento di Pizzo Fatuo",
  reward = "Ecco il tuo pizzo fatuo, $N. È comodo e resistente, e dentro c'è la magia dei capelli delle laughing sisters.$B$BGoditelo, e se ti piace, fallo sapere a Deino, per favore. È una maga con cui voglio restare in buoni rapporti...",
  en_title = "Nether-lace Garment",
}
T[1947] = {
  title = "Viaggio nella Palude",
  desc = "È arrivato il momento di guadagnarti la bacchetta da mago. Per cominciare la missione, parla con l'eremita umana Tabetha, nella Dustwallow Marsh: troverai la sua baracca nel cuore della palude, a ovest di Theramore.$B$BParlale, perché sa moltissime cose. Troverai la casetta di Tabetha a ovest di Theramore, appena a nord delle Stonemaul Ruins.",
  obj = "Parla con Tabetha.",
  reward = "Silenzio! Questo è un momento delicato, nessuno deve disturbarmi!$B$BUn attimo...",
  en_title = "Journey to the Marsh",
  en_obj = "Speak with Tabetha.",
}
T[1948] = {
  title = "Oggetti di Potere",
  desc = "Creare la bacchetta di un mago non è facile: servono sostanze rare, e bisogna costruire un recipiente capace di contenere grandi quantità di energia magica. Devi raccogliere queste cose e portarmele.$B$BSu questa pergamena ho scritto cosa ti serve e come procurartelo. Portami esattamente quello che c'è in questa lista e segui le indicazioni alla lettera, perché se non lo fai, quando creeremo la tua bacchetta le cose potrebbero andare... male.",
  obj = "Porta 1 Jade e il Bolt Charged Bramble a Tabetha in Dustwallow Marsh.",
  progress = "Ciao, $N. Ce li hai, gli oggetti che mi servono?",
  reward = "Aha! Hai preso la giada e creato il rovo! Ben fatto!$B$BQuello che ti esce dalle orecchie è fumo? Forse ti sei $Gavvicinato:avvicinata; troppo quando il fulmine ha colpito i bastoncini totem, ma non preoccuparti. Essere colpiti da un fulmine porta fortuna!",
  en_title = "Items of Power",
  en_obj = "Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh.",
}
T[1949] = {
  title = "Segreti Nascosti",
  desc = "Per creare la tua bacchetta devo leggere alcuni passaggi fondamentali di un libro preciso: si intitola Rituals of Power e l'ha scritto il Magus Tirth.$B$BIo non ne ho una copia, e non ce l'ha nessuna delle grandi biblioteche del mondo. Dovrai parlare con Tirth e fartelo dare da lui.$B$BBuona fortuna. Un tempo Tirth era un grande mago e studioso, ma oggi passa le giornate a bere e a scommettere alle corse degli gnomi e dei goblin, nelle Shimmering Flats.",
  obj = "Parla con il Magus Tirth in Shimmering Flats.",
  reward = "Cosa? Parla più forte! Queste vecchie orecchie non sentono più come una volta.$B$BBeh, spero che tu mi abbia portato un boccale di birra fresca o una buona soffiata sulla prossima corsa! Altrimenti ti conviene tirare dritto... perché ho una bacchetta della metamorfosi con sopra il tuo nome!",
  en_title = "Hidden Secrets",
  en_obj = "Speak with Magus Tirth in the Shimmering Flats.",
}
T[1950] = {
  title = "Parola d’ordine?",
  desc = "Posso aiutarti con il libro, ma prima devi aiutare me!$B$BIl tomo che cerchi è nel mio forziere a chiusura arcana. Per aprirlo bisogna pronunciare una frase specifica, e non me la riesco a ricordare! Di solito è il mio assistente ad aiutarmi con queste cose, ma non si vede da nessuna parte.$B$BSe vuoi il mio libro, allora trova il mio apprendista! Chiedi in giro vicino alla pista — con un po' di fortuna, qualcuno l'avrà visto. Trascinalo qui, o almeno fatti dire quella frase magica, così possiamo aprire il forziere!",
  obj = "Trova la frase che apre il forziere di Tirth, poi torna da Tirth.",
  progress = "Cosa aspetti? Mi serve la mia frase magica!",
  reward = "Ah, ora ricordo...$B$BMi ero dimenticato di quella piccola maledizione che ho lanciato su Johnson. Non ricordo perché l'ho fatto, ma di sicuro se l'era meritata, quel piccolo ingrato!",
  en_title = "Get the Scoop",
  en_obj = "Find the phrase to Tirth's strongbox, then return to Tirth.",
}
T[1951] = {
  title = "Rituals of Power",
  desc = "Mm... a pensarci bene, il libro non ce l'ho! Vedi, avevo qualche debito di gioco, e per saldarlo ho venduto l'ultima copia di Rituals of Power a un membro del clero....$B$BUno della Scarlet Brotherhood. Deve averlo portato nella loro biblioteca, nello Scarlet Monastery, nelle Tirisfal Glades!$B$BSe vuoi quel libro, dovrai andare a cercarlo al monastero. E scusami per tutto il disturbo. Di questi tempi non sono più quello di una volta...",
  obj = "Porta il libro Rituals of Power a Tabetha in Dustwallow Marsh.",
  progress = "Salve, $N. Hai trovato il libro, Rituals of Power?",
  reward = "È proprio lui! Esattamente quello che mi serve per preparare il rituale che creerà la tua bacchetta! Spero che trovarlo non ti abbia dato troppo disturbo...",
  en_title = "Rituals of Power",
  en_obj = "Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.",
}
T[1952] = {
  title = "Bacchetta del Mago",
  desc = "Ora vado a creare le bacchette.",
  obj = "Parla con Tabetha dopo il suo rituale.",
  reward = "Ecco le bacchette che ho creato. Scegli pure!",
  en_title = "Mage's Wand",
  en_obj = "Speak with Tabetha after her ritual.",
}
T[1953] = {
  title = "Ritorno alla Palude",
  desc = "È giunto il momento di parlare con Tabetha, $N... l'eremita della Dustwallow Marsh. Sarà lei a insegnarti come si crea un potente strumento da mago.$B$BTabetha vive in una capanna nel cuore della Dustwallow Marsh, a ovest di Theramore.",
  obj = "Parla con Tabetha.",
  reward = "Ah, sì. Sei qui per un globo o per un bastone, $N? Molto bene, ti aiuterò a costruirlo.$B$BMa ti avverto — è un procedimento pericoloso, e potrebbe voler dire la tua morte.$B$BO la mia. Di sicuro la morte di qualcuno... $B$BMa speriamo che sia quella di qualcun altro, eh?",
}
T[1954] = {
  title = "L'Infernal Orb",
  desc = "Per prima cosa bisogna procurarsi un globo dotato di potere. Gli stregoni della Burning Blade ne hanno di belli, di ottima qualità... peccato che ci abbiano rinchiuso dentro dei demoni! Ma possiamo rimediare, sì che possiamo.$B$BVai a Desolace e ruba un infernal orb a un evocatore della Burning Blade: li troverai alla Mannoroc Coven.$B$BTorna da me quando avrai il globo.",
  obj = "Porta un Infernal Orb a Tabetha in Dustwallow Marsh.",
  progress = "Ce l'hai, l'infernal orb, $N?",
  reward = "Oh, che bel globo! No, non bello come è bello un succo fresco in una giornata calda.$B$BAnzi, a pensarci bene, adesso non è bello per NIENTE. Non il succo, il globo!$B$BConcentrati, $N! Se vogliamo finire il compito dovrai essere $Gconcentrato:concentrata;!",
}
T[1955] = {
  title = "L'Esorcismo",
  desc = "Ora che abbiamo il globo di un evocatore, bisogna esorcizzare il demone che ci sta dentro. A questo ci penso io: è la parte facile.$B$BQuella difficile tocca a te. Sei tu $Gquello:quella; che deve uccidere il demone, quando esce.$B$BE dovrai fare in fretta. Se ci metti troppo, tornerà a saltare dentro il globo e dovremo ricominciare da capo!$B$BQuindi preparati. Tieni pronti gli incantesimi più potenti e le pozioni a portata di mano, e se hai un amico portalo con te. Perché non sarà un bello spettacolo.",
  obj = "Uccidi il Demon of the Orb, poi parla con Tabetha.",
  progress = "Per togliere la corruzione dal globo dovrai uccidere quel demone, $N.",
  reward = "Ben fatto, $N! Hai dato a quel demone una lezione che non dimenticherà tanto presto.$B$BCi penserà due volte prima di rimettere la sua brutta testa in questo mondo per cercare $Glo stupido mortale:la stupida mortale; che l'ha battuto. E stavolta, probabilmente, con degli amici. Amici grossi e squamosi, che non vorrebbero altro che farti a pezzettini di $R.$B$BNon ti ho $Gspaventato:spaventata;, vero...$N?",
}
T[1956] = {
  title = "Potere a Uldaman",
  desc = "Ora che ci siamo liberati del demone, ci serve una sorgente energetica. Purtroppo le migliori sono di solito anche le più antiche e le più difficili da ottenere. Simpatico come a volte il destino si diverta a darti un morso, vero?$B$BPer questo dovrai andare a Uldaman a sconfiggere l'obsidian sentinel. È grossa, è resistente, e la sua sorgente energetica picchia duro!$B$BTi auguro tutta la fortuna del mondo, $N. E se la fortuna non ti assiste, be'... è stato bello conoscerti.",
  obj = "Recupera un'Obsidian Power Source e portala a Tabetha in Dustwallow Marsh.",
  progress = "Sei $Gstato:stata; a Uldaman, $N? L'hai sconfitta, l'obsidian sentinel?",
  reward = "Ce l'hai fatta? Ben fatto!$B$BStavo chiacchierando con dei colleghi e, quando è saltato fuori il tuo nome, mi hanno detto: \"Sai, $N sotto pressione lavora proprio bene!\"$B$BMa quando ho raccontato che ti avevo mandato a Uldaman contro l'obsidian sentinel, mi hanno detto che ero matta! Hanno detto: \"Tabetha, sei matta! È impossibile che $N riesca ad affrontare quella sentinella!\"$B$BE io ho risposto: \"Vedremo\", e loro: \"Sì, vedremo...\"$B$BBe', gliel'abbiamo fatto vedere eccome, eh!",
}
T[1957] = {
  title = "Mana Surges",
  desc = "Abbiamo quasi finito, $N, ma quest'ultimo passo è il più pericoloso.$B$BHo il globo vuoto dell'evocatore e sono pronta a potenziarlo sfruttando l'energia di una fenditura di mana. Con un incantesimo aprirò per un po' una fenditura, e da lì si riverseranno fuori delle creature: le mana surges. Tu devi sconfiggere le mana surges: così il loro potere si libererà e io lo raccoglierò.$B$BUccidi abbastanza mana surges prima che la fenditura si chiuda, e io metterò nel tuo globo tutta l'energia raccolta.",
  obj = "Uccidi 12 Mana Surges entro il tempo limite.",
  progress = "Le mana surges che hai ucciso non bastano, $N.",
  reward = "Ce l'hai fatta! Non ho mai dubitato di te, neanche per un secondo! Va be', forse per un secondo, o due... ma in fondo non avevo molti dubbi.$B$BDavvero.",
}
T[1958] = {
  title = "Potere Celeste",
  reward = "Dovresti essere $Gfiero:fiera; di te, $N. Davanti alle creature che hai affrontato sono caduti molti maghi.$B$BIl Celestial Orb è pronto. Oppure, se vuoi, posso montarlo in cima a un bastone: decidi tu. Io sceglierei il globo, ma chi sono io per giudicare?",
}
T[1959] = {
  title = "Rapporto ad Anastasia",
  desc = "I maghi di Undercity hanno notato un disturbo magico in città e hanno chiamato i colleghi dell'Orda a indagare.$B$BAnastasia Hartwell potrà dirti di più.  Va' a parlarle nel Magic Quarter di Undercity.",
  obj = "Parla con Anastasia Hartwell.",
  reward = "È vero.  Abbiamo rilevato un disturbo magico qui in città.  Non ne conosciamo ancora l'origine, né sappiamo se sia maligno o benigno.  Prima dobbiamo raccogliere altre informazioni...$B$BEd eccoci, $N, al tuo compito.",
  en_title = "Report to Anastasia",
  en_obj = "Speak with Anastasia Hartwell.",
}
T[1960] = {
  title = "Indagine nella Bottega dell'Alchimista",
  desc = "La bottega d'alchimia di Algernon, nell'Apothecarium, è il centro di uno strano disturbo.  Creature invisibili, fatte soltanto di magia, si aggirano per il negozio — ci dev'essere un motivo, e dobbiamo scoprirlo!$B$BIndaga sul disturbo e cattura quelle creature.  Prendi una cassa di scrigni e una pergamena qui dietro di me.  Usa la pergamena nella bottega per renderle visibili, sottomettile con i tuoi incantesimi, poi getta a terra uno scrigno per imprigionarle.  Torna con gli scrigni pieni, quelli vuoti e la formula.",
  obj = "Prendi un Cantation of Manifestation e un Chest of Containment Coffers da dietro Anastasia Hartwell.  Porta 3 Filled Containment Coffers, il Chest of Containment Coffers e il Cantation of Manifestation ad Anastasia a Undercity.",
  progress = "Hai indagato sull'anomalia, $N?  Hai catturato le creature?",
  reward = "Molto bene, $N.  Le menti migliori fra noi studieranno le creature racchiuse in questi scrigni di contenimento, e scopriremo perché si trovano a Undercity.$B$BSe la loro comparsa è dovuta a una frattura nel flusso naturale della magia, dovremo stabilire se si è aperta per caso.  Se invece dietro c'è l'attacco di qualche forza magica, dovremo prepararci ad altre anomalie in futuro, ancora più gravi.",
  en_title = "Investigate the Alchemist Shop",
  en_obj = "Obtain a Cantation of Manifestation and a Chest of Containment Coffers from behind Anastasia Hartwell.  Bring 3 Filled Containment Coffers, the Chest of Containment Coffers and the Cantation of Manifestation to Anastasia in the Undercity.",
}
T[1961] = {
  title = "Raccolta di Materiali",
  desc = "È ora che tu indossi le tue prime vesti da $Gmago:maga;, $N.  Sono un segno del tuo rango e una prova del tuo valore.$B$BPer ottenerle, dovrai prendere le gemme di mana ai maghi di Dalaran a Silverpine.  Le loro convinzioni sono simili alle nostre, quindi ucciderli è un po' sgradevole, ma se non hanno la forza di resisterci, non meritano di vivere.$B$BPorta le gemme e una scorta di lino a Josef Gregorian, nella sartoria del Magic Quarter.",
  obj = "Porta 10 pezzi di lino e 6 Dalaran Mana Gems a Josef Gregorian.",
  progress = "Anastasia mi aveva detto che saresti $Gvenuto:venuta; da me, e sono pronto a confezionare le tue vesti.  Hai le gemme e il lino?",
  reward = "È un materiale ottimo, e anche se non ho il talento per giudicare la qualità di queste gemme di mana, sapremo presto se hanno il potere necessario per creare vesti di fuoco arcano...",
  en_title = "Gathering Materials",
  en_obj = "Bring 10 Linen Cloth and 6 Dalaran Mana Gems to Josef Gregorian.",
}
T[1962] = {
  title = "Vesti di Fuocomagico",
  reward = "Eccoti le vesti, $N. Indossale con onore.",
  en_title = "Spellfire Robes",
}
T[1963] = {
  title = "La Mano Spezzata",
  desc = "Il Capoguerra usa metodi troppo prudenti. Esita a scatenare la potenza dell'Orda. Un tempo eravamo più forti, tutti grandi conquistatori. Dobbiamo ritrovare quell'orgoglio, e la Mano Spezzata ci riuscirà.$B$BCi rafforziamo nell'ombra e colpiamo chi resta scoperto, abbattendo i nemici in segreto. Per dimostrare il tuo valore, dovrai portare a termine un compito per me.$B$BIl troll Tazan commercia con i pirati vicino a Ratchet. Ha delle informazioni che mi servono. Uccidilo e portami la bisaccia.",
  obj = "Uccidi Tazan e porta la sua Bisaccia a Therzok nella Cleft of Shadow a Orgrimmar.",
  progress = "Solo uno stolto crede che una carica con l'ascia in pugno sia più pericolosa di un pugnale nel buio.",
  reward = "Hm, sono lieto di sapere che Tazan non è più tra noi, ma una bisaccia chiusa a chiave non ci serve a nulla. Abbiamo bisogno delle informazioni che contiene.$B$BPer chi desidera unirsi alla Mano Spezzata, sarà una degna seconda prova.",
  en_title = "The Shattered Hand",
  en_obj = "Kill Tazan and bring his Satchel to Therzok in the Cleft of Shadow in Orgrimmar.",
}
T[1978] = {
  title = "Gli Inseguimorte",
  desc = "Lo Syndicate? Non l'avrei mai sospettato. A quanto pare i signori di Alterac sono caduti molto in basso negli anni seguiti al loro tradimento.$B$BLord Varimathras sarà lieto di saperlo e, visto che hai avuto un ruolo così decisivo in questa scoperta, sarebbe giusto che fossi tu a portargli la notizia.$B$BAh, e come potevo dimenticarlo?$B$B$GBenvenuto:Benvenuta; tra gli Inseguimorte.",
  obj = "Consegna Andron's Ledger a Varimathras in Hall of the Dark Lady, a Undercity.",
  progress = "Sì?",
  reward = "Mmm, interessante. Gli Inseguimorte hanno fatto un lavoro ammirevole, a scovare tutto questo.$B$BA quanto ho capito, anche tu meriti un encomio per come hai agito. Spero che per te diventi un'abitudine, $N, i miei Inseguimorte hanno sempre bisogno di $Gun uomo:una donna; in gamba.",
  en_title = "The Deathstalkers",
  en_obj = "Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity.",
}
T[1998] = {
  title = "Fenwick Thatros",
  desc = "Lord Varimathras mi ha appena mandato una missiva: c'è una minaccia per i Forsaken, e va eliminata subito. Si chiama Fenwick Thatros, e Lord Varimathras crede che sia uno dei capi dei non morti che hanno messo radici nella Silverpine Forest.$B$BHo pensato subito a te, $N. Mi fido abbastanza delle tue capacità da essere certo che porterai a termine questa missione alla perfezione.$B$BSecondo gli ultimi rapporti dei Deathstalkers a Silverpine, Thatros si trova vicino al molo fatiscente sul Lordamere.",
  obj = "Uccidi Fenwick Thatros e porta la sua testa a Mennet Carkad in Rogues' Quarter of the Undercity.",
  progress = "Per questo servizio a Lord Varimathras ho la massima fiducia in te.",
  reward = "Ben fatto, $N. Mi viene da pensare che hai reso molti servizi ai Deathstalkers e hai dimostrato quanto vali, e che forse è giunto il momento di approfondire il tuo addestramento nelle arti dell'ombra.",
  en_title = "Fenwick Thatros",
  en_obj = "Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity.",
}
T[1999] = {
  title = "Gli Attrezzi del Mestiere",
  desc = "I maghi del Kirin Tor ad Ambermill hanno messo al sicuro documenti importanti sulla situazione attuale di Dalaran: ce l'ha confessato uno dei nostri prigionieri. Lord Varimathras ha affidato ai Deathstalkers il compito di recuperarli.$B$BQuesto lavoro tocca a te, $N. Però ti servirà un po' di attrezzatura, e dovrai saper scassinare le serrature. Prima di partire parla con Estelle Gendry, la nostra fornitrice, e chiedile un set di attrezzi.",
  obj = "Trova il Dalaran Status Report e riportalo a Mennet Carkad in Rogues' Quarter of the Undercity.",
  progress = "Hai trovato i documenti, $N?",
  reward = "Molto bene, $N! Hai imparato come si deve la raffinata arte dello scasso, e più in fretta di quanto potessi mai aspettarmi.$B$BAvevo ragione a fidarmi di te. Credimi, $Gragazzo:ragazza;: prevedo che farai molta strada in questo mestiere.",
  en_title = "Tools of the Trade",
  en_obj = "Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity.",
}
T[2040] = {
  title = "Assalto Sotterraneo",
  desc = "Gnomeregan è finita nelle mani di quei perfidi troggs! Siamo messi male, ma forse tu puoi aiutarci, $N.$B$BGiù nel profondo delle Deadmines c'è un trituratore goblin che funziona: trovalo e portami qui l'alimentatore, intatto. Con quello potremo dare ai nostri escavazionatori girotrivellomatici l'energia per sfondare i confini rocciosi sotterranei di Gnomeregan e aprire la strada a un assalto gnomesco!",
  obj = "Recupera lo Gnoam Sprecklesprocket dalle Deadmines e portalo a Shoni the Shilent a Stormwind.",
  progress = "Hai trovato lo Gnoam Sprecklesprocket, $N?",
  reward = "Ben fatto, $N. Grazie a te, il giorno in cui Gnomeregan sarà liberata è un passo più vicino!",
  en_title = "Underground Assault",
  en_obj = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.",
}
T[2178] = {
  title = "Zampalunga e Dolce Vita",
  desc = "Lo senti questo profumino delizioso? È la mia ricetta segreta, $N — strider stew fresco. Una bontà!$B$BTi piacerebbe impararla?$B$BPrima di insegnartela, però, dovrai dimostrare di saper tenere testa a quelle bestie.$B$BNon pretendo che tu vada a domarne uno e torni qui in groppa, ma se riesci ad abbatterne qualcuno e a riportarmi un po' della loro carne succulenta, potrei lasciarmi convincere a svelarti i segreti dello strider stew.",
  obj = "Riporta 5 pezzi di Strider Meat ad Alanndarian Nightsong ad Auberdine.",
  progress = "La pentola è vuota e io ho fame! Perché ci metti tanto?",
  reward = "Fantastico! Assaggialo e dimmi cosa ne pensi, $N!",
  en_title = "Easy Strider Living",
  en_obj = "Bring back 5 Strider Meat to Alanndarian Nightsong in Auberdine.",
}
T[2198] = {
  title = "La Shattered Necklace",
  desc = "Hai trovato una collana annerita: l'ossidazione nasconde una lavorazione intricata e magica. La collana è stata infranta, e alla montatura sembrano mancare tre gemme. Sul retro si vede appena l'impronta del sigillo cittadino di Ironforge, e sotto ci sono incise tre minuscole lettere: \"TdK\".$B$BPer scoprire qualcosa su questa collana dovrai risalire alle sue origini. Forse si può partire dal sigillo e dalle iniziali...",
  obj = "Cerca il creatore originale della shattered necklace per scoprirne il possibile valore.",
  progress = "Hai sbagliato gnomo, $Gamico:amica;! Io lì non c'ero! Non puoi provare niente!$B$BUn momento... e tu chi sei? Ma che... dove l'hai trovata questa collana?",
  reward = "Sì... il gioielliere che ha fatto questa collana sono io. E non ho l'abitudine di regalare informazioni. Le informazioni non sono mai gratis, $Gamico:amica;. Se devo aiutare te, prima devi aiutare ME.",
  en_title = "The Shattered Necklace",
  en_obj = "Search for the original creator of the shattered necklace to learn of its potential value.",
}
T[2199] = {
  title = "Sapere a Pagamento",
  desc = "Qui a Ironforge sono un gioielliere di grande fama! Be', di grande fama un tempo... prima che gli imbrogli di un concorrente mi facessero cadere in disgrazia! Nel mio mestiere, una cattiva reputazione vuol dire il disastro economico. E così eccomi qui, senza un rame a mio nome: un buon nome, anche se per ora è infangato.$B$BVoglio che tu mi procuri cinque silver bars per finire un ordine che ho ricevuto — il primo da quella che sembra un'eternità.$B$BPortami quei cinque silver bars e risponderò alle tue domande sulla collana.",
  obj = "Porta cinque silver bars a Talvash del Kissel a Ironforge.",
  progress = "Hai i cinque silver bars che ti ho chiesto? Ti racconterò la triste storia di sventure legata alla collana che ora è tua... ma solo quando avrò quei lingotti! Ti prego, dai una mano a uno gnomo, eh?",
  reward = "Per me sei in gamba, e non m'importa cosa vanno dicendo tutti gli altri... Scherzo, scherzo! Davvero, grazie, $Gamico mio:amica mia;.$B$BAllora, la collana che hai è una delle mie creazioni migliori, ma le mancano tre gemme che aiutano a legarci il potere magico. L'ho fatta tempo fa per un paladino che si era messo in testa una missione tutta sua: ripulire dalla \"corruzione malvagia\" un sito di scavo nelle Badlands che si chiama Uldaman.$B$BBe'... quel paladino è morto a Uldaman, e le mie disgrazie erano solo all'inizio.",
  en_title = "Lore for a Price",
  en_obj = "Bring five silver bars to Talvash del Kissel in Ironforge.",
}
T[2200] = {
  title = "Ritorno a Uldaman",
  desc = "Un mio concorrente ha messo in giro la voce che era stata la mia collana a maledire il paladino. E va da sé che nessuno vuole comprare oggetti maledetti da un gioielliere.$B$B$N, ti propongo un patto: tu trovi le gemme e io rimetto insieme la collana, purché tu vada a dire in giro che io NON faccio oggetti maledetti!$B$BProva a cercare indizi a Uldaman; magari guarda se laggiù c'è il corpo del paladino, perché, per quanto ne sappiamo, l'ultimo ad averla è stato lui! Quando trovi le gemme dovresti usare questa: così potrai contattarmi qui a Ironforge.",
  obj = "Cerca indizi su dove si trovi ora la collana di Talvash dentro Uldaman. Il paladino ucciso di cui ha parlato è stato l'ultimo ad averla.",
  reward = "Remains of a paladin: dal diario si capisce che il paladino, dopo molti sforzi, aveva scoperto dove si trovavano tutte e tre le gemme mancanti:$B$BMentre combattevano contro i Troggs per il controllo di Uldaman, i nani Shadowforge hanno nascosto il rubino nella loro zona barricata.$B$BI troggs hanno messo il topazio in un'urna, vicino a degli insoliti abitanti di Uldaman — dei nani dell'Alleanza!$B$BLo zaffiro, infine, se l'è preso l'anziano trogg in persona.",
  en_title = "Back to Uldaman",
  en_obj = "Search for clues as to the current disposition of Talvash's necklace within Uldaman.  The slain paladin he mentioned was the person who had it last.",
}
T[2201] = {
  title = "Trova le Gemme",
  desc = "Nel diario del paladino ci sono forse gli unici indizi che Uldaman offrirà su dove si trovano le gemme della collana. Se quello che ha scritto il paladino è ancora esatto, bisognerà vedersela con i nani Shadowforge e con i troggs che si contendono il controllo del sito di scavo.$B$BForti di queste informazioni, ora la ricerca delle gemme comincia sul serio. Recuperate tutte le gemme, bisognerà avvisare Talvash a Ironforge con la Phial of Scrying, come ha detto lui.",
  obj = "Trova il rubino, lo zaffiro e il topazio sparsi per Uldaman. Una volta recuperati, contatta Talvash del Kissel a distanza usando la Phial of Scrying che ti ha dato in precedenza.$B$BDal diario sai che...$B* Il rubino è stato nascosto in una zona barricata Shadowforge.$B* Il topazio è stato nascosto in un'urna in una delle zone Trogg, vicino ad alcuni nani dell'Alleanza.$B$B* Lo zaffiro se l'è preso Grimlok, il capo dei trogg.",
  progress = "L'immagine di Talvash prende forma nell'acqua della bacinella divinatoria.$B$B\"Caspita, sei ancora $Gvivo:viva;! Sei $Griuscito:riuscita; a trovare le gemme? Sei proprio $Gil salvatore:la salvatrice; in cui speravo per la mia reputazione? Ti prego, dimmi che non hai sprecato una carica della fiala solo per fare due chiacchiere: quelle cose NON costano poco, e io sono già in grossi guai con i soldi.",
  reward = "Sì, sono proprio queste le tre gemme. Ottimo lavoro! Purtroppo il tuo compito non è ancora finito del tutto.$B$BNo, non sto cercando di fregarti, $Gsciocco:sciocca; $C. Qui si tratta di fare gioielli magici — gioielli della qualità di Talvash del Kissel! Per dargli un po' di sprint ci vuole una fonte di energia potente. Be', quella collana di sprint da dare non ne ha più.",
  en_title = "Find the Gems",
  en_obj = "Find the ruby, sapphire, and topaz that are scattered throughout Uldaman.  Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B$B* The sapphire has been claimed by Grimlok, the trogg leader.",
}
T[2202] = {
  title = "Raccolta di Reagenti a Uldaman",
  desc = "Ho sentito parlare di una pianta scoperta da poco, che chiamano magenta fungus caps. Crescono a gruppi giù in fondo agli scavi di Uldaman; magari si trovano anche da altre parti, ma per ora quello è l'unico posto che conosco dove crescono. Voglio studiare a cosa potrebbero servire in alchimia, ed è qui che entri in gioco tu.$B$BCerca i gruppi di cappelli magenta e portamene una dozzina. Sta' $Gattento:attenta;, se li urti potrebbero sputare spore velenose.$B$BFammi questo favore e ti preparo una dose di uno dei miei famosi elisir ristoratori!",
  obj = "Porta 12 Magenta Fungus Caps a Jarkal Mossmeld a Kargath.",
  progress = "Me li hai presi i magenta fungus caps che mi servono per il mio lavoro di alchimia? Niente cappelli — niente ricompensa!",
  reward = "Ben fatto, $N, ancora una volta hai dimostrato quanto vali! I cappelli saranno interessanti da studiare, ci puoi scommettere.$B$BE ora, come promesso, eccoti un assaggio di una delle mie pozioni ristoratrici più potenti, presa dalla mia scorta personale. Goditela...$B$BSe sei $Gun abile alchimista:un'abile alchimista;, magari potremmo fare altri affari. Comunque sia, grazie dell'aiuto!",
  en_title = "Uldaman Reagent Run",
  en_obj = "Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.",
}
T[2203] = {
  title = "Raccolta di Reagenti nelle Badlands II",
  desc = "Mi sei $Gstato:stata; di grande aiuto, $C, e mi piacerebbe ricompensarti proprio con la ricetta della pozione che ti ho dato prima... solo che dovrei affidarti un compito piuttosto pericoloso. Ascolta cosa ti chiedo.$B$BIn questo forziere ci sono tre empty thaumaturgy vessels, intrise di un'aura di sintonia che prosciugherà il sangue di un drago scorched guardian. Usane una sulla bestia e la farai infuriare parecchio, quindi stai in guardia. Quando le avrai riempite tutte e tre, portamele.$B$BFallo e la ricetta sarà tua.",
  obj = "Usa le empty thaumaturgy vessels sui draghi scorched guardian che si trovano in Badlands. Una volta riempite, portale a Jarkal Mossmeld, a Kargath.",
  progress = "Hai raccolto con le ampolle il sangue di drago scorched guardian che mi serve? Sì, lo so che è un compito pericoloso... ma se ce la fai, ti aspetta la ricetta della mia pozione ristorativa. Rischio e ricompensa, $Gamico mio:amica mia;... rischio e ricompensa...",
  reward = "Da alchimista ad alchimista, ti rendo omaggio. Ecco, prendi questa ricetta e imprimila nella memoria. Che ti porti il successo e le ricompense che ha dato a me in tutti questi anni.",
  en_title = "Badlands Reagent Run II",
  en_obj = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Jarkal Mossmeld in Kargath.",
}
T[2204] = {
  title = "Riparare la Collana",
  desc = "Dovrai trovare un po' di \"sprint\" per la collana, e a dire il vero il posto migliore dove cercarlo è probabilmente Uldaman. Immagino che là dentro ci siano un sacco di costrutti in giro, no? Bene: fai fuori il più grosso e il più cattivo di tutti e prendi la sua fonte di energia! Sono quasi sicuro di poterla fondere nella collana.$B$BSenza quella fonte di energia riparare la collana sarà impossibile. Quando ce l'hai torna da me qui a Ironforge, e te la sistemeremo per bene!",
  obj = "Ottieni una fonte di energia dal costrutto più potente che riesci a trovare a Uldaman e consegnala a Talvash del Kissel a Ironforge.",
  progress = "Non ti sei neanche $Gfermato:fermata; a darti una sistemata dopo aver lasciato Uldaman, eh. Sei $Gvenuto:venuta; $Gdritto:dritta; qui, e al diavolo il tanfo di sotterraneo che ti porti dietro. Be', speriamo che questa visita sia solo maleodorante, e non pure inutile.$B$BHai la fonte di energia per la collana?",
  reward = "Ma guarda un po' — sono proprio contento di vedere te e questa fonte di energia $Gtutti interi:tutte intere;. Ora che le gemme sono di nuovo al loro posto, mi ci vorrà un momento per fonderla magicamente con la collana. Appena avrò finito, però, sarà tua!$B$BSei $Gemozionato:emozionata;, vero? $GTutto:Tutta; un fremito per l'attesa? Vediamo, dove avrò messo quel focalizzatore magico...",
  en_title = "Restoring the Necklace",
  en_obj = "Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.",
}
T[2205] = {
  title = "Cerca lo SI: 7",
  desc = "Il distintivo? Oh, niente, $Gpivello:pivella; — niente alla tua portata, comunque. A guardarti, direi che Mathias rischia di scambiarti per $Gil ragazzo:la ragazza; che consegna il formaggio invece che per $Gun vero ladro:una vera ladra;. In ogni caso, mi hanno affidato un incarico e ho promesso di portarlo a termine.$B$BA proposito di consegne, porta questo pacco a Mathias e magari ti darà un paio di lavoretti.$B$BDatti una mossa.",
  obj = "Consegna il pacco di Keryn Sylvius a Master Mathias Shaw a Stormwind Barracks.",
  progress = "Posso aiutarti, $C?",
  reward = "Mi hai trovato — e a giudicare dall'aspetto, direi che correre e poi cercarmi ti ha messo a dura prova, nel corpo e nella mente.$B$BVuoi che Renzik ti accompagni a una locanda o sei $Gpronto:pronta; a lavorare un po'?",
  en_title = "Seek out SI: 7",
  en_obj = "Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks.",
}
T[2206] = {
  title = "Prendi e Scappa",
  desc = "Dai nostri agenti sul campo arrivano notizie di un gran movimento di Defias a sud di Goldshire. Secondo i rapporti, i Defias si sono presi il Jerod's Landing e adesso se ne servono per contrabbandare grandi quantità di merce da Redridge a Westfall.$B$BDevi entrare di nascosto nell'edificio del molo e portarmi quel registro delle spedizioni, $N. Probabilmente sta in fondo alle tasche dell'Ormeggiatore.$B$B...e $N, se vieni $Gscoperto:scoperta;, l'SI:7 negherà di sapere che esisti.",
  obj = "Trova il Defias Dockmaster e recupera il Registro delle Spedizioni per Master Mathias Shaw.",
  progress = "Ogni momento che passi a bighellonare in caserma è un pezzo di vita che se ne va, $C.",
  reward = "Sono stupito... Stupito che Keryn abbia finalmente trovato una recluta che forse ha la stoffa di $Gun vero ladro:una vera ladra;. Prendi questa lama, $N. Un giorno sarai di nuovo $Gchiamato:chiamata; a servire l'SI:7. Affina le tue abilità, tieni gli occhi aperti e quella lama affilata.$B$BNon ci vedrai arrivare, ma quando saremo lì te ne accorgerai...",
  en_title = "Snatch and Grab",
  en_obj = "Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw.$B",
}
T[2218] = {
  title = "Strada per la Salvezza",
  desc = "Un'altra anima perduta in cerca di una guida, eh? Immagino che tu voglia trovare uno scopo — il tuo scopo. Mi è capitato mille volte: $Gun altro eroe:un'altra eroina; in cerca di lavoro.$B$BBe', oggi è il tuo giorno fortunato, $Gamico:amica;. Hogral ha la cura per il tuo tormento.$B$BEcco cosa devi fare: sali per questa strada fino a Ironforge e raggiungi la Forlorn Cavern. Una volta lì, cerca la gilda dei ladri e parla con Hulfdan Blackbeard. Ti metterà sulla strada della salvezza.",
  obj = "Parla con Hulfdan Blackbeard a Ironforge.",
  reward = "E così credi d'essere $Gun gran furfante:una gran furfante;? $GDestinato:Destinata; a entrare fra i pochi eletti di Blackbeard — a diventare $Gun ufficiale:un'ufficiale; dell'Hidden Circle?$B$BSolo un mascalzone buono a nulla potrebbe darsi tante arie.$B$BÈ proprio quel che cerchiamo! $GBenvenuto:Benvenuta; a bordo, $N!",
  en_title = "Road to Salvation",
  en_obj = "Speak with Hulfdan Blackbeard in Ironforge.",
}
T[2238] = {
  title = "Semplici Sotterfugi",
  desc = "Vedi, il Re sta sventrando la cava a cielo aperto per tirarne fuori minerali e gemme. Più ricchezze di quante un nano solo avrebbe il diritto di vederne in dieci vite.$B$BL'Hidden Circle ha dei valori, $N. Noi diamo valore agli oggetti di valore. Capisci?$B$BOra, secondo noi il Re dovrebbe spartire un po' di quel bottino, ma senza che il vecchio 'Barbafetida' sappia di spartirlo — se capisci cosa intendo.$B$BDevi andare a parlare con Onin MacHammar, dalle parti di Gnomeregan, e poi tornare a farci rapporto. Quel nano furbo s'è nascosto in mezzo ai lebbrosi. Sta' $Gattento:attenta;.",
  obj = "Trova Onin MacHammar vicino a Gnomeregan.",
  reward = "Shhhh! Abbassa la voce, $Gscemo:scema; che non sei altro. Ci sentiranno.",
  en_title = "Simple Subterfugin'",
  en_obj = "Find Onin MacHammar by Gnomeregan.",
}
T[2239] = {
  title = "Onin's Report",
  desc = "La Cava? Già, quasi tutti i giorni vedo passare da questo avamposto quei mostruosi steam tanks corazzati.$B$BI miei contatti a est mi dicono che il carro parte da Ironforge, carica alla Gol'Bolar Quarry, si ferma a Kharanos per rifornirsi e poi, per qualche dannato motivo, fa il giro lungo passando per Gnomeregan, prima di tornare a Ironforge a scaricare la merce.$B$BÈ tutto nel rapporto, $R. Riportalo a Hulfdan, così potrà pianificare la prossima mossa.",
  obj = "Riporta l'Onin's Report a Hulfdan a Ironforge.",
  progress = "Ti è piaciuto il fetore di leper gnome? Te lo chiedo solo perché hai un sorriso da $Gmatto:matta; stampato in faccia.$B$BChe notizie mi porti da Onin?",
  reward = "Il giro lungo? Per la mia barba!$B$BHai fatto un buon lavoro, $N. Prendi questo pugnale e sparisci. Il Circolo ti richiamerà quando la fase tre potrà partire.$B$BE la fase tre cos'è? Viene subito dopo la fase due — cioè io che ti prendo a calci nel sedere.$B$B$GInteressato:Interessata;?",
  en_title = "Onin's Report",
  en_obj = "Take Onin's Report back to Hulfdan in Ironforge.",
}
T[2240] = {
  title = "La Camera Nascosta",
  desc = "Adesso pensiamo a quello che ci aspetta.$B$BC'è una camera segreta da esplorare, la Chamber of Khaz'mul. Il guaio è che sta dietro un'enorme porta chiusa a chiave! Per fortuna io so come aprirla.$B$BHo scritto tutto nel mio diario, qui sul tavolo. Per ora io e il mio gruppo non possiamo muoverci... quindi tocca a te, $N, trovare la camera di Khaz'mul al posto nostro!$B$BLeggi il diario, esplora la camera e poi fai rapporto a Prospector Stormpike, all'Explorers' League di Ironforge.",
  obj = "Leggi il Baelog's Journal, esplora la camera nascosta, poi fai rapporto a Prospector Stormpike.",
  progress = "Hai qualcosa da riferirmi?",
  reward = "Hai visto la Chamber of Khaz'mul? Incredibile! Baelog era sicuro che esistesse, ma ti confesso che io avevo i miei dubbi.$B$BGrazie, $N. Con un po' di fortuna, la tua scoperta spingerà i nostri capi a darsi di nuovo da fare per riconquistare Uldaman. E se un giorno tornerà nelle mani di Ironforge, i segreti della Chamber of Khaz'mul saranno nostri!",
  en_title = "The Hidden Chamber",
  en_obj = "Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike.",
}
T[2241] = {
  title = "La Mela Cade",
  desc = "Dicono che sono 'cotto', qualunque cosa significhi.$B$BCerto, passo ogni momento della giornata a pensare a Syurna. Certo, ho la casa piena di quadri e disegni di Syurna. Certo, spesso sto giorni interi senza mangiare, dormire o bere, a piangere l'amore che avremmo potuto vivere. Che c'è di tanto sbagliato?$B$BE adesso non vuole vedermi! ME! Ho provato a mandarle dei messaggi, ma non parla con nessuno che non sia un ladro.$B$BPotresti portarle questo fiore? E non dimenticarti di dirle che viene da Jannok.",
  obj = "Porta la Jannok's Rose a Syurna a Darnassus.",
  progress = "Oh, ma che meraviglia. Hai portato i fiori per il tuo funerale.",
  reward = "Se avessi tenuto tutti i fiori che quello sciocco di Jannok mi ha mandato, ci avrei aperto un negozio. Comunque sia, pare che l'ultimo corriere di Jannok possa servire a qualcosa.$B$B$GInteressato:Interessata; a un po' di lavoro, $C?",
  en_title = "The Apple Falls",
  en_obj = "Take Jannok's Rose to Syurna in Darnassus.",
}
T[2242] = {
  title = "Il Destino Chiama",
  desc = "Crediamo che esista un essere in grado di aiutarci a capire cosa sta accadendo alle foreste di Teldrassil. Purtroppo, i tentativi di convincerlo a collaborare sono stati un disastro.$B$BSi nasconde su un ramo ai margini dell'Oracle Glade. Tutti quelli che finora si sono avvicinati al satiro, con la forza o con la diplomazia, sono andati incontro alla rovina. Forse la risposta è la furtività, $N.$B$BScopri cosa porta nelle sacche Sethir the Ancient e torna a riferirmelo.",
  obj = "Trova Sethir the Ancient e porta a Syurna gli indizi che riesci a scoprire.",
  progress = "Hai qualcosa da riferire su Sethir the Ancient, $N?",
  reward = "Sono notizie funeste, $N. Sembra che il morbo che ha colpito le foreste e i fiumi di Darkshore abbia cominciato a contaminare la nostra casa.$B$BCi hai servito bene, ma qui non puoi fare altro. Prendi questa lama come ricompensa per i servigi resi a Teldrassil.",
  en_title = "Destiny Calls",
  en_obj = "Find Sethir the Ancient and bring back any clues that you may discover to Syurna.$B",
}
T[2258] = {
  title = "Raccolta di Reagenti nelle Badlands",
  desc = "$N, se te la senti, una mano mi farebbe comodo. Sono un alchimista abbastanza conosciuto, e mi piacerebbe che mi aiutassi a recuperare alcuni reagenti che si trovano nelle Badlands.$B$BPer rifare le scorte mi servono queste cose: cinque buzzard gizzards, dieci crag coyote fangs e cinque rock elemental shards. Li puoi prendere dalle bestiole, è ovvio; se combattere non fa per te, trovati qualche amico che invece è del mestiere.$B$BProcurameli e qualche moneta te la porti a casa. Allora, che vuoi fare?",
  obj = "Porta 5 Buzzard Gizzards, 10 Crag Coyote Fangs e 5 Rock Elemental Shards a Jarkal Mossmeld a Kargath, Badlands.",
  progress = "Hai già trovato quello che mi serve? Finché non mi porti quei reagenti, non sarai $Gpagato:pagata;.",
  reward = "Ah, ben fatto! Con questi dovrei andare avanti per un po', almeno. Ecco la tua paga, come promesso.$B$BSe ti interessa, ci sono altri reagenti che mi servirebbero, però quelli si trovano solo giù in fondo agli scavi di Uldaman. Procurarli non sarà facile, ma se vorrai darmi di nuovo una mano, farò in modo che ne valga la pena.$B$BMagari con qualcosa di più di qualche moneta luccicante, eh?",
  en_title = "Badlands Reagent Run",
  en_obj = "Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and  5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands.",
}
T[2259] = {
  title = "Erion Shadewhisper",
  desc = "Non temere, $N, non ti mando da Syurna. Erion richiede la tua presenza alla Cenarion Enclave. Affrettati!",
  obj = "Contatta Erion Shadewhisper a Darnassus.",
  reward = "È tempo di allargare gli orizzonti, $R — il mondo ti attende.",
  en_title = "Erion Shadewhisper",
  en_obj = "Contact Erion Shadewhisper in Darnassus.$B",
}
T[2260] = {
  title = "La Richiesta di Erion",
  desc = "Le voci sulle tue imprese sono arrivate lontano, $N. Così lontano che i Servizi Segreti di Stormwind hanno chiesto proprio di te.$B$BIl viaggio è faticoso e non privo di pericoli, ma l'occasione di addestrarti con l'SI:7 non va presa alla leggera.$B$BUn nuovo mondo ti attende, $N. Raggiungi l'Old Town di Stormwind e parla con Renzik \"The Shiv\" al quartier generale dell'SI:7.",
  obj = "Raggiungi Stormwind City e chiedi udienza a Renzik \"The Shiv.\"",
  reward = "Hai risposto alla chiamata dell'SI:7, $N, e sei $Gvenuto:venuta; da lidi lontani per unirti alle nostre file, ma hai ancora molto da imparare.",
  en_title = "Erion's Behest",
  en_obj = "Travel to Stormwind City and seek council with Renzik \"The Shiv.\"$B",
}
T[2278] = {
  title = "I Dischi di Platino",
  desc = "Al centro della sala del tesoro si trovano quattro enormi dischi di platino, ciascuno decorato da molti sigilli di origine sconosciuta. Quando li tocchi, la mano ti formicola, e subito dopo compare all'improvviso il volto di una grande stone watcher.$B$B\"Saluti. Sono un custode del sapere. Qui, nei Dischi di Norgannon, è registrata e custodita per questo mondo la sintesi di Earthen compiuta dai Creatori.\"$B$BHai scoperto sul mondo una gran quantità di conoscenze finora ignote!",
  obj = "Parla con la stone watcher e scopri quale antico sapere custodisce. Dopo aver appreso il sapere che ha da offrire, attiva i Dischi di Norgannon.",
  progress = "La voce della stone watcher sembra risuonare nel profondo del tuo essere:$B$B\"Devi soddisfare un prerequisito: l'assimilazione dei dati dei Dischi di Norgannon. Soddisfatto il requisito, ti sarà consentito ottenere una versione portatile dei dati archiviati. Prima, assicurati di aver esplorato a fondo le informazioni contenute in questo archivio.\"",
  reward = "Ora che conosci la storia di Earthen, dei troggs e dei nani, segui le istruzioni della stone watcher e accedi di nuovo ai Dischi di Norgannon. Dall'interno dei dischi arriva un ronzio breve e debole, poi la stone watcher parla:$B$B\"I dischi sono stati sintetizzati. Accedi ancora una volta ai Dischi di Norgannon e riceverai la tua copia personale.\"",
  en_title = "The Platinum Discs",
  en_obj = "Speak with stone watcher and learn what ancient lore it keeps.  Once you have learned what lore it has to offer, activate the Discs of Norgannon.",
}
T[2279] = {
  title = "I Dischi di Platino",
  desc = "Quando tocchi di nuovo i Dischi di Norgannon, la mano ti formicola. Questa volta, però, dall'interno dei dischi arriva uno strano rumore stridente.$B$BAll'improvviso lo zaino si fa più pesante di prima, e dentro scopri una versione in miniatura dei dischi!$B$BUn oggetto del genere avrebbe di certo un valore inestimabile per chi si interessa alla storia antica di Azeroth. L'Explorers' League di Ironforge, nota in tutta l'Alleanza, è proprio un gruppo di questo tipo: forse saprebbe farne buon uso.",
  obj = "Porta la versione in miniatura dei Dischi di Norgannon a Explorers' League a Ironforge.",
  progress = "Sì? Posso aiutarti in qualcosa? Ti assicuro che adesso sono molto occupato. Ma se è una questione di grave importanza per l'Explorers' League, allora sono tutto orecchi!",
  reward = "Cos'hai lì... oh, cielo. L'hai trovato dove?$B$BNo, davvero?$B$BHai parlato con chi di cosa?$B$BNO, DAVVERO?!$B$B$GMio buon:Mia buona; $C, forse hai appena fatto la scoperta archeologica dell'anno! Per gli Dei, ma chi voglio prendere in giro: la scoperta del secolo! Se questi dischi sono quello che penso, potrebbero essere proprio la chiave che cercavamo! Si dimostrerebbe una volta per tutte la legittimità della creazione incantata dei Nani!",
  en_title = "The Platinum Discs",
  en_obj = "Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge.",
}
T[2280] = {
  title = "I Dischi di Platino",
  desc = "Quando tocchi di nuovo i Dischi di Norgannon, la mano ti formicola; stavolta, però, dall'interno dei dischi arriva uno strano stridore.$B$BTutt'a un tratto lo zaino si fa più pesante di prima. Ci guardi dentro e trovi una versione in miniatura dei dischi!$B$BUn oggetto del genere sarebbe senz'altro inestimabile per chi si interessa alla storia antica di Azeroth. I saggi di Thunder Bluff, noti in tutta l'Orda, sono storici proprio di questo tipo: forse sapranno farne buon uso.",
  obj = "Porta la versione in miniatura dei Dischi di Norgannon a uno dei saggi a Thunder Bluff.",
  progress = "Sì, giovane, ti vedo entrare in tenda a passo di marcia, con foga... e con la determinazione di chi ha uno scopo. Vieni a chiedermi consiglio su una questione di estrema importanza per l'Orda? Forse vuoi che ti sveli un mistero dell'universo?",
  reward = "E questi, dunque, cosa sono?$B$BNotevole, giovane! Questi dischi... percepisco in loro segreti che la terra ha custodito gelosamente per molti anni. Sei $Gstato:stata; molto $Gsaggio:saggia; a portarli qui da me.",
  en_title = "The Platinum Discs",
  en_obj = "Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff.",
}
T[2281] = {
  title = "Appuntamento a Redridge",
  desc = "Se ti mandassi sul campo adesso, sarebbe un suicidio, e a Renzik non serve $Gun altro ladro morto:un'altra ladra morta; sulla coscienza. Ma non preoccuparti, $N — Renzik ti rimetterà in pari.$B$BVai nelle Redridge Mountains e parla con un socio del SI:7 che si chiama Lucius. Lo troverai sui moli di Lakeshire, a ciondolare con gli altri loschi buoni a nulla.",
  obj = "Avventurati fino a Lakeshire, nelle Redridge Mountains, e parla con Lucius.",
  reward = "Ah, dita un po' grosse, eh? Non preoccuparti, $N: ho fatto dei ladri provetti di ladri più inutili di te.",
  en_title = "Redridge Rendezvous",
  en_obj = "Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius.$B",
}
T[2282] = {
  title = "Alther's Mill",
  desc = "Sono anni che addestriamo ladri, qui! Del resto, non tutti i furfanti nascono con la grazia e la finezza del vecchio Lucius.$B$BPiù su, appena fuori dalla strada, c'è l'Alther's Mill. Lassù tengo una cassetta con dentro una cosa importante: vai a prendermela! Riportami l'emblema e avrai il tuo Certificate of Thievery!",
  obj = "Apri la Lucius's Lockbox, recupera la Token of Thievery e riportalo a Lucius a Lakeshire.",
  progress = "Mi sono scordato di dirti degli orchi?$B$BHo sentito che vanno a ficcare il naso lassù, dalle parti della segheria.",
  reward = "L'hai scassinata, eh? Bel lavoro, $N.$B$BOra, se muori, possiamo stare tranquilli: sarà colpa della tua stupidità, non dell'inesperienza.",
  en_title = "Alther's Mill",
  en_obj = "Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire.",
}
T[2283] = {
  title = "Recupero della Collana",
  desc = "Abbiamo un lavoro per te, se hai il fegato di farlo!$B$BNel cuore di Badlands c'è il sito di scavo di Uldaman. Ci è arrivata la storia di un paladino idiota che ci è morto da poco, e la cosa ci interessa: addosso aveva una collana di grande valore. A quanto pare ha tre grosse gemme: un rubino, uno zaffiro e un topazio.$B$BLa faccenda è questa: la collana la vogliamo noi, e per averla paghiamo IL MASSIMO IN ARGENTO. Può darsi che sia danneggiata, ma poco importa; ai graffi ci pensiamo noi.",
  obj = "Cerca una collana di valore nel sito di scavo di Uldaman e portala a Dran Droffers a Orgrimmar. La collana potrebbe essere danneggiata.",
  progress = "Allora, la collana ce l'hai? Senza quella, da noi non vedrai neanche una moneta di rame!",
  reward = "Mmmm, roba da recuperare! L'odore della collana lo sento da qui. Su, diamo un'occhiata a questa bellezza...$B$BEhi, che credi di fare? Questa collana è senza gemme! Pensavi che non ce ne saremmo accorti? Persino Malton lo vedrebbe, che le gemme non ci sono.$B$BBeh, magari non le hai rubate tu... ma senza quelle gemme la collana non vale niente! Il tuo lavoro è tutt'altro che finito!",
  en_title = "Necklace Recovery",
  en_obj = "Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar.  The necklace may be damaged.",
}
T[2284] = {
  title = "Recupero della Collana, Parte 2",
  desc = "Com'è vero che Malton è un tonto, quelle gemme sono ancora da qualche parte a Uldaman. Ti tocca tornare laggiù a cercarle.$B$BTe l'ho detto: se ci hanno informati bene, con la collana vanno un rubino, uno zaffiro e un topazio. Trovali e rimettili nella collana.$B$BDove siano, chi lo sa? Magari sarai $Gfortunato:fortunata; e troverai il cadavere del Paladino: se non l'hanno già ripulito del tutto, potrebbe averle ancora addosso.",
  obj = "Trova un indizio su dove si trovino le gemme nelle profondità di Uldaman.",
  reward = "A quanto pare hai trovato i resti del paladino di cui ti aveva parlato Dran. Frugandoci in mezzo, scopri quello che ha tutta l'aria di essere il suo diario. Il libro è ridotto male: il sangue secco ha macchiato quasi tutto il testo. Quello che riesci a leggere, però, non ha senso; per quanto ne sai, è la lingua degli umani.$B$BSe vuoi cavarne qualcosa, dovrai farlo tradurre.",
  en_title = "Necklace Recovery, Take 2",
  en_obj = "Find a clue as to the gems' whereabouts in the depths of Uldaman.",
}
T[2298] = {
  title = "Retata Reale",
  desc = "Insomma, eravamo lì lì per cominciare a progettare la fase III, quando un paio di zucconi di Magni piombano qua dentro blaterando di un qualche furto e si mettono ad arrestare un po' di gente dell'Hidden Circle.$B$BBe', nessuno mette in catene il vecchio Blackbeard! Le argomentazioni si son fatte pesanti e belle fitte, e chissà come il tuo nome erano spifferato!$B$BIl mio consiglio? Prendi il primo Grifone in partenza da Ironforge e vola a Stormwind. Vai nell'Old Town e parla con un mio vecchio amico, un certo Renzik \"The Shiv.\"",
  obj = "Raggiungi Stormwind e cerca Renzik \"The Shiv.\"",
  reward = "Fa sempre piacere avere nelle nostre file $Guno:una; dei ladri addestrati da Hulfdan!",
  en_title = "Kingly Shakedown",
  en_obj = "Travel to Stormwind and seek out Renzik \"The Shiv.\"",
}
T[2299] = {
  title = "Da Hulfdan!",
  desc = "Dove ti eri $Gcacciato:cacciata;, $N? Hulfdan ti ha cercato dappertutto. Pensavamo che il re ti avesse messo ai ferri.$B$BRaggiungi Ironforge il prima possibile e parla con Hulfdan!",
  obj = "Raggiungi Ironforge e parla con Hulfdan Blackbeard.",
  reward = "Abbassa la voce, $N, che le guardie potrebbero sentirti.",
  en_title = "To Hulfdan!",
  en_obj = "Travel to Ironforge and speak with Hulfdan Blackbeard.",
}
T[2300] = {
  title = "SI:7",
  desc = "Renzik ti stava cercando, $Gpivello:pivella;.$B$BAl posto tuo non farei aspettare il vice di Mathias.",
  obj = "Raggiungi Stormwind e cerca Renzik \"The Shiv.\"",
  reward = "Sei $Gpronto:pronta; a metterti al lavoro o ti serve un pisolino prima di cominciare?",
  en_title = "SI:7",
  en_obj = "Travel to Stormwind and seek out Renzik \"The Shiv.\"$B",
}
T[2318] = {
  title = "Tradurre il Diario",
  desc = "Ti trovi in una specie di vicolo cieco: dovrai far tradurre il libro in una lingua che capisci. Al mondo c'è di sicuro parecchia gente capace di farlo, ma il posto più vicino dove potresti trovarne qualcuno è l'avamposto di Kargath, in Badlands. Potrebbe essere un buon punto da cui cominciare.",
  obj = "Trova qualcuno che possa tradurre il diario del paladino. Il posto più vicino dove potresti trovare qualcuno è Kargath, in Badlands.",
  reward = "Potente $C, lo so cosa sei $Gvenuto:venuta; a fare qui in Badlands: cerchi il mio dono delle lingue. Vai dietro ai pezzi di quella collana che hai trovato a Uldaman.$B$B$GSorpreso:Sorpresa;? Non esserlo — sapere queste cose è il mio mestiere. Parliamo piuttosto di cosa farai in cambio di un diario tradotto. Fidati — sono l'unico che troverai capace di tradurlo.$B$BAnzi, lascia che ti faccia un'offerta migliore di quella di Dran Droffers, e l'accordo con loro potrai portarlo a termine lo stesso. Adesso sei $Ginteressato:interessata;, vero?",
  en_title = "Translating the Journal",
  en_obj = "Find someone who can translate the paladin's journal.  The closest location that might have someone is Kargath, in the Badlands.",
}
T[2338] = {
  title = "Tradurre il Diario",
  desc = "Quelli della Recuperi Droffers e Figlio non sono abbastanza svegli da ridare la magia alla collana, io sì. Voglio solo studiarla, per imparare a farne anch'io, e quindi mi serve la tua. Prestamela, e in cambio del tempo per studiarla ti tradurrò il diario. Mentre cerchi le gemme dovrei fare in tempo a imparare quello che mi serve.$B$BÈ un accordo semplice, e nessuno se ne accorgerà. Allora, che vuoi fare?",
  obj = "Presta la collana a Jarkal. In cambio, ti tradurrà il diario.",
  progress = "Ci hai pensato, vero? Se accetti, sei $Gun:una; $C $Gsveglio:sveglia; — tu e io avremo quello che vogliamo, e quelli della Recuperi Droffers e Figlio crederanno di avere quello che vogliono loro.",
  reward = "Un buon affare lo riconosci al volo — sapevo di poter contare su di te.$B$BCi vorrà solo un attimo, il tempo di lanciare un incantesimo che traduca in fretta la lingua degli umani in una forma che tu possa capire. Sono un troll di parola; chiedi pure di Jarkal Mossmeld a chiunque nell'Orda. Ora, cominciamo...",
  en_title = "Translating the Journal",
  en_obj = "Let Jarkal borrow the necklace.  In exchange, he will translate the journal for you.",
}
T[2339] = {
  title = "Trova le Gemme e la Fonte di Energia",
  desc = "Ecco il diario, te l'ho tradotto così puoi leggerlo da $Gsolo:sola;. In breve, i nani hanno nascosto il rubino, i troggs il topazio, e lo zaffiro ce l'ha un trogg di nome Grimlok.$B$BSenti — per far funzionare di nuovo la collana ti servirà una fonte di energia. Dran Droffers non lo sa. Io, per trovarla, farei così: scendi più in fondo che puoi a Uldaman e uccidi il costrutto più forte che c'è. Qualunque cosa sia, ce l'avrà di sicuro.$B$BQuando avrai raccolto tutto, torna qui!",
  obj = "Recupera tutte e tre le gemme e una fonte di energia per la collana da Uldaman, poi portale a Jarkal Mossmeld, a Kargath. Jarkal crede che una fonte di energia si possa trovare sul costrutto più forte presente a Uldaman.$B$BDal diario sai che...$B* Il rubino è stato nascosto in una zona Shadowforge sbarrata.$B* Il topazio è stato nascosto in un'urna in una delle zone Trogg, vicino ad alcuni nani dell'Alleanza.$B* Lo zaffiro è stato preso da Grimlok, il capo trogg.",
  progress = "Se non hai le gemme e una fonte di energia capace di incanalare di nuovo il potere magico nella collana, ti aspetta un altro viaggio nelle profondità di Uldaman.$B$BLe gemme te le restituirò, così potrai consegnarle agli scagnozzi di Orgrimmar; la fonte di energia la tengo io, visto che sarà proprio quella a far funzionare la collana...",
  reward = "Davvero ben fatto, $C. Adesso la nostra deviazione darà frutti generosi. La collana è finita, e sono sicuro di poter ripetere ogni volta il procedimento per costruirla.$B$BMa prima che tu riporti le gemme a Orgrimmar insieme alla collana, le analizzerò in fretta con un incantesimo che ho preparato apposta. Ci vorrà solo un attimo.",
  en_title = "Find the Gems and Power Source",
  en_obj = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath.  Jarkal believes a power source might be found on the strongest construct present in Uldaman.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B* The sapphire has been claimed by Grimlok, the trogg leader.",
}
T[2340] = {
  title = "Consegna le Gemme",
  desc = "Per la montatura e per la gemma andrà bene qualsiasi cosa, basta che siano dello stesso materiale. Ma è questa fonte di energia che riporterà la magia nella collana... spero.$B$BLe gemme per la tua versione della collana te le do volentieri, a patto che la fonte di energia funzioni davvero.$B$BVa' a Orgrimmar e fa' la tua parte del patto con Recuperi Droffers e Figlio. Però sul nostro accordo acqua in bocca, e quando torni potrei avere una splendida sorpresa per te.",
  obj = "Consegna la Necklace and Gem Salvage a Dran Droffers a Orgrimmar.",
  progress = "Ma guarda chi si vede! Te la sei presa comoda per arrivare fin qui, a quanto vedo. Speriamo che non sia tempo perso! Se non hai tutto quello che ho chiesto, non verrai $Gpagato:pagata;. E fidati — controlleremo ogni cosa due e tre volte!",
  reward = "Eh sì, c'è tutto. Senti, ti dispiace se ci teniamo anche la borsa? No? Grazie, molto gentile! Har!$B$BCon questa collana faremo il bottino più grosso che abbiamo mai fatto! Ma non prendertela troppo; tanto sono sicuro che non ti andrebbe. E di nuovo har!$B$BUn patto è un patto, perciò eccoti il compenso per il recupero. Per ora qui abbiamo finito; ripassa più avanti a vedere se c'è altro lavoro. Nel frattempo, sparisci!",
  en_title = "Deliver the Gems",
  en_obj = "Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar.",
}
T[2341] = {
  title = "Recupero della Collana, Tentativo 3",
  desc = "Dran e Malton Droffers si mettono a bisticciare sulla merce appena recuperata: metà dell'accordo è fatta. Per chiudere la faccenda ti serve un viaggio nelle Badlands, perché Jarkal Mossmeld, a Kargath, potrebbe avere in serbo per te una ricompensa speciale.",
  obj = "Vai da Jarkal Mossmeld a Kargath per scoprire se ha avuto successo.",
  reward = "La fonte di energia che mi hai dato è andata oltre ogni mia aspettativa. Sono riuscito a farci una collana per te e una per me, e ne è avanzata abbastanza per farne almeno altre tre. Renderanno parecchio, e Recuperi Droffers e Figlio non ne sapranno niente.$B$BEcco a te, $Gamico mio:amica mia;. Grazie per lo splendido lavoro... e per il disturbo ti do qualcosa di davvero speciale.",
  en_title = "Necklace Recovery, Take 3",
  en_obj = "Visit Jarkal Mossmeld in Kargath to see if he was successful.",
}
T[2342] = {
  title = "Tesori Recuperati",
  desc = "A un Garrett non si addice spazzare i recinti dei pipistrelli con questa scopa! Questo lavoro maledetto mi ha fruttato qualche moneta, e pur di migliorare la mia condizione sono disposto a spenderla per te.$B$BDa quando noi Garretts sgobbavamo laggiù come scavatori, l'arma prediletta della famiglia Garrett è chiusa nel nostro baule, nella South Common Hall of Uldaman. Senza quell'arma resterò bloccato qui per sempre — letteralmente — a spazzare lo sporco di questi pipistrelli infernali.$B$BVa' a recuperare il tesoro della mia famiglia e portamelo! Aiutami a riprendermi quello che mi spetta per nascita!",
  obj = "Prendi il tesoro di famiglia di Patrick Garrett dal baule di famiglia in South Common Hall of Uldaman e portaglielo a Undercity.",
  progress = "Spazzo e spazzo, e non si finisce mai... questi pipistrelli non si stancano di prendersi gioco di me e della mia scopa. Ti prego, dimmi che hai recuperato il tesoro della mia famiglia! Ti ho offerto il mio argento — non ti basta?!",
  reward = "Finalmente — una scopa degna di un Garrett. Te lo dico io: vali eccome fino all'ultima moneta d'argento che ho speso per te!$B$BMi sentite, luridi pipistrelli? Adesso impugno l'arma prediletta della famiglia Garrett! Tremate, pipistrelli, tremate!!",
  en_title = "Reclaimed Treasures",
  en_obj = "Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.",
}
T[2358] = {
  title = "Horns of Nez'ra",
  desc = "Molti anni fa, le Horns of Nez'ra sono state rubate dalla tenuta di Ravenholdt. Le ho cercate per continenti e oceani, e alla fine ho scoperto che erano sempre state nelle mani di queste bestie insignificanti.$B$BUccidi ogni orco Blackrock che incontri, finché non avrai recuperato le Horns of Nez'ra. Se riuscirai a ritrovarle, cercami a Lakeshire.$B$BFallo per me e il tuo nome sarà noto a Ravenholdt, $N.",
  obj = "Riporta le Horns of Nez'ra ad Arantir's Shadow a Lakeshire.",
  progress = "Hai le corna del principe demone?",
  reward = "Privare Ravenholdt dell'artefatto sarebbe come rinnegare la propria stessa esistenza. Ben fatto, $Gladro:ladra;. Un giorno potresti far parte degli assassini di Ravenholdt.$B$BQuando ero un giovane ladro in cerca d'avventure a Darkshore, ho scoperto un infuso che ripristina l'energia in combattimento. Mi è stato utile per tutti questi anni, e ora ti lascio un assaggio del thistle tea. Bevine quando ti senti $Gstanco:stanca;, $N, e torna a combattere con vigore!",
  en_title = "Horns of Nez'ra",
  en_obj = "Return the Horns of Nez'ra to Arantir's Shadow in Lakeshire.",
}
T[2359] = {
  title = "La Torre di Klaven",
  desc = "Sono settimane che tengo d'occhio questa torre, $N. Poco tempo fa è arrivato un grosso carico da Duskwood, e con lui sono arrivate anche quelle guardie.$B$BCosa sono? Ne so quanto te. Una cosa però posso dirtela — non sono umane.$B$BComunque, nel carico c'era un forziere — e immagino che sia proprio quello che stanno sorvegliando quegli abomini. Lo zombi con gli spuntoni ha una chiave che ci servirà.$B$BPrendi quella chiave, entra nella torre e scopri cosa c'è in quel forziere. Quello che trovi, portalo a Mathias.",
  obj = "Ruba la Defias Tower Key, introduciti nella Defias Tower e scopri il contenuto del Duskwood Chest. Porta tutte le informazioni che trovi a Mathias Shaw a Stormwind. Leggi il Kearnen's Journal per saperne di più sulla torre.",
  progress = "Novità da Agent Kearnen?",
  reward = "Questo spiegherebbe i servi Defias che tu e Kearnen avete visto fuori dalla torre, $N. E spiegherebbe anche perché la Venture Company è coinvolta con i Defias, e gli strani carichi in arrivo da Duskwood.$B$BSecondo questo libro, i troll Zanzil di Stranglethorn hanno trovato il modo di resuscitare i morti con delle pozioni... o, per la precisione: con il veleno.$B$BSenza una solida conoscenza dei veleni al SI:7 non servirai a nulla, $N — tanto più ora che abbiamo a portata di mano la ricetta per creare la non morte.",
  en_title = "Klaven's Tower",
  en_obj = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower.$B",
}
T[2360] = {
  title = "Mathias e i Defias",
  desc = "Arrivi giusto in tempo, $N. Secondo le ricognizioni del SI:7, a Westfall i Defias sono insolitamente attivi.$B$BA quanto pare hanno occupato una torre di guardia abbandonata dell'Alleanza, a sud-est di Sentinel Hill, e ne hanno fatto la loro base operativa: da lì fanno arrivare di contrabbando merci dalla rotta di rifornimento di Redridge.$B$BVa' a Westfall e fatti fare rapporto da Agent Kearnen. La troverai nascosta vicino alla torre.$B$B... e $N, se vieni $Gscoperto:scoperta;, il SI:7 negherà di sapere che esisti.",
  obj = "Raggiungi Westfall e trova Agent Kearnen per il rapporto.",
  reward = "Era ora che Mathias mi mandasse $Gun altro agente:un'altra agente; a darmi man forte, eh? Beh, spero che sia $Gpronto:pronta; a sentire qualche brutta notizia.",
  en_title = "Mathias and the Defias",
  en_obj = "Travel to Westfall and find Agent Kearnen for your debriefing.",
}
T[2361] = {
  title = "Restaurare la Collana",
  reward = "Questa collana te la do volentieri, possente $C. Mi hai reso un servizio inestimabile, e di questo ti ringrazio. Portala con orgoglio, e mi raccomando, di' a voce alta e più di una volta chi te l'ha fatta!$B$BE se poi ti riuscisse di buttare lì che non è maledetta per davvero, sarebbe fantastico.",
  en_title = "Restoring the Necklace",
}
T[2378] = {
  title = "Trova la Shattered Hand",
  desc = "Hai servito bene i Deathstalkers, $N, ma forse è ora che tu ti spinga più lontano. Nelle arti della furtività e dell'inganno hai mostrato talento, eppure ti serve ancora molto addestramento.$B$BI Deathstalkers hanno degli alleati nella Shattered Hand. Cerca chi è disposto ad aiutarci — trova Shenthul a Orgrimmar.",
  obj = "Viaggia fino a Orgrimmar e parla con Shenthul alla Cleft of Shadow.",
  reward = "Quindi saresti tu ciò che i nostri potenti alleati hanno mandato a Shenthul? Non è proprio entusiasmante....",
  en_title = "Find the Shattered Hand",
  en_obj = "Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow.",
}
T[2379] = {
  title = "Zando'zan",
  desc = "La tua determinazione, da sola, non basta per superare gli ostacoli che ci aspettano.$B$BPer cominciare il tuo addestramento da agente della Shattered Hand, parla con Zando'zan.$B$BPotrai fare il passo successivo verso il tuo destino solo quando avrai padroneggiato le arti della furtività e del furto.",
  obj = "Parla con Zando'zan alla Cleft of Shadow.",
  reward = "Forse Zando'zan ha sbagliato. Zando'zan chiede scusa.",
  en_title = "Zando'zan",
  en_obj = "Speak with Zando'zan at the Cleft of Shadow.",
}
T[2380] = {
  title = "A Orgrimmar!",
  desc = "Non sei $Gun maestro:una maestra; della furtività e dell'inganno, ma le cose possono cambiare, e cambieranno. Evidentemente con le tue scarse capacità hai colpito chi comanda, visto che il grande Shenthul ha chiesto di te per nome.$B$BSegui la strada che da qui va a nord fino a Orgrimmar e parla con Shenthul nella Cleft of Shadow.",
  obj = "Parla con Shenthul alla Cleft of Shadow, in Orgrimmar.",
  reward = "È importante che la Shattered Hand resti vigile davanti ai cambiamenti che Thrall vuole portare nell'Orda. Per rovesciare il suo dominio non basterà essere in tanti — bisogna padroneggiare la furtività e l'inganno.",
  en_title = "To Orgrimmar!",
  en_obj = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar.",
}
T[2381] = {
  title = "Saccheggiare i Saccheggiatori",
  desc = "Non voglio spaventarti, $N, ma gli ultimi cinque ladri che ho mandato a rubare il southsea treasure mi sono tornati indietro a pezzi.$B$BPiù a sud lungo la costa troverai la Tide Razor, la nave del southsea freebooter. Il bottino è riposto nella stiva — il southsea treasure. Sul secondo ponte c'è il covo dei pirati, dove addestrano tutti i loro ladri.$B$BSali a bordo, ruba il tesoro e riportamelo. Se ti serve allenarti a rubare, usa il covo dei pirati, ma stai $Gattento:attenta;!",
  obj = "Riporta il Southsea Treasure a Wrenix the Wretched a Ratchet. Non dimenticare di prendere un E.C.A.C. e i Thieves' Tools da Wrenix's Gizmotronic Apparatus. Ti serviranno entrambi per completare la missione.$B$BSe vieni $Gattaccato:attaccata; da pappagalli insolitamente ostili, usa il tuo E.C.A.C.!",
  progress = "Be', almeno i pezzi del corpo ce li hai ancora tutti. Il tesoro l'hai trovato?",
  reward = "Incredibile! Improbabile! Semplicemente stupefacente! Hai talento, $N. O magari sei $Gl'uomo più fortunato:la donna più fortunata; del mondo!$B$BEcco la tua parte del bottino. Sono sicuro che questa roba la sapresti usare meglio di me.",
  en_title = "Plundering the Plunderers",
  en_obj = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.$B$BShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!$B$B",
}
T[2382] = {
  title = "Wrenix di Ratchet",
  desc = "Zando'zan l'ha visto! Sì, il giorno sta arrivando! La morte di Thrall... il pugnale nella schiena, il veleno che gli scorre in ogni vena... Zando'zan ha detto troppo.$B$B$N! Zando'zan ha un compito per $N! $N deve andare a Ratchet, a est del Crossroads, e parlare con Wrenix the Wretched. Vai!",
  obj = "Viaggia fino a Ratchet e parla con Wrenix the Wretched.",
  reward = "$GUn altro:Un'altra;? Gli ultimi cinque che mi ha mandato quel troll pazzo sono finiti in pasto agli squali. Speriamo che a te vada un po' meglio, eh?",
  en_title = "Wrenix of Ratchet",
  en_obj = "Travel to Ratchet and speak with Wrenix the Wretched.",
}
T[2383] = {
  title = "Simple Parchment",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene dall'addestratore dei guerrieri, Frang. Vorrebbe scambiare due parole con te quando sarai $Gpronto:pronta;. Lo troverai fuori da The Den, riparato all'ombra.",
  obj = "Leggi la Simple Parchment e parla con Frang in Valley of Trials.",
  progress = "Che cos'hai lì? Una pergamena? Spero che tu non sia $Guno studioso:una studiosa;...",
  reward = "Ah, è la mia pergamena. Avevo sentito che saresti $Garrivato:arrivata; nella Valle, $N. Sono contento che tu ce l'abbia fatta — speriamo che tu sopravviva alle prove che ti aspettano. Come ti ho detto, vieni da me man mano che diventi più forte — farò il possibile per addestrarti nelle vie $Gdel:della; $C.$B$BBuona fortuna, $N, e torna da me ogni volta che ti senti $Gpronto:pronta;.",
  en_title = "Simple Parchment",
  en_obj = "Read the Simple Parchment and speak to Frang in the Valley of Trials.",
}
T[2398] = {
  title = "I Nani Perduti",
  desc = "Il sito di scavo di Uldaman non è sempre stato invaso. Una volta la zona la tenevamo noi nani di Ironforge, ma... questo prima che arrivassero i troggs. Ne sono arrivati così tanti e così in fretta che neanche la forza dei nani è bastata a fermarli!$B$BAnzi, ci sono piombati addosso così all'improvviso che temo che qualcuno dei nostri sia rimasto intrappolato dietro le linee nemiche.$B$BPoco prima che spuntassero i troggs, il mio amico Baelog ha portato un piccolo gruppo di nani nel cuore del sito. Se lui e i suoi compagni sono vivi, voglio che tu li trovi.",
  obj = "Trova Baelog a Uldaman.",
  reward = "Era ora che arrivassi! Stavo per perdere una scommessa con Olaf!$B$BHa scommesso che gli sarebbe cresciuta la barba fino alle ginocchia prima di vedere $Gun altro:un'altra; $R $Gvivo:viva;. Beh, eccoti qui, e come vedi alla barba di Olaf manca ancora qualche pollice.$B$BGrazie, $N. La vincita la divido con te.",
  en_title = "The Lost Dwarves",
  en_obj = "Find Baelog in Uldaman.",
}
T[2418] = {
  title = "Pietre del Potere",
  desc = "Tempo fa mi è capitata una disavventura con gli Shadowforge Dwarves. Mi hanno portato all'Angor Fortress per studiare due tipi di strane pietre che venivano da Uldaman. Ho scoperto che, a trattarle nel modo giusto, erano fonti di energia stabili e durature. Incredibile cosa salta fuori da quel vecchio scavo!$B$BComunque, dopo che gli ho svelato il segreto delle pietre, mi hanno cacciato dall'Angor Fortress e si sono messi a scavare a Uldaman per trovarne altre.$B$BQuelle pietre le voglio per me! Portamene di tutti e due i tipi e ti pagherò profumatamente!",
  obj = "Porta 8 Dentrium Power Stones e 8 An'Alleum Power Stones a Rigglefuzz nelle Badlands.",
  progress = "Ce le hai, le pietre del potere, $N? Ho un roditore robotico a cui serve una fonte di energia...",
  reward = "Fantastico, ne hai trovate! Grazie mille, $N. Sei $Gil:la; $R più affidabile che abbia mai incontrato!$B$BNon vedo l'ora di provarle su certi congegni su cui sto armeggiando. Scommetto che, nelle condizioni giuste, con queste pietre dentro continueranno ad andare, e andare, e andare...",
  en_title = "Power Stones",
  en_obj = "Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.",
}
T[2439] = {
  title = "I Dischi di Platino",
  desc = "Questo oggetto è una scoperta incredibile. Se le conoscenze che custodisce sono giuste, gli antichi Titani, o i Creatori, come li chiamano i dischi, sono il legame con la nostra creazione incantata! Dovremo studiarlo il più a lungo possibile.$B$BQuanto a te, $Geroico:eroica; $C, porta questo buono a Dinita Stonemantle, al caveau. Ti dà diritto a quella che ritengo una giusta ricompensa per una scoperta così straordinaria!$B$BQuando sarai $Gpronto:pronta;, torna direttamente da me: c'è ancora molto da fare per l'Explorers' League!",
  obj = "Porta il reward voucher a Dinita Stonemantle in Vault of Ironforge.",
  progress = "$GBenvenuto:Benvenuta; nel Vault of Ironforge, $N. Cosa posso fare per te, oggi?",
  reward = "Ah, sì, un buono dell'Explorers' League... e di gran valore, aggiungerei.$B$BL'Explorers' League mi autorizza a darti una ricompensa a tua scelta, presa direttamente dal suo caveau. Riceverai questo oggetto, e come premio potrai scegliere fra cinque superior healing potions o cinque greater mana potions.",
}
T[2440] = {
  title = "I Dischi di Platino",
  desc = "Dedicherò le mie energie a questi dischi, e a tempo debito mi sveleranno come funzionano davvero.$B$BQuanto a te, $N, hai avuto la diligenza di segnalarmelo, e ora avrai la tua ricompensa. Porta questo buono a Bena Winterhoof, l'istruttrice di alchimia di Thunder Bluff: ti consegnerà un oggetto speciale che, credo, ti interesserà, e ti farà scegliere tra alcune pozioni della mia scorta personale.$B$BTorna presto da me, però: sento che questa scoperta ci darà ancora parecchio da fare.",
  obj = "Porta il reward voucher a Bena Winterhoof a Thunder Bluff.",
  progress = "Saluti, $C! Sei qui per addestrarti nell'alchimia, o magari per qualcos'altro?",
  reward = "Bene, $N, se Sage Truthseeker ti ha dato questo oggetto, devi averlo reso molto contento. Ti spetta anche un dono dalla sua scorta di pozioni: come ricompensa puoi scegliere tra 5 superior healing potions e 5 greater mana potions.",
  en_title = "The Platinum Discs",
  en_obj = "Take the reward voucher to Bena Winterhoof in Thunder Bluff.",
}
T[2458] = {
  title = "Sotto Copertura",
  desc = "La Venture Company... Ne avrai forse sentito parlare?$B$BCi abbiamo messo un anno a infiltrare un nostro agente in profondità nelle loro file. È costata molta fatica e un piano studiato con cura, ma ce l'abbiamo fatta.$B$BDa poco abbiamo saputo che la Venture Co. sta preparando qualcosa di grosso. Vai alla torre della Venture Co., a nord della Sludge Fen, e mettiti in contatto con il nostro agente sotto copertura, Taskmaster Fizzule.$B$BQuando trovi la torre, usa questo flare gun, poi avvicinati a Fizzule e fagli vedere il saluto della Shattered Hand.",
  obj = "Raggiungi Venture Co. Tower, a nord della Sludge Fen, e contatta l'agente segreto della Shattered Hand, Taskmaster Fizzule.$B$BQuando la torre è in vista, usa la Flare Gun per segnalare il tuo arrivo a Taskmaster Fizzule. Spara DUE razzi, poi avvicinati a Taskmaster Fizzule ed esegui il Saluto della Shattered Hand con /salute.$B$BQueste azioni vanno eseguite nell'ordine giusto, perché Fizzule attaccherà ed eliminerà chiunque non riconosca.",
  reward = "Fa piacere vedere $Gun altro agente:un'altra agente; della Shattered Hand da queste parti, anche se col razzo forse hai un po' esagerato!$B$BLa prossima volta che hai bisogno di parlarmi, soffia due volte in questo fischietto: così saprò che sei $Gun alleato:un'alleata;.",
  en_title = "Deep Cover",
  en_obj = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.$B$BWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.$B$BThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize.",
}
T[2460] = {
  title = "Il Saluto della Shattered Hand",
  desc = "Da $Gladro:ladra; della Shattered Hand, è fondamentale che impari il Saluto della Shattered Hand: è l'unico modo per riconoscere con certezza un altro membro della Hand.$B$BGuarda, impara, ripeti.",
  obj = "Esegui il Saluto della Shattered Hand su Shenthul.",
  progress = "Esercitati!",
  reward = "Ben fatto, $N. Adesso sei $Gpronto:pronta; per andare avanti.",
  en_title = "The Shattered Salute",
  en_obj = "Perform the Shattered Salute on Shenthul.",
}
T[2478] = {
  title = "Missione: Possibile ma Non Probabile",
  desc = "Dovrai rubare la chiave della torre a Foreman Silixiz, $N. Quando avrai la chiave, tienila — potrebbe servirmi più avanti.$B$BRicorda, il veleno ha indebolito ogni cosa in questa torre. Usa le tue abilità per seminare caos e distruzione fra i suoi abitanti. Uccidili tutti — non avere pietà!$B$BQuando là dentro tutto giacerà in un mucchio insanguinato, scassina il forziere di Gallywix e ruba la cassa di mistura di Zanzil che vi è contenuta. Porta sia la testa di Gallywix sia la mistura a Shenthul, a Orgrimmar.",
  obj = "Ruba la Silixiz's Tower Key a Foreman Silixiz, poi uccidi due il Mutated Venture Co. Drones, due Venture Co. Patrollers e due la Venture Co. Lookouts.$B$BAssassina il Gran Caposquadra Gallywix e prendine la testa, poi scassina il forziere di Gallywix e ruba la Cache of Zanzil's Altered Mixture. Riporta la Cassa e la Gallywix's Head a Shenthul, a Orgrimmar, per ulteriori istruzioni.",
  progress = "Che cos'hai da riferire, $N?",
  reward = "Povero Fizzule, era un buon agente — uno dei nostri migliori. Ahimè, è il prezzo da pagare, $N. Fare l'agente sul campo per la Shattered Hand è un lavoro pericoloso.$B$BHai svolto bene il tuo dovere, $C. Sarebbe un peccato se non vivessi abbastanza da servirci di nuovo.",
  en_title = "Mission: Possible But Not Probable",
  en_obj = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.$B$BAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction.$B",
}
T[2479] = {
  title = "L'Aiuto di Hinott",
  desc = "Porta un campione della mistura a Serge Hinott, a Tarren Mill.$B$BSe c'è qualcuno che può curarti, è Serge. Se vivrai abbastanza a lungo, Serge ti mostrerà come creare e usare i veleni.",
  obj = "Viaggia fino a Tarren Mill, in Hillsbrad Foothills, e consegna il Sample of Zanzil's Mixture a Serge Hinott.$B$BPer arrivare a Tarren Mill, prendi lo Zeppelin per Undercity e segui la strada a sud attraverso Silverpine, in direzione di Hillsbrad. Segui i cartelli!",
  progress = "E questo cos'è???",
  reward = "Sei deliziosamente $Gpallido:pallida;, $C. E cos'è quell'odore nauseabondo che emani? Devo saperlo!",
  en_title = "Hinott's Assistance",
  en_obj = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.$B$BTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!$B$B",
}
T[2480] = {
  title = "L'Aiuto di Hinott",
  desc = "Non ho mai visto risultati così meravigliosi da un veleno! Zanzil, dici? Mai sentito nominare, ma devo fargli i complimenti per aver creato questo intruglio.$B$BDunque, dovrei curarti e poi insegnarti a usare il veleno?$B$BDammi qualche momento per esaminare la tossina, $N.",
  obj = "Attendi che Serge Hinott completi la cura.",
  reward = "La cura è pronta! Bevi questa antitossina e la follia strisciante si fermerà, ma per l'odore non potrò fare nulla.",
  en_title = "Hinott's Assistance",
  en_obj = "Wait for Serge Hinott to complete the cure.",
}
T[2521] = {
  title = "Al Servizio di Kum'isha",
  desc = "$R, quel tuo cervello minuscolo riesce a capire quanto sia rara una sfera di draenethyst perfetta? I Draenei hanno passato vite intere a cercare anche uno solo di questi cristalli, e sono andati incontro a una fine orribile senza averlo mai trovato.$B$BE tu ti presenti davanti a Kum'isha, sai cosa ha chiesto Kum'isha e vuoi ancora aiutare? Bene, $R... Se mai, viaggiando per queste terre, ti capitasse di trovare una sfera di draenethyst perfetta, portamela: ti ricompenserò con ricchezze che non hai mai nemmeno sognato.",
  obj = "Durante i tuoi viaggi nelle Blasted Lands, se mai dovessi trovare una Flawless Draenethyst Sphere, porta l'oggetto a Kum'isha the Collector.$B$BAttenzione: questa gemma è uno dei cristalli più rari di tutta Azeroth. Qualsiasi creatura di queste terre potrebbe avere con sé una Flawless Draenethyst Sphere.$B$BRiceverai una ricompensa per ogni Flawless Draenethyst Sphere che avrai raccolto.",
  progress = "Ho dedicato la vita a cercare le flawless draenethyst spheres. Tutta la vita, $R!",
  reward = "I miei occhi mi ingannano? Impossibile! Dove l'hai... Come...$B$BForse adesso si potrà aprire un varco che ci riporti in patria.",
}
T[2522] = {
  title = "Gli Sforzi di Kum'isha",
  desc = "L'evocazione del portale è fallita, ma confido che il prossimo tentativo andrà a buon fine.$B$BLa speranza dei Draenei arde quanto la tua avidità di ninnoli, $R. Torna in queste terre maledette e procurami un'altra flawless draenethyst sphere.$B$BNaturalmente, se accettare o no questo compito lo decidi solo tu *ghigno*.",
  obj = "Trova una Flawless Draenethyst Sphere e portala a Kum'isha the Collector.",
  progress = "Hai trovato un'altra flawless draenethyst sphere?",
  reward = "Semplicemente straordinario. Dubitavo che riuscissi a trovare un'altra sfera, eppure eccola qui, che pulsa fra le mani.$B$BBen fatto, $N!$B$BSe ne trovassi altre — e credo che sia impossibile — riportamele e ti ricompenserò ancora.",
}
T[2523] = {
  title = "Corrupted Songflower",
  progress = "Hai trovato quella che pare una pianta di songflower, ma malata e corrotta. Manda un odore pungente e malsano, e per tornare com'era ha un disperato bisogno di cure.",
  reward = "Spalmi sul songflower un po' di unguento per piante Cenarion, e subito la pianta comincia a perdere la forma corrotta e rifiorisce, rigogliosa e sana.",
}
T[2581] = {
  title = "Snickerfang Jowls",
  desc = "Tutti sanno che le iene hanno nelle guance una forza tremenda, ma tanta da spezzare tre pollici di acciaio di torio? Impossibile, improbabile, eppure l'ho visto con i miei occhi.$B$BAvventurati nelle Blasted Lands e portami tre snickerfang jowls. E mentre cerchi gli snickerfang, tieni d'occhio cinghiali e scorpok: per completare il preparato iniziale mi servono anche due blasted boar lungs e una scorpok pincer.",
  obj = "Porta tre Snickerfang Jowls, due Blasted Boar Lungs e una Scorpok Pincer a Bloodmage Drazial.",
  progress = "Puzzi, $N. Te ne sei $Gandato:andata; a spasso per i campi di zolfo? E i miei componenti, dove sono?!",
  reward = "Come ti senti, $N? Emani l'aura dello snickerfang — nessun mortale ha una forza come la tua!$B$BPurtroppo, con i componenti che mi hai portato, sono riuscito a ricavarne il preparato per una tavoletta sola. Se te ne servirà un'altra, avrò bisogno di altri componenti.",
}
T[2582] = {
  title = "Furia dei Secoli",
  desc = "Ah, $N, $Gbentornato:bentornata;. A quanto pare ti è piaciuto l'effetto dell'infusione robusta e operativa che si ricava dallo snickerfang. Ti avverto: sul momento ti dà un'esplosione di forza titanica, ma alla lunga potrebbe essere un pericolo per lo spirito e l'intelligenza.$B$BDetto questo, ne hai ancora bisogno? Allora portami altre tre snickerfang jowls, due blasted boar lungs e una scorpok pincer.",
  obj = "Porta tre Snickerfang Jowls, due Blasted Boar Lungs e una Scorpok Pincer a Bloodmage Drazial.",
  progress = "Hai portato gli organi delle bestie?",
  reward = "Ecco qua! E ricorda: usala con parsimonia. Se te ne serve un'altra, torna da me quando avrai finito questa.",
}
T[2583] = {
  title = "La Vitalità di un Cinghiale",
  desc = "In queste terre devastate vivono due specie di cinghiale: il cinghiale criniera di cenere e il cinghiale infernale.$B$BSembrerebbe che queste bestie siano così resistenti da essere quasi immuni ai danni: per gli altri animali sono troppo difficili da uccidere, e non vale la pena provarci.$B$BDobbiamo fare altre analisi, $N. Portami tre blasted boar lungs, due scorpok pincers e un basilisk brain, e dal residuo del preparato creerò un elisir divino. Sarai la mia prima cavia!",
  obj = "Porta tre Blasted Boar Lungs, due Scorpok Pincers e un Basilisk Brain a Bloodmage Drazial.",
  progress = "Gli organi dove sono, $N!?",
  reward = "Lo spirito del cinghiale illumina il tuo essere, $N! Mi domando: ti credi invulnerabile come queste bestie?",
}
T[2584] = {
  title = "Spirito del Cinghiale",
  desc = "La prima volta che ti ho somministrato l'elisir, $N, ho capito che una o due dosi non ti avrebbero saziato l'appetito. E anche adesso ti leggo la fame negli occhi. A quanto pare l'intruglio dà una dipendenza a cui non sa resistere nemmeno chi ha la volontà più forte.$B$BE così sia! Se ti serve altro lung juice cocktail, torna nella landa desolata e procurami tre blasted boar lungs, due scorpok pincers e un basilisk brain.",
  obj = "Porta tre Blasted Boar Lungs, due Scorpok Pincers e un Basilisk Brain a Bloodmage Drazial.",
  progress = "Gli organi dove sono, $N!?",
  reward = "Devo avvertirti, $N: non provare a mescolare le formule che ho creato. Le proprietà chimiche dell'ultima che hai ingerito avranno sempre la meglio sugli incantamenti precedenti; l'altra formulazione, così, non avrà più effetto.",
}
T[2585] = {
  title = "L'Assalitore Risoluto",
  desc = "Li hai mai visti combattere, $N? Gli scorpok, dico. Hai mai notato con quanta grazia e agilità si muovono? E con che decisione colpiscono?$B$BSe solo trovassimo il modo di isolare quell'agilità e racchiuderla, saremmo ricchi oltre ogni nostra... voglio dire... sarebbe una manna per la comunità scientifica.$B$BSe mi aiuti, $N, ti concederò un assaggio del preparato.$B$BPer ottenere un campione stabile mi serviranno tre scorpok pincers, due vulture gizzards e un blasted boar lung.",
  obj = "Porta tre Scorpok Pincers, due Vulture Gizzards e un Blasted Boar Lung a Bloodmage Drazial.",
  progress = "Gli organi dove sono, $N!?",
  reward = "Affascinante. Nessun altro preparato è stato così difficile da analizzare.$B$BPrendi un pizzico di questo sale residuo e mettilo sotto la lingua. Dovresti sentire prima una leggera euforia, poi un'agilità e una rapidità senza precedenti.",
}
T[2586] = {
  title = "Sale dello Scorpok",
  desc = "Sei $Gvivo:viva;! Questa sì che è una bella notizia. Immagino che tu sia $Gtornato:tornata; per dell'altro assaggio di scorpok?$B$BMolto bene, $N. Torna nelle terre desolate e non ripresentarti qui prima di aver raccolto tre scorpok pincers, due vulture gizzards e un blasted boar lung.",
  obj = "Porta tre Scorpok Pincers, due Vulture Gizzards e un Blasted Boar Lung a Bloodmage Drazial.",
  progress = "Dove sono gli organi, $N!?",
  reward = "Ottimo lavoro, $N. Questo campione dell'assaggio è per te; gli altri nove li userò per le ricerche.$B$BTutte le volte che ti servirà dell'altro ground scorpok assay, torna da me e un accordo lo troveremo.",
}
T[2601] = {
  title = "Il Morso del Basilisco",
  desc = "Queste terre desolate sono infestate dal redstone basilisk, $N. Questi basilischi si sono adattati e prosperano più di qualunque altro animale selvatico della regione.$B$BLi ho osservati da lontano mentre cacciano e svolgono le attività di ogni giorno — queste bestie ragionano in modo più complesso persino di certi umanoidi.$B$BDevo studiarne i cervelli!$B$BPortamene dieci, $N. Il composto, però, non si può completare senza due vulture gizzards come base della soluzione.",
  obj = "Porta dieci Basilisk Brains e due Vulture Gizzards a Bloodmage Lynnore.",
  progress = "Sei $Gtornato:tornata; con gli organi che ti avevo chiesto?",
  reward = "Meraviglioso, $N! In dono ti offro un assaggio di come funziona dentro il redstone basilisk.$B$BSe il composto ti piace, se ne può sempre preparare dell'altro... a un prezzo.",
}
T[2602] = {
  title = "Mente Infallibile",
  desc = "Già ti si è affievolita la concentrazione? Servono altre ricerche!$B$BOh sì, il prezzo è sempre quello, $N. Avventurati nelle terre devastate e riportami dieci cervelli dei redstone e due vulture gizzards.",
  obj = "Porta dieci Basilisk Brains e due Vulture Gizzards a Bloodmage Lynnore.",
  progress = "Sei $Gtornato:tornata; con gli organi che ti avevo chiesto?",
  reward = "Sì, sì, dammi un momento e avrai dell'altro composto da consumare, $N.$B$BPrendilo... e $N, non provare ad assumere questi preparati sperimentali uno dopo l'altro. Le conseguenze potrebbero essere disastrose.",
}
T[2603] = {
  title = "Il Vigore dell'Avvoltoio",
  desc = "In queste terre devastate la morte ha davvero le ali, $R. Ho visto i black slayers e gli spolpaossa banchettare sul cadavere di più di un esploratore caduto — e a volte nutrirsi delle carcasse più ripugnanti e piene di malattie. E allora viene da chiedersi come il loro organismo riesca a vincere la pestilenza che si è presa queste terre.$B$BAiutami nei miei studi, $N! Stomaci mi servono! E per la base del preparato ci vorranno anche due snickerfang jowls.$B$BPer la fatica sarai $Gricompensato:ricompensata; il doppio.",
  obj = "Porta dieci Vulture Gizzards e due Snickerfang Jowls a Bloodmage Lynnore.",
  progress = "Non farmi perdere tempo, $N. Finché non avrai recuperato gli oggetti che ti ho chiesto, non abbiamo niente da dirci.",
  reward = "Davvero eccellente! Mi metto subito al lavoro. Forse ne uscirà una cura per molti dei mali del mondo!$B$BAh sì, la tua ricompensa — e naturalmente, se ti servirà altra cicca, torna da me: un altro incarico ti sarà affidato.",
}
T[2604] = {
  title = "Dominio Spirituale",
  desc = "Vedo che il fuoco dentro di te si è affievolito. Diresti che l'euforia dello spirito è durata un'ora?$B$BSe desideri altra gizzard gum, allora altri stomaci mi servono. Torna nelle terre desolate, $N, e non ripresentarti qui prima di aver recuperato dieci stomaci e due guance.",
  obj = "Porta dieci Vulture Gizzards e due Snickerfang Jowls a Bloodmage Lynnore.",
  progress = "Non farmi perdere tempo, $N. Finché non avrai recuperato gli oggetti che ti ho chiesto, non abbiamo niente da dirci.",
  reward = "Forse un giorno riuscirò a isolare gli enzimi attivi di questo assaggio e a ricavarne un prodotto molto più efficace. Per ora, purtroppo, dovrai accontentarti di quello che riesco a produrre. Se ti servirà altra gizzard gum, torna da me.",
}
T[2605] = {
  title = "Il Goblin Assetato",
  desc = "Vedi, mi è venuta un'idea. Ho sentito dire che a sud-ovest vivono delle strane creature, i raccoglitori di rugiada... e che sanno conservare l'acqua dentro ghiandole speciali.$B$BSe riuscissi a mettere le mani su una di quelle ghiandole, credo che ne tirerei fuori una bevanda capace di placare questa sete terribile! Te la senti di aiutarmi, $N?$B$BVai a cercare il giardino dei cactus, $N: i raccoglitori di rugiada li trovi lì.",
  obj = "Raccogli una Laden Dew Gland e portala a Marin Noggenfogger a Gadgetzan.",
  progress = "Ti prego, dimmi che li hai trovati, i raccoglitori di rugiada?",
  reward = "Oh, magnifico! Dammi qua — fammela bere!",
}
T[2606] = {
  title = "Di Buon Gusto",
  desc = "Bleah! Che sapore orribile, questa roba! E addio all'idea...$B$BAspetta, cosa? Oh, lo so, lo so, secondo te questa roba non va lasciata perdere. E va bene, allora.$B$BUhhhh, ho un'idea! Geniale! Porta questa rugiada alla mia amica Sprinkle — in cucina è bravissima. Raccontale cosa stiamo combinando e dille che vorremmo farla andare giù un po' meglio.$B$BCioè, se il sapore dev'essere così cattivo, che almeno dia una bella botta... E invece io la botta non la sento proprio...",
  obj = "Marin Noggenfogger vuole che tu parli con Sprinkle a Gadgetzan.",
  progress = "Il vecchio Marin ci sta riprovando, eh? E questo intruglio, di cosa è fatto?",
  reward = "Non fraintendermi, Marin è un tipo a posto — solo un po'... eccentrico, diciamo.$B$BE ovviamente, ancora una volta, gli serve il mio aiuto.",
}
T[2607] = {
  title = "Il Tocco di Zanzil",
  desc = "A quanto pare hai riportato più informazioni di quante me ne aspettassi perfino io. Le cose hanno preso una piega davvero strana, $N.$B$BUna cura? Mmh... Scendi in cantina e parla con Doc Mixilpixil — forse può aiutarti.",
  obj = "Parla con Doc Mixilpixil nella cantina della Caserma.",
  reward = "Era ora! Metti il formaggio sul tavolo e smamma. Osborne ti paga all'uscita.",
  en_title = "The Touch of Zanzil",
  en_obj = "Speak with Doc Mixilpixil in the cellar of the Barracks.",
}
T[2608] = {
  title = "Il Tocco di Zanzil",
  desc = "Oh cielo, sembri la morte in persona. Anzi, correggo — la morte l'ho vista, e tu hai un aspetto anche peggiore. Tu, $Gsignore:signorina;, saresti quello che la morte ha sputato tossendo all'ultima visita medica.$B$BAh! L'hai sentita, Noarm? Segnatela!$B$B*Coff* Ehm, sì, per aiutarti dovrò prelevarti un po' di sangue. Non preoccuparti, fa male solo le prime... cinquanta volte o giù di lì... Quando sei $Gpronto:pronta; per il trattamento usa /lay down, $N.",
  obj = "Usa /lay down e fatti visitare da Doc Mixilpixil. Come può trovare la cura, se non ne scopre la causa?",
  progress = "Quando sei $Gpronto:pronta; per la visita, sdraiati a terra con /lay down e comincio la flebotomia.",
  reward = "Dammi un momento, $N, devo consultarmi con i colleghi. Dottor Montgomery, Signor Noarm, a consulto!",
  en_title = "The Touch of Zanzil",
  en_obj = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?$B",
}
T[2609] = {
  title = "Il Tocco di Zanzil",
  desc = "Parere unanime, $N: hai la 'ite'.$B$BPer fortuna, per la 'ite' ho una cura.$B$BEcco cosa mi serve: un mazzo di simple wildflowers, una leaded vial, un bronze tube e infine, ma non certo per importanza, una spool of light chartreuse silk thread. Me ne ha lasciata una Ol' Emma, al 'Finest Thread', il negozio lungo i canali.$B$BOra sbrigati, $N, e finché non sarai $Gguarito:guarita; cerca di non toccare nessuno. Ah, e il Dottor Montgomery dice che ti serve una doccia — parole sue, non mie.",
  obj = "Porta a Doc Mixilpixil un mazzo di Simple Wildflowers, una Leaded Vial, un Bronze Tube e una Spool of Light Chartreuse Silk Thread. La 'ite' non passa da sola, $Ggiovanotto:signorina;.",
  progress = "Se vuoi guarire dalla 'ite' devi impegnarti più di così, $N. Dove sono i reagenti per la cura?",
  reward = "Cosa sto facendo? Che ti sembra che stia facendo? Preparo una cura per la tua 'ite'! Adesso non indignarti con me, $N!$B$BAncora qualche secondo. Ecco! Spruzzati addosso questa, ehm, medicina dal profumo fantastico e tornerai come $Gnuovo:nuova;.",
  en_title = "The Touch of Zanzil",
  en_obj = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young $g fella:lady;. ",
}
T[2621] = {
  title = "Il Disonorato",
  desc = "Rimpianto. Non mi resta altro. Una sola scelta sbagliata, e ne sono venute diverse conseguenze orribili. Se solo avessi aspettato quegli ordini. Forse avrebbero descritto gli orrori che ci aspettavano in quelle terre maledette! O forse dovevano mandarci a un altro incarico? Alla fine la colpa è stata mia. Tutta quanta mia.$B$BE adesso eccomi qui, ad aspettare ordini. Devo sapere. Devo avere quegli ordini.$B$BDispatch Commander Ruag è a Stonard. Trovalo e scopri che fine hanno fatto gli ordini.",
  obj = "Parla con Dispatch Commander Ruag a Stonard.",
  reward = "Thrall's Grasp... Ho ancora quella storia fresca nella memoria.$B$B<Commander Ruag scuote la testa.>$B$BUna cosa terribile, quello che è successo a quel reggimento. Quando hanno distrutto quel battaglione, l'orda ha perso alcuni dei suoi soldati migliori.",
}
T[2622] = {
  title = "Gli Ordini Scomparsi",
  desc = "Gli ordini? E che te ne faresti, degli ordini?$B$BChe cosa vorresti insinuare, $N? Certo che li ho mandati, quegli ordini! I soldati a cui li avevo affidati sono finiti in un'imboscata e i murlocs li hanno picchiati senza pietà. Se n'è salvato uno solo, sempre che quella si possa chiamare salvezza. Parla a malapena, non riesce a camminare e bisogna nutrirlo con un tubo. Se vuoi sapere che fine hanno fatto quegli ordini, parla con Bengor. Di sicuro è qui intorno da qualche parte... e, $N, sta' $Gattento:attenta; a dove ficchi il naso — potrebbero staccartelo a morsi.",
  obj = "Parla con Bengor.",
  reward = "Oratore delle pa... palu.. paludi...",
  en_title = "The Missing Orders",
  en_obj = "Speak to Bengor.",
}
T[2623] = {
  title = "Swamp Talker",
  desc = "Ordini dati da comandante delle comunicazioni. Noi... noi preso ordini. Su strada per le Blasted Lands, imboscata.$B$BMurlocs... Tanti murlocs... Uno chiamato Swamp Talker. Lui preso ordini da mie mani mentre lancia entrava in mio cranio. Est... grotta....$B$B<Bengor sviene.>",
  obj = "Recupera i Warchief's Orders e riportali al Fallen Hero of the Horde.",
  progress = "Aspetto gli ordini.",
  reward = "È peggio di quanto pensassi. A diciannove dei miei uomini si poteva risparmiare l'agonia che hanno sofferto. Se solo non avessi agito in modo tanto irrazionale.$B$BDevi aiutarli, $N! Io sono impotente.",
  en_title = "The Swamp Talker",
  en_obj = "Retrieve the Warchief's Orders and return them to the Fallen Hero of the Horde.",
}
T[2641] = {
  title = "L'Ingrediente Segreto di Sprinkle",
  desc = "Quando ero piccola, a cucinare era sempre mia sorella. Un orrore! Certi suoi intrugli riuscivo a malapena a mandarli giù — finché non ho trovato quello che mi piace chiamare il mio ingrediente \"segreto\"! Lo aggiungi a qualsiasi cosa e... WOW! Ha un sapore fantastico!$B$BChe cos'è, mi chiedi? Un fungo, il Violet Tragan. Se vuoi che ti aiuti a trasformare questa bevanda orrenda in qualcosa di commestibile, vai nelle Hinterlands e cerca un laghetto da quelle parti.$B$BAh, e ricordati: il Violet Tragan lo trovi solo sott'acqua.",
  obj = "Sprinkle a Gadgetzan vuole che tu raccolga un Violet Tragan e glielo riporti.",
  progress = "Sotto le acque di quel lago — solo lì si trova il Violet Tragan. Spero che tu sia $Gbravo:brava; a trattenere il respiro!",
  reward = "È proprio quello, $N!$B$BSembra così buono che quasi quasi... Ahah, ci sei $Gcascato:cascata;!",
}
T[2661] = {
  title = "Consegna per Marin",
  desc = "Ecco qua la Violet Powder, $N. Portala a Marin, e digli che mi deve un favore!",
  obj = "Sprinkle vuole che tu porti la Violet Powder a Marin Noggenfogger a Gadgetzan.",
  progress = "Oh, $N, finalmente sei $Gtornato:tornata;. Allora, cosa mi hai portato?",
  reward = "Violet Powder, eh? Proviamola — tanto peggio di così non può andare, poco ma sicuro!",
}
T[2662] = {
  title = "Noggenfogger Elixir",
  desc = "E ora mescoliamo questa polvere con la rugiada.$B$BTorna da me fra un minuto... quando avrò messo a punto il favoloso Noggenfogger Elixir!",
  obj = "Marin Noggenfogger vuole che tu gli parli di nuovo dopo che avrà creato l'elisir.",
  reward = "Bevi questo! È assolutamente meraviglioso!!!$B$BLo sapevo che avevo la stoffa... Oh, grazie ancora per l'aiuto, $N, ma per favore fatti un po' in là, eh? Mi intralci gli affari! Con il favoloso Noggenfogger Elixir farò milioni, milioni!$B$BCome? Sprinkle dice che le devo un favore? Oh, quella Sprinkle, che burlona!",
}
T[2681] = {
  title = "Le Pietre Che ci Legano",
  desc = "Le forze di Razelikh e dei suoi sottoposti non le sconfiggerai da $Gsolo:sola;.$B$BRaduna un buon gruppo di avventurieri e libera i miei uomini dalla loro tortura eterna! Diciotto pietre devi frantumare.$B$BCombatti con forza e muori con onore, $N.",
  obj = "Libera nove il Servants of Razelikh, tre il Servants of Sevine, tre il Servants of Allistarj e tre il Servants of Grol. Torna dal Fallen Hero quando avrai completato il compito. Devi restare vicino alle pietre, o il processo fallirà.",
  progress = "Non è un'impresa facile, $N, ma non arrenderti!",
  reward = "Ce l'hai fatta, $N! Finalmente quelle povere tortured souls possono riposare.$B$BMa il nostro lavoro non è ancora finito, $N: abbiamo molto di cui parlare, e ancora tanto da fare.",
}
T[2701] = {
  title = "Eroi del Passato",
  desc = "Ti prego, prendi da qui dentro una reliquia del passato: a noi non serve più.$B$BChe possa esserti utile nella lotta contro la legione.",
  obj = "Apri il forziere e prendi la tua ricompensa.",
  reward = "Per un momento lo scintillio e il luccichio ti accecano.",
}
T[2702] = {
  title = "Eroi del Passato",
  desc = "Con la tua nobiltà e il tuo eroismo mi hai reso onore, $N.$B$BE hai reso onore anche a loro...",
  obj = "Parla con Corporal Thund Splithoof.",
  reward = "È così: ci hai onorati tutti. Dirti grazie non basta.",
}
T[2721] = {
  title = "Kirith",
  desc = "Un capitolo della tua avventura si chiude, $N, e un altro comincia.$B$BManca ancora all'appello uno dei miei uomini, disperso da qualche parte nelle Blasted Lands: Lieutenant Kirith, naturalmente.$B$BCome ti ho già detto, Allistarj ci ha imprigionati e torturati tutti e due, ma al povero Kirith è venuta meno la forza di volontà. Dalla mia gabbia sentivo gli esperimenti; le urla strazianti risuonavano nei corridoi della grotta. È stata l'ultima volta che ho visto o sentito Kirith.",
  obj = "Scopri che fine ha fatto Lieutenant Kirith.",
  reward = "Trebor? È stato Trebor a mandarti?",
}
T[2741] = {
  title = "Il Super Egg-O-Matic",
  progress = "Il Super Egg-O-Matic, l'ultima invenzione di Curgle Cranklehop, è un macchinario davvero notevole.$B$BAppena ti avvicini al pannello di controllo, il Super Egg-O-Matic si mette a scoppiettare all'impazzata.",
  reward = "Metti l'hippogryph egg nella macchina, che risponde con una serie di bip e strani rumori meccanici.$B$BA quanto pare l'Ovometro ha pesato, misurato e impacchettato l'uovo. Questo sì che è un servizio rapido!",
}
T[2742] = {
  title = "Rin'ji È in Trappola!",
  desc = "Ehi, $R!$B$BRin'ji perso ascia, poi essere catturato! Per favore, aiuta Rin'ji a scappare. Me sapere che a $R come te non piace gente di Rin'ji, ma Rin'ji supplica! Dovere uscire di qui!$B$BSe $Glui:lei; aiuta Rin'ji a uscire di qui, avere qualcosa per $R gentile...$B$BQualcosa di segreto, Rin'ji nasconde sulle Overlook Cliffs.",
  obj = "Scorta Rin'ji fuori da Quel'Danil Lodge, poi trova il suo segreto nascosto a Overlook Cliffs, a est.",
  progress = "Rin'ji ha paura!",
  reward = "Il \"segreto\" di cui parlava Rin'ji dev'essere questa tavoletta troll.$B$BÈ coperta di strani segni che non riesci a decifrare.",
}
T[2743] = {
  title = "Il Favore delle Tenebre",
  desc = "Veniamo al dunque, $R; qui ho poco tempo.$B$BDevi distruggere la triade di potere che protegge Razelikh, il signore dei demoni, e non sarà semplice come liberare un'anima dannata.$B$B<Kirith sogghigna.>$B$BVedi, ciascuno dei sottoposti di Razelikh porta al collo un terzo di un amuleto che ha creato Razelikh: proprio quello che ti servirà per evocare l'arcidemone.$B$BTorna da Trebor e spiegagli cosa serve per evocare Razelikh. Lui saprà dirti cosa fare dopo.",
  obj = "Torna dal Fallen Hero of the Horde con le tue scoperte.",
  reward = "Il signore dei demoni è astuto e calcolatore quasi quanto è brutale, $N.",
}
T[2744] = {
  title = "Il Cacciatore di Demoni",
  desc = "È Razelikh a proteggere la triade.$B$BRazelikh li ha ripagati dei loro servigi dando a ciascuno di loro un potere quasi illimitato nelle Blasted Lands. Ogni pezzo dell'amuleto è legato alla forza vitale di chi lo porta e lo rende immortale: finché restano nelle Blasted Lands, nessuno può ucciderli, e la loro vita va avanti fino alla fine dei tempi.$B$BC'è qualcuno che potrebbe aiutarti ancora, $N. Va' ad Azshara e trova Loramus Thalipedes, il cacciatore di demoni. Cercalo sulle isole.",
  obj = "Parla con Loramus Thalipedes ad Azshara.",
  progress = "Che ci fai qui?",
  reward = "Ti aiuterò, ma non credo che tu sappia davvero contro cosa ti stai mettendo.",
}
T[2745] = {
  title = "Infiltrarsi nel Castello",
  desc = "Mmm, una storia interessante, e da prendere sul serio. Sì, posso aiutarti, ma per arrivare fino in fondo dovrai fare giustizia in un modo che non è... legale.$B$BBisogna sistemare Lescovar e Marzon, e in fretta. Credi di essere capace di una cosa del genere?$B$BSta a te deciderlo. Se sì, corri al castello e cerca un mio vecchio amico, uno gnomo che si chiama Tyrion. È da un paio di settimane che tiene d'occhio Lescovar, e dovrebbe poterti aiutare a chiudere la faccenda.",
  obj = "Parla con Tyrion in Stormwind Castle.",
  reward = "Ma che...?! Non arrivarmi alle spalle in quel modo! E parla piano! In nome dell'Ombra, cosa ti salta in mente di prendermi di sorpresa così? Non vedi che ho da fare, razza di $Gscemo:scema;?$B$BCome sarebbe a dire, cosa sto facendo? Aspetto che si apra il prossimo Dark Portal, cosa diavolo credi che stia facendo? Di' quello che hai da dire e sparisci... prima che le guardie ci vedano nascosti insieme nei cespugli. Ho una reputazione da difendere.",
  en_title = "Infiltrating the Castle",
  en_obj = "Speak to Tyrion in Stormwind Castle.",
}
T[2746] = {
  title = "Oggetti di una Certa Importanza",
  desc = "Così Trias vuole accelerare un po' i tempi, eh? Va bene, si può fare, però io non sono pronto. E sappi una cosa: la parte difficile la faccio io, ma $Gquello:quella; che si sporcherà le mani sei tu, capito? Bene.$B$BAllora, prima di mettere in atto il piano, devi procurarmi alcune cose. Ho il travestimento perfetto per far passare Spybot oltre quelle guardie.$B$BPortami un po' di seta e un paio di mele. Per la seta arrangiati, ma le mele della misura giusta le trovi alla piccola fattoria di Clara, appena fuori città.",
  obj = "Porta 3 Silk Cloth e 2 Clara's Fresh Apples a Tyrion a Stormwind.",
  progress = "È da un paio di settimane che tengo d'occhio Lescovar. Trias non si è mai fidato di lui, ma che c'entrasse con la Defias Brotherhood non lo sospettavamo: le piste che seguivamo lo collegavano al Twilight's Hammer. Comunque sia, è diventato troppo pericoloso perché la città riesca a tenerlo a bada, ed è qui che entriamo in gioco noi.$B$BProcurami quegli oggetti e potremo mettere in atto il mio piano.",
  reward = "Vanno benissimo, $N. Ottimo lavoro.$B$BIl resto dell'attrezzatura che mi serve ce l'ho nello zaino... grazie alla Luce, un mio amico sarto mi ha appena fatto una borsa di seta. Stavo restando senza spazio per tutta la roba che mi porto dietro.$B$BPrima che Spybot entri, sistemiamo i dettagli, così saprai cosa fare.",
  en_title = "Items of Some Consequence",
  en_obj = "Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind.",
}
T[2747] = {
  title = "Un Extraordinary Egg",
  progress = "Delle uova recuperate a Feralas, ben poche ne ho viste in condizioni straordinarie. Sono le uova più rare di tutte...",
  reward = "Ma bene, ne hai uno — incredibile!$B$BSpero che non dimenticherai mai il bene che hai fatto oggi.",
}
T[2748] = {
  title = "Un Fine Egg",
  progress = "Un fine egg è un uovo che, se le condizioni sono ideali, si schiuderà senza risentire degli effetti malvagi degli incantesimi degli ogres Gordunni.",
  reward = "Molto bene, $N. Quest'uovo lo mando a Darnassus, e spero che lì si schiuda presto!$B$BTi prego di accettare questo in segno di gratitudine.",
}
T[2749] = {
  title = "Un Ordinary Egg",
  progress = "Delle hippogryph eggs comuni se ne schiude più o meno una su due. Noi le accudiamo come meglio possiamo e, con un po' di fortuna, si schiuderanno.",
  reward = "Allora, $N, hai trovato un ordinary egg? Dammelo, per favore... e speriamo in bene.$B$BNon è molto quello che ho, ma accetta questa ricompensa, ti prego. E se mai tornassi a Feralas, ricordati che io sono sempre qui, pronta a prendere le uova che trovi laggiù.",
}
T[2750] = {
  title = "Un Bad Egg",
  progress = "Queste uova non si possono salvare — non si schiuderanno mai.",
  reward = "Temo di avere brutte notizie per te, $N. Quest'uovo è troppo rovinato. Posso prenderlo io e farlo smaltire come si deve.$B$BNon scoraggiarti, ti prego; non possiamo salvarle tutte. Se ti capita di tornare a Feralas, riprova. Porta un altro uovo per il Super Uovo-O-Matic!",
}
T[2751] = {
  title = "Bastioni Barbarici",
  desc = "Venti generazioni di Omosh hanno impugnato questo martello, $N. Centomila tonnellate di metallo abbiamo forgiato. E adesso, che tragedia, tutto finisce con Orokk, il fallimento degli Omosh: senza parenti e incapace di avere figli.$B$BNon posso lasciar morire con me le ricette segrete degli Omosh! Qualcuno deve portare avanti l'eredità, che sia un Omosh o no!$B$BDimostra a Orokk che sei capace, $N: porta a Orokk due patterned bronze bracers, due bronze greatswords e due sharp claws. Quando li porti a Orokk, andremo avanti.",
  obj = "Porta due Patterned Bronze Bracers, due Bronze Greatswords e due Sharp Claws a Orokk Omosh a Orgrimmar.",
  progress = "Bronzo, $N! Altro bronzo!!",
  reward = "La stirpe si spegnerà, ma la leggenda degli Omosh forse vivrà ancora!$B$BHai dimostrato di essere $Gun:una; fabbro, $N. E la ricompensa di un fabbro è la soddisfazione di vedere le sue armi e armature coperte del sangue dei nemici!$B$BPossano le corazze che forgerai per le generazioni future essere intrise del sangue dei tuoi nemici!",
}
T[2752] = {
  title = "Sugli Spallacci di Ferro",
  desc = "Orokk vede l'entusiasmo nei tuoi occhi, $N: la saggezza degli Omosh la assorbi come una spugna.$B$BTre lezioni ti insegnerò!$B$BTorna all'incudine, assorbi il calore della forgia e crea per Orokk quattro asce da battaglia di bronzo e quattro bronze warhammers. Solo allora imparerai lo spallaccio di ferro.",
  obj = "Porta quattro Asce da Battaglia di Bronzo e quattro Bronze Warhammers a Orokk Omosh a Orgrimmar.",
  progress = "Fammi vedere la tua dedizione, $R.",
  reward = "Orokk è fiero di te, $N. Leggi e impara le spalle di ferro!",
}
T[2753] = {
  title = "Schiacciati Sotto i Piedi",
  desc = "Orokk ha solo altre due lezioni da insegnare, $N. Lo so che ti fanno male i muscoli, ma non fermarti, fallo per gli Omosh!$B$BPorta a Orokk quattro green iron helms, quattro green iron bracers e due green iron leggings — così tu impari, e i tuoi nemici soffrono!",
  obj = "Porta quattro Green Iron Helms, quattro Green Iron Bracers e due Green Iron Leggings a Orokk Omosh a Orgrimmar.",
  progress = "Sotto il peso dei tuoi stivali, i loro crani si spaccheranno!",
  reward = "Ricordi a Orokk suo nonno, Chief Gorokk of Omosh! Leggi e impara lo stivale di ferro.",
}
T[2754] = {
  title = "Corna della Frenesia",
  desc = "Questa è l'ultima lezione che Orokk ti insegna, $N. Ritorna all'incudine sacra e alla forgia! Porta a Orokk due solid iron mauls, due silvered bronze boots e due silvered bronze gauntlets.$B$BGuarda la paura nei loro occhi quando ti avvicini!",
  obj = "Porta due Solid Iron Mauls, due Silvered Bronze Boots e due Silvered Bronze Gauntlets a Orokk Omosh a Orgrimmar.",
  progress = "Fa' vedere al ferro chi comanda, $N!",
  reward = "Straordinario! Ora la via degli Omosh l'hai imparata, $N!",
}
T[2755] = {
  title = "Gioie degli Omosh",
  desc = "Orokk non piange, $N. Fuliggine in occhio.$B$B<Orokk si asciuga una lacrima.>$B$BAgli Omosh resta un ultimo segreto di famiglia, e Orokk te lo insegnerà. Grazie a $N, Orokk morirà felice.$B$BPrima impara danza della gioia Omosh, poi impari pugno di ferro!",
  obj = "Guarda e impara Omosh Dance of Joy.",
  reward = "<Orokk ansima.>$B$BDa molto tempo Orokk non faceva la danza della gioia Omosh. Ora impara, $N!",
}
T[2756] = {
  title = "Le Antiche Usanze",
  desc = "Ai tempi delle leggende, Aturk spaccava i crani dei nemici e ne macinava le ossa fino a farne una polvere fine per i filamenti. Ma quei giorni sono lontani, $R. Il Capoguerra chiede la pace fra i clan, e adesso i vecchi nemici vengono solo tenuti d'occhio, con diffidenza!$B$BIncredibile, lo so, ma così vuole Thrall.$B$BBasta lamentarsi! Sei qui per imparare, e imparerai! Portami quattro steel breastplates e quattro elmi d'acciaio, e avrai un assaggio della guerra!",
  obj = "Porta quattro Steel Breastplates e quattro Steel Plate Helms ad Aturk the Anvil a Orgrimmar.",
  progress = "Aturk è come il tempo: non aspetta nessuno! Sbrigati, $Gsciocco:sciocca;!",
  reward = "A quanto pare non sei altro che l'ennesima pecora docile del Capoguerra, $N. Che delusione.$B$BCome vorrei morire gloriosamente sul campo di battaglia. E invece sono bloccato qui, per ordine di Thrall, a insegnare a forgiare ai poppanti! Guarda e impara, $Gragazzino:ragazzina;!",
}
T[2757] = {
  title = "Booty Bay o Niente!",
  desc = "Senti, $Gragazzo:ragazza;, a gironzolare da queste parti non imparerai niente.$B$BConosco un tizio che conosce un tizio. Bazzica la fucina di Booty Bay. Se gli mostri questo stemma, ti dirà tutto sul mithril.$B$BAllora, che ne dici? Lascia queste sciocchezze ai poppanti col pannolino, $N — è ora di andare avanti.$B$BSe ti interessa, il suo nome è McGavan. Mostragli questo gingillo e noterà la tua dedizione.",
  obj = "Parla con McGavan a Booty Bay.",
  progress = "Razza rara la tua, compare. Fammi vedere quello stemma.",
  reward = "Per i peli della schiena di Blackhoof — finalmente $Gqualcuno degno:qualcuna degna; di The Mithril Order!",
}
T[2758] = {
  title = "Le Origini dell'Arte del Fabbro",
  desc = "Quando avevo più o meno la tua età, un nano di nome Galvan mi ha preso sotto la sua ala e mi ha insegnato tutto quello che sapeva sulla forgiatura. Prima di partire per Booty Bay, mi ha fatto promettere di trasmettere il suo sapere a chiunque avesse il desiderio e la determinazione di progredire nel mestiere del fabbro — ed eccomi qui — dopo tutti questi anni.$B$BE adesso è ora che anche tu impari qualcosa. Forgiami sei Golden Scale Bracers e scoprirai da dove vien fuori l'arte del fabbro, $N.",
  obj = "Porta sei Golden Scale Bracers a Hank the Hammer a Stormwind.",
  progress = "Sarai tu $Gil prossimo erede:la prossima erede; di Galvan?",
  reward = "Molto bene, $N! Ascolta e impara.$B$BL'arte del fabbro non la trovi qui! <Hank indica il martello.>$B$BL'arte del fabbro non la trovi neanche qui! <Hank indica l'incudine.>$B$BL'arte del fabbro viene fuori solo da qui! <Hank indica il cuore.>$B$BE adesso sai da dove nasce l'arte del fabbro.",
}
T[2759] = {
  title = "Alla Ricerca di Galvan",
  desc = "Anche se Galvan ha lasciato Booty Bay molti anni fa, alcuni membri dell'ordine sono ancora in città, nella speranza di trovare un giorno qualcun altro degno degli insegnamenti di Galvan.$B$BPrendi questo stemma e mostralo a McGavan, a Booty Bay.$B$BSe riuscirai davvero ad arrivare fin là, saprà che ne sei $Gdegno:degna;. Ho fiducia in te, $N!",
  obj = "Parla con McGavan a Booty Bay.",
  progress = "Razza rara la tua, compare. Fammi vedere quello stemma.",
  reward = "Per i peli della schiena di Blackhoof — finalmente $Gqualcuno degno:qualcuna degna; di The Mithril Order!",
}
T[2760] = {
  title = "The Mithril Order",
  desc = "La maggior parte delle nostre reclute non arriva mai a Booty Bay, $N. Lo scintillio dello stemma basta a risvegliare la sete di tesori anche nel fabbro più integerrimo. Stolti sono, perché lo stemma non è che una goccia nel mare in confronto alle ricchezze che vedrai!$B$BTrova Galvan the Ancient e mostragli la tua spilla. Vive molto più a nord, tra Zul Gurub e il tumulo degli ogre Mosh'Ogg.",
  obj = "Parla con Galvan the Ancient a Stranglethorn Vale.",
  progress = "Salve! Avvicinati; mostra a Galvan cos'hai.",
  reward = "Ah, molti anni sono passati da quando qualcuno si è dimostrato degno di essere iniziato a The Mithril Order. Cominciamo subito!",
}
T[2761] = {
  title = "Dai la Fusione, Togli la Fusione",
  desc = "Tanti fabbri pensano che estrarre e forgiare siano due mestieri separati, che non dipendono l'uno dall'altro; ma come si fa a forgiare senza estrarre? Ah ah — è impossibile! Un fabbro provetto dev'essere anche un minatore provetto.$B$BDimostra a Galvan che sei $Gcapace:capace;, $N. Portami quaranta lingotti di ferro e quaranta di mithril. In cambio Galvan ti insegnerà i segreti degli ornate mithril pants!",
  obj = "Porta quaranta Mithril Bars e quaranta Iron Bars a Galvan the Ancient in Stranglethorn.",
  progress = "A furia di scavare ti si gonfiano i muscoli e ti fa male dappertutto!",
  reward = "Lavori con una serietà impeccabile, $N! Stai cominciando a capire i segreti della mineralogia di Galvan! Prendi questo e impara tutto quello che puoi.",
}
T[2762] = {
  title = "Il Grande Ingannatore d'Argento",
  desc = "Dicono che il truesilver sia più forte e più resistente del mithril. Galvan non contesta questo giudizio sui minerali, ma il truesilver, nonostante il nome, non è vero argento! Il mithril è un minerale molto più nobile! AH! Comunque sia, per questa lezione dovrai andare a cercare il grande ingannatore d'argento, $N.$B$BPortami quaranta lingotti di mithril e cinque di truesilver. In cambio imparerai il segreto degli ornate mithril gloves e, soprattutto, scoprirai che il truesilver è un bugiardo!",
  obj = "Porta quaranta Mithril Bars e cinque Truesilver Bars a Galvan the Ancient in Stranglethorn.",
  progress = "A furia di scavare ti si gonfiano i muscoli e ti fa male dappertutto!",
  reward = "È un'amante crudele, vero, $N? Parlo del truesilver, si capisce. Eh sì, a Galvan ci sono voluti più di dieci anni sulle montagne di Alterac per imparare questa lezione. Prendi questo e impara tutto quello che puoi!",
}
T[2763] = {
  title = "L'Arte dell'Infusione",
  desc = "Per il nostro mestiere, $N, raccogliere gemme preziose è di somma importanza. E di gemme più preziose del citrino ce ne sono poche: amplifica enormemente le proprietà magiche che infondiamo nei nostri manufatti.$B$BIn questa lezione rafforzeremo quaranta lingotti di mithril con quattro citrini: così capirai meglio la gemmologia magica e imparerai a creare gli ornate mithril shoulders.",
  obj = "Porta quaranta Mithril Bars e quattro Citrines a Galvan the Ancient in Stranglethorn.",
  progress = "A furia di scavare ti si gonfiano i muscoli e ti fa male dappertutto!",
  reward = "Si fa fatica a staccare gli occhi da tanto splendore, $N. Eh sì, il citrino è una gemma magnifica.$B$BFa' attenzione e impara quello che una scoperta del genere può insegnarci!",
}
T[2764] = {
  title = "Il Miglior Allievo di Galvan",
  desc = "Se sei $Gpronto:pronta; a finire l'addestramento con Galvan, ti conviene andare a Gadgetzan.$B$BLì c'è il mio allievo migliore, Trenton Lighthammer, che ha molto da insegnarti sull'arte del mithril decorato. Se no, resta qui e impara!$B$BOh, Gadgetzan è a Tanaris, naturalmente!",
  obj = "Parla con Trenton Lighthammer a Gadgetzan.",
  reward = "Ti manda Galvan the Ancient??$B$B<Trenton si inchina.>$B$BConoscere $Gun altro allievo:un'altra allieva; del maestro è un grande onore!",
}
T[2765] = {
  title = "Fabbro Esperto!",
  desc = "Fin dalla prima volta che sei $Gvenuto:venuta; da me sapevo che saresti $Gdiventato:diventata; $Guno:una; dei miei allievi migliori! Hai ceduto a McGavan un monile di un certo potere senza pensarci due volte, e l'hai fatto solo per poter incontrare me. Una fede così cieca e una tale devozione al mestiere meritano una ricompensa.$B$BSei $Gdiventato:diventata; $Gun esperto:un'esperta; di forgiatura, $N. Raccogline i frutti!",
  obj = "Ritira la tua ricompensa da Galvan the Ancient!",
  reward = "Per arrivare fin qui hai sacrificato un monile di potere: è più che giusto che tu ne riceva uno molto più potente. Fanne buon uso, $N.",
}
T[2766] = {
  title = "Trova OOX-22/FE!",
  desc = "Hai trovato una specie di strano congegno di metallo a forma di uovo. Giochi un po' con una delle manopole e l'uovo prende vita: si apre e si trasforma in un marchingegno robotico gnomesco, o qualcosa del genere! Dall'interno dell'uovo robotico gracchia una voce.$B$B\"Mi chiamo Oglethorpe Obnoticus e il mio robot cercatore si è schiantato! Se lo recuperi, ti ricompenserò: per favore, porta questo segnalatore al robot!\"$B$B\"Ho calcolato per te le coordinate del robot: è in una grotta vicino alla Feral Scar Vale!\"",
  obj = "Porta il segnalatore di soccorso al robot cercatore di Oglethorpe in una grotta vicino a Feral Scar Vale.",
  progress = "A quanto pare hai trovato il relitto di... un pollo robotico? Dall'uovo la voce gracchia di nuovo:$B$B\"Sì, ottimo lavoro! È proprio questo il mio robot cercatore, anche se i miei sensori dicono che gli serve una scossa per ripartire, prima di poter tornare in volo a Booty Bay a farsi riparare. Su, metti il segnalatore dentro il veicolo — al resto ci pensa il segnalatore!\"",
  reward = "Metti l'uovo... il segnalatore di soccorso... dentro il pollo... il robot cercatore.$B$BIl robot ronza e sibila dall'interno, mentre cerca a fatica di alzarsi in piedi. Quando prende vita, torni a sentire la voce di Oglethorpe, che però adesso viene da lì dentro:$B$B\"Almeno OOX-22/FE funziona, ma ha bisogno di grosse riparazioni! È troppo pesante perché tu possa portarlo... però credo di avere un'idea. Te la senti di tenerlo d'occhio ancora un po'?\"",
  en_title = "Find OOX-22/FE!",
  en_obj = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.",
}
T[2767] = {
  title = "Salva OOX-22/FE!",
  desc = "La voce dello gnomo gracchia di nuovo dal robot:$B$B\"Devo portare OOX-22/FE in un posto aperto e sicuro, dove possa cominciare una lunga procedura di decollo. Ha un sistema di occultamento integrato, ma da qui mi ci vuole tempo per rimetterlo in funzione. Scorta il robot da dove si trova fino, diciamo, al molo lungo la Forgotten Coast! Dovrebbe essere il posto perfetto, e il tragitto abbastanza lungo per far ripartire tutto!\"$B$B\"Portalo sano e salvo fino al molo, poi vieni a parlarmi a Booty Bay! Oglethorpe Obnoticus — passo e chiudo!\"",
  obj = "Scorta OOX-22/FE fino al molo lungo la Forgotten Coast, poi fai rapporto a Oglethorpe Obnoticus a Booty Bay.",
  progress = "Sì, sono io, Oglethorpe Obnoticus, maestro inventore al tuo servizio! Allora, posso aiutarti in qualcosa?",
  reward = "Oh, sei TU $Gil grande salvatore:la grande salvatrice; di OOX-22/FE! Non so nemmeno da dove cominciare a ringraziarti! La mia serie di robot cercatori va ancora sviluppata, ma recuperandolo mi hai risparmiato ore e ore di lavoro in più per ricostruirlo, e parecchie monete d'oro in costi di produzione!$B$BTi prego, scegli quello che vuoi fra questi oggetti. Grazie ancora per il generoso aiuto, $N: io e i miei robot siamo in debito con te!",
  en_title = "Rescue OOX-22/FE!",
  en_obj = "Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay.",
}
T[2768] = {
  title = "Divino-matic Rod",
  desc = "Sergeant Bly mi ha derubato! Diceva che voleva solo prenderla in prestito, e invece si è portato via la mia amata divino-matic rod!! Senza quella verga, come faccio a sapere dove scavare nuovi pozzi d'acqua??$B$BTrova Bly e riportami la verga! Ho sentito che ha portato la sua banda di avventurieri dalla dubbia fama a caccia di tesori a Zul'Farrak, a ovest. Scommetto che lo troverai lì.$B$BSperiamo che ci abbiano pensato i troll, perché se dovrai batterti con lui per la verga, ti aspetta uno scontro serio.",
  obj = "Porta la Divino-matic Rod a Chief Engineer Bilgewhizzle a Gadgetzan.",
  progress = "Hai trovato Sergeant Bly? E la mia divino-matic rod, l'hai recuperata?",
  reward = "L'hai trovata! Ben fatto, $N! Hai dovuto batterti con Bly per riaverla? Spero che tu abbia steso a dovere lui e la sua banda!",
  en_title = "Divino-matic Rod",
  en_obj = "Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.",
}
T[2769] = {
  title = "I Fratelli Brassbolts",
  desc = "Conosci i fratelli Brassbolts? Stanno nello Shimmering Flats, a Kalimdor, e gareggiano contro i goblin con la loro auto a razzo. Di solito vincono loro, e non c'è da stupirsi: l'auto goblin salta in aria così spesso che non arriva quasi mai al traguardo!$B$BEppure i fratelli Brassbolts cercano sempre nuovi modi per far andare l'auto più veloce, e Wizzle mi ha detto che per il prossimo esperimento gli serve un componente molto raro.$B$BProbabilmente gli serve una mano per procurarsi quel pezzo: va' a parlarci e scoprilo.",
  obj = "Parla con Wizzle Brassbolts nello Shimmering Flats.",
  reward = "Ah, vuoi darmi una mano? Grandioso!$B$BMi serve un pezzo per un esperimento a cui sto lavorando, e per procurarmelo ho bisogno di $Gun:una; $C $Gcoraggioso:coraggiosa; come te!",
  en_title = "The Brassbolts Brothers",
  en_obj = "Speak with Wizzle Brassbolts in the Shimmering Flats.",
}
T[2770] = {
  title = "Gahz'rilla",
  desc = "Nel profondo di Zul'Farrak, la città dei troll delle sabbie a Tanaris, c'è una pozza sacra, e da lì i troll evocano una bestia enorme! Gahz'rilla! È così feroce che persino le sue scaglie crepitano di energia, ed è proprio quell'energia che voglio sfruttare per la mia auto!$B$BPortami la scaglia elettrificata di Gahz'rilla!$B$BPerò i troll tengono ben nascosto il modo di evocare Gahz'rilla: prima di poterlo affrontare, devi strappargli il segreto.",
  obj = "Porta la Gahz'rilla's Electrified Scale a Wizzle Brassbolts nello Shimmering Flats.",
  progress = "Ce l'hai, la scaglia? Non vedo l'ora di provare modi diversi per sfruttarne l'energia!",
  reward = "Wow, hai preso la scaglia! Grazie, $N. Non vedo l'ora di mettermi al lavoro su questo coso!$B$BE allora, l'hai visto Gahz'rilla? Era grande come dicono??",
  en_title = "Gahz'rilla",
  en_obj = "Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.",
}
T[2771] = {
  title = "La Testa sulle Spalle",
  desc = "A quanto pare il maestro l'aveva in mente fin dall'inizio. A me non hanno insegnato a creare gli oggetti che sai fare tu, e a te quelli che so fare io.$B$BIl maestro è saggio, $N. Ci insegneremo a vicenda!$B$BInsegnami a fare un mithril coif e degli ornate mithril shoulders, e io ti mostrerò come si crea un ornate mithril helm.",
  obj = "Porta due Mithril Coifs e un Ornate Mithril Shoulder a Trenton Lighthammer.",
  progress = "Allora, $N, hai finito di forgiare gli oggetti?",
  reward = "Eccellente! Modestia a parte, è uno scambio equo. Guarda e impara, $N!",
}
T[2772] = {
  title = "Il Mondo ai Tuoi Piedi",
  desc = "L'anno scorso, al Campionato di Forgiatura di Tutta la Valle, tutti i presenti hanno visto un vigliacco della Venture Co. Foundry falciarmi la gamba. Nessuno però sapeva come ho fatto ad andare avanti e alla fine a vincere il torneo: proprio così, con gli ornate mithril boots!$B$BQuest'anno, però, al torneo c'è anche un trituratore della Venture Co., quindi dovrò imparare a forgiare gli ornate mithril pants! Insegnami la via dei pantaloni e impara la via dello stivale!",
  obj = "Porta due paia di Heavy Mithril Boots e un paio di Ornate Mithril Pants a Trenton Lighthammer.",
  progress = "Allora, $N, hai finito di forgiare gli oggetti?",
  reward = "Avrai il mondo ai tuoi piedi, $N! Vengano pure tutti a colpirti le gambe, tanto ora sei infalciabile!",
}
T[2773] = {
  title = "Il Ragazzo del Mithril",
  desc = "Da queste parti mi conoscono come il Ragazzo del Mithril, quello che fornisce mithril decorato agli avventurieri di tutto il mondo.$B$B<Trenton sussurra.>$B$BMa non sanno che non conosco la tecnica per forgiare gli ornate mithril gloves. Shhhh! Che resti il nostro piccolo segreto.$B$BTu insegnami a creare gli ornate mithril gloves, $N, e io in cambio ti mostrerò il pezzo che ha coronato il mio addestramento alla scuola di Galvan: l'ornate mithril breastplate.",
  obj = "Porta due Heavy Mithril Breastplates e un paio di Ornate Mithril Gloves a Trenton Lighthammer.",
  progress = "Allora, $N, hai finito di forgiare gli oggetti?",
  reward = "Grazie di tutto quello che mi hai insegnato, $N. Presto il signore e padrone del completo di mithril decorato sarà tuo.$B$BAmmira!",
}
T[2781] = {
  title = "RICERCATO: Caliph Scorpidsting",
  desc = "RICERCATO: Caliph Scorpidsting!$B$BLa Gadgetzan Water Company di Gadgetzan, Tanaris, pagherà una lauta taglia per la testa di Caliph Scorpidsting, capo dei fuorilegge Wastewander, che si è macchiato, fra l'altro, di questi crimini:$B$B1. Ha assassinato dipendenti della Gadgetzan Water Co.!$B2. Ha rubato risorse della Gadgetzan Water Co.!$B3. Ha sequestrato proprietà della Gadgetzan Water Co.!$B$BPorta a Chief Engineer Bilgewhizzle la prova che Caliph Scorpidsting è morto, e riceverai subito la ricompensa!",
  obj = "Porta la testa di Caliph Scorpidsting a Chief Engineer Bilgewhizzle a Gadgetzan.",
  progress = "Sì, $C, sono un funzionario della Gadgetzan Water Company. Cosa posso fare per te?",
  reward = "Finalmente — giustizia è fatta! A quegli spregevoli nomadi hai assestato un colpo poderoso! Con la morte di Scorpidsting potremmo riuscire a cacciare una volta per tutte quegli abusivi dai pozzi di Gadgetzan!$B$BPer l'autorità che mi conferisce la Gadgetzan Water Company, ti consegno con piacere questa taglia: hai reso un grande servizio a tutti noi.",
}
T[2782] = {
  title = "Rin'ji's Secret",
  desc = "La tavoletta è coperta di segni di Witherbark troll. Il segreto di Rin'ji è proprio un mistero...$B$BForse tra le mani hai qualcosa di molto prezioso. Ma potrebbe anche essere l'esatto contrario: un Witherbark troll in difficoltà farebbe probabilmente di tutto per tirarsi fuori dai guai...",
  obj = "Oran Snakewrithe, una nota studiosa dei Witherbark trolls, potrebbe riuscire a decifrare la tavoletta. Si sa che risiede a Magic Quarter of the Undercity.",
  progress = "Bene, bene, e questo che cos'è?",
  reward = "Questa tavoletta... Davvero insolita... Dove l'hai trovata, $N?",
}
T[2783] = {
  title = "Meschini Litigi",
  desc = "Stiamo combattendo il nemico sbagliato, $N.$B$BMentre noi litighiamo con gli orchi per un po' di terra bruciata, il vero potere di queste terre continua a crescere, in forza e in numero.$B$BDobbiamo restare qui a combattere l'Orda per farci poi sbaragliare, un giorno, dagli eserciti della Burning Legion? Non serve a niente.$B$BMetti da parte le divergenze, $N, e parla con il fallen hero dell'Orda. Lui conosce la verità sulle Blasted Lands.",
  obj = "Parla con il Fallen Hero of the Horde al confine tra le Blasted Lands e la palude.",
  reward = "L'Alleanza vuole aiutarci?$B$BNon credevo che avrei mai rivisto un giorno come questo, con l'Alleanza che combatte fianco a fianco con l'Orda contro un nemico comune.$B$BCosì sia... ci uniremo.",
}
T[2784] = {
  title = "Caduta in Disgrazia",
  desc = "Ascolta la mia storia, $R.",
  obj = "Ascolta il Fallen Hero of the Horde raccontare la sua storia.",
  progress = "Ascolta quello che ho da dire.",
  reward = "Da spirito sono impotente, $N. Aiutami. Lascia che riconquisti il mio onore.",
}
T[2801] = {
  title = "Una Storia di Dolore",
  desc = "Prima di andare avanti, devi ascoltare la mia storia.",
  obj = "Ascolta il Fallen Hero of the Horde raccontare la sua storia.",
  progress = "Ascolta quello che ho da dirti, $N.",
  reward = "Ora è tempo di agire, $N.",
}
T[2821] = {
  title = "Il Marchio di Qualità",
  desc = "Sulla lavorazione del cuoio la mia filosofia è questa: il lavoro dev'essere della migliore qualità possibile — niente compromessi. Chi ti dice che la qualità non conta sta cercando di venderti una villa sul mare a Dun Morogh!$B$BDi recente, mentre cercavo materiali di alta qualità, mi sono imbattuto nelle thick yeti hides. Gli yeti vivono a Feralas, e molti stanno nella Feral Scar Vale. Ne voglio un po': portamene una pila da dieci e ti lascerò scegliere uno dei miei articoli di cuoio. Se ti sembra giusto, affare fatto.",
  obj = "Porta 10 Thick Yeti Hides a Pratt McGrubben in Feathermoon Stronghold.",
  progress = "Con una pila di dieci thick yeti hides ti guadagni uno degli oggetti che creo, a tua scelta. E siccome alla qualità ci tengo, ti garantisco che sarà un buon pezzo!$B$BSe non trovi gli yeti, so io dove potresti cercarli: prova nell'entroterra, poco lontano dalla Forgotten Coast, intorno alla Feral Scar Vale.",
  reward = "Ti sei $Gfermato:fermata; a guardare bene la consistenza di queste pelli? Se trattate a dovere, potrebbero benissimo essere più resistenti del ferro. Le conoscono in pochi, e con tutte le soluzioni di concia che so preparare potrei riuscire a creare oggetti con un vero marchio di qualità... grazie a te, naturalmente!$B$BE ora scegli pure fra quello che posso offrirti per il tuo servizio!",
}
T[2822] = {
  title = "Il Marchio della Qualità",
  desc = "Vado fiero del mio lavoro con il cuoio, e credo che si veda; sulla qualità non si transige mai. Chi ti dice che la qualità non conta vorrebbe farti credere anche che la terra non custodisca segreti!$B$BL'ultima volta che sono andato in cerca di materiali di alta qualità ho scoperto le thick yeti hides. Gli yeti sono originari di Feralas e di solito stanno a ovest di qui, nella Feral Scar Vale. Portami una pila di dieci pelli e potrai scegliere uno dei miei articoli di cuoio. Se ti sta bene, siamo d'accordo!",
  obj = "Porta 10 Thick Yeti Hides a Jangdor Swiftstrider a Camp Mojache.",
  progress = "Sei $Griuscito:riuscita; a procurarti una pila di dieci thick yeti hides? I miei articoli di cuoio non sono secondi a nessuno, e se avrai le pelli te ne darò qualcuno.$B$BSe gli yeti non li trovi, so dove potrebbe essercene qualcuno. Prova a cercare a ovest di qui, poco nell'entroterra della Forgotten Coast, intorno alla Feral Scar Vale.",
  reward = "Ah, eccellente! Con un trattamento speciale queste pelli diventano resistenti come il ferro, te lo dico io! Ci vorranno molti tentativi prima di trovare la miscela giusta per conciarle, ma sono sicuro che porteranno il mio marchio di qualità più in alto.$B$BQuanto a te, $N... il tuo aiuto per me è stato prezioso. Scegli pure fra questi oggetti che ho realizzato.",
}
T[2841] = {
  title = "Guerre degli Impianti",
  desc = "La tecnologia degli gnomi — due anni fa era poco più di una barzelletta. I tempi sono proprio cambiati. Adesso hanno costruito un impianto nuovo che batte tutti i nostri modelli di trituratore messi insieme. Mi servono i progetti, $N!$B$BPeccato che siano chiusi in una cassaforte vicino a Mekgineer Thermaplugg. E come se non bastasse, la combinazione la conosce solo Mekgineer Thermaplugg.$B$BFa' tutto quello che serve per avere quella combinazione, $N, poi apri la cassaforte e riportami i progetti!",
  obj = "Recupera i Rig Blueprints e la Thermaplugg's Safe Combination a Gnomeregan e portali a Nogg a Orgrimmar.",
  progress = "Di progetti non ne vedo. Te li sei nascosti addosso da qualche parte o te ne stai qui $Gimpalato:impalata; solo per darmi fastidio?",
  reward = "Lo sapevo che ce l'avresti fatta, $N! Sovik invece aveva i suoi dubbi.$B$B<Nogg si schiarisce la voce.>$B$BCon i progetti in mano, è solo questione di tempo: scopriremo tutte le innovazioni gnomesche usate per costruire l'impianto e le trasformeremo in innovazioni goblin per i nostri nuovi modelli di trituratore.",
  en_title = "Rig Wars",
  en_obj = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.$B",
}
T[2842] = {
  title = "Capo Ingegnere Scooty",
  desc = "Appena Kernobee ci ha parlato del nuovo marchingegno gnomesco, io e Scooty ci siamo messi al lavoro sul Traspoliportatore 6000: il modo più veloce e affidabile per arrivare a Gnomeregan.$B$BOra finalmente è pronto per i passeggeri, $N. Se vuoi provarlo, vai a Booty Bay e parla con Scooty al posatoio del wind rider. A Booty Bay ci arrivi con la nave da Ratchet.$B$BCerto, puoi sempre provare a raggiungere Gnomeregan attraverso le montagne di Dun Morogh, infestate dai nani!",
  obj = "Parla con Scooty a Booty Bay.",
  reward = "È una bellezza, eh? Il meglio della tecnologia dei trasporti goblin — ed è esplosa solo una dozzina di volte, più o meno.$B$BNon preoccuparti, $N, l'ho sistemata come si deve. Non ti esploderà addosso — e se succede, sarà una cosa rapida e indolore.",
  en_title = "Chief Engineer Scooty",
  en_obj = "Speak with Scooty in Booty Bay.",
}
T[2843] = {
  title = "Gnomer-viaaaaa!",
  desc = "Finché hai il segnalatore con te, ti basta salire sulla piattaforma per essere $Gteletrasportato:teletrasportata; a Gnomeregan.$B$BPotrebbe esserci qualche strano effetto collaterale, ma non dovrebbe essere niente di permanente... non più.$B$BQuasi mi dimenticavo la cosa più importante — come tornare. Quando sarai $Gpronto:pronta; per il ritorno, sali sulla piattaforma del traspoliportatore a Gnomeregan!$B$BAdesso devo tarare il segnalatore sulla tua taglia e sul tuo peso.",
  obj = "Aspetta che Scooty tari il Goblin Transponder.",
  progress = "È pronto!",
  reward = "Ecco fatto! Quando sei $Gpronto:pronta;, sali sulla piattaforma.",
  en_title = "Gnomer-gooooone!",
  en_obj = "Wait for Scooty to calibrate the Goblin Transponder.",
}
T[2844] = {
  title = "Il Gigante Guardiano",
  desc = "Sono un buono a nulla, $N. Dovevo badare alla mia piccola amica Shay e chissà come m'è scappata. Davvero, non ho mica capito bene cos'è successo: l'ultima volta che l'ho vista camminavamo fra le rovine, qua a nord.$B$BFilava tutto liscio, poi mi sono girato e... non c'era più.$B$BAdesso non so proprio cosa fare. Tu hai qualche idea, $N? Sono preoccupato da morire.$B$BEhi, e se andassi tu a cercare Shay? Le tue gambe sono molto più svelte delle mie.",
  obj = "Trova la ragazzina elfa della notte che si è persa.",
  reward = "Oh, sono così contenta che tu mi abbia trovata! Lo devo ammettere, mi sono un po' persa... Ma questo posto non è bellissimo?",
}
T[2845] = {
  title = "Shay la Girovaga",
  desc = "Credi di riuscire ad aiutarmi a ritrovare la strada per tornare dal mio amico Rockbiter? Doveva badare a me... Però è vero, ogni tanto tendo ad allontanarmi: ci sono così tante cose da vedere che mi distraggo di continuo.$B$BUna cosa però riesce sempre ad attirare la mia attenzione.$B$BIn questo forziere troverai una campana a cui tengo moltissimo. Ne adoro il suono. Ti do la mia parola: se mi allontano, ti basta suonarla e io torno di corsa.",
  obj = "Prendi la Shay's Bell dal forziere.$B$BScorta Shay Leafrunner fino all'accampamento di Rockbiter.",
  progress = "Cominciavo a stare in pensiero per te! Grazie mille di aver riportato a casa Shay, $N.",
  reward = "Cosa? 'Sta campana funziona quando Shay scappa via, dici? Ma guarda un po'!$B$BHai fatto tanto per me, $N, quindi ecco qua.",
}
T[2846] = {
  title = "Tiara of the Deep",
  desc = "Tanto tempo fa avevo un gioiello bellissimo, la Tiara of the Deep. E non era soltanto graziosa — chi sapeva usarla ci trovava dentro un grande potere.$B$BPer questo l'Hydromancer Velratha, appena ha saputo della tiara, ha voluto averla a ogni costo. Ha mandato degli agenti a casa mia, e me l'hanno rubata mentre non c'ero. Che ladri!$B$BRivoglio la mia tiara! Va' a Zul'Farrak, la città dei troll in Tanaris, trova Velratha e strappagliela. Riportamela e ti guadagnerai il mio favore.",
  obj = "Porta la Tiara of the Deep a Tabetha in Dustwallow Marsh.",
  progress = "Ce l'hai, la tiara, $N? Velratha ha capito quanto costa mettersi contro di me?",
  reward = "Magnifico! L'hai trovata! E, cosa non meno importante — Velratha non ce l'ha più! Grazie, $N. Ti sarò debitrice per sempre!$B$BE se prima ti sono sembrata un po'... cattiva, non farci caso. Con chi non mi ha derubata sono una persona molto più gentile, vedrai.",
  en_title = "Tiara of the Deep",
  en_obj = "Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.",
}
T[2847] = {
  title = "Leather Armor Selvatico",
  desc = "$N, stai diventando $Gun conciatore:una conciatrice; davvero abile! E io conosco degli schemi che potrebbero interessarti... quelli dell'armatura di Cuoio Selvatico! Il Cuoio Selvatico sfrutta le proprietà potenti e caotiche delle wildvines, che si trovano dove la vegetazione è rigogliosa e addosso ad alcune delle creature che ci vivono. L'armatura che ne viene fuori, per chi ha la tua abilità, non ha rivali: garantito.$B$BTi insegnerò a farla, ma per un po' dovrai lavorare per me. Per cominciare mi bastano dieci pezzi di thick leather; dei dettagli parliamo dopo.",
  obj = "Porta 10 pezzi di Thick Leather a Pratt McGrubben in Feathermoon Stronghold.",
  progress = "Te l'ho detto: mentre impari a creare l'armatura di Cuoio Selvatico, lavori per me. Le wildvines sono potenti e caotiche, perciò danno all'armatura che creerai, già robusta di suo, un beneficio casuale ma forte. Queste conoscenze, però, mi sono costate fatica.$B$BPer cominciare mi servono dieci pezzi di thick leather.$B$BFatto questo, passeremo al lavoro che ti tocca per avere gli schemi.",
  reward = "Bene, $N, sono contento di averti con me. Da $Gconciatore:conciatrice; hai fatto una scelta intelligente: quando saprai creare anche un solo pezzo dell'armatura di Cuoio Selvatico, chi indossa armature di cuoio farà la fila da te.$B$BMettiamoci al lavoro — da dove vuoi cominciare?",
  en_title = "Wild Leather Armor",
  en_obj = "Bring 10 Thick Leather to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2848] = {
  title = "Wild Leather Shoulders",
  desc = "I Wild Leather shoulders sostengono benissimo il corpo di chi li indossa e danno una protezione di prim'ordine alle spalle e alla parte alta delle braccia. Come in tutte le armature di Cuoio Selvatico, la wildvine cucita all'interno dà all'oggetto un beneficio potente ma casuale.$B$BPer questo schema mi servono sei thick armor kits e una wildvine: per te non dovrebbe essere troppo difficile.",
  obj = "Porta 6 Thick Armor Kits e una Wildvine a Pratt McGrubben in Feathermoon Stronghold.",
  progress = "Ce li hai i sei thick armor kits e la wildvine che ti ho chiesto?$B$BNon credere che fare potenziamenti d'armatura sia un lavoro monotono: se ci lavori con costanza, ti fai un metodo che affina le tue abilità per il lavoro minuzioso che serve all'armatura di Cuoio Selvatico.$B$BVedi — c'è un vero motivo se mi prepari queste cose...",
  reward = "Questi potenziamenti d'armatura sono di buona qualità, $N. E la qualità è proprio quello che pretendo, non solo dal mio lavoro ma anche da chi lavora per me.$B$BHai lavorato bene e questo schema te lo sei $Gguadagnato:guadagnata;: spero che ti renda quanto ha reso a me.",
  en_title = "Wild Leather Shoulders",
  en_obj = "Bring 6 Thick Armor Kits and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2849] = {
  title = "Wild Leather Vest",
  desc = "Le Wild Leather vests sono il pezzo base di ogni completo di armatura di Cuoio Selvatico. Nella veste la struttura si fonde con la wildvine, e ne viene fuori un capo che dà al busto la massima protezione ma lascia comunque che la potente magia si faccia strada attraverso l'indumento.$B$BPer questo schema mi servono due pettorali corazzati di Turtle Scale, due paia di guanti di Turtle Scale e una wildvine. È una richiesta impegnativa, ma non dovresti faticare troppo a soddisfarla.",
  obj = "Porta 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves e una Wildvine a Pratt McGrubben in Feathermoon Stronghold.",
  progress = "Ce li hai i due pettorali corazzati e i guanti di Turtle Scale che ho ordinato? E non scordarti la wildvine!$B$BFin dai primi schemi si impara che le basi della forma valgono anche per i capi più difficili. Anche se si tratta di oggetti diversi, la forma dei pettorali corazzati di Turtle Scale ti prepara alla cura dei dettagli che ci vuole per creare una Wild Leather vest.$B$BE i guanti... beh, quelli li tengo io. Ricordati che lavori per me!",
  reward = "Sono davvero dei bei pezzi, $N. Basterebbero la maestria e la cura con cui sono fatti per farli valere parecchie monete d'argento più di un pezzo qualunque.$B$BHai evaso il mio ordine e ora ti spetta la ricompensa: adesso sai creare le Wild Leather vests!",
  en_title = "Wild Leather Vest",
  en_obj = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2850] = {
  title = "Wild Leather Helmet",
  desc = "Un Wild Leather helmet dà a chi lo indossa una protezione superiore delle parti vitali della testa, e la comodità non ci rimette. Come in tutte le armature di Cuoio Selvatico, la wildvine integrata dà alla struttura dell'elmo un miglioramento potente ma casuale. Chi indossa il cuoio lo vorrà di sicuro!$B$BPer questo schema mi servono due Nightscape tunics, due Nightscape headbands e una wildvine. Completa l'ordine e lo schema è tuo!",
  obj = "Porta 2 Nightscape Tunics, 2 Nightscape Headbands e una Wildvine a Pratt McGrubben in Feathermoon Stronghold.",
  progress = "Prima di insegnarti a creare i Wild Leather helmets mi servono quelle giubbe, quelle bande e anche quel pezzo di wildvine.$B$BFra gli avventurieri l'equipaggiamento per la testa è molto ambito, che sia una banda di una semplicità disarmante o un elmo che copre tutto. Qualunque aspetto abbia, per fare un buon copricapo le basi restano le stesse.",
  reward = "L'equipaggiamento di Nightscape che mi hai portato va benissimo per l'ordine, $N. Da $Gun conciatore:una conciatrice; del tuo calibro non mi aspetto niente di meno.$B$BQuesto schema te lo sei $Gguadagnato:guadagnata; davvero. Te lo do volentieri, e spero che ne trarrai il giusto profitto.",
  en_title = "Wild Leather Helmet",
  en_obj = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2851] = {
  title = "Wild Leather Boots",
  desc = "Ormai hai imparato parecchio, $N, ma c'è ancora altro da imparare. Adesso tocca ai Wild Leather boots, la pietra angolare di ogni completo.$B$BSono stivali fatti per avvolgere comodamente il piede e proteggerlo dai pericoli dell'avventura, e le suole morbide sono una benedizione per chi vuole muoversi in silenzio anche con le scarpe ai piedi.$B$BPer avere il modello dovrai evadere un ordine di due Nightscape pants e due Nightscape boots. E mi serviranno anche due wildvines... non uno solo. Quando hai tutto, fammelo sapere.",
  obj = "Porta 2 Nightscape Pants, 2 Nightscape Boots e 2 Wildvines a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Prima di avere il modello devi evadere l'ordine di pantaloni, stivali e wildvines, $N. Hai finito?$B$BGià dal primo paio di stivali che impariamo a fare, cominciamo a capire che uno stivale di qualità deve trovare un sottile equilibrio fra comodità e funzionalità. Se uniamo le due cose, riusciamo a creare oggetti che fanno ignorare a chi li indossa una fatica che stroncherebbe chiunque portasse articoli di qualità inferiore.",
  reward = "Ancora una volta hai evaso un ordine complesso con l'abilità di $Gun professionista esperto:una professionista esperta;. Ti sei $Gguadagnato:guadagnata; questo modello, e anche la mia gratitudine.",
  en_title = "Wild Leather Boots",
  en_obj = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2852] = {
  title = "Wild Leather Leggings",
  desc = "Adesso che hai le basi, $N, sei $Gpronto:pronta; a padroneggiare lavori più complessi. Le Wild Leather leggings sono fra le protezioni di cuoio più robuste e potenti che si trovino in giro. Vita, cosce, polpacci e organi vitali — tutto ha una protezione enorme. E con il potenziamento in più della wildvine, gli avventurieri che le avranno ti ringrazieranno ogni volta che ti vedono.$B$BPer avere il modello dovrai evadere un ordine di due elmi di Turtle Scale, due bracciali di Turtle Scale e due wildvines.",
  obj = "Porta 2 Turtle Scale Helms, 2 Turtle Scale Bracers e 2 Wildvines a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Hai pronti i bracciali e gli elmi di Turtle Scale? E non dimenticare i due wildvines che mi servono!$B$BOrmai cominci a capire quante potenzialità si nascondono nelle armature di Cuoio Selvatico. Per un conciatore, un'armatura che si può impiegare senza limiti ha un valore quasi inestimabile. L'unico limite è quante risorse hai per realizzare gli oggetti — non la qualità dei prodotti finiti!",
  reward = "Ancora una volta, un ordine evaso senza difetti. Magari un giorno sarò io a venire da TE per farmi insegnare qualcosa, eh, $N?$B$BEcco il modello per le gambiere, e con lui la mia gratitudine. Fa' tuo questo sapere e metti le tue notevoli abilità in tutto quello che realizzerai!",
  en_title = "Wild Leather Leggings",
  en_obj = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2853] = {
  title = "$GMaestro:Maestra; del Cuoio Selvatico",
  desc = "Beh, $N, sei la diligenza fatta persona. Delle armature di Cuoio Selvatico ti resta un solo modello: tutti gli altri li hai già padroneggiati. E non ti farò faticare inutilmente per averlo. Te lo sei $Gguadagnato:guadagnata; pienamente, e anche di più... solo che non posso dartelo io. Deve essere il mio maestro a ricompensarti, colui che mi ha introdotto al mestiere.$B$BPorta questa lettera a Telonis, che insegna conciatura a Darnassus. Fagliela vedere e lascia che ti riconosca come suo pari, come faccio io.",
  obj = "Consegna la Pratt's Letter a Telonis, il maestro conciatore di Darnassus.",
  progress = "Salute, $R... vedo dal tuo aspetto che sei $Gun conciatore:una conciatrice; come me. Sei $Gvenuto:venuta; ad attingere alle mie abilità, o forse ti portano da me altri affari?",
  reward = "Ah sì, ti manda Pratt. Benché sia un umano, a volte mi ricorda noi elfi della notte. La sua dedizione e il suo talento con il cuoio sono notevoli, e che in questa lettera ti lodi così è un segno di rispetto che riconosco.$B$BSo che ti ha insegnato l'arte del Cuoio Selvatico. Permettimi di completare il tuo addestramento con questo modello, e usalo bene: pochi al mondo conoscono i segreti dei Wild Leather cloaks.",
  en_title = "Master of the Wild Leather",
  en_obj = "Give Pratt's Letter to Telonis, the master leatherworker of Darnassus.",
}
T[2854] = {
  title = "Leather Armor Selvatico",
  desc = "$N, la tua abilità di $Gconciatore:conciatrice; ti precede. Ho conoscenze di conciatura che faresti bene ad apprendere... l'armatura di Cuoio Selvatico! Il Cuoio Selvatico attinge alle proprietà potenti e caotiche delle wildvines, che si trovano dove la vegetazione è rigogliosa e anche su alcune delle creature che ci vivono. Per $Gun artigiano:un'artigiana; della tua abilità, un'armatura fatta con questo materiale non ha rivali, garantito.$B$BTi insegnerò, ma per un po' lavorerai per me. Per cominciare ti chiedo solo dieci pezzi di thick leather. Dei dettagli parleremo dopo.",
  obj = "Porta 10 pezzi di Thick Leather a Jangdor Swiftstrider a Camp Mojache.",
  progress = "Mettiamo le cose in chiaro; mentre impari l'arte dell'armatura di Cuoio Selvatico, sarai $Gmio:mia; apprendista. Le wildvines sono potenti e caotiche insieme, e per questo danno all'armatura che realizzerai, già robusta di suo, un beneficio casuale ma forte. Queste conoscenze, però, non le ho acquisite facilmente.$B$BPer avviarti su questa strada, il primo prezzo è di dieci pezzi di thick leather.$B$BPoi passeremo al lavoro che dovrai svolgere per ottenere gli schemi.",
  reward = "Bene, $N, sono felice di averti con me come $Gmio:mia; apprendista. Come $Gconciatore:conciatrice; hai preso una decisione saggia; quando avrai imparato a padroneggiare l'arte del Cuoio Selvatico, chi porta armature di cuoio ti reclamerà a gran voce.$B$BMettiamoci al lavoro — da dove vuoi cominciare?",
  en_title = "Wild Leather Armor",
  en_obj = "Bring 10 Thick Leather to Jangdor Swiftstrider in Camp Mojache.",
}
T[2855] = {
  title = "Wild Leather Shoulders",
  desc = "I Wild Leather shoulders sostengono molto bene la corporatura di chi li indossa, e proteggono meglio di altri non solo le spalle, ma anche la parte alta delle braccia. Come in tutte le armature di Cuoio Selvatico, mentre si cuce la wildvine nell'oggetto si infonde un potenziamento casuale ma molto potente.$B$BPer questo schema mi servono sei thick armor kits e una wildvine. Per te non dovrebbe essere una richiesta troppo difficile.",
  obj = "Porta 6 Thick Armor Kits e una Wildvine a Jangdor Swiftstrider a Camp Mojache.",
  progress = "Hai i sei thick armor kits e la wildvine che ti ho chiesto?$B$BConsidera la realizzazione dei potenziamenti d'armatura una lezione di lavoro costante e affidabile; il metodo regolare che sviluppi esercitando il mestiere su di loro ti aiuta ad affinare le abilità che servono per la lavorazione minuziosa delle armature di Cuoio Selvatico.$B$BOgni lezione ha uno scopo, $N. Bisogna accoglierle una per una, come meritano.",
  reward = "Questi potenziamenti d'armatura sono di qualità solida, $N. Se c'è una cosa che pretendo dal mio lavoro, e anche da quello di chi istruisco, è la qualità.$B$BHai lavorato bene e ti sei $Gguadagnato:guadagnata; questo schema; spero che ripaghi te come ha ripagato me.",
  en_title = "Wild Leather Shoulders",
  en_obj = "Bring 6 Thick Armor Kits and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
}
T[2856] = {
  title = "Wild Leather Vest",
  desc = "Le Wild Leather vests sono il pezzo fondamentale di ogni set di armatura di Cuoio Selvatico. Con la sua struttura e la wildvine intrecciata dentro, la veste protegge al massimo il torso e lascia che una magia potente si faccia strada attraverso l'indumento.$B$BPer questo schema mi servono due pettorali corazzati di Turtle Scale, due paia di guanti di Turtle Scale e una wildvine. Non è una lezione facile, ma l'abilità per completarla ce l'hai di sicuro.",
  obj = "Porta 2 Turtle Scale Breastplates, 2 paia di Turtle Scale Gloves e una Wildvine a Jangdor Swiftstrider a Camp Mojache.",
  progress = "Hai i due pettorali corazzati e i guanti di Turtle Scale? E non dimenticare la wildvine!$B$BGià con i primi schemi impariamo che i fondamenti della forma valgono bene anche per indumenti più difficili. I pettorali corazzati di Turtle Scale sono un altro oggetto, ma la loro forma ti prepara ai dettagli che servono per realizzare una Wild Leather vest.$B$BA mano a mano che vai avanti con le lezioni, le abilità che ti insegno diventeranno arte.",
  reward = "Questi pezzi sono davvero belli, $N. L'abilità e la cura con cui li hai realizzati dimostrano che hai scelto di dedicarti completamente a questi compiti.$B$BHai soddisfatto le mie richieste, ed ecco la tua ricompensa. La conoscenza per realizzare le Wild Leather vests ora è tua!",
  en_title = "Wild Leather Vest",
  en_obj = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
}
T[2857] = {
  title = "Wild Leather Helmet",
  desc = "Un Wild Leather helmet dà a chi lo indossa una protezione superiore delle zone vitali della testa, senza sacrificare la comodità. Come in tutte le armature di Cuoio Selvatico, la wildvine che ha dentro conferisce alla struttura dell'elmo un potenziamento magico potente ma casuale. Chi porta il cuoio vorrà di sicuro questo pezzo!$B$BPer questo schema mi servono due Nightscape tunics, 2 Nightscape headbands e una wildvine. Completa questa lezione e lo schema sarà tuo!",
  obj = "Porta 2 Nightscape Tunics, 2 Nightscape Headbands e una Wildvine a Jangdor Swiftstrider a Camp Mojache.",
  progress = "Prima di insegnarti a realizzare i Wild Leather helmets, ho bisogno che tu mi faccia quelle giubbe e quelle bande; e poi mi serve quel pezzo di wildvine.$B$BFra gli avventurieri i copricapi sono molto ambiti, che si tratti di una banda di una semplicità disarmante o di un elmo che copre tutta la testa. Qualunque aspetto abbiano, i fondamenti per crearne di valore restano gli stessi.",
  reward = "Questo equipaggiamento di Nightscape che mi hai portato risponde perfettamente ai requisiti che ti ho indicato, $N. Da $Gun conciatore:una conciatrice; del tuo calibro non mi aspetto niente di meno.$B$BTi sei $Gguadagnato:guadagnata; l'onore di realizzare i Wild Leather helmets. Ti cedo volentieri questo schema, e spero che saprai trarne il profitto che merita.",
  en_title = "Wild Leather Helmet",
  en_obj = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
}
T[2858] = {
  title = "Wild Leather Boots",
  desc = "Conosci sempre meglio l'armatura di Cuoio Selvatico, $N, ma hai ancora da imparare.$B$BI Wild Leather boots sono la pietra angolare di ogni completo. Stivali come questi sono fatti per tenere il piede comodo e insieme per proteggerlo dai pericoli dell'avventura, e le suole morbide sono una benedizione per chi vuole muoversi in silenzio.$B$BPer questo schema devi creare due paia di Nightscape pants e due paia di Nightscape boots, e mi servono anche due wildvines... non una sola. Quando avrai tutto, andremo avanti.",
  obj = "Porta 2 Nightscape Pants, 2 Nightscape Boots e 2 Wildvines a Jangdor Swiftstrider a Camp Mojache.",
  progress = "Per imparare lo schema devi prima consegnarmi i pantaloni, gli stivali e le wildvines, $N. Hai fatto quello che ti ho chiesto?$B$BGià dal primo paio di stivali che impariamo a fare, cominciamo a capire che uno stivale di qualità deve stare in perfetto equilibrio fra comodità e funzionalità. Con l'una e l'altra riusciamo a creare oggetti che permettono a chi li indossa di ignorare una stanchezza che stroncherebbe chi porta merce peggiore.",
  reward = "Ancora una volta hai creato oggetti con l'abilità di $Gun professionista esperto:una professionista esperta;. Ti sei $Gguadagnato:guadagnata; questo schema, insieme alle mie congratulazioni.",
  en_title = "Wild Leather Boots",
  en_obj = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.",
}
T[2859] = {
  title = "Wild Leather Leggings",
  desc = "Sei $Gpronto:pronta; per lezioni più complesse, $N. Le Wild Leather leggings sono fra i pezzi di cuoio più robusti e potenti in circolazione. Vita, cosce, polpacci e organi vitali — tutto riceve una protezione enorme. E con il potenziamento della wildvine in più, gli avventurieri che le hanno ti ringrazieranno ogni volta che ti vedranno.$B$BPer avere questo schema mi servono due elmi di Turtle Scale, due bracciali di Turtle Scale e due wildvines.",
  obj = "Porta 2 Turtle Scale Helms, 2 Turtle Scale Bracers e 2 Wildvines a Jangdor Swiftstrider a Camp Mojache.",
  progress = "Sono pronti i bracciali e gli elmi di Turtle Scale? E non dimenticare le due wildvines che mi servono.$B$BOrmai cominci a capire il potere che si nasconde nell'armatura di Cuoio Selvatico. Per un conciatore, un'armatura che si può impiegare senza limiti è quasi inestimabile. Gli unici limiti stanno nella quantità dei materiali per fare gli oggetti — non nella qualità dei prodotti finiti!",
  reward = "Ancora una volta hai portato a termine il mio compito senza un errore. Forse un giorno sarò io a venire da TE in cerca di sapere, eh, $N?$B$BEcco lo schema per le gambiere, con i miei ringraziamenti. Fai tuo questo sapere, e fa' che i tuoi prodotti finiti mettano a frutto le tue notevoli abilità!",
  en_title = "Wild Leather Leggings",
  en_obj = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.",
}
T[2860] = {
  title = "$GMaestro:Maestra; del Cuoio Selvatico",
  desc = "$N, ti ho insegnato tutto quello che potevo. Resta però un ultimo schema per l'armatura di Cuoio Selvatico. Non ti farò faticare inutilmente per averlo: te lo sei $Gguadagnato:guadagnata; in pieno, e anche di più. Solo che non posso dartelo liberamente.$B$BDeve essere la mia maestra, colei che mi ha avviato al mestiere, a ricompensarti. Porta questo biglietto a Una, che insegna la conciatura a Thunder Bluff. Mostrale la lettera e lascia che ti riconosca come $Gun suo pari:una sua pari;, come faccio io.",
  obj = "Consegna la Jangdor's Letter a Una, la maestra conciatrice di Thunder Bluff.",
  progress = "Salute, $R... dal tuo aspetto capisco che sei $Gun conciatore:una conciatrice; come me. Sei $Gvenuto:venuta; ad attingere alle mie abilità, o forse hai altre faccende da sbrigare con me?",
  reward = "Ah, sì, ti manda Jangdor. Mi fa piacere vedere che uno dei miei allievi migliori ora ha $Gun allievo tutto suo:un'allieva tutta sua;.$B$BCon il cuoio ha una dedizione e un talento notevoli, e se in questa lettera ti loda così, è un segno di rispetto che riconosco.$B$BSo che ti ha insegnato l'arte del Cuoio Selvatico: permettimi di completare il tuo addestramento con questo schema. Fanne buon uso; in pochi al mondo conoscono i segreti dei Wild Leather cloaks.",
  en_title = "Master of the Wild Leather",
  en_obj = "Give Jangdor's Letter to Una, the master leatherworker of Thunder Bluff.",
}
T[2861] = {
  title = "Il Compito di Tabetha",
  desc = "Si dice che Tabetha, una maga nostra collega che vive nel cuore della Dustwallow Marsh, abbia un osso da rompere a un certo troll delle sabbie di Zul'Farrak. Se vai a parlare con Tabetha, potrà dirti di più.$B$BE portati dietro qualche amico, $N. Se Tabetha ti manda a Zul'Farrak, non vorrai andarci $Gsolo:sola;.$B$BLa casetta di Tabetha la trovi a ovest di Theramore, subito a nord della Stonemaul Ruin.",
  obj = "Parla con Tabetha in Dustwallow Marsh.",
  reward = "Proprio così. Ho un osso da rompere a una troll. Anzi, più d'uno. Tutte le ossa che ha!$B$BMi dai una mano?",
  en_title = "Tabetha's Task",
  en_obj = "Speak with Tabetha in Dustwallow Marsh.",
}
T[2862] = {
  title = "Guerra Contro i Woodpaw",
  desc = "Gli gnolls... sono più di una seccatura. Sono una minaccia continua per l'esistenza stessa di questo accampamento! Che siano nativi di Feralas o no, poco importa: se non li affrontiamo con più determinazione, finiremo cacciati dall'intera regione.$B$BUltimamente gli attacchi gnoll contro l'accampamento si sono fatti più accaniti. Ci serve il tuo aiuto per sfoltire le loro file: portami dieci delle loro pellicce e ti ricompenserò generosamente per l'impegno.$B$BVai!",
  obj = "Porta 10 Woodpaw Gnoll Manes a Hadoken Swiftstrider a Camp Mojache.",
  progress = "Li ricacciamo indietro, e loro tornano all'attacco! Qualcuno o qualcosa deve spingerli alla frenesia... oh, sei $Gtornato:tornata;, eh, $N? Hai portato le pellicce che mi servono per pagare la taglia?",
  reward = "Questa è la prova di un buon inizio, $N: le tue capacità di soldato meritano un elogio.$B$BNon sei $Gl'unico:l'unica; a cui ho affidato questo compito. Molti prima di te li hanno combattuti, e in passato siamo riusciti a tenerli a bada. Di recente, però, cercano molto più spesso di spingersi a nord, nella nostra zona d'influenza, e anche i loro attacchi si sono fatti più feroci... quasi fossero disperati.$B$BPerò ho un piano, $N, che potrebbe sistemarli una volta per tutte...",
  en_title = "War on the Woodpaw",
  en_obj = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.",
}
T[2863] = {
  title = "Attacco agli Alfa",
  desc = "Il piano è questo: abbattere uno dopo l'altro, in rapida successione, diversi capi degli gnolls — gli Alfa, come si fanno chiamare. Se riusciamo a devastarli con tanta rapidità e precisione, nelle loro file scoppierà il caos. E forse riusciremo anche a far entrare in quelle teste dure e piene di pulci che possiamo distruggerli, e che lo faremo!$B$BVoglio che sia tu $Gil messaggero:la messaggera; della mia volontà, $N: elimina cinque dei loro Alfa entro un'ora, o il piano non funzionerà e resteremo in questo stallo!",
  obj = "Uccidi 5 Woodpaw Alphas e torna da Hadoken Swiftstrider entro un'ora.",
  progress = "Sta per scadere il tempo, $N! Se non sei qui per dirmi che hai eliminato gli Alfa, lo stai sprecando!",
  reward = "Hai fatto come ti ho chiesto, e per questo ti rendo onore. Accetta questa piccola ricompensa per i tuoi sforzi, $N.$B$BOra che le loro file sono sfoltite e i capi sono morti, gli gnolls ci penseranno due volte prima di assaltare l'accampamento. Ma la questione non è chiusa...$B$BDeve esserci un motivo se gli gnolls sono stati spinti a una tale frenesia. Prima che abbiano modo di riorganizzarsi, però, voglio scoprire cosa la provoca.",
  en_title = "Alpha Strike",
  en_obj = "Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour.",
}
T[2864] = {
  title = "Tran'rek",
  desc = "Mio cugino Tran'rek è nei guai. Settimane fa mi ha promesso un carico di gusci di scarabeo, e ancora non me l'ha consegnato. È mio cugino, perciò mi dispiacerebbe dover mandare qualcuno a Gadgetzan a rompergli qualcosa.$B$BCi parleresti tu, con Tran'rek, da parte mia? E gli faresti capire che deve preparare il carico prima che io faccia qualcosa di avventato?$B$BGadgetzan è nel nord di Tanaris, a Kalimdor.",
  obj = "Parla con Tran'rek a Gadgetzan.",
  reward = "Ciao!$B$BOh, hai parlato con mio cugino Krazek? Come sta? Spero che se la passi bene, a Booty Bay...$B$BGusci di scarabeo, dici? Beh... lascia che ti racconti una storia...",
  en_title = "Tran'rek",
  en_obj = "Speak with Tran'rek in Gadgetzan.",
}
T[2865] = {
  title = "Gusci di Scarabeo",
  desc = "Gli scarabei di Tanaris hanno gusci durissimi! Talmente duri che ci si costruisce un sacco di cose. Ma proprio tante!$B$BAnzi, quei gusci sono così utili... che hanno cacciato gli scarabei quasi fino all'estinzione!$B$BIo so dove ce ne sono altri, e se mi prometti di portarmi i loro gusci, ti dico dove trovarli. Promesso?$B$BOk, a Zul'Farrak c'è una colonia di scarabei. I troll, immagino, non li cacciano per i gusci.$B$BTu però puoi farlo! Va' a Zul'Farrak e portami dei gusci intatti!",
  obj = "Porta 5 Uncracked Scarab Shells a Tran'rek a Gadgetzan.",
  progress = "Ce li hai, i gusci? Mio cugino a Booty Bay aspetta un carico e sta perdendo la pazienza!",
  reward = "Oh, fantastico! Li hai trovati!$B$BGrazie, $N. Mi hai salvato la vita!",
  en_title = "Scarab Shells",
  en_obj = "Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.",
}
T[2866] = {
  title = "Le Ruins of Solarsal",
  desc = "A sud di qui ci sono le Ruins of Solarsal, un luogo che risale a molto prima dei tempi moderni. All'inizio le abbiamo esplorate, ma non vi abbiamo trovato nulla di rilevante, e così le abbiamo lasciate in pace.$B$BDi recente, però, i naga Hatecrest le hanno occupate in numero allarmante. In un primo momento abbiamo pensato che fosse il preludio di un attacco. È una minaccia ancora possibile, ma crediamo che ci possa essere dell'altro.$B$BVa' laggiù, esplora le rovine e cerca qualunque cosa ti salti all'occhio. Buona fortuna, $N.",
  obj = "Esplora Ruins of Solarsal e indaga sulla presenza dei naga in quel luogo.",
  reward = "A esaminarlo, il gazebo mostra cose interessanti e insolite rispetto alle rovine che lo circondano.$B$BPrimo, è chiaramente una costruzione più recente di tutto ciò che si trova lì intorno. Secondo, sui lati è incisa una piccola serie di glifi che si ripete sempre nello stesso schema; per il resto, non se ne conoscono né l'origine né il significato. Terzo, la pietra del gazebo è calda al tatto.$B$BQuesto, di sicuro, è qualcosa che \"salta all'occhio\" esplorando le rovine!",
  en_title = "The Ruins of Solarsal ",
  en_obj = "Explore the Ruins of Solarsal and investigate the presence of the naga there.",
}
T[2867] = {
  title = "Ritorno alla Feathermoon Stronghold",
  desc = "Hai scoperto lo strano gazebo nel cuore delle Ruins of Solarsal: è ora di tornare alla Feathermoon Stronghold e riferire a General Shandris Feathermoon quello che hai trovato qui.",
  obj = "Torna da Shandris Feathermoon a Feathermoon Stronghold e riferisci ciò che hai scoperto.",
  reward = "$GBentornato:Bentornata;, $N. Quello che mi riferisci su questo gazebo è davvero... inquietante. A quanto pare, anche se i naga laggiù non si stessero preparando ad attaccare, il fatto che restino lì non promette nulla di buono per la nostra avanzata nel Feralas. In ogni caso, eccoti un compenso per l'indagine.$B$BLa Feathermoon Stronghold, sembra, ha un disperato bisogno di altro aiuto contro i naga Hatecrest. Se sei $Gdisposto:disposta;, vorrei affidarti questo compito. C'è molto da fare.",
  en_title = "Return to Feathermoon Stronghold",
  en_obj = "Return to Shandris Feathermoon in the Feathermoon Stronghold and report your findings.",
}
T[2869] = {
  title = "Contro gli Hatecrest",
  desc = "A questo punto conviene dare per scontato che i naga, qualunque cosa stiano tramando, prima o poi si muoveranno per prendersi l'isola. Dobbiamo passare all'attacco e contrastare la minaccia prima che sia troppo tardi.$B$BPortami dieci Scaglie Hatecrest in buono stato: come procurartele dovrebbe esserti chiaro. Così ti farai le ossa con i naga per la prima volta, e la presenza dei naga sulla Sardor Isle si indebolirà — due risultati che vanno a nostro vantaggio.",
  obj = "Porta 10 Hatecrest Naga Scales a Latronicus Moonspear a Feathermoon Stronghold.",
  progress = "$N, se sei qui a rendere conto del compito che ti è stato affidato, eccellente — cerco dieci scaglie Hatecrest. Se invece sei qui per fare due chiacchiere, al momento non ho tempo per simili sciocchezze.$B$BSappi una cosa: noi elfi della notte non siamo guerrafondai, e la nostra razza è votata a preservare la pace e l'armonia. Questo però non vuol dire che non difenderemo attivamente i nostri interessi. È il mio dovere verso General Feathermoon e verso la roccaforte.",
  reward = "Sì, sì, queste scaglie vanno più che bene. Anzi, credo che le manderò giù a Pratt perché le esamini: magari riuscirà a ricavarne qualcosa di utile.$B$BQuanto a te, ho un'altra missione da affidarti, ma prima ecco la ricompensa per le scaglie. Il servizio costante che rendi al Generale e a tutta la Feathermoon Stronghold è una benedizione di fronte alle avversità.",
  en_title = "Against the Hatecrest",
  en_obj = "Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold.",
}
T[2870] = {
  title = "Contro Lord Shalzaru",
  desc = "$N, dai nuovi rapporti degli esploratori abbiamo un'idea chiara della catena di comando dei naga: fra le loro file ci sono anche dei reali, e sono loro a prendere tutte le decisioni.$B$BIn particolare, abbiamo individuato uno dei reali più crudeli: Lord Shalzaru. Secondo gli esploratori è stato proprio lui a portare alla luce una strana reliquia, durante un recente scavo dei naga in una grotta a sud delle rovine principali, al di là dell'acqua, sull'Isle of Dread.$B$BFerma lui e fermerai tutto questo. Poi portami la sua reliquia, così potremo studiarla.",
  obj = "Elimina Lord Shalzaru, poi porta la Mysterious Relic che ha portato alla luce a Latronicus Moonspear a Feathermoon Stronghold.",
  progress = "Abbattere Lord Shalzaru farebbe di certo slittare i loro piani di settimane, se non di mesi, e la reliquia che ha portato alla luce ci interessa senza dubbio.$B$BHai portato a termine la missione che ti è stata affidata, $N?",
  reward = "Ben fatto, $N! Con la morte di Lord Shalzaru i naga resteranno nello scompiglio per un po', se non per sempre. La minaccia che rappresentano è più che mai sotto il nostro controllo, e lo dobbiamo a te.$B$BEcco un'altra ricompensa dal tesoro della roccaforte — te la sei guadagnata fino all'ultima moneta di rame. Tu e i tuoi sarete sempre i benvenuti alla Feathermoon Stronghold, $Gamico mio:amica mia;.$B$BUn'ultima cosa prima che tu vada, $N... se potessi...",
  en_title = "Against Lord Shalzaru",
  en_obj = "Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold.",
}
T[2871] = {
  title = "La Consegna della Reliquia",
  desc = "Ti sarei grato se fossi così gentile da consegnare la reliquia a mia moglie, Vestia. Oltre a essere un'ottima sacerdotessa per la nostra comunità, è una delle studiose più esperte che si possano trovare. Io di questo congegno non ci capirei niente nemmeno con una scommessa in ballo. Mia moglie, invece: se qualcuno può scoprire che cos'è, è lei... e dobbiamo saperlo!$B$BÈ qui dietro l'angolo, di sicuro a studiare. Grazie, $N.",
  obj = "Consegna la Mysterious Relic a Vestia Moonspear a Feathermoon Stronghold.",
  progress = "Sì, posso aiutarti?$B$BAspetta, sei $Gil:la; $C che aiuta General Feathermoon e Latro contro la minaccia dei naga, vero? Io sono Vestia, la moglie di Latro — ehm, cioè, di Latronicus. Piacere di conoscerti!$B$BScusa, sei qui per lavoro, naturalmente. Hai qualcosa per me — da parte sua, per caso?",
  reward = "Interessante... dici che viene dalle Ruins of Solarsal? Be', Latro ha ragione, devo esaminarlo. A prima vista non sembra appartenere alle rovine. D'altra parte non è di fattura naga... non una cosa così estranea.$B$BMi ci vorrà un po' di tempo per studiarlo. Quando avrò finito, se sarai da queste parti, forse avrò bisogno dei tuoi talenti.$B$BEcco, prendi uno di questi oggetti, ne abbiamo in più: spero che ti sia utile!",
  en_title = "Delivering the Relic",
  en_obj = "Deliver the Mysterious Relic to Vestia Moonspear in Feathermoon Stronghold.",
}
T[2872] = {
  title = "Il Debito di Stoley",
  desc = "Il mio vecchio amico Stoley mi deve una bottiglia di rum, e non un rum qualunque. Fa il barista a Steamwheedle Port, a Tanaris, su Kalimdor, e mi ha promesso che il rum di laggiù è più forte di qualsiasi cosa si trovi a Booty Bay. È talmente sicuro di sé che dice che, se lo assaggio e non gli do ragione, mi raddoppierà i soldi che mi deve!$B$BBe', credo che ormai non sia più così sicuro come l'ultima volta che ci siamo parlati, e adesso ha paura di darmi quel rum. Ma io davanti a una scommessa non mi tiro indietro, quindi perché non vai tu a parlargli da parte mia...",
  obj = "Parla con Stoley a Steamwheedle Port.",
  reward = "Ah, allora hai parlato con MacKinley, eh?$B$BNon è come crede lui! Non ho paura di dargli un po' di Rum di Sentina Steamwheedle...$B$BIl fatto è che non ho rum da dargli!",
}
T[2873] = {
  title = "Stoley's Shipment",
  desc = "Devo del rum a \"Sea Wolf\" MacKinley a Booty Bay per saldare una scommessa, ma il rum è finito! Captain Cuergo mi ha rubato l'ultima spedizione e l'ha nascosta in quella città pirata cinta da mura, a sud.$B$BSe riesci a ritrovare la mia spedizione di rum e a riportarmela, potrò dimostrare a MacKinley che l'alcol di Kalimdor le suona di santa ragione a quello di Booty Bay!",
  obj = "Porta la Stoley's Shipment a Stoley a Steamwheedle Port.",
  progress = "L'hai trovata, la mia spedizione di rum, $N?",
  reward = "Ottimo, grazie della spedizione! Adesso io e MacKinley possiamo finalmente saldare la scommessa.",
}
T[2874] = {
  title = "Consegna a MacKinley",
  desc = "Grazie ancora dell'aiuto, $N. Ecco una bottiglia di rum di sentina Steamwheedle: portala a MacKinley, così finalmente potrà smetterla con quelle sue idee folli sull'alcol di Booty Bay.",
  obj = "Porta la Stoley's Bottle a \"Sea Wolf\" MacKinley a Booty Bay.",
  progress = "Stoley si è deciso a sganciare il mio alcol?",
  reward = "Mm, vediamo un po'...$B$BNon ci posso credere! Questa roba è... terribile! Fantastico!$B$BBe', direi che Stoley può tenersi i soldi che mi deve: sul rum di sentina Steamwheedle ha mantenuto la parola. Roba densa come la ghiaia, che brucia come la lava!",
}
T[2875] = {
  title = "RICERCATO: Andre Firebeard",
  desc = "Lo spregevole pirata Andre Firebeard è ricercato per crimini contro Steamwheedle e Gadgetzan.$B$BPer decreto del consiglio di governo, chiunque legga il presente avviso è autorizzato a ricorrere alla forza letale nel catturare Andre e i suoi complici.$B$BPer ulteriore decreto, se al momento dell'udienza Andre risultasse deceduto, o altrimenti indisposto, la sua testa potrà fare le sue veci, e la consegna di detta testa a Security Chief Bilgewhizzle costituisce un contratto vincolante, ed esigibile.",
  obj = "Porta la Testa di Andre a Security Chief Bilgewhizzle a Steamwheedle Port.",
  progress = "Mi sembri un po' $Gstordito:stordita;. Hai letto i nostri documenti legali?",
  reward = "Ah, la testa di Andre. Allora al processo ci arriva, alla fine!$B$BTi sono molto grato, $N. Ora, se firmi qui, posso pagarti per i servizi resi.$B$BLe clausole in piccolo non ti preoccupare: sono innocue, e... tanto non credo che esista una lente d'ingrandimento abbastanza piccola per leggerle.",
}
T[2876] = {
  title = "Ship Schedules",
  desc = "In questo rotolo sono segnati gli orari delle spedizioni fra Steamwheedle Port e Booty Bay, sia passate sia future, con i nomi delle navi. Accanto ai viaggi di alcune ci sono delle grosse 'X', accanto ad altri annotazioni come \"BOTTINO GROSSO\" e \"SCONTRO DURO\".$B$BA Steamwheedle Port qualcuno vorrebbe vedere questo documento.",
  obj = "Porta gli Ship Schedules a un'autorità di Steamwheedle Port.",
  progress = "Sembri senza fiato. Devi dirmi qualcosa?",
  reward = "Oh, cielo, ha tutta l'aria di una lista di partenze e arrivi delle navi, con date e orari precisi e tutto quanto! Se ci mettesse le mani sopra il capitano di una nave pirata, se la spasserebbe alla grande!$B$BDici che l'hai presa a un pirata? Beh, questa è una notizia preoccupante...$B$BGrazie, $N. Sono contento che tu gliel'abbia tolta e che quel pirata adesso morda la polvere!",
}
T[2877] = {
  title = "Pulizia di Skulk Rock",
  desc = "Noi Wildhammer il passato lo ricordiamo, più dei nostri fratelli di Ironforge. Se vuoi farti degli amici qui, sporcati le mani per noi!$B$BL'Orda ha abbandonato le sue posizioni nelle Hinterlands intorno a Skulk Rock; adesso la zona è invasa da sludges e melme schifose. Su quell'area abbiamo dei piani, ma prima ci serve una squadra di pulizia che ci apra un varco.$B$BEd è qui che entri in gioco tu, Raggio di Sole! Scendi laggiù, fai fuori dieci green sludges e dieci jade oozes e poi torna qui a fare rapporto da me. In marcia!",
  obj = "Uccidi 10 Green Sludges e 10 Jade Oozes, poi torna a fare rapporto da Fraggar Thundermantle ad Aerie Peak.",
  progress = "Non provare a mercanteggiare sulla missione, $R! Se gli dei avessero voluto morte quelle melme, ci avrebbero già pensato loro con un miracolo, non credi?!",
  reward = "Ma guarda un po' chi dà una mano ai Wildhammer! Sei $Gun:una; $C d'azione, e da queste parti è l'azione che rispettiamo.$B$BLa tua piccola missione di pulizia conta molto più di quanto pensi. Con gente che sfoltisce le melme e le sludges, in un attimo potremo allargare la nostra sfera d'influenza. Ecco — prendi qualcosina, oltre ai nuovi amici che ti sei $Gfatto:fatta; qui ad Aerie Peak!",
}
T[2878] = {
  title = "Corrupted Songflower",
  progress = "Quella che hai trovato sembra una pianta di songflower, malata e corrotta, e manda un odore pungente e malsano. Per tornare com'era, ha un disperato bisogno di cure.",
  reward = "Sul songflower applichi un po' di unguento per piante Cenarion, e la pianta comincia subito a perdere l'aspetto corrotto: rifiorisce, rigogliosa e sana.",
}
T[2879] = {
  title = "Lo Stave of Equinex",
  desc = "Forse questo è proprio lo Stave of Equinex! In realtà lo Stave of Equinex è una chiave: serve ad aprire l'Equinex Monolith nelle Ruins of Ravenwind, sulla terraferma a ovest del Dream Bough.$B$BFra quelle rovine ardono ancora quattro fiamme: Samha, Imbel, Byltan e Lahassa. Trovale e raccogline l'essenza, poi mettiti accanto all'Equinex Monolith e usa le essenze per caricare di energia il bastone. Se è davvero lo Stave of Equinex, potrai aprire il Monolito e prendere un manufatto sacro custodito al suo interno.",
  obj = "Carica di energia il Troyas' Stave e trova l'Equinex Monolith.",
  progress = "Silenzioso, l'Equinex Monolith si erge fra le rovine. Cosa conterrà?",
  reward = "Il bastone carico di energia è quasi impossibile da tenere in mano: il suo potere ti rimbomba in tutto il corpo.$B$BAllunghi la mano verso la fredda superficie dell'Equinex Monolith...$B$BSi apre una piccola porta: dentro c'è un manufatto, e puoi infilare la mano per prenderlo.$B$BRaggi di luce riempiono la zona tutt'intorno all'Equinex Monolith.",
}
T[2880] = {
  title = "Taglia sulle Collane Troll",
  desc = "Mettitelo in testa, $R — NON facciamo parte dell'Alleanza! I Wildhammer sono indipendenti, e per loro il valore si dimostra con le imprese e con i fatti, non con le chiacchiere di chi usa il blablà per dar forza al suo atteggiamento da fannullone!$B$BSe cerchi amici qui, prima dimostraci quanto vali! I luridi troll che soffocano i pendii delle Hinterlands a volte portano con sé delle collane tribali. Portamene cinque e lo segneremo come un passo nella giusta direzione per te.",
  obj = "Porta 5 Troll Tribal Necklaces a Fraggar Thundermantle ad Aerie Peak.",
  progress = "Voglio cinque di quelle collane tribali che i troll si portano addosso. Se te lo devo spiegare meglio, uccidi un troll e hai buone probabilità di trovarne una!$B$BDimostra ai Wildhammer quanto vali!",
  reward = "Ora sì che ci siamo! Vedi — queste collane dimostrano che sei $Gdisposto:disposta; a sporcarti le mani. Ed è una cosa che noi Wildhammer apprezziamo in chi frequentiamo.$B$BContinua così e prima o poi entrerai nelle nostre grazie.",
}
T[2881] = {
  title = "Taglia sulle Collane Troll",
  progress = "L'hai già fatto, ma le troll tribal necklaces che trovi e che sei $Gdisposto:disposta; a consegnare continueremo ad accettarle tutte. Ogni volta che me le porti la tua reputazione presso i Wildhammer migliora ancora; se sei $Gdisposto:disposta; a combattere per noi, noi saremo disposti a combattere per te!$B$BPerché contino me ne servono cinque, di troll tribal necklaces, $N.",
  reward = "Ora sì che ci siamo! Vedi — queste collane dimostrano che sei $Gdisposto:disposta; a sporcarti le mani. Ed è una cosa che noi Wildhammer apprezziamo in chi frequentiamo.$B$BContinua così e prima o poi entrerai nelle nostre grazie.",
}
T[2882] = {
  title = "Cuergo's Gold",
  desc = "La mappa mostra un tratto di spiaggia rivolto a sud. Sotto, in una bella grafia, c'è scritto...$B$BA sud di Wheedle$BA sud di casa$BCerca albero maestro, bandiera e ossa$BSe coraggio avrai, scava là$BScava e prenditi il Cuergo's gold!$BTi servirà una chiave, e una chiave vedrai$BGli uomini che affronterai ti faran pagare col sangue.",
  obj = "Trova il Cuergo's gold!",
  progress = "Il forziere è chiuso a chiave!",
  reward = "Ti aspetta il tesoro nascosto di Captain Cuergo!",
}
T[2902] = {
  title = "Indagine sui Woodpaw",
  desc = "Gli Gnolls non brillano per intelligenza, ma una qualche strategia scritta sulle ultime mosse ce l'avranno di sicuro. Se trovassimo quei piani, capiremmo meglio cosa li agita tanto.$B$BVoglio che torni dai Woodpaw e cerchi qualunque cosa somigli ai loro piani di battaglia. Qualcosa devono averlo: i loro attacchi sono stati troppo coordinati per farne a meno. Quando li avrai trovati, torna da me.",
  obj = "Trova i piani di battaglia gnoll da qualche parte negli accampamenti gnoll a sud di Camp Mojache.",
  reward = "Esaminando la mappa, scopri che sono i piani di battaglia che vuole Hadoken Swiftstrider. Ci sono disegnate numerose frecce, forse movimenti di truppe, ma per lo più sembrano puntare a sud, non a nord, dove si trova Camp Mojache.$B$BIn un altro punto della mappa c'è il disegno di quello che ti sembra una specie di grosso insetto, con varie tacche sotto. A giudicare dall'aspetto degli gnolls, forse indicano le perdite subite contro quegli insetti sconosciuti...",
  en_title = "Woodpaw Investigation",
  en_obj = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.",
}
T[2903] = {
  title = "I Piani di Battaglia",
  desc = "Hai scoperto i piani di battaglia degli gnolls: ora non resta che riportarli a Hadoken Swiftstrider, a Camp Mojache. Forse lui, o qualcun altro lì, riuscirà a capire meglio cosa tramano gli gnolls.",
  obj = "Porta i Woodpaw Battle Plans a Hadoken Swiftstrider a Camp Mojache.",
  progress = "$GBentornato:Bentornata;, $N — hai trovato qualche prova concreta dei piani degli gnolls?",
  reward = "Ah, proprio quello che ci serviva. Non sono molto bravo a decifrare gli scarabocchi di questa mappa, almeno non la maggior parte, ma ai miei tempi ho visto abbastanza piani di battaglia da capire come stanno messi gli gnolls. A quanto pare combattono una guerra su due fronti: uno contro di noi... ma il grosso delle loro forze sembra rivolto contro un nemico a sud.$B$BQui c'è sotto più di quanto sembri. Forse è ora di scoprire chi sia davvero quest'altro nemico che affrontano.",
  en_title = "The Battle Plans",
  en_obj = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.",
}
T[2904] = {
  title = "Un Bel Pasticcio",
  desc = "<Kernobee geme.> Cos... cos'è successo?$B$BL'ultima cosa che ricordo è un gruppo di nani dark iron che mi cattura, mi picchia quasi a morte e poi mi butta qui dentro con questi sudici troggs.$B$BTirami fuori di qui, $N!$B$BIl piano è questo: tu mi porti fino all'uscita e, se ne usciamo vivi, vai a Booty Bay a dire a Scooty che sono andato a Ratchet ad avvertire Tinkerwiz che nella costruzione di quel supermacchinario ci sono di mezzo i dark iron.$B$BMuoviamoci!",
  obj = "Scorta Kernobee fino all'uscita di Clockwerk Run, poi fai rapporto a Scooty a Booty Bay.",
  progress = "Eh? Kernobee è vivo??",
  reward = "Immagino che una ricompensa te la meriti, per averci riportato Kernobee tutto intero, $N. Se torni a Gnomeregan, queste potrebbero darti il vantaggio che ti servirà per battere quel traditore buono a nulla di Mekgineer Thermaplugg.",
  en_title = "A Fine Mess",
  en_obj = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.",
}
T[2922] = {
  title = "Salva il Cervello di Techbot!",
  desc = "Quando è caduta la nostra amata città di Gnomeregan, una scintilla vagante deve aver dato la scossa a Techbot, la mia povera creazione. Un tempo dava una mano a me e ai miei colleghi con aggeggi a non finire e una scorta infinita di informazioni, ma il suo cervello positronico si è polarizzato. Adesso è negatronico... e il comportamento di Techbot si è capovolto: vaga per Gnomeregan in preda alla frenesia!$B$BMa forse si può ancora salvare. Se riesci a recuperare il nucleo della memoria di Techbot e a portarmelo, forse scoprirò cosa ha causato la polarizzazione e potrò riparare il mio povero Techbot.",
  obj = "Porta il Techbot's Memory Core a Tinkmaster Overspark a Ironforge.",
  progress = "Hai trovato Techbot? Il nucleo della memoria, l'hai recuperato??",
  reward = "Oh, magnifico! Grazie, $N! Mi ci metto subito!!$B$BPovero, povero Techbot... Non abbatterti. Ti rimetteremo in sesto.$B$BE adesso, dove avrò messo la spina della chiave girevole a martinetto idraulico...",
  en_title = "Save Techbot's Brain!",
  en_obj = "Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge.",
}
T[2923] = {
  title = "Tinkmaster Overspark",
  desc = "Tinkmaster Overspark è molto turbato per quello che è successo a Techbot, la sua creazione meccanica. Io me lo ricordo come un congegno gentile, che agli gnomi tornava utile, ma Overspark mi dice che si è guastato.$B$BChe tristezza. Ma con un po' di fortuna forse si può riparare!$B$BVai a parlare con Tinkmaster Overspark, a Tinker Town, a Ironforge: sarebbe felice del tuo aiuto.",
  obj = "Parla con Tinkmaster Overspark a Ironforge.",
  reward = "Sì, è vero: Techbot è impazzito! Ti prego, mi puoi aiutare?",
  en_title = "Tinkmaster Overspark",
  en_obj = "Speak with Tinkmaster Overspark in Ironforge.",
}
T[2924] = {
  title = "Essential Artificials",
  desc = "Un componente meccanico adatto quasi a ogni uso — l'essential artificial — era utilissimo agli inventori e ai fabbri di Gnomeregan. Ma nella fuga precipitosa dalla città nessuno si è ricordato di portarne via neanche uno! E a me ne servono moltissimi per un lavoro che sto per cominciare.$B$BTi prego, va' a Gnomeregan e procurami un po' di essential artificials. Li troverai nelle zone più profonde della città, chiusi in contenitori chiamati estrapolatori artificiali.$B$BGrazie, $N, e mi raccomando, fai in fretta!",
  obj = "Porta 12 Essential Artificials a Klockmort Spannerspan a Ironforge.",
  progress = "Hai gli essential artificials?",
  reward = "Li hai trovati! Ora posso cominciare i miei nuovi esperimenti!$B$BNon so davvero come ringraziarti, $N! Con il tuo coraggio hai fatto fare passi da gigante alla ricerca gnomesca!",
  en_title = "Essential Artificials",
  en_obj = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge.",
}
T[2925] = {
  title = "Gli Essenziali di Klockmort",
  desc = "Un amico gnomo, Klockmort Spannerspan, mi ha mandato un messaggio da Ironforge. Scrive che gli serve aiuto per una missione pericolosa ma essenziale a Gnomeregan, la città degli gnomi, un tempo gloriosa, oggi contaminata e infestata da abitanti impazziti e dai loro congegni.$B$BDevo restare qui, ma mi si stringe il cuore a non poterlo aiutare. Se potessi andarci tu al posto mio, te ne sarei profondamente grato.$B$BTroverai Klockmort a Tinkertown, a Ironforge.",
  obj = "Parla con Klockmort Spannerspan a Ironforge.",
  reward = "Sì, eccome! Mi serve davvero aiuto per una missione a Gnomeregan. E tu sei proprio $Gil:la; $C $Gadatto:adatta; all'impresa!",
  en_title = "Klockmort's Essentials",
  en_obj = "Speak with Klockmort Spannerspan in Ironforge.",
}
T[2926] = {
  title = "Gnoscalin",
  desc = "Dopo l'incidente, Gnoarn non fa altro che pensare e parlare di ripulire Gnomeregan dai trogg che la infestano e di trovare una cura per il morbo che la affligge, $N.$B$BPer fortuna, io e Razzle siamo a un passo da una specie di cura — o da quella, o dalla ricetta di un rum potentissimo. Non lo sapremo finché non lo proviamo! Naturalmente, per mettere alla prova la nostra teoria, ci serve qualcosina: per la precisione, le scorie radioattive dei trogg irradiati di Gnomeregan. Riempi questa fiala di quella roba verde brillante e riportamela!",
  obj = "Usa l'Empty Leaden Collection Phial sugli Irradiated Invaders o sugli Irradiated Pillagers per raccogliere scorie radioattive. Quando è piena, riportala a Ozzie Togglevolt a Kharanos.",
  progress = "Non vedi che qui stiamo cercando di curare l'intero popolo degli gnomi??! Ci serve altra roba verde brillante!",
  reward = "Ottimo lavoro! È giunto il momento di provare la nuova formula. Se funziona, non solo quel captured leper gnome dovrebbe guarire, ma a me dovrebbero ricrescere tutti i capelli! Fatti indietro!",
  en_title = "Gnogaine",
  en_obj = "Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.",
}
T[2927] = {
  title = "Il Giorno Dopo",
  desc = "Non crederai mica che sia sempre stato calvo, vero? Eh no, $Gsignore:signora;! Questa tragica perdita di capelli la devo alla fuga radioattiva a Gnomeregan. Fino a quel giorno avevo l'unico gnomafro di tutta Azeroth.$B$B<Gnoarn agita il pugno in aria.>$B$BMaledetti quei maledetti sudici troggs — maledetti tutti quanti!!$B$BForse non è ancora troppo tardi, $N. Magari si può ancora salvare — la città, intendo! Va' a parlare con Ozzie Togglevolt a Kharanos. Lui e il suo socio Razzle stanno lavorando a una soluzione.",
  obj = "Parla con Ozzie Togglevolt a Kharanos.",
  reward = "Ero sicuro che perdere quella splendida chioma sarebbe stata la sua fine, e invece è sopravvissuto!$B$BGli ero proprio accanto quando il raggio radioattivo l'ha colpito. Quelle deliziose ciocche castane sono cadute a terra a ciuffi! A grappoli! E l'orrore è stato ancora più grande quando Gnoarn è andato completamente fuori di testa! Oh sì, fuori di testa, proprio così! Gnoarn si è toccato la testa calva senza riuscire a crederci, con uno sguardo che gridava vendetta, $N! Poi ha rivolto la rabbia contro i troggs!$B$B<Ozzie rabbrividisce.>",
  en_title = "The Day After",
  en_obj = "Speak with Ozzie Togglevolt in Kharanos.",
}
T[2928] = {
  title = "Escavazionatori Girotrivellomatici",
  desc = "È terribile, $N. Non avremo pezzi a sufficienza per portare a Dun Morogh la nostra flotta di escavazionatori girotrivellomatici.$B$BCi servono pezzi di ricambio, $N. E per i nostri veicoli dove trovarne, se non a Gnomeregan? Ho sentito dire che laggiù bot e mech se ne vanno in giro liberi come bestiame al pascolo nella prateria.$B$BHo bisogno che tu vada a Gnomeregan a fare a pezzi quei robot. Portami le loro interiora da robot. Due dozzine dovrebbero bastare.",
  obj = "Porta ventiquattro Robo-mechanical Guts a Shoni a Stormwind.",
  progress = "Se questa fosse una gara, a quest'ora l'avresti già persa.",
  reward = "Andrà benissimo, $N. Ecco riparato un escavazionatore girotrivellomatico; ne restano altri 398.",
  en_title = "Gyrodrillmatic Excavationators",
  en_obj = "Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.",
}
T[2929] = {
  title = "Il Grande Tradimento",
  desc = "Avevo fiducia in Thermaplugg, $R. Non avrei mai pensato che potesse tradire me e tutto il popolo gnomico. E per cosa, poi? Il potere? La ricchezza? Col tempo li avrebbe avuti comunque. Ci hanno cacciati da casa nostra, e ora è quel pazzo a comandare. Il re del nulla...$B$BCi riprenderemo Gnomeregan, $N. Non ci fermeremo finché la città non tornerà nelle nostre mani. Se vuoi unirti alla nostra lotta, ti chiedo una cosa semplice: uccidi il traditore. Distruggi Mekgineer Thermaplugg.",
  obj = "Avventurati a Gnomeregan e uccidi Mekgineer Thermaplugg. Torna da High Tinker Mekkatorque quando il compito sarà completato.",
  progress = "Hai portato a termine il compito? Ha implorato clemenza? Pietà??",
  reward = "Mi piace pensare che l'ultima cosa che gli è passata per la testa, mentre crollava a terra, sia stato il tuo piede, $R. Con Thermaplugg morto, i piani per riprenderci Gnomeregan sono un passo più vicini a diventare realtà.",
  en_title = "The Grand Betrayal",
  en_obj = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.",
}
T[2930] = {
  title = "Salvataggio Dati",
  desc = "Quanti dati ci siamo lasciati dietro, quando siamo fuggiti da Gnomeregan! E che dati, di vitale importanza!$B$BNelle profondità di Gnomeregan c'è un terminale ad alta sicurezza Matrix Punchograph 3005-D, e a me serve una prismatic punch card con i suoi dati. Devi accedere al terminale, ma prima ti serve l'autorizzazione... e per averla devi passare dai terminali a sicurezza più bassa — i modelli -A, -B e -C. E per fare QUESTO ci vogliono le schede perforate di sicurezza, cominciando da quella bianca... e le abbiamo lasciate tutte in città.$B$BUna catastrofe! Mi aiuti?",
  obj = "Porta una Prismatic Punch Card a Master Mechanic Castpipe a Ironforge.",
  progress = "Ce l'hai, la prismatic punch card??",
  reward = "Ce l'hai fatta! Hai trovato la prismatic punch card, hai recuperato i dati perduti! Dati di importanza vitale, cruciale, incommensurabile: senza di loro non avremmo potuto vivere un istante di più!$B$BIl tuo servizio resterà a lungo nella memoria degli gnomi, $N.",
  en_title = "Data Rescue",
  en_obj = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.",
}
T[2931] = {
  title = "L'Incarico di Castpipe",
  desc = "Master Mechanic Castpipe, a Ironforge, cerca avventurieri! Sta mettendo insieme delle squadre da rimandare a Gnomeregan per una missione di recupero dati di massima sicurezza e di massima importanza.$B$BCastpipe non sarà un membro dell'Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences come me, però resta uno gnomo intelligente: se pensa che una cosa sia importante, secondo i miei calcoli ci sono ottantaquattro probabilità su cento che lo sia davvero!$B$BMica male, come probabilità!",
  obj = "Parla con Master Mechanic Castpipe a Ironforge.",
  reward = "Sto organizzando delle missioni di estrazione dati a Gnomeregan: se sei qui per questo, ascolta bene!",
  en_title = "Castpipe's Task",
  en_obj = "Speak with Master Mechanic Castpipe in Ironforge.",
}
T[2932] = {
  title = "Messaggio Cupo",
  desc = "Un tempo i Witherbark trolls erano alleati dell'Orda, ma hanno tradito Thrall... e questo va punito!$B$BEcco, prendi la mia picca e va' nell'Hinterlands, molto più a nord. Sta a nord-est di Tarren Mill, un villaggio in mano ai nostri alleati, i Forsaken.$B$BQuando arrivi nell'Hinterlands, dai la caccia ai Witherbark trolls. Prendi i loro teschi e pianta la mia picca nel terreno di uno dei loro villaggi più piccoli, Hiri'watha o Zun'watha.$B$BFagli capire che le loro azioni spregevoli hanno delle conseguenze!",
  obj = "Raccogli i Witherbark Skulls e mettili sulla Nimboya's Pike. Pianta la Nimboya's Laden Pike in uno dei Witherbark Villages nell'Hinterlands, poi torna da Nimboya a Stranglethorn.",
  progress = "Il mio incarico non l'hai ancora portato a termine, $N.",
  reward = "Ho saputo della tua impresa. Cupa, ma onorevole. Speriamo che i Witherbark diano ascolto al tuo messaggio.",
}
T[2933] = {
  title = "Venom Bottles",
  desc = "Dentro queste bottiglie c'è un veleno verde e ripugnante.$B$BCon tutte le bottiglie che ci sono in questo villaggio, per i Witherbark dev'essere una cosa molto importante. Magari a uno speziale del vicino Tarren Mill farebbe piacere averne un campione.",
  obj = "Porta una Venom Bottle a uno speziale a Tarren Mill.",
  progress = "Salve, gentile $C. È stata una giornata lunga, e non mi è riuscito nemmeno un esperimento... Spero che mi porti buone notizie.",
  reward = "Ah, e questo cos'è? Sembra veleno... di una qualche creatura aracnoide, ritengo. E dove l'hai preso?",
}
T[2934] = {
  title = "Undamaged Venom Sac",
  desc = "Devo avere un campione fresco del veleno che mi hai portato. I ragni da cui l'hanno raccolto devono vivere nelle Hinterlands — dagli la caccia finché non trovi un'undamaged venom sac, e portamela. Di ragni ne troverai molti vicino alla città troll di Shadra'Alor.$B$BNon indugiare, $N: quando me la consegni, la sacca deve essere ancora fresca.",
  obj = "Porta un'Undamaged Venom Sac ad Apothecary Lydon a Tarren Mill.",
  progress = "Hai l'undamaged venom sac, $N? Non vedo l'ora di sperimentare il suo veleno fresco, e ho ordinato una serie di animaletti terribilmente carini su cui provarlo!",
  reward = "Oh, splendido! Il veleno è davvero fresco, e sono certo che sia letalissimo. Grazie!",
}
T[2935] = {
  title = "Consulta Master Gadrin",
  desc = "Il veleno dei guardiani della covata non era potente quanto quello che mi avevi portato all'inizio: deve venire da un altro ragno.$B$BVoglio un campione fresco di quel veleno. Per scoprire da dove arriva devi consultare un troll che conosca bene i Witherbark — Master Gadrin, a Sen'jin Village. Va' in Durotar e parla con Gadrin. Con un po' di fortuna, saprà dove i Witherbark si procurano il veleno.",
  obj = "Parla con Master Gadrin a Sen'jin Village.",
  reward = "Ah, allora vuoi il veleno fresco del ragno dei witherbark, eh? Beh, siediti... quello che sto per dirti non ti piacerà.",
}
T[2936] = {
  title = "La Dea Ragno",
  desc = "I Witherbark venerano una dea ragno, ed è da lei che raccolgono il veleno più potente. Quindi, se vuoi il veleno, devi evocare la loro dea!$B$BE per evocarla devi conoscere il suo vero nome. È scritto su una tavoletta sepolta a Tanaris, nella città troll di Zul'Farrak, dentro una tomba sorvegliata da Theka the Martyr.$B$BSconfiggi Theka, trova la sua tavoletta e leggila: così scoprirai il nome della dea ragno. Quando lo saprai, torna da me.",
  obj = "Leggi la Tablet of Theka per scoprire il nome della dea ragno dei Witherbark, poi torna da Master Gadrin.",
  progress = "Lo conosci, il nome della dea ragno?",
  reward = "Ah, Elortha no Shadra... questo nome pronuncialo solo sussurrando, perché nei regni dello spirito dirlo ha un grande peso.$B$BLo scriverò su una pergamena e ti preparerò un incantesimo di evocazione...",
  en_title = "The Spider God",
  en_obj = "Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin.",
}
T[2937] = {
  title = "Evocare Shadra",
  desc = "Prendi questa pergamena e leggila davanti all'altare di Shadra'Alor, nel cuore del regno dei witherbark nelle Hinterlands: così evocherai Shadra, la dea ragno.",
  obj = "Sconfiggi Shadra all'altare di Shadra'Alor, poi porta il suo veleno ad Apothecary Lydon a Tarren Mill.",
  progress = "Ce l'hai, il veleno?",
  reward = "Forte, ce l'hai!",
}
T[2938] = {
  title = "Veleno per Undercity",
  desc = "Il veleno che hai raccolto dal dio ragno dei Witherbark è proprio una bella scoperta! Con appena una goccia di quella roba sono riuscito a uccidere quasi due dozzine di conigli. Certo, alcuni erano molto giovani, così piccoli da stare nel palmo di una mano, e di sicuro resistevano poco alle tossine, ma non si può negare che questo veleno sia potente!$B$BVorrei che ne mandassi un campione al mio superiore, Apothecary Faranell, nell'Apothecarium of the Undercity. Sono certo che vorrà provarlo di persona.",
  obj = "Porta la Faranell's Parcel a Master Apothecary Faranell a Undercity.",
  progress = "Mi avevano avvisato che stavi arrivando, $N. Hai una busta per me?",
  reward = "Ah, molto bene. Lydon ha detto che il veleno in questa busta è il più potente che abbia mai maneggiato, e sta lavorando a nuovi modi di usarlo.$B$BCon un po' di fortuna, ne troveremo molti.$B$BGrazie, $N. Quello che hai fatto per la Royal Apothecary Society non si può negare.",
}
T[2939] = {
  title = "In Cerca di Conoscenza",
  desc = "Per quanto le rovine di Feralas possano essere piuttosto pericolose, hanno molto da raccontare su quello che è successo qui.$B$BQualche giorno fa, frugando fra le macerie a sud, ho trovato quello che ha tutta l'aria di un normale bastone, eppure non riesco a togliermi dalla testa che sia qualcosa di più. Angelas e io ci abbiamo passato ore sui libri, senza trovare niente.$B$BUna mia collega a Darnassus forse sa dirci di cosa si tratta, $N. Perché non vai a parlarle e vedi se può aiutarci?",
  obj = "Parla con Daryn Lightwind a Rut'theran Village.",
  reward = "Oh, e così ti manda Troyas Moonbreeze?$B$B<borbotta>...sempre lì a infastidirmi con quelle sue idee strampalate, convinto di aver trovato qualcosa di importante...$B$BSenti, $N, sarò franca. Troyas è sempre convinto di aver scoperto qualcosa di importante in quelle rovine. La verità è che probabilmente gli ogres o le arpie che ci vivono adesso si sono accaparrati da un pezzo tutto ciò che aveva davvero valore.$B$BSei $Glibero:libera; di dare un'occhiata in giro, ma non so se troverai qui qualche libro che possa esserti utile.",
}
T[2940] = {
  title = "Feralas: A History",
  desc = "Questo libro sembra non essere stato aperto da moltissimo tempo. Le copertine sono parecchio consumate e le pagine ingiallite, ma esaminandolo ti accorgi che potrebbe essere proprio ciò che Troyas sta cercando.$B$BLo sollevi, ma ti rendi conto che faresti meglio a chiedere prima di prenderlo in prestito.",
  obj = "Chiedi a Daryn Lightwind se puoi prendere in prestito il suo libro.",
  reward = "Dunque, vorresti prendere in prestito Feralas: A History?$B$BFammi pensare...$B$BTi presterò questo libro, $N, ma solo se prima farai qualcosa per me.",
}
T[2941] = {
  title = "Chi Chiede in Prestito",
  desc = "Nella mia vita ho studiato molte materie, e la mia ultima passione sono gli snapjaw che popolano la spiaggia nelle Hinterlands. Ce n'è uno in particolare che vorrei vedere, uno snapjaw gigante di nome Gammerita. Andrei io stessa, ma le mie ricerche mi trattengono qui. Credo che una sua immagine sarebbe il miglior ripiego.$B$BPorta questa lettera a Curgle Cranklehop a Tanaris. Lei ha creato per me un'invenzione capace di catturare un'immagine. L'ha chiamata \"istantanea\", mi pare...",
  obj = "Porta la lettera a Curgle Cranklehop a Tanaris.",
  progress = "Una lettera — per me?",
  reward = "Sei $Gun altro:un'altra; tirocinante di Daryn? È una storica davvero preparata, $N. Dovresti essere $Ggrato:grata; di studiare sotto la sua guida.$B$BE ora fammi prendere il Super Snapper FX. Ti piacerà da matti!",
}
T[2942] = {
  title = "La Pietra del Domani",
  desc = "Appena togli il manufatto dal Monolito, senti che l'energia dello Stave of Equinex comincia a svanire.",
  obj = "Riporta la Pietra Scintillante e lo Stave of Equinex a Troyas Moonbreeze nella Feathermoon Stronghold.",
  progress = "Sono lieto che tu sia $Gtornato:tornata;, $N: sono ansioso di sapere cosa hai scoperto.",
  reward = "Da quando sei $Gpartito:partita;, $N, ho continuato a leggere. Questa pietra che hai trovato si chiama Pietra del Domani. Non sono ancora del tutto sicuro di a cosa serva, ma se qualcuno l'ha nascosta in quel modo dentro l'Equinex Monolith, puoi stare $Gcerto:certa; che è qualcosa di grande importanza.$B$BProseguirò i miei studi, e spero di poter contare su di te in futuro, $N. Grazie per tutto il tuo aiuto.",
}
T[2943] = {
  title = "Ritorno da Troyas",
  desc = "Eccolo, $N. Ti prego, abbi cura del mio libro.$B$BOra sbrigati. Sono certa che Troyas non vede l'ora che tu torni.",
  obj = "Consegna il libro a Troyas Moonbreeze a Feathermoon Stronghold.",
  progress = "Salve, $N. Sei $Gstato:stata; a Darnassus?",
  reward = "Hai portato un libro. Eccellente!",
}
T[2944] = {
  title = "Il Super Snapper FX",
  desc = "Sarai $Gil primo:la prima; a vedere la mia nuova invenzione, $N. Ti basta inquadrare quello che vuoi fotografare e premere il pulsante.$B$BCome si chiamava quella creatura delle Hinterlands che hai nominato? Gammerita? Be', buona fortuna a trovarla. Sono certa che Daryn sarà davvero contenta dell'istantanea che le porterai.$B$BComunque, ecco il Super Snapper. Divertiti!",
  obj = "Usa il Super Snapper FX per scattare un'istantanea di Gammerita, poi torna da Daryn Lightwind a Rut'theran Village.",
  progress = "Allora, finalmente sei $Gtornato:tornata;, $N. E hai portato l'aggeggio che Curgle ha costruito per me — perfetto.",
  reward = "Bene! L'invenzione di Curgle si è dimostrata all'altezza delle aspettative.$B$BNon montarti la testa, ma sappi che sono soddisfatta del tuo lavoro, $N.$B$BOra, dove ho lasciato quel libro...",
}
T[2945] = {
  title = "Grime-Encrusted Ring",
  desc = "Dal cadavere di uno dei nani Dark Iron hai recuperato quello che sembra un anello. Che tipo di anello sia, però, è difficile dirlo: è tutto ricoperto di sporcizia e residui induriti, e non c'è modo di indossarlo. Sotto i residui ti pare di intravedere la lieve lucentezza di un metallo prezioso, e forse persino lo scintillio di una gemma.$B$BSe vuoi usare questo anello, dovrai trovare qualcosa per ripulirlo dalle incrostazioni.",
  obj = "Trova un modo per togliere la sporcizia dal Grime-Encrusted Ring.",
  progress = "Il marchingegno gnomesco che hai davanti porta una targhetta con la scritta \"The Sparklematic 5200\". A leggere le istruzioni lì sotto, la macchina in sostanza serve a togliere lo sporco dagli oggetti: si mette dentro l'oggetto e poi, per avviarla, si infilano tre monete d'argento in una fessura.$B$BIl grime-encrusted ring che hai trovato prima sembra proprio la cosa giusta da provare in questa macchina!",
  reward = "Metti l'anello nello Sparklematic 5200 e infili una moneta d'argento nella fessura.$B$BLa macchina si mette a sobbalzare violentemente, con dolorosi rumori di macinazione. Cosa stia succedendo là dentro all'anello, si può solo immaginare...$B$BLa macchina si ferma all'improvviso e strombazza la fine con un semplice \"Ding!\" Il vano degli oggetti si apre e rivela una scatolina ben incartata, con un fiocco rosso. Sembra che lo Sparklematic 5200 faccia anche i pacchetti regalo!",
  en_title = "Grime-Encrusted Ring",
  en_obj = "Figure out a way to remove the grime from the Grime-Encrusted Ring.",
}
T[2946] = {
  title = "Vedere Cosa Succede",
  desc = "Vogliamo che porti ai cancelli sigillati di Uldum i dischi in miniatura che hai trovato. Cosa succederà quando lo farai... non... non lo sappiamo con certezza.$B$BLo ammettiamo, sembra rischioso. Ma potrebbe anche non succedere niente. Forse dovrai usare i dischi su qualcosa, o magari le porte si apriranno quando li avrai con te. Sii $Gdisposto:disposta; a provare di tutto, e $Gpronto:pronta; a qualsiasi cosa.$B$BQuando avrai scoperto cosa succede, torna a Ironforge: al tuo ritorno avremo un sacco di cose da analizzare!",
  obj = "Porta i miniature platinum discs ai cancelli di Uldum a Tanaris e cerca indizi sul collegamento tra le due cose.",
  progress = "Dalla sabbia rovente spunta questo piedistallo dall'aspetto familiare. Forse il fatto che sia qui significa qualcosa...",
  reward = "Quando tocchi il piedistallo, nello zaino i dischi in miniatura di Uldaman si mettono a ronzare e a brillare. Un formicolio familiare ti corre lungo le mani, e davanti ai cancelli di Uldum prende vita l'immagine di un'altra Stone Watcher.$B$B\"Saluti. Sono un guardiano dell'ingresso. Ai dischi usati per l'accesso mancano i dischi d'ingresso corretti, le Piastre di Uldum. Si prega di integrare tali piastre nella struttura dei dischi e di ripetere la sequenza d'accesso. Grazie.\"",
}
T[2947] = {
  title = "Il Ritorno dell'Anello",
  desc = "Apri la scatola uscita dallo Sparklematic 5200 e trovi quello che sospettavi — un anello luccicante! Quando lo indossi, senti un potere magico scorrerti nel corpo.$B$BDentro la fascia c'è impresso il sigillo di Ironforge, piccolo ma riconoscibile. Accanto sono incise tre minuscole iniziali: \"TdK\". Forse sono di chi possedeva l'anello prima di te, o forse di chi l'ha fabbricato. Tieniti l'anello... oppure restituiscilo a questa persona. Decisioni, decisioni...",
  obj = "Puoi tenere l'anello, oppure trovare la persona responsabile dell'impronta e delle incisioni all'interno della fascia.",
  progress = "Ehi, piano, $Gsocio:socia; — sono un uomo d'affari molto importante! Sono sicuro che il corriere è solo in ritardo a portare l'affitto... aspetta... tu non sei il mio padrone di casa.$B$BMa certo che non lo sei — che sciocco! Sei $Gvenuto:venuta; da me perché cerchi il miglior gioielliere di tutta Ironforge, uno che NON fabbrica oggetti MALEDETTI! Sì!$B$BEhm... cosa ti serve?",
  reward = "Un anello, dici? Fammi vedere... sì, perbacco, quell'anello l'ho fatto io.$B$BPrima che Gnomeregan saltasse in aria, lì avevo un negozietto. Magari è uno di quelli che ho lasciato quando me la sono data a gambe: è un modello semplice, e ne ho fatti diversi uguali. Magari era di qualcuno che non è riuscito a uscire.$B$BCe l'avevano i nani Dark Iron? Beh, ecco un altro strato di complotto da aggiungere ai nove che già circolano. Forse alle autorità interesserebbe saperlo; con uno come me è sprecato.$B$BOra, torniamo all'anello...",
  en_title = "Return of the Ring",
  en_obj = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.",
}
T[2948] = {
  title = "Fai da Gnomo",
  desc = "Senti, $N, l'anello è tuo, certo... ma io posso fartene uno migliore! Te l'ho detto, quel modello è davvero semplice. Adesso sono molto più abile, e per la modica somma di trenta monete d'argento te lo abbellisco! Beh, a dire il vero un po' più di trenta...$B$BIl fatto è che al momento sono in difficoltà; ho finito del tutto i materiali. Se mi porti un lingotto d'argento e una moss agate, ci aggiungo un intreccio d'argento e agata che gli darà un po' più di brio!$B$BFidati!",
  obj = "Porta il Brilliant Gold Ring, un Silver Bar, una Moss Agate e 30 monete d'argento a Talvash del Kissel a Ironforge.",
  progress = "Allora, ce li hai i materiali che mi servono? Non te li chiederei, se la fortuna non mi avesse voltato le spalle...",
  reward = "Ah, era proprio quello che mi serviva! Un giorno, quando sarò uscito da questo buco dove sono finito senza colpa, creerò per te, anzi per TUTTI, i monili più belli di tutta Azeroth! Intanto grazie per essere $Gstato comprensivo:stata comprensiva; sui reagenti. Di solito, per un anello di questa qualità, chiedo dieci volte tanto...$B$BA proposito di anelli, eccoti quello nuovo!",
  en_title = "Gnome Improvement",
  en_obj = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge.",
}
T[2949] = {
  title = "Il Ritorno dell'Anello",
  desc = "Apri la scatola uscita dallo Sparklematic 5200 e dentro trovi un anello scintillante! Appena lo infili, un'ondata di potere magico ti attraversa il corpo.$B$BDentro la fascia è impresso il sigillo di Orgrimmar: piccolo, ma si riconosce. Accanto ci sono delle lettere incise, ma anche dopo averle pulite se ne leggono solo le prime tre: \"NOG...\"$B$BForse sono le iniziali di chi lo possedeva prima, o magari di chi l'ha fatto. Tenere l'anello... o andare a cercare \"NOG\" — decisioni, decisioni...",
  obj = "Puoi tenere l'anello, oppure trovare chi ha fatto l'impronta e le incisioni all'interno della fascia.",
  progress = "Uno penserebbe che un modo per superare quei piccoli gnomi schifosi lo troveremmo da soli. Ci scommetterei perfino: quel marchingegno, in origine, ce l'hanno rubato loro! Bah, quegli unti, sudici... ehm, sì? Ti serve qualcosa?",
  reward = "Un anello che viene da Gnomeregan? Fammi vedere... Mio non è, però è interessante.$B$BLa storia di Gnomeregan — ben gli sta, a quel branco di zucconi. Sono stati una barzelletta per anni, e adesso, quasi da un giorno all'altro, si mettono a costruire marchingegni migliori dei nostri?$B$BL'anello ce l'avevano i nani Dark Iron? Questo è ancora più interessante! Sai, può darsi che gli gnomi abbiano rubato i loro folli progetti di golem e poi li abbiano modificati. Di sicuro quei Dark Irons ci terrebbero a una bella vendetta. Vale la pena di indagare.$B$BSai, a proposito di quell'anello...",
  en_title = "Return of the Ring",
  en_obj = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.",
}
T[2950] = {
  title = "Nogg Rifà l'Anello",
  desc = "No, no, no — non è che adesso, così di punto in bianco, dico che l'anello è mio. Di solito non lo faccio, ma quello che mi hai detto sui Dark Irons mi è stato molto utile. Te lo migliorerò come non avrebbe mai saputo fare chi ha costruito questa cosetta da niente. Qualche gnomo, probabilmente...$B$BPortami un lingotto d'argento, una moss agate e trenta monete d'argento per il disturbo, e io aggiungerò all'anello un reticolo d'argento e agata che rafforzerà la magia che contiene. Ti interessa?",
  obj = "Porta il Brilliant Gold Ring, un Silver Bar, una Moss Agate e 30 monete d'argento a Nogg a Orgrimmar.",
  progress = "Hai i materiali che mi servono? Se non mi porti tutto quello che ti ho chiesto, questo progetto non lo posso migliorare.",
  reward = "Ecco il tuo anello, meglio di prima. E grazie ancora di quello che mi hai detto su quei nani Dark Iron. Mi sembra una pista ragionevole per capire come mai a quegli gnomi sia venuta all'improvviso un'ispirazione da goblin.",
  en_title = "Nogg's Ring Redo",
  en_obj = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar.",
}
T[2951] = {
  title = "The Sparklematic 5200!",
  desc = "Fra gli gnomi che resistono alla follia fuori dalla stanza, questo marchingegno spicca. Sul dispositivo una piccola targa dice \"Lo Sparklematic 5200\", e sotto c'è un testo:$B$B\"Sporco e incrostazioni rovinano i tuoi luccichini? Lo Sparklematic 5200 rimette il brillio nel brill-astico! Infila l'oggetto da pulire e metti tre monete d'argento nella fessura. Lascia lavorare lo Sparklematic 5200 per un momento e voila! I tuoi oggetti di valore usciranno puliti e luccicanti!\"",
  obj = "Inserisci un Oggetto Sudicio nello Sparklematic 5200, e assicurati di avere tre monete d'argento per avviare la macchina.",
  progress = "Sembrerebbe che il dispositivo voglia una specie di grime-encrusted object da pulire, più tre monete d'argento per mettere in moto il marchingegno. Con tutte e due le cose, lo Sparklematic 5200 dovrebbe funzionare...",
  reward = "Metti l'oggetto sudicio e tre monete d'argento nello Sparklematic 5200. La macchina prende vita di colpo e cerca, quasi freneticamente, di togliere il sudiciume dall'oggetto sconosciuto. Dal suo cuore rimbombano rumori di macinazione forti e violenti. Il telaio di metallo della bestia scricchiola e geme, mentre sbanda da una parte all'altra...",
  en_title = "The Sparklematic 5200!",
  en_obj = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
}
T[2952] = {
  title = "The Sparklematic 5200!",
  reward = "Veloce com'era partito, lo Sparklematic 5200 si ferma all'improvviso. Si sente un semplice \"ding\" e la bocca della macchina si apre a spirale verso l'alto. Dentro c'è una scatoletta chiusa da un fiocchetto: a quanto pare, dopo aver tolto il sudiciume, la macchina incarta l'oggetto. Anche se non avesse funzionato, almeno adesso l'oggetto sta in una bella scatola.$B$BBeh, per scoprire se l'ha pulito o no, un modo c'è...",
  en_title = "The Sparklematic 5200!",
}
T[2953] = {
  title = "Altra Azione Sparklematic",
  progress = "The Sparklematic 5200 è vuoto, e aspetta un grime-encrusted object da pulire e tre monete d'argento per partire!",
  reward = "The Sparklematic 5200 prende vita e sbanda avanti e indietro. Dentro, il detergente gnomesco della macchina polverizza l'indifeso sudiciume che incrostava l'oggetto inserito.$B$BThe Sparklematic 5200 si ferma, e lo annuncia un familiare \"ding!\" Il vano degli oggetti si apre a spirale e mostra una neatly wrapped box.",
  en_title = "More Sparklematic Action",
}
T[2954] = {
  title = "La Stone Watcher",
  desc = "\"Saluti — sono un guardiano dell'accesso. Se non hai già integrato le Tavole di Uldum nel tuo set di dischi, non ti permetterò di entrare nel complesso di Uldum.\"$B$BDev'essere questa la reazione che si sperava di ottenere mandandoti nel deserto di Tanaris con i dischi di platino: la comparsa dello Stone Watcher of Norgannon. Come da istruzioni, prima di proseguire dovrai scoprire la storia della Stone Watcher.",
  obj = "Scopri lo scopo dello Stone Watcher of Norgannon, poi interagisci con l'Uldum Pedestal nel deserto di Tanaris.",
  progress = "Prima di proseguire bisogna scoprire lo scopo della stone watcher...",
  reward = "La voce della stone watcher risuona di potere e autorità:$B$B\"Quando accederai al piedistallo, riavrai i dischi. Una volta ottenute le Tavole di Uldum e incorporate nel tuo set di dischi, potrai entrare nel complesso.\"",
}
T[2962] = {
  title = "L'Unica Cura È Altra Roba Verde Brillante",
  desc = "Il tuo campione non solo era poco, ma anche impuro.$B$BCi serve altra roba verde brillante. I trogg, evidentemente, non sono abbastanza irradiati per le nostre esigenze. Dovrai scendere a Gnomeregan e riportarmi un po' di scorie radioattive, dritte dalla fonte. Parlo delle irradiated slimes, delle creature in agguato e degli orrori, contaminati anche loro. Ti avverto, queste scorie sono difficili da conservare. Potrebbero servirti diversi tentativi con la fiala prima di raccogliere un campione adatto.",
  obj = "Vai a Gnomeregan e riporta l'High Potency Radioactive Fallout. Attenzione, le scorie sono instabili e si degradano piuttosto in fretta.$B$BA lavoro finito, Ozzie vorrà anche la tua Heavy Leaden Collection Phial.",
  progress = "Mmh, non brilli. È un buon segno.",
  reward = "<Ozzie ti esamina.> Notevole, hai ancora tutti gli arti al loro posto. Ora vediamo cosa sa fare questa roba!",
  en_title = "The Only Cure is More Green Glow",
  en_obj = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.$B$BOzzie will also require your Heavy Leaden Collection Phial when the task is complete.$B",
}
T[2963] = {
  title = "Presagi di Uldum",
  desc = "Ti saluto di nuovo, $N! Con la tua scoperta a Uldaman hai messo in fermento l'Explorers' League, che sta lavorando per svelare i segreti dei miniature platinum discs che hai trovato. Arrivi qui nella Sala proprio al momento giusto, così posso dirti che forse siamo sulla buona strada!$B$BHistorian Karnik ha trovato alcuni indizi importanti sulle vere origini della Valley of the Watchers, nel deserto di Tanaris, e vorrebbe parlarti al più presto!",
  obj = "Parla con Historian Karnik nell'Hall of Explorers a Ironforge.",
  reward = "Sono contento che non ti sia passata la voglia di esplorare, $N! Con il tuo talento naturale e il tuo fegato potremmo svelare segreti che non avremmo mai creduto possibili!$B$BThe Discs of Norgannon di Uldaman erano un immenso deposito di informazioni, e ti hanno permesso di accedere solo agli strati superiori, per così dire, di quello che custodivano. Si dice che i Creatori avessero altri depositi sparsi per Azeroth. Il che ci porta a Uldum...",
}
T[2964] = {
  title = "Un Compito Futuro",
  desc = "Bene, $N... per ora, a quanto pare, siamo finiti in un vicolo cieco. Sappiamo cosa ci serve — le Tavole di Uldum — ma non abbiamo idea di dove possano essere. Ci vorranno parecchie ricerche per mettere a punto un piano d'attacco solido. Qualche idea su dove cominciare a cercare ce l'ho; spero proprio che presto ti chiederemo di partire a recuperarle.$B$BIl Gran Esploratore va informato, $N; e di sicuro vorrà anche ringraziarti di persona per aver aiutato ancora una volta la Lega.",
  obj = "Parla con High Explorer Magellas a Ironforge.",
  reward = "Siamo tutti d'accordo, allora — il piano d'attacco migliore è lasciare tutto in sospeso finché non riusciremo a restringere le zone dove potrebbero essere nascoste queste tavole. Fin qui ci hai portati tu, $N, e spero che sarai ancora tu a tornare sul campo per aprire Uldum a tutti noi!$B$BNel frattempo, lascia che ti dia questo compenso; dovrebbe coprire tutte le spese che hai sostenuto per aiutarci, più un piccolo extra. Torna presto a trovarci... Uldum ci chiama!",
}
T[2965] = {
  title = "Presagi di Uldum",
  desc = "Ah, $N, che fortuna che tu sia $Gtornato:tornata; da me. Le tue scoperte al sito di scavo di Uldaman hanno dato di certo a noi saggi molto di cui discutere. Ne parlavo proprio con una dei druidi, Nara Wildmane, quando ho capito che le avventure che ha vissuto in passato potrebbero contare molto per il prossimo passo.$B$BVorrei che le parlassi dei viaggi che ha fatto nella Valley of the Watchers, nel deserto di Tanaris. Ti aspetta sull'Elder Rise.",
  obj = "Parla con Nara Wildmane su Elder Rise, a Thunder Bluff.",
  reward = "Nel profondo del deserto di Tanaris c'è un luogo chiamato Valley of the Watchers. I dischi che hai recuperato... una volta tradotti, i loro glifi parlano di un posto di nome Uldum. Quasi tutti lo credono un mito.$B$BIo so che non è vero; Uldum esiste. Ci sono stata. Be'... fuori, almeno.$B$BIl punto è questo, $N: crediamo che i dischi e Uldum siano legati, e vogliamo che tu ci vada.",
  en_title = "Portents of Uldum",
  en_obj = "Speak with Nara Wildmane on the Elder Rise in Thunder Bluff.",
}
T[2966] = {
  title = "Vedere Cosa Succede",
  desc = "Sage Truthseeker e io vorremmo che portassi ai cancelli sigillati di Uldum i dischi in miniatura che hai trovato. Noi... non sappiamo bene cosa succederà quando lo farai.$B$BSembra rischioso, certo, e lo riconosciamo. Ma potrebbe anche non succedere niente. Magari i dischi andranno usati su qualcosa. Forse le porte si aprono se li hai con te. Sii $Gdisposto:disposta; a tentare di tutto, e $Gpronto:pronta; a tutto.$B$BScopri quello che puoi, poi torna da me. Avremo molto di cui discutere.",
  obj = "Porta i miniature platinum discs ai cancelli di Uldum, a Tanaris, e cerca indizi sul legame tra le due cose.",
  progress = "Dalla sabbia rovente spunta un piedistallo dall'aspetto familiare. Forse, se si trova qui, vuol dire qualcosa...",
  reward = "Appena tocchi il piedistallo, nello zaino i dischi in miniatura di Uldaman ronzano e brillano. Un formicolio familiare ti corre lungo le mani, mentre davanti ai cancelli di Uldum prende vita l'immagine di un'altra Stone Watcher.$B$B\"Saluti. Sono un guardiano dell'accesso. Ai dischi usati per l'accesso mancano i dischi d'ingresso corretti, le Piastre di Uldum. Si prega di integrare queste piastre nella struttura dei dischi e di ripetere la sequenza di accesso. Grazie.\"",
  en_title = "Seeing What Happens",
  en_obj = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.",
}
T[2967] = {
  title = "Ritorno a Thunder Bluff",
  desc = "Tocchi di nuovo il piedistallo; all'improvviso i dischi di platino ricompaiono nello zaino.$B$BHai appreso ciò che sapeva la stone watcher e hai riavuto i dischi: è ora di tornare a Thunder Bluff e raccontare a Nara Wildmane quello che hai scoperto.",
  obj = "Parla con Nara Wildmane a Thunder Bluff.",
  progress = "$GBentornato:Bentornata;, $N. Sei $Griuscito:riuscita; a sfruttare i dischi a tuo vantaggio, o è stato tutto inutile?",
  reward = "Ti mancavano alcuni dischi? Curioso: pare che quelli di Norgannon siano solo una parte della serie completa — come le chiavi di un mazzo, per così dire.$B$BSe troviamo le Tavole di Uldum, potremmo davvero entrare nel complesso di Uldum. Non so se esserne entusiasta o terrorizzata.$B$BForse dovremo rischiare tutto perché i segreti che la terra custodisce, quelli che ci distruggerebbero tutti, restino quello che sono — segreti.",
  en_title = "Return to Thunder Bluff",
  en_obj = "Speak with Nara Wildmane in Thunder Bluff.",
}
T[2968] = {
  title = "Un Compito Futuro",
  desc = "Bene, $N... purtroppo pare che siamo arrivati a un punto morto. Sappiamo cosa ci serve — le Tavole di Uldum — ma non abbiamo idea di dove possano essere. Faremo qualche ricerca, poi metteremo a punto un solido piano d'attacco. Ho un paio di idee su dove cominciare a cercare; spero proprio che presto ti chiederemo di tornare ad aiutarci a scoprire la verità.$B$BSage Truthseeker va informato, $N; di certo vorrà anche ringraziarti di persona per aver risposto ancora una volta alla chiamata.",
  obj = "Parla con Sage Truthseeker a Thunder Bluff.",
  reward = "Allora siamo tutti d'accordo — la cosa migliore è aspettare finché non potremo restringere la ricerca alle zone dove potrebbero essere nascoste le tavole. Ci hai portati fin qui, $N, e spero che toccherà a te tornare sul campo per affrontare i segreti di Uldum.$B$BNel frattempo, lascia che ti dia questo onorario; dovrebbe coprire le spese che hai sostenuto per aiutarci, e un piccolo extra. Torna presto a trovarci... Uldum ci chiama tutti, giovane.",
  en_title = "A Future Task",
  en_obj = "Speak with Sage Truthseeker in Thunder Bluff.",
}
T[2969] = {
  title = "Libertà per Tutte le Creature",
  desc = "$N, il lurido clan Grimtotem sta catturando faerie dragons. Cosa voglia farne, né io né Jer'kai ne abbiamo idea, ma di sicuro niente di buono.$B$BNon abbiamo la forza di farci strada combattendo fin dentro l'accampamento e liberare i draghi catturati... ma forse, con il tuo aiuto...$B$BSe sei $Gdisposto:disposta;, e hai degli amici forti, apri la gabbia con questa chiave e libera le creature, assicurandoti che riescano a fuggire vive. Io sarò al tuo fianco per tutto il tempo; Jer'kai resterà qui.",
  obj = "Usando la Bamboo Cage Key, libera gli Sprite Darters dal recinto nell'accampamento Grimtotem. Devono sopravvivere almeno 6 Sprite Darters e Kindal Moonweaver.$B$BHai 6 minuti prima che Kindal decida che è ora di ritirarsi e tu fallisca la quest.",
  progress = "Non possiamo lasciare che il clan Grimtotem distrugga queste splendide creature. Bisogna liberarle dalla prigionia!",
  reward = "Sia ringraziata Elune, $N! Sei una grande benedizione per noi e per i draghi che hai salvato. Io e Jer'kai, da sole, non saremmo mai riuscite ad aiutarli — il tuo intervento negli affari dei Grimtotem sarà ricordato.$B$BOra va' a parlare con Jer'kai... io devo prepararmi per la nostra rappresaglia. Che i faerie dragons siano liberi non vuol dire che lo resteranno. Adesso io e Jer'kai passeremo all'offensiva.",
}
T[2970] = {
  title = "Dispensare Giustizia",
  desc = "Come ti ha già detto Kindal, ora noi due attaccheremo i Grimtotem. Insieme dovremmo riuscire ancora a far fuori qualcuno dei tauren senza rischiare troppo, ma un aiuto ci farebbe piacere, se sei $Gdisposto:disposta; e in grado.$B$BL'accampamento qui sotto l'hai visto, ma ce ne sono altri a est. Usa le tattiche che preferisci e infliggi ai tauren più danni che puoi. Ci ritroveremo qui quando avranno sentito il morso delle frecce di Kindal e delle tue armi.",
  obj = "Uccidi 12 Grimtotem Naturalists, 10 Grimtotem Raiders e 6 Grimtotem Shamans, poi torna da Jer'kai Moonweaver a Feralas.",
  progress = "Kindal ha bisogno di tempo per prepararsi, ma abbiamo già fatto decine di vittime. Il clan Grimtotem sa bene che siamo in zona: ci cercano come vipere.$B$BFaranno qualsiasi cosa per staccarci la testa dal corpo. Faresti bene a stare $Gattento:attenta;... ora che ti sei $Gintromesso:intromessa;, verranno a cercare anche te.",
  reward = "Su di te Kindal aveva ragione, $N — ci sai proprio fare. Come $Gavventuriero:avventuriera; sei più $Gesperto:esperta; di noi due, e per questo ti ringraziamo.$B$BIl clan Grimtotem è molto più ostile della maggior parte dei tauren... chissà se i loro simili disapprovano quello che fanno. Non mi sorprenderebbe. Come probabilmente sai, molte razze di Azeroth sono imparentate con stirpi meno benevole.$B$BMa di questo parleremo un altro giorno.",
}
T[2972] = {
  title = "Dispensare Giustizia",
  desc = "Qui fuori, nelle terre selvagge, io e Kindal abbiamo pochi mezzi per ricompensarti del tuo aiuto, ma non vogliamo che tu ti senta $Gpoco apprezzato:poco apprezzata;. Prendi il mio anello con sigillo. Se mai ti trovassi fra i rami di Teldrassil, va' al Tempio della Luna, nel cuore di Darnassus, dove troverai la mia High Priestess Tyrande Whisperwind. L'anello le farà sapere che stiamo bene e darà credito al tuo racconto.$B$BGrazie da tutte e due, $N.",
  obj = "Porta il Jer'kai's Signet Ring a High Priestess Tyrande Whisperwind a Darnassus.",
  progress = "Salve, $Gfigliolo:figliola;. Ci fa piacere vedere qui al tempio avventurieri più potenti. Se hai tempo, ti andrebbe di raccontare una storia o due ai più giovani? So che a molti di loro la tua saggezza farebbe bene.$B$BScusami, che scortese che sono. Sei $Gvenuto:venuta; al Tempio a cercare il nostro aiuto, e io ti importuno. Perdonami, ti prego. Dimmi, cosa possono fare per te i servitori della Luce?",
  reward = "È una storia straordinaria, $N. Ci fa piacere che tu abbia aiutato non solo la stirpe dei draghi, ma anche una delle nostre sacerdotesse. Jer'kai ha fatto bene a mandarti da me. Farò in modo che riabbia l'anello — ho degli esploratori che fra poco partiranno verso Feralas, e durante la missione avranno una cosa in più su cui indagare.$B$BGrazie ancora e, ti prego, finché sei qui fa' come se fossi a casa tua.",
}
T[2973] = {
  title = "Lo Splendore di un Nuovo Mantello",
  desc = "$GBen trovato:Ben trovata;, $C. Sono sceso fin qui a Feralas con i miei compagni, per una missione che ci hanno affidato i nostri signori di Orgrimmar.$B$BA Korrin, la mia compagna di vita, piacciono molto i vestiti nuovi, così voglio farle un mantello nuovo ornato con le ali dei faerie dragons, sottili come veli. Mi aiuteresti? Gli Sprite darters che cerco, quelli dalle ali splendide, stanno a ovest di Camp Mojache.",
  obj = "Porta 10 Iridescent Sprite Darter Wings a Krueg Skullsplitter a Camp Mojache.",
  progress = "Se li provochi, gli sprite darters possono essere bestiole pericolose: fai attenzione quando ci hai a che fare, $C. E guardati ancora di più dagli elfi della notte da queste parti, perché di solito quegli sciocchi seccatori si rintanano anche nelle foreste.$B$BQuando avrai raccolto abbastanza ali fammelo sapere, e ti ricompenserò a dovere!",
  reward = "Splendido, $C! Queste andranno benissimo. Ce n'è abbastanza per il mantello di Korrin, e forse ne avanza pure! Grazie.$B$BIl viaggio non è stato troppo pericoloso, spero? Feralas è una zona che non perdona, ma si vede che te la sei cavata piuttosto bene.$B$BGrazie ancora, $C.",
  en_title = "A New Cloak's Sheen",
  en_obj = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.",
}
T[2974] = {
  title = "Una Cupa Scoperta",
  desc = "Cosa!? Hai incontrato dei tauren da queste parti? Stai scherzando! Che aspetto avevano!?$B$BIl clan Grimtotem! Ne hai trovato qualcuno? Belgrom, uno dei nostri signori, si interessa alla loro specie... ha perfino messo una taglia su di loro.$B$BDevi tornare là, $C. Torna là e portami le loro corna... a mucchi, se ci riesci. I Grimtotem non vanno presi alla leggera, né sottovalutati. Torna là e uccidili: fa' che i fiumi di Feralas scorrano rossi del loro sangue oscuro.",
  obj = "Porta 20 Grimtotem Horns a Krueg Skullsplitter a Camp Mojache.",
  progress = "Prendi sul serio le mie parole, $C: il clan Grimtotem è malvagio. Se hai scoperto dove si trovano, tocca a te tornare là e sferrare il primo colpo contro il loro clan... prima che vengano da noi a radere al suolo i nostri villaggi o a saccheggiare le nostre terre.",
  reward = "Queste sono buone corna, $C. Ben fatto. Le tengo io, e appena torneremo a Orgrimmar lo dirò a Belgrom. Ormai mi hai aiutato due volte, e per questo hai la mia stima. Forse un giorno potrò essere io ad aiutarti! Buona fortuna.",
  en_title = "A Grim Discovery",
  en_obj = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.",
}
T[2975] = {
  title = "Gli Ogres di Feralas",
  desc = "Da queste parti non si può non vedere cosa sta facendo la tribù dei Gordunni Ogre. Guardati intorno, $N: basta la loro presenza a sfregiare questa terra. Dobbiamo ricacciarli indietro prima che si allarghino ancora a Feralas.$B$BSegui il fiume verso nord e arriverai al loro avamposto. Riduci il loro numero, $N: dobbiamo fargli capire che qui quelli come loro non sono graditi.",
  obj = "Rok Orhan, a Camp Mojache, vuole che tu uccida 10 Gordunni Ogres, 10 Gordunni Ogre-Magi e 5 Gordunni Brutes.",
  progress = "Allora, $N, ti muovi? O è troppo difficile quello che ti ho chiesto?",
  reward = "Ottimo, $N. Col tempo questa terra guarirà: non dobbiamo arrenderci.",
  en_title = "The Ogres of Feralas",
  en_obj = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Ogres, 10 Gordunni Ogre-Magi, and 5 Gordunni Brutes.",
}
T[2976] = {
  title = "Una Cupa Scoperta",
  desc = "Cosa?!$B$BAh, allora ho parlato davvero di una taglia, eh? Be', così imparo ad aprire bocca, no?$B$BIl lavoro l'hai fatto tu, quindi immagino sia giusto che la ricompensa più grande vada a te. Prendi le corna, te le faccio mettere in una cassa. Cerca Belgrom Rockmaul nella Valley of Honor: vorrà sapere cosa hai visto e ti ricompenserà per il duro lavoro.$B$BStammi bene, $C, e grazie ancora di tutto quello che hai fatto.",
  obj = "Porta la Crate of Grimtotem Horns a Belgrom Rockmaul a Orgrimmar.",
  progress = "Sbrigati, $C, oggi ho parecchio da fare.",
  reward = "I Grimtotem!? Interessante. Dici che li hai incontrati mentre cacciavi a Feralas? Davvero?$B$BI miei colleghi vorranno sentire queste notizie, $C. Dimmi qualcosa di più, e intanto ti conto le monete.$B$BE prima che tu vada, voglio ringraziarti per le informazioni che mi hai dato oggi.",
  en_title = "A Grim Discovery",
  en_obj = "Bring the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar.",
}
T[2977] = {
  title = "Ritorno a Ironforge",
  desc = "Usi di nuovo il piedistallo; all'improvviso i dischi di platino ricompaiono nello zaino.$B$BOra che sai quello che sapeva la stone watcher e hai di nuovo con te i dischi, è il momento di tornare a Ironforge e raccontare all'Explorers' League cosa hai scoperto.",
  obj = "Parla con Historian Karnik a Ironforge.",
  progress = "$GBentornato:Bentornata;, $N. Sei $Griuscito:riuscita; a sfruttare i dischi, o alla fine è stato un buco nell'acqua?",
  reward = "Ti mancavano alcuni dischi? Curiosamente, a quanto pare i dischi di Norgannon sono solo una parte del set completo — come le chiavi di un portachiavi, per così dire.$B$BSe riuscissimo a trovare le Tavole di Uldum, potremmo entrare proprio dentro il complesso di Uldum! Immagina di esplorare davvero il posto dove lavoravano i Creatori, senza doverti portare dietro un'enorme pala!$B$BNon che ci sia niente di male nelle pale... o nello scavare...",
}
T[2978] = {
  title = "La Gordunni Scroll",
  desc = "Raccogli la pergamena sporca e ti accorgi che sembra raffigurare una specie di riunione, o forse di cerimonia. A Rok Orhan interesserebbero la pergamena e quello che potrebbe voler dire per i Gordunni.",
  obj = "Porta la Gordunni Scroll a Rok Orhan a Camp Mojache.",
  progress = "E questa cos'è?",
  reward = "Questa pergamena... L'hai trovata al Gordunni Outpost?",
  en_title = "The Gordunni Scroll",
  en_obj = "Bring the Gordunni Scroll to Rok Orhan in Camp Mojache.",
}
T[2979] = {
  title = "Cerimonia Oscura",
  desc = "Sembrano i piani di una specie di cerimonia oscura, $N. Per quel che riesco a capire, a celebrare il rituale sono i signori maghi dei Gordunni.$B$BTrovane uno e prendigli un globo.$B$BNel globo di un mago c'è un grande potere: ci aiuterà a saperne di più su questa cerimonia e sulla magia dei Gordunni.",
  obj = "Rok Orhan a Camp Mojache vuole che tu trovi un Gordunni Orb.",
  progress = "$N, dobbiamo capire meglio perché i Gordunni si trovano qui.",
  reward = "Questo globo ci dirà altro sui Gordunni... e con quello che sapremo prepareremo la loro disfatta, $N.",
}
T[2980] = {
  title = "Gli Ogres di Feralas",
  desc = "Hai dimostrato di essere $Gun vero:una vera; combattente, e ora confido che tu abbia il coraggio di portare avanti il lavoro.$B$BVa' nell'High Wilderness, a sud-ovest di qui. Su quelle terre, che un tempo erano degli elfi della notte, ci sono alcune costruzioni abbandonate e distrutte. Cerca le rovine: quando vedrai gli alberi avvizziti e il terreno profanato, avrai trovato i Gordunni. Ricacciali indietro.$B$BQuesti ogres sono molto più forti di quelli che hai affrontato finora, $N. Sta' $Gattento:attenta;.",
  obj = "Rok Orhan, a Camp Mojache, vuole che tu uccida 10 Gordunni Shaman, 10 Gordunni Warlocks e 5 Gordunni Maulers.",
  progress = "Allora, $N, le hai trovate le rovine?",
  reward = "Hai dimostrato di essere $Gun alleato fidato e affidabile:un'alleata fidata e affidabile;, $N.",
  en_title = "The Ogres of Feralas",
  en_obj = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Shaman, 10 Gordunni Warlocks, and 5 Gordunni Maulers.",
}
T[2981] = {
  title = "Una Minaccia a Feralas",
  desc = "Per $Gun:una; $C $Gesperto:esperta; che voglia mettersi alla prova, non c'è posto migliore di Feralas. Lì domina una tribù di ogres chiamata Gordunni, la forza militare più potente della zona, e sono sempre di più. Vanno fermati prima che diventino una minaccia per la nostra presenza a Feralas.$B$BVa' da Rok Orhan, una guerriera che conosco di fama: vive a Camp Mojache, a Feralas. Quando arriverai, ti spiegherà meglio la situazione.",
  obj = "Belgrom Rockmaul vuole che tu parli con Rok Orhan a Camp Mojache.",
  reward = "Così ti manda Belgrom. Arrivi giusto in tempo, $R.$B$BTi spiego la situazione, poi deciderai tu se sei all'altezza della sfida... Ma se ti manda Belgrom, sul tuo coraggio non ho dubbi.",
}
T[2982] = {
  title = "L'High Wilderness",
  desc = "Io e Troyas stiamo esplorando le rovine che ricoprono le foreste di Feralas, anche se è pericoloso.$B$BUltimamente però Troyas va da solo nell'High Wilderness, e sono davvero in pensiero per lui. Quella zona è finita in mano ai Gordunni Ogres, che non vedono di buon occhio chiunque entri nel loro territorio.$B$BSperavo che fossi $Gdisposto:disposta; ad andare alle rovine a sud-est a eliminare qualche ogres. Rendile un po' più sicure per il mio Troyas, e te ne sarò profondamente grata.",
  obj = "Angelas Moonbreeze vuole che tu uccida 8 Gordunni Warlocks, 8 Gordunni Shaman e 8 Gordunni Brutes.",
  progress = "Fai attenzione ai Gordunni, $N. Sembra che la loro magia devasti la terra stessa su cui stanno.",
  reward = "Ti sono molto grata per quello che hai fatto per me.$B$BE ora, ti prego, non dire una parola a Troyas di questa faccenda...",
  en_title = "The High Wilderness",
  en_obj = "Angelas Moonbreeze wants you to kill 8 Gordunni Warlocks, 8 Gordunni Shaman, and 8 Gordunni Brutes.",
}
T[2983] = {
  title = "Il Richiamo del Fuoco",
  desc = "È da un po' che non sei più $Gstato messo:stata messa; alla prova, $N. Finora nei tuoi studi sei $Gstato:stata; paziente, ma adesso devi conoscere poteri più grandi... devi conoscere il vero potere. L'elemento del fuoco è tuo, se sei $Gpronto:pronta; a pagarne il prezzo.$B$BCerca Kranal Fiss nelle Barrens. Vive in una piccola casa a nord del Crossroads, ma fa' attenzione: se arrivi alle maledette terre degli elfi della notte, sei $Gandato:andata; decisamente troppo lontano.",
  obj = "Trova Kranal Fiss nelle Barrens.",
  reward = "Hmmm, è stato Swart a mandarti da me, eh?$B$BBene, allora. Swart è sempre stato uno di cui fidarsi, quindi vuol dire che sei $Gpronto:pronta; per il prossimo sapta — il sapta del fuoco.$B$BTe lo leggo già negli occhi, quell'ardore, quel desiderio. Hai assaggiato il potere, e adesso sei $Gpronto:pronta; a prenderne ancora. Pazienza, $N. Ricorda cosa ti ha insegnato la terra. Il potere e la distruzione arriveranno senza fatica, ma tu dovrai sapere lo stesso quando fermare la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[2984] = {
  title = "Il Richiamo del Fuoco",
  desc = "Da molto tempo non sei più $Gstato messo:stata messa; alla prova, $N. Finora hai studiato con pazienza, ma è giunto il momento di imparare di più. Il momento di conoscere la distruzione... e il caos. Puoi comprendere l'elemento del fuoco, se sei $Gpronto:pronta; a pagarne il prezzo.$B$BCerca Kranal Fiss nelle Barrens. Vive in una piccola casa a nord del Crossroads, ma fa' attenzione: se arrivi alle terre degli elfi della notte, sei $Gandato:andata; troppo lontano.",
  obj = "Trova Kranal Fiss nelle Barrens.",
  reward = "Hmmm, è stato Narm a mandarti da me, eh?$B$BBene, allora. Narm è sempre stato uno di cui fidarsi, quindi vuol dire che sei $Gpronto:pronta; per il prossimo sapta — il sapta del fuoco.$B$BTe lo leggo già negli occhi, quell'ardore, quel desiderio. Hai assaggiato il potere, e adesso sei $Gpronto:pronta; a prenderne ancora. Pazienza, $N. Ricorda cosa ti ha insegnato la terra. Il potere e la distruzione arriveranno senza fatica, ma tu dovrai sapere lo stesso quando fermare la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[2985] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Sembri $Gpronto:pronta; per la prossima prova, $N. Negli studi sei $Gstato:stata; paziente, ma ora è tempo che tu impari di più: è tempo che tu impari la purezza dell'acqua.$B$BCerca Islen Waterseer nelle Barrens. Sta sulla costa orientale, a sud del Southfury River e di Ratchet: la troverai lì, nella sua capanna da pesca. Buona fortuna, $N.",
  obj = "Trova Islen Waterseer nelle Barrens.",
  reward = "Il vento ti corre incontro dall'orizzonte; la terra ti regge salda sotto i piedi; e il fuoco ti ha già scaldato lo spirito — direi che è ora che tu impari la purezza dell'acqua.$B$BIl cammino ti ha portato fin qui, e lo spirito ti darà la forza di spingerti ancora più avanti. Ma il primo passo tocca a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[2986] = {
  title = "Il Richiamo dell'Acqua",
  desc = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai studiato con pazienza, ma ora è tempo che tu impari di più: è tempo che tu impari la purezza dell'acqua.$B$BCerca Islen Waterseer nelle Barrens. Sta sulla costa orientale, a sud del Southfury River e di Ratchet: la troverai lì, nella sua capanna da pesca. Buona fortuna, $N.",
  obj = "Trova Islen Waterseer nelle Barrens.",
  reward = "Il vento ti corre incontro dall'orizzonte; la terra ti regge salda sotto i piedi; e il fuoco ti ha già scaldato lo spirito — direi che è ora che tu impari la purezza dell'acqua.$B$BIl cammino ti ha portato fin qui, e lo spirito ti darà la forza di spingerti ancora più avanti. Ma il primo passo tocca a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[2987] = {
  title = "Gordunni Cobalt",
  desc = "Sono appena arrivato qui a Feralas, e ho sentito dire che i Gordunni Ogres che vivono in queste terre selvagge hanno dei minerali interessanti. Chissà cosa tramano, ma di sicuro di quella roba sono gelosi! Non la lasciano in giro, no: la sotterrano, così quelli come me non ci mettono le mani sopra.$B$BSe sei $Gdisposto:disposta;, ti do la mia pala. Va' al Gordunni Outpost, a nord di qui, e tirami fuori un po' di cobalto dei Gordunni. Cerca il bagliore blu, poi comincia a scavare!",
  obj = "Orwin Gizzmick a Camp Mojache vuole 12 campioni di Gordunni Cobalt.",
  progress = "Su, va' lassù e mettiti a scavare!$B$BHo giri da fare e gente da vedere — il tempo è denaro!",
  reward = "Perfetto! Me li porterò dietro per il resto del viaggio, $N. Sono sicuro che troverò qualcuno disposto a pagare fior di quattrini per questo cobalto.$B$BTieni, prendi questo per il disturbo.",
  en_title = "Gordunni Cobalt",
  en_obj = "Orwin Gizzmick in Camp Mojache wants 12 samples of Gordunni Cobalt.",
}
T[2988] = {
  title = "Gabbie dei Witherbark",
  desc = "Il figlio del nostro grifone più possente è sparito! Sharpbeak, l'erede di Swiftwing, si è perso qualche giorno fa mentre era a caccia con i genitori, e crediamo che se lo siano preso i troll.$B$BDevi aiutarci! Cerca nelle gabbie dei due villaggi di Witherbark troll e guarda se c'è Sharpbeak.",
  obj = "Controlla le gabbie nei due villaggi Witherbark, poi torna da Gryphon Master Talonaxe.",
  progress = "Hai guardato nelle gabbie, $N? Dobbiamo trovare Sharpbeak!",
  reward = "Sharpbeak non era nei villaggi? Mm... brutte notizie. Quel grifone è destinato a guidare la prossima generazione. Se lo perdiamo, la forza e lo spirito della nostra flotta ne soffriranno moltissimo.",
}
T[2989] = {
  title = "The Altar of Zul",
  desc = "Sharpbeak non stava con i Witherbark trolls. Forse l'hanno preso i troll Vilebranch. Va' all'Altar of Zul, sul confine occidentale del territorio dei Vilebranch, e cerca il piccolo grifone.",
  obj = "Controlla la cima di Altar of Zul, poi torna da Gryphon Master Talonaxe.",
  progress = "Sbrigati, $N! Se Sharpbeak ce l'hanno i troll Vilebranch, chissà cosa potrebbero fargli!",
  reward = "Sharpbeak non c'era? È una brutta notizia, ma anche una buona...$B$BMeno male che non era all'Altar of Zul, perché i troll Vilebranch sono famosi per i loro sacrifici.$B$BGrazie di tutto l'aiuto che mi hai dato, ma temo di doverti affidare un compito ancora più grande.",
}
T[2990] = {
  title = "Thadius Grimshade",
  desc = "Porta questa piuma a Thadius Grimshade, l'indovino. Anni fa ha lasciato Aerie Peak per andare dietro a conoscenze più oscure, ma in fondo al cuore è ancora un Wildhammer!$B$BE magari i suoi talenti possono aiutarci a trovare Sharpbeak.$B$BQuesta piuma viene dal nido dove dorme il piccolo grifone. Se la consegni a Thadius, con un po' di fortuna potrà trovare Sharpbeak con le sue magie divinatorie.$B$BBuona fortuna, $N. Thadius lo trovi nelle Blasted Lands, nella torre dei maghi di Nethergarde Keep.",
  obj = "Porta la Sharpbeak's Feather a Thadius Grimshade nelle Blasted Lands.",
  progress = "$N, sei qui per portarmi un dono?",
  reward = "Ah, sì. Questa piuma è di un grifone eccellente, destinato a grandi cose... se riuscirà ad arrivare all'età adulta sano e salvo.$B$BVuoi trovarlo? Allora ascolta bene, $Gcoraggioso:coraggiosa; $C...",
}
T[2991] = {
  title = "Nekrum's Medallion",
  desc = "Scoprirò dov'è il tuo grifone, ma prima devi fare una cosa per me. A Zul'Farrak c'è un troll, Nekrum Gutchewer, con un medaglione che vorrei tanto studiare. Portami quel Medaglione e userò i miei poteri per trovare Sharpbeak.$B$BZul'Farrak sta oltre l'oceano, a ovest, nel deserto di Tanaris.",
  obj = "Porta il Nekrum's Medallion a Thadius Grimshade nelle Blasted Lands.",
  progress = "Ce l'hai il Nekrum's Medallion, $N? Nasconde poteri che non vedo l'ora di scoprire.",
  reward = "Ah, il medaglione di Nekrum. Dicono che abbia dato al troll una vita innaturalmente lunga, ma non senza un prezzo. Spero di trovare il modo di sfruttarne il potere senza subirne gli... spiacevoli effetti collaterali.$B$BMi hai reso un servizio, $N. Ora tocca a me mantenere la mia parte del patto.",
  en_title = "Nekrum's Medallion",
  en_obj = "Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.",
}
T[2992] = {
  title = "La Divinazione",
  desc = "Fammi spazio, devo eseguire un rituale di divinazione. Troverò il legame fra la piuma che mi hai portato e il suo proprietario, e lo seguirò fino a Sharpbeak in persona.$B$BCioè... se tutto va secondo i piani. Altrimenti... faresti meglio a chiudere gli occhi.",
  obj = "Aspetta che Grimshade esegua il rituale di divinazione.",
  reward = "Il rituale è riuscito. Ho visto Sharpbeak e posso dirti come trovarlo.",
}
T[2993] = {
  title = "Ritorno nelle Hinterlands",
  desc = "Sharpbeak è chiuso in una gabbia, in alto su una rupe in cima a Jintha'Alor, nelle Hinterlands. La chiave della gabbia ce l'ha la somma sacerdotessa dei troll Vilebranch, Vile Priestess Hexx.$B$BEcco. La mia parte l'ho fatta. Che la fortuna ti accompagni nella tua impresa, $N.",
  obj = "Parla con Gryphon Master Talonaxe.",
  reward = "Hai parlato con Grimshade? Che ti ha detto?$B$B...Cosa? Sharpbeak ce l'hanno i troll Vilebranch? È intollerabile! Dobbiamo radunare dei combattenti e riprendercelo!",
}
T[2994] = {
  title = "Salvare Sharpbeak",
  desc = "Dobbiamo salvare Sharpbeak!$B$BFatti strada combattendo fino alla cima di Jintha'Alor, nel cuore del territorio dei Vilebranch, prendi alla perfida Priestess Hexx la chiave della gabbia di Sharpbeak, poi trova Sharpbeak e mettilo in salvo!",
  obj = "Raggiungi combattendo la cima di Jintha'Alor, uccidi Vile Priestess Hexx per avere la chiave della gabbia di Sharpbeak e salva Sharpbeak.",
  progress = "Salva Sharpbeak!",
  reward = "Swiftwing e Keenclaw sono tornati poco fa con il loro piccolo, e gli stanno addosso come due genitori alle prime armi. A vederli di nuovo insieme, vengono gli occhi lucidi perfino a questo vecchio nano...$B$BNon potremo mai ripagarti abbastanza per quello che hai fatto, $N. I grifoni di Aerie Peak, e i loro cavalieri, canteranno il tuo nome per molto, molto tempo.",
}
T[2995] = {
  title = "Linee di Comunicazione",
  desc = "La Quel'Danil Lodge è un centro di comunicazione per gli alti elfi dell'Hinterlands. I loro ambasciatori si danno da fare per stringere rapporti con altre razze, e condividono con loro ciò che sanno dei Witherbark trolls che vivono nella parte meridionale dell'Hinterlands. Tutti i documenti di queste comunicazioni sono custoditi nella loggia.$B$BNon ci serve che gli Highvale si trovino degli alleati, $N.$B$BDistruggi i documenti degli Highvale: le loro linee di comunicazione vanno bruciate... letteralmente.",
  obj = "Oran Snakewrithe a Undercity vuole che tu vada nell'Hinterlands e bruci gli Highvale Records, l'Highvale Report e gli Highvale Notes.",
  progress = "La chiave è tenere isolati gli elfi Highvale. Hai trovato la loggia?",
  reward = "Perfetto, $N. Mentre gli Highvale cercano di recuperare le informazioni perse, noi potremo isolare le loro linee ancora di più...",
}
T[2996] = {
  title = "In Cerca di Strahad",
  desc = "Finora ti ho insegnato io delle abilità, ma è ora che sia un altro a istruirti. Si chiama Strahad e si trova a Ratchet. È umano, ma non farti ingannare: non è debole. Sarà anche piccolo, ma è potente, e può insegnarti evocazioni più forti — sento che sei $Gpronto:pronta;. Va' da lui, ora. Lo trovi a Ratchet... sopra la città portuale, vicino alla sua torre.",
  obj = "Parla con Strahad Farsan a Ratchet.",
  reward = "Giornata movimentata a Ratchet, vero? Quanto mi piace guardare una città portuale che fatica. Tanto mistero, tanta avventura... tanta ignoranza.$B$BVedo odio nei tuoi occhi, $N? Bene, ne faremo buon uso.",
  en_title = "Seeking Strahad",
  en_obj = "Speak to Strahad Farsan in Ratchet.",
}
T[2997] = {
  title = "Tome of Divinity",
  desc = "Salve, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Dun Morogh, ma quando hai tempo dovresti salire fino a Ironforge e parlare con una delle persone più rispettate fra i nostri: Tiza Battleforge. I paladini più giovani vanno da lei quando arriva il momento di imparare di più sulla Luce e su quello che ci si aspetta da loro.$B$BLa trovi al piano di sopra, nell'Hall of Mysteries. Se non ci sei mai $Gstato:stata;, è nel Mystic Ward. Buona fortuna, $N.",
  obj = "Parla con Tiza Battleforge a Ironforge.",
  reward = "$GBen trovato:Ben trovata;, $N. Spero che la Luce ti mostri la vera via e ti protegga dal male.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[2998] = {
  title = "Tome of Divinity",
  desc = "Salute, $Gfratello:sorella;. Duthorian Rall, uno dei nostri paladini più influenti, di recente ha parlato di te. Gli ho sentito dire che era ora di metterti un po' alla prova... e lodare molto come te la sei cavata finora.$B$BAl posto tuo, appena hai un momento, andrei a Stormwind a parlargli. Lo troverai di sicuro nella Cathedral of Light — passa lì quasi tutto il tempo.",
  obj = "Parla con Duthorian Rall a Stormwind.",
  reward = "È bello qui a Stormwind, non è vero?$B$BA dire il vero, non saresti $Gpotuto:potuta; arrivare in un momento migliore, $N.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[2999] = {
  title = "Tome of Divinity",
  desc = "Ciao, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Dun Morogh, ma quando trovi un momento dovresti salire di sopra a parlare con Tiza Battleforge, una delle figure più rispettate fra noi. I paladini più giovani vanno da lei quando è ora di imparare di più sulla Luce e su quello che ci si aspetta da loro.",
  obj = "Parla con Tiza Battleforge a Ironforge",
  reward = "Ben $Gtrovato:trovata;, $N. Spero che la Luce ti indichi la vera via e ti tenga al riparo dal male.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge",
}
T[3000] = {
  title = "Tome of Divinity",
  desc = "Salve, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Azeroth, ma quando trovi il tempo dovresti tornare a Ironforge a parlare con una dei paladini più rispettati della tua patria: Tiza Battleforge. I giovani paladini nanici vanno da lei quando è ora di saperne di più sulla Luce e su quello che ci si aspetta da tutti noi.$B$BLa trovi al piano di sopra dell'Hall of Mysteries, nel Mystic Ward.",
  obj = "Parla con Tiza Battleforge a Ironforge.",
  reward = "Ti saluto e ti do il benvenuto, $N.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[3001] = {
  title = "In Cerca di Strahad",
  desc = "In passato ti ho insegnato alcune abilità, ma ora è tempo che sia un altro a istruirti. Si chiama Strahad e si trova a Ratchet. È un umano, ma non farti ingannare: non crederlo debole, né tuo nemico... almeno per ora. È potente, e merita rispetto. Può insegnarti le evocazioni superiori, e credo che tu sia $Gpronto:pronta;. Ora va' da lui.$B$BLo troverai a Ratchet... sopra la città portuale, accanto alla torre.",
  obj = "Trova Strahad Farsan a Ratchet.",
  reward = "C'è un gran daffare oggi a Ratchet, non trovi? Quanto mi piace guardare una città portuale all'opera. Tanto mistero, tanta avventura... tanta ignoranza.$B$BÈ odio quello che vedo nei tuoi occhi, $N? Bene, ne faremo buon uso.",
  en_title = "Seeking Strahad",
  en_obj = "Find Strahad Farsan in Ratchet.",
}
T[3002] = {
  title = "Il Gordunni Orb",
  desc = "Conosco bene il mio nemico, $N, ma sono una guerriera. Non saprei nemmeno da dove cominciare per dirti cosa può fare questo globo.$B$BSo che a Orgrimmar c'è un mago che saprà dirci qualcosa di più. Portaglielo.",
  obj = "Porta il Gordunni Orb a Uthel'nay in Darkbriar Lodge a Orgrimmar.",
  progress = "Che mi hai portato, $R?",
  reward = "Affascinante, $N...$B$BÈ un globo molto potente, ma pure molto pericoloso.",
}
T[3022] = {
  title = "Maneggiare con Cura",
  desc = "$N, vedo quanto desideri essere $Gdevoto:devota; alla mia nobile causa. Ma sì, certo che puoi fare qualcosa per me!$B$BPorta questa cassa di uova a Erelas Ambersky, un druido che se ne prende cura: le aiuta a schiudersi e poi addestra i giovani ippogrifi. Lo trovi a Teldrassil, in un piccolo villaggio a sud che si chiama Rut'theran.",
  obj = "Porta la Cassa Imballata con Cura a Erelas Ambersky, a Rut'theran Village.",
  progress = "Un'altra spedizione di Curgle, immagino?",
  reward = "Ti ringrazio dell'aiuto, $N. Senza di noi gli ippogrifi non potrebbero prosperare. Ah, ma questo lo capisci fin troppo bene, ne sono sicuro: sei $Gandato:andata; di persona a Feralas e hai visto la devastazione che i Gordunni hanno portato laggiù.$B$BBeh, come vedi qui ho molto da fare, quindi ti conviene rimetterti in cammino.$B$BGrazie ancora, $N.",
}
T[3042] = {
  title = "Troll Temper",
  desc = "Dalle arenarie i troll Sandfury di Zul'Farrak ricavano un agente per la tempra, e io posso usarlo per temprare quello che forgio, eccome se posso! Gli intenditori lo apprezzano molto, quindi se mi porti una buona scorta di sudore ti ricompenserò bene.$B$BZul'Farrak è a nord-ovest di Gadgetzan. Buona fortuna.",
  obj = "Porta 20 Fiale di Troll Temper a Trenton Lighthammer a Gadgetzan.",
  progress = "Allora, $N, il sudore me l'hai portato?",
  reward = "Ah, che ottimo sudore! E quanto ne hai portato! Mi ci vorranno giorni di lavoro per usarlo tutto!$B$BGrazie, $N. Accetta questo come compenso.",
  en_title = "Troll Temper",
  en_obj = "Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.",
}
T[3062] = {
  title = "Cuore Oscuro",
  desc = "Edana Hatetalon è la regina delle arpie Northspring che vivono fra le rovine a ovest. È il male puro: ho sentito dire che ha un cuore di cristallo. Non prova alcuna emozione, se non l'odio verso chiunque altro. Devi affrontare Edana e riportarmi il suo cuore oscuro.$B$BHo sentito parlare di un corno che le arpie portano con sé — se lo suoni presso le pietre Hatetalon, nella parte settentrionale delle rovine, richiamerai la regina.$B$BImmagina che sorpresa, quando a chiamarla non saranno i suoi simili, ma la sua morte.",
  obj = "Talo Thornhoof a Camp Mojache vuole il Cuore Oscuro di Edana Hatetalon.",
  progress = "Bisogna fermare l'odio che Edana diffonde per queste terre.",
  reward = "Ora so che Edana è morta davvero. Questo cuore lo terrò in ricordo di ciò che hai fatto qui per me, $N. Grazie.",
}
T[3063] = {
  title = "Vendetta sui Northspring",
  desc = "Ai miei tempi ero un cacciatore esperto, e non c'era creatura in giro che temessi. Finché...$B$BStavo affilando la lama nella foresta, dopo una dura battaglia, quando sono caduto in un'imboscata. Le arpie mi hanno circondato, e a malapena sono riuscito a trascinarmi in salvo.$B$BSento ancora l'eco delle loro grida...$B$BDa allora non sono più lo stesso. Ma l'odio mi ribolle dentro — dopo tutti questi anni, devo pareggiare i conti.$B$BLe arpie Northspring sono a ovest di qui. Vendicami, $N.",
  obj = "Talo Thornhoof vuole che tu uccida 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers e 4 Northspring Slayers.",
  progress = "Le arpie Northspring hanno ali nere come la notte: non perderle d'occhio, o spariranno nell'oscurità.",
  reward = "Grazie, $N. Hai dato pace alla mente di un vecchio tauren.",
}
T[3065] = {
  title = "Simple Tablet",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene dall'addestratore dei guerrieri, Frang. Vorrebbe scambiare due parole con te quando sarai $Gpronto:pronta;. Lo troverai fuori da The Den, riparato all'ombra.",
  obj = "Leggi la Simple Tablet e parla con Frang in Valley of Trials.",
  progress = "$GUn altro:Un'altra; $R a rinforzare le fila. A me va bene così.$B$BProbabilmente farai fatica a sollevare una buona arma come un'ascia, ma una lancia vale quanto qualunque altra.$B$B$GBenvenuto:Benvenuta; nella Valley of Trials.",
  reward = "È il posto adatto a te per proseguire l'addestramento nelle vie $Gdel:della; $C. Se hai domande, chiedi pure a chiunque qui intorno, e quando ti senti $Gpronto:pronta;, torna da me per allenarti. Ne so quanto qualunque $C della Valle e posso trasmetterti il mio sapere... a pagamento.",
  en_title = "Simple Tablet",
  en_obj = "Read the Simple Tablet and speak to Frang in the Valley of Trials.",
}
T[3082] = {
  title = "Etched Tablet",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene dall'addestratrice dei cacciatori, Jen'shan. Vorrebbe scambiare due parole con te quando sarai $Gpronto:pronta;.",
  obj = "Parla con Jen'shan in Valley of Trials.",
  progress = "Jen'shan vedere $Gun potente cacciatore:una potente cacciatrice; davanti a lei e gli spiriti approvare.$B$BLa via del cacciatore è uno dei nostri modi di vivere più vecchi. L'Orda venire da noi quando loro lottare solo per sopravvivere su Azeroth, e loro chiedere a noi di insegnare, di mostrare segreti di tante cose. Erano già forti: forti nelle vie degli sciamani; forti nelle vie dei guerrieri. Ma la via del cacciatore non essere la loro via... allora.",
  reward = "Ora noi insegniamo loro quelle cose, e loro ce ne insegnano altre. Noi diventiamo una razza sola... quasi. Noi essere alleati da tanto tempo ormai. Quindi tu ricordati di aiutarli. E Jen'shan ricordare di aiutare te.$B$BJen'shan insegnare a te le vie del cacciatore — insegnare bene. Tu mai dimenticare: i cacciatori essere molto rispettati dalla tribù. Tu avere una parte grande da fare nel futuro... tu mai dimenticare questo.$B$BQuando senti il bisogno, vieni da Jen'shan. Lei insegnare a te quanto può quando lei sentire che tu essere $Gpronto:pronta;.",
  en_title = "Etched Tablet",
  en_obj = "Speak to Jen'shan in the Valley of Trials.",
}
T[3083] = {
  title = "Encrypted Tablet",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene dall'addestratore dei ladri, Rwag. Vorrebbe scambiare due parole con te quando sarai $Gpronto:pronta;.",
  obj = "Leggi l'Encrypted Tablet e parla con Rwag in Valley of Trials.",
  progress = "$GBenvenuto:Benvenuta; nella Valley of Trials, $N. Se sei qui, vuol dire che hai ricevuto la mia tavoletta, quindi vengo subito al punto.$B$BSono Rwag e mi occupo di addestrare i furfanti, i ladri e i tagliaborse qui nella Valle. Se non sarai $Gpronto:pronta; per quello che ti aspetta, la Mano verrà a cercare me. Ma non preoccuparti: non controlleranno ogni tua mossa, anche se, qualora avessero bisogno dei tuoi talenti, faresti bene a collaborare.",
  reward = "Fino a quel momento, sarai sotto la mia guida. Ti insegnerò i trucchi del mestiere, come si suol dire. Quando ti senti $Gpreparato:preparata;, vieni da me e vedrò di proseguire il tuo addestramento. Nel frattempo, esercita le tue capacità e tienile affilate come un rasoio. Non si sa mai quando potrebbe servirti anche l'abilità più insignificante.",
  en_title = "Encrypted Tablet",
  en_obj = "Read the Encrypted Tablet and speak to Rwag in the Valley of Trials.",
}
T[3084] = {
  title = "Rune-Inscribed Tablet",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice degli sciamani, Shikrik. Vorrebbe parlarti quando sarai $Gpronto:pronta;.",
  obj = "Parla con Shikrik in Valley of Trials.",
  progress = "Ah, $Gbenvenuto:benvenuta;, $N. Sono lieta che tu sia $Garrivato:arrivata;. Con tutti gli allievi da istruire, le mie giornate si sono fatte lunghe e persino frenetiche, ma l'arrivo di $Guno:una; della tua stirpe mi dà grande soddisfazione — ricordo i tempi in cui ero io a imparare da uno dei vostri sciamani.",
  reward = "Come probabilmente sai, sono gli elementi a darci il potere. Fuoco, terra, acqua e aria — questi sono i nostri strumenti.$B$BLa nostra forza viene dagli spiriti degli antenati. Siamo noi le guide del nostro popolo. Ciò che Thrall è per l'Orda, noi lo saremo per i villaggi e le città che visiteremo. Si rivolgeranno a noi in cerca di saggezza e protezione. Per essere più $Gpreparato:preparata;, devi addestrarti spesso. Quando senti che il tuo potere è cresciuto, vieni da me e ti insegnerò quello che posso.",
  en_title = "Rune-Inscribed Tablet",
  en_obj = "Speak to Shikrik in the Valley of Trials.",
}
T[3085] = {
  title = "Hallowed Tablet",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei sacerdoti, Ken'jai. Vorrebbe parlarti quando sarai $Gpronto:pronta;.",
  obj = "Leggi l'Hallowed Tablet e parla con Ken'jai fuori da the Den in Valley of Trials.",
  progress = "Allora ce l'hai fatta... bene bene! Gli spiriti m'hanno detto che tu venire presto a trovare Ken'jai. Voglio essere uno dei primi a darti il benvenuto in Valley of Trials. Questo posto non essere tua casa a lungo, ma finché lo è, perché non ne approfitti al meglio.",
  reward = "Mettendoti alla prova, vedrai che comandi gli spiriti sempre meglio — li chiamerai per imprese via via più grandi...  ed è lì che entra in gioco il vecchio Ken'jai. Vieni a parlare col vecchio Ken'jai quando ti senti $Gpronto:pronta;. Se gli spiriti essere d'accordo, allora vediamo d'insegnarti abilità più potenti... ma solo se gli spiriti essere d'accordo.$B$BOra va', parla col resto della gente della Valle. Torna da me più tardi.",
  en_title = "Hallowed Tablet",
  en_obj = "Read the Hallowed Tablet and speak to Ken'jai outside the Den in the Valley of Trials.",
}
T[3086] = {
  title = "Glyphic Tablet",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice dei maghi, Mai'ah. Vorrebbe parlarti quando sarai $Gpronto:pronta;.",
  obj = "Leggi la Glyphic Tablet e parla con Mai'ah vicino all'ingresso di the Den in Valley of Trials.",
  progress = "Tu sembrare già voler compiacere Mai'ah, $N. Questo essere buono. Tu dare rispetto a Mai'ah, e Mai'ah forse ridare rispetto a te. Ma basta con questo, tu essere qui per imparare la magia, non per sentire Mai'ah parlare.$B$BCi essere una cosa sola che Mai'ah non potere insegnarti sulla magia, $N, ed essere come fermare la corruzione.",
  reward = "Tu essere tra gli esseri più potenti del pianeta, $N... su questo non esserci niente da discutere. E tutti saperlo... saperlo bene, pure!$B$BMa tu dovere stare $Gattento:attenta;! Perché non essere orco, o elfo, o nano che tu dovere temere... essere le cose che tu non potere vedere. La magia essere potente. Ti far fare cose che forse tu non volere. Ti far credere d'essere più potente di quanto tu essere davvero. Sii paziente. Sii $Gaccorto:accorta;.$B$BQuando tu credere d'essere $Gpronto:pronta; per l'addestramento, torna da Mai'ah. Lei insegnarti quello che tu essere $Gpronto:pronta; a imparare, nessun problema.",
  en_title = "Glyphic Tablet",
  en_obj = "Read the Glyphic Tablet and speak with Mai'ah near the entrance to the Den in the Valley of Trials.",
}
T[3087] = {
  title = "Etched Parchment",
  desc = "Ah, mentre eri via è arrivata una cartapecora per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice dei cacciatori, Jen'shan. Vorrebbe parlarti quando sarai $Gpronto:pronta;.",
  obj = "Leggi l'Etched Parchment e parla con Jen'shan in Valley of Trials.",
  progress = "Ah, allora alla fine tu venire. Bene. Jen'shan ti stava aspettando.$B$BMolti credere che sia una via facile, ma Jen'shan ti dice che non essere vero. Domare le bestie di Durotar e oltre richiede tanta abilità quanto padroneggiare le arti arcane o parlare con i nostri antenati.$B$BTirare con l'arco o col fucile forse non essere pericoloso per te come lanciare un incantesimo, ma di sicuro essere altrettanto pericoloso per il tuo nemico.",
  reward = "Quando abbiamo finito, dovresti fare un giro dagli altri abitanti della Valle. Loro ti chiedere di fare cose per loro... cose che metteranno alla prova la tua abilità e ti faranno scoprire alcuni dei pericoli di questa terra.$B$BMan mano che acquisti esperienza e saggezza, avrai bisogno che Jen'shan ti mostri tecniche e capacità migliori. Torna spesso da Jen'shan. Ti farò sapere cosa posso insegnarti.",
  en_title = "Etched Parchment",
  en_obj = "Read the Etched Parchment and speak to Jen'shan in the Valley of Trials.",
}
T[3088] = {
  title = "Encrypted Parchment",
  desc = "Ah, mentre eri via è arrivata una cartapecora per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei ladri, Rwag. Vorrebbe parlarti quando sarai $Gpronto:pronta;.",
  obj = "Leggi l'Encrypted Parchment e parla con Rwag in Valley of Trials.",
  progress = "Shhh, non così forte. Non mi fido di Nartok, laggiù. Con uno che deve nascondersi in fondo a una caverna ancora più di quanto faccia io è meglio non scherzare.$B$BImmagino che tu non abbia avuto problemi a orientarti?",
  reward = "Ora che hai scoperto dove mi sono sistemato, è meglio che tu sappia una cosa: la Shattered Hand mi ha chiesto di badare a te. Vogliono che io ti addestri e ti tenga $Ginformato:informata; su qualunque cosa possa servire loro. Anche se ancora non ti interessa aiutarli — e saresti $Guno sciocco:una sciocca; a non volerlo — farò quello che posso per istruirti... per un piccolo compenso. Torna da me quando pensi di essere $Gpronto:pronta;, e vedremo cosa puoi imparare.",
  en_title = "Encrypted Parchment",
  en_obj = "Read the Encrypted Parchment and speak to Rwag in the Valley of Trials.",
}
T[3089] = {
  title = "Rune-Inscribed Parchment",
  desc = "Ah, $N, mentre eri via è arrivata una cartapecora per te.$B$BLeggila quando hai un momento. Se non sbaglio te la manda l'addestratrice degli sciamani, Shikrik: vorrebbe parlarti quando sarai $Gpronto:pronta;.",
  obj = "Leggi la Rune-Inscribed Parchment e parla con Shikrik in Valley of Trials.",
  progress = "Dunque, sei $Garrivato:arrivata;. Cominciavo a chiedermi quando ti saresti $Gfatto:fatta; vedere. La cartapecora l'ho mandata tempo fa — non ero sicura che ti fosse arrivata.$B$BMa basta chiacchiere... sei qui perché sei $Gstato scelto:stata scelta;, $Gscelto:scelta; per guidare la vita spirituale del nostro popolo.",
  reward = "Sarai il tramite attraverso cui parlano i nostri antenati, e il potere degli elementi sarà ai tuoi ordini. Fare a pezzi i nemici sarà un gioco da ragazzi; curare gli alleati, facile come respirare. Ricordalo quando affronterai nuove sfide, e torna da me ogni volta che vuoi: io resto qui, per insegnarti nuovi incantesimi e metterti sulla strada giusta quando sarai $Gpronto:pronta;.",
  en_title = "Rune-Inscribed Parchment",
  en_obj = "Read the Rune-Inscribed Parchment and speak to Shikrik in the Valley of Trials.",
}
T[3090] = {
  title = "Tainted Parchment",
  desc = "Ah, $N, mentre eri via è arrivata una cartapecora per te.$B$BCon gli stregoni, se posso, preferisco non averci a che fare, ma credo che dovresti leggerla quando hai un momento. Se non sbaglio te la manda Nartok, nominato da poco tuo addestratore: vorrebbe parlarti quando sarai $Gpronto:pronta;.",
  obj = "Leggi la Tainted Parchment e parla con Nartok dentro The Den, in Valley of Trials.",
  progress = "Finalmente sei $Garrivato:arrivata;... e senza farti notare, per giunta. Bene.$B$BIl nostro mondo è pieno di sciocchi, $N. Anche il potente Thrall ha difetti più grandi di quanto molti riescano a vedere: volta le spalle al potere che servirebbe per fare di questa terra una cosa tutta nostra! Non siamo più il popolo che le creature del Nether hanno manipolato e usato. Apparteniamo solo a noi stessi. Siamo orgogliosi... e siamo forti.",
  reward = "E ora anche tu ti sei $Gunito:unita; alle nostre file. Non fraintendermi, $N: avere in mano un potere che molti invidieranno non vuol dire che ti accetteranno facilmente. Thrall lascia entrare a Orgrimmar quelli come noi perché siamo ancora suoi fratelli — non può voltarci le spalle, o diventeremmo patetici come gli umani che lo hanno reso schiavo. Il punto è questo: stai $Gattento:attenta;. Puoi essere potente, ma se sei $Gsciocco:sciocca;, sei già $Gmorto:morta;.$B$BSe hai bisogno di imparare incantesimi, torna da me.",
  en_title = "Tainted Parchment",
  en_obj = "Read the Tainted Parchment and speak to Nartok inside the Den in the Valley of Trials.",
}
T[3091] = {
  title = "Simple Note",
  desc = "$N, poco fa ti cercava una messaggera. Credo che te l'abbia mandata Harutt, l'addestratore dei guerrieri. Se questa nota è sua, io non aspetterei troppo a leggerla.",
  obj = "Leggi la Simple Note e parla con Harutt Thunderhorn al Camp Narache.",
  progress = "Ah, finalmente sei $Garrivato:arrivata;, $C. Non ti ho mentito, nella nota, $N: anche noi siamo speciali, come i druidi o gli sciamani della nostra tribù, e tu sei importante quanto loro. Tocca a noi difendere i confini, dare la caccia ai centauri e andare in guerra.",
  reward = "Nella tribù ognuno ha il suo ruolo, e ognuno deve affrontare gli stessi riti. Non lasciare mai che l'orgoglio ti dica il contrario.$B$BIo resto qui ad addestrare i nuovi guerrieri, quelli che cercano la gloria della battaglia e seguono le vie dei nostri primi antenati. Quando ti sentirai $Gpronto:pronta;, torna da me: farò il possibile per insegnarti ancora. Va' con la benedizione della tribù, $N.",
  en_title = "Simple Note",
  en_obj = "Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache.",
}
T[3092] = {
  title = "Etched Note",
  desc = "$N, poco fa ti cercava una messaggera. Credo che te l'abbia mandata Lanka, l'addestratore dei cacciatori. Se questa nota è sua, io non aspetterei troppo a leggerla.",
  obj = "Leggi l'Etched Note e parla con Lanka Farshot sulla Red Cloud Mesa.",
  progress = "$GBenvenuto:Benvenuta; al Camp Narache, $N. Mi hanno parlato bene di te: vieni da una stirpe forte, e molti anziani ti ritengono già abile. Questo, però, lo metteremo alla prova.$B$BPer un po' le pianure di Mulgore saranno la tua casa — cerca di conoscerle a fondo. Un giorno viaggerai in terre sconosciute per padroneggiare abilità superiori, e devi essere $Gpronto:pronta;.",
  reward = "Ed è compito mio fare in modo che tu sia $Gpreparato:preparata;: ti insegnerò le basi del nostro mestiere — come addomesticare il tuo famiglio, come sparare con il fucile e tante altre abilità che ti serviranno.$B$BI cacciatori sono una parte importante della nostra tradizione e della nostra storia, $N, e faresti bene a ricordare quanto conti per la tribù. Se servirai bene il nostro popolo, sarai $Grispettato:rispettata; e $Gvenerato:venerata;.",
  en_title = "Etched Note",
  en_obj = "Read the Etched Note and speak to Lanka Farshot in Red Cloud Mesa.",
}
T[3093] = {
  title = "Rune-Inscribed Note",
  desc = "$N, poco fa ti cercava una messaggera. Credo che te l'abbia mandata Meela, l'addestratrice degli sciamani. Se questa nota è sua, io non aspetterei troppo a leggerla.",
  obj = "Leggi la Rune-Inscribed Note e parla con Meela Dawnstrider al Camp Narache.",
  progress = "Eccoti qui davanti a me, veloce come l'acqua che cade dal cielo. Mi fa piacere la tua prontezza: vuol dire che capisci quanto conta questo incontro, e quanto conta che tu sia qui. Non sono un capo, ma capisco gli elementi e so parlare con gli spiriti del nostro popolo. Ti insegnerò a fare lo stesso.",
  reward = "Ci incontreremo molte volte nei giorni che verranno, e ogni volta, spero, te ne andrai un po' più $Gpotente:potente;... un po' più $Gpreparato:preparata;. Il tuo spirito brucerà luminoso e ardente, come l'Eternal Flame.$B$BOra va', $N. Va' e mettiti alla prova. Quando avrai bisogno di me, mi troverai qui.",
  en_title = "Rune-Inscribed Note",
  en_obj = "Read the Rune-Inscribed Note and speak to Meela Dawnstrider in Camp Narache.",
}
T[3094] = {
  title = "Verdant Note",
  desc = "$N, poco fa ti cercava una messaggera. Credo che te l'abbia mandata Gart, l'addestratore dei druidi. Se questa nota è sua, io non aspetterei troppo a leggerla.",
  obj = "Leggi la Verdant Note e parla con Gart Mistrunner al Camp Narache.",
  progress = "Sei $Garrivato:arrivata;. Bene. In tutta Mulgore, e anche oltre, gli spiriti dei nostri antenati si sono fatti inquieti, e non so dirti perché. Il tuo dovere, per sempre, sarà imparare ad ascoltare gli spiriti della natura e agire come loro avatar. Ricordatelo.",
  reward = "Ci unisce un legame comune, ma dagli elfi della notte non aspettarti una grande accoglienza. L'orgoglio limita ancora il loro sguardo, e comunque non è affar nostro. L'unica cosa di cui devi occuparti sono gli insegnamenti della Madre Terra, e io ti trasmetterò quello che so man mano che crescerai in saggezza.$B$BTorna spesso da me, $N. Vedrai che la Madre Terra concede abilità incredibili a chi le è più devoto.",
  en_title = "Verdant Note",
  en_obj = "Read the Verdant Note and speak to Gart Mistrunner in Camp Narache.",
}
T[3095] = {
  title = "Simple Scroll",
  desc = "Ah, mentre eri via a occuparti di quello Scourge senza cervello, è arrivata questa pergamena per te. Immagino sia una faccenda importante, visto che a quanto pare porta il sigillo dell'istruttore dei guerrieri, Dannal. Io troverei un momento per leggerla, prima di ripartire.",
  obj = "Leggi la Simple Scroll e parla con Dannal Stern a Deathknell.",
  progress = "Ah, allora sei $Garrivato:arrivata;. Bene. Ho sentito dire che alcuni altri sono riusciti a sfuggire alla \"morte\" e che erano diretti in città. Forse quella tenacia tornerà utile anche in futuro.$B$BPuoi ringraziare Sylvanas per la libertà... la libertà della mente e del corpo. Anche se sei ancora $Gtormentato:tormentata; dalla pestilenza e dai suoi effetti, ora sei $Glibero:libera; di andare e venire come meglio credi.",
  reward = "Sarò qui per addestrarti man mano che diventerai più $Gesperto:esperta;... vieni a trovarmi tutte le volte che vuoi. Chiedo un compenso minimo, ma vedrai che tutto ciò che posso insegnarti ne varrà la pena.$B$BOra va' e metti alla prova la tua abilità. Scoprirai molte altre cose con l'esperienza, e di alcune non posso parlarti qui. Sappi solo che, in futuro, Sylvanas avrà bisogno di guerrieri con la tua forza. Su di te poggerà la nostra salvezza. Non dimenticarlo.",
  en_title = "Simple Scroll",
  en_obj = "Read the Simple Scroll and speak to Dannal Stern in Deathknell.",
}
T[3096] = {
  title = "Encrypted Scroll",
  desc = "Ah, mentre eri via a occuparti di quello Scourge senza cervello, è arrivata questa pergamena per te. Immagino sia una faccenda importante, visto che a quanto pare porta il sigillo dell'istruttore dei ladri, David Trias. Io troverei un momento per leggerla, prima di ripartire.",
  obj = "Leggi l'Encrypted Scroll e parla con David Trias a Deathknell.",
  progress = "Alla fine sei $Garrivato:arrivata;? Bene, col tempo avremo bisogno di altri ladri. Probabilmente gli Shadowstalkers finiranno per trovarti quando lo riterranno opportuno, quindi evita i passi falsi e non fare niente di cui potresti pentirti. A loro servono agenti di talento... non borseggiatori e sciocchi.",
  reward = "Passo quasi tutto il tempo qui alla locanda, a tenere d'occhio le facce nuove e a seguire le giovani promesse. Riga dritto e farò il possibile per insegnarti qualcosa. Torna da me quando vuoi, e vedremo se sei $Gpronto:pronta; per una o due nuove abilità.",
  en_title = "Encrypted Scroll",
  en_obj = "Read the Encrypted Scroll and speak to David Trias in Deathknell.",
}
T[3097] = {
  title = "Hallowed Scroll",
  desc = "Ah, mentre eri via a occuparti di quello Scourge senza cervello, è arrivata questa pergamena per te. Immagino sia una faccenda importante, visto che a quanto pare porta il sigillo dell'istruttore dei sacerdoti, Duesten. Io troverei un momento per leggerla, prima di ripartire.",
  obj = "Leggi l'Hallowed Scroll e parla con Dark Cleric Duesten nella chiesa di Deathknell.",
  progress = "Ah, dunque tra incendi, pestilenza, rivolte e cose ben peggiori, $Gun altro:un'altra; dei \"fedeli\" bussa alla mia porta. Ebbene, ti do il benvenuto, $C. E concedimi un momento per spiegarti un paio di cose, prima che tu decida di andare in cerca di ciò che ti spinge avanti: l'Holy Light non ti riguarda più, gli spiriti dei tuoi antenati sono favole e le creature del Nether non ti vogliono.$B$BFin qui mi segui?",
  reward = "C'è un'unica cosa che devi sapere: siamo sopravvissuti grazie alla sola volontà. È la fede in noi stessi che ci distingue dagli altri, e con i nostri poteri porteremo grandi cambiamenti in tutta Azeroth. I deboli verranno ad appoggiarsi a te. I lebbrosi ti chiameranno Signore. E gli ignoranti si rivolgeranno a te in cerca di una guida. È mio dovere fare in modo che tu abbia gli strumenti necessari, così che, quando verrà il momento, sarai $Gpreparato:preparata;. Vieni a cercarmi man mano che acquisirai esperienza. Ti insegnerò poteri più grandi, se sarai $Gpronto:pronta;.",
  en_title = "Hallowed Scroll",
  en_obj = "Read the Hallowed Scroll and speak to Dark Cleric Duesten in the church in Deathknell.",
}
T[3098] = {
  title = "Glyphic Scroll",
  desc = "Ah, mentre eri via a occuparti di quello Scourge senza cervello, è arrivata questa pergamena per te. Immagino sia una faccenda importante, visto che a quanto pare porta il sigillo dell'istruttrice dei maghi, Isabella. Io troverei un momento per leggerla, prima di ripartire.",
  obj = "Leggi la Glyphic Scroll e parla con Isabella nella chiesa di Deathknell.",
  progress = "Sapevo che saresti $Gvenuto:venuta; da me, $N. Non perché ti manchi la volontà di seguire la tua strada, ma perché siamo anime affini. $GEntrambi:Entrambe; abbiamo provato il dolore. $GEntrambi:Entrambe; abbiamo sofferto. E ora vogliamo il potere di riprenderci ciò che, lo sappiamo, ci appartiene: questa terra, le nostre vite, i nostri destini. Ma hai ancora molto da imparare.",
  reward = "Dovrai tornare spesso da me, se vuoi diventare abbastanza potente da distruggere chi vorrebbe opporsi a noi. Le regole della magia valgono ancora per te, $N. Scoprirai che la corruzione continua a seguirti, come lupi affamati nella notte. Scoprirai che la sua carezza somiglia a una dipendenza, a un vecchio amante che vuole ancora starti accanto. Ma queste cose si possono tenere a bada. Ti domineranno solo se glielo permetterai.$B$BOra va', e torna da me quando i tuoi poteri saranno cresciuti.",
  en_title = "Glyphic Scroll",
  en_obj = "Read the Glyphic Scroll and speak to Isabella in the church in Deathknell.",
}
T[3099] = {
  title = "Tainted Scroll",
  desc = "Ah, mentre eri via a occuparti di quello Scourge senza cervello, è arrivata questa pergamena per te. Immagino sia una faccenda importante, visto che a quanto pare porta il sigillo dell'istruttore degli stregoni, Maximillion. Io troverei un momento per leggerla, prima di ripartire.",
  obj = "Leggi la Tainted Scroll e parla con Maximillion a Deathknell.",
  progress = "Ti do il benvenuto, $Gfratello:sorella;. Sapevo che saresti $Gvenuto:venuta;. Era solo questione di tempo.$B$BQuello che ho detto ti ha interessato, vero? Le mie parole hanno trovato un'eco in te... qualcosa dentro di te sapeva che ciò che affermavo era la verità. Bene.$B$BSappi questo, però: non sto tradendo Sylvanas. Semmai, lei apprezzerebbe le mie tesi, visto che sono state proprio le sue convinzioni a portare i Forsaken dove sono oggi.",
  reward = "Ho detto che uno schiavo resta uno schiavo, chiunque sia il padrone. Ricordi? Sappiamo entrambi che è quel tipo di controllo — quel tipo di potere — a spingerci, ora. Vogliamo che le creature ci servano. Siamo consapevoli di essere più potenti e di meritare più rispetto di quanto ce ne diano gli altri... e così ora cerchiamo di prendercelo.$B$BSarò tuo alleato in questa lotta — la lotta per la nostra libertà. La libertà di scegliere le nostre alleanze. Quando ti sentirai $Gpronto:pronta;, torna da me e ti insegnerò tutto ciò che so.",
  en_title = "Tainted Scroll",
  en_obj = "Read the Tainted Scroll and speak to Maximillion in Deathknell.",
}
T[3100] = {
  title = "Simple Letter",
  desc = "Mi hanno chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera sigillata con lo stemma di Llane, il nostro istruttore di guerrieri. Io non perderei tempo: leggila prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.",
  obj = "Leggi la Simple Letter e parla con Llane Beshere a Northshire Abbey.",
  progress = "Ah, hai ricevuto la mia lettera, $N... bene.$B$BDi recente sono arrivati molti guerrieri a Elwynn — una fortuna per Stormwind, ma un guaio per i coboldi e i Defias della zona.",
  reward = "Sistemati per bene, impara a conoscere il territorio e torna da me ogni volta che ti serve addestramento. Sarò qui giorno e notte.$B$BI Knights of the Silver Hand hanno fatto un buon lavoro nel rendere questo posto abbastanza sicuro, ma quando conoscerai gli altri abitanti scoprirai, credo, che hanno tutti qualche problema e che farebbe loro comodo una mano — quella che $Gun:una; $C può dare. Buona fortuna.",
  en_title = "Simple Letter",
  en_obj = "Read the Simple Letter and speak to Llane Beshere in Northshire Abbey.",
}
T[3101] = {
  title = "Consecrated Letter",
  desc = "Mi hanno chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera sigillata con lo stemma di Brother Sammuel, il nostro istruttore di paladini. Io non perderei tempo: leggila prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.",
  obj = "Leggi la Consecrated Letter e parla con Brother Sammuel a Northshire Abbey.",
  progress = "Finalmente! Ci incontriamo faccia a faccia, da fratello a $Gfratello:sorella;. Ti do il benvenuto a Northshire. Questa sarà la tua casa per un breve periodo, mentre impari come vanno le cose, ma sappi che Stormwind non è lontana e, prima o poi, il tuo cammino ti condurrà lì. Fino ad allora, però, sii paziente... $GCavaliere:Cavaliera; della Silver Hand.",
  reward = "Nel frattempo, ci sono un paio di altre cose che dovresti sapere. Per molti, in questa terra, sei un simbolo — comportati di conseguenza. L'Holy Light risplende in te, e sarà evidente sia ai tuoi alleati sia ai tuoi nemici.$B$BInoltre, man mano che crescerai in saggezza e potere, dovrai addestrarti per apprendere nuove abilità. È qui che entro in gioco io. Quando sentirai di aver acquisito un po' di esperienza qui a Northshire, torna da me e ti insegnerò quello che, secondo me, sei $Gpronto:pronta; a imparare. Buona fortuna... $C!",
  en_title = "Consecrated Letter",
  en_obj = "Read the Consecrated Letter and speak to Brother Sammuel in Northshire Abbey.",
}
T[3102] = {
  title = "Encrypted Letter",
  desc = "Mi hanno chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera sigillata con lo stemma di Jorik, uno dei nostri istruttori. Io non perderei tempo: leggila prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.",
  obj = "Leggi l'Encrypted Letter e parla con Jorik Kerridan nella stalla dietro Northshire Abbey.",
  progress = "Sei $Garrivato:arrivata; qui $Gsano e salvo:sana e salva;, e non sembra che ti abbiano visto in molti. Per me basta così. Non mi piace attirare l'attenzione, qui dietro... si sta bene, in pace. Sono sicuro che mi capisci.$B$BHai già avuto qualche guaio? Mi fa piacere che tu non ne abbia avuti. Cambierà presto.",
  reward = "Vedrai che parecchie organizzazioni fanno a gara per accaparrarsi le nostre capacità, $N. Avventurieri, SI:7... diamine, persino la Defias Brotherhood non disdegnerebbe una spia o due a Stormwind. Ma ricordati una cosa: sei $Gpadrone di te stesso:padrona di te stessa;. Non farti mai costringere da nessuno a fare qualcosa che non ti va! E poi, le carte buone le abbiamo tutte noi... almeno, prima che la partita finisca. Capisci cosa intendo?$B$BComunque, volevo solo presentarmi e farti sapere che sono qui se ti serve addestramento. Passa quando vuoi.",
  en_title = "Encrypted Letter",
  en_obj = "Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey.",
}
T[3103] = {
  title = "Hallowed Letter",
  desc = "Mi hanno chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera sigillata con lo stemma di Priestess Anetta, la nostra istruttrice di sacerdoti. Io non perderei tempo: leggila prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.",
  obj = "Leggi l'Hallowed Letter e parla con Priestess Anetta a Northshire Abbey.",
  progress = "Ah, finalmente sei $Garrivato:arrivata;. Sapevo che avresti trovato la strada fino a me. L'Holy Light risplende su di te e sul cammino che hai scelto. Sono tempi duri — la Burning Legion è ancora presente su Azeroth, tutta Kalimdor cerca nuovi modi per difendersi dai mali che la affliggono, e spetta a te aiutare quante più persone puoi.",
  reward = "Torna da me man mano che acquisirai esperienza, e farò il possibile per trasmetterti il mio sapere. Fino ad allora, va' con la compassione nel cuore, e lascia che la saggezza ti guidi. Ricorda: il mondo diventa un posto migliore solo se sei tu a renderlo tale.",
  en_title = "Hallowed Letter",
  en_obj = "Read the Hallowed Letter and speak to Priestess Anetta in Northshire Abbey.",
}
T[3104] = {
  title = "Glyphic Letter",
  desc = "Mi hanno chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera chiusa con il sigillo di Khelden, il nostro istruttore di magia. Io non esiterei: leggila prima di dedicarti a qualunque altra faccenda qui all'Abbazia.",
  obj = "Leggi la Glyphic Letter e parla con Khelden Bremen all'interno di Northshire Abbey.",
  progress = "Salve, $N. Sono Khelden. Posso fare qualcosa per te?",
  reward = "Ah ah, sapevo che il mio biglietto non ti avrebbe $Gdistolto:distolta; dalla tua strada. Allora sei $Gpronto:pronta;, vero? $GPronto:Pronta; ad accettare il tuo destino? $GPronto:Pronta; a sfidare gli dei e qualunque altra forza ti si pari davanti, per inseguire la conoscenza e il potere?$B$BNon ti mentirò, $N, sarai $Gtemuto:temuta; quanto $Grispettato:rispettata;. Ma sappi anche questo, quando avrai bisogno di addestramento mi troverai qui. Vieni pure a cercarmi man mano che diventerai più forte.",
  en_title = "Glyphic Letter",
  en_obj = "Read the Glyphic Letter and speak to Khelden Bremen inside Northshire Abbey.",
}
T[3105] = {
  title = "Tainted Letter",
  desc = "Mi hanno chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera chiusa con il sigillo di Drusilla, che fa parte dei nostri istruttori. Io non esiterei: leggila prima di dedicarti a qualunque altra faccenda qui all'Abbazia.",
  obj = "Leggi la Tainted Letter e parla con Drusilla La Salle accanto a Northshire Abbey.",
  progress = "Ah, eccoti $Garrivato:arrivata;, e giusto in tempo, $N. Poco fa c'erano qui alcune guardie che mi lanciavano occhiate strane... miseri profani.",
  reward = "Man mano che diventerai più forte, sarai $Gtentato:tentata; — ricordati sempre di dominarti. Non ti mentirò — la corruzione può colpire chiunque pratichi le arti arcane; soprattutto chi ha a che fare con le creature della Twisting Nether. Sii paziente, e sii prudente... ma senza per questo soffocare l'ambizione.$B$BQuando sarai ancora più potente, torna da me e ti insegnerò altro sulla nostra arte.",
  en_title = "Tainted Letter",
  en_obj = "Read the Tainted Letter and speak to Drusilla La Salle next to Northshire Abbey.",
}
T[3106] = {
  title = "Simple Rune",
  desc = "Mentre mi davi una mano, mi hanno lasciato questa runa da darti. Leggila con calma quando ne hai l'occasione. Penso venga dall'istruttore dei guerrieri, Thran. Dalle un'occhiata e, quando puoi, va' a cercarlo ad Anvilmar.",
  obj = "Leggi la Simple Rune e parla con Thran Khorman alla Coldridge Valley.",
  progress = "Accidenti che freddo oggi, eh? Sembra che la neve non se ne vada mai, $N.$B$BL'avrai già notato, ma adesso gli gnomi vivono in città con noi. Il fatto è che sono riusciti a farsi cacciare di casa a suon di esplosioni. Non andarlo a spifferare in giro, ma non me la sento proprio di dargli torto — credo che anch'io sarei ricorso agli esplosivi, se Ironforge fosse infestata dai Dark Irons o roba simile.",
  reward = "Giusto perché tu lo sappia, potresti vedere qualche novità: nani che in battaglia usano la magia invece dei fucili, alcuni di noi che si mettono a venerare l'Holy Light come certi umani e, ultimi ma non ultimi, i trogg. Sui di loro ne saprai di più in seguito, ma per ora sappi che io sono qui per aiutarti.$B$BSono qui per insegnarti a essere $Gun vero:una vera; $C. Ogni volta che pensi di aver bisogno di altro addestramento, torna da me e vedrò cosa posso fare.",
  en_title = "Simple Rune",
  en_obj = "Read the Simple Rune and speak to Thran Khorman in Coldridge Valley.",
}
T[3107] = {
  title = "Consecrated Rune",
  desc = "Mentre mi davi una mano, mi hanno consegnato questa runa da passare a te. Leggila con calma, quando puoi. Secondo me viene dall'istruttore dei paladini, Bromos. Dacci un'occhiata e, appena ne hai l'occasione, vai a cercarlo dentro Anvilmar.",
  obj = "Leggi la Consecrated Rune e parla con Bromos Grummner in Coldridge Valley.",
  progress = "Allora, ce l'hai fatta! E appena in tempo. C'è molto da fare nella Coldridge Valley e oltre. Mi servirà il tuo aiuto quanto a te servirà il mio!$B$BOra che sei $Gun Cavaliere:una Cavaliera; della Silver Hand, tieniti $Gpronto:pronta; a esserne all'altezza.",
  reward = "Gli umani ci hanno insegnato molto sull'Holy Light e su quanto il loro ordine conti per loro... e per la difesa di tutta Azeroth. Rispettiamo molto le sue radici profonde nella tradizione, e il fatto che basti una sola figura, un solo sacrificio, a fare la differenza tra il dolore e la salvezza.$B$BNoi due lavoreremo insieme per qualche tempo. Quando pensi di essere $Gpronto:pronta;, torna da me e vedremo di addestrarti un po'. Non posso mica mandarti in giro per il mondo $Gimpreparato:impreparata;, no?",
  en_title = "Consecrated Rune",
  en_obj = "Read the Consecrated Rune and speak to Bromos Grummner in Coldridge Valley.",
}
T[3108] = {
  title = "Etched Rune",
  desc = "Mentre mi davi una mano, mi hanno lasciato questa runa da darti. Leggila con calma quando hai tempo. Secondo me te la manda l'istruttore dei cacciatori, Thorgas. Dalle un'occhiata e, quando puoi, va' a cercarlo ad Anvilmar.",
  obj = "Leggi l'Etched Rune e parla con Thorgas Grimson alla Coldridge Valley.",
  progress = "Ce l'hai fatta! Mi fa piacere! Scommetto che non hai nemmeno dovuto seguire le mie tracce per trovare il posto. Ah ah!$B$BIl nostro mestiere è intriso di tradizione, $N. Imparare i segreti della natura. Imparare a seguire le tracce di un orso tra le montagne. Anche solo sopravvivere contando sul proprio ingegno richiede un gran coraggio e tanta astuzia. Pensi di esserne $Gcapace:capace;?",
  reward = "Ricorda sempre di rispettare il mondo in cui vivi. Le bestie che scelgono di combattere al tuo fianco; il luccichio dell'arma; il peso delle munizioni; il morso di un vento gelido: devi conoscere a fondo tutte queste cose.$B$BFarò quello che posso per aiutarti, ma il grosso del lavoro tocca a te. Ogni volta che ti senti $Gpronto:pronta;, torna a parlarmi. Ti addestrerò quando potrò.",
  en_title = "Etched Rune",
  en_obj = "Read the Etched Rune and speak to Thorgas Grimson in Coldridge Valley.",
}
T[3109] = {
  title = "Encrypted Rune",
  desc = "Mentre mi davi una mano, mi hanno lasciato questa runa da darti. Leggila con calma quando ne hai l'occasione. Penso venga dall'istruttore dei ladri, Solm. Dalle un'occhiata e, quando puoi, va' a cercarlo ad Anvilmar.",
  obj = "Leggi l'Encrypted Rune e parla con Solm Hargrin alla Coldridge Valley.",
  progress = "Ce l'hai fatta! Ottimo!$B$BUltimamente c'è un gran viavai, quindi sono contento di contare tra le nostre file $Gun altro:un'altra; del clan di Ironforge. Non c'è niente di meglio che avere una lama gelida in pugno e un'ombra che ti permetta di essere sempre un passo avanti agli altri, e se sei qui sai benissimo cosa intendo!",
  reward = "Comunque, quando comincerai a ficcare il naso in giro per Coldridge, prima o poi avrai bisogno di addestramento. Torna da me ogni volta che ti serve e ti insegnerò quello che so — un trucco qui, una manovra là. Insomma, la roba che ti tiene in vita e ti fa guadagnare qualche moneta in più.$B$BE abbi un occhio di riguardo anche per i nostri amici gnomi... gli è andata un po' male, con Gnomeregan che è stata... distrutta. Avranno bisogno del nostro aiuto per sentirsi i benvenuti.",
  en_title = "Encrypted Rune",
  en_obj = "Read the Encrypted Rune and speak to Solm Hargrin in Coldridge Valley.",
}
T[3110] = {
  title = "Hallowed Rune",
  desc = "Mentre mi davi una mano, mi hanno consegnato questa runa da darti. Leggila con calma, quando puoi. Penso vienga dall'istruttore dei sacerdoti, Branstock. Dacci un'occhiata e vallo a cercare dentro Anvilmar appena ti capita.",
  obj = "Leggi l'Hallowed Rune e parla con Branstock Khalder ad Anvilmar.",
  progress = "Ach! Ce l'hai fatta, $N! Magnifico!$B$BStavo per dire che ormai, a forza di aspettarti, avevo quasi perso la fede... capito, perdere la fede? È una battuta, $Gragazzo:ragazza;... vabbè, lascia perdere. Tanto non sei $Gvenuto:venuta; fin qui per sentire le mie brutte battute.",
  reward = "Posso addestrarti io, mentre impari a orientarti nella Coldridge Valley. Quando ti senti $Gpronto:pronta;, torna da me e vedremo di insegnarti uno o due incantesimi nuovi per difendere la valle da quei maledetti trogg.$B$BHai dalla tua parte la Luce e tutta Ironforge, $N... ma niente pressioni, eh: non devi mica diventare per forza qualcuno di speciale.",
  en_title = "Hallowed Rune",
  en_obj = "Read the Hallowed Rune and speak to Branstock Khalder in Anvilmar.",
}
T[3111] = {
  title = "Runa Glifica",
  desc = "Tanto tempo fa gli alti elfi hanno insegnato i segreti della magia a noi e ai nostri alleati umani. E ci facevano la predica sulle regole, su come la magia può farti impazzire! Ma tu non crederci. Noi non siamo come gli elfi; le loro debolezze non le abbiamo. Resta sulla retta via e scoprirai che la magia è potente come strumento quanto come arma.$B$BQuando sei $Gpronto:pronta;, vieni a cercarmi dentro Anvilmar. Ti aspetto!",
  obj = "Parla con Marryk Nurribit dentro Anvilmar.",
}
T[3112] = {
  title = "Simple Memorandum",
  desc = "Mentre mi davi una mano, mi hanno consegnato questo promemoria da darti. Leggilo con calma, quando puoi. Penso venga dall'istruttore dei guerrieri, Thran. Dacci un'occhiata e vallo a cercare dentro Anvilmar appena ti capita.",
  obj = "Leggi il Simple Memorandum e parla con Thran Khorman a Coldridge Valley.",
  progress = "Ah, beh, ecco $Gun:una; $R in missione con l'ennesimo promemoria... che carino.$B$BNo, no, non ti sto prendendo in giro, $Gpiccoletto:piccoletta;. La tua tenacia va rispettata, questo è poco ma sicuro. Anch'io me la prenderei allo stesso modo se Ironforge cadesse in mano ai nani Dark Iron, quindi non pensare che la tua sventura mi lasci indifferente...",
  reward = "Beh, visto che è la tua direttiva primaria, o come la chiamate oggi, ho promesso di fare tutto il possibile perché tu e i tuoi siate pronti a riprendervi casa... ed è proprio quello che farò.$B$BQuando ti senti $Gpronto:pronta;, torna dal buon vecchio Thran e ti insegnerò volentieri quello che so. L'addestramento si paga, ma non ti costerà troppo. Buona fortuna.",
  en_title = "Simple Memorandum",
  en_obj = "Read the Simple Memorandum and speak to Thran Khorman in Coldridge Valley.",
}
T[3113] = {
  title = "Encrypted Memorandum",
  desc = "Mentre mi davi una mano, mi hanno consegnato questo promemoria da darti. Leggilo con calma, quando puoi. Penso venga dall'istruttore dei ladri, Solm. Dacci un'occhiata e vallo a cercare dentro Anvilmar appena ti capita.",
  obj = "Leggi l'Encrypted Memorandum e parla con Solm Hargrin a Coldridge Valley.",
  progress = "Mi fa piacere che il mio biglietto ti sia arrivato e che tu sia $Gpassato:passata; a trovarmi. Scusa se ho fatto finta che fosse un promemoria dei tuoi superiori... non volevo offenderti. Sapevo solo che noi due, e tutti quelli come noi, dobbiamo restare uniti.$B$BIn pochi pensano che avere quelli come noi nascosti tutti nella stessa città sia un'ottima idea, ma credo che riusciremo a intenderci senza problemi. Tu che ne pensi?",
  reward = "Qui per lo più mi faccio gli affari miei, così nessuno ci dà la colpa quando sparisce qualcosa, ma se avessi bisogno di un po' di addestramento o che so io, torna pure quando vuoi.$B$BTu e io ci capiamo. Sappiamo che, alla fine dei conti, ci si può fidare solo della famiglia... ed è proprio quello che abbiamo qui, no? Gnomeregan sarà anche stata... invasa, e qualunque altro guaio ci capiti tra capo e collo, noi ci guardiamo le spalle a vicenda. Giusto?",
  en_title = "Encrypted Memorandum",
  en_obj = "Read the Encrypted Memorandum and speak to Solm Hargrin in Coldridge Valley.",
}
T[3114] = {
  title = "Glyphic Memorandum",
  desc = "Mentre mi davi una mano, mi hanno consegnato questo promemoria da darti. Leggilo con calma, quando puoi. Penso venga dall'istruttore dei maghi, Marryk. Dacci un'occhiata e vallo a cercare dentro Anvilmar appena ti capita.",
  obj = "Leggi il Glyphic Memorandum e parla con Marryk Nurribit dentro Anvilmar, sopra Coldridge Valley.",
  progress = "Eh, che c'è, $R? Parla più forte, se non ti dispiace. Dopo un paio di birre non ci sento tanto bene.",
  reward = "Ah, sì! Le Arti Arcane... certo.$B$BEcco cosa devi sapere, $N: non cacciarti in troppi guai. Metti da parte qualche moneta per offrirmi una birra... o per gli incantesimi che ti interessano. E stai alla larga da Gnomeregan, accidenti. A parte questo, buona giornata! Sono qui se hai bisogno di me o vuoi addestrarti... o quello che è.",
  en_title = "Glyphic Memorandum",
  en_obj = "Read the Glyphic Memorandum and speak to Marryk Nurribit inside Anvilmar above Coldridge Valley.",
}
T[3116] = {
  title = "Simple Sigil",
  desc = "Questo sigillo me l'ha consegnato un messaggero della nostra istruttrice dei guerrieri, Alyissia. Pare che Alyissia voglia parlarti, quando avrai un momento. Leggilo e poi portaglielo.",
  obj = "Leggi il Simple Sigil e parla con Alyissia a Shadowglen.",
  progress = "Ce l'hai fatta. Ne sono davvero lieta.$B$BNegli ultimi anni sono successe molte cose, $N: la creazione di Teldrassil, la corruzione di tante creature della foresta, qui e altrove, la scoperta di terre che credevamo perdute, come Feralas... tanto, in così poco tempo. Ma queste sono solo alcune delle ragioni per cui siamo qui, e la più importante è proteggere la nostra gente da altri mali.",
  reward = "Presto vedrai membri di altre razze fra i rami della nostra casa — non per questo devi farti dei pregiudizi. Sono i benvenuti. Ci daranno una mano quando potranno. Non tutti saranno altruisti, ma meritano un po' di fiducia.$B$BMa ora tutto questo non conta. Dobbiamo concentrarci su di te e su come puoi servire la nostra gente. Sono qui proprio per questo. Man mano che diventerai più forte, ti insegnerò la via $Gdel:della; $C. Torna da me quando vuoi e farò il possibile per aiutarti.",
  en_title = "Simple Sigil",
  en_obj = "Read the Simple Sigil and speak to Alyissia in Shadowglen.",
}
T[3117] = {
  title = "Etched Sigil",
  desc = "Questo sigillo me l'ha consegnato un messaggero della nostra istruttrice dei cacciatori, Ayanna. Pare che Ayanna voglia parlarti, quando avrai un momento. Leggilo e poi portaglielo.",
  obj = "Leggi l'Etched Sigil e parla con Ayanna Everstride in cima ad Aldrassil, a Shadowglen.",
  progress = "Sei $Garrivato:arrivata;, e appena in tempo, $N. $GBenvenuto:Benvenuta; a Shadowglen.$B$BQuando hai ricevuto il mio sigillo eri in salute e di buon umore, spero?$B$BCome ti ho già detto, sono qui per addestrarti come $Gcacciatore:cacciatrice;; per insegnarti ad ammaestrare le bestie perché ti aiutino in battaglia; a usare l'arco con precisione infallibile; a rispettare la terra in cui viviamo e anche quelle più lontane.",
  reward = "Man mano che scoprirai ciò che Shadowglen ha da insegnarti, vieni a trovarmi — potrò aiutarti a capire meglio il tuo ruolo di $Gcacciatore:cacciatrice; e quello di cui sei capace.$B$BViviamo tempi insidiosi, $N, perciò non dare per scontata l'abilità dei tuoi famigli — in questo mondo ci sono cose più pericolose di quanto tu possa immaginare. Va' con Elune e torna ancora da me.",
  en_title = "Etched Sigil",
  en_obj = "Read the Etched Sigil and speak to Ayanna Everstride at the top of Aldrassil in Shadowglen.",
}
T[3118] = {
  title = "Encrypted Sigil",
  desc = "Questo sigillo me l'ha consegnato un messaggero del nostro istruttore dei ladri, Frahun. Pare che Frahun voglia parlarti, quando avrai un momento. Leggilo e poi portaglielo.",
  obj = "Leggi l'Encrypted Sigil e parla con Frahun Shadewhisper a Shadowglen.",
  progress = "Salve, $N. Sono contento che tu mi abbia trovato. Cominciavo a pensare che ti fossi $Gperso:persa; per strada.$B$BDa quando ti ho mandato il sigillo, a Shadowglen non è successo niente di davvero nuovo, ma lascio a te il compito di raccogliere informazioni. Se vuoi, parla pure con gli altri qui intorno ad Aldrassil.",
  reward = "Fino ad allora, sappi che in questi tempi incerti c'è più bisogno che mai di quelli come noi. La pace con le altre razze può crollare da un momento all'altro, e si parla molto di membri dell'Orda che cercano di seminare ancora più diffidenza. Ricordatelo.$B$BMan mano che acquisterai potere e ti sentirai più $Gpreparato:preparata;, torna qui da me e vedrò di darti qualche lezione. È importante che tu sappia maneggiare l'arma che preferisci, e non solo.",
  en_title = "Encrypted Sigil",
  en_obj = "Read the Encrypted Sigil and speak to Frahun Shadewhisper in Shadowglen.",
}
T[3119] = {
  title = "Hallowed Sigil",
  desc = "Un messaggero della nostra istruttrice dei sacerdoti, Shanda, mi ha consegnato questo sigillo. Pare che Shanda voglia parlarti, quando hai un momento. Leggilo, poi portaglielo.",
  obj = "Leggi l'Hallowed Sigil e parla con Shanda ad Aldrassil.",
  progress = "Mi fa piacere che tu sia $Garrivato:arrivata; così in fretta, $N. $GBenvenuto:Benvenuta;.$B$BAvrai sentito che tutta Teldrassil è in fermento, con tanti viaggiatori che vanno e vengono. Perfino i membri dell'Alleanza hanno avuto il permesso di salire sui rami di Teldrassil, per incontrare altri Kaldorei che si preparano alle avventure che li aspettano.",
  reward = "Per ora non preoccuparti del mondo che sta sotto Teldrassil. Per quello ci sarà tempo più avanti. Adesso va' a parlare con gli altri a Shadowglen — possono spiegarti meglio cosa è successo. Aiutali in tutti i modi che puoi, e quando senti di aver bisogno di altro addestramento torna da me: ti insegnerò quello che posso.",
  en_title = "Hallowed Sigil",
  en_obj = "Read the Hallowed Sigil and speak to Shanda in Aldrassil.",
}
T[3120] = {
  title = "Verdant Sigil",
  desc = "Un messaggero del nostro istruttore dei druidi, Mardant, mi ha consegnato questo sigillo. Pare che Mardant voglia parlarti, quando hai un momento. Leggilo, poi portaglielo.",
  obj = "Leggi il Verdant Sigil e parla con Mardant Strongoak, nell'albero Aldrassil a Shadowglen.",
  progress = "Ah, giovane $C. Vedo che sei $Gansioso:ansiosa; di andare avanti con gli studi. Bene.$B$BMi chiedo se tu abbia già trascorso molto tempo in The Emerald Dream. Forse non sei ancora $Gpronto:pronta; per quello... ma col tempo lo sarai, ne sono certo.$B$BPer adesso, però, dovremmo parlare d'altro.",
  reward = "Per ora sarò io il tuo mentore e la tua guida. Il mio dovere è insegnarti a interpretare non solo quello che ci dicono gli spiriti, ma anche le complessità e i segreti di The Emerald Dream.$B$BPiù imparerai e diventerai potente, più scoprirai sulla nostra trance del sonno. Intanto torna da me quando vuoi, e ti insegnerò quello che posso sulle vie della nostra gente.",
  en_title = "Verdant Sigil",
  en_obj = "Read the Verdant Sigil and speak to Mardant Strongoak, in the tree Aldrassil in Shadowglen.",
}
T[3121] = {
  title = "Una Strana Richiesta",
  desc = "Per cominciare qui mi serve una cosa, e ce l'ha Neeru Fireblade a Orgrimmar! Ha preparato un intruglio che mi occorre per il mio... be', vedrai.$B$BOra va' — a Orgrimmar. Tieni, porta con te quest'a shrunken head: l'ho promessa a Neeru in cambio delle erbe. Apparteneva a un povero nano in cui mi sono imbattuto nella foresta. Neeru ne sarà contento, ne sono sicuro.$B$BNeeru lo trovi nella Cleft of Shadow.",
  obj = "Porta lo Shrunken Head a Neeru Fireblade a Orgrimmar.",
  progress = "Sì?",
  reward = "Aspettavo che Uzer'i mi facesse avere questo...$B$BEcco, ti do la miscela di erbe che ho preparato per i suoi... be', esperimenti...",
}
T[3122] = {
  title = "Ritorno da Witch Doctor Uzer'i",
  desc = "Ecco le erbe, $N: portale a Witch Doctor Uzer'i.$B$BE digli, per favore, che dello shrunken head sono soddisfatto.",
  obj = "Consegna la Neeru's Herb Pouch a Witch Doctor Uzer'i in Feralas.",
  progress = "Hai parlato con Neeru?",
  reward = "Mi serve proprio questo per preparare il recipiente del muisek, $N. Presto vedremo se i miei ultimi incantesimi saranno potenti come speravo.$B$BUn momento, per favore: devo compiere il rituale e applicare le erbe.",
}
T[3123] = {
  title = "Mettere alla Prova il Recipiente",
  desc = "Sarà una prova; per il rituale che ho eseguito e per le tue capacità. Prendi questo recipiente, $N. Ti darà il potere di rimpicciolire una creatura e di catturarla dentro.$B$BRaggiungi le Hinterlands e cerca i Wildkin, creature che un tempo erano gli animali di Elune, la dea degli elfi della notte. I tuoi bersagli, $N, sono i bestiagufi feroci, quelli primitivi o i savage owlbeasts. Uccidine 10 e, prima che gli spiriti fuggano, rimpiccioliscili e catturali con il recipiente per muisek.",
  obj = "Raggiungi le Hinterlands e trova i Wildkin. Uccidine 10 e usa il Recipiente per Muisek per rimpicciolire e catturare i Wildkin caduti.$B$BPorta 10 Wildkin Muiseks e il Recipiente per Muisek a Witch Doctor Uzer'i a Feralas.",
  progress = "Sei $Griuscito:riuscita; a catturare i wildkin?$B$BSe ci riesci, saremo pronti a rimpicciolire e catturare il muisek delle creature di Feralas.",
  reward = "Quando una creatura muore di morte violenta, il suo muisek può fuggire in cerca di vendetta. Rimpicciolendo le creature come hai fatto tu, $N, il muisek non può scappare. Ora possiamo usarlo come vogliamo!",
}
T[3124] = {
  title = "Hippogryph Muisek",
  desc = "Hai dimostrato di essere $Gdegno:degna; di fiducia e capace di usare il recipiente per muisek, quindi ora vorrei che catturassi un'altra creatura.$B$BDa molti anni gli ippogrifi sono fedeli compagni degli elfi della notte; hanno spiriti leali e saldi.$B$BIl tuo compito è uccidere 10 frayfeather hippogryphs e poi, in fretta, rimpicciolirli e catturarli con il recipiente, così il loro muisek si conserva. Li troverai nell'High Wilderness, a sud di qui.",
  obj = "Uccidi 10 Frayfeather Hippogryphs di qualsiasi tipo, poi usa il Recipiente per Muisek per rimpicciolirli e catturarli.",
  progress = "Sei $Griuscito:riuscita; a catturare gli ippogrifi?",
  reward = "Se, dopo aver ucciso un animale, lasciassimo fuggire il suo muisek, potrebbe prendere la forma di una creatura ancora più grande, e non saremmo mai al sicuro dalla sua vendetta.$B$BTi ho affidato un compito pericoloso, $N, e ancora una volta l'hai portato a termine bene.",
}
T[3125] = {
  title = "Faerie Dragon Muisek",
  desc = "$N, ora devo farti catturare una creatura che a vederla può sembrare piuttosto fragile, ma quello che ci interessa davvero è il suo spirito potente. I faerie dragons di cui parlo hanno servito gli elfi della notte da alleati. Dobbiamo catturarne uno, perché anche l'orda possa trarre vantaggio da questa forza di spirito.$B$BEcco il muisek, $N. Uccidi 8 sprite darters o sprite dragons e cattura il loro muisek. Li troverai a ovest di qui.",
  obj = "Uccidi 8 Sprite Darters o Sprite Dragons. Usa il Recipiente per Muisek per rimpicciolire e catturare i Faerie Dragons caduti.",
  progress = "Sei $Griuscito:riuscita; a catturare il muisek dei faerie dragons?",
  reward = "Grazie, $N. Ora i poteri spirituali del drago fatato sono a nostra disposizione.$B$BSpero che tu sia $Gdisposto:disposta; a fare un altro lavoro per me.",
}
T[3126] = {
  title = "Treant Muisek",
  desc = "Il nostro prossimo bersaglio, $N, sono i wandering forest walkers che vagano per la foresta. Gli elfi della notte hanno arruolato i treants come alleati contro l'orda. Saranno pure lenti, ma che facciano da protettori non si può negare.$B$BPresto potremo usare questo potere a nostro vantaggio.$B$BTrova 3 wandering forest walkers; uccidili, poi rimpiccioliscili e catturali con il recipiente per muisek.",
  obj = "Uccidi 3 Wandering Forest Walkers. Usa il Recipiente per Muisek per rimpicciolire e catturare i Treants caduti.",
  progress = "Sei $Griuscito:riuscita; a catturare i wandering forest walkers?",
  reward = "Grazie, $N. Ci manca poco per completare la nostra collezione di muisek.",
}
T[3127] = {
  title = "Mountain Giant Muisek",
  desc = "L'ultima cosa che ti chiederò è di andare a nord-ovest a trovare il nemico finale.$B$BI mountain giants hanno lasciato le montagne per aiutare gli elfi della notte quando la legione infuocata è comparsa nel mondo. Li riconoscerai dalla mole enorme e dal terreno che comincia a tremare mentre attraversi il loro territorio di roccia.$B$BNon vedo l'ora di sfruttare un potere così grande. Uccidi 7 mountain giants, poi cattura il loro potente muisek con il recipiente per muisek.",
  obj = "Uccidi 7 Land Walkers o Cliff Giants. Usa il Recipiente per Muisek per rimpicciolire e catturare i Mountain Giants caduti.",
  progress = "Sei $Griuscito:riuscita; a catturare i mountain giants?",
  reward = "Immagina quante possibilità ci dà quello che abbiamo ora, $N. Con i materiali che hai raccolto potrò imprigionare per sempre il muisek di queste creature in qualunque cosa io voglia.",
}
T[3128] = {
  title = "Materiali Naturali",
  desc = "Per portare a termine la mia impresa mi serviranno un po' di materiali... Puoi pensarci mentre fai gli altri compiti che ti darò.$B$BMi serve uno splintered log preso da un treant di Feralas. Poi degli Encrusted minerals, che trovi sui mountain giants e sui faerie dragons a ovest. Il resilient sinew invece lo prendi dalle bestie-gufo di Hinterlands o dagli ippogrifi di Feralas. E per finire mi servono tanti metallic fragments: puoi prenderli da una qualsiasi delle creature che ti ho nominato.",
  obj = "Porta 2 Splintered Logs, 6 Encrusted Minerals, 20 pezzi di Resilient Sinew e 40 Metallic Fragments a Witch Doctor Uzer'i a Camp Mojache.",
  progress = "Sei $Griuscito:riuscita; a raccogliere i materiali che mi servono?",
  reward = "Eccellente! Con questi materiali e il muisek dovremmo ottenere proprio i risultati che speravamo.",
}
T[3129] = {
  title = "Armi dello Spirito",
  desc = "Infondere il muisek nelle armi è un procedimento difficile. Ma adesso ho tutti i materiali che servono e il muisek delle creature che hai catturato, quindi posso cominciare. Aspetta, per favore: torno tra un momento.",
  obj = "Witch Doctor Uzer'i vuole che tu aspetti un momento mentre prepara le armi.",
  reward = "Come ti avevo promesso, $N, puoi scegliere. Il muisek delle creature è stato sigillato per sempre nel potere di queste armi.$B$BOra puoi usare la loro energia come se fosse tua. Usala bene.",
}
T[3130] = {
  title = "Contro gli Hatecrest",
  desc = "Ora ti mando dal mio secondo in comando, Latronicus, che finora ha seguito da vicino le forze dei naga. Io resterò qui a valutare la situazione dei naga nel suo insieme: per quanto vorrei impegnare contro di loro tutte le nostre forze, lasciare la roccaforte esposta a un attacco diretto dell'Orda — o peggio — non mi sembra la scelta migliore.$B$BComunque, Latronicus ti aspetta. Finora hai fatto un buon lavoro, $N: continua così.$B$BPuoi andare.",
  obj = "Fai rapporto a Latronicus Moonspear a Feathermoon Stronghold.",
  reward = "Eccellente, $N — in chi lavora con me apprezzo lo spirito del \"si può fare\".$B$BGeneral Feathermoon mi ha incaricato di affrontare direttamente i naga, e i miei piani sono due: primo, indebolire le loro forze, nel numero e nel comando; secondo, scoprire che cosa stanno tramando nelle rovine. Con il tuo aiuto contrasteremo la presenza dei naga senza sacrificare la sicurezza della roccaforte nel suo insieme.",
  en_title = "Against the Hatecrest",
  en_obj = "Report to Latronicus Moonspear in Feathermoon Stronghold.",
}
T[3141] = {
  title = "Loramus",
  desc = "Vuoi combattere i demoni, dunque? Allora faresti bene ad ascoltare la mia storia.",
  obj = "Ascolta Loramus Thalipedes mentre racconta la sua storia.",
  progress = "Non interrompermi, $R.",
  reward = "E sia...",
}
T[3161] = {
  title = "Gahz'ridian",
  desc = "$N, sono uno scienziato, ma sotto sotto sono anche un cacciatore di tesori!$B$BTanto tempo fa, quando questa terra era occupata dai troll, loro hanno fatto una gran quantità di ornamenti a immagine di Gahz'rilla, un'idra che adoravano come una divinità. Li hanno scolpiti in un elemento che io chiamo \"Gahz'ridian\", dal nome del dio idra.$B$BQualcuno l'ho trovato anch'io, ma me ne servirebbero altri da studiare — riusciresti a trovarmene qualcuno?$B$BHo perfino inventato un rilevatore che fa diventare la ricerca del Gahz'ridian un gioco da ragazzi! Basta indossarlo e si comincia!",
  obj = "Marvon Rivetseeker a Tanaris vuole che tu raccolga 30 Gahz'ridian Ornaments.",
  progress = "Qualche problema?$B$BIl Gahz'ridian si trova praticamente dappertutto a Tanaris, $N, quindi continua a cercare!",
  reward = "Perfetto; per i miei studi questi ornamenti sono l'ideale. Grazie mille dell'aiuto, $N.$B$BOh, mi ridai l'elmo?",
}
T[3181] = {
  title = "Il Corno della Bestia",
  desc = "Il gigantesco corno è pieno di graffi e crepe. Nella superficie ruvida è conficcato uno strano oggetto di metallo.$B$BGuardando meglio, ti accorgi che il metallo è in realtà una testa d'ascia rotta. Sopra ci sono incise queste parole:$B$BProprietà di Mountaineer Pebblebitty.$B$BQuando provi a estrarla, va in mille pezzi.$B$BUps!",
  obj = "Porta il Margol's Gigantic Horn a Mountaineer Pebblebitty.",
  progress = "No, non aprirò il cancello.",
  reward = "Cos'hai lì? Un falso, è evidente!$B$BMi sono trovata faccia a faccia con Margol e so per certo che il suo corno è grande almeno otto volte quello che hai in mano, $N. Probabilmente l'hai preso a uno stormsnout nei Barrens. No, $Gsignore:signora;, non puoi fregare Pebblebitty!",
}
T[3201] = {
  title = "Finalmente!",
  desc = "Ma ti pare che Pebblebitty abbia dubitato che il corno fosse autentico? Detto fra noi, secondo me è solo gelosa. So che ci teneva davvero a uccidere quella bestia con le sue mani, con la storia dell''incidente' e tutto il resto.$B$BQuindi ti serve una proof of deed? Con il contributo che hai appena dato al museo, nessun problema.$B$B<Curator Thorius comincia a compilare un grande documento.>$B$BEcco fatto! Puoi riportarla a Pebblebitty.",
  obj = "Riporta la Proof of Deed a Mountaineer Pebblebitty.",
  progress = "Non ci credo.",
  reward = "Non capisco come qualcuno debole come te abbia sconfitto Margol, ma i patti sono patti. Ecco la chiave.$B$BSe dopo questa storia ti succede qualcosa, la colpa sarà solo tua.",
}
T[3321] = {
  title = "Hai Perso Questo?",
  desc = "Hai fatto molto per l'Ordine, $N. Una persona qualunque, davanti a tutta la dedizione che ci vuole per arrivare fin qui, si sarebbe arresa. Né io né Galvan abbiamo dubbi: sei $Guno:una; di noi.$B$BPer questo credo che tu meriti una piccola ricompensa. Niente di che, solo un monile. Le sue proprietà forse le conosci già, perché credo proprio che all'inizio sia stato questo a portarti da noi.",
  obj = "Aspetta che Trenton finisca il suo lavoro.",
  progress = "Oggi chiudiamo la celebrazione del tuo impegno verso l'Ordine.",
  reward = "Alzati e sii $Griconosciuto:riconosciuta;, $N, $Gfabbro:fabbra; di The Mithril Order.",
}
T[3341] = {
  title = "Porre Fine",
  desc = "Nelle Barrens c'è un orribile groviglio di rampicanti chiamato Razorfen Downs. Dalle prime osservazioni erano emerse poche minacce, ma le ultime scoperte sono molto più gravi...$B$BI verrospini di Razorfen Downs si sono alleati con lo Scourge. Ora a governarli è un Lich di nome Amnennar the Coldbringer, che con il potere della sua immensa mente controlla ogni loro mossa.$B$BAmnennar ha un legame telepatico diretto con Ner'zhul, e quel legame dobbiamo spezzarlo, $N. Bisogna porre fine all'Araldo del Freddo.",
  obj = "Andrew Brownell vuole che tu uccida Amnennar the Coldbringer e ne riporti il teschio.",
  progress = "È una faccenda della massima importanza, $N. Dobbiamo fermare ogni tentativo dello Scourge di rinforzare i suoi ranghi.",
  reward = "Un Lich è di una lealtà incrollabile, $N. Fa' sapere loro che una lealtà così li porterà solo alla distruzione.",
  en_title = "Bring the End",
  en_obj = "Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.",
}
T[3362] = {
  title = "Thistleshrub Valley",
  desc = "La Thistleshrub Valley, l'hai mai vista? Posto parecchio pericoloso, $N.$B$BDi quelle strane bestie che ci stanno laggiù proprio non mi fido! Gnarled thistleshrubs e thistleshrub rootshapers, mi pare si chiamassero così...$B$BComunque, nella valle ci voglio entrare, ma con tutti quei thistleshrub in giro di tornarci non se ne parla. Ed è qui che entri in gioco tu — fanne fuori un po' e magari ci faccio un pensierino. Che ne dici, $N? Mi dai una mano?",
  obj = "Tran'rek a Gadgetzan vuole che tu uccida 8 Gnarled Thistleshrubs e 8 Thistleshrub Rootshapers.",
  progress = "Quel cactus nella valle vorrei vederlo un po' più da vicino... Perciò lasciane qualche pezzo intero, eh?",
  reward = "Sono grossi così? Forse mi tocca rivedere il piano...$B$BPerò la tua parte dell'accordo l'hai rispettata, quindi ecco quello che ti avevo promesso.",
}
T[3363] = {
  title = "Corrupted Songflower",
  progress = "Quella che hai trovato sembra una pianta di songflower, malata e corrotta, e manda un odore pungente e malsano. Per tornare com'era, ha un disperato bisogno di cure.",
  reward = "Sul songflower applichi un po' di unguento per piante Cenarion, e la pianta comincia subito a perdere l'aspetto corrotto: rifiorisce, rigogliosa e sana.",
}
T[3366] = {
  title = "La Glowing Shard",
  desc = "La scheggia è di un verde brillante e, per quanto solida, sembra che appena sotto la superficie vortichi del fumo. Non riesci a staccare lo sguardo dalle profondità del cristallo, e intanto sai che ha qualcosa di molto inquietante.$B$BForse dovresti cercare a Ratchet qualcuno che sappia dirti di più su questa strana scheggia.",
  obj = "Raggiungi Ratchet per scoprire il significato del Nightmare Shard.",
}
T[3367] = {
  title = "Le Pietre di Suntara",
  desc = "<Dorius geme.>$B$BSono ferito grave, $R. Sono... stordito... Mi gira tutto intorno... Sanguino... dentro.$B$BDevo rientrare a Ironforge. Aiutami, $N.",
  obj = "Aiuta Dorius a tornare a Ironforge.",
  progress = "Non ce la farò...",
  reward = "A Dorius è caduta questa lettera quando gli hanno sparato.",
}
T[3368] = {
  title = "Le Pietre di Suntara",
  desc = "Fratello,$B$Bse leggi questa lettera, io non ci sono più. Non so come ti sia arrivata, ma ringrazia e ricompensa chi te l'ha portata.$B$BQuanto alle pietre: esistono, e ce le hanno i Dark Irons. Il loro capo, Lathoric the Black, ne usa il potere per rendere schiava la mia squadra di scavo. Li hanno portati al calderone. Hanno la mente distorta, e lavorano giorno e notte per finire una cosa chiamata Obsidion.$B$BAiutali, fratello. È l'ultimo desiderio di un morto.$B$B-Dorius",
  obj = "Porta la Singed Letter a Thorius a Ironforge. Si trova in Hall of Explorers.",
  progress = "<Thorius singhiozza.>",
  reward = "<Thorius si asciuga il viso.>$B$BIn nome della Luce, il suo desiderio sarà esaudito. Lo giuro.",
}
T[3369] = {
  title = "Negli Incubi",
  desc = "Questo frammento custodisce grandi segreti; è l'essenza pura di The Emerald Dream. Eppure quello che vedo dentro non è un sogno; una visione così la si chiamerebbe un incubo.$B$BNon voglio allarmarti, $N, ma credo sia meglio che tu porti al più presto questo frammento a un druido saggio.$B$BDevi cercare Hamuul Runetotem, sull'Elder Rise. Va' a Thunder Bluff. Di più non posso dirti.",
  obj = "Porta il Nightmare Shard a Hamuul Runetotem, su Elder Rise.",
  progress = "Posso aiutarti in qualcosa?",
  reward = "Ti manda Falla? Bene bene, vediamo questo frammento di cui, a sentire te, lei era così restia a parlare...$B$B<Hamuul scruta il frammento>$B$BOh... non avevo... Be'.$B$B$N, grazie di avermelo portato. Però, ti avverto, parlare di cose del genere non è saggio. Sono faccende di cui non dovresti occuparti.$B$BDiciamo solo che in The Emerald Dream le cose non stanno come pensavamo...$B$BForse un giorno le nostre strade si incroceranno di nuovo.",
  en_title = "In Nightmares",
  en_obj = "Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise.",
}
T[3370] = {
  title = "Negli Incubi",
  desc = "Questo frammento custodisce grandi segreti; è l'essenza pura di The Emerald Dream. Eppure quello che vedo dentro non è un sogno; una visione così la si chiamerebbe un incubo.$B$BNon voglio allarmarti, $N, ma credo sia meglio che tu porti al più presto questo frammento a un druido saggio...$B$BDevi cercare Mathrengyl Bearwalker, nel Cenarion Circle. Va' a Darnassus. Di più non posso dirti.",
  obj = "Porta il Nightmare Shard a Mathrengyl Bearwalker a Darnassus.",
  progress = "Posso aiutarti in qualcosa?",
  reward = "Ti manda Falla? Bene bene, vediamo questo frammento di cui, a sentire te, lei era così restia a parlare...$B$B<Mathrengyl scruta il frammento>$B$BOh... non avevo... Be'.$B$B$N, grazie di avermelo portato. Però, ti avverto, parlare di cose del genere non è saggio. Sono faccende che spettano soltanto ai druidi Cenarion.$B$BDiciamo solo che in The Emerald Dream le cose non stanno come pensavamo...$B$BForse un giorno le nostre strade si incroceranno di nuovo.",
  en_title = "In Nightmares",
  en_obj = "Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus.",
}
T[3371] = {
  title = "Giustizia Nanica",
  desc = "Ho un buco al posto del cuore, $N, un vuoto. Non mi riprenderò tanto presto dalla perdita di Dorius. Devo fare in modo che il suo ultimo desiderio si avveri — chi l'ha ucciso a sangue freddo va consegnato alla giustizia.$B$BTorna nella Searing Gorge ed esaudisci la sua ultima richiesta: libera i suoi uomini.",
  obj = "Torna a Searing Gorge e trova la squadra archeologica di Dorius.",
  reward = "Non pensare a me, aiuta gli altri.",
}
T[3372] = {
  title = "Liberali",
  desc = "Liberali, $R. Anche quando il corpo non regge più, il potere di Suntara li obbliga a finire il loro lavoro.$B$BLa chiave è l'altare di Suntara. Va' a nord-ovest; sulle colline sopra la grotta... quelli del Twilight's Hammer fanno la guardia a una reliquia. Recuperala e mettila sull'altare di Suntara.$B$B<Il dying archaeologist crolla.>",
  obj = "Trova il Mysterious Artifact sorvegliato dai Twilight's Hammer Idolaters nel quadrante nord-occidentale di Searing Gorge.",
  progress = "L'altare è vuoto.",
  reward = "Metti il mysterious artifact sull'altare di Suntara.",
}
T[3373] = {
  title = "L'Essence of Eranikus",
  desc = "Appena tocchi la gemma, una voce profonda ti risuona nella mente.$B$B\"Ascolta la mia supplica, mortale. Sono Eranikus of the Green Dragonflight, custode di questo tempio maledetto. Dovevo impedire ai troll di far tornare quell'abominio di un dio, e per ora ho fallito. Mentre infondo una parte della mia essenza in questa gemma, sento la presa sul Sogno sprofondare nel caos. Ti prego — metti questa gemma nella fonte dell'essenza della mia tana e lascia che la nostra magia mi purifichi la mente dalla contaminazione, perché io possa riposare.\"",
  obj = "Metti l'Essence of Eranikus nell'Essence Font di questa tana, in Sunken Temple.",
  progress = "Mentre ti avvicini alla fonte dell'essenza di cui ti ha parlato Eranikus, la sua voce torna a raggiungerti nella mente.$B$B\"Sì, mortale, questa fonte dell'essenza redimerà la parte della mia mente infusa nella gemma, quella ancora pura. Metti la gemma nella fonte e lascia che la magia del Green Dragonflight purifichi il mio essere dalla corruzione e dalla contaminazione. Solo allora troverò la vera liberazione, e solo allora lo Stormo potrà tornare a vegliare sugli Atal'ai.\"",
  reward = "Metti la gemma nella fonte dell'essenza.$B$B\"Grazie, mortale, hai — no... questo, questo non può essere! No! La corruzione di questo dio maledetto contamina persino la santità di una fonte dell'essenza del Green Dragonflight! No, ti prego, sento che l'essenza mi viene strappata via! IL DOLORE! Sento la morsa di un incubo eterno che mi afferra...\"$B$B\"Mortale, ti scongiuro! Trova un membro del Green Dragonflight che fermi tutto questo... aiutami... sono incatenato nell'oscurità... per sempre nell'agonia... ti prego, non torturare...\"",
}
T[3374] = {
  title = "L'Essence of Eranikus",
  desc = "Attivi la Pietra del Giuramento e, attraverso la pietra, Itharius ti parla direttamente nella mente.$B$B\"Se accetti l'incarico affidato a questa Pietra del Giuramento, ti impegni a sostenere la mia causa e quella del Ysera's Dragonflight: redimere l'anima corrotta di Eranikus. Il primo sacrificio, uno dei tanti che di certo faremo tu e io, sarà consegnarmi la gemma che tiene incatenato quel che resta della parte libera della psiche di Eranikus.\"$B$B\"Fallo, $N, e lavoreremo insieme per redimere un'anima che lo merita.\"",
  obj = "Porta l'Oathstone of Ysera's Dragonflight e l'Essence of Eranikus Incatenata a Itharius nella Swamp of Sorrows. È lì che sceglierai se aiutare il Ysera's Dragonflight o no.",
  progress = "Eccoci a un altro bivio, $N: è giunto il momento di una nuova scelta. Che cosa decidi, mortale?",
  reward = "Hai fatto la tua scelta, e così ha inizio. Finora hai deciso come ritengo giusto; d'ora in poi saranno le tue azioni e le tue imprese a dire se continuerà a essere così.",
  en_title = "The Essence of Eranikus",
  en_obj = "Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows.  It is there that you will make your choice to aid Ysera's Dragonflight or not.",
}
T[3375] = {
  title = "Fiala di Ricambio",
  desc = "Ehm... ti serve un'altra phial of scrying? Stai scherzando, vero? Che fine ha fatto la prima?! Qui ci aspetta un sacco di lavoro, $R. Quelle fiale non crescono sugli alberi! Magari, anzi: andrei a coglierne una, visto che un'altra non ce l'ho!!$B$BEcco cosa mi serve per fartene una: una mana potion, un pezzo di carbone e un po' di sweet nectar. Non domandarmi perché: tu portami quello che ti chiedo e te ne farò una nuova.",
  obj = "Porta una Mana Potion, del Coal e dello Sweet Nectar a Talvash del Kissel a Ironforge per avere una fiala che sostituisca la Talvash's Phial of Scrying.",
  progress = "Per fare un'altra fiala ho bisogno di una mana potion, di un pezzo di carbone e di un po' di sweet nectar.$B$BE, a quanto pare, di un sacco di pazienza.",
  reward = "$GIl potente avventuriero:La potente avventuriera; mantiene la parola. Evviva me. A proposito, ho mentito — un'altra fiala ce l'avevo. Uff, prendila.$B$BBeh, cosa ti aspettavi?! \"Oh, ecco, prendine un'altra! Sono solo uno sciocco qualunque che non ha niente di meglio da fare che distribuire congegni magici di comunicazione agli avventurieri!\" Però stai $Gtranquillo:tranquilla;: con quello che mi hai dato potrò farti un'altra fiala quando perderai anche questa.$B$BTi prego, dimostrami che mi sbaglio e non perdere quella nuova, d'accordo?",
}
T[3377] = {
  title = "Prayer to Elune",
  desc = "Mi aiuterai, mortale? Allora ascolta la mia storia.",
  obj = "Ascolta la storia di Zamael.",
  progress = "Lascia che finisca la mia storia.",
  reward = "Qui, in questa gabbia, ho accettato il mio destino. Ma la preghiera va ritrovata.",
}
T[3378] = {
  title = "Prayer to Elune",
  desc = "Mi aiuterai, mortale? Troverai la preghiera a Elune?$B$BTe l'ho detto: la preghiera era incisa su una tavoletta d'oro, e deve averla con sé uno di questi furfanti che adorano gli idoli.$B$BSe riesci a recuperarla, portala ad Astarii Starseeker, a Darnassus. Dopo le innumerevoli malvagità che ho compiuto contro questo mondo e i suoi abitanti, poco importa che la mia fede si sia riaccesa: ma la mia preghiera deve essere ascoltata. Essere assolto? È l'ultima cosa che mi aspetto.",
  obj = "Trova la Prayer to Elune e portala ad Astarii Starseeker a Darnassus.",
  progress = "Che cosa ti porta al Tempio della Luna, $N?",
  reward = "Questa sera Elune ti sorride, $N: le hai restituito un'anima perduta. Accetta questo, ti prego, in segno della nostra gratitudine.",
}
T[3379] = {
  title = "Tessitore d'Ombra",
  desc = "Per la shadow silk, i ragni della Searing Gorge sono una fonte preziosissima. E sai bene quanto gli artigiani del nostro mestiere vadano in cerca della shadow silk.$B$BDa poco un gruppo di bracconieri ha invaso queste terre e sta facendo strage di ragni, senza curarsi minimamente delle conseguenze a lungo termine. Perciò il primo compito che ti chiedo è semplice: trovali... e falli fuori.$B$BComincia a cercarli a nord.$B$BSe hai bisogno d'aiuto, parla con Raze.",
  obj = "Uccidi il gruppo di Shadow Silk Poachers che si aggira in Searing Gorge. Nilith ha motivo di credere che siano cinque quelli da sterminare. Torna da Nilith in Searing Gorge quando avrai finito.",
  progress = "Che informazioni mi porti?",
  reward = "Ottimo lavoro, $N.$B$BSono certa che un pezzo di tessuto d'ombra come questo non l'hai mai visto.",
}
T[3380] = {
  title = "Il Sunken Temple",
  desc = "In questo mondo ci sono spiriti inquieti, $N. Spiriti corrotti dall'isolamento, legati a un male antico...$B$BHo sentito di un posto nelle profondità della terra — confinato laggiù da poteri più grandi di tutti quelli che ho mai visto.$B$BSe vuoi sapere di più su questo luogo, il Sunken Temple, cerca un goblin che si chiama Marvon Rivetseeker. Ha studiato tanti luoghi antichi del mondo e l'ultima cosa che si sa di lui è che ha lasciato casa sua a Ratchet per fare ricerche sulle rovine troll di Tanaris.",
  obj = "Trova Marvon Rivetseeker a Tanaris.",
  reward = "Sì, il Sunken Temple: posso dire di averlo visto con i miei occhi. Vuoi saperne di più, forse?$B$BHai l'aria $Gdi un tipo avventuroso:di una tipa avventurosa; — so delle cose che ti potrebbero incuriosire...",
}
T[3381] = {
  title = "Un Incontro con il Maestro",
  desc = "Ah, $Gun giovane:una giovane; $R $Gvenuto:venuta; a parlare con Sanath. Che giornata meravigliosa! Sono davvero onorato che tu mi conceda la grazia della tua presenza. Grazie!$B$BTi prego... non essere così arrogante da pensare che il mio sarcasmo fosse un complimento. Mettiamo in chiaro una cosa: non mi piaci. Ma questa chiacchierata non riguarda noi — riguarda il mio maestro.$B$BPortami un paio di piume di ippogrifo per le mie frecce e ti darò il permesso di vederlo. Mi ha chiesto di mandargli gli avventurieri che si fossero dimostrati abbastanza degni.",
  obj = "Porta 2 Undamaged Hippogryph Feathers a Sanath Lim-yo in Azshara se vuoi parlare con il suo maestro.",
  progress = "Sto qui per volere del mio maestro, e per il trasporto fino alla sua torre mi è concesso di chiedere il prezzo che voglio. Per ora a ogni viaggiatore chiedo soltanto le due piume, così posso continuare a fare le mie frecce inconfondibili.$B$BSe non stai $Gattento:attenta;, alzo il prezzo. Che ne dici di mezza dozzina di monete d'oro?$B$BSì, immaginavo. Bada a come ti comporti e il prezzo resta quello.",
  reward = "Due piume, proprio come avevo chiesto. E nemmeno male.$B$BAllora, sei $Gpronto:pronta;? Basta una parola e parti.$B$BOh, e te lo ripeto, bada a come ti comporti... il mio maestro non vede di buon occhio gli imbecilli, ma con chi lo soddisfa è molto generoso.",
}
T[3382] = {
  title = "Un Equipaggio Sotto Attacco",
  desc = "Eravamo appena al largo della costa e cercavamo un rifugio sicuro dove gettare l'ancora. Il sole era tramontato da un'ora al massimo quando ci hanno attaccati... quei maledetti naga!$B$BNon so cosa cercassero, ma di sicuro non l'hanno trovato — sono già tornati una volta. Un paio delle mie vedette sorvegliano l'ingresso della valle, per darci l'allarme in tempo quando arriverà il prossimo attacco.$B$BMi spiace che tu sia $Garrivato:arrivata; proprio adesso, $N, ma non dipende da me.$B$BSei $Gpronto:pronta; per la battaglia della tua vita?",
  obj = "Difendi Captain Vanessa Beltis, il suo equipaggio e i passeggeri dell'Horizon Scout dall'attacco dei naga. Captain Vanessa Beltis deve sopravvivere.",
  progress = "Ci aspetta una battaglia dura...",
  reward = "Ce l'hai fatta! Grazie! È stata di sicuro una delle battaglie più brutali che abbia mai combattuto. Non so come ringraziarti.$B$BVorrei solo che più uomini del mio equipaggio fossero usciti vivi da questa prova.$B$BTi chiederei di parlare con i passeggeri dell'Horizon Scout che sono sopravvissuti. Alcuni avevano affari in zona e, se sei $Gdisposto:disposta;, potrebbero avere qualche richiesta per te. Grazie ancora di tutto l'aiuto.",
}
T[3385] = {
  title = "The Undermarket",
  desc = "Si fanno chiamare The Undermarket: mercanti senza scrupoli, pronti a vendere, trasportare, scambiare, a fare praticamente qualsiasi cosa, purché il prezzo sia giusto.$B$BE c'è di peggio, $N: hanno messo su una base operativa proprio qui, nella Searing Gorge. A dirigere l'operazione è Trade Master Kovic, che ha stretti legami con i nani Dark Iron della regione.$B$BDobbiamo colpire duro e far arrivare un messaggio ai loro capi. Uccidi Trade Master Kovic e il suo tirapiedi Clunk, e quando avrai finito riportami la sua trader's satchel.$B$BAl Calderone!",
  obj = "Uccidi Trade Master Kovic e il suo tirapiedi Clunk. Recupera la Trader's Satchel dal suo cadavere e portala a Nilith.",
  progress = "Il Maestro del Commercio è ancora vivo?",
  reward = "Hai assestato un colpo decisivo a The Undermarket: prima di mandare altri scagnozzi nella gola, i loro capi ci penseranno due volte.$B$BAh, e nella trader's satchel non ho trovato niente di utile. Qualunque cosa ci trovi, puoi tenertela.",
}
T[3402] = {
  title = "The Undermarket",
  desc = "Voglio che la notizia della sconfitta di Kovic la porti tu, di persona, a Vizzklick, a Gadgetzan. Sarà così felice di sapere che Kovic è morto che, ne sono certa, ti darà una ricompensa grandiosa.",
  obj = "Parla con Vizzklick a Gadgetzan.",
  reward = "Kovic ucciso??! Che giorno glorioso, $N! Per anni quel furfante ha mandato avanti i suoi loschi traffici sottobanco, facendo concorrenza sleale a mercanti onesti e laboriosi di tutto il mondo.$B$BPer un'impresa così ti meriti una bella ricompensa! E una bella ricompensa avrai!",
}
T[3421] = {
  title = "Viaggio di Ritorno",
  reward = "Ora ti riporto all'accampamento di Sanath.$B$BNon fare caso ai suoi modi sgarbati — è maleducato con tutti, tranne che col maestro. Forse un giorno imparerà la lezione.",
}
T[3441] = {
  title = "Castigo Divino",
  desc = "Ascolta la mia storia, $Gavventuriero:avventuriera;.",
  obj = "Ascolta Kalaran Windblade mentre racconta la sua storia.",
  progress = "Lasciami finire, mor... $R.",
  reward = "Ne hai sentito abbastanza? Sei $Gpronto:pronta; ad agire?",
}
T[3442] = {
  title = "La Fiamma Perfetta",
  desc = "Hai preso la decisione giusta, $N.$B$BDobbiamo colpire dove faremo più danno: le quattro torri di guardia.$B$BQuando bruceranno tutte e quattro, potremo lanciare l'offensiva prima che facciano in tempo a reagire.$B$BPer incendiare le torri ti servirà lo strumento giusto, e per costruirlo occorrono alcuni materiali.$B$BPortami quattro hearts of flame e quattro sfere di golem oil, e ne ricaverò la torcia della fiamma perfetta.$B$BTi conviene prendertela prima di tutto con i golem e gli elementali di queste terre.",
  obj = "Raccogli 4 Hearts of Flame e 4 sfere di Golem Oil e porta gli oggetti a Kalaran Windblade.",
  progress = "Hai raccolto i materiali?",
  reward = "Ben fatto, $N. Siamo quasi pronti.",
}
T[3443] = {
  title = "Forgiare l'Asta",
  desc = "Per contenere la fiamma perfetta ci serviranno un'asta e un involucro, e per prima cosa devi trovare l'asta giusta.$B$BNel calderone, i sorveglianti e gli schiavisti Dark Iron usano armi di torio incantato, una lega durissima. Se mi porti otto thorium plated daggers, posso scomporne la lega e forgiarne di nuovo un'asta.",
  obj = "Porta 8 Thorium Plated Daggers a Kalaran Windblade.",
  progress = "Otto, $N. Me ne servono otto!",
  reward = "Sei $Gun:una; manovale eccezionale, $N. Non hai mai pensato di cambiare mestiere? $GUn:Una; detective, magari? $GRaccoglitore:Raccoglitrice; di cianfrusaglie? Oh, ci sono: uno di quegli gnomi sciocchi che strisciano sulle spiagge di Azeroth con i loro aggeggi per rilevare i metalli, a caccia di tesori perduti. Sì, sarebbe proprio il posto giusto per te.",
}
T[3444] = {
  title = "Lo Stone Circle",
  desc = "Una volta sono entrato nelle sale minacciose del Sunken Temple. Il male di quel posto penetra in chiunque ci metta piede: a stento sono riuscito a ritrovare l'uscita, facendomi strada nella melma che adesso ricopre i pavimenti. Ricordo solo che barcollavo in una grande sala circolare, piena di statue di serpenti...$B$BPoco tempo fa ho scoperto una pietra rotonda che sembrava portare impresso lo stesso simbolo del serpente. L'ho fatta imballare e spedire al mio laboratorio a Ratchet. Recuperala, e forse potrò dirti di più.",
  obj = "Recupera lo Stone Circle dal laboratorio di Marvon Rivetseeker a Ratchet.",
  progress = "Ratchet non è lontana da qui, $N. Non ci vorrà molto ad arrivarci.",
  reward = "Sì... È questa la pietra.$B$BAdesso mi sta tornando in mente tutto, $N...",
}
T[3445] = {
  title = "Il Sunken Temple",
  desc = "Ho sentito parlare di un luogo nelle profondità della terra — confinato laggiù da poteri più grandi di qualunque cosa io abbia mai visto.$B$BSe vuoi saperne di più su questo luogo, il Sunken Temple, cerca un goblin di nome Marvon Rivetseeker. Come me e Troyas, ha studiato molti luoghi antichi del mondo, e l'ultima cosa che si sa di lui è che ha lasciato casa sua a Ratchet per fare ricerche sulle rovine troll di Tanaris.$B$BBuona fortuna a trovarlo: da un po' non si hanno più sue notizie.",
  obj = "Trova Marvon Rivetseeker a Tanaris.",
  reward = "Sì, il Sunken Temple: posso dire di averlo visto con i miei occhi. Vuoi saperne di più, forse?$B$BHai l'aria $Gdi un tipo avventuroso:di una tipa avventurosa; — so delle cose che ti potrebbero incuriosire...",
}
T[3446] = {
  title = "Nelle Profondità",
  desc = "Dentro il tempio ho trovato una sala rotonda con sei balconate, e sul bordo di ognuna c'è una statua di serpente. Per curiosità ne ho spinta una per vedere cosa succedeva, ed era una trappola! Con l'esplosione per poco non ho fatto un volo mortale. Ero lì, steso sulla sporgenza, quando guardando giù ho notato un'altra statua in fondo alla sala; una specie di altare... di Hakkar, mi pare si chiamasse.$B$BCredo che il segreto sia quell'altare — devi portarci questo gettone, nel Sunken Temple.",
  obj = "Trova l'Altar of Hakkar nel Sunken Temple, nella Swamp of Sorrows.",
  progress = "Esaminando la statua noti sul fianco una rientranza grande proprio come il gettone che ti ha dato Marvon...",
  reward = "Spingi lo stone circle nell'apertura e senti che si incastra al suo posto.$B$BOra che la pietra è sistemata puoi andare avanti... ma cosa dovresti fare adesso?$B$BForse è il caso di esaminare meglio questo altare...",
}
T[3447] = {
  title = "Il Segreto del Cerchio",
  desc = "Ho i ricordi confusi, ma ti dirò quello che posso. Credo che il cerchio di statue nel Sunken Temple, per quanto pericoloso, custodisca il segreto per arrivare a un tesoro ancora più grande.$B$BDall'altare principale sono riuscito ad attivare una serie di luci. Se scopri cosa significano queste luci, penso che potresti svelare i segreti nascosti in questa sala.$B$BPerò ti avverto, $N. Nel tempio si annida un grande male, e con ogni probabilità qualunque cosa di valore è sorvegliata con zelo...",
  obj = "Entra nel Sunken Temple e scopri il segreto nascosto nel cerchio di statue.",
  reward = "Anche nella penombra del tempio, l'occhio dell'idolo scintilla vivido. È trasparente, e dietro si vede luccicare qualcosa. Lo sposti di lato, infili la mano nella statua e afferri quello che c'è dentro.$B$BOra il tesoro degli Atal'ai è tuo.",
}
T[3448] = {
  title = "Passare il Fardello",
  desc = "Da poco mi hanno affidato il compito di indagare su Azshara — una zona un tempo bellissima, abitata dagli elfi ai tempi in cui praticavano la magia. Adesso è più pericolosa che bella, ma questo non ci impedisce di cercare risposte sul nostro passato in ogni angolo.$B$BUn mio compagno, Tymor, si è offerto di darmi una mano a indagare sulla zona, visto che queste cose gli interessano in modo particolare.$B$BLo trovi nel suo posticino a destra dell'Hall of Mysteries, qui in città.",
  obj = "Parla con Tymor a Ironforge.",
  reward = "Ah, ti manda Karnik, vero? Mi aspettavo di avere presto sue notizie. Su Azshara ho scoperto cose meravigliose. Lo so che gli elfi della notte vivono incredibilmente a lungo, ma a volte tutti si scordano qualcuno degli eventi più... sfortunati della propria vita. Non lo dico per criticare, è solo un'osservazione.$B$BTanto tempo fa c'erano città costruite dagli elfi, piene di conoscenze sulla magia e su altre arti perdute. Io queste cose le studio, e così ho cominciato a indagare. Quello che ho trovato era davvero emozionante.",
}
T[3449] = {
  title = "Rune Arcane",
  desc = "Un tempo certi elfi veneravano la magia quanto Elune stessa. Alcuni dei loro maghi più potenti hanno creato rune e tavolette che riportavano le regole dell'arcano e le loro intuizioni sulle scoperte fatte, e le lasciavano in luoghi pubblici, perché chiunque potesse rifletterci sopra.$B$BMi piacerebbe tanto avere dei ricalchi di queste rune dalle Ruins of Eldarath. Il corredo apposta ce l'ho, ma a trovarle toccherà a te. Fai attenzione, però: l'Explorer's League non è la sola a interessarsi di Eldarath.",
  obj = "Usando il Drawing Kit, fai i ricalchi della Rune of Beth'Amara, della Rune of Jin'yael, della Rune of Markri e della Rune of Sael'hai, prima di dirigerti verso la piccola isola al largo della penisola meridionale di Azshara e fare segnale a Pilot Xiggs Fuselighter perché venga a prenderli.",
  progress = "Bene, bene, bene, felice di vedere che sei $Garrivato:arrivata; fin qui, $N. Li hai presi i ricalchi per Tymor?$B$BQuesto posto sarà anche pericoloso, ma lungo la costa non è successo granché. Forse c'entrano i naga che nuotano sott'acqua, ma non sono affari miei... io pattuglio i cieli.",
  reward = "Che bello vederti $Gsano e salvo:sana e salva;, $N. Spero non sia stata troppo dura.$B$BLi porto subito a Tymor, che sarà entusiasta di dare un'occhiata a questa roba.$B$BIl flare gun puoi pure buttarlo... tanto ormai non ti servirà più a niente, e io ne ho già uno nuovo.",
}
T[3450] = {
  title = "Un Ritiro Facile",
  desc = "Voglio che i calchi arrivino alla mia torre, ma non serve che ti faccia tutta quella strada. Li farò portar via in volo da Azshara.$B$BXiggs Fuselighter mi deve un favore o due e presto sarà da quelle parti — si è arruolato per pattugliare la costa. Prima di partire, va' a parlargli. Può darti un flare gun per fargli segnale. Quando avrai i calchi, va' dove ti dice lui e consegnaglieli, così potrà portarli alla mia torre sani e salvi. Dovrebbe essere nell'hangar di Military Ward.",
  obj = "Parla con Xiggs Fuselighter a Ironforge.",
  reward = "Cosa posso fare per te, $N? Adesso sono un po' preso a preparare la nave per un lungo viaggio. Sono passato a trovare qualche pilota di carri armati — mi servono dei wendigo manes per foderare la cabina di pilotaggio, e di solito gliene avanzano.$B$BUn minuto posso dartelo, se fai in fretta... uno dei ragazzi è appena partito per lo Steelgrill's Depot a vedere se i piloti di laggiù hanno dei manti in più per me.",
}
T[3451] = {
  title = "Segnale per il Ritiro",
  desc = "Ah, allora ti manda Tymor, eh? Già, gli devo un favore o due. Come dici? Ma guarda un po' quel diavoletto. Sì, una mano gliela posso dare. Quindi ti servono un flare gun e un posto... niente di più facile.$B$BAl largo della penisola meridionale di Azshara c'è un isolotto dove abbiamo allestito una piazzola di atterraggio. Prendi questo flare gun e usalo lì. Io vedo il segnale e passo a ritirare questo... qualunque cosa voglia lui.",
  obj = "Parla con Xiggs Fuselighter e fatti dare una Standard Issue Flare Gun a Ironforge.",
  reward = "Ecco il mio standard issue flare gun, e dopo aver sparato abbi pazienza — ha solo un paio di colpi, e potrei metterci un minuto ad arrivare da te, dipende da quanto sono al largo. Quando hai lanciato il razzo, guarda verso il mare.",
}
T[3452] = {
  title = "L'Involucro della Fiamma",
  desc = "Per la torcia manca un ultimo pezzo.$B$BSulle montagne a nord-ovest troverai un grande accampamento del Twilight's Hammer. Dicono che si portino dietro simboli e idoli in onore del loro dio, e forse sono incantati abbastanza da ricavarne un involucro magico. Portami anche un solo simbolo di Ragnaros e proverò a estrarne la magia per fare l'involucro.",
  obj = "Trova e porta uno Symbol of Ragnaros a Kalaran Windblade.",
  progress = "Senza una fonte adatta di energia arcana non si può completare la torch of retribution.",
  reward = "Il simbolo emana una magia immonda; per il nostro compito è perfetto.",
}
T[3453] = {
  title = "La Torch of Retribution",
  desc = "Dammi un momento per mettere insieme i pezzi e fare gli incantamenti necessari.",
  obj = "Aspetta che Kalaran Windblade completi la Torch of Retribution.",
  progress = "Non interrompere l'incanalamento.",
  reward = "Ti resta un ultimo compito da portare a termine.",
}
T[3454] = {
  title = "La Torch of Retribution",
  desc = "Ora la torcia va legata al suo proprietario. Prendila, $N.",
  obj = "Prendi la Torch of Retribution.",
  reward = "Afferri la torcia con tutte e due le mani; ondate di odio e di rabbia ti pulsano in tutto l'essere.",
}
T[3461] = {
  title = "Ritorno da Tymor",
  desc = "Tymor non mi ha dato niente per pagarti, quindi ti conviene parlarne con lui quando torni a Ironforge. Di certo sarà ancora a casa sua, nel Mystic Ward. Va' a bussargli e fatti pagare come si deve. Questo posto non è mica una scampagnata... poco ma sicuro.$B$BComunque, grazie ancora di averlo aiutato, e buona fortuna.$B$BAh, e il drawing kit a me non serve. Perché non lo riporti a Tymor quando passi da lui?",
  obj = "Riporta a Tymor il suo Drawing Kit, a Ironforge.",
  progress = "Sei $Gtornato:tornata;! Ottimo. Ce l'hai anche il mio drawing kit?",
  reward = "Magnifico! Sono proprio felice di sentirlo.$B$BNon vedo l'ora di andare nella mia torre a studiare quei ricalchi. Ti invidio tanto... andare in un posto come Azshara. Immagino sia il sogno di ogni studioso dell'arcano.$B$BBeh, di ricompensa non abbiamo mai parlato, visto che lavoravi solo per l'Explorer's League, ma qualcosa te lo meriti.",
}
T[3462] = {
  title = "Squire Maltrake",
  desc = "Va' a parlare con il mio emissario, Squire Maltrake. Ti dirà altro su come usare la Torch of Retribution.",
  obj = "Parla con Squire Maltrake.",
  reward = "Sei $Gpronto:pronta; a sferrare il colpo?",
}
T[3463] = {
  title = "Incendiale!",
  desc = "Ascolta bene, $N. Le quattro torri non si possono distruggere, ma con la torch of retribution puoi farle bruciare per moltissimo tempo: un fuoco che nessun elemento e nessuna forza riescono a domare.$B$BFinché bruciano, nessuna guardia o sentinella potrà prendere posto nelle vedette, e così la loro prima linea di difesa salterà.$B$BDevi entrare in ciascuna torre e usare la Torch of Retribution dentro le fortificazioni. Guardati dalle sentinelle d'élite dei Dark Irons, $N.",
  obj = "Dai fuoco alle North, South, East e West Sentry Towers usando la Torch of Retribution dentro ciascuno degli edifici.",
  progress = "Ti sei $Gperso:persa;, $N?",
  reward = "È glorioso! Non è forse glorioso, $Gsignore:signora;?",
}
T[3481] = {
  title = "Ninnoli...",
  desc = "Il forziere sembra chiuso a chiave.",
  obj = "Apri il forziere.",
  reward = "Il forziere si apre appena lo tocchi. Quanto formaggio ci sarà mai qui dentro? C'è un solo modo per scoprirlo.",
}
T[3483] = {
  title = "Segnale per il Recupero",
  reward = "Ah, ti serve un altro flare gun, eh? Si può fare.$B$BE non dimenticarti, la punta meridionale di Azshara. È un'isoletta trasformata in piattaforma di atterraggio. Se sei nel punto giusto, non puoi non vederla.",
}
T[3501] = {
  title = "Tutto Conta in Grandi Quantità",
  desc = "Una sfera perfetta di draenethyst forse non la troverai mai, ma esplorando queste terre scoverai senz'altro diversi frammenti imperfetti.$B$BDifficilmente Kum'isha riuscirà a tornare a casa con dei frammenti difettosi, ma i pezzi potrebbero servire ai draenei per altri scopi utili.$B$BRiportami tutti i frammenti di draenethyst difettosi che trovi, e ti ricompenserò.",
  obj = "Porta a Kum'isha gli Imperfect Draenethyst Fragments e ricevi una ricompensa per ognuno che consegni.",
  progress = "Hai avuto fortuna, esplorando?",
  reward = "Mi fai proprio schifo, $R. $GUn uomo adulto:Una donna adulta; che sbava davanti a un mucchio di cianfrusaglie? Pietoso! Prendi la ricompensa e sparisci dalla mia vista.",
}
T[3502] = {
  title = "Le Cianfrusaglie di un Draenei...",
  desc = "Beh, un tale sfoggio di avidità vorace mi fa venire la nausea.$B$BComunque, sulla tua dipendenza dalle cose materiali non mi soffermerò troppo.$B$BPer ogni imperfect draenethyst fragment che mi consegni, ti ricompenserò con altre cianfrusaglie: il mio mucchio si rimpicciolisce e il tuo cresce. Su Draenor si chiama 'vantaggio reciproco'.",
  obj = "Porta a Kum'isha gli Imperfect Draenethyst Fragments. Qualsiasi mostro nelle Blasted Lands potrebbe avere con sé un frammento.",
  progress = "Allora? Il draenethyst? Te lo ricordi?$B$B<Kum'isha chiude la mano a pugno e ti bussa sulla testa.>$B$BC'è nessuno in casa?",
  reward = "Mi fai proprio schifo, $R. $GUn uomo adulto:Una donna adulta; che sbava davanti a un mucchio di cianfrusaglie? Pietoso! Prendi la ricompensa e sparisci dalla mia vista.$B$BTi suona familiare? Dovrebbe, visto che lo ripeto mille volte al giorno.$B$BOh, quanto lo odio, questo mondo.",
}
T[3503] = {
  title = "Incontro con il Maestro",
  reward = "Un tempo potevo pretendere qualunque cosa da chi cercava il mio maestro. Adesso invece basta che tu lo chieda, e ti manderò da lui.$B$BLa cosa mi irrita, ma i suoi ordini non li discuto. Posso solo divertirmi a prendere in giro i vestiti ridicoli che porti o la tua faccia patetica. E anche questo mi annoia...$B$BMi annoiano persino queste chiacchiere! Vuoi vederlo o no, il mio maestro?",
}
T[3504] = {
  title = "Tradito",
  desc = "Donna traditrice e ladra! Così la chiamo io — e non sarà mai nient'altro!$B$BForse ho fatto un grave errore, $N: mi sono fidato di un'elfa del sangue. E, quel che è peggio, mi sono fidato di una donna!$B$BDiceva che ad Azshara c'erano grandi ricchezze... oggetti potenti. Bastava che mandassi con lei qualche guerriero a proteggerla, e ne avrei avuto una ricompensa. Be', alla fine lo sciocco sono io — li ha uccisi tutti.$B$BVoglio vendetta, $N, ma non posso permettermi di mandare nessun altro. Cerca Ag'tor a Valormok, a nord dell'Haldarr Encampment: ti dirà di più.",
  obj = "Consegna la Sealed Letter to Ag'tor ad Ag'tor Bloodfist ad Azshara.",
  progress = "Ah, allora Belgrom ha messo giudizio e si è deciso a mandare in nostro aiuto qualcuno che non è dei suoi, eh?$B$BIn questo accampamento c'era una dozzina di guerrieri, $N, e adesso sono tutti morti: li ha uccisi quella maga, Rimtori. Si è rigirata Belgrom come voleva... l'ha perfino sedotto. Non sono affari miei, ma detto fra noi è proprio una tentatrice. Sarà per questo che sono ancora qui ad aiutare Belgrom — probabilmente avrei fatto lo stesso anch'io.",
  reward = "Abbiamo mandato contro di lei e i suoi lavoratori tutto quello che avevamo, ma in battaglia sono forti. Nessuno si è preso la briga di tornare. Qualcuno sarà morto, immagino, ma altri, ne sono sicuro, sono scappati e basta... codardi.$B$BAdesso però sono arrivati i rinforzi, e forse qualcosa possiamo ancora farla. Magari riusciamo anche a punirla per aver mentito a Belgrom e averlo tradito.$B$BChe ne dici, ci stai?",
}
T[3505] = {
  title = "Tradito",
  desc = "Lo immaginavo.$B$BLa nostra crociata comincia contro i suoi lavoratori, sulle scogliere meridionali della penisola settentrionale di Azshara. Uccidili con furia sanguinaria — fagli capire che hanno tradito gli alleati sbagliati.$B$BDi lei per ora non preoccuparti — passa quasi tutto il tempo a perlustrare Azshara con le sue guardie del corpo. Quando avrai ucciso i lavoratori, sarebbe prudente trovare il suo accampamento personale: conviene sapere dove attaccarla. Lì potrebbe esserci qualcosa da usare per provocarla.",
  obj = "Uccidi 10 Blood Elf Reclaimers e 10 Blood Elf Surveyors prima di cercare l'accampamento della Magus Rimtori. Una volta trovato, cerca qualcosa che potrebbe essere importante per lei e che si possa usare per attirarla in uno scontro.",
  progress = "Sulla copertina di pelle nera il titolo del libro è impresso in foglia d'oro: Kaldorei Tome of Summoning. Lo apri e vedi che è molto vecchio, ma in condizioni eccellenti.$B$BTi pare che il testo sia scritto in qualche lingua antica... forse Kaldorei?$B$BL'istinto ti dice che dovresti tornare qui quando avrai finito di punire gli elfi del sangue per il loro tradimento.",
  reward = "Cominci a sfogliarlo e arrivi a una pagina segnata da una sottile striscia di seta nera.$B$BMentre cerchi di decifrare la scrittura, noti un diagramma in fondo a una delle pagine. Dai una rapida occhiata intorno e ti accorgi che i cristalli, il cerchio e perfino alcuni degli altri componenti a terra sono disposti in modo simile al diagramma.",
}
T[3506] = {
  title = "Tradito",
  desc = "Ci rifletti ancora un po' e ti vengono in mente alcune idee, una delle quali ti fa sorridere: forse distruggere i cristalli farebbe arrabbiare l'elfa del sangue che ha massacrato tanti orchi e tradito Belgrom?$B$BContinuando a decifrare la scrittura e le immagini, capisci che uno dei cristalli è legato al creatore del cerchio — gli altri a qualcosa di molto più sinistro.$B$BChiudi il libro e ti chiedi quale cristallo distruggere.",
  obj = "Distruggi il cristallo focalizzatore arcano legato alla Magus Rimtori, poi uccidila. In seguito, porta l'Head of Magus Rimtori ad Ag'tor Bloodfist ad Azshara.",
  progress = "Come procede il massacro dei traditori elfi del sangue, $N? Hai fatto qualche progresso?$B$BSpero che sia tu $Gquello:quella; abbastanza forte da mettere in ginocchio quella carogna! Con tutto ciò che ha fatto, merita solo una morte dolorosa!",
  reward = "RAR!! Incredibile!$B$BCe l'hai fatta! Belgrom ne sarà contento! Finalmente gli spiriti di decine dei nostri guerrieri potranno trovare pace. Grazie, $N.",
}
T[3507] = {
  title = "Tradito",
  desc = "Torna da Belgrom a Orgrimmar: vorrà vedere la testa con i suoi occhi! Noi torneremo lì a breve.$B$BAh, è proprio un bel giorno. Grazie per l'aiuto, $N.",
  obj = "Parla con Belgrom Rockmaul a Orgrimmar.",
  progress = "Mi ricordo di te, $C. Ti avevo chiesto di andare ad Azshara a distruggere quella donnaccia che mi ha tradito! Sembra che siano passate tante lune. Non dirmi che sono morti anche Ag'tor e gli altri!",
  reward = "AHAH! Guardati adesso, donna patetica! Sputo su quel che resta di te!$B$BGrazie, $N. Grazie dal profondo del cuore! È davvero un gran giorno!$B$BSe fosse in mio potere, ti darei un regno! Ma forse ti accontenterai di questo.$B$B<Belgrom abbassa lo sguardo sulla testa della maga che l'aveva tradito.>$B$BAhah! Stupida elfa del sangue, guardati adesso... in un sacco di iuta, senza più un corpo! Non avresti mai dovuto tradire Belgrom!",
}
T[3508] = {
  title = "Spezzare la Barriera",
  desc = "Sei $Gtemerario:temeraria;, $N. È una qualità ammirevole della tua gente — gettarvi alla cieca in battaglia quando le possibilità di vincere sono poche o nessuna. Ti aiuterò, se non altro per vedere cadere uno dei servitori di Razelikh.$B$BPer spezzare la barriera che avvolge i sottoposti di Razelikh ci vorrà tempo, e bisognerà recuperare artefatti rari.$B$BStai $Gfermo:ferma;: prima devo compiere il rituale dell'illuminazione, e quello che verrò a sapere mi aiuterà a forgiare armi di grande potere.",
  obj = "Aspetta che Loramus completi l'incantesimo dell'illuminazione.",
  reward = "Occorre scoprire il nome della bestia.",
}
T[3509] = {
  title = "Il Nome della Bestia",
  desc = "Il signore dei demoni e i suoi servitori si possono ferire in un modo soltanto: forgiando un'arma di potere che porti il suo vero nome.$B$BUna volta forgiata un'arma del genere, il demone e tutti quelli che comanda saranno vulnerabili.$B$BAd Azshara dimora una divinità minore, Lord Arkkoroc, e tu devi cercarlo. Ma stai $Gattento:attenta;: se ti scopriranno, i suoi servitori non si fermeranno davanti a nulla pur di distruggerti.$B$BPer informazioni come queste dovrai pagare un prezzo, non c'è dubbio.",
  obj = "Parla con Lord Arkkoroc ad Azshara. Comincia a cercare in riva all'acqua per trovare Temple of Arkkoran.",
  reward = "Un signore dei demoni?$B$B<Lord Arkkoroc ride.>$B$BForse l'uno può aiutarti con queste informazioni; ma prima sei tu che devi aiutare l'uno.",
}
T[3510] = {
  title = "Il Nome della Bestia",
  desc = "È lei che uccide i miei figli, mortale, lei che si fa chiamare sovrana di questi oceani. Nient'altro che una falsa dea. Schiacciala e riportami tutte le sue teste.$B$BIn cambio avrai il nome che cerchi, e un'altra cosa che conta altrettanto.$B$BSi aggira nella covata... la chiamano Hetaera.$B$B<Lord Arkkoroc indica a sud-ovest.>$B$BVa'!",
  obj = "Uccidi Hetaera e porta l'Hetaera's Bloodied Head, l'Hetaera's Beaten Head e l'Hetaera's Bruised Head a Lord Arkkoroc.",
  progress = "<Lord Arkkoroc si china a esaminarti.>$B$BDove sono?",
  reward = "Finalmente $Guno:una; $Gdegno:degna; della saggezza di Arkkoroc!",
}
T[3511] = {
  title = "Il Nome della Bestia",
  desc = "Ti rivelerò il nome del signore dei demoni, Razelikh the Defiler, come ti ho promesso. Ma prima devo preparare una cosa della massima importanza per il tuo viaggio.$B$BPer creare l'arma che vuoi serve una tempra. Dammi un momento: devo spremere il sangue da queste teste.$B$B<Lord Arkkoroc stringe le teste fra i pugni giganteschi e ne spreme via tutto il sangue.>$B$BPorta a Loramus la tempra, e con lei il nome della bestia: Rakh'likh.",
  obj = "Porta la tempra a Loramus Thalipedes.",
  progress = "Incredibile, $R: sei $Gtornato:tornata;! Hai scoperto il vero nome?",
  reward = "La tempra darà il vetriolo che ci serve per forgiare le armi, e ora per crearle manca solo un ultimo passo.",
}
T[3512] = {
  title = "Con le Parole di Eranikus",
  desc = "$N, per prima cosa dobbiamo trovare il modo di parlare con Eranikus attraverso la gemma. Ora giace fra il sonno e la morte, in uno stato precario, contorto in una trama di incubi. L'essenza che mi hai dato è molto contaminata, ma abbiamo comunque una possibilità di raggiungerlo.$B$BSpingiti fino alle terre gelate di Winterspring, nella parte orientale, e cerca Umbranse the Spiritspeaker, uno dei nostri alleati mortali. È un umano che parla per i morti. Eranikus non è davvero morto, ma lui potrebbe aiutarci lo stesso.",
  obj = "Viaggia fino alla parte orientale di Winterspring e parla con Umbranse the Spiritspeaker.",
  reward = "Ha fatto bene, Itharius, a mandarti da me. Non è morto come intendi tu la morte, eppure presto Eranikus ci darà consiglio con le sue stesse parole. Per ora, però, non posso aiutarti direttamente... almeno, non ancora.$B$BTi presterò la mia arte di parlare con i morti, ma prima mi serve l'aiuto di qualcuno che — a differenza di me — non sia frenato dagli acciacchi della vecchiaia. Mi hanno portato via, contro la mia volontà, il più potente dei miei strumenti di divinazione, e se non lo riavrò non sapremo come aiutare Eranikus.",
  en_title = "In Eranikus' Own Words",
  en_obj = "Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker.",
}
T[3513] = {
  title = "La Runed Scroll",
  desc = "Ha l'aria di un documento ufficiale, questa pergamena, legata stretta da un nastro argentato. Qualcuno vorrebbe vederla, ne sei $Gsicuro:sicura;, ma chi?$B$BA nord, vicino al confine con Ashenvale, c'è un avamposto: se la pergamena parla degli elfi della notte, è lì che andrebbe portata.",
  obj = "Porta la Runed Scroll alla torre di guardia settentrionale in Barrens.",
  progress = "Che c'hai lì?",
  reward = "Bene bene... Dove l'hai trovata?",
  en_title = "The Runed Scroll",
  en_obj = "Take the Runed Scroll to the northern guard tower in the Barrens.",
}
T[3514] = {
  title = "Presenza dell'Orda",
  desc = "Questa pergamena arriva da quella driade subdola di Rynthariel, il Maestro delle Chiavi della Talon Den, sullo Stonetalon Peak.$B$BCon il messaggero a cui l'hai presa non avrà più contatti, eh eh, ma noi qui dobbiamo tenere duro. L'Orda non tollererà le sue staffette da queste parti.$B$B$N, va' alla Talon Den. Uccidi Rynthariel e poi pianta un simbolo che vedano tutti. Prendi questa bandiera dell'Orda, $N, e piantala nella Talon Den: così non saranno più tanto avventati da mandare un altro messaggero attraverso il nostro territorio.",
  obj = "Uccidi il capo di Talon Den, Rynthariel the Keymaster.",
  progress = "Non possiamo lasciare che l'Alleanza stia sulla nostra terra, $N. Faglielo sapere.",
  reward = "Sei $Gun duro:una dura;! Liberare The Den da Rynthariel è un passo importante, $N. Ci metteranno molto a riorganizzarsi, e così nelle Barrens le staffette dell'Alleanza saranno di meno. Prima di mandarne un'altra da queste parti, ci penseranno due volte.$B$BGrazie.",
  en_title = "Horde Presence",
  en_obj = "Kill the leader of the Talon Den, Rynthariel the Keymaster.",
}
T[3517] = {
  title = "Rubare il Sapere",
  desc = "Lo ammetto, $N: la mia situazione ad Azshara l'ho sfruttata al massimo. La punizione di Belgrom ha avuto i suoi vantaggi.$B$BPrima di partire mi sono informata un po', e saresti $Gsorpreso:sorpresa; di quante cose di valore ci sono in giro.$B$BSe mi aiuti a raccoglierne qualcuna, ti racconterò di più dei miei affari e ti darò perfino una parte dei guadagni.$B$BA est, sparse per le Ruins of Eldarath, ci sono delle tavolette che mi servono. Tutte e quattro portano il nome di maghi Highborne. Procuramele e poi ne riparliamo.",
  obj = "Trova la Tablet of Beth'Amara, la Tablet of Jin'yael, la Tablet of Markri e la Tablet of Sael'hai, poi torna da Jediga in Azshara.",
  progress = "Per le persone giuste, le tavolette che ti sto facendo raccogliere dovrebbero valere qualche bella moneta di rame. A chi consegnarle te lo dico quando le avrai trovate. Ma non sono una sciocca... la tua parte l'avrai quando avrò la prova che sono state consegnate.$B$BQuindi datti da fare — non abbiamo tutto il giorno. Potrei dover cercare qualcun altro che mi aiuti.",
  reward = "Perfetto, $N, e sono pure in buono stato. Con queste dovremmo strappare un buon prezzo a tutti gli interessati.$B$BNon perdiamo qui più tempo del necessario. Ci sono soldi da guadagnare.",
}
T[3518] = {
  title = "Consegna a Magatha",
  desc = "La prima tavoletta è per una femmina tauren... si chiama Magatha. È tra gli anziani di Thunder Bluff ed è una delle sostenitrici dell'alleanza fra i tauren e i Forsaken. Più di ogni altro anziano, crede che i tauren e le loro usanze possano aiutare i Forsaken a ritrovare la strada per tornare umani.$B$BPortale la Tablet of Beth'Amara. Potrebbe essere l'anello che le manca per trovare il modo di aiutare i Forsaken... o almeno, così dice lei.",
  obj = "Porta la Tablet of Beth'Amara a Magatha a Thunder Bluff.",
  progress = "Sì, $N. Che cosa posso fare per te? Ho parecchie faccende a cui pensare, quindi sbrigati, per favore.",
  reward = "Ah, finalmente, la Tablet of Beth'Amara. Mi chiedevo se la mia collaborazione con Jediga fosse fallita, o se la povera orchessa fosse morta ad Azshara. Sono contenta che ce l'abbia fatta.$B$BBeth'Amara era uno degli alchimisti più influenti degli Highborne. Si diceva che, fra le altre cose, solo quel mago fosse riuscito a padroneggiare la trasmutazione dei metalli.",
}
T[3520] = {
  title = "Screecher Spirits",
  desc = "Sto cercando gli spiriti dei vale screechers di Feralas. Sono cugini di un dio antico, molto antico, e hanno lo spirito legato a lui.$B$BPrendi questa bacchetta di rovo e parti per Feralas. Nella parte centrale e meridionale di Feralas cerca i vale screechers e sconfiggili, poi agita il mio rovo sui cadaveri: così lo spirito si convincerà a farsi vedere. Toccalo e raccogline l'essenza.$B$BPoi torna da me con il rovo e con l'essenza, e ti racconterò qualcosa di più sul dio antico di cui ti ho parlato.",
  obj = "Cattura gli spiriti di 3 stridenti a Feralas, poi torna da Yeh'kinya a Steamwheedle Port.",
  progress = "$N, l'hai raccolta l'essenza degli screecher spirits?",
  reward = "Bel lavoro, $N. Forse è arrivato il momento di dirti qualcosa di più...$B$BFra i troll c'è un'antica profezia: il dio morto Hakkar, il Soulflayer, un giorno tornerà su questa terra. Alcuni dicono che la venuta di Hakkar porterà gioia e gloria alla stirpe dei troll, altri invece credono che la sua resurrezione segnerà la fine di ogni cosa.$B$BIo a questo mito non ci credo, ma so che l'essenza di Hakkar racchiude un grande potere, e quel potere va tenuto lontano da chi ne abuserebbe...",
}
T[3523] = {
  title = "Il Flagello delle Downs",
  desc = "Magnifico! Grazie per avermi salvato: mi chiamo Belnistrasz. Ormai mi davo per morto... o peggio, in pasto a questi parassiti infestati dallo Scourge. Sì — hai sentito bene, ho detto Scourge; hanno stretto una specie di patto con Quilboar di qui, ed è da lì che nasce questo incubo.$B$BAscolta... non voglio limitarmi a scappare: voglio fare qualcosa di utile, per il bene di tutti noi. Te la sentiresti di darmi una mano? Probabilmente sarà pericoloso, ma mi sembri il tipo che non se ne preoccupa troppo.",
  obj = "Se accetti di aiutare Belnistrasz, parla di nuovo con lui e restituiscigli la Pietra del Giuramento che ti ha dato.",
  progress = "La politica non fa per me; che tu stia con l'Orda o con l'Alleanza, non m'importa. Mi preme di più soffocare le minacce gravi e immediate per tutte le razze... e qui dentro ne abbiamo una bella grossa.$B$BSe vuoi essere $Gun vero eroe:una vera eroina; per tutti i popoli, allora ridammi la pietra del giuramento che ti ho dato: sarà il segno del tuo impegno. Io... non sono di queste parti; per quelli della mia specie una pietra del giuramento è importante, è il vincolo di un accordo.",
  reward = "Fantastico, mi pareva che avessi l'aria $Gdell'eroe:dell'eroina;! Non te lo nascondo, $N: ci aspetta un lavoro duro. Se non perdiamo di vista il compito che abbiamo davanti, dovremmo avere la meglio.$B$BOra lascia che ti spieghi cosa sta succedendo...",
  en_title = "Scourge of the Downs",
  en_obj = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.",
}
T[3525] = {
  title = "Spegnere l'Idolo",
  desc = "Vicino all'ingresso c'è un idolo che Quilboar usano come forno macabro; quelle bestie... divorano letteralmente le persone che rapiscono nelle Barrens. Posso spegnerlo e impedire che lo usino ancora, ma da solo non ce la faccio. Il mio piano: tu mi scorti fino all'idolo e lì comincerò il rituale. Riuscirò a malapena a parlarti, figuriamoci a difendermi, quindi mentre lo spengo dovrai proteggermi tu. Se mi abbattono, per noi è finita.$B$BSei con me?!",
  obj = "Scorta Belnistrasz fino all'idolo dei Quilboar nei Razorfen Downs.$B$BProteggi Belnistrasz mentre compie il rituale per spegnere l'idolo.",
  reward = "Andandosene all'improvviso, Belnistrasz ha lasciato un braciere acceso. Mentre fissi la fiamma, ti riempie la mente l'immagine di un drago rosso dalle grandi ali. La voce è quella di Belnistrasz, ma più roca, e ti parla direttamente.$B$B\"Davvero, mortali, siete gli eroi che speravo. Grazie a voi il massacro che queste bestie compivano è finito. Ancora una volta la mia fiducia nei mortali come te si è rinnovata. Prendi questa ricompensa: è degna di $Gun eroe:un'eroina;.\"",
  en_title = "Extinguishing the Idol",
  en_obj = "Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.$B$BProtect Belnistrasz while he performs the ritual to shut down the idol.",
}
T[3526] = {
  title = "Ingegneria Goblin",
  desc = "A livello esperto, l'ingegneria si divide in due discipline distinte: quella gnomesca e quella goblin. Va da sé che ogni ingegnere geniale sceglie l'ingegneria goblin. Impara a dominare il mondo usando con accortezza potenti esplosivi e congegni fantastici!$B$B$N, leggi questo manuale e, se vuoi imparare l'ingegneria goblin, portalo a Nixx Sprocketspring a Gadgetzan. Ricorda — l'appartenenza è per sempre e non potrai più unirti all'altra disciplina: prima di completare il suo incarico, quindi, assicurati che sia proprio quello che vuoi.",
  obj = "Se vuoi saperne di più sull'Ingegneria Goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring a Gadgetzan.",
  progress = "Le nuove reclute le fiuto come un'ottima polvere da mina — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare a padroneggiare le esplosioni?",
  reward = "Bene, $N, sei $Gstato saggio:stata saggia; a venire a cercare i miei insegnamenti! Qualsiasi babbeo può diventare esperto delle basi dell'ingegneria — lo dimostrano gli gnomi e la loro casa irradiata di Gnomeregan. Ma per padroneggiare la disciplina dell'Ingegneria Goblin ci vogliono una mente forte e una mano ferma (e sottolineo FERMA).$B$BDrizza le orecchie, $N, che magari impari qualcosa.",
  en_title = "Goblin Engineering",
  en_obj = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
}
T[3527] = {
  title = "La Profezia di Mosh'aru",
  desc = "L'antica profezia di Mosh'aru parla di un modo per contenere l'essenza del dio Hakkar. L'hanno scritta su due tavolette e portata nella città troll di Zul'Farrak, a ovest di Gadgetzan.$B$BPortami le tavolette di Mosh'aru!$B$BLa prima la custodisce Theka the Martyr, un troll morto da tanto tempo. Si dice che una maledizione abbia trasformato in scarabei i suoi persecutori, e che adesso zampettino intorno al suo santuario.$B$BLa seconda la custodisce l'idromante Velratha, vicino alla pozza sacra di Gahz'rilla.$B$BQuando le avrai, portamele.",
  obj = "Porta le First e le Second Mosh'aru Tablets a Yeh'kinya a Tanaris.",
  progress = "$N, ce l'hai le tavolette della Profezia di Mosh'aru?$B$BQuando le avrò, le studierò e scoprirò come contenere l'essenza di Hakkar!",
  reward = "Ah, bene. Queste antiche tavolette posso fonderle insieme, e poi studiarne i segreti nascosti.$B$BIl mio debito con te cresce, $N. E crescerà ancora di più.",
  en_title = "The Prophecy of Mosh'aru",
  en_obj = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.",
}
T[3528] = {
  title = "Il Dio Hakkar",
  desc = "È arrivato il momento di catturare l'essenza dell'avatar di Hakkar.$B$BPorta l'Egg of Hakkar al Sanctum of the Fallen God nel Sunken Temple, ad Azeroth, e invoca il potere dell'uovo per risvegliare il dio morto.$B$BTi manderà contro i suoi servitori. Sconfiggi i suoi bevitori di sangue e prendi il loro sangue Hakkari: con quello spegnerai le fiamme eterne che trattengono lo spirito di Hakkar. Quando saranno spente tutte, l'avatar di Hakkar entrerà nel nostro mondo.$B$BSconfiggilo e metti la sua essenza dentro l'uovo di Hakkar.",
  obj = "Porta il Filled Egg of Hakkar a Yeh'kinya a Tanaris.",
  progress = "$N, hai sconfitto l'avatar di Hakkar? L'uovo che ti ho dato ha già preso potere dalla sua essenza?",
  reward = "L'essenza di Hakkar è stata raccolta! L'Uovo freme già di vita! Possibile che i miti su Hakkar siano veri?$B$BNon deve essere così, perché ho paura di quello che Hakkar potrebbe fare se rinascesse. Quest'uovo lo terrò al sicuro, e farò in modo che non finisca in mani malvagie.$B$BLe tue fatiche al mio fianco sono finite, $N. Hai toccato una leggenda, e un giorno le tue azioni potrebbero cambiare il volto del nostro mondo.",
}
T[3541] = {
  title = "Consegna a Jes'rimon",
  desc = "Ho un ricettatore a Orgrimmar, abita in The Drag. Se non sai dove guardare è difficile beccarlo, ma se lo cerchi in uno degli edifici più alti non dovresti avere problemi a trovarlo.$B$BPerò fammi un favore: non andare a gridare a tutto Kalimdor che sta lì e che affari fa — sarebbe un guaio per tutti e due.$B$BPer la Tablet of Jin'yael ci pagherà più del giusto. Non so bene perché, ma avresti dovuto vedere quant'era entusiasta quando ha saputo dove si trovava.",
  obj = "Porta la Tablet of Jin'yael a Jes'rimon a Orgrimmar.",
  progress = "Sì, che ti serve, mon? Oggi ho un sacco di cose da sbrigare, e nella mia agenda tu non sei fra quelle. Scocciami, e faccio in modo che cambi.",
  reward = "Ahhh, Jediga manda il suo pacco fin da Azshara. Bene. Lo stavo aspettando.$B$BJediga, quella sì che è una gran donna... e pure letale. Cosa si può volere di meglio?$B$BGuarda qua... la tavoletta è in condizioni perfette. Sei $Gun buon messaggero:una buona messaggera;, $N.",
}
T[3542] = {
  title = "Consegna ad Andron Gant",
  desc = "Il mio prossimo contatto è Andron Gant. Di solito se ne sta rintanato a Undercity... proprio vicino all'Apothecarium.$B$BSu cosa vuole farci con la Tavoletta è stato un po' più chiacchierone. A quanto pare alcuni maghi di Undercity vogliono studiare certi incantesimi arcani degli alti nati, e pensano che questa tavoletta li aiuterà. Markri era bravo a evocare creature, soprattutto elementali.$B$BPorta la Tablet of Markri, poi torna da me a prendere la tua parte della ricompensa.",
  obj = "Porta la Tablet of Markri ad Andron Gant a Undercity.",
  progress = "Beh... <hic>... ma guarda che sorpresa! $GUn avventurierererere:Un'avventurierererera;... <hic>!$B$BChe p'sso fare per te... <hic>?",
  reward = "Ecco, prendi un po' di monete... comprati... <hic>... un'armatura nuova o roba del genere....$B$BCon questa, le... <hic> persone giuste ci guadagneranno una o due monete d'oro luccicanti.",
}
T[3561] = {
  title = "Consegna ad Archmage Xylem",
  desc = "Quest'ultima tavoletta va a qualcuno di molto pericoloso, $N. Dammi retta: di questa persona mi fido molto meno che di tutti gli altri che ti ho chiesto di incontrare.$B$BArchmage Xylem ha una torre sulle colline che dominano Azshara. È umano, ma non si comporta come nessuno degli umani che ho incontrato... o ucciso. Emana potere, e non oso chiedergli cosa voglia fare della tavoletta.$B$BÈ venuto lui da me, ma mi ha detto che, quando fossi stata pronta a incontrarlo, la sua guardia del corpo, Sanath, mi avrebbe aiutata a raggiungere la torre. Cerca Sanath a nord.",
  obj = "Porta la Tablet of Sael'hai ad Archmage Xylem ad Azshara.",
  progress = "Come posso aiutarti, $N?",
  reward = "Ah, la Tablet of Sael'hai... era tanto che desideravo studiarla.$B$BGrazie, $N. Di' pure a Jediga che ha fatto un buon lavoro: questa varrà di sicuro il compenso che ha chiesto.",
}
T[3562] = {
  title = "Il Pagamento di Magatha per Jediga",
  desc = "Porta questa nota a Jediga e dille che al suo ritorno troverà qui il pagamento. Dille anche che sono soddisfatta del suo lavoro.$B$BVa' in fretta, $N, e di' alla tua padrona che la aspetto qui.",
  obj = "Consegna la Magatha's Note a Jediga ad Azshara.",
  progress = "Allora, che ha detto Magatha? Quella vecchia megera... Scommetto che non è stata granché gentile.",
  reward = "Ah, bene. È stata molto più ragionevole di quanto pensassi... almeno con te. Quasi mi aspettavo che ti facesse punire per l'insolenza di aver mandato qualcun altro al posto mio. Quella tavoletta deve volerla proprio tanto. Interessante.$B$BUna cosa su cui riflettere un'altra volta.",
}
T[3563] = {
  title = "Il Pagamento di Jes'rimon a Jediga",
  desc = "Porta questa lettera a Jediga e falle sapere che il nostro affare è stato vantaggioso e che sono contento del suo lavoro.$B$BDille di tornare presto a Orgrimmar, e Jes'rimon farà in modo di prendersi buona cura di lei.$B$BRiferiscile questo, e magari in futuro avrò ancora bisogno dei tuoi servizi, $N.",
  obj = "Consegna la Jes'rimon's Note a Jediga ad Azshara.",
  progress = "Hai già parlato con Jes'rimon?$B$BTra i troll è un cafone, ma di solito le sue informazioni sono precise e i suoi lavori pagano bene.$B$BSe riesci a sopportarne i modi, con i suoi affari puoi metterti in tasca un bel po' di monete.",
  reward = "Dalla lettera vedo che era più che soddisfatto... pure un po' troppo.$B$BForse un giorno mi prenderò il tempo di fargli sapere quanto apprezzo anche le sue avance. Be', almeno ho un motivo per non vedere l'ora di passare più tempo ad Azshara.$B$BEcco la tua parte del compenso.",
}
T[3564] = {
  title = "Il Pagamento di Andron a Jediga",
  desc = "Ecco... porta... <hic> questo a Jediga. Buona fortuna!",
  obj = "Consegna l'Andron's Note a Jediga in Azshara.",
  progress = "Hai già incontrato Andron? Da Undercity esce di rado, quindi trovarlo non dovrebbe essere difficile.",
  reward = "Perfetto... aspetta un attimo.$B$BAhah! Ma che gli hai detto quando gli hai dato la tavoletta, $N? Ci ha pagato fin troppo! Non che mi lamenti. Gli hai detto che l'accordo era cambiato? O era di nuovo ubriaco?$B$BNon importa... ecco, prendi anche una parte in più.",
}
T[3565] = {
  title = "Il Pagamento di Xylem a Jediga",
  desc = "Che c'è? Ah, sì, il tuo compenso. Certo.$B$BPrendi questo e vattene. Sono sicuro che Jediga ti sta aspettando con tanta, tanta pazienza.",
  obj = "Consegna la Xylem's Note a Jediga ad Azshara.",
  progress = "Allora, cosa ha detto Xylem? Non ti ha fatto niente, vero? Ti ha lanciato un incantesimo? Ti ha $Gconvinto:convinta; con l'inganno a lavorare per lui?",
  reward = "Nessun problema? Proprio nessuno? Be', questa sì che è nuova... Mi aspettavo che si facesse un po' pregare, o almeno che tradisse il nostro accordo. Mmm, forse dopotutto di lui ci si può fidare.$B$BBe', inutile rimuginarci troppo. Ecco la tua parte, e grazie dell'aiuto.",
}
T[3566] = {
  title = "Sorgi, Obsidion!",
  desc = "Era... era... era tutta una trappola.$B$BPerdona... mi.$B$BUccidi quel bastardo... uccidilo per noi... per Thorius.",
  obj = "Uccidi Lathoric the Black e Obsidion, e torna da Thorius a Ironforge con l'Head of Lathoric the Black e l'Heart of Obsidion.",
  progress = "Non ti credo! Fammi vedere le prove!",
  reward = "<Thorius diventa bianco in volto.>$B$BNon... non può essere. Mio fratello? Ha organizzato tutto lui?$B$B<Il volto di Thorius si contorce dalla rabbia.>$B$BHa tradito me e ha tradito Ironforge! A quanto pare, l'influenza degli Old Gods è ancora forte in queste terre. Se mio fratello — un tempo un uomo nobile e d'onore — si è piegato con tanta facilità al volere di Ragnaros, temo che nessuno sia al sicuro.",
}
T[3567] = {
  title = "Fino in Cima",
  reward = "Vuoi ammirare il panorama dalla cima di uno dei due colossi gemelli? Posso mandarti lassù, $R.$B$BPrima, però, pensa bene a come scenderai. Il viaggio è di sola andata.",
  en_title = "To the Top",
}
T[3568] = {
  title = "Corruzione Strisciante",
  desc = "Vedi la tauren alle mie spalle — quella che pare sul punto di stare male? È stata ad Azshara di recente. Racconta che alcuni naga l'hanno ferita mentre attraversava le Ruins of Eldarath.$B$BNe ha respinti alcuni, poi si è fermata a riposare sulla spiaggia e ha bevuto da una delle pozze di marea. Adesso ha la nausea... e non solo quella.$B$BVorrei scoprire cosa ha bevuto. Prendi questa scatola: ci troverai alcune empty vials che ho etichettato io. Riempile in una pozza diversa ciascuna e torna qui.",
  obj = "Riempi tutte e 4 le Empty Vials alle pozze di marea lungo la costa delle Ruins of Eldarath, ad Azshara, prima di tornare da Chemist Cuely.",
  progress = "Lo sai dove porta tutto questo, vero, $N? Non può sopravvivere... guardala. Per lei, ormai, la cosa migliore è aiutarci a trovare una cura per la piaga, e nell'acqua che ha bevuto potrebbe nascondersi un indizio che ci aiuti a capire come. Morirà comunque — tanto vale che muoia facendo qualcosa di nobile per il nostro popolo. Non sei d'accordo?",
  reward = "Magnifico. Sei $Gtornato:tornata; prima che morisse. Bene, bene.$B$BAllora mettiamoci al lavoro, che ne dici?$B$BÈ da un po' che studio i suoi sintomi, e la faccenda è piuttosto brutta. Mi stupisce che stia ancora in piedi. Ha vomitato dappertutto tre o quattro volte... un odore davvero gradevole.$B$BDammi solo un attimo per preparare qualcosa da provare sulla nostra... amica.",
}
T[3569] = {
  title = "Corruzione Strisciante",
  desc = "Da' questo a Thersa. Forse la curerà... forse no. Lo sapremo solo quando l'avrà bevuto.",
  obj = "Consegna il Cuely's Elixir a Thersa Windsong a Undercity.",
  progress = "Sono venuta a Undercity perché ho sentito dire che i loro alchimisti cercano da tempo, e con impegno, una cura per la loro malattia. Qualcuno mi ha suggerito che forse avrebbero potuto aiutare anche me.$B$BIn questo posto mi sento tutt'altro che benvenuta, ma non avevo scelta — il male che mi ha colpita mi lacera dentro, e il loro aiuto mi serviva subito.",
  reward = "Chemist Cuely è stato molto disponibile... in un modo che inquieta. Ma se dice che questo mi aiuterà, non ho altra scelta. Non ho il tempo di cercare un'altra strada. Ho già parlato con sacerdoti e sciamani, e nessuno ha potuto aiutarmi.$B$BSperiamo che la Madre Terra vegli sul mio spirito.",
}
T[3570] = {
  title = "Corruzione Strisciante",
  reward = "Non avrei mai immaginato che l'elisir agisse così in fretta. Grazie, $N. Mi metto subito al lavoro sul resto di questi campioni. Sono sicuro che presto Lady Sylvanas e i Forsaken potranno servirsene.",
}
T[3601] = {
  title = "Kim'jael, Certo!",
  desc = "Kim'jael, certo!! Lo sai cosa vuol dire Kim'jael per gli elfi del Sangue, $N? Piccolo ratto... o giù di lì. Quei grossi prepotenti!$B$BMi hanno assunto perché li aiutassi a esplorare la zona in cerca di chissà quali tesori perduti. Si capisce, appena hanno detto \"tesoro\" e la somma che erano disposti a pagare ho accettato al volo, ma naturalmente poi mi si sono rivoltati contro e hanno cercato di uccidere... ME!$B$BIl che dimostra che di un elfo del Sangue non ci si può fidare.$B$BIl guaio è che la mia attrezzatura ce l'hanno ancora loro, e io non riesco a riprendermela. Mi dai una mano?",
  obj = "Cerca in Thalassian Base Camp la Bussola, il Cannocchiale, il Pollo Impagliato e il Wizzlegoober di Kim'jael, poi riportali a lui in Azshara.",
  progress = "Quei puzzolenti elfi del Sangue. Te lo dico io: se fossi forte come te, andrei laggiù io stesso a dargli una lezione! Invece mi tocca accontentarmi di pagare te perché ci pensi al posto mio.",
  reward = "Ahah! Gliel'hai fatta vedere, eh?!$B$BFantastico! Così quegli elfi del Sangue imparano a tradire i soci... soprattutto uno leale come un mercante goblin! Bah, elfi del Sangue...!$B$BBe', ripagarti del disturbo è il minimo che possa fare... proprio come ti avevo detto.$B$BEcco qua... ti dovrebbero tornare utili.",
}
T[3602] = {
  title = "Azsharite",
  desc = "Gli antichi cliff giants del sud di Azshara si nutrono della roccia e degli edifici di queste terre, e ciò che mangiano esce nei loro escrementi come un cristallo molto malleabile ed estremamente resistente, chiamato Azsharite.$B$BSe ne trovano formazioni sparse lungo l'arco meridionale, ma i giganti sono così violenti che se ne recuperano poche.$B$BDevi spingerti a sud e procurarti abbastanza Azsharite da creare il corpo dell'arma. I miei felhounds ti aiuteranno a scovare il cristallo.",
  obj = "Recupera venti pezzi di Crystallized Azsharite nel sud di Azshara. Puoi farti aiutare dal Felhound a 'fiutare' dove si trovano i depositi ben nascosti.$B$BTorna da Loramus quando avrai finito.",
  progress = "Il male non dorme, $Gstolto:stolta;. Per riposare avrai tempo quando sarai finalmente $Gmorto:morta;. Ora portami quei cristalli.",
  reward = "Hai concluso i tuoi compiti ad Azshara, mortale. Ora devo forgiare i componenti che ti serviranno per il prossimo passo della tua avventura.",
}
T[3621] = {
  title = "La Formazione di Felbane",
  desc = "Ora le armi si possono forgiare. Devi portare l'azsharite temprata a qualcuno che sappia imbrigliare l'energia vil.$B$BC'è un fabbro così nella Stranglethorn Vale: Galvan the Ancient, capo di The Mithril Order, creerà le armi come gli indicherai. Il suo accampamento sta tra Zul'Gurub e il tumulo degli ogre Mosh'Ogg.$B$BIn questa prova ti sostengano la determinazione e la fede. E se dovessi fallire, sappi che il tuo Dio ti sorride dall'alto, mortale.",
  obj = "Porta la Shipment to Galvan l'Antico nella Stranglethorn Vale.",
  progress = "Loramus, eh? Erano molti anni che non sentivo quel nome.",
  reward = "Santo cielo, posso solo immaginare cosa hai passato per procurarti questi materiali. In pochi si avventurano ad Azshara e ne tornano vivi, figuriamoci chi affronta semidei e giganti!",
}
T[3625] = {
  title = "Armi Vil di Azsharite Incantate",
  desc = "$N, ogni arma richiederà un po' di tempo.$B$BE poi il potere della Maledizione Vil potrai usarlo solo una volta ogni tre minuti. Contro Razelikh the Defiler e i suoi servitori, gli effetti che indeboliscono potrebbero durare ora di più, ora di meno. Per questo la Maledizione Vil devi scatenarla solo al momento giusto!$B$BOra lasciami un momento per forgiare la tua arma, $N.",
  obj = "Aspetta che Galvan finisca di forgiare le armi.",
  progress = "Se si interrompe la forgiatura, l'arma potrebbe uscire imperfetta. Abbi pazienza, $N.",
  reward = "<Galvan si asciuga il sudore dalla fronte.>$B$BUn ammazzademoni migliore non è mai esistito, $N.",
  en_title = "Enchanted Azsharite Fel Weaponry",
  en_obj = "Wait for Galvan to finish forging the weaponry.",
}
T[3626] = {
  title = "Ritorno alle Blasted Lands",
  desc = "L'ora della redenzione è vicina, $N. Devi tornare nelle Blasted Lands con le armi nuove e parlare con il Fallen Hero of the Horde: da lui riceverai l'ultimo obiettivo.",
  obj = "Torna dal Fallen Hero of the Horde.",
  reward = "Sembri $Gtemprato:temprata; dalla battaglia, $N. Sei $Gpronto:pronta; ad affrontare Razelikh e i suoi servitori?",
  en_title = "Return to the Blasted Lands",
  en_obj = "Return to the Fallen Hero of the Horde.",
}
T[3627] = {
  title = "Riunire l'Amuleto Spezzato",
  desc = "Per arrivare al Profanatore devi prima distruggere la triade del potere e recuperare i pezzi dell'amuleto. Quando li avrai tutti e tre, torna da me e ti dirò come proseguire.$B$BVai, $N! Alle Blasted Lands! Sevine, Allistarj e Grol devono cadere!",
  obj = "Uccidi Grol the Destroyer, Lady Sevine e l'Archmage Allistarj. Prendi dai loro cadaveri l'Amulet of Grol, l'Amulet of Sevine e l'Amulet of Allistarj.$B$BRicorda di USARE le tue Armi Vil di Azsharite Incantate per indebolire la triade. Non possono essere uccisi in nessun altro modo — ma usale con saggezza...",
  progress = "I tre formeranno l'uno, l'uno illuminerà la via.",
  reward = "L'amuleto di Razelikh the Defiler è di nuovo intero, ma lui avverte lo scompiglio nella sua catena di comando. Sa che stai venendo a prenderlo...",
}
T[3628] = {
  title = "Tu Sei Rakh'likh, Demone",
  desc = "La tana di Razelikh è in cima alla montagna più alta delle Blasted Lands, e l'unico modo per arrivarci sono le rune di teletrasporto che si trovano lì vicino. Finché avrai l'amuleto, potrai teletrasportarti lassù quando vuoi. Lì dovrai evocare la bestia: la chiave è l'amuleto, $N. Usalo sull'Altar of the Defiler.$B$BSe sconfiggerai il Profanatore, portami il suo corno. Per chiunque lo vedrà diventerà un simbolo di speranza — la prova che in questo mondo dilaniato dalla guerra gli eroi esistono davvero.",
  obj = "Distruggi Razelikh the Defiler e porta il Severed Horn of the Defiler al Fallen Hero of the Horde. Dovrai anche portare la Ward of the Defiler, così che il Fallen Hero possa distruggerla, impedendo che finisca mai nelle mani sbagliate.",
  progress = "Non c'è più niente da temere.",
  reward = "Oggi è un giorno che resterà nella memoria per l'eternità. Il signore supremo demoniaco delle Blasted Lands è caduto, finalmente!",
}
T[3629] = {
  title = "Ingegneria Goblin",
  desc = "A livello esperto l'ingegneria si divide in due discipline ben distinte: gnomesca e goblin. Se nomino quella goblin è solo perché sono un istruttore imparziale. A loro piace costruire cose che saltano in aria, e di rado si preoccupano di cosa ci sia di mezzo — fossero anche loro stessi.$B$B$N, leggi questo manuale. Se vuoi imparare a farti saltare in aria, portalo a Nixx Sprocketspring a Gadgetzan. Ricorda — la scelta è definitiva e non potrai più unirti all'altra disciplina, quindi prima di portare a termine il suo incarico assicurati che sia questo quello che vuoi.",
  obj = "Se vuoi saperne di più sull'Ingegneria Goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.",
  progress = "Le reclute nuove le fiuto come la polvere esplosiva di prima qualità — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare l'arte dell'esplosione?",
  reward = "Bene, $N, sei $Gstato:stata; $Gsaggio:saggia; a venire a imparare da me! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — ne sono la prova gli gnomi e la loro Gnomeregan radioattiva. Ma per padroneggiare la disciplina dell'Ingegneria Goblin ci vogliono una mente forte e una mano ferma (e sottolineo FERMA).$B$BTieni le orecchie dritte, $N, che magari impari qualcosa.",
  en_title = "Goblin Engineering",
  en_obj = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
}
T[3630] = {
  title = "Ingegneria Gnomesca",
  desc = "A livello esperto l'ingegneria si divide in due discipline: gnomesca e goblin. E quella gnomesca è di gran lunga la migliore! Si costruiscono congegni e dispositivi meravigliosi, che migliorano la vita!$B$B$N, leggi questo manuale. Se vuoi saperne di più sull'ingegneria gnomesca, portalo a Tinkmaster Overspark a Ironforge. Ricorda — la scelta è definitiva e non potrai più unirti all'altra disciplina, quindi sii $Gsicuro:sicura; prima di portare a termine il suo incarico!",
  obj = "Se vuoi saperne di più sull'Ingegneria Gnomo, porta il Manual of Engineering Disciplines a Tinkmaster Overspark, a Ironforge.",
  progress = "Sì, sì, a quale tua necessità posso provvedere oggi? Il tempo di certo non mi manca: non faccio altro che starmene qui, mentre la nostra amata città giace in una nube di morte radioattiva.",
  reward = "Ah, $Gun:una; giovane $Gingegnere:ingegnera; $Ginteressato:interessata; a intraprendere l'unica, vera disciplina dell'ingegneria! Beh, perdona il mio melodramma, $Gamico:amica;. La nostra situazione resta disperata, ma è sempre una bella giornata quando $Gun altro:un'altra; $Gingegnere:ingegnera; risponde al richiamo della vera ingegneria!",
  en_title = "Gnome Engineering",
  en_obj = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.",
}
T[3631] = {
  title = "Evoca Felsteed",
  desc = "Hmph. Secondo me non sei $Gpronto:pronta;, ma non sono io a deciderlo. Strahad la pensa diversamente, e la decisione è sua... stavolta.$B$BVuole parlarti, e in fretta. Lo troverai ancora nella sua torretta con gli accoliti, sopra Ratchet, nelle Barrens.$B$BNon metterci troppo.",
  obj = "Parla con Strahad Farsan in Barrens.",
  reward = "Così hai deciso di onorarmi di nuovo della tua presenza. Che gentile da parte tua.$B$BI miei accoliti si domandavano se ti saresti mai $Gfatto vivo:fatta viva;. Gli ho risposto che non c'era alcun dubbio. Quando c'è di mezzo il potere, ne sei $Gattratto:attratta; come una falena dalla fiamma.",
}
T[3632] = {
  title = "Ingegneria Gnomesca",
  desc = "A livello esperto, l'ingegneria si divide in due discipline: gnomesca e goblin. E quella gnomesca è di gran lunga la migliore! Vuol dire costruire congegni e dispositivi meravigliosi che rendono la vita migliore!$B$B$N, leggi questo manuale, e se vuoi saperne di più sull'ingegneria gnomesca portalo a Tinkmaster Overspark, qui a Ironforge. Ricorda — l'adesione è per sempre e non potrai più unirti all'altra disciplina, quindi, prima di completare il suo incarico, assicurati di esserne $Gsicuro:sicura;!",
  obj = "Se vuoi saperne di più sull'Ingegneria Gnomo, porta il Manual of Engineering Disciplines a Tinkmaster Overspark, a Ironforge.",
  progress = "Sì, sì, cosa posso fare per te oggi? Il tempo di certo non mi manca: non faccio altro che starmene qui, mentre la nostra amata città giace in una nube di morte radioattiva.",
  reward = "Ah, $Gun giovane ingegnere interessato:una giovane ingegnera interessata; all'unica, vera disciplina dell'ingegneria! Beh, perdona il mio melodramma, $Gamico:amica;. La nostra situazione resta disperata, ma quando $Gun altro ingegnere:un'altra ingegnera; risponde allo squillo di tromba della vera ingegneria, la giornata è sempre bella!",
  en_title = "Gnome Engineering",
  en_obj = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.",
}
T[3633] = {
  title = "Ingegneria Goblin",
  desc = "A livello esperto l'ingegneria si divide in due discipline ben distinte: gnomica e goblin. E ovviamente l'ingegneria goblin è quella che scelgono tutti gli ingegneri geniali. Impara a dominare il mondo con un uso giudizioso di esplosivi potenti e congegni fantastici!$B$B$N, leggi questo manuale e, se vuoi imparare l'ingegneria goblin, portalo a Nixx Sprocketspring a Gadgetzan. Ricorda — l'iscrizione è per sempre e non potrai più unirti all'altra disciplina, quindi prima di completare il suo incarico assicurati che sia proprio quello che vuoi.",
  obj = "Se vuoi saperne di più sull'Ingegneria Goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring a Gadgetzan.",
  progress = "Le nuove reclute le fiuto come un'ottima polvere esplosiva — a un miglio di distanza. Sei $Gvenuto:venuta; per imparare a padroneggiare l'esplosione?",
  reward = "Ebbene, $N, sei $Gstato saggio:stata saggia; a cercare i miei insegnamenti! Nelle basi dell'ingegneria può diventare esperto qualsiasi imbranato — gli gnomi e la loro casa irradiata, Gnomeregan, ne sono la prova. Ma per padroneggiare la disciplina dell'Ingegneria Goblin ci vogliono una mente forte e una mano ferma (con l'accento su FERMA).$B$BDrizza le orecchie, $N, e magari imparerai qualcosa.",
  en_title = "Goblin Engineering",
  en_obj = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
}
T[3634] = {
  title = "Ingegneria Gnomica",
  desc = "A livello esperto l'ingegneria si divide in due discipline: gnomica e goblin. Io la trovo uno spreco, ma la specializzazione gnomica dovresti conoscerla comunque. Fanno oggetti e congegni che promettono di cambiare il mondo, ma funzionano di rado.$B$B$N, leggi questo manuale. Se vuoi imparare a fare fermacarte di metallo, portalo a Tinkmaster Overspark a Ironforge. Ricorda — l'iscrizione è per sempre e non potrai più unirti all'altra disciplina, quindi prima di completare il suo incarico assicurati di esserne $Gsicuro:sicura;!",
  obj = "Se vuoi saperne di più sull'Ingegneria Gnomo, porta il Manual of Engineering Disciplines a Tinkmaster Overspark a Ironforge.",
  progress = "Sì, sì, cosa posso fare per te oggi? Di tempo ne ho di sicuro: non faccio altro che starmene qui, mentre la nostra amata città giace in una nube di morte irradiata.",
  reward = "Ah, $Gun giovane ingegnere:una giovane ingegnera; che vuole seguire l'unica, vera disciplina dell'ingegneria! Beh, perdona il melodramma, $Gamico:amica;. La nostra situazione è ancora disperata, ma quando vedo $Gun altro ingegnere:un'altra ingegnera; rispondere al richiamo della vera ingegneria è sempre una bella giornata!",
  en_title = "Gnome Engineering",
  en_obj = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.",
}
T[3635] = {
  title = "Ingegneria Gnomesca",
  desc = "A livello esperto, l'ingegneria si divide in due discipline: quella gnomesca e quella goblin. Secondo me è uno spreco, ma è giusto che tu conosca anche la specializzazione gnomesca. Fanno oggetti e congegni che pretendono di cambiare il mondo e che funzionano di rado.$B$B$N, leggi questo manuale e, se vuoi imparare a fare fermacarte di metallo, portalo a Oglethorpe Obnoticus a Booty Bay. Ricorda — l'appartenenza è per sempre e non potrai più unirti all'altra disciplina: prima di completare il suo incarico, quindi, assicurati di esserne $Gsicuro:sicura;.",
  obj = "Se vuoi saperne di più sull'Ingegneria Gnomo, porta il Manual of Engineering Disciplines a Oglethorpe Obnoticus a Booty Bay.",
  progress = "Salve! Se sei qui per un robot a ricerca automatica che potrebbe averti sfondato un muro del tuo domicilio, ti rimando fin da subito al mio avvocato. Altrimenti, cosa posso fare per te?",
  reward = "Sei $Gvenuto:venuta; a imparare l'ingegneria gnomesca, eh? Beh, sei $Gcapitato:capitata; dallo gnomo giusto. La fazione al potere a Gnomeregan potrà anche usare la politica per emarginare chi considera una minaccia intellettuale, ma sa bene che la conoscenza non la può controllare.$B$BLo sappiamo sia io sia loro: quando me ne sono andato da Gnomeregan, hanno perso uno dei più grandi gnome engineers ancora in vita. Se sei $Gun allievo capace:un'allieva capace;, ti insegnerò quello che so.",
  en_title = "Gnome Engineering",
  en_obj = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.",
}
T[3636] = {
  title = "Porta la Luce",
  desc = "Lo Scourge minaccia di continuo l'Alleanza, e sono certo che lo sai bene anche tu. Ultimamente, $N, abbiamo scoperto cose molto strane.$B$BNelle Barrens c'è un orribile groviglio di rovi chiamato Razorfen Downs. Un tempo ci vivevano dei semplici verrospini, ma ora è chiaro che con lo Scourge è stato stretto un patto, e ne sono uscite creature ben peggiori... A comandarle adesso è il lich Amnennar the Coldbringer.$B$BSchierati con la Luce, $N; poni fine a questa unione malvagia.",
  obj = "Archbishop Bendictus vuole che tu uccida Amnennar the Coldbringer a Razorfen Downs.",
  progress = "Amnennar va annientato. Va', e fa' presto.",
  reward = "Grazie, $N. Adesso lo Scourge ci penserà due volte prima di tentare ancora di ingrossare le sue file.$B$BChe tu sia $Gbenedetto:benedetta; dalla Luce.",
  en_title = "Bring the Light",
  en_obj = "Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs.",
}
T[3637] = {
  title = "Ingegneria Gnomica",
  desc = "A livello esperto l'ingegneria si divide in due discipline: gnomica e goblin. Io la trovo uno spreco, ma la specializzazione gnomica dovresti conoscerla comunque. Fanno oggetti e congegni che promettono di cambiare il mondo, ma funzionano di rado.$B$B$N, leggi questo manuale. Se vuoi imparare a fare fermacarte di metallo, portalo a Oglethorpe Obnoticus a Booty Bay. Ricorda — l'iscrizione è per sempre e non potrai più unirti all'altra disciplina, quindi prima di completare il suo incarico assicurati di esserne $Gsicuro:sicura;.",
  obj = "Se vuoi saperne di più sull'Ingegneria Gnomo, porta il Manual of Engineering Disciplines a Oglethorpe Obnoticus a Booty Bay.",
  progress = "Salve! Se sei $Gvenuto:venuta; per un robot autoguidato che forse ha sfondato un muro del tuo domicilio, ti rimando fin d'ora al mio avvocato. Altrimenti, cosa posso fare per te oggi?",
  reward = "Sei $Gvenuto:venuta; a imparare l'ingegneria gnomica, eh? Beh, hai trovato lo gnomo giusto. La fazione che comanda a Gnomeregan potrà anche servirsi della politica per emarginare chi ritiene una minaccia intellettuale, ma sa di non poter controllare la conoscenza.$B$BLo sappiamo bene sia io che loro: quando me ne sono andato da Gnomeregan, hanno perso uno dei più grandi gnome engineers ancora in vita. Se sei $Gun allievo capace:un'allieva capace;, ti insegnerò quello che so.",
  en_title = "Gnome Engineering",
  en_obj = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.",
}
T[3638] = {
  title = "Il Giuramento di Segretezza",
  desc = "L'ingegneria Goblin bada al pratico: profitti alti e potenza esplosiva ancora più alta! Con i nostri schemi si costruiscono bombe potenti e armi formidabili, e il manuale che hai letto ne parlava.$B$BNel manuale si parlava anche dell'antichissimo giuramento di segretezza sui nostri schemi. Una volta $Gdiventato:diventata; ingegnere goblin, indietro non si torna, e all'ingegneria gnomesca non avrai più nessun accesso.$B$BSe vuoi ancora diventare ingegnere goblin, firma questo documento, con cui giuri segretezza per tutta la vita, e poi torna a parlare con me. Pensaci bene, $N.",
  obj = "Se accetti di diventare un Goblin Engineer, clicca con il tasto destro sul Giuramento di Segretezza e parla di nuovo con Nixx Sprocketspring a Gadgetzan.",
  progress = "Se hai firmato il documento e sei $Gpronto:pronta; a consegnarmelo, allora la cosa è decisa. Ti hanno avvertito: è un viaggio di sola andata. Se sei $Gpronto:pronta;, sali a bordo!",
  reward = "$GBenvenuto:Benvenuta; a bordo, Goblin Engineer $N! Presto avrai accesso agli schemi di ingegneria più potenti di tutta Azeroth.$B$BAdesso che ti sei $Gimpegnato:impegnata; a inseguire questa conoscenza, è il momento di esaminare il tuo lavoro di ingegneria in stile goblin. Poi ti aiuteremo a preparare un piano per sfruttare al massimo il tuo talento di ingegnere goblin!",
  en_title = "The Pledge of Secrecy",
  en_obj = "If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan.",
}
T[3639] = {
  title = "Mostra il Tuo Lavoro",
  desc = "Come tuo mentore, voglio vedere dei campioni del tuo lavoro. Che tu sia $Gun ingegnere esperto:un'ingegnere esperta; non c'è dubbio, $N, ma vorrei analizzarli per trovare il modo di dare più spazio alle tecniche goblin in quello che costruirai. Ecco cosa mi serve: venti big iron bombs, venti candelotti di solid dynamite e cinque esemplari di explosive sheep — e tieni le sicure inserite!$B$BConsegnami questi oggetti e ti rilascerò la tua Goblin Engineer Membership Card; ti serve per accedere a tutti gli istruttori di ingegneria goblin!",
  obj = "Porta 20 Big Iron Bombs, 20 Solid Dynamite e 5 Explosive Sheep a Nixx Sprocketspring a Gadgetzan.",
  progress = "Appena mi porterai gli oggetti di ingegneria che hai costruito, così li esamino, ti consegnerò un'autentica Goblin Engineer Membership Card! Finché è valida, avrai accesso illimitato a qualsiasi istruttore di ingegneria goblin in tutto il mondo.",
  reward = "Ecco la tua prima Goblin Engineer Membership Card!$B$BLe sue quote sono pagate in anticipo per quattordici giorni; tutte le tessere scadono dopo due settimane di attività. Quando la tua scade, paga le quote successive a un istruttore di ingegneria goblin qualsiasi e ne avrai un'altra; senza tessera, la tua iscrizione resterà sospesa per un po' e non potrai accedere a nuovi schemi.$B$BQuello che sai già, però, non cambia mai; ingegnere goblin una volta, ingegnere goblin per sempre.",
  en_title = "Show Your Work",
  en_obj = "Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to Nixx Sprocketspring in Gadgetzan.",
}
T[3640] = {
  title = "Il Giuramento di Segretezza",
  desc = "L'ingegneria gnomesca è teoria ingegneristica fatta su misura per noi! Con i nostri schemi costruiamo congegni che controllano il mondo intorno a noi; ne parlava anche il manuale che hai letto.$B$BLo stesso manuale parlava del nostro antichissimo giuramento di segretezza sugli schemi. Una volta che diventi uno gnome engineer, non si torna indietro: all'ingegneria goblin non avrai più nessun accesso.$B$BSe vuoi ancora diventare uno gnome engineer, firma questo documento, con cui giuri di mantenere il segreto per tutta la vita, e torna a parlarmi. Pensaci bene, $N.",
  obj = "Se accetti di diventare uno Gnome Engineer, clicca con il tasto destro sul Giuramento di Segretezza e parla di nuovo con Tinkmaster Overspark, a Ironforge.",
  progress = "Se hai firmato il documento e sei $Gpronto:pronta; a consegnarmelo, allora è fatta.$B$BI segreti che sto per condividere con te sono di tale portata che firmare il Giuramento di Segretezza è assolutamente fondamentale. L'ho firmato anch'io, e così i miei fratelli e le mie sorelle gnome engineers. Entrerai in una cerchia davvero prestigiosa, $GIngegnere:Ingegnera; $N!",
  reward = "$GBenvenuto:Benvenuta; tra noi, $N! Presto avrai accesso agli schemi di ingegneria più avanzati di tutta Azeroth.$B$BOra che ti sei $Gimpegnato:impegnata; a cercare questa conoscenza, è il momento di guardare il tuo lavoro di ingegneria con occhio gnomesco. Da lì ti aiuteremo a mettere a punto un piano per sfruttare al massimo i tuoi talenti nell'ingegneria gnomesca!",
  en_title = "The Pledge of Secrecy",
  en_obj = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark in Ironforge.",
}
T[3641] = {
  title = "Mostra il Tuo Lavoro",
  desc = "Come tuo mentore, voglio vedere qualche campione del tuo lavoro. Che tu sia $Gun ingegnere abile:un'ingegnera abile;, $N, non c'è dubbio. Però vorrei analizzarlo per capire come dare più spazio alle tecniche gnomesche in quello che costruirai d'ora in poi. Ecco cosa mi serve: sei mithril tubes, un accurate scope e due advanced target dummies.$B$BPortami questi oggetti e ti rilascerò la tua Gnome Engineer Membership Card: serve per accedere a tutti gli istruttori di ingegneria gnomesca!",
  obj = "Porta 6 Mithril Tubes, un Accurate Scope e 2 Advanced Target Dummies a Tinkmaster Overspark, a Ironforge.",
  progress = "Appena avrò in mano gli oggetti di ingegneria che hai fabbricato, da esaminare, ti consegnerò un'autentica Gnome Engineer Membership Card! Finché la tessera resta valida, avrai accesso illimitato a qualunque istruttore degli gnome engineers, in ogni parte del mondo.",
  reward = "Ecco la tua prima Gnome Engineer Membership Card!$B$BLa quota di questa tessera è pagata in anticipo per quattordici giorni; tutte le tessere scadono dopo due settimane di attività. Alla scadenza, paga la quota successiva a un qualsiasi istruttore degli gnome engineers e avrai un'altra tessera; senza, la tua iscrizione resterà temporaneamente sospesa e non potrai accedere a nuovi schemi.$B$BQuello che già sai, però, non si tocca mai; gnome engineer una volta, gnome engineer per sempre.",
  en_title = "Show Your Work",
  en_obj = "Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to Tinkmaster Overspark in Ironforge.",
}
T[3642] = {
  title = "Il Giuramento di Segretezza",
  desc = "L'ingegneria gnomica è la teoria dell'ingegneria messa al servizio dei nostri bisogni! Con i nostri schemi costruiamo congegni che controllano il mondo intorno a noi; ne parlava anche il manuale che hai letto.$B$BLo stesso manuale parlava del nostro antichissimo giuramento di segretezza sugli schemi. Quando diventi uno gnome engineer, non si torna indietro: all'ingegneria goblin non avrai più alcun accesso.$B$BSe vuoi ancora diventare uno gnome engineer, firma questo documento, con cui giuri segretezza per tutta la vita, e torna a parlarmi. Pensaci bene, $N.",
  obj = "Se accetti di diventare uno Gnome Engineer, clicca con il tasto destro sul Giuramento di Segretezza e parla di nuovo con Oglethrope Obnoticus a Booty Bay.",
  progress = "Se hai firmato il documento e sei $Gpronto:pronta; a consegnarmelo, allora non si torna indietro.$B$BIn politica posso anche essere in profondo disaccordo con Gnomeregan — soprattutto con quello sciocco di Tinkmaster Overspark — ma il Giuramento di Segretezza viene prima di tutto! Devi accettare di seguire un'unica strada e restarle fedele per tutta la vita.",
  reward = "$GBenvenuto:Benvenuta; a bordo, $N! Presto avrai accesso agli schemi di ingegneria più avanzati di tutta Azeroth.$B$BOra che ti sei $Gimpegnato:impegnata; a perseguire questo sapere, è il momento di esaminare il tuo lavoro di ingegneria in stile gnomico: partiremo da lì per aiutarti a preparare un piano che sfrutti al massimo i tuoi talenti di ingegneria gnomica!",
  en_title = "The Pledge of Secrecy",
  en_obj = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Oglethrope Obnoticus in Booty bay.",
}
T[3643] = {
  title = "Mostrami il Tuo Lavoro",
  desc = "Come tuo mentore, voglio vedere qualche campione del tuo lavoro. Che tu sia $Gun ingegnere:un'ingegnera; abile non c'è dubbio, $N, ma vorrei analizzarlo per capire come dare più spazio alle tecniche gnomiche nei tuoi progetti futuri. Come campioni mi servono sei mithril tubes, un accurate scope e due advanced target dummies.$B$BPortami questi oggetti e ti darò la tua Gnome Engineer Membership Card: è necessaria per accedere a tutti gli addestratori di ingegneria gnomica!",
  obj = "Porta 6 Mithril Tubes, un Accurate Scope e 2 Advanced Target Dummies a Oglethorpe Obnoticus a Booty Bay.",
  progress = "Appena avrò ricevuto da esaminare gli oggetti di ingegneria che hai costruito, ti consegnerò una vera Gnome Engineer Membership Card! Finché la tessera è valida, potrai accedere senza limiti a qualsiasi addestratore di ingegneria gnomica del mondo.",
  reward = "Ecco la tua prima Gnome Engineer Membership Card!$B$BLa quota di questa tessera è già pagata per quattordici giorni; tutte le tessere scadono dopo due settimane di attività. Alla scadenza, paga la quota successiva a un addestratore di ingegneria gnomica qualsiasi e avrai un'altra tessera; senza, la tua iscrizione sarà sospesa e non potrai accedere a nuovi schemi.$B$BQuello che sai già, però, non si tocca mai: una volta gnome engineer, per sempre gnome engineer.",
  en_title = "Show Your Work",
  en_obj = "Bring 6 Mithril Tubes, an Accurate Scope, and a 2 Advanced Target Dummies to Oglethorpe Obnoticus in Booty Bay.",
}
T[3644] = {
  title = "Rinnovo della Tessera d'Iscrizione",
  progress = "Per rinnovare la tessera d'iscrizione c'è da pagare una quota di due monete d'oro.",
  reward = "Visto che sei $Gun praticante:una praticante; dell'ingegneria goblin e in regola, per due monete d'oro posso rinnovare una tessera d'iscrizione scaduta. Pagata la quota, ricevi una tessera nuova, che ti dà accesso agli schemi di ingegneria goblin presso gli istruttori giusti.$B$BQuesta tessera vale per due settimane di attività, e alla scadenza la quota d'iscrizione va pagata di nuovo! Se gli schemi ti servono, dovrai metterti in pari con i pagamenti.",
  en_title = "Membership Card Renewal",
}
T[3645] = {
  title = "Rinnovo della Tessera di Iscrizione",
  progress = "Se vuoi rinnovare la tessera di iscrizione, devi pagare la quota di rinnovo di due monete d'oro.",
  reward = "Visto che pratichi l'ingegneria Gnomesca e sei in regola, posso rinnovarti una tessera di iscrizione scaduta per due monete d'oro. Paghi la quota e ti viene rilasciata una tessera nuova, che ti dà accesso agli schemi di ingegneria Gnomesca presso gli istruttori adatti.$B$BLa tessera dura due settimane di attività, e poi la quota va pagata di nuovo! Se vuoi accedere agli schemi, dovrai metterti in pari con le quote arretrate.",
  en_title = "Membership Card Renewal",
}
T[3646] = {
  title = "Rinnovo della Tessera di Iscrizione",
  progress = "Se vuoi rinnovare la tessera di iscrizione, devi pagare la quota di rinnovo: due monete d'oro.",
  reward = "Visto che pratichi l'ingegneria Goblin e sei in regola, posso rinnovarti una tessera di iscrizione scaduta per una quota di due monete d'oro. Paghi la quota e ti rilascio una tessera nuova, che ti dà accesso agli schemi di ingegneria Goblin presso gli istruttori adatti.$B$BQuesta tessera vale per due settimane di attività, e quando scadono dovrai pagare di nuovo le quote di iscrizione! Per accedere agli schemi devi metterti in regola con gli arretrati.",
  en_title = "Membership Card Renewal",
}
T[3647] = {
  title = "Rinnovo della Tessera di Iscrizione",
  progress = "Per rinnovare la tessera di iscrizione devi pagare la quota di rinnovo: due monete d'oro.",
  reward = "Pratichi l'ingegneria Gnomesca e sei in regola, quindi posso rinnovarti la tessera di iscrizione scaduta per una quota di due monete d'oro. Paghi la quota e ricevi una tessera nuova, che ti apre gli schemi di ingegneria Gnomesca presso gli istruttori adatti.$B$BLa tessera dura due settimane di attività, e poi le quote di iscrizione vanno pagate di nuovo! Se vuoi accedere agli schemi, dovrai metterti in pari con i pagamenti arretrati.",
  en_title = "Membership Card Renewal",
}
T[3661] = {
  title = "Prediletti di Elune?",
  desc = "I wildkin sono creature davvero imprevedibili, $N. Sanno essere di una dolcezza incredibile, ma diventano ferocissimi se qualcosa a cui tengono viene minacciato.$B$BSi dice che sia stata Elune a creare queste bestie, e vorrei scoprire se è vero.$B$BDi recente ho sentito parlare di una popolazione di wildkin che vive nelle Hinterlands — Bestiagufi Feroci, Bestiagufi Primitivi e Savage Owlbeasts. Li troverai in mezzo agli altri animali della zona. Mi raccoglieresti un po' di wildkin feathers?",
  obj = "Raccogli 15 Wildkin Feathers in Hinterlands per Erelas Ambersky a Rut'theran Village.",
  progress = "Cerca di evitarli, se puoi, $N. I Wildkin potrebbero scambiare il tuo interesse per l'intenzione di far loro del male...",
  reward = "Grazie per avermele portate, $N.$B$BChe cosa hai scoperto sui Wildkin?$B$BForse queste penne ci diranno qualcosa di più. Mostri feroci o semplici animali domestici confusi? Un giorno vorrei conoscere la verità...$B$BContinuerò le ricerche — torna a trovarmi fra qualche tempo, per favore.",
}
T[3681] = {
  title = "Tome of Divinity",
  desc = "Scusa se ti interrompo nei tuoi viaggi, $R, ma ho pensato che dovessi saperlo: da poco è arrivato un messaggio da Stormwind che chiede ai paladini di presentarsi lì per addestrarsi.$B$BSe non sbaglio sei $Gvicino:vicina; a un momento speciale, ed è ora che tu cominci a studiare i Tomi.$B$BCerca Duthorian Rall a Stormwind. Di solito addestra i paladini nella Cathedral of Light.",
  obj = "Parla con Duthorian Rall a Stormwind.",
  reward = "$GBenvenuto:Benvenuta; nella Cathedral of Light, $C.",
  en_title = "Tome of Divinity",
  en_obj = "Speak with Duthorian Rall in Stormwind.",
}
T[3701] = {
  title = "Le Fumanti Ruins of Thaurissan",
  desc = "Avventurati tra le rovine fumanti di Thaurissan, nelle Burning Steppes, e raccogli tutte le informazioni che riesci a trovare.$B$BSi dice che tra le rovine siano sparse delle mysterious relics: forse è da lì che dovresti cominciare a cercare, $N. Sta' $Gattento:attenta; ai guardiani di Thaurissan: Assassini che sorvegliano le rovine per difendere i segreti che potrebbero esservi ancora sepolti.",
  obj = "Avventurati fino a Ruins of Thaurissan, in Burning Steppes, e recupera informazioni dalle Reliquie di Thaurissan. Torna da Royal Historian Archesonus quando avrai recuperato le informazioni.",
  progress = "Hai nuove informazioni per me?",
  reward = "Oh, cielo! Queste informazioni chiariscono parecchie cose su Thaurissan.$B$BE c'è ancora tanto da scoprire!",
}
T[3702] = {
  title = "Le Fumanti Ruins of Thaurissan",
  desc = "Ti va di sentire, in breve, la storia dei nani Dark Iron?",
  obj = "Ascolta Royal Historian Archesonus mentre racconta la storia di Thaurissan.",
  progress = "Lascia che finisca di raccontarti la storia di Thaurissan.",
  reward = "Andiamo avanti?",
}
T[3721] = {
  title = "Un OOX Tutto per Te",
  reward = "Hai recuperato tre dei miei robot autoguidati OOX! Sei $Gandato:andata; ben oltre il dovuto, quindi per tutto il tuo aiuto ti darò qualcosa di speciale. È una versione in miniatura proprio del robot che hai imparato a conoscere e ad amare, l'OOX!$B$BDi solito un congegno così potenzialmente letale non lo lascerei a nessuno, ma mi sei $Gstato:stata; davvero d'aiuto. E poi — su questo modello i meccanismi di combattimento e la logica di autoguida sono stati disattivati.$B$BPer il resto, è un OOX, perdinci!",
}
T[3761] = {
  title = "Un'Goro Soil",
  desc = "Pare che il terreno dell'Un'Goro Crater sia ricco di potenti proprietà magiche. Il Cenarion Circle vuole studiarne grandi quantità; va' nelle terre selvagge di Un'Goro e raccoglierne abbastanza da portare avanti le nostre ricerche.$B$BQua e là troverai cumuli di terreno fertile, e su alcune bestie potresti trovare dei campioni utilizzabili. Portali tutti fuori, da Ghede; cerca i mucchi di terra e il tauren che sbraita ordini. Non lo fa per cattiveria, ma cerca di non farlo arrabbiare!",
  obj = "Porta 20 campioni di Un'Goro Soil a Ghede su Elder Rise di Thunder Bluff.",
  progress = "Riposo, Soldato. Se sei qui a scaricare il terreno di Un'Goro — allora ottimo! Altrimenti, sparisci.",
  reward = "Ah, ma certo, Soldato $N, non fare il minimo sforzo per aiutarmi a scaricare il terreno sui mucchi! Se i Grandi Spiriti l'avessero voluto, ce l'avrebbero portato lassù con un miracolo, no?!$B$BL'Arcidruido Runetotem vuole parlarti ancora, ma per il suo prossimo compito vedrai che ti farà comodo una conoscenza da esperto di Erboristeria. Se però non ce l'hai, troverà comunque come impiegarti.",
  en_title = "Un'Goro Soil",
  en_obj = "Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff.",
}
T[3762] = {
  title = "Assistere l'Arcidruido Runetotem",
  desc = "Scusami, $C, se puoi vorrei rubarti solo un momento.$B$BIl Cenarion Circle di Thunder Bluff sta cercando proprio avventurieri esperti come te, che lo aiutino in una ricerca di vitale importanza. I dettagli non li conosco, ma so che a guidarla è nientemeno che Hamuul Runetotem.$B$BTi prego — se sei $Ginteressato:interessata;, va' a parlare direttamente con lui sull'Elder Rise, nella città di Thunder Bluff.",
  obj = "Parla con Arch Druid Hamuul Runetotem a Thunder Bluff.",
  reward = "Salute, $C; sono lieto che tu sia $Ginteressato:interessata; ad aiutarci nella ricerca. C'è molto da fare, e ti farei un torto se ti dicessi che non è un lavoro pericoloso. Spero che non ti spaventi... ma dal tuo aspetto direi che il pericolo lo conosci già.",
  en_title = "Assisting Arch Druid Runetotem",
  en_obj = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.",
}
T[3763] = {
  title = "Aiutare Arch Druid Staghelm",
  desc = "Scusami, $C, vorrei rubarti solo un momento, se possibile.$B$BIl Cenarion Circle di Darnassus cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca di vitale importanza. Non ne conosco i dettagli, ma posso dirti che a guidarlo è nientemeno che Arch Druid Fandral Staghelm.$B$BTi prego — se sei $Ginteressato:interessata;, parla direttamente con lui nella Cenarion Enclave, proprio a Darnassus.",
  obj = "Parla con Arch Druid Fandral Staghelm a Darnassus.",
  reward = "Bene, $C... ti hanno detto che a guidare questa ricerca sono io in persona, perciò sei $Gvenuto:venuta; di corsa, ovviamente.$B$BOra che sei qui, ascolta bene i dettagli, perché te li spiego una volta sola; non ho alcuna voglia di ripetermi.",
}
T[3764] = {
  title = "Un'Goro Soil",
  desc = "Si dice che il suolo dell'Un'Goro Crater sia ricco di potenti proprietà magiche. Voglio separare i fatti dalle dicerie: addentrati nelle terre selvagge di Un'Goro e raccogli abbastanza campioni di terreno di buona qualità da permetterci di proseguire gli studi.$B$BForse pensi che raccogliere roba sia un compito al di sotto delle tue capacità; con un atteggiamento simile non ti guadagnerai la stima né mia né del Cenarion Circle. Porta i campioni a Jenal, che senza dubbio starà perdendo tempo qui fuori, dietro quest'albero; basta cercare i cumuli di terriccio. Della logistica si occuperà lui — non io.",
  obj = "Porta 20 campioni di Un'Goro Soil a Jenal, in Cenarion Enclave a Darnassus.",
  progress = "Ah sì, la terra. L'Arcidruido vuole venti carichi per ogni avventuriero, e venti carichi avrà. Che chi trama contro di noi si perda per strada!",
  reward = "Scarica qui il tuo prezioso carico, nobile $C. Dev'essere stato un bel fardello... non diverso da quello che porta un visionario come me. Ecco un compenso per il tuo lavoro, come stabilito dall'Arcidruido in persona.$B$BArch Druid Staghelm vuole parlarti di nuovo, $N, ma per il suo prossimo incarico ti sarà d'aiuto avere già una discreta conoscenza dell'Erbalismo. Se però non lo conosci, potrai comunque renderti utile al Circolo!",
}
T[3765] = {
  title = "La Corruzione in Terre Lontane",
  desc = "Stormwind — che centro animato.$B$BSono venuto da lontano in cerca di aiuto, perché si dice spesso che per le strade di questa città girino avventurieri coraggiosi.$B$BMio fratello, Gershala, ha bisogno di una mano a Darkshore, dove vive, nella città costiera di Auberdine.$B$BIl viaggio è lungo ed epico, ed è per questo che mi rivolgo a $Gun:una; $C $Gesperto:esperta; come te.",
  obj = "Raggiungi Gershala Nightwhisper ad Auberdine.",
  reward = "Ah, dunque ti manda mio fratello, Argos? Sarai $Gstanco:stanca; dal viaggio, immagino. Ma abbiamo molte cose di cui parlare.",
  en_title = "The Corruption Abroad",
  en_obj = "Travel to Gershala Nightwhisper in Auberdine.",
}
T[3781] = {
  title = "Ricerca sul Morrowgrain",
  desc = "Con quello che chiamiamo Evergreen Pouch abbiamo coltivato semi di Tharlendris nel terreno dell'Un'Goro Crater. Da questi semi nascono, a caso, erbe potenti di ogni tipo. Una di queste è il morrowgrain, un'erba misteriosa di cui sappiamo poco; intendo svelarne i segreti.$B$BPorta questo a Mathrengyl, al piano di sotto, e ti darà dei semi per cominciare. Se li finisci, dovrai comprarne altri da lui.",
  obj = "Porta il Seed Voucher dell'Arcidruido a Mathrengyl Bearwalker a Cenarion Enclave of Darnassus.",
  progress = "Pace e serenità a te, $Gamico:amica;. Ti manda l'Arcidruido in persona, vero?",
  reward = "Sì, questo buono vale venti pacchetti di semi. Se li finisci, possiamo fornirtene altri. Purtroppo, però, produrre semi di Tharlendris in gran quantità è piuttosto costoso. Per questo il Cenarion Circle chiede a chi ci aiuta di contribuire coprendo parte della spesa.$B$BChi torna con del morrowgrain scopre che la ricompensa offerta dall'Arcidruido ripaga di gran lunga quanto ha speso.",
}
T[3782] = {
  title = "Ricerca sul Morrowgrain",
  desc = "Nel terreno dell'Un'Goro Crater abbiamo coltivato semi di Tharlendris, servendoci di quello che chiamiamo un Evergreen Pouch. Ne è nata una varietà casuale di erbe potenti, e fra queste c'è il morrowgrain: un'erba misteriosa, di cui sappiamo poco. Spero proprio di venirne a capo, per il Circolo.$B$BPorta questo buono a mia figlia Bashana, che ti darà dei semi per aiutarci. Se li finirai, dovrai comprarne altri da lei.",
  obj = "Porta il Seed Voucher a Bashana Runetotem a Thunder Bluff.",
  progress = "Pace a te, $Gamico:amica;. Ti manda l'Arcidruido in persona, vero?",
  reward = "Sì, questo buono vale venti pacchetti di semi. Se li finirai, ne ho altri da venderti.$B$BPurtroppo, $N, produrre semi di Tharlendris in grandi quantità costa parecchio, e per questo il Cenarion Circle chiede a chi ci aiuta di coprire una parte della spesa. Chi torna con il morrowgrain, però, scopre che la ricompensa dell'Arcidruido ripaga il costo con largo margine.",
  en_title = "Morrowgrain Research",
  en_obj = "Take the Seed Voucher to Bashana Runetotem in Thunder Bluff.",
}
T[3783] = {
  title = "Siamo Arrivati, Yeti?",
  desc = "I miei amici hanno sempre delle grandi idee, e io non mi sono mai sentita alla loro altezza... fino a oggi! Ho appena disegnato i progetti di una cosa fantastica! Se prometti di non dirlo a nessuno, ti svelo il segreto...$B$BCostruirò un mechanical yeti! Quando lo vedranno, i miei amici si prenderanno un colpo di sicuro, e quando si saranno ripresi so che ne rimarranno impressionati!$B$BPer cominciare mi serve della thick yeti fur degli ice thistle yeti. Mi dai una mano? Li trovi a sud-est.",
  obj = "Raccogli 10 Thick Yeti Furs per Umi Rumplesnicker a Everlook.",
  progress = "Qui ho un sacco di cose da cominciare. Portami quelle pellicce appena puoi, per favore!",
  reward = "Queste pellicce sono perfette, $N. Siamo partiti alla grande!",
}
T[3784] = {
  title = "Assistere l'Arcidruido Runetotem",
  desc = "Scusami, $C, se puoi vorrei rubarti solo un momento.$B$BIl Cenarion Circle di Thunder Bluff sta cercando proprio avventurieri esperti come te, che lo aiutino in una ricerca di vitale importanza. I dettagli non li conosco, ma so che a guidarla è nientemeno che Hamuul Runetotem.$B$BTi prego — se sei $Ginteressato:interessata;, va' a parlare direttamente con lui sull'Elder Rise, nella città di Thunder Bluff.",
  obj = "Parla con Arch Druid Hamuul Runetotem a Thunder Bluff.",
  reward = "Salute, $C; sono lieto che tu sia $Ginteressato:interessata; ad aiutarci nella ricerca. C'è molto da fare, e ti farei un torto se ti dicessi che non è un lavoro pericoloso. Spero che non ti spaventi... ma dal tuo aspetto direi che il pericolo lo conosci già.",
}
T[3785] = {
  title = "Ricerca sul Morrowgrain",
  desc = "Ecco l'Evergreen Pouch che ti servirà per i semi di Tharlendris. Dovrai anche avere sottomano dei campioni di terra di Un'Goro, che faranno da fertilizzante. Una volta che hai tutto, basta usare lo zaino: al resto penserà lui.$B$BQuando avrai abbastanza morrowgrain, portamelo qui all'enclave. Per favore, non importunare l'Arcidruido; è un uomo molto impegnato, e non c'è bisogno di disturbarlo ogni volta che qualcuno torna con un'altra partita di morrowgrain!",
  obj = "Usa un Evergreen Pouch con un Pacchetto di Semi di Tharlendris e due campioni di Un'Goro Soil per provare a coltivare un po' di Morrowgrain.$B$BPorta 10 pezzi di Morrowgrain a Mathrengyl Bearwalker a Darnassus.",
  progress = "Allora, $N, hai coltivato del morrowgrain per le importanti ricerche dell'Arcidruido? Il lavoro che lui svolge per il Cenarion Circle è fondamentale, e il tuo aiuto non passerà inosservato!",
  reward = "Ben fatto, $N, mi assicurerò di consegnarlo all'Arcidruido in persona quando ne avrà bisogno. Nel frattempo, accetta questo come segno di gratitudine da parte del Cenarion Circle.$B$BDi morrowgrain non ne abbiamo mai abbastanza; se vuoi continuare ad aiutarci, torna da me quando ne avrai coltivato dell'altro.",
}
T[3786] = {
  title = "Ricerca sul Morrowgrain",
  desc = "Ecco l'Evergreen Pouch: è con questo che userai i semi di Tharlendis. Ti serviranno anche dei campioni di terreno di Un'Goro, che faranno da fertilizzante. Quando avrai tutto, usa lo zaino e al resto penserà lui.$B$BAppena avrai abbastanza morrowgrain, portameli qui all'Elder Rise. E per favore, non disturbare l'Arcidruido: fra la ricerca e le tante preoccupazioni che ha, sarà molto impegnato!",
  obj = "Usa un Evergreen Pouch con un Pacchetto di Semi di Tharlendis e due campioni di Un'Goro Soil per provare a coltivare del Morrowgrain.$B$BPorta 10 Morrowgrain a Bashana Runetotem a Thunder Bluff.",
  progress = "Sì, $N, hai coltivato un po' di morrowgrain per l'importante ricerca dell'Arcidruido? Grazie al tuo aiuto, le misteriose proprietà dell'Un'Goro Crater si fanno ogni giorno più chiare.",
  reward = "Ben fatto, $N: li consegnerò senz'altro all'Arcidruido in persona, quando ne avrà bisogno. Intanto accetta questo, in segno di gratitudine da parte del Cenarion Circle.$B$BPer ora di morrowgrain abbiamo sempre bisogno: se vuoi continuare ad aiutarci, torna quando ne avrai coltivato dell'altro.",
  en_title = "Morrowgrain Research",
  en_obj = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.$B$BBring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff.",
}
T[3787] = {
  title = "La Richiesta di Jonespyre",
  desc = "Scusami, $Gamico:amica;...$B$BUn mio collega vorrebbe parlarti della ricerca che stai portando avanti con il Cenarion Circle. È un druido, si chiama Quintis Jonespyre e risiede alla Feathermoon Stronghold, a Feralas. Vorrebbe discutere con te del morrowgrain... e gli preme molto che l'Arcidruido non venga a sapere niente di questa nostra conversazione.$B$BSe sei $Ginteressato:interessata;, va' a parlargli: di sicuro ti svelerà ogni cosa.",
  obj = "Parla con Quintis Jonespyre a Feathermoon Stronghold.",
  reward = "Grazie di essere $Gvenuto:venuta;, $Gstanco viaggiatore:stanca viaggiatrice;! Lascia che mi presenti — sono Quintis Jonespyre, druido e umile servitore di Malfurion e del Cenarion Circle. Io e i miei colleghi (General Shandris Feathermoon e il Protettorato — forse avrai sentito parlare di noi) volevamo parlarti del lavoro che stai facendo per Fandral Staghelm a Darnassus.$B$BPrima di entrare nel vivo, vorrei chiederti di tenere questa conversazione fra noi. Se ti sta bene, possiamo cominciare.",
  en_title = "Jonespyre's Request",
  en_obj = "Speak with Quintis Jonespyre in Feathermoon Stronghold.",
}
T[3788] = {
  title = "La Richiesta di Jonespyre",
  desc = "Scusami, $Gamico:amica;...$B$BUn mio collega vorrebbe parlarti della ricerca che stai portando avanti con il Cenarion Circle. È un druido, si chiama Quintis Jonespyre e risiede qui alla Feathermoon Stronghold. Vorrebbe discutere con te del morrowgrain... e gli preme molto che l'Arcidruido non venga a sapere niente di questa nostra conversazione.$B$BSe sei $Ginteressato:interessata;, va' a parlargli: di sicuro ti svelerà ogni cosa.",
  obj = "Parla con Quintis Jonespyre a Feathermoon Stronghold.",
  reward = "Grazie di essere $Gvenuto:venuta;, $Gstanco viaggiatore:stanca viaggiatrice;! Lascia che mi presenti — sono Quintis Jonespyre, druido e umile servitore di Malfurion e del Cenarion Circle. Io e i miei colleghi (General Shandris Feathermoon e il Protettorato — forse avrai sentito parlare di noi) volevamo parlarti del lavoro che stai facendo per Fandral Staghelm a Darnassus.$B$BPrima di entrare nel vivo, vorrei chiederti di tenere questa conversazione fra noi. Se ti sta bene, possiamo cominciare.",
}
T[3789] = {
  title = "Aiutare Arch Druid Staghelm",
  desc = "Scusami, $C, vorrei rubarti solo un momento, se possibile.$B$BIl Cenarion Circle di Darnassus cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca di vitale importanza. Non ne conosco i dettagli, ma posso dirti che a guidarlo è nientemeno che Arch Druid Fandral Staghelm.$B$BTi prego — se sei $Ginteressato:interessata;, parla direttamente con lui nella Cenarion Enclave, proprio a Darnassus.",
  obj = "Parla con Arch Druid Fandral Staghelm a Darnassus.",
  reward = "Bene, $C... ti hanno detto che a guidare questa ricerca sono io in persona, perciò sei $Gvenuto:venuta; di corsa, ovviamente.$B$BOra che sei qui, ascolta bene i dettagli, perché te li spiego una volta sola; non ho alcuna voglia di ripetermi.",
  en_title = "Assisting Arch Druid Staghelm",
  en_obj = "Speak with Arch Druid Fandral Staghelm in Darnassus.",
}
T[3790] = {
  title = "Aiutare Arch Druid Staghelm",
  desc = "Scusami, $C, vorrei rubarti solo un momento, se possibile.$B$BIl Cenarion Circle di Darnassus cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca di vitale importanza. Non ne conosco i dettagli, ma posso dirti che a guidarlo è nientemeno che Arch Druid Fandral Staghelm.$B$BTi prego — se sei $Ginteressato:interessata;, parla direttamente con lui nella Cenarion Enclave, proprio a Darnassus.",
  obj = "Parla con Arch Druid Fandral Staghelm a Darnassus.",
  reward = "Bene, $C... ti hanno detto che a guidare questa ricerca sono io in persona, perciò sei $Gvenuto:venuta; di corsa, ovviamente.$B$BOra che sei qui, ascolta bene i dettagli, perché te li spiego una volta sola; non ho alcuna voglia di ripetermi.",
}
T[3791] = {
  title = "Il Mistero del Morrowgrain",
  desc = "Sarò franco con te, $N. Mi incuriosisce — anzi, mi preoccupa il motivo per cui l'Arcidruido di Darnassus si serve del nome del Cenarion Circle, e pure delle sue risorse, per procurarsi quantità enormi di morrowgrain. Sono un ricercatore, e le maledizioni sono la mia specialità. Ho sentito dire che i morrowgrain, nelle giuste condizioni, sprigionano proprietà simili a quelle di altre erbe usate nelle maledizioni primitive.$B$BVoglio saperne di più, e ti chiedo di aiutarmi. Portami dieci morrowgrain e non mancherò di ricompensarti.",
  obj = "Porta 10 Morrowgrain a Quintis Jonespyre a Feathermoon Stronghold.",
  progress = "Mi servono dieci morrowgrain — almeno per avviare la ricerca dovrebbero bastare. Di sicuro ne consumerò parecchi dietro a piste sbagliate, ma è così che funziona.",
  reward = "Puah, questi morrowgrain mi fanno sentire... strano. In nome di Elune, cosa sta combinando Staghelm con questa roba?$B$BComunque, grazie ancora dell'aiuto. Ecco una cosetta... sai, per la fatica. La ricerca sul morrowgrain mi porterà via un po' di tempo, e di sicuro me ne servirà dell'altro. Già che ci sono, potrei anche vedere se i morrowgrain hanno qualche uso utile in alchimia. Eppure, mi mette a disagio anche solo starci vicino.",
}
T[3792] = {
  title = "Morrowgrain per la Feathermoon Stronghold",
  progress = "Salve di nuovo, $N. Le ricerche procedono abbastanza bene, ma se hai altri cinque Morrowgrain sarei felice di prenderli. Be'... felice per modo di dire, in questo caso; più ci sto vicino, più mi sento a disagio. Ma la ricerca mi impone di rimboccarmi le maniche e andare fino in fondo.",
  reward = "Grazie, $N; per ora li metto da parte. Non ho le risorse di Staghelm, ma qualcosina per il disturbo posso dartela. E poi, chissà cosa succederà se Staghelm continua a ricevere Morrowgrain su Morrowgrain. Qui gatta ci cova, dammi retta.$B$BRicorda che cerco sempre altri Morrowgrain, cinque alla volta.",
}
T[3801] = {
  title = "Eredità dei Dark Iron",
  desc = "Saluti, $N. Sono Franclorn Forgewright. Sì, proprio quel Franclorn Forgewright, quello a cui si deve il metodo architettonico della pietra lavorata. Nelle tue avventure per questo nostro mondo dilaniato dalla guerra avrai di sicuro attraversato una delle mie creazioni, o ci sarai $Gsalito:salita; sopra.$B$BTi starai chiedendo cosa ci faccio qui e cosa voglio da te — domande legittime, tutte e due.$B$BMi serve il tuo aiuto, naturalmente. E in cambio ti darò la chiave per le profondità della mia città maledetta.",
  obj = "Parla con Franclorn Forgewright se sei $Ginteressato:interessata; a ottenere una chiave della città principale.",
  reward = "Che ti abbia portato qui l'avidità o un gesto di devozione disinteressata, quello che stai per intraprendere è per il bene di tutti noi.",
}
T[3802] = {
  title = "Eredità dei Dark Iron",
  desc = "Fineous Darkvire lo troverai nell'Hall of Crafting, oltre il Ring of Law. Uccidi quel cane miserabile e riprendi Ironfel.$B$BPorta Ironfel allo Shrine of Thaurissan e metti il martello dove gli spetta: nelle mani della statua eretta in mio onore.$B$BFatto questo, si aprirà lo scomparto dove ho custodito la chiave maestra. E, cosa ancora più importante, Ironfel resterà per sempre fra le mie mani. Se provassero a toglierlo, la statua e il martello andrebbero in frantumi tutti e due, perduti per sempre.",
  obj = "Uccidi Fineous Darkvire e recupera il grande martello, Ironfel. Porta Ironfel a Shrine of Thaurissan e mettilo sulla statua di Franclorn Forgewright.",
  progress = "La statua incombe su di te, minacciosa.",
  reward = "Il martello si incastra saldo al suo posto, fra le mani dell'enorme monumento Dark Iron, e alla base della statua si apre un minuscolo scomparto. Dentro trovi...",
}
T[3803] = {
  title = "Morrowgrain per Darnassus",
  progress = "L'Arcidruido cerca sempre altro morrowgrain per portare avanti le ricerche del Cenarion Circle.  Lo accettiamo a lotti di dieci, e in cambio ti diamo una scorta di merci che ti torneranno utili.  Quando ne avrai un lotto, fammelo sapere e ti ricompenserò di conseguenza.",
  reward = "Eccellente — questo morrowgrain farà senz'altro piacere all'Arcidruido.  Devo ammettere però... che anche solo starci vicino mi mette un po' a disagio.  Posso solo immaginare quanto gli costi tollerarne in quantità così grandi!$B$BEcco per te, $N.  Il Cenarion Circle ti ringrazia per il costante sostegno.",
}
T[3804] = {
  title = "Morrowgrain per Thunder Bluff",
  progress = "L'Arcidruido cerca sempre altro morrowgrain per il progetto di ricerca del Cenarion Circle sull'Un'Goro Crater. Ne prendiamo dieci alla volta, e in cambio ti diamo una scorta di beni che dovrebbero tornarti utili. Quando ne avrai dieci, dimmelo e ti ricompenserò come si deve.",
  reward = "Eccellente — questo morrowgrain ci sarà senz'altro d'aiuto, quando verrà il momento. Sappiamo che gli elfi della notte stanno facendo ricerche simili su queste erbe, anche se non è chiaro a cosa le useranno, nel caso scoprano qualcosa. Secondo l'Arcidruido il morrowgrain ci servirà finché non avremo svelato i misteri di quest'erba.$B$BQuesto è per te, $N: il Cenarion Circle ti ringrazia perché continui a sostenerlo.",
  en_title = "Morrowgrain to Thunder Bluff",
}
T[3821] = {
  title = "Dreadmaul Rock",
  desc = "Più di tre settimane fa hanno mandato Sha'ni nelle Burning Steppes a indagare su alcune segnalazioni di strane attività rituali degli ogres Firegut.$B$BGoretooth dice che da quel plotone non si è fatto sentire nessuno e che farei meglio a voltare pagina e pensare al mio dovere. Ti rendi conto? È mia moglie!$B$BIo non posso lasciare il mio posto, $N, ma devo sapere che fine ha fatto Sha'ni. Va' tu nelle Burning Steppes a cercarla.",
  obj = "Avventurati in Burning Steppes e scopri che fine ha fatto Sha'ni Proudtusk.",
  reward = "Il mio povero Thal'trak.$B$BFiniti i turni di servizio, volevamo andare a vivere dai miei genitori, nelle Hinterlands. E adesso è andato tutto in fumo!",
  en_title = "Dreadmaul Rock",
  en_obj = "Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk.",
}
T[3822] = {
  title = "Krom'Grul",
  desc = "Hanno catturato il mio plotone al completo, $N, e li hanno uccisi tutti — tranne me.$B$BIl loro capo, Krom'Grul, mi voleva tenere da parte per una specie di rituale.$B$BQuella bestia mi ha incatenata a questo altare e mi ha seviziata per un'ora, finché il corpo non ha ceduto. Poi mi ha strappato dal naso l'anello nuziale e se l'è messo al dito. Una ferocia così non l'avevo mai vista!$B$BTrova Krom'Grul e uccidilo! Riporta il mio anello a Thal'trak.$B$BE digli, $N, che ci rivedremo... in un'altra vita.",
  obj = "Recupera lo Sha'ni's Nose-Ring da Krom'Grul e riportalo a Thal'trak a Kargath. Cerca nelle varie grotte e miniere di Dreadmaul Rock.",
  progress = "Hai trovato Sha'ni? Sta bene?",
  reward = "<Thal'trak crolla.>$B$BDovevamo trasferirci nelle Hinterlands, te l'ha detto? Questa doveva essere la sua ultima missione.$B$B<Thal'trak singhiozza.>$B$BNon lo voglio, $N. Tienilo, buttalo, non m'importa! Ormai quell'anello per me non significa niente. Non senza di lei...",
}
T[3823] = {
  title = "Spegnere i Firegut",
  desc = "Dobbiamo colpire i nemici prima che ci colpiscano loro!$B$BSarò breve, $Gsoldato:soldatessa;.$B$BGli ogres Firegut delle Burning Steppes sono alleati di quei vili orchi Roccianera e lavorano gomito a gomito con loro: giorno e notte sorvegliano il Dreadmaul Rock, ricco di minerali, e tengono aperte le linee di rifornimento.$B$BLascia il segno, $N. Paralizza le loro forze e torna da me a lavoro finito.$B$B<Oralius afferra l'aria come per strangolare qualcuno.>$B$BTI UCCIDERÒ, WINKY!",
  obj = "Uccidi 15 Firegut Ogre-Mages, 7 Firegut Ogres e 7 Firegut Ogre Brutes, poi torna da Oralius.",
  progress = "Sulla tua uniforme non c'è neanche lontanamente abbastanza sangue, $Gsoldato:soldatessa;!",
  reward = "Eccezionale, $Gsoldato:soldatessa;! Orchi e ogres accuseranno il colpo per minuti, forse addirittura per ore!",
}
T[3824] = {
  title = "Gor'tesh il Signore dei Bruti",
  desc = "Te lo dico io, stanno barcollando! Il prossimo colpo dev'essere quello decisivo.$B$BGor'tesh, il signore dei bruti, deve morire. E soprattutto devi portarmi la sua testa: così potrò preparare la terza fase dell'attacco agli ogres Firegut.$B$BTi avverto, $Gsoldato:soldatessa;: Gor'tesh non comanda dal Dreadmaul Rock, ma da una costruzione degli orchi Roccianera a ovest del Dreadmaul Rock.$B$BQuindi gli ordini sono semplici: trova Gor'tesh e tagliagli quella testa grassa. Torna da me a lavoro finito.$B$BSTAI ZITTO, WINKY!",
  obj = "Trova Gor'tesh, da qualche parte a ovest di Dreadmaul Rock. Uccidi Gor'tesh, poi porta la Gor'tesh's Lopped Off Head a Oralius, in Burning Steppes.",
  progress = "Oh, giorno glorioso! Sei $Gtornato:tornata; con la testa?",
  reward = "Guardala, $Gsoldato:soldatessa;. Disgustosa! Quando gli ogres Firegut rimasti vedranno questo muso grasso infilzato su una picca in cima alla loro montagna, sarà un'isteria di massa!$B$B<Oralius sghignazza come un pazzo.>",
}
T[3825] = {
  title = "Testa di Ogre su un Palo = Festa",
  desc = "Ti resta un'ultima cosa da fare, $Gsoldato:soldatessa;.$B$BMi sono preso la libertà di infilzare la testa di Gor'tesh su una picca. Adesso devi solo portare questa testa in cima al Dreadmaul Rock e piantarla nel terreno. Poi guarda quegli ogres codardi scappare per salvarsi la pelle! Quando ti sarai $Gdivertito:divertita;, torna da me e ti ricompenserò per tutto il tuo duro lavoro.$B$B<Oralius sembra perdere il contatto con la realtà.>",
  obj = "Porta la Gor'tesh's Lopped Off Head e mettila in cima a Dreadmaul Rock. Cerca un dirt mound morbido in cui piantare la picca.",
  progress = "Allora? Hai dipinto qualche quadro della scena?",
  reward = "Ottimo lavoro, $Gsoldato:soldatessa;! Semplicemente incredibile! Oh, per questo mi daranno la medaglia al valore, ehm, cioè, per questo sarai $Gricompensato:ricompensata; generosamente!",
}
T[3841] = {
  title = "Un Orfano in Cerca di Casa",
  desc = "Oh, ciao, $N. Sono davvero contenta di rivederti. Com'è andato il viaggio a Darnassus?$B$BBe', sarai felice di sapere che in tua assenza siamo andati parecchio avanti. Abbiamo perfino salvato un nido pieno di uova, anche se purtroppo la madre, quando l'abbiamo raggiunta, era già morta.$B$BDimmi, ne vorresti uno come animale da compagnia? A quanto pare stanno per schiudersi, e avranno bisogno di $Gun buon padre:una buona madre;. Che ne dici?$B$BSe ti interessa davvero, porta una delle uova a Quentin, alle piste da corsa di Shimmering Flats. Ti dirà di più.",
  obj = "Parla con Quentin a Thousand Needles.",
  progress = "Oh, salve, $C.$B$BNon farti ingannare dal posto in cui mi trovi: non sono qui davvero per le corse... per quanto possano essere divertenti.$B$BIn realtà sono venuto a Thousand Needles per indagare il più possibile e capire quanto di questa terra si possa ancora recuperare. Ormai è una specie di crociata personale: ridare vita a questa zona e rinnovarla con terra nuova e fertile. Forse scoprirò che qui vicino c'è una fonte d'acqua.$B$BNon dirmi che non hai notato quanto sia strano il passaggio fra Feralas e Thousand Needles. Quando è successo, c'era all'opera una strana magia.",
  reward = "Ah, uno sprite darter egg, e quasi maturo, se non mi sbaglio. È straordinario che tu ne abbia trovato uno, e per giunta in condizioni così buone: di questi tempi a Feralas se ne vedono di rado. Da quanto so, in zona c'erano diversi bracconieri che cercavano di catturarli e di ucciderli, per molte ragioni. Davvero un peccato... sono creature così belle, da adulte.$B$BCome hai fatto a trovare una cosa del genere?",
}
T[3842] = {
  title = "Una Breve Incubazione",
  desc = "I Moonweaver, eh? Molto intrigante. Vorrei che gli sprite darters potessero capire davvero cosa voglia dire avere quei due a prendersi cura di loro. Sono entrambi molto capaci.$B$BQuindi l'uovo te l'hanno regalato. Bene, allora dovrai occupartene tu, per tutto il tempo che vorrai. Sembra quasi pronto a schiudersi, ma dobbiamo essere sicuri che sia sano e che non abbia subito danni.$B$BMi bastano due elisir di tempra per un piccolo incantesimo che protegga l'uovo: gli altri componenti li ho qui con me.",
  obj = "Porta 2 Elixir of Fortitudes a Quentin a Thousand Needles.",
  progress = "Più resto qui, più sono tentato di partecipare a queste corse, $N. Davvero sconcertante...$B$BHai già trovato gli elisir? Appena potrò dirti se l'uovo sarà sano o no, te lo restituirò, e lo terrai tu finché non sarà pronto a schiudersi.$B$BFammi sapere.",
  reward = "Magnifico. Andranno benissimo. Dammi un momento per mescolare i componenti, e vedremo come se la caverà quest'uovo.",
}
T[3843] = {
  title = "Il Nuovo Membro della Famiglia",
  desc = "Un esemplare magnifico, $N. Se questa creatura supera la gestazione, ne verrà fuori un animale da compagnia davvero sano!$B$BSe vuoi andare fino in fondo, c'è un'ultima cosa che ti consiglierei — vai ad Aerie Peak, nell'Hinterlands, e parla con un nano di nome Agnar Beastamer: è un maestro addestratore di animali e dovrebbe saperti guidare nelle ultime fasi dell'incubazione.$B$BMa fai presto, $N: quest'uovo è fragile e senza le cure giuste non durerà a lungo.",
  obj = "Porta il tuo Fragile Sprite Darter Egg in Hinterlands e parla con Agnar Beastamer, ma sbrigati, hai solo 1 ora per trovarlo prima che il piccolo dentro l'uovo muoia.",
  progress = "Salute a te, $N. Che posso fare per te?",
  reward = "Bene, bene, bene... Era da secoli che non ne vedevo uno. Un drago delle fate, se non sbaglio... pare della varietà sprite darter. Ottimo, davvero ottimo.$B$BBe', se vogliamo che questo piccoletto si schiuda e cresca forte e sano, dobbiamo procurargli un po' di cibo. Meno male che me l'hai portato in tempo.",
}
T[3844] = {
  title = "È un Segreto per Tutti",
  desc = "Sulla riva giace una zattera distrutta. Come sia finita in uno stagno così piccolo non è chiaro, anche se dagli alberi capisci che il livello dell'acqua potrebbe non essere sempre lo stesso.$B$BForse, esplorando un po' la zona, troverai altri indizi...",
  obj = "Cerca nello stagno un indizio su chi possa essere il proprietario della zattera distrutta.",
  reward = "Sul fondo dello stagno giace uno zaino fradicio.",
}
T[3845] = {
  title = "È un Segreto per Tutti",
  desc = "Afferri lo zaino e lo trascini a riva. Se esamini quello che c'è dentro, forse riesci a scoprire qualcosa di più sul proprietario.$B$BAl Marshal's Refuge c'è qualche viaggiatore di passaggio. Lì potresti saperne di più.",
  obj = "Esamina gli oggetti nello zaino e portali al loro proprietario.",
  progress = "Ciao. Ma io ti ho già visto... O no?",
  reward = "Oh... Sì, queste cose mi dicono qualcosa... be', più o meno...",
}
T[3861] = {
  title = "COCCODÈ!",
  desc = "\"Coc... coc... coc... COCCODÈ!$B$BCoc... coc... coc.\"$B$BLa gallina alza lo sguardo su di te, poi si mette a grattare la terra con le zampe. Ti sembra che stia scrivendo una parola, ma non sei $Gsicuro:sicura; di quale. Potrebbe essere... S-A-L-D-E-A-N? Prima che tu possa chiedere, si volta e torna alle sue faccende.",
  obj = "Trova dello Special Chicken Feed e torna dalla gallina tua amica. Quando la trovi, fai /cheer verso di lei prima di provare a darle lo Special Chicken Feed.",
  progress = "La gallina ti fissa, gli occhi scuri e freddi. Affamata, ti aspetta.$B$B\"COCCODÈÈÈ!$B$BCoc...coc...coc.\"",
  reward = "\"COCCODÈ!!!\"$B$BLa gallina si getta sul mangime che hai posato a terra e se ne ingozza.$B$BDopo un momento si guarda intorno, spaventata, e va avanti e indietro, a disagio. Che sia incinta, questa gallina? Pensi che sia meglio dare un'occhiata sotto di lei.",
}
T[3881] = {
  title = "La Salvezza della Spedizione",
  desc = "Non so come tu sia $Garrivato:arrivata; fin qui, ma che piacere vederti! Sono Williden Marshal, a capo di una spedizione indipendente. La nostra ultima impresa, la più grande di tutte, è andata incontro a una serie di disastri che sembra non finire mai, e il peggiore è stato sottovalutare la ferocia dell'Un'Goro Crater!$B$BQuando siamo scappati dai campi base, a sud-ovest e a nord-est del cratere, ci siamo lasciati dietro delle provviste vitali. Mi sembri in gamba — ci aiuteresti a recuperarle?",
  obj = "Porta la Crate of Foodstuffs e il Research Equipment a Williden Marshal in Un'Goro Crater.",
  progress = "Se vogliamo avere qualche speranza di uscire vivi di qui, ci serve la nostra grande crate of foodstuffs. E se riuscissimo a recuperare almeno una parte del research equipment, sarebbe una benedizione in un mare di sventure.",
  reward = "Hai recuperato sia i viveri SIA il nostro research equipment! Non hai salvato solo la spedizione: ci hai salvato la vita. Io e il resto della squadra non sappiamo come ringraziarti; adesso, grazie a te, forse riusciremo a tirare avanti qui per un po'.$B$BNon abbiamo molto, ma dopo l'aiuto prezioso che ci hai dato non ti lascerò certo a bocca asciutta. Grazie, $N — nella Marshal Expeditions hai un amico!",
}
T[3882] = {
  title = "Lancia le Ossa",
  desc = "Uno direbbe che, se sono il capo scavatore della Marshal Expeditions, a me scavare piaccia. Forse a questo mondo c'è di peggio da fare... ma non mi viene in mente niente.$B$BDovevamo scavare nella Terror Run — nome FANTASTICO, tra l'altro — a caccia di stegodonti e diemetradonti morti. Beh, lì è pieno anche di quelli vivi! Wil e Hol sono ancora fissati con lo studio di questa trappola mortale, quindi ci servono quelle dinosaur bones. Ma detto tra noi, se ne porti qualcuna presa da quelli vivi, va bene lo stesso.",
  obj = "Porta 8 Dinosaur Bones a Spark Nilminer in Un'Goro Crater.",
  progress = "Pensa di me quello che vuoi, ma a loro non importerà se le ossa da studiare sono di stegodonti e diemetradonti antichi o di quelli che per poco non ci hanno divorati in un boccone mentre provavamo a montare i campi. A me basta uscirne vivi...",
  reward = "Ottimo, queste dovrebbero bastare. E adesso, se permetti...$B$BGRAZIE DI AVER DISSOTTERRATO TUTTE QUESTE OSSA PER NOI SENZA FARE IL MINIMO MALE ALLE BESTIE DEL POSTO.$B$BSe l'hai fatto davvero o no, non lo voglio sapere. Lasciamo le cose come stanno, va bene? Ecco, magari con questo terrai le labbra cucite su tutta la faccenda. Tutto pur di uscire vivi di qui, dico io!",
}
T[3883] = {
  title = "Ecologia Aliena",
  desc = "Una battuta d'arresto non vuol dire che la ricerca si debba fermare! Prima di ritrovarci qui stavamo studiando gli insetti Gorishi nella parte sud del cratere. Sono estranei all'ecologia di Un'Goro, e vogliamo scoprire perché si trovano qui.$B$BNella rete dei loro alveari ci devono essere delle incubatrici di larve: le riconosci dalle covate appese. Con questa fiala preleva un campione di parete dell'alveare vicino a una qualunque delle incubatrici, e riportamelo perché possa studiarlo. Ma fa' attenzione!",
  obj = "Usa la Fiala Raschiatrice per raccogliere un Hive Wall Sample da una delle incubatrici degli alveari Gorishi in Un'Goro Crater. Cerca le camere con le covate di larve appese.$B$BPorta l'Hive Wall Sample a Hol'anyee Marshal in Un'Goro Crater.",
  progress = "Hai con te il campione dell'alveare Gorishi da farmi studiare, $N?",
  reward = "Sì, questo andrà benissimo. Mi sei $Gstato:stata; di grande aiuto... Vorrei poterti dare di più, ma visto che siamo praticamente bloccati in mezzo a una terra selvaggia, ho ben poco da offrirti. Però stai $Gtranquillo:tranquilla; — senza il tuo aiuto le ricerche che abbiamo fatto qui non sarebbero state possibili!",
}
T[3884] = {
  title = "Il Diario di Williden",
  desc = "Hai trovato un a mangled journal. Qualche pagina si legge ancora, e un certo Williden Marshal vi scrive che è suo. Se il diario dice il vero, Williden potrebbe essere da qualche parte nella zona nord del Cratere. Stando a quello che c'è scritto, quando gli accampamenti sono stati invasi, lui e i suoi compagni sono saliti su un'altura per sfuggire alle bestie feroci del Cratere.",
  obj = "Riporta il diario a Williden Marshal, da qualche parte in Un'Goro Crater.",
  progress = "Ehilà! Io e i miei compagni siamo felici di vedere da queste parti degli esseri viventi che non siano bestie feroci cresciute a dismisura! Cosa ti porta nell'Un'Goro Crater?",
  reward = "Ma guarda un po' — il mio diario! Pensavo di averlo perso, come quasi tutto quello che ci siamo portati a Un'Goro. Grazie di cuore per avermelo riportato!",
}
T[3906] = {
  title = "Disarmonia della Fiamma",
  desc = "Gli anziani hanno percepito un turbamento fra gli elementi. I nani Dark Iron hanno evocato nel nostro mondo uno spirito immondo, che minaccia di affliggere le nostre terre con una siccità eterna. Bisogna indagare su questa disarmonia della fiamma.$B$BRecati a Blackrock Mountain e, passando per la Chasm of Flame, entra nella cava. Lì troverai questo signore del fuoco: Overmaster Pyron.$B$BMetti fine a questo sconvolgimento, poi torna da me.",
  obj = "Raggiungi la cava in Blackrock Mountain e uccidi Overmaster Pyron. Torna da Thunderheart quando avrai completato questo incarico.",
  progress = "Fra gli elementi c'è ancora subbuglio, $N.",
  reward = "Non può essere... non deve essere. La distruzione di Pyron ha solo sollevato un velo: nelle profondità di Blackrock c'è una fonte di corruzione molto più subdola.",
}
T[3907] = {
  title = "Disarmonia del Fuoco",
  desc = "Sento il sapore dell'impurità nell'aria intorno a te, $N. C'è un altro che la controlla, nascosto nelle profondità di Blackrock.$B$BIl vento e la terra gridano il suo nome: Lord Incendius... ma qualcuno... qualcosa... comanda questo essere. Non è che un emissario.$B$BTrovalo e scopri dove si nasconde il suo padrone. Quando avrai queste informazioni, torna da me.",
  obj = "Entra nelle Blackrock Depths e rintraccia Lord Incendius. Uccidilo e porta a Thunderheart ogni fonte di informazioni che riesci a trovare.",
  progress = "Presto le fiamme travolgeranno queste terre. Affrettati, $N!",
  reward = "<Thunderheart stringe la Tablet of Kurniya.>$B$BRagnaros... qui...$B$BGli anziani avevano ragione a temere la corruzione che emana da Blackrock Mountain. Un generale degli Old Gods! NEL NOSTRO MONDO! Qui a Kargath dobbiamo ripensare la nostra posizione, e decidere se restare a combattere o fuggire per paura di una nuova frattura.$B$BSe esplorerai ancora Blackrock Mountain, sii $Gcauto:cauta;, $N. In quelle profondità infuocate risiede un male molto più grande di qualunque cosa esista in questo mondo.",
}
T[3908] = {
  title = "È un Segreto per Tutti",
  desc = "Vedi, non ho idea di come ci sia arrivato. Non lo sa davvero nessuno — è un segreto per tutti! Non riesco proprio a ricordare niente...$B$BPerò con questi oggetti che mi hai portato... qualcosa mi sta tornando in mente.$B$BLa mia spada. Dovrei rafforzarla in qualche modo, ma non so bene perché. Mi dispiace non poterti dire di più, ma non me lo ricordo proprio!$B$BVabbè, so dove puoi portarla — da Donova Snowden a Winterspring. La trovi vicino alle sorgenti calde: può temprare la spada accanto alle pozze.",
  obj = "Porta la Spada di Linken a Donova Snowden in Winterspring.",
  progress = "Ma guarda un po'... Alla fine Linken si è deciso a mandarmi la sua spada.",
  reward = "Be', certo che posso temprare questa spada. Intanto che ci lavoro, puoi spiegarmi perché Linken ci ha messo tanto a farmela avere. Di solito non è uno che dimentica le cose...",
}
T[3909] = {
  title = "Il Videre Elixir",
  desc = "E questo cos'è? Linken... HA DIMENTICATO?$B$BOh, capisco... Ha perso la memoria...$B$BBe', ecco la sua spada. Però non è completa. So chi può finirla, ma... potrebbe non essere semplice parlargli.$B$BAscolta, c'è qualcuno che potrà aiutarti. Ci vorrebbe troppo a spiegarti tutto adesso, ma in un modo o nell'altro devi procurarti un Videre Elixir. Che io sappia, l'unico che può darti una mano è Gregan Brewspewer. Non è uno che si trova facilmente, ma l'ultima volta che ho avuto sue notizie era accampato nelle terre selvagge di Feralas.",
  obj = "Cerca Gregan Brewspewer nel nord di Feralas. Scopri da lui come procurarti il Videre Elixir, poi torna da Donova Snowden a Winterspring.",
  progress = "Sei già $Gtornato:tornata;?",
  reward = "Mi servirà una fiala per controllare che sia davvero l'elisir... Sì... È proprio lui.",
}
T[3911] = {
  title = "L'Ultimo Elemento",
  desc = "C'è del lavoro per chi si spinge nelle profondità, $N.$B$BI Dark Irons sono diventati maestri nel costruire golem potentissimi.$B$BStando ai primi rapporti delle nostre spie, i nani si servono di una fonte di energia unica per dare alle loro creazioni una forza omicida senza pari.$B$BPensa a cosa potremmo fare con i nostri abominations, se riuscissimo a mettere le mani su quest'essence of the elements! Metti a soqquadro quella città, se serve, ma non tornare senza l'essenza! La paga varrà il rischio.",
  obj = "Viaggia a Blackrock Depths e recupera 10 Essence of the Elements. Per prima cosa pensi di perquisire i golem e chi li costruisce. Ricordi anche che Vivian Lagrave ha borbottato qualcosa sugli elementali.",
}
T[3912] = {
  title = "Appuntamento alla Tomba",
  desc = "Con questo elisir potrai parlare con qualcuno che di solito non riusciresti nemmeno a vedere...$B$BPorta il Videre elixir e la spada di Linken al cimitero appena fuori Gadgetzan, a Tanaris, e lì bevi la pozione. Quello che succede potrebbe lasciarti piuttosto $Gsorpreso:sorpresa;, ma non allarmarti.$B$BNella tua \"altra\" forma, vai dritto a nord fino alle montagne: colui con cui devi parlare lo troverai in una delle fenditure nella roccia. Si chiama Gaeriyan.$B$BRicorda, ti parlerà solo in quella forma...",
  obj = "Vai al cimitero fuori da Gadgetzan e usa il Videre Elixir. Segui il resto delle istruzioni di Donova per trovare Gaeriyan.",
  reward = "Era da tanto che nessuno veniva a parlare con me...",
}
T[3913] = {
  title = "Una Situazione Grave",
  desc = "Se torni al cimitero, $N, troverai una lapide... e non una qualunque: questa spiccherà fra le altre. Custodisce dei segreti.$B$BSpingi la pietra, e li scoprirai...",
  obj = "Resuscita, poi cerca la lapide che Gaeriyan ti ha detto di trovare.",
  progress = "Dev'essere questa la lapide di cui parlava Gaeriyan...",
  reward = "Spingi con decisione la pietra, che scivola via e scopre sotto di sé una piccola cavità.$B$BCi metti dentro la Spada di Linken e ti accorgi che si incastra alla perfezione...",
}
T[3914] = {
  title = "La Spada di Linken",
  desc = "C'è un forte lampo di luce, e poi riesci di nuovo a raccogliere la spada. Si è trasformata!",
  obj = "Consegna la Linken's Superior Sword a Linken in Un'Goro Crater.",
  progress = "Oh! Mi ricordo di te! Sei... No, non dirmelo!",
  reward = "La mia spada... È completa!$B$BAdesso, se solo mi ricordassi a cosa mi serviva...$B$BEcco, lascia almeno che ti paghi il lavoro.",
}
T[3941] = {
  title = "L'Aiuto di uno Gnomo",
  desc = "Penso... Penso... So che sono venuto qui per qualcosa di importante...$B$BHo un'idea, $N. Nella grotta laggiù c'è una gnoma, J.D., che appena sono arrivato qui è stata molto gentile con me. Confuso com'ero, magari le ho detto qualcosa.$B$BPerché non vai a chiederle se ne sa niente? Oh, ma fai attenzione — passa il tempo ad armeggiare con quegli strambi cristalli luminosi che ho visto nel cratere. Non so bene cosa combini là dentro!",
  obj = "Trova J.D. Collie nella grotta a Marshal's Refuge.",
  reward = "Resta lì dove sei solo un momento... Sto provando una nuova combinazione di cristalli...",
}
T[3942] = {
  title = "La Memoria di Linken",
  desc = "Oh... Linken? Sì, è un tipo curioso. Quando è arrivato borbottava cose strane di ogni tipo. Avrà preso una bella botta in testa, immagino.$B$BUna cosa che ha detto però mi è rimasta in mente — stava facendo una specie di totem; diceva che doveva parlare con qualcuno di nome Eridan Bluewind... in un posto che si chiama Felwood, credo?$B$BMa adesso dubito che sappia dirti granché. Se vuoi saperne di più, forse ti conviene andare a cercare tu $Gstesso:stessa; Eridan?",
  obj = "Trova Eridan Bluewind nel sud di Felwood.",
  reward = "Salve, $C. Posso esserti d'aiuto?",
}
T[3961] = {
  title = "L'Avventura di Linken",
  desc = "E pensare che Linken era qui da tutto questo tempo per liberarci di Blazerunner... Ha l'aria di un tipo così normale, eppure ho notato che, al contrario di quasi tutti gli gnomi, dei miei esperimenti e dei miei aggeggi non gli importa proprio niente. In fondo al cuore dev'essere un vero guerriero.$B$BPortagli il totem. Vedi se lo aiuta a ricordare perché è venuto qui.",
  obj = "Porta il Silver Totem of Aquementas a Linken a Marshal's Refuge.",
  progress = "Rieccoti, $N!",
  reward = "J.D. ti ha dato una mano?",
}
T[3962] = {
  title = "È Pericoloso Andare da Soli",
  desc = "$N, finalmente ricordo... Sì, sono venuto qui per combattere Blazerunner. Ero in viaggio, e questa doveva essere l'ultima tappa.$B$BMa l'eroe non sono più io... sei tu. Dopo tutto quello che hai fatto — tocca a te portare a termine questa impresa, non a me.$B$BBlazerunner custodisce un manufatto chiamato Golden Flame, che dà un potere più grande di qualunque altra cosa io abbia mai conosciuto, ed è pericoloso nelle mani di chi ha un cuore malvagio.$B$BFaresti bene a portarti dietro qualcun altro — è pericoloso andare da soli. Questo è il mio consiglio.",
  obj = "Raggiungi Fire Plume Ridge, a sud di Marshal's Refuge.$B$BTrova Blazerunner e usa il totem per rimuovere la sua aura protettiva. Dopo averlo sconfitto, prendi la Golden Flame dalla grotta.",
  progress = "Dietro l'aura che si è creato con la Golden Flame, Blazerunner è quasi invincibile. Solo tu hai il potere di toglierla, con il Silver Totem of Aquementas.",
  reward = "Grazie, $N.$B$BOra la Golden Flame tornerà nella mia terra natale, dove potrà stare al sicuro e non sarà mai più usata per il male.$B$BSenza di te non saprei ancora chi sono! Hai fatto così tanto per me che vorrei darti qualcosa di speciale...$B$BPrendi quello che vuoi!",
}
T[3981] = {
  title = "Commander Gor'shak",
  desc = "Povero Gargal... non se l'è nemmeno vista arrivare. BAM! La freccia gli si è piantata dritta in cima alla testa. Non era un genio nemmeno prima, ma adesso...$B$B<Galamav fa una smorfia.>$B$BQuando gli abbiamo tolto la freccia, abbiamo trovato un biglietto arrotolato legato all'asta. Sopra c'era il disegno rozzo di un orco dietro le sbarre e la firma di Commander Gor'shak.$B$BSe è ancora vivo nelle Profondità, tocca a te trovarlo.$B$BUna trappola, dici? Ma non mi dire, zoccoli intorpiditi! È proprio per questo che ci vai tu!",
  obj = "Trova Commander Gor'shak nelle Blackrock Depths.$B$BRicordi che nel rozzo disegno dell'orco c'erano delle sbarre tracciate sopra il ritratto. Forse dovresti cercare una specie di prigione.",
  reward = "Non abbiamo molto tempo, $R, quindi ascoltami bene. Quello che sto per dirti è riservato: deve restare fra noi.",
}
T[3982] = {
  title = "Cosa Sta Succedendo?",
  desc = "Sono qui per ordine di Thrall. Credi davvero che questi buffoni potessero catturarmi? Mi sono fatto prendere apposta, per raccogliere informazioni.$B$B<Gor'shak sussurra.>$B$BEmperor Thaurissan ha rapito la Principessa di Ironforge, e Princess Bronzebeard è proprio qui, in questa città! Scommetto che al vecchio Magni si è quasi fermato il cuore, quando l'ha saputo.$B$B<Gor'shak ride.>$B$BShhh! Senti? Arrivano le guardie! DIFENDITI!",
  obj = "Difendi Gor'shak.",
  progress = "Difenditi, $Gsciocco:sciocca;!",
  reward = "C'è mancato poco. Ormai sanno che sei qui... di sicuro ne arriveranno altri.",
}
T[4001] = {
  title = "Cosa Sta Succedendo?",
  desc = "Con il nano della cella di fronte, Kharan, finora ho parlato poco, ma sono riuscito a convincerlo che io, anzi -noi- non vogliamo fargli del male.$B$BVa' da lui e scopri tutto quello che puoi sulla Principessa e su chi l'ha rapita. Poi riferisci ogni cosa al Capoguerra.$B$BThrall non vuole che la Principessa venga ferita: ha messo a punto un grande piano, che prevede di riportarla sana e salva a Ironforge. Kharan è già al corrente di tutto... Va'!",
  obj = "Parla con Kharan Mighthammer e raccogli informazioni sul rapimento di Princess Moira Bronzebeard. Porta quelle informazioni a Thrall a Orgrimmar.$B$BRicordi che Gor'shak ha detto che Kharan è rinchiuso in una cella qui vicino.",
  progress = "Cosa ti porta in questi luoghi sacri?",
  reward = "Per l'Orda è l'occasione di cambiare per sempre il clima politico di questo nostro mondo dilaniato dalla guerra. Ascoltami bene, $N.$B$BQuesta missione non possiamo permetterci di fallirla.",
}
T[4002] = {
  title = "Gli Eastern Kingdoms",
  desc = "Le informazioni che mi porti sono eccellenti, $N.$B$BDa Capoguerra, il mio dovere è fare ciò che è meglio per l'Orda, e far sì che le generazioni dopo di noi non siano costrette a vivere senza speranza.$B$BCi è capitata tra le mani l'occasione di plasmare le nostre alleanze future: una mossa in aiuto dei nani potrebbe rafforzare molto i nostri rapporti negli Eastern Kingdoms. Ecco perché non devi fallire!$B$BSei $Gpronto:pronta;?",
  obj = "Parla con Thrall se sei $Gpronto:pronta; ad affrontare la missione che ha preparato.",
  reward = "Da qui non si torna indietro, $N.",
}
T[4003] = {
  title = "Il Salvataggio Reale",
  desc = "Se riuscirà, questo attacco contro i nani Dark Iron provocherà un'onda d'urto in tutto il loro regno.$B$BPrincess Bronzebeard è sotto il controllo di Emperor Thaurissan, e per liberarla dovrai uccidere l'Imperatore. Ti avverto: il compito è doppiamente pericoloso, perché finché l'Imperatore la controllerà, Bronzebeard ti attaccherà senza esitare.$B$BNON FARLE DEL MALE!",
  obj = "Uccidi Emperor Dagran Thaurissan e libera Princess Moira Bronzebeard dal suo incantesimo malvagio.",
  progress = "<Princess Moira si rannicchia, impaurita.>",
  reward = "Che cosa hai fatto!",
}
T[4004] = {
  title = "La Principessa Salvata?",
  desc = "Hai ucciso mio marito, $R! Il mio bambino nascerà senza un padre.$B$B<Princess Moira ti punta il dito contro.>$B$BE sarà lui, te lo assicuro, il prossimo sovrano del regno di Ironforge. Per questo torto, tu e quelli della tua specie sarete braccati fino alla fine dei giorni.$B$B<Pensi che Princess Moira possa risentire ancora dell'incantesimo di Thaurissan.>$B$BLasciami in pace, $R. Il tuo capoguerra, ne sono certa, sarà ansioso di sapere dove hanno portato le sue intromissioni.",
  obj = "Torna da Thrall!",
  reward = "<Thrall è sconcertato da quello che gli hai riferito.>$B$BAll'orizzonte incombe una nuova minaccia. Ora che gli anni di Magni volgono al termine, questo nascituro Dark Iron avrà la strada aperta per diventare sovrano di Ironforge.$B$BHai fatto ciò che ti avevo chiesto, e per questo sarai $Gricompensato:ricompensata;.$B$BOra lasciami, $N! Devo consultarmi con Sylvanas e Cairne.",
}
T[4005] = {
  title = "Aquementas",
  desc = "Prendi questa borsa di provviste e portala con te a Tanaris. Alla Lost Rigger Cove cerca un cerchio di pietre.$B$BIl segreto è la penisola più a est...$B$BIl libro di Aquor leggilo solo da quel cerchio; evoca l'unica creatura capace di trasformare gli oggetti che hai raccolto in un totem con cui combattere Blazerunner.$B$BAquementas non sarà contento di essere risvegliato, ma ricorda, perché trasformi gli oggetti devi restare nel cerchio.",
  obj = "Porta il Book of Aquor, i Silvery Claws e l'Irontree Heart a Tanaris.$B$BUsa il Book of Aquor per evocare Aquementas.$B$BQuando avrai il totem completo, portalo a J.D. Collie a Marshal's Refuge.",
  progress = "E così sei $Gtornato:tornata;, eh? Mmm... Fammi un po' vedere, $N.",
  reward = "Blazerunner, dici...$B$BSì, lo so che al centro carbonizzato del cratere vive un elementale forte. Gli stiamo tutti alla larga; nessuno è riuscito a passare attraverso la potente aura che lo avvolge. In tanti, mentre cercavano di affrontarlo, sono stati spinti giù dai sentieri di roccia fino a terra.",
}
T[4022] = {
  title = "Un Assaggio di Fiamma",
  desc = "Lo stormo sa quello che hai fatto nella Searing Gorge.$B$BMostramela, $R. La muta, imbecille.",
  obj = "Mostra a Cyrus Therepentous la Black Dragonflight Molt che hai ricevuto da Kalaran Windblade.",
  progress = "<Gli occhi di Cyrus diventano due sfere ardenti.>",
  reward = "<Cyrus esamina la muta.>$B$BHai dimostrato che non sei del tutto inutile, mortale.",
}
T[4023] = {
  title = "Un Assaggio di Fiamma",
  desc = "Cerchi lo Stormo? Mostrami una prova del tuo valore, mortale.",
  obj = "Mostra a Cyrus Therepentous una prova del tuo valore.$B$BHai la sensazione che Cyrus sappia già che non ne sei $Gdegno:degna;.",
  progress = "<Gli occhi di Cyrus diventano due sfere ardenti.>",
  reward = "<Cyrus esamina la muta.>$B$BHai dimostrato che non sei del tutto inutile, mortale.",
}
T[4024] = {
  title = "Un Assaggio di Fiamma",
  desc = "Desidero assaporare le fiamme roventi della montagna di fuoco, lasciare che i fuochi fusi di Blackrock si riversino su tutto il mio essere. È quell'essenza che bramo, quel calore rovente.$B$BNei Depths of Blackrock dimora Bael'Gar, un essere di pura fiamma nato dai fuochi di Ragnaros. Uccidi Bael'Gar e portami dai suoi resti fumanti un frammento del suo fuoco interiore.$B$BUsa la muta sui suoi resti: così ne estrarrai la fiamma interiore senza rischi.$B$BSe ci riesci, sarai $Gricompensato:ricompensata;.",
  obj = "Viaggia fino a Blackrock Depths e uccidi Bael'Gar.$B$BSai solo che il gigante dimora dentro Blackrock Depths. Ricorda di usare l'Altered Black Dragonflight Molt sui resti di Bael'Gar per catturare l'Essenza Ardente.$B$BRiporta l'Encased Fiery Essence a Cyrus Therepentous.",
  progress = "Il gigante è caduto?",
  reward = "<Cyrus ti strappa di mano l'essenza ardente.>$B$BSÌ!$B$BPrendi il tuo premio e vattene. Sparisci subito dalla mia vista!",
}
T[4041] = {
  title = "Il Videre Elixir",
  progress = "Ma certo che posso prepararti il Videre Elixir, basta che mi porti un'Evoroot.$B$BDi erbe e alchimia ne so un sacco... Anzi, lascia che ti racconti di quando ho trasmutato in oro il formaggio che stavo per mangiarmi a pranzo... ehi... Dove vai?",
  reward = "E così l'hai fatta al vecchio Miblon, eh?",
}
T[4061] = {
  title = "L'Ascesa delle Macchine",
  desc = "Le macchine si sono fatte notare durante le nostre prime incursioni nella Searing Gorge. Indagando meglio, abbiamo scoperto che venivano portate qui dalle Burning Steppes, forse dai Blackrock Depths. Ecco perché abbiamo bisogno di te, $N.$B$BPer prima cosa andrai nelle Burning Steppes a recuperare le schegge elementali dagli automi di roccia e dalle creazioni di roccia minori della regione. Quando ne avrai raccolte abbastanza, torna da me e scoprirò da dove vengono.",
  obj = "Va' nelle Burning Steppes e recupera 10 Fractured Elemental Shards per Hierophant Theodora Mulvadania.$B$BRicordi che Theodora ha indicato i golem e gli elementali di quella regione come una fonte di queste schegge.",
  progress = "Non prendere questo compito alla leggera, $N!",
  reward = "<Theodora dispone i frammenti davanti a sé.>$B$B<Theodora esamina i frammenti con cura attraverso un enorme monocolo.>$B$BInteressante. Nella struttura di base di ognuno di questi frammenti sono incise... delle iniziali.",
}
T[4062] = {
  title = "L'Ascesa delle Macchine",
  desc = "G.L.A.$B$BEcco le 'iniziali' impresse sulle schegge elementali. Sotto c'è una specie di indicazione di grado. Le macchine che hai distrutto nelle Burning Steppes erano di 'Grado IV.' Immagino sia un grado basso.$B$BPorta questo campione di scheggia a Lotwil Veriatus, all'accampamento a est. È uno studioso piuttosto noto nel campo delle scienze elementali. Forse potrà darci una mano con la ricerca.",
  obj = "Porta l'Elemental Shard Sample a Lotwil Veriatus.$B$BRicordi che Theodora ha detto che Lotwil si trovava in un accampamento a est.",
  progress = "Che cos'hai lì, $R?",
  reward = "<Lotwil impallidisce.>$B$BIo... io questi segni li conosco.",
  en_title = "The Rise of the Machines",
  en_obj = "Take the Elemental Shard Sample to Lotwil Veriatus.$B$BYou recall Theodora saying that Lotwil was stationed in a camp to the east.$B",
}
T[4063] = {
  title = "L'Ascesa delle Macchine",
  desc = "Non può essere Argelmach! Argelmach è stato ucciso dieci anni fa. Come faccio a esserne sicuro? L'ho ucciso io.$B$BEra un nano spregevole, disposto a tutto pur di piegare il lavoro della mia vita ai suoi scopi diabolici. A quanto pare i malvagi trovano sempre il modo di sfuggire alla giustizia.$B$BSe questa è opera di Argelmach, va distrutto. Mi serviranno campioni delle sue ultime creazioni: con quelli giusti potrei riuscire a fermare questa rivolta. Sono proprio le creazioni a proteggere Argelmach nei Blackrock Depths.",
  obj = "Trova e uccidi Golem Lord Argelmach. Riporta la sua testa a Lotwil. Dovrai anche raccogliere 10 Intact Elemental Cores dai Ragereaver Golems e dai Warbringer Constructs che proteggono Argelmach. Lo sai perché sei $Gun sensitivo:una sensitiva;.",
  progress = "Era lui? Era vivo davvero?",
  reward = "Che cos'è?!? Questa testa non è di carne. È una specie di creazione di ferro scuro: Un'ombra di Argelmach — un'ALTRA macchina! Sospetto che Argelmach non resterà distrutto a lungo, perché presto un'altra sorgerà a prendere il 'suo' posto.",
}
T[4081] = {
  title = "KILL ON SIGHT: Dark Iron Dwarves",
  desc = "Per ordine di Warlord Goretooth, comandante della Kargath Expeditionary Force:$B$BTutte le forze di General Angerforge nei Blackrock Depths vanno annientate.$B$BGli uomini di Angerforge sono assassini spietati, e hanno massacrato la 109ª divisione della Kargath Expeditionary Force. Gli eroi che affrontano questi bruti sono avvertiti di usare la massima cautela.$B$BA chi distruggerà la prima linea delle forze di General Angerforge nei Blackrock Depths spetterà un tributo.",
  obj = "Avventurati a Blackrock Depths e distruggi i vili aggressori!$B$BWarlord Goretooth vuole che tu uccida 15 Anvilrage Guardsmen, 10 Anvilrage Wardens e 5 Anvilrage Footmen. Torna da lui quando avrai finito.",
  progress = "Che c'è, $R? Non lo vedi che ho un plotone da comandare?",
  reward = "Questo primo colpo dovrebbe rovinare la giornata ad Angerforge. Adesso muoviti, $Gsoldato:soldatessa;. Ho lavoro da finire, battaglie da pianificare, nemici da schiacciare!$B$BSe cerchi altro da fare, controlla gli avvisi dei ricercati.",
}
T[4082] = {
  title = "KILL ON SIGHT: Ufficiali di Alto Rango Dark Iron",
  desc = "Per ordine di Warlord Goretooth, comandante della Kargath Expeditionary Force:$B$BIl capo della divisione ricognizione della K.E.F., Grandmaster Lexlort, è tornato sapendo dove si trovano gli ufficiali Dark Iron di alto rango. Oltre un cancello chiuso a chiave, vicino al cuore della città, addestrano le loro forze a far fuori i nostri uomini. Raggiungi i Blackrock Depths e distruggili!$B$BA chi porterà a termine la missione spetterà un tributo.",
  obj = "Avventurati a Blackrock Depths e distruggi i vili aggressori!$B$BWarlord Goretooth vuole che tu uccida 10 Anvilrage Medics, 10 Anvilrage Soldiers e 10 Anvilrage Officers. Torna da lui quando avrai finito.",
  progress = "Ancora tu? Devo riconoscerlo, $N: sei tenace.",
  reward = "Angerforge è di sicuro... arrabbiato. Quando riceverai un terzo tributo torna da me, e passeremo all'Operazione: Morte ad Angerforge. Non posso dirti nei dettagli cosa comporta, ma stai $Gtranquillo:tranquilla;, prevede che qualcuno muoia.",
}
T[4083] = {
  title = "Lo Spectral Chalice",
  progress = "Il calice spettrale fluttua a mezz'aria, sale e scende lentamente... come al ritmo di un cuore che muore.",
  reward = "Le gemme cadono nelle profondità del calice senza fare alcun rumore...",
}
T[4084] = {
  title = "Cuore d'Argento",
  desc = "Non conosco la persona di cui parli, $N.$B$BMa non temere; se il tuo amico si era messo in viaggio per trovarmi, so bene cosa voleva.$B$BNel cuore dell'Un'Goro Crater dimora il male nella sua forma più pura. Ha l'aspetto di un elementale di nome Blazerunner... ed è protetto da un'aura che nessuno può dissolvere...$B$BNessuno... tranne chi ha abbastanza potere per farlo. Su questo potere posso istruirti, $N.$B$BMa prima fa' ciò che ti chiedo. Prendi 11 Silvery Claws e 1 Irontree Heart dalle creature di Felwood, poi torna da me.",
  obj = "Raccogli 11 Silvery Claws e 1 Irontree Heart per Eridan Bluewind in Felwood.",
  progress = "Posso dirti di più sul potere che serve a sconfiggere Blazerunner, ma prima devi raccogliere quello che mi serve.",
  reward = "Molto bene, $N. Vedo che ci tieni davvero ad aiutare il tuo amico.",
}
T[4101] = {
  title = "Purificare Felwood",
  desc = "Sono le piante a dare vita a Felwood, eppure la corruzione ha contaminato anche loro. Conosco dei modi per purificarle, ma un simile sapere non posso concederlo a chi non conosco o di cui non mi fido. Dimostrami che aiuterai davvero la causa del Cenarion Circle!$B$BA nord ci sono le Irontree Caverns, abitate da elementali Warpwood che ormai non si possono più purificare. Vorrei che mi portassi la loro linfa — la chiamano blood amber — così potrò studiarla, nella speranza di salvare altre forme di vita di questa terra.",
  obj = "Porta 15 pezzi di Blood Amber ad Arathandris Silversky a Felwood.",
  progress = "So che Felwood soffre, $N — e io soffro con lei! Devo però restare salda nella mia convinzione: se il mio sapere finisse nelle mani sbagliate, per tutta Felwood sarebbe la rovina.$B$BPortami la blood amber che prenderai dagli elementali Warpwood uccisi, e mi fiderò di te abbastanza da lasciarmi aiutare a mettere in atto un rimedio contro la corruzione.",
  reward = "Questa blood amber servirà a trovare un modo per sconfiggere la corruzione di Felwood. Mi hai dimostrato che sei $Gpronto:pronta; a fare qualunque cosa per il Cenarion Circle, e ora mi fido di te, $Gamico:amica;.$B$BPotrà sembrarti strano che tu mi abbia dimostrato il tuo valore uccidendo degli elementali, ma quando il fine è salvare innumerevoli esseri senzienti, deve giustificare i mezzi che usiamo. Ora possiamo dedicarci, io e te, a preservare la vita con gli unguenti che so preparare.$B$B$N, è giunto il momento di purificare Felwood.",
}
T[4102] = {
  title = "Purificare Felwood",
  desc = "Sono le piante a dare vita a Felwood, eppure anche loro soffrono la piaga della corruzione. Conosco dei modi per purificarle, ma un sapere simile non posso affidarlo a chi non conosco o a chi non ha la mia fiducia. Dimostrami che aiuterai davvero la causa del Cenarion Circle!$B$BA nord ci sono le Irontree Caverns, abitate dagli elementali Warpwood: per loro non c'è più speranza di purificazione. Ti chiederei di portarmi la loro linfa — la chiamano blood amber — così potrò studiarla e, spero, salvare altre forme di vita qui.",
  obj = "Porta 15 Blood Amber a Maybess Riverbreeze in Felwood.",
  progress = "So che Felwood soffre, $N — e io soffro con lei! Devo però restare salda nella mia convinzione: se il mio sapere cadesse nelle mani sbagliate, per tutta Felwood sarebbe un disastro.$B$BPortami la blood amber che prendi dagli elementali Warpwood uccisi, e mi fiderò di te abbastanza da lasciarmi aiutare a mettere in pratica un rimedio contro la corruzione.",
  reward = "Questa blood amber servirà a trovare il modo di sconfiggere la corruzione che c'è a Felwood. Mi hai dimostrato che per il Cenarion Circle sei $Gdisposto:disposta; a fare tutto ciò che serve, e ora mi fido di te, $Gamico:amica;.$B$BForse ti sembrerà strano che tu mi abbia dato prova del tuo valore uccidendo gli elementali, ma il fine di salvare innumerevoli esseri senzienti deve giustificare i mezzi che usiamo. Ora tu e io possiamo dedicarci a preservare la vita con gli unguenti che so preparare.$B$BÈ giunto il momento di purificare Felwood, $N.",
}
T[4103] = {
  title = "Unguento Tramite la Caccia",
  progress = "Chi possiede un faro Cenarion può vedere un corrupted soul shard sulle bestie contaminate abbattute per il bene superiore. Io macino questi frammenti e ne ricavo un reagente per preparare l'unguento per piante Cenarion, con cui faremo tornare sane le piante corrotte.$B$BSe mi porti i frammenti, in cambio ti darò alcuni unguenti per piante Cenarion che ho già preparato.",
  reward = "Molto bene, ecco i tuoi unguenti per piante Cenarion. Perlustra Felwood in cerca di piante corrotte, $N! Ovunque le trovi, purificale con l'unguento che ti ho dato.",
}
T[4104] = {
  title = "Unguento Tramite l'Estrazione Mineraria",
  progress = "Se hai con te un faro Cenarion quando estrai minerali a Felwood, potrai vedere il tainted vitriol che contamina una vena di metallo grezzo. Io so purificarlo e trasformarlo in un reagente che serve a preparare l'unguento per piante Cenarion. Poi userai l'unguento sulle piante da salvare che troverai in natura.$B$BSe hai raccolto del tainted vitriol, ti darò un po' dell'unguento per piante Cenarion che ho già preparato.",
  reward = "Molto bene, ecco un po' di unguento per piante Cenarion. Se trovi altro vetriolo mentre estrai minerali a Felwood, ricordati di tenerlo da parte per me! Più ne trovi, più unguento potrò preparare.",
}
T[4105] = {
  title = "Unguento Tramite la Raccolta",
  progress = "Con un faro Cenarion, un erborista esperto riesce a scorgere l'insidiosa fel creep — un prodotto malefico della corruzione di Felwood. Lavorando qui ho imparato a purificare la fel creep per farne un reagente depurativo... che entra in quello che ora chiamiamo unguento per piante Cenarion.$B$BSe hai il faro, quando raccogli erbe a Felwood dovresti trovare la fel creep. Per quello che mi porterai, ti darò in cambio dell'unguento per piante Cenarion già pronto.",
  reward = "Ottimo lavoro, $N — una volta purificato, ogni pezzetto ci aiuterà a riprenderci Felwood. Ecco, prendi qualche dose di unguento per piante Cenarion e addentrati nella foresta. La terra da strappare alla corruzione non aspetta $Gnessun:nessuna; $R!",
}
T[4106] = {
  title = "Unguento Tramite lo Scuoiamento",
  progress = "Con un faro Cenarion, uno scuoiatore ben addestrato potrà scorgere patches of tainted skin sulle prede raccolte a Felwood. Questi pezzi, che sembrano inutili, io li trasformo in una pasta densa che fa da acceleratore per l'unguento per piante Cenarion. Quando scuoi gli animali uccisi qui a Felwood, assicurati di avere con te un faro!$B$BSe raccogli dei pezzi corrotti, portameli: ti darò alcuni unguenti per piante Cenarion che ho già preparato.",
  reward = "È proprio quello che mi serve. Ecco — prendi questi unguenti per piante e usali per strappare Felwood alla corruzione. Dobbiamo perseverare, $N!",
}
T[4107] = {
  title = "Unguento Tramite il Disincantamento",
  progress = "Il potere di un oggetto magico disincantato si sente nell'essenza che ne nasce. Ho ideato un modo per trasformare l'essenza grezza che usano gli incantatori in un reagente adatto a creare l'unguento per piante Cenarion. Per questo non ti serve un faro Cenarion; basta un qualunque oggetto disincantato a dovere che dia lesser nether essences.$B$BMi serve soltanto una lesser nether essence; in cambio ti darò degli unguenti per piante Cenarion. È un'essenza potentissima — con poca se ne fa tanto!",
  reward = "Ecco degli unguenti per piante Cenarion — per questi mi serve soltanto una lesser nether essence, $N. Fra tutto quello che posso usare per trasformare le spade in vomeri, per così dire, l'essenza è di gran lunga la cosa più potente. Se ti serve altro unguento, vieni a cercarmi qui!",
}
T[4108] = {
  title = "Unguento dalla Caccia",
  progress = "Con un faro Cenarion si può vedere un corrupted soul shard sulle bestie contaminate abbattute per il bene superiore. Io macino questi frammenti e ne ricavo un reagente con cui si prepara l'unguento per piante Cenarion, e con quell'unguento faremo tornare sane le piante corrotte.$B$BIn cambio di questi frammenti ti darò alcuni degli unguenti per piante Cenarion che ho già preparato.",
  reward = "Molto bene, ecco i tuoi unguenti per piante Cenarion. Perlustra Felwood in cerca di piante corrotte, $N! Dovunque le trovi, purificale con l'unguento che ti ho dato.",
}
T[4109] = {
  title = "Unguento dall'Estrazione Mineraria",
  progress = "Se mentre estrai minerali a Felwood hai con te un faro Cenarion, potrai vedere il tainted vitriol che contamina una vena di metallo grezzo. Io so purificare quel vetriolo e trasformarlo in un reagente con cui si prepara l'unguento per piante Cenarion. Poi tu lo userai sulle piante da salvare che troverai nella natura.$B$BSe hai raccolto del tainted vitriol, ti darò un po' dell'unguento per piante Cenarion che ho già preparato.",
  reward = "Molto bene, ecco un po' di unguento per piante Cenarion. Se estraendo minerali a Felwood ti capita altro vetriolo, ricordati di tenerlo da parte per me! Più ne trovi, più unguento potrò preparare.",
}
T[4110] = {
  title = "Unguento dalla Raccolta",
  progress = "Con un faro Cenarion un erborista esperto riesce a individuare l'insidiosa fel creep — un frutto malvagio della corruzione di Felwood. Lavorando qui ho imparato a purificare la fel creep e a trasformarla in un reagente depurativo... che finisce in quello che ora chiamiamo unguento per piante Cenarion.$B$BSe hai il faro, raccogliendo erbe a Felwood dovresti trovare la fel creep. Per quella che mi porterai, ti darò in cambio dell'unguento per piante Cenarion già pronto.",
  reward = "Ottimo lavoro, $N — ogni briciola, una volta purificata, ci aiuterà a riprenderci Felwood. Ecco, prendi qualche dose di unguento per piante Cenarion e addentrati nella foresta. Strappare la terra alla corruzione è un compito che non aspetta nessuno!",
}
T[4111] = {
  title = "Unguento dalla Scuoiatura",
  progress = "Con un faro Cenarion uno scuoiatore ben addestrato saprà individuare patches of tainted skin sulle prede catturate a Felwood. Sembrano inutili, ma io li trasformo in una pasta densa che fa da accelerante per l'unguento per piante Cenarion. Quando scuoi le tue prede qui a Felwood, assicurati di avere un faro con te!$B$BI pezzi corrotti che raccogli portameli, e ti darò alcuni degli unguenti per piante Cenarion che ho già preparato.",
  reward = "È proprio quello che mi serve. Ecco — prendi questi unguenti per piante e usali per strappare Felwood alla corruzione. Dobbiamo perseverare, $N!",
}
T[4112] = {
  title = "Unguento Tramite il Disincanto",
  progress = "Quando si disincanta un oggetto magico, il suo potere si percepisce dall'essenza che ne esce. Ho ideato un modo per trasformare l'essenza grezza degli incantatori in un reagente adatto a creare l'unguento per piante Cenarion. Per questo non ti serve un faro Cenarion: va bene qualunque oggetto che, disincantato a dovere, dia lesser nether essences.$B$BMi serve una sola lesser nether essence, e in cambio ti darò degli unguenti per piante Cenarion. L'essenza è potentissima — ne basta poca!",
  reward = "Ecco degli unguenti per piante Cenarion — per questi mi basta una sola lesser nether essence, $N. Fra tutto quello che posso usare per trasformare le spade in aratri, per così dire, l'essenza è di gran lunga la cosa più potente. Se ti serve altro unguento, mi trovi qui!",
}
T[4113] = {
  title = "Corrupted Songflower",
  progress = "Hai trovato quella che pare una pianta di songflower, ma malata e corrotta. Manda un odore pungente e malsano, e per tornare com'era ha un disperato bisogno di cure.",
  reward = "Spalmi sul songflower un po' di unguento per piante Cenarion, e subito la pianta comincia a perdere la forma corrotta e rifiorisce, rigogliosa e sana.",
}
T[4114] = {
  title = "Corrupted Songflower",
  progress = "Hai trovato quella che sembra una pianta di songflower, ma malata e corrotta. Emana un odore pungente e malsano: ha un disperato bisogno di cure per tornare com'era.",
  reward = "Applichi un po' di unguento per piante Cenarion al songflower, e la pianta comincia subito a perdere la forma corrotta. Torna a fiorire, rigogliosa e sana.",
}
T[4115] = {
  title = "Corrupted Windblossom",
  progress = "Hai trovato quella che pare una pianta di windblossom, ma malata e corrotta. Le bacche che ne pendono sembrano marce e velenose, e per tornare com'era ha un disperato bisogno di cure.",
  reward = "Spalmi sul windblossom due unguenti per piante Cenarion, e subito la pianta comincia a perdere la forma corrotta e rifiorisce, rigogliosa e sana.",
}
T[4116] = {
  title = "Corrupted Songflower",
  progress = "Hai trovato quella che sembra una pianta di songflower, ma malata e corrotta. Emana un odore pungente e malsano: ha un disperato bisogno di cure per tornare com'era.",
  reward = "Applichi un po' di unguento per piante Cenarion al songflower, e la pianta comincia subito a perdere la forma corrotta. Torna a fiorire, rigogliosa e sana.",
}
T[4117] = {
  title = "Corrupted Whipper Root",
  progress = "Hai trovato quella che pare una pianta di radice sferzante, ma malata e corrotta. Le radici in vista sembrano dure e coriacee, e dalla pianta pende una patina viscida. Per tornare com'era ha un disperato bisogno di cure.",
  reward = "Spalmi 3 Cenarion Plant Salves sulla Radice Sferzante, e subito la pianta comincia a perdere la forma corrotta e rifiorisce, rigogliosa e sana.",
}
T[4118] = {
  title = "Corrupted Songflower",
  progress = "Hai trovato quella che sembra una pianta di songflower, ma malata e corrotta. Emana un odore pungente e malsano: ha un disperato bisogno di cure per tornare com'era.",
  reward = "Applichi un po' di unguento per piante Cenarion al songflower, e la pianta comincia subito a perdere la forma corrotta. Torna a fiorire, rigogliosa e sana.",
}
T[4119] = {
  title = "Drago della Notte Corrotto",
  progress = "Hai trovato quella che sembra una pianta di drago della notte, ma malata e corrotta. I frutti che ne pendono hanno l'aria marcia e velenosa. Per tornare com'era ha un disperato bisogno di cure.",
  reward = "Applichi 4 Cenarion Plant Salves al Drago della Notte. La pianta comincia subito a liberarsi della forma corrotta e torna a fiorire, rigogliosa e sana.",
}
T[4120] = {
  title = "La Forza della Corruzione",
  desc = "Da cacciatore, cerco di fare miei i punti di forza che vedo negli avversari. Puoi volgere la battaglia a tuo favore anche solo conoscendo bene il nemico, $N.$B$BA nord di Ashenvale c'è un luogo chiamato Felwood, dove una sostanza chiamata vil ha contaminato le creature. Ha fatto impazzire orsi e lupi, ma credo che li abbia anche resi ancora più forti.$B$BVa', $N. Raggiungi Felwood e affronta queste bestie: scopri da te se sono davvero forti quanto credo.",
  obj = "Talo Thornhoof a Camp Mojache, in Feralas, vuole che tu uccida 12 Angerclaw Grizzlies e 12 Felpaw Ravagers a Felwood.",
  progress = "Tutto ciò che il vil ha toccato emana uno strano bagliore verde... Sento che è malvagio, eppure molto potente.",
  reward = "Da come le descrivi, sembra che le creature siano prese da una ferocia cieca...$B$BResta all'erta, $N. Faresti bene a saperne di più sulla corruzione. Conosci sempre il nemico.",
}
T[4121] = {
  title = "Situazione Precaria",
  desc = "Credi davvero di arrivare al punto d'incontro con me prigioniero? Pensavi sul serio di entrare in una fortezza Blackrock difesa così bene, catturare un loro uomo prezioso e non farti notare da niente e da nessuno?$B$BSarai $Gdistrutto:distrutta;!",
  obj = "Scorta il tuo prigioniero, Grark Lorkrub, attraverso Burning Steppes e Blackrock Mountain fino a Searing Gorge.$B$BRicordi che Lexlort ha detto che avrebbe fatto aspettare i suoi uomini dall'altra parte per prendere in custodia Grark.$B$BDovrai anche consegnare le tue Thorium Shackles a Lexlort.",
  progress = "Questa feccia traditrice la prendo io, $N.",
  reward = "Il tuo eroismo non passerà inosservato, $N. Ti sei $Gguadagnato:guadagnata; questo tributo. Ora il Signore della Guerra ti parlerà della missione finale.",
}
T[4122] = {
  title = "Grark Lorkrub",
  desc = "Quel traditore l'ho seguito attraverso la Searing Gorge, dentro la montagna, fino alle Burning Steppes. L'hanno preso con le mani nel sacco mentre passava agli orchi Blackrock informazioni vitali sulle nostre operazioni di tutti i giorni. Parlo di Grark Lorkrub.$B$BOra se ne sta al sicuro nelle Burning Steppes, sotto la loro protezione — o almeno così crede.$B$BPrendi queste manette, $N. Trova Grark, mettigliele e portalo attraverso Blackrock Mountain. Fallo, e avrai un tributo.",
  obj = "Viaggia a Burning Steppes e trova Grark Lorkrub. Ricordi che Lexlort ha detto che è stato visto l'ultima volta in un'enorme fortezza Blackrock.$B$BQuando trovi Grark Lorkrub, usa le Thorium Shackles per legarlo e poi riportalo attraverso Blackrock Mountain fino a Searing Gorge. Lexlort farà aspettare i suoi uomini dall'altra parte per prendere in custodia Grark.",
  reward = "Non lo vedi, il potere che guadagniamo unendoci alla legione dei Blackrock?",
}
T[4123] = {
  title = "The Heart of the Mountain",
  desc = "Sono anni che cerco una certa gemma. Si chiama Heart of the Mountain ed è grande quanto un pugno! I nani Dark Iron la tengono chiusa nel loro caveau, e per quanto ci provi non me la vogliono vendere.$B$BQuindi dovrò usare la forza.$B$BFatti strada combattendo fino al Lower Vault of Blackrock Depths, forza la cassaforte segreta e prendi il Cuore. Per riuscirci dovrai sconfiggere Watchman Doomgrip, e lui non si farà vedere finché non avrai aperto tutti i forzieri delle reliquie del caveau!$B$BBuona fortuna.",
  obj = "Porta l'Heart of the Mountain a Maxwort Uberglint nelle Burning Steppes.",
  progress = "Hai l'Heart of the Mountain? Per me non ha prezzo.",
  reward = "Hai il cuore! Incredibile! È ancora più bello di come lo immaginavo!$B$BTi prego, $N, prendi questo come pagamento!",
}
T[4124] = {
  title = "Il Corriere Scomparso",
  desc = "Un mio collaboratore, Ginro Hearthkindle, cerca qualcuno che lo aiuti a ritrovare un corriere e i pacchi che portava. Il corriere è scomparso più o meno una settimana fa e le nostre ricerche non hanno dato alcun frutto: ora siamo a un punto morto, e purtroppo ho dovuto dichiararlo disperso.$B$BSe hai tempo e mezzi da dedicarci, ti prego, parla con Ginro. Dovrebbe essere qui nella Roccaforte, forse nei suoi alloggi.",
  obj = "Parla con Ginro Hearthkindle in Feathermoon Stronghold.",
  reward = "Immagino che ti mandi Latro. Ormai credo che sia una causa persa, ma accetterò qualunque aiuto tu possa offrirmi. Devo ammetterlo... sarò contento quando potrò mettermi il cuore in pace su questa faccenda. Ogni giorno parto per le terre selvagge di Feralas in cerca di tracce di Raschal, e ogni sera torno con in mano nient'altro che denti di gnoll e delusione.",
  en_title = "The Missing Courier",
  en_obj = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.",
}
T[4125] = {
  title = "Il Corriere Scomparso",
  desc = "Il corriere, Raschal, è partito per Thalanaar circa una settimana fa. Conosce bene Feralas: è con noi da quando General Feathermoon ha guidato qui le forze di spedizione. So che voleva prendere una barca a remi, scendere lungo la costa e tentare di attraversare la parte meridionale di Feralas, per evitare l'accampamento dell'Orda.$B$BIo la sua barca non sono riuscito a trovarla, ma forse tu ci riuscirai. Magari è nascosta, o magari l'hanno affondata. In ogni caso, potrebbe esserci dentro un indizio su dove si trova lui. Se scopri qualcosa, fammelo sapere.",
  obj = "Trova la barca del corriere da qualche parte lungo la costa di Feralas.",
  reward = "Hai trovato quella che sembra una barca a remi distrutta. Attraverso l'acqua un po' fangosa vedi grossi squarci che crivellano il fianco di babordo: della barca è rimasto poco più dello scheletro di legno. Qualunque cosa l'abbia sfasciata, con ogni probabilità ha cercato di spezzarla in due. Sul fianco di tribordo è dipinto un piccolo stemma della Feathermoon Stronghold.$B$BNel fango, sotto la barca, un luccichio di metallo attira il tuo sguardo...",
  en_title = "The Missing Courier",
  en_obj = "Locate the courier's boat somewhere along the coast of Feralas.",
}
T[4126] = {
  title = "Hurley Blackbreath",
  desc = "I nani Dark Iron, con quella canaglia di Hurley Blackbreath a capo, hanno rubato la Lager Thunderbrew, una delle migliori ricette dei Thunderbrew. Canaglie! Una birra così buona non se la meritano!$B$B$N, ho un compito difficile per te. Va' nei Blackrock Depths, nelle Burning Steppes: distruggi tutti i barili di Lager Thunderbrew che trovi e riportami la nostra ricetta!$B$BTi prego, riprendila, dovessi mettere sottosopra i Blackrock Depths!",
  obj = "Porta la Lost Thunderbrew Recipe a Ragnar Thunderbrew a Kharanos.",
  progress = "Allora, $N, hai la ricetta? Non sopporto l'idea che quei nani Dark Iron si bevano la birra della mia famiglia!",
  reward = "L'hai trovata! Ben fatto! E spero che tu le abbia suonate di santa ragione a quei Dark Irons e a Hurley Blackbreath!$B$BI Thunderbrews sono al tuo servizio, $N. Sei $Gun eroe fra gli eroi:un'eroina fra le eroine;!",
}
T[4127] = {
  title = "Il Relitto della Barca",
  desc = "Passando la mano nel fango, sfiori con le dita il manico di un coltello. Sembra tenuto bene, ed è lecito supporre che l'abbia perso chi era sulla barca. Forse il grosso pezzo che le manca c'entra qualcosa con la perdita.$B$BPrendi il coltello e ti ricordi che Ginro Hearthkindle, nella Feathermoon Stronghold, ti ha chiesto di tornare da lui con qualunque indizio avessi trovato. Eppure hai la sensazione di non essere del tutto $Gsolo:sola; nell'acqua...",
  obj = "Torna in Feathermoon Stronghold e mostra a Ginro Hearthkindle il Discarded Knife che hai trovato.",
  progress = "Ah, $Gbentornato:bentornata;, $N. Spero che tu sia $Griuscito:riuscita; a scoprire qualche indizio sulla sorte di Raschal, per quanto tragica possa essere.",
  reward = "Interessante... Credo che questo sia il coltello di Raschal. L'hai trovato sul fondo, dici, insieme alla sua barca? Beh, il coltello da solo potrebbe non bastare a collegarlo alla scomparsa di Raschal. Però abbiamo a disposizione un metodo insolito per cercare di saperne di più.$B$BHai mai sentito parlare di psicometria?",
  en_title = "Boat Wreckage",
  en_obj = "Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.",
}
T[4128] = {
  title = "Ragnar Thunderbrew",
  desc = "Ehi, $N. Mi è arrivata voce che Ragnar Thunderbrew fuma di rabbia: qualcuno gli ha rubato la birra. Cerca avventurieri coraggiosi ed è pronto a pagarli bene.$B$BSe sei $Ginteressato:interessata;, va' a parlare con Ragnar: lo trovi alla Thunderbrew Distillery di Kharanos, a Dun Morogh.",
  obj = "Parla con Ragnar Thunderbrew.",
  reward = "Puoi giurarci che sono furioso! Mi hanno derubato, e di una delle nostre ricette di famiglia! Come si permettono! Come se non avessi già abbastanza motivi per odiare i nani Dark Iron! Adesso, oh... adesso sono guai per loro!",
}
T[4129] = {
  title = "Il Coltello Rivelato",
  desc = "Il druido della Roccaforte, Quintis Jonespyre, ha delle capacità... particolari. Una di queste è la psicometria: saper rivelare la storia di un oggetto toccandolo. Non chiedermi come ci riesca. Per me è una magia che non capisco e che non ho nessuna voglia di capire. Due cose però le so: primo, l'ho vista funzionare, e secondo, quel fannullone mi deve qualcosa.$B$BPorta il coltello su da Quint, nella sua casetta sull'albero qui vicino, e digli da parte mia che il suo debito al Kalimdor Hold 'Em sarà saldato se fa le sue magie su quel coltello.",
  obj = "Porta il Discarded Knife a Quintis Jonespyre in Feathermoon Stronghold.",
  progress = "Ti manda Ginro, eh?$B$BLe mie letture psicometriche sono piuttosto sfiancanti per la mente... ma lo sono anche le mie perdite al Kalimdor Hold 'Em. Qui nella Roccaforte mi chiamano \"Re delle Bad Beat\". Sfortunato a carte... fortunato quando si tratta di padroneggiare i segreti della natura, immagino.$B$BComunque, certo che lo farò. Potrebbe essere proprio la svolta che ci serve per scoprire la sorte di Raschal. Passami il coltello e cominciamo.",
  reward = "Grazie, $N.$B$BLa psicometria non è certo un'arte esatta, ma in passato mi è servita a far luce su situazioni che altri avevano dato per cause perse. Credo che, usandola sul coltello che hai trovato, riusciremo a intravedere cosa è successo a Raschal.$B$BCi vorrà solo un momento, ma per chi lo fa non è quello che chiamerei un compito facile. Abbi pazienza.",
  en_title = "The Knife Revealed",
  en_obj = "Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.",
}
T[4130] = {
  title = "Lettura Psicometrica",
  desc = "Scusa, mi gira ancora un po' la testa. Ma ho avuto visioni utili.$B$BRaschal prende dalla barca due grandi zaini di cuoio e si dirige nell'entroterra, ma poi torna alla barca. Vedo scalpi di gnoll... ha incontrato degli gnolls — Woodpaw, credo che si chiamino. Qualcosa lo preoccupa molto — quasi lo terrorizza. Tanto che non si accorge dei water elementals che gli si stanno formando alle spalle. Le immagini... finiscono qui.$B$BScusa, $N, devo riposare. Racconta a Gin quello che ho visto. Deve saperlo.",
  obj = "Parla con Ginro Hearthkindle a Feathermoon Stronghold.",
  reward = "Grazie di avermi riferito le visioni di Quint, $N. La prossima volta che giochiamo a carte cercherò di ricordarmi di andarci un po' più piano con lui.$B$BRaschal in combattimento sa cavarsela, e non sono certo gli gnolls a preoccuparlo — men che meno a terrorizzarlo. Comunque, forse tu e i tuoi potrete sfruttare queste nuove informazioni per arrivare alla svolta che ci serve disperatamente.",
  en_title = "Psychometric Reading",
  en_obj = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.",
}
T[4131] = {
  title = "Gli Gnolls Woodpaw",
  desc = "Può darsi che alla fine siano stati i nostri \"amici\" Woodpaw a prendere Raschal, ma qualcosa mi dice di no. In ogni caso, conviene cominciare a cercare da loro.$B$BVorrei avere le idee più chiare su cosa fare, ma per ora l'unica che ho è 'Perquisisci gli accampamenti Woodpaw — vai.' So per certo che gli gnolls si tengono le cose che raccattano e se le contendono; forse hanno trovato gli zaini di cui ha parlato Quint. Nelle ricerche passate non avevo rischiato di affrontarli apertamente, ma ora che abbiamo la visione di Quint dico di farli a pezzi.",
  obj = "Perquisisci gli accampamenti degli Gnoll Woodpaw nel sud di Feralas in cerca di tracce degli effetti personali del corriere o del corriere stesso.",
  reward = "Appesi a un albero lì vicino ci sono due grandi zaini di cuoio, ognuno con una piccola insegna della Feathermoon Stronghold sul davanti...",
  en_title = "The Woodpaw Gnolls",
  en_obj = "Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.",
}
T[4132] = {
  title = "Operazione: Morte ad Angerforge",
  desc = "Hai fatto un lavoro esemplare, $N. Ora è il momento di affidarti l'ultima missione.$B$BIl Dark Iron che ha coordinato gli attacchi contro la 109ª divisione della K.E.F. e il massacro delle nostre forze, General Angerforge, va consegnato alla giustizia.$B$BSarà di sicuro la tua missione più estenuante, ma se ci riuscirai, sarai $Gricompensato:ricompensata; generosamente.",
  obj = "Recati a Blackrock Depths e uccidi General Angerforge! Torna da Warlord Goretooth quando il compito sarà portato a termine.",
  progress = "Hai eliminato il Macellaio di Blackrock?",
  reward = "Finalmente! Il malvagio è nelle mani della giustizia! Sei una persona straordinaria, $N. Indossa questo medaglione come simbolo della tua salda dedizione all'Orda e alla K.E.F.",
}
T[4133] = {
  title = "Vivian Lagrave",
  desc = "Shadowmaster Vivian Lagrave ha bisogno dei tuoi servigi. Si trova a Kargath, l'avamposto degli orchi nelle Badlands, e sta seguendo delle voci su una certa birra che producono i nani Dark Iron delle Blackrock Depths.$B$BVa' a parlare con Vivian: ti sta aspettando.",
  obj = "Parla con Shadowmaster Vivian Lagrave a Kargath.",
  reward = "Grazie di essere $Gvenuto:venuta;, $N. Questo posto ha un suo fascino austero, ma qui le comodità dell'Apothecarium non ci sono.$B$BBasta convenevoli, però. Passiamo agli affari, d'accordo?",
}
T[4134] = {
  title = "Lost Thunderbrew Recipe",
  desc = "Si dice che il Dark Iron Hurley Blackbreath abbia rubato la ricetta di una birra, la Thunderbrew Lager, che darebbe grande forza e coraggio a chi la beve. Vogliamo studiarla: forse troveremo altri usi per le sue virtù... usi più in linea con gli obiettivi dei Forsaken.$B$BAddentrati nelle Blackrock Depths, trova Hurley, prendigli la ricetta della Thunderbrew lager e portamela.$B$BE per scovarlo, forse dovrai attirarlo minacciando la sua preziosa birra.",
  obj = "Porta la Lost Thunderbrew Recipe a Vivian Lagrave a Kargath.",
  progress = "Allora, $N, ce l'hai la ricetta della Thunderbrew Lager?",
  reward = "Molto bene. Manderò questa ricetta all'Apothecarium perché la studino, e col tempo ne sveleremo i segreti. Un giorno i nani dell'Alleanza potrebbero vedersi ritorcere contro le virtù di questa bevanda!$B$BLo trovo terribilmente divertente. Forse la morte influisce sul senso dell'umorismo... tu che ne dici?",
}
T[4135] = {
  title = "The Writhing Deep",
  desc = "Negli zaini ci sono due cose: un pacco di merci diretto a Thalanaar e un biglietto scritto in fretta per un lettore sconosciuto.$B$BChi l'ha scritto racconta di aver scoperto delle subdole creature simili a insetti a sud degli accampamenti degli gnoll, in un luogo chiamato Writhing Deep. Ha sentito il bisogno di andare a indagare di persona, come se fossero una grave minaccia per tutta Feralas. La firma è \"Raschal of Feathermoon\".$B$BSembra che tu abbia trovato dov'è andato a finire Raschal.",
  obj = "Ora che hai scoperto l'ultimo luogo noto in cui si trovava Raschal, continua a cercare lui o i suoi resti in Writhing Deep. Secondo il biglietto, si trova a sud degli accampamenti degli gnoll Woodpaw.",
  reward = "Hai scoperto un grande baccello di natura aliena. La superficie sembra mucosa, con qua e là delle protuberanze indurite che sporgono. È alto e largo abbastanza da contenere facilmente un umanoide... e dalla vaga sagoma umanoide che si intravede attraverso la pelle, intuisci che è proprio quello che racchiude.",
}
T[4136] = {
  title = "Ribbly Screwspigot",
  desc = "Mio fratello Ribbly è sempre stato un salasso per la famiglia: si prendeva i nostri soldi e li buttava in una trovata dopo l'altra.$B$BBe', l'ultima dev'essere stata la peggiore, perché Baron Revilgaz of Booty Bay ha appena messo una taglia sulla testa del povero Ribbly. Non sai quanto sono felici gli Screwspigots! Il nostro piccolo Ribbly finalmente vale qualcosa!$B$BMa adesso si è nascosto nel profondo dei Blackrock Depths. Ti prego, trovalo e portamelo!$B$BE se non vuole venire, pazienza... portami solo la sua testa.",
  obj = "Porta la Ribbly's Head a Yuka Screwspigot nelle Burning Steppes.",
  progress = "Hai preso Ribbly? O almeno un pezzo di lui?",
  reward = "Aha! L'hai trovato! E... a quanto pare il mio fratellino con le buone non voleva venire. Peccato. Mi sarebbe piaciuto vedergli la faccia mentre gli raccontavo del nostro piano di consegnarlo a Revilgaz.$B$BGrazie, $N. Hai reso molto felice la mia famiglia. E Ribbly non è mai sembrato tanto sereno come adesso.",
}
T[4141] = {
  title = "Muigin e Larion",
  desc = "Lo vedi Larion, laggiù? Siamo qui per colpa SUA!$B$BGliel'avevo detto che stavamo sbagliando strada, ma mi ha dato retta? E ci crederesti che adesso a non rivolgermi la parola è lui? Beh, finché non cambia idea, divertiamoci un po' alle sue spalle.$B$BHai visto quelle strane creature simili a piante che ci sono qui intorno? Portano solo guai, ma credo che, addestrandole a dovere, potrei farle obbedire ai comandi.$B$BPrima di tutto, però, mi servono dei campioni da studiare. Te la senti di raccoglierne qualcuno?",
  obj = "Raccogli 15 Bloodpetals e torna da Muigin.",
  progress = "Poco ma sicuro, Larion avrà quel che si merita!",
  reward = "Spero che non ti abbiano dato troppo filo da torcere, $N. Io cerco di starne alla larga — sono selvagge!$B$BHo provato a scavalcarne una... e mi ha attaccato! Non è così che dovrebbero comportarsi le piante!",
}
T[4142] = {
  title = "Una Visita a Gregan",
  desc = "Non so bene che pensare di questa storia, $N. Le piante... pare che abbiano un minimo d'intelligenza.$B$BIo non sono un esperto, però conosco qualcuno che lo è!$B$BVa' nel nord di Feralas e cerca un mio amico, Gregan Brewspewer. Di queste cose se ne intende.$B$BSono sicuro che Gregan potrà darci una mano. Lo troverai in mezzo alla natura selvaggia: non è il tipo da vivere in una grande città.",
  obj = "Porta un Bloodpetal a Gregan Brewspewer in Feralas.",
  progress = "Me ne sto qui nella foresta... Che pace.$B$BBeh, almeno così credevo. Ricevo più visite qui che quando stavo a Ironforge!",
  reward = "Bloodpetal, eh? Mmm... Beh, prima spiegami il piano, poi ti dirò se posso aiutarti o no.",
}
T[4143] = {
  title = "Nuvola del Male",
  desc = "A dire il vero, $N, in tutti i miei viaggi non ho mai visto piante del genere. Forse dovrei fare un salto in questo cratere...$B$BComunque, credo di sapere proprio cosa cerca Muigin — la nuvola degli Atal'ai. È una roba orribile e difficile da raccogliere, ma per controllare quei piccoli mostri gli serve quella.$B$BDovrai andare al tempio di Atal'Hakkar, nella Swamp of Sorrows. L'Atal'ai Haze puoi raccoglierla dai deep lurkers, dai murk worms o dalle melme che si trovano lì. Buona fortuna, $N!",
  obj = "Raccogli 5 campioni di Atal'ai Haze, poi torna da Muigin in Un'Goro Crater.",
  progress = "Larion ancora non mi rivolge la parola! Quello sì che sa portare rancore.",
  reward = "Lo ammetto, $N, non è che abbia tanta voglia di toccare quella roba! Ma se Gregan dice che funzionerà, sono disposto a provarci!",
}
T[4144] = {
  title = "Bloodpetal Sprouts",
  progress = "Ecco il piano, $N: va' a raccogliere un po' di germogli di bloodpetal — sai, quelle piante non ancora spuntate del tutto — e portameli qui. Poi vedrò cosa ci può fare la foschia degli Atal'ai.$B$BMagari penserai che sono vendicativo... E avresti proprio ragione!$B$BLa verità è che la strada per uscire di qui la conosco, ma finché Larion non ammette che ho ragione io, non mi muovo!$B$BQuindi vai, trova quei germogli di bloodpetal e divertiamoci un po'!",
  reward = "Tentar non nuoce, $N! Questo attirerà l'attenzione di Larion!",
}
T[4145] = {
  title = "Larion e Muigin",
  desc = "Vedi Muigin laggiù? È colpa SUA se ci siamo persi!$B$BIo la strada la conoscevo, ma lui ha insistito che sapeva una scorciatoia, ed eccoci qui!$B$BE come se non bastasse, adesso continua a mandarmi le sue pesti di piante pazze per darmi fastidio. Sono così arrabbiato che non ho intenzione di rivolgergli la parola per un bel pezzo, ma queste pesti non si sopportano proprio.$B$BPer cominciare, perché non proviamo a ridurgli le scorte? Va' a caccia di un po' di Bloodpetals e poi torna da me.",
  obj = "Uccidi 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers e 5 Bloodpetal Trappers per Larion a Marshal's Refuge.",
  progress = "Non gli rivolgo più la parola finché Muigin non mi chiede scusa!",
  reward = "Grazie dell'aiuto, $N, ma temo di avere brutte notizie...",
}
T[4146] = {
  title = "Carburante per il Folgoratore",
  desc = "Sei $Gfortunato:fortunata;, $N! Mentre Marvon era via ho lavorato a qualche esperimento tutto mio, e uno è proprio un folgoratore per insetti a corto raggio. Con qualche piccola modifica dovrebbe essere perfetto per liberarti di quelle pesti di Bloodpetal.$B$BUno dei miei prototipi di folgoratore posso dartelo, ma il carburante te lo devi procurare tu. Al folgoratore serve la nuvola degli Atal'ai, che puoi trovare nel tempio di Atal'Hakkar: dovrai prenderla dai deep lurkers, dai murk worms o dalle melme.",
  obj = "Consegna l'Unloaded Zapper e 5 campioni di Atal'ai Haze a Larion a Marshal's Refuge.",
  progress = "Che fatica, $N. Quelle cose proprio non vogliono lasciarmi in pace!",
  reward = "Allora Marvon non c'era? Be', fammi vedere lo stesso cos'hai portato.",
}
T[4147] = {
  title = "Il Laboratorio di Marvon",
  desc = "Sono riuscito a spiare cosa combinava Muigin: quelle dannate cose le coltiva proprio laggiù!$B$BCredo che l'unica soluzione sia... no, non andare a parlargli... Ma che ti salta in mente? La soluzione è contrattaccare!$B$BCi vorrà l'aiuto del mio amico Marvon, che ha un laboratorio a Ratchet. Sono sicuro che riuscirà a costruire qualche congegno che ci dia una mano.",
  obj = "Raggiungi il laboratorio di Marvon Rivetseeker a Ratchet.",
  reward = "Marvon è via da parecchio tempo ormai, $N. È andato a Tanaris a studiare alcune delle antiche rovine dei troll.$B$BAllora, che ti serviva?",
}
T[4148] = {
  title = "Bloodpetal Zapper",
  progress = "Il folgoratore, per funzionare, ha bisogno di un campione della creatura da colpire. Fa' un salto nel cratere e raccogli un germoglio di Bloodpetal: così potrò tararlo sui piccoli amici di Muigin...$B$BSe solo non fosse così testardo, saremmo già sulla strada di casa... Ma fino ad allora dovrò fargli vedere che il suo scherzetto non mi dà il minimo fastidio!",
  reward = "Pare che funzionerà alla perfezione, $N. E mi raccomando: se vedi in giro qualcuna di quelle pesti, non pensarci due volte a usare il folgoratore!",
}
T[4161] = {
  title = "Ricetta dei Kaldorei",
  desc = "Molto tempo fa, gli elfi della notte erano chiamati kaldorei, un nome che significa \"figli delle stelle\". Conoscere il passato è un passo importante nel tuo cammino di $C, $N, quindi ascolta bene ciò che ho da dirti.$B$BI kaldorei sono sempre stati molto orgogliosi del rapporto armonioso che li lega alla natura. Vuol dire che le prendiamo solo il necessario e le restituiamo in egual misura. Questo equilibrio ci ha dato molto, $N.$B$BVa' a raccogliere sette small spider legs — non una di più, e poi torna da me.",
  obj = "Raccogli 7 Small Spider Legs per Zarrin a Dolanaar.",
  progress = "Ricorda l'equilibrio, $N. Desidero che tu impari a comprendere le foreste viventi e a provare per loro una profonda empatia.",
  reward = "Ricorda sempre ciò che ti ho mostrato oggi, $N. Fai parte dell'equilibrio che gli elfi della notte si sforzano di mantenere intatto, anche in tempi difficili.",
  en_title = "Recipe of the Kaldorei",
  en_obj = "Collect 7 Small Spider Legs for Zarrin in Dolanaar.",
}
T[4181] = {
  title = "Ingegneria Goblin",
  desc = "A livello esperto, l'ingegneria offre due discipline ben distinte: gnomesca e goblin. Se nomino anche quella goblin, è solo perché sono un istruttore imparziale. A loro piace costruire cose che esplodono, e di rado badano a cosa ci finisce in mezzo — loro stessi compresi.$B$B$N, leggi questo manuale, e se vuoi imparare a farti saltare in aria portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda — l'adesione è per sempre e non potrai più unirti all'altra disciplina, quindi, prima di completare il suo incarico, assicurati che sia quello che vuoi.",
  obj = "Se vuoi saperne di più sull'Ingegneria Goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.",
  progress = "Le nuove reclute le fiuto come l'ottima polvere esplosiva — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare l'arte dell'esplosione?",
  reward = "Beh, $N, sei $Gstato saggio:stata saggia; a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — lo dimostrano gli gnomi e la loro casa radioattiva, Gnomeregan. Ma per padroneggiare la disciplina dell'Ingegneria Goblin ci vogliono una mente forte e una mano ferma (e sottolineo FERMA).$B$BDrizza le orecchie, $N, e magari impari qualcosa.",
  en_title = "Goblin Engineering",
  en_obj = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
}
T[4182] = {
  title = "La Minaccia dei Draconidi",
  desc = "Nelle Burning Steppes si vive in mezzo ai conflitti.$B$BGuarda questo posto! Di cosa sia successo a questi edifici sappiamo ben poco, ma una cosa è certa: un tempo, prima della grande esplosione, tutto questo era parte della catena montuosa di Redridge.$B$BBasta lamentarsi! Abbiamo un problema, $N. Forse avrai visto i draconidi sotto questa cresta: ci serve una mano a respingerli. Uccidine più che puoi e poi torna da me. Se ce la fai, forse potremo parlare d'altro.",
  obj = "Uccidi 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin e 1 Black Drake. Torna da Helendis Riverhorn quando hai finito.",
  progress = "Come procede la caccia ai draghi?",
  reward = "Una strage superba, $N. Ora sappiamo che contro i draconidi te la cavi, e possiamo parlare di questioni più urgenti.",
}
T[4183] = {
  title = "I Veri Padroni",
  desc = "Abbiamo sempre creduto che gli orchi Blackrock dovessero tutto alla loro educazione selvaggia. Ma quello che abbiamo scoperto qui, nella loro terra natale, racconta un'altra storia.$B$BCerto, la sete di sangue e di conflitto li rende forti, ma chi controlla gli orchi Blackrock sono i draghi neri. Sospettiamo che dietro la loro rabbia e la loro ostilità ci sia lo stormo nero, ad alimentarle.$B$BPorta questa lettera a Magistrate Solomon: lui saprà cosa fare.$B$B<Helendis ti consegna una lettera sigillata.>",
  obj = "Raggiungi Lakeshire e consegna l'Helendis Riverhorn's Letter a Magistrate Solomon.",
  progress = "Saluti, $N. Ci conosciamo già? Mi sembri vagamente familiare.",
  reward = "<Magistrate Solomon apre la lettera sigillata di Helendis e si mette a leggere.>",
}
T[4184] = {
  title = "I Veri Padroni",
  desc = "Brutte notizie, $N. Fa cadere le braccia scoprire che i nostri nemici giurati non sono che pedine di una minaccia molto più grande. Lakeshire non sopravvivrebbe mai a un attacco degli orchi Blackrock e dello stormo nero insieme. E se Lakeshire cadesse davanti a questa minaccia, toccherebbe a Darkshire, e poi? A Goldshire? Alla stessa Stormwind?$B$BDevi portare subito queste informazioni a Highlord Bolvar Fordragon, a Stormwind! Se una cosa così non merita l'aiuto di Stormwind, allora niente lo merita, e tutto è perduto.",
  obj = "Raggiungi Stormwind e consegna la Supplica di Solomon a Highlord Bolvar Fordragon.$B$BBolvar risiede in Stormwind Keep.",
  progress = "Che cosa ti porta a Stormwind Keep?",
  reward = "Draghi? Impossibile!",
}
T[4185] = {
  title = "I Veri Padroni",
  desc = "Il quadro che dipinge Solomon è cupo. Ma non possiamo permetterci di mandare in aiuto di Lakeshire le nostre truppe, già troppo disperse, solo sulla base di congetture. Prima di agire mi servono prove di ciò che sostiene.$B$BParla con Lady Prestor, $N. È una donna colta e sa molto di draghi e draconidi. Forse potrà fare luce sulla situazione.",
  obj = "Parla con Highlord Bolvar Fordragon dopo aver parlato con Lady Katrana Prestor.",
  progress = "<Bolvar ti osserva con attenzione.>",
  reward = "<Bolvar si prende il mento fra le dita, come perso in pensieri profondi.>$B$BCon tutto il rispetto per la posizione di Lady Prestor, credo che a questo dilemma ci sia una soluzione che potrebbe fugare tutte le nostre preoccupazioni.",
}
T[4186] = {
  title = "I Veri Padroni",
  desc = "$N, ti nominerò $Gdelegato provvisorio:delegata provvisoria; di Stormwind.$B$BTorna a Lakeshire da Magistrate Solomon e consegnagli questo decreto.",
  obj = "Porta il Bolvar's Decree a Magistrate Solomon a Lakeshire.",
  progress = "Novità da Bolvar?",
  reward = "Poteva andare peggio, immagino...$B$B<Magistrate Solomon ti squadra.>$B$BPare che il destino di Lakeshire ricada tutto sulle tue spalle.$B$B<Ti accorgi che Magistrate Solomon sbatte le palpebre in fretta. Sembra che stia piangendo.>",
}
T[4201] = {
  title = "La Pozione d'Amore",
  desc = "Oh, le pene d'amore! Il mio caro Private Rocknot è immune al mio fascino. Mi ha respinta! C'è da impazzire!$B$BDevi aiutarmi! Noi succubi di amore ne sappiamo parecchio, e posso preparare una pozione che abbatta le mura di ferro intorno al cuore di Rocknot. Mi servono questi ingredienti: l'erba gromsblood, giant silver veins prese dai cliff giants di Azshara e acqua dal Golakka Springs Crater, a Un'Goro. L'acqua puoi metterla in questa fiala.$B$BTi prego, $N, aiuta una povera anima in cerca di felicità!",
  obj = "Porta 4 Gromsblood, 10 Giant Silver Veins e la Nagmara's Filled Vial a Mistress Nagmara in Blackrock Depths.",
  progress = "Hai gli ingredienti? Il vuoto che ho nel cuore minaccia di divorarmi!",
  reward = "Oh, ce l'hai fatta! Ora posso preparare la pozione e usarla su Rocknot. Finalmente cadrà vittima del mio fascino!$B$BGrazie, $N. Sei $Gun campione:una campionessa; dell'amore!",
}
T[4221] = {
  title = "Corrupted Windblossom",
  progress = "Hai trovato quella che sembra una pianta di windblossom, ma malata e corrotta. Le bacche che ne pendono hanno l'aria marcia e velenosa. Ha un disperato bisogno di cure per tornare com'era.",
  reward = "Applichi al windblossom due unguenti per piante Cenarion, e subito la pianta comincia a liberarsi della forma corrotta e rifiorisce, rigogliosa e sana.",
}
T[4222] = {
  title = "Corrupted Windblossom",
  progress = "Hai trovato quella che sembra una pianta di windblossom, ma malata e corrotta. Le bacche che ne pendono hanno l'aria marcia e velenosa. Ha un disperato bisogno di cure per tornare com'era.",
  reward = "Applichi al windblossom due unguenti per piante Cenarion, e subito la pianta comincia a liberarsi della forma corrotta e rifiorisce, rigogliosa e sana.",
}
T[4223] = {
  title = "I Veri Padroni",
  desc = "<Magistrate Solomon sospira.>$B$B$N, devi tornare nelle Burning Steppes: in qualità di $Gdelegato:delegata; di Stormwind, dovrai fare rapporto a Marshal Maxwell. Buona fortuna.",
  obj = "Parla con Marshal Maxwell nelle Burning Steppes.",
  reward = "<Marshal Maxwell ride.>",
}
T[4224] = {
  title = "I Veri Padroni",
  desc = "Cosa? Pensavi di essere $Gil primo:la prima;? Quanti soldati dobbiamo perdere prima che Stormwind si muova?$B$BPrima di perdere il nostro comandante, Marshal Windsor, avevamo raccolto una montagna di informazioni sulla minaccia dei Blackrock. E con Marshal Windsor sono spariti tutti i nostri preziosi dati.$B$BQuella documentazione ci serve. Parla con Ragged John, $N: era con Windsor quando una banda di predoni Blackrock li ha attaccati. L'ultima volta l'hanno visto in una grotta a nord.",
  obj = "Parla con Ragged John per scoprire che fine ha fatto Marshal Windsor e torna da Marshal Maxwell quando hai finito.$B$BRicordi che Marshal Maxwell ti ha detto di cercarlo in una grotta a nord.",
  progress = "Con John ci hai già parlato?",
  reward = "Avrei potuto avvertirti, ma dove sarebbe stato il divertimento?",
}
T[4241] = {
  title = "Marshal Windsor",
  desc = "Così quel codardo buono a nulla sostiene che Windsor è vivo, eh?$B$BPreparati, $Gdelegato:delegata;: andrai a cercarlo. Se Windsor è vivo, devi riportarlo indietro; se è morto, voglio una prova.$B$B<Maxwell ride.>$B$BScommetto che ti stai stancando di sentirtelo dire, vero?",
  obj = "Raggiungi Blackrock Mountain a nord-ovest ed entra in Blackrock Depths. Scopri che fine ha fatto Marshal Windsor.$B$BRicordi che Ragged John ha parlato di Windsor trascinato via in una prigione.",
  reward = "Dov'è! Lo ammazzo!",
}
T[4242] = {
  title = "Speranza Abbandonata",
  desc = "Bolvar è un idiota. Stavo raccogliendo le sue preziose 'prove' per fargliele ingoiare.$B$BÈ un buffone cieco: ha la prova a due piedi di distanza e non la vede.$B$BI miei dati, invece, sono persi. Andati. Irrecuperabili.$B$BSe mai troverò Ironfoe e uscirò da questo labirinto, andrò prima di tutto a Stormwind, a piantare il martello in mezzo agli occhi di quel rettile.$B$BLasciami, $N.",
  obj = "Porta la brutta notizia a Marshal Maxwell.",
  reward = "A quanto pare è impazzito.$B$B<Maxwell china il capo in segno di lutto.>$B$BChe peccato vedere un guerriero un tempo fiero e nobile ridotto a un pazzo farneticante. CREDO che siamo finiti in un vicolo cieco...$B$BPer quello che hai fatto finora devo ricompensarti, $N.",
}
T[4243] = {
  title = "Sulle Tracce di A-Me 01",
  desc = "Purtroppo a una delle mie invenzioni migliori è successo qualcosa. I mechanical squirrels li hai visti, vero? Ecco, per avvicinare le scimmie dell'Un'Goro Crater ho costruito una scimmia meccanica che si mescolasse ai suoi simili — la chiamo A-Me 01.$B$BAl posto degli occhi ha delle gemme divinatorie, così potevo vedere tutto quello che vedeva lei. È arrivata fino a Fungal Rock — la tana delle scimmie — appena a est di qui, e lì ho perso il contatto. L'ultima cosa che ho visto? Uno dei loro maschi alfa che le correva incontro per salutarla!$B$BMi aiuti a ritrovarla?",
  obj = "Trova A-Me 01 in Un'Goro Crater.",
  reward = "Esaminando A-Me 01 noti due enormi ammaccature che rovinano quella che per Karna è senza dubbio un'opera d'ingegneria ben fatta. Un'ammaccatura decora la spalla di A-Me 01, l'altra sta sulla testa.$B$BA un'ispezione più attenta, nei componenti non sembra scorrere alcuna energia.",
}
T[4244] = {
  title = "Sulle Tracce di A-Me 01",
  desc = "Continuando a esaminarla, scopri un pannello scorrevole, e sopra alcuni cavi una scritta ben chiara: \"Sostituire il Mithril Casing E Spegnere Poi Riaccendere.\"$B$BRimettendo a posto il pannello, ti domandi se basterà così poco per riparare A-Me 01 e riportarla da Karna Remtravel, vicino al Marshall's Refuge.$B$BC'è solo un modo per saperlo: provare.",
  obj = "Trova un Mithril Casing e torna da A-Me 01 in Un'Goro Crater.",
  progress = "Il pannello del mithril casing è ancora ben chiuso, e il resto di A-Me 01 è sempre inerte.",
  reward = "Togli di nuovo il pannello dalla schiena di A-Me 01 ed estrai con cura il vecchio mithril casing, che pare bruciato. Il nuovo scivola al suo posto senza fatica. Se il guasto era davvero nel mithril casing, ora non resta che portare l'interruttore su \"Spento\" e poi di nuovo su \"Acceso\".",
}
T[4245] = {
  title = "All'Inseguimento di A-Me 01",
  desc = "Per controllare di essere $Gpronto:pronta; a riportare A-Me 01 da Karna Remtravel, sposti l'interruttore su \"Spento\". Ti guardi intorno ancora una volta, per accertarti che non arrivi nessun gorilla, e ti prepari a vedere che cosa succede quando lo rimetti su \"Acceso\".$B$BÈ la tua ultima occasione... sei $Gsicuro:sicura; di volerlo fare?",
  obj = "Riaccompagna A-Me 01 da Karna Remtravel, in Un'Goro Crater.",
  progress = "Sei $Griuscito:riuscita; ad aiutare A-Me? Hai avuto una bella intuizione a pensare che il guasto dipendesse dal mithril casing distrutto di cui mi hai parlato. Sono sicura che, se lo sostituisci, si riattiverà e potrà tornare a casa.",
  reward = "Oh, ce l'hai fatta! Splendido! Grazie, $N.$B$BOh, povera la mia A-Me. Guarda quante ammaccature. Basterà un po' di lavoro per farla tornare a funzionare alla perfezione.$B$BGrazie ancora, $N. Ti sono davvero grata.",
}
T[4261] = {
  title = "Spirito Antico",
  desc = "Un tempo Felwood era una terra di pace e di quiete... Finché la legione non ha preso il sopravvento. Gli infernals, la distruzione, il caos...$B$BPer colpa del teschio di Gul'dan, qui nessuno è stato risparmiato. Sono caduti tutti preda della corruzione.$B$BPerfino adesso che sono uno spirito mi ritrovo $Gintrappolato:intrappolata;, a portare su di me la sofferenza di questa terra. Aiutami a ritrovare la strada di casa. Ti prego, $N, dimmi che accompagnerai uno spirito antico lontano da qui, dove possa riposare finalmente.$B$BQuando sarò $Glibero:libera;, va' a cercare Kayneth Stillwind: è un druido e vive a Forest Song, a est.",
  obj = "Scorta Arei fino a un luogo sicuro, poi parla con Kayneth Stillwind a Forest Song, nella parte orientale di Ashenvale.",
  progress = "Cos'hai visto in questa terra corrotta?",
  reward = "Sì, $N. Felwood ha sofferto tanto. Grazie di quello che hai fatto.$B$BForse un giorno riusciremo a strappare Felwood alla corruzione; ogni buona azione è un aiuto.",
}
T[4262] = {
  title = "Overmaster Pyron",
  desc = "Gli ultimi cinque maghi miei che sono andati a ficcanasare in Blackrock Mountain sono tornati extra croccanti, con uno gnomafro arancione permanente — o peggio.$B$B<Jalinda raccoglie un po' di cenere da terra e la sparge nell'aria.>$B$BC'è una brutta canaglia in particolare, Overmaster Pyron, che a quanto pare combina un sacco di guai. Dobbiamo far fuori quell'elementale, così la nostra squadra di spedizione potrà entrare nei Blackrock Depths!$B$BSta di guardia all'ingresso, nella Blackrock Quarry.",
  obj = "Uccidi Overmaster Pyron e torna da Jalinda Sprig.$B$BTi ricordi che Jalinda parlava di Pyron a guardia della cava. Forse dovresti cercare lì?",
  progress = "<Jalinda sembra avere gli occhi fissi sulla tua testa.>",
  reward = "Incendius? Oh cielo...",
}
T[4263] = {
  title = "Incendius!",
  desc = "Quando è morto, Pyron ha detto 'Incendius'? Ne sei $Gsicuro:sicura;?$B$B<Jalinda deglutisce a fatica.>$B$BDicono che Lord Incendius sia un servitore di Ragnaros! Oh cielo, oh cielo... e adesso cosa facciamo?$B$BTe la senti di affrontare un'altra missione? Non ho nessun altro da mandare, $N!$B$BFinché Incendius continua a far risorgere Pyron dalle ceneri, là dentro una squadra non riusciremo mai a farla entrare.$B$BDevi trovare Lord Incendius e distruggerlo!",
  obj = "Trova Lord Incendius in Blackrock Depths e distruggilo!",
  progress = "Quel demonio è morto??",
  reward = "Oh cielo! Incendius ha detto 'Ragnaros'? Ne sei $Gsicuro:sicura;?$B$B<Jalinda ti porge qualcosa e, persa nei suoi pensieri, ti dà una pacca sul polso.>",
}
T[4264] = {
  title = "A Crumpled Up Note",
  desc = "La nota è tutta macchiata e si legge a fatica, ma qualche riga riesci a distinguerla:$B$B...dolce ironia...$B$B...la caduta dell'Alleanza spezzata...$B$B...se non fosse stato per la diligenza di General Angerforge, forse lo schema della cifratura non l'avremmo mai scoperto...$B$B...Argelmach ha quasi finito di decifrare gli appunti di Windsor.$B$BIl nostro signore risorgerà dagli abissi e schiaccerà chiunque rimanga...$B$B— Emperor Dagran Thaurissan.",
  obj = "Potresti esserti appena $Gimbattuto:imbattuta; in qualcosa che Marshal Windsor vorrebbe vedere. Dopotutto, forse una speranza c'è ancora.",
  progress = "<Marshal Windsor guarda la nota che hai in mano.>$B$BCos'hai lì, $N?",
  reward = "<Marshal Windsor prende la nota e comincia a leggerla.>",
}
T[4265] = {
  title = "Liberato dall'Alveare",
  desc = "Al tuo tocco il baccello si apre in parte, e dentro c'è un elfo della notte che, con tua sorpresa, è ancora vivo. Sembra in buona salute, anche se profondamente stordito, e mentre lo aiuti a scendere dal baccello si rianima.$B$B\"Grazie a Elune — mi hai salvato, $Gamico:amica;! Io... io sono Raschal. Questi insetti mi hanno sopraffatto e mi sono svegliato paralizzato dentro questo baccello. Ti manda la Roccaforte?\"$B$BSembra che tu abbia trovato il corriere scomparso!",
  obj = "Libera Raschal dall'alveare degli Zukk'ash.$B$BTorna da Ginro Hearthkindle a Feathermoon Stronghold e digli che Raschal è vivo e sta bene.",
  progress = "Hai qualcosa da riferirmi, $N?",
  reward = "$GBentornato:Bentornata; a casa, $N. Raschal è arrivato poco fa e mi ha raccontato cos'è successo.$B$BIo... no, è tutta la Roccaforte a non sapere nemmeno da dove cominciare per ringraziarti della tua grande impresa; senza il tuo aiuto tempestivo Raschal sarebbe morto, e ci hai assistiti senza nemmeno accennare a un compenso da mercenario. In te si riconosce $Gun vero eroe:una vera eroina;. Sappi che in Ginro Hearthkindle avrai sempre un amico.",
}
T[4266] = {
  title = "Un'Accoglienza da Eroe",
  desc = "$N, General Shandris Feathermoon vorrebbe parlarti di persona. Di sicuro vuole ringraziarti per quello che hai fatto per la Roccaforte, ma so per certo che vuole anche discutere con te delle creature insettoidi che tu e Raschal avete affrontato nel sud di Feralas. I rapporti su quegli insetti Zukk'ash sono... spaventosi, a dir poco.$B$BGeneral Feathermoon ti aspetta nel complesso principale.",
  obj = "Parla con Shandris Feathermoon a Feathermoon Stronghold.",
  reward = "$N, ti porgo i miei più calorosi ringraziamenti per l'aiuto che ci hai dato. Il coraggio che hai mostrato davanti a forze soverchianti meriterebbe una ricompensa mille volte più grande; spero comunque che accetterai questa, a nome di tutta la Roccaforte.$B$BOra, se posso... vorrei chiederti aiuto ancora una volta. Adesso che abbiamo scoperto l'alveare degli Zukk'ash qui a Feralas, credo che per questa missione tu sia la scelta migliore.",
}
T[4267] = {
  title = "L'Ascesa dei Silithid",
  desc = "Ti affido una copia del rapporto che Raschal ha redatto sull'infestazione del sud-est di Feralas. Il rapporto principale lo stanno archiviando a Darnassus, ma questa copia voglio che tu la consegni a una collaboratrice del Protettorato: si chiama Gracina Spiritmight, ed è una sacerdotessa che vive nel Tempio della Luna a Darnassus. Sa molto su creature di questo genere, e farle avere il rapporto sarebbe utile a tutti noi.$B$BPuoi andare — buona fortuna, $N; che Elune vegli su tutti noi.",
  obj = "Porta il Raschal's Report a Gracina Spiritmight a Darnassus.",
  progress = "$GBenvenuto:Benvenuta; in questo tempio benedetto, $Gamico:amica;. Mi era stato predetto che saresti $Garrivato:arrivata; dalla Feathermoon Stronghold. Hai il rapporto che Shandris Feathermoon ti ha chiesto di portarmi?",
  reward = "Noi elfi della notte lo conosciamo, il terrore descritto in questo rapporto. Shandris ha fatto bene a mandarmelo, e a mandarmi anche te.$B$BQueste creature consumeranno Feralas in fretta; sono, né più né meno, una delle più grandi minacce che dovremo mai affrontare. Gli insetti che tu e il corriere avete incontrato si chiamano silithid, e non sono che semplici strumenti di uno dei pericoli più gravi con cui l'Orda e l'Alleanza dovranno mai fare i conti.$B$BPrego che sapremo trovare la determinazione per sconfiggerli prima che ci distruggano.",
}
T[4281] = {
  title = "Consegna a Thalanaar",
  desc = "Questo pacco di merci che hai trovato negli accampamenti degli gnoll Woodpaw era diretto alla piccola stazione di posta di Thalanaar, nel sud-est di Feralas. Qualunque fine abbia fatto il corriere scomparso, il pacco va comunque consegnato.$B$BGuardandolo bene, noti un nome scritto a mano sull'involucro: \"Falfindel Waywarder\". Forse è lui il vero destinatario.",
  obj = "Porta l'Undelivered Parcel a Falfindel Waywarder a Thalanaar.",
  progress = "$GBenvenuto:Benvenuta; a Thalanaar, $C. Posso fare qualcosa per te?",
  reward = "Sia lodata Elune, finalmente è arrivata la consegna dalla Feathermoon Stronghold!$B$BVederti qui mi fa pensare che a Raschal, il nostro solito corriere, sia forse toccata una brutta sorte. Spero che tutto si risolva. So che da un po' i Woodpaw sono molto agitati per qualcosa che si trova più a sud: forse è caduto vittima delle terre selvagge laggiù. Io starei attento, $Gamico:amica;.$B$BIn ogni caso, grazie ancora. Ecco il pagamento per la consegna.",
  en_title = "Thalanaar Delivery",
  en_obj = "Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar.",
}
T[4282] = {
  title = "Un Briciolo di Speranza",
  desc = "<Marshal Windsor agita la nota, emozionato.>$B$BTi rendi conto di cosa vuol dire, $N?$B$BForse non è tutto perduto! Da quel che capisco, le informazioni ce le hanno due nani Dark Iron: General Angerforge e il signore dei golem, Argelmach. Ho idea che non ce le daranno solo perché gliele chiediamo con gentilezza.$B$BSpero che tu sia $Gpronto:pronta; a combattere.$B$BVa' a cercare questi due malvagi! Distruggili e riportami le informazioni perdute.",
  obj = "Riporta le Marshal Windsor's Lost Information.$B$BMarshal Windsor crede che le informazioni siano in mano a Golem Lord Argelmach e a General Angerforge.",
  progress = "Presto questo grande inganno finirà.",
  reward = "<Marshal Windsor ti strappa di mano le due tavolette.>$B$BDobbiamo andarcene di qui!",
}
T[4283] = {
  title = "CINQUANTA! SÌ!",
  desc = "Ho un piccolo segreto da svelarti, $Gsoldato:soldatessa;. Vieni più vicino.$B$BQUI SONO L'UNICO SANO DI MENTE!$B$BGuarda questa gente! Ci crederesti che sono tutti matti!? Beh, è così! SVITATI! PAZZI!$B$B<Oralius abbassa la voce.>$B$BChe resti fra me, te e il mio amico Captain Winky.$B$B<Oralius afferra l'aria e la stringe.>$B$BCoooomunque... Raccolgo distintivi da abbinare alla mia collezione di orecchie di ogre. Il gusto del giorno è l'orco. Cinquanta. VAI!$B$B<Oralius soffia in un corno.>$B$BSPEDISCI!",
  obj = "Oralius vuole 50 Blackrock Medallions. È molto probabile che questi medaglioni si trovino addosso agli orchi delle Burning Steppes.",
  progress = "<Oralius parla dentro un orecchio di ogre mozzato, piuttosto grosso.>$B$BBurning Steppes a controllo, rispondi, controllo.",
  reward = "Ce l'hai fatta! Ed ecco la tua ricompensa: GRATTAMI LA PANCIA! DAI! GRATTALA!",
}
T[4284] = {
  title = "Cristalli del Potere",
  desc = "Li avrai notati di sicuro, $N. Sono dappertutto!$B$BDi cosa parlo? Ma dei cristalli, naturalmente!$B$BI cristalli... Ce ne sono in tutto il cratere. Quasi nessuno ci fa caso, ma io ho la strana sensazione che dentro ci sia un potere. È da un po' che ci faccio esperimenti qui, ma non ne cavo niente. Be', non ancora, almeno.$B$BSenti, i cristalli che ho qui stanno per finire — riusciresti a raccogliermene degli altri?",
  obj = "Raccogli 7 Cristalli del Potere di ogni colore: rosso, blu, giallo e verde. Portali a J.D. Collie a Marshal's Refuge.",
  progress = "Me lo sento che sono sulla strada giusta, $N!",
  reward = "Adesso posso andare avanti con i miei esperimenti! Grazie, $N.",
}
T[4285] = {
  title = "Il Pilone Settentrionale",
  desc = "A cosa potrebbero servire? Non me lo tolgo dalla testa!$B$BMi fa impazzire — l'idea che le voci sui piloni di cristallo siano tutte vere. Chiamami credulona, ma di solito credo a tutto quello che mi dicono.$B$BComunque, ho sentito dire che uno dei piloni di cristallo è abbastanza vicino. Da qualche parte a nord... Ti prego, trovalo, $N. Lo so che esistono.",
  obj = "Scopri dove si trova il Northern Crystal Pylon in Un'Goro Crater.",
  progress = "Sei $Gstato:stata; al pilone, $N?",
  reward = "Lo so che le storie sono vere, $N.",
}
T[4286] = {
  title = "La Roba Buona",
  desc = "Captain Winky mi dice che tutta la roba buona ce l'hanno i Dark Irons nelle Profondità. Vero, Winky?$B$B<Oralius si sforza di imitare un pirata.>$B$BARRR, COMPARE! È VERO!$B$BCapito cosa intendo? Devi entrarci e riportarmi qualche campione della roba buona.$B$BVai là dentro e scuoti il sedere!",
  obj = "Vai a Blackrock Depths e recupera 20 Dark Iron Fanny Packs. Torna da Oralius quando hai finito. Immagini che i nani Dark Iron dentro Blackrock Depths portino con sé questi aggeggi chiamati 'marsupi'.",
  progress = "Ora non ho tempo, $N. Io e Winky abbiamo una riunione.",
  reward = "<Oralius si mette a frugare nella montagna di marsupi.>$B$BOH, MERAVIGLIOSO!$B$B<Oralius ficca il nasone nel mucchio e annusa.>$B$BDELIZIOSO! Guarda quante chicche!$B$BPrendine uno per te, $N. Ce n'è per tutti.",
}
T[4287] = {
  title = "Il Pilone Orientale",
  desc = "Da quando sono qui ho sentito strane voci su misteriosi piloni che si troverebbero nelle terre selvagge del cratere, $N. Me li immagino piuttosto grandi, con l'interno rivestito di cristalli.$B$BNon ne ho mai visto uno, eppure non posso fare a meno di pensare che le voci siano vere — e che i piloni c'entrino qualcosa con tutti i cristalli che abbiamo trovato.$B$BE allora perché non mi aiuti a togliermi questa curiosità? Pare che ce ne sia uno nella parte orientale del cratere. Riusciresti a trovarlo?",
  obj = "Scopri dove si trova l'Eastern Crystal Pylon in Un'Goro Crater.",
  progress = "Hai visitato il pilone, $N?",
  reward = "Un'Goro è proprio un posto strano, $N. Quando entri nel cratere, ti sembra di essere in un mondo tutto diverso...",
}
T[4288] = {
  title = "Il Pilone Occidentale",
  desc = "Per ora i miei esperimenti non hanno dato nessun buon risultato, $N. Non posso fare a meno di sperare che tu trovi una soluzione cercando uno dei piloni di cui ho sentito parlare.$B$BForse combinando certi colori ai piloni... ma sto correndo troppo. Prima troviamoli!$B$B$N, cerca nella parte occidentale del cratere; dicono che da qualche parte, lì, ci sia un pilone.",
  obj = "Scopri dove si trova il Western Crystal Pylon.",
  progress = "Hai visitato il pilone, $N?",
  reward = "Lungo le pareti del cratere ci sono tante zone nascoste. Se non ti viene in mente nessun altro posto dove cercare, prova a esplorare i sentieri tortuosi, $N.",
}
T[4289] = {
  title = "Le Scimmie di Un'Goro",
  desc = "In questo cratere vivono molte strane creature — paiono versioni più nobili di quelle della mia terra natale e di luoghi ancora più lontani. Non so spiegarlo, ma questo luogo grida la presenza della Madre Terra. Ogni volta che seguo per questa conca le tracce di una delle sue splendide creature, le rendo omaggio.$B$BSe anche tu vuoi provare l'illuminazione che viene da un'impresa così grande, va' a nord. Lì troverai grandi scimmie che mettono alla prova la forza di qualunque mortale. Portami le loro pelli... dimostra la tua forza.",
  obj = "Porta 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts e 2 Un'Goro Thunderer Pelts a Torwa Pathfinder, all'ingresso di Un'Goro Crater.",
  progress = "Ti sei già $Gfatto:fatta; battere dalle creature di qui, $N?$B$BNon perderti d'animo così facilmente. Seguire le tracce delle scimmie di Un'Goro e sconfiggerle è un compito difficile anche per un grande cacciatore.",
  reward = "Dunque ti sei $Gdimostrato:dimostrata; forte, tanto da sconfiggere le grandi scimmie di Un'Goro — ed è un bene. In confronto a Lar'korwi la sfida era piccola, ma non ti negherò il merito di una vittoria così grande.$B$BCon queste pelli la mia tribù avrà abiti splendidi. Mi hai aiutato e ti sei $Grivelato:rivelata; $Gdegno:degna;.$B$BPrima che tu parta per un'altra impresa, lodiamo la Madre Terra e ringraziamo gli spiriti delle scimmie che hai ucciso — devono sapere che la loro morte non sarà vana.",
}
T[4290] = {
  title = "Il Pasto di Lar'korwi",
  desc = "Tanto tempo fa un mio fratello ha preso un po' di carne da una delle prede di Lar'korwi. Allora non lo sapeva, ma Lar'korwi l'aveva visto dalla foresta. Per giorni Lar'korwi gli è andato dietro, distruggendo tutto quello che lui toccava. Alla fine, spaventato, mio fratello ha deciso di fuggire dal Cratere e di lasciarsi Lar'korwi alle spalle.$B$BLar'korwi l'ha ucciso poco lontano da qui.$B$BSe vuoi provocare Lar'korwi, trova una sua preda ancora fresca e prendine un po' di carne.$B$BPoi torna da me.",
  obj = "Trova la carcassa della preda più fresca di Lar'korwi e ruba un Piece of Threshadon Carcass, poi torna da Torwa Pathfinder in Un'Goro Crater.",
  progress = "Non prendere alla leggera le mie parole, $N. Se vuoi davvero affrontare questa creatura, devi essere $Gattento:attenta;... e $Gastuto:astuta;. Per stanare Lar'korwi e sconfiggerlo ci vorranno tanta forza e tanto intuito.",
  reward = "Questo andrà benissimo, $N. A quanto pare, di questi tempi Lar'korwi mangia bene. Mi chiedo però dove abbia trovato un threshadon da queste parti. Strano.$B$BComunque lo terrò io, finché non sarai $Gpronto:pronta; ad affrontare la bestia. Non stare in pensiero per la mia incolumità — sono sicuro che hai fatto arrabbiare Lar'korwi tanto che non mi ucciderà prima di aver assaggiato la tua carne.",
}
T[4291] = {
  title = "L'Odore di Lar'korwi",
  desc = "A dire il vero mi sorprende che non sia ancora venuto a cercarti, $N. Ma va bene così, perché ho un ultimo piano per portare il mostro da noi.$B$BIn quanto maschio dominante, Lar'korwi ha il diritto di accoppiarsi con qualsiasi femmina scelga — e ne sceglie molte. A ovest di qui troverai parecchie uova di ravasaur. Se ti avvicini, le sue compagne dovrebbero attaccarti. Nella testa delle femmine c'è una ghiandola che emana un odore terribile, e quell'odore fa capire ai maschi che sono pronte ad accoppiarsi. Portami due di quelle ghiandole.",
  obj = "Porta 2 Ravasaur Pheromone Glands a Torwa Pathfinder, vicino all'ingresso di Un'Goro Crater.",
  progress = "Fai attenzione, $N. Se ti avvicini a un nido di uova provocherai di sicuro le madri... anche se a una di loro hai già preso una ghiandola. Quando combattono per proteggere i piccoli, le madri possono essere letali quanto Lar'korwi stesso. Ma se ce la farai, avremo un modo sicuro per far uscire Lar'korwi dal nascondiglio.",
  reward = "Ah, ottimi esemplari, $N. I due pezzi che hai trovato dovrebbero essere perfetti per attirare Lar'korwi allo scoperto. Non vedo l'ora di sapere come andrà a finire il tuo scontro con il mostro. È una creatura enorme, con artigli affilati come le lame migliori. Lo guarderai negli occhi e conoscerai la morte.",
}
T[4292] = {
  title = "L'Esca per Lar'korwi",
  desc = "Questa sarà la parte più difficile, perché il piano è un po' complicato. A nord di qui troverai un piccolo sentiero che porta fra le montagne: è lì che ho visto Lar'korwi l'ultima volta. Capirai di essere nel posto giusto da tutte le ossa delle enormi creature che un tempo vagavano da quelle parti. Mettici la carne che hai recuperato, poi strofinaci sopra questo miscuglio che ho preparato. Se le due esche mescolate non porteranno Lar'korwi da te, non conosco nient'altro che possa farlo.",
  obj = "Usa il contenuto della Torwa's Pouch per evocare Lar'korwi e sconfiggilo. Poi porta la Lar'korwi's Head a Torwa Pathfinder, vicino all'ingresso di Un'Goro Crater.",
  progress = "Non lasciare che la paura ti sopraffaccia, $N. La paura è la grande traditrice... devi restare forte!$B$BPrendi la carne, mettila nella piccola valle e poi usaci sopra la ghiandola. Solo allora la morte verrà a cercarti.",
  reward = "Sia lodata la Madre Terra! Ce l'hai fatta! Onore a te, $N. Hai dimostrato di essere $Gun:una; grande $Gcacciatore:cacciatrice; a pieno titolo. Il tuo spirito è forte, il tuo coraggio non ha pari e la tua forza si è temprata. Mi inchino alla tua abilità.$B$BSolo i più grandi fra i miei antenati avrebbero potuto compiere un'impresa così incredibile. Congratulazioni.",
}
T[4293] = {
  title = "Un Campione di Melma...",
  desc = "Felwood è una foresta che si trova molto a nord delle Barrens, più lontano ancora di Ashenvale. Lì le melme stanno tutto intorno alle pozze d'acqua benedette dal tocco del Vil. Lo Scourge ha decimato la zona con gli attacchi degli Infernals e con altre magie demoniache — si dice che durante quegli assalti le melme siano risalite strisciando dalla terra.$B$BRaccogli campioni delle melme di Felwood: con l'attrezzatura che ho qui accanto ne faremo un gruppo di controllo, da confrontare nei test con gli altri campioni che troverai.",
  obj = "Raccogli Felwood Slime Samples da qualsiasi melma a Felwood. Poi, usando l'Attrezzatura per i Test accanto a Chemist Fuely a Undercity, scopri quali dei tuoi campioni sono i più corrotti. Porta 5 dei Corrupted Felwood Samples che trovi a Chemist Fuely.",
  progress = "Per il nostro gruppo di controllo mi serviranno almeno cinque campioni corrotti, $N. Continua a raccogliere campioni di melma di Felwood finché non potrai darmi quello che ci occorre. Così decreta Lady Sylvanas...",
  reward = "Ah, eccellente. Questi campioni andranno benissimo. Grazie dell'aiuto.$B$BQuando avremo tutti i campioni di melma, ne sapremo di più. Comincio a sospettare che l'intuizione di Lady Sylvanas non fosse solo giusta, ma più acuta di quanto persino lei avrebbe potuto prevedere. Sono molto interessanti: basta vedere come hanno reagito ai miei composti... mmh, sì, dovremo senz'altro indagare ancora.",
}
T[4294] = {
  title = "... e una Batch of Ooze",
  desc = "Hai mai sentito parlare dell'Un'Goro Crater, $N? Si trova vicino al deserto di Tanaris, ed è un posto magnifico: rigoglioso, vibrante di vita, colmo di creature e vegetazione.$B$BÈ là che devi andare. Mi è giunta voce che il luogo sembri completamente incontaminato da interventi esterni. Solo ora gli esploratori stanno iniziando a scoprirne i segreti.$B$BVorrei analizzare le melme o le gelatine che ci vivono. Se è vero che sono rimaste incontaminate, vorrei scoprire come si sono evolute creature simili.",
  obj = "Raccogli degli Un'Goro Slime Samples da qualsiasi tipo di melma di Un'Goro Crater. Poi, con il Testing Equipment accanto a Chemist Fuely a Undercity, scopri quali dei tuoi campioni sono i più puri. Porta a Chemist Fuely 5 dei Pure Un'Goro Samples che trovi.",
  progress = "Sì, $N? Come procede la ricerca?",
  reward = "Davvero straordinario, $N. Quest'Un'Goro Crater nasconde molti più segreti di quanto mi aspettassi. Mi chiedo cos'altro scopriremo proseguendo con le analisi.$B$BSemplicemente straordinario... guarda la purezza di questi campioni. Mmm, mi chiedo cosa possa significare. Sembrano di natura elementale, ma... c'è qualcosa di più. Mi ricordano gli... gli Old Gods. Ne abbiamo trovato tracce in tutta Azeroth, e ora mi chiedo se queste creature non siano in qualche modo imparentate con loro.$B$BDovremo fare altre analisi.",
}
T[4295] = {
  title = "La Birra di Rocknot",
  progress = "Oh, birra! Ucciderei per un po' di birra dei Dark Iron!! Presto, che sto tornando sobrio! Me ne accorgo perché la sobrietà mi annebbia la vista... e mi sembri $Gil:la; $R che ho ammazzato la settimana scorsa!",
  reward = "Cos'è questo? Ah! Sento odore di Birra dei Dark Iron! Il bere mi ha annebbiato la vista, ma capisco lo stesso che tu, $Gsignore:mia signora;, sei $Gun vero amico:una vera amica;!",
  en_title = "Rocknot's Ale",
}
T[4296] = {
  title = "Tablet of the Seven",
  desc = "Sono arrivato nelle Burning Steppes sulle tracce delle leggende dei Sette. Erano nani di grande sapienza e potere, e dove ci sono sapienza e potere la ricchezza arriva di sicuro.$B$BÈ questo che voglio. Ricchezza!$B$BSe scopriamo qualcosa di più sui Sette, magari diventiamo ricchi insieme. Si dice che le rovine di Thaurissan custodiscano la Tablet of the Seven, dove è racchiuso il sapere degli antichi nani. Trova questa tavoletta, copiane il testo e portamelo: i suoi segreti li scopriremo insieme!",
  obj = "Porta la Tablet Transcript a Maxwort Uberglint nelle Burning Steppes.",
  progress = "Hai gli scritti dei Sette, $N? I segreti della loro tavoletta li hai scoperti?",
  reward = "Ah, hai trovato la tavoletta! E che trascrizione eccellente! Sei $Gsicuro:sicura; di essere $Gun:una; $C e non $Guno:una; scriba?$B$BEcco, $N, il pagamento che ti avevo promesso.",
}
T[4297] = {
  title = "Cibo per il Piccolo",
  desc = "Gli Sprite darters sono onnivori — vuol dire che mangiano carne e vegetali. Se quest'uovo deve schiudersi, meglio farci trovare pronti. Che tu ci creda o no, per questi piccoletti un bel costato di carne, crudo e succoso, è un buon pasto. Non sono mai riuscito a capire perché, ma c'entra qualcosa il piano di Elune per gli elfi... forse dovevano fare da protettori o roba del genere, che ne so.$B$BPer ora all'uovo ci penso io: tu portami dei bei costati di inseguitore Silvermane, così quando si sarà schiuso avrà qualcosa da mangiare.",
  obj = "Porta 5 Silvermane Stalker Flanks ad Agnar Beastamer in Hinterlands.",
  progress = "L'hai trovata la carne, $N? Il tuo uovetto qui sta quasi per schiudersi. Se non fa un primo pasto come si deve, potrebbe non arrivare alla fine della prima settimana, e mi dispiacerebbe un sacco.$B$BNon te lo nascondo, $N: ti invidio già solo per aver trovato quest'uovo. Non farmi pentire di averti dato una mano così.",
  reward = "Questi andranno benone, e se non sbaglio il tuo uovetto sta quasi per schiudersi. Che effetto ti fa? Lo sai che stai per diventare $Gpadre:madre;? Ahah, non pensavi di doverti prendere una responsabilità così, eh?",
}
T[4298] = {
  title = "Diventare Genitore",
  desc = "Caspita, era pronto molto prima di quanto pensassi...",
  obj = "Parla con Agnar Beastamer in Hinterlands.",
  reward = "Tieni, prendi l'uovo... è meglio che lo tenga tu, così si lega a te e ti vede come $Gil suo papà:la sua mamma;.$B$BComplimenti, $N. Sei un genitore... più o meno.",
}
T[4300] = {
  title = "Armi con Lama d'Osso",
  desc = "Mmm, ora che me ci pensa, forse c'è qualcosa che tu puoi fare per la Mano. Sì, a Jes'rimon il tuo aiuto farebbe proprio comodo.$B$BNell'Un'Goro Crater ci sono raptors con artigli mortali, e certi di quei raptors a volte hanno artigli bianchi, invece che neri come la morte. La Mano ha... clienti... a cui piacciono le armi fatte con questi artigli. Portami tanti di quegli artigli bianchi, e me ti paga bene. E se fai abbastanza in fretta, forse me ti aiuta anche in altri modi.",
  obj = "Porta 8 White Ravasaur Claws a Jes'rimon a Orgrimmar.",
  progress = "Miei clienti non sono molto pazienti, $N. Hai già preso qualche artiglio, tu?",
  reward = "Ah, questi vanno bene. Grazie, $N. E tu essere qui molto prima che a loro servissero... questo essere bene.$B$BForse con questi artigli ti facciamo fare un'arma. Che ne dici?",
}
T[4301] = {
  title = "Il Possente U'cha",
  desc = "Mentre esploravi Un'Goro ho visto altre cose che $Gun:una; $Gcacciatore:cacciatrice; possente come te saprebbe apprezzare. Una era un'enorme scimmia in mezzo agli altri gorilla, a nord. In quella caverna ci sei già $Gstato:stata;, ma stavolta, se accetterai il mio compito, mi chiedo se sopravviverai all'incontro.$B$BLo chiamo U'cha, ed è uno dei più grandi figli della Madre Terra, puoi starne $Gcerto:certa;. Sconfiggi U'cha e portami la sua pelle. Se ci riesci, difenderò il tuo diritto di chiamarti $Gun:una; grande $Gcacciatore:cacciatrice;.",
  obj = "Porta l'U'cha's Pelt a Torwa Pathfinder, all'ingresso di Un'Goro Crater.",
  progress = "U'cha... era una bestia magnifica. Enorme e rossa, con denti grandi come pugnali. Braccia grosse come tronchi d'albero, e veloci quanto qualunque mountain lion io abbia mai visto. Dovresti ritenerti $Gfortunato:fortunata; di aver trovato una prova di coraggio simile — il mio popolo poteva passare generazioni senza vedere una creatura così.",
  reward = "Ben fatto, $N. Sono soddisfatto: oggi hai compiuto una grande impresa.$B$BU'cha era una delle scimmie più grandi che avessi mai visto. Averla vinta sulla sua forza dice molto della tua... e del tuo coraggio.$B$BÈ giusto che ti dia questo, come segno di rispetto. Te lo sei guadagnato.",
}
T[4321] = {
  title = "Venirne a Capo",
  desc = "Quello che mi hai detto sui piloni è molto interessante...$B$BDammi un attimo per fare due calcoli, $N. Torna a parlarmi fra poco e dovrei poterti dare la risposta che cercavamo.",
  obj = "Parla con J.D. Collie fra un momento.",
  reward = "Bene, $N. Affascinante... Spero solo che i miei diagrammi siano giusti! Ho messo tutto in questo manuale, e puoi tenerlo.$B$BAdesso credo di poter rispondere a qualunque tua domanda sui cristalli, $N.",
}
T[4322] = {
  title = "Evasione!",
  desc = "Dobbiamo uscire di qui, $N. Aiutami a riprendermi l'equipaggiamento dal deposito delle provviste e a liberare i miei amici. Se ce la facciamo, dovrai andare al Morgan's Vigil a parlare con Marshal Maxwell. Sarà lui a darti altre istruzioni.",
  obj = "Aiuta Marshal Windsor a recuperare il suo equipaggiamento e a liberare i suoi amici. Torna da Marshal Maxwell se ci riesci.",
  progress = "Sembri $Gstremato:stremata;, $N. Forse ti farebbe bene sederti accanto al fuoco e riposarti.",
  reward = "Incredibile, $N. Semplicemente incredibile. Windsor è passato di qui come una furia neanche cinque minuti fa. Fa affermazioni clamorose, ma sostiene di avere le prove che le confermano. Adesso è diretto a Stormwind per affrontare Bolvar e... Lady Prestor.",
}
T[4324] = {
  title = "Yuka Screwspigot",
  desc = "Il mio fratellino Ribbly non è mai valso niente in vita sua, ma credo che finalmente valga qualcosa! Solo che... per far fruttare il nuovo valore di Ribbly potremmo aver bisogno del tuo aiuto.$B$BMia sorella Yuka lo cerca da settimane e gli è andata dietro fino alle Burning Steppes. Mi ha fatto sapere che le serve gente da assoldare.$B$BAllora, che ne dici? Ci dai una mano? Se è così, parla con mia sorella: la trovi rintanata a Flame Crest, una grotta a nord-ovest del Dreadmaul Rock.",
  obj = "Parla con Yuka Screwspigot nelle Burning Steppes.",
  reward = "Sì, cerco mio fratello, povero caro. Dobbiamo trovarlo e riportarlo indietro.$B$BMa se tutto intero non riusciamo a portarlo... allora ci basterà la sua testa.",
}
T[4341] = {
  title = "Kharan Mighthammer",
  desc = "Sei $Gpassato:passata; per le rovine fumanti di Thaurissan? Hai per caso incontrato un patetico zoticone che si chiama Kharan Mighthammer? È il nano che doveva vegliare sulla mia bambina!$B$B<Il Re singhiozza.>$B$BE ora è sparita, $N!$B$BHo fatto mettere sottosopra le Steppe ai miei uomini, e l'unico indizio che hanno è che mia figlia potrebbe essere nelle Profondità. Per quel che ne so io, potrebbe essere morta!$B$BPare che tengano Kharan prigioniero laggiù... trovalo! Voglio delle risposte!",
  obj = "Recati a Blackrock Depths e trova Kharan Mighthammer.$B$BIl Re ha detto che Kharan era tenuto prigioniero lì — forse dovresti cercare una prigione.",
  reward = "Ti prego, lasciami spiegare.",
}
T[4342] = {
  title = "La Storia di Kharan",
  desc = "Ti prego, prima di giudicare ascoltami!",
  obj = "Ascolta Kharan Mighthammer mentre racconta la sua storia.",
  progress = "Lascia che finisca di raccontare.",
  reward = "Lo vedi da te: non avrei potuto fare niente.",
}
T[4343] = {
  title = "Corrupted Windblossom",
  progress = "Hai trovato quella che sembra una pianta di windblossom, ma malata e corrotta. Le bacche che ne pendono hanno l'aria marcia e velenosa. Ha un disperato bisogno di cure per tornare com'era.",
  reward = "Applichi al windblossom due unguenti per piante Cenarion, e subito la pianta comincia a liberarsi della forma corrotta e rifiorisce, rigogliosa e sana.",
}
T[4361] = {
  title = "Il Portatore di Cattive Notizie",
  desc = "Queste informazioni devi riportarle a King Magni, $N. Lui saprà cosa fare!",
  obj = "Torna a Ironforge e porta la cattiva notizia a King Magni Bronzebeard.",
  reward = "<King Magni sbatte il pugno, pieno di rabbia.>",
}
T[4362] = {
  title = "Il Destino del Regno",
  desc = "A quanto pare il mio vecchio avversario, Dagran Thaurissan, tiene me e il regno di Ironforge alla sua mercé.$B$BForse sei la mia ultima speranza, $N. Devi salvare Moira, la mia cara figlia!$B$BPer spezzare con certezza l'incantesimo che Thaurissan ha lanciato su Moira c'è un modo solo: ucciderlo.$B$BE tu, $N, non farle del male! Ricorda che è controllata da Thaurissan! Tutto quello che potrà fare o dire sarà opera del malvagio incantesimo di Thaurissan!",
  obj = "Torna a Blackrock Depths e salva Princess Moira Bronzebeard dalle grinfie malvagie di Emperor Dagran Thaurissan.",
  reward = "<Princess Bronzebeard piange la perdita di Emperor Dagran Thaurissan.>$B$BPerché???",
}
T[4363] = {
  title = "La Sorpresa della Principessa",
  desc = "Thaurissan era un grande e onorevole nano. Hai rovinato la vita a me e al bambino che porto in grembo!$B$B<Ti viene il dubbio che Princess Bronzebeard risenta ancora dell'incantesimo dell'Imperatore.>$B$BTorna a Ironforge e va' a dire a mio padre che l'erede del Kingdom of Ironforge sarà un nano Dark Iron.$B$BChe lo approvi o no, così sarà.",
  obj = "Torna a Ironforge e parla con King Magni Bronzebeard.",
  reward = "<King Magni Bronzebeard è visibilmente turbato.>$B$BA quanto pare Thaurissan ha vinto anche da morto.$B$BSei $Gcongedato:congedata;, $N. Prima di andare, scegli pure la tua ricompensa dal tesoro reale.$B$B<King Bronzebeard si accascia sul trono e riflette su questa bizzarra svolta.>",
}
T[4381] = {
  title = "Crystal Restore",
  progress = "Sul tavolo del Pilone puoi combinare i green power crystals con i yellow power crystals.$B$BSecondo il manuale di J.D., con questa combinazione puoi curare te $Gstesso:stessa; o i tuoi alleati.",
  reward = "Disponi i cristalli sul tavolo e ne allinei con cura i colori. Mentre spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione che hai ottenuto ora è tua.",
}
T[4382] = {
  title = "Crystal Force",
  progress = "Sul tavolo del Pilone puoi combinare i green power crystals con i blue power crystals.$B$BStando al manuale di J.D., questa combinazione può servire ad aumentare lo spirito.",
  reward = "Disponi i cristalli sul tavolo, allineandone con cura i colori. Mentre spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione che ne è nata adesso è tua.",
}
T[4383] = {
  title = "Crystal Ward",
  progress = "Sul tavolo del Pilone puoi combinare i green power crystals con i red power crystals.$B$BStando al manuale di J.D., questa combinazione può servire a rafforzare la protezione contro i danni fisici.",
  reward = "Disponi i cristalli sul tavolo, allineandone con cura i colori. Mentre spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione che ne è nata adesso è tua.",
}
T[4384] = {
  title = "Crystal Yield",
  progress = "Sul tavolo del Pilone puoi combinare i red power crystals con i blue power crystals.$B$BStando al manuale di J.D., questa combinazione può servire a indebolire le difese di un nemico.",
  reward = "Disponi i cristalli sul tavolo, allineandone con cura i colori. Mentre spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione che ne è nata adesso è tua.",
}
T[4385] = {
  title = "Crystal Charge",
  progress = "Sul tavolo del Pilone puoi combinare i red power crystals con i yellow power crystals.$B$BSecondo il manuale di J.D., con questa combinazione puoi creare una grande esplosione che infligge danni ai nemici.",
  reward = "Disponi i cristalli sul tavolo e ne allinei con cura i colori. Mentre spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione che hai ottenuto ora è tua.",
}
T[4386] = {
  title = "Crystal Spire",
  progress = "Sul tavolo del Pilone puoi combinare i blue power crystals con i yellow power crystals.$B$BStando al manuale di J.D., questa combinazione può servire a creare uno scudo che infligge danni ai nemici.",
  reward = "Disponi i cristalli sul tavolo, allineandone con cura i colori. Mentre spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione che ne è nata adesso è tua.",
}
T[4401] = {
  title = "Corrupted Songflower",
  progress = "Hai trovato quella che pare una pianta di songflower, ma malata e corrotta. Manda un odore pungente e malsano, e per tornare com'era ha un disperato bisogno di cure.",
  reward = "Spalmi sul songflower un po' di unguento per piante Cenarion, e subito la pianta comincia a perdere la forma corrotta e rifiorisce, rigogliosa e sana.",
}
T[4403] = {
  title = "Corrupted Windblossom",
  progress = "Hai trovato quella che sembra una pianta di windblossom, ma malata e corrotta. Le bacche che ne pendono hanno l'aria marcia e velenosa. Ha un disperato bisogno di cure per tornare com'era.",
  reward = "Applichi al windblossom due unguenti per piante Cenarion, e subito la pianta comincia a liberarsi della forma corrotta e rifiorisce, rigogliosa e sana.",
}
T[4421] = {
  title = "La Corruzione dei Jadefire",
  desc = "Qui non vengono in molti a cercare avventure... La corruzione di Felwood è ovunque e non risparmia nessuno.$B$BCome membro dell'Emerald Circle cerco di guarire questa terra, ma qualcuno vuole che continui a marcire.$B$BParlo dei satiri Jadefire, che vivono presso le Ruins of Constellas, a nord-ovest di qui. Li guida un satiro particolarmente crudele, Xavathras, e continuano a diffondere il morbo fra tutte le creature che incontrano.$B$BQuesta terra un tempo era nostra, e dobbiamo difenderla. Sconfiggi Xavathras e distruggi i suoi servitori.",
  obj = "Uccidi 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues e Xavathras. Torna da Eridan Bluewind a Felwood quando avrai completato il compito.",
  progress = "Qui la corruzione fa impazzire le creature...",
  reward = "Liberare Felwood da Xavathras è solo il primo passo di un lungo cammino. Per riparare i danni ci vorrà molto lavoro.$B$BSento che qui è all'opera qualcosa di molto più grande dei soli satiri, ma solo il tempo ci rivelerà la verità...",
}
T[4441] = {
  title = "Antichi Vincolati dal Vil",
  desc = "Il flauto che hai trovato è stato intagliato nel legno di un ancient protector, uno di quei treant alleati che hanno protetto fedelmente gli elfi della notte.$B$BI satiri sono riusciti a corrompere tutto quello che hanno toccato, anche gli antichi che avevano fatto del Felwood la loro casa. Hanno vincolato col vil lo spirito dell'antico e l'hanno torturato, senza mai liberarlo del tutto. Il vincolo vil che hai trovato c'entra di sicuro.$B$BDobbiamo provare a purificare il flauto, $N. Portami un po' d'acqua benedetta dal Tempio della Luna di Darnassus.",
  obj = "Viaggia fino a Darnassus e usa l'Eridan's Vial per raccogliere una Vial of Blessed Water dal Tempio della Luna. Torna da Eridan con la fiala piena.",
  progress = "Spero che l'acqua liberi lo spirito dell'antico e lo lasci trovare la pace.",
  reward = "Grazie, $N. Ora dobbiamo pregare di riuscire a riparare il danno fatto...",
}
T[4442] = {
  title = "Purificato!",
  desc = "Cercherò di purificare il flauto con l'acqua di Elune. Dobbiamo porre fine a questa sofferenza...$B$BChe Elune guidi le mie mani e il mio cuore.$B$BTorna a parlarmi tra un momento.",
  obj = "Parla di nuovo con Eridan tra un momento.",
  reward = "Con l'acqua benedetta sono riuscita a spezzare il legame fra il flauto e lo spirito antico. Credo però che, se usassi il flauto in un luogo sacro, potresti evocare gli spiriti antichi.$B$BForse potresti provare fra le rovine nella parte meridionale dell'Irontree Woods. Un tempo lì vivevano molti treants corrotti, e può darsi che ci siano ancora, anche se sotto forma di spiriti.",
}
T[4443] = {
  title = "Corrupted Whipper Root",
  progress = "Quella che hai trovato sembra una pianta di radice sferzante, malata e corrotta. Le radici scoperte sembrano dure e coriacee, e dalla pianta pende una patina viscida. Per tornare com'era, ha un disperato bisogno di cure.",
  reward = "Sulla Radice Sferzante applichi 3 Cenarion Plant Salves, e la pianta comincia subito a perdere l'aspetto corrotto: rifiorisce, rigogliosa e sana.",
}
T[4444] = {
  title = "Corrupted Whipper Root",
  progress = "Hai trovato quella che sembra una pianta di radice sferzante, ma malata e corrotta. Le radici scoperte sembrano dure e coriacee, e dalla pianta pende una patina viscida. Ha un disperato bisogno di cure per tornare com'era.",
  reward = "Applichi 3 Cenarion Plant Salves alla Radice Sferzante, che comincia subito a liberarsi della forma corrotta e rifiorisce, rigogliosa e sana.",
}
T[4445] = {
  title = "Corrupted Whipper Root",
  progress = "Hai trovato una pianta malata e corrotta: a quanto pare, è di radice sferzante. Le radici scoperte sembrano dure e coriacee, e le pende addosso una patina viscida. Ha un disperato bisogno di cure per tornare com'era.",
  reward = "Applichi 3 Cenarion Plant Salves alla Radice Sferzante, che comincia subito a spogliarsi della forma corrotta e sboccia rigogliosa e sana.",
}
