T[4467] = {
  title = "Corrupted Windblossom",
  progress = "Hai trovato quella che sembra una pianta di windblossom, ma malata e corrotta. Le bacche che ne pendono sembrano marce e velenose. Per tornare com'era ha un disperato bisogno di cure.",
  reward = "Applichi al windblossom due balsami per piante Cenarion. Subito comincia a perdere la forma corrotta e sboccia in una pianta rigogliosa e sana.",
}
T[4481] = {
  title = "Libram of Constitution",
  progress = "In questo mondo ogni cosa ha un prezzo da pagare, e per l'oggetto che cerchi il prezzo è di trenta monete d'oro.$B$BLa maggior parte dei componenti che hai raccolto, naturalmente, la terrò per me. Ma non temere: il tuo ninnolo lo avrai.",
  reward = "È un disonore per la sua memoria... che sia $Gun:una; mortale come te a completare l'opera della sua vita.$B$BPrenditi l'amalgama e vattene!",
}
T[4482] = {
  title = "Libram of Tenacity",
  progress = "Trenta monete d'oro, $R. Trenta monete d'oro e i componenti necessari.",
  reward = "Per completare il compendio che ora hai in mano, a Kariel è servito il tempo di parecchie delle tue vite, $R. E tutto questo per cosa? Perché il suo discepolo se ne stesse nelle Burning Steppes a imbastardire le sue ricerche, per saziare una brama arcana che non ha mai fine... Maledetta questa ripugnante dipendenza.$B$BMi disgustano la tua avidità che non si sazia mai e la tua mancanza di compassione. Vattene!",
}
T[4483] = {
  title = "Libram of Resilience",
  progress = "Se la resilienza vuoi avere, trenta monete d'oro mi devi cedere.",
  reward = "In questo mondo sono andati perduti altri compendi, in luoghi dove non oseresti mettere piede. Luoghi che pregheresti non esistessero.$B$BLe energie di questi componenti le berrò io. A te resteranno gli scarti...",
}
T[4484] = {
  title = "Libram of Voracity",
  progress = "Non farmi perdere tempo, $R. Dammi quello che mi serve: trenta monete d'oro e i componenti.",
  reward = "La testa mi pulsa... Le energie delle vaste distese di cui è fatto il nostro universo... ARGGH!$B$BPrendi quello che vuoi e vattene!",
}
T[4485] = {
  title = "Il Tome of Nobility",
  desc = "Salve, $N. Vedo che la tua dedizione non vacilla, e nemmeno la tua fede.$B$BCredo sia ora che tu parli con Duthorian Rall, a Stormwind: ti resta qualche lezione da imparare, e sento che sei $Gpronto:pronta;.$B$BCercalo nella Cathedral of Light e, $N, prendi sul serio queste lezioni. Sei $Garrivato:arrivata; dove sei con l'umiltà e il duro lavoro: non deluderci diventando arrogante.$B$BStammi bene.",
  obj = "Parla con Duthorian Rall a Stormwind.",
  reward = "Ah, $N, sei $Gtornato:tornata; alla Cattedrale. Bene. Ultimamente sono successe molte cose, e se ti dimostrerai $Gdegno:degna; vorrei il tuo aiuto.$B$BIn giro ci sono molti nemici infidi, e per fermarli mi servirà una mano.",
}
T[4486] = {
  title = "Il Tome of Nobility",
  desc = "Bene, bene, bene, ma guarda $Gil possente paladino:la possente paladina; in tutta la sua regalità.$B$BScusa, $N, non volevo offenderti... è che certe volte, davanti alle imprese che hai compiuto, divento un po' invidioso. Tiza dice che è il mio punto debole, e le ho giurato che avrei provato a correggermi. Solo che a volte è dura, sai?$B$BMa volevo parlarti perché Duthorian Rall a Stormwind ti ha mandato a dire di raggiungerlo nella Cathedral of Light quando sei $Gpronto:pronta;. Pareva una cosa importante, come se stesse succedendo qualcosa.",
  obj = "Parla con Duthorian Rall a Stormwind.",
  reward = "Ah, $N, sei $Gtornato:tornata; alla Cattedrale. Bene. Ultimamente sono successe molte cose, e vorrei il tuo aiuto, se ti dimostrerai $Gdegno:degna;.$B$BIn giro ci sono tanti nemici infidi, e avrò bisogno di te per fermarli.",
}
T[4487] = {
  title = "Evoca Felsteed",
  desc = "Ah, bene, eccoti qui. Ti avevo mandato dietro $Guna succube:un infernal; per attirare la tua attenzione, ma a quanto pare sei $Griuscito:riuscita; ad arrivare prima che ti trovasse. Poco male.$B$BUltimamente si parla del tuo potere che cresce — buon per te, forse un guaio per altri. Ma sono dettagli. Quello che conta è che secondo me hai dimostrato quanto vali, e quindi ti meriti... eheh... una specie di benedizione.$B$BSopra Ratchet, nelle Barrens, troverai un uomo di nome Strahad. Credo che le vostre strade si siano già incrociate.",
  obj = "Parla con Strahad Farsan a Ratchet.",
  reward = "Così hai deciso di onorarmi di nuovo della tua presenza. Che gentile da parte tua.$B$BI miei accoliti si domandavano se ti saresti mai $Gfatto vivo:fatta viva;. Gli ho risposto che non c'era alcun dubbio. Quando c'è di mezzo il potere, ne sei $Gattratto:attratta; come una falena dalla fiamma.",
}
T[4488] = {
  title = "Evoca Felsteed",
  desc = "Ah, $N, ti sei $Gdegnato:degnata; di onorarci della tua presenza. Che meraviglia!$B$BSpero che tu non pretenda anche di essere $Gservito e riverito:servita e riverita;. Il tuo potere crescerà pure in fretta, ma quanto a conoscenza e comprensione vere sei ancora $Gun novellino:una novellina;. Se non stai $Gattento:attenta;, la corruzione avrà la meglio su di te e sulla tua debole volontà.$B$BMa veniamo al punto: Strahad vuole parlarti. Risiede ancora nella sua torre, quella che domina Ratchet, nelle Barrens. Ti consiglio di sbrigarti.",
  obj = "Parla con Strahad Farsan a Ratchet.",
  reward = "Così hai deciso di onorarmi di nuovo della tua presenza. Che gentile da parte tua.$B$BI miei accoliti si domandavano se ti saresti mai $Gfatto vivo:fatta viva;. Gli ho risposto che non c'era alcun dubbio. Quando c'è di mezzo il potere, ne sei $Gattratto:attratta; come una falena dalla fiamma.",
}
T[4489] = {
  title = "Evoca Felsteed",
  desc = "Tu, $R! Vieni qui!$B$BSei tu $Gquello:quella; che chiamano $N, giusto?$B$BCome pensavo. Sarò breve: il tuo potere cresce, e non è passato inosservato. Ora è arrivato il momento che tu venga $Gricompensato:ricompensata; per i tuoi sforzi.$B$BVa' nelle Barrens. Lì, sopra Ratchet, troverai Strahad Farsan — te lo ricordi, forse? Vuole scambiare due parole con te. Io non perderei tempo.",
  obj = "Parla con Strahad Farsan a Ratchet.",
  reward = "Così hai deciso di onorarmi di nuovo della tua presenza. Che gentile da parte tua.$B$BI miei accoliti si domandavano se ti saresti mai $Gfatto vivo:fatta viva;. Gli ho risposto che non c'era alcun dubbio. Quando c'è di mezzo il potere, ne sei $Gattratto:attratta; come una falena dalla fiamma.",
}
T[4490] = {
  title = "Evoca Felsteed",
  desc = "Vorrei premiarti per la pazienza e il duro lavoro. Ma sappi una cosa: in futuro evocare un Felsteed sarà molto più difficile. Dovrai guadagnartelo... e non sarà semplice.$B$BPer ora va', e usa come meglio credi il potere di evocare una creatura simile.",
  obj = "Parla con Strahad Farsan a Ratchet per apprendere l'abilità di evocare un Felsteed.",
  reward = "Buona fortuna, $N. Non vedo l'ora di rivederti.",
}
T[4491] = {
  title = "Un Piccolo Aiuto dai Miei Amici",
  desc = "Uff... Che caldo...$B$BStavo esplorando la zona quando, all'improvviso, il caldo è diventato insopportabile. Mi sarà venuto un colpo di calore.$B$BTi prego, aiutami a tornare dalla mia amica Spraggle, a Marshal's Refuge. Credo di stare abbastanza bene per seguirti fin lì.$B$BMi sento un po' stordito: se dovessi svenire di nuovo, spruzzami addosso un po' d'acqua con la borraccia di Spraggle. Dovrebbe funzionare, spero...",
  obj = "Accompagna Ringo da Spraggle Frock a Marshal's Refuge.$B$BSe Ringo sviene, usa la Spraggle's Canteen per rianimarlo.",
  progress = "Ero così in pensiero per Ringo...",
  reward = "Ringo non è in gran forma, $N, ma sono felice di riaverlo qui tutto intero!$B$BGrazie di averlo trovato.",
}
T[4492] = {
  title = "Disperso!",
  desc = "Devi aiutarmi, $N! Il mio amico Ringo è partito per esplorare il vulcano qui a sud, e manca da troppo tempo. Sono davvero in pensiero per lui.$B$BPensi di riuscire a trovarlo? Perché non ti porti dietro la mia borraccia — se trovi Ringo, di sicuro ne avrà bisogno!",
  obj = "Trova Ringo a Fire Plume Ridge.",
  progress = "Co... Cosa?",
  reward = "Oh... sono proprio contento che qualcuno mi abbia trovato...",
}
T[4493] = {
  title = "La Marcia dei Silithid",
  desc = "Sembrerebbe che l'intento dei silithid, anzi — la loro stessa ragione d'essere, sia divorare tutto ciò che incontrano sul cammino e che non appartiene al loro ecosistema. Perseguono un unico scopo, ed è per questo che rappresentano una grave minaccia per ogni forma di vita su Azeroth.$B$BCiò che abbiamo visto finora non è che l'inizio. Sospetto che la loro forza provenga dalle profondità di Kalimdor: l'Un'Goro Crater. Recati a Gadgetzan, nel deserto di Tanaris, e parla con Alchemist Pestlezugg. Esponigli la mia teoria; di certo ci aiuterà a combattere i silithid.",
  obj = "Parla con Alchemist Pestlezugg a Gadgetzan.",
  reward = "Sì, avevo intuito che ti mandava Gracina. La tua esperienza nella lotta contro queste bestiacce non ha prezzo; per quanto ne so, nessuno ha mai avuto a che fare con esseri del genere prima d'ora. Quanto all'idea di Gracina che l'Un'Goro Crater sia il loro cuore... forse ha ragione. Un'Goro è una giungla misteriosa e pericolosa a ovest di qui. Magari, andando lì, faremo anche un passo avanti per capire cosa siano davvero i silithid.",
}
T[4494] = {
  title = "La Marcia dei Silithid",
  desc = "Sembrerebbe che l'intento dei silithid, anzi — la loro stessa ragione d'essere, sia divorare tutto ciò che incontrano sul cammino e che non appartiene al loro ecosistema. Perseguono un unico scopo, ed è per questo che rappresentano una grave minaccia per ogni forma di vita su Azeroth.$B$BCiò che abbiamo visto finora non è che l'inizio. Sospetto che la loro forza provenga dalle profondità di Kalimdor: l'Un'Goro Crater. Recati a Gadgetzan, nel deserto di Tanaris, e parla con Alchemist Pestlezugg. Esponigli la mia teoria; di certo ci aiuterà a combattere i silithid.",
  obj = "Parla con Alchemist Pestlezugg a Gadgetzan.",
  reward = "Sì, avevo intuito che ti mandava Zilzibin. La tua esperienza nella lotta contro queste bestiacce non ha prezzo; per quanto ne so, nessuno ha mai avuto a che fare con esseri del genere prima d'ora. Quanto all'idea di Zil che l'Un'Goro Crater sia il loro cuore... forse ha ragione. Un'Goro è una giungla misteriosa e pericolosa a ovest di qui. Magari, andando lì, faremo anche un passo avanti per capire cosa siano davvero i silithid.",
}
T[4496] = {
  title = "Pasticci nella Giungla",
  desc = "Le mie ricerche hanno rivelato che i silithid sono come le api; elimina la regina e il resto dell'alveare dovrebbe precipitare nel caos. Preparerò un richiamo per attirarla fuori; una volta evocata, toccherà a te abbatterla.$B$BPrima, però, ci servono dei reagenti; non vogliamo che ti cacci nei pasticci nella giungla $Gimpreparato:impreparata;. Va' a ovest, trova l'alveare dei silithid nell'Un'Goro Crater e prendi una ghiandola odorifera da uno degli insetti. Mi serviranno anche dei campioni di terreno prelevati a Un'Goro.",
  obj = "Porta una Gorishi Scent Gland e 5 campioni di Un'Goro Soil ad Alchemist Pestlezugg, a Gadgetzan.",
  progress = "Trovare una ghiandola odorifera adatta potrebbe richiedere un po' di tempo — non deve essere danneggiata, e il modo in cui bisogna procurarsela non aiuta di certo. Quanto al terreno, non credo che sarà difficile trovarlo.$B$BComunque, hai quello che mi serve per preparare il richiamo?",
  reward = "Ah sì, la ghiandola odorifera. La membrana sembra intatta — eccellente. Il terreno, sì, dovrebbe andare benissimo. Con le mie aggiunte speciali dovrei riuscire a macinare tutto quanto e ottenere il richiamo perfetto.$B$BDammi un momento per prepararlo, $N. Quando sarà pronto, potremo passare alla fase successiva, e speriamo che basti a fermare i silithid prima che invadano Gadgetzan... e il resto di Kalimdor.",
}
T[4501] = {
  title = "Beware of Pterrordax",
  desc = "Cercasi combattente esperto che si occupi della minaccia dei Pterrordax dell'Un'Goro Crater. Sono sempre di più e stanno diventando un pericolo per chi viaggia nella zona.$B$BRiduci il loro numero uccidendo 10 pterrordax e 15 esemplari di frenzied pterrordax.$B$BA lavoro finito, parla con Spraggle Frock e riceverai una ricompensa.",
  obj = "Uccidi 10 Pterrordax e 15 Frenzied Pterrordax, poi parla con Spraggle Frock a Marshal's Refuge.",
  progress = "A dir la verità, quelle strane creature non mi preoccupavano più di tanto... Finché un giorno non ho visto quella scritta sul fianco di una grossa pietra.$B$BATTENZIONE AI PTERRORDAX$B$BChi può averla scritta? Non lo so, ma è troppo inquietante per far finta di niente!",
  reward = "Gli pterrordax di qui mi terrorizzano davvero! Grazie per averne ridotto il numero, $N: forse adesso mi sentirò abbastanza al sicuro da avventurarmi fuori da Marshal's Refuge.",
}
T[4502] = {
  title = "Attività Vulcanica",
  desc = "Facendo l'apprendista di Marvon Rivetseeker ho imparato tantissimo. Ma ormai è via da così tanto tempo che penso di mettermi a lavorare a qualche esperimento tutto mio.$B$BDi recente ho letto dell'Un'Goro Crater e della strana attività vulcanica che c'è al suo centro. Credo che ci sarebbe molto da imparare, se solo riuscissi a mettere le mani su un po' di cenere degli elementali che stanno lì.$B$BTi dispiacerebbe raccoglierne per me, se passi da quelle parti?",
  obj = "Raccogli 9 campioni di Un'Goro Ash dagli elementali del fuoco intorno al vulcano in Un'Goro Crater e riportali a Liv Rizzlefix a Ratchet.",
  progress = "È vero che il vulcano di Un'Goro è attivo? Con un po' della sua cenere, $N, sono sicura che potrei imparare molto.",
  reward = "Questi campioni saranno perfetti per i miei studi! Grazie, $N! Te lo prometto, sarai $Gil primo:la prima; a cui racconterò cosa ho scoperto.",
}
T[4503] = {
  title = "Il Velivolo di Shizzle",
  desc = "Sto costruendo una macchina volante!$B$BSono rimasto bloccato qui, e a orientarmi sono proprio negato. Per tornare a Gadgetzan prenderei un grifone o una wind rider, ma quelle bestie mi fanno morire di paura.$B$BAllora, mi aiuti? Mi mancano solo le ali, e per farle pensavo che le scaglie palmate dello pterrordax e del diemetradon sarebbero perfette. Io non ho nessuna intenzione di affrontarne uno, ma tu sembri $Gbello tosto:bella tosta;. Perché non ci provi?",
  obj = "Raccogli 8 Webbed Diemetradon Scales e 8 Webbed Pterrordax Scales per Shizzle a Marshal's Refuge.",
  progress = "Ogni grande veicolo deve avere un nome... Io pensavo di chiamarlo... Pwned!",
  reward = "Sì, queste scaglie sono perfette. Con queste il velivolo riesco a farlo decollare di sicuro!$B$BGrazie!",
}
T[4504] = {
  title = "Super Appiccicoso",
  desc = "Sono sempre a caccia di un modo per fare un po' d'oro in fretta, $N. Dammi una mano con la mia ultima idea e ti spetta una piccola fetta dei guadagni. Che te ne pare?$B$BLo sapevo!$B$BVa' alle pozze di pece nella zona nord dell'Un'Goro Crater e raccogline un po' per me. Ma non una pece qualunque, eh: va presa dalle bestie che vivono attorno alle pozze. Quella normale non appiccica abbastanza.$B$BLe creature che sembrano piante hanno la clorofilla nella pelle, e se la mischi alla pece diventa super appiccicosa!",
  obj = "Raccogli 12 campioni di Super Sticky Tar per Tran'rek a Gadgetzan.",
  progress = "Altro colpo di Tran'rek — questa colla super appiccicosa andrà a ruba!",
  reward = "Sì, questa pece fa proprio al caso mio...$B$BEhi, un momento, le mani... Non riesco a staccarle...$B$BForse non è stata una grande idea. Oh, ma aspetta! Un solvente per la Super sticky tar! Ecco dove stanno i soldi veri!",
}
T[4505] = {
  title = "Il Pozzo della Corruzione",
  desc = "C'è chi direbbe che sono di una crudeltà fuori dal comune... Ma in verità è solo un forte desiderio di vedere l'Orda in vantaggio sull'Alleanza, con ogni mezzo possibile.$B$BUltimamente mi interessa un pozzo lunare alle Ruins of Constellas, a sud di qui, custodito dai satiri Jadefire. Un tempo era un simbolo di rinascita per quegli insopportabili elfi della notte; ora è corrotto, e lo usano per far nascere altri satiri.$B$BMi è venuta un'idea, $N, e vorrei un campione di quell'acqua... per questo mio piccolo amico felino.",
  obj = "Raccogli un campione di acqua corrotta dal pozzo lunare dei Jadefire Satyrs e portalo a Winna Hazzard a Bloodvenom Post.",
  progress = "La cosa è della massima importanza. Ora mettiti in cammino.",
  reward = "Molto bene. Dobbiamo trovare il modo di usare questa corruzione contro i nostri nemici...",
}
T[4506] = {
  title = "Corrupted Sabers",
  desc = "Quest'acqua corrotta può tornarci utile, $N. Ne è bastato appena un goccio e il mio gattino è diventato grande il doppio, e sembra più forte... in qualche modo. Questi gatti potrebbero servirci...$B$BEcco, $N. Prendi questo trasportino: il gattino che c'è dentro liberalo accanto al pozzo lunare, nelle Ruins of Constellas. Eh, eh... Sono certa che sarai $Gsoddisfatto:soddisfatta; dei risultati!$B$BRiportami il gatto, e il tempo che ci avrai speso te lo ripagherò, vedrai.",
  obj = "Porta il gattino di Winna al pozzo lunare corrotto, liberalo, poi riportalo da Winna.$B$BQuando sarai $Gtornato:tornata; da Winna, clicca sul gatto per consegnarlo a Winna.",
  progress = "Non mi dirai che non riesci a tornare laggiù! Muoviti!",
  reward = "Eccellente!$B$BI forsaken ricorreranno a ogni mezzo per schiacciare l'alleanza! E l'acqua corrotta ci sarà di certo utile nelle imprese che ci aspettano...",
}
T[4507] = {
  title = "Il Pedone Mangia la Regina",
  desc = "Ecco l'esca. Nella rete dell'alveare dovrebbe esserci una specie di cristallo, che secondo noi i silithid usano come una sorta di dispositivo di sintonia per l'alveare intero. Io lo cercherei nelle incubatrici.$B$BUsa l'esca sul cristallo e dovresti stanare la regina, ma stai $Gattento:attenta; — probabilmente avrà diverse guardie a proteggerla. Fai fuori la regina e prendile il cervello. Sarà uno schifo, ma ci serve disperatamente per studiarlo. Buona fortuna, $N!",
  obj = "Sconfiggi la Gorishi Hive Queen una volta evocata.$B$BPorta il Cervello della Regina Gorishi ad Alchemist Pestlezugg a Gadgetzan.",
  progress = "Per le nostre ricerche il cervello della regina ci serve assolutamente. Da quel che abbiamo scoperto, crediamo sia ben possibile che questi silithid siano controllati da un'intelligenza maligna. Rabbrividisco al pensiero di cosa possa tenere in pugno qualcosa di insidioso come i silithid, $N.",
  reward = "Fantastico, $N! Oggi abbiamo vinto una bella battaglia. Ci vorrà un po' per capire fino in fondo cosa abbiamo in mano, ma ne faremo buon uso, non preoccuparti.$B$BQuanto ai silithid, dubito sinceramente che sia tutto qui. Mi dispiace dirlo, ma è andato tutto fin troppo liscio.",
}
T[4508] = {
  title = "La Calma Prima della Tempesta",
  desc = "Le mie ultime scoperte, e quello che abbiamo imparato qui oggi, devono finire nelle mani di chi probabilmente può farci qualcosa. Per quanto qui a Gadgetzan sappiamo arrangiarci, da soli non ce la possiamo fare.$B$BPorta il mio ultimo rapporto a Gracina Spiritmight, a Darnassus: sta ancora al Tempio della Luna, giusto? Ha degli amici fra i pezzi grossi dell'Alleanza, e se riusciamo a tirarli dentro questa faccenda, $N, forse ne usciremo vivi.",
  obj = "Porta il Pestlezugg's Un'Goro Report a Gracina Spiritmight, a Darnassus.",
  progress = "Sono degli sciocchi, $N! Non gli passa nemmeno per la testa di guardarsi intorno in cerca di una minaccia più grande, e il loro odio irrazionale per l'Orda sarà la fine di tutti noi. Non so più che prove dargli della minaccia silithid, a parte buttarli in uno degli alveari perché la vedano con i loro occhi!$B$BScusami, mi porti notizie?",
  reward = "Lo apprezzo davvero, ma non so a cosa ci servirà. L'Alleanza ignora ogni minaccia che non venga dall'Orda, e perfino i nostri capi qui a Darnassus non riescono a mettersi d'accordo su cosa sia esattamente questa minaccia. Sciocchi come Fandral Staghelm sostengono che i silithid non siano affatto quello che dico io, la minaccia di un antico passato. Solo la sua arroganza supera la sua ignoranza.$B$BTu la minaccia l'hai vista di persona, $N. Dobbiamo restare decisi a sconfiggere i silithid!",
}
T[4509] = {
  title = "Calma Prima della Tempesta",
  desc = "Le mie ultime scoperte, insieme a quello che abbiamo imparato qui oggi, devono arrivare nelle mani di chi probabilmente può farne qualcosa. Noi di Gadgetzan saremo anche pieni di risorse, ma da soli non possiamo farcela.$B$BPorta il mio ultimo rapporto a Zilzibin Drumlore, a Orgrimmar: sta ancora nella parte alta di The Drag, giusto? Ha amici in alto nell'Orda, e se riusciamo a coinvolgerli in questa faccenda, $N, forse ne usciremo vivi.",
  obj = "Porta il Pestlezugg's Un'Goro Report a Zilzibin Drumlore, a Orgrimmar.",
  progress = "Sono degli sciocchi, $N! Non gli passa nemmeno per la testa di guardarsi intorno in cerca di una minaccia più grande, e quel loro odio irrazionale per l'Alleanza sarà la nostra rovina. Non so quante altre prove potrei dargli della minaccia dei silithid, a meno di buttarli in uno degli alveari a vedere con i loro occhi!$B$BScusa, mi porti delle notizie?",
  reward = "Ti sono davvero grato, ma non so a cosa ci servirà. L'Orda non bada alle minacce che non vengono dall'Alleanza. Forse Thrall in persona agirebbe, se qualcuno gli mettesse davanti i fatti, ma è assediato da ogni parte da consigli che si contraddicono. Se pensassero che servisse a cogliere di sorpresa l'Alleanza, questi sciocchi ci farebbero correre dietro alla nostra coda immaginaria!$B$BLa minaccia l'hai vista tu $Gstesso:stessa;, $N. Dobbiamo continuare a darci da fare per sconfiggere i silithid!",
}
T[4510] = {
  title = "La Calma Prima della Tempesta",
  desc = "$N, il tuo aiuto è stato inestimabile. Senza dubbio verrà il momento in cui avrò ancora bisogno di te contro i silithid. Dobbiamo assimilare quello che abbiamo scoperto a Un'Goro: temo di aver sbagliato a credere che i silithid venissero da Un'Goro... e che da qualche parte ci sia davvero una presenza molto più forte.$B$BPorta questo biglietto a Idriana, in banca: ti darà qualcosa dal mio caveau, e consideralo un segno della mia gratitudine. Grazie del tuo aiuto, $Gvaloroso:valorosa; $C.",
  obj = "Porta il Bank Voucher a Idriana, nella banca di Darnassus.",
  progress = "Elune'adore, $C. In cosa posso esserti utile, oggi?",
  reward = "Questo bank voucher mi autorizza a prelevare un oggetto dal conto che Gracina Spiritmight tiene da noi e a consegnartelo. Direi che è il caso di farti le congratulazioni!",
}
T[4511] = {
  title = "Calma Prima della Tempesta",
  desc = "$N, senza di te non saremmo arrivati fin qui. Presto verrà il momento, non c'è dubbio, in cui ti chiederò di nuovo aiuto contro i silithid. Dobbiamo fare tesoro di quello che abbiamo scoperto a Un'Goro: temo di essermi sbagliato a pensare che i silithid venissero da Un'Goro... e che in realtà, da qualche parte, ci sia una presenza molto più forte.$B$BPorta questo biglietto a Karus, in banca. Ti darà qualcosa dal mio caveau, come segno della mia gratitudine. Grazie dell'aiuto, potente $C.",
  obj = "Porta il Bank Voucher a Karus, nella banca di Orgrimmar.",
  progress = "Zug zug! Cosa posso fare per te oggi, $C?",
  reward = "Con questo bank voucher sono autorizzato a prelevare un oggetto dal conto che Zilzibin Drumlore ha da noi e a consegnartelo. Direi che le congratulazioni sono d'obbligo!",
}
T[4512] = {
  title = "Un Po' di Melma Fa Tanta Strada",
  desc = "Ma quello che ho studiato più di tutto sono le melme. Lo so, sembra strano, ma sono dappertutto!$B$BNon molto tempo fa ho aiutato una signora a Menethil a ritrovare la borsa — se l'erano mangiata le melme. E ho visto dei membri della Royal Apothecary Society di Undercity raccogliere campioni di quella roba. Voglio sapere perché! Da dove viene?$B$BHo sentito dire che a Felwood ce ne sono altre. Per andare avanti con la ricerca mi servono campioni delle melme di laggiù. Ti darò dei contenitori: usali sulle creature morte per raccoglierne un campione.",
  obj = "Porta 6 Filled Cursed Ooze Jars e 6 Filled Tainted Ooze Jars a Laris Geardawdle a Ironforge.",
  progress = "Certi esperimenti che ho fatto sono affascinanti. Credo che con un altro po' di lavoro riuscirò a capire la natura di queste creature e che parte abbiano avuto nello sviluppo della vita su Azeroth... sempre che c'entrino qualcosa.$B$BUna delle mie teorie più importanti, che piace poco, è che le melme e le poltiglie siano legate alla creazione di questo pianeta... quasi ne fossero una secrezione.$B$BMa non posso né dimostrarla né smentirla finché non avrò altri campioni.",
  reward = "Risultati straordinari, $N! Sei $Griuscito:riuscita; ad avvicinarti abbastanza a quelle cose corrotte da prenderne un campione, e non sembri neanche $Gmalconcio:malconcia;! Grazie. Oh, questi campioni andranno benissimo. Non vedo l'ora di cominciare i test.$B$BSe ho ragione, potrei diventare uno dei più grandi scienziati della Lega degli Esploratori!$B$BE così tutti i nani vedranno che accogliere noi gnomi a Ironforge dopo l'incidente di Gnomeregan non è stato un errore.",
}
T[4513] = {
  title = "Un Po' di Melma Fa Tanta Strada",
  desc = "Mi servono altri campioni, $N. Ma — non so bene come dirlo — devono essere puri. Lo so, lo so. \"Cosa vuol dire 'puri', Laris?\" Non ne sono sicuro. Però so che questi sono corrotti... proprio come Felwood. Ed è questo che rende la mia scoperta così importante. Sembra che le melme si adattino... che prendano le caratteristiche della zona in cui si trovano. Dovrò trovare campioni non contaminati. Ma dove? Dove?!$B$BBah! $N, prendi questi contenitori, caso mai ne trovassi qualcuno per conto tuo.",
  obj = "Porta 10 Filled Pure Sample Jars a Laris Geardawdle a Ironforge.$B$BSe hai difficoltà a trovarli, prova a farti dare altri indizi da Laris.",
  progress = "Quante cose da considerare. Ma che significa? E che effetto ha sulla vita della gente di Azeroth?",
  reward = "L'hai trovato? $N, sei un vero tesoro. La tua dedizione e il tuo aiuto sono stati magnifici, e non potrò mai ringraziarti abbastanza.$B$BTi prego, prendi questo per il disturbo. Ora ho del lavoro da sbrigare, ma se torni più avanti sono sicuro che avrò di nuovo bisogno dei tuoi servigi.$B$BGrazie. Grazie davvero.",
}
T[4521] = {
  title = "Guardiani Selvaggi",
  desc = "Winterspring è appena oltre i Timbermaw, a nord-est di Felwood. Ci sei mai $Gstato:stata;?$B$BHo sentito dire che la zona è piena di creature chiamate selvagufi. Si sa che queste bestie custodiscono dei segreti; segreti degli Elfi della Notte.$B$BDobbiamo scoprire cosa potrebbe nascondersi a Winterspring.$B$BMi dicono che i ragged owlbeasts stanno appena a sud della strada, mentre al centro di Winterspring ce ne sono altri, chiamati raging owlbeasts. Spazzali via e aprici l'accesso a quelle terre.",
  obj = "Trull Failbane a Felwood vuole che tu uccida 15 Raging Owlbeasts e 15 Ragged Owlbeasts.",
  progress = "Quando avrai portato a termine il compito che ti ho affidato, torna a fare rapporto.",
  reward = "Ottime notizie, $N. Ora che queste bestie sono state tolte di mezzo, possiamo cominciare a spingerci più a fondo a Winterspring. Sei $Gpronto:pronta; a continuare?",
}
T[4542] = {
  title = "Messaggio per Freewind Post",
  desc = "$GCoraggioso:Coraggiosa; $Gviaggiatore:viaggiatrice;, qui i centauri attaccano sempre più spesso, e Freewind Post deve sapere subito di queste nuove aggressioni! Va' a sud-est, a Freewind Post, cerca Cliffwatcher Longhorn e consegnagli quest'urgent message.$B$BE sta' in guardia: tieniti alla larga dal Grimtotem Clan, qui vicino... ultimamente con noi si comportano in modo strano.",
  obj = "Porta l'Urgent Message a Cliffwatcher Longhorn a Freewind Post.",
  progress = "Che cosa vuoi, $C? Un urgent message — per me?",
  reward = "Altre cattive notizie! Questi centauri hanno passato il segno! Hanno assaltato una delle mie carovane di rifornimenti e massacrato tutto il gruppo. È un oltraggio che non resterà impunito!",
  en_title = "Message to Freewind Post",
  en_obj = "Bring the Urgent Message to Cliffwatcher Longhorn at Freewind Post.",
}
T[4561] = {
  title = "Analisi delle Impurità — Un'Goro Crater",
  progress = "Prendi un campione di melma dell'Un'Goro Crater e ne versi un po' nelle varie provette e becher sul tavolo. Tutto comincia a bollire e a schizzare, e intanto la melma cambia colore. Quando il processo rallenta e i liquidi si calmano, vedi una piccola capsula di Petri con dentro i tuoi campioni purificati di melma di Un'Goro, insieme ad altri residui.",
  reward = "Prendi la capsula di Petri con il campione di melma. Per sapere se il campione è abbastanza puro c'è un solo modo: aprirla ed esaminarne il contenuto di persona. Se va bene, troverai un campione che soddisfi i criteri di Chemist Fuely.",
}
T[4581] = {
  title = "Kayneth Stillwind",
  desc = "Il druido Kayneth Stillwind mi ha fatto sapere che vorrebbe un rapporto su quello che succede lungo la nostra costa e nelle foreste intorno ad Astranaar. Teme che una corruzione si stia diffondendo per Ashenvale... e forse ha ragione.$B$BEcco il mio rapporto, portaglielo. Lo troverai nel santuario di Forest Song, nei Nightsong Woods a est.",
  obj = "Porta lo Shindrell's Note a Kayneth Stillwind a Forest Song.",
  progress = "Hai qualcosa per me?",
  reward = "Ah, il rapporto di Shindrell! Grazie mille, $N. Shindrell è una sentinella eccellente, coraggiosa e acuta. Devo leggerlo per cercare indizi su una malvagità che temo si stia diffondendo per Ashenvale.",
  en_title = "Kayneth Stillwind",
  en_obj = "Take Shindrell's Note to Kayneth Stillwind in Forest Song.",
}
T[4601] = {
  title = "The Sparklematic 5200!",
  desc = "Fra gli gnomi che resistono alla follia fuori dalla stanza, questo marchingegno salta all'occhio. Sul congegno c'è una piccola targa con la scritta \"Lo Sparklematic 5200\", seguita da un testo:$B$B\"Sporco e incrostazioni vi rovinano le cosine luccicanti? Lo Sparklematic 5200 rimette lo splendore nello splend-tastico! Inserite l'oggetto da pulire e infilate tre monete d'argento nella fessura. Lasciate lavorare lo Sparklematic 5200 per un momento e voila! I vostri oggetti di valore usciranno puliti e luccicanti!\"",
  obj = "Inserisci un Oggetto Sudicio nello Sparklematic 5200 e assicurati di avere tre monete d'argento per avviare la macchina.",
  progress = "A quanto pare, per avviarsi il congegno vuole un qualche grime-encrusted object da pulire e tre monete d'argento. Con tutti e due, lo Sparklematic 5200 dovrebbe funzionare...",
  reward = "Metti l'oggetto sudicio e tre monete d'argento nello Sparklematic 5200. La macchina si risveglia di colpo e si lancia in un tentativo frenetico di togliere lo sporco dall'oggetto sconosciuto. Dal suo cuore arrivano i rumori forti e violenti di qualcosa che gira e sbatte. La bestia sbanda da una parte all'altra, e il telaio di metallo scricchiola e geme...",
  en_title = "The Sparklematic 5200!",
  en_obj = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
}
T[4602] = {
  title = "The Sparklematic 5200!",
  desc = "Fra gli gnomi che resistono alla follia fuori dalla stanza, questo marchingegno salta all'occhio. Sul congegno c'è una piccola targhetta con la scritta \"Lo Sparklematic 5200\", seguita da un testo:$B$B\"Le tue cosine luccicanti sono rovinate da sporcizia e residui? Lo Sparklematic 5200 rimette lo splendore nello splendido! Inserisci l'oggetto da pulire e infila tre monete d'argento nella fessura. Lascia lavorare lo Sparklematic 5200 per qualche istante e voila! I tuoi oggetti di valore usciranno puliti e splendenti!\"",
  obj = "Inserisci un Oggetto Sudicio nello Sparklematic 5200, e assicurati di avere tre monete d'argento per avviare la macchina.",
  progress = "A quanto pare il congegno ha bisogno di un qualche grime-encrusted object da pulire e di tre monete d'argento per mettersi in moto. Con tutti e due, lo Sparklematic 5200 dovrebbe funzionare...",
  reward = "Inserisci l'oggetto sudicio e tre monete d'argento nello Sparklematic 5200. La macchina si risveglia di colpo e si mette a cercare, frenetica, di togliere la sporcizia dall'oggetto sconosciuto. Dal suo cuore rimbombano rumori di rimescolio, forti e violenti, e il telaio di metallo della bestia scricchiola e geme mentre sbanda da una parte all'altra...",
  en_title = "The Sparklematic 5200!",
  en_obj = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
}
T[4603] = {
  title = "Altra Azione con lo Sparklematic",
  progress = "The Sparklematic 5200 è vuoto e per partire aspetta un grime-encrusted object da pulire e tre monete d'argento!",
  reward = "Lo Sparklematic 5200 si risveglia e comincia a sbandare avanti e indietro. Là dentro, l'agente pulente gnomesco della macchina polverizza lo sporco indifeso incrostato sull'oggetto inserito.$B$BCon un \"din!\" familiare, lo Sparklematic 5200 si ferma. Lo scomparto per gli oggetti si apre a spirale e dentro compare una neatly wrapped box.",
  en_title = "More Sparklematic Action",
}
T[4604] = {
  title = "Altra Azione Sparklematic",
  progress = "The Sparklematic 5200 è vuoto: aspetta un grime-encrusted object da pulire e tre monete d'argento per partire!",
  reward = "Lo Sparklematic 5200 si accende e comincia a sbandare avanti e indietro. Dentro la macchina, il detergente gnomesco polverizza l'indifesa sporcizia incrostata sull'oggetto.$B$BPoi, con un familiare \"ding!\", lo Sparklematic 5200 si ferma. Il vano per gli oggetti si apre a spirale e rivela una neatly wrapped box.",
  en_title = "More Sparklematic Action",
}
T[4605] = {
  title = "The Sparklematic 5200!",
  reward = "Così rapido com'era partito, lo Sparklematic 5200 si ferma di colpo. Dalla macchina arriva un semplice \"din\", e la sua bocca si apre a spirale verso l'alto. Dentro c'è una scatolina legata con un fiocchetto. Si direbbe che la macchina incarti l'oggetto dopo averlo liberato dal sudiciume. Se anche non avesse funzionato, almeno adesso l'oggetto è incartato in una bella scatola.$B$BBe', c'è un modo per scoprire se l'ha pulito o no...",
  en_title = "The Sparklematic 5200!",
}
T[4606] = {
  title = "The Sparklematic 5200!",
  reward = "Lo Sparklematic 5200 si ferma all'improvviso, rapido com'era partito. Si sente un semplice \"ding\" e la bocca della macchina si apre a spirale verso l'alto: dentro c'è una scatolina legata con un fiocchetto. A quanto pare, la macchina incarta gli oggetti dopo averli ripuliti dalle incrostazioni. E anche se non avesse funzionato, almeno adesso l'oggetto sta chiuso in una bella scatola.$B$BBe', per sapere se l'ha pulito oppure no c'è un modo solo...",
  en_title = "The Sparklematic 5200!",
}
T[4621] = {
  title = "Alt, Ammiraglio!",
  desc = "Stammi a sentire, lupo di mare... è i poteri di Booty Bay che non ci lascia, a noi Bloodsail, navigare dove ci pare e prenderci quel che vogliamo per diritto di saccheggio. Se piantassi un coltello in Fleet Master Seahorn, con le navi di Booty Bay non avremmo mai più guai. E se ne piantassi uno in Baron Revilgaz, non ci toccherebbe mai più subire la legge come dicono loro.$B$BSe vuoi diventare ammiraglio onorario fra di noi — sì, AMMIRAGLIO, gli pianti un coltello a tutti e due, come t'ho detto. Adesso va', $Gragazzo:ragazza;, e torna da me quando che il lavoro è fatto.",
  obj = "Uccidi Fleet Master Seahorn e Baron Revilgaz of Booty Bay, poi torna da Fleet Master Firallon a bordo di Crimson Veil, al largo della costa di Stranglethorn Vale.",
  progress = "Sei già $Gtornato:tornata;, dannato marinaio! L'hai fatto, quel che t'ho ordinato? Se ci deludi, ti tocca camminare sull'asse.$B$BArrrrr...",
  reward = "Alt... Ammiraglio $N! Sei $Gil:la; pirata dei pirati, $Gragazzo:ragazza;!$B$BDarti questo cappello mi scalda il cuore. Uno così non lo troverai mai da nessun'altra parte, e chiunque ti guardi vedrà che sei un Ammiraglio della Marina Bloodsail!",
  en_title = "Avast Ye, Admiral!",
  en_obj = "Slay Fleet Master Seahorn and Baron Revilgaz of Booty Bay, and then return to Fleet Master Firallon aboard the Crimson Veil off the coast of Stranglethorn Vale.",
}
T[4642] = {
  title = "Fusione di Influenze",
  desc = "Ecco un po' di melma sigillata, ottenuta dai campioni di Felwood che hai recuperato. Porta il contenitore all'Un'Goro Crater e trova una melma pura... una primordiale andrà benissimo. Quando sarai abbastanza $Gvicino:vicina;, fai uscire la melma dal contenitore e vediamo che cosa pensano l'una dell'altra.$B$BFinito l'esperimento, portami un campione di quello che ne resta. Ti aspetto qui nell'Apothecarium.",
  obj = "Porta un Merged Ooze Sample a Chemist Fuely a Undercity.",
  progress = "Come va l'esperimento, $N? Io continuerò a studiare i campioni che mi hai recuperato — comincio a capire perché Lady Sylvanas si interessi tanto a queste creature. Se fanno davvero parte degli Old Gods, chissà come potremo approfittarne.",
  reward = "Oh, davvero eccellente, $N. Questo sì che è davvero eccellente.$B$BChe storia. Chi l'avrebbe mai detto che le due avrebbero interagito così... Dovrò dedicare più tempo a studiare quali fattori dell'ambiente modificano queste creature.$B$BPer ora proseguo con le mie ricerche. Forse ci rivedremo presto. Fino ad allora, ti auguro ogni bene.",
}
T[4661] = {
  title = "Analisi della Corruzione — Felwood",
  progress = "Prendi un campione di melma di Felwood e ne versi un po' nelle varie provette e becher sul tavolo. Tutto comincia a bollire e a schizzare, e intanto la melma cambia colore. Quando il processo rallenta e i liquidi si calmano, vedi una piccola capsula di Petri con dentro i tuoi campioni alterati di melma di Felwood, insieme ad altri residui.",
  reward = "Prendi la capsula di Petri con il campione di melma. Per sapere se il campione è abbastanza puro c'è un solo modo: aprirla ed esaminarne il contenuto di persona. Se va bene, troverai un campione che soddisfi i criteri di Chemist Fuely.",
}
T[4701] = {
  title = "Abbattila",
  desc = "Avrai visto di certo i worgs al servizio degli orchi Blackrock.$B$BÈ curioso — per quanti ne distruggiamo, non calano mai. I miei esploratori riferiscono che i worgs vengono allevati, addestrati e poi mandati fuori da Blackrock Spire: la capitale degli orchi Blackrock. Devi recarti a Blackrock Spire e trovare l'origine di questa minaccia. Trovarla... e distruggerla.$B$BBuona fortuna, $N. Che Cenarius ti protegga...",
  obj = "Recati a Blackrock Spire e distruggi l'origine della minaccia dei worgs. Mentre te ne andavi, Helendis ha gridato un nome: Halycon. È il nome con cui gli orchi chiamano il worg.",
  progress = "Hai trovato l'origine della minaccia dei worgs e te ne sei $Goccupato:occupata;?",
  reward = "Non soffermarti sulla sua sofferenza, $N. La bestia era corrotta — frutto di magia oscura. Hai reso un grande servizio all'Alleanza e verrai $Gricompensato:ricompensata;.",
}
T[4721] = {
  title = "Guardiani Selvaggi",
  desc = "Sono tornati dei messaggeri da Winterspring, e dicono che nella parte meridionale di Winterspring c'è una serie di piccole caverne. Sembra che dei selvagufi si siano stanziati lì intorno. Se custodiscono qualcosa di prezioso, credo che lo troveremo lì.$B$BQuesti, vedrai, saranno più difficili dei precedenti, $N. Pare che le creature siano impazzite a forza di stare vicine proprio alla cosa che cercano di proteggere.",
  obj = "Trull Failbane a Felwood vuole che tu dia la caccia a 10 Berserk Owlbeasts a Winterspring.",
  progress = "Gli ordini li conosci, $N.",
  reward = "Per il duro lavoro ho un gran rispetto, $N. Ora possiamo portare avanti i nostri piani per Winterspring.",
}
T[4724] = {
  title = "La Padrona del Branco",
  desc = "C'è chi dice che i worg comandati dagli orchi Blackrock siano opera di una forza soprannaturale. Altri sostengono che non siano veri worg, ma una razza di cani demoniaci che un signore degli abissi caduto ha donato agli orchi.$B$BLa verità è molto meno contorta, ma fa altrettanta paura. I worg dei Blackrock discendono da Halycon e dal suo compagno. Halycon è la gigantesca matriarca della tana dei worg. E il suo compagno? Nessuno è mai sopravvissuto per raccontarlo.$B$BColpisci i worg al cuore. Distruggi Halycon... e guardati le spalle, $N.",
  obj = "Uccidi Halycon, padrona del branco dei worg Bloodaxe.",
  progress = "Morta la padrona del branco, possiamo cominciare a sfoltire le sentinelle worg della Guglia e, alla fine, guadagnare un po' di terreno dentro la città.",
  reward = "Cuccioli rabbiosi? Gizrul the Slavener? E sei $Gvivo:viva; per raccontarlo?! Incredibile! Questo tributo te lo sei proprio meritato!",
}
T[4726] = {
  title = "Broodling Essence",
  desc = "Da settimane studio i draconidi delle Burning Steppes, e finalmente credo di aver fatto una scoperta! Ho inventato un congegno — l'ho chiamato Draco Incarcinatrix 900. Riesce a catturare l'essenza delle broodlings di drago!$B$BO almeno, credo che ci riesca.$B$BEcco, prendi il congegno e colpisci una broodling nelle Burning Steppes. Se sconfiggi la broodling finché è sotto l'effetto, la sua essenza dovrebbe liberarsi.$B$BSe succede, splendido! Riportami un po' di campioni da studiare!",
  obj = "Porta 8 campioni di Broodling Essence e il Draco-Incarcinatrix 900 a Tinkee Steamboil, presso Flame Crest, in Burning Steppes.",
  progress = "Ce l'hai la broodling essence, $N? Non vedo l'ora di studiarla.$B$BE poi... il mio mecenate non è uno da deludere.",
  reward = "Ha funzionato! L'hai presa, l'essenza! Ben fatto, $N! Ben fatto!$B$BPer le mie ricerche questa essenza sarà preziosissima. Un giorno spero di imparare a catturare cuccioli di drago vivi, o magari le loro uova. Se trovassi il modo, tutti gli studiosi di draghi del mondo mi invidierebbero!$B$BE ne sarebbe soddisfatto anche il mio datore di lavoro, che, come ti ho detto prima, è meglio tenere contento...",
}
T[4729] = {
  title = "Kibler's Exotic Pets",
  desc = "Ti chiederai che ci faccio qui fuori. Guarda le gabbie! Mi pare ovvio, no?$B$BPrima di tutto amo gli animali, ma di mestiere faccio il venditore. Scovo animali esotici per i ricchi e i famosi, e addomestico le bestie perché si comportino da veri animali da compagnia.$B$BE adesso ti domanderai: \"Cosa posso fare per te, Kibler?\" Semplice: prendi questa gabbia per bestie e trovami dei worg pups. In cambio ti addomesticherò un worg!",
  obj = "Recati a Blackrock Spire e trova dei Bloodaxe Worg Pups. Usa la gabbia per trasportare le piccole bestie feroci. Riporta un Caged Worg Pup a Kibler.",
  progress = "<Kibler è tutto preso a litigare con Opus.>",
  reward = "Li hai presi giusto in tempo, $N. Ancora un po' e non si sarebbero più lasciati addestrare! Dammi un attimo e il piccoletto sarà pronto da portare a casa.",
}
T[4734] = {
  title = "Congelamento delle Uova",
  desc = "$N, ho lavorato sodo a un congegno nuovo, l'eggscilloscope! Serve a sparare una raffica di energia gelida sull'uovo di un drago nero... e a congelarlo del tutto! Me lo provi?$B$BHo sentito dire che i draghi hanno un nido in alto nel Blackrock Spire, dove fanno schiudere le uova. Dovrai andare proprio lì a provare l'eggscilloscope, e poi fammi sapere come ha funzionato!$B$BE niente paura. Le uova di drago congelate dovrebbero essere innocue. È di quelle non congelate che devi preoccuparti!",
  obj = "Usa l'Eggscilloscope Prototype su un uovo nel Nido.",
  progress = "$N, l'hai provato l'eggscilloscope?",
  reward = "Ha funzionato? Splendido! Lo sapevo!$B$BMentre non c'eri ho lavorato a una nuova versione dell'eggscilloscope, con una portata molto maggiore.$B$BEcco, tienine uno, caso mai tornassi al Blackrock Spire.",
}
T[4735] = {
  title = "Raccolta di Uova",
  desc = "$N, finalmente sono pronta per i campioni veri di uova di drago! Ecco, prendi questo collectronic module. È fatto per estrarre un uovo di drago e prepararlo al trasporto. Torna alla Covata e raccogli le uova con il modulo.$B$BE non dimenticarti di congelarle, o potrebbero schiudersi prima che tu riesca a prenderle!$B$BQuando ne avrai abbastanza, portamele!",
  obj = "Porta 8 Collected Dragon Eggs e il Collectronic Module a Tinkee Steamboil a Flame Crest, in Burning Steppes.",
  progress = "Ce le hai, le uova, $N? Il mio finanziatore ha saputo che le stai raccogliendo per me e non vede l'ora di metterci le mani sopra!",
  reward = "Wow, le hai prese! Il collectronic module ha funzionato! Sono un genio!$B$BGrazie, $N. Il mio finanziatore sarà proprio contento di ricevere queste uova...",
}
T[4736] = {
  title = "In Cerca di Menara Voidrender",
  desc = "Ah, salve, $N. Stai facendo buoni progressi con l'addestramento, tanto che secondo me ti meriti una ricompensa per l'impegno — e per non esserti ancora $Gfatto:fatta; corrompere dall'arcano.$B$BSe ti interessa, cerca Menara Voidrender a Ratchet. Al momento la trovi nella torre di Strahad Farsan, quella che domina la città.$B$BNon è un tipo molto cordiale, $N, quindi non aspettarti lodi. Ma se lavori sodo, farà in modo che non ti manchi nulla.",
  obj = "Parla con Menara Voidrender in Barrens.",
  reward = "Ah, ti manda Briarthorn. Bene. Vuol dire che la voce arriva abbastanza lontano da raggiungere i futuri allievi, e ne sono lieta.$B$BQuelli come noi, $N, di solito fanno fronte comune, qualunque sia la razza. Ed è importante soprattutto per questo: se non riusciamo a placare o a controllare come si deve coloro con cui abbiamo più a che fare, riversano la loro malvagità su tutti, senza distinzioni.$B$BHai imparato moltissime cose, credo, e se sei $Gdisposto:disposta; ti aiuterei a creare degli strumenti che completino le tue abilità.",
}
T[4737] = {
  title = "In Cerca di Menara Voidrender",
  desc = "Hmph, continui a sforzarti per diventare più potente. Per me è solo questione di tempo: la corruzione e la dipendenza si impadroniranno di te e diventerai $Gschiavo:schiava; di ciò che cerchi di dominare.$B$BPfah! $GUno sciocco:Una sciocca; sei! Il tempo mi darà ragione — nient'altro... solo il tempo.$B$BMa a quanto pare non tutti la pensano come Zevrost. Sembra che Menara voglia creare per te degli strumenti per renderti più potente e sfruttare la tua forza. Se ti interessa, vai a Ratchet, nei Barrens: la trovi lì, sopra la città.",
  obj = "Parla con Menara Voidrender in Barrens.",
  reward = "Ah, ti manda Zevrost. Bene. Vuol dire che la voce arriva abbastanza lontano da raggiungere i futuri allievi, e ne sono lieta.$B$BQuelli come noi, $N, di solito fanno fronte comune, qualunque sia la razza. Ed è importante soprattutto per questo: se non riusciamo a placare o a controllare come si deve coloro con cui abbiamo più a che fare, riversano la loro malvagità su tutti, senza distinzioni.$B$BHai imparato moltissime cose, credo, e se sei $Gdisposto:disposta; ti aiuterei a creare degli strumenti che completino le tue abilità.",
}
T[4738] = {
  title = "In Cerca di Menara Voidrender",
  desc = "Chiariamo una cosa, $N: non credo che tu sia $Gpronto:pronta; per responsabilità del genere. Secondo me un novizio non dovrebbe mai mettere mano alla creazione di un oggetto di potere, soprattutto se non ha ancora dato prova di sé.$B$BMa non sta a me deciderlo. Spetta a chi ha il potere, o almeno a chi desidera concederti doni simili.$B$BSe vuoi saperne di più, ti consiglio di cercare Menara Voidrender a Ratchet. Di solito la trovi nella torre sopra la città portuale.",
  obj = "Parla con Menara Voidrender in Barrens.",
  reward = "Ah, ti manda Demisette. Bene. Vuol dire che la voce arriva abbastanza lontano da raggiungere i futuri allievi, e ne sono lieta.$B$BQuelli come noi, $N, di solito fanno fronte comune, qualunque sia la razza. Ed è importante soprattutto per questo: se non riusciamo a placare o a controllare come si deve coloro con cui abbiamo più a che fare, riversano la loro malvagità su tutti, senza distinzioni.$B$BHai imparato moltissime cose, credo, e se sei $Gdisposto:disposta; ti aiuterei a creare degli strumenti che completino le tue abilità.",
}
T[4739] = {
  title = "In Cerca di Menara Voidrender",
  desc = "$C! Sì, tu!$B$BTi manca qualche pezzo d'equipaggiamento, ma si vede chiaramente che sei $Gpronto:pronta; — l'aria intorno a te trasuda più sicurezza. Sì, adesso lo vedo.$B$BMenara Voidrender avrebbe qualcosa da insegnarti, se te la senti. Passa il tempo a istruire nelle arti arcane gli allievi più giovani, e fa persino dei doni a chi supera le sue prove.$B$BSe ti interessa, vai a Ratchet, nei Barrens. La trovi sopra la città, nella torre di Strahad.",
  obj = "Parla con Menara Voidrender in Barrens.",
  reward = "Ah, ti manda Kaal. Bene. Vuol dire che la voce arriva abbastanza lontano da raggiungere i futuri allievi, e ne sono lieta.$B$BQuelli come noi, $N, di solito fanno fronte comune, qualunque sia la razza. Ed è importante soprattutto per questo: se non riusciamo a placare o a controllare come si deve coloro con cui abbiamo più a che fare, riversano la loro malvagità su tutti, senza distinzioni.$B$BHai imparato moltissime cose, credo, e se sei $Gdisposto:disposta; ti aiuterei a creare degli strumenti che completino le tue abilità.",
}
T[4741] = {
  title = "Guardiani Selvaggi",
  desc = "Nella parte settentrionale di Winterspring i Selvagufi si fanno ancora più feroci, e lassù dobbiamo continuare a intervenire.$B$BDai la caccia ai moontouched owlbeasts a Winterspring ed esplora la zona dove vivono.$B$BIl terreno è pericoloso, ma so che sarai all'altezza della sfida. Torna da me quando avrai ucciso 13 selvagufi.",
  obj = "Trull Failbane a Felwood vuole che tu dia la caccia a 13 Moontouched Owlbeasts.",
  progress = "Non dirmi che sei troppo $Gspaventato:spaventata;! Muoviti!",
  reward = "Si vede che il lavoro ti piace. E qui, credo, siamo sulla pista giusta.",
}
T[4742] = {
  title = "Sigillo dell'Ascesa",
  desc = "Come vedi, il sigillo disadorno ha tre castoni vuoti, e in ognuno va messa una gemma che rappresenta il comando dei capi. Alla fine Overlord Wyrmthalak, signore della cittadella inferiore, deve forgiare il sigillo nelle fiamme del Black Dragonflight.$B$BSappi questo, mortale: capita di rado che uno dei tre generali della cittadella inferiore porti con sé una gemma, perciò durante la ricerca dovrai stare all'erta. Resta $Gdeterminato:determinata;!",
  obj = "Trova le tre gemme del comando: la Gemstone of Smolderthorn, la Gemstone of Spirestone e la Gemstone of Bloodaxe. Riportale, insieme all'Unadorned Seal of Ascension, a Vaelan.$B$BI Generali, come ti ha detto Vaelan, sono: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; e Overlord Wyrmthalak dei Bloodaxe.",
  progress = "Prima di tutto coraggio e pazienza, $N!",
  reward = "<Per un istante l'immagine di Vaelan si fa sfocata.>$B$B<I pezzi che avevi raccolto sono scomparsi.>$B$BOra l'Unforged Seal of Ascension è pronto. È arrivato il momento dell'ultimo passo.",
}
T[4743] = {
  title = "Sigillo dell'Ascesa",
  desc = "A parte quelli della cittadella superiore, sono pochi i dragonidi neri capaci di forgiare il sigillo con il loro alito di fuoco. Wyrmthalak è uno di loro, ma la sua volontà è infrangibile.$B$BDevi andare al Wyrmbog, nella Dustwallow Marsh, dove troverai un antico drake chiamato Emberstrife. Devi spezzargli la volontà, $N. Una volta spezzata, usa questo globo sul suo corpo indebolito: avrai pochi secondi per controllarne la mente e alimentare le fiamme che forgeranno il sigillo.",
  obj = "Vai al Wyrmbog in Dustwallow Marsh. Trova l'antico drake, Emberstrife, e picchialo senza pietà finché la sua volontà non sarà spezzata.$B$BÈ in quel momento che dovrai mettere l'Unforged Seal of Ascension davanti alla grande bestia. Poi dovrai essere $Gsvelto:svelta; a usare l'Orb of Draconic Energy sul suo corpo indebolito e impadronirti delle sue facoltà mentali. Controlla la bestia e scaglia le Fiamme del Black Dragonflight sull'Unforged Seal of Ascension!",
  progress = "Non perdere tempo, $N: Nefarian lavora febbrilmente per scatenare il suo male sul nostro mondo.",
  reward = "Stai $Gfermo:ferma; mentre pronuncio l'ultima invocazione di protezione.$B$B<Gli occhi di Vaelan diventano due globi di fiamma.>$B$BIl Sigillo dell'Ascesa è completo...$B$BSappi che ho infuso nel manufatto potenti protezioni: nell'ora più buia, quando tutto sembrerà perduto, la potenza dello stormo rosso sarà al tuo servizio.",
}
T[4764] = {
  title = "Doomrigger's Clasp",
  desc = "In alto in Blackrock Spire c'è una sala che un tempo chiamavano Hall of Fortune. Lì i nani Dark Iron custodivano reliquie, trofei e opere d'arte.$B$BParlo di molto tempo fa. Dicono che la sala sia crollata e che adesso serva a... scopi meno raccomandabili. Eppure credo che ci si possano ancora trovare antiche reliquie dei nani.$B$BFra queste c'è la Doomrigger's clasp, dalla superficie così incrostata di gemme rare che, a quanto si diceva, faceva piangere qualunque nano la guardasse.$B$BÈ quella fibbia il tuo obiettivo, $N.",
  obj = "Porta la Doomrigger's Clasp a Mayara Brightwing in Burning Steppes.",
  progress = "Allora, $N, hai la fibbia? Il mio mecenate la pagherà profumatamente.",
  reward = "L'hai trovata! Allora le voci erano vere!$B$BGrazie, $N. Count Remington Ridgewell, il mio mecenate, sarà molto contento di vedere questo nuovo pezzo per la sua collezione.",
}
T[4765] = {
  title = "Consegna a Ridgewell",
  desc = "Ho imballato la Fibbia di Doomrigger in una cassa, pronta per il viaggio fino a Stormwind. Mi sei $Gstato:stata; di grandissimo aiuto, $N — posso chiederti un ultimo favore?$B$BConsegna la cassa a Count Remington Ridgewell: lo troverai nella Fortezza di Stormwind. Sono certa che sarà molto contento di vedere cosa hai per lui.",
  obj = "Porta la Ridgewell's Crate a Remington Ridgewell a Stormwind.",
  progress = "Mi hanno detto che sarebbe arrivato un messaggero, con un dono da Blackrock Spire.$B$BSei tu $Gquello:quella;?",
  reward = "Ah, allora sei davvero tu $Gquello:quella;! Ti ringrazio, $N. E... se ancora non lo sapevi... la gratitudine di un nobile del casato di Ridgewell vale quasi quanto il riscatto di un re.",
}
T[4766] = {
  title = "Mayara Brightwing",
  desc = "Ho un'agente, Mayara Brightwing, che è stata mandata nelle Burning Steppes a esplorare la città in rovina di Thaurissan. Fra le macerie di quella città dei nani Dark Iron potrebbero nascondersi oggetti di grande valore... oggetti che starebbero benissimo nel nostro museo di famiglia.$B$BMayara dice di aver trovato qualcosa e che le servirà aiuto per recuperarlo, solo che non si trova a Thaurissan: ci vorrà invece una spedizione in Blackrock Spire.$B$BI dettagli non li conosco, ma se sei $Ginteressato:interessata;, va' a parlare con Mayara nelle Burning Steppes.",
  obj = "Parla con Mayara Brightwing in Burning Steppes.",
  reward = "Vieni da Stormwind? Magnifico — conosco un'opera d'arte che Remington ucciderebbe pur di avere nel suo museo, ma tirarla fuori non sarà facile.$B$BE qui entri in gioco tu.",
}
T[4767] = {
  title = "Wind Rider",
  desc = "Mi hanno affidato il compito di trovare nuove viverne per i maestri cavalieri del vento. Sono sempre di più, e un giorno spero di diventare anch'io un cavaliere del vento. Ma non riusciamo ad addestrare viverne a sufficienza per stare dietro alle richieste. Forse puoi aiutarmi tu, $N.$B$BVorrei che andassi a Highperch a raccogliere uova di viverna. Da qui, segui le pareti del canyon verso nord-ovest, fino a una rampa che porta a Highperch. Fai attenzione, perché le viverne proteggono molto le loro uova e con gli intrusi non saranno tenere.",
  obj = "Porta 10 Highperch Wyvern Eggs a Elu a Freewind Post.",
  progress = "$N, hai trovato le uova di viverna che cerco? Non vedo proprio l'ora di cominciare l'addestramento da cavaliere del vento!",
  reward = "Perfetto! Con queste uova, spero, farò il prossimo passo per diventare un cavaliere del vento. Ecco un segno della mia gratitudine; e che una buona caccia risplenda sempre su di te, $C.",
  en_title = "Wind Rider",
  en_obj = "Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post.",
}
T[4768] = {
  title = "La Darkstone Tablet",
  desc = "La Darkstone Tablet raccoglie gli scritti di Urheld Darkstone, un nano morto da tempo. Era un alchimista di grande abilità, ma i suoi contemporanei lo ritenevano pazzo, e per questo le sue ricerche le ha tenute per sé.$B$BMa le ha incise su alcune tavolette, e credo che una si trovi in Blackrock Spire, in una stanza che un tempo si chiamava Hall of Fortune. Come si chiami oggi non lo so: sono pochi quelli che entrano a Blackrock e ne tornano.$B$BMa se sei $Gdisposto:disposta; ad affrontarne i pericoli e a riportarmi la tavoletta, ti aspetta una grande ricompensa.",
  obj = "Porta la Darkstone Tablet a Shadow Mage Vivian Lagrave a Kargath.",
  progress = "Hai trovato la Tavoletta, $N? Desidero ardentemente scoprirne i segreti.",
  reward = "Eccellente. Per studiare le formule incise su questa tavoletta ci vorranno giorni, ma sono certa che il lavoro darà dolci frutti.$B$BGrazie, $N. Ci sei $Gstato:stata; di un aiuto inestimabile.",
}
T[4769] = {
  title = "Vivian Lagrave e la Darkstone Tablet",
  desc = "Vivian Lagrave mi ha scritto da Kargath, nelle Badlands. I suoi studi le fanno credere che dentro Blackrock Spire ci sia un testo antico che gioverebbe alle nostre ricerche. Per averne la conferma le servirà qualcuno che porti via il testo dalla guglia, e non è un compito facile.$B$BSe ti interessa, va' a parlare con Vivian a Kargath.",
  obj = "Parla con Shadowmage Vivian Lagrave.",
  reward = "È vero. Credo che dentro Blackrock Spire sia custodita una tavoletta con antiche ricette alchemiche, e sono lieta di vederti qui, perché per recuperarla mi serve aiuto.$B$BMettiti $Gcomodo:comoda; e ti spiego meglio.",
}
T[4770] = {
  title = "Verso Casa",
  desc = "Ti prego, aiutami, $C! È da un po' che mi nascondo qui a Highperch, e sono giorni che non vedo un volto amico. Ero venuto a studiare la viverna, ma credo di essermi avvicinato un po' troppo: mi hanno cacciato da uno dei nidi e mi sono perso.$B$BDevo tornare al Whitereach Post! Motega non sa che sono sparito, e quando scoprirà che mi sono avventurato da solo a Highperch sarà furioso.$B$BIl Whitereach Post è appena a est di qui... ti prego, portami là!",
  obj = "Scorta Pao'ka Swiftmountain fuori da Highperch, poi parla con Motega Firemane a Whitereach Post.",
  reward = "Cosa!? Se avessi saputo che Pao'ka Swiftmountain andava a ficcare il naso per Highperch, l'avrei incatenato a un totem! Suo padre era poco convinto di lasciarlo venire con me a Thousand Needles. Siamo venuti qui a studiare le varie creature che vivono in queste belle terre.$B$BTi ringrazio di aver aiutato Pao'ka. Spero che questo ti ripaghi di qualunque sventura ti sia costata l'impresa.",
  en_title = "Homeward Bound",
  en_obj = "Escort Pao'ka Swiftmountain from Highperch, and then talk to Motega Firemane in Whitereach Post.",
}
T[4771] = {
  title = "Dawn's Gambit",
  desc = "Ho messo la Dawn's Gambit nel contenitore che ci hai portato, quello delle uova di drago. Adesso tocca a te portarla nel profondo della Scholomance.$B$BIl mago non morto Vectus guida un gruppo di studiosi del flagello... metti la Dawn's Gambit nella loro stanza, quella che chiamano la \"sala di osservazione\". Reagirà con i non morti che si trovano lì e, con un po' di fortuna, li distruggerà!$B$BDopo, battere Vectus non dovrebbe essere un problema. Giusto?",
  obj = "Metti la Dawn's Gambit in Viewing Room of the Scholomance. Sconfiggi Vectus, poi torna da Betina Bigglezink.",
  progress = "Ricorda, $N — dobbiamo essere tolleranti, ma rigidi nelle nostre convinzioni!",
  reward = "Ce l'hai fatta! Vectus è sconfitto! E la Dawn's Gambit... ha funzionato?$B$BUhm... forse il congegno non è andato bene come speravo, ma sono contenta che tu sia $Griuscito:riuscita; a cavartela lo stesso. Ben fatto, $N!$B$BThe Argent Dawn e la brava gente di Azeroth ti devono molto.",
}
T[4781] = {
  title = "Componenti per l'Enchanted Gold Bloodrobe",
  desc = "Il prossimo compito è semplice come il primo, ma dovrai farti aiutare.$B$BPer il ricamo della cappa mi serve del filo dorato, che non è facile da trovare e che pochissimi sanno fare. Per fortuna un fedele della nostra causa ne conosce i segreti, ed è disposto ad aiutare chi si fa strada nelle nostre file.$B$BPorta un gold bar a Xizk Goodstitch, a Booty Bay: è un maestro sarto e sarà felice di filarti il filo. I Gold bars li fondono i minatori esperti, quindi chiedi aiuto a un minatore.",
  obj = "Porta un Gold Bar a Xizk Goodstitch in Stranglethorn Vale.",
  progress = "I Gold bars, sì... sì. Portamene uno e vedremo cosa si può fare per filarti un po' di filo. Intanto ti consiglio di pensare a diventare più potente: le prove più dure devono ancora arrivare. E fidati... per quanto potente tu creda di essere, rimpiangerai di non esserti $Gpreparato:preparata; meglio.",
  reward = "Perfetto, $N. Sono contento che tu abbia trovato così in fretta un minatore che ti aiutasse. O hai fatto tutto da $Gsolo:sola;? In ogni caso, bel lavoro: per il filo questo andrà benissimo.$B$BCi vorrà un po' per fare quella roba, quindi dovrai tornare — a dire il vero la mando a una principessa che teniamo rinchiusa in una torre e che non ha altro compito che filare filo d'oro... no, sul serio. Dico davvero... va bene, non proprio.",
}
T[4782] = {
  title = "Componenti per l'Enchanted Gold Bloodrobe",
  desc = "Torna da Menara e dille che ci vorrà un po', ma che farò in modo di non deluderla... né te. Dille di farti finire di raccogliere gli altri componenti: per allora il filo dovrebbe essere pronto, e potrai tornare a prenderlo.$B$BBuona fortuna, $N. Ah, e quando sei lì salutami Strahad. Quel vecchio matto... piazzare una torre proprio lì accanto a Ratchet... che pazzia.",
  obj = "Torna da Menara Voidrender in Barrens.",
  reward = "Bene, sei $Gtornato:tornata;, $N. E il filo?$B$BAh, capisco. Accettabile. Il goblin e suo fratello finora non ci hanno mai deluso — immagino sia comprensibile che non l'avesse pronto subito. E sia... intanto abbiamo altro di cui occuparci.$B$BSei $Gpronto:pronta; per il prossimo passo?",
}
T[4783] = {
  title = "Componenti per l'Enchanted Gold Bloodrobe",
  desc = "I prossimi componenti si trovano a Desolace, molto a ovest dei Barrens e perfino delle Stonetalon Mountains.$B$BLì il caos regna ancora, dai tempi della Frattura. Sarà una prova per la tua forza e per la tua astuzia — affronterai creature d'odio e altre della Burning Legion.$B$BPortami il sangue dei satiri Hatefury, a nordest, e procurami una lesser infernal stone dai lesser infernals della Mannoroc Coven.$B$BUseremo entrambe le cose per costruire la tua tonaca.",
  obj = "Porta 10 Vials of Hatefury Blood e 1 Lesser Infernal Stone a Menara Voidrender in Barrens.",
  progress = "Desolace non è un posto ospitale: naga, giganti, satiri, la Burning Legion... tutti questi, insieme ai clan di centauri in guerra, rendono la regione pericolosa per chi non sta attento.$B$BCome ti ho detto, metterà alla prova non solo la tua forza e la tua astuzia, ma anche la tua pazienza. Sii prudente in quelle terre, $N.",
  reward = "Eccellente, $N. Andranno benissimo. Li preparo subito, mentre tu passi agli ultimi due componenti. Sei $Gpronto:pronta;?",
}
T[4784] = {
  title = "Componenti per l'Enchanted Gold Bloodrobe",
  desc = "Ora mi servono solo tre cose, $N, e poi potremo finire la tua tonaca.$B$BPrima di tutto, il fine gold thread che Xizk sta preparando per te: torna da lui a Booty Bay e prendilo.$B$BPoi portami due smoldering coals dagli elementali del fuoco negli Arathi Highlands. Se ricordo bene, stanno a ovest, vicino al Thoradin's Wall.$B$BInfine, un soul shard creato da te.$B$BQuando avrai tutti i componenti, torna qui alla torre e completerò la tonaca per te.",
  obj = "Porta del Fine Gold Thread, 2 Smoldering Coals e un Soul Shard a Menara Voidrender in Barrens.",
  progress = "Presto, $N, te lo prometto. La tonaca sarà più che adatta alle tue necessità e di sicuro ti darà un vantaggio sugli avversari.",
  reward = "Eccellente, $N! Abbiamo raccolto i componenti e siamo $Gpronti:pronte;.$B$BConfido che ne sarai $Gsoddisfatto:soddisfatta;.",
}
T[4785] = {
  title = "Fine Gold Thread",
  reward = "Ecco qua, $N. E salutaci Menara, per favore.$B$BCi aspettiamo grandi cose da te. Forse, quando la Legione cadrà in ginocchio, si dirà il tuo nome ad alta voce per lodare il tuo potere. Non vedo l'ora!",
}
T[4786] = {
  title = "La Tonaca Completata",
  desc = "Ora ti assemblo la tonaca. Ci vorrà solo qualche istante: non allontanarti.",
  obj = "Aspetta che Menara Voidrender completi la tua tonaca e poi parlale di nuovo.",
  progress = "Un momento, $N...",
  reward = "È fatta, $N. Eccola, indossala con orgoglio.$B$BHai lavorato sodo e nel tuo futuro vedo grandi cose. Ricorda: per resistere alla corruzione che accompagna il nostro cammino ci vogliono grande volontà e forza d'animo. Finché la tua volontà resterà tua, avrai grande successo.",
}
T[4787] = {
  title = "L'Ancient Egg",
  desc = "La Profezia di Mosh'aru parla di un ancient egg, una reliquia dei tempi in cui i troll governavano vasti imperi. Ha il potere di contenere l'essenza di Hakkar, e potrebbe essere l'unico modo per proteggere il nostro mondo dalla sua malvagità.$B$BPortami l'ancient egg, $N. Si dice che stia nascosto nelle profondità di Jintha'Alor, nelle Hinterlands, in una grotta dietro l'anfiteatro, in cima alla città.",
  obj = "Porta l'Ancient Egg a Yeh'kinya a Tanaris.",
  progress = "Ce l'hai l'ancient egg? Sento agitarsi grandi forze, e temo che il tempo stringa.",
  reward = "Ah, ce l'hai l'uovo! Mi inchino a te, $N. Si ricorderanno a lungo della tua forza e del tuo coraggio.",
}
T[4788] = {
  title = "Le Ultime Tavolette",
  desc = "Io intanto esamino la terza e la quarta tavoletta di Mosh'aru, e tu devi trovare la quinta e la sesta! Non sarà facile: ce le hanno i troll Smolderthorn, dentro Blackrock Spire. Il picco è un'oscura montagna di fuoco fra le Burning Steppes e la Searing Gorge.$B$BBuona fortuna, $N. Blackrock Spire non è posto per gente perbene...",
  obj = "Porta le Fifth e Sixth Mosh'aru Tablets a Prospector Ironboot a Tanaris.",
  progress = "Allora, $N, sei $Gstato:stata; al picco? Ce le hai la quinta e la sesta tavoletta?",
  reward = "Incredibile! Le hai trovate! Sei $Gun vero eroe:una vera eroina;, $N!$B$BEd è una fortuna, perché ho letto le tavolette che mi avevi portato e, da quel che ho capito... per fermare quello che sta arrivando ci servirà un eroe...",
}
T[4801] = {
  title = "Frostsaber E'ko",
  progress = "A Winterspring combatterai dei grandi felini, i frostsabers: 'ste bestie sono veloci e furbe da non credere. Vuoi la velocità del frostsaber? Allora portami gli E'ko che trovi addosso a loro.$B$BE ricordati: se vuoi andare a caccia di E'ko, la Cache of Mau'ari devi averla nell'inventario.",
  reward = "Per $N, Mau'ari il juju lo può tirar fuori... Usa la Cache of Mau'ari e lancialo su di te o sui tuoi alleati.",
}
T[4802] = {
  title = "Winterfall E'ko",
  progress = "A Winterspring combatterai i furbolg Winterfall, creature fuorviate. Il loro capo ha voluto così, e adesso sono forti da non credere. Vuoi il potere dei Winterfall? Allora portami gli E'ko che trovi addosso a loro.$B$BE ricordati: se vuoi andare a caccia di E'ko, la Cache of Mau'ari devi averla nell'inventario.",
  reward = "Per $N, Mau'ari il juju lo può tirar fuori... Usa la Cache of Mau'ari e lancialo su di te o sui tuoi alleati.",
}
T[4803] = {
  title = "Shardtooth E'ko",
  progress = "A Winterspring troverai dei grossi orsi dalla pelle spessissima. 'Sti Shardtooth bears, con tutto quello che riescono a sopportare, ci ricavano un sacco di protezione. Vuoi la resistenza al fuoco? Allora portami gli E'ko che trovi sugli Shardtooth.$B$BE ricordati: se vuoi andare a caccia di E'ko, la Cache of Mau'ari devi averla nell'inventario.",
  reward = "Per $N, Mau'ari il juju lo può tirar fuori... Usa la Cache of Mau'ari e lancialo su di te o sui tuoi alleati.",
}
T[4804] = {
  title = "Chillwind E'ko",
  progress = "A Winterspring combatterai delle grandi creature volanti, i Chillwind: 'ste bestie hanno il potere di usare la magia del gelo. Vuoi resistere al gelo? Allora portami gli E'ko che trovi sui Chillwind.$B$BE ricordati: se vuoi andare a caccia di E'ko, la Cache of Mau'ari devi averla nell'inventario.",
  reward = "Per $N, Mau'ari il juju lo può tirar fuori... Usa la Cache of Mau'ari e lancialo su di te o sui tuoi alleati.",
}
T[4805] = {
  title = "Ice Thistle E'ko",
  progress = "A Winterspring combatterai delle grandi creature, gli ice thistle yeti. 'Ste bestie sono lente, ma con la pelliccia folta che le protegge evitano un sacco di colpi. Vuoi saper schivare gli attacchi? Allora portami gli E'ko che trovi addosso a loro.$B$BE ricordati: se vuoi andare a caccia di E'ko, la Cache of Mau'ari devi averla nell'inventario.",
  reward = "Per $N, Mau'ari il juju lo può tirar fuori... Usa la Cache of Mau'ari e lancialo su di te o sui tuoi alleati.",
}
T[4806] = {
  title = "Frostmaul E'ko",
  progress = "A Winterspring li hai combattuti, i grossi ice giants che chiamano frostmaul. Loro ce l'hanno, la potenza e la forza pura. Se vuoi prende' la forza dei frostmaul, porta a me gli E'ko che trovi addosso a loro.$B$BE ricorda, se vuoi anda' a caccia di E'ko devi ave' la Cache of Mau'ari nell'inventario.",
  reward = "Per $N Mau'ari può tira' fuori il juju... Usa la Cache of Mau'ari per lancia' questo addosso a te o ai tuoi alleati.",
}
T[4807] = {
  title = "Wildkin E'ko",
  progress = "A Winterspring ti toccherà combatte' creature potenti, che la magia sembrano avercela dentro dalla nascita. Le magie forti, questi wildkin le sanno usa'. Se vuoi fa' cresce' l'intelletto, porta a me gli E'ko che trovi su qualunque bestia-gufo di là.$B$BE ricorda, se vuoi anda' a caccia di E'ko devi ave' la Cache of Mau'ari nell'inventario.",
  reward = "Per $N Mau'ari può tira' fuori il juju... Usa la Cache of Mau'ari per lancia' questo addosso a te o ai tuoi alleati.",
}
T[4808] = {
  title = "Felnok Steelspring",
  desc = "Devo chiederti un altro favore.$B$BDai primi studi sull'essenza che hai raccolto, sembra che le uova dei cuccioli di drago si possano congelare e conservare! Voglio mettere alla prova la teoria, ma prima mi servono dei componenti di ingegneria fatti su misura, e può costruirli il mio collega Felnok Steelspring.$B$BEcco, porta questa lettera a Felnok: gli spiega cosa mi serve. Felnok lo trovi a Winterspring, nella città di Everlook.",
  obj = "Consegna la Tinkee's Letter a Felnok Steelspring.",
  progress = "Che freddo quassù! Mi hai portato una coperta, spero!",
  reward = "Questa non è una coperta! E questa cos'è? Una lettera di Tinkee? Chissà cosa racconta...$B$BAh, studia nelle Burning Steppes. Logico — è il posto giusto per trovare draconidi. Oh, ma guarda! Dice che le servono dei pezzi per un congegno che vuole costruire. E qui entro in gioco io, immagino, eh?",
}
T[4809] = {
  title = "Corni di Chillwind",
  desc = "Per Tinkee ho quasi tutto, ma manca un componente importante: i corni di chillwind. Quelli della chillwind chimaera di Winterspring racchiudono un freddo concentrato, ma vanno bene solo se sono perfetti e intatti! Per completare l'ordine di Tinkee me ne serve una scorta.$B$BPortami gli uncracked chillwind horns e io preparo una cassa per Tinkee.",
  obj = "Porta 8 Uncracked Chillwind Horns a Felnok Steelspring.",
  progress = "Ce li hai, i corni di chillwind, $N?",
  reward = "Begli esemplari. Pieni di freddo! Aspetta che mi metta i guanti, poi li imballo con le altre cose che servono a Tinkee...",
}
T[4810] = {
  title = "Ritorno da Tinkee",
  desc = "Bene, è tutto preparato e imballato, pronto da portare via! Buon viaggio, e ricordati di dire a Tinkee che mi deve un favore!",
  obj = "Porta la Felnok's Package a Tinkee Steamboil in Burning Steppes.",
  progress = "$N! Hai parlato con Felnok? Ce li hai, i componenti che mi servono?",
  reward = "Ce li hai! Fantastico! Mi metto subito al lavoro! Grazie mille, $N!$B$BMi sei $Gstato:stata; di grande aiuto, e in futuro potrei aver bisogno di te per compiti ancora più importanti...",
}
T[4821] = {
  title = "Alien Egg",
  desc = "Gira voce che qui a Thousand Needles ci sia un alien egg. Chi dice di averlo visto non è riuscito nemmeno ad avvicinarsi abbastanza da esaminarlo bene: i serpenti lo custodiscono come se fosse uno dei loro.$B$BVoglio che tu vada a cercare quest'alien egg e me lo porti, così potrò studiarlo. Secondo i rapporti si trova in una tana di serpenti, ma di tane ce ne sono diverse ai piedi delle pareti rocciose, a sud e a nord-est del Freewind Post.",
  obj = "Riporta l'Alien Egg a Hagar Lightninghoof a Freewind Post.",
  progress = "Devo saperne di più su quest'uovo misterioso, chissà cosa ne uscirà.",
  reward = "Sì, finalmente... mi hanno portato l'uovo misterioso. Ora vediamolo più da vicino... Cosa..! Cos'è questo..?",
  en_title = "Alien Egg",
  en_obj = "Return the Alien Egg to Hagar Lightninghoof in Freewind Post.",
}
T[4822] = {
  title = "Io Gelo, Tu Geli...",
  desc = "GELATO! Oh ti prego ti prego ti prego, mi prendi un po' di gelato?! Il mio gusto preferito è la fragola, e al mondo non c'è gelato alla fragola più buono del Gelato alla Fragola di Tigule e Foror! È il gelato che mi piace di più in tutto il mondo!$B$BL'ho mangiato una volta, tanto tempo fa, quando ero alla pista da corsa delle Shimmering Flats, ma ho sentito che forse adesso lo vendono anche in città! Per favore? Dai, ti prego? Con sopra il Gelato alla Fragola di Tigule e Foror??!?!",
  obj = "Procura un po' di Gelato alla Fragola per il tuo pupillo. Il ragazzino sembra preferire il gelato della marca di Tigule e Foror.",
  progress = "Vorrei che facessero anche altri gusti oltre alla fragola, ma per fortuna la fragola è proprio quello che preferisco!",
  reward = "Mmmmmmmmm! Il loro gelato alla fragola lo adoro! Se c'è una cosa che Tigule sa fare, è il gelato!$B$BGrazie mille, $N — è la cosa più buona di sempre!",
  en_title = "You Scream, I Scream...",
  en_obj = "Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream.",
}
T[4841] = {
  title = "Pacifica i Centauri",
  desc = "$N, ti supplico, dai la caccia a questi centauri: sentiranno la furia della nostra vendetta. Attacca il loro accampamento a nord di Freewind Post! Che la furia guidi la tua mano!",
  obj = "Uccidi 12 Galak Scouts, 10 Galak Wranglers e 6 Galak Windchasers, poi torna da Cliffwatcher Longhorn a Freewind Post.",
  progress = "Suvvia, $N, lo so che non ne hai ancora uccisi abbastanza. Dagli la caccia e, in segno di gratitudine, ti ricompenserò.",
  reward = "Questo è per te, $N, in segno di gratitudine.",
  en_title = "Pacify the Centaur",
  en_obj = "Kill 12 Galak Scouts, 10 Galak Wranglers, and 6 Galak Windchasers, and then return to Cliffwatcher Longhorn in Freewind Post.",
}
T[4842] = {
  title = "Strane Fonti",
  desc = "A dire il vero, qui a Winterspring vulcani non ce ne sono, ma credo che dietro queste sorgenti termali ci siano ragioni molto più minacciose...$B$BBe', immagino che vorrai vederlo con i tuoi occhi. Dovrai attraversare Winterspring da un capo all'altro e scendere fino all'estremo sud. Quando l'aria si farà densa e afosa e il cielo si scurirà, avrai trovato quella che secondo me è la fonte delle sorgenti termali.$B$BDai un'occhiata. Quando tornerai, sono sicura che avrai molte domande.",
  obj = "Segui le istruzioni di Donova Snowden, poi torna a fare rapporto.",
  progress = "L'acqua delle sorgenti pare avere proprietà molto strane... Cosa voglia dire, ancora non lo so con certezza...",
  reward = "Sì, i demoni laggiù nella Darkwhisper Gorge; credo sia la loro presenza a influire così sulla terra. Io continuerò a tenere d'occhio le sorgenti termali qui e vedrò se scopro qualcos'altro.$B$BSe pensi di spingerti più a fondo nella Darkwhisper Gorge, al posto tuo aspetterei di essere un po' più forte.",
}
T[4861] = {
  title = "Gufaltri Infuriati",
  desc = "Ehi, $Gragazzo:ragazza;! Dei gufaltri assetati di sangue mi hanno buttato fuori dal mio campo nel sud di Winterspring! Be', credo di essermi avvicinato troppo a qualcosa che sorvegliavano.$B$BMe la sono cavata per un pelo, e temo che un mio amico non abbia avuto la stessa fortuna. Te la sentiresti di sfidare i gufaltri e arrivare fino al campo? Mi servono i rifornimenti, e vorrei riavere anche l'amuleto che ieri ho dissotterrato allo scavo.",
  obj = "Trova il campo distrutto e i rifornimenti di Jaron Stoneshaper nella parte meridionale di Winterspring.",
  reward = "Fra le altre cose distrutte al campo spicca una cassa gravemente danneggiata...",
}
T[4862] = {
  title = "Ci-A-Ti-Ti-I-Vu-O",
  desc = "Che tu ci creda o no, là fuori c'è gente disposta a pagare anche per la più schifosa delle bestie addomesticate!$B$BAvevo mandato Bijou nello Spire a provare a raccogliere un po' di quelle spire spider eggs, ma sono settimane che non ho sue notizie. Magari puoi darmi una mano tu?$B$BFacciamo così, $N. Va' a Blackrock Spire e raccoglimi un po' di spire spider eggs. Portamele qui e non solo ti darò qualche soldo, ma ti addomesticherò perfino un ragno!",
  obj = "Recati a Blackrock Spire e raccogli 15 Spire Spider Eggs per Kibler.$B$BA quanto pare, queste uova si potrebbero trovare vicino ai ragni.",
  progress = "Quelle nella borsa sono uova di ragno o sei solo $Gcontento:contenta; di vedermi?",
  reward = "Che carico! Voglio dire, guarda quante uova! Dovrebbero valere un bel po' d'oro.$B$BCome promesso, ecco la tua bestiolina. Non farti mordere!",
}
T[4863] = {
  title = "Gufaltri Infuriati",
  desc = "Ti guardi intorno, ma non vedi granché che possa interessare a Jaron. Noti però che la cassa che hai trovato è stata sfondata, quasi come se i gufaltri cercassero proprio quella...$B$BA est scorgi a fatica un carro abbandonato. Forse lì troverai le cose di Jaron: vale la pena dare un'occhiata.",
  obj = "Trova il carro distrutto di Jaron Stoneshaper.",
  reward = "Mentre ti avvicini al carro, ti pare che qui non ci sia granché d'altro per Jaron. Abbassando lo sguardo, però, noti a terra alcune casse mezzo sepolte nella neve, che sembrano intatte.",
}
T[4864] = {
  title = "Gufaltri Infuriati",
  desc = "Esamini il contenuto della cassa e decidi che gli attrezzi e gli altri oggetti che ci sono dentro potrebbero servire a Jaron. Dell'amuleto, però, nessuna traccia.$B$BPare che i gufaltri vivano nelle terre a nord e a est di qui: stabilisci quindi che il prossimo passo è affrontare quelle creature e riprendere loro l'amuleto.",
  obj = "Raccogli i Jaron's Supplies dalla neve, poi trova i gufaltri che hanno rubato l'amuleto di cui ha parlato Jaron.$B$BPorta i Jaron's Supplies e il Blue-feathered Amulet a Jaron Stoneshaper, al rifugio di Winterspring.",
  progress = "Sì... Sentiamo, che novità ci sono?",
  reward = "Be', me lo aspettavo, $Gragazzo:ragazza;. Me l'immaginavo che quelle bestie impazzite avessero distrutto tutta la mia roba...$B$BMa hai trovato i miei attrezzi e, soprattutto, l'amuleto! Chissà perché i gufaltri difendevano con tanta ferocia questo oggetto... Comunque sia, prima di tornare dalle loro parti ci penserò due volte!",
}
T[4865] = {
  title = "Serpente Selvaggio",
  desc = "Non ci avrei mai creduto, se non l'avessi visto con i miei occhi. La vendetta è giunta a Thousand Needles!$B$B<Hagar si asciuga la fronte.>$B$B$N, devi fare presto! Va' subito a cercare Motega Firemane: è al Whitereach Post, lungo la strada, appena a nord-ovest di Freewind Post. Lui saprà cosa fare!",
  obj = "Riferisci quello che hai scoperto a Motega Firemane.",
  reward = "Vendetta! Dunque la leggenda di Arikara è vera. E in effetti è un problema da risolvere subito.",
  en_title = "Serpent Wild",
  en_obj = "Report your findings to Motega Firemane.",
}
T[4866] = {
  title = "Latte di Madre",
  desc = "Dev'essere uno dei veleni più potenti al mondo, $R!$B$BDurante le mie capatine ai Bastioni ho sentito per caso i Blackrock che parlavano di quanto è letale. Lo chiamano 'Latte di Madre', dal nome di Mother Smolderweb, quel grosso ragno schifoso nella grotta di Skitterweb.$B$BEcco cosa ti chiedo: un campione vivo del Latte, che scorra nelle TUE vene. Non basta che mi porti la ghiandola! Fatti avvelenare da lei e torna da me!$B$BPoi... ti mungo io!$B$B<Si sfrega le mani, pregustando il momento.>",
  obj = "Nel cuore di Blackrock Spire troverai Mother Smolderweb. Affrontala e fatti avvelenare. È probabile che dovrai anche ucciderla. Torna da Ragged John quando sarai $Gavvelenato:avvelenata;, così potrà 'mungerti'.",
  progress = "<Ragged John ti dà un pizzicotto.>",
  reward = "Con questo ci viene fuori la birra migliore di sempre!$B$BEh, a cosa credevi che mi servisse? Per un veleno o roba del genere??$B$BRagazzi matti...",
}
T[4867] = {
  title = "Urok Doomhowl",
  desc = "Argh! Che fatica parlare!$B$BPrendi questo biglietto! Portami il mio mojo!",
  obj = "Leggi la Warosh's Scroll. Porta il Warosh's Mojo a Warosh.",
  progress = "Ah! Ce l'hai, il mio mojo?",
  reward = "Aha! Sento già i miei poteri che tornano. E la maledizione di Urok non mi tormenta più la mente.$B$BGrazie, $N! L'umiltà è indegna di me, ma il tuo aiuto devo riconoscerlo.$B$BE ti auguro fortuna nei tuoi viaggi per il Blackrock Spire. Sei $Gun pazzo:una pazza; se pensi di arrivare fino in cima, ma sul tuo coraggio non si discute.",
}
T[4881] = {
  title = "Complotto per un Assassinio",
  desc = "Il Tauren Kanati Greycloud ha l'audacia di piantare un accampamento di caccia a Thousand Needles. Va ucciso: così ci liberiamo dell'accampamento e di chiunque potrebbe venirgli dietro. Ci ritroveremo al piccolo accampamento a Sudovest del Great Lift.",
  obj = "Avverti Kanati Greycloud a Whitereach Post del complotto per ucciderlo.",
  reward = "Vengono a uccidermi? Gli farò vedere io come combatte un Tauren!",
  en_title = "Assassination Plot",
  en_obj = "Warn Kanati Greycloud at Whitereach Post of the plot to kill him.",
}
T[4882] = {
  title = "Custodire i Segreti",
  desc = "Non sei $Gsicuro:sicura; di quanto sia importante la collana caduta dal collo del gufo selvatico appena ucciso. Brilla intensamente, e intanto si affievolisce e si riaccende piano.$B$BTrull Failbane, che sembra conoscere a fondo i gufi selvatici, potrebbe saperne di più: forse dovresti chiedere a lui.",
  obj = "Porta la Blue-feathered Necklace a Trull Failbane a Bloodvenom Post.",
  progress = "Sei qui per un altro incarico?",
  reward = "Hai fatto una scoperta importante?",
}
T[4883] = {
  title = "Custodire i Segreti",
  desc = "So molto delle gufobestie che hai sconfitto a Winterspring, ma delle magie che usano non me ne intendo granché. Credo però di conoscere qualcuno che potrebbe esaminare la collana e, molto probabilmente, dirti di cosa si tratta.$B$BVa' da Nara Wildmane, a Thunder Bluff: in questo campo è un'esperta. Buona fortuna, $N.",
  obj = "Porta la Blue-feathered Necklace a Nara Wildmane.",
  progress = "Che cosa posso fare per te, $N?",
  reward = "L'energia di questa collana, $N. Credo che venga da una fonte sola.$B$B<Nara chiude gli occhi e resta in silenzio per un momento.>$B$BOra i gufi selvatici sono fuorviati e confusi, ma non sono sempre stati così. Un tempo avevano uno scopo ed erano guidati a servire. Elune, la dea degli elfi della notte, ha creato queste creature perché sorvegliassero i suoi luoghi più sacri.$B$BPuò sembrare un fatto di poco conto; eppure ti esorto a guardare più a fondo.$B$BCol tempo imparerai. Grazie per avermela portata, $N.",
}
T[4901] = {
  title = "I Guardiani dell'Altare",
  desc = "In cima alla cresta c'è quello che credo sia un altare della dea Elune. Per quanto riesco a capire, dobbiamo accendere le cinque torce in ogni grotta: solo allora potremo arrivare dritti all'altare.$B$BFra le antiche rovine di Kel'Theril ho trascritto alcune formule incise nella pietra, e credo che siano il segreto per sbloccare l'altare. Mentre recito l'incantesimo, avrò bisogno che tu accenda ogni torcia.$B$BSe ci riusciremo, potrai riferire a Erelas quello che abbiamo scoperto!",
  obj = "Proteggi Ranshalla mentre tenta di riattivare l'Altare di Elune. Riferisci le tue scoperte a Erelas Ambersky a Rut'theran Village.",
  reward = "Hai incontrato Ranshalla?",
}
T[4902] = {
  title = "Wildkin di Elune",
  desc = "Affascinante!$B$BMi sono sempre chiesto quale fosse la verità... Be', devi assolutamente far conoscere questa scoperta! Va' subito da Arch Druid Fandral Staghelm — lo troverai a Darnassus, nel Cenarion Circle. Spiegagli cos'è successo, proprio come l'hai raccontato a me. Sono sicuro che gli interesserà altrettanto!$B$BÈ un'informazione importante, $N!",
  obj = "Parla con Arch Druid Fandral Staghelm a Darnassus.",
  reward = "Non esitare: dimmi perché sei $Gvenuto:venuta;.$B$BAh, sì? Mmm. Be'.$B$BGrazie per averlo riferito direttamente a me; è sempre meglio rivolgersi ai vertici... Però... Sì. I druidi del Cenarion Circle conoscono i Wildkin da tempo. Sanno che sono animali prediletti di Elune, scelti per custodire i luoghi più sacri.$B$BPerciò, anche se non è una novità, ti faccio senz'altro i complimenti per l'impegno. Ecco, prendi questo — mi sembra una ricompensa adatta a un'impresa simile.",
}
T[4903] = {
  title = "L'Ordine del Signore della Guerra",
  desc = "Per ordine di Warlord Goretooth, questi abitanti di Blackrock Spire vanno distrutti:$B$BHighlord Omokk, la minaccia panciuta.$B$BWar Master Voone, troll crudele e spietato.$B$BOverlord Wyrmthalak, sorvegliante della città minore.$B$BDovrai anche riportare gli eventuali documenti importanti che troverai.$B$BSe riuscirai, sarai $Gonorato:onorata;.$B$BSe fallirai, sarai $Gdimenticato:dimenticata;.",
  obj = "Uccidi Highlord Omokk, War Master Voone e Overlord Wyrmthalak. Recupera gli Important Blackrock Documents. Torna da Warlord Goretooth a Kargath quando avrai compiuto la missione.",
  progress = "<Warlord Goretooth fa il saluto.>",
  reward = "<Per un attimo, la pelle verde spento di Warlord Goretooth si fa di un bianco smorto.>",
}
T[4904] = {
  title = "Finalmente Libera",
  desc = "Arnak è convinto che ci sposeremo... ma io ho rifiutato la sua proposta, e quella notte stessa è tornato a rapirmi. Mio fratello ha provato a fermarlo, ma Arnak era troppo forte. Lui... l'ha ucciso, e poi mi ha portata qui. Povero fratello mio...$B$B$N, potresti scortarmi fuori dal Darkcloud Pinnacle? Ti prego... devo tornare da Thalia! Sarà preoccupata da morire.",
  obj = "Scorta Lakota Windsong fuori da Darkcloud Pinnacle, poi parla con Thalia Amberhide a Freewind Post.",
  progress = "Thalia Amberhide:",
  reward = "Grazie, $N. Me lo sentivo fin nelle ossa che avrebbe ritrovato la strada per tornare da me. Mi ha raccontato quanto sei $Gstato coraggioso:stata coraggiosa; e come l'hai aiutata a fuggire. Questi oggetti erano di suo fratello. So che vorrebbe che li avessi tu.",
  en_title = "Free at Last",
  en_obj = "Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post.",
}
T[4906] = {
  title = "Ulteriore Corruzione",
  desc = "Più a nord c'è un secondo accampamento di satiri, guidato dal crudele Xavaric, che minaccia la terra di Felwood. Questi vili traditori e ingannatori si nutrono della corruzione delle creature indigene di Felwood.$B$BXavathras e i suoi servitori erano solo una parte di un piano più grande — coltivare un pozzo lunare corrotto e poi consegnarne i frutti a Xavaric.$B$BOra che Xavathras è fuori dai giochi, tocca a te finire il lavoro, $N. Dirigiti a nord e sconfiggi Xavaric.",
  obj = "Eridan Bluewind a Felwood vuole che tu uccida 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters e Xavaric. Torna da Eridan quando avrai completato il compito.",
  progress = "Ti prego, metti fine alla sofferenza delle creature di Felwood.",
  reward = "Grazie di tutto quello che hai fatto, $N. Che Elune ti protegga e ti guidi lungo il cammino che ti aspetta.",
}
T[4907] = {
  title = "Tinkee Steamboil",
  desc = "Ciao, $N. Ti ricordi di Tinkee Steamboil? Be', lei si ricorda di te! Mi ha mandato un messaggio per dirmi di tenere gli occhi aperti, caso mai ti vedessi, perché... le serve di nuovo il tuo aiuto. Credo che c'entrino i suoi studi sui draghi.$B$BDovresti andare a parlarle al Flame Crest, nelle Burning Steppes.",
  obj = "Parla con Tinkee Steamboil.",
  reward = "Felnok aveva ragione! Mi serve proprio di nuovo il tuo aiuto, e stavolta... sarà davvero pericoloso.$B$BSei $Gpronto:pronta;??",
}
T[4941] = {
  title = "La Saggezza di Eitrigg",
  desc = "Rend è vivo?$B$BImpossibile!$B$BSi credeva che Rend fosse stato ucciso decenni fa.$B$BVa' a cercare la saggezza di Eitrigg, $N. Nessuno sa meglio di lui come agiscono i Blackrock e, se quello che c'è scritto qui è vero, Eitrigg deve saperlo. Il diritto alla vendetta non andrebbe negato a nessuno.$B$BLo troverai a Orgrimmar.$B$BQuando avrai parlato con Eitrigg, rivolgiti al Capoguerra e chiedigli cosa vuole fare al riguardo.",
  obj = "Parla con Eitrigg a Orgrimmar. Dopo aver discusso la faccenda con Eitrigg, chiedi consiglio a Thrall.$B$BRicordi di aver visto Eitrigg nella sala di Thrall.",
  progress = "Non lo vedi che non devo essere interrotto?",
  reward = "<Thrall appare sgomento alla notizia che porti.>",
}
T[4961] = {
  title = "Purificazione del Globo di Orahil",
  desc = "Ah, il globo di un evocatore — la contaminazione deve venire da qui. Se vuoi usarlo, bisogna esorcizzare il demone che ci sta dentro, e questo per me è facile.$B$BLa parte difficile tocca a te: quando l'avrò liberato, dovrai uccidere il demone.$B$BE dovrai essere $Grapido:rapida;. Se ci metti troppo, tornerà nel globo e dovremo ricominciare da capo!$B$BQuindi preparati, $N. Tieni pronti gli incantesimi più potenti e a portata di mano le pozioni, e cercati un amico, se ne hai uno. Perché non sarà un bello spettacolo.",
  obj = "Uccidi il Demon of the Orb, poi parla con Tabetha.",
  progress = "Se vuoi liberare per sempre il globo dalla presenza di quel demone, dovrai ucciderlo, $N.",
  reward = "Ben fatto, $N! A quel demone hai dato una lezione che non dimenticherà tanto presto, e hai mostrato grande potere e grande abilità. Ora direi che è il momento di tornare da Menara con la sfera purificata, così potrai farne buon uso.$B$BBuona fortuna, $C. Forse le nostre strade si incroceranno ancora.",
}
T[4962] = {
  title = "Frammento di un Felhound",
  desc = "Dunque, hai scelto di catturare l'anima di un felhound. Bene.$B$BPrendi questo rubino — ti servirà a catturare l'anima della creatura. Non è molto diverso da incantesimi che conosci già: quando la creatura sta per morire usa la gemma, e al resto dovrebbe pensarci lei.$B$BIl mio consiglio è di andare a Desolace e metterti alla prova con uno qualsiasi dei felhounds che ci trovi. Dovrebbero andare benissimo.$B$BQuando ci sarai $Griuscito:riuscita;, porta a Menara lo spirito catturato e anche il rubino.",
  obj = "Prendi il Felhas Ruby e usalo su uno dei Felhounds che si trovano a Desolace. Una volta $Griuscito:riuscita;, riporta il Felhas Ruby e l'Imprisoned Felhound Spirit a Menara Voidrender in Barrens.",
  progress = "Sì, $N? Hai deciso? Un Infernal o un felhound?$B$BÈ una scelta personale, e dovrebbe rispecchiare i tuoi punti di forza e le tue debolezze. Capita che uno stregone preferisca rafforzare ancora di più le doti che ha, invece di colmare le lacune. A volte sopraffare il nemico è una tattica che funziona quanto diventare un incantatore più equilibrato.",
  reward = "Ah, lo spirito di un felhound. Ben fatto, $N.$B$BLi fonderò per te quando avrò sia lo spirito sia il globo purificato, ma non prima.",
}
T[4963] = {
  title = "Frammento di un Infernal",
  desc = "Dunque, hai scelto di catturare l'anima di un infernal. Bene.$B$BPrendi questo smeraldo — ti servirà a catturare l'anima della creatura. Non è molto diverso da incantesimi che conosci già: quando la creatura sta per morire usa la gemma, e al resto dovrebbe pensarci lei.$B$BIl mio consiglio è di andare a Desolace e metterti alla prova con uno qualsiasi degli infernals che ci trovi. Dovrebbero andare benissimo.$B$BQuando ci sarai $Griuscito:riuscita;, porta a Menara lo spirito catturato e anche lo smeraldo.",
  obj = "Prendi l'Infus Emerald e usalo su uno degli Infernals che si trovano a Desolace. Una volta $Griuscito:riuscita;, riporta l'Infus Emerald e l'Imprisoned Infernal Spirit a Menara Voidrender in Barrens.",
  progress = "Sì, $N? Hai deciso? Un Infernal o un felhound?$B$BÈ una scelta personale, e dovrebbe rispecchiare i tuoi punti di forza e le tue debolezze. Capita che uno stregone preferisca rafforzare ancora di più le doti che ha, invece di colmare le lacune. A volte sopraffare il nemico è una tattica che funziona quanto diventare un incantatore più equilibrato.",
  reward = "Ah, lo spirito di un infernal. Ben fatto, $N.$B$BLi fonderò per te quando avrò sia lo spirito sia il globo purificato, ma non prima.",
}
T[4964] = {
  title = "L'Orb of Dar'Orahil Completato",
  desc = "Mi metto subito al lavoro: creerò il tuo globo e ci infonderò il nuovo demone. Quando avrò finito, potrai scegliere se lo vuoi in forma di bastone o di globo. Ho sempre ritenuto importante rispettare l'arma che uno stregone si sceglie... Non vedo perché dovrei abbandonare questa usanza.",
  obj = "Aspetta che Menara Voidrender completi l'Orb of Dar'Orahil e poi parlale di nuovo.",
  reward = "È fatto, $N. Dimmi solo cosa preferisci: un bastone, da impugnare con entrambe le mani, o un globo, che ti permette di usare come arma un pugnale o una spada.$B$BAffrontando un felhound hai compiuto una grande impresa. Sono certa che questo oggetto ti sarà utile in futuro. Continua a impegnarti nelle arti, $N. Attenderò notizie delle tue gesta.",
}
T[4965] = {
  title = "Conoscenza del Globo di Orahil",
  desc = "Bene, bene, bene... che piacere vedere crescere il tuo potere, $N. Scommetto che sei quasi $Gpronto:pronta; per parlare con Menara Voidrender nelle Barrens. Se non ci hai mai parlato, te lo dico io: credo di non aver mai conosciuto nessun'altra così esperta nel creare oggetti — globi, soprattutto — capaci di imprigionare persino un demone e di piegarlo al nostro volere con tanta facilità.$B$BSe sei $Ginteressato:interessata;, la trovi nella torre di Strahad, sopra Ratchet, nelle Barrens.",
  obj = "Parla con Menara Voidrender in Barrens.",
  reward = "Ah, cerchi qualcosa di più... sostanzioso. Se sei davvero $Gpronto:pronta;, in questo posso aiutarti.$B$BPer una volta fa piacere vedere $Guno:una; dei nostri cercare più potere in qualcosa che non sia soltanto conoscenza.$B$BAllora, te la senti, $N?",
}
T[4966] = {
  title = "Proteggi Kanati Greycloud",
  desc = "Ma i centauri potrebbero essere più di quanti pensassi: ti chiedo, $N, di combattere al mio fianco contro questi vili assassini.",
  obj = "Proteggi Kanati Greycloud dall'attacco dei centauri.",
  reward = "Grazie dell'aiuto, $N. Senza di te non sarei riuscito a respingerli.",
  en_title = "Protect Kanati Greycloud",
  en_obj = "Protect Kanati Greycloud from the centaur attack.",
}
T[4967] = {
  title = "Conoscenza del Globo di Orahil",
  desc = "Ancora $Guno sciocco:una sciocca;, ancora a caccia degli orpelli dei mortali. Sì, ti parlo con arroganza. Ti vedo qui davanti a me e rido. Sei $Gpatetico:patetica;!$B$BMa quello che penso io non ha importanza. Conta solo cosa ne pensa chi è disposto ad avere a che fare con te! E stavolta, contro il mio parere, chi ha un po' di potere ritiene che tu meriti di più.$B$BSe è questo che vuoi, dovresti parlare con Menara Voidrender, nella torre sopra Ratchet. Credo che tu l'abbia già incontrata tempo fa.",
  obj = "Parla con Menara Voidrender in Barrens.",
  reward = "Ah, cerchi qualcosa di più... sostanzioso. Se sei davvero $Gpronto:pronta;, in questo posso aiutarti.$B$BPer una volta fa piacere vedere $Guno:una; dei nostri cercare più potere in qualcosa che non sia soltanto conoscenza.$B$BAllora, te la senti, $N?",
}
T[4968] = {
  title = "Conoscenza del Globo di Orahil",
  desc = "Mmh, sei $Garrivato:arrivata; fin qui... davvero sorprendente. Credevo che a forza di incanalare l'arcano la corruzione ti fosse entrata fin dentro l'anima e ti avesse già fatto impazzire. Allora, che ne dici se proviamo a spingerti ancora più in là?$B$BSe vuoi mettere alla prova la tua abilità, cerca Menara Voidrender nella torre di Strahad, sopra Ratchet. Ti guiderà lei.",
  obj = "Parla con Menara Voidrender in Barrens.",
  reward = "Ah, cerchi qualcosa di più... sostanzioso. Se sei davvero $Gpronto:pronta;, in questo posso aiutarti.$B$BPer una volta fa piacere vedere $Guno:una; dei nostri cercare più potere in qualcosa che non sia soltanto conoscenza.$B$BAllora, te la senti, $N?",
}
T[4969] = {
  title = "Conoscenza del Globo di Orahil",
  desc = "Ah ah! Te la stai cavando proprio bene, giovane $C.$B$BCol tempo gli infernals e i dreadlords si inchineranno davanti a te!$B$BMa fino ad allora dovrai ancora affidarti ad armi forgiate dalle mani delle razze mortali.$B$BMi sembri $Gpronto:pronta; per un'altra creazione di questo tipo e, se sei $Gdisposto:disposta;, Menara Voidrender vorrebbe parlarti! La trovi vicino alla torre di Strahad, che domina la città portuale di Ratchet. Va' da lei quando te la senti.",
  obj = "Parla con Menara Voidrender in Barrens.",
  reward = "Ah, cerchi qualcosa di più... sostanzioso. Se sei davvero $Gpronto:pronta;, posso aiutarti.$B$BPer una volta fa piacere vedere $Guno:una; dei nostri cercare più potere in qualcosa che non sia soltanto conoscenza.$B$BAllora, te la senti, $N?",
}
T[4970] = {
  title = "Provviste per i Frostsaber",
  desc = "Se desideri dare prova del tuo valore, puoi cominciare da un compito molto semplice, ma molto importante.$B$BRaccogli la carne delle chimere e degli shardtooth bears della zona e portamela: con quella nutrirò i frostsabers in addestramento.",
  obj = "Raccogli 5 Shardtooth Meats e 5 Chillwind Meats per Rivern Frostwind a Winterspring.",
  progress = "Disciplina e determinazione: questi sono i tuoi obiettivi. Potrei chiederti più e più volte un compito semplice, e ogni volta dovrai dare il meglio di te.",
  reward = "Grazie dell'aiuto, $N. Più passa il tempo, più cresce la stima che ho per te.",
}
T[4971] = {
  title = "Una Questione di Tempo",
  desc = "Una forza sinistra — molto probabilmente lo Scourge — ha manomesso la linea temporale ad Andorhal! Posso provare a tenere intatto il tempo che scorre qui e a riparare quello che è stato danneggiato, ma per farlo senza interruzioni avrò bisogno del tuo aiuto.$B$BI Temporal parasites — spazzini che si nutrono dei fili del flusso alterato del tempo — adesso infestano i silos di Andorhal, e l'unico segno visibile della loro presenza è un impulso blu di distorsione. Mi rallentano le divinazioni; ti prego, $N, aiutami a stanarli con questo temporal displacer.",
  obj = "Usa il Temporal Displacer vicino a uno dei silos di Andorhal e fai uscire allo scoperto i Temporal Parasites.$B$BUccidi 15 Temporal Parasites, poi riporta il Temporal Displacer a Chromie in Andorhal Inn, Western Plaguelands.",
  progress = "I Temporal parasites sono un male comune: si trovano ovunque il flusso del tempo sia stato manomesso. Qui ne percepisco molti, e la cosa mi turba.$B$BSe stani tutti quelli che riesci a trovare, potrò tenere meglio sotto controllo la situazione del tempo, che qui va sempre peggio. Quando sarà fatto, lo percepirò.",
  reward = "Grazie, $N: adesso il tempo sembra più facile da riparare. Forse non comprendi fino in fondo le conseguenze di una linea temporale spezzata, ma apprezzo che tu capisca quanto sia urgente contrastare quello che, lo sospetto sempre di più, è un misfatto orchestrato dallo Scourge.$B$BNon vedo niente di male a ricompensarti per l'aiuto, mortale. Le tue imprese più grandi devono ancora arrivare, e un ninnolo in dono non cambierà certo il tuo destino. Io e lo stormo draconico, però, avremmo ancora bisogno del tuo aiuto...",
}
T[4972] = {
  title = "Scandire il Tempo",
  desc = "$N, ho bisogno che tu raggiunga il mondo fuori da questa stanza. Ti spiego.$B$BVedi quanto è diversa questa stanza dal resto di Andorhal. Il mio stormo draconico agisce in molti modi e in molte linee temporali. Per riparare i danni di Andorhal adesso lavoro da un'altra linea temporale, così da non contaminarla troppo. Ma per andare avanti mi servono dei ninnoli del tempo, rimasti intrappolati da quando ha colpito la piaga. Li troverai negli scrigni, fra gli edifici in rovina di questa città che un tempo era fiera.",
  obj = "Trova 5 Andorhal Watches, che si trovano negli scrigni tra le macerie della città. Riportali a Chromie in Andorhal Inn, Western Plaguelands.",
  progress = "I ninnoli del tempo che cerco sono congegni semplici, per lo più orologi: le lancette si sono bloccate per sempre quando la piaga ha devastato Andorhal la prima volta.$B$BIl tempo non ha fine, e gli orologi che mi porterai torneranno di sicuro nelle loro case a scandire il tempo... cioè, finché qui continueranno i disturbi.",
  reward = "Sono proprio quelli che mi servono, $N. Grazie.$B$BLascia che ti ricompensi come si deve con questo. Forse non capirai a cosa possa servirti un congegno del genere, e magari non sai nemmeno bene cosa sia davvero. Ahimè, non posso dirti quando ti tornerà più utile; sappi solo che un giorno, in futuro, potresti scoprire che questo oggetto, una volta consumato, è utilissimo ed efficace. Se tenerlo o no fino ad allora... questo, $Gamico mio:amica mia;, sta a te.",
}
T[4973] = {
  title = "Contare il Tempo",
  desc = "Se sei $Gdisposto:disposta; a darmi ancora una mano, mi farà proprio comodo. Se fra le rovine di Andorhal scovi altri orologi, li prendo volentieri. Mi servono a mantenere l'equilibrio contro qualunque forza maligna stia interferendo qui con la linea temporale.$B$BIn cambio degli orologi ti darò un altro oggetto: ho il sospetto che in futuro ti tornerà molto utile.",
  obj = "Trova 5 Andorhal Watches fra le macerie della città e portali a Chromie, in Andorhal Inn, Western Plaguelands.",
  progress = "Gli orologi di Andorhal sono tutti fermi alle tre in punto, proprio come il grande orologio sulle rovine del municipio. È stato allora che la pestilenza si è diffusa per la prima volta sulla città in tutta la sua forza, e ne ha soffocato la vita.$B$BPossiamo rammaricarci tutti quanto vogliamo di quello che è successo quel giorno, ma è stato proprio quello a dare forma al flusso del tempo come lo percepite voi mortali. Lo stormo dei draghi bronzei deve continuare a proteggere la linea temporale, senza sosta!",
  reward = "Grazie ancora per l'aiuto. Accetta questo dono, ti prego. Forse non sai ancora quando usare un oggetto del genere, ma magari in futuro il sentiero del tempo ti rivelerà i suoi veri intenti. Diciamo che a te l'ho già visto succedere, $N.",
}
T[4974] = {
  title = "Per l'Orda!",
  desc = "Se Rend osa avanzare pretese così grandiose è perché lo protegge lo stormo nero.$B$BTu, $N, troverai il modo di attraversare le Halls of Ascension. Poi arriverai fino al 'Capoguerra' Rend Blackhand e lo distruggerai — PER L'ORDA!$B$B<Thrall sbatte il pugno sul trono.>$B$BLa prossima volta che tornerai nelle mie stanze, alzerai in trionfo la sua testa e la porgerai al tuo Capoguerra. Fallo, e sarai $Gonorato:onorata; come $Gun eroe:un'eroina; dell'Orda.",
  obj = "Raggiungi Blackrock Spire e uccidi Warchief Rend Blackhand. Prendi la sua testa e torna a Orgrimmar.",
  progress = "<Thrall grugnisce.>",
  reward = "Hai inferto un colpo devastante alle forze dei Blackrock, $N. Con il loro Capoguerra morto, la legione dei Blackrock ripiomba nelle fauci del caos.$B$BPer onorare le tue gesta eroiche, il popolo di Kalimdor riceverà una ricompensa!",
}
T[4975] = {
  title = "L'Orb of Noh'Orahil Completato",
  desc = "Mi metto subito al lavoro: creerò il tuo globo e ci infonderò il nuovo demone. Quando avrò finito, potrai scegliere se lo vuoi in forma di bastone o di globo. Ho sempre ritenuto importante rispettare l'arma che uno stregone si sceglie... Non vedo perché dovrei abbandonare questa usanza.",
  obj = "Aspetta che Menara Voidrender completi l'Orb of Noh'Orahil e poi parlale di nuovo.",
  reward = "È fatto, $N. Dimmi solo cosa preferisci: un bastone, da impugnare con entrambe le mani, o un globo, che ti permette di usare come arma un pugnale o una spada.$B$BAffrontando l'infernal hai compiuto una grande impresa, e questa ricompensa ti starà a pennello. Ti auguro altri successi nelle arti, $N.",
}
T[4976] = {
  title = "Restituzione della Sfera Purificata",
  desc = "Riporta la sfera purificata a Menara, a Ratchet, $N. Portale i miei saluti e sta' $Gattento:attenta;. Spero proprio che tu sappia resistere alla tentazione e alla corruzione che di sicuro incontrerai lungo la tua strada.$B$BBuona fortuna.",
  obj = "Riporta la Cleansed Infernal Orb a Menara Voidrender in Barrens.",
  progress = "Come va la ricerca di Tabetha e del globo, $N?$B$BIn fatto di arcano, Tabetha si è rivelata più che utile. Se riesci a trovarla, sono sicura che ti aiuterà senza problemi.",
  reward = "Ben fatto, $N. Questa sfera andrà benissimo.$B$BOra devi solo decidere quale demone vuoi che io imprigioni nella sfera purificata. Fatto questo, avrai un nuovo, magnifico oggetto da impugnare.",
}
T[4981] = {
  title = "Agente Bijou",
  desc = "Mai fidarsi di un goblin. Tutto qui, $N.$B$BSi chiama Bijou — è una delle nostre agenti più sfuggenti. Ho scoperto che lavorava per un losco commerciante di animali esotici delle Burning Steppes, un certo Kibler: in pratica, ci faceva il doppio gioco. E peggio ancora, si pagava le sue operazioni con i fondi dell'Orda.$B$BLa voglio qui, viva.$B$BL'hanno vista l'ultima volta mentre entrava in Blackrock Spire. Trovala e riportamela.$B$BE, $N, non farti incantare dalle sue belle parole.",
  obj = "Vai a Blackrock Spire e scopri che fine ha fatto Bijou.",
  reward = "Non ti mentirò, $R. Mi servivano i soldi! Kibler paga molto, molto bene — molto più di quanto potrà mai pagarmi la K.E.F.$B$BMa non dubitare della mia lealtà! Perché credi che sia quaggiù? Per procurare a quel goblin pazzo qualche uovo di animale esotico o un'altra stupidaggine del genere? No, solo uno scemo davvero verrebbe a Blackrock Spire a raccogliere animali da compagnia. Già, non credo che al mondo ce ne siano molti, di tipi così.$B$B<Bijou ride.>$B$BCi manca solo che quella gente si riproduca.",
}
T[4982] = {
  title = "Bijou's Belongings",
  desc = "Di notte, quando il posto è poco sorvegliato, giro di nascosto per la città e mi annoto tutto quello che vedo e che potrebbe avere un valore strategico per la K.E.F.$B$BIeri notte, però, è andata malissimo. Sono inciampata in un filo teso e ho fatto scattare un allarme. Ho nascosto l'attrezzatura da ricognizione e sono corsa al riparo! Purtroppo non riesco a tornare a riprenderla. Hanno raddoppiato e triplicato le pattuglie! Tutte quelle informazioni sono perse.$B$BRecuperami i miei beni e tornerò alla K.E.F. senza fare storie.",
  obj = "Trova i Bijou's Belongings e riportaglieli. Ricordi che ti ha detto di averli nascosti al piano più basso della città.",
  progress = "Hai avuto fortuna?",
  reward = "Ce l'hai fatta! Appena Lexlort avrà questi piani, si scorderà tutte le cattiverie che voleva farmi.$B$B$N, sei $Gil mio eroe:la mia eroina;!",
}
T[4983] = {
  title = "Bijou's Reconnaissance Report",
  desc = "Riporta questo rapporto a Lexlort. Mi restituirà il buon nome e darà di sicuro alla K.E.F. un vantaggio strategico per affrontare questi orchi.$B$BVenire con te? Ho fin troppo da fare. Muoviti, hanno bisogno di questi rapporti al più presto!",
  obj = "Riporta il Bijou's Reconnaissance Report a Grandmaster Lexlort a Kargath.",
  progress = "Dov'è la goblin???",
  reward = "Devo ammetterlo; è riuscita a sgusciare fuori da un'altra situazione spinosa! Questi rapporti si riveleranno preziosissimi per affrontare gli orchi Roccianera.$B$BNaturalmente sarai $Gricompensato:ricompensata; per il tuo duro lavoro.",
}
T[4984] = {
  title = "Anche la Fauna Soffre",
  desc = "Da solo potevo fare ben poco contro lo Scourge, ma sono venuto lo stesso in queste terre per cercare di sanare i danni inflitti alla natura. Gli animali soffrono per la pestilenza che continua a soffocare la regione, e non trovano né pietà né pace. Ti chiedo di portare avanti ciò che io qui non sono riuscito a finire.$B$BAgli animali che soffrono non resta altra salvezza che una liberazione dolce e misericordiosa. Cerca i diseased wolves qui intorno e sopprimili. Ti prego, $N, metti fine alla loro sofferenza — così lenirai di certo anche la mia.",
  obj = "Distruggi 8 Diseased Wolves, poi torna da Mulgris Deepriver a Writhing Haunt, Western Plaguelands.",
  progress = "I lupi infettati dalla pestilenza vanno soppressi, $N. La malattia che portano non ha cura. Ci ho provato... ci ho provato finché la pestilenza non ha sopraffatto anche me.",
  reward = "Io... sento che ora le anime dei lupi che hai soppresso trovano riposo. Loro — e io — ti ringraziamo di questa liberazione misericordiosa.$B$BIn questo luogo dannato non sono solo i lupi a soffrire, $N. Ti prego, ho ancora bisogno di te.",
}
T[4985] = {
  title = "Anche la Fauna Soffre",
  desc = "A est di qui, vicino al confine con le Eastern Plaguelands, un tempo per le campagne si aggiravano grizzly fieri e maestosi. La pestilenza scatenata dallo Scourge ha distrutto anche loro. Ora vagano qua e là, straziati dai muscoli che si irrigidiscono e dal pelo e dalla carne che marciscono.$B$BTi chiedo di mettere fine anche alla loro sofferenza. Per il loro patire non c'è altra cura che una morte rapida, e a dargliela dovrà essere la tua mano.",
  obj = "Distruggi 8 Diseased Grizzlies, poi torna da Mulgris Deepriver a Writhing Haunt, Western Plaguelands.",
  progress = "Sento i tuoi passi, $N. La vista mi ha abbandonato, ma riesco ancora a percepire quello che mi circonda. Hai messo fine alla sofferenza dei grizzly appestati?",
  reward = "\"So che i grizzly sono stati soppressi e che il loro tormento è finito. Io... ho ancora una cosa per te. L'ho scritta su... su questo ramo, quando ho sentito che il mio tempo in questo mondo era giunto alla fine.$B$BE infatti... ci sono arrivato. Grazie ancora, $Gamico:amica;... le creature di questa terra maledetta possono riposare... e adesso lo farò anch'io.\"$B$BDetto questo, il druido emette un sospiro pesante, seguito da quello che sembra un rantolo di morte. Il suo corpo giace immobile sul pavimento del casolare.",
}
T[4986] = {
  title = "Glyphed Oaken Branch",
  desc = "La mano senza vita del druido tauren stringe un ramo di quercia che sembra sorprendentemente sano. Se lo osservi da vicino, scopri che nella corteccia sono incisi dei glifi druidici.$B$BQuando lo afferri, lo senti più caldo di quanto dovrebbe. Nella mente ti compare l'immagine dell'albero di Teldrassil — di Darnassus, per la precisione — e ti vengono sulla punta della lingua le parole \"Cenarion Circle\". Sembra che nel ramo sia stata racchiusa l'indicazione di dove portarlo.",
  obj = "A giudicare dalla magia infusa nel Glyphed Oaken Branch, il passo successivo voluto dal druido tauren è consegnarlo al Cenarion Circle a Darnassus. Chiedi aiuto a uno dei druidi del posto.",
  progress = "Ti do il benvenuto in questa enclave a nome del Cenarion Circle, $C. Che cosa ti porta da noi?",
  reward = "È... è piuttosto strano. Questo druido — un druido tauren, per giunta — ti ha affidato moltissime informazioni preziose su quanto si sia estesa la piaga dello Scourge. Se quello che dici è vero, mi sorprende che un tauren dia notizie del genere a $Gun:una; $R, e per di più liberamente. Ne faremo buon uso, te lo prometto. Forse i tauren non si sono allontanati da Cenarius quanto crede Fandral...$B$BEhm, comunque, accetta questo, ti prego, in segno di gratitudine da parte del Cenarion Circle.",
}
T[4987] = {
  title = "Glyphed Oaken Branch",
  desc = "La mano senza vita del druido tauren stringe un ramo di quercia che sembra sorprendentemente sano. Se lo osservi da vicino, scopri che nella corteccia sono incisi dei glifi druidici.$B$BQuando lo afferri, lo senti più caldo di quanto dovrebbe. Nella mente ti compare l'immagine di Thunder Bluff, a Mulgore — dell'Elder Rise, per la precisione — e ti vengono sulla punta della lingua le parole \"Cenarion Circle\". Sembra che nel ramo sia stata racchiusa l'indicazione di dove portarlo.",
  obj = "A giudicare dalla magia infusa nel Glyphed Oaken Branch, il passo successivo voluto dal druido tauren è consegnarlo al Cenarion Circle a Thunder Bluff. Chiedi aiuto a uno dei druidi del posto.",
  progress = "Ti do il benvenuto in questa enclave a nome del Cenarion Circle, $C. Che cosa ti porta da noi?",
  reward = "Questo viene da Mulgris, dici? Avevamo sentito dire che voleva prendersi cura delle creature che soffrono nelle Plaguelands, ma questo proprio non ce lo aspettavamo... ed è molto triste. Mulgris è... era un buon amico. Piangerò la sua scomparsa con tutto il cuore.$B$BGrazie alla tua diligenza, i suoi sforzi non sono stati vani. Questo ramo custodisce molte conoscenze sulla piaga che lo Scourge diffonde sulla terra, e le studieremo con cura. Quanto a te, accetta questo, ti prego: è il minimo che possiamo fare per il tuo nobile impegno.",
}
T[5001] = {
  title = "Bijou's Belongings",
  desc = "Di solito non tratto con $Gun:una; $R, ma a quanto pare mi trovo tra l'incudine e un troll. Vedi, sono qui per una missione importantissima per l'Orda, però quello che ho scoperto riguarda anche il bene dell'Alleanza. E credimi, non sono certo un'amica dell'Alleanza, ma i Roccianera sono una minaccia ben più grande di una semplice banda di orchi.$B$BTu mi ritrovi i miei beni, e io ti aiuto con qualche informazione che potrebbe tornare utile alla tua gente.$B$BAffare fatto?",
  obj = "Trova i Bijou's Belongings e riportaglieli. Buona fortuna!",
  progress = "Hai avuto fortuna?",
  reward = "Ma guarda un po'! Dov'erano??",
}
T[5002] = {
  title = "Messaggio per Maxwell",
  desc = "Sono una goblin di parola, $R. Ora ascolta bene:$B$BQuesti orchi servono soprattutto da bestie da soma e da carne da cannone allo stormo dei draghi neri!$B$BIl loro vero capo è nientemeno che Nefarian, la progenie di Deathwing. E ho scoperto anche dove stanno i sottoposti di Nefarian in questa parte della cittadella.$B$BPorta questa mappa a Marshal Maxwell, nelle Burning Steppes. Sopra c'è segnato dove si trovano questi mostri, così li individuerai senza fatica.",
  obj = "Vai a Burning Steppes e consegna il Bijou's Information a Marshal Maxwell.",
  progress = "Ah, $N. Quanto tempo è passato.",
  reward = "Tutto questo coincide con buona parte di quello che sapevamo già. Sono comunque informazioni interessanti, e piuttosto spiacevoli.$B$BI segni su questa mappa saranno preziosi per ridimensionare la minaccia dei Roccianera.",
}
T[5021] = {
  title = "Meglio Tardi Che Mai",
  desc = "\"Il pacco va consegnato... consegnato prima che io resti intrappolata qui!\"$B$BPer la casa fluttuano, quasi come un sussurro, le grida di una donna in preda al panico. Al piano di sopra, rannicchiata nell'angolo, c'è l'apparizione di una donna: non sembra rendersi conto del tutto di quello che la circonda, e di te si accorge appena.$B$B\"Sei $Gvenuto:venuta; a consegnare il mio pacco? Ti prego, prima che le cose vadano peggio! Stavo per andarmene a cavallo. Dovrebbe essere ancora vicino al mio cavallo... o ho fatto troppo tardi?\"",
  obj = "I vaneggiamenti della donna spettrale indicavano che aveva bisogno di far consegnare un pacco. Ha detto che si trovava dov'era il suo cavallo. Dove sia il cavallo o dove andasse consegnato il pacco — dalle parole del fantasma non si capisce.",
  reward = "Nella stalla, fra il degrado e le rovine, adesso spicca un pacco che altrimenti ti sarebbe potuto sfuggire. Forse è quello per cui strepitava il fantasma di Janice Felstone...",
}
T[5022] = {
  title = "Meglio Tardi Che Mai",
  desc = "Raccogli il pacco e lo ripulisci dal sottile strato di polvere e sporcizia che gli si era depositato sopra. Una grafia frettolosa lo indirizza a una certa Emma Felstone di Stormwind, e la data di consegna è di ben più di quattro anni fa.$B$BNon è chiaro se Emma Felstone sia ancora viva, ma è risaputo che lo Stormwind City Hall tiene i registri della popolazione cittadina: se ne occupano i Royal Factors of the Stormwind Census.",
  obj = "Chiedi ai Royal Factors of Stormwind dove si trova una certa Emma Felstone. Di solito c'è un funzionario dell'anagrafe in City Hall.",
  progress = "$GBenvenuto:Benvenuta; all'ufficio dell'anagrafe di Stormwind. Se cerchi informazioni sulla nostra popolazione, posso aiutarti.",
  reward = "Un pacco per una certa Emma Felstone, dici? Ultimo indirizzo noto Stormwind, quattro anni fa? Bene, vediamo un po'...$B$BDai nostri registri risulta che circa quattro anni fa in città c'era un'Emma Felstone. Anzi, forse c'era — il censimento che sto consultando è di cinque anni fa, e non mi risulta che se ne sia andata. Il che però non vuol dire che sia ancora qui.$B$BAspetta un attimo... non sarà mica per Ol' Emma, questo pacco?",
}
T[5023] = {
  title = "Meglio Tardi Che Mai",
  desc = "Raccogli il pacco e lo ripulisci dal sottile strato di polvere e sporcizia che gli si era depositato sopra. Una grafia frettolosa lo indirizza a un certo Jeremiah Felstone di Lordaeron, e la data di consegna è di ben più di quattro anni fa.$B$BNon è chiaro se Jeremiah Felstone sia ancora vivo, ma è risaputo che Undercity, un tempo nota come Lordaeron, tiene i registri della popolazione cittadina: se ne occupa il Royal Overseers of the Undercity Census.",
  obj = "Chiedi a Royal Overseers of the Undercity dove si trova un certo Jeremiah Felstone. Di solito c'è un funzionario dell'anagrafe vicino al banco di registrazione di gilde e tabarde.",
  progress = "Sei qui per chiedere aiuto all'anagrafe di Undercity, o solo per sapere se è morto qualcuno che conoscevi? Me lo chiedono spesso.",
  reward = "Un pacco per un certo Jeremiah Felstone, ultimo indirizzo noto Lordaeron... Dovrei riuscire ad aiutarti.$B$BJeremiah Felstone viveva in città prima della pestilenza. Beh, dovrei dire l'ex Jeremiah Felstone — alcuni Forsaken hanno cambiato cognome per liberarsi del loro vecchio aspetto. E il suo caso non fa eccezione: l'ex Jeremiah Felstone oggi è conosciuto come Jeremiah Payson.$B$BAspetta un attimo... ma non è il venditore di scarafaggi?",
}
T[5047] = {
  title = "Finkle Einhorn, al Tuo Servizio!",
  desc = "Troverai Malyfous Darkhammer a Everlook, $C. Digli che 'Finkle sta benone' e che la tuta funziona alla perfezione.$B$BPoi dagli questo:$B$B<Finkle ti porge un pezzo di carne luminosa.>$B$BL'ho strappato dalle viscere della bestia mentre ero in 'vacanza'.$B$BScommetto che Malyfous ti saprebbe dire con una certa precisione cosa ci può fare, con i pezzi di un mostro del genere!$B$BOh, e immagino che tu non sappia dov'è Everlook, vero? A Winterspring, $Gamico:signora;!",
  obj = "Parla con Malyfous Darkhammer a Everlook.",
  progress = "Sì?",
  reward = "È vivo? La tuta ha funzionato? E questo che cos'è?",
}
T[5048] = {
  title = "La Buona Emma",
  desc = "È un tantino scorbutica, e magari pure fuori di zucca... ma secondo i registri Ol' Emma potrebbe essere Emma Felstone.$B$BForse l'avrai vista girovagare per la città, Ol' Emma: parla da sola, e il più delle volte blatera cose senza senso. Comunque non fa male a niente e a nessuno, e la gente di solito la lascia stare.$B$BTutto considerato, direi che Ol' Emma è proprio Emma Felstone. Potresti chiederle se di cognome fa davvero Felstone.",
  obj = "Trova Ol' Emma a Stormwind e verifica se è davvero Emma Felstone. Se lo è, forse vorrà il pacco che Janice Felstone ha preparato per lei.",
  progress = "Ti direi di levarti dal mio prato, ma come vedi un prato non ce l'ho.",
  reward = "Mi chiamo proprio Emma Felstone — e da anni sei la prima persona che mi chiama così. Chi... chi sei?$B$BDici di aver conosciuto... mia sorella?! È ancora viva? Ma chi voglio prendere in giro, certo che no. Quando a Lordaeron è scoppiata la pestilenza, mi aspettavo già il peggio. Tanti della mia famiglia sono morti... o peggio. E ora eccomi qui, la pazza Ol' Emma, tutta sola. Cosa sei, $Gun tombarolo:una tombarola; o qualcosa del genere? Cerchi il tuo prossimo bersaglio?$B$BCome... hai un pacco per me da parte di mia sorella?",
  en_title = "Good Natured Emma",
  en_obj = "Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone.  If she is, then perhaps she'd like the package Janice Felstone made for her.",
}
T[5049] = {
  title = "Il Blues di Jeremiah",
  desc = "Dalle prove che sono riuscito a mettere insieme, la persona che cerchi — nonché il destinatario del pacco — è Jeremiah Payson, il venditore di scarafaggi di Undercity.$B$BHo sempre pensato che per vendere... scarafaggi ci voglia un talento speciale. Ma tu, possente $C, di certo sei nel bel mezzo di un viaggio davvero epico, e ti lascio alle tue imprese che cambiano il mondo. Permettimi solo di avere una parte nella tua magnum opus, rivelandoti dove si trova: vicino alla banca, a strisciare come si conviene sotto una delle passerelle.",
  obj = "Trova Jeremiah Payson a Undercity e verifica se è davvero Jeremiah Felstone. Se lo è, forse vorrà il pacco che Janice Felstone ha preparato per lui.",
  progress = "Ogni volta che qualcuno schiaccia uno scarafaggio, piango. Ti prego, non farmi piangere.",
  reward = "Quel nome non lo uso da anni... ma sì, in un certo momento della mia vita — prima di questa gloriosa non-vita — quello era il mio cognome.$B$BSostieni di aver conosciuto mia sorella... o meglio, di averci parlato di recente.$B$BChe è morta.$B$BDa quattro anni.$B$BSai, se non avessi già le ossa così fragili, sarei tentato di staccarmi un piede sul tuo didietro. Sei proprio un avvoltoio, eh?$B$BCome... hai un pacco per me da parte di mia sorella?",
}
T[5050] = {
  title = "Good Luck Charm",
  desc = "A quanto pare mi sbagliavo su di te, $N, e ti devo delle scuse. Mia sorella mi ha mandato diversi effetti personali e, buffo a dirsi, fra questi c'è l'atto di proprietà della fattoria Felstone. Per ora, credo, rinuncerò a reclamarla.$B$BSe lo spirito di mia sorella è rimasto legato alla fattoria e non riesce a trovare pace, ti prego... potresti restituirle questo? È metà di un good luck charm: una metà l'aveva lei, l'altra suo marito.$B$BForse sapere che queste cose le ho io darà finalmente pace alla sua anima.",
  obj = "Riporta a Janice Felstone, in Western Plaguelands, il suo Good Luck Half-Charm.",
  progress = "John, tesoro... sei tu? Ho così freddo, all'improvviso...",
  reward = "Restituisci il mezzo talismano all'apparizione. Lei lo guarda, poi guarda te, e aspetta.$B$B\"Caro, dove l'hai messa la tua metà del talismano? Non possiamo stare insieme se non abbiamo tutte e due le metà. Caro... mi vedi?\"",
}
T[5051] = {
  title = "Due Metà Diventano Una",
  desc = "Il povero fantasma continua a farneticare:$B$B\"Ho così freddo, John. Portami il tuo talismano e staremo insieme! Presto, John, prima che arrivi la pestilenza a trasformarci in bestie orribili! Non ti vedo, John... ma so che sei vicino. Ti sento qui accanto a me.\"$B$BForse lo spirito di Janice Felstone cerca proprio questo: che qualcuno trovi la seconda metà del talismano e la riunisca alla prima.",
  obj = "Trova l'altra metà del Good Luck Charm da qualche parte in Felstone Farm, in Western Plaguelands, e ricomponilo.$B$BConsegna il Good Luck Charm a Janice Felstone in Felstone Farm, in Western Plaguelands.",
  progress = "John, non farti prendere dai ghouls... non lasciare che i ghouls prendano me... brutti ghouls... il nostro talismano ci terrà al sicuro.",
  reward = "Consegni il good luck charm ricomposto al fantasma di Janice Felstone. Non appena lo stringe, la vedi cambiare quasi all'istante: la sua forma eterea scintilla, e ti guarda con occhi limpidi ma tristi.$B$B\"Mi hai liberata... questo talismano non mi servirà più. Ti prego, prendilo: forse darà a te il conforto che ha dato a me.\"",
}
T[5052] = {
  title = "Blood Shards di Agamaggan",
  desc = "Oltre alle spine, il sangue ha toccato <sbuffo> anche altre parti della terra: pietre rosso sangue mescolate ad altri minerali. I Bristleback estraggono questi frammenti e li portano addosso come totem, <sbuffo> per avere forza in battaglia e per le loro magie. <sbuffo>$B$BIo, di quella magia, conosco i segreti.$B$BPorta a Mangletooth uno di questi blood shards, per dimostrare che hai capito. Portane molti a Mangletooth, e lui ti benedirà con la magia dei verrospino — la magia di Agamaggan! <sbuffo>",
  obj = "Porta un Blood Shard a Mangletooth a Camp Taurajo, in Barrens.$B$BRaccogli altri Blood Shards se vuoi che ti benedica con il potere di Agamaggan.",
  progress = "Le nostre tribù accorrono nelle zone di spine sparse per le Barrens, <sbuffo> perché sono luoghi sacri, ma nessuno lo è quanto Razorfen. Tutto Razorfen è il corpo di Agamaggan, <sbuffo> ma le Downs sono protetti più di ogni altro posto, perché l'ingresso sono le sue enormi fauci! <sbuffo> Inghiottono interi quelli che non gli sono fedeli, e lui li mastica e poi ne sputa i corpi! <sbuffo>$B$BAgamaggan ci ha lasciato il suo corpo per proteggerci, e ci dona il suo spirito perché noi possiamo proteggere lui. <sbuffo>",
  reward = "Ah, hai capito davvero. <sbuffo> Non ho parlato al vento, $R. Mangletooth sarà pure in gabbia, ma nessuna gabbia può fermare il potere di Agamaggan! <sbuffo>$B$BToccare il frammento, sentirlo... ne è passato di tempo, $R.$B$BSai com'è? Vedersi strappare via il proprio potere?$B$BMa ne parleremo un'altra volta. Ti ho promesso informazioni, ti ho promesso il potere di Agamaggan. Il mio popolo ha voltato le spalle a Mangletooth, e ora io ti scateno contro di loro. <sbuffo>",
  en_title = "Blood Shards of Agamaggan",
  en_obj = "Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens.$B$BCollect more Blood Shards if you want him to bless you with Agamaggan's power.",
}
T[5054] = {
  title = "Ursius degli Shardtooth",
  desc = "A nord-ovest, fra le montagne innevate di Winterspring, un abile cacciatore segue le tracce della sua preda... È Ursius degli shardtooth bears, una bestia agile e astuta.$B$BOra mando te contro di lui. Si aggira sui pendii delle colline a nord-ovest di Everlook: trovalo e dagli la caccia, prima che capisca cosa vuoi fare.$B$BChiunque abbia affrontato Ursius si è presto ritrovato a fare la preda, con lui nella parte del cacciatore. Stai in guardia.",
  obj = "Storm Shadowhoof a Everlook, in Winterspring, vuole che tu uccida Ursius.",
  progress = "Va' ora, $C, e cerca Ursius.",
  reward = "Il compito non era facile, eppure te la sei cavata egregiamente. Ma non affrettarti a credere di avermi impressionato, $N.",
}
T[5055] = {
  title = "Brumeran dei Chillwind",
  desc = "Brumeran è rapida e astuta, e plana in silenzio sulle distese innevate nel sud di Winterspring. Ma non lasciarti ingannare dalla sua grazia: non è innocua. Chi le si mette contro la paga cara, spesso con la vita.$B$BCerca Brumeran dei chillwind fra le chimere, sconfiggila e torna da me.",
  obj = "Storm Shadowhoof a Everlook, in Winterspring, vuole che tu uccida Brumeran.",
  progress = "Brumeran ti sta chiamando, $N.",
  reward = "Sì, sei $Gtornato:tornata;. Ora credo che tu sia $Gun cacciatore nato:una cacciatrice nata;: hai affrontato le creature più feroci e sei di nuovo qui, superando le mie aspettative.$B$BAdesso sei $Gpronto:pronta; per la mia ultima richiesta.",
}
T[5056] = {
  title = "Shy-Rotam",
  desc = "Nel nord di Winterspring c'è un masso imponente, la Frostsaber Rock, e intorno a quel masso si radunano grandi felini. La loro capobranco è conosciuta come Shy-Rotam. Se sconfiggessi la matriarca dei frostsabers, ogni $Galtro:altra; $R ti guarderebbe con grande rispetto.$B$BTorna in quelle aspre terre selvagge e lì prendi la carne sacra dai frostsabers. Poi trova la pietra di Shy-Rotam e posala lì: mettendole davanti la carne dei suoi simili evocherai Shy-Rotam, in preda alla collera.$B$BSii $Gpronto:pronta; ad affrontarne la furia, e sconfiggila.",
  obj = "Storm Shadowhoof a Everlook, in Winterspring, vuole che tu sconfigga Shy-Rotam.",
  progress = "Shy-Rotam è audace e spietata: difenderà con fervore i suoi simili.",
  reward = "Hai dimostrato forza e determinazione. Ti aspettano ancora molte sfide, ma ti ho già mostrato tutto quello che potevo.",
}
T[5057] = {
  title = "Imprese Passate",
  desc = "Avevo sentito parlare delle tue imprese, $N, ancora prima che mi rivolgessi la parola... del tuo desiderio incrollabile di dimostrare quanto vali, della tua abilità eccezionale come $C. E ora so che è tutto vero.$B$BChi eccelle come te merita un riconoscimento. Porta questo contrassegno a un mio amico di Thunder Bluff, Melor Stonehoof: sono sicuro che si ricorderà di te e di ciò che hai compiuto tanto tempo fa. Raccontagli le tue ultime vittorie, e non dimenticare mai quello che hai fatto oggi.",
  obj = "Porta il Contrassegno di Storm Shadowhoof a Melor Stonehoof a Thunder Bluff.",
  reward = "È dalle esperienze della vita che impariamo, $N, e sono sicuro che le tue non abbiano fatto altro che renderti più forte e più $Gsaggio:saggia;. Da quando ci siamo parlati la prima volta sei $Gcresciuto:cresciuta; molto.$B$BPrendi questo, in ricordo dei compiti difficili che hai portato a termine come $C $R, e sappi che avrai sempre il mio rispetto e la mia ammirazione.",
}
T[5058] = {
  title = "Mrs. Dalson's Diary",
  reward = "Un diario dalle pagine ingiallite è aperto sull'ultima annotazione:$B$B\"Non so cosa succederà ora che Harold si è trasformato. Ho dovuto metterci tutte le forze che avevo per trascinarlo nell'unico posto che ho trovato dove chiuderlo dentro e tenercelo. La chiave l'ho nascosta addosso, e prego che funzioni...$B$BSpero di riuscire ad andarmene da qui, ma mi servono soldi. Credo che la nostra roba sia tutta nell'armadietto... e ora che ci penso, la chiave non ce l'ha addosso Harold?$B$BCi dormirò su, adesso sono stanca morta.\"",
}
T[5059] = {
  title = "Sotto Chiave",
  progress = "La porta della latrina ha cominciato a scheggiarsi lungo il telaio, come se qualcuno avesse cercato di forzarla più e più volte, senza sosta. Adesso è chiusa a chiave dall'esterno.$B$BMentre scuoti la porta, da dentro arriva un gemito gutturale! Qualunque cosa ci sia lì dentro, di certo non sembra amichevole.",
  reward = "Con la chiave trovata sullo scheletro di quella che era Mrs. Dalson apri la porta della latrina. Un ghoul assetato di sangue balza fuori dalla latrina, dove era rimasto intrappolato per chissà quanto tempo.$B$BDall'urlo agghiacciante che il ghoul lancia appena ti vede, è chiaro che quello che un tempo era Farmer Dalson ormai non si può più salvare.",
}
T[5060] = {
  title = "Sotto Chiave",
  progress = "Davanti a te c'è un armadietto molto robusto, chiuso saldamente da una serratura incorporata. Sul davanti ci sono graffi profondi e segni. Viene da pensare che li abbiano lasciati tanti tentativi violenti, tutti falliti, di scoprire i segreti che ora nasconde.$B$BPer aprirlo dovrai trovare la chiave.",
  reward = "La chiave presa dai macabri resti di Farmer Dalson entra perfettamente nella serratura. Le ante dell'armadietto si spalancano e dentro compaiono diversi oggetti rimasti intatti, che hanno l'aria di valere parecchio.",
}
T[5061] = {
  title = "Forma Acquatica",
  desc = "Hai concluso le lezioni che tutti i giovani druidi devono ricevere prima di poter assumere un aspetto acquatico. Ora torna dal tuo maestro, Mathrengyl Bearwalker, a Darnassus. Mostragli il pendente e dimostragli che sei $Gpronto:pronta; a imparare ciò che ha da insegnarti. Sarà lui a completare il tuo addestramento: così potrai diventare una cosa sola con l'acqua.$B$BArrivederci, giovane $Gdruido:druida;. Parleremo ancora.",
  obj = "Torna a Darnassus e mostra il Pendant of the Sea Lion a Mathrengyl Bearwalker.",
  progress = "Mi avevano avvisato del tuo ritorno a Darnassus, ma prima di insegnarti la forma acquatica mi serve una prova delle lezioni che hai appreso a Moonglade.$B$BHai il Pendant of the Sea Lion?",
  reward = "Davvero notevole, $N. Sei $Gpronto:pronta; a imparare la forma acquatica, ed è un piacere insegnartela.$B$BInoltre, in riconoscimento di quanto hai compiuto nelle due prove, ti dono questo oggetto. Spero che si riveli una gradita aggiunta all'equipaggiamento di $Gun:una; $Gprotettore:protettrice; della natura e custode dell'equilibrio.",
  en_title = "Aquatic Form",
  en_obj = "Return to Darnassus and show Mathrengyl Bearwalker the Pendant of the Sea Lion.",
}
T[5062] = {
  title = "Fuoco Sacro",
  desc = "Arikara è una creatura letale, e bisogna occuparsene in fretta. Per darle la caccia dovrai accendere il sacro fuoco della vita — sarà il fuoco a evocarla.$B$BVa' subito a raccogliere la rara pianta di Incendia agave. Quando ne avrai raccolta abbastanza, chiedi consiglio a Magatha Grimtotem sull'Elder Rise, a Thunder Bluff: è una sciamana potente, capace di incantare l'agave e di ricavarne una polvere che accenderà il fuoco.$B$BDirigiti a nord-est, alla Boiling Pool, e raccogli lì l'Incendia Agave.",
  obj = "Raccogli 10 fasci di Incendia Agave, poi consulta Magatha Grimtotem su Elder Rise a Thunderbluff.",
  progress = "Così Motega Firemain manda notizie di Arikara... beh, questa sì che è grave.$B$B<Magatha si guarda intorno.>$B$BArikara è una creatura letale, nata al solo scopo di vendicarsi di chi ha commesso atti atroci.$B$B<Magatha sorride.>",
  reward = "Bene, hai raccolto tutta l'Incendia agave che serviva. Quest'erba rara si trova solo a Thousand Needles, e aiuterà ad accendere il sacro fuoco della vita, che ora è sopito.$B$B<Magatha comincia a incantare l'Incendia agave.>",
  en_title = "Sacred Fire",
  en_obj = "Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff.",
}
T[5063] = {
  title = "Berretto del Sapiente Scarlatto",
  desc = "Forse non vedrai mai un berretto più raffinato. Con la pristine hide della bestia, i nostri abili artigiani creeranno il cappello più straordinario che un prestigiatore possa sperare di portare in testa!$B$BPorta cinquanta monete d'oro e gli oggetti qui sotto, e il Berretto del Sapiente Scarlatto ti ornerà la testa:$B$B*La pristine hide della Bestia.$B$B*Frayed abomination stitchings.$B$B*Arcane crystals.$B$B*Enchanted scarlet thread.$B$BAMMIRA!",
  obj = "Per creare il Berretto del Sapiente Scarlatto, dovrai portare i seguenti oggetti a Malyfous Darkhammer: 1 Pristine Hide della Bestia; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread.$B$BDovrai anche pagare 50 monete d'oro per la creazione dell'oggetto.",
  progress = "Se non hai tutto quello che mi serve, stai sprecando il mio tempo.",
  reward = "Sbalorditivo! Ti ci saranno volute settimane per mettere insieme quei componenti... e una pristine hide, come hai fatto a trovarla?!?$B$BGoditi il berretto, $N!",
}
T[5064] = {
  title = "Spiare i Grimtotem",
  desc = "$N, in passato ci hai servito bene, perciò ora ti affido una missione importante. Il Grimtotem Clan trama qualcosa in segreto. Nelle ultime settimane si sono visti tre agenti di origine sconosciuta far visita ai Grimtotem. Abbiamo scoperto che questi messaggi, ben custoditi, stanno in forzieri diversi nel Darkcloud Pinnacle.$B$B$N, se riesci in quest'impresa pericolosa, ti ricompenserò come meriti.",
  obj = "Trova e recupera le tre Note Segrete in Darkcloud Pinnacle.",
  progress = "Hai scoperto che cosa tramano i Grimtotem?",
  reward = "Grande Spirit Totem! Questa sì che è una notizia terribile. Devo cominciare a prepararmi a qualunque cosa possa succedere.$B$B$N, come promesso, ecco la ricompensa per il coraggio con cui ci hai servito.",
  en_title = "Grimtotem Spying",
  en_obj = "Locate and retrieve the three Secret Notes in Darkcloud Pinnacle.",
}
T[5065] = {
  title = "Le Tavolette Perdute di Mosh'aru",
  desc = "Il troll con cui hai parlato non ti ha detto la verità. Le due tavolette che hai recuperato per lui, a sentir loro, contenevano l'essenza di Hakkar, ma la leggenda non finisce lì. Ci ho studiato sopra a lungo, e ho scoperto che le Tavolette di Mosh'aru non sono due, ma sei! Sei!$B$BE ho paura che i segreti delle altre non ci piaceranno...$B$BVa' a cercare la terza e la quarta tavoletta di Mosh'aru. Ce le hanno i troll mossflayer, nelle Eastern Plaguelands: trovale e portamele.",
  obj = "Porta le Third e Fourth Mosh'aru Tablets a Prospector Ironboot a Tanaris.",
  progress = "Ce le hai, le tavolette? Temo che quello che c'è scritto sopra riveli una grave minaccia per il nostro mondo.",
  reward = "Le hai trovate! Ottimo!$B$BGrazie, $N. Mi metterò a studiare questi testi per bene e ne caverò fuori il significato.$B$BPer te, però, c'è un altro compito...",
}
T[5066] = {
  title = "Chiamata alle Armi: Le Plaguelands!",
  desc = "Udite, udite! Che tutti gli eroi ascoltino queste parole!$B$BIl Kingdom of Stormwind ha lanciato una chiamata alle armi! Chiunque sia in grado di combattere è pregato di impugnarle contro l'oscura minaccia dello Scourge, nelle terre settentrionali degli Eastern Kingdoms! Corre voce che dalle rovine delle Plaguelands stiano sorgendo nuovi pericoli!$B$BEroi del regno — cercate Commander Ashlam Valorfist, che ha posto il suo campo base in Chillwind Camp, a nord delle Alterac Mountains!",
  obj = "Cerca Commander Ashlam Valorfist. Il suo campo base si trova a Chillwind Camp, a nord delle Alterac Mountains.",
  reward = "$GBenvenuto:Benvenuta; nelle Plaguelands, $Geroe:eroina;. È una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia dello Scourge che incombe a nord e a nord-est. Sono lieto che tu non abbia lasciato inascoltato lo squillo di tromba del dovere e del servizio al bene comune!$B$BSe sei $Gpronto:pronta; a sporcarti le mani, qui ai margini delle Plaguelands c'è molto lavoro per eroi volenterosi e capaci.",
  en_title = "A Call to Arms: The Plaguelands!",
  en_obj = "Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains.",
}
T[5067] = {
  title = "Gambali dell'Arcano",
  desc = "Nessuno è mai riuscito a creare un oggetto simile, ma si ritiene che si possa fare — nelle giuste circostanze.$B$BIl cercatore dell'arcano che desideri infondere nei gambali un potere immenso dovrà trovare quanto segue:$B$B* La pristine hide della Bestia.$B$B* Frayed abomination stitchings.$B$B*Arcanite Bars.$B$B*Il fluido per imbalsamazioni di Frostwhisper.$B$BAMMIRA!",
  obj = "Per creare i Gambali dell'Arcano, dovrai portare i seguenti oggetti a Malyfous Darkhammer: 1 Pristine Hide della Bestia; 5 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Frostwhisper's Embalming Fluid.$B$BDovrai anche pagare 50 monete d'oro per la creazione dell'oggetto.",
  progress = "Se non hai tutto quello che mi serve, stai sprecando il mio tempo.",
  reward = "Di rado ho visto dei mortali compiere un'impresa più improbabile. Crogiolati nella gloria della mia opera! Raccogline i frutti!",
}
T[5068] = {
  title = "Corazza della Sete di Sangue",
  desc = "Si dice che sia stata creata una sola Corazza della Sete di Sangue, destinata alla leggendaria assassina Garona. Difficilmente questo mondo ne vedrà un'altra.$B$BPoco importa! Con i componenti necessari, i nostri maestri artigiani possono riprodurla:$B$B*La pristine hide della Bestia.$B$B*Frayed abomination stitchings.$B$B*Arcanite bars.$B$B*La skin of shadow.$B$BAMMIRA!",
  obj = "Per creare la Corazza della Sete di Sangue, dovrai portare i seguenti oggetti a Malyfous Darkhammer: 1 Pristine Hide della Bestia; 10 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Skin of Shadow.$B$BDovrai anche pagare 50 monete d'oro per la creazione dell'oggetto.",
  progress = "Se non hai tutto quello che mi serve, stai sprecando il mio tempo.",
  reward = "Credevo che sarei morto e sepolto prima di vedere questo giorno.$B$BUn'impresa così grande può essere eclissata solo dalla ricompensa.",
}
T[5081] = {
  title = "La Missione di Maxwell",
  desc = "Queste informazioni colmano le lacune dei nostri rapporti sul Blackrock Spire, che per il resto sono impeccabili.$B$BL'attacco deve essere decisivo, $N.$B$BPer prima cosa va distrutto il loro maestro di guerra, il troll Voone. Senza i suoi piani di battaglia, gli orchi Roccianera precipiteranno nel caos.$B$BPoi dovrai eliminare il Gran Signore degli ogres, Omokk. Senza la sua guida, quei codardi degli ogres dei Roccianera non possono niente.$B$BInfine, il signore supremo della cittadella: Wyrmthalak. Morto lui, la loro unità di comando centrale resterà senza un tramite.",
  obj = "Vai a Blackrock Spire e distruggi War Master Voone, Highlord Omokk e Overlord Wyrmthalak. Torna da Marshal Maxwell a lavoro finito.",
  progress = "Situazione?",
  reward = "Ottimo lavoro, $N. Se non altro, ci hai fatto guadagnare altro tempo — tempo prezioso, prezioso.",
}
T[5082] = {
  title = "La Minaccia dei Winterfall",
  desc = "Sono venuta a Winterspring a studiare le Frostfire Hot Springs, e ho notato che l'acqua sembra avere ...strane proprietà. Da dove vengano non sono ancora riuscita a scoprirlo, e a dire il vero ultimamente i furbolg Winterfall mi hanno creato qualche difficoltà.$B$BLe sorgenti sembrano attirare loro quanto me. Ormai sono gelosissimi dell'acqua e non mi lasciano avvicinare alle due più grandi, qui a nord.$B$BVorrei andare avanti con gli studi: mi daresti una mano?",
  obj = "Donova Snowden a Winterspring vuole che tu uccida 8 Winterfall Pathfinders, 8 Winterfall Den Watchers e 8 Winterfall Totemics.",
  progress = "Ti sono grata dell'aiuto!",
  reward = "Grazie mille, $N! Adesso posso rimettermi al lavoro qui.$B$BAll'accampamento dei Winterfall hai trovato qualcosa di interessante?",
}
T[5083] = {
  title = "Winterfall Firewater",
  desc = "Questa fiala che hai preso ai furbolg Winterfall è vuota, ma dentro noti qualche goccia di uno strano liquido verde; sembra quasi che brilli.$B$BChe sia qualcosa di importante?$B$BProbabilmente Donova Snowden ne sa qualcosa di più: è da un po' di tempo che è accampata vicino alle sorgenti termali di Winterspring.",
  obj = "Porta l'Empty Firewater Flask a Donova Snowden a Winterspring.",
  progress = "Che cos'hai trovato?",
  reward = "L'hai preso ai Winterfall?",
}
T[5084] = {
  title = "Caduti nella Corruzione",
  desc = "Questo liquido verdastro... mi ricorda un po' la melma che ho visto quando sono passata per Felwood. E ho visto anche alcuni Winterfall Runners entrare nelle terre dei Timbermaw... Forse tutto questo c'entra con la fiala che hai trovato, $N.$B$BSubito dopo Timbermaw Hold, a Felwood, c'è un grosso gruppo di furbolg: è la tribù Deadwood, che il vil ha corrotto e fatto impazzire. Perché non vai a dare un'occhiata, per vedere se trovi qualche prova di accordi fra i Winterfall e i Deadwood?",
  obj = "Cerca un indizio nell'accampamento dei furbolg Deadwood nel nord di Felwood.",
  reward = "Nel calderone ribolle una sostanza putrida, che manda un odore ripugnante...",
}
T[5085] = {
  title = "Poltiglia Misteriosa",
  desc = "La sostanza verdastra nel calderone sembra simile a quella che hai trovato nella fiala. Questa strana roba appiccicosa potrebbe essere corrotta quanto i furbolg che l'hanno preparata...$B$BSe i furbolg Winterfall la usano, finiranno presto corrotti quanto la tribù Deadwood?$B$BMeglio tornare da Donova a raccontarle cosa hai scoperto, e portarle anche un campione del liquido del calderone.",
  obj = "Torna da Donova Snowden a riferire ciò che hai scoperto.",
  progress = "Spero che tu abbia scoperto qualcosa, $N. I Winterfall si fanno sempre più aggressivi!",
  reward = "Sei proprio $Gpieno:piena; di risorse, $N. Pensi che i furbolgs Winterfall siano stati all'accampamento dei Deadwood?",
}
T[5086] = {
  title = "Toxic Horrors",
  desc = "Ho studiato il campione che mi hai portato. Non posso dirlo con certezza, ma credo che ci siano tracce di elementi tossici. C'è un solo modo per esserne sicuri, però: raccoglierne un po' e fare un confronto.$B$BSecondo me i furbolg Deadwood potrebbero prendere questi elementi da altre creature corrotte di Felwood; soprattutto dagli elementali che vivono nell'Irontree Woods, quelli che chiamano toxic horrors.$B$BRaccogline qualche campione da farmi confrontare, ma fai attenzione — laggiù è molto pericoloso!",
  obj = "Raccogli 3 Toxic Horror Droplets per Donova Snowden a Winterspring.",
  progress = "Mi sa che cominciamo a capire cosa succede qui, $N.",
  reward = "Adesso devo confrontarle con la sostanza che hai trovato nel calderone, e dopo ne sapremo di sicuro di più.",
}
T[5087] = {
  title = "Winterfall Runners",
  desc = "Molto interessante, $N...$B$BSe si mescola questa sostanza tossica con l'acqua delle sorgenti termali, il veleno sparisce e resta solo la capacità di alterare per un po' chi la manda giù. Dev'essere per questo che i Winterfall difendono le sorgenti con tanto fervore — gli servono per purificare il corroborante.$B$BDobbiamo farla finita — tagliare i contatti fra i Winterfall e i Deadwood. Un gruppo di messaggeri fa la spola sulla strada fra il loro villaggio e Felwood: trovali, sconfiggili e rubagli il carico.",
  obj = "Trova i Winterfall Runners e impedisci loro di consegnare il carico a Winterfall Village.",
  progress = "Vedremo che succede quando ai Winterfall mancherà il corroborante!",
  reward = "<Donova esamina quello che c'è nella cassa.>$B$BChissà se mandare giù questa sostanza rende i furbolg più aggressivi. Sembrano proprio molto più grossi...",
}
T[5088] = {
  title = "Arikara",
  desc = "Prendi quest'Incendia powder, raffinata e purificata, portala a Thousand Needles e gettala sul sacro fuoco della vita. Lo troverai nel Darkcloud Pinnacle, su una guglia isolata dove seppelliscono i loro morti.$B$BNell'Incendia powder ho intessuto un incantesimo che evocherà Arikara davanti a te, $N.$B$BTemo che dia la caccia a Cairne Bloodhoof: le tradizioni dei Tauren sono cambiate troppo, e ho paura che sia stato questo a far infuriare Arikara. Sbrigati, $C, prima che sia tutto perduto!",
  obj = "Uccidi Arikara. Porta i suoi resti e l'Incendia powder a Motega Firemane a Whitereach Post come prova della tua impresa.",
  progress = "$N, hai ucciso il feroce serpente Arikara?",
  reward = "Non ha senso. Perché Arikara dovrebbe dare la caccia a Cairne Bloodhoof? Magatha è la nostra sciamana più potente: non può sbagliarsi.$B$B<Motega scuote la testa.>$B$BComunque sia, quello che hai fatto per l'Orda è una grande impresa, e non passerà inosservata — ti prego, scegli uno di questi oggetti come ricompensa per il tuo aiuto.",
  en_title = "Arikara",
  en_obj = "Slay Arikara. Bring her remains and the Incendia powder to Motega Firemane in Whitereach Post as proof of your deed.",
}
T[5089] = {
  title = "General Drakkisath's Command",
  desc = "Sul cadavere del serpente sconfitto trovi quello che sembra un messaggio importante: una lettera sul protocollo, scritta dal suo superiore, General Drakkisath.$B$BL'istinto ti dice di portarla a Marshal Maxwell.",
  obj = "Porta il General Drakkisath's Command a Marshal Maxwell in Burning Steppes.",
  progress = "Che cos'hai lì, $N?",
  reward = "La trama si infittisce...",
}
T[5090] = {
  title = "Chiamata alle Armi: Le Plaguelands!",
  desc = "Udite, udite! Che tutti gli eroi ascoltino queste parole!$B$BIl Kingdom of Stormwind ha lanciato una chiamata alle armi! Chiunque sia in grado di combattere è pregato di impugnarle contro l'oscura minaccia dello Scourge, nelle terre settentrionali degli Eastern Kingdoms! Corre voce che dalle rovine delle Plaguelands stiano sorgendo nuovi pericoli!$B$BEroi del regno — cercate Commander Ashlam Valorfist, che ha posto il suo campo base in Chillwind Camp, a nord delle Alterac Mountains!",
  obj = "Cerca Commander Ashlam Valorfist. Il suo campo base si trova a Chillwind Camp, a nord delle Alterac Mountains.",
  reward = "$GBenvenuto:Benvenuta; nelle Plaguelands, $Geroe:eroina;. È una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia dello Scourge che incombe a nord e a nord-est. Sono lieto che tu non abbia lasciato inascoltato lo squillo di tromba del dovere e del servizio al bene comune!$B$BSe sei $Gpronto:pronta; a sporcarti le mani, qui ai margini delle Plaguelands c'è molto lavoro per eroi volenterosi e capaci.",
}
T[5091] = {
  title = "Chiamata alle Armi: Le Plaguelands!",
  desc = "Udite, udite! Che tutti gli eroi ascoltino queste parole!$B$BIl Kingdom of Stormwind ha lanciato una chiamata alle armi! Chiunque sia in grado di combattere è pregato di impugnarle contro l'oscura minaccia dello Scourge, nelle terre settentrionali degli Eastern Kingdoms! Corre voce che dalle rovine delle Plaguelands stiano sorgendo nuovi pericoli!$B$BEroi del regno — cercate Commander Ashlam Valorfist, che ha posto il suo campo base in Chillwind Camp, a nord delle Alterac Mountains!",
  obj = "Cerca Commander Ashlam Valorfist. Il suo campo base si trova a Chillwind Camp, a nord delle Alterac Mountains.",
  reward = "$GBenvenuto:Benvenuta; nelle Plaguelands, $Geroe:eroina;. È una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia dello Scourge che incombe a nord e a nord-est. Sono lieto che tu non abbia lasciato inascoltato lo squillo di tromba del dovere e del servizio al bene comune!$B$BSe sei $Gpronto:pronta; a sporcarti le mani, qui ai margini delle Plaguelands c'è molto lavoro per eroi volenterosi e capaci.",
}
T[5092] = {
  title = "Aprire la Strada",
  desc = "Le vie che portano ad Andorhal da ovest e da nord sono ben fortificate, quindi intendo colpire la città dalla strada a est, che è meno difesa. Come prima linea di difesa lo Scourge conta sulla barriera di non morti che infesta il Sorrow Hill. Se vogliamo avanzare su Andorhal, dovremo passare per il Sorrow Hill.$B$BIl tuo primo incarico sarà aprire la strada attraverso il Sorrow Hill. Sfoltisci gli scheletri e i ghouls che infestano la zona; quando hai finito, torna a fare rapporto!",
  obj = "Uccidi 10 Skeletal Flayers e 10 Slavering Ghouls a Sorrow Hill.$B$BTorna da Commander Ashlam Valorfist a Chillwind Camp, Western Plaguelands.",
  progress = "Preparati al peggio, $N — e dai fondo a tutte le tue energie. Non sarà un compito facile. Mentre qui raduniamo le nostre forze per poi colpire lo Scourge, tu farai parte dell'avanguardia che passerà all'attacco! La tua missione sul Sorrow Hill ci aprirà la strada verso la vittoria!",
  reward = "Missione compiuta, $N! Ben fatto, ben fatto.$B$BLascia che ti ricompensi del lavoro svolto fin qui con qualche moneta delle casse di Stormwind. Ti consiglio di spenderle in equipaggiamento utile per la prossima missione... quella che ti porterà fin dentro le rovine di Andorhal.$B$BSii $Gpronto:pronta;! Sii vigile!",
}
T[5093] = {
  title = "Chiamata alle Armi: Le Plaguelands!",
  desc = "Eroi del regno, ascoltatemi — l'Orda vi chiama ad agire, e senza indugio!$B$BLa chiamata alle armi è partita: chiunque sia in grado di combattere si schieri contro lo Scourge! Si dice che dalle rovine degli Eastern Kingdoms stiano sorgendo nuove minacce, e che incombano a est di Undercity, nelle regioni settentrionali delle terre che ora si chiamano Plaguelands!$B$BEroi del regno — cercate High Executor Derrington, che ha piantato il suo campo base al Bulwark, a est della Radura di Tirisfal!",
  obj = "Cerca High Executor Derrington. Il suo campo base si trova a Bulwark, a est di Tirisfal Glade e di Undercity.",
  reward = "$GBenvenuto:Benvenuta; nelle Plaguelands, $Geroe:eroina;. Sei su una delle frontiere più pericolose di Azeroth: a est, e ancora più in là, incombe la minaccia dello Scourge. Sono lieto di sapere che in te il richiamo del dovere e del servizio all'Orda non ha trovato orecchie sorde!$B$BQui, ai margini delle Plaguelands, c'è molto da fare per eroi volenterosi e capaci, se sei $Gpronto:pronta; a sporcarti le mani.",
}
T[5094] = {
  title = "Chiamata alle Armi: Le Plaguelands!",
  desc = "Eroi del regno, ascoltatemi — l'Orda vi chiama ad agire, e senza indugio!$B$BLa chiamata alle armi è partita: chiunque sia in grado di combattere si schieri contro lo Scourge! Si dice che dalle rovine degli Eastern Kingdoms stiano sorgendo nuove minacce, e che incombano a est di Undercity, nelle regioni settentrionali delle terre che ora si chiamano Plaguelands!$B$BEroi del regno — cercate High Executor Derrington, che ha piantato il suo campo base al Bulwark, a est della Radura di Tirisfal!",
