}
T[5095] = {
  title = "Chiamata alle Armi: Le Plaguelands!",
  desc = "Eroi del regno, ascoltatemi — l'Orda vi chiama ad agire, e senza indugio!$B$BLa chiamata alle armi è partita: chiunque sia in grado di combattere si schieri contro lo Scourge! Si dice che dalle rovine degli Eastern Kingdoms stiano sorgendo nuove minacce, e che incombano a est di Undercity, nelle regioni settentrionali delle terre che ora si chiamano Plaguelands!$B$BEroi del regno — cercate High Executor Derrington, che ha piantato il suo campo base al Bulwark, a est delle Tirisfal Glades!",
  obj = "Cerca High Executor Derrington. Il suo campo base si trova a Bulwark, a est di Tirisfal Glades e di Undercity.",
