}
T[5096] = {
  title = "Diversivi Scarlatti",
  desc = "Prima di Andorhal dobbiamo occuparci della minaccia della Scarlet Crusade, che avanza da Hearthglen. Si sono accampati fra il Felstone Field e le Dalson's Tears, e così rischiamo di trovarci a combattere lo Scourge e la Crociata nello stesso momento.$B$BIl mio piano è metterli gli uni contro gli altri: andrai a distruggere la tenda di comando che hanno montato, con qualche Flame in a Bottle presa da questa cassa di incendiari. Rasa al suolo la tenda, pianta lì accanto questo stendardo dello Scourge. Con un po' di fortuna, per vendicarsi ci ignoreranno e penseranno solo allo Scourge.",
  obj = "Raggiungi il campo base della Scarlet Crusade tra il Felstone Field e Dalson's Tears e distruggi la loro tenda di comando.$B$BPianta lo stendardo dello Scourge nel campo, poi torna da High Executor Derrington a Bulwark, Western Plaguelands.",
  progress = "Un attacco a sorpresa contro la precaria posizione avanzata della Scarlet Crusade ci darà il tempo di marciare su Andorhal. Confido che tu sia $Gvenuto:venuta; a riferirmi un successo!$B$BQuando il piano sarà compiuto dovremo lavorare sodo, e in fretta. Se non abboccano al nostro piccolo stratagemma, non abbiamo né i mezzi né gli uomini per combattere lo Scourge e la Scarlet Crusade nello stesso momento.",
  reward = "Eseguito alla perfezione, $N. Il tuo attacco alla Scarlet Crusade ci farà guadagnare tempo. Ho mandato uno dei miei esploratori migliori a sorvegliare il campo, per assicurarsi che le truppe della Crociata che verranno a rinforzare la posizione abbocchino all'esca.$B$BOra che la pressione su di noi è calata, dovremmo finalmente poter rischiare una missione dentro Andorhal stessa, e per giunta importante. Visti i successi che hai ottenuto finora, mi piacerebbe molto affidarla ancora a te.",
}
T[5097] = {
  title = "Di Torre in Torre",
  desc = "Con un congegno magico chiamato beacon torch possiamo segnare i bersagli che scegliamo per le prossime azioni delle nostre truppe. E proprio a questo proposito, crediamo che lo Scourge si serva delle torri di guardia di Andorhal per controllare i movimenti delle sue forze.$B$BEcco la tua missione: sfonda le difese di Andorhal e piazza i fari su tutte e quattro le torri di guardia. Dovrai metterti sulla soglia di ogni torre per collocare il faro, che poi la segnerà. La beacon torch ha solo cinque cariche, perciò usale con giudizio!",
  obj = "Usando la Beacon Torch, segna ogni torre di Andorhal; dovrai stare sulla soglia della torre per riuscire a segnarla.$B$BUna volta segnate tutte e quattro le torri, riporta la Beacon Torch a Commander Ashlam Valorfist a Chillwind Camp, nelle Western Plaguelands.",
  progress = "Una volta segnate, le torri saranno i primi bersagli del nostro attacco ad Andorhal. Ho il sospetto che, messe fuori uso quelle, la minaccia principale di Andorhal verrà allo scoperto. Da lì in poi ci si batterà apertamente per il dominio della città!$B$BSei $Gtornato:tornata; a dirmi che ce l'hai fatta, vero? E non dimenticare la beacon torch; il materiale bellico va sempre tenuto sotto controllo.",
  reward = "I miei sacerdoti mi dicono che i nostri rilevatori dei fari captano segnali fortissimi da tutte e quattro le torri! Oserei dire che hai portato a termine un'altra missione con un successo pieno e totale! Ancora una volta, ben fatto, $N!$B$BAdesso che le torri sono segnate, i preparativi per l'attacco sono completi. È ora di dare battaglia allo Scourge!",
}
T[5098] = {
  title = "Lungo Tutte le Torri di Guardia",
  desc = "Con un congegno magico chiamato beacon torch possiamo segnare i bersagli che vogliamo far colpire ai nostri soldati nelle prossime azioni. E proprio qui entra in gioco una cosa: crediamo che lo Scourge usi le torri di guardia di Andorhal per controllare i movimenti delle sue truppe.$B$BEcco la tua missione: superare le difese di Andorhal e piazzare i fari presso tutte e quattro le torri di guardia. Per farlo devi trovarti sulla soglia di ciascuna torre; a segnarla poi ci penserà il faro. La beacon torch ha solo cinque cariche, quindi usale con saggezza!",
  obj = "Con la Beacon Torch, segna ogni torre di Andorhal; per riuscirci dovrai stare sulla soglia.$B$BUna volta segnate tutte e quattro le torri, riporta la Beacon Torch a High Executor Derrington al Bulwark, Western Plaguelands.",
  progress = "Una volta segnate, le torri saranno i bersagli di massima priorità del nostro attacco ad Andorhal. Sospetto che, tolte di mezzo le torri, la minaccia principale di Andorhal uscirà allo scoperto. Da lì in poi ci si batterà apertamente per il controllo della città!$B$BSei $Gtornato:tornata; a dirmi che ce l'hai fatta, vero? E non dimenticare la beacon torch; il materiale va tenuto sotto controllo.",
  reward = "I miei stregoni riferiscono che i nostri rilevatori dei fari captano segnali fortissimi da tutte e quattro le torri! Hai eseguito i miei ordini con l'abilità e la precisione di $Gun veterano esperto:una veterana esperta;. Ancora una volta prendo debita nota dei tuoi servigi all'Orda, $N!$B$BOra che le torri sono segnate, i preparativi per l'attacco sono completi. È giunta l'ora di colpire lo Scourge!",
}
T[5102] = {
  title = "La Fine di General Drakkisath",
  desc = "Affrontiamo queste bestie su due fronti: le combattiamo dall'interno da Stormwind, la nostra capitale, e qui nelle Burning Steppes portiamo la battaglia alle loro porte. Dobbiamo restare vigili, $N. La nostra ira non deve risparmiare nessuno, come loro non hanno avuto pietà dei nostri quando hanno colpito le nostre case e le nostre famiglie.$B$BTrova questo General Drakkisath e distruggilo!$B$BNon sarà certo un compito semplice, ma le ricompense saranno straordinarie.",
  obj = "Vai a Blackrock Spire e distruggi General Drakkisath. Torna da Marshal Maxwell a lavoro finito.",
  progress = "Allora, è fatta?",
  reward = "Non c'è dubbio: i prossimi che colpiremo saranno i loro signori dei draghi. Ben fatto, $Gcoraggioso:coraggiosa; soldato dell'Alleanza! Davvero ben fatto.",
}
T[5103] = {
  title = "Morte Ardente e Infuocata",
  desc = "Di questo umano restano solo alcune ossa carbonizzate. Sembra che sia morto a un passo da ciò che cercava — degli Unfired Plate Gauntlets.$B$BForse ti conviene prendere i guanti e uscire dal fuoco?",
  obj = "Qualcuno a questo mondo deve pur sapere cosa farsene di questi guanti. Buona fortuna!",
  reward = "Ma che...",
}
T[5121] = {
  title = "High Chief Winterfall",
  desc = "Sappiamo ancora molto poco del perché i furbolg mandino giù questa strana sostanza, ma credo sia meglio farla finita prima che la situazione ci sfugga di mano.$B$BDi solito i furbolg Winterfall non sono una tribù aggressiva: se si comportano così, secondo me stanno eseguendo gli ordini del loro capo. Al danno già fatto, molto probabilmente, non c'è rimedio, ma credo che, morto lui, non peggioreranno.$B$BDirigiti a est, verso il Winterfall Village.",
  obj = "Donova Snowden a Winterspring vuole che tu sconfigga High Chief Winterfall.",
  progress = "Magari al Winterfall Village scoprirai qualcosa di più, $N.",
  reward = "Grazie di cuore, $N. Spero di poter tornare ai miei studi senza paura di finire in un'imboscata. Ti prego, accetta questa ricompensa.",
}
T[5122] = {
  title = "Il Medallion of Faith",
  progress = "È il potere di questa cappella che mi dà la forza di resistere alla corruzione che ho nel cuore: se ne esco, diventerò un cavaliere della morte. Esiste però un medaglione, il medallion of faith, che mi darà la forza che mi serve per andarmene.$B$BTi prego, $N, recupera quel medaglione. Lo custodisce Malor the Zealous, un folle della Scarlet Brotherhood che vive nelle profondità dello Scarlet Bastion, nella parte occidentale di Stratholme.",
  reward = "Hai recuperato il medaglione! Ora potrò lasciare la cappella e fare il mio dovere.$B$BDevo uccidere la bestia che ha aiutato a corrompere me e tanti miei fratelli e sorelle, Baron Rivendare!",
}
T[5123] = {
  title = "L'Ultimo Pezzo",
  desc = "Il registro che hai trovato addosso al gran capo sembra corposo, ma ne sfogli un paio di pagine e ti accorgi che non riesci a leggerlo. I segni sono rozzi e tracciati così male che non sei $Gsicuro:sicura; che qualcuno sappia decifrarli.$B$BForse però Donova potrà dirti cosa c'è scritto...",
  obj = "Porta il Crudely-written Log a Donova Snowden, a Winterspring.",
  progress = "E questo che cos'è, $N?",
  reward = "Chissà cosa vuol dire tutto questo... Non ci capisco niente...",
}
T[5124] = {
  title = "Fiery Plate Gauntlets",
  desc = "Per la barba di Thaurissan!$B$BDove li hai trovati?$B$BE soprattutto, saresti $Gdisposto:disposta; a separartene? Naturalmente ti pagherei per un gesto tanto nobile.$B$BFacciamo così, $N. Se mi dai quei guanti compatti, ti insegno a fartene un paio tutto tuo. Devi solo procurarmi i materiali, così posso mettere a punto la ricetta esatta.$B$BAffare fatto??$B$BEcco la lista di ciò che mi serve. Visto che i guanti ce li metti tu, a tutto quello che non è Enchanted Thorium ci penso io.",
  obj = "Porta a Malyfous Darkhammer 6 Enchanted Thorium Bars, 2 Essence of Fire e 4 Star Rubies. Dovrai consegnare anche gli Unfired Plate Gauntlets.",
  progress = "Il tempo è denaro, $N, e io non ho granché né dell'uno né dell'altro.",
  reward = "Come promesso, $N, ecco la tua ricetta! Ci aggiungo anche qualcosina in più per tutta la fatica e la dedizione. Tanto, che me ne faccio di questa roba???",
}
T[5125] = {
  title = "La Resa dei Conti di Aurius",
  reward = "$N, sto morendo... ma la mia anima è salva, e per questo ti devo più di quanto le parole possano dire. Prendi questo, ti prego... e continua a combattere, $Gvaloroso:valorosa; $C!",
}
T[5126] = {
  title = "Il Racconto di Lorax",
  desc = "Il Satiro va avanti e indietro, parlando da solo. Vuoi fargli qualche domanda?",
  obj = "Parla con Lorax. Ascolta ciò che ha da dire.",
  progress = "...",
  reward = "<Lorax ride.>",
}
T[5127] = {
  title = "La Forgia Demoniaca",
  desc = "Lorax fa patti, non li accetta da insignificanti mortali.$B$BUn patto con te lo farò, però... prendi questa picca: è intrisa di potenti energie Vili. Quando troverai Goraluk Anvilcrack, uccidilo e con questa picca trafiggigli il cuore morente. La sua anima ha barattato, la sua anima io avrò. Riporta la picca, riporta il pettorale che il ladro ha rubato, e ti insegnerò ciò che lui doveva imparare.",
  obj = "Vai a Blackrock Spire e trova Goraluk Anvilcrack. Uccidilo e poi usa la Blood Stained Pike sul suo cadavere. Una volta risucchiata la sua anima, la picca sarà Macchiata d'Anima.$B$BDevi anche trovare l'Unforged Rune Covered Breastplate.$B$BRiporta sia la Soul Stained Pike sia l'Unforged Rune Covered Breastplate a Lorax a Winterspring.",
  progress = "Non tentare...",
  reward = "Il nostro patto non hai infranto. L'anima io ho preso. La ricompensa io darò.",
}
T[5128] = {
  title = "Words of the High Chief",
  desc = "Ormai i Winterfall non sono più un pericolo per me, ma se vuoi ancora capire cosa spingesse i furbolgs a preparare e a bere questa strana acquavite, secondo me dovresti cercare Kelek Skykeeper.$B$BÈ uno dell'Emerald Circle, un gruppo di druidi che a Felwood si dedicano a guarire la terra dalla corruzione.$B$BKelek conosce bene i furbolgs di Felwood, e sul registro potrebbe dirti di più.$B$BGrazie ancora, $N.",
  obj = "Porta il Crudely-written Log a Kelek Skykeeper, nel sud di Felwood.",
  progress = "L'Emerald Circle è amico di tutti, $R. Che cosa posso fare per te?",
  reward = "Sì, se me lo lasci esaminare per un po', forse riesco a tradurtelo.$B$B<Kelek sfoglia le pagine.>$B$BAppena potrò studiarlo per bene, ti farò sapere.$B$BGrazie di avermelo mostrato, $N. Dei furbolgs Winterfall si sa pochissimo.",
}
T[5141] = {
  title = "Lavorazione del Cuoio a Scaglie di Drago",
  desc = "Lavorare il cuoio a scaglie di drago non è facile, ma dà enormi soddisfazioni. Ti insegnerò a fabbricare questa pregiata armatura di maglia, a patto che tu accetti certe condizioni.$B$BSe scegli questa strada, rinunci per sempre a imparare la lavorazione del cuoio elementale o tribale; al vertice di quest'arte c'è posto per una sola delle tre. Poi mi serviranno alcuni campioni dei tuoi lavori migliori con le armature di scorpide. E infine dovrai dimostrarmi di saperti procurare la materia prima del mestiere: le scaglie dei draconidi.",
  obj = "Porta 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves e 10 Worn Dragonscales a Peter Galen, in Azshara.$B$BCompletando questa quest avrai accesso alle arti della Lavorazione del Cuoio a Scaglie di Drago.$B$BUna volta completata la quest, non potrai più imparare la Lavorazione del Cuoio Elementale né la Lavorazione del Cuoio Tribale; prima di farlo, assicurati che sia questa la strada che vuoi seguire.",
  progress = "Se sei $Gpronto:pronta; a prendere una decisione definitiva e a diventare $Gun conciatore:una conciatrice; a scaglie di drago, sono disposto a prenderti come $Gallievo:allieva;. Portami quello che ti ho chiesto e cominceremo la tua formazione.",
  reward = "Devo riconoscerlo — per prendere una decisione definitiva come la tua ci vuole una volontà ferma. Ti assicuro che la lavorazione del cuoio a scaglie di drago si rivelerà una strada redditizia e piena di soddisfazioni.$B$BQuando in futuro vorrai addestrarti in quest'arte, ti basterà venire a parlare con me: ti metterò a disposizione tutto quello che ancora non hai imparato.",
}
T[5142] = {
  title = "Piccola Pamela",
  desc = "Nella battaglia di Darrowshire siamo morti in tantissimi. Tantissimi... e a molti è andata peggio.$B$BAll'inizio della battaglia ho nascosto mia nipote Pamela, e non so cosa le sia successo. Sono solo uno spirito errante, ma il mio cuore vuole ancora sapere che sorte ha avuto Pamela.$B$BTi prego, $Gbuon:buona; $C. Andresti a cercarla a Darrowshire? È a est, oltre il Gahrron's Withering.",
  obj = "Trova Pamela Redpath.",
  reward = "Ciao. Sono Pamela, e tu come ti chiami?",
}
T[5143] = {
  title = "Conciatura Tribale",
  desc = "Per imparare la conciatura tribale bisogna capire quanto sia davvero primordiale la natura; so che padroneggi già l'arte di creare armature di cuoio selvatico, e sono disposta a completare il tuo addestramento.$B$BSappi questo, $C: scegliendo questa strada accetti di non imparare mai la conciatura delle scaglie di drago o la conciatura elementale; c'è spazio per praticare una sola delle tre arti. Portami inoltre i migliori esemplari della tua armatura di cuoio selvatico: da lì inizieremo il tuo cammino verso la maestria.",
  obj = "Porta una Wild Leather Vest e un Wild Leather Helmet a Caryssia Moonhunter a Feralas.$B$BCompletare questa missione ti darà accesso alle arti della Conciatura Tribale.$B$BCompletare questa missione ti impedirà di imparare la Conciatura delle Scaglie di Drago e la Conciatura Elementale; assicurati che sia questa la strada che vuoi seguire prima di farlo.",
  progress = "La natura è una forza da placare prima che tu possa sperare di imparare a piegarne la volontà nei tuoi indumenti di cuoio. Portami la tua offerta per lei, e farò in modo che tu venga $Gascoltato:ascoltata;.",
  reward = "Mi hai portato le tue offerte migliori, e presto la natura ti permetterà di piegarla alla tua volontà. Quando avrò finito di istruirti, il tuo lavoro sarà esso stesso una forza della natura.$B$BIn futuro, per addestrarti nell'arte, ti basterà parlarmi: metterò a tua disposizione qualsiasi conoscenza che non hai ancora fatto tua.",
}
T[5144] = {
  title = "Conciatura Elementale",
  desc = "La conciatura elementale la conosco: se sei $Gdisposto:disposta; ad aprire la mente ai poteri superiori della materia, ti insegnerò tutto quello che c'è da imparare.$B$BSappi una cosa, $C: se scegli questa via, accetti di non imparare mai la conciatura delle scaglie di drago o quella tribale; delle tre arti se ne può praticare una sola. Mi servirà inoltre una prova adeguata che sei in sintonia con gli elementi della natura; per darmela, portami le essenze più pure di fuoco, acqua, terra e vento.",
  obj = "Porta 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth e 2 Breath of Wind a Sarah Tanner in Searing Gorge.$B$BCompletare questa missione ti darà accesso alle arti della Conciatura Elementale.$B$BCompletare questa missione ti impedirà di imparare la Conciatura delle Scaglie di Drago e la Conciatura Tribale; assicurati che sia questa la via che vuoi seguire prima di farlo.",
  progress = "Per creare armature di cuoio di questo tipo servono pazienza e dedizione. Quando avrai legato la tua sorte agli elementi, non potrai più voltar loro le spalle. Portami la prova che ne sei $Gdegno:degna; e cominceremo.",
  reward = "Hai legato la tua sorte, e gli elementi ti accettano. Quando avrò finito di insegnarti, padroneggerai la volontà di creare i più raffinati indumenti di cuoio.$B$BIn futuro, per addestrarti in quest'arte, ti basterà parlarmi e ti metterò a disposizione tutto ciò che non hai ancora imparato.",
}
T[5145] = {
  title = "Lavorazione del Cuoio a Scaglie di Drago",
  desc = "La lavorazione del cuoio a scaglie di drago non è facile, ma dà enormi soddisfazioni. Ti insegnerò a fabbricare questa ottima armatura di maglia, a patto che tu accetti certe condizioni.$B$BSe scegli questa strada, accetti di non imparare mai la lavorazione del cuoio elementale o tribale; al vertice dell'arte c'è posto per una sola delle tre. Poi mi serviranno alcuni campioni del tuo lavoro migliore con le armature di scorpide. Infine, dovrai dimostrarmi che sai procurarti la materia prima del mestiere: le scaglie dei draconidi.",
  obj = "Porta 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves e 10 Worn Dragonscales a Thorkaf Dragoneye, in Badlands.$B$BCompletare questa missione ti darà accesso alle arti della Lavorazione del Cuoio a Scaglie di Drago.$B$BUna volta completata la missione, non potrai imparare la Lavorazione del Cuoio Elementale e la Lavorazione del Cuoio Tribale; prima di farlo, assicurati che sia questa la strada che vuoi seguire.",
  progress = "Se sei $Gpronto:pronta; a prendere una decisione definitiva e a diventare $Gun conciatore:una conciatrice; di scaglie di drago, io sono disposto ad accoglierti come $Gallievo:allieva;. Portami solo quello che ti ho chiesto e cominceremo la tua formazione.",
  reward = "Te lo devo riconoscere — ci vuole molta forza di volontà per prendere una decisione definitiva come hai appena fatto. E ti assicuro che la lavorazione del cuoio a scaglie di drago si rivelerà una strada redditizia e gratificante.$B$BIn futuro, quando vorrai addestrarti in quest'arte, ti basterà parlare con me: ti trasmetterò tutto quello che ancora non hai imparato.",
}
T[5146] = {
  title = "Conciatura Elementale",
  desc = "Conosco la conciatura elementale: se sei $Gdisposto:disposta; ad aprire la mente ai poteri superiori della materia, condividerò con te tutto quello che c'è da imparare.$B$BMa sappi una cosa, $C: se scegli questa via, accetti di non imparare mai la conciatura delle scaglie di drago né quella tribale, perché delle tre arti c'è posto per praticarne una sola. E mi servirà anche una prova adeguata che sei in sintonia con gli elementi della natura: per questo, portami le essenze più pure di fuoco, acqua, terra e vento.",
  obj = "Porta 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth e 2 Breath of Wind a Brumn Winterhoof su Arathi Mountains.$B$BCompletare questa quest ti darà accesso alle arti della Conciatura Elementale.$B$BCompletare questa quest ti impedirà di imparare la Conciatura delle Scaglie di Drago e la Conciatura Tribale; assicurati che sia questa la via che vuoi seguire prima di farlo.",
  progress = "Fare armature di cuoio di questo tipo chiede pazienza e dedizione. Quando hai legato il tuo destino agli elementi, non puoi più voltare loro le spalle. Portami la prova del tuo valore, e cominceremo.",
  reward = "Hai legato il tuo destino, e gli elementi ti accettano. Quando avrò finito di insegnarti, avrai la forza di volontà per creare gli abiti di cuoio più raffinati.$B$BIn futuro, per addestrarti in quest'arte ti basterà parlarmi, e ti trasmetterò tutto quello che non avrai ancora fatto tuo.",
}
T[5147] = {
  title = "RICERCATO: Arnak Grimtotem",
  desc = "Ricercato: Arnak Grimtotem$B$BArnak l'emarginato è ricercato per gli orrendi crimini di omicidio e rapimento. Ricche ricompense attendono chi avrà il coraggio di consegnare questo criminale alla giustizia.$B$BL'ultima volta Arnak è stato visto sulle rupi vicino al Darkcloud Pinnacle. Per riscuotere la ricompensa, mostra la prova della tua impresa a Cliffwatcher Longhorn a Freewind Post.",
  obj = "Uccidi Arnak Grimtotem e porta la prova della tua impresa a Cliffwatcher Longhorn a Freewind Post.",
  progress = "Hai novità su quell'assassino di Arnak Grimtotem?",
  reward = "Ah! Be', questa sì che è un'ottima notizia! Cominciavo a credere che non l'avrebbero mai consegnato alla giustizia!$B$BEcco a te, $N... e grazie. Sentir parlare delle infamie di Arnak mi faceva ribollire il sangue!",
  en_title = "Wanted - Arnak Grimtotem",
  en_obj = "Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post.",
}
T[5148] = {
  title = "Conciatura Tribale",
  desc = "Per imparare la conciatura tribale bisogna capire quanto la natura sia davvero primordiale. So che l'arte di fabbricare armature di cuoio selvatico ormai la padroneggi, e sono disposto a completare il tuo addestramento.$B$BSappi una cosa, $C: se scegli questa via, accetti di non imparare mai la conciatura delle scaglie di drago o quella elementale, perché delle tre arti se ne può praticare una sola. E poi portami i migliori esemplari della tua armatura di cuoio selvatico: da lì cominceremo a fare di te $Gun maestro:una maestra;.",
  obj = "Porta una Wild Leather Vest e un Wild Leather Helmet a Se'Jib in Stranglethorn Vale.$B$BCompletare questa quest ti darà accesso alle arti della Conciatura Tribale.$B$BCompletandola, non potrai più imparare la Conciatura delle Scaglie di Drago né la Conciatura Elementale; prima di farlo, assicurati che sia questa la via che vuoi seguire.",
  progress = "La natura è una forza, e prima di sperare di imparare a piegarne la volontà nei tuoi indumenti di cuoio devi placarla. Portami l'offerta per questa forza e farò in modo che tu venga $Gascoltato:ascoltata;.",
  reward = "Le offerte che hai dato sono le tue migliori, e presto la natura ti permetterà di piegarla alla tua volontà. Quando avrò finito di istruirti, il tuo lavoro sarà di per sé una forza della natura.$B$BD'ora in poi, se vorrai addestrarti in quest'arte, ti basterà parlarmi: ti trasmetterò tutto quello che non hai ancora fatto tuo.",
}
T[5149] = {
  title = "Pamela's Doll",
  desc = "La zia Marlene mi ha detto di restare qui a casa nostra, perché mio padre doveva andare a combattere. Il mio papà è l'uomo più coraggioso del mondo intero!$B$BMa è tanto tempo che sono qui, e lui non è venuto a prendermi. A volte arrivano delle persone cattive che mi sussurrano delle cose, e io voglio che papà le mandi via, ma lui non c'è!$B$BE certe volte, quando viene buio, voglio giocare con la mia bambola, ma non posso perché l'ho lasciata in paese.$B$BMe la trovi, la mia bambola?",
  obj = "Trova la bambola di Pamela.",
  progress = "Hai trovato la mia bambola?",
  reward = "L'hai trovata! Hai trovato la mia bambola! Oh, grazie!",
}
T[5150] = {
  title = "Dadanga Ha Fame!",
  progress = "Quando ti avvicini, Dadanga alza lo sguardo su di te. Pare che speri in qualcosa...$B$BProbabilmente ha fame!$B$BNel cratere deve pur crescere qualcosa che farebbe da spuntino perfetto a un grosso erbivoro. Dadanga è una ragazza bella grossa; qualunque cosa le porti, ne servirà parecchia!",
  reward = "Dadanga sembra contenta, quando le metti davanti i germogli.$B$BIn cambio della leccornia, spinge verso di te uno small brown-wrapped package!",
}
T[5151] = {
  title = "Hypercapacitor Gizmo",
  desc = "I centauri hanno attaccato la nostra carovana e sono l'unico a essermi salvato! Il mio ingranaggio migliore ce l'ha al collo una pantera rara ma potente, che gli fa la guardia. Ah! Davanti a questa belva feroce tremano persino i centauri!$B$BTieni, ecco la chiave della gabbia. Si sono presi tutto quello che c'era, ma la pantera l'hanno lasciata stare. Uccidi la belva, riportami il mio ingranaggio ipercapacitante e ti ricompenserò.$B$BLa carovana distrutta la trovi appena a nord di qui.",
  obj = "Uccidi la belva e riporta l'Hypercapacitor Gizmo e la Panther Cage Key a Wizlo Bearingshiner.",
  progress = "Ce l'hai il mio ingranaggio ipercapacitante?",
  reward = "Il mio ingranaggio ipercapacitante! Avrò da fare per un po', finché non capisco a cosa serve...",
  en_title = "Hypercapacitor Gizmo",
  en_obj = "Slay the beast and bring back the Hypercapacitor Gizmo and Panther Cage Key to Wizlo Bearingshiner.",
}
T[5152] = {
  title = "Zia Marlene",
  desc = "Oh, quanto mi sento sola! Dov'è la mia famiglia? La zia Marlene mi ha detto di restare qui, poi se n'è andata e non è più tornata! E papà... l'hai visto?$B$BForse la zia Marlene sa dov'è. Abita vicino ad Andorhal, in una casa a sud. Credo che fosse su una collina... me l'ha detto lei, che era su una collina.$B$BTi prego, $N. Sei $Gil mio nuovo amico:la mia nuova amica;! Andresti a parlare con la zia per me?",
  obj = "Parla con Marlene, a sud di Ruins of Andorhal.",
  reward = "Hai visto Pamela? Come sta? È viva?? Oh, no! Povera Pamela! Era così giovane, una bambina così felice...$B$BNon sa che cosa è successo a suo padre, vero? A mio fratello, Joseph?$B$BNo... non potrebbe capire che cosa è successo a Joseph. E anche se ci riuscisse, non avrei il cuore di dirglielo...",
}
T[5153] = {
  title = "Una Strana Storica",
  desc = "Vorrei tanto che Joseph tornasse a stare con sua figlia, ma non è possibile. Lo Scourge gli ha distorto l'anima e l'ha trasformato in un mostro. Oh, è condannato!$B$BMa forse possiamo cambiare il suo destino.$B$BQui fuori, fra le tombe, cerca il monumento di Joseph. Il corpo lì non c'è, perché anni fa è stato calpestato e distrutto, ma sotto il monumento c'è la sua fede nuziale. Porta quella fede a Chromie... una gnoma strana, con dei poteri molto strani.$B$BChromie alloggia nella locanda in rovina, nell'angolo nord-ovest di Andorhal.",
  obj = "Porta la Joseph's Wedding Ring a Chromie.",
  progress = "La tua visita arriva con un curioso tempismo. Non vieni dal futuro, vero?",
  reward = "Cos'è? Una fede nuziale? Fammi vedere...$B$BAh! Un tempo questo anello stava al dito di un grand'uomo, un uomo dal passato molto tragico.$B$BSei qui per aiutarlo? Ormai per lui è troppo tardi... ma forse possiamo aiutarlo nel passato!",
}
T[5154] = {
  title = "Gli Annals of Darrowshire",
  desc = "Per salvare Joseph Redpath dobbiamo prima scoprire il suo passato, e possiamo farlo con gli Annals of Darrowshire, un libro custodito nel municipio di Andorhal.$B$BPortami quel libro. Così sapremo qual è il destino di Joseph e, con un po' di fortuna... potremo cambiarlo!",
  obj = "Porta gli Annals of Darrowshire a Chromie ad Andorhal.",
  progress = "Hai trovato il libro, $N?",
  reward = "Ben fatto, l'hai trovato!$B$BL'hai letto? Parla di Joseph Redpath? Se è così, forse possiamo salvarlo!$B$BAh. Gli Annals of Darrowshire raccontano una storia molto inquietante. Dicono che durante la battaglia Joseph Redpath è stato corrotto ed è passato fra le file dello Scourge! Poi ha tradito i difensori di Darrowshire.$B$BÈ un brutto destino. Se ci riusciamo, dovremmo provare a cambiarlo, non credi?",
}
T[5155] = {
  title = "Forze di Jaedenar",
  desc = "Se devo fidarmi di te in questa faccenda, prima dovrai dimostrarmi quanto vali.$B$BDevo sapere che sei $Gun nemico:una nemica; dello Shadow Council — i responsabili di molti mali, qui e altrove.$B$BAddentrati in Felwood. A ovest vedrai un sentiero che porta a Jaedenar: è lì che il Consiglio trama con la Burning Legion.$B$BScendi nelle profondità di una delle Barrow Dens corrotte dove vivono e uccidi quelli della loro specie. Quando l'avrai fatto, torna da me: allora saprò che vuoi davvero aiutarci.",
  obj = "Entra a Jaedenar e uccidi 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts e 6 Jaedenar Cultists, poi torna da Greta Mosshoof a Felwood.",
  progress = "Come va la battaglia, $N? So che a qualcuno può disgustare l'idea di versare sangue come prova d'onore, ma devi capire che serve a due scopi: riducendo il loro numero mi rendi il compito più facile, e intanto fra noi nasce un rispetto reciproco che in futuro non potrà che renderci più forti.$B$BSpero che tu capisca.",
  reward = "Bene, $N! Ora che sono sempre di meno, possiamo incalzarli ancora di più.$B$BCom'è stato questo primo assaggio del loro potere? Erano forti come pensavi? Di più? O forse per te non sono stati affatto una sfida. Non sarebbe notevole?$B$BDei dettagli delle tue imprese potremo parlare più tardi. Adesso abbiamo altro a cui pensare.",
}
T[5156] = {
  title = "Verificare la Corruzione",
  desc = "A nord, sul lato est della strada, c'è un posto che chiamano Shatter Scar Vale: lì, durante l'ultima grande guerra, gli infernals sono stati fatti piovere dal cielo. I crateri sfregiano ancora la terra, e gli infernals continuano a fare lo stesso.$B$BDue cose mi incuriosiscono. La prima: ci sono ancora elementali entropici che vagano da quelle parti? E la seconda: i crateri sono ancora pieni dell'acqua fetida e corrotta che ci si è raccolta anni fa? Mi aiuti a controllare, $N? Ma fai attenzione, gli infernals distruggono tutto quello che trovano sulla loro strada.",
  obj = "Cerca e distruggi 2 Entropic Beasts e 2 Entropic Horrors mentre esplori Shatter Scar Vale. Dopo aver controllato se i crateri sono ancora pieni di acqua vile corrotta, torna da Taronn Redfeather a Felwood.",
  progress = "Spero che la ricerca stia andando bene, $N. Io non mi sono ancora spinto così a nord e, lo ammetto, l'idea di trovarmi prima o poi sulla strada di un infernal mi spaventa un pochino. Quelle creature non hanno cervello, ma fanno comunque una certa impressione.",
  reward = "Bene che tu sia $Gvivo:viva;, $N. Male, invece, che l'acqua sia ancora lì. Speravo di trovare almeno una fonte d'acqua pura qui a Felwood. A quanto pare, la mia ricerca è fallita. Se ci fosse stata, guarire la terra sarebbe stato molto più facile.$B$BDovrò pensare a salvare le creature della foresta che posso, e a distruggere quelle ormai tanto corrotte da essere un pericolo per se stesse quanto per chi viaggia attraverso questi boschi un tempo possenti.",
}
T[5157] = {
  title = "Raccolta dell'Acqua Corrotta",
  desc = "Nel cuore di Jaedenar si trova lo Shadow Hold — la loro fortezza principale, sede della loro corruzione e della loro malvagità.$B$BLo Shadow Council ha circondato il suo covo di incantesimi protettivi che hanno la forma di bracieri. Se voglio sapere di più sul nostro nemico con la divinazione, bisogna spegnere quei bracieri: così dovrei riuscire a spiare il Consiglio e scoprire chi lo guida.$B$BSe puoi, prendi questa borraccia e riempila al Moon Well che si trova in mezzo a Jaedenar. Poi torna da me.",
  obj = "Porta l'Empty Canteen a Moon Well al centro di Jaedenar e riempila, poi torna da Greta Mosshoof a Felwood.",
  progress = "Quando avremo l'acqua del Moon Well, la purificheremo e la useremo per spegnere i bracieri di protezione dentro lo Shadow Hold. Così dovrei avere tutto il tempo di spingere lo sguardo ancora più a fondo in quelle sale e capire chi guida davvero questo... culto.$B$BPrego che la Madre Terra sia con noi.",
  reward = "Questa andrà benissimo, $N.$B$BOra, a parte versare l'acqua sui bracieri, ci resta solo da farla purificare. Non dovrebbe essere difficile — probabilmente basterà un piccolo viaggio.$B$BSperiamo di farcela in fretta.",
}
T[5158] = {
  title = "In Cerca di Aiuto Spirituale",
  desc = "Porta l'acqua corrotta nelle Barrens, $N. A sud di Ratchet, nascosta lungo la riva, c'è una mia vecchia amica, una sciamana di nome Islen Waterseer. È potente, e ci aiuterà: il suo legame con gli spiriti dell'acqua è sempre stato forte. Il nostro è un compito nobile, e questo dovrebbe bastare a convincere lei e gli spiriti a darci una mano.$B$BDovresti trovarla in un piccolo accampamento proprio in riva all'acqua. E, $N, non badare ai pirati... per te sono solo una seccatura, non una minaccia.",
  obj = "Porta l'Acqua Corrotta di Moon Well a Islen Waterseer nelle Barrens.",
  progress = "Sento che non sei $Gun semplice viaggiatore:una semplice viaggiatrice; in cerca della strada per Ratchet. Vieni, siediti e riposati nel nostro accampamento. Parlami quando sarai $Gpronto:pronta;.",
  reward = "Ah, hai bisogno che l'acqua di questo Moon Well venga purificata. Fermare questa forza malvagia a Felwood mi sembra un fine abbastanza nobile, ma non sta a me decidere se purificarla. Lo chiederò agli spiriti dell'acqua — saranno loro a giudicare se la causa è giusta.$B$BDammi un momento e porterò loro la tua supplica. Spero che siano favorevoli alla tua causa quanto lo sono io.",
}
T[5159] = {
  title = "L'Acqua Purificata Torna a Felwood",
  desc = "Ringrazia gli spiriti, $N: sono stati loro ad aiutarti, non io.$B$BAdesso ti affido quest'acqua purificata. Porta a Greta i miei saluti e i miei auguri migliori, ti prego. Ha davanti qualcosa di più grande di molti di noi... e presto se ne accorgerà, ne sono certa.$B$BLo Shadow Council non è una forza da prendere alla leggera, $N. Tienilo a mente.$B$BE ora va'. Prendi l'acqua e torna da Greta.",
  obj = "Porta l'Acqua Purificata di Moon Well a Greta Mosshoof, a Felwood.",
  progress = "Ah, vedo che sei $Gtornato:tornata;, $N. Bene. Hai trovato Islen nelle Barrens, o dobbiamo cercare un'altra strada per raggiungere i nostri obiettivi?",
  reward = "Quest'acqua dovrebbe bastarci, e anche di più, per i nostri scopi.$B$BMi fa piacere sapere che Islen è riuscita ad aiutarci. Con gli spiriti dell'acqua ha sempre avuto una grande forza. Ed è anche saggia: di rado gli spiriti non approvano i suoi propositi. Che entrambi abbiano benedetto il nostro compito mi fa sperare che siamo sulla strada giusta.",
}
T[5160] = {
  title = "La Matrona Protettrice",
  desc = "Mettiti in viaggio per Kalimdor, $R. Il nostro stormo dimora nelle terre gelide di Winterspring: quando arriverai a Winterspring, cerca le caverne di Mazthoril.$B$BSui pavimenti ghiacciati di Mazthoril troverai delle rune color cobalto. Tieni in mano una delle mie scaglie, mettiti sopra una runa e sarai $Gtrasportato:trasportata; da Haleh, la nostra matrona protettrice.$B$BConsegnale la scaglia: così potrà scrutare ciò che ho visto e percepito qui, in questo luogo condannato.",
  obj = "Viaggia fino a Winterspring e trova Haleh. Consegnale la scaglia di Awbee.",
  progress = "Che bello vederti, $N.",
  reward = "Gli Aspetti insistono perché restiamo fuori dalle faccende dei mortali, ma in questo mondo non sempre si può — soprattutto quando uno dei nostri ignora con disprezzo tali editti.",
}
T[5161] = {
  title = "L'Ira del Blue Flight",
  desc = "Comprendiamo ciò che la maledetta progenie di Deathwing cerca di fare, e sappiamo che non dobbiamo permetterlo.$B$BLa montagna Blackrock protegge Nefarian, e per questo intervenire è diventato per noi sempre più difficile.$B$BPossiamo però darti potere, mortale — se lo vorrai.$B$BIl cammino che ti aspetta è pieno di pericoli, e sta a te decidere se accettare il nostro aiuto. Pensaci, e torna da me quando avrai deciso.",
  obj = "Parla con Haleh se vuoi proseguire.",
  reward = "Così sia...",
}
T[5162] = {
  title = "L'Ira del Blue Flight",
  desc = "Controllo l'arcano, ed è l'arcano che ti manderà alla tua prossima meta.$B$BIl viaggio comincerà quando sarai $Gpronto:pronta;: andrai nelle Plaguelands a parlare con Jeziba.$B$BÈ un mortale saggio come gli antichi, paziente come la terra immobile. Lo troverai ad Andorhal.",
  obj = "Parla con Jeziba nelle Plaguelands. Risiede ad Andorhal.",
  reward = "Sono Jeziba, e per molti sono lo Scultore. Ma io non scolpisco statue: scolpisco eroi.",
}
T[5163] = {
  title = "Siamo Arrivati, Yeti?",
  desc = "È tutto pronto, $N!$B$BHo già scritto ai miei amici per dirgli che ho una sorpresa per loro. E qui entri in gioco tu!$B$BTi do il mio mechanical yeti: andrai a trovare i miei amici uno per uno e li prenderai alla sprovvista, accendendo lo yeti e mandandoglielo contro.$B$BQuando l'avrai fatto vedere a Legacki a Everlook, a Sprinkle a Gadgetzan e a Quixxil a Marshal's Refuge, torna a raccontarmi com'è andata!$B$BE poi riportami anche il mio yeti, per favore.",
  obj = "Prendi l'Umi's Mechanical Yeti e spaventa i suoi amici:$B$BLegacki a Everlook (Winterspring)$BSprinkle a Gadgetzan (Tanaris)$BQuixxil a Marshal's Refuge (Un'Goro Crater)$B$BQuando hai finito, riporta il Mechanical Yeti a Umi.",
  progress = "Non vedo l'ora di sapere come reagiscono i miei amici!$B$BNon se lo aspetteranno mai!",
  reward = "Ah! Ci penseranno due volte prima di prendere ancora in giro le mie idee!$B$BGrazie dell'aiuto, $N. Senza di te non mi sarei divertita così tanto!",
}
T[5164] = {
  title = "Catalogue of the Wayward",
  desc = "Haleh non avrebbe potuto scegliere uno strumento di giustizia migliore. Leggi il catalogo degli smarriti e sarai $Gilluminato:illuminata;.$B$BSe persevererai... se farai quello che ti viene chiesto... se sopravvivrai... diventerai $Gun eroe:un'eroina;.",
  obj = "Leggi il Catalogue of the Wayward.",
  reward = "Il grosso di questo libro è fatto di centinaia e centinaia di pagine piene di testo e simboli confusi.",
}
T[5165] = {
  title = "Spegnere le Fiamme della Protezione",
  desc = "Ora devi tornare a Jaedenar. Con ogni probabilità i bracieri sono sparsi per tutto lo Shadow Hold: spegni le fiamme di ognuno, e le protezioni innalzate dal Council cadranno, almeno per poco. Io aspetterò quel momento, e quando arriverà scruterò a fondo l'Eremo per cercare di scoprire chi è la testa di questa bestia. Allora, e solo allora, vedremo di attaccarli direttamente.",
  obj = "Usando l'Acqua Purificata di Moon Well, spegni le fiamme dei quattro bracieri di protezione in Shadow Hold, a Felwood, poi torna da Greta Mosshoof in Emerald Sanctuary.",
  progress = "Se vogliamo avere qualche speranza di prepararci a una battaglia molto più grande, i bracieri vanno spenti. Entrare nella tana del drago senza sapere nulla è un'impresa da sciocchi, e questo è molto peggio di un drago. Lo Shadow Council ha sulla coscienza, da solo, un gran numero di crimini e di atrocità. Se vogliamo fermarli, dovremo muoverci in fretta.",
  reward = "Non appena le fiamme dell'ultimo braciere si sono spente, sono riuscita a vederti con i miei incantesimi. Ben fatto, $N.$B$BPrima che gli stregoni dello Shadow Council riuscissero a rilanciare i loro incantesimi, sono venuta a sapere alcune cose. Spero che basti.$B$BPer ora riposati. Tra un momento ti dirò cosa ho scoperto.",
}
T[5166] = {
  title = "Corazza dello Stormo Cromatico",
  desc = "Forgiare una corazza potente, che protegga dagli attacchi incessanti dello stormo cromatico, è un'impresa che poggia sull'ironia.$B$BLe scaglie delle stesse bestie che combattiamo vanno cucite sul carapace intatto di un drake o drago cromatico anziano. Per ora non se ne conosce nessuno, e c'è da sperare che non ne esistano mai.$B$BInfine, il componente forse più difficile di tutti: il blood of heroes.$B$BE alla fine sarà lo Scultore a forgiare questa creazione.",
  obj = "Per forgiare la Corazza dello Stormo Cromatico, dovrai portare questi oggetti a Jeziba lo 'Scultore':$B$B1 Carapace Cromatico.$B$B10 Brilliant Chromatic Scales.$B$B10 Blood of Heroes.$B$B10 Frayed Abomination Stitchings.",
  progress = "Hai scelto saggiamente, $R.",
  reward = "Non l'hai ancora capito? Il viaggio era la meta. Non le senti, le cicatrici della battaglia? E il dolore che hai sopportato?$B$BHai superato la prova, e ora sei un essere più potente. Molto più potente. Questa corazza non è che un riflesso delle tue capacità innate.",
}
T[5167] = {
  title = "Gambiere dello Sfidante Cromatico",
  desc = "Come base dei gambali serve il carapace di un drake cromatico adulto. Sul telaio di filo metallico si dispongono poi a strati le Brilliant chromatic scales, incantate nel blood of heroes. Per finire, all'interno degli schinieri va applicata la morbida skin of shadow.",
  obj = "Per forgiare le Gambiere dello Sfidante Cromatico, dovrai portare questi oggetti a Jeziba lo 'Scultore':$B$B1 Carapace Cromatico.$B$B10 Brilliant Chromatic Scales.$B$B10 Blood of Heroes.$B$B5 Skin of Shadow.",
  progress = "Nessuno ha mai realizzato un oggetto simile!",
  reward = "Quando entrerai nelle loro sale, $N, sentiranno l'odore dei loro simili. Schiacciali con la loro stessa paura!",
}
T[5168] = {
  title = "Eroi di Darrowshire",
  desc = "Gli eroi di Darrowshire li porto nel cuore, e le loro storie sono tutte nel libro che mi hai portato, gli Annals of Darrowshire.$B$BC'è il paladino Davil Lightfire, e c'è il suo libro, che la Crociata ha portato al municipio di Hearthglen.$B$BE in quelle pagine c'è anche mio fratello, Captain Redpath. Dopo che ha tradito, hanno incrinato il suo scudo e l'hanno gettato via, e adesso sta nel posto che meno ti aspetteresti — vicino al fienile del Gahrron's Withering.$B$BRaccogli queste reliquie, $N. Il destino e la tragedia le circondano.",
  obj = "Porta il Davil's Libram e il Redpath's Shield a Carlin Redpath.",
  progress = "Hai con te le reliquie, $N?",
  reward = "Hai il libro e lo scudo!$B$BLa loro storia si intreccia con quella di Darrowshire. Non so spiegarlo, ma sono certo che il destino li riunirà.",
}
T[5181] = {
  title = "I Malvagi di Darrowshire",
  desc = "Gli Annals of Darrowshire parlano dei malvagi di quella battaglia. Raccontano che durante lo scontro le forze dell'Alleanza hanno distrutto Horgus the Ravager, il signore dei ghoul. Il suo corpo l'hanno gettato in un lago a nord-ovest di Corin's Crossing, e il teschio è ancora lì.$B$BMarduk the Black non è mai stato sconfitto, ma la sua leggendaria spada è stata infranta e si è persa: giace sul fondo della gola a ovest di Corin's Crossing.$B$BRecupera questi oggetti, $N. Non so dirti perché, ma sono certo che il loro destino è legato a te.",
  obj = "Porta lo Skull of Horgus e la Shattered Sword of Marduk a Carlin Redpath alla Cappella della Speranza della Luce.",
  progress = "Allora, $N, hai trovato il teschio e la spada?",
  reward = "Li hai trovati! Ben fatto, $N! Queste reliquie racchiudono un potere che non comprendo fino in fondo, e che un giorno saprai sfruttare.$B$BMi riportano alla mente anche ricordi oscuri, di morte e di tradimento, e dell'ultima notte di Darrowshire...",
}
T[5201] = {
  title = "Intrusione dei Winterfall",
  desc = "Ai più la mia presenza sfugge, $N. Qui a Winterspring, però, c'è una seccatura che sembra aver messo radici: i furbolg Winterfall.$B$BIo non ho mai attaccato i furbolg direttamente, eppure sembrano impazziti, spaventati da qualunque cosa incontrino sul loro cammino. Li ho visti uccidere innumerevoli creature che per sfortuna si trovavano nel posto sbagliato al momento sbagliato.$B$BSono stanco delle loro intromissioni — ti prego, aiutami a contrattaccare. Uccidi i furbolg e tienili lontani dalla Frostsaber Rock.",
  obj = "Rivern Frostwind vuole che tu uccida 5 Winterfall Shaman e 5 Winterfall Ursa.",
  progress = "Sembrano così paranoici, i furbolgs...",
  reward = "Mi solleva sapere che, almeno per un po', l'intrusione dei Winterfall non sarà più un nostro pensiero.$B$BStai cominciando a dare prova di perseveranza, $N.",
}
T[5202] = {
  title = "Una Strana Chiave Rossa",
  desc = "La piccola chiave rossa sembra fatta di una specie di osso: pesa in mano, eppure pare molto fragile. Perché mai un membro dello Shadow Council dovrebbe tenersi una cosa del genere? Forse a Jaedenar c'è qualcosa che questa strana chiave può aprire.",
  obj = "Esplora Jaedenar per scoprire a cosa serve la Blood Red Key.",
  progress = "Comincio a chiedermi se riuscirò mai a fuggire da questa gabbia.$B$BPrima o poi mi sacrificheranno ai demoni che adorano, quali che siano: è solo questione di tempo. Mostri!",
  reward = "Hai trovato la chiave! Ti prego, dammela: finalmente potrò fuggire!",
}
T[5203] = {
  title = "Salvataggio da Jaedenar",
  desc = "Ma per quanto mi addolori, prima di tutto c'è una cosa da fare: devo trovare Lightforge, la spada di Trey, e fuggire dallo Shadow Hold per far sapere ai miei superiori cosa sta succedendo qui. Mi aiuti, $N?$B$BIl nostro equipaggiamento è poco lontano, e hai già dimostrato di saper sopravvivere al sentiero che sale fino in cima.$B$BUna volta fuori andrò a Darnassus, se riesci a trovare la mia amica Jessir vicino al confine con Ashenvale. Doveva incontrarsi con noi all'accampamento dell'Emerald Circle, lì vicino.$B$BChe ne dici, $N? Mi aiuti ancora una volta?",
  obj = "Scorta Arko'narin fino al luogo in cui sono custoditi Lightforge e il suo equipaggiamento, poi proteggila mentre fuggi dallo Shadow Hold. Dopodiché cerca Jessir Moonbow a Felwood per farle sapere cosa è successo ai suoi amici.",
  progress = "Sembri $Gaffannato:affannata;, $N. Va tutto bene o c'è qualcosa che non va?",
  reward = "Sei tu che hai aiutato Arko a fuggire? Sono proprio contenta che tu mi abbia trovata. È passata di qui poco fa, diretta a Darnassus. Aveva con sé Lightforge e non si è fermata nemmeno a parlare con i druidi per farsi curare: ha detto che era troppo urgente.$B$BMi ha raccontato però del vostro incontro con lo spirito di Trey. Che destino terribile per un Cavaliere della Silver Hand. Non lo ha dato a vedere, ma so che il pensiero di aver perso uno dei suoi amici più cari la sta distruggendo dentro.",
}
T[5204] = {
  title = "Il Castigo della Luce",
  desc = "Vorrebbe far finta di stare bene, farmi credere di essere abbastanza forte da affrontare tutto questo da sola, ma so che non è così. La morte di Trey e il racconto delle torture che ha subito la tormenteranno a lungo, e non c'è niente che possiamo fare per impedirlo. Un po' di pace, però, possiamo dargliela!$B$B$N, torna allo Shadow Hold, uccidi l'aguzzino di Trey e trova i suoi resti. Niente ci impedisce di chiudere tutte queste questioni in sospeso, mentre Arko'narin piange in privato, a modo suo.",
  obj = "Torna a Jaedenar e uccidi la succube Rakaiah prima di trovare i Resti di Trey Lightforge.",
  progress = "Esamini il corpo: non c'è dubbio, sono i resti del Cavaliere della Silver Hand Trey Lightforge. Per un attimo pensi ad Arko'narin, e ti chiedi se qualcuno nella tua vita abbia mai contato per te quanto quest'uomo contava per la prigioniera Elfa della notte che da poco hai aiutato a fuggire dallo Shadow Hold.$B$BDopo esserti $Gpreso:presa; ancora un momento per riordinare i pensieri, sai che non puoi riportare i resti del paladino a Jessir senza aver prima ucciso il suo aguzzino.",
  reward = "Raccogli i resti del paladino con tutta la cura che puoi, ricordando che almeno il suo spirito è stato liberato da ogni dolore o sofferenza che possano avergli inflitto.",
}
T[5206] = {
  title = "Predoni di Darrowshire",
  desc = "Chromie mi ha detto che le reliquie che hai raccolto sono reagenti per un potente incantesimo, ma ne manca ancora uno: i teschi dei membri dello scourge che hanno preso parte alla battaglia di Darrowshire.$B$BPrendi questo cristallo e dai la caccia agli scourge champions per prendere i loro teschi. Il cristallo è incantato: passalo sopra un teschio, e se il campione ha preso parte alla battaglia, il teschio echeggerà. Portami quei resonating skulls.$B$BVai, $N. Gli scourge champions li trovi a nord, nella Noxious Glade, e a ovest, nella Fungal Vale.",
  obj = "Porta 5 Resonating Skulls e il Mystic Crystal a Carlin Redpath nelle Eastern Plaguelands.",
  progress = "Hai i teschi? Chromie ha detto che saranno fondamentali per il suo incantesimo, quello che ci darà la possibilità di salvare Darrowshire.",
  reward = "Li hai trovati! Magnifico!$B$BNon capisco del tutto come possano aiutarci, ma ne avverto il potere, e sento nelle ossa che sono legati a Darrowshire, il mio villaggio natale.",
}
T[5210] = {
  title = "Fratello Carlin",
  desc = "La mia magia ha aggiunto nuove pagine in fondo agli Annals of Darrowshire, e ora la storia che raccontano va oltre la battaglia. In uno dei nuovi passi si parla di un altro Redpath, Carlin, sopravvissuto al tradimento di Joseph. Adesso Carlin è nelle Plaguelands a est, alla Cappella della Speranza della Luce.$B$BPrendi il libro e parlagli.",
  obj = "Porta gli Extended Annals of Darrowshire a Carlin Redpath in Eastern Plaguelands.",
  progress = "Arrivi da ovest? Come va nel resto di Lordaeron? Che Andorhal è perduta lo so, ma lo Scourge è già arrivato fino alla bella Tirisfal?",
  reward = "Che libro è questo? Gli Annals of Darrowshire? Prima della guerra quella era casa mia... casa mia, prima della battaglia che l'ha distrutta! Perché mi hai portato questo libro?$B$BMa guarda qui! In fondo ci sono pagine sui giorni dopo la battaglia! Ecco un passo che parla di me! E un altro su mio fratello Joseph! Quello che c'è scritto è vero?$B$BDobbiamo scoprire la verità!",
}
T[5211] = {
  title = "Difensori di Darrowshire",
  desc = "Nella battaglia di Darrowshire sono caduti tanti difensori. E tanti adesso vagano di nuovo come orrendi servitori dello Scourge! Trova quelle povere anime e metti fine alla loro sofferenza!$B$BDai la caccia ai cannibal ghouls, ai gibbering ghouls e ai diseased flayers. Molti di quei mostri un tempo erano la brava gente di Darrowshire: se ne distruggi i corpi, ne libererai le anime.$B$BLi troverai nella Plaguewood, a Corin's Crossing e nelle altre roccaforti che lo Scourge ha nelle Eastern Plaguelands.",
  obj = "Libera 15 Darrowshire Spirits e torna da Carlin Redpath.",
  progress = "In sogno i poveri difensori di Darrowshire gridano verso di me, $N. Devi liberarli!",
  reward = "Mi fa piacere sapere che hai trovato le anime tormentate dei miei compagni e le hai liberate. Ora che almeno alcuni dei difensori di Darrowshire non languono più nella vile servitù dello Scourge, il mio cuore piangerà meno.",
}
T[5212] = {
  title = "La Carne Non Mente",
  desc = "Al mondo non ci sono solo gli speziali Forsaken ad aver studiato le scienze.$B$BSono anni che studio la pestilenza, $R. Credevamo che si stesse indebolendo, ma quello che ho scoperto qui nelle Plaguelands è sorprendente. A quanto pare diventa sempre più forte!$B$BDevo fare altri esperimenti! La fonte più potente della pestilenza è la carne contaminata degli ultimi contagiati. Vai a Stratholme e portami dei campioni, $N.",
  obj = "Recupera 20 Plagued Flesh Samples a Stratholme e portali a Betina Bigglezink. Sospetti che qualunque creatura di Stratholme possa avere il suddetto campione di carne.",
  progress = "C'è chi dice che mi preoccupo troppo — e io gli rispondo: 'Voi non vi preoccupate abbastanza!'",
  reward = "Nella struttura chimica degli agenti attivi della pestilenza è cambiato qualcosa. Ci vogliono altri dati.",
}
T[5213] = {
  title = "L'Agente Attivo",
  desc = "Devi spingerti più a fondo in Stratholme, $N.$B$BPassati i primi cancelli, troverai gli ziggurat. Sappiamo che lo Scourge trae un grande potere da quelle costruzioni. Esplorali e torna con tutte le informazioni che riesci a scoprire.",
  obj = "Recati a Stratholme ed esplora gli ziggurat. Trova i nuovi Scourge Data e portali a Betina Bigglezink.",
  progress = "Manca poco e scopriremo che cos'è questo nuovo agente attivo della pestilenza!",
  reward = "Straordinario! Ci vorranno mesi per sezionare e analizzare tutto quanto. The Argent Dawn ti ringrazia per il tuo impegno, $N.$B$BScegli, con la nostra benedizione, fra questo Seal of the Dawn e questa Runa dell'Alba. Puoi usare l'uno o l'altra al posto di un normale Argent Dawn Commission per raccogliere pietre del flagello per noi. Se perdi il tuo, vieni a parlarmi e te ne procuro un altro.",
}
T[5214] = {
  title = "Il Grande Fras Siabi",
  desc = "Una cosa terribile... quello che è capitato a Fras. Vedi, quando hanno saccheggiato la città, Fras non voleva lasciarsi dietro la sua preziosa merce. L'ultima cosa che gli ho sentito dire è stata: 'Brucerò fino all'ultima foglia prima che ci mettano sopra le loro dannate mani sporche!'$B$BUn buon sigaro mi piacerà pure, ma sciocco non sono. Quel giorno me ne sono andato e ho lasciato Fras col suo delizioso negozio. Immagino che sia finito tra le fiamme, ma se c'è anche solo la possibilità che una scatola del suo famoso tabacco sia ancora intatta...$B$BChe ne dici, $N? Me la trovi una scatola per il vecchio Smokey?",
  obj = "Trova il negozio di tabacchi di Fras Siabi a Stratholme e recupera una scatola di Siabi's Premium Tobacco. Torna da Smokey LaRue quando il lavoro è fatto.",
  progress = "Non ce la faccio più, $N! Mi devi aiutare! Sto morendo!",
  reward = "Oh, dolce, dolce sigaro, quanto mi sei mancato...",
}
T[5215] = {
  title = "The Scourge Cauldrons",
  desc = "Nelle terre di quella che un tempo era Lordaeron ci sono otto calderoni — quattro qui a ovest e altri quattro, nascosti, a est. Sputano veleni nell'aria e spargono la piaga per tutta la regione, al servizio dello Scourge.$B$BSpegnerli del tutto non possiamo: il potere negromantico di Kel'Thuzad è troppo forte. Crediamo però di avere un modo per volgerli a nostro vantaggio. Per questo incarico farai capo alla mia vice, High Priestess MacDonnell: il resto te lo spiegherà lei.",
  obj = "Parla con High Priestess MacDonnell a Chillwind Point, in Western Plaguelands.",
  reward = "Che il potere della Luce risplenda su di te in questi tempi bui, $C. Sono lieta di guidarti nel nostro piano per sabotare i calderoni dello Scourge.$B$BQuello che vogliamo è cambiare la composizione della piaga che esce dai calderoni, fino a farne qualcosa che danneggi lo Scourge. Per riuscirci dovrai assicurarti l'accesso a ognuno dei quattro calderoni delle Western Plaguelands.$B$BTieniti $Gpronto:pronta;, $Geroe:eroina;: ti aspetta una gloriosa battaglia contro il vile Scourge!",
}
T[5216] = {
  title = "Obiettivo: Felstone Field",
  desc = "Fra i quattro calderoni qui a ovest, il più accessibile potrebbe essere quello del Felstone Field: le truppe che lo Scourge tiene lì sono meno esperte, anche se non vanno sottovalutate.$B$BVa' al Felstone Field, a nordovest di Andorhal, e affronta il signore del calderone che sta lì: crediamo che abbia una chiave per accedere al calderone. Appena l'avrai aperto, usa questa bottiglia per prendere un campione dei veleni che ci sono dentro; dovremo studiarlo per sviluppare un antidoto.",
  obj = "Vai a Felstone Field, in Western Plaguelands, per trovare e sconfiggere il Signore del Calderone che si trova lì. Potrebbe avere una chiave per accedere al calderone. Devi avere con te l'Empty Felstone Field Bottle per prendere un campione dei veleni usati nel calderone.",
  progress = "Un pannello d'accesso al calderone non cede: è chiuso saldamente. Per aprirlo dovrai trovare la chiave.",
  reward = "La chiave presa a Cauldron Lord Bilemaw apre alla perfezione il pannello d'accesso. Ne esce un fetore orribile, e dentro il calderone turbina una miscela sconosciuta di sostanze concentrate.$B$BLa bottiglia entra abbastanza bene sotto un piccolo rubinetto, e puoi prendere un campione per High Priestess MacDonnell, a Chillwind Point.",
}
T[5217] = {
  title = "Ritorno a Chillwind Camp",
  desc = "Riempi la bottiglia con l'intruglio velenoso del calderone, quanto basta per avere un campione da studiare.$B$BCon il veleno in mano, è ora di tornare da High Priestess MacDonnell a Chillwind Camp e portare a termine la missione.",
  obj = "Porta la Filled Felstone Field Bottle a High Priestess MacDonnell a Chillwind Camp, in Western Plaguelands.",
  progress = "$GBentornato:Bentornata; nella relativa sicurezza di Chillwind Camp, $N. A che punto sei con i calderoni?",
  reward = "Ben fatto, $N — ad Alchemist Arbington dovrebbe bastare pochissimo per analizzarlo e preparare un antidoto da mettere nel calderone. Se riusciamo a pomparne abbastanza nell'aria, potremmo indebolire tutto lo Scourge che c'è qui.$B$BCi aspetta senza dubbio una lunga fatica: dovremo colpire questi calderoni di continuo e aggiungere i nostri reagenti alla loro miscela. Ma se riusciamo a continuare così, quando arriverà il momento della battaglia avremo un enorme vantaggio sullo Scourge!",
}
T[5218] = {
  title = "Calderone del Felstone Field",
  progress = "Davanti a te si erge il calderone della piaga dello Scourge, che sputa tossine nell'aria in enormi quantità. Alla base della sua vasta piattaforma c'è un piccolo pannello d'accesso anonimo.$B$BOra che hai sconfitto il signore del calderone e hai preso la chiave, puoi aggiungerci i reagenti adatti a creare un antidoto alla piaga.",
  reward = "Appena aggiungi i reagenti alla miscela, la nube che esce dal calderone comincia a cambiare colore e consistenza. Persino le forze del Flagello che si trovano appena nei paraggi sembrano ritrarsi, mentre i nuovi componenti si diffondono nell'aria.",
}
T[5219] = {
  title = "Obiettivo: Dalson's Tears",
  desc = "Uno dei calderoni della piaga sta nel campo di una vecchia fattoria che adesso chiamano Dalson's Tears. Ebbene, oggi di lacrime non ne verseremo: fermeremo lo Scourge e lo faremo soffocare con i suoi stessi fumi!$B$BVa' alle Dalson's Tears, quasi esattamente a nord di Andorhal, ed elimina il signore del calderone che sta lì. Come l'altro, dovrebbe avere una chiave che ti aprirà il calderone. Prendine un campione con questa bottiglia: ognuno usa una sua miscela di tossine.",
  obj = "Vai a Dalson's Tears, in Western Plaguelands, per trovare e sconfiggere il Signore del Calderone che si trova lì, e usa la sua chiave per accedere al calderone. Devi avere con te l'Empty Dalson's Tears Bottle per prendere un campione dei veleni usati nel calderone.",
  progress = "Un pannello d'accesso al calderone non cede: è chiuso saldamente. Per aprirlo dovrai trovare la chiave.",
  reward = "La macabra chiave trovata sul signore del calderone scivola senza fatica in una serratura e poi scompare, lasciandoti l'accesso al calderone per sempre. Nella struttura alla base del calderone, icori grezzi e viscosi pulsano dentro tubi contorti.$B$BLa bottiglia entra abbastanza bene sotto un piccolo rubinetto, e puoi prendere un campione per High Priestess MacDonnell, a Chillwind Point.",
}
T[5220] = {
  title = "Ritorno a Chillwind Camp",
  desc = "Riempi con cura la bottiglia con gli icori del calderone, fino a quella che ti sembra la quantità giusta per un campione.$B$BCon il veleno in mano, è ora di tornare da High Priestess MacDonnell a Chillwind Camp e portare a termine la missione.",
  obj = "Porta la Filled Dalson's Tears Bottle a High Priestess MacDonnell a Chillwind Camp, in Western Plaguelands.",
  progress = "Sappiamo che ogni calderone usa una miscela di reagenti diversa per generare la tossina che provoca la piaga, e sappiamo anche che per ognuno dovremo sviluppare un antidoto apposta. Il tuo campione delle Dalson's Tears sarà la chiave per capire quali reagenti servono a quel calderone.",
  reward = "Ah, qui di roba da studiare ce n'è in abbondanza. Ben fatto, $N!$B$BPer ora il prossimo passo tocca a noi: dobbiamo preparare un elenco di reagenti che, mescolati a quello che c'è già nel calderone, gli facciano da antidoto.$B$BE l'unico modo per farcelo arrivare sarà mettere i reagenti direttamente nel calderone. Alchemist Arbington ti darà altre informazioni, quindi vai a parlargli appena puoi.",
}
T[5221] = {
  title = "Calderone delle Dalson's Tears",
  progress = "Davanti a te si erge il calderone della peste dello Scourge, che sputa nell'aria tossine in enormi quantità. Alla base della sua grande piattaforma c'è un piccolo pannello d'accesso anonimo.$B$BHai già sconfitto il signore del calderone e preso la sua chiave: ora puoi aggiungere i reagenti adatti e creare un antidoto alla peste.",
  reward = "Mentre aggiungi i reagenti alla miscela, la nube che il calderone sputa comincia a cambiare colore e consistenza. Anche le creature del Flagello che si trovano solo nei dintorni sembrano ritrarsi davanti ai nuovi componenti immessi nell'ambiente.",
}
T[5222] = {
  title = "Obiettivo: Writhing Haunt",
  desc = "Abbiamo aperto due calderoni, e anche se potrai accedervi per sempre, vogliamo aprire comunque gli altri due: così avremo tutti più modi per introdurre l'antidoto!$B$BStavolta colpirai il calderone di Writhing Haunt, quasi esattamente a est di Andorhal, abbastanza vicino alle mura in rovina della città. Come le altre volte, elimina il signore del calderone che sta lì e prendigli la chiave. Per il campione usa questa bottiglia.$B$BBuona caccia, $N!",
  obj = "Vai a Writhing Haunt, in Western Plaguelands, per trovare e sconfiggere il Signore del Calderone che si trova lì, e usa la sua chiave per accedere al calderone. Devi avere con te l'Empty Writhing Haunt Bottle per prendere un campione dei veleni usati nel calderone.",
  progress = "Un pannello d'accesso al calderone non cede: è chiuso saldamente. Per aprirlo dovrai trovare la chiave.",
  reward = "La chiave del signore del calderone apre il pannello d'accesso e poi scompare, proprio come quelle dei due calderoni di cui ti sei già $Goccupato:occupata;. Sotto la piattaforma del calderone ribolle con violenza una sostanza dall'odore putrido.$B$BLa bottiglia entra abbastanza bene sotto un piccolo rubinetto, e puoi prendere un campione per High Priestess MacDonnell, a Chillwind Point.",
}
T[5223] = {
  title = "Ritorno a Chillwind Camp",
  desc = "Riempi con delicatezza la bottiglia vuota, e ora nel fragile contenitore di vetro ondeggia avanti e indietro un campione della sostanza disgustosa che ribolle sotto la piattaforma del calderone.$B$BCon il veleno in mano, è ora di tornare da High Priestess MacDonnell a Chillwind Camp e portare a termine la missione.",
  obj = "Porta la Filled Writhing Haunt Bottle a High Priestess MacDonnell a Chillwind Camp, in Western Plaguelands.",
  progress = "Una volta analizzato il campione che hai preso al calderone di Writhing Haunt, avremo una terza via per scagliare sullo Scourge un antidoto devastante!",
  reward = "Un'altra missione eseguita alla perfezione, $N! Ora abbiamo tre calderoni da rivolgere contro lo Scourge. Se il dominio negromantico di Kel'Thuzad su queste terre non fosse forte come adesso, oserei dire che li spegneresti del tutto!$B$BAlchemist Arbington preparerà un rapporto su quello che servirà a questo calderone — e agli altri che abbiamo rivolto contro il nemico — per diffondere il nostro antidoto alla piaga. Detto questo, è giunto il momento di prendere il controllo dell'ultimo calderone dell'ovest!",
}
T[5224] = {
  title = "Calderone di Writhing Haunt",
  progress = "Davanti a te si erge il calderone della piaga dello Scourge, che sputa tossine nell'aria in enormi quantità. Alla base della sua vasta piattaforma c'è un piccolo pannello d'accesso anonimo.$B$BOra che hai sconfitto il signore del calderone e hai preso la chiave, puoi aggiungerci i reagenti adatti a creare un antidoto alla piaga.",
  reward = "Appena aggiungi i reagenti alla miscela, la nube che esce dal calderone comincia a cambiare colore e consistenza. Persino le forze del Flagello che si trovano appena nei paraggi sembrano ritrarsi, mentre i nuovi componenti si diffondono nell'aria.",
}
T[5225] = {
  title = "Obiettivo: Gahrron's Withering",
  desc = "L'ultimo calderone rimasto sta in una fattoria che adesso chiamano Gahrron's Withering. A sorvegliarlo ci sono alcuni dei servitori più forti dello Scourge — spettri e fantasmi, per la precisione. Non prenderli alla leggera, $N.$B$BIl Gahrron's Withering è esattamente a nordest di qui, vicino al punto dove iniziano le Eastern Plaguelands. Come le altre volte, elimina il signore del calderone che sta lì e prendigli la chiave. Ecco la tua bottiglia vuota per il campione: riportamela piena. Che la Luce ti protegga in questa missione pericolosa, $C.",
  obj = "Vai a Gahrron's Withering, in Western Plaguelands, per trovare e sconfiggere il Signore del Calderone che si trova lì, e usa la sua chiave per accedere al calderone. Devi avere con te l'Empty Gahrron's Withering Bottle per prendere un campione dei veleni usati nel calderone.",
  progress = "Un pannello d'accesso al calderone non cede: è chiuso saldamente. Per aprirlo dovrai trovare la chiave.",
  reward = "La chiave di Cauldron Lord Soulwrath si disintegra appena tocca la serratura del pannello d'accesso, alla base della piattaforma del calderone. Da dentro arriva un leggero rumore metallico, poi il pannello si apre e mostra altre tossine viscose nella struttura del calderone.$B$BLa bottiglia entra abbastanza bene sotto un piccolo rubinetto, e puoi prendere un campione per High Priestess MacDonnell, a Chillwind Point.",
}
T[5226] = {
  title = "Ritorno a Chillwind Camp",
  desc = "Guardi gli icori putridi del calderone gocciolare nella bottiglia vuota, e intanto chiudi con cura il rubinetto nel pannello di controllo.$B$BCon il veleno in mano, è ora di tornare da High Priestess MacDonnell a Chillwind Camp e portare a termine la missione.",
  obj = "Porta la Filled Gahrron's Withering Bottle a High Priestess MacDonnell a Chillwind Camp, in Western Plaguelands.",
  progress = "Il Gahrron's Withering ospita l'ultimo dei calderoni qui a ovest a cui dobbiamo accedere. Quando avremo un campione della piaga che sputa fuori, potremo introdurre i nostri reagenti nell'ambiente attraverso quattro recipienti diversi! Anche con il potere di Kel'Thuzad alle spalle, lo Scourge farà fatica a tenerci lontani da tutti e quattro.",
  reward = "Congratulazioni, $N: hai sbloccato l'ultimo calderone per noi! Presto Alchemist Arbington saprà di quali reagenti ha bisogno questo calderone per la miscela.$B$BQuanto a te, sono sicura che il Comandante Valorfist vorrà ringraziarti di persona per l'aiuto che ci hai dato. Senza di te, la nostra lotta contro lo Scourge sarebbe stata quasi insormontabile. Grazie, $Geroe:eroina;!",
}
T[5227] = {
  title = "Calderone del Gahrron's Withering",
  progress = "Davanti a te si erge il calderone della piaga dello Scourge, che sputa tossine nell'aria in enormi quantità. Alla base della sua vasta piattaforma c'è un piccolo pannello d'accesso anonimo.$B$BOra che hai sconfitto il signore del calderone e hai preso la chiave, puoi aggiungerci i reagenti adatti a creare un antidoto alla piaga.",
  reward = "Appena aggiungi i reagenti alla miscela, la nube che esce dal calderone comincia a cambiare colore e consistenza. Persino le forze del Flagello che si trovano appena nei paraggi sembrano ritrarsi, mentre i nuovi componenti si diffondono nell'aria.",
}
T[5228] = {
  title = "The Scourge Cauldrons",
  desc = "Nelle terre di quella che un tempo era Lordaeron ci sono otto calderoni — quattro a ovest e altri quattro saldamente insediati a est. Sputano veleni nell'aria e diffondono la piaga in tutta la regione per conto dello Scourge.$B$BIl potere negromantico di Kel'Thuzad è troppo forte per spegnere del tutto questi calderoni, ma forse abbiamo trovato il modo di volgerli a nostro vantaggio. La mia vice, Shadow Priestess Vandis, è il tuo punto di riferimento per questo incarico; d'ora in poi le istruzioni te le darà lei.",
  obj = "Parla con Shadow Priestess Vandis al Bulwark, Western Plaguelands.",
  reward = "Dalle ombre ti porgo i miei saluti, $Gfratello:sorella; $R. Sarò io a coordinare il nostro piano per sabotare i calderoni dello Scourge.$B$BVogliamo cambiare la composizione della piaga che producono, trasformandola in qualcosa che danneggi lo Scourge. Per riuscirci dovrai assicurarti l'accesso a ciascuno dei quattro calderoni qui nelle Western Plaguelands.$B$BÈ giunto il momento di guidare l'attacco contro lo Scourge, $Geroe:eroina;.",
}
T[5229] = {
  title = "Obiettivo: Felstone Field",
  desc = "Dei quattro calderoni nelle Western Plaguelands, quello del Felstone Field potrebbe essere il più facile da aprire. Lì lo Scourge ha schierato truppe meno esperte, ma non vanno sottovalutate.$B$BRaggiungi il Felstone Field, dritto a est da qui e a nord-ovest di Andorhal, e affronta il signore del calderone. Ha con sé una chiave che ti permetterà di aprire il calderone. Una volta aperto, usa questa bottiglia per prelevare un campione delle sue tossine; ci servirà per studiarle e sviluppare un agente neutralizzante.",
  obj = "Vai a Felstone Field, nelle Western Plaguelands, trova il Signore del Calderone e sconfiggilo. Potrebbe avere una chiave che permette di accedere al calderone. Devi avere con te l'Empty Felstone Field Bottle per prelevare un campione dei veleni usati nel calderone.",
  progress = "Un pannello d'accesso al calderone resta saldamente chiuso. Per aprirlo dovrai trovare la chiave.",
  reward = "La chiave presa a Cauldron Lord Bilemaw entra alla perfezione nella serratura del pannello d'accesso, ma svanisce dopo l'uso. Comunque, ormai pensi di poter aprire il pannello anche senza chiave. Dall'apertura esce un fetore nauseabondo, mentre un miscuglio ignoto di sostanze concentrate turbina dentro il calderone.$B$BC'è un piccolo rubinetto, e la bottiglia ci sta sotto abbastanza bene: puoi prelevare un campione per Shadow Priestess Vandis, al Bulwark.",
}
T[5230] = {
  title = "Ritorno al Baluardo",
  desc = "Riempi la bottiglia con l'intruglio velenoso del calderone, quanto basta per avere un campione da studiare.$B$BOra che hai il veleno, è il momento di tornare da Shadow Priestess Vandis al Bulwark per portare a termine la missione.",
  obj = "Porta la Filled Felstone Field Bottle a Shadow Priestess Vandis al Bulwark, Western Plaguelands.",
  progress = "$GBentornato:Bentornata; nella relativa sicurezza del Bulwark, $N. Che progressi hai fatto con i calderoni?",
  reward = "Ben fatto, $N — ad Apothecary Dithers basterà pochissimo per analizzarlo e preparare un agente neutralizzante da immettere nel calderone. Se riusciremo a pomparne abbastanza nell'aria, potremmo indebolire tutto lo Scourge della zona.$B$BSarà senza dubbio un'impresa lunga e faticosa: dovremo colpire questi calderoni di continuo e aggiungere i nostri reagenti alla loro miscela. Ma se terremo il ritmo, avremo un enorme vantaggio sullo Scourge quando arriverà il momento della battaglia!",
}
T[5231] = {
  title = "Obiettivo: Dalson's Tears",
  desc = "Uno dei calderoni della piaga si trova nel campo di una vecchia fattoria, ormai chiamata Dalson's Tears. Nessuno verserà lacrime, oggi, $C: dobbiamo colpire quel calderone e aprirlo!$B$BRaggiungi Dalson's Tears, quasi dritto a nord di Andorhal, ed elimina il signore del calderone. Come il precedente, dovrebbe avere una chiave che ti permetterà di entrare nelle viscere del calderone. Usa questa bottiglia per prelevare un campione dall'interno; ogni calderone ha la sua miscela di tossine.",
  obj = "Vai a Dalson's Tears, nelle Western Plaguelands, trova il Signore del Calderone, sconfiggilo e usa la sua chiave per accedere al calderone. Devi avere con te l'Empty Dalson's Tears Bottle per prelevare un campione dei veleni usati nel calderone.",
  progress = "Un pannello d'accesso al calderone resta saldamente chiuso. Per aprirlo dovrai trovare la chiave.",
  reward = "La chiave d'osso trovata sul signore del calderone scivola facilmente in una serratura e poi svanisce, dandoti accesso permanente al calderone. Icori grezzi e densi pulsano nei tubi contorti alla base della struttura.$B$BC'è un piccolo rubinetto, e la bottiglia ci sta sotto abbastanza bene: puoi prelevare un campione per Shadow Priestess Vandis, al Bulwark.",
}
T[5232] = {
  title = "Ritorno al Baluardo",
  desc = "Riempi con cura la bottiglia con gli icori del calderone, finché il campione non ti sembra abbastanza grande.$B$BOra che hai il veleno, è il momento di tornare da Shadow Priestess Vandis al Bulwark per portare a termine la missione.",
  obj = "Porta la Filled Dalson's Tears Bottle a Shadow Priestess Vandis al Bulwark, Western Plaguelands.",
  progress = "Sappiamo che ogni calderone usa una diversa miscela di reagenti per produrre la tossina che genera la piaga, e sappiamo anche che dovremo sviluppare un agente neutralizzante specifico per ciascuno. Il tuo campione di Dalson's Tears sarà la chiave per scoprire di quali reagenti abbia bisogno quel calderone.",
  reward = "Ah, qui ce n'è in abbondanza da studiare. Ben fatto, $N!$B$BPer ora il passo successivo spetta a noi. Dovremo stilare un elenco di reagenti che, combinati con ciò che c'è già nel calderone, ne neutralizzino l'effetto.$B$BL'unico modo per introdurli sarà metterli direttamente al suo interno. Apothecary Dithers ne saprà di più, quindi non mancare di parlargli il prima possibile.",
}
T[5233] = {
  title = "Obiettivo: Writhing Haunt",
  desc = "Siamo riusciti ad aprire due calderoni; anche se potrai accedervi in qualsiasi momento, vogliamo comunque sbloccare gli altri due. Così avremo tutti più possibilità di introdurre l'agente neutralizzante!$B$BStavolta colpirai il calderone del Writhing Haunt. Si trova quasi dritto a est di Andorhal, piuttosto vicino alle mura in rovina della città; come le altre volte, elimina il signore del calderone e prendigli la chiave. Usa questa bottiglia per prelevare il campione.$B$BBuona caccia, $N!",
  obj = "Vai a Writhing Haunt, nelle Western Plaguelands, trova il Signore del Calderone, sconfiggilo e usa la sua chiave per accedere al calderone. Devi avere con te l'Empty Writhing Haunt Bottle per prelevare un campione dei veleni usati nel calderone.",
  progress = "Un pannello d'accesso al calderone resta saldamente chiuso. Per aprirlo dovrai trovare la chiave.",
  reward = "La chiave del signore del calderone apre il pannello d'accesso e poi svanisce, proprio come le chiavi dei calderoni precedenti. Sotto la piattaforma ribolle violentemente una sostanza dall'odore putrido.$B$BC'è un piccolo rubinetto, e la bottiglia ci sta sotto abbastanza bene: puoi prelevare un campione per Shadow Priestess Vandis, al Bulwark.",
}
T[5234] = {
  title = "Ritorno al Baluardo",
  desc = "Riempi delicatamente la bottiglia vuota fino all'orlo; adesso, nel fragile contenitore di vetro, ondeggia avanti e indietro un campione della sostanza ripugnante che ribolle sotto la piattaforma del calderone.$B$BOra che hai il veleno, è il momento di tornare da Shadow Priestess Vandis al Bulwark per portare a termine la missione.",
  obj = "Porta la Filled Writhing Haunt Bottle a Shadow Priestess Vandis a The Bulwark, Western Plaguelands.",
  progress = "Quando avremo analizzato il campione prelevato dal calderone del Writhing Haunt, avremo una terza via per colpire lo Scourge con un agente neutralizzante devastante!",
  reward = "Un'altra missione eseguita alla perfezione, $N! Ora abbiamo tre calderoni da ritorcere contro lo Scourge. Se il dominio negromantico di Kel'Thuzad su queste terre non fosse così forte, oserei dire che li avresti spenti del tutto!$B$BApothecary Dithers preparerà un rapporto su cosa servirà a questo calderone — e agli altri che abbiamo piegato ai nostri scopi — per diffondere il nostro agente contro la piaga. Detto questo, è giunto il momento di portare sotto il nostro controllo l'ultimo calderone dell'ovest!",
}
T[5235] = {
  title = "Obiettivo: Gahrron's Withering",
  desc = "L'ultimo calderone rimasto si trova in una fattoria oggi chiamata Gahrron's Withering. È sorvegliato da alcuni dei servitori più temibili dello Scourge — per la precisione, spettri e fantasmi. Non vanno presi alla leggera, $N.$B$BIl Gahrron's Withering è molto a est del Bulwark, vicino a dove iniziano le Eastern Plaguelands; come le altre volte, elimina il signore del calderone e prendigli la chiave. Ecco la bottiglia vuota per il campione: riportamela piena. Che le ombre ti avvolgano e ti proteggano in questa missione pericolosa, $C.",
  obj = "Vai a Gahrron's Withering, nelle Western Plaguelands, trova il Signore del Calderone, sconfiggilo e usa la sua chiave per accedere al calderone. Devi avere con te l'Empty Gahrron's Withering Bottle per prelevare un campione dei veleni usati nel calderone.",
  progress = "Un pannello d'accesso al calderone resta saldamente chiuso. Per aprirlo dovrai trovare la chiave.",
  reward = "La chiave di Cauldron Lord Soulwrath si disintegra non appena tocca la serratura del pannello d'accesso, alla base della piattaforma del calderone. Dall'interno si sente un leggero clangore metallico, e il pannello si spalanca rivelando una nuova massa di tossine viscose dentro la struttura del calderone.$B$BC'è un piccolo rubinetto, e la bottiglia ci sta sotto abbastanza bene: puoi prelevare un campione per Shadow Priestess Vandis, al Bulwark.",
}
T[5236] = {
  title = "Ritorno al Baluardo",
  desc = "Chiudi con cura il rubinetto nel pannello di controllo, guardando gli icori putridi del calderone gocciolare nella bottiglia vuota.$B$BOra che hai il veleno, è il momento di tornare da Shadow Priestess Vandis al Bulwark per portare a termine la missione.",
  obj = "Porta la Filled Gahrron's Withering Bottle a Shadow Priestess Vandis al Bulwark, Western Plaguelands.",
  progress = "Il Gahrron's Withering ospita l'ultimo calderone a cui ci serve accedere qui a ovest. Una volta ottenuto un campione della piaga che produce, potremo immettere i nostri reagenti nell'ambiente attraverso quattro calderoni distinti! Lo Scourge farà fatica a tenerci lontani da tutti e quattro, anche con il potere di Kel'Thuzad alle spalle.",
  reward = "Congratulazioni, $N, hai aperto per noi l'ultimo calderone! Apothecary Dithers saprà presto di quali reagenti abbia bisogno per la miscela.$B$BQuanto a te, sono certa che High Executor Derrington vorrà ringraziarti di persona per l'aiuto che ci hai dato. Senza di te, la nostra lotta contro lo Scourge sarebbe stata quasi impossibile. Grazie, possente $C.",
}
T[5237] = {
  title = "Missione Compiuta!",
  reward = "$N, modificando i calderoni ci hai regalato una vittoria straordinaria!$B$B<Il comandante si schiarisce la gola e prende a parlare a gran voce.>$B$BOdano tutti coloro che sono al mio cospetto: a $N, $Gvero eroe:vera eroina; dell'Alleanza, che ha servito il Kingdom of Stormwind e l'Alleanza ben oltre il proprio dovere — di fronte a forze soverchianti e a pericoli incredibili, mi permetto di aggiungere — consegno questo, e porgo la nostra eterna gratitudine. Evviva, dico io!",
}
T[5238] = {
  title = "Missione Compiuta!",
  reward = "$N, sei $Griuscito:riuscita; a modificare i calderoni: per noi è una vittoria enorme!$B$B<Il gran esecutore si schiarisce la voce e comincia a tuonare.>$B$BAscoltino tutti coloro che sono al mio cospetto: per i servigi resi ai Forsaken e all'Orda intera, ben oltre quanto ci si aspettava — e davanti a difficoltà schiaccianti e a un pericolo incredibile, aggiungerei — conferisco questo a $N, e $Ggli:le; porgo la nostra eterna gratitudine come $Gvero eroe:vera eroina; dell'Orda. Urrà!",
}
T[5241] = {
  title = "Zio Carlin",
  desc = "Certe notti sento piangere mio Zio Carlin. Sembra lontano, verso est.$B$BSpero che non pianga per me! $N, potresti trovare mio zio e dirgli che sto bene?$B$BSe lo trovi, digli che lo aspetto e che voglio sentire la storia che mi raccontava sempre... quella dei conigli e della marmellata di bacche! È così divertente!",
  obj = "Trova Carlin Redpath.",
  reward = "Hai visto Pamela? È viva?$B$BÈ morta? No! Oh, Pamela! Perché il tuo spirito soffre ancora in questo mondo. Perché sei perita tu, mentre la sorte tiene in vita me? Prenderei il tuo posto all'istante, e vagherei io per la morta Darrowshire, fantasma e solo!$B$BAh, ma questa notizia non può cambiare il destino. Grazie, $N. Ora il mio dovere, il dovere della vendetta, arde come sempre.",
}
T[5242] = {
  title = "Un Colpo Finale",
  desc = "Purtroppo, a quanto vedo, l'unico modo per fermare questa minaccia per Felwood è un attacco frontale. Nello Shadow Hold non si entra da nessun'altra parte, e io non ho modo di teletrasportarti dentro. Non resta che andare dritto fino in fondo... e so anche chi dovresti cercare. Si chiama Fel'dan... Shadow Lord Fel'dan. È lui il mortale che comanda laggiù... la testa del serpente. Uccidi lui e le due succubi al suo servizio, poi torna da me. È Fel'dan a stringere patti con la Legione. Va fermato.",
  obj = "Uccidi Moora e Salia, e porta la Shadow Lord Fel'dan's Head a Greta Mosshoof a Felwood.",
  progress = "Spero che, senza Fel'dan, lo Shadow Council perda di vista i suoi scopi e cominci a combattersi dall'interno. Si contenderanno il controllo l'uno contro l'altro e accumuleranno risorse per i piani futuri. Sarà quello il momento giusto per annientare loro e i loro schiavi demoniaci.",
  reward = "Sia lodata la Madre Terra, $N! Grazie! È davvero un grande giorno!$B$BColpito così nella sua gerarchia, lo Shadow Council farà molta fatica a tornare potente come un tempo. Oggi hai fatto una gran cosa!",
}
T[5243] = {
  title = "Le Case del Sacro",
  desc = "Considero la mia non morte una malattia, $R. Un male che chiede soltanto di essere curato; eppure è anche una grande benedizione per l'Argent Dawn. Quale strumento migliore dei non morti, per abbattere gli infedeli dello Scourge?$B$BI miei colleghi mi riveriscono per i sacrifici che ho compiuto, ma a me gli onori non dicono nulla.$B$BSe ti interessa aiutare l'Argent Dawn, un lavoro da offrirti ce l'ho.$B$BAvventurati a Stratholme e recupera la nostra scorta di acqua santa. Cercala nelle supply crates.",
  obj = "Viaggia fino a Stratholme, a nord. Cerca nelle supply crates sparse per la città e recupera 5 Stratholme Holy Water. Torna da Leonid Barthalomew the Revered quando avrai raccolto abbastanza del liquido benedetto.",
  progress = "Sii $Gcauto:cauta;, non tutte le supply crates saranno scampate alla distruzione della città. L'acqua lo Scourge non osa toccarla, ma di certo non basterà a tenere lontani i parassiti.",
  reward = "Ben fatto, $R. Hai dimostrato che, per quanto tu sia tollerante con gli altri, non ti fermerai davanti a nulla pur di distruggere i servitori di Kel'Thuzad.",
}
T[5244] = {
  title = "The Ruins of Kel'Theril",
  desc = "Quella di Kel'Theril è la storia di una razza maledetta, legata al luogo dove ha tentato un rituale sfortunato...$B$BUn tempo gli alti nobili che troverai lì hanno rubato un manufatto sacro, convinti di poterne assorbire il potere per diventare ancora più forti. Nel tentativo, un'enorme esplosione ha mandato in frantumi la reliquia, e i pezzi sono finiti sotto il ghiaccio del lago...$B$BSe vuoi saperne di più, parla con Jaron Stoneshaper: è stato da quelle parti di recente e può raccontarti altro.",
  obj = "Parla con Jaron Stoneshaper a Starfall Village.",
  reward = "Beh, certo che posso raccontarti qualcos'altro su Kel'Theril. Bada, non sono mica uno storico, ma quel che ho visto laggiù te lo posso dire...",
}
T[5245] = {
  title = "Spiriti Inquieti di Kel'Theril",
  desc = "Poco ma sicuro, gli spiriti degli alti nobili sono creature infelici. Vanno ancora in cerca dei pezzi proprio della cosa che li ha condannati a restare per sempre a Kel'Theril — la reliquia rubata.$B$BSe ci tieni tanto, prenditi il mio piccone, scendi a sud fino al lago e vedi un po' se riesci a tirar fuori i pezzi dal ghiaccio.$B$BOra, di quello che troverai non posso dirti niente, ma conosco qualcuno che forse può... Aurora Skycaller; vive vicino alla Northpass Tower, nel nord delle Eastern Plaguelands.",
  obj = "Usa il Jaron's Pick per trovare i quattro Frammenti dell'Highborne Relic. Portali ad Aurora Skycaller in Eastern Plaguelands.",
  progress = "Perché sei $Gvenuto:venuta; qui?",
  reward = "Non desidero parlare del passato degli alti elfi, $N. Ti prego, mi addolora pensare a quanto è successo... E al fatto che non si può rimediare in alcun modo.",
}
T[5246] = {
  title = "Frammenti del Passato",
  desc = "Non avevo capito... Perdonami, $C, le mie parole sono state insensibili.$B$BNon desidero soffermarmi sugli errori dei miei antenati, ma se la tua richiesta è davvero sincera, ti aiuterò.$B$B<Aurora esamina i frammenti.>$B$BCredo che questo sia il Crystal of Zin-Malor, un manufatto capace di contenere e controllare potenti forze arcane. Avrebbe potuto servire al bene, ma sono state le intenzioni malvagie di chi l'ha rubato a mandarlo in frantumi.$B$BVa' al Temple of Zin-Malor ad Azshara — non mi resta che sperare che il libro ci sia ancora.",
  obj = "Trova i Sacred Highborne Writings in Temple of Zin-Malor ad Azshara e portali ad Aurora Skycaller vicino a Northpass Tower in Eastern Plaguelands.",
  progress = "Solo leggendo le pagine degli scritti sacri saprò se posso aiutarti o no...",
  reward = "Nessuno tocca queste pagine da tanti, tanti anni...",
}
T[5247] = {
  title = "Frammenti del Passato",
  desc = "Se davvero desideri ricreare il manufatto, potrò aiutarti.$B$BPer risaldare i pezzi mi serviranno oggetti con forti proprietà magiche: un enchanted thorium bar e cinque dosi di crystal restore... E dovrai anche raccogliere un po' d'acqua in un posto che forse non ti aspetti... Cerca la pozza infausta lungo l'Eldreth Row a Dire Maul, a Feralas, e riempi questa fiala.$B$BMentre sei via, cercherò di ricavare da queste pagine quel che mi serve sapere per riparare i danni subiti dalla reliquia.",
  obj = "Porta un Enchanted Thorium Bar, 5 Crystal Restore e una Vial of Dire Water ad Aurora Skycaller vicino a Northpass Tower in Eastern Plaguelands.",
  progress = "La reliquia va affidata soltanto alle mani più fidate. Nessuno deve rubarla di nuovo...",
  reward = "Con questi elementi posso fondere fra loro i frammenti... e riportarli, spero, a com'erano un tempo.",
}
T[5248] = {
  title = "Tormentati dal Passato",
  desc = "$N, piango per quello che è successo in passato. Come razza, gli elfi sono andati in frantumi come questo cristallo. Non so se i pezzi torneranno mai a essere una cosa sola, ma poterti aiutare in questo piccolo compito mi ha alleviato il dolore.$B$BIl passato non dobbiamo dimenticarlo, $N...$B$BTi prego, riporta il Crystal of Zin-Malor al Lake Kel'Theril. Lì devi trovare uno spirito degli alti nobili che riconosca l'errore commesso tanto tempo fa, e mostrargli che abbiamo rimesso le cose a posto.",
  obj = "Porta il Crystal of Zin-Malor a Lake Kel'Theril in Winterspring e trova uno spirito degli alti nobili che ti parli.",
  progress = "Maledeeeetti... Per sempreeeee...",
  reward = "Ti preeego, lasciaaamiiii...",
}
T[5249] = {
  title = "Verso Winterspring!",
  desc = "Più a nord, a Winterspring, si trovano molte antiche rovine elfiche. È una terra ostile, che però nasconde tanti segreti e tanti luoghi da esplorare.$B$BIl lavoro qui a Felwood non mi ha mai lasciato l'occasione di andare a Winterspring. Ma tu non hai nessun motivo per non andarci!$B$BUna volta lì, cerca Wynd Nightchaser: passa quasi tutto il tempo a Starfall Village e conosce bene la zona.",
  obj = "Trova Starfall Village a Winterspring e parla con Wynd Nightchaser.",
  reward = "$GUn amico:Un'amica; di Ivy Leafrunner? Piacere di conoscerti, $N.",
}
T[5250] = {
  title = "Starfall",
  desc = "A nord di Felwood, a Winterspring, si trovano molte antiche rovine elfiche. È una terra ostile, che però nasconde tanti segreti e tanti luoghi da esplorare.$B$BI miei studi qui mi tengono così occupata che da un po' non trovo l'occasione di andare a Winterspring. Ma tu non hai nessun motivo per non andarci a studiare le rovine.$B$BUna volta lì, cerca Wynd Nightchaser: passa quasi tutto il tempo a Starfall e conosce bene la zona.$B$BDigli che sei $Gun mio studente:una mia studentessa;...",
  obj = "Trova Starfall a Winterspring e parla con Wynd Nightchaser.",
  reward = "$GUno studente:Una studentessa; di Daryn Lightwind? Piacere di conoscerti, $N.",
}
T[5251] = {
  title = "L'Archivista",
  desc = "Tutto ciò che viene spinto all'estremo è un pericolo per il nostro mondo, $N. Prendi la Scarlet Crusade: credi che il loro cieco fanatismo serva un bene più grande? Quanti innocenti hanno distrutto in nome della Luce?$B$BBlasfemi, tutti quanti!$B$BCe n'è uno, però, che mi interessa in particolare: Archivist Galford di Stratholme, l'uomo che sorveglia i documenti più preziosi della Crociata. Distruggilo e brucia i suoi archivi! Se ci riesci, torna da me e sarai $Gricompensato:ricompensata;.",
  obj = "Vai a Stratholme e trova Archivist Galford della Scarlet Crusade. Distruggilo e brucia Scarlet Archive.",
  progress = "Ricorda, $N — dobbiamo essere tolleranti, ma fermi nelle nostre convinzioni!",
  reward = "Eccezionale, $N! Anni di informazioni andati perduti! Nelle prossime settimane The Scarlet Crusade accuserà il colpo, di questo sono certo.",
}
T[5252] = {
  title = "Remorseful Highborne",
  desc = "Il... il cristallo...$B$BQui gli alti nobili hanno la mente offuscata dalla loro stessa sofffferenza...$B$BSono addolorrrrata, ma riconosco l'errorrrre di ciò che è accaduto tanto tempo fa. Non c'è modooo di cambiare il passato, eppure ora sono in pacccce, perché so che hai recuperato il cristallo di Zin-Malor...$B$BDeeevi restituirlo...$B$BDeeeve essere restituiiito.",
  obj = "Parla con Wynd Nightchaser a Starfall Village e chiedigli qual è il posto giusto per il Crystal of Zin-Malor.",
  progress = "Te ne sei $Gandato:andata; da un bel po', $N. Come te la sei cavata?",
  reward = "È... quello che penso?",
}
T[5253] = {
  title = "Il Crystal of Zin-Malor",
  desc = "Notevole davvero, $N.$B$BIl cristallo di Zin-Malor non potrà mai tornare al tempio, che come sai è in rovina. Ma hai cercato di rimediare al male del passato, e credo che questo non debba restare senza ricompensa.$B$BCerca Arch Druid Fandral Staghelm a Darnassus e portagli il cristallo, $N. Dovrebbe finire nelle mani di chi non ne abuserà: a vederlo, solo una manciata degli incantatori più forti saprebbe dominare una forza del genere.",
  obj = "Consegna il Crystal of Zin-Malor ad Arch Druid Fandral Staghelm a Darnassus.",
  progress = "Sì, $R?",
  reward = "Ho sentito parlare del Crystal of Zin-Malor: chi lo usa ottiene un incredibile potere arcano, ma solo se ne è davvero degno. Mi colpisce che, oltre ad averlo recuperato, tu riconosca i tuoi limiti e non abbia tentato di usarlo.$B$BGrazie per avermelo portato, $N. Lo terremo al sicuro. E che gli spiriti maledetti che un tempo custodivano il cristallo in frantumi trovino finalmente la pace.",
}
T[5262] = {
  title = "La Verità Crolla Addosso",
  desc = "Mentre la polvere si posa sulla sala, cerchi di raccogliere le idee. Ripensi a quello che è appena successo, e ancora non riesci a capire quanto sia grave la situazione.$B$BIl Gran Crociato della Scarlet Crusade... un demone? E non un demone qualsiasi, ma il fratello di Varimathras, arcisignore di Undercity?$B$BRiponi con cura nello zaino la testa mozzata del dreadlord: senza una prova, di certo nessuno crederebbe alla tua storia.$B$BDuke Nicholas Zverenhoff deve saperlo subito!",
  obj = "Porta l'Head of Balnazzar a Duke Nicholas Zverenhoff in Eastern Plaguelands.",
  progress = "Cos'hai lì, $N?",
  reward = "Cosa vorrà dire tutto questo per la Crociata? Possibile che fossero sotto il controllo di questo demone? Che abbiano fatto da pedine a un male più grande, senza saperlo?",
}
T[5263] = {
  title = "Oltre il Dovere",
  desc = "Hai un talento naturale per la distruzione, e sai eseguire gli ordini: due cose che di rado si vedono insieme. Comincio a pensare che potresti essere un ottimo strumento della giustizia divina.$B$B<Zverenhoff congiunge le mani davanti al viso.>$B$BSu Stratholme regna il galoppino di Kel'Thuzad. Dimostrami che sei $Gun campione:una campionessa; — $Gil mio campione:la mia campionessa;. Distruggi Baron Rivendare e torna da me con la sua testa.",
  obj = "Avventurati a Stratholme e distruggi Baron Rivendare. Prendi la sua testa e torna da Duke Nicholas Zverenhoff.",
  progress = "Il Barone ha ucciso più persone di quante probabilmente tu ne abbia mai viste in vita tua.",
  reward = "Erano molti anni che non accoglievo un campione fra le nostre fila: sei $Gil primo:la prima; da tanto tempo a essere $Gricevuto:ricevuta; in udienza da Lord Maxwell.",
}
T[5264] = {
  title = "Lord Maxwell Tyrosus",
  desc = "Sto per farti un grande onore, $N.$B$BLord Maxwell vuole ricompensarti per i servigi che hai reso all'Argent Dawn!$B$BSono anni che Maxwell non concede udienza agli estranei.",
  obj = "Parla con Lord Maxwell Tyrosus. Si trova dentro la chiesa.",
  reward = "Sei $Gun alleato degno:un'alleata degna;, $N, e raccoglierai i frutti della tua salda dedizione.",
}
T[5265] = {
  title = "The Argent Hold",
  desc = "Per anni The Argent Hold è rimasta chiusa, e nessuno è mai stato degno di attingervi il potere dell'Argent Dawn — fino a oggi.$B$BOra The Argent Hold è aperta per te, $N.",
  obj = "Apri The Argent Hold e ritira la ricompensa.",
  reward = "Wow...",
}
T[5281] = {
  title = "Le Restless Souls",
  desc = "Nella caduta di Stratholme c'è chi ha trovato una morte tragica. Molti si sono tolti la vita: piuttosto che diventare uno dello Scourge, hanno scelto di gettarsi tra le innumerevoli fiamme della città fumante.$B$BOra vagano come spiriti irrequieti per le strade di Stratholme.$B$BDobbiamo aiutarli, $N!$B$BHo un collaboratore, Egan, che sta facendo miracoli con fantasmi e anime. Cercalo: si aggira nelle Plaguelands orientali, vicino a Stratholme, a mettere alla prova le sue invenzioni.",
  obj = "Trova Egan. Sai solo che è stato visto l'ultima volta nei dintorni di Stratholme.",
  reward = "Allora Alen ha trovato finalmente qualcuno abbastanza $Gcoraggioso:coraggiosa;, eh?",
}
T[5282] = {
  title = "Le Restless Souls",
  desc = "Quello che mi dà la forza — la voglia di continuare a vivere e a respirare — è l'odio implacabile che provo per lo Scourge e per tutto quello che ha fatto. Ma fanatico non lo sono. C'è chi, come la Scarlet Crusade, preferirebbe distruggere i non morti innocenti che concedere loro anche solo un briciolo di compassione.$B$BEd eccoci al punto: il mio fucile. Libererà dalle catene le anime tormentate di Stratholme.$B$BUsalo sui fantasmi che infestano le strade saccheggiate e libera le loro anime.",
  obj = "Usa l'Egan's Blaster sui cittadini fantasma e sugli spectral citizens di Stratholme. Quando le restless souls si liberano dai loro gusci spettrali, usa di nuovo il fucile — saranno libere!$B$BLibera 15 Restless Souls e torna da Egan.",
  progress = "È la compassione a separarci dagli animali, $N. Ricordatelo...",
  reward = "<Egan si asciuga una lacrima.>$B$BHai visto mia madre, $N? L'hai liberata?$B$BSei un luminoso esempio di rettitudine. Per il disturbo...",
}
T[5283] = {
  title = "L'Arte dell'Armaiolo",
  desc = "Allora hai fatto la scelta furba.$B$BFra me e il vecchio Ironus, qui, non corre buon sangue. Lo sa bene, quel buono a nulla di un fabbricante di giocattoli, chi sono i veri artigiani da queste parti.$B$BLe grandi guerre si vincono con una buona difesa. Quando arriva il momento, non c'è attacco che tenga.$B$BBene, al lavoro. Mi basta che tu mi dimostri di avere un po' di talento grezzo. Poi ti strapperò via tutte le impurità che ti restano e ti forgerò finché non diventerai $Gun armaiolo:un'armaiola;. Il mithril decorato lo sai fare, vero?",
  obj = "Per diventare $Gun Armaiolo:un'Armaiola;, devi creare i seguenti oggetti e portarli a Grumnus: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate.",
  progress = "Ah, non c'è niente di meglio di una bella abbronzatura da forgia. Chi ce l'ha più bella lo riconosci dai segni del grembiule.",
  reward = "Ci siamo, $N. Da qui non si torna più indietro. Sei ancora in tempo per diventare $Gun fabbricante:una fabbricante; di giocattoli, ehm, $Gun:una; fabbro d'armi.$B$BConto sul fatto che farai la scelta giusta.",
}
T[5284] = {
  title = "La Via del Forgiatore d'Armi",
  desc = "Come $Gforgiatore:forgiatrice; d'armi scoprirai che quasi sempre eroi e avventurieri verranno da te per l'equipaggiamento. A volte il lavoro può diventare insopportabile, ma le ricchezze ripagano ampiamente il mal di schiena e i polmoni pieni di cenere.$B$BOh sì, $N, tutto l'oro ce l'hanno i forgiatori d'armi!$B$BSe vuoi unirti alle nostre file, dovrai dimostrarmi che sai farmi guadagnare un argento o due — cioè che hai la stoffa per essere $Gil tipo:la ragazza; a cui ci si rivolge quando servono armi di qualità superiore. Mettiti al lavoro!",
  obj = "Per diventare $GForgiatore:Forgiatrice; d'Armi, devi creare i seguenti oggetti e portarli a Ironus: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes e 2 Big Black Maces.",
  progress = "<Ironus è occupato a sistemare le monete d'oro in piccole pile ordinate.>",
  reward = "Era ora! Ho dei clienti che aspettano.$B$BDammi qua quella roba e stammi a sentire: stai per fare il primo passo nella carriera di $Gforgiatore:forgiatrice; d'armi.",
}
T[5301] = {
  title = "L'Arte del Forgiatore di Armature",
  desc = "Soddisfazione. È questo che mi danno il martello e l'incudine. Quando vedo un fiero guerriero dell'Orda protetto dal mio acciaio, ricordo cosa vuol dire essere vivi. È una dipendenza a cui non oserei mai rinunciare, $N.$B$BQuesta soddisfazione non posso dartela: posso solo metterti sulla strada. Come ogni impresa della vita, la via del forgiatore di armature è un viaggio.$B$BSe vuoi essere $Guno:una; dei pochi eletti, basta che tu lo chieda e ti addestrerò, ma prima un compito devi portare a termine.",
  obj = "Per diventare $Gforgiatore:forgiatrice; di armature, devi creare i seguenti oggetti e consegnarli a Okothos: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate.",
  progress = "Continuerò a battere l'acciaio fino all'ultimo respiro.",
  reward = "Ecco l'ultimo passo prima di cominciare la tua nuova carriera di $Gforgiatore:forgiatrice; di armature, $N. Se vuoi tirarti indietro, è la tua ultima occasione. Altrimenti, preparati a una vita di gloria.",
}
T[5302] = {
  title = "La Via del Forgiatore di Armi",
  desc = "Un giorno forgerò un martello leggendario. Un martello degno di un Capoguerra!$B$BÈ l'opera della mia vita, $N, la mia passione. In te vedo la stoffa per stare tra noi, per essere $Guno:una; di noi — $Gun forgiatore:una forgiatrice; di armi. E sono io quello che può aiutarti a tirarla fuori.$B$BTi basta portare a termine un compito semplice. Semplice per chi ha un'abilità eccezionale come la tua.",
  obj = "Per diventare $GForgiatore:Forgiatrice; di Armi, devi creare i seguenti oggetti e consegnarli a Borgosh: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes e 2 Big Black Maces.",
  progress = "Per la gloria dell'Orda!",
  reward = "Ecco l'ultimo passo prima di cominciare la tua nuova carriera di $Gforgiatore:forgiatrice; di armi, $N. Se vuoi tirarti indietro, è la tua ultima occasione. Altrimenti, preparati a essere $Gdivorato:divorata; dalla conoscenza!",
}
T[5305] = {
  title = "Dolce Serenity",
  desc = "La dolce Serenity si trova entro i confini dello Scarlet Bastion, e il Crimson Hammersmith ne difende la ricetta a costo della vita. Sconfiggilo e portami il suo grembiule: in cambio ti addestrerò a diventare $Gun forgiatore:una forgiatrice; di martelli.$B$BSappi una cosa: una volta scelta la via del forgiatore di martelli, non potrai più intraprendere né quella del forgiatore di spade né quella del forgiatore di asce.",
  obj = "Viaggia fino a Stratholme e uccidi il Crimson Hammersmith. Recupera il Crimson Hammersmith's Apron e torna da Lilith.",
  progress = "Il suo grembiule! Dov'è?",
  reward = "Che tu possa sfondare molti crani, $N!",
}
T[5306] = {
  title = "Pietra del Serpente della Cacciatrice dell'Ombra",
  desc = "Non farti ingannare dalla sua bellezza, $C: la cacciatrice dell'ombra Vosh'gajin è letale e folle.$B$B<Kilram indica la cicatrice sul volto.>$B$BGià, me l'ha fatta lei — una carezza d'amore, così l'ha chiamata.$B$BAdesso finalmente è arrivata l'ora della vendetta.$B$BVosh'gajin la trovi nel Blackrock Spire. Uccidila e torna da me con la sua pietra del serpente: fallo, e ti insegnerò l'arte del forgiatore di asce.",
  obj = "Viaggia fino a Blackrock Spire e uccidi Shadow Hunter Vosh'gajin. Recupera la Vosh'gajin's Snakestone e torna da Kilram.",
  progress = "Dice la leggenda che basta usare una volta sola la pietra del serpente di Vosh'gajin per tenere un'ascia affilata come un rasoio per 1000 anni!",
  reward = "Il sapere è potere!",
}
T[5307] = {
  title = "Corruzione",
  desc = "Se sono brusco con te, c'è un motivo: la Black Guard, le unità scheletriche d'élite di Baron Rivendare, ha rubato i progetti per forgiare la grande lama, Corruzione.$B$BSì, Baron Rivendare di Stratholme.$B$BOra quei progetti li difende il fabbro della Black Guard, a costo della sua... non-vita.$B$BUccidilo e portami una prova dell'impresa: ti insegnerò l'arte del forgiatore di spade.",
  obj = "Trova il Black Guard Swordsmith a Stratholme e distruggilo. Recupera l'Insignia of the Black Guard e torna da Seril Scourgebane.",
  progress = "Hai forse dimenticato il compito che ti è stato affidato, $N?",
  reward = "Dovrebbe essere ovvio: una spada è sempre la scelta migliore.",
}
T[5341] = {
  title = "La Fortuna della Famiglia Barov",
  desc = "Nella Scholomance giace la fortuna della famiglia Barov. Io, Alexi Barov, sono uno degli ultimi due eredi della casata Barov. L'altro è mio fratello, Weldon.$B$BWeldon, quel miserabile codardo, è fuggito durante la guerra, e così ha salvato la sua inutile vita da umano.$B$BOra cerca gli atti di proprietà per reclamare il patrimonio tutto per sé. Recuperali prima di mio fratello e ti renderò più $Gricco:ricca; di quanto tu abbia mai sognato!",
  obj = "Avventurati a Scholomance e recupera la fortuna della famiglia Barov. È composta da quattro atti: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; e The Deed to Southshore. Torna da Alexi Barov quando avrai finito.",
  progress = "China il capo in mia presenza, $R. Dopotutto io sono un nobile, e tu sei $Gun plebeo squattrinato:una plebea squattrinata;.",
  reward = "Ottimo lavoro, $R. Ora non resta che assicurarmi l'eredità...",
}
T[5342] = {
  title = "L'Ultimo Barov",
  desc = "Naturalmente, finché mio fratello è vivo, potrebbe sorgere qualche contesa su chi sia il principale beneficiario della fortuna di famiglia. Non deve succedere.$B$B$GUno spregevole straccione:Una spregevole stracciona; come te non si farà scrupoli davanti a un piccolo omicidio a sangue freddo, spero.$B$BÈ un compito semplice, e mi aspetto che tu lo porti a termine; sempre che tu voglia riscuotere la ricompensa.$B$BWeldon se ne sta a est, a Chillwind Camp, sotto la protezione dell'Alleanza. Uccidilo e portami la testa.$B$B<Alexi sbadiglia.>$B$BE ora sbrigati.",
  obj = "Raggiungi Chillwind Camp — territorio dell'Alleanza — e assassina Weldon Barov. Prendigli la testa e torna da Alexi Barov.$B$BAttenzione: probabilmente Weldon sarà ben protetto dalla feccia dell'Alleanza.",
  progress = "Fai in modo che la fortuna sia mia, e avrai la tua parte del bottino.",
  reward = "Magnifico! Ora solo io possiedo il potere e la fortuna della casata Barov!$B$B<Alexi ti lancia un grosso sacco.>$B$BE tieniti il resto, lurido animale.",
}
T[5343] = {
  title = "La Fortuna della Famiglia Barov",
  desc = "Il mio caro fratello Alexi. Che sciocco sono stato a risparmiarlo. Ho guardato il nemico in faccia, uno dei non morti, e l'ho lasciato vivere.$B$B<Weldon sputa.>$B$BE adesso va in cerca della MIA eredità. Questo non può succedere, punto e basta.$B$BTrova gli atti della mia famiglia prima che quel vile miserabile ci metta sopra le sue mani ossute, e ti coprirò di ricchezze. Sono fra le rovine della Scholomance. Sbrigati!",
  obj = "Recati a Scholomance e recupera la fortuna della famiglia Barov. Questa fortuna è fatta di quattro atti: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; e The Deed to Southshore. Torna da Weldon Barov quando avrai completato questo compito.",
  progress = "Metti al sicuro il mio futuro, e io metterò al sicuro il tuo.",
  reward = "Mi resta solo un'altra cosa da chiederti, $N.",
}
T[5344] = {
  title = "L'Ultimo Barov",
  desc = "Ora che gli atti sono tornati a me, resta una cosa sola da fare. Alexi va ucciso. Morto lui, non dovrò mai più preoccuparmi di qualche banda di mercenari senza scrupoli a caccia della mia testa.$B$BIl compito è semplice. Alexi si nasconde al riparo dell'Orda — al Bulwark.$B$BNo, non mi basta che tu vada da lui e lo uccida, io voglio la sua testa! Come te la procurerai... be', quello lo decidi tu. Certe faccende non si addicono a chi è cresciuto con la mia nobile educazione.",
  obj = "Recati a Bulwark — territorio dell'Orda — e assassina Alexi Barov. Prendi la sua testa e torna da Weldon Barov.$B$BAttenzione, Alexi sarà probabilmente ben protetto dalla feccia dell'Orda.",
  progress = "Il pagamento lo vuoi, non è vero?",
  reward = "Che giorno glorioso! Finalmente la casata Barov è libera dalla sua macchia, e la mia fortuna è al sicuro!$B$BPrendi questo e sparisci dalla mia vista, $Gplebeo:plebea;.",
}
T[5361] = {
  title = "Albero Genealogico",
  desc = "Mio fratello Nataka è di stanza al Ghost Walker Post, laggiù a Desolace. Ti chiederei... potresti portargli questo rapporto da parte mia? È passato un anno dall'ultima volta che gli ho scritto, e da allora i centauri sono insolitamente attivi, quindi è giusto che lo sappia.$B$BRaggiungi la Stonetalon Mountain, a nord del Crossroads, poi prosegui a ovest verso la Charred Vale. Da lì scendi a sud verso Desolace; là troverai una strada che porta giù fino al Ghost Walker Post.",
  obj = "Consegna il Cliffwatcher Longhorn Report a Nataka Longhorn a Ghost Walker Post, in Desolace.",
  progress = "Che notizie mi porti, $C! Ah — dici che hai un messaggio da mio fratello? Su, dammi il rapporto!",
  reward = "Non so cosa ti leghi a mio fratello, ma a quanto pare si fida di te, $C.$B$BIo sono Nataka Longhorn e ti do il benvenuto al Ghost Walker Post, abbiamo un gran bisogno di $Gun:una; $C! Parla con gli altri, forse il tuo aiuto qui serve.",
  en_title = "Family Tree",
  en_obj = "Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace.",
}
T[5381] = {
  title = "Hand of Iruxos",
  desc = "La Burning Blade possiede la Demon Box, e lì dentro c'è la potente Hand of Iruxos: è con quella che la Burning Blade apre portali demoniaci alla Mannoroc Coven. Dobbiamo fermare l'ondata di demoni che entra nel nostro mondo, $N!$B$BUsa questo demon pick sul cristallo rosso della Thunder Axe Fortress, e potrai arrivare alla Demon Box.",
  obj = "Recupera la Demon Box dalla Thunder Axe Fortress e riportala, insieme al Demon Pick, a Taiga Wisemane in Shadowprey Village.",
  progress = "Hai la Demon Box, $N?",
  reward = "Ah, la Demon Box. Dammela, $C: la aprirò... e così ti rivelerò l'Hand of Iruxos.",
  en_title = "Hand of Iruxos",
  en_obj = "Retrieve the Demon Box from Thunder Axe Fortress, and return it, along with the Demon Pick to Taiga Wisemane in Shadowprey Village.$B",
}
T[5382] = {
  title = "Doctor Theolen Krastinov, il Macellaio",
  desc = "Krastinov ha causato la morte di migliaia di persone. Va punito: giustizia deve essere fatta.$B$BTrovalo e fagli patire la stessa agonia che ha inflitto a innumerevoli innocenti. Quando l'avrai distrutto, brucia i nostri resti e riducili in cenere, $N.",
  obj = "Trova Doctor Theolen Krastinov nella Scholomance. Distruggilo, poi brucia i Remains of Eva Sarkhoff e i Remains of Lucien Sarkhoff. Torna da Eva Sarkhoff quando avrai finito.",
  progress = "Il Macellaio va fermato!",
  reward = "Sento lo spirito che guarisce, $N. A me e a mio marito hai reso un grande servizio, ma sono certa che resti ancora altro da fare.",
}
T[5383] = {
  title = "Krastinov's Bag of Horrors",
  desc = "Apri la borsa e ci trovi dentro vari strumenti di tortura. In mezzo a tutta quella roba, un oggetto strano ti salta all'occhio: una fiala di sangue — ancora calda al tatto.$B$BTi viene da pensare che ai Sarkhoff la scoperta potrebbe interessare.",
  obj = "Porta la Borsa degli Orrori a Eva Sarkhoff a Caer Darrow.",
}
T[5384] = {
  title = "Kirtonos the Herald",
  desc = "Eccolo, $N.$B$B<Eva indica la fiala dentro la borsa.>$B$BIl blood of innocents: il sangue più puro, quello usato per placare il padrone di Krastinov.$B$BCon questo sangue si può evocare Kirtonos, ed è dunque con questo sangue che Kirtonos va distrutto.$B$BPorta il sangue al portico e mettilo sul braciere. Kirtonos verrà — non può resistere. Quando apparirà, scatenagli contro la furia e l'ira di mille morti innocenti.$B$BSe ci riuscirai, non avrai solo la nostra gratitudine.",
  obj = "Torna nella Scholomance con il Blood of Innocents. Trova il portico e metti il Blood of Innocents nel braciere. Kirtonos verrà a nutrirsi della tua anima.$B$BCombatti con valore, non cedere di un passo! Distruggi Kirtonos e torna da Eva Sarkhoff.",
  progress = "Stai $Gattento:attenta;: Kirtonos è un combattente esperto.",
  reward = "La morte di Kirtonos chiude un capitolo dell'orribile storia della Scholomance, ma c'è ancora altro da fare. Ora anche altri, qui, sanno delle tue azioni coraggiose. Prendi questo, $N: è un frammento della nostra stessa essenza, e ti permetterà di comunicare con le altre anime perdute di Caer Darrow.",
}
T[5385] = {
  title = "I Resti di Trey Lightforge",
  desc = "Raccogli con cura il sacco e ti prepari a tornare da Jessir Moonbow, al confine fra Felwood e Ashenvale. Con un po' di fortuna, quando avrai consegnato i resti ai suoi amici, il paladino riceverà gli onori che merita.",
  obj = "Riporta i Resti di Trey Lightforge a Jessir Moonbow a Felwood.",
  progress = "Com'è andata a Jaedenar, $N?",
  reward = "Ce l'hai fatta! Sia lodata Elune, e qualunque potere tu veneri, $N. Oggi hai compiuto un'azione nobile e onorevole. Sono certa che Arko'narin sarà felice che tu abbia trovato il tempo non solo di salvarla, ma anche di uccidere la creatura che ha torturato uno dei suoi migliori amici.$B$BVorrei poter fare di più per te, ma ti prego, prendi questo.",
}
T[5386] = {
  title = "Il Pescato del Giorno",
  desc = "È da tempo che al Ghost Walker Post non si sente l'odore del pesce cotto. Nessuno pesca meglio dei troll di Shadowprey Village... ma ahimè, con i centauri così attivi mi resta poco tempo per arrivare fin da loro. Hrm...$B$BFammi un favore: vai a Shadowprey Village, parla con il pescatore del posto, Jinar'Zillen, e riportami il mio preferito, il Bloodbelly fish. Prendi la strada a sud di qui: ti porterà verso ovest, fino al villaggio dei troll.",
  obj = "Parla con Jinar'Zillen a Shadowprey Village, poi porta a Nataka Longhorn 2 Bloodbelly fish.",
  progress = "Quando penso al Bloodbelly fish fritto mi formicola lo zoccolo e mi viene l'acquolina in bocca... Ne hai con te?",
  reward = "Sei $Gun salvatore:una salvatrice;, $N! Hanno un aspetto così buono, questi esemplari di Bloodbelly fish, che quasi li mangerei crudi.$B$B<Nataka comincia a sbavare.>$B$BEcco qui — scegli uno di questi oggetti in pagamento per i pesci.",
  en_title = "Catch of the Day",
  en_obj = "Talk to Jinar'Zillen at Shadowprey Village, and then bring Nataka Longhorn 2 Bloodbelly fish.",
}
T[5401] = {
  title = "Argent Dawn Commission",
  reward = "Chi combatte il male per conto dell'Argent Dawn deve indossare il nostro distintivo: portandolo avrai il diritto di reclamare le ricompense che offrono i nostri furieri.$B$BFinché porti il distintivo, dalle creature dello Scourge che uccidi potrai ottenere gli Scourgestone, le insegne che a volte hanno con sé. Procurati queste insegne e portamele: per ogni serie che mi consegnerai riceverai il nostro segno di eroismo — l'Argent Dawn Valor Token.$B$BCompi il tuo destino, $C — unisciti alla lotta oggi stesso!",
}
T[5402] = {
  title = "Minion's Scourgestones",
  progress = "Un Minion's Scourgestone è l'insegna dei soldati semplici dello Scourge. Capita di trovarlo sulle truppe più deboli schierate nelle Plaguelands, anche se quel \"più deboli\" va preso con le dovute cautele: lo Scourge non va mai sottovalutato, ovunque si trovi.$B$BAl momento The Argent Dawn offre un emblema del valore in cambio di venti di queste insegne — e io farò volentieri lo scambio, purché tu abbia guadagnato abbastanza scourgestone!",
  reward = "Congratulazioni, $N — sono lieta di consegnarti un emblema del valore dell'Argent Dawn!$B$BGli emblemi servono a due cose. Primo — puoi usarli per migliorare la tua reputazione presso l'Argent Dawn, e così potresti accedere a opzioni e ricompense riservate ai nostri alleati onorati e riveriti. Secondo — puoi darli ai nostri furieri, insieme alle monete, per pagare alcuni degli oggetti più pregiati della Dawn.$B$BQualunque cosa tu decida, sappi che il distintivo te lo stai guadagnando. Ben fatto!",
}
T[5403] = {
  title = "Invader's Scourgestones",
  progress = "Un Invader's Scourgestone è l'insegna delle truppe scelte dello Scourge, e a volte si trova sui soldati più forti schierati nelle Plaguelands. Uccidere una di queste creature è una vera sfida, ma chi porta il distintivo e ha il compito di sconfiggere il male dovrebbe accoglierla con piacere.$B$BAl momento The Argent Dawn offre un emblema del valore in cambio di dieci di queste insegne. Portamele qui e farò in modo che tu riceva la giusta ricompensa.",
  reward = "Congratulazioni, $N — sono lieta di consegnarti un emblema del valore dell'Argent Dawn!$B$BOgni emblema del valore consegnato a chi lo merita è il segno che le sorti stanno volgendo contro lo Scourge. Ora che sempre più eroi combattono lo Scourge nelle loro terre, quando verrà il momento di muovere guerra al male supremo dello Scourge l'Argent Dawn sarà di certo in prima linea. Spero che il valore che hai dimostrato per ottenere l'emblema ti porti alla vittoria anche allora!",
}
T[5404] = {
  title = "Corruptor's Scourgestones",
  progress = "Un Corruptor's Scourgestone è l'insegna dei signori dello Scourge: ne possiede uno ogni essere potente che ha autorità sullo Scourge. Uccidere una creatura tanto malvagia farebbe di certo avanzare la causa dell'Argent Dawn, e di tutte le cause giuste!$B$BPer conto dell'Argent Dawn ti darò un emblema del valore in cambio di una sola di queste insegne. Fai attenzione quando cerchi di procurartene una, $N — con esseri così potenti non si scherza.",
  reward = "Congratulazioni, $N — sono lieta di consegnarti un emblema del valore dell'Argent Dawn!$B$BSe hai ottenuto un emblema del valore in questo modo, hai dimostrato di essere $Gun vero eroe:una vera eroina; della causa del bene. Apprezziamo ogni sforzo contro lo Scourge, ma abbattere uno dei suoi capi vuol dire infliggergli una sconfitta davvero schiacciante!$B$BPer la Dawn, $Gfratello mio:sorella mia;!",
}
T[5405] = {
  title = "Argent Dawn Commission",
  reward = "Chiunque combatta il male in nome dell'Argent Dawn deve indossare il nostro distintivo. Con quello addosso, avrai diritto alle ricompense dei nostri intendenti.$B$BFinché lo porterai, potrai ottenere Scourgestone dalle creature dello Scourge che abbatti; sono insegne che a volte hanno con sé. Procuratele e portamele. Per ogni serie che consegnerai riceverai il nostro riconoscimento per l'eroismo — l'Argent Dawn Valor Token.$B$BCompi il tuo destino, $C — unisciti alla lotta oggi stesso!",
}
T[5406] = {
  title = "Corruptor's Scourgestones",
  progress = "Un Corruptor's Scourgestone è l'insegna dei signori dello Scourge. Ogni essere potente che ha autorità sullo Scourge ne porta sempre uno con sé. Uccidere una creatura tanto malvagia farebbe di certo avanzare la causa dell'Argent Dawn, e di ogni giusta causa!$B$BA nome dell'Argent Dawn, ti darò un emblema del valore in cambio di una sola di queste insegne. Procuratene una con prudenza, $N — con esseri così forti non si scherza.",
  reward = "Congratulazioni, $N — sono lieto di consegnarti un emblema del valore dell'Argent Dawn!$B$BOttenere un emblema in questo modo dimostra che sei $Gun vero eroe:una vera eroina; della causa del bene. Apprezziamo ogni sforzo contro lo Scourge, ma abbattere uno dei suoi capi significa infliggergli davvero una sconfitta schiacciante!$B$BPer l'Alba, $Gfratello mio:sorella mia;!",
}
T[5407] = {
  title = "Invader's Scourgestones",
  progress = "Un Invader's Scourgestone è l'insegna delle truppe scelte dello Scourge. A volte si trova addosso ai soldati più forti di stanza nelle Plaguelands. Uccidere una creatura simile è davvero un'impresa, ma chi ha l'incarico di sconfiggere il male dovrebbe affrontarla con entusiasmo.$B$BAl momento The Argent Dawn offre un emblema del valore in cambio di dieci di queste insegne. Portamele qui e farò in modo che tu riceva la giusta ricompensa.",
  reward = "Congratulazioni, $N — sono lieto di consegnarti un emblema del valore dell'Argent Dawn!$B$BOgni emblema assegnato a chi lo merita è un segno che le sorti si stanno volgendo contro lo Scourge. Sempre più eroi combattono lo Scourge nelle sue stesse terre, e quando verrà il momento di muovere guerra al male supremo dello Scourge, l'Argent Dawn sarà di certo in prima linea. Spero che il valore che hai dimostrato per ottenere l'emblema ti porti alla vittoria anche allora!",
}
T[5408] = {
  title = "Minion's Scourgestones",
  progress = "Un Minion's Scourgestone è l'insegna dei soldati semplici dello Scourge. A volte si trova addosso ai più deboli fra le sue truppe schierate nelle Plaguelands, anche se \"deboli\" è una parola da prendere con le pinze. Lo Scourge, ovunque si trovi, non va mai sottovalutato.$B$BAl momento The Argent Dawn offre un emblema del valore in cambio di venti di queste insegne — uno scambio che faccio volentieri, purché tu abbia guadagnato abbastanza scourgestone!",
  reward = "Congratulazioni, $N — sono lieto di consegnarti un emblema del valore dell'Argent Dawn!$B$BGli emblemi servono a due scopi. Primo — puoi usarli per migliorare la tua reputazione presso l'Argent Dawn; così potresti accedere a opzioni e ricompense riservate ai nostri alleati onorati e riveriti. Secondo — puoi darli ai nostri intendenti, insieme al denaro, per pagare alcuni degli oggetti più preziosi dell'Alba.$B$BQualunque cosa tu decida, sappi che ti stai guadagnando il distintivo. Ben fatto!",
}
T[5421] = {
  title = "Pesci in un Secchio",
  progress = "Ricompenso chiunque mi renda la vita un po' più facile... A me piace fare il meno possibile, mon!$B$BHo un sacco di trappole per crostacei sotto i moli, qui a Shadowprey Village. Se sei tanto gentile da fare il lavoro al posto mio e raccogliermi i crostacei, avrai in cambio qualcosa che desideri... capisci l'antifona, mon? Per ogni cinque crostacei che mi porti, ti do un bel Bloodbelly fish!",
  reward = "Fantastico, mon, niente è meglio di un lavoro fatto, soprattutto quando a farlo è qualcun altro... eh?",
  en_title = "Fish in a Bucket",
}
T[5461] = {
  title = "L'Umano, Ras Frostwhisper",
  desc = "I non morti temono la vita quanto i vivi temono la morte. Non è raro che un non morto senziente, dopo la trasformazione, distrugga completamente ogni traccia della vita che aveva prima.$B$BPurtroppo, per creare un artefatto capace di far tornare mortale Ras Frostwhisper, ci serve un grimorio dei suoi anni tra i vivi.$B$BVa' nella città in rovina di Stromgarde, la patria di Frostwhisper, e cerca lì un oggetto del genere. Che la fortuna ti accompagni, $N.",
  obj = "Viaggia verso gli Arathi Highlands, fino alle rovine di Stromgarde. Cerca a Stromgarde un Keepsake of Remembrance. Se trovi un oggetto simile, riportalo a Magistrate Marduke.",
  progress = "Non capita spesso di scoprire un keepsake of remembrance, $N.",
  reward = "Dubitavo che potesse esistere un oggetto simile. Di sicuro ci apre davanti un'occasione incredibile — e non dobbiamo sprecarla.$B$BPreparati, $N, perché quello che sto per chiederti ti porterà nelle profondità dell'inferno.",
}
T[5462] = {
  title = "Il Morente, Ras Frostwhisper",
  desc = "Bisogna sintonizzare il grimorio su un suolo contaminato.$B$BSi dice che Frostwhisper abbia ceduto a The Lich King proprio a Stratholme. Lì, su quel terreno insanguinato, ha dato la vita — di sua volontà e con uno scopo — per diventare uno degli immortali.$B$BEd è quel terreno che bisogna trovare.$B$BC'è un non morto, un dissidente dello Scourge: The Banshee Queen l'ha liberato, ma lui è rimasto fedele alla causa dell'Argent Dawn. Trovalo: si chiama Leonid Barthalomew the Revered, e forse ne sa di più. Va' a Light's Hope, $N.",
  obj = "Viaggia fino a Light's Hope, in Eastern Plaguelands, e cerca Leonid Barthalomew the Revered. Mostragli il Keepsake of Remembrance e raccontagli tutto ciò che hai scoperto.",
  progress = "Non fare domande, se non vuoi sentirne le risposte.",
  reward = "<Leonid esamina il grimorio.>$B$BIl tuo dilemma mi risveglia ricordi che speravo non tornassero mai più a galla.",
}
T[5463] = {
  title = "Menethil's Gift",
  desc = "Ho visto l'umano, Ras Frostwhisper, promettere la sua anima immortale a The Lich King. Si è portato il pugnale alla gola e, sorridendo, se l'è tagliata da un orecchio all'altro. Il corpo è crollato dentro i confini del pentacolo. The Lich King si è fermato sopra il mago caduto: è bastato un gesto, ed è nato Ras Frostwhisper, il lich.$B$B<Leonid fissa il terreno, poi alza lo sguardo verso di te.>$B$BSì, $R, ricordo. Quello che cerchi ha un nome — Menethil's Gift: è il terreno benedetto da The Lich King — terra santa per lo Scourge.",
  obj = "Viaggia fino a Stratholme e trova Menethil's Gift. Posa il Keepsake of Remembrance sul terreno empio.",
  progress = "Tutto intorno al Menethil's Gift fa un freddo straordinario.",
  reward = "Appoggi il grimorio sul suolo contaminato.",
}
T[5464] = {
  title = "Menethil's Gift",
  desc = "L'anima del caduto si aggrappa a ciò che rappresenta la sua vita passata e lo trasforma in un soulbound keepsake. Lo prendi e lo riponi nella sacca.",
  obj = "Porta il Soulbound Keepsake a Leonid Barthalomew in Eastern Plaguelands.",
  progress = "<Leonid rabbrividisce.>",
  reward = "Così come l'anima si è aggrappata al pegno, si aggrapperà alla forma fisica di Ras Frostwhisper.",
}
T[5465] = {
  title = "Soulbound Keepsake",
  desc = "Torna da Marduke e portagli il pegno, $N. Sarà lui a spiegarti come usarlo.",
  obj = "Torna da Magistrate Marduke a Caer Darrow. Mostragli il Soulbound Keepsake.",
  progress = "Hai compiuto l'impossibile?",
  reward = "Ero sicuro che mi avresti raggiunto come un altro spirito sventurato.",
}
T[5466] = {
  title = "Il Lich, Ras Frostwhisper",
  desc = "Ti resta un solo compito, $N. Va' ad affrontare il lich, Ras Frostwhisper, nella sua tana.$B$BUsa contro la bestia il potere del pegno — sii implacabile! Mentre si dibatte, i colpi ti pioveranno addosso di sicuro: resisti. Non cedere al dolore!$B$BQuando il rituale sarà compiuto, Ras tornerà mortale, e a quel punto dovrai ucciderlo. Abbattilo e prendi la sua testa umana.",
  obj = "Trova Ras Frostwhisper in Scholomance. Quando l'avrai trovato, usa il Soulbound Keepsake sul suo volto da non morto. Se riesci a farlo tornare mortale, abbattilo e recupera l'Human Head of Ras Frostwhisper. Riporta la testa a Magistrate Marduke.",
  progress = "Porti il peso di diecimila anime irrequiete, $N.",
  reward = "Diecimila anime gridano insieme, $N! Hai inferto un colpo mortale allo Scourge e ai suoi padroni.",
}
T[5501] = {
  title = "Collezionista di Ossa",
  desc = "Qui c'è una miniera d'oro, te lo dico io — una miniera d'oro! Le Kodo bones cambieranno il mondo per sempre... Ho clienti che ci fanno mobili, strumenti musicali e perfino polvere esplosiva.$B$BUna carovana passa a ritirare le mie kodo bones e poi le vende a Shadowprey Village. Se riesci ad arrivare al cimitero dei kodo, a sud di qui, e a portarmi dieci kodo bones, avrai qualcosa in cambio. Affare fatto?",
  obj = "Porta 10 Kodo Bones da Kodo Graveyard a Bibbly F'utzbuckle a Kormek's Hut.",
  progress = "Hai le ossa? La carovana arriva da un momento all'altro. Mi mancano solo altre dieci kodo bones per stabilire il mio record personale. Il mio record personale, te lo dico io!",
  reward = "Ah, evviva! Le mie ossa!$B$BNon vedo l'ora che i ragazzi a casa vedano la mia faccia sulla copertina di Goblin'preneur. Sarò il goblin più ricco del mondo... e pensare che il mio insegnante di educazione fisica diceva che non sarei mai diventato nessuno.",
  en_title = "Bone Collector",
  en_obj = "Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut.",
}
T[5502] = {
  title = "$GUn Guardiano:Una Guardiana; dell'Orda",
  desc = "Sei $Gstato:stata; tanto gentile con me, $N. Non pensavo proprio che mi sarei divertito così tanto durante la Settimana dei Bambini. Grazie. Non starò triste per quello che mi è successo — i miei genitori mi dicevano sempre di andare oltre tutte le cose brutte che capitano. Diventerò un eroe... proprio come te.$B$BMi dispiace dirlo, ma è ora che torni a casa. Torniamo indietro, così racconto alla matrona che persona fantastica sei!",
  obj = "Riporta il tuo protetto all'orfanotrofio di Orgrimmar consegnando l'Orcish Orphan Whistle a Orphan Matron Battlewail nella Valley of Honor.",
  progress = "Che piacere rivederti, $N. Hai portato a termine i compiti che ti sei $Gofferto:offerta; di svolgere durante la Settimana dei Bambini?",
  reward = "Che gli spiriti ti benedicano, $N. Per Grunth hai fatto più di quanto quasi tutti si sognerebbero mai di fare. Grazie — sei l'esempio perfetto di cosa voglia dire essere $Gun eroe:un'eroina; dell'Orda.$B$BTi prego — se hai tempo, torna a trovarci. So che Grunth ne sarebbe contento, e anch'io.$B$BCon te Grunth si è divertito tanto, $N. Voleva regalarti uno dei suoi animali da compagnia preferiti, così ti ricorderai di lui.",
  en_title = "A Warden of the Horde",
  en_obj = "Return your ward to the Orgrimmar orphanage by handing in the Orcish Orphan Whistle to Orphan Matron Battlewail in the Valley of Honor.",
}
T[5503] = {
  title = "Argent Dawn Commission",
  reward = "Chiunque combatta il male per conto dell'Argent Dawn deve indossare il nostro distintivo. Portandolo, avrai il diritto di riscuotere le ricompense che offrono i nostri furieri.$B$BFinché lo porterai, dalle creature dello Scourge che uccidi potrai ottenere Scourgestone: sono insegne che a volte hanno con sé. Raccoglile e portamele. Per ogni serie che mi consegnerai riceverai il nostro segno di eroismo — l'Argent Dawn Valor Token.$B$BCompi il tuo destino, $C: unisciti alla lotta oggi stesso!",
}
T[5504] = {
  title = "I Ripari della Dawn",
  desc = "Il tuo servizio all'Argent Dawn merita un encomio, $N. Fra noi sei davvero $Griverito:riverita;. Ho il permesso di venderti uno degli oggetti più preziosi della Dawn — i nostri ripari contro la magia.$B$BApplicando un riparo allo spallaccio che porti già, potrai rafforzare le tue difese contro gli incantesimi in uno dei cinque modi possibili. In segno della tua costante dedizione alla nostra causa, per avere questi ripari ti chiedo almeno dieci dei nostri gettoni del valore.",
  obj = "Porta 10 Argent Dawn Valor Tokens a Quartermaster Hasana, al Bulwark, Western Plaguelands.",
  progress = "Ah, nobile $C! Hai portato i gettoni del valore che ti abbiamo chiesto? Consegnameli e potrai acquistare i vari ripari che offriamo.",
  reward = "Eccellente — ho debitamente registrato il tuo tributo alla Dawn, $N. Fatto questo, sono lieta di poterti vendere i nostri ripari. Finché manterrai la reputazione che hai ora presso di noi, potrai comprarli da qualsiasi furiere autorizzato dell'Argent Dawn.$B$BPer la Dawn, $Gfratello mio:sorella mia;!",
}
T[5505] = {
  title = "La Chiave per la Scholomance",
  reward = "Bene, ecco a te, $N — la Skeleton Key, completa. Per quanto ne posso essere certo, con questa chiave potrai entrare nella Scholomance. Ma per esserne assolutamente sicuri c'è un modo solo: provala subito, dico io, senza perdere tempo.$B$BBuona fortuna, $Gpotente eroe:potente eroina;. Che tu possa continuare a portare la luce nell'oscurità!",
}
T[5507] = {
  title = "I Ripari della Dawn",
  desc = "Il tuo servizio all'Argent Dawn merita lode, $N, e fra noi sei davvero $Griverito:riverita;. Mi hanno autorizzato a venderti uno degli oggetti più preziosi della Dawn — i nostri ripari di resistenza alla magia.$B$BSe applichi un riparo allo spallaccio che porti, la tua resistenza ai poteri magici aumenta in uno di cinque modi diversi. Per darti accesso a questi ripari ti chiedo almeno dieci dei nostri emblemi del valore, in segno di costante dedizione alla nostra causa.",
  obj = "Porta 10 Argent Dawn Valor Tokens a Quartermaster Lightspark a Chillwind Camp, Western Plaguelands.",
  progress = "Ah, nobile $C! Hai portato gli emblemi del valore richiesti? Appena me li consegni, potrai acquistare i nostri vari ripari.",
  reward = "Eccellente — prendo debitamente nota del tuo tributo alla Dawn, $N. Ora che è fatto, sono lieto di poterti vendere i nostri ripari. Finché manterrai la posizione che hai presso di noi, potrai acquistarli da qualsiasi quartiermastro autorizzato dell'Argent Dawn.$B$BPer la Dawn, $Gfratello mio:sorella mia;!",
}
T[5508] = {
  title = "Corruptor's Scourgestones",
  progress = "Una Corruptor's Scourgestone è l'insegna dei signori dello Scourge: ogni essere potente che ha il comando sullo Scourge ne porta sempre una. Uccidere una creatura tanto malvagia farebbe di certo avanzare la causa dell'Argent Dawn e di ogni causa giusta!$B$BPer conto dell'Argent Dawn, in cambio di una sola di queste insegne ti darò un emblema del valore. Fai attenzione quando vai a procurartene una, $N — con esseri così potenti non si scherza.",
  reward = "Congratulazioni, $N — è un piacere consegnarti un emblema del valore dell'Argent Dawn!$B$BOttenerne uno in questo modo dimostra che sei $Gun vero eroe:una vera eroina; della causa del bene. Apprezziamo ogni sforzo contro lo Scourge, ma abbattere uno dei suoi capi vuol dire infliggergli una sconfitta davvero schiacciante!$B$BPer la Dawn, $Gfratello mio:sorella mia;!",
}
T[5509] = {
  title = "Invader's Scourgestones",
  progress = "Un'Invader's Scourgestone è l'insegna delle truppe scelte dello Scourge, e a volte la si trova addosso ai più forti fra i soldati di stanza nelle Plaguelands. Uccidere una creatura simile è davvero una sfida, ma è una sfida che chi ha il compito di sconfiggere il male dovrebbe affrontare con piacere.$B$BAl momento The Argent Dawn offre un emblema del valore in cambio di dieci di queste insegne. Portamele qui e farò in modo che tu riceva la giusta ricompensa.",
  reward = "Congratulazioni, $N — è un piacere consegnarti un emblema del valore dell'Argent Dawn!$B$BOgni emblema del valore che va a chi lo merita è un segno che le sorti si stanno volgendo contro lo Scourge. Ci sono sempre più eroi a combattere lo Scourge nelle sue stesse terre, e quando verrà il momento di muovere guerra al male supremo dello Scourge, l'Argent Dawn sarà di certo in prima linea. Spero che il valore che hai dimostrato per ottenere l'emblema ci porti alla vittoria anche allora!",
}
T[5510] = {
  title = "Minion's Scourgestones",
  progress = "Una Minion's Scourgestone è l'insegna delle truppe semplici dello Scourge. A volte la si trova addosso ai più deboli fra i suoi soldati di stanza nelle Plaguelands, anche se \"deboli\" va certo inteso in senso relativo. Ovunque si trovi, lo Scourge non va mai sottovalutato.$B$BAl momento The Argent Dawn offre un emblema del valore in cambio di venti di queste insegne — uno scambio che faccio volentieri, sempre che tu abbia raccolto abbastanza scourgestone!",
  reward = "Congratulazioni, $N — è un piacere consegnarti un emblema del valore dell'Argent Dawn!$B$BGli emblemi servono a due scopi. Uno — si possono usare per migliorare la tua reputazione presso l'Argent Dawn, e così potresti accedere a opzioni e ricompense riservate ai nostri alleati onorati e riveriti. Due — si possono dare ai nostri furieri, insieme a del denaro, per pagare alcuni degli oggetti più pregiati della Dawn.$B$BQualunque cosa tu decida, sappi che il distintivo te lo stai guadagnando. Ben fatto!",
}
T[5511] = {
  title = "La Chiave per Scholomance",
  reward = "Bene, eccola qui, $N — la Skeleton Key completa. Per quanto posso esserne certo, ti permetterà di varcare i confini della Scholomance. Tuttavia, c'è un solo modo per essere assolutamente sicuri che funzioni. Il mio consiglio: non perdere tempo e mettila alla prova.$B$BBuona fortuna, $Gpotente eroe:potente eroina;. Che le tue vittorie continuino a portarti fama e potere mentre metti a ferro e fuoco la Scholomance!",
}
T[5513] = {
  title = "Ripari della Dawn",
  desc = "Quello che hai fatto per l'Argent Dawn merita un encomio, $N, e qui fra noi sei $Griverito:riverita; davvero. Mi hanno autorizzata a mettere in vendita per te uno degli oggetti più preziosi della Dawn — i nostri ripari di resistenza magica.$B$BSe applichi un riparo allo spallaccio che già indossi, la tua resistenza ai poteri della magia aumenterà in uno di cinque modi possibili. Per darti accesso a questi ripari ti chiedo almeno dieci dei nostri emblemi del valore, in segno della tua continua dedizione alla nostra causa.",
  obj = "Porta 10 Argent Dawn Valor Tokens a Quartermaster Breechlock a Light's Hope Chapel, Eastern Plaguelands.",
  progress = "Ah, nobile $C! Hai con te gli emblemi del valore che ti sono stati chiesti? Appena me li consegni, metto in vendita per te i nostri vari ripari.",
  reward = "Eccellente — il tuo tributo alla Dawn è stato registrato a dovere, $N, e ora sono lieta di mettere in vendita per te i nostri ripari. Finché manterrai lo status che hai adesso presso di noi, potrai comprarli da qualsiasi quartiermastro autorizzato dell'Argent Dawn.$B$BPer la Dawn, $Gfratello mio:sorella mia;!",
}
T[5514] = {
  title = "Uno Stampo a Peso d'Oro...",
  desc = "Il goblin con cui dovrai parlare è Krinkle Goodsteel. A Gadgetzan, nel deserto di Tanaris, vende i suoi servigi al miglior offerente. Probabilmente è l'unico in grado di realizzare lo stampo che ci serve, e non lavorerà certo a buon mercato. Ora ti chiediamo di mettere mano al portafoglio e pagare qualunque cifra pretenda.$B$BSono uno speziale, non un banchiere. Se avessi dell'oro da parte, di certo non sarei qui.$B$BMi sa che ho di nuovo detto ad alta voce quello che avrei dovuto tenere per me. Ops.$B$BGadgetzan ti aspetta! Buona fortuna!",
  obj = "Porta gli Imbued Skeletal Fragments e 15 monete d'oro a Krinkle Goodsteel a Gadgetzan.",
  progress = "Sì, so chi sei e so perché sei qui. Dithers mi ha mandato un messaggio prima del tuo arrivo. Veniamo al dunque, che ne dici?$B$BHo uno stampo che puoi usare per la skeleton key, ma ti costerà — quindici monete d'oro, in anticipo, niente trattative. Metterò io gli skeletal fragments nello stampo, e ti insegnerò anche a forgiare il gambo della chiave senza saperne niente di fabbreria... il tutto gratis, per giunta.$B$BChi l'ha detto che i mercenari non fanno offerte vantaggiose!",
  reward = "Dithers aveva detto che avresti consegnato la merce, e così hai fatto! Un patto è un patto; lascia che ti metta i frammenti nello stampo.$B$BDithers li ha già trattati con la sua infusione? Ottimo... altrimenti ti sarebbe toccato un lungo viaggio di ritorno fino al Bulwark.",
}
T[5515] = {
  title = "Krastinov's Bag of Horrors",
  desc = "Ci siamo tolti un grande peso dal cuore, $N, ma il tuo compito non è ancora finito: Kirtonos, il padrone di Krastinov, è ancora vivo.$B$BPrima di affrontare Kirtonos, però, dovrai trovare il modo di evocarlo.$B$BSi dice che sia Jandice Barov a portare il blood of innocents da Krastinov a Kirtonos.$B$BCercala nelle catacombe sommerse della Scholomance e abbattila, poi riportami ogni indizio che riesci a trovare.",
  obj = "Trova Jandice Barov nella Scholomance e distruggila. Recupera dal suo cadavere la Krastinov's Bag of Horrors. Riporta la borsa a Eva Sarkhoff.",
  progress = "<Eva si fa ora sfocata, ora nitida.>",
  reward = "La borsa degli orrori!",
}
T[5517] = {
  title = "Chromatic Mantle of the Dawn",
  desc = "$GFratello:Sorella; $N — hai compiuto così tante imprese per l'Argent Dawn che non è facile raccontarle. Come giusto tributo ti cederò uno dei nostri speciali Chromatic Mantles of the Dawn — una versione che protegge chi lo indossa da tutte le forme di magia a cui si può resistere, tutte in una volta. I Chromatic Mantles of the Dawn sono riservati soltanto ai più potenti eroi della Dawn!$B$BPortami venticinque emblemi del valore in segno di tributo, e ti darò il migliore fra tutti i nostri ripari.",
  obj = "Porta 25 Argent Dawn Valor Tokens a Quartermaster Breechlock a Light's Hope Chapel, Eastern Plaguelands.",
  progress = "Saluti, potente $Gsacerdote:sacerdotessa;! Hai con te gli emblemi del valore che ti ho chiesto? Appena me li consegni, ti darò il tuo Chromatic Mantle of the Dawn.",
  reward = "Davvero notevole, $N — ora il Chromatic Mantle of the Dawn è tuo!$B$BFinché manterrai lo status di Osannato presso l'Argent Dawn, potrai acquistare altri Ripari Cromatici. Li troverai subito disponibili presso qualsiasi quartiermastro della Dawn.",
}
T[5518] = {
  title = "Il Gordok Ogre Suit",
  desc = "Se vuoi affrontare il re di questa discarica — e credo proprio che lo farai — prima dovrai riuscire a passare Captain Kromcrush. Certo, puoi passarlo anche ammazzandolo. Ma forse ti conviene lasciarlo vivo.$B$BCome, chiedi? In tutto il tempo che sono qui, credo di aver capito come si fa un completo da ogre che regga quanto basta per ingannare questi babbei. L'unico guaio è che non sta insieme a lungo: dieci minuti al massimo. Portami quello che mi serve e te ne faccio uno. Tanto non vado da nessuna parte...",
  obj = "Porta 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads e l'Ogre Tannin a Knot Thimblejack. Al momento è incatenato nell'ala dei Gordok di Dire Maul.",
  progress = "Fra le cose che mi servono per il completo, l'Ogre Tannin è probabilmente la più difficile da trovare — credo che ne abbiano un po' al piano di sopra? Difficile dirlo: con questa palla al piede non è che mi muova granché...$B$BComunque, portami quello che mi serve e ti preparo un completo da ogre che farà credere a Captain Kromcrush che sei $Guno:una; dei suoi uomini.",
  reward = "Sì, così funziona. Basta infilare qui e rimboccare qua... eh eh — verrà benissimo! <Un largo sorriso illumina la faccia del goblin in catene.>$B$BEcco qua, sei $Gpronto:pronta;. Ricorda — non è la cosa più solida del mondo. Ti dura dieci minuti, poi cade a pezzi e a quel punto non ingannerai più nessuno! Conviene metterlo appena prima di avvicinarti a lui, e ricorda... crederà che solo TU sia $Gun alleato:un'alleata; — non i tuoi compagni di gruppo!",
}
T[5519] = {
  title = "Il Gordok Ogre Suit",
  progress = "Ti serve un altro completo, eh? Be', a quanto pare da qui non me ne vado tanto presto — portami le stesse cose dell'altra volta e te ne faccio un altro.",
  reward = "Ecco qua, $N — mettitelo addosso e avrai dieci minuti per fare quello che ti pare. Buona fortuna!$B$BAh, e se ti capita di trovare una chiave per tirarmi fuori di qui, FAMMELO SAPERE, MI RACCOMANDO!!!",
}
T[5521] = {
  title = "Chromatic Mantle of the Dawn",
  desc = "$GFratello:Sorella; $N — le imprese che hai compiuto per l'Argent Dawn sono davvero troppe per raccontarle con facilità. Come giusto tributo ti cederò uno dei nostri speciali Chromatic Mantles of the Dawn — una versione che protegge chi lo indossa da tutte le forme di magia a cui si può resistere, tutte insieme. I Chromatic Mantles of the Dawn sono riservati solo ai più potenti fra gli eroi della Dawn!$B$BPortami venticinque emblemi del valore in tributo e ti darò il migliore di tutti i nostri ripari.",
  obj = "Porta 25 Argent Dawn Valor Tokens a Quartermaster Lightspark a Chillwind Camp, Western Plaguelands.",
  progress = "Saluti, potente $C! Hai portato gli emblemi del valore che ti ho chiesto? Consegnameli e ti darò il tuo Chromatic Mantle of the Dawn.",
  reward = "Davvero notevole, $N — ora il Chromatic Mantle of the Dawn è tuo!$B$BFinché manterrai lo stato di Osannato presso l'Argent Dawn, potrai acquistare altri Ripari Cromatici: qualsiasi quartiermastro della Dawn te li metterà subito a disposizione.",
}
T[5522] = {
  title = "Leonid Barthalomew",
  desc = "Mi è arrivato un messaggio dal mio padrone, Vectus. Be', non proprio da Vectus... veniva da un certo Leonid Barthalomew. Io Leonid non lo conosco, ma lui conosceva il mio padrone, e il mio padrone non lo conosce nessuno, se non è lui a volerlo.$B$BLeonid dice che Vectus vuole le uova di drago, e che vuole sia tu a portargliele alla Cappella della Speranza della Luce, nelle Eastern Plaguelands.$B$BQuesta fa male! Perché tu? Vectus non si fida di me? Oh, lascia stare... prendi le uova e di' a Leonid che ho fatto quello che il nostro padrone ha ordinato.",
  obj = "Porta le Frozen Eggs a Leonid Barthalomew in Eastern Plaguelands.",
  progress = "Sei tu $Gquello:quella; che combina guai in Blackrock Spire, vero? Hai quello che ti ho chiesto?",
  reward = "Ah, molto bene. Non sai quale potere malvagio hai servito, ma adesso conoscerai la verità. E non temere — io non servo quel padrone. Sono Leonid Barthalomew, e i miei fratelli dell'Argent Dawn mi chiamano \"il Venerato\".$B$BHo ingannato Tinkee perché mandasse da me te e le uova di drago, ed è un bene che il trucco abbia funzionato: se queste uova fossero arrivate a destinazione, un grande potere sarebbe finito nelle mani del nemico.",
}
T[5524] = {
  title = "Chromatic Mantle of the Dawn",
  desc = "$GFratello:Sorella; $N — hai compiuto per l'Argent Dawn davvero così tante imprese che sarebbe difficile elencarle tutte. Come giusto riconoscimento, ti cederò uno dei nostri speciali Chromatic Mantles of the Dawn — una versione che protegge chi la porta da ogni forma di magia a cui si può resistere, e da tutte nello stesso momento. I Chromatic Mantles of the Dawn sono riservati ai più potenti fra gli eroi della Dawn!$B$BPortami venticinque gettoni del valore in segno di tributo e ti darò il migliore dei nostri ripari.",
  obj = "Porta 25 Argent Dawn Valor Tokens a Quartermaster Hasana, al Bulwark, Western Plaguelands.",
  progress = "Saluti, potente $C! Hai portato i gettoni del valore che ti ho chiesto? Appena me li darai, ti consegnerò il tuo Chromatic Mantle of the Dawn.",
  reward = "Davvero notevole, $N — il Chromatic Mantle of the Dawn ora è tuo!$B$BFinché manterrai la reputazione di Osannato presso l'Argent Dawn, potrai acquistare altri Ripari Cromatici. Li troverai subito in vendita presso qualunque furiere della Dawn.",
}
T[5525] = {
  title = "Libera Knot!",
  progress = "Si chiama Gordok Shackle Key — be', almeno così continuano a chiamarla questi \"paciocconi\". Potrebbe averla uno qualunque degli ogres, credo, ma non saprei dirti chi. Forse è più facile che ce l'abbiano le guardie...$B$BMa che dico — ce l'hai già, vero?! È quella lì??!",
  reward = "Tu — numero uno in classifica. Tutti gli altri — numero due o peggio. Oh, grazie di avermi liberato!$B$BLo sapevo che la mia vita era destinata a qualcosa di più che fare da antipasto a qualche ogre!",
}
T[5526] = {
  title = "Schegge della Vitevile",
  desc = "Ora la tua conoscenza di Eldre'Thalas — Dire Maul — a Feralas tornerà utile, $N. Nella parte orientale della città in rovina, Alzzin the Wildshaper ha imposto il suo dominio corrotto. Recati là in tutta fretta e affronta qualunque sfida ti attenda.$B$BIl Frutto della Fertilità, ormai corrotto e diventato la Vitevile, dovrebbe trovarsi vicino ad Alzzin. Quando cadrà, cattura quanta più essenza della Vitevile puoi, sigillala nel Reliquiario e portala a me.$B$BBuona fortuna, e che Cenarion ti accompagni.",
  obj = "Trova la Vitevile a Dire Maul e prendine una scheggia. Probabilmente riuscirai a procurartene una solo con la morte di Alzzin the Wildshaper. Usa il Reliquary of Purity per sigillarci dentro la scheggia in modo sicuro, e riportalo a Rabine Saturna a Nighthaven, Moonglade.",
  progress = "Con il Sealed Reliquary of Purity nelle nostre mani, potremo non solo eliminare dal mondo una minaccia corruttrice, ma anche studiarla sotto la nostra accorta sorveglianza. Forse riusciremo persino a ideare nuovi mezzi per combattere la contaminazione della corruzione che da sempre incombe su Azeroth.$B$BSo che Milli non avrebbe voluto altrimenti...",
  reward = "È fatta, $Gcoraggioso:coraggiosa; $C, e per questo il Cenarion Circle è in debito con te. La guerra è tutt'altro che finita, ma abbiamo vinto una grande battaglia contro chi vorrebbe portarci alla rovina.$B$BTi prego — accetta questo come segno della nostra eterna gratitudine. Sappi che, per la tua grande impresa, qui sarai $Gaccolto:accolta; come $Gun eroe:un'eroina; del Cenarion Circle, $N. Grazie.",
}
T[5527] = {
  title = "Un Reliquary of Purity",
  desc = "Il primo passo è trovare un contenitore capace di custodire una sostanza estremamente corruttibile senza che chi lo maneggia ne subisca gli effetti nocivi. Conosco un solo tipo di oggetto che potrebbe contenere qualcosa di immondo come la Vitevile: un Reliquary of Purity.$B$BNel cuore delle terre desolate di Silithus si trovano i resti di un villaggio degli elfi della notte, noto come Southwind. Molti, molti anni fa lì ce n'era uno: questo lo so. Se vogliamo riuscire, devi setacciare quelle rovine nella speranza di recuperarlo.",
  obj = "Viaggia fino a Silithus e cerca un Reliquary of Purity fra le rovine di Southwind Village. Se riesci a trovarlo, riportalo a Rabine Saturna a Nighthaven, Moonglade.",
  progress = "Un Reliquary of Purity è già di per sé un manufatto. Ne sono stati creati pochi, e si credeva che col tempo fossero andati perduti quasi tutti.$B$BLo ammetto: di quello di Southwind so da un po'. A dire il vero, con i disordini che crescono a Silithus, ho pensato che fosse meglio che i nostri segreti restassero proprio questo — segreti. Frugare e ficcare il naso non farebbe che destare i sospetti dei nostri nemici.$B$BAhimè, il tempo dell'inerzia è finito, soprattutto vista la situazione a Eldre'Thalas.",
  reward = "Sei davvero $Gingegnoso:ingegnosa; come dicono in molti. È una benedizione per il Cenarion Circle che tu lavori per conto nostro.$B$BOra che il Reliquiario è tornato nelle nostre mani, sono tranquillo: mi sento più a mio agio a chiederti non solo di affrontare un demone maligno, ma anche di riportare, intanto, un oggetto pericoloso...",
}
T[5528] = {
  title = "La Prova d'Assaggio Gordok",
  reward = "Tu adesso grande capo, così tu prendi assaggio gratis di mie birre migliori! Queste bevute pompano te E fanno te $Gbello brillo:bella brilla;! Queste sono quelle buone, capo... tu prova e poi dici tu stesso a Kreeg!",
}
T[5529] = {
  title = "Plagued Hatchlings",
  desc = "The Argent Dawn ha scoperto da poco che lo Scourge si sta creando uno stormo tutto suo di draghi appestati! Dobbiamo impedirglielo — se lo Scourge mette insieme un esercito di draghi, dilagherà per Azeroth e nessuno potrà più fermarlo!$B$BI suoi negromanti li allevano alla Scholomance, in mezzo al Darrowmere Lake.$B$BVai alla Scholomance e uccidi quante più proli puoi... prima che crescano ancora!",
  obj = "Uccidi 20 Plagued Hatchlings, poi torna da Betina Bigglezink alla Light's Hope Chapel.",
  progress = "Vai alla Scholomance, $N. Fai fuori quelle plagued hatchlings prima che crescano!",
  reward = "Ben fatto, $N! Ci vorrà un bel pezzo prima che riescano a far crescere un'altra covata di draghi.$B$B...Almeno, spero!",
}
T[5531] = {
  title = "Betina Bigglezink",
  desc = "Le uova che hai portato erano destinate agli esperimenti dello Scourge, che vuole creare uno stormo di draghi appestati. Queste uova di drago nero congelate sarebbero state preziosissime per i loro studi, e di sicuro li avrebbero fatti avanzare più in fretta.$B$BAdesso è ora di mettere fine alle loro ricerche.$B$BPorta le frozen eggs a Betina Bigglezink, che è qui fuori. Conosce bene la scienza e l'alchimia, e ha creato un'arma da usare contro lo Scourge. Con il tuo aiuto, gli daremo un duro colpo.",
  obj = "Porta le Frozen Eggs a Betina Bigglezink.",
  progress = "Ciao, $N! Mi hanno detto che hai con te delle uova di drago? Be', fammele vedere!",
  reward = "Eccole! E in un contenitore così carino. Della misura perfetta!$B$BMetteremo queste uova al sicuro per studiarle più avanti, ma adesso ci serve la cosa in cui le hai portate.$B$BHo creato un congegno con uno scopo ben preciso: distruggere gli studiosi non morti della Scholomance. Fanno ricerche sui draghi per creare uno stormo di draghi appestati, e dobbiamo impedire che vadano avanti.$B$BL'ho chiamato Dawn's Gambit, perché... non sono sicura che funzioni!$B$BLo scopriresti tu per noi?",
}
T[5533] = {
  title = "Scholomance",
  desc = "Sull'isola di Caer Darrow si trova la Scholomance — un abominevole centro di negromanzia e malvagità dello Scourge. Lì dimora il nostro nemico, che compie indicibili atti di depravazione su vittime ignare... o almeno, così supponiamo. Il passaggio è sbarrato da una porta e, per quanto ci proviamo, senza una chiave adatta non c'è modo di entrare.$B$BAlchemist Arbington conosce bene la Scholomance e ha un'idea su come procurarsi una chiave. Mi hai dimostrato quanto vali, e ora questo compito lo affido a te. Va' a parlarne con lui.",
  obj = "Parla con Alchemist Arbington a Chillwind Point, Western Plaguelands.",
  reward = "$GBen trovato:Ben trovata;, $C. Negli ultimi tempi ho dedicato buona parte dei miei studi alla Scholomance, e credo di sapere come potresti procurarti una chiave... una che ti permetta di superare la porta d'ingresso.$B$BQuali orrori si vedano là dentro, $N, posso solo immaginarlo. A volte proprio non so come facciate, voi eroi...",
}
T[5534] = {
  title = "L'Equipaggiamento \"Smarrito\" di Kim'jael",
  desc = "Cosa?! Cosa?!$B$BNon ti è bastato? Hai idea di quanto costano quegli esplosivi? Li vendono a... oh, lascia perdere. E va bene, vuoi fare soldi veri? Perché gli affari funzionano così: dimostri di essere $Gun:una; dipendente $Gprezioso:preziosa;, tieni duro per un po', e poi vieni $Gricompensato:ricompensata; a dovere.$B$BSe sei $Gun:una; dipendente \"$Gprezioso:preziosa;\", allora vai alle Ruins of Eldarath e trovami la some rune che cercavano quegli elfi del Sangue. Pare che ce l'abbiano i naga.",
  obj = "Trova la Some Rune che i naga hanno in loro possesso nelle Ruins of Eldarath e riportala a Kim'jael in Azshara.",
  progress = "Allora, $N? Dov'è la runa? Sei $Gun bravo:una brava; dipendente, no? Sei qui per dare una mano?$B$BNon farmi venire dubbi sul pagarti quanto abbiamo concordato. Cosa? Oh, non abbiamo concordato niente? Oh, magnifico... allora fai pure con comodo — sappi solo che, se ci metti tanto, sarà molto meno.",
  reward = "Ahah! Meraviglioso!$B$BDi sicuro scoprirò a cosa serve e perché la voleva Magus Rimtori — la megera che mi ha assunto. Ah! Adesso vi ho in pugno, puzzolenti elfi del Sangue! Kim'jael! Ah! Gli faccio vedere io chi sono i ratti!$B$BHai fatto un buon lavoro, $N. Grazie mille. Tieni, prendi questi soldi e fila — ho delle cose da capire.",
}
T[5535] = {
  title = "Inquietudine Spirituale",
  desc = "Tanto tempo fa, gli Highborne erano fra i più potenti studiosi delle arti arcane che gli elfi della notte abbiano mai avuto. Ma studi simili portano con sé la corruzione, che ha fatto molto danno alla loro società e ha colpito duramente tutta Azeroth... e sono certo che lo sai bene.$B$BAlle Sentinelle ho promesso che avrei liberato dai legami mortali ogni spirito che avessi trovato. Se farai lo stesso, sono certo di poterti dare una piccola ricompensa.$B$BGli spiriti infestano lo Shadowsong Shrine, qui a nord-est.",
  obj = "Distruggi 6 Highborne Apparitions e 6 Highborne Lichlings, poi torna da Loh'atu ad Azshara.",
  progress = "Come va la caccia agli spiriti degli Highborne, $C?$B$BSono tante le cose che hanno fatto soffrire molto tutte le razze di Azeroth, ma questi spiriti, chissà perché, sembrano una piaga per ogni popolo. Forse dipende dal desiderio di qualunque magia arcana, che non li abbandona mai — un desiderio così è un presagio della Burning Legion, e sappiamo dove può portare.",
  reward = "Ben fatto, $C, e grazie dell'aiuto. Ora gli spiriti sono in pace, e le minacce che il loro desiderio dell'arcano attirava si sono ridotte.$B$BLe due parti del conflitto che devasta Azeroth, ne sono certo, vedranno che stai al di sopra di queste cose.",
}
T[5536] = {
  title = "Una Terra Piena d'Odio",
  desc = "I satiri, aspetto deforme e malvagio degli elfi della notte, oggi infettano le terre sacre dove un tempo camminava Cenarius. Di tutte le atrocità commesse da quelle creature demoniache non posso parlare a nome degli elfi della notte, ma alla Madre Terra ho giurato di aiutare gli elfi a liberare la terra da un fastidio del genere.$B$BSe mi aiutassi a eliminarli, sono certo che dimostreresti il tuo valore.$B$BIl clan Haldarr lo troverai qui a nord-est. Torna da me quando ti sarai $Gmisurato:misurata; con il loro potere.",
  obj = "Uccidi 6 Haldarr Satyr, 2 Haldarr Tricksters e 2 Haldarr Felsworn, poi torna da Loh'atu al confine con Ashenvale.",
  progress = "Come va la battaglia contro i satiri, $C?$B$BSono forti come pensavi? Di più? O forse non erano niente in confronto alla tua potenza.",
  reward = "Ben fatto, $C. Vedo che oltre che abile sei anche $Gastuto:astuta;. Sconfiggere creature simili prova che sei fedele ai principi della Madre Terra, anche se non la riconosci come tua divinità. Lei è in ogni cosa di questo pianeta, e anche oltre. I suoi occhi, uno scuro e uno chiaro, viaggiano per i cieli e ci guardano sempre dall'alto.$B$BAccetta queste poche monete, ti prego, come ringraziamento per quello che hai fatto.",
}
T[5537] = {
  title = "Skeletal Fragments",
  desc = "La chiave della Scholomance ha un nome: Skeleton Key. Va forgiata con i resti di uno scheletro — anzi, di parecchi — e temprata, dentro uno stampo adatto, soltanto con i metalli più resistenti. A farla funzionare, alla fine, sarà il sigillo di potere di un essere che per sua natura può aprire il portale della Scholomance.$B$BMa andiamo con ordine, $N. Per forgiarla ci serviranno degli skeletal fragments. Quello che cerchiamo dovrebbero darcelo gli scheletri dentro Andorhal, ma potrebbero andar bene anche quelli fuori dalle mura.",
  obj = "Porta 15 Skeletal Fragments ad Alchemist Arbington a Chillwind Point, Western Plaguelands.",
  progress = "Lo so, suona macabro, ma ci servirà una buona scorta di skeletal fragments adatti a fare lo strato esterno della chiave. Non per niente la chiamano Skeleton Key, sai.",
  reward = "Questi andranno bene, $N! Adesso tocca a me — infonderò loro una tempra adatta, che li faccia reggere all'intensa forgiatura che li aspetta.$B$BIl prossimo passo sarà procurarci lo stampo giusto per la chiave. A Tanaris conosco un fabbro goblin che in passato ha fatto stampi per oggetti altrettanto macabri. Lavora per il padrone di sempre dei goblin — il miglior offerente.",
}
T[5538] = {
  title = "Stampo Fa Rima con...",
  desc = "Il goblin da cui dovrai andare si chiama Krinkle Goodsteel, e a Gadgetzan, nel deserto di Tanaris, vende le sue abilità al miglior offerente. Probabilmente è l'unico capace di fare lo stampo che ci serve, e non si farà pagare poco. Adesso ti chiediamo di mettere mano alla borsa e di pagare quello che pretende, qualunque somma sia.$B$BSono un alchimista, non un banchiere. Se avessi messo da parte un po' d'oro, non sarei certo qui.$B$BMi sa che mi è scappato di nuovo quello che dovevo tenere per me. Ops.$B$BGadgetzan ti aspetta! Buona fortuna!",
  obj = "Porta gli Imbued Skeletal Fragments e 15 monete d'oro a Krinkle Goodsteel a Gadgetzan.",
  progress = "Sì, so chi sei e perché sei qui. Arbington mi ha avvisato prima che arrivassi. Parliamo d'affari, che ne dici?$B$BPer la skeleton key ho uno stampo che fa al caso tuo, ma ti costerà — quindici monete d'oro, in anticipo, e non si tratta. Agli skeletal fragments nello stampo ci penso io, e ti insegno anche a forgiare il fusto della chiave senza che tu sappia niente di forgiatura... il tutto gratis, per giunta.$B$BE poi dicono che i mercenari non fanno prezzi competitivi!",
  reward = "Arbington aveva detto che avresti portato la merce, e così è stato! I patti sono patti; lascia che metta i frammenti nello stampo.$B$BArbington li ha già infusi? Ottimo... sennò ti sarebbe toccato un lungo viaggio di ritorno fino a Chillwind Point.",
}
T[5542] = {
  title = "Cani Demoniaci",
  desc = "Se vuoi restare qui, ti chiedo solo di guadagnarti il pane. Ci sono parecchie seccature che avrebbero bisogno di un po' di 'disciplina'.$B$BPuoi cominciare dai Plaguehounds e dai loro giovani.$B$BNon ho molto da offrirti in cambio, ma se ce la fai un pasto caldo e due chiacchiere non ti mancheranno di sicuro.",
  obj = "Uccidi 20 Plaguehound Runts, 5 Plaguehounds e 5 Frenzied Plaguehounds. Torna da Tirion Fordring quando il compito è concluso.",
  progress = "Nessuna pietà per i cani demoniaci, $R. Sono abomini!",
  reward = "Ben fatto, $N. Vieni. Riposati. Mangiamo insieme e parliamo dei tempi andati!",
}
T[5543] = {
  title = "Cieli Tinti di Sangue",
  desc = "Guai a chi si spinge senza giudizio nelle Plaguelands. In questi boschi vive ogni sorta di creatura immonda — dalla fanatica Scarlet Crusade, che uccide chiunque non porti il suo marchio, al sanguinario Scourge, che pensa solo a ingrossare le proprie file con altri non morti.$B$BPerfino gli animali selvatici sono diventati bestie voraci, mangiatrici di uomini. Ti chiedo di distruggere quelli che attaccano dal cielo: i Plaguebats.",
  obj = "Uccidi 30 Plaguebats e torna da Tirion Fordring.",
  progress = "Non sottovalutare quelle bestiacce alate, $R. La Piaga ha dato loro poteri soprannaturali.",
  reward = "Sei uno splendido esempio di rettitudine, $R! Era da tanto che non sentivo pulsare nelle vene il sangue degli eroi. Il tuo coraggio mi risolleva lo spirito!",
}
T[5544] = {
  title = "Sbobba Carogna",
  desc = "Le scorte di cibo stanno finendo, $R. Mi vergogno ad ammetterlo, ma forse non ne ho abbastanza da dividere con te.$B$BAiuteresti un vecchio in un compito semplice? Da queste parti le sole bestie scampate alla devastazione della Piaga sono i vermi Carogna. La loro carne ha un sapore piuttosto insipido, ma si conserva per mesi senza fatica. Me ne serviranno parecchie centinaia di libbre per rifornirmi in vista del prossimo inverno!",
  obj = "Cerca i Carrion Grubs e Devourers della regione. Uccidili e raccogli la loro carne. Torna da Tirion Fordring quando avrai raccolto 15 Slabs of Carrion Worm Meat.",
  progress = "Col tempo imparerai a sopportarne il sapore, $R.",
  reward = "Che la Luce vegli su di te! Che tu sia $Gbenedetto:benedetta;, giovane.",
}
T[5561] = {
  title = "Il Raduno dei Kodo",
  desc = "Bibbly crede di essere l'unico goblin di Desolace che sappia fare soldi. Be', l'unica carovana che ha il coraggio di viaggiare da queste parti dipende da me. Da quando ho imparato a ringiovanire e a controllare i kodo anziani e i dying kodos col mio kodo kombobulator, il proprietario della carovana, Cork, Rigger e io siamo diventati soci.$B$BPrendi il kombobulator e usalo sui kodo antichi, su quelli anziani o sui dying kodos; la bestia prenderà una scossa che la trasformerà in un tamed kodo e la costringerà a seguirti. Una volta domato un kodo, riportamelo.",
  obj = "Riporta cinque Tamed Kodos e il Kodo Kombobulator a Smeed Scrabblescrew a Scrabblescrew's Camp.",
  progress = "La carovana arriva fra poco; hai i cinque nuovi tamed kodos che ti ho chiesto?",
  reward = "<Smeed Scrabblescrew comincia a contare.>$B$BTre, quattro e cinque... eccellente, chiedo cinque tamed kodos e ricevo cinque tamed kodos... diventerò ricco... sì, ricchissimo! Spero di vedere la faccia verde di Bibbly quando saprà del mio successo!",
  en_title = "Kodo Roundup",
  en_obj = "Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp.",
}
T[5581] = {
  title = "Portali della Legione",
  desc = "Ecco — l'Hand of Iruxos. Uno spettacolo raccapricciante.$B$BTi serve per esiliare i demon portals della Mannoroc Coven... ed è proprio quello che ora ti chiedo. La minaccia dei Demoni cresce, e per arginare l'ondata che si riversa su questo mondo dobbiamo chiuderli. Buona fortuna, $N... e fai attenzione ai guardiani dei portali.",
  obj = "Esilia 6 Portali alla Mannoroc Coven e torna da Taiga Wisemane a Shadowprey Village.",
  progress = "Hai esiliato i demon portals alla Mannoroc Coven?",
  reward = "Meriti di essere $Glodato:lodata;, $N. Il tuo impegno ha dato un grande aiuto alla lotta contro la minaccia demoniaca e ha reso più sicura tutta Azeroth.",
  en_title = "Portals of the Legion",
  en_obj = "Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village.",
}
T[5582] = {
  title = "Healthy Dragon Scale",
  desc = "La scaglia si è staccata da un cucciolo di drago appestato. Le altre scaglie della giovane bestia sono butterate e trasudanti, ma questa, cosa rara, è sana e intatta.$B$BBetina Bigglezink vorrà studiarne un campione.",
  obj = "Porta l'Healthy Dragon Scale a Betina Bigglezink alla Cappella della Speranza di Luce, in Eastern Plaguelands.",
  progress = "Hai qualcosa da farmi vedere, $N?",
  reward = "Eccellente! Per i miei studi sulle macchinazioni dello Scourge mi sarà preziosissima. Grazie, $N, e se ne trovi altre come questa, portamele!",
}
T[5601] = {
  title = "Sorella Pamela",
  desc = "Durante la grande guerra sono fuggita da Lordaeron, e ho avuto la fortuna di andarmene prima che lo Scourge dilagasse nella mia terra natale e ne facesse un incubo appestato! A me è andata bene, alla mia famiglia no. Temo che li abbiano uccisi tutti nella battaglia di Darrowshire.$B$BDarrowshire è un villaggio degli Eastern Kingdoms, adagiato fra le colline meridionali di quelle che oggi sono le Eastern Plaguelands. Ci andresti a cercare la mia famiglia? Mi mancano tantissimo, e più di tutti la mia sorellina Pamela.$B$BTi prego, trovala per me!",
  obj = "Trova Pamela Redpath a Darrowshire.",
  reward = "Dov'è mia sorella Jessica? È andata via tanto tempo fa, quando ero solo una bambina. Quando se n'è andata ha pianto tanto. Non so perché ha pianto! Magari è caduta e ha sbattuto il dito del piede.$B$BQuando c'era Jessica giocavamo, ballavamo e raccoglievamo dei bei fiori intorno alla casa. E certe volte, quando vedevamo papà che tornava, ci nascondevamo e poi saltavamo fuori per fargli una sorpresa!$B$BTorna, Jessica! Se torni magari torna anche papà, e possiamo giocare di nuovo tutti insieme...",
}
T[5621] = {
  title = "Vesti della Luna",
  desc = "Ho bisogno del tuo aiuto, $N. Io devo restare qui ad addestrare gli altri allievi, ma tu sì che puoi soccorrere una delle nostre Sentinelle, appena a sud di Dolanaar. È rimasta ferita mentre pattugliava il villaggio e le servirebbe il nostro sostegno. Si chiama Shaya.$B$BQuando la trovi, curale le ferite e poi rafforzane il corpo con i tuoi incantesimi. Così, se dovesse cacciarsi nei guai, almeno sarà protetta più a lungo. Quando avrai compiuto il tuo dovere verso Elune, torna qui da me.",
  obj = "Trova Sentinel Shaya e curale le ferite con Lesser Heal (Grado 2). Poi concedile Power Word: Fortitude e torna da Laurna Morninglight a Dolanaar.",
  progress = "I nostri incantesimi di Fortificazione sono molto potenti, Delor. Permettono ai compagni di sopportare più danni da qualsiasi attacco e di sopravvivere là dove altrimenti cadrebbero. Ma non sono niente in confronto alla nostra capacità di guarire. Nessun guaritore è più grande di un sacerdote — ricordatelo bene. Il tuo potere, da solo, può facilmente cambiare le sorti di una battaglia.",
  reward = "Hai agito bene e hai servito Elune. Per questo ti ringrazio.$B$BTi prego, prendi questa veste in segno della mia gratitudine. Significa che ti sei $Gguadagnato:guadagnata; un posto nel nostro ordine. Se vuoi, indossala con orgoglio, ma in ogni caso ti riconosceremo sempre come $Guno:una; dei nostri.$B$BVa' con Elune, $N, e grazie.",
  en_title = "Garments of the Moon",
  en_obj = "Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar.",
}
T[5622] = {
  title = "Nella Grazia di Elune",
  desc = "$N, quando avrai finito ciò che devi fare qui a Shadowglen, dovrai recarti a Dolanaar. Lì troverai Laurna Morninglight. Sarà lei a proseguire la tua istruzione nelle vie di Elune, ed è con lei che ti guadagnerai le prime vesti, segno del tuo rango di $Gsacerdote:sacerdotessa; di Elune.$B$BAbbi cura di te, e possa tu essere $Gprotetto:protetta; nei tuoi viaggi.",
  obj = "Parla con Laurna Morninglight a Teldrassil.",
  reward = "Sono lieta che Shanda ti abbia mandato da me, $N. Insegnare ai giovani sacerdoti le vie di Elune mi dà grande soddisfazione.",
  en_title = "In Favor of Elune",
  en_obj = "Speak to Laurna Morninglight in Teldrassil.",
}
T[5623] = {
  title = "In Favore della Luce",
  desc = "$GBen ritrovato:Ben ritrovata;, giovane $Gsacerdote:sacerdotessa;. È giunto il momento che tu approfondisca la nostra fede. Quando avrai portato a termine i compiti che ti restano qui a Northshire, cerca Priestess Josetta a Goldshire. Ha altro da insegnarti, e le è giunta voce che stai diventando sempre più forte nelle vie della Luce. Non vede l'ora di continuare a istruirti.",
  obj = "Parla con Priestess Josetta a Elwynn Forest.",
  reward = "Sono lieta che tu sia $Garrivato:arrivata;, $N. Abbiamo molto di cui parlare: il tuo futuro e il tuo cammino nella Luce.",
  en_title = "In Favor of the Light",
  en_obj = "Speak to Priestess Josetta in Elwynn Forest.",
}
T[5624] = {
  title = "Vesti della Luce",
  desc = "Di solito propongo ai seguaci della Luce una piccola prova per verificarne le capacità. Voglio vedere se sono degni di indossare la prima veste — un segno che la chiesa dà pubblicamente il suo benestare $Gal sacerdote:alla sacerdotessa; e $Glo:la; sostiene.$B$BMa stavolta la situazione è un po' diversa. Un abitante di Goldshire ha visto una guardia ferita vicino al lago, a est di qui. Si chiama Roberts. Trovalo, curalo, rafforzagli il corpo e torna da me. Se ci riuscirai, considererò superata la prova.",
  obj = "Trova Guard Roberts e cura le sue ferite con Lesser Heal (Rank 2). Poi lanciagli Power Word: Fortitude e torna da Priestess Josetta a Goldshire.",
  progress = "Come forse avrai già capito, in tempi così duri la magia curativa è vitale per la sopravvivenza della nostra gente — soprattutto per gli avventurieri e gli eroi che prendono le armi e ricorrono alla magia per respingere tante minacce diverse.$B$BFaresti bene a ricordare sempre quanto sia importante questa capacità. Unita all'incantesimo Fortitude, la guarigione rende i tuoi compagni molto più efficaci in battaglia, perché potranno reggere più colpi.$B$BNon permettere a nessuno di sminuire la potenza della tua magia.",
  reward = "Eccellente, $N. Con una guardia in salute in più a proteggere il paese, saremo tutti un po' più al sicuro. Mi fa piacere vedere che impari già a usare con saggezza le tue capacità. Quando ti sentirai $Gpronto:pronta; per un nuovo addestramento, torna pure da me. Per ora, però, prendi questa veste. Farà sapere agli altri che fai parte del nostro ordine. Se non vuoi indossarla, va bene lo stesso. Più avanti ci saranno altre prove, e per quelle non sarà necessaria.",
  en_title = "Garments of the Light",
  en_obj = "Find Guard Roberts and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Priestess Josetta in Goldshire.",
}
T[5625] = {
  title = "Vesti della Luce",
  desc = "Di solito è più o meno a questo punto che si mette alla prova chi ha il tuo potere, per vedere se è degno di indossare la veste che indica il suo posto nella chiesa. Ma a dirla tutta, ho cose più urgenti a cui pensare. È appena passato di qui un cittadino di Kharanos e m'ha detto che c'è un montanaro ferito appena fuori città, a sud — si chiama Dolf.$B$BTu curi Dolf e gli dai Fortitude, e per me avrai dimostrato quanto vali. Che te ne pare?",
  obj = "Trova Mountaineer Dolf e curagli le ferite con Lesser Heal (Grado 2). Poi lanciagli Power Word: Fortitude e torna da Maxan Anvol a Kharanos.",
  progress = "Hai già trovato Dolf, $N?$B$BProbabilmente lo sai già, ma saper curare ci rende molto utili. Non solo possiamo prenderci cura dei feriti: siamo indispensabili perché sopravvivano tutti quegli aspiranti eroi là fuori che cercano di farsi un nome. Con Fortitude per incassare più colpi e la nostra magia curativa per tenerli in vita, non c'è niente che non possiamo superare!",
  reward = "Ben fatto, $N. La Luce è dentro di te, non c'è dubbio.$B$BTieni, prendi questa veste. Mostrerà il tuo ruolo nella chiesa e aiuterà la gente a riconoscerti come $Gun:una; $C — indossala, se vuoi.$B$BPiù avanti avrai altre prove da superare. Fa' il possibile per conoscere le tue abilità e quello di cui sei capace. Prova a combattere un paio di volte da $Gsolo:sola;, e poi insieme ad altri viaggiatori.$B$BMa non stare in pensiero... sei potente come pochi altri.",
  en_title = "Garments of the Light",
  en_obj = "Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.",
}
T[5626] = {
  title = "In Favore della Luce",
  desc = "Ehi! $N! Hai un minuto?!$B$BSegui la Luce da un bel po' ormai, abbastanza per andare da Maxan Anvol a Kharanos. Lui t'insegnerà di più sul cammino che stai percorrendo e, se ti dimostrerai $Gdegno:degna;, ti darà la tua prima veste, il segno del tuo rango di $Gsacerdote:sacerdotessa;.$B$BE adesso muoviti! Quando hai finito qui, passa per la galleria — lui ti aspetterà.",
  obj = "Parla con Maxan Anvol a Dun Morogh.",
  reward = "Oh, allora t'ha $Gmandato:mandata; Branstock, eh? Bene, bene! Ha ragione: è proprio ora che tu faccia un passo molto più grande nella Luce. Ti forgerà il carattere e ti renderà più forte... ed è quello che ti servirà più di tutto: forza del corpo... forza di volontà.",
  en_title = "In Favor of the Light",
  en_obj = "Speak to Maxan Anvol in Dun Morogh.",
}
T[5627] = {
  title = "Stelle di Elune",
  reward = "Hai dato prova di essere $Gdegno:degna; dell'attenzione di Elune, $N. Se ti senti $Gpronto:pronta;, sarei davvero felice di insegnarti uno dei suoi incantesimi, che conosce soltanto il nostro popolo.",
  en_title = "Stars of Elune",
}
T[5628] = {
  title = "Ritorno a Casa",
  desc = "Ah, sì, salve, $N? Che piacere che tu ti sia $Gfermato:fermata; a parlare un momento. Così $Ggiovane:giovane; e così $Glontano:lontana; da casa — un'ambizione che ammiro. Quanto avrei voluto trovare il coraggio di girare il mondo, quando ero giovane.$B$BPoco tempo fa è passata di qui una sacerdotessa del tuo ordine, e cercava proprio te. Ha detto che dovevi tornare al Tempio della Luna a Darnassus e parlare con Priestess Alathea, ed era molto urgente — si trattava del tuo addestramento. Se puoi, cerca di non indugiare troppo.",
  obj = "Parla con Priestess Alathea a Darnassus.",
  reward = "Meraviglioso, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere vedere chi abbiamo addestrato partire per il mondo e poi tornare da noi sano e salvo. Come te la sei passata? Elune continua a benedire i tuoi viaggi? Quando avremo parlato ancora della questione che ci riguarda, forse potrai raccontarmene di più.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5629] = {
  title = "Ritorno a Casa",
  desc = "$GBen ritrovato:Ben ritrovata;, $N. So che sei $Gstato:stata; $Goccupato:occupata; ad aiutare il nostro popolo, ma devi anche ritagliarti un po' di tempo per te. Priestess Alathea ha mandato qualcuno qui a cercarti. A quanto pare hai attirato l'attenzione dei nostri anziani, che ti ritengono $Gpronto:pronta; per cose più grandi. Va' al Tempio della Luna, a Darnassus, e cerca Alathea: ti starà aspettando. Buona fortuna, e che Elune sia con te.",
  obj = "Parla con Priestess Alathea a Darnassus.",
  reward = "Splendido, sei $Gtornato:tornata;, $N. A Tyrande e a me fa sempre piacere vedere chi abbiamo addestrato partire per il mondo e tornare da noi sano e salvo. Com'è andata? Elune benedice ancora i tuoi viaggi? Forse, quando avremo parlato della faccenda che ci riguarda, potresti raccontarmene di più.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5630] = {
  title = "Ritorno a Casa",
  desc = "Ehilà, $Gragazzo:ragazza;. Fa piacere vederti girare in lungo e in largo, fino a terre lontane. Senza offesa, ma di solito tanti della tua gente questi climi freddi non li sopportano granché. Sono contento che tu abbia la scorza più dura.$B$BPoco tempo fa è passata di qui una delle vostre sacerdotesse che ti cercava — diceva che dovevi trovare una certa Priestess Alathea nel Tempio della Luna, laggiù a Darnassus. Ha detto che era importante e che dovevi tornarci presto.",
  obj = "Parla con Priestess Alathea a Darnassus.",
  reward = "Splendido, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere vedere coloro che abbiamo addestrato avventurarsi nel mondo e tornare da noi sani e salvi. Com'è andata? Elune benedice ancora i tuoi viaggi? Forse, quando avremo discusso della questione che ci attende, potrai raccontarmene di più.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5631] = {
  title = "Ritorno a Casa",
  desc = "Giovane $R, poco tempo fa una sacerdotessa è venuta a cercarti nelle nostre sale. Ha detto che il suo compito era trovarti, e che devi tornare al più presto al Tempio della Luna di Darnassus. Una volta là, cerca Priestess Alathea — ti dirà di più.$B$BChe la Luce sia con te, $N.",
  obj = "Parla con Priestess Alathea a Darnassus.",
  reward = "Magnifico, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Com'è andata? Elune benedice ancora i tuoi viaggi? Forse, quando avremo discusso della questione che ci attende, potresti raccontarmene di più.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5632] = {
  title = "Ritorno a Casa",
  desc = "Oh, sì, certo. Salve, $N. Poco fa è passata di qui una messaggera del nostro ordine che ti cercava. Ha parlato di qualcosa di importante che sta succedendo a Darnassus, e ha detto che dovresti tornare al Tempio della Luna appena puoi. Quando arrivi, parla con Priestess Alathea. Credo che abbia a che fare con i tuoi ottimi progressi nel nostro cammino.$B$BTe lo ripeto, torna a Darnassus quando puoi.",
  obj = "Parla con Priestess Alathea a Darnassus.",
  reward = "Che bello, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando quelli che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti va? Elune benedice ancora i tuoi viaggi? Forse potrai raccontarmene di più quando avremo approfondito la questione che ci riguarda.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5633] = {
  title = "Ritorno a Casa",
  desc = "Salve, $Gragazzo:ragazza;. Fa piacere vederti qui, nelle nostre grandi sale. Benedetti siate, tu e la tua gente.$B$BMentre giravi per le nostre terre, è venuta qui a cercarti una sacerdotessa del tuo tempio. Ha detto che devi tornare al Tempio della Luna il prima possibile. Non so dirti altro, mi dispiace, ma sembrava una cosa importante. Appena arrivi al tempio, parla con Priestess Alathea.",
  obj = "Parla con Priestess Alathea a Darnassus.",
  reward = "Magnifico, $N, sei $Gtornato:tornata; a casa. A Tyrande e a me fa sempre piacere vedere coloro che abbiamo addestrato partire per il mondo e poi tornare da noi sani e salvi. Com'è andata? Elune benedice ancora i tuoi viaggi? Magari, quando avremo parlato più a fondo della questione che ci occupa, potresti raccontarmi qualcosa di più del tuo cammino.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5634] = {
  title = "Desperate Prayer",
  desc = "Giovane $R, poco tempo fa un sacerdote è venuto a cercarti nelle nostre sale. Ha detto che il suo compito era trovarti, e che devi tornare al più presto all'Hall of Mysteries di Ironforge. Una volta là, cerca High Priest Rohan — ti dirà di più.$B$BChe la Luce sia con te, $N.",
  obj = "Parla con High Priest Rohan a Ironforge.",
  reward = "Sei $Gdiventato:diventata; un esempio luminoso per chi viaggia in queste terre pericolose e oltre, e così hai reso un grande servizio alla Luce. Accetta questa lezione, ti prego, come ringraziamento per tutto ciò che hai fatto.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5635] = {
  title = "Desperate Prayer",
  desc = "Hai attirato l'attenzione dei nostri superiori, $N. Ti chiedono di andare all'Hall of Mysteries a Ironforge il prima possibile. A quanto pare per loro hai già dimostrato quanto vali, e sono pronti a portare avanti il tuo addestramento. Appena arrivi, cerca High Priest Rohan: sarà lui a guidarti da lì in poi. Buona fortuna, e che la Luce sia con te.",
  obj = "Parla con High Priest Rohan a Ironforge.",
  reward = "Sono lieta che tu sia $Garrivato:arrivata;, $N. Abbiamo molte cose da discutere, ma prima di tutto viene il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che ogni servitore della Luce deve imparare. Se sei $Gpronto:pronta;, cominciamo subito a vederne alcune.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5636] = {
  title = "Desperate Prayer",
  desc = "Che Elune ti benedica, $Gbuon:buona; $R. Spero che oggi la tua Luce ti trovi e ti protegga a dovere.$B$BPoco fa è passato di qui uno dei tuoi sacerdoti a cercarti. Ha detto che dovresti tornare il prima possibile all'Hall of Mysteries per parlare con High Priest Rohan. A quanto pare hai lavorato bene, se hai attirato tanta attenzione. Non mi fermerei troppo qui — la tua gente ha bisogno di te.",
  obj = "Parla con High Priest Rohan a Ironforge.",
  reward = "Sono contenta che tu sia $Garrivato:arrivata;, $N. Dovremo discutere di molte cose, ma la più importante è il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominciamo subito da alcune.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5637] = {
  title = "Desperate Prayer",
  desc = "È ora che tu vada a Stormwind, $N. High Priest Rohan, nell'Hall of Mysteries, vuole parlarti. Se il Gran Sacerdote ti vuole lì di persona, dev'essere qualcosa di molto buono o di molto brutto, ma scommetto che ti sei solo $Gfatto:fatta; onore e che ti cerca per una buona ragione.$B$BComunque non perdere troppo tempo qui intorno. Io ci andrei il prima possibile.",
  obj = "Parla con High Priest Rohan a Ironforge.",
  reward = "Sono lieta che tu sia $Garrivato:arrivata;, $N. Dovremo parlare di molte cose, ma la più importante è il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che ogni servitore della Luce deve imparare. Se sei $Gpronto:pronta;, cominceremo subito ad affrontarne alcune.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5638] = {
  title = "Desperate Prayer",
  desc = "Poco fa è passato di qui uno dei tuoi sacerdoti che ti cercava, $R. Mi ha chiesto di indirizzarti all'Hall of Mysteries, se ti avessi visto. Per lui era una cosa molto importante, ma al tuo posto non mi preoccuperei troppo. Sembrava di buon umore... come se avesse buone notizie. Però non tarderei troppo ad andarci.$B$BElune sia con te, $Gbuon:buona; $R.",
  obj = "Parla con High Priest Rohan a Ironforge.",
  reward = "Sono lieta che tu sia $Garrivato:arrivata;, $N. Dovremo parlare di molte cose, ma la più importante è il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominciamo subito ad affrontarne qualcuna.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5639] = {
  title = "Desperate Prayer",
  desc = "Hanno bisogno di te a Stormwind, $N. Laurena, la Gran Sacerdotessa del posto, dice che è ora di dimostrare che meriti il prossimo livello del tuo addestramento. Non metterci troppo ad arrivare: la trovi nella Cathedral of Light, al centro della città. Portale i miei saluti e falle vedere quanto sei $Gdegno:degna; di una simile vocazione. La Luce sia con te, $N.",
  obj = "Parla con High Priestess Laurena a Stormwind.",
  reward = "Sono lieta che tu sia $Garrivato:arrivata;, $N. Dovremo parlare di molte cose, ma la più importante è il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, ne affronteremo subito qualcuna.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5640] = {
  title = "Desperate Prayer",
  desc = "Sia lode a Elune, e alla tua Luce, $N.$B$BPiù o meno a questo punto del cammino, molti del nostro ordine apprendono abilità che riflettono la loro fede in Elune, e se la memoria non mi inganna, per il tuo ordine dovrebbe valere lo stesso.$B$BQuando avrai sbrigato i tuoi affari a Darnassus, ti consiglierei di cercare uno dei vostri Gran Sacerdoti per proseguire l'addestramento.",
  obj = "Parla con High Priest Rohan a Stormwind.",
  reward = "Sono contenta che tu sia $Garrivato:arrivata;, $N. Avremo molte cose di cui parlare, ma prima ancora viene il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che ogni servitore della Luce deve imparare. Se sei $Gpronto:pronta;, cominciamo subito ad affrontarne qualcuna.",
}
T[5641] = {
  title = "Chastise",
  reward = "Hai la stoffa di $Gun:una; grande $C, $N. Continua così!$B$BHai già dimostrato di essere $Gpronto:pronta; alla battaglia. Forse è ora di insegnarti qualcosina in più.",
  en_title = "A Lack of Fear",
  en_obj = "Speak to High Priest Rohan in Ironforge.",
}
T[5642] = {
  title = "Shadowguard",
  desc = "Sta succedendo qualcosa di importante a Orgrimmar, $N.$B$BDi solito i messaggeri che passano di qui a cercare sacerdoti troll non hanno nessuna fretta. Stavolta, invece, sembravano molto più di corsa. Non trattenerti troppo a Thunder Bluff: io tornerei alla Valley of Spirits il prima possibile.",
  obj = "Parla con Ur'kyo a Orgrimmar.",
  reward = "I tuoi riti arriveranno presto. Per ora ti insegno un incantesimo che ti sarà molto utile quando combatti contro i nemici.",
  en_title = "Shadowguard",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5643] = {
  title = "Shadowguard",
  desc = "Come molti dei nostri sacerdoti, anche tu devi affrontare i riti di passaggio della tua tribù. Spesso questi riti insegnano ai sacerdoti abilità speciali, vitali per sopravvivere. Sento che per te quel momento è giunto, proprio adesso, mentre parliamo. Devi tornare alla Valley of Spirits a Orgrimmar e parlare con Ur'kyo: quello che ti insegnerà potrebbe contare molto per il futuro.",
  obj = "Parla con Ur'kyo a Orgrimmar.",
  reward = "Presto verranno i tuoi riti. Per adesso ti insegno un incantesimo che ti tornerà molto utile quando ti batterai contro i nemici.",
  en_title = "Shadowguard",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5644] = {
  title = "Dark Sacrifice",
  desc = "Ah, che giornata meravigliosa per te, $N. Da quello che hai imparato vedo che è ora di rimandarti da Aelthalyste. Ci sono cose che solo lei può insegnarti, e comunque soltanto se ti dimostrerai $Gdegno:degna;.$B$BNon ti rovinerò la sorpresa, ma ricordo quando ero un giovane sacerdote e scoprivo il vero potere... il potere divino. Sì, quelli sì che erano bei tempi.$B$BTorna da Aelthalyste nell'Undercity, $N: ti starà aspettando nel War Quarter.",
  obj = "Parla con Aelthalyste nell'Undercity.",
  reward = "Bene, sei $Gtornato:tornata;, e appena in tempo. Abbiamo grandi cose di cui parlare, $N. Le tue capacità crescono, e dobbiamo essere certi che tu sia $Gpronto:pronta;.",
  en_title = "Devouring Plague",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5645] = {
  title = "Chastise",
  desc = "$N, il tuo High Priest Rohan vuole vederti a Ironforge. Sbrigati, $Gmio caro amico:mia cara amica;, la tua prossima prova è ormai vicina. Anche se mi piacerebbe assistere ai riti speciali della tua razza, il mio posto è qui. Ma che la Luce possa accompagnarti nei tuoi viaggi. Quando arriverai in città, Rohan dovrebbe essere ancora nel Mystic Ward. Ti aspetterà.",
  obj = "Parla con High Priest Rohan a Ironforge.",
  reward = "Hai fatto bene a venire, $N. La nostra è una razza fiera e forte, ed è ora che tu non solo impari a esserlo, ma anche a infondere negli altri lo stesso sentimento e la stessa fiducia. Sei $Gpronto:pronta;, $Gragazzo:ragazza;?",
  en_title = "A Lack of Fear",
  en_obj = "Speak to High Priest Rohan in Ironforge.",
}
T[5646] = {
  title = "Dark Sacrifice",
  desc = "Aelthalyste mostrare grande rispetto per la nostra gente: lei rimandarla da me per altro addestramento, e ora io faccio lo stesso con la sua tribù.$B$BTu torna a Undercity, $N. Nel War Quarter lei essere pronta a insegnarti di più sulla tua gente e sui suoi costumi. Vai, e non aspettare troppo.",
  obj = "Parla con Aelthalyste a Undercity.",
  reward = "Bene, sei $Gtornato:tornata;, e appena in tempo. Abbiamo cose importanti da dirci, $N. Le tue abilità crescono sempre di più, e dobbiamo essere certi che tu sia $Gpronto:pronta;.",
  en_title = "Devouring Plague",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5647] = {
  title = "Chastise",
  desc = "La tua razza è davvero forte, $N, e siamo fieri di potervi chiamare alleati. A ogni tramonto, tu e la tua gente vi avvicinate non solo alla scoperta delle vostre vere origini, ma anche alla certezza di essere sulla strada giusta in tante cose. Che senso di trionfo deve darti!$B$BDa Ironforge è arrivato da poco un messaggio: ti chiedeva di tornare lì e di parlare con High Priest Rohan, nel Mystic Ward. Io non lo farei aspettare. Che Elune guidi i tuoi viaggi.",
  obj = "Parla con High Priest Rohan a Ironforge.",
  reward = "Bene, sei $Gvenuto:venuta;, $N. La nostra razza è fiera e forte, ed è ora che tu impari non solo a esserlo tu $Gstesso:stessa;, ma anche a infondere negli altri lo stesso sentimento e la stessa fiducia. Sei $Gpronto:pronta;, $Gragazzo:ragazza;?",
  en_title = "A Lack of Fear",
  en_obj = "Speak to High Priest Rohan in Ironforge.",
}
T[5648] = {
  title = "Vesti della Spiritualità",
  desc = "Tu essere $Gpronto:pronta; per la tua prima prova, $N. A sud di Razor Hill, appena fuori città, una delle nostre grunt è rimasta ferita respingendo alcune delle vecchie truppe di Proudmoore. Lei non sta tanto bene, e le servirebbe molto l'aiuto di uno della nostra gente. Trovala — si chiama Kor'ja — curale le ferite e dalle la benedizione dei nostri antenati.$B$BSe tu fai questo, per me essere prova sufficiente che sei $Gpronto:pronta; per andare avanti sulla nostra via.",
  obj = "Trova Grunt Kor'ja e curale le ferite con Lesser Heal (Grado 2). Poi conferiscile Power Word: Fortitude e torna da Tai'jin a Razor Hill.",
  progress = "Quasi tutti trovano logico che le magie di guarigione essere potenti, ma pochi capiscono quanto. Tu puoi tenere in vita tanti che invece dovrebbero andare a incontrare i loro antenati. Questa magia di guarigione insieme al potere di Fortitude essere una combinazione di incantesimi molto forte. Ricordatelo. Questo essere utile a ogni tipo di gente: guerrieri, maghi e tutti quelli che stanno in mezzo.",
  reward = "Bene, allora Kor'ja vive e se ne va a difendere il nostro villaggio da quegli umani malvagi. Spesso mi viene voglia di ricordare i giorni di battaglia; quando il potere si mostrava in combattimento ed erano tante volte i saggi a distruggere quelli che contavano solo sulla loro forza.$B$BTu ti sei $Gcomportato:comportata; bene con me, $N. Adesso prendi questa veste. Forse ti aiuta, forse non ti importa, ma te la sei guadagnata e io sono fiera di chiamarti $Gfratello:sorella;.",
  en_title = "Garments of Spirituality",
  en_obj = "Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill.",
}
T[5649] = {
  title = "In Favore della Spiritualità",
  desc = "Sì, mon. La nostra gente si è unita all'Orda perché loro essere un bene per noi. Loro leali, e ci insegnano tante cose, tipo l'onore. Ma le vecchie usanze sono dure a morire. Gli orchi magari non approvano tutte le nostre tradizioni, ma questo non volere dire che noi non possiamo continuare a praticarne qualcuna in segreto.$B$BTu lo sai, ed è per questo che ti mando da Tai'jin a Razor Hill. Lei ti racconta di più della nostra storia. Ti insegna le usanze della nostra tribù. Va' da lei quando essere $Gpronto:pronta;.",
  obj = "Parla con Tai'jin in Durotar.",
  reward = "Ahh... così finalmente sei $Gvenuto:venuta; da Tai'jin. Questo essere buono.$B$BTu già sai che noi non siamo la stessa tribù che un tempo si è unita all'Orda. Adesso noi essere molto più forti. Più forti perché ci adattiamo — l'Orda ci ha insegnato almeno questo. Noi non sconfiggiamo più i nemici per prendere la loro forza; adesso prima prendiamo forza, e poi sconfiggiamo i nemici.$B$BLa differenza essere sottile, ma tu capirai. Vedrai. La tribù conta che tu impari queste cose.",
  en_title = "In Favor of Spirituality",
  en_obj = "Speak to Tai'jin in Durotar.",
}
T[5650] = {
  title = "Vesti dell'Oscurità",
  desc = "Il nostro potere viene dall'oscurità e dall'ombra, $N, ma il tuo ruolo non si limita a questo. Hai constatato che conoscere le arti curative ha il suo valore. È saggio. Ma prima di comprendere il buio, devi conoscere anche la luce. Per questo ti metterò alla prova.$B$BA nord del cimitero c'è un Deathguard ferito — Deathguard Kel. Da tempo ci protegge dagli gnoll e ha bisogno di cure. Ma devi anche rafforzargli il corpo prima che possa tornare in servizio. Usa gli incantesimi per fare entrambe le cose, poi torna da me.",
  obj = "Trova Deathguard Kel e curagli le ferite con Lesser Heal (Rank 2). Poi lanciagli Power Word: Fortitude e torna da Dark Cleric Beryl a Brill.",
  progress = "I nostri poteri ci rendono ideali in moltissime situazioni, $N. Scoprirai però che, comunque vada, i talenti più ricercati a nostra disposizione resteranno sempre due: risanare le ferite e permettere ai compagni di sopportare più danni. Non per questo, però, devi rinunciare a percorrere altre strade come $C — puoi renderti utile in molti modi. Ma... se desideri davvero distruggere i nemici con l'energia magica, forse l'arcano fa più al caso tuo.",
  reward = "Hai superato la mia prova con facilità. Bene.$B$BPresto sarai $Gpronto:pronta; ad assumerti maggiori responsabilità, e da lì il cammino ti porterà verso poteri più oscuri — poteri che $Gnessun:nessuna; $C di un'altra razza possiede.$B$BPrendi questa veste, simbolo della tua posizione. Te la sei guadagnata. Se non desideri indossarla, così sia: puoi farne ciò che vuoi. Io e quelli come noi ti riconosceremo sempre il merito di ciò che hai ottenuto nei nostri ranghi.",
  en_title = "Garments of Darkness",
  en_obj = "Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill.",
}
T[5651] = {
  title = "In Favore dell'Oscurità",
  desc = "Sono molte le lezioni che i Forsaken hanno appreso per esperienza — cose che alcune razze riescono appena a comprendere. E anche se il nostro cammino si snoda nell'oscurità, scoprirai che moltissime cose dipendono tanto dalla luce quanto dal buio. L'addestramento ti permetterà di usarli entrambi... con discrezione. Ma dammi retta: non dimenticare mai che siamo stati forgiati nella corruzione e lasciati a marcire come nient'altro che carcasse. L'Oscurità è la nostra casa.$B$BQuando sarai $Gpronto:pronta; a proseguire gli studi, cerca Dark Cleric Beryl a Brill.",
  obj = "Parla con Dark Cleric Beryl nelle Tirisfal Glades.",
  reward = "Finalmente sei $Garrivato:arrivata;. La fede da sola non ti basterà per superare le prove che ti attendono, giovane. Anche dell'ambizione e un po' di impazienza sarebbero d'aiuto.",
  en_title = "In Favor of Darkness",
  en_obj = "Speak to Dark Cleric Beryl in Tirisfal Glades.",
}
T[5652] = {
  title = "Hex of Weakness",
  reward = "Questa lezione, giovane, faresti bene a seguirla con attenzione: in battaglia l'Hex of Weakness ti sarà di grande aiuto. Più avanti ti metterò alla prova, per farti crescere e per farti dimostrare il tuo valore alla tribù.",
  en_title = "Hex of Weakness",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5654] = {
  title = "Hex of Weakness",
  desc = "Essere tempo che tu incontri Ur'kyo, $N. Lui stare nella Valley of Spirits, nella città degli orchi: va' là e parla con lui. È tempo che tu impari di più sulle antiche usanze della nostra gente. Essere tempo che tu venga $Gaccolto:accolta; nel cerchio e $Gfatto:fatta; $Gun vero sacerdote:una vera sacerdotessa; della nostra tribù.",
  obj = "Parla con Ur'kyo a Orgrimmar.",
  reward = "Ah, bene, ora tu essere qui. Possiamo cominciare ad addestrarti nelle antiche usanze.",
  en_title = "Hex of Weakness",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5655] = {
  title = "Hex of Weakness",
  desc = "Io mandato qui per assicurare che tu non vagare troppo lontano da casa, $N. Loro mandare me per assicurare che tu tornare a casa, perché Ur'kyo, più grande dei nostri sacerdoti, volere parlare con te. Tu andare là. Tu andare nella Valley of Spirits nella città degli orchi e tu parlare con Ur'kyo. Lui aspettare te adesso.",
  obj = "Parla con Ur'kyo a Orgrimmar.",
  reward = "Faresti bene a prestare attenzione a questa lezione, giovane. Hex of Weakness ti sarà di grande aiuto in battaglia. Più avanti ti sottoporrò a delle prove, perché tu possa crescere e dimostrare il tuo valore alla tribù.",
  en_title = "Hex of Weakness",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5656] = {
  title = "Hex of Weakness",
  desc = "Vedere sacerdoti di ogni cultura in giro per il mondo mi scalda sempre il cuore immortale. E sapere che esiste un potere che non è arcano, e che è alla nostra portata. Per questo è un onore per me rimandarti a casa, $N.$B$BUr'kyo, il vostro grande sacerdote a Orgrimmar, ha chiesto di vederti. Lo troverai nella Valley of Spirits.",
  obj = "Parla con Ur'kyo a Orgrimmar.",
  reward = "Questa lezione faresti bene a seguirla con attenzione, giovane. In battaglia l'Hex of Weakness ti sarà di grande aiuto. Più avanti avrò delle prove per te, per farti crescere e per dimostrare alla tribù quanto vali.",
  en_title = "Hex of Weakness",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5657] = {
  title = "Hex of Weakness",
  desc = "Casa. Torna a casa, giovane $R.$B$BUr'kyo, il tuo capo spirituale, ti prega di tornare da lui per parlargli del sentiero che stai percorrendo.$B$BVa' alla Valley of Spirits, nella grande città dell'Orda, Orgrimmar: lì lo troverai.",
  obj = "Parla con Ur'kyo a Orgrimmar.",
  reward = "Questa lezione, giovane, faresti bene ad ascoltarla con attenzione: in battaglia l'Hex of Weakness ti sarà di grande aiuto. Più avanti avrò delle prove per te, che ti faranno crescere e ti permetteranno di dimostrare alla tribù quanto vali.",
  en_title = "Hex of Weakness",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5658] = {
  title = "Touch of Weakness",
  reward = "Ah, giovane $C, sono lieta che tu sia $Gtornato:tornata; qui. Vorrei insegnarti una lezione, e faresti bene a non dimenticarla. Sei $Gpronto:pronta;?",
  en_title = "Touch of Weakness",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5659] = {
  title = "Touch of Weakness",
  desc = "Il tuo posto non è qui, $N. Faresti bene ad andare al più presto nel War Quarter di Undercity: Aelthalyste ha chiesto a tutti i suoi sacerdoti e a tutte le sue sacerdotesse di raggiungerla lì non appena sono pronti. È ora che imparino a conoscere meglio il loro potere e a dominarlo.$B$BNon tollererà ritardi né scuse: meglio che ti metta in cammino.",
  obj = "Parla con Aelthalyste a Undercity.",
  reward = "Ah, bene, $Gne è arrivato un altro:ne è arrivata un'altra;. Per me il tempo non conterà, ma per te è prezioso. Hai molto da imparare, e io desidero insegnarti molto: devi solo dimostrare quanto vali. Fallo, e sarai $Gricompensato:ricompensata; generosamente.",
}
T[5660] = {
  title = "Touch of Weakness",
  desc = "Tu essere $Glontano:lontana; da casa, $C. Nella tua città sotto la terra avere bisogno di te: la tua maestra, quella che tu chiamare Aelthalyste, avere bisogno di te laggiù. Come per la mia tribù, esserci cose che tu dovere imparare solo da lei. Tu non stare qui troppo a lungo. Tu dovere andare al War Quarter, veloce quanto uno zeppelin può portarti.",
  obj = "Parla con Aelthalyste nell'Undercity.",
  reward = "Ah, bene, ne è $Garrivato:arrivata; $Gun altro:un'altra;. Per me il tempo non conterà, ma per te è essenziale. Hai molto da imparare, e molto desidero insegnarti. Devi solo dimostrare quanto vali: fallo, e sarai $Gricompensato:ricompensata; generosamente.",
  en_title = "Touch of Weakness",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5661] = {
  title = "Touch of Weakness",
  desc = "Tu essere $Glontano:lontana; da casa qui a Bloodhoof Village, $N. Io essere mandato qui per trovare sacerdoti della mia tribù da rimandare indietro a parlare con nostri capi, ma questo non volere dire che io non potere aiutare anche te.$B$BIo sentire dire che spirito di tua somma sacerdotessa volere tutti i Forsaken da lei — ci sono cose che tu dovere imparare.$B$BTu andare a incontrare Aelthalyste nel War Quarter in quella città tua.",
  obj = "Parla con Aelthalyste a Undercity.",
  reward = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Per me il tempo forse non conta, ma per te è essenziale. Hai molto da imparare, e c'è molto che voglio insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.",
  en_title = "Touch of Weakness",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5662] = {
  title = "Touch of Weakness",
  desc = "I miei rispetti a te e alla tua gente, $N. Di solito insegno soltanto a chi è della mia tribù. Chi ti insegna è Aelthalyste, nella città che un tempo si chiamava Lordaeron.$B$BSe vuoi imparare le abilità che ti distinguono dalle altre fedi, dovresti tornare da lei.$B$BVai al War Quarter di Undercity: lì troverai la tua maestra.",
  obj = "Parla con Aelthalyste a Undercity.",
  reward = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Per me il tempo forse non conta, ma per te è essenziale. Devi imparare molte cose, e io desidero insegnartele. Devi solo dimostrare quanto vali: fallo, e sarai $Gricompensato:ricompensata; generosamente.",
  en_title = "Touch of Weakness",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5663] = {
  title = "Touch of Weakness",
  desc = "Aelthalyste ha mandato un messaggio a tutti i suoi sacerdoti: dobbiamo indirizzare i più giovani del nostro ordine all'Undercity, perché proseguano l'addestramento. Se davvero ti consideri $Guno:una; dei nostri fedeli, dovresti tornarci anche tu.$B$BAelthalyste la troverai nel War Quarter, giù nel profondo dell'Undercity.",
  obj = "Parla con Aelthalyste nell'Undercity.",
  reward = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Per me il tempo non conterà, ma per te è prezioso. Hai molto da imparare, e io desidero insegnarti molto: devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.",
  en_title = "Touch of Weakness",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5672] = {
  title = "Grazia di Elune",
  reward = "Ti sei $Gdedicato:dedicata; a Elune e al nostro popolo, e così hai raggiunto uno stato a cui non tutti noi possiamo arrivare. La tradizione vuole che, per la tua devozione, ora ti vengano insegnate abilità ancora più grandi. Accetti?",
  en_title = "Elune's Grace",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5673] = {
  title = "La Grazia di Elune",
  desc = "Lo sai che puoi rivolgerti ai nostri istruttori quando vuoi, $N, ma certe cose non possiamo insegnartele noi. Fra queste ci sono gli insegnamenti della tua dea, Elune. Concede abilità speciali ai suoi fedeli e, se non sbaglio, per te è ora di andare a casa al tuo Tempio della Luna per essere $Gmesso:messa; alla prova.$B$BTornaci quando puoi e parla con Priestess Alathea.",
  obj = "Parla con Priestess Alathea a Darnassus.",
  reward = "Che Elune ti benedica per essere $Gtornato:tornata; da noi così in fretta. Questo è un momento importante del tuo addestramento, e tutto il nostro ordine lo prende molto sul serio. Quando ti sarai $Griposato:riposata; dal viaggio, fammelo sapere, per favore. Allora potremo parlare di come proseguire e di dove ti condurrà il tuo cammino.",
  en_title = "Elune's Grace",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5674] = {
  title = "La Grazia di Elune",
  desc = "È arrivato un giorno meraviglioso, $N. Hai raggiunto l'età in cui $Gi nostri sacerdoti vengono addestrati:le nostre sacerdotesse vengono addestrate; in abilità che conoscono solo gli Elfi della notte. Ma non spetta a me addestrarti. Appena avrai concluso i tuoi affari qui, devi tornare al Tempio della Luna e parlare con Priestess Alathea. Prima ti metterà alla prova, per assicurarsi che tu sia $Gpronto:pronta;, e solo allora ti insegnerà la Grazia di Elune.",
  obj = "Parla con Priestess Alathea a Darnassus.",
  reward = "Che Elune ti benedica per essere $Gtornato:tornata; da noi così in fretta. Questo è un momento importante del tuo addestramento, e tutto il nostro ordine lo prende molto sul serio. Quando ti sarai $Griposato:riposata; dal viaggio, ti prego, fammelo sapere. Allora potremo parlare di come proseguirà la tua formazione e della prossima tappa del tuo cammino.",
  en_title = "Elune's Grace",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5675] = {
  title = "La Grazia di Elune",
  desc = "Il tempo stringe, $Gragazzo:ragazza;. È ora di tornare a casa, a Darnassus: Priestess Alathea ha mandato a dire che devi andarci per l'addestramento. Pare che ti ritengano $gdegno:degna; di essere $Gmesso:messa; alla prova proprio come chi serve la Luce. Faresti bene a partire appena puoi. Nel messaggio Alathea diceva che ti aspetterà nel Tempio della Luna. Buona fortuna.",
  obj = "Parla con Priestess Alathea a Darnassus.",
  reward = "Che Elune ti benedica per essere $Gtornato:tornata; da noi così in fretta. È un momento importante del tuo addestramento, e tutto il nostro ordine lo prende molto sul serio. Quando ti sarai $Griposato:riposata; dal viaggio, fammelo sapere, ti prego: allora potremo parlare di come proseguirà l'addestramento e di dove ti porterà il cammino.",
  en_title = "Elune's Grace",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5676] = {
  title = "Arcane Feedback",
  reward = "Abbiamo dovuto imparare alcune magie per proteggerci da quello che di solito si chiama il nostro più grande nemico: l'arcano.$B$BVorrei insegnarti un incantesimo che ti aiuti a difendere te $Gstesso:stessa; e i tuoi compagni da chi brandisce un potere simile.",
  en_title = "Arcane Feedback",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5677] = {
  title = "Arcane Feedback",
  desc = "Per quanto mi piacerebbe mostrarti i nostri insegnamenti speciali della Luce, non tocca a noi. Il tuo posto è a Stormwind, con la tua gente, $N... per ora. Credimi, non lo dico per offenderti. Quando sarai di nuovo da High Priestess Laurena nella Cathedral of Light capirai cosa intendo — è arrivato il momento che la tua razza ti prepari al futuro; di separarti dagli altri che seguono un cammino simile.",
  obj = "Parla con High Priestess Laurena a Stormwind.",
  reward = "Ah, arrivi proprio al momento giusto, $N. Cominciavo a chiedermi se i miei messaggeri ce l'avessero fatta tutti. Sono lieta di vedere che è così: altrimenti scommetto che saresti ancora in giro per il mondo a saperne di più su tutte le minacce che incombono sul nostro popolo.$B$BSei $Gpronto:pronta;? $GPronto:Pronta; per altro addestramento, intendo. Il tuo potere cresce più in fretta, e sento che sei $Gpronto:pronta; a imparare di più sulla nostra fede.",
  en_title = "Arcane Feedback",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5678] = {
  title = "Arcane Feedback",
  desc = "È ora che tu torni a Stormwind, giovane: i tuoi superiori ti hanno richiamato lì per proseguire l'addestramento. La cosa mi turba un po', ma la tua razza e la mia sono alleate, e io non tradirei questo legame.$B$BNon voglio essere così reticente con te — ma la mia diffidenza verso le magie arcane, che siano di ispirazione divina o no, è ancora forte.$B$BCapirai di cosa parlo quando sarai $Gtornato:tornata; alla tua Cathedral of Light. Appena arrivi, va' a parlare con High Priestess Laurena.",
  obj = "Parla con High Priestess Laurena a Stormwind.",
  reward = "Ah, arrivi proprio al momento giusto, $N. Cominciavo a chiedermi se tutti i miei messaggeri ce l'avessero fatta. Sono contenta di vedere che è così: altrimenti scommetterei che saresti ancora in giro per il mondo a scoprire di più su tutti i pericoli che minacciano il nostro popolo.$B$BSei $Gpronto:pronta;? $GPronto:Pronta; a riprendere l'addestramento, intendo. Il tuo potere sta crescendo più in fretta, e sento che è il momento di farti conoscere meglio la nostra fede.",
}
T[5679] = {
  title = "Dark Sacrifice",
  reward = "Se ti senti $Gpronto:pronta;, $N, ti insegnerei la Devouring Plague: è un incantesimo di notevole potere e ti aiuterà nelle battaglie che ti aspettano. Esercitati — più avanti ci sarà un esame.",
  en_title = "Devouring Plague",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5680] = {
  title = "Shadowguard",
  reward = "I tuoi riti arriveranno presto. Intanto ti insegno un incantesimo che ti sarà molto utile quando combatterai i nemici.",
  en_title = "Shadowguard",
  en_obj = "Speak to Ur'kyo in Ogrimmar.",
}
T[5721] = {
  title = "La Battaglia di Darrowshire",
  desc = "Adesso, $N, prenderai parte alla battaglia di Darrowshire e salverai Joseph Redpath.$B$BMetti questo relic bundle nella piazza di Darrowshire e gli spiriti del villaggio si leveranno. Unisciti a loro nella battaglia e fa' in modo che succedano due cose: Davil deve restare vivo finché Horgus non muore, e Redpath deve sopravvivere fino a quando non verrà corrotto, e poi sconfitto.$B$BUna volta sconfitto Redpath corrotto, il suo spirito sarà salvo: parlagli, e poi torna da sua figlia Pamela.",
  obj = "Metti il Relic Bundle nella piazza di Darrowshire.$B$BImpedisci la morte di Davil Lightfire fino alla morte di Horgus.$B$BImpedisci la morte di Captain Redpath finché non appare Redpath the Corrupted.$B$BSconfiggi Redpath the Corrupted.$B$BParla con lo spirito di Joseph Redpath quando appare nella piazza, poi parla con Pamela a casa sua.",
  progress = "Là fuori mi sa che ho sentito dei fantasmi. Mi sussurrano cose che fanno paura...",
  reward = "La battaglia è finita! Ho sentito il mio papà che mi sussurrava. Ha fatto scappare tutti i fantasmi e dice che sta tornando a casa! Sono tanto felice!$B$BMi ha detto anche di accoglierti, se venivi a casa nostra, e così ho fatto il tè!$B$BSpero che ti piaccia con tanto zucchero!",
}
T[5722] = {
  title = "Alla Ricerca della Sacca Perduta",
  desc = "Nel Ragefire Chasm a Magatha non interessano soltanto i troggs. Ha saputo che uno dei suoi servitori, un certo Maur Grimtotem, ha trovato qualcosa di strano mentre si trovava nella Chasm, ma non ne è mai uscito per mostrarle cos'era. Vorrebbe che qualcuno ritrovasse il corpo di Maur — se c'è ancora — e qualunque traccia di quello che ha scoperto mentre cercava di parlare con i troggs.$B$BSe porterai a Magatha qualcosa di interessante, sono sicuro che ti ricompenserà con grande generosità.$B$BTe lo ripeto: cerca la Chasm nelle zone più buie di Orgrimmar.",
  obj = "Cerca il cadavere di Maur Grimtotem in Ragefire Chasm e frugalo in cerca di oggetti interessanti.",
  reward = "A quanto sembra, il corpo è stato pestato duramente, a colpi di clava o a pugni, eppure i vestiti e l'equipaggiamento paiono quasi tutti al loro posto. Si direbbe che ai troggs i beni materiali non importino granché.$B$BCominci a frugare il corpo, alla ricerca di qualcosa di interessante che possa essere d'aiuto a Magatha.",
  en_title = "Searching for the Lost Satchel",
  en_obj = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.",
}
T[5723] = {
  title = "Mettere alla Prova la Forza di un Nemico",
  desc = "Sotto la città di Orgrimmar, dalle profondità sotto i tunnel pieni di lava, delle creature robuste chiamate troggs hanno cominciato a risalire in superficie. Magatha, nella sua infinita benevolenza, ha cercato di fare pace con loro, ma quelle creature si sono rivoltate contro i suoi diplomatici e li hanno uccisi. Lei non permetterà che il popolo tauren venga trattato in questo modo, e ora le considera una minaccia per tutta l'Orda.$B$BTi chiede di mettere fine a questa minaccia trogg prima che travolga l'Orda da sotto. Trova il Ragefire Chasm e distruggili tutti.",
  obj = "Cerca il Ragefire Chasm a Orgrimmar, poi uccidi 8 Ragefire Troggs e 8 Ragefire Shaman prima di tornare da Rahauro a Thunder Bluff.",
  progress = "A che punto sei con la ricerca della Chasm? E con i troggs?$B$BNon possiamo lasciare che la minaccia continui — se va avanti, non farà altro che ferire i nostri fratelli orchi.",
  reward = "Sono lieto che tu abbia preso sul serio il compito di Magatha. Grazie, $N. Ora che sono rimasti così in pochi, sono sicuro che i troggs faranno più fatica a risalire in superficie.$B$BForse in futuro potremo trovare il tempo di capire da dove vengono queste creature e cosa vogliono davvero.",
  en_title = "Testing an Enemy's Strength",
  en_obj = "Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.",
}
T[5724] = {
  title = "Riportare la Sacca Perduta",
  desc = "Sotto il corpo del tauren trovi una sacca: la stringe ancora forte tra le braccia, come se avesse cercato di proteggerla mentre i troggs lo attaccavano.$B$BGliela sfili dalla presa ferrea, la riponi fra le tue cose e ti prepari a lasciare le gallerie per tornare da Rahauro a Thunder Bluff.",
  obj = "Porta la Grimtotem Satchel a Rahauro a Thunder Bluff.",
  progress = "Allora, $N, sei $Griuscito:riuscita; a trovare qualcosa? Ci servirebbe qualunque indizio per capire perché uno del suo clan sia dovuto morire inutilmente.",
  reward = "Ottimo, $N, grazie.$B$BMagatha mi ha detto di darti questo, se avessi ritrovato il suo compagno di clan. Prendilo, ti prego, come ringraziamento.",
  en_title = "Returning the Lost Satchel",
  en_obj = "Take the Grimtotem Satchel to Rahauro in Thunder Bluff.",
}
T[5725] = {
  title = "Il Potere di Distruggere...",
  desc = "Come forse ben saprai, molti membri della Legione elargiscono doni ai propri seguaci. Secondo la Dama Oscura, alcuni di questi doni starebbero meglio nelle sue mani che in quelle di chi ha una visione... più limitata.$B$BNe è un esempio lampante una setta dello Shadow Council nota come Searing Blade, che si nasconde nelle caverne sotto Orgrimmar. La Dama mi dice che alcuni membri della Searing Blade sono entrati in possesso di due potenti libri di incantesimi — e lei vorrebbe \"prenderli in prestito\". Sarai tu a procurarglieli.",
  obj = "Porta i libri Spells of Shadow e Incantations from the Nether a Varimathras a Undercity.",
  progress = "Ho altri cento compiti di cui occuparmi, $C. Ce li hai, i libri?",
  reward = "Bene, $C. Hai servito degnamente la Dama Oscura. La tua costante perseveranza e la tua ambizione saranno di grande utilità ai suoi sudditi. Torna da me, più avanti: forse avrò altri compiti per te, che aiuteranno la Dama Oscura nei suoi tentativi di sopraffare The Lich King e di liberare del tutto lo Scourge.",
  en_title = "The Power to Destroy...",
  en_obj = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.",
}
T[5728] = {
  title = "Nemici Nascosti",
  desc = "Hmm, i capi della Searing Blade... è questo che mi preoccupa di più. Se sono loro a contare per Neeru, è loro che dobbiamo colpire per primi. Quel satiro... Bazzalan, e l'altro nominato da Neeru — cos'era, uno stregone? — vanno uccisi.$B$BTorna alla Cleft of Shadow ed entra nel Ragefire Chasm, $N. Trova i due capi della Searing Blade e uccidili, ma stai $Gattento:attenta; che Neeru non scopra che sei $Gstato:stata; tu: per lui devi restare $Guno dei suoi fratelli:una delle sue sorelle; d'armi.",
  obj = "Uccidi Bazzalan e Jergosh the Invoker, poi torna da Thrall a Orgrimmar.",
  progress = "Li hai già trovati, $N? Parlo dei capi della Searing Blade.$B$BSapevo che lo Shadow Council voleva togliermi Orgrimmar e l'Orda intera, ma non avevo capito con che rapidità fossero riusciti a infiltrarsi in città. Quante braccia ha, questa bestia... possiamo tagliarle fino allo sfinimento, ma resteremo sempre al punto di partenza. Dovrò dire alle mie spie di raddoppiare gli sforzi.",
  reward = "Sono lieto che tu sia $Gtornato:tornata;, $N. Alcuni dei miei fedeli mi hanno avvisato subito che, ora che i capi sono stati uccisi, nelle caverne sotto Orgrimmar regna il caos. Ho perfino sentito dire che Neeru era più che agitato: a quanto pare abbiamo ammaccato la sua armatura. Non posso dire che mi dispiaccia... per quanto piccola sia la vittoria.",
  en_title = "Hidden Enemies",
  en_obj = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.",
}
T[5741] = {
  title = "Sceptre of Light",
  desc = "Si dice che la Burning Blade, nella Thunder Axe Fortress a est, abbia ottenuto dai Naga lo Sceptre of Light. Secondo la leggenda, lo scettro può far sprofondare intere città sotto i grandi mari. La Burning Blade non deve avere in mano un potere simile.$B$BPer questo lo scettro devi recuperarlo tu $Gstesso:stessa;! Ce l'ha un veggente della Burning Blade, che lo studia in cima a una delle torri di guardia di Thunder Axe.",
  obj = "Prendi lo Sceptre of Light e riportalo ad Azore Aldamort presso la torre di Ethel Rethor.",
  progress = "Hai lo Sceptre of Light?",
  reward = "L'inafferrabile Sceptre of Light! Con questo recupero hai liberato il mondo da una grave minaccia. Ben fatto, $C, ben fatto.",
  en_title = "Sceptre of Light",
  en_obj = "Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor.$B",
}
T[5742] = {
  title = "Redenzione",
  desc = "Hai lavorato sodo, $Gamico:amica;. Riposa le ossa stanche e lascia che mi presenti come si deve.",
  obj = "Ascolta ciò che Tirion Fordring ha da dire.",
  progress = "Ti prego, $Gamico:amica;; siediti e ascolta la mia storia.",
  reward = "La redenzione dei Fordring sarà un'impresa difficile. Sei $Gpronto:pronta;?",
}
T[5761] = {
  title = "Abbattere la Bestia",
  desc = "Il nostro grande Capoguerra mi ha affidato prima di tutto un compito: stanare le creature che infestano di influssi demoniaci la grande città del nostro signore. La Burning Blade è una minaccia, ma non è la sola; la Searing Blade, per esempio, si è stabilita nel Ragefire Chasm e cerca in segreto di corrompere membri innocenti dell'Orda.$B$BPer fermarli dobbiamo uccidere il loro capo — una Felguard di nome Taragaman the Hungerer.$B$BUccidilo: il suo cuore placherà Thrall, ne sono certo.",
  obj = "Entra nel Ragefire Chasm e uccidi Taragaman the Hungerer, poi porta il suo cuore a Neeru Fireblade a Orgrimmar.",
  progress = "Hai ucciso la bestia? Dev'essere lui a guidare la Searing Blade nel Ragefire Chasm.",
  reward = "Ah! Ce l'hai fatta! Thrall ne sarà molto contento.$B$BQuesto cuore lo farò trattare come si deve.$B$BTu, però, per ora pensa a festeggiare la vittoria: a informare Thrall del tuo successo ci penso io.$B$BGrazie dell'aiuto, $C.",
  en_title = "Slaying the Beast",
  en_obj = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.",
}
T[5762] = {
  title = "Hemet Nesingwary",
  desc = "Ho un pacco per un mio vecchio cliente, un nano che si chiama Hemet Nesingwary. Ci ha messo settimane ad arrivare, e Hemet ormai è partito da un pezzo: ha detto che andava a Stranglethorn a cacciare le bestie del posto, ma mi ha lasciato del denaro perché gli spedissi la merce appena possibile.$B$BHemet è un nano ricco, e con i ricchi conviene restare in buoni rapporti, no? Allora... ti va di consegnare il pacco al posto mio?$B$BMi hanno detto che Hemet ha un accampamento a Stranglethorn, a nord di Grom'gol.",
  obj = "Porta la Kravel's Crate a Hemet Nesingwary a Stranglethorn.",
  progress = "Quella sul colletto è polvere del deserto?$B$BUhm... se il naso non m'inganna, direi che non è polvere, ma sale del deserto! Sei $Gstato:stata; a Shimmering Flats, eh?",
  reward = "Ottimo, il mio pacco da parte di Koalbeard! Grazie, $N. In questa cassa ci sono munizioni di calibro speciale, e qui nella giungla ci faranno molto comodo!$B$BEcco la tua paga. E dimmi, come se la passa di questi tempi quel vecchio brontolone di Kravel? Sempre a combinarne qualcuna, scommetto...",
  en_title = "Hemet Nesingwary",
  en_obj = "Take Kravel's Crate to Hemet Nesingwary in Stranglethorn.",
}
T[5763] = {
  title = "Caccia a Stranglethorn",
  desc = "Molto tempo fa è arrivato in questa terra un nano di nome Hemet, in cerca di grandi bestie da cacciare. Col fucile aveva un'abilità straordinaria, e per molti giorni abbiamo cacciato insieme. Ci siamo scordati persino dell'inimicizia tra i nostri popoli.$B$BQuando è partito da Desolace per Stranglethorn, ho giurato che un giorno lo avrei riaccolto qui, per tornare a cacciare insieme. Ora quel momento è giunto.$B$BPorta questo kodo horn a Hemet: saprà che viene da me. Lo troverai a Stranglethorn, a nord dell'accampamento Grom'gol Base.",
  obj = "Porta il Roon's Kodo Horn a Hemet Nesingwary a Stranglethorn.",
  progress = "Siediti, $C. Fra poco tornerai a lanciarti nella giungla.",
  reward = "Ah, questo corno è di un Tauren, Roon Wildmane. Io e lui ci siamo divertiti a dare la caccia alle bestie di Desolace. E così Roon mi invita a tornare, eh?$B$BPer ora siamo nella giungla fino al collo, ma grazie, $N. Magari la prossima spedizione mi riporterà a Desolace, la terra dei centauri.",
  en_title = "Hunting in Stranglethorn",
  en_obj = "Bring Roon's Kodo Horn to Hemet Nesingwary in Stranglethorn.",
}
T[5781] = {
  title = "Ricordi Dimenticati",
  desc = "Per aiutare Taelan a ritrovare ciò che ha perduto, devi raccogliere alcuni oggetti del suo passato.$B$BIl primo è un giocattolo che gli ho regalato quando ha compiuto 7 anni. Ci teneva più di ogni altra cosa: un martello da guerra in miniatura; la copia esatta del mio.$B$BQuando mi hanno bandito per tradimento, sua madre gli ha detto che ero morto. Lo hanno portato davanti alla mia falsa tomba nell'Undercroft, e lì ha sepolto il martello insieme al mio ricordo — per sempre.$B$BDevi andare nell'Undercroft e riprendere il martello di Taelan.",
  obj = "Recati a Undercroft — nella parte più a sud di Eastern Plaguelands — e recupera il Taelan's Hammer. Torna da Tirion Fordring una volta completato l'obiettivo.",
  progress = "Deve essere redento.",
  reward = "<Tirion sbatte le palpebre per ricacciare indietro le lacrime.>$B$BEra destino che ci incontrassimo, $N. Per me la tua gentilezza è stata una benedizione.",
}
T[5801] = {
  title = "Forgiata a Fire Plume",
  desc = "Per forgiare il fusto della chiave ti servono due lingotti di torio e una fonte di calore molto potente. Per il torio dovrai arrangiarti, ma col calore posso darti una mano.$B$BNell'Un'Goro Crater, a ovest di qui, c'è Fire Plume Ridge — un vulcano che ribolle. Il lago di lava sulla cima scotta abbastanza da fondere insieme torio e ossa. Lo stampo che hai comprato col tuo oro basta immergerlo nel lago; al resto penserà la lava.$B$BDa me è tutto. Per finire la chiave dovrai tornare a parlare con Arbington.",
  obj = "Porta lo Skeleton Key Mold e 2 Thorium Bars in cima a Fire Plume Ridge nell'Un'Goro Crater. Usa lo Skeleton Key Mold vicino al lago di lava per forgiare l'Unfinished Skeleton Key.$B$BPorta l'Unfinished Skeleton Key ad Alchemist Arbington a Chillwind Point, Western Plaguelands.",
  progress = "Hai finito il fusto della chiave universale? Mi dispiace che il costo dello stampo sia ricaduto tutto su di te, ma per contrastare lo Scourge dobbiamo fare tutti la nostra parte. Consegnami la chiave incompiuta e sarai $Gpronto:pronta; per l'ultimo elemento che manca a completarla.$B$BNon sarà per niente facile, ma ora il lavoro che hai fatto finora per preparare un assalto ad Andorhal comincerà a dare i suoi frutti. Vedrai.",
  reward = "Ci è costata parecchio, questa skeleton key, eh, $N? Eppure è ancora incompiuta; è arrivato il momento di concentrarci sulla nostra creazione. Per questo dovrai affrontare il nemico finale, quello contro cui ci prepariamo da tempo ad Andorhal... l'essere malvagio che tira le fila dentro le mura della città in rovina.$B$BParlo di Araj the Summoner — un lich, e uno degli esseri più potenti che lo Scourge abbia al suo servizio.",
}
T[5802] = {
  title = "Forgiata a Fire Plume",
  desc = "Per forgiare il gambo della chiave ti servono due barre di torio e una fonte di calore fortissima. Per il torio dovrai arrangiarti, ma con il calore posso darti una mano.$B$BA ovest di qui, nell'Un'Goro Crater, c'è il Fire Plume Ridge — un vulcano ribollente. Il lago di lava in cima è abbastanza caldo da fondere insieme torio e osso. Con il tuo oro hai comprato uno stampo che basta immergere nel lago lassù; al resto ci penserà la lava.$B$BDa parte mia è tutto. Per completare la chiave dovrai parlare di nuovo con Dithers.",
  obj = "Porta lo Skeleton Key Mold e 2 Thorium Bars in cima a Fire Plume Ridge, a Un'Goro Crater. Usa lo Skeleton Key Mold vicino al lago di lava per forgiare l'Unfinished Skeleton Key.$B$BPorta l'Unfinished Skeleton Key ad Apothecary Dithers al Bulwark, Western Plaguelands.",
  progress = "Hai finito il gambo della chiave? Mi dispiace davvero che il costo dello stampo sia ricaduto interamente su di te, ma contro lo Scourge ognuno deve fare la propria parte. Quando mi avrai consegnato la chiave incompiuta, sarai $Gpronto:pronta; per l'ultimo elemento necessario a completarla.$B$BNon sarà per niente facile, ma il lavoro che hai svolto finora per preparare l'assalto ad Andorhal comincerà a dare i suoi frutti. Vedrai.",
  reward = "Ci è costata parecchio, questa skeleton key, non è vero, $N? Eppure è ancora incompiuta; è giunto il momento di dare forza alla nostra creazione. Per questo dovrai vedertela con il nemico supremo che ci siamo preparati ad affrontare ad Andorhal... l'essere che comanda tra le mura della città in rovina.$B$BParlo di Araj the Summoner — un lich, e uno dei più potenti che lo Scourge annoveri tra i suoi.",
}
T[5803] = {
  title = "Araj's Scarab",
  desc = "Araj the Summoner tiene in pugno Andorhal dal cuore della città in rovina. Sappiamo che, prima di prendersela, era a capo della Scholomance. Per finire la chiave ci servirà il suo sigillo — lo chiamano scarabeo — da montare come testa.$B$BOra che è uscito allo scoperto, apriti la strada fino al centro di Andorhal e spezza il suo dominio. Quando l'avrai distrutto, prendi lo scarabeo dal suo filatterio caduto!$B$BLa Chiave della Scholomance ti aspetta, $N!",
  obj = "Distruggi Araj the Summoner e porta l'Araj's Scarab ad Alchemist Arbington a Chillwind Point, Western Plaguelands.",
  progress = "Sei $Garrivato:arrivata; fin qui, $N — solo distruggendo la forma fisica di Araj the Summoner avremo i mezzi per finire la chiave. Prendi l'Araj's scarab a ogni costo e portamelo — lo salderò alla chiave come testa.",
  reward = "Sì, è proprio questo! Io... ancora una volta, il tuo eroismo mi lascia sbalordito, tanto è grande. Davvero non mi capacito di fin dove sei $Gdisposto:disposta; a spingerti per sconfiggere le forze dell'oscurità.$B$BAdesso lasciami fare la mia piccola parte. Con un solvente speciale che ho preparato dovrei riuscire a fissare lo scarabeo come testa della chiave, e a infonderle il potere di sfondare la porta sbarrata della Scholomance.$B$BVada come vada...",
}
T[5804] = {
  title = "Araj's Scarab",
  desc = "Araj the Summoner domina Andorhal dal cuore della città in rovina. Sappiamo che un tempo era a capo di Scholomance, prima di prendersi Andorhal. Per completare la chiave ci servirà il suo sigillo — lo chiamano scarabeo — da montare come testa.$B$BRaggiungi il centro di Andorhal e spezza il suo dominio sulla città, ora che è uscito allo scoperto. Quando l'avrai distrutto, strappa lo scarabeo dal suo filatterio abbattuto!$B$BLa Chiave di Scholomance ti aspetta, $N!",
  obj = "Distruggi Araj the Summoner e porta l'Araj's Scarab ad Apothecary Dithers al Bulwark, Western Plaguelands.",
  progress = "Sei $Garrivato:arrivata; fin qui, $N — solo distruggendo la forma fisica di Araj the Summoner avremo i mezzi per completare la chiave. Prendi l'Araj's scarab, con le buone o con le cattive, e portamelo — lo fonderò con la chiave per farne la testa.",
  reward = "Sì, è questo! Io... ancora una volta, la tua astuzia e il tuo coraggio mi lasciano davvero sbalordito. Non riesco a credere fin dove sei $Gdisposto:disposta; a spingerti pur di vincere.$B$BOra lascia che faccia la mia piccola parte. Ho preparato un solvente speciale che dovrebbe permettermi di fissare lo scarabeo come testa della chiave, infondendole il potere di forzare la porta sbarrata di Scholomance.$B$BCi vorrà solo un momento...",
}
T[5821] = {
  title = "Guardia del Corpo a Pagamento",
  desc = "Normalmente io e Rigger porteremmo il nostro kodo oltre i Kolkar Centaur. Ogni tanto però sentiamo i tamburi di guerra dei Centauri, e allora ci fermiamo. Da morti non si fanno affari!$B$BFacciamo così, $C: se ci proteggi finché non ci saremo lasciati alle spalle il villaggio dei Kolkar, ti ricompenseremo come si deve.$B$BÈ solo un breve tratto: devi soltanto tenere intatta la carovana, poi potrai ritirare la ricompensa da Smeed Scrabblescrew — sta un po' più avanti lungo la strada. Facciamo qualche affare insieme.",
  obj = "Scorta la Carovana Gizelton oltre il villaggio dei Kolkar Centaur. Parla con Smeed a Scrabblescrew's Camp per la ricompensa.",
  progress = "Perché sto qui ad aspettare quella maledetta carovana?$B$B<Smeed sembra aver avuto un'illuminazione.>$B$BAh, già, i conti li pagano loro. Li hai visti?",
  reward = "Sai, pagare gente come te per fare la guardia alla Carovana Gizelton non mi sembra redditizio. $C, se fossi un po' più alto potrei prendermi un secondo lavoro e starmene in sella a un kodo, all'amazzone, col fucile più grosso che riesco a reggere in mano... e a quei maledetti centauri farei vedere io chi comanda.",
  en_title = "Bodyguard for Hire ",
  en_obj = "Escort the Gizelton Caravan past the Kolkar Centaur village. Talk with Smeed at Scrabblescrew's Camp for your reward.",
}
T[5845] = {
  title = "Di onore perduto",
  desc = "L'Ordine della Mano d'Argento fu decimato del tutto quando Uther fu ucciso.$B$BIl ragazzo resistette finché poté. Spinto fino al borgo dilaniato dalla guerra di Northdale, fece la sua ultima resistenza.$B$BEra rimasto vivo qualcuno dell'Ordine, si chiese, e aveva importanza?$B$BFu con quel pensiero che Taelan gettò a terra lo stendardo dell'Ordine e rinnegò tutto quello che aveva conosciuto. Il suo onore rimase sul terreno intriso di sangue di Northdale.$B$BDevi raggiungere Northdale e recuperare quel simbolo dell'onore perduto.",
  obj = "Raggiungi Northdale, nella regione nordorientale delle Eastern Plaguelands, e recupera lo Symbol of Lost Honor. Torna da Tirion Fordring quando hai finito.",
  progress = "La mia fede ti guiderà, $N. la Luce non conosce confini.",
  reward = "È glorioso adesso, perfino ridotto a brandelli, come il giorno in cui lo guardai e pronunciai il mio giuramento di fedeltà.$B$BLa sua redenzione arriva, e forse la mia con lei...",
}
T[5846] = {
  title = "Of Love and Family",
  desc = "Quando Taelan era bambino, andavamo sovente in gita a Caer Darrow con la famiglia. L'ultima volta un'artista di nome Renfray ci ha ritratti in posa sulla spiaggia. Di Taelan e di Karandra non ho ricordo più caro: è stato allora, con mia moglie e mio figlio fra le braccia, che ho sentito un legame d'amore e di famiglia che non avrei mai più conosciuto.$B$BSe quel dipinto esiste ancora, devi trovarlo.$B$BVa' sull'isola in rovina di Caer Darrow e scopri se il dipinto o l'artista sono ancora lì.",
  obj = "Recati sull'isola di Caer Darrow, nella zona centro-meridionale delle Plaguelands, e cerca qualsiasi indizio su dove si trovi il dipinto.",
  reward = "Come potrei dimenticare? Su quest'isola molti spiriti sono maledetti, costretti a rivivere il loro ultimo ricordo felice prima della tragica fine.$B$BAnch'io sono maledetta, ma non come loro — io sono una dei pochi che ricordano tutto...$B$BForse quello che mi chiedi è il motivo per cui infesto queste rovine. Forse quello che ti dico mi renderà libera.",
}
T[5848] = {
  title = "Of Love and Family",
  desc = "Il dipinto... Nel mio laboratorio — dentro la caserma dell'Ordine — è rimasto appeso alla parete per anni.$B$BDopo il processo di Tirion ho capito che non potevo più lasciarlo in vista, e l'ho nascosto dove non avrebbero mai pensato di cercare.$B$BVa' a Stratholme, addentrati in quello che ora è lo Scarlet Bastion e cerca un dipinto delle nostre lune gemelle. Gratta via la pittura finché non scoprirai il mio capolavoro, 'Amore e Famiglia'.$B$BChe la Luce guidi le tue azioni.",
  obj = "Recati a Stratholme, nella parte settentrionale di Plaguelands. Troverai il dipinto 'Amore e Famiglia' in Scarlet Bastion, nascosto dietro un altro quadro che raffigura le lune gemelle del nostro mondo.$B$BRiporta il dipinto a Tirion Fordring.",
  progress = "Il dipinto, $N. Ce l'hai?",
  reward = "<Alla vista del dipinto, Tirion quasi crolla.>$B$B<Comincia a singhiozzare quasi freneticamente.>",
}
T[5861] = {
  title = "Trova Myranda",
  desc = "$N, finora hai fatto tutto quello che ti ho chiesto. Alla tua ricerca di redenzione manca un solo passo.$B$BGli oggetti che hai raccolto devi consegnarli a Taelan, ma purtroppo Taelan e i suoi Scarlet Crusaders ti attaccheranno appena ti vedono.$B$BPer fargli avere il mio messaggio c'è un modo solo: un travestimento che li inganni.$B$BA sud troverai la tomba di Uther. Lì ora vive Myranda, una mia vecchia confidente di cui mi fido — cercala. Mostrale gli oggetti e ti aiuterà.",
  obj = "Recati alla Tomba di Uther, nella parte meridionale di Plaguelands. Mostra il Tirion's Gift a Myranda the Hag.",
  progress = "Sapevo che sarebbe arrivato questo giorno.",
  reward = "Quando Tirion era Signore di Mardenholde, ero la sua consigliera più fidata. Mi sono opposta apertamente al verdetto dell'Order of the Silver Hand, e per la mia insolenza mi hanno bandita.$B$BLa sua è stata una vita piena di dolori e delusioni, $R. Sei $Gpronto:pronta; a riparare i torti subiti dai Fordring?",
}
T[5862] = {
  title = "Sotterfugio Scarlatto",
  desc = "Sono quella che chiameresti un'illusionista. Forse riesco a creare un'illusione che ti faccia entrare a Hearthglen, ma sta' in guardia; i miei poteri hanno dei limiti.$B$BSe ti allontanerai troppo da queste terre, gli effetti dell'illusione svaniranno. L'incantesimo mi chiede molta concentrazione e molto potere, quindi posso tenerlo solo per poco.$B$BTorna a parlarmi quando sarai $Gpronto:pronta;.",
  obj = "Parla con Myranda per ottenere l'Illusione Scarlatta. Recati a Hearthglen sotto l'effetto dell'Illusione Scarlatta e consegna il Tirion's Gift a Highlord Taelan Fordring.$B$BHearthglen è a nord, Taelan dovrebbe trovarsi dentro Mardenholde Keep.",
  progress = "Fai parte dei rinforzi venuti da Tyr's Hand?",
  reward = "Che cos'è, soldato?$B$B<Taelan apre la scatola e si mette a esaminarne il contenuto.>$B$BQuesto... questo non può essere vero. Ma tutto quello che mi hai mostrato...$B$B<Taelan cade su un ginocchio, il battito gli accelera. La furia dei secoli sta per scatenarsi su questa città.>",
}
T[5863] = {
  title = "Il Dunemaul Compound",
  desc = "Da poco è arrivata a Tanaris una grossa banda di ogres nomadi. Si sono presi un bel pezzo di deserto a sud di qui e ci hanno costruito un insediamento. Intanto diverse bande più piccole girano per le dune, e alcune hanno invaso le antiche rovine troll.$B$BIl Dunemaul Compound va distrutto! Non possiamo lasciare che questi ogres mettano insieme un esercito.$B$BIl capo della banda si chiama Gor'marok the Ravager: credo che mettere fine al suo comando sarà l'inizio della fine per gli ogres.",
  obj = "Andi Lynn a Gadgetzan vuole che tu distrugga Dunemaul Compound uccidendo 10 Dunemaul Brutes, 10 Dunemaul Enforcers e Gor'marok the Ravager.",
  progress = "Sono così in pensiero! Ti prego, fai attenzione!",
  reward = "Sono così contenta che tu ci sia $Griuscito:riuscita; per me, $N! Grazie per l'aiuto!",
}
T[5881] = {
  title = "Richiamare le Riserve",
  desc = "L'Orda sa tenere ben riposate le nostre truppe... dalla Great War a oggi, qui a Kalimdor, abbiamo prosperato.$B$BDevo chiederti un favore. Nelle lande del sud ho un ragazzo, Grish Longrunner, che fa la guardia al Great Lift. Portagli questa lettera: gli dirà che sto mandando un guerriero di riserva a dargli il cambio, così potrà andare a trovare la famiglia. Me l'aveva chiesto tempo fa: sarà felice di saperlo.",
  obj = "Maggran vuole che tu consegni una lettera a Grish Longrunner a Great Lift in Barrens.",
  progress = "Mi porti notizie da Maggran Earthbinder?",
  reward = "Questa sì che è una bella notizia; è da troppo tempo che sto qui seduto a fare la guardia a questo pezzo di legno. Adesso potrò stare un po' con la famiglia... Evviva!",
  en_title = "Calling in the Reserves",
  en_obj = "Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens.",
}
T[5882] = {
  title = "Unguento Tramite la Caccia",
  progress = "Chi ha con sé un faro Cenarion può vedere un corrupted soul shard sulle bestie contaminate che vengono abbattute per il bene superiore. Io macino questi frammenti e ne ricavo un reagente che serve a fare l'unguento per piante Cenarion, e con quell'unguento faremo tornare sane le piante corrotte.$B$BSe mi porti i frammenti, in cambio ti darò degli unguenti per piante Cenarion che ho già preparato.",
  reward = "Molto bene, allora: ecco i tuoi unguenti per piante Cenarion. Batti il Felwood in cerca di piante corrotte, $N! Dovunque siano, purificale con l'unguento che ti ho dato.",
}
T[5883] = {
  title = "Unguento Tramite l'Estrazione",
  progress = "Se estrai minerali nel Felwood portando con te un faro Cenarion, potrai vedere il tainted vitriol che intacca una vena di metallo grezzo. Io so come purificare quel vetriolo e ricavarne un reagente che serve a fare l'unguento per piante Cenarion, che poi userai sulle piante da salvare che trovi in natura.$B$BSe hai raccolto del tainted vitriol, ti darò un po' dell'unguento per piante Cenarion che ho già preparato.",
  reward = "Molto bene, allora, ecco un po' di unguento per piante Cenarion. Se scavando nel Felwood trovi altro vetriolo, ricordati di metterlo da parte per me! Più ne trovi, più unguento potrò fare.",
}
T[5884] = {
  title = "Unguento Tramite la Raccolta",
  progress = "Un faro Cenarion permette a un erborista esperto di scorgere l'insidiosa fel creep — un prodotto malefico della corruzione del Felwood. Lavorando qui ho imparato a purificare la fel creep e a farne un reagente che risana... e che usiamo in quello che ora chiamiamo unguento per piante Cenarion.$B$BSe raccogli erbe nel Felwood con il faro addosso, dovresti trovare la fel creep. Per quello che mi porterai ti darò in cambio dell'unguento per piante Cenarion già pronto.",
  reward = "Ottimo lavoro, $N — ogni briciolo, una volta purificato, ci aiuterà a riprenderci il Felwood. Ecco, prendi qualche dose di unguento per piante Cenarion e vai nella foresta. La terra da strappare alla corruzione non aspetta $Gnessun:nessuna; $R!",
}
T[5885] = {
  title = "Unguento Tramite la Scuoiatura",
  progress = "Un faro Cenarion permette a uno scuoiatore ben addestrato di scorgere patches of tainted skin sul bottino raccolto nel Felwood. Sembrano pezzi inutili, ma io li trasformo in una pasta densa che fa da acceleratore per l'unguento per piante Cenarion. Quando scuoi le prede qui nel Felwood, assicurati di avere un faro con te!$B$BSe raccogli dei pezzi corrotti, portameli e ti darò degli unguenti per piante Cenarion che ho già fatto.",
  reward = "È proprio quello che mi serve. Ecco — prendi questi unguenti per piante e usali per strappare il Felwood alla corruzione. Dobbiamo perseverare, $N!",
}
T[5886] = {
  title = "Unguento Tramite Disincantamento",
  progress = "Il potere di un oggetto magico, una volta disincantato, si sente nell'essenza che ne esce. Ho ideato un modo per trasformare l'essenza grezza usata dagli incantatori in un reagente adatto a preparare l'unguento vegetale Cenarion. Quindi non ti serve un faro Cenarion: va bene qualsiasi oggetto disincantato a dovere che dia lesser nether essences.$B$BMi basta una sola lesser nether essence, e in cambio ti darò degli unguenti vegetali Cenarion. È un'essenza potentissima — con poca se ne fa tanto!",
  reward = "Ecco degli unguenti vegetali Cenarion — per questi mi serve solo una lesser nether essence, $N. Fra tutto quello che posso usare per trasformare le spade in vomeri, per così dire, l'essenza è di gran lunga l'oggetto più potente. Se ti serve altro unguento, vieni a cercarmi qui!",
}
T[5887] = {
  title = "Unguento Tramite la Caccia",
  progress = "Chi ha con sé un faro Cenarion può vedere un corrupted soul shard sulle bestie contaminate che vengono abbattute per il bene di tutti. Io macino quei frammenti e ne ricavo un reagente per preparare l'unguento per piante Cenarion, con cui faremo tornare sane le piante corrotte.$B$BIn cambio di questi frammenti ti darò degli unguenti per piante Cenarion che ho già preparato.",
  reward = "Molto bene, ecco i tuoi unguenti per piante Cenarion. Setaccia il Felwood in cerca di piante corrotte, $N! Dovunque siano, purificale con l'unguento che ti ho dato.",
}
T[5888] = {
  title = "Unguento Tramite l'Estrazione Mineraria",
  progress = "Se porti con te un faro Cenarion quando estrai minerali nel Felwood, potrai vedere il tainted vitriol che contamina un filone di metallo grezzo. Io so come purificare quel vetriolo e farne un reagente per preparare l'unguento per piante Cenarion, che poi userai sulle piante selvatiche da salvare.$B$BSe hai raccolto del tainted vitriol, ti darò un po' dell'unguento per piante Cenarion che ho già preparato.",
  reward = "Molto bene, ecco un po' di unguento per piante Cenarion. Se trovi altro vetriolo mentre estrai minerali nel Felwood, ricordati di metterlo da parte per me! Più ne trovi, più unguento potrò preparare.",
}
T[5889] = {
  title = "Unguento Tramite la Raccolta",
  progress = "Con un faro Cenarion, un erborista esperto riesce a scorgere l'insidiosa fel creep — un prodotto maligno della corruzione del Felwood. Lavorando qui ho imparato a depurare la fel creep e a farne un reagente purificante... quello che serve per ciò che ora chiamiamo unguento per piante Cenarion.$B$BSe raccogli erbe nel Felwood e hai con te il faro, dovresti trovare la fel creep. Per quello che mi porterai, ti darò in cambio dell'unguento per piante Cenarion già pronto.",
  reward = "Ottimo lavoro, $N — ogni briciola, una volta purificata, ci aiuterà a riprenderci il Felwood. Ecco, prendi qualche dose di unguento per piante Cenarion e addentrati nella foresta. Strappare la terra alla corruzione è un compito che non aspetta $Gnessun:nessuna; $R!",
}
T[5890] = {
  title = "Unguento Tramite la Scuoiatura",
  progress = "Con un faro Cenarion, uno scuoiatore ben addestrato riesce a scorgere dei patches of tainted skin sulle prede cacciate nel Felwood. Sembrano inutili, ma io li trasformo in una pasta densa che fa da acceleratore all'unguento per piante Cenarion. Quando scuoi le prede qui nel Felwood, assicurati di avere con te un faro!$B$BQuando raccogli i pezzi corrotti, portameli: in cambio ti darò degli unguenti per piante Cenarion che ho già preparato.",
  reward = "È proprio quel che mi serve. Ecco, prendi questi unguenti per piante e usali per strappare il Felwood alla corruzione. Dobbiamo tenere duro, $N!",
}
T[5891] = {
  title = "Unguento dal Disincanto",
  progress = "Il potere di un oggetto magico disincantato si capisce dall'essenza che ne esce. Ho trovato il modo di trasformare l'essenza grezza che usano gli incantatori in un reagente con cui preparare l'unguento per piante Cenarion. Non ti serve un faro Cenarion, per questo: va bene qualunque oggetto che, disincantato a dovere, dia lesser nether essences.$B$BMi serve soltanto una lesser nether essence, e in cambio ti darò degli unguenti per piante Cenarion. È un'essenza potentissima — ne basta un pizzico!",
  reward = "Ecco degli unguenti per piante Cenarion — in cambio mi basta una sola lesser nether essence, $N. Fra tutto quello che posso usare per trasformare le spade in vomeri, per così dire, l'essenza è di gran lunga la cosa più potente. Se ti serve altro unguento, vieni a cercarmi qui!",
}
T[5892] = {
  title = "Irondeep Supplies",
  desc = "Prima che cominciassero i combattimenti abbiamo sistemato le scorte per Dun Baldar nella miniera di Irondeep. Finché avevamo truppe in più a sorvegliarla, i troggs spuntati lì non erano un gran problema, ma adesso che combattiamo contro l'Orda non riusciamo più a tenere Irondeep.$B$BCi servono le scorte che stanno a Irondeep, $N. Entra nella miniera e portamene un carico.",
  obj = "Porta 10 Irondeep Supplies al Furiere dell'Alleanza a Dun Baldar.",
  progress = "Le hai, le scorte, $N? Non bastano mai!",
  reward = "Ben fatto! Queste scorte le userò a dovere! Grazie, $N!",
}
T[5893] = {
  title = "Coldtooth Supplies",
  desc = "Un tempo la miniera di Coldtooth, a nord, era il posto ideale per tenere le scorte in più, ma ora che i combattimenti con gli Stormpike si fanno feroci non sempre abbiamo guerrieri da mandare a difenderla. Così la miniera finisce spesso in mano all'Alleanza, o alle creature del sottosuolo...$B$BMa le nostre scorte ci servono ancora, $N! Va' alla miniera di Coldtooth e portamene un carico. E guardati dai nemici lungo la strada; laggiù le sorti della battaglia cambiano in fretta...",
  obj = "Porta 10 Coldtooth Supplies al Furiere dell'Orda alla Frostwolf Keep.",
  progress = "Sei $Gstato:stata; alla miniera di Coldtooth, $N? Le scorte che ti ho chiesto, le hai?",
  reward = "Ah, le hai prese. Ottimo lavoro, $N! Queste scorte, dopo tanto tempo in quella miniera buia, sanno un po' di muffa, ma le useremo lo stesso.$B$BGrazie, $N. Quello che fai è fondamentale per mantenere le nostre truppe.",
}
T[5901] = {
  title = "Che la Piaga ti Colga",
  desc = "Dunque, per portare dolore e discordia alla Scarlet Crusade, voglio privarli della loro preziosa segheria. Sono certa che perdere una risorsa simile li metterà in serie difficoltà ora che cerca di difendere la città e di ricostruirla per i propri scopi. Mi aiuterai, $N?$B$BPer cominciare, porta questo barattolo a Plaguewood, nelle Eastern Plaguelands. Riempilo con le termiti dei termitai sparsi per il bosco. Torna quando ne avrai abbastanza.",
  obj = "Usa l'Empty Termite Jar sui Termitai in Eastern Plaguelands. Dopo aver raccolto 100 Plagueland Termites, torna da Mickey Levine al Bulwark, nelle Tirisfal Glades.",
  progress = "Hai già le termiti, $N? Sono certa che per $Gun:una; $C $Gsveglio:sveglia; come te sia scontato.$B$BQuando ne avremo abbastanza, faremo in modo che nessuno possa più usare la segheria!",
  reward = "Andranno benissimo, $N. Grazie.$B$BSe sei $Gpronto:pronta;, possiamo passare alla prossima fase.",
  en_title = "A Plague Upon Thee",
  en_obj = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Mickey Levine at the Bulwark in Tirisfal Glades.",
}
T[5902] = {
  title = "Che la Piaga ti Colga",
  desc = "Ora che abbiamo termiti in abbondanza, porta questo barile rinforzato in acciaio alla Northridge Lumber Mill, a sud di Hearthglen — la troverai a ovest della strada che sale verso la città.$B$BUna volta lì, sistemalo al centro della segheria; in un punto rialzato, come sopra una cassa o qualcosa del genere.$B$BQuando l'avrai aperto il resto dovrebbe venire da sé. A quel punto non ti resta che tornare qui e ti ricompenserò per avermi aiutata.",
  obj = "Trova un punto adatto al centro di Northridge Lumber Mill, in Western Plaguelands, dove sistemare il Barrel of Plagueland Termites.",
  reward = "Mentre sistemi il barile sopra la cassa, le termiti si agitano visibilmente.",
  en_title = "A Plague Upon Thee",
  en_obj = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.",
}
T[5903] = {
  title = "Una Piaga su di Te",
  desc = "Ho provato tante volte a cacciare la Scarlet Crusade con la sola forza, ma senza risultato. Così ho deciso di tentare un'altra strada: rendere loro la vita più difficile.$B$BSe sei $Gdisposto:disposta; a darmi una mano, voglio infestare quella segheria con la specie di termiti più terribile che si sia mai trovata.$B$BNella Plaguewood, vicino a Stratholme, un tempo grandiosa, c'è una razza che è sopravvissuta sia alla piaga sia allo Scourge. Trova i termitai e riempi di termiti questo contenitore: così potremo prepararle prima di scatenarle contro la Crociata.",
  obj = "Usa l'Empty Termite Jar sui Termitai in Eastern Plaguelands. Dopo aver raccolto 100 Plagueland Termites, torna da Nathaniel Dumah a Chillwind Camp in Western Plaguelands.",
  progress = "Allora, $N, hai trovato i termitai? Ho sentito dire che nella Plaguewood ce ne sono dappertutto.",
  reward = "Queste andranno benissimo, $N, grazie. Guardale... così tante, tutte ammucchiate. Quasi mi dispiace per la Crociata, ma in fondo quella segheria non è mai stata loro, no?",
}
T[5904] = {
  title = "Una Piaga su di Te",
  desc = "Ora che abbiamo le termiti, porta questo barile rinforzato in acciaio alla Northridge Lumber Mill, a sud di Hearthglen — la trovi a ovest della strada che sale al paese.$B$BUna volta lì, metti il barile al centro della segheria; cerca un posto adatto, magari sopra una cassa, e poi aprilo. A quel punto le termiti dovrebbero fare il loro lavoro e rendere la segheria inutilizzabile per la Crociata.",
  obj = "Trova un posto adatto al centro di Northridge Lumber Mill in Western Plaguelands dove mettere il Barrel of Plagueland Termites.",
  reward = "Mentre metti il barile sopra la cassa, le termiti si agitano visibilmente.",
}
T[5921] = {
  title = "Moonglade",
  desc = "Le sacre terre di Moonglade accolgono tutti i druidi, nonostante le tensioni che oggi dividono il Cenarion Circle tra Arch Druid Staghelm e Keeper Remulos — il guardiano di Moonglade. Ora che stai imparando le vie dell'Unghia, ti insegnerò l'incantesimo che ti trasporta laggiù. Lancialo ogni volta che cerchi la conoscenza o il conforto di Moonglade.$B$BPer la tua prima lezione, va' a Moonglade e parla con Dendrite Starblaze, a Nighthaven, del sentiero che hai intrapreso. Buona fortuna, $Ggiovane druido:giovane druida;.",
  obj = "Usa l'incantesimo \"Teletrasporto: Moonglade\" per raggiungere Moonglade. Quando arrivi, parla con Dendrite Starblaze nel villaggio di Nighthaven.",
  reward = "E così ha inizio, Father Cenarius. E così ha inizio.$B$B<Dendrite traccia nell'aria sopra di sé un gesto rapido e invisibile. Una lieve aura di potere scende su di lui.>$B$BLa prima prospettiva della natura a cui devi adattarti è quella dell'orso. Io ti avvierò a comprendere questo aspetto della vita druidica, ma sta a te abbracciarlo e diffonderlo — ora e per sempre!",
  en_title = "Moonglade",
  en_obj = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.",
}
T[5922] = {
  title = "Moonglade",
  desc = "Tutti i druidi, tauren o elfi della notte che siano, sono i benvenuti nelle terre sacre di Moonglade. Keeper Remulos — guardiano di Moonglade — veglia su tutti i druidi che lì vanno in letargo. Ora che stai imparando le vie dell'Unghia, ti insegnerò l'incantesimo per arrivarci: lancialo ogni volta che cercherai la conoscenza o il conforto di Moonglade.$B$BPer la tua prima lezione, raggiungi Moonglade e parla del sentiero che ora percorri con Dendrite Starblaze, a Nighthaven. Buona fortuna, $Ggiovane druido:giovane druida;.",
  obj = "Usa l'incantesimo \"Teletrasporto: Moonglade\" per raggiungere Moonglade. Quando arrivi, parla con Dendrite Starblaze nel villaggio di Nighthaven.",
  reward = "E così comincia, Father Cenarius. E così comincia.$B$B<Dendrite traccia un gesto rapido e invisibile nell'aria sopra di sé. Una lieve aura di potere scende su di lui.>$B$BLa prima prospettiva della natura a cui dovrai adattarti è quella dell'orso. Io ti indicherò la strada per comprendere questo aspetto della vita druidica, ma tocca a te abbracciarlo e diffonderlo — ora e per sempre!",
  en_title = "Moonglade",
  en_obj = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.",
}
T[5923] = {
  title = "Rispondere alla Chiamata",
  desc = "Scusami, $Gamico:amica;...$B$BMi è giunta voce che Mathrengyl Bearwalker ha fatto sapere che vuole parlarti. A quanto pare il tuo addestramento da $Gdruido:druida; sta per prendere nuova vita, e sarà lui stesso a istruirti. Mathrengyl è l'assistente diretto dell'Arcidruido in persona: uno dei druidi più saggi e illustri che troverai a Teldrassil.$B$BLo trovi nella Cenarion Enclave of Darnassus, al secondo piano dell'albero di Fandral Staghelm.",
  obj = "Parla con Mathrengyl Bearwalker nella Cenarion Enclave, Darnassus.",
  reward = "Sono lieto che oggi tu abbia trovato la strada fin qui, $Ggiovane druido:giovane druida;. È giunto il momento di fare un grande passo in un mondo molto più grande.$B$BOgni figlio di Cenarius porta in sé la chiamata a servire la natura. Animali e piante sono nostri amici, e insieme nostri protetti. Scegliamo di dedicare la vita a custodire l'equilibrio, per il loro bene e per il nostro. In questo mondo il tuo primo passo sarà imparare le vie dell'orso e la forza del corpo e del cuore.$B$BPreparati!",
  en_title = "Heeding the Call",
  en_obj = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.",
}
T[5924] = {
  title = "Rispondere alla Chiamata",
  desc = "Scusami, $Gamico:amica;...$B$BMi è giunta voce che Mathrengyl Bearwalker ha fatto sapere che vuole parlarti. A quanto pare il tuo addestramento da $Gdruido:druida; sta per prendere nuova vita, e sarà lui stesso a istruirti. Mathrengyl è l'assistente diretto dell'Arcidruido in persona: uno dei druidi più saggi e illustri che troverai a Teldrassil.$B$BLo trovi nella Cenarion Enclave of Darnassus, al secondo piano dell'albero di Fandral Staghelm.",
  obj = "Parla con Mathrengyl Bearwalker nella Cenarion Enclave, Darnassus.",
  reward = "Sono lieto che oggi tu abbia trovato la strada fin qui, giovane $C. È giunto il momento di fare un grande passo in un mondo molto più grande.$B$BOgni figlio di Cenarius porta in sé la chiamata a servire la natura. Animali e piante sono nostri amici, e insieme nostri protetti. Scegliamo di dedicare la vita a custodire l'equilibrio, per il loro bene e per il nostro. In questo mondo il tuo primo passo sarà imparare le vie dell'orso e la forza del corpo e del cuore.$B$BPreparati!",
  en_title = "Heeding the Call",
  en_obj = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.",
}
