T[5929] = {
  title = "Great Bear Spirit",
  desc = "Nella parte nordoccidentale di Moonglade vive un essere saggio e nobile che chiamiamo Great Bear Spirit. A tutti i druidi ha fatto da maestro e da guida, portandoli alla prima vera comprensione naturale dell'orso. Prima o poi ogni druido va in cerca della saggezza dello spirito, e tu non farai eccezione.$B$BVa' ora dal Great Bear Spirit e impara ciò che ha da insegnarti. Quando sarà soddisfatto di te, torna da me qui a Nighthaven: vedremo allora se hai fatto davvero tesoro delle sue lezioni.",
  obj = "Cerca il Great Bear Spirit nella parte nordoccidentale di Moonglade e impara ciò che ha da insegnarti sulla natura dell'orso. Quando hai finito, torna da Dendrite Starblaze a Nighthaven, Moonglade.",
  progress = "Non tornare finché il Great Bear Spirit non ti avrà rimandato da me. Senza la sua benedizione il tuo addestramento non può andare avanti.",
  reward = "<Mentre ti avvicini, Dendrite traccia un altro gesto invisibile nell'aria sopra di sé. Un'altra aura di potere scende su di lui, e sul suo volto compare un sorriso appena accennato.>$B$BSento in te una saggezza che non c'era la prima volta che ci siamo incontrati, giovane. Mi guardi con forza e con un'intenzione consapevole, anche se non ancora messa a fuoco. Ora imparerai a concentrare la tua forza e a portare la natura dell'orso in quello che fai.",
  en_title = "Great Bear Spirit",
  en_obj = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.",
}
T[5930] = {
  title = "Great Bear Spirit",
  desc = "Nel nord-ovest di Moonglade vive un essere saggio e nobile che chiamiamo il Great Bear Spirit. Per ogni druido è stato il maestro e la guida che porta a capire davvero, per la prima volta, la natura dell'orso. Prima o poi tutti i druidi vanno a cercare la sua saggezza, e tu non farai eccezione.$B$BVa' ora dal Great Bear Spirit e impara quello che ha da insegnarti. Quando sarà soddisfatto di te, torna qui da me, a Nighthaven: allora vedremo se hai davvero fatto tesoro delle sue lezioni.",
  obj = "Cerca il Great Bear Spirit nel nord-ovest di Moonglade e impara ciò che ha da insegnarti sulla natura dell'orso. Al termine, torna da Dendrite Starblaze a Nighthaven, Moonglade.",
  progress = "Torna solo quando il Great Bear Spirit ti avrà rimandato da me: senza la sua benedizione il tuo addestramento non può andare avanti.",
  reward = "<Mentre ti avvicini, Dendrite traccia un altro gesto invisibile nell'aria sopra di sé. Un'altra aura di potere scende su di lui, e lui accenna un sorriso.>$B$BSento in te, giovane, una saggezza che al nostro primo incontro non c'era. Mi guardi con forza e con uno scopo consapevole, anche se non ancora a fuoco. Ora imparerai a concentrare la forza e a portare la natura dell'orso in quello che fai.",
  en_title = "Great Bear Spirit",
  en_obj = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.",
}
T[5931] = {
  title = "Ritorno a Darnassus",
  desc = "È giunto il momento di separarci, giovane: per mettere in pratica quello che hai imparato devi tornare da chi ti ha mandato da me. Mathrengyl Bearwalker cammina davvero in equilibrio con la natura, anche se vive pericolosamente vicino al luogo dove l'equilibrio ha vacillato. Segui le sue istruzioni e presto concluderai le prime lezioni da $Gprotettore:protettrice; dell'equilibrio.$B$BVa' ora, giovane. Ci rivedremo.",
  obj = "Torna a Darnassus e parla con Mathrengyl Bearwalker nella Cenarion Enclave.",
  reward = "$GBentornato:Bentornata;, $N. Sento che il tuo primo incontro con il Great Bear Spirit è andato come per tutti i druidi che cominciano a percorrere il sentiero dell'Unghia... un po' sconcertante, ma molto intenso. Per me, lo so, è stato così.$B$BIl Great Bear Spirit fa parte di Azeroth da quando Azeroth esiste nei cieli. Abbiamo imparato a contare sulla sua saggezza e sul suo potere per alimentare il nostro scopo, e ora per te è giunto il momento di metterlo alla prova per la prima volta. Ascolta bene...",
  en_title = "Back to Darnassus",
  en_obj = "Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave.",
}
T[5932] = {
  title = "Ritorno a Thunder Bluff",
  desc = "È ora di separarci, giovane: per mettere in pratica quello che hai imparato devi tornare da chi ti ha mandato da me. Anche se i tauren sono considerati giovani nelle vie di Cenarius, Turak Runetotem cammina davanti alla natura in grande equilibrio. Ascolta le sue istruzioni e presto avrai completato le prime lezioni come $Gprotettore:protettrice; dell'equilibrio.$B$BOra va', giovane. Ci rivedremo.",
  obj = "Torna a Thunder Bluff e parla con Turak Runetotem sull'Elder Rise.",
  reward = "$GBentornato:Bentornata;, $N. Sento che il tuo primo incontro con il Great Bear Spirit è andato come per ogni druido che comincia a percorrere il sentiero dell'Unghia... un po' sconcertante, ma molto intenso. Per me, di sicuro, è stato così.$B$BIl Great Bear Spirit fa parte di Azeroth da quando Azeroth esiste nei cieli. Noi tauren ascoltiamo con attenzione questi spiriti, e il suo scopo fa prosperare tutti noi. Ora è il momento della tua prima prova al servizio di quello scopo. Ascolta bene...",
  en_title = "Back to Thunder Bluff",
  en_obj = "Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise.",
}
T[5941] = {
  title = "Ritorno da Chromie",
  desc = "Di reliquie della battaglia di Darrowshire ne hai raccolte tante. E ogni volta che ne riportavi altre, il mio cuore sospirava per il villaggio... sospirava di poterlo proteggere dal suo destino.$B$BLo so che non è possibile, eppure Chromie, quella strana gnoma ad Andorhal, mi dice che si può fare. Dice che puoi salvare Darrowshire!$B$BMi ha chiesto di riunire le reliquie e di fargliele avere tramite te. Ha detto che ti aspetta nella locanda in rovina di Andorhal.",
  obj = "Porta il Bundle of Relics a Chromie ad Andorhal.",
  progress = "Sono stata in contatto con il tuo amico Carlin. La rovina del suo villaggio lo fa soffrire molto, ma di te parla benissimo, e sa che puoi rimettere le cose a posto.$B$BOh, ma sto divagando... $N, ce le hai le reliquie che ti ho chiesto?",
  reward = "Ah sì, eccole qui. Tutte insieme intessono un potente incantesimo, che risveglierà gli spiriti di Darrowshire.$B$BCon quell'incantesimo, e un po' di fortuna, possiamo salvare Joseph Redpath!",
}
T[5942] = {
  title = "Tesori Nascosti",
  desc = "Papà mi ha detto di darti questa chiave. Dice che apre un forziere là dietro, sul retro della casa.$B$BE voleva che ti dicessi grazie. Gli hai fatto un favore? Gli hai detto che hai trovato la mia bambola?$B$BBeh, tieni, ecco la chiave. E grazie, $N. Grazie! Sei $Gun signore:una signora; tanto gentile!",
  obj = "Porta la Joseph's Key al Joseph's Chest.",
  progress = "Questo forziere è vecchio e coperto di sporcizia.",
  reward = "La chiave entra nella serratura e il forziere si apre...",
}
T[5943] = {
  title = "Carovana Gizelton",
  desc = "Hai l'aria di $Gun:una; $R capace. Ti andrebbe di guadagnare qualcosa? Io e Cork abbiamo messo su questa carovana per fare un mucchio di soldi, e non avevamo idea di quanti pericoli ci fossero a far quattrini!$B$BPiù avanti c'è la Mannoroc Coven... Di solito i demoni non ci badano, ma stavolta i kodo si sono spaventati per qualcosa. Ti pagherò se proteggerai la carovana finché non avrà superato la Mannoroc Coven. Una volta passati sani e salvi, la ricompensa potrai riscuoterla dal nostro socio d'affari Smeed, allo Scrabblescrew's Camp.",
  obj = "Scorta la Carovana Gizelton attraverso Mannoroc Coven. Parla con Smeed a Scrabblescrew's Camp per ricevere la tua ricompensa.",
  progress = "Sai, se un giorno quella carovana sparisse, sarei rovinato! Non è che mi porti cattive notizie della carovana, vero?$B$B<Smeed si asciuga la fronte.>$B$BSia ringraziata la dea dell'avidità!",
  reward = "Non so se convenga pagare così tanto per far proteggere la Carovana Gizelton. Cork e Rigger guadagnano appena un pezzo d'oro a settimana, ma finché continuano a pagarmi i kodo, di come mandano avanti i loro affari non me ne importa niente.",
  en_title = "Gizelton Caravan",
  en_obj = "Escort the Gizelton Caravan through Mannoroc Coven. Talk with Smeed at Scrabblescrew's Camp for your reward.",
}
T[5944] = {
  title = "Nei Sogni",
  desc = "Per tanto tempo sono stato la marionetta del Gran Crociato. Che senso aveva combattere contro ciò che era diventata la Scarlet Crusade? Sono passati decenni, eppure a tenermi in vita sono stati i ricordi di mio padre; quei ricordi preziosi.$B$BFaccio dei sogni, $Gstraniero:straniera;. In sogno mio padre è con me. Mi sta accanto, fiero, mentre vengo accolto nell'Ordine. Insieme combattiamo legioni dello Scourge. Facciamo onore all'Alleanza, a Lordaeron.$B$BNon voglio più sognare.$B$BPortami da lui.",
  obj = "Scorta Taelan Fordring fuori da Hearthglen.",
  progress = "<Tirion si ricompone.>",
  reward = "Questi mostri hanno ucciso mio figlio, e non resterà senza conseguenze. Che ti sia di conforto sapere che l'Ordine è rinato.$B$BOra prendo il mio posto di Alto Signore del nuovo Order of the Silver Hand.$B$BQuesti oggetti del mio passato — sono tutto ciò che posso offrirti per quello che hai fatto. Prendili, ti prego, in segno della mia gratitudine; negli anni mi hanno servito bene, tutti quanti.$B$BChe ci sia dato di rivederci, in tempi migliori, e di ricordare i giorni ormai lontani... le dure battaglie combattute... i sogni riscattati.",
}
T[5961] = {
  title = "Il Campione di The Banshee Queen",
  desc = "Mi rallegra molto che chi è temprato dalla battaglia si unisca alla nostra causa. Giorno dopo giorno cresciamo di numero e di forza. Sei forse $Gpronto:pronta; a mettere alla prova il tuo valore, $C?$B$BUno dei miei primi campioni è stato Nathanos, che oggi chiamano l'Araldo della Piaga. Nei nostri ranghi, pochi hanno più dedizione o più vigore di lui.$B$BCercalo nelle Eastern Plaguelands. Risiede al Marris Stead; di tanto in tanto vaga per le lande devastate e uccide tutta la feccia dello Scourge e dell'Alleanza che trova sul suo cammino.",
  obj = "Parla con Nathanos Blightcaller in Eastern Plaguelands. Si dice che abbia preso dimora a Marris Stead.",
  reward = "Di certo la Signora Oscura non ti considera $Gdegno:degna; di incontrare il suo campione. Sei qui per sfamare i miei segugi, vero? Non può esserci altro motivo per venirmi a interrompere.",
}
T[5981] = {
  title = "Giganti Scatenati",
  desc = "Circa 4.000 anni fa alcuni giganti scatenati minacciavano la vita della regina frostsaber, e Tyrande Whisperwind la salvò. Da allora i frostsabers sono alleati degli elfi della notte.$B$BQuegli stessi giganti, che un tempo erano un pericolo per i frostsabers, vivono ancora poco lontano da qui. Si chiamano frostmaul e hanno occupato la grande valle a sud.$B$BDimostra la tua lealtà ai frostsabers: uccidi questi giganti nel nome della regina frostsaber, Shy-Rotam!",
  obj = "Rivern Frostwind vuole che tu uccida 4 Frostmaul Giants e 4 Frostmaul Preservers.",
  progress = "Devi continuare a dar prova del tuo valore, $N.",
  reward = "Eccellente, $N. Della tua determinazione ho preso debita nota.",
}
T[6001] = {
  title = "Corpo e Cuore",
  desc = "Subito a est di Auberdine ci sono molte grotte dei moonkin, e in quella più vicina ad Auberdine si trova una Moonkin Stone. Il suo difensore, Lunaclaw, ti affronterà solo quando ci avrai sparso sopra la Cenarion Moondust. Lunaclaw possiede una forza che dovrai usare come $Guno:una; dell'Unghia.$B$BTi sei $Gguadagnato:guadagnata; il diritto di usare questa Cenarion Moondust, $N... ora dimostrami di esserti $Gguadagnato:guadagnata; il diritto alla forza del corpo e alla forza del cuore che servono a $Gun druido:una druida;!",
  obj = "Usa la Cenarion Moondust sulla Moonkin Stone di Auberdine per far comparire Lunaclaw. Poi dovrai affrontare Lunaclaw e guadagnarti la forza del corpo e del cuore che possiede.$B$BQuando hai finito, parla con Mathrengyl Bearwalker a Darnassus.",
  progress = "Quando avrai affrontato la sfida che ti aspetta, capirai fino in fondo la forza del corpo e la forza del cuore. Fino ad allora non posso aiutarti oltre.",
  reward = "Finalmente hai fatto il tuo grande passo in un mondo molto più grande, $N. Sento in te l'insegnamento del Great Bear Spirit, e sento che hai ricevuto la forza che era di Lunaclaw.$B$BOra sul tuo cammino non ci sono più ostacoli... lascia che ti insegni che cosa vuol dire essere un Druid of the Claw!",
  en_title = "Body and Heart",
  en_obj = "Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.$B$BSpeak with Mathrengyl Bearwalker in Darnassus when you are done.",
}
T[6002] = {
  title = "Corpo e Cuore",
  desc = "A ovest di Taurajo, nelle Barrens — poco prima che lascino il posto a Mulgore — c'è una Moonkin Stone. I moonkin sono bestie speciali, che non vengono da queste parti. Lunaclaw, il difensore della pietra, ti affronterà quando la cospargerai di Cenarion Lunardust. Dentro di sé Lunaclaw ha una forza che tu, come $Guno:una; dell'Unghia, devi usare.$B$BTi sei $Gguadagnato:guadagnata; il diritto di usare questa Cenarion Lunardust, $N... ora dimostrami che ti sei $Gguadagnato:guadagnata; quello di possedere la forza del corpo e del cuore che serve a un druido!",
  obj = "Usa la Cenarion Lunardust sulla Moonkin Stone tra Mulgore e le Barrens per far comparire Lunaclaw. Poi dovrai affrontare Lunaclaw e guadagnarti la forza del corpo e del cuore che possiede.$B$BParla con Turak Runetotem a Thunder Bluff quando hai finito.",
  progress = "Quando avrai affrontato la sfida che ti aspetta, capirai fino in fondo la forza del corpo e del cuore. Fino ad allora non posso aiutarti di più.",
  reward = "Finalmente hai fatto il tuo grande passo verso un mondo molto più vasto, $N. Sento in te l'insegnamento del Great Bear Spirit, e capisco che hai ricevuto la forza che possedeva Lunaclaw.$B$BSulla tua strada non ci sono più ostacoli... ora lascia che ti insegni cosa vuol dire essere un Druid of the Claw!",
  en_title = "Body and Heart",
  en_obj = "Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.$B$BSpeak with Turak Runetotem in Thunder Bluff when you are done.",
}
T[6004] = {
  title = "Affari in Sospeso",
  desc = "Mi hanno mandata in avanscoperta a fare un po' di danni e a capire quanto sono forti le difese di Hearthglen. Nell'Alleanza c'è chi pensa che la cittadina conti per qualcosa di più della sua storia. Di cosa si tratti non sta a me chiedermelo, ma comunque, finché non mi sarò riposata, non sono in condizione di andare avanti.$B$BSe te la senti, un aiuto lo pagherei bene. Comincia dal loro accampamento a sud di qui, vicino al piccolo bastione che hanno eretto. Se dimostri di essere abbastanza forte, forse potrei chiederti una mano con il mio obiettivo principale.",
  obj = "Uccidi 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi e 2 Scarlet Knights prima di tornare da Kirsta Deepshadow in Western Plaguelands.",
  progress = "Come va, $N? Sono più forti di quanto ti aspettassi? Spero di no. Per portare a termine la missione ci vorrà un bel po' più di forza di quella che ti ho chiesto finora.",
  reward = "Ben fatto, $N. Mi stupisce che tu li abbia sistemati così in fretta. Grazie.$B$BNon ho ancora incontrato nessuno che approvi la Scarlet Crusade e i suoi metodi. Credo nella Luce quanto chiunque altro a Stormwind, ma loro hanno dimostrato di voler solo uccidere chi non è fedele al loro movimento... perfino gli innocenti.",
}
T[6021] = {
  title = "Zaeldarr the Outcast",
  desc = "Ci credi che, con tutti i guai che abbiamo nelle terre appestate... ci tocca stare attenti anche ai ladri? E non ladri qualunque, ladri troll.$B$BE non ladri troll qualunque. Ladri troll morti!$B$BLi guida un grosso troll morto di nome Zaeldarr the Outcast, e vengono di notte a rubare i cadaveri dalla fossa qui sotto, per poi portarseli nel loro malvagio covo di troll morti — l'Undercroft a ovest.$B$BVai lì e fai fuori Zaeldarr, $N. Delle sue malefatte sono stufo da morire!",
  obj = "Porta la Zaeldarr's Head a Caretaker Alen alla Light's Hope Chapel.",
  progress = "Hai trovato il covo, $N? Ti sei $Goccupato:occupata; di Zaeldarr?",
  reward = "Ottimo, l'hai preso! E spero che tu abbia dato una lezione anche alla sua banda!",
}
T[6022] = {
  title = "Uccidere con uno Scopo",
  desc = "Finché resti nel mio podere, uccidi con uno scopo.$B$BPer cominciare, darai da mangiare ai miei segugi.$B$BPrendi questo mortar and pestle e va' a Corin's Crossing: lì di creature dello Scourge da massacrare ne troverai un'ampia scelta. Mi serve del living rot, preso dalle loro carcasse fresche. Prendi quel living rot, macinalo nel mortaio e lascialo riposare finché non si coagula. Poi riportami qui il coagulated rot.$B$BE tieni presente, imbecille, che il living rot dei non morti non resta 'vivo' a lungo. Devi uccidere in fretta!",
  obj = "Va' a Corin's Crossing, a est, e massacra i membri dello Scourge che abitano il villaggio. Raccogli 7 pezzi di Living Rot in meno di 10 minuti. Usa il Mortar and Pestle per macinare il Living Rot e ottenere il Coagulated Rot.",
  progress = "Stai piangendo? Se lo trovi troppo 'noioso', '$Geroe:eroina;', ti consiglio di tornare dalla Dama Oscura e di raccontarle gli orribili maltrattamenti che hai subito nel mio podere.$B$BOra levati dalla mia vista!",
  reward = "Deludente. Io speravo di dare in pasto te ai miei segugi.$B$B<Nathanos sospira.>$B$BBe', almeno avranno qualcosa da mangiare.",
}
T[6023] = {
  title = "Affari in Sospeso",
  desc = "La mia vera missione era indebolire le forze esterne della Scarlet Crusade e poi infiltrarmi a Hearthglen per capire quanti sono. Da sola non sono ancora in condizione di farlo: potrei chiederti di nuovo una mano, $N? Prima che mi scoprissero ho raccolto qualche informazione: la Crociata ha due membri importanti che sono la spina dorsale delle sue forze fuori dalla città, Huntsman Radley e Cavalier Durgen. Uccidili e avremo fatto dei passi avanti. Dovrebbero trovarsi lungo l'Hearthglen Pass, fuori dalla città vera e propria.",
  obj = "Uccidi Huntsman Radley e Cavalier Durgen prima di tornare da Kirsta Deepshadow in Western Plaguelands.",
  progress = "Li hai già trovati, $N? Tolti di mezzo quei due, potrò entrare a Hearthglen e guardare più da vicino come sono organizzati. Senza il tuo aiuto non ce la faccio. Ti prego, trovami Radley e Durgen.",
  reward = "Grazie, $N. Mi sei $Gstato:stata; d'aiuto più di quanto sperassi. L'aria di questo posto sembra prosciugarmi la volontà. Sono stanca, e mi accorgo che più resto qui, meno miglioro.$B$BNon so bene come farò a infiltrarmi a Hearthglen e a riferire quanto è forte la presenza della Scarlet Crusade.$B$BMa questa è un'altra faccenda, e prima che tu vada, ecco, prendi questo... come pagamento per il tuo aiuto. Grazie ancora.",
}
T[6024] = {
  title = "La Supplica di Hameya",
  desc = "Uccidimi. Prima che sia troppo tardi.$B$BSono Hameya. In viaggio verso Zul'Mashar, io e i miei fratelli abbiamo mangiato della carne guasta... e siamo cambiati. Siamo infetti.$B$BOra sento le parole del lich che mi spingono ad andare a Zul'Mashar e a contagiare altri del mio popolo. Non riesco a resistere, così ho scritto questa pergamena prima che la volontà mi abbandonasse.$B$BHo sepolto un forziere nella terra, accanto a un carro dietro questa cripta, ma si apre solo con la mia chiave. E la chiave ce l'ho io. Se vuoi il mio tesoro, trovami.$B$BUccidimi. Prima che sia troppo tardi.",
  obj = "Uccidi Infiltrator Hameya. Usa la sua chiave sul Mound of Dirt dietro Undercroft.",
  progress = "Il forziere sepolto qui è chiuso saldamente a chiave.",
  reward = "Il forziere di Hameya è aperto!!",
}
T[6025] = {
  title = "Affari in Sospeso",
  desc = "Cosa? Davvero? Vuoi saperne di più? Ma hai già fatto tanto per me, $N. Non potrei mai chiederti di entrare a Hearthglen al posto mio.$B$BSei $Gsicuro:sicura;, $N? Hearthglen è molto più pericolosa del Valico — non posso proteggerti in nessun modo, e non so nemmeno dirti cosa potresti trovarti davanti.$B$BBeh, se vuoi davvero aiutarmi, entra in città e cerca un punto alto da cui si veda bene. Da lì potrai capire quanti sono e venire a dirmelo. Ma fai attenzione....",
  obj = "Entra a Hearthglen e trova un punto d'osservazione elevato da cui vedere la città e valutare le forze della Scarlet Crusade, poi torna da Kirsta Deepshadow in Western Plaguelands.",
  progress = "È un compito pericoloso, $N. Ti invidio il coraggio.",
  reward = "Ce l'hai fatta, $N! Grazie!$B$BTornerò da Elling... cioè, a Stormwind, appena potrò. Ecco, prendi questa moneta, è il minimo che possa fare per te. Fai onore alla tua gente, $N. Grazie e buona fortuna.",
}
T[6026] = {
  title = "È Chiedere Parecchio",
  desc = "Questa gente dell'Argent Dawn ha ingaggiato il vecchio Smokey per un lavoretto di demolizione. E la mamma di Smokey non ha mica tirato su un fesso: quando sul tavolo si sbattono monete d'oro, i servigi di Smokey sono a disposizione. Questo è il mio motto!$B$BOra, il compenso sarei pronto a dividerlo con te, se sei $Gdisposto:disposta; a scarpinare un po'. Funziona così: io vado a Plaguewood a segnare gli edifici da distruggere, e tu raccogli i componenti per le bombe. Quando hai tutto, ci ritroviamo qui. Affare fatto?",
  obj = "Smokey LaRue vuole che tu gli porti 2 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs e 8 Unstable Triggers.$B$BPer questi oggetti dovrai trovare un fabbro e un ingegnere.",
  progress = "Fidati del vecchio Smokey, $R: la ricompensa ne varrà la pena. Quando c'è da pagare, questa gente dell'Argent Dawn non scherza.",
  reward = "Metà te la posso pagare in anticipo, e metà a lavoro finito.",
}
T[6027] = {
  title = "Book of the Ancients",
  desc = "$N, ti affido la Gem of the Serpent. Sulla Ranazjar Isle, una piccola isola a nord-ovest di qui, c'è la Statua del Serpente: posa la gemma sulla sua mano ed evocherai chi protegge il Book of the Ancients. Quel libro racchiude i segreti dei naga, custoditi da secoli. Portamelo, e sui nostri nemici squamosi scopriremo molte cose!",
  obj = "Prendi il Book of the Ancients e riportalo ad Azore Aldamort presso la torre di Ethel Rethor.",
  progress = "Ah, $N! Che bello rivederti. Hai il Book of the Ancients?",
  reward = "Il Book of the Ancients, perduto da tanto tempo! Farò in modo che questo libro arrivi all'alto consiglio. Oggi hai fatto un buon lavoro, e per questo meriti di essere $Gringraziato:ringraziata;... come si ringrazia un eroe!",
  en_title = "Book of the Ancients",
  en_obj = "Get the Book of the Ancients and return it to Azore Aldamort at the tower in Ethel Rethor.$B",
}
T[6028] = {
  title = "L'Everlook Report",
  desc = "Mi serve una persona responsabile per una faccenda piccola, ma importante lo stesso. Sono qui a rappresentare gli interessi dell'Argent Dawn presso il governo locale di Everlook, e devo far avere un rapporto sui progressi ad Argent Officer Pureheart, a Chillwind Camp: è parecchio lontano da qui, sul margine meridionale delle Western Plaguelands.$B$BSe posso permettermi — sarebbe il modo perfetto per presentarti al mio superiore, e magari lei avrà qualche incarico per te!",
  obj = "Consegna l'Everlook Report ad Argent Officer Pureheart a Chillwind Camp, Western Plaguelands.",
  progress = "Saluti, $C. Finché resti qui a Chillwind Camp, a nome dell'Argent Dawn ti offro sicurezza e riparo. E potrei avere anche del lavoro per te...",
  reward = "Ha mille risorse, Gregor. È da un bel pezzo che ha a che fare con lo Steamwheedle Cartel, e ormai è un esperto nell'\"arte\" delle trattative goblin. Certo, i goblin sono fedeli prima di tutto a chi ha la borsa più piena, ma il valore della diplomazia lo conoscono e lo rispettano anche loro. Se non altro, gli fa tornare i clienti...$B$BComunque sia, l'Argent Dawn riconosce il tuo impegno. Prendi questo, con i nostri ringraziamenti.",
}
T[6029] = {
  title = "L'Everlook Report",
  desc = "Mi serve una persona responsabile per una faccenda piccola, ma importante lo stesso. Sono qui a rappresentare gli interessi dell'Argent Dawn presso il governo locale di Everlook, e devo far avere un rapporto sui progressi ad Argent Officer Garush, al Bulwark: è parecchio lontano da qui, sul margine occidentale delle Western Plaguelands, a est delle Tirisfal Glades.$B$BSe posso permettermi — sarebbe il modo perfetto per presentarti al mio superiore, e magari lui avrà qualche incarico per te!",
  obj = "Consegna l'Everlook Report ad Argent Officer Garush a Bulwark, Western Plaguelands.",
  progress = "Saluti, $C. Finché resti qui al Bulwark, a nome dell'Argent Dawn ti offro sicurezza e riparo. E potrei anche darti l'occasione di combattere per una causa che ne vale la pena!",
  reward = "Ha mille risorse, per essere un umano, Gregor. È da un bel pezzo che ha a che fare con lo Steamwheedle Cartel, e ormai è un esperto nell'\"arte\" delle trattative goblin. Certo, i goblin sono fedeli prima di tutto a chi ha la borsa più piena, ma il valore della diplomazia lo conoscono e lo rispettano anche loro. Se non altro, gli fa tornare i clienti...$B$BComunque sia, l'Argent Dawn riconosce il tuo impegno. Prendi questo, con i nostri ringraziamenti.",
}
T[6030] = {
  title = "Duke Nicholas Zverenhoff",
  desc = "Un medium che vive isolato qui intorno, un certo Umbranse, ha consegnato all'Argent Dawn un vero capolavoro letterario... forse la più grande raccolta di sproloqui che mi sia mai capitato di leggere.$B$BDuke Nicholas Zverenhoff, uno dei capi più rispettati dell'Alba, è un linguista brillante. Potresti portarglielo da parte mia — in cambio di una ricompensa, naturalmente? Cappella della Speranza di Luce — è lì che lo trovi adesso, all'estremità orientale delle Eastern Plaguelands.",
  obj = "Consegna il libro \"Studies in Spirit Speaking\" a Duke Nicholas Zverenhoff a Cappella della Speranza di Luce, Eastern Plaguelands.",
  progress = "Che la Luce ti guidi in questi tempi difficili, $C. Che cosa ti porta qui, in questo faro di speranza in mezzo all'oscurità e alla disperazione?",
  reward = "Questo... quello che mi hai portato è un libro molto speciale. Vorrei poterti dire che qui \"speciale\" vuol dire \"unico e forse illuminante\", ma è ancora tutto da vedere.$B$B\"Ooooooo?\" Chi, sano di mente, si inventerebbe una cosa del genere?$B$BBe', questo Umbranse che dice Gregor l'ho già sentito nominare, quindi un qualche valore ce l'ha. Farò del mio meglio per decifrarlo. Quanto a te... ti prego, prendi questo — per gentile concessione dell'Argent Dawn. E già che sei qui, forse ci sono altre cose in cui puoi darci una mano.",
}
T[6031] = {
  title = "Runecloth",
  desc = "A Timbermaw siamo contenti. Gli stranieri non ci piacciono. Per noi è un bene, ma per i commerci è un male.$B$BPoco tempo fa è venuta a Timbermaw un'amica elfa della notte, cosa rara, e indossava un mantello di runecloth. Il Runecloth fra noi è rara, ma il mantello era così bello che la mia gente vuole che io faccia altri vestiti di runecloth.$B$BMi porterai un po' di runecloth? Se ne porti abbastanza, in cambio ti darò qualcosa.",
  obj = "Porta 30 Runecloth a Meilosh a Timbermaw Hold.",
  progress = "Hai il runecloth? La mia gente non vede l'ora di avere altri oggetti di runecloth!",
  reward = "Ah, hai portato la stoffa. Che bel tessuto!$B$BGrazie, $N, sei $Gun vero amico:una vera amica;. Prendi questo in cambio, ti prego.",
}
T[6032] = {
  title = "Stoffa Sacra",
  desc = "Il popolo di Timbermaw adora toccare il runecloth, ma per noi non è sacra. La mooncloth sì, è sacra.$B$BPortami una piccola scorta di questa stoffa santa e ti insegnerò una tecnica segreta di sartoria.",
  obj = "Porta 2 Mooncloth a Meilosh a Timbermaw Hold.",
  progress = "$N, hai portato la mooncloth?",
  reward = "Ah, molto bene. Con questa mooncloth faremo gli abiti sacri del nostro popolo. Grazie, $N. Adesso ti addestro.",
}
T[6041] = {
  title = "Quando Smokey Canta, Divento $GViolento:Violenta;",
  desc = "Mentre tu raccoglievi i materiali, ho mandato qualcuno dei miei a segnare gli edifici dello Scourge da demolire.$B$BIl piano è questo: ti do dieci candelotti della mia miscela speciale, tu li porti a Plaguewood e li piazzi dentro le strutture dello Scourge che ho fatto marcare per la detonazione.$B$B<Smokey schiocca le dita.>$B$BBing! Facile così.",
  obj = "Va' a Plaguewood, a nord-ovest di Light's Hope. Distruggi 8 Strutture dello Scourge usando la Smokey's Special Compound presso il Mark of Detonation piazzato dentro ogni edificio. Smokey ha fatto marcare gli Ziggurat e gli Slaughterhouses.$B$BUna volta piazzata la bomba, esci dall'edificio e ammira il tuo lavoro.$B$BA proposito, la Smokey's Special Compound è piuttosto... instabile.",
  progress = "Mi è avanzato un po' di materiale per qualche altro candelotto di miscela speciale. Se te ne servono altri, basta dirlo al vecchio Smokey.",
  reward = "Sei molto più $Gscuro:scura; di come ti ricordavo. Hai proprio quell'aria; quella di chi dice 'Sono $Gstato carbonizzato:stata carbonizzata; da una bomba ad alto potenziale.'$B$B<Smokey ride.>$B$BComunque! Ecco la tua parte del bottino, con qualcosina in più per lenire le bruciature.",
}
T[6042] = {
  title = "Le Piccole Seccature della Non Vita",
  desc = "Non puoi fare due passi fuori da questa fattoria senza imbatterti in uno di quegli odiosi pipistrelli. Voglio poter portare fuori i segugi a massacrare lo Scourge senza che quei maledetti, sudici pipistrelli mi aggrediscano. Ovviamente ho di meglio da fare che ammazzare pipistrelli senza pensare, un giorno dopo l'altro. Tu, invece, no.$B$BCosa? Il tuo addestramento? Questo è il tuo addestramento! Ora levati dalla mia vista e torna solo quando avrai ucciso un bel numero di quei demoni alati. Non deludermi.",
  obj = "Uccidi 20 Noxious Plaguebats e 10 Monstrous Plaguebats. Torna da Nathanos Blightcaller quando hai finito.",
  progress = "Poteva andarti peggio: avrei potuto farti raccogliere guano di pipistrello.$B$B<Nathanos ti fissa, pensieroso.>$B$BMmh... Ehi! Aspetta un attimo. Dove vai?",
  reward = "Incredibile quello che si riesce a ottenere con un po' di rabbia e di furia.",
}
T[6061] = {
  title = "Addomesticare la Bestia",
  desc = "Per noi tauren è importante seguire le tradizioni degli antenati e combattere creature possenti: sconfiggendole possiamo assorbirne gli spiriti, e così ci avviciniamo alla Madre Terra.$B$BAllo stesso modo, addomesticare una bestia che combatta al nostro fianco ci aiuta a diventare tutt'uno con la natura intorno a noi. Prima o poi imparerai ad addomesticare quella che vorrai, ma ogni cosa richiede pratica, e hai molto da imparare. Per cominciare, prendi questo taming rod: devi domare un adult plainstrider.",
  obj = "Usa il Taming Rod per addomesticare un Adult Plainstrider. Fai pratica con le tue abilità, poi riporta il Taming Rod a Yaw Sharpmane a Bloodhoof Village.",
  progress = "Fa' pratica con le tue abilità, $N, e addomestica l'adult plainstrider.",
  reward = "La Madre Terra mi ha mandato dei segni: hai fatto bene.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.",
}
T[6062] = {
  title = "Addomesticare la Bestia",
  desc = "Imporre la propria autorità sulla natura è un'abilità ammirevole. Da $Gcacciatore:cacciatrice;, devi impegnarti a imparare come usare la forza e la potenza di qualunque creatura sceglierai.$B$BPrendere il controllo di un animale non è un'impresa facile, e devi affrontarla con molta determinazione.$B$BCome primo incarico, prendi questo taming rod e usalo su un dire mottled boar per addomesticarlo. Ne troverai proprio vicino a Razor Hill. Combatti con il cinghiale al fianco per mettere alla prova le tue capacità, poi torna da me.",
  obj = "Usa il Taming Rod per addomesticare un Dire Mottled Boar. Metti alla prova le tue capacità, poi riporta il Taming Rod a Thotar a Razor Hill.",
  progress = "Buona fortuna, giovane $Gcacciatore:cacciatrice;.",
  reward = "Te la sei cavata bene, $N. Credo che tu sia $Gpronto:pronta; per il prossimo compito.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill.",
}
T[6063] = {
  title = "Addomesticare la Bestia",
  desc = "Come $Gcacciatore:cacciatrice;, non devi mai dimenticare la responsabilità che hai tra le mani. La natura non è una forza che si possa piegare ai nostri desideri; va rispettata e riconosciuta come qualcosa che supera la tua stessa esistenza.$B$B$N, prima di ottenere la capacità di addomesticare un animale che ti faccia da compagno, devi dimostrare di aver compreso tutto questo.$B$BIl tuo primo compito è prendere questo taming rod. Ti servirà per domare un webwood lurker. Ammansiscilo ed esercita le tue abilità di $Gcacciatore:cacciatrice;.",
  obj = "Usa il Taming Rod per addomesticare un Webwood Lurker. Esercita le tue abilità, poi riporta il Taming Rod a Dazalar a Dolanaar.",
  progress = "Imparerai, $N, e un giorno sarai $Gun grande cacciatore:una grande cacciatrice;.",
  reward = "Eccellente, $N! Impari davvero in fretta.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.",
}
T[6064] = {
  title = "Addomesticare la Bestia",
  desc = "Ciao, $Gragazzo:ragazza;! Allora, vuoi sapere come si fa ad avere un famiglio tutto tuo?$B$BBeh, cominciamo. Per chi va a caccia non c'è niente di più importante dell'equipaggiamento, ma il mio nuovo Shrapnel Blaster lo lasciamo per un'altra volta. Per ora pensiamo a una cosa che di sicuro ti interessa parecchio: un famiglio!$B$BIl modo migliore per imparare è provare come compagne creature diverse e vedere quale fa per te. Quindi trova un large crag boar e addomesticalo con il taming rod.",
  obj = "Addomestica un Large Crag Boar con il Taming Rod. Fai pratica, poi riporta il Taming Rod a Grif Wildheart a Kharanos.",
  progress = "Non preoccuparti, $Gragazzo:ragazza;! Ne proverai un po' prima di doverne scegliere uno solo.",
  reward = "Lo so, lo so: ti stai chiedendo cosa c'è dopo, vero?!",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.",
}
T[6065] = {
  title = "Il Sentiero del Cacciatore",
  desc = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza $Gesperto:esperta; da saper gestire una bestia e farne la tua compagna, addestrandola.$B$BDevi andare da Yaw Sharpmane, a Bloodhoof Village: lui può mostrarti come guadagnarti un famiglio tutto tuo.",
  obj = "Parla con Yaw Sharpmane a Bloodhoof Village.",
  reward = "Sì, direi proprio che sei $Gpronto:pronta;...",
  en_title = "The Hunter's Path",
  en_obj = "Speak with Yaw Sharpmane in Bloodhoof Village.",
}
