T[6074] = {
  title = "La Via del Cacciatore",
  desc = "Ciao, giovane $Gcacciatore:cacciatrice;. Mi sembri abbastanza in gamba da saper gestire una bestia e addestrarla a farti da compagna.$B$BDevi andare da Grif Wildheart, a Kharanos: è lui che può spiegarti come guadagnarti un famiglio tutto tuo.",
  obj = "Parla con Grif Wildheart a Kharanos.",
  reward = "Sì, direi proprio che anche tu sei $Gpronto:pronta;....",
  en_title = "The Hunter's Path",
  en_obj = "Speak with Grif Wildheart in Kharanos.",
}
T[6075] = {
  title = "La Via del Cacciatore",
  desc = "Ciao, giovane $Gcacciatore:cacciatrice;. Mi sembri abbastanza in gamba da saper gestire una bestia e addestrarla a farti da compagna.$B$BDevi andare da Grif Wildheart, a Kharanos: è lui che può spiegarti come guadagnarti un famiglio tutto tuo.",
