T[6081] = {
  title = "Addestrare la Bestia",
  desc = "Adesso hai il potere di addomesticare un famiglio, ma devi anche acquisire le capacità per addestrarlo.$B$BVa' a Orgrimmar: lì devi parlare con Ormak Grimshot, uno dei nostri cacciatori più venerati. Sarà lui a darti la capacità di addestrare il tuo nuovo famiglio. Lo troverai vicino all'Hall of the Brave.$B$BBuona fortuna, $N.",
  obj = "Parla con Ormak Grimshot a Orgrimmar.",
  reward = "$GUn giovane cacciatore:Una giovane cacciatrice;, vedo. Sì, ti concederò le capacità che ti servono per addestrare e guidare il famiglio. Potrai insegnargli nuove abilità, ma non solo: adesso potrai anche dargli da mangiare e rianimarlo, se dovesse cadere in battaglia.$B$BOra va', $Gcacciatore:cacciatrice;. Torneremo a parlarci più avanti.",
  en_title = "Training the Beast",
  en_obj = "Speak with Ormak Grimshot in Orgrimmar.",
}
T[6082] = {
  title = "Addomesticare la Bestia",
  desc = "L'ultima creatura da addomesticare è quella a cui dovresti cercare di somigliare: l'armored scorpid. Colpisce rapido e sicuro; controllare una forza così è il tuo destino di $Gcacciatore:cacciatrice;.$B$BAl tuo ritorno ti concederò le capacità che ti servono per addomesticare un animale a tua scelta, e quella creatura sarà ai tuoi ordini. Sotto il tuo controllo, il famiglio farà esperienza insieme a te. Ti mostrerò anche come richiamarlo e congedarlo quando vuoi.",
  obj = "Usa il Taming Rod per addomesticare un Armored Scorpid. Metti alla prova le tue capacità, poi torna da Thotar a Razor Hill.",
  progress = "Lo scorpide: sei $Griuscito:riuscita; ad addomesticarlo?",
  reward = "Ti ho insegnato tutto quello che potevo, $N. Ora è il momento di mettere a frutto quanto hai imparato qui e di scegliere un famiglio tutto tuo.$B$BEcco a te, $N. Adesso ti darò il potere di addomesticare una bestia, di richiamarla e di congedarla come meglio credi. Usa con orgoglio le tue nuove capacità: te le sei guadagnate.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill.",
}
T[6083] = {
  title = "Addomesticare la Bestia",
  desc = "Che un famiglio ti dia un vantaggio sui rivali lo sanno tutti, $N. Quando prendi il controllo di un'altra creatura, aggiungi forza alla tua. Il famiglio deve diventare un'estensione di $Gte stesso:te stessa;.$B$BPer il prossimo compito dovrai lasciare la terraferma: la creatura successiva la troverai nelle acque al largo della costa. Di fronte a Sen'jin Village, vicino alle Echo Isles, cerca un granchio vivace chiamato surf crawler. Addomesticalo con il taming rod, poi metti alla prova le tue capacità.",
  obj = "Usa il Taming Rod per addomesticare un Surf Crawler. Metti alla prova le tue capacità, poi riporta il Taming Rod a Thotar a Razor Hill.",
  progress = "Devi fare pratica, se vuoi le capacità per controllare bene il famiglio. Hai addomesticato un surf crawler?",
  reward = "Te la sei cavata bene, $N. Impari in fretta.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill.",
}
T[6084] = {
  title = "Addomesticare la Bestia",
  desc = "Quei crag boars sono piuttosto massicci; magari ti piacerebbe qualcosa di un po' più aggraziato? E allora ho proprio quel che fa per te. A sud e a est di qui troverai dei grossi gatti bianchi che chiamano snow leopards. Sono come un fucile intagliato con eleganza: dietro lo splendido aspetto si nasconde un combattente potente, capace di infliggere danni enormi. Vedrai che sono molto più agili e veloci del cinghiale che hai addomesticato.$B$BPrendi questo taming rod e vedi come ti trovi con lo snow leopard.",
  obj = "Addomestica uno Snow Leopard con il Taming Rod. Fai pratica, poi torna da Grif Wildheart a Kharanos.",
  progress = "Che ne dici dello snow leopard, $N?",
  reward = "Quando riterrò che hai imparato abbastanza, ti lascerò scegliere qualunque famiglio ti piaccia.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos.",
}
T[6085] = {
  title = "Addomesticare la Bestia",
  desc = "Magari ti piacerebbe una creatura che abbia poco più della forza bruta. L'ice claw bear è un ottimo compagno per $Gun cacciatore:una cacciatrice; alle prime armi come te, e lo trovi a est di Kharanos. Ecco il taming rod: prova questo animale come famiglio e vedi se ti piace!$B$BQuando torni, ti darò le abilità che ti servono per addomesticare un animale a tua scelta: affronterà le tue stesse sfide e farà esperienza insieme a te. Ti mostrerò anche come chiamarlo e congedarlo quando vuoi.",
  obj = "Addomestica un Ice Claw Bear con il Taming Rod. Fai pratica, poi riporta il Taming Rod a Grif Wildheart a Kharanos.",
  progress = "L'hai già addomesticato, l'ice claw bear?",
  reward = "Ecco qua, $N. Adesso ti darò il potere di addomesticare una bestia, e anche di chiamarla e congedarla quando vuoi.$B$BTrovati un famiglio buono e leale, e buona caccia!",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.",
}
T[6086] = {
  title = "Addestrare la Bestia",
  desc = "$N, adesso hai il potere di addomesticare un famiglio, ma devi anche imparare ad addestrarlo.$B$BVa' a Ironforge e cerca l'Hall of Arms: lì devi parlare con Belia Thundergranite, una delle nostre addestratrici di animali più stimate. Ti darà il potere di addestrare il tuo nuovo famiglio, quindi muoviti, $Gragazzo:ragazza;!$B$BBelia è una tipa alla mano: non dovresti avere problemi a farti approvare da lei. Buona fortuna, $N.",
  obj = "Parla con Belia Thundergranite a Ironforge.",
  reward = "Una nuova recluta, eh? Vedo che sei sulla buona strada per diventare $Gun:una; grande $C.$B$BSì, posso darti le capacità che ti servono per addestrare e guidare il tuo famiglio. Oltre a insegnargli nuove abilità, adesso potrai anche nutrirlo, e rianimarlo se dovesse cadere in battaglia.$B$BRicorda: il segreto per tirare fuori il meglio dal tuo nuovo famiglio è rispettarlo e trattarlo bene. In cambio, sarà il tuo amico più fedele.",
  en_title = "Training the Beast",
  en_obj = "Speak with Belia Thundergranite in Ironforge.",
}
T[6087] = {
  title = "Addomesticare la Bestia",
  desc = "$GCacciatore:Cacciatrice;, hai uno spirito focoso, pronto ad affrontare la prossima sfida.$B$BOra dovrai conquistarti la compagnia di un lupo chiamato prairie stalker. È una creatura veloce e senza paura: se la prendi come famiglio, queste qualità dovranno diventare anche tue.$B$BIn battaglia imparerai a fare squadra con il tuo famiglio: alla fine dovrete agire come una cosa sola, muscolo a muscolo.$B$BEcco il taming rod, $N. Addomestica un prairie stalker e fa' pratica con le tue abilità.",
  obj = "Usa il Taming Rod per addomesticare un Prairie Stalker. Fai pratica con le tue abilità, poi riporta il Taming Rod a Yaw Sharpmane a Bloodhoof Village.",
  progress = "Hai trovato un prairie stalker?",
  reward = "Sì... La Madre Terra ti crede $Gpronto:pronta; per la prossima lezione.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.",
}
T[6088] = {
  title = "Addomesticare la Bestia",
  desc = "Per l'ultimo compito dovrai addomesticare una creatura che vive nel cielo. Lo swoop è un avversario difficile, ma se diventerà tuo alleato i suoi attacchi affilati e la sua presenza minacciosa saranno tuoi.$B$BAl tuo ritorno, per volere della Madre Terra, ti concederò le abilità che ti serviranno per addomesticare l'animale che vorrai e farne il tuo compagno: affronterà le tue stesse sfide e farà esperienza al tuo fianco. Ti mostrerò anche come richiamarlo e congedarlo quando vorrai.",
  obj = "Usa il Taming Rod per addomesticare uno Swoop. Fai pratica con le tue abilità, poi riporta il Taming Rod a Yaw Sharpmane a Bloodhoof Village.",
  progress = "Presto sarai $Gpronto:pronta;, $N.",
  reward = "Hai imparato tutto quello che potevo insegnarti, $N. Le benedizioni della Madre Terra ti guidino nella scelta del famiglio.$B$BEcco a te, $N: ora ti darò il potere di addomesticare una bestia, e anche di richiamarla e congedarla come meglio credi. Usa con orgoglio le tue nuove abilità, e onora la Madre Terra.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.",
}
T[6089] = {
  title = "Addestrare la Bestia",
  desc = "Ora hai il potere di addomesticare un famiglio, ma devi anche apprendere le abilità per addestrarlo.$B$BVa' a Thunder Bluff: lì dovrai parlare con Holt Thunderhorn, uno dei nostri cacciatori più venerati. Se ti riterrà $Gdegno:degna;, ti darà la capacità di addestrare il tuo nuovo famiglio.$B$BHolt ha sconfitto le bestie più potenti e temute di Azeroth, e comanda molte creature forti, tutte sue. È molto legato alla Madre Terra, e da lui hai tanto da imparare. Buona fortuna, $N.",
  obj = "Parla con Holt Thunderhorn su Hunter Rise a Thunder Bluff.",
  reward = "$GUn giovane cacciatore:Una giovane cacciatrice;, vedo. Sì, posso concederti le abilità che ti servono per addestrare e guidare il tuo famiglio. D'ora in poi non solo potrai insegnargli nuove abilità, ma potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.$B$BOra va'. La Madre Terra ti guidi sul tuo cammino. Ci rivedremo più avanti.",
  en_title = "Training the Beast",
  en_obj = "Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff.",
}
T[6101] = {
  title = "Addomesticare la Bestia",
  desc = "La natura, $N, è varia, e su questo si può sempre contare. È prevedibile nel suo non restare mai uguale; cambia di continuo.$B$BI compiti che ti affido ti aiuteranno a vedere e ad apprezzare le enormi diversità tra le creature che potresti scegliere come compagne.$B$BPrendi questo taming rod e usalo per domare un nightsaber stalker, che troverai a sud. Esercita le tue abilità di $Gcacciatore:cacciatrice;. Così comincerai a cogliere somiglianze e differenze nella natura.",
  obj = "Usa il Taming Rod per addomesticare un Nightsaber Stalker. Esercita le tue abilità, poi riporta il Taming Rod a Dazalar a Dolanaar.",
  progress = "Comprendere l'equilibrio tra la natura e se stessi è il modo di vivere di ogni elfo della notte.",
  reward = "Vedo il tuo impegno, e mi accorgo che hai compreso ciò che ti ho insegnato, $N.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.",
}
T[6102] = {
  title = "Addomesticare la Bestia",
  desc = "Hai addomesticato due creature che abitano la terra, ora devi domarne una che solca i cieli. Con il taming rod ammansisci uno strigid screecher, che troverai a ovest di qui. Esercita le tue abilità con questo possente gufo al tuo fianco.$B$BAl tuo ritorno ti concederò le capacità necessarie per addomesticare un animale a tua scelta e farne il tuo compagno; questa creatura affronterà le tue stesse sfide e acquisirà esperienza insieme a te. Ti mostrerò anche come richiamarla e congedarla a tuo piacimento.",
  obj = "Usa il Taming Rod per addomesticare uno Strigid Screecher. Esercita le tue abilità, poi riporta il Taming Rod a Dazalar a Dolanaar.",
  progress = "Sono fiero dei tuoi successi, $N. Hai portato a termine l'ultimo compito che ti ho affidato?",
  reward = "Hai imparato tutto ciò che posso insegnarti, $N. Permettimi di darti un ultimo consiglio: scegli con giudizio il tuo primo famiglio. Preferirai una creatura della terra, dell'acqua o del cielo? Qualunque sia, ti resterà di sicuro accanto per parecchio tempo.$B$BEcco, $N. Ora ti concederò il potere di addomesticare una bestia, e di richiamarla e congedarla come meglio credi. Usa le tue nuove abilità con orgoglio; te le sei guadagnate.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.",
}
T[6103] = {
  title = "Addestrare la Bestia",
  desc = "Ora hai il potere di addomesticare un famiglio, ma devi anche acquisire le abilità per addestrarlo.$B$BRecati a Darnassus. Lì dovrai parlare con Jocaste, tra i nostri cacciatori più venerati. Ti darà la capacità di addestrare il tuo nuovo compagno, quindi affrettati.$B$BAnche se Jocaste può sembrare severa, è sempre lieta di vedere $Gun altro cacciatore:un'altra cacciatrice; salire di grado. Trattala con rispetto e ricambierà. Buona fortuna, $N.",
  obj = "Parla con Jocaste in Cenarion Enclave, a Darnassus.",
  reward = "$GUn cacciatore alle prime armi:Una cacciatrice alle prime armi;, vedo. Sì, posso concederti le abilità necessarie per addestrare e guidare il tuo famiglio. Non solo gli insegnerai nuove tecniche: d'ora in poi potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.$B$BRicorda, $N, rispetta sempre l'equilibrio e vivi con stupore reverente davanti alla natura che ti circonda. Ora va'. Torneremo a parlarci più avanti.",
  en_title = "Training the Beast",
  en_obj = "Speak to Jocaste in the Cenarion Enclave, in Darnassus.",
}
T[6121] = {
  title = "Nuove Lezioni",
  desc = "Ora sei $Gpronto:pronta; a conoscere i veleni e il potere che noi druidi abbiamo su di essi, $N. Cenarius ci ha concesso la facoltà di purificare anche il più immondo dei veleni con un semplice incantesimo. Non è un dono da prendere alla leggera... e perché tu impari bene questa lezione, dovrai affrontare gli effetti degli avvelenamenti come farebbe un profano.$B$BRaggiungi Moonglade e parla con Dendrite Starblaze; ti aspetta per cominciare.",
  obj = "Raggiungi Moonglade e parla con Dendrite Starblaze nel villaggio di Nighthaven.",
  reward = "Salute, giovane $Gdruido:druida;, sono lieto di vederti $Gpronto:pronta; e $Gdesideroso:desiderosa; di imparare a curare i veleni.$B$BIn passato la maggior parte dei druidi affrontava prove allestite apposta, ma per te non sarà così. C'è stata un'ondata di avvelenamenti tra gli animali di Auberdine, e il villaggio non è riuscito a porvi rimedio. Per questo hanno chiesto aiuto a Moonglade tramite un rappresentante, e noi ti mandiamo laggiù a soccorrerli. Non è un'esercitazione — farai un lavoro vero. Tienilo a mente.",
  en_title = "Lessons Anew",
  en_obj = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven.",
}
T[6122] = {
  title = "La Fonte Principale",
  desc = "Le Cliffspring Falls di Darkshore sono la principale fonte d'acqua potabile della regione, e ora sospetto che siano anche la principale fonte del veleno che sta colpendo la fauna locale — in particolare i caprioli. Usa questo campionatore per prelevare un po' d'acqua dall'imboccatura della grotta; fai attenzione, perché in una caverna vicino alle cascate ora vivono dei naga pericolosi.$B$BUna volta pieno, consegnalo ad Alanndarian Nightsong ad Auberdine. È stata lei a chiedere il nostro aiuto, e insieme lavorerete per curare questo male.",
  obj = "Usa l'Empty Cliffspring Falls Sampler per prelevare un campione d'acqua dall'imboccatura della grotta vicino alle cascate.$B$BConsegna il Filled Cliffspring Falls Sampler ad Alanndarian Nightsong ad Auberdine, Darkshore.",
  progress = "Sei tu $Gil:la; $Ginviato:inviata; del Cenarion Circle di Moonglade? Magnifico! Abbiamo una vera crisi fra le mani con quei poveri caprioli, e ogni aiuto è ben accetto.$B$BHai il campione d'acqua di cui mi ha parlato Dendrite Starblaze? Mi ha avvisata che ne avresti prelevato uno, per trovare insieme una cura...",
  reward = "Per Elune, quest'acqua è disgustosa! Non c'è da stupirsi che i caprioli stiano male.$B$BQualcosa sta inquinando l'acqua, e così corrompe l'intera falda di Darkshore. Si sono visti caprioli malati in tutta la zona, e non solo lungo il fiume. Anche se con ogni probabilità è questa la causa principale della malattia che si sta diffondendo, c'è dell'altro in gioco.$B$BChe tu ci creda o no, proprio quest'acqua ci aiuterà a preparare una cura. Mentre la studio, mi servono alcuni ingredienti per mettere a punto il rimedio...",
  en_title = "The Principal Source",
  en_obj = "Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.$B$BDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore.",
}
T[6123] = {
  title = "Raccogliere la Cura",
  desc = "L'acqua farà da base per l'unguento curativo che preparerò per i caprioli. Per le proprietà medicinali mi serve un po' di earthroot. Gli erboristi sanno come trovarla: se per sfortuna non sei del mestiere, dovrai cercare qualcuno che lo sia e che ci dia una mano.$B$BInfine, per renderlo più potente, ho bisogno di un po' di lunar fungus. Trovare i ciuffi di funghi lunari è abbastanza facile; ce ne sono ovunque nelle grotte appena a est di qui. In quelle caverne vivono i Moonkin, che ultimamente sono irritabili, quindi fai attenzione.",
  obj = "Porta 5 Earthroot e 12 Lunar Funguses ad Alanndarian Nightsong ad Auberdine, così che possa preparare un unguento curativo.",
  progress = "Hai i reagenti che mi servono per preparare l'unguento? I caprioli non migliorano da soli, quindi meglio sbrigarsi ad aiutarli!",
  reward = "Ottimo, $N, tanto che dovrebbe bastare per qualche dose abbondante d'unguento — almeno quanto serve per cominciare a fare la differenza.$B$BPreparare una cura per i veleni a volte può essere davvero difficile, perché spesso ciascuno ha bisogno di un antidoto ben preciso. Immagina di poter neutralizzare un veleno a piacimento, senza doverti preoccupare degli ingredienti esatti dell'antidoto!$B$BOra lascia che mi metta al lavoro!",
  en_title = "Gathering the Cure",
  en_obj = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve.",
}
T[6124] = {
  title = "Curare i Malati",
  desc = "Con i reagenti che mi hai portato ho preparato abbastanza unguento per dieci dosi, $N. Mentre il villaggio e io proviamo a farne dell'altro, vorrei che ci aiutassi a portarci avanti. In tutta Darkshore ci sono caprioli che stanno male: applica l'unguento a ogni sickly deer e guariscilo.$B$BDendrite Starblaze di Moonglade vorrà parlarti quando avrai finito, ne sono certa. Per favore, porta la gratitudine di Auberdine al Cenarion Circle di laggiù... e lascia che ti ringrazi di persona per l'aiuto che ci hai dato!",
  obj = "Usa il Curative Animal Salve su 10 Sickly Deer sparsi per tutta Darkshore; così dovresti curarli. Sickly Deer sono stati segnalati a partire dalla zona a sud del Cliffspring River, a nord di Auberdine, fino alla parte meridionale di Darkshore, al confine con Ashenvale.",
  progress = "Hai portato a termine ciò che ti ha chiesto Alanndarian Nightsong di Auberdine? Finché non l'avrai fatto, il lavoro non sarà concluso.",
  reward = "Hai fatto bene a prenderti cura di ogni sickly deer di Darkshore: questi animali sono vittime inconsapevoli di una contaminazione e di una corruzione più vaste, che si stanno diffondendo in tutta la terra. A Darnassus c'è chi sceglie di riconoscere questa minaccia... e c'è chi ignora i segnali sempre più evidenti. Spero che tu non sia tra quelli che chiudono gli occhi davanti a ciò che hanno sotto il naso, $N.$B$BIn ogni caso, hai dimostrato il tuo valore come $Gamico:amica; della natura e del Circolo — prendi questo, in segno di riconoscimento.",
  en_title = "Curing the Sick",
  en_obj = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them.  Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins.",
}
T[6125] = {
  title = "Potere sul Veleno",
  desc = "Hai imparato cosa significa curare un avvelenamento senza l'aiuto di poteri spirituali. Ora che stai per fare tuo questo nuovo potere sul veleno, ricorda quanto devono sopportare gli altri per combattere gli avvelenamenti.$B$BAdesso dovresti tornare da Mathrengyl Bearwalker a Darnassus, $N. Senza dubbio ha un incantesimo molto importante da insegnarti, ora che hai compreso la lezione che ti è stata impartita.$B$BAddio, giovane $Gdruido:druida;. Ci rivedremo.",
  obj = "Torna da Mathrengyl Bearwalker in Cenarion Enclave, Darnassus.",
  reward = "$GBentornato:Bentornata; — ho seguito i tuoi progressi in questa lezione da quando sei $Gpartito:partita;, e devo ammettere che la situazione di Auberdine mi ha sorpreso. La faccenda merita ulteriori indagini, perché introdurre simili veleni nell'ambiente turba profondamente l'equilibrio.$B$BHai affrontato la prova con compostezza, anche sotto pressione. Per questo non c'è ricompensa migliore, per te, di un potere permanente sul veleno. Usalo bene, $N... usalo bene.",
  en_title = "Power over Poison",
  en_obj = "Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.",
}
T[6126] = {
  title = "Nuove Lezioni",
  desc = "$N, ora sei $Gpronto:pronta; a imparare cosa sono i veleni e quale potere abbiamo su di essi noi druidi. Cenarius ci ha concesso di purificare con una semplice formula anche i veleni più immondi. È un dono che non va preso alla leggera... e per essere certo che tu impari questa lezione, affronterai gli effetti degli avvelenamenti come li affronterebbe una persona comune.$B$BRaggiungi Moonglade e parla con Dendrite Starblaze; ti aspetta per cominciare la lezione.",
  obj = "Raggiungi Moonglade e parla con Dendrite Starblaze nel villaggio di Nighthaven.",
  reward = "Salve, $Ggiovane druido:giovane druida;, sono lieto di vederti $Gpronto:pronta; e $Gdesideroso:desiderosa; di imparare a curare i veleni.$B$BUn tempo quasi tutti i druidi affrontavano prove già stabilite, ma per te non sarà così. Al Crossroads, nella Barrens, gli animali sono stati colpiti da un'ondata di avvelenamenti, e lì non riescono a tenerla sotto controllo. Qualcuno del posto ha chiesto aiuto a Moonglade, e noi ti mandiamo ad aiutarli. Non è un'esercitazione — farai un lavoro vero. Tienilo a mente.",
  en_title = "Lessons Anew",
  en_obj = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven.",
}
T[6127] = {
  title = "La Fonte Principale",
  desc = "Il Dreadmist Peak, a nordovest del Crossroads, è con ogni probabilità la fonte principale del veleno che si sta diffondendo. Sulle sue alte cime ci sono pozze d'acqua che influenzano il clima. Sospetto che ora quell'acqua sia contaminata dalla Burning Blade, che adora i demoni.$B$BCon questo campione preleva l'acqua dalla pozza in cima al picco e, quando sarà pieno, consegnalo a Tonga Runetotem al Crossroads. È stato lui a chiederci aiuto, e lavorerai al suo fianco per affrontare questo male.",
  obj = "Usa l'Empty Dreadmist Peak Sampler per prelevare un campione d'acqua da una pozza in cima al picco.$B$BConsegna il Filled Dreadmist Peak Sampler a Tonga Runetotem al Crossroads, Barrens.",
  progress = "Ti manda il Cenarion Circle di Moonglade, vero? Che fortuna per noi! Non riusciamo a riportare in equilibrio le sickly gazelles che vagano nel nord della Barrens; qualsiasi aiuto è il benvenuto.$B$BHai portato il campione d'acqua di cui mi ha parlato Dendrite Starblaze? Mi ha avvisato che ne avresti prelevato uno, così da poter lavorare insieme a una cura...",
  reward = "Per i miei antenati, quest'acqua è disgustosa! Per forza le gazzelle sono malate.$B$BQualcosa sta inquinando l'acqua, e così comincia a devastare l'ecosistema del nord della Barrens. Si sono viste gazzelle malate dappertutto a nord della strada est-ovest che passa di qui. Con ogni probabilità è quest'acqua la fonte principale della malattia che si sta diffondendo, ma sotto c'è dell'altro.$B$BChe tu ci creda o no, quest'acqua ci aiuterà a ottenere una cura. Mentre la studio, mi servono alcune cose per prepararla...",
  en_title = "The Principal Source",
  en_obj = "Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.$B$BDeliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens.",
}
T[6128] = {
  title = "Raccogliere la Cura",
  desc = "L'acqua sarà la base del balsamo curativo che preparerò per le gazzelle. Perché guarisca, mi serve un po' di earthroot. Gli erboristi sanno dove trovarla, quindi, se non hai questa abilità, dovrai cercarne uno che ci aiuti.$B$BInfine, perché sia potente, mi servono kodo horns — non basteranno semplici schegge e frammenti. Nella parte settentrionale della Barrens vagano kodo alla tua portata; abbattine qualcuno per il bene superiore dell'equilibrio, $N, e portami le corna.",
  obj = "Porta 5 Earthroot e 5 Kodo Horns a Tonga Runetotem al Crossroads, perché possa preparare un balsamo curativo.",
  progress = "Hai i reagenti che mi servono per il balsamo? Le gazzelle non migliorano da sole, quindi, se vogliamo salvarle, faremmo meglio a non perdere tempo!",
  reward = "Ottimo, $N, ce ne dovrebbe essere abbastanza per parecchie dosi di balsamo — almeno quante servono per cominciare a fare la differenza.$B$BA volte preparare una cura per i veleni è piuttosto difficile, perché spesso ciascuno vuole un antidoto ben preciso. Immagina di poter curare un veleno quando vuoi, senza preoccuparti degli ingredienti esatti dell'antidoto!$B$BOra mi metto al lavoro!",
  en_title = "Gathering the Cure",
  en_obj = "Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve.",
}
T[6129] = {
  title = "Curare i Malati",
  desc = "Sono riuscito a preparare dieci dosi di balsamo, $N. Mentre cerco con le autorità locali di farne ancora, vorrei che ci aiutassi a portarci avanti. Le sickly gazelles sono sparse in tutto il nord della Barrens; usa il balsamo per guarirle dal malessere.$B$BDendrite Starblaze, a Moonglade, vorrà parlarti quando avrai finito, ne sono certo. Ti prego, porta la nostra gratitudine al Cenarion Circle... e lascia che ti ringrazi di persona per l'aiuto che ci hai dato!",
  obj = "Usa il Curative Animal Salve su 10 Sickly Gazelles che si trovano in tutta la parte settentrionale di Barrens; così dovrebbero guarire. Le Sickly Gazelles sono state segnalate a nord della strada est-ovest che attraversa il Crossroads.",
  progress = "Hai fatto quello che ti ha chiesto Tonga Runetotem al Crossroads? Finché non l'avrai fatto, il tuo lavoro non è finito.",
  reward = "Hai fatto un buon lavoro prendendoti cura delle sickly gazelles della Barrens; sono vittime ignare di una contaminazione e di una corruzione più grandi, che si stanno diffondendo in tutta la terra. Voi tauren siete molto desiderosi di comprendere le vie di Cenarius; tu, come i tuoi anziani a Thunder Bluff, stai dimostrando che il bisogno di equilibrio supera le barriere artificiali fra le razze.$B$B$N, hai dimostrato quanto vali come $Gamico:amica; della natura e del Circolo — prendi questo come simbolo.",
  en_title = "Curing the Sick",
  en_obj = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them.  Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads.",
}
T[6130] = {
  title = "Potere sul Veleno",
  desc = "Hai imparato cosa vuol dire curare il veleno senza aiuto spirituale. Presto avrai un nuovo potere sul veleno: ricorda ciò che gli altri devono sopportare per combatterne i mali.$B$BOra dovresti tornare da Turak Runetotem a Thunder Bluff, $N. Di certo ha un incantesimo molto importante da insegnarti, adesso che $Gl'allievo:l'allieva; ha compreso la lezione che $Ggli:le; è stata impartita.$B$BAddio, $Ggiovane druido:giovane druida;. Ci parleremo ancora.",
  obj = "Torna da Turak Runetotem a Elder Rise, Thunder Bluff.",
  reward = "$GBentornato:Bentornata; — ho seguito i tuoi progressi in questa lezione da quando sei $Gpartito:partita;, e devo ammettere che quando ho saputo della situazione al Crossroads sono rimasto sorpreso. La cosa va indagata più a fondo, perché spargere simili veleni nell'ambiente turba molto l'equilibrio.$B$BSotto pressione hai agito con compostezza. Per questo non trovo ricompensa migliore di un potere permanente sul veleno. Usalo bene, $N... usalo bene.",
  en_title = "Power over Poison",
  en_obj = "Return to Turak Runetotem on the Elder Rise, Thunder Bluff.",
}
T[6131] = {
  title = "Timbermaw Ally",
  desc = "I Timbermaw sono l'unica tribù di furbolg sfuggita alla corruzione. Eppure ormai molte altre razze uccidono i furbolg alla cieca, senza curarsi di capire chi sia amico e chi nemico. Ecco perché i furbolg Timbermaw si fidano di pochissimi.$B$BVuoi dimostrare quanto vali? Ricaccia indietro la tribù corrotta Deadwood di Felwood e un giorno potremmo considerarti $Gun alleato:un'alleata;. La prima tribù Deadwood — guerrieri, ricognitori e giardinieri — la trovi a ovest di qui.",
  obj = "Grazle vuole che tu dimostri il tuo valore uccidendo 5 Deadwood Warriors, 5 Deadwood Pathfinders e 5 Deadwood Gardeners.",
  progress = "Continua così, $N. La nostra fiducia, se la vuoi, devi guadagnartela dimostrandoci quanto vali.",
  reward = "Quello che è successo in passato ci fa soffrire molto. Grazie di aver aiutato a proteggere i Timbermaw.",
}
T[6132] = {
  title = "Tirami Fuori di Qui!",
  desc = "Tirami fuori di qui!$B$BSono salita fino alla Valley of Spears per parlare con i Maraudines. Pensavo di concludere qualche affare con loro... e invece non vogliono nemmeno parlare! Secondo me vogliono mangiarmi!$B$BTirami fuori di qui e mio fratello Hornizz ti pagherà alla grande! Lo trovi al nostro accampamento vicino al cimitero dei kodo, a est.$B$BSbrighiamoci, $N. Neanche due minuti fa ho sentito dei centauri che parlavano di andare a prendere la legna per la pentola...",
  obj = "Scorta Melizza Brimbuzzle, poi parla con Hornizz Brimbuzzle a Kodo Graveyard in Desolace.",
  progress = "Hai visto mia sorella Melizza? Non sta mai ferma, e per questo finisce nei guai di continuo.",
  reward = "Me l'aveva detto, mia sorella Melizza, che saresti $Garrivato:arrivata;. Grazie mille di averla tirata fuori dal pasticcio in cui si era messa; peccato che, con ogni probabilità, si sia già cacciata in un altro!",
  en_title = "Get Me Out of Here!",
  en_obj = "Escort Melizza Brimbuzzle, then speak with Hornizz Brimbuzzle at the Kodo Graveyard in Desolace.",
}
T[6133] = {
  title = "Il Comando del Signore dei Ranger",
  desc = "Gli alti elfi del rifugio di Quel'Lithien hanno una cosa che mi appartiene, $C: un documento che racconta la mia vita da mortale.$B$BPrima che tu lo chieda: no, non hai nessun diritto di sapere cosa c'è scritto. Fa' quello che ti dico e basta, verme: recupera il registro.$B$BE assicurati, imbecille, di lasciarti dietro quanta più discordia e dolore possibile. Lasciali a soffrire...",
  obj = "Va' ai confini settentrionali delle Eastern Plaguelands e recupera il Quel'Thalas Registry. L'oggetto si trova da qualche parte nel rifugio di Quel'Lithien.$B$BDevi anche uccidere 8 Rangers, 8 Pathstriders e 8 Woodsmen.",
  progress = "Non farmi aspettare, $C.",
  reward = "Confido che tu non abbia letto il registro. Una cosa così idiota non la faresti nemmeno tu...",
}
T[6134] = {
  title = "Raccolta di Ghost-o-plasm",
  desc = "A sud-est c'è una valle infestata dai fantasmi dei centauri, la Valley of Bones. Fa paura, vero? Beh, pensa a quanta paura fa a un centauro!$B$BEcco, prendi questa crate of ghost magnets. Se metti un magnete fra i due grandi scheletri della valle, i Dead Goliaths, i fantasmi gli si avvicineranno. Tu tieniti a distanza, fai fuori i fantasmi e prenditi il loro ghost-o-plasm.$B$BHo il vago sospetto che ai Magram questa poltiglia interessi MOLTO, e ho intenzione di vendergliela.",
  obj = "Porta 8 Ghost-o-plasms e la Crate of Ghost Magnets a Hornizz Brimbuzzle in Desolace.",
  progress = "$N, dov'è il mio ghost-o-plasm?",
  reward = "Eccolo! A quanto pare un po' ti è finito pure addosso. Un po' viscido, eh?$B$BBeh, grazie mille per tutto il disturbo, $N. Questa roba varrà una fortuna... sempre che riesca a convincere i centauri di cosa si tratta!",
  en_title = "Ghost-o-plasm Round Up",
  en_obj = "Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.",
}
T[6135] = {
  title = "Duskwing, Oh, Quanto ti Odio...",
  desc = "Finora hai portato a termine le missioni che ti ho affidato; non con la massima puntualità, però.$B$BImmagino che ti senta $Gpronto:pronta; per una sfida. Sì... Sì, imbecille, forse sei $Gpronto:pronta; per una serie di missioni più impegnative.$B$BDuskwing, il pipistrello demoniaco albino, si aggira per le campagne appena a nord di qui. Rintraccialo e distruggilo. Torna da me con una pezza della sua pelliccia bianca e sarai $Gricompensato:ricompensata;.",
  obj = "Trova Duskwing e uccidilo. Dal cadavere recupera una Patch of Duskwing's Fur e portala a Nathanos Blightcaller.$B$BSi dice che Duskwing si aggiri per le campagne a nord di Marris Stead.",
  progress = "Ti sconsiglio di affrontare questa sfida da $Gsolo:sola;, $C.",
  reward = "Ottimo lavoro, imbecille. Da questa pelliccia ricaverò qualcosa che potrai usare.",
}
T[6136] = {
  title = "Il Corpulento",
  desc = "Oltre l'accampamento dell'Argent Dawn a Speranza della Luce, e a ovest di Northdale, troverai il corpulento maggot Borelgore.$B$BPer colpa di quel mostro ho perso interi reggimenti. La sua mole non conosce limiti! Più mangia, più diventa grosso...$B$BSe la bestia ti divorasse non ne subirei alcun danno emotivo, ma preferirei che fossi tu $Gil vincitore:la vincitrice;. Per questa missione ti consiglio di farti aiutare da altri. Si sa che Borelgore ha inghiottito piccoli battaglioni così sciocchi da attaccarlo.",
  obj = "Trova Borelgore nelle lande settentrionali delle Eastern Plaguelands e distruggilo. Torna da Nathanos Blightcaller quando la missione è compiuta.",
  progress = "Te l'ho detto di recente che ti odio?",
  reward = "Continua così e potrei dover promuoverti da imbecille a minorato mentale di prima classe.",
}
T[6141] = {
  title = "Brother Anton",
  desc = "Il mio fratello d'armi, Brother Anton, ha sentito dire che nel lontano Kalimdor, in una terra chiamata Desolace, c'è un'infestazione di non morti. Anton si è subito imbarcato per raggiungerla, per scovare e distruggere la minaccia dei non morti!$B$BCerca qualcuno che abbia il coraggio e la determinazione per aiutarlo. Se il tuo cuore è sincero, va' a parlare con Anton: lo trovi a Desolace, a Nijel's Point, la città dell'Alleanza.",
  obj = "Parla con Brother Anton a Desolace.",
  reward = "Mi è giunta voce che dall'est stanno arrivando aiuti. Si parlava di te? Sei $Gvenuto:venuta; qui per aiutare lo Scarlet Brother nella sua crociata?$B$BSe è così, ascolta bene...",
  en_title = "Brother Anton",
  en_obj = "Speak with Brother Anton in Desolace.",
}
T[6142] = {
  title = "Esca di Bivalve",
  desc = "Hai l'aria di $Gun:una; $Gpescatore:pescatrice;, $C! Io adoro pescare — pesco da tutta la vita. L'esca migliore è il soft-shelled clam meat: i pesci non gli resistono proprio, capisci?$B$BPiù a nord, al largo della costa, troverai il relitto di una nave, e tutta la zona è piena di Soft-shelled clams. Riportami 10 pezzi di soft-shelled clam meat e ti darò qualcosa in cambio.",
  obj = "Trova 10 pezzi di Soft-shelled Clam Meat e portali a Mai'Lahii a Shadowprey Village.",
  progress = "Non vedo l'ora di andare a pesca con un po' di soft-shelled clam meat fresco; ce li hai i 10 pezzi che mi servono?",
  reward = "Perfetto mon, è proprio quello che lo stregone mi ha detto di fare contro il mal di testa. Mi fa: \"Mai'Lahii — va' a pescare, che ti fa sentire meglio.\"$B$BBeh, già mi sento meglio, grazie mon!",
  en_title = "Clam Bait",
  en_obj = "Find 10 pieces of Soft-shelled Clam Meat and bring it back to Mai'Lahii at Shadowprey Village.",
}
T[6143] = {
  title = "Altri Pesci da Friggere",
  desc = "Magari l'hai sentito, magari no... io e la mia ciurma stava a pescare vicino alla Ranazjar Isle, a nord della nave naufragata al largo della costa, su a nord. Pescavamo sempre lì; e adesso non penso ad altro che a come vendicare i compagni caduti.$B$BI naga ci hanno attaccati una mattina e hanno ammazzato tutti tranne me.$B$BIl senso di colpa mi pesa troppo sulla coscienza, $C; ho bisogno che tu vada a friggere quelli naga per me. Farò in modo che ne valga la pena; pensi di potermi aiutare?",
  obj = "Uccidi 7 Slitherblade Myrmidon, 7 Slitherblade Naga e 5 Slitherblade Sorceresses, poi parla con Drulzegar a Shadowprey in Desolace.",
  progress = "Sento ancora le loro voci che gridavano aiuto mentre i naga ci scatenavano addosso il caos. Se non fosse per questo ginocchio malandato, verrei a darti una mano a uccidere quei maledetti naga!$B$BLi trovi quasi sempre giù in fondo alle barriere coralline, sotto la superficie... in agguato... a tramare...",
  reward = "Sentire che i naga sono stati sconfitti è dolce, ma il cuore mi resta vuoto. Il resto della mia vita lo passerò a farli uccidere tutti.$B$BEcco, mon, la tua ricompensa, come promesso. È poca cosa rispetto alla soddisfazione di sapere che i naga sono stati fritti per la cosa odiosa che hanno fatto alla mia ciurma.",
  en_title = "Other Fish to Fry ",
  en_obj = "Slay 7 Slitherblade Myrmidon, 7 Slitherblade Naga, and 5 Slitherblade Sorceresses, and then talk to Drulzegar at Shadowprey in Desolace.",
}
T[6144] = {
  title = "La Chiamata al Comando",
  desc = "È arrivato l'ordine, $C. Varimathras in persona vuole che rimandi a Undercity i miei agenti più 'capaci', per un'operazione tattica estremamente delicata.$B$BPurtroppo i più capaci li hanno uccisi più di tre anni fa, e al loro posto mi ritrovo un'accozzaglia di gentaglia senza cervello.$B$B<Nathanos ti fissa con freddezza.>$B$BVa' subito a Undercity e fai rapporto a Varimathras. E non mettermi in imbarazzo, $C!",
  obj = "Viaggia fino a Undercity e parla con Varimathras.",
  reward = "Il Gran Crociato se ne sta al sicuro nello Scarlet Bastion, mentre le sue forze si riversano nelle tue terre, profanano i tuoi edifici e i tuoi monumenti e assassinano il tuo popolo.$B$BLa Dama Oscura mi ha ordinato di sistemare questo insetto una volta per tutte, e tu diventerai lo strumento della resa dei conti dei Forsaken.",
}
T[6145] = {
  title = "Il Crimson Courier",
  desc = "Come il corpo non può sopravvivere senza la testa, così la testa non sopravvive senza il corpo. Il comando della Scarlet Crusade dentro Stratholme ha difese quasi impenetrabili: dobbiamo invece staccare il corpo dalla testa.$B$BI miei Deathstalkers hanno raccolto informazioni su quello che fa la Crociata fuori da Stratholme: ogni giorno il suo comando centrale manda un rapporto a Tyr's Hand. È quel rapporto la chiave, $R! Trova il Crimson Courier, recupera il rapporto e portalo a Nathanos.",
  obj = "Torna in Eastern Plaguelands e rintraccia il Crimson Courier. Uccidi il Corriere e recupera il Grand Crusader's Command.$B$BPorta il comando a Nathanos Blightcaller per ricevere altre istruzioni.",
  progress = "Riesci in questo, e ti sarai quasi $Gguadagnato:guadagnata; il mio rispetto, $C.",
  reward = "<Nathanos ride.>$B$BEccellente! Finalmente! L'occasione per distruggere l'Oracolo Scarlatto!",
}
T[6146] = {
  title = "Lo Stratagemma di Nathanos",
  desc = "Ho fatto qualche modifica a questo comando. Se il nostro piccolo stratagemma funziona, faranno uscire allo scoperto l'Oracolo Scarlatto, e noi colpiremo!$B$BOra ascoltami bene, $C. Questo comando devi consegnarlo al Lord Crociato, Valdelmar.$B$BCome? Mettendoglielo in mano, imbecille.$B$BPorta il comando e questa rotten apple a Tyr's Hand. Appena entri in città, mangia la mela: ti trasformerai in qualcosa di più... gradevole per gli umani. Poi prendi il comando e consegnalo al Lord Crociato, Valdelmar.",
  obj = "Viaggia fino a Tyr's Hand, a sud-est di Marris Stead. Una volta lì, dai un morso alla Rotten Apple. Con le sembianze della Scarlet Crusade, consegna il Grand Crusader's Command a Crusader Lord Valdelmar.",
  progress = "Inaccettabile, soldato!",
  reward = "Dove sei $Gstato:stata;? Pensavamo che lo Scourge ti avesse $Gcatturato:catturata;.",
}
T[6147] = {
  title = "Ritorno da Nathanos",
  desc = "Insolita richiesta, quella del Gran Crociato. Mmh, comunque sia... sarà fatto come chiede. Torna allo Scarlet Bastion e avvisalo che l'Oracolo partirà presto.$B$BPrenderemo ogni precauzione perché arrivi illesa a Stratholme.",
  obj = "Torna da Nathanos Blightcaller con le nuove informazioni.",
  reward = "Che stolti! Nessuno si è accorto del mio inganno! Preparati, $C. Dobbiamo colpire con fredda astuzia!",
}
T[6148] = {
  title = "L'Oracolo Scarlatto, Demetria",
  desc = "Demetria è la prima consigliera del Gran Crociato. La chiamano l'Oracolo per i suoi sensi 'ultraterreni', e ha contribuito a diverse vittorie della Crociata contro lo Scourge.$B$BQuesto stratagemma è riuscito a farla uscire allo scoperto, ma se ha davvero poteri psichici si aspetterà senz'altro qualche guaio. E quel 'guaio' sarai tu a procurarglielo.$B$BRintraccia l'Oracolo ed eliminala. Dovrebbero partire da Tyr's Hand proprio adesso. Voglio essere fiero di te, verme.",
  obj = "The Scarlet Crusade è in movimento. Da qualche parte lungo la strada da Tyr's Hand a Stratholme troverai l'Oracolo, Demetria, e il suo seguito. Dalle la caccia e uccidila. Se ci riesci, torna da Nathanos Blightcaller.",
  progress = "Allora, $N, a che punto sei?",
  reward = "Gli ci vorranno anni per riprendersi da un colpo simile! Ben fatto, $N! Ti sei $Gguadagnato:guadagnata; non solo il mio rispetto, ma anche questa ricompensa.",
}
T[6161] = {
  title = "Prendi il Tesoro di Rackmore!",
  desc = "Il diario di bordo di Rackmore racconta che la sua nave era diretta alla Feathermoon Stronghold quando venne attaccata da creature del mare. Perché il tesoro non cadesse in mani nemiche, nascose il forziere sulla Ranazjar Isle.$B$BIl forziere si apre con due chiavi, una d'argento e una d'oro. Le chiavi sono andate perdute, ma se si ritrovano chiavi e forziere, ad attendere c'è un tesoro!",
  obj = "Trova la Rackmore's Silver Key. Trova la Rackmore's Golden Key. Trova e apri il Rackmore's Chest.",
  progress = "Il forziere è chiuso saldamente a chiave.",
  reward = "Il forziere si apre e svela il tesoro di Rackmore!",
  en_title = "Claim Rackmore's Treasure!",
  en_obj = "Find Rackmore's Silver Key.  Find Rackmore's Golden Key.  Find and open Rackmore's Chest.",
}
T[6162] = {
  title = "L'Ultima Battaglia di un Marito",
  desc = "Per l'onore del nostro clan, mio marito ha viaggiato per Felwood combattendo lo Shadow Council e altre atrocità corrotte!$B$BEra sfuggito alla morte già tante volte, quando mi è arrivata una sua lettera: un druido gli aveva chiesto aiuto contro un grosso furbolg contaminato, un certo Overlord Ror — e da allora di nessuno dei due si è più saputo niente.$B$BVoglio la mano artigliata di questo Ror, $N. Deve pagare per avermi resa vedova! Credo che la creatura stia a sud... vicino al confine con Ashenvale.",
  obj = "Uccidi Overlord Ror e riporta il suo artiglio a Dreka'Sur a Bloodvenom Post, a Felwood.",
  progress = "Hai già l'artiglio della bestia, $N? Pagherà per i suoi crimini. Che sia corrotto o solo arrabbiato perché vive in una foresta tanto tetra, non m'importa. Nessun furbolg che commette simili crimini contro la mia famiglia vivrà a lungo!",
  reward = "Hai mantenuto la parola, e questo mi rende onore. Mio marito è morto combattendo — ne sarebbe stato fiero. Ma non potevo darmi pace prima di sapere che la creatura che mi ha costretta a vivere da sola aveva pagato per quello che aveva fatto.$B$BGrazie ancora, $N.",
}
T[6163] = {
  title = "Ramstein",
  desc = "Mi hanno sopraffatto. Ho resistito proprio qui, in questa fattoria... ho tenuto la posizione per difendere Lordaeron. Un'enorme ondata dello Scourge ha travolto la fattoria e tutto quello che c'era.$B$BQuel miserabile. Quella sozzura. Mi sovrastava, e dal petto squarciato gli penzolavano le budella.$B$BMi sono risvegliato come Scourge. Per tanto tempo sono rimasto impotente, con la mente fusa a quella di The Lich King.$B$BÈ venuta a prendermi... in qualche modo, nel profondo, sapevo che l'avrebbe fatto. Libero.$B$BE ora devo vendicarmi — vendicarmi di ciò che mi ha tolto la vita. Distruggilo.",
  obj = "Viaggia fino a Stratholme e uccidi Ramstein the Gorger. Prendi la sua testa come ricordo per Nathanos.",
  progress = "Dopo che Sylvanas mi ha liberato, per mesi ho dato la caccia alla bestia in queste lande desolate, finché non si è rifugiata a Stratholme. Quel bastardo...",
  reward = "Mi chiedo... ha implorato pietà? Ma poteva sapere cos'è, la pietà?$B$B<Nathanos sputa.>$B$BAppenderò al muro la testa di questa bestia.$B$BTi sei $Gguadagnato:guadagnata; un posto fra i miei campioni, $N.$B$B<Nathanos saluta.>",
}
T[6164] = {
  title = "Augustus' Receipt Book",
  desc = "Pronto per gli affari! Che cosa ti serve?$B$BOh, aspetta... Senza il mio libro mastro non posso aprire bottega. Come li tengo i conti, senza il mio libro mastro?$B$BDevo averlo lasciato da qualche parte in città. Avevo una stanza alla locanda... dev'essere lì.$B$BPortami il mio libro. Ti prego, portamelo! Portamelo e vedrai! Aprirò bottega e vedrai che i miei prezzi sono DA PAZZI!",
  obj = "Porta l'Augustus' Receipt Book ad Augustus the Touched a Terrordale.",
  progress = "Ce l'hai, il mio libro mastro? Non vedo l'ora di rimettermi a fare affari!",
  reward = "Eccolo! Oh, cielo! Avevo dimenticato quant'era pieno!$B$BOggi è un giorno glorioso, $N! Stupendo! Bello da impazzire, dico io!",
}
T[6182] = {
  title = "Il Primo e l'Ultimo",
  desc = "Nathanos Marris è stato il primo e l'ultimo umano a diventare signore dei ranger. Era discepolo di Sylvanas Windrunner, che ora è The Banshee Queen dei Forsaken.$B$BCredevamo che Nathanos fosse caduto in battaglia cinque anni fa, mentre difendeva Lordaeron. Il cadavere non è mai stato ritrovato, ma si pensava che dalle Eastern Plaguelands non fosse uscito vivo.$B$BMathias Shaw sta indagando sulla scomparsa e potrebbe avere delle novità. Presentati subito da lui: lo trovi nell'Old Town, alla Caserma.",
  obj = "Parla con Mathias Shaw in Old Town Stormwind. Si trova nella Caserma.",
  reward = "Ci sono arrivate alcune segnalazioni di attività insolite dei Forsaken nelle Eastern Plaguelands, così abbiamo mandato degli agenti dell'SI:7 a indagare. Quello che hanno scoperto è inquietante.",
  en_title = "The First and the Last",
  en_obj = "Speak with Mathias Shaw in Old Town Stormwind. He resides in the Barracks.",
}
T[6183] = {
  title = "Onorare i Morti",
  desc = "Sul caso Marris avevo messo cinque dei miei migliori agenti sul campo. Ne è tornato uno solo, e tre giorni dopo è morto nel sonno.$B$BLe poche cose che siamo riusciti a cavargli erano frasi senza senso, ma due parole le abbiamo distinte: \"Nathanos\" e \"Blightcaller\".$B$BNon ho uomini per andare avanti con l'indagine, e da Ravenholdt non avremo aiuto. Dobbiamo andare fino in fondo a questa storia, se non altro per dare pace alle famiglie dei caduti. Mi aiuterai?",
  obj = "Parla di nuovo con Mathias Shaw se vuoi accettare il suo incarico.",
  reward = "<Mathias annuisce.>$B$BEro sicuro che Bolvar mi avrebbe mandato uomini e donne d'onore — i soldati più devoti dell'Alleanza.",
  en_title = "Honor the Dead",
  en_obj = "Speak with Mathias Shaw again if you wish to accept his task.",
}
T[6184] = {
  title = "Flint Shadowmore",
  desc = "Per ora, quindi, sappiamo soltanto che Nathanos Marris potrebbe essere stato ucciso da questo Blightcaller. Presumiamo che il Blightcaller sia lo stesso mostro che ha eliminato i miei agenti.$B$BFlint Shadowmore, un altro agente dell'SI:7, è di stanza all'accampamento dell'Alleanza di Chillwind Point, nelle Western Plaguelands. Cercalo: ti dirà come stanno le cose adesso nelle Plagues e ti affiderà un incarico.$B$BBuona fortuna, $N.",
  obj = "Raggiungi Chillwind Camp in Western Plaguelands e incontra il tuo contatto, Flint Shadowmore.",
  reward = "La prima missione sarà semplice e senza giri, $N. Dentro e fuori. Ricognizione...",
}
T[6185] = {
  title = "Le Eastern Plagues",
  desc = "Come ti dicevo, la prima missione è una ricognizione. Niente di speciale, $N. Vai nelle Eastern Plaguelands e cerca qualunque indizio su questo Blightcaller.$B$BSta' $Gattento:attenta; a ogni notizia sui nostri agenti scomparsi. Dobbiamo pensare che siano morti, e se sono morti ci devono essere dei cadaveri... da qualche parte.$B$B<Flint deglutisce a fatica.>$B$BOgni agente dell'SI:7 porta questa insegna.$B$B<Flint ti mostra la sua insegna dell'SI:7.>$B$BRiportami tutte quelle che riesci a trovare.",
  obj = "Perlustra le Eastern Plaguelands in cerca di indizi sul \"Blightcaller\" e sugli agenti dell'SI:7 scomparsi. Se trovi delle Insegne dell'SI:7, riportale a Flint Shadowmore a Chillwind Camp.",
  progress = "Ha... Hai trovato qualcosa??",
  reward = "Rutger. Fredo. Turyen. Tutti... morti...$B$B<Flint stringe forte le insegne.>$B$BDove si trovavano? Hai scoperto qualcos'altro su quel bastardo del Blightcaller?",
}
T[6186] = {
  title = "Giunge il Blightcaller",
  desc = "<Flint sembra aver perso ogni colore in volto.>$B$BNa... È stato Nathanos? Il Blightcaller è Nathanos?$B$BPerché? Era... era così nobile — un signore dei ranger rispettato da tutti, l'unico umano a cui abbiano mai permesso di addestrarsi con gli alti elfi. E adesso è uno spietato agente dei Forsaken?$B$BMi... mi dispiace chiedertelo, $N, ma il Gran Signore Fordragon va informato subito di questa svolta. Ti prego, torna a Stormwind e portagli la notizia.",
  obj = "Torna a Stormwind e informa Highlord Bolvar Fordragon del destino di Nathanos Marris.",
  reward = "No. È... NO! Come può essere? Un agente dei Forsaken? Il CAMPIONE di The Banshee Queen???$B$B<Highlord Bolvar Fordragon si accascia, sconfitto.>",
  en_title = "The Blightcaller Cometh",
  en_obj = "Return to Stormwind and inform Highlord Bolvar Fordragon of the fate of Nathanos Marris.",
}
T[6187] = {
  title = "L'Ordine Deve Essere Ristabilito",
  desc = "Lo sai quanti signori dei ranger ci sono al mondo? Quanti umani lo sono mai diventati?$B$BQuello che ha fatto Nathanos non aveva precedenti. Era un genio della tattica, e in dieci anni di guerra ha portato più volte l'Alleanza alla vittoria.$B$BE ora... il campione dei Forsaken.$B$BNo. Non può essere. L'ordine deve essere ristabilito.$B$BRaduna un esercito, $N. Torna nelle Plagues con le tue truppe e distruggi il Blightcaller.$B$BBuona fortuna, $N. Dico davvero: in questa battaglia ne avrai bisogno.",
  obj = "Raduna un esercito e raggiungi le Eastern Plaguelands. Sferra un attacco in forze contro Nathanos Blightcaller e contro tutta la feccia dell'Orda che dovesse cercare di proteggerlo.$B$BNon perdere la testa, $N. L'Orda difenderà il signore dei ranger a costo della vita.",
  progress = "<Highlord Bolvar Fordragon è perso nei suoi pensieri.>",
  reward = "È una tragedia. Penso... credo che la nostra stirpe sia maledetta, $N. Siamo condannati a perdere i guerrieri più grandi, gli eroi più nobili, gli studiosi più dotati.$B$BTi siamo debitori, $N, e ti assicuro che, ovunque si trovi ora Nathanos Marris, ti sorride dall'alto.",
}
T[6282] = {
  title = "Le Arpie Minacciano",
  desc = "I Tauren vanno fieri di essere i protettori di queste terre. Capirai di certo, allora, perché mi allarma il numero di arpie che vivono qui a Stonetalon.$B$BSe a Kalimdor le arpie sono sempre di più, la causa sono le Bloodfury; minacciano ogni forma di vita e impediscono agli innocenti di lasciare i loro confini.$B$BDevi decimare le arpie, $N!",
  obj = "Maggran Earthbinder a Sun Rock Retreat vuole che tu uccida 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers e 7 Bloodfury Roguefeathers.",
  progress = "Non lasciarti scoraggiare dalla Charred Vale; su quelle colline vivono molte creature malvagie. Resta forte, $N, e avrai la meglio su questa minaccia per il nostro popolo. Ora va' e colpisci duro — i nostri figli non conosceranno mai il male di un tempo.",
  reward = "Che notizia eccellente! Raccontami ancora di come hai seminato il terrore nei cuori freddi di quelle spregevoli arpie. Le Bloodfury hanno subito un duro colpo!",
  en_title = "Harpies Threaten",
  en_obj = "Maggran Earthbinder in Sun Rock Retreat wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.",
}
T[6283] = {
  title = "La Stirpe Bloodfury",
  desc = "Tenere basso il numero delle Bloodfury Harpies non basterà. Per la loro malattia l'unica vera cura sarebbe uccidere il loro capo, Bloodfury Ripper!$B$BPer quelle sudice creature è quasi una regina. Uccidila e di sicuro caleranno di numero.$B$BTorna nella Charred Vale e la troverai lungo le colline a ovest. Sconfiggerla non sarà facile, ma ti aspetta una grande ricompensa.",
  obj = "Maggran a Sun Rock Retreat vuole che tu uccida Bloodfury Ripper e gli porti i suoi resti come prova della tua impresa.",
  progress = "Bloodfury Ripper è una creatura orribile! La troverai nella Charred Vale, lungo le colline a ovest.$B$BSenza di lei le bloodfury saranno indifese... e di sicuro potremo sconfiggerle per sempre!",
  reward = "Sento già la rabbia che svanisce. E adesso, che ne farò del mio tempo? Sapere che il male si aggirava vicino alla mia terra mi occupava i pensieri, ma ora tacciono. Forse è un bene... forse ora posso dedicarmi al bene, come dovrebbero fare tutti i Tauren.$B$BAccetta questa ricompensa per il disturbo, ti prego.",
  en_title = "Bloodfury Bloodline",
  en_obj = "Maggran at Sun Rock Retreat wishes you to slay Bloodfury Ripper and bring her remains as proof of your deed.",
}
T[6284] = {
  title = "Aracnofobia",
  desc = "Attenzione: se entri nel Sishir Canyon, a ovest di qui, lo fai a tuo rischio e pericolo.$B$BBesseleth e i suoi figli della foresta dalle otto zampe hanno fatto di questo canyon la loro tana di ragnatele.$B$BSu Besseleth c'è una taglia, messa da Maggran Earthbinder al Sun Rock Retreat. Uccidila e porta a Maggran la prova della sua morte: è lì che riceverai la ricompensa per esserti $Gsbarazzato:sbarazzata; di questa minaccia a otto zampe.",
  obj = "Uccidi Besseleth e porta la Besseleth's Fang a Maggran al Sun Rock Retreat.",
  progress = "Besseleth è una predatrice spietata... Temo per chi percorre di notte il Webwinder Path: è allora che lei e i suoi figli vanno a caccia di viaggiatori innocenti. Sono caduto io stesso preda della sua zanna di morte, lunga due piedi, ma per fortuna sono riuscito a respingerla e a mettermi in salvo. Darei qualsiasi cosa per vedere distrutto quel mostro.",
  reward = "Bella caccia, $N! Besseleth è una vecchia predatrice di queste parti... e non la rimpiangerò. Prendi questa ricompensa: è il segno che sei $Gil campione:la campionessa; della foresta.$B$B<Maggran si massaggia la ferita che gli ha lasciato Besseleth.>$B$BForse ora molti altri verranno al Sun Rock Retreat senza temere ciò che si nasconde nel buio.",
  en_title = "Arachnophobia",
  en_obj = "Kill Besseleth and bring Besseleth's Fang to Maggran at Sun Rock Retreat.",
}
T[6301] = {
  title = "Ciclo di Rinascita",
  desc = "L'avidità dell'industria e una guerra che non si ferma mai hanno devastato le terre di Stonetalon, e una ferita come questa possono curarla solo le benedizioni della Madre Terra.$B$B$N, vorrei che cercassi un seme speciale, il Gaea seed. Se ne trovano soltanto qui, nella Stonetalon Mountain, a nord del Sun Rock Retreat, lungo la riva del Mirkfallon Lake.$B$BPortami i semi e infonderò in loro un potere sciamanico che li farà crescere più in fretta.",
  obj = "Tammra Windfield al Sun Rock Retreat vuole che tu raccolga 10 Gaea Seeds.",
  progress = "Mi addolora profondamente la distruzione che portano senza sosta la guerra e chi cerca di arricchirsi col legname. Mi servono i Gaea seeds per aiutare il ciclo della rinascita e risanare le terre. Li hai, $C?",
  reward = "Ah, $N, hai i Gaea seeds. Guarda: con la benedizione della Madre Terra, persino questi piccoli chicchi di vita possono sbocciare e prosperare.$B$B<Tammra comincia a intonare un canto.>",
  en_title = "Cycle of Rebirth",
  en_obj = "Tammra Windfield at Sun Rock Retreat wants you to gather 10 Gaea Seeds.",
}
T[6381] = {
  title = "Nuova Vita",
  desc = "L'hai visto anche tu, $C: la terra soffre, ma il ciclo della vita è molto forte. Adesso tocca a noi fare la nostra parte per aiutarlo. Devi piantare questi semi nel cuore della distruzione, nella Charred Vale, a ovest. Fai attenzione, perché arpie ed elementali del fuoco furiosi infestano ancora quella terra sfregiata.$B$B$N, prendi questi enchanted Gaea seeds e piantali nei mucchi di terra fertile. Il ciclo della vita deve andare avanti!",
  obj = "Pianta 10 Gaea Seeds nei Dirt Mounds di Gaea, e poi riporta gli Enchanted Gaea Seeds rimasti a Tammra al Sun Rock Retreat.",
  progress = "I semi che pianti sono forti: resistono alla corruzione e aprono la strada ad altra vita. Non smetteranno di crescere: prima terranno lontana la corruzione e risaneranno la terra sfregiata, poi un giorno, grazie a loro, Stonetalon tornerà a essere una foresta rigogliosa.$B$BHai piantato tutti i Gaea seeds?",
  reward = "È una grande vittoria per la terra. E col tempo succederà dell'altro: la Venture Co. raccoglierà buzz saws e asce e se ne andrà, gli spiriti del fuoco furiosi si placheranno e la terra caccerà via le arpie.$B$BSolo allora, $N, Stonetalon sarà davvero in pace.$B$BHai lavorato bene, $C; prendi uno di questi oggetti, come ringraziamento per la nuova vita che oggi hai creato qui.",
  en_title = "New Life",
  en_obj = "Plant 10 Gaea Seeds in Gaea Dirt Mounds, and then return the remaining Enchanted Gaea Seeds to Tammra at Sun Rock Retreat.",
}
T[6389] = {
  title = "Una Piaga su di Te",
  desc = "Ti guardi intorno nella segheria in cerca di qualcosa con cui aprire il barile, e trovi un piede di porco che sembra fare al caso tuo.$B$BPianti bene i piedi a terra e preghi di riuscire a uscire dalla segheria prima che le termiti ti raggiungano.",
  obj = "Libera le Plagueland Termites in Northridge Lumber Mill, poi torna con il Barrel of Plagueland Termites da Nathaniel Dumah a Chillwind Camp in Western Plaguelands.",
  progress = "Ce l'hai fatta, $N? Hai liberato le termiti? Che la Luce ci aiuti, se la Scarlet Crusade riuscisse a tenersi la segheria e anche Hearthglen. Non dovrebbero avere né l'una né l'altra. Approfittano soltanto delle vittime dell'ultima guerra, e andrebbero abbattuti come animali rabbiosi!",
  reward = "Haha! Grazie, $N! Ce l'hai fatta! Ora lo spirito di mio padre può riposare, e io vivere in pace.$B$BGrazie ancora. Se c'è qualcosa che posso fare per te, chiedi pure, ti prego.",
}
T[6390] = {
  title = "Che la Piaga ti Colga",
  desc = "Ti guardi intorno nella segheria in cerca di qualcosa di adatto per aprire il barile. Trovi un piede di porco che sembra fare al caso tuo.$B$BTi prepari e preghi di riuscire a uscire dall'edificio prima che le termiti ti raggiungano.",
  obj = "Libera le Plagueland Termites in Northridge Lumber Mill, poi torna con il Barrel of Plagueland Termites da Mickey Levine al Bulwark, nelle Tirisfal Glades.",
  progress = "Ce l'hai fatta, $N? Hai liberato le termiti nella segheria?$B$BEra già abbastanza grave che la mia famiglia avesse perso il lavoro e la vita, ma vedere poi il posto dove sono cresciuta occupato da quei disgustosi, sedicenti uomini santi... puah!!",
  reward = "Grazie, $N. Ecco, prendi questa moneta. Mi dispiace non poterti dare di più, ma consolati sapendo di aver contribuito a vanificare gli sforzi della Scarlet Crusade!",
}
T[6393] = {
  title = "Guerra Elementale",
  desc = "Il Tribunal of the Tides mi ha mandato qui nella Stonetalon Mountain a fare guerra agli elementali del fuoco. Neptulon the Tidehunter, Signore di tutti i water elementals, ci tiene in prima persona a vedere spenti i nostri cugini infuocati.$B$B$N, puoi aiutarmi a guadagnare il favore del Tribunal distruggendo gli elementali del fuoco nella Charred Vale: quando li hai sconfitti, lasciano le Incendrites. Portamele e sarai $Gricompensato:ricompensata;.",
  obj = "Porta 10 Incendrites a Tsunaman a Sun Rock Retreat.",
  progress = "Il Tribunal of the Tides si fa impaziente: vuole porre fine a questa guerra che da eoni infuria in tutte le dimensioni. I miei fratelli non vedono l'ora di avere notizie della gloriosa vittoria sugli odiati elementali del fuoco. Hai le Incendrites che mi servono?",
  reward = "Gli spiriti dell'acqua dentro di me ribollono di entusiasmo. $N, grazie a te ho una gloriosa vittoria da riferire al Tribunal of the Tides.",
  en_title = "Elemental War",
  en_obj = "Bring 10 Incendrites to Tsunaman at Sun Rock Retreat.",
}
T[6402] = {
  title = "Appuntamento a Stormwind",
  desc = "Devi vederti con Windsor alle porte di Stormwind.$B$BQuello che Windsor sta per rivelare scuoterà il regno fin dalle fondamenta!$B$BNon provare ad andarci da $Gsolo:sola;, $N. Ti serve un esercito! Raduna i tuoi compatrioti. Alle armi!",
  obj = "Vai a Stormwind City e raggiungi le porte della città. Parla con Squire Rowe perché possa far sapere a Marshal Windsor che sei $Garrivato:arrivata;.",
  reward = "Prima di cominciare, ti chiedo di radunare un esercito. Dopotutto, abbiamo davanti un drago!",
  en_title = "Stormwind Rendezvous",
  en_obj = "Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived.",
}
T[6403] = {
  title = "La Grande Mascherata",
  desc = "È stata proprio un'avventura, $Gamico:amica;. Ti sono immensamente debitore. Forse, quando tutto sarà finito...$B$BCome ormai avrai senz'altro capito, Lady Prestor è Onyxia: Progenie di Deathwing, gemella del tiranno della Guglia, Nefarian.$B$BPer troppo tempo ha tenuto il nostro regno prigioniero del suo sguardo ammaliatore. Persino il Sommo Signore è soggiogato dai suoi inganni — un burattino nelle sue mani. Oggi finisce tutto... L'incantesimo sarà spezzato.$B$BNon temere, perché insieme vinceremo!$B$BSei $Gpronto:pronta;?",
  obj = "Segui Reginald Windsor per le vie di Stormwind. Proteggilo da ogni pericolo!",
  progress = "Ero... ero... ero impotente.",
  reward = "<Bolvar tiene in mano il medaglione infranto.>$B$BLa magia racchiusa al suo interno va riaccesa. L'occhio del drago va sintonizzato.$B$BIl sacrificio di Windsor ha liberato il nostro Regno, ma la minaccia di Onyxia e della sua stirpe incombe ancora.$B$BÈ questo l'oggetto che teneva prigionieri la mia mente e il mio corpo. Ed è anche ciò che mi ha dato accesso ai pensieri stessi di Onyxia — ai suoi segreti. Sebbene ora le visioni siano confuse, alcune cose le ricordo.",
  en_title = "The Great Masquerade",
  en_obj = "Follow Reginald Windsor through Stormwind. Protect him from harm!",
}
T[6441] = {
  title = "Satyr Horns",
  desc = "Ehilà! Ero di passaggio per Ashenvale, diretta a Ratchet, e ho deciso di fare tappa qui a Splintertree. Un'occasione io la cerco sempre, e pare che di questi tempi a Ratchet le satyr horns siano molto richieste.$B$BHo fatto un po' di domande in giro, e da quel che ho capito i satiri di Night Run, Satyrnaar e Xavian hanno tutti le corna che fanno al caso mio. Io non sono all'altezza di quei satiri... ma tu, a vederti, potresti esserlo!$B$BFacciamo così: tu mi procuri le corna e io farò in modo che ne valga la pena.",
  obj = "Raccogli 16 Satyr Horns per Pixel a Splintertree Post.",
  progress = "Spero che ti sbrighi a procurarti quelle corna, $N. Fra poco torno a Ratchet!",
  reward = "Sono perfette, $N! Grazie della mano!$B$BOh, e questo è per il disturbo...",
  en_title = "Satyr Horns",
  en_obj = "Collect 16 Satyr Horns for Pixel in Splintertree Post.",
}
T[6462] = {
  title = "Troll Charm",
  desc = "I miei parenti venivano qui con molti troll charms sacri, ma prima che arrivassero a Zoram'gar i furbolgs Thistlefur li hanno attaccati e uccisi! Quei luridi Furbolgs!$B$BI fratelli e le sorelle che ho perso mi mancano, ma ci rivedremo nell'aldilà. I loro troll charms, invece, in questo mondo valgono molto. Che ce li abbiano i furbolgs è un oltraggio!$B$B$N, devi recuperare i talismani! Stanno in alcuni forzieri nella Thistlefur Hold, una caverna in fondo al Thistlefur Village, a nord di Astranaar.",
  obj = "Porta 8 Troll Charms a Mitsuwa, a Zoram'gar Outpost.",
  progress = "Li hai trovati, i talismani, $N? Ogni istante che quegli oggetti sacri restano in mano ai furbolgs mi fa ribollire il sangue di rabbia!",
  reward = "Li hai trovati! Grazie, grazie, $N! Non sai quanto hai fatto per me.$B$BUn troll senza talismano è come un orco senza cicatrici di battaglia...$B$BNon vale niente.",
  en_title = "Troll Charm",
  en_obj = "Bring 8 Troll Charms to Mitsuwa at the Zoram'gar Outpost.",
}
T[6482] = {
  title = "Libertà per Ruul",
  desc = "Eh? Chi sei?$B$B$N? Non sei $Gun:una; furbolg. Sono maledetti! Mi hanno preso per un orso, mi hanno catturato e adesso mi lasciano morire di fame! Le forze mi stanno abbandonando...$B$BAiutami a scappare, poi va' a parlare con mia sorella Yama, allo Splintertree Post, a est.$B$B$N! Devo scappare!",
  obj = "Scorta Ruul, poi parla con Yama Snowhoof allo Spintertree Post.",
  progress = "Hai visto mio fratello Ruul? È entrato nella foresta giorni fa e non è più tornato...",
  reward = "Hai trovato mio fratello! L'avevano catturato i Thistlefur? È una notizia terribile: molti Furbolgs sono creature nobili, ma i Thistlefur sono corrotti.$B$BGrazie di averlo salvato, $N. Non voglio pensare a come hanno trattato il povero Ruul. Dopo un calvario simile, probabilmente dormirà a lungo...",
  en_title = "Freedom to Ruul",
  en_obj = "Escort Ruul, then speak with Yama Snowhoof in Splintertree Post.",
}
T[6501] = {
  title = "L'Occhio del Drago",
  desc = "Posso offrirti soltanto un frammento del medaglione infranto.$B$BDevi trovare un altro essere dal sangue di drago, disposto ad aiutarti a forgiare una nuova chiave. Una volta ottenuta, dovrai recarti al Wyrmbog, nella Dustwallow Marsh. È lì che c'è la sua tana, $N.$B$BDove cercare altri stormi di draghi pronti a darti una mano? Purtroppo non lo so... Si dice che esistano. Alcuni potrebbero persino lavorare e vivere tra noi, travestiti da membri di una delle razze umanoidi. Ti auguro buona fortuna.",
  obj = "Devi cercare in tutto il mondo un essere capace di ridare potere al Fragment of the Dragon's Eye. Di lui sai soltanto che esiste.",
  progress = "Percepisco un'aura malvagia che si irradia da te, $R. Che cosa avrai mai con te, per emanare un'aura del genere?",
  reward = "Avrei dovuto immaginarlo — un frammento della madre della covata dei draghi neri, Onyxia. Che disgusto...",
  en_title = "The Dragon's Eye",
  en_obj = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist.",
}
T[6502] = {
  title = "Drakefire Amulet",
  desc = "È un pezzo del drago; una scaglia — incantata e trasformata. Intera, avrebbe potuto dare accesso alla tana della bestia. Infranta, è inutile.$B$BL'oggetto si potrebbe riparare, ma servirebbe il sangue di un campione dei draghi neri. Ce n'è uno... Lo chiamano General Drakkisath, signore degli eserciti di dragonidi di Nefarian. Forse ne hai sentito parlare?$B$BTorna con il suo sangue, $R, e incanterò il frammento trasformandolo in qualcosa che ti aprirà la strada verso la tana di Onyxia.",
  obj = "Devi recuperare il Blood of the Black Dragon Champion da General Drakkisath. Drakkisath si trova nella sala del trono, dietro Halls of Ascension, a Blackrock Spire.",
  progress = "Lo scorrere del tempo non si ferma né rallenta, $R. La mia vita è eterna, la tua no. Non sprecare quello che hai...",
  reward = "Questo amuleto ti darà l'accesso che cerchi. La tana di Onyxia si trova nella Dustwallow Marsh. Finché lo porterai con te, le protezioni del covo non potranno impedirti di entrare.$B$BIl Blue Flight ti augura buona fortuna, $N.",
}
T[6503] = {
  title = "Ashenvale Outrunners",
  desc = "Ci è arrivata notizia che le staffette di Ashenvale sono partite da poco dal Silverwing Outpost, e che ora girano di nascosto vicino ai nostri territori nella foresta. Non vogliamo che scoprano qualcosa sulle nostre difese!$B$BMuoviti di nascosto nelle foreste a sud di qui e a est dell'avamposto dell'Alleanza di Silverwing. Scova le staffette, uccidile e poi torna da me.",
  obj = "Uccidi 9 Ashenvale Outrunners, poi torna da Kuray'bin a Splintertree Outpost.",
  progress = "Sto aspettando notizie sulle staffette che hai ucciso, $N.",
  reward = "Molto bene, $N. Hai un talento notevole per la caccia...$B$BSenza quelle staffette l'Alleanza è un po' più cieca, e senza informazioni è meno probabile che attacchi.",
  en_title = "Ashenvale Outrunners",
  en_obj = "Kill 9 Ashenvale Outrunners, then return to Kuray'bin at Splintertree Outpost.",
}
T[6504] = {
  title = "Le Pagine Perdute",
  desc = "Ho appena ritirato questo trinciatore a Ratchet e stavo tornando al Warsong Lumber Camp, dove dovrei essere in servizio. Mi hanno dato un manuale che spiega come farlo funzionare, ma durante il viaggio di ritorno una raffica di vento fortissima me l'ha strappato di mano. Le pagine sono volate dappertutto e mi è rimasta solo la copertina.$B$BOrmai potrebbero essere quasi ovunque, credo... ma senza quelle pagine non so come usare il trinciatore! Me le ritroveresti?",
  obj = "Trova le 12 pagine mancanti del Manuale d'Uso del Trinciatore e uniscile per formare i Capitoli 1, 2 e 3. Riporta le pagine a Gurda Ragescar vicino a Splintertree Post.",
  progress = "Spero che trovi presto le pagine, $N! Devo proprio tornare al lavoro!",
  reward = "Leggere non è il mio forte... ma adesso posso tornare al lavoro! Grazie, $N!",
  en_title = "The Lost Pages",
  en_obj = "Find the 12 missing pages of the Shredder Operating Manual, and put them together to form Chapters 1, 2, and 3. Return the pages to Gurda Ragescar near Splintertree Post.$B",
}
T[6521] = {
  title = "Un'Alleanza Empia",
  desc = "Malcin sostiene di trovarsi fuori da Razorfen Downs. L'ambasciatore va ucciso — agli occhi di The Lich King la sua missione sarà un fallimento.$B$BIl fatto che sia là spiega molte cose che abbiamo scoperto sulla zona — alcuni verrospini sono diventati spaventosamente potenti, e intanto, a modo loro, mostrano i segni della Piaga. Di certo vuol dire che hanno stretto un patto di qualche tipo.$B$BTrova Malcin e uccidilo, $N. A cosa fatta, torna da me.",
  obj = "Porta l'Ambassador Malcin's Head a Varimathras nell'Undercity.",
  progress = "Hai trovato l'Ambasciatore, $N? È morto?$B$BNon possiamo permettere che lo Scourge metta piede su Kalimdor. Minaccia già abbastanza i nostri confini, senza che dobbiamo affrontarlo su due fronti.$B$BDa quello che mi hai raccontato, l'unico segno di speranza è che la megera non sembrava corrotta. In fondo al suo spirito deve sapere che lo Scourge può portare un grande potere, ma che, se accettasse il loro patto, le Barrens non sarebbero davvero sue.",
  reward = "Bene. Ottimo lavoro, $C.$B$BOra che Malcin è morto, sappiamo almeno che l'avanzata del Flagello si fermerà. La Dama Oscura ti ringrazia per gli sforzi e vuole ricompensarti con un dono.$B$BAnche se non sappiamo fin dove arrivi l'influenza del Flagello dentro Downs, sono certo che presto scopriremo i suoi complotti.",
  en_title = "An Unholy Alliance",
  en_obj = "Bring Ambassador Malcin's Head to Varimathras in the Undercity.",
}
T[6522] = {
  title = "Un'Alleanza Empia",
  desc = "Mia Signora,$B$BSapete benissimo che cosa vi offriamo: per voi è una grande occasione, quella di prendere le Barrens e le terre al di là. In cambio vogliamo soltanto il vostro aiuto, e per aiuto non intendiamo che la libertà di agire nella zona.$B$BVi prego, concedeteci di parlarne ancora. Il nostro potere è grande, e siamo pronti a dividerlo con chi avrà la saggezza di unirsi a noi. Per ora resterò fuori da Razorfen Downs.$B$BDistinti saluti,$BAmbassador Malcin",
  obj = "Porta la Small Scroll a Varimathras nell'Undercity.",
  progress = "Di che faccenda vuoi parlarmi, $N? Se continui a infastidirmi, per te dev'essere importante.",
  reward = "Riconosco l'insegna su questa pergamena, $N. L'hai trovata addosso a quella megera che regna su Razorfen Kraul? Interessante.$B$BA quanto pare, allo Scourge un continente solo non basta. Quest'Ambassador Malcin — quello che ha scritto il messaggio — è uno dei servitori appestati dello Scourge: prima che le cose... cambiassero, era un diplomatico umano presso il regno di Lordaeron.$B$BSe lo Scourge cerca di mettere piede su Kalimdor, tocca a noi agire.",
  en_title = "An Unholy Alliance",
  en_obj = "Take the Small Scroll to Varimathras in the Undercity.",
}
T[6544] = {
  title = "L'Assalto di Torek",
  desc = "Ehi! $C! Vieni qui!$B$BCon i miei predoni sto per attaccare il Silverwing Outpost, a ovest. Puntiamo alla sua comandante, Duriel Moonfire. Secondo gli esploratori, a difendere l'avamposto c'è un gran numero di sentinelle e guerrieri. Sarà una battaglia gloriosa!$B$BVuoi darci una mano e prenderti la tua parte di gloria, $N? Allora, a cose fatte, potrai riferire il nostro successo al mio superiore, Ertog Ragetusk, a Splintertree.$B$BChe ne dici? Sei con noi?",
  obj = "Scorta Torek nel suo attacco contro il Silverwing Outpost e Duriel Moonfire, poi fai rapporto a Ertog Ragetusk allo Splintertree Post.",
  progress = "Torek è stato mandato in missione contro il Silverwing Outpost. L'attacco è riuscito?",
  reward = "Allora l'attacco di Torek è riuscito! Ben fatto, $N. Gli elfi della notte sono avversari niente male. Un po' magri, ma forti e feroci! Sono sicuro che la battaglia è stata uno spettacolo...$B$BE spero che ti sia $Gguadagnato:guadagnata; qualche cicatrice!",
  en_title = "Torek's Assault",
  en_obj = "Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post.",
}
T[6546] = {
  title = "Warsong Outrider Update",
  progress = "Su questo sentiero ci sono molti pericoli, $N. Tienilo a mente mentre viaggi per queste terre. L'alleanza ci minaccia da molto vicino.$B$BAbbiamo nemici su tutti i fronti. Nella parte orientale di Ashenvale i satiri sono ovunque, e sono una forza temibile. Ho scoperto pure che i naga si sono presi una vasta zona di Azshara.$B$BMi fa piacere vedere che i nostri ranghi continuano a crescere — tieniti $Gpronto:pronta; per quello che ti aspetta, $N.",
  reward = "Porta a Kadrak il mio aggiornamento. E fai in fretta, $N.",
  en_title = "Warsong Outrider Update",
}
T[6547] = {
  title = "Warsong Scout Update",
  progress = "Occhi aperti, $R. Spesso gli elfi si nascondono nell'ombra...$B$BNon possiamo mai abbassare la guardia. Abbiamo sudato per conquistare questa terra, e gli elfi non aspettano altro che l'occasione per portarcela via.$B$BMi porti i prossimi ordini da parte di Kadrak, immagino?",
  reward = "Riferisci a Kadrak che qui siamo riusciti a tenere a bada gli elfi della notte. I nostri piani vanno avanti bene.",
  en_title = "Warsong Scout Update",
}
T[6561] = {
  title = "Malvagità a Blackfathom",
  desc = "Le forze mi hanno abbandonato. Ho bisogno del tuo aiuto!$B$BTanto tempo fa, qui sorgeva un grande tempio di Elune. Ma la sventura l'ha mandato in rovina quando la corruzione di un Old God è filtrata dal sottosuolo e ha contaminato il sacro Moon Well.$B$BDalle acque è emerso Aku'Mai, servitore dell'Old God.$B$BI cultisti del Twilight's Hammer si sono alleati con i naga per occupare queste terre. Li guida Kelris, e in cambio di potere sacrificano innocenti ad Aku'Mai.$B$BTi prego, $N, uccidi Kelris e porta la sua testa a Bashana, a Thunder Bluff.",
  obj = "Porta la testa di Twilight Lord Kelris a Bashana Runetotem a Thunder Bluff.",
  progress = "Che la Madre Terra sia con te, $N.$B$BDovremmo tutti cercare la pace tra la terra e i suoi popoli, tutti quanti. Lei ha un grande disegno per la natura, e in quel disegno ognuno di noi ha la sua parte.",
  reward = "Da tempo Kelris sfuggiva all'Argent Dawn.$B$BPer un po' l'avevano creduto morto, o disperso.$B$BPonendo fine al suo regno hai risparmiato la vita a molti innocenti, $N.$B$BSia lodata la Madre Terra! Offrire qualcun altro in sacrificio a un servitore di un Old God per il proprio tornaconto è a dir poco disgustoso!$B$BOggi hai fatto una grande cosa. Kelris era una creatura del male, e venerando esseri come gli Old Gods cercava di riportare il mondo a un'epoca di caos. Grazie, $N.",
  en_title = "Blackfathom Villainy",
  en_obj = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.",
}
T[6562] = {
  title = "Guai nelle Profondità",
  desc = "Je'neu Sancrea ha bisogno di aiuto: lo troverai allo Zoram'gar Outpost, ad Ashenvale, la foresta degli elfi della Notte a nord dei monti Stonetalon. Puoi arrivarci passando per la Windshear Crag, oppure salendo verso nord attraverso Barrens. La Zoram Strand è molto più a ovest, oltre la foresta. Sta' $Gattento:attenta;, $N. Laggiù ci sono forze che non gradiranno la tua presenza.",
  obj = "Parla con Je'neu Sancrea ad Ashenvale.",
  reward = "Ti manda Tsunaman? Eccellente. Allora abbiamo delle questioni da discutere.",
  en_title = "Trouble in the Deeps",
  en_obj = "Speak to Je'neu Sancrea in Ashenvale.",
}
T[6563] = {
  title = "L'Essenza di Aku'Mai",
  desc = "Nei primi tunnel dei Blackfathom Deeps, lungo le pareti della caverna, ci sono grandi ammassi di zaffiri. Di recente si sono visti i naga raccogliere quei cristalli, e finché non sapremo perché lo fanno, sento che dovremmo fermare i naga. I cristalli hanno un grande potere elementale e, usati nel modo sbagliato, potrebbero diventare un potente componente arcano.$B$BMi aiuterai, $N? I Blackfathom Deeps sono lungo la Zoram Strand, a nord del nostro avamposto.",
  obj = "Porta 20 Sapphires of Aku'Mai a Je'neu Sancrea ad Ashenvale.",
  progress = "Come va la ricerca dei cristalli, $N? Hai visto i naga raccoglierli? Prego gli antenati di farci scoprire perché raccolgono cose del genere.",
  reward = "Ben fatto, $N. Questi sono i cristalli di cui ti parlavo. Intrigante...$B$BSento il potere che hanno dentro. Gli spiriti dell'acqua ci si aggrappano. Qualunque cosa i naga volessero farne... be', rallegriamoci che non siano più nelle loro mani.",
  en_title = "The Essence of Aku'Mai",
  en_obj = "Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.",
}
T[6564] = {
  title = "Fedeltà agli Old Gods",
  desc = "Sulla nota spiegazzata ci sono delle righe scarabocchiate con una brutta calligrafia:$B$B\"Sì, di' a tutte le sacerdotesse di portarmi i cristalli. Lì dentro gli spiriti elementali dell'acqua sono potenti, e ai nostri acquamanti saranno di grande aiuto nelle evocazioni.$B$BSe controlliamo il potere dei cristalli, placheremo Aku'Mai. E un giorno ne avremo abbastanza per riportare Aku'Mai fra noi, e il mondo tornerà alla sua era più grande! L'era in cui dominano gli Old Gods!\"",
  obj = "Porta la Damp Note a Je'neu Sancrea ad Ashenvale.",
  progress = "Sì, $N? Ti serve qualcosa? Sui cristalli che i naga stanno raccogliendo ho ancora molto da imparare.",
  reward = "Davvero interessante. Sono contento che tu me l'abbia fatto notare.$B$BOra i nostri guai hanno un nome... Lorgus Jett.",
  en_title = "Allegiance to the Old Gods",
  en_obj = "Bring the Damp Note to Je'neu Sancrea in Ashenvale.",
}
T[6565] = {
  title = "Fedeltà agli Old Gods",
  desc = "Questo seguace del Twilight's Hammer non deve portare a termine il suo piano. Il Twilight's Hammer non capisce gli spiriti della natura: crede negli Old Gods — creature del caos e della distruzione, sconfitte tanto tempo fa. Questo Lorgus non deve farcela. Devi fermarlo tu, $N. Io non posso — sono troppo debole.$B$BEntra in Blackfathom Deeps, trovalo e uccidilo. Quando hai finito, torna da me, qui a Zoram'gar.",
  obj = "Uccidi Lorgus Jett in Blackfathom Deeps, poi torna da Je'neu Sancrea ad Ashenvale.",
  progress = "L'hai già trovato, $N? Lorgus va fermato!",
  reward = "Benissimo!! Grazie, $N. Forse il Twilight's Hammer non l'abbiamo fermato del tutto, ma almeno hai sventato un altro dei loro piani per riportare al potere gli Old Gods.$B$BChissà cos'altro stanno preparando, ma per ora possiamo stare tranquilli.",
  en_title = "Allegiance to the Old Gods",
  en_obj = "Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.",
}
T[6566] = {
  title = "Ciò Che Porta il Vento",
  desc = "È bello rivederti, $N. Il vento porta notizie dall'Eastern Kingdom.$B$BSiediti e ascolta.",
  obj = "Ascolta Thrall.",
  progress = "Abbi pazienza, $N. Ascolta con attenzione!",
  reward = "Sei $Gpronto:pronta; a farti carico di questo compito?",
}
T[6567] = {
  title = "Il Campione dell'Orda",
  desc = "Uno dei miei campioni mi ha fatto sapere che forse c'è un modo per entrare nella tana del drago. Va' a cercarlo.$B$BRexxar vaga per il deserto desolato di Desolace, spostandosi fra Stonetalon e Feralas. Ti sta aspettando.",
  obj = "Cerca Rexxar. Il Capoguerra ti ha indicato dove si trova. Percorri i sentieri di Desolace, tra le Stonetalon Mountains e Feralas.",
  reward = "C'è un solo modo per entrare nella tana del drago, $R.$B$BVedi, nella tana della madre della covata possono entrare solo i più forti del Black Dragonflight. Bisogna superare molte prove, e la chiave d'accesso deve incantarla con una cerimonia General Drakkisath in persona!$B$BE visto che non sei della stirpe dei draghi neri, potresti avere qualche difficoltà a passare.$B$B<Rexxar sorride.>",
}
T[6568] = {
  title = "Il Testamento di Rexxar",
  desc = "Che cosa sai delle illusioni, $N? Vedi, per aggirare le difese del Black Flight dovrai crearne una.$B$BConosco una persona che forse sarebbe disposta ad aiutarti a mettere in piedi l'inganno. In passato ha già aiutato la nostra gente, quando le è sembrata una causa degna.$B$BNelle Western Plaguelands troverai Myranda the Hag, maestra illusionista — un'esule dell'alleanza di Lordaeron. Va' laggiù e portati dietro questo messaggio.",
  obj = "Consegna il Testamento di Rexxar a Myranda the Hag nelle Western Plaguelands.",
  progress = "Non capita spesso di vedere qualcuno dell'Orda da queste parti di Lordaeron. Cos'hai per Myranda?",
  reward = "<Myranda tiene in mano il biglietto, si ferma un attimo, poi sorride.>$B$BCome sta? Rexxar, dico. Oh, suvvia, non fare quella faccia $Gconfuso:confusa;. La lettera è in bianco apposta. Portava con sé le intenzioni e i pensieri di chi l'ha scritta. Visto quello che c'è dentro, non c'è da stupirsi che Rexxar l'abbia lasciata così. Pensa se ti avessero $Gcatturato:catturata; o $Gucciso:uccisa; e avessero scoperto queste informazioni!$B$BOh, lascia perdere! Myranda ti aiuterà, $R. Al Capoguerra devo un paio di favori.$B$B<Myranda sorride.>",
  en_title = "The Testament of Rexxar",
  en_obj = "Deliver Rexxar's Letter to Myranda the Hag in the Western Plaguelands.",
}
T[6569] = {
  title = "Illusioni Oculus",
  desc = "Allora $Gil:la; $R vorrebbe diventare $Guno:una; del Black Flight, eh?$B$BL'illusione che ti serve è una sciocchezza da creare, ma i componenti per la divinazione sono piuttosto difficili da procurarsi. Rexxar e il Capoguerra ti hanno affidato questa missione, perciò Myranda deve presumere che tu ne sia capace.$B$BVa' nella cittadella superiore di Blackrock Spire e uccidi tanti esemplari di black dragonspawn da riempire una delle tue borse con i loro occhi.$B$BQuando avrai raccolto abbastanza reagente, torna da Myranda.",
  obj = "Vai a Blackrock Spire e raccogli 20 Black Dragonspawn Eyes. Torna da Myranda the Hag quando avrai finito.",
  progress = "L'ingrediente più importante di qualsiasi illusione sono gli occhi di ciò che vogliamo imitare, $N.$B$B<Myranda indica una borsa piena fin quasi a traboccare di bulbi oculari, con l'etichetta 'Crociata Scarlatta'.>$B$B<Myranda ride.>",
  reward = "Lascia che Myranda dia un'occhiata, $R.$B$BOh sì, questi andranno benissimo.$B$BCon questi reagenti Myranda ti creerà un medaglione che ti darà un'illusione capace di ingannare il guardiano dello stormo dei draghi neri.",
}
T[6570] = {
  title = "Emberstrife",
  desc = "Ho sintonizzato questo medaglione sulla magia che serve a creare e mantenere un'illusione dentro i confini della tana di Emberstrife.$B$BEmberstrife è un antico drake; un vecchio guardiano di Nefarian, che ha sulle spalle il compito di mettere alla prova le dragobestie che ambiscono al rango di guardia scelta di Onyxia.$B$BVa' nel Wyrmbog della Dustwallow Marsh ed entra nella tana di Emberstrife. Una volta lì, indossa l'amuleto e segui il tuo destino, ovunque ti porti!",
  obj = "Vai a Wyrmbog, in Dustwallow Marsh, e cerca Emberstrife's Den. Una volta dentro, indossa l'Amulet of Draconic Subversion e parla con Emberstrife.",
  reward = "Siamo rimasti così a corto di soldati validi che Nefarian mi manda dei cuccioli? Le mie prove non le supererai mai, pivello.",
  en_title = "Emberstrife",
  en_obj = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife.$B",
}
T[6571] = {
  title = "Rifornimenti Warsong",
  desc = "Al campo di taglio Warsong siamo a corto di un po' di cose!$B$BLa nostra spedizione di lame seghettate ce l'ha Pixel, allo Splintertree Post. Per la cassa di asce, invece, bisognerà arrivare fino a Booty Bay e farsela consegnare da Wharfmaster Lozgil.$B$BPer l'olio e la corda sarà più difficile. La corda ce l'hanno sgraffignata i furbolgs Thistlefur e Foulweald, mentre il carico d'olio l'hanno intercettato i satiri, che adesso lo usano per i loro riti detestabili a Night Run, Satyrnaar e Xavian!$B$BMi dai una mano?",
  obj = "Raccogli i Rifornimenti Warsong per Locke Okarr a Splintertree Post: le Warsong Saw Blades, la Logging Rope, il Warsong Oil e la Warsong Axe Shipment.",
  progress = "Spero che tu ce la faccia a procurarmi i rifornimenti! Se non li consegno presto, finisco in guai seri!",
  reward = "Eccellente, $N. Mi hai risparmiato un sacco di lavoro!$B$BMa non pensare che non te ne sia grato!",
  en_title = "Warsong Supplies",
  en_obj = "Collect the Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil, and the Warsong Axe Shipment for Locke Okarr in Splintertree Post.",
}
T[6581] = {
  title = "Warsong Saw Blades",
  progress = "Le lame seghettate Warsong, arrivate dritte da Ratchet! Eh sì, ce le ho proprio qui.$B$B...Ma come pensi di pagarmi? Mica puoi prenderle e basta, sai! Il mio tempo costa caro!$B$BQuello che mi serve davvero è una buona arma da fuoco da tenere con me in viaggio. Una ragazza deve sapersi proteggere, no? Ce n'è una che mi piace un sacco, e sono sicura che per un ingegnere costruirla non sarebbe un problema.$B$BQuindi, se mi porti un deadly blunderbuss, il carico di lame seghettate è tuo. Affare fatto?",
  reward = "È perfetto — proprio quello che ci voleva! Bene, ecco il carico.",
  en_title = "Warsong Saw Blades",
}
T[6582] = {
  title = "La Prova dei Teschi, Scryer",
  desc = "Noi siamo i figli di Deathwing, cucciolo, e sugli Aspetti minori dobbiamo imporre il nostro dominio.$B$BSe dell'ascesa sei davvero $Gdegno:degna;, lo stormo draconico minore appassirà al tuo cospetto.$B$BTrova i loro campioni e, in nome di nostro Padre, annientali!$B$BRecati a Winterspring e scova il possente drake blu, Scryer. Schiaccia lui e chiunque del Blue Flight si metta sul tuo cammino. Poi strappagli il teschio e riportamelo.",
  obj = "Devi trovare il drake campione dello stormo draconico blu, Scryer, e ucciderlo. Strappa il teschio dal cadavere e riportalo a Emberstrife.$B$BSai che Scryer si trova a Winterspring.",
  progress = "<Emberstrife sibila.>",
  reward = "Uno fra sssvariati, completato...",
  en_title = "The Test of Skulls, Scryer",
  en_obj = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.$B$BYou know that Scryer can be found in Winterspring.",
}
T[6583] = {
  title = "La Prova dei Teschi, Somnus",
  desc = "Nostro Padre schiaccia gli Aspetti in persona, e noi, allo stesso modo, dobbiamo sforzarci di portare caos e distruzione ai loro figli.$B$BDevi misurare in battaglia la tua abilità contro i sognatori insonni: i figli del Green Flight.$B$BRecati nella Swamp of Sorrows e stana Somnus, il drake campione del Green Flight. Sfoga l'odio; domina l'insetto... E torna da me col suo teschio...",
  obj = "Distruggi il drake campione di Green Flight, Somnus. Prendi il suo teschio e portalo a Emberstrife.",
  progress = "Non farti rivedere finché non ti sarai $Gbagnato:bagnata; nel sangue dei nostri nemici e $Gabbeverato:abbeverata; della loro sofferenza.",
  reward = "Un altro, completato...",
  en_title = "The Test of Skulls, Somnus",
  en_obj = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife.",
}
T[6584] = {
  title = "La Prova dei Teschi, Chronalis",
  desc = "I guardiani del tempo, i figli di Nozdormu — Signore dei Secolisss...$B$BLe Caverns of Time le sorvegliano in tre, ma al Black Flight ne interessa uno solo: il Mutatempo, Chronalis, il draghetto prediletto di Nozdormu.$B$BSssferra a questo campione un colpo tale da far piangere persino le stoiche sabbie del tempo, e torna da me col suo teschio.",
  obj = "A guardia di Caverns of Time, nel Tanaris Desert, c'è Chronalis, figlio di Nozdormu. Distruggilo e porta il suo teschio a Emberstrife.",
  progress = "Per ironia della sorte, cucciolo, il tempo ssstringe.",
  reward = "I resti più odiatisss...",
  en_title = "The Test of Skulls, Chronalis",
  en_obj = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.",
}
T[6585] = {
  title = "La Prova dei Teschi, Axtroz",
  desc = "Sopra le montagne di Grim Batol nostro Padre si è scagliato con furia contro le forze unite degli Aspetti. Ma la traditrice, Alexstrasza, con il suo atto vigliacco ha dato agli altri Aspetti il tempo di sfuggire all'ira di Padre.$B$BUn atto cosssì vergognoso...$B$BOra è il Red Flight a sorvegliare Grim Batol, e il suo luogotenente, Axtroz, va distrutto. Portami il teschio di Axtroz. Per Padre, $Gcucciolo:cucciola;!",
  obj = "Vai a Grim Batol e rintraccia Axtroz, il drake campione del Red Flight. Distruggilo e prendi il suo teschio. Porta il teschio a Emberstrife.",
  progress = "Cambiamenti... sssento che stanno avvenendo in te, $Gcucciolo:cucciola;. Supera questa prova e non resterà che la cerimonia.",
  reward = "Avevo dubbi sulla tua dedizione, $Gcucciolo:cucciola;. Ma hai perseverato, hai dominato i nostri nemici e hai fatto onore al nostro stormo.$B$BOra devo preparare i teschi per la tua ascesa.",
  en_title = "The Test of Skulls, Axtroz",
  en_obj = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.",
}
T[6601] = {
  title = "Ascesa...",
  desc = "Dai teschi dei nostri nemici si ricava un medaglione. Questo medaglione lo conosci, sssì? Di certo l'avrai visto indosso ai tuoi anziani.$B$BPrendilo, $Gcucciolo:cucciola;. Torna alla Spire e presentalo a General Drakkisath: sarà il Generale a porre sul medaglione l'incantamento finale, che legherà il monile al tuo spirito.$B$BQuando sarà finito, indosserai il medaglione come simbolo d'onore, segno della tua ascesa a uno dei nostri ranghi più esclusivi: $GGuardiano:Guardiana; della madre della covata.$B$BVai!",
  obj = "Sembrerebbe che la farsa sia finita. Sai che l'Amulet of Draconic Subversion che Myranda the Hag ha creato per te non funzionerà all'interno di Blackrock Spire. Forse dovresti trovare Rexxar e spiegargli il problema. Mostragli il Dull Drakefire Amulet. Speriamo che sappia cosa fare.",
  progress = "Niente panico, $N!",
  reward = "Sono solo chiacchiere da drago, $N — più aria fritta che informazioni concrete. Dalla loro razza c'è da aspettarselo: pomposi e aggressivi.",
  en_title = "Ascension...",
  en_obj = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next.",
}
T[6602] = {
  title = "Blood of the Black Dragon Champion",
  desc = "Dal Generale ci andrai, sì, ma non come $Guno:una; del Black Dragonflight.$B$BVedi, per il Black Flight una cerimonia non è che un altro modo di dire spargimento di sangue.$B$BPer attivarsi, all'amuleto inattivo manca solo il sangue del Generale. Uno dei loro rozzi meccanismi di sicurezza.$B$BTorna a Blackrock Spire e distruggi Drakkisath. Portami qui il suo sangue e attiverò la chiave della tana di Onyxia.",
  obj = "Vai a Blackrock Spire e uccidi General Drakkisath. Raccogli il suo sangue e portalo a Rexxar.",
  progress = "Non credo di doverti dire che Drakkisath non va preso alla leggera.$B$BLascio la parola alle migliaia di morti per mano sua.",
  reward = "Questa vittoria sarà ricordata per molti anni, $N. Il Drakefire Amulet aprirà la tana di Onyxia: raduna i tuoi alleati e conquista il trionfo per l'Orda.",
}
T[6603] = {
  title = "Guai a Winterspring!",
  desc = "Ci sono guai a Winterspring!$B$BMa certo, un po' di tempo nelle terre selvagge lo passo, e di queste cose me ne intendo... e ne vado sempre fierissima. Per me le ore passate là fuori, sulle colline, valgono oro: ti fanno venire riflessi pronti, sangue freddo e occhio acuto...$B$BPer apprezzare la natura selvaggia come la apprezzo io ci vogliono giudizio, cervello e maturità.$B$BDunque, di che stavo parlando?$B$BAh, già, i guai. Va' da Donova Snowden, alle sorgenti termali: potrà dirti di più.",
  obj = "Trova Donova Snowden vicino alle sorgenti termali a Winterspring.",
  reward = "Be', ciao! Allora, Meggi ti ha raccontato dei guai che ho trovato qui?",
}
T[6604] = {
  title = "Gufi Selvaggi Infuriati",
  desc = "Hai visto l'accampamento abbandonato qui a sud? A quanto pare i gufi selvaggi sono impazziti e hanno distrutto praticamente tutto quello che hanno trovato!$B$BHo sentito che uno dei sopravvissuti all'attacco sta riposando a Starfall Village, qui a ovest. Sono proprio curioso di sapere com'è andata... e tu?",
  obj = "Parla con Jaron Stoneshaper a Starfall Village.",
  reward = "Sì? Cosa posso fare per te?",
}
T[6605] = {
  title = "Un Tipo Strano",
  desc = "Sono appena rientrato da Felwood, $N. Strada facendo ho fatto tappa al Bloodvenom Post, e lì ho conosciuto un personaggio davvero strano... Pareva che avesse in testa una cosa sola. Credo di poterti dire di che si tratta, ma penso che lei preferirebbe spiegartelo di persona.$B$BSe sei $Ginteressato:interessata;, va' al Bloodvenom Post, nella parte occidentale di Felwood, e cerca Winna Hazzard.$B$BChissà, magari le serve il tuo aiuto...",
  obj = "Parla con Winna Hazzard a Felwood.",
  reward = "Ah, $C. Vedo che una speranza c'è ancora. Sei qui per aiutarmi?",
}
T[6606] = {
  title = "Un Po' di Fortuna",
  desc = "Un po' di fortuna non guasta mai, eh? Basta un piccolo vantaggio e la situazione si gira a tuo favore...$B$BTempo fa ho conosciuto per caso una taumaturga piuttosto eccentrica, che mi ha fatto un lucky charm... a pagamento. Ma credimi, ne valeva davvero la pena!$B$BMagari saresti $Ginteressato:interessata; ad averne uno tutto tuo? Cerca Witch Doctor Mau'ari a Everlook. Il mio, comunque, non lo cedo!",
  obj = "Parla con Witch Doctor Mau'ari a Everlook.",
  reward = "Ah, ti manda Harlo? Be', e tu chi saresti? Immagino che vuoi il mio aiuto, eh?",
}
T[6607] = {
  title = "Nat Pagle, Pescatore Estremo",
  desc = "Non è che mi piaccia poi tanto, pescare. E saranno 20 o 30 anni buoni che lo faccio.$B$BOgnuno ha i suoi motivi per fare quel che fa, dico io.$B$BOra, per diventare $Gun maestro pescatore:una maestra pescatrice; non serve pescare per 30 anni o tirare su ogni pesce del mare. Per me basta essere $Gdeterminato:determinata; — $Gdeterminato:determinata; abbastanza da startene lì col sedere piantato per ore e ore, senza far niente.$B$BFacciamo così: tu mi porti qualche pesce raro e io ti insegno un paio di cose. Ecco la lista:",
  obj = "Nat Pagle vuole che tu peschi questi pesci:$B$BMisty Reed Mahi Mahi da Misty Reed Strand, in Swamp of Sorrows.$B$BUn Sar'theris Striker da Sar'theris Strand, in Desolace.$B$BFeralas Ahi da Verdantis River of Feralas.$B$BSavage Coast Blue Sailfin da Savage Coast, a Stranglethorn Vale.$B$BTorna da Nat Pagle quando li avrai tirati su tutti!",
  progress = "Oggi abbocca qualcosa?",
  reward = "Questa sì che è una bella pescata!$B$BVieni qua, ti faccio vedere come si calano le lenze.",
}
T[6608] = {
  title = "Tu Troppo $GBravo:Brava;.",
  desc = "Lumak no può più insegnare niente a $N. Tu troppo $Gbravo:brava;! Tu cerca amico di Lumak, Nat Pagle. Lui umano, ma no mangiare! Lui amico di Lumak! Nat insegna te pescare più meglio.$B$BTu trova Nat in Dustwallow Marsh, a sud di città di umanetti, Thermoroqualcosadelgenere. Probabile Nat pesca. Tu va' ora!",
  obj = "Pensi che Lumak stia cercando di dirti che non può più aiutarti a migliorare la tua abilità nella pesca. Forse dovresti provare a cercare il suo amico, Nat Pagle, un umano che pesca al largo di una delle isole a sud di Theramore (almeno, è quello che ti sembra abbia detto Lumak).",
  reward = "Ma certo, tu devi essere $Gun amico:un'amica; di Lumak.$B$BLa pesca? Te ne posso dire tutto quello che c'è da sapere.",
}
T[6609] = {
  title = "Non Ho Più Niente!",
  desc = "Sono un nano, per l'amor del cielo, $Gragazzo:ragazza;! Mica son nato per pescare! Ma dico, guardami! Sono fatto praticamente di pietra.$B$BNon ho più niente — mi hai spremuto fino all'ultima goccia. Ti ho insegnato tutto quello che so, pesce lesso!$B$BNon ci arrivi? Ah, e va bene. Laggiù a Kalimdor ho un vecchio amico che può darti una mano: si chiama Nat Pagle, un bravo ragazzo. Lo trovi sulle isole a sud di Theramore. Muoviti!",
  obj = "Viaggia fino a Kalimdor, nella città costiera di Theramore. Da lì dovrai cercare un'isola a sud della città principale. Nat Pagle attende il tuo arrivo!",
  reward = "Per gli ospiti, sulla mia isola, il posto c'è sempre... credo...",
}
T[6610] = {
  title = "Clamlette Surprise",
  desc = "Il bivalve, ne hai mai sentito parlare? Ma certo che no! È il mio ultimo capolavoro in cucina, e il più grande di tutti! Oh, $N, mi basta pensare a un bivalve e mi viene l'acquolina in bocca.$B$BPurtroppo sono rimasto senza ingredienti per farne! Facciamo un patto? Tu mi procuri quello che serve per preparare un bivalve, io ti insegno i segreti della cucina esotica e per giunta ti do pure un paio di bivalvi! Affare fatto??$B$BEcco di cosa ho bisogno:",
  obj = "Dirge Quikcleave vuole che tu prenda questi oggetti:$B$B12 Giant Eggs. Le troverai sui Roc che vagano per Tanaris o su qualsiasi altra specie di grosso uccello.$B$B10 pezzi di Zesty Clam Meat. Li troverai nei molluschi, naturalmente!$B$B20 pezzi di Alterac Swiss. Va' dunque a un caseificio!$B$BRaccogli tutti gli oggetti e torna da Dirge.",
  progress = "Queste voglie mi porteranno alla rovina! Sbrigati, $N — prima che metta mano alle scorte.",
  reward = "Ti aspetta una vera prelibatezza, $N. Guarda e impara!$B$B<Dirge si mette a preparare il clamlette surprise.>",
}
T[6611] = {
  title = "A Gadgetzan Devi Andare!",
  desc = "Come pensi che Zamja ti insegna qualcosa? Tu hai preso tutto il mojo da cucina di Zamja e ancora vuoi di più!$B$BZamja non può aiutare. $R $Gciccione:cicciona; deve andare a Gadgetzan. Là trovi un piccolo goblin che si chiama Dirge — lui aiuta te, $Gciccione:cicciona;.$B$BQuando tu diventi $Gun gran cuoco:una gran cuoca;, torni e insegni a Zamja, va bene? Ora vai!",
  obj = "Vai a Gadgetzan nel deserto di Tanaris e parla con Dirge Quikcleave per far progredire la tua carriera culinaria.",
  reward = "<Dirge sputa qualche pezzo di sandalo di cuoio.>$B$BPfftuì...$B$B<Dirge tossisce forte.>$B$BChe c'è? Guarda che il cuoio è sorprendentemente ricco di proteine e povero di carboidrati.",
}
T[6612] = {
  title = "Conosco un Tizio...",
  desc = "Si vede dal mestolo che sai il fatto tuo. Peccato che io non possa insegnarti niente.$B$BPer tua fortuna, conosco un tizio. È un goblin, e probabilmente è il miglior cuoco di Kalimdor.$B$BEh già, ed ecco la brutta notizia, $Gragazzo:ragazza; — ti tocca andare fino a Kalimdor. Vai a Gadgetzan e cerca Dirge Quikcleave: ti metterà lui sulla strada giusta.",
  obj = "Viaggia fino a Gadgetzan, nel deserto di Tanaris, e parla con Dirge Quikcleave per far progredire la tua carriera in cucina.",
  reward = "<Dirge sputa un pezzo di cuoio.>$B$BPfftey...$B$B<Dirge tossisce rumorosamente.>$B$BChe c'è? Sappi che il cuoio, chi l'avrebbe detto, è ricco di proteine e povero di carboidrati, $R.",
}
T[6621] = {
  title = "Il Re dei Foulweald",
  desc = "$N, a sud-est di Astranaar vive un'altra tribù di Furbolgs, i Foulweald. Sono meno numerosi dei Thistlefur, ma la loro ferocia è una minaccia per il futuro, e possiamo eliminarla con una dimostrazione di forza.$B$BPrendi questo stendardo, va' al villaggio dei Foulweald e piantalo sul loro tumulo totemico. Proveranno a distruggere lo stendardo: tu resisti finché non compare il loro capo, Murgut, a salvare l'onore della tribù. Portami il totem che ha con sé.$B$BRaduna i tuoi alleati, $N: non è un compito per $Gun:una; $C da $Gsolo:sola;.",
  obj = "Pianta il Karang's Banner sul Foulweald Totem Mound. Non lasciare che i furbolgs distruggano lo stendardo. Sconfiggi Chief Murgut e porta il Murgut's Totem a Karang Amakkar a Zoram'gar.",
  progress = "Allora, $N, hai sconfitto Chief Murgut? Il suo Totem dei Foulweald l'hai recuperato?",
  reward = "Ottimo lavoro, $N. Hai sfidato i Foulweald, hai sconfitto il loro capo, e così gli hai fatto capire bene una cosa:$B$BCon l'Orda non si scherza.$B$BPer un bel pezzo, credo, quella tribù non ci darà molti problemi.",
  en_title = "King of the Foulweald",
  en_obj = "Place Karang's Banner on the Foulweald Totem Mound.  Do not let the furbolgs destroy the banner.  Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar.",
}
T[6622] = {
  title = "Triage",
  desc = "Buongiorno, $Gdottore:dottoressa;. Oggi pomeriggio vedremo se sai fare il triage dei pazienti come si deve. Supera l'esame, ed entrerai nei prestigiosi ranghi della Traumatologia dell'Orda.$B$BOra fai attenzione! Prima si curano i feriti mortalmente, poi quelli feriti gravemente, e per ultimi gli altri feriti. Per superare l'esame devi salvare 15 pazienti: se durante il triage te ne muoiono 6, sarai $Gbocciato:bocciata;.$B$BRiceverai le Triage bandages.$B$BBuona fortuna, $Gdottore:dottoressa;.",
  obj = "Salva i pazienti medicandoli con le Triage Bandages. Devi salvare 15 pazienti prima che 6 di loro muoiano per le ferite.$B$BRicorda l'ordine del triage! I Critically Injured Soldiers muoiono più in fretta, seguiti dai Badly Injured Soldiers. Gli Injured Soldiers ci mettono di più a morire e vanno salvati DOPO aver fatto il triage dei Critically Injured e dei Badly Injured Soldiers.",
  progress = "Un lavoro miracoloso, $Gdottore:dottoressa;. Davvero miracoloso.",
  reward = "$GDottor:Dottoressa; $N, $Gbenvenuto:benvenuta; nella Traumatologia dell'Orda.",
}
T[6623] = {
  title = "Traumatologia dell'Orda",
  desc = "$GDottor:Dottoressa; $N, suppongo. Che piacere rivederti.$B$BHo notizie meravigliose per te! Doctor Gregory Victor, medico capo della Traumatologia dell'Orda, ha chiesto di persona che tu lo raggiunga a Hammerfall. Potrebbe essere l'occasione della vita! Io darei qualsiasi cosa per studiare con il grande Doctor Gregory Victor! Non sprecarla!",
  obj = "Vai a Hammerfall negli Arathi Highlands e parla con Doctor Gregory Victor per entrare nei ranghi della Traumatologia dell'Orda.",
  reward = "Magnifico. Infilati il camice e cominciamo subito!",
}
T[6624] = {
  title = "Triage",
  desc = "Buongiorno, $Gdottore:dottoressa;. Oggi pomeriggio verrai $Gesaminato:esaminata;: vedremo se sai fare il triage dei pazienti come si deve. Se passi l'esame, entrerai nei prestigiosi ranghi del Trauma dell'Alleanza.$B$BOra fai attenzione! Si curano per primi i feriti mortalmente, subito dopo i feriti gravemente e per ultimi i feriti. Per superare l'esame devi salvare 15 pazienti. Se durante il triage te ne muoiono 6, sei $Gbocciato:bocciata;.$B$BBuona fortuna, $Gdottore:dottoressa;.",
  obj = "Salva i pazienti curando le loro ferite con le Triage Bandages. Devi salvare 15 pazienti prima che 6 di loro muoiano per le ferite.$B$BRicorda l'ordine del triage! I Critically Injured Soldiers muoiono più in fretta, seguiti dai Badly Injured Soldiers. Gli Injured Soldiers ci mettono più tempo a morire e vanno salvati DOPO il triage dei Feriti Mortalmente e dei Badly Injured Soldiers.",
  progress = "Un lavoro miracoloso, $Gdottore:dottoressa;. Semplicemente miracoloso.",
  reward = "$GDottor:Dottoressa; $N, $Gbenvenuto:benvenuta; nel Trauma dell'Alleanza.",
}
T[6625] = {
  title = "Traumatologia dell'Alleanza",
  desc = "$GIl dottor:La dottoressa; $N, presumo. Che piacere vederti.$B$BHo una notizia meravigliosa per te! Gustaf VanHowzen, il primario della Traumatologia dell'Alleanza, ti vuole con sé a Theramore: l'ha chiesto lui di persona. Potrebbe essere l'occasione della vita! Io darei qualsiasi cosa per poter studiare con il grande dottor Gustaf VanHowzen! Non lasciartela scappare, $Gdottore:dottoressa;!",
  obj = "Viaggia fino a Theramore, in Dustwallow Marsh, e parla con Doctor Gustaf VanHowzen per entrare nelle file della Traumatologia dell'Alleanza.",
  reward = "Magnifico. Infilati il camice, che dobbiamo cominciare subito!",
}
T[6626] = {
  title = "Un Esercito del Male",
  desc = "Da quel che ho visto, i Forsaken non trasmettono la loro... malattia... Questo diplomatico, a quanto pare, concede la non morte a chi vuole seguirlo. Comincio a pensare che sia uno dello Scourge.$B$BPer ora, però, non è lui che mi preoccupa: sono le file sempre più numerose che lo circondano. Ogni giorno escono strisciando dall'ombra e quasi lo implorano di dar loro più potere.$B$BDa sola non sono abbastanza potente per affrontarli, $N. Che ne dici? Te la senti di andare a caccia?",
  obj = "Uccidi 8 Razorfen Battleguard, 8 Razorfen Thornweavers e 8 Death's Head Cultists e torna da Myriam Moonsinger vicino all'ingresso di Razorfen Downs.",
  progress = "Come procede la caccia, $N? Basta vedere qui questo piccolo assaggio del potere di quel diplomatico per togliermi ogni dubbio: lo Scourge è una delle minacce più grandi che questo mondo abbia mai visto.",
  reward = "Grazie, $N! Sono certa che il tuo lavoro sarà di grande aiuto.$B$BIo continuerò a studiare qui questo diplomatico e il resto dei quilboar. Se cerchi avventure più grandi, al tuo posto troverei qualche amico e andrei in quella grotta laggiù, quella che sembra un'enorme fauce di cinghiale. Lì dentro, ne sono sicura, troverai sfide più difficili.",
  en_title = "A Host of Evil",
  en_obj = "Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.",
}
T[6627] = {
  title = "Prova del Sapere",
  desc = "Mi hai portato il libro, e ora è arrivato il momento della tua domanda. Sei $Gpronto:pronta;?$B$BNon c'è fretta, $C, quindi non sentirti sotto pressione: prenditi tutto il tempo che vuoi per rispondere.",
  obj = "Rispondi correttamente alla domanda di Braug Dimspirit e poi parlagli di nuovo. Resterà nelle Stonetalon Mountains finché non sarai $Gpronto:pronta;.",
  progress = "La vita è piena di domande, $C. A tutte non riuscirai mai a rispondere, ma con il tempo e lo studio forse ne saprai un po' di più.",
  reward = "Ben fatto, $C. Hai studiato il testo che ti avevo chiesto, e così hai superato un'altra delle nostre prove.",
  en_title = "Test of Lore",
  en_obj = "Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready.",
}
T[6628] = {
  title = "Prova del Sapere",
  desc = "Dunque il momento è di nuovo arrivato. Da $Gstudioso:studiosa; del sapere, hai mostrato grande tenacia nell'accettare il mio compito.$B$BEd ecco la domanda. Se sei $Gpronto:pronta;, torna a parlarmi, e prenditi tutto il tempo che ti serve, $N — per rispondere non c'è fretta.",
  obj = "Rispondi correttamente alla domanda di Parqual Fintallas e poi parlagli di nuovo. Resterà a Undercity finché non sarai $Gpronto:pronta;.",
  progress = "Per sopravvivere in questo mondo, secondo me, c'è una sola regola da conoscere: più sai, più vedrai.$B$BSe studi, se osservi, comincerai a vedere del mondo cose che $Gnessun altro:nessun'altra; $R vedrà.",
  reward = "Ben fatto, $N. Avevo i miei dubbi che avessi studiato il testo che ti avevo chiesto di procurarmi, ma hai risposto correttamente.",
  en_title = "Test of Lore",
  en_obj = "Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready.",
}
T[6641] = {
  title = "Vorsha the Lasher",
  desc = "Vorsha the Lasher... la diabolica idra che vaga per i mari...$B$BHa attaccato il nostro avamposto senza che nessuno la provocasse, ogni volta, e ha distrutto tutto quello che le capitava davanti.$B$BMa io sono pronto, $N: mi sono preparato per sconfiggere l'idra e farla finita con i suoi attacchi a Zoram'gar.$B$BSu un'isola appena al largo della costa i naga tengono acceso un braciere per onorare la natura malvagia di questa bestia. Se lo spegniamo, credo che Vorsha comparirà infuriata.$B$BAvremo bisogno di aiuto, perciò porta con te qualche alleato forte.",
  obj = "Tieni al sicuro Muglash mentre si dirige al braciere. Aiutalo a spegnerlo, poi proteggilo mentre combatti contro i Naga.$B$BSe ci riesci, torna a Zoram'gar Outpost e informa Warsong Runner della morte di Vorsha the Lasher.",
  reward = "Da quando sono arrivato qui ho visto i naga attaccare molte volte. Sapere che Vorsha non vagherà più libera mi tranquillizza.$B$BSiamo in debito con te, $N.",
  en_title = "Vorsha the Lasher",
  en_obj = "Keep Muglash safe as he travels to the brazier. Help him by putting the brazier out, then protect him as you fight against the Naga.$B$BIf you are successful, return to the Zoram'gar Outpost and inform the Warsong Runner of the death of Vorsha the Lasher.",
}
T[6642] = {
  title = "Favore Presso la Confraternita, Dark Iron Ore",
  progress = "Anche se nelle Profondità abbonda, il Dark Iron resta per la Confraternita una merce preziosa: è il Dark Iron che prediligono le sacre armi e gli armamenti di Ragnaros.$B$BPer ogni 10 pezzi di Dark Iron Ore che offrirai, favore presso la Confraternita otterrai.",
  reward = "La tua offerta è stata accettata. Favore hai ottenuto. Continua così, e l'accesso agli antichi mestieri ti sarà concesso.",
}
T[6643] = {
  title = "Favore Presso la Confraternita, Fiery Core",
  progress = "Guai a chi sfida il destino dentro il Molten Core. Rapida giunge la morte — una punizione inflitta senza pietà.$B$BMolti della Confraternita sono andati perduti in cerca di Fiery Cores.$B$BOffri 1 Fiery Core, e favore presso la Confraternita ti sarà concesso.",
  reward = "La tua offerta è stata accettata. Favore hai ottenuto. Continua così, e l'accesso agli antichi mestieri ti sarà concesso.",
}
T[6644] = {
  title = "Favore Presso la Confraternita, Lava Core",
  progress = "The Thorium Brotherhood capisce in che difficile situazione ti trovi, $R, ed è per questo che a Lokhtos è stato dato il potere di contrattare.$B$BOffri 1 Lava Core, e favore presso la Confraternita ti sarà concesso.",
  reward = "La tua offerta è stata accettata. Favore hai ottenuto. Continua così, e l'accesso agli antichi mestieri ti sarà concesso.",
}
T[6645] = {
  title = "Favore Presso la Confraternita, Core Leather",
  progress = "Molte delle ricette sacre vogliono la pelle delle bestie predilette di Ragnaros.$B$BOffri 2 Core Leather, scuoiato dai cadaveri fumanti dei Core Hounds del Molten Core, e favore presso la Confraternita ti sarà concesso.",
  reward = "La tua offerta è stata accettata. Favore hai ottenuto. Continua così, e l'accesso agli antichi mestieri ti sarà concesso.",
}
T[6646] = {
  title = "Favore Presso la Confraternita, Blood of the Mountain",
  progress = "Una vera rarità sono le lacrime del Fire Lord.$B$BOffri 1 Blood of the Mountain, e favore presso la Confraternita ti sarà concesso.",
  reward = "La tua offerta è stata accettata. Favore hai ottenuto. Continua così, e l'accesso agli antichi mestieri ti sarà concesso.",
}
T[6661] = {
  title = "Caccia a Deeprun Rat",
  desc = "$GFermo:Ferma; là, canaglia. Arrrr... Arrrrivi in cerca di lavoro? Quaggiù abbiamo un brutto problema di ratti e troppo poche braccia sul cassero di poppa.$B$BChe ne dici? Devi solo prendere 'sto flauto acchiapparatti e suonarlo vicino a quei parassiti. Ti seguiranno fino ai confini del mondo!$B$BAcchiappane cinque, di quelle bestiacce, e portale qui. Ci servono vive.$B$BArrrrr...",
  obj = "Cattura 5 Deeprun Rats usando il Rat Catcher's Flute. Riporta i ratti da Monty. Quando hai finito, non dimenticare di restituire il flauto.",
  progress = "Yarrr... $GMarinaio:Marinaia; d'acqua dolce, come mai ci metti tanto?",
  reward = "Queste vanno benone, $Gcompagno:compagna;. Mio fratello le vuole ancora vive e vegete, sennò vanno a male... E uno spiedino di ratto guasto non vuoi mica assaggiarlo.",
  en_title = "Deeprun Rat Roundup",
  en_obj = "Capture 5 Deeprun Rats by using the Rat Catcher's Flute. Lead the rats back to Monty. Don't forget to turn in the flute when you're finished.",
}
T[6662] = {
  title = "Mio Fratello, Nipsy",
  desc = "Mio fratello, Nipsy, vende spiedini di ratto dall'altra parte di Deeprun. Devi portargli questa cassa di ratti prima che vadano a male. Muoviti!$B$BHai già viaggiato in tram, eh? È facile. Sali a bordo quando arriva e goditi la corsa. E durante il tragitto tieni braccia e gambe dentro, se non vuoi ritrovarti con una gamba di legno a vita.",
  obj = "Porta la Carton of Mystery Meat da Nipsy a Stormwind Deeprun Tram Depot.",
  progress = "<Nipsy infila l'indice in uno dei fori d'aerazione della scatola.>$B$BVivi e vegeti... e giusto in tempo!",
  reward = "Povero Monty. Dall'incidente di Gnomeregan non è più lo stesso. Quel ragazzo non ha mai visto l'oceano in vita sua, altro che pirata.$B$B<Nipsy sospira.>$B$BSe non altro, non mi fa mai mancare bestiole che si dimenano.",
  en_title = "Me Brother, Nipsy",
  en_obj = "Take the Carton of Mystery Meat to Nipsy at the Stormwind Deeprun Tram Depot.",
}
T[6681] = {
  title = "Il Maniero, Ravenholdt",
  desc = "$N,$B$BRavenholdt ha mostrato interesse per te, giovane $Gladro:ladra;, e ti abbiamo tenuto d'occhio. Hai uno stile un po' goffo, ma a questo possiamo rimediare.$B$BSe sei $Gpronto:pronta; a diventare $Gdiscepolo:discepola; di Master Ravenholdt e membro dell'Assassin's League, ti basta portare al Ravenholdt Manor il Seal of Ravenholdt (lo trovi allegato a questa lettera).$B$BCome primo compito dovrai trovare il maniero, che sta nascosto fra le colline di Hillsbrad, e dare prova della tua astuzia.$B$BCordiali saluti,$B$BFahrad",
  obj = "Porta il Seal of Ravenholdt a Fahrad al Ravenholdt Manor, nascosto tra le colline di Hillsbrad.$B$BLungo la strada la tua astuzia sarà messa alla prova. Tieniti $Gpronto:pronta;.",
  progress = "Hai incontrato Milton?$B$B<Fahrad ride.>",
  reward = "Eccellente davvero, giovane $Gladro:ladra;.$B$BSembri un po' $Gmalconcio:malconcia;, ma tutto sommato sei $Gintero:intera;.$B$BTi aspetta un lungo viaggio — lungo e ricco di soddisfazioni. Sei $Gpronto:pronta; ad abbracciare finalmente il tuo destino fra i maestri di Ravenholdt?$B$BParla con le guardie qui fuori. Sapranno dirti da dove cominciare.",
  en_title = "The Manor, Ravenholdt",
  en_obj = "Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.$B$BYour cunning will be tested along the way. Be prepared.",
}
T[6701] = {
  title = "Syndicate Emblems",
  progress = "Sono anni che siamo impantanati in una lotta contro lo Syndicate. Quello che non hanno in abilità lo compensano con il numero. È impossibile ucciderli tanto in fretta da vederli diminuire!$B$BAbbiamo scoperto che il modo migliore per tenere testa a una massa simile è rubargli gli emblemi. Chi si fa rubare l'emblema è disonorato, e ci pensano i suoi stessi compagni a 'sistemarlo'.$B$BRipuliscigli le tasche e porta gli emblemi a me o a qualunque altra guardia.$B$BComincia da Durnholde, qui a sud.",
  reward = "Ehi, bel lavoro! Continua così, e gli altri ladri potrebbero smetterla di sputarti addosso.",
  en_title = "Syndicate Emblems",
}
T[6721] = {
  title = "Il Sentiero del Cacciatore",
  desc = "Ciao, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza $Gesperto:esperta; da saper gestire una bestia e addestrarla come compagna.$B$BDevi andare da Dazalar a Dolanaar. Saprà indicarti la strada per guadagnarti un famiglio tutto tuo.",
  obj = "Parla con Dazalar a Dolanaar.",
  reward = "Sì, è giunto il momento, $C.",
  en_title = "The Hunter's Path",
  en_obj = "Speak with Dazalar in Dolanaar.",
}
T[6722] = {
  title = "Il Sentiero del Cacciatore",
  desc = "Ciao, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza $Gesperto:esperta; da saper gestire una bestia e addestrarla come compagna.$B$BDevi andare da Dazalar a Dolanaar. Saprà indicarti la strada per guadagnarti un famiglio tutto tuo.",
  obj = "Parla con Dazalar a Dolanaar.",
  reward = "Sì, è ora di addestrarti...",
  en_title = "The Hunter's Path",
  en_obj = "Speak with Dazalar in Dolanaar.",
}
T[6741] = {
  title = "Altro Bottino!",
  progress = "Mi servono altri armor scraps, $N! Ne hai qualcuno?",
  reward = "Grazie ancora, $N. L'Orda è fiera di te...",
}
T[6761] = {
  title = "La Nuova Frontiera",
  desc = "Ho affidato al mio secondo, Mathrengyl Bearwalker, la richiesta d'aiuto di Moonglade. Parla con lui di questa faccenda — NON con me.$B$BTi do un consiglio... amichevole... Sono stato io a guidarci fuori dalle tenebre — NON il Cenarion Circle di Moonglade — quando per la nostra razza tutto era perduto. Teldrassil dà a tutti noi una nuova vita! Loro vorrebbero farti credere il contrario, e sarebbe stupido dar retta alla loro propaganda.$B$BLascio a te decidere se sei $Guno stolto:una stolta; o no.",
  obj = "Parla con Mathrengyl Bearwalker a Cenarion Enclave of Darnassus.",
  reward = "Sì, $C, grazie di essere $Gvenuto:venuta;. Mi scuso per il malinteso... tra l'Arcidruido e Keeper Remulos di Moonglade si respira una diffidenza fortissima. Ognuno sospetta l'altro di imbrogli, e qui le strane corruzioni di Teldrassil, che continuano senza sosta, restano un problema. E di certo questo non aiuta a placare i sospetti.$B$BIn ogni caso, il nostro dovere verso il Cenarion Circle rimane... anche se i suoi capi possono essere in disaccordo tra loro.",
}
T[6762] = {
  title = "Rabine Saturna",
  desc = "Per questo compito, il maggiordomo di Keeper Remulos a Moonglade — Rabine Saturna — cerca aiuto per esplorare le vaste terre desolate molto a ovest di Tanaris... e ancora più a ovest di Un'Goro. Lo troverai a Nighthaven, il villaggio principale di Moonglade.$B$BIl tuo lavoro sarà senza dubbio di enorme beneficio per tutti noi, ma ti consiglio di muoverti con cautela. Tra Darnassus e Moonglade ci sono tensioni... che col tempo potrebbero crescere.",
  obj = "Parla con Rabine Saturna nel villaggio di Nighthaven, a Moonglade. Moonglade si trova tra Felwood e Winterspring, e si raggiunge da un sentiero che parte da Timbermaw Hold.",
  reward = "Sono Rabine Saturna, e a nome di Keeper Remulos e di tutti gli abitanti di questa radura sacra ti do il benvenuto.$B$BApprezzo il tuo interesse e il tuo desiderio di aiutare il Cenarion Circle. So anche che l'Arcidruido di Darnassus ti ha espresso il suo disappunto per l'aiuto che ci dai. Ti assicuro che è per un bene più grande, e che sarai al sicuro da qualunque ritorsione sconsiderata possa colpirti.$B$BQui sei tra amici, $N.",
}
T[6781] = {
  title = "Altri Armor Scraps",
  progress = "$N, ci servono altri armor scraps per rifornire le truppe!",
  reward = "Questi pezzi sono buoni, $N. Ci posso fabbricare equipaggiamento nuovo per le nostre truppe.$B$BSe le scorte salgono abbastanza, forse le nostre unità da combattimento più esperte scenderanno in campo!",
}
T[6801] = {
  title = "Lokholar the Ice Lord",
  progress = "Vengo da Thunder Bluff, $R. È stato Cairne in persona a volere che assistessi il Frostwolf Clan in questi tempi terribili.$B$BMa non perdiamo altro tempo: devi abbattere i nostri nemici e portarmi il loro sangue. Quando ne avremo raccolto abbastanza, potrà cominciare il rituale di evocazione.$B$BUna volta scatenato il signore elementale contro l'esercito Stormpike, la vittoria sarà certa.",
  reward = "Il sangue dei nostri nemici è stato versato. Mescolerò questo sangue con quello che abbiamo già raccolto, e quando l'offerta sarà completa il Signore del Ghiaccio mostrerà a questi cani Stormpike tutta l'ira del Frostwolf Clan!",
}
T[6804] = {
  title = "Acqua Avvelenata",
  desc = "Una squadra di esploratori elementali è stata mandata nelle terre appestate orientali di Lordaeron, e la malattia che regna laggiù li ha deformati e infettati. I Signori delle Acque non possono tollerare un simile affronto alla nostra purezza!$B$BPrendi questa fiala: contiene un po' di uno degli aspetti di Neptulon. Usalo sugli elementali appestati, e combatterà il veleno nei loro corpi e li curerà! Però il conflitto che si scatenerà dentro di loro li getterà in una follia travolgente.$B$BSconfiggi le discordant surges e portami i bracciali del vincolo che portano addosso.",
  obj = "Usa l'Aspect of Neptulon sugli elementali avvelenati delle Eastern Plaguelands. Porta 12 Discordant Bracers e l'Aspect of Neptulon a Duke Hydraxis ad Azshara.",
  progress = "Hai portato i bracciali?",
  reward = "Hai fatto bene, $C. Gli elementali corrotti che hai curato erano un oltraggio per tutte le acque. La purezza è la nostra forza, e se vogliamo vincere la guerra contro gli altri dobbiamo restare forti.",
}
T[6805] = {
  title = "Assaltatori e Rimbombanti",
  desc = "Noi elementali dell'acqua siamo in guerra con gli esseri degli elementi inferiori. Se in questo conflitto sei davvero $Gnostro alleato:nostra alleata;, dimostrami la tua convinzione!$B$BLontano a sud, nel deserto di Silithus, c'è un angolo di roccia chiamato Crystal Vale, dove brulicano i servitori dell'aria e della terra. Lì proteggono oggetti di potere dagli esseri più piccoli, i mortali: non so perché lo facciano, ma voglio rendere vani i loro sforzi.$B$BVa' nella Crystal Vale a Silithus, sconfiggi i nostri nemici e torna da me.",
  obj = "Uccidi 15 Dust Stormers e 15 Desert Rumbers, poi torna da Duke Hydraxis ad Azshara.",
  progress = "Non abbiamo stima per la codardia, $C. Va' a Silithus e dimostra il tuo coraggio.",
  reward = "Hai dimostrato il tuo coraggio, e anche il tuo valore per noi. Forse un giorno avrò altri compiti per te, più adatti a $Gun prezioso alleato:una preziosa alleata; dei Signori delle Acque.",
}
T[6821] = {
  title = "Eye of the Emberseer",
  desc = "Mi hai dimostrato di saper sconfiggere i nostri nemici e di saper compiere missioni che fanno avanzare la causa dei Signori delle Acque. Ma finora hai affrontato solo avversari minori... e $Gmesso:messa; di fronte a un nemico potente, avresti la meglio?$B$BEcco il tuo nuovo compito.$B$BNella parte alta di Blackrock Spire gli orchi hanno catturato un servitore del fuoco, Pyroguard Emberseer. Trova il luogo dove lo tengono prigioniero, elimina i carcerieri e poi uccidi il Mirabraci. Portami il suo occhio: mi mostrerà quanto vali.",
  obj = "Porta l'Eye of the Emberseer a Duke Hydraxis ad Azshara.",
  progress = "Allora, $C, hai l'Occhio? Ce l'hai la forza per entrare in Blackrock Spire?",
  reward = "Ah, allora la forza ce l'hai. E anche l'astuzia, perché per Blackrock Spire la forza bruta da sola non basta.$B$BIn verità, $N, potresti ancora rivelarti $Gun alleato prezioso:un'alleata preziosa; per noi...",
}
T[6822] = {
  title = "The Molten Core",
  desc = "$N, forse è arrivato il momento di metterti davvero alla prova. Sei $Gpronto:pronta;?$B$BIn fondo ai Blackrock Depths un passaggio porta al Molten Core, una roccaforte del nostro nemico presidiata dai servitori del fuoco più potenti di questo mondo.$B$BEntra nel Molten Core, $N, e dimostrami che hai la forza e la volontà di sconfiggere quello che ci troverai.$B$BE se fra la tua gente hai degli alleati, radunali: solo un esercito può sperare di entrare nel Molten Core e uscirne vivo.",
  obj = "Uccidi 1 il Fire Lord, 1 Molten Giant, 1 Ancient Core Hound e 1 Lava Surger, poi torna da Duke Hydraxis ad Azshara.",
  progress = "Il successo ti aspetta nel Molten Core, $N.",
  reward = "Hai fatto quello che quasi tutti i tuoi simili riterrebbero impossibile. Hai affrontato gli esseri del Molten Core e hai trionfato!$B$BPer una creatura così piccola, hai dimostrato di avere grandi risorse.$B$BForse, un giorno, potremmo stringere una vera alleanza fra la tua gente e i Signori delle Acque.",
}
T[6823] = {
  title = "Agente di Hydraxis",
  desc = "Se desideri davvero allearti con noi, ti invito a muovere guerra ai nostri nemici: i servitori dell'aria, della terra e del fuoco. Ogni sconfitta che infliggerai loro ne indebolirà la presenza qui, e proverà ancora di più la tua fedeltà alla nostra causa.$B$BSarà una campagna lunga, ma se persevererai, grandi saranno la tua gloria e il tuo onore.",
  obj = "Ottieni la reputazione Onorato con gli Hydraxian Waterlords, poi parla con Duke Hydraxis ad Azshara.",
  progress = "La tua campagna non è ancora finita, $N. Va' a sconfiggere i nostri nemici, i servitori dell'aria, della terra e del fuoco, e forse un giorno ti guadagnerai un posto nella sala dei Signori delle Acque.",
  reward = "Nelle sale dei Signori delle Acque risuonano le tue imprese contro i nostri nemici, $N. C'era chi pensava che il tuo corpo fosse troppo piccolo e fragile per prendere parte alla nostra guerra, ma hai ottenuto grandi successi. Hai conquistato il nostro rispetto, ed è un'impresa incredibile.",
}
T[6824] = {
  title = "Le Mani del Nemico",
  desc = "$N, i tuoi servigi ci sono preziosi, ed è per questo che esitiamo a mandarti in quest'ultima missione: non vogliamo perdere $Gun agente così utile:un'agente così utile;.$B$BMa se riuscisse, darebbe un enorme impulso alla nostra guerra e... si è deciso che valeva la pena di metterti a rischio.$B$BVogliamo che siano distrutti questi capitani del Molten Core: Lucifron, Sulfuron, Gehennas e Shazzrah. Uccidili e portami le loro mani!$B$BÈ un compito che richiederà tutte le tue risorse, $N, ma se ci riuscirai, ai Firelords infliggerai un colpo terribile.",
  obj = "Porta le Hands of Lucifron, Sulfuron, Gehennas e Shazzrah a Duke Hydraxis ad Azshara.",
  progress = "$N, hai sconfitto Lucifron e gli altri? Hai le mani del nemico?",
  reward = "Hai le mani! Hai sconfitto i capitani del fuoco! Se non ti conoscessi e non sapessi di cosa sei capace, non l'avrei creduto possibile.$B$B$N, le tue imprese non si contano, ma la notizia di quest'ultima solleverà onde fra i Signori delle Acque. Un giorno il tuo nome potrebbe diventare per noi una leggenda.$B$BTorna a parlarmi, $N: potrei avere un altro compito ancora...",
}
T[6825] = {
  title = "Richiamo dell'Aria — Guse's Fleet",
  progress = "Dobbiamo preparare la nuova flotta di War Riders, $R! I miei cavalieri sono pronti ad attaccare sul campo di battaglia centrale; ma prima devo stuzzicargli l'appetito — prepararli all'assalto.$B$BMi serve abbastanza Carne di Soldato degli Stormpike da sfamare una flotta! Centinaia di libbre! Ce la puoi fare di sicuro, vero? Muoviti!",
  reward = "La flotta si nutre della loro carne. Divora il nemico.$B$BPresto spiccheremo il volo!",
}
T[6826] = {
  title = "Richiamo dell'Aria — Jeztor's Fleet",
  progress = "Hai lavorato sodo, $N, ma siamo solo all'inizio!$B$BI miei War Riders devono assaggiare la carne dei loro bersagli: così avremo la certezza di un attacco chirurgico contro i nostri nemici!$B$BLa mia flotta è la seconda per potenza del nostro comando aereo, quindi colpirà i più potenti fra i nostri avversari. Ecco perché le serve la carne dei Luogotenenti Stormpike.$B$BSbrigati, $Gsoldato:soldatessa;!",
  reward = "Ancora! Ancora! Portane dell'altra, perché presto saranno pronti!",
}
T[6827] = {
  title = "Richiamo dell'Aria — Mulverick's Fleet",
  progress = "Sono rimasto rinchiuso per giorni in un buco infernale dei nani: puoi scommetterci che voglio vendetta!$B$BDobbiamo pianificare tutto con attenzione.$B$BPrima di tutto, ai miei war riders servono bersagli da puntare — bersagli ad alta priorità. Li dovrò nutrire con la carne dei Comandanti Stormpike. Peccato che quelle piccole canaglie se ne stiano trincerate ben dietro le linee nemiche! Ti aspetta proprio un bel lavoro.",
  reward = "Non basta! Un lavoro del genere me lo aspetterei da un novellino, ma da te, $N? Forza, $Gsoldato:soldatessa;! MUOVITI! Serve altra carne!",
}
T[6844] = {
  title = "Umber, Archivista",
  desc = "C'è ancora molto da fare qui, ma credo sia fondamentale portare questo oggetto al Circolo perché lo analizzi. Fidati — il lavoro sarà ancora qui quando avremo chiuso questa faccenda. Se dentro questa chitina appiccicosa c'è un diario, il Circolo avrà finalmente una finestra sul passato!$B$BPortalo all'archivista del Circolo a Nighthaven. Si chiama Umber, ed è un uomo geniale. Un po' svitato, certo, ma geniale comunque! Umber ha recuperato tomi ridotti molto peggio di così. Se si può salvare, lui ci riuscirà.",
  obj = "Porta l'Encrusted Silithid Object a Umber — l'archivista del Cenarion Circle — nel villaggio di Nighthaven, a Moonglade.",
  progress = "Ma salve! Hrmm...$B$BLascia che sia un po' sincero con te, $Gamico:amica;... hai un odorino non proprio fresco. Puzzolentino, si potrebbe dire. Non è un assalto personale al tuo essere, sia chiaro. Dico solo che... in futuro potresti darti una rinfrescata dopo essere $Grientrato:rientrata; dal campo. Così le prime impressioni saranno un po' più positivamente impressionanti!$B$BEhm, comunque... cosa posso fare per te?",
  reward = "Ma per mille rospi e scimmie! Che cos'hai lì? Ha più o meno la forma di un libro, direi... proverò a rompere questo guscio.$B$BTi ha mandato da me Layo, da Silithus? Ho sentito solo qualche voce che rimbomba molto in sordina — che poi, a pensarci bene, se rimbomba tanto in sordina non è — sugli orrori che succedono laggiù. Aggiungici che non vado matto per niente che somigli a un insetto, ed ecco la ricetta perfetta per restarmene qui con i libri!",
}
T[6845] = {
  title = "Svelare i Segreti del Passato",
  desc = "Comunque, faresti bene a ripassare da me fra non molto... sempre che tu voglia sapere cosa c'era qui dentro. Appena scopro cos'è, e se è davvero un libro, te lo dico volentieri.$B$BNel frattempo, io passerei dalla mamma orsa di questo piccolo accampamento di orsi, Rabine. Di sicuro vorrà sapere che pazzie hai combinato. Mai far aspettare la mamma orsa, $N... a meno che tu non voglia ritrovarti $Gcoperto:coperta; di miele.$B$BÈ già successo, fidati.",
  obj = "Parla con Rabine Saturna nel villaggio di Nighthaven, a Moonglade.",
  reward = "Ah, $N — speravo che saresti $Gpassato:passata;. Sono lieto di vederti in salute.$B$BMi è giunta voce che saresti $Gtornato:tornata; dal campo, e volevo esprimerti di persona la gratitudine del Cenarion Circle per l'aiuto che ci hai dato finora. Di sicuro ci sono altri segreti da svelare a Silithus; ciò che hai consegnato a Umber dovrebbe rivelarsi molto interessante, una volta scoperto il contenuto. Ti prego, accetta questo dono in segno della riconoscenza che continuiamo a provare per il tuo sostegno.$B$BGrazie, $Ggeneroso:generosa; $C.",
}
T[6846] = {
  title = "Iniziate l'Attacco!",
  progress = "Le mie truppe hanno avuto i rifornimenti e sono pronte all'assalto. Mancano solo gli ordini di Noreg Stormpike, poi le mando nella mischia!",
  reward = "Ah, gli ordini! Devo attaccare a mia discrezione, dicono. E la mia discrezione dice... adesso!",
}
T[6847] = {
  title = "Master Ryson's All Seeing Eye",
  desc = "Allo Syndicate non importa nulla della tua guerra nel cuore di Alterac, $C. Faremo quello che abbiamo sempre fatto: aspetteremo che dalle ceneri e dalle macerie di questa follia esca un vincitore netto, e allora colpiremo.$B$BMa adesso non siamo qui per questo. L'Occhio Onniveggente è andato perduto — se lo sono preso i troll Winterax di queste parti.$B$BRecupera l'Occhio e i nostri servigi saranno tuoi — finché la tua parte durerà.$B$BQuando avrai l'occhio torna da me, così potrò esaminarti.$B$B<Master Ryson sogghigna.>",
  obj = "Recupera il Master Ryson's All Seeing Eye dalle grotte dei Winterax e riportalo a Master Ryson.$B$BAttenzione, si dice che il Master Ryson's All Seeing Eye porti con sé una terribile maledizione!",
}
T[6848] = {
  title = "Master Ryson's All Seeing Eye",
  desc = "Allo Syndicate non importa nulla della tua guerra nel cuore di Alterac, $C. Faremo quello che abbiamo sempre fatto: aspetteremo che dalle ceneri e dalle macerie di questa follia esca un vincitore netto, e allora colpiremo.$B$BMa adesso non siamo qui per questo. L'Occhio Onniveggente è andato perduto — se lo sono preso i troll Winterax di queste parti.$B$BRecupera l'Occhio e i nostri servigi saranno tuoi — finché la tua parte durerà.$B$BQuando avrai l'occhio torna da me, così potrò esaminarti.$B$B<Master Ryson sogghigna.>",
  obj = "Recupera il Master Ryson's All Seeing Eye dalle grotte dei Winterax e riportalo a Master Ryson.$B$BAttenzione, si dice che il Master Ryson's All Seeing Eye porti con sé una terribile maledizione!",
}
T[6861] = {
  title = "Zinfizzlex's Portable Shredder Unit",
  desc = "Non vedo l'ora di provare la mia unità segatronchi portatile, $R, proprio come te, ma per costruire il kit mi servono materiali — un sacco di materiali!$B$BPer la precisione, mi ci vuole una montagna di torio, mithril e ferro, più una sega a vapore per ogni unità. Le seghe dovrai procurartele alla segheria.$B$BMentre ficcanasavo da queste parti (prima che mi catturassero) ho visto una pila di seghe a vapore all'accampamento dei taglialegna degli Stormpike.",
  obj = "Master Engineer Zinfizzlex vuole che tu gli porti quanto segue:$B$B*30 Thorium Bars.$B$B*50 Mithril Bars.$B$B*75 Iron bars.$B$B*1 Steamsaw.",
  progress = "Non vedo l'ora di provare la mia unità segatronchi portatile, $R, proprio come te, ma per costruire il kit mi servono materiali — un sacco di materiali!$B$BPer la precisione, mi ci vuole una montagna di torio, mithril e ferro, più una sega a vapore per ogni unità. Le seghe dovrai procurartele alla segheria.$B$BMentre ficcanasavo da queste parti (prima che mi catturassero) ho visto una pila di seghe a vapore all'accampamento dei taglialegna degli Stormpike.$B$BMaster Engineer Zinfizzlex vuole che tu gli porti quanto segue:",
}
T[6862] = {
  title = "Zinfizzlex's Portable Shredder Unit",
  desc = "Non vedo l'ora di provare la mia unità segatronchi portatile, $R, proprio come te, ma per costruire il kit mi servono materiali — un sacco di materiali!$B$BPer la precisione, mi ci vuole una montagna di torio, mithril e ferro, più una sega a vapore per ogni unità. Le seghe dovrai procurartele alla segheria.$B$BMentre ficcanasavo da queste parti (prima che mi catturassero) ho visto una pila di seghe a vapore all'accampamento dei taglialegna dei Frostwolf.",
  obj = "Master Engineer Zinfizzlex vuole che tu gli porti quanto segue:$B$B*30 Thorium Bars.$B$B*50 Mithril Bars.$B$B*75 Iron bars.$B$B*1 Steamsaw.",
  progress = "Non vedo l'ora di provare la mia unità segatronchi portatile, $R, proprio come te, ma per costruire il kit mi servono materiali — un sacco di materiali!$B$BPer la precisione, mi ci vuole una montagna di torio, mithril e ferro, più una sega a vapore per ogni unità. Le seghe dovrai procurartele alla segheria.$B$BMentre ficcanasavo da queste parti (prima che mi catturassero) ho visto una pila di seghe a vapore all'accampamento dei taglialegna degli Stormpike.$B$BMaster Engineer Zinfizzlex vuole che tu gli porti quanto segue:",
}
T[6881] = {
  title = "Ivus the Forest Lord",
  progress = "Una contaminazione di energia elementale protegge il Frostwolf Clan. I loro sciamani si immischiano in poteri che, se nessuno li fermerà, di certo ci distruggeranno tutti.$B$BOrmai il danno è troppo grande perché il Circolo possa tenerlo sotto controllo! Dobbiamo chiamare Ivus in nostro aiuto.$B$BI soldati Frostwolf portano con sé dei talismani elementali chiamati storm crystals, e con quei talismani possiamo evocare Ivus. Mettiti in cammino e prendi i cristalli, $N!",
  reward = "Ben fatto, $N. Con il potere di questo talismano accrescerò la magia già raccolta. Quando ne avremo accumulato abbastanza, concentrerò le energie riunite e invocherò il Forest Lord in aiuto della nostra causa.",
}
T[6901] = {
  title = "Lancia l'Attacco!",
  progress = "Ho le truppe rifornite e pronte all'assalto. Ci servono solo gli ordini del Frostwolf Quartermaster, e poi le mando nella mischia!",
  reward = "Era ora! Adesso possiamo far capire all'Alleanza quanto è stata folle a venire nell'Alterac Valley!",
}
T[6921] = {
  title = "Tra le Rovine",
  desc = "Il Twilight's Hammer si è stabilito nelle Moonshrine Ruins of Blackfathom Deeps. La loro presenza non può che costringere gli elementi ad agire contro di noi. Se nessuno li ferma, questa regione sarà loro per sempre.$B$B$N, vai a Blackfathom e cerca la pietra degli abissi delle rovine: dovrebbe essere da qualche parte lì vicino, in acqua. Dentro c'è un fathom core — un congegno che, a saperlo leggere nel modo giusto, racconta la storia di tutta l'attività elementale. Se riesco ad averlo, io e l'Earthen Ring forse potremo fare qualcosa per fermarli!",
  obj = "Porta il Fathom Core a Je'neu Sancrea, a Zoram'gar Outpost, Ashenvale.",
  progress = "Sei $Griuscito:riuscita; a trovare il fathom core? Senza, non avremo idea di cosa stia combinando di preciso laggiù il Twilight's Hammer.",
  reward = "È proprio quello che mi serve! Un fathom core è un pozzo incredibile di informazioni, da cui potremo attingere tanto. Qualunque cosa stia tramando là dentro il Twilight's Hammer — e credimi, non è niente di buono — adesso io e i miei compagni la scopriremo.$B$BOggi hai fatto un buon lavoro, e l'Earthen Ring ti guarda con favore per la mano che ci hai dato. Hai aiutato anche tutta l'Orda, e dovresti andarne $Gfiero:fiera;.",
  en_title = "Amongst the Ruins",
  en_obj = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
}
T[6922] = {
  title = "Baron Aquanis",
  desc = "Il water elemental che hai sconfitto ha lasciato dietro di sé uno strange water globe, e ti viene da pensare che fosse l'oggetto, in qualche modo, a dare energia alla bestia. Dentro si agita una specie d'acqua dall'aria putrida, e il globo sembra resistere a qualunque forza fisica.$B$BSe c'è qualcuno che può capirci qualcosa, è Je'neu Sancrea of the Earthen Ring, che si trova allo Zoram'gar Outpost dell'Orda, ad Ashenvale.",
  obj = "Porta lo Strange Water Globe a Je'neu Sancrea a Zoram'gar Outpost, Ashenvale.",
  progress = "Ah, salve di nuovo, $N. Ero qui a leggere le onde del mare, come faccio sempre. Che ti porta all'avamposto?",
  reward = "Questa... questa sì che è una bella scoperta, $N.$B$BDici che l'hai preso da Baron Aquanis, a Blackfathom? È da tempo che si pensa che Baron Aquanis sia una potenza elementale corrotta; con questo globo vedremo cos'è, di preciso, che l'ha corrotto. Non sarebbe una sorpresa se fosse stato il Twilight's Hammer, ma dai nostri studi capiremo anche come ci sono riusciti.$B$BHai fatto bene a portarmelo. Ti prego — prendi questo, insieme ai saluti più calorosi dell'Earthen Ring.",
  en_title = "Baron Aquanis",
  en_obj = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
}
T[6941] = {
  title = "Richiamo dell'Aria — Vipore's Fleet",
  progress = "Dobbiamo occuparci delle unità d'élite dei Frostwolf che sorvegliano le linee, $Gsoldato:soldatessa;! A te affido il compito di sfoltire quella mandria di selvaggi: torna da me con le medaglie dei loro luogotenenti e legionari. Quando giudicherò che abbiamo tolto di mezzo abbastanza marmaglia, ordinerò l'attacco aereo.",
  reward = "Fra poco lo stormo sarà pronto. Continua così!",
}
T[6942] = {
  title = "Richiamo dell'Aria — Slidore's Fleet",
  progress = "I miei grifoni sono pronti a colpire la prima linea, ma finché le linee non saranno sfoltite non possono attaccare.$B$BI guerrieri Frostwolf che hanno il compito di tenere la prima linea portano sul petto, con orgoglio, medaglie di servizio. Strappa quelle medaglie dai loro cadaveri putridi e portamele qui.$B$BQuando la prima linea sarà sfoltita abbastanza, lancerò il richiamo dell'aria! Morte dall'alto!",
  reward = "Portane ancora, $Gsoldato:soldatessa;! In un attimo gli Aerie gryphons saranno pronti a colpire!",
}
T[6943] = {
  title = "Richiamo dell'Aria — Ichman's Fleet",
  progress = "Hanno il morale a terra, soldato. Dopo il nostro ultimo attacco aereo fallito contro l'Orda, si rifiutano di volare! Sta a te risollevarglielo.$B$BTorna sul campo di battaglia e colpisci al cuore il comando dei Frostwolf: abbatti i loro comandanti e i loro guardiani, e riportami tutte le medaglie che riesci a ficcare nello zaino! Te lo prometto: quando i miei grifoni vedranno il bottino e sentiranno l'odore del sangue nemico, torneranno a volare! Ora va'!",
  reward = "Vedi? Guardali, soldato! Si stanno riprendendo... Presto lo stormo di Ichman tornerà a colpire il cuore della valle! Gli Stormpike domineranno i cieli!",
}
T[6961] = {
  title = "Great-father Winter È Qui!",
  desc = "Ti auguro un Winter Veil splendido, $Gamico:amica;! E non dimenticare di salutare Greatfather Winter! Se quest'anno sei $Gstato:stata; $Gbuono:buona;, il giorno della Feast of Winter Veil riceverai dei dolcetti meravigliosi. Mi raccomando, digli cosa speri di ricevere!$B$BRicordati anche di fare scorta di dolcetti da regalare a chi quest'anno è stato buono: ne abbiamo di ogni tipo. Dalla nostra fattoria alla tua tavola — è la genuina bontà di Smokywood Pastures!",
  obj = "Parla con Greatfather Winter, che si trova vicino all'area dei venditori di Smokywood Pastures a Orgrimmar.",
  reward = "Oh oh ohilà. Io sono Greatfather Winter, e io — per gentile concessione della brava gente di Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola, è la genuina bontà di Smokywood Pastures\" — vorrei augurarti una fantastica Feast of Winter Veil.$B$BSe quest'anno sei $Gstato:stata; $Gbuono:buona;, può darsi che per la Feast of Winter Veil ti arrivino in regalo i dolcetti di Smokywood Pastures. Urrà.",
  en_title = "Great-father Winter is Here!",
  en_obj = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.",
}
T[6962] = {
  title = "Dolcetti per Great-father Winter",
  desc = "Ehi, faresti un favore a Greatfather Winter, ehm, $Gpiccolo:piccola;?$B$BNon che voglia parlare di me in terza persona senza motivo, ma Greatfather Winter lavora da tutto il giorno, e anche a lui farebbe comodo un dolcetto. Un po' di gingerbread cookies, con dell'ice cold milk per mandarli giù, ci starebbero proprio bene. Te la senti di essere $Gun amico:un'amica; del Babbo e procurarmeli?",
  obj = "Porta 5 Gingerbread Cookies e un Ice Cold Milk a Greatfather Winter a Orgrimmar.",
  progress = "A furia di parlare di dolcetti è venuta voglia anche a me. Mmmm... Gingerbread cookies e latte...",
  reward = "Sei proprio $Gun grande aiutante:una grande aiutante; del vecchio Greatfather Winter, $N. Buona Feast of Winter Veil.$B$BEcco un pensierino... sai, per il disturbo.",
  en_title = "Treats for Great-father Winter",
  en_obj = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Great-father Winter in Orgrimmar.",
}
T[6963] = {
  title = "Dolcetti Rubati di Winter Veil",
  desc = "Senti... non voglio rovinare la magia di questo periodo, ma a Smokywood Pastures farebbe comodo un po' d'aiuto — di quello per cui voi avventurieri andate famosi.$B$BNon ci è arrivata un'importante spedizione di dolcetti che doveva rifornirci per le feste, e ora è sparito anche l'agente di Smokywood Pastures che avevamo mandato a cercarla! Ti prego — l'ultima segnalazione della spedizione arriva dalle Alterac Mountains, ed è lì che il nostro uomo è andato a cercarla.$B$BGuarda se li trovi entrambi lassù, sani e salvi!",
  obj = "Trova l'investigatore di Smokywood Pastures scomparso nelle regioni innevate delle Alterac Mountains.",
  reward = "M-m-mi senti! Sia l-l-lodato il b-b-bilancio!$B$BNon sono m-m-mica un p-p-pupazzo di neve — mi c-c-chiamo Sacks, e l-l-lavoro per Smokywood Pastures, alla f-f-filiale di Orgrimmar... Mi hanno m-m-mandato qui a cercare un p-p-pacco scomparso, e mi ha attaccato una c-c-creatura che non avevo mai visto p-p-prima!$B$BFa v-v-veramente tanto f-f-freddo...",
  en_title = "Stolen Winter Veil Treats",
  en_obj = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.",
}
T[6964] = {
  title = "Il Vero Senso della Stagione",
  desc = "Regali, dolcetti, doni... bah, dico io!$B$BQuei goblin snaturano il vero senso di questa stagione — The Feast of Winter Veil. È un tempo di rinnovamento: la terra dorme sotto una coltre di neve portata da Greatfather Winter, che NON è quel goffo sciocco laggiù vestito di rosso!$B$BSe vuoi scoprire da $Gsolo:sola; che cosa sia davvero la Festa, chiedi a Sagorne Creststrider. Sono certo che si stupirà nel vedere che a qualcuno importa della storia più che dei regali.",
  obj = "Parla con Sagorne Creststrider, in Valley of Wisdom a Orgrimmar, riguardo a The Feast of Winter Veil.",
  reward = "The Feast of Winter Veil, dici? Ahimè, un tempo aveva un significato più profondo per noi tauren. Oggi sembra che altri abbiano trasformato la leggenda di questa stagione di rinnovamento in qualcosa che aiuta a vendere dolciumi e regali.$B$BNon mi sorprende che Furmund sia amareggiato da un cambiamento simile. Lui e i tauren come lui si aggrappano al nostro passato come a uno stendardo di guerra. Anche se credo che un po' di festa faccia sempre bene, è importante ricordare le origini della Festa.",
  en_title = "The Reason for the Season",
  en_obj = "Speak with Sagorne Creststrider in the Valley of Wisdom of Orgrimmar about the Feast of Winter Veil.",
}
T[6981] = {
  title = "La Glowing Shard",
  desc = "La scheggia è di un verde brillante e, per quanto sia solida, appena sotto la superficie sembra che vortichi del fumo. Non riesci a staccare gli occhi dalle profondità del cristallo; eppure sai che ha qualcosa di molto inquietante.$B$BForse dovresti cercare a Ratchet qualcuno che ne sappia di più su questa strana scheggia.",
  obj = "Raggiungi Ratchet per trovare qualcuno che possa dirti di più sulla glowing shard.$B$BPoi consegna la scheggia come ti verrà indicato.",
  progress = "Salve, $R. Cosa posso fare per te?",
  reward = "Oh... Non ho mai visto niente del genere...",
  en_title = "The Glowing Shard",
  en_obj = "Travel to Ratchet to find someone that can tell you more about the glowing shard.$B$BThen, deliver the shard as you are directed.",
}
T[6982] = {
  title = "Coldtooth Supplies",
  desc = "La miniera di Coldtooth è un deposito dell'Orda. Il cibo che danno alle loro truppe non riesco a mandarlo giù, e armi e armature le tengono in uno stato pietoso! Ma... in tempi come questi, con le scorte che contano così tanto, possiamo usare quello che hanno.$B$BEntra nella miniera di Coldtooth e riportami le loro scorte: ci aiuteranno a tenere l'Alleanza pronta a combattere, e ai guerrieri dell'Orda toglieranno un equipaggiamento di cui hanno un gran bisogno.$B$BBuona fortuna, $N. La miniera è molto più a sud, nel cuore del territorio dell'Orda.",
  obj = "Porta 10 Coldtooth Supplies al Furiere dell'Alleanza a Dun Baldar.",
  progress = "Sei $Gentrato:entrata; nella miniera di Coldtooth, nel territorio dell'Orda, $N? Le loro scorte, le hai razziate?",
  reward = "Ah, le hai prese. Ottimo lavoro, $N! Queste scorte, dopo tanto tempo in quella miniera buia, sanno un po' di muffa, ma le useremo lo stesso.$B$BGrazie, $N. Quello che fai è fondamentale per mantenere le nostre truppe.",
}
T[6983] = {
  title = "Sei cattivo, The Abominable Greench",
  desc = "A r-r-rubarci la spedizione di d-d-dolcetti è stata una c-c-creatura chiamata \"The Abominable Greench\", $N. Ma stai $Ga-a-attento:a-a-attenta;! È stato lui a t-t-trasformarmi in questo m-m-mucchio di neve!$B$BTi s-s-servirà un po' d'aiuto per a-a-affrontarlo. L'ho visto g-g-girare dalle parti degli y-y-yeti; è s-s-sicuramente qui da qualche p-p-parte! T-t-trova i dolcetti, $N, riportali a Smokywood Pastures, a Orgrimmar, e d-d-di' loro che mi devono s-s-scongelare!",
  obj = "Trova gli Stolen Treats e riportali a Kaymard Copperpinch a Orgrimmar. Si pensa che li abbia l'Abominable Greench, che si aggira da qualche parte nelle regioni innevate delle Alterac Mountains.",
  progress = "$N — senza quei dolcetti per rifornirci, la nostra Festa di Winter Veil sarà rovinata! Persino Graccu, quest'anno, non potrà offrire i suoi deliziosi pasticci di carne a tutti i bravi bimbi...",
  reward = "L'hai trovata! Hai salvato la Smokywood Pasture's Feast of Winter Veil!$B$BPovero Sacks... manderemo senz'altro una squadra lassù a trovare il modo di scongelarlo. Speriamo che torni in tempo per il giorno della Festa; dovrà però recuperare le ore di lavoro perse. Ad ogni modo, senza di te niente di tutto questo sarebbe stato possibile!",
  en_title = "You're a Mean One...",
  en_obj = "Locate and return the Stolen Treats to Kaymard Copperpinch in Orgrimmar.  It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.",
}
T[6984] = {
  title = "Un Grazie da Smokywood Pastures!",
  desc = "Noi di Smokywood Pastures ti siamo grati per aver recuperato gli Stolen Treats, $N. Per questo vorremmo offrirti un regalo speciale... consegnato nientemeno che da Great-father Winter in persona!$B$BTi prego, parla con Great-father Winter: ti darà il regalo per la Festa di Winter Veil da parte di tutti noi di Smokywood Pastures. Dalla nostra fattoria alla tua tavola, sempre la genuina bontà di Smokywood Pastures... grazie a te, naturalmente!",
  obj = "Parla con Great-father Winter a Orgrimmar.",
  reward = "Oh oh OH!, $Gavventuriero:avventuriera;!$B$BI goblin mi hanno detto che in queste feste ti sei $Gguadagnato:guadagnata; un regalo speciale, e sono lieto di dartelo. Ecco qui — ti auguro una meravigliosa Festa di Winter Veil, quest'anno e negli anni a venire.",
  en_title = "A Smokywood Pastures Thank You!",
  en_obj = "Speak with Great-father Winter in Orgrimmar.",
}
T[6985] = {
  title = "Irondeep Supplies",
  desc = "I nani Stormpike usano la miniera di Irondeep come deposito. Voglio che tu la razzi e mi porti le scorte. Così ostacoleremo gli Stormpike nell'Alterac Valley e avremo l'equipaggiamento che ci serve!$B$BStai in guardia, $N. La miniera di Irondeep è nel cuore del territorio dell'Alleanza, e chi la controlla cambia come le nevi di Alterac.",
  obj = "Porta 10 Irondeep Supplies al Furiere dell'Orda alla Frostwolf Keep.",
  progress = "Sei $Gentrato:entrata; nella miniera di Irondeep, $N? Le scorte, le hai razziate?",
  reward = "Le hai prese! Ben fatto, $N! E spero che durante la razzia tu abbia incontrato qualche nano e versato il loro sangue per i Frostwolf!",
}
T[7001] = {
  title = "Stalle Vuote",
  desc = "La guerra nella valle ha messo a dura prova i nostri soldati. Dobbiamo rinvigorire le nostre forze!$B$BSe riempiamo le stalle, i Wolf Riders potranno tornare a cavalcare sul campo di battaglia.$B$BPrendi questa museruola e va' a cercare i lupi del gelo che vivono nella foresta qui vicino. Quando ne trovi uno, domalo con la museruola. Poi portami la bestia domata e la sistemerò nella stalla.$B$BAppena avremo abbastanza lupi nelle stalle, i Wolf Riders torneranno a pattugliare le nostre prime linee.",
  obj = "Trova un Frostwolf in Alterac Valley. Usa la Frostwolf Muzzle quando sei $Gvicino:vicina; al Frostwolf per 'domare' la bestia. Una volta domato, il Frostwolf ti seguirà fino alla Frostwolf Stable Master. Parla con la Frostwolf Stable Master per farti riconoscere la cattura.",
  progress = "Senza di te i Frostwolf Wolf Riders non avrebbero cavalcature per andare in battaglia. Ci rendi un grande servizio!",
  reward = "Spero solo che chi raccoglie le pelli di montone sia determinato quanto te, $N.$B$BDi questo passo, in qualche ora avremo le stalle piene!",
}
T[7002] = {
  title = "Finimenti di Pelle d'Ariete",
  progress = "Alcuni dei nostri soldati sono impegnati a catturare lupi per il maestro di stalla, ma ad altri tocca procurare le cose semplici che servono per cavalcare. I finimenti da cavalcatura, naturalmente.$B$BDevi attaccare gli arieti nativi della regione. Proprio quelli su cui monta la cavalleria degli Stormpike!$B$BUccidili e portami le loro pelli. Quando ne avremo messe insieme abbastanza, faremo dei finimenti per i cavalieri. I Frostwolf Wolf Riders cavalcheranno ancora!",
  reward = "Ben fatto, $Gsoldato:soldatessa;. Quando avrò accumulato abbastanza pelli, ti avviserò.$B$BAvanti così!",
}
T[7003] = {
  title = "Giganti Folgorati",
  desc = "Se resto qui, coi giganti dovrò fare qualcosa! Agli affari non fanno certo bene, no?$B$BSto lavorando a una variante di un raggio rimpicciolente gnomesco, però lo costruisco con i superiori progressi tecnologici GOBLIN! Per risparmiarmi inconvenienti come la morte, vorrei che a provarlo fossi tu, su uno qualsiasi dei giganti di Feralas. Una volta rimpiccioliti, dovresti trovargli addosso del miniaturization residue — portamene un po'!",
  obj = "Usa la Zorbin's Ultra-Shrinker per folgorare qualsiasi tipo di gigante che si trova a Feralas e ridurlo a una forma più gestibile. Porta 15 Miniaturization Residues trovati sulle versioni folgorate di questi giganti a Zorbin Fandazzle, ai moli della Forgotten Coast, a Feralas.",
  progress = "Te lo assicuro, nell'ingegneria il Miniaturization residue è una merce preziosa! Be', è prezioso perché mi aiuta a evitare che il folgoratore combini qualcosa di deludente, tipo esplodere addosso a chi lo usa.$B$BOh, parlo dei folgoratori diversi da quello che ho dato a te. Assolutamente!",
  reward = "Splendifavoloso! Sono contento di vederti tornare col residuo, e pure con tutte le appendici principali ancora intatte! Cioè, be', usare l'Ultra Riduttore non è mai stato pericoloso, no?$B$BApprezzo molto quanto ti sei $Gimpegnato:impegnata; per me, $N. Sei davvero $Gun amico:un'amica; dei goblin di ogni dove. Accetta questo in segno di gratitudine!",
}
T[7021] = {
  title = "Great-father Winter È Qui!",
  desc = "Ti auguro uno splendido Winter Veil, $Gamico:amica;! E non dimenticare di salutare Greatfather Winter: in questo momento si trova a Orgrimmar! Se quest'anno sei $Gstato:stata; $Gbuono:buona;, il giorno della Feast of Winter Veil ti arriveranno dei dolcetti meravigliosi. Mi raccomando, digli cosa speri di ricevere quest'anno!$B$BE fai scorta di dolcetti da regalare a chi quest'anno è stato buono: ne abbiamo un'ampia scelta. Dalla nostra fattoria alla tua tavola — è la genuina bontà di Smokywood Pastures!",
  obj = "Parla con Greatfather Winter; si trova vicino all'area dei venditori di Smokywood Pastures a Orgrimmar.",
  reward = "Oh oh ohlà. Sono Greatfather Winter, e io — per gentile concessione della brava gente di Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola, è la genuina bontà di Smokywood Pastures\" — vorrei augurarti una fantastica Feast of Winter Veil.$B$BSe quest'anno sei $Gstato:stata; $Gbuono:buona;, per la Feast of Winter Veil forse ti arriveranno in regalo dei dolcetti di Smokywood Pastures. Urrà.",
  en_title = "Great-father Winter is Here!",
  en_obj = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.",
}
T[7022] = {
  title = "Greatfather Winter È Qui!",
  desc = "Ti auguro un meraviglioso Winter Veil, $Gamico:amica;! E passa a salutare Greatfather Winter, mi raccomando! Se quest'anno sei $Gstato buono:stata buona;, alla Feast of Winter Veil riceverai dei dolcetti favolosi. E ricordati di dirgli cosa speri di ricevere!$B$BE già che ci sei, fai scorta di dolcetti da regalare a chi quest'anno è stato buono. Ne abbiamo di tutti i tipi. Freschi dalla nostra fattoria alla tua tavola — è la genuina bontà di Smokywood Pastures!",
  obj = "Parla con Greatfather Winter; si trova vicino all'area dei venditori di Smokywood Pastures a Ironforge.",
  reward = "Oh oh ohilà. Sono Greatfather Winter e — per gentile concessione della brava gente di Smokywood Pastures... \"Freschi dalla nostra fattoria alla tua tavola, è la genuina bontà di Smokywood Pastures\" — ti auguro una fantastica Feast of Winter Veil.$B$BSe quest'anno sei $Gstato buono:stata buona;, magari per la Feast of Winter Veil ti arriverà in regalo qualche dolcetto di Smokywood Pastures. Urrà.",
  en_title = "Greatfather Winter is Here!",
  en_obj = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge.",
}
T[7023] = {
  title = "Greatfather Winter È Arrivato!",
  desc = "Ti auguro un Winter Veil meraviglioso, $Gamico:amica;! E non scordarti di passare a salutare Greatfather Winter, che in questi giorni si trova a Ironforge! Se quest'anno sei $Gstato buono:stata buona;, il giorno della Feast of Winter Veil riceverai dei dolcetti fantastici. E digli cosa speri di trovare quest'anno!$B$BFai anche scorta di dolcetti da regalare a chi quest'anno si è comportato bene. Ne abbiamo di ogni tipo. Dalla nostra fattoria alla tua tavola — è la bontà genuina delle Smokywood Pastures!",
  obj = "Parla con Greatfather Winter; si trova vicino all'area dei venditori delle Smokywood Pastures a Ironforge.",
  reward = "Oh oh ohlà. Sono Greatfather Winter, e io — per gentile concessione della brava gente delle Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola, è la bontà genuina delle Smokywood Pastures\" — vorrei augurarti una Feast of Winter Veil fantastica.$B$BSe quest'anno sei $Gstato buono:stata buona;, forse ti arriverà qualche dolcetto delle Smokywood Pastures come regalo per la Feast of Winter Veil. Urrà.",
  en_title = "Greatfather Winter is Here!",
  en_obj = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge.",
}
T[7024] = {
  title = "Great-father Winter È Qui!",
  desc = "Ti auguro un meraviglioso Winter Veil, $Gamico:amica;! E non dimenticare di salutare Greatfather Winter: in questo momento si trova a Orgrimmar! Se quest'anno sei $Gstato buono:stata buona;, il giorno della Feast of Winter Veil riceverai dei dolcetti favolosi. Ricordati di dirgli cosa speri di ricevere quest'anno!$B$BE fai scorta anche di dolcetti da regalare a chi quest'anno è stato buono: ne abbiamo un'ottima scelta. Freschi dalla nostra fattoria alla tua tavola — è la genuina bontà di Smokywood Pastures!",
  obj = "Parla con Greatfather Winter; si trova vicino all'area dei venditori di Smokywood Pastures a Orgrimmar.",
  reward = "Oh oh ohlà. Sono Greatfather Winter, e io — per gentile concessione della brava gente di Smokywood Pastures... \"Freschi dalla nostra fattoria alla tua tavola, è la genuina bontà di Smokywood Pastures\" — vorrei augurarti una fantastica Feast of Winter Veil.$B$BSe quest'anno sei $Gstato buono:stata buona;, forse per la Feast of Winter Veil riceverai in premio dei dolcetti di Smokywood Pastures. Urrà.",
  en_title = "Great-father Winter is Here!",
  en_obj = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.",
}
T[7025] = {
  title = "Dolcetti per Greatfather Winter",
  desc = "Ehi, faresti un favore a Greatfather Winter, ehm, $Gpiccolo:piccola;?$B$BNon che io voglia parlare di me in terza persona senza motivo, ma Greatfather Winter è al lavoro da tutto il giorno, e un dolcetto farebbe comodo anche a lui. Dei gingerbread cookies e dell'ice cold milk per mandarli giù sarebbero proprio quello che ci vuole. Saresti così $Gamico:amica; del Babbo da portarmene un po'?",
  obj = "Porta 5 Gingerbread Cookies e un Ice Cold Milk a Greatfather Winter a Ironforge.",
  progress = "A furia di parlare di dolcetti è venuta voglia anche a me. Mmmm... Gingerbread cookies e latte...",
  reward = "$N, sei proprio $Gun bravo aiutante:una brava aiutante; per il vecchio Greatfather Winter. Buona Feast of Winter Veil.$B$BTieni, un pensierino... sai, per il disturbo.",
  en_title = "Treats for Greatfather Winter",
  en_obj = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Ironforge.",
}
T[7026] = {
  title = "Finimenti per Cavalcare i Montoni",
  progress = "La Stormpike Brigade non può lanciarsi in battaglia a pelo! Le nostre cavalcature hanno bisogno di finimenti; dopotutto, non siamo dei selvaggi.$B$BFaremmo presto a uccidere i montoni che girano vicino alla nostra base e a ricavarne il cuoio per un finimento, ma sarebbe da idioti. Quei montoni ci servono da cavalcare.$B$BDevi colpire la base nemica, uccidere i lupi del gelo che usano come cavalcature e prenderne le pelli. Portamele, e con quelle faremo i finimenti per la cavalleria. Vai!",
  reward = "Ben fatto, $Gsoldato:soldatessa;. Quando avrò messo da parte abbastanza pelli te lo farò sapere.$B$BContinua così!",
}
T[7027] = {
  title = "Stalle Vuote",
  desc = "Guarda le stalle, $N! Vuote! La Stormpike Brigade è rimasta senza montoni da cavalcare — la cavalleria non esiste più.$B$BDevi aiutarci, $Gsoldato:soldatessa;. Prendi questo collare d'addestramento e addentrati nelle terre selvagge della valle. Cerca i montoni di Alterac che girano per la zona e catturane uno con il collare. Quando l'avrai preso, riportamelo e lo metterò nella stalla.$B$BAppena avremo abbastanza montoni, lo faremo sapere al comandante dei cavalieri di montoni. Con il tuo aiuto la cavalleria rinascerà!",
  obj = "Trova un Alterac Ram in Alterac Valley. Usa lo Stormpike Training Collar quando sei $Gvicino:vicina; all'Alterac Ram per 'domare' la bestia. Una volta domato, l'Alterac Ram ti seguirà fino alla Stalliera. Parla con la Stalliera per farti riconoscere la cattura.",
  progress = "Senza di te gli Stormpike Ram Riders non avrebbero cavalcature per andare in battaglia. Ci rendi un grande servizio!",
  reward = "In un attimo le stalle saranno piene. Continua così!",
}
T[7028] = {
  title = "Mali Contorti",
  desc = "Le caverne di cristallo di Terramok sono a ovest, nel profondo di Maraudon... Un luogo antico, carico di storia. E io voglio mettere le mani su un po' di quella storia, $C. Dietro le porte giganti giacciono nascoste reliquie degli antichi dèi.$B$BSe sei $Gdisposto:disposta; ad affrontare i mali contorti di Maraudon, credo di poter fare in modo che ne valga la pena. Raccogli le theradric crystal carvings che trovi e portamele.$B$BQuando avrò le sculture, potrò... studiarle. Questi poteri dormono da troppo tempo...",
  obj = "Raccogli 25 Theradric Crystal Carvings per Willow in Desolace.",
  progress = "Niente domande!$B$BSai bene cosa ti ho chiesto.",
  reward = "Ah ah ah! Lo sapevo che saresti $Gtornato:tornata;.$B$B<Willow borbotta.>$B$B...Così facile da convincere.$B$B...Per il prezzo giusto fa qualsiasi cosa. Eh eh eh...",
}
T[7029] = {
  title = "Corruzione di Vyletongue",
  desc = "Un satiro di nome Vyletongue ha corrotto le caverne di Maraudon, e ora molte delle piante che vi crescono stentano a svilupparsi.$B$BPrendi questa fiala, $N, e riempila alla pozza di cristallo arancione, dentro le caverne. Il suo rivestimento interno contrasterà le tossine e trasformerà il liquido in un agente curativo.$B$BCerca i Vylestem vines nelle caverne arancioni e usa su di loro il liquido purificato. La pianta sarà liberata dalla corruzione, ma sappi che Vyletongue continuerà a controllarla. Potrebbe usarla contro di te...",
  obj = "Riempi la Coated Cerulean Vial alla pozza di cristallo arancione a Maraudon.$B$BUsa la Filled Cerulean Vial sui Vylestem Vines per costringere il corrotto Noxxious Scion a uscire allo scoperto.$B$BCura 8 piante uccidendo questi Noxxious Scion, poi torna da Vark Battlescar a Shadowprey Village.",
  progress = "Se riuscirai a curarla, la pianta tornerà a crescere. Dobbiamo fare quello che possiamo, $N...",
  reward = "Grazie per avermela riportata, $N. Con il liquido che vi è rimasto potrò proseguire i miei studi.$B$BC'è ancora molto da fare, ma hai contribuito a curare parte della corruzione che Vyletongue ha diffuso per Maraudon. Ti prego, accetta questo in segno di gratitudine.",
}
T[7041] = {
  title = "Corruzione di Vyletongue",
  desc = "Un satiro di nome Vyletongue ha corrotto le caverne di Maraudon, e ora molte delle piante che vi crescono stentano a svilupparsi.$B$BPrendi questa fiala, $N, e riempila alla pozza arancione corrotta, dentro le caverne. Il suo rivestimento interno contrasterà le tossine e trasformerà il liquido in un agente curativo.$B$BCerca i Vylestem vines nelle caverne arancioni e usa su di loro il liquido purificato. La pianta sarà liberata dalla corruzione, ma sappi che Vyletongue continuerà a controllarla. Potrebbe usarla contro di te...",
  obj = "Riempi la Coated Cerulean Vial alla pozza di cristallo arancione a Maraudon.$B$BUsa la Filled Cerulean Vial sui Vylestem Vines per costringere il corrotto Noxxious Scion a uscire allo scoperto.$B$BCura 8 piante uccidendo questi Noxxious Scion, poi torna da Talendria a Nijel's Point.",
  progress = "Se riuscirai a curarla, la pianta tornerà a crescere. Dobbiamo fare quello che possiamo, $N...",
  reward = "Grazie per avermela riportata, $N. Con il liquido che vi è rimasto potrò proseguire i miei studi.$B$BC'è ancora molto da fare, ma hai contribuito a curare parte della corruzione che Vyletongue ha diffuso per Maraudon. Ti prego, accetta questo in segno di gratitudine.",
}
T[7042] = {
  title = "Dolcetti Rubati di Winter Veil",
  desc = "Senti... non vorrei rovinare la magia delle feste, ma alla Smokywood Pastures servirebbe una mano — di quelle per cui voi avventurieri andate famosi.$B$BCi manca un'importante spedizione di dolcetti che doveva rifornirci per la stagione, e adesso è scomparso anche l'agente della Smokywood Pastures che abbiamo mandato sul campo a cercarla!  Ti prego — la spedizione è stata avvistata per l'ultima volta nelle Alterac Mountains, ed è lì che il nostro uomo è andato a cercarla.$B$BVedi se li trovi lì tutti e due, sani e salvi!",
  obj = "Trova l'investigatore di Smokywood Pastures scomparso nelle regioni innevate di Alterac Mountains.",
  reward = "M-m-mi senti!  Sia r-r-ringraziato il b-b-bilancio!$B$BIn realtà non sono un p-p-pupazzo di neve — mi ch-ch-chiamo Sacks, e l-l-lavoro per la f-f-filiale della Smokywood Pastures di Ironforge... Mi hanno m-m-mandato qui a cercare una s-s-spedizione scomparsa, e mi ha attaccato una c-c-creatura che non avevo mai visto p-p-prima!$B$BChe f-f-freddo tremendo...",
  en_title = "Stolen Winter Veil Treats",
  en_obj = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.",
}
T[7043] = {
  title = "Sei Proprio un Cattivone...",
  desc = "È stata una c-c-creatura chiamata \"The Abominable Greench\" a rubare la nostra spedizione di d-d-dolcetti, $N.  Ma stai $Ga-a-attento:a-a-attenta;!  È lui che mi ha t-t-trasformato in questo c-c-casino ghiacciato!$B$BTi s-s-servirà aiuto per a-a-affrontarlo.  L'ho visto g-g-girare in lungo e in largo fra gli y-y-yeti; di s-s-sicuro è qui da q-q-qualche parte!  T-t-trova i dolcetti, $N, riportali a Smokywood Pastures, a Ironforge, e d-d-di' loro che ho b-b-bisogno di essere scongelato!",
  obj = "Trova gli Stolen Treats e riportali a Wulmort Jinglepocket a Ironforge.  Da quanto si sa, l'ultimo ad averli era l'Abominable Greench, che si aggira da qualche parte nelle regioni innevate di Alterac Mountains.",
  progress = "$N — se non arrivano quei dolcetti a rifornirci, la nostra Feast of Winter Veil sarà rovinata!  Quest'anno neanche Graccu potrà dividere i suoi deliziosi pasticci di carne con tutti i buoni bambini e le buone bambine...",
  reward = "L'hai trovata!  Hai salvato la Smokywood Pasture's Feast of Winter Veil!$B$BPovero Sacks... manderemo di sicuro una squadra lassù per trovare un modo di scongelarlo.  Speriamo che torni in tempo per il giorno della Festa; però dovrà recuperare le ore di lavoro perse.  Comunque, senza di te niente di tutto questo sarebbe stato possibile!",
  en_title = "You're a Mean One...",
  en_obj = "Locate and return the Stolen Treats to Wulmort Jinglepocket in Ironforge.  It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.$B",
}
T[7044] = {
  title = "Leggende di Maraudon",
  desc = "Un satiro oscuro, Lord Vyletongue, ha diffuso il suo male in queste caverne tortuose, avvelenando la mente di chiunque ci si trovi. Vive ancora oltre i cristalli viola.$B$BVyletongue ha creato anche un simbolo vivente della sua corruzione, Noxxion, che dimora oltre i cristalli arancioni. Insieme hanno rubato le due parti dello scettro di mio fratello. Celebras, mio fratello... vaga alla cieca là dentro, maledetto dalla corruzione.$B$BDevi aiutarlo! Trova i pezzi e parla con mio fratello... in qualche modo.",
  obj = "Recupera le due parti dello Scepter of Celebras: la Celebrian Rod e il Celebrian Diamond.$B$BTrova un modo per parlare con Celebras.",
  progress = "Mi sono risvegliato da un incubo che sembrava senza fine...",
  reward = "Ora che hai recuperato le due parti del mio scettro, spero che un giorno Maraudon possa liberarsi della corruzione Vyle.",
}
T[7045] = {
  title = "Un Grazie dalla Smokywood Pastures!",
  desc = "Noi della Smokywood Pastures ti siamo grati per aver recuperato gli Stolen Treats, $N.  Per questo vorremmo offrirti un regalo speciale... consegnato nientemeno che da Greatfather Winter in persona!$B$BTi prego, parla con Greatfather Winter: ti darà il regalo per la Feast of Winter Veil da parte di tutti noi qui alla Smokywood Pastures.  Dalla nostra fattoria alla tua tavola, la bontà genuina della Smokywood Pastures non manca mai... grazie a te, naturalmente!",
  obj = "Parla con Greatfather Winter a Ironforge.",
  reward = "Oh oh oh, ciao, $Gavventuriero:avventuriera;!$B$BI goblin mi hanno detto che in queste feste ti sei $Gguadagnato:guadagnata; un regalo speciale, e sono felice di dartelo.  Ecco qua — ti auguro una meravigliosa Feast of Winter Veil, quest'anno e in tutti gli anni a venire.",
  en_title = "A Smokywood Pastures Thank You!",
  en_obj = "Speak with Greatfather Winter in Ironforge.",
}
T[7046] = {
  title = "Lo Scepter of Celebras",
  desc = "Un tempo lo scettro mi dava speranza. Con il suo potere ero libero di muovermi in fretta per queste caverne. Speravo di portare pace allo spirito di mio zio... Ora questo compito lo affido a te.$B$BPerché le due parti tornino una sola, mi servirà il tuo aiuto nel rituale. Ti prego, seguimi e ascolta le mie istruzioni mentre incanalo l'energia necessaria a riunire la verga con il diamante.$B$BInsieme creeremo di nuovo lo Scepter of Celebras!",
  obj = "Aiuta Celebras the Redeemed mentre crea lo Scepter of Celebras.$B$BParla con lui quando il rituale è completo.",
  progress = "Se vuoi ricominciare il rituale, abbandona il nostro primo tentativo e poi torna a parlarmi.",
  reward = "Ti prego, prendi questo, e sappi che d'ora in poi dovrai usare per il bene il potere che ti è stato concesso. Prosegui il tuo viaggio nelle caverne e, se tutto va bene, troverai i resti di mio zio. Molti pericoli ti attendono, $N.$B$BSe ce ne sarà bisogno, torna a parlarmi.",
}
T[7061] = {
  title = "The Feast of Winter Veil",
  desc = "Ecco — se vuoi saperne di più su The Feast of Winter Veil, leggi questo libro. Sono convinto che il nostro modo di intendere questa storia sia il più giusto, ma ho studiato abbastanza leggende da apprezzare che tutte le informazioni siano raccolte in un'unica fonte.$B$BQuando hai finito, porta il libro a Cairne Bloodhoof, a Thunder Bluff. So per certo che gli interesserà sapere che altri si interessano alle tradizioni del nostro popolo.",
  obj = "Se vuoi, leggi il libro \"The Feast of Winter Veil\" per saperne di più sulla festività. Quando hai finito, consegnalo a Cairne Bloodhoof, a Thunder Bluff.",
  progress = "Ti do il benvenuto a Mulgore e nella nostra umile comunità di Thunder Bluff, $Gamico:amica;. Chi sceglie di interessarsi al regno, alla sua gente e alle sue tradizioni attira sempre la mia attenzione. È per questo che sei qui davanti a me?",
  reward = "Con il passare degli anni, le leggende e le tradizioni legate al Winter Veil sono passate in secondo piano nei pensieri della gente. Sì, so che i goblin contribuiscono a far rivivere questa stagione per i propri scopi, ma se il nostro popolo ci riflette, almeno in qualche modo, queste tradizioni restano vive.$B$BVoler andare oltre le cose materiali per conoscere il nostro passato è una qualità ammirevole, giovane $C. Rendo onore alla tua saggezza.",
  en_title = "The Feast of Winter Veil",
  en_obj = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to Cairne Bloodhoof in Thunder Bluff.",
}
T[7062] = {
  title = "Il Vero Senso della Festa",
  desc = "Regali, dolcetti, pacchetti... bah, dico io!$B$BQuei goblin stanno snaturando il vero significato di questo periodo dell'anno — The Feast of Winter Veil. È il tempo della rinascita: la terra dorme sotto una coltre di neve portata da Greatfather Winter, che NON è quel buffone impacciato vestito di rosso laggiù!$B$BSe vuoi scoprire da te che cos'è davvero la Festa, chiedi a Historian Karnik, all'Explorer's League. Sono sicuro che si stupirà nel vedere qualcuno che si interessa alla storia invece che ai regali.",
  obj = "Parla con Historian Karnik, all'Explorer's League di Ironforge, a proposito di The Feast of Winter Veil.",
  reward = "The Feast of Winter Veil, dici? Ahimè, un tempo aveva un significato ben più profondo per noi nani. Oggigiorno pare che altri abbiano trasformato la leggenda di Greatfather Winter in un pretesto per vendere dolciumi e regali.$B$BNon c'è da stupirsi che Goli sia amareggiato per un cambiamento del genere. Lui e i nani come lui si aggrappano al nostro passato come a uno stendardo di guerra. Io penso che festeggiare un po' faccia sempre bene, ma è importante ricordare le origini della Festa.",
  en_title = "The Reason for the Season",
  en_obj = "Speak with Historian Karnik at the Explorer's League in Ironforge about the Feast of Winter Veil.",
}
T[7063] = {
  title = "The Feast of Winter Veil",
  desc = "Ecco — se vuoi saperne di più su The Feast of Winter Veil, leggi questo libro. Anche se ritengo che il nostro modo di intendere la leggenda sia quello giusto, da buon studioso apprezzo che tutte le informazioni siano raccolte in un'unica fonte.$B$BQuando hai finito, porta il libro a King Magni Bronzebeard. So per certo che gli farebbe piacere sapere che altri si interessano alle leggende più antiche.",
  obj = "Se vuoi, leggi il libro \"The Feast of Winter Veil\" per saperne di più sulla festività. Quando hai finito, consegnalo a King Magni Bronzebeard a Ironforge.",
  progress = "Ti do il benvenuto nel Kingdom of Ironforge, $Gamico:amica;. Mi stanno sempre a cuore coloro che scelgono di interessarsi al regno, alla sua gente e alle sue tradizioni. È per questo che ti trovi al mio cospetto?",
  reward = "Col passare degli anni, la gente ha relegato in secondo piano le leggende e le tradizioni legate a Winter Veil. Ammetto che i goblin stanno riportando in auge questo periodo dell'anno per i loro scopi, ma il fatto che i cittadini ci pensino, almeno in qualche forma, contribuisce a mantenere vive queste tradizioni.$B$BIl tuo desiderio di andare oltre le cose materiali e conoscere il nostro passato è una qualità ammirevole, giovane $C. Rendo omaggio alla tua erudizione.",
  en_title = "The Feast of Winter Veil",
  en_obj = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to King Magni Bronzebeard in Ironforge.",
}
T[7064] = {
  title = "Corruzione della Terra e del Seme",
  desc = "Nelle profondità di Maraudon vive una malvagia creatura di caos — Princess Theradras, una forza elementale della terra legata agli Old Gods. Secoli fa lei e Zaetar, primo figlio di Cenarius, iniziarono una relazione, e i figli nati da quell'unione divennero noti ai popoli di Kalimdor come centauri. Eternamente riconoscenti, i centauri uccisero Zaetar, e ora ne custodiscono i resti. Sono qui per trovare qualcuno abbastanza potente da uccidere Theradras, così che possiamo recuperare i resti di Zaetar prima di tornare a Stonetalon.",
  obj = "Uccidi Princess Theradras e torna da Selendra vicino a Shadowprey Village in Desolace.",
  progress = "Preferirei combattere questa battaglia da soli, ma non abbiamo altra scelta — ci serve qualcuno più potente, e le razze di Azeroth hanno dimostrato senza ombra di dubbio che, quando lavorano insieme, sanno superare cose del genere. Per questo ci rivolgiamo a te.$B$BSpero solo che basti.$B$BZaetar, fratello di Remulos, ha portato molte sofferenze in questo mondo, e alla fine l'ha pagato con la vita. Mi auguro solo che chiederti aiuto non abbia causato altre morti.",
  reward = "È una notizia meravigliosa, $N! Grazie!$B$BChiederò a Marandis un saggio consiglio sui resti di Zaetar, ma almeno la prova più difficile l'hai superata.$B$BMi hanno detto che, se la missione fosse riuscita, avrei potuto ricompensare chi ci avesse aiutati. Mi hanno dato questi oggetti, doni del nostro popolo — puoi sceglierne uno.",
}
T[7065] = {
  title = "Corruzione della Terra e del Seme",
  desc = "Nelle profondità di Maraudon vive una creatura di caos e malvagità, $N: Princess Theradras, una forza elementale della terra in qualche modo legata agli Old Gods. Secoli fa Zaetar, primo figlio di Cenarius, andò a cercarla, e dalla loro... relazione nacquero le creature note come centauri. Eternamente riconoscenti, i centauri uccisero Zaetar, e ora i suoi resti li custodisce Theradras. Sono qui per trovare qualcuno abbastanza potente da uccidere Theradras, così che possiamo recuperare i resti di Zaetar prima di tornare a Stonetalon.",
  obj = "Uccidi Princess Theradras e torna da Keeper Marandis a Nijel's Point in Desolace.",
  progress = "Mi pesa dover rivolgere la mia supplica alle razze mortali, ma non abbiamo altra scelta. Le razze di Azeroth hanno dimostrato senza ombra di dubbio che, quando lavorano insieme, sanno superare cose del genere, ed è per questo che chiedo aiuto a loro.$B$BSpero solo che basti.$B$BZaetar, fratello di Remulos, ha portato molte sofferenze in questo mondo, e alla fine l'ha pagato con la vita. C'è una lezione per tutti noi, se siamo abbastanza saggi da coglierla.",
  reward = "È una notizia meravigliosa, $N! Grazie!$B$BMi preoccupa che tu non sia $Griuscito:riuscita; a riportare i resti di Zaetar, ma chi sono io per mettere in dubbio ciò che vuole il primogenito di Cenarius. Forse ora la volontà dei centauri si spezzerà e la loro sete di sangue si placherà — possiamo solo sperarlo.$B$BMi hanno affidato questi oggetti per ricompensare chiunque ci avesse aiutati, se la missione fosse riuscita. Puoi sceglierne uno, in segno di gratitudine.",
}
T[7066] = {
  title = "Seed of Life",
  desc = "I centauri, quegli sciagurati — figli e figlie miei — hanno bisogno del loro padre.$B$BGuardati intorno — questo luogo risuona di speranza, di tutto ciò che predica mio padre Cenarius. È nato da me! E non posso portarglielo via... nemmeno per i crimini che hanno commesso contro di me.$B$BC'è però una cosa che vorrei chiederti, per rasserenare mio fratello. Prendi questo seme... è il primo caduto dalla vita che i miei resti hanno nutrito. Digli che il mio spirito resta qui e che vivo ancora. Capirà, ne sono sicuro.",
  obj = "Cerca Remulos a Moonglade e consegnagli il Seed of Life.",
  progress = "Hai addosso l'odore della corruzione, $N... come tanti avventurieri, di questi tempi. Eppure in te c'è qualcosa di diverso. Sei $Gvenuto:venuta; a parlarmi di qualcosa? Ti circonda un'aura che mi sembra familiare, ma non riesco a capire da dove venga.$B$BTi prego, ti supplico, dimmi perché sei $Gvenuto:venuta; a chiedermi udienza.",
  reward = "Dunque mio fratello ha trovato pace, finalmente? Sono fiero di essere vissuto abbastanza da vedere questo giorno. Con tutta la sua arroganza e la sua rabbia, lo credevo davvero perduto per noi, ma questo... questo simbolo del suo sacrificio non fa che dimostrare che non è perduto — è solo rinato. Prende il suo posto nella natura, com'era suo dovere.$B$BGrazie, $N. Portandomelo hai messo al sicuro un po' della speranza che credevo di aver perduto. Un giorno questo seme sarà importante per la gente di questa terra devastata dalla guerra... lo sento.",
}
T[7067] = {
  title = "The Pariah's Instructions",
  desc = "Mi avranno anche esiliato come eretico, ma le mie convinzioni restano vere — ed è solo questo a farmi andare avanti. Però, per compiere il mio destino, ho bisogno dell'aiuto di un estraneo... di qualcuno che non appartenga a nessuna tribù di centauri.$B$BSi tratta di entrare nelle sacre sale di Maraudon — una tomba che il mio popolo protegge e dove possono entrare solo i più devoti.$B$BSe accetti di aiutarmi, basta un cenno del capo e ti darò una pergamena con le mie istruzioni. Leggila, e rifletti sulle mie parole.",
  obj = "Leggi the Pariah's Instructions. Poi recupera l'Amulet of Union a Maraudon e riportalo al Centaur Pariah nella parte meridionale di Desolace.",
  progress = "Allora, $N, che cosa hai deciso? Puoi aiutarmi? Metterai piede sul suolo sacro, perché io possa forgiare un'unica, grande tribù di centauri!?",
  reward = "Eccolo, $R! Eccolo! Adesso posso cominciare la grande impresa di unire le tribù. Grazie.$B$BTi prego, accetta questo per il tuo impegno. Spero che la prossima volta ci incontreremo in circostanze ben diverse.",
}
T[7068] = {
  title = "Shadowshard Fragments",
  desc = "Nel luogo sacro dei centauri stare magie potenti... il luogo sacro di Maraudon. Le tribù di centauri di Desolace difendono quel posto co' la loro vita, ma non posson impedirci di prendere quel che ci serve.$B$BTu, tu vai là, a Maraudon, e cerca le creature di roccia fatte di shadowshard. Tu portare a me i cristalli viola, e in cambio Uthel'nay costruire qualcosa per te.$B$BIl posto essere pericoloso, e allora forse tu portare qualche amico.",
  obj = "Raccogli 10 Shadowshard Fragments a Maraudon e portali a Uthel'nay a Orgrimmar.",
  progress = "Tu trovato i cristalli? Rituali di potere, incantesimi di grande forza — in ogni tipo di magia arcana quei frammenti di shadowshard forse molto utili.",
  reward = "Ah, questi essere perfetti per le me magie. Tu prendi uno di questi monili, ecco, e ora vai... me avere molto da studiare.",
}
T[7070] = {
  title = "Shadowshard Fragments",
  desc = "Ho iniziato da poco a studiare diversi cristalli e le loro proprietà arcane, e Lady Proudmoore mi ha permesso di chiedere ai viaggiatori diretti a Desolace di cercare un luogo chiamato Maraudon. Dentro il tempio in rovina ci sono grandi elementali fatti di pietre violacee: le ho chiamate shadowshard.$B$BSe decidi di spingerti fin là e trovi un po' di quei cristalli, te ne sarei molto grato. E se ti fa piacere, potrei anche ricavarne un monile per te.",
  obj = "Raccogli 10 Shadowshard Fragments a Maraudon e riportali ad Archmage Tervosh a Theramore, sulla costa della Dustwallow Marsh.",
  progress = "Hai già fatto il viaggio? Lo so che sarebbe piuttosto pericoloso, ma se ce la facessi, ne varrebbe davvero la pena.",
  reward = "Sono perfetti, $N. A dire il vero da lì sono tornati anche altri avventurieri, e con quello che hanno portato sono riuscito a ricavare questi... ti prego, prendine pure uno per tutta la tua fatica. E grazie ancora per i nuovi campioni da studiare.",
}
T[7081] = {
  title = "Cimiteri dell'Alterac Valley",
  desc = "I cimiteri dell'Alterac Valley sono territori preziosi, e l'Orda e l'Alleanza si battono con ferocia per queste terre sacre. Sei $Gpronto:pronta;, $N, a unirti alla lotta?$B$BVoglio che tu assalti un cimitero nemico: cercane uno con uno stendardo dell'Orda nel mezzo e strappalo da terra! Fatto questo, il tuo compito sarà concluso...$B$BMa se ce la fai anche a tenere il cimitero per qualche minuto, presto arriveranno le nostre truppe a darti il cambio.",
  obj = "Assalta un cimitero, poi torna da Sergeant Durgen Stormpike nelle Alterac Mountains.",
  progress = "$N, di cimiteri non ne hai ancora assaltato nessuno. Torna da me quando avrai portato a termine il compito!",
  reward = "Ben fatto! Per controllare l'Alterac Valley i cimiteri sono vitali: ogni volta che ne conquisti uno, contribuisci a garantire il dominio dell'Alleanza su queste terre.$B$BE adesso va', $N. Torna a combattere, e se vedi un cimitero sotto il controllo dell'Orda... sai cosa fare!",
}
T[7082] = {
  title = "I Cimiteri di Alterac",
  desc = "Le linee del fronte dell'Alterac Valley non stanno mai ferme: i territori passano di mano in mano mentre affrontiamo gli avversari in combattimenti mortali. E le battaglie, $N, infuriano più che altrove nei cimiteri.$B$BVoglio che tu attacchi un cimitero in mano all'Alleanza! Cercane uno con uno stendardo dell'Alleanza nel mezzo e strappalo da terra.$B$BCon questo il compito che ti ho affidato sarà concluso, ma... se tieni il cimitero per qualche minuto, diventerà nostro e arriveranno delle truppe a darti il cambio.",
  obj = "Assalta un cimitero, poi torna da Corporal Teeka Bloodsnarl nelle Alterac Mountains.",
  progress = "Attacca un cimitero in mano all'Alleanza!",
  reward = "Ben fatto, $N! Più cimiteri controlliamo, più gli spiriti dei nemici vagheranno smarriti e senza meta.",
}
T[7101] = {
  title = "Torri e Bunker",
  desc = "Torri e bunker sono posizioni importanti: dobbiamo conquistarle e tenerle tutte! Per questo voglio che tu attacchi un bunker in mano al nemico.$B$BEntra in uno che abbia uno stendardo dell'Alleanza: dentro ne troverai un altro. Strappalo, e al suo posto comparirà uno stendardo bianco dell'Orda. Ben fatto!$B$BA quel punto il compito che ti ho affidato sarà concluso, ma se tieni la posizione abbastanza a lungo, e l'Alleanza non se la riprende, verrà distrutta!",
  obj = "Conquista una torre nemica, poi torna da Corporal Teeka Bloodsnarl nelle Alterac Mountains.",
  progress = "Non hai ancora assaltato un bunker, $N! Aspetti che siano altri a prendersi la tua gloria?",
  reward = "Ho saputo che la tua missione è andata a buon fine! Mi fa piacere...$B$BOra le nostre truppe possono lanciarsi alla carica impunemente e far vedere all'Alleanza che l'Alterac Valley non è posto per loro!",
}
T[7102] = {
  title = "Torri e Bunker",
  desc = "Torri e bunker sono posizioni difensive chiave, perciò dobbiamo tenerne quanti più possiamo! Voglio che tu attacchi una torre o un bunker nell'Alterac Valley.$B$BEntra in una torre che abbia in cima uno stendardo dell'Orda: dentro ne troverai un altro, sempre nemico. Strappalo, e al suo posto comparirà uno stendardo bianco dell'Alleanza. Ben fatto!$B$BA quel punto la missione che ti ho affidato sarà conclusa, ma tieni la zona abbastanza a lungo e, se l'Orda non se la riprende, verrà distrutta!",
  obj = "Distruggi lo stendardo di una torre o di un bunker nemico, poi torna da Sergeant Durgen Stormpike nelle Alterac Mountains.",
  progress = "Non hai ancora assaltato una torre, $N! Cosa aspetti?",
  reward = "Dal campo mi è arrivato un rapporto: hai dato una mano a prendere uno stendardo nemico. Ben fatto, $N! Adesso che le loro truppe a distanza sono fuori posizione, possiamo spingere avanti la linea del fronte!",
}
T[7121] = {
  title = "Il Quartiermastro",
  desc = "$N, il nostro quartiermastro mi ha incaricato di mandargli le nuove reclute. Ha bisogno delle provviste dei depositi nelle miniere di Alterac, e a prenderle probabilmente manderà te.$B$BSegui la strada. Lo trovi a ovest.",
  obj = "Parla con lo Stormpike Quartermaster.",
  reward = "Fa piacere vedere truppe fresche da queste parti, $N, ma con un po' di fortuna finirai nel vivo dell'azione e $Gfresco:fresca; non ci resterai a lungo!$B$BParlami di nuovo. Ci sono dei compiti che devo spiegarti....",
}
T[7122] = {
  title = "Conquista una Miniera",
  desc = "Nelle miniere dell'Alterac Valley non ci sono solo minerali. Tanto i Frostwolf quanto gli Stormpike hanno nascosto le provviste in eccesso nelle miniere di Irondeep e di Coldtooth... e non è una cattiva idea, se solo riuscissimo a tenerle sotto controllo!$B$BConquista una miniera e torna da me. Entra in una che non controlliamo e uccidine il capo: a quel punto la miniera sarà nostra, e manderemo delle truppe a proteggerla!",
  obj = "Conquista una miniera non controllata dagli Stormpike, poi torna da Sergeant Durgen Stormpike nelle Alterac Mountains.",
  progress = "Non hai ancora conquistato la miniera, $N!$B$BQuando controlleremo una miniera, ne raccoglieremo minerali e provviste molto più facilmente.",
  reward = "Ce l'hai fatta! Ben fatto, $N!$B$BCon una miniera sotto il nostro controllo e delle truppe di stanza, raccoglierne minerali e provviste è molto più facile.",
}
T[7123] = {
  title = "Parla con il Nostro Quartiermastro",
  desc = "$N, il Frostwolf Quartermaster cerca reclute per dei compiti da svolgere nelle miniere dell'Alterac Valley. Parla con lui; ti dirà di più.$B$BSegui la strada verso ovest ed entra nel bunker, poi prendi l'uscita ovest e lo trovi lì.",
  obj = "Parla con il Frostwolf Quartermaster.",
  reward = "Salute, $N! Mi fa piacere vedere $Gun:una; $C come te, $Gdesideroso:desiderosa; di fare la sua parte per l'Orda. Parlami di nuovo, ho dei compiti fondamentali per te...",
}
T[7124] = {
  title = "Conquista una Miniera",
  desc = "La battaglia infuria nelle terre dell'Alterac Valley, e infuria anche nelle miniere di Coldtooth e di Irondeep. Sono ricche di minerali tutte e due e tutte e due fanno da deposito per le scorte; non c'è da stupirsi se valgono così tanto!$B$BAiuta il nostro sforzo bellico, $N! Conquista una delle miniere per l'Orda! Per farlo, entra in una miniera che non controlliamo e uccidine il capo. A quel punto sarà nostra, e manderemo truppe a proteggerla!",
  obj = "Conquista una miniera, poi torna da Corporal Teeka Bloodsnarl nelle Alterac Mountains.",
  progress = "Non hai ancora conquistato una miniera, $N! Trovane una che non controlliamo e sconfiggine il capo!",
  reward = "Hai conquistato una miniera! Con i nostri guerrieri a proteggerla, sarà molto più semplice estrarre minerali dalle sue profondità o raccogliere le scorte che ci sono state nascoste.$B$BBen fatto, $N. Hai dato un grande aiuto al nostro sforzo bellico.",
}
T[7141] = {
  title = "La Battaglia di Alterac",
  desc = "L'Explorers' League crede che nell'Alterac Valley ci siano dei manufatti, ma gli orchi Frostwolf non ci lasciano esplorare. Non possiamo permettere che l'Orda fermi le nostre ricerche! Sconfiggi Drek'Thar, il generale dei Frostwolf: morto lui, gli orchi perderanno il vantaggio.$B$BDrek'Thar è nella Frostwolf Keep, nel sud dell'Alterac Valley. Sconfiggilo, poi torna da me.",
  obj = "Entra in Alterac Valley, sconfiggi il generale dell'Orda Drek'thar e poi torna da Prospector Stonehewer in Alterac Mountains.",
  progress = "Va', $N. Raggiungi l'Alterac Valley e sconfiggi il generale degli orchi!",
  reward = "Ben fatto, $N! Con la morte del suo generale l'Orda ha subito un duro colpo, e ora avremo il margine che ci serve per esplorare!",
}
T[7142] = {
  title = "La Battaglia per Alterac",
  desc = "I nani Stormpike e i loro alleati hanno invaso l'Alterac Valley: dobbiamo scacciarli! E per vincere la battaglia per Alterac bisogna sconfiggere il loro generale, Vanndar Stormpike!$B$BVanndar lo troverai a Dun Baldar, nel nord dell'Alterac Valley.$B$BDistruggilo, $N, e poi torna da me.",
  obj = "Entra in Alterac Valley e sconfiggi il generale dei nani, Vanndar Stormpike. Poi torna da Voggah Deathgrip in Alterac Mountains.",
  progress = "I nani in casa nostra non li tollereremo! Piomba sui nemici e sconfiggi il loro capo, il generale Stormpike!",
  reward = "Ben fatto, $N! Con questa folle invasione gli Stormpike non hanno speranze.$B$BAh! Finora l'unica cosa che gli è riuscita è farsi uccidere il generale!",
}
T[7161] = {
  title = "Il Terreno di Prova",
  desc = "Salute, $C. È da tanto che non abbiamo l'occasione di rispondere al richiamo della battaglia. I vecchi sentimenti ci mettono un po' a riaffiorare, ma quando si risvegliano il sangue scorre impetuoso. Torna la furia della battaglia...$B$BChi arriva per la prima volta nella Valle deve prima compiere il rito della battaglia.$B$BIn fondo alla caverna degli gnoll Wildpaw c'è uno stendardo dei Frostwolf. Avventurati fin laggiù e recuperalo. Riportamelo e ti concederò l'insegna da $Giniziato:iniziata; dei Frostwolf.",
  obj = "Raggiungi la caverna dei Wildpaw a sud-est della base principale in Alterac Valley e trova il Frostwolf Banner. Riporta il Frostwolf Banner a Warmaster Laggrond.",
  progress = "Svegliati! Svegliati, $N! Non stai sognando. Sei $Gtrincerato:trincerata; davvero nel cuore di una battaglia furiosa!",
  reward = "Quel bruciore che senti è la tua anima che si risveglia: il tuo spirito ha accolto la chiamata alle armi.$B$BOra sei $Guno:una; dei Frostwolf, $N. Congratulazioni.$B$BQuesta insegna tienila sempre con te. Man mano che salirai di grado fra i Frostwolf, te ne darò altre al suo posto, più potenti.$B$BForse un giorno le file del Frostwolf Clan ti osanneranno. Se quel giorno arriverà, ti sarà concesso l'Occhio del Comando.",
}
T[7162] = {
  title = "Terreno di Prova",
  desc = "Sei $Garrivato:arrivata; appena in tempo, $C. Quei selvaggi dei Frostwolf non si arrendono! Dobbiamo fargli vedere la potenza degli Stormpike: si devono piegare alla nostra superiorità.$B$BPrima di scendere sul campo di battaglia, però, ti conviene entrare nei ranghi degli Stormpike.$B$BLe Icewing Caverns sono a sudovest di Dun Baldar, e laggiù in fondo c'è piantato uno Stormpike Banner. Avventurati là dentro, recupera lo stendardo e riportamelo: così ti sarai $Gguadagnato:guadagnata; un'insegna di $Giniziato:iniziata; degli Stormpike.",
  obj = "Recati a Icewing Caverns, a sudovest di Dun Baldar in Alterac Valley, e recupera lo Stormpike Banner. Riporta lo Stormpike Banner a Lieutenant Haggerdin in Alterac Mountains.",
  progress = "$GAttento:Attenta; alle arpie da quelle parti, $C: non ci pensano due volte a strapparti la gola!",
  reward = "Prendi questa insegna e portala con orgoglio, $N. Man mano che salirai di grado fra gli Stormpike, crescerà anche lei. Quando guadagnerai onore presso gli Stormpike, torna da me e te la sostituirò con altre più potenti.$B$BForse un giorno, su questo campo di battaglia, diventerai una leggenda. E se mai quel giorno arriverà, ti sarà concesso l'Occhio del Comando.",
}
T[7163] = {
  title = "Alzati e Fatti Riconoscere",
  progress = "<Warmaster Laggrond ti saluta.>$B$BÈ arrivato il tuo momento, $N. Hai fatto molto per il Frostwolf Clan, e così ti sei $Gguadagnato:guadagnata; un posto fra i Frostwolf non solo da $Gsoldato:soldatessa;, ma anche da $Gamico:amica;.$B$BBen fatto! Fammi vedere l'insegna da $Giniziato:iniziata;.",
  reward = "Questa nuova insegna rispecchia il tuo grado fra i Frostwolf. Portala sempre con te.$B$BE tu, $C... Muori con onore!",
}
T[7164] = {
  title = "$GOnorato:Onorata; nel Clan",
  progress = "È bello rivederti, $C. Non mi aspettavo di vederti tornare. Eppure hai dimostrato di essere $Gun soldato coraggioso:una soldatessa coraggiosa; e d'onore dei Frostwolf.$B$BÈ di nuovo il tuo momento, $N. Ti sei $Gguadagnato:guadagnata; un nuovo grado e, con quello, una nuova insegna che segna la tua ascesa.$B$BFammi vedere l'insegna.",
  reward = "<Warmaster Laggrond fa il saluto.>$B$BVai, $N! Continua a difendere i Frostwolf. Questa guerra dobbiamo vincerla! Per Drek'Thar! Per il Capoguerra!",
}
T[7165] = {
  title = "Riverenza Meritata",
  progress = "Quanti caduti. Il sangue inzuppa i campi. Eppure... Tu vivi... Hai resistito. Hai portato i nostri eserciti a tante vittorie, e per questo, $Gsoldato:soldatessa;, ti sei $Gguadagnato:guadagnata; un nuovo grado.$B$BFammi vedere l'insegna.",
  reward = "<Warmaster Laggrond ruggisce.>$B$BSi raccontano già le tue imprese, $Gsoldato:soldatessa;. Gli Stormpike tremano di paura appena sentono il tuo nome. Avanti così!",
}
T[7166] = {
  title = "Eroi Leggendari",
  progress = "Emani autorità e potere, $C. Per i Frostwolf sei $Gosannato:osannata; — il nemico si fa piccolo appena sente il tuo nome.$B$BAlzati, $GEroe:Eroina; dei Frostwolf. Alzati e sii $Gonorato:onorata;!$B$BFammi vedere l'insegna.",
  reward = "Presto, sul campo di battaglia, tutti saranno sotto il tuo sguardo vigile. La Valle e le sue truppe saranno al tuo comando!",
}
T[7167] = {
  title = "L'Occhio del Comando",
  progress = "Drek'Thar canta le tue lodi, e in tutto Kalimdor si raccontano le tue gesta eroiche. Il Capoguerra è raggiante — ha apprezzato molto come hai difeso strenuamente il nostro clan.$B$BL'Occhio del Comando è tuo: te lo sei $Gguadagnato:guadagnata;.$B$BMostra l'insegna, Comandante $N.",
  reward = "Incanala il potere dell'insegna e fa' che il nemico oda le tue parole. La potenza dell'Orda non si discute!",
}
T[7168] = {
  title = "Ascendi e Fatti Riconoscere",
  progress = "I più non vivono abbastanza a lungo per elevarsi al di sopra della propria mediocrità. Tu ti sei $Gdimostrato:dimostrata; $Gun soldato esemplare:una soldatessa esemplare;, $C, ed è giunto il momento.$B$BPresenta la tua insegna.",
  reward = "Che i nostri nemici vedano chi li ha abbattuti: $Gun soldato:una soldatessa; di grado! Combatti per la gloria degli Stormpike!",
}
T[7169] = {
  title = "$GOnorato:Onorata; nella Guardia",
  progress = "Alla base sono tutti in fermento per le tue imprese nel Field of Strife! Hai inferto al nemico colpi possenti — gli hai schiacciato il morale! E per questo hai guadagnato un grado d'onore fra gli Stormpike.$B$BPresenta la tua insegna.",
  reward = "Il re ha saputo del tuo eroismo al fronte, $C. Continua a difendere con fermezza la Stormpike Guard!",
}
T[7170] = {
  title = "Riverenza Guadagnata",
  progress = "Devo saperlo, $N: quando guardi il nemico dritto negli occhi, ci vedi la paura? Adesso tremano davanti a te? Devono capire che sono sconfitti!$B$BHai guadagnato la riverenza della Guardia. Presenta la tua insegna!",
  reward = "Quando ci siamo conosciuti non avrei mai immaginato che stesse nascendo $Gun eroe:un'eroina;. Avanti così, $Gsoldato:soldatessa;!",
}
T[7171] = {
  title = "Eroi Leggendari",
  progress = "Ho davanti $Gun eroe osannato:un'eroina osannata; dell'Alleanza.$B$B<Lieutenant Haggerdin fa il saluto militare.>$B$BIn pochi sono arrivati a un grado così alto fra gli Stormpike. Ho visto il nemico cadere davanti a te, e la sua determinazione sgretolarsi in tua presenza. Quando ti getti nella mischia diventi il faro di speranza delle nostre forze!$B$BPresenta la tua insegna.",
  reward = "L'Occhio del Comando lo porterai sicuramente tu!",
}
T[7172] = {
  title = "L'Occhio del Comando",
  progress = "Fagli sentire la tua voce, Comandante $N! Fagli conoscere la paura e mostragli che potere ha il clan Stormpike nelle sue file!$B$BPresenta le tue insegne.",
  reward = "Tocca a te portare le nostre truppe alla vittoria, Comandante! I soldati sono sotto il tuo comando: gli ordini li prenderanno direttamente da te. Guidali.... Schiaccia il clan Frostwolf.",
}
T[7181] = {
  title = "La Leggenda di Korrak",
  desc = "Gli Stormpike invasori non sono l'unica minaccia della regione, $Gsoldato:soldatessa;. Nella Valle si combatte su due fronti: anche i troll cannibali Winterax si battono per il potere.$B$BA guidarli è Korrak the Bloodrager — una bestia crudele e astuta.$B$BAttaccare Korrak potrebbe essere un colpo devastante per il clan Winterax. Uccidi la bestia e sarai $Gricompensato:ricompensata;!",
  obj = "Secondo la leggenda, il capo dei potenti troll Winterax appare quando vuole per seminare il caos fra gli abitanti di Alterac Valley.$B$BSe Korrak dovesse farsi vedere, distruggilo e torna da Warmaster Laggrond.",
}
T[7201] = {
  title = "L'Ultimo Elemento",
  desc = "C'è lavoro per chi si spinge nelle profondità, $N.$B$BI Dark Irons sono diventati maestri nel costruire golem di una potenza enorme.$B$BSecondo le prime notizie delle nostre spie, i nani alimentano le loro creazioni con una fonte di energia unica, che dà loro una potenza letale senza pari.$B$BImmagina cosa potremmo fare con i nostri abominations, se mettessimo le mani su quest'essence of the elements! Metti pure sottosopra quella città, se serve, ma non tornare senza l'essenza! Il compenso varrà il rischio.",
  obj = "Viaggia fino a Blackrock Depths e recupera 10 Essence of the Elements. La tua prima idea è frugare tra i golem e i costruttori di golem. Ricordi che Vivian Lagrave ha anche borbottato qualcosa sugli elementali.",
  progress = "Fammele vedere!",
  reward = "Magnifico! Le farò portare subito a Undercity da un corriere!$B$BQuanto a te — ecco il compenso promesso. Tieni il resto, lurida bestia!",
}
T[7202] = {
  title = "Korrak the Bloodrager",
  desc = "I troll Winterax di queste parti sono selvaggi spietati: non chiedono di meglio che buttare le nostre ossa nel loro lurido stufato.$B$BDobbiamo fargli vedere quanto siamo forti!$B$BDalle loro caverne abbiamo recuperato dei tomi che descrivono la loro gerarchia di comando. Stando a questi reperti, il capo, Korrak the Bloodrager, di solito resta nascosto finché non ha un motivo per farsi vedere.$B$BSe muore Korrak, muore anche il Winterax Clan! Uccidilo e torna qui.",
  obj = "Secondo la leggenda, il capo dei potenti troll Winterax appare quando vuole per seminare il caos fra gli abitanti di Alterac Valley.$B$BSe Korrak dovesse farsi vedere, distruggilo e torna da Lieutenant Haggerdin in Alterac Mountains.",
}
T[7221] = {
  title = "Parla con Prospector Stonehewer",
  desc = "Ah, $N, eccoti a rapporto, eh? Ottimo, agli Stormpike serve chiunque riusciamo a radunare!$B$BVa' a parlare con Prospector Stonehewer a Dun Baldar: sta cercando gente per una missione vitale in territorio nemico. La troverai nella parte più bassa della guarnigione di Dun Baldar.$B$BE mentre attraversi Dun Baldar tieni gli occhi aperti. C'è parecchio lavoro per $Gun:una; $C $Glaborioso:laboriosa; che non ha paura di sporcarsi le mani.",
  obj = "Parla con Prospector Stonehewer nella guarnigione di Dun Baldar.",
}
T[7222] = {
  title = "Parla con Voggah Deathgrip",
  desc = "$GUn:Una; $C? Bene! Ci fa piacere vederti ad Alterac, $N. I nani intrusi e i loro alleati ci stanno invadendo la valle, e invitiamo tutta l'Orda a unirsi a noi nel giusto massacro!$B$BParla con Voggah Deathgrip: cerca agenti per una missione importante nella roccaforte dell'Alleanza nell'Alterac Valley!$B$BVoggah lo troverai nella Frostwolf Keep.",
  obj = "Parla con Voggah a Frostwolf Keep.",
}
T[7223] = {
  title = "Armor Scraps",
  desc = "Nell'Alterac Valley le battaglie infuriano senza sosta, e quello che ci arriva da Ironforge non basta a equipaggiare le nostre truppe esperte.$B$BSe sul campo di battaglia trovi degli armor scraps, portameli: darai una mano allo sforzo bellico!",
  obj = "Porta 20 Armor Scraps a Murgot Deepforge a Dun Baldar.",
  progress = "$N, mi hai portato degli armor scraps?",
  reward = "Questi pezzi sono buoni, $N. Ci posso fabbricare equipaggiamento nuovo per le nostre truppe.$B$BSe le scorte salgono abbastanza, forse le nostre unità da combattimento più esperte scenderanno in campo!",
}
T[7224] = {
  title = "Bottino Nemico",
  desc = "Quando combatti il nemico, raccogli i pezzi delle armature e portameli. Ne farò armature per le nostre truppe!",
  obj = "Porta 20 Armor Scraps a Smith Regzar in Frostwolf Village.",
  progress = "Come va la caccia, $N? Hai degli armor scraps per me?",
  reward = "Andranno benissimo. Li fonderò, li rattopperò, e nessuno capirà mai che erano di quei codardi degli Stormpike!$B$BGrazie, $N. E fatti lucidare quell'armatura...",
}
T[7241] = {
  title = "In Difesa dei Frostwolf",
  desc = "In una terra lontana risuonano i tamburi di guerra, $C. La malvagia Stormpike Guard di Ironforge attacca il clan prediletto del tuo Capoguerra.$B$BBasta guardarti per capire che sei davvero $Gtemprato:temprata; dalla battaglia e $Gpronto:pronta; ad abbracciare la causa dei Frostwolf.$B$BOra sta a te fare il prossimo passo della tua evoluzione.$B$BL'ingresso dell'Alterac Valley lo troverai ad Alterac, a nord di Tarren Mill: lì c'è Warmaster Laggrond. Sbrigati, $C, perché la battaglia è già qui!",
  obj = "Raggiungi l'Alterac Valley, che si trova fra le Alterac Mountains. Trova Warmaster Laggrond — che sta fuori dall'ingresso del tunnel — e parla con lui per iniziare la tua carriera come $Gsoldato:soldatessa; dei Frostwolf. L'Alterac Valley è a nord di Tarren Mill, ai piedi delle Alterac Mountains.",
  reward = "Chi vuole diventare un soldato dei Frostwolf deve prima essere messo alla prova...",
}
T[7261] = {
  title = "L'Imperativo Sovrano",
  desc = "Nelle valli di Alterac stiamo combattendo una battaglia brutale. Da una parte ci attaccano i troll cannibali Winterax, dall'altra il selvaggio Frostwolf Clan. In nome di King Magni Bronzebeard, vanno sterminati tutti e due! Per il regno di Ironforge, conquistare, ripulire e convertire quella terra è un imperativo sovrano e territoriale.$B$BAhimè, i soldati non crescono sugli alberi! Presentati a Lieutenant Haggerdin, fuori dall'Alterac Valley, e comincia a servire con onore fra gli Stormpike.",
  obj = "Raggiungi l'Alterac Valley nelle Hillsbrad Foothills. Fuori dal tunnel d'ingresso, trova Lieutenant Haggerdin e parla con lui.$B$BPer la gloria di Bronzebeard!",
  reward = "Mettiamoci al lavoro!",
}
T[7281] = {
  title = "Amore Fraterno",
  desc = "Che tragedia... Mio fratello, un comandante degli Stormpike, mi affronta sul campo di battaglia.$B$BFra i quattro Comandanti degli Stormpike è senza dubbio il più pericoloso. Se viene ucciso, forse The Banshee Queen potrebbe convertirlo come ha convertito me — mostrargli i suoi errori...$B$BMio fratello lo troverai nel cuore del territorio nemico. Uccidilo e torna da me. Confido che saprai portare a termine questa missione, $Gsoldato:soldatessa;.$B$BE, $Gsoldato:soldatessa;, non andarci da $Gsolo:sola;.",
  obj = "Addentrati nel territorio degli Stormpike e uccidi Commander Karl Philips. Torna da Commander Louis Philips quando avrai finito.",
  progress = "Quanto deve soffrire a restare fra i vivi, mentre il suo amato fratello è asceso alla perfezione.",
  reward = "Il tuo eroismo non passerà inosservato, $N.$B$BPer salvarlo, non posso perdere tempo. Bisogna contattare Sylvanas!",
}
T[7282] = {
  title = "Amore Fraterno",
  desc = "Bisogna mettere fine alle sue sofferenze, soldato! Non sa quello che fa: è diventato un servo senza volontà della temuta Regina Banshee.$B$BSpingiti oltre il Field of Strife, nel profondo del territorio dei Frostwolf. Trova mio fratello e distruggilo: il suo tormento deve finire.",
  obj = "Raggiungi il territorio dei Frostwolf e uccidi Commander Louis Philips. Torna da Commander Karl Philips quando avrai completato il compito.",
  progress = "Non do a cuor leggero un ordine simile, soldato.",
  reward = "Ti sei $Gricordato:ricordata; di bruciare il cadavere, vero?",
}
T[7301] = {
  title = "Signori del Cielo Caduti",
  desc = "I loro Comandanti di Squadriglia sono nostri prigionieri, $R. Lassù nei cieli la battaglia è stata furiosa, ma alla fine sono caduti! Purtroppo, durante un contrattacco contro la Frostwolf Keep, hanno abbattuto i nostri piloti migliori, e tu devi scoprire che fine hanno fatto.$B$BCerca a Tower Point Ovest e alla Frostwolf Keep: sono gli ultimi posti dove li hanno visti. Perlustra queste zone a fondo.",
  obj = "Raggiungi il territorio dei Frostwolf e cerca Wing Commander Slidore, Wing Commander Vipore e Wing Commander Ichman. Torna da Commander Duffy una volta completata la missione.",
  progress = "Hai qualche buona notizia per me?",
  reward = "Incredibile! Li hai liberati, vero? Vero??? Be', almeno sappiamo dove li tenevano.",
}
T[7302] = {
  title = "Signori del Cielo Caduti",
  desc = "Il nostro supporto aereo è allo sbando, $N: i Comandanti di Squadriglia sono stati abbattuti sopra il territorio nemico. Devi scoprire che fine hanno fatto, così potremo tentare un salvataggio!$B$BGuse l'hanno vista l'ultima volta mentre sorvolava l'Icewing Bunker. Jeztor's War Rider l'hanno avvistato vicino alla segheria degli Stormpike. E Mulverick... quello sconsiderato l'hanno visto precipitare vicino al Fortilizio Nord di Dun'Baldar.$B$BNon ho altre informazioni. In marcia! E perlustra a fondo quelle zone.",
  obj = "Scopri che fine hanno fatto Wing Commander Guse, Wing Commander Jeztor e Wing Commander Mulverick. Torna da Commander Mulfort quando avrai completato la missione.",
  progress = "Come va la ricerca, $Gsoldato:soldatessa;?",
  reward = "Ottimo lavoro! Le informazioni che hai raccolto saranno preziosissime per la nostra causa.",
}
T[7321] = {
  title = "Soothing Turtle Bisque",
  desc = "Chi l'ha detto che i non morti non sanno niente di cucina? Prendi ad esempio la mia ricetta segreta per la Zuppa Cremosa di Tartaruga: conosco gente che risorgerebbe solo per gustarsene una scodella! Eh, eh...$B$BA proposito, è da un po' che non riesco a prepararla. Una volta andavo di persona al Lake Lordamere a cacciare le snapjaws, quelle brutte bestie, ma adesso il lavoro non mi lascia allontanare da qui.$B$BPortami un po' di Turtle Meat delle snapjaws e delle soothing spices, e ti faccio vedere come si fa!",
  obj = "Porta 10 pezzi di Turtle Meat e delle Soothing Spices a Christoph Jeffcoat a Tarren Mill.",
  progress = "Sei $Griuscito:riuscita; a trovare gli ingredienti? Te lo dico io, da queste parti adesso girano fin troppi vermi dell'alleanza... Per me si sono già spinti anche troppo vicino...",
  reward = "La mia soothing turtle bisque ti terrà al caldo in una notte fredda... ammesso che ti interessino queste cose.",
  en_title = "Soothing Turtle Bisque",
  en_obj = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Christoph Jeffcoat in Tarren Mill.",
}
T[7341] = {
  title = "Uno Scambio Equo",
  progress = "Saluti, $R. Sono Kolark, Cacciatore di Taglie di Thunderbluff. Gran parte del mondo ho percorso, e molto ho visto.$B$BViaggiando per i South Seas ho scoperto queste meravigliose thorium headed arrows. Ahimè, di frecce ne ho una scorta infinita, mentre le cartucce mi sono finite. Bah, nessun Tauren che si rispetti si farebbe mai vedere con un arco fragile, nemmeno da morto. Le frecce non servono a niente!$B$BTi propongo uno scambio alla pari: thorium shells in cambio delle mie thorium headed arrows. Affare fatto?",
  reward = "Eccellente! Sono un Tauren di parola, $R. Le frecce sono tue.",
}
T[7342] = {
  title = "Le Frecce Sono per Femminucce",
  progress = "Ma ci credi a questa robaccia?! L'ultima spedizione di munizioni da Kharanos è stata un pasticcio! E adesso non ci restano che queste frecce fragili e buone a nulla! Che diavolo me ne faccio di 500.000 thorium headed arrows?$B$BFacciamo così, $Gragazzo:ragazza;. Tu mi porti delle thorium shells e io ti do in cambio delle thorium headed arrows — alla pari! Affare fatto?",
  reward = "Questo sì che si chiama affare fatto! Le frecce sono tue.",
}
T[7361] = {
  title = "Favore fra i Darkspear",
  desc = "<Najak ringhia.>$B$BPrima che ci fossero gli elfi della notte, c'era il troll. Gli elfi vengono dal troll.$B$BI loro attacchi ribelli contro il mio popolo non verranno tollerati. Staghelm ci vuole spazzare via — cancellare ogni traccia di chi ha dato la vita a lui e ai suoi simili. Non succederà!$B$BPer ogni elfo della notte che ucciderai e decapiterai, Najak ti concederà il favore dei Darkspear. La voce delle tue imprese correrà per tutto Kalimdor e per gli Eastern Kingdoms. Ora va' e servi i Darkspear!",
  obj = "Il tuo compito è uccidere i giocatori elfi della notte avversari in Alterac Valley.$B$BUccidi un elfo della notte e torna da Najak Hexxen alla Frostwolf Keep con una Severed Night Elf Head.",
  progress = "Cercano di sterminarci? E invece saranno sterminati loro.",
  reward = "$N, è solo uno fra migliaia. Ma hai fatto un buon lavoro.",
}
T[7362] = {
  title = "$GAlleato:Alleata; dei Tauren",
  desc = "La Vecchia Saggia mi ha mandato in questa zona di guerra a studiare le altre razze, e più precisamente a raccogliere campioni di gnomo. A Magatha interessa soprattutto come riescono a sopravvivere. Già, gli gnomi — per quanto pateticamente deboli e minuscoli — sono molto resistenti, sia in combattimento sia fuori.$B$BPer tua fortuna, cerco dei bruti che eseguano gli ordini di Magatha. Torna da me con dei tufts of gnome hair e i tauren ti considereranno $Gun alleato:un'alleata;.",
  obj = "Il tuo compito è uccidere i giocatori gnomi avversari in Alterac Valley.$B$BUccidi uno gnomo e torna da Ravak Grimtotem alla Frostwolf Keep con un Tuft of Gnome Hair.",
  progress = "Da dove vengano i capelli non m'importa, $R.",
  reward = "Già, questo è gnomo, non c'è dubbio. Ben fatto, $R, ma c'è ancora lavoro da fare.",
}
T[7363] = {
  title = "La Condizione Umana",
  desc = "Gli umani sono davvero detestabili.$B$B<Commander Philips fa una smorfia.>$B$BSarò pure un soldato dei Frostwolf, ma resto un servitore di Sylvanas.$B$BE durante il servizio sbrigo qualche lavoro extra per i Dark Apothecaries of the Undercity.$B$BMi hanno affidato il compito di raccogliere human bone chips con cui curare la condizione umana.$B$BHo l'autorizzazione a passarlo ai miei subordinati.$B$BTrovali. Uccidili. Riportami le loro schegge d'osso.",
  obj = "Il tuo compito è uccidere i giocatori umani avversari in Alterac Valley.$B$BUccidi un umano e torna da Commander Louis Philips (che si aggira fra le prime linee e la rocca Frostwolf) con un'Human Bone Chip.$B$BUna cura per la condizione umana è a portata di mano!",
  progress = "Sì, è vero: mio fratello è un umano. Che vergogna... Una macchia sul mio stato di servizio quasi immacolato.",
  reward = "Sarebbe più facile se accettassero la malattia e si arrendessero al tuo tocco guaritore. Ma probabilmente sarebbe anche meno divertente. Continua così! Li cureremo, in un modo o nell'altro.",
}
T[7364] = {
  title = "Taglia di Gnomeregan",
  desc = "Mi ha mandato il Gran Inventore in persona, su questo campo di battaglia, a difendere i miei fratelli e le mie sorelle gnomi. Ci è giunta voce che i tauren danno la caccia agli gnomi e li uccidono. E il peggio è che ai caduti strappano ciuffi dei gloriosi capelli gnomeschi. Queste atrocità devono finire. Dobbiamo ripagarli con la stessa moneta!$B$BLi voglio senza zoccoli, $C. Portami i loro zoccoli! Dimostra di essere $Gun alleato:un'alleata; degli gnomi.",
  obj = "Ti è stato affidato il compito di uccidere i giocatori tauren avversari nell'Alterac Valley.$B$BUccidi un tauren e torna da Dirk Swindle a Dun'Baldar con un Tauren Hoof.",
  progress = "Falli zoppicare, $N. Che capiscano che il popolo gnomesco non si lascia mettere i piedi in testa!",
  reward = "*Dirk lancia lo zoccolo su un mucchio dietro di sé.*",
}
T[7365] = {
  title = "Il Requiem di Staghelm",
  desc = "L'ordine l'ha dato Staghelm. Tutti i troll sul campo di battaglia vanno sterminati. Pretendono di aver dato vita agli elfi della notte, e a pretese così assurde si risponde con la forza e con il dovuto pregiudizio.$B$BUccidili e torna da me col loro mojo. Lo ripeto: voglio che tu gli rubi il mojo.",
  obj = "Ti è stato affidato il compito di uccidere i giocatori troll avversari nell'Alterac Valley.$B$BUccidi un troll e torna da Athramanis a Dun'Baldar con il Darkspear Troll Mojo.",
  progress = "Ho ancora nel naso la puzza di quei troll fetidi.",
  reward = "Grazie, $N. Ora l'aria è un po' più pura.",
}
T[7366] = {
  title = "La Misericordia dell'Arcivescovo",
  desc = "L'Arcivescovo è buono quanto è saggio. Pensare che un uomo possa guardare con misericordia una massa di miserabili come quella...$B$B<Commander Philips scuote la testa, incredulo.>$B$BTroppo buono... Davvero troppo buono.$B$BL'Arcivescovo ci chiede di avere pietà dei non morti e di dar loro una morte rapida e definitiva. In cambio di una misericordia così grande chiediamo soltanto i loro cuori, neri e pieni di malattie.$B$BPortami i cuori dei Forsaken, da bruciare in una cerimonia alla Cathedral of Light. Fa' presto, $N!",
  obj = "Ti è stato affidato il compito di uccidere i giocatori Forsaken avversari nell'Alterac Valley.$B$BUccidi un Forsaken e torna da Commander Karl Philips (che si aggira tra la segheria e la miniera) con un Forsaken Heart.",
  progress = "Benedictus! All'ombra della sua grandezza non sono che un granello. Sia lodato!",
  reward = "Sia lodato Benedictus! Un'altra anima perduta, che le fiamme incandescenti della Luce salveranno presto!$B$BOrsù, va', o $Gsoldato:soldatessa; della Luce! Ce ne sono altre da salvare!",
}
T[7367] = {
  title = "Disinnescare la Minaccia",
  desc = "I Frostwolf hanno riempito di trappole le prime linee e le basi, $C. Quando invadi il territorio nemico, guarda bene dove metti i piedi.$B$BSe vuoi colpirli duro, devi togliergli la fonte delle munizioni antiuomo — cioè il loro esperto di esplosivi. Uccidilo e potrai disinnescare le mine senza pericolo. E finché lui resterà a terra, resteranno giù anche le mine.$B$BProbabilmente lo troverai in una torre vicino all'Iceblood Garrison. Buona fortuna!",
  obj = "Trova il Frostwolf Explosives Expert e uccidilo. Torna dallo Stormpike Explosives Expert quando avrai finito.",
}
T[7368] = {
  title = "Disinnescare la Minaccia",
  desc = "Sulle mine so tutto. Dopotutto, qui sulle prime linee sono io a piazzarle tutte.$B$BSe vuoi disinnescare i campi minati degli Stormpike, ti basta uccidere il loro esperto di esplosivi. Quel nano codardo se ne starà di sicuro nascosto nella prima torre del Field of Strife. Fallo fuori e le mine, una volta disinnescate, non torneranno più.$B$BSe ti capita di ucciderlo, torna qui a dirmelo. Nessuna buona azione dovrebbe restare senza ricompensa.",
  obj = "Trova lo Stormpike Explosives Expert e uccidilo. Torna dal Frostwolf Explosives Expert quando avrai finito.",
}
T[7385] = {
  title = "Un Gallone di Sangue",
  progress = "Se vuoi, puoi offrire quantità maggiori del sangue tolto ai nostri nemici. Accetterò con piacere offerte da un gallone, $N.",
  reward = "Il sangue dei nostri nemici è stato versato. Mescolerò questo sangue con quello che abbiamo già raccolto, e quando l'offerta sarà completa il Signore del Ghiaccio mostrerà a questi cani Stormpike tutta l'ira del Frostwolf Clan!",
}
T[7386] = {
  title = "Ammasso di Cristalli",
  progress = "A volte, in battaglia, potresti restare $Gtrincerato:trincerata; per giorni o settimane di fila. Durante quei periodi più lunghi potrebbe capitarti di raccogliere grossi ammassi di storm crystals dei Frostwolf.$B$BIl Circolo accetta queste offerte, $N.",
  reward = "Ben fatto, $N. Con il potere di questi talismani accrescerò la magia già raccolta. Quando ne avremo accumulato abbastanza, concentrerò le energie riunite e invocherò il Forest Lord in aiuto della nostra causa.",
}
T[7401] = {
  title = "Wanted: DWARVES!",
  desc = "Per ordine di Sergeant Yazra Bloodsnarl, tutti i nani sul campo di battaglia vanno uccisi a vista.$B$BSe uccidi un nano in combattimento, strappagli la colonna vertebrale e lascia lì un mucchio di puzza e marciume senza spina dorsale: sarà un monito per chiunque osi opporsi alla potenza dei Frostwolf.$B$BPoi torna da Sergeant Yazra Bloodsnarl con la prova delle tue gesta eroiche.",
  obj = "Ti è stato affidato il compito di uccidere i giocatori Nano avversari in Alterac Valley.$B$BUccidi un Nano e strappagli la colonna vertebrale. Porta la Dwarf Spine a Sergeant Yazra Bloodsnarl a Frostwolf Keep.",
  progress = "Io l'ironia la tratto all'ingrosso, soldato.",
  reward = "Adesso hai licenza di decimare i nani a dozzine, $C!$B$B<Yazra fissa per un momento un punto lontano.>$B$BLa prima svertebrazione non si scorda mai...",
}
T[7402] = {
  title = "Wanted: ORCS!",
  desc = "Per ordine di Corporal Noreg Stormpike, tutti i soldati idonei degli Stormpike sono tenuti a uccidere qualunque orco avversario incontrino sul campo di battaglia.$B$BI soldati dovranno strappare dalle fauci del nemico una zanna o un dente e presentare detto dente a prova dell'impresa.$B$BIndossare guanti protettivi.",
  obj = "Ti è stato affidato il compito di uccidere i giocatori Orco avversari in Alterac Valley.$B$BUccidi un Orco e porta l'Orc Tooth a Corporal Noreg Stormpike a Dun Baldar.",
  progress = "Ti serve una pinza, per strappare i denti?",
  reward = "Bene, $N. Aspetto i topolini.",
}
T[7429] = {
  title = "Libera Knot!",
  progress = "Si chiama Gordok Shackle Key — be', almeno così continuano a chiamarla questi \"paciocconi\". Potrebbe averla uno qualunque degli ogres, credo, ma non saprei dirti chi. Forse è più facile che ce l'abbiano le guardie...$B$BMa che dico — ce l'hai già, vero?! È quella lì??!",
  reward = "Oh, grazie di avermi liberato! Tu — numero uno in classifica. Tutti gli altri — numero due o peggio.$B$BLo sapevo che la mia vita era destinata a qualcosa di più che fare da antipasto a qualche ogre!",
}
T[7441] = {
  title = "Pusillin e l'Elder Azj'Tordin",
  desc = "Ho abbassato la guardia per un attimo soltanto, $Gstraniero:straniera;, nella fretta di sfuggire alla stretta del Principe caduto, ed è bastato: l'imp Pusillin, uno dei demoni più immondi, mi ha derubato del book of incantations e della chiave delle sale di Eldre'Thalas, un tempo grandiose.$B$BDella chiave non mi importa più: ho scambiato l'immortalità con la libertà. Del mio book of incantations, invece, ho un bisogno disperato.$B$BTrova l'imp, Pusillin, e riprendi il mio libro.$B$BCerca Pusillin nel Warpwood Quarter of Dire Maul.",
  obj = "Raggiungi Dire Maul e trova l'Imp, Pusillin. Convinci Pusillin, con ogni mezzo, a darti il Book of Incantations di Azj'Tordin.$B$BSe recuperi il Book of Incantations, torna da Azj'Tordin, a Lariss Pavilion, in Feralas.",
  progress = "Non rimpiango nulla, $Gstraniero:straniera;. La Regina se n'è andata da tempo, e la follia di Prince Tortheldrin ha rovinato le opere degli Shen'Dralar. Cerco solo la libertà... La fuga...",
  reward = "L'hai trovato! Sia maledetto quel miserabile imp. Di beni materiali, ahimè, ne ho ben pochi: scegli pure fra quello che posso offrirti.",
}
T[7461] = {
  title = "La Follia Interiore",
  desc = "Hai sentito abbastanza? Sei $Gun uomo:una donna; d'azione?$B$BQuesta follia deve cessare: l'era degli immortali è tramontata da tempo. Distruggi i guardiani attorno ai piloni e il campo di forza si abbasserà; poi elimina Immol'thar. A quel punto il Principe avrà perso gran parte del suo potere: attaccalo e finiscilo. Dai riposo agli spiriti di questa città, $Gavventuriero:avventuriera;.",
  obj = "Devi distruggere i guardiani attorno ai 5 Piloni che alimentano la Prison of Immol'thar. Una volta spenti i Piloni, il campo di forza che circonda Immol'thar si sarà dissolto.$B$BEntra nella Prison of Immol'thar ed elimina il demone immondo che si trova al suo centro. Infine, affronta Prince Tortheldrin nell'Athenaeum.$B$BSe completi questa missione, torna dalla Shen'dralar Ancient nel cortile.",
  progress = "Stai $Gattento:attenta;, $Gavventuriero:avventuriera;. Il Principe è... persuasivo.",
  reward = "Ti ringraziamo, $Geroe:eroina;.",
}
T[7462] = {
  title = "Il Treasure of the Shen'dralar",
  desc = "Sotto la scalinata della biblioteca, l'Athenaeum, troverai nascosta un'antica cassa. Prendi ciò che desideri.",
  obj = "Torna all'Athenaeum e trova il Treasure of the Shen'dralar. Ritira la ricompensa!",
  reward = "Apri la cassa e dentro trovi...",
}
T[7463] = {
  title = "Ristoro Arcano",
  desc = "$GUn:Una; $R $Gmago:maga;! Che meraviglia. Non vedevo uno della tua specie da... oh, da quanto sarà? 500 anni, ormai!$B$BHo qualcosa che ti toglierà la sete, ma prima mi devi fare un lavoro.$B$B<Lydros ridacchia.>$B$BC'è un'anomalia a Eldre'Thalas: un water elemental si è stabilito nell'ala est, e la sua presenza va catalogata!$B$BAvventurati nel Warpwood Quarter ed estrai una parte dell'essenza elementale di Hydrospawn. Riportamela, e ti insegnerò un piccolo incantesimo utile.",
  obj = "Viaggia fino a Warpwood Quarter of Dire Maul e uccidi il water elemental Hydrospawn. Torna da Lorekeeper Lydros ad Athenaeum con l'Hydrospawn Essence.",
  progress = "Sì? Ti conosco?",
  reward = "Splendido! Chi sei, già? Oh, non importa. Cosa dovevo darti? Mmh... beh, sei $Gun mago:una maga;: questo forse ti sarà utile.",
}
T[7481] = {
  title = "Leggende Elfiche",
  desc = "Diversi anni fa un maestro elfico solitario, di nome Kariel Winthalus, è fuggito dalla sua terra natale devastata, portando con sé alcuni antichi manufatti elfici.$B$BSeguendo le tracce del maestro perduto, siamo partiti dalle rovine di Quel'Thalas, abbiamo attraversato le Burning Steppes e le grandi distese del mare, e siamo arrivati fino a Feralas.$B$BSospettiamo che l'elfo si sia rifugiato nelle sale di Eldre'Thalas (quella che oggi chiamano Dire Maul).$B$BDevi trovarlo, $Gavventuriero:avventuriera;. Vivo o morto che sia, dobbiamo recuperare la conoscenza che portava con sé!",
  obj = "Cerca Kariel Winthalus a Dire Maul. Torna da Sage Korolusk, a Camp Mojache, con qualunque informazione tu riesca a trovare.",
  progress = "La studiosa elfa della notte Runethorn, mia collega, sta reclutando alleati per questo compito.",
  reward = "Che peccato... che tragedia. Gli oggetti sono andati perduti, dici? E di lui nessuna traccia, eh?",
}
T[7482] = {
  title = "Leggende Elfiche",
  desc = "Diversi anni fa un maestro elfico solitario, di nome Kariel Winthalus, è fuggito dalla sua terra natale devastata, portando con sé alcuni antichi manufatti elfici.$B$BSeguendo le tracce del maestro perduto, siamo partiti dalle rovine di Quel'Thalas, abbiamo attraversato le Burning Steppes e le grandi distese del mare, e siamo arrivati fino a Feralas.$B$BSospettiamo che l'elfo si sia rifugiato nelle sale di Eldre'Thalas (quella che oggi chiamano Dire Maul).$B$BDevi trovarlo, $Gavventuriero:avventuriera;. Vivo o morto che sia, dobbiamo recuperare la conoscenza che portava con sé!",
  obj = "Cerca Kariel Winthalus a Dire Maul. Torna da Scholar Runethorn, a Feathermoon, con qualunque informazione tu riesca a trovare.",
  progress = "Il saggio tauren Korolusk, mio collega, sta reclutando alleati per questo compito.",
  reward = "Che peccato... che tragedia. Gli oggetti sono andati perduti, dici? E di lui nessuna traccia, eh?",
}
T[7483] = {
  title = "Libram of Rapidity",
  desc = "Master Winthalus ha perso il Libram of Rapidity nell'ala est. Con il Compendio puoi applicare all'equipaggiamento un piccolo incantesimo di rapidità. Trucchetti da salotto, a dire il vero...$B$BComunque, se ti interessa, dovrai presentare il Compendio con alcuni reagenti di base.$B$BMmh... servono anche, credo, del blood of heroes, un pristine black diamond e dei large brilliant shards. Potrei sbagliarmi!$B$B<Lydros scrolla le spalle.>",
  obj = "Porta un Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards e 2 Blood of Heroes a Lorekeeper Lydros a Dire Maul per ricevere un Arcanum of Rapidity.",
  progress = "Che c'è? Ho tanto da catalogare!",
  reward = "<Lydros sbadiglia.>$B$BEcco l'Arcanum of Rapidity, come promesso. Non spenderlo tutto in una volta.$B$B<Lydros ridacchia.>",
}
T[7484] = {
  title = "Libram of Focus",
  desc = "Uno dei famigli dello Storico più giovane si è quasi interessato a questo compendio. Poverino, aveva solo qualche settimana.$B$BChi di voi è più portato per la magia potrebbe trovare interessante questo oggetto.$B$BIl Libram of Focus è andato perduto in quest'ala, e posso solo supporre che ce l'abbia uno degli spiriti degli Highborne.$B$BPortami il Compendio con dei large brilliant shards, della skin of shadow e un pristine black diamond, e io evocherò l'Arcanum.",
  obj = "Porta un Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards e 2 Skin of Shadow a Lorekeeper Lydros a Dire Maul per ricevere un Arcanum of Focus.",
  progress = "Ancora tu? E adesso che altro vorrai mai?",
  reward = "Mentre applichi l'incantamento, vedi di non farti male, $R.",
}
T[7485] = {
  title = "Libram of Protection",
  desc = "Quando ha perso questo compendio ha pianto come un bambino. Bada, anch'io ho pianto su dei testi — non c'è perdita più grande di quella del sapere e della storia — ma piangere per quest'accozzaglia di formule quasi inutili? Assurdo! Mi è venuto da pensare che il Principe gli facesse un favore, a strappargli la carne dalle ossa.$B$BPortami il Compendio con un pristine black diamond, dei large brilliant shards e delle frayed abomination stitching, e io ricreerò l'Arcanum.$B$BAh, e controlla l'ala nord.",
  obj = "Porta un Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards e 1 Frayed Abomination Stitching a Lorekeeper Lydros a Dire Maul per ricevere un Arcanum of Protection.",
  progress = "È la mia pazienza a risparmiarti la sofferenza.",
  reward = "Sì, sì... Calmati. Ecco il tuo Arcanum, come promesso.",
}
T[7486] = {
  title = "La Ricompensa di $Gun Eroe:un'Eroina;",
  desc = "$N, i servizi che hai reso ai Signori delle Acque sono andati oltre tutto quello che potevamo aspettarci dagli abitanti di questo mondo.$B$BNon capiamo le idee del tuo popolo sulla gratitudine o sul premiare le buone azioni, ma stavolta... forse una ricompensa è meritata.$B$BSotto le onde, ai piedi del lato meridionale di quest'isola, troverai uno scrigno. Dentro c'è la tua... ricompensa.$B$BVa', $N, e prendi la tua ricompensa.",
  obj = "Prendi la tua ricompensa dall'Hydraxis' Coffer.",
  reward = "La voce di Hydraxis scende dalla superficie delle acque...$B$B\"Scegli quello che ti si addice di più, $N, e che ti protegga dai nemici dei Signori delle Acque.\"",
}
T[7487] = {
  title = "Sintonia con il Nucleo",
  desc = "Tutto intorno a noi ci sono squarci che si agitano, si lacerano e collassano, $R. A neanche due passi da qui ce n'è uno che attraversa le profondità del Blackrock Mountain e conduce fin nelle fauci del Firelord.$B$B$GSorpreso:Sorpresa;? Peccato... Le razze mortali non riescono a comprendere ciò che non possono vedere, toccare o sentire.$B$BIl portale c'è, te lo assicuro, ed è possibile entrarci.$B$BTi ho incuriosito? Sintonizzarsi è semplice: avventurati nei Blackrock Depths e recupera un core fragment. Quando me lo riporterai, sintonizzerò la tua essenza con il portale.",
  obj = "Avventurati fino al portale d'ingresso di Molten Core in Blackrock Depths e recupera un Core Fragment. Torna da Lothos Riftwaker in Blackrock Mountain quando avrai recuperato il Core Fragment.",
  progress = "Se saltassi nell'apertura adesso, potrebbe finire in un disastro... per te.",
  reward = "Attraversa l'apertura alla mia destra: ti ritroverai dentro il Molten Core.",
}
T[7488] = {
  title = "Lethtendris's Web",
  desc = "La maga Lethtendris, una crudele elfa del sangue, brutale quanto è perversa la sua dipendenza dalla magia, è fuggita a Dire Maul. Ha costruito un congegno, una ragnatela che intrappola le energie magiche del luogo, e temiamo che, se nessuno la ferma, farà danni irreparabili al nostro mondo!$B$BFermala, $N. Trovala e recupera la sua ragnatela: probabilmente lei è vicino ai satiri, nel Warpwood Quarter of Dire Maul. Portami la ragnatela, così che il suo potere possa tornare libero alle terre selvagge, senza pericolo...",
  obj = "Porta la Lethtendris' Web a Latronicus Moonspear a Feathermoon Stronghold, in Feralas.",
  progress = "Ce l'hai, la ragnatela, $N? La sua energia magica è concentrata e va dispersa!",
  reward = "Hai recuperato la ragnatela! Ben fatto, $N! Come tanti elfi della sua risma, Lethtendris è cieca davanti ai pericoli che l'abuso della magia può portare al nostro mondo. Si credono padroni della magia e non si rendono conto di essere schiavi della loro stessa dipendenza. Mi rattrista che sia morta, ma era necessario.$B$BGrazie, $N. Farò liberare senza pericolo le energie della ragnatela su una vasta area, e poi la distruggerò, così da impedire nuovi abusi della magia.",
}
T[7489] = {
  title = "Lethtendris's Web",
  desc = "L'elfa del sangue Lethtendris ha passato il segno. Voleva così tanto accumulare potere magico che ha sfidato i suoi fratelli e ha costruito un congegno insidioso: una ragnatela fatta apposta per risucchiare le energie magiche corrotte di Dire Maul. Le sta raccogliendo proprio ora, e intende scatenarle contro i suoi nemici.$B$BLethtendris va fermata. Cercala nel Warpwood Quarter of Dire Maul, sconfiggila e portami la sua ragnatela: così potrà tornare fra elfi del sangue più assennati, che la studieranno.",
  obj = "Porta la Lethtendris's Web a Talo Thornhoof a Camp Mojache, a Feralas.",
  progress = "$N, hai con te la Lethtendris's Web?",
  reward = "Ben fatto, $N. In questa ragnatela sono racchiuse enormi riserve della magia di Dire Maul, e temo i danni che potrebbero scatenarsi se qualcuno irresponsabile come Lethtendris riuscisse a imbrigliare quelle energie. La sua morte mi rattrista, ma so che finché era viva dalla ragnatela non si sarebbe mai separata.$B$BGrazie, $N. La manderò a studiosi di magia più responsabili di Lethtendris: saranno loro i nuovi custodi del suo potere.",
}
T[7490] = {
  title = "Vittoria per l'Orda",
  desc = "Hai compiuto l'impossibile. La madre della covata del Black Dragonflight giace morta ai tuoi piedi. Prendile la testa e portala al tuo Capoguerra.",
  obj = "Porta l'Head of Onyxia a Thrall a Orgrimmar.",
  progress = "<Quando vede l'enorme testa di Onyxia, per un istante l'espressione impassibile di Thrall cambia. Per poco non sguaina il possente Doomhammer.>",
  reward = "È una grande vittoria per l'Orda, $N. Tante volte hai reso onore al tuo Capoguerra. Ora tocca al Capoguerra rendere onore a te.",
}
T[7491] = {
  title = "Sotto gli Occhi di Tutti",
  desc = "Overlord Runthak ti attende nella Valley of Strength.$B$B<Thrall ti saluta.>$B$BNon far aspettare il tuo pubblico, $Geroe:eroina;.",
  obj = "Raggiungi Overlord Runthak nella Valley of Strength.",
  reward = "Scegli la ricompensa, e che comincino i festeggiamenti per la tua gloriosa vittoria.",
}
T[7492] = {
  title = "Camp Mojache",
  desc = "Talo Thornhoof, un anziano Tauren di Feralas, chiede aiuto. Di dettagli ne ha dati pochi, ma ha detto che cerca agenti per una faccenda tanto delicata... quanto grave.$B$BServi l'Orda, $N. Va' a Camp Mojache, a Feralas, e parla con Talo.",
  obj = "Parla con Talo Thornhoof a Camp Mojache, a Feralas.",
  reward = "Ah, è bello vedere $Gun:una; $C rispondere alla mia chiamata. Ho bisogno dei tuoi servigi, $N, e temo che ti condurranno su un sentiero pericoloso...$B$BUn sentiero che porta a Dire Maul.",
}
T[7493] = {
  title = "Il Viaggio È Appena Iniziato",
  reward = "$GUno sterminatore:Una sterminatrice; di draghi e $Gun conciatore esperto:una conciatrice esperta;? Non smetti mai di stupirmi, $Geroe:eroina;. Mi inchino davanti a te.$B$BAccetta, ti prego, quello che sto per insegnarti. Se vuoi distruggere ciò che resta del Black Dragonflight, questa conoscenza si rivelerà preziosissima.$B$BCon le scaglie della madre della covata crea il mantello. Proteggerà te e i tuoi alleati dal soffio incendiario del Signore di Roccianera... Nefarian.",
}
T[7494] = {
  title = "Feathermoon Stronghold",
  desc = "$N! A Feralas serve il tuo aiuto!$B$BLethtendris, una maga fuorilegge, è fuggita nelle antiche rovine elfiche di Eldre'thalas, che oggi si chiamano Dire Maul. Pare che abbia con sé un oggetto carico di una pericolosa energia magica, e bisogna recuperarlo.$B$BLatronicus Moonspear cerca agenti disposti a entrare a Dire Maul e a strapparlo a Lethtendris.$B$BServi l'Alleanza! Va' a cercare Latronicus alla Feathermoon Stronghold, a Feralas.",
  obj = "Parla con Latronicus Moonspear a Feathermoon Stronghold, in Feralas.",
  reward = "Salute a te, $N. Sono lieto di vederti, ma mi dispiace che non ci incontriamo in circostanze più piacevoli.$B$BAscolta bene: ho per te un compito di vitale importanza...",
}
T[7495] = {
  title = "Vittoria per l'Alleanza",
  desc = "Hai compiuto l'impossibile. Ai tuoi piedi giace morta la madre della covata del Black Dragonflight. Prendile la testa e portala al Gran Signore.",
  obj = "Porta l'Head of Onyxia a Highlord Bolvar Fordragon a Stormwind.",
  progress = "Per la barba di Uther!",
  reward = "Per tanti anni sono rimasto prigioniero del suo sguardo ammaliante. Finalmente vedo fatta giustizia e l'onore di Stormwind ristabilito! Oggi festeggiamo questa gloriosa vittoria!",
  en_title = "Victory for the Alliance",
  en_obj = "Take the Head of Onyxia to Highlord Bolvar Fordragon in Stormwind.",
}
T[7496] = {
  title = "Festeggiare i Bei Momenti",
  desc = "Raggiungi Major Mattingly nella Valley of Heroes, $N. Sarà lì ad aspettarti...",
  obj = "Cerca Major Mattingly in Valley of Heroes.",
  reward = "Sono pochi ad avere l'onore di una cerimonia come questa, $N. Scegli la tua ricompensa, ti prego, e potremo cominciare i festeggiamenti.",
  en_title = "Celebrating Good Times",
  en_obj = "Seek out Major Mattingly in the Valley of Heroes.",
}
T[7497] = {
  title = "Il Viaggio È Appena Iniziato",
  reward = "$GUn ammazzadraghi:Un'ammazzadraghi; e $Gun:una; $Gconciatore:conciatrice; $Gesperto:esperta;? Non finisci mai di stupire, $Geroe:eroina;. Al tuo cospetto mi sento piccolo.$B$BTi prego, accetta quello che sto per insegnarti. Se vuoi distruggere ciò che resta del Black Dragonflight, queste conoscenze ti saranno preziosissime.$B$BUsa le scaglie della madre della covata per creare il mantello: proteggerà te e i tuoi alleati dal soffio incendiario del Signore di Roccianera... Nefarian.",
  en_title = "The Journey Has Just Begun",
}
