T[7507] = {
  title = "Il Compendio di Foror",
  desc = "Hai scoperto qualcosa di grande importanza: non hai mai visto un libro come questo.$B$BA quanto pare qualcuno, o qualcosa, è riuscito a infrangere il sigillo dell'Athenaeum. Dentro, il testo è confuso e si legge a malapena.",
  obj = "Riporta il Foror's Compendium of Dragon Slaying ad Athenaeum.",
  progress = "Ah, una delle nostre più grandi raccolte, che mancava da secoli.",
  reward = "Al mercato nero questo libro ti avrebbe fruttato parecchio oro, $N, soprattutto ora che il sigillo protettivo è spezzato e i segreti per uccidere i draghi sono alla portata di chiunque abbia l'intelletto necessario per assimilare il sapere custodito in queste pagine sacre.$B$BForse ci vorrebbe una grande ricompensa... Beh, una ricompensa che richiederà uno sforzo enorme.",
}
T[7508] = {
  title = "La Forgiatura di Quel'Serrar",
  desc = "Se vuoi assumerti questo compito, consegna la dull blade a Lydros.",
  obj = "Consegna la Dull and Flat Elven Blade a Lorekeeper Lydros.",
  progress = "Eccellente, cominciamo...",
  reward = "Se riuscirai a entrare nella tana del drago, a scaldare la lama nel suo soffio infuocato e poi a temprarla nel suo sangue, la vincolerò perché tu possa usarla.",
}
T[7509] = {
  title = "La Forgiatura di Quel'Serrar",
  desc = "Porta l'unfired ancient blade nella tana di Onyxia e affrontala.$B$BPer scaldare la lama ci vorrà un po' di astuzia. Durante lo scontro cercherà di sicuro di incenerirti col suo soffio infuocato. Pianta lì vicino l'unfired ancient blade e spera che il soffio la scaldi. Se sopravvivi, raccogli quella che ora è l'heated ancient blade e finisci il drago.$B$BImmergi l'heated ancient blade nel suo cadavere fumante e otterrai la treated ancient blade.",
  obj = "Devi fare in modo che Onyxia sputi fuoco sull'Unfired Ancient Blade. Una volta fatto, raccogli quella che ora è l'Heated Ancient Blade. Attenzione, un'Heated Ancient Blade non resterà calda per sempre — il tempo stringe.$B$BL'ultimo passo prima di tornare da me è uccidere la bestia e conficcare l'Heated Ancient Blade nel suo cadavere.$B$BFallo e Quel'Serrar sarà tua.",
  progress = "Forse un giorno sarà qualcun altro a brandire la lama prismatica.",
  reward = "<Lydros mormora parole incomprensibili.>$B$BCome promesso, $C, ecco la lama di Quel'Serrar.",
}
T[7521] = {
  title = "Thunderaan il Cercatore del Vento",
  desc = "Ti ho detto tutto quello che so, $N. Tocca a te trovare l'elementium. Tocca a te distruggere la forma corporea del Firelord.$B$BFallo, e la benedizione di Thunderaan sarà tua.",
  obj = "Per liberare Thunderaan il Cercatore del Vento dalla sua prigione, devi consegnare la metà destra e la metà sinistra dei Vincoli del Wind Seeker, 10 barre di Elementium e l'Essence of the Firelord a Highlord Demitrian.",
  progress = "Metti in ginocchio il mondo, se serve!",
  reward = "Non osavo prevedere questo giorno nemmeno in sogno.$B$BContempla, mortale.$B$BCONTEMPLA COLUI CHE È PIÙ ANTICO DELL'ESISTENZA!$B$BCONTEMPLA COLUI CHE HA AFFRONTATO SIA IL TITANO SIA IL DIO!$B$BSORGI, MIO PADRONE! LIBERATI DAI VINCOLI!",
}
T[7541] = {
  title = "Al Servizio dell'Orda",
  reward = "Ai nostri studiosi servirà tempo per esaminare il pendente che ci hai portato, ma per il servizio che hai reso all'Orda vorrei offrirti un piccolo dono.$B$BGrazie, $N. Le tue azioni fanno onore a te, e a noi.",
  en_title = "Service to the Horde",
}
T[7562] = {
  title = "Mor'zul Bloodbringer",
  desc = "$N, nello studio delle arti oscure ti sei $Gspinto:spinta; a fondo, e il tuo dominio sulle creature di altri mondi è cresciuto tanto che... forse sei $Gpronto:pronta; a legare a te uno dei famigerati destrieri del terrore.$B$BPer evocare la bestia dalla sua dimora serve un rituale che chiede grande potere e molte risorse, ma se vuoi dominare quella cavalcatura epica, parla con Mor'zul Bloodbringer: è accampato vicino all'Altare delle Tempeste, nelle Burning Steppes.$B$BVa', $N. Sarà una missione rischiosa, ma $Guno:una; $GStregone:Strega; della tua levatura non si tira indietro davanti al pericolo!",
  obj = "Parla con Mor'zul Bloodbringer in Burning Steppes.",
  reward = "Saluti, $N, e $Gbenvenuto:benvenuta;. Sei qui come me per studiare vicino all'Altare delle Tempeste, magari per sfruttarne l'energia per qualche scopo nascosto...$B$BOppure... è con me che vuoi parlare? Sì, credo di sì.$B$BVuoi dominare un destriero del terrore? Non è una cosa facile: ti costerà parecchio sangue, sudore... e oro, naturalmente. Ma un destriero del terrore di Xoroth è un premio per cui vale davvero la pena lottare, quindi se sei $Ginteressato:interessata;, resta ad ascoltare...",
}
T[7563] = {
  title = "Furia di Sangue",
  desc = "I destrieri del terrore vivono in un altro mondo, nelle infuocate Plains of Xoroth, e per legare a te una di quelle famose bestie devi invocare glifi potenti. Posso tracciarli io per te su una pergamena, ma prima mi servirà un inchiostro speciale.$B$BLontano da qui, a Winterspring, vive una razza di bestie-gufo. Un tempo erano creature pure, poi le emanazioni demoniache della Darkwhisper Gorge le hanno fatte impazzire, e adesso vagano fra le nevi in preda alla frenesia.$B$BÈ il loro sangue che mi serve per l'inchiostro della tua pergamena. Portamelo.",
  obj = "Porta 30 bottiglie di Raging Beast's Blood a Mor'zul Bloodbringer in Burning Steppes.",
  progress = "Le hai viste, $N, le bestie-gufo furenti? Quelle creature hanno una magia forte, e si concentra nel sangue che scorre nei loro corpi tormentati.",
  reward = "Ah, molto bene. Farò distillare questo sangue, e l'inchiostro che ne verrà fuori lo userò per la pergamena che ti ho promesso. E forse un pochino me lo terrò, perché ho sentito dire che a gustarlo si prova una certa euforia...",
}
T[7564] = {
  title = "Wildeyes",
  desc = "Gorzeeki, il mio servitore, è un alchimista piuttosto abile: può preparare lui l'inchiostro che mi servirà per la tua pergamena. Ho raccolto il sangue che mi hai procurato; portalo a Gorzeeki, così può mettersi al lavoro.",
  obj = "Porta la Case of Blood a Gorzeeki Wildeyes in Burning Steppes.",
  progress = "Hai qualcosa per me? Non sarà un ragno grosso e succoso? O magari una roach? Spero che sia ancora vivo... Adoro masticarli finché sono vivi...",
  reward = "Oh, è sangue. Allora sarà del padrone Mor'zul. Ne è così innamorato, adora vederlo versare. A me invece piace quando scorre nelle vene di un piccolo roditore: così resta caldo... finché non lo vuoi.$B$BQuesto è sangue potente. Mor'zul starà preparando un'altra pergamena per evocare un destriero del terrore! Che emozione!$B$BSe è così, e il rituale lo farai tu, allora... ti servirà molto più del sangue, $Gamico mio:amica mia;.",
}
T[7581] = {
  title = "I Vincoli della Prigione",
  desc = "I vincoli per la prigione del Doomguard devi procurarteli dai demoni minori.$B$BDovrebbe andare benissimo il sangue dei satiri Wildspawn che occupano Dire Maul: quando si sarà coagulato, terrà insieme le schegge di Hederine e alimenterà la prigione di cristallo.",
  obj = "Recati a Dire Maul, a Feralas, e recupera 15 Satyr Blood dai Wildspawn Satyr che abitano il Warpwood Quarter. Quando hai finito, torna da Daio in Tainted Scar.",
  progress = "Solo il sangue dei satiri Wildspawn andrà bene.",
  reward = "Ah, ottimo recupero. Questo sangue sopprimerà le difese magiche del Doomguard.",
}
T[7582] = {
  title = "L'Involucro della Prigione",
  desc = "I demoni Hederine che occupano le pendici del Mount Hyjal secernono potenti veleni vil: se li si lascia maturare, si induriscono fino a diventare un cristallo denso e antimagia. Questi cristalli sono ormai noti come Tears of the Hederine.$B$BLe pareti di una prigione fatta di questo materiale non le infrangerebbe nemmeno l'immenso potere di un Doomguard.$B$BVai alla Darkwhisper Gorge, a Winterspring, e recupera le Lacrime.",
  obj = "Recati alla Darkwhisper Gorge, a Winterspring, e recupera 5 Tears of the Hederine dai demoni Hederine che occupano la gola. Quando avrai completato questo compito, torna da Daio in Tainted Scar.",
  progress = "Gli Hederine non ti cederanno le loro preziose gemme senza lottare, $N.",
  reward = "Non mi resta che unire il sangue dei Wildspawn a questi cristalli, e la prigione sarà pronta all'uso.",
}
T[7583] = {
  title = "Soppressione",
  desc = "La prigione è pronta. Ora viene la parte più difficile del compito.$B$BCon questa prigione di cristallo devi trovare e catturare un Doomguard Commander in Tainted Scar.$B$BStai in guardia! Un Doomguard è un avversario astuto e letale: appena inizierai il rituale di imprigionamento cercherà di distruggerti, e si dimenerà con furia per sfuggire alla prigionia.$B$BSe la prenderà solo con te, $N, perciò ti raccomando di portare dei compagni capaci di tenerti in vita!",
  obj = "Avventurati in Tainted Scar e trova un Doomguard Commander.$B$BUsa la Glowing Crystal Prison sul Doomguard Commander. Preparati a un feroce assalto, perché il demone tenterà di sfuggire alla cattura.$B$BSe ci riuscirai, porta l'Imprisoned Doomguard a Daio in Tainted Scar.",
  progress = "Hmm? Allora?",
  reward = "Hai fatto quello che ti avevo chiesto: sei $Gpronto:pronta; a ricevere la conoscenza per evocare e controllare la bestia.",
}
T[7601] = {
  title = "Gli Ordini di Niby",
  desc = "Vuoi che ti insegni i segreti per evocare un infernal servant? Allora devi distruggere Kroshius, prendere dai suoi resti in fiamme il nucleo infernale e portarmelo. Non è facile come sembra, però: ormai Kroshius è quasi del tutto spento. Devi riaccenderne il cadavere e farlo risorgere dalle macerie, e per riuscirci dovrai raccogliere alcuni componenti da altre entità demoniache.$B$BTi metterà sulla buona strada Impsy, il mio imp.",
  obj = "Parla con Impsy in Felwood.",
  reward = "Oh, mamma, ci risiamo.",
}
T[7602] = {
  title = "Essenza Vil Perfetta",
  desc = "Se vuoi rianimare Kroshius, ti ci vuole del Fel fire. Il Fel fire posso crearlo io, ma ho bisogno di alcuni componenti.$B$BDevi procurarmi delle essenze Vil perfette da tre regioni diverse del mondo.$B$BIl primo tipo di essenza ce l'avranno i Legashi Satyrs di Azshara; il secondo i legionari di Jaedenar, a Jaedenar, e il terzo le felguard sentries delle Blasted Lands.$B$BTorna con un'essenza per tipo e io creerò il Fel fire con cui potrai rianimare Kroshius.",
  obj = "Impsy in Felwood ti ha chiesto di portargli tre Essenze Vil Perfette provenienti da tre luoghi diversi.$B$BI Legashi Satyrs di Azshara hanno l'Essenza Vil Perfetta della loro regione. I Jaedenar Legionnaires di Jaedenar hanno l'Essenza Vil Perfetta della loro regione. Le Felguard Sentries delle Blasted Lands hanno l'Essenza Vil Perfetta della loro regione.$B$BRecupera le Essenze Vil Perfette e torna da Impsy in Felwood.",
  progress = "Detto fra noi, Niby è tonto.",
  reward = "Dammi un minuto e combino le essenze per farne il Fel fire.",
}
T[7603] = {
  title = "Kroshius' Infernal Core",
  desc = "Kroshius giace accasciato a nordest, nella Shatter Scar Vale. Prendi questo Fel fire e usalo sui suoi resti: il fuoco dovrebbe rianimare l'infernal caduto.$B$BA quel punto, ne sono certo, ucciderà te e tutti gli amici che avrai con te — e fidati, ti conviene portarne qualcuno.$B$BSe per qualche miracolo riesci a uccidere Kroshius, prendigli il nucleo infernale e portalo a Niby.",
  obj = "Cerca i resti di Kroshius in Shatter Scar Vale, in Felwood. Quando li avrai trovati, usa il Fel Fire lì vicino e attendi il ritorno di Kroshius. Quando l'infernal si sarà risvegliato, uccidilo e prendi dal suo cadavere il Kroshius' Infernal Core.$B$BPorta il Kroshius' Infernal Core a Niby the Almighty in Felwood.",
  progress = "Ti sei $Gperso:persa;?",
  reward = "Un patto è un patto! Presto, prendi questo e scrivi. Non ho tempo! La mia evocazione più grande è ormai alle porte!",
}
T[7604] = {
  title = "Un Contratto Vincolante",
  desc = "Con la presente $Gil sottoscritto:la sottoscritta; dichiara che il lingotto di Sulfuron consegnato alla Thorium Brotherhood (TB Ltd.) è autentico e non un'imitazione. $GIl sottoscritto:La sottoscritta; riconosce inoltre che la TB Ltd non ha alcuna responsabilità né colpa per qualsiasi danno $Ggli:le; dovesse capitare nel tentativo di costruire, forgiare, trovare, creare, vendere o mangiare Sulfuras.$B$BFirmando il presente contratto, accetti tutti i termini qui elencati.$B$B_________________$B$BFirma",
  obj = "Consegna il Thorium Brotherhood Contract a Lokhtos Darkbargainer se vuoi ricevere gli schemi di Sulfuron.",
  progress = "Affare fatto?",
  reward = "Un piacere fare affari con te, $N!$B$BA nome della TB Ltd., ti auguro buona fortuna nella ricerca di Sulfuras!",
}
T[7621] = {
  title = "Un Avvertimento",
  reward = "$GSacerdote:Sacerdotessa;, stai per affrontare una serie di eventi difficili, che metteranno alla prova ogni tua capacità.$B$BTi consiglio di ascoltare la storia che ho da raccontarti.$B$BTi avverto, questo compito devi portarlo a termine da $Gsolo:sola;. Conviene che i tuoi alleati restino a distanza. Se qualcuno interverrà dall'esterno, la punizione sarà severissima.$B$BIl destino ha condotto qui te, e te soltanto. Combatti con onore. Incanala la Luce.",
}
T[7622] = {
  title = "L'Equilibrio tra Luce e Ombra",
  desc = "Devi fare ciò che io non ho potuto: salvare i contadini abbattuti mentre fuggivano da Stratholme.$B$BCammineranno verso la luce, e tu dovrai fare in modo che sopravvivano. Se ne cadranno troppi, la nostra esistenza maledetta andrà avanti — e avrai fallito.$B$BSaranno messi alla prova ogni abilità, ogni preghiera e ogni incantesimo che hai imparato. Che la Luce ti protegga, $N.",
  obj = "Salva 50 Contadini prima che ne vengano uccisi 15. Parla con Eris Havenfire se porterai a termine questo compito.$B$BPuoi guardare il Death Post per vedere quanti Contadini sono stati uccisi.",
  reward = "Hai una tenacia e un coraggio sbalorditivi, $Gsacerdote:sacerdotessa;. Ti sei $Gguadagnato:guadagnata; il diritto di custodire la Splinter of Nordrassil. Ti resta un solo compito: recuperare The Eye of Shadow. Setaccia il mondo.",
}
T[7623] = {
  title = "Lord Banehollow",
  desc = "Mor'zul dice che vuoi aprire un portale verso Xoroth. Per riuscirci ti servirà della polvere stellare Xorothian, e su Azeroth non è facile da trovare!$B$BUn essere che potrebbe averne un po' però c'è: Lord Banehollow, a Jaedenar, la sede dello Shadow Council! Parla con lui, e forse la polvere stellare te la cederà.$B$BMa se vai a Jaedenar dovrai avvolgerti nella forma di male propria dello Shadow Council, e per farlo ti serviranno alcune delle mie shadowy potions. Che ti costeranno...",
  obj = "Compra le Shadowy Potions da Gorzeeki nelle Burning Steppes.$B$BUsa le pozioni per attraversare Jaedenar e parla con Lord Banehollow.",
  reward = "La mia pazienza si misura in millenni, $C, ma non credere che per questo ti conceda più di un istante del mio tempo...",
}
T[7624] = {
  title = "Ulathek il Traditore",
  desc = "Vuoi entrare nelle mie grazie? Allora uccidi per me.$B$BIl mio servo Ulathek mi striscia davanti in modo patetico, e intanto trama con Lord Hel'nurath su Xoroth. Hel'nurath vuole usurpare il mio potere qui, e Ulathek gli fa da spia...$B$BDimostrami che servi me e non i miei rivali. Affronta Ulathek nei suoi alloggi, nello Shadow Hold a ovest: digli che conosco il suo segreto e guarda la paura che lo afferra. Poi portami the traitor's heart!",
  obj = "Affronta Ulathek, poi porta The Traitor's Heart a Lord Banehollow a Jaedenar.",
  progress = "Sento già sulle labbra il sapore del cuore di Ulathek. Com'è dolce la carne di un traditore...",
  reward = "Ah, splendido! Dopo una settimana a marcire, questo cuore sarà una prelibatezza succulenta! Forse manderò a prendere la testa di Ulathek, per tenermela davanti mentre mangio...$B$BMi hai reso un servigio, $C, e la mia pazienza con te è cresciuta. Di poco.",
}
T[7625] = {
  title = "Xorothian Stardust",
  desc = "Dunque vieni da me per la polvere stellare Xorothian? Vuoi aprire un portale verso Xoroth, il dominio del mio rivale Hel'nurath? O forse vuoi rubargli uno dei suoi preziosi destrieri del terrore?$B$BMolto bene. Il mio servo Ur'dan ha una scorta di polvere stellare Xorothian, e puoi averla da lui... se sei in grado di pagarne il prezzo.",
  obj = "Compra la Xorothian Stardust da Ur'dan. Portala a Gorzeeki Wildeyes nelle Burning Steppes.",
  progress = "Sei $Gstato:stata; a Jaedenar, $N? Lord Banehollow ti ha dato la polvere stellare?",
  reward = "Eccola! Non ci credo, ce l'hai fatta! Con quel Dreadlord devi aver concluso un grosso affare, o pagato una bella somma, o tutte e due!$B$BMor'zul avrà prestissimo il suo inchiostro e potrà finalmente creare la pergamena del glifo: così potrai aprire un portale verso Xoroth e farne uscire uno dei famosi destrieri del terrore!",
}
T[7626] = {
  title = "Campana di Dethmoora",
  desc = "Una Campana di Dethmoora prende il nome dal defunto stregone Dethmoora Darkeyes ed è uno dei tre strumenti che servono per creare un Cerchio dell'Evocazione Superiore. Se sono sintonizzati a dovere con la Ruota e la Candela, questi oggetti convogliano enormi riserve di potere arcano.$B$BIl mio servitore Gorzeeki può costruire una campana del genere, ma gli servirà una grossa scorta di elixirs of shadow power. Procurati gli elisir da un alchimista e portali a Gorzeeki.",
  obj = "Porta 10 Elixirs of Shadow Power a Gorzeeki Wildeyes in Burning Steppes.",
  progress = "Ce li hai quegli elisir, $N? Mor'zul mi ha detto che ti serve una Campana di Dethmoora, e per farne una ci vuole un sacco di potere dell'ombra!",
  reward = "Molto bene! Spero che trovare questi elisir non sia stato troppo difficile. Gli alchimisti, a volte, sanno essere così tirchi con le loro creazioni...$B$BPreparerò la campana e la terrò io finché non sarai $Gpronto:pronta; per il tuo rituale.",
}
T[7627] = {
  title = "Ruota della Marcia Nera",
  desc = "Una Ruota della Marcia Nera contiene e dirige le energie violente che servono al Cerchio dell'Evocazione Superiore. Per costruirne una, Gorzeeki avrà bisogno di large brilliant shards da un incantatore e di dark iron ore da un maestro minatore.$B$BRecupera tutto e portalo al mio servitore.",
  obj = "Porta 6 Large Brilliant Shards e 25 pezzi di Dark Iron Ore a Gorzeeki in Burning Steppes.",
  progress = "Fare una Ruota della Marcia Nera non è facile, e ci vogliono un sacco di materiali. Li hai già raccolti?",
  reward = "Eccoli qua! Ho sentito dire che il dark iron ore si trova solo nelle profondità di Blackrock, e sono sicuro che neanche trovare questi frammenti è stato facile. Voi stregoni, con la vostra dedizione, mi lasciate spesso a bocca aperta. Se invece metteste tutta quell'energia nell'arte di catturare insetti, oh... che banchetto vi godreste!$B$BScusa, mi sono perso in chiacchiere. Creerò la ruota e la terrò per te finché non sarai $Gpronto:pronta; per il tuo rituale.",
}
T[7628] = {
  title = "Candela del Giorno del Giudizio",
  desc = "Una Candela del Giorno del Giudizio accumula il fuoco e lo rivolge contro chi volesse disturbare il tuo rituale. Se la candela è accesa quando crei il Cerchio dell'Evocazione Superiore, le sue fiamme bruceranno tutti i demoni ribelli!$B$BContenere quel fuoco non è facile: ci vuole l'essenza racchiusa nelle scaglie di un drago nero. Procurati quelle scaglie da uno scuoiatore e portale a Gorzeeki Wildeyes.",
  obj = "Porta 35 Black Dragonscales a Gorzeeki Wildeyes in Burning Steppes.",
  progress = "Hai portato le scaglie di drago, $N? Finché non le ho, non voglio mettermi a fare la candela... o rischio di far saltare in aria tutto l'accampamento!",
  reward = "Ah, molto bene. Mi serviranno per contenere le fiamme della candela. Ora che ho le scaglie, la preparerò e la terrò io finché non sarai $Gpronto:pronta; a cominciare il tuo rituale per il Cerchio dell'Evocazione Superiore.",
}
T[7629] = {
  title = "Consegna dell'Imp",
  desc = "Alla pergamena di Mor'zul manca ancora un passaggio; mi serve della carta infusa di polvere stellare Xorothian. E... temo di non poterlo fare qui. Non ho l'attrezzatura!$B$BC'è però un laboratorio alchemico che ha tutto il necessario. Sta nella Scholomance, sull'isola di Caer Darrow, nelle Plaguelands.$B$BIo il viaggio non posso farlo, ma ecco — prendi questo vaso. Dentro c'è un imp piuttosto sveglio: fallo uscire al laboratorio e sarà lui a infondere la pergamena.",
  obj = "Porta l'Imp in a Jar al laboratorio alchemico della Scholomance. Una volta creata la pergamena, riporta il vaso a Gorzeeki Wildeyes.",
  progress = "Sei $Gstato:stata; nella Scholomance, $N? L'imp ha già infuso la pergamena con la polvere stellare?",
  reward = "Ah, bene. J'eevee ha creato la pergamena. Allora, com'era la Scholomance? Incantevole, vero? E quegli insetti che ci vivono... ho sentito dire che sono deliziosi!$B$BBen fatto, $N, e grazie di avermi riportato il vaso. Ce l'ho da tanto tempo... e non è in vendita!",
}
T[7630] = {
  title = "Arcanite",
  desc = "Ora che la Campana, la Ruota e la Candela sono fatte, dovrei preparare una black lodestone. Durante il rituale ti servirà per sostenere gli altri oggetti, nel caso cedessero.$B$BPer fare la magnetite mi serve un po' di arcanite. Ne hai? Se no, allora... dovrai procurartela da un alchimista.$B$BQuando l'avrai, torna da me e preparerò la black lodestone.",
  obj = "Porta 3 Arcanite Bars a Gorzeeki in Burning Steppes.",
  progress = "Hai l'arcanite, $N? Appena ce l'ho, posso prepararti la black lodestone.",
  reward = "L'hai trovata! Ben fatto! Adesso posso creare la magnetite. Quando finalmente sarai $Gpronto:pronta; per il rituale che crea il Cerchio dell'Evocazione Superiore, ti conviene averne una, così sarai $Gsicuro:sicura; che il rituale non vada in fumo!",
}
T[7631] = {
  title = "Maldestriero di Xoroth",
  desc = "I preparativi sono tutti fatti. Ora devi compiere il rituale per creare un Cerchio dell'Evocazione Superiore, e poi usare la pergamena intrisa di polvere di stelle Xorothian... per aprire un portale verso Xoroth.$B$BHo scritto su un rotolo le istruzioni per il rituale. Studialo con attenzione: se vuoi riuscirci, devi eseguire ogni passaggio alla lettera.$B$BChe la fortuna sia con te, $N. E che le anime dei tuoi nemici trovino in fretta la strada per la tua sacca dei frammenti.",
  obj = "Leggi le Mor'zul's Instructions. Evoca uno Xorothian Dreadsteed, sconfiggilo, poi lega a te il suo spirito.",
  reward = "Lo spirito dello Xorothian Dreadsteed è vinto. La rabbia gli pulsa ancora nei fianchi spettrali, ma sai che l'anima della bestia è tua...$B$BTi sussurra nella mente una magia oscura e ti infonde la conoscenza per evocare un maldestriero.",
}
T[7632] = {
  title = "L'Antica Foglia",
  desc = "L'epidermide della foglia brilla di un verde acceso. La superficie, estremamente rugosa, mostra numerose venature e grinze.$B$BSe dovessi tirare a indovinare, diresti che la foglia viene da qualcosa di antico e potente.$B$BForse dovresti cercare chi la possedeva in origine?",
  obj = "Trova il proprietario dell'Ancient Petrified Leaf. Buona fortuna, $N; il mondo è grande.",
  progress = "<Vartrus geme.>",
  reward = "Certo che le riconosco, le mie foglie. Guarda qui! È in perfette condizioni.$B$BChe gentile da parte tua riportarla, $C.$B$BForse tu potresti esserci utile, e noi a te.",
}
T[7633] = {
  title = "Una Presentazione",
  reward = "Abbiamo notato la tua diligenza e la tua integrità, $C.$B$BSiamo gli Antichi: Protettori di questa foresta, un tempo grandiosa. Le nostre forme fisiche furono distrutte 10.000 anni fa, quando Archimonde e la Burning Legion marciarono su Hyjal, ma i nostri spiriti sono rimasti intatti.$B$BAbbiamo dei compiti da offrirti. Se li porterai a termine, ti sveleranno i segreti degli Antichi.$B$BSappi che, se li completerai, ti basterà tornare a questa roccia e risponderemo alla chiamata.",
}
T[7634] = {
  title = "Ancient Sinew Wrapped Lamina",
  desc = "Salve, $C. Sono Hastat, Ancient of Lore, e custodisco una conoscenza perduta da ere.$B$BCon la giusta legatura, una delle mie foglie può diventare una faretra come non se ne vedono da 10.000 anni, e insieme a un arco degli Antichi potrebbe concedere poteri inimmaginabili.$B$BTorna qui con il tendine di un drago blu adulto e questa faretra sarà tua.",
  obj = "Hastat the Ancient ti ha chiesto di portargli un Mature Blue Dragon Sinew. Se trovi questo tendine, riportalo a Hastat a Felwood.",
  progress = "$GBentornato:Bentornata;, giovane $C.",
  reward = "Che le mie foglie proteggano le tue frecce da ogni male. Che le tue frecce colpiscano nel segno. Che i nemici del nostro mondo siano abbattuti.",
}
T[7635] = {
  title = "Una Corda Adatta",
  desc = "Vartrus può offrirti l'asta per un arco degli Antichi, ma la corda che serve a completarlo posso incantarla solo io.$B$BÈ un compito semplice, $Gmingherlino:mingherlina;: uccidi un drago nero adulto e staccagli il tendine dalle ossa. Riportamelo e lo incanterò fino a farne una corda d'arco quasi indistruttibile.",
  obj = "Stoma the Ancient ti ha chiesto di portargli un Mature Black Dragon Sinew. Se trovi questo tendine, riportalo a Stoma a Felwood.",
  progress = "Sono certo che trovare e uccidere un drago nero non ti darà molte difficoltà, $N. Non farmi perdere tempo in chiacchiere inutili.",
  reward = "Era davvero un drago immondo, questo. Il tendine puzza di malvagità.$B$BDammi un momento: devo purificare questa carne dalla sozzura e applicarle gli incantesimi adatti.",
}
T[7636] = {
  title = "Il Bastone degli Antichi",
  desc = "Gli agenti della Burning Legion agiscono ancora nel nostro mondo, $C, e corrompono tutto ciò che toccano. In loro presenza la natura appassisce e piange.$B$BDevi rintracciare questi corruttori demoniaci e distruggerli, $N. Ma attenzione: devi affrontarli da $Gsolo:sola;, o fuggiranno. Finché sarai $Gsolo:sola;, cercheranno di ucciderti: colpiscili e trasforma la loro arroganza in sofferenza.$B$BTi concedo un pezzo della mia corteccia: le iscrizioni ti guideranno verso i bersagli. Riportami le loro teste.",
  obj = "Devi trovare e distruggere questi quattro corruttori demoniaci:$B$BSimone the Seductress.$B$BKlinfran the Crazed.$B$BSolenor the Slayer.$B$BArtorius the Doombringer.$B$BDistruggi queste creature e torna da Vartrus the Ancient a Felwood con le loro teste.$B$BConsulta la Petrified Bark nel tuo inventario per avere indizi su dove si trovano.$B$BDEVI completare questo compito da $Gsolo:sola;.",
  progress = "Non lasciarti ingannare dai loro travestimenti!",
  reward = "Ci hai servito bene, $N! Prendi questo bastone e uniscilo alla corda d'arco che sa creare Stoma: insieme formano un'arma davvero formidabile.",
}
T[7637] = {
  title = "Accento sul Sacrificio",
  desc = "Per prepararti a questo compito dovrai prima dimostrare il giusto sacrificio e il giusto giudizio... con l'accento sul sacrificio.$B$BPer riuscirci ti serve l'exorcism censer di High Priest Rohan. Lo userai per ragioni buone e giuste, è vero, ma in cambio gli spetta comunque un giusto compenso.$B$BRaggiungi Ironforge e parla con il Gran Sacerdote: se porterai con te molto denaro per ripagarlo dell'incensiere che perde, dimostrerai il giusto sacrificio.$B$BVa' ora, $N: il tempo stringe.",
  obj = "Viaggia fino a Ironforge e ottieni il Rohan's Exorcism Censer del Gran Sacerdote. Per averlo dovrai fare una donazione di 150 monete d'oro.",
  progress = "Salute, nobile $GPaladino:Paladina;! Il mio fidato incensiere è pronto: l'ho riempito con l'incenso più fresco e l'ho benedetto tre volte, perché tu possa usarlo. Con la tua donazione noi di Ironforge potremo farci un incensiere nuovo, e anche rimpinguare le scarse riserve di cibo per i nostri bisognosi.",
  reward = "Benedizioni su di te, $Gamico:amica; $C! Hai donato ben più del necessario. Con il tuo sacrificio non solo recupereremo ciò che abbiamo perduto, ma potremo anche soccorrere i più bisognosi qui a Ironforge.$B$BE ora lascia che mi assicuri di aver preparato a dovere questo incensiere, così ti servirà bene quando ne avrai bisogno...",
}
T[7638] = {
  title = "Lord Grayson Shadowbreaker",
  desc = "$N, è giunto il momento di scoprire cosa ti servirà per avere una cosa che di certo aspetti da tempo... il tuo destriero.$B$BParla con Lord Grayson Shadowbreaker, qui nello Stormwind's Cathedral District. Sarà lui a guidarti non solo nei segreti della cavalcatura più fidata di un Paladino, ma anche nelle prove che ti aspettano per averne una tutta tua.$B$BBuona fortuna per questa impresa. Per la Luce, $Gnobile fratello:nobile sorella;!",
  obj = "Parla con Lord Grayson Shadowbreaker in Stormwind's Cathedral District.",
  reward = "Sono lieto di vederti, $N. So che aspettavi notizie su come ottenere il tuo destriero, e ora il momento è giunto.$B$BDi certo sarai $Gmesso:messa; alla prova in molti modi, ma soprattutto nella volontà di superare i tanti ostacoli che ti troverai davanti. Non è un esercizio per imparare — la tua statura va oltre le semplici prove didattiche. Devi salvare il tuo futuro compagno dalle grinfie del male che hai combattuto per tutta la vita.$B$BPresta attenzione, il tuo momento è giunto!",
}
T[7639] = {
  title = "Per Dimostrare il Giusto Giudizio",
  desc = "Prendi l'incensiere, hai la mia benedizione. L'ho usato io stesso in parecchi esorcismi, e negli ardui compiti che ti aspettano dovrebbe tornarti utile.$B$BOra torna da Lord Grayson Shadowbreaker a Stormwind, $N: è con lui che prosegue la tua missione.",
  obj = "Riporta l'Exorcism Censer a Lord Grayson Shadowbreaker in Cathedral District of Stormwind.",
  progress = "$GBentornato:Bentornata;, $N. Hai ottenuto l'exorcism censer?",
  reward = "Sì, questo andrà bene. Lungo questo cammino ti sarà chiesto più di una volta di compiere sacrifici, e sono lieto di vedere che sei $Gdisposto:disposta; a farlo. Per adempiere ai doveri di un Paladino il sacrificio è essenziale... ma non serve che ti faccia la predica.$B$BOra, $N, le tue azioni dovranno dimostrare il giusto giudizio. E lo strumento con cui porterai quel giudizio agli spiriti tormentati delle terre che abbiamo perduto sarà proprio questo incensiere.",
}
T[7640] = {
  title = "Esorcizzare Terrordale",
  desc = "Nell'incensiere ho messo un pizzico di terra raccolta dal suolo contaminato di Terrordale, nelle Eastern Plaguelands. Ora ti servirà per trovare laggiù i luoghi dove gli spiriti danno segni di turbamento e inquietudine. Cerca le aure verdi che impregnano il terreno mentre il mondo fisico cede sotto il tormento del regno degli spiriti, e con l'incensiere scaccia gli spiriti malvagi.$B$BQuando avrai giudicato a sufficienza gli spiriti di quel luogo, sarai $Gpronto:pronta; a proseguire.",
  obj = "Usa l'Exorcism Censer per scacciare gli spiriti che tormentano Terrordale. Dopo aver ucciso 25 Terrordale Spirits, torna da Lord Grayson Shadowbreaker in Cathedral District of Stormwind.",
  progress = "Che piacere rivederti, $N. Hai portato a termine il lavoro a Terrordale?",
  reward = "Ben fatto, $N. Portare il giudizio della Luce su coloro che dimorano nell'oscurità è un compito da affrontare con vigore e zelo, ed è proprio quello che hai fatto, con il sacrificio a Ironforge e con i giudizi sugli spiriti di Terrordale.$B$BNei prossimi passi ti verranno chiesti di nuovo sacrificio e giudizio, perché cercherai di riscattare lo spirito di un destriero caduto, che ora serve un Cavaliere della Morte noto come Darkreaver.",
}
T[7641] = {
  title = "Il Lavoro di Grimand Elmore",
  desc = "Senza una bardatura adatta, il destriero di un paladino non è altro che una bestia da soma. E per il tuo non basta che la bardatura sia fatta con i materiali migliori che si trovano: viste le circostanze, deve anche essere abbastanza in sintonia con il regno degli spiriti.$B$BPer prima cosa, $N — facciamo fare la bardatura. Uno dei migliori artigiani di oggi, Grimand Elmore, si trova nello Stormwind's Dwarven District. Il suo lavoro non costerà poco, ma è la qualità quella che cerchiamo. Va' a parlargli.",
  obj = "Parla con Grimand Elmore in Stormwind's Dwarven District.",
  reward = "Salve — Lord Shadowbreaker mi aveva avvisato per tempo che saresti $Gpassato:passata; da queste parti a trovarmi. Sono disposto a farti la bardatura che ti serve, ma mettiamolo in chiaro prima di tutto: non costerà poco e non sarà facile.$B$BTi dico solo questo, e Grayson mi darà ragione... in tutta Azeroth non troverai una bardatura migliore di quelle che si fanno proprio qui.",
}
T[7642] = {
  title = "Raccolta di Materiali",
  desc = "Per la bardatura ti serviranno quattro cose: runecloth per la fodera, arcanite bars per le piastre, Arthas' Tears per la sintonia spirituale e acqua santa di Stratholme per infonderle lo spirito. Anzi, le cose sono cinque... c'è anche l'oro per il mio compenso, che comprende tutto il lavoro più una sella e delle staffe fatte a mano.$B$BQuando avrai tutto, potrò finire la bardatura. Intanto, mentre raccogli i materiali, posso cominciare a occuparmi di qualche cosa.",
  obj = "Porta 40 pezzi di Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 fiale di Stratholme Holy Water e 150 monete d'oro a Grimand Elmore in Dwarven District of Stormwind.",
  progress = "Ah, $C. Senza le cose che ti ho detto, la bardatura non potrò finirla. Hai raccolto tutto?",
  reward = "Questo... be', è proprio quello che mi serviva. Sei davvero $Gun:una; $C $Gpieno:piena; di risorse, eh?$B$BBene, allora finiamo questa bardatura!",
}
T[7643] = {
  title = "Ancient Equine Spirit",
  desc = "La tua bardatura ha bisogno di una benedizione speciale, e deve dargliela uno spirito adatto. A Dire Maul ce n'è uno: è l'Ancient Equine Spirit, che adesso è prigioniero di un treant corrotto, Tendris Warpwood. Giudica questa bestia immonda, $N.$B$BSappi questo — da sola la libertà non basta. Prima che ti benedica, lo spirito va calmato, e per farlo serve una biada speciale. Passa prima da Southshore e parlane con Merideth Carlson... e preparati ad altri sacrifici.",
  obj = "Procurati la biada speciale che serve a nutrire uno spirito equino. A quanto pare, la fonte di questo cibo è Merideth Carlson, a Southshore.$B$BVai nel dungeon di Dire Maul, a Feralas, e uccidi Tendris Warpwood. Così libererai l'Ancient Equine Spirit. Dagli da mangiare la biada speciale per calmarlo. Infine, dagli l'Arcanite Barding perché possa benedirla.",
  progress = "L'Ancient Equine Spirit ti guarda e aspetta, come se volesse qualcosa da te.",
  reward = "L'Ancient Equine Spirit accetta la Manna-Enriched Horse Feed che gli offri e, mentre si serve dell'avena e dei cereali speciali, strofina il muso sul contenitore. Mangiato un po', guarda la bardatura che porti con te e si mette in posizione, come se volesse che gliela mettessi sulla groppa...",
}
T[7644] = {
  title = "Blessed Arcanite Barding",
  desc = "Appena la bardatura si posa sulla groppa dell'Ancient Equine Spirit, manda un bagliore lievissimo. Per un breve istante l'aria si carica di potere, poi la bardatura sparisce dalla groppa del cavallo e te la ritrovi al sicuro nello zaino.$B$BA quanto pare è stata benedetta. Come ti ha detto Lord Shadowbreaker, adesso dovresti riportargliela a Stormwind.",
  obj = "Torna con la Blessed Arcanite Barding da Lord Grayson Shadowbreaker, in Cathedral District of Stormwind.",
  progress = "$N, sei $Gtornato:tornata;! Sei $Griuscito:riuscita; a sbrigartela con Merideth Carlson e con Tendris Warpwood? A dire il vero, a volte non saprei dire chi dei due sia la minaccia più grande...",
  reward = "Hai fatto molta strada, $Gamico mio:amica mia;. Ora la tua bardatura è pronta come si deve per l'ultimo compito che ci aspetta.$B$BLa metterai al tuo destriero quando l'avrai redento. Ma prima dovrai affrontare una lotta immane. Il tuo momento si avvicina — urrà!$B$BCi resta un ultimo oggetto da creare prima di cominciare, $N. Spero che da quando ti sei $Gfatto:fatta; fare la bardatura non ti sia passata l'intraprendenza...",
}
T[7645] = {
  title = "Manna-Enriched Horse Feed",
  desc = "Quelli della Silver Hand mi credevano PAZZA quando gli ho detto che sapevo preparare una biada speciale per nutrire i cavalli spirituali. Mi credevano pazza TUTTI! Bene, adesso è arrivata la resa dei conti!$B$BTi preparerò quello che ti serve, $GPALADINO:PALADINA;... $Gcosiddetto:cosiddetta; $GCAMPIONE:CAMPIONESSA;... ma ti costerà. Per questa miscela mi servono dei biscotti speciali — gli Enriched Manna Biscuits, venduti solo dall'Argent Dawn. E poi esigo, sì, ESIGO dell'oro per risarcirmi delle sofferenze che ho patito!$B$BFammi vedere il sacrificio di cui ti vanti tanto, $GPALADINO:PALADINA;.",
  obj = "Recupera 20 Enriched Manna Biscuits — l'ingrediente chiave per preparare la Manna-Enriched Horse Feed — per Merideth Carlson a Southshore, in Hillsbrad Foothills. The Argent Dawn è nota come l'unica fornitrice dei biscotti.$B$BDevi anche darle 50 monete d'oro per placare la sua suscettibilità ferita.",
  progress = "Sì, adesso ti ho dimostrato che avevi torto, vero? Ho dimostrato a tutti che si sbagliavano! AVEVO RAGIONE FIN DALL'INIZIO!!!",
  reward = "SÌ, E ORA CHI — aspetta — mi dai anche l'oro? Non sei $Gstato:stata; tu a darmi della pazza (a dire il vero mi hanno dato della svitata fuori di testa)... eppure sei $Gdisposto:disposta; a fare un sacrificio anche per torti che non hai commesso?$B$BIo... ti ho giudicato male, $N. Se ti servisse altra biada, vieni da me: te la darò gratis. Grazie... nobile $C.$B$BPerò i soldi me li tengo — non sono così svitata da rinunciare a una fortuna.",
}
T[7646] = {
  title = "Il Divination Scryer",
  desc = "Ora dobbiamo assemblare un Divination Scryer — sarà lui a dare inizio alla prova che ti permetterà di redimere il destriero caduto. In realtà il tuo veggente è quasi pronto: il catalizzatore è l'exorcism censer usato a Terrordale, e un involucro adatto per il congegno lo realizzerò io.$B$BMancano però gli ultimi componenti: due diamanti. Devono essere opposti nello splendore quanto lo sono nello scopo — un Azerotiano e un Nero Intatto. Saranno questi due il faro con cui il veggente squarcerà le ombre!",
  obj = "Porta un Azerothian Diamond e un Pristine Black Diamond a Lord Grayson Shadowbreaker, in Cathedral District of Stormwind.",
  progress = "Hai fatto davvero tanta strada, $N. Questo tuo ultimo sacrificio di beni terreni darà origine a una delle tue imprese più grandi. Lo sento in ogni fibra del mio essere!",
  reward = "Sono begli esemplari, $N — ora gli ultimi pezzi sono al loro posto. Finalmente è giunto il tuo momento!$B$BNelle profondità del Great Ossuary di Scholomance giacciono i resti scheletrici di molti esseri, e fra loro c'è un destriero un tempo nobile. Ora la sua anima svuotata fa da cavalcatura a Death Knight Darkreaver. È lui che affronterai, ed è quella cavalcatura che giudicherai. Solo tu, $N, puoi redimerne l'anima e salvarla dal tormento della schiavitù.",
}
T[7647] = {
  title = "Giudizio e Redenzione",
  desc = "Prendi questa bisaccia — dentro trovi gli oggetti che ti serviranno per il compito.$B$BNel cuore del sotterraneo del Great Ossuary usa il divination scryer per far apparire gli spiriti maledetti che dovrai giudicare. Durante la prova dosa con saggezza i tuoi giudizi — si riveleranno più potenti di quanto immagini. Dopo gli spiriti comparirà il cavaliere della morte; sconfiggilo e recupera l'anima perduta del destriero. Solo allora, $N, potrai redimerlo e mettere la bardatura alla tua nuova cavalcatura!$B$BBuona fortuna!",
  obj = "Usa il Divination Scryer nel cuore del sotterraneo di Great Ossuary, a Scholomance. Così farai apparire gli spiriti che devi giudicare. Sconfiggendo questi spiriti evocherai Death Knight Darkreaver. Abbattilo e recupera l'anima perduta del destriero caduto.$B$BDai la Charger's Redeemed Soul e la Bardatura Incantata Benedetta a Darkreaver's Fallen Charger.",
  progress = "Lo spirito del destriero caduto ti guarda con aria afflitta. Ha occhi tristi, quasi vuoti, e ti fissa come se avesse perso ogni speranza.",
  reward = "Un barlume di vita — che da tempo mancava alla povera bestia — le brilla negli occhi mentre le restituisci l'anima giudicata. Dopo aver giudicato redento il destriero, gli metti la bardatura sulla groppa e senti un sacro impeto di potere scorrerti intorno. Il destriero ti strofina il muso sulla mano mentre si libera dei pesi del passato. Ora senti che potrai chiamarlo a farti da cavalcatura ogni volta che ne avrai bisogno.$B$BHai ottenuto il tuo destriero epico, $C! Congratulazioni!",
}
T[7648] = {
  title = "Il Miglior Lavoro di Grimand",
  desc = "<Grimand si asciuga il sudore dalla fronte, raggiante d'orgoglio.>$B$BEcco qua, $Gamico mio:amica mia;. Questo è tra i lavori migliori che abbia mai fatto — buono quanto la bardatura che ho fatto con le mie mani per Lord Shadowbreaker, quando è andato a prendersi il suo destriero. Grazie di esserti $Gaffidato:affidata; a me per avere il meglio.$B$BDi sicuro anche Grayson vorrà vedere la bardatura con i suoi occhi. Portagliela, e ringrazialo da parte mia per la sua onestà negli affari.",
  obj = "Porta l'Arcanite Barding a Lord Grayson Shadowbreaker a Stormwind's Cathedral District perché la esamini.",
  progress = "Procedi bene, $N. Quando avrai realizzato la bardatura, sarai sulla buona strada per il compito successivo.",
  reward = "È davvero un lavoro notevole. A quanto pare, con gli anni, Grimand continua ad affinare la sua maestria. E non è cosa da poco, visto che già ai vecchi tempi, quando ha fatto la mia bardatura, il suo lavoro era tra i migliori che si potessero trovare.$B$BQuesta bardatura andrebbe benissimo per qualsiasi cavalcatura normale, ma qui non abbiamo a che fare con una bestia qualunque. Perché sia degna di posarsi sul destriero di $Gun:una; $C, dovrai farla benedire da una fonte adeguata. Fino ad allora la terrò io per te.",
}
