T[7652] = {
  title = "Un Affare in Offerta Speciale",
  reward = "Allora, $Gsignore:signora;, ho un affare d'oro per te.$B$BHo qui un po' di queste ricette per armature a piastre Imperiali di cui mi voglio sbarazzare, e cerco qualcuno disposto ad accollarsene il peso. In cambio ti chiedo solo dei thorium bars. Ti va?",
}
