T[7664] = {
  title = "Sostituzione di Ivory Raptor",
  reward = "Tu porti a me tuo vecchio raptor, io do a te uno nuovo con artigli appena affilati! Il nuovo raptor sarà veloce proprio come quello di prima, ma con un aspetto diverso. Puoi dare un'occhiata ai raptors veloci qui intorno per vedere fra quali dovrai scegliere.",
  en_title = "Ivory Raptor Replacement",
}
T[7665] = {
  title = "Sostituzione del Raptor Rosso",
  reward = "Tu porti a me tuo vecchio raptor, io do a te uno nuovo con artigli appena affilati! Il nuovo raptor sarà veloce proprio come quello di prima, ma con un aspetto diverso. Puoi dare un'occhiata ai raptors veloci qui intorno per vedere fra quali dovrai scegliere.",
  en_title = "Red Raptor Replacement",
}
T[7666] = {
  title = "Di Nuovo nel Great Ossuary",
  reward = "Torni nella Scholomance, $N? Hai già pagato così caro per usare il Divination Scryer — forse vorresti portarne con te un altro, per affrontare di nuovo i pericoli del Great Ossuary.$B$BMa certo, prendilo pure. Te lo sei guadagnato, non c'è dubbio.",
}
T[7667] = {
  title = "Aiuto Materiale",
  desc = "$N, ho una faccenda urgente e spero che tu possa aiutarmi... con aiuto materiale, ma anche spirituale. Lascia che ti spieghi.$B$BNel profondo della Scholomance, in Lordaeron, c'è una sala chiamata Great Ossuary, e io devo completare un congegno capace di squarciare le ombre di quella stanza orribile. Per finire il lavoro che ho cominciato mi servono due diamanti: un Azerotiano e un Nero Intatto. So bene che non sono oggetti da poco — ma non ho i mezzi per procurarmeli.$B$BPotresti portarmene uno di ciascun tipo?",
  obj = "Se vuoi aiutare Sagorne Crestrider in Orgrimmar's Valley of Wisdom, portagli un Azerothian Diamond e un Pristine Black Diamond.",
  progress = "Chiedere un aiuto materiale mi mette a disagio, ma il divination scryer — il congegno che spero di finire — ha bisogno di un diamante per tipo. Se non potessi aiutarmi, lo capirei, naturalmente.",
  reward = "Non c'è generosità pari alla tua, $N. Grazie per la gentilezza.$B$BOra potrò finire il divination scryer, e per costruirne altri non dovrei più aver bisogno di diamanti... forse vorresti aiutarmi a usarlo? Serve a un compito importantissimo, te lo assicuro... un compito che, se venisse trascurato, potrebbe portare il regno degli spiriti a un disastro totale!",
}
T[7668] = {
  title = "La Minaccia di Darkreaver",
  desc = "Death Knight Darkreaver domina il Great Ossuary nella Scholomance e minaccia di piegare al suo volere il regno degli spiriti: va fermato! Ed è qui che entra in gioco il veggente che hai aiutato a creare.$B$BUsa il divination scryer nel cuore del seminterrato del Great Ossuary e richiamerai gli spiriti al servizio di Darkreaver. Quando li avrai sconfitti, apparirà il cavaliere della morte in persona. $N, portami la sua testa! Solo con la sua fine si potrà rimediare al danno fatto al regno degli spiriti!",
  obj = "Usa il Divination Scryer nel cuore del seminterrato del Great Ossuary in Scholomance. Così facendo compariranno degli spiriti che dovrai combattere. Sconfitti questi spiriti, comparirà Death Knight Darkreaver; sconfiggilo.$B$BPorta la Darkreaver's Head a Sagorne Creststrider in Valley of Wisdom, Orgrimmar.",
  progress = "Il tempo stringe, $N — sei $Griuscito:riuscita; a fermare la minaccia di Death Knight Darkreaver?",
  reward = "Questa sì che è una vittoria da assaporare, $N! Con la fine di Darkreaver dovrebbero ristabilirsi i fragili vincoli che tengono ancorato il regno degli spiriti.$B$BHai fatto molto più di quanto ti si chiedeva, anche quando di ricompense o compensi non sapevi nulla. Sei davvero $Gun:una; $C di valore, $Gamico mio:amica mia;.$B$BSo che aver agito per preservare il regno degli spiriti dovrebbe bastare come ringraziamento, ma ti prego — accetta questo semplice dono in segno di gratitudine.",
}
T[7669] = {
  title = "Di Nuovo nel Great Ossuary",
  reward = "Torni nella Scholomance, $N? Hai già pagato a così caro prezzo l'uso del Divination Scryer — forse vorresti portarne con te un altro, per affrontare ancora una volta i pericoli del Great Ossuary.$B$BPrendilo pure. Te lo sei meritato, non c'è dubbio.",
}
T[7670] = {
  title = "Lord Grayson Shadowbreaker",
  desc = "$N, è giunto il momento che tu sappia cosa ci vuole per ottenere ciò che senza dubbio aspetti da tempo... il tuo destriero.$B$BParla con Lord Grayson Shadowbreaker nello Stormwind's Cathedral District. Ti svelerà i segreti della cavalcatura più fidata di un Paladino e ti guiderà nei compiti che ti attendono per averne una tua.$B$BTi auguro il meglio per questa prova. Per la Luce, $Gnobile fratello:nobile sorella;!",
  obj = "Parla con Lord Grayson Shadowbreaker in Stormwind's Cathedral District.",
  reward = "Sono lieto di vederti, $N. So che aspettavi di sapere come ottenere il tuo destriero, e ora ci siamo.$B$BDi certo sarai $Gmesso:messa; alla prova in molti modi, ma soprattutto nella volontà di superare i tanti ostacoli che ti si pareranno davanti. Non saranno esercizi per imparare — la tua statura va oltre le semplici prove da allievo. Dovrai strappare il tuo futuro compagno alle grinfie del male che hai combattuto per tutta la vita.$B$BPresta attenzione, il tuo momento è arrivato!",
}
T[7671] = {
  title = "Sostituzione del Frostsaber",
  reward = "Se mi porti il tuo vecchio frostsaber, te lo scambierò con uno del nuovo branco.   Il felino rapido che riceverai sarà veloce quanto il precedente, ma avrà un aspetto diverso.   Puoi dare un'occhiata ai felini rapidi che abbiamo già qui nel recinto per vedere come sarà.",
}
