T[7807] = {
  title = "Una Donazione di Lana",
  progress = "In questo momento raccogliamo donazioni di wool cloth. Se ci doni sessanta pezzi di wool cloth, gli Gnomeregan Exiles riconosceranno appieno la tua generosità. Con le scorte di lana che abbiamo, da te ci basterebbero sessanta pezzi in tutto. Per il resto della raccolta dovremmo riuscire a farci aiutare da altri nel reame.$B$BSe hai con te i sessanta pezzi di wool cloth e sei $Gpronto:pronta; a donarli, te li prendo subito.",
  reward = "Magnifico! Ti siamo grati per la generosa donazione, $N!",
  en_title = "A Donation of Wool",
}
T[7808] = {
  title = "Una Donazione di Seta",
  progress = "Le nostre scorte di seta sono ai minimi storici, come quelle di quasi tutti gli altri tessuti. Con le riserve che abbiamo, da te ci basterebbero sessanta pezzi di seta in tutto. Con il sostegno degli altri dovremmo farcela a raggiungere l'obiettivo.$B$BE aggiungo, se permetti: un dono generoso come la seta farebbe di certo crescere la tua reputazione nella comunità! Se hai con te i sessanta pezzi di silk cloth e sei $Gpronto:pronta; a donarli, te li prendo subito.",
  reward = "Magnifico! Ti siamo grati per la generosa donazione, $N!",
  en_title = "A Donation of Silk",
}
T[7809] = {
  title = "Una Donazione di Mageweave",
  progress = "Il mageweave sta finendo, e ci farebbe comodo una mano per rifornire le scorte! Con tutta la comunità che contribuisce, da te ci basterebbe una donazione di 60 pezzi di mageweave cloth per arrivare all'obiettivo. Una generosità del genere non sfuggirebbe agli Gnomi di Gnomeregan, te lo assicuro!$B$BSe hai con te i sessanta pezzi di mageweave cloth e sei $Gpronto:pronta; a donarli, te li prendo subito.",
  reward = "Magnifico! Ti siamo grati per la generosa donazione, $N!",
}
T[7810] = {
  title = "Arena Master",
  desc = "Per diventare maestro dell'arena ci vuole per forza qualcosa di più! Magari il Pirata che organizza l'evento a Gurubashi lo saprà!",
  obj = "Parla con Short John Mithril nella Stranglethorn Arena.",
