T[7813] = {
  title = "Una Donazione di Lana",
  progress = "In questo periodo accettiamo donazioni di wool cloth. Se doni sessanta pezzi di wool cloth, Undercity riconoscerà appieno la tua generosità. Con la lana che abbiamo già in magazzino, da te ci basterebbero sessanta pezzi in tutto: il resto dovremmo riuscire a farcelo dare da altri, nel reame, per portare avanti la raccolta.$B$BSe hai con te i sessanta pezzi di wool cloth e sei $Gpronto:pronta; a donarli, li prendo subito.",
  reward = "Splendido! Ti ringraziamo della generosa donazione, $N!",
  en_title = "A Donation of Wool",
}
T[7814] = {
  title = "Una Donazione di Seta",
  progress = "Le nostre scorte di seta, come quelle di quasi tutte le altre stoffe, non sono mai state così basse. Viste le riserve che abbiamo, da te ci basterebbero sessanta pezzi di seta in tutto: con l'aiuto degli altri dovremmo arrivare all'obiettivo.$B$BE aggiungo che un dono generoso come la seta farebbe di certo crescere la tua reputazione qui nella comunità! Se hai con te i sessanta pezzi di silk cloth e sei $Gpronto:pronta; a donarli, li prendo subito.",
  reward = "Splendido! Ti ringraziamo della generosa donazione, $N!",
  en_title = "A Donation of Silk",
}
T[7815] = {
  title = "Snapjaws, Mon!",
  desc = "Non farti ingannare dai loro occhioni, mon! Quei saltwater snapjaws sono una minaccia. Non riesco a pescare cinque minuti che subito uno di quei giganteschi aspirapesci mi spezza la lenza e mi ruba l'esca.$B$BFai un favore a me e alla gente di Revantusk Village e ammazzali, mon.$B$BAmmazzali tutti quanti!",
  obj = "Katoom the Angler a Revantusk Village in Hinterlands vuole che tu uccida 15 tartarughe Saltwater Snapjaw. Torna da lui quando avrai completato questo compito.",
  progress = "Come va la caccia?",
  reward = "Oh, mon! Non so proprio come ringraziarti! Spero che questa fishing pole basti a ripagarti del lavoro.",
}
T[7816] = {
  title = "Gammerita, Mon!",
  desc = "Yo! Là fuori c'è una tartaruga che non è come le altre. È la Gammerita, la capa dei saltwater snapjaws — un rettile lurido e ladro fino al midollo.$B$BMon, mi ha rubato l'esca migliore. Me l'ha strappata via dalla lenza! E da allora i pesci non abboccano più come prima.$B$BTrova Gammerita e tirale fuori dallo stomaco la mia esca.",
  obj = "Katoom the Angler a Revantusk Village in Hinterlands vuole che tu uccida Gammerita e recuperi la Katoom's Best Lure dal suo cadavere.$B$BKatoom ha detto che Gammerita se ne sta sulla costa insieme alle altre tartarughe.",
  progress = "Ce l'hai già?",
  reward = "MON! È fantastico! Con la mia esca migliore e meno snapjaw in giro, i pesci verranno a frotte.",
}
