T[7828] = {
  title = "Inseguire gli Inseguitori",
  desc = "Nelle lande selvagge e ostili dell'Hinterlands abbiamo perso molti troll coraggiosi, $R. Fra i pericoli più grandi per i nostri cacciatori ci sono i lupi Silvermane: aspettano in agguato, nascosti fra i cespugli e nel terreno, e colpiscono appena si presenta l'occasione.$B$BTanta ferocia non resterà impunita!$B$BDevi metterti a pensare come i Silvermane. Insegui gli inseguitori! Uccidili tutti!",
  obj = "Huntsman Markhor a Revantusk Village nell'Hinterlands vuole che tu uccida 15 Silvermane Stalkers e 15 Silvermane Howlers. Torna da lui quando avrai finito.$B$BMarkhor ha detto che i lupi si nascondono nelle lande selvagge dell'Hinterlands.",
  progress = "Fagli vedere la forza dei Revantusk!",
  reward = "Ottimo lavoro, $R. I Revantusk ti sono grati per quello che hai fatto.",
}
T[7829] = {
  title = "Caccia ai Selvaggi",
  desc = "Fra le creature dell'Hinterlands, i savage owlbeasts sono tra le più irascibili. Con gli artigli e il becco feroci, queste bestie hanno abbattuto più di un buon guerriero Revantusk.$B$BOgni savage owlbeast che vedi, $R, uccidilo. Quando non reggerai più tutto questo sangue versato, torna da me: allora quello che hai fatto sarà pesato, misurato e giudicato.",
  obj = "Huntsman Markhor a Revantusk Village nell'Hinterlands vuole che tu uccida 20 Savage Owlbeasts. Torna da lui quando avrai finito.$B$BMarkhor ha detto che i Savage Owlbeasts occupano le lande selvagge dell'Hinterlands.",
  progress = "Sgombra la mente dai pensieri impuri, $R, e diventa una cosa sola con la natura selvaggia!",
  reward = "Ben fatto, $N. Hai dimostrato di essere $Gun degno alleato:una degna alleata; dei Revantusk.",
}
T[7830] = {
  title = "Vendicare i Caduti",
  desc = "Quella feccia che si fa chiamare Wildhammer addestra i grifoni a uccidere i troll. È orribile, lo so, ma non preoccuparti: presto giustizia sarà fatta.$B$BPer adesso voglio che pensi solo a sterminare i grifoni anziani della zona, quelli che chiamano Skylords.$B$BUccidine uno e portami la sua piuma.",
  obj = "Huntsman Markhor a Revantusk Village nell'Hinterlands vuole che tu uccida un Razorbeak Skylord e recuperi la sua Skylord Plume. Torna da lui quando avrai finito.$B$BMarkhor ha detto che i Razorbeak Skylord sono una specie rara che tende a occupare le lande selvagge dell'Hinterlands.",
  progress = "Il Razorbeak Skylord è una specie di grifone molto più rara: è quella che si accoppia e mette al mondo una prole assassina.",
  reward = "<Markhor esamina la piuma.>$B$BChissà quanti dei nostri cacciatori ha divorato questa bestia, prima che tu la consegnassi alla giustizia.",
}
T[7831] = {
  title = "Una Donazione di Mageweave",
  progress = "Il mageweave scarseggia, e per ricostituire le scorte il tuo aiuto ci farebbe comodo! Contando su tutta la comunità, per raggiungere l'obiettivo da te ci basterebbe una donazione di 60 pezzi di mageweave cloth. Una generosità del genere non passerebbe inosservata a Orgrimmar, te lo assicuro!$B$BSe hai con te i sessanta pezzi di mageweave cloth e sei $Gpronto:pronta; a donarli, posso prenderli adesso.",
  reward = "Magnifico! Ti ringraziamo della generosa donazione, $N!",
}
T[7832] = {
  title = "Altro Runecloth",
  progress = "Consegnami la pila di runecloth quando sei $Gpronto:pronta;, e la accetterò.",
  reward = "$N — senza eroi come te a lavorare per la tribù, soffriremmo di sicuro. Grazie dell'impegno costante!",
}
T[7833] = {
  title = "Una Donazione di Lana",
  progress = "In questo periodo raccogliamo donazioni di wool cloth. Se doni sessanta pezzi di wool cloth, i Darkspear Trolls ti saranno pienamente riconoscenti per la tua generosità. Con la lana che abbiamo già in magazzino, da te ci servirebbero solo sessanta pezzi in tutto. Per mandare avanti la raccolta, dagli altri del reame dovremmo riuscire a procurarcene quanto basta.$B$BSe hai con te i sessanta pezzi di wool cloth e sei $Gpronto:pronta; a donarli, li prendo subito.",
  reward = "Magnifico! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Wool",
}
T[7834] = {
  title = "Una Donazione di Seta",
  progress = "Le nostre scorte di seta non sono mai state così basse, come quelle di quasi tutti gli altri tessuti. Con le riserve che abbiamo, da te ci servirebbero solo sessanta pezzi di seta in tutto: con l'aiuto degli altri dovremmo farcela ad arrivare all'obiettivo.$B$BLasciamelo dire: un dono generoso come la seta farebbe di certo crescere la tua reputazione qui nella comunità! Se hai con te i sessanta pezzi di silk cloth e sei $Gpronto:pronta; a donarli, li prendo subito.",
  reward = "Magnifico! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Silk",
}
T[7835] = {
  title = "Una Donazione di Mageweave",
  progress = "Il mageweave scarseggia, e per rifornire le scorte il tuo aiuto ci farebbe comodo! Dato che contiamo su tutta la comunità, da te basterebbero 60 pezzi di mageweave cloth per raggiungere l'obiettivo. Te lo assicuro, una generosità simile non sfuggirebbe ai Darkspear Trolls!$B$BSe hai con te i sessanta pezzi di mageweave cloth e sei $Gpronto:pronta; a donarli, li prendo subito.",
  reward = "Magnifico! Ti ringraziamo per la tua generosa donazione, $N!",
}
T[7836] = {
  title = "Una Donazione di Runecloth",
  progress = "$N, per la nostra raccolta di tessuti sei $Gstato:stata; $Gun:una; $Gsostenitore:sostenitrice; formidabile. Ci stiamo dando da fare per rifornire le riserve, ma c'è un tessuto che resta pericolosamente scarso — il runecloth. Ne abbiamo un bisogno disperato, e speriamo che tu possa aiutarci come hai già fatto!$B$BSe sei $Gdisposto:disposta;, portami tutto il runecloth di cui puoi fare a meno. Per cominciare accetteremo una sola donazione di sessanta pezzi, poi si vedrà.",
  reward = "Fantastico — li useremo subito, te lo assicuro. Ancora grazie per l'aiuto! Senza di te saremmo davvero persi.$B$BDopo tutte le donazioni che hai fatto, accetterò di certo ogni altra offerta di runecloth che vorrai farci in futuro. Ti basta passare da me, e farò io stessa in modo che le tue buone azioni non passino inosservate!",
}
T[7837] = {
  title = "Ulteriore Runecloth",
  progress = "Quando vuoi, puoi consegnarmi la pila di runecloth.",
  reward = "$N — se non ci fossero eroi come te a lavorare per la tribù, di certo soffriremmo. Grazie per il tuo impegno di sempre!",
}
T[7838] = {
  title = "Gran Maestro dell'Arena",
  progress = "$GFermo:Ferma; lì, marinaio d'acqua dolce! Portami 12 monili dell'Arena Master e diventerai $Gun Gran Maestro:una Gran Maestra; della Gurubashi Arena! Arrrr!",
  reward = "Hai versato tanto sangue sul suolo dell'Arena, e son lieto di nominarti $GGran Maestro:Gran Maestra; dell'Arena!",
  en_title = "Arena Grandmaster",
}
T[7839] = {
  title = "Teppisti Vilebranch",
  desc = "Quella feccia dei Vilebranch ha invaso il villaggio e mi ha rubato gli utensili! Ne ho altri di riserva, ma quelli me li aveva regalati uno gnomo di buon cuore che mi ha salvato la vita quando ero un giovane orco.$B$BLi rivoglio, $N — per me sono tutto.$B$BSecondo Markhor, gli utensili sono stati visti vicino ai templi di Agol'watha e Shaol'watha.$B$BI templi sono nella regione nordorientale dell'Hinterlands.$B$BRecupera i miei utensili!",
  obj = "Smith Slagtree, a Revantusk Village in Hinterlands, vuole che tu trovi gli Slagtree's Lost Tools. Torna da lui quando avrai finito.$B$BSmith Slagtree ha detto che gli utensili potrebbero essere in uno dei templi Vilebranch nella regione nordorientale di Hinterlands. Dovresti controllare anche Skulk Rock.",
  progress = "Fa' attenzione ai troll Vilebranch della regione, $N: sono feccia spietata e assassina.",
  reward = "I miei utensili! Li hai trovati! Oh, giorno glorioso! Grazie, $N.",
}
T[7840] = {
  title = "Lard Ha Perso il Suo Pranzo",
  desc = "Lard era a fare picnic in posto speciale segreto, e brutto cattivo Vilebranch picchia Lard co' grosso bastone. Lard corre indietro da Revantusk, ma scorda là pranzo di Lard. Ora Lard ha fame. Tu torni a posto speciale segreto e prendi pranzo di Lard, forse? Lard ha paura. Va' a norde! Posto speciale segreto è isola là a norde.",
  obj = "Lard, a Revantusk Village in Hinterlands, vuole che tu trovi il Lard's Lunch. Torna da lui quando avrai finito.$B$BSecondo Lard, l'ha lasciato sull'isola a nord. $GAttento:Attenta; ai troll Vilebranch.",
  progress = "<Lard si strofina la pancia enorme.>$B$BLard tanto affamato.",
  reward = "<Lard ti prende di mano l'enorme haunch of meat e se lo ficca in bocca.>$B$BQuesto ci voleva! Grazzie, $Gpiccoletto:piccoletta;.$B$BTu aiuti Lard, e Lard fa per te cestino da picnic speciale.",
}
T[7841] = {
  title = "Message to the Wildhammer",
  desc = "I Wildhammer si accordano coi nostri nemici e stringono alleanze nuove. Stavolta lavorano con gli elfi alti, mon.$B$B<Otho sputa.>$B$BA quei nani Wildhammer dobbiamo mandare un messaggio — scritto col sangue dei nostri nemici. Ogni elfo alto Highvale che trovi, massacralo, e lascia lì i corpi come avvertimento.$B$BMai mettersi contro i troll!",
  obj = "Otho Moji'ko, a Revantusk Village nell'Hinterlands, vuole che tu massacri 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman e 15 Highvale Rangers. Torna da lui quando hai finito.$B$BPuoi trovare gli elfi alti Highvale alla Quel'Danil Lodge, nella regione nord-occidentale dell'Hinterlands.",
  progress = "Sei troppo $Gpulito:pulita;, mon. Devi buttarti nella mischia — sporcarti le mani col nemico.",
  reward = "Pare che pure i Revantusk stringano alleanze nuove, mon! Hai fatto un buon lavoro.",
}
T[7842] = {
  title = "Un Altro Message to the Wildhammer",
  desc = "Dicono che i Wildhammer coi grifoni sono legati come un troll con la sua compagna. Che schifo, ma lo possiamo usare a nostro vantaggio, mon. Mandiamogli un altro messaggio.$B$BUccidi ogni grifone che vedi nell'Hinterlands e prendi le piume. Con quelle ci facciamo il messaggio finale.",
  obj = "Otho Moji'ko, a Revantusk Village nell'Hinterlands, vuole che tu gli porti 10 Long Elegant Feathers dei grifoni che vivono nell'Hinterlands. Torna da lui quando hai finito.$B$BSi sa che i grifoni vivono in ogni regione dell'Hinterlands.",
  progress = "Con l'ultimo messaggio scappano di sicuro. O sennò si arrabbiano tanto, tanto.",
  reward = "Oh, mon, ne vedremo delle belle. Ancora un passo e i Wildhammer capiranno che coi troll non si scherza!",
}
T[7843] = {
  title = "Il Final Message to the Wildhammer",
  desc = "<Otho ti porge una lunga lancia intrisa di sangue e avvolta in diverse piume di grifone.>$B$BPrendi questa lancia, mon, e portala ad Aerie Peak, proprio in mezzo alla città, vicino al pozzo. Piantala! Ficcala dritta nel terreno! Fai vedere a quei nani che i troll fanno sul serio! Poi torna qui quando hai fatto, e magari $Gvivo:viva;.",
  obj = "Otho Moji'ko, a Revantusk Village nell'Hinterlands, vuole che tu vada ad Aerie Peak, nella regione occidentale dell'Hinterlands, e metta il Final Message to the Wildhammer vicino al pozzo al centro della città. Torna da lui quando hai finito.$B$BFai attenzione ai nani Wildhammer arrabbiati e ai membri turbolenti dell'Alleanza.",
  progress = "Che aspetti, mon?",
  reward = "Avrei voluto esserci anch'io a vedere che facce facevano, mon. Stanno facendo le valigie? Se ne vanno dalla città?$B$BHai fatto bene, $N. Proprio bene. Come ricompensa, Otho ti dà il mojo grosso.",
}
T[7844] = {
  title = "Cugini Cannibali",
  desc = "Nell'Hinterlands abitano tre tribù di troll diverse, $N, e le somiglianze finiscono più o meno qui: siamo tutti troll e viviamo tutti nell'Hinterlands.$B$BI Vilebranch — e il nome gli calza a pennello — sono una banda di depravati che si nutrono di altri troll e di umanoidi.$B$BSe ci fosse Zul'jin, li avrebbe annientati tutti quanti con un gesto della mano — ahimè, Zul'jin non è ancora tornato, e ci tocca cavarcela da soli.$B$BSta a te distruggere la feccia della regione!",
  obj = "Mystic Yayo'jin, a Revantusk Village in Hinterlands, vuole che tu uccida 30 Vilebranch Scalpers e 15 Vilebranch Soothsayers. Torna da lei quando avrai finito.$B$BYayo'jin ha detto che questi troll si trovano vicino ai templi di Shaol'watha e Agol'watha, nella regione a nord-nordest di Hinterlands.",
  progress = "I Vilebranch Soothsayers e Scalpers vivono nella regione a nord-nordest dell'Hinterlands.",
  reward = "Ben fatto, $C. Nemmeno Zul'jin in persona avrebbe saputo fare di meglio!",
}
T[7845] = {
  title = "Elder Torntusk Rapito!",
  desc = "I selvaggi Vilebranch hanno attaccato il nostro villaggio di notte, con un'incursione audace, e si sono presi il mio compagno. Le nostre spie mi hanno detto che è ancora vivo, prigioniero in cima a Jintha'alor. Pare che Vile Priestess Hexx lo stia preparando per sacrificarlo al Dio del sangue senza volto, Hakkar.$B$BDevi salvarlo, $N! Il villaggio non reggerebbe a una perdita così grande.",
  obj = "Primal Torntusk a Raventusk Village, in Hinterlands, vuole che tu salvi il suo compagno, Elder Torntusk, da Jintha'alor.$B$BTi hanno detto che è tenuto prigioniero in cima a Jintha'alor, la capitale dei Vilebranch, che si trova nella regione meridionale di Hinterlands.",
  reward = "Muoviti, $N. Di sicuro hanno già avvertito le guardie che sei qui.",
}
T[7846] = {
  title = "Recupera la Chiave!",
  desc = "La chiave delle catene ce l'ha Hitah'ya the Keeper, nella grotta qui vicino. Fai attenzione, $C, perché è ben sorvegliata.$B$BUccidila e torna qui con la chiave per aprire i miei ceppi: solo allora sarò libero di tornare a casa.",
  obj = "Elder Torntusk a Jintha'alor vuole che tu uccida Hitah'ya the Keeper per prendere la Shackle Key delle sue catene. Torna da Elder Torn'tusk quando avrai recuperato la chiave.",
  progress = "Sbrigati!",
  reward = "Libero, finalmente! Grazie, $N. I Revantusk conosceranno le tue gesta!",
}
T[7847] = {
  title = "Torna da Primal Torntusk",
  desc = "Torna dalla mia compagna, Primal Torntusk, a Revantusk Village, e dille che sto tornando a casa! Ti ricompenserà, puoi starne $Gcerto:certa;.",
  obj = "Elder Torntusk a Jintha'alor vuole che tu torni da Primal Torntusk a Revantusk Village con la notizia della sua liberazione.",
  reward = "Hai fatto un grande servizio ai Revantusk, $N! Siamo molto in debito con te.",
}
T[7848] = {
  title = "Sintonizzazione con il Nucleo",
  desc = "Tutto intorno a noi le fenditure si agitano, si lacerano e crollano, $R. A nemmeno due passi da qui si apre uno squarcio che attraversa le profondità del Blackrock Mountain e arriva fino alle fauci del Firelord.$B$B$GSorpreso:Sorpresa;? Peccato... Le razze mortali non comprendono ciò che non possono vedere, toccare o sentire.$B$BIl portale è lì, te lo assicuro, e vi si può accedere.$B$BHo stuzzicato il tuo interesse? La sintonizzazione è semplice. Avventurati nei Blackrock Depths e recupera un core fragment. Portamelo e sintonizzerò la tua essenza con il portale.",
  obj = "Avventurati fino al portale d'ingresso del Molten Core in Blackrock Depths e recupera un Core Fragment. Torna da Lothos Riftwaker in Blackrock Mountain quando avrai recuperato il Core Fragment.",
  progress = "Prima che ti sia concesso di entrare, devi sintonizzare la tua anima con il Molten Core.",
  reward = "Ora posso trasportarti nel Molten Core. Chiedi e sarà fatto.",
}
T[7849] = {
  title = "Ansia da Separazione",
  desc = "Anch'io, come tanti nel nostro villaggio, ho perso una persona cara nelle lande selvagge. Ahimè, era mio fratello gemello, Malkhor — l'hanno catturato i Vilebranch nella stessa incursione in cui si sono presi la compagna di Torntusk.$B$BPurtroppo non era destino che vivesse, e l'hanno giustiziato in modo rapido e brutale; poi hanno dato i suoi resti in pasto alle melme e ai lupi dei Vilebranch.$B$BPer la sua vita è troppo tardi, ma per la sua anima no. Recupera i suoi resti, $N.",
  obj = "Huntsman Markhor a Revantusk Village nell'Hinterlands vuole che tu recuperi i resti di suo fratello gemello. Trova e porta l'Huntsman Malkhor's Skull e le Huntsman Malkhor's Bones a Huntsman Markhor.$B$BMarkhor ha detto che i resti di suo fratello sono stati dati in pasto alle melme e ai lupi dei Vilebranch. Ha anche detto che a Jintha'alor c'è una fossa dei rifiuti piena di melme, oltre a una tana di lupi. Entrambi i luoghi si trovano vicino alla cima del tempio.",
  progress = "Quando avrò i suoi resti li porterò a Yayo'jin, perché li prepari per una sepoltura come si deve.",
  reward = "Fratello mio carissimo, quanto mi mancherai...$B$BGrazie per l'aiuto, $N. Per me sei $Gun vero eroe:una vera eroina;.",
}
T[7850] = {
  title = "Recipienti Oscuri",
  desc = "I Vilebranch combattono con una ferocia sovrannaturale, frutto delle immonde trame magiche di Vile Priestess Hexx.$B$BSparsi per tutta Jintha'alor troverai degli oscuri vessels of tainted blood: irradiano la magia immonda del Dio del sangue senza volto, dando forza ai Vilebranch e spingendoli anche alla follia.$B$BRuba quei recipienti e riportameli: potrò rimuovere la corruzione e, alla fine, allentare la presa del Dio del sangue.",
  obj = "Primal Torntusk, a Revantusk Village in Hinterlands, vuole che tu recuperi 10 Vessels of Tainted Blood da Jintha'alor. Torna da Primal Torntusk quando avrai finito.",
  progress = "Sii $Gcauto:cauta; quando combatti i Vilebranch, $N. Hanno la mente annebbiata — si battono fino alla morte.",
  reward = "L'energia oscura che spinge i Vilebranch si è dissolta — per ora. Nella battaglia contro il male dobbiamo restare sempre vigili: anche quando la Sacerdotessa Vile viene distrutta, presto un'altra ne prende il posto.",
}
T[7861] = {
  title = "Ricercati: Vile Priestess Hexx e i Suoi Tirapiedi",
  desc = "Per ordine di Primal Torntusk, Vile Priestess Hexx e i suoi tirapiedi vanno consegnati alla giustizia!$B$BUna lauta ricompensa attende chiunque uccida Vile Priestess Hexx insieme a tutta la sua guardia scelta Aman'zasi.",
  obj = "Ti è stato ordinato di uccidere Vile Priestess Hexx e 20 Vilebranch Aman'zasi Guards. Una volta completato il compito, presentati da Primal Torntusk a Revantusk Village, in Hinterlands.$B$BVile Priestess Hexx e le Guardie Aman'zasi si trovano in cima a Jintha'alor, in Hinterlands.",
  progress = "Hai notizie da Jintha'alor?",
  reward = "Questo sì che è un colpo devastante per i Vilebranch. Sarai $Gricompensato:ricompensata;, e riccamente, $N.",
}
T[7862] = {
  title = "Offerta di Lavoro: Capitano della Guardia di Revantusk Village",
  desc = "Con la perdita di Guard Captain Malkhor, il posto di Capitano della Guardia dei Revantusk è di nuovo vacante. Se sei $Ginteressato:interessata; a diventare tu il Capitano della Guardia dei Revantusk, porta a termine i compiti che seguono e presenta la tua candidatura a Primal Torntusk:$B$BStermina i Vilebranch Berserkers.$B$BStermina i Vilebranch Shadow Hunters.$B$BStermina i Vilebranch Blood Drinkers.$B$BStermina i Vilebranch Soul Eaters.",
  obj = "Ti è stato affidato il compito di decimare 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers e 20 Vilebranch Soul Eaters.$B$BSe completi questo compito, torna da Primal Torntusk a Revantusk Village, in Hinterlands.",
  progress = "Sei qui per l'offerta di lavoro?",
  reward = "Sei $Gun candidato davvero degno:una candidata davvero degna; del nuovo incarico, $N. Accetta questo monile come segno del nostro apprezzamento per il tuo impegno. Esaminerò tutte le candidature l'anno prossimo.",
}
T[7863] = {
  title = "Sentinel Basic Care Package",
  reward = "Hai senz'altro cominciato a darci prova del tuo valore, $N. Come ricompensa, prendi questo kit curativo! Dentro ci sono razioni e bende che funzionano soltanto nella Warsong Gulch.$B$BSe continuerai a dimostrare quanto vali nella Gulch, potrai acquistare questi oggetti: le razioni diventano disponibili quando raggiungi il livello Amichevole con noi, le bende con il livello Onorato.",
  en_title = "Sentinel Basic Care Package",
}
T[7864] = {
  title = "Sentinel Standard Care Package",
  reward = "Hai senz'altro cominciato a darci prova del tuo valore, $N. Come ricompensa, prendi questo kit curativo! Dentro ci sono razioni e bende che funzionano soltanto nella Warsong Gulch.$B$BSe continuerai a dimostrare quanto vali nella Gulch, potrai acquistare questi oggetti: le razioni diventano disponibili quando raggiungi il livello Amichevole con noi, le bende con il livello Onorato.",
  en_title = "Sentinel Standard Care Package",
}
T[7865] = {
  title = "Sentinel Advanced Care Package",
  reward = "Hai senz'altro cominciato a darci prova del tuo valore, $N. Come ricompensa, prendi questo kit curativo! Dentro ci sono razioni e bende che funzionano soltanto nella Warsong Gulch.$B$BSe continuerai a dimostrare quanto vali nella Gulch, potrai acquistare questi oggetti: le razioni diventano disponibili quando raggiungi il livello Amichevole con noi, le bende con il livello Onorato.",
  en_title = "Sentinel Advanced Care Package",
}
T[7866] = {
  title = "Outrider Basic Care Package",
  reward = "Di certo hai cominciato a dimostrarci quanto vali, $N. Prendi questo kit curativo come ricompensa! Dentro ci sono razioni e bende che puoi usare solo nella Warsong Gulch.$B$BMan mano che continuerai a dimostrare il tuo valore nella Gulch, potrai comprare questi oggetti. Le razioni le puoi avere quando sei a livello Amichevole con noi, le bende quando sei a livello Onorato.",
  en_title = "Outrider Basic Care Package",
}
T[7867] = {
  title = "Outrider Standard Care Package",
  reward = "Di certo hai cominciato a dimostrarci quanto vali, $N. Prendi questo kit curativo come ricompensa! Dentro ci sono razioni e bende che puoi usare solo nella Warsong Gulch.$B$BMan mano che continuerai a dimostrare il tuo valore nella Gulch, potrai comprare questi oggetti. Le razioni le puoi avere quando sei a livello Amichevole con noi, le bende quando sei a livello Onorato.",
  en_title = "Outrider Standard Care Package",
}
T[7868] = {
  title = "Outrider Advanced Care Package",
  reward = "Di certo hai cominciato a dimostrarci quanto vali, $N. Prendi questo kit curativo come ricompensa! Dentro ci sono razioni e bende che puoi usare solo nella Warsong Gulch.$B$BMan mano che continuerai a dimostrare il tuo valore nella Gulch, potrai comprare questi oggetti. Le razioni le puoi avere quando sei a livello Amichevole con noi, le bende quando sei a livello Onorato.",
  en_title = "Outrider Advanced Care Package",
}
T[7871] = {
  title = "Sconfiggi gli Invasori!",
  desc = "Oltre questo tunnel ti aspetta un campo di lotta e di tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra: abbatte la vegetazione sempreverde per alimentare le sue macchine da guerra.$B$BEntra in Warsong Gulch e difendi la Silverwing Hold. Ricaccia indietro le forze d'invasione dell'Orda!$B$BSe ci riuscirai, ti guadagnerai un Contrassegno d'Onore. Portamelo, $N, e avrai la tua ricompensa.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong a Silverwing Grove.",
  progress = "Hai combattuto in Warsong Gulch, hai difeso la Silverwing Hold?",
  reward = "In Warsong Gulch hai dimostrato quanto vali per la nostra lotta. Continua ad aiutare la causa e portami altri Contrassegni d'Onore: così ti guadagnerai ancora di più la nostra fiducia.",
  en_title = "Vanquish the Invaders!",
  en_obj = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
}
T[7872] = {
  title = "Sconfiggi gli Invasori!",
  desc = "Oltre questo tunnel ti aspetta un campo di lotta e di tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra: abbatte la vegetazione sempreverde per alimentare le sue macchine da guerra.$B$BEntra in Warsong Gulch e difendi la Silverwing Hold. Ricaccia indietro le forze d'invasione dell'Orda!$B$BSe ci riuscirai, ti guadagnerai un Contrassegno d'Onore. Portamelo, $N, e avrai la tua ricompensa.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong a Silverwing Grove.",
  progress = "Hai combattuto in Warsong Gulch, hai difeso la Silverwing Hold?",
  reward = "In Warsong Gulch hai dimostrato quanto vali per la nostra lotta. Continua ad aiutare la causa e portami altri Contrassegni d'Onore: così ti guadagnerai ancora di più la nostra fiducia.",
}
T[7873] = {
  title = "Sconfiggi gli Invasori!",
  desc = "Oltre questo tunnel ti aspetta un campo di lotta e di tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra: abbatte la vegetazione sempreverde per alimentare le sue macchine da guerra.$B$BEntra in Warsong Gulch e difendi la Silverwing Hold. Ricaccia indietro le forze d'invasione dell'Orda!$B$BSe ci riuscirai, ti guadagnerai un Contrassegno d'Onore. Portamelo, $N, e avrai la tua ricompensa.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong a Silverwing Grove.",
  progress = "Hai combattuto in Warsong Gulch, hai difeso la Silverwing Hold?",
  reward = "In Warsong Gulch hai dimostrato quanto vali per la nostra lotta. Continua ad aiutare la causa e portami altri Contrassegni d'Onore: così ti guadagnerai ancora di più la nostra fiducia.",
}
T[7874] = {
  title = "Reprimi gli Usurpatori Silverwing",
  desc = "Le terre selvagge della foresta di Ashenvale cederanno alla potenza dell'Orda, $R. Qualunque cosa dicano o facciano i Silverwing, non potranno fermare il nostro imperativo sovrano. Kalimdor appartiene all'Orda. Come osano provare a impedirci di raccogliere ciò che è nostro di diritto!$B$BMentre spazzi via i loro deboli tentativi di rallentare la nostra avanzata, lascia che l'orgoglio ti gonfi il petto. Distruggi le Silverwing Sentinels e guadagnati un Contrassegno d'Onore. Torna da me con il Contrassegno, $N, e sarai $Gricompensato:ricompensata;.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.",
  progress = "Il sangue dei nostri nemici è un contrassegno d'onore. Tu ne hai uno?",
  reward = "<Captain Shatterskull lancia un ruggito di trionfo>$B$BQuanto potranno resistere ancora? Quanta altra feccia dell'Alleanza dovrà perire per mano dell'Orda prima che si ritirino? Solo il tempo lo dirà, $R...",
  en_title = "Quell the Silverwing Usurpers",
  en_obj = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
}
T[7875] = {
  title = "Reprimi gli Usurpatori Silverwing",
  desc = "Le terre selvagge della foresta di Ashenvale cederanno alla potenza dell'Orda, $R. Qualunque cosa dicano o facciano i Silverwing, non potranno fermare il nostro imperativo sovrano. Kalimdor appartiene all'Orda. Come osano provare a impedirci di raccogliere ciò che è nostro di diritto!$B$BMentre spazzi via i loro deboli tentativi di rallentare la nostra avanzata, lascia che l'orgoglio ti gonfi il petto. Distruggi le Silverwing Sentinels e guadagnati un Contrassegno d'Onore. Torna da me con il Contrassegno, $N, e sarai $Gricompensato:ricompensata;.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.",
  progress = "Il sangue dei nostri nemici è un contrassegno d'onore. Tu ne hai uno?",
  reward = "<Captain Shatterskull lancia un ruggito di trionfo>$B$BQuanto potranno resistere ancora? Quanta altra feccia dell'Alleanza dovrà perire per mano dell'Orda prima che si ritirino? Solo il tempo lo dirà, $R...",
}
