}
T[7877] = {
  title = "Il Treasure of the Shen'dralar",
  desc = "Nella biblioteca, l'Athenaeum, sotto la scalinata è nascosta un'antica cassa. Prendi quello che desideri.",
  obj = "Torna all'Athenaeum e trova il Treasure of the Shen'dralar. Reclama la tua ricompensa!",
  reward = "Apri la cassa e trovi...",
}
T[7881] = {
  title = "Stivali per la Fiera",
  progress = "Noi della Darkmoon Faire camminiamo parecchio. Andiamo a piedi da una tappa all'altra della fiera... anzi, non ci vedrai mai seduti mentre lavoriamo! Non c'è da stupirsi, quindi, se consumiamo un bel po' di stivali! Ci servono calzature resistenti ma anche eleganti, e gli embossed leather boots fanno proprio al caso nostro.$B$BTu! Sei $Gun conciatore:una conciatrice;: fammi degli embossed leather boots e, in cambio del lavoro, ti darò un biglietto della Darkmoon Faire.",
  reward = "Grazie, $N. Sono fatti proprio bene. Una lavorazione di prima qualità! Ecco un biglietto della Darkmoon Faire... buon divertimento, $Gsignore:mia signora;.",
  en_title = "Carnival Boots",
}
T[7882] = {
  title = "Giubbe per la Fiera",
  progress = "I nostri lavoranti della Fiera non si limitano a spazzare i rifiuti e a piantare picchetti! Aiutano anche a proteggere la carovana durante gli spostamenti, e per questo hanno sempre bisogno di giubbe corazzate belle robuste.$B$BSe fabbrichi qualche tough leather armor e me la porti, farò in modo che arrivi alle persone giuste. In cambio, ti procurerò anche un po' di biglietti della Darkmoon Faire.",
  reward = "Ah, hai portato le giubbe. Splendido. Posso chiederti da che animale viene la pelle che hai usato? Le cuciture sono eseguite molto bene, e la grana del cuoio ha un che di ruvido e robusto. Si vede che sei $Gun artigiano:un'artigiana; di talento!$B$BGrazie, $N, ed ecco i tuoi biglietti.",
  en_title = "Carnival Jerkins",
}
T[7883] = {
  title = "Lo Gnomo Più Grande del Mondo!",
  progress = "Yebb Nebblegear vuole ingaggiare nuovi artisti per il suo spettacolo, e sta cercando in lungo e in largo lo gnomo più grande del mondo. Ne conosci per caso qualcuno di dimensioni ragguardevoli?$B$BVuole che il costume sia pronto molto prima di trovare lo gnomo. Credo che una barbaric harness sarebbe una buona base da cui partire: potresti fabbricarne qualcuna e portarmele? Se lo farai, avrò per te una pila di biglietti della Darkmoon Faire...",
  reward = "Oh, cielo, sono proprio enormi!! Non riesco a immaginare uno gnomo capace di riempirle a dovere, ma niente paura — se quello che troveremo non sarà abbastanza grande, posso sempre aggiustargli il costume.$B$BMille grazie, $N. Ecco i biglietti che ti avevo promesso.",
  en_title = "The World's Largest Gnome!",
}
T[7884] = {
  title = "Il Ragazzo Crocolisco e il Bearded Murloc",
  progress = "Yebb sta preparando altre attrazioni per il suo zoo, tra cui dimore umide e paludose per un ragazzo cresciuto dai crocolischi, e forse per un murloc. Ci serviranno dei bei gambali impermeabili, così da non inzupparci durante il montaggio e lo smontaggio. Per un lavoro del genere, credo che quelli di scaglie di tartaruga faranno al caso nostro.$B$B$N, sapresti fabbricarli? Se lo farai, avrai in premio una bella pila di biglietti della Darkmoon Faire...",
  reward = "Ottimo, li hai fatti! Andranno benissimo... Spero solo di non dover essere io a pulire la gabbia dei crocolischi, quando sarà il momento. Quelle bestie sanno essere proprio bestiali, non credi?$B$BEcco i tuoi biglietti, $N. Goditeli, e goditi il soggiorno alla Darkmoon Faire!",
  en_title = "Crocolisk Boy and the Bearded Murloc",
}
T[7885] = {
  title = "Kit per Armature",
  progress = "Forse non te ne rendi conto, ma mandare avanti una fiera itinerante costa un sacco! Si consuma tutto così in fretta che, se riusciamo a guadagnarci qualcosa, è un miracolo.$B$BCon tutte queste spese nascoste, siamo sempre a caccia di un modo per tenere in sesto l'attrezzatura spendendo il meno possibile. Le tende, per esempio, si strappano spesso, ma ho scoperto che i kit per armature di cuoio fanno da toppe ottime. Potresti trovarmi un po' di kit per armature e portarmeli? Ci faresti risparmiare un bel po'! In cambio avrò per te una manciata di biglietti della Darkmoon Faire...",
  reward = "Ottimo! Vanno benissimo! Ho appena visto uno strappo in una tenda laggiù, e per ripararlo uno di questi kit per armature è proprio quello che mi ci vuole!$B$BGrazie mille, $N. Con questi kit risparmieremo un sacco in riparazioni. Ecco i tuoi biglietti — te li meriti!",
}
T[7889] = {
  title = "Coarse Weightstone",
  progress = "Ci vuole un sacco di fatica per essere la donna più forte del mondo! I miei pesi stanno diventando troppo leggeri, e se voglio restare in forma me ne servono altri!$B$BPensi di potermi portare qualche pietra da contrappeso? Se ci riesci, ti darò un biglietto della Darkmoon Faire.",
  reward = "Magnifico! Andranno benissimo! Non sono troppo pesanti, ma nemmeno troppo leggere. Sono perfette per mettere su muscoli!$B$BGrazie mille, $N. Ecco il tuo biglietto della Darkmoon Faire!",
  en_title = "Coarse Weightstone",
}
T[7890] = {
  title = "Heavy Grinding Stone",
  progress = "Per allenarmi, mi piace infilare un bastone tra le heavy grinding stones e poi sollevarlo sopra la testa. Non è facile, ma non si diventa la donna più forte del mondo, come me, stando con le mani in mano!$B$BMi aiuteresti? Mi servono altre pietre da molatura — portamene qualcuna e te le scambierò con dei biglietti della Darkmoon Faire.",
  reward = "Hai portato le pietre! E sono pesanti! Sento già i muscoli che crescono. Grazie, $N!$B$BEcco, prendi questi biglietti, e mi raccomando, non mangiare troppi dolci mentre sei alla fiera. $GUn:Una; $C grande e forte come te deve tenersi in forma per combattere!",
  en_title = "Heavy Grinding Stone",
}
T[7891] = {
  title = "Green Iron Bracers",
  progress = "Sto preparando un costume nuovo per quando avrò un padiglione tutto mio, come donna più forte del mondo! Al momento cerco dei bracciali da indossare. Non devono coprire molto, perché la gente vuole vedere i miei muscoli, ma un tocco di colore mi piacerebbe comunque, capisci?$B$BChe ne dici di green iron bracers, $N? Sapresti farmi dei green iron bracers? Se ci riesci, ho un bel mucchio di biglietti della Darkmoon Faire per te.",
  reward = "Sì! Sono proprio quello che mi serve! Che colore stupendo, e lasciano comunque le braccia scoperte, così si vede quanto sono forti! Perfetti!$B$BTieni, $N. Ecco i tuoi biglietti — divertiti!",
  en_title = "Green Iron Bracers",
}
T[7892] = {
  title = "Big Black Mace",
  progress = "Nel mio numero da donna più forte del mondo, ho intenzione di farmi dare degli oggetti dal pubblico e di fracassarli con una big black mace!$B$BSapresti costruirmi una big black mace, $N?",
  reward = "Ah, perfetta! Questa mazza ha una testa bella grossa e pesante. Scommetto che potrei sfasciarci quasi qualsiasi cosa. Spero solo di non romperla insieme a quello che colpisco!$B$BEcco i tuoi biglietti, $N. Buon divertimento alla fiera!",
  en_title = "Big Black Mace",
}
T[7893] = {
  title = "Rituali di Forza",
  progress = "$N, per diventare la donna più forte del mondo ho girato il mondo, e ho imparato i segreti per sviluppare i muscoli da maestri dei pesi di terre lontane, da guru della forza e da antichi manuali. Ora conosco esercizi proibiti che ucciderebbero i deboli e storpierebbero i non iniziati!$B$BQueste prove di forza e di preparazione fisica vanno fatte allenandosi con le pietre abrasive più dense. $N, potresti trovare o fabbricare qualche pietra abrasiva e portarmela? Se lo fai, ti darò dei biglietti...",
  reward = "Grazie, $N. Queste pietre mi serviranno per un rituale che accresce la forza: l'ho appreso da un'antica tavoletta, nel folto della giungla di Stranglethorn.$B$BSi dice che colei che compie questo rito sacro come si deve avrà la forza e la resistenza di dieci Tauren!",
}
T[7894] = {
  title = "Copper Modulator",
  progress = "Yebb sta preparando una nuova attrazione per lo Zoo Bizarre, che lascerà la gente a bocca aperta e la farà impazzire di gioia! Ma ci vorrà un sacco di lavoro, e un sacco di materiali...$B$BTra cui i copper modulators. Ci servono tantissimi modulatori per le parti meccaniche dell'attrazione. Portami dei copper modulators e te li scambierò con un biglietto della Darkmoon Faire.",
  reward = "Aha! I modulatori! Magnifico!$B$BNon posso dirti di preciso cosa stiamo costruendo, ma questi ci saranno preziosissimi per realizzarlo. Sono in debito con te, $N, ma ti prego, prendi questo biglietto della Darkmoon Faire in segno di gratitudine.",
  en_title = "Copper Modulator",
}
T[7895] = {
  title = "Whirring Bronze Gizmo",
  progress = "Il mio nuovo stand sarà uno spettacolo, sì, $Gsignore:signora;! Uno spettacolo da vedere e... per pochi fortunati, da toccare!$B$BSento già i whirring bronze gizmos intonare un canto di estasi meccanica, mentre i clienti si avvicinano al mio banco e mettono alla prova la propria abilità!$B$BAh... ora mi servono gli ingranaggi veri e propri per avvicinare il mio sogno alla realtà. Ti prego, $N, portami dei whirring bronze gizmos... e avrai i biglietti della Darkmoon Faire!",
  reward = "Hai portato gli ingranaggi! Splendido! Già adesso sento nella mente il loro coro di ronzii e frullii! Oh, quando avrò finito questo stand, sarà la meraviglia del mondo, dai retta a me!$B$BEcco i tuoi biglietti, $N. E buon divertimento alla Fiera!",
  en_title = "Whirring Bronze Gizmo",
}
T[7896] = {
  title = "Green Fireworks",
  progress = "Quando finalmente questo stand sarà in funzione, vorrò farmi pubblicità! E quale modo migliore per farsi notare dei fuochi d'artificio?$B$BBeh, qualcuno potrebbe pensare che l'odore di un calderone dove ribollono le teste dei nemici attiri di più la folla, ma... qui c'è gente di ogni sorta, e non tutti apprezzerebbero. Quindi dovranno bastare i fuochi d'artificio!$B$BPortami dei green fireworks, $N, e per te c'è una bella manciata di biglietti della Darkmoon Faire.",
  reward = "Hai portato i fuochi d'artificio. Ottimo lavoro, $N! Non vedo l'ora di accenderli per annunciare al mondo che il mio stand è pronto! Devo ancora aspettare, e parecchio, temo, ma... sarò pronto quando sarò pronto, no?$B$BEcco i biglietti, $N. Divertiti!",
  en_title = "Green Fireworks",
}
T[7897] = {
  title = "Mechanical Repair Kits",
  progress = "Se non posso aprire il mio stand è soprattutto perché... è tutto rotto! Mi servono dei mechanical repair kits per aggiustare tutta questa roba!$B$BPotresti portarmeli, $N? Facciamo uno scambio... kit in cambio di biglietti della Darkmoon Faire. Che ne dici?",
  reward = "Grazie! Ora posso mettermi a riparare.$B$BCi vorranno un sacco di kit e un sacco di notti in bianco per rimettere tutto in funzione. A volte penso che sarebbe meglio tornare alle origini e ricominciare a fare il cacciatore di teste, ma... la Fiera mi ha trattato bene.$B$BPrendi questi biglietti, $N, e divertiti!",
  en_title = "Mechanical Repair Kits",
}
T[7898] = {
  title = "Thorium Widget",
  progress = "Anche Yebb Nebblegear, come me, sta lavorando a una futura attrazione. Nebb dice che sarà così straordinaria da attirare gente da tutto il mondo... e che ci farà diventare tutti molto, molto ricchi!$B$BPer costruirla gli servono dei thorium widgets, e vuole che li raccolga io per lui. Allora, $N, che ne dici? Sai dove si trovano dei thorium widgets? E se sei $Gun ingegnere:un'ingegnera;, sai fabbricarli? Ti va di scambiarli con dei biglietti della Darkmoon Faire?",
  reward = "Ah, grazie, $N! Questi meccanismi a Yebb piaceranno. Cosa voglia farci non lo so, ma Yebb è un piccolo gnomo astuto. Astuto, e forse anche un po' subdolo....$B$BSe solo gli piacesse il sapore della carne umanoide... sarebbe un ottimo troll!$B$BTieni, $N. I patti sono patti, e questi biglietti sono tuoi.",
}
T[7899] = {
  title = "Small Furry Paws",
  progress = "La prima lezione per attirare la folla è: adescala con aggeggi e ninnoli! Mi daresti una mano?$B$BMi servono small furry paws da usare come premi. Le trovi sui felini di Barrens o di Darkshore....$B$BPortami un po' di zampe e in cambio ti darò un biglietto della Darkmoon Faire.",
  reward = "Fantastico, le hai prese! Ci serviranno per fare giocattoli e gingilli, che attireranno altra gente alla Fiera!$B$BEcco il tuo biglietto, $N. Te lo sei guadagnato!",
  en_title = "Small Furry Paws",
}
T[7900] = {
  title = "Torn Bear Pelts",
  progress = "I bambini adorano i giocattoli! E ho scoperto che i piccoli, di qualunque razza siano, vanno tutti matti per i pupazzi morbidi e pelosi fatti con le torn bear pelts!$B$BLe pelli le trovi sugli orsi di Ashenvale o di Hillsbrad. Portamene un mucchio e ti guadagnerai un mucchio di biglietti della Darkmoon Faire!",
  reward = "Belle pelli, $N! Farò cucire a qualcuno un sacco di pupazzi. Con un po' d'imbottitura e un tocco di colore, credo che faranno gola ai bambini di tutta Azeroth!$B$BI biglietti? Ah, sì, il tuo compenso! Eccoli!",
  en_title = "Torn Bear Pelts",
}
T[7901] = {
  title = "Soft Bushy Tails",
  progress = "È incredibile a cosa la gente dia valore! Prendi, per esempio, un bastoncino di legno con attaccata una soft bushy tail. Ecco, io e te potremmo pensare che una cosa del genere non valga granché... ma se a quella cianfrusaglia dai un bel nome come \"Coda Selvaggia di Fuzz\" e la metti in una scatola carina, tutti penseranno che sia preziosa. La spazzatura diventa un tesoro!$B$BPortami delle soft bushy tails prese ai lupi di Desolace e di Badlands, e ti darò dei biglietti della Darkmoon Faire.",
  reward = "Ottimo lavoro, $N! Queste code saranno premi fantastici per il nostro pubblico, e questo vuol dire visitatori contenti... che lo raccontano agli amici e ne portano altri!$B$BEcco i tuoi biglietti! Divertiti alla Darkmoon Faire... e non dimenticare di parlare di noi ai tuoi amici!",
  en_title = "Soft Bushy Tails",
}
T[7902] = {
  title = "Vibrant Plumes",
  progress = "L'immaginazione è una cosa incredibile. Può far sembrare la collinetta più piccola la montagna più alta. E l'ombra più innocua può diventare quella proiettata da un incubo orribile!$B$BNoi della Darkmoon Faire lasciamo sbocciare l'immaginazione dei nostri visitatori! Ma per aiutare la loro fantasia a spingersi più in là... a volte dobbiamo ricorrere a qualche trucco.$B$BMi servono vibrant plumes per una delle mie attrazioni. Puoi prenderle dagli uccelli delle zone più pericolose di Azeroth. Portamele e avrai tanti biglietti!",
  reward = "Ah, le piume! Sono stupende, non trovi! Con bellezze simili sarà facile accendere la fantasia di chiunque!$B$BChe opera di bene fai, $N. I sorrisi dei nostri visitatori quando vedono lo spettacolo sono già un compenso grandioso, ma accetta anche questi biglietti, ti prego.",
  en_title = "Vibrant Plumes",
}
T[7903] = {
  title = "Evil Bat Eyes",
  progress = "Ti capita mai di ritrovarti in una caverna a notte fonda, a vagare in cerca di avventure? Sì? Davvero? Beh, allora li avrai visti, gli occhi inquietanti dei pipistrelli che ti fissano dall'alto e aspettano che abbassi la guardia per succhiarti il sangue!$B$BChe pensiero spaventoso, non trovi? Ma certo! Gli occhi di pipistrello fanno paura, non c'è dubbio!$B$B$N, mi porteresti degli evil bat eyes? Mi servono per... una cosa che sto progettando. Una cosa spaventosa.$B$BLi trovi addosso ai pipistrelli delle Eastern Plaguelands.",
  reward = "Ottimo! Li hai presi, gli occhi! Spero che dare la caccia a quei pipistrelli ti abbia fatto venire i brividi: se ha spaventato $Gun:una; $C $Gcoraggioso:coraggiosa; come te, quegli occhi faranno di sicuro paura ai visitatori della nostra Fiera.$B$BTieni questi biglietti, $N, e grazie dell'aiuto.",
}
T[7905] = {
  title = "La Darkmoon Faire",
  desc = "Sta arrivando la Darkmoon Faire! Quando sarà in città, non perderti nessuna delle sue meraviglie e delle sue emozioni!$B$BSe fai in fretta, puoi cambiare questo buono con biglietti premio gratis! Ti basta consegnarlo a Gelvas Grimgate, dentro il luna park.$B$BAl momento la Fiera è fuori da Goldshire, nell'Elwynn Forest. Non mancare! Vai oggi stesso!",
  obj = "Consegna il Free Ticket Voucher a Gelvas Grimgate, all'interno del luna park della Darkmoon Faire.",
  progress = "Sì, $Gamico:amica;, in cosa posso aiutarti? Hai un buono da riscattare?",
  reward = "$GBenvenuto:Benvenuta; alla Darkmoon Faire! Questo buono vale CINQUE, sì, CINQUE biglietti premio!$B$BQuando avrai messo da parte un po' di biglietti premio, vieni da me e li cambierai con premi di valore. Più biglietti hai, più premi puoi vincere. Urrà!",
  en_title = "The Darkmoon Faire",
  en_obj = "Deliver the Free Ticket Voucher to Gelvas Grimgate, located inside the Darkmoon Faire carnival.",
}
T[7907] = {
  title = "Mazzo delle Bestie di Darkmoon",
  desc = "Ora che hai riunito in un mazzo tutte le carte delle Bestie, compare misteriosamente una nona carta, con lo stesso dorso delle altre otto. Sopra c'è scritto: \"Riporta queste carte alla Darkmoon Faire e sarai $Gricompensato:ricompensata;.\" Hai sentito dire che la fiera si ferma a turno a Mulgore e a Goldshire, a qualche mese di distanza: dovrai aspettare che ripassi da queste parti.",
  obj = "Riporta il Mazzo delle Bestie alla Darkmoon Faire quando arriva in città.",
  progress = "Vedo che sei $Griuscito:riuscita; a completare un mazzo di bestie! Congratulazioni!",
  reward = "Allora hai messo insieme un mazzo di Bestie. Riportandocelo, stringerai con la Darkmoon un legame che non verrà dimenticato tanto presto. Permettimi di offrirti una delle carte darkmoon superiori, come piccolo segno del nostro apprezzamento.",
}
T[7908] = {
  title = "Arena Master",
  desc = "Per diventare maestro dell'arena ci vuole per forza qualcosa di più! Magari il Pirata che organizza l'evento a Gurubashi lo saprà!",
  obj = "Parla con Short John Mithril nella Stranglethorn Arena.",
}
T[7926] = {
  title = "La Darkmoon Faire",
  desc = "Sta arrivando la Darkmoon Faire! Quando arriverà in città, non perderti tutte le sue meraviglie e le sue emozioni!$B$BSe ti sbrighi, con questo buono puoi avere biglietti premio gratis! Basta consegnarlo a Gelvas Grimgate, dentro il luna park.$B$BIn questo momento la Fiera è appena fuori da Thunder Bluff, a Mulgore. Non mancare! Vacci oggi stesso!",
  obj = "Consegna il Free Ticket Voucher a Gelvas Grimgate, all'interno del luna park della Darkmoon Faire.",
  progress = "Sì, $Gamico:amica;, posso aiutarti? Hai un buono da riscattare?",
  reward = "$GBenvenuto:Benvenuta; alla Darkmoon Faire! Questo buono vale CINQUE biglietti premio, sì, CINQUE!$B$BQuando avrai messo da parte un po' di biglietti premio, vieni da me e te li cambio con premi preziosi. Più biglietti raccogli, più premi puoi vincere. Urrà!",
  en_title = "The Darkmoon Faire",
  en_obj = "Deliver the Free Ticket Voucher to Gelvas Grimgate, located inside the Darkmoon Faire carnival.",
}
