}
T[7937] = {
  title = "La Tua Fortuna ti Attende...",
  desc = "\"La tua fortuna ti attende a Eastvale.\"$B$BIl biglietto della fortuna che ti ha dato Sayge è appena tiepido al tatto. Stringendolo forte, vedi un'immagine dell'Eastvale Logging Camp, nell'Elwynn Forest; e concentrandoti meglio, nell'immagine scorgi un pagliaio accanto a una stalla.",
  obj = "Vai a Eastvale Logging Camp in Elwynn Forest e cerca la tua fortuna.",
  progress = "Questo pagliaio sembra quello della tua visione.",
  reward = "Frughi in fretta nel pagliaio e trovi una cassetta chiusa a chiave! A quanto pare hai trovato la tua fortuna!",
}
T[7938] = {
  title = "La Tua Fortuna ti Attende...",
  desc = "\"La tua fortuna ti attende nelle Deadmines.\"$B$BIl responso che ti ha dato Sayge è appena caldo al tatto. Lo stringi forte e ti appare un'immagine delle Deadmines, nel villaggio in rovina di Moonbrook, in Westfall. Se ti concentri meglio sull'immagine, ti ritrovi a percorrere passaggi tortuosi fino a un portale scintillante... che porta nel cuore stesso delle miniere. Mentre lo attraversi, dal nulla compare uno strano forziere.",
  obj = "Viaggia fino alle Deadmines in Westfall e cerca la tua fortuna.",
  progress = "Questo forziere sembra quello della tua visione...",
  reward = "Frughi in fretta nel forziere e trovi una cassetta chiusa a chiave! A quanto pare, la tua fortuna l'hai trovata!",
}
T[7939] = {
  title = "Altre Dense Grinding Stones",
  progress = "$N, grazie di tutto l'aiuto che mi hai dato. Non so davvero come ringraziarti!$B$BAnche se non ne ho più così bisogno... se mi porti altre dense grinding stones, ho ancora dei biglietti della Darkmoon Faire per te.",
  reward = "Grazie mille, $N. Ecco i tuoi biglietti della Darkmoon Faire!",
}
T[7940] = {
  title = "1200 Biglietti — Orb of the Darkmoon",
  progress = "Fatti avanti, fatti avanti! Hai biglietti della Darkmoon Faire da riscattare? Basta dirlo! Biglietti di vario taglio, li puoi cambiare con premi meravigliosi e fantastici. Non fare $Gil timido:la timida;, prova e vedrai!",
  reward = "Ecco qua, ecco qua! Un premio da re! Congratulazioni, $Gamico mio:amica mia;!$B$BHai altri biglietti da consegnare? Fammelo sapere! Finché la Darkmoon Faire resta qui, i biglietti te li riscatto io.",
}
T[7941] = {
  title = "Altri Kit per Armature",
  progress = "$N, devo ringraziarti per tutto l'aiuto che mi hai dato. Ho scorte in abbondanza, in buona parte per merito tuo, ma se vuoi portarmi altri kit per armature, te li scambierò volentieri con dei biglietti della Darkmoon Faire.",
  reward = "Ecco a te, $N. Uno scambio equo. Buon divertimento.",
}
T[7942] = {
  title = "Altri Thorium Widgets",
  progress = "$N, sei $Gstato:stata; così gentile con noi: mi hai portato merci senza mai stancarti. Ti sarò eternamente grato!$B$BAnche se non ci servono più tanti Thorium widgets come prima, puoi comunque portarmeli e li scambierò volentieri con biglietti della Darkmoon Faire.",
  reward = "Tieni, $N. Ecco dei biglietti della Darkmoon Faire per divertirti. E non spenderli tutti in una volta, come si suol dire!",
}
T[7943] = {
  title = "Altri Occhi di Pipistrello",
  progress = "$N, l'attrazione che sto progettando sarà la cosa più spaventosa da quando Gnomeregan è stata invasa! E gran parte del merito va a te e a tutti i gingilli che mi hai procurato. Grazie infinite!$B$BNon mi serve molto altro, ma... se mi porti altri evil bat eyes dai pipistrelli delle Eastern Plaguelands... potrei avere ancora dei biglietti della Darkmoon Faire per te.",
  reward = "Grazie ancora, $N. Ecco i tuoi biglietti!",
}
T[7944] = {
  title = "La Tua Fortuna ti Attende...",
  desc = "\"La tua fortuna ti attende nelle Wailing Caverns.\"$B$BAl tatto, la predizione che ti ha consegnato Sayge è leggermente calda. La stringi forte e ti appare l'immagine di una grotta a sud-ovest del Crossroads, nelle Barrens. Ti concentri meglio su ciò che vedi e percorri passaggi tortuosi fino a un portale scintillante... che porta nel cuore stesso delle caverne. Appena lo attraversi, dal nulla compare uno strano forziere.",
  obj = "Raggiungi Wailing Caverns in Barrens e cerca la tua fortuna.",
  progress = "Questo forziere somiglia a quello della tua visione...",
  reward = "Frughi in fretta nel forziere e ci trovi dentro una cassetta di sicurezza! A quanto pare, hai trovato la tua fortuna!",
  en_title = "Your Fortune Awaits You...",
  en_obj = "Travel to the Wailing Caverns in the Barrens and seek out your fortune.",
}
T[7945] = {
  title = "La Tua Fortuna ti Attende...",
  desc = "\"La tua fortuna ti attende fuori dalla Palemane Rock.\"$B$BIl responso che ti ha dato Sayge è appena caldo al tatto. Lo stringi forte e ti appare un'immagine della Palemane Rock di Mulgore. Se ti concentri meglio sull'immagine, vicino all'ingresso della grotta scorgi un ceppo.",
  obj = "Viaggia fino alla Palemane Rock in Mulgore e cerca la tua fortuna.",
  progress = "Questo ceppo sembra quello della tua visione.",
  reward = "Frughi in fretta nel ceppo e trovi una cassetta chiusa a chiave! A quanto pare, la tua fortuna l'hai trovata!",
}
T[7946] = {
  title = "Progenie di Jubjub",
  progress = "Sono così felice che Jubjub non sia più dispersa. Va matta per la birra Dark Iron, e quando l'ho finita... è scappata a cercarne dell'altra!$B$BOra che Jubjub è tornata, voglio tutta la birra che riesco a procurarmi! Guai se scappa di nuovo!$B$BHai un po' di Birra Dark Iron? Se me ne dai un boccale, ti do in cambio un uovo di rana di Jubjub...",
  reward = "Grazie, $N. Eccoti l'uovo! Ci metterà un po' a schiudersi, ma poi avrai un fantastico animale da compagnia!",
}
T[7961] = {
  title = "Conigli Fuwbacchioni!",
  desc = "Questi conigli si moltiplicano senza freni. Bisogna fare qualcosa!$B$BAiutaci, $N, sei la nostra unica speranza.",
  obj = "Uccidi 5 conigli e torna da Jon LeCraft vicino alla forgia sull'Isola dei Designer.",
}
T[7962] = {
  title = "Pewli di Coniglio",
  desc = "Voglio delle pelli di coniglio LeCrafty. Prendine qualcuna dai Conigli LeCrafty.$B$BÈ importante!",
  obj = "Porta 3 Pelli di Coniglio LeCrafty a Jon LeCraft.",
}
T[7981] = {
  title = "1200 Biglietti — Amulet of the Darkmoon",
  progress = "Fatti avanti, fatti avanti! Hai biglietti della Darkmoon Faire da riscattare? Basta dirlo! Biglietti di vario taglio, li puoi cambiare con premi meravigliosi e fantastici. Non fare $Gil timido:la timida;, prova e vedrai!",
  reward = "Ecco qua, ecco qua! Un premio da re! Congratulazioni, $Gamico mio:amica mia;!$B$BHai altri biglietti da consegnare? Fammelo sapere! Finché la Darkmoon Faire resta qui, i biglietti te li riscatto io.",
}
