T[8041] = {
  title = "Forza del Mount Mugamba",
  reward = "Salve, $C. Io sono Jin'rokh the Breaker, troll di Mugamba. Noi della tribù Zandalar riconosciamo le tue imprese, e rendiamo onore alla tua tenacia e alla tua forza di volontà.$B$BPorta al collo questo talismano, $C, e lascia che la forza del Mount Mugamba scorra in tutto il tuo essere. Che ti dia vigore mentre abbatti i nostri nemici!",
}
T[8042] = {
  title = "Forza del Mount Mugamba",
  progress = "Che piacere vederti in buona salute, $N. Le gloriose battaglie che hai combattuto toccano ogni essere vivente di questo pianeta. Hakkar non deve mai uscire dai confini di Zul'Gurub: il mondo crollerebbe di certo sotto la sua fame immensa.$B$BDammi il talismano e ne amplificherò la forza. Usa la Strength of Mugamba per punire i nostri nemici!",
  reward = "Le nostre strade si incroceranno ancora, $C.",
}
T[8043] = {
  title = "Forza del Mount Mugamba",
  progress = "$GMaestro:Maestra; $N, sei $Gtornato:tornata;! Molthor ha fatto sapere al Re delle tue imprese, e il tuo nome lo conoscono persino nei South Seas. Forse un giorno sarai $Gun:una; $C $Gleggendario:leggendaria; — una storia che resterà nei secoli.$B$BDammi il talismano: ne amplificherò il potere ancora una volta.",
  reward = "Distruggi i Gurubashi con la tua nuova forza!",
}
T[8044] = {
  title = "La Rage of Mugamba",
  progress = "King Rastakhan ti manda i suoi saluti, $GMaestro:Maestra; $N. Nessuno, fuori dalla tribù Zandalar, ha mai ricevuto un simile onore.$B$B<Jin'rokh si inchina.>$B$BDammi il talismano e lo potenzierò ancora una volta. E sappi che ora la Rage of Mugamba è legata nel profondo alla tua anima.",
  reward = "Zul'jin ti invidierebbe, $C. Va' e conquista!",
}
T[8045] = {
  title = "L'Heathen's Brand",
  reward = "Sappi questo, $Gpagano:pagana;: è stata una catastrofe a riunirci. Gli Zandalar non capiscono né apprezzano i tuoi costumi pagani, ma siamo un popolo giusto. Porta al collo questo marchio: servirà da monito per i nostri nemici e da simbolo della tua amicizia verso gli Zandalar.$B$BContinua a servire il nostro popolo, e amplificherò il potere del marchio.",
}
T[8046] = {
  title = "L'Heathen's Brand",
  progress = "Forse ho giudicato troppo in fretta, $C. A quanto pare la tua fede cieca in questa Luce vale qualcosa, dopotutto.$B$BDammi il tuo marchio e ne amplificherò il potere.",
  reward = "Fa' quel che devi per sconfiggere i nostri nemici, $C. Anche a costo di incanalare la Luce.$B$B<Jin'rokh rabbrividisce.>",
}
T[8047] = {
  title = "L'Heathen's Brand",
  progress = "Lo confesso, non credevo che avessi la determinazione per portare avanti questa causa fino in fondo, $C. Ora Zandalar ti considera $Gun alleato prezioso:un'alleata preziosa;. Ottimo lavoro, davvero.$B$BDammi il tuo marchio e ne amplificherò il potere ancora una volta.",
  reward = "Abbiamo fedi diverse, ma la nostra causa è giusta. Abbatti i nostri nemici, nobile $C.",
}
T[8048] = {
  title = "L'Hero's Brand",
  progress = "Il Re ha riconosciuto la tua esistenza, $C. Sei $Gil primo:la prima; della tua specie che Rastakhan accetta come $Gvero alleato:vera alleata; di Zandalar.$B$BSarai $Gricompensato:ricompensata; generosamente per i tuoi sforzi. Presenta il tuo marchio e ne amplificherò il potere per l'ultima volta.",
  reward = "Vigilanza, onore, lealtà, coraggio... Sono tutte qualità che tu incarni, e che incarnerà anche il tuo marchio.",
}
T[8049] = {
  title = "The Eye of Zuldazar",
  reward = "Prendi questo talismano, $Gsacerdote:sacerdotessa;: è il segno della nostra gratitudine.$B$BPiù si rafforzerà il tuo legame con i troll di Zandalar, più The Eye of Zuldazar diventerà potente. Torna da me ogni tanto e infonderò potere nel gioiello.",
}
T[8050] = {
  title = "The Eye of Zuldazar",
  progress = "$GBenvenuto:Benvenuta;, $Gsacerdote:sacerdotessa;. The Eye of Zuldazar pulsa di energia: sei $Gpronto:pronta; per il passo successivo. Dammi il talismano e compirò l'infusione.",
  reward = "Continua a combattere il Soulflayer e i suoi servitori, $N. Non dobbiamo mai lasciarlo uscire dai confini di Zul'Gurub.",
}
T[8051] = {
  title = "The Eye of Zuldazar",
  progress = "I venti sussurrano le storie delle tue battaglie contro i Gurubashi, $Gsacerdote:sacerdotessa;, e delle tue gesta cominciano a parlare persino i reali. Si dice che King Rastakhan abbia fatto addirittura il tuo nome.$B$BÈ ora di infondere potere nell'Occhio. Dammi il talismano e ci penserò io.",
  reward = "Resta $Grisoluto:risoluta; nelle tue imprese, $N. Il Soulflayer cercherà di risucchiarti la voglia di vivere.",
}
T[8052] = {
  title = "The All-Seeing Eye of Zuldazar",
  progress = "Se solo avessimo altri diecimila come te, $N. In un batter d'occhio gli eserciti di Hakkar sarebbero dispersi al vento.$B$B<Al'tabim sospira.>$B$BAhimè, l'Occhio è pronto a sprigionare tutto il suo potenziale. Dammelo.",
  reward = "Colpiscili tutti, e che Hakkar riconosca i suoi...",
}
T[8053] = {
  title = "Paragoni del Potere: I Parabracci del Libero Pensatore",
  desc = "Sei $Gun pagano:una pagana;. Nella tribù c'è posto per i pagani. I pagani sono i liberi pensatori di Zandalar. I liberi pensatori non temono l'oppressione. I liberi pensatori muoiono per ciò in cui credono. Sappiamo che tu moriresti per ciò in cui credi. Per questo hai il nostro riconoscimento. Per questo hai la possibilità di dimostrare ancora quanto vali.$B$BCi servono i Paragoni del Potere. Va' a Zul'Gurub. Uccidi i servitori di Hakkar. Torna quando avrai quello che cerco. Reclama il primo equipaggiamento da battaglia di un libero pensatore di Zandalar.$B$BVa'.",
  obj = "Porta a Jin'rokh the Breaker le Primal Hakkari Bindings. Devi anche avere una reputazione pari o superiore ad Amichevole con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova su Yojamba Isle, Stranglethorn Vale.",
  progress = "Sei $Gtornato:tornata;? Hai i Paragoni del Potere? Mi stai facendo perdere tempo?$B$BSpero di no, $Gpagano:pagana;.",
  reward = "Ci fai molto onore. Hai le mani che grondano del sangue dei servitori di Hakkar. Sei $Gun amico:un'amica; della tribù.$B$BIndossa questi bracciali. Sono i parabracci del libero pensatore. Ecco cosa intendo per vero potere.",
}
T[8054] = {
  title = "Paragoni del Potere: La Cintura del Libero Pensatore",
  desc = "Le tue credenze ci sono estranee, $Gpagano:pagana;. Un tempo gli antichi Zandalar furono marchiati come eretici. Era il tempo in cui il Gurubashi Empire era forte. I pagani osarono sfidare il sacerdote di Hakkar. Allora i pagani furono cacciati e uccisi come parassiti. Quei pagani non vacillarono mai nella lotta contro il Dio del Sangue. Onoriamo il prezzo che pagarono. Loro sono i liberi pensatori.$B$BDistruggi i servitori di Hakkar a Zul'Gurub. Portami i Paragoni del Potere che cerco. Se ci riuscirai, la ricompensa sarà generosa.$B$BVa'.",
  obj = "Porta a Jin'rokh the Breaker un Primal Hakkari Shawl. Devi anche avere una reputazione pari o superiore a Onorato con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova su Yojamba Isle, Stranglethorn Vale.",
  progress = "Se sei qui, vuol dire vittoria? Hai i Paragoni? Grondi dei resti dei tuoi nemici?",
  reward = "Il tuo onore nella tribù è assicurato. A Zul'Gurub hai fatto molte vittime. I nemici cadono davanti alle tue convinzioni. I nemici cadono davanti al tuo potere.$B$BQuesta è la cintura del libero pensatore. È un simbolo d'onore. È un mojo potente. Ora è tua.",
}
T[8055] = {
  title = "Paragoni del Potere: La Corazza del Libero Pensatore",
  desc = "Nella tribù, l'equipaggiamento da battaglia ti dà potere. È così che si onorano i liberi pensatori. Sono fanatici: nelle loro corazze mettono mojo potente. Se davanti al nemico il loro credo vacilla, la corazza no.$B$BPer avere una corazza così devi essere $Gvenerato:venerata; fra noi. Va' a Zul'Gurub e prendi i Paragoni del Potere che mi servono. Prendili agli stolti là dentro, nel modo più doloroso, e portameli. Dimostra una volta per tutte quanto vali come $Glibero pensatore:libera pensatrice;.",
  obj = "Porta a Jin'rokh the Breaker una Primal Hakkari Tabard. Devi anche avere una reputazione pari o superiore a Venerato con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova su Yojamba Isle, Stranglethorn Vale.",
  progress = "Hai i Paragoni? Hanno del mojo dentro, e ci servono. Ci aiuterai.",
  reward = "Hai fatto quello che pochi sono mai riusciti a fare. Hai messo in ginocchio i servitori di Hakkar e hai mostrato loro di cosa è capace un libero pensatore. A noi hai mostrato che un eretico può essere venerato nella tribù. Non hai solo il vero potere. Tu SEI il vero potere.$B$BPrendi la corazza, $Glibero pensatore:libera pensatrice;. Schiaccia chi ti si oppone.",
}
T[8056] = {
  title = "Paragoni del Potere: I Bracciali dell'Augure",
  desc = "Gli àuguri della nostra tribù sono venerati per il dono della vista divina, mon. Non sono stregoni: passano il tempo a gettare le ossa o a leggere le foglie in cerca di responsi — non a lanciare malocchi alla gente. Da $Gsciamano:sciamana;, del potere degli auspici sai già qualcosa; noi Zandalar teniamo molto alle intuizioni che danno alla tribù.$B$BPortami un'offerta di Paragoni del Potere da dentro Zul'Gurub e facci vedere quanto vali. Se lo fai per noi, ti darò dei bracciali che per i nostri àuguri valgono più di qualunque altro!",
  obj = "Porta a Maywiki of Zuldazar i Primal Hakkari Armsplint. Devi anche avere una reputazione pari o superiore ad Amichevole con la Zandalar Tribe.$B$BMaywiki of Zuldazar si trova su Yojamba Isle, Stranglethorn Vale.",
  progress = "Ce li hai i Paragoni del Potere di Zul'Gurub che mi servono? Questi bracciali valgono tutta la fatica che ti costeranno!",
  reward = "Pare che dentro di te ci sia un po' dell'augure Zandalar. Sappiamo delle imprese che hai compiuto per noi a Zul'Gurub, mon. Questi Paragoni del Potere saranno di grande aiuto alla tribù Zandalar — una tribù, aggiungo, a cui puoi rivolgerti come ad amici. Prendi questi bracciali, $N: te li sei guadagnati, e anche di più!",
}
T[8057] = {
  title = "Paragoni del Potere: I Bracciali dell'Aruspice",
  desc = "Gli aruspici sono membri fondamentali della nostra tribù; faresti bene a dare ascolto ai loro presagi. Entrano in comunione con gli animali e, quando serve, li offrono agli spiriti: così ci danno una guida divina. In passato l'intuito e la saggezza dell'aruspice ci hanno dato un vantaggio nelle guerre contro le tribù divise dei Gurubashi.$B$BPortami un'offerta di Paragoni del Potere da dentro Zul'Gurub e facci vedere quanto vali. Se lo fai, ti darò dei bracciali che ogni aruspice degli Zandalar vorrebbe avere.",
  obj = "Porta a Maywiki of Zuldazar un Primal Hakkari Stanchion. Devi anche avere una reputazione pari o superiore ad Amichevole con la Zandalar Tribe.$B$BMaywiki of Zuldazar si trova su Yojamba Isle, Stranglethorn Vale.",
  progress = "Ce li hai i Paragoni del Potere di Zul'Gurub? Questi bracciali ripagano la fatica, $N. Fidati, mon!",
  reward = "Ah, lo sento il potere che esce da questi Paragoni del Potere, $N. Hai dimostrato di essere qualcuno che noi della tribù possiamo chiamare \"$Gamico:amica;\". Un patto è un patto, $N... ecco a te il potere dei bracciali dell'aruspice!",
}
T[8058] = {
  title = "Paragoni del Potere: I Bracciali del Giustificatore",
  desc = "La vendetta è potere, e il giustificatore degli Zandalar è quel potere. La tribù ha molti nemici, e il giustificatore li punisce. Nessun crimine contro di noi resta impunito: la pena la infligge il giustificatore. I nostri nemici temono la nostra vendetta, e fanno bene. La temeranno per sempre.$B$BDiventa $Guno:una; dei nostri giustificatori. Cerca i Paragoni del Potere dentro Zul'Gurub, uccidi i servitori di Hakkar e compi la vendetta in nome della tribù. Sarai $Gricompensato:ricompensata;.",
  obj = "Porta a Jin'rokh the Breaker i Primal Hakkari Armsplint. Devi anche avere una reputazione pari o superiore ad Amichevole con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova su Yojamba Isle, Stranglethorn Vale.",
  progress = "Hai portato i Paragoni del Potere? Hai compiuto la vendetta degli Zandalar?",
  reward = "Oggi hai seminato molta vendetta. Hai preso l'aspetto del giustificatore e hai messo in ginocchio i servitori del Dio del Sangue.$B$BPrendi questo: in futuro alimenterà la tua vendetta. Ora sei $Gamico:amica; degli Zandalar.",
}
T[8059] = {
  title = "Paragoni del Potere: Le Fasce del Demoniaco",
  desc = "Quando hanno a che fare con i demoni, gli stregoni camminano su un terreno pericoloso, ma i nostri demoniaci si spingono ancora più in là. Con un rituale antico e arcano lasciano che un demone entri in loro; ma invece di farsi possedere, lo rendono schiavo dall'interno, assorbono il potere della bestia e lo piegano al proprio comando. Sono pochi quelli che riescono a padroneggiare un'impresa simile.$B$BPerché tu possa conoscere il potere del demoniaco, mi servono dei Paragoni del Potere da Zul'Gurub. Vai là e recupera quello che cerchiamo.",
  obj = "Porta ad Al'tabim the All-Seeing un Primal Hakkari Stanchion. Devi anche avere una reputazione pari o superiore ad Amichevole con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova a Yojamba Isle, Stranglethorn Vale.",
  progress = "Sei $Gtornato:tornata; con i Paragoni del Potere? Se sconfiggerai i servitori diabolici di Hakkar, non ci darai solo prova del tuo valore, ma dimostrerai anche di voler imparare le vie del demoniaco.",
  reward = "Ben fatto... prima di cedere i Paragoni del Potere avranno di certo pagato in modi atroci. Prendi queste — le fasce del demoniaco. Sono fatte con il powerful mojo che si usa per evocare la preda del demoniaco, e per acquisire potere sono uno strumento potente.",
}
T[8060] = {
  title = "Paragoni del Potere: Le Fasce dell'Illusionista",
  desc = "Da noi i maghi della tribù si chiamano illusionisti. Nei loro incantesimi usano un mojo potente, che spesso stordisce e confonde i nemici della tribù!$B$B<Al'tabim ride malvagiamente.>$B$BVedere all'opera un potente illusionista è proprio uno spettacolo: mette in ginocchio i nostri nemici con la loro stessa follia!$B$BSe vuoi conoscere la via dei nostri illusionisti, va' a Zul'Gurub e riportami i Paragoni del Potere che ti chiedo. In cambio avrai le fasce da braccio con cui i nostri illusionisti tessono gli incantesimi.",
  obj = "Porta ad Al'tabim the All-Seeing le Primal Hakkari Bindings. Devi anche avere una reputazione pari o superiore ad Amichevole con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova su Yojamba Isle, in Stranglethorn Vale.",
  progress = "$N — sei già $Gtornato:tornata;? Ce l'hai fatta a prendere i Paragoni del Potere che mi servono?",
  reward = "Notevole... hai sentito il mojo che ci scorre dentro? Ai tempi in cui il Gurubashi Empire dominava queste terre, i Paragoni del Potere si usavano come una specie di moneta. Ora noi Zandalar useremo il mojo latente che c'è dentro per combattere la seconda ascesa del Blood God Hakkar!$B$BOggi hai fatto un buon lavoro — sappi che fra gli Zandalar hai un amico. E per questo, ecco le fasce da illusionista che ti avevo promesso!",
}
T[8061] = {
  title = "Paragoni del Potere: Le Fasce del Confessore",
  desc = "Noi Zandalar diamo potere a chi parla con l'autorità del divino. I nostri sacerdoti non sono solo guaritori — sono i nostri confessori. Il male arriva da fuori — come Hakkar — ma anche da dentro la tribù. I nostri confessori fanno da giudici fra di noi, e ci preservano dallo stesso male che ha divorato i Gurubashi dall'interno.$B$BVa' a Zul'Gurub e riporta i Paragoni del Potere dei Gurubashi. Impara cosa vuol dire essere il confessore, e preservaci dal male.",
  obj = "Porta ad Al'tabim the All-Seeing un Primal Hakkari Stanchion. Devi anche avere una reputazione pari o superiore ad Amichevole con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova su Yojamba Isle, in Stranglethorn Vale.",
  progress = "Sei $Gtornato:tornata; da Zul'Gurub, eh? Ce l'hai fatta a recuperare i Paragoni del Potere dai servitori di Hakkar?",
  reward = "Eccezionale, $N! Portarmeli non è stata un'impresa da poco. Oggi, non c'è dubbio, hai fatto da confessore della nostra tribù e ci hai preservati dalla minaccia di Hakkar. Queste fasce sono degne di $Gun amico:un'amica; della tribù come te!",
}
T[8062] = {
  title = "Paragoni del Potere: I Bracciali del Predatore",
  desc = "Nei tempi bui seguiti alla caduta del Gurubashi Empire, erano i predatori Zandalar a sfamare la tribù con la loro abilità. I cacciatori dicono di somigliare molto ai predatori della nostra tribù — chi cerca la caccia incarna l'essenza del predatore, sì. Ma sarà la tua caccia a Zul'Gurub a mostrarci quanto vali davvero in confronto ai nostri migliori predatori.$B$BPortami un po' dei Paragoni del Potere di Zul'Gurub, e muoverai i primi passi per diventare il predatore supremo.",
  obj = "Porta i seguenti Paragoni del Potere da Zul'Gurub a Falthir the Sightless: le Primal Hakkari Bindings. Devi anche avere una reputazione pari o superiore ad Amichevole con la Zandalar Tribe.$B$BFalthir the Sightless si trova su Yojamba Isle, a Stranglethorn Vale.",
  progress = "Dai la caccia a chi custodisce i Paragoni del Potere a Zul'Gurub, $N. Sono loro la tua preda, e hanno quello che serve a tutti e due.",
  reward = "Sì... non ho bisogno della vista per sentire la presenza dei Paragoni del Potere. Molti nella tribù sono rimasti colpiti dal tuo successo a Zul'Gurub. Per noi sei $Gun amico:un'amica; degli Zandalar, e non solo: ti riteniamo anche abbastanza $Gdegno:degna; da possedere i bracciali del predatore — oggetti potenti, e simbolo di cosa significa essere un predatore. Ben fatto, $N.",
}
T[8063] = {
  title = "Paragoni del Potere: I Bracciali dello Svitato",
  desc = "Gli svitati degli Zandalar somigliano ai ladri, ma più di tutto abbracciano la follia... il caos... l'imprevedibilità dell'esistenza. Erano terrificanti sul campo di battaglia, e nei tempi selvaggi dopo la divisione delle tribù hanno seminato confusione e scompiglio tra i nostri nemici. Senza di loro oggi non saremmo qui.$B$BPortami i Paragoni del Potere di Zul'Gurub che cerco, e avrai da me la prima delle preziose armature dello svitato. Abbraccia la follia!",
  obj = "Porta a Falthir the Sightless i Primal Hakkari Armsplint. Devi anche avere una reputazione pari o superiore ad Amichevole con la Zandalar Tribe.$B$BFalthir the Sightless si trova su Yojamba Isle, a Stranglethorn Vale.",
  progress = "Cerca la follia dentro Zul'Gurub e oscurala con la tua, $N! Se lo fai avrai successo, e chi ha successo ha la sua ricompensa! Che il Dio del Sangue non regni mai più sovrano!",
  reward = "Ben fatto, $N... con le tue imprese a Zul'Gurub ti sei $Gguadagnato:guadagnata; il diritto di chiamare amica la tribù Zandalar. Ai Paragoni ci penso io; tu accetta questa ricompensa per il tuo impegno!",
}
T[8064] = {
  title = "Paragoni del Potere: La Cintura dell'Aruspice",
  desc = "Noi Zandalar le vie dei druidi non le conosciamo: la natura va piegata ai nostri bisogni, non il contrario. Eppure fra noi è l'aruspice il più in sintonia con la natura, ed è giusto così. Chi fa rendere l'anima a una bestiola sa cosa vuol dire essere una di loro. È questo il vero potere della natura.$B$BPortami un'offerta di Paragoni del Potere da dentro Zul'Gurub, per dimostrarci quanto vali. Se lo fai, ti darò un oggetto potente — una cintura usata da molti aruspici degli Zandalar.$B$BMojo forte, mon!",
  obj = "Porta a Maywiki of Zuldazar una Primal Hakkari Sash. Maywiki of Zuldazar si trova su Yojamba Isle, Stranglethorn Vale. Devi anche essere Onorato con gli Zandalar.",
  progress = "Ce li hai i Paragoni del Potere di Zul'Gurub che mi servono? Se ce li hai, la cintura dell'aruspice sarà tua.",
  reward = "Ti ringrazio — puoi giurarci, il potere nascosto in questi oggetti sarà già da solo un tesoro. Non hai solo fatto quello che ti ho chiesto: per noi della tribù ti sei anche $Gdimostrato:dimostrata; $Gdegno:degna; d'onore. Come promesso, ecco la tua ricompensa!",
}
T[8065] = {
  title = "Paragoni del Potere: La Tunica dell'Aruspice",
  desc = "Quello che un aruspice indossa è il simbolo supremo del suo potere, $N. Fra i suoi abiti è la tunica a rappresentare il legame fra lui e la saggezza divina che cerca. Spesso ci intesse parti delle bestiole che sacrifica, e così si ricorda di ciò che lo lega ai suoi doni.$B$BPortami un'offerta di Paragoni del Potere da dentro Zul'Gurub e dimostraci quanto vali. Se lo fai, sarà tua una tunica che trasuda il vero potere di un aruspice.",
  obj = "Porta a Maywiki of Zuldazar una Primal Hakkari Tabard. Maywiki of Zuldazar si trova su Yojamba Isle, Stranglethorn Vale. Devi anche essere Riverito con gli Zandalar.",
  progress = "Ce li hai i Paragoni del Potere di Zul'Gurub che servono? La tunica dell'aruspice vale tutta la fatica che ti costerà.",
  reward = "Notevole... hai raccolto i Paragoni del Potere che servivano, $N. Le tue imprese a Zul'Gurub per gli Zandalar sono leggendarie; d'ora in poi nella tribù sarai $Griverito:riverita;. Ecco la tua tunica, possente $C!",
}
T[8066] = {
  title = "Paragoni del Potere: La Cintura del Predatore",
  desc = "Un predatore sa braccare la preda, ma quello che vince sa anche colpirla quando le si è fatto sotto. Devi padroneggiare tutte e due le cose, se vuoi avere qualche speranza di riuscire a Zul'Gurub... e di diventare come i predatori Zandalar.$B$BPortami le parti migliori dei Paragoni del Potere da Zul'Gurub. A me andrà in premio il potere che sprigionano quei ninnoli, a te la cintura del predatore Zandalar — un equipaggiamento che vale bene lo scambio.",
  obj = "Porta i seguenti Paragoni del Potere da Zul'Gurub a Falthir the Sightless: un Primal Hakkari Shawl. Devi anche avere una reputazione pari o superiore a Onorato con la Zandalar Tribe.$B$BFalthir the Sightless si trova su Yojamba Isle, a Stranglethorn Vale.",
  progress = "Colpisci i folli servitori di Hakkar a Zul'Gurub — i Paragoni del Potere li hanno loro, $N. Dimostra a loro — e alla tribù — che sai vincere, da aspirante predatore.",
  reward = "Ho sentito il tuo arrivo qualche istante fa, $N, ma con fatica. A rivelarmi che eri qui sono stati i Paragoni del Potere che hai portato. Non ho bisogno di vedere i ninnoli per sentirne il potere; il loro mojo latente — magia grezza, se vuoi — continuerà ad alimentare i nostri sforzi per sventare i piani diabolici del Blood God Hakkar.$B$BPer il tuo successo meriti di essere $Gelogiato:elogiata; — e $Gricompensato:ricompensata;. Nella tribù sei $Gonorato:onorata;, e $Gdegno:degna; di indossare la cintura del predatore.",
}
T[8067] = {
  title = "Paragoni del Potere: Il Mantello del Predatore",
  desc = "Noi Zandalar teniamo molto a ciò che indossiamo come simbolo dei nostri traguardi. Per sentire cosa emana da ciò che uno indossa non serve vederlo — il potere va oltre la vista. Così sono le vesti del predatore Zandalar, e quella a cui i predatori tengono di più è il mantello. Li aiuta a sparire alla vista... e a far sentire la loro presenza quando lo vogliono.$B$BI Paragoni del Potere ti aspettano a Zul'Gurub. Portami quello che cerco, e il mantello del predatore sarà tuo.",
  obj = "Porta i seguenti Paragoni del Potere da Zul'Gurub a Falthir the Sightless: una Primal Hakkari Aegis. Devi anche avere una reputazione pari o superiore a Reverito con la Zandalar Tribe.$B$BFalthir the Sightless si trova su Yojamba Isle, a Stranglethorn Vale.",
  progress = "Sono andate bene, le tue incursioni a Zul'Gurub, $N? Solo quando mi avrai portato quello che cerco — e avrai dato piena prova di te alla tribù — ti guadagnerai un mantello che non ha uguali tra gli Zandalar.",
  reward = "Successo... nella tribù meriti di essere $Griverito:riverita;, $N. Ottenere i Paragoni del Potere che servivano per il mantello non è stata un'impresa da poco, ma l'hai affrontata come il più letale dei nostri predatori. Ti sei $Gguadagnato:guadagnata; il tuo posto tra loro, e di certo anche il diritto di indossare il loro mantello.",
}
T[8068] = {
  title = "Paragoni del Potere: Il Mantello dell'Illusionista",
  desc = "La magia è una forza grezza e primordiale, e solo chi è abbastanza forte riesce a plasmarla. Il mojo è la nostra estensione di questo potere, e un modo efficace per manipolarlo è l'illusione. Come si fa a sperare davvero di vincere contro un nemico che in realtà non c'è nemmeno? Noi Zandalar questo potere lo conosciamo, ed è per questo che nella tribù gli illusionisti hanno un posto d'onore.$B$BPrendi a Zul'Gurub i Paragoni del Potere che servono — in cambio avrai l'onore della tribù e un mantello potente, di quelli che portano i nostri migliori illusionisti!",
  obj = "Porta ad Al'tabim the All-Seeing un Primal Hakkari Shawl. Devi anche avere una reputazione pari o superiore a Onorato con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova su Yojamba Isle, in Stranglethorn Vale.",
  progress = "Com'è andata la tua incursione a Zul'Gurub? I tuoi nemici li hai fatti impazzire con il potere dell'illusione? Illusione o no, la loro morte — e i Paragoni del Potere che gli hai preso — aiuteranno a sventare l'ascesa di Hakkar.",
  reward = "Successo! Da ora in poi nella tribù sarai $Gonorato:onorata;! Oggi, grazie a te, $N, Zul'Gurub ha di certo assaggiato la forza degli Zandalar.$B$BCon la benedizione della tribù, prendi il mantello da illusionista degli Zandalar. Che ti serva bene.",
}
T[8069] = {
  title = "Paragoni del Potere: Le Vesti dell'Illusionista",
  desc = "Nella tribù il rango e il potere si riconoscono da quello che indossiamo. Le nostre vesti sono fatte con i materiali più pregiati e intessute del mojo con cui ci rendiamo potenti. Gli illusionisti non fanno eccezione: si dice che nell'aspetto le loro vesti racchiudano l'essenza stessa dell'illusione, e secondo la leggenda le loro vesti antiche non si presentavano mai uguali due volte.$B$BTi darò una veste da illusionista, $N... ma prima guadagnati un posto riverito nella tribù! Portami i Paragoni del Potere da Zul'Gurub!",
  obj = "Porta ad Al'tabim the All-Seeing una Primal Hakkari Kossack. Devi anche avere una reputazione pari o superiore a Riverito con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova su Yojamba Isle, in Stranglethorn Vale.",
  progress = "Sei $Gtornato:tornata; con i Paragoni del Potere che ci servono? Lo so che non sarà facile... ma è da tempo che ho predetto l'arrivo di uno straniero che ci avrebbe aiutati nella lotta contro Hakkar. Che sia tu, dico io!",
  reward = "Finalmente qualcuno $Gdegno:degna; di indossare la veste da illusionista! Il tuo successo a Zul'Gurub ti ha assicurato la riverenza della tribù per le ere a venire. Indossala con orgoglio, $N!",
}
T[8070] = {
  title = "Paragoni del Potere: I Bracciali del Confessore",
  desc = "Poco dopo la caduta dei Gurubashi, noi Zandalar siamo stati quasi sconfitti per sempre dal male nato nella nostra stessa tribù. È stato allora che fra noi sono sorti i confessori: hanno salvato la tribù bandendo chi voleva distruggere la propria gente. E non ci tengono solo in armonia con gli spiriti, ma preservano anche la carne.$B$BVa' a Zul'Gurub e guarda con i tuoi occhi la depravazione di Hakkar e dei Gurubashi. Strappa loro i Paragoni del Potere che cerchiamo: se ci riesci, avrai la tua ricompensa!",
  obj = "Porta ad Al'tabim the All-Seeing una Primal Hakkari Sash. Devi anche avere una reputazione pari o superiore a Onorato con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova su Yojamba Isle, in Stranglethorn Vale.",
  progress = "I Paragoni del Potere... ce li hai? Solo quando li avremo potremo usare la forza latente racchiusa al loro interno. Sarà bello ribaltare la situazione contro i servitori del Dio del Sangue...",
  reward = "Successo! Questi ci aiuteranno parecchio a rafforzare il nostro potere contro l'ascesa di Hakkar. Grazie a te abbiamo fatto un passo importante per essere sicuri che il Dio del Sangue non ci distrugga tutti.$B$BOggi ti sei $Gguadagnato:guadagnata; l'onore della tribù, $N. Prendi questi — i bracciali del confessore — in segno di gratitudine.",
}
T[8071] = {
  title = "Emblemi del Potere: Il Mantello del Confessore",
  desc = "Tutti i confessori degli Zandalar portano un mantello particolare, il segno che sono i custodi della tribù. Questi mantelli sono intessuti di powerful mojo, che li aiuta a giudicare chi ci minaccia. Anche tu, come $Gsacerdote:sacerdotessa;, devi passare il tempo a giudicare chi è degno e chi no: un mantello così sarebbe di sicuro una benedizione per te.$B$BCombatti i servitori di Hakkar a Zul'Gurub, portami gli Emblemi del Potere che cerco, e in cambio ti darò un mantello degno dei nostri migliori confessori.",
  obj = "Porta ad Al'tabim the All-Seeing una Primal Hakkari Aegis. Devi anche avere una reputazione pari o superiore a Riverito con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova su Yojamba Isle, a Stranglethorn Vale.",
  progress = "Hai gli Emblemi del Potere di Zul'Gurub?",
  reward = "Ben fatto, $N — grazie a te, oggi i servitori di Hakkar hanno di certo assaggiato la vendetta degli Zandalar. Con quello che hai fatto ti sei $Gguadagnato:guadagnata; per sempre un posto riverito nella tribù. Ti prego, fai tuo questo mantello da confessore, con la nostra benedizione!",
}
T[8072] = {
  title = "Paragoni del Potere: Il Mantello dello Svitato",
  desc = "Uno degli svitati leggendari degli Zandalar è stato Khar'vaxal the Cracked. La leggenda narra che, la prima volta che ha affrontato i nemici della tribù, Kar'xavan ha indossato un mantello tessuto apposta con \"la trama della follia\". Ad avvolgerne la figura non c'era solo il mantello, ma anche la velocità accecante dei suoi due pugnali. Oggi gli svitati tengono al mantello come al segno del loro posto nella tribù.$B$BPortami i Paragoni del Potere che cerco, e avrai un mantello simile, per tessere follia contro i tuoi nemici.",
  obj = "Porta a Falthir the Sightless un Primal Hakkari Girdle. Devi anche avere una reputazione pari o superiore a Onorato con la Zandalar Tribe.$B$BFalthir the Sightless si trova su Yojamba Isle, a Stranglethorn Vale.",
  progress = "Sei $Gtornato:tornata; — hai i Paragoni del Potere che mi servono?$B$BAncora oggi la leggenda di Khar'vaxal the Cracked ci ricorda che nessun nemico — per quanto grande sia la minaccia — è impossibile da sconfiggere. Il caos metterà tutti in ginocchio, questo è certo... e forse anche gli elementi meno caotici del caos.",
  reward = "Oggi la vittoria è nostra, grazie alla follia che hai seminato tra i nostri comuni nemici! Tra gli Zandalar meriti di essere $Gonorato:onorata;, e per mostrarti gratitudine per le tue imprese non c'è modo migliore che offrirti il mantello dello svitato!",
}
T[8073] = {
  title = "Paragoni del Potere: La Tunica del Folle",
  desc = "Gli occhi mi hanno lasciato tanto tempo fa, ma non mi mancano. Anche in una tribù come la nostra — dove le vesti dicono il rango e lo scopo di chi le porta — l'abito più potente sprigiona un potere che i semplici occhi non riescono a vedere. La preziosa tunica del folle Zandalar non fa eccezione: ne esce il potere puro del caos e della follia, quello che i folli sanno incanalare.$B$BI Paragoni del Potere che mi servono si trovano a Zul'Gurub; portami quello che cerco e avrai in ricompensa una tunica leggendaria tutta tua... degna di $Gun tessitore:una tessitrice; di follia.",
  obj = "Porta a Falthir the Sightless una Primal Hakkari Aegis. Devi anche avere una reputazione pari o superiore a Riverito con la Zandalar Tribe.$B$BFalthir the Sightless si trova su Yojamba Isle, Stranglethorn Vale.",
  progress = "$GBentornato:Bentornata; sull'Isola, $N... arrivi in trionfo con i Paragoni del Potere?",
  reward = "Impressionante... oggi hai fatto quello che in pochi credevano possibile. Nella tribù sarai $Griverito:riverita; per tutta la vita, $N, questo è sicuro. Ti sei $Gguadagnato:guadagnata; il diritto di indossare la tunica del folle — portala con la nostra benedizione.",
}
T[8074] = {
  title = "Paragoni del Potere: La Cintura dell'Augure",
  desc = "Gli àuguri conoscono il mojo degli elementi, mon, e lo usano per guidare la tribù verso la gloria. Nei giorni bui, dopo che il Gurubashi Empire si è fatto a pezzi da solo, sono stati i nostri àuguri a condurci a un rifugio sicuro nei South Seas. E sono stati sempre loro a riportarci qui nella Valle, dritti nel cuore del male che ribolle a Zul'Gurub.$B$BPortami un'offerta di Paragoni del Potere da dentro Zul'Gurub e dimostraci quanto vali. Se lo fai, ti darò una cintura che usano i nostri àuguri — una con dentro un mojo potente!",
  obj = "Porta a Maywiki of Zuldazar un Primal Hakkari Girdle. Devi anche avere una reputazione pari o superiore a Onorato con la Zandalar Tribe.$B$BMaywiki of Zuldazar si trova su Yojamba Isle, Stranglethorn Vale.",
  progress = "Mi servono i Paragoni del Potere, mon — nella nostra lotta contro il male di Zul'Gurub ne tireremo fuori tutto il potere. Ce li hai?",
  reward = "Ti sento addosso l'odore del male sconfitto, $N. È un odore dolce, mon... e credo che tu lo conosca molto bene.$B$BLo so che portarmi i Paragoni del Potere che servono per la cintura non è un'impresa da poco. Le tue gesta non hanno solo onorato la tribù: ti hanno anche reso onore fra la mia gente. Ecco qua — prendi la cintura dell'augure e indossala come tua!",
}
T[8075] = {
  title = "Paragoni del Potere: L'Usbergo dell'Augure",
  desc = "Tutti gli àuguri degli Zandalar portano un pettorale tutto loro, che si chiama usbergo: è rifinito con le sete e le stoffe più pregiate, intrecciate a una robusta maglia metallica. È il simbolo della loro divinità, mon, ma anche della loro autorità. E mettersi contro chi ha passato la vita a parlare con gli spiriti non è mai saggio...$B$BDimostraci quanto vali: portami da dentro Zul'Gurub un'offerta dei Paragoni del Potere, e da me avrai uno degli usberghi più belli che i nostri àuguri possano mai sperare di indossare!",
  obj = "Porta a Maywiki of Zuldazar una Primal Hakkari Tabard. Devi anche avere una reputazione pari o superiore a Reverito con la Zandalar Tribe.$B$BMaywiki of Zuldazar si trova a Yojamba Isle, Stranglethorn Vale.",
  progress = "I Paragoni del Potere sono una fonte essenziale di potere magico — proprio quello che ci vuole per fare l'usbergo dell'augure. Portami ciò che mi serve e potrò darti le vesti più belle che un àugure Zandalar possa volere per sé.",
  reward = "So cosa hai passato per portarmi i Paragoni del Potere, $N. Non è stato facile, mon — sconfiggere il male che trasuda da Zul'Gurub come melma schifosa — ma ora che è tutto finito te lo posso dire con sicurezza: fra gli Zandalar sarai $Greverito:reverita; per secoli e secoli!$B$BEcco — prendi l'usbergo dell'augure e portalo con orgoglio!",
}
T[8076] = {
  title = "Emblemi del Potere: Il Mantello del Demoniaco",
  desc = "Il demoniaco non cerca solo di possedere il potere, ma di incarnarlo in pieno. Più di uno dei nostri demoniaci ha perso lo scontro con un demone, ma con i nemici che ci minacciano — soprattutto a Zul'Gurub — il potere che un demoniaco riesce a scatenare sui nostri avversari vale il sacrificio. Per sopravvivere dobbiamo schiacciare chi vuole distruggerci: ce l'ha insegnato la caduta del Gurubashi Empire.$B$BVa' a Zul'Gurub e procurati gli Emblemi del Potere che ci servono. Se lo fai, un prezioso oggetto da demoniaco sarà tuo.",
  obj = "Porta ad Al'tabim the All-Seeing una Primal Hakkari Sash. Devi anche avere una reputazione pari o superiore a Onorato con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova su Yojamba Isle, a Stranglethorn Vale.",
  progress = "Hai recuperato gli Emblemi del Potere di Zul'Gurub? Il potere latente di questi oggetti lo prenderemo noi e lo faremo nostro, ma se ce la farai, in cambio avrai un potere tutto tuo...",
  reward = "Ben fatto, $N. Gli Emblemi del Potere di Zul'Gurub dovrebbero ricordare quanto potere è andato sprecato. Al loro apice i Gurubashi erano forti, ma si sono lasciati consumare da quella stessa forza. Un demoniaco sa che il suo è un gioco molto simile, eppure spesso per sopravvivere serve proprio il potere scatenato.$B$BUsa questo mantello da $Galleato onorato:alleata onorata; degli Zandalar... ti sarà utile.",
}
T[8077] = {
  title = "Emblemi del Potere: Le Vesti del Demoniaco",
  desc = "Nella tribù il simbolo supremo del potere è l'abito che portiamo in battaglia. Le vesti di un demoniaco uniscono in un solo tessuto runecloth pregiata e mojo dalla potenza devastante. Si dice che l'aspetto della veste spaventi chiunque la veda... soprattutto i demoni che il demoniaco finirà per dominare.$B$BDevi portarmi da Zul'Gurub una serie ben precisa di Emblemi del Potere. Sarà difficile... ma se ce la farai, di sicuro avrai una veste tutta per te.",
  obj = "Porta ad Al'tabim the All-Seeing una Primal Hakkari Kossack. Devi anche avere una reputazione pari o superiore a Riverito con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova su Yojamba Isle, a Stranglethorn Vale.",
  progress = "Gli Emblemi del Potere... li hai portati? Il simbolo supremo del potere demoniaco lo condivideremo con te solo quando li avremo, $N.",
  reward = "Notevole — con la tua vittoria a Zul'Gurub ora siamo certi — anzi, ne è certo il mondo — che Hakkar non trionferà. Forse verrà il giorno in cui affronterai il Dio del Sangue in persona... e se succederà, sappi che nella tribù degli Zandalar sarai sempre $Griverito:riverita;.$B$BOh, e credo che anche questa semplice veste ti sarà d'aiuto.$B$B<Al'tabim ti strizza l'occhio con aria complice.>",
}
T[8078] = {
  title = "Paragoni del Potere: La Vindicator's Belt",
  desc = "Dentro Zul'Gurub attende la vendetta suprema. Hakkar non deve risorgere. Hakkar ha distrutto il Gurubashi Empire dall'interno, e nessun sacrificio è bastato. Dei troll resta l'ombra delle glorie di un tempo, e so che la colpa è di Hakkar.$B$BDiventa $Gil giustificatore:la giustificatrice; che eri $Gdestinato:destinata; a essere. Porta distruzione fra i servitori del male: Zul'Gurub deve assaggiare la vendetta degli Zandalar. Come prova, consegnami i Paragoni del Potere, e riceverai la vindicator's belt. Riceverai vero potere.$B$BVa'.",
  obj = "Porta a Jin'rokh the Breaker un Primal Hakkari Girdle. Devi anche avere una reputazione pari o superiore a Onorato con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova su Yojamba Isle, Stranglethorn Vale.",
  progress = "Hai portato i Paragoni del Potere? Hai abbattuto i nemici della tribù? Hakkar deve conoscere l'ira del giustificatore!",
  reward = "Ora conosci la via del giustificatore. Hai portato onore alla tribù e a te $Gstesso:stessa;, e dolore ai nostri nemici.$B$BLa vindicator's belt è tua. Di certo stai diventando una cosa sola con la via del giustificatore.",
}
T[8079] = {
  title = "Paragoni del Potere: La Corazza del Giustificatore",
  desc = "La corazza è il simbolo del potere del giustificatore. È forgiata con mojo potente e la affidiamo solo a chi veneriamo. È il segno della vendetta degli Zandalar.$B$BDiventare giustificatore vuol dire diventare vendetta. Prendi a Zul'Gurub i Paragoni del Potere che ci servono e portaceli. Ci riprenderemo il mojo che ci hanno rubato e faremo pagare i servitori di Hakkar. Come ricompensa, avrai da noi la corazza del giustificatore.$B$BVa'. Sii la nostra vendetta, $N.",
  obj = "Porta a Jin'rokh the Breaker una Primal Hakkari Kossack. Devi anche avere una reputazione pari o superiore a Venerato con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova su Yojamba Isle, Stranglethorn Vale.",
  progress = "Se sei qui, vuol dire vittoria? Hai i Paragoni del Potere? Raccontami la vendetta che hai seminato oggi!",
  reward = "Per le tue imprese meriti di essere $Gvenerato:venerata;. La tribù ricompensa i suoi eroi. Zul'Gurub non aveva mai assaggiato così la vendetta degli Zandalar.$B$BLe tue gesta annunceranno quelle di altri che verranno. Vedranno in te un segno di vero potere. Vedranno in te la vendetta in persona!",
}
T[8080] = {
  title = "Arathi Basin Mark of Honor!",
  desc = "Qualunque soldato ti dirà che la guerra si combatte con i soldati. E ti dirà anche che, con un equipaggiamento scadente o a stomaco vuoto, una battaglia è persa ancora prima di cominciare!$B$BEcco perché l'Arathi Basin conta tanto. Nel bacino ci sono zone chiave dove si trovano risorse essenziali. Metalli, armi, cibo, legname — ci servono tutti, e lì si possono prendere tutti.$B$BEcco cosa ti chiedo, $N. Entra nell'Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con un Contrassegno d'Onore.",
  obj = "Vinci la battaglia per l'Arathi Basin, ottieni un Arathi Basin Mark of Honor e riportalo a Sergeant Maclear a Refuge Pointe.",
  progress = "Hai i Contrassegni d'Onore, $N? Senza quelli The League of Arathor non riesce a combattere una battaglia come si deve...",
  reward = "Hai preso il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri intendenti, che le faranno arrivare in fretta alle truppe.$B$BGrazie, $N. Del resto, le guerre si vincono davvero così: portando a termine missioni come la tua.",
}
T[8101] = {
  title = "Il Pebble of Kajaro",
  reward = "$R, il sassolino incastonato in questo talismano viene dal Mount Kajaro, nei South Seas. Il Mount Kajaro è una zona tormentata dall'instabilità — segnata da eruzioni vulcaniche violente e spesso magiche.$B$BPiù crescerà il tuo legame con i troll degli Zandalar, più crescerà il potere di questo sassolino. Usane la forza per abbattere i nostri nemici. Sii come la montagna: $GRapido:Rapida;, $Gesplosivo:esplosiva;, letale...",
}
T[8102] = {
  title = "Il Pebble of Kajaro",
  progress = "$GBentornato:Bentornata;, $C. Vedo che il sassolino l'hai usato parecchio. Molti dei nostri nemici sono caduti davanti alle tue capacità ultraterrene, e hanno sofferto tanto. È ora di accrescere il potere del sassolino. Dammelo.",
  reward = "Sii inarrestabile, come i fronti di lava del Kajaro.",
}
T[8103] = {
  title = "Il Pebble of Kajaro",
  progress = "Gli Hakkari ti temono, $N. Parlano di orrori che credevano potesse compiere solo il loro Dio senza volto. Con la forza di Kajaro li hai bruciati, e ora la paura la conoscono in due luoghi.$B$BÈ tempo di rafforzare ancora il ciondolo. Dammi il talismano.",
  reward = "Continua a decimare i troll di Zul'Gurub. Hakkar deve vedere che il mondo non si piegherà alla sua volontà indomabile.",
}
T[8104] = {
  title = "Il Jewel of Kajaro",
  progress = "Dammi il talismano, $N: devo mostrarti una cosa.",
  reward = "<Al'tabim frantuma il ciondolo con una potente forza invisibile.>$B$BVedi? Il ciondolo è quello che noi chiamiamo un geode. Dentro ha potenti cristalli che hanno assorbito le energie latenti del nostro mondo, e tagliandolo a metà ne ho finalmente liberato tutto il potenziale. Usalo per devastare i nostri nemici.",
}
T[8105] = {
  title = "La Battaglia per l'Arathi Basin!",
  desc = "$N, la battaglia per l'Arathi Basin è una lotta per le risorse e il territorio. Dobbiamo tenere i punti chiave della zona e farli funzionare, così che riforniscano le nostre forze delle materie prime e delle provviste di cui hanno tanto bisogno. Il tuo incarico è assaltare i punti più lontani dalla nostra base nell'Arathi Basin.$B$BSe la fattoria, la miniera, la segheria e la forgia sono in mano al nemico, assaltale. Cerca lo stendardo nemico e strappalo dall'asta!$B$BTorna da me quando l'avrai fatto in tutti e quattro i punti.",
  obj = "Assalta la miniera, la segheria, la forgia e la fattoria, poi torna da Field Marshal Oslight a Refuge Pointe.",
  progress = "$N, le quattro basi non le hai ancora assaltate. Torna da me quando avrai completato gli obiettivi.",
  reward = "Mi sono arrivati i rapporti sulle tue imprese nell'Arathi Basin, $N. Ben fatto! Con persone come te che si uniscono qui alla lotta, ho fiducia che un giorno riconquisteremo le nostre terre natie.",
}
T[8106] = {
  title = "Kezan's Taint",
  reward = "Accetta questo talismano, $C. Accettalo, e usa il suo potere per abbattere i nemici che abbiamo in comune.$B$BSappi che porti al collo un pezzo di storia. Un tempo Kezan era un grande territorio dello Zandalar Empire, ma ahimè, la corruzione dei principi mercanti goblin ha scacciato i miei fieri fratelli e sorelle.$B$BOggi Kezan ospita Undermine, la capitale goblin; ma sappi che prima della corruzione ha conosciuto la grandezza, e ancora oggi per il mio popolo Kezan è terra sacra.",
}
T[8107] = {
  title = "Kezan's Taint",
  progress = "Fra i troll Zandalar l'onore si guadagna, $N. E l'onore porta una ricompensa — amicizia, alleanza...$B$BDammi il talismano, così ne accrescerò il potere.",
  reward = "Attingi all'oscurità, $C. Abbraccia le ombre, e lascia che il Kezan's Taint rafforzi i tuoi oscuri traffici.",
}
T[8108] = {
  title = "Kezan's Taint",
  progress = "Sono pronto per te, $C. Potenzierò ancora una volta il tuo talismano, e ti chiedo solo di continuare a distruggere Hakkar e i suoi servitori.$B$BDammi il talismano.",
  reward = "Fermeremo il Soulflayer solo unendo i nostri sforzi.",
}
T[8109] = {
  title = "Kezan's Unstoppable Taint",
  progress = "Evoca i tuoi demoni, $C, e lasciali crogiolare nell'energia del Kezan's Taint. Guidali sul campo di battaglia! Decima il nemico!$B$BSì... Ora è il momento di dare al Kezan's Taint il potenziamento finale. Passami il talismano.",
  reward = "Strappa la carne dai loro cadaveri. Guarda le ombre che divorano gli Hakkari. Trai potere dalla loro paura, $C, e lascia che il Kezan's Taint lo accresca...",
}
T[8110] = {
  title = "Enchanted South Seas Kelp",
  reward = "Tu vedere questa seaweed qui, mon? Lei venire dai South Seas. Noi mettere solo un po' di mojo e un po' di magia, e lei prendere le proprietà più adatte al suo padrone.$B$BTu essere $Gun:una; $C, quindi per te essere facile, mon: tu solo avvolgerla intorno al collo e pensare alla natura, o agli scoiattoli, o a qualsiasi cosa piacere a voi gente.",
}
T[8111] = {
  title = "Enchanted South Seas Kelp",
  progress = "Ehi mon! Essere bello vedere te di nuovo. La tribù parlare di te che ammazzare gli Hakkari e tutto il resto. Molthor dato a me il via per mettere più mojo nel tuo talismano. Tu dare qua, e Maywiki lo fa più buono.",
  reward = "Pezzo da collo non essere roba da fumare, mon! Tu dovere usare lui per combattere il male.",
}
T[8112] = {
  title = "Enchanted South Seas Kelp",
  progress = "Come stare quel talismano, mon? Sembrare ora di dare alle sue foglie un altro po' di magia e mojo. Lui appassire, e avere bisogno di rifiorire un po'. Tu dare qua, e Maywiki lo sistema subito.",
  reward = "Adesso tu andare dai troll malvagi di Zul'Gurub e fare vedere a loro cosa sapere fare i tuoi poteri della natura, mon!",
}
T[8113] = {
  title = "Pristine Enchanted South Seas Kelp",
  progress = "$N! Passato tanto tempo da quando io visto te. Tu sapere che King Rastakhan in persona dare a me l'ordine di mettere l'ultimo pezzetto di mojo e magia nel tuo talismano? Essere vero, mon! Io non crederci se non vedere con i miei occhi. Tu dare qua.",
  reward = "Bel viaggio essere stato, $N mon. Tu continuare ad ammazzare e schiacciare Hakkar e lui servitori.",
}
T[8114] = {
  title = "Controlla Quattro Basi",
  desc = "$N, hai portato l'attacco ai nostri nemici nell'Arathi Basin e su quel campo di battaglia ti sei $Gguadagnato:guadagnata; grandi onori. Ci hai dato prova del tuo valore come $C, e hai fatto capire ai nemici che non ci piegheremo alla loro malvagità!$B$BProprio per questo ho un compito difficile per te: voglio che tu conquisti e tenga almeno quattro basi dell'Arathi Basin. Se ci riuscirai, non solo ci assicureremo risorse cruciali, ma mostreremo all'Orda che siamo superiori!$B$BVa', $N, e buona fortuna.",
  obj = "Entra nell'Arathi Basin, conquista e controlla quattro basi contemporaneamente, e poi torna da Field Marshal Oslight a Refuge Pointe.",
  reward = "Ottimo lavoro, $N! È venuto da me un esploratore tutto entusiasta, con un rapporto sulle tue imprese. Noi della League of Arathor siamo molto soddisfatti!$B$BTra i soldati della Lega stai diventando in fretta $Gun eroe:un'eroina;, e quello che hai fatto oggi conferma ancora una volta la tua ottima reputazione.",
}
T[8115] = {
  title = "Controlla Cinque Basi",
  desc = "$N, combattere per le risorse dell'Arathi Basin è un'impresa sanguinosa, e quello che fai per la League of Arathor è tanto necessario quanto apprezzato.$B$BE per te abbiamo un altro compito.$B$BLa Lega vuole sferrare un'offensiva decisa contro i Defilers che occupano l'Arathi Basin. Vogliamo cacciarli da ogni punto strategico del campo di battaglia!$B$BNon sarà facile, ma se qualcuno può riuscirci, quello sei tu.",
  obj = "Controlla 5 basi nell'Arathi Basin contemporaneamente, poi torna da Field Marshal Oslight a Refuge Pointe.",
}
T[8116] = {
  title = "Vision of Voodress",
  reward = "Tu e Maywiki avere una cosa in comune, mon: noi due essere $Gsciamani:sciamane;! Va bene, Maywiki è più una mistica e tu più una schiappa, ma $Gtutti:tutte; e due sappiamo cosa portano i grandi spiriti.$B$BQuesta sfera te la regalo, da portare al collo. Guardaci bene dentro e vedrai il villaggio di Voodress nei South Seas! Che ti tiri su lo spirito!",
}
T[8117] = {
  title = "Vision of Voodress",
  progress = "Buone notizie, $N: ultimamente Molthor cantare le tue lodi. Lui dire che tu stai diventando $Gun vero eroe:una vera eroina; degli Zandalar.$B$BE dire anche a Maywiki di lucidarti ancora la sfera! Dalla qua, così Maywiki può ravvivare la visione.",
  reward = "$GAttento:Attenta; agli spiriti Hakkari malvagi, mon. A dire il vero, loro fare paura.",
}
T[8118] = {
  title = "Vision of Voodress",
  progress = "Sha-mon! Maywiki fa una battuta!$B$B<Maywiki ride.>$B$BAllora tu hai usato spiriti ed elementi contro i nostri nemici a Zul'Gurub, eh? Lodati siano gli spiriti!$B$BOra Maywiki ti fa brillare la sfera. Dalla qua, $N.",
  reward = "Guardala adesso, $N: Voodress si vede ancora più chiaro, eh? Lascia scorrere in te il potere primordiale, mon.",
}
T[8119] = {
  title = "L'Unmarred Vision of Voodress",
  progress = "<Maywiki indica il tuo talismano.>$B$BGuardalo, $N! Ha preso vita: gli spiriti danzano attorno alla sfera.$B$BDallo a Maywiki, così gli dà un ultimo ritocco.",
  reward = "Un giorno, $N, con questa sfera potrai parlare direttamente con me. Quando sarà finita questa battaglia contro Hakkar e Maywiki tornerà a casa. Chiamiamo gli spiriti e chiediamo che quel giorno arrivi presto.",
}
T[8120] = {
  title = "La Battaglia per l'Arathi Basin!",
  desc = "Avrai senz'altro sentito che la League of Arathor sta mandando truppe in gran numero nell'Arathi Basin. Questi sciocchi dell'Alleanza sono avidi di cibo e rifornimenti, e vogliono a tutti i costi prendersi le ricche risorse di quel luogo e tenerle in pugno. Dobbiamo far vedere loro che Arathi non sarà mai più la casa degli umani!$B$BVai nell'Arathi Basin e assalta la miniera, la segheria, la fucina e le stalle. Abbatti gli stendardi nemici e reclama quei territori per l'Orda.$B$BVai, $N. Quando avrai portato a termine il compito, torna a riferire.",
  obj = "Assalta la miniera, la segheria, la fucina e la stalla di Arathi Basin, poi torna da Deathmaster Dwire a Hammerfall.",
  reward = "Un esploratore Defiler mi ha portato la notizia del tuo successo, $N. Ben fatto.$B$BCome imparerai, per vincere la battaglia per l'Arathi Basin dobbiamo restare sempre all'erta e schiacciare l'Alleanza ogni volta che prova ad allargarsi. Se lo farai, qui la vittoria sarà nostra.",
}
T[8121] = {
  title = "Conquista Quattro Basi",
  desc = "$N, mentre le battaglie per l'Arathi Basin infuriano, quello che hai fatto è arrivato alle orecchie di molti. Fra noi sei $Gtenuto:tenuta; in grande considerazione, e per questo sono fiduciosa che porterai a termine la missione che ho per te.$B$BÈ ora di mandare un messaggio alla League of Arathor: dobbiamo far vedere loro che i loro possedimenti nell'Arathi Basin sono precari e si perdono in fretta. E glielo faremo vedere tenendo quattro punti strategici dell'Arathi Basin tutti nello stesso momento.$B$BSe ci riuscirai, $N, ti guadagnerai grande rispetto fra i Defilers.",
  obj = "Tieni quattro basi contemporaneamente in Arathi Basin, poi torna da Deathmaster Dwire a Hammerfall.",
}
T[8122] = {
  title = "Conquista Cinque Basi",
  desc = "Immersi come siamo nel conflitto, è difficile accorgersene, ma le nostre spie riferiscono che la League of Arathor comincia a perdere la sua determinazione. Dobbiamo approfittarne e assestare loro un colpo brutale! Torna nell'Arathi Basin e scagliati sui nemici. Maledicili, uccidili e prendi il controllo di tutte e cinque le basi strategiche! Fai fuggire i loro soldati dalla prima linea, urlanti e sanguinanti, con le storie della tua crudeltà sulle labbra piagnucolanti.$B$BFallo, e porterai ai Defilers una grande vittoria.",
  obj = "Tieni cinque basi contemporaneamente in Arathi Basin, poi torna da Deathmaster Dwire a Hammerfall.",
}
T[8123] = {
  title = "Taglia le Linee di Rifornimento di Arathor",
  desc = "Pur di riconquistare Arathi, The League of Arathor non bada a spese. Ora stanno affluendo in questa regione lontana, loro e tutte le razze dell'Alleanza, decisi ad allargare il loro dominio partendo da Refuge Pointe. Vanno fermati, e il modo migliore è impadronirci dei loro rifornimenti.$B$BTu puoi aiutarci, $N. Entra nell'Arathi Basin, famoso per le miniere ricche, le terre fertili e gli artigiani abili. Conquista ogni base che puoi e tienila, vinci la battaglia e torna da me con il Contrassegno d'Onore che otterrai.",
  obj = "Vinci la battaglia per l'Arathi Basin, ottieni un Arathi Basin Mark of Honor e riportalo al Deathstalker Mortis a Hammerfall.",
  progress = "Che c'è, $R? Ce li hai i Contrassegni d'Onore? Torna nell'Arathi Basin, uccidi i vermi dell'Alleanza e impadronisciti delle sue risorse per la Dama Oscura!",
  reward = "<Il Deathstalker Mortis sorride>$B$BI nostri nemici hanno subito un altro colpo decisivo, $N. Grazie alle tue imprese, presto l'Arathi Basin cadrà nelle mani dei Defilers.",
}
T[8141] = {
  title = "Zandalarian Shadow Talisman",
  reward = "Fai progressi in fretta, giovane $C. Forse è ora di iniziarti alla Shera Ali'kh — la Death's Hand, in zandalari. Per migliaia di anni siamo stati gli assassini dello Zandalar Empire. Poi per troppo tempo siamo rimasti con le mani in mano, e abbiamo lasciato che gli Hakkari diventassero più forti. Ora affrontiamo di nuovo Hakkar, ma stavolta senza un fronte troll unito a sostenerci. Tocca a te e ai tuoi alleati dare una mano a sconfiggere il Dio del Sangue e i suoi servitori!$B$BIndossa questo talismano e lascia che ti sia d'aiuto nei viaggi.",
}
T[8142] = {
  title = "Zandalarian Shadow Talisman",
  progress = "Impressionante, $N. Hai un talento per uccidere che da molti anni non sentivo in nessun altro. Perfino Molthor sa del lavoro che hai fatto per gli Zandalar. È ora di potenziare ancora il tuo talismano. Dammelo.",
  reward = "Il talismano può ricevere un ultimo potenziamento, $C. Ci penserò io, quando sarà il momento giusto.",
}
T[8143] = {
  title = "Zandalarian Shadow Talisman",
  progress = "Sento che hai ucciso innumerevoli Hakkari, $N. Hai addosso il fetore del loro mojo.$B$BImmagino che il talismano dell'Ombra ti sia stato utile nello sterminio? Dammelo, e lascia che ne accresca il potere.",
  reward = "Da $Gun assassino:un'assassina; del tuo calibro conviene stare alla larga. I tuoi nemici devono imparare il rispetto! Ed è proprio quello che otterrai quando il nemico vedrà il bagliore della Death's Hand — troppo tardi...",
}
T[8144] = {
  title = "Zandalarian Shadow Mastery Talisman",
  progress = "Brama di crescere, $N. Il talismano ha assorbito tutto quello che hai fatto, e le migliaia di cadaveri di troll sparsi per Zul'Gurub ne hanno nutrito il potere. Dammelo e farò l'ultimo potenziamento.",
  reward = "Questa è l'ultima volta che parliamo sotto gli auspici della Shera Ali'kh. Sai tutto quello che c'è da sapere. Prendi il talismano e va' avanti con la tua strage. Hakkar non deve mai lasciare Zul'Gurub.",
}
T[8145] = {
  title = "Il Maelstrom's Tendril",
  reward = "Tra gli Zandalarians il mestiere del cacciatore è venerato. I più grandi fra i nostri cacciatori arrivano fino ai confini del Maelstrom per dare prova della loro determinazione.$B$BDal cuore del mare strappano dei filamenti di alga chiamati Maelstrom's Tendril, e con quell'alga intrecciano poi un talismano, incantato per renderli più precisi e più potenti.$B$BOra ti concedo un solo intreccio del Maelstrom's Tendril. Più crescerà il tuo legame con Zandalar, più potere intreccerò nel talismano.",
}
T[8146] = {
  title = "Il Maelstrom's Tendril",
  progress = "Ah, $N, che piacere tornare a fiutarti.$B$B<Falthir sogghigna.>$B$BDovrai perdonare il mio senso dell'umorismo, che a volte sa essere proprio rivoltante.$B$BSento che hai gettato i nostri nemici in una grande angoscia. Le forze di Hakkar gridano il tuo nome piene di rabbia. Davvero eccellente.$B$BTi sei $Gguadagnato:guadagnata; un altro intreccio per il talismano. Dammelo.",
  reward = "Che vadano a cercare l'espiazione sulla punta delle tue munizioni.",
}
T[8147] = {
  title = "Il Maelstrom's Tendril",
  progress = "Ah, $N, che piacere tornare a fiutarti.$B$B<Falthir sogghigna.>$B$BDovrai perdonare il mio senso dell'umorismo, che a volte sa essere proprio rivoltante.$B$BSento che hai gettato i nostri nemici in una grande angoscia. Le forze di Hakkar gridano il tuo nome piene di rabbia. Davvero eccellente.$B$BTi sei $Gguadagnato:guadagnata; un altro intreccio per il talismano. Dammelo.",
  reward = "Che vadano a cercare l'espiazione sulla punta delle tue munizioni.",
}
T[8148] = {
  title = "Maelstrom's Wrath",
  progress = "Molthor porta notizie da King Rastakhan, $N: la corte reale è molto colpita da come hai decimato le forze Hakkari, e devo concederti l'ultimo intreccio del talismano. Dammelo.",
  reward = "Il tuo viaggio è appena cominciato, giovane $C. Forse un giorno andrai fino al Maelstrom e getterai uno sguardo nel cuore del mondo.$B$BTi auguro potere e tenacia!",
}
T[8149] = {
  title = "Onorare un Eroe",
  desc = "Durante la Festa del Raccolto di Azeroth ringraziamo gli eroi per quello che hanno sacrificato — alcuni persino la vita — per noi. L'Alleanza onora molti eroi, ma nessuno ha una storia più tragica di quella di Uther Lightbringer.$B$BAiutaci a rendere omaggio a Uther: porta quest'offerta alla sua tomba, nelle Western Plaguelands. Deponila presso la sua statua, poi torna da me. Resterò qui solo fino alla fine della festa, quindi non perdere tempo e fa' avere a Uther il suo tributo.",
  obj = "Raggiungi la Tomba di Uther in Western Plaguelands e usa Uther's Tribute presso la sua statua, poi torna da Wagner Hammerstrike, fuori da Ironforge, prima che finisca la Festa del Raccolto.",
  progress = "Sei già $Gstato:stata; alla Tomba di Uther a deporre il tributo?$B$BPer gli avventurieri meno esperti può essere un viaggio pericoloso; la strada più sicura, si fa per dire, potrebbe essere risalire verso nord il corso d'acqua che attraversa Hillsbrad, fino alle Plaguelands. Il fiume nasce da un lago vicino al Sorrow Hill; da lì sali verso ovest tra le colline e tieniti alla larga dall'altra tomba che c'è lì vicino... è infestata dallo Scourge.",
  reward = "Era un eroe fra gli eroi, Uther. Non riesco nemmeno a immaginare l'angoscia che ha provato quando Arthas — il suo allievo migliore, che Uther amava come un figlio — ha tradito l'intera umanità. Eppure si è fatto avanti per cercare di fermare Arthas, e per questo sarà ricordato per sempre come un vero paladino. Ha combattuto fino alla fine, pensando solo a chi poteva salvare.$B$BGrazie, $N. Oggi hai reso omaggio a un grande eroe, onorando il suo spirito e quello della Festa del Raccolto.",
  en_title = "Honoring a Hero",
  en_obj = "Travel to Uther's Tomb in Western Plaguelands and use Uther's Tribute at his statue, and then return to Wagner Hammerstrike outside Ironforge before the Harvest Festival is over.",
}
T[8150] = {
  title = "Onorare un Eroe",
  desc = "Alla Festa del Raccolto di Azeroth ringraziamo gli eroi per i sacrifici — a volte il sacrificio estremo — che hanno fatto per noi. L'Orda riconosce molti eroi, ma nessuno incarna la forza e il sacrificio come Grom Hellscream.$B$BAiutaci a onorare Grom: porta questa offerta al suo monumento nel Demon Fall Canyon of Ashenvale, posala alla base e poi torna da me. Resto qui solo fino alla fine della festa, quindi non perdere tempo e porta a Grom il suo tributo.",
  obj = "Raggiungi il Grom's Monument nel Demon Fall Canyon of Ashenvale e usa il Grom's Tribute alla base del monumento. Torna da Javnir Nashak fuori da Orgrimmar prima che finisca la Festa del Raccolto.",
  progress = "Hai raggiunto il Grom's Monument e gli hai posato il suo tributo?$B$BLa zona del monumento porta ancora i segni della corruzione della Burning Legion. Se sei poco $Gesperto:esperta; di avventure, sta' all'erta quando ti avvicini.",
  reward = "Il nome completo di Grom — Grommash — vuol dire \"Il Cuore del Gigante\"; e per opporsi da solo a Mannoroth ci è voluto questo e anche di più. Credo che l'abbia detto meglio di tutti il Capoguerra: la maledizione degli orchi è cominciata e finita con Grom. È giusto che oggi l'Orda sgorghi dal sacrificio di Grom — e forse dalla sua redenzione — come da una sorgente.$B$BGrazie, $N. Oggi hai reso omaggio a un grande eroe, e hai onorato il suo spirito e quello della Festa del Raccolto.",
  en_title = "Honoring a Hero",
  en_obj = "Travel to Grom's Monument in the Demon Fall Canyon of Ashenvale and use Grom's Tribute at the base of the monument.  Return to Javnir Nashak outside Orgrimmar before the Harvest Festival is over.",
}
T[8151] = {
  title = "Il Talismano del Cacciatore",
  desc = "Ogtinc of Azshara ha chiamato a sé i cacciatori esperti come te. È un cacciatore furbolg che ha lasciato la sua tribù per aiutare il Cenarion Circle. I suoi insegnamenti servono ad arricchire la saggezza di chi pratica la sua stessa arte e a guidarlo nel mantenere l'equilibrio. Faresti bene a parlargli.$B$BOgtinc vive in cima alle scogliere di Azshara, a nordest delle Ruins of Eldarath.",
  obj = "Parla con Ogtinc ad Azshara.",
  reward = "Il mio scopo ora non è più cacciare, ma insegnare al cacciatore. È questo il compito che mi ha affidato il destino.$B$BCreiamo insieme un talismano del cacciatore — una raccolta di trofei di prede abbattute, che ti ricorderà le tue prove e i tuoi trionfi passati. Alla fine il talismano lo terrò io, ma ti ricompenserò con qualcos'altro.",
}
T[8153] = {
  title = "Corni di Corsiero",
  desc = "Il corsiero porta i corni più possenti delle terre conosciute e li usa per difendersi: incorna chi lo attacca, e spesso così si rovina le punte. Corni naturali e perfetti sono il segno di uno spirito animale assolutamente sicuro di sé.$B$BSe avrai corni come questi, ti infonderanno la stessa sicurezza.$B$BDai la caccia al mosshoof courser, trova i corni perfetti e portameli.",
  obj = "Porta un paio di Perfect Courser Antlers a Ogtinc ad Azshara. Ogtinc vive in cima alle scogliere a nordest delle Ruins of Eldarath.",
  progress = "Li hai trovati, i corni?",
  reward = "Se sono tuoi, hai la vista acuta e una grande pazienza. Ben fatto.",
}
T[8154] = {
  title = "Arathi Basin Mark of Honor!",
  desc = "Qualunque soldato ti dirà che la guerra si combatte con i soldati. E ti dirà anche che, con un equipaggiamento scadente o a stomaco vuoto, una battaglia è persa ancora prima di cominciare!$B$BEcco perché l'Arathi Basin conta tanto. Nel bacino ci sono zone chiave dove si trovano risorse essenziali. Metalli, armi, cibo, legname — ci servono tutti, e lì si possono prendere tutti.$B$BEcco cosa ti chiedo, $N. Entra nell'Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con un Contrassegno d'Onore.",
  obj = "Vinci la battaglia per l'Arathi Basin, ottieni un Arathi Basin Mark of Honor e riportalo a Sergeant Maclear a Refuge Pointe.",
  progress = "Hai i Contrassegni d'Onore, $N? Senza quelli The League of Arathor non riesce a combattere una battaglia come si deve...",
  reward = "Hai preso il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri intendenti, che le faranno arrivare in fretta alle truppe.$B$BGrazie, $N. Del resto, le guerre si vincono davvero così: portando a termine missioni come la tua.",
}
T[8155] = {
  title = "Risorse dell'Arathi Basin!",
  desc = "Qualunque soldato ti dirà che la guerra si combatte con i soldati. E ti dirà anche che, con un equipaggiamento scadente o a stomaco vuoto, una battaglia è persa ancora prima di cominciare!$B$BEcco perché l'Arathi Basin conta tanto. Nel bacino ci sono zone chiave dove si trovano risorse essenziali. Metalli, armi, cibo, legname — ci servono tutti, e lì si possono prendere tutti.$B$BEcco cosa ti chiedo, $N. Entra nell'Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con un Contrassegno d'Onore.",
  obj = "Vinci la battaglia per l'Arathi Basin, ottieni un Arathi Basin Mark of Honor e riportalo a Sergeant Maclear a Refuge Pointe.",
  progress = "Hai i Contrassegni d'Onore, $N? Senza quelli The League of Arathor non riesce a combattere una battaglia come si deve...",
  reward = "Hai preso il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri intendenti, che le faranno arrivare in fretta alle truppe.$B$BGrazie, $N. Del resto, le guerre si vincono davvero così: portando a termine missioni come la tua.",
  en_title = "Arathi Basin Resources!",
  en_obj = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.",
}
T[8156] = {
  title = "Arathi Basin Mark of Honor!",
  desc = "Qualunque soldato ti dirà che la guerra si combatte con i soldati. E ti dirà anche che, con un equipaggiamento scadente o a stomaco vuoto, una battaglia è persa ancora prima di cominciare!$B$BEcco perché l'Arathi Basin conta tanto. Nel bacino ci sono zone chiave dove si trovano risorse essenziali. Metalli, armi, cibo, legname — ci servono tutti, e lì si possono prendere tutti.$B$BEcco cosa ti chiedo, $N. Entra nell'Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con un Contrassegno d'Onore.",
  obj = "Vinci la battaglia per l'Arathi Basin, ottieni un Arathi Basin Mark of Honor e riportalo a Sergeant Maclear a Refuge Pointe.",
  progress = "Hai i Contrassegni d'Onore, $N? Senza quelli The League of Arathor non riesce a combattere una battaglia come si deve...",
  reward = "Hai preso il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri intendenti, che le faranno arrivare in fretta alle truppe.$B$BGrazie, $N. Del resto, le guerre si vincono davvero così: portando a termine missioni come la tua.",
  en_title = "Arathi Basin Resources!",
  en_obj = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.",
}
T[8160] = {
  title = "Taglia le Linee di Rifornimento di Arathor",
  desc = "The League of Arathor non bada a spese pur di riconquistare Arathi. Ora arrivano in massa in questa regione lontana, insieme a tutte le razze dell'Alleanza, decisi a estendere il loro dominio partendo da Refuge Pointe. Dobbiamo fermarli, e il modo migliore è portargli via le provviste.$B$BTu puoi aiutarci, $N. Entra nell'Arathi Basin, noto per le ricche miniere, la terra fertile e gli artigiani esperti. Prendi più basi che puoi e tienile, vinci la battaglia e riportami il Contrassegno d'Onore che otterrai.",
  obj = "Vinci la battaglia per l'Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Deathstalker Mortis a Hammerfall.",
  progress = "Che c'è, $R? Ce li hai, i Contrassegni d'Onore? Torna nell'Arathi Basin, fai strage dei parassiti dell'Alleanza e impadronisciti delle risorse per la Dama Oscura!",
  reward = "<Deathstalker Mortis sorride>$B$BAbbiamo assestato ai nostri nemici un altro colpo decisivo, $N. Grazie alle tue imprese, l'Arathi Basin cadrà presto nelle mani dei Defilers.",
}
