T[8166] = {
  title = "La Battaglia per l'Arathi Basin!",
  desc = "$N, la battaglia per l'Arathi Basin è una lotta per le risorse e il territorio. Dobbiamo tenere i punti chiave della zona e farli funzionare, così che riforniscano le nostre forze delle materie prime e delle provviste di cui hanno tanto bisogno. Il tuo incarico è assaltare i punti più lontani dalla nostra base nell'Arathi Basin.$B$BSe la fattoria, la miniera, la segheria e la forgia sono in mano al nemico, assaltale. Cerca lo stendardo nemico e strappalo dall'asta!$B$BTorna da me quando l'avrai fatto in tutti e quattro i punti.",
  obj = "Assalta la miniera, la segheria, la forgia e la fattoria, poi torna da Field Marshal Oslight a Refuge Pointe.",
  reward = "Mi sono arrivati i rapporti sulle tue imprese nell'Arathi Basin, $N. Ben fatto! Con persone come te che si uniscono qui alla lotta, ho fiducia che un giorno riconquisteremo le nostre terre natie.",
}
T[8167] = {
  title = "La Battaglia per l'Arathi Basin!",
  desc = "$N, la battaglia per l'Arathi Basin è una lotta per le risorse e il territorio. Dobbiamo tenere i punti chiave della zona e farli funzionare, così che riforniscano le nostre forze delle materie prime e delle provviste di cui hanno tanto bisogno. Il tuo incarico è assaltare i punti più lontani dalla nostra base nell'Arathi Basin.$B$BSe la fattoria, la miniera, la segheria e la forgia sono in mano al nemico, assaltale. Cerca lo stendardo nemico e strappalo dall'asta!$B$BTorna da me quando l'avrai fatto in tutti e quattro i punti.",
  obj = "Assalta la miniera, la segheria, la forgia e la fattoria, poi torna da Field Marshal Oslight a Refuge Pointe.",
  reward = "Mi sono arrivati i rapporti sulle tue imprese nell'Arathi Basin, $N. Ben fatto! Con persone come te che si uniscono qui alla lotta, ho fiducia che un giorno riconquisteremo le nostre terre natie.",
  en_title = "The Battle for Arathi Basin!",
  en_obj = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.",
}
T[8168] = {
  title = "La Battaglia per l'Arathi Basin!",
  desc = "$N, nell'Arathi Basin si lotta per le risorse e per il territorio. Dobbiamo tenere i punti chiave della zona e farli funzionare, per dare alle nostre forze le materie prime e le provviste di cui hanno tanto bisogno. Ti ordino di attaccare i punti dell'Arathi Basin più lontani dalla nostra base.$B$BQuando la fattoria, la miniera, la segheria e la fucina sono in mano al nemico, attaccale. Trova il suo stendardo e strappalo dall'asta!$B$BFatto questo in tutti e quattro i punti, torna da me.",
  obj = "Attacca la miniera, la segheria, la fucina e la fattoria, poi torna da Field Marshal Oslight a Refuge Pointe.",
  reward = "Ho ricevuto rapporti sulle tue imprese nell'Arathi Basin, $N. Ben fatto! Con gente come te che si unisce alla lotta qui, confido che un giorno riconquisteremo le nostre terre.",
  en_title = "The Battle for Arathi Basin!",
  en_obj = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.",
}
T[8169] = {
  title = "La Battaglia per l'Arathi Basin!",
  desc = "Avrai senz'altro sentito che la League of Arathor sta mandando truppe in gran numero nell'Arathi Basin. Questi sciocchi dell'Alleanza sono avidi di cibo e rifornimenti, e vogliono a tutti i costi prendersi le ricche risorse di quel luogo e tenerle in pugno. Dobbiamo far vedere loro che Arathi non sarà mai più la casa degli umani!$B$BVai nell'Arathi Basin e assalta la miniera, la segheria, la fucina e le stalle. Abbatti gli stendardi nemici e reclama quei territori per l'Orda.$B$BVai, $N. Quando avrai portato a termine il compito, torna a riferire.",
  obj = "Assalta la miniera, la segheria, la fucina e la stalla di Arathi Basin, poi torna da Deathmaster Dwire a Hammerfall.",
  reward = "Un esploratore Defiler mi ha portato la notizia del tuo successo, $N. Ben fatto.$B$BCome imparerai, per vincere la battaglia per l'Arathi Basin dobbiamo restare sempre all'erta e schiacciare l'Alleanza ogni volta che prova ad allargarsi. Se lo farai, qui la vittoria sarà nostra.",
}
T[8170] = {
  title = "La Battaglia per l'Arathi Basin!",
  desc = "Avrai senz'altro sentito che la League of Arathor sta mandando truppe in gran numero nell'Arathi Basin. Questi sciocchi dell'Alleanza sono avidi di cibo e rifornimenti, e vogliono a tutti i costi prendersi le ricche risorse di quel luogo e tenerle in pugno. Dobbiamo far vedere loro che Arathi non sarà mai più la casa degli umani!$B$BVai nell'Arathi Basin e assalta la miniera, la segheria, la fucina e le stalle. Abbatti gli stendardi nemici e reclama quei territori per l'Orda.$B$BVai, $N. Quando avrai portato a termine il compito, torna a riferire.",
  obj = "Assalta la miniera, la segheria, la fucina e la stalla di Arathi Basin, poi torna da Deathmaster Dwire a Hammerfall.",
  reward = "Un esploratore Defiler mi ha portato la notizia del tuo successo, $N. Ben fatto.$B$BCome imparerai, per vincere la battaglia per l'Arathi Basin dobbiamo restare sempre all'erta e schiacciare l'Alleanza ogni volta che prova ad allargarsi. Se lo farai, qui la vittoria sarà nostra.",
  en_title = "The Battle for Arathi Basin!",
  en_obj = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.",
}
T[8171] = {
  title = "La Battaglia per l'Arathi Basin!",
  desc = "Avrai senz'altro sentito che la League of Arathor sta mandando truppe in gran numero nell'Arathi Basin. Questi sciocchi dell'Alleanza, avidi di cibo e provviste, sono decisi a impadronirsi delle ricche risorse della zona e a tenerle sotto controllo. Dobbiamo mostrare loro che Arathi non sarà mai più una casa per gli umani!$B$BVa' nell'Arathi Basin e attacca la miniera, la segheria, la forgia e le stalle. Abbatti gli stendardi dei nemici e rivendica quei territori per l'Orda.$B$BVa', $N. Quando avrai portato a termine il compito, torna da me a fare rapporto.",
  obj = "Attacca la miniera, la segheria, la forgia e la stalla dell'Arathi Basin, poi torna da Deathmaster Dwire a Hammerfall.",
  reward = "Un esploratore dei Defiler mi ha portato notizia del tuo successo, $N. Ben fatto.$B$BImparerai che per vincere la battaglia per l'Arathi Basin dobbiamo restare sempre vigili e schiacciare ogni tentativo dell'Alleanza di espandersi. Se lo farai, qui la vittoria sarà nostra.",
  en_title = "The Battle for Arathi Basin!",
  en_obj = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.",
}
T[8181] = {
  title = "Affronta Yeh'kinya",
  desc = "Ho studiato le Tavolette di Mosh'aru, $N, e le notizie sono brutte. Proprio dall'uovo in cui l'hai catturato può rinascere Hakkar nella sua vera forma, il dio in persona. Yeh'kinya ti ha detto che serviva a contenere il suo male, e invece serve a ricrearlo! Quel troll ti ha portato fuori strada!$B$BVa' da Yeh'kinya e pretendi che ti consegni l'uovo. E prega che non sia troppo tardi per fermare il ritorno di Hakkar!",
  obj = "Parla con Yeh'kinya.",
  reward = "Così hai parlato con quel vecchio nano di Ironboot e hai scoperto le Tavolette perdute di Mosh'aru, eh? Che cercatore ficcanaso...$B$BNon importa. È troppo tardi per salvare questo mondo. Hakkar è rinato e la sua potenza sta già crescendo... nelle profondità dell'antico regno troll di Zul'Gurub! È giunto! E regnerà nel sangue e nel terrore!$B$BGrazie, $N. Mi hai aiutato ad affrettare il ritorno del Soulflayer!",
}
T[8182] = {
  title = "La Mano di Rastakhan",
  desc = "$N, è successo quello che temevamo di più. Secondo la leggenda il Soulflayer dominava l'antico mondo dei troll con il male e il terrore, e il suo potere non aveva limiti. Se non viene fermato subito, il suo nuovo regno potrebbe allargarsi a tutta Azeroth!$B$BUn contingente di troll Zandalarian potrebbe aiutarci ad arginare questa marea di oscurità. Si sono accampati su Yojamba Isle, al largo della costa di Stranglethorn, a ovest delle rovine di Zul'Kunda. Parla con il loro capo, Molthor, e prega che sappia come sconfiggere Hakkar.",
  obj = "Parla con Molthor a Stranglethorn.",
  reward = "Sei $Gstato mandato:stata mandata; dal cercatore, Ironboot? Quelli della sua specie sono saggi, e lui lo è stato ancora di più a portarti da me: io e i troll Zandalarian potremmo conoscere un modo per sconfiggere il Soulflayer.$B$BParla con i troll di quest'isola, ascolta quello che hanno da dirti e preparati, $N, perché il compito che ti aspetta è intriso di sangue.",
}
T[8183] = {
  title = "L'Heart of Hakkar",
  desc = "L'Heart of Hakkar arde dall'interno. Il Soulflayer è stato sconfitto, eppure il nucleo del suo potere rimane ancora in questo organo maledetto.",
  obj = "Porta l'Heart of Hakkar a Molthor su Yojamba Isle.",
  progress = "$N, hai addosso il fetore di un'anima malvagia. Ti ha $Gmaledetto:maledetta; il Soulflayer?",
  reward = "Ah, l'Heart of Hakkar. Allora il Soulflayer è stato ucciso! Il nostro mondo è salvo!$B$B$N, nessuna lode basterà mai per il servizio che ci hai reso. Sei $Gun vero eroe:una vera eroina; di questo regno!",
}
T[8184] = {
  title = "Presence of Might",
  progress = "Con i componenti giusti, Zanza può creare gli antichi incantamenti troll.$B$BIl primo è un idolo primordiale degli Hakkari, e devi strapparlo ai luogotenenti più potenti degli Hakkari: Jin'do e il Signore del Sangue.$B$BIl secondo è una punctured voodoo doll, e ne trovi nei cumuli di rifiuti sparsi per questo luogo immondo. Fruga nei mucchi vudù stregati.$B$BPortami queste cose e ti creerò un incantamento potente!",
  reward = "Usalo bene, $C. Nessuna pietà per gli Hakkari!",
}
