T[8193] = {
  title = "Maestro Pescatore",
  progress = "Oggi, dalle 2 alle 4 del pomeriggio, c'è una gara per decidere chi è il più grande pescatore di tutti! Devi solo essere la PRIMA PERSONA a portarmi 40 Pesci Gustosi, presi dai banchi di Pesci Gustosi lungo la costa di Stranglethorn, prima di chiunque altro, e sarai $Gproclamato:proclamata; $GMaestro Pescatore:Maestra Pescatrice;!$B$BSe non sei la prima persona a portarmi 40 pesci, la mia apprendista qui ti darà comunque del denaro per ogni 5 Pesci Gustosi che le porti.$B$BAh, e non perdere tempo: i Pesci Gustosi vanno a male in fretta!",
  reward = "Se vuoi essere $Gproclamato:proclamata; $GMaestro Pescatore:Maestra Pescatrice;, sbrigati a consegnarli! Sto qui in piedi da ORE a stomaco vuoto! Molla qua quei cosi!",
  en_title = "Master Angler",
}
T[8194] = {
  title = "$GPescatore:Pescatrice; Apprendista",
  progress = "La gara ha già un vincitore, ma i Pesci Gustosi te li compro lo stesso, e a un prezzo ragionevole. Che ne dici, eh!",
  reward = "Se l'affare va bene a te, a me va bene!",
}
T[8195] = {
  title = "Zulian, Razzashi e Hakkari Coins",
  progress = "Cerco i Paragoni del Potere che chiamano Monete delle Tribù. Sono la valuta dei vari abitanti di Zul'Gurub, e ognuna è intrisa di un mojo sottile ma potente.$B$BNe esistono nove tipi. I miei compatrioti ne cercano alcune per le varie armature che offrono agli eroi Zandalar. Se te ne avanza qualcuna, per una serie di tre ti darò uno dei nostri Gettoni d'Onore. I Gettoni li puoi spendere da Rin'wosho the Trader, che in cambio offre ai nostri eroi oggetti speciali.",
  reward = "Eccellente — questa serie di monete sarà un'ottima aggiunta alla nostra collezione, che cresce sempre di più... e che useremo per difendere la tribù dall'ascesa del Dio del Sangue. Questo Gettone d'Onore te lo sei $Gguadagnato:guadagnata;, $N, e con lui anche la gratitudine della tribù!",
}
T[8196] = {
  title = "Essenze di Mango",
  progress = "La potentissima essence mango cresce su molte isole dei South Seas. Basta un mango solo per ristorare corpo e mente di chi lo mangia. Se non ne hai mai assaggiato uno, fai un torto a te $Gstesso:stessa;!$B$BQui sull'isola ne abbiamo abbastanza da potertene dare una manciata in cambio di uno Zandalar Honor Token. Se vuoi sapere come si ottengono gli emblemi, parla con Vinchaxa; se no, passiamo agli affari!",
  reward = "Scambio onesto, $Gamico mio:amica mia; — goditi i frutti succosi dei South Seas, con la benedizione della tribù.",
}
T[8201] = {
  title = "Una Collezione di Teste",
  desc = "È vero. Ora Hakkar dimora a Zul'Gurub, immerso nel potere dei nostri dèi. Dei sommi sacerdoti soggiogati incanalano nel Soulflayer le energie delle nostre divinità più sacre, e presto diventerà più forte di qualsiasi essere di Azeroth. Va fermato!$B$BPrendi questa sacred cord e infilaci le teste dei sommi sacerdoti che stanno incanalando l'energia dei nostri dèi.$B$BFatto questo, torna da me.",
  obj = "Infila 5 Channeler's Heads, poi riporta la Collezione di Teste di Troll a Exzhal su Yojamba Isle.",
  progress = "Hai la collezione di teste, $N? Dobbiamo impedire ad Hakkar di prendere altro potere!",
  reward = "Hai preso le teste! Hai messo fine al saccheggio del potere dei nostri dèi e indebolito Hakkar!$B$BQuello che hai fatto è davvero eroico, $N. Possano le teste di questi troll schiavi implorarti pietà ancora a lungo, quando il loro sangue sarà ormai freddo.",
}
T[8221] = {
  title = "Pesce Raro — Keefer's Angelfish",
  progress = "*Ronzio* *Clic*$B$BIl Maestro Pescatore Bluegill deve catalogare dei pesci rari, e io li sto cercando. Se mi porti un Keefer's Angelfish, questa ottima ricompensa sarà tua.$B$B*Zzzap* *Ronzio*",
  reward = "*Ronzio*$B$BIdentificazione del Keefer's Angelfish completata.$B$BLa tua Ricompensa è ora disponibile.$B$B*clic-clic* *Bzzzz*",
}
T[8222] = {
  title = "Glowing Scorpid Blood",
  progress = "In tutto il tempo che ho lavorato alla Fiera ho imparato un sacco di cose sui clienti, e te ne dico una, una perla di saggezza: i clienti adorano la roba che brilla! Non importa cosa sia — prendi la gamba rotta di una sedia, falla brillare, e tutti i bambini farebbero miglia e miglia per averne una!$B$BEcco perché, $N, mi serve un po' di glowing scorpid blood. Lo prendi dagli scorpidi di Silithus, delle Blasted Lands o delle Burning Steppes.",
  reward = "Ottimo lavoro, $N! Grazie mille! Con questo sangue ci faccio una vernice, e ogni genere di cianfrusaglia da quattro soldi diventerà un tesoro che brilla!$B$BEcco i tuoi biglietti. E grazie ancora!",
}
T[8223] = {
  title = "Altro Glowing Scorpid Blood",
  progress = "Il sangue di scorpide funziona alla grande, $N! È incredibile come un pizzico di luccichio e di splendore possa trasformare in un ninnolo prezioso quello che altrimenti sarebbe solo un pezzo di ciarpame. I clienti amano questa roba, e alla fine è tutta una questione d'amore, non credi...$B$BMi sei $Gstato:stata; di grande aiuto, $N, e anche se non ho molto bisogno di altro glowing scorpid blood, se me ne porti ancora ti darò comunque qualche biglietto.",
  reward = "Grazie ancora, $N. Ecco i biglietti!",
}
T[8224] = {
  title = "Pesce Raro — Dezian Queenfish",
  progress = "*Ronzio* *Clic*$B$BIl Maestro Pescatore Bluegill deve catalogare dei pesci rari, e io li sto cercando. Se mi porti un Dezian Queenfish, questa ottima ricompensa sarà tua.$B$B*Zzzap* *Ronzio*",
  reward = "*Ronzio*$B$BIdentificazione del Dezian Queenfish completata.$B$BLa tua Ricompensa è ora disponibile.$B$B*clic-clic* *Bzzzz*",
}
T[8225] = {
  title = "Pesce Raro — Brownell's Blue Striped Racer",
  progress = "*Ronzio* *Clic*$B$BIl Maestro Pescatore Bluegill deve catalogare dei pesci rari, e io li sto cercando. Se mi porti un Brownell's Blue Striped Racer, questa ottima ricompensa sarà tua.$B$B*Zzzap* *Ronzio*",
  reward = "*Ronzio*$B$BIdentificazione del Pesce Striato di Brownell completata.$B$BLa tua Ricompensa è ora disponibile.$B$B*clic-clic* *Bzzzz*",
}
T[8227] = {
  title = "Nat's Measuring Tape",
  desc = "Fra le esche da pesca e l'attrezzatura ridotte a pezzi c'è un nastro da misura di seta, arrotolato, con attaccata un'etichetta che dice:$B$B\"Nat Pagle, Dustwallow Marsh.\"",
  obj = "Riporta il Nat's Measuring Tape a Nat Pagle in Dustwallow Marsh.",
  progress = "Ehilà, $Gragazzo:ragazza;. Sei qui a pescare un po'?",
  reward = "Ma guarda, hai trovato il mio nastro da misura preferito! Quanto lo adoro! Ci ho misurato alcuni dei pesci più grossi che abbia mai preso...$B$BSolo che l'ho perso a Zul'Gurub... ci sei $Gstato:stata;, a Zul'Gurub? Hai visto il leggendario Gahz'ranka?$B$BBeh... ti va di catturarlo?",
}
T[8228] = {
  title = "Potrei Avere un Volantino sulla Pesca?",
  reward = "Questa domenica a Booty Bay c'è una Gara di Pesca! Se vuoi partecipare, eccoti le regole del torneo!",
}
T[8229] = {
  title = "Potrei Avere un Volantino sulla Pesca?",
  reward = "'Sta domenica a Booty Bay c'è una Gara di Pesca! Ecco qua le regole per te!",
}
T[8231] = {
  title = "Caccia ai Wavethrasher",
  desc = "Il wavethrasher è una bestia anfibia che vive solo qui ad Azshara: creature potenti e resistenti.$B$BLe scaglie di un wavethrasher, dure e riflettenti, rispecchiano la forza del cacciatore.$B$BSegui le tracce dei wavethrashers lungo la costa di Azshara, dagli la caccia e portami le loro scaglie.",
  obj = "Porta 6 Wavethrasher Scales a Ogtinc ad Azshara. Ogtinc vive in cima alle scogliere a nordest delle Ruins of Eldarath.",
  progress = "Ce l'hai fatta?",
  reward = "Non è facile sconfiggere i wavethrashers, e in acqua lo è ancora meno.$B$BHai dimostrato che sei $Gpronto:pronta; a cacciare prede ancora più letali.",
}
T[8232] = {
  title = "Il Drake Verde",
  desc = "Ora ti affido una caccia pericolosa: uccidi Morphaz, il drake verde, e portami il suo dente. Morphaz vive nelle profondità del Temple of Atal'Hakkar, che ha l'ingresso nella Swamp of Sorrows.$B$BSe vuoi sconfiggerlo, non devi andarci $Gsolo:sola;. Questo drake ha molti nemici — cerca altri che vogliano distruggerlo.$B$BIl dente del drake rappresenta il potere che un cacciatore troverà in compagnia degli altri. Portamelo, e avrai imparato molto.",
  obj = "Porta il Tooth of Morphaz a Ogtinc ad Azshara. Ogtinc vive in cima alle scogliere a nordest delle Ruins of Eldarath.",
  progress = "Vedo saggezza nei tuoi occhi, $N. Hai finito la tua caccia?",
  reward = "Hai imparato le antiche usanze, $N, e per questo ti offro un dono di quando ero $C.",
}
T[8233] = {
  title = "Una Semplice Richiesta",
  desc = "Lord Jorach Ravenholdt vuole vederti. È una faccenda segreta, e non posso dirti altro.$B$BIl Ravenholdt Manor è nelle Hillsbrad Foothills — cerca un sentiero fra le montagne a nord-ovest del Durnhold Keep.",
  obj = "Parla con Lord Jorach Ravenholdt in Ravenholdt Manor.",
  reward = "$GBenvenuto:Benvenuta;, $Gbenvenuto:benvenuta;, $Gbenvenuto:benvenuta;! Prego, $N, siediti: parliamo di una semplice questione.$B$BVedi, $N, di recente ho perso una cosa a cui tengo molto e, per dirla chiara, la rivoglio a ogni costo. Non preoccuparti, ci sarà qualcosa anche per te! Oh sì, qualcosa di molto bello.$B$BAllora, $N, che ne dici... sei $Gpronto:pronta; per un'avventura?",
}
T[8234] = {
  title = "Sealed Azure Bag",
  desc = "Andiamo con ordine. Ho perso una piccola sacca azzurra, e cosa ci sia dentro è una faccenda privata.$B$BNon perdere tempo a dare la caccia ai ladri: sono già morti. Sappiamo che quegli sciocchi non sono riusciti ad aprirla, così l'hanno venduta come reliquia sacra a uno sciamano timbermaw ad Azshara. Furbi.$B$BHo bisogno che tu vada ad Azshara e riprenda la sacca allo sciamano con discrezione... o con la forza. Scommetto che col primo metodo avrai più fortuna. Quando l'avrai presa, portala ad Archmage Xylem.",
  obj = "Recupera la Sealed Azure Bag dal Timbermaw Shaman ad Azshara. Poi porta la sacca ad Archmage Xylem, che si trova anche lui ad Azshara.",
  progress = "Ci conosciamo?",
  reward = "Vedo che hai con te la sacca di Lord Ravenholdt. Perché non l'hai detto subito, $Gragazzo:ragazza;?",
}
T[8235] = {
  title = "Encoded Fragments",
  desc = "Lord Ravenholdt ha chiesto un favore a tutti e due: vuole togliere l'incantamento da questa sacca.$B$BPurtroppo, di recente mi hanno rubato alcuni libri su come dissolvere gli incantesimi, e dei selvaggi li hanno distrutti. Quel che ne resta, per me, ha ancora valore.$B$BSe riesci a portarmi abbastanza encoded fragments, posso rimetterli insieme. Ti conviene uccidere le forest oozes, che tendono a raccogliere quasi di tutto. Le trovi nella parte nord-orientale di Azshara.",
  obj = "Porta 10 Encoded Fragments ad Archmage Xylem ad Azshara.",
  progress = "Hai trovato abbastanza frammenti per andare avanti col mio lavoro?",
  reward = "A quanto pare hai raccolto alcuni dei frammenti migliori. Forse, dopotutto, non sei $Gun buono:una buona; a nulla.",
}
T[8236] = {
  title = "L'Azure Key",
  desc = "Per decifrare i frammenti e togliere l'incantamento ci vorrà del tempo. Quando avrò finito, porterò io stesso la sacca a Lord Ravenholdt.$B$BResta ancora la questione della chiave: si dice che la custodisca un drake verde chiamato Morphaz. Il drake si è stabilito nelle profondità del Temple of Atal'Hakkar, che ha l'ingresso nella Swamp of Sorrows.$B$BRaduna i tuoi amici e addentrati nella sua tana. Lord Ravenholdt aspetterà che torni con la chiave.",
  obj = "Riporta l'Azure Key a Lord Jorach Ravenholdt.",
  progress = "La sacca mi è già arrivata da Archmage Xylem, hai trovato la chiave?",
  reward = "La chiave! Pensavo di averla persa per sempre. Ti prego, prendi uno degli indumenti incantati che tengo da parte — li riservo ai ladri di straordinaria abilità e lealtà. Che tutti sappiano che con $N non si scherza!$B$B<Jorach apre la sacca e lo inonda un bagliore dorato che viene dall'interno. Spalanca gli occhi e fissa...>",
}
T[8238] = {
  title = "Gurubashi, Vilebranch e Witherbark Coins",
  progress = "Cerco i Paragoni del Potere che chiamano Monete delle Tribù. Sono la valuta dei vari abitanti di Zul'Gurub, e ognuna è intrisa di un mojo sottile ma potente.$B$BNe esistono nove tipi. I miei compatrioti ne cercano alcune per le varie armature che offrono agli eroi Zandalar. Se te ne avanza qualcuna, per una serie di tre ti darò uno dei nostri Gettoni d'Onore. I Gettoni li puoi spendere da Rin'wosho the Trader, che in cambio offre ai nostri eroi oggetti speciali.",
  reward = "Eccellente — questa serie di monete sarà un'ottima aggiunta alla nostra collezione, che cresce sempre di più... e che useremo per difendere la tribù dall'ascesa del Dio del Sangue. Questo Gettone d'Onore te lo sei $Gguadagnato:guadagnata;, $N, e con lui anche la gratitudine della tribù!",
}
T[8239] = {
  title = "Sandfury, Skullsplitter e Bloodscalp Coins",
  progress = "Cerco i Paragoni del Potere che chiamano Monete delle Tribù. Sono la valuta dei vari abitanti di Zul'Gurub, e ognuna è intrisa di un mojo sottile ma potente.$B$BNe esistono nove tipi. I miei compatrioti ne cercano alcune per le varie armature che offrono agli eroi Zandalar. Se te ne avanza qualcuna, per una serie di tre ti darò uno dei nostri Gettoni d'Onore. I Gettoni li puoi spendere da Rin'wosho the Trader, che in cambio offre ai nostri eroi oggetti speciali.",
  reward = "Eccellente — questa serie di monete sarà un'ottima aggiunta alla nostra collezione, che cresce sempre di più... e che useremo per difendere la tribù dall'ascesa del Dio del Sangue. Questo Gettone d'Onore te lo sei $Gguadagnato:guadagnata;, $N, e con lui anche la gratitudine della tribù!",
}
T[8240] = {
  title = "Un Bijou per Zanza",
  desc = "Per noi distruggere i vari Bijous degli Hakkari conta così tanto che siamo felici di lasciarlo fare anche a chi non è della tribù!$B$BPrendi uno qualsiasi dei bijous che trovi a Zul'Gurub, portalo all'Altar of Zanza e distruggilo. Solo per questa volta, oltre a ciò che riceveresti di solito, ti darò un Gettone d'Onore in più della nostra tribù.$B$BGuarda con i tuoi occhi le benedizioni di Zanza!",
  obj = "Distruggi uno qualsiasi dei Bijous degli Hakkari trovati a Zul'Gurub presso l'Altar of Zanza su Yojamba Isle. Poi parla con Vinchaxa lì vicino.",
  progress = "Hai distrutto il bijou all'Altar of Zanza? Fallo, e sarai $Gbenedetto:benedetta; due volte da Zanza!",
  reward = "Eccellente... ogni bijou che strappiamo ai servitori del Dio del Sangue ci avvicina di un passo alla loro sconfitta definitiva. Le tue nobili azioni fanno onore agli Zandalar — e a te $Gstesso:stessa;.$B$BRicorda, $N: i bijous che trovi a Zul'Gurub puoi sempre distruggerli all'altare, e ognuno ti varrà riconoscimento e un Gettone d'Onore! Se non hai già un gettone, assicurati solo di avere uno spazio libero nell'inventario.",
}
T[8241] = {
  title = "Ripristinare le Scorte di Fiery Flux con il Ferro",
  progress = "Basta sprecare il mio prezioso tempo in chiacchiere, $R. Le nostre scorte di fiery flux stanno finendo, ed è ora di pensare a rifornirle.$B$BEcco cosa mi devi portare:$B$B*Scaglie di Incendosaur.$B$B*Iron bars.$B$B*Coal.$B$BPrendo tutto quello che riesci a darmi!$B$BE vedi di sbrigarti, se vuoi entrare nelle grazie della Confraternita.",
  reward = "Per altro fiery flux c'è sempre posto, $Gpivello:pivella;. Continua a portarne... a meno che non ti dica basta.",
}
T[8242] = {
  title = "Ripristinare le Scorte di Fiery Flux con l'Heavy Leather",
  progress = "Basta sprecare il mio prezioso tempo in chiacchiere, $R. Le nostre scorte di fiery flux stanno finendo, ed è ora di pensare a rifornirle.$B$BEcco cosa mi devi portare:$B$B*Scaglie di Incendosaur.$B$B*Heavy Leather.$B$B*Coal.$B$BPrendo tutto quello che riesci a darmi!$B$BE vedi di sbrigarti, se vuoi entrare nelle grazie della Confraternita.",
  reward = "Per altro fiery flux c'è sempre posto, $Gpivello:pivella;. Continua a portarne... a meno che non ti dica basta.",
}
T[8243] = {
  title = "Le Potenti Bevande di Zanza",
  progress = "Adesso che nella tribù hai più prestigio, puoi avere alcune delle nostre bevande più potenti. Ammira... questi infusi sono pieni di mojo — benedetti da Zanza e buoni per avventurieri di ogni tipo!$B$BTe ne lascio scegliere uno dei tre che ho; in cambio, ti chiedo uno Zandalar Honor Token. Bada però: nel tuo spirito può scorrere l'effetto di uno solo alla volta.$B$BQuando sei $Gpronto:pronta; per uno scambio, fammelo sapere!",
  reward = "Scambio onesto, $Gamico mio:amica mia; — goditi le benedizioni di Zanza, con i nostri omaggi!",
}
T[8246] = {
  title = "Sigilli degli Zandalar",
  progress = "$N — tu che sei così $Gosannato:osannata; fra gli Zandalar, per te ho qualcosa di molto speciale. Dritti dalla nostra patria nei South Seas... i Sigilli degli Zandalar! Questi sigilli potenziano qualunque oggetto per le spalle tu abbia. Che tu cerchi potenza, mojo o serenità — ho quello che fa per te!$B$BPer un sigillo a tua scelta chiedo quindici Zandalar Honor Tokens. Se gli emblemi li hai pronti, io sono pronto a chiudere l'affare!",
  reward = "Scambio onesto, $Gamico mio:amica mia; — prendi il tuo sigillo, con la benedizione della tribù!",
}
T[8249] = {
  title = "Cercasi Cofanetti",
  progress = "I miei ladri devono fare pratica con i grimaldelli, e mi servono serrature all'altezza — quella roba che ci fabbrica Zan va bene giusto per i principianti più infimi.$B$BFacciamo così: portami 5 Heavy Junkboxes e ti darò alcuni dei migliori coltelli da lancio che il popolo dei ladri conosca.$B$BI cofanetti puoi scassinarli e frugarci dentro, ma almeno qualche moneta dovrai lasciarcela... anche a un apprendista ladro serve un incentivo.",
  reward = "Che questi coltelli trovino posto nel cuore di qualcuno.$B$BLetteralmente.",
}
T[8250] = {
  title = "Arte Magica",
  desc = "Ultimamente Archmage Xylem va chiedendo in giro... di qualcuno con la tua esperienza.$B$BSe vuoi cercarlo, è ad Azshara. La sua torre sta in cima alle scogliere, e ci si sale solo con un incantesimo di teletrasporto che lancia il suo arrogante servitore, Sanath Lim-yo.$B$BSanath è accampato sotto la torre del padrone. Per trovarlo, segui la strada principale di Azshara fino al bivio all'ingresso delle Ruins of Eldarath. Da lì vai dritto verso nord, finché non arrivi alle scogliere.",
  obj = "Cerca Sanath Lim-yo e fatti portare da Archmage Xylem.",
  reward = "<Sanath ti guarda con un ghigno di scherno.>$B$BArchmage Xylem ti attende.",
}
T[8251] = {
  title = "Magic Dust",
  desc = "Gli elfi del sangue di Azshara hanno trovato il modo di ridurre in polvere gli oggetti magici che si procurano. La glittering dust che ne ricavano non è come i componenti che dà di solito un incantesimo di disincanto.$B$BHo mandato il mio apprendista a trattare per averla, e l'hanno ucciso senza pensarci due volte. Per questo devono pagare.$B$BIl tempo delle parole è finito, $N. Trova gli elfi del sangue lungo le scogliere di Azshara e prenditi la loro glittering dust con metodi più \"persuasivi\".",
  obj = "Porta 10 Glittering Dust ad Archmage Xylem.",
  progress = "Hai portato la polvere?",
  reward = "Ben fatto, $N! Non finisce mai di stupirmi quanto sappia essere persuasiva una raffica di dardi arcani.",
}
T[8252] = {
  title = "Il Corallo della Sirena",
  desc = "Guardati intorno. Gli spitelash hanno invaso le rovine e le spiagge, e da poco quelle miserabili creature hanno imparato a riconoscere i rari componenti originari di Azshara.$B$BParlo in particolare dell'enchanted coral — ne sono attratte per motivi che non conosco. Ormai nella baia ne è rimasto poco, e per le mie ricerche è fondamentale. Ho bisogno che tu tolga un po' di enchanted coral alle spitelash sirens e me lo porti.",
  obj = "Raccogli 6 Enchanted Coral e portali ad Archmage Xylem.",
  progress = "Le spitelash sirens sono maghe sorprendentemente abili. Ma non quanto te, spero?",
  reward = "Questo corallo è un esemplare magnifico, $N. Non c'è dubbio: le tue capacità sono precise e letali.$B$BNon credere che i tuoi sforzi siano passati inosservati. Forse sei $Gdegno:degna; di una vera prova della tua abilità...",
}
T[8253] = {
  title = "Distruggi Morphaz",
  desc = "Nelle profondità del tempio sommerso di Atal'Hakkar c'è un drake verde di nome Morphaz.$B$BAnni fa mi ha sopraffatto con un'imboscata audace e ha divorato intero il mio apprendista. Non è certo la prima volta che perdo un apprendista, ma quello portava con sé un'arcane shard di dimensioni e qualità senza pari.$B$BDovrai radunare alleati potenti e addentrarti nel tempio. Distruggi Morphaz e recupera l'arcane shard dal suo stomaco senza età.",
  obj = "Recupera l'Arcane Shard da Morphaz e torna da Archmage Xylem.",
  progress = "Hai ucciso la mia vecchia nemesi?",
  reward = "Incredibile. In tutti questi anni la scheggia ha assorbito l'energia del drake ed è cresciuta.$B$BOra non posso chiederti altro. Con questa scheggia ho ritrovato in pieno la capacità di forgiare l'arcano. La mia prima creazione è tua, $N, e non ti resta che scegliere...",
}
T[8254] = {
  title = "In soccorso di Cenarion",
  desc = "E' nella natura del divino aiutare chi ha bisogno. Come lo fa è insignificante — conta solo il perché.$B$BTra i bisognosi c'è il Cenarion Circle. Se vuoi aiutarli nelle loro difficoltà parla con Ogtinc: lo trovi in cima alle scogliere a nord-est delle Ruins of Eldarath, ad Azshara.",
  obj = "Cerca Ogtinc ad Azshara.",
  reward = "Ora che sei $Garrivato:arrivata;, mi sono tolto un peso dalle spalle. Abbiamo molto da fare.",
}
T[8255] = {
  title = "Corsieri e Ricorsieri",
  desc = "I mosshoof coursers di Azshara sono animali magnifici che un tempo vivevano a Felwood. Per natura resistono a malattie e veleni, la corruzione di quel luogo li ha lasciati intatti: nella loro saggezza ancestrale, decisero semplicemente di andarsene da quella terra malata.$B$BMi piange il cuore, ma devo chiederti di cacciare per me queste possenti bestie. Raccoglimi quattro ghiandole di cervo, il primo ingrediente di un unguento ristoratore — lo useremo per guarire Felwood.",
  obj = "Procurati 4 Healthy Courser Glands e portale a Ogtinc ad Azshara. Ogtinc risiede in cima alle scogliere a nord-est di Ruins of Eldarath.",
  progress = "Sei $Gtornato:tornata;. Ce l'hai fatta?",
  reward = "Per fortuna il percorso divino ti ha portato da noi, $N. Il tuo credo non ti impedisce di fare ciò che è necessario per preparare questo unguento.$B$BVedi, per il Cenarion Circle il corsiero è sacro. Ucciderne uno, per qualunque motivo e per quanto sia necessario, indebolisce il loro spirito.",
}
T[8256] = {
  title = "L'Ichor of Undeath",
  desc = "Per questo unguento ristoratore la formula da seguire è semplice: una parte di veleno e due di cura. Una cura ce l'hai; ora devi raccogliere il veleno.$B$BI non morti potenti, come il lingering highborne che si aggira fra le Ruins of Eldarath, a volte sono così impregnati di male che questo si condensa in una melma verdastra e malsana, che i vivi chiamano ichor of undeath.$B$BQuesta sostanza ripugnante è così potente che mi basta un solo icore.",
  obj = "Procurati un Ichor of Undeath per Ogtinc ad Azshara. Ogtinc risiede in cima alle scogliere a nord-est di Ruins of Eldarath.",
  progress = "Ci serve l'icore, e in fretta. L'hai trovato?",
  reward = "Non posso dire che mi faccia piacere ricevere una sostanza così orribile, ma è un male necessario. Grazie, $N.",
}
T[8257] = {
  title = "Blood of Morphaz",
  desc = "Ora manca l'ultima parte, la seconda cura.$B$BIl drake verde Morphaz, come si sa, è immune a qualsiasi veleno e malattia — molti druidi sono morti per scoprirlo. Il suo sangue è senza dubbio sufficientemente potente per quello che ci serve.$B$BMentre tu recuperi l'ultima parte, un corriere del Cenarion Circle prenderà quelle che hai già raccolto. Chiama i tuoi alleati e va' a cercare la tana del drake nel tempio sommerso di Atal'Hakkar. Porta il suo sangue a Greta Mosshoof, a Felwood.",
  obj = "Uccidi Morphaz nel tempio sommerso di Atal'Hakkar e porta il suo sangue a Greta Mosshoof a Felwood. L'ingresso del tempio sommerso si trova nella Swamp of Sorrows.",
  progress = "Hai il sangue di Morphaz?",
  reward = "Hai ucciso Morphaz e ci hai portato il suo sangue... Una notizia così bella che stento a crederci!$B$BMetteremo subito insieme gli ingredienti e cominceremo a guarire gli alberi e le creature di Felwood. Per rimediare a quello che è successo qui ci vorrà una vita intera, ma tu ci hai fornito i mezzi per farlo.",
}
T[8258] = {
  title = "La Minaccia di Darkreaver",
  desc = "Death Knight Darkreaver regna sul Great Ossuary, nella Scholomance, e minaccia di piegare il regno degli spiriti al suo volere: va fermato! Ed è qui che entra in gioco il veggente che mi hai aiutato a costruire.$B$BUsa il divination scryer nel cuore del sotterraneo del Great Ossuary ed evocherai gli spiriti servitori di Darkreaver. Sconfiggili, e il cavaliere della morte comparirà in persona. Portami la sua testa, $N! Solo la sua morte potrà rimediare al danno inflitto al regno degli spiriti!",
  obj = "Usa il Divination Scryer nel cuore del sotterraneo del Great Ossuary nella Scholomance. Così facendo compariranno degli spiriti che dovrai combattere. Sconfitti gli spiriti, verrà evocato Death Knight Darkreaver; sconfiggilo.$B$BPorta la Darkreaver's Head a Sagorne Creststrider in Valley of Wisdom, Orgrimmar.",
  progress = "Il tempo stringe, $N — sei $Griuscito:riuscita; a fermare la minaccia di Death Knight Darkreaver?",
  reward = "Questa è una vittoria da assaporare, $N! Con la morte di Darkreaver dovrebbero ristabilirsi i fragili legami che tengono ancorato il regno degli spiriti.$B$BHai fatto molto più di quello che ti si chiedeva, anche quando non sapevi nulla di ricompense o compensi. Sei davvero $Guno:una; Shaman di valore, $Gamico mio:amica mia;.$B$BSo che agire in difesa del regno degli spiriti dovrebbe bastare come ringraziamento, ma ti prego — accetta questo semplice dono, con la mia gratitudine.",
}
T[8259] = {
  title = "Una Ricompensa Più Adatta",
  reward = "Ah, $N... il tuo impegno contro Darkreaver è stato straordinario — e meritava, se posso dirlo, una ricompensa ben migliore di quella che hai avuto. Ti prego, accetta quest'elmo come dono in più per le tue imprese nella Scholomance.$B$BGrazie ancora.",
}
T[8260] = {
  title = "Arathor Basic Care Package",
  reward = "Di certo hai cominciato a dimostrarci quanto vali, $N. Come ricompensa, eccoti questo kit curativo! Dentro ci sono razioni e bende, ma si possono usare solo nell'Arathi Basin.$B$BMan mano che ti farai valere nel Basin, potrai comprare questi oggetti: le razioni quando sarai Amichevole con noi, le bende quando sarai $GOnorato:Onorata;.",
  en_title = "Arathor Basic Care Package",
}
