T[8263] = {
  title = "Defiler's Basic Care Package",
  reward = "Non c'è dubbio, $N: hai cominciato a dimostrarci quanto vali. Prendi questo kit curativo come ricompensa! Dentro ci sono razioni e bende, ma potrai usarle solo nell'Arathi Basin.$B$BMan mano che ti farai valere nel Basin, potrai comprare questi oggetti: le razioni quando sarai Amichevole con noi, le bende quando sarai $GOnorato:Onorata;.",
  en_title = "Defiler's Basic Care Package",
}
T[8264] = {
  title = "Defiler's Standard Care Package",
  reward = "Hai di certo cominciato a dimostrarci quanto vali, $N. Come ricompensa, prendi questo kit curativo! Dentro ci sono razioni e bende che si possono usare solo nell'Arathi Basin.$B$BMan mano che ti farai valere nel Basin, potrai acquistare questi oggetti. Le razioni diventano disponibili quando sei Amichevole con noi, le bende quando sei $GOnorato:Onorata;.",
}
T[8265] = {
  title = "Defiler's Advanced Care Package",
  reward = "Hai di certo cominciato a dimostrarci quanto vali, $N. Come ricompensa, prendi questo kit curativo! Dentro ci sono razioni e bende che si possono usare solo nell'Arathi Basin.$B$BMan mano che ti farai valere nel Basin, potrai acquistare questi oggetti. Le razioni diventano disponibili quando sei $GOnorato:Onorata; con noi, le bende quando sei $GReverito:Reverita;.",
}
T[8266] = {
  title = "Nastri del Sacrificio",
  progress = "So che a volte avere la meglio a Warsong Gulch può essere difficile. Ma il tuo impegno per noi è importante, anche quando la vittoria non arriva.$B$BSe completi una delle prove a Warsong Gulch senza vincere, riceverai comunque dei Nastri del Sacrificio. Portali a me, così le Sentinelle potranno ricompensarti per esserti $Gspeso:spesa; per noi... anche se stavolta non ce l'hai fatta.",
  reward = "Be', davanti alla sconfitta non sei $Gfuggito:fuggita;. Hai tenuto duro, $N, ed è questo, alla fine dei conti, che fa di te $Gun vero eroe:una vera eroina;. La prossima volta vincerai di sicuro... ma ti ringraziamo comunque dell'impegno.",
  en_title = "Ribbons of Sacrifice",
  en_obj = "Bring the Ribbons of Sacrifice to Captain Shatterskull so that the Outriders may reward you for acting on our behalf.",
}
T[8268] = {
  title = "Nastri del Sacrificio",
  progress = "So che a volte avere la meglio a Warsong Gulch può essere difficile. Ma il tuo impegno per noi è importante, anche quando la vittoria non arriva.$B$BSe completi una delle prove a Warsong Gulch senza vincere, riceverai comunque dei Nastri del Sacrificio. Portali a me, così gli Outriders potranno ricompensarti per esserti $Gspeso:spesa; per noi... anche se stavolta non ce l'hai fatta.",
  reward = "Be', davanti alla sconfitta non sei $Gfuggito:fuggita;. Hai tenuto duro, $N, ed è questo, alla fine dei conti, che fa di te $Gun vero eroe:una vera eroina;. La prossima volta vincerai di sicuro... ma ti ringraziamo comunque dell'impegno.",
  en_title = "Ribbons of Sacrifice",
  en_obj = "Bring the Ribbons of Sacrifice to Sentinel Farsong so that the Sentinels may reward you for acting on our behalf.",
}
T[8271] = {
  title = "Eroe degli Stormpike",
  reward = "Tu che sei $Gun eroe:un'eroina; degli Stormpike puoi sceglierti un oggetto fra questi tesori appena saccheggia... ehm, recuperati.",
}
T[8272] = {
  title = "Eroe dei Frostwolf",
  reward = "Che effetto fa, $N? Che effetto fa schiacciare i nemici e vedere le loro linee andare in pezzi? Bello, vero?$B$BPer un'impresa eroica come questa ti meriti una ricompensa, soldato.",
}
T[8273] = {
  title = "La Gratitudine di Oran",
  reward = "Be', interessante, no? Dici di aver trovato questa tavoletta su un'isoletta deserta a The Overlook Cliffs, in The Hinterlands, $C? Davvero molto interessante. <Oran ripone con cura la tavoletta e si sfrega le mani.>$B$BGrazie dell'impegno che hai messo in questa faccenda. La nostra Dama Oscura sarà molto compiaciuta della scoperta. Ecco, lascia che ti ricompensi come meriti.",
}
T[8275] = {
  title = "Riconquistare Silithus",
  desc = "Attenzione, eroi dell'Alleanza! Da troppo tempo nessuno contrasta la minaccia dei silithid. Senza trovare una vera opposizione, hanno passato tutto questo tempo a prepararsi a espandersi su larga scala.$B$BLe forze del Cenarion Circle si stanno radunando a Silithus per dare battaglia a queste spregevoli creature, e chiamiamo a unirsi a noi tutti gli avventurieri in grado di combattere!$B$BNon aspettate che sia troppo tardi! Aiutateci a difendere Azeroth! Presentatevi a Windcaller Proudhorn, a Cenarion Hold, e avrete istruzioni precise!",
  obj = "Parla con Windcaller Proudhorn a Cenarion Hold, in Silithus.",
  reward = "Eccellente, una nuova recluta risponde alla chiamata alle armi contro i silithid. $GBenvenuto:Benvenuta; a Cenarion Hold, $C. Mi fa piacere vedere che le parole dei nostri emissari arrivano fino a eroi del tuo calibro. Qui le occasioni per aiutarci non ti mancheranno, e mi aspetto che presto ti dimostrerai $Gun prezioso alleato:una preziosa alleata; per la nostra causa.",
}
T[8276] = {
  title = "Riconquistare Silithus",
  desc = "Attenzione, campioni dell'Orda! C'è una minaccia che abbiamo lasciato incontrastata troppo a lungo. In tutta Azeroth il terreno trema vicino agli alveari dei silithid, e quelle scosse ci hanno avvertito: si stanno muovendo in gran numero e si preparano a espandersi.$B$BLe forze del Cenarion Circle si stanno radunando a Silithus per dare battaglia ai silithid prima che sia troppo tardi! Non profaneranno mai più le nostre terre!$B$BChiunque sia in grado di combattere deve presentarsi a Windcaller Proudhorn, a Cenarion Hold! I silithid saranno sconfitti!",
  obj = "Parla con Windcaller Proudhorn a Cenarion Hold, in Silithus.",
  reward = "Eccellente, una nuova recluta risponde alla chiamata alle armi contro i silithid. $GBenvenuto:Benvenuta; a Cenarion Hold, $C. Mi fa piacere vedere che le parole dei nostri emissari arrivano fino a eroi del tuo calibro. Qui le occasioni per aiutarci non ti mancheranno, e mi aspetto che presto ti dimostrerai $Gun prezioso alleato:una preziosa alleata; per la nostra causa.",
}
T[8277] = {
  title = "Veleno Letale del Deserto",
  desc = "Beetix Ficklespragg, al tuo servizio! Mio cugino Noggle campa raccogliendo erbe rare per gli alchimisti della Cenarion Hold. O almeno, campava: dall'ultimo viaggio è tornato con un veleno potente che gli scorre nelle vene.$B$BSono riuscita a rallentarlo, ma per neutralizzarlo del tutto mi servono campioni del veleno della creatura che l'ha punto.$B$BNoggle è arrivato da nord, quindi ci scommetterei la testa: sono stati gli stonelash scorpids o i sand skitterers. Portami un po' di pungiglioni e di zanne, e proverò a preparargli un antidoto.",
  obj = "Beetix Ficklespragg a Cenarion Hold, in Silithus, vuole che tu raccolga 8 Stonelash Scorpid Stingers e 8 Sand Skitterer Fangs. Torna da lei quando avrai finito.",
  progress = "Allora, li hai raccolti tutti quei campioni? Da un momento all'altro potremmo perdere Noggle!",
  reward = "Incrocia le dita, $Gamico:amica;! Speriamo di farcela a salvare Noggle!",
}
T[8278] = {
  title = "L'Ultima Speranza di Noggle",
  desc = "Maledizione! L'antidoto non ha funzionato. Allora Noggle dev'essere stato punto da una delle creature più forti dell'estremo sud.$B$BMi serve che tu vada laggiù a prendermi altri campioni, $N. La buona notizia è che il loro veleno è più forte, quindi me ne serviranno di meno. La cattiva è che a sud strisciano creature velenose di più tipi, e i campioni dovrai prenderli da specie diverse.",
  obj = "Beetix Ficklespragg a Cenarion Hold, in Silithus, vuole che tu raccolga 3 Stonelash Pincer Stingers, 3 Stonelash Flayer Stingers e 3 Rock Stalker Fangs.",
  progress = "È la nostra ultima occasione per salvare Noggle! Sbrigati!",
  reward = "Sì! Sembra che funzioni: Noggle si sta riprendendo. Ti dobbiamo un favorone!",
}
T[8279] = {
  title = "Il Lessico del Crepuscolo",
  desc = "Il Twilight's Hammer non è tenero con chi abbandona le sue file: mi danno ancora la caccia, come se fossi una specie di bestia! Inutile dirlo, chi è loro nemico è mio amico!$B$BPer decifrare questa Tavoletta mi serve il libro che i loro scribi usano per cifrare i messaggi segreti: il Lessico del Twilight. Per loro è uno strumento così importante che ne tengono i tre capitoli in posti diversi! Gli ufficiali che hanno in custodia il Lessico si chiamano Twilight Keepers: cercali negli accampamenti del Twilight's Hammer.",
  obj = "Porta i tre capitoli del Lessico del Twilight a Hermit Ortell a Silithus.",
  progress = "Chi va là? Oh, sei tu! Hai già trovato tutti i capitoli del Lessico?",
  reward = "Sì! Queste sono le parti del libro! Allora, $N, cominciamo.$B$BScambia ogni terza parola con quelle del secondo capitolo... poi scambia una parola sì e una no con quelle del primo... Aspetta, o era il contrario?",
}
T[8280] = {
  title = "Proteggere le Linee di Rifornimento",
  desc = "Cenarion Hold ha un'importanza strategica enorme. Sono convinta che, finché lo terremo, la vittoria sui silithid sarà nostra. Sempre che riusciamo a far arrivare i rifornimenti, s'intende.$B$BPer le nostre carovane i vermi del deserto si sono rivelati un pericolo ancora più grande degli stessi silithid. Proprio stamattina un gruppo di dredge strikers ha devastato un grosso carico di morrowgrain. Ho bisogno che tu ne sfoltisca le file, così le scorte non correranno rischi.",
  obj = "Windcaller Proudhorn di Cenarion Hold, in Silithus, vuole che tu uccida 15 Dredge Strikers.",
  progress = "I dredge strikers sono una seria minaccia, e dobbiamo occuparcene in fretta!",
  reward = "Ti sono sinceramente grata. Aiutando Cenarion Hold hai mostrato un vero coraggio.",
}
T[8281] = {
  title = "Rafforzare la Sicurezza",
  desc = "Finora il tuo lavoro è stato davvero esemplare, $N. Però le nostre linee di rifornimento non sono ancora del tutto sicure. Ora che i dredge strikers non ci sono più, i loro cugini più grossi che vivono a sud saliranno di certo verso nord a prenderne il posto.$B$BPer tenerli a bada dovrai uccidere parecchi dredge crushers, ma quando ci sono di mezzo i rifornimenti non possiamo lasciare niente al caso.",
  obj = "Windcaller Proudhorn di Cenarion Hold, in Silithus, vuole che tu uccida 20 Dredge Crushers.",
  progress = "I dredge crushers sono una seria minaccia, e dobbiamo occuparcene subito!",
  reward = "Eccellente! Nei preparativi per la guerra contro i silithid ti sei $Gdimostrato:dimostrata; $Gun prezioso alleato:una preziosa alleata;.",
}
T[8282] = {
  title = "La Sacca Perduta di Noggle",
  desc = "Dove sono? Dov'è la mia sacca? *sussulto* Devo averla persa scappando da Deathclasp, lo scorpide gigante. Avevo così fretta di filarmela che sono finito dritto in un nido di stonelash flayers.$B$BNella sacca c'erano reagenti rari di ogni tipo, e senza quelli io e Beetix non potremo preparare le pozioni che servono a Cenarion Hold. Sono ancora troppo debole per alzarmi, ma se mi riporti i reagenti saprò ricompensarti.$B$BDeathclasp me lo sono trovato davanti nella catena montuosa a sud, dietro l'accampamento di Bronzebeard.",
  obj = "Recupera la Noggle's Satchel dalle montagne nel sud di Silithus e riportagliela a Cenarion Hold.",
  progress = "Non hai ancora trovato la mia sacca? Beh, dovrei ringraziare la mia buona stella: se non altro il veleno è stato eliminato.",
  reward = "Sì! Mi hai riportato la sacca, e ci sono tutti i miei reagenti rari! Ti sarò debitore a lungo.",
}
T[8283] = {
  title = "Ricercata — Deathclasp, Terrore delle Sabbie",
  desc = "Si ritiene che la terribile scorpide, Deathclasp, si sia ritirata sulla catena montuosa meridionale di fronte all'aumento dell'attività dei silithid. Rappresenta una grave minaccia per le pattuglie e le spedizioni nelle regioni del sud. Chi prenderà parte alla sua distruzione sarà lautamente ricompensato. Per informazioni sulla ricompensa, rivolgersi a Captain Vish Kozus, in cima alla Cenarion Hold Watchtower.",
  obj = "Porta la Deathclasp's Pincer a Vish Kozus, Capitano della Guardia.",
  progress = "Come prova dell'impresa mi servirà la chela della creatura. Niente chela, niente ricompensa.",
  reward = "Eccellente! Ora che Deathclasp non c'è più, possiamo usare liberamente la catena montuosa meridionale come via strategica per aggirare gli alveari dei silithid. Apprezziamo molto quello che hai fatto.",
}
T[8284] = {
  title = "Il Mistero del Crepuscolo",
  desc = "A nord-ovest di qui, un tempo, c'era un fiorente accampamento di cultisti del Twilight's Hammer. Se ti spingessi fin là adesso, troveresti la zona che brulica di elementali, e a indicare il punto dove sorgeva il campo non restano che pezzi di legno e di tela sparsi qua e là.$B$BSul posto ho recuperato qualche frammento di una tavoletta d'argilla, ma sono troppo pochi per ricostruirci qualcosa di utile. Vedi un po' se riesci a trovare i frammenti che mancano: così potremo fare un po' di luce sulla presenza del Twilight's Hammer qui a Silithus.",
  obj = "Geologist Larksbane alla Cenarion Hold di Silithus vuole che tu raccolga 8 Twilight Tablet Fragments.",
  progress = "L'accampamento devastato è a nord-ovest di qui. Torna quando avrai tutti i frammenti.",
  reward = "Proprio come sospettavo. Le parole sulle tavolette, una per una, riesco a decifrarle, ma sembrano non avere né logica né significato. Che le sette del Twilight's Hammer usino un codice per nascondere il senso dei loro testi non è una novità: dovremo rivolgerci a qualcuno che se ne intenda più di noi.",
}
T[8285] = {
  title = "Il Disertore",
  desc = "Si dice che un membro del Twilight's Hammer, un certo Ortell, abbia disertato la setta. Pare che si sia nascosto sulle montagne a sud di Southwind Village e che ci viva da eremita. Magari riesci a convincerlo ad aiutarti a decifrare la tavoletta.$B$BPrendi la tavoletta restaurata e va' a cercare Ortell.",
  obj = "Porta la tavoletta restaurata a Hermit Ortell a Silithus.",
  progress = "Tu! Come hai fatto a trovarmi? Chi sei? Non sei $Gstato seguito:stata seguita;, vero? Parla!",
  reward = "Vedo che conosci la mia vecchia organizzazione. Sarai della Cenarion Hold.$B$BCerchi informazioni da usare contro di loro? Vieni più vicino: forse possiamo aiutarci a vicenda.",
}
T[8286] = {
  title = "Ciò Che il Domani Porterà",
  desc = "L'abbraccio della morte aveva ormai quasi sopraffatto il mio essere, quando lui è intervenuto. Ha soffiato una volta sola sul mio corpo martoriato, poi ha atteso, paziente, che le sabbie del tempo mi purificassero le ferite.$B$B\"Per sempre resterai, se dovrai\": così ha detto, e quelle parole mi hanno vincolato come Guardiano.$B$BOra volgi lo sguardo al deserto. La seconda guerra è alle porte. Va' in cerca del luogo dove riposa il Bronzo: avventurati nelle Caverns of Time e scopri se il maestro ha fatto ritorno. Prima di procedere devo averne la certezza.",
  obj = "Avventurati in Caverns of Time, a Tanaris, e trova Anachronos, della Brood of Nozdormu.",
  progress = "Anachronos ha fatto ritorno?",
  reward = "È come dev'essere — il grande è risorto. La mia veglia giunge al termine...",
}
T[8287] = {
  title = "Uno Scopo Terribile",
  desc = "Bene, ci siamo... e sono informazioni piuttosto preziose, devo dire! Ho visto arrivare a Silithus le forze del Cenarion Circle: vogliono cacciare il Twilight's Hammer, vero? Questo li aiuterà.$B$BPorta questa pergamena al loro capo, Commander Mar'alith. Presto il Twilight's Hammer sarà sconfitto, e io sarò fuori dalle sue grinfie per sempre!",
  obj = "Porta la Pergamena della Tavoletta Decifrata a Commander Mar'alith.",
  progress = "Cosa mi porti, $N?",
  reward = "Sono informazioni davvero interessanti, $N. Fanno un po' di luce sulla presenza del Twilight's Hammer a Silithus, e senza dubbio ci aiuteranno nella lotta contro di loro. I tuoi sforzi avranno una generosa ricompensa, $C.",
}
T[8288] = {
  title = "Solo Uno Potrà Ascendere",
  desc = "Non c'è tempo da perdere! Bisogna trovare un eroe! Il compito che affido richiederà un esercito, ma dalla folla di aspiranti campioni soltanto uno potrà emergere e prendere su di sé il peso e la responsabilità di un alleato della Brood.$B$BNella tana del Signore di Roccianera si annida una bestia crudelissima: il Broodlord Lashlayer, che sorveglia le Halls of Strife e sbarra la strada verso il santuario interno di Nefarian. Uccidi quell'abominio immondo e portami la sua testa. Se ci riuscirai, potrai cominciare la prossima tappa del tuo viaggio.",
  obj = "Riporta l'Head of the Broodlord Lashlayer a Baristolth of the Shifting Sands a Cenarion Hold, in Silithus.",
  progress = "Quello che devi guadagnarti è il favore della Brood of Nozdormu.",
  reward = "Che tu sia $Gil primo:la prima; in mille anni a guadagnarti il favore del Bronze Flight?",
}
T[8290] = {
  title = "Sconfiggi gli Invasori",
  desc = "Oltre questo tunnel ti attende un campo di lotta e di tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra: abbatte il fogliame sempreverde per alimentare le sue macchine da guerra.$B$BEntra a Warsong Gulch e difendi la Silverwing Hold. Ricaccia indietro le forze d'invasione dell'Orda!$B$BSe lo farai, guadagnerai un talismano al merito. Portamene uno, $N, e avrai da me la tua ricompensa.",
  obj = "Entra a Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong a Silverwing Grove.",
  en_title = "Vanquish the Invaders",
  en_obj = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
}
T[8291] = {
  title = "Sconfiggi gli Invasori!",
  desc = "Oltre questo tunnel ti attende un campo di lotta e di tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra: abbatte il fogliame sempreverde per alimentare le sue macchine da guerra.$B$BEntra a Warsong Gulch e difendi la Silverwing Hold. Ricaccia indietro le forze d'invasione dell'Orda!$B$BSe lo farai, guadagnerai un Contrassegno d'Onore. Portamelo, $N, e avrai da me la tua ricompensa.",
  obj = "Entra a Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong a Silverwing Grove.",
  progress = "Hai combattuto a Warsong Gulch e difeso la Silverwing Hold?",
  reward = "Nella nostra lotta a Warsong Gulch hai dimostrato quanto vali. Continua a servire la causa e portami altri Contrassegni d'Onore. Se lo farai, ti guadagnerai ancora di più la nostra fiducia.",
}
T[8294] = {
  title = "Reprimi gli Usurpatori Silverwing",
  desc = "Le terre selvagge della foresta di Ashenvale soccomberanno alla potenza dell'Orda, $R. Qualunque cosa dicano o facciano, i Silverwing non possono fermare la nostra volontà sovrana. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!$B$BMentre stronchi i loro deboli tentativi di rallentare la nostra avanzata, lascia che l'orgoglio ti gonfi il petto. Distruggi le Silverwing Sentinels e guadagnati un Contrassegno d'Onore. Portamene uno, $N, e avrai la tua ricompensa.",
  obj = "Entra a Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull a Mor'shan Base Camp.",
  progress = "Il sangue dei nostri nemici è un contrassegno d'onore. Ne hai uno?",
  reward = "<Captain Shatterskull ruggisce trionfante>$B$BQuanto potranno resistere ancora? Quanta altra feccia dell'Alleanza dovrà perire per mano dell'Orda prima che si ritirino? Solo il tempo lo dirà, $R...",
}
T[8295] = {
  title = "Reprimi gli Usurpatori Silverwing",
  desc = "Le terre selvagge della foresta di Ashenvale soccomberanno alla potenza dell'Orda, $R. Qualunque cosa dicano o facciano, i Silverwing non possono fermare la nostra volontà sovrana. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!$B$BMentre stronchi i loro deboli tentativi di rallentare la nostra avanzata, lascia che l'orgoglio ti gonfi il petto. Distruggi le Silverwing Sentinels e guadagnati un contrassegno d'onore Warsong. Portamene uno, $N, e avrai la tua ricompensa.",
  obj = "Entra a Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull a Mor'shan Base Camp.",
  en_title = "Quell the Silverwing Usurpers",
  en_obj = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
}
T[8297] = {
  title = "Arathi Basin Mark of Honor!",
  desc = "Qualunque soldato te lo dirà: la guerra si fa con i soldati. E ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima ancora di cominciare!$B$BEcco perché l'Arathi Basin è importante. Nel bacino ci sono punti chiave dove si trovano risorse essenziali. Metalli, armi, cibo, legname — servono tutti, e lì si possono prendere tutti.$B$BQuindi, $N, ecco cosa voglio da te. Entra nell'Arathi Basin, vinci la battaglia tenendo più basi del nemico e riportami un Contrassegno d'Onore.",
  obj = "Vinci la battaglia per l'Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Sergeant Maclear a Refuge Pointe.",
  progress = "Allora, $N, hai i Contrassegni d'Onore? Senza quelli The League of Arathor non riesce a combattere una battaglia come si deve...",
  reward = "Hai preso il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, così potranno distribuirle in fretta alle truppe.$B$BGrazie, $N. Le guerre si vincono davvero portando a termine missioni come la tua.",
}
T[8299] = {
  title = "Taglia le Linee di Rifornimento di Arathor",
  desc = "The League of Arathor non bada a spese pur di riconquistare Arathi. Ora arrivano in massa in questa regione lontana, insieme a tutte le razze dell'Alleanza, decisi a estendere il loro dominio partendo da Refuge Pointe. Dobbiamo fermarli, e il modo migliore è portargli via le provviste.$B$BTu puoi aiutarci, $N. Entra nell'Arathi Basin, noto per le ricche miniere, la terra fertile e gli artigiani esperti. Prendi più basi che puoi e tienile, vinci la battaglia e riportami il Contrassegno d'Onore che otterrai.",
  obj = "Vinci la battaglia per l'Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Deathstalker Mortis a Hammerfall.",
  progress = "Che c'è, $R? Ce li hai, i Contrassegni d'Onore? Torna nell'Arathi Basin, fai strage dei parassiti dell'Alleanza e impadronisciti delle risorse per la Dama Oscura!",
  reward = "<Deathstalker Mortis sorride>$B$BAbbiamo assestato ai nostri nemici un altro colpo decisivo, $N. Grazie alle tue imprese, l'Arathi Basin cadrà presto nelle mani dei Defilers.",
}
T[8301] = {
  title = "Il Sentiero dei Giusti",
  desc = "La Brood of Nozdormu diffida per natura delle razze inferiori. A me hai dimostrato di avere la stoffa dell'eroe, ma ora è giunto il momento di provarlo al mio signore.$B$BAlveare Ashi, Hive'Zora, Hive'Regal: brulicano tutti di attività e minacciano tutti la nostra esistenza. Uccidi i silithid di questi alveari e togli loro un frammento di carapace. Quando non riuscirai a portarne altri, torna da me e rafforzerò la tua determinazione.",
  obj = "Raccogli 200 Silithid Carapace Fragments e torna da Baristolth.",
  progress = "La loro diffidenza verso le razze mortali nasce da una lunga storia; ma ahimè, meglio che sia la Brood a raccontarla, a tempo debito.",
  reward = "Non sei $Gsolo:sola;, $Geroe:eroina;. Ora ti concederò la facoltà di nominare degli aiutanti per la tua impresa. Se vuoi essere $Gil campione:la campionessa; del tuo popolo, ti servirà chi ti assista nei compiti e nei doveri.",
}
T[8302] = {
  title = "La Mano del Giusto",
  desc = "Scegli con saggezza i tuoi delegati, mortale: ogni volta che tornerai a compito concluso, un nuovo delegato potrai scegliere.$B$BDetto questo, ho bisogno di altri frammenti di carapace. Non perdere tempo!",
  obj = "Raccogli 200 Silithid Carapace Fragments e torna da Baristolth.",
  progress = "Forse un giorno l'intera Cenarion Hold lavorerà ai tuoi ordini.",
  reward = "Ben fatto, $Geroe:eroina;. Ora ti sarà concesso di nominare un altro Agent of Nozdormu.",
}
T[8303] = {
  title = "Anachronos",
  desc = "È giunto il momento, $N.$B$BPerdonami se ti ho tenuto nascoste così tante cose. I nemici sono ovunque, persino sotto il nostro naso. Leggi questo tomo, ti prego, e impara. Prendi la conoscenza che ti affido e cerca il nostro maestro.",
  obj = "Cerca Anachronos alle Caverns of Time a Tanaris.",
  reward = "Sei tu la speranza di Kalimdor, $N.",
}
T[8304] = {
  title = "Carissima Natalia",
  desc = "La mia cara Natalia è scomparsa.$B$BA dire il vero, già nelle settimane prima di sparire si comportava in modo strano. Più di una volta l'avevo sorpresa a parlare da sola, senza nessuno intorno. Lei insisteva che andava tutto bene e che doveva poter continuare le sue ricerche.$B$BL'ultima volta l'hanno vista dirigersi a sud, verso l'accampamento di Bronzebeard.$B$BI miei soldati sono già impegnati su troppi fronti, $N. Ho bisogno che tu vada all'accampamento di Bronzebeard a interrogare quei nani.",
  obj = "Commander Mar'alith a Cenarion Hold, in Silithus, vuole che tu interroghi gli abitanti di Bronzebeard's Encampment. Troverai Bronzebeard's Encampment a sud di Cenarion Hold.$B$BQuando avrai raccolto le informazioni richieste, torna da Commander Mar'alith.",
  progress = "Non perdere tempo, $N!",
  reward = "<Commander Mar'alith china il capo, pensieroso.>$B$BViva o morta che sia, devo fare ciò che è giusto: bisogna trovarla. Ma, ahimè, il dovere mi lega a questo avamposto. Mi aiuterai ancora una volta, $N?",
}
T[8305] = {
  title = "Ricordi Dimenticati da Tempo",
  desc = "Nel deserto meridionale di Silithus, vicino alla barriera sacra, c'è una lacrima cristallina, una sola. Simboleggia le grandi perdite che abbiamo subito nella War of the Shifting Sands. Trovala e scruta nelle sue profondità: così otterrai l'illuminazione.",
  obj = "Trova la Crystalline Tear a Silithus e scruta nelle sue profondità.",
  reward = "Senti un grande dolore vorticare attorno al cristallo, una forza così potente che ti sembra di essere sul punto di crollare e morire di tristezza.",
}
T[8306] = {
  title = "Nelle Maw of Madness",
  desc = "Ho bisogno che tu ti avventuri in Hive'Regal a scoprire che ne è stato della mia carissima Natalia, $N. Da $Gsolo:sola; non sarà un'impresa facile: ti consiglio di portare con te qualche amico. E prima di gettarti a capofitto nelle fauci della follia, torna a parlare con quei nani, che potrebbero darti qualche consiglio su come affrontare i silithid di quell'alveare.$B$BE $N, se è davvero pazza come dicono... fai ciò che devi.$B$B<Commander Mar'alith ti volta le spalle.>",
  obj = "Commander Mar'alith a Cenarion Hold, in Silithus, vuole che tu trovi la sua amata Natalia. Secondo le informazioni che hai raccolto, potresti trovare Mistress Natalia Mar'alith a Hive'Regal, a sud.$B$BNon dimenticare di andare dai nani all'accampamento di Bronzebeard prima di avventurarti nell'alveare. Potrebbero avere altro lavoro e qualche consiglio per te.$B$BE $N, ricorda le parole del Comandante: \"Fai ciò che devi...\"",
  progress = "Natalia?",
  reward = "<Commander Mar'alith si stringe il petto.>$B$BC'Thun? CHE vuol dire tutto questo? Che cos'è C'Thun? Come ha potuto questo demonio fare della mia dolce Natalia il mostro che mi hai descritto?",
}
T[8307] = {
  title = "Ricetta del Deserto",
  desc = "Abituarmi alla vita nel deserto è stato a dir poco difficile. Mi mancano gli uccelli e gli alberi di Auberdine, e per di più in un posto così arido la scelta del cibo è ridottissima. Sto cercando di imparare qualcosa sulle erbe del deserto, ma qui ce ne sono poche.$B$BHo visto dei gruppi del Twilight's Hammer, quelli dell'accampamento a ovest di qui, cacciare i sandworms per mangiarli. Eppure la Sandworm meat è così amara che non riesco a immaginare come facciano a renderla mangiabile. Se vai al loro accampamento tieni gli occhi aperti, e se scopri qualcosa fammelo sapere.",
  obj = "Cerca informazioni su come cucinare la Sandworm Meat nell'accampamento del Twilight's Hammer a ovest di Cenarion Hold.",
  reward = "Il libro raccoglie parecchie ricette comuni e qualcuna insolita. Lo sfogli per qualche secondo e noti una ricetta che usa la sandworm meat.",
}
T[8308] = {
  title = "Brann Bronzebeard's Lost Letter",
  desc = "A chi di dovere:$B$BSe stai leggendo questa lettera, o sono morto o morirò presto. Difficile dirlo. Comunque, la maggior parte della squadra è morta.$B$BTrovate informazioni su un Titano. Grande battaglia fra lui e un Old God. Sì, un Old God bona fide. Trovato antico tunnel che porta ad Ahn'Qiraj. Ci entro.$B$BPorta questa lettera al mio vecchio accampamento. Fa' che alla mia scimmia non manchino cibo, acqua e abbracci.$B$B-Brann Bronzebeard, Esploratore Estremo$B$BP.S. Occhio a elfo della notte pazzo, adoratore di un Old God.",
  obj = "Porta la Lettera di Brann Bronzebeard a Bronzebeard's Encampment, nella parte meridionale di Silithus.",
  progress = "Oh, cielo.",
  reward = "Be', ora si spiegano un sacco di cose. Se mai trovi un modo per entrare ad Ahn'Qiraj, cerca il vecchio Brann: senza la sua scimmia, temo che sarà indifeso.",
}
T[8309] = {
  title = "A Caccia di Glifi",
  desc = "Da quando abbiamo fatto la prima incursione negli alveari e Mistress Mar'alith è stata colpita dalla follia, tutti e tre gli alveari sputano fuori insetti a non finire! Tutto questo movimento in più potrebbe dipendere dai glifi che coprono quegli strani cristalli.$B$BCi serve un calco dei cristalli di ognuno dei tre alveari. Se mettiamo le mani su quei calchi, forse potremo dare un senso a questa follia.$B$BPrendi questo corredo da trascrizione, porta con te qualche amico e fa' irruzione negli alveari, $N. E non tornare finché non avrai le copie di tutti e tre.",
  obj = "Rutgar Glyphshaper, a Bronzebeard's Encampment, in Silithus, vuole che tu ti spinga a Hive'Ashi, a Hive'Zora e a Hive'Regal e recuperi i Calchi dei Glifi dai Cristalli Glifati di ogni alveare.$B$BUsa il Geologist's Transcription Kit per fare una copia accettabile degli antichi glifi. Torna da Rutgar Glyphshaper quando avrai finito.",
  progress = "Se in uno degli alveari ti capita una ragazza elfa della notte fuori di testa, da parte nostra dalle un bel calcio nel sedere.",
  reward = "Di questi glifi non ci capisco un'acca. Mai visto niente del genere! Spero che le ricerche di Frankal riescano a fare un po' di luce su questo pasticcio.",
}
T[8310] = {
  title = "Decifrare il Codice",
  desc = "Credo di riuscire a preparare un elisir che ci renderà più facile decifrare i glifi e la lingua dei silithid e dei Qiraji! Cosa mi serve? Bella domanda! Cervelli! Per la precisione, un cervello per ogni tipo di silithid che vive negli alveari. Portameli, e forse il lavoro di Rutgar non sarà stato vano.",
  obj = "Frankal Stonebridge, a Bronzebeard's Encampment, in Silithus, vuole che tu recuperi un Hive'Zora Silithid Brain, un Hive'Ashi Silithid Brain e un Hive'Regal Silithid Brain. Torna da Frankal quando avrai finito.",
  progress = "Va' a giocare con la scimmia, $Gragazzo:ragazza;. Non ho tempo per queste cose.",
  reward = "Eccezionale! Non andare troppo lontano, $Gragazzo:ragazza;. Potremmo aver bisogno di te per un altro paio di lavori.",
}
T[8311] = {
  title = "Dolcetti di Hallow's End per Jesper!",
  desc = "Voglio andare a fare dolcetto o scherzetto, ma sono malato e non posso. Se ci vai tu al posto mio, le caramelle che ricevi te le scambio con un po' di quelle che ho già! Credo che queste caramelle ti piaceranno — ti trasformano in cose buffe e paurose!$B$BPer Hallow's End i locandieri delle grandi città hanno caramelle da regalare — parla con loro e fai gli scherzetti che ti chiedono! E poi c'è anche un piccolo gnomo di nome Talvash, a Ironforge, che ne sta distribuendo. Quando le hai tutte, riportamele qui!",
  obj = "Parla con i locandieri di Stormwind, Ironforge e Darnassus, e anche con Talvash del Kissel a Ironforge. Fai gli scherzetti che ti chiedono in cambio dei dolcetti che offrono.$B$BTorna da Jesper a Stormwind Orphanage con un Darnassus Marzipan, una Gnomeregan Gumdrop, uno Stormwind Nougat e un'Ironforge Mint.",
  progress = "Hai già finito con dolcetto o scherzetto? Mi rende triste non poterci andare perché sono malato, ma il tuo aiuto mi fa sentire un po' meglio...",
  reward = "Wow, le hai prese tutte! Sei $Gfantastico:fantastica;!$B$BGrazie di aver fatto dolcetto o scherzetto per me. Tieni questi dolcetti alla zucca — secondo me ti piaceranno tantissimo!$B$BBuon Hallow's End, $N!",
  en_title = "Hallow's End Treats for Jesper!",
  en_obj = "Speak with the innkeepers of Stormwind, Ironforge, and Darnassus, as well as Talvash del Kissel in Ironforge.  Perform the tricks they ask of you in exchange for the treats they offer.$B$BReturn to Jesper at the Stormwind Orphanage with a Darnassus Marzipan, Gnomeregan Gumdrop, Stormwind Nougat, and Ironforge Mint.",
}
T[8312] = {
  title = "Dolcetti di Hallow's End per Spoops!",
  desc = "Voglio andare a fare dolcetto o scherzetto, ma sono malata e non posso. Se ci vai tu al posto mio, in cambio di quelle che raccoglierai ti darò delle caramelle che ho già! Credo che queste caramelle ti piaceranno — ti trasformano in cose buffe e anche spaventose!$B$BPer Hallow's End tutti i locandieri delle grandi città hanno caramelle da regalare — parla con loro e fai gli scherzetti che ti chiedono! Anche una troll che si chiama Kali Remik, a Sen'jin Village, sta distribuendo caramelle. Quando le avrai tutte, riportamele qui!",
  obj = "Parla con i locandieri di Orgrimmar, Undercity e Thunder Bluff, e anche con Kali Remik a Sen'jin Village. Fai gli scherzetti che ti chiedono in cambio dei dolcetti che ti offrono.$B$BTorna da Spoops a Orgrimmar Orphanage con un Thunder Bluff Marzipan, una Darkspear Gumdrop, un Orgrimmar Nougat e un'Undercity Mint.",
  progress = "Hai già finito di fare dolcetto o scherzetto? Sono triste perché sono malata e non posso andarci, ma con il tuo aiuto mi sento un po' meglio...",
  reward = "Wow, le hai prese tutte! Sei $Gfantastico:fantastica;!$B$BGrazie per aver fatto dolcetto o scherzetto al posto mio. Ecco, prendi questi dolcetti alla zucca — credo che ti piaceranno tanto!$B$BBuon Hallow's End, $N!",
  en_title = "Hallow's End Treats for Spoops!",
  en_obj = "Speak with the innkeepers of Orgrimmar, Undercity, and Thunder Bluff, as well as Kali Remik in Sen'jin Village.  Perform the tricks they ask of you in exchange for the treats they offer.$B$BReturn to Spoops at the Orgrimmar Orphanage with a Thunder Bluff Marzipan, Darkspear Gumdrop, Orgrimmar Nougat, and Undercity Mint.",
}
T[8313] = {
  title = "Condividere il Sapere",
  desc = "La ricetta per cucinare la sandworm meat si legge bene, ma cita erbe e spezie che non hai mai sentito nominare. Forse Calandrath conosce abbastanza le piante del deserto da riuscire a capirla.",
  obj = "Porta la Torn Recipe Page a Calandrath, nella locanda di Cenarion Hold.",
  progress = "Hai imparato la ricetta? Spero che tu non voglia tenertela per te!",
  reward = "Vediamo un po'...$B$BSembra abbastanza semplice. Certe erbe le chiamano con nomi tutti loro, ma non è difficile capire quali siano. Ecco, ti faccio vedere!",
}
T[8314] = {
  title = "Svelare il Mistero",
  desc = "Siamo a un passo da una svolta, $N! Con i calchi che hai recuperato siamo riusciti a ricreare i glifi su questo prisma cristallino. A quanto pare, i Qiraji e altre entità sconosciute li usano per mandare messaggi di vario genere ai silithid.$B$BPurtroppo dai glifi non siamo riusciti a ricavare altro. Dobbiamo trovare il modo di sbloccare i messaggi nascosti nei cristalli.$B$BPorta il glyphed crystal prism a Geologist Larksbane a Cenarion Hold. Lei potrebbe darti una mano.",
  obj = "Rutgar Glyphshaper a Bronzebeard's Encampment vuole che tu consegni il Glyphed Crystal Prism a Geologist Larksbane a Cenarion Hold, in Silithus.",
  progress = "Oh, cielo! Che cos'hai lì, $N?",
  reward = "Se i nani non sono riusciti a decifrare i glifi, è perché non c'è niente da decifrare. Per trasmettere il messaggio, lo strato esterno mobile del prisma deve allinearsi bene con i segni del cristallo interno. Ingegnoso...$B$BQuesti dati dovremmo riuscire a tradurli, ma prima bisogna sbloccare il codice. Sulla superficie del prisma c'è un solo indizio — ammesso che i calchi siano stati riportati bene — e non promette niente di buono.",
}
T[8315] = {
  title = "Il Richiamo",
  desc = "I glifi raffigurano un emissario dei Qiraji che incontra tre silithid vicino alle ossa di un grande drago. Sopra c'è quella che secondo me è una specie di codice: potrebbe essere proprio la chiave per evocare l'emissario.$B$BFarò una copia del codice dei glifi, e tu dovrai tracciarla nella sabbia presso le Bones of Grakkarond. Se ho ragione, i Sovrani arriveranno convinti che ci siano nuovi dati pronti da trasmettere. Abbattili e affronta l'emissario: è lui ad avere la chiave dei cristalli...",
  obj = "Geologist Larksbane a Cenarion Hold, in Silithus, vuole che tu recuperi il Crystal Unlocking Mechanism dal Qiraji Emissary.$B$BTi è stato detto di portare i Glyphs of Calling alle Bones of Grakkarond, a sud di Cenarion Hold, e di tracciarli nella sabbia. Se il Qiraji Emissary dovesse comparire, uccidilo e recupera il Crystal Unlocking Mechanism. Torna da Geologist Larksbane se ci riesci.$B$BRaduna un esercito per questa impresa, $N!",
  progress = "Appena si presenta l'occasione, devi coglierla e colpire!",
  reward = "Ho in mano 20,000 anni di storia, $N!",
}
T[8316] = {
  title = "Armamenti di Guerra",
  reward = "La guerra è alle porte, $N, e si porta dietro orrori indicibili. Hai fatto tutto quello che ti si poteva chiedere, e una ricompensa te la meriti.$B$BSe mai questa... questa profezia si avverasse...$B$B<Geologist Larksbane impallidisce.>$B$BPer tutti noi potrebbe non esserci più un futuro.$B$BQuesti armamenti ti saranno preziosissimi per la campagna in questo deserto.",
}
T[8317] = {
  title = "Aiuto in Cucina",
  desc = "Quella ricetta mi tornerà proprio utile. Meglio che mi metta subito al lavoro, così per oggi avrò pronti degli smoked desert dumplings. Una mano a prepararne un po' mi farebbe comodo, e ti assicuro che ne varrà la pena.",
  obj = "Calandrath a Cenarion Hold ha bisogno di una scorta di 10 Smoked Desert Dumplings.",
  progress = "Come vanno quegli gnocchi?",
  reward = "Ottimo! Mi hai salvato la vita. Questi gnocchi sono venuti proprio buoni: dal Twilight's Hammer non mi aspettavo tanto gusto.",
}
T[8318] = {
  title = "Comunicazioni Segrete",
  desc = "Alcuni cultisti del Twilight's Hammer girano con dei foglietti pieni di frasi senza senso. Voglio che me ne porti una pila, $C.$B$BCosa vogliano dire non lo capisco, ma il punto non è questo! È proprio con questi foglietti che i loro vari gruppi si scambiano i messaggi in segreto. Più testi togliamo dalla circolazione, meno potranno comunicare!",
  obj = "Porta 10 Encrypted Twilight Texts a Bor Wildmane a Cenarion Hold.",
  progress = "Hai qualche testo per me?",
  reward = "Eccellente! Li metto da parte, magari più avanti torneranno utili.",
}
T[8319] = {
  title = "Encrypted Twilight Texts",
  progress = "Continua a portarmi testi: presto cacceremo il Twilight's Hammer da Silithus.",
  reward = "Ottimo lavoro! Metterò una buona parola per te.",
}
T[8320] = {
  title = "Twilight Geolords",
  desc = "Il Twilight's Hammer, un culto folle votato alla distruzione, ha allestito accampamenti a Silithus, e lì compie rituali giorno e notte. Quali siano i loro piani ancora non lo sappiamo, ma pensiamo che c'entrino in qualche modo i cristalli rossi pulsanti sparsi per il deserto.$B$BForse un giorno ne sveleremo il mistero, ma prima c'è da affrontare la minaccia immediata. Va' nei loro accampamenti a ovest e cerca i geosignori del Twilight. Sono loro le teste di questi serpenti; è lì che dobbiamo colpire!",
  obj = "Uccidi 10 Twilight Geolords, poi torna da Huum Wildmane a Cenarion Hold.",
  progress = "Addentrati nel deserto, $N, e trova i geosignori del Twilight. Quando saranno morti, torna da me.",
  reward = "Hai fatto un buon lavoro, $N. Uccidendo i geosignori del Twilight avrai inferto un duro colpo al culto. Speriamo che questo rallenti i loro piani...",
}
T[8321] = {
  title = "Vyral the Vile",
  desc = "Abbiamo scoperto un'altra base operativa del Twilight's Hammer: si chiama Twilight's Run ed è una caverna nascosta nell'angolo nord-orientale di Silithus. Il capo del culto da quelle parti, Vyral the Vile, infesta la caverna — ora è lui che devi sconfiggere. Quando l'avrai fatto, portami il suo anello con sigillo.$B$BChe la fortuna ti assista, $N: gli orrori della Twilight's Run sono davvero temibili.",
  obj = "Porta il Vyral's Signet Ring a Huum Wildmane a Cenarion Hold.",
  progress = "$N, hai già sconfitto Vyral the Vile? Ce l'hai, il suo anello con sigillo?",
  reward = "Ce l'hai fatta! Vyral è morto! Per le operazioni del Twilight Hammer a Silithus non può che essere la rovina. Forse ce ne sono altri che sgattaiolano qua e là, ma il colpo che oggi hai inferto al culto è di quelli da cui non si riprenderanno facilmente.",
}
T[8322] = {
  title = "Rotten Eggs",
  desc = "La gente di Southshore amano la loro birra, e per questo tengono in gran conto quella servita alla Southshore Inn. Ora che è arrivato il caos di Hallow's End, possiamo approfittarne per rovinargli l'ultima bevuta, e ne avranno per settimane — se non per mesi!$B$BPrendi queste Rotten Eggs e mettile nel barile principale della birra, dentro la Southshore Inn. Basterà la tua presenza a scatenare disordini, quindi tieniti $Gpronto:pronta; a difenderti!$B$BQuando avrai lasciato a Southshore un sapore in bocca che non dimenticherà tanto presto, torna da me qui al festival!",
  obj = "Metti le Rotten Eggs nel barile principale della birra, in Southshore Inn.",
  progress = "Il barile è pieno di birra.",
  reward = "Ti sei $Gfatto:fatta; strada combattendo fin dentro la locanda, e ora metti le uova nel barile. Senti il fetore nauseabondo che impregna l'aria...",
  en_title = "Rotten Eggs",
  en_obj = "Place the Rotten Eggs in the main brew keg located inside the Southshore Inn.",
}
T[8323] = {
  title = "Veri Credenti",
  desc = "Ora che il Lessico del Twilight è in mio possesso, vorrei chiederti un piccolo favore.$B$BOgni mese la mia vecchia organizzazione fa circolare un bollettino segreto, scritto in codice.$B$BSe le loro ricerche per trovarmi fanno passi avanti, o se le interrompono, la notizia finirà sul Vero Credente.$B$BPer me sono informazioni preziose, è ovvio, ma nel bollettino ce ne sono anche altre utili che posso condividere. Portami tutti i testi codificati che trovi addosso ai membri del Twilight's Hammer.",
  obj = "Hermit Ortell vuole che gli porti 10 Encrypted Twilight Texts",
  progress = "Hai trovato dei testi codificati? Sono piuttosto curioso di leggere il Vero Credente di questo mese.",
  reward = "Eccellente! Mi metto a decifrarli appena posso, e se scopro qualcosa di interessante farò in modo di passarti le informazioni.",
}
T[8324] = {
  title = "Ancora Credenti",
  progress = "Hai trovato altri testi codificati? Portamene un bel mucchio: per decifrarli ci vuole un po' di tempo.",
  reward = "Eccellente! Non vedo l'ora di leggerli. Ti prego, se ne trovi, continua a portarmeli qui.",
}
T[8331] = {
  title = "Aurel Goldleaf",
  desc = "$N, speravamo che le operazioni del Twilight's Hammer a Silithus stessero rallentando... purtroppo ci sbagliavamo. Continuando a colpire il culto con le nostre incursioni, abbiamo scoperto che un potere ancora più oscuro, l'Abyssal Council, controlla il Martello attraverso le pietre del vento arcane sparse fra gli accampamenti del culto. La tua prossima mossa, $N, sarà contro l'Abyssal Council.$B$BVa' a parlare con l'artigiana Aurel Goldleaf, nella parte orientale di Cenarion Hold: per questo stratagemma ci servirà la sua abilità.",
  obj = "Parla con Aurel Goldleaf a Cenarion Hold.",
  reward = "Buongiorno, $N. Mi hanno detto che affronterai l'Abyssal Council? Se è così, ascolta con attenzione quello che sto per dirti...",
}
T[8332] = {
  title = "I Duchi del Concilio",
  desc = "Crediamo che si possa usare una pietra del vento per tendere un'imboscata a un duca dell'Abyssal Council. Per riuscirci, però, bisogna comunicare attraverso la pietra e convincere il concilio di essere un capo di medio rango del Twilight's Hammer.$B$BPer uno stratagemma simile occorre una copia del medaglione di grado del culto. Posso crearne una, ma mi serviranno un large brilliant shard e gli amuleti che portano gli Abyssal Templar.$B$BPortameli e al resto penserò io.",
  obj = "Porta 1 Large Brilliant Shard e 3 Abyssal Crests ad Aurel Goldleaf a Cenarion Hold.",
  progress = "Hai il frammento e gli amuleti, $N? Mi occorrono per creare il medaglione di grado del cultista del crepuscolo.",
  reward = "Ah, molto bene. Al medaglione stavo già lavorando — ora, con questi ultimi ingredienti, mi bastano pochi istanti per finirlo...$B$BEcco fatto. Questo è il medaglione, $N.$B$BDovrai indossarlo quando attiverai una delle pietre del vento del Twilight's Hammer. Mettilo insieme al resto della tenuta del crepuscolo, e l'Abyssal Council ti prenderà per $Guno:una; dei cultisti al suo servizio.",
}
T[8333] = {
  title = "Medaglione di Rango",
  progress = "Se hai bisogno di un altro medaglione di rango da cultista del Twilight, sono lieta di accontentarti. Prima però mi servono un altro frammento brillante e un po' di abyssal crests...",
  reward = "Eccolo, $N. Un altro medaglione di rango del Twilight. Fanne buon uso, e buona fortuna contro l'Abyssal Council!",
}
T[8341] = {
  title = "I Signori del Concilio",
  desc = "I Signori dell'Abyssal Council si possono evocare solo con le pietre del vento maggiori, e con loro possono parlare soltanto i membri di rango più alto del Twilight's Council. Ma... ho trovato il modo di perfezionare il tuo travestimento e ingannare i Signori Abissali!$B$BPer il travestimento serve un anello del comando, che indossano solo i membri di grado più elevato del culto. Se mi porterai dei large brilliant shards e degli abyssal signets, te ne fabbricherò uno.",
  obj = "Porta 5 Large Brilliant Shards e 3 Abyssal Signets ad Aurel Goldleaf a Cenarion Hold.",
  progress = "Hai i frammenti e gli anelli con sigillo, $N? Mi servono per creare l'anello del comando.",
  reward = "Grazie. Un momento solo e l'anello è pronto...$B$BEccolo. Ora sei $Gpronto:pronta;.$B$BQuando attivi una pietra del vento maggiore, assicurati di indossare questo anello insieme a un medaglione del rango e al resto dei paramenti del crepuscolo. Così l'Abyssal Council ti prenderà per $Guno:una; dei suoi servitori, e a quel punto, forse, potrai attirarne uno in un'imboscata!",
}
T[8342] = {
  title = "Anello di Signoria del Crepuscolo",
  progress = "$N, se hai intenzione di affrontare ancora l'Abyssal High Council, ti occorrerà un altro anello di signoria del Twilight. Portami altri frammenti e sigilli, e te ne preparerò uno.",
  reward = "Ah, vedo che sei forte nelle tue convinzioni. In pochi affrontano quel concilio di demoni!$B$BEcco il tuo anello, $N. Che la tua volontà, e la tua fortuna, restino salde.",
}
T[8343] = {
  title = "La Scoperta di Goldleaf",
  desc = "$N, Aurel Goldleaf crede di aver trovato il modo di evocare e sconfiggere uno dei membri al vertice dell'Abyssal Council! Sarà un compito pericoloso, ma ti sei $Gguadagnato:guadagnata; il grande rispetto del Cenarion Circle, e sappiamo che, se c'è qualcuno in grado di farcela, sei tu.$B$BChe la fortuna ti accompagni, $N. Quando sarai $Gpronto:pronta;, va' a parlare con Aurel.",
  obj = "Parla con Aurel Goldleaf a Cenarion Hold.",
  reward = "Huum dice il vero. Credo di aver capito come evocare un signore dell'Abyssal Council! Ascolta, ti spiego...",
}
T[8348] = {
  title = "L'Anello con Sigillo dei Duchi",
  desc = "Huum mi dice che hai scoperto come evocare gli Abyssal Dukes! Non è cosa da poco.$B$BE sai cos'altro non sarebbe cosa da poco? Fare a pezzi per bene uno di quei cosi. Sui loro tirapiedi farà colpo, se capisci cosa intendo. Riportami il suo anello con sigillo, come prova dell'impresa.",
  obj = "Porta l'Abyssal Signet a Bor Wildmane a Cenarion Hold.",
  progress = "Com'è andata con l'Abyssal Duke? Picchiava duro?",
  reward = "Appena ti ho visto entrare a Cenarion Hold ho capito che eri $Gun:una; $C $Gtosto:tosta;. Continua così!",
}
T[8349] = {
  title = "Bor Wildmane",
  desc = "Ora che hai un medaglione e puoi evocare un Abyssal Duke, va' a parlare con Bor Wildmane: ti affiderà un incarico contro l'Abyssal Council.$B$BBuona fortuna, $N. E se mai ti serviranno altri medaglioni, torna pure da me.",
  obj = "Parla con Bor Wildmane a Cenarion Hold.",
  reward = "Che piacere rivederti, $C! Così ti sei $Gfatto:fatta; fare un medaglione? Bene — ti servirà per la tua prossima impresa...",
}
T[8351] = {
  title = "Bor Vuole Parlare",
  desc = "Ora che puoi travestirti da membro al vertice del Twilight Council, sono sicura che Bor Wildmane vorrà parlarti. Va' da lui, e preparati a una missione molto difficile...",
  obj = "Parla con Bor Wildmane a Cenarion Hold.",
  reward = "Sì, è così, $N. Ho in serbo per te un compito molto duro...",
}
T[8352] = {
  title = "Lo Scettro del Concilio",
  desc = "Huum e io parlavamo proprio di te. Dice che sei quasi $Gpronto:pronta; a misurarti con un Signore Abissale!$B$BTe lo devo dire: è un'impresa molto pericolosa, e faresti bene a portarti dei rinforzi. Non parlo di uno o due amici, ma di una squadra di prim'ordine, pronta a combattere. Se sono bravi quanto te, potreste perfino sconfiggerlo!$B$BSe ce la farai — e come sempre vorrò delle prove — ti darò una ricompensa davvero grande.",
  obj = "Porta un Abyssal Scepter a Bor Wildmane a Cenarion Hold.",
  progress = "Allora, com'è andata? Farei qualsiasi cosa per lasciare il mio posto e battermi io stesso con una di quelle cose!",
  reward = "Ce... ce l'hai fatta! Ce l'hai fatta, $N! Ecco! Prendi questo. È il forziere più grande che avevamo sottomano, e ci ho messo dentro alcune delle cose migliori che abbiamo trovato.",
}
T[8353] = {
  title = "Fare la Gallina per una Mentina",
  desc = "Ah, fai dolcetto o scherzetto per un bambino malato, eh? Stavo giusto per dire, sei un po' troppo $Gvecchio:vecchia; per andartene in giro a frugare in cerca di caramelle...$B$BBeh, per il mio dolcetto — un'Ironforge Mint — dovrai... chiocciare come una gallina! Sì, le galline adorano le mentine... va be', forse non le ADORANO... ma la mentina non te la do finché non chiocci per me!$B$BAllora, $C, sei all'altezza della sfida o no?! Ora guadagnati il dolcetto!",
  obj = "Fai l'emote della gallina a Innkeeper Firebrew, e in cambio riceverai un'Ironforge Mint!",
  progress = "Aspetto...",
  reward = "Che spasso! Ben fatto, $N! Ecco qua il tuo dolcetto.$B$BBuona Hallow's End!",
  en_title = "Chicken Clucking for a Mint",
  en_obj = "Do a chicken emote at Innkeeper Firebrew, and in exchange you'll receive an Ironforge Mint!",
}
T[8354] = {
  title = "Coccodè per una Mentina",
  desc = "Ah, dolcetto o scherzetto per un bambino malato, eh? E io che stavo per dirti che sei un po' troppo $Gvecchio:vecchia; per andartene in giro a rovistare in cerca di caramelle...$B$BBe', se vuoi il mio dolcetto — un'Undercity Mint — dovrai... fare coccodè come una gallina! Sì, alle galline piacciono le mentine... d'accordo, forse non le ADORANO... ma la mentina non te la do finché non fai coccodè per me!$B$BAllora, $C, te la senti o no?! È ora di guadagnarti il dolcetto!",
  obj = "Usa l'emote della gallina su Innkeeper Norman e in cambio riceverai un'Undercity Mint!",
  progress = "Aspetto...",
  reward = "Che spasso! Ben fatto, $N! Eccoti il dolcetto.$B$BBuona Hallow's End!",
  en_title = "Chicken Clucking for a Mint",
  en_obj = "Do a chicken emote at Innkeeper Norman, and in exchange you'll receive an Undercity Mint!",
}
T[8355] = {
  title = "Caramella in Arrivo",
  desc = "Oh, qualcuno che fa dolcetto o scherzetto! Urrà!$B$BBeh, raccogliere caramelle per un bambino malato è un gesto nobile, certo, ma non posso lasciarti andare così facilmente. Ho una deliziosa Gnomeregan Gumdrop per il piccolo... ma solo se mi fai il verso del treno! Ah ah, sì, ecco lo scherzetto! Questa caramella gommosa costa un verso del treno!$B$BCiuf-ciuf, $C!",
  obj = "Fai l'emote del treno davanti a Talvash del Kissel, e in cambio riceverai una Gnomeregan Gumdrop!",
  progress = "Beh, dai, forza...",
  reward = "Tuuu-tuuu! Ben fatto, $N! Ecco a te il dolcetto.$B$BBuona Hallow's End!",
  en_title = "Incoming Gumdrop",
  en_obj = "Do a train emote at Talvash del Kissel, and in exchange you'll receive a Gnomeregan Gumdrop!",
}
T[8356] = {
  title = "Mostra i Muscoli per un Torrone",
  desc = "Hai addosso un costume... interessante. Sarai anche così gentile da aiutare un bambino malato a fare dolcetto o scherzetto, quest'anno, ma temo che a me lo scherzetto dovrai farlo tu!$B$BVediamo... sembri così $Gforte:forte; e $Gmuscoloso:muscolosa;, con quel... costume... fammi vedere i muscoli! Sì, forza, fammeli vedere, $Gforzuto:forzuta;!$B$BQuando, e solo quando, mi mostrerai i muscoli, ti darò un po' di gustoso Stormwind Nougat. Per Hallow's End è un dolcetto perfetto.",
  obj = "Usa l'emote flex su Innkeeper Allison e in cambio riceverai dello Stormwind Nougat!",
  progress = "Niente dolcetti finché non vedo i muscoli, $N...",
  reward = "Sei davvero $Gfortissimo:fortissima;, ahah! Ben fatto, e grazie di essere $Gstato:stata; al gioco. Ecco i tuoi dolcetti.$B$BBuon Hallow's End, $N!",
  en_title = "Flexing for Nougat",
  en_obj = "Do a flex emote at Innkeeper Allison, and in exchange you'll receive Stormwind Nougat!$B",
}
T[8357] = {
  title = "Ballare per il Marzapane",
  desc = "Anche se fai dolcetto o scherzetto per un bambino malato, devi comunque fare uno scherzetto per avere il dolcetto! Non possiamo mica cambiare la tradizione, giusto...$B$BCredo che oggigiorno il prezzo di un pezzo di marzapane sia scatenarsi e BALLARE! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò un po' di squisito marzapane!",
  obj = "Fai un'emote di ballo rivolta a Innkeeper Saelienne e in cambio riceverai del Darnassus Marzipan!",
  progress = "Sai ballare, vero? Prova così: metti dentro il piede destro... poi il piede destro fuori... il piede destro dentro... e scuoti tutto quanto...",
  reward = "Hai proprio il ballo nel sangue, $N!$B$BEcco il tuo dolcetto, visto che hai saputo stare al gioco. Buon Hallow's End, e salutami tanto il tuo piccolo amico malato! Spero che guarisca presto.",
  en_title = "Dancing for Marzipan",
  en_obj = "Do a dance emote at Innkeeper Saelienne, and in exchange you'll receive Darnassus Marzipan!",
}
T[8358] = {
  title = "Caramella in Arrivo",
  desc = "Ecco $Guno:una; che va a fare dolcetto o scherzetto! Eh sì, mon!$B$BAllora, lo so che stai facendo una cosa nobile, che raccogli dolci per un bambino malato, ma non posso mica lasciarti andare così facilmente. Ho una gustosa Darkspear Gumdrop da dare al bambino... se mi fai il verso del treno! Ah ah, sì, lo scherzetto sarà questo! Per questa caramella si paga con un verso del treno!$B$BCiuf-ciuf, $C!",
  obj = "Fai l'emote del treno davanti a Kali Remik e in cambio riceverai una Darkspear Gumdrop!",
  progress = "Su, avanti...",
  reward = "Tuu-tuu! Ben fatto, $N! Ecco il tuo dolcetto.$B$BBuona Hallow's End!",
}
T[8359] = {
  title = "Mostra i Muscoli per il Torrone",
  desc = "Interessante... il costume che indossi. Quest'anno sei così gentile da aiutare un bambino malato a fare dolcetto o scherzetto, eppure temo che dovrò chiederti di fare uno scherzetto per me!$B$BVediamo... con quel... costume... sembri così $Gforte e muscoloso:forte e muscolosa;, fammi vedere i muscoli! Sì, forza, $Gforzuto:forzuta;, mostrameli!$B$BSolo quando mi avrai mostrato i muscoli ti darò un po' di gustoso Orgrimmar Nougat. È un ottimo dolcetto per l'Hallow's End.",
  obj = "Usa l'emote per mostrare i muscoli a Innkeeper Gryshka e in cambio riceverai dell'Orgrimmar Nougat!",
  progress = "Niente dolci finché non mi fai vedere i muscoli, $N...",
  reward = "Sei proprio possente, ahah! Ben fatto, e grazie di essere $Gstato:stata; al gioco. Eccoti i dolci.$B$BBuona Hallow's End, $N!",
}
T[8360] = {
  title = "Ballare per il Marzapane",
  desc = "Anche se fai dolcetto o scherzetto per un bambino malato, il dolcetto devi comunque guadagnartelo con un numero! Mica possiamo cambiare la tradizione, dico bene...$B$BDi questi tempi, credo, un pezzo di marzapane costa una cosa sola: scatenarsi e BALLARE! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò del gustoso marzapane!",
  obj = "Esegui un'emote di ballo davanti a Innkeeper Pala e in cambio riceverai il Thunder Bluff Marzipan!",
  progress = "Sai ballare, vero? Prova così: il piede destro dentro... poi il piede destro fuori... il piede destro dentro... e scuotilo tutto...",
  reward = "Ma che $Gballerino scatenato:ballerina scatenata; che sei, $N!$B$BEcco il tuo dolcetto, visto che sei $Gstato:stata; al gioco. Buon Hallow's End, e salutami il tuo piccolo amico malato! Spero che guarisca presto.",
  en_title = "Dancing for Marzipan",
  en_obj = "Do a dance emote at Innkeeper Pala, and in exchange you'll receive Thunder Bluff Marzipan!",
}
T[8361] = {
  title = "Contatti Abissali",
  desc = "Abbiamo visto i cultisti del Twilight's Hammer fare rituali per evocare potenti nobili elementali. Non sappiamo se siano loro gli esseri che venerano o se facciano da intermediari per forze ancora più potenti. Una cosa però è certa: gli ordini li ricevono da questi elementali.$B$BVoglio che trovi il modo di contattare un Abyssal Templar e di dargliele di santa ragione! Niente getta le truppe nel caos come togliere di mezzo la catena di comando. E già che ci sei, portami una prova.",
  obj = "Bor Wildmane a Cenarion Hold, in Silithus, vuole che tu distrugga un Abyssal Templar e gli porti un Abyssal Crest come prova dell'impresa.",
  progress = "Il lavoro è fatto?",
  reward = "Ah! Ce l'hai fatta, $N! Presto il Twilight's Hammer sarà schiacciato!",
}
T[8362] = {
  title = "Abyssal Crests",
  progress = "Hai dimostrato che in combattimento te la sai cavare, $N. Continuiamo a fare pressione sul Twilight's Hammer: va' a combattere altri Abyssal Templars e ti ricompenserò con un po' della roba che io e Huum abbiamo trovato in battaglia.",
  reward = "Buon lavoro! Sono Templari in meno di cui preoccuparmi.$B$BEcco qua, $N. Spero che tu ci trovi qualcosa di utile.",
}
T[8363] = {
  title = "Abyssal Signets",
  progress = "Hai dimostrato di poter affrontare un Abyssal Duke senza nessun problema, $N. E io le buone abitudini le incoraggio sempre: portami altri anelli con sigillo e ti darò una ricompensa.",
  reward = "Eccellente, $N! Aver sconfitto quei Duchi farà barcollare il Twilight's Hammer per un po'. Come promesso, ecco la tua ricompensa: è tra la roba migliore che io e Huum abbiamo trovato.",
}
T[8364] = {
  title = "Abyssal Scepters",
  progress = "Hai superato davvero ogni mia aspettativa, $N. Hai affrontato avversari che io e Huum avremmo attaccato solo dopo averci pensato a lungo.$B$BOrmai il massimo che posso fare è continuare a premiare gli sforzi che fai contro il Twilight's Hammer e i suoi signori.$B$BPortami altri abyssal scepters e farò del mio meglio per darti una ricompensa all'altezza.",
  reward = "Lo sapevo che ce l'avresti fatta, $N! Ecco la tua ricompensa.",
}
T[8365] = {
  title = "Cappelli da Pirata, Ohoi!",
  desc = "Sei tu l'aiuto che mi manda il Cartello? Andrai bene, immagino. Stammi a sentire, $C. Come sai, procuro abiti alla moda all'élite di Azeroth. Re e Regine, Capiguerra e, beh, comunque si chiamino le regine dell'Orda: tutti indossano quello che decido io che sia di moda. E lo pagano un occhio della testa, che è la parte migliore.$B$BEcco come andrà. Scendi alla Lost Rigger Cove e procurati un bel po' di cappelli da pirata, in un modo o nell'altro. Credi di farcela?",
  obj = "Haughty Modiste vuole che tu raccolga 20 Southsea Pirate Hats e glieli riporti a Steamwheedle Port, in Tanaris.",
  progress = "Hai tutti e 20 i cappelli? Non ti credo, fammeli vedere. E sarà meglio che siano in perfette condizioni!",
  reward = "Oh, sei un amore, anche se mi hai fatto aspettare più di quanto sia abituata. Con questa spedizione dovrei guadagnare un bel po' di soldi, una volta puliti e personalizzati i cappelli. E siccome un lavoro ben fatto lo ricompenso sempre volentieri, eccoti un pensierino. Un consiglio, dolcezza: spendine un po' per farti un bagno.",
}
T[8366] = {
  title = "Stretta sui Southsea",
  desc = "Argh! Mi chiedono l'impossibile!$B$BLo Steamwheedle Cartel vuole che dia una lezione ai Southsea pirates. Il guaio è che non posso stare in due posti nello stesso momento; devo rimanere qui a mantenere la pace.$B$BUltimamente i pirati se ne infischiano dei soldi per la protezione che il cartello sborsa con regolarità. Perciò vorrei nominarti agente a titolo provvisorio, così vai laggiù e gliela fai vedere tu.$B$BLi trovi alla Lost Rigger Cove, non molto lontano, verso sud. Grazie, $N, te ne devo una!",
  obj = "Security Chief Bilgewhizzle di Steamwheedle Port a Tanaris vuole che tu uccida 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers e 10 Southsea Swashbucklers.",
  progress = "Già di ritorno? Spero che a quei teppisti dei Southsea tu abbia dato una lezione che non scorderanno tanto presto.",
  reward = "$N! Sei $Gil numero uno:la numero uno;!!!$B$BOra che hai sistemato quella feccia dei Southsea, il Cartello mi lascerà respirare un po', ne sono sicuro. Vediamo, cosa posso darti come ricompensa? Che ne dici di qualche moneta, e per il disturbo una di queste cose a tua scelta?",
}
T[8367] = {
  title = "Per il Grande Onore",
  desc = "Servire l'Orda in una delle grandi battaglie contro l'Alleanza porta grande onore! Ma i nostri veri grandi combattenti sono quei pochi che hanno servito l'Orda su TUTTI i fronti che abbiamo aperto. Gli avversari non li sconfiggeremo con qualche schermaglia isolata, ma con una guerra ben coordinata.$B$BVa' a schiacciare l'Alleanza nell'Arathi Basin, nell'Alterac Valley e nella Warsong Gulch! Per l'Onore! Per l'Orda!",
  obj = "Porta 3 Alterac Valley Marks of Honor, 3 Arathi Basin Marks of Honor e 3 Warsong Gulch Marks of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Arathi gronda ancora del sangue di grandi guerrieri, e in tutto l'Alterac il cozzare dell'acciaio non smette di risuonare. Se non porti notizie dal fronte, non farmi perdere tempo!",
  reward = "Non sono state prove facili, ma il coraggio non ti ha abbandonato e la forza non ti è venuta meno. Separati dai vecchi pegni di vittoria, $C: nessuno ne avrà bisogno per ricordare il tuo valore. Stai $Gdritto:dritta;, $N. Oggi camminerai con grande orgoglio, perché sei $Gun eroe:un'eroina;!",
}
T[8368] = {
  title = "Battaglia della Warsong Gulch",
  desc = "La battaglia contro le Silverwing Sentinels nella Warsong Gulch è molto importante. Con la scusa di proteggere una foresta che non le appartiene, l'Alleanza cerca di sottrarre all'Orda una delle nostre maggiori fonti di legname.$B$BNon permetterlo, $N! Torna da me con la prova che hai servito degnamente l'Orda!",
  obj = "Porta 3 Warsong Marks of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Porti notizie dalla Warsong Gulch, $N?",
  reward = "Eccellente! Difendendo le nostre operazioni nella Warsong Gulch hai dimostrato quanto vali! Che la voce del tuo onore corra in lungo e in largo per le nostre terre.",
  en_title = "Battle of Warsong Gulch",
  en_obj = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8369] = {
  title = "Invasori dell'Alterac Valley",
  desc = "Ascoltami bene, $N. Qualunque cosa tu abbia sentito sulla battaglia che infuria nell'Alterac Valley, una cosa è certa: la Stormpike Expedition ha invaso il Territorio Frostwolf. Se mai lasceremo che l'Alleanza invada le terre dell'Orda senza rispondere con decisione, quel giorno appenderò l'ascia al chiodo e passerò il resto della vita nella vergogna. Va' a scacciare gli invasori!",
  obj = "Porta 3 Alterac Valley Marks of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Che notizie porti dalle terre dei Frostwolf? Come va la battaglia per l'Alterac Valley?",
  reward = "Proteggendo le nostre terre nell'Alterac Valley hai mostrato grande coraggio! Riferirò le tue gesta ai miei superiori.",
}
T[8370] = {
  title = "La Conquista dell'Arathi Basin",
  desc = "Il nostro conflitto con l'Alleanza è diventato una guerra vera e propria. Ormai nessuna delle due parti usa più falsi pretesti per scendere in battaglia, né se li aspetta dall'altra.$B$BLa battaglia per l'Arathi Basin è una questione di risorse, né più né meno. O se le prende l'Alleanza per usarle contro di noi, o ce le prendiamo noi per mandare avanti la guerra. Aiuta i Defilers a mantenere il flusso di risorse che ci serve, $N!",
  obj = "Porta 3 Arathi Basin Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Sei $Gtornato:tornata; con notizie da Arathi, $C?",
  reward = "Proteggere le nostre risorse ad Arathi è un compito importante! Hai fatto un buon lavoro, $N.",
  en_title = "Conquering Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8371] = {
  title = "Sforzi Congiunti",
  desc = "Non combattiamo più battaglie isolate contro l'Orda, $Gragazzo:ragazza;.$B$BSe vinciamo su un fronte, togliamo all'Orda risorse che userebbe contro di noi in un'altra battaglia. Allo stesso modo, una battaglia persa, qualunque sia, potrebbe dare il vantaggio al nemico da qualche altra parte del mondo.$B$BAll'Alleanza servono più combattenti capaci di vedere il quadro intero... veri veterani, con tanta esperienza alle spalle! $N, torna da me quando avrai combattuto l'Orda su tutti i campi di battaglia dove siamo impegnati.",
  obj = "Porta 3 Alterac Valley Mark of Honor, 3 Arathi Basin Mark of Honor e 3 Warsong Gulch Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Come vanno 'sti viaggi, $Gragazzo:ragazza;?",
  reward = "Non sei tipo da deludere, $N! Quello che hai imparato va oltre le medaglie e gli encomi da poco. Quello che hai imparato viene solo dall'esperienza e dalla tempra che si indurisce sul campo di battaglia.$B$BHai fatto bene, $C. Sei $Gun vero eroe:una vera eroina; dell'Alleanza!",
}
T[8372] = {
  title = "Combatti per Warsong Gulch",
  desc = "Le Silverwing Sentinels sono in guerra con i Warsong Outriders perché gli Orchi stanno devastando la foresta. Ma per difendere proprio questa foresta ci sono motivi che vanno oltre il semplice amore per la natura.$B$BLa foresta è una barriera strategica, e grazie a lei possiamo difendere Ashenvale da un attacco su larga scala. Senza, Astranaar reggerebbe un giorno o due e poi verrebbe annessa alle Barrens.$B$BFai la tua parte nella lotta contro i Warsong Outriders, $N! Per l'Alleanza!",
  obj = "Porta 3 Warsong Gulch Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Sei $Gtornato:tornata; con notizie dal fronte, $N?",
  reward = "Ben fatto, $N! Hai reso un buon servizio all'Alleanza.",
  en_title = "Fight for Warsong Gulch",
  en_obj = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8373] = {
  title = "Il Potere del Pino",
  desc = "Dell'Hallow's End la cosa che odio di più sono le bombe puzzolenti che i Forsaken usano contro Southshore. Chi l'avrebbe mai detto che festeggiare la liberazione volesse dire un pasticcio che puzza così tanto?$B$BDurante l'Hallow's End, prendi questo purificatore e togli di mezzo le schifose bombe puzzolenti che l'Orda potrebbe lasciare qui nel villaggio. Combatte le puzze con il potere del pino.$B$BDai una mano a tenere pulita Southshore e ti darò dei dolcetti dell'Hallow's End che ti piaceranno di sicuro. Affare fatto?",
  obj = "Usa uno Stink Bomb Cleaner per rimuovere ogni Forsaken Stink Bomb lasciata a Southshore. Torna da Sergeant Hartman a Southshore quando hai finito.",
  progress = "Quei maledetti Forsaken... come se non bastasse essere non morti, si agitano pure e si mettono a combinare guai nel MIO villaggio!",
  reward = "Ah, qui si respira già quasi meglio. Quasi.$B$BGrazie a te, $N, Southshore potrebbe anche superare un'altra Hallow's End. Ecco i tuoi dolcetti, e grazie! Se finisci le caramelle, mi pare che a Ironforge ci sia una gnoma, una certa Katrina Shimmerstar, che può vendertene altre; credo che ci sia solo durante l'Hallow's End.",
  en_title = "The Power of Pine",
  en_obj = "Use a Stink Bomb Cleaner to remove any Forsaken Stink Bomb that's been dropped on Southshore.  Return to Sergeant Hartman in Southshore when you're done.",
}
T[8374] = {
  title = "Conquistare l'Arathi Basin",
  desc = "Per vincere una guerra non basta essere più furbi e più forti dell'avversario. Spesso vince semplicemente chi produce più del nemico.$B$BLo schieramento che riuscirà a conquistare per primo l'Arathi Basin ci troverà una grossa riserva di risorse.$B$BSe vince l'Alleanza, le nostre truppe avranno più spade e picche. Se invece dovesse vincere l'Orda, quelle spade e picche verrebbero forgiate lo stesso, ma puntate contro di noi! È ora di dare una mano all'Alleanza nell'Arathi Basin, $N.",
  obj = "Porta 3 Arathi Basin Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Dimmi, che notizie porti dal fronte?",
  reward = "Ottimo lavoro, soldato! Avanti così e l'Orda la facciamo scappare fino a Orgrimmar.",
  en_title = "Claiming Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8375] = {
  title = "Ricorda l'Alterac Valley!",
  desc = "Mettiamolo in chiaro, $N. L'Orda ha proprio ragione quando dice che l'Alterac Valley è Territorio Frostwolf.$B$BVedi, la Stormpike Expedition è arrivata nella zona in pace, a cercare minerali e reliquie. E i Frostwolf hanno risposto con l'atto di aggressione più brutale e incivile che l'Alleanza abbia mai subito.$B$BNon dimentichiamo mai i coraggiosi nani morti in quel vile attacco a sorpresa. Ora va', $C, e fai la tua parte nella battaglia per l'Alterac Valley. Per l'Alleanza!",
  obj = "Porta 3 Alterac Valley Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Che notizie mi porti, $N?",
  reward = "Hai fatto la tua parte, $N. Gli atti incivili dell'Orda l'Alleanza non può lasciarli impuniti!",
}
T[8376] = {
  title = "Armamenti di Guerra",
  reward = "La guerra è alle porte, $N, e si porta dietro orrori indicibili. Hai fatto tutto quello che ti si poteva chiedere, e una ricompensa te la meriti.$B$BSe mai questa... questa profezia si avverasse...$B$B<Geologist Larksbane impallidisce.>$B$BPer tutti noi potrebbe non esserci più un futuro.$B$BQuesti armamenti ti saranno preziosissimi per la campagna in questo deserto.",
}
