T[8383] = {
  title = "Ricorda l'Alterac Valley!",
  progress = "Nell'Alterac Valley la Battaglia infuria ancora, $N! E tu, $N, hai fatto la tua parte di recente?",
  reward = "Continui a fare onore all'Alleanza, $N. Se non molliamo, l'Orda sarà presto schiacciata.",
}
T[8384] = {
  title = "Conquistare l'Arathi Basin",
  progress = "Con la guerra contro l'Orda le nostre provviste se ne vanno in fretta, $N. Tenere il controllo dell'Arathi Basin è fondamentale, se vogliamo che le risorse continuino ad arrivare! Hai già dato una mano in Arathi?",
  reward = "Ottimo lavoro, $C! Con i tuoi sforzi aiuterai l'Alleanza a procurarsi le risorse che le servono.",
  en_title = "Claiming Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8385] = {
  title = "Sforzi Congiunti",
  progress = "Ah, $N. Spero che continuerai a portare la tua esperienza sui vari fronti. Molti dei nostri ragazzi e ragazze sul campo ammirano i veterani navigati come te.",
  reward = "La tua fama è tutta meritata, $N. Senza gente come te, l'Alleanza non avrebbe speranza contro le forze selvagge dell'Orda.",
}
T[8386] = {
  title = "Lotta per la Warsong Gulch",
  progress = "Ricordati che nella lotta per la Warsong Gulch non si tratta solo di proteggere gli alberi. Quello che conta è mantenere una barriera naturale tra Ashenvale e le Barrens. Hai notizie dal campo di battaglia, $N?",
  reward = "Buon lavoro, $N. Grazie a te, le nostre difese naturali in Ashenvale resteranno intatte per un altro giorno.",
  en_title = "Fight for Warsong Gulch",
  en_obj = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8387] = {
  title = "Invasori dell'Alterac Valley",
  progress = "La battaglia per l'Alterac infuria ancora! Devi tornare nell'Alterac Valley e ricacciare ancora una volta gli invasori dal territorio Frostwolf, $N!",
  reward = "Ottimo lavoro, $N! Dovresti essere $Gfiero:fiera; di te. Gli invasori dell'Alleanza vanno scacciati dall'Alterac!",
}
T[8388] = {
  title = "Per un Grande Onore",
  progress = "Sono tanti i guerrieri coraggiosi che ti guardano con ammirazione, $N. Nella lotta contro l'Alleanza resti un esempio per tutti. Che notizie porti dai tuoi viaggi?",
  reward = "Fai ancora onore all'Orda, $N. Mi fa piacere vedere che non ti sei $Grammollito:rammollita;.",
}
T[8389] = {
  title = "Battaglia di Warsong Gulch",
  progress = "Nella Warsong Gulch la battaglia infuria ancora, $N. Fa' la tua parte per cacciare le Silverwing Sentinels dalle nostre terre!",
  reward = "Ben fatto, $C! Hai aiutato l'Orda ad assicurarsi il controllo della Warsong Gulch!",
  en_title = "Battle of Warsong Gulch",
  en_obj = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8390] = {
  title = "Conquistare Arathi Basin",
  progress = "Per fare la guerra alla feccia dell'Alleanza servono risorse, $N! Non possiamo restare senza scorte nel bel mezzo di una battaglia. Continua a tenere l'Arathi Basin nelle nostre mani!",
  reward = "Mettere al sicuro le nostre risorse ad Arathi è un compito importante! Hai lavorato bene, $N.",
  en_title = "Conquering Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8391] = {
  title = "Conquistare l'Arathi Basin",
  progress = "Con la guerra contro l'Orda le nostre provviste se ne vanno in fretta, $N. Tenere il controllo dell'Arathi Basin è fondamentale, se vogliamo che le risorse continuino ad arrivare! Hai già dato una mano in Arathi?",
  reward = "Buon lavoro, $Gsoldato:soldatessa;! Continua così e l'Orda la faremo scappare fino a Orgrimmar.",
  en_title = "Claiming Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8392] = {
  title = "Conquistare l'Arathi Basin",
  progress = "Con la guerra contro l'Orda le nostre provviste se ne vanno in fretta, $N. Tenere il controllo dell'Arathi Basin è fondamentale, se vogliamo che le risorse continuino ad arrivare! Hai già dato una mano in Arathi?",
  reward = "Ottimo lavoro, $C! Con i tuoi sforzi aiuterai l'Alleanza a procurarsi le risorse che le servono.",
}
T[8393] = {
  title = "Conquistare l'Arathi Basin",
  desc = "Una guerra non si vince soltanto superando l'avversario in astuzia e in battaglia. Spesso, alla fine, vince chi produce più del nemico.$B$BNell'Arathi Basin c'è una bella riserva di risorse, e andrà alla prima fazione che riuscirà a conquistarlo.$B$BSe vince l'Alleanza, le nostre truppe avranno più spade e più picche. Se invece dovesse vincere l'Orda, quelle spade e quelle picche verrebbero fatte lo stesso, solo che le punterebbero contro di noi! È ora di dare una mano all'Alleanza nell'Arathi Basin, $N.",
  obj = "Porta 3 Arathi Basin Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Dimmi un po', che notizie arrivano dal fronte?",
  reward = "Ottimo lavoro, $Gsoldato:soldatessa;! Avanti così e faremo scappare l'Orda fino a Orgrimmar.",
  en_title = "Claiming Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
