T[8397] = {
  title = "Conquistare l'Arathi Basin",
  progress = "La guerra con l'Orda sta consumando in fretta le nostre provviste, $N. Dobbiamo assolutamente tenere il controllo dell'Arathi Basin, perché le risorse continuino ad arrivare! Hai già dato una mano in Arathi?",
  reward = "Ottimo lavoro, $C! Il tuo impegno aiuterà l'Alleanza ad avere le risorse che le servono.",
}
T[8398] = {
  title = "La Conquista di Arathi Basin",
  progress = "La guerra contro l'Orda ci sta prosciugando le scorte in fretta, $N. Tenere Arathi Basin è fondamentale, se vogliamo che le risorse continuino ad arrivare! Hai già dato una mano ad Arathi?",
  reward = "Ottimo lavoro, $C! Il tuo impegno aiuterà l'Alleanza ad avere le risorse che le servono.",
}
T[8399] = {
  title = "Combatti per Warsong Gulch",
  desc = "Le Silverwing Sentinels sono in guerra contro i Warsong Outriders perché gli Orchi stanno distruggendo la foresta. Ma per difendere proprio questa foresta ci sono altre ragioni, oltre al semplice amore per la natura.$B$BÈ una barriera strategica, che ci permette di proteggere Ashenvale da un attacco su larga scala. Senza, Astranaar resisterebbe un giorno o due e poi verrebbe annessa alle Barrens.$B$BFai la tua parte contro i Warsong Outriders, $N! Per l'Alleanza!",
  obj = "Porta 3 Warsong Gulch Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Sei $Gtornato:tornata; dal fronte con qualche notizia, $N?",
  reward = "Buon lavoro, $N. Grazie a te, le nostre difese naturali ad Ashenvale resteranno in piedi per un altro giorno.",
  en_title = "Fight for Warsong Gulch",
  en_obj = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
