T[8403] = {
  title = "Lotta per Warsong Gulch",
  desc = "Le Silverwing Sentinels fanno la guerra ai Warsong Outriders perché gli Orchi stanno distruggendo la foresta. Ma per difendere proprio questa foresta c'è ben altro che il semplice amore per la natura.$B$BQuella foresta è una barriera strategica: è grazie a lei che possiamo difendere Ashenvale da un attacco su larga scala. Senza la foresta, Astranaar reggerebbe un giorno o due, poi verrebbe annessa alle Barrens.$B$BFai la tua parte nella lotta contro i Warsong Outriders, $N! Per l'Alleanza!",
  obj = "Porta 3 Warsong Gulch Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Allora, $N, sei $Gtornato:tornata; con notizie dal fronte?",
  reward = "Ben fatto, $N! Hai servito l'Alleanza come si deve.",
}
