T[8408] = {
  title = "Battaglia per Warsong Gulch",
  progress = "Non dimenticarlo: la battaglia per Warsong Gulch non si combatte solo per proteggere gli alberi, ma anche per tenere in piedi una barriera naturale tra Ashenvale e i Barrens. Allora, $N, mi porti notizie dal campo di battaglia?",
  reward = "Ottimo lavoro, $N. Grazie a te le nostre difese naturali ad Ashenvale resteranno intatte per un altro giorno.",
}
T[8409] = {
  title = "Barili Rovinati",
  desc = "Sei $Griuscito:riuscita; a mettere le Rotten Eggs nel barile. I prossimi barili di birra della Southshore Inn saranno rovinati di sicuro!$B$BOra dovresti tornare da Darkcaller Yanka al Wickerman Festival, a Tirisfal Glade, per riferirle del tuo successo.",
  obj = "Torna da Darkcaller Yanka al Wickerman Festival, a Tirisfal Glade.",
  reward = "Ah, ce l'hai fatta! Hai mostrato il vero spirito di Hallow's End — anzi, dovrei dire lo spirito dei REIETTI!$B$B<Darkcaller Yanka ride e si sfrega le mani.>$B$BChe goduria sapere che ora Southshore dovrà banchettare con birra avariata o farne del tutto a meno! Quanto a te, prendi questi dolcetti. Credo che saprai farne buon uso!",
  en_title = "Ruined Kegs",
  en_obj = "Return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.",
}
T[8410] = {
  title = "Maestria Elementale",
  desc = "Bath'rah the Windwatcher ha mandato a chiamare $Guno sciamano saggio:una sciamana saggia; come te: vuole che gli porti un campione di ogni elemento, per dimostrare che sei $Gpronto:pronta;.$B$BPer trovare Bath'rah, raggiungi il fiume a est di Tarren Mill e seguilo verso nord fino alle rovine dove vive Bath'rah.",
  obj = "Raccogli un campione di aria, fuoco, terra e acqua per Bath'rah the Windwatcher.",
  progress = "Cosa mi hai portato, $C?",
  reward = "Ottimo, mon. Ora possiamo parlare.",
}
T[8411] = {
  title = "Padroneggiare gli Elementi",
  desc = "$GBenvenuto:Benvenuta;, mon. Prima portami gli elementi, poi parliamo.",
  obj = "Porta gli elementi terra, aria, fuoco e acqua a Bath'rah the Windwatcher.",
  progress = "Gli elementi dove sono, mon?",
  reward = "Ecco gli elementi che mi servono. Adesso parliamo.",
}
T[8412] = {
  title = "Spirit Totem",
  desc = "Gli spiriti elementali di qui non mi vedono più di buon occhio.$B$BDi totem ne sai più di chiunque altro, e a me serve uno spirit totem che mi protegga. Gli elementi ce li abbiamo già: adesso ci vuole qualcosa di più legato alla natura. Di più primordiale.$B$BNelle Western Plaguelands puoi uccidere gli orsi per prendere gli artigli e i ragni per gli occhi. Gli uccelli spazzini mangiano di tutto, quindi potrebbero avere gli uni o gli altri.",
  obj = "Porta i pezzi per lo spirit totem a Bath'rah the Windwatcher.",
  progress = "Gli spiriti sanno cosa stiamo combinando, e cercano di uccidermi! Spero che i pezzi li hai.",
  reward = "Grande, mon! Proviamolo...",
}
T[8413] = {
  title = "Il Vudù",
  desc = "Lo spirit totem così non basta proprio. Ci serve un po' di magia vudù per farlo funzionare come si deve.$B$BNel tempio sommerso i troll hanno piume cariche di magie vudù. Va' là e uccidi Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Poi la magia ci basta per un vero spirit totem.",
  obj = "Porta le voodoo feathers a Bath'rah the Windwatcher.",
  progress = "Dove stanno le piume, mon?",
  reward = "Era ora che questo troll dormisse una notte intera! Ora a vegliare su di me c'è lo spirit totem.$B$BÈ un sacco di tempo che raccolgo cose, magari vuoi qualcosa per tutto il disturbo?",
}
T[8414] = {
  title = "Dissipare il Male",
  desc = "Saluti, $C. Che piacere vedere crociati come te in queste terre desolate.$B$BQui i non morti non finiscono mai, e per combatterli serve la tua forza sacra. Dovresti raccogliere un gran numero di scourgestone e portarle a High Priest Thel'danis: lo trovi a guardia della Tomba di Uther, sul Sorrow Hill, non lontano da qui.$B$BPuò sperare di trovare le scourgestone solo chi ha un Argent Dawn Commission, quindi, se non l'hai già fatto, parla con Officer Pureheart.",
  obj = "Raccogli 20 Minion's Scourgestones e portale a High Priest Thel'danis nelle Western Plaguelands.",
  progress = "Che male mi hai portato?",
  reward = "Dissipare il male da una scourgestone è un rischio, perché attira l'attenzione dei non morti per miglia e miglia. Ma tu sei $Gforte:forte; nella Luce, $N, e non temo per te...",
}
T[8415] = {
  title = "Chillwind Point",
  desc = "Commander Ashlam Valorfist ha lanciato un appello, $N: gli serve $Gun paladino:una paladina; della tua purezza e del tuo valore. Lo trovi a Chillwind Point, nel sud delle Western Plaguelands. Raggiungilo e aiutalo nella sua causa per la Luce!",
  obj = "Parla con Commander Ashlam Valorfist a Chillwind Point.",
  reward = "Molto bene, $C! Ora vediamo di che pasta sei $Gfatto:fatta;.",
}
T[8416] = {
  title = "Inert Scourgestones",
  desc = "Ora le pietre sono purificate dal male, $N.$B$BSo quali sono i piani del Comandante Ashlam: gli servirà solo una scourgestone inerte. Portagliela, e potremo avvolgere lo Scourge nel fuoco della giustizia.",
  obj = "Porta l'Inert Scourgestone a Commander Ashlan Valorfist a Chillwind Point.",
  progress = "Allora, Thel'danis è riuscito a purificare le scourgestone?",
  reward = "Hai fatto quello che ti ho chiesto senza fare domande, $N.$B$BA quanto pare, la mia fiducia te la sei guadagnata. Forse adesso posso spiegarti il nostro piano più nel dettaglio.",
}
T[8417] = {
  title = "Uno Spirito Tormentato",
  desc = "Nelle Blasted Lands c'è uno spirito tormentato, un tempo grande eroe dell'Orda. L'onore di un guerriero non muore con il corpo: parlare con lui ti gioverebbe.",
  obj = "Parla con il Fallen Hero of the Horde all'ingresso di Blasted Lands.",
  progress = "Allora, Stoley l'ha sganciata, la mia roba da bere?",
  reward = "Dunque sei $Gvenuto:venuta; ad alleviare il mio dolore. Magari bastasse abbattermi, ma non è così semplice...",
}
T[8418] = {
  title = "Forgiare la Pietragrossa",
  desc = "Adesso dobbiamo unire le inert scourgestones per creare un'arma capace di frantumare le file dei non morti. Non è cosa da poco, $N: solo i troll del tempio sommerso possiedono la rara magia che ritorce contro una cosa il suo stesso male.$B$BNel tempio quei troll li conoscono come Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Non avere rimorsi per le loro anime corrotte... non sono prive di malvagità.",
  obj = "Porta le voodoo feathers ad Ashlam Valorfist.",
  progress = "Li hai uccisi, quei miserabili troll?",
  reward = "Eccellente, $N. Potrei dirmi sorpreso, ma sapevo che non ci avresti delusi.$B$BHo l'onore di consegnarti una delle Holy Mightstones. Usala bene.",
}
T[8419] = {
  title = "La Richiesta di un Imp",
  desc = "$N, un imp di Felwood che si chiama Impsy ha chiesto di vederti. La cosa è un po' strana: vuole che gli porti un pezzo di felcloth in segno di buona fede. Con il potere che hai già come $Gstregone:stregona;, immagino tu sappia che i satiri di Felwood portano la felcloth con sé.$B$BImpsy lo trovi poco a nord delle Bloodvenom Falls che, a quanto ho sentito, in questo periodo dell'anno sono davvero belle.",
  obj = "Porta un pezzo di felcloth a Impsy in Felwood.",
  progress = "Hai il mio felcloth?",
  reward = "Che $Gsplendido:splendida; $C sei!$B$B<Impsy si porta la felcloth al viso.>$B$BOh, quanto adoro sentirlo addosso: ti brucia la pelle e ti intreccia pensieri malvagi nella mente...",
}
T[8420] = {
  title = "Bollente e Pizzicante",
  desc = "Forse ti sembrerà strano detto da un imp, ma vorrei un animaletto tutto mio. Sul serio. Non è giusto che Niby abbia me e io non abbia niente!$B$BE non serve nemmeno che sia vivo. Per cominciare a costruirlo mi servirebbe qualcosa tipo un po' di felcloth. Qui a Felwood i satiri a volte hanno della felcloth con sé: ti basta ucciderne finché non ne trovi un po'. Non è poi così terribile, no?",
  obj = "Porta un pezzo di felcloth a Impsy in Felwood.",
  progress = "Hai il mio felcloth?",
  reward = "Wow! Sei troppo gentile, soprattutto per $Guno stregone:una stregona;!$B$B<Impsy si porta la felcloth al viso.>$B$BOh, quanto adoro sentirlo addosso: ti brucia la pelle e ti intreccia pensieri malvagi nella mente...",
}
T[8421] = {
  title = "La Roba Sbagliata",
  desc = "Ora che ho il mio felcloth posso cominciare sul serio a creare il *mio* animaletto.$B$BPerò gli serviranno degli occhi. Potresti strappare un po' di rotting wood al popolo degli alberi di ferro, così ci intaglio due occhi adorabili. Stanno a nord, nell'Irontree Woods.$B$BPer dargli quel profumo di demone nuovo mi servirà anche un po' di bloodvenom essence: ce l'hanno le tainted oozes che girano proprio qui, vicino a me e a Niby.",
  obj = "Porta 10 Rotting Wood e 4 Bloodvenom Essence a Impsy in Felwood.",
  progress = "Hai la roba?",
  reward = "Andrà benissimo.",
}
T[8422] = {
  title = "Troll della Stessa Piuma",
  desc = "Il mio animaletto è quasi pronto: ora mi manca solo qualcosa per imbottirlo.$B$BE vanno bene soltanto le voodoo feathers dei troll del tempio sommerso. Sono Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Uccidili. Uccidili tutti.$B$BNon è un compito da poco, $N, quindi, perché ne valga la pena, ti darò qualcosa di Niby — tanto a lui probabilmente non serve.",
  obj = "Porta in tutto 6 Voodoo Feathers prese ai troll del tempio sommerso.",
  progress = "Me le hai portate, le piume? Questa bambola va imbottita!",
  reward = "Magnifico, ora il mio animaletto è completo!$B$B<Impsy imbottisce in fretta la bambola e la stringe in un abbraccio demoniaco.>$B$BOh, che strano effetto collaterale hanno queste voodoo feathers...",
}
T[8423] = {
  title = "Affinità tra Guerrieri",
  desc = "<L'Eroe ti squadra.>$B$BSei $Gun:una; $C, non c'è dubbio. Vorrei affidarti un compito d'onore, ma prima devo mettere alla prova la tua forza.$B$BSi dice che Rexxar misurasse il filo delle sue lame uccidendo un cinghiale infernale con un colpo solo, rapido. Ora io misurerò la tua forza: ucciderai quei cinghiali.",
  obj = "Uccidi 7 Helboar in Blasted Lands e torna dal Fallen Hero of the Horde.",
  progress = "Gli aculei ardenti dei cinghiali infernali lasciano cicatrici orribili. Non temere il dolore né lo sfregio, $Gguerriero:guerriera;: non sono niente in confronto alla prigione a cui sono legato.",
  reward = "Non mi servono prove per sapere cosa hai fatto, $C. Lo vedo dalla determinazione scolpita sul tuo volto.",
}
T[8424] = {
  title = "Guerra ai Giurati dell'Ombra",
  desc = "I giurati dell'ombra non se ne vanno dalle Blasted Lands, e questo mi provoca un grande dolore. Con i loro oscuri rituali e i loro incantesimi mi infliggono un'agonia che da vivo non ho mai provato.$B$BAttraverso di te posso far arrivare il mio messaggio di dolore. Va' e porta la mia ira.",
  obj = "Massacra i Giurati dell'Ombra in Blasted Lands e torna dal Fallen Hero of the Horde.",
  progress = "Non è facile sconfiggere i giurati dell'ombra, vero? Ma tu sei $Gun guerriero:una guerriera;: trionferai, o morirai provandoci.",
  reward = "Hai già placato il mio dolore e mi hai reso onore. Ti ringrazio, $C.",
}
T[8425] = {
  title = "Voodoo Feathers",
  desc = "Il tuo onore mi ha dato un po' di pace, ed è giusto che io ti offra qualcosa in cambio.$B$BDa vivo avevo armi e armatura splendide, ma ora non mi servono a nulla: starebbero meglio nelle tue mani.$B$BVa' al tempio sommerso e distruggi i guardiani troll Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Hanno con sé delle piume magiche capaci di ricomporre il mio corpo per il tempo che basta a ricompensarti.",
  obj = "Porta le Voodoo Feathers dei troll in Sunken Temple al Fallen Hero of the Horde.",
  progress = "Sei già $Gtornato:tornata;? Per me il tempo non è più lo stesso: forse per te è stato davvero un lungo viaggio...",
  reward = "Finalmente sento di nuovo il freddo tocco dell'acciaio, anche se solo per un istante.",
}
T[8426] = {
  title = "Battaglia di Warsong Gulch",
  desc = "La battaglia contro le Silverwing Sentinels nella Warsong Gulch è di grande importanza. Con la scusa di proteggere una foresta che non è sua, l'Alleanza cerca di togliere all'Orda una delle nostre più grandi fonti di legname.$B$BNon permetterlo, $N! Torna da me con la prova di aver servito degnamente l'Orda!",
  obj = "Porta 3 Warsong Gulch Marks of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "La battaglia contro le Silverwing Sentinels nella Warsong Gulch è di grande importanza. Con la scusa di proteggere una foresta che non è sua, l'Alleanza cerca di togliere all'Orda una delle nostre più grandi fonti di legname.$B$BNon permetterlo, $N! Torna da me con la prova di aver servito degnamente l'Orda!",
  reward = "Eccellente! Difendendo le nostre operazioni nella Warsong Gulch hai dimostrato quanto vali! Che del tuo onore si parli in lungo e in largo per le nostre terre.",
  en_title = "Battle of Warsong Gulch",
  en_obj = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
}
