T[8436] = {
  title = "Conquista dell'Arathi Basin",
  desc = "Lo scontro fra noi e l'Alleanza è diventato guerra vera. Ormai nessuna delle due parti cerca più falsi pretesti per scendere in battaglia, e nessuna se li aspetta.$B$BNell'Arathi Basin si combatte per le risorse, punto e basta. O se le prende l'Alleanza e le usa contro di noi, o ce le prendiamo noi e ci mandiamo avanti la nostra guerra. Aiuta i Defilers a tenere aperto il flusso di risorse che ci serve, $N!",
  obj = "Porta 3 Arathi Basin Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Sei $Gtornato:tornata; da Arathi con delle notizie, $C?",
  reward = "Mettere al sicuro le nostre risorse ad Arathi è un compito importante! Hai lavorato bene, $N.",
  en_title = "Conquering Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8437] = {
  title = "Conquista dell'Arathi Basin",
  desc = "Lo scontro fra noi e l'Alleanza è diventato guerra vera. Ormai nessuna delle due parti cerca più falsi pretesti per scendere in battaglia, e nessuna se li aspetta.$B$BNell'Arathi Basin si combatte per le risorse, punto e basta. O se le prende l'Alleanza e le usa contro di noi, o ce le prendiamo noi e ci mandiamo avanti la nostra guerra. Aiuta i Defilers a tenere aperto il flusso di risorse che ci serve, $N!",
  obj = "Porta 3 Arathi Basin Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Sei $Gtornato:tornata; da Arathi con delle notizie, $C?",
  reward = "Mettere al sicuro le nostre risorse ad Arathi è un compito importante! Hai lavorato bene, $N.",
}
T[8438] = {
  title = "Alla Conquista dell'Arathi Basin",
  desc = "Fra noi e l'Alleanza ormai è guerra vera. Nessuna delle due parti cerca più falsi pretesti per scendere in battaglia, né se li aspetta dall'altra.$B$BNell'Arathi Basin si combatte per le risorse, né più né meno. O se le prende l'Alleanza per usarle contro di noi, o ce le prendiamo noi per mandare avanti la guerra. Aiuta i Defilers a non far mai mancare il flusso di risorse che ci serve, $N!",
