T[8440] = {
  title = "Alla Conquista dell'Arathi Basin",
  progress = "Per fare la guerra a quella feccia dell'Alleanza servono risorse, $N! Non possiamo restare senza scorte nel pieno della battaglia. Continua a tenere l'Arathi Basin nelle nostre mani!",
  reward = "Ottimo lavoro, $N! Finché l'Arathi Basin resta in mano nostra, di provviste ne avremo in abbondanza.",
