}
T[8446] = {
  title = "Avvolto nell'Incubo",
  desc = "Da questo oggetto trasuda la corruzione.$B$BPotrebbe esserci un legame tra l'oggetto e i draghi che escono dal Sogno. Devi trovare qualcuno in grado di decifrarne il significato. Forse i druidi di Moonglade o di Cenarion Hold sapranno dirti di più.",
  obj = "Trova qualcuno in grado di decifrare il significato del Nightmare Engulfed Object.$B$BForse un druido di grande potere potrebbe aiutarti.",
  progress = "Sì, $R?",
  reward = "Devo purificare questo oggetto dalla contaminazione. Potrebbe aiutarmi a capire perché di recente non sono riuscito ad addentrarmi nel Sogno. Dammelo.",
}
T[8447] = {
  title = "Leggende al Risveglio",
  desc = "Le acque del Lake Elune'ara dovrebbero dissolvere gli incubi che avvolgono questo oggetto. Dammi un momento per purificarlo, $N.",
  obj = "Attendi che Keeper Remulos purifichi il Nightmare Engulfed Object a Moonglade.",
  reward = "Prendi il suo anello, $N. Per Malfurion ha assolto il suo compito. Ora ne avrà uno nuovo per te...",
}
T[8460] = {
  title = "Timbermaw Ally",
  desc = "I Timbermaw sono l'unica tribù di furbolg sfuggita alla corruzione. Eppure ora molte altre razze uccidono i furbolg alla cieca, senza chiedersi se siano amici o nemici. Per questo i furbolg Timbermaw si fidano di pochissimi.$B$BVuoi dimostrare quanto vali? Respingi la tribù corrotta dei Deadwood di Felwood, e un giorno potremmo considerarti $Gun alleato:un'alleata;. La prima tribù Deadwood — guerrieri, ricognitori e giardinieri — la troverai a ovest di qui.",
  obj = "Grazle vuole che tu dimostri il tuo valore uccidendo 6 Deadwood Warriors, 6 Deadwood Pathfinders e 6 Deadwood Gardeners. Quando hai finito, torna da lui nel sud di Felwood, vicino a Emerald Sanctuary.",
  progress = "Continua così, $N. Se vuoi guadagnarti la nostra fiducia, dovrai dimostrarci quanto vali.",
  reward = "Quello che è successo in passato ci fa soffrire molto. Grazie di quanto hai fatto per aiutare a proteggere i Timbermaw. Ti prego di accettare questa umile offerta, in segno della nostra amicizia che cresce.",
}
T[8461] = {
  title = "I Deadwood del Nord",
  desc = "Proprio a sud-ovest di qui c'è un accampamento di furbolgs Deadwood, tutto permeato dalla corruzione, e desidero porvi fine prima che diventino un problema.$B$BLa tribù Deadwood è malvagia, ma solo perché l'energia vil le inquina la mente: la loro ostilità non è davvero innata. Eppure per loro non si può fare nulla, e mi rattrista dover combattere i nostri stessi fratelli.$B$BTi prego, $N — fai ciò che va fatto. Risparmiami solo i dettagli; immagini così penose mi turbano fin troppo.",
  obj = "Nafien vuole che tu uccida 6 Deadwood Den Watchers, 6 Deadwood Avengers e 6 Deadwood Shamans. Torna da lui nel nord di Felwood, vicino all'ingresso di Timbermaw Hold.",
  progress = "Quando avrai conquistato la fiducia dei Timbermaw, sono sicuro che potremo fare qualcosa per te. I Timbermaw non dimenticano i loro alleati, tanto più in tempi bui come questi.",
  reward = "Sento che hai vinto. Vittoria... che parola vuota, dopo quello che si è dovuto fare. Comunque sia, ti sei $Gdimostrato:dimostrata; $Gdegno:degna; della nostra fiducia.$B$BForse ci vorrà del tempo prima che i Timbermaw ti accolgano nel Rifugio senza ostilità, ma la tua perseveranza eroderà ogni sospetto che i miei fratelli potrebbero nutrire verso di te. Finché non ci tradirai e non alzerai le armi contro di noi, un'intesa la troveremo.",
}
T[8462] = {
  title = "Parla con Nafien",
  desc = "Forse sei in grado di affrontare una minaccia più grande che incombe su noi Timbermaw. Qui, di certo, hai dimostrato di esserne capace...$B$BMolto più a nord, lungo questa strada, un altro della mia specie fa la guardia davanti all'ingresso di Timbermaw Hold. Si chiama Nafien; anche se può sembrare una bestia selvaggia e sgradevole, non devi temerlo. Cerca solo aiuto contro le forze maligne che minacciano la nostra casa.",
  obj = "Viaggia verso nord lungo la strada principale di Felwood e parla con il furbolg di nome Nafien. Fa la guardia fuori dall'ingresso di Timbermaw Hold.",
  reward = "Ah... il vento mi ha portato voce di chi, pur non essendo dei nostri, cerca l'alleanza dei furbolgs Timbermaw. Ti do il benvenuto, ma sappi che la mia tribù non vede di buon occhio gli stranieri.$B$BSono tempi difficili, e possiamo fidarci solo di chi sceglie di combattere al nostro fianco la corruzione della terra... e ce l'ha dimostrato come si deve. Gli altri, se dovessero entrare nel Rifugio, troveranno aperta ostilità.",
}
T[8464] = {
  title = "Attività dei Winterfall",
  desc = "I Timbermaw tendono a stare per conto loro, $N. Garantiamo un passaggio sicuro a chi ha la nostra fiducia, ma per quanto possibile evitiamo le altre tribù di furbolg.$B$BDi recente la tribù Winterfall è diventata sempre più ostile con noi. Sembra in preda alla rabbia, completamente travolta dalla paura e dall'odio per qualunque cosa non capisca.$B$BDevo chiederti di sfoltirne le fila, così che siano meno una minaccia per noi. Li trovi nel Winterfall Village, molto a est di qui.",
  obj = "Salfa vuole che tu uccida 8 Winterfall Shaman, 8 Winterfall Den Watchers e 8 Winterfall Ursa. Salfa si trova appena fuori dall'ingresso di Timbermaw Hold, a Winterspring.",
  progress = "Apprezziamo molto quello che hai fatto per i Timbermaw, $N. Continua così e di certo ti guadagnerai la fiducia e il rispetto della mia tribù.",
  reward = "Grazie per quello che hai fatto, per quanto triste sia. Accetta questo in segno di gratitudine.$B$BTi chiederei di continuare ad aiutarci, $N: abbiamo pochissimi alleati a cui rivolgerci e, senza il tuo aiuto, le minacce contro la mia tribù sarebbero di certo troppo grandi per affrontarle da soli.",
}
T[8465] = {
  title = "Parla con Salfa",
  desc = "La corruzione non ci minaccia solo da sud, con i furbolgs Deadwood, ma anche da est, con i furbolgs Winterfall di Winterspring. Se vuoi aiutarci ancora, parla con Salfa, dall'altra parte del Rifugio, all'ingresso che dà su Winterspring. Ci arrivi seguendo il sentiero a sinistra.$B$BStai in guardia — se i miei simili là dentro ti considerano ostile o $Godiato:odiata;, ti attaccheranno. Muoviti più in fretta che puoi ed evita gli scontri. Uccidere un Timbermaw — anche per legittima difesa — non farà che allontanarti ancora di più da noi.",
  obj = "Attraversa Timbermaw Hold ed esci a Winterspring. Parla con Salfa, che fa la guardia fuori dall'ingresso di Timbermaw Hold.",
  reward = "Salute, $C — sono qui di guardia come portavoce dei Timbermaw a Winterspring e come $Gdifensore:difensora; della tribù.$B$BI nostri fratelli Winterfall, in questa terra gelida, sono caduti preda dello stesso influsso corruttore dei furbolg di Felwood. Se sei $Gvenuto:venuta; fin qui per aiutare i furbolgs Timbermaw, siamo pronti ad accettare il tuo aiuto.",
}
T[8466] = {
  title = "Piume per Grazle",
  progress = "Con me hai dato prova del tuo valore, ma potresti doverlo dimostrare ancora ai fratelli della mia tribù, che sono diffidenti. Per questo potrei ancora esserti utile.$B$BAlcuni furbolgs Deadwood portano un copricapo caratteristico, che può servire a provare che ne stai sfoltendo le file. Portami una piuma da ognuno che riesci a prendere; per ogni cinque che mi consegni, ti guadagnerai la stima dei Timbermaw.",
  reward = "Ben fatto, $N! Farò sapere delle tue imprese a quelli della mia specie.$B$BRicordati di portarmi tutte le piume che trovi. Continuerò a prenderle finché ce ne sarà bisogno.",
}
T[8467] = {
  title = "Piume per Nafien",
  progress = "Con me hai già dato prova del tuo valore, ma potresti doverlo dimostrare ancora ai fratelli della mia tribù, che sono sospettosi. E in questo potrei aiutarti di nuovo.$B$BAlcuni furbolgs Deadwood portano un copricapo particolare, che può servire come prova di averne ridotto il numero. Portami una piuma da ogni copricapo che recuperi; per ogni cinque che mi consegnerai, otterrai il riconoscimento dei Timbermaw.",
  reward = "Ben fatto, $N! Farò conoscere alla mia gente le tue imprese.$B$BRicordati di portarmi tutte le piume che trovi. Le accetterò ancora, finché ce ne sarà bisogno.",
}
T[8469] = {
  title = "Perline per Salfa",
  progress = "La mia fiducia l'hai di certo conquistata, $N, ma forse quella della mia tribù devi ancora guadagnartela, perché non si fida facilmente. C'è un modo per riuscirci.$B$BSi sa che i Winterfall portano con sé perline spirituali per proteggersi dagli spiriti maligni. Evidentemente non sono servite allo scopo, visto che a portare la corruzione sono proprio i Winterfall. Portami le perline spirituali dei furbolgs Winterfall caduti: per ogni serie di cinque che mi consegnerai, otterrai riconoscimento tra i Timbermaw.",
  reward = "Ancora una volta ci dai prova del tuo onore! Farò sapere alla mia gente delle tue gesta.$B$BRicordati di portarmi tutte le perline dei Winterfall che trovi: per ogni altra serie che mi porterai, parlerò in tuo favore alla tribù.",
}
T[8470] = {
  title = "Deadwood Ritual Totem",
  desc = "Hai trovato uno dei totem rituali dei furbolgs Deadwood. Il totem in sé è di fattura anonima, ma emana un senso di disperazione palpabile. Se c'è un oggetto che può rappresentare al meglio la corruzione che affligge i furbolgs Deadwood, è di sicuro questo.$B$BA qualcuno dei furbolgs di Timbermaw Hold un oggetto del genere potrebbe servire... sempre che tu ti sia $Gguadagnato:guadagnata; abbastanza la loro fiducia da farli parlare con te.",
  obj = "Porta il Deadwood Ritual Totem all'interno di Timbermaw Hold e vedi se uno dei furbolgs che si trovano lì saprà trovare un uso per l'oggetto. I Timbermaw non parleranno con te se la tua reputazione con loro non è almeno Neutrale.",
  progress = "Sì, $C, cosa posso fare per te? Cammini tra noi in pace, ma di certo qualcosa non va. Sento qualcosa... qualcosa di inquietante...",
  reward = "Questo totem... lo riconosco, è dei Deadwood, ma è impregnato del fetore della putrefazione. Il marciume che ha rivolto i nostri fratelli contro di noi, qualunque sia, è di certo dentro questo oggetto.$B$BSei $Gstato saggio:stata saggia; a portarcelo, $N. Forse, con lo studio e i rituali, potremo scoprire che cosa inquina la loro mente. Grazie, $Gamico:amica; — accetta queste offerte in cambio della tua scoperta.",
}
T[8471] = {
  title = "Winterfall Ritual Totem",
  desc = "Hai trovato uno dei totem rituali dei furbolgs Winterfall. Il totem in sé è di fattura anonima, ma sembra emanare un'angoscia e una disperazione quasi tangibili. Se davvero molti dei furbolgs Winterfall ne portano uno, questo spiegherebbe di sicuro buona parte della loro condizione attuale.$B$BA qualcuno dei furbolgs di Timbermaw Hold un oggetto del genere potrebbe servire... sempre che tu ti sia $Gguadagnato:guadagnata; abbastanza la loro fiducia da farli parlare con te.",
  obj = "Porta il Winterfall Ritual Totem all'interno di Timbermaw Hold e vedi se uno dei furbolgs che si trovano lì saprà trovare un uso per l'oggetto. I Timbermaw non parleranno con te se la tua reputazione con loro non è almeno Neutrale.",
  progress = "$C — ti avvicini a noi in pace, ma sento che ti portano qui questioni gravi e serie... tanto per un furbolg quanto per $Gun:una; $R. Che cosa sei $Gvenuto:venuta; a dirci?",
  reward = "Questa cosa... ha la forma di un Winterfall Ritual Totem, ma l'hanno distorta forze che non riesco nemmeno a comprendere. La contaminazione che ha messo i Winterfall contro di noi, qualunque sia, è di certo dentro questo oggetto.$B$BÈ stata una saggezza divina a portarci sia questo oggetto sia te, $N. Lo studieremo con attenzione: forse un giorno i Winterfall smetteranno di infuriarsi contro di noi.$B$BGrazie, $Gamico:amica; — accetta queste offerte in cambio della tua benevolenza.",
}
T[8481] = {
  title = "La Radice di Tutti i Mali",
  desc = "$N, grazie a te abbiamo trovato il modo di evocare la radice di tutti i mali della tribù Winterfall — il demone corruttore che la tiene in pugno!$B$BPorta questa torcia all'ingresso della grotta privata di High Chief Winterfall e piantala lì: il demone sarà costretto a mostrarsi e a venire a vedere cosa succede. In quel momento tu e i tuoi alleati dovrete abbatterlo! Solo l'essenza del demone caduto potrà avviare la lunga guarigione della tribù Winterfall... e salvare Timbermaw Hold.",
  obj = "Pianta la Demon Summoning Torch all'ingresso della grotta di High Chief Winterfall nel villaggio furbolg dei Winterfall. Sconfiggi il demone e recupera l'Essence of Xandivious per Gorn One Eye a Timbermaw Hold.",
  progress = "Sei $Gtornato:tornata; da noi, $N... allora il demone è stato ucciso?",
  reward = "Ci... ci hai salvati! Con la tua vittoria sul demone Xandivious Timbermaw Hold sarà al sicuro per gli anni a venire. Per la nostra gente sei $Gun vero eroe:una vera eroina;.$B$BTi prego, accetta questo con la nostra benedizione. I furbolgs guariranno lentamente — e il conflitto andrà avanti — ma oggi hai dato ai Winterfall qualcosa che non avevano mai avuto.$B$BHanno una possibilità di sopravvivere.",
}
T[8484] = {
  title = "La Negoziazione della Pace",
  desc = "Le tue gesta vanno oltre la storia di $Gun semplice eroe:una semplice eroina;, $N. Se sei $Gun rappresentante:una rappresentante; del tuo popolo, è con il tuo popolo che ci impegneremmo a fare la pace.$B$BTi prego — porta questa offerta al re dei nani che vive in una montagna di ferro; credo che voi la chiamiate Ironforge. In passato ha cercato di mettersi in contatto con noi a nome della sua Alleanza, ma ora è giusto riconoscere che la chiave degli sforzi di pace della tua Alleanza sei tu.",
  obj = "Porta la Timbermaw Offering of Peace a King Magni Bronzebeard a Ironforge.",
  progress = "$C, sei $Gil benvenuto:la benvenuta; nel mio dominio. Ironforge sarà sempre casa tua, per $Gun eroe:un'eroina; come te. Allora, che cosa ti porta da me?",
  reward = "Una svolta davvero fortunata. Se riuscissimo a stringere una pace duratura con queste creature, avremmo di sicuro un vantaggio nelle faccende di Kalimdor... un vantaggio che gli Elfi della Notte da soli non possono sostenere. Avviserò subito gli altri capi dell'Alleanza e manderemo altri diplomatici!$B$BQuanto a te, $N... hai mostrato coraggio tanto nella diplomazia quanto nell'azione. Ti ringrazio, e con me tutta l'Alleanza.",
}
T[8485] = {
  title = "La Negoziazione della Pace",
  desc = "Le tue gesta vanno oltre la storia di $Gun semplice eroe:una semplice eroina;, $N. Se sei $Gun rappresentante:una rappresentante; del tuo popolo, è con il tuo popolo che ci impegneremmo a fare la pace.$B$BTi prego — porta questa offerta al capoguerra degli orchi che vive nelle terre di Durotar; credo che voi chiamiate la sua città Orgrimmar. In passato ha cercato di mettersi in contatto con noi a nome della sua Orda, ma ora è giusto riconoscere che la chiave degli sforzi di pace della tua Orda sei tu.",
  obj = "Porta la Timbermaw Offering of Peace a Thrall a Orgrimmar.",
  progress = "Il capoguerra ti porge i suoi saluti, $C. In questi tempi difficili le tue gesta rendono più forte l'Orda. Allora, che cosa ti porta da me?",
  reward = "Una svolta davvero fortunata. Se riuscissimo a stringere una pace duratura con queste creature, avremmo di sicuro un vantaggio nel difendere Kalimdor dalle minacce esterne. Avviserò subito gli altri capi dell'Orda e manderemo altri diplomatici!$B$BQuanto a te, $N... hai mostrato coraggio tanto nella diplomazia quanto nell'azione. Ti ringrazio, e con me l'Orda intera.",
}
T[8492] = {
  title = "L'Alleanza Ha Bisogno di Copper Bars!",
  desc = "Ehi, $C, hai l'aria di chi è abbastanza in forma da contribuire allo sforzo bellico! Qui ci serve ogni aiuto possibile per mettere insieme il materiale per la Guerra di Ahn'Qiraj, e oggi è il tuo giorno fortunato.$B$BRaccolgo copper bars a pile da venti. È per una giusta causa, che ne dici? Te la senti di dare una mano all'Alleanza?",
  obj = "Porta 20 Copper Bars a Sergeant Stonebrow, in Military Ward a Ironforge.",
  progress = "Allora, soldato, ce li hai già quei venti lingotti di rame?",
  reward = "Ce l'hai fatta, $Gragazzo:ragazza;! Quei copper bars vanno subito sulla pila, e ci fabbricheremo il materiale bellico. È l'impegno di gente come te che mi rende fiero di servire l'Alleanza. Ottimo lavoro, soldato!$B$BE se ti capitano tra le mani altri copper bars, fa' in modo che arrivino a me.",
  en_title = "The Alliance Needs Copper Bars!",
  en_obj = "Bring 20 Copper Bars to Sergeant Stonebrow at the Military Ward in Ironforge.",
}
T[8493] = {
  title = "L'Alleanza Ha Bisogno di Altri Copper Bars!",
  desc = "Sei di nuovo qui, $C? Eccezionale! Per lo sforzo bellico di Ahn'Qiraj ci servono ancora altre pile di copper bars, se riesci a procurarle. Ci dai una mano?",
  obj = "Porta 20 copper bars a Sergeant Stonebrow, all'aerodromo di Dun Morogh.",
  progress = "Sei di nuovo qui, $C? Eccezionale! Con i lingotti che hai portato finora fabbricheremo ogni genere di cosa per la guerra. Per esempio, so che il rame finirà in alcune parti degli steam tanks che stiamo costruendo, e anche in una piccola flotta di girocotteri che contiamo di schierare, se ci sarà tempo.$B$BMa non lasciarti ingannare dalle pile che vedi qui: per lo sforzo bellico di Ahn'Qiraj ci servono ancora altri copper bars, se riesci a procurarli. Ci dai una mano?",
  reward = "Ottimo lavoro! Andare in giro a scavare quel rame e poi fonderlo dev'essere stata una bella avventura. Sempre che tu non l'abbia comprato alla casa d'aste. Comunque sia, a me sta bene. Per il tuo contributo allo sforzo bellico ti meriti un encomio, $C. E se hai altri copper bars, portameli senza esitare.",
  en_title = "The Alliance Needs More Copper Bars!",
  en_obj = "Bring 20 copper bars to Sergeant Stonebrow at the airfield in Dun Morogh.",
}
T[8494] = {
  title = "L'Alleanza Ha Bisogno di Iron Bars!",
  desc = "Ma guarda un po' chi si vede, $GSignor Elegantone:Signora Elegantona;, che piacere. Se per caso non l'hai sentito mentre eri là fuori ad \"avventurarti\", l'Alleanza si prepara a una guerra ad Ahn'Qiraj e ha bisogno di iron bars... un sacco di lingotti. Portameli a pile da venti. Possiamo contare su di te, vero, $C?",
  obj = "Porta 20 Iron Bars a Corporal Carnes, in Military Ward a Ironforge.",
  progress = "Se hai quei venti lingotti di ferro, dove li hai nascosti non lo voglio sapere!",
  reward = "Bene, bene, ma guarda chi c'è: $N. E ce l'hai fatta. Immagino che adesso mi toccherà tenerti d'occhio. Mi costa dirlo, ma grazie dell'impegno. L'Alleanza non se ne scorderà, e io nemmeno. Ora torna là fuori e spaccati la schiena per qualunque altra cosa ci sia da raccogliere.",
  en_title = "The Alliance Needs Iron Bars!",
  en_obj = "Bring 20 Iron Bars to Corporal Carnes at the Military Ward in Ironforge.",
}
T[8495] = {
  title = "L'Alleanza Ha Bisogno di Altri Iron Bars!",
  desc = "Già di ritorno? Smettila di costringermi a rivedere la poca stima che ho di te, $C, che mi fai sciogliere tutto dentro. Allora, come vedi gli iron bars non bastano ancora per tutte le armi, le armature, gli steam tanks e compagnia bella da costruire per la caccia agli insetti. Ce la fai a portarmi un'altra pila di venti iron bars tra un viaggio e l'altro a Zul'Gurub, o dovunque vi ritroviate voi ragazzini di oggi?",
  obj = "Porta 20 iron bars a Corporal Carnes, all'aerodromo di Dun Morogh.",
  progress = "Già di ritorno? Smettila di costringermi a rivedere la poca stima che ho di te, $C, che mi fai sciogliere tutto dentro. Allora, come vedi gli iron bars non bastano ancora per tutte le armi, le armature, gli steam tanks e compagnia bella da costruire per la caccia agli insetti. Ce la fai a portarmi un'altra pila di venti iron bars tra un viaggio e l'altro a Zul'Gurub, o dovunque vi ritroviate voi ragazzini di oggi?",
  reward = "Oggi nelle Burning Steppes dev'esserci freddo. Guarda un po': c'è $N, e mi ha portato un regalo. Venti iron bars! Proprio quello che ho sempre desiderato.$B$BMa scherzi a parte, grazie, $N. Fai onore a te $Gstesso:stessa; e all'Alleanza. Adesso torna là fuori e porta altra roba per lo sforzo bellico!",
  en_title = "The Alliance Needs More Iron Bars!",
  en_obj = "Bring 20 iron bars to Corporal Carnes at the airfield in Dun Morogh.",
}
T[8496] = {
  title = "Bende per il Fronte",
  desc = "Dopo le ultime perdite, sul campo di battaglia le bende scarseggiano pericolosamente. Procurati una partita di materiale di primo soccorso e consegnala a Windcaller Proudhorn a Cenarion Hold.",
  obj = "Porta 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages e 30 Heavy Mageweave Bandages a Windcaller Proudhorn a Cenarion Hold, in Silithus. Per completare questa missione devi portare anche le Logistics Task Briefing X.",
}
T[8497] = {
  title = "Kit di Sopravvivenza nel Deserto",
  desc = "Ora che a Cenarion Hold arrivano nuove reclute, c'è il problema di tenerle in vita nel deserto. Fra la disidratazione e le tante creature velenose, i volontari inesperti corrono un serio pericolo. Raccogli le provviste che servono per un kit di sopravvivenza nel deserto e portale a Calandrath, a Cenarion Hold.",
  obj = "Porta 4 Globes of Water, 4 Powerful Anti-Venom e 4 Smoked Desert Dumplings a Calandrath, alla locanda di Cenarion Hold, in Silithus. Per completare questa missione devi portare anche le Logistics Task Briefing I.",
}
T[8498] = {
  title = "Twilight Battle Orders",
  desc = "Secondo i nostri esploratori, i capi del Twilight's Hammer stanno diramando nuovi ordini di battaglia, che i Twilight Prophets distribuiscono sotto stretta scorta. Intercetta gli ordini e portali a Commander Mar'alith.",
  obj = "Ottieni i Twilight Battle Orders e portali a Commander Mar'alith a Cenarion Hold, in Silithus. Per completare questa missione devi portare anche le Tactical Task Briefing X.",
  progress = "Hai qualcosa per me?",
  reward = "Eccellente. Bisogna stare un passo avanti al nemico. Con queste informazioni potremo prevedere gli attacchi del Twilight's Hammer.",
}
T[8499] = {
  title = "L'Alleanza Ha Bisogno di Thorium Bars!",
  desc = "Sei proprio gentile a chiedere di cosa ha bisogno l'Alleanza. Abbiamo un sacco di raccolte in corso, e io mi occupo di questa: ci serve una gran quantità di thorium bars. Con il torio costruiremo tante cose diverse per la guerra, e prima di tutto un battaglione di steam tanks, che appena saranno pronti verranno trasportati in volo a Silithus. Ci puoi aiutare in quest'impresa, $C?",
  obj = "Porta 20 Thorium Bars a Dame Twinbraid in Military Ward di Ironforge.",
  progress = "Oh, mio fratello mi manda una spedizione? Splendido! Oggi la fortuna mi sorride!",
  reward = "Quindi Gnoarn non si fida di me quando si tratta di ricognizioni? Chissà perché...",
  en_title = "The Alliance Needs Thorium Bars!",
  en_obj = "Bring 20 Thorium Bars to Dame Twinbraid at the Military Ward in Ironforge.",
}
T[8500] = {
  title = "L'Alleanza Ha Bisogno di Altri Thorium Bars!",
  desc = "Che bello rivederti, $N. Spero che te la passi bene. Sì, ci servono ancora thorium bars. Se te ne avanzano, li raccolgo io per lo sforzo bellico di Ahn'Qiraj.",
  obj = "Porta 20 thorium bars a Dame Twinbraid all'aerodromo di Dun Morogh.",
  progress = "Che bello rivederti, $N. Spero che te la passi bene. Sì, ci servono ancora thorium bars. Se te ne avanzano, li raccolgo io per lo sforzo bellico di Ahn'Qiraj.",
  reward = "Eccellente, $C! Bel lavoro. Ci penso io a mettere questi lingotti sul bancale e a farli arrivare ai fabbri e agli ingegneri che lavorano sodo per mettere insieme le scorte del nostro esercito. Grazie ancora, e se ti capitano altri thorium bars, passa pure da me.",
  en_title = "The Alliance Needs More Thorium Bars!",
  en_obj = "Bring 20 thorium bars to Dame Twinbraid at the airfield in Dun Morogh.",
}
T[8501] = {
  title = "Obiettivo: Hive'Ashi Stingers",
  desc = "Ora che lo sforzo bellico si fa più intenso, i silithid della zona minacciano sempre di più le nostre operazioni. Sei $Gstato scelto:stata scelta; per partecipare a un assalto a Hive'Ashi, e il tuo obiettivo principale saranno i pungitori volanti di Hive'Ashi.$B$BA compito finito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Ashi Stingers e torna da Commander Mar'alith a Cenarion Hold, in Silithus. Devi anche portare le Combat Task Briefing XII per completare questa quest.",
  progress = "Hai qualcosa da dirmi, $N?",
  reward = "Ottimo lavoro, $N. Prendo nota del tuo contributo all'attacco a Hive'Ashi.",
}
T[8502] = {
  title = "Obiettivo: Hive'Ashi Workers",
  desc = "Ora che lo sforzo bellico si fa più intenso, i silithid della zona minacciano sempre di più le nostre operazioni. Sei $Gstato scelto:stata scelta; per partecipare a un assalto a Hive'Ashi, e il tuo obiettivo principale saranno le operaie di Hive'Ashi.$B$BA compito finito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Ashi Workers e torna da Commander Mar'alith a Cenarion Hold, in Silithus. Devi anche portare le Combat Task Briefing III per completare questa quest.",
  progress = "Hai qualcosa da dirmi, $C?",
  reward = "Ottimo lavoro, $N. Senza le operaie, per i silithid sarà dura riparare qualunque danno inflitto alla struttura dell'alveare.",
}
T[8503] = {
  title = "L'Alleanza Ha Bisogno di Stranglekelp!",
  desc = "Allora, $C, ti ho già raccontato di tutti i favolosi usi dello stranglekelp? Sì? Oh, beh... comunque ce ne serve tanto, e quando dico tanto voglio dire TANTISSIMO! Ci daresti una mano? Lo so che vuol dire rinunciare a tutte le cose meravigliose che ci puoi fare, ma è per una buona causa!",
  obj = "Porta 20 Stranglekelp a Private Draxlegauge in Military Ward di Ironforge.",
  progress = "Non è vero! Non mi sognerei mai di fare la cresta sullo stranglekelp di queste pile. Anche se la tentazione ci sarebbe, visto che è utile per così tante cose da essere quasi una panacea. *coff* Non è che per caso hai quello stranglekelp di cui parlavamo prima?",
  reward = "Evviva! Altri venti a posto. Sei $Gil migliore:la migliore;. Meglio che impacchetti tutto prima che appassisca. Tanto stranglekelp e così poco tempo!$B$BGrazie ancora, $C!",
  en_title = "The Alliance Needs Stranglekelp!",
  en_obj = "Bring 20 Stranglekelp to Private Draxlegauge at the Military Ward in Ironforge.",
}
T[8504] = {
  title = "L'Alleanza Ha Bisogno di Altro Stranglekelp!",
  desc = "Beh, ciao di nuovo... com'è che ti chiamavi? Ah sì, $N! Sei $Gvenuto:venuta; a vedere se mi serve altro stranglekelp, eh? Oggi è il tuo giorno fortunato, perché a questa importantissima domanda rispondo con un convintissimo SÌ! Ce la fai a raccoglierne altri venti?",
  obj = "Porta 20 stranglekelp a Private Draxlegauge all'aerodromo di Dun Morogh.",
  progress = "Beh, ciao di nuovo... com'è che ti chiamavi? Ah sì, $N! Sei $Gvenuto:venuta; a vedere se mi serve altro stranglekelp, eh? Oggi è il tuo giorno fortunato, perché a questa importantissima domanda rispondo con un convintissimo SÌ! Ce la fai a raccoglierne altri venti?",
  reward = "Oh, santo cielo, è proprio un bel carico di stranglekelp. Presto, mettiamolo in una cassa, così resta fresco. Portandolo qui hai fatto un grande favore a me... a noi, all'Alleanza. Farò sapere a tutti che sei $Gstato:stata; tu, $Gil grande:la grande; $N, ad aiutare a far pendere la bilancia nello sforzo bellico di Ahn'Qiraj, con il tuo contributo di stranglekelp!",
  en_title = "The Alliance Needs More Stranglekelp!",
  en_obj = "Bring 20 stranglekelp to Private Draxlegauge at the airfield in Dun Morogh.",
}
T[8505] = {
  title = "L'Alleanza Ha Bisogno di Purple Lotus!",
  desc = "$C, il purple lotus si presta a tantissimi usi. Li conosco bene, ed è per questo che l'Alleanza mi ha chiesto di venire qui: devo conservare le erbe raccolte e fare in modo che in guerra abbia purple lotus a sufficienza per qualunque uso voglia farne.$B$BVorrei che viaggiassi per il mondo e mi riportassi un po' di questi fiori. Puoi farlo?",
  obj = "Porta 20 Purple Lotus a Master Nightsong in Military Ward a Ironforge.",
  progress = "Hai con te le erbe di purple lotus che ti ho chiesto?",
  reward = "Il tuo contributo ci è molto prezioso, $C. Solo con lo sforzo di tutti insieme riusciremo a respingere la spietata avanzata dei silithid e di qualunque forza li stia spingendo avanti. Persino l'Orda sta mettendo da parte la sua scorta di purple lotus. Se ne trovi altro, ti prego, torna da me.",
  en_title = "The Alliance Needs Purple Lotus!",
  en_obj = "Bring 20 Purple Lotus to Master Nightsong at the Military Ward in Ironforge.",
}
T[8506] = {
  title = "L'Alleanza Ha Bisogno di Altro Purple Lotus!",
  desc = "$GBentornato:Bentornata;, $C. La nostra raccolta cresce, ma ci serve altro purple lotus. Se riesci a raccoglierne ancora, ti supplico di farlo e di riportarmelo qui.",
  obj = "Porta 20 purple lotus a Master Nightsong all'aerodromo di Dun Morogh.",
  progress = "$GBentornato:Bentornata;, $C. La nostra raccolta cresce, ma ci serve altro purple lotus. Se riesci a raccoglierne ancora, ti supplico di farlo e di riportarmelo qui.",
  reward = "A nome dell'Alleanza accetto volentieri il tuo contributo, $N. Il tuo impegno servirà direttamente a preparare diverse pozioni e oli che sosterranno i nostri uomini e le nostre donne sul campo. Grazie. E se ne trovassi altro, ti prego, pensa a tornare da me.",
  en_title = "The Alliance Needs More Purple Lotus!",
  en_obj = "Bring 20 purple lotus to Master Nightsong at the airfield in Dun Morogh.",
}
T[8507] = {
  title = "Servizio sul Campo",
  desc = "Saluti, $N. Prima che io possa affidarti compiti più impegnativi in questa guerra, dovrai fare la tua parte di servizio sul campo.$B$BFuori da Hive'Zora troverai l'Ironforge Brigade di Captain Blackanvil.$B$BPresentati a rapporto da lui o dalla sua luogotenente, Janela Stouthammer, e poi torna da me: avrò pronto per te un incarico più avanzato.$B$BAh, e facci il favore di stare alla larga dall'Orgrimmar Legion. Fra le due forze c'è tanta ostilità che siamo stati costretti a tenerle ben separate.",
  obj = "Presentati in servizio all'avamposto di Ironforge Brigade vicino a Hive'Zora. Prepara gli Unsigned Field Duty Papers, ottieni i Signed Field Duty Papers da Captain Blackanvil e torna da Windcaller Kaldon a Cenarion Hold, in Silithus.$B$BNota: curare o lanciare incantesimi benefici su un membro di Ironforge Brigade attiverà il PvP su di te.",
  progress = "Le forze di Captain Blackanvil le troverai di stanza fuori da Hive'Zora. Se non riesci a trovarlo, parla con la sua luogotenente, Janela Stouthammer.",
  reward = "Molto bene, $N. Ho preparato per te una serie di compiti che dovrebbero mettere a frutto al meglio le tue capacità.$B$BGrazie ai continui sforzi tuoi e di chi è come te, il nostro nemico sarà presto sconfitto una volta per tutte!$B$BSe ti servissero nuove istruzioni per una missione, torna da Captain Blackanvil.",
}
T[8508] = {
  title = "Documenti di Servizio sul Campo",
  progress = "Vuoi far firmare quei documenti, immagino, $Gragazzo:ragazza;?",
  reward = "Sì, di questi tempi quella scaramuccia passerà per servizio sul campo, suppongo. Riportali a Cenarion Hold: di sicuro avranno un lavoro comodo pronto per te.$B$BForza, vai!",
}
T[8509] = {
  title = "L'Alleanza Ha Bisogno di Arthas' Tears!",
  desc = "Sarò semplice e diretta, $C. Per la guerra di Ahn'Qiraj l'Alleanza deve mettere insieme una grande quantità di Arthas' Tears. Non chiedermi a cosa servano: io eseguo gli ordini e basta. Però vorrei che ne raccogliessi quante più puoi e me le riportassi qui. Sei $Gdisposto:disposta; a farlo?",
  obj = "Porta 20 Arthas' Tears a Sergeant Major Germaine in Military Ward a Ironforge.",
  progress = "Come? Parla più forte, $C! Ce l'hai quel carico di Arthas' Tears che ti ho chiesto?",
  reward = "Ottimo lavoro, $C. Devo dire che sono piacevolmente sorpresa. Non crederesti quanta gente è passata di qui a offrirsi di aiutare e poi non è mai tornata. Lascia che le metta in una cassa e le registri a tuo nome; poi ne riparliamo per capire se me ne servono altre.",
  en_title = "The Alliance Needs Arthas' Tears!",
  en_obj = "Bring 20 Arthas' Tears to Sergeant Major Germaine at the Military Ward in Ironforge.",
}
T[8510] = {
  title = "L'Alleanza Ha Bisogno di Altre Arthas' Tears!",
  desc = "Ok, pare che mi servano ancora altre Arthas' Tears. Immagino che le troverai più o meno dove le hai raccolte per me l'ultima volta. Prima le abbiamo, prima potremo lanciare l'offensiva contro le forze di Ahn'Qiraj.$B$BCi dai di nuovo una mano, $C?",
  obj = "Porta 20 arthas' tears a Sergeant Major Germaine all'aerodromo di Dun Morogh.",
  progress = "Ok, pare che mi servano ancora altre Arthas' Tears, $C. Immagino che le troverai più o meno dove le hai raccolte l'ultima volta. I preparativi per la guerra procedono bene, ma prima le abbiamo, prima potremo lanciare l'offensiva contro le forze di Ahn'Qiraj.$B$BCi dai di nuovo una mano, $N?",
  reward = "Semplicemente eccezionale, $N! Fai davvero onore all'Alleanza. Penserò io a mettere via queste erbe finché qualcuno non verrà a trasformarle in qualcosa di utile per la guerra. Torna pure quando vuoi, soprattutto se hai altre Arthas' Tears per me.",
  en_title = "The Alliance Needs More Arthas' Tears!",
  en_obj = "Bring 20 Arthas' Tears to Sergeant Major Germaine at the airfield in Dun Morogh.",
}
T[8511] = {
  title = "L'Alleanza Ha Bisogno di Light Leather!",
  desc = "Noi Stoneflayer siamo scuoiatori da generazioni, $C, ed è per questo che l'Alleanza ha chiesto alla mia famiglia di dare una mano a raccogliere il light leather per lo sforzo bellico di Ahn'Qiraj. Io sono qui per controllare che il cuoio venga conciato come si deve, qualunque cosa vogliano farne. Ma ci serve il tuo aiuto.$B$BIo devo restare qui a occuparmene, quindi ho bisogno che sia tu ad andare a raccogliere le pelli e a riportarmele. Che ne dici, $Gragazzo:ragazza;, ci provi?",
  obj = "Porta 10 pezzi di Light Leather a Bonnie Stoneflayer, in Military Ward, a Ironforge.",
  progress = "Spero proprio che quello sia il light leather che mi hai promesso, $C.",
  reward = "Secondo me l'Alleanza sarà molto contenta delle tue pelli, $C, e io farò in modo che non ne vada sprecata nemmeno una. Grazie, e quando le avrò contate ricordati di ripassare da me, così vediamo se ce ne servono altre.",
  en_title = "The Alliance Needs Light Leather!",
  en_obj = "Bring 10 Light Leather to Bonnie Stoneflayer at the Military Ward in Ironforge.",
}
T[8512] = {
  title = "L'Alleanza Ha Bisogno di Altro Light Leather!",
  desc = "Che piacere rivederti, $N. Pare che ci serva altro light leather per preparare i vari materiali da guerra: se riuscissi a portarmene una pila da dieci, sarebbe perfetto.",
  obj = "Porta 10 pezzi di light leather a Bonnie Stoneflayer, all'aerodromo di Dun Morogh.",
  progress = "Che piacere rivederti, $N. Pare che ci serva altro light leather per preparare i vari materiali da guerra: se mi portassi una pila da dieci, sarebbe perfetto.",
  reward = "Grazie della generosa donazione, $N. Li metto subito sulla pila, e sono sicura che in un attimo diventeranno una bella armatura o qualche toppa di cuoio, oppure serviranno per qualcos'altro nei nostri preparativi. Pare che di light leather ce ne serva sempre altro. Torna presto a trovarmi.",
  en_title = "The Alliance Needs Light Leather!",
  en_obj = "Bring 10 light leather to Bonnie Stoneflayer at the airfield in Dun Morogh.",
}
T[8513] = {
  title = "L'Alleanza Ha Bisogno di Medium Leather!",
  desc = "Sì, $Gsignore:signora;, mi hanno affidato il compito di raccogliere e registrare tutto il medium leather per lo sforzo bellico. Se hai modo di procurarti del medium leather, da qualunque parte venga, ti prego di portarmelo qui. Se puoi dedicarmi un po' di tempo, ti sarei davvero grato dell'aiuto.",
  obj = "Porta 10 pezzi di Medium Leather a Private Porter, in Military Ward, a Ironforge.",
  progress = "Sì, $Gsignore:signora;, mi ricordo di te. Quello che hai con te è il medium leather?",
  reward = "Wow! Mi pare che fossi qui giusto un attimo fa a offrirti $Gvolontario:volontaria;. Grazie mille della donazione: adesso lo impacchetto e lo conto tutto. Tu sì che sai come rallegrare la giornata a uno.",
  en_title = "The Alliance Needs Medium Leather!",
  en_obj = "Bring 10 Medium Leather to Private Porter at the Military Ward in Ironforge.",
}
T[8514] = {
  title = "L'Alleanza Ha Bisogno di Altro Medium Leather!",
  desc = "Sì, $Gsignore:signora;, pare che finora abbiamo messo insieme un bel po' di pezzi di medium leather. So che è chiedere tanto, ma se sei ancora $Gdisposto:disposta;, il tuo aiuto mi farebbe comodo per provare a ridurre quel che resta della mia quota.",
  obj = "Porta 10 pezzi di medium leather a Private Porter, all'aerodromo di Dun Morogh.",
  progress = "Sì, $Gsignore:signora;, pare che abbiamo raccolto molti pezzi di medium leather, ma ce ne serve ancora. Ti assicuro che verrà usato tutto bene: non se ne sprecherà nemmeno un pezzo. So che è chiedere tanto, ma se sei ancora $Gdisposto:disposta;, il tuo aiuto mi farebbe comodo per provare a ridurre quel che resta della mia quota.",
  reward = "Perbacco, $Gsignore:signora;, è proprio un sacco di medium leather quello che hai portato! Farò in modo che venga usato tutto come si deve, proprio così. Con il tuo aiuto arriveremo in un attimo alla quantità di medium leather prevista!$B$BGrazie, $N!",
  en_title = "The Alliance Needs More Medium Leather!",
  en_obj = "Bring 10 medium leather to Private Porter at the airfield in Dun Morogh.",
}
T[8515] = {
  title = "L'Alleanza Ha Bisogno di Thick Leather!",
  desc = "Oh, mamma mia, sarà fantastico! $C, i preparativi per la guerra ad Ahn'Qiraj vanno a pieno ritmo, e a me tocca tenere il conto di tutto il thick leather che arriva. Ci faremo tonnellate di cose, ma prima dobbiamo procurarcene una tonnellata. Alla lettera, eh! Ed è qui che entri in gioco tu.$B$BAllora, te la senti di andare là fuori e riportarmi una bella pila alta di thick leather? Eh, ce la fai, ce la fai?!",
  obj = "Porta 10 pezzi di Thick Leather a Marta Finespindle, in Military Ward a Ironforge.",
  progress = "Quello che hai nello zaino è thick leather, $C? Sì? Non vedo l'ora che tu me lo dia! Saranno tutti così contenti di noi, non credi?",
  reward = "Oh, lo sapevo che ce l'avresti fatta, $C, lo sapevo! Lo farò arrivare nelle mani giuste il prima possibile. Ora, vediamo un po'. Mmm, pare che il conteggio vada piuttosto bene. Ripassa tra un attimo, quando avrò finito di contare, così vediamo se ne serve ancora. Perché se serve, sei tu $Gquello:quella; che voglio là fuori a raccoglierlo per me!",
  en_title = "The Alliance Needs Thick Leather!",
  en_obj = "Bring 10 Thick Leather to Marta Finespindle at the Military Ward in Ironforge.",
}
T[8516] = {
  title = "L'Alleanza Ha Bisogno di Altro Thick Leather!",
  desc = "Già, la pila non è ancora abbastanza alta. $N, al nostro obiettivo di thick leather non ci siamo ancora. Pensa a quante cose ci possiamo fare, con tutto quel cuoio! Armature e armi di ogni genere. Roba per l'interno degli steam tanks e mirini per fucili! Occhiali da ingegneria, e scommetto che se alla fine ne raccogliamo troppo il resto potremmo darlo all'Orda per i suoi zeppelin!$B$BAllora, me ne porti dell'altro, di thick leather?",
  obj = "Porta 10 pezzi di thick leather a Marta Finespindle, al campo d'aviazione di Dun Morogh.",
  progress = "Già, la pila non è ancora abbastanza alta. $N, al nostro obiettivo di thick leather non ci siamo ancora. Pensa a quante cose ci possiamo fare, con tutto quel cuoio! Armature e armi di ogni genere. Roba per l'interno degli steam tanks e mirini per fucili! E occhiali da ingegneria, che sono sempre divertenti!$B$BAllora, me ne porti dell'altro, di thick leather?",
  reward = "Ce l'hai fatta di nuovo! È semplicemente incredibile come vai là fuori, raccogli tutta questa roba e poi me la riporti qui. Te lo dico io, quando sapranno quanto hai dato una mano da queste parti, non potrai fare due passi per strada senza che la gente ti chieda l'autografo!$B$BGrazie ancora della tua generosissima donazione di thick leather, $N.",
  en_title = "The Alliance Needs More Thick Leather!",
  en_obj = "Bring 10 thick leather to Marta Finespindle at the airfield in Dun Morogh.",
}
T[8517] = {
  title = "L'Alleanza Ha Bisogno di Linen Bandages!",
  desc = "La guerra ad Ahn'Qiraj sarà lunga e sanguinosa. È molto saggio che l'Alleanza chieda aiuto a te e a quelli come te per accumulare il materiale necessario, prima di gettarsi a capofitto nel conflitto.$B$BMi hanno chiesto di dirigere la raccolta di linen bandages per la guerra, e spero che mi aiuterai a radunarne quante ne servono. Non è cosa da poco, ma almeno le linen bandages sono le più facili da fare. Sei con noi, $C?",
  obj = "Porta 20 Linen Bandages a Sentinel Silversky, in Military Ward a Ironforge.",
  progress = "Mi hai portato le venti linen bandages che mi servono, $C?",
  reward = "Molti sono i soldati che trarranno beneficio da quanto hai dato qui oggi, $C. Mi assicurerò di persona che l'Alleanza sappia dei tuoi sforzi. Concedimi un momento per riporre come si deve queste bende e aggiornare il conteggio, poi torna da me per vedere se me ne servono altre.$B$BChe la Light of Elune splenda su di te, $R!",
  en_title = "The Alliance Needs Linen Bandages!",
  en_obj = "Bring 20 Linen Bandages to Sentinel Silversky at the Military Ward in Ironforge.",
}
T[8518] = {
  title = "L'Alleanza Ha Bisogno di Altre Linen Bandages!",
  desc = "Sempre mi stupisce l'altruismo che si vede là dove tanti sceglierebbero l'egoismo. $C, prima che il mio incarico qui sia compiuto mi serve ancora un certo numero di linen bandages. Mi aiuterai ancora una volta a raccogliere quelle bende?",
  obj = "Porta 20 linen bandages a Sentinel Silversky, al campo d'aviazione di Dun Morogh.",
  progress = "Sempre mi stupisce l'altruismo che si vede là dove tanti sceglierebbero l'egoismo. $C, prima che il mio incarico qui sia compiuto mi serve ancora un certo numero di linen bandages. Mi aiuterai ancora una volta a raccogliere quelle bende?",
  reward = "Meriti un elogio, $N. Mentre c'è chi approfitterebbe dell'economia di guerra per riempirsi le tasche, in preda all'avidità, tu hai dimostrato più e più volte che la devozione all'Alleanza, e anzi a tutta Azeroth, per te viene prima di ogni cosa.$B$BChe le benedizioni di Elune siano sempre con te!",
  en_title = "The Alliance Needs More Linen Bandages!",
  en_obj = "Bring 20 linen bandages to Sentinel Silversky at the airfield in Dun Morogh.",
}
T[8519] = {
  title = "Una Pedina sulla Scacchiera Eterna",
  desc = "Ritrovi la calma, concentri lo sguardo e ti accorgi che dentro il cristallo qualcosa si muove. Osservi più da vicino e capisci che stai scrutando nel passato... un ricordo... dimenticato da tempo.",
  obj = "Scopri tutto ciò che puoi sul passato, poi parla con Anachronos alle Caverns of Time a Tanaris.",
  reward = "Dopo il tradimento di Staghelm ho raccolto i frammenti dello Scepter of the Shifting Sands e sono tornato qui, deciso a difendere lo scettro da chiunque volesse servirsene per fare del male al nostro mondo — così è nato il compito degli Stormi dei Draghi.$B$BDiviso fra i quattro potenti Aspetti, lo scettro sarebbe stato quasi impossibile da ricomporre per chi cercasse di proposito il caos... o almeno così credevo. Che sciocco sono stato. Quello stormo maledetto mi dà la caccia ancora oggi.",
}
T[8520] = {
  title = "L'Alleanza Ha Bisogno di Silk Bandages!",
  desc = "La guerra di Ahn'Qiraj è alle porte, e dobbiamo fare tutto il possibile perché ai nostri soldati non manchi niente: qui ci occupiamo proprio di questo. A me hanno affidato il compito di fare in modo che si raccolgano abbastanza silk bandages.$B$BPensi di potermi dare una mano, $C?",
  obj = "Porta 20 Silk Bandages a Nurse Stonefield, in Military Ward a Ironforge.",
  progress = "Ciao, $C, sei $Griuscito:riuscita; a procurarti quelle venti silk bandages?",
  reward = "Ce l'hai fatta, $C! Grazie a te abbiamo fatto un altro passo verso il nostro obiettivo per le silk bandages. Adesso le metto via; poi, se vuoi, possiamo parlare ancora.",
  en_title = "The Alliance Needs Silk Bandages!",
  en_obj = "Bring 20 Silk Bandages to Nurse Stonefield at the Military Ward in Ironforge.",
}
T[8521] = {
  title = "L'Alleanza Ha Bisogno di Altre Silk Bandages!",
  desc = "Sei molto gentile a offrirti di nuovo di aiutarmi, $C. A quanto pare abbiamo già raccolto un po' di silk bandages, ma ce ne serviranno altre.",
  obj = "Porta 20 silk bandages a Nurse Stonefield, all'aerodromo di Dun Morogh.",
  progress = "Sei molto gentile a offrirti di nuovo di aiutarmi, $C. A quanto pare abbiamo raccolto un bel numero delle silk bandages che ci hanno chiesto, ma ce ne servono ancora. $N, potresti metterne insieme un altro pacco e riportarmele qui? L'Alleanza e io te ne saremo molto riconoscenti.",
  reward = "Sei davvero una persona generosa. Grazie mille per quello che hai dato alla guerra: sono quelli come te che faranno la differenza fra la vittoria e la sconfitta ad Ahn'Qiraj. Spero solo che tutto questo basti.$B$BGrazie ancora, $N.",
  en_title = "The Alliance Needs More Silk Bandages!",
  en_obj = "Bring 20 silk bandages to Nurse Stonefield at the airfield in Dun Morogh.",
}
T[8522] = {
  title = "L'Alleanza Ha Bisogno di Runecloth Bandages!",
  desc = "Discuti pure quanto vuoi delle ragioni della guerra, $C: ormai è cominciata. Guarda la famiglia e gli amici che hai intorno, e chiediti cosa puoi fare perché, se saranno coinvolti, abbiano ogni possibilità di sopravvivere all'incendio.$B$BÈ per questo che raccolgo qui bende di runecloth, da qualunque parte arrivino. Vorresti fare una donazione?",
  obj = "Porta 20 Runecloth Bandages a Keeper Moonshade, in Military Ward a Ironforge.",
  progress = "I giorni passano, uno dopo l'altro, e noi andiamo avanti. Hai con te quelle bende di runecloth, $C?",
  reward = "La tua costanza in questo compito merita un elogio, $C. Ora metterò via queste bende; poi vorrei riparlare con te della possibilità che tu ne raccolga altre di runecloth.",
  en_title = "The Alliance Needs Runecloth Bandages!",
  en_obj = "Bring 20 Runecloth Bandages to Keeper Moonshade at the Military Ward in Ironforge.",
}
T[8523] = {
  title = "L'Alleanza Ha Bisogno di Altre Runecloth Bandages!",
  desc = "Ed eccoci di nuovo a discutere di questioni urgenti, $C. Ti ringrazio ancora per quanto hai fatto finora: non tutti darebbero con tanta generosità. Ma c'è dell'altro lavoro da fare.$B$B$N, raccoglierai un'altra volta delle bende di runecloth e me le riporterai qui?",
  obj = "Porta 20 bende di runecloth a Keeper Moonshade, all'aerodromo di Dun Morogh.",
  progress = "Ed eccoci di nuovo a discutere di questioni urgenti, $C. Ti ringrazio ancora per quanto hai fatto finora: non tutti darebbero con tanta generosità. Ma c'è dell'altro lavoro da fare.$B$B$N, raccoglierai un'altra volta delle bende di runecloth e me le riporterai qui?",
  reward = "Percorriamo insieme una bella strada, $N. Sei $Gun ottimo compagno:un'ottima compagna; di lavoro. Ancora una volta ti rendo grazie per i tuoi sforzi a favore di tutta l'Alleanza. Torna presto a parlarmi.",
  en_title = "The Alliance Needs More Runecloth Bandages!",
  en_obj = "Bring 20 runecloth bandages to Keeper Moonshade at the airfield in Dun Morogh.",
}
T[8524] = {
  title = "L'Alleanza Ha Bisogno di Rainbow Fin Albacore!",
  desc = "Ehi, $Gamico:amica;! Se ti chiedessi: 'Non pensi che anche i soldati debbano avere da mangiare come tutti gli altri?', di sicuro mi risponderesti: 'sì'. E io sono d'accordo con te al 110%! Che bello pensarla allo stesso modo. Ti basta andare là fuori, pescare un bel po' di raw rainbow fin albacore, cucinarla tutta e riportarmela qui. Mmm, mmm, ne sento già il sapore.",
  obj = "Porta 20 Rainbow Fin Albacore a Slicky Gastronome a Military Ward di Ironforge.",
  progress = "Sei $Gtornato:tornata; con tutta quella rainbow fin albacore di cui parlavamo prima, scommetto. Vero, $C?",
  reward = "Due per l'Alleanza, uno per me, due per l'Alleanza, uno per me. Ehi, $Gpescivendolo:pescivendola;, gran bel lavoro. Si vede che farai davvero onore al club. Però mi sa che di alborella ce ne serve ancora. Perché non vai là fuori a racimolarne un altro po'? Ho già lo stomaco che brontola.",
  en_title = "The Alliance Needs Rainbow Fin Albacore!",
  en_obj = "Bring 20 Rainbow Fin Albacore to Slicky Gastronome at the Military Ward in Ironforge.",
}
T[8525] = {
  title = "L'Alleanza Ha Bisogno di Altra Rainbow Fin Albacore!",
  desc = "Ma come! Ancora tu? Beh, che io sia lo zio di una scimmia... solo che sono uno gnomo. Slicky Gastronome, per la precisione! Allora sei $Gtornato:tornata; a dare una mano, eh? E come darti torto? Non lo adori anche tu, l'odore di tutto quel cibo? <sbava>$B$BBasta perdere tempo! Va' là fuori e riportami altra rainbow fin albacore!",
  obj = "Porta 20 rainbow fin albacore a Slicky Gastronome all'aeroporto di Dun Morogh.",
  progress = "Ma come! Ancora tu? Beh, che io sia lo zio di una scimmia... solo che sono uno gnomo. Slicky Gastronome, per la precisione! Allora sei $Gtornato:tornata; a dare una mano, eh? E come darti torto? Non lo adori anche tu, l'odore di tutto quel cibo? <sbava>$B$BBasta perdere tempo! Va' là fuori e riportami altra rainbow fin albacore!",
  reward = "Lo sapevo che avevi la stoffa, $Gragazzo:ragazza;. Hai l'aria di chi sa cosa $Ggli:le; piace. Per la precisione: ti piace far contenti me e i pezzi grossi. E ci sei $Griuscito:riuscita;, te lo garantisco.$B$BAhah, va bene: metto via per bene questi pesci, e poi io e te ci facciamo una chiacchieratina su altre venti alborelle da raccogliere.",
  en_title = "The Alliance Needs More Rainbow Fin Albacore!",
  en_obj = "Bring 20 rainbow fin albacore to Slicky Gastronome at the airfield in Dun Morogh.",
}
T[8526] = {
  title = "L'Alleanza Ha Bisogno di Roast Raptor!",
  desc = "Oh, come va, $C? Vedo che forse ti interessa raccogliere cibo per la guerra che sta per scoppiare ad Ahn'Qiraj? Chissà perché, mio padre pensava che fare la volontaria qui sarebbe stata un'esperienza istruttiva. Grosso errore. A me la carne non piace nemmeno mangiarla.$B$BComunque, se ti va, potresti riportarmi un sacco di roast raptor. Pare che sia quello che vorranno tutti i soldati.",
  obj = "Porta 20 Roast Raptor a Sarah Sadwhistle a Military Ward di Ironforge.",
  progress = "Allora, ce l'hai già tutto quel roast raptor?",
  reward = "Caspita, che bello. Grazie di avermi portato tutta questa carne animale bruciata, $C. La metto su quel mucchio laggiù: sono sicura che qualcuno se ne occuperà. Se hai un po' di tempo libero, immagino che vorrai portarmene ancora?",
  en_title = "The Alliance Needs Roast Raptor!",
  en_obj = "Bring 20 Roast Raptor to Sarah Sadwhistle at the Military Ward in Ironforge.",
}
T[8527] = {
  title = "L'Alleanza Ha Bisogno di Altro Roast Raptor!",
  desc = "Ciao di nuovo, $C. Si vede che tutto questo ti entusiasma tanto. Immagino quindi che tu voglia portarmi altri venti roast raptor. Fantastico. Beh, fai pure. Ci vediamo quando torni, credo.",
  obj = "Porta 20 roast raptor a Sarah Sadwhistle all'aeroporto di Dun Morogh.",
  progress = "Ciao di nuovo, $C. Si vede che tutto questo ti entusiasma tanto. Immagino quindi che tu voglia portarmi altri venti roast raptor? Fantastico. Beh, fai pure. Ci vediamo quando torni, credo.",
  reward = "Wow, sei proprio $Gun tipo:una tipa; che non si ferma mai. Mi stanco solo a guardarti. Comunque, grazie da parte dell'Alleanza e tutto il resto. Farò in modo che tutta quella carne morta venga impacchettata. Magari più tardi potresti ripassare da me a vedere se ne serve ancora, anche se, a dirla tutta, comincia a far puzzare tutto.",
  en_title = "The Alliance Needs More Roast Raptor!",
  en_obj = "Bring 20 roast raptor to Sarah Sadwhistle at the airfield in Dun Morogh.",
}
T[8528] = {
  title = "L'Alleanza Ha Bisogno di Spotted Yellowtail!",
  desc = "Raccogliere pesce cotto forse non ti sembrerà una cosa da eroi, giovane $C, ma non sottovalutare quanto conta la preparazione. Anche i soldati devono mangiare, come tutti, e noi siamo qui per fare la nostra parte: quando comincerà la guerra ad Ahn'Qiraj, dovranno avere tutto ciò di cui hanno bisogno.$B$BPer questo faccio scorta di spotted yellowtail. È un cibo versatile, si conserva bene e si può usare in molti piatti diversi. E poi non ha l'odore di certi altri pesci di mare. Sei $Gdisposto:disposta; ad aiutarmi in questa impresa?",
  obj = "Porta 20 Spotted Yellowtail a Huntress Swiftriver in Military Ward, a Ironforge.",
  progress = "Se sei già di ritorno, di sicuro hai lo spotted yellowtail di cui abbiamo parlato.",
  reward = "Grazie per questo dono, $C, e per di più arrivato così puntuale. Di certo ai nostri soldati non mancherà da mangiare. Lascia solo che sistemi per bene questi pesci, poi, se sei $Gdisposto:disposta;, potremo parlare di un secondo carico.",
  en_title = "The Alliance Needs Spotted Yellowtail!",
  en_obj = "Bring 20 Spotted Yellowtail to Huntress Swiftriver at the Military Ward in Ironforge.",
}
T[8529] = {
  title = "L'Alleanza Ha Bisogno di Altro Spotted Yellowtail!",
  desc = "Se sei ancora $Gdisposto:disposta;, $N, vorrei mandarti di nuovo a prendere un carico di spotted yellowtail. Con l'esperienza che ti sei $Gfatto:fatta; la prima volta, immagino che stavolta la pesca sarà molto più rapida e facile. Ci stai?",
  obj = "Porta 20 spotted yellowtail a Huntress Swiftriver all'aerodromo di Dun Morogh.",
  progress = "Se sei ancora $Gdisposto:disposta;, $N, vorrei mandarti di nuovo a prendere un carico di spotted yellowtail. Con l'esperienza che ti sei $Gfatto:fatta; la prima volta, immagino che stavolta la pesca sarà molto più rapida e facile. Ci stai?",
  reward = "Sei un vero membro dell'Alleanza, $N. I tuoi sforzi non passeranno inosservati, e non resteranno senza riconoscenza. Grazie anche per aver cucinato il pesce: farò in modo che venga conservato per bene, poi dovrò aggiornare il conteggio. Ogni pesce ci avvicina un po' di più ad agganciare l'obiettivo.",
  en_title = "The Alliance Needs More Spotted Yellowtail!",
  en_obj = "Bring 20 spotted yellowtail to Huntress Swiftriver at the airfield in Dun Morogh.",
}
T[8530] = {
  title = "L'Alleanza Ha Bisogno di Singed Corestones!",
  desc = "$C, ho bisogno del tuo aiuto. Per lo sforzo bellico di Ahn'Qiraj dobbiamo raccogliere certe pietre che si trovano nel Molten Core: le singed Corestones, per la precisione. Mi dicono che i nostri fabbri e ingegneri possono farne buon uso, ed è qui che entri in gioco tu: devi andare nel Molten Core e raccoglierne quante più puoi. Naturalmente, ti conviene portarti dietro trentanove dei tuoi amici più stretti.",
  obj = "Porta 50 singed corestones a Commander Stronghammer alla pista di volo di Dun Morogh.",
}
T[8532] = {
  title = "L'Orda Ha Bisogno di Copper Bars!",
  desc = "Mi fa piacere che tu abbia deciso di dare una mano qui. Non tutti lo farebbero, perciò voglio essere sicuro che tu abbia capito bene cosa mi serve: Copper bars, non copper ore. Non abbiamo né il tempo né la gente per fondere tutto da soli, quindi se avrai la gentilezza di pensarci tu, il tuo impegno sarà annotato come si deve. Ne sei in grado, $C?",
  obj = "Porta 20 Copper Bars a Miner Cromwell alla Valley of Spirits, a Orgrimmar.",
  progress = "Spero che quelli che porti siano i venti copper bars, $C.",
  reward = "Questi lingotti andranno bene, e grazie di non averli lucidati: inutile farli belli, se poi verranno maciullati per qualunque equipaggiamento si debba costruire per la guerra. A impilarli ci penso io, e farò in modo che vengano usati come si deve. Se ti interessa portarne altri venti, torna a parlarmi.",
  en_title = "The Horde Needs Copper Bars!",
  en_obj = "Bring 20 Copper Bars to Miner Cromwell at the Valley of Spirits in Orgrimmar.",
}
T[8533] = {
  title = "L'Orda Ha Bisogno di Altri Copper Bars!",
  desc = "Già di ritorno? Diventerai $Gun vero minatore:una vera minatrice; in men che non si dica, $C. Allora, sai già come funziona: vai a estrarre un bel po' di copper ore, lo fondi in lingotti e me li riporti qui. Che tu ne sia capace lo so; la domanda è: ne hai voglia?",
  obj = "Porta 20 copper bars a Miner Cromwell in Durotar.",
  progress = "Già di ritorno? Diventerai $Gun vero minatore:una vera minatrice; in men che non si dica, $C. Allora, sai già come funziona: vai a estrarre un bel po' di copper ore, lo fondi in lingotti e me li riporti qui. Che tu ne sia capace lo so; la domanda è: ne hai voglia?",
  reward = "Ancora una volta ti sei $Gdimostrato:dimostrata; all'altezza, $C. Farò in modo che questo rame venga usato a tempo debito; per ora, però, devo mettere questi copper bars sul bancale e contarli. Se ne hai ancora voglia, mi farebbe comodo il tuo aiuto per raccogliere altri copper bars.",
  en_title = "The Horde Needs More Copper Bars!",
  en_obj = "Bring 20 copper bars to Miner Cromwell in Durotar.",
}
T[8534] = {
  title = "Hive'Zora Scout Report",
  desc = "Abbiamo mandato i nostri esploratori migliori nel cuore degli alveari dei silithid a raccogliere informazioni. Da diversi giorni ormai l'Esploratrice Azenel tiene d'occhio i movimenti dei silithid a Hive'Zora: trovala e fatti dare un rapporto scritto. Dobbiamo poter agire su quelle informazioni al più presto, $N.",
  obj = "Contatta Cenarion Scout Azenel in Hive'Zora e porta l'Hive'Zora Scout Report a Windcaller Proudhorn a Cenarion Hold. Devi anche portare le Tactical Task Briefing VI per completare questa quest.",
  progress = "L'Esploratrice Azenel la troverai dentro Hive'Zora. Sbrigati, $N! Il tempo stringe.",
  reward = "Ti sono davvero grata per l'impegno, $N. Leggerò subito questi rapporti di esplorazione; tu intanto puoi passare al prossimo incarico.",
}
T[8535] = {
  title = "Hoary Templar",
  desc = "Il Twilight's Hammer e i nobili elementali che venerano sono una minaccia temibile per le nostre operazioni a Silithus. Ora che dentro Ahn'Qiraj ci troviamo davanti nuovi nemici, non possiamo permetterci di abbassare la guardia qui fuori.$B$BTrova il modo di evocare e distruggere un Hoary Templar, poi fai rapporto a Bor Wildmane.",
  obj = "Evoca e uccidi un Hoary Templar e torna da Bor Wildmane a Cenarion Hold. Devi anche portare le Tactical Task Briefing IV per completare questa quest.",
  progress = "Hai già portato a termine il compito, $N?",
  reward = "Bel lavoro, $N. Ecco il prossimo incarico.",
}
T[8536] = {
  title = "Earthen Templar",
  desc = "Il Twilight's Hammer e i nobili elementali che venerano sono una minaccia temibile per le nostre operazioni a Silithus. Ora che dentro Ahn'Qiraj ci troviamo davanti nuovi nemici, non possiamo permetterci di abbassare la guardia qui fuori.$B$BTrova il modo di evocare e distruggere un Earthen Templar, poi fai rapporto a Bor Wildmane.",
  obj = "Evoca e uccidi un Earthen Templar e torna da Bor Wildmane a Cenarion Hold. Devi anche portare le Tactical Task Briefing III per completare questa quest.",
  progress = "Hai già portato a termine il compito, $N?",
  reward = "Bel lavoro, $N. Ecco il prossimo incarico.",
}
T[8537] = {
  title = "Crimson Templar",
  desc = "Il Twilight's Hammer e i nobili elementali che venera sono una minaccia temibile per le nostre operazioni a Silithus. Ora che dentro Ahn'Qiraj affrontiamo nuovi nemici, non possiamo permetterci di abbassare la guardia con quelli che stanno fuori.$B$BTrova il modo di evocare e distruggere un Crimson Templar, poi fai rapporto a Bor Wildmane.",
  obj = "Evoca e uccidi un Crimson Templar e torna da Bor Wildmane a Cenarion Hold. Per completare questa missione devi portare anche le Tactical Task Briefing II.",
  progress = "Il compito è fatto, $N?",
  reward = "Ottimo lavoro, $N. Ecco il prossimo incarico.",
}
T[8538] = {
  title = "I Quattro Duchi",
  desc = "I legami fra il Twilight's Hammer e l'Abyssal Council si stanno rivelando più importanti di quanto pensassimo.$B$BCrediamo che fra le forze principali che organizzano i cultisti del Twilight's Hammer ci siano i nobili elementali noti come Abyssal Dukes. Trova il modo di attirare i quattro Abyssal Dukes nel nostro piano di esistenza, e distruggili!$B$BTi abbiamo affidato questo compito per la dedizione e l'abilità che hai dimostrato negli incarichi passati, e siamo certi che riuscirai nell'impresa.",
  obj = "Trova un modo per evocare e uccidere il Duke of Cynders, Duke of Fathoms, Duke of Zephyrs e Duke of Shards e torna da Commander Mar'alith a Cenarion Hold. Per completare questa missione devi portare anche le Tactical Task Briefing V.",
  progress = "Il compito è fatto, $N?",
  reward = "Oggi hai compiuto una grande impresa per la nostra causa, $N: hai sconfitto alcuni dei nostri nemici più potenti, e per questo ti faccio i miei più sentiti complimenti.",
}
T[8539] = {
  title = "Obiettivo: Hive'Zora Hive Sisters",
  desc = "Per l'assalto a Hive'Zora sono stati chiamati rinforzi, e tu sei $Gstato:stata; $Gscelto:scelta; per colpire le sorelle di Hive'Zora. Quando avrai finito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Zora Hive Sisters e torna da Commander Mar'alith a Cenarion Hold, in Silithus. Per completare questa missione devi portare anche le Combat Task Briefing V.",
  progress = "Hai qualcosa da dirmi, $C?",
  reward = "Ottimo lavoro, $N. Sei $Gun degno alleato:una degna alleata;.",
}
T[8540] = {
  title = "Stivali per la Guardia",
  desc = "La divisione a cavallo della guardia di Cenarion Hold è a corto di ornate mithril boots. Procurane una partita e portala subito a Captain Vish Kozus a Cenarion Hold.",
  obj = "Porta 3 Ornate Mithril Boots a Vish Kozus, Capitano della Guardia a Cenarion Hold, in Silithus. Per completare questa missione devi portare anche le Logistics Task Briefing II.",
}
T[8541] = {
  title = "Pietre da Molatura per la Guardia",
  desc = "La guardia di Cenarion Hold è a corto di pietre da molatura. Procurane una partita e portala subito a Captain Vish Kozus a Cenarion Hold.",
  obj = "Porta 10 Dense Grinding Stones, 10 Solid Grinding Stones e 10 Heavy Grinding Stones a Vish Kozus, Capitano della Guardia a Cenarion Hold, in Silithus. Per completare questa missione devi portare anche le Logistics Task Briefing III.",
}
T[8542] = {
  title = "L'Orda Ha Bisogno di Tin Bars!",
  desc = "Lok'tar, $R, di sicuro sai già che andremo in guerra contro gli insetti, ad Ahn'Qiraj. Ma prima il Capoguerra ha deciso che faremo una cosa che si chiama \"prepararsi\". Io preferirei affilare armi e battere armature col martello, ma sono fiero che abbiano scelto me per raccogliere qui i tin bars. Solo che senza il tuo aiuto non ce la faccio.$B$BQuindi mi serve che tu vada là fuori, faccia tin bars e me li riporti qui. Credo che me ne serviranno più di quanti ne so contare.",
  obj = "Porta 20 Tin Bars al Grunt Maug nella Valley of Spirits, a Orgrimmar.",
  progress = "Quanti tin bars hai lì, $C? Finita la guerra, credo che mi servirà qualcuno che mi insegni a contare.",
  reward = "Bene, direi che è il numero giusto di tin bars. E non provare a fregarmi, $C! A contare mi fa male il cranio. Adesso io metto questi lingotti sulla pila, e tu torni là fuori e mi riporti altra roba uguale.",
  en_title = "The Horde Needs Tin Bars!",
  en_obj = "Bring 20 Tin Bars to Grunt Maug at the Valley of Spirits in Orgrimmar.",
}
T[8543] = {
  title = "L'Orda Ha Bisogno di Altri Tin Bars!",
  desc = "Molto bene, vedo che fai sul serio con la guerra. Però aspettare che cominci mi mette un po' di nervoso, e se non ti sbrighi a portare la roba mi arrabbierò. O magari posso esercitarmi su di te.$B$BHar! Forse no: poi chi me li riporterebbe, i tin bars?",
  obj = "Porta 20 tin bars al Grunt Maug in Durotar.",
  progress = "Molto bene, vedo che fai sul serio con la guerra. Però aspettare che cominci mi rende un po' nervoso, e di sicuro sei $Gnervoso:nervosa; anche tu, $C. Quando comincerà, sarà glorioso. L'Orda che corre armi in pugno sulle sabbie del deserto di Silithus e si getta a testa bassa contro le masse di insetti. Quel giorno tutti si copriranno di grande onore!$B$BHar! Ma prima ci servono altri tin bars. Buffo come una cosa così piccola possa fare tanta differenza, non trovi?",
  reward = "Throm'ka, $N. Con i tuoi tin bars fai onore a me e all'Orda. Li metto sulla pila, e poi qualcuno verrà a farci delle cose. E quando sarà tutto fatto, andremo in guerra e faremo vedere alla debole Alleanza come si combattono gli insetti.$B$BOra riportami altri tin bars!",
  en_title = "The Horde Needs More Tin Bars!",
  en_obj = "Bring 20 tin bars to Grunt Maug in Durotar.",
}
T[8544] = {
  title = "Conqueror's Spaulders",
  desc = "Fra noi si dice che le elaborate armature da spalla delle razze mortali siano nate dal tentativo di imitare le ali di un drago.$B$BPortami le manette che portano i più alti capi Qiraji e ne farò un paio di spallacci più terrificanti persino delle ali di Nefarian in persona!",
  obj = "Porta le Qiraji Bindings of Command, 2 Idols of Night, 5 Stone Scarabs e 5 Clay Scarabs ad Andorgos ad Ahn'Qiraj. Devi anche raggiungere la reputazione Neutrale con la Brood of Nozdormu per completare questa missione.",
  progress = "I componenti che mi servono: li hai raccolti?",
  reward = "Con i materiali che mi hai portato e con le scaglie dei nostri nemici Qiraji caduti creo per te questi spallacci, mortale. Che ti diano la protezione di cui hai bisogno, e che la loro vista metta paura ai nostri avversari.",
}
T[8545] = {
  title = "L'Orda Ha Bisogno di Mithril Bars!",
  desc = "$C, la guerra sta arrivando e non possiamo fare altro che prepararci. Ed è qui che io e te possiamo darci una mano, mon. Vedi, mi hanno messa a capo della raccolta di tutti i mithril bars che ci servono per costruire tutto quello che ci vorrà. E me ne servono ancora!$B$BQuindi spero che tu possa andare là fuori a scavarci un po' di mithril e poi fonderlo in lingotti. Che dici, puoi farlo per noi?",
  obj = "Porta 20 Mithril Bars a Senior Sergeant T'kelah nella Valley of Spirits, a Orgrimmar.",
  progress = "Sarebbe proprio bello avere tutti i mithril bars che ci servono per la guerra di Ahn'Qiraj. Sei $Gtornato:tornata; per questo, mon? Hai i miei lingotti?",
  reward = "Per te e per me è un buon inizio, $C. Altri venti mithril bars da mettere sulle pile e spuntare dalla lista, e tutto quanto sarà usato a dovere per fare materiale bellico.$B$BRipassa da me, perché sai, pare che ci serviranno ancora più mithril bars.",
  en_title = "The Horde Needs Mithril Bars!",
  en_obj = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar.",
}
T[8546] = {
  title = "L'Orda Ha Bisogno di Altri Mithril Bars!",
  progress = "Sì, sono contenta che sei qui, mon. Mi hai già dato una mano, e adesso ho di nuovo bisogno di te. Cerchiamo ancora di mettere insieme altri mithril bars per la guerra; costruiremo un sacco di armature e armi e cose per andare a schiacciare quegli insetti ad Ahn'Qiraj.$B$BQuindi, se sei $Gun vero amico:una vera amica;, mi riporti altre pile di mithril bars. Prendo tutto quello che hai, finché non arriviamo alla quota. Ne hai qualcuno per me, adesso?",
  reward = "Bel lavoro, $N! Con altri venti lingotti siamo ancora un po' più vicini all'obiettivo, e abbiamo altro materiale bellico. A metterli via ci penso io. E se ti procuri un'altra pila di mithril bars, mon, portala qui da me.",
  en_title = "The Horde Needs More Mithril Bars!",
  en_obj = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar.",
}
T[8548] = {
  title = "Equipaggiamento da Battaglia del Volontario",
  desc = "I distintivi che ti guadagni con gli incarichi di combattimento, logistici e tattici per Cenarion Hold non servono solo a fare scena, $N.$B$BFaresti bene a tenerli da conto: man mano che dimostrerai la tua lealtà alla nostra organizzazione, potrò darti in cambio parte dell'equipaggiamento che riserviamo agli alleati più stretti.",
  obj = "Porta 5 Cenarion Combat Badges, 3 Cenarion Logistics Badges e 7 Cenarion Tactical Badges a Vargus, a Cenarion Hold, in Silithus. Devi inoltre ottenere la reputazione Amichevole con il Cenarion Circle per poter completare questa quest.",
  progress = "È nel nostro interesse che gli alleati più fedeli siano ben equipaggiati, $N.",
  reward = "Ottimo lavoro, $N. Accetta questo a nome del Cenarion Circle. Te lo sei proprio meritato, $Gamico:amica;!",
}
T[8549] = {
  title = "L'Orda Ha Bisogno di Peacebloom!",
  desc = "Si dice che ogni generazione abbia una prova decisiva da affrontare. Temo che per noi sarà la Guerra di Ahn'Qiraj: è quello il crogiolo in cui verrà messa alla prova la nostra tempra. Così ci prepariamo, e intanto scopriamo di che pasta siamo fatti.$B$BMi sono offerta di aiutare l'Orda raccogliendo più peacebloom che posso, perché se ne ricavino pozioni per la guerra. Spero che tu sia qui per darmi una mano. Se è così, dovresti portarmi una buona quantità di quest'erba. Mi aiuterai, $C?",
  obj = "Porta 20 Peacebloom a Herbalist Proudfeather nella Valley of Spirits a Orgrimmar.",
  progress = "$GTornato:Tornata; così presto con il peacebloom, $C?",
  reward = "E così, con i nostri sforzi, ci avviciniamo ancora un po' alla guerra. Grazie di aver lavorato tanto duramente per raccogliere questo peacebloom, $C. Ti assicuro che verrà usato bene, e che il tuo contributo non è passato inosservato, $N. Se sarai $Gdisposto:disposta;, torna da me con altri fiori. Fino ad allora, che la Madre Terra ti guidi.",
  en_title = "The Horde Needs Peacebloom!",
  en_obj = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar.",
}
T[8550] = {
  title = "L'Orda Ha Bisogno di Altro Peacebloom!",
  progress = "Ben $Gritrovato:ritrovata;, $N. Mi fa piacere che tu voglia parlarmi ancora del nostro bisogno infinito di peacebloom. Lo sforzo bellico va avanti, e con lui la nostra produzione di pozioni ed elisir che ci aiuteranno nelle battaglie a venire. Ci darai ancora una mano, $C? Mi serve tanto peacebloom quanto l'altra volta: se riesci a raccoglierlo e a riportarmelo qui, te ne sarò davvero grata. E se ce l'hai già con te, naturalmente, lo prenderò subito più che volentieri",
  reward = "Grazie del tuo impegno costante, $N. Con la tua generosità disinteressata porti grande onore a te e ai tuoi antenati, e tutti lo sapranno! Metterò via queste erbe, così resteranno fresche fino a quando serviranno. Ancora una volta mostri il vero spirito dell'Orda: la lotta per superare ogni ostacolo e la promessa che, lavorando insieme, possiamo farcela.",
  en_title = "The Horde Needs Peacebloom!",
  en_obj = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar.",
}
T[8551] = {
  title = "Il Captain's Chest",
  desc = "Un tempo navigavo da qui fino a Ratchet, a Kalimdor. Ero un capitano di successo, con una reputazione impeccabile.$B$BFinché...$B$BQuei maledetti giganti marini mi hanno rovinato! Mi hanno distrutto la nave, ucciso l'equipaggio e mi hanno messo su una scialuppa diretta a Booty Bay. E uno di loro, Gorlash, mi ha rubato il Captain's Chest: ha detto che lo voleva come tabacchiera. Che faccia tosta!$B$BHo sentito dire che Gorlash si aggira lungo la costa, a est di qui. Trovalo e riportami il mio forziere! Fallo, e ti sarai $Gguadagnato:guadagnata; la gratitudine di un capitano.",
  obj = "Porta lo Smotts' Chest a Hecklebury Smotts a Booty Bay.",
  progress = "Ohilà, $N! Hai trovato Gorlash? Quel forziere era il mio preferito, e ha uno scomparto segreto dove tenevo i tesori più preziosi!",
  reward = "L'hai trovato! Oh, giorno felice è questo! Grazie, $N. Riavere il forziere mi spegne un po' il fuoco che ho dentro.$B$BMa la mia vendetta non è compiuta...",
  en_title = "The Captain's Chest",
  en_obj = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.",
}
T[8552] = {
  title = "La Monogrammed Sash",
  desc = "Lungo l'orlo di questa fascia pregiata sono ricamate le lettere \"HS\".",
  obj = "Restituisci la Monogrammed Sash al suo proprietario.",
  progress = "Salve. Mi cerchi per qualche affare?",
  reward = "Mi hai riportato la fascia? Allora... devi aver ucciso Mok'rash, il sea giant! Urrà!$B$BSono contento che quel lurido furfante sia morto — Mok'rash era uno dei tre giganti del mare che mi hanno distrutto le navi e ammazzato l'equipaggio.$B$BTre volte.$B$BSei $Gun:una; $C di valore, $N.",
  en_title = "The Monogrammed Sash",
  en_obj = "Return the Monogrammed Sash to its owner.",
}
T[8553] = {
  title = "La Scimitarra del Capitano",
  desc = "Per colpa di quei giganti ho perso la prima nave, così ne ho comprata un'altra. L'ho battezzata Smotts' Revenge, l'ho riempita di provviste e di marinai e sono partito a cercare quei furfanti. Li ho trovati, ma... mi hanno battuto. Hanno distrutto la Smotts' Revenge, hanno ucciso il secondo equipaggio e mi hanno messo su un'altra scialuppa di salvataggio.$B$BStavolta è stato un altro gigante, Negolash, a rubarmi la scimitarra.$B$BAffronta Negolash e riportamela!$B$BParla con Sprogger, che faceva il cuoco sulla Smotts' Revenge ed è sopravvissuto all'ultimo attacco: può aiutarti a trovare il gigante.",
  obj = "Parla con Sprogger.",
  reward = "Ehilà, ehilà, $N. Il Capitano mi ha detto che sei a caccia di Negolash, eh?",
  en_title = "The Captain's Cutlass",
  en_obj = "Speak with Sprogger.",
}
T[8554] = {
  title = "Affrontare Negolash",
  desc = "Negolash è un gigante affamato.$B$BQuando i giganti ci hanno distrutto la nave, Negolash è andato dritto nella mia cucina. Non aveva fame di marinai come gli altri: Negolash voleva il vino... e le mie Barbecued Buzzard Wings. Sono la mia specialità, e per la ricetta ho dovuto spingermi fino alle Badlands!$B$BSe vuoi attirare il gigante, procurati del vino e un mucchio di ali di condor e mettili nella nostra vecchia scialuppa di salvataggio, lungo la costa a sud-est di qui. Appena Negolash sentirà l'odore di tutto quel cibo, arriverà di sicuro!",
  obj = "Porta 10 Barbecued Buzzard Wings e 5 bottiglie di Junglevine Wine alla scialuppa di salvataggio di Captain Smotts.$B$BUccidi Negolash e porta la Smotts' Cutlass a Captain Smotts a Stranglethorn.",
  progress = "Hai recuperato la mia scimitarra, $N?",
  reward = "Hai strappato a Negolash la mia scimitarra! Che fortuna, non ci posso credere, $N! Da quando ti ho incontrato la mia sorte è cambiata in meglio, non c'è dubbio!$B$BGrazie! E se un giorno avrò una nuova nave e vorrai solcare i mari, sarai $Gil mio ospite d'onore:la mia ospite d'onore;.",
  en_title = "Facing Negolash",
  en_obj = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.$B$BKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.",
}
T[8555] = {
  title = "Il Charge of the Dragonflights",
  reward = "Eranikus, Vaelastrasz e Azuregos... Questi draghi li conosci di certo, mortale. Non è un caso, quindi, che come custodi del nostro mondo abbiano avuto ruoli tanto importanti.$B$BPurtroppo (e la colpa è in parte della mia ingenuità), per mano degli agenti degli Old Gods o per il tradimento di chi si diceva loro amico, ogni guardiano ha fatto una fine tragica, e la mia sfiducia verso la tua specie ne è cresciuta.$B$BCercali... E tu, $R, preparati al peggio.",
}
T[8556] = {
  title = "Signet of Unyielding Strength",
  desc = "Si dice che gli anelli portati dai luogotenenti Qiraji concedano loro abilità formidabili. In teoria, se si sostituissero le gemme corrotte che li adornano con materiali più puri, se ne otterrebbero anelli non corrotti.$B$BLe gemme degli idoli Qiraji andrebbero benissimo, perché sono di qualità superiore.$B$BPortami l'anello e gli idoli e ne creerò per te uno potente, $C.",
  obj = "Porta 1 Qiraji Magisterial Ring, 2 Lambent Idols, 5 Bronze Scarabs e 5 Ivory Scarabs a Windcaller Yessendra a Silithus. Per completare questa quest devi anche ottenere la reputazione Onorato con il Cenarion Circle.",
  progress = "Mi hai portato l'anello e i materiali, $N?",
  reward = "Sostituirò per te la gemma dell'anello. Vedrai, l'effetto è molto più... gradevole.",
}
T[8557] = {
  title = "Drape of Unyielding Strength",
  desc = "Mi fa piacere sapere che ci aiuti nell'attacco ad Ahn'Qiraj, $N. Per la lotta contro il nostro nemico posso prepararti un oggetto protettivo che ti sarà utile, $C.$B$BMi occorrerà un drappo Qiraji, che naturalmente adatterò alle tue misure, e poi idoli e scarabei, per farne un fermaglio adeguato.$B$BNon resterai $Gdeluso:delusa;, te lo prometto.",
  obj = "Porta 1 Qiraji Martial Drape, 2 Onyx Idols, 5 Silver Scarabs e 5 Bone Scarabs a Keyl Swiftclaw in Silithus. Per completare questa quest devi anche ottenere la reputazione Riverito con il Cenarion Circle.",
  progress = "Hai con te i materiali per il mantello, $N?",
  reward = "Ah sì... è immacolato, questo drappo.$B$BPrendi questo mantello, $N, e che ti protegga dalla magia immonda dei Qiraji.",
}
T[8558] = {
  title = "Sickle of Unyielding Strength",
  desc = "Gli oggetti che impugnano i Qiraji e i loro servi sono fatti dei materiali più rari e pregiati: ossa di antiche creature gigantesche, gemme venute dalle profondità della terra, metalli puri e resistenti.$B$BMi basta guardare i manufatti Qiraji per avere voglia di frantumarli, fonderne i pezzi e lavorarli con la mia arte. Dimostra la tua fedeltà al Circolo, $N, e con i migliori materiali Qiraji ti forgerò un'arma potente.",
  obj = "Porta 1 Qiraji Spiked Hilt, 2 Alabaster Idols, 5 Crystal Scarabs e 5 Stone Scarabs a Warden Haro a Silithus. Per completare questa missione devi anche ottenere la reputazione Osannato con il Cenarion Circle.",
  progress = "$N, mi hai portato i componenti che mi servono?",
  reward = "Hai lavorato bene, $C. Quest'elsa è opera di un maestro... ha un equilibrio perfetto.$B$BPrendi la tua arma, $N. Impugnala con piena sicurezza e sconfiggi i nostri nemici!",
}
T[8559] = {
  title = "Conqueror's Greaves",
  desc = "Antica e forte è la magia dei Qiraji, e i più potenti fra i qiraji brandiscono oggetti capaci di far esitare perfino un drago.$B$BPortami le manette del comando qiraji insieme ad altri componenti minori, e ne ricaverò per te un paio di stivali potenti.$B$BTi serviranno nella lotta contro il nemico.",
  obj = "Porta le Qiraji Bindings of Command, 2 Idols of War, 5 Ivory Scarabs e 5 Gold Scarabs a Kandrostrasz in Ahn'Qiraj. Per questa quest serve anche la reputazione Neutrale con la Brood of Nozdormu.",
  progress = "Hai trovato gli oggetti che ti ho chiesto, $N?",
  reward = "Bel lavoro, $N. Hai dimostrato di non essere $Gun:una; mortale qualunque.$B$BEcco, te li consegno: sono certo che ti aiuteranno a schiacciare i vili qiraji.",
}
T[8560] = {
  title = "Conqueror's Legguards",
  desc = "Cerchi di dimostrare il tuo valore alla mia specie, mortale? Molto bene: forse possiamo aiutarci a vicenda.$B$BOuro, l'antico verme delle sabbie, è un essere dal potere leggendario. Si dice che l'abbia creato l'Old God in persona, come una parodia della vita.$B$BLa sua pelle è innaturale... spessa, quasi impenetrabile, eppure così flessibile da permettergli di muoversi con la velocità e la grazia di una creatura molto più piccola.$B$BPortami un campione di quella pelle insieme ad altri componenti minori, e ti realizzerò dei gambali di grande potere.",
  obj = "Porta l'Ouro's Intact Hide, 2 Idols of Death, 5 Bronze Scarabs e 5 Ivory Scarabs a Kandrostrasz dentro Ahn'Qiraj. Per completare questa quest devi anche raggiungere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Hai portato i componenti che mi servono, $N?",
  reward = "Sì... la pelle del verme sarà un ottimo strato protettivo. Insieme alle parti più resistenti dei Qiraji che abbiamo distrutto per arrivare fin qui, dovrebbe diventare un pezzo d'armatura formidabile. Possa aiutarti ad affrontare gli orrori indicibili che ti attendono là dentro!",
}
T[8561] = {
  title = "Conqueror's Crown",
  desc = "Gli Imperatori Gemelli... i loro sussurri non si fermano mai, e lentamente mi stanno togliendo il senno. Mi deridono, perché sanno che non posso spingermi più a fondo nel loro dominio per salvare mio fratello Arygos.$B$BNelle mie visioni vedo i loro volti mostruosi, adorni di potenti corone. Ma avrò la mia vendetta... trasmuterò questi simboli del potere Qiraji in altri che servano meglio ai nostri bisogni.$B$BPortami i componenti che mi servono, $N, e ti darò un copricapo dal potere senza pari.",
  obj = "Porta la Vek'nilash's Circlet, 2 Idols of the Sun, 5 Stone Scarabs e 5 Crystal Scarabs ad Andorgos ad Ahn'Qiraj. Devi anche raggiungere la reputazione Amichevole con la Brood of Nozdormu per completare questa missione.",
  progress = "$N, mi hai portato i componenti che ti ho chiesto?",
  reward = "Ce l'hai fatta! Gli Imperatori Gemelli hanno smesso di sussurrare.$B$BPrendi questo, è la tua ricompensa. Basterà vederlo perché la paura entri nel cuore dei Qiraji... ricorderà loro i capi caduti e $Gil:la; mortale che li ha uccisi.",
}
T[8562] = {
  title = "Conqueror's Breastplate",
  desc = "Sotto Ahn'Qiraj, l'innominabile Old God si sta lentamente risvegliando dal sonno. Il terribile destino che incombe su Azeroth potrebbe compiersi fra qualche giorno come fra qualche anno; per esseri potenti come lui il tempo non ha significato.$B$BQuando le stelle saranno propizie, si scaglierà con una collera terribile contro ogni essere vivente. Prima di allora devi trovarlo e scoprire come porre fine alla sua esistenza.$B$BFallo, e portami un pezzo del suo guscio: ti concederò un'armatura che nessun mortale ha mai indossato... un'armatura degna di chi ha ucciso un dio!",
  obj = "Porta il Carapace of the Old God, 2 Idols of War, 5 Silver Scarabs e 5 Bone Scarabs a Vethsera dentro Ahn'Qiraj. Devi anche raggiungere la reputazione Onorato con la Brood of Nozdormu per completare questa quest.",
  progress = "Il temibile C'Thun attende, dormiente, nella sua dimora ad Ahn'Qiraj.",
  reward = "Non credevo che saresti $Gtornato:tornata; da quest'impresa, $N.$B$BHai compiuto un destino più grande di quello della maggior parte degli esseri immortali.$B$BUccidendo C'Thun non hai soltanto salvato tutta Azeroth: hai alterato l'equilibrio di eventi cosmici che vanno oltre la tua comprensione.$B$BAccetta questo pettorale, simbolo della gloria e del fardello che le tue azioni porteranno con sé.$B$BPossa il suo potere aiutarti nelle sfide che ti attendono, $Guccisore:uccisora; di dei!",
}
T[8565] = {
  title = "Vittorie Passate ad Arathi",
  reward = "Ah, sì! Ci mancherebbe che ci dimenticassimo dei tuoi successi passati nell'Arathi Basin.",
}
T[8566] = {
  title = "Vittorie Passate ad Arathi",
  reward = "Ah, sì! Non ci dimenticheremmo certo dei tuoi successi passati nell'Arathi Basin.",
}
