}
T[8572] = {
  title = "Equipaggiamento da Battaglia del Veterano",
  desc = "I distintivi che ti guadagni con gli incarichi di combattimento, logistici e tattici per Cenarion Hold non servono solo a fare scena, $N.$B$BFaresti bene a tenerli da conto: man mano che dimostrerai la tua lealtà alla nostra organizzazione, potrò darti in cambio parte dell'equipaggiamento che riserviamo agli alleati più stretti.",
  obj = "Porta 7 Cenarion Combat Badges, 4 Cenarion Logistics Badges e 4 Cenarion Tactical Badges a Vargus, a Cenarion Hold, in Silithus. Devi inoltre ottenere la reputazione Onorato con il Cenarion Circle per poter completare questa quest.",
  progress = "È nel nostro interesse che gli alleati più fedeli siano ben equipaggiati, $N.",
  reward = "Ottimo lavoro, $N. Accetta questo a nome del Cenarion Circle. Te lo sei proprio meritato, $Gamico:amica;!",
}
T[8573] = {
  title = "Equipaggiamento da Battaglia del Campione",
  desc = "I distintivi che ti guadagni con gli incarichi di combattimento, logistici e tattici per Cenarion Hold non servono solo a fare scena, $N.$B$BFaresti bene a tenerli da conto: man mano che dimostrerai la tua lealtà alla nostra organizzazione, potrò darti in cambio parte dell'equipaggiamento che riserviamo agli alleati più stretti.",
  obj = "Porta 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 20 Cenarion Tactical Badges e 1 Mark of Cenarius a Vargus, a Cenarion Hold, in Silithus. Devi inoltre ottenere la reputazione Osannato con il Cenarion Circle per poter completare questa quest.",
  progress = "È nel nostro interesse che gli alleati più fedeli siano ben equipaggiati, $N.",
  reward = "Ottimo lavoro, $N. Accetta questo a nome del Cenarion Circle. Te lo sei proprio meritato, $Gamico:amica;!",
}
T[8574] = {
  title = "Equipaggiamento da Battaglia del Risoluto",
  desc = "I distintivi che ti guadagni con gli incarichi di combattimento, logistici e tattici per Windcaller Proudhorn non servono solo a fare scena, $N.$B$BFaresti bene a tenerli da conto: man mano che dimostrerai la tua lealtà alla nostra organizzazione, potrò darti in cambio parte dell'equipaggiamento che riserviamo agli alleati più stretti.",
  obj = "Porta 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 17 Cenarion Tactical Badges e 1 Mark of Remulos a Vargus, a Cenarion Hold, in Silithus. Devi inoltre ottenere la reputazione Riverito con il Cenarion Circle per poter completare questa quest.",
  progress = "È nel nostro interesse che gli alleati più fedeli siano ben equipaggiati, $N.",
  reward = "Ottimo lavoro, $N. Accetta questo a nome del Cenarion Circle. Te lo sei proprio meritato, $Gamico:amica;!",
}
T[8575] = {
  title = "Il Magical Ledger di Azuregos",
  desc = "Di questo libro mastro non capisci una sola parola. Non sai neanche in che lingua sia scritto!",
  obj = "Consegna il Magical Ledger di Azuregos a Narain Soothfancy in Tanaris.",
  progress = "Ooooh! Un aggeggio magico pulsante! È per me?",
  reward = "<Narain esamina impaziente la lettera.>$B$BStraordinario, $R! Che cos'è? Di Draconico non so leggere un'acca.",
}
T[8576] = {
  title = "Tradurre il Registro",
  reward = "Andiamo con ordine, $N! Per prima cosa dobbiamo capire cosa ha scritto Azuregos in questo registro.$B$BTi ha detto di fabbricare un'arcanite buoy, dici, e lo schema è questo? Strano che l'abbia scritto in Draconico: quel vecchio caprone lo sa che questi scarabocchi non li so leggere.$B$BSe vogliamo che funzioni, mi servono gli occhiali divinatori, un pollo da cinquecento libbre e il volume II di \"Draconic for Dummies.\" Non per forza in quest'ordine.",
}
T[8577] = {
  title = "Stewvul, Ex-B.F.F.",
  desc = "Se devo tradurre qualcosa, ho bisogno degli occhiali veggenti. Purtroppo parecchio tempo fa me li ha rubati Stewvul, il mio ex migliore amico per sempre. Mi ha spezzato il cuore in cinque punti e poi mi ha lasciato qui a marcire.$B$BGrazie alla mia fidata sfera di cristallo ho ristretto le ricerche a due posti: il Greymane Wall a Silverpine, oppure quello che sembra un mondo al di là di un portale, nell'Outland, che adesso è invaso dalla Burning Legion. Devi rintracciarlo e riprendermi gli occhiali, $N!",
  obj = "Narain Soothfancy vuole che trovi il suo ex migliore amico per sempre (BFF), Stewvul, e che recuperi gli occhiali veggenti che Stewvul gli ha rubato.",
  reward = "Non posso credere che mi abbia trovato. Ero sicuro di averlo seminato quando stavo nell'Outland. Io là non ci torno, $R! Neanche per sogno, mai e poi mai! Basta fare il suo migliore amico per sempre part-time e il suo schiavo a tempo pieno.",
}
T[8578] = {
  title = "Occhiali Veggenti? Nessun Problema!",
  desc = "<Dalla cassa senti uscire un sospiro di sollievo.>$B$BVuoi soltanto i suoi occhiali veggenti? Fantastico! Nessun problema... Dammi un minuto per... Ehi! Dove diavolo... Accidenti!$B$BAllora, ho una notizia brutta e una peggiore. Quella brutta è che ho perso gli occhiali. Quella peggiore è che li ho persi il mese scorso, mentre ficcavo il naso nel Molten Core. Già, il Molten Core... Direi che i nostri affari finiscono qui! Ciao!",
  obj = "Trova i Narain's Scrying Goggles e riportali a Narain Soothfancy a Tanaris.",
  progress = "The Molten Core, eh? Spero che i miei occhiali siano ancora tutti interi!",
  reward = "Eccezionale! E adesso dove li ho messi quel 500 pound chicken e il Volume II di \"Draconic For Dummies???\" Ah, ed ecco un pensierino per tutta la fatica!",
}
T[8579] = {
  title = "Campioni Mortali",
  progress = "Sentiamo i nostri fratelli ridotti in schiavitù nelle profondità di Ahn'Qiraj, ma nemmeno un esercito di draghi basterebbe a salvarli, $R.$B$BSe ci avvicinassimo ancora a C'Thun, lo stesso incantesimo che ha imprigionato loro metterebbe saldamente anche noi sotto il suo controllo.$B$BL'Old God ha previsto il nostro arrivo, e ogni speranza è perduta. Cosa potrebbe mai cambiare $Gun:una; semplice mortale come te?",
  reward = "Vedo che non sei $Gun:una; mortale qualunque, $N. Per quanto infinitamente piccole, ormai le tue possibilità contro l'Old God sono maggiori delle nostre: in fondo lui si aspetta i draghi alle porte, ma non è pronto per qualcuno come te.$B$BMille anni fa Anachronos e Staghelm sconfissero i Qiraji grazie all'alleanza fra le razze mortali e quelle dei draghi: allo stesso modo, anche noi stringeremo un patto. Guadagnati la fiducia dello Stormo Bronzeo e avrai anche la nostra. Solo allora faremo di te $Gun vero campione:una vera campionessa;.",
}
T[8580] = {
  title = "L'Orda Ha Bisogno di Firebloom!",
  desc = "Ehi, $C. Sì, proprio tu, mon! L'Orda pensa che per questa guerra di Ahn'Qiraj le serve un sacco di firebloom. Magari lo mettono in belle cose che fanno bum? Magari lo danno all'Alleanza per far andare i loro steam tanks? Chi lo sa? Pele'keiki no!$B$BPerò una cosa Pele'keiki la sa... lui sa che tu lo aiuti e gli riporti tanto firebloom, vero, mon?",
  obj = "Porta 20 Firebloom a Batrider Pele'keiki nella Valley of Spirits a Orgrimmar.",
  progress = "Tu non vuoi far arrabbiare Pele'keiki. Tu porti tanto firebloom, e presto, e fai contento Pele'keiki.",
  reward = "$C! Pele'keiki contento, per ora. Pele'keiki prende tutto questo firebloom e lo mette in una cassa, così resta fresco, e poi Pele'keiki si assicura che tutto il firebloom diventa roba buona per la guerra. E se ne trovi ancora, tu vieni veloce da Pele'keiki. Pele'keiki probabile che ne serve ancora.",
  en_title = "The Horde Needs Firebloom!",
  en_obj = "Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar.",
}
T[8581] = {
  title = "L'Orda Ha Bisogno di Altro Firebloom!",
  progress = "Pele'keiki sa che vieni ad aiutare. Porta tanto firebloom e fallo molto contento. Pele'keiki forse fa grosse bombe con il firebloom, e quando arriva la guerra le butta sugli insetti dal suo pipistrello, sopra Ahn'Qiraj. Ma a Pele'keiki serve altro firebloom, $C!$B$BTu porti a Pele'keiki quel firebloom, e alla svelta. Torna con almeno tanto quanto l'ultima volta, e Pele'keiki sarà contento.",
  reward = "Non è uno scherzo, $C? Tu porti il firebloom a Pele'keiki così veloce? Pele'keiki lo conta subito, mon! Tu fai Pele'keiki così contento che lui dice a tutti che $N è $Gil miglior raccoglitore:la miglior raccoglitrice; di firebloom di sempre! Pele'keiki non vede l'ora che comincia la guerra. Ora sì che illuminiamo il cielo sopra Silithus, vero, $Gfratello:sorella;?!",
  en_title = "The Horde Needs More Firebloom!",
  en_obj = "Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar.",
}
T[8582] = {
  title = "L'Orda Ha Bisogno di Purple Lotus!",
  desc = "Il purple lotus, $C, è un reagente che entra in moltissime pozioni, elisir e oli, e alcuni ci torneranno utili ad Ahn'Qiraj. Per lo sforzo bellico dovremo prepararne in quantità immense. E farò anche degli esperimenti per trovare altri usi del loto. Ma per tutto questo mi servirà una grande quantità di fiori.$B$BEd è qui che entri in gioco tu. Va' sul campo e raccogli più purple lotuses che puoi. Sei $Gdisposto:disposta; a farlo per noi?",
  obj = "Porta 20 Purple Lotus ad Apothecary Jezel, nella Valley of Spirits, a Orgrimmar.",
  progress = "Sei già $Gtornato:tornata; con il purple lotus che ti ho chiesto, $C? Mi serve al più presto, è fondamentale: altrimenti tutto quello che sto cercando di fare qui finirà nel nulla.",
  reward = "Un impegno lodevole, $C. Misurerò questi campioni per capire come usarli al meglio, e annoterò il tuo contributo. Poi il purple lotus andrà conservato come si deve finché non sarò pronta a usarlo. Quanto a te, se sei ancora disponibile, immagino che mi servirà altro purple lotus. Ripassa da me fra un momento, per favore.",
  en_title = "The Horde Needs Purple Lotus!",
  en_obj = "Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar.",
}
T[8583] = {
  title = "L'Orda Ha Bisogno di Altro Purple Lotus!",
  progress = "In effetti pare che ci serva ancora altro purple lotus, $C. Finora i miei studi non hanno scoperto nuovi modi di usare quest'erba, ma ci sono metodi collaudati che non abbiamo ancora messo in pratica.$B$BHo bisogno che torni sul campo e raccolga almeno venti campioni di purple lotus. Poi riportameli qui.",
  reward = "Un lavoro eccellente e preciso, $N. Meriti un elogio per la diligenza, e anche per la celerità. Mi assicurerò di persona che nessuno di questi purple lotuses vada sprecato.$B$BGrazie ancora. E se ti capita altro purple lotus, non esitare a portarmelo con la massima sollecitudine.",
  en_title = "The Horde Needs More Purple Lotus!",
  en_obj = "Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar.",
}
T[8584] = {
  title = "Non Chiedermi Mai dei Miei Affari",
  desc = "Se c'è una cosa che devi sapere di me è questa: non chiedermi MAI dei miei affari! Lavoro con cose che tu, semplicemente, non puoi capire. Un esempio? Sai cos'è un muzzledorf psicotronico? Certo che no! Ecco perché io faccio i piani e tu vai a prendere le cose.$B$BCome ti ho già detto, se vogliamo che funzioni ci servirà un 500 pound chicken.$B$BVai a Gadgetzan e parla con Dirge Quikcleave — ti aiuterà a cominciare a cercare un esemplare adatto.",
  obj = "Narain Soothfancy a Tanaris vuole che tu parli con Dirge Quikcleave a Gadgetzan.",
  reward = "<Dirge si gratta la testa.>$B$BUn 500 pound chicken? Una cosa del genere non esiste! Almeno, non più. Di un pollo così ho sentito parlare... The Black Chicken of Death...$B$B<La voce di Dirge si spegne.>$B$BMa sì, chi ha visto quel pollo non è mai sopravvissuto per raccontarlo. Ho un'idea che potrebbe tornare utile a tutti e due, $Gragazzo:ragazza;.",
}
T[8585] = {
  title = "L'Isle of Dread!",
  desc = "Dicono che i chimaerok dell'Isle of Dread, a Feralas, abbiano le cibarie più succulente e tenere che esistano! E questi chimaerok hanno pure un papà che, preparato a dovere, potrebbe somigliare a un 500 pound chicken... o forse no.$B$BVai sull'Isle of Dread, uccidi Lord Lakmaeran e portami la sua fresh carcass: allo gnomo dovrebbe bastare. Per accontentare me, invece, dovrai procurarti un po' di chimaerok tenderloin.$B$BFallo e avrai il tuo 500 pound chicken, più qualcosina.",
  obj = "Recupera la Lakmaeran's Carcass e 20 Chimaerok Tenderloins per Dirge Quickcleave a Tanaris.",
  progress = "Mmmmm... Chimaerok...",
  reward = "Guarda che marezzatura hanno quei filetti! Fantastico!$B$BE adesso, quel pollo... Hrm, fammi pensare. Mi ci vorrà qualche minuto per mettere a punto la ricetta.",
}
T[8586] = {
  title = "Dirge's Kickin' Chimaerok Chops",
  desc = "La ricetta è pronta! Adesso portami un po' di carburante razzo e di deeprock salt. Alle spezie ci penso io, e la carne che mi hai portato farà il resto.$B$BQuando avrò quello che ti ho chiesto, il pollo sarà pronto da riportare a Narain.",
  obj = "Dirge Quikcleave a Gadgetzan vuole che tu gli porti 20 dosi di Goblin Rocket Fuel e 20 dosi di Deeprock Salt.",
  progress = "Sbrigati, $Gragazzo:ragazza;. Non vogliamo che questa carne vada a male.",
  reward = "È pronto! Ecco a te la mia più grande creazione: Dirge's Kickin' Chimaerok Chops!",
}
T[8587] = {
  title = "Ritorno da Narain",
  desc = "Sono un goblin di parola, $Gragazzo:ragazza;. Ecco il tuo 500 pound chicken.$B$BChe se ne faccia uno gnomo di un 500 pound chicken, non lo saprò mai...$B$B<Dirge borbotta qualcosa di incomprensibile.>$B$BCi dormirà dentro, probabilmente... Sporchi gnomi...",
  obj = "Consegna il 500 Pound Chicken a Narain Soothfancy a Tanaris.",
  progress = "Che cos'è questo profumo delizioso?",
  reward = "<Narain affonda tutti e due i pugni nell'enorme pollo e si riempie la bocca con la deliziosa prelibatezza di Dirge.>$B$BMMmmm... È incredibile! È il pollo più buono che abbia mai mangiato!",
}
T[8588] = {
  title = "L'Orda Ha Bisogno di Heavy Leather!",
  desc = "Visto che ci prepariamo alla guerra, forse è meglio procurarci prima tutto quello che serve, non credi, mon? Fra le forniture di guerra che produciamo, uno dei materiali base è l'heavy leather. Ci servirà quasi per tutto, dai rinforzi alle armature, e pure per i buoni vecchi teloni.$B$BMa prima ce ne serve dell'altro, e ci pensi tu, $C. Affila il coltello e portamene un fascio, poi ne riparliamo.",
  obj = "Porta 10 Heavy Leather a Skinner Jamani, nella Valley of Spirits, a Orgrimmar.",
  progress = "Se sei qui solo per chiacchierare, $C, non ho tempo da perdere. Ho troppe pile di heavy leather da conciare. Torna quando ne avrai almeno dieci per me.",
  reward = "Oh, allora l'heavy leather che mi serviva ce l'hai davvero. Hai proprio la lama affilata, $C; queste sono pelli buone! Ora che siamo partiti col piede giusto, mi assicurerò che il tuo contributo venga usato bene. E se ti capita altro heavy leather, portamelo.",
  en_title = "The Horde Needs Heavy Leather!",
  en_obj = "Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar.",
}
T[8589] = {
  title = "L'Orda Ha Bisogno di Altro Heavy Leather!",
  progress = "È vero, $C, mi serve ancora altro heavy leather. A quanto pare i generali e i loro furieri non smettono mai di chiederne. E non è niente in confronto a quello che vogliono i mastri degli zeppelin!$B$BDevo mettere insieme la mia quota alla svelta. $N, portami altre pile di heavy leather il prima possibile!",
  reward = "Sei $Gun:una; grande, mon! Grazie mille dell'heavy leather. Ogni pezzetto ci porta un po' più vicini. Adesso lo metto in pila, così gli altri conciatori possono cominciare a lavorare.$B$BGrazie ancora, $N. E se ti capitano altre pile di heavy leather, sai dove trovarmi.",
  en_title = "The Horde Needs More Heavy Leather!",
  en_obj = "Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar.",
}
T[8590] = {
  title = "L'Orda Ha Bisogno di Thick Leather!",
  desc = "Sono contenta che tu abbia deciso di parlarmene, $C. A quanto pare l'Orda si prepara a pieno ritmo per l'imminente Guerra di Ahn'Qiraj, ma la nostra parte, tu e io, dobbiamo ancora farla.$B$BMi hanno incaricata di raccogliere un gran numero di pelli di thick leather, che serviranno per ogni genere di materiale bellico, e mi serve il tuo aiuto per procurarle. Se sceglierai di darmi una mano, avrai onore e la gratitudine dell'Orda. Lo farai?",
  obj = "Porta 10 pezzi di Thick Leather a Sergeant Umala in Valley of Spirits, a Orgrimmar.",
  progress = "$C, sei già $Gtornato:tornata; coi dieci pezzi di thick leather di cui avevamo parlato?",
  reward = "Ottimo lavoro, $C. Sono sicura che queste pelli di thick leather serviranno a rinforzare gli zeppelin e a fabbricare armature e armi di ogni genere. Hai la mia gratitudine, e quella dell'Orda. Se nei tuoi viaggi trovi altro thick leather, torna da me, e che la fortuna ti accompagni.",
  en_title = "The Horde Needs Thick Leather!",
  en_obj = "Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar.",
}
T[8591] = {
  title = "L'Orda Ha Bisogno di Altro Thick Leather!",
  progress = "$C, come vedi, di thick leather devo raccoglierne ancora. Ti chiedo di nuovo una mano, e ti prometto che, se porterai a termine il compito, i tuoi sforzi ti verranno riconosciuti.$B$BIl tempo stringe! Torna da me con il thick leather, così potremo finire i preparativi e partire per la guerra, $Geroe:eroina;!",
  reward = "Ce l'hai fatta, $N, lo sapevo che ci saresti $Griuscito:riuscita;! Ancora una volta, grazie a nome di tutta l'Orda. Abbiamo notato i tuoi sforzi, e li apprezziamo molto. E se hai altro thick leather da donare, portamelo qui.$B$BLok'tar Ogar, $C!",
  en_title = "The Horde Needs More Thick Leather!",
  en_obj = "Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar.",
}
T[8592] = {
  title = "Tiara of the Oracle",
  desc = "Gli Imperatori Gemelli... i loro sussurri non si fermano mai, e lentamente mi stanno togliendo il senno. Mi deridono, perché sanno che non posso spingermi più a fondo nel loro dominio per salvare mio fratello Arygos.$B$BNelle mie visioni vedo i loro volti mostruosi, adorni di potenti corone. Ma avrò la mia vendetta... trasmuterò questi simboli del potere Qiraji in altri che servano meglio ai nostri bisogni.$B$BPortami i componenti che mi servono, $N, e ti darò un copricapo dal potere senza pari.",
  obj = "Porta la Vek'nilash's Circlet, 2 Idols of the Sage, 5 Silver Scarabs e 5 Bone Scarabs ad Andorgos ad Ahn'Qiraj. Devi anche raggiungere la reputazione Amichevole con la Brood of Nozdormu per completare questa missione.",
  progress = "$N, mi hai portato i componenti che ti ho chiesto?",
  reward = "Ce l'hai fatta! Gli Imperatori Gemelli hanno smesso di sussurrare.$B$BPrendi questo, è la tua ricompensa. Basterà vederlo perché la paura entri nel cuore dei Qiraji... ricorderà loro i capi caduti e $Gil:la; mortale che li ha uccisi.",
}
T[8593] = {
  title = "Trousers of the Oracle",
  desc = "Cerchi di dimostrare il tuo valore alla mia specie, mortale? Molto bene: forse possiamo aiutarci a vicenda.$B$BOuro, l'antico verme delle sabbie, è un essere dal potere leggendario. Si dice che l'abbia creato l'Old God in persona, come una parodia della vita.$B$BLa sua pelle è innaturale... spessa, quasi impenetrabile, eppure così flessibile da permettergli di muoversi con la velocità e la grazia di una creatura molto più piccola.$B$BPortami un campione di quella pelle insieme ad altri componenti minori, e ti realizzerò dei gambali di grande potere.",
  obj = "Porta l'Ouro's Intact Hide, 2 Idols of Life, 5 Gold Scarabs e 5 Clay Scarabs a Kandrostrasz dentro Ahn'Qiraj. Per completare questa quest devi anche raggiungere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Hai portato i componenti che mi servono, $N?",
  reward = "Sì... la pelle del verme sarà un ottimo strato protettivo. Insieme alle parti più resistenti dei Qiraji che abbiamo distrutto per arrivare fin qui, dovrebbe diventare un pezzo d'armatura formidabile. Possa aiutarti ad affrontare gli orrori indicibili che ti attendono là dentro!",
}
T[8594] = {
  title = "Mantle of the Oracle",
  desc = "Fra noi si dice che le elaborate armature da spalla delle razze mortali siano nate dal tentativo di imitare le ali di un drago.$B$BPortami le manette che portano i più alti capi Qiraji e ne farò un paio di spallacci più terrificanti persino delle ali di Nefarian in persona!",
  obj = "Porta le Qiraji Bindings of Command, 2 Idols of Rebirth, 5 Silver Scarabs e 5 Ivory Scarabs ad Andorgos ad Ahn'Qiraj. Devi anche raggiungere la reputazione Neutrale con la Brood of Nozdormu per completare questa missione.",
  progress = "I componenti che mi servono: li hai raccolti?",
  reward = "Con i materiali che mi hai portato e con le scaglie dei nostri nemici Qiraji caduti creo per te questi spallacci, mortale. Che ti diano la protezione di cui hai bisogno, e che la loro vista metta paura ai nostri avversari.",
}
T[8595] = {
  title = "Campioni Mortali",
  progress = "Per un mortale uccidere un signore dei Qiraji è un'impresa notevole, $N, ma sono tanti e potenti. Continua a sconfiggerli e dimostra il tuo valore di $Gnostro campione:nostra campionessa;.",
  reward = "Continui a servirci bene, $N, e il nostro patto resta valido.",
}
T[8596] = {
  title = "Footwraps of the Oracle",
  desc = "La magia Qiraji è antica e potente, e i più forti fra i qiraji brandiscono oggetti di una potenza tale da far esitare persino un drago.$B$BPortami le manette del comando qiraji, insieme ad altri componenti minori, e ti creerò un paio di stivali potenti.$B$BTi torneranno utili nella lotta contro il nemico.",
  obj = "Porta le Qiraji Bindings of Command, 2 Idols of Death, 5 Bronze Scarabs e 5 Gold Scarabs a Kandrostrasz ad Ahn'Qiraj. Questa missione richiede anche la reputazione Neutrale con la Brood of Nozdormu.",
  progress = "Allora, $N, hai gli oggetti che ti ho chiesto?",
  reward = "Hai fatto un buon lavoro, $N, e hai dimostrato di non essere $Gun comune mortale:una comune mortale;.$B$BTe li consegno, certo che ti aiuteranno a schiacciare gli spregevoli qiraji.",
}
T[8597] = {
  title = "Draconic for Dummies",
  desc = "Lo sapevo che quel libro un giorno mi sarebbe tornato utile! Per fortuna ho avuto l'ingegno e la lungimiranza di nasconderlo in un posto sicuro.$B$BNon preoccuparti, è un luogo dove nessuno potrebbe mai sperare di trovarlo! La prima volta, solo per arrivarci, mi è servito un girocottero. Al ritorno, purtroppo, mi sono schiantato sulla spiaggia. Ed è proprio grazie a quell'incidente che ho ottenuto questi poteri psichici supergnomeschi!$B$BCerca il relitto del mio girocottero da qualche parte sulla Land's End Beach, e da lì nuota verso sud! Quando vedrai il posto, lo riconoscerai!",
  obj = "Trova il libro di Narain Soothfancy, sepolto su un'isola nei South Seas.",
  reward = "Il libro è sparito! In cima al dirt mound c'è un biglietto.",
}
T[8598] = {
  title = "rIsCaTt0",
  desc = "<Il biglietto è scritto con caratteri di ogni tipo, incollati sulla pergamena.>$B$BAbbiamo il tuo prezioso libro, gnomo. Se vuoi rivederlo, farai esattamente come ti diciamo.$B$B<Seguono 3 pagine di istruzioni dettagliate.>$B$BPorta i soldi e vieni da solo!",
  obj = "Riporta la Ransom Letter a Narain Soothfancy a Tanaris.",
  progress = "Ehi, che succede?",
  reward = "<Narain si fa rosso acceso in viso.>$B$BLibrapire il mio... libro, eh!? Gli faccio vedere io cosa vuol dire mettersi contro uno gnomo sensitivo!",
}
T[8599] = {
  title = "Canzone d'Amore per Narain",
  desc = "Non ricevo spesso visite. Anzi, l'ultima volta che è venuto a trovarmi qualcuno è stato quando ho salvato quel caro, dolce gnomo dai rottami della macchina volante precipitata.$B$B<Meridith fissa il vuoto, persa in un ricordo.>$B$BLo conosci? Narain? Narain Soothfancy? Oh, per me sarebbe così importante se qualcuno gli portasse un mio messaggio. Devo dirgli cosa provo! È amore, lo so! Lo so e basta!$B$BPotresti portare tu un messaggio a Narain? Te ne sarei debitrice per sempre!",
  obj = "Porta la lettera d'amore di Meridith a Narain Soothfancy a Tanaris.",
  progress = "Puzzi di pesce!",
  reward = "Cosa!?$B$B<Narain comincia ad agitarsi.>$B$BBe', ehm... E che cosa dovrei farci??? È un pesce! UN PESCE, ti dico! Io sono uno gnomo. Non potrebbe mai funzionare.",
}
T[8600] = {
  title = "L'Orda Ha Bisogno di Rugged Leather!",
  desc = "Trovo che conti più come il coltello sta nel palmo che quanto sia affilato. Anche la lama più smussata taglia, se premi nel modo giusto, non credi, $C? Ma tu e io questi problemi non li abbiamo, visto che le nostre lame le teniamo più affilate di tutte, vero?$B$BBe', poco importa: ho un compito per te. Al servizio dell'Orda, e per dare il tuo contributo alla guerra di Ahn'Qiraj, voglio che tu mi porti un certo numero di pelli di rugged leather. Lo farai, no?",
  obj = "Porta 10 pezzi di Rugged Leather a Doctor Serratus in Valley of Spirits, a Orgrimmar.",
  progress = "Non può volerci tanto a tagliarmi dieci pezzi di rugged leather! Forse dovresti affilare lo skinning knife? O magari mi sbaglio, e li hai lì nella sacca?",
  reward = "Molto bene: mi pare che tu abbia fatto un lavoro piuttosto decente, anche se alcune pelli sono un po' sfilacciate ai bordi. Poco importa, il compito è fatto e la ricompensa te la sei guadagnata. Se ti capita un'altra pila di rugged leather, portamela senza indugio.",
  en_title = "The Horde Needs Rugged Leather!",
  en_obj = "Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar.",
}
T[8601] = {
  title = "L'Orda Ha Bisogno di Altro Rugged Leather!",
  progress = "I preparativi per l'imminente guerra di Ahn'Qiraj vanno avanti, $C. Però, per essere certi di non restare indietro, o almeno che non sia colpa mia, voglio che tu mi porti un'altra pila di rugged leather. Ti sarei molto grato se te ne occupassi subito, $N.",
  reward = "Esercizio, esercizio, esercizio. In questo mondo, un coltello ben affilato e la capacità di usarlo ti porteranno lontano, $N. A quanto pare, queste pelli hanno i bordi migliori dell'ultima volta. Hai comprato un coltello nuovo?$B$BComunque sia, ti ringraziamo per i tuoi sforzi. La tua donazione è stata registrata, e ti assicuro che sarà usata bene. Se ti capita altro rugged leather, torna da me, perché probabilmente mi servirà.",
  en_title = "The Horde Needs More Rugged Leather!",
  en_obj = "Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar.",
}
T[8602] = {
  title = "Stormcaller's Pauldrons",
  desc = "Fra noi si dice che le elaborate armature da spalla delle razze mortali siano nate dal tentativo di imitare le ali di un drago.$B$BPortami le manette che portano i più alti capi Qiraji e ne farò un paio di spallacci più terrificanti persino delle ali di Nefarian in persona!",
  obj = "Porta le Qiraji Bindings of Dominance, 2 Idols of Life, 5 Gold Scarabs e 5 Crystal Scarabs ad Andorgos ad Ahn'Qiraj. Devi anche raggiungere la reputazione Neutrale con la Brood of Nozdormu per completare questa missione.",
  progress = "I componenti che mi servono: li hai raccolti?",
  reward = "Con i materiali che mi hai portato e con le scaglie dei nostri nemici Qiraji caduti creo per te questi spallacci, mortale. Che ti diano la protezione di cui hai bisogno, e che la loro vista metta paura ai nostri avversari.",
}
T[8603] = {
  title = "Vestments of the Oracle",
  desc = "Sotto Ahn'Qiraj, l'innominabile Old God si sta lentamente risvegliando dal sonno. Il terribile destino che incombe su Azeroth potrebbe compiersi fra qualche giorno come fra qualche anno; per esseri potenti come lui il tempo non ha significato.$B$BQuando le stelle saranno propizie, si scaglierà con una collera terribile contro ogni essere vivente. Prima di allora devi trovarlo e scoprire come porre fine alla sua esistenza.$B$BFallo, e portami un pezzo del suo guscio: ti concederò un'armatura che nessun mortale ha mai indossato... un'armatura degna di chi ha ucciso un dio!",
  obj = "Porta l'Husk of the Old God, 2 Idols of Death, 5 Stone Scarabs e 5 Crystal Scarabs a Vethsera dentro Ahn'Qiraj. Devi anche raggiungere la reputazione Onorato con la Brood of Nozdormu per completare questa quest.",
  progress = "Il temibile C'Thun attende, dormiente, nella sua dimora ad Ahn'Qiraj.",
  reward = "Non credevo che saresti $Gtornato:tornata; da quest'impresa, $N.$B$BHai compiuto un destino più grande di quello della maggior parte degli esseri immortali.$B$BUccidendo C'Thun non hai soltanto salvato tutta Azeroth: hai alterato l'equilibrio di eventi cosmici che vanno oltre la tua comprensione.$B$BAccetta questi paramenti, simbolo della gloria e del fardello che le tue azioni porteranno con sé.$B$BPossa il loro potere aiutarti nelle sfide che ti attendono, $Guccisore:uccisora; di dei!",
}
T[8604] = {
  title = "L'Orda Ha Bisogno di Wool Bandages!",
  desc = "Salute, $C. In vista della guerra di Ahn'Qiraj, sono io a coordinare qui la raccolta di wool bandages per l'Orda. Sul campo, purtroppo, i nostri soldati non possono contare sul fatto che ci sia un guaritore a tenerli in vita: credimi, lo so per esperienza. Ecco perché stiamo preparando per loro tutti questi first aid kits.$B$BSe hai tempo, mi servono molte wool bandages. Portamele qui e farò in modo che tu venga $Gricompensato:ricompensata; come si deve.",
  obj = "Porta 20 Wool Bandages a Healer Longrunner nella Valley of Spirits a Orgrimmar.",
  progress = "Ah, $C, sei già $Gtornato:tornata; con le wool bandages?",
  reward = "Grazie, $C, a nome mio e dell'Orda. Se vuoi dare ancora una mano allo sforzo bellico, le altre wool bandages che trovi portamele qui. Fino ad allora, che i tuoi antenati veglino su di te!",
  en_title = "The Horde Needs Wool Bandages!",
  en_obj = "Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar.",
}
T[8605] = {
  title = "L'Orda Ha Bisogno di Altre Wool Bandages!",
  progress = "Che piacere rivederti, $C. Qui i preparativi per lo sforzo bellico vanno avanti, e per raccogliere bende di wool ho ancora bisogno di tutto l'aiuto che puoi darmi. Qualunque contributo sarà molto apprezzato. Spero solo che i nostri sforzi bastino. Sui campi di battaglia del passato ho perso troppe anime nobili: devo fare tutto quello che è in mio potere perché non succeda più.",
  reward = "Sei $Gun:una; $C d'onore, $N! Farò in modo che queste bende finiscano nelle mani giuste. Grazie, a nome mio e dell'Orda.$B$BVa' in pace, e se ti avanzano altre bende di wool torna da me. Qui ci serve tutto l'aiuto possibile.",
  en_title = "The Horde Needs More Wool Bandages!",
  en_obj = "Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar.",
}
T[8606] = {
  title = "Esca!",
  desc = "Ci sono! Ecco cosa facciamo. Riempio un sacco di sassi e la consegna la fai tu. Lo so, c'era scritto che dovevo consegnarlo io, e lo farò — più o meno.$B$B<Narain ti squadra da capo a piedi.>$B$BSì, andrai benissimo. Prendi questo turbante, la tunica e il sacco di sassi, e vai al punto di consegna a Winterspring.$B$BTutto quello che ti serve l'ho messo in questo kit speciale. Quando si presentano a ritirare la merce, falli fuori! Così imparano a mettersi contro Narain!",
  obj = "Narain Soothfancy a Tanaris vuole che tu vada a Winterspring e lasci la Bag of Gold al punto di consegna indicato dai librapitori.",
  reward = "Forse questi librapitori li abbiamo sottovalutati.",
}
T[8607] = {
  title = "L'Orda Ha Bisogno di Mageweave Bandages!",
  desc = "Se mi rivolgi la parola è per aiutarmi con la raccolta che mi hanno affidato, immagino? Bene! Voglio che tu raccolga un buon numero di mageweave bandages, con qualunque mezzo, e dico proprio qualunque. Fresche sarebbero gradite, ma non indispensabili. Portamele qui, $C, e mi assicurerò di persona che tu venga $Gricompensato:ricompensata; come si deve.",
  obj = "Porta 20 Mageweave Bandages a Lady Callow nella Valley of Spirits a Orgrimmar.",
  progress = "Non fallire e non farmi fare brutta figura, $C! Torna qui al più presto con le mageweave bandages di cui abbiamo parlato.",
  reward = "Sorprendente, eppure accettabile. Forse ho sottovalutato le tue 'capacità', $C. Forse. Per un compito così semplice sarai $Gricompensato:ricompensata; ben più del dovuto. Ma non montarti la testa. Se vuoi davvero dimostrare quanto vali, dovresti andare là fuori a prendermi un altro pacco di mageweave bandages.",
  en_title = "The Horde Needs Mageweave Bandages!",
  en_obj = "Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.",
}
T[8608] = {
  title = "L'Orda Ha Bisogno di Altre Mageweave Bandages!",
  progress = "Sei $Gtornato:tornata;? Interessante. Come vedi, la mia raccolta per lo 'sforzo bellico' di Ahn'Qiraj continua. Ho quindi bisogno che tu torni a raccogliermi una pila di mageweave bandages. Attendo il tuo ritorno, $C.",
  reward = "Straordinario, $C, ci sei $Griuscito:riuscita; davvero un'altra volta! Be', dicono che io sappia scegliere bene chi mettere al mio servizio. Molto bene, il tuo contributo è stato annotato, e riceverai i benefici sociali che i tuoi sforzi ti hanno procurato. Però, se vuoi davvero dimostrare quanto vali, ti suggerisco di tornare là fuori a raccogliere ancora un altro pacco di mageweave bandages.",
  en_title = "The Horde Needs More Mageweave Bandages!",
  en_obj = "Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.",
}
T[8609] = {
  title = "L'Orda Ha Bisogno di Runecloth Bandages!",
  desc = "Pare inevitabile che l'Orda e l'Alleanza vadano incontro alla guerra ad Ahn'Qiraj. Eppure, cosa sorprendente, non si combatteranno fra loro: combatteranno contro i silithid e qualunque forza li controlli. E sorprende altrettanto vedere entrambi gli schieramenti fare la loro parte per raccogliere ciò che serve a combattere e vincere questa guerra.$B$BRaccolgo bende di runecloth da distribuire ai soldati, ma senza aiuto non ce la farò, e spero di poter contare sul tuo. Puoi aiutarmi, $C?",
  obj = "Porta 20 Runecloth Bandages a Stoneguard Clayhoof in Valley of Spirits, a Orgrimmar.",
  progress = "La guerra arriverà presto, credo, $C. Ti ringrazio del tempo e dell'impegno che metti nell'aiutarci a raccogliere. Sei $Gtornato:tornata; perché ti sei $Gprocurato:procurata; le bende di runecloth di cui abbiamo parlato?",
  reward = "Fai onore all'Orda, $C. Grazie per l'impegno, lo apprezziamo! Ora dovrò mettere via queste bende nuove e rifare il conto, per vedere quanto siamo vicini all'obiettivo. Se vuoi, puoi raccogliere altre bende di runecloth e riportarmele qui.",
  en_title = "The Horde Needs Runecloth Bandages!",
  en_obj = "Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar.",
}
T[8610] = {
  title = "L'Orda Ha Bisogno di Altre Runecloth Bandages!",
  progress = "Si avvicina sempre di più il momento in cui ci getteremo a capofitto nell'incendio di Ahn'Qiraj, $Gsacerdote:sacerdotessa;. Ma prima dobbiamo raccogliere le forze e prepararci, se vogliamo sopravvivere all'assalto degli insetti e dei loro padroni.$B$BSe sei di nuovo qui, vorrai di sicuro dare altre bende di runecloth allo sforzo di guerra, vero? Ti prego, fallo appena puoi e torna da me ancora una volta.",
  reward = "È un gesto di grande generosità, $N, e probabilmente salverà la vita a molti combattenti ad Ahn'Qiraj. Grazie: sappi che l'Orda ti è grata per quello che hai donato. Se fabbrichi o trovi altre bende di runecloth, ti prego, pensa a portarmele qui.",
  en_title = "The Horde Needs More Runecloth Bandages!",
  en_obj = "Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar.",
}
T[8611] = {
  title = "L'Orda Ha Bisogno di Lean Wolf Steaks!",
  desc = "Non me ne sto qui solo per prendermi una bella abbronzatura, $C. Ci sono preparativi di guerra da fare. Se vogliamo schiacciare quegli insetti ad Ahn'Qiraj dobbiamo essere pronti, e anche col cibo!$B$BMi hanno messa qui a raccogliere e salare lean wolf steaks per la guerra in arrivo. Ma visto che io devo restare a occuparmi di tutto, ho bisogno che tu vada là fuori, uccida qualche lupo, ne cucini la carne per farne lean wolf steaks e me le riporti. Hai capito tutto?",
  obj = "Porta 20 Lean Wolf Steaks a Bloodguard Rawtar in Valley of Spirits, a Orgrimmar.",
  progress = "Sei già $Gtornato:tornata; con quelle lean wolf steaks, $C? Non m'importa se sono stracotte o crude: basta che siano saporite e che me le porti in fretta!",
  reward = "Ok, questa pila di carne mi sembra buona. Le salo, le metto via, e speriamo che restino abbastanza fresche da potersi ancora mangiare quando sarà il momento.$B$BGrazie del contributo, $C. Pensi di riuscire a portarmene un altro carico?",
  en_title = "The Horde Needs Lean Wolf Steaks!",
  en_obj = "Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar.",
}
T[8612] = {
  title = "L'Orda Ha Bisogno di Altre Lean Wolf Steaks!",
  progress = "Come vedi, $C, dobbiamo mettere da parte altro cibo per i soldati. Non so se sei mai $Gstato:stata; in guerra, ma passato lo shock iniziale del campo di battaglia ti può venire una bella fame. L'ultima volta hai fatto un buon lavoro, quindi per un'altra pila di quelle lean wolf steaks mi aspetto che te la cavi altrettanto bene, se non un po' più in fretta.",
  reward = "A giudicare dall'odore, tu, o qualcuno che conosci, sei proprio $Gun gran cuoco:una gran cuoca;, $N. Queste lean wolf steaks mi fanno venire l'acquolina in bocca: se ne sparisce qualcuna, immagino che nessuno se ne accorgerà. Comunque, bel lavoro. Farò in modo che qualcuno le metta via per bene, così non andranno troppo a male.$B$BSe ne trovi altre, sai dove cercarmi.",
  en_title = "The Horde Needs More Lean Wolf Steaks!",
  en_obj = "Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar.",
}
T[8613] = {
  title = "L'Orda Ha Bisogno di Spotted Yellowtail!",
  desc = "Essere bella giornata per pescare, no pensi, mon? Meglio così, perché a me sembrare che servire tanto pesce. L'Orda chiedere a me di pensare io a raccogliere per loro una tonnellata di spotted yellowtail: loro dire che servire per la guerra che preparare ad Ahn'Qiraj. Io dire a loro che fare il meglio che posso, e così a me servire un po' di aiuto. Tu aiutare me, $C?",
  obj = "Porta 20 Spotted Yellowtail a Fisherman Lin'do, in Valley of Spirits di Orgrimmar.",
  progress = "$GTornato:Tornata; già con lo spotted yellowtail, $C? Tu ricordato di cucinarlo bene? Ai soldati sotto il sole caldo del deserto noi non servire pesce crudo, puoi starne $Gsicuro:sicura;.",
  reward = "Oh sì, questa essere roba buona. Io impacchettare tutto per bene, così niente andare sprecato. Grazie a te per aiutare me così. Con tutto questo spotted yellowtail, io pensare che tu essere $Gun pescatore:una pescatrice; numero uno. E se a te capita di pescare e cucinare ancora, tu portare qui a me; io fare in modo che tutti sapere che tu fatto questo!",
  en_title = "The Horde Needs Spotted Yellowtail!",
  en_obj = "Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar.",
}
T[8614] = {
  title = "L'Orda Ha Bisogno di Altro Spotted Yellowtail!",
  progress = "Come vedi, a noi servire ancora tanti pescetti. I combattenti della prossima Guerra di Ahn'Qiraj dovere mangiare tanto, così a me servire tutto lo spotted yellowtail che posso avere. Tu pescare, cucinare e portare qui a me, e io dare a te i miei ringraziamenti e quelli dell'Orda.",
  reward = "Questa essere la pesca migliore finora, $N! Lavoro buono e onesto, questo. E pure niente lische! Grazie a te per questo spotted yellowtail, mon. Se tu cucinare ancora, torna presto!",
  en_title = "The Horde Needs More Spotted Yellowtail!",
  en_obj = "Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar.",
}
T[8615] = {
  title = "L'Orda Ha Bisogno di Baked Salmon!",
  desc = "Lo sforzo bellico per Ahn'Qiraj è un'impresa immensa, $C. Ogni cosa che raccogliamo qui, il metallo per le armi come il cibo da mangiare, conta allo stesso modo: se non mangi da giorni, nel momento decisivo non avrai la forza di sollevare l'ascia.$B$BPer questo raccogliamo tutto il cibo possibile. Io raccolgo il baked salmon, un piatto scelto perché nutre e si conserva bene. Mi aiuteresti in questo compito, $C?",
  obj = "Porta 20 Baked Salmon a Chief Sharpclaw, in Valley of Spirits di Orgrimmar.",
  progress = "Se li provochi, gli sprite darters possono essere bestiole pericolose. Fai attenzione quando hai a che fare con loro, $C, e ancora di più con gli elfi della notte della zona: quegli sciocchi seccatori, di solito, si nascondono anche loro nelle foreste.$B$BQuando avrai raccolto abbastanza ali, fammelo sapere: ti ricompenserò come si deve, puoi contarci!",
  reward = "Magnifico, $C! Queste andranno benissimo. Ce ne sono abbastanza per farne un mantello a Korrin, e forse anche di più! Grazie.$B$BSpero che il viaggio non sia stato troppo pericoloso? La zona di Feralas non è nota per la sua clemenza, ma è chiaro che te la sei cavata.$B$BGrazie ancora, $C.",
  en_title = "The Horde Needs Baked Salmon!",
  en_obj = "Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar.",
}
T[8616] = {
  title = "L'Orda Ha Bisogno di Altro Baked Salmon!",
  progress = "L'ultima partita di baked salmon che hai donato allo sforzo bellico aveva un aspetto delizioso, $C: lo ammetto, sono stato tentato di tenermene un po'. Come vedi, la quota non l'abbiamo ancora raggiunta. Spero che tu sia $Gtornato:tornata; perché hai con te un'altra scorta di baked salmon",
  reward = "Il tempo e le energie che doni allo sforzo bellico vanno ben oltre il dovuto, $N, e ti assicuro che le tue fatiche non sono passate inosservate. Ti ringrazio a nome mio e dell'Orda. Se cuoci un'altra partita, ti prego, torna da me.",
  en_title = "The Horde Needs More Baked Salmon!",
  en_obj = "Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar.",
}
T[8617] = {
  title = "L'Orda Ha Bisogno di Singed Corestones!",
  desc = "È arrivato il momento di contribuire allo sforzo bellico di Ahn'Qiraj, $C. I giorni beati passati a oziare sono finiti. Ora tocca a te servire me e l'Orda, e ti assicuro che non sono indulgente quanto il Capoguerra.$B$BRadunerai le tue forze, una gilda se ce l'hai, e invaderai il Molten Core. Là dentro scoprirai che gli abitanti del posto hanno delle singed corestones. Riportamene in gran quantità.",
  obj = "Porta 50 singed corestones a General Zog a Durotar.",
}
T[8619] = {
  title = "Morndeep l'Anziano",
  reward = "Fa piacere sapere che la gente di questa terra onora ancora le razze antiche. Ti auguro ogni bene, $N, e ti offro questo pegno...",
  en_title = "Morndeep the Elder",
}
T[8620] = {
  title = "L'Unica Prescrizione",
  desc = "Me lo dovevo immaginare. Il mio acerrimo nemico, Doctor Weavil, ne ha combinata un'altra delle sue! E ora, grazie al tuo fallimento a Winterspring, Doctor Weavil ha distrutto il mio libro! E adesso come lo salvi il mondo, $Geroe:eroina;?$B$BIl biglietto che mi è arrivato diceva che l'unica copia conosciuta di \"Draconic for Dummies: Volume II\" è stata strappata in 8 parti e dispersa ai quattro venti! Se in qualche modo riesci a ritrovare i capitoli mancanti, rimettili insieme con questa rilegatura magica e torna da me.",
  obj = "Recupera gli 8 capitoli perduti di Draconic for Dummies, uniscili con la Magical Book Binding e riporta il libro completo di Draconic for Dummies: Volume II a Narain Soothfancy a Tanaris.",
  progress = "Anch'io mi metto i pantaloni come te — una gamba alla volta. Solo che io, coi pantaloni addosso, faccio arcanite buoys. Arcanite buoys, baby!",
  reward = "Fantastico! Non ci credo che ti sia $Gpreso:presa; tutto questo disturbo! Ma sei una specie di macchina? Io, al tuo posto, probabilmente avrei lasciato implodere il mondo.$B$BMi levo il turbante davanti a te, $Gsignore:signora;. E nessuna buona azione deve restare senza ricompensa.",
}
T[8621] = {
  title = "Stormcaller's Footguards",
  desc = "La magia Qiraji è antica e potente, e i più forti fra i qiraji brandiscono oggetti di una potenza tale da far esitare persino un drago.$B$BPortami le manette del dominio qiraji, insieme ad altri componenti minori, e ti creerò un paio di stivali potenti.$B$BTi torneranno utili nella lotta contro il nemico.",
  obj = "Porta le Qiraji Bindings of Dominance, 2 Idols of the Sage, 5 Bronze Scarabs e 5 Clay Scarabs a Kandrostrasz ad Ahn'Qiraj. Questa missione richiede anche la reputazione Neutrale con la Brood of Nozdormu.",
  progress = "Allora, $N, hai gli oggetti che ti ho chiesto?",
  reward = "Hai fatto un buon lavoro, $N, e hai dimostrato di non essere $Gun comune mortale:una comune mortale;.$B$BTe li consegno, certo che ti aiuteranno a schiacciare gli spregevoli qiraji.",
}
T[8622] = {
  title = "Stormcaller's Hauberk",
  desc = "Sotto Ahn'Qiraj, l'innominabile Old God si sta lentamente risvegliando dal sonno. Il terribile destino che incombe su Azeroth potrebbe compiersi fra qualche giorno come fra qualche anno; per esseri potenti come lui il tempo non ha significato.$B$BQuando le stelle saranno propizie, si scaglierà con una collera terribile contro ogni essere vivente. Prima di allora devi trovarlo e scoprire come porre fine alla sua esistenza.$B$BFallo, e portami un pezzo del suo guscio: ti concederò un'armatura che nessun mortale ha mai indossato... un'armatura degna di chi ha ucciso un dio!",
  obj = "Porta il Carapace of the Old God, 2 Idols of the Sage, 5 Silver Scarabs e 5 Bone Scarabs a Vethsera dentro Ahn'Qiraj. Devi anche raggiungere la reputazione Onorato con la Brood of Nozdormu per completare questa quest.",
  progress = "Il temibile C'Thun attende, dormiente, nella sua dimora ad Ahn'Qiraj.",
  reward = "Non credevo che saresti $Gtornato:tornata; da quest'impresa, $N.$B$BHai compiuto un destino più grande di quello della maggior parte degli esseri immortali.$B$BUccidendo C'Thun non hai soltanto salvato tutta Azeroth: hai alterato l'equilibrio di eventi cosmici che vanno oltre la tua comprensione.$B$BAccetta questo pettorale, simbolo della gloria e del fardello che le tue azioni porteranno con sé.$B$BPossa il suo potere aiutarti nelle sfide che ti attendono, $Guccisore:uccisora; di dei!",
}
T[8623] = {
  title = "Stormcaller's Diadem",
  desc = "Gli Imperatori Gemelli... sussurrano senza sosta, e a poco a poco mi stanno facendo perdere la ragione. Si prendono gioco di me, perché sanno che non posso spingermi più a fondo nel loro dominio per salvare mio fratello Arygos.$B$BLi vedo nelle visioni, quei volti mostruosi ornati di corone potenti. Ma mi vendicherò... Trasmuterò questi simboli del potere Qiraji in qualcosa di più adatto a ciò che ci serve.$B$BPortami i componenti che mi servono, $N, e avrai da me un copricapo dal potere senza pari.",
  obj = "Porta il Vek'lor's Diadem, 2 Idoli della Rinascita, 5 Stone Scarabs e 5 Crystal Scarabs ad Andorgos ad Ahn'Qiraj. Per completare questa quest devi anche ottenere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Mi hai portato i componenti che ti avevo chiesto, $N?",
  reward = "Ci sei $Griuscito:riuscita;! Gli Imperatori Gemelli hanno smesso di sussurrare.$B$BPrendi questo, è la tua ricompensa. Basterà vederlo per mettere paura nel cuore dei Qiraji... gli ricorderà i loro capi caduti e $Gil:la; mortale che li ha uccisi.",
}
T[8624] = {
  title = "Stormcaller's Leggings",
  desc = "Vuoi dimostrare il tuo valore alla mia razza, mortale? Molto bene: forse possiamo esserci utili a vicenda.$B$BOuro, l'antico sandworm, è un essere dal potere leggendario. Si dice che l'abbia creato l'Old God in persona, come una parodia della vita.$B$BHa una pelle innaturale... spessa, quasi impenetrabile, eppure flessibile, che gli permette di muoversi con la velocità e la grazia di una creatura molto più piccola.$B$BPortami un campione di quella pelle, insieme ad altri componenti minori, e ti creerò dei gambali di grande potere.",
  obj = "Porta la Skin of the Great Sandworm, 2 Idols of Strife, 5 Bronze Scarabs e 5 Ivory Scarabs a Kandrostrasz dentro Ahn'Qiraj. Per completare questa missione devi anche raggiungere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Allora, $N, hai portato i componenti che ti ho chiesto?",
  reward = "Sì... la pelle del verme farà da ottimo strato protettivo e, unita alle parti più robuste dei Qiraji che abbiamo distrutto lungo la strada, dovrebbe diventare un pezzo d'armatura formidabile. Che ti aiuti ad affrontare gli orrori indicibili che attendono là dentro!",
}
T[8625] = {
  title = "Enigma Shoulderpads",
  desc = "Fra noi si dice che le armature da spalla ornate delle razze mortali siano nate dal tentativo di imitare le ali di un drago.$B$BPortami le manette che indossano i capi Qiraji di rango più alto, e ne ricaverò un paio di spallacci più terrificanti persino delle ali di Nefarian in persona!",
  obj = "Porta le Qiraji Bindings of Dominance, 2 Idoli della Rinascita, 5 Silver Scarabs e 5 Ivory Scarabs ad Andorgos ad Ahn'Qiraj. Per completare questa quest devi anche ottenere la reputazione Neutrale con la Brood of Nozdormu.",
  progress = "Li hai raccolti, i componenti che mi servono?",
  reward = "Con i materiali che mi hai portato e con le scaglie dei nostri avversari Qiraji caduti, ti preparo questi spallacci, mortale. Che ti diano la protezione che ti serve, e che ai nostri nemici basti vederli per avere paura.",
}
T[8626] = {
  title = "Striker's Footguards",
  desc = "La magia Qiraji è antica e potente, e i più forti fra i qiraji brandiscono oggetti di una potenza tale da far esitare persino un drago.$B$BPortami le manette del comando qiraji, insieme ad altri componenti minori, e ti creerò un paio di stivali potenti.$B$BTi torneranno utili nella lotta contro il nemico.",
  obj = "Porta le Qiraji Bindings of Command, 2 Idols of Life, 5 Stone Scarabs e 5 Bone Scarabs a Kandrostrasz ad Ahn'Qiraj. Questa missione richiede anche la reputazione Neutrale con la Brood of Nozdormu.",
  progress = "Allora, $N, hai gli oggetti che ti ho chiesto?",
  reward = "Hai fatto un buon lavoro, $N, e hai dimostrato di non essere $Gun comune mortale:una comune mortale;.$B$BTe li consegno, certo che ti aiuteranno a schiacciare gli spregevoli qiraji.",
}
T[8627] = {
  title = "Avenger's Breastplate",
  desc = "Sotto Ahn'Qiraj, l'innominabile Old God si sta lentamente risvegliando dal sonno. Il terribile destino che incombe su Azeroth potrebbe compiersi fra qualche giorno come fra qualche anno; per esseri potenti come lui il tempo non ha significato.$B$BQuando le stelle saranno propizie, si scaglierà con una collera terribile contro ogni essere vivente. Prima di allora devi trovarlo e scoprire come porre fine alla sua esistenza.$B$BFallo, e portami un pezzo del suo guscio: ti concederò un'armatura che nessun mortale ha mai indossato... un'armatura degna di chi ha ucciso un dio!",
  obj = "Porta il Carapace of the Old God, 2 Idols of the Sage, 5 Silver Scarabs e 5 Bone Scarabs a Vethsera dentro Ahn'Qiraj. Devi anche raggiungere la reputazione Onorato con la Brood of Nozdormu per completare questa quest.",
  progress = "Il temibile C'Thun attende, dormiente, nella sua dimora ad Ahn'Qiraj.",
  reward = "Non credevo che saresti $Gtornato:tornata; da quest'impresa, $N.$B$BHai compiuto un destino più grande di quello della maggior parte degli esseri immortali.$B$BUccidendo C'Thun non hai soltanto salvato tutta Azeroth: hai alterato l'equilibrio di eventi cosmici che vanno oltre la tua comprensione.$B$BAccetta questo pettorale, simbolo della gloria e del fardello che le tue azioni porteranno con sé.$B$BPossa il suo potere aiutarti nelle sfide che ti attendono, $Guccisore:uccisora; di dei!",
}
T[8628] = {
  title = "Avenger's Crown",
  desc = "Gli Imperatori Gemelli... sussurrano senza sosta, e a poco a poco mi stanno facendo perdere la ragione. Si prendono gioco di me, perché sanno che non posso spingermi più a fondo nel loro dominio per salvare mio fratello Arygos.$B$BLi vedo nelle visioni, quei volti mostruosi ornati di corone potenti. Ma mi vendicherò... Trasmuterò questi simboli del potere Qiraji in qualcosa di più adatto a ciò che ci serve.$B$BPortami i componenti che mi servono, $N, e avrai da me un copricapo dal potere senza pari.",
  obj = "Porta il Vek'lor's Diadem, 2 Idoli della Rinascita, 5 Stone Scarabs e 5 Crystal Scarabs ad Andorgos ad Ahn'Qiraj. Per completare questa quest devi anche ottenere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Mi hai portato i componenti che ti avevo chiesto, $N?",
  reward = "Ci sei $Griuscito:riuscita;! Gli Imperatori Gemelli hanno smesso di sussurrare.$B$BPrendi questo, è la tua ricompensa. Basterà vederlo per mettere paura nel cuore dei Qiraji... gli ricorderà i loro capi caduti e $Gil:la; mortale che li ha uccisi.",
}
T[8629] = {
  title = "Avenger's Legguards",
  desc = "Vuoi dimostrare il tuo valore alla mia razza, mortale? Molto bene: forse possiamo esserci utili a vicenda.$B$BOuro, l'antico sandworm, è un essere dal potere leggendario. Si dice che l'abbia creato l'Old God in persona, come una parodia della vita.$B$BHa una pelle innaturale... spessa, quasi impenetrabile, eppure flessibile, che gli permette di muoversi con la velocità e la grazia di una creatura molto più piccola.$B$BPortami un campione di quella pelle, insieme ad altri componenti minori, e ti creerò dei gambali di grande potere.",
  obj = "Porta la Skin of the Great Sandworm, 2 Idols of Strife, 5 Bronze Scarabs e 5 Ivory Scarabs a Kandrostrasz dentro Ahn'Qiraj. Per completare questa missione devi anche raggiungere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Allora, $N, hai portato i componenti che ti ho chiesto?",
  reward = "Sì... la pelle del verme farà da ottimo strato protettivo e, unita alle parti più robuste dei Qiraji che abbiamo distrutto lungo la strada, dovrebbe diventare un pezzo d'armatura formidabile. Che ti aiuti ad affrontare gli orrori indicibili che attendono là dentro!",
}
T[8630] = {
  title = "Avenger's Pauldrons",
  desc = "Fra noi si dice che le armature da spalla ornate delle razze mortali siano nate dal tentativo di imitare le ali di un drago.$B$BPortami le manette che indossano i capi Qiraji di rango più alto, e ne ricaverò un paio di spallacci più terrificanti persino delle ali di Nefarian in persona!",
  obj = "Porta le Qiraji Bindings of Dominance, 2 Idols of Life, 5 Crystal Scarabs e 5 Gold Scarabs ad Andorgos ad Ahn'Qiraj. Per completare questa quest devi anche ottenere la reputazione Neutrale con la Brood of Nozdormu.",
  progress = "Li hai raccolti, i componenti che mi servono?",
  reward = "Con i materiali che mi hai portato e con le scaglie dei nostri avversari Qiraji caduti, ti preparo questi spallacci, mortale. Che ti diano la protezione che ti serve, e che ai nostri nemici basti vederli per avere paura.",
}
T[8631] = {
  title = "Enigma Leggings",
  desc = "Vuoi dimostrare alla mia razza quanto vali, mortale? Molto bene: forse possiamo aiutarci a vicenda.$B$BOuro, l'antico sandworm, è un essere dal potere leggendario. Si dice che l'Old God in persona l'abbia creato come parodia della vita.$B$BHa una pelle innaturale... spessa, quasi impenetrabile, eppure flessibile: gli permette di muoversi con la velocità e la grazia di una creatura molto più piccola.$B$BPortami un campione di quella pelle insieme ad altri componenti minori, e ti creerò delle gambiere di grande potere.",
  obj = "Porta l'Ouro's Intact Hide, 2 Idoli del Saggio, 5 Silver Scarabs e 5 Bone Scarabs a Kandrostrasz dentro Ahn'Qiraj. Per completare questa quest devi anche ottenere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Hai portato i componenti che mi servono, $N?",
  reward = "Sì... la pelle del verme farà da ottimo strato protettivo. Unita alle parti più robuste dei Qiraji che abbiamo abbattuto lungo la strada, dovrebbe diventare un pezzo d'armatura formidabile. Possa aiutarti ad affrontare gli orrori indicibili che attendono là dentro!",
}
T[8632] = {
  title = "Enigma Circlet",
  desc = "Gli Imperatori Gemelli... sussurrano senza sosta, e a poco a poco mi stanno facendo perdere la ragione. Si prendono gioco di me, perché sanno che non posso spingermi più a fondo nel loro dominio per salvare mio fratello Arygos.$B$BLi vedo nelle visioni, quei volti mostruosi ornati di corone potenti. Ma mi vendicherò... Trasmuterò questi simboli del potere Qiraji in qualcosa di più adatto a ciò che ci serve.$B$BPortami i componenti che mi servono, $N, e avrai da me un copricapo dal potere senza pari.",
  obj = "Porta la Vek'nilash's Circlet, 2 Idols of Night, 5 Bronze Scarabs e 5 Ivory Scarabs ad Andorgos ad Ahn'Qiraj. Per completare questa quest devi anche ottenere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Mi hai portato i componenti che ti avevo chiesto, $N?",
  reward = "Ci sei $Griuscito:riuscita;! Gli Imperatori Gemelli hanno smesso di sussurrare.$B$BPrendi questo, è la tua ricompensa. Basterà vederlo per mettere paura nel cuore dei Qiraji... gli ricorderà i loro capi caduti e $Gil:la; mortale che li ha uccisi.",
}
T[8633] = {
  title = "Enigma Robes",
  desc = "Sotto Ahn'Qiraj, l'innominabile Old God si sta lentamente risvegliando dal sonno. Il terribile destino che incombe su Azeroth potrebbe compiersi fra qualche giorno come fra qualche anno; per esseri potenti come lui il tempo non ha significato.$B$BQuando le stelle saranno propizie, si scaglierà con una collera terribile contro ogni essere vivente. Prima di allora devi trovarlo e scoprire come porre fine alla sua esistenza.$B$BFallo, e portami un pezzo del suo guscio: ti concederò un'armatura che nessun mortale ha mai indossato... un'armatura degna di chi ha ucciso un dio!",
  obj = "Porta l'Husk of the Old God, 2 Idols of the Sun, 5 Gold Scarabs e 5 Clay Scarabs a Vethsera dentro Ahn'Qiraj. Devi anche raggiungere la reputazione Onorato con la Brood of Nozdormu per completare questa quest.",
  progress = "Il temibile C'Thun attende, dormiente, nella sua dimora ad Ahn'Qiraj.",
  reward = "Non credevo che saresti $Gtornato:tornata; da quest'impresa, $N.$B$BHai compiuto un destino più grande di quello della maggior parte degli esseri immortali.$B$BUccidendo C'Thun non hai soltanto salvato tutta Azeroth: hai alterato l'equilibrio di eventi cosmici che vanno oltre la tua comprensione.$B$BAccetta queste vesti, simbolo della gloria e del fardello che le tue azioni porteranno con sé.$B$BPossa il loro potere aiutarti nelle sfide che ti attendono, $Guccisore:uccisora; di dei!",
}
T[8634] = {
  title = "Enigma Boots",
  desc = "La magia Qiraji è forte e antica, e i qiraji più potenti brandiscono oggetti di una forza tale da far esitare persino un drago.$B$BPortami le manette del dominio qiraji insieme ad altri componenti minori, e ti creerò un paio di stivali potenti.$B$BTi serviranno nella lotta contro il nemico.",
  obj = "Porta le Qiraji Bindings of Dominance, 2 Idoli del Sole, 5 Silver Scarabs e 5 Crystal Scarabs a Kandrostrasz ad Ahn'Qiraj. Questa quest richiede anche la reputazione Neutrale con la Brood of Nozdormu.",
  progress = "Hai trovato gli oggetti che ti avevo chiesto, $N?",
  reward = "Ben fatto, $N: hai dimostrato di non essere $Gun:una; mortale qualunque.$B$BPrendi questi oggetti. Sono certo che ti aiuteranno a schiacciare i vili qiraji.",
}
T[8635] = {
  title = "Splitrock l'Anziano",
  reward = "Le battaglie delle ere passate sono i semi da cui nascono le leggende. Il tuo è un tempo di eroi, giovane. Possa la tua leggenda mettere radici e prosperare.$B$BTi auguro ogni bene, $N, e ti offro questo pegno...",
  en_title = "Splitrock the Elder",
}
T[8636] = {
  title = "Rumblerock l'Anziano",
  reward = "Quel che è fatto di vita deve morire e tornare alla terra, ma quel che è fatto di spirito vive in eterno. Ti auguro ogni bene, $N, e ti offro questo pegno...",
  en_title = "Rumblerock the Elder",
}
T[8637] = {
  title = "Deathdealer's Boots",
  desc = "La magia Qiraji è forte e antica, e i qiraji più potenti brandiscono oggetti di una forza tale da far esitare persino un drago.$B$BPortami le manette del comando qiraji insieme ad altri componenti minori, e ti creerò un paio di stivali potenti.$B$BTi serviranno nella lotta contro il nemico.",
  obj = "Porta le Qiraji Bindings of Command, 2 Idols of Strife, 5 Crystal Scarabs e 5 Bone Scarabs a Kandrostrasz ad Ahn'Qiraj. Questa quest richiede anche la reputazione Neutrale con la Brood of Nozdormu.",
  progress = "Hai trovato gli oggetti che ti avevo chiesto, $N?",
  reward = "Ben fatto, $N: hai dimostrato di non essere $Gun:una; mortale qualunque.$B$BPrendi questi oggetti. Sono certo che ti aiuteranno a schiacciare i vili qiraji.",
}
T[8638] = {
  title = "Deathdealer's Vest",
  desc = "Sotto Ahn'Qiraj, l'innominabile Old God si sta lentamente risvegliando dal sonno. Il terribile destino che attende Azeroth potrebbe arrivare fra pochi giorni come fra anni: per esseri potenti come lui il tempo non ha significato.$B$BQuando le stelle saranno favorevoli, si scaglierà con una collera terribile contro tutti gli esseri viventi. Prima di allora devi trovarlo e scoprire come porre fine alla sua esistenza.$B$BFallo, e portami un pezzo del suo guscio: ti darò un'armatura che nessun mortale ha mai indossato... un'armatura degna di chi ha ucciso un dio!",
  obj = "Porta il Carapace of the Old God, 2 Idols of Strife, 5 Bronze Scarabs e 5 Ivory Scarabs a Vethsera, all'interno di Ahn'Qiraj. Per completare questa missione devi anche raggiungere la reputazione Onorato con la Brood of Nozdormu.",
  progress = "Il terribile C'Thun attende nel sonno, nella sua dimora ad Ahn'Qiraj.",
  reward = "Non mi aspettavo di vederti tornare dall'impresa, $N.$B$BIl destino che hai compiuto è più grande di quello della maggior parte degli esseri immortali.$B$BUccidendo C'Thun non hai solo salvato tutta Azeroth: hai anche spostato l'equilibrio di eventi cosmici che vanno oltre la tua comprensione.$B$BAccetta questa corazza come simbolo della gloria e del fardello che le tue azioni ti porteranno.$B$BChe il suo potere ti aiuti nelle sfide che ti attendono, $Guccisore:ucciditrice; di dèi!",
}
T[8639] = {
  title = "Deathdealer's Helm",
  desc = "Gli Imperatori Gemelli... i loro sussurri non smettono mai, e piano piano mi logorano la mente. Mi deridono, perché sanno che non posso spingermi più a fondo nel loro dominio per salvare mio fratello Arygos.$B$BNelle visioni vedo i loro volti mostruosi, adorni di corone potenti. Ma avrò la mia vendetta... Trasmuterò questi simboli del potere Qiraji in altri che facciano più al caso nostro.$B$BPortami i componenti che mi servono, $N, e ti darò un copricapo dal potere senza pari.",
  obj = "Porta il Vek'lor's Diadem, 2 Idoli della Guerra, 5 Gold Scarabs e 5 Clay Scarabs ad Andorgos ad Ahn'Qiraj. Per completare questa missione devi anche raggiungere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Allora, $N, mi hai portato i componenti che ti ho chiesto?",
  reward = "Ce l'hai fatta! Gli Imperatori Gemelli hanno smesso di sussurrare.$B$BPrendi questo, è la tua ricompensa. Basterà vederlo per mettere paura nel cuore dei Qiraji... ricorderà loro i capi caduti e $Gil:la; mortale che li ha uccisi.",
}
