  obj = "Porta l'Husk of the Old God, 2 Idols of Night, 5 Stone Scarabs e 5 Crystal Scarabs a Vethsera, all'interno di Ahn'Qiraj. Per completare questa missione devi anche raggiungere la reputazione Onorato con la Brood of Nozdormu.",
  progress = "Il terribile C'Thun attende nel sonno, nella sua dimora ad Ahn'Qiraj.",
  reward = "Non mi aspettavo di vederti tornare dall'impresa, $N.$B$BIl destino che hai compiuto è più grande di quello della maggior parte degli esseri immortali.$B$BUccidendo C'Thun non hai solo salvato tutta Azeroth: hai anche spostato l'equilibrio di eventi cosmici che vanno oltre la tua comprensione.$B$BAccetta queste vesti come simbolo della gloria e del fardello che le tue azioni ti porteranno.$B$BChe il loro potere ti aiuti nelle sfide che ti attendono, $Guccisore:ucciditrice; di dèi!",
}
T[8662] = {
  title = "Doomcaller's Circlet",
  desc = "Gli Imperatori Gemelli... i loro sussurri non smettono mai, e piano piano mi logorano la mente. Mi deridono, perché sanno che non posso spingermi più a fondo nel loro dominio per salvare mio fratello Arygos.$B$BNelle visioni vedo i loro volti mostruosi, adorni di corone potenti. Ma avrò la mia vendetta... Trasmuterò questi simboli del potere Qiraji in altri che facciano più al caso nostro.$B$BPortami i componenti che mi servono, $N, e ti darò un copricapo dal potere senza pari.",
  obj = "Porta la Vek'nilash's Circlet, 2 Idols of Death, 5 Silver Scarabs e 5 Bone Scarabs ad Andorgos ad Ahn'Qiraj. Per completare questa missione devi anche raggiungere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Allora, $N, mi hai portato i componenti che ti ho chiesto?",
  reward = "Ce l'hai fatta! Gli Imperatori Gemelli hanno smesso di sussurrare.$B$BPrendi questo, è la tua ricompensa. Basterà vederlo per mettere paura nel cuore dei Qiraji... ricorderà loro i capi caduti e $Gil:la; mortale che li ha uccisi.",
}
T[8663] = {
  title = "Doomcaller's Trousers",
  desc = "Vuoi dimostrare il tuo valore alla mia stirpe, mortale? Bene, forse possiamo aiutarci a vicenda.$B$BOuro, l'antico sandworm, è un essere dal potere leggendario. Si dice che l'abbia creato l'Old God in persona, come parodia della vita.$B$BLa sua pelle è innaturale... spessa, quasi impenetrabile, eppure flessibile, tanto che gli permette di muoversi con la velocità e la grazia di una creatura molto più piccola.$B$BPortami un campione di quella pelle e qualche altro componente minore, e creerò per te delle gambiere di grande potere.",
  obj = "Porta la Skin of the Great Sandworm, 2 Idols of Rebirth, 5 Gold Scarabs e 5 Clay Scarabs a Kandrostrasz, dentro Ahn'Qiraj. Per completare questa missione devi anche raggiungere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Hai portato i componenti che mi servono, $N?",
  reward = "Sì... la pelle del verme sarà un ottimo strato protettivo. Insieme alle parti più resistenti dei Qiraji che abbiamo distrutto sulla strada fin qui, dovrebbe diventare un pezzo d'armatura formidabile. Possa aiutarti ad affrontare gli orrori indicibili che ti attendono là dentro!",
}
T[8664] = {
  title = "Doomcaller's Mantle",
  desc = "Tra noi si racconta che le spalliere decorate delle razze mortali siano nate per cercare di imitare le ali di un drago.$B$BPortami le manette che indossano i capi supremi dei Qiraji: ne ricaverò un paio di spallacci che fanno paura persino più delle ali di Nefarian in persona!",
  obj = "Porta le Qiraji Bindings of Dominance, 2 Idoli del Saggio, 5 Bronze Scarabs e 5 Bone Scarabs ad Andorgos ad Ahn'Qiraj. Per completare questa quest devi anche raggiungere la reputazione Neutrale con la Brood of Nozdormu.",
  progress = "I componenti che mi servono, li hai raccolti?",
  reward = "Con i materiali che mi porti e le scaglie dei nostri nemici Qiraji caduti, ti creo questi spallacci, mortale. Che ti proteggano quanto ti serve, e che i nostri avversari, solo a vederli, ne abbiano paura.",
}
T[8665] = {
  title = "Genesis Boots",
  desc = "La magia Qiraji è forte e antica. I qiraji più potenti impugnano oggetti così temibili da far esitare persino un drago.$B$BPortami le manette del dominio qiraji e qualche altro componente minore, e creerò per te un paio di stivali di grande potere.$B$BTi saranno utili nella lotta contro il nemico.",
  obj = "Porta le Qiraji Bindings of Dominance, 2 Idols of Rebirth, 5 Stone Scarabs e 5 Silver Scarabs a Kandrostrasz, ad Ahn'Qiraj. Questa missione richiede anche la reputazione Neutrale con la Brood of Nozdormu.",
  progress = "Hai trovato gli oggetti che ti ho chiesto, $N?",
  reward = "Ottimo lavoro, $N. Hai dimostrato di non essere $Gun:una; comune mortale.$B$BTe li consegno: sono certo che ti aiuteranno a schiacciare gli spregevoli qiraji.",
}
T[8666] = {
  title = "Genesis Vest",
  desc = "Sotto Ahn'Qiraj, l'innominabile Old God si sta lentamente risvegliando dal sonno. Il terribile destino che attende Azeroth potrebbe arrivare fra pochi giorni come fra anni: per esseri potenti come lui il tempo non ha significato.$B$BQuando le stelle saranno favorevoli, si scaglierà con una collera terribile contro tutti gli esseri viventi. Prima di allora devi trovarlo e scoprire come porre fine alla sua esistenza.$B$BFallo, e portami un pezzo del suo guscio: ti darò un'armatura che nessun mortale ha mai indossato... un'armatura degna di chi ha ucciso un dio!",
  obj = "Porta l'Husk of the Old God, 2 Idols of Rebirth, 5 Bronze Scarabs e 5 Ivory Scarabs a Vethsera, all'interno di Ahn'Qiraj. Per completare questa missione devi anche raggiungere la reputazione Onorato con la Brood of Nozdormu.",
  progress = "Il terribile C'Thun attende nel sonno, nella sua dimora ad Ahn'Qiraj.",
  reward = "Non mi aspettavo di vederti tornare dall'impresa, $N.$B$BIl destino che hai compiuto è più grande di quello della maggior parte degli esseri immortali.$B$BUccidendo C'Thun non hai solo salvato tutta Azeroth: hai anche spostato l'equilibrio di eventi cosmici che vanno oltre la tua comprensione.$B$BAccetta questa corazza come simbolo della gloria e del fardello che le tue azioni ti porteranno.$B$BChe il suo potere ti aiuti nelle sfide che ti attendono, $Guccisore:ucciditrice; di dèi!",
}
T[8667] = {
  title = "Genesis Helm",
  desc = "Gli Imperatori Gemelli... i loro sussurri non smettono mai, e piano piano mi tolgono il senno. Si fanno beffe di me, perché sanno che non posso spingermi più a fondo nel loro dominio per salvare mio fratello Arygos.$B$BNelle visioni vedo i loro volti mostruosi, ornati di potenti corone. Ma mi vendicherò... trasmuterò questi simboli del potere dei Qiraji in altri più adatti alle nostre esigenze.$B$BPortami i componenti che mi servono, $N, e ti darò un copricapo dal potere senza pari.",
  obj = "Porta il Vek'lor's Diadem, 2 Idols of Life, 5 Gold Scarabs e 5 Clay Scarabs ad Andorgos ad Ahn'Qiraj. Per completare questa quest devi anche raggiungere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "$N, mi hai portato i componenti che ti ho chiesto?",
  reward = "Ce l'hai fatta! Gli Imperatori Gemelli non sussurrano più.$B$BPrendi questo, è la tua ricompensa. Basterà vederlo perché la paura entri nel cuore dei Qiraji... ricorderà loro i capi caduti e $Gil:la; mortale che li ha uccisi.",
}
T[8668] = {
  title = "Genesis Trousers",
  desc = "Vuoi dimostrare il tuo valore alla mia stirpe, mortale? Bene, forse possiamo aiutarci a vicenda.$B$BOuro, l'antico sandworm, è un essere dal potere leggendario. Si dice che l'abbia creato l'Old God in persona, come parodia della vita.$B$BLa sua pelle è innaturale... spessa, quasi impenetrabile, eppure flessibile, tanto che gli permette di muoversi con la velocità e la grazia di una creatura molto più piccola.$B$BPortami un campione di quella pelle e qualche altro componente minore, e creerò per te delle gambiere di grande potere.",
  obj = "Porta la Skin of the Great Sandworm, 2 Idols of War, 5 Stone Scarabs e 5 Crystal Scarabs a Kandrostrasz, dentro Ahn'Qiraj. Per completare questa missione devi anche raggiungere la reputazione Amichevole con la Brood of Nozdormu.",
  progress = "Hai portato i componenti che mi servono, $N?",
  reward = "Sì... la pelle del verme sarà un ottimo strato protettivo. Insieme alle parti più resistenti dei Qiraji che abbiamo distrutto sulla strada fin qui, dovrebbe diventare un pezzo d'armatura formidabile. Possa aiutarti ad affrontare gli orrori indicibili che ti attendono là dentro!",
}
