T[8687] = {
  title = "Obiettivo: Hive'Zora Tunnelers",
  desc = "Sono stati chiamati rinforzi a unirsi all'assalto a Hive'Zora, e tu sei $Gstato scelto:stata scelta; per colpire i perforatori di Hive'Zora. A compito finito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Zora Tunnelers e fai rapporto a Commander Mar'alith a Cenarion Hold, in Silithus. Per completare questa missione devi anche portare le Combat Task Briefing VII.",
  progress = "Hai qualcosa da riferirmi, $C?",
}
T[8688] = {
  title = "Windrun l'Anziano",
  reward = "Le risposte ai misteri terreni, $N, le custodiscono i cieli con le loro innumerevoli stelle. E allora i saggi, e i fortunati, potrebbero alzare lo sguardo e trovare la verità?",
  en_title = "Windrun the Elder",
}
T[8689] = {
  title = "Shroud of Infinite Wisdom",
  desc = "Mi fa piacere sapere che ci aiuti nell'attacco ad Ahn'Qiraj, $N. Per la lotta contro il nostro nemico posso prepararti un oggetto protettivo che ti sarà utile, $C.$B$BMi occorrerà un drappo Qiraji, che naturalmente adatterò alle tue misure, e poi idoli e scarabei, per farne un fermaglio adeguato.$B$BNon resterai $Gdeluso:delusa;, te lo prometto.",
  obj = "Porta 1 Qiraji Martial Drape, 2 Jasper Idols, 5 Gold Scarabs e 5 Clay Scarabs a Keyl Swiftclaw in Silithus. Per completare questa quest devi anche ottenere la reputazione Riverito con il Cenarion Circle.",
  progress = "Hai con te i materiali per il mantello, $N?",
  reward = "Ah sì... è immacolato, questo drappo.$B$BPrendi questo mantello, $N, e che ti protegga dalla magia immonda dei Qiraji.",
}
