T[8697] = {
  title = "Ring of Infinite Wisdom",
  desc = "Si dice che gli anelli portati dai luogotenenti Qiraji concedano loro abilità formidabili. In teoria, se si sostituissero le gemme corrotte che li adornano con materiali più puri, se ne otterrebbero anelli non corrotti.$B$BLe gemme degli idoli Qiraji andrebbero benissimo, perché sono di qualità superiore.$B$BPortami l'anello e gli idoli e ne creerò per te uno potente, $C.",
  obj = "Porta 1 Qiraji Ceremonial Ring, 2 Obsidian Idols, 5 Silver Scarabs e 5 Bone Scarabs a Windcaller Yessendra a Silithus. Per completare questa quest devi anche ottenere la reputazione Onorato con il Cenarion Circle.",
  progress = "Mi hai portato l'anello e i materiali, $N?",
  reward = "Sostituirò per te la gemma dell'anello. Vedrai, l'effetto è molto più... gradevole.",
}
T[8698] = {
  title = "Ring of the Gathering Storm",
  desc = "Si dice che gli anelli portati dai luogotenenti Qiraji concedano loro abilità formidabili. In teoria, se si sostituissero le gemme corrotte che li adornano con materiali più puri, se ne otterrebbero anelli non corrotti.$B$BLe gemme degli idoli Qiraji andrebbero benissimo, perché sono di qualità superiore.$B$BPortami l'anello e gli idoli e ne creerò per te uno potente, $C.",
  obj = "Porta 1 Qiraji Magisterial Ring, 2 Vermillion Idols, 5 Silver Scarabs e 5 Bone Scarabs a Windcaller Yessendra a Silithus. Per completare questa quest devi anche ottenere la reputazione Onorato con il Cenarion Circle.",
  progress = "Mi hai portato l'anello e i materiali, $N?",
  reward = "Sostituirò per te la gemma dell'anello. Vedrai, l'effetto è molto più... gradevole.",
}
T[8699] = {
  title = "Band of Vaulted Secrets",
  desc = "Si dice che gli anelli portati dai luogotenenti Qiraji concedano loro abilità formidabili. In teoria, se si sostituissero le gemme corrotte che li adornano con materiali più puri, se ne otterrebbero anelli non corrotti.$B$BLe gemme degli idoli Qiraji andrebbero benissimo, perché sono di qualità superiore.$B$BPortami l'anello e gli idoli e ne creerò per te uno potente, $C.",
  obj = "Porta 1 Qiraji Magisterial Ring, 2 Azure Idols, 5 Gold Scarabs e 5 Clay Scarabs a Windcaller Yessendra a Silithus. Per completare questa quest devi anche ottenere la reputazione Onorato con il Cenarion Circle.",
  progress = "Mi hai portato l'anello e i materiali, $N?",
  reward = "Sostituirò per te la gemma dell'anello. Vedrai, l'effetto è molto più... gradevole.",
}
