T[8705] = {
  title = "Gavel of Infinite Wisdom",
  desc = "Gli oggetti che impugnano i Qiraji e i loro servi sono fatti dei materiali più rari e pregiati: ossa di antiche creature gigantesche, gemme venute dalle profondità della terra, metalli puri e resistenti.$B$BMi basta guardare i manufatti Qiraji per avere voglia di frantumarli, fonderne i pezzi e lavorarli con la mia arte. Dimostra la tua fedeltà al Circolo, $N, e con i migliori materiali Qiraji ti forgerò un'arma potente.",
  obj = "Porta 1 Qiraji Ornate Hilt, 2 Lambent Idols, 5 Bronze Scarabs e 5 Ivory Scarabs a Warden Haro a Silithus. Per completare questa missione devi anche ottenere la reputazione Osannato con il Cenarion Circle.",
  progress = "$N, mi hai portato i componenti che mi servono?",
  reward = "Hai lavorato bene, $C. Quest'elsa è opera di un maestro... ha un equilibrio perfetto.$B$BPrendi la tua arma, $N. Impugnala con piena sicurezza e sconfiggi i nostri nemici!",
}
