T[8728] = {
  title = "La Buona Notizia e la Cattiva Notizia",
  desc = "Be', c'è voluto un po' più del previsto. Vediamo un po' cosa dice questo registro.$B$B<Narain legge il registro in silenzio, borbottando fra sé ogni tanto.>$B$BLa buona notizia è che sono sicuro al 99% di riuscire a creare un'arcanite buoy che funzioni secondo le tue specifiche. Ovviamente, tutto dipende dalla cattiva notizia.$B$BLa cattiva notizia è che mi serviranno un sacco di arcanite, di elementium ore e di gemme rare.$B$BPortami quello che mi serve e la boa te la fabbrico io.",
  obj = "Narain Soothfancy a Tanaris vuole che gli porti 20 Arcanite Bars, 10 pezzi di Elementium Ore, 10 Azerothian Diamonds e 10 Blue Sapphires.",
  progress = "Le Arcanite buoys non si fabbricano mica da sole, $N. E NO, niente prestiti.",
  reward = "Un patto è un patto. Spero proprio che tu sappia in cosa ti stai cacciando, $N. Fai un sacco di fatica solo per andare a pesca.",
}
T[8729] = {
  title = "L'Ira di Neptulon",
  desc = "Ti ho già parlato della cattiva notizia? Si chiama Maws: 100 piedi di morte e distruzione. Mi sa che quel piccolo dettaglio me l'ero scordato.$B$BLa mia superiore chiaroveggenza psico-psionica dice che il posto migliore per gettare la boa è al largo della costa di Azshara, nella Bay of Storms.$B$BCerca un vortice turbinante, che con ogni probabilità sarà pieno di rottami.$B$BA proposito, spero che tu abbia degli amici.$B$BE se per qualche miracolo dovessi farcela, porta il frammento dello scettro ad Anachronos.",
  obj = "Usa l'Arcanite Buoy presso lo Swirling Maelstrom, a Bay of Storms, ad Azshara.",
  progress = "Il tempo stringe, $Gcampione:campionessa;.",
  reward = "Ben fatto, $N. Presto potrò rimettere insieme lo Scepter of the Shifting Sands.",
}
T[8730] = {
  title = "La Corruzione di Nefarius",
  desc = "$GCampione:Campionessa;, sei tu? Mille anni sono passati da quando il frammento mi è stato affidato, e proprio nella mia ora più buia qualcuno sorge a liberarmene... Ma che tragedia sarebbe, senza crudeltà?$B$B<Vaelastrasz tossisce debolmente.>$B$BNe... Nefarius adesso ha il frammento dello scettro.$B$BIl tempo stringe. Nefarius vuole distruggere il frammento. Sbrigati!",
  obj = "Uccidi Nefarian e recupera il Red Scepter Shard. Riporta il Red Scepter Shard ad Anachronos a Caverns of Time, in Tanaris. Hai 5 ore per portare a termine questo compito.",
  progress = "Ancora un eroe dei nostri perduto per mano della progenie di Deathwing. Questa sofferenza sarà per sempre la nostra maledizione...",
  reward = "L'anima di Vaelastrasz è in pace, $Gcampione:campionessa;. Tutti gli Aspetti seguono con grande interesse i tuoi progressi: sappi che hai alleati potenti.$B$BMi è stato ordinato di darti qualcosa che ti aiuti in questa lotta. Usalo bene...",
}
T[8731] = {
  title = "Servizio sul Campo",
  desc = "Saluti, $N. Prima che io possa affidarti compiti più impegnativi in questa guerra, dovrai fare la tua parte di servizio sul campo.$B$BFuori da Hive'Regal troverai l'Orgrimmar Legion del Capitano Skullsplit.$B$BFai rapporto a lui e riportami la prova del servizio svolto: avrò pronto per te un incarico più avanzato.$B$BAh, e per favore, cerca di stare alla larga dall'Ironforge Brigade. Fra i nostri volontari dell'Alleanza e quelli dell'Orda la tensione è alta.",
  obj = "Fai rapporto a Krug Skullsplit all'avamposto di Orgrimmar Legion davanti a Hive'Regal. Prepara gli Unsigned Field Duty Papers, ottieni i Signed Field Duty Papers e portali a Windcaller Kaldon a Cenarion Hold.$B$BNota: curare o lanciare incantesimi benefici su un membro di Orgrimmar Legion attiverà il PvP su di te.",
  progress = "Hai finito il tuo servizio sul campo, $N? Il Capitano Skullsplit è fuori da Hive'Regal.",
  reward = "Si vede che Krug non si cura molto delle scartoffie. L'ha firmato col sangue di silithid!$B$BMolto bene, $N. Ho preparato una serie di compiti che dovrebbero sfruttare bene le tue capacità di $C.$B$BGrazie ai continui sforzi tuoi e di chi è come te, il nostro nemico sarà presto schiacciato!",
}
T[8732] = {
  title = "Documenti di Servizio sul Campo",
  progress = "Vuoi far firmare quei documenti, immagino, $Gragazzo:ragazza;?",
  reward = "Sì, di questi tempi una scaramuccia così piccola può anche passare per servizio sul campo, immagino. Riporta questi documenti a Cenarion Hold: di sicuro avranno pronto per te un incarico comodo.$B$BSu, vai!",
}
T[8733] = {
  title = "Eranikus, Tyrant of the Dream",
  desc = "Questo è un viaggio di redenzione, $Geroe:eroina;. Se oggi dovessi essere ucciso, sarei morto per una causa giusta e retta. Devi recuperare il green scepter shard e purificare Eranikus dalla contaminazione che gli hanno inflitto gli Old Gods.$B$BVa' a Darnassus: appena fuori dalle mura della città troverai uno dei miei agenti. Sarà lui a mettere in moto le cose per noi e a informare Tyrande dei nostri piani senza mettere in allarme Staghelm.$B$B<Malfurion sospira.>$B$BUna caduta in disgrazia che si prepara da mille anni...",
  obj = "Recati sul continente di Teldrassil e trova l'agente di Malfurion da qualche parte fuori dalle mura di Darnassus.",
  reward = "Il wisp tace, a parte un ronzio basso. Stranamente, riesce a comunicare con te col pensiero.",
}
T[8734] = {
  title = "Tyrande e Remulos",
  desc = "Tyrande sarà informata, mortale: Shan'do Stormrage mi ha preparato a questa evenienza.$B$BOra devi avventurarti nella Moonglade e parlare con Remulos, che ti darà altre istruzioni per evocare Eranikus.$B$BTutti noi ti auguriamo tanta fortuna.",
  obj = "Recati nella Moonglade e parla con Keeper Remulos.",
  reward = "Se Eranikus si rifiutasse, strapparlo al Sogno sarebbe impossibile. Ma sono le sue stesse intenzioni a costringerlo a entrare nel nostro mondo: vuole distruggere la manifestazione vivente di Malfurion. Se ci riuscisse, sarebbe la fine di uno dei più potenti alleati del Sogno, e caduto Malfurion, l'Incubo consumerebbe interamente ciò che resta...",
  en_title = "Tyrande and Remulos",
  en_obj = "Travel to the Moonglade and speak to Keeper Remulos. ",
}
T[8735] = {
  title = "The Nightmare's Corruption",
  desc = "Devi recarti ai quattro portali del sogno di Azeroth ed estrarre da ognuno un fragment of the Nightmare's corruption. Ce li avranno i draconidi che abitano quelle zone. Quando li avrai raccolti, torna da me.",
  obj = "Recati ai quattro portali del Sogno di Smeraldo di Azeroth e raccogli un Fragment of the Nightmare's Corruption da ognuno. Torna da Keeper Remulos nella Moonglade quando avrai completato questo compito.",
  progress = "<Remulos è assorto nei suoi pensieri.>",
  reward = "Sei $Gpronto:pronta;? E il mondo, è pronto per ciò che stiamo per invocare? Non lo so... Il dovere mi lega a Malfurion. Il dovere e l'onore...",
}
T[8736] = {
  title = "L'Incubo si Manifesta",
  desc = "Con Eranikus dovremo usare moderazione: il nostro compito è redimerlo, non distruggerlo.$B$BTyrande è già in viaggio per aiutarci. Dovremo resistere ai colpi del drago e salvare Nighthaven da una distruzione certa.$B$BStai in guardia! Tu e i tuoi alleati siete la nostra unica speranza.",
  obj = "Difendi Nighthaven da Eranikus. Non lasciare che Keeper Remulos muoia. Non uccidere Eranikus. Difenditi. Attendi Tyrande.",
  reward = "È redento, $N, e ora torna nel Sogno a rimediare al male che ha fatto lui solo. Eranikus sarà un alleato potente per Malfurion e per mio padre.$B$BQueste armi sono per te, $N: me le ha date Ysera in persona. Faresti bene a usarle nelle battaglie contro i Qiraji.",
}
T[8737] = {
  title = "Azure Templar",
  desc = "Per le nostre operazioni a Silithus, il Twilight's Hammer e i nobili elementali che venerano sono una minaccia formidabile. Ora che dentro Ahn'Qiraj affrontiamo nuovi nemici, non possiamo permetterci di abbassare la guardia con quelli che stanno fuori.$B$BTrova il modo di evocare un Azure Templar, distruggilo e fai rapporto a Bor Wildmane.",
  obj = "Evoca e uccidi un Azure Templar e fai rapporto a Bor Wildmane a Cenarion Hold. Per completare questa missione devi anche portare le Tactical Task Briefing I.",
  progress = "Hai già finito il tuo compito, $N?",
  reward = "Ottimo lavoro, $N. Ecco il prossimo incarico per te.",
}
T[8738] = {
  title = "Hive'Regal Scout Report",
  desc = "Per raccogliere informazioni abbiamo mandato i nostri esploratori migliori nel cuore degli alveari dei silithid. L'Esploratore Landion tiene d'occhio da diversi giorni i movimenti dei silithid a Hive'Regal: trovalo e fatti consegnare un rapporto scritto. Su queste informazioni dobbiamo poter agire il prima possibile, $N.",
  obj = "Contatta Cenarion Scout Landion dentro Hive'Regal e porta l'Hive'Regal Scout Report a Windcaller Proudhorn a Cenarion Hold. Per completare questa missione devi anche portare le Tactical Task Briefing VII.",
  progress = "L'Esploratore Landion lo trovi dentro l'Alveare Regal. Sbrigati, $N! Il tempo stringe.",
  reward = "Apprezzo molto i tuoi sforzi, $N. Leggerò subito questi rapporti di ricognizione; tu, intanto, dai pure un'occhiata al prossimo incarico.",
}
T[8739] = {
  title = "Hive'Ashi Scout Report",
  desc = "Per raccogliere informazioni abbiamo mandato i nostri esploratori migliori nel cuore degli alveari dei silithid. L'Esploratrice Jalia tiene d'occhio da diversi giorni i movimenti dei silithid a Hive'Ashi: trovala e fatti consegnare un rapporto scritto. Su queste informazioni dobbiamo poter agire il prima possibile, $N.",
  obj = "Contatta Cenarion Scout Jalia dentro Hive'Ashi e porta l'Hive'Ashi Scout Report a Windcaller Proudhorn a Cenarion Hold. Per completare questa missione devi anche portare le Tactical Task Briefing VIII.",
  progress = "L'Esploratrice Jalia la trovi dentro Hive'Ashi. Sbrigati, $N! Il tempo stringe.",
  reward = "Apprezzo molto i tuoi sforzi, $N. Leggerò subito questi rapporti di ricognizione; tu, intanto, dai pure un'occhiata al prossimo incarico.",
}
T[8740] = {
  title = "Twilight Marauders",
  desc = "Sono state avvistate bande di cultisti del Twilight's Hammer che, a cavallo, si muovono fuori dalla portata delle nostre forze a Cenarion Hold ed eliminano le nostre pattuglie e carovane più piccole.$B$BTrova e sconfiggi i twilight marauders e il loro capo, una terribile guerriera di nome Morna. A compito finito, fai rapporto a Windcaller Proudhorn.",
  obj = "Uccidi Twilight Marauder Morna e 5 Twilight Marauders. Fai rapporto a Windcaller Proudhorn quando avrai finito il tuo compito. Per completare questa missione devi anche portare le Tactical Task Briefing IX.",
  progress = "Hai già finito il tuo compito, $N?",
  reward = "Ben fatto, $N. I twilight marauders facevano subire alle nostre pattuglie perdite inaccettabili. Ecco il prossimo incarico.",
}
T[8741] = {
  title = "Il Campione Ritorna",
  desc = "Il custode aspetta il tuo ritorno, $N. Porta il green scepter shard ad Anachronos, nelle Caverns of Time.",
  obj = "Porta il Green Scepter Shard ad Anachronos a Caverns of Time, in Tanaris.",
}
T[8742] = {
  title = "La Might of Kalimdor",
  progress = "Sono passati mille anni e, come era destino, davanti a me c'è qualcuno. Qualcuno che guiderà il suo popolo verso una nuova era.$B$BL'Old God trema, $N. Oh sì, ha paura della tua fede. Infrangi la profezia di C'Thun.$B$BSa che stai arrivando, $Gcampione:campionessa; — e con te giunge la potenza di Kalimdor. Dimmi soltanto quando sarai $Gpronto:pronta; e ti concederò lo Scepter of the Shifting Sands.",
  reward = "The Scepter of the Shifting Sands è di nuovo intero, $N.$B$BSei tu che devi usarlo. Sei tu che devi annunciare la prossima era del tuo popolo.$B$BPrima di suonare The Scarab Gong dovrai aspettare che gli eserciti dell'Orda e dell'Alleanza siano arrivati a Silithus.",
}
T[8743] = {
  title = "Batti il Gong!",
  progress = "The Scarab Gong incombe minaccioso davanti a te. Fatti forza, $N; appena avrai suonato The Scarab Gong, le porte di Ahn'Qiraj si apriranno.$B$BDalle fauci spalancate della bestia non possono uscire che caos e distruzione. Difendi il tuo popolo!",
  reward = "Accanto al gong spunta dal terreno un cristallo speciale. Forse è un favore della Progenie.",
}
T[8744] = {
  title = "Un Carefully Wrapped Present",
  reward = "Sul biglietto di questo regalo c'è scritto:$B$BPer $N,$B$BChe la tua festa di Great-Winter sia allegra e luminosa!",
  en_title = "A Carefully Wrapped Present",
}
T[8745] = {
  title = "Il Tesoro del Senza Tempo",
  reward = "Salute, $Gcampione:campionessa;. Sono Jonathan, custode del gong sacro ed eterno osservatore del Bronze Flight.$B$BÈ stato il Senza Tempo in persona a darmi il potere di concederti un oggetto a tua scelta dal suo tesoro senza tempo. Possa aiutarti nelle battaglie contro C'Thun.",
}
T[8746] = {
  title = "Metzen the Reindeer",
  desc = "È un DISASTRO! Hanno rapito Metzen the Reindeer!$B$BMetzen è una delle otto renne di Great-father Winter — e appartiene a Smokywood Pastures. Ci sono arrivate non una, ma DUE ransom letters, da gruppi che dicono di avere Metzen. Le feste sono nel pieno e qui la cassa piange! Ti prego — trova Metzen e riportacelo!$B$BCerca indizi nelle ransom letters e cospargilo con questa polvere di renna — lo libererà da qualunque legame!$B$BSbrigati, ti prego!",
  obj = "Trova Metzen the Reindeer. Cerca nei biglietti che hai ricevuto gli indizi su dove lo tengono prigioniero.$B$BQuando trovi Metzen, tieni con te il Pouch of Reindeer Dust: potrai spargergli addosso un po' di polvere, che dovrebbe liberarlo dalla prigionia.$B$BUna volta liberato Metzen, riporta il Pouch of Reindeer Dust a Kaymard Copperpinch a Orgrimmar.",
  progress = "$N! L'hai trovato? Ti sono bastati i biglietti nella borsa che ti ho dato per rintracciare Metzen? Non voglio nemmeno pensare a cosa potrebbero fargli quei teppisti crudeli... ma un riscatto così esorbitante non possiamo proprio permettercelo!",
  reward = "Ce l'hai fatta! Urrà!$B$BProprio poco fa Metzen è rientrato in volo nelle stalle di Great-father Winter — sì, Metzen vola davvero! La polvere ha funzionato a meraviglia, lo sapevo. Hai salvato dal disastro la Feast of Winter Veil, e con lei anche Smokywood Pastures. Grazie, $N.$B$BAscolta... per quello che hai fatto voglio darti questo. È una cosa MOLTO speciale: se hai una cavalcatura, credo che ti ci divertirai un mondo. Buon Winter Veil!",
}
T[8747] = {
  title = "Il Sentiero del Protettore",
  reward = "Notevole, $Gpiccolo:piccola;. Per ottenere il favore del Bronze Flight hai affrontato molte difficoltà, e della tua dedizione prendo nota.$B$BL'anello con sigillo del difensore ti offrirà una protezione superiore contro le forze del male.$B$BSappi che, scelto il sentiero, non potrai più tornare indietro, nemmeno se dovessi cambiare idea.",
}
T[8748] = {
  title = "Il Sentiero del Protettore",
  progress = "Hai difeso con costanza i figli di Kalimdor, e non è passato inosservato. Dammi l'anello con sigillo, così ne accrescerò i poteri.",
  reward = "La tua ascesa fra i ranghi della Stirpe è davvero notevole, $N. Che tu non ti allontani mai dal sentiero del protettore!",
}
T[8749] = {
  title = "Il Sentiero del Protettore",
  progress = "Fai onore alla mia specie, $N. Abbatti i nemici di Kalimdor! Mostra loro cosa vuol dire sfregiare la terra dell'eterna luce delle stelle.$B$BHai guadagnato un altro potenziamento. Dammi l'anello con sigillo, così ne rafforzerò il potere.",
  reward = "La tua ascesa fra i ranghi della Stirpe è davvero notevole, $N. Che tu non ti allontani mai dal sentiero del protettore!",
}
T[8750] = {
  title = "Il Sentiero del Protettore",
  progress = "Di rado si vede una dedizione così grande. Hai dimostrato che la tua volontà non vacilla, $N, e per la tua salda vigilanza sul nostro mondo sarai $Gricompensato:ricompensata; con generosità.$B$BDammi l'anello con sigillo: ne rafforzerò l'incantamento.",
  reward = "La tua ascesa fra i ranghi della Stirpe è davvero notevole, $N. Possa tu non allontanarti mai dal sentiero del protettore!",
}
T[8751] = {
  title = "Il Protettore di Kalimdor",
  progress = "Non ho mai visto tanta tenacia! Il Bronze Flight ti concede un ultimo incantamento. L'ha chiesto il Senza Tempo in persona!$B$BDammi l'anello con sigillo: vi apporterò le modifiche necessarie.",
  reward = "Alzati, $GProtettore:Protettrice; di Kalimdor! Alzati e sii $Griconosciuto:riconosciuta;!",
}
T[8752] = {
  title = "Il Sentiero del Conquistatore",
  reward = "Notevole, $Gpiccolo:piccola;. Non hai risparmiato fatica per conquistare il favore del Bronze Flight, e una dedizione simile non passa inosservata.$B$BL'anello con sigillo del conquistatore renderà molto più potenti i tuoi attacchi fisici.$B$BMa ti avverto: una volta scelto il sentiero, se cambierai idea non potrai tornare indietro.",
}
T[8753] = {
  title = "Il Sentiero del Conquistatore",
  progress = "Non mi è sfuggito come continui a difendere i figli di Kalimdor. Dammi l'anello con sigillo: ne accrescerò i poteri.",
  reward = "La tua ascesa fra i ranghi della Stirpe è davvero notevole, $N. Possa tu non allontanarti mai dal sentiero del conquistatore!",
}
T[8754] = {
  title = "Il Sentiero del Conquistatore",
  progress = "Fai onore alla mia specie, $N. Abbatti i nemici di Kalimdor! Mostra loro cosa significa deturpare la terra della luce stellare eterna.$B$BTi sei $Gguadagnato:guadagnata; un altro potenziamento: dammi l'anello con sigillo e ne rafforzerò il potere.",
  reward = "La tua ascesa fra i ranghi della Stirpe è davvero notevole, $N. Possa tu non allontanarti mai dal sentiero del conquistatore!",
}
T[8755] = {
  title = "La Via del Conquistatore",
  progress = "Di rado si vede una dedizione così grande. Hai dimostrato che la tua volontà non vacilla, $N, e per aver vegliato con tanta fermezza sul nostro mondo sarai $Gricompensato:ricompensata; generosamente.$B$BDammi l'anello con sigillo e ne rafforzerò l'incantamento.",
  reward = "Notevole davvero, la tua ascesa nei ranghi della Stirpe, $N. Possa tu non allontanarti mai dalla via del conquistatore!",
}
T[8756] = {
  title = "Il Conquistatore Qiraji",
  progress = "Mai vista tanta tenacia! Il Bronze Flight ti concede un ultimo incantamento, e a chiederlo è stato il Senzatempo in persona!$B$BDammi l'anello con sigillo e farò le modifiche necessarie.",
  reward = "Alzati, Conquistatore Qiraji! Alzati e sii $Griconosciuto:riconosciuta;!",
}
T[8757] = {
  title = "La Via dell'Invocatore",
  reward = "Notevole, $Gpiccolo:piccola;. Per guadagnarti il favore del Bronze Flight ti sei $Gdato:data; molto da fare, e la tua dedizione non passa inosservata.$B$BL'anello con sigillo dell'invocatore accrescerà di molto le tue capacità magiche e naturali.$B$BMa sappi che, scelta la tua via, non potrai più tornare indietro, anche se dovessi cambiare idea.",
}
T[8758] = {
  title = "La Via dell'Invocatore",
  progress = "Hai difeso senza sosta i figli di Kalimdor, e ti è stato riconosciuto. Dammi l'anello con sigillo e ne accrescerò i poteri.",
  reward = "Notevole davvero, la tua ascesa nei ranghi della Stirpe, $N. Possa tu non allontanarti mai dalla via dell'invocatore!",
}
T[8759] = {
  title = "La Via dell'Invocatore",
  progress = "Fai onore alla mia specie, $N: abbatti i nemici di Kalimdor! Mostra loro che cosa vuol dire deturpare la terra dell'eterna luce delle stelle.$B$BTi sei $Gguadagnato:guadagnata; un altro potenziamento: dammi l'anello con sigillo e ne rafforzerò il potere.",
  reward = "Notevole davvero, la tua ascesa nei ranghi della Stirpe, $N. Possa tu non allontanarti mai dalla via dell'invocatore!",
}
T[8760] = {
  title = "Il Sentiero dell'Invocatore",
  progress = "Raramente si vede una dedizione simile. Hai dimostrato una volontà incrollabile, $N, e per la tua fedele vigilanza sul nostro mondo sarai $Gricompensato:ricompensata; generosamente.$B$BConsegnami il tuo anello con sigillo, perché io ne rafforzi l'incantamento.",
  reward = "Notevole davvero la tua ascesa tra i ranghi della Stirpe, $N. Possa tu non deviare mai dal sentiero dell'invocatore!",
}
T[8761] = {
  title = "$GIl:La; Grande $GInvocatore:Invocatrice;",
  progress = "Mai ho visto tenacia simile! Il Bronze Flight ti concede un ultimo incantamento. L'ha chiesto il Senza Tempo in persona!$B$BConsegnami il tuo anello con sigillo, perché io vi apporti le modifiche necessarie.",
  reward = "Alzati, Grande $GInvocatore:Invocatrice;! Alzati, e che tutti ti riconoscano!",
}
T[8762] = {
  title = "Metzen the Reindeer",
  desc = "È successo un DISASTRO! Hanno rapito Metzen the Reindeer!$B$BMetzen è una delle otto renne di Greatfather Winter — e appartiene a Smokywood Pastures. Ci sono arrivate non una ma DUE ransom letters, da gruppi che dicono di avere Metzen. Le feste sono ormai nel pieno, e qui siamo a corto di soldi! Ti prego — trova Metzen e riportacelo!$B$BCerca gli indizi nelle ransom letters, e poi cospargilo con questa polvere di renna — lo libererà da qualunque legame!$B$BTi prego, fai presto!",
  obj = "Trova Metzen the Reindeer. Cerca nelle note che hai ricevuto degli indizi su dove lo tengono prigioniero.$B$BQuando trovi Metzen, devi avere con te il Pouch of Reindeer Dust per poterlo cospargere con un po' di polvere; questo dovrebbe liberare Metzen dai legami della prigionia.$B$BRiporta il Pouch of Reindeer Dust a Wulmort Jinglepocket a Ironforge una volta liberato Metzen.",
  progress = "$N! Ti sono bastate le note nella borsa che ti ho dato per trovare Metzen? Non voglio neanche pensare a cosa potrebbero fargli quei delinquenti crudeli... ma un riscatto così esorbitante non possiamo assolutamente permettercelo!",
  reward = "Ce l'hai fatta! Urrà!$B$BPoco fa Metzen è rientrato in volo alle stalle di Greatfather Winter — sì, Metzen vola davvero! La polvere ha funzionato a meraviglia; lo sapevo. Hai salvato dal disastro la Feast of Winter Veil e anche Smokywood Pastures. Grazie, $N.$B$BSenti... per quello che hai fatto voglio darti questo. È una cosa MOLTO speciale: se hai una cavalcatura, credo che ti divertirai un sacco. Buon Winter Veil!",
}
T[8763] = {
  title = "L'Eroe del Giorno",
  desc = "Senti... non dovrei proprio dirtelo, ma visto che sei $Gl'eroe:l'eroina; del giorno e tutto il resto...$B$BIn questo periodo dell'anno il fresh holly si trova dappertutto, ma non dura mai. Noi però abbiamo una macchina che lo conserva — così non va mai a male! Ci serve a ravvivare le feste... e, d'estate, i profitti!$B$BIl conservatore te lo lascio usare, ma solo se sei $Gun maestro cuoco:una maestra cuoca;. Ti servono un po' di deeprock salt e due, tre, oh, diciamo cinque monete d'oro. In cambio avrai una bella partita tutta per te.",
  obj = "Porta 1 Deeprock Salt e 5 monete d'oro a una qualsiasi macchina Holly Preserver, e riceverai 5 Preserved Holly.",
  progress = "A prima vista la macchina \"Holly Preserver\" sembra una specie di alambicco, ma guardandola bene si notano alcune modifiche in stile goblin. In ogni caso, quello che sai di cucina sembra bastare per capire come funziona.$B$BDentro c'è già del fresh holly — per metterla in moto ti basta metterci un po' di deeprock salt e cinque monete d'oro.",
  reward = "La macchina si avvia con un leggero brontolio e uno sbuffo di vapore. Poco dopo si ferma, e un altro piccolo getto di vapore annuncia che ha finito. Si apre uno sportello, ed ecco una partita di preserved holly!",
}
T[8764] = {
  title = "Il Cambio di Sentiero — Mai Più $GProtettore:Protettrice;",
  progress = "$GCampione:Campionessa;, se mai scegliessi di percorrere un altro sentiero, portami il tuo anello con sigillo e una montagna di scarabei dei nostri nemici ad Ahn'Qiraj.",
  reward = "Stammi bene, $N. Se cambierai idea, io sarò qui ad aiutarti.",
}
T[8765] = {
