  progress = "$GCampione:Campionessa;, se mai scegliessi di percorrere un altro sentiero, portami il tuo anello con sigillo e una montagna di scarabei dei nostri nemici ad Ahn'Qiraj.",
  reward = "Stammi bene, $N. Se cambierai idea, io sarò qui ad aiutarti.",
}
T[8766] = {
  title = "Il Cambio di Sentiero — Mai Più $GConquistatore:Conquistatrice;",
  progress = "$GCampione:Campionessa;, se mai scegliessi di percorrere un altro sentiero, portami il tuo anello con sigillo e una montagna di scarabei dei nostri nemici ad Ahn'Qiraj.",
  reward = "Stammi bene, $N. Se cambierai idea, io sarò qui ad aiutarti.",
}
T[8767] = {
  title = "Un Gently Shaken Gift",
  reward = "A quanto pare, qualcuno ha già scosso questo regalo qualche volta. Sul biglietto c'è scritto:$B$BPer $Gun:una; $C $R davvero speciale.",
  en_title = "A Gently Shaken Gift",
}
T[8768] = {
  title = "Un Gaily Wrapped Present",
  reward = "Questo regalo, incartato a festa, porta il tuo nome.$B$BAspetta, si è appena mosso?",
  en_title = "A Gaily Wrapped Present",
}
T[8769] = {
  title = "Un Ticking Present",
  reward = "I tuoi amici di Smokeywood Pastures ti augurano una Feast of Great-Winter piena di gioia.",
}
T[8770] = {
  title = "Obiettivo: Hive'Ashi Defenders",
  desc = "Mentre la guerra si inasprisce, la presenza silithid nella zona minaccia sempre di più le nostre operazioni. Sei $Gstato scelto:stata scelta; per prendere parte a un assalto a Hive'Ashi, e il tuo obiettivo principale saranno i suoi difensori.$B$BQuando avrai portato a termine il compito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Ashi Defenders e fai rapporto a Commander Mar'alith a Cenarion Hold, in Silithus. Per completare questa quest devi anche portare le Combat Task Briefing I.",
  progress = "Hai qualcosa da dirmi, $C?",
  reward = "Ottimo lavoro, $N. Come sempre, hai dimostrato una diligenza degna di nota.",
}
T[8771] = {
  title = "Obiettivo: Hive'Ashi Sandstalkers",
  desc = "Mentre la guerra si inasprisce, la presenza silithid nella zona minaccia sempre di più le nostre operazioni. Sei $Gstato scelto:stata scelta; per prendere parte a un assalto a Hive'Ashi, e il tuo obiettivo principale saranno i suoi inseguitori delle sabbie.$B$BQuando avrai portato a termine il compito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Ashi Sandstalkers e fai rapporto a Commander Mar'alith a Cenarion Hold, in Silithus. Per completare questa quest devi anche portare le Combat Task Briefing II.",
  progress = "Hai qualcosa da dirmi, $C?",
  reward = "Ottimo lavoro, $N. Il tuo contributo all'attacco contro Hive'Ashi non è passato inosservato.",
}
T[8772] = {
  title = "Obiettivo: Hive'Zora Waywatchers",
  desc = "Per l'assalto a Hive'Zora sono stati chiamati dei rinforzi, e tu sei $Gstato scelto:stata scelta; per colpirne i vigilanti. Quando avrai portato a termine il compito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Zora Waywatchers e fai rapporto a Commander Mar'alith a Cenarion Hold, in Silithus. Per completare questa quest devi anche portare le Combat Task Briefing VI.",
  progress = "Hai qualcosa da dirmi, $C?",
  reward = "Ottimo lavoro, $N. Il tuo contributo all'attacco contro Hive'Zora non è passato inosservato.",
}
T[8773] = {
  title = "Obiettivo: Hive'Zora Reavers",
  desc = "Per l'assalto a Hive'Zora sono stati chiamati dei rinforzi, e tu sei $Gstato scelto:stata scelta; per colpirne i razziatori. Quando avrai portato a termine il compito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Zora Reavers e fai rapporto a Commander Mar'alith a Cenarion Hold, in Silithus. Per completare questa quest devi anche portare le Combat Task Briefing IV.",
  progress = "Hai qualcosa da dirmi, $C?",
  reward = "Mi hanno parlato bene del tuo contributo all'attacco contro Hive'Zora. Continua così, e la vittoria sarà presto nostra.",
}
T[8774] = {
  title = "Obiettivo: Hive'Regal Ambushers",
  desc = "Mentre la guerra si inasprisce, la presenza silithid nella zona minaccia sempre di più le nostre operazioni. Sei $Gstato scelto:stata scelta; per prendere parte a un assalto a Hive'Regal, e il tuo obiettivo principale saranno i suoi aggressori.$B$BQuando avrai portato a termine il compito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Regal Ambushers e fai rapporto a Commander Mar'alith a Cenarion Hold, in Silithus. Per completare questa quest devi anche portare le Combat Task Briefing VIII.",
  progress = "Desideri dirmi qualcosa, $N?",
  reward = "Ottimo lavoro, $N. Il tuo contributo all'attacco contro Hive'Regal non è passato inosservato.",
}
T[8775] = {
  title = "Obiettivo: Hive'Regal Spitfires",
  desc = "Con lo sforzo bellico che cresce, i silithid presenti nella zona sono una minaccia sempre più grande per le nostre operazioni. Sei $Gstato scelto:stata scelta; per prendere parte a un assalto a Hive'Regal, e il tuo obiettivo principale saranno gli sputafuoco volanti di Hive'Regal.$B$BQuando avrai portato a termine il compito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Regal Spitfires e fai rapporto a Commander Mar'alith a Cenarion Hold, in Silithus. Devi anche portare le Combat Task Briefing IX per completare questa missione.",
  progress = "Hai qualcosa da dirmi, $N?",
  reward = "Ottimo lavoro, $N. Prendo nota del contributo che hai dato all'attacco a Hive'Regal.",
}
T[8776] = {
  title = "Obiettivo: Hive'Regal Slavemakers",
  desc = "Con lo sforzo bellico che cresce, i silithid presenti nella zona sono una minaccia sempre più grande per le nostre operazioni. Sei $Gstato scelto:stata scelta; per prendere parte a un assalto a Hive'Regal, e il tuo obiettivo principale saranno gli schiavizzatori di Hive'Regal.$B$BQuando avrai portato a termine il compito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Regal Slavemakers e fai rapporto a Commander Mar'alith a Cenarion Hold, in Silithus. Devi anche portare le Combat Task Briefing X per completare questa missione.",
  progress = "Hai qualcosa da dirmi, $N?",
  reward = "Ottimo lavoro, $N. Prendo nota del contributo che hai dato all'attacco a Hive'Regal.",
}
T[8777] = {
  title = "Obiettivo: Hive'Regal Burrowers",
  desc = "Con lo sforzo bellico che cresce, i silithid presenti nella zona sono una minaccia sempre più grande per le nostre operazioni. Sei $Gstato scelto:stata scelta; per prendere parte a un assalto a Hive'Regal, e il tuo obiettivo principale saranno gli scavaterra di Hive'Regal.$B$BQuando avrai portato a termine il compito, fai rapporto a Commander Mar'alith.",
  obj = "Uccidi 30 Hive'Regal Burrowers e fai rapporto a Commander Mar'alith a Cenarion Hold, in Silithus. Devi anche portare le Combat Task Briefing XI per completare questa missione.",
  progress = "Hai qualcosa da dirmi, $N?",
  reward = "Ottimo lavoro, $N. Prendo nota del contributo che hai dato all'attacco a Hive'Regal.",
}
T[8778] = {
  title = "The Ironforge Brigade Ha Bisogno di Esplosivi!",
  desc = "The Ironforge Brigade ha chiesto, cosa insolita, dei componenti molto... instabili... Raccoglili e portali a Mr. Nozzlespring dell'Ironforge Brigade.",
  obj = "Porta 6 Oli d'Immolazione, 5 Goblin Rocket Fuel e 10 Dense Blasting Powder ad Arcanist Nozzlespring vicino a Hive'Zora, in Silithus. Devi anche portare le Logistics Task Briefing IV per completare questa missione.",
  progress = "Hai qualcosa per me, $N?",
  reward = "Ah, sì! Questi mi torneranno utili! Grazie mille, $N!",
}
T[8779] = {
  title = "Materiali per la Divinazione",
  desc = "Gli studi di Geologist Larksbane si sono rivelati preziosissimi per le nostre operazioni in Silithus. Di recente ha chiesto dei materiali per la divinazione, che le servono per la sua ricerca.$B$BRaccogli questi materiali e consegnaglieli di persona, così potrà proseguire il lavoro.",
  obj = "Porta 1 Large Brilliant Shard, 1 Large Radiant Shard e 1 Huge Emerald a Geologist Larksbane a Cenarion Hold, in Silithus. Devi anche portare le Logistics Task Briefing V per completare questa missione.",
}
T[8780] = {
  title = "Potenziamenti d'Armatura per il Fronte",
  desc = "Sul campo di battaglia The Ironforge Brigade è pericolosamente vicina a esaurire la scorta di potenziamenti d'armatura. Procurane un lotto e portalo a Janela Stouthammer, all'avamposto dell'Ironforge Brigade fuori da Hive'Zora.",
  obj = "Porta 8 Rugged Armor Kits e 8 Heavy Armor Kits a Janela Stouthammer all'Avamposto dell'Ironforge Brigade vicino a Hive'Zora, in Silithus. Devi anche portare le Logistics Task Briefing VII per completare questa quest.",
}
T[8781] = {
  title = "Armi per il Fronte",
  desc = "Nella nostra lotta in Silithus The Ironforge Brigade è stata un'alleata preziosa, ma purtroppo lungo la strada fin qui ha perso molti rifornimenti. Procura un lotto di armi e portalo a Janela Stouthammer, vicino a Hive'Zora.",
  obj = "Porta 2 Moonsteel Broadswords a Janela Stouthammer all'Avamposto dell'Ironforge Brigade fuori da Hive'Zora. Devi anche portare le Logistics Task Briefing VI per completare questa quest.",
  progress = "Hai qualcosa per me, $N?",
  reward = "Oh, eccellente! Così non dovrò più sentire nessuno lamentarsi delle lame smussate. Grazie, $N.",
}
T[8782] = {
  title = "Forniture per le Uniformi",
  desc = "Con i volontari appena arrivati, le uniformi non bastano più. Procura un lotto di materiali per le uniformi e portalo a Windcaller Proudhorn.",
  obj = "Porta 1 Mooncloth, 2 Bolts of Runecloth e 1 Ironweb Spider Silk a Windcaller Proudhorn a Cenarion Hold, in Silithus. Devi anche portare le Logistics Task Briefing VIII per completare questa quest.",
}
T[8783] = {
  title = "Materiali Straordinari",
  desc = "Il fabbro di Cenarion Hold, Vargus, ha chiesto dei materiali incantati con cui forgiare armi potenti per le nostre forze. Procurali e portali direttamente a Vargus: le truppe di Cenarion Hold devono restare ben equipaggiate.",
  obj = "Porta 2 Enchanted Thorium Bars e 2 Enchanted Leather a Vargus a Cenarion Hold, in Silithus. Devi anche portare le Logistics Task Briefing IX per completare questa quest.",
}
T[8784] = {
  title = "Segreti dei Qiraji",
  desc = "Hai scoperto un antico manufatto Qiraji! Forse questa reliquia può tornare utile a uno dei draghi vicino all'ingresso del tempio.",
  obj = "Porta l'Ancient Qiraji Artifact ai draghi nascosti vicino all'ingresso del tempio.",
  progress = "Stai brillando! So cosa vuol dire...",
  reward = "Una scoperta eccezionale, $N. Davvero meravigliosa! Di certo ci aiuterà a capire le menti contorte del nemico.",
}
T[8785] = {
  title = "L'Orgrimmar Legion Ha Bisogno di Mojo!",
  desc = "L'Orgrimmar Legion ha chiesto diversi ingredienti insoliti e, visti i risultati che sta ottenendo in Silithus, vorremmo accontentarla al più presto. Raccogli i materiali e portali alla troll di nome Shai.",
  obj = "Porta 6 Powerful Mojo, 6 Flasks of Big Mojo e 8 Oli di Immolazione a Shadow Priestess Shai vicino a Hive'Regal, in Silithus. Devi anche portare le Logistics Task Briefing IV per completare questa quest.",
  progress = "Me li hai portati, i materiali, $N?",
  reward = "Ah, sì. Proprio quello che mi serviva! Ci preparo un intruglio speciale che ai silithid non piacerà per niente!",
}
T[8786] = {
  title = "Armi per il Campo",
  desc = "L'Orgrimmar Legion ci ha chiesto altre armi, e finora non siamo riusciti a mandargliele. Procurati le armi che servono e portale a Merok Longstride, fuori da Hive'Regal.",
  obj = "Porta 3 Massive Iron Axes a Merok Longstride all'accampamento dell'Orgrimmar Legion fuori da Hive'Regal. Devi portare anche le Logistics Task Briefing VI per completare questa missione.",
  progress = "Hai qualcosa per me, $N?",
  reward = "Ottimo lavoro. Ne eravamo rimasti a corto, $N.",
}
T[8787] = {
  title = "Potenziamenti d'Armatura per il Campo",
  desc = "I coraggiosi volontari dell'Orgrimmar Legion sono arrivati a Silithus per sostenere la nostra causa, ma durante il viaggio, chissà come, le loro scorte di potenziamenti d'armatura sono andate perdute. Procurane una partita e portala a Merok Longstride, all'accampamento dell'Orgrimmar Legion.",
  obj = "Porta 8 Rugged Armor Kits e 8 Heavy Armor Kits a Merok Longstride vicino a Hive'Regal. Devi portare anche le Logistics Task Briefing VII per completare questa missione.",
  progress = "Hai qualcosa per me, $N?",
  reward = "Ah, sì... Li distribuirò alle truppe, $N. L'Orgrimmar Legion ti ringrazia!",
}
T[8788] = {
  title = "Un Gently Shaken Gift",
  reward = "A quanto pare, qualcuno ha già scosso questo regalo qualche volta. Sul biglietto c'è scritto:$B$BPer $Gun:una; $C $R davvero speciale.",
  en_title = "A Gently Shaken Gift",
}
T[8789] = {
  title = "Imperial Qiraji Armaments",
  desc = "In questi mille anni non siamo rimasti con le mani in mano, $N.$B$BAbbiamo osservato queste bestie divorare i loro simili quando non servivano più, le abbiamo ascoltate tramare e complottare per distruggere il nostro mondo, e abbiamo scoperto come si tradiscono fra loro.$B$BLe debolezze ci sono, e sappiamo come volgerle a nostro vantaggio.$B$BTrova il loro equipaggiamento cerimoniale e portamelo: unito all'elemento creato dall'instabilità del loro stesso Dio, porterà la resa dei conti.",
  obj = "Arygos nel Temple of Ahn'Qiraj creerà per te degli Armamenti Infusi d'Elementio se gli porterai l'Imperial Qiraji Armaments e 3 pezzi di Elementium Ore.",
  progress = "Cerca quello che ti ho chiesto. Diventerai più grande della somma delle tue parti, $Gcampione:campionessa;.",
  reward = "Infuse di Elementio, queste armi fenderanno con una facilità incredibile i Qiraji e il loro Dio.",
}
T[8790] = {
  title = "Imperial Qiraji Regalia",
  desc = "Secondo Arygos, l'elemento nato dagli scontri fra gli Old Gods e i loro servitori potrebbe essere, nelle giuste condizioni, estremamente letale anche per loro. Parlo dell'Elementio, mortale.$B$BTrova l'Imperial Qiraji Regalia e portamelo insieme all'elemento tossico, e io ne infonderò il potere in armi formidabili.",
  obj = "Merithra of the Dream nel Temple of Ahn'Qiraj creerà per te degli Armamenti Infusi d'Elementio se le porterai l'Imperial Qiraji Regalia e 3 pezzi di Elementium Ore.",
  progress = "Sarai tu ad abbatterli e a liberarci da queste catene.",
  reward = "Usa bene questo oggetto, $N, e fa' provare a loro il dolore che tanto desiderano infliggere agli altri.",
}
T[8791] = {
  title = "La Caduta di Ossirian",
  desc = "Una terribile minaccia è stata messa a tacere per sempre: il crudele Ossirian è stato sconfitto.$B$BPer gli abitanti di Kalimdor la notizia di questa vittoria sarebbe un sollievo. Prendi la testa di Ossirian e portala a Commander Mar'alith della Cenarion Hold.",
  obj = "Consegna l'Head of Ossirian the Unscarred a Commander Mar'alith alla Cenarion Hold, a Silithus.",
  progress = "Ah, $N, sei $Gtornato:tornata;! E $Gtutto intero:tutta intera;, aggiungerei. Che notizie mi porti da Ahn'Qiraj?",
  reward = "Ti offro il mio più alto encomio, $N, e un oggetto di potere a tua scelta: hai reso un grande servizio al popolo di Kalimdor.",
}
T[8792] = {
  title = "L'Orda Ha Bisogno del Tuo Aiuto!",
  desc = "Ciao, mi fa piacere che tu abbia deciso di ascoltarmi. Per prepararsi alla Guerra di Ahn'Qiraj l'Orda ha bisogno di tutto l'aiuto possibile, e quindi abbiamo bisogno di te! In questo stesso momento i raccoglitori ufficiali stanno radunando i materiali che servono per la guerra ormai vicina, ma senza il tuo aiuto non arriveremo ai nostri obiettivi, $N!$B$BDovresti andare a parlare con chi è al comando, Warlord Gorchuk. Allora, $C, che ne dici? Ci darai una mano con questi preparativi vitali?",
  obj = "Parla con Warlord Gorchuk in Orgrimmar's Valley of Spirits.",
  reward = "Throm'ka, $C! Fa piacere vedere tanti membri dell'Orda come te, $N, venire a dare il loro sostegno per preparare il terreno alla Guerra di Ahn'Qiraj ormai vicina. Con gli sforzi che facciamo qui ci assicureremo la vittoria contro i Silithid e i loro malvagi padroni nascosti dentro Ahn'Qiraj.$B$BOra che sei qui, non dimenticare di parlare con i vari raccoglitori e di offrirti per procurare i materiali che fanno al caso tuo.",
  en_title = "The Horde Needs Your Help!",
  en_obj = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.",
}
T[8793] = {
  title = "L'Orda Ha Bisogno del Tuo Aiuto!",
  desc = "Salve, sono contento che tu abbia deciso di ascoltarmi. Per prepararsi alla Guerra di Ahn'Qiraj l'Orda ha bisogno di tutto l'aiuto possibile, e quindi anche del tuo! In questo preciso momento i raccoglitori ufficiali stanno mettendo insieme i materiali che servono per la guerra imminente, ma senza il tuo aiuto non ce la faremo a raggiungere i nostri obiettivi, $N!$B$BTi conviene andare a parlare col tizio che comanda, Warlord Gorchuk. Allora, $C, che ne dici? Ci darai una mano con dei preparativi così importanti?",
  obj = "Parla con Warlord Gorchuk in Orgrimmar's Valley of Spirits.",
  reward = "Throm'ka, $C! Fa piacere vedere tanti membri dell'Orda come te, $N, che offrono il loro sostegno per gettare le basi dell'imminente Guerra di Ahn'Qiraj. Con lo sforzo che facciamo qui ci garantiremo la vittoria sui Silithid e sui loro malvagi padroni nascosti dentro Ahn'Qiraj.$B$BOra che sei qui, non dimenticare di parlare con i vari raccoglitori e di offrire il tuo aiuto per procurare i materiali più adatti a te.",
  en_title = "The Horde Needs Your Help!",
  en_obj = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.",
}
T[8794] = {
  title = "L'Orda Ha Bisogno del Tuo Aiuto!",
  desc = "Salve, mi fa piacere che tu abbia deciso di ascoltarmi. L'Orda deve prepararsi alla Guerra di Ahn'Qiraj e le serve tutto l'aiuto possibile: vuol dire che abbiamo bisogno di te! In questo momento i raccoglitori ufficiali stanno radunando i materiali per la guerra che si avvicina, ma senza il tuo aiuto non raggiungeremo i nostri obiettivi, $N!$B$BTi conviene andare a parlare con chi comanda, Warlord Gorchuk. Allora, $C, che ne dici? Ci darai una mano con i preparativi? Sono di vitale importanza.",
  obj = "Parla con Warlord Gorchuk in Orgrimmar's Valley of Spirits.",
  reward = "Throm'ka, $C! È bello vedere tanti membri dell'Orda come te, $N, farsi avanti per aiutare a gettare le basi della Guerra di Ahn'Qiraj che si avvicina. Lo sforzo che facciamo qui ci garantirà la vittoria contro i Silithid e i loro malvagi padroni nascosti dentro Ahn'Qiraj.$B$BOra che sei qui, ricordati di parlare con i vari raccoglitori e di aiutarli a procurare i materiali più adatti a te.",
  en_title = "The Horde Needs Your Help!",
  en_obj = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.",
}
T[8795] = {
  title = "L'Alleanza Ha Bisogno del Tuo Aiuto!",
  desc = "Salve! Sono $Gcontento:contenta; che tu abbia deciso di ascoltarmi. Per prepararsi alla Guerra di Ahn'Qiraj l'Alleanza ha bisogno di tutto l'aiuto possibile, e questo vuol dire che abbiamo bisogno di te! In questo momento i raccoglitori ufficiali stanno radunando il materiale che serve per la guerra che ci aspetta, ma senza il tuo aiuto non riusciremo a raggiungere i nostri obiettivi, $N!$B$BDovresti andare a parlare con chi comanda, Field Marshal Snowfall. Allora, che ne dici, $C? Darai una mano con questi preparativi vitali?",
  obj = "Parla con Field Marshal Snowfall a Ironforge's Military Ward.",
  reward = "Salve, e ben $Gtrovato:trovata;, $Gragazzo:ragazza;! Fa piacere vedere tanti membri dell'Alleanza come te, $N, farsi avanti per preparare il terreno alla Guerra di Ahn'Qiraj che ci aspetta. Con lo sforzo che facciamo qui avremo la vittoria assicurata contro i Silithid e i loro malvagi padroni nascosti dentro Ahn'Qiraj.$B$BOra che sei qui, non dimenticarti di parlare con i vari raccoglitori e di offrirti per procurare i materiali adatti a te.",
  en_title = "The Alliance Needs Your Help!",
  en_obj = "Speak with Field Marshal Snowfall in Ironforge's Military Ward.",
}
T[8796] = {
  title = "L'Alleanza Ha Bisogno del Tuo Aiuto!",
  desc = "Salve, sono contenta che tu abbia deciso di ascoltarmi. Per prepararsi alla Guerra di Ahn'Qiraj l'Alleanza ha bisogno di tutto l'aiuto possibile, e quindi abbiamo bisogno di te! In questo stesso momento i raccoglitori ufficiali stanno radunando il materiale che serve per la guerra imminente, ma senza il tuo aiuto non riusciremo a raggiungere i nostri obiettivi, $N!$B$BDovresti andare a parlare con il capo, Field Marshal Snowfall. Allora, $C, che ne dici? Darai una mano con i preparativi fondamentali?",
  obj = "Parla con Field Marshal Snowfall in Ironforge's Military Ward.",
  reward = "Salute e ben $Gtrovato:trovata;, $Gragazzo:ragazza;! Che bello vedere tanti membri dell'Alleanza come te, $N, farsi avanti per offrire il loro sostegno e gettare le basi della Guerra di Ahn'Qiraj che ci aspetta. Con lo sforzo che facciamo qui ci garantiremo la vittoria contro i Silithid e i loro malvagi padroni nascosti dentro Ahn'Qiraj.$B$BOra che sei qui, non dimenticare di parlare con i vari raccoglitori e di offrirti per procurare i materiali per cui sei $Gportato:portata;.",
  en_title = "The Alliance Needs Your Help!",
  en_obj = "Speak with Field Marshal Snowfall in Ironforge's Military Ward.",
}
T[8797] = {
  title = "L'Alleanza Ha Bisogno del Tuo Aiuto!",
  desc = "Ciao, sono contenta che tu abbia deciso di ascoltarmi. L'Alleanza ha bisogno di tutto l'aiuto possibile per prepararsi alla Guerra di Ahn'Qiraj, e questo vuol dire che contiamo su di te! In questo momento gli incaricati ufficiali della raccolta stanno radunando i materiali necessari per lo scontro imminente, ma senza il tuo contributo non riusciremo a raggiungere i nostri obiettivi, $N!$B$BDovresti andare a parlare con chi comanda, Field Marshal Snowfall. Che ne dici, $C? Ci darai una mano in questi preparativi fondamentali?",
  obj = "Parla con Field Marshal Snowfall in Ironforge's Military Ward.",
  reward = "Salute e ben $Gtrovato:trovata;, $Gragazzo:ragazza;! Che piacere vedere tanti membri dell'Alleanza come te, $N, venire a dare man forte per preparare il terreno alla Guerra di Ahn'Qiraj, ormai alle porte. Lo sforzo che facciamo qui ci garantirà la vittoria contro i Silithid e i loro malvagi padroni nascosti dentro Ahn'Qiraj.$B$BOra che sei qui, non dimenticare di parlare con i vari incaricati della raccolta e di offrirti per procurare i materiali che sai trovare meglio.",
  en_title = "The Alliance Needs Your Help!",
  en_obj = "Speak with Field Marshal Snowfall in Ironforge's Military Ward.",
}
T[8798] = {
  title = "Uno Yeti Tutto Tuo",
  reward = "Ehi! Sai che c'è?! Anche tu sei $Gun ingegnere:un'ingegnera;! Allora, visto che mi hai aiutata a dare una lezione ai miei amici, ti insegnerò a costruire un mechanical yeti tutto tuo! Così il divertimento non finirà mai, e potrai spaventare chi ti pare! Sempre che tu riesca a scovare i componenti per costruirlo, s'intende.$B$BChe ne dici, $N? Vuoi imparare il segreto per costruire un mechanical yeti?",
}
T[8799] = {
  title = "L'Eroe del Giorno",
  desc = "Senti... non dovrei proprio dirtelo, ma visto che sei $Gl'eroe:l'eroina; del giorno e tutto il resto...$B$BIn questo periodo dell'anno c'è fresh holly dappertutto, ma non dura mai. Noi però abbiamo una macchina che lo conserva, e così non va mai a male! Ci serve per ravvivare le feste... e i profitti d'estate!$B$BIl conservatore te lo lascio usare, ma solo se sei $Gun maestro:una maestra; di cucina. Ti serviranno un po' di deeprock salt e due, tre... oh, diciamo cinque monete d'oro. Ne ricaverai una bella partita tutta per te.",
  obj = "Porta 1 Deeprock Salt e 5 monete d'oro alla macchina Holly Preserver: in cambio riceverai 5 Preserved Holly.",
  progress = "A prima vista la macchina \"Holly Preserver\" sembra una specie di alambicco, ma a guardarla bene si notano alcune modifiche in stile goblin. Comunque, con la tua abilità in cucina sembri capire come funziona.$B$BDentro c'è già fresh holly — per metterla in moto basta fornire un po' di deeprock salt e cinque monete d'oro.",
  reward = "Mettendosi in moto, la macchina brontola piano e sbuffa un po' di vapore. Poco dopo si ferma con un altro piccolo sbuffo. Si apre uno sportello: dentro c'è una partita di preserved holly!",
}
T[8800] = {
  title = "Equipaggiamento da Battaglia Cenarion",
  desc = "Man mano che porti a termine i compiti di guerra che ti vengono affidati, ti conviene passare da Vargus, il fabbro, e mostrargli tutti i distintivi che hai guadagnato strada facendo. Ti darà un equipaggiamento all'altezza dell'impegno che metti nella nostra causa.",
  obj = "Parla con Vargus a Cenarion Hold, in Silithus.",
  reward = "Ti manda Kaldon? Molto bene, vediamo cosa possiamo fare per te.",
}
T[8801] = {
  title = "L'Eredità di C'Thun",
  desc = "Le mura di Ahn'Qiraj tremano: una forza del male più antica del mondo stesso è stata distrutta.$B$BGuardando i resti del colossale abominio ti si gela quasi il cuore. Anche ora che è morto, l'eredità del male di C'Thun la senti tutta intorno a te.$B$BHai fatto quello che si credeva impossibile.$B$BAfferri un peduncolo oculare del mostro e lo metti al sicuro nella sacca.$B$BPorta l'Eye of C'Thun ai draghi della sala accanto.",
  obj = "Porta l'Eye of C'Thun a Caelastrasz in Temple of Ahn'Qiraj.",
  progress = "<Caelastrasz si inginocchia davanti a te.>$B$B$GLord:Lady; $N, ci hai liberati dalla sua morsa.",
  reward = "Lasceremo questo luogo da soli, $GLord:Lady; $N — quando saremo certi che il male qui dentro sia stato distrutto del tutto. Il tuo leggendario viaggio è quasi alla fine.",
}
T[8802] = {
  title = "$GIl Salvatore:La Salvatrice; di Kalimdor",
  desc = "Recati alle Caverns of Time, $GLord:Lady; $N: Anachronos attende il tuo ritorno. Consegnagli l'occhio di C'Thun, perché di certo vorrà metterlo nella collezione del suo padrone.",
  obj = "Porta l'Eye of C'Thun ad Anachronos in Caverns of Time.",
  progress = "$GLord:Lady; $N! È finita...",
  reward = "Il Padrone ha lasciato questi per te, $Gcampione:campionessa;. Vengono dal tesoro senza tempo: una collezione di manufatti che abbracciano migliaia di anni — a te la scelta.",
}
T[8803] = {
  title = "Un Festive Gift",
  reward = "Sul regalo c'è un biglietto:$B$BA $N,$B$Bcon la speranza che ti aiuti a portare calorosi auguri e l'allegria delle feste in tutta Azeroth.$B$BDa Greatfather Winter",
  en_title = "A Festive Gift",
}
T[8804] = {
  title = "Kit di Sopravvivenza nel Deserto",
  desc = "Ora che alla Cenarion Hold arrivano nuove reclute, il problema è tenerle in vita nel deserto: per dei volontari inesperti la disidratazione e le tante creature velenose sono una seria minaccia. Raccogli le provviste che servono per un kit di sopravvivenza nel deserto e portale a Calandrath, alla Cenarion Hold.",
  obj = "Porta 4 Globes of Water, 4 Powerful Anti-Venom e 4 Smoked Desert Dumplings a Calandrath alla locanda della Cenarion Hold, a Silithus. Devi portare anche le Logistics Task Briefing I per completare questa missione.",
}
T[8805] = {
  title = "Stivali per la Guardia",
  desc = "La divisione a cavallo della guardia della Cenarion Hold è rimasta a corto di ornate mithril boots. Procurane una partita e portala subito a Captain Vish Kozus, alla Cenarion Hold.",
  obj = "Porta 3 Ornate Mithril Boots a Vish Kozus, Capitano della Guardia alla Cenarion Hold, a Silithus. Devi portare anche le Logistics Task Briefing II per completare questa missione.",
}
T[8806] = {
  title = "Pietre da Molatura per la Guardia",
  desc = "Le pietre da molatura della guardia di Cenarion Hold stanno finendo. Procurane una partita e portala subito a Captain Vish Kozus, a Cenarion Hold.",
  obj = "Porta 10 Dense Grinding Stones, 10 Solid Grinding Stones e 10 Heavy Grinding Stones a Vish Kozus, Capitano della Guardia a Cenarion Hold, in Silithus. Per completare questa quest devi portare anche le Logistics Task Briefing III.",
}
T[8807] = {
  title = "Materiali di Divinazione",
  desc = "Gli studi di Geologist Larksbane sono stati di enorme valore per le nostre operazioni in Silithus, e di recente ci ha chiesto dei materiali di divinazione per le sue ricerche.$B$BRaccoglili e portaglieli di persona, perché possa andare avanti col suo lavoro.",
  obj = "Porta 1 Large Brilliant Shard, 1 Large Radiant Shard e 1 Huge Emerald a Geologist Larksbane a Cenarion Hold, in Silithus. Per completare questa quest devi portare anche le Logistics Task Briefing V.",
}
T[8808] = {
  title = "Forniture per le Uniformi",
  desc = "L'ultima ondata di volontari ci ha lasciati a corto di uniformi. Procura una partita di materiali per confezionarne di nuove e portala a Windcaller Proudhorn.",
  obj = "Porta 1 Mooncloth, 2 Bolts of Runecloth e 1 Ironweb Spider Silk a Windcaller Proudhorn a Cenarion Hold, in Silithus. Per completare questa quest devi portare anche le Logistics Task Briefing VIII.",
}
T[8809] = {
  title = "Materiali Straordinari",
  desc = "Il fabbro di Cenarion Hold, Vargus, ci ha chiesto materiali incantati per forgiare armi potenti alle nostre forze. Procurali e portali a Vargus in persona, perché le truppe di Cenarion Hold restino ben equipaggiate.",
  obj = "Porta 2 Enchanted Thorium Bars e 2 Enchanted Leather a Vargus a Cenarion Hold, in Silithus. Per completare questa quest devi portare anche le Logistics Task Briefing IX.",
}
T[8810] = {
  title = "Bende per il Fronte",
  desc = "Con le ultime perdite, le scorte di bende sul campo di battaglia sono pericolosamente scarse. Procura una partita di materiale di pronto soccorso e consegnala a Windcaller Proudhorn, a Cenarion Hold.",
  obj = "Porta 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages e 30 Heavy Mageweave Bandages a Windcaller Proudhorn a Cenarion Hold, in Silithus. Per completare questa quest devi portare anche le Logistics Task Briefing X.",
}
T[8811] = {
  title = "Un Sigillo di Encomio",
  progress = "Se un avventuriero ha un solo sigillo di encomio, glielo cambio con un piccolo riconoscimento presso Darnassus.$B$BTieni presente, però, che conviene consegnare dieci sigilli tutti insieme, in una pila: così il tuo impegno avrà un riconoscimento maggiore. Il cambio del sigillo singolo lo offriamo come servizio a chi non ne ha abbastanza per una pila completa di dieci.$B$BDetto questo, se vuoi comunque consegnarne uno solo, sono $Gpronto:pronta; ad aiutarti.",
  reward = "Molto bene — le tue imprese sono a registro, e il tuo impegno riceve il giusto riconoscimento. Continua così, $C.$B$BSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.",
  en_title = "One Commendation Signet",
}
T[8812] = {
  title = "Un Sigillo di Encomio",
  progress = "Se un avventuriero ha un solo sigillo di encomio, glielo cambio con un piccolo riconoscimento presso gli Gnomeregan Exiles.$B$BTieni presente, però, che conviene consegnare dieci sigilli tutti insieme, in una pila: così il tuo impegno avrà un riconoscimento maggiore. Il cambio del sigillo singolo lo offriamo come servizio a chi non ne ha abbastanza per una pila completa di dieci.$B$BDetto questo, se vuoi comunque consegnarne uno solo, sono $Gpronto:pronta; ad aiutarti.",
  reward = "Molto bene — le tue imprese sono a registro, e il tuo impegno riceve il giusto riconoscimento. Continua così, $C.$B$BSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.",
  en_title = "One Commendation Signet",
}
T[8813] = {
  title = "Un Sigillo di Encomio",
  progress = "A chi ha un solo sigillo di encomio offro di scambiarlo con me per un piccolo riconoscimento presso Ironforge.$B$BRicorda però che conviene consegnare i sigilli tutti insieme, in una pila da dieci: così i tuoi sforzi otterranno un riconoscimento più grande. Lo scambio di un sigillo singolo è un servizio che offriamo a chi non ne ha abbastanza per completare una pila.$B$BDetto questo, se vuoi comunque consegnarne uno solo, sono $Gpronto:pronta; ad aiutarti.",
  reward = "Molto bene — le tue imprese sono state messe a registro, e i tuoi sforzi ricevono il riconoscimento che meritano. Continua così, $C.$B$BSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.",
  en_title = "One Commendation Signet",
}
T[8814] = {
