T[8856] = {
  title = "Kit di Sopravvivenza nel Deserto",
  desc = "Ora che a Cenarion Hold arrivano nuove reclute, bisogna pensare a tenerle in vita nel deserto: per dei volontari inesperti la disidratazione e le tante creature velenose sono una seria minaccia. Raccogli le provviste che servono per un kit di sopravvivenza nel deserto e portale a Calandrath, a Cenarion Hold.",
  obj = "Porta 4 Globes of Water, 4 Powerful Anti-Venom e 4 Baked Salmon a Calandrath, nella locanda di Cenarion Hold, in Silithus.",
}
T[8857] = {
  title = "Segreti del Colosso — Ashi",
  desc = "Cerco avventurieri temprati dalla battaglia, pronti e capaci di portare a Oglethorpe, a Booty Bay, un campione fresco del guscio di Colossus of Ashi caduto. No, no, non voglio che ti avvicini neanche al cadavere di quella cosa. Prendi uno dei miei campioni e sbrigati. Marci non gli servono a niente!",
  obj = "Porta il Colossus of Ashi's Husk a Oglethorpe Obnoticus, a Booty Bay.",
  progress = "Sì? Che cos'hai lì?",
  reward = "Oh, che polli costruirò con questo guscio meraviglioso! Ben fatto, $Gragazzo mio:ragazza mia;!",
}
T[8858] = {
  title = "Segreti del Colosso — Regal",
  desc = "Niente mi farebbe più piacere che ficcare 'sto guscio d'insetto nella faccia grassa di Oilfist... Solo che son bloccato qui a raccogliere campioni da quello scarafaggio gigante, e con la stazza che ha quel coso, ne avrò fino alle prime ore del mattino.$B$BFammi il favore di portare 'sto campione a Oilfist, e alla svelta, $C. Paga UN SACCO!$B$BEh sì, il Thorium Point — sta nella Searin' Gorge.",
  obj = "Porta il Colossus of Regal's Husk a Overseer Oilfist nella Searing Gorge.",
  progress = "Mmm...",
  reward = "Eccellente. Da questa chitina potremmo di certo ricavare un'armatura incredibilmente potente. Ecco qui le ricchezze promesse.",
}
T[8859] = {
  title = "Segreti del Colosso — Zora",
  desc = "Per recuperare questo campione i miei servitori per poco non sono morti. Devi sbrigarti, assolutamente! Lord Maxwell Tyrosus aspetta con ansia un campione fresco di guscio. Crede che i segreti di questo Colossus possano aiutarci nella guerra contro lo Scourge!$B$BPerché sei ancora qui?! Alla Speranza della Luce! Sì, per i tuoi sforzi sarai $Gricompensato:ricompensata; profumatamente...",
  obj = "Porta il Colossus of Zora's Husk a Lord Maxwell Tyrosus, a Light's Hope Chapel, in Eastern Plaguelands.",
  progress = "$GAmico:Amica;, hai il passo un po' pesante.",
  reward = "Eccellente, e proprio in tempo! Ben fatto, $Gragazzo:ragazza;.",
}
T[8860] = {
  title = "Festeggiamenti per il Nuovo Anno!",
  desc = "Stormwind festeggia l'arrivo del nuovo anno! Si beve gratis tutto il giorno, e stanotte ci saranno i fuochi d'artificio! Dovrebbe essere niente male... ma oggi fa festa anche Booty Bay; scommetto che lì sarà ancora meglio!$B$BComunque, a Innkeeper Allison di Stormwind serve una scorta di cibo di Smoky Wood Pasture per sfamare tutti i festaioli. Fammi il favore di consegnargliela!$B$BGrazie, $N! Innkeeper Allison si trova alla Gilded Rose, nel Trade District of Stormwind.",
  obj = "Porta le Smokywood Supplies a Innkeeper Allison a Stormwind.",
  progress = "Salve! Sei qui per la festa! O forse hai solo bisogno di far riposare i piedi stanchi...",
  reward = "Oh, le mie provviste di Smokywood! Splendido! Mi serviranno per sfamare tutta la gente in città durante i festeggiamenti!$B$BGrazie, $N. Prendi questo compenso, e non dimenticare di bere e ballare con chi fa baldoria là fuori!",
  en_title = "New Year Celebrations!",
  en_obj = "Bring the Smokywood Supplies to Innkeeper Allison in Stormwind.",
}
T[8861] = {
  title = "Festeggiamenti per il Nuovo Anno!",
  desc = "Thunder Bluff festeggia l'arrivo del nuovo anno! Lì si beve gratis per tutto il giorno, e stanotte ci sarà uno spettacolo di fuochi d'artificio!$B$BDovrebbe essere niente male... ma oggi c'è una festa anche a Booty Bay; scommetto che sarà ancora meglio!$B$BComunque, a Innkeeper Pala di Thunder Bluff serve una scorta di cibo di Smoky Wood Pasture per sfamare tutti i partecipanti alla festa. Mi faresti il favore di portargliela!$B$BGrazie, $N! Innkeeper Pala si trova nella locanda vicino al ponte per l'Hunter's Rise.",
  obj = "Porta le Smokywood Supplies a Innkeeper Pala a Thunder Bluff.",
  progress = "Buongiorno, $C! Sei $Gvenuto:venuta; a Thunder Bluff per i nostri festeggiamenti? O sei qui per far riposare uno zoccolo stanco tra una caccia e l'altra?",
  reward = "Oh, molto bene! Queste provviste mi aiuteranno a sfamare tutta la nostra gente venuta qui a festeggiare il nuovo anno!$B$BTi ringrazio, $N. Ti sono debitrice. Ti prego, prendi queste monete... e segui il mio consiglio — bevi a volontà dai barili qui fuori, e unisciti alle danze dei nostri festaioli!",
  en_title = "New Year Celebrations!",
  en_obj = "Bring the Smokywood Supplies to Innkeeper Pala in Thunder Bluff.",
}
T[8862] = {
  title = "Elune's Candle",
  progress = "La candela di Elune è un artefatto che i fedeli della Festa della Luna venerano molto. Racchiude vera luce lunare, pronta a essere liberata!$B$BPer quasi tutte le creature questa luce è innocua, ma vedrai come brucia e abbaglia Omen e i suoi servitori.",
  reward = "Molto bene, accetto queste coins of ancestry. Prendi la candela di Elune, ti prego, e con lei la mia benedizione. Goditi anche questi fuochi d'artificio: sono un omaggio.$B$BChe la tua Festa della Luna sia piena di gioia e di allegria, $N.$B$BE se sceglierai di affrontare Omen e i suoi servitori, la candela di Elune ti sarà davvero utile...",
  en_title = "Elune's Candle",
}
T[8863] = {
  title = "Festival Dumplings",
  progress = "Se hai fame, sei $Gvenuto:venuta; nel posto giusto, $Gamico mio:amica mia;!$B$BI ravioli sono il cibo tradizionale della Festa della Luna: si servono fin dalla prima festa, e sono lieto di poterli offrire anche a questa. Per una sola coin of ancestry ti farò assaggiare uno dei piatti più gustosi che mangerai mai!",
  reward = "Eccellente: questi ravioli te li offro io, goditeli. Sono solo un piccolo segno di gratitudine per l'onore che ti sei $Gguadagnato:guadagnata; con le tue azioni, ma credo che ti piaceranno lo stesso.$B$BSe hai altre coins of ancestry, sono pronto a offrirti in cambio un'ampia scelta di oggetti.",
  en_title = "Festival Dumplings",
}
T[8864] = {
  title = "Abiti Lunari da Festa",
  progress = "Ho alcuni abiti che potrebbero interessarti. Un tempo si indossavano durante la Festa della Luna, e questi che ho adesso sono forse i più belli che abbia mai visto: ognuno è fatto a mano, solo con i materiali più pregiati e morbidi.$B$BIn cambio di alcune coins of ancestry ti lascerò scegliere uno dei tre modelli che ho, e sarà tuo. Ti va bene?",
  reward = "Molto bene, accetto queste coins of ancestry. Prendi il tuo abito, ti prego, con la mia benedizione, e goditi anche questi fuochi d'artificio: sono un omaggio.$B$BCome hai onorato gli anziani, così onori me con la tua sola presenza. Grazie, e che la tua Festa della Luna sia gioiosa.",
  en_title = "Festive Lunar Dresses",
}
T[8865] = {
  title = "Completi Lunari da Festa",
  progress = "Ho il piacere di dirti che ho una bella selezione di completi da festa con pantaloni che possono essere tuoi... ma solo per delle coins of ancestry. Se tieni alla moda, sono proprio quello che cerchi! Completi così, te lo assicuro, non li troverai da nessun'altra parte.$B$BIn cambio di alcune Coins of Ancestry ti lascerò scegliere uno dei tre modelli che ho, e sarà tuo. Ti va bene?",
  reward = "Molto bene, accetto queste coins of ancestry. Prendi il tuo completo, ti prego, con la mia benedizione, e goditi anche questi fuochi d'artificio: sono un omaggio.$B$BSe hai altre coins of ancestry da scambiare, torna a parlarmi: per tutta la durata della Festa della Luna offrirò vari oggetti.",
  en_title = "Festive Lunar Pant Suits",
}
T[8866] = {
  title = "Bronzebeard l'Anziano",
  reward = "Mi fa piacere sapere che la gente di questa terra rende ancora omaggio alle antiche razze. Ti auguro ogni bene, $N, e ti offro questo dono...",
  en_title = "Bronzebeard the Elder",
}
T[8867] = {
  title = "Fuochi d'Artificio Lunari",
  desc = "Ogni anno i druidi di Moonglade festeggiano il grande trionfo della nostra città su un antico male.$B$BRendiamo onore alla saggezza degli anziani, ci sediamo a banchetti magnifici e, naturalmente... spariamo fuochi d'artificio!$B$BIl nostro venditore ti darà dei razzi colorati in cambio di una piccola offerta. Prova qualcuno dei lanciarazzi qui intorno, $N.",
  obj = "Lancia 8 Fuochi d'Artificio Lunari e 2 Fuochi d'Artificio a Grappolo e torna da un Lunar Festival Harbinger in una qualsiasi capitale.",
  progress = "Hai trovato i lanciarazzi, $N?",
  reward = "Ben fatto, $N.$B$BOra che sei $Gentrato:entrata; nello spirito della festa, che ne dici di prendere questo invito alla celebrazione di Moonglade?$B$BSe hai un po' di tempo libero, è una festa davvero piacevole. Condividiamo cibo, bevande, storie e naturalmente... altri fuochi d'artificio!$B$BApri l'invito dentro il cerchio di luce lunare superiore e sarai $Gtrasportato:trasportata; a Moonglade.",
  en_title = "Lunar Fireworks",
  en_obj = "Launch 8 Lunar Fireworks and 2 Cluster Fireworks and return to a Lunar Festival Harbinger at any capital city.",
}
T[8868] = {
  title = "Benedizione di Elune",
  desc = "Un tempo la bestia Omen era un eroe di questo mondo. Era un lupo di grande forza e fortuna, e ha combattuto al fianco degli eroi della War of the Ancients, finché non ha ceduto alla magia demoniaca. Allora si è rivoltato contro gli alleati e ha imperversato per Azeroth, lasciandosi dietro morte e terrore.$B$BAlla fine è stato sconfitto qui, a Moonglade, e ora dorme nel limo del Lake Elune'ara. Ma a ogni nuovo anno, durante la festa, si risveglia...$B$BRaduna dei compagni, $N, evoca la bestia Omen e sconfiggila. Guadagnati la benedizione di Elune!",
  obj = "Evoca Omen, sconfiggilo e ottieni la Benedizione di Elune. Torna da Valadar Starsong a Nighthaven",
  progress = "Sotto il Lake Elune'ara Omen si agita ancora, $N...",
  reward = "Ottimo lavoro, $N. Sconfiggendo Omen hai rimandato il suo spirito nelle acque di Elune'ara. La bestia è benedetta da Elune e per questo non può morire, ma la sua rabbia si placherà per un altro anno.$B$BLa tua vittoria è una celebrazione, $N — una celebrazione della potenza di Omen, di te e dei tuoi alleati, e della pace che hai donato a questo tragico eroe del nostro passato.",
}
T[8869] = {
  title = "Dolce Serenity",
  desc = "La dolce Serenity si trova nello Scarlet Bastion, e il Crimson Hammersmith ne protegge la ricetta a costo della vita. Sconfiggilo e portami il suo grembiule: in cambio ti addestrerò finché non sarai $Gun:una; forgiamartelli.$B$BSappi questo: una volta scelta la via del forgiamartelli, quelle del forgiaspade e del forgiasce non saranno più disponibili.",
  obj = "Vai a Stratholme e uccidi il Crimson Hammersmith. Recupera il Crimson Hammersmith's Apron e torna da Lilith.",
}
T[8870] = {
  title = "La Celebrazione della Luna",
  desc = "È di nuovo quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a festeggiare con noi la Celebrazione della Luna. Qui in città troverai il Lunar Festival Harbinger, nel punto segnato da un cerchio benedetto di luce lunare: potrà dirti di più sulla festa.",
  obj = "Parla con il Lunar Festival Harbinger a Mystic Ward of Ironforge. Puoi parlare anche con i Lunar Festival Harbingers nelle altre capitali.",
  reward = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti alla festa?",
  en_title = "The Lunar Festival",
  en_obj = "Talk to the Lunar Festival Harbinger in the Mystic Ward of Ironforge.  You can also talk to Lunar Festival Harbingers in other capital cities.",
}
T[8871] = {
  title = "La Celebrazione della Luna",
  desc = "È di nuovo quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a festeggiare con noi la Celebrazione della Luna. Qui in città troverai il Lunar Festival Harbinger, nel punto segnato da un cerchio benedetto di luce lunare: potrà dirti di più sulla festa.",
  obj = "Parla con il Lunar Festival Harbinger a Park District, a Stormwind. Puoi parlare anche con i Lunar Festival Harbingers nelle altre capitali.",
  reward = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti alla festa?",
  en_title = "The Lunar Festival",
  en_obj = "Talk to the Lunar Festival Harbinger in the Park District in Stormwind.  You can also talk to Lunar Festival Harbingers in other capital cities.",
}
T[8872] = {
  title = "La Celebrazione della Luna",
  desc = "È di nuovo quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a festeggiare con noi la Celebrazione della Luna. Qui in città troverai il Lunar Festival Harbinger, nel punto segnato da un cerchio benedetto di luce lunare: potrà dirti di più sulla festa.",
  obj = "Parla con il Lunar Festival Harbinger a Cenarion Enclave, a Darnassus. Puoi parlare anche con i Lunar Festival Harbingers nelle altre capitali.",
  reward = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti alla festa?",
  en_title = "The Lunar Festival",
  en_obj = "Talk to the Lunar Festival Harbinger at the Cenarion Enclave in Darnassus.  You can also talk to Lunar Festival Harbingers in other capital cities.",
}
T[8873] = {
  title = "La Celebrazione della Luna",
  desc = "È di nuovo quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a festeggiare con noi la Celebrazione della Luna. Qui in città troverai il Lunar Festival Harbinger, nel punto segnato da un cerchio benedetto di luce lunare: potrà dirti di più sulla festa.",
  obj = "Parla con il Lunar Festival Harbinger a Valley of Wisdom, a Orgrimmar. Puoi parlare anche con i Lunar Festival Harbingers nelle altre capitali.",
  reward = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti alla festa?",
  en_title = "The Lunar Festival",
  en_obj = "Talk to the Lunar Festival Harbinger in the Valley of Wisdom in Orgrimmar.  You can also talk to Lunar Festival Harbingers in other capital cities.",
}
T[8874] = {
  title = "La Celebrazione della Luna",
  desc = "È di nuovo quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a festeggiare con noi la Celebrazione della Luna. Qui in città troverai il Lunar Festival Harbinger, nel punto segnato da un cerchio benedetto di luce lunare: potrà dirti di più sulla festa.",
  obj = "Parla con il Lunar Festival Harbinger all'ingresso di Undercity. Puoi parlare anche con i Lunar Festival Harbingers nelle altre capitali.",
  reward = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti alla festa?",
  en_title = "The Lunar Festival",
  en_obj = "Talk to the Lunar Festival Harbinger in the entrance to the Undercity.  You can also talk to Lunar Festival Harbingers in other capital cities.",
}
T[8875] = {
  title = "La Celebrazione della Luna",
  desc = "È di nuovo quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a festeggiare con noi la Celebrazione della Luna. Qui in città troverai il Lunar Festival Harbinger, nel punto segnato da un cerchio benedetto di luce lunare: potrà dirti di più sulla festa.",
  obj = "Parla con il Lunar Festival Harbinger a Elder Rise, a Thunder Bluff. Puoi parlare anche con i Lunar Festival Harbingers nelle altre capitali.",
  reward = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti alla festa?",
  en_title = "The Lunar Festival",
  en_obj = "Talk to the Lunar Festival Harbinger at the Elder Rise in Thunder Bluff.  You can also talk to Lunar Festival Harbingers in other capital cities.",
}
T[8876] = {
  title = "Razzi Piccoli",
  progress = "Custodisco i segreti dei razzi della Festa della Luna, e condivido con gioia il mio sapere con chi è onorato.$B$BSe mi dai delle coins of ancestry, in cambio posso offrirti la ricetta di un razzo piccolo...",
  reward = "Ah, molto bene. Ecco le tue ricette, $N: che la mia Elune ti benedica.",
  en_title = "Small Rockets",
}
T[8877] = {
  title = "Firework Launcher",
  progress = "I razzi sono un modo meraviglioso di festeggiare, eppure, se vuoi vederne lo splendore... vanno lanciati da un mortaio.$B$BPortami delle coins of ancestry e potrò insegnarti a costruire mortai per razzi come quelli che vedi a Moonglade.",
  reward = "Ecco a te, $N. Questo è lo schema per costruire un firework launcher. Sistema i mortai dove vuoi festeggiare, poi invita gli amici a unirsi a te!",
}
T[8878] = {
  title = "Ricette Festive",
  progress = "Gli abiti e i tailleur pantalone che vedi sono vestiti tradizionali di molti anni fa: si indossano per onorare le antiche usanze e i cari scomparsi.$B$BPortami delle coins of ancestry, $N, e ti darò il modello per creare abiti o completi rossi tradizionali.",
  reward = "Ecco i modelli, $N. Sono certa che i frutti di questo sapere ti sembreranno molto belli.",
}
T[8879] = {
  title = "Razzi Grandi",
  progress = "I razzi grandi della Festa riempiono il cielo di splendore — solo i razzi a grappolo possono rivaleggiare con la loro magnificenza!$B$BPortami delle coins of ancestry, $N, e condividerò il sapere per crearli.",
  reward = "Molto bene — accetto queste coins of ancestry. Ecco le tue ricette, $N: possa tu usarle per diffondere la gloria di Elune!",
}
T[8880] = {
  title = "Razzi a Grappolo",
  progress = "I razzi a grappolo sono un insieme di singoli razzi, e sono di una bellezza straordinaria! Portami delle coins of ancestry e condividerò con te il sapere per crearli...",
  reward = "Ecco a te, $N. Prendi queste ricette e imparane i segreti. Ti auguro buona fortuna: non vedo l'ora di ammirare le tue magnifiche creazioni.",
}
T[8881] = {
  title = "Grandi Fasci Pirotecnici",
  progress = "Costruire dei grandi fasci pirotecnici richiede risorse enormi e molta abilità, ma il loro splendore e la loro bellezza ripagano lo sforzo! Portami delle coins of ancestry e ti insegnerò a costruirli.",
  reward = "Grazie, $N. Questa è la ricetta dei grandi fasci pirotecnici. Possano le tue creazioni portare gioia e fortuna a chiunque alzi lo sguardo per ammirarle.",
}
T[8882] = {
  title = "Cluster Launcher",
  progress = "Per gli spettacoli di fuochi d'artificio più splendidi i fasci pirotecnici sono indispensabili, e vanno lanciati dai cluster launchers! Non è logico, allora, che tu impari i segreti per costruirli? Portami delle coins of ancestry e te li svelerò.",
  reward = "Ecco il tuo schema. Studialo con cura, e impara...$B$BBuona fortuna, $N. Possano le tue celebrazioni rivaleggiare con la Festa della Luna stessa!",
}
T[8883] = {
  title = "Valadar Starsong",
  desc = "Con il Lunar Festival invitation puoi andare a Moonglade! Ci troverai tanti festaioli, e nel villaggio di Nighthaven Valadar Starsong e sua sorella Fariel aspettano chi non vede l'ora di unirsi alla celebrazione.$B$BPassa dalla luce lunare superiore per arrivare a Moonglade e parla con Valadar Starsong: così scoprirai quali premi potresti vincere durante la festa!",
  obj = "Usa il Lunar Festival Invitation nella luce lunare per andare a Moonglade. Quando arrivi, parla con Valadar Starsong a Nighthaven.",
  reward = "$GBenvenuto:Benvenuta; a Nighthaven, $N, dove si tiene la Celebrazione della Luna! Di solito il nostro villaggio vive isolato, lontano dai popoli di Azeroth, ma in questi giorni di festa apriamo a tutti le braccia e il cuore.$B$BGoditi la visita, $N, e quando sarai $Gpronto:pronta; torna a parlare con me o con mia sorella.",
  en_title = "Valadar Starsong",
  en_obj = "Use your Lunar Festival Invitation in the moonlight to travel to Moonglade. Speak with Valadar Starsong in Nighthaven when you arrive.",
}
T[8893] = {
  title = "Il Super Egg-O-Matic",
  progress = "Il Super Egg-O-Matic, l'ultima invenzione di Curgle Cranklehop, è un macchinario davvero notevole.$B$BAppena ti avvicini al pannello di controllo, il Super Egg-O-Matic si mette a scoppiettare all'impazzata.",
  reward = "Metti l'hippogryph egg nella macchina, che risponde con una serie di bip e strani rumori meccanici.$B$BA quanto pare l'Ovometro ha pesato, misurato e impacchettato l'uovo. Questo sì che è un servizio rapido!",
}
T[8897] = {
  title = "Carissima Colara,",
  desc = "Devo stare di guardia qui alla porta, ma sono sempre in pensiero per la mia innamorata, Colara. La vedo solo per qualche ora, quando mi va bene, e poi, insomma, guardami: prendo la paga di un ufficiale di basso grado e da un giorno all'altro potrebbero mandarmi al fronte.$B$BE se si dimenticasse di me? In città ci sono tanti uomini. Tanti uomini ricchi.$B$BComunque, ho buttato giù qualcosa... niente di che, ma se glielo portassi tu da parte mia, te ne sarei grato.",
  obj = "Consegna la Carefully Penned Note del Tenente Heldric a Colara Dean, fuori dalla banca di Stormwind.",
  progress = "$GCiao, bel ragazzo. Posso fare qualcosa per te?:Oh, santo cielo! Posso fare qualcosa per te?;",
  reward = "Oh, che dolce! Non mi aveva mai mandato niente prima d'ora. Dici che fa sul serio?$B$BColara Heldric? Suona bene, direi. Oh, ma sto correndo troppo. Grazie.",
  en_title = "Dearest Colara,",
  en_obj = "Deliver Lieutenant Heldric's Carefully Penned Note to Colara Dean outside the bank in Stormwind.",
}
T[8898] = {
  title = "Carissima Colara,",
  desc = "L'ultima volta che sono passato da Stormwind per affari della banca ho conosciuto una ragazza, e mi ha rubato il cuore. Adesso non riesco a togliermela dalla testa! Vorrei mandarle questo messaggio — l'ho riscritto dodici volte!$B$BDi questi tempi la posta è così piena che voglio essere sicuro che arrivi.$B$BSe vai da quelle parti, mi daresti una mano?",
  obj = "Consegna la Creased Letter a Colara Dean, fuori dalla banca di Stormwind.",
  progress = "Ciao, $Gbello:bella;. Ti serve qualcosa?",
  reward = "Tormek? Oh sì, me lo ricordo bene. Che bella barba aveva, e sotto un bel sorriso.$B$BAh, non ci posso credere che si sia ricordato di me!",
  en_title = "Dearest Colara,",
  en_obj = "Deliver the Creased Letter to Colara Dean outside the bank in Stormwind.",
}
T[8899] = {
  title = "Carissima Colara,",
  desc = "Come descrivere la sua bellezza? Migliaia di anni di parole, eppure non so cosa dire.$B$BQuesti mortali confondono la mente e ci riducono a sciocchi balbettanti.$B$BHo fissato queste righe troppo a lungo. Non riesco a cavarne niente di più eloquente. No, deve riceverla subito, o qualche altro pretendente le farà di certo girare la testa.",
  obj = "Consegna l'Immaculate Letter a Colara Dean, fuori dalla banca di Stormwind.",
  progress = "Ehi, ciao, $Gbello:bella;. Posso fare qualcosa per te?",
  reward = "Non ho mai ricevuto niente del genere. Che cosa deliziosa!",
  en_title = "Dearest Colara,",
  en_obj = "Deliver the Immaculate Letter to Colara Dean outside the bank in Stormwind.",
}
T[8900] = {
  title = "Carissima Elenia,",
  desc = "Era così triste. Me ne sono accorto quando sono riuscito a guardare oltre la sua condizione. Voglio dire, sembrava triste — tu non lo saresti?$B$BMa quando le ho parlato, tra noi è nato un legame. Non credevo che qualcuno potesse capire cosa pensavo, eppure lei ci riusciva.$B$BQuando l'ho raccontato agli altri mi hanno riso dietro, così non le ho più parlato. Ma mi manca. Le porteresti questo messaggio da parte mia? Voglio essere sicuro che finisca nelle sue mani.",
  obj = "Consegna lo Slightly Creased Note a Elenia Haydon vicino alla banca di Undercity.",
  progress = "Oh, e a cosa devo il piacere?",
  reward = "Da un orco non ti aspetteresti che sappia esprimersi così bene. Certo, finora non abbiamo mai avuto davvero l'occasione di conoscerli. Grazie di avermelo portato.",
  en_title = "Dearest Elenia,",
  en_obj = "Deliver the Slightly Creased Note to Elenia Haydon near the bank in the Undercity.",
}
T[8901] = {
  title = "Carissima Elenia,",
  desc = "Hai mai conosciuto l'amore, giovane? Io non sapevo cosa fosse fino a poco tempo fa, quando ho incontrato una ragazza di Undercity, Elenia. È già raro che uno della mia gente si interessi a qualcuno che non sia dei nostri, figuriamoci a una dei Forsaken.$B$BMa ora penso a lei giorno e notte.$B$BSe puoi, le porteresti questa lettera? Voglio che venga qui a Mulgore. Spero che dica di sì.",
  obj = "Consegna la Carefully Written Letter a Elenia Haydon vicino alla banca di Undercity.",
  progress = "Oh, a cosa devo questo piacere?",
  reward = "Che parole gentili mi scrive Temma. Ma, per quanto mi commuovano, l'amore di un tauren non posso prenderlo in considerazione. Siamo troppo diversi, nei pensieri, nel corpo e nella mente.$B$BPer fortuna questi suoi pensieri non devo riceverli di persona. Non sopporterei di spezzargli il cuore.",
  en_title = "Dearest Elenia,",
  en_obj = "Deliver the Carefully Written Letter to Elenia Haydon near the bank in the Undercity.",
}
T[8902] = {
  title = "Carissima Elenia,",
  desc = "Una vita fa ero promesso sposo di Elenia, il mio amore d'infanzia. Erano anni che non pensavo più a lei, ma ultimamente mi torna spesso in mente.$B$BForse, nonostante tutto quello che è successo, nelle nostre vite può esserci ancora un po' di spazio per il nostro amore.$B$BSono sicuro che anche lei è cambiata. Potresti consegnarle questa lettera da parte mia? Sono troppo nervoso per dargliela di persona.",
  obj = "Consegna la Lovingly Composed Letter a Elenia Haydon vicino alla banca di Undercity.",
  progress = "Oh, e a cosa devo questo piacere?",
  reward = "Mi riporta alla mente ricordi di una vita fa, $N. Elenia Tor. Così mi sarei chiamata, sai. Ci saremmo sposati con una bella cerimonia sulle rive del lago. Poi lui sarebbe andato in pensione e ci saremmo presi una fattoria dove passare la vecchiaia.$B$BSogni semplici, allora.$B$BMa se mi vedesse ora, dubito che riuscirebbe anche solo a scorgere in me Elenia. Solo carne fredda e un cuore morto...",
  en_title = "Dearest Elenia,",
  en_obj = "Deliver the Lovingly Composed Letter to Elenia Haydon near the bank in the Undercity.",
}
T[8903] = {
  title = "Amore Pericoloso",
  desc = "C'è qualcosa di innaturale in questa epidemia d'amore. Non è decoroso, è un pugno nell'occhio e, nel peggiore dei casi, potrebbe minacciare la sicurezza dell'Alleanza stessa.$B$BPensaci: e se le guardie fossero cadute vittime di questo strano male? Bisogna fare qualcosa.$B$BVai da una delle guardie qui a Stormwind e scopri se si sono lasciate travolgere da questa sciocchezza.",
  obj = "Procurati uno Stormwind Guard's Card e portalo ad Aristan Mottar a Stormwind.",
  progress = "Avevo ragione a preoccuparmi? Le guardie sono afflitte da questo mal d'amore?",
  reward = "Allora è vero. È incredibile. Come può essere successo? Fammi pensare un momento. Dietro dev'esserci una ragione.",
  en_title = "Dangerous Love",
  en_obj = "Get a Stormwind Guard's Card and return it to Aristan Mottar in Stormwind.",
}
T[8904] = {
  title = "Amore Pericoloso",
  desc = "C'è qualcosa di innaturale in questa epidemia d'amore. È disgustosa e potrebbe diventare una minaccia per tutti noi, perché ci fa abbassare la guardia.$B$BÈ già grave che tanti dei nostri si siano lasciati prendere da questo comportamento ridicolo. Ma credo che il contagio abbia raggiunto perfino i nostri guardiani, che dovrebbero essere immuni a cose del genere.$B$BTrova uno dei nostri guardiani e scopri se questa sciocchezza ha colpito anche loro.",
  obj = "Prendi un Guardian's Moldy Card e portalo a Fenstad Argyle a Undercity.",
  progress = "Facevo bene a preoccuparmi? Quegli idioti dei nostri guardiani hanno ceduto?",
  reward = "Dunque è vero. È incredibile. Com'è potuto succedere? Lasciami riflettere un momento. Dietro tutto questo dev'esserci un motivo.",
  en_title = "Dangerous Love",
  en_obj = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity.",
}
T[8905] = {
  title = "Una Proposta Seria",
  desc = "$GBen trovato:Ben trovata;, $C. Ho qualcosa che potrebbe interessarti.$B$BHo con me un'armatura molto simile a quella che porta chi fa il tuo mestiere, ma di qualità ben superiore. Per un piccolo favore sarei disposta a darti i suoi bracciali in cambio di quelli comuni.$B$BIl sangue dei frostsabers e degli orsi che abitano Winterspring ha delle proprietà che adesso mi servono. Portamene un bel campione, con i bracciali e un po' d'oro: vedrai che ne varrà la pena.",
  obj = "Ottieni 15 Winterspring Blood Samples e 20 monete d'oro e portali, insieme a un set di Wildheart Bracers, a Deliana a Ironforge.",
  progress = "Mi hai portato quello che ti ho chiesto, $N?",
  reward = "Eccellente! Allora procediamo con lo scambio. Mi costa separarmi da questa splendida armatura, ma temo che a breve non mi servirà.$B$BSe ti va di fare altri lavori per me, potrei essere disposta a cederti anche il resto dei pezzi.",
}
