T[8921] = {
  title = "L'Ectoplasmic Distiller",
  desc = "Ah, ti serve il mio ultimo progetto... l'extra-dimensional ghost revealer! Peccato che io sia rimasto senza fondi e senza manodopera.$B$BSei $Gdisposto:disposta; a darmi una mano? Eccellente! Prima di tutto dobbiamo costruire un dispositivo che raccolga il tessuto stesso della morte! Mettere insieme un ectoplasmic distiller non sarà facile, $N.$B$BMi dovrai portare un convertitore d'arcanite, delle greater eternal essences e dello stonescale oil. Per fare un filtro, poi, mi servirà della volcanic ash dalle pozze di lava delle Burning Steppes.",
  obj = "Torna da Mux Manascrambler a Gadgetzan con 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash e 40 monete d'oro.",
  progress = "Lo so che i materiali costano un po'... ma ti prometto che serviranno tutti, fino all'ultimo!",
  reward = "Proprio i materiali che mi servivano, $N, e arrivano anche al momento giusto!$B$BFra pochi istanti il tuo distillatore sarà pronto! Intanto prendi questo, come ricompensa per avermi aiutato con il mio progetto.",
}
T[8922] = {
  title = "Un Dispositivo Soprannaturale",
  desc = "Devo trovare il modo di parlare con Anthion Harmon... anzi, per essere precisi, con il suo fantasma!$B$BConosco un ingegnere che ha uno strano interesse per il soprannaturale. Sostiene di saper costruire una macchina che gli permette di parlare con i morti!$B$BIl sangue che hai raccolto era per lui: vai a Gadgetzan e portaglielo, come pagamento per i suoi servigi!",
  obj = "Porta il Sealed Blood Container a Mux Manascrambler, dentro Gadgetzan, in Tanaris.",
  progress = "Hai qualcosa per me?",
  reward = "Eccellente! Stavo giusto finendo le scorte!$B$BTi manda Deliana, dici?",
}
T[8923] = {
  title = "Un Dispositivo Soprannaturale",
  desc = "Devi essere $Gcoraggioso:coraggiosa; davvero, per essere $Grimasto:rimasta; dopo quello che è successo. O forse ti ha incuriosito il pezzo d'armatura che ti ho dato. Se vuoi ancora aiutarmi, ce n'è dell'altro.$B$BI campioni di veleno che hai raccolto sono per Mux Manascrambler, un ingegnere che conosco e che si interessa di soprannaturale. Il suo ultimo progetto è un dispositivo per comunicare con i morti! Contattare Anthion e scoprire di più sulla mia situazione è l'ultima speranza che mi resta.",
  obj = "Porta il Sealed Venom Container a Mux Manascrambler, a Gadgetzan.",
  progress = "Vuoi parlarmi?",
  reward = "Eccellente! Stavo giusto finendo le scorte!$B$BTi manda Mokvar, dici?",
}
T[8924] = {
  title = "A Caccia di Ectoplasma",
  desc = "Un bel lavoro d'ingegneria, modestia a parte! Temo che ti toccherà viaggiare un po' per trovare i non morti incorporei che ci servono.$B$BVedi, a seconda del clima il tessuto spettrale dei morti prende consistenze diverse. Gli elfi della notte tormentati di Silithus, gli spiriti degli altinati di Winterspring e i fantasmi e le banshee delle Eastern Plaguelands dovrebbero darci i vari tipi di ectoplasma che cerchiamo. Prima di raccoglierli, ricordati di piazzare il distillatore lì vicino!",
  obj = "Usa l'Ectoplasmic Distiller vicino ai non morti incorporei per raccogliere 12 Scorched Ectoplasms a Silithus, 12 Frozen Ectoplasms a Winterspring e 12 Stable Ectoplasms nelle Eastern Plaguelands. Riportali insieme all'Ectoplasmic Distiller a Mux Manascrambler, a Gadgetzan.",
  progress = "L'hai raccolto, l'ectoplasma, $R?",
  reward = "Sì, questi vanno benissimo!$B$BAttingendo alle energie ultraterrene di queste sostanze potremo metterci in contatto con quelli la cui anima non ha ancora lasciato del tutto questo mondo!",
}
T[8925] = {
  title = "Una Fonte di Energia Portatile",
  desc = "Ora dovremo trovare una fonte di energia stabile e portatile per tenere attivo l'ectoplasma. Ho sentito parlare di un possente elementale, Magma Lord Bokk, che ha per cuore un potente magma core — una fonte inesauribile di calore!$B$BPare che si trovi nelle Burning Steppes, a sud di Blackrock Mountain. Portami il magma core e avremo carburante a sufficienza per alimentare l'extra-dimensional ghost revealer!",
  obj = "Trova Magma Lord Bokk nelle Burning Steppes, prendi il suo Magma Core e portalo a Mux Manascrambler, a Gadgetzan.",
  progress = "Hai trovato il Signore del Magma, $N?",
  reward = "Ce l'hai fatta! Questo di sicuro darà energia a sufficienza per alimentare l'extra-dimensional ghost revealer!",
}
T[8926] = {
  title = "Il Giusto Compenso",
  desc = "Hai mantenuto la parola e hai portato il congegno costruito da Mux. Credo che ti spetti una ricompensa, se voglio che tu continui a darti da fare per salvarmi la pelle. Portami la cintura e i guanti che vuoi migliorare. Ti prometto che quelli che ti darò in cambio saranno di gran lunga superiori.",
  obj = "Porta una Wildheart Belt e un paio di Wildheart Gloves a Deliana, a Ironforge.",
  progress = "Sei $Gpronto:pronta; a fare lo scambio?",
  reward = "Tu hai mantenuto la tua parte del patto, io manterrò la mia.$B$BRicorda solo che i pezzi migliori li terrò io finché non avrai finito il lavoro.",
}
T[8927] = {
  title = "Il Giusto Compenso",
  desc = "Ti sei $Gdimostrato:dimostrata; una persona molto affidabile, $N. Confido che mi aiuterai a uscire da questa brutta situazione, ma per me è più saggio ricompensarti in base ai risultati.$B$BPer ora prenderò la tua cintura e i tuoi guanti e te ne darò altri in cambio. Se arriveremo entrambi fino in fondo, ti metterò a disposizione il resto dei pezzi.",
  obj = "Porta una Wildheart Belt e un paio di Wildheart Gloves a Mokvar, a Orgrimmar.",
  progress = "Sei $Gpronto:pronta; per lo scambio?",
  reward = "Il nostro accordo resta valido. Ricorda solo che questo è appena un assaggio di ciò che ti aspetta. Liberami da questo destino maledetto e ti ricompenserò con oggetti davvero potenti.",
}
T[8928] = {
  title = "Un Mercante Losco",
  desc = "Con il nucleo avremo carburante a sufficienza per alimentare il nostro dispositivo; adesso dobbiamo solo costruire una verga capace di incanalare quell'energia senza fondersi.$B$BA Winterspring ho incontrato un imp che vendeva merci esotiche di ogni genere. Aveva una verga elementale che farebbe proprio al caso nostro. Mi mangio ancora le mani per non averla comprata.$B$BVive in una grotta all'ingresso della Darkwhisper Gorge. Intrufolati là dentro e cerca di trovarlo.$B$BE bada che non ti chieda più di quaranta monete d'oro: è il prezzo che ha fatto a me!",
  obj = "Cerca un imp dentro una grotta all'ingresso della Darkwhisper Gorge, nel sud di Winterspring, compra una Fel Elemental Rod e torna da Mux Manascrambler a Gadgetzan.",
  progress = "Sei $Griuscito:riuscita; a trovare l'imp nella Darkwhisper Gorge?",
  reward = "Ce l'hai fatta! Questa verga andrà benissimo. Adesso mettiamo insieme il tutto...",
}
T[8929] = {
  title = "In Cerca di Anthion",
  desc = "Bene, non ci resta altro da fare che provare l'invenzione del goblin. Si dice che Anthion sia stato falciato dalle legioni di non morti di Stratholme mentre cercava di varcarne i cancelli.$B$BProva a usare il congegno lì e scopri tutto quello che sapeva Anthion.",
  obj = "Usa l'Extra-Dimensional Ghost Revealer all'ingresso di Stratholme e parla con il fantasma di Anthion Harmon.",
  reward = "È stata Deliana a mandarti da me? Farò del mio meglio per aiutarti, ma prima devo chiederti un grande favore.",
}
T[8930] = {
  title = "Alla Ricerca di Anthion",
  desc = "Molto bene, $N. Non resta che mettere alla prova l'invenzione del goblin. Si dice che Anthion sia stato ucciso dalle legioni di non morti di Stratholme mentre cercava di varcarne i cancelli.$B$BProva a usare il congegno sul posto e vedi se riesci davvero a parlare con i morti!",
  obj = "Usa l'Extra-Dimensional Ghost Revealer all'ingresso di Stratholme e parla con il fantasma di Anthion Harmon.",
  reward = "È stato Mokvar a mandarti da me? Farò del mio meglio per aiutarti, ma prima devo chiederti un grande favore.",
}
T[8931] = {
  title = "Il Giusto Compenso",
  desc = "Hai mantenuto la parola e hai portato il congegno costruito da Mux. Credo che ti spetti una ricompensa, se voglio che tu continui a darti da fare per salvarmi la pelle. Portami una cintura comune e un paio di guanti che vuoi migliorare.",
  obj = "Porta una Beaststalker's Belt e un paio di Beaststalker's Gloves a Deliana, a Ironforge.",
  progress = "Sei $Gpronto:pronta; a fare lo scambio?",
  reward = "Tu hai mantenuto la tua parte del patto, io manterrò la mia.$B$BRicorda solo che i pezzi migliori li terrò io finché non avrai finito il lavoro.",
}
