T[8942] = {
  title = "Giusto Compenso",
  desc = "Ti sei $Gdimostrato:dimostrata; una persona molto affidabile, $N. Anche se sono sicuro che mi aiuterai a uscire da questa difficile situazione, sarebbe saggio ricompensarti in base a quello che farai.$B$BPer ora ti cambierò la cintura e i guanti. Se arriveremo in fondo tutti e due, ti metterò a disposizione gli altri pezzi.",
  obj = "Porta un Cord of the Elements e un paio di Gauntlets of the Elements a Mokvar a Orgrimmar.",
  progress = "Sei $Gpronto:pronta; per lo scambio?",
  reward = "Il nostro accordo resta valido. Ricorda però: questo non è che un assaggio di ciò che ti aspetta. Liberami da questo destino maledetto e ti ricompenserò con oggetti di grandissimo potere.",
}
T[8943] = {
  title = "Il Giusto Compenso",
  desc = "Ti sei $Gdimostrato:dimostrata; una persona molto affidabile, $N. Confido che mi aiuterai a uscire da questa brutta situazione, ma per me è più saggio ricompensarti in base ai risultati.$B$BPer ora prenderò la tua cintura e i tuoi guanti e te ne darò altri in cambio. Se arriveremo entrambi fino in fondo, ti metterò a disposizione il resto dei pezzi.",
