T[8945] = {
  title = "La Supplica del Morto",
  desc = "Ti darò le informazioni che chiedi, $N. Ma ci sono questioni più urgenti.$B$BLa feccia non morta al servizio di Rivendare ha preso prigioniera la mia amata moglie.$B$BMi ero opposto con forza alla sua decisione di unirsi alla sciocca crociata dell'Argent Dawn, ma ormai non ha più importanza. Devi finire ciò che ho tentato di fare, devi strappare Ysida dalle grinfie del Barone!",
  obj = "Entra a Stratholme e salva Ysida Harmon da Baron Rivendare.",
  progress = "Dimmi, Ysida è viva?",
  reward = "Grazie per avermi salvata... temevo per la mia vita. Ti prego, accetta questo dono come piccolo segno della mia gratitudine.$B$BAnthion è... no... non può essere...",
}
T[8946] = {
  title = "Prova di Vita",
  desc = "Che il mio amato sia morto mentre cercava di salvarmi è il più crudele dei destini. Eppure tu dici di poter parlare con lui.$B$BPortagli questo medaglione come prova che sto bene. Non deve indugiare in questo mondo; il mio cuore non potrebbe sopportarlo.$B$BAddio, $N. Ti sarò debitrice per sempre.",
  obj = "Porta il Ysida's Locket ad Anthion Harmon, a Eastern Plaguelands.",
  progress = "Ysida... è viva?",
  reward = "Quel medaglione... l'hai trovata! Finalmente posso riposare in pace.$B$BOra risponderò a tutte le domande che vorrai farmi, $N. Ma sbrigati, non mi resta molto tempo in questo mondo.",
}
T[8947] = {
  title = "La Strana Richiesta di Anthion",
  desc = "Non avevamo capito quanto fosse importante il medaglione di Valthalak, così lo abbiamo spartito insieme al resto del bottino. Il primo pezzo l'ha preso un nano di nome Theldren. Ho cercato di riprenderglielo e lui mi ha quasi ammazzato di botte. Dovrai prenderti il frammento con la forza.$B$BL'ultima volta che ho sentito parlare di lui, era diventato un gladiatore dei nani Dark Iron. Convincerlo ad affrontarti, però, non sarà proprio semplice.$B$BProcurami questi materiali. Ti serviranno.",
  obj = "Porta 3 Dark Iron Bars, 20 Enchanted Leather, 3 Mooncloth e 4 Cured Rugged Hides ad Anthion Harmon, a Eastern Plaguelands.",
  progress = "Hai procurato i materiali che ti ho chiesto, $N?",
  reward = "Eccellente. Li trasmuterò in qualcosa di più adatto alle nostre necessità.",
}
T[8948] = {
  title = "Il Vecchio Amico di Anthion",
  desc = "Theldren non è tipo da accettare di buon grado uno scontro leale. Ho preparato questo stendardo con i colori della sua famiglia.$B$BCon un po' di stregoneria in più, diventerà una provocazione a cui non saprà resistere.$B$BUna mia vecchia conoscenza, Falrin, sa esattamente cosa fare. Ha un modo tutto suo di... irritare la gente. Lo troverai nella biblioteca di Dire Maul.",
  obj = "Porta il Banner of Provocation incompleto a Falrin Treeshaper nella biblioteca di Dire Maul.",
  progress = "Parla, $Gstraniero:straniera;, non vedi che sono occupato?",
  reward = "Ti manda Anthion, dici? Lo credevo morto. Beh, immagino di averne sentite di più strane in vita mia.$B$BMolto bene, allora. Cosa vuoi che faccia con questo stendardo?",
}
T[8949] = {
  title = "La Vendetta di Falrin",
  desc = "Sì, è vero che conosco l'incantamento che ti serve, $C. Ma non sono tipo da concedere favori gratuitamente, anche se ti ha mandato qui un vecchio amico.$B$BNon provo altro che odio e disprezzo per i nostri rozzi vicini ogre. E non faccio differenze: odio i seguaci di Omokk tanto quanto quelli di King Gordok.$B$BVoglio che tu li uccida. Uccidine tanti! Portami le perline che hanno al collo come prova del tuo lavoro. Fallo e parleremo della tua richiesta.",
  obj = "Raccogli 25 Ogre Warbeads dagli Ogres a Dire Maul o a Blackrock Spire e torna da Falrin Treeshaper, dentro Athenaeum di Dire Maul.",
  progress = "Mi hai fatto il favore che ti ho chiesto, $N?",
  reward = "Hmmm... strano, ma ripensando a mio fratello, ucciso da quei bruti, non mi sento affatto meglio.$B$BBe', tu hai rispettato la tua parte del patto. Vediamo cosa posso fare per te.",
}
T[8950] = {
  title = "L'Incantamento dell'Istigatore",
  desc = "Applicare allo stendardo l'incantamento che ti serve non mi costa alcuna fatica, $N. Purtroppo non ho i materiali necessari, perché capita molto di rado che qualcuno chieda un sortilegio del genere.$B$BMi servirà l'essenza di uno dei fantasmi Eldreth che infestano queste sale, una manciata di Dark Runes di Scholomance e un po' di Large Brilliant Shards. Portami questi reagenti e farò quanto mi chiedi.",
  obj = "Porta quanto segue a Falrin Treeshaper, a Dire Maul: 1 Jeering Spectre's Essence, 4 Dark Runes e 8 Large Brilliant Shards.",
  progress = "Hai raccolto i materiali che mi servono, $N?",
  reward = "Sì, questi andranno benissimo. Quando avrò finito, la tua vittima accetterà la sfida, e nessuna forza al mondo potrà impedirlo.",
}
T[8951] = {
  title = "Le Parole di Commiato di Anthion",
  desc = "L'anima di Valthalak era custodita in questo amuleto. Accecati dall'avidità, lo abbiamo stoltamente diviso in tre parti, senza sapere quale maledizione ci attendeva.$B$BL'unico modo per fermare l'incantesimo di Valthalak è ricomporre il medaglione. Torna da Deliana e dille che Bodley è l'unica speranza che ha di trovare i pezzi mancanti. Parla con lei delle ricompense che hai concordato.$B$BIo, per una volta, riposerò in pace. Ti auguro tutta la fortuna del mondo; te ne servirà fino all'ultima goccia!",
  obj = "Torna da Deliana a Ironforge con un set composto da Wildheart Boots, un Wildheart Kilt e Wildheart Spaulders.",
  progress = "Sei $Gtornato:tornata;, $N. Devi raccontarmi tutto quello che hai scoperto. Ma prima occupiamoci della tua ricompensa.",
  reward = "Non posso credere che siamo praticamente spacciati, e tutto per colpa di uno stupido medaglione! E sei $Gsicuro:sicura; che Anthion abbia nominato Bodley?$B$BBe', hai fatto il tuo lavoro, quindi sbrighiamo la faccenda della ricompensa.",
}
