T[8959] = {
  title = "Le Parole di Commiato di Anthion",
  desc = "L'anima di Valthalak era custodita in questo amuleto. Accecati dall'avidità, lo abbiamo stoltamente diviso in tre parti, senza sapere quale maledizione ci attendeva.$B$BL'unico modo per fermare l'incantesimo di Valthalak è ricomporre il medaglione. Torna da Deliana e dille che Bodley è l'unica speranza che ha di trovare i pezzi mancanti. Parla con lei delle ricompense che hai concordato.$B$BIo, per una volta, riposerò in pace. Ti auguro tutta la fortuna del mondo; te ne servirà fino all'ultima goccia!",
  obj = "Torna da Deliana a Ironforge con un set composto da Boots of Valor, Legplates of Valor e Spaulders of Valor.",
  progress = "Sei $Gtornato:tornata;, $N. Devi raccontarmi tutto quello che hai scoperto. Ma prima occupiamoci della tua ricompensa.",
  reward = "Non posso credere che siamo praticamente spacciati, e tutto per colpa di uno stupido medaglione! E sei $Gsicuro:sicura; che Anthion abbia nominato Bodley?$B$BBe', hai fatto il tuo lavoro, quindi sbrighiamo la faccenda della ricompensa.",
}
T[8960] = {
  title = "Lo Sfortunato Destino di Bodley",
  desc = "Quindi dobbiamo recuperare il resto del medaglione? Trovare Bodley sarà un po' un grattacapo. È ripartito verso Blackrock Mountain per tentare di rientrare a Blackrock Spire e non è più tornato.$B$BTi consiglio di portare con te il congegno del goblin che rivela i fantasmi, perché temo che sia successo il peggio.",
  obj = "Recati a Blackrock Mountain e usa l'Extra-Dimensional Ghost Revealer per trovare Bodley vicino a Blackrock Spire.",
  reward = "Sono così felice che tu riesca a vedermi. Finalmente qualcuno con cui parlare!$B$BCi aiuterai, $N? Ci aiuterai a rimediare al torto che abbiamo commesso e a rimettere le cose a posto? Se è vero che hai già il Top Piece of Lord Valthalak's Amulet, credo di poterti indicare la strada giusta per ottenere le altre due parti, riunirle e mettere fine a tutto questo.$B$BOh, a proposito, ciao, mi chiamo Bodley. Piacere di conoscerti!",
}
T[8961] = {
  title = "Tre Re della Fiamma",
  desc = "Per evocare Lord Valthalak dobbiamo prima recuperare gli altri due terzi dell'amuleto. Per farlo ci servono un braciere e dei carboni speciali da bruciarci dentro.$B$BQuello che ci occorre ce l'hanno tre nobili del fuoco: Lord Incedius a Blackrock Depths, Pyroguard Emberseer a Blackrock Spire e The Duke of Cynders a Silithus. Prendi un pezzo dei resti di ciascuno, poi torna da me con un Hallowed Brazier, che puoi acquistare dall'Argent Dawn se hai la reputazione di Onorato presso di loro.",
  obj = "Raccogli l'Incendicite of Incendius, l'Ember of Emberseer e la Cinder of Cynders, insieme a un Hallowed Brazier, e portali a Bodley dentro Blackrock Mountain.",
  progress = "Accettare quell'ultimo incarico è stata una follia... la nostra rovina. Se solo non avessimo portato via senza saperlo lo spirito di Lord Valthalak, racchiuso nell'amuleto; se solo nel nostro gruppo di mercenari non ci fossero stati quegli ingordi che se lo sono spartito. Oggi sarei vivo, magari a buttar giù una birra o a lanciare in aria uno dei miei bambini.$B$B$N, non lasciare che l'avidità degli ignobili della nostra vecchia compagnia segni anche la tua fine.",
  reward = "Sono colpito, $C, ma non c'è tempo da perdere. Ti affiderò il prossimo compito, perché dovrai ancora procurarti qualche altro componente importante prima di poter procedere.$B$BTorna a parlarmi quando ti sentirai $Gpronto:pronta; per la sfida che ti attende.",
}
T[8962] = {
  title = "Componenti Importanti",
  desc = "Ascolta bene, $C. Il braciere ce l'abbiamo, e anche il modo per accenderlo: adesso ci manca ancora un componente di cui impregnarlo; qualcosa che faccia da fulcro e abbia abbastanza forza da attirare lo spirito del mio defunto ex compagno.$B$BMor Grayhoof, il più noto dei nostri druidi, aveva molti amici intimi nel Cenarion Circle, e alcuni sono caduti per mano dei silithid. Devi recuperare dei Druidical Remains dai silithid che popolano i dintorni di Hive'Regal, nel sud-est di Silithus.",
  obj = "Procurati i Druidical Remains e portali a Bodley, in Blackrock Mountain.",
  progress = "Sei già di ritorno, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Bel lavoro, $N. Adesso infonderò nel braciere l'essenza dei resti.$B$BOra non resta che scendere nella parte inferiore del Blackrock Spire, nella sala di War Master Voone, a Tazz'Alaor, e lì usare il braciere per evocare lo spirito corrotto del mio ex compagno, Mor Grayhoof. Finché qualcuno non gli toglierà il frammento d'amuleto, non potrà riposare.",
}
T[8963] = {
  title = "Componenti Importanti",
  desc = "Ascolta bene, $C. Il braciere ce l'abbiamo, e anche il modo per accenderlo: adesso ci manca ancora un componente di cui impregnarlo; qualcosa che faccia da fulcro e abbia abbastanza forza da attirare lo spirito della mia defunta ex compagna.$B$BIsalien, la nostra sacerdotessa, è cresciuta in Starbreeze Village, a Winterspring. Devi procurarti una Starbreeze Village Relic dai Frostmaul giants della Frostwhisper Gorge, nel sud di Winterspring: si sa che ogni tanto si spingono verso nord a fare incursioni.",
  obj = "Procurati una Starbreeze Village Relic e portala a Bodley, in Blackrock Mountain.",
  progress = "Sei già di ritorno, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Bel lavoro, $N. Adesso infonderò nel braciere l'essenza della reliquia.$B$BOra non resta che andare allo Shrine of Eldretharr, nell'ala est di Dire Maul, e lì usare il braciere per evocare lo spirito della mia ex compagna, Isalien. A corromperlo sono stati il frammento dell'amuleto di Valthalak che aveva con sé e la parte dell'anima di lui che vi è racchiusa.",
}
T[8964] = {
  title = "Componenti Importanti",
  desc = "Ascolta bene, $C. Il braciere ce l'abbiamo, e anche il modo per accenderlo: adesso ci manca ancora un componente di cui impregnarlo; qualcosa che faccia da fulcro e abbia abbastanza forza da evocare i resti dei miei defunti ex compagni.$B$BI fratelli Jarien e Sothos credevano nella via della Scarlet Crusade, e speravano di diventare cavalieri di quella spregevole organizzazione. Vai a Tyr's Hand, nelle Eastern Plaguelands, e recupera una Brilliant Sword of Zealotry dai pretoriani di laggiù.",
  obj = "Recupera una Brilliant Sword of Zealotry e portala a Bodley, in Blackrock Mountain.",
  progress = "Sei già di ritorno, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Bel lavoro, $N. Adesso infonderò nel braciere l'essenza della spada.$B$BOra non resta che entrare in The Crimson Throne, dentro The Scarlet Bastion di Stratholme, e lì usare il braciere per evocare i resti dei miei ex compagni, Jarien e Sothos. Possedere il frammento d'amuleto di Valthalak, con lo spirito di lui racchiuso dentro, ha distorto le loro anime ancora di più.",
}
T[8965] = {
  title = "Componenti Importanti",
  desc = "Ascolta bene, $C. Il braciere ce l'abbiamo, e anche il modo per accenderlo: adesso ci manca ancora un componente di cui impregnarlo; qualcosa che faccia da fulcro e abbia abbastanza forza da attirare lo spirito del mio defunto ex compagno.$B$BKormok, un negromante ogre che viaggiava con noi, si dilettava a evocare le anime dei morti esiliati della Purgation Isle, al largo della costa meridionale delle Hillsbrad Foothills. Vai laggiù e prendi dai loro resti delle Soul Ashes of the Banished.",
  obj = "Ottieni le Soul Ashes of the Banished e portale a Bodley, in Blackrock Mountain.",
  progress = "Sei già di ritorno, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Bel lavoro, $N. Adesso infonderò nel braciere l'essenza delle ceneri.$B$BOra non resta che entrare nella Scholomance, fino alla sala di Ras Frostwhisper, e lì usare il braciere per evocare lo spirito del mio ex compagno, Kormok. Il frammento d'amuleto, con dentro lo spirito di Valthalak, l'ha corrotto ancora di più, e non avrà pace finché non glielo strapperai con la forza.",
}
T[8966] = {
  title = "Il Left Piece of Lord Valthalak's Amulet",
  desc = "Il mio amico Mor Grayhoof è stato il primo a cadere vittima di un frammento dell'amuleto di Lord Valthalak che portava con sé, e della scheggia di spirito corruttore che vi è racchiusa. Dopo aver rubato il libro degli incantesimi e l'amuleto di Valthalak, siamo scappati dalla parte superiore del Blackrock Spire per salvarci la pelle, e durante la fuga Mor è precipitato nella parte inferiore della guglia.$B$BPiù tardi abbiamo scoperto che era sopravvissuto alla caduta, ma War Master Voone l'aveva catturato e torturato. Alcuni spectral assassins si sono intrufolati e l'hanno ucciso proprio sotto gli occhi di Voone.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Mor Grayhoof e uccidilo. Torna da Bodley, in Blackrock Mountain, con il Left Piece of Lord Valthalak's Amulet e il Brazier of Beckoning.",
  progress = "Allora, è fatta? Hai recuperato il frammento sinistro dell'amuleto di Lord Valthalak e dato finalmente pace allo spirito del mio vecchio compagno, Mor Grayhoof?",
  reward = "Hai fatto una gran cosa, $N. Ora uno spirito riposa in pace, ma prima di poterci lasciare tutto questo alle spalle c'è ancora molto lavoro da fare.$B$BPurtroppo non so dove si trovi chi è morto con addosso il frammento destro dell'amuleto. Ma non temere; in vita mi dilettavo di divinazione, perciò ho per te un altro compito, che ci permetterà di scovare l'ultimo frammento.",
}
T[8967] = {
  title = "Il Left Piece of Lord Valthalak's Amulet",
  desc = "Più tardi, mentre facevamo il possibile per sopravvivere, abbiamo saputo che Isalien, una sacerdotessa elfa della notte della nostra compagnia, era andata nell'antica città dei suoi avi, quella che oggi si conosce come Dire Maul. A quanto abbiamo capito, ci era andata per motivi personali, ma anche per svelare i segreti del frammento d'amuleto che portava con sé.$B$BNon ce l'ha fatta, però. Ci è arrivata voce che Alzzin the Wildshaper e le sue forze le hanno teso un'imboscata allo Shrine of Eldretharr.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Isalien e uccidila. Torna da Bodley, in Blackrock Mountain, con il Left Piece of Lord Valthalak's Amulet e il Brazier of Beckoning.",
  progress = "Non mi dirai che hai già salvato lo spirito di Isalien e recuperato il frammento sinistro dell'amuleto di Lord Valthalak, $N?",
  reward = "Grazie, $N, per aver dato riposo allo spirito di Isalien. Forse ora troverà la pace accanto alla sua dea. Ma se vogliamo uscire da questo bel pasticcio, c'è ancora molto lavoro che ci aspetta.$B$BPurtroppo non so dove si trovi chi è morto con addosso il frammento destro dell'amuleto. Ma non temere; in vita mi dilettavo di divinazione, perciò ho per te un altro compito, che ci permetterà di scovare l'ultimo frammento.",
}
T[8968] = {
  title = "Il Left Piece of Lord Valthalak's Amulet",
  desc = "Quando la nostra compagnia di mercenari si è sciolta, i fratelli Jarien e Sothos hanno deciso di unirsi alla Scarlet Crusade, e si sono portati via il Left Piece of Lord Valthalak's Amulet. Bella liberazione, dico io, ma quel frammento dobbiamo riaverlo.$B$BDa quel che siamo riusciti a capire, li ha uccisi Grand Crusader Dathrohan in persona, perché non avevano superato i riti d'iniziazione nella sua sala dello Scarlet Bastion.$B$BIn ogni caso, quel frammento d'amuleto dovremo recuperarlo noi... cioè tu.",
  obj = "Usa il Brazier of Beckoning per evocare Jarien e Sothos e uccidili. Torna da Bodley, in Blackrock Mountain, con il Left Piece of Lord Valthalak's Amulet e il Brazier of Beckoning.",
  progress = "Mi stai dicendo, $C, che hai già dato pace alle anime di quei due sciocchi e recuperato il frammento sinistro dell'amuleto di Lord Valthalak?",
  reward = "Immagino sia meglio così, che le anime di quei due abbiano finalmente trovato pace, anche se da vivi non mi andavano a genio. Comunque, abbiamo quello che cercavamo, ed è proprio un bene!$B$BPurtroppo non so dove si trovi chi è morto con addosso il frammento destro dell'amuleto. Ma non temere; in vita mi dilettavo di divinazione, perciò ho per te un altro compito, che ci permetterà di scovare l'ultimo frammento.",
}
T[8969] = {
  title = "Il Left Piece of Lord Valthalak's Amulet",
  desc = "Abbiamo quello che ci serve, quindi è ora di parlare di chi evocherai.$B$BPer essere un ogre, Kormok non era male, finché non si è dato alla negromanzia. Da allora, per quasi tutti nella compagnia, l'aria si è fatta inquietante. Così nessuno si è stupito quando ha preso il suo frammento d'amuleto ed è tornato nella sua nuova casa, la Scholomance.$B$BMa nemmeno lì, o forse lì meno che mai, era al sicuro dagli spectral assassins, che l'hanno ucciso proprio sotto gli occhi del suo maestro, Ras Frostwhisper.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Kormok e uccidilo. Torna da Bodley, in Blackrock Mountain, con il Left Piece of Lord Valthalak's Amulet e il Brazier of Beckoning.",
  progress = "Se sei $Gtornato:tornata; con il frammento sinistro dell'amuleto, $N, i miei complimenti. Altrimenti, ti prego, occupatene, perché non c'è tempo da perdere, te lo assicuro!",
  reward = "Ottimo lavoro, $N! Per essere un ogre, Kormok non era poi così male, almeno finché era vivo, e spero che trovi il riposo che si merita. Ma c'è altro lavoro che ci aspetta.$B$BPurtroppo non so dove si trovi chi è morto con addosso il frammento destro dell'amuleto. Ma non temere; in vita mi dilettavo di divinazione, perciò ho per te un altro compito, che ci permetterà di scovare l'ultimo frammento.",
}
T[8970] = {
  title = "Vedo l'Alcaz Island nel Tuo Futuro...",
  desc = "Come dicevo, $C, quando ero vivo ho accarezzato l'idea di fare l'indovino. Ma ci si guadagnava meno di quanto potresti pensare, soprattutto perché è un mestiere pericoloso e i reagenti sono rari e cari. Comunque ne so abbastanza per localizzare l'ultimo frammento dell'amuleto e, con quello, lo spirito del mio ex compagno.$B$BEd è qui che entri in gioco tu, $N. Devi andare all'Alcaz Island, al largo della costa della Dustwallow Marsh, e raccogliere del Bloodkelp dai naga Strashaz che ci vivono.",
  obj = "Raccogli 20 Bloodkelp dai naga Strashaz e poi torna da Bodley, in Blackrock Mountain.",
  progress = "Mi serve del Bloodkelp, $N, un bel mucchio, per alimentare i miei incantesimi di divinazione. Per raccoglierlo all'Alcaz Island probabilmente dovrai portarti dietro almeno un paio di amici... quegli Strashaz sono dei tipacci!",
  reward = "A dire il vero, $N, mi sorprende che tu sia $Gtornato:tornata; $Gtutto intero:tutta intera;. Del resto, immagino che ormai l'Alcaz Island sia l'ultimo dei tuoi problemi.$B$BBene, dammi un momento... con la divinazione non basta schioccare le dita per avere risposte precise.",
}
T[8977] = {
  title = "Ritorno da Deliana",
  desc = "È stato un piacere lavorare con te, $N. Ecco il prodotto finito.$B$BSpero che ti serva per quello che stai facendo. E se non ti dispiace, spargi la voce: qualche cliente in più non guasterebbe!",
  obj = "Porta l'Extra-Dimensional Ghost Revealer a Deliana a Ironforge.",
  progress = "Sei $Gtornato:tornata;?",
  reward = "Eccellente! Ben fatto, $N. Non so se fidarmi del lavoro del goblin, ma non ho altra scelta.",
}
T[8978] = {
  title = "Ritorno da Mokvar",
  desc = "È stato un piacere lavorare con te, $N. Ecco il prodotto finito.$B$BSpero che ti serva per quello che stai facendo. E se non ti dispiace, spargi la voce: qualche cliente in più non guasterebbe!",
  obj = "Torna da Mokvar a Orgrimmar con l'Extra-Dimensional Ghost Revealer.",
  progress = "Sei $Gtornato:tornata; con il dispositivo?",
  reward = "Sei $Gtornato:tornata; con il dispositivo! Mi colpisce la tua dedizione, $N. Ottimo lavoro.",
}
T[8979] = {
  title = "L'Intuizione di Fenstad",
  desc = "Credo di aver capito il motivo degli strani comportamenti recenti. Hai sentito la nuova fragranza nell'aria, che sovrasta il fetore dei canali? Le nuove acque di colonia e i nuovi profumi che vanno tanto di moda?$B$BUna qualche alchimia immonda ci ha annebbiato la mente.$B$BC'è un solo modo per esserne certi — porta una bottiglia di acqua di colonia e una di profumo alla mia amica, Apothecary Zinge. La Royal Apothecary Society scoprirà la verità.$B$BAl tuo ritorno ti rimborserò l'acquisto.",
  obj = "Porta 1 Cologne Bottle e 1 Perfume Bottle ad Apothecary Zinge in Undercity's Apothecarium.",
  progress = "Come posso esserti utile?",
  reward = "Un'altra delle ossessioni di Fenstad, vedo. Crede forse che la Royal Apothecary Society non abbia niente di meglio da fare che stare dietro alle sue piccole indagini?$B$BE va bene, lo accontenterò ancora una volta.",
  en_title = "Fenstad's Hunch",
  en_obj = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Apothecary Zinge in the Undercity's Apothecarium.",
}
T[8980] = {
  title = "Il Referto di Zinge",
  desc = "Questa non me l'aspettavo. Sembra che Fenstad abbia davvero fiutato qualcosa, dopotutto. Ho trovato tracce di sostanze usate nelle pozioni per il controllo mentale.$B$BNon è insolito che i profumi ne contengano un po', ma alcuni degli ingredienti che ho rilevato... Questa è alchimia seria, all'altezza di un membro della Royal Apothecary Society.",
  obj = "Torna da Fenstad Argyle, fuori dalla banca a Undercity.",
  reward = "Dunque avevo ragione. Non c'è tempo da perdere. Dobbiamo scoprire da dove vengono queste fragranze contaminate.$B$BEcco il rimborso per l'acqua di colonia e il profumo.",
  en_title = "Zinge's Assessment",
  en_obj = "Return to Fenstad Argyle outside the bank in the Undercity.",
}
T[8981] = {
  title = "Fare Regali",
  progress = "Sei $Gvenuto:venuta; a consegnare al tuo capo preferito un regalo d'amore e di adorazione?",
  reward = "Splendido! Splendido! Lo metto nel mucchio insieme agli altri regali.$B$BNon pensavo che ne arrivassero così tanti! Devi amarli davvero, i tuoi capi.$B$BE adesso uno in più nel conteggio...",
  en_title = "Gift Giving",
}
T[8982] = {
  title = "Risalire alla Fonte",
  desc = "Dobbiamo scoprire chi è il fornitore. Ho visto Apothecary Katrina con una bottiglia di quel profumo infilata nello zaino. Mi ha detto di averla comprata da Norman, il locandiere.",
  obj = "Parla con Innkeeper Norman a Undercity.",
  reward = "Ah sì, le scorte di profumo e acqua di colonia mi sono arrivate da poco. Non so per quanto riuscirò a tenerle sugli scaffali — sembra che nessuno ne abbia mai abbastanza.$B$BSe vuoi saperlo, io non ci trovo niente di speciale.",
  en_title = "Tracing the Source",
  en_obj = "Speak with Innkeeper Norman in the Undercity.",
}
T[8983] = {
  title = "Risalire alla Fonte",
  desc = "C'è qualcosa che non va nella mia merce? Be', non avevo mai visto tanta gente desiderare qualcosa con tale insistenza.$B$BHo comprato le scorte da una mercante di nome Mara Rennick. È nuova in città.$B$BHa detto che doveva consegnare dei prodotti al sarto del Mage Quarter.",
  obj = "Parla con Mara Rennick nella bottega del sarto in Undercity's Mage Quarter.",
  reward = "Temo di aver venduto tutte le scorte di profumo e acqua di colonia a Norman, il locandiere. Se ne vuoi un po', dovresti parlare con lui — sempre che gliene sia rimasto.$B$BPerò dovresti fare in fretta. Credo che troverai $Gl'acqua di colonia:il profumo; irresistibile.",
  en_title = "Tracing the Source",
  en_obj = "Speak with Mara Rennick at the tailor's shop in the Undercity's Mage Quarter.",
}
T[8984] = {
  title = "La Fonte Svelata",
  desc = "Senti, quello che fa uno speziale rinnegato non mi riguarda. Se sta mandando all'aria i nostri sforzi, allora sarò io la prima a indicarti la giusta strada$B$BSe è innocente, non ha niente da nascondere, giusto?$B$BHo comprato la merce da Apothecary Staffron Lerent. Lavora in un luogo isolato oltre il Ravenholdt Manor, sulle colline sopra Hillsbrad. A dirti la verità, mi è sembrato un po' strano.",
  obj = "Trova Apothecary Staffron Lerent in Hillsbrad Foothills, oltre Ravenholdt Manor.",
  reward = "Sì, quelle fragranze le ho create io. Un profumo meraviglioso, non trovi? Irresistibile.$B$BQuando i guerrieri dell'Alleanza e dell'Orda saranno tutti in preda a questi sentimenti d'amore, non avranno più la forza di fermare l'ascesa dello Shadow Council.$B$BSaranno indeboliti, impreparati. Preoccupati per i loro cari, perderanno mordente.$B$BLa soluzione era così semplice. Perché ci ho messo tanto a trovarla? Il punto debole di tutti è il cuore. E non c'è nulla che tu possa fare per fermare l'inevitabile.",
  en_title = "The Source Revealed",
  en_obj = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills past Ravenholdt Manor.",
}
T[8985] = {
  title = "Altri Componenti Importanti",
  desc = "$C, ascolta bene. Ora che sappiamo dove si trova l'ultimo frammento dell'amuleto, ci manca ancora un componente da infondere nel braciere; qualcosa che eserciti un richiamo abbastanza forte da attirare lo spirito di una mia vecchia compagna, ormai defunta.$B$BIsalien, la nostra sacerdotessa, è cresciuta a Starbreeze Village, in Winterspring. Dovresti procurarmi una Starbreeze Village Relic dai Frostmaul giants della Frostwhisper Gorge, nel sud di Winterspring. Sono noti per le scorrerie che ogni tanto fanno verso nord.",
  obj = "Procurati una Starbreeze Village Relic e portala a Bodley, dentro Blackrock Mountain.",
  progress = "Allora sei già $Gtornato:tornata;, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Ottimo lavoro, $N. Infonderò l'essenza della reliquia nel braciere.$B$BOra non resta che andare allo Shrine of Eldretharr, nell'ala est di Dire Maul, e usare il braciere per evocare lo spirito della mia vecchia compagna, Isalien. Il suo spirito è stato corrotto dal frammento dell'amuleto di Valthalak che aveva con sé, e dalla parte dell'anima di lui che vi è racchiusa.$B$BOh, a proposito, mi era avanzato un po' di bloodkelp dal tuo viaggio all'Alcaz Isle, così ci ho preparato qualche pozione per te. Scegli quella che vuoi!",
}
T[8986] = {
  title = "Altri Componenti Importanti",
  desc = "$C, ascolta bene. Ora che sappiamo dove si trova l'ultimo frammento dell'amuleto, ci manca ancora un componente da infondere nel braciere; qualcosa che eserciti un richiamo abbastanza forte da attirare lo spirito di un mio vecchio compagno, ormai defunto.$B$BMor Grayhoof, il nostro druido più illustre, aveva molti cari amici nel Cenarion Circle, e i silithid ne hanno uccisi alcuni. Dovresti recuperare dei Druidical Remains da quegli insetti che infestano i dintorni di Hive'Regal, nel sud-est di Silithus.",
  obj = "Procurati i Druidical Remains e portali a Bodley, dentro Blackrock Mountain.",
  progress = "Allora sei già $Gtornato:tornata;, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Ottimo lavoro, $N. Infonderò l'essenza dei resti nel braciere.$B$BOra non resta che scendere nella parte inferiore di Blackrock Spire, fino alla sala dove risiede War Master Voone, a Tazz'Alaor, e lì usare il braciere per evocare lo spirito corrotto del mio vecchio compagno, Mor Grayhoof. Non troverà pace finché qualcuno non gli toglierà il frammento dell'amuleto.$B$BOh, a proposito, mi era avanzato un po' di bloodkelp dal tuo viaggio all'Alcaz Isle, così ci ho preparato qualche pozione per te. Scegli quella che vuoi!",
}
T[8987] = {
  title = "Altri Componenti Importanti",
  desc = "$C, ascolta bene. Ora che sappiamo dove si trova l'ultimo frammento dell'amuleto, ci manca ancora un componente da infondere nel braciere; qualcosa che eserciti un richiamo abbastanza forte da evocare i resti di due miei vecchi compagni, ormai defunti.$B$BI fratelli Jarien e Sothos credevano nella causa della Scarlet Crusade, e aspiravano a diventare cavalieri di quell'infame organizzazione. Va' a Tyr's Hand, nelle Eastern Plaguelands, e recupera una Brilliant Sword of Zealotry dai pretoriani di stanza laggiù.",
  obj = "Recupera una Brilliant Sword of Zealotry e portala a Bodley, dentro Blackrock Mountain.",
  progress = "Allora sei già $Gtornato:tornata;, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Ottimo lavoro, $N. Infonderò l'essenza della spada nel braciere.$B$BOra non resta che entrare in The Crimson Throne, all'interno di The Scarlet Bastion di Stratholme, e lì usare il braciere per evocare i resti dei miei compagni di un tempo, Jarien e Sothos. Il frammento dell'amuleto di Valthalak che hanno con sé, in cui è racchiuso il suo spirito, ha distorto ancora di più le loro anime.$B$BOh, a proposito, mi era avanzato un po' di bloodkelp dal tuo viaggio all'Alcaz Isle, così ci ho preparato qualche pozione per te. Scegli quella che vuoi!",
}
T[8988] = {
  title = "Altri Componenti Importanti",
  desc = "$C, ascolta bene. Ora che sappiamo dove si trova l'ultimo frammento dell'amuleto, ci manca ancora un componente da infondere nel braciere; qualcosa che eserciti un richiamo abbastanza forte da attirare lo spirito di un mio vecchio compagno, ormai defunto.$B$BKormok, un negromante ogre che viaggiava con noi, si divertiva a evocare le anime dei morti esiliati della Purgation Isle, al largo della costa meridionale delle Hillsbrad Foothills. Va' laggiù e recupera delle Soul Ashes of the Banished dai loro resti.",
  obj = "Procurati le Soul Ashes of the Banished e portale a Bodley, dentro Blackrock Mountain.",
  progress = "Allora sei già $Gtornato:tornata;, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Ottimo lavoro, $N. Infonderò l'essenza delle ceneri nel braciere.$B$BOra non resta che addentrarsi nella Scholomance fino alla sala di Ras Frostwhisper e lì usare il braciere per evocare lo spirito del mio vecchio compagno, Kormok. Il frammento dell'amuleto, in cui è racchiuso lo spirito di Valthalak, l'ha corrotto ancora di più. Non troverà pace finché non glielo strapperai con la forza.$B$BOh, a proposito, mi era avanzato un po' di bloodkelp dal tuo viaggio all'Alcaz Isle, così ci ho preparato qualche pozione per te. Scegli quella che vuoi!",
}
T[8989] = {
  title = "Il Right Piece of Lord Valthalak's Amulet",
  desc = "Il mio amico Mor Grayhoof è stato il primo a cadere vittima del frammento dell'amuleto di Lord Valthalak che portava con sé, e del brandello di spirito racchiuso al suo interno, che corrompe chi lo porta. Dopo aver rubato il libro degli incantesimi e l'amuleto di Valthalak, siamo fuggiti dalla parte superiore di Blackrock Spire per salvarci la pelle. Durante la fuga, Mor è precipitato nei livelli inferiori della guglia.$B$BIn seguito abbiamo scoperto che era sopravvissuto alla caduta, ma era finito nelle mani di War Master Voone, che l'aveva torturato. Alcuni spectral assassins si sono intrufolati e lo hanno ucciso proprio sotto gli occhi di Voone.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Mor Grayhoof e uccidilo. Torna da Bodley, dentro Blackrock Mountain, con il Lord Valthalak's Amulet ricomposto e il Brazier of Beckoning.",
  progress = "Allora è fatta? Hai recuperato il frammento destro dell'amuleto di Lord Valthalak, l'hai ricomposto in un unico pezzo e hai finalmente dato pace allo spirito del mio vecchio compagno, Mor Grayhoof?",
  reward = "Grazie per aver aiutato Mor Grayhoof, $N. Un altro spirito riposa in pace, e ora l'amuleto è di nuovo intero! Ma la prova più difficile ci aspetta ancora.$B$BPerché il braciere si sintonizzi su Lord Valthalak e possa evocarlo, dovrai raccogliere altri oggetti e portarmeli qui.",
}
T[8990] = {
  title = "Il Right Piece of Lord Valthalak's Amulet",
  desc = "In seguito, mentre cercavamo di sopravvivere come potevamo, siamo venuti a sapere che Isalien, sacerdotessa elfa della notte della nostra compagnia, si era recata nell'antica città del suo popolo, oggi nota come Dire Maul. Da quanto abbiamo capito, ci era andata sia per motivi personali sia per svelare i segreti del pezzo dell'amuleto che aveva con sé.$B$BPerò non ce l'ha fatta. Ci è giunta voce che Alzzin the Wildshaper e i suoi le avevano teso un'imboscata allo Shrine of Eldretharr.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Isalien e uccidila. Torna da Bodley, dentro Blackrock Mountain, con il Lord Valthalak's Amulet ricomposto e il Brazier of Beckoning.",
  progress = "Non dirmi che hai già salvato lo spirito di Isalien e recuperato il Right Piece of Lord Valthalak's Amulet, $N? Assicurati di ricomporre i pezzi dell'amuleto prima di consegnarmelo.",
  reward = "Grazie, $N, per aver dato riposo allo spirito di Isalien. Ora, forse, troverà pace accanto alla sua dea. E abbiamo anche l'amuleto ricomposto! Ma ci aspetta ancora la prova più difficile.$B$BPerché il braciere si sintonizzi e possa richiamare Lord Valthalak, bisogna raccogliere qualche altro oggetto e portarmelo qui.",
}
T[8991] = {
  title = "Il Right Piece of Lord Valthalak's Amulet",
  desc = "I fratelli Jarien e Sothos hanno deciso di unirsi alla Scarlet Crusade quando la nostra compagnia di mercenari si è sciolta. Si sono portati via il Right Piece of Lord Valthalak's Amulet. Bella liberazione, dico io, ma quel pezzo ci serve.$B$BDa quanto abbiamo potuto scoprire, a ucciderli è stato proprio Grand Crusader Dathrohan in persona, perché avevano fallito i riti d'iniziazione nella sua sala dello Scarlet Bastion.$B$BIn ogni caso, a noi... cioè a te, tocca ancora recuperare quel pezzo dell'amuleto.",
  obj = "Usa il Brazier of Beckoning per evocare Jarien e Sothos e uccidili. Torna da Bodley, dentro Blackrock Mountain, con il Lord Valthalak's Amulet ricomposto e il Brazier of Beckoning.",
  progress = "Vuol dire, $C, che hai già dato pace alle anime di quei due sciocchi e ricomposto i pezzi del Lord Valthalak's Amulet?",
  reward = "Credo sia un bene che le anime di quei due abbiano finalmente trovato pace, anche se da vivi non mi stavano simpatici. In ogni caso, abbiamo quello che cercavamo, e ora l'amuleto è ricomposto! Ma ci aspetta ancora la prova più difficile.$B$BPerché il braciere si sintonizzi e possa richiamare Lord Valthalak, bisogna raccogliere qualche altro oggetto e portarmelo qui.",
}
T[8992] = {
  title = "Il Right Piece of Lord Valthalak's Amulet",
  desc = "Ora abbiamo quello che ci serve, quindi è il momento di parlare di chi sarà il prossimo da evocare.$B$BKormok era un tipo a posto, per essere un ogre, almeno fino a quando non si è dato alla negromanzia. Da lì in poi, le cose si sono fatte inquietanti per quasi tutti nella compagnia. Nessuno si è stupito, quindi, quando ha preso il suo pezzo dell'amuleto e se n'è tornato nella sua nuova casa, Scholomance.$B$BMa neanche lì, o forse proprio lì, era al sicuro dagli spectral assassins. L'hanno ucciso sotto gli occhi del suo padrone, Ras Frostwhisper.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Kormok e uccidilo. Torna da Bodley, dentro Blackrock Mountain, con il Lord Valthalak's Amulet ricomposto e il Brazier of Beckoning.",
  progress = "Mi complimento con te, $N, se sei $Gtornato:tornata; con l'amuleto completo. Se invece non è così, occupatene, ti prego: non c'è tempo da perdere, te lo assicuro!",
  reward = "Ottimo lavoro, $N! Kormok non era poi così male, per essere un ogre, almeno finché era vivo, quindi spero che trovi il riposo che si merita. E ora abbiamo l'amuleto completo! Ma ci aspetta ancora la prova più difficile.$B$BPerché il braciere si sintonizzi e possa richiamare Lord Valthalak, bisogna raccogliere qualche altro oggetto e portarmelo qui.",
}
T[8993] = {
  title = "Fare Regali",
  progress = "Sei $Gvenuto:venuta; a consegnare al tuo capo preferito un regalo d'amore e di adorazione?",
  reward = "Splendido! Splendido! Lo metto nel mucchio insieme agli altri regali.$B$BNon pensavo che ne arrivassero così tanti! Devi amarli davvero, i tuoi capi.$B$BE adesso uno in più nel conteggio...",
  en_title = "Gift Giving",
}
T[8994] = {
  title = "Ultimi Preparativi",
  desc = "Ci siamo quasi, $C. Non resta che recuperare qualche altro componente, così potrò sintonizzare il braciere e renderlo capace di richiamare Lord Valthalak.$B$BPer cominciare, devo chiederti di addentrarti in Blackrock Spire e uccidere gli orchi che ci vivono. I loro bracciali contengono tracce dei metalli che mi servono, quindi me ne occorreranno parecchi per estrarne la quantità giusta. Poi, per completare l'infusione, dovrai portarmi un Flask of Supreme Power.$B$BBuona fortuna, $N!",
  obj = "Raccogli 40 Blackrock Bracers e procurati un Flask of Supreme Power. Portali a Bodley, dentro Blackrock Mountain.",
  progress = "Abbiamo fatto tanta strada, $N, e volevo solo dirti grazie, qualunque cosa accada! Hai rischiato la vita per aiutare i membri sopravvissuti della nostra compagnia di mercenari, La Veiled Blade, e per quanto mi riguarda, ormai sei dei nostri.",
  reward = "Allora ci siamo. Estrarrò il metallo dai bracciali e impregnerò il braciere di questi ultimi componenti. A quel punto sarà pronto, e potrai evocare Lord Valthalak e restituirgli finalmente il suo amuleto dello spirito.$B$BSei $Garrivato:arrivata; fin qui, $N: non vacillare proprio ora che la fine è in vista!",
}
T[8995] = {
  title = "Mea Culpa, Lord Valthalak",
  desc = "Ora è tutto pronto, $N.$B$BQuando era in vita, Lord Valthalak abitava quella che ora è la sala della Bestia. Va' lì e usa il Brazier of Beckoning per evocare Lord Valthalak. Il braciere gli ridarà un corpo, quindi bisognerà ucciderlo di nuovo. Io mi occuperei prima della Bestia. E assicurati di portare con te abbastanza amici per uscire $Gvivo:viva; dalla parte superiore di Blackrock Spire.$B$BUna volta che avrai fatto fuori Valthalak, usa l'amuleto sul suo cadavere. Quando il suo spirito sarà di nuovo intero, probabilmente vorrà riavere anche l'amuleto.$B$BBuona fortuna!",
  obj = "Usa il Brazier of Beckoning per evocare Lord Valthalak. Eliminalo e usa il Lord Valthalak's Amulet sul cadavere. Poi riporta il Lord Valthalak's Amulet allo Spirit of Lord Valthalak.",
  progress = "$C, osi disturbare il mio riposo!",
  reward = "Per tua fortuna so che non facevi parte del gruppo che me l'ha rubato.$B$BOra mi riprendo ciò che è mio, mortale! Dammi l'amuleto!",
}
T[8996] = {
  title = "Ritorno da Bodley",
  desc = "Per questa volta ignorerò la tua impertinenza, $C, perché oggi hai compiuto un gesto nobile: mi hai restituito il resto del mio spirito rubato. Nonostante la tua natura palesemente debole, $R, hai dimostrato il coraggio che a chi mi ha derubato è mancato, e che probabilmente non avrà mai!$B$BTorna da loro, prima che io cambi idea e ti uccida su due piedi. Va' a dire loro che sono al sicuro... per ora.",
  obj = "Torna da Bodley, dentro Blackrock Mountain, e consegnagli il Brazier of Beckoning.",
  progress = "$N, sei $Gtornato:tornata;, e ancora $Gvivo:viva;! Be', almeno uno di noi due lo è.$B$BDevi raccontarmi tutto!",
  reward = "Ha detto davvero tutto questo? Caspita, non riesco a credere che richiamerà gli spectral assassins e i cacciatori, anche se ha lasciato intendere che in futuro potrebbe ancora fare del male ai miei compagni rimasti in vita.$B$BÈ un gran giorno, $N! Hai fatto ciò che pochi avrebbero mai potuto fare, e ci hai assolti, almeno in parte, da alcuni dei nostri peccati passati.$B$BGrazie! In segno di riconoscenza, vorrei darti questo. Puoi usarlo per evocare spiriti negli stessi luoghi infestati in cui l'hai già fatto, e anche in qualche altro.",
}
T[8997] = {
  title = "Ritorno all'Inizio",
  desc = "Allora è un addio, immagino, $Gamico mio:amica mia;. Ma io resto sempre qui, se ogni tanto ti va di tornare a fare due chiacchiere con me. Probabilmente mentre ciondoli da queste parti aspettando che i compagni ti raggiungano per un'incursione a Blackrock Spire.$B$BVai, prima che mi metta a piangere. Torna da Deliana a Ironforge e raccontale com'è andata.",
  obj = "Parla con Deliana a The High Seat, a Ironforge.",
  reward = "Sono proprio felice di vederti tornare da me $Gsano e salvo:sana e salva;, $N. Hai un bell'aspetto, anche se un po' $Gmalconcio:malconcia;.$B$BVieni, raccontami tutto quello che è successo.",
}
T[8998] = {
  title = "Ritorno all'Inizio",
  desc = "Allora suppongo che sia un addio, $Gamico mio:amica mia;. Ma io sarò sempre qui, se ogni tanto vorrai tornare a fare due chiacchiere con me. Probabilmente mentre te ne starai a bighellonare aspettando che i tuoi compari ti raggiungano per un raid nel Blackrock Spire.$B$BVai, prima che mi metta a piangere. Torna da Mokvar a Orgrimmar e raccontagli cos'è successo.",
  obj = "Parla con Mokvar alla Grommash Hold, in Orgrimmar's Valley of Wisdom.",
  reward = "Mi fa piacere vedere che sei $Gsopravvissuto:sopravvissuta;, $N. Hai un bell'aspetto, anche se sembri un po' più $Gesperto:esperta;.$B$BVieni, raccontami tutto quello che è successo.",
}
T[8999] = {
  title = "Il Meglio alla Fine",
  desc = "Che storia incredibile, $N! Grazie, anche da parte di tutti quelli che ci hanno preso parte: ti sono sinceramente grati. Forse adesso riuscirò a dormire la notte con tutti e due gli occhi chiusi.$B$BQuanto alla ricompensa, credo di avere un paio di cose che ti piaceranno davvero.",
  obj = "Consegna a Deliana il tuo Wildheart Cowl e la tua Wildheart Vest.",
  progress = "Come d'accordo, sei $Gpronto:pronta; a darmi i pezzi Wildheart in cambio del nuovo Feralheart Cowl e della Veste?",
  reward = "Mi mancherai, $N. Ti devo così tanto che non credo riuscirò mai a sdebitarmi.$B$BSpero che la nuova armatura per la testa e per il torso ti piaccia e ti protegga ancora a lungo.",
}
T[9000] = {
  title = "Il Meglio alla Fine",
  desc = "Che storia incredibile, $N! Grazie, anche da parte di tutti quelli che ci hanno preso parte: ti sono sinceramente grati. Forse adesso riuscirò a dormire la notte con tutti e due gli occhi chiusi.$B$BQuanto alla ricompensa, credo di avere un paio di cose che ti piaceranno davvero.",
  obj = "Consegna a Deliana la tua Beaststalker's Cap e la tua Beaststalker's Tunic.",
  progress = "Come d'accordo, sei $Gpronto:pronta; a darmi i pezzi del Predatore di Bestie in cambio del nuovo Beastmaster's Cap e della Tunica?",
  reward = "Mi mancherai, $N. Ti devo così tanto che non credo riuscirò mai a sdebitarmi.$B$BSpero che la nuova armatura per la testa e per il torso ti piaccia e ti protegga ancora a lungo.",
}
T[9001] = {
  title = "Il Meglio alla Fine",
  desc = "Che storia incredibile, $N! Ti sono grata, e con me ti ringraziano di cuore tutti quelli che ne hanno fatto parte. Forse adesso riuscirò a dormire la notte con tutti e due gli occhi chiusi.$B$BPer la ricompensa, credo di avere alcune cose che ti piaceranno davvero.",
  obj = "Consegna a Deliana la tua Magister's Crown e le tue Magister's Robes.",
  progress = "Come d'accordo, sei $Gpronto:pronta; a consegnarmi i pezzi del Magistro in cambio della nuova Sorcerer's Crown e delle nuove Vesti?",
  reward = "Mi mancherai, $N. Ti sono talmente grata che non credo riuscirò mai a sdebitarmi.$B$BSpero che la nuova armatura per testa e torso ti piaccia, e che ti protegga ancora a lungo.",
}
