T[9005] = {
  title = "Il Meglio alla Fine",
  desc = "Che storia incredibile, $N! Ti sono grata, e con me ti ringraziano di cuore tutti quelli che ne hanno fatto parte. Forse adesso riuscirò a dormire la notte con tutti e due gli occhi chiusi.$B$BPer la ricompensa, credo di avere alcune cose che ti piaceranno davvero.",
  obj = "Consegna a Deliana la tua Dreadmist Mask e la tua Dreadmist Robe.",
  progress = "Come d'accordo, sei $Gpronto:pronta; a consegnarmi i pezzi Dreadmist in cambio della nuova Deathmist Mask e della nuova Tonaca?",
  reward = "Mi mancherai, $N. Ti sono talmente grata che non credo riuscirò mai a sdebitarmi.$B$BSpero che la nuova armatura per testa e torso ti piaccia, e che ti protegga ancora a lungo.",
}
T[9006] = {
  title = "Il Meglio per Ultimo",
  desc = "Che storia incredibile, $N! Ti sono grata, e con me ti ringraziano di cuore tutti quelli che ci sono stati coinvolti. Forse adesso riuscirò a dormire la notte con tutti e due gli occhi chiusi.$B$BQuanto alla ricompensa, credo di avere qualche cosa che ti piacerà davvero.",
  obj = "Dai a Deliana il tuo Helm of Valor e il tuo Breastplate of Valor.",
  progress = "Allora, come d'accordo, sei $Gpronto:pronta; a consegnare i pezzi del Valore in cambio del nuovo Elmo e del Breastplate of Heroism?",
  reward = "Mi mancherai, $N. Ti devo talmente tanto che non credo riuscirò mai a sdebitarmi.$B$BSpero che la nuova armatura per testa e petto ti piaccia e ti protegga a lungo.",
}
T[9007] = {
  title = "Il Meglio alla Fine",
  desc = "Che storia incredibile, $N! Ti ringrazio, e ti assicuro che chiunque ne abbia fatto parte ti è grato di cuore. Grazie a quello che hai fatto, siamo liberi dagli errori del passato.$B$BQuanto alla ricompensa, credo di avere un paio di cose che di sicuro hai meritato e che ti piaceranno davvero.",
  obj = "Consegna a Mokvar il tuo Wildheart Cowl e la tua Wildheart Vest.",
  progress = "Come d'accordo: sei $Gpronto:pronta; a darmi i tuoi pezzi Wildheart? In cambio avrai il tuo nuovo Feralheart Cowl e la nuova Veste.",
  reward = "Sentirò davvero la tua mancanza, $N. Ho con te un debito che forse non riuscirò mai a ripagare.$B$BGoditi la nuova armatura per testa e petto. Che ti protegga a lungo e ti aiuti a raggiungere un onore ancora più grande!",
}
T[9008] = {
  title = "Il Meglio alla Fine",
  desc = "Che storia incredibile, $N! Ti ringrazio, e ti assicuro che chiunque ne abbia fatto parte ti è grato di cuore. Grazie a quello che hai fatto, siamo liberi dagli errori del passato.$B$BQuanto alla ricompensa, credo di avere un paio di cose che di sicuro hai meritato e che ti piaceranno davvero.",
  obj = "Consegna a Mokvar la tua Beaststalker's Cap e la tua Beaststalker's Tunic.",
  progress = "Come d'accordo: sei $Gpronto:pronta; a darmi i tuoi pezzi del Predatore di Bestie? In cambio avrai il tuo nuovo Beastmaster's Cap e la nuova Tunica.",
  reward = "Sentirò davvero la tua mancanza, $N. Ho con te un debito che forse non riuscirò mai a ripagare.$B$BGoditi la nuova armatura per testa e petto. Che ti protegga a lungo e ti aiuti a raggiungere un onore ancora più grande!",
}
T[9009] = {
  title = "Il Meglio alla Fine",
  desc = "Che storia incredibile, $N! Hai la mia gratitudine e, te lo assicuro, la sentita riconoscenza di tutti quelli che vi hanno preso parte. Grazie ai tuoi sforzi siamo liberi dagli errori del passato.$B$BQuanto alla ricompensa, credo di avere alcune cose che ti sei di sicuro $Gguadagnato:guadagnata;, e che ti piaceranno davvero.",
  obj = "Dai a Mokvar la tua Devout Crown e la tua Devout Robe.",
  progress = "Come d'accordo: sei $Gpronto:pronta; a darmi i pezzi del Devoto in cambio della nuova Virtuous Crown e della Tonaca?",
  reward = "Mi mancherai davvero, $N. Ho un debito con te che forse non riuscirò mai a ripagare.$B$BGoditi la nuova armatura per la testa e il torace. Possa proteggerti a lungo e aiutarti a conquistare un onore ancora più grande!",
}
