T[9014] = {
  title = "Il Meglio alla Fine",
  desc = "Che storia incredibile, $N! Grazie, e te lo assicuro: con me ti ringraziano di cuore tutti quelli che ci hanno preso parte. È merito tuo se ora siamo liberi dagli errori del passato.$B$BE veniamo alla ricompensa: credo di avere un paio di cose che ti sei di certo $Gmeritato:meritata;, e che ti piaceranno davvero.",
  obj = "Consegna a Mokvar la tua Magister's Crown e le tue Magister's Robes.",
  progress = "Come d'accordo: sei $Gpronto:pronta; a consegnare i pezzi del Magistro in cambio della nuova Sorcerer's Crown e delle Vesti nuove?",
  reward = "Mi mancherai davvero, $N. Il debito che ho con te forse non riuscirò mai a ripagarlo.$B$BGoditi la nuova armatura per testa e torso: che ti protegga a lungo e ti aiuti a conquistare onori ancora più grandi!",
}
T[9015] = {
  title = "La Sfida",
  desc = "Ascoltami bene, $N. Perché lo stendardo funzioni a dovere, dovrai entrare nel Ring of the Law, nei Blackrock Depths, lasciarti condannare da High Justice Grimstone e piantarlo saldamente a terra in segno di sfida.$B$BLa tua vittima non saprà trattenersi: si getterà nella mischia, con una gran voglia di combatterti. Quando avrai ottenuto ciò che cerchi, torna da Anthion.",
  obj = "Viaggia fino a Ring of the Law a Blackrock Depths e pianta il Banner of Provocation al centro mentre vieni $Gcondannato:condannata; da High Justice Grimstone. Uccidi Theldren e i suoi gladiatori e torna da Anthion Harmon a Eastern Plaguelands con il primo pezzo dell'amuleto di Lord Valthalak.",
  progress = "Sei $Gtornato:tornata;, $N!",
  reward = "Hai recuperato parte del medaglione, $N?",
}
T[9016] = {
  title = "Le Parole di Commiato di Anthion",
  desc = "L'anima di Valthalak era custodita in questo amuleto. Accecati dall'avidità, lo abbiamo stoltamente diviso in tre parti, senza sapere quale maledizione ci attendeva.$B$BL'unico modo per fermare l'incantesimo di Valthalak è ricomporre l'amuleto. Torna da Mokvar e digli che Bodley è l'unica speranza che ha di trovare i pezzi mancanti. Parla con lui delle ricompense che hai concordato.$B$BIo, per una volta, riposerò in pace. Ti auguro tutta la fortuna del mondo; te ne servirà fino all'ultima goccia!",
  obj = "Torna da Mokvar a Orgimmar con un set composto da Wildheart Boots, un Wildheart Kilt e Wildheart Spaulders.",
  progress = "Sei $Gtornato:tornata;, $N, e ti leggo negli occhi che hai molto da raccontarmi. Prima occupiamoci della tua ricompensa.",
  reward = "Questa maledizione ci è piombata addosso per un semplice medaglione. Certo che Lord Valthalak sa portare rancore.$B$BCercheremo di trovare i pezzi mancanti — si spera prima che io vada incontro a una morte prematura. Ma ora vediamo la tua ricompensa.",
}
