T[9050] = {
  title = "Redemption Wristguards",
  desc = "I resti dei nostri eroi caduti li troverai sui cadaveri dei Signori di Naxxramas. Portami quei cimeli profanati, con dei frammenti di piastre logorati dalla guerra e i materiali che possono ridare vita all'armatura maledetta, e ti forgerò un bel pezzo d'armatura.",
