T[9051] = {
  title = "Prova Tossica",
  desc = "La tossina che mi hai aiutato a preparare serve a uno scopo particolare. Per colpa dei grandi devilsaurs del cratere la caccia è pericolosa, e sopravvivere per me è difficile. E anche se ne avessi la forza, uccidere un devilsaur servirebbe solo a lasciare il suo territorio a un altro.$B$BPrendi questa daga avvelenata e piantala a fondo in un devilsaur vivo. La tossina dovrebbe placare la creatura, anche se non so dirti quanto in fretta...",
  obj = "Trafiggi un Devilsaur con la Devilsaur Barb. Torna da Torwa Pathfinder in Un'Goro Crater quando hai finito.",
  progress = "Sei $Griuscito:riuscita; a placare la grande bestia?",
  reward = "Grazie, $N. Sei $Gcoraggioso:coraggiosa; e $Gsaggio:saggia;.$B$BDimmi: che effetto ha avuto la tossina sul devilsaur?",
}
T[9052] = {
  title = "Veleno di Bloodpetal",
  desc = "Mi serve il tuo aiuto per preparare una specie di tossina che plachi una grande creatura che vive qui nel cratere. Non è mortale, e solo l'occhio acuto di $Gun druido:una druida; può sperare di raccoglierne gli ingredienti.$B$BI funghi bloodcap li troverai fra i germogli di bloodpetal, un po' in tutto il cratere. Gli aculei dei Gorishi, invece, li prenderai alle vespe giganti che volano dentro e intorno allo Slithering Scar, nella parte sud del cratere.",
  obj = "Raccogli 8 Bloodcap e 8 Gorishi Stings e torna da Torwa Pathfinder in Un'Goro Crater.",
  progress = "Ci sei $Griuscito:riuscita;?",
  reward = "Finalmente, gli ingredienti!$B$BCon la terra di Un'Goro che ho raccolto, la tossina è facile da preparare...",
}
T[9053] = {
  title = "Un Ingrediente Migliore",
  desc = "È come temevo — per una creatura tanto potente la tossina è troppo debole.$B$BSe vogliamo una tossina abbastanza forte, dovrai scendere fino in fondo al Temple of Atal'Hakkar, svelare i segreti dell'altare e recuperare una putrid vine dal suo guardiano. Il tempio è pericoloso: ti conviene portare degli amici.$B$BQuando avrai finito, torna da me.",
  obj = "Recupera una Putrid Vine dal guardiano in fondo al Sunken Temple e torna da Torwa Pathfinder.",
  progress = "Hai con te la vite?",
  reward = "Ora posso finalmente completare la tossina. Non oso chiederti di usarla di nuovo sulla creatura: ti ho già domandato troppo.$B$BHai la mia gratitudine e il mio rispetto, e ti auguro ogni bene nei tuoi viaggi, $N.",
}
