}
T[9077] = {
  title = "Bonescythe Breastplate",
  desc = "Vuoi un pezzo della Falce Ossuta? Allora i materiali dovrai procurarmeli tu.$B$BEntra a Naxxramas, la grande città fluttuante della morte, lassù nel cielo, e trova armature sconsacrate e armor scraps logori dalla guerra. Riportameli qui insieme ai materiali per montare il tutto, e avrai il tuo pezzo della Falce Ossuta. Ah, e il disturbo me lo dovrai pagare... Le ossa ce le metto io.",
  obj = "Rohan the Assassin, a Light's Hope Chapel, in Eastern Plaguelands, ti farà un Bonescythe Breastplate se gli porti: 1 Desecrated Breastplate, 25 Wartorn Leather Scraps, 2 Arcanite Bars e 6 Cured Rugged Hides.",
  progress = "<Rohan ti mostra le sue mosse.>$B$BChe c'è, $N? Per la gara di dopo devo centrare questo bersaglio alla perfezione.",
  reward = "Ecco qua, $R: il Bonescythe breastplate, come promesso. Speriamo che le autorità della moda non siano nei paraggi. A girare con quello addosso, ti sbatterebbero in gattabuia!",
}
T[9078] = {
  title = "Bonescythe Legplates",
  desc = "Vuoi un pezzo della Falce Ossuta? Allora i materiali dovrai procurarmeli tu.$B$BEntra a Naxxramas, la grande città fluttuante della morte, lassù nel cielo, e trova armature sconsacrate e armor scraps logori dalla guerra. Riportameli qui insieme ai materiali per montare il tutto, e avrai il tuo pezzo della Falce Ossuta. Ah, e il disturbo me lo dovrai pagare... Le ossa ce le metto io.",
  obj = "Rohan the Assassin, a Light's Hope Chapel, in Eastern Plaguelands, ti farà i Bonescythe Legplates se gli porti: 1 Desecrated Legplates, 20 Wartorn Leather Scraps, 1 Arcanite Bar, 8 Cured Rugged Hides e 100 monete d'oro.",
  progress = "<Rohan ride.>$B$BMi sono appena accorto di quanto sia ironica tutta questa storia.",
  reward = "Quando giri con quei cosi addosso, sta' $Gattento:attenta;. Potresti tagliarti.",
}
T[9079] = {
  title = "Bonescythe Helmet",
  desc = "Vuoi un pezzo della Falce Ossuta? Allora i materiali dovrai procurarmeli tu.$B$BEntra a Naxxramas, la grande città fluttuante della morte, lassù nel cielo, e trova armature sconsacrate e armor scraps logori dalla guerra. Riportameli qui insieme ai materiali per montare il tutto, e avrai il tuo pezzo della Falce Ossuta. Ah, e il disturbo me lo dovrai pagare... Le ossa ce le metto io.",
  obj = "Rohan the Assassin, a Light's Hope Chapel, in Eastern Plaguelands, ti farà un Bonescythe Helmet se gli porti: 1 Desecrated Helmet, 15 Wartorn Leather Scraps, 8 Cured Rugged Hides, 1 Nexus Crystal e 75 monete d'oro.",
  progress = "Mi dai dei soldi.$B$B<Rohan ride.>$B$BMi fa morire dal ridere ancora adesso.",
  reward = "A distinguere il mio modello di Bonescythe helmet da quello di Don Julio è lo stile, $N. Lo stile...",
}
T[9080] = {
  title = "Bonescythe Pauldrons",
  desc = "Vuoi un pezzo della Falce Ossuta? Allora i materiali dovrai procurarmeli tu.$B$BEntra a Naxxramas, la grande città fluttuante della morte, lassù nel cielo, e trova armature sconsacrate e armor scraps logori dalla guerra. Riportameli qui insieme ai materiali per montare il tutto, e avrai il tuo pezzo della Falce Ossuta. Ah, e il disturbo me lo dovrai pagare... Le ossa ce le metto io.",
  obj = "Rohan the Assassin, a Light's Hope Chapel, in Eastern Plaguelands, ti farà i Bonescythe Pauldrons se gli porti: 1 Desecrated Pauldrons, 12 Wartorn Leather Scraps, 5 Cured Rugged Hides, 1 Nexus Crystal e 50 monete d'oro.",
  progress = "<Rohan ti guarda con sospetto.>$B$BDi recente sei $Gstato:stata; a Tyr's Hand?",
  reward = "<Rohan si asciuga il sudore dalla fronte.>$B$BQuesti paraspalle mi sono costati un bel po' di lavoro! Non farti ammazzare come $Gun pivello:una pivella;, $N.",
}
T[9081] = {
  title = "Bonescythe Sabatons",
  desc = "Vuoi un pezzo della Falce Ossuta? Allora i materiali dovrai procurarmeli tu.$B$BEntra a Naxxramas, la grande città fluttuante della morte, lassù nel cielo, e trova armature sconsacrate e armor scraps logori dalla guerra. Riportameli qui insieme ai materiali per montare il tutto, e avrai il tuo pezzo della Falce Ossuta. Ah, e il disturbo me lo dovrai pagare... Le ossa ce le metto io.",
  obj = "Rohan the Assassin, a Light's Hope Chapel, in Eastern Plaguelands, ti farà i Bonescythe Sabatons se gli porti: 1 Desecrated Sabatons, 12 Wartorn Leather Scraps, 3 Cured Rugged Hides, 2 Nexus Crystals e 25 monete d'oro.",
  progress = "Portami i materiali, $C, e smettila di farmi perdere tempo.",
  reward = "Vanno ai piedi. Di', non sei $Gandato:andata; di nuovo a ficcanasare a Tyr's Hand, vero?",
}
T[9082] = {
  title = "Bonescythe Gauntlets",
  desc = "Se vuoi che ti prepari la Falce Ossuta, i materiali te li devi procurare tu.$B$BEntra a Naxxramas, quella grossa città della morte che fluttua lassù nel cielo, e cerca armature sconsacrate e armor scraps logorati dalla guerra. Portameli insieme ai materiali per assemblare il tutto e la tua Falce Ossuta l'avrai. Ah, e il disturbo me lo paghi... Le ossa ce le metto io.",
  obj = "Rohan the Assassin, a Light's Hope Chapel, in Eastern Plaguelands, creerà i Bonescythe Gauntlets se gli porti quanto segue: 1 Desecrated Gauntlets, 8 Wartorn Leather Scraps, 1 Arcanite Bar e 5 Cured Rugged Hides.",
  progress = "E come pensi che faccia qualcosa, senza gli oggetti che ti ho chiesto?",
  reward = "Se ti trovassi proprio alle strette, questi guanti farebbero probabilmente anche da armi. Portali con orgoglio!",
}
T[9083] = {
  title = "Bonescythe Waistguard",
  desc = "Se vuoi che ti prepari la Falce Ossuta, i materiali te li devi procurare tu.$B$BEntra a Naxxramas, quella grossa città della morte che fluttua lassù nel cielo, e cerca armature sconsacrate e armor scraps logorati dalla guerra. Portameli insieme ai materiali per assemblare il tutto e la tua Falce Ossuta l'avrai. Ah, e il disturbo me lo paghi... Le ossa ce le metto io.",
  obj = "Rohan the Assassin, a Light's Hope Chapel, in Eastern Plaguelands, creerà una Bonescythe Waistguard se gli porti quanto segue: 1 Desecrated Waistguard, 8 Wartorn Leather Scraps, 5 Cured Rugged Hides, 1 Nexus Crystal e 15 monete d'oro.",
  progress = "E come pensi che faccia qualcosa, senza gli oggetti che ti ho chiesto?",
  reward = "La cintura è pronta, $N. Hai mai visto un oggetto di questa qualità a un prezzo così basso?",
}
T[9084] = {
  title = "Bonescythe Bracers",
  desc = "Se vuoi che ti prepari la Falce Ossuta, i materiali te li devi procurare tu.$B$BEntra a Naxxramas, quella grossa città della morte che fluttua lassù nel cielo, e cerca armature sconsacrate e armor scraps logorati dalla guerra. Portameli insieme ai materiali per assemblare il tutto e la tua Falce Ossuta l'avrai. Ah, e il disturbo me lo paghi... Le ossa ce le metto io.",
