T[9085] = {
  title = "Shadows of Doom",
  desc = "Quando avrai abbattuto le difese dei cerchi di evocazione dello Scourge comparsi nelle zone sotto attacco, potrai affrontare gli accoliti che li proteggono.$B$BIn realtà non sono uomini, ma ombre: alcune fra le creature più spaventose di The Lich King. Le puoi rivelare con le necrotic runes che portano con sé, e poi distruggerle con la magia o con la forza delle armi.",
  obj = "Vai a un cerchio di evocazione e uccidi una Shadow of Doom, poi torna da Commander Thomas Helleran alla Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "Allora, $N, hai avuto fortuna?",
  reward = "Ottimo lavoro, $N. Con le ombre distrutte, The Lich King deciderà di richiamare le sue necropoli e di lasciarci in pace: è solo questione di tempo.",
}
T[9086] = {
  title = "Dreamwalker Tunic",
  desc = "Molti eroi sono caduti nell'ultima guerra, e ancora oggi molti continuano a morire per mano dello Scourge. Ai caduti strappano di dosso l'armatura e la riportano a Naxxramas, per scopi che nessuno conosce.$B$BRecupera l'armatura sconsacrata e gli armor scraps segnati dalla guerra, procurami il resto dei materiali che mi servono e io creerò la Dreamwalker armor.",
  obj = "Rayne, a Light's Hope Chapel, in Eastern Plaguelands, creerà una Dreamwalker Tunic se le porti: 1 Desecrated Tunic, 25 Wartorn Leather Scraps, 6 Cured Rugged Hides e 2 Nexus Crystals.",
  progress = "I materiali costano molto, ma è un prezzo che si dimentica presto.",
  reward = "$N, la tua Dreamwalker tunic è pronta.",
}
