T[9094] = {
  title = "Guanti dell'Argent Dawn",
  progress = "Portami trenta necrotic runes e in cambio potrai scegliere una protezione per le mani: dovrebbe rivelarsi preziosa nella nostra lotta contro lo Scourge non morto.",
  reward = "Hai fatto un buon lavoro, $N. Scegli una protezione per le mani: è il nostro grazie per i tuoi sforzi.",
}
T[9095] = {
  title = "Frostfire Robe",
  desc = "Da Sorvegliante ho avuto accesso a molti degli effetti personali di Medivh, e fra quelle cose i più illuminanti sono stati i tomi. La maggior parte di quei libri era piena — per dirla senza mezzi termini — di fesserie. Qualche perla però c'era. In uno dei tomi si descriveva come creare un'armatura degna di un arcimago: Fuocogelo.$B$B<Angela si indica la testa.>$B$BÈ tutto qui dentro, e sono disposta a condividere con te i frutti di quel sapere, se riesci a procurarmi i materiali che servono.",
  obj = "Archmage Angela Dosantos a Light's Hope Chapel, in Eastern Plaguelands, creerà una Frostfire Robe se le porterai quanto segue: 1 Desecrated Robe, 25 Wartorn Cloth Scraps, 4 Mooncloth e 2 Nexus Crystals.",
  progress = "Se avrò i materiali e i reagenti giusti, potrò ricreare la mitica armatura di Fuocogelo.",
  reward = "Ricorda, $C: il potere senza freni è distruttivo quanto quello lasciato inutilizzato. Indossa il Fuocogelo con prudenza.",
}
T[9096] = {
  title = "Frostfire Leggings",
  desc = "Da Sorvegliante ho avuto accesso a molti degli effetti personali di Medivh, e fra quelle cose i più illuminanti sono stati i tomi. La maggior parte di quei libri era piena — per dirla senza mezzi termini — di fesserie. Qualche perla però c'era. In uno dei tomi si descriveva come creare un'armatura degna di un arcimago: Fuocogelo.$B$B<Angela si indica la testa.>$B$BÈ tutto qui dentro, e sono disposta a condividere con te i frutti di quel sapere, se riesci a procurarmi i materiali che servono.",
  obj = "Archmage Angela Dosantos a Light's Hope Chapel, in Eastern Plaguelands, creerà le Frostfire Leggings se le porterai quanto segue: 1 Desecrated Leggings, 20 Wartorn Cloth Scraps, 4 Mooncloth e 2 Nexus Crystals.",
  progress = "Se avrò i materiali e i reagenti giusti, potrò ricreare la mitica armatura di Fuocogelo.",
  reward = "Ricorda, $C: il potere senza freni è distruttivo quanto quello lasciato inutilizzato. Indossa il Fuocogelo con prudenza.",
}
T[9097] = {
  title = "Frostfire Circlet",
  desc = "Da Sorvegliante ho avuto accesso a molti degli effetti personali di Medivh, e fra quelle cose i più illuminanti sono stati i tomi. La maggior parte di quei libri era piena — per dirla senza mezzi termini — di fesserie. Qualche perla però c'era. In uno dei tomi si descriveva come creare un'armatura degna di un arcimago: Fuocogelo.$B$B<Angela si indica la testa.>$B$BÈ tutto qui dentro, e sono disposta a condividere con te i frutti di quel sapere, se riesci a procurarmi i materiali che servono.",
  obj = "Archmage Angela Dosantos a Light's Hope Chapel, in Eastern Plaguelands, creerà una Frostfire Circlet se le porterai quanto segue: 1 Desecrated Circlet, 15 Wartorn Cloth Scraps, 3 Mooncloth e 3 Nexus Crystals.",
