T[9103] = {
  title = "Plagueheart Robe",
  desc = "Non ti nascondo niente, verme: l'oscurità chiusa negli oggetti del Cuore Infetto potrebbe benissimo distruggerci tutti e due. È per questo che il prezzo è così alto. Se devo morire, morirò da uomo ricco.$B$BE di come morirai tu m'importa meno di uno sputo di gnoll: voglio soltanto che tu faccia quello che ti chiedo. Portami quello che mi serve e ci guadagneremo tutti e due — oppure moriremo; ma questo te l'ho già detto...",
  obj = "Mataus the Wrathcaster, a Light's Hope Chapel in Eastern Plaguelands, creerà una Plagueheart Robe se gli porti quanto segue: 1 Desecrated Robe, 25 Wartorn Cloth Scraps, 4 Mooncloth e 2 Nexus Crystals.",
  progress = "Ecco che torna il roditore prodigo! Hai quello che mi serve?",
  reward = "Vedi? Ora ne capisci il potere? Purificazione... Che sciocchi...$B$B<Mataus scuote la testa con disapprovazione.>$B$BAdesso prendila e sparisci dalla mia vista.",
}
