T[9111] = {
  title = "Robe of Faith",
  desc = "<Padre Montoy fa strani gesti nell'aria davanti a te.>$B$B$GFigliolo benedetto:Figliola benedetta;, hai trovato le vesti dei caduti? Povere anime, hanno esalato l'ultimo respiro sul campo di battaglia — e sono state spogliate di tutto, perfino della dignità.$B$BPortami i resti sconsacrati dei defunti con i reagenti di purificazione, e conoscerai la fede.",
  obj = "Father Inigo Montoy, a Light's Hope Chapel in Eastern Plaguelands, creerà una Robe of Faith se gli porti questi materiali: 1 Desecrated Robe, 25 Wartorn Cloth Scraps, 4 Mooncloth e 2 Nexus Crystals.",
  progress = "$GFigliolo:Figliola;, mi hai portato i reagenti?",
  reward = "Le vesti sono pronte, $N. Colpisci col tuo giusto fuoco chi vorrebbe fare del male al nostro mondo.",
}
