T[9120] = {
  title = "La Caduta di Kel'Thuzad",
  desc = "Del signore di Naxxramas non resta che il filatterio. Il buon senso ti dice di distruggerlo, perché il lich non possa riformarsi. Per fortuna, a quella voce interiore della ragione dai retta di rado.$B$BAlla Speranza di Luce c'è qualcuno che ti pagherà profumatamente per questo artefatto. E se Kel'Thuzad torna nel pieno dei suoi poteri, chi se ne importa?",
  obj = "Porta the Phylactery of Kel'Thuzad alla Cappella della Speranza di Luce, in Eastern Plaguelands.",
}
T[9121] = {
  title = "La Dread Citadel — Naxxramas",
  desc = "Nel cuore della Plaguewood c'è l'ingresso della temibile cittadella di Naxxramas. Finora le protezioni magiche sul portale runico hanno vanificato ogni tentativo di entrare. Almeno fino a ora.$B$BAbbiamo trovato il modo di passare con un occultamento arcano — un vecchio incantesimo minore dei Kirin Tor, con qualche modifica mia. Visto che la tua dedizione alla causa dell'Alba lascia un po' a desiderare, $N, per te il prezzo sarà alto. Puoi rifiutare e tornare quando sarai $Griverito:riverita; o $Gosannato:osannata;: avrai uno sconto.",
  obj = "Archmage Angela Dosantos alla Cappella della Speranza di Luce nelle Eastern Plaguelands vuole 5 Arcane Crystals, 2 Nexus Crystals, 1 Righteous Orb e 60 monete d'oro. Devi anche essere $GOnorato:Onorata; presso l'Argent Dawn.",
  progress = "Nessuno di quelli che sono entrati a Naxxramas è sopravvissuto per raccontarlo.",
  reward = "Sentirai un leggero formicolio, $N: vuol dire che sta funzionando. Quando sarà finito, potrai entrare a Naxxramas salendo sul portale runico nella Plaguewood.",
}
T[9122] = {
  title = "La Dread Citadel — Naxxramas",
  desc = "Nel cuore della Plaguewood c'è l'ingresso della temibile cittadella di Naxxramas. Finora le protezioni magiche sul portale runico hanno vanificato ogni tentativo di entrare. Almeno fino a ora.$B$BAbbiamo trovato il modo di passare con una specie di occultamento arcano permanente — un vecchio incantesimo minore dei Kirin Tor, con qualche modifica mia. Detto questo, è un occultamento costoso. Ma visto che la tua dedizione alla causa dell'Alba è ammirevole, siamo disposti a coprire parte delle spese.",
  obj = "Archmage Angela Dosantos alla Cappella della Speranza di Luce nelle Eastern Plaguelands vuole 2 Arcane Crystals, 1 Nexus Crystal e 30 monete d'oro. Devi anche essere $GRiverito:Riverita; presso l'Argent Dawn.",
  progress = "Nessuno di quelli che sono entrati a Naxxramas è sopravvissuto per raccontarlo.",
  reward = "Sentirai un leggero formicolio, $N: vuol dire che sta funzionando. Quando sarà finito, potrai entrare a Naxxramas salendo sul portale runico nella Plaguewood.",
}
T[9123] = {
  title = "La Dread Citadel — Naxxramas",
  desc = "Nel cuore della Plaguewood c'è l'ingresso della temibile cittadella di Naxxramas. Finora le protezioni magiche sul portale runico hanno vanificato ogni tentativo di entrare. Almeno fino a ora.$B$BAbbiamo trovato il modo di passare con una specie di occultamento arcano permanente — un vecchio incantesimo minore dei Kirin Tor, con qualche modifica mia. Detto questo, è un occultamento costoso; ma la tua dedizione alla causa dell'Alba è incrollabile! Non ti faremo pagare niente.",
  obj = "Archmage Angela Dosantos alla Cappella della Speranza di Luce nelle Eastern Plaguelands ti concederà l'Occultamento Arcano senza alcun costo. Devi essere $GOsannato:Osannata; presso l'Argent Dawn.",
  progress = "Nessuno di quelli che sono entrati a Naxxramas è sopravvissuto per raccontarlo.",
  reward = "Sentirai un leggero formicolio, $N: vuol dire che sta funzionando. Quando sarà finito, potrai entrare a Naxxramas salendo sul portale runico nella Plaguewood.",
}
T[9124] = {
  title = "L'Armatura Insidiacripte Non si Fa da Sola...",
  desc = "Che ne diresti di guadagnarti una di queste monete luccicanti?$B$B<Leopold alza un insignia of the Crusade.>$B$BForse puoi aiutarmi con un piccolo problema, $N. Vedi, faccio armature Insidiacripte per chi è abbastanza scemo da avventurarsi a Naxxramas. I materiali principali me li procurano loro, ma le crypt fiend parts mi finiscono sempre. Portamene un fascio e ti pagherò con un fregio — da spendere dal furiere.",
  obj = "Huntsman Leopold, a Light's Hope Chapel in Eastern Plaguelands, vuole 30 Crypt Fiend Parts.",
  progress = "Come va la caccia?",
  reward = "Ah, questo va benissimo, $N. Ricorda, altre parti le accetto sempre. Per ogni fascio che mi porti avrai un fregio in ricompensa.",
}
T[9125] = {
  title = "Crypt Fiend Parts",
  progress = "Col primo fascio hai fatto un lavoro esemplare, $N. Se ne hai altri, li prendo subito, e per ognuno che mi consegni avrai in ricompensa un altro fregio.",
  reward = "Davvero eccellente, $N! Queste mi torneranno utili di sicuro.",
}
T[9126] = {
  title = "Scavi per la Falciaossa",
  desc = "Per l'armatura Falciaossa, il modello di Don Julio vuole bone fragments — un sacco di bone fragments. I materiali principali me li procura a sufficienza chi è abbastanza pazzo da avventurarsi a Naxxramas, ma sono sempre in cerca di altri bone fragments dello Scourge.$B$BAllora, che ne dici? $GInteressato:Interessata; a sporcarti le mani e intanto a distruggere un po' dello Scourge? Ci guadagniamo tutti e due.",
  obj = "Rohan the Assassin, a Light's Hope Chapel in Eastern Plaguelands, vuole 30 Bone Fragments.",
  progress = "Posso indicarti qualche posto infestato dagli scheletri, $C.",
  reward = "Lavori in fretta, $N. Veloce come una volpe... Senti, ti ho mai raccontato di quando cantavo in un quartetto barbershop?$B$BRicordami di raccontartela, uno di questi giorni.",
}
T[9127] = {
  title = "Bone Fragments",
  progress = "Per uno che fa il mio mestiere, i bone fragments non sono mai abbastanza, $N. Quando ne hai qualcuno in più, portameli e ti ripagherò con un altro fregio.",
  reward = "Il sogno di fare il ballerino a tempo pieno alla discoteca di Gadgetzan sta per avverarsi! Continua così, $N.",
}
T[9128] = {
  title = "L'Equazione Elementale",
  desc = "Salute, $Gavventuriero:avventuriera;! Ti interessa qualche incarico? Chi lavora per me lo pago in insegne, da spendere dall'Intendente in oggetti di potere.$B$BMi basta che tu mi porti tutti i pezzi di core of elements che riesci a trasportare. Più sono, meglio è!$B$BLi troverai addosso agli elementali di ogni forma e dimensione che vivono in tutto il nostro mondo.",
  obj = "Archmage Angela Dosantos alla Cappella della Speranza di Luce nelle Eastern Plaguelands vuole 30 Core of Elements.",
  progress = "Io posso solo indicarti la strada giusta, $N.",
  reward = "Ottimo lavoro, $N! Come promesso, l'insegna è tua. Solo, ricorda che ce ne sono ancora tante...",
}
T[9129] = {
  title = "Core of Elements",
  progress = "A dire il vero, con i nuclei creo l'armatura Gelofuoco, quella che usano i maghi che combattono a Naxxramas. Senza di te e quelli come te, questa guerra la staremmo perdendo di sicuro.$B$BDetto questo, portami altri nuclei e avrai altre insegne.",
  reward = "Ci stai rendendo un grande servizio, $N. Ben fatto!",
}
T[9131] = {
  title = "Forgiare il Dreadnaught",
  desc = "Hai mai visto l'armatura Dreadnaught, $C? No, certo che no. Sei ancora $Gun ragazzino:una ragazzina; — $Gun moccioso:una mocciosa;. Ed è magnifica, te lo dico io.$B$BTi starai chiedendo cosa c'entri tu in tutto questo, vero? Allora senti, $Gpivello:pivella;: mi servono brandelli dei Dark Iron, e per averne il più possibile sono disposto a pagare.$B$BCon quei brandelli metterò insieme dei set di Dreadnaught per i nostri campioni. Tu portameli, e io ti pagherò.",
  obj = "Korfax, a Light's Hope Chapel, in Eastern Plaguelands, vuole 30 Dark Iron Scraps.",
  progress = "<Korfax ti ringhia contro.>$B$BCosa vuoi? Delle indicazioni? Quelle te le posso dare...",
  reward = "Per ora basta così. Se ne recuperi altri, sai dove cercarmi.",
}
T[9132] = {
  title = "Dark Iron Scraps",
  progress = "Per ogni bracciata di brandelli ti darò un'insegna — e più ne porti, meglio è. Ora sparisci dalla mia vista, prima che ti spacchi in due!",
  reward = "Tutto qui quello che mi hai portato? Forse la prima volta non mi hai sentito. Me ne servono DI PIÙ!",
}
T[9136] = {
  title = "Flora Selvaggia",
  desc = "Per i coraggiosi eroi che entrano a Naxxramas realizzo un'armatura speciale, nota come Viandante dei Sogni. Quasi tutti i materiali che mi servono me li procurano loro, ma cerco sempre qualcuno capace di raccogliere savage fronds dalla flora del nostro mondo.$B$BForse penserai che un lavoro simile non sia alla tua altezza, ma senza le fronde l'armatura non si potrebbe fare.$B$BE poi sono l'unica che può pagarti con un fregio a tua scelta, perché mi finanziano sia la Dawn sia la Crusade.",
  obj = "Rayne a Light's Hope Chapel, in Eastern Plaguelands, vuole 30 Savage Fronds.",
  progress = "La flora del nostro mondo la conosco a fondo. Ti servono indicazioni?",
  reward = "Ti sono molto obbligata, $N.$B$B<Rayne si inchina.>$B$BRicorda: le fronde le accetto sempre.",
}
T[9137] = {
  title = "Savage Fronds",
  progress = "Per ogni fascio di fronde che mi porti ti pagherò con un insignia of the Dawn o della Crusade, come preferisci.$B$BI fregi puoi consegnarli all'Intendente in cambio di varie ricompense.",
  reward = "Grazie, $N. Il tuo lavoro è fondamentale perché la nostra campagna contro lo Scourge abbia successo.",
}
T[9141] = {
  title = "Mi Chiamano \"Il Gallo\"",
  desc = "Vuoi un mandato? Cosa? Ti sei $Gpresentato:presentata; e ti aspetti che ti consegni così un ordine di lavoro richiestissimo? Non credo proprio, $Gpivello:pivella;. Per i lavori qui al fronte fanno offerte artigiani da tutto il mondo.$B$BSe un ordine di lavoro lo vuoi, prima mi dimostri che sei $Gdisposto:disposta; a sanguinare per la causa. Portami un emblema del valore, poi ne parliamo.$B$BE su quegli emblemi le tue sudice manine da $Gpivello:pivella; ce le metti in un modo solo — dandoti da fare ad ammazzare.",
  obj = "Dispatch Commander Metz alla Light's Hope Chapel nelle Eastern Plaguelands vuole un Argent Dawn Valor Token.",
  progress = "<Commander Metz mastica il sigaro.>$B$BChe c'è? Sono un uomo impegnato, io.",
  reward = "Bene, funziona così: per ogni emblema del valore che mi porti, ti do un altro mandato. Tu completi l'ordine che c'è scritto sopra e lo consegni a Packmaster Stonebruiser. Capito? Bene. Ora sparisci.",
}
T[9142] = {
  title = "Mandato dell'Artigiano",
  progress = "La procedura la conosci, $Gragazzo:ragazza;: con un emblema del valore ti fai dare un mandato dell'artigiano.",
  reward = "Te lo sei guadagnato, $Gpivello:pivella;. E adesso non lamentarti degli ordini: o li completi o li distruggi.",
}
T[9153] = {
  title = "Sotto l'Ombra",
  desc = "Le necropoli fluttuanti dello Scourge affliggono le terre dell'Orda come quelle dell'Alleanza. Le ombre delle fortezze volanti avvolgono Tanaris, le Blasted Lands, Winterspring e le Burning Steppes.$B$BRiusciremo a respingerle solo se uniamo le forze.$B$BA sostenere le necropoli sono cerchi magici sparsi in vari punti delle aree invase. Abbiamo stabilito che, annientando le orde senza mente intorno a questi cerchi, se ne distruggeranno le difese.",
  obj = "Controlla la mappa per trovare un'area sotto attacco dello Scourge. Vai lì e danneggia una necropoli sconfiggendo le forze dello Scourge che la circondano. Porta 10 Necrotic Runes a Commander Thomas Helleran alla Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "Per avere la meglio su questa minaccia ci vorrà tempo. Tu come te la sei cavata, $N?",
  reward = "Hai fatto un buon lavoro, $N. Una sconfitta dopo l'altra, avremo ragione di questa rinnovata minaccia dello Scourge.$B$BRiposati e riprendi le forze, ma poi dovrai tornare al fronte, per non perdere il terreno che abbiamo guadagnato oggi.$B$BPer aiutarti nelle prossime battaglie, in cambio di altre necrotic runes ti metteremo a disposizione alcuni dei nostri oggetti speciali.",
}
T[9154] = {
  title = "Cappella della Speranza di Luce",
  desc = "Lo Scourge è tornato, e non è mai stato così numeroso. Per difendere le nostre terre, The Argent Dawn sta reclutando ogni uomo e ogni donna che abbia volontà e capacità.$B$BSe la nostra causa è anche la tua, porta questo documento al Keeper of the Rolls: lo troverai alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.",
  obj = "Consegna il Call to Arms Announcement al Keeper of the Rolls, alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.",
  progress = "Sei $Gvenuto:venuta; a unirti al nostro ordine, giusto?",
  reward = "The Argent Dawn ha chiesto aiuto, e tu sei fra quelli che hanno risposto. Non abbiamo tempo per addestrarti, ma ci fidiamo delle tue capacità e contiamo che ti unirai a noi per respingere la minaccia dello Scourge.",
}
T[9165] = {
  title = "Writ of Safe Passage",
  desc = "Se non c'erano gli avventurieri ad aiutarci, la mia carovana non ce l'avrebbe mai fatta! Il Flagello sbucava da ogni angolo e cercava di non farci arrivare fin qui.$B$B<Guard Didier si asciuga la fronte.>$B$BAdesso ci tocca aspettare qui che arrivi Field Marshal Chambers. Sarà lui a firmare il tuo writ of safe passage, e poi tu lo riporterai a Dispatch Commander Metz a Light's Hope Chapel.$B$BE, $N, sta' $Gattento:attenta; a come parli davanti a Chambers. È uno di quelli che \"ti stacca la testa a morsi e ti sputa giù per la trachea\" — solo che lui lo fa davvero...",
  obj = "Consegna il Writ of Safe Passage firmato a Dispatch Commander Metz a Light's Hope Chapel, nelle Eastern Plaguelands.",
  progress = "Nome, grado e numero di matricola!",
  reward = "<Dispatch Commander Metz prende il decreto e lo firma.>$B$BOttimo lavoro, $N. Anzi, eccezionale! Prendi questo come pegno della nostra gratitudine. Senza giochi di parole, $Gpivello:pivella;.",
}
T[9178] = {
  title = "Craftsman's Writ - Dense Weightstone",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta al completamento dell'ordine di lavoro concordato.$B$BOrdine di Lavoro BS-091:$B$B120 Dense Weightstones.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser alla Light's Hope Chapel nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B-Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 120 Dense Weightstones e il Craftsman's Writ - Dense Weightstone — a Packmaster Stonebruiser alla Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "Stai completando un ordine di lavoro, $C?",
  reward = "Già, queste torneranno comode per le armi da botta della fanteria.",
}
T[9179] = {
