T[9183] = {
  title = "Craftsman's Writ - Radiant Circlet",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta al completamento dell'ordine di lavoro concordato.$B$BOrdine di Lavoro BS-80:$B$B3 Radiant Circlets.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser alla Light's Hope Chapel nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B-Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 3 Radiant Circlets e il Craftsman's Writ - Radiant Circlet — a Packmaster Stonebruiser alla Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "Stai completando un ordine di lavoro, $C?",
  reward = "Ancora non riesco a credere che Metz si aspetti che le nostre truppe indossino questa spazzatura di bassa qualità per proteggersi dagli attacchi gelidi dello Scourge.",
}
T[9184] = {
  title = "Craftsman's Writ - Wicked Leather Headband",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta, una volta completato l'ordine di lavoro previsto dal contratto.$B$BOrdine di lavoro LW-971:$B$B10 Wicked Leather Headbands.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser, alla Light's Hope Chapel nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B-Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 10 Wicked Leather Headbands e il Craftsman's Writ - Wicked Leather Headband — a Packmaster Stonebruiser, alla Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "Devi consegnare un ordine di lavoro, $C?",
  reward = "Queste sono... perverse.",
}
T[9185] = {
  title = "Craftsman's Writ - Rugged Armor Kit",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta, una volta completato l'ordine di lavoro previsto dal contratto.$B$BOrdine di lavoro LW-448:$B$B25 Rugged Armor Kits.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser, alla Light's Hope Chapel nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B-Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 25 Rugged Armor Kits e il Craftsman's Writ - Rugged Armor Kit — a Packmaster Stonebruiser, alla Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "Devi consegnare un ordine di lavoro, $C?",
  reward = "I rugged armor kits hanno molti usi, $N. Non servono SOLO a essere schiaffati su certi pezzi d'armatura per avere più protezione. Come questo qui: lo userò come copriteiera.",
}
T[9186] = {
  title = "Craftsman's Writ - Wicked Leather Belt",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta, una volta completato l'ordine di lavoro previsto dal contratto.$B$BOrdine di lavoro LW-736:$B$B9 Wicked Leather Belts.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser, alla Light's Hope Chapel nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B-Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 9 Wicked Leather Belts e il Craftsman's Writ - Wicked Leather Belt — a Packmaster Stonebruiser, alla Light's Hope Chapel nelle Eastern Plaguelands.",
