  reward = "Queste cinture sono addirittura più perverse delle bande — se riesci a credere che sia possibile.",
}
T[9187] = {
  title = "Craftsman's Writ - Runic Leather Pants",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta, una volta completato l'ordine di lavoro previsto dal contratto.$B$BOrdine di lavoro LW-8485:$B$B4 Runic Leather Pants.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser, alla Light's Hope Chapel nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B-Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 4 Runic Leather Pants e il Craftsman's Writ - Runic Leather Pants — a Packmaster Stonebruiser, alla Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "Devi consegnare un ordine di lavoro, $C?",
  reward = "I druidi apprezzeranno di sicuro la maestria con cui sono stati fatti questi pantaloni. Mille grazie, $C.",
}
T[9188] = {
  title = "Craftsman's Writ - Brightcloth Pants",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta, una volta completato l'ordine di lavoro previsto dal contratto.$B$BOrdine di lavoro TR-95:$B$B6 Brightcloth Pants.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser, alla Light's Hope Chapel nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B-Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 6 Brightcloth Pants e il Craftsman's Writ - Brightcloth Pants — a Packmaster Stonebruiser, alla Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "Devi consegnare un ordine di lavoro, $C?",
  reward = "Riesco quasi a vedere il mio riflesso in questa roba! È pazzesco.",
}
T[9190] = {
  title = "Craftsman's Writ - Runecloth Boots",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta al completamento dell'ordine di lavoro concordato.$B$BOrdine di lavoro TR-635:$B$B8 Runecloth Boots.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B— Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 8 Runecloth Boots e il Craftsman's Writ - Runecloth Boots — a Packmaster Stonebruiser alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.",
  progress = "Stai completando un ordine di lavoro, $C?",
  reward = "Per la barba di Bronzebeard! Mi hai portato davvero degli stivali di runecloth... Mi sa che ho perso la scommessa.",
}
T[9191] = {
  title = "Craftsman's Writ - Runecloth Bag",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta al completamento dell'ordine di lavoro concordato.$B$BOrdine di lavoro TR-9999:$B$B8 Runecloth Bags.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B— Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 8 Runecloth Bags e il Craftsman's Writ - Runecloth Bag — a Packmaster Stonebruiser alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.",
  progress = "Stai completando un ordine di lavoro, $C?",
  reward = "Benedetti lacci degli stivali! Sono quello che penso? Le truppe non fanno che lamentarsi della mancanza di spazio per tutto quello che serve sul campo. Uno di loro mi ha perfino fatto un disegnino — che femminuccia...$B$BQueste di sicuro aiuteranno a calmare un po' i piagnistei.",
}
T[9194] = {
  title = "Craftsman's Writ - Runecloth Robe",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta al completamento dell'ordine di lavoro concordato.$B$BOrdine di lavoro TR-7229:$B$B8 Runecloth Robes.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B— Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 8 Runecloth Robes e il Craftsman's Writ - Runecloth Robe — a Packmaster Stonebruiser alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.",
  progress = "Stai completando un ordine di lavoro, $C?",
  reward = "Non dovevi! No, davvero, non dovevi. Non so cosa abbia in testa Metz, ma nessuno andrà a Naxxramas con addosso queste tonache.$B$B<Packmaster Stonebruiser sospira.>$B$BBah, un altro mucchio di robaccia da far mandare al fronte e un'altra sgridata da prendermi da Chambers.",
}
T[9195] = {
  title = "Craftsman's Writ - Goblin Sapper Charge",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta al completamento dell'ordine di lavoro concordato.$B$BOrdine di lavoro EN-11:$B$B20 Goblin Sapper Charges.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B— Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 20 Goblin Sapper Charges e il Craftsman's Writ - Goblin Sapper Charge — a Packmaster Stonebruiser alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.",
  progress = "Stai completando un ordine di lavoro, $C?",
  reward = "Così parli la mia lingua, $C. Roba che fa BUM!",
}
T[9196] = {
  title = "Craftsman's Writ - Thorium Grenade",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta al completamento dell'ordine di lavoro concordato.$B$BOrdine di lavoro EN-7:$B$B20 Thorium Grenades.$B$BTutti gli ordini completati vanno consegnati a Packmaster Stonebruiser alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.$B$BIl contratto è nullo se manomesso o danneggiato.$B$B— Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 20 Thorium Grenades e il Craftsman's Writ - Thorium Grenade — a Packmaster Stonebruiser alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.",
  progress = "Stai completando un ordine di lavoro, $C?",
  reward = "Farle dev'essere costato un bel po' di monete di rame. Ho ragione o ho ragione, $N?",
}
T[9197] = {
  title = "Craftsman's Writ - Gnomish Battle Chicken",
  desc = "Il portatore di questo contratto ha diritto a un pagamento sotto forma di un'insegna a sua scelta, al completamento dell'ordine di lavoro previsto dal contratto.$B$BOrdine di Lavoro EN-0:$B$B4 Galline da Battaglia Gnomesche.$B$BTutti gli ordini evasi vanno consegnati a Packmaster Stonebruiser alla Light's Hope Chapel, nelle Eastern Plaguelands.$B$BIl contratto è nullo e privo di validità se manomesso o danneggiato.$B$B-Dispatch Commander Metz, The Argent Dawn",
  obj = "Consegna 4 Galline da Battaglia Gnomesche e il Craftsman's Writ - Gnomish Battle Chicken — a Packmaster Stonebruiser alla Light's Hope Chapel, nelle Eastern Plaguelands.",
  progress = "Stai evadendo un ordine di lavoro, $C?",
  reward = "Perché sorridi? Cosa c'è di tanto divertente? Senti, $Gfigliolo:figliola;, la gnomish battle chicken è un'unità importantissima e non va presa alla leggera — MAI. Le mandiamo nelle zone che potrebbero essere molto appestate o infestate, e ripuliscono tutti gli insetti appestati o i maggots delle carogne che potrebbero ancora svolazzare in giro. Lo sanno tutti che i robot sono immuni alla peste.$B$BScommetto che adesso non ti senti più tanto $Gfurbo:furba;, eh? $GStupidone:Stupidona;...",
}
