T[9208] = {
  title = "La Savage Guard — Arcanum of Protection",
  desc = "Zanza può creare tanti antichi incantamenti troll, coi componenti adatti! Hai mai sentito parlare della Savage Guard? No, certo che no: hai la mente annebbiata dalla magia inferiore degli elfi.$B$BPortami un arcanum fatto dagli elfi e potrò distruggere quell'aberrazione. Fallo, e la Savage Guard sarà tua.",
  obj = "Zanza the Restless a Zul'Gurub vuole un Arcanum of Protection.",
  progress = "Ce l'hai l'arcanum?",
  reward = "La magia senza valore di questi incantamenti nutre la mia rabbia, e la rabbia mi dà forza.$B$BPortamene altri e avrai un'altra Savage Guard.",
}
T[9209] = {
  title = "La Savage Guard — Arcanum of Rapidity",
  desc = "Con i componenti giusti, Zanza può creare tanti antichi incantamenti troll! La Savage Guard, ne hai mai sentito parlare? No, certo che no. Hai la mente annebbiata dalla magia inferiore degli elfi.$B$BPortami un arcanum di fattura elfica, così potrò distruggere quell'aberrazione. Fallo e la Savage Guard sarà tua.",
  obj = "Zanza the Restless a Zul'Gurub vuole un Arcanum of Rapidity.",
  progress = "Ce l'hai, l'arcanum?",
  reward = "La magia di questi incantamenti non vale niente, e alimenta la mia rabbia. E la rabbia mi dà forza.$B$BPortamene altri e avrai un'altra Savage Guard.",
}
T[9210] = {
  title = "La Savage Guard — Arcanum of Focus",
  desc = "Con i componenti giusti, Zanza può creare tanti antichi incantamenti troll! La Savage Guard, ne hai mai sentito parlare? No, certo che no. Hai la mente annebbiata dalla magia inferiore degli elfi.$B$BPortami un arcanum di fattura elfica, così potrò distruggere quell'aberrazione. Fallo e la Savage Guard sarà tua.",
  obj = "Zanza the Restless a Zul'Gurub vuole un Arcanum of Focus.",
