  reward = "La magia di questi incantamenti non vale niente, e alimenta la mia rabbia. E la rabbia mi dà forza.$B$BPortamene altri e avrai un'altra Savage Guard.",
}
T[9211] = {
  title = "L'Ice Guard",
  desc = "Ah, l'Ice Guard. È un sottile velo di magia protettiva steso su alcuni pezzi dell'equipaggiamento. Chi combatte contro le creature del gelo e del ghiaccio e usa l'Ice Guard sarà protetto meglio dai loro attacchi.$B$BCome tutto quello che crea l'Iracondo, ha un prezzo — e non lo abbasserò, piagnucola quanto vuoi. $GInteressato:Interessata;?",
  obj = "Mataus the Wrathcaster a Light's Hope Chapel, in Eastern Plaguelands, vuole 10 Insignia of the Crusade e 30 monete d'oro.",
  progress = "Senza queste guardie dell'Argent Dawn saresti una macchia sul pavimento.",
  reward = "<Mataus intasca l'oro.>$B$BGoditi le spese di riparazione, $R. Naxxramas è 'poco gentile' con i non iniziati.",
}
T[9213] = {
  title = "La Shadow Guard",
  desc = "Una creazione geniale! La Shadow Guard funziona proprio come l'Ice Guard: un sottile velo di magia protettiva steso su alcuni pezzi dell'equipaggiamento. E come l'Ice Guard, anche la Shadow Guard ti costerà una bella somma.$B$B<Mataus tende la mano e sfrega le dita.>$B$B$GInteressato:Interessata;?",
  obj = "Mataus the Wrathcaster a Light's Hope Chapel, in Eastern Plaguelands, vuole 10 Insignia of the Crusade e 30 monete d'oro.",
  progress = "<Mataus sbadiglia.>$B$BSparisci, insetto, se non hai qualcosa per me.",
  reward = "<Mataus si infila l'oro nella veste.>$B$BChe ci fai ancora qui, $R? Abbiamo concluso i nostri affari.",
}
T[9221] = {
  title = "Armamenti Superiori da Battaglia — Amico della Dawn",
  desc = "Salve, $Gamico:amica;. Hai degli insignias of the Dawn o della Crusade da scambiare con oggetti di potere?$B$BTi devo avvertire; chi compra con reputazione amichevole presso la Dawn paga un sovrapprezzo salato. Ti consiglio di migliorare la tua reputazione con la Dawn prima di andare avanti con i tuoi piani.",
  obj = "In cambio di 30 Insignias of the Dawn e 30 Insignias of the Crusade puoi scegliere un oggetto dal forziere dell'Argent Dawn.",
  progress = "Scegli con cura. Niente rimborsi.",
  reward = "Buona giornata, $N. È stato un piacere fare affari con te.",
}
