T[9229] = {
  title = "Il Fate of Ramaladni",
  desc = "Ramaladni era un guerriero della Confraternita — un allievo di Highlord Mograine da prima ancora che nascesse l'Alba! Quando ha saputo della morte di Mograine, l'odio e la rabbia hanno avuto la meglio su di lui.$B$BDevi capire una cosa, $N: un uomo che si lascia guidare dalla rabbia e dalla vendetta smette di essere un uomo, e diventa l'incarnazione delle emozioni che lo dominano. Così Ramaladni, lo spirito della vendetta, sarebbe entrato a Naxxramas per compierla... e non sarebbe mai più tornato.$B$BEntra a Naxxramas e scopri che fine ha fatto Ramaladni.",
  obj = "Entra a Naxxramas e scopri il Fate of Ramaladni.",
  progress = "Hai notizie di Ramaladni?",
  reward = "È il suo anello! Ma è distrutto. Di Ramaladni non hai trovato nient'altro?$B$B<Korfax fa una smorfia.>$B$BPer Ramaladni non promette niente di buono. L'anello, però... forse si può ancora recuperare.",
}
T[9230] = {
  title = "Ramaladni's Icy Grasp",
  desc = "Riparare questo anello potrebbe essere un'impresa, $N. Vedi, è fatto con le stesse rune che si formano dentro le strutture dello Scourge — come Naxxramas. Mi servono anche altri materiali, ma soprattutto dovresti procurarti quelle frozen runes. Portami quello che mi serve e io riporterò l'anello all'antico splendore.",
  obj = "Korfax, alla Light's Hope Chapel nelle Eastern Plaguelands, vuole che tu gli porti 1 Frozen Rune, 1 Blue Sapphire e 1 Arcanite Bar.",
  progress = "Le Frozen runes dovrebbero trovarsi dentro Naxxramas.",
  reward = "Nemmeno Ramaladni in persona avrebbe saputo fare di meglio! Ecco l'anello, come ti avevo promesso.",
}
T[9232] = {
  title = "L'Unica Canzone Che Conosco...",
  desc = "Ti credi $Gun eroe:un'eroina; dell'Alba, eh? Ho visto i nostri soldati migliori finire travolti dalla plebaglia di Kel'Thuzad! E come potrebbe mai cavarsela a Naxxramas qualcuno così sprovveduto?$B$B<Wilhelm sospira.>$B$BBah, che scelta c'ho? Sei il meglio che riesco a trovare; tanto vale darti una mano.$B$BOmarion mi ha lasciato una ricetta sola. È l'unica canzone che conosco... Di questi pantaloni posso fare qualche variante; a te tocca solo procurarmi i materiali.",
  obj = "Craftsman Wilhelm a Light's Hope Chapel in Eastern Plaguelands vuole che tu gli porti 2 Frozen Runes, 2 Essence of Water, 2 Blue Sapphires e 30 monete d'oro.",
  progress = "Omarion non l'hai incontrato, vero?",
  reward = "<Wilhelm si asciuga il sudore dalla fronte.>$B$BChe faticaccia! Goditeli, questi pantaloni, $C. Almeno adesso morirai con un paio pulito addosso.",
}
T[9233] = {
  title = "Omarion's Handbook",
  desc = "Wilhelm,$B$BSe stai leggendo queste righe, vuol dire che sono morto — finalmente. Sappi che i miei ultimi pensieri sono andati a te e a quanto sei negato nei mestieri. Purtroppo chi porta questo manuale, quanto ad artigianato, è messo perfino peggio di te.$B$BA proposito del libro: qui dentro c'è il resto delle mie ricette. A chi te lo porta prepara tutto quello che chiede. Di sicuro ti farai pagare salato i tuoi servigi, perché dopotutto sei un bastardo.$B$BCon Disprezzo,$B$BOmarion",
  obj = "Porta l'Omarion's Handbook a Craftsman Wilhelm alla Cappella della Speranza di Luce, in Eastern Plaguelands.",
  progress = "È quello che penso?$B$B<Wilhelm sembra sbavare.>",
  reward = "Quando ha scritto 'sta roba doveva aver proprio perso le rotelle! Io e Omarion — eravamo culo e camicia!$B$BComunque, $N, così si aprono nuove possibilità. Adesso posso creare altri oggetti — per un piccolo compenso, più il costo dei materiali, s'intende.",
}
T[9234] = {
  title = "Icebane Gauntlets",
  desc = "Grazie a te e a Omarion, che riposi in pace, adesso posso creare gli Icebane gauntlets. Basta che mi porti i materiali e mi paghi un piccolo compenso per il lavoro.",
  obj = "Craftsman Wilhelm a Light's Hope Chapel in Eastern Plaguelands vuole 5 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essences of Water e 200 monete d'oro.",
  progress = "I materiali li hai portati?",
  reward = "Ecco qua il tuo ordine, $N. Consegnato come promesso!",
}
