T[9237] = {
  title = "Glacial Cloak",
  desc = "Grazie a te e a Omarion, che riposi in pace, adesso posso creare un Glacial cloak. Basta che mi porti i materiali e mi paghi un piccolo compenso per il lavoro.",
  obj = "Craftsman Wilhelm a Light's Hope Chapel in Eastern Plaguelands vuole 5 Frozen Runes, 4 Bolts of Runecloth, 2 Essences of Water, 4 Ironweb Spider Silks e 200 monete d'oro. Devi anche avere la reputazione Osannato con l'Argent Dawn.",
  progress = "I materiali li hai portati?",
  reward = "Ecco qua il tuo ordine, $N. Consegnato come promesso!",
}
