T[9247] = {
  title = "La Chiamata del Custode",
  desc = "$N,$B$BIn passato hai servito gli interessi dell'Argent Dawn dando sempre il meglio di te. Adesso che il bisogno è più grande che mai, suoniamo di nuovo la chiamata a raccolta.$B$B$N, se sei $Gdisposto:disposta; ad aiutarci ancora una volta, ti prego di presentarti al Keeper of the Rolls alla Cappella della Speranza di Luce, nelle Eastern Plaguelands.",
  obj = "Porta la Lettera del Keeper of the Rolls al mittente, alla Cappella della Speranza di Luce, in Eastern Plaguelands.",
  en_title = "The Keeper's Call",
  en_obj = "Take the Letter from the Keeper of the Rolls to him at Light's Hope Chapel in the Eastern Plaguelands.",
}
T[9248] = {
  title = "Un'Umile Offerta",
  desc = "Ishnu-alah, $R. Mostrami la prova che un Signore dell'Abyssal Council è morto, e ti ricompenserò con un oggetto che dovrebbe esserti d'aiuto nelle battaglie contro i Qiraji.",
  obj = "Aurel Goldleaf, a Cenarion Hold, in Silithus, vuole che le porti 1 Abyssal Scepter. Devi anche essere $GOnorato:Onorata; presso il Cenarion Circle.",
  progress = "Fandu-dath-belore? Oh, perdonami, $N. Non ti avevo $Griconosciuto:riconosciuta;. Hai portato lo scettro?",
  reward = "Ande'thoras-ethil. Nella mia lingua madre significa: 'Che i tuoi guai si facciano più piccoli'.$B$BPorta l'anello con orgoglio e in buona salute, $N.",
}
T[9249] = {
  title = "40 Biglietti — Schematic: Steam Tonk Controller",
}
T[9250] = {
  title = "Frame of Atiesh",
  desc = "Con il corpo ormai formato, Atiesh è quasi completo: mancano soltanto la testa e la base del bastone. Resta però un piccolo problema: il bastone fa da tramite al male di Sargeras.$B$BTrova qualcuno che possa aiutarti a rintracciare i pezzi che mancano e a esorcizzare il male dal bastone.",
  obj = "Trova qualcuno che ti aiuti a recuperare gli ultimi due pezzi del bastone e a liberarlo dal male.",
  progress = "La sua ora era giunta, mortale.",
  reward = "Gli arcimaghi sono morti.$B$BNon piangere la loro scomparsa, $N: tutte queste cose sono decise dal fato. Così come era destino che fossi tu a impugnare il bastone del Guardiano...",
}
T[9251] = {
  title = "Atiesh, il Gran Bastone Contaminato",
  desc = "Ti chiedi perché tu sia ancora $Gvivo:viva;, visto che porti con te un oggetto di grande malvagità. La risposta non è chiara, $N. Io faccio solo ciò che devo.$B$BKel'Thuzad siede sul trono a Naxxramas e trama... Cerca ciò che possiedi, e possiede ciò che cerchi.$B$BQuanto alla base del bastone, il nano Brann Bronzebeard l'aveva con sé quando è entrato ad Ahn'Qiraj. Da Ahn'Qiraj poi è uscito, ma la base di Atiesh è rimasta lì.$B$BSe riuscirai a recuperare i pezzi, riportameli.",
  obj = "Anachronos, a Caverns of Time in Tanaris, vuole la Staff Head of Atiesh e la Base of Atiesh.",
  progress = "Così com'è adesso, il bastone è fin troppo pericoloso per stare nelle mani di un mortale.",
  reward = "Dentro c'è un essere... un essere che non è di questo mondo.",
}
T[9257] = {
  title = "Atiesh, Greatstaff of the Guardian",
  desc = "$N, quest'ultimo compito sarà il più difficile di tutti. Hai affrontato e vinto un Old God e il Generale di The Lich King, ma ora devi misurarti con la mano di Sargeras.$B$BPorta il granbastone a Stratholme: lì troverai un pezzo di terra consacrata, il terreno dove sono stati assassinati i più grandi cavalieri di Lordaeron. Posa sul suolo sacro il granbastone contaminato e preparati, perché ne uscirà un'entità dal potere immenso... Sconfiggi l'essere demoniaco che lo controlla e torna da me.",
  obj = "Anachronos a Caverns of Time in Tanaris vuole che tu porti Atiesh, Greatstaff of the Guardian a Stratholme e lo usi sulla Consecrated Earth. Sconfiggi l'entità che viene esorcizzata dal granbastone e torna da lui.",
  progress = "Non mi è concesso interferire, $R.",
  reward = "Non si può sminuire l'importanza di questa impresa, $N. Hai compiuto ciò che quasi tutti avrebbero ritenuto impossibile. Ahimè, così era destino. Il granbastone ha fatto la sua scelta...",
}
T[9259] = {
  title = "Traditore dei Bloodsail",
  progress = "Quel cane rognoso di Revilgaz ha promesso il perdono a tutti gli ex Bloodsail disposti a rivoltarsi contro il loro cap'tano! E quel succhiasentina m'ha chiesto d'andare a far fuori i miei vecchi compari e di portargli le loro bandane, come prova.$B$BIo non ho cuore di farlo, e non lo chiederò nemmeno a te. Portami un po' di silk cloth e di red dye, che ne tiro fuori delle copie come si deve. Al Barone dirò che hai voltato gabbana, ma sta' in guardia... ai Bloodsail non piacerà per niente!",
  reward = "Un minuto di silenzio per i nostri compari caduti, $N.$B$B<Il Bloodsail Traitor ti sorride e ti fa l'occhiolino.>$B$BUn conto è fare il traditore, ma ammazzare i propri compagni... quello sì che sarebbe davvero spregevole, eh sì!",
  en_title = "Traitor to the Bloodsail",
}
T[9260] = {
  title = "Indaga sul Flagello di Stormwind",
  desc = "Lo Scourge si è accampato proprio davanti alle nostre porte, e non possiamo restare con le mani in mano! Tu ti farai avanti per difendere Stormwind da questi maledetti invasori, non è vero?$B $BQui fuori ci sono degli strani cerchi runici: brillano della stessa energia che avvolge i non morti e la Necropoli lassù. Significano qualcosa, ne sono certo, e voglio che tu scopra cosa. Già che ci sei, sfoltisci le file di quelle aberrazioni. Torna con le prove della loro morte e con quello che avrai scoperto, e ti ricompenserò. Vai!",
  obj = "Raccogli tre Dim Necrotic Stones dallo Scourge fuori da Stormwind e indaga sui cerchi runici luminosi vicino al suo accampamento.",
  progress = "Hai già indagato sull'invasione? Non abbiamo tempo per bighellonare!",
  reward = "Mmm. Da quello che mi racconti, le voci dentro i cerchi... in qualche modo devono servire a comunicare. Rabbrividisco al pensiero delle menti innaturali che si raggiungono con una magia del genere. Comunque sia, sembri esserne $Guscito:uscita; $Gintegro:integra; e $Gsano:sana; di mente. The Argent Dawn apprezza i tuoi servigi.",
  en_title = "Investigate the Scourge of Stormwind",
  en_obj = "Collect three Dim Necrotic Stones from the Scourge outside Stormwind and investigate the glowing runic circles near their encampment.",
}
T[9261] = {
  title = "Indaga sul Flagello di Ironforge",
  desc = "Lo Scourge si è accampato proprio alle nostre porte; non possiamo restare con le mani in mano! Ti farai avanti per difendere Ironforge da questi maledetti invasori, vero? $B $BQui fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli sospesa sopra di noi. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Intanto sfoltisci le file di quelle aberrazioni; portami le prove della loro morte insieme ai risultati delle tue indagini, e ti ricompenserò. Va'!",
  obj = "Raccogli tre Dim Necrotic Stones da Scourge fuori da Ironforge e indaga sui cerchi runici luminosi vicino al loro accampamento.",
  progress = "Hai già indagato sull'invasione? Non c'è tempo da perdere!",
  reward = "Mmm. Da quello che mi hai raccontato, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero delle menti innaturali con cui si entra in contatto grazie a una simile magia. Comunque sia, sembra che tu ne sia $Guscito:uscita; $Gintegro:integra; e $Gsano:sana; di mente. The Argent Dawn ti è grata per i servigi resi.",
  en_title = "Investigate the Scourge of Ironforge",
  en_obj = "Collect three Dim Necrotic Stones from the Scourge outside Ironforge and investigate the glowing runic circles near their encampment.",
}
T[9262] = {
  title = "Indaga sul Flagello di Darnassus",
  desc = "Lo Scourge si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Ti farai avanti per difendere Darnassus da questi invasori maledetti, vero? $B $BLà fuori ci sono strani cerchi runici, che brillano della stessa energia che avvolge i non morti e la Necropoli sopra di noi. Hanno un significato, ne sono certa, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quelle aberrazioni; portami le prove della loro morte insieme a ciò che avrai scoperto e ti ricompenserò.  Vai!",
  obj = "Raccogli tre Dim Necrotic Stones dallo Scourge fuori da Darnassus e indaga sui cerchi runici luminosi vicino al loro accampamento.",
  progress = "Hai già indagato sull'invasione? Non c'è tempo da perdere!",
  reward = "Mmh. Da quello che mi hai detto, le voci dentro i cerchi... devono servire a comunicare, in qualche modo. Rabbrividisco al pensiero di quali menti innaturali si possano raggiungere con una magia del genere. In ogni caso, sembra che tu ne sia $Guscito:uscita; $Gintegro:integra; e $Gsano:sana; di mente.  The Argent Dawn apprezza i tuoi servigi.",
  en_title = "Investigate the Scourge of Darnassus",
  en_obj = "Collect three Dim Necrotic Stones from the Scourge outside Darnassus and investigate the glowing runic circles near their encampment.",
}
T[9263] = {
  title = "Indaga sul Flagello di Orgrimmar",
  desc = "Lo Scourge si è accampato proprio alle nostre porte: non possiamo starcene con le mani in mano! Ti farai avanti per difendere Orgrimmar da questi maledetti invasori, vero?$B$BLà fuori ci sono strani cerchi runici che brillano della stessa energia che avvolge i non morti e la Necropoli sopra le nostre teste. Sono certo che vogliono dire qualcosa, e voglio che tu scopra cosa. Già che ci sei, sfoltisci le file di quelle aberrazioni: portami le prove che sono cadute, insieme a quello che avrai scoperto, e ti ricompenserò. Vai!",
  obj = "Raccogli tre Dim Necrotic Stones dallo Scourge fuori da Orgrimmar e indaga sui cerchi runici luminosi vicino al loro accampamento.",
  progress = "Hai già indagato sull'invasione? Non c'è tempo da perdere!",
  reward = "Mmh. Da quello che mi racconti, le voci dentro i cerchi... devono servire, in qualche modo, a comunicare. Rabbrividisco a pensare quali menti innaturali si raggiungano con una magia del genere. Comunque, mi sembra che tu ne sia $Guscito integro e sano:uscita integra e sana; di mente. The Argent Dawn apprezza i tuoi servigi.",
  en_title = "Investigate the Scourge of Orgrimmar",
  en_obj = "Collect three Dim Necrotic Stones from the Scourge outside Orgrimmar and investigate the glowing runic circles near their encampment.",
}
T[9264] = {
  title = "Indaga sul Flagello di Thunder Bluff",
  desc = "Lo Scourge si è accampato alle nostre porte e non possiamo starcene con le mani in mano! Ti farai avanti per difendere Thunder Bluff da questi invasori maledetti, vero?$B$BQui fuori ci sono degli strani cerchi runici: brillano della stessa energia che circonda i non morti e la Necropoli lassù. Sono certa che significano qualcosa, e voglio che tu scopra cosa. E già che ci sei, sfoltisci le file di quegli abomini. Portami le prove della loro morte e quello che avrai scoperto, e ti ricompenserò. Va'!",
  obj = "Raccogli tre Dim Necrotic Stones dallo Scourge fuori da Thunder Bluff e indaga sui cerchi runici luminosi vicino al suo accampamento.",
  progress = "Hai già indagato sull'invasione? Non c'è tempo per bighellonare!",
  reward = "Mmm. Da quello che mi hai detto, le voci dentro i cerchi... devono essere un modo per comunicare. Rabbrividisco a pensare a quali menti innaturali si contattino con una magia simile. Comunque sia, a quanto pare ne sei $Guscito:uscita; $Gintegro:integra; e $Gsano:sana; di mente. The Argent Dawn ti è grata per i tuoi servigi.",
  en_title = "Investigate the Scourge of Thunder Bluff",
  en_obj = "Collect three Dim Necrotic Stones from the Scourge outside Thunder Bluff and investigate the glowing runic circles near their encampment.",
}
T[9265] = {
  title = "Indaga sul Flagello dell'Undercity",
  desc = "Lo Scourge si è accampato proprio davanti alle nostre porte, e noi non possiamo starcene a guardare! Ti farai avanti per difendere l'Undercity da questi invasori maledetti, vero?$B$BLà fuori ci sono strani cerchi runici: brillano della stessa energia che avvolge i non morti e la Necropoli lassù. Qualcosa significano, ne sono certo, e voglio che tu scopra cosa. Intanto sfoltisci le file di quelle aberrazioni: torna da me con una prova della loro morte e con quello che hai scoperto, e ti ricompenserò. Va'!",
  obj = "Raccogli tre Dim Necrotic Stones dallo Scourge fuori da Undercity e indaga sui cerchi runici luminosi vicino al loro accampamento.",
  progress = "Hai già indagato sull'invasione? Non c'è tempo da perdere!",
  reward = "Mmh. Da quello che mi racconti, le voci dentro i cerchi... devono servire a comunicare, in qualche modo. Rabbrividisco a pensare con quali menti innaturali si entri in contatto attraverso una magia del genere. Comunque sia, sembri esserne $Guscito:uscita; $Gintegro:integra; e $Gsano:sana; di mente. The Argent Dawn apprezza i tuoi servigi.",
  en_title = "Investigate the Scourge of the Undercity",
  en_obj = "Collect three Dim Necrotic Stones from the Scourge outside the Undercity and investigate the glowing runic circles near their encampment.",
}
T[9266] = {
  title = "Fare Ammenda",
  progress = "Devi averla fatta davvero grossa a noi o ai nostri amici, $N. Comunque sia, sono qui per offrirti un modo di tornare nelle nostre grazie.$B$BCome sai, a Winterspring fa parecchio freddo, e con tutti noi goblin arrivati da altre città ci farebbe comodo una mano per stare al caldo. Portami un po' di runecloth e di carbone, e metterò una buona parola per te. Ma ti avverto: ai nostri nemici non farà piacere che tu ci dia una mano.",
  reward = "Grazie, $N. Di questo passo ti riscatterai in fretta agli occhi della nostra bella città.",
  en_title = "Making Amends",
}
T[9267] = {
  title = "Ricucire Vecchie Ferite",
  progress = "Faresti meglio a pensarci due volte prima di mettere piede a Ratchet, $N! In giro si parla delle tue malefatte.$B$BPerò sei $Gfortunato:fortunata;: è appena arrivata una nave piena di feriti, reduci da uno scontro con i Bloodsail Buccaneers. Ecco l'occasione per dimostrare che non sei $Gun completo mascalzone:una completa mascalzona;. Dacci una mano: portaci del linen cloth per le bende e delle empty vials per le pozioni.",
  reward = "Sono contenta che tu stia capendo i tuoi errori, $N. Continua a portarci provviste: non ci dimenticheremo di te tanto facilmente, $Gsignorino:signorina;!",
  en_title = "Mending Old Wounds",
}
T[9268] = {
  title = "Guerra in Mare",
  progress = "Vuoi tornare $Gamico:amica; dei goblin di Tanaris, $N? Per respingere i nostri vecchi nemici, i Bloodsail Buccaneers, ci servono materiali per vele e cannoni. Portami tessuto di magitrama e strong flux, e saremo sulla buona strada per perdonarti le offese.",
  reward = "Continua a portarcene, $N. Noi goblin non dimentichiamo tanto facilmente!",
}
