T[9310] = {
  title = "Faint Necrotic Crystal",
  desc = "Sul cadavere dello spettro caduto trovi un cristallo che emana una debole energia necrotica.",
  obj = "Porta il Faint Necrotic Crystal a Lieutenant Rukag nel cortile di Undercity.",
  progress = "Posso aiutarti in qualche modo?",
  reward = "Viene da uno spettro che attaccava la città, dici?$B$BAbbiamo avuto notizia dei campi base delle necropoli che lo Scourge sta evocando. Sospetto che cercassero di crearne uno nell'Undercity. D'ora in poi dovremo stare all'erta.",
  en_title = "Faint Necrotic Crystal",
  en_obj = "Bring the Faint Necrotic Crystal to Lieutenant Rukag in the courtyard of the Undercity.",
}
T[9317] = {
  title = "Consecrated Sharpening Stones",
  progress = "Portami otto necrotic runes degli invasori dello Scourge e potrò darti una consecrated sharpening stone, che dovrebbe esserti di grande aiuto in battaglia contro i servitori di The Lich King.",
  reward = "Grazie, $N. Ecco le tue consecrated sharpening stones: usale con prudenza.",
}
T[9318] = {
  title = "Blessed Wizard Oil",
  progress = "L'Argent Dawn ti darà una fiala di blessed wizard oil in cambio delle necrotic runes degli invasori dello Scourge.",
  reward = "Spero che questi oggetti ti tornino utili nelle battaglie che verranno.",
}
T[9319] = {
  title = "Una Luce nei Luoghi Oscuri",
  desc = "Non siamo i soli a celebrare questa festa, $N. La fiamma tocca ogni creatura, ogni cultura. Anche nei luoghi più oscuri si accendono i fuochi.$B$BSe vuoi vederli con i tuoi occhi, scendi nelle profondità. Cerca i falò che ardono a Stratholme, a Scholomance, tra gli ogres di Dire Maul e nelle sale della stessa Blackrock Spire; attenderò il tuo ritorno.",
  obj = "Trova e tocca i falò situati a Blackrock Spire, Dire Maul, Scholomance e Stratholme, poi torna dal Festival Flamekeeper.",
  progress = "Hai trovato la strada nell'oscurità?",
  reward = "La tua essenza vibra dell'energia delle fiamme che hai scoperto, $N. Il fuoco che hai incontrato è potente e, con le giuste conoscenze, se ne può imbrigliare la forza...$B$B<Il Custode della Fiamma mormora un incantesimo in una strana lingua arcana. Poi estrae una bottiglia luminosa.>$B$BAh! Eccola. Che illumini il tuo cammino, ovunque tu vada.",
}
T[9320] = {
  title = "Major Mana Potion",
  progress = "Fra le altre provviste abbiamo anche diverse major mana potions, e potrebbero tornarti utili. Per quindici necrotic runes te ne do una.",
  reward = "Ecco qua, $N. Stai $Gattento:attenta; là fuori: non siamo abbastanza per permetterci molte perdite sul campo di battaglia.",
}
T[9321] = {
  title = "Major Healing Potion",
  progress = "Fra le altre provviste abbiamo anche un certo numero di major healing potions che potrebbero esserti utili. Te ne do una per quindici necrotic runes.",
  reward = "Ecco qua, $N. Fai attenzione là fuori: non siamo abbastanza numerosi da poterci permettere molte perdite sul campo di battaglia.",
}
T[9322] = {
  title = "Fuochi Selvaggi in Kalimdor",
  desc = "La Midsummer Fire Festival si celebra ovunque su Azeroth, e la variegata terra di Kalimdor non fa eccezione. Mi sembri in forma per viaggiare — forse è il caso di metterti in cammino.$B$BNon si può apprezzare davvero la Mezza Estate senza aver visto i fuochi azzurri e roventi accesi in giro per il mondo. I festeggianti hanno acceso falò nella fredda parte occidentale di Winterspring, nella parte nord-orientale di Azshara, vicino al Valor's Rest nelle distese desolate di Silithus e all'ingresso del lussureggiante Un'Goro. Torna quando avrai completato il viaggio.",
  obj = "Visita gli accampamenti di Mezza Estate situati ad Azshara, Silithus, Un'Goro Crater e Winterspring, poi torna dal Festival Flamekeeper.",
  progress = "Le fiamme di Kalimdor brillano forte?",
  reward = "Il tuo spirito brilla, scaldato dai fuochi di Kalimdor, $Gamico:amica;. Il calore ti rinvigorisce, non è vero?$B$BQuando il potere si sarà affievolito, forse questi ti aiuteranno a sentirlo di nuovo.",
  en_title = "Wild Fires in Kalimdor",
  en_obj = "Visit the Midsummer camps located in Azshara, Silithus, Un'Goro Crater, and Winterspring, then return to the Festival Flamekeeper.",
}
T[9323] = {
  title = "Fuochi Selvaggi negli Eastern Kingdoms",
  desc = "La nostra celebrazione della fiamma si estende per tutto il mondo, $C. Non c'è un solo luogo che il calore di questa festa non abbia toccato, e i fuochi più potenti ardono di un azzurro brillante. Cercali.$B$BNe troverai uno subito a nord di Blackrock Spire. Gli altri sono nel cuore delle Eastern Plaguelands, vicino a una cittadina in rovina, lungo la strada che porta alle scogliere delle montuose Hinterlands e sulla via per il Dark Portal, nelle Blasted Lands.$B$BTorna quando avrai finito il viaggio.",
  obj = "Visita gli accampamenti della Festa del Fuoco situati a Blasted Lands, Eastern Plaguelands, Hinterlands e Searing Gorge, poi parla con il Festival Flamekeeper.",
  progress = "Hai già girato tutto il continente? L'illuminazione ti attende.",
  reward = "Ah, eccoti. Un po' più $Gstanco:stanca;, un po' più $Gimpolverato:impolverata;, ma $Gilluminato:illuminata;! In questa stagione il calore ci raggiunge tutti e ci unisce; il potere dei fuochi che hai toccato ti fa brillare da capo a piedi.$B$BAh, ma immagino che di questi tempi l'illuminazione interiore sembri una ricompensa piuttosto misera per una commissione. Prendi questi, allora, e goditi la festa.",
  en_title = "Wild Fires in the Eastern Kingdoms",
  en_obj = "Visit the Fire Festival camps located in Blasted Lands, Eastern Plaguelands, the Hinterlands and Searing Gorge, then speak with the Festival Flamekeeper.",
}
T[9324] = {
  title = "Il Furto della Fiamma di Orgrimmar",
  desc = "Questa fiamma, rubata dal cuore stesso di Orgrimmar, ti inonda di calore. È un potere allo stato puro che non conosci, ma il Maestro del Sapere potrebbe dirti di più...",
  obj = "Riporta la Flame of Orgrimmar al Festival Loremaster.",
  progress = "Stai praticamente risplendendo, $R. Che cos'hai lì?",
  reward = "Che cos'è? Se non sbaglio, questa fiamma viene dal cuore stesso di Orgrimmar! Il suo calore rovente riflette l'animo feroce degli orchi e dei troll. Che splendida aggiunta alla nostra collezione — quanto sei $Gcoraggioso:coraggiosa; a infiltrarti nella tana del nemico per recuperare il fuoco sacro!",
}
T[9325] = {
  title = "Il Furto della Fiamma di Thunder Bluff",
  desc = "Questa fiamma, rubata agli sciamani di Thunder Bluff, ti inonda di calore. È un potere allo stato puro che non conosci, ma il Maestro del Sapere potrebbe dirti di più...",
  obj = "Riporta la Flame of Thunder Bluff al Festival Loremaster.",
  progress = "Stai praticamente risplendendo, $R. Che cos'hai lì?",
  reward = "Se non vado errato, questo fuoco viene dalle rupi di Thunder Bluff! Come vibra del potere degli spiriti! Sei proprio $Gun vero ladro:una vera ladra;, $N. Eccoti il giusto compenso per la tua bravura. Ora, se solo avessimo le fiamme di tutte e tre le città...",
}
T[9326] = {
  title = "Il Furto della Fiamma di Undercity",
  desc = "Questa fiamma, rubata tra le rovine sopra Undercity, ti inonda di calore. È un potere allo stato puro che non conosci, ma il Maestro del Sapere potrebbe dirti di più...",
  obj = "Riporta la Flame of the Undercity al Festival Loremaster.",
  progress = "Stai praticamente risplendendo, $R. Che cos'hai lì?",
  reward = "Mm... che fuoco strano! È smorzato, quasi cova sotto la cenere, eppure il calore è intenso. E dici che viene da Undercity? Affascinante. Con le fiamme di tutte e tre le città, chissà cosa potremmo realizzare?",
}
T[9330] = {
  title = "Rubare la Fiamma di Stormwind",
  desc = "Rubata dal cuore stesso di Stormwind, questa fiamma ti inonda di calore. Il suo è un potere grezzo che non conosci, ma il Cantastorie forse ne sa di più...",
  obj = "Riporta la Flame of Stormwind al Festival Talespinner.",
  progress = "Ma tu quasi risplendi, $R. Che cos'hai lì?",
  reward = "E questo fuoco che arde così vivo... viene da Stormwind, dici? Straordinario! Chissà che avventura dev'essere stata! Te lo pago, naturalmente. E se trovi qualcos'altro del genere, non mancare di tornare da me a parlarmene.",
}
T[9331] = {
  title = "Rubare la Fiamma di Ironforge",
  desc = "Rubata dal cuore stesso di Ironforge, questa fiamma ti inonda di calore. Il suo è un potere grezzo che non conosci, ma il Cantastorie forse ne sa di più...",
  obj = "Riporta la Flame of Ironforge al Festival Talespinner.",
  progress = "Ma tu quasi risplendi, $R. Che cos'hai lì?",
  reward = "Una fiamma così vigorosa deve venire dalle sale di Ironforge; è salda come i nani stessi. Bel colpo, $N. Se avessi anche i fuochi delle altre città... ah, lasciamo perdere. Ecco il tuo compenso.",
}
T[9332] = {
  title = "Rubare la Fiamma di Darnassus",
  desc = "Rubata dalle rive di Teldrassil, questa fiamma ti inonda di calore. Il suo è un potere grezzo che non conosci, ma il Cantastorie forse ne sa di più...",
  obj = "Riporta la Flame of Darnassus al Festival Talespinner.",
  progress = "Ma tu quasi risplendi, $R. Che cos'hai lì?",
  reward = "Questo fuoco trasuda un antico dolore, $N. Dici che l'hai strappato alle radici di Teldrassil? Affascinante! Eccoti una ricompensa per la tua bravura. Se trovi qualcos'altro del genere torna da me; potrebbe tornarmi utile.",
}
T[9333] = {
  title = "Guanti dell'Argent Dawn",
  progress = "Portami trenta necrotic runes e in cambio ti lascerò scegliere una protezione per le mani. Nella nostra lotta contro lo Scourge dei non morti dovrebbe rivelarsi preziosa.",
  reward = "Bel lavoro, $N. Scegli pure una protezione per le mani, come ringraziamento per l'impegno.",
}
T[9334] = {
  title = "Blessed Wizard Oil",
  progress = "Per le necrotic runes degli invasori dello Scourge, l'Argent Dawn ti darà in cambio una fiala di blessed wizard oil.",
  reward = "Spero che questi oggetti ti servano nelle battaglie che verranno.",
}
