  title = "Major Mana Potion",
  progress = "Fra le altre provviste abbiamo anche un certo numero di major mana potions che potrebbero esserti utili. Te ne do una per quindici necrotic runes.",
  reward = "Ecco qua, $N. Fai attenzione là fuori: non siamo abbastanza numerosi da poterci permettere molte perdite sul campo di battaglia.",
}
T[9338] = {
  title = "Fedeltà al Cenarion Circle",
  progress = "Anche se non hai bisogno delle ricompense materiali che offriamo, questi distintivi restano il segno della fiducia e dell'amicizia che ci legano.$B$BPortameli: se andrai ben oltre il dovere, prenderò debita nota del tuo servizio.",
  reward = "Ci fai onore, $N. Con i tuoi continui sforzi supereremo ogni ostacolo.",
}
T[9339] = {
  title = "La Ricompensa di un Ladro",
  reward = "Oggi hai dimostrato quanto vali, $N.$B$BNon ho molto altro da darti, se non questa corona: un dono degno di $Gun conquistatore:una conquistatrice;. Che illumini il tuo cammino.",
}
T[9341] = {
  title = "Tabard of the Argent Dawn",
  progress = "Hai fatto molto per la nostra causa, $N. Se vuoi, posso darti l'insegna dell'Argent Dawn: siamo fieri di averti fra i nostri alleati.",
  reward = "Prendi questa insegna e portala con orgoglio. Forse le tue gesta spingeranno altri a prendere le armi e a sostenerci nella lotta contro lo Scourge.",
}
T[9343] = {
  title = "Tabard of the Argent Dawn",
  progress = "Hai fatto tanto per la nostra causa, $N. Se lo desideri, posso darti il tabarro dell'Argent Dawn. Siamo orgogliosi di contarti fra i nostri alleati.",
  reward = "Prendi questo tabarro e portalo con orgoglio. Chissà che le tue gesta non spingano altri a prendere le armi per sostenere la nostra lotta contro lo Scourge.",
}
T[9353] = {
  title = "Riscatta l'iCoke Gift Box Voucher",
}
T[9362] = {
  title = "Warlord Krellian",
  desc = "Il tempo stringe, $N! Con i miei incantesimi di divinazione ho scoperto una potente fonte di magia. Io non posso lasciare la torre, e per questo ti chiederei di uccidere la vile creatura che possiede questo manufatto.$B$BSi chiama Warlord Krellian, quel piccolo, patetico cretino, e si nasconde dietro le guardie nel Temple of Zin-Malor. Riducilo in cenere e prendigli la prismatic shell che tanto brama.",
  obj = "Recupera la Prismatic Shell per Archmage Xylem. L'Arcimago risiede in una torre in cima alle scogliere di Azshara.",
  progress = "Non c'è tempo da perdere! Ce l'hai, la conchiglia?",
  reward = "Questa conchiglia ha un'aura strana, devo dire. Visto che l'hai recuperata tu, mi pare giusto che parte della ricompensa sia mettere alla prova le sue capacità magiche...",
}
T[9364] = {
  title = "Magia Frammentata",
  desc = "Con le mie ricerche ho scoperto che la prismatic shell ha un uso singolare.$B$BPortala con te e lancia l'incantesimo polymorph sugli Spitelash di Azshara. Dopo qualche istante l'aura caotica della conchiglia li dividerà per poco tempo in diversi cloni più piccoli: uccidili il più in fretta possibile, e la conchiglia ne raccoglierà l'essenza.$B$BRiportamela quando sarà piena.",
  obj = "Lancia Polymorph sugli Spitelash di Azshara e uccidi i cloni che compaiono qualche secondo dopo. Quando avrai ucciso 50 Polymorph Clones, torna da Archmage Xylem ad Azshara.",
  progress = "Hai raccolto la magia?",
  reward = "Splendido! Splendido!$B$BOra possiamo dare a questa magia la forma di un nuovo incantesimo. Osserva!",
}
T[9365] = {
  title = "La Ricompensa del Ladro",
  reward = "Oggi hai dimostrato il tuo valore, $N.$B$BNon ho molto altro da darti, ma ho questa corona; un dono degno di $Gun conquistatore:una conquistatrice;. Possa illuminarti il cammino.",
}
T[9367] = {
  title = "Il Festival del Fuoco",
  desc = "La Mezza Estate è di nuovo arrivata!$B$BOgni anno, come vuole la tradizione, si scelgono i Custodi della Fiamma che badano ai falò delle nostre capitali. Ci sono fuochi accesi in tutta Azeroth, ma è fondamentale che i nostri siano i più caldi e luminosi, per rendere il giusto omaggio alla stagione.$B$BA dire il vero, avrei un compito per te, se non ti dispiace. Non so ancora se nelle capitali le fiamme ardano tutte come si deve. Vacci di persona e scaldati accanto ai falò — assicurati che scottino per bene!",
  obj = "Tocca i falò di Stormwind, Ironforge e Darnassus, poi parla con un Festival Loremaster nelle capitali.",
  progress = "I fuochi sono accesi?",
  reward = "Eccellente! A quanto pare quest'anno abbiamo nominato Custodi della Fiamma scrupolosi, se i falò sono curati bene come dici. Grazie per averli ispezionati al posto mio; ecco, prendi questo come piccolo segno della mia stima.",
  en_title = "The Festival of Fire",
  en_obj = "Touch the bonfires within Stormwind, Ironforge, and Darnassus, then speak to a Festival Loremaster within the capital cities.",
}
T[9368] = {
  title = "La Festa del Fuoco",
  desc = "La Mezza Estate è tornata!$B$BOgni anno, come vuole la tradizione, si scelgono dei Custodi della Fiamma che curino i falò delle nostre capitali. Mentre i fuochi ardono in tutta Azeroth, è fondamentale che i nostri siano i più caldi e luminosi, per rendere alla stagione il giusto omaggio.$B$BAnzi, se non ti dispiace, ho un compito per te. Nessuno mi ha ancora detto se i fuochi di tutte le capitali ardono come si deve. Va' di persona a scaldarti ai falò — e assicurati che siano caldi!",
  obj = "Tocca i falò di Orgrimmar, Thunder Bluff e Undercity, poi parla con un Festival Talespinner in una delle capitali.",
  progress = "Com'è andata, $N? Hai avuto fortuna?",
  reward = "Eccellente! Se i falò sono curati bene come dici, pare che quest'anno abbiamo nominato Custodi della Fiamma diligenti. Grazie di averli controllati per me. Ecco, accetta questo piccolo segno della mia stima.",
  en_title = "The Festival of Fire",
  en_obj = "Touch the bonfires within Orgrimmar, Thunder Bluff, and the Undercity, then speak to a Festival Talespinner within the capital cities.",
}
T[9378] = {
  title = "DND FLAG La Dread Citadel — Naxxramas",
  desc = "Nel cuore della Plaguewood c'è l'ingresso della temibile cittadella di Naxxramas. Finora le protezioni magiche del portale runico hanno fermato chiunque abbia tentato di entrare. Almeno fino a oggi.$B$BAbbiamo trovato il modo di passare con una specie di occultamento arcano permanente — un vecchio incantesimo minore del Kirin Tor, che ho modificato un po' io. Certo, l'occultamento costa caro; ma la tua dedizione alla causa della Dawn è incrollabile! Le spese le copriamo noi.",
  obj = "Archmage Angela Dosantos, a Light's Hope Chapel in Eastern Plaguelands, ti concederà gratuitamente l'Occultamento Arcano. Devi essere $GOsannato:Osannata; con l'Argent Dawn.",
}
T[9386] = {
  title = "Una Luce nei Luoghi Oscuri",
  desc = "Hai proprio voglia di fare, eh? Se sei $Gdisposto:disposta; a scendere ancora una volta nelle profondità, ti ricompenserò volentieri.$B$BCerca i falò che ardono a Stratholme, a Scholomance, a Dire Maul e nelle sale della stessa Blackrock Spire; non vedo l'ora che tu torni, $N.",
  obj = "Trova e tocca i falò situati a Blackrock Spire, Dire Maul, Scholomance e Stratholme, poi parla con il Festival Flamekeeper.",
  progress = "Hai trovato la strada nell'oscurità?",
  reward = "Hai dimostrato di non essere del tutto inutile, mortale.",
}
T[9388] = {
  title = "Fiamme Tremolanti su Kalimdor",
  desc = "Oggi ardono molte fiamme in tutto il mondo, $N. I fuochi più difficili da curare sono quelli verdi; senza sorveglianza non restano accesi a lungo. Assicurati che le fiamme color smeraldo brucino ancora su Kalimdor per il nostro Custode della Fiamma, eh?$B$BLe troverai vicino a Ratchet, nelle Barrens, nei pressi del Master's Glaive, a Darkshore, nella foresta di Ashenvale, accanto al ponte poco lontano dal Silverwing Outpost, e sulla strada principale delle Stonetalon Mountains, all'altezza della deviazione per la Windshear Crag.",
  obj = "Visita i falò di Ashenvale, Barrens, Darkshore e Stonetalon Mountains, poi parla con il Festival Flamekeeper.",
  progress = "I fuochi non devono spegnersi prima della fine del festival!",
  reward = "Ahhh, allora ardono ancora. Ne sono $Glieto:lieta;; non sarebbe giusto che quelle fiamme si spegnessero prima del tempo. Hai fatto un buon lavoro, $N. Prendi questo, con la mia benedizione.",
  en_title = "Flickering Flames in Kalimdor",
  en_obj = "Visit the bonfires within Ashenvale, the Barrens, Darkshore, and Stonetalon Mountains, then speak with the Festival Flamekeeper.",
}
T[9389] = {
  title = "Fiamme Tremolanti negli Eastern Kingdoms",
  desc = "Per tradizione, la Midsummer Fire Festival illumina la terra con una miriade di fiamme. Alcuni sostengono che i fuochi verdi siano i più belli, perché sono i più difficili da mantenere e hanno una tonalità così particolare.$B$BAssicurati che ardano ancora negli Eastern Kingdoms per il nostro Custode della Fiamma. Si trovano vicino a Dun Modr, nelle Wetlands, nei pressi di Pyrewood Village, nella Silverpine Forest, sulle scogliere che dominano il faro di Westfall e accanto alla torre in rovina delle Hillsbrad Foothills.",
  obj = "Visita i falò di Hillsbrad Foothills, la Silverpine Forest, Westfall e Wetlands, poi parla con il Festival Flamekeeper.",
  progress = "Hai portato a termine il compito?",
  reward = "Dunque sei $Gtornato:tornata; e hai controllato le fiamme color smeraldo del continente. Che ne pensi, mm? Uno spettacolo raro e meraviglioso, senza dubbio. So bene, però, che le ricompense concrete sono più apprezzate... quindi, ti prego, prendi questo per il disturbo.",
  en_title = "Flickering Flames in the Eastern Kingdoms",
  en_obj = "Visit the bonfires within Hillsbrad Foothills, Silverpine Forest, Westfall, and the Wetlands, then speak with the Festival Flamekeeper.",
}
T[9415] = {
  title = "Presentati a Marshal Bluewall",
  desc = "Sei una delle nuove reclute di Marshal Bluewall? Ma certo che sì.$B$BE allora che aspetti? Nel deserto stanno morendo dei bravi soldati. Non vedi l'ora di raggiungerli?$B$BSu, muoviti. E vedi di non disidratarti per strada.",
  obj = "Parla con Marshal Bluewall all'accampamento dell'Alleanza vicino a Hive'Zora.",
  reward = "All'Alleanza servono tutti i combattenti che riesce a trovare. Dalla parte settentrionale del continente all'Orda arrivano rinforzi senza sosta, e noi facciamo fatica a tenere il passo.$B$BTi spiego come stanno le cose.",
  en_title = "Report to Marshal Bluewall",
  en_obj = "Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.",
}
T[9416] = {
  title = "A Rapporto da General Kirika",
  desc = "Tu sarai una delle nuove reclute di General Kirika. Era ora che ti facessi vedere: nel deserto i corpi si consumano in fretta.$B$BAi nani arrivano rinforzi ogni giorno, e nella lotta per le risorse di Silithus non possiamo permetterci di perdere terreno.$B$BLe istruzioni fattele dare dalla Generale. Il mio compito è trovarti, non addestrarti.",
  obj = "Parla con General Kirika all'accampamento dell'Orda vicino a Hive'Regal.",
  reward = "Bene che tu sia qui, ma non c'è tempo da perdere in chiacchiere. Ti servono istruzioni, e poi devi metterti in marcia.$B$BAscolta bene.",
  en_title = "Report to General Kirika",
  en_obj = "Speak with General Kirika at the Horde encampment near Hive'Regal.",
}
T[9419] = {
  title = "Setacciare il Deserto",
  desc = "Da poco abbiamo scoperto che l'Orda va rovistando nel deserto di Silithus in cerca di risorse, ma lì per lì non ci abbiamo badato granché. Mandare tanti uomini in un deserto così torrido non ci sembrava valerne la pena.$B$BPoi però abbiamo capito quanto contano quelle risorse, e adesso stiamo correndo ai ripari.$B$BSe posso contare sul tuo aiuto, va' nel deserto, recupera il silithyst e riportalo qui.",
  obj = "Trova e consegna il Silithyst all'Estrattore di Silithyst, poi parla con Marshal Bluewall all'accampamento dell'Alleanza vicino a Hive'Zora.",
  progress = "Fai attenzione là fuori, però sbrigati. Non abbiamo tempo da perdere.",
  reward = "Sia lodata la Luce, ce l'hai fatta.$B$BAvessimo cominciato prima, adesso non saremmo in una situazione tanto disperata. Non possiamo lasciare che le ricchezze del deserto finiscano nelle mani dell'Orda.",
  en_title = "Scouring the Desert",
  en_obj = "Find and deliver Silithyst to the Silithyst Extractor, then speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.",
}
T[9422] = {
  title = "Setacciare il Deserto",
  desc = "È da tempo ormai che sfruttiamo le risorse di cristallo del deserto di Silithus, e gli unici pericoli erano le creature di questi posti, la sabbia, la polvere e un caldo opprimente.$B$BOra però sembra che l'Alleanza si sia accorta di quello che abbiamo trovato qui. Fra noi e loro è una gara: chi mette le mani sulle risorse naturali e le tiene lontane dall'altra parte.$B$BMi servono tutte le braccia disponibili, e spero di poter contare anche sulle tue.",
  obj = "Trova e consegna Silitisto all'Estrattore di Silitisto, poi parla con General Kirika all'accampamento dell'Orda vicino a Hive'Regal.",
  progress = "Occhio ai pericoli del deserto, $N. Con l'Alleanza in agguato fra le dune, ogni passo potrebbe essere l'ultimo.",
  reward = "Hai lavorato bene, $N. Queste risorse andranno ad aggiungersi alle nostre scorte, e ogni briciola è un guadagno per noi e una perdita per il nemico.",
  en_title = "Scouring the Desert",
  en_obj = "Find and deliver Silithyst to the Silithyst Extractor then speak with General Kirika at the Horde encampment near Hive'Regal.",
}
T[9556] = {
  title = "Al Vincitore...",
  desc = "Avrai certo combattuto a lungo e strenuamente fra le torri, $R. Vorremmo ricompensarti per aver difeso queste terre, ma prima devi dimostrarci che capisci quanto pesano le tragedie avvenute qui.$B$BCerca una fiala di acqua santa per le strade di Stratholme e, quando l'avrai, va' nel quartiere dei maghi di Stormwind o a Undercity... Se in queste terre sarai $Gvittorioso:vittoriosa;, lì troverai il mio collega.",
  obj = "Raccogli una bottiglia di Stratholme Holy Water nella città di Stratholme e consegnala al Lordaeron Mage in Mage Quarter of Stormwind o a Undercity quando la tua fazione è vittoriosa in Eastern Plaguelands.",
}
T[9664] = {
  title = "Creare Nuovi Avamposti",
  desc = "$GBenvenuto:Benvenuta; nelle Plaguelands, $N. Lo sai anche tu: per quanto ci siamo dati da fare, le terre a ovest di qui sono ancora in mano ai Forsaken e ai loro alleati. Così i comandanti dell'Alleanza hanno deciso di costruire nuove fortificazioni qui a est, per stringere il cappio intorno ai nostri nemici.$B$BBisogna conquistare le torri abbandonate dai tempi di Lordaeron e ricostruirle a questo scopo. Sono terre pericolose, queste, e una mano da parte tua ci farebbe comodo.",
  obj = "Conquista Crown Guard Tower, Eastwall Tower, Northpass Tower e Plaguewood Tower nelle Eastern Plaguelands, poi torna da Emmisary Whitebeard a Light's Hope Chapel.",
  progress = "Una volta che le torri saranno nostre, potremo presto circondare i Forsaken. Poi schiacciarli sarà solo questione di tempo.",
  reward = "Molto bene, $N. Sarà importante difendere queste torri dagli attacchi che verranno, e finché non arriveranno i rinforzi a mettere in sicurezza la zona potremmo aver bisogno di te.",
}
T[9665] = {
  title = "Rafforzare le Nostre Difese",
  desc = "Alcuni agenti dei Forsaken hanno scoperto un piano dell'Alleanza: creare nuove basi qui nelle Eastern Plaguelands, nelle torri abbandonate della zona.$B$BÈ fondamentale impedire che si insedino in forze ai nostri confini orientali: questa incursione dell'Alleanza va respinta. Per ora il nostro piano è questo: cacciarli da tutte le torri che potrebbero aver già preso e difendere da altri attacchi quelle che teniamo noi.",
  obj = "Conquista Crown Guard Tower, Eastwall Tower, Northpass Tower e Plaguewood Tower nelle Eastern Plaguelands, poi torna da Emmisary Gormok a Light's Hope Chapel.",
  progress = "Se pensano che gli lasceremmo creare basi così vicino a una delle nostre capitali, sono degli sciocchi.$B$BLi dissangueremo finché non se la daranno a gambe per tornarsene a sud.",
  reward = "Questa è una buona notizia, $N. Qui nelle Plaguelands la lotta non si fermerà finché non avremo respinto del tutto le forze dell'Alleanza.$B$BFino a quel giorno, spero che ci darai ancora una mano.",
}
T[65593] = {
  title = "I Cuori degli Amanti",
  desc = "I cuori degli amanti attirano un incubus, e più l'amore è struggente, più l'esca è irresistibile.$B$BLe mie divinazioni me ne hanno mostrati due che dovrebbero fare proprio al caso nostro.$B$BAvelina Lilly lavora come sarta per i maghi caduti di Ambermill, nella Silverpine Forest. Isaac Pearson, nelle Barrens, spera di lasciare il segno nella città sul mare di Ratchet.$B$BFaticano ai due capi del mondo, eppure i loro cuori sospirano solo l'uno per l'altra. Porta quei cuori a Carendin.",
  obj = "Porta i cuori di Avelina Lilly e Isaac Pearson a Carendin Halgar, nel Temple of the Damned.",
  progress = "Ah, $N, sei $Gtornato:tornata;. Allora, sei $Griuscito:riuscita; a procurarti i cuori degli amanti?",
  reward = "Come previsto. Ottimo lavoro, $N.$B$B<Carendin prende un cuore per mano, poi li accosta piano l'uno all'altro.>$B$BIdioti.",
}
T[65597] = {
  title = "Il Vincolo",
  desc = "È finalmente giunto il momento. Porta i cuori al cerchio di evocazione qui sotto, mettili al centro ed evoca l'incubus.$B$BIl demone non sarà contento di scoprire che l'hai attirato in una trappola. Non cadere preda delle sue lusinghe, $N: devi sottometterlo del tutto.$B$BSolo allora potrò insegnarti l'incantesimo per vincolarlo alla tua volontà.",
  obj = "Usando i Cuori degli Amanti, evoca e sottometti un incubus, poi riporta i Cuori degli Amanti a Carendin Halgar, nel Magic Quarter of the Undercity.",
  progress = "L'incubus è molto abile nel combattimento, ma la sua arma più potente è il fascino illusorio. Basta un solo istante di esitazione e il demone ne approfitterà per soggiogarti.$B$BNon lasciarglielo fare, $N.",
  reward = "Notevole. Davvero notevole. Dare la caccia ai mortali è la specialità dei sayaad. Più di uno stregone si è creduto abbastanza forte da comandarne uno, e invece si è ritrovato a obbedirgli.$B$BQuesta prova non ti ha spezzato, $N: con il tuo impegno ti sei $Gguadagnato:guadagnata; la ricompensa. Ti insegnerò l'incantesimo per evocare l'incubus.",
}
T[65601] = {
  title = "L'Amore Fa Male",
  desc = "Un sayaad maschio si chiama incubus: una creatura profondamente malvagia, con la mente fissa su un solo scopo.$B$BPer attirare il demone nel nostro mondo serve un'esca — un oggetto che rappresenti un grande amore e una grande devozione.$B$BSe ti fidi a farti guidare da un cieco, $N, ascolta. Lungo la via principale di Orgrimmar, a est della Cleft of Shadow, vive Magar, che desidera con tutto il cuore il ritorno del suo compagno, Krilge.$B$BVa' a cercarlo: ti chiederà di trovare una cosa preziosa. È quella la chiave che devi portare a Gan'rul.",
  obj = "Parla con Magar a Orgrimmar.",
  reward = "Chi ti ha parlato di Krilge? Sei $Gvenuto:venuta; a portarmi notizie? Vedi di non prenderti gioco di me...",
}
T[65602] = {
  title = "Che Cos'È l'Amore?",
  desc = "Per tentare un incubus ti servirà un reagente potente — un oggetto che rappresenti grande devozione e amore.$B$BCon le mie divinazioni ho trovato una piccola statuetta che dovrebbe fare al caso tuo per il rituale.$B$BMigliaia di anni fa apparteneva a una giovane coppia. I proprietari di allora non ci sono più, ma il loro cimelio è arrivato fino ai giorni nostri.$B$BSegui la strada verso nord fino ad Ashenvale, poi gira a ovest e supera Maestra's Post. Vedrai una casa immersa tra gli alberi: è lì che troverai quello che cerchi.",
  obj = "Recupera la Wooden Figurine e portala a Gakin the Darkbinder in Mage Quarter of Stormwind.",
  progress = "Sei $Gtornato:tornata;. E ce l'hai fatta, presumo?",
  reward = "<Gakin rigira in mano la statuetta di legno.>$B$BPercepisco l'energia emotiva racchiusa in questo manufatto, rimasta intatta nonostante il tempo passato. L'incubus ne sarà attratto come una mosca dal miele.$B$BTakar non delude mai.",
}
T[65603] = {
  title = "Il Vincolo",
  desc = "È giunto il momento. Prendi la statuetta e scendi nelle cripte qui sotto: è stato preparato un cerchio di evocazione, e dovrai metterla al centro.$B$BA quel punto il portale si aprirà e l'incubus passerà nel nostro mondo.$B$BNon sottovalutare un sayaad. Appena si accorgerà del tuo inganno, il demone ti attaccherà senza esitare, e per sconfiggerlo dovrai usare tutto quello che ti è stato insegnato.$B$BSe ci riesci, torna da me e vincolerò la creatura alla tua volontà. Se fallisci, la tua anima è perduta.",
  obj = "Usando la Wooden Figurine, evoca e sottometti un incubus, poi riporta la Wooden Figurine a Gakin the Darkbinder nello Slaughtered Lamb.",
  progress = "L'incubus proverà a farti abbassare la guardia con lusinghe e inganni: è un demone abile a conquistare il cuore dei mortali.$B$BRicorda che qualunque cosa possa offrirti è falsa. Per lui sei solo una preda.",
  reward = "Non male, $N. Hai sconfitto il demonio, e la tua volontà ne è uscita intatta.$B$BPiù di $Gun:una; $C si è $Gcreduto:creduta; abbastanza forte da vincolare un sayaad, e ha finito per diventare il prossimo pasto del demone. Mi fa piacere vedere che tu non sei così $Gstolto:stolta;.$B$BGuarda bene: ti insegnerò l'invocazione per richiamare l'incubus che hai appena vincolato.",
}
T[65604] = {
  title = "Il Vincolo",
  desc = "Sì... capisco. In questi fili sento le emozioni che vi sono rimaste racchiuse: l'amore è intessuto nelle cuciture. L'incubus non potrà resistere.$B$BPortala al cerchio di evocazione nella tenda di Neeru, $N. Evoca un incubus malvagio e poi mostragli la tua maestria. Non aspettarti che si sottometta senza opporre resistenza: tieni pronta la magia e preparati a combattere. Per molti stregoni, sottovalutare un demone è stato l'ultimo errore.$B$BQuando l'avrai sconfitto, riportami la stoffa: farò sapere a Magar cosa hai trovato.",
  obj = "Usando la Withered Scarf, evoca e sottometti un incubus, poi riporta la Withered Scarf a Gan'rul Bloodeye a Orgrimmar.",
  progress = "I sayaad dominano le menti e torturano le anime. Il loro aspetto ti riempie il cuore di gioia e ti lascia $Gindifeso:indifesa; mentre ti squarciano la carne con fruste e artigli.$B$BNon lasciarti tentare dalle lusinghe dell'incubus, $N: uccidilo in fretta e falla finita.",
  reward = "Ah! $GVittorioso:Vittoriosa;, come previsto!$B$BL'incubus è sottomesso, e sarà un piacere insegnarti a evocarlo. Stai diventando sempre più forte, e non dubito che questo sia solo un trampolino verso poteri ancora più grandi.$B$BRiporterò la sciarpa a Magar. Conosco quell'orco da molti anni, e non avrei mai pensato che tenesse a qualcuno come teneva a Krilge.$B$BCi ricorda cosa ci separa dai demoni: noi ci serviamo della loro oscurità, ma loro non si serviranno mai di noi.",
}
T[65610] = {
  title = "Vorrei Che Fossi Qui",
  desc = "Ho conosciuto Krilge ad Ashenvale, mentre tessevo Mooncloth. Era di stanza lì a proteggere i civili dai pericoli, finché non è sparito...$B$BHanno smesso di cercarlo e lo considerano un disertore, ma io non ci credo.$B$BCi vedevamo spesso al Fallen Sky Lake, prima che lo invadessero quelle bestie di palude aggressive.$B$BDi solito non sono uno che chiede favori, ma se andassi ad Ashenvale a cercare qualche traccia di lui, te ne sarei grato.",
  obj = "Esamina il Fallen Sky Lake ad Ashenvale e riferisci ciò che hai scoperto a Gan'rul Bloodeye a Orgrimmar.",
  progress = "Sì, che c'è?",
  reward = "Cos'hai lì, $N? Una sciarpa di... Mooncloth? Vedi di non provarci con me.",
}
T[76156] = {
  title = "In Agguato con la Madre Terra",
  desc = "Sento che in te si nasconde un talento per le arti sottili, $C. Con questa maschera infiltrati nella miniera della Venture Company, qui vicino, e rubane le provviste. Come travestimento forse non convince, ma a un ladro abile bastano un sorriso irresistibile e una distrazione astuta, nient'altro, per sgusciare oltre qualsiasi guardia. Credo che ne sia capace anche tu.",
  obj = "Intrufolati nella miniera della Venture Company a sud-est di Thunder Bluff e raccogli 5 Seaforium Mining Charges dai carrelli di materiale esplosivo, poi portale a Boarton Shadetotem a Thunder Bluff.",
  progress = "Dovremo lavorare sulla tua furtività, $C. Ti ho sentito arrivare dal momento in cui hai messo piede sull'altopiano.",
  reward = "Mmm... forse i travestimenti non fanno per te.",
}
T[76160] = {
  title = "In Agguato con la Madre Terra",
  desc = "Forse il tuo talento sono i veleni, non i travestimenti. A nord le Arpie fanno il nido su un albero che produce una resina molto tossica. Raccogli le pigne cadute intorno ai nidi, poi schiacciale per farne un unguento. Spalmato su una lama, farà bruciare le ferite nella carne dell'avversario e gli trasformerà il sangue in sale.",
  obj = "Raccogli 8 Windfury Cones a nord di Thunder Bluff, usale con il Mortar and Pestle, poi torna da Boarton Shadetotem a Thunder Bluff con il risultato.",
  progress = "Quando avrai finito, maneggia l'unguento con attenzione, $C. Anche solo toccarlo con la pelle potrebbe fare molto male.",
  reward = "$C, questo non è l'unguento velenoso che ti avevo chiesto. Mi hai portato del burro di pinoli. Sei $Gsicuro:sicura; di aver seguito le mie istruzioni?$B$BSpalmato su un po' di pane speziato servirà molto più che su un pugnale. Però, contro un nemico allergico alla frutta secca, saresti davvero temibile.",
}
T[76240] = {
  title = "In Agguato con la Madre Terra",
  desc = "Mi resta un'ultima idea, e potrebbe essere quella che ci fa riuscire. Sento ancora che in te si nasconde un talento, ma proviamo a farlo uscire per una via meno diretta.$B$BProcurati un Raw Brilliant Smallfish e portalo qui. Con questi pugnali puliscilo e sfilettalo. Non pensarci troppo — fa' quello che ti viene naturale.",
  obj = "Compra o pesca un Raw Brilliant Smallfish, poi usa il Knife Set per sfilettarlo davanti a Boarton Shadetotem a Thunder Bluff.",
  progress = "Hai qualcosa per me?",
  reward = "Che esibizione, $C. Non è la precisione da ladro che speravo, ma hai un'ambidestrezza notevole.$B$BOra capisco che non sarai tu ad addestrare il mio popolo nelle arti sottili, però c'è una cosa che posso insegnarti. Buon viaggio, $C. L'Orda avrà bisogno di eroi come te.",
}
T[78088] = {
  title = "Uno Strano Artefatto",
  desc = "<La sfera misteriosa che hai in mano ti riempie di un terrore gelido. Ti pare quasi di sentire una voce che ti risuona debole nella mente: è bassa, gutturale, e capisci bene che parla una lingua demoniaca.$B$BAnche se sei $Gun:una; $Gpaladino:paladina;, questa magia va oltre le tue capacità. Cerca qui in Kalimdor un paladino più esperto che possa aiutarti a capire la natura di questo oggetto sinistro.>",
  obj = "Porta l'Althalaxx Orb a Delgren the Purifier a Maestra's Post ad Ashenvale.",
  progress = "Hai trovato qualcosa nella torre?",
  reward = "Hai fatto bene a portarmela, $N.",
}
T[78089] = {
  title = "Consigli da Stormwind",
  desc = "In questa sfera c'è una potente oscurità. Che sia di natura demoniaca è chiaro, ma oltre a questo non riesco a capire a cosa serva.$B$BPortala a colei che chiamano Katherine the Pure, nella Cattedrale di Stormwind, e chiedile consiglio.",
  obj = "Porta l'Althalaxx Orb a Katherine the Pure a Stormwind.",
  progress = "Porti notizie da Kalimdor?",
  reward = "<Esamina la sfera con aria preoccupata>",
}
T[78090] = {
  title = "Un Secondo Parere",
  desc = "Non so cosa pensare di questa sfera, $N. Credo che ci servirà l'aiuto di... uno specialista.$B$BSappiamo che a Stormwind opera una setta di stregoni. Ufficialmente, in città gli stregoni non li tolleriamo. Ufficiosamente, quello che sanno può tornare utile quando si ha a che fare con forze demoniache.$B$BTrova un loro rappresentante e chiedigli un parere sulla sfera.",
  obj = "Trova il santuario degli stregoni a Stormwind e chiedi consiglio sulla sfera.",
  progress = "Sei parecchio $Glontano:lontana; dalla cattedrale, $C. Spero che tu sappia che qui non hai nessuna autorità.",
  reward = "Allora la Silver Hand ha bisogno del mio aiuto? E non costerà poco.",
}
T[78091] = {
  title = "Guadagnarsi il Sale",
  desc = "Studierò la sfera e ti dirò cosa scopro, ma prima devi fare una cosa per me.$B$BPer potenziare i rituali di evocazione, gli stregoni del clan Blackrock usano dei sali preparati apposta. Vai a prenderne un po' agli orchi di Redridge.$B$BQuando torni, ti racconterò a cosa mi hanno portato i miei studi.",
  obj = "Raccogli 14 Summoner's Salt dagli Evocatori Blackrock nelle Redridge Mountains, poi torna da Ursula Deline a Stormwind.",
  progress = "<La stregona è intenta a studiare la sfera>",
  reward = "Ah... i sali. Me n'ero scordata del tutto.$B$BNon ho mai visto niente di simile a questa sfera, $N.",
}
T[78092] = {
  title = "Deve Essere Distrutta",
  desc = "Nemmeno una stregona esperta come me può resistere a lungo ai tentacoli di coscienza che si allungano da questa sfera. Mi costa ammetterlo, $N, ma va distrutta.$B$BÈ quasi indistruttibile, però l'arma di un potente signore dei demoni potrebbe avere ragione di lei. Ho sentito dire che una lama del genere si trova ad Ashenvale — nel punto in cui è stato annientato il signore degli abissi Mannoroth.$B$BLì raccogli delle particelle dell'essenza del demone caduto, poi frantuma la sfera sulla lama.",
  obj = "Raccogli 12 Particelle di Mannoroth dai demoni ad Ashenvale. Portale insieme alla Sfera di Althalaxx alla Spear of Mannoroth nel Demon Fall Canyon.",
  progress = "<Ti si rizzano i capelli mentre energie infernali ti avvolgono>",
  reward = "<Sollevi la sfera verso la lancia>",
}
T[78093] = {
  title = "Ritorno da Delgren",
  desc = "<I frammenti della sfera giacciono ai tuoi piedi. Delgren vorrà sapere che ci sei $Griuscito:riuscita;.>",
  obj = "Riporta i Frammenti della Sfera a Delgren.",
  progress = "Hai trovato il modo di distruggere la sfera?",
  reward = "Che sollievo, $N. Ma qualunque cosa stesse osservando Azeroth attraverso quella sfera... ho la sensazione che non sarà contenta di saperla distrutta.$B$BPrendi questo, come ringraziamento per la tua fatica. E... stai $Gattento:attenta;.",
}
