T[78132] = {
  title = "Dragonslayer's Helm",
  progress = "Un tempo l'elmo dell'Ammazzadraghi era di un grande comandante, caduto in battaglia. Si dice che la sua anima tormentata infesti ancora il luogo in cui è morto.",
  reward = "Ottimo lavoro, $N! Con questo ho fatto un altro passo sulla via della gloria.",
}
T[78133] = {
  title = "Dragonslayer's Shield",
  progress = "Si dice che lo scudo dell'Ammazzadraghi sia in mano a un signore della guerra Orchesco, che l'ha rubato durante l'assalto a un insediamento umano.",
  reward = "Ottimo lavoro, $N! Con questo ho fatto un altro passo sulla via della gloria.",
}
T[78134] = {
  title = "Dragonslayer's Lance",
  progress = "La lancia dell'Ammazzadraghi ha cambiato padrone molte volte, e ogni tanto si sparge la voce che sia comparsa in qualche traffico d'armi al mercato nero. Forse chi la tiene adesso, un tipo poco raccomandabile, sarebbe disposto a cederla; a un certo prezzo.",
  reward = "Ottimo lavoro, $N! Con questo ho fatto un altro passo sulla via della gloria.",
}
