T[78261] = {
  title = "L'Horn of Xelthos",
  desc = "<Nel forziere c'è un biglietto>$B$BSalve, $N.$B$BDesidero un tesoro noto come L'Horn of Xelthos: si trova da qualche parte nello Shadowfang Keep.$B$BDi solito nella rocca ci si avventura con dei rinforzi, ma in questo lavoro la cosa fondamentale è non dare nell'occhio.$B$BDevi andarci da $Gsolo:sola;.$B$BNelle Stonetalon Mountains ho un contatto, Veenix, che dovrebbe poterti aiutare a superare il cancello del cortile. Al resto pensi tu.$B$BRiporta qui il corno e subito dopo ti invierò il compenso.$B$B— C",
  obj = "Trova L'Horn of Xelthos nello Shadowfang Keep. Poi riportalo al punto di consegna segreto di C vicino a Pyrewood Village. Devi completare il lavoro da $Gsolo:sola;.",
  progress = "<Il forziere è lì, vuoto.>",
  reward = "<Metti L'Horn of Xelthos nel forziere>",
}
T[78270] = {
  title = "Grimaldelli Goblin",
  desc = "<Nel forziere c'è un biglietto>$B$BSalve di nuovo, $N.$B$BDesidero un tesoro noto come L'Horn of Xelthos: si trova da qualche parte nello Shadowfang Keep.$B$BDi solito nella rocca ci si avventura con dei rinforzi, ma in questo lavoro la cosa fondamentale è non dare nell'occhio.$B$BDevi andarci da $Gsolo:sola;.$B$BNelle Stonetalon Mountains ho un contatto, Veenix, che dovrebbe poterti aiutare a superare il cancello del cortile. Al resto pensi tu.$B$BRiporta qui il corno e subito dopo ti invierò il compenso.$B$B— C",
  obj = "Trova L'Horn of Xelthos nello Shadowfang Keep. Poi riportalo al punto di consegna segreto di C vicino a Pyrewood Village.",
  progress = "Dici che vuoi fare irruzione nella Shadowfang... da $Gsolo:sola;? Hai fegato!$B$BGli esplosivi per superare il cancello te li posso procurare, ma perché nei registri sembri tutto regolare mi serve un ordine di lavoro. Ce l'avrà qualche dipendente qui intorno, probabilmente. Sarà uno che armeggia o costruisce parecchio.",
  reward = "Bel lavoro, $N. Per uno che fa il tuo mestiere sarà stata una passeggiata, immagino.$B$BEcco la merce, come promesso.",
}
T[78307] = {
  title = "L'Horn of Xelthos",
  reward = "<Nel forziere c'è un biglietto>$B$BPer $N. Ci rivedremo.$B$B— C",
}
T[78676] = {
  title = "L'Eye of Bhossca",
  desc = "<Nel forziere c'è un biglietto>$B$BChe piacere riaverti qui, $N.$B$BL'ultimo oggetto dei miei desideri è un artefatto noto come l'Eye of Bhossca: secondo le mie fonti, l'occhio si trova da qualche parte nello Scarlet Monastery. Come per lo Shadowfang Keep, nel monastero devi infiltrarti da $Gsolo:sola;.$B$BPrima di entrare ti gioverebbe procurarti un travestimento: muoverti sarà un tantino più facile. Nei terreni del monastero qualcosa lo troverai di certo.$B$BRiporta qui l'occhio e ti consegnerò il compenso come l'altra volta.$B$B— C",
  obj = "Trova L'Eye of Bhossca nello Scarlet Monastery. Poi riportalo al punto di consegna segreto di C vicino a Pyrewood Village. Devi completare il lavoro da $Gsolo:sola;.",
  progress = "<Il forziere è lì, vuoto.>",
  reward = "<Metti L'Eye of Bhossca nel forziere>",
}
T[78699] = {
  title = "L'Eye of Bhossca",
  reward = "<Dentro il forziere c'è un biglietto>$B$BPer $N. Ti terrò d'\"occhio\".$B$B- C",
}
T[78823] = {
  title = "Il Terrore dei Cieli del Deserto",
  desc = "Il disegno, fatto di tratti larghi e grezzi, sembra rappresentare un grosso uccello rapace. Per quanto la composizione sia semplice, si vede bene che l'artista guardava la creatura con paura e soggezione. Un esperto di caccia grossa potrebbe dirti di più.",
  obj = "Porta il Primitive Drawing a Hemet Nesingwary in Stranglethorn Vale.",
}
T[78830] = {
  title = "Terrore dei Cieli del Deserto",
  desc = "Questo disegno mi fa tornare in mente una storia che ho sentito durante un'altra spedizione, non molto tempo fa. Mi hanno parlato di un grande uccello, Gharrik, che regna sulle Badlands da predatore supremo.$B$BL'ultima volta l'hanno avvistata a nord-est di Camp Cagg. Che il nido sia da qualche parte lì intorno?$B$BPer farla uscire allo scoperto ti servirà un'esca viva. Ti presto una gabbia per catturarne qualcuna, ma nelle Badlands la piccola fauna scarseggia: le esche dovrai cercarle altrove.$B$BUna penna di Gharrik sarebbe un bel trofeo. Tutto l'accampamento parlerebbe di te, puoi starne $Gcerto:certa;.",
  obj = "Ottieni una Crimson Trophy Quill da Gharrik in Badlands. Poi torna da Hemet Nesingwary in Stranglethorn Vale.",
  progress = "Come va la caccia? Non dirmi che l'uccello ha avuto la meglio su di te!",
  reward = "Questa sì che è una penna da mettere in mostra! Ben fatto, $N.$B$BSe vuoi, fermati a riposare qui per un po'. Attraversare il deserto dev'essere stato faticoso, ne sono sicuro.",
}
T[78916] = {
  title = "Il Cuore del Vuoto",
  desc = "La temibile bestia Aku'mai giace morta. Fra le viscere e il sangue del suo cadavere gonfio si nasconde un'enorme perla iridescente che trabocca di pura energia del Vuoto.",
  obj = "Porta la Blackfathom Pearl a Dawnwatcher Selgorm a Darnassus.",
  progress = "$N, che notizie mi porti da Blackfathom?",
  reward = "Aku'mai, il servitore degli Old Gods, è morto: un'impresa degna di veri eroi.$B$BQuesto oggetto potrebbe essere la chiave per capire molto meglio la natura del Vuoto e l'effetto che ha sul nostro mondo. Bisogna studiarlo subito. Grazie, $N.",
}
T[78917] = {
  title = "Il Cuore del Vuoto",
  desc = "La temibile bestia Aku'mai giace morta. Fra le viscere e il sangue del suo cadavere gonfio si nasconde un'enorme perla iridescente che trabocca di pura energia del Vuoto.",
  obj = "Porta la Blackfathom Pearl a Bashana Runetotem a Thunder Bluff.",
  progress = "$N, che notizie mi porti da Blackfathom?",
  reward = "Aku'mai, il servitore degli Old Gods, è morto. Con questa impresa hai fatto un gran bene agli abitanti di Kalimdor.$B$BLa perla, poi, potrebbe essere la chiave per capire molto meglio la natura del Vuoto e l'effetto che ha sul nostro mondo. Bisogna studiarla subito. Cammina con la Madre Terra, $N.",
}
T[79007] = {
  title = "... e quel biglietto che hai trovato",
  desc = "<Le braci si spengono in un debole bagliore e ti imbatti nei resti di un fuoco acceso da poco.$B$BFra le provviste sparpagliate trovi un biglietto bruciacchiato.>$B$B\"Non tutto ciò che brucia è perduto. Trova la terra gemella, trova il luogo.\"",
  obj = "I resti carbonizzati del biglietto sono la tua unica guida.",
  reward = "Ti imbatti nei resti dell'ennesimo cadavere carbonizzato, e intanto lo sguardo ti cade su un messaggio fissato a un'asse di legno.",
}
