T[79090] = {
  title = "Respingere gli Invasori",
  desc = "Alcuni dei Warsong Outriders sono a terra, sconfitti, ma la battaglia infuria ancora...",
  obj = "Porta il Warsong Outrider Mark a Felore Moonray, Priestess of the Moon, alla base del Moonwell ad Ashenvale.",
  progress = "Che notizie porti dal fronte, $N?",
  reward = "Gli invasori dell'Orda continuano a insozzare le nostre terre e a raccogliere risorse dalla natura selvaggia che ci è sacra. Non smettere di scacciarli!$B$BForse questo sacro inno di battaglia ti ispirerà a combatterli con più determinazione. Grazie, $N.",
}
