T[79098] = {
  title = "Ripulisci la Foresta!",
  desc = "Questo è morto, ma quegli esasperanti membri dell'alleanza non smettono di combattere... e questo amuleto cos'è?",
  obj = "Porta il Silverwing Sentinel Charm a Kazragore, Far Seer, alla base del Bonfire ad Ashenvale.",
  progress = "Che notizie porti dal fronte, $N?",
  reward = "Questi cani dell'Alleanza continuano a impedirci di raccogliere le risorse di cui ha bisogno Orgrimmar. Non smettere di scacciarli!$B$BQuesto tamburo di battaglia dei Warsong ti ispirerà a combatterli con più determinazione. Lok'tar Ogar, $N!",
}
T[79192] = {
  title = "Passo Dopo Passo",
  desc = "Il biglietto comincia così: \"Secondo la Missione, tutti e due facevano consegne per la Nuova Piaga. A me paiono solo incidenti da speziali. Se vuoi un posto sicuro per parlare, trova il mio angolino accogliente sulle montagne fra The Barrens e Desolace.\"",
  obj = "Strappi il biglietto dall'asse e leggi le parole scarabocchiate.",
  reward = "Qui si accampano di sicuro sia gli avventurieri delle terre selvagge sia i mercenari. Ti salta all'occhio l'angolo di un biglietto che sventola nella brezza, e allunghi la mano per prenderlo.",
}
T[79229] = {
  title = "Rapina sulla Strada",
  desc = "Davanti a te c'è un accampamento ridotto a una scena raccapricciante. Dai resti si capisce che le vittime erano due umani e un nano. Le ossa portano i segni di un attacco feroce, ma le provviste saccheggiate ti dicono che non è stato un animale. E le ferite non sono nemmeno quelle delle armi dei centauri.$B$BForse chi rovista da tempo in queste terre saprebbe cosa pensarne.",
  obj = "Trova qualcuno a Desolace che sappia qualcosa dell'accampamento saccheggiato.",
  reward = "Ah, così ne hai trovato un altro...",
}
T[79235] = {
  title = "In Fuga",
  desc = "Di scene come quella che descrivi ne ho trovate un paio, $N, e sempre in accampamenti di umani e nani. Fra le carovane si dice che sia stato un gruppo di predoni dell'Orda, e viste le vittime e la brutalità degli attacchi sembra probabile.$B$BPare che i banditi siano fuggiti da Desolace quando si sono trovati alle calcagna un maresciallo dell'Alleanza.$B$BSe vuoi stanarne uno, io darei un'occhiata a Booty Bay: nei porti la gente losca va e viene di continuo, e potresti beccarne uno in cerca di una barca per andarsene da qualche parte.",
  obj = "Trova uno dei predoni di Desolace.",
  reward = "Che ti serve? Fai in fretta.",
}
T[79236] = {
  title = "Una Ciliegia per i Tuoi Pensieri?",
  desc = "Stai con il maresciallo? No, non mi sembra.$B$BLe voci che hai sentito dicono il vero solo a metà. Sì, saccheggiavamo gli accampamenti di umani e nani, ma non per conto dell'Orda: ci pagava un privato.$B$BOffrimi un po' di grog e ti racconto tutta la storia.",
  obj = "Porta un Cherry Grog a Tokal, a Booty Bay, per sentire il resto della sua storia.",
  progress = "Allora, me lo porti quel bicchiere?",
  reward = "Ah, questa sì che è roba buona. Dunque, dov'ero rimasta?",
}
T[79242] = {
  title = "Nessun Onore tra i Ladri",
  desc = "Come stavo dicendo...$B$BIl capo non era dell'Orda: era un'elfa della notte che si chiamava Illari Duskfeather. Ci passava informazioni sugli accampamenti e ci lasciava perfino quasi tutto il bottino, tenendosi solo qualche pezzo fra i più rari.$B$BPerò, appena ci siamo ritrovati il maresciallo alle calcagna, ci ha lasciati a morire. Non so cosa l'abbia spinta a farlo, ma credo che ci abbia usati come capri espiatori.$B$BNon sono una vendicativa, ma non fermerò chi vuole darle la caccia. Se la cerchi, una volta ha parlato di un nascondiglio sulla costa di Arathi.",
  obj = "Trova Illari Duskfeather sulla costa degli Arathi Highlands e ottieni l'accesso al forziere in cui tiene il bottino rubato.",
  progress = "<Apri il forziere con la chiave di Illari.>",
  reward = "<Nel forziere trovi una piccola scatola e qualche moneta.>",
}
T[79358] = {
  title = "Tempesta, Terra e Fuoco",
  desc = "Allagare Thousand Needles non è mica un'impresa da poco, $N. Se non avessi sentito io stesso la furia degli elementi, non ci avrei mai creduto. Eppure eccoci qua.$B$BI quilboar non sono i primi a usare gli elementi come armi in modo sconsiderato, e non saranno gli ultimi. Se vogliamo preparare un nostro contro-rituale, dobbiamo capire meglio questi elementi distorti. Prendi questo libro. Parla dei tanti popoli di Azeroth e di come praticano lo sciamanesimo.$B$BSe riesci a imparare qualcosa da loro, magari troviamo una soluzione.",
  obj = "Raccogli 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems e 5 Twisted Water Totems per Veyric Thunderhame ad Arathi Highlands.",
}
T[79360] = {
  title = "Aiuto Elementale",
  desc = "Adesso che padroneggi gli elementi hai un obbligo verso di loro, e di conseguenza verso tutta Azeroth. Il loro aiuto noi lo chiediamo, il loro potere non lo pretendiamo. È ora di ricambiare i favori che ti hanno concesso, e credo di sapere come.$B$BQuilboar distorcono gli elementi per i loro scopi, e pare che si stiano allargando entro questi confini. Entra nel loro kraul e metti fine a qualunque cosa stiano tramando: queste terre vanno protette.",
  obj = "Sconfiggi Charlga Razorflank a Razorfen Kraul e raccogli informazioni sui piani dei quilboar.",
  progress = "Pericolo? Non ci è arrivata nessuna segnalazione del genere. E le nostre wind riders hanno troppo da fare per perdere tempo dietro alle storie di fantasmi.",
  reward = "<Consegni il biglietto a Bath'rah, che lo legge e fa una risatina poco convinta.>$B$BAh, allora è vero, mon... Pure io ho sentito tanta agitazione nel piano elementale, e una delle cause dev'essere 'sta cosa qua.$B$BCi vorrebbe una gran tempesta per inondare tutto Thousand Needles, e si perderebbero un sacco di vite.$B$BCredo d'avere giusto la cosa che fa per te, ma non sarà facile.",
}
T[79361] = {
  title = "Tempesta, Terra e Fuoco",
  desc = "Quindi quilboar vogliono inondare Thousand Needles con il loro sciamanesimo distorto, eh? Sembra quasi impossibile da immaginare, ma l'hai visto tu $Gstesso:stessa;: queste creature non vanno prese alla leggera.$B$BAvrei voluto continuare il tuo addestramento come si deve, ma adesso non c'è tempo. In queste terre vivono tante creature diverse, amiche e nemiche, e nessuna merita una sorte simile. Dobbiamo agire.$B$BPrendi questo tomo. Serviva per lo studio, ma ora potrebbe essere la chiave per disperdere la tempesta che sta arrivando.",
  obj = "Raccogli 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems e 5 Twisted Water Totems per Prate Cloudseer a Thousand Needles.",
  progress = "Ah, ti stai impolverando un po', là fuori?",
  reward = "Oh sì, sì. Adesso sì che ci siamo.",
}
T[79362] = {
  title = "Grant's Shield",
  desc = "Uno scudo lasciato dallo spettro di Grant Valor, padre della famiglia Valor ed eroe di Raven Hill.$B$BVisto che lo spirito di Grant combatte ancora i non morti, forse il suo conto in sospeso era uccidere il flagello che lo ferì nel Raven Hill Cemetery. Probabilmente è quello che ha ancora la sua mazza conficcata addosso.",
  obj = "Trova la Grant's Mace su uno degli scheletri nel Raven Hill Cemetery, poi torna da Sirra Von'Indie a Darkshire per altre informazioni.",
}
T[79363] = {
  title = "Silvia's Sword",
  desc = "Una spada lasciata dallo spirito della guardia di Raven Hill, Silvia Valor, che passò la vita a proteggere i civili e le loro case.$B$BDato che lo spirito di Silvia visita ancora le fattorie, forse il compito che le restava era sbaragliare i defias che si sono stabiliti ad Addle's Stead, a sud di Raven Hill.",
  obj = "Sconfiggi 7 Lame Notturne Defias e 7 Incantatori Defias ad Addle's Stead, poi torna da Sirra Von'Indi a Darkshire per avere altre informazioni.",
  progress = "Ti sei già $Gcacciato:cacciata; in qualche pericolo?",
  reward = "Togliti di dosso 'sto fango, abbiamo quasi finito.",
}
T[79364] = {
  title = "Occhi al Cielo",
  desc = "Stando al biglietto che hai trovato, i Razormane si sono intanati a Thousand Needles per una specie di rituale nascosto. Tempeste furiose e maree che salgono...$B$BQuilboar staranno usando qualche crudele stregoneria imparata da Hirzek, uno sciamano che si è spinto molto in là pur di distorcere gli elementi. Per inondare il canyon gli servirebbero poteri elementali devastanti.$B$BNon siamo pronti ad affrontare una cosa del genere, ma $Gun potente sciamano:una potente sciamana; come te avrà di sicuro un'idea. Torna dai tuoi alleati e vedi se riesci a trovare una risposta.",
  obj = "Parla con Prate Cloudseer a Thousand Needles.",
  progress = "Per contenere questi elementi ci serve una fiala più grande e cristallina.",
  reward = "Sapevo che potevo contare su di te.",
}
T[79365] = {
  title = "Con il Vento Sotto le Ali",
  desc = "Ecco, mon, ti serve una Squall-breakers Potion. Bevila e ti proteggerà dagli elementi della tempesta, ma ricorda che dura poco.$B$BOra va', torna dai tuoi amici in difficoltà. Per te non posso fare altro.",
  obj = "Torna da Rau Cliffrunner a Thousand Needles, a Freewind Post.$B$BOggetto fornito:",
  reward = "Le nostre wind riders hanno trovato qualcosa, ma non sono riuscite ad avvicinarsi abbastanza da capire cosa succede. Sei $Griuscito:riuscita; a trovare qualcosa che possa aiutarci?",
}
T[79366] = {
  title = "Ascolta il Mio Richiamo",
  desc = "Ora che hai i totem distorti, dobbiamo usarli per evocare gli elementali corrotti che quilboar stanno invocando. Sconfiggili: così purificherai queste terre e metterai fine all'abominevole rituale dei Razormane. Poi torna da Rau Cliffrunner a dire che ce l'hai fatta. Ti conviene cominciare la purificazione dalle pozze di vapore a ovest, dove abbondano tutti gli elementi. Ma fai attenzione, $N: quilboar non resteranno con le mani in mano mentre mandi all'aria i loro piani.",
  obj = "Usa i Totem Distorti per porre fine al rituale dei quilboar.",
}
T[79442] = {
  title = "Le Armi di Tempest",
  desc = "Il nostro popolo non potrà mai ringraziarti abbastanza, ma io di quest'occhio non saprei proprio che farmene. Ho sentito parlare di un vecchio sciamano, sulle montagne di Alterac, che ha occhio per la magia degli elementali della tempesta. Forse lui potrebbe crearti qualcosa.",
  obj = "Consegna l'Eye of the Tempest a Bath'rah the Windwatcher in Alterac Mountains.",
  progress = "Ahh! Pare che sei $Gtornato:tornata; $Gtutto:tutta; $Gintero:intera;, eh. E allora, com'è andata con 'sta pozione?$B$BBeh, meno male che avevo fiducia in te. Perché quella pozione è solo un gran bel punch, $Gfratello:sorella;. Contro quelle tempeste è molto più buona che efficace.$B$BSu, su... non essere $Garrabbiato:arrabbiata; con me. Ti serviva solo un po' d'incoraggiamento. È andata come doveva andare fin dall'inizio.$B$BMa già che sei qui... ho notato quel gran bell'occhio che hai in mano...",
  reward = "Facciamo così. Basta trucchi, basta giochi. Ho una cosa che t'interessa.$B$BTu mi dai quell'occhio e io ti do questa gran bella runa, pronta a insegnarti trucchi nuovi.$B$BChe ne dici?",
}
T[79482] = {
  title = "Dolci Rubati di Winter Veil",
  desc = "Senti... non vorrei rompere l'incanto della stagione, ma Smokywood Pastures avrebbe bisogno di un po' d'aiuto — quello per cui voi tipi da avventura siete famosi.$B$BCi manca un'importante spedizione di dolci che doveva rifornirci per la stagione, e adesso è sparito pure l'agente di Smokywood Pastures che avevamo mandato a cercarla! Ti prego — l'ultima volta la spedizione è stata segnalata nelle Alterac Mountains, ed è lì che è andato il nostro uomo.$B$BVedi se riesci a trovarli tutti e due sani e salvi!",
  obj = "Trova l'investigatore di Smokywood Pastures scomparso nelle regioni innevate delle Alterac Mountains.",
  reward = "M-m-mi s-s-senti! Sia l-l-lodato il b-b-bilancio!$B$BNon sono mica un p-p-pupazzo di neve — mi c-c-chiamo Sacks e l-l-lavoro alla f-f-filiale di Ironforge di Smokywood Pastures... Mi hanno m-m-mandato qui a cercare un p-p-pacco s-s-scomparso, quando una c-c-creatura che non avevo mai v-v-visto p-p-prima mi ha attaccato!$B$BFa c-c-così f-f-freddo...",
}
T[79483] = {
  title = "Dolci Rubati di Winter Veil",
  desc = "Senti... non vorrei rompere l'incanto della stagione, ma Smokywood Pastures avrebbe bisogno di un po' d'aiuto — quello per cui voi tipi da avventura siete famosi.$B$BCi manca un'importante spedizione di dolci che doveva rifornirci per la stagione, e adesso è sparito pure l'agente di Smokywood Pastures che avevamo mandato a cercarla! Ti prego — l'ultima volta la spedizione è stata segnalata nelle Alterac Mountains, ed è lì che è andato il nostro uomo.$B$BVedi se riesci a trovarli tutti e due sani e salvi!",
  obj = "Trova l'investigatore di Smokywood Pastures scomparso nelle regioni innevate delle Alterac Mountains.",
  reward = "M-m-mi s-s-senti! Sia l-l-lodato il b-b-bilancio!$B$BNon sono mica un p-p-pupazzo di neve — mi c-c-chiamo Sacks e l-l-lavoro alla f-f-filiale di Orgrimmar di Smokywood Pastures... Mi hanno m-m-mandato qui a cercare un p-p-pacco s-s-scomparso, quando una c-c-creatura che non avevo mai v-v-visto p-p-prima mi ha attaccato!$B$BFa c-c-così f-f-freddo...",
}
T[79492] = {
  title = "Metzen the Reindeer",
  desc = "È successo un DISASTRO! Hanno rapito Metzen the Reindeer!$B$BMetzen è una delle otto renne di Greatfather Winter — e proprietà di Smokywood Pastures. Ci sono arrivate non una ma DUE ransom letters, da gruppi che dicono di avere Metzen. Con le feste ormai ben avviate, qui siamo a corto di soldi! Ti prego — trova Metzen e riportacelo!$B$BCerca indizi nelle ransom letters, e spargigli addosso questa polvere di renna — lo libererà da qualsiasi legame!$B$BTi prego, fai presto!",
  obj = "Trova Metzen the Reindeer. Usa le note che ti sono state date per trovare indizi su dove è tenuto prigioniero.$B$BQuando trovi Metzen, tieni con te il Pouch of Reindeer Dust per poter spargere un po' di polvere su di lui; questo dovrebbe liberare Metzen dalla prigionia.$B$BRiporta il Pouch of Reindeer Dust a Wulmort Jinglepocket a Ironforge una volta liberato Metzen.",
  progress = "$N! Le note nella bisaccia che ti ho dato ti sono bastate per trovare Metzen? Non oso pensare a cosa potrebbero fargli quei delinquenti crudeli... ma un riscatto così esorbitante non possiamo proprio permettercelo!",
  reward = "Ce l'hai fatta! Urrà!$B$BMetzen è appena tornato in volo alle stalle di Greatfather Winter — sì, Metzen vola davvero! La polvere ha funzionato a meraviglia; lo sapevo. Hai salvato dal disastro la Feast of Winter Veil, e con lei Smokywood Pastures. Grazie, $N.$B$BSenti... per quello che hai fatto qui, voglio che tu abbia questo. È una cosa MOLTO speciale: se hai una cavalcatura, credo che ti divertirai un mondo. Buon Winter Veil!",
}
T[79495] = {
  title = "Metzen the Reindeer",
  desc = "È successo un DISASTRO! Hanno rapito Metzen the Reindeer!$B$BMetzen è una delle otto renne di Great-father Winter — e appartiene alle Smokywood Pastures. Ci sono arrivate non una, ma DUE ransom letters, da gruppi che sostengono di avere Metzen. Le feste sono ormai nel vivo e qui la cassa è a secco! Ti prego — trova Metzen e riportacelo!$B$BCerca indizi nelle ransom letters e cospargilo con questa polvere di renna — scioglierà qualsiasi legame!$B$BTi prego, sbrigati!",
  obj = "Trova Metzen the Reindeer. Cerca nei biglietti che ti sono stati dati indizi su dove è tenuto prigioniero.$B$BQuando trovi Metzen, tieni con te il Pouch of Reindeer Dust per poterlo cospargere con un po' di polvere; dovrebbe liberare Metzen dai legami della prigionia.$B$BRiporta il Pouch of Reindeer Dust a Kaymard Copperpinch a Orgrimmar una volta liberato Metzen.",
  progress = "$N! L'hai trovato? Ti sono bastati i biglietti nella borsa che ti ho dato per rintracciare Metzen? Non voglio nemmeno pensare a cosa potrebbero fargli quei teppisti crudeli... ma un riscatto così esorbitante non possiamo proprio permettercelo!",
  reward = "Ce l'hai fatta! Urrà!$B$BMetzen è tornato poco fa in volo alle stalle di Great-father Winter — sì, sa volare davvero! La polvere ha funzionato a meraviglia; lo sapevo. Hai salvato dal disastro la Feast of Winter Veil, e con lei le Smokywood Pastures. Grazie, $N.$B$BSenti... per quello che hai fatto, voglio che tu abbia questo. È una cosa MOLTO speciale: se hai una cavalcatura, credo che ti divertirai un mondo. Buon Winter Veil!",
}
T[79535] = {
  title = "Basilisks: Should Petrification be Feared?",
  progress = "Hai portato qualcosa per la nostra collezione?",
  reward = "Grazie, $N. Con il tuo impegno il nostro sapere cresce.$B$BSe trovi altre opere magiche che potrebbero servire alla biblioteca, ti prego, portamele.",
}
T[79536] = {
  title = "$GGrande Amico:Grande Amica; di The Library",
  reward = "Grazie alle tue donazioni la biblioteca prospera.$B$BTi prego, prendi questo.",
}
T[79624] = {
  title = "Chiunque Può Cucinare",
  desc = "Sembra la ricetta di qualche piatto di carne, scritta in una lingua che non capisci. Vista la provenienza e l'argomento, probabilmente è Ogre.$B$BGli Ogres di solito non sono tipi da fornelli, ma se ne conoscessi uno con questa inclinazione, potrebbe tradurtela.",
  obj = "Trova un ogre in grado di leggere l'Illegible Recipe.",
  progress = "Chi tu? Forse primo cliente di Skonk?",
  reward = "Tu avere ricetta? Skonk ascoltare.",
}
T[79637] = {
  title = "Un Ticking Present",
  reward = "I tuoi amici degli Smokeywood Pastures ti augurano una gioiosa Feast of Great-Winter.",
}
T[79677] = {
  title = "Una Spesa Veloce",
  desc = "Altri ogres ride di Skonk, perché Skonk più piccolo di loro. Loro dice che ogre piccolo è debole, e allora Skonk impara cucinare, no combattere. Così loro prende in giro ancora di più, e Skonk scappa via per seguire sogno.$B$BSkonk sa fare piatto, però serve ingredienti. Tu prendi appunti. Trova ingredienti. Skonk più concentrato su arte; non proprio tipo da logistica.",
  obj = "Raccogli gli ingredienti per il piatto di Skonk, poi portaglieli negli Arathi Highlands",
}
T[79731] = {
  title = "La Pergamena dei Troll",
  desc = "<Sotto i tuoi occhi, gli antichi glifi prendono la forma di parole.>$B$BGli dèi concederanno la loro benedizione quando le acque della sorgente sacra scorreranno nella fontana di Zul'Kunda.",
  obj = "Risolvi l'enigma della pergamena. Fatto questo, a Hemet Nesingwary potrebbe far piacere ascoltare la storia.",
  reward = "Una fontana magica nascosta nella giungla? Che storia, $N!$B$BEcco l'idea per un altro capitolo del libro! Vediamo un po', dove ho messo il manoscritto...",
}
