T[79974] = {
  title = "Lavoro Bagnato",
  desc = "\"Mi piace avere sempre una scorta di riserva qui vicino, caso mai dovessi scappare in fretta.$B$BLa parete di questa montagna è così bella che sembra scolpita dalle cascate del tempo.$BQuello è il nido delle aquile: è ciò che stai cercando.\"",
  obj = "Spolverando una borsa da messaggero che spunta dal terreno, trovi una pergamena infilata tra le provviste.",
  reward = "Ingegneria Nanica, sempre una meraviglia.",
}
T[79975] = {
  title = "Pugno dell'Aquila",
  desc = "<Dentro la cassetta degli attrezzi trovi una lettera piegata con cura.>$B$B\"Da qui, con gli attrezzi giusti, detti legge tu. Ottimo posto per lanciare un aliante a paracadute.$B$BPer servire al meglio l'Aquila e il Pugno, devo restare a distanza: è una questione di lealtà. Questa barricata ha visto giorni migliori, come i Vecchi Regni che un tempo difendeva, ma non la abbandonerò mai.\"",
  obj = "Gli spruzzi d'acqua inumidiscono l'aria, la vista è incredibile.",
  reward = "Qualcuno ha appena aggiunto legna a un falò, ma si vede bene che è partito in fretta.",
}
T[79976] = {
  title = "Dev'Essere Questo il Posto",
  desc = "\"Allora, ho deciso di riportare il mio lavoro sottoterra. Perché non finisca nelle mani sbagliate.\"$B$B<La carta è strappata quel tanto che basta a contenere il messaggio. Non sai se siano le ultime parole dell'autore che leggerai, o un indizio per il prossimo nascondiglio. Un sacco a pelo legato male ti si sta srotolando sui piedi...>",
  obj = "Chiunque ci fosse, se n'è appena andato.",
  reward = "Un pesante telo avvolge attrezzi di vario tipo. Ti prendi lo zaino.",
}
T[79980] = {
  title = "Arrampicata",
  desc = "\"Niente male, eh? Se stai leggendo queste righe, la mia scorta è ancora lì. Fai cento passi dritto verso nord, e quando scendi dal dirupo non romperti le caviglie. Dovrebbe essercene abbastanza per tirare avanti.\"",
  obj = "Trova ciò che ti aspetta.",
  reward = "Dal terreno tiri fuori una borsa da messaggero, e fra le provviste trovi infilata una pergamena sporca.",
}
T[80001] = {
  title = "Riaccendere",
  progress = "Un focolare spento. E la legna è persino abbastanza asciutta per prendere fuoco.",
  reward = "Metti a frutto le tue doti da $Gesploratore:esploratrice;.",
}
T[81570] = {
  title = "Jarl Ha Bisogno di una Lama",
  desc = "Ho da tagliare. Cosa taglierò non posso dirtelo, ma... mi serve una lama. Una lama particolare...$B$BC'è chi la chiama moonsteel broadsword. Io la chiamo lama da fendente.$B$BMi aiuti? Magari la trovi in città, o magari parli con un fabbro e te la fa apposta.$B$BMa non dormirci sopra. Quello che taglio non si conserva per sempre...",
  obj = "Porta un Moonsteel Broadsword a Jarl in Dustwallow Marsh.",
  progress = "Ce l'hai la mia lama??",
  reward = "È una bella lama. Fa un bel fendente. È una bella lama da fendente. Grazie. Grazie, grazie, grazie!!! Adesso voglio provarla....$B$BDopo. La provo dopo. Ma come dicevo... grazie.",
}
T[81730] = {
  title = "Missione di Duskwood I: Sconfiggi i Worgen",
  desc = "Mentre qui questi demoni ci distraggono, The Emerald Dream viene corrotto e si trasforma in incubo. Presto, attraversa il Portale di The Emerald Dream nel Twilight Grove e raggiungi l'Incursione dell'Incubo nel Rotting Orchard. Sconfiggi i worgen che ci trovi, poi torna da me.",
  obj = "Sconfiggi 10 Nightmare Runners e 10 Nightmare Weavers nell'Incursione dell'Incubo di Duskwood in Rotting Orchard e torna da Field Captain Palandar.",
  reward = "Ben fatto! I tuoi servigi saranno ben ricompensati. Ti andrebbe un'altra missione?",
}
T[81731] = {
  title = "Missione II a Duskwood: Sconfiggi gli Ogres",
  desc = "Questi demoni ci tengono distratti qui, e intanto la corruzione sta trasformando The Emerald Dream in un incubo. Presto, attraversa il Portale di The Emerald Dream nel Twilight Grove e raggiungi l'Incursione dell'Incubo al Vul'gol Ogre Mound. Sconfiggi gli ogres che ci troverai, poi torna da me.",
  obj = "Sconfiggi 3 Deranged Ogres e 3 Demented Fire Weavers nell'Incursione dell'Incubo di Duskwood a Vul'gol Ogre Mound e torna da Field Captain Palandar.",
  progress = "Allora, ti sei $Goccupato:occupata; degli ogres?",
  reward = "Ben fatto! Per i tuoi servigi avrai una buona ricompensa. Un'altra missione, magari?",
}
T[81732] = {
  title = "Missione III a Duskwood: Sconfiggi i Dragonidi",
  desc = "Questi demoni ci tengono distratti qui, e intanto la corruzione sta trasformando The Emerald Dream in un incubo. Presto, attraversa il Portale di The Emerald Dream nel Twilight Grove e raggiungi l'Incursione dell'Incubo presso The Yorgen Farmstead. Sconfiggi i dragonidi che ci troverai, poi torna da me.",
  obj = "Sconfiggi 3 Wyrmkin Terrorwalkers e 10 Nightterror Whelps nell'Incursione dell'Incubo di Duskwood a the Yorgen Farmstead e torna da Field Captain Palandar.",
  reward = "Ben fatto! Per i tuoi servigi avrai una buona ricompensa. Un'altra missione, magari?",
}
T[81733] = {
  title = "Missione IV a Duskwood: Informazioni sugli Ogre",
  desc = "Questi demoni ci tengono distratti qui, e intanto la corruzione sta trasformando The Emerald Dream in un incubo. Presto, attraversa il Portale di The Emerald Dream nel Twilight Grove e raggiungi l'Incursione dell'Incubo al Vul'gol Ogre Mound. Lì troverai Dreamwarden Thalinar: fatti dare un rapporto informativo e torna da me.",
  obj = "Raccogli informazioni da Dreamwarden Thalinar nell'Incursione dell'Incubo di Duskwood, nelle profondità di Vul'gol Ogre Mound, e torna da Field Captain Palandar.",
  progress = "Ce l'hai, il rapporto?",
  reward = "Ben fatto! Per i tuoi servigi avrai una buona ricompensa. Un'altra missione, magari?",
}
T[81734] = {
  title = "Missione V a Duskwood: Informazioni sui Worgen",
  desc = "Questi demoni ci tengono distratti qui, e intanto la corruzione sta trasformando The Emerald Dream in un incubo. Presto, attraversa il Portale di The Emerald Dream nel Twilight Grove e raggiungi l'Incursione dell'Incubo al Rotting Orchard. Lì troverai Dreamwarden Dorilar: fatti dare un rapporto informativo e torna da me.",
  obj = "Raccogli informazioni da Dreamwarden Dorilar nell'Incursione dell'Incubo di Duskwood, nel fienile a Rotting Orchard, e torna da Field Captain Palandar.",
  progress = "Ce l'hai, il rapporto?",
  reward = "Ben fatto! Per i tuoi servigi avrai una buona ricompensa. Un'altra missione, magari?",
}
T[81735] = {
  title = "Missione VI a Duskwood: Informazioni sui Draghi",
  desc = "Questi demoni ci tengono distratti qui, e intanto la corruzione sta trasformando The Emerald Dream in un incubo. Presto, attraversa il Portale di The Emerald Dream nel Twilight Grove e raggiungi l'Incursione dell'Incubo presso The Yorgen Farmstead. Lì troverai Dreamwarden Amalia: fatti dare un rapporto informativo e torna da me.",
  obj = "Raccogli informazioni da Dreamwarden Amalia nell'Incursione dell'Incubo di Duskwood, nella casa colonica a the Yorgen Farmstead, e torna da Field Captain Palandar.",
  progress = "Ce l'hai, il rapporto?",
  reward = "Ben fatto! Per i tuoi servigi avrai una buona ricompensa. Un'altra missione, magari?",
}
