T[86574] = {
  title = "Rifornimenti per Stonetalon",
  desc = "<Il corpo di questo sventurato è segnato dai molti colpi delle viverne Alafiera. Lì accanto giace lo zaino, sgualcito, abbandonato e vuoto; solo un piccolo biglietto, stretto nella mano del corriere, dice cosa è andato perduto: un carico per Innkeeper Faralia allo Stonetalon Peak.>$B$B<Probabilmente le viverne si sono portate via i fagotti di rifornimenti per foderarci i nidi.>",
  obj = "Raccogli 6 Rifornimenti di Stonetalon dalle Viverne Alafiera e consegnali a Innkeeper Faralia.",
  progress = "Spero che il carico arrivi presto...",
  reward = "Hai trovato il carico che mancava?$B$BOh, non sapevo che il corriere non ce l'avesse fatta. È... una cosa tragica...$B$BFarò buon uso di questi rifornimenti: la sua perdita non sarà stata vana.",
}
T[86576] = {
  title = "Ninnoli delle Bloodfury",
  desc = "Le arpie Bloodfury non si limitano a spargere la loro sporcizia per tutta la Charred Vale: raccolgono anche tutto quello che luccica. Mi dicono che fanno collezione di pietre del sole giallo oro di vario tipo, e le usano come ornamento. A me questi ninnoli non servono, ma Mor'rogal mi ha detto che in passato li ha usati.$B$BQuando combatti le arpie della Valle, cerca le Glittering Sunstones e porta quelle che trovi a Mor'rogal, sulle colline sopra di noi.",
  obj = "Porta 15 Glittering Sunstones a Mor'rogal.",
  progress = "Ho questioni importanti per la testa, $C. Fai in fretta.",
  reward = "Ah, mi hai portato le pietre del sole che raccolgono le arpie! Amano ammucchiare oggetti luccicanti, ma il vero valore di queste pietre non lo conoscono. Catturano la luce abbagliante del sole e ne riflettono la maestà: noi possiamo usarle per adornare santuari e case di piccole scintille di luce, in suo onore. E di notte anche la luna le illumina con la sua bellezza d'argento.$B$BQueste pietre ci ricordano il legame che ci unisce alle luci del cielo.",
}
T[86585] = {
  title = "Lo Stendardo dei Caduti",
  desc = "La montanara caduta ha con sé uno stendardo di Ironforge. Forse era in ricognizione, o stava guidando una carica disperata. In ogni caso, lo stendardo è stato gettato a terra e calpestato. Un trogg l'ha uccisa all'istante, probabilmente con una Spiked Club, colpendola alla testa così forte da farle volare via l'elmo.$B$BIl trogg che l'ha uccisa sarà ancora nei paraggi, e con ogni probabilità si ricorda dello stendardo. Se innalzi di nuovo il Banner of Ironforge, potresti attirarlo allo scoperto.",
  obj = "Innalza lo stendardo di Ironforge, fai uscire allo scoperto il trogg Headsplitter e uccidilo, poi fai rapporto a Captain Rugelfuss.",
  progress = "Quello stendardo ha visto molte battaglie!",
  reward = "Hai trovato il corpo di Ylva? Ah, poveretta. Diceva che avrebbe dimostrato ai trogg che Ironforge non sarebbe mai caduta per mano di gente come loro. Era andata a cercare alcuni montanari che non erano più tornati da un pattugliamento in territorio trogg. Ha sempre avuto uno spirito troppo intraprendente per essere cauta. Ora sappiamo cos'è successo.$B$BRiporto io lo stendardo e mi assicuro che venga ripulito ed esposto. Tu dovresti prendere la sua arma. Che ti sia utile contro i trogg.",
}
T[86613] = {
  title = "Excavation Tools",
  desc = "A quanto pare, gli attrezzi dello scavo sono per lo più intatti: i nani li hanno abbandonati quando sono fuggiti dai troggs. Se li riporti agli scavatori, li aiuterai di certo nel lavoro.",
  obj = "Riporta 6 Excavation Tools a Magmar Fellhew.",
  progress = "Ci resta solo da, ehm, sistemare il sito di scavo, e poi rimettiamo tutto in carreggiata!",
  reward = "I nostri attrezzi!$B$BQuando i troggs hanno invaso l'accampamento, abbiamo dovuto lasciarne lì quasi tutti. Ci daranno una gran mano quando avremo messo l'invasione sotto controllo e potremo rimetterci al lavoro!",
}
T[86614] = {
  title = "Argento delle Onde",
  desc = "<Fra le cianfrusaglie da pesca nei detriti ci sono alcuni ami arrugginiti, bobine di filo rotte e un fermaglio d'argento per capelli, un po' corroso ma finemente decorato, con il monogramma \"K.D.\">",
  obj = "Restituisci il Fermaglio per Capelli d'Argento con Monogramma al proprietario.",
  progress = "Oggi ho un sacco di faccende da sbrigare, potresti fare in fretta?",
  reward = "Il mio fermaglio! Credevo di averlo perso per sempre!$B$BCon un po' di lavoro tornerà a brillare come nuovo. Grazie per avermelo portato! Saprò ricompensarti come si deve.",
}
T[86667] = {
  title = "Neve Imprigionata",
  desc = "Il mio vecchio mentore, Norric, mi ha mandato un elementale minore con una strana richiesta. Gli serve un barattolo di neve per certi suoi riti sciamanici! Non so cosa ci voglia fare, ma quando si tratta di magia ho imparato da tempo a non mettere in dubbio i suoi metodi.$B$BSono impegnata a studiare gli elementali della zona, quindi non posso andare ad aiutarlo. Vai all'ingresso della galleria al South Gate Pass, dove c'è neve tutto l'anno. Raccoglila in questo barattolo di ceramica e portagliela prima che si sciolga. Lì dentro dovrebbe restare fredda.",
  obj = "Consegna un Jar of Snow a Norric Lochthane, a casa sua sulla costa nord-occidentale del Loch.",
  progress = "Eh? Che cosa vuoi?",
  reward = "Questo barattolo è per me?$B$BNeve! Ce l'ha fatta, Grenhild! Mi ha mandato la neve che le avevo chiesto!$B$BPeccato, però, speravo che venisse a trovarmi di persona.$B$BBeh, in ogni caso, grazie per il tuo impegno. Mi sarà di grande aiuto nel lavoro.",
}
T[86757] = {
  title = "Rallentare l'Avanzata degli Orchi",
  desc = "Gli orchi hanno conquistato la foresta orientale, e adesso i loro esploratori e i loro grunt si aggirano ovunque nei boschi! Muoversi per Ashenvale non è più sicuro per la nostra gente.$B$BDobbiamo ricacciare indietro gli orchi e mettere al sicuro la foresta. Avanzando con cautela e di nascosto ai margini del loro accampamento, siamo riusciti a far fuori qualche grunt e qualche esploratore.$B$BAffronta gli orchi e portami le spade seghettate e i coltelli ricurvi che usano. Farò in modo che le loro armi siano recuperate e riutilizzate: così non andrà sprecato niente.",
  obj = "Porta 6 Spade Orco Seghettate e 4 Pugnali Orco Ricurvi a Shandrina.",
  progress = "Se gli orchi continuano a spingersi sempre più a fondo nelle foreste, temo per la sorte delle nostre case.",
  reward = "Ottimo lavoro, $N.$B$BDeploro che la situazione ci costringa a ricorrere a questo genere di violenza, ma se nessuno ferma gli orchi invaderanno Astranaar e abbatteranno tutto il bosco. Almeno il metallo delle loro armi rozze possiamo riusarlo per costruire le nostre difese.",
}
T[86758] = {
  title = "Rigirare il Coltello nella Piaga",
  desc = "Ti ho mai raccontato di quando per poco un crocolisco non mi staccava la mano? Sono riuscito a piantargli il coltello nella mascella e me la sono filata di corsa. Credevo di averlo ancora qui da qualche parte, ma non lo trovo più.$B$BComunque, quel croc sarà ancora là fuori a cacciare lungo la riva del lago. Quella bestiaccia andrebbe tolta di mezzo, se non altro per la sicurezza degli altri cacciatori.$B$BHo cominciato a chiamarlo Daggerfang. Se lo vedi, fagli un bel saluto da parte mia! E per \"saluto\" intendo \"coltellata\".",
  obj = "Trova e sconfiggi il crocolisco Daggerfang e riporta il coltello di Marek.",
  progress = "Come va la caccia?",
  reward = "Ah! Ce l'hai fatta! Non pensavo che quel vecchio croc avrebbe mai avuto quel che si meritava, ma così va benone!$B$BOh, ehm... sai, mi son dovuto procurare un altro coltello, ma magari quello vecchio porterà un po' di fortuna a te. Perché non lo tieni tu?",
}
T[86776] = {
  title = "Ingredienti per la Forgia",
  desc = "Thelsamar è un gran bel posto per viverci, ma non abbiamo tutte le comodità di Ironforge. Il bronzo mi finisce sempre! Se voglio continuare a fare attrezzi, paioli e pentole, me ne serve dell'altro!$B$BVedo che hai un po' di pratica alla forgia. Pensi di potermi fondere dei bronze bars? Posso pagarti bene!",
  obj = "Porta 10 Bronze Bars a Morhan Coppertongue.",
  progress = "Le forge devono restare accese!",
}
T[86784] = {
  title = "Rami e Ossa",
  desc = "La mia socia Eleanor Shackleton va fiera dei suoi viaggi nelle terre selvagge, dove sopravvive al maltempo e ai mostri. Adesso è accampata qui vicino, sulle colline a ovest, e mi torna in mente un consiglio che mi ha dato una volta: \"Quando pensi di avere abbastanza legna da ardere, raccogline cinque volte tanto.\"$B$BSe hai un po' di tempo libero, potresti raccogliere un po' di legna in questo cesto e portarla al suo accampamento. Sono sicuro che saprà darti qualche suggerimento sulla vita di $Gun avventuriero:un'avventuriera; in viaggio.",
  obj = "Raccogli 6 Dry Branches e portali a Eleanor Shackleton.",
  progress = "$GBenvenuto:Benvenuta; accanto al mio fuoco, $Gviaggiatore:viaggiatrice;.",
  reward = "Altra legna da ardere? È sempre la benvenuta. Terrà al caldo queste vecchie ossa nelle notti fredde delle Radure.$B$BPer raccogliere la legna ho già una fascia, quindi quel cesto puoi anche tenerlo.",
}
T[87288] = {
  title = "Pelli Morbide di Fiera",
  desc = "Salve, $Gviaggiatore:viaggiatrice;! Spero che la visita al nostro villaggio ti stia piacendo. Mi piace Dolanaar perché è piccola e rustica, e qui sono tutti cordiali.$B$BSono una mercante del posto e porto qui ogni sorta di attrezzi e ninnoli che potrebbero tornarti utili in viaggio. Anzi, se ti interessa uno scambio, avrei bisogno di qualche pelle di nightsaber. Queste creature sono maestose e bellissime, ma quelle della zona sono piuttosto aggressive, quindi non sentirti troppo in colpa se devi difenderti.",
  obj = "Porta 6 Soft Nightsaber Pelts ad Aldria.",
  progress = "Che bello rivederti! Sei qui per uno scambio?",
  reward = "Oh, sono splendide. È un peccato dover ricorrere alla violenza con animali tanto maestosi, ma è importante che le strade restino sicure, e con queste pelli verranno fuori bellissime coperte e scialli.$B$BEcco, ti do qualcosa per ricordarle. È morbido e robusto al tempo stesso.",
}
T[87318] = {
  title = "I Cari dei Profughi",
  desc = "Il Thandol Span è diventato pericoloso da quando i Dark Irons hanno fatto saltare il ponte, ma non mi aspettavo di incappare in alcuni di loro proprio lì!$B$BIo sono riuscito a scappare, ma la mia compagna, Essene, l'ho persa di vista. L'ho cercata dappertutto, senza trovare nessuna traccia di lei. Sarà stata catturata dai Dark Irons? È caduta nel fiume là sotto? È riuscita a tornare dall'altra parte? Non lo so! Non so nemmeno se è viva!$B$BTi prego, se trovi traccia di lei, fammelo sapere!",
  obj = "Cerca Essene, la compagna di Corma.",
  reward = "Ti manda Corma? Che notizia fantastica!$B$BQuando i Dark Irons ci hanno teso un'imboscata ci siamo $Gseparati:separate;; io ho battuto la testa e non capivo più dove stessi andando. Sono $Gfinito:finita; qui, e in questi ultimi giorni ho tirato avanti con le provviste che avevo nella borsa. Ma ora che sei $Griuscito:riuscita; a superare i Dark Irons, forse posso scappare.$B$BDevo solo raccogliere la mia roba e riprendermi un attimo, poi troverò il modo di fuggire!$B$BNon ha mai rinunciato a me. Che cuore meraviglioso.",
}
T[87491] = {
  title = "Scintilla di Libertà",
  desc = "Sss! Quegli schifosi dei Dark Irons mi hanno evocato e mi tengono in gabbia accanto al loro misero focolare!$B$BIl fuoco deve correre selvaggio, correre libero! Liberami! Devo scappare! Devo BRUCIARE!$B$BNessun Dark Iron è al sicuro! Riducili in cenere! Brucia la loro polvere nera! Brucia la loro fortezza, le loro micce, la loro follia!$B$BFammi uscire e li BRUCERÒ TUTTI!",
  obj = "Scorta il captive fire elemental fuori da Dun Modr, verso la libertà.",
  reward = "Che spettacolo pirotecnico! Credo di non aver mai visto niente del genere!$B$BMeno male che l'elementale del fuoco, ehm, si è spento, per così dire. Poteva finire male, se se la prendeva con noi invece che con quei Dark Irons!",
}
T[87760] = {
  title = "Sacro Tuffatore",
  desc = "Da Darnassus è arrivata la risposta, $N!$B$BGrazie ai campioni degli animali abbiamo scoperto che i naga hanno soggiogato queste creature marine e le usano, contro la loro volontà, come cavalcature e bestie da soma. Quelle troppo ostinate, troppo vecchie o ferite gravemente le hanno scacciate per divertimento. Mostruoso!$B$BAbbiamo il sacro dovere di mettere fine a tutto questo!$B$BI naga hanno delle forze nelle Ruins of Mathystra, e devono essere loro a catturare i trebbiatori al largo della costa. Trova la loro domatrice di bestie, uccidila e portami i suoi strumenti di dominio!",
  obj = "Trova una Stormscale Beastmistress, uccidila e riporta la sua Rod of Deep Dominion.",
  progress = "Finalmente risolveremo questo mistero, e gli animali troveranno pace!",
  reward = "È stato un lungo viaggio, Orangequake, ma ne è valsa la pena.$B$BFinalmente hai strappato la verga con cui i naga piegano le creature marine al loro servizio. Mi assicurerò che venga distrutta, e i trebbiatori e le tartarughe marine potranno vivere in pace.$B$BGrazie ancora. Alla fine la tua tenacia è stata ricompensata, e io, personalmente, te ne sono grata.",
}
T[88756] = {
  title = "Riporta il Botto",
  desc = "I Dark Irons c'hanno qualche accampamento qui a est, sul Direforge Hill, e si son portati nelle tende un bel po' d'esplosivi rubati dal nostro cantiere.$B$BChe razza di guai possono combinare i Dark Irons con un barile di polvere, non c'è bisogno che te lo dica!$B$BLo so che i Dark Irons sono pericolosi, ma quei barili dobbiamo riprenderceli. Li riconosci dai segni rossi che c'hanno sopra. Mica possiamo lasciarli ai Dark Irons!",
  obj = "Recupera 3 Stolen Explosives dagli accampamenti di Dark Iron Dwarf.",
  progress = "'Sta guerra coi Dark Irons non finisce mai!",
  reward = "Ah, mi son tolto un bel peso. Almeno i Dark Irons non potranno far rotolare un carretto-bomba contro i nostri carri... né tirarceli addosso con un trabucco... né farli rotolare giù dalla collina su di noi... né darli in pasto alle melme e poi liberarle vicino al campo nostro e dargli fuoco.$B$BOra non ci resta che tenere asciutta la polvere!$B$BGrazie!",
}
T[88757] = {
  title = "Gli averi del profugo",
  desc = "Scappando da quei Dark Irons ho finito per perdere un sacco di roba!$B$BA quanto pare mi mancano... la borraccia di cuoio verde, il libro degli incantesimi, la collana e... beh, mi servono!$B$BSe riesci a ritrovarli mentre rifaccio i bagagli e riprendo fiato, mi daresti una grossa mano.",
  obj = "Riporta l'Essene's Necklace, l'Essene's Spellbook e l'Essene's Waterskin.",
  progress = "Mi sto solo riallacciando gli stivali! Sei $Griuscito:riuscita; a superare quei Dark Irons e a ritrovare la mia roba?",
  reward = "Hai il mio libro! E la borraccia! E la collana! Oh, oggi la fortuna sta dalla mia parte... grazie mille.$B$BMeglio controllare che sia tutto intatto!",
}
T[88758] = {
  title = "Sentimenti dei Dispersi",
  desc = "Mi manca solo da finire i bagagli, poi potrò andarmene da qui!$B$BUn ultimo favore, se puoi: ecco — porta questo biglietto a Corma, così saprà che sono $Gvivo:viva; e che sono in cammino!",
  obj = "Riporta il biglietto di Essene a Corma Villard.",
  progress = "Hai trovato una traccia di lei?",
  reward = "È viva? È viva!$B$BFammi vedere questo biglietto... \"Cara Corma...\" mmm... oh, giorno benedetto! Sia lodata la Luce!$B$BNon potrò mai ringraziarti abbastanza per averci riuniti. Non vedo l'ora di riaverla qui!$B$BHai reso a entrambi un servizio meraviglioso.",
}
T[90902] = {
  title = "Riscoprire la Luce",
  desc = "Sono fiero di accogliere fra le nostre file $Gun altro:un'altra; $C appena $Grisorto:risorta;. Ora che torni in sintonia con la luce, potresti accorgerti che certe abilità che un tempo ti venivano naturali adesso ti provocano un forte dolore, soprattutto quelle che incanalano la luce per curare te $Gstesso:stessa; o gli altri. $B$BL'unico modo per superarlo è — purtroppo — affrontarlo. Come con qualsiasi altro muscolo atrofizzato, devi sopportare il dolore e allenare la carne finché non torna a funzionare del tutto.",
  obj = "Cura 5 Injured Deathguard con l'abilità Holy Light.",
  progress = "Col tempo tornerai a padroneggiare la luce.",
  reward = "Il dolore non è una novità per chi ha conosciuto la morte, ed è per questo che i Forsaken lo sopportano particolarmente bene. Ha anche un potere purificatore, e dovresti accoglierlo come un segno d'onore e come la prova che, nonostante la tua nuova condizione, sei ancora $Gun servitore:una servitrice; della luce. $B$BStammi bene e cammina di nuovo nella luce, $C.",
}
T[91208] = {
  title = "Farsene una ragione",
  desc = "Non tutti i nostri compagni Paladini che risorgono si abituano in fretta alla nostra nuova realtà. Alcuni faticano ad accettare di essere diventati, in un certo senso, proprio ciò che hanno combattuto per tutta la vita.$B$BSpesso a queste persone basta un gesto gentile e qualcuno disposto ad ascoltarle. Purtroppo, molti altri passano subito alla violenza. Trova la paladina spaventata fuggita sulle colline verso ovest da questa cappella. Tendile una mano amica. Riportala alla luce, se puoi.",
  obj = "Trova la Frightened Paladin a Deathknell.",
  progress = "Accettare questa nuova vita non è facile per nessuno di noi. Alcuni proprio non riescono a sopportarlo.",
  reward = "È una tragedia, molti dei nostri fratelli e le sorelle, dopo il risveglio, cedono alla follia. Per quanto preziosa l'anima di ogni Forsaken, a volte non possiamo fare di meglio che concedere una fine rapida a chi non riesce ad abituarsi.$B$BPregherò la luce per lei. Grazie per aver fatto ciò che andava fatto, $N.",
}
T[91209] = {
  title = "Continua l'Addestramento",
  desc = "Lordaeron non sarà più quella di un tempo, ma la nostra casa va ancora protetta da minacce di ogni sorta, ed è ora che tu esca ad affrontare il mondo. La tua prossima tappa dovrebbe essere la città di Brill, al centro di Tirisfal Glades. Va' da Shari Stilwell: sarà lei a proseguire il tuo addestramento.$B$BUn ultimo consiglio prima che tu parta — sei $Gun:una; $C, e nelle terre dei Forsaken dovrai stare più $Gattento:attenta; del solito. Molti di coloro che servono la Dama Oscura diffidano di noi e del nostro legame con la luce.",
  obj = "Esci da Deathknell seguendo la strada verso est fino alla città di Brill. Fai rapporto a Shari Stilwell per continuare l'addestramento.",
  reward = "$GBenvenuto:Benvenuta; tra noi, $C. È sempre incoraggiante vedere altri dei nostri girare per queste terre. Qui a Brill in tanti hanno bisogno dell'aiuto di avventurieri come te. Aiutali e cerca la forza nella luce. Torna da me ogni volta che avrai bisogno di addestrarti.$B$BQuando avrai dato prova del tuo valore a me e alla gente di Brill, ti indicherò la strada per la prossima meta del tuo viaggio.$B$BVa' con la luce, $C.",
}
T[91282] = {
  title = "Una Seconda Casa",
  desc = "È incoraggiante vedere i miei fratelli e le mie sorelle appena risorti prosperare come hai fatto tu. Tuttavia, solo nella comunità e in una fede condivisa possiamo esprimere fino in fondo il nostro potenziale, ed è per questo che stiamo fondando un nuovo ordine di paladini proprio qui a Tirisfal. $B$BSe vuoi saperne di più, passa dal nostro monastero ai margini dei Whispering Woods. Si chiama Bandarion Keep. Sorge sulle scogliere poco a nord-ovest della Solliden Farmstead, e non puoi non notarlo.",
  obj = "Trova la fortezza di Bandarion Keep e lì fai rapporto a Breton Samuels.",
  reward = "Un'altra recluta? $GBenvenuto:Benvenuta; a Bandarion Keep, $Gfratello:sorella;.",
}
T[91285] = {
  title = "Murlocs alle Porte",
  desc = "Di solito ai nuovi arrivati riserviamo un'accoglienza un po' più ospitale, ma in questo momento abbiamo un problemino con i murlocs.$B$BUna tribù di murlocs usava la rocca per riprodursi. Da quando ci siamo trasferiti qui e li abbiamo cacciati non fanno che darci problemi, e ora la situazione comincia a sfuggirci di mano. Hai l'aria di chi ha già combattuto: potresti aiutarci a respingere qualcuna di queste pesti? Li troverai appostati sulle scogliere lungo la strada a est e negli accampamenti intorno al lago a ovest.",
  obj = "Uccidi 8 Vile Fin Attackers e 8 Vile Fin Seers e torna da Breton Samuels quando hai finito.",
  progress = "Non si arrendono mai, questi murlocs!",
  reward = "Ti ringraziamo dell'aiuto. Gli attacchi non finiranno del tutto, ne sono sicuro, ma spero che almeno rallentino un po'. Ricostruire questo posto è già abbastanza difficile di suo, senza un murloc che cerca di piantarti una lancia nella schiena.",
}
T[91294] = {
  title = "Un Giro per la Rocca",
  desc = "Ora che abbiamo sotto controllo la minaccia immediata dei murlocs, ti consiglio di fare un giro della roccaforte. Non è ancora granché, ma è casa nostra.$B$BQuando avrai finito di esplorare, cerca Danitha Morr: è lei il nostro capo, e può aiutarti a sistemarti.$B$BSono davvero contento di averti conosciuto, $N. Che la luce ti guidi.",
  obj = "Parla con gli abitanti di Bandarion Keep.",
  progress = "$GBenvenuto:Benvenuta; a Bandarion Keep, $C. Una faccia nuova fa sempre piacere.",
  reward = "Ti ha $Gmandato:mandata; quassù Breton, eh? Ottimo.$B$BMi chiamo Danitha Morr e, se in questa rocca c'è qualcuno che somiglia a un comandante, quella sono io. Se sei $Gvenuto:venuta; a cercare la fratellanza di chi resta ancora fedele alla luce, sei nel posto giusto.$B$BPrima di poterci stabilire del tutto qui c'è parecchio lavoro da fare, e ti saremmo molto grati se volessi darci una mano.",
}
T[91316] = {
  title = "Lavori di Riparazione",
  desc = "Così lontano da Undercity, la logistica è complicata e abbiamo una grave carenza dei materiali da costruzione che servono a restaurare la fortezza. Vorrei che mi dessi una mano.$B$BIl villaggio in rovina di Shadowvale si trova nella Whispering Forest, appena a sud-ovest di qui. In uno degli edifici c'è una vecchia cantina per le provviste, dove si conservava un po' di tutto. Probabilmente laggiù c'è ancora del materiale utilizzabile. Recupera quello che puoi e torna da noi.",
  obj = "Raccogli 12 pezzi di Sturdy Lumber a Shadowvale, in Tirisfal Glades.",
  progress = "Si dice che la posizione sia tutto. Arroccata sulle scogliere, la fortezza sembrerà pure imponente, ma restare riforniti così lontano dalla vera civiltà si sta rivelando una bella impresa. Una svista spiacevole da parte nostra.",
  reward = "Sono contento che la tua spedizione a Shadowvale abbia dato i suoi frutti. Più tardi manderò Breton e qualche altra nuova recluta a sgomberare il resto della cantina e a recuperare tutto ciò che è rimasto laggiù al buio.",
}
T[91317] = {
  title = "Gli Offuscati",
  desc = "Non tutti i paladini risorti si sono adattati bene alla nostra nuova esistenza, come forse avrai già visto con i tuoi occhi. Alcuni si sono portati dietro i pregiudizi della vita passata, e continuano a usare violenza contro gli altri Forsaken.$B$BGià ora il nostro popolo diffida di noi, perché ricorda bene le persecuzioni che ha subito dai vivi in nome della luce, e questi attacchi non aiutano. Alcuni di questi paladini offuscati si sono stabiliti a Shadowvale, a sud-ovest. Eliminali e portami la testa del loro capo.",
  obj = "Uccidi 8 Tarnished Drudges e 6 Tarnished Zealots, e raccogli la testa di Commander Rudolph Gelhardt alle Tirisfal Glades.",
  progress = "Gli Offuscati minacciano quel poco di benevolenza che gli altri Forsaken hanno verso di noi. Per quanto mi addolori incrociare le spade con quelli che erano nostri fratelli e sorelle, vanno fermati, se vogliamo che il nostro giovane ordine sopravviva.",
  reward = "Ottimo lavoro, $N. Ogni volta che uno di questi Offuscati abbatte un Forsaken, per i nostri detrattori diventa ancora più facile alimentare la sfiducia verso noi paladini. Eliminandoli aiuteremo la nostra causa e consolideremo il nostro posto qui a Tirisfal.$B$BSospetto che ci vorrà molto tempo prima che i Forsaken e l'orda ci accettino del tutto. Potrebbero passare anni... o forse perfino decenni, ma la cosa migliore che possiamo fare è continuare a sforzarci di dimostrare quanto valiamo.",
}
T[91723] = {
  title = "Strumenti Delicati",
  desc = "Maledizione! Ogni volta che provo a calibrare questi delicati strumenti arcani, arriva un'ondata di energia e me li manda di nuovo fuori taratura.$BSembra che le ondate vengano da nord, dove quei primitivi Kobolds si esercitano con la loro rozza magia. Potresti levarne di mezzo qualcuno, così vado avanti con il mio lavoro?",
  obj = "Uccidi 8 Kobold Geomancers nella Jasperlode Mine, poi torna da Hamish Bergwort alla Tower of Azora.",
  progress = "Fammi sapere quando hai finito, così riprovo a calibrare gli strumenti.",
  reward = "Ben fatto, $Gamico mio:amica mia;. Adesso fammi riprovare a calibrarli...",
}
T[91724] = {
  title = "Strumenti Delicati",
  desc = "Ci siamo quasi, e... Per la Distorsione Fatua! C'è qualcosa che continua a disturbare gli strumenti.$B$BÈ davvero frustrante, $N. Ho sentito dire che i banditi della zona fanno pratica con gli incantesimi vicino allo Stone Cairn Lake. Magari, se li fermi, questi disturbi finiranno una buona volta e potrò combinare qualcosa?",
  obj = "Uccidi 8 Defias Rogue Wizards allo Stone Cairn Lake, poi torna da Hamish Bergwort alla Tower of Azora.",
  progress = "Fammi sapere quando hai finito, così riprovo a calibrare gli strumenti.",
  reward = "Pare che adesso funzioni tutto come si deve. Grazie, $N.",
}
T[91725] = {
  title = "Stolen Enchanting Supplies",
  desc = "Master Theocritus mi ha mandata all'emporio a prendere dei materiali da incantamento, ma mentre tornavo un branco di gnolls mi ha teso un'imboscata!$B$BHo lasciato cadere il pacco e sono scappata, ma se torno a mani vuote, per punizione mi toccherà pulire per settimane dopo gli esperimenti di metamorfosi! Pensi di riuscire a ritrovarmi i materiali?",
  obj = "Raccogli 5 Stolen Enchanting Supplies negli accampamenti gnoll intorno allo Stone Cairn Lake, poi torna da Blixie Fitzwink vicino alla Tower of Azora.",
  progress = "Hai trovato i materiali?",
  reward = "Oh, che sollievo! Pare che ci sia tutto. Grazie!",
}
T[91732] = {
  title = "Buon Acciaio",
  desc = "Dopo la guerra il buon acciaio scarseggia, e i nostri attrezzi ne hanno risentito. I minatori di Jasperlode usavano picconi di ottima fattura, e immagino che ce ne sia ancora qualcuno laggiù, nelle profondità della miniera. Potresti recuperarmene alcuni, così vedo se riesco a riutilizzarne l'acciaio?",
  obj = "Raccogli 4 Mining Tools nella Jasperlode Mine, poi torna da Hagar Lowe a Eastvale Logging Camp.",
  progress = "Sei già $Gstato:stata; alla miniera?",
  reward = "Oh, che belli. Vedi come brillano? Davvero, non li fanno più come una volta.",
}
T[91733] = {
  title = "Giù per il Fiume",
  desc = "Stavo riportando un carico di provviste dalla stazione commerciale, ma il carro si è ribaltato e la merce è finita nel fiume! Prima che riuscissi a riprenderla, la corrente l'aveva già trascinata a valle.$B$BCon tutti quei murlocs e quei lupi laggiù, da solo non ho nessuna speranza di recuperare le provviste. Sembri $Gun tipo tosto:una tipa tosta;. Pensi di riuscire a ritrovarmele?",
  obj = "Raccogli la Waterlogged Axe, la Waterlogged Saw e la Waterlogged Toolbox trascinati dalla corrente da Eastvale Logging Camp, poi torna da Ormin Pelford.",
  progress = "Hai trovato le provviste?",
  reward = "Sei un po' $Gbagnato:bagnata;, $N. Mi dispiace. Ma grazie per averle recuperate.",
}
T[91736] = {
  title = "Applejack Still",
  progress = "Mentre esamini il congegno, un forte odore di mele ti brucia il naso.",
  reward = "La macchina versa un liquido trasparente in una bottiglia...",
}
T[91738] = {
  title = "Una Delizia alle Mele",
  progress = "Al sergente si illuminano gli occhi quando nota la tua bottiglia di Thunder Applejack...",
  reward = "Vedo bene? Erano mesi che non mi capitava una goccia di Thunder Applejack!$BDovrebbe ridare il sorriso alle truppe. Ti ringrazio, $C!",
}
T[91740] = {
  title = "Croaky's Head",
  desc = "Di sicuro questo murloc terrorizza da un bel po' le strade della zona. Pensi che le guardie della ronda qui vicino vorranno sapere che è morto.",
  obj = "Consegna la Croaky's Head a Merell Ross alla Ridgepoint Tower.",
  progress = "Sì?",
  reward = "Per colpa dei murlocs, la settimana scorsa abbiamo perso due membri della ronda, $C. Adesso che il loro capo è morto, speriamo di poter cominciare a cacciarli da Elwynn.",
}
T[91741] = {
  title = "Nibbled-On Book",
  desc = "<Uno dei coboldi ha lasciato cadere questo libro. Sembra che abbia provato a mangiarlo.$B$BBrother Paxton cura una piccola biblioteca all'interno dell'abbazia. Viene di sicuro da lì.>",
  obj = "Riporta il libro a Brother Paxton.",
  progress = "Cos'hai lì? Sembra uno dei miei libri.",
  reward = "Ehi! Come mai ce l'hai tu? Dovrebbe stare sullo scaffale! Povero me, i coboldi mi hanno rubato di nuovo i libri. Vorranno mangiarseli!$B$BGrazie per avermelo riportato, ma come faccio a recuperare tutti gli altri volumi che mi mancano?",
}
T[91743] = {
  title = "Roditori Mascalzoni",
  desc = "Quegli orribili coboldi mi stanno mangiando i libri! Devi riprendere i libri prima che divorino tutta la mia biblioteca.",
  obj = "Recupera 8 Stolen Books dai coboldi di Northshire Valley e riportali a Brother Paxton.",
  progress = "Hai già messo in salvo i miei libri, $N?!",
  reward = "Grazie infinite! Ecco! Prendi uno di questi manuali pratici. A me non servono.$B$BMa mancano ancora tantissimi volumi. Pare che i coboldi non li mangino. E allora perché li vogliono?",
}
T[91745] = {
  title = "Consulenza Mineraria",
  desc = "Va' a parlare con la nuova apprendista minatrice, Kelsey Fargo. Lavora proprio fuori dalla miniera e avrà visto cosa combinano i coboldi. Già che ci sei, magari può insegnarti un paio di cose sul mestiere.",
  obj = "Parla con Kelsey Fargo fuori da Echo Ridge Mine in Northshire Valley.",
  reward = "Coboldi con dei libri? Già, ne ho visti un po' che correvano avanti e indietro con i libri in mano e si urlavano contro. Li staranno rubando dalla biblioteca dell'abbazia.",
}
T[91746] = {
  title = "Elmpaw's Head",
  desc = "Il trofeo è un ricordo notevole della tua vittoria su Elmpaw, e forse a qualche cacciatore o scuoiatore del posto interesserebbe sentirne la storia.",
  obj = "Consegna l'Elmpaw's Head a Helene Peltskinner vicino a Goldshire.",
  progress = "Sì?",
  reward = "Allora hai abbattuto Elmpaw? Davvero notevole, $N!$B$BTi do qualcosa in cambio del trofeo — conosco alcuni collezionisti che pagheranno parecchio per metterlo sulla mensola del camino, quando l'avrò preparato.",
}
T[91751] = {
  title = "Rough Wolf Pelts",
  desc = "Cerchi un'occasione per fare un po' di pratica con la scuoiatura? Di solito a cacciare i lupi mi aiuta mio marito, ma adesso ha da fare su, dalle parti dell'abbazia. Una mano a raccogliere altre pellicce mi farebbe comodo, così riesco a completare gli ordini su cui sto lavorando.",
  obj = "Scuoia i lupi nei dintorni dell'Elwynn Forest per ottenere 7 Rough Wolf Pelts, poi consegnale a Helene Peltskinner vicino a Goldshire.",
  progress = "Allora, come te la sei cavata con le pellicce di lupo?",
  reward = "Ottimo lavoro con queste pellicce, $C. Per la caccia hai un talento vero.",
}
T[91752] = {
  title = "Il Quadro Generale",
  desc = "Ogni tanto passa di qui un coboldo che urla \"Figure per Narf!\" Non so chi sia Narf. Forse uno dei capi coboldi in fondo alla miniera? Scommetto che ormai ha un sacco pieno di libri.$B$BVa' a recuperarli e portali al nostro tutore della legge, Marshal McBride. Faresti bene a trovare un amico che ti aiuti. Quelli dentro la miniera sono molto più cattivi.",
  obj = "Recupera un Sack of \"Picture\" Books da Shinyfinder Narf. Porta il sacco a Marshal McBride, appena dentro Northshire's Abbey.",
  progress = "Hai già recuperato quei libri rubati?",
  reward = "Grazie per aver riportato questi libri rubati, $N. Li restituirò subito a Brother Paxton.$B$BStai diventando $Gun vero eroe:una vera eroina; da queste parti. Ottimo lavoro!",
}
T[91753] = {
  title = "Una Lezione Incantevole",
  desc = "Per l'arte dell'incantatore il rigore accademico è naturalmente essenziale, ma una base pratica può dare i suoi frutti. Prendi, per esempio, l'umile Kobold: non ha alcuna istruzione formale, eppure mostra una sorta di attitudine innata per i trucchetti e gli incantamenti semplici.$B$BProcurati qualcuna delle sue effigi di cera e scomponi gli incantamenti che racchiudono. Potrebbe rivelarsi illuminante.",
  obj = "Kitta Firewind nella Tower of Azora vuole che tu raccolga 3 Luminous Residue.$B$BIl Luminous Residue si ottiene disincantando le Crude Wax Effigies lasciate dai Kobold Geomancers.",
  progress = "Cosa ti hanno rivelato gli studi?",
  reward = "Teoria e pratica sono le due facce della stessa medaglia, $N. Non dimenticarlo.",
}
T[91758] = {
  title = "Segui Quel Coboldo!",
  desc = "Con quei coboldi non hai ancora finito. Kelsey ci ha appena fatto sapere che un coboldo è uscito dalla miniera con un grosso sacco di libri. Ho bisogno che tu lo rintracci, così potremo recuperare i volumi per Brother Paxton.$B$BVa' a parlare con Tordrin Sternblade. È il nuovo istruttore dei Cacciatori, appena arrivato da Ironforge. Lo trovi dietro l'abbazia, vicino alla stalla. Può aiutarti a seguire le tracce del ladro.",
  obj = "Parla con Tordrin Sternblade vicino alla stalla dietro Northshire's Abbey.",
  reward = "Posso aiutarti a scovare 'sta canaglia. Lascia che ti prepari qualcosa al volo.",
}
T[91772] = {
  title = "Shhh! Stiamo Cacciando Coboldi",
  desc = "Bene. Prendi il kobold tracking kit. Ti servirà per seguire il coboldo che preoccupa Marshal McBride.$B$BSegui le tracce e porta quel che trovi a Marshal Dughan a Goldshire.$B$BHo la sensazione che 'ste canaglie stiano tramando qualcosa fuori da Northshire. Perciò ti ci vorrà l'aiuto di Dughan.",
  obj = "Segui le tracce del coboldo, poi porta il Kobold Tracking Kit a Marshal Dughan a Goldshire e riferiscigli cosa hai scoperto.",
  progress = "Hai capito dove stanno andando i Kobolds?",
  reward = "Cos'è questo, $N? Sei sulle tracce dei coboldi?$B$BBeh, è ovvio che sono diretti alla miniera di Fargodeep! Quel posto ne è infestato.$B$BBel lavoro, direi. Mi servirà qualcuno che si occupi del problema.",
}
T[91775] = {
  title = "Restituzione dei Libri",
  desc = "Mentre indaghi nella Fargodeep Mine, vedi se trovi qualche libro di Brother Paxton da riportargli. Paxton è preoccupatissimo soprattutto per un volume intitolato \"Divertirsi con gli Elementali\". Pensa che perfino un coboldo potrebbe usarlo per evocare un servitore elementale. Ti avverto, le profondità della miniera sono piuttosto pericolose. Faresti bene a portarti degli amici.$B$BPrendi questa borsa per libri, così li proteggerai quando li troverai!",
  obj = "Trova 6 Lost Books e \"Divertirsi con gli Elementali\" e riportali a Marshal Dughan.",
  progress = "Hai già trovato tutti i libri?",
  reward = "Lodo la tua diligenza, $N. Brother Paxton mi ha mandato un elenco di libri, e hai ritrovato quasi tutti quelli scomparsi. Gli altri saranno stati portati alla Jasperlode Mine.$B$BLa borsa per libri puoi tenerla!",
}
T[91777] = {
  title = "Libri Rari",
  desc = "Dall'elenco di Brother Paxton mancano solo due libri: \"Geomancy for Curious Young Wizards\" e \"Arcane Explainer: Magical Stuff in Simple Words\".$B$BI coboldi li avranno portati alla Jasperlode Mine. Ti prego, rintraccia quei due volumi e riportali a Brother Paxton.$B$BTemo però che sarà piuttosto pericoloso. Se il coboldo \"apprendista\" stava evocando un elementale, chissà cosa può fare il maestro. Se fossi in te, mi porterei qualche amico.",
  obj = "Recupera \"Geomancy for Curious Young Wizards\" e \"Arcane Explainer: Magical Stuff in Simple Words\" e riportali a Brother Paxton, dentro Northshire's Abbey.",
  progress = "Hai già trovato tutti i miei libri scomparsi?",
  reward = "Oh, $N! Grazie infinite per aver salvato la mia biblioteca. Mi hai reso un servizio straordinario. Prendi pure una di queste ottime armi. Erano destinate alla milizia, ma tu puoi farne un uso migliore.",
}
T[91858] = {
  title = "Incidente Diplomatico",
  desc = "A Silverpine è successa una cosa davvero sfortunata, e ci ha dato un'occasione unica per dimostrare all'orda quanto valiamo.$B$BMentre andavano a Tarren Mill, due dignitari dell'Earthen Ring sono scomparsi nella Silverpine Forest. Non sappiamo molto altro, ma si dice che la faccenda stia diventando un vero incidente diplomatico. Se riusciamo a ritrovare i dispersi, la cosa potrebbe aiutarci a ottenere la legittimità di cui abbiamo tanto bisogno.$B$BA The Sepulcher c'è un nostro uomo, Trevan Rol. Va' da lui e parlagli.",
  obj = "Recati a The Sepulcher nella Silverpine Forest e parla con Trevan Rol dei viaggiatori scomparsi dell'Earthen Ring.",
  reward = "Ti ha mandato Danitha? Be', allora so già cosa ti porta qui. Ti sei appena $Gcacciato:cacciata; in un dannato bel pasticcio, $C.",
}
T[91859] = {
  title = "Una Strana Coppia",
  desc = "Vado dritto al punto: questi \"dignitari\" non sono diplomatici qualunque. Uno era un Tauren, e fin qui niente di strano per l'Earthen Ring; ma l'altro — e stenterai a crederci — era un elfo. Un *alto* elfo. Erano avvolti nei mantelli, ma i quel'dorei li ho già visti, e ci scommetterei il mignolo buono: era proprio uno di loro.$B$BPerché mai un elfo accompagnava un Tauren attraverso il territorio dell'orda? Be', ne so quanto te. Di più non so dirti, per cui ti consiglierei di parlare con Deathguard Baldren, vicino all'ingresso del paese.",
  obj = "Parla con Deathguard Baldren dei misteriosi viaggiatori dell'Earthen Ring passati di recente per The Sepulcher.",
  reward = "Per voi paladini non avrò simpatia, ma devo ammetterlo: il tuo tempismo è impeccabile. Meglio essere fortunati che bravi, immagino?",
}
T[91860] = {
  title = "Un Destino Funesto",
  desc = "Ieri notte, durante la pattuglia, ho visto un gruppo di gnolls che scaricava un corpo molto grosso su una pira, sulla riva della Fenris Isle. Non ho visto né l'elfo né cadaveri più piccoli, ma direi che per loro non promette niente di buono.$B$BSe sei $Gcoraggioso:coraggiosa; o $Gstupido:stupida;, puoi lanciarti all'assalto della Fenris Isle e saperne di più; ma se vuoi il mio parere, è tanta fatica per trovare un elfo spocchioso che probabilmente è morto da un pezzo.$B$BSo che voi paladini adorate fare giuramenti e abbracciare cause perse, ma questa non ne vale la pena. Fidati.",
  obj = "Esplora la Fenris Isle a est e scopri la sorte della comitiva dell'Earthen Ring.",
  reward = "<Il cadavere davanti a te è senza dubbio quello di un Tauren, e si vede che l'hanno rosicchiato parecchio prima di gettarlo sulla pira. Dell'elfa che ti hanno descritto, però, non vedi traccia. Forse è ancora viva da qualche parte, più all'interno della fortezza qui vicino?$B$BSarà pericoloso, ma per saperlo con certezza c'è un solo modo.>",
}
T[91861] = {
  title = "Dentro il Fenris Keep",
  desc = "<Un solo corpo fa ben sperare. Forse l'High Elf di cui hanno parlato Trevan e Hadrec è ancora vivo, da qualche parte più all'interno della fortezza qui vicino?>",
  obj = "Esplora il Fenris Keep a nord e cerca di trovare il membro scomparso della comitiva dell'Earthen Ring.",
  reward = "Sei $Guno:una; dei Forsaken, vero? Mi aiuti a liberarmi?$B$BTemo che mi resti poco tempo. Ti prego, sbrigati!",
}
T[91862] = {
  title = "Lumina Windsinger",
  desc = "Quel'dorei? No, non sono una \"quel'dorei\". Sono Lumina Windsinger e sono shen'dorei, una degli Skyborne Modellavento.$B$BSono arrivata in queste terre come ospite dell'Earthen Ring. Banon, il mio compagno, e io stavamo attraversando Silverpine diretti agli Arathi Highlands, dove volevamo studiare le convergenze elementali. Come vedi, non ce l'abbiamo fatta.$B$BMa adesso non c'è tempo. Uccidi gli gnolls qui intorno, prendi la chiave di questa gabbia e liberami. Il resto te lo racconterò quando saremo al sicuro, lontano da qui.",
  obj = "Recupera la Fenris Isle Key dai Rot Hide Gnolls e usala per liberare Lumina Windsinger.",
  progress = "Gli Gnolls sono al secondo posto fra le creature peggiori che abbia incontrato finora su Azeroth.",
  reward = "Grazie, $C. Purtroppo non siamo ancora fuori pericolo.",
}
T[91899] = {
  title = "Una Sealed Crate",
  progress = "Un'altra consegna! Fantastico. Mettila lì vicino alla pila e parliamo del tuo compenso.",
  reward = "Grazie per l'impegno, $N. Di recente c'è stata un'ondata di assalti di banditi e ladri lungo le rotte commerciali. Se trovi altre casse abbandonate in giro, portale qui e al resto penseremo noi.$B$BEcco la tua paga.",
}
T[91900] = {
  title = "Una Sealed Crate",
  progress = "Un'altra consegna! Fantastico. Mettila lì, accanto alle altre, così parliamo del compenso.",
  reward = "Grazie per l'impegno, $N. Ultimamente sono aumentati i banditi e i ladri che assaltano le rotte commerciali. Se trovi altre casse abbandonate in giro, portale qui e al resto penseremo noi.$B$BEcco quanto ti spetta.",
}
T[91901] = {
  title = "Una Sealed Crate",
  progress = "Un'altra consegna! Fantastico. Posala lì, accanto alla pila, e potremo parlare del tuo compenso.",
  reward = "Grazie per il duro lavoro, $N. Ultimamente lungo le rotte commerciali ci sono sempre più banditi e ladri che tendono agguati. Se in giro trovi altre casse abbandonate, portale qui: al resto ci penseremo noi.$B$BEcco la tua paga.",
}
