  reward = "Grazie per il duro lavoro, $N. Ultimamente lungo le rotte commerciali ci sono sempre più banditi e ladri che tendono agguati. Se in giro trovi altre casse abbandonate, portale qui: al resto ci penseremo noi.$B$BEcco la tua paga.",
}
T[91920] = {
  title = "Occhi Selvaggi",
  desc = "Non oserei mai mettere in dubbio l'efficacia delle formule di Apothecary Renferrel, ma mentirei se dicessi che la pozione è servita a qualcosa.$B$BLungo la riva del Lake Lordamere c'è uno sciame di murlocs e, cosa degna di nota, i murlocs hanno gli occhi. Sospetto che la voglia dello speziale di provare cose nuove sia soffocata dalla sua recente ossessione per i cuori. Portagli qualche occhio.$B$BSe la scelta è tra andare incontro a una seconda morte certa e farmi uccidere da Renferrel per aver messo in dubbio i suoi metodi, scelgo la seconda.",
  obj = "Raccogli 3 murloc eyes e portali ad Apothecary Renferrel al Sepulcher.",
  progress = "Oh. Sei $Gtornato:tornata;?",
  reward = "La pozione non ha funzionato? Certo che no. Mi hai portato troppo pochi cuori. La ricetta ne richiede chiaramente sei. Tu me ne hai dati tre.$B$BTuttavia, confesso che finora non avevo mai pensato a come usare le parti dei murloc...$B$B<Renferrel prende gli occhi.>$B$BPosso permettermi di sacrificare qualcuno dei miei cuori per restituire le forze al tuo Deathstalker.",
}
T[91921] = {
  title = "Ritorno da Quinn (di Nuovo)",
  desc = "Ecco la nuova pozione per aiutare Quinn a rimettersi, preparata con l'amore estratto da sei cuori interi.$B$BOra scusami, prima che la tua presenza mi costringa a compilare altre scartoffie.",
  obj = "Porta la pozione di Quinn a Quinn Yorick a Ivar Patch, a nord del Sepulcher.",
  progress = "Sei $Gtornato:tornata;! Cominciavo a rassegnarmi all'idea di ridurmi a un ghoul.",
  reward = "<Quinn prende la pozione e la beve.>$B$BSì, sento che sta facendo effetto. Presto potrò rimettermi in viaggio.$B$BMi hai fatto un grande favore, $N.",
}
T[92109] = {
  title = "Il Mio Primo Alchemy Set",
  desc = "Ehm... 'giorno, $Gsignore:signorina;. Non dovrei parlare con gli sconosciuti, però... Ehi, a cosa servono quelle bottiglie luccicanti che ti spuntano dallo zaino? Sei $Gun:un'; alchimista? Che forte!$B$BAnch'io da grande voglio fare l'alchimista. Ma papà non mi fa giocare con nessuna delle sue erbe, dice che è troppo pericoloso.$B$BBe', io voglio cominciare a imparare adesso. Me la procureresti un po' di roba? Ti prego, ti prego!",
  obj = "Porta 5 Empty Vials, 5 Silverleaf e 5 Peacebloom alla giovane aspirante alchimista nel fienile di Moonbrook, nella Westfall.",
  progress = "'Giorno di nuovo! Me l'hai portata, la roba da alchimia?",
  reward = "Oddio! Guarda qua! Le hai raccolte tu, le erbe?$B$BWow, grazie $Gsignore:signorina;, corro subito a vedere cosa riesco a fare con questa roba! Vuoi guardare?",
}
T[92110] = {
  title = "La Mia Prima Vera Pozione",
  desc = "Wow, la mia primissima pozione! Quando hai cominciato tu, lo sapevi che mescolando quelle due erbe la pozione sarebbe diventata di un rosso acceso?$B$BÈ stato divertente, ma mettere insieme qualche fiore non mi sembra il genere di alchimia che fa papà. Lui ci mette anche altri ingredienti.$B$BNon so cos'altro usare, quindi proviamo con la prima cosa che mi viene in mente! Vediamo... i murloc eyes, magari? Mi fa schifo solo a dirlo, ma scommetto che succederà qualcosa.",
  obj = "Raccogli 3 Murloc Eyes per la giovane aspirante alchimista nel fienile di Moonbrook, nella Westfall.",
  progress = "Non preoccuparti per me, sono grande e so badare a me stessa. Solo, non dire a nessuno che mi nascondo qui: è il nostro piccolo segreto.",
  reward = "Mi hai portato i murloc eyes! Sono così emozionata per la mia prima VERA pozione che mi manca il respiro!$B$BMentre eri via sono sgattaiolata fuori a prendere qualche altra erba, e al piano di sotto ho trovato delle empty vials. Ehm... stavolta mescoli tu.$B$B<La bambina ti guarda con entusiasmo mentre mescoli gli ingredienti, ma quando aggiungi gli occhi arriccia il naso. In pochi secondi l'intruglio si fa di un arancione malaticcio.>$B$BWow! Visto? Avevo ragione. Io non la berrei, ma se ne vuoi fare ancora, ecco la mia ricetta. Torna a trovarmi qualche volta!",
}
T[92124] = {
  title = "Inventario dei Libri",
  desc = "Dobbiamo capire quanti libri mancano!$B$BVa' a parlare con Daniel, il mio inutile assistente: può fare un inventario veloce e dirci quanto è grave il problema.$B$BHa la testa fissa sulle varie professioni artigiane dell'Elwynn Forest. Quel ragazzo pensa sempre a quelle, invece che al lavoro importante che ha: aiutare me.$B$BNon farlo partire a blaterare di professioni, e scopri che fine hanno fatto i miei libri!",
  obj = "Parla con Daniel, l'assistente di Brother Paxton, nella biblioteca.",
  reward = "Già, l'ho sentito. Per tre volte ho avvertito Brother Paxton che i coboldi stavano scavando gallerie sotto l'abbazia.$B$BPare che si siano presi un sacco di libri: ci sono scaffali interi svuotati. Forse dovresti chiedere a Brother Paxton cosa vuole che tu faccia.$B$BGià che sei qui, posso parlarti delle professioni? Sarei felice di rispondere alle tue domande o di indicarti gli istruttori della zona.",
}
T[92401] = {
  title = "Una Richiesta Spaventata",
  desc = "È per mio marito, Edward...$B$BOgni settimana va al cimitero tra le rovine di Lordaeron, ma stavolta non è tornato. Abbiamo perso nostro figlio quando Arthas ha raso al suolo la città, e non ne abbiamo mai ritrovato il corpo: per questo il mio caro Edward è ancora pieno di senso di colpa e di dolore. Ho provato a convincerlo a non frugare in quelle rovine invase, ma lui non vuole arrendersi. Cerco di non stare in pensiero, ma ormai sono passati giorni.$B$BLaggiù ci sono cose che non posso affrontare. Ma se sei $Gdisposto:disposta;, devo sapere che fine ha fatto mio marito.",
  obj = "Indaga sulla scomparsa di Edward Heartweaver nelle Ruins of Lordaeron.",
  progress = "Prima mio figlio, e adesso il dolce Edward...",
  reward = "Non era giusto chiederti una cosa del genere, e non sarebbe stato ingiusto se te ne fossi semplicemente $Gandato:andata;. Grazie, $Gstraniero:straniera;. Non posso ricambiarti come meriteresti, ma spero che uno di questi ti vada bene.$B$BSpero che le nostre strade si incrocino di nuovo, senza tanto dolore.",
}
T[92415] = {
  title = "Ricorda Che ti Voglio Bene",
  desc = "<Sul terreno del cimitero, calpestato dai non morti, un fascio di pergamene strappate e macchiate è sopravvissuto a stento. Vi si parla di un bambino scomparso della famiglia Heartweaver. Forse la matrona degli orfani di Stormwind City ne saprà di più.>",
  obj = "Porta la Blood-Stained Letter a Orphan Matron Nightingale a Stormwind City.",
  progress = "Che c'è, $N? Cosa cerchi?",
  reward = "Heartweaver? Heartweaver...$B$BOh! Little Jeremy Heartweaver. L'hanno portato qui anni fa, dopo l'attacco a Lordaeron. Poverino, nell'attacco ha perso tutti e due i genitori.$B$BA dire il vero, poco tempo fa l'ha adottato una donna dolce che vive a Duskwood.",
}
T[92421] = {
  title = "La Giustizia della Luce",
  desc = "Come paladino dei Forsaken, ho il dovere di compiere la volontà della nostra Dama Oscura e, insieme, di provvedere ai bisogni della nostra gente. E per nostra fortuna possiamo fare l'una e l'altra cosa.$B$BSopra l'Undercity il flagello si aggira ancora in gran numero, e nessuno lo ferma. Le nostre forze si assottigliano mentre cerchiamo di riprenderci la nostra terra, e la carne in decomposizione non si può ricucire. Non senza pezzi di ricambio.$B$BSe solo il nostro glorioso capitano Garek Bandarion fosse ancora con noi, so cosa vorrebbe: finire ciò che ha cominciato e guarire la nostra gente. Per Lordaeron!",
  obj = "Raccogli 25 Intact Limbs nelle Ruins of Lordaeron per Morbin Lightbane nell'Undercity.",
  progress = "Che ne è del flagello invasore? Sei $Griuscito:riuscita; a trovare dei pezzi di ricambio adatti?",
  reward = "Chi perde il favore di The Banshee Queen subisca la nostra giustizia!$B$BCon questi pezzi i nostri fratelli e le nostre sorelle possono sperare di arrivare a domani. Fai onore a Captain Bandarion.",
}
T[92422] = {
  title = "L'Ira di Rath'mael",
  desc = "Sono arrivati rapporti dal Lordamere Overlook, nel cuore delle Ruins of Lordaeron. Una nebbia empia ha invaso le strade e il cimitero, offrendo un po' di copertura al flagello lassù. $B$BSecondo i nostri esploratori, quei non morti li evoca una nuova figura potente fra le loro fila, un negromante noto come Rath'mael. Non possiamo permetterci il lusso di aspettare che la cosa si risolva da sola, $N.$B$BSe hai alleati, chiamali in aiuto dei Forsaken. Caccia questa creatura dalle nostre terre.",
  obj = "Uccidi Rath'mael nelle Ruins of Lordaeron per Deathguard Kristof a Brill.",
  reward = "Non ho dubbi che qualcun altro della sua specie lo rimpiazzerà, ma possiamo solo sperare che nel frattempo le loro fila si assottiglino.$B$BGrazie, $N.",
}
T[92432] = {
  title = "Una Richiesta Allarmante",
  desc = "Porto cattive nuove da Dalaran. Qualcosa ha sconvolto le nostre linee di prana, e in città i nostri costrutti sono diventati imprevedibili e distruttivi.$B$BNon sappiamo ancora da dove venga questo caos, e l'alto consiglio ci ha ordinato di non farne parola, per non disonorare il nostro ordine. Ma questa farsa non può andare avanti per sempre. Proprio adesso, la città viene invasa!$B$BÈ stata Archmage Modera a mandarmi a chiedere aiuto fuori. Troverai la sua immagine vicino a Dalaran, sulla riva del Lordamere Lake.",
  obj = "Presentati dall'Image of Archmage Modera vicino alla City of Dalaran.",
  reward = "Vedo che Jacques ha trovato aiuto.$B$BNon sarebbe del tutto permesso, ma in un momento così disperato non possiamo lasciare che il nostro orgoglio respinga degli alleati. Non lasciarti ingannare dalle guardie: la situazione è tutt'altro che sotto controllo.",
}
T[92434] = {
  title = "Sangue per le Strade",
  desc = "Qualunque cosa sia stata ad abbassare la barriera di Dalaran, ora la città è nel caos. E adesso che hai sistemato le loro pattuglie, non potremmo avere momento migliore per entrare e scoprire i loro segreti.$B$BPorta con te la chiave che hai trovato al campo di internamento e cerca le fogne lungo il confine settentrionale della città. Con un po' di fortuna, quei maghi non avranno avuto motivo di proteggere un punto d'ingresso così... sgradevole.",
  obj = "Trova un modo per entrare a Dalaran lungo Lordamere Lake.",
  progress = "Abbassa l'arma, $R.$B$BQuella chiave non basterà a superare le mie protezioni, credo. Davvero pensavi che avremmo lasciato scoperto un punto debole del genere, in un momento come questo?",
  reward = "Che l'orda si sia interessata alla mia città proprio in un momento così precario non è certo un caso.$B$BAnzi, ci contavo. Ho una proposta da farti.",
}
T[92454] = {
  title = "$GBenvenuto:Benvenuta;!",
  desc = "$GBenvenuto:Benvenuta; in World of Warcraft!$B$BPer ringraziarti in modo speciale di aver acquistato la Collector's Edition di World of Warcraft, consegna questo buono regalo a Dalia Windbreeze in Thendal Grove. In cambio riceverai un regalo: un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.$B$BGrazie ancora, e buona permanenza in World of Warcraft!",
  obj = "Porta il Thendal Grove Gift Voucher a Dalia Windbreeze.",
}
T[92456] = {
  title = "Un Campione Verde",
  desc = "Se proprio devi seccarmi, renditi almeno utile. C'è una commissione da sbrigare.$B$BPer essere una città di maghi, Dalaran si interessa di botanica più di quanto ci si aspetterebbe. I Kirin Tor se ne stanno per conto loro, ma mi piacerebbe tanto avere un campione della loro vegetazione intrisa di mana.$B$BSi vede che ti trovi a tuo agio dove la gente non ti vuole: forse potresti trovare il modo di entrare in città. Se ci riesci, portami qualunque cosa cresca nel loro giardino centrale.",
  obj = "Raccogli un Fel Infused Blossom nella City of Dalaran per Shylamiir, a Stormwind City.",
  progress = "Allora, ce l'hai già?",
  reward = "Questo... non è quello che avevo in mente.$B$BEvidentemente la città ha più guai di quanto mi aspettassi. Ma quello che hai trovato è altrettanto affascinante, se non di più.$B$BNon sei poi così $Gfastidioso:fastidiosa; come pensavo, direi. Bel lavoro.",
}
T[92457] = {
  title = "Arcano Affamato",
  desc = "La breccia ha colpito molti dei nostri factotum e degli incantamenti sparsi per la città, e fra questi diversi che si occupano delle difese. Questa energia arcana frammentata ha parlato a elementali ribelli, che ora cercano di saturarsi della magia che scorre libera.$B$BMentre noi pensiamo alle protezioni e alle altre emergenze gravi, se riuscissi a sfoltire questa massa di elementali faresti un favore al Kirin Tor.",
  obj = "Sconfiggi 8 Seeking Remnants, 8 Saturated Remnants e 8 Mana Echoes dentro la City of Dalaran per Archmage Modera, fuori da Dalaran.",
  reward = "Grazie, $N. Questi progressi contribuiranno a tenere Dalaran al sicuro.",
}
T[92458] = {
  title = "Il Cuore della Perturbazione",
  desc = "Qualunque cosa abbia perturbato le linee di prana, è partita dalla cima della Violet Citadel. Dai salotti dei piani alti è arrivato un fragore assordante, e adesso un potere arcano fuori controllo ci sommerge. Ci vogliono tutte le nostre forze anche solo per tenere in piedi le protezioni.$B$BNon possiamo più perdere tempo. Ci serve aiuto.$B$BIl Kirin Tor ha il suo da fare là dentro, ma a te servirà comunque un modo meno in vista per entrare. Prendi questa chiave: quando sarai $Gentrato:entrata; in città, raggiungimi nella cittadella. Dobbiamo mettere fine a questa perturbazione.",
  obj = "Raccogli l'Arcane Mote per l'Image of Archmage Modera vicino alla City of Dalaran.",
  progress = "A che ci serve l'orgoglio, se non resta in piedi nessuna città di cui andare fieri?",
  reward = "Non so cosa tu abbia visto lassù, $N, e non ha importanza. Ora conta solo contenere questo granulo e mettere fine a questa follia.$B$BLa tua parte l'hai fatta bene. Il resto, adesso, tocca a noi.",
}
T[92459] = {
  title = "$GAmico:Amica; del Kirin Tor",
  desc = "Il consiglio non sarà contento quando scoprirà il nostro sotterfugio, ma i risultati non potrà negarli. La città si sta calmando e possiamo abbassare le protezioni.$B$BMi sembra giusto che la buona notizia la porti tu. Consegna questo granulo ad Archmage Celindra, nella Violet Citadel.",
  obj = "Parla con Archmage Celindra nella City of Dalaran.",
  progress = "Archmage Modera parla un gran bene di te. Che cosa ti porta a Dalaran?",
  reward = "Dove l'hai trovato? Nel salotto?$B$B<Per un istante l'espressione di Archmage Celindra si fa cupa, poi lei ritrova la compostezza.>$B$BCredo che faresti meglio a togliertelo dalla mente, $Gamico:amica;. Per ora il Kirin Tor è lieto di accogliere $Gun:una; $C competente come te. $GBenvenuto:Benvenuta; a Dalaran.",
}
T[92461] = {
  title = "Armonia in Equilibrio",
  desc = "Viviamo tempi di grande incertezza per il nostro popolo. Affrontiamo sfide senza precedenti, che forse richiederanno soluzioni audaci, ma dobbiamo anche fare i conti con le faccende ordinarie e quotidiane qui in Thendal Grove. Pensa, per esempio, al recente e insostenibile aumento della popolazione di vuldren.$B$BI vuldren sono una parte vitale del nostro ecosistema. Tuttavia, gli squilibri vanno corretti per preservare la delicata armonia che unisce tutte le creature di Thendal Grove.$B$BVa' a est e abbatti un po' dei vuldren che troverai.",
  obj = "Uccidi 8 Vuldren Juveniles a Thendal Grove.",
  progress = "Per quanto sia sgradevole dover abbattere delle creature viventi, senza una mano che intervenga così la nostra terra andrebbe incontro al disastro. È una lezione importante per qualcuno come te.",
  reward = "Grazie per il servizio reso a Zephras, giovane $C.$B$BDi solito i vuldren sono piuttosto docili, ma gli animali che abitano Zephras avvertono quando la magia nei venti perde l'equilibrio e, se nessuno interviene, possono diventare pericolosi e imprevedibili.",
}
T[92462] = {
  title = "Indagine sull'Infestazione",
  desc = "Uno dei nostri ranger ha segnalato da poco un'infestazione di cirromosche qui in Thendal Grove. $B$BQuesti insetti possono diventare pericolosi se lo sciame cresce troppo, quindi ti chiederei di andare all'estremità orientale del Boschetto e di sterminarne quanti più puoi.",
  obj = "Uccidi 8 Pesky Cirrusflies in Thendal Grove.",
  progress = "Non possiamo permettere che simili parassiti mettano radici nel nostro tranquillo boschetto. Un'infestazione, se non la si tiene sotto controllo, può diventare pericolosa in fretta.",
  reward = "A giudicare da quante budella d'insetto hai addosso, dev'essere proprio una bella infestazione.",
}
T[92463] = {
  title = "La Cirrusfly Queen",
  desc = "Se la foresta è davvero così piena di questi insetti, uccidere le operaie non basterà.$B$BAddentrati fra gli alberi e trova la regina. Sarà vicino all'alveare, circondata da soldati più grossi e aggressivi, quindi stai $Gattento:attenta;.$B$BToglila di mezzo e torna qui quando hai finito. Sarà un problema in meno a cui pensare da queste parti.",
  obj = "Distruggi la Cirrusfly Queen in Thendal Grove.",
  progress = "Le cirromosche non vanno sottovalutate. Magari non sembrano pericolose, ma devi fare attenzione a quelle più grosse. Più sono grandi, più sono cattive!",
  reward = "Bel lavoro, $N. Saresti $Gun ottimo:un'ottima; ranger, se questa storia dell'\"$Gavventuriero:avventuriera;\" non dovesse funzionare.",
}
T[92464] = {
  title = "Inquietudine Elementale",
  desc = "Da quando i nostri benefattori elementali ci hanno lasciati, a quanto pare non facciamo che passare da un subbuglio all'altro. Ora il problema è che le creature nate dai venti, vicino ai monoliti a nord-est, sono in agitazione.$B$BA differenza degli spiriti del vento senzienti che un tempo vivevano qui, questi semplici folletti non hanno una vera coscienza di sé: rispecchiano le forze, le emozioni e le intenzioni delle creature che li circondano. $B$BLa mia apprendista, Yala Windwatcher, è andata a osservarli. Cercala e scopri che cosa ha appreso.",
  obj = "Parla con Yala Windwatcher a Thendal Grove.",
  reward = "Ti ha $Gmandato:mandata; Rorian? Bene. Il tuo aiuto mi farebbe comodo.",
}
T[92465] = {
  title = "Sobillatori",
  desc = "Il culto degli Al'Aketh è una piaga per quest'isola. Sono di certo questi cultisti ad agitare i semplici folletti del vento che vivono qui e a renderli violenti.$B$BPurtroppo dovremo disperdere i roiling winds prima che facciano del male a qualcuno. Bisogna anche mandare al culto un messaggio chiaro: nel boschetto non sono graditi.$B$BMi aiuterai, $C?",
  obj = "Uccidi 6 Roiling Winds e 7 Al'Aketh Converts a Thendal Grove.",
  progress = "È fatta?",
  reward = "Mi addolora versare sangue shen'dorei qui nel boschetto, ma si fa quel che si deve.",
}
T[92466] = {
  title = "Richiamo della Terra",
  desc = "Gran parte della nostra prosperità la dobbiamo agli elementi del vento, eppure il cammino che percorriamo ci chiede di obbedire al richiamo di tutti e quattro gli elementi primari e di affrontare una prova per ciascuno. Ma prima di cominciare davvero la tua prima prova, devi dimostrare quanto è forte la tua determinazione.$B$BVai alle pietre erette a est. Lì hanno avvistato un gruppo di convertiti degli Al'Aketh, e vanno cacciati. Affronta i cultisti e portami uno dei loro sigilli, come prova delle tue imprese.",
  obj = "Porta un Signet of Akir a Windshaper Boro.",
  progress = "Il culto degli Al'Aketh è il pericolo più diretto e urgente per la nostra patria. Con le loro azioni, sempre più estremiste, hanno destabilizzato la nostra società e danneggiato il legame, già indebolito, che ci unisce agli spiriti dei quattro venti. Gli elementi ci chiedono di agire per dimostrare tenacia e determinazione, qualità proprie del dominio dell'elemento della terra.",
  reward = "Sei $Gtornato:tornata; con quello che ti avevo chiesto, quindi la tua grinta e la tua determinazione sono fuori discussione. Sei $Gpronto:pronta; per il passo successivo, $N.",
}
T[92467] = {
  title = "Richiamo della Terra",
  desc = "La sapta è una bevanda creata per legare i nostri spiriti agli elementi. Questa pozione è intrisa di magia e permette a chi ha una volontà forte di vedere gli elementi come nessun altro può. Il tuo spirito sarà legato all'elemento per cui la sapta è stata creata, e la ricetta la conosce solo una ristretta cerchia di sciamani.$B$BLa sapta si beve sempre in un luogo sacro, mai da nessun'altra parte — ricordalo.$B$BCerca la Rise of Spirits, su per il passo a est di qui. Lì bevi la sapta e... be', vedrai quello che devi vedere.",
  obj = "Trova la Rise of Spirits e bevi l'Earth Sapta.",
  reward = "Ah... $N... $Gfiglio:figlia; dei quattro venti... Cerchi di capire. Cerchi risposte. Perché i venti ti hanno abbandonato? Come puoi riaverli? Queste risposte non posso dartele, perché non conosco né i motivi né i movimenti dei venti.$B$BSulla terra, però, posso insegnarti molto. La sua forza, la sua determinazione. Anche qui, lassù in questo mare infinito di nuvole, resti una creatura della terra. Se speri di trovare la forza per parlare di nuovo con gli spiriti dei quattro venti, è questo il cammino che devi percorrere.",
}
T[92468] = {
  title = "Il Richiamo della Terra",
  desc = "Prendi questo Rough Quartz e portalo a colui che chiami Windshaper Boro, come prova del nostro incontro. Ti creerà un totem, e questo frammento ne sarà il cuore. Per quanto possa sembrare minuto, scoprirai che le dimensioni non contano, e che anche la più piccola delle cose può durare più di tante altre.$B$BSii paziente, $N. Resta forte. E cerca la saggezza. È questo che gli elementi ti chiedono. Alla fine diventerai una cosa sola con la terra — rispettala, come lei rispetterà te.",
  obj = "Porta il Rough Quartz a Windshaper Boros in Thendal Grove.",
  progress = "Come imparerai, il sentiero che percorriamo è meno semplice di quanto sembri. Cerchiamo la voce necessaria per parlare con gli spiriti dei venti, ma i venti non sono che una delle forze elementali di questo mondo. Solo comprendendo tutti e quattro gli elementi e — speriamo — imparando a padroneggiarli ritroveremo la voce per intonare di nuovo i canti del vento.",
  reward = "Bene!$B$BIl totem che ti creerò non è solo un simbolo del tuo rango di $C — ha anche altre capacità. Può servire, per esempio, da catalizzatore per gli incantesimi. Sono incantesimi legati alla terra e, man mano che la tua saggezza crescerà, potrai attingere a sempre più poteri di questo elemento.$B$BGli istruttori sapranno quando sarai $Gpronto:pronta; per un sapere più profondo.$B$BMa per ora, prendi questo totem della terra...",
}
T[92469] = {
  title = "Ritorno da Rorian",
  desc = "Hai fatto abbastanza qui, $C. Io resterò a ripulire quaggiù gli ultimi rimasti.$B$BTorna al Villaggio e avvisa Rorian della presenza del culto. Non ne sarà contento.",
  obj = "Riferisci a Rorian the Dayseeker la notizia degli Al'Aketh, a Thendal Grove.",
  reward = "È davvero preoccupante, ma purtroppo non sorprende. Da tempo siamo al corrente dei movimenti del culto, ma ci siamo limitati a osservarli da lontano. Agitando gli spiriti del vento vicino ai monoliti, hanno chiaramente alzato il tiro.$B$BHai reso un servizio difficile ma necessario a Thendal Grove, $N. Grazie.",
}
T[92470] = {
  title = "Matriarca Immonda",
  desc = "Rorian ti ha detto che ti ho tenuto d'occhio. Ora ti propongo una prova di determinazione. Ma ti avverto — ti porterà incontro a grandi pericoli.$B$BVai nelle caverne a ovest. Sfoltisci le file degli ursera che vi abitano e trova la loro matriarca, quella che i ranger chiamano \"Urs'anah\". Abbattila e portami la prova della sua morte. Fatto questo, avrai compiuto un passo importante sul tuo cammino.",
  obj = "Uccidi 8 Ursera Scavengers e raccogli la testa della madre della tana, Urs'anah, a Thendal Grove.",
  progress = "Ciò che ti chiedo non è facile, ma dovrai essere $Gpronto:pronta; a sfide ben più grandi, se vuoi sopravvivere abbastanza a lungo da servire Zephras Isle.",
  reward = "Ottimo lavoro. Hai abbattuto bestie e sconfitto gli intrusi del culto. Hai mostrato grandi potenzialità, ma presto il tuo cammino dovrà portarti oltre la relativa sicurezza del Thendal Village.",
}
T[92471] = {
  title = "Aetheen of the Gales",
  desc = "Forse non te ne rendi conto, ma tutto ciò che hai fatto è stato una sorta di prova. Un esame in vista di quel che ti attende. L'isola là fuori è grande, e Zephras ha bisogno di giovani avventurieri pieni di slancio come te, se vogliamo uscire vivi dalle prove che il nostro popolo deve affrontare.$B$BColei che chiamano Aetheen of the Gales è una delle nostre guide qui su Zephras Isle, e ti ha tenuto d'occhio. Ha un compito che dovrai portare a termine. Parla con lei per saperne di più.",
  obj = "Parla con Aetheen of the Gales a Thendal Grove.",
  reward = "Rorian mi ha parlato molto di te. Probabilmente non mi conosci, ma sono un membro del Council of Elders qui su Zephras Isle. Sono venuta a Thendal Grove per leggere il flusso dei venti, e anche per valutare i giovani shen'dorei come te che stanno diventando adulti.$B$BDimmi dunque: sei $Gpronto:pronta; a fare il prossimo passo? Sei $Gpronto:pronta; a servire Zephras Isle?",
}
T[92472] = {
  title = "Il Prossimo Passo",
  desc = "Una delle minacce più diffuse su Zephras Isle è il Culto degli Al'Aketh. Sono fanatici religiosi votati all'adorazione del presunto sovrano elementale di Skywall, Al'Akir the Windlord. Sono brutali e ostinati, e il loro potere e le loro ambizioni si fanno ogni giorno più micidiali.$B$BPresto il tuo cammino ti porterà a Shen'dar Village, a sud. Quando arrivi, presentati a Constable Aonda. Il culto minaccia Shen'dar, che ha bisogno di aiuto. Di' ad Aonda che ti mando io.",
  obj = "Fai rapporto a Constable Aonda a Shen'dar Village.",
  reward = "Ti ha $Gmandato:mandata; Aetheen, quindi? Lo confesso, non mi sembri granché, ma Shen'dar Village non rifiuta un aiuto volenteroso, tanto meno se a inviarlo è Elder Aetheen in persona.",
}
T[92473] = {
  title = "Invasione Aggressiva",
  desc = "La tana di ursera a sud-ovest sta diventando un problema, e in fretta. Proprio la settimana scorsa i guardaboschi hanno dovuto uccidere un giovane ursera che si era avvicinato troppo alle case e aveva tentato di aggredire un bambino mentre giocava ai piedi dell'albero antico, al centro del villaggio.$B$BPer fortuna il piccolo è sopravvissuto. La fame e la disperazione rendono queste bestie troppo pericolose per lasciarle fare. Va' a sud e abbatti gli ursera più gracili. Quando hai finito, portami i loro artigli come prova.",
  obj = "Raccogli 6 Scrawny Ursera Claws da Scrawny Ursera in Thendal Grove.",
  progress = "Ultimamente gli ursera sono diventati molto più aggressivi. Chissà cosa è cambiato per farli comportare così.",
  reward = "Ben fatto, $C. I Rangers del Boschetto hanno un debito con te.",
}
T[92474] = {
  title = "Cadere con Stile",
  desc = "Ehi, ciao, $N! Ti va di fare un gioco?$B$BDevi solo salire su quel cornicione... e poi saltare! Usa la capacità innata di camminare sull'aria per rallentare la caduta e vedi fin dove riesci ad arrivare planando.$B$BLe regole sono inventate e i punti non contano, ma prendi punti bonus se riesci ad atterrare proprio davanti a Rorian the Dayseeker e spaventarlo! Non gli piacerà, ma se riesci a metterlo tutto in agitazione io mi farò di sicuro una bella risata! Ah!",
  obj = "Salta dalla cima della torre di guardia di Thendal Grove e usa l'abilità Walk on Air per rallentare la caduta.",
  progress = "Camminare sull'aria può tirarti fuori da — e, beh... cacciarti in — guai di ogni genere!",
  reward = "Quante volte dovrò ripetere a Myriaal di non spingere gli altri a usare i nostri doni di skyborne in modo sconsiderato!$B$BDetto questo, suppongo che un po' di pratica nella relativa sicurezza del villaggio sia... accettabile.$B$BIn futuro ti suggerirei solo di usare la tua capacità con giudizio. Non vorrai esaurire la magia alla leggera e poi trovarti a secco quando ne avrai davvero bisogno.",
}
T[92479] = {
  title = "Una Scribbled Letter",
  desc = "Mi hanno chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera chiusa con il sigillo di Tordrin Stemblade, il nostro istruttore dei cacciatori. Prenditi un momento per leggerla, prima di dedicarti a qualunque altra faccenda qui all'Abbazia.",
  obj = "Leggi la Scribbled Letter e parla con Tordrin Stemblade a Northshire Abbey.",
  progress = "Ah, t'è arrivata la mia lettera, $N... bene.$B$BUna volta un umano non si sarebbe fatto vedere manco morto con un arco in mano — ora non più, mi sa. È un bene per Stormwind, ma un male per i coboldi e le bestie mangiauomini della zona.",
  reward = "Sistemati per bene, impara a conoscere il territorio e torna da me ogni volta che ti serve addestramento. Sarò qui giorno e notte.$B$BQuesta terra si fa sempre più pericolosa, e quando incontrerai altra gente scoprirai, credo, che hanno tutti qualche guaio e una mano gli farebbe comodo — una mano che un cacciatore in gamba può dargli. Buona fortuna.",
}
T[92481] = {
  title = "$GUn Allievo:Un'Allieva; dell'Arcano",
  desc = "Mentre eri via a occuparti del problema dei vuldren, la nostra istruttrice di magia — Dorii Brightwhisper — ha lasciato per te questo cristallo di richiamo. Contiene una specie di messaggio, quindi dagli un'occhiata. Dopo, troverai Dorii nell'edificio proprio dietro di me.",
  obj = "Esamina il Glowing Recall Crystal, poi parla con Dorii Brightwhisper a Thendal Grove.",
  progress = "Salve, $N. Sono lieta di avere il privilegio di aiutarti a progredire negli studi di magia.",
  reward = "Fatti guardare. Sì, credo che diventerai $Gun giovane:una giovane; $C eccellente. Il potere arcano si è affievolito nel nostro popolo, ma c'è chi vorrebbe riscoprire molto di ciò che abbiamo perduto nei millenni trascorsi quassù, tra le nuvole. Sono certa che sarai in prima linea in questa ricerca senza fine della conoscenza arcana, e che un giorno ci renderai orgogliosi.$B$BTorna a parlarmi se vuoi proseguire il cammino.",
}
T[92482] = {
  title = "La Via $Gdel:della; $C",
  desc = "Mentre eri via a occuparti del problema dei vuldren, l'istruttrice che qui addestra ogni $C come te — Tai'ree Farsight — ha lasciato questo biglietto per te. La trovi proprio laggiù, vicino al centro del villaggio. Leggilo, poi va' a cercarla.",
  obj = "Leggi la Scribbled Note, poi parla con Tai'ree Farsight a Thendal Grove.",
  progress = "<Tai'ree ti rivolge un secco cenno del capo.>",
  reward = "La via $Gdel:della; $C è irta di pericoli, e solo chi ha i sensi più acuti e i riflessi più pronti può prosperare nelle terre selvagge. Ti guardo e rivedo me stessa davanti al mio mentore, tanti anni fa. Credo che tu abbia la stoffa, ma alla fine dipende solo da te.$B$BTorna a parlarmi se vuoi proseguire il cammino.",
}
T[92483] = {
  title = "A Casa tra le Ombre",
  desc = "Mentre eri via a occuparti del problema dei vuldren, l'istruttore che qui addestra ogni $C come te — Akeri Duskblade — ha chiesto di parlarti. Ti ha lasciato questo biglietto: dopo averlo letto, raggiungilo nella torre di guardia, qui al villaggio.$B$BÈ un tipo losco, ma d'altronde lo sei anche tu. Credo che andrete d'accordo.",
  obj = "Leggi la Simple Note, poi parla con Akeri Duskblade nella torre di guardia di Thendal Grove.",
  progress = "<Akeri ti squadra con sospetto.>",
  reward = "Per poco non ti ho sentito avvicinarti, giovane $C.$B$BPer poco.$B$BMa \"per poco\" non basterà quando lascerai Thendal Grove. Devi essere una lama sottile, silenziosa e ferma. Sempre vigile, sempre $Gattento:attenta; a ciò che ti circonda. Potresti avere la stoffa per sopravvivere ai pericoli di Zephras. Ma potresti anche finire in un fosso con la gola tagliata. Alla fine, dipende solo da te.$B$BTorna a parlarmi se vuoi proseguire il cammino.",
}
T[92484] = {
  title = "Abbracciare gli Elementi",
  desc = "Mentre eri via a occuparti del problema dei vuldren, l'istruttore che qui addestra ogni $C come te — Windshaper Boro — ha lasciato per te questo cristallo di richiamo. Esaminalo, per favore, poi parla con Boro, che trovi proprio laggiù, vicino al centro del villaggio.",
  obj = "Esamina l'Humming Recall Crystal, poi parla con Windshaper Boro a Thendal Grove.",
  progress = "Che i venti ti guidino, $N.",
  reward = "Lo senti? Il sussurro dei venti? Ne dubito, visto che gli spiriti hanno smesso di parlarci quando ci hanno abbandonati, tanti anni fa.$B$BChi tra noi vorrebbe tornare a chiedere udienza agli spiriti dei quattro venti affina la propria conoscenza degli elementi e del mondo naturale, sperando con tutto il cuore di riprendere il dialogo interrotto così all'improvviso.$B$BVorresti percorrere questa via e padroneggiare gli elementi?$B$BTorna a parlarmi se vuoi proseguire il cammino, e ti addestrerò.",
}
T[92485] = {
  title = "$GUn Allievo:Un'Allieva; della Natura",
  desc = "Mentre eri via a occuparti del problema dei vuldren, l'istruttore che qui addestra ogni $C come te — Xyton Silverwind — ha lasciato questo biglietto per te. Leggilo appena puoi, poi cerca Silverwind al pianterreno del grande albero proprio dietro di me.$B$BAscolta le sue parole e i suoi consigli: può insegnarti molto.",
  obj = "Leggi la Folded Parchment, poi parla con Xyton Silverwind a Thendal Grove.",
  progress = "Salve, sono Xyton Silverwind, custode della sapienza druidica.",
  reward = "La flora e la fauna di Zephras Isle formano un ricco mosaico di vita rigogliosa. L'ecosistema ha bisogno di un equilibrio costante per mantenere l'armonia della natura, e noi druidi ne siamo i custodi. Vedo in te un grande potenziale, ma questa via non è facile, e ti servirà una guida mentre acquisterai forza come $Gallievo:allieva; della zanna, dell'artiglio, della piuma e del ramo.$B$BTorna a parlarmi se vuoi proseguire il cammino.",
}
T[92489] = {
  title = "Potere Travolgente",
  desc = "I Kirin Tor sono da tempo alleati dell'Alleanza. Da quando l'arcidemone Archimonde l'ha distrutta, la città dei maghi, un tempo fiera, si è chiusa in sé stessa e ha cominciato a diffidare degli estranei.$B$BNegli ultimi anni hanno cominciato a ricostruire la città di Dalaran per riportarla all'antico splendore, ma secondo i rapporti faticano a contenere un'esplosione di energie arcane fuori controllo.$B$BDobbiamo aiutarli a respingere questi attacchi, altrimenti rischiamo di perdere uno dei nostri alleati più potenti.",
  obj = "Uccidi il Mana Elemental nella City of Dalaran per High Sorcerer Andromath, a Stormwind City.",
  reward = "Una creatura di puro mana? Qualunque cosa stia causando questa perturbazione, è più potente di quanto dicessero i primi rapporti.$B$BCon il tuo aiuto hanno guadagnato tempo prezioso, e hai ricordato ai Kirin Tor chi sono i loro alleati. Ottimo lavoro, $N.",
}
T[92514] = {
  title = "$GBenvenuto:Benvenuta; a Shen'dar Village",
  desc = "Hai proprio quell'aria da \"Windshaper\". Ti tradisce quel filo di elettricità statica che sento sulla pelle quando sono vicina a qualcuno toccato dagli spiriti. Prima che ti metta al lavoro sul serio, dovresti presentarti alla nostra anziana Windshaper, Illaya Amberwind. È qui fuori, vicino al centro del paese.$B$BOh, e passa anche da Coriella Calmbreeze: gestisce la locanda e può darti alloggio e provviste, se ti servono.",
  obj = "Parla con Illaya Amberwind e Coriella Calmbreeze a Shen'dar Village.",
  progress = "Questo posto non è granché, ma è casa.",
  reward = "Allora ti sei $Gpresentato:presentata; a Illaya? Bene. Di questi tempi c'è molta tensione fra l'High Order e i Windshapers, ma qui a Shen'dar si mantengono i toni civili. Tutti sanno bene che abbiamo problemi più grandi dei loro battibecchi.$B$BOra che hai sbrigato questa faccenda, mi sembri il tipo che non ama stare con le mani in mano, e io ho un problema con dei banditi: speravo che potessi aiutarmi.",
}
T[92515] = {
  title = "Il Problema dei Prideclaw",
  desc = "Come se non bastassero i banditi e quei cultisti invasati, in questo periodo le colline brulicano anche di prideclaw. Cominciano a spingersi fino ai confini del villaggio e ogni giorno si fanno più audaci. Prima o poi qualcuno perderà un animale o un figlio: è solo questione di tempo. Sarebbe più pietoso sfoltirli adesso che dopo una tragedia.$B$BPortami una dozzina di pelli, più o meno. Posso ricavarne ogni genere di articoli utili al villaggio.",
  obj = "Raccogli 10 Prideclaw Pelts dai Prideclaw nelle Shen'dar Highlands.",
  progress = "Se vuoi saperlo, secondo me i Prideclaw sono perfino carini. A distanza di sicurezza... e stando dietro a qualcuno con una spada in mano, si capisce.",
  reward = "Non ho mica detto che sarebbe stato un lavoro pulito, no?",
}
T[92516] = {
  title = "Ippogrifi Molesti",
  desc = "Da poco uno stormo di ippogrifi ha fatto il nido a sud-est di Shen'dar Village, e da allora semina il panico fra chi viaggia sulla strada. Mi serve qualcuno che scenda laggiù a sfoltirli un po'.",
  obj = "Uccidi 8 Hippogryph Youths, 6 Hippogryph Protectors e un'Hippogryph Matriarch nelle Shen'dar Highlands.",
  progress = "Gli ippogrifi sono creature molto orgogliose. Probabilmente è il rumore dei convogli di carri a innervosirli e a spingerli all'attacco. Qualunque sia il motivo, non possiamo far finta di niente davanti ai carovanieri morti.",
  reward = "Ben fatto, e anche in fretta. Niente male davvero.",
}
T[92517] = {
  title = "La Malavita",
  desc = "Non lontano da qui, a nord, c'è una grotta nascosta dietro una cascata. So per certo che ci si è annidata una banda di briganti. Ci davano problemi già prima che arrivasse il culto, ma ora sono un vero flagello. Purtroppo non posso permettermi di mandare gente a ripulire la zona.$B$BHo bisogno che tu ci vada e te ne occupi al posto mio. Uccidine quanti più puoi e, se possibile, elimina il loro capo, quello che chiamano \"Badwind\" Bennic. Quella grotta è pericolosa, quindi stai $Gattento:attenta;.",
  obj = "Uccidi 10 Highlands Bandits e il loro capo, \"Badwind\" Bennic, nelle Shen'dar Highlands.",
  progress = "È una brutta faccenda vedere gli Shen'dorei ridotti a depredare la loro stessa gente pur di sopravvivere, ma da quando i piloni hanno cominciato a guastarsi, là fuori la disperazione cresce di giorno in giorno.",
  reward = "Ora che i banditi si sono dispersi, abbiamo un problema in meno da affrontare. Anche se, lo confesso, adesso temo che i sopravvissuti cerchino rifugio nel culto e ne ingrossino ancora le file, che già crescono a un ritmo allarmante.$B$BComunque sia, le vittorie ce le prendiamo quando arrivano.",
}
T[92519] = {
  title = "Rifornimenti per il Reparto",
  desc = "Apothecary Jorell doveva portarci una cassa di antidoti ed elisir già giorni fa, e invece siamo ancora a mani vuote. Quello sciocco si sarà avvelenato un'altra volta a forza di preparare pozioni in quella baracca senz'aria che chiama laboratorio.$B$BSe vuoi dare ancora una mano al nostro reparto, per questo compito tu saresti molto più affidabile.$B$BSegui la strada fino alla fattoria Go'shek, a sud di qui e un po' verso ovest. Probabilmente troverai la cassa già imballata e pronta da portare via, e Jorell sparito o disinteressato ai suoi impegni.",
  obj = "Ritira una cassa di Packaged Tonics al laboratorio di Jorell nella Fattoria Go'shek e torna da Doctor Gregory Victor a Hammerfall.",
  progress = "Se riesci a procurare a questi pazienti qualcosa per il dolore, alcuni potrai rimandarli fuori dalla porta veloci come sono entrati.",
  reward = "Nessuna bottiglia rotta? Sì, per questo lavoro sei senz'altro una scelta migliore dei tirapiedi di Jorell.$B$BCon questi potremo tenere a bada i malanni dei nostri pazienti ancora per un po'.$B$BVisto che hai dimostrato di essere $Gportato:portata; per il lavoro sul campo, capisco che le ferite facciano parte del mestiere. Scegli pure fra le provviste: almeno tu le userai.",
}
T[92521] = {
  title = "La Torre dei Demoni",
  desc = "Lo sai che sono $Guno stregone:una strega;, vero? Adesso sono $Gridotto:ridotta; alla miseria e a tagliare carne, ma un tempo ero $Gun potente mago:una potente maga;!$B$BIl mio imp continua ad allontanarsi e, anche se mi basterebbe richiamarlo, sono un po' $Gcurioso:curiosa; di sapere cosa combina. Sgattaiola via per andare a parlare con un satiro incatenato in una torre a sud-est di qui. Se non ti dispiace, vorrei scoprire cosa si dicono.$B$BSono $Gsicuro:sicura; che non c'è niente di cui preoccuparsi, ma con i demoni non si sa mai, giusto?",
  obj = "Spia l'imp di Hnaz alla torre con il satiro prigioniero.",
}
T[92528] = {
  title = "Tra i Fedeli",
  desc = "Con ogni nuova recluta entusiasta come te, i fedeli di Al'Akir diventano sempre più forti. Lo vedi anche tu: la nostra forza dà forma alla tempesta stessa!$B$BDi solito ti manderei subito da Skypriest Aanders per una valutazione, ma in questo momento sta ricevendo un ospite alla locanda, nella parte nord della città. Per ora, ti prego, sta' alla larga da lì: una recluta non rasata come te sarebbe fuori posto davanti a un ospite simile.$B$BNel frattempo, vedi solo di non stare tra i piedi a nessuno.",
  obj = "Guardati intorno in Falaath Village per scoprire le intenzioni del culto negli Shen'dar Highlands.",
  progress = "Che cosa hai scoperto?",
  reward = "C'era Lorthuna in persona? È lei a guidare tutto quel dannato culto!$B$BSe si preparano a muoversi contro Shen'dar Village e la torre di guardia occidentale, dobbiamo farci trovare pronti. La cosa strana, però, è... perché la torre di guardia?$B$BIl Villaggio lo capisco, ma la torre? Non conta granché come posizione strategica, se non come piccolo posto di vedetta.$B$BComunque sia, saremo pronti ad accoglierli. Scopriranno che la gente degli altopiani non si coglie alla sprovvista così facilmente come credono.",
}
T[92529] = {
  title = "Falaath Village",
  desc = "Mi rallegra il cuore sapere che vuoi servire Al'Akir. Le prove che oggi affrontiamo come popolo nascono dal nostro autocompiacimento: siamo diventati superbi e abbiamo dato per scontata la generosità dei venti. Ne è seguita la stagnazione, ed è per questo che gli spiriti del vento ci hanno abbandonati.$B$BSolo con atti di contrizione potremo sentire di nuovo la carezza del vento. Se cerchi la compagnia di shen'dorei che la pensano come te, va' a Falaath Village e lì cerca Missionary Jasaan. Ti marchierò, così i fedeli ti riconosceranno come recluta.",
  obj = "Presentati a Missionary Jasaan vicino all'entrata di Falaath Village.$B$BSe perdi il Marchio di Akir, parla con Sania Silverstream in Shen'dar Village per riottenere l'effetto.",
  reward = "Cosa vedo? $GUn nuovo accolito:Una nuova accolita;, $Gmandato:mandata; dalla sorella Sania, che desidera servire il signore del vento? Oggi siamo davvero benedetti dal tocco dei quattro venti!$B$BAccogliamo chiunque desideri crogiolarsi nelle benedizioni di Al'Akir.",
}
T[92532] = {
  title = "La Via del Guerriero",
  desc = "Mentre eri via, la nostra istruttrice dei guerrieri — Blademaster Ren — ha chiesto di mandarti da lei appena fossi $Gtornato:tornata;. Ti ha lasciato anche questa nota.$B$BLeggila, poi va' a cercare Blademaster Ren nella torre di guardia del villaggio.",
  obj = "Leggi la Crumpled Note che hai ricevuto, poi cerca Blademaster Ren nella torre di guardia di Thendal Village.",
  progress = "Allora, sei $Gvenuto:venuta; ad addestrarti?",
  reward = "Ti aspetta un viaggio pericoloso. Il nostro mondo sta cambiando e, se il nostro popolo spera di sopravvivere, avrà bisogno di chi ha la volontà di guidare e proteggere gli altri. Più diventerai potente, più ti servirà una guida. Vieni da me — farò il possibile per addestrarti man mano che progredisci.$B$BBuona fortuna, $N, e che i venti ti guidino.",
}
T[92544] = {
  title = "Teppisti Al'Aketh",
  desc = "Una banda di facinorosi del culto Al'Aketh, guidata da un vero mostro di nome Malduko Cloudcrush, si è stabilita vicino alle rovine del tempio, poco a sud-ovest di qui. Di sicuro è stata High Priestess Lorthuna dello Shrine of Akir a mandare questa marmaglia ad attaccare i viaggiatori e a costringere la nostra gente a unirsi al culto.$B$BIo devo restare qui al mio posto per avvertire del pericolo chi lascia il boschetto, ma ti sarei grata se potessi occuparti di quei cultisti e del loro capo.",
  obj = "Uccidi 6 Al'Aketh Brutes, 4 Al'Aketh Neophytes e Malduko Cloudcrush in Thendal Grove.",
  progress = "Ho idea che vedere qualche compare sanguinare a terra farà passare in fretta a quei teppisti ogni voglia di fare i fanatici.",
  reward = "Ho dovuto fare di tutto per trattenermi dal lasciare la mia postazione e venire a darti man forte. Posso solo sperare che quegli zoticoni abbiano capito l'antifona e se ne vadano presto. $B$BGrazie, $C. I Rangers di Thendal Grove ti sono riconoscenti.",
}
T[92550] = {
  title = "Caos negli Altopiani",
  desc = "Qui la difesa migliore potrebbe essere proprio l'attacco. Adesso abbiamo un vantaggio: sappiamo che ci colpiranno. Quello che non si aspettano è che saremo noi a farlo per primi.$B$BTi ho già chiesto molto, ma ti prego, torna a Falaath Village. Uccidi tutti i cultisti che puoi e, se riesci ad avvicinarti abbastanza, elimina il comandante e portami la sua testa. Io resto qui a organizzare i cittadini e le nostre poche peacekeepers per preparare una difesa... nel caso tu non tornassi.",
  obj = "Raggiungi le rovine di Falaath Village, uccidi 6 Al'Aketh Stormcallers e 4 Living Lightning e prendi la testa di Commander Cyclas.",
  progress = "È bello ribaltare le parti con questi fanatici.",
  reward = "Siano ringraziati i venti, sei $Gtornato:tornata;!$B$BSania Silverstream è sgattaiolata fuori città poco prima che arrivassi: di sicuro è fuggita quando ha visto i nostri prendere le armi.$B$BHai fatto una cosa incredibile per la gente di Shen'dar Village, e abbiamo con te un debito di gratitudine. Se il culto tornerà negli altopiani, scoprirà che Shen'dar non è un bersaglio così facile.$B$BChe i venti ti guidino, $N.",
}
T[92551] = {
  title = "Stolen Supplies",
  desc = "Ho sentito dire che forse andrai a Falaath Village? Già che sei lì, tieni gli occhi aperti, per favore: potresti trovare i depositi di provviste che ci hanno rubato.$B$BDa mesi gli Al'Aketh assaltano le nostre carovane di rifornimenti, che vanno e vengono dalle pianure trasportando merci di ogni genere, come cibo e windstones. Naturalmente danno la colpa ai banditi, ma sappiamo tutti che la roba finisce sempre nello stesso posto. Se a Falaath ne è rimasta un po' e riuscissi a recuperarla, ci saresti di grande aiuto.",
  obj = "Raccogli 10 pacchi di Stolen Shen'dar Supplies a Falaath Village, in Shen'dar Highlands.",
  progress = "Qui ci sono tanti skyborne affamati e disperati che hanno bisogno di queste provviste.",
  reward = "Fantastico! Senza le consegne regolari tiravamo avanti a malapena. Mi accorderò con il conestabile per ridistribuire questi rifornimenti agli abitanti che ne hanno più bisogno.",
}
T[92553] = {
  title = "Rifornire le Dispense",
  desc = "Hai voglia di lavorare un po'? I muscoli di $Gun avventuriero forte:un'avventuriera forte; come te mi farebbero comodo. Qui intorno si fa sempre più pericoloso, e ultimamente nessuno ha avuto granché tempo per cacciare o raccogliere cibo: mi serve qualcuno che vada là fuori a procurarmi uova fresche e strider meat per sfamare il villaggio.$B$BSe mi porti quello che mi serve, ti insegno volentieri una delle mie famose ricette. Che ne dici?",
  obj = "Raccogli 3 Small Eggs e 8 Strider Meat dalle creature che si trovano negli Shen'dar Highlands.",
  progress = "Per quanto le cose cambino qui su Zephras e per quanto diventino incerte, io lo dico sempre: non c'è conforto migliore di una pipa di peacebloom secco e di una bella pancia piena!",
  reward = "Queste uova non si trovano facilmente, ma che il vento mi salvi, fritte in un po' di sego d'ursera sono DELIZIOSE.$B$BSe ti avanza del tempo e ti piace cucinare, posso passarti qualche consiglio e qualche trucco che ho imparato. Basta una parola e ti addestro volentieri.",
}
T[92579] = {
  title = "Verso Valanaar",
  desc = "Per ora il pilone e il villaggio sembrano al sicuro, perciò vorrei che portassi questo rapporto a Valennia Stormfist, a Valanaar, all'estremità sudorientale dell'isola. Valennia guida i peacekeepers dell'isola e deve sapere cos'è successo qui.$B$BIl culto si sta espandendo in fretta. Finora i peacekeepers hanno evitato lo scontro diretto, ma quei tempi sono finiti: Valanaar dovrà essere pronta a combattere.$B$BAd ogni modo, ti ringrazio. A Shen'dar avrai sempre degli amici, $N.",
  obj = "Consegna l'Aonda's Written Report a Valennia Stormfist a Valanaar.",
  progress = "Una lettera di Aonda. E cosa avrà combinato, quella furba montanara?",
  reward = "<Valennia si incupisce in volto mentre legge la lettera.>$B$BAonda ti ha affidato questa lettera e qui parla abbastanza bene di te, quindi proverò a fidarmi anch'io. Prima di proseguire il discorso devo consultarmi con i pochi peacekeepers che ci restano in città e preparare un piano, nel caso il culto colpisca qui la prossima volta. Intanto goditi il soggiorno a Valanaar.$B$BSe cerchi qualcosa da fare, molti abitanti avrebbero probabilmente bisogno dell'aiuto di $Gun giovane e forte avventuriero:una giovane e forte avventuriera; come te.",
}
T[92595] = {
  title = "I Windshapers",
  desc = "<Illaya ti sorride con calore.>$B$BSono felice che tu sia $Gtornato:tornata; a parlare con me, $Gfiglio:figlia; dei venti. Fin dal primo istante in cui sei $Gcomparso:comparsa; davanti a me ho capito che la vista celeste era forte in te. Anche per $Gun:una; $C, hai un talento particolare per il nostro dono.$B$BVieni, parliamo del mandato dei Windshapers, della natura delle lotte che combattiamo su Zephras e della difficile situazione del nostro popolo.",
  obj = "Ascolta ciò che ha da dire Illaya Amberwind.",
  progress = "Il mondo sta cambiando e ci aspetta una strada difficile. Per salvarci abbiamo una sola possibilità.",
  reward = "Credo che ora tu capisca quanto conti la missione dei Windshapers. Se speriamo di ristabilire un dialogo con gli spiriti dei venti, ogni anima capace di padroneggiare la vista celeste è di vitale importanza.$B$BFra minacce interne come gli Al'Aketh e l'incertezza sulla nostra sicurezza qui a Skywall, tocca a noi, in quanto Windshapers, usare i nostri doni per salvare la nostra casa e far sì che gli Shen'dorei sopravvivano a questi tempi difficili.",
}
T[92596] = {
  title = "L'High Order",
  desc = "Intorno a te c'è un'aura di energia arcana forte, anche per $Gun:una; $C come te.$B$BVieni, sediamoci a parlare un po' della natura dell'arcano e della difficile situazione della nostra patria.",
  obj = "Siediti e parla con Rathiril Sunlance.",
  progress = "La nostra terra sta cambiando, ma da tutto questo potrebbe ancora nascere qualcosa di buono.",
  reward = "Dalla missione dell'High Order dipende la sopravvivenza del nostro popolo. Teniamo nella massima stima i nostri benefattori elementali, ma dobbiamo guardare in faccia la realtà; ora non ci sono più, e siamo soli.$B$BFra minacce interne come gli Al'Aketh e le incertezze sulla nostra sicurezza su questo piano, il nostro destino, in quanto discendenti Highborne della nostra antica patria di Eldre'Thalas, è usare i nostri doni perché gli shen'dorei tornino a reggersi sulle proprie gambe.",
}
T[92597] = {
  title = "Leggere le Linee di Forza",
  desc = "Qui nel piano elementale traiamo gran parte del nostro potere arcano dalle linee di forza che scorrono ancora nel terreno sotto i nostri piedi. Di recente queste linee hanno cominciato ad affiorare, offrendoci un accesso più diretto e potente alle loro energie arcane latenti.$B$BVai ai menhir a nordest. Lì c'è una linea di forza. Ricorri al potere che hai dalla nascita e assorbi l'energia della linea.",
  obj = "Usa la tua abilità razziale Read Ley Line presso la linea di forza in Thendal Grove.",
  progress = "La nostra unica via di salvezza è sviluppare appieno le capacità che ci spettano in quanto figli e figlie degli alti nobili. I Windshapers non sono molto meglio degli Al'Aketh: si prostrano davanti a creature ultraterrene a cui non importa nulla di loro.",
  reward = "Lo senti? Sì? Bene! Hai mosso i primi passi. Scoprirai che, con le tue capacità, potrai attingere all'energia magica latente in molti luoghi. Farlo ti porterà un'infinità di benefici, alcuni profondi, altri più sottili. Non saprai quali finché non lo farai, ma è questo il bello del dono... rendere noto l'ignoto.$B$BSe vogliamo sopravvivere a questi tempi terribili, dobbiamo essere incrollabili nella ricerca della conoscenza... e del potere.",
}
T[92598] = {
  title = "Il Dono della Vista Celeste",
  desc = "In quanto Modellavento, puoi usare la sacra vista celeste che gli spiriti elementali ci hanno donato. Raggiungi i menhir a nordest del villaggio. Trova la convergenza elementale che c'è lì e usa il tuo dono.$B$BScoprirai che puoi ricorrere alla vista celeste ovunque, ma vicino a una convergenza il beneficio che ne trai è molto maggiore. A volte potresti anche ricevere qualche altra perla di saggezza dagli spiriti attirati da quei luoghi di potere.",
  obj = "Usa la tua abilità razziale Skysight presso Elemental Convergence in Thendal Grove.",
  progress = "Il dono della vista celeste ti offrirà un grande beneficio. Usalo con saggezza.",
  reward = "Come un muscolo, la vista celeste va esercitata, se speri di padroneggiare sempre meglio il dono. Sfruttarla per colmare la distanza tra il mondo dei mortali e quello degli spiriti potrebbe rivelarsi preziosissimo nelle tue avventure.$B$BFaresti bene a ricordare ciò che hai imparato qui oggi. La capacità di usare i nostri doni per ascoltare la voce degli elementi potrebbe essere la chiave della nostra sopravvivenza.",
}
T[92640] = {
  title = "Tempi Disperati",
  desc = "Visto che non possiamo affrontare il culto in campo aperto, conviene approfittare di questa occasione per attaccare il santuario stesso. Possiamo togliere di mezzo Lorthuna in persona prima che porti a termine la sua parte del complotto.$B$BGuarda caso, Valennia prepara da tempo una strategia per un eventuale assalto al Santuario. L'unico problema è che ci servirà aiuto.$B$BParla con Valennia per i dettagli.",
  obj = "Parla con Valennia Stormfist a Valanaar e segui le sue istruzioni.",
  reward = "In questo momento fra i Windshapers e l'High Order la tensione è alta, ma senza entrambi i gruppi dalla nostra parte non potremmo sperare di realizzare questo piano.",
}
T[92642] = {
  title = "Sabotare la Logistica",
  desc = "Valennia ha mandato una sola persona ad aiutarci a respingere un assalto in piena regola... per tutti i venti.$B$BNon sembri granché, ma mi accontento di quello che passa il convento. Dobbiamo colpirli il più duramente possibile per farla finita presto. La mia gente non resisterà ancora a lungo.$B$BScendi dalla collina e sabota la loro logistica. Sono i guaritori a rimandare all'attacco gli assalitori: se li eliminiamo, forse riusciremo a riorganizzarci e a respingerli. E già che sei là fuori, uccidere altri cultisti ci sarà d'aiuto.",
  obj = "Uccidi 4 Al'Aketh Healers e 8 Al'Aketh Brawlers nelle Gustberry Lowlands.",
  reward = "Sei ancora $Gvivo:viva;? Ringraziamo i venti per questo piccolo miracolo, direi.",
}
T[92643] = {
  title = "Il Voltagabbana",
  desc = "Fra gli Al'Aketh c'è un voltagabbana. Dice di sapere che cosa ha davvero in mente il culto per l'isola e vuole consegnarsi, ma solo se avrà la garanzia di essere protetto.$B$BIl disertore si nasconde in una casa isolata sugli altopiani, appena a nord-ovest di Valanaar. Mi serve qualcuno che vada lì con discrezione, trovi il traditore e lo scorti fino a noi. Potrebbe essere una trappola, ma se le sue informazioni sono importanti come sostiene lui, vale la pena correre qualche rischio.",
  obj = "Trova il cultista voltagabbana nella casa all'inizio degli altopiani, a nord-ovest di Valanaar.",
  reward = "<Non c'è dubbio che l'uomo sia morto: l'hanno ucciso gli assassini che hai affrontato fuori dalla casa. Mentre ti inginocchi per esaminare il corpo, noti il riflesso di qualcosa che luccica...>",
}
T[92644] = {
  title = "Brutte Notizie",
  desc = "<Infili la mano sotto il corpo ancora caldo del cultista voltagabbana e ne tiri fuori un piccolo cristallo blu luminoso. Sembra danneggiato, ma potrebbe comunque essere importante. Forse interesserà a High Elder Shadowsong.>",
  obj = "Consegna il cristallo luminoso a Talanaanis Shadowsong a Valanaar.",
  progress = "Sei $Gtornato:tornata;? E... $Gsolo:sola;?",
  reward = "Dici che il voltagabbana era già morto quando sei $Garrivato:arrivata;? Brutta notizia.$B$B<Consegni il cristallo che hai trovato sul corpo del dead cultist.>$B$BInteressante...",
}
T[92645] = {
  title = "Frantumare la Frantumatrice",
  desc = "Sarà difficile respingere questo attacco, a meno di eliminare la comandante del culto. Belguilos \"la Frantumatrice\", la chiamano, ed è un vero flagello. Prima che il culto sfuggisse di mano faceva la peacekeeper, e già allora era... strana. Ora che è una cultista, posso solo immaginare quanto possa essere peggiorata.$B$BForse ti sto mandando dritto alla morte, ma se vogliamo sopravvivere, qui, qualcuno deve togliere di mezzo Belguilos. La troverai alla villa ai piedi della collina. Buona fortuna, $C.",
  obj = "Uccidi Commander Belguilos nelle Gustberry Lowlands.",
  reward = "Belguilos è morta? Che i quattro venti ti benedicano, $C. $B$BForse ne usciremo vivi, dopotutto.",
}
T[92646] = {
  title = "Affronta Lorthuna",
  desc = "Pochi istanti fa Lorthuna è fuggita fino alle guglie sopra di noi attraverso una specie di portale, e Ayessa ed Elaadrin le sono andati dietro.$B$BTemo di aver preso un colpo di troppo: io mi fermo qui. Attraversa il portale, trova Ayessa e aiutali a fermare Lorthuna.$B$BElaadrin e Ayessa hanno detto di aver mandato a chiamare aiuto, ma se non arriva presto, da qui in poi sei $Gsolo:sola;. Buona fortuna, $C.",
  obj = "Prendi il portale per Rohashi Spires sopra di te e unisciti a Elaadrin Evengale e Ayessa Dawnsinger nello scontro con High Priestess Lorthuna.",
  reward = "Ho mandato alcuni dei nostri guaritori a fare in modo che Valennia e le forze che le restano tornassero sane e salve. Adesso dovrebbe riposare nella residenza del Sommo Anziano.$B$BMuln è già ripartito per Azeroth, ma io e lui abbiamo parlato di cosa attende i Windshapers e della nostra missione su Azeroth. Purtroppo l'isola ora è più vulnerabile che mai, e ci serve un piano per difendere Zephras da quello che sta per arrivare.",
}
T[92679] = {
  title = "Decima di Sangue",
  desc = "Sa — Salve, $Gstraniero:straniera;. Hai tutta l'aria di $Gun avventuriero:un'avventuriera; capace. Io...$B$B<L'uomo Skyborne fa una smorfia, chiaramente in preda a un dolore terribile>$B$B...mi chiedevo se per caso cercassi lavoro? Sono venuto qui a Valanaar per reclutare combattenti che mi aiutino a salvare la mia fattoria. Se ti interessa, ti prego, raggiungi mia moglie Aamelia Windfield al nostro frutteto, nelle pianure a ovest di Valanaar.",
  obj = "Ascolta cosa ha da dire Alvarion Windfield e trova Aamelia Windfield a Windfield Orchard.",
  progress = "Cosa? Alvarion è vivo?",
  reward = "<Aamelia ascolta mentre le spieghi che fine ha fatto Alvarion.>$B$BAlmeno so che a Valanaar sarà al sicuro.$B$B$GStraniero:Straniera;, mi dispiace dirtelo, ma credo che quell'idiota di mio marito ti abbia mandato qui a morire per niente. Se hai un minimo di buon senso, dovresti andartene subito. Non è la tua battaglia.",
}
T[92682] = {
  title = "Renditi Utile",
  desc = "Oh, quindi hai più coraggio che buon senso, eh? Va bene, non discuto.$B$BFerauu e i suoi scagnozzi non verranno a ritirare la loro parte del raccolto ancora per un po', quindi nel frattempo ti farò lavorare in cambio dei pasti.$B$BEsci e raccoglimi le mele della tempesta che servono per oggi. Ah, e i banditi che si aggirano intorno agli alberi... Credono di essere furtivi. Non lo sono. Fammeli fuori. $B$BVediamo cosa sai fare in combattimento.",
  obj = "Raccogli 10 Ripe Stormapples e uccidi 5 Hungry Bandits a Windfield Orchard.",
  progress = "Questi banditi tendono più a tradirsi e derubarsi a vicenda che a rapinare la gente comune. Scommetto che se Ferauu sapesse che alcuni dei suoi hanno fatto di testa loro e sono venuti qui in anticipo per mettere le mani sul raccolto, li ucciderebbe con le sue mani.",
  reward = "Dalla finestra ti ho visto abbattere quei banditi. Niente male.",
}
T[92683] = {
  title = "Flutterfly Dust",
  desc = "Li avrai notati di certo, i flutterflies giganti là fuori, nei campi più lontani vicino al frutteto? Sono belli da vedere, ma hanno anche altri pregi: la polvere delle ali, per la precisione. Sporca parecchio, però se riesci a raccoglierne tanta, in casa fa comodo.$B$BPrendi questo Flutterfly Swatter e dai una bella botta a quei grossi insetti per me. Di solito si spaventano e scappano, ma ogni tanto se la prendono un po'. Comunque vada, scuoteranno il sedere e lasceranno cadere un mucchio di polvere.",
  obj = "Raccogli 5 Flutterfly Dust dai Flutterflies nei Gustberry Lowlands.",
  progress = "Di solito i Flutterflies sono docili e tranquilli, ma se li prendi per il verso sbagliato ogni tanto ti sorprendono.",
  reward = "Questa roba sporca un po' e ha il vizio di finire dappertutto: probabilmente te la scuoterai dai pantaloni per settimane, purtroppo. Però ti sono davvero grata. Ce l'avevo nella lista delle cose da fare da settimane, ma allontanarmi troppo da casa è un grosso rischio, qui tutta da sola con i banditi in agguato ovunque.$B$BNon chiedermi a cosa mi serve questa roba. Cose. Roba e cose. Non preoccupartene.",
}
T[92684] = {
  title = "Ornery Galestriders",
  desc = "Come se il raccolto di quest'anno non fosse già abbastanza scarso, ci si mettono pure i galestriders della zona, che si intrufolano nel frutteto a rubarmi le mele della tempesta. Te la senti di andare nei campi a sfoltirli per me?$B$BMa attenzione, $Gstraniero:straniera;: i galestriders dei bassopiani sono più grossi e più rabbiosi di quelli degli altopiani. Stai in guardia, perché se ti distrai basta un calcio ben assestato a stenderti per sempre.$B$BPortami un po' della loro carne: così ne viene fuori anche un pasto caldo per tutti e due.",
  obj = "Raccogli 7 Lowlands Galestrider Tenderloins dagli Ornery Galestriders nei Gustberry Lowlands.",
  progress = "Non ceno con della carne vera da... beh, da troppo tempo, credo.",
  reward = "Che filetti grossi! Là fuori devi aver abbattuto dei veri mostri.",
}
T[92685] = {
  title = "Le Colline Hanno gli Occhi",
  desc = "I banditi hanno accampamenti dappertutto, e uno piccolo sta sulle colline appena a nord di qui. Sali lassù e comincia a spaccare crani. Se riusciamo a coglierli alla sprovvista e a farli fuori prima che vengano loro a prenderci, potremmo riequilibrare le sorti quanto basta per avere una possibilità.$B$BPortami le loro maschere: più sono insanguinate, meglio è.",
  obj = "Recupera 7 Blood-Stained Bandit Masks da Highwayman Bandits nei Gustberry Lowlands.",
  progress = "Se riesci a portarmi abbastanza maschere da bandito, magari ci cucio una coperta e la regalo a Ferauu.$B$B<Aamelia ride fragorosamente.>",
  reward = "Quando ho detto più insanguinate meglio è, mi hai dato proprio retta. Bene: vuol dire che li hai fatti soffrire.$B$BScherzi a parte, grazie per tutto quello che hai fatto finora. Sono settimane che fluttuo senza meta per questa fattoria, come se aspettassi solo la fine. Credo di stare ricominciando a sperare.$B$BFerauu e i suoi scagnozzi arriveranno da un momento all'altro, e non resta che uscire ad affrontarli. Che ne dici, vieni con me fino in fondo?",
}
T[92693] = {
  title = "Mantenere la Posizione",
  desc = "Hai fatto tanto per darci una possibilità di farcela. Se oggi moriremo, sapremo almeno di averci provato con tutte le nostre forze.$B$BQuesta è la tua ultima occasione, $Gstraniero:straniera;. Se vuoi tornare a Valanaar e metterti in salvo, non te ne farei una colpa.$B$BSe invece hai proprio un debole per le cause perse, dimmi quando sei $Gpronto:pronta; a partire. Usciremo là fuori a testa alta, e sarà quel che sarà.",
  obj = "Parla con Aamelia Windfield quando sei $Gpronto:pronta; ad affrontare il capo dei banditi.",
  progress = "In tutta Skywall non ci sono abbastanza mele della tempesta per ripagarti di questo.",
  reward = "Io... non riesco a credere che sia finita. Devo fermarmi un momento a calmarmi, o il cuore mi salterà fuori dal petto.",
}
T[92698] = {
  title = "Qual È il Mio Scopo?",
  desc = "<Ti avvicini per cercare di sentire le parole che provengono da sotto le placche corazzate del gigantesco costrutto.>$B$B...Errore di funzione...$B$B...Domanda...$B$B...Qual è....$B$B...Funzione...$B$B<Queste parole e frasi frammentate sembrano ripetersi all'infinito. Forse qualcuno nei dintorni sa qualcosa di più su questo costrutto?>",
  obj = "Parla con Aamelia Windfield del Malfunctioning Cyclone Construct.",
  reward = "Il costrutto? Vaga per i campi da decenni. Da quando gli elementali del vento se ne sono andati, credo. Alvarion sospettava che un tempo trasportasse i raccolti al mercato, o che magari badasse al bestiame, prima che qui ci fosse un frutteto. Ma può darsi che sia stato mille anni fa.$B$BAnticamente erano i Windshapers a occuparsi della manutenzione di questi costrutti. Abbiamo pensato di chiedere loro di venire a dargli un'occhiata, ma non ci è mai sembrata una cosa urgente. Ormai perlopiù non ci facciamo nemmeno caso.",
}
T[92699] = {
  title = "Il Magister Supremo",
  desc = "Ora che sei $Garrivato:arrivata; a Valanaar, ti conviene presentarti agli altri membri dell'High Order che si trovano qui. L'attuale Magister Supremo, Elaadrin Evengale, si è stabilito con i suoi nella loggia all'estremità sud-orientale di Valanaar.$B$BE fa' attenzione: qui l'High Order e i Windshapers non vanno molto d'accordo. Sii prudente e sta' alla larga dai Windshapers. Il culto ci dà già abbastanza pensieri: non tollererò scontri tra fazioni per le strade di Valanaar.",
  obj = "Trova Elaadrin Evengale a Valanaar.",
  reward = "Salve, e $Gbenvenuto:benvenuta;. Rathiril mi ha parlato di te in un messaggio magico, e dice che sei promettente.$B$BOra che ti ho davanti, capisco perché ti ha consigliato di cercarmi. Emani un'aura arcana vibrante. Ormai sono ben pochi quelli di noi che hanno il talento, per non parlare della volontà, di fare ciò che serve per salvare la nostra casa. Hai il coraggio e la forza necessari per aiutare l'High Order?$B$BImmagino che lo scopriremo.",
}
T[92700] = {
  title = "La Grande Veggente del Cielo",
  desc = "Ora che sei $Garrivato:arrivata; a Valanaar, vorrai probabilmente presentarti agli altri Windshapers che si trovano qui. L'attuale Grande Veggente del Cielo e la sua gente hanno la loro base nella loggia vicino al centro di Valanaar.$B$BDevi anche sapere che da queste parti i Windshapers e l'High Order non vanno molto d'accordo. Stai $Gattento:attenta; e tieniti ben alla larga dall'High Order. Il culto ci dà già abbastanza pensieri: nelle strade di Valanaar non tollererò violenze fra fazioni.",
  obj = "Trova Ayessa Dawnsinger a Valanaar.",
  reward = "L'Anziano Amberwind mi ha fatto sapere di te e delle tue imprese a Shen'dar Village. Qui sei davvero $Gil benvenuto:la benvenuta;, $Gamico:amica;.$B$BHai un'aura potente, e si vede che sei in sintonia con gli spiriti. Ultimamente sono sempre meno quelli di noi che possiedono la vista celeste, e se vogliamo sopravvivere a questi tempi difficili Zephras ha bisogno di chi ha questo dono. Sono lieta che tu abbia trovato la strada fino a me.$B$BNon vedo l'ora di conoscerti meglio.",
}
T[92701] = {
  title = "Verso Valanaar",
  desc = "Per ora il pilone e il villaggio sembrano al sicuro, quindi vorrei che consegnassi questo rapporto a Valennia Stormfist, a Valanaar, all'estremità sud-orientale dell'isola. Valennia guida i peacekeepers dell'isola e deve sapere cos'è successo qui.$B$BIl culto si diffonde in fretta e finora i peacekeepers hanno evitato lo scontro diretto, ma quel tempo è finito: Valanaar dovrà essere pronta a combattere.$B$BComunque, grazie. A Shen'dar avrai sempre degli amici, $N.",
  obj = "Consegna l'Aonda's Written Report a Valennia Stormfist a Valanaar.",
  progress = "Una lettera di Aonda. Cos'ha combinato, quella furba montanara?",
  reward = "<Il volto di Valennia si incupisce mentre legge la lettera.>$B$BAonda ti ha affidato questa lettera e qui scrive abbastanza bene di te, perciò proverò a fidarmi anch'io. Prima di riprendere il discorso devo consultarmi con i pochi peacekeepers che mi sono rimasti e preparare un piano, nel caso la prossima volta il culto colpisca qui. Intanto goditi il soggiorno a Valanaar.$B$BSe cerchi qualcosa da fare, a molti abitanti del villaggio servirebbe probabilmente l'aiuto di $Gun giovane e forte avventuriero:una giovane e forte avventuriera; come te.",
}
T[92703] = {
  title = "Porta la Notizia",
  desc = "Dopo tutto questo non mi sembra giusto chiamarti ancora $Gstraniero:straniera;, quindi... grazie, $N.$B$BSe non ti disturba e passi da quelle parti, ti prego, racconta ad Alvarion cos'è successo qui. E digli anche che, appena si sarà rimesso in piedi, deve portare qui un modellatore del vento che esamini il costrutto e si accerti che non sia pericoloso tenerlo vicino alla nostra... alla nostra famiglia.$B$B<Aamelia si tocca dolcemente la pancia.>$B$BLui di questo non sa niente. Per ora teniamolo fra noi.",
  obj = "Parla con Alvarion Windfield a Valanaar.",
  reward = "<Gli occhi di Alvarion si riempiono di lacrime mentre finisci di raccontargli cos'è successo al frutteto.>$B$BNon so come ringraziarti, $Gamico:amica;. Sono venuto a Valanaar a cercare speranza. Una speranza vana, ne ero quasi certo. E invece ho trovato $Gun eroe:un'eroina;. $GUn vero eroe:Una vera eroina;, come nelle storie di prima che arrivassimo a Skywall.$B$BNon dimenticherò mai quello che hai fatto per noi, $N. A casa dei Windfield sarai sempre $Gil benvenuto:la benvenuta;.",
}
T[92706] = {
  title = "RICERCATO: Bruuz",
  desc = "A tutti i pescatori!$B$BNelle acque vicino al molo di carico si aggira uno squalo gigante che attacca i marinai e le piccole imbarcazioni. Gli scaricatori del porto l'hanno soprannominato \"Bruuz\". Chi mi porta la sua pinna avrà una bella ricompensa!$B$B— Gazlowe",
  obj = "Porta la Bruuz's Dorsal Fin a Gazlowe a Ratchet.",
  progress = "Cosa posso fare per te, skyborne?",
  reward = "Finalmente qualcuno ha ucciso quella cosa! Hai idea di quanto sia difficile mettere in acqua una ciurma, quando in città non fanno che gridare \"Squalo!\"?$B$BMagari stasera a cena ci metto la pinna di quel mostro, nella zuppa, giusto per ridere io per ultimo.",
}
T[92707] = {
  title = "Il Gigante in The Den",
  desc = "I bracciali strappati all'enorme cadavere del golia sono massicci: ci passa tutto il braccio fino alla spalla senza toccare i bordi.$B$BDovresti riportarli a Hammerfall come avvertimento. Drum Fel dovrebbe sapere a cosa va incontro.",
  obj = "Porta i Goliath's Wristguards a Drum Fel a Hammerfall.",
}
T[92708] = {
  title = "Una Grande Avventura",
  desc = "I Windshapers si stanno dando molto da fare per far fronte alla crisi che ha colpito Zephras Isle. Mentre cercavamo gli spiriti del vento scomparsi abbiamo fatto diverse scoperte sorprendenti, e ora stiamo preparando un piano che potrebbe darci i mezzi per salvare l'isola.$B$BPerché funzioni, però, ci serviranno giovani avventurieri forti come te. Se hai un momento, ti prego, parliamone ancora un po'.",
  obj = "Ascolta cosa ha da dire Ayessa Dawnsinger.",
  reward = "Ora capisci? Fuori da Skywall c'è un mondo di conoscenze e di potenzialità mai sfruttate. Questa resterà sempre la nostra casa, ma mi sono convinta che la strada della nostra salvezza porti in basso. Dobbiamo andare su Azeroth a procurarci il potere e i mezzi per salvare Zephras Isle. È questa la via.$B$BQuando sarà il momento, avrai il coraggio di unirti a noi?",
}
T[92709] = {
  title = "Una Grande Avventura",
  desc = "Il tuo lignaggio highborne ti risplende negli occhi, chiaro come il cielo sopra di noi. Sei $Guno:una; di noi, ed è grazie a giovani come te che salveremo la nostra casa. Ma prima lascia che ti parli meglio della missione e dei piani che abbiamo qui su Zephras... e oltre.",
  obj = "Ascolta ciò che ha da dire Elaadrin Evengale a Valanaar.",
  reward = "Allora, ora capisci? Riscoprire l'antica magia dei nostri antenati è essenziale per svelare i segreti di Zephras Isle e assicurarci un futuro, ma per salvare la nostra casa dobbiamo ritrovare ciò che abbiamo perduto in questi ultimi millenni.$B$BLa chiave è Azeroth. Il Kirin Tor ci indicherà la via.$B$BMentre ci prepariamo a partire, dovresti presentarti agli altri membri dell'High Order qui a Valanaar. Quasi tutti hanno qualche compito da portare a termine, e l'aiuto di qualcuno come te farebbe loro comodo.",
}
T[92727] = {
  title = "Lo Studioso Scomparso",
  desc = "La ricerca della conoscenza è il compito principale dell'High Order, ma su Zephras questo lavoro non è mai stato pericoloso come adesso.$B$BUno dei nostri studiosi — Fillion Flamebreeze — era partito per gli Shen'dar Highlands a raccogliere dati sulla magia portata dal vento, che in alcune zone della regione si concentra. Purtroppo non è tornato, e temiamo che gli sia capitato qualcosa per strada.$B$BSe puoi, ti prego, ritrovalo per noi. L'ultima volta è stato visto sulla strada che da Valanaar va a ovest, verso gli Shen'dar Highlands.",
  obj = "Scopri che fine ha fatto Fillion Flamebreeze.",
  reward = "<Sul lembo della borsa a tracolla che giace davanti a te ci sono alcune macchioline di quello che sembra sangue secco. Esaminando la macchia, ti accorgi che sul lembo è ricamato anche un nome. C'è scritto: \"Fillion Flamebreeze\".>",
}
T[92741] = {
  title = "Visitatori Sgraditi",
  desc = "La Shadowgale Forest è estremamente pericolosa e di solito è vietata ai comuni avventurieri. Negli ultimi mesi gli shriekling si sono moltiplicati a dismisura e hanno cominciato ad allargare il loro territorio fuori dal bosco, cosa che potrebbe diventare un problema. Le proprietà alchemiche degli shriekling talons mi interessano, per cui uno sfoltimento quanto mai necessario è anche l'occasione per far avanzare gli studi.$B$BRecati nella Shadowgale Forest e da' la caccia a quelle bestie. Portami quanti più artigli puoi.",
  obj = "Recati nella Shadowgale Forest e raccogli 8 Shriekling Talons per Iaadaria Bitterwind a Valanaar.",
  progress = "Non è abitudine dell'High Order fare da semplici cacciatori e guardiacaccia, ma quando un servizio come questo può far progredire gli studi, siamo lieti di renderci utili alla comunità.",
  reward = "Che bel bottino di artigli mi hai portato. Non vedo l'ora di metterci le mani!$B$BGrazie per i servigi resi all'High Order, $C.",
}
T[92742] = {
  title = "Analisi dei Pozzi",
  desc = "Dobbiamo scoprire da dove viene il veleno che sta corrompendo questa terra, e di che natura sia. Cominciamo dalle acque sotterranee delle fattorie qui intorno.$B$BVa' al Jansen Stead, a nord, e alla Molsen Farm, a nord-ovest di qui, e raccogli dei campioni dai loro pozzi.",
  obj = "Usa il Well Water Sample Kit per raccogliere dei campioni dai pozzi del Jansen Stead e della Molsen Farm.",
  progress = "Hai raccolto i campioni?",
  reward = "Grazie. Vediamo un po'...",
}
T[92743] = {
  title = "Un Conqueror's Crown",
  desc = "Siamo il clan di centauri più forte di tutta la terra, e meritiamo armi feroci quanto noi siamo forti!$B$BA Warug ne serve una più che a chiunque altro. Una corona... no, un elmo! Un conqueror's crown! Ho sentito leggende su un temibile conquistatore al di là dei mari. Va' in un posto che chiamano Badlands e cerca una cripta, laggiù. Torna da me solo quando avrai trovato l'elmo.$B$BFallo per me, e ti svelerò la più grande forza dei Magram.",
  obj = "Mantieni la tua reputazione con i Magram e porta un Conqueror's Crown da Badlands a Warug a Magram Village.",
  progress = "Niente elmo, niente chiacchiere!",
  reward = "Guarda qui! Guardalo! Che elmo! Degno di un Khan... ma a portarlo sarà Warug. Sono contento.$B$BSei $Gpronto:pronta; a imparare la nuova arma dei Magram contro i nostri nemici?",
}
T[92744] = {
  title = "Branchie di Murloc",
  desc = "La corruzione che colpisce i raccolti di Westfall potrebbe essere filtrata anche nell'oceano. Se pure i pesci della zona sono contaminati, Stormwind potrebbe essere condannata alla carestia.$BVa' lungo la costa, raccogli le branchie dei murlocs e portamele. I Murlocs sono piuttosto resistenti, ma il loro organismo è estremamente sensibile alle sostanze contaminanti: qualunque tossina ci sia nell'acqua di mare, nelle branchie che troverai si vedrà subito.",
  obj = "Alba Fairmoon vuole che tu raccolga 7 Longshore Murloc Gills lungo la costa di Westfall.",
  progress = "Nessun problema con i murlocs, spero?",
  reward = "Capisco... per ora queste branchie sembrano sane. Ma non dobbiamo abbassare la guardia.",
}
T[92745] = {
  title = "Lo Stato delle Miniere",
  desc = "Nei campioni che hai preso dai pozzi ci sono metalli tossici! Se non fermiamo presto questa corruzione, passeranno decenni prima che su questa terra tornino a crescere i raccolti.$BI Defias si sono impadroniti delle miniere di Westfall e ne saccheggiano le risorse facendo lavorare delle creature. Ostacolali: uccidi i loro minatori nella Jangolode Mine, a nord, e nella Gold Coast Quarry, a ovest.",
  obj = "Uccidi 4 Kobold Diggers nella Jangolode Mine e 6 Riverpaw Miners nella Gold Coast Quarry.",
  progress = "Che notizie porti dalle miniere?",
  reward = "Ben fatto, $N. Temo però che il veleno abbia origine da qualche altra parte...",
}
T[92747] = {
  title = "Spionaggio a Moonbrook",
  desc = "Strano — il veleno non sembra venire dalle miniere che hai esaminato.$B$BMi hanno detto che le Deadmines, sotto il villaggio di Moonbrook, sono le miniere più grandi e profonde di Westfall, ma che sono abbandonate dai tempi della First War. Possibile che le Deadmines siano tornate in funzione?$B$BVa' a Moonbrook, $N, ti prego, e cerca prove di attività minerarie o industriali. È l'ultima pista che ci resta!",
  obj = "Raccogli 8 Suspicious Industrial Supplies a Moonbrook.",
  progress = "Hai trovato qualcosa?",
  reward = "Che cos'è tutto questo?",
}
T[92748] = {
  title = "Consulenza Esplosiva",
  desc = "Le forniture che hai trovato indicano un'enorme attività industriale, da qualche parte nelle Deadmines: le tossine che affliggono i campi di Westfall vengono senza dubbio da lì. Dobbiamo fermarla, e in fretta.$B$BQualunque cosa ci sia laggiù, non sarà facile distruggerla. Va' al Dwarven District of Stormwind e trova un ingegnere che possa procurarci degli esplosivi.",
  obj = "Vai al Dwarven District a Stormwind e trova un ingegnere che possa aiutarti.",
  reward = "Devi far saltare in aria qualcosa?",
}
T[92749] = {
  title = "Un Piano Esplosivo",
  desc = "Un sabotaggio industriale? Mi interessa!$BPartiamo da un po' di dinamite...",
  obj = "Ottieni 10 Rough Dynamite tramite creazione, scambi o la casa d'aste, poi torna da Sprite Jumpsprocket nel Dwarven District of Stormwind.",
  progress = "Fammi vedere quegli esplosivi, $N!",
  reward = "Ottimo inizio! Adesso si tratta di mettere insieme tutto... e aggiungerci un pizzico di pepe in più...",
}
T[92750] = {
  title = "Detonazione a Distanza",
  desc = "Vuoi un'esplosione \"controllata\", immagino? Meno divertente, certo, ma è una buona scelta se ci tieni a conservare tutti gli arti.$BUn detonatore a distanza, temo, non ce l'ho — perché non vai a chiederlo a quei tipi furtivi giù ai Servizi Segreti di Stormwind? Loro dovrebbero riuscire a trovarci qualcosa.",
  obj = "Parla con qualcuno dei Servizi Segreti di Stormwind per procurarti un detonatore a distanza.",
  reward = "Mmm... Cerchi qualcosa di particolare, eh?",
}
T[92751] = {
  title = "Detonazione a Distanza",
  desc = "Devi distruggere qualcosa? C'entrano per caso le tue faccende a Moonbrook? Non fare $Gil sorpreso:la sorpresa;. Al SI:7 non sfugge niente di quello che succede nelle terre di Stormwind.$B$BSe hai in mente di far saltare in aria qualcosa nelle grotte sotto Westfall, ti conviene trovarti già ben fuori. Prendi questo detonatore a distanza — è un prototipo che i nostri ingegneri hanno messo a punto da poco.$B$BOh — e meglio non dire al tuo amico elfo che ci sono di mezzo anch'io.",
  obj = "Porta il Remote Detonator Kit a Sprite Jumpsprocket nel Dwarven District of Stormwind.",
  progress = "Hai preso un detonatore a distanza? Uno normale non va proprio bene!",
  reward = "Ottimo — è proprio quello che ci serve!",
}
T[92752] = {
  title = "Consulenza Esplosiva",
  desc = "Ecco qua — la bomba è pronta! E mi raccomando, $Gattento:attenta; al detonatore.",
  obj = "Torna da Alba Fairmoon a Westfall.",
  progress = "Hanno dato frutto i tuoi sforzi a Stormwind?",
  reward = "Sono felice che tu sia $Gtornato:tornata;, $N.",
}
T[92753] = {
  title = "Distruzione nelle Deadmines",
  desc = "La fonte del veleno sarà probabilmente una specie di grande forgia metallurgica. Trova un modo per entrare nelle Deadmines e individua la forgia, poi piazza gli esplosivi.$BTi aspetterò sulle colline dietro Moonbrook. Al tuo ritorno potremo farli esplodere. Distrutta la forgia, speriamo che la terra cominci a guarire.",
  obj = "Trova la forgia nascosta in Deadmines e piazza gli Extra-Destructive Explosives lì vicino. Poi raggiungi Alba Fairmoon all'uscita di Deadmines.",
  reward = "Dunque hai trovato la forgia e piazzato la bomba... resta solo una cosa da fare.",
}
T[92754] = {
  title = "Un Nuovo Bisogno di Protezione dall'Ombra",
  desc = "I nostri compagni di clan si spingono sempre più a sud, fino alla maledetta Valley of Bones e oltre.$B$BNonostante la tua reputazione presso il nostro clan, non mi fido di te al punto da raccontarti i dettagli delle loro spedizioni. Tanto ti annoierebbero, $Gstraniero:straniera;.$B$BQuello che ti riguarda è questo: per tenerli in vita ci servono Greater Shadow Protection Potions in grandi quantità. Portamene un po' e metterò una buona parola per te.",
  obj = "Mantieni la tua reputazione con i Magram e porta 3 Greater Shadow Protection Potions a Mirda a Magram Village, in Desolace.",
}
T[92755] = {
  title = "Misticismo Misterioso",
  desc = "Giorno dopo giorno, i nostri saccheggiatori tornano con sempre meno armamenti tolti agli avventurieri caduti.$B$BCosì come sono, questi pezzi non ci servono, ma li recuperiamo per ricavarne materiale. A me vanno quelli più magici, perché posso disincantarli e usarne i misteriosi residui per incantare le nostre armi, soprattutto quelle degli inseguivento.$B$BSe voglio dare al prossimo gruppo di razziatori un equipaggiamento che valga qualcosa, ho bisogno di Greater Mystic Essences.",
  obj = "Mantieni la tua reputazione con i Gelkis e porta 3 Greater Mystic Essences a Halea in Gelkis Village, a Desolace.",
}
T[92811] = {
  title = "Guerra Economica",
  progress = "Se la guerra ci ha insegnato una cosa, è questa: il denaro è potere.$B$BTutti i centauri di Desolace si sono accordati per commerciare con legno finemente intagliato, che racconta la gloria e le conquiste di ciascuno di loro. È l'unica tregua dalla battaglia, e solo ai più assennati è permesso trattare con gli altri clan.$B$BHo visto quelli della tua specie commerciare in oro e argento. Per noi non valgono niente, come per voi i nostri totem. Portamene un po' e il Clan Magram ne sarà contento.",
  reward = "Saggia decisione, $Gstraniero:straniera;. La tua generosità non passerà inosservata.",
}
T[92812] = {
  title = "Guerra Economica",
  progress = "Molto tempo fa tutti i clan dei centauri di Desolace si sono accordati per commerciare in storie: per la precisione, in totem intagliati che rappresentano le grandi imprese di un singolo o di un clan. Il conflitto non finisce mai, eppure tutti i clan rispettano ancora questa tradizione, anche se fra noi si commercia sempre più di rado.$B$BSe ne raccogli qualcuno, magari dai centauri caduti degli altri clan, portameli. Ai Gelkis farebbe comodo più potere di scambio, e dirò al Khan che ci hai aiutato.",
  reward = "Li aggiungerò alla nostra collezione. Con quello che ci porti il nostro potere cresce, ma per avere la meglio sul Clan Magram la strada è ancora lunga.",
}
T[92814] = {
  title = "Mi Serve un Sarto",
  desc = "La mia compagna, Halea, deve assicurarsi che le nostre armi vengano potenziate con l'energia magica adatta.$B$BDi incantamenti non ci capisco proprio niente, ma il mio compito è tenere il villaggio ben rifornito ed equipaggiato, e so che Halea è spesso indietro con il lavoro — e non per colpa sua.$B$BVorrei regalarle qualche vestito semplice su cui esercitarsi. Vedo degli avventurieri che vagano fra le tempeste di sabbia con il viso coperto da semplici maschere: potresti procurarmene qualcuna?",
  obj = "Mantieni la tua reputazione con i Gelkis e porta una White Bandit Mask a Molkar in Gelkis Village, a Desolace.",
}
T[92817] = {
  title = "Tecnica del Cuoio",
  desc = "Convincere i miei compagni di clan Gelkis a indossare un'armatura è quasi impossibile, nonostante le tante perdite che abbiamo subito per lame o dardi nel petto.$B$BMi hanno affidato il compito di progettare un corpetto che protegga in modo ragionevole, senza il presunto 'prurito' di cui si lamentano. Le scorte scarseggiano, e non oso sprecare cuoio prezioso per della robaccia.$B$B$GStraniero:Straniera;, mi porteresti un'imbracatura adatta a un centauro rozzo? Vorrei imparare dalla tua tecnica.",
  obj = "Mantieni la tua reputazione con i Gelkis e porta una Barbaric Harness a Talra in Gelkis Village, a Desolace.",
}
T[92818] = {
  title = "Grandi, Anzi, MASSIVE Iron Axes",
  desc = "SERVONO PIÙ ARMI.$B$BPIÙ. ARMI.$B$BSE NO, I MAGRAM COME LI SCHIACCIANO QUEI GELKIS GRACILI?$B$BFAMMI VEDERE COSA SAI FABBRICARE, $GSTRANIERO:STRANIERA;. PORTAMI DELLE ASCE. GRANDI, ANZI, MASSICCE.$B$BSBRIGATI.",
  obj = "Mantieni la tua reputazione con i Magram e porta 2 Massive Iron Axes a Grolkar in Magram Village, a Desolace.",
}
T[92819] = {
  title = "Distruzione nelle Deadmines",
  desc = "Ci siamo quasi. Usa il detonatore e metti fine a tutto questo.",
  obj = "Usa il detonatore.",
  reward = "Non so cosa dire, $N. Pensare che Stormwind abbia anteposto le ambizioni militari al sostentamento della sua gente...",
}
T[92834] = {
  title = "Vendicato Dieci Volte",
  desc = "Quando il culto ha cominciato la sua campagna di violenza, le Peacekeepers e i Windshapers hanno risposto mostrando i muscoli. A me è sembrata un'escalation sciocca, così mi sono battuto per un dialogo pacifico. Ieri ho mandato il mio amico Belathaan Brightwish allo Shrine of Akir, nella speranza di avviarlo.$B$BÈ appena arrivata una scatola: dentro c'era la lingua di Belathaan, intinta in un pigmento d'argento.$B$BOra ho capito che con il culto non si può ragionare. Uccidi tutti i cultisti che vedi e portami i talismani di preghiera che hanno con sé.",
  obj = "Raccogli 10 Al'Aketh Windstone Charms dai cultisti degli Al'Aketh che si trovano a nord di Valanaar, ai Gustberry Fields o allo Shrine of Akir.",
  progress = "Con i Windshapers mi trovo d'accordo di rado, ma avevano ragione a scartare l'idea di cercare un confronto pacifico con gli Al'Aketh. Ho tentato di scegliere la via più nobile e un caro amico ci ha rimesso la vita: è un errore con cui dovrò convivere per il resto dei miei giorni.",
  reward = "Noi dell'High Order andiamo fieri del nostro pragmatismo e della nostra logica, e la logica dice che nella maggior parte dei casi la scelta più prudente è evitare il conflitto e la perdita di vite.$B$B<Gli occhi di Elaadrin cominciano a brillare e a crepitare di energia arcana.>$B$B...tuttavia il culto ha scambiato la nostra prudenza per debolezza, e non è affatto pronto a pagare il prezzo di quell'errore.",
}
T[92840] = {
  title = "Catturare il Vento",
  desc = "Fillion era stato mandato alle Overlook Standing Stones con uno strumento speciale, per misurare e studiare l'energia elementale del luogo.$B$BPrendi questo — un Index Esoteria — e usalo per estrarre i dati dalle enormi formazioni di windstone che si trovano lì. Ma stai in guardia: ora i Windshapers sorveglieranno gelosamente il sito.$B$BSe qualcuno prova a ostacolarti, be'... fai quello che devi. Con le loro interferenze ho esaurito la pazienza.",
  obj = "Porta l'Index Esoteria alle Overlook Standing Stones negli Shen'dar Highlands e usalo sulle Formazioni di Windstone della zona per raccogliere dati.",
  progress = "Spesso faccio fatica a distinguere i Windshapers dagli Al'Aketh, se non per il fatto che uno dei due è più apertamente violento dell'altro. Schiavi entrambi delle loro convinzioni sbagliate, se li si lascia a se stessi sono pericolosi allo stesso modo.$B$BVedono il nostro desiderio di capire meglio questo regno e la sua magia come una profanazione delle loro tradizioni. È per la loro grettezza che la nostra missione è così importante: se non lo facciamo noi, chi avrà il coraggio di salvare Zephras?",
  reward = "Non avrei voluto versare sangue Windshaper, ma la colpa di questo conflitto inutile ricade soltanto sulle loro spalle. Noi cercavamo di raccogliere informazioni in pace, e loro hanno risposto con la violenza.$B$BPurtroppo la voce si è sparsa, e i Windshapers parlano già di 'massacro'. Qui a Valanaar non oserebbero vendicarsi, ma di certo non dimenticheranno.$B$B$N, sei $Gstato:stata; di enorme aiuto all'High Order. Grazie.",
}
T[92841] = {
  title = "Valley of Bones",
  desc = "È ora che tu sappia della nostra grande scoperta, $Gstraniero:straniera;... ma non sarà Warug a raccontartela!$B$BVa' a sud, dall'altra parte del villaggio, e cerca un centauro grosso e puzzolente: si chiama Orgrul.$B$BQuando sarai $Garrivato:arrivata;, lo saprai.$BQuando lo vedrai, lo saprai.$BSe pensa che meriti di sapere, saprai.$B$BE se non lo pensa? Be'. Potrai essere $Gcontento:contenta; di sapere che Warug ha una corona nuova.",
  obj = "Migliora la tua reputazione con i Magram e trova Orgrul vicino a Valley of Bones, a sud di Magram Village.",
  reward = "Allora è vero quello che si dice. Peccato che Warug ti abbia fatto correre di qua e di là per compiti futili, ma almeno hai dimostrato quanto vali.$B$BGuarda giù nella valle: cosa vedi? Ossa e cadaveri. Non morti che vagano. E i Twin Goliaths.$B$BQuesto posto era maledetto molto prima che arrivassimo noi, e ho il sospetto che lo resterà per molte generazioni ancora. Il nostro clan è stato il primo ad affrontare gli orrori di laggiù, e sarà l'unico a impadronirsi del suo potere.$B$BAnche tu, come me, non vedi l'ora di regnare su tutta Desolace?",
}
T[92844] = {
  title = "Montagna di Ossa",
  desc = "Non abbiamo ancora capito perché, ma una specie di energia negromantica si è diffusa in tutta la Valley of Bones.$B$BA noi però il perché non importa. Ora la magia è nostra, e chi non combatte con la lama o con il maglio lo addestriamo a questa nuova magia.$B$BSe credi che voglia farti cominciare con un compito impegnativo, ti sbagli. Per ora va' nella Valley of Bones e portami un po' di ossa: sono sicuro che sei in grado di farlo.",
  obj = "Mantieni la tua reputazione con i Magram e porta 426 Gently Cursed Bones a Orgrul, a sud di Magram Village, a Desolace.",
  progress = "Per ogni osso che manca, te ne prendo uno dei tuoi per pareggiare il conto.",
  reward = "<Orgrul comincia a contare le ossa, ma quando arriva alle due cifre salta qualche numero e alla fine perde il conto. Ci riprova, ma a metà ti lancia un'occhiataccia, perché lo stai guardando con una smorfia.>$B$BBah. Le conto dopo. Mi sembrano abbastanza. Vedi di non ingannarmi.$B$BQueste me le tengo io.",
}
T[92846] = {
  title = "Negromanti Reietti",
  desc = "Hai notato i centauri gracili che vanno in giro qui intorno pestando i piedi? Sono di stirpe Gelkis.$B$BNoi Magram ci siamo già stabiliti più in fondo al canyon. Quando i Gelkis si sono accorti che eravamo qui, alcuni di loro hanno deciso di seguire le nostre orme. Non so se vogliano unirsi a noi o tentare di rovesciarci, ma so che i loro compagni di clan li hanno esiliati tutti.$B$BSono lupi solitari che si immischiano in poteri che non sono loro. Li voglio morti.",
  obj = "Mantieni la tua reputazione con i Magram e uccidi Negromanti Reietti in Valley of Bones.",
  reward = "Buahaha, le loro urla le ho sentite fin da qui!$B$BI Gelkis dovrebbero imparare a massacrare i consanguinei che tradiscono le proprie origini. Se non lo fanno, tocca a noi fare pulizia al posto loro, e io non sono qui per sistemare i guai di un clan inferiore.$B$BSe ne vedi altri, assicurati di spegnergli la luce negli occhi. Gelkis una volta, Gelkis per sempre.",
}
T[92847] = {
  title = "Lacrime Corruttrici",
  desc = "$GStraniero:Straniera;, hai notato l'arma che avevano in mano i negromanti reietti? Faremo in modo che i Gelkis non vivano abbastanza da padroneggiare le vie della negromanzia, ma il modo in cui la incanalano ha attirato la mia attenzione. Usano perfino gli stessi cristalli che Warug ti ha chiesto di rubare.$B$BCredo che questa tecnica possiamo sfruttarla a nostro vantaggio. Avventurati di nuovo nella valle a prendere un po' di legno dagli alberi maledetti, e vedi se Warug è disposto a cedere qualcuno dei suoi cristalli. Ci farò dei bastoni.",
  obj = "Mantieni la tua reputazione con i Magram e riporta 3 pezzi di Petrified Bark e 3 Imbued Tears a Orgrul.",
  progress = "Questi bastoni potrebbero essere proprio il pezzo che ci manca per conquistare il resto della Valley of Bones. Ora va', $R: sfruttiamo le vie dei Gelkis prima che facciano la loro prossima scoperta.",
  reward = "Solo tre? Hmmph, Warug è il solito tirchio. Dammi un momento per fare i bastoni.$B$BUno lo prendo io. Il secondo va al Necrokhan che pattuglia la strettoia verso le rovine elfiche.$B$BIl terzo è tuo. Ora più che mai, fai parte di questa guerra.",
}
T[92849] = {
  title = "Lo Studioso Scomparso",
  desc = "<Da quello che hai appena trovato, è molto probabile che qui a Fillion sia capitata qualche disgrazia. Potrebbe essere ancora nei paraggi, e forse ha bisogno di aiuto. Poco più a nord noti una caverna: dovresti continuare a cercarlo lì.>",
  obj = "Continua a cercare Fillion Flamebreeze.",
  reward = "Gr... grazie, $Gstraniero:straniera;. Tornavo da un incarico alle Overlook Standing Stones quando i Windshapers mi hanno teso un'imboscata e mi hanno aggredito all'improvviso. Mi hanno portato a forza fino all'imboccatura della caverna e mi hanno lasciato lì, sanguinante e a malapena cosciente. Prima di perdere i sensi, l'ultima cosa che ricordo è un'enorme bestia alata che usciva dalla caverna e mi afferrava.$B$BCredo di poterlo dire con certezza: se non fossi $Garrivato:arrivata; tu, sarei diventato la cena di quella bestia e dei suoi piccoli.",
}
T[92850] = {
  title = "Lo Studioso Scomparso",
  desc = "Mi sento già molto meglio. Con le arti arcane me la cavo, e Valanaar è poco lontana: posso farcela da solo. Ma c'è una cosa che conta più della mia incolumità: questi shriekling hanno fatto il nido vicinissimo a Valanaar, e sono un pericolo. Ti prego, torna dentro e prendi la testa di quella bestia!$B$BQuando avrai finito mi troverai a Valanaar: devo riferire al Magistro Supremo quello che è successo qui e a che punto è la mia missione.",
  obj = "Uccidi la Shriekling Matriarch nello Shriekling Den, poi porta la sua testa a Fillion Flamebreeze a Valanaar.",
  progress = "Quegli shriekling sono troppo pericolosi per lasciarli nidificare così vicino a Valanaar. Però... sono l'ultimo dei nostri problemi.",
  reward = "Grazie ancora, $N.",
}
T[92860] = {
  title = "Al Servizio di Zephras",
  desc = "Noi dell'High Order abbiamo fatto del nostro meglio per evitare un conflitto diretto con il culto, ma ormai non si può più. Hanno dato prove chiare della loro ostilità, e ora girano voci di movimenti del culto su scala più ampia in tutta l'isola. È evidente che stanno preparando qualcosa e, qualunque cosa sia, non promette niente di buono per il popolo di Zephras.$B$BPresentati a Valennia Stormfist e dille che, se ce ne fosse bisogno, noi dell'High Order sosterremo pienamente gli sforzi di Valanaar contro gli Al'Aketh.",
  obj = "Presentati a Valennia Stormfist e falle sapere che l'High Order è con loro nella lotta contro gli Al'Aketh.",
  reward = "Mi dispiace per Belathaan. Era mio cugino, un buon mago e un servitore di Zephras. Lo vendicheremo.$B$BSembri impaziente di darci subito una mano. Vieni, parliamo della situazione più nel dettaglio.",
}
T[92867] = {
  title = "Terra da Custodire",
  desc = "Il nostro retaggio starà pure andando in rovina, ma questa non è l'ultima roccaforte che ci resta. Abbiamo altro in serbo, e per proteggerlo dobbiamo tenerlo nascosto.$B$BSempre più gente sostiene la conservazione delle sculture rimaste e dei sacri luoghi di sepoltura. La marmaglia che si è stabilita nel nostro antico regno non immagina nemmeno quale vendetta sta per abbattersi su di lei.$B$BRespingi i Boulderfist e lo Syndicate. Devono imparare che Stromgarde non è solo pugno, aquila e pietre.",
  obj = "Sconfiggi gli intrusi Boulderfist, dello Syndicate e Witherbark a Stromgarde Keep e torna da Groundskeeper Lomar.",
}
T[92871] = {
  title = "Al Servizio di Zephras",
  desc = "Valennia Stormfist e le sue peacekeepers proteggono Zephras da sempre, e noi le abbiamo aiutate come meglio potevamo. Si dice che il culto si stia muovendo sempre di più in tutta l'isola, ed è chiaro che sta preparando qualcosa.$B$BPresentati da Valennia e ribadiscile che, se ce ne fosse bisogno, i Windshapers appoggiano in pieno Valanaar nella lotta contro gli Al'Aketh.",
  obj = "Presentati da Valennia Stormfist e dille che i Windshapers sono con loro nella lotta contro gli Al'Aketh.",
  reward = "Sembri impaziente di aiutare subito. Vieni, parliamo meglio della situazione.",
}
T[92872] = {
  title = "Passi Doverosi",
  desc = "Custodiamo in eterno questa tomba e la conoscenza dei riti cerimoniali con cui si onorano queste anime cadute.$B$BOra che sei $Gsceso:scesa; tre livelli sotto terra, muovi i primi passi per tornare al mondo illuminato dal sole, portando con te una sacra saggezza.$B$BOgni stagione portiamo via un po' della polvere di questa tomba e la spargiamo negli oceani di Azeroth. È un gesto simbolico, che rinnova i cicli.$B$BPrendi questo sacchetto. Va' alle scogliere dietro lo Stromgarde Keep e gettalo in mare.",
  obj = "Getta il Pouch of Tomb Dust in The Great Sea e torna da Caretaker Alaric nella cripta di Stromgarde Keep.",
}
T[92873] = {
  title = "Prova di Fattibilità",
  desc = "Sappiamo già che questi cristalli non servono solo a spaccare il terreno — i Gelkis hanno dimostrato che si possono piegare a fini negromantici. Ricordi le ossa che ti ho fatto raccogliere? Le ho rimesse insieme come ho potuto, poco più su sulla collina. Bastavano per due scheletri funzionanti.$B$B<Orgrul ti porge un bastone appena fatto.>$B$BMentre tu giochi con il tuo nuovo giocattolo, io consegnerò il bastone del Necrokhan. Torna solo quando potrai dimostrare di saperlo usare.",
  obj = "Mantieni la tua reputazione con il Clan Magram, poi porta 426 Well Cursed Bones da un rituale riuscito a Orgrul.",
  progress = "Finora ci hai aiutato, ma se non sai risvegliare i morti, ai Magram non servi più.",
  reward = "Vedo un fuoco nuovo ardere vivo nei tuoi occhi, $Gstraniero:straniera;. Hai dimostrato di saper creare le tue armi, di evocare servitori ai tuoi ordini e, soprattutto, di imporre il tuo dominio quando si rifiutano di obbedirti.$B$BPeccato che tu non abbia sangue di centauro. Saresti già sulla buona strada per diventare il prossimo Khan.",
}
T[92880] = {
  title = "Ritorno a Valanaar",
  desc = "Credo che ci vorrà un po' per ripulire la zona da ciò che resta degli assalitori, ma ora abbiamo molte più possibilità di farcela. Torna a Valanaar e fai sapere che qui la situazione si è stabilizzata.$B$BNon so come ringraziarti per l'aiuto. Senza di te saremmo messi molto peggio. Avevo chiesto rinforzi e, a quanto pare, ho avuto invece $Gun eroe:un'eroina; in erba. Mi va bene così.$B$BChe i quattro venti ti benedicano, $C.",
  obj = "Porta il Rapporto di Yorna a Valennia Stormfist in Valanaar.",
  reward = "<Valennia è visibilmente sollevata mentre le racconti come stanno le cose alla torre di guardia orientale.>$B$BSiano ringraziati i venti.",
}
T[92881] = {
  title = "La Richiesta del Gran Anziano",
  desc = "Gli attacchi alle torri di guardia, a occidente e a oriente, non sono una coincidenza. Dopo quello che ci hai raccontato di quel sacerdote del cielo alla torre di guardia occidentale, sospettiamo che il culto voglia fare qualcosa ai piloni d'ancoraggio.$B$BTi prego, parla con High Elder Shadowsong: ti illustrerà una pista che potrebbe rivelarsi promettente.",
  obj = "Parla con Talaanis Shadowsong a Valanaar.",
  reward = "Ho una piccola faccenda per cui serve proprio l'aiuto di $Gun avventuriero:un'avventuriera; come te.",
}
T[92893] = {
  title = "Nessuna Pietà per i Deboli",
  desc = "Addentrandoti nella Valley of Bones troverai dei vagabondi Gelkis che hanno osato mettere piede nel nostro territorio. Ho ordinato di tenerli in vita per darli in pasto ai vermi delle ossa che scavano qua e là, ma pare che le prede vive non li interessino.$B$BIl compito è semplice. Trova i prigionieri e spegni la loro vita. Non lasciare loro nemmeno un breve barlume di speranza di essere liberi.",
  obj = "Mantieni la tua reputazione con il Clan Magram e uccidi 5 Gelkis Captives sparsi in Valley of Bones. Torna da Orgrul dopo aver completato il compito.",
  reward = "Mi sarebbe piaciuto appendere i loro teschi alla mia tenda, ma ai Magram i loro corpi servono molto di più lasciati nella valle.$B$BEntro domattina i vermi delle ossa ne avranno divorato la carne, e allora avremo tanti nuovi scheletri da risvegliare.$B$BOgni Gelkis morto rende più forte l'esercito dei Magram!",
}
T[92894] = {
  title = "Rianimare le Ossa",
  desc = "Ti leggo l'eccitazione negli occhi, $Gstraniero:straniera;. Cominci a capire che potenziale ha la negromanzia?$B$BCerto che sì. Ed è proprio per questo che ti ordino di affinare ancora le tue capacità.$B$BMan mano che ti addentri nella Valley of Bones, vedrai cosa resta dei tentativi falliti di rianimare i morti: opera dei Gelkis, senza dubbio. Quei resti riescono a malapena a uscire dalla terra, scavando con le unghie. Farebbe ridere, se non fosse così patetico.$B$BHo infuso nel tuo bastone un potere più grande. Usalo per far crescere il nostro esercito, e schiaccia chi si oppone!",
  obj = "Mantieni la tua reputazione con il Clan Magram e usa l'Enhanced Necromancy Staff per rianimare del tutto i non morti che faticano a emergere in tutta la Valley of Bones. Torna da Orgrul quando l'esercito Magram sarà cresciuto.",
  reward = "<Orgrul ascolta la tua spiegazione e non riesce a trattenere un ghigno.>$B$BNon crucciarti, $Gstraniero:straniera;: questo esperimento è stato tutt'altro che un fallimento. Adesso sappiamo quanto è debole e fragile la negromanzia dei Gelkis. Ne hanno ancora di strada da fare, prima di eguagliare la nostra potenza.$B$BE che tu sia $Griuscito:riuscita; a prendere il controllo di qualcuno di loro depone molto a tuo favore. Quegli scheletri saranno anche andati sprecati, ma le tue capacità le hai dimostrate, e sono notevoli.$B$BPer ora il bastone me lo riprendo. C'è altro lavoro da fare.",
}
T[92909] = {
  title = "Mietere le Mietitrici",
  desc = "Oh no... adesso sì che sono nei guai!$B$BHo saputo delle mietitrici che terrorizzano i campi di Westfall, così sono venuto fin da Ironforge per vedere se riuscivo a ricalibrarle. Ma sono molto più aggressive di quanto prevedessero i miei calcoli, e mi hanno inseguito dentro questa stalla!$B$BSe avessi un po' di isomolle e girostabilizzatori delle mietitrici, potrei costruire un congegno per coprirmi la fuga. Potresti procurarmi i pezzi?",
  obj = "Ozwin Ironsprocket, a Saldean's Farm, vuole che tu gli porti 14 Golem Isosprings e 5 Harvester Gyrostabilizers.",
  progress = "Là fuori è un disastro, $N! Hai raccolto i pezzi che mi servono?",
  reward = "Grazie mille! Mi metto a studiare un piano di fuga. Nel frattempo, prendi questo!",
}
T[92910] = {
  title = "Mietere i Mietitori",
  desc = "Il pezzo che sei $Griuscito:riuscita; a recuperare dal mietitore sembra quasi intatto. A qualcuno che s'interessa di golem mietitori potrebbe far piacere vederlo.",
  obj = "Porta il Precessive Autocognition Assembly a Ozwin Ironsprocket a Saldean's Farm.",
  reward = "E questo cos'è?",
}
T[92911] = {
  title = "Mietere i Mietitori",
  desc = "Capisco... Comincio a intuire cosa fa funzionare quei mostri, e ho un'idea su come potremmo prendere il controllo dei loro sistemi, almeno per un po'.$B$BIo continuo ad armeggiare con il congegno che mi hai portato. Tu intanto potresti racimolare qualche pezzo per il dispositivo?",
  obj = "Ozwin Ironsprocket a Saldean's Farm vuole che gli porti 8 Golem Isosprings, 4 Copper Modulators e un Crude Scope.",
  progress = "Allora, Raton, come procede il progetto?",
  reward = "Eccolo qua, Raton! Dovrebbe funzionare alla grande. Va' a provarlo!$B$B...Io? No, io resto qui. Tanto comincio a sentirmi a casa.",
}
T[92947] = {
  title = "La Nostra Mossa",
  desc = "Bene, ci siamo tutti. Ho appena mandato alcuni dei miei combattenti migliori dentro il santuario dall'ingresso principale: devono creare un po' di scompiglio e fare da diversivo, mentre io entro dal fianco con il grosso delle nostre forze.$B$BSe tutto va bene, dovremmo riuscire a sfondare in fretta ed eliminare la Gran Sacerdotessa. Tu entra e comincia a spaccare crani. Quando avrai fatto un po' di confusione, raggiungi la mia vice, Hyusaa Quickbreeze, vicino alla scalinata del santuario.$B$BChe i venti ti guidino, $C.",
  obj = "Uccidi 7 Al'Aketh Guardians, 7 Al'Aketh Spiritcallers e 7 Al'Aketh Blademasters, poi fai rapporto a Hyusaa Quickbreeze allo Shrine of Akir.",
  progress = "<Hyusaa ti rivolge un cenno del capo.>",
  reward = "Abbiamo combattuto duramente per arrivare fin qui, ma non è ancora finita.",
}
T[93034] = {
  title = "Valley of Bones",
  desc = "Mentre eri via è tornato al villaggio uno dei nostri esploratori, e le notizie che ha portato hanno confermato i miei timori.$B$BI Magram tramano qualcosa, $N, e non è niente di buono.$B$BLa Valley of Bones, lontano a est, è una terra maledetta: pochi centauri hanno osato entrarci, e ancora meno ne sono mai tornati a casa. Laggiù il nostro nemico ha trovato qualcosa, qualcosa di malvagio, e dobbiamo scoprire cos'è.$B$BCerca l'esploratore Nerlokh all'ingresso meridionale. Ma forse dovrai dare altre prove del tuo valore ai Gelkis.",
  obj = "Migliora la tua reputazione con i Gelkis e trova Nerlokh vicino alla Valley of Bones, molto a est di Gelkis Village.",
  reward = "Ecco la Valley of Bones. Maledetta per sempre: un luogo a cui nemmeno la grande Theradras sorriderebbe. Da generazioni nessun clan osava mettere zoccolo qui, eppure ora pare che i Magram l'abbiano reclamato come loro!$B$BSono poco $Gaddestrato:addestrata; e non ho l'equipaggiamento per combattere — oltre questi archi non vado. Tocca a te, $N, batterti per i Gelkis.$B$BHai fatto molto per noi, ma il tuo lavoro è appena cominciato.",
}
T[93035] = {
  title = "Devastare i Devastatori",
  desc = "Non serve guardare lontano: i non morti si trascinano proprio qui davanti a noi. Ma hai notato che hanno qualcosa di strano?$B$BCamminano su due gambe, non su quattro! Questi scheletri non sono nemmeno i nostri fratelli caduti. I Magram staranno violando i corpi di chi è morto molto prima che Desolace fosse il nostro dominio. Non riesco a immaginare con quale giustificazione abbiano voltato le spalle a Madre Theradras per mettersi a profanare cadaveri che riposavano qui da secoli.$B$BRimetti a riposare i non morti, $N.",
  obj = "Mantieni la tua reputazione con il Clan Gelkis e uccidi 6 Undead Ravagers, poi torna da Nerlokh all'ingresso meridionale della Valley of Bones.",
  reward = "Sembravi $Gammaccato:ammaccata; e $Gmalconcio:malconcia;, ma non $Gspezzato:spezzata;. Per quelli che sono stati rimessi a riposare i tuoi sforzi hanno fatto la differenza, ma avrai notato di certo che nella valle l'agitazione non ha fatto che crescere.$B$BTemo che presto le stesse ossa che hai sepolto si rimetteranno in piedi.$B$BDobbiamo andare avanti.",
}
T[93036] = {
  title = "Infiltrarsi nel Culto",
  desc = "Forse lo sai già, forse no: Sania Silverstream, laggiù, è una \"missionaria\" degli Al'Aketh. Amano farsi passare per un normale ordine religioso e, per reclutare, mandano in giro emissari dall'aria innocua. Finora abbiamo tollerato Sania per non arrivare a uno scontro diretto con il culto, ma è chiaro che questa illusione di pace non durerà ancora a lungo.$B$BQui sei $Gnuovo:nuova; e $Gsconosciuto:sconosciuta; ai più, quindi vorrei vedere se riesci a servirti di Sania per avvicinarti al culto e scoprire che piani hanno per il villaggio.",
  obj = "Parla con Sania Silverstream in Shen'dar Village.",
  reward = "Salve, $Gfigliolo:figliola;, mi chiamo Sania Silverstream e sono una sacerdotessa di rango minore dell'Order of the Al'Aketh. Desideri sapere di più sul nostro sovrano, il Windlord Al'Akir?$B$BAlla tavola del Signore del Vento c'è sempre posto per i giusti e per i pentiti.",
}
T[93037] = {
  title = "Smascherare i Rinnegati",
  desc = "Mentre aspettavo il tuo arrivo ho guardato un po' più in là, tra gli archi, e ho notato una cosa che ho bisogno che tu mi confermi.$B$BNon sopporto di dirla ad alta voce, non finché non saprò che i miei sospetti sono fondati.$B$B$N, mentre ti orienti nella valle, uccidi alcuni dei negromanti che sembrano più deboli degli altri. Strappa loro le vesti rituali, con attenzione, e portamele. Devo sapere se ho la mente lucida e la vista chiara.",
  obj = "Mantieni la tua reputazione con il Clan Gelkis e porta 1 Necromantic Garb a Nerlokh all'ingresso della Valley of Bones.",
  progress = "Hai la mia parola: quando avrai portato a termine il compito, ti dirò cosa sospetto.$B$BPer il bene del nostro clan, speriamo che i miei occhi mi abbiano giocato un brutto scherzo.",
  reward = "<Nerlokh ti prende in fretta la stoffa e gli accessori, e la sua espressione si fa gelida. Ne guarda solo alcuni, poi mette da parte il resto.>$B$B$N. Questi negromanti minori sono Gelkis.$B$BOra capisco perché, a quanto pare, perdiamo membri più spesso di quanto le nostre schermaglie farebbero pensare. Alcuni di noi stanno disertando, probabilmente per fare colpo sui Magram.$B$BIl nostro clan sta perdendo questa guerra.",
}
T[93041] = {
  title = "Affrontare la Verità",
  desc = "Questa scoperta è devastante per il nostro clan, ma è meglio che lo sappia solo chi deve saperlo. Uthek è tra questi: deve essere al corrente di quello che succede qui, e credo che saprà come procedere.$B$BPrendi questo e mostraglielo. Per sicurezza dovremmo portarle anche una prova della negromanzia: trova un teschio che sembri maledetto da poco. Sospetto che li ammucchino nelle fauci di uno degli scheletri giganteschi.",
  obj = "Mantieni la tua reputazione con il Clan Gelkis e porta un Accursed Skull e la Gelkis Necromantic Garb a Uthek the Wise in Gelkis Village.",
  progress = "Non pensavo di rivederti così presto. Devo prenderlo come un cattivo presagio?",
  reward = "<Uthek ha ascoltato la tua spiegazione con aria dubbiosa, finché non le hai mostrato le prove materiali.>$B$BMi ero accorta che stavamo diminuendo, $N, ma questo non me lo sarei mai aspettato! La negromanzia... usata senza vergogna da quegli immondi Magram. E adesso scopro che c'entra anche il mio clan?$B$BParlerò con il Khan. Per ora, preparati a tornare in prima linea.",
}
T[93044] = {
  title = "Un Grido Purificatore",
  desc = "Non tornerai a mani vuote da Nerlokh, nella Valley of Bones.$B$BEntra nella grotta al centro del nostro villaggio e cerca Mulara. Chiedile a nome mio le Tears of Theradras: ne abbiamo poche, ma sono la nostra migliore speranza contro l'immonda negromanzia dei Magram!$B$BPreparerò un rituale, e creeremo un'arma che spezzi i loro incantesimi.",
  obj = "Mantieni la tua reputazione con i Gelkis e riporta le Tears of Theradras a Uthek the Wise in Gelkis Village.",
  progress = "Fai presto, $N. Nerlokh non dovrebbe restare a lungo senza protezione.",
  reward = "Sono grata che Mulara abbia potuto aiutarci. Sapevo che ci avrebbe provato, ma temevo che non avesse cristalli da darci.$B$BPrenditi un momento per schiarirti le idee: presto ti spiegherò il mio piano.",
}
T[93045] = {
  title = "Metti alla Prova la Tua Teoria",
  desc = "Ho messo il teschio che mi hai portato accanto ad alcune ossa trovate mentre aspettavo il tuo ritorno. Subito ho visto una luce malsana spandersi dal teschio e impadronirsi di quelle vecchie ossa. Ora capisco perché resistere al richiamo della negromanzia è così difficile.$B$BTi ricordi questo cristallo? È draenethyst. So poco di quello che può fare, ma credo che sia in grado di incanalare il potere di Theradras. Con questo, forse riuscirai a dissolvere la maledizione.$B$BIl luogo del rituale è vicino allo stagno, appena a est del villaggio.",
  obj = "Mantieni la tua reputazione con i Gelkis e dissolvi la maledizione negromantica presente sull'Accursed Skull. Una volta $Griuscito:riuscita;, torna a rapporto da Nerlokh vicino alla Valley of Bones.",
  progress = "$N! Sei di ritorno da Gelkis Village? Confido che Uthek abbia saputo darti qualche spunto.",
  reward = "Quel bastone sembra uno di quelli di Uthek, ma la gemma non la riconosco. Dici che si chiama draenethyst?$B$B<Nerlokh ascolta il tuo racconto degli ultimi eventi e osserva i tuoi gesti da $R, molto espressivi.>$B$BUn'arma per contrastare la negromanzia è proprio quello che ci serve, e se Uthek ti affida uno dei suoi grandi bastoni, deve fidarsi molto di questo piano.$B$BAnch'io ho delle notizie per te.",
}
T[93058] = {
  title = "Salvare i Nostri",
  desc = "Appena dietro la collina c'è stata una breve battaglia fra alcuni negromanti, e ne ho approfittato per dare un'occhiata più da vicino all'interno.$B$B$N, non tutti quelli che abbiamo perso di recente erano disertori. Più avanti nella valle ci sono dei Gelkis tenuti prigionieri! Non ho potuto capire in che situazione fossero, perché un enorme bruto Magram mi si è lanciato contro alla carica. Mi ritengo fortunato che abbia perso interesse in fretta.$B$BDevi tornare nella Valley of Bones e liberarli. I Gelkis restano uniti.",
  obj = "Mantieni la tua reputazione con il clan Gelkis e salva 5 Gelkis Captives nella Valley of Bones. Torna da Nerlokh vicino all'ingresso quando hai finito.",
  reward = "Quando ho sentito il calpestio degli zoccoli, sulle prime ho pensato che stessero per ricacciarmi fino al villaggio. Immagina la mia gioia quando ho visto i miei fratelli ritirarsi oltre questi archi, sani e salvi!$B$BHo detto ai sopravvissuti di andare a rapporto da Uthek e riferirle tutto quello che possono aver scoperto. Non mi aspetto rinforzi, $N, ma questo fa ben sperare per il futuro del nostro clan.$B$BRestiamo concentrati sul nostro compito.",
}
T[93062] = {
  title = "Seppellire le Ossa",
  desc = "Veniamo al tuo bastone. Lo riconosco, è uno di quelli di Uthek. E mi hai detto che è fatto con le Lacrime di Theradras, che è potenziato con un Draenethyst Crystal e che può dissolvere la magia oscura?$B$BPiù avanti nella valle ho notato degli scheletri intrappolati appena sotto il terreno roccioso. Credo che siano evocazioni fallite dei Negromanti Reietti, forse condannate per sempre a un'esistenza soffocata dalla terra.$B$BFarli tornare a riposare in pace sarebbe un bene per la nostra causa e per i loro spiriti.",
  obj = "Mantieni la tua reputazione con il Clan Gelkis e dissolvi le maledizioni da 8 evocazioni fallite in tutta Valley of Bones.",
  reward = "Sapere che hai riportato la pace a tanti corpi mi toglie un peso dalle spalle.$B$BPer tutta la vita ho creduto che le guerre fra i nostri clan sarebbero finite per forza nella brutalità e in un bagno di sangue. Non avrei mai immaginato di guardare la morte in faccia e di vederla ricambiare lo sguardo.$B$BGrazie ancora, $N.",
}
T[93065] = {
  title = "Prepararsi alla Battaglia",
  desc = "Le Peacekeepers si stanno mobilitando e ci stiamo equipaggiando tutti per partire. Fai i preparativi che ti servono e raggiungici sulla strada orientale che dal paese va verso nord. Prima di metterci in marcia faremo un ultimo controllo con tutti.",
  obj = "Parla con Valennia Stormfist nei Gustberry Lowlands.",
  reward = "Più pronti di così non potremmo essere.",
}
T[93066] = {
  title = "Bristleback Retreat",
  desc = "Dall'altra parte della valle abbiamo messo su un piccolo avamposto, per prepararci a marciare nella foresta qui vicino. Prima che tu vada dritto laggiù, però, voglio che ti occupi dei Bristleback, che di recente hanno fatto un'incursione lungo la strada. Pare che siano arrivati più o meno insieme a noi, ma sono riusciti a mettere le mani su un manufatto del tempio vicino che ci ha tenuti a distanza.$B$BIl compito è semplice: cerca le spine e i maiali e uccidine un bel po', senza distinzioni. Poi vai a fare rapporto a Hagiak, all'accampamento di cui ti ho parlato.",
  obj = "Mantieni la tua reputazione con i Magram e uccidi i quilboar a Bristleback Retreat. Poi fai rapporto a Hagiak a Magram Front, dall'altra parte di Valley of Bones, a Desolace.",
  reward = "Mi spiace che tu abbia fatto tanta strada, $Gstraniero:straniera;, ma qui al fronte dei Magram non ci servi. Mi hai già distratto abbastanza da rallentare il nostro lavoro.$B$BTorna da Orgrul e digli —$B$BA pensarci bene, ho qualcosa per $Gun soldato sacrificabile:una soldatessa sacrificabile; come te. Sarà una faccenda rapida, nel bene o nel male.",
}
T[93072] = {
  title = "Soluzioni a Lungo Termine",
  desc = "Qui fuori, a sud-ovest, c'è un secondo villaggio di centauri: è dei Gelkis. Ti aspetti che ti mandi laggiù solo a versare un po' di sangue, vero? Bene. Ed è meglio che sia la prima cosa che ti viene in mente, altrimenti dubiterei della tua fedeltà ai Magram!$B$BChe aspetti? Vai! Uccidi!",
  obj = "Mantieni la tua reputazione con il clan Magram e uccidi 2 Outcast Scouts, 6 Outcast Marauders e 8 Negromanti Reietti, poi torna da Hagiak a Magram Front.",
  reward = "I miei esploratori mi hanno già detto che ce l'hai fatta. Forse ora possiamo andare avanti con l'addestramento in pace. I Gelkis devono imparare che questo posto, e Desolace, sono dei centauri nati dal sangue dei Magram.$B$BSe vedi degli sbandati, taglia la testa anche a loro. Devono aver paura di mettere anche solo uno zoccolo fuori dal loro piccolo tugurio.$B$BUn giorno, presto, sarà nostro anche quello.",
}
T[93089] = {
  title = "Ciò Che Verrà",
  desc = "Ringrazia da parte mia Elaadrin, ti prego, per tutto quello che l'High Order e i tuoi nuovi amici di questo \"Kirin Tor\" hanno fatto per Zephras Isle. So che l'High Order intende lasciare l'isola: per questa spedizione il tuo ordine ha la mia benedizione e i miei auguri.$B$BQualunque soluzione arcana trovi l'High Order, posso solo sperare che ci dia davvero la stabilità che ci è mancata in questi ultimi anni. E se hai intenzione di andare con loro... be', questa missione ne sarà ancora più forte.$B$BChe i venti siano con te, $N.",
  obj = "Parla con Elaadrin Evengale quando sei $Gpronto:pronta; a lasciare Zephras Isle.",
  reward = "Mi rallegra sapere che la nostra spedizione ha la benedizione di High Elder Shadowsong. Il culto è sconfitto e i preparativi sono conclusi: credo che sia finalmente il momento.$B$BAnsirem si è impegnato molto per aiutarci ad avviare un trasporto stabile con le navi skycutter fra la città di Dalaran e Zephras Isle. Abbiamo fatto tutte le prove possibili, ed è ora che la nostra avanguardia parta.",
}
T[93090] = {
  title = "Cosa Viene Dopo",
  desc = "Ringrazia Ayessa da parte mia per tutto quello che i Windshapers e i tuoi nuovi amici di questo \"Earthen Ring\" hanno fatto per Zephras Isle. So del piano di lasciare l'isola portando con sé gli sciamani dei Windshapers, e alla spedizione del vostro ordine vanno la mia benedizione e i miei auguri.$B$BSpero soltanto che la soluzione dei Windshapers, qualunque essa sia, ci dia davvero la stabilità che negli ultimi anni ci è mancata.$B$BChe i venti siano con te, $N.",
  obj = "Parla con Ayessa Dawnsinger quando sei $Gpronto:pronta; a lasciare Zephras Isle.",
  reward = "Sono lieta di sapere che la nostra spedizione ha la benedizione di High Elder Shadowsong. Ora che il culto è sconfitto e i preparativi sono pronti, credo che il momento sia finalmente arrivato.$B$BMuln si è impegnato molto per aiutarci ad avviare un collegamento stabile di fendicieli fra Zephras Isle e un luogo chiamato Mulgore, dove vive l'Earthen Ring. Abbiamo fatto qualche viaggio di prova, e alcuni dei nostri aspettano già dall'altra parte.",
}
T[93122] = {
  title = "Dare un'Occhiata",
  desc = "Tutti abbiamo sottovalutato il potere del clan Magram e la sua presenza in questa zona, ma la cosa potrebbe tornare a nostro vantaggio.$B$BCon tanti dei loro distratti, e visto che non accettano gli esiliati degli altri clan, chi resta a difendere il villaggio? E il loro Khan?$B$BDevi spingerti nella valle più a fondo di quanto tu abbia mai fatto e guardarti intorno. Se qui i Magram sono fortificati quanto sembra, potrebbero aver lasciato scoperto il loro villaggio...",
  obj = "Mantieni la tua reputazione con i Gelkis e indaga sui luoghi d'interesse dei centauri a Shen'dralas. Poi torna da Nerlokh all'ingresso di Valley of Bones con le tue scoperte.",
  reward = "<Riassumi le tue scoperte.>$B$BNon uno, ma DUE accampamenti?$B$B<Chiarisci che uno è senza dubbio dei Magram, mentre l'altro sembra appartenere ai reietti.>$B$BAllora è probabile che i Magram siano in pieno conflitto. $N, credo che questa possa essere la nostra occasione.",
}
T[93125] = {
  title = "Ritorno a Casa",
  desc = "Tu! Ti ho visto là fuori mentre combattevi i reietti. Non so da dove arrivi, ma mi serve il tuo aiuto.$B$BSono $Gstato attirato:stata attirata; qui dai miei fratelli Gelkis, che mi hanno promesso che sarei $Gstato:stata; al sicuro. Sapevo che la guerra nella Desolace ci stava sfuggendo di mano, ma non avrei mai immaginato che il mio stesso popolo si sarebbe dato alla negromanzia, in un tentativo contorto di passare al clan dei Magram. Quando ho alzato la voce contro tutto questo, hanno minacciato di uccidermi se mai avessi messo zoccolo fuori da questa tenda!$B$BTi prego, aiutami.",
  obj = "Mantieni la tua reputazione con i Gelkis e scorta Rokren fuori dall'Outcast Hideaway. Poi informa Nerlokh, vicino a Valley of Bones, di quanto è successo.",
}
T[93128] = {
  title = "Khan Jehn",
  desc = "Vorrei che l'ordine venisse da Uthek o dal Khan Shaka, ma temo che la nostra occasione duri poco. Troppo poco per sentire chi si trova a Gelkis Village.$B$BCon quello che sta succedendo qui alla Valley of Bones, credo che i Magram abbiano lasciato il Khan Jehn con poche difese. Se c'è mai stato un momento buono per attaccare il Khan di un altro clan, è questo.$B$BMa $N, con un Khan non si scherza, e con Jehn meno che mai. Se hai il coraggio di agire, sii $Grapido:rapida;, ma non sottovalutarlo.",
  obj = "Mantieni la tua reputazione con i Gelkis e uccidi il Khan Jehn a Magram Village. Quando ci sarai $Griuscito:riuscita;, fai rapporto a Uthek the Wise a Gelkis Village, in Desolace.",
  reward = "Hanno ucciso il Khan Jehn!?$B$BNon ci credo. Non riesco a crederci. Che gesto sfrontato! Folle! Nerlokh non aveva nessuna autorità per proporre un attacco del genere!$B$BEppure, se quello che dici è vero, non posso negare che la sconfitta di Jehn sia di buon auspicio per il futuro del nostro clan. Presto un nuovo Khan prenderà il suo posto, ma abbiamo il tempo di preparare la prossima mossa.$B$BParlerò con il nostro Khan. Per ora, qui il tuo lavoro è finito. Goditi la vittoria di oggi, ma non tentare la sorte un'altra volta.",
}
T[93129] = {
  title = "Minaccia di Fame",
  desc = "Visto che sembri fin troppo $Gdesideroso:desiderosa; di aiutare il nostro clan, sono $Gcerto:certa; che saresti $Gdisposto:disposta; a recuperare un po' di forniture, già che sei laggiù all'Outcast Hideaway.$B$BPer un Magram abbattere i nemici dovrebbe essere già un motivo sufficiente, ma non vedo perché non potremmo anche guadagnarci qualcosa.$B$BSistemati gli esuli, potremo rendere questo posto sicuro per i Magram e radunare un esercito che metta in ginocchio gli altri clan!",
  obj = "Mantieni la tua reputazione con i Magram e porta 6 Stolen Supplies a Hagiak al Magram Front.",
  progress = "Uccidi i loro soldati e affama chi sopravvive. Quel loro piccolo nascondiglio non dovrebbe mai più bastare a fare da base contro il nostro clan!",
  reward = "<Hagiak sbircia dentro diverse casse, all'inizio in silenzio.>$B$BDi tutte le cose da portare in prima linea, non mi sarei mai $Gaspettato:aspettata;... lasciamo stare. In alcune di queste casse c'è del cibo, ed è questo che conta. Così qui resisteranno molto meno a lungo.$B$BLa vittoria finale del nostro clan si avvicina.",
}
T[93159] = {
  title = "Lo Strange Hermit",
  desc = "Ehm, uhm... c-ciao, cioè, volevo dire, salve! Anzi, saluti! Scusami... è, uhm, passato tanto tempo dall'ultima volta che ho parlato sul serio con qualcun altro. Temo di essere un po' arrugginito.$B$B<La strana figura incappucciata si muove a disagio davanti a te.>$B$BAllora, ehm, uhm... come ti va la giornata?",
  obj = "Parla con lo Strange Hermit nella Shadowgale Forest e scopri di più su di lui.",
  progress = "Ecco, la storia è questa...",
  reward = "...e più o meno è tutto quello che ho da dire. Prima di stare qui ero — uhm — da un'altra parte. Adesso sono qui, e ho i miei amici e le mie cose. C-cose che ho costruito io, voglio dire. Più o meno è tutto quello che mi serve. Almeno, credo che sia tutto quello che mi serve.$B$BPerò, devo dire, è bello parlare con qualcuno che risponde. Gli spiriti della foresta ci provano, ma finiscono sempre per mettersi a cantare. Ha il suo fascino, ma non è proprio una conversazione s-stimolante.",
}
T[93160] = {
  title = "La Generosità della Foresta",
  desc = "Grazie per esserti $Gfermato:fermata; a parlare con me! S-se vuoi darmi una mano, avrei bisogno di qualcuno che mi aiuti a raccogliere le ghiande da terra, nella foresta. Quelle qui intorno le ho già prese quasi tutte, ma la foresta è piena di quei cosi mezzi raptor e mezzi uccelli. Là fuori è pericoloso, e preferirei non finire come pranzo di un uccello gigante!$B$BQuindi, se ti va, magari potresti raccoglierle tu per me? In cambio preparerò qualcosa di buono per tutti e due!",
  obj = "Raccogli 8 Ghiande di Shadowgale nella Shadowgale Forest.",
  progress = "Mmm, con queste ghiande riesco a cucinare cose che credo ti piaceranno!",
  reward = "Grazie, $Gstraniero:straniera;! Vedrai, arrostite sono una delizia!$B$BScusami, ci metto poco a prepararle.",
}
T[93161] = {
  title = "L'Ancient Hilt",
  desc = "Alla debole luce della torcia scorgi un piccolo luccichio di metallo. Guardando meglio, capisci che è l'elsa spezzata di un'antica spada.$B$BLa lama non c'è più, ma si vede bene che quest'elsa è un lavoro da maestro. È un cimelio prezioso, e qualcuno potrebbe volerne sapere di più.",
  obj = "Trova qualcuno che potrebbe essere interessato all'Ancient Hilt che hai trovato tra le rovine di Ban'aethal.",
  progress = "Aspetta... che cosa hai lì? Possibile?",
  reward = "Per il mio popolo questo oggetto ha un valore che le parole non bastano a esprimere. Questa spada fu forgiata dal leggendario fabbro arcano Luminarian. Quando fuggimmo da Kalimdor, Luminarian accompagnò il nostro popolo, e per secoli continuò il suo lavoro nelle Skyborne Isles. Molte delle armi e delle armature che oggi vedi impugnare e indossare su Zephras si rifanno allo stile delle sue straordinarie creazioni. La lama è spezzata e la magia si è esaurita, ma la spada non è irreparabile. Prendila, e cerca qualcuno che conosca meglio le opere di Luminarian. Forse potrà aiutarti.",
}
T[93165] = {
  title = "La Pietà Cade su Orecchie Sorde",
  desc = "Gli Al'Aketh hanno portato una grande tragedia nella nostra enclave, e il sangue si ripaga col sangue.$B$BTi faccio un'offerta, $Gstraniero:straniera;. Se ti capitasse di scontrarti con questi maledetti cultisti, portami le orecchie di quelli che uccidi. Per ognuna che mi riporterai avrai una ricompensa, sia in monete sia, col tempo, con l'accesso ai segreti dei Nightclaw, se dimostrerai di essere $Gun vero amico:una vera amica;.",
  obj = "Raccogli 5 Al'Aketh Cultist's Ears dai cultisti Al'Aketh nella Shadowgale Forest, nello Shrine of Akir o nei Gustberry Lowlands.",
  progress = "Non avrò pace finché le mie zanne non avranno squarciato la gola di ogni cultista di quest'isola, fino all'ultimo.",
  reward = "Ottimo lavoro. Eliminare il culto può solo fare del bene. Spero che serva a far capire che con i Nightclaw non si scherza e che i nostri rancori sono profondi.$B$BImmagino che il culto ti darà il tuo bel da fare. Se raccogli altre orecchie, portamele qui.",
}
T[93172] = {
  title = "Libera le Conche",
  desc = "Quasi tutti gli elfi dell'isola, a quanto pare, credono che questi boschi siano infestati. E non hanno torto.$B$BTra le vecchie rovine a nord-est si radunano degli strani spiriti, simili a fantasmi. Certe notti quasi li senti \"cantare\". Non assomiglia a nessuna canzone che abbia mai ascoltato, ma una canzone lo è di sicuro, ed è... così triste.$B$BNon so bene perché, ma credo che laggiù, tempo fa, sia successo qualcosa di terribile, e che in qualche modo gli spiriti siano rimasti intrappolati lì. Se ti senti $Gcoraggioso:coraggiosa;, potresti aiutarli a liberarsi?",
  obj = "Distruggi 10 Wind Hollows nella Shadowgale Forest.",
  progress = "Non ci resta che sperare che quei poveri spiriti trovino la pace, una volta liberi da questo posto.",
  reward = "Grazie, $Gstraniero:straniera;.",
}
T[93174] = {
  title = "Il Costrutto Malfunzionante",
  desc = "Il costrutto davanti a te ronza e sputacchia: è chiaro che non funziona come dovrebbe. Da $Gingegnere:ingegnera; con poca esperienza, sospetti che vada riparato.$B$BA Valanaar ci sono alcuni Artigiani che hanno una certa pratica con la manutenzione dei costrutti ciclonici come questo, e anche l'eremita che ti ha insegnato l'ingegneria potrebbe saperne qualcosa.",
  obj = "Parla prima con Riaani Nightwind a Valanaar e poi con lo Strange Hermit in Shadowgale Forest per saperne di più sul Malfunctioning Cyclone Construct.",
}
T[93176] = {
  title = "I Miei Piccoli Amici",
  desc = "Stai ammirando il mio piccolo serraglio, eh? È l'opera della mia non-vita. Ho passato ore e ore a studiarli: l'anatomia, la dieta, perfino i rituali sociali.$B$BVuoi unirti a me in questo passatempo? Ecco, prendi questo pacco: dentro ci sono appunti e materiale che dovrebbero bastarti per cominciare. Se lo perdi, dovrai comprarne un altro da me, per una piccola somma.",
  obj = "Usa gli oggetti contenuti nell'Entomology Starter Kit per trovare e catturare un'Arbor Tarantula, un Hay Weevil Specimen e un Flesh Picker.",
  progress = "Però devo dirlo: non c'è niente di meglio dell'emozione di scoprire esemplari nuovi. Un tempo adoravo andarli a cercare in ogni genere di fango e sporcizia, ma ormai l'occasione mi capita di rado.$B$BSotto questo aspetto, la mia piccola covata è insieme una benedizione e una maledizione: hanno bisogno di così tante attenzioni che non posso spingermi oltre la palude.",
  reward = "Sono davvero deliziosi! Guarda le zampe anteriori di questo! E il colore del carapace di quest'altro! Oh, e le mandibole di questo qui!$B$BNon ti facevo $Gun entomologo:un'entomologa;, eppure hai proprio un occhio attento.$B$BTi prego, prendi questo. Credo che tu gli sia $Gpiaciuto:piaciuta;, e questa specie in particolare io l'ho già catalogata.$B$BOra, se permetti, devo tornare alle mie ricerche. Mi hai dato molto da studiare!",
}
T[93188] = {
  title = "Ritorna da Orgrul",
  desc = "Al fronte hai fatto abbastanza. Ce la caviamo da soli.$B$BVa' a dire a Orgrul che la tua parte l'hai fatta. Il Magram Front adesso è più forte, e abbiamo messo gli occhi sull'accampamento degli esiliati: quando un'altra schiera di combattenti si unirà alla mischia, sarà il nostro prossimo insediamento.$B$BAllora? Muoviti!",
  obj = "Mantieni la tua reputazione con i Magram e fai rapporto a Orgrul vicino all'ingresso settentrionale di Valley of Bones.",
  reward = "Nella tua breve assenza, a Magram Village è successa una cosa interessante: un atto di guerra, eseguito con cura da uno straniero che combatteva sotto lo stendardo dei Gelkis.$B$BQualche mese fa avrei preteso la tua esecuzione, e quella di tutti gli altri stranieri che giocano d'inganno con i nostri clan senza sapere quello che fanno.$B$BMa questa non è una circostanza qualunque.$B$BÈ un'opportunità. Per te, per i Magram, per la guerra.",
}
T[93196] = {
  title = "Khan Jehn",
  desc = "Khan Jehn, il capo del nostro clan, è stato ucciso da una banda di stranieri come te, che agivano per conto del Clan Gelkis.$B$BPuoi smetterla di fingerti $Gsorpreso:sorpresa;. Attaccare Magram Village mentre guardavamo da un'altra parte è una strategia di guerra prevedibile, soprattutto per i Gelkis.$B$BSai perché non mostro né rabbia né rimorso, $Gstraniero:straniera;?$B$B<Orgrul ti porge un'arma che conosci, infusa di un potere ancora più grande di quando l'hai impugnata l'ultima volta.>$B$BEcco perché.",
  obj = "Mantieni la tua reputazione con i Magram ed esegui un rituale di negromanzia per resuscitare Khan Jehn. Il luogo del rituale si trova in una tenda presso il lago centrale di Magram Village.",
  reward = "I Gelkis reclutano stranieri per le loro subdole strategie di guerra; il nostro clan, invece, li manderebbe a morire.$B$BEppure eccoti qui, $N: $Guno straniero:una straniera; che ha dimostrato una lealtà feroce verso il Clan Magram, pur essendo così poco $Gbenvoluto:benvoluta;.$B$BNon so cosa ti spinga, ma il tuo potenziale l'ho visto con i miei occhi. Hai la mia gratitudine e quella del nostro clan.$B$BPer noi non sei più $Guno straniero:una straniera;. Per noi sei Magram.",
}
T[93224] = {
  title = "Carved Centaur Totems",
  desc = "Immagino non ti sorprenderà sapere che tutti e due i clan dei centauri sono restii ad accettare aiuto da chi non è dei loro. Soprattutto da gente come te e me — sai, i non-centauri.$B$BUna cosa però ci accomuna tutti: sappiamo che il denaro è potere. E abbiamo scoperto che i centauri del posto commerciano in legno intagliato. Se mi porti qualche campione delle loro decorazioni, posso ordinare d'urgenza incisioni simili. Magari riusciamo a comprarci un vantaggio.",
  obj = "Ottieni 5 Carved Centaur Totems uccidendo centauri di qualsiasi clan in ogni angolo di Desolace, poi portali a Captain Pentigast a Nijel's Point.",
  progress = "Sei $Gtornato:tornata; con i totem?",
  reward = "Non sono un centauro, ma questo fascio di totem mi sembra sufficiente: se mi metto nei loro ferri di cavallo, un regalo così mi farebbe felice. E mentre eri via sono riuscito a procurarmene anche qualcuno in più.$B$BParlami quando sei $Gpronto:pronta; per la consegna — mi fido di te: saprai scegliere il clan giusto con cui schierarci.",
}
T[93225] = {
  title = "Carved Centaur Totems",
  desc = "Ho notato che a volte i centauri di clan diversi si ritrovano lontano dagli insediamenti e commerciano fra loro. Li ho tenuti d'occhio per molte notti, e a quanto pare succede con ogni clan; ma soprattutto ho visto che moneta usano: totem intagliati.$B$BSe portiamo ai Gelkis o ai Magram un fagotto pesante di totem, credo che potremo volgere le sorti a nostro favore. Ho già cominciato a intagliarne qualcuno, ma senza qualche pezzo autentico dubito che si lasceranno ingannare tanto facilmente.",
  obj = "Ottieni 5 Carved Centaur Totems uccidendo centauri di qualsiasi clan in tutta Desolace, poi riportali a Gurda Wildmane al Ghost Walker Post.",
  progress = "Sei $Gtornato:tornata; con i totem?",
  reward = "Sono bellissimi — ho sottovalutato la creatività dei centauri. Non avrei mai immaginato che una razza così piena di brutalità e di crudeltà sapesse apprezzare le storie raccontate negli intagli.$B$BImmagino che apprezzarli costi molta meno fatica che farli. Anzi, mi correggo: non avrei mai immaginato che i centauri avessero la pazienza di intagliare tante storie nel legno. E il legno, dove lo prendono?$B$BComunque sia, parlami quando sei $Gpronto:pronta; per la consegna.",
}
T[93226] = {
  title = "Comprare l'Amicizia: Magram",
  desc = "Io starei con i Magram. Nonostante le difficoltà del passato, oggi sono senza dubbio il clan dominante. E ho sentito dire che con i Gelkis sono di un'ostilità brutale.$B$BCapisco tutti e due i clan in guerra, e i Gelkis più di tutti, ma la guerra è loro, non nostra. Dovremmo stare con la fazione che mette meno a rischio la nostra causa, e credo che siano i Magram.$B$BPorta questo al loro intendente in Magram Village, a sud-est.",
  obj = "Porta la Totem Tote all'Intendente dei Magram a Magram Village, in Desolace, per aumentare di molto la tua reputazione con quel clan. Devi essere almeno Neutrale con il Magram Clan Centaur.",
  progress = "Che affari ha $Guno straniero:una straniera; con Gorhak?",
  reward = "<Gli occhi di Gorhak si spalancano quando gli offri il fascio di totem intagliati, ma nel rialzare lo sguardo su di te aggrotta la fronte.>$B$BNon sono uno sciocco, $Gstraniero:straniera;. Una donazione così non arriva senza un motivo: vuoi qualcosa da me, o dal nostro clan. Cosa, non lo so.$B$B<Con un solo gesto della mano, l'intendente fa sua la borsa.>$B$BE oggi del tuo secondo fine non mi importa.$B$B$GBenvenuto:Benvenuta; a Magram Village, $Gstraniero:straniera;.",
}
T[93227] = {
  title = "Comprare l'Amicizia: Gelkis",
  desc = "A prima vista scommetterei che i Gelkis sono in difficoltà: sono molti meno dei Magram, e di rado i nostri esploratori mi dicono di averli visti scorrazzare.$B$BEppure sono uno dei clan dominanti di Desolace, e sopravvivono ancora oggi. Qualcosa di giusto lo devono pur fare.$B$BSe vuoi fare pace con i Gelkis, porta questa sacca di totem a Gelkis Village, lontano, a sud-ovest. Per quanto primitivi, un tesoriere di qualche tipo probabilmente ce l'hanno.",
  obj = "Porta la Totem Tote all'Intendente dei Gelkis a Gelkis Village, in Desolace, per aumentare di molto la tua reputazione con quel clan. Devi essere almeno Neutrale con il Gelkis Clan Centaur.",
  progress = "$GUno straniero:Una straniera; così addentro al villaggio? Sarà meglio che tu sia qui per affari.",
  reward = "<Molkar sbircia nella borsa. Gli si increspa sulle labbra un sorrisetto, che si spegne solo per un attimo quando scorge un totem palesemente falso. Fa finta di non vederlo.>$B$BNon so cosa abbia spinto $Guno straniero:una straniera; a portare un dono simile al nostro clan, ma per il nostro popolo è una grande fortuna: di recente il Clan Magram è più feroce del solito.$B$BNel nostro villaggio non devi più muoverti con cautela. Avvertirò Uthek, e lui parlerà con il Khan.",
}
T[93317] = {
  title = "Stagione dei Granchi",
  desc = "Conosci i Windsong Crawlers? Vedi, sono granchi che vivono soltanto nel Windsong Lake, qui a Zephras, e si possono pescare solo poche settimane all'anno.$B$BCon il culto così attivo in questo periodo non sono riuscita ad andare al lago a pescarli, e il tempo stringe. Te ne sarei grata se andassi tu a prendermene un po'. Di solito stanno lungo le rive del lago e nei fiumi.$B$BPerò fa' attenzione, sono più cattivi di quanto sembrino!",
  obj = "Raccogli 6 pezzi di Windsong Crawler Meat.",
  progress = "Qui la carne di Windsong Crawler è piuttosto comune, ma sulle isole di Anvilas e Siroccas era quasi una prelibatezza. Un tempo, quando le correnti celesti erano aperte, ogni volta che andavo a Shen'dramar o a New Eldre'naar la gente del posto mi assaliva pur di averne un po'.$B$BNon ci torno da... beh... tanto tempo.",
  reward = "Che i venti mi benedicano, questa carne ha un aspetto fantastico!$B$BGrazie mille, $C.",
}
T[93318] = {
  title = "RICERCATA: Vulgara the Insatiable",
  desc = "Per ordine di Constable Aonda of the Peacekeepers, viene posta una taglia sul flagello degli altopiani, Vulgara the Insatiable. Avvistata l'ultima volta su un'altura appena a sud-ovest di Shen'dar Village, la terribile vuldren alata è estremamente pericolosa e bisogna avvicinarla con cautela.$B$BConsegna la testa della bestia a Danarii Bellowveil per ricevere la ricompensa.",
  obj = "Uccidi Vulgara the Insatiable in Shen'dar Highlands e porta la testa a Danarii Bellowveil.",
  progress = "Mi serve la testa della creatura come prova dell'impresa.",
  reward = "Come se non avessimo già abbastanza grattacapi tra il culto e gli highlands bandits, ci mancava pure una vuldren gigante a terrorizzare i cittadini. Oggi hai fatto una gran cosa. Come promesso, ecco la tua ricompensa.",
}
T[93319] = {
  title = "Pilfered Windstones",
  desc = "Qui su Zephras dipendiamo sempre di più dalle windstones nella vita di tutti i giorni, perciò cerchiamo di tenerne una scorta per le emergenze. Ultimamente ho notato che dai nostri magazzini ne sparisce qualcuna.$B$BAbbiamo trovato delle windstones addosso ai banditi catturati di recente, e sospetto che dietro gli ammanchi ci siano loro.$B$BSe passi vicino alla loro grotta, a nord, ti dispiacerebbe dargli una bella lezione e recuperare un po' delle windstones che ci hanno rubato?",
  obj = "Raccogli 10 Pilfered Windstones dagli Highlands Bandits in Shen'dar Highlands.",
  progress = "Probabilmente questi ladruncoli ci svaligiano le provviste da mesi. Ho cercato di convincere Aonda a organizzare un'incursione per ripulire una volta per tutte quella grotta di banditi, ma non ha voluto allontanare dal villaggio i pochi peacekeepers che abbiamo.$B$BVisto che i cultisti di Falaath Village, a sud, sono sempre più numerosi, in fondo non posso darle torto.",
  reward = "Grazie, $C. Per ora queste dovrebbero bastarci per tirare avanti. Se però non sistemiamo presto le rotte dei rifornimenti, qualche windstones rubata sarà l'ultimo dei nostri problemi.",
}
T[93320] = {
  title = "Difesa della Torre",
  desc = "Mi è appena giunta notizia che il culto sta attaccando la torre di guardia del pilone, poco fuori città! Ho mandato i pochi peacekeepers che avevamo di riserva a tentare di aprirsi un varco tra le retrovie nemiche per soccorrere i difensori, ma per la nostra gente laggiù ogni aiuto in più potrebbe fare la differenza tra la vita e la morte.$B$BTi prego, parti subito per la torre di guardia orientale e fa' tutto quello che puoi.$B$BA guidare i rinforzi è la mia luogotenente, Yorana Windyreed. Se è ancora viva, potrà dirti come puoi essere più utile.",
  obj = "Presentati a Yorana Windyreed alla torre di guardia orientale, nelle Gustberry Lowlands.",
  reward = "Per ora li stiamo tenendo a bada, ma sono più numerosi di noi e i nostri combattenti cominciano a stancarsi. Dobbiamo trovare il modo di uscire da questo stallo, e in fretta.",
}
T[93429] = {
  title = "Sangue del Mio Sangue",
  desc = "I Lost Ones del Fallow Sanctuary sono nostri consanguinei, eppure sono diventati esseri di pura violenza e odio.$B$BPer loro non può esserci né redenzione né salvezza. Sono condannati a vagare per questa palude per tutta la vita, creature senza mente e piene d'odio.$B$BLa loro sofferenza deve finire: qualcuno deve liberarli dall'agonia. Lo so, è un compito macabro, ma lo faresti per proteggere quelli di noi che sono rimasti?",
  obj = "Uccidi 10 Lost Ones nel Fallow Sanctuary.",
  reward = "Grazie per aver protetto The Harborage e per aver tenuto le nostre mani lontane dal sangue della nostra gente.",
}
T[93430] = {
  title = "Riprendersi l'Esca",
  desc = "Stavolta l'hanno fatta grossa! Quei disgraziati davano già abbastanza problemi, e adesso uno di loro mi ha pure rubato la lucky lure!$B$BStamattina stavo pescando, quando uno è sbucato dal fango, mi ha tagliato la lenza ed è scappato con l'esca. Quasi di sicuro è uno dei pescatori dei Lost Ones, che conta di usarla per sé.$B$BBe', da quell'esca dipendono le nostre scorte di pesce, quindi devo riaverla. I Lost Ones pescano lungo le rive a est di qui. Trova quel ladro, $R!",
  obj = "Trova il Lost One Fisherman che ha rubato l'esca di Pelluk e riprenditela.",
  progress = "Senza la mia lucky lure non prendo niente! Qui fuori rischiamo di morire di fame.",
  reward = "È proprio lei! Oh, grazie, $R. Ogni tanto passa a trovarmi, e ti darò una parte del mio pescato!",
}
T[93459] = {
  title = "Altre Orecchie di Al'Aketh",
  desc = "Di solito il culto Al'Aketh si tiene alla larga da questa foresta, perché teme le voci che la dicono infestata... voci che siamo ben felici di alimentare. I Druidi del mio ordine desiderano solo vivere qui a Shadowgale una vita tranquilla e pacifica, e il culto la minaccia.$B$BMolti di noi hanno paura.$B$BVengo a farti un'offerta. Combatti i cultisti per noi e portaci le orecchie di quelli che uccidi. Per ognuna che ci riporterai ti ricompenseremo con del denaro e, col tempo, se ti dimostrerai $Gun vero amico:una vera amica;, ti daremo accesso ai nostri segreti.",
  obj = "Raccogli 10 Al'Aketh Cultist's Ears dagli Al'Aketh nella Shadowgale Forest, nello Shine of Akir o nei Gustberry Lowlands e riportale a Vayn Moonclaw nella Shadowgale Forest.",
  progress = "<Vayn ti fa un cenno con il capo.>",
  reward = "Come promesso, ecco la tua ricompensa.",
}
T[93461] = {
  title = "$GBenvenuto:Benvenuta; a Shen'dar Village",
  desc = "Hai proprio quell'aria da \"High Order\". Chi discende dagli Highborne sembra avere sempre un lieve scintillio negli occhi che lo tradisce. Prima che ti metta al lavoro sul serio, dovresti presentarti al nostro anziano dell'High Order, Rathiril Sunlance. Lo trovi qui nella loggia principale, appena girato l'angolo.$B$BOh, e passa anche da Coriella Calmbreeze: gestisce la locanda e può darti alloggio e provviste, se ti servono.",
  obj = "Parla con Rathiril Sunlance e Coriella Calmbreeze a Shen'dar Village.",
  progress = "Questo posto non è granché, ma è casa.",
  reward = "Allora ti sei $Gpresentato:presentata; a Rathiril? Bene. Di questi tempi c'è molta tensione fra l'High Order e i Windshapers, ma qui a Shen'dar si mantengono i toni civili. Be', almeno in paese. Quello che succede nelle terre selvagge resta nelle terre selvagge.$B$BOra che hai sbrigato questa faccenda, mi sembri il tipo che non ama stare con le mani in mano. Ci sono un paio di cose da fare: te la senti di lavorare un po'?",
}
T[93464] = {
  title = "Il Mago in Visita",
  desc = "Devo confessarti una cosa, $N. Il draenethyst è sacro per noi e ci mantiene sani di mente, eppure nessuno qui lo comprende fino in fondo.$B$BMi ricordo di un mago che una volta è arrivato all'Harborage da Desolace: un umano, si chiamava Azore. Temeva il potere del draenethyst e diceva che non doveva finire nelle mani sbagliate.$B$BAllora l'abbiamo cacciato via, per proteggere ciò che era nostro. Ultimamente però mi ritrovo a chiedermi che cosa sapesse di preciso.$B$BTi chiedo di trovare questo mago, $R. Quello che sa potrebbe esserci di immenso valore.",
  obj = "Trova a Desolace il mago che conosce il potere del draenethyst.",
  reward = "Draenethyst, dici? Sì, può darsi che ne sappia un paio di cose...",
}
T[93465] = {
  title = "Appunti sul Draenethyst",
  desc = "Credo che sia più esatto dire che conosco qualcuno che sa un paio di cose sul draenethyst.$B$BVedi, gli stregoni della Burning Blade lo stanno studiando. È una sostanza che viene da oltre il portale oscuro, quindi è logico che chi pratica le arti più oscure possa volerla piegare ai propri fini. Ovviamente non possiamo permetterlo.$B$BLa stregona che cerchi si chiama Gimashi, e la troverai in cima alla sua torre, in un burrone a sud-est. Nei suoi appunti ci saranno le risposte che ti servono.",
  obj = "Prendi gli appunti di Gimashi sul Draenethyst e riportali ad Azore Aldamort.",
}
T[93552] = {
  title = "Raccogliere le Windstones",
  desc = "Le Windstones sono una risorsa fondamentale su Zephras Isle, perché contengono l'energia grezza e concentrata dei venti stessi. Gli elementali del vento che vivevano qui con noi su Zephras sono scomparsi parecchi anni fa, e da allora la magia che sostiene quest'isola si sta lentamente esaurendo. Pur con i loro limiti, le windstones restano una fonte di energia affidabile, e per noi hanno un valore inestimabile.$B$BTroverai le windstones grezze sparse per il boschetto. Pensi di potermi aiutare a raccoglierle?",
  obj = "Raccogli 15 Windstone Clusters dalle Windstone Grezze in Thendal Grove.",
  progress = "Salve, $C.",
  reward = "Grazie davvero. Noi elfi abbiamo tutti un legame profondo con la magia, e queste windstones diventano sempre più preziose, man mano che il potere infuso nell'isola dai grandi piloni d'ancoraggio continua a svanire. $B$BLe Windstones non sono l'unica risorsa utile che si può ricavare da questa terra. Ecco, prendi uno di questi manuali.",
}
T[93585] = {
  title = "Questa Mia Luce",
  desc = "Oh, grazie al cielo, qualcuno di civile!$B$BSono qui per conto della Chiesa dell'Holy Light: devo prendere contatto con i draenei dell'Harborage. Vedi, qui l'Alleanza non ha nessun punto d'appoggio, e un po' di diplomazia con la gente del posto potrebbe darci una mano in questo. Dopotutto, la Luce accoglie tutti nel suo gregge!$B$BPerò oltre questo ponte la strada brulica dei parenti più selvaggi dei draenei, e per arrivare sano e salvo all'Harborage ho bisogno di protezione. Mi aiuteresti, $C?",
  obj = "Scorta Father Tuttle a The Harborage.",
}
T[93663] = {
  title = "Smarrito in Transito",
  desc = "I draenei dell'Harborage sono abili pescatori, pronti a pescare a strascico in acque più pericolose di quelle dove mi spingerei io. Ogni tanto facciamo scambi: loro ci danno parte del pescato e io offro un po' delle provviste che ci avanzano.$B$BAvevo mandato un corriere goblin a consegnare l'ultimo carico, ma non è più tornato. Sarà finito in pasto a un crocolisco.$B$BMa, soprattutto, è in gioco la mia reputazione negli affari. Quel carico va ritrovato e consegnato all'approdo. Ti prego, se puoi, trovalo: cerca vicino all'acqua, lungo la strada.",
  obj = "Trova il corriere scomparso e assicurati che il carico di Dar venga consegnato a Harborage.",
}
T[93678] = {
  title = "Appunti Riassunti sulla Draenetista",
  desc = "Ho trascritto gli appunti di Gimashi sulla draenetista. Pare che i frammenti abbiano una certa energia, ma una sfera pura di quella roba è di gran lunga più potente, e sembra che fosse proprio quella che cercava la Burning Blade.$B$BIn molti appunti Gimashi accenna a portali e a rituali di evocazione demoniaca. Dove portino quei portali, o quali demoni servano a evocare, non saprei dirlo con certezza.$B$BLe mie risposte non sono definitive, ma ti prego lo stesso di riportare questi appunti nella palude. Spero capirai se non vengo con te.",
  obj = "Riporta gli appunti trascritti di Azore a Magtoor a Harborage, in Swamp of Sorrows.",
}
T[93680] = {
  title = "Key to the City",
  desc = "L'Alleanza aveva un esercito di maghi, i Kirin Tor. Erano potenti, ma la demoniaca Burning Legion si è rivelata ancora più forte: l'arcidemone Archimonde ha raso al suolo la loro città in un colpo solo, come fosse un giocattolo. Chi è sopravvissuto non era più che un vagabondo senza casa.$B$BFinché non hanno ricostruito Dalaran. E per giunta proprio alle porte della Dama Oscura!$B$BQuando sarai nei loro accampamenti, cerca qualcosa che ci faccia entrare in città senza farci notare. Devo saperne di più.",
  obj = "Procurati la Dalaran Sewer Key per Magus Wordeen Voidglare a Tarren Mill.",
  progress = "Cos'hai trovato? Un tomo antico? Una reliquia segreta?",
  reward = "Una chiave delle fogne? Beh, meno male che non toccherà a me usarla.$B$BPrima di servircene senza rischi, però, abbiamo del lavoro da fare.",
}
T[93689] = {
  title = "$GAmico:Amica; del Kirin Tor",
  desc = "È un'ottima notizia! Ora che a Dalaran è tornata la pace, non vedo perché il Kirin Tor non dovrebbe accoglierti a braccia aperte!$B$BTi prego, presentati al consiglio il prima possibile. Sono $Gcerto:certa; che non vedranno l'ora di conoscere $Gil salvatore:la salvatrice; della città.",
  obj = "Parla con Archmage Celindra in City of Dalaran.",
}
T[93735] = {
  title = "Il Costrutto Rotto",
  desc = "I Windshapers si sono sempre presi cura degli strumenti e dei congegni magici che ci hanno donato gli spiriti del vento, compresi i tanti costrutti magici sparsi per l'isola. Da quando gli spiriti ci hanno lasciati, ne funzionano ancora pochissimi.$B$BUno dei pochi rimasti in funzione a Valanaar si è danneggiato. Abbiamo mandato uno dei nostri artigiani a occuparsene, ma potrebbe avere bisogno di una mano. Raggiungi l'estremità occidentale della città e aiutalo in tutto quello che puoi.",
  obj = "Trova Riaani Nightwind nella parte occidentale di Valanaar.",
  reward = "<Riaani ha la faccia sepolta sotto le pesanti piastre dell'armatura del costrutto e cerca di lavorare ai meccanismi che ci sono sotto. Non si accorge minimamente di te.>$B$BMaledette tempeste — dov'è il nucleo?! A chi è venuto in mente di togliere anche il Girozefiro? È un miracolo che i venti di questo costrutto non si siano ancora dissolti del tutto!",
}
T[93736] = {
  title = "Spiriti Indesiderati",
  desc = "Ai Windshapers preme soprattutto capire meglio perché gli spiriti ci hanno lasciati, e cosa potremmo fare per riportarli indietro. Nella Shadowgale Forest, a nord, c'è una cosa curiosa: una strana forma di spiritello del vento che alcuni chiamano \"cavità\". Sappiamo poco di loro e del perché si trovino lì, ma una cosa è certa: hanno cominciato a comparire dopo che gli spiriti del vento se ne sono andati.$B$BHo bisogno che tu ci vada e li disperda. Raccogli i loro resti e portameli.",
  obj = "Raccogli 10 Wind Hollow Essences dalle Wind Hollows nella Shadowgale Forest.",
  progress = "La Shadowgale Forest è un posto pericoloso. C'è perfino chi dice che sia infestata. Sono piuttosto sicura di non crederci, ma so bene che non fa per i deboli di cuore, né per chi ci arriva impreparato.",
  reward = "Toccare queste essenze mi riempie di una sensazione di... profonda inquietudine. Mi sembra quasi di sentire un'aura malvagia, piena di rimpianto, che emana da loro. C'è da svenire.$B$B<Endaria rabbrividisce appena.>$B$BNon ho nessuna voglia di studiarle ancora.",
}
T[93737] = {
  title = "Il Costrutto Rotto",
  desc = "Oh, ciao. Ti manda Ayessa ad aiutarmi? Va bene, allora.$B$BSi vede lontano un miglio che sei $Gun:una; $Gnovellino:novellina;, e non so cosa tu possa fare, ma se mi dai un attimo per tirare fuori la testa dalle viscere di questo costrutto, forse mi verrà in mente qualcosa in cui puoi darmi una mano.",
  obj = "Parla con Riaani Nightwind e ascolta cosa ha da dire.",
  progress = "Non riesco a immaginare perché qualcuno voglia rubare questi componenti al costrutto. Tranne il girozefiro, non servono quasi a niente, e perfino il giro sarebbe quasi inutile fuori dallo scopo per cui è stato fatto.",
  reward = "Grazie per aver recuperato questi materiali. Immagino che procurarsene alcuni non sia stato facilissimo.$B$BCon questi pezzi posso rimettere in funzione il costrutto. Poi non ci resta che sperare che abbia la memoria intatta e che possa dirci chi gli ha preso i componenti.",
}
T[93738] = {
  title = "Il Costrutto Rotto",
  desc = "Brightwish, eh? Quindi l'High Order voleva togliere questi componenti per qualche motivo. Ma perché?$B$BL'High Order è sempre stato invadente, sempre lì a voler sperimentare con la magia degli spiriti del vento. Sono fin troppo audaci: gli abbiamo severamente proibito di immischiarsi nelle conoscenze che spettano ai Windshaper, ma ultimamente stanno mettendo alla prova la nostra pazienza.$B$BCredo che dovresti riferire ad Ayessa Dawnsinger quello che hai scoperto: lei saprà dirti cosa fare.",
  obj = "Torna da Ayessa Dawnsinger a Valanaar.",
  reward = "Molto interessante, quindi era l'High Order il responsabile del guasto del costrutto?$B$BConosco Belathaan: è il cugino di Valennia Stormfist, e sua madre era una Windshaper. Mi delude che sia stato coinvolto in questa storia.$B$BDevo pensarci un momento.",
}
T[93739] = {
  title = "Esplorare l'Orda",
  desc = "Azeroth è un mondo grande, e il territorio dell'Orda è vasto. The Undercity, Orgrimmar e Thunder Bluff hanno popoli e culture davvero unici.$B$BSe sarai ospite dell'Orda qui su Azeroth, faresti bene a visitare le nostre capitali, una dopo l'altra. Per le indicazioni, parla con il mio consigliere Nazgrel.",
  obj = "Parla con Nazgrel nella Grommash Hold per ricevere altre istruzioni. Usa le istruzioni ricevute per trovare Vol'jin, Cairne Bloodhoof e Lady Sylvanas Windrunner e parlare con loro.",
  reward = "Dunque sei $Gtornato:tornata;. Spero che il viaggio ti abbia insegnato molto.$B$BA quanto mi risulta, il tuo popolo si sta ancora stabilendo a Mulgore. Nell'attesa ti consiglio di esplorare i dintorni di Orgrimmar. The Barrens, in particolare, hanno sempre bisogno di avventurieri volenterosi come te.",
}
T[93740] = {
  title = "Sangue per Sangue",
  desc = "Stamattina, negli Altopiani, sono stati trovati morti alcuni dei nostri novizi Windshaper. Certezze non ne abbiamo, ma con ogni probabilità sono stati gli Al'Aketh. E i Windshapers il sangue lo ripagano col sangue, ogni volta.$B$BVa' a nord e uccidi ogni Al'Aketh che incontri. A prova dell'impresa, portami i loro talismani di preghiera windstone. Noi non perdoniamo e non dimentichiamo.",
  obj = "Raccogli 10 Al'Aketh Windstone Charms dai cadaveri dei cultisti Al'Aketh nei Gustberry Lowlands.",
  progress = "Per troppo tempo gli Al'Aketh si sono abbandonati al fanatismo sanguinario. E questo è solo l'inizio della resa dei conti che li aspetta.",
  reward = "<Ayessa ha l'aria scossa e assente mentre le consegni i talismani windstone.>$B$BNon badare a me, $N. Oggi è stata solo... una giornata dura. Grazie per i servigi che finora hai reso ai windshapers.",
}
T[93746] = {
  title = "Una Risposta Ferma",
  desc = "L'High Order è stato avvertito di cosa succede a chi si immischia negli affari dei Windshaper. Secondo me dobbiamo dare a Belathaan una lezione esemplare e rispedirlo all'High Order con qualche livido e un sano rispetto per i limiti che abbiamo fissato.$B$BBelathaan è stato visto uscire dalla città diretto a nord, verso lo Shrine of Akir. Non so perché ci stesse andando, ma la cosa più sicura è affrontarlo lungo la strada, finché è solo. Trovalo e mettigli un po' di paura in corpo.",
  obj = "Affronta Belathaan Brightwish lungo la strada per lo Shrine of Akir.",
  reward = "Aspetta — cosa?! Belathaan... è morto?$B$B<Ayessa ascolta mentre le racconti cosa è successo.>$B$BL'High Order si incontrava con gli Al'Aketh per discutere di pace? Con il culto non c'è pace, sono fanatici assassini. Come ha potuto Elaadrin mandare Belathaan a trattare con loro da solo?$B$BNon pensarci, $N. Non è colpa tua. La colpa, ancora una volta, è dell'arroganza dell'High Order. Ti sei solo $Gtrovato:trovata; nel posto giusto al momento sbagliato.",
}
T[93791] = {
  title = "Parla con Belann",
  desc = "$N, è chiaro che le tue capacità magiche stanno crescendo, e credo sia giunto il momento che tu prenda parte a una delle più antiche tradizioni che l'High Order riserva ai giovani aspiranti maghi. È ora che tu crei un focus magico tutto tuo.$B$BCerca Belann Windwood a Valanaar. Da più di un secolo costruisce bastoni e bacchette per l'High Order, quindi sarai in buone mani.",
  obj = "Parla con Belann Windwood a Valanaar.",
  reward = "Ah, devi essere $N, giusto? È confortante vedere giovani maghi desiderosi di imparare le nostre usanze e la nostra storia. Vieni, ti spiego come procedere per realizzare il tuo focus magico.",
}
T[93797] = {
  title = "Rami nel Vento",
  desc = "Da secoli è tradizione che i giovani maghi, quando hanno dato prova di una certa padronanza della magia, si creino un focus tutto loro. Di solito si raccoglie un ramo caduto dai nostri alberi più antichi, perché conservano ancora qualche traccia di vento elementale.$B$BHo scoperto che i rami migliori si trovano vicino al santuario del vento, appena a sud di Falaath Village. Va' e portamene uno bello grosso: mentre realizziamo il tuo focus magico, ti insegnerò le nostre usanze.",
  obj = "Porta un Wind-Infused Bough a Belann Windwood a Valanaar.",
  progress = "Di anno in anno, a Zephras ci sono sempre meno persone portate per la magia. $B$BSono lieto di vedere giovani maghi come te prendere parte alle nostre tradizioni più antiche e contribuire così a tenere vive la nostra storia e la nostra cultura.",
  reward = "Grazie, $N. In questo legno sento chiaramente le energie elementali, che aspettano solo di essere imbrigliate da chi ne ha il dono. Ne verrà fuori un eccellente focus magico.$B$BForse questo ramo ti ha chiamato con il suo canto? Spesso è il ramo a scegliere $Gil:la; $C, e non il contrario.$B$B<Belann ridacchia e te lo prende delicatamente dalle mani.>",
}
T[93835] = {
  title = "Affronta Lorthuna",
  desc = "Pochi istanti fa Lorthuna è fuggita nelle guglie qui sopra attraverso una specie di portale, e Ayessa ed Elaadrin l'hanno seguita oltre.$B$BTemo di aver preso un colpo di troppo: io mi fermo qui. Tu attraversa il portale, trova Elaadrin e aiutali a fermare Lorthuna.$B$BElaadrin e Ayessa dicono di aver mandato a chiamare aiuto, ma se non arriva presto, da qui in poi sei $Gsolo:sola;. Buona fortuna, $C.",
  obj = "Prendi il portale per le Rohashi Spires sovrastanti e raggiungi Elaadrin Evengale e Ayessa Dawnsinger nel loro scontro con High Priestess Lorthuna.",
  reward = "Ho mandato alcuni dei maghi che ci sono rimasti a fare in modo che anche Valennia e le sue forze riuscissero a fuggire. A quest'ora dovrebbe riposare nella residenza di High Elder Shadowsong.$B$BAnsirem è dovuto tornare su Azeroth, ma prima di partire abbiamo discusso insieme le prossime mosse dell'High Order. Siamo sopravvissuti a questa giornata, ma ora Zephras è pericolosamente vulnerabile e dobbiamo decidere come affrontare ciò che verrà.",
}
T[93836] = {
  title = "Il Destino di Zephras",
  desc = "Muln mi ha raccontato molto dei signori elementali, e purtroppo abbiamo buoni motivi per temere Al'Akir. Ora che sono cadute le protezioni che nascondevano Zephras ai suoi occhi, siamo del tutto indifesi. Se decide di attaccarci, qui, nel suo stesso dominio, contro di lui non abbiamo nessuna speranza.$B$BHigh Elder Shadowsong deve sapere in che pericolo siamo e, soprattutto, cosa intendiamo fare con la missione su Azeroth. Troveremo il modo di salvare la nostra casa. Lo giuro.",
  obj = "Parla con Talaanis Shadowsong a Valanaar.",
  reward = "<Talaanis Shadowsong ascolta con attenzione mentre gli racconti cosa è accaduto sopra lo Shrine of Akir e gli parli del piano di Ayessa di lasciare Zephras Isle.>$B$BDevo rifletterci ancora. Di buono, però, c'è che ci siamo liberati di Lorthuna e abbiamo tolto al culto il suo capo. La nostra casa non è ancora stata invasa e, con i tempi degli dèi elementali, potrebbero passare anni... persino decenni, prima che Al'Akir si degni di rivolgere a noi la sua attenzione.$B$BOra c'è molto da temere, ma anche molto da festeggiare.",
}
T[93926] = {
  title = "La Torre di Guardia Occidentale",
  desc = "Qualunque ragione abbia il culto per attaccare la torre, non vale la pena di perdere la nostra gente.$B$BVorrei che andassi a sud-ovest a controllare quella torre di guardia. Lì troverai i peacekeepers: di' loro di tornare al villaggio. Tenere quella posizione non vale le vite che costerebbe: preferisco concentrare qui i difensori che abbiamo, per proteggere i cittadini.$B$BA comandarli è il Peacekeeper Vaaniel: digli di rientrare il più in fretta possibile. Sbrigati!",
  obj = "Trova il Peacekeeper Vaaniel alla torre di guardia occidentale.",
  reward = "<Il corpo è ancora piuttosto fresco: evidentemente è morto da poco. A giudicare dalle ustioni e dai segni di bruciature sulla pelle del peacekeeper, l'hanno ucciso gli incantatori del culto che comandano le tempeste.>",
}
T[93927] = {
  title = "Un'Ultima Richiesta",
  desc = "<Mentre esamini il corpo del peacekeeper morto, un biglietto insanguinato gli scivola dalle mani. Se lo raccogli e lo leggi, potresti trovarci un indizio su come procedere.>",
  obj = "Raccogli il biglietto che hai trovato vicino al peacekeeper morto e leggilo per capire cosa fare.",
  progress = "Che notizie dalla torre di guardia occidentale?",
  reward = "Allora sono tutti morti. Che le tempeste maledicano quei bastardi del culto!$B$BAnche se sei $Griuscito:riuscita; a eliminare il sacerdote e a fermare i cultisti alla torre, confesso che ora mi preoccupa il doppio quello che, da quanto mi hai detto, stavano facendo al pilone. Se avevano con sé una scorta così enorme di windstones, vuol dire che per farlo gli serviva un'energia immensa.$B$BMi chiedo quale sia il loro vero scopo. Profanare il pilone, attaccare il villaggio? A che pro?",
}
T[93928] = {
  title = "Di Topi e Latte",
  desc = "Mi serve un biscotto, capito?$B$BNyeah!",
  obj = "Porta un biscotto al topo.",
  reward = "(PH) Grazie!",
}
T[93948] = {
  title = "Consegna il Sigillo",
  desc = "Visto che vai comunque a Valanaar, per favore consegna a Talaanis Shadowsong, che è a Valanaar, l'anello con il sigillo che hai recuperato dalla torre.$B$BVorrà riaverlo e, soprattutto, vorrà sapere che fine ha fatto suo nipote. Talaanis è il Sommo Anziano di Zephras Isle e, cosa ancora più importante, è un brav'uomo, molto amato dalla gente nonostante le difficoltà di questi tempi. Mi addolora pensare a come prenderà la notizia. Per favore, porgigli le mie condoglianze.",
  obj = "Consegna lo Shadowsong Family Signet a Talaanis Shadowsong a Valanaar.",
  progress = "Cos'hai per me? Oh... oh, no.",
  reward = "Mi... dispiace tanto sapere che mio nipote è morto. Grazie di cuore per averlo recuperato e per avermelo portato.$B$BNon capita spesso che dalle alture scendano giovani shen'dorei così capaci. Se cerchi lavoro, parla con Valennia Stormfist, il capitano dei peacekeepers qui a Valanaar. Di questi tempi ci serve tutto l'aiuto che possiamo trovare.",
}
T[93949] = {
  title = "Cimici",
  desc = "Ci hanno messo le cimici.$B$BNelle pianure è la stagione degli skyhopper, e quelle bestiacce sono dappertutto. Un mago dell'High Order ci ha riferito che su uno degli insetti che ha ucciso c'era una specie di incantesimo. Esaminandolo da vicino, ci è sembrato un incantesimo per origliare.$B$BSospettiamo che il culto usi questi insetti incantati come spie. Va' a sterminarli per noi. A occhio non riuscirai a distinguere quelli incantati, quindi non ti resta che ucciderli tutti.",
  obj = "Uccidi gli Skyhopper a Valanaar finché non avrai eliminato 8 Enchanted Skyhoppers.",
  progress = "Sono una guerriera di professione da più di trecento anni. Ho visto cose che non potresti nemmeno immaginare, eppure... Odio. Davvero. Gli insetti.",
  reward = "Senz'altro a Valanaar ci sono ancora altre di queste bestiole, ma ogni skyhopper incantato che schiacciamo rende la città un pochino più sicura.",
}
T[93951] = {
  title = "Un Pizzico di Bellezza",
  desc = "Gli ippogrifi che si sono stabiliti a sud-ovest del villaggio possono essere una seccatura, ma offrono anche un'occasione davvero unica per procurarsi le loro piume. Molti skyborne adorano ornarsi i capelli con vibrant plumes, e il piumino degli ippogrifi ha colori straordinariamente accesi e, soprattutto, è morbido come la seta.$B$BSe vai da quelle parti, cerca di raccogliere quante più piume cadute riesci intorno ai loro nidi. Ma fai attenzione: gli ippogrifi selvatici non gradiscono le visite.",
  obj = "Raccogli 8 piume di Hippogryph Down nelle Shen'dar Highlands.",
  progress = "Che belle cose mi hai portato?",
  reward = "Raccogliere piume per i capelli può sembrare una frivolezza un po' vanitosa. Eppure, anche in tempi come questi, bisogna godersi il più possibile le piccole gioie. $B$BSe anche una sola cosa che creo rende felice qualcuno, allora per me è stata una buona giornata. Grazie di avermi portato queste piume e di avermi aiutata a regalare un po' di allegria a Zephras.",
}
T[93958] = {
  title = "Il Santuario Interno",
  desc = "Le forze di Valennia sono appena riuscite a sfondare nel santuario interno. All'inizio, lì dentro, la battaglia era dura, ma adesso c'è un silenzio... inquietante. Entra e fa' il possibile per arrivare a Valennia e alle sue forze... ammesso che ne sia rimasto qualcuno.$B$BIo rimango qui a guardarti le spalle.",
  obj = "Parla con Valennia Stormfist nel santuario interno dello Shrine of Akir.",
  reward = "<Valennia sembra ferita in modo grave.>",
}
T[93963] = {
  title = "Alla Scoperta dell'Alleanza",
  desc = "Stormwind, Ironforge e Darnassus hanno ciascuna popoli e culture tutti propri. Sei ospite dell'Alleanza qui su Azeroth: dovresti prenderti il tempo di visitare le nostre capitali, una dopo l'altra.$B$BPer avere le indicazioni con cui cominciare, parla con Randal Emerson nell'anticamera meridionale.",
  obj = "Parla con Randal Emerson in Stormwind Keep per ricevere altre istruzioni. Segui le istruzioni ricevute per trovare King Magni Bronzebeard, High Tinker Mekkatorque e Tyrande Whisperwind e parlare con loro.",
  reward = "Ah, sei $Gtornato:tornata;.$B$BSpero che le tue avventure ti abbiano fatto capire quanto è grande e pieno di meraviglie il nostro mondo. So che deve sembrarti travolgente, ma se vuoi aiutare la tua gente devi essere $Gpronto:pronta; a tutto quello che potrebbe capitarti qui su Azeroth.$B$BNell'attesa che il tuo ordine si stabilisca a Dalaran, ti suggerisco di rivolgere l'attenzione alle terre intorno a Stormwind. A Westfall, soprattutto, servono sempre altri avventurieri forti che le diano una mano, se sei $Gdisposto:disposta;.",
}
T[94003] = {
  title = "Lo Skybreaker Bulwark",
  desc = "Della stirpe degli Skybreakers, qui su Zephras Isle, sono rimasta solo io. Gli altri li hanno assassinati gli Al'Aketh.$B$BPiù grande del mio dolore c'è solo la vergogna. Lo scudo ancestrale della mia famiglia — lo Skybreaker Bulwark — ora è nelle mani di un cultista di nome Zaal Stormshield. Nella mia famiglia si tramanda che nessun male possa colpire chi impugna questo scudo ed è degno di farlo.$B$BZaal non ne è degno, di questo sono certa. Trova quell'uomo allo Shrine of Akir e riprendigli il mio scudo. Fallo, e ti insegnerò la Difesa Skybreaker.",
  obj = "Recupera lo Skybreaker Bulwark da Zaal Stormshield allo Shrine of Akir.",
  progress = "<Seena ti rivolge un secco cenno del capo.>",
  reward = "Hai fatto quello che io non ho potuto fare, e hai ridato l'onore alla mia famiglia. Per questo ti farò un dono che pochi, su Zephras, sono degni di ricevere: ti insegnerò i segreti della Difesa Skybreaker.$B$BE per mettere in pratica quello che ho da insegnarti ti servirà uno scudo. Ti prego, prendi questo. Ora che lo Skybreaker Bulwark mi è stato restituito, mi serve a poco.$B$BBanu'Adoraah, $Gamico:amica;.",
}
T[94004] = {
  title = "Craftsman's Writ: Elixir of Ogre's Strength",
  desc = "<La nota, scritta con un inchiostro ormai sbiadito, chiede 1 Elisir della Forza dell'Ogre e spiega dove consegnarlo e come verrà pagato. In fondo, una riga avverte che il mandato si può trasferire.>",
  obj = "Procurati gli oggetti che chiede il cliente e consegnali nel luogo segnato sulla mappa. Per concludere la transazione devi avere con te questo mandato.",
  progress = "Che?",
  reward = "Tu portato elisir!! Grazzie, $R. Tu fatto tutta questa strada per aiutare Sos'mol. Mai nessun ogre fatto questo prima. Sos'mol ricordare questo. Un giorno ripagare te. Me promette.",
}
T[94006] = {
  title = "Il Grande Spirito Ursera",
  desc = "Salute, $N. Hai fatto abbastanza progressi negli studi druidici: credo sia giunto il momento di incontrare uno dei grandi spiriti che dimorano qui su Zephras. Urs'endris è saggio e nobile, e da generazioni insegna ai druidi ad assumere la forma di ursera. Purtroppo il suo dominio ha cominciato ad avvizzire e a precipitare nel cielo, come molte altre zone di Zephras.$B$BPer trovarlo, dirigiti a nord-est, vicino alla cascata all'ombra dello Shrine of Akir. Saprà darti altre istruzioni.",
  obj = "Parla con Urs'endris vicino alle cascate a nord-est di Valanaar.",
  reward = "Dunque desideri abbracciare la via dell'artiglio, $Gfiglio mio:figlia mia;? Molto bene. Parliamone.",
}
T[94007] = {
  title = "Domare la Bestia",
  desc = "Adesso che nelle terre selvagge degli altopiani hai cominciato a sentirti a tuo agio, credo sia arrivato il momento di cercarti un compagno animale tutto tuo.$B$BRaggiungi il porto di Valanaar, a sud-est, e parla con Quel'ana Quickgale: ti insegnerà l'arte di domare le bestie.",
  obj = "Fai rapporto a Quel'ana Quickgale a Valanaar.",
  reward = "Sono proprio $Glieto:lieta; che tu sia $Gvenuto:venuta;. Avanti, cominciamo.",
}
T[94013] = {
  title = "Addomesticare la Bestia",
  desc = "Hai addomesticato due bestie e sei $Gtornato:tornata; trionfante. Ora viene l'ultima prova: i venti di Zephras sussurrano di sfide più grandi che ti attendono. Prendi questo Taming Rod e va' nei Gustberry Lowlands. Lì addomestica un Vuldren Alpha e mostra la tua maestria. Supera questa lezione e sarai $Gpronto:pronta; a conoscere più a fondo le vie del cacciatore.",
  obj = "Usa il Taming Rod per addomesticare un Vuldren Alpha nei Gustberry Lowlands. Esercita le tue capacità, poi riporta il Taming Rod a Quel'ana Quickgale a Valanaar.",
  progress = "Imparerai, $N. Un giorno sarai $Gun:una; grande $C.",
  reward = "Eccellente, $N! Impari davvero in fretta. Ora che le basi le conosci, posso insegnarti a stringere con un compagno animale un legame che duri. Porta con te quello che hai imparato, e prospera. Sii $Gil:la; $C di cui Zephras Isle ha bisogno.",
}
T[94050] = {
  title = "Addestrare la Bestia",
  desc = "Ora hai il potere di addomesticare un famiglio, ma devi anche imparare ad addestrarlo, e in questo nessuno è più bravo di mia sorella, Quel'dora: sarà lei a insegnartelo. Va' con i venti, giovane $C.",
  obj = "Parla con Quel'dora Quickgale a Valanaar.",
  reward = "$GUn:Una; $C alle prime armi, vedo. Sì, posso concederti le capacità che ti servono per addestrare e guidare il tuo famiglio. Non potrai solo insegnargli nuove abilità: da ora potrai anche nutrirlo, e rianimarlo se dovesse cadere in battaglia. Ricorda, $N: rispetta sempre l'equilibrio e guarda con meraviglia la natura intorno a te. Ora va'. Torneremo a parlarci più avanti.",
}
T[94212] = {
  title = "Craftsman's Writ: Elixir of Wisdom",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Elixir of Wisdom e dà indicazioni sul luogo di consegna e sul pagamento. In fondo c'è scritto che la commissione si può trasferire.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questa commissione.",
  progress = "Vieni a scaldarti vicino al fuoco.",
  reward = "Lo ammetto, pensavo che i venti infidi degli altopiani avrebbero fatto a brandelli quella lettera. Non avrei mai creduto che qualcuno notasse la mia umile richiesta, figuriamoci che venisse a consegnarmela di persona.$B$BIl tuo è un impegno gentile e ammirevole, $R. Questo elisir mi sarà d'aiuto nella meditazione.$B$BSe ti va, fermati pure a raccontarmi qualche storia dei tuoi viaggi. La compagnia mi fa piacere.",
}
T[94213] = {
  title = "Craftsman's Writ: Lesser Mana Potion",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Lesser Mana Potion e dà indicazioni sul luogo di consegna e sul pagamento. In fondo c'è scritto che la commissione si può trasferire.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questa commissione.",
  progress = "Buongiorno, $R. La compagnia mi è gradita, ma ho la mente altrove. Se non abbiamo affari da sbrigare, ti prego di riprendere la tua strada.",
  reward = "Ah, è questa la pozione che avevo chiesto?$B$B<L'elfa ti prende la fiala dalle mani con rispetto.>$B$BArrivi al momento giusto, e la tua generosità mi è molto gradita. La accetto, e in cambio ti offro un piccolo segno della mia gratitudine.$B$BGrazie, spero di rivederti.",
}
T[94214] = {
  title = "Craftsman's Writ: Shadow Protection Potion",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Shadow Protection Potion e dà indicazioni sul luogo di consegna e sul pagamento. In fondo c'è scritto che la commissione si può trasferire.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questa commissione.",
  progress = "Ehilà, tienilo a mente per la prossima volta: non si corre a tutta velocità incontro a un goblin con la guardia del corpo! Non si sa mai come va a finire.",
  reward = "D'altra parte, con un ordine urgente come questo da evadere, non posso darti torto se vuoi incassare il guadagno.$B$BEcco qua, $Gamico:amica;. Grazie per aver procurato a un goblin le shadow protection potions di cui aveva tanto bisogno. L'hai VISTO cosa succede da queste parti?",
}
T[94215] = {
  title = "Craftsman's Writ: Free Action Potion",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Free Action Potion e dà indicazioni sul luogo di consegna e sul pagamento. In fondo c'è scritto che la commissione si può trasferire.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questa commissione.",
  progress = "<Ti avvicini a una creatura che si dimena, chiaramente prigioniera della seta di ragno, proprio nel punto che la commissione segnava sulla mappa.>",
  reward = "<Senza perdere tempo, porgi alla massa che si contorce la Free Action Potion richiesta. Sembra che non si accorga di te, o che non riesca a prendere l'oggetto.$B$BAccanto al bozzolo ci sono alcune monete sparse. Puoi decidere di lasciare lì la pozione e tenerti le monete: in quel caso, la natura farà di sicuro il suo corso.>",
}
T[94216] = {
  title = "Craftsman's Writ: Elixir of Lesser Agility",
  desc = "<La nota, scritta con inchiostro sbiadito, richiede 1 Elixir of Lesser Agility e riporta il luogo di consegna e il pagamento. In fondo si legge che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Devi avere con te questo ordine per completare la transazione.",
  progress = "Sei qui per...$B$B<Ziz si guarda intorno con sospetto nella sua minuscola capanna e abbassa la voce.>$B$BL'elisir?",
  reward = "<Ziz continua a parlare sottovoce.>$B$BNon ti farò tutta la tiritera su come sono finito qui, però un consiglio te lo do.$B$BA volte, per fare colpo sul nuovo capo, basta prendersi il merito del lavoro di un altro. Quindi tu mi consegni l'elisir, e io racconterò quanto sangue, sudore e lacrime ci ho versato per prepararlo.$B$BÈ un lavoro nuovo, ok? Devo fare una buona prima impressione!",
}
T[94217] = {
  title = "Craftsman's Writ: Lesser Troll's Blood Elixir",
  desc = "<La nota, scritta con inchiostro sbiadito, richiede 1 Lesser Troll's Blood Elixir e riporta il luogo di consegna e il pagamento. In fondo si legge che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Devi avere con te questo ordine per completare la transazione.",
  progress = "Yarr, ce l'hai l'elisir?",
  reward = "Proprio quello che ha ordinato Short John Mithril!$B$BEccoti le monete. Fossi in te me le stringerei al petto mentre sgattaioli fuori di qui: i combattenti dell'arena hanno sete di ricchezze quanto di sangue!",
}
T[94218] = {
  title = "Craftsman's Writ: Elixir of Defense",
  desc = "<La nota, scritta con inchiostro sbiadito, richiede 1 Elixir of Defense e riporta il luogo di consegna e il pagamento. In fondo si legge che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Devi avere con te questo ordine per completare la transazione.",
  progress = "Se $Gl'assassino:l'assassina; di cui l'equipaggio continua ad avvertirmi sei TU, beh, ti conviene pensarci due volte prima di scagliarti contro di ME, $Gbello:bella;!",
  reward = "Oh, oh!! L'elisir!$B$BOh, cielo. Scusami tanto se me la sono presa con te così. Sono sulle spine da quando mi hanno detto che uno di quei goblin avrebbe messo una taglia su di me!$B$BPurtroppo altra protezione non posso permettermela, quindi non mi resta che scolarmene uno e sperare in bene. Salute!",
}
T[94219] = {
  title = "Craftsman's Writ: Draught of Water Breathing",
  desc = "<La nota, scritta con inchiostro sbiadito, richiede 1 Draught of Water Breathing e riporta il luogo di consegna e il pagamento. In fondo si legge che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Devi avere con te questo ordine per completare la transazione.",
  progress = "Se sei $Gun:una; cliente, ho brutte notizie per te. Un nano si è comprato tutto quello che mi restava! Adesso aspetto rifornimenti da lontano.$B$BPerò se ti servono empty vials, sei nel posto giusto!",
  reward = "Se pensi di accamparti qui nelle notti di pioggia, le pozioni di respirazione acquatica sono indispensabili. Di solito faccio i pisolini sotto quel ponte laggiù, ma ogni tanto lì sotto si allaga.$B$BOra posso dormire sonni tranquilli, perché so che gli incubi in cui annego restano incubi e basta.$B$BA pensarci bene, forse avrei dovuto ordinarne qualcuna da rivendere...",
}
T[94220] = {
  title = "Craftsman's Writ: Pearl-Handled Dagger",
  desc = "<La nota, scritta con inchiostro sbiadito, richiede 1 Pearl-Handled Dagger e riporta il luogo di consegna e il pagamento. In fondo si legge che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Devi avere con te questo ordine per completare la transazione.",
  progress = "Avvicinarsi a me di soppiatto non è saggio, $R. Parla in fretta, e parla piano.",
  reward = "Oh, mi porti il pugnale? Ah, allora immagino che la mia sia stata una minaccia a vuoto, eh?$B$BCon i compiti che ho qui devo stare sempre in massima allerta, soprattutto con alt — ehm, il vile Syndicate che si aggira in altri punti della zona.$B$BOra saresti così gentile da consegnarmi la lama? Devo tornare al lavoro.",
}
T[94221] = {
  title = "Craftsman's Writ: Golden Rod",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Golden Rod e riporta le indicazioni per la consegna e il pagamento. In fondo c'è scritto che questo ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo ordine.",
  progress = "<Il nano sembra perso in una profonda meditazione, ma il tuo arrivo l'ha distratto. Per fortuna ti accoglie con un sorriso.>",
  reward = "Ah, la Golden Rod che avevo chiesto. Pensavo che non sarebbe mai arrivata. Stavo già valutando di tornare a Ironforge per comprarne una alla casa d'aste. Mi hai risparmiato un viaggio, e questi vecchi piedi ti ringraziano di cuore.$B$BAncora non so come potrò usarla per entrare in contatto con le Pietre del Vincolo, e neppure se ci riuscirò, ma ho il sospetto che mi avvicini di un passo.$B$BNel peggiore dei casi, be', mi tengo volentieri un bastone nuovo.",
}
T[94222] = {
  title = "Craftsman's Writ: Iridescent Hammer",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 1 Iridescent Hammer e spiega dove consegnarlo e come verrà pagato. In fondo c'è scritto che questo mandato è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo mandato.",
  progress = "AHHH! Oh... Me pensato tu essere mostro di melma.",
  reward = "Questo mio nuovo martello?<Il peon ti strappa l'arma di mano prima che tu possa rispondere e la agita all'impazzata verso di te, e per poco non ti spacca il cranio.>SÌ! Ora me reagisce. Questo me non perde, no no. Tu prendi questo. Me non sa a che serve, ma è caduto da creatura di melma.",
}
T[94223] = {
  title = "Craftsman's Writ: Silver Skeleton Key",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Silver Skeleton Key e spiega dove consegnarla e come avverrà il pagamento. In fondo una scritta dice che quest'ordine si può trasferire.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te quest'ordine.",
  progress = "<Seguendo le istruzioni dell'ordine, finisci nel profondo di una cripta, $Gcircondato:circondata; dai non morti. Su un baule lì accanto c'è un biglietto.>Chiunque legga per primo queste righe sarà il primo a sapere che sono morto. Sono un semplice custode del Raven Hill Cemetery, e persino i miei padroni a Darkshire si sono quasi scordati di me. Non ho eredi a cui lasciare le mie immense ricchezze, così le ho nascoste in questa cassa, per chi o cosa riuscirà ad aprirla.",
  reward = "<Le orde di non morti continuano ad ammassarsi qui intorno e di altri non c'è traccia, così decidi di aprire il baule senza fatica con la tua Silver Skeleton Key. Con tutte quelle promesse di ricchezze straordinarie, il baule è quasi vuoto. Se non altro, c'è abbastanza per coprire parte del costo di questa disavventura.>",
}
T[94224] = {
  title = "Craftsman's Writ: Heavy Bronze Mace",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Heavy Bronze Mace e riporta le indicazioni per la consegna e il pagamento. In fondo c'è scritto che questo ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo ordine.",
  progress = "Shh. Parla piano. Non sono ancora $Gpronto:pronta; per combattere.",
  reward = "Caspita. Sei $Garrivato:arrivata; ben $Gpreparato:preparata;! Spero che quella mazza sia per me, a meno che tu non voglia combattere TUTTE le battaglie.",
}
T[94225] = {
  title = "Craftsman's Writ: Rough Bronze Leggings",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Rough Bronze Leggings e riporta le indicazioni per la consegna e il pagamento. In fondo c'è scritto che questo ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo ordine.",
  progress = "Che c'è?",
  reward = "Sono le gambiere che avevo ordinato, eh? \"Da tre a cinque giorni lavorativi\", dicevano. Macché, da tre a cinque MESI lavorativi!$B$BLe ho ordinate quando lavoravo per la Venture Co là fuori, e te lo dico io, quel rapporto è finito da un pezzo: quindi possiamo dire che quest'ordine è scaduto.$B$BChe ci fai ancora qui? Uff, va bene! Ecco il pagamento.",
}
T[94226] = {
  title = "Craftsman's Writ: Green Iron Gauntlets",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Green Iron Gauntlets e riporta le indicazioni per la consegna e il pagamento. In fondo c'è scritto che questo ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo ordine.",
  progress = "Sei $Gvenuto:venuta; a prenderti la tua dose quotidiana di pugni?",
  reward = "Mmph. Dev'esserci stato un brutto errore di traduzione. Io non ho chiesto dei green iron gauntlets: ho chiesto proprio delle iron knuckles verdi.$B$B<MacKinley fa finta di tirarti un montante e si ferma a un soffio, a una distanza calcolata quanto basta per non romperti la mascella.>$B$BComunque anche questi mandano KO, quindi credo che potrò usarli in attesa del ricambio.$B$BEcco il pagamento. Oh, ti aspettavi di più? Be', anch'io.",
}
T[94227] = {
  title = "Craftsman's Writ: Big Bronze Knife",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Big Bronze Knife e spiega dove consegnarlo e come verrà pagato. In fondo, una nota dice che la commissione si può passare ad altri.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questa commissione.",
  progress = "<La gallina... si sta schiarendo la voce?>$B$BCoccodè, coccodè.",
  reward = "Coccodè? COCCODÈ COCCODÈ! COCCO!$B$B<Con la lama appena ricevuta nel becco, la gallina fissa da lontano il Magus Tirth con aria minacciosa.>",
}
T[94228] = {
  title = "Craftsman's Writ: Green Iron Boots",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Green Iron Boots e spiega dove consegnarli e come verranno pagati. In fondo, una nota dice che la commissione si può passare ad altri.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questa commissione.",
  progress = "Dimmi che sei tu $Gquello:quella; con gli stivali, ti prego...",
  reward = "Finalmente! Sono giorni che marcio per le paludi con i piedi fradici!$B$BE speriamo che almeno questi non arrugginiscano. Conto sul fatto che tu sappia quello che fai.",
}
T[94229] = {
  title = "Craftsman's Writ: Ornate Spyglass",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Ornate Spyglass e spiega dove consegnarlo e come verrà pagato. In fondo, una nota dice che la commissione si può passare ad altri.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questa commissione.",
  progress = "Ehi! Per poco non ti vedevo. Forse ti avrei visto arrivare prima, se un dannato ingegnere si decidesse una buona volta a consegnarmi l'ordine.",
  reward = "Oh. Oh! L'ingegnere sei tu? Be', almeno sei $Gil fattorino:la fattorina;.$B$BPer favore, dammi il cannocchiale. Ho poco tempo e un sacco di cose da ispezionare.",
}
T[94230] = {
  title = "Craftsman's Writ: Explosive Sheep",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Explosive Sheep e spiega dove consegnarla e come verrà pagata. In fondo, una nota dice che la commissione si può passare ad altri.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questa commissione.",
  progress = "<La donna scruta sconvolta la fattoria vicina, e si accorge che ti avvicini appena in tempo per non spaventarsi.>$B$BTi prego, dimmi che mi stai portando uno dei miei ordini di artigianato!",
  reward = "L'Explosive Sheep? È un po' più piccola di come la speravo, ma...$B$B<Allunga le mani per afferrarla, ma poi te la toglie con cautela dalle braccia. Poco dopo la posa a terra con delicatezza.>$B$BSpero che faccia abbastanza danni da farne scappare qualcuno...",
}
T[94231] = {
  title = "Craftsman's Writ: Moonsight Rifle",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Moonsight Rifle e spiega dove consegnarlo e come verrà pagato. In fondo, una nota dice che la commissione si può passare ad altri.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questa commissione.",
  progress = "Ehi, EHI, $Gamico:amica;, mai sentito parlare di una cosetta chiamata \"discrezione\"? Facciamo lo spelling insieme, D-I-S...ZIONE. Mi farai saltare la copertura!",
  reward = "Ohoho, ritiro tutto. Guarda che bello sputafuoco. Scommetto che a un satiro stacca la testa di netto.$B$BGrazie, $Gsocio:socia;, e adesso fatti da parte, o finirai nel fuoco incrociato.",
}
T[94232] = {
  title = "Craftsman's Writ: Minor Recombobulator",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 1 Minor Recombobulator, con le indicazioni per la consegna e il pagamento. In fondo c'è scritto che il mandato è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo mandato.",
  progress = "Abbiamo affari da trattare?",
  reward = "Quando ho ordinato un congegno per dissolvere le maledizioni non so bene cosa mi aspettassi, ma di sicuro non questo Recon — Racom — uff, questo Coso Minore!$B$BSenti, so quanto è complicato chiedere un rimborso, e per queste cose NON ho tempo. Per tutti e due è molto più semplice se me lo tengo e basta, e al prossimo ordine sarò più $Gpreciso:precisa;.$B$BPer il bene di entrambi, speriamo che tu non incasini anche quello!",
}
T[94233] = {
  title = "Craftsman's Writ: Practice Lock",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 1 Practice Lock, con le indicazioni per la consegna e il pagamento. In fondo c'è scritto che il mandato è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo mandato.",
  progress = "Ho visto tutto questo posto bruciare fino alle fondamenta e quel mastio crollare. Uno spettacolo magnifico.$B$BNon mi sarei mai $Gaspettato:aspettata; che una banda di briganti provasse a farne la sua base operativa.",
  reward = "Ahh, ecco la mia serratura per esercitarmi.$B$BLo Syndicate sta tramando per rifare di questo posto una prigione, com'era una volta. So già che qui c'è almeno un orco rinchiuso, forse di più. Non ho intenzione di essere $Gil prossimo:la prossima;, ma se mi prendono alla sprovvista voglio essere più $Gpreparato:preparata; dell'ultima volta.",
}
T[94234] = {
  title = "Craftsman's Writ: Shadow Goggles",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 1 Shadow Goggles, con le indicazioni per la consegna e il pagamento. In fondo c'è scritto che il mandato è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo mandato.",
  progress = "Ehi! Guarda dove metti i piedi!",
  reward = "I miei nuovi shadow goggles!$B$B<Senza dire altro, il goblin ti lancia una manciata di monete con una mano e con l'altra ti strappa l'oggetto. L'affare è concluso, e la sua attenzione è già altrove prima che tu abbia il tempo di capire cosa sia successo.>",
}
T[94235] = {
  title = "Craftsman's Writ: Gnomish Universal Remote",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 1 Gnomish Universal Remote, con le indicazioni per la consegna e il pagamento. In fondo c'è scritto che il mandato è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo mandato.",
  progress = "$GAttento:Attenta; a dove metti i piedi, $N! Questo affare ha il vizio di attivarsi quando meno te lo aspetti, e se non siamo noi ai comandi non abbiamo ancora capito bene dove possa portarti.",
  reward = "Pare che ci sia andata bene: il controllo è arrivato! A quanto vedo l'hai già precalibrato per noi, e devo ammettere che in questa situazione non è l'ideale.$B$BIn un attimo dovrei riuscire a smontarlo e a capire come funziona. Poi, speriamo, forse potrò prendermi la pausa di cui ho tanto bisogno. Mi sembra di essere $Grimasto:rimasta; per mesi e mesi a trafficare con i comandi di questo teletrasporto!",
}
T[94236] = {
  title = "Craftsman's Writ: Big Bronze Bomb",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 1 Big Bronze Bomb, con le indicazioni per la consegna e il pagamento. In fondo c'è scritto che il mandato è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo mandato.",
  progress = "Hai la roba?",
  reward = "Ehi, ecco la bomba che ho ordinato!$B$BBe', almeno una delle bombe. A me serviva un assortimento! Sai, abbastanza per provarle tutte e vedere quanto funzionano, E averne ancora qualcuna per le mie esigenze!$B$BVa be', fa niente. Eccoti un pezzo della tua parte: il resto te lo do quando porti a ME l'ordine completo!",
}
T[94237] = {
  title = "Craftsman's Writ: Crafted Solid Shot",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 200 Crafted Solid Shot e spiega dove consegnarli e come verrà pagato. In fondo, una scritta avverte che quest'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te quest'ordine.",
  progress = "Sei qui per comprare o per vendere?",
  reward = "Meno male che sei $Garrivato:arrivata; proprio adesso, sono contento. L'altro giorno mi sono passati davanti come una furia degli orchi Dragonmaw e mi hanno lanciato un'occhiataccia.$B$BMentre venivo qui sono rimasto senza munizioni, ed è per metà il motivo per cui non me ne sono ancora andato da questo posto miserabile!$B$BL'altra metà è che c'è ancora da guadagnarci.$B$B<Kixxle si sfrega le mani, avido.>",
}
T[94238] = {
  title = "Craftsman's Writ: Heavy Leather Ball",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 1 Heavy Leather Ball e spiega dove consegnarla e come verrà pagata. In fondo, una scritta avverte che quest'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te quest'ordine.",
  progress = "<Sos'mol cantava stonato una canzone inventata lì per lì da molto prima che tu arrivassi. Mentre ti avvicinavi ha continuato, solo a voce più bassa. Sembrava un po' imbarazzato, ma di certo non abbastanza da smettere di canticchiare quanto si annoiava.>",
  reward = "Cosa questo? Questa la palla che me sognava?$B$BTu, $R, dai palla a me?$B$BQuesto giorno più felice di vita di ogre... Questo tanto più importante di... ehm... cos'era l'altra cosa che me voleva?$B$BNon ricorda. Adesso palla più importante.$B$BGrazzie!!",
}
T[94239] = {
  title = "Craftsman's Writ: Fine Leather Pants",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 1 Fine Leather Pants e spiega dove consegnarli e come verrà pagato. In fondo, una scritta avverte che quest'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te quest'ordine.",
  progress = "Per favore, circola e cerca di non attirare l'attenzione su di noi.",
  reward = "Oh! I pantaloni? Ah, appena l'ho scritto mi sono accorta che mi serviva un completo intero — tuta nuova compresa.$B$BSe è il modo per toglierti di torno, credo di dover rispettare l'ordine. In fondo hai fatto un viaggio faticoso per trovarmi.$B$BPrendi questo, e adesso per favore...$B$B<Con un gesto educato ma deciso ti ha fatto segno di andartene.>",
}
T[94240] = {
  title = "Craftsman's Writ: Herbalist's Gloves",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 1 Herbalist's Gloves e spiega dove consegnarli e come verrà pagato. In fondo, una scritta avverte che quest'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te quest'ordine.",
  progress = "Ah, a quanto pare sei qui per una consegna. Fermati un momento a riprendere fiato.",
  reward = "<Murache indica giù per il pendio, verso il lago invaso da mostruose creature vegetali.>$B$BQueste bestie sono affascinanti: è da qualche giorno che le osservo. Credo che abbiano molto da insegnarci sull'erboristeria e sulle tecniche agricole. I guanti che mi hai portato sembrano perfetti allo scopo; una volta ho provato a toccarle a mani nude e ho passato ore a levarmi le spine dalle dita.$B$BSe scopro qualcosa di interessante, sarai $Gil primo:la prima; a saperlo, $Gamico:amica;.",
}
T[94241] = {
  title = "Craftsman's Writ: Dark Leather Tunic",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 1 Dark Leather Tunic e spiega dove consegnarla e come verrà pagata. In fondo, una scritta avverte che quest'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te quest'ordine.",
  progress = "COSA???",
  reward = "Oh, che tempismo perfetto!$B$BCallahan! È arrivata la tua camicia nuova. Sbrigati a cambiarti, così smetto di sentirti lamentare di continuo del prurito.$B$BE questo è per te, $R: il tuo compenso. Prima di andartene in giro, dovresti dare un'occhiata alla mia merce, ora che puoi permettertela!",
}
T[94242] = {
  title = "Craftsman's Writ: Pilferer's Gloves",
  desc = "<Il biglietto, scritto con inchiostro sbiadito, chiede 1 Pilferer's Gloves e indica dove va fatta la consegna e come avverrà il pagamento. In fondo, una nota avverte che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo ordine.",
  progress = "Compri o vendi?",
  reward = "Sì, bene. Apprezzo un lavoro fatto a regola d'arte, e in fretta. Con i miei superiori metterò una buona parola per te.$B$BCome ti suona \"$N dello Syndicate\"? Se continui così, un giorno quel titolo potrebbe essere tuo!",
}
T[94243] = {
  title = "Craftsman's Writ: Heavy Quiver",
  desc = "<Il biglietto, scritto con inchiostro sbiadito, chiede 1 Heavy Quiver e riporta il luogo di consegna e il pagamento. In fondo c'è scritto che il mandato è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo mandato.",
  progress = "Ti serve un lavoro?",
  reward = "Io — Mmh. Non mi ricordo perché l'ho ordinata. <Ziz alza le spalle e butta la faretra su un mucchio di cianfrusaglie lì vicino.>",
}
T[94244] = {
  title = "Craftsman's Writ: Dark Leather Shoulders",
  desc = "<Il biglietto, scritto con inchiostro sbiadito, chiede 1 Dark Leather Shoulders e indica dove va fatta la consegna e come avverrà il pagamento. In fondo, una nota avverte che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo ordine.",
  progress = "Yarr, che affari porti al vecchio Narkk?",
  reward = "Finalmente, ecco i me' spallacci!$B$BHai mai avuto uno di 'sti strilloni appollaiato sulla spalla? Scommetto di no! Con quegli artigli, fanno male!$B$BAdesso hanno un posto dove starsene a riposare tutto il giorno, e tu ti ritrovi il borsellino più pesante!$B$B<Narkk fissa il borsellino in questione.>$B$BPer ora!",
}
T[94245] = {
  title = "Craftsman's Writ: Barbaric Gloves",
  desc = "<Il biglietto, scritto con inchiostro sbiadito, chiede 1 Barbaric Gloves e indica dove va fatta la consegna e come avverrà il pagamento. In fondo, una nota avverte che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo ordine.",
  progress = "Le iscrizioni sono chiuse, $Gamico:amica;. E poi mi sembri un po' troppo $Ggrosso:grossa; per entrare in uno dei nostri carrelli.",
  reward = "Oh, sia lodato l'oro, sono FINALMENTE arrivati i miei guanti nuovi.$B$BNon sai quanto li ho aspettati. Tutti gli altri goblin insistono a lavorare a mani nude, ma è così che ci si rimette un'unghia. O un dito!$B$B<Il capo dei box si sfila in fretta i vecchi guanti sudici e ti strappa di mano il paio nuovo.>",
}
T[94246] = {
  title = "Craftsman's Writ: Red Whelp Gloves",
  desc = "<Il biglietto, scritto con inchiostro sbiadito, chiede 1 Red Whelp Gloves e indica dove va fatta la consegna e come avverrà il pagamento. In fondo, una nota avverte che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo ordine.",
  progress = "Che mi hai portato?",
  reward = "Sono questi, i Red Whelp Gloves? Ho sentito che costano un sacco a fabbricarli, ma valgono fino all'ultima moneta. Pensavo di attrezzarmi per far fuori qualcuno di quei draghetti a nordest, ma a quanto pare sputano fuoco.$B$BComunque sia, te li levo di mano e me li infilo subito! Grazie, $Gamico:amica;!",
}
T[94247] = {
  title = "Craftsman's Writ: Lesser Wizard's Robe",
  desc = "<Il biglietto, scritto con inchiostro sbiadito, chiede 1 Lesser Wizard's Robe e indica dove va fatta la consegna e come avverrà il pagamento. In fondo, una nota avverte che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo ordine.",
  progress = "<L'uomo sta sull'attenti e scruta oltre il fianco della montagna, verso Dalaran. Quando si accorge di te, ti fa avvicinare con un discreto cenno della mano.>",
  reward = "<Alan parla sottovoce.>$B$BNon ti pare un po' sospetto portare vesti eleganti, in pieno giorno, a un uomo vestito di cuoio scuro?$B$BBe', ehm, per fortuna sono qui per conto del Kirin Tor, quindi non sta per avvenire nessuno scambio losco. Proprio nessuno.$B$BLa tonaca, per favore.",
}
T[94248] = {
  title = "Craftsman's Writ: Blue Overalls",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Blue Overalls e dà indicazioni sul luogo di consegna e sul pagamento. In fondo, una riga avverte che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Devi avere con te quest'ordine per completare la transazione.",
  progress = "Oh! Parla piano, per favore: non serve attirare ancora più attenzione su di noi.$B$BHai qualcosa per me?",
  reward = "La Blue Overalls! Grazie al cielo, ora ho un cambio di vestiti come si deve.$B$BTieni, prendi questo, e poi per favore vai per la tua strada. Non ho tempo di chiacchierare: devo tenere d'occhio la fattoria e non posso rischiare altre distrazioni.",
}
T[94249] = {
  title = "Craftsman's Writ: Azure Silk Hood",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Azure Silk Hood e dà indicazioni sul luogo di consegna e sul pagamento. In fondo, una riga avverte che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Devi avere con te quest'ordine per completare la transazione.",
  progress = "AHHHH! Oh, essere solo $Gun:una; $R.$B$BCiao $R!",
  reward = "Essere cappuccio che me ordin-in-inato!$B$BMe scordato perché voluto all'inizio, ma me prende uguale.$B$BTieni moneta luccicante, prendi. Caduta fuori da mostro di melma. Tante e tante!",
}
T[94250] = {
  title = "Craftsman's Writ: Small Silk Pack",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Small Silk Pack e dà indicazioni sul luogo di consegna e sul pagamento. In fondo, una riga avverte che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Devi avere con te quest'ordine per completare la transazione.",
  progress = "Ehi! È per me quella sacca?",
  reward = "Ah ah! Grazie, $Gamico:amica;, te ne devo una.$B$B<Kzixx infila la mano in una Small Silk Pack che ha già con sé, piena di monete fino all'orlo, e ne tira fuori una manciata. Conta una parte minuscola di tutta la sua ricchezza e te la porge.>$B$BDovrebbe bastare. Niente ripensamenti!",
}
T[94251] = {
  title = "Craftsman's Writ: Phoenix Pants",
  desc = "<Il biglietto, scritto con un inchiostro sbiadito, chiede 1 Phoenix Pants e dà indicazioni sul luogo di consegna e sul pagamento. In fondo, una riga avverte che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Devi avere con te quest'ordine per completare la transazione.",
  progress = "Sei $Gvenuto:venuta; a prenderti 'sto voodoo?",
  reward = "Mmh.$B$BSe pensi che cercavo 'sti pantaloni pacchiani, mi sa che sei un po' $Gperso:persa;.$B$BMa te li levo di mezzo lo stesso. Non si sa mai quando a un altro avventuriero servirà un paio nuovo!",
}
T[94252] = {
  title = "Craftsman's Writ: Red Woolen Boots",
  desc = "<La nota, scritta con un inchiostro sbiadito, chiede 1 Red Woolen Boots e spiega dove consegnarli e come verranno pagati. In fondo c'è scritto che questo mandato è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla tua mappa. Per completare la transazione devi avere con te questo mandato.",
  progress = "Ehi!",
  reward = "Quando lavoravo per la Venture Co, quegli stivali dovevo portarli tutto il giorno, tutti i giorni. Pensavo di potermeli togliere e starmene comodo nella mia capanna, ma mi è venuto in mente solo dopo aver sparso fango dappertutto.$B$BE questi stivali? Sembrano molto più comodi. Meglio di così c'è solo girare a piedi nudi!",
}
T[94253] = {
  title = "Craftsman's Writ: Colorful Kilt",
  desc = "<La nota, scritta con inchiostro sbiadito, chiede 1 Colorful Kilt e riporta il luogo di consegna e il pagamento. In fondo, una riga avverte che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo ordine.",
  progress = "Giù la testa, mon! Quelli stanno a guardare...",
  reward = "Conto di intrufolarmi presto oltre i cancelli di Zul'Gurub, ma per confondermi tra loro mi serve l'equipaggiamento giusto. Pensavo di travestirmi da uno dei loro ritualisti.$B$BQuesto colorful kilt è proprio quello che mi ci vuole.",
}
T[94254] = {
  title = "Craftsman's Writ: Greater Adept's Robe",
  desc = "<La nota, scritta con inchiostro sbiadito, chiede 1 Greater Adept's Robe e riporta il luogo di consegna e il pagamento. In fondo, una riga avverte che l'ordine è trasferibile.>",
  obj = "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo ordine.",
