T[97925] = {
  title = "Campeggio 101: Sartoria",
  desc = "La Sartoria è un mestiere più efficace di quanto si creda, e investirci conviene: sono sicuro che ti sarà molto utile.$B$BConosco qualcuno che, se hai l'abilità necessaria, può insegnarti a creare un Faction Banner per il tuo accampamento. Su qualsiasi campo di battaglia, per vincere sono fondamentali ispirazione e morale, e uno stendardo che ispira può fare molto per tenerti $Gcarico:carica; di energia.",
  obj = "Parla con Eldrin nell'Eastvale Logging Camp nell'Elwynn Forest per imparare a creare un oggetto da campo per la tua professione, dopo aver dimostrato padronanza nella tua abilità.",
  reward = "Ecco fatto: ora puoi creare uno Stendardo dell'Adunata tutto tuo. Alla maggior parte della gente non piace granché trovarsi un accampamento in centro città, quindi se vuoi provarlo dovrai andare nelle terre selvagge.$B$BAh, e ricorda: in un accampamento non può mancare un fuoco da campo, e te ne servirà uno prima di montare il campo. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco: se non l'hai già fatto, potresti rivolgerti a un istruttore di cucina per imparare le basi.",
}
T[97926] = {
  title = "Arrangiarsi",
  desc = "Magari aiutare fosse così facile, $C. Davvero.$B$BSe deciderai di fermarti più a lungo nelle nostre terre, scoprirai che in molti sono nel bisogno. Le casse di Stormwind non sono più quelle di un tempo, e quel poco che resta deve bastare per tutti.$B$BLa prossima volta che vedi l'anziano, consegnagli questa risposta. Non è quella che spera, ma per ora non posso offrire altro.",
  obj = "Porta l'Alexston's Reply a Thundris Windweaver ad Auberdine, nella Darkshore.",
  progress = "Sei $Gtornato:tornata;. Che notizie porti da Stormwind?",
  reward = "Notizie tristi, davvero. Ti ringrazio comunque di aver fatto il viaggio.$B$BDato che né Stormwind né Darnassus verranno in nostro aiuto, pare che toccherà a noi decidere il destino di Auberdine.",
}
T[97927] = {
  title = "Campeggio 101: Alchimia",
  desc = "Allora hai scelto di fare l'Alchimista e di preparare infusi e pozioni. Sono sicura che in viaggio ti tornerà utile.$B$BMi sa che conosco qualcuno che può insegnarti a creare un Mana Well per il tuo accampamento. Costruiscine uno, e tutti i guaritori e gli incantatori accorreranno a farsi un sorso rinfrescante.",
  obj = "Parla con Kray a Thunder Bluff per imparare a creare un oggetto da campeggio della tua professione, quando avrai dimostrato di padroneggiare la tua abilità.",
  progress = "Sì, posso insegnarti.",
  reward = "Ecco qua: ora puoi creare un Mana Well tutto tuo. Alla gente non piace granché che si montino accampamenti in mezzo alla città, perciò se vuoi metterlo alla prova dovrai andare nelle terre selvagge.$B$BAh, e ricorda: senza un fuoco da campo un accampamento non è completo, e ti servirà prima ancora di montare il campo. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti farti insegnare da qualcuno le basi delle arti culinarie.",
}
T[97928] = {
  title = "Campeggio 101: Forgiatura",
  desc = "Allora sei $Gdiventato:diventata; un Fabbro. Ottima scelta, se vuoi essere $Gsicuro:sicura; che le tue lame non perdano mai il filo.$B$BMi sa che conosco chi può darti una mano e insegnarti a creare una Sharpening Wheel. Mettine una nel tuo accampamento, e tutti i guerrieri e i ladri della zona faranno la fila per affilare le armi.",
  obj = "Parla con Thrag Stonehoof a Thunder Bluff per imparare a creare un oggetto da campeggio della tua professione, quando avrai dimostrato di padroneggiare la tua abilità.",
  reward = "Ecco qua: ora puoi creare una Sharpening Wheel tutta tua. Alla gente non piace granché che si montino accampamenti in mezzo alla città, perciò se vuoi metterla alla prova dovrai andare nelle terre selvagge.$B$BAh, e ricorda: senza un fuoco da campo un accampamento non è completo, e ti servirà prima ancora di montare il campo. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti farti insegnare da qualcuno le basi delle arti culinarie.",
}
T[97929] = {
  title = "Campeggio 101: Incantamento",
  desc = "Gli incantatori rendono tutto migliore, e in qualsiasi accampamento in mezzo alle terre selvagge sono sempre i benvenuti.$B$BCredo di conoscere qualcuno che può insegnarti a creare un Enchanted Lute per il tuo accampamento. Nei momenti di riposo trovare un po' di svago è importantissimo, e questo pizzico di magia può aiutarti a essere $Gpronto:pronta; ad affrontare ogni sorta di sfida quando ti rimetterai in cammino.",
  obj = "Parla con Mot Dawnstrider a Thunder Bluff per imparare a creare un oggetto da campeggio per la tua professione, una volta che avrai dimostrato di padroneggiare la tua abilità.",
  reward = "Ecco fatto: ora puoi creare un Enchanted Lute tutto tuo. Se vuoi provarlo, però, dovrai andare nelle terre selvagge, perché alla maggior parte della gente non piace molto che si montino accampamenti in mezzo alla città.$B$BAh, e ricorda: senza un fuoco da campo nessun accampamento è completo, e prima di montare il campo te ne servirà uno. Ad accendere un fuoco possono insegnarti quasi tutti i cuochi: se non l'hai già fatto, ti conviene passare da un istruttore di cucina per imparare le basi.",
}
T[97930] = {
  title = "Campeggio 101: Ingegneria",
  desc = "Gli ingegneri come te sanno sfornare marchingegni, bot e bombe di ogni sorta, per divertirsi e per guadagnarci.$B$BCredo di conoscere qualcuno che può insegnarti a creare un Reagent Bot per il tuo accampamento. Questo utile automa può aiutarti a restare ben $Grifornito:rifornita;, e così né tu né i tuoi alleati rimarrete mai senza i materiali che alimentano gli incantesimi.",
  obj = "Parla con Twizwick Sprocketgrind in The Venture Co. Mine, in Mulgore, per imparare a creare un oggetto da campeggio per la tua professione, una volta che avrai dimostrato di padroneggiare la tua abilità.",
}
T[97931] = {
  title = "Campeggio 101: First Aid",
  desc = "Così ti sei $Gdato:data; al First Aid? È una strada onorevole... e pratica, per $Gun:una; $C.$B$BMi sa che conosco qualcuno che può insegnarti a creare un First Aid Kit per il tuo accampamento. Chi va all'avventura prima o poi si fa male, e offrire nel tuo accampamento cure tanto necessarie potrebbe persino salvare delle vite.",
  obj = "Parla con Vira Younghoof a Bloodhoof Village per imparare a creare un oggetto da campeggio della tua professione, quando avrai dimostrato di padroneggiarla.",
  progress = "Quando avrai fatto un po' di pratica nella tua professione, potrò insegnarti.",
  reward = "Ecco fatto: ora puoi creare il tuo First Aid Kit personale. Alla maggior parte della gente non piace molto vedersi montare accampamenti in mezzo al paese, quindi se vuoi provarlo dovrai andare nelle terre selvagge.$B$BAh, e ricorda: non c'è accampamento senza un fuoco, e ti servirà prima di allestire il campo. Ad accenderlo te lo possono insegnare quasi tutti i cuochi. Se non l'hai già fatto, potresti cercare qualcuno che ti istruisca nell'arte culinaria e imparare le basi.",
}
T[97932] = {
  title = "Campeggio 101: Pesca",
  desc = "Non si direbbe, ma in un accampamento la tua abilità di $Gpescatore:pescatrice; può tornarti utile.$B$BCredo di conoscere qualcuno che può insegnarti a creare una Fish Bowl per il tuo accampamento. Con questo arredo puoi portare un po' di allegria a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e in combattimento si vedrà, ne sono sicura.",
  obj = "Parla con Uthan Stillwater a Bloodhoof Village per imparare a creare un oggetto da campeggio per la tua professione, una volta che avrai dimostrato di padroneggiare la tua abilità.",
  reward = "Ecco fatto: ora puoi creare una Fish Bowl tutta tua. Se vuoi provarla, però, dovrai andare nelle terre selvagge, perché alla maggior parte della gente non piace molto che si montino accampamenti in mezzo alla città.$B$BAh, e ricorda: senza un fuoco da campo nessun accampamento è completo, e prima di montare il campo te ne servirà uno. Ad accendere un fuoco possono insegnarti quasi tutti i cuochi: se non l'hai già fatto, ti conviene passare da un istruttore di cucina per imparare le basi.",
}
T[97933] = {
  title = "Campeggio 101: Erboristeria",
  desc = "Mi sembra che in erboristeria tu abbia acquisito una certa abilità. Sai, raccogliere fiori non è solo un modo di bighellonare: può essere utile... e redditizio.$B$BCredo di conoscere qualcuno che può insegnarti a creare un'Incense Candle per il tuo accampamento. Per far resistere in battaglia guaritori e incantatori è fondamentale che il morale sia alto, e un'Incense Candle può dare una carica che chi usa la magia apprezzerà di sicuro.",
  obj = "Parla con Komin Winterhoof a Thunder Bluff per imparare a creare un oggetto da campeggio per la tua professione, una volta che avrai dimostrato di padroneggiare la tua abilità.",
  progress = "Sì, posso insegnarti.",
  reward = "Ecco fatto: ora puoi creare un'Incense Candle tutta tua. Se vuoi provarla, però, dovrai andare nelle terre selvagge, perché alla maggior parte della gente non piace molto che si montino accampamenti in mezzo alla città.$B$BAh, e ricorda: senza un fuoco da campo nessun accampamento è completo, e prima di montare il campo te ne servirà uno. Ad accendere un fuoco possono insegnarti quasi tutti i cuochi: se non l'hai già fatto, ti conviene passare da un istruttore di cucina per imparare le basi.",
}
T[97934] = {
  title = "Campeggio 101: Conciatura",
  desc = "Sei $Gdiventato:diventata; $Gun:una; $Gconciatore:conciatrice;: buon per te, $C. Credo di conoscere qualcuno che può insegnarti a farti una tenda, una di quelle che ti tengono al fresco nei giorni caldi e all'asciutto quando piove.$B$BCon una buona tenda sopra la testa riposerai quanto ti serve per restare $Glucido:lucida; in viaggio.",
  obj = "Parla con Chaw Stronghide a Bloodhoof Village per imparare a creare un oggetto da campeggio per la tua professione, una volta che avrai dimostrato di padroneggiare la tua abilità.",
  progress = "Sì, posso insegnarti.",
  reward = "Ecco qua, una tenda da campeggio tutta tua. Alla gente in genere non piace granché vedere tende piantate in mezzo al paese, perciò se vuoi provarla dovrai andare nelle terre selvagge.$B$BOh, e ricorda: senza fuoco non c'è accampamento. Prima di montare il campo te ne serve uno, e quasi ogni cuoco può insegnarti ad accenderlo. Se non l'hai già fatto, potresti fare un salto da chi insegna l'arte culinaria e impararne le basi.",
}
T[97935] = {
  title = "Campeggio 101: Estrazione Mineraria",
  desc = "Quello del minatore non è il mestiere più affascinante, ma è un lavoro onesto, ed è una bella professione da provare.$B$BMi sa che conosco qualcuno che può insegnarti a creare una Lodestone per il tuo accampamento. Costruiscine una, e chiunque voglia menare la spada non vedrà l'ora di radunarsi intorno al tuo fuoco ad assorbire quella \"spinta\" in più che in combattimento può renderlo più abile.",
  obj = "Parla con Brek Stonehoof a Thunder Bluff per imparare a creare un oggetto da campeggio per la tua professione, dopo che avrai dimostrato di essere $Gesperto:esperta; nella tua abilità.",
  reward = "Ecco fatto: da adesso puoi creare una Lodestone tutta tua. Se vuoi provarla, però, dovrai andare nelle terre selvagge, perché alla gente non piace granché che si piantino accampamenti in mezzo al paese.$B$BAh, e ricorda: un accampamento senza fuoco da campo non è completo, e prima di piantare il campo te ne servirà uno. Ad accendere un fuoco te lo può insegnare quasi qualunque cuoco: se non l'hai già fatto, ti conviene passare da qualcuno che ti istruisca nelle arti culinarie e imparare le basi.",
}
T[97936] = {
  title = "Campeggio 101: Scuoiatura",
  desc = "Per un avventuriero, saper ricavare con destrezza pelli e cuoio dalle bestie abbattute è una delle capacità più preziose che possa avere.$B$BMi sa che conosco qualcuno che può insegnarti a costruire una Camp Chair per il tuo accampamento. A volte è importante solo tirare il fiato, e con alcune delle pelli che hai raccolto puoi farti una sedia comoda. Un po' di relax può aiutarti a restare in piena forma e a colpire nel punto giusto la prossima volta che ti ritroverai in una zuffa.",
  obj = "Parla con Yonn Deepcut a Bloodhoof Village per imparare a costruire un oggetto da campeggio per la tua professione, dopo aver dimostrato di padroneggiare l'abilità.",
  progress = "Se hai l'abilità, ti posso addestrare.",
  reward = "Ecco fatto: ora puoi costruirti una Camp Chair tutta tua. Alla gente, perlopiù, non piace granché vedere accampamenti montati in mezzo al paese, quindi se vuoi provarla dovrai andare nelle terre selvagge.$B$BAh, e ricorda: un accampamento non è completo senza un falò, e prima di montare il campo te ne servirà uno. Ad accendere un fuoco te lo può insegnare quasi qualunque cuoco. Se non l'hai ancora fatto, faresti bene a passare da un istruttore di cucina per imparare le basi.",
}
T[97937] = {
  title = "Campeggio 101: Sartoria",
  desc = "La sartoria è un mestiere su cui vale la pena investire: è più potente di quanto si pensi, e sono sicura che ti tornerà utile.$B$BConosco qualcuno che può insegnarti a creare un Faction Banner per il tuo accampamento, purché tu abbia l'abilità necessaria. Per vincere su qualunque campo di battaglia l'ispirazione e il morale sono fondamentali, e uno stendardo che ispira aiuta parecchio a tenerti $Gcarico:carica; di energia.",
  obj = "Parla con Vhan a Thunder Bluff per imparare a creare un oggetto da campeggio per la tua professione, una volta che avrai dimostrato di padroneggiare la tua abilità.",
}
T[97938] = {
  title = "Campeggio 101: Alchimia",
  desc = "Allora hai deciso di fare l'Alchimista e preparare infusi e pozioni. Sono sicura che in viaggio ti tornerà utile.$B$BCredo di conoscere qualcuno che può insegnarti a creare un Mana Well per il tuo accampamento. Costruiscine uno, e guaritori e incantatori accorreranno tutti per un sorso rinfrescante.",
  obj = "Parla con Cyndra Kindwhisper a Dolanaar per imparare a creare un oggetto da campeggio per la tua professione, una volta che avrai dimostrato di padroneggiare la tua abilità.",
  progress = "Sì, posso insegnarti.",
  reward = "Ecco qua, ora puoi creare un Mana Well tutto tuo. Alla gente in genere non piace granché vedere accampamenti piantati in mezzo al paese, perciò se vuoi provarlo dovrai andare nelle terre selvagge.$B$BOh, e ricorda: senza fuoco non c'è accampamento. Prima di montare il campo te ne serve uno, e quasi ogni cuoco può insegnarti ad accenderlo. Se non l'hai già fatto, potresti fare un salto da chi insegna l'arte culinaria e impararne le basi.",
}
