T[97968] = {
  title = "Campeggio 101: Erboristeria",
  desc = "Mi pare che con l'erboristeria tu te la cavi già un po'. Raccogliere fiori non è solo un modo per perdere tempo, sai. Può essere utile... e redditizio.$B$BMi sa che conosco qualcuno che ti può insegnare a creare un'Incense Candle per il tuo accampamento. Perché guaritori e incantatori restino in battaglia il morale alto è fondamentale, e un'Incense Candle può dare una spinta che chi usa la magia apprezzerà di sicuro.",
  obj = "Parla con Syriel Nightrain a Valanaar per imparare a creare un oggetto da campeggio della tua professione, una volta che avrai dimostrato di essere $Gesperto:esperta; nella tua abilità.",
  reward = "Ecco fatto, adesso sai creare la tua Incense Candle personale. Alla maggior parte della gente non piace granché che qualcuno si accampi in mezzo al paese, quindi se vuoi provarla dovrai andare nella natura selvaggia.$B$BAh, e ricorda: senza un fuoco da campo nessun accampamento è completo, e te ne servirà uno prima di accamparti. Quasi ogni cuoco sa insegnarti ad accenderlo. Se non l'hai ancora fatto, forse ti conviene passare da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.",
}
T[97969] = {
  title = "Campeggio 101: Conciatura",
  desc = "Sei $Gdiventato:diventata; $Gun conciatore:una conciatrice;, $C: buon per te. Mi sa che conosco qualcuno che può insegnarti a farti una tenda che ti tenga al fresco quando fa caldo e all'asciutto quando piove.$B$BCon una buona tenda sopra la testa potrai riposare quanto ti serve e restare $Glucido:lucida; durante i viaggi.",
  obj = "Parla con Indari Sunseam a Shen'dar Village per imparare a creare un oggetto da campeggio della tua professione, una volta che avrai dimostrato la tua bravura.",
  progress = "Sì, posso insegnarti.",
  reward = "Ecco fatto: la tua tenda da campo, tutta per te. Di solito alla gente non va molto a genio vedere tende piantate in mezzo al paese, quindi se vuoi provarla dovrai andare nelle terre selvagge.$B$BAh, e ricorda: un accampamento non è completo senza un fuoco da campo, e prima di accamparti te ne servirà uno. Quasi tutti i cuochi possono insegnarti ad accenderlo. Se non l'hai ancora fatto, potresti passare da qualcuno che ti addestri nell'arte culinaria e imparare le basi.",
}
T[97970] = {
  title = "Campeggio 101: Estrazione",
  desc = "L'estrazione non sarà il più affascinante dei mestieri, ma è un lavoro onesto, e una bella professione da scoprire.$B$BMi sa che conosco qualcuno che può insegnarti a creare una Lodestone per il tuo accampamento. Costruiscine una, e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"spinta\" in più che può dare alla sua abilità in combattimento.",
  obj = "Parla con Messana Crestwind a Shen'dar Village per imparare a creare un oggetto da campeggio della tua professione, una volta che avrai dimostrato la tua bravura.",
  progress = "Se hai la stoffa, posso addestrarti.",
  reward = "Ecco fatto: ora puoi creare una Lodestone tutta tua. Di solito alla gente non va molto a genio vedere accampamenti montati in mezzo al paese, quindi se vuoi provarla dovrai andare nelle terre selvagge.$B$BAh, e ricorda: un accampamento non è completo senza un fuoco da campo, e prima di accamparti te ne servirà uno. Quasi tutti i cuochi possono insegnarti ad accenderlo. Se non l'hai ancora fatto, potresti passare da qualcuno che ti addestri nell'arte culinaria e imparare le basi.",
}
T[97971] = {
  title = "Campeggio 101: Scuoiatura",
  desc = "Ricavare con abilità le pelli e i pellami dalle bestie abbattute è una delle capacità più preziose per un avventuriero.$B$BMi sa che conosco qualcuno che può insegnarti a creare una Camp Chair per il tuo accampamento. Ogni tanto è importante fermarsi a riposare, e con un po' delle pelli che hai raccolto puoi farti una sedia comoda. Rilassarti un po' può aiutarti a essere in piena forma e a colpire nel segno la prossima volta che ti ritroverai in una zuffa.",
  obj = "Parla con Mendalass Tattermend a Shen'dar Village per imparare a creare un oggetto da campeggio della tua professione, una volta che avrai dimostrato la tua bravura.",
  reward = "Ecco fatto: ora puoi creare una Camp Chair tutta tua. Di solito alla gente non va molto a genio vedere accampamenti montati in mezzo al paese, quindi se vuoi provarla dovrai andare nelle terre selvagge.$B$BAh, e ricorda: un accampamento non è completo senza un fuoco da campo, e prima di accamparti te ne servirà uno. Quasi tutti i cuochi possono insegnarti ad accenderlo. Se non l'hai ancora fatto, potresti passare da qualcuno che ti addestri nell'arte culinaria e imparare le basi.",
}
T[97972] = {
  title = "Campeggio 101: Sartoria",
  desc = "La sartoria, come professione su cui investire, è di una potenza sorprendente, e sono sicuro che ti tornerà utile.$B$BSe hai l'abilità necessaria, conosco qualcuno che può insegnarti a creare un Faction Banner per il tuo accampamento. Su qualsiasi campo di battaglia, per vincere sono fondamentali l'ispirazione e il morale, e uno stendardo che ispira può fare molto per tenerti $Gcarico:carica;.",
  obj = "Parla con Taleen Shimmerthread a Shen'dar Village per imparare a creare un oggetto da campeggio per la tua professione, dopo aver dimostrato di padroneggiare l'abilità.",
  reward = "Ecco fatto: ora puoi creare uno Stendardo di Adunata tutto tuo. Alla maggior parte della gente non piace granché trovarsi accampamenti montati in mezzo alla città, quindi se vuoi provarlo dovrai andartene nelle terre selvagge.$B$BAh, e ricorda: senza un fuoco da campo non è un vero accampamento, e te ne servirà uno prima di montare il campo. Ad accenderlo te lo può insegnare quasi ogni cuoco; se non l'hai ancora fatto, potresti passare da un istruttore di cucina per imparare le basi.",
}
T[97973] = {
  title = "Campeggio 101: Sartoria",
  desc = "La sartoria è una professione che vale più di quanto si pensi: investirci conviene, e sono sicuro che ti tornerà utile.$B$BSe ne hai la capacità, conosco qualcuno che può insegnarti a creare un Faction Banner per il tuo accampamento. Per vincere su qualsiasi campo di battaglia l'ispirazione e il morale sono fondamentali, e uno stendardo che ispira può fare molto per tenerti $Gcarico:carica;.",
  obj = "Parla con Taleen Shimmerthread a Shen'dar Village per imparare a creare un oggetto da campeggio della tua professione, una volta che avrai dimostrato la tua bravura.",
  progress = "Torna a parlarmi quando sarai un po' più $Gesperto:esperta; nella tua professione.",
  reward = "Ecco fatto: ora puoi creare uno Stendardo dell'Adunata tutto tuo. Di solito alla gente non va molto a genio vedere accampamenti montati in mezzo al paese, quindi se vuoi provarlo dovrai andare nelle terre selvagge. Ah, e ricorda: un accampamento non è completo senza un fuoco da campo, e prima di accamparti te ne servirà uno. Quasi tutti i cuochi possono insegnarti ad accenderlo. Se non l'hai ancora fatto, potresti passare da qualcuno che ti addestri nell'arte culinaria e imparare le basi.",
}
T[97977] = {
  title = "Il Richiamo della Natura",
  desc = "I furbolg Gnarlpine non si rivolterebbero così facilmente contro i loro antichi alleati. Dobbiamo saperne di più sulla loro sventura.$B$BCerca dei totem nelle loro case abbandonate. Se ne è rimasto intatto qualcuno nel caos della loro partenza, dalle incisioni potremmo capire meglio cos'è accaduto qui.$B$BTroverai i loro accampamenti lungo il margine occidentale della valle, anche se i grell e i grellkin potrebbero aver sparpagliato i totem più lontano.",
  obj = "Raccogli 4 Gnarlpine Totems e portali a Tarindrella.",
  progress = "Non preoccuparti dei totem più grandi che potresti trovare. Non saprei che farmene, anche se riuscissi a portarli qui!",
  reward = "Oh, è persino peggio di quanto pensassi.$B$BQueste incisioni rivelano che gli Gnarlpine hanno cominciato ad avere incubi in cui una grande ombra li sterminava. In poco tempo la paura si è trasformata in rabbia — e l'ombra ha preso il volto dei loro vecchi amici elfi. Accorgersi che la propria mente sta scivolando via...$B$BPossiamo solo sperare che questo ci aiuti a capire meglio cosa sta accadendo su Teldrassil. Grazie per l'aiuto, $N.",
}
T[97979] = {
  title = "La Dea Provvede",
  desc = "Sei $Gnato:nata; kaldorei — i figli delle stelle — e hai ereditato un diritto di nascita che non somiglia a nessun altro in questo mondo. La grazia di Elune può far risplendere i nostri punti di forza e guidare a segno i nostri colpi, oppure aiutarci a nasconderci, come la luna può eclissare il sole.$B$BLa Long Vigil che è seguita alla difesa del Mount Hyjal è finita, e siamo entrati in un'Alleanza con altri — li conoscerai a tempo debito. Per ora sei $Gaccoccolato:accoccolata; fra i rami di Teldrassil.$B$BMostra i doni di Madre Luna e crogiolati nelle sue benedizioni.",
  obj = "Lancia Luce di Elune e Fusione nell'Ombra.",
  progress = "Ci sono poche gioie grandi come crogiolarsi nella luce di Madre Luna.",
  reward = "Hai visto i doni della nostra dea. Usali bene, e lei non ti abbandonerà mai.",
}
T[97985] = {
  title = "Cuori Tonanti",
  desc = "Affascinanti, vero? È la prima volta che scopro i segreti per creare un abomination.$B$BHo studiato questi appunti, e a quanto pare ci serve un cuore. Uno enorme!$B$BHo sentito dire che sul bordo del canyon, a Thousand Needles, fa la ronda un thunder lizard di dimensioni impressionanti che si chiama Stormheart. Con un nome così, il suo cuore sarà perfetto. Quel cuore deve essere mio!$B$BAh, ti consiglio anche di portarti degli amici. Stormheart non è famoso per la sua docilità.",
  obj = "Uccidi Stormheart a Thousand Needles e prendi il suo cuore.",
  progress = "Oh, sei $Gtornato tutto intero:tornata tutta intera;! Peccato, altrimenti le tue ossa e quel che resta della tua carne sarebbero state un ottimo materiale per i miei esperimenti.",
  reward = "Eccellente! Riesco a malapena a contenere l'entusiasmo. Oh, il cuore ha ancora degli impulsi elettrici? Notevole. Così non dovrò riportarlo in vita con una scossa!$B$BQuesto cuore sarà un'aggiunta meravigliosa all'abomination e, se questi appunti sono corretti, sembra proprio avere le dimensioni richieste.$B$BAh, adoro i piani che riescono bene.",
}
T[98013] = {
  title = "Forze Crescenti",
  desc = "Preparati, giovane, ad affrontare le rovine... laggiù non avrai via libera.$B$BDecine e decine di Highborne maledetti, oggi conosciuti come naga, si aggirano per quella che un tempo era una grandiosa città. Va' a nordest ed eliminali da questa terra.$B$BCiò che erano un tempo... non esiste più. Se aiutano il Twilight's Hammer, non possono che portare altro dolore alle foreste che un tempo hanno dato loro riparo.$B$BÈ la guerra che cercano, $C. La guerra... è ciò che porteremo.",
  obj = "Elimina 12 Stormscale Myrmidons, 8 Stormscale Sorceresses e 6 Stormscale Warriors per Arbal al Grove of the Ancients.",
  reward = "Non darti pena, giovane. Saccheggiare la propria casa per conto di un qualche oscuro padrone...$B$BÈ imperdonabile.",
}
T[98021] = {
  title = "Viaggio Verso Sentinel Hill",
  desc = "Se vuoi cominciare a fare del bene nel nostro mondo, ti consiglio di andare a sud, a Westfall, e di presentarti da un uomo di nome Gryan Stoutmantle, nell'insediamento noto come Sentinel Hill. La sua gente ha bisogno di aiuto.$B$BA te, che sei $Garrivato:arrivata; qui da un altro piano dell'esistenza, i problemi delle nostre terre potranno sembrare piccoli. Ma ti assicuro che per chi ne soffre il tuo aiuto è tutto, e che queste fatiche ti renderanno più forte.$B$BBuona fortuna là fuori, $Gavventuriero:avventuriera;!",
  obj = "Presentati da Gryan Stoutmantle a Sentinel Hill, in Westfall.",
  reward = "Da mesi supplico Stormwind di aiutarmi, e mi manda $Gun elfo mingherlino:un'elfa mingherlina;? Be', a caval donato non si guarda in bocca, suppongo.$B$B$GBenvenuto:Benvenuta; a Westfall, $C. Vediamo se riusciamo a metterti al lavoro.",
}
T[98024] = {
  title = "Viaggio al Crocevia",
  desc = "Dopo il viaggio che ti ha portato fin qui dal piano elementale, i problemi delle nostre terre potranno sembrarti piccoli. Ma sta' $Gcerto:certa;, i pericoli che l'orda deve affrontare sono più che reali, e se sopravvivrai al tuo servizio diventerai formidabile.$B$BSe vuoi cominciare a fare del bene nel nostro mondo, dirigiti a sud-ovest, verso le vaste terre chiamate Barrens. Lì troverai un insediamento, il Crossroads, dove i fieri abitanti hanno sempre bisogno d'aiuto.$B$BVa' con onore, $Gavventuriero:avventuriera;!",
  obj = "Fai rapporto a Thork a The Crossroads in The Barrens.",
  reward = "E qui cosa abbiamo? $GUn elfo:Un'elfa;? E dici che ti ha mandato il Capoguerra?$B$B<Thork grugnisce secco e ti squadra da capo a piedi.>$B$BMi sembri un po' $Gmingherlino:mingherlina;, ma poco importa. Qui fuori o prosperi e sopravvivi, o muori. In queste terre le cose vanno così.",
}
T[98025] = {
  title = "RICERCATA: Jai'vhanel",
  desc = "Attenzione!$B$BSi offre una ricompensa per la morte della civetta \"Jai'vhanel\", detta anche \"Piumaspada\".$B$BPurtroppo la civetta è impazzita e ha preso ad attaccare i viaggiatori lungo la strada vicino ad Auberdine.$B$BL'ultima volta Jai'vhanel è stata vista a nord delle rovine di Ameth'Aran, ai piedi della montagna. Come prova della sua morte, riporta una delle sue jet black feathers.$B$BPer riscuotere la taglia, rivolgersi a Sentinel Glynda Nal'Shea ad Auberdine.$B$BL'Auberdine Village Council",
  obj = "Trova e uccidi la civetta chiamata Jai'vhanel e prendi una delle sue piume. La civetta nera è stata vista l'ultima volta a nord delle rovine di Ameth'Aran, ai piedi della montagna. Riferisci la morte di Jai'vhanel a Sentinel Glynda Nal'Shea ad Auberdine.",
  progress = "Salute, $C — cosa possono fare per te le Sentinelle oggi? Sei qui per chiedere della taglia su Jai'vhanel, forse?",
  reward = "Mi fa piacere sapere che la faccenda è sistemata, ma mi rattrista che non siamo riusciti a trovare un'altra soluzione. Jai'vhanel era stata a lungo una specie di guardiana di questa zona, e non so cosa possa averla fatta precipitare nella follia.$B$BIn ogni caso, grazie per l'aiuto di oggi, $C. Le strade per Auberdine sono tornate sicure.",
}
T[98027] = {
  title = "Gleaming Crescent Necklace",
  desc = "<La collana d'argento che hai in mano brilla appena mentre la esamini, e la piccola mezzaluna ti ricorda altri simboli degli elfi della notte che hai già visto.$B$BVoltandola, trovi una piccola iscrizione: \"Alor'lormah, Maliynn\". Che sia di Maliynn, ad Astranaar?>",
  obj = "Consegna la collana a mezzaluna a Maliynn ad Astranaar.$B$BOggetto fornito:",
  reward = "Oh, cielo! Non ci posso credere, l'hai trovata! E io che pensavo di aver cercato dappertutto!$B$BL'avevo persa mentre portavo provviste a uno dei nostri avamposti, e dopo averla cercata lungo la strada mi ero arresa.$B$BGrazie di avermela riportata. Me l'avevano regalata i miei genitori, che non ci sono più, e non sai quanto significhi per me riaverla.",
}
T[98028] = {
  title = "Baron Marinous",
  desc = "Del potente elementale resta soltanto una sfera di quella che sembra acqua pura, intorbidita da una sostanza sconosciuta. Ai bordi la sfera pare limpida, ma solo finché non la giri — come se la nube facesse apposta a non farti guardare dentro.$B$BQualunque cosa sia successa all'elementale — e alle rovine che proteggeva — in qualche modo è ancora attiva.$B$BSolo Onu, l'Ancient of Lore che sta al Grove of the Ancients, molto più a sud, potrebbe saperne di più.",
  obj = "Porta il Clouded Water Globe a Onu a Grove of the Ancients, in Darkshore.",
  progress = "Davanti a me percepisco qualcosa di molto più antico di te, $R... che cosa mi hai portato?",
  reward = "<Onu sembra sorpreso — o almeno sorpreso quanto può sembrarlo un antico.>$B$BScale che scendono a Mathystra? Possibile?$B$B<Onu scuote la testa.>$B$BDevo parlarne con gli altri. Per ora ti basti sapere che è un bene che l'abbia scoperto tu, prima dei naga... o dei loro alleati della setta.$B$BAccetta questo come ringraziamento per il tuo impegno. Sconfiggere un guardiano elementale non è impresa da poco.",
}
T[98042] = {
  title = "Si Ride e si Scherza Finché...",
  desc = "<Mentre strappi l'unica pagina dal Twilight Tome, una voce minacciosa ti invade la mente senza essere stata invitata.>$B$BHanno fallito.$B$BSarai $Gdimenticato:dimenticata;.$B$BPerderanno l'occhio che hanno ottenuto.",
  obj = "Ottieni un Peerless Eye da un Twilight Disciple o da uno Sgherro al Master's Glaive nella Darkshore e trova qualcuno ad Auberdine disposto a prenderlo.",
  progress = "Sembri $Gturbato:turbata;. Ti ascolto.",
  reward = "<Thundris rimane in silenzio per un po'.>$B$BQuesto porta il marchio di un antico male, $C. Lo farò portare subito a Darnassus, dove verrà studiato più a fondo.$B$BAnde'thoras-ethil.",
}
T[98046] = {
  title = "Corona della Terra",
  desc = "<Arch Druid Fandral Staghelm stringe gli occhi.>$B$BSei ancora qui?$B$BPrendi la fiala e sparisci dalla mia vista, $C. Anche stavolta, è chiaro, le risposte che cerco non sono nelle acque. $B$BForse una delle sacerdotesse del Tempio della Luna, a sud, potrà sbarazzarsene.$B$B<Fandral distoglie lo sguardo e smette di rivolgerti la parola.>$B$BDevo cercare altrove, se voglio che funzioni...",
  obj = "Porta il Drained Vessel a Lariia nel Tempio della Luna a Darnassus.",
  progress = "Come posso aiutarti?",
  reward = "Non badare all'Arcidruido, $N. In assenza di Malfurion porta sulle spalle un peso enorme.$B$BAspetta! Nella fiala c'è ancora qualche goccia! Forse è per questo che il suo incantesimo è fallito?",
}
T[98059] = {
  title = "Il Tesoro di Hillsbrad",
  desc = "Il consiglio di Hillsbrad non ha risposto alle lettere del nostro nuovo magistrato, e le ultime notizie che sono $Griuscito:riuscita; a strappare a un mercante di passaggio dalla città non bastano certo a giustificare il loro silenzio.$B$BChiediamo solo un piccolo plotone — eppure mi dicono che dentro un complesso cinto da mura riposano diverse baliste d'assedio, in perfette condizioni.$B$BEntra nel loro municipio come $Gun:una; $Gcittadino:cittadina; che va a riconsegnare un modulo del censimento, e posa questa per bene sul tavolo della contabilità.$B$BQuando hai fatto, torna da me.",
  obj = "Posa la Sealed Company Request che ti è stata data sul tavolo della contabilità nel municipio di Hillsbrad.",
  reward = "Ottimo lavoro, $Gsoldato:soldatessa;. So che non sei di stanza qui da noi, ma un aiuto valido non lo rifiutiamo mai.$B$BSe non rispondono a QUESTA lettera, dovremo passare a maniere più rozze.$B$BE se ci sarà di nuovo bisogno di trattare con i civili, ti terremo di riserva.",
}
T[98065] = {
  title = "Corona della Terra",
  desc = "Devi portarla subito a Tyrande! Te la verserò in un recipiente più adatto alle cerimonie.$B$BNon temere. L'Alta Priestess of Elune è decisa, ma gentile. Protegge chiunque entri a Darnassus e porta a tutti la luce della nostra dea.$B$BSarà lieta di ricevere quest'acqua sacra. La troverai proprio sopra di noi.",
  obj = "Porta i Moonwell Remnants a Tyrande Whisperwind nel Tempio della Luna a Darnassus.",
  progress = "Ti prego, dimmi cosa ti porta qui. Ho una città da governare e un popolo da guidare.",
  reward = "Staghelm ha fatto molto in assenza del mio amato, ma non è Malfurion. E non è lui a gestire gli affari di Darnassus — quel fardello spetta a me sola.$B$B<Il volto di Tyrande si ricompone.>$B$BTi chiedo scusa. Come avrai notato, abbiamo molte sfide da superare.$B$BPer ora Fandral è l'Arcidruido, e ti prego di rispettarne il ruolo. Ma lui si occupa del druidismo; io, invece, non solo servo Elune, ma guido anche il nostro popolo come vuole lei.$B$BOgni goccia di quest'acqua è benedetta dalla nostra dea. Ti ringrazio di averla salvata.",
}
T[98067] = {
  title = "Gli Occhi delle Sentinelle",
  desc = "General Feathermoon fa in modo che tutte le sentinelle abbiano il tempo di pregare Elune. Per sconfiggere i nostri nemici, una vera cacciatrice non impugna soltanto la lama, ma anche i doni della dea.$B$BPuoi aiutarmi nei compiti di ogni giorno. Disponi le sentinelle in città — comincia dalle gallerie che scendono sotto la Cenarion Hold, a nord, poi la banca al centro, la locanda nella Craftsman's Terrace, a nord-est, e le porte della città. Le guardie possono aiutarti.$B$BA Teldrassil c'è qualcosa che non va — dobbiamo restare vigili.",
  obj = "Disponi i Sentinel Owls all'ingresso delle profondità della Cenarion Hold, alla Darnassus Bank, alla Locanda della Craftsman's Terrace e alla Porta della Città per Sentinel Dalia Sunblade nel Tempio della Luna a Darnassus.",
  progress = "Dobbiamo restare vigili: Darnassus sarà anche ben protetta, ma i nostri nemici sono ovunque.",
  reward = "Ti ringrazio dell'aiuto. I riti quotidiani mi danno pace, ma è bello, invece, avere un momento per riflettere.",
}
T[98069] = {
  title = "Stolen Freewind Supplies",
  desc = "Maledette arpie! Hanno attaccato l'ultima carovana che avevo organizzato per portare le forniture al Freewind Post. Per ora ce n'è abbastanza, ma senza altre presto resteremo a corto.$B$BNon so bene cosa se ne vogliano fare le arpie, di forniture in più, ma ti sarei grata se me le riportassi. Hanno la tana a ovest di qui: le trovi sia ai piedi della scogliera sia dentro una grotta in cima.",
  obj = "Porta 8 Stolen Freewind Supplies a Jandia al Freewind Post.",
  progress = "Sei $Griuscito:riuscita; a recuperare le forniture che le arpie hanno rubato?",
  reward = "Grazie, $N. Con queste forniture tireremo avanti finché non arriverà il prossimo carico.",
}
T[98070] = {
  title = "Ferma lo Stridio",
  desc = "The Screeching Canyon ospita una banda di arpie del posto, note per la loro ferocia e per le tattiche da predoni. Le ultime carovane di rifornimenti che hanno avuto il coraggio di attraversare questa zona sono finite nelle loro imboscate.$B$BSe non si fa qualcosa presto, temo che nessuna carovana oserà più affrontare il viaggio fino al Freewind Post.$B$BVa', uccidi quante più arpie puoi. Quando avrai compiuto l'impresa torna da me, e ti ricompenserò bene per i tuoi sforzi.",
  obj = "Uccidi 5 Screeching Harpies, 5 arpie Screeching Roguefeather e 5 arpie Screeching Windcaller.",
  reward = "Che notizia meravigliosa! Farò sapere ai nostri fornitori che le arpie sono state sistemate. Almeno le prossime carovane avranno una minaccia in meno di cui preoccuparsi.",
}
T[98071] = {
  title = "Lo Scambio del Birraio",
  desc = "Ho fatto un po' di scambi coi compari birrai di Dun Garok. Pare che non siamo i soli a sentire la mancanza dei vigneti della famiglia Fallrook! Quasi tutte le bottiglie delle annate migliori se le son bevute da un pezzo, ma in cantina abbiamo ancora casse di quel vino.$B$BPorta questa cassa di Varietale Fallrook a Dun Garok, a sudest, e lasciagliela vicino al focolare dove si riuniscono, giù in fondo al forte.$B$BIn cambio, torna con un sacco degli Homebrew Hops.$B$BDa 'ste parti, quella fortezza è la cosa più simile a casa!",
  obj = "Consegna le bottiglie di Varietale Fallrook a Dun Garok, nella parte sudorientale delle Hillsbrad Foothills, e riporta un sacco dei loro Homebrew Hops.",
  progress = "Cerchi 'na birra nuova da provare?",
  reward = "Ecco l'odore dei luppoli che mi mancava! M'hai fatto un gran favore, $N: ogni volta che vado fino a Dun Garok di persona, ci metto giorni a ripartire. Una volta che mi ci son messo comodo, è dura staccarmi dai saloni di quella fortezza. Son contento di tenere sullo scaffale un po' di vecchi sapori per i fratelli nani. Eccoti un a little somethin' per l'aiuto.",
}
T[98072] = {
  title = "Coccodrilli del Cielo",
  desc = "Sei proprio $Guno:una; che si dà da fare! Mi resta solo un altro favore da chiederti, se te la senti di provare qualcosa di un po' più pericoloso.$B$BCoi coccodrilli il guadagno è sicuro, ma è poca roba rispetto a quello che rendono le scaglie di cucciolo di drago. Per un sacco di quelle la gente sgancia fior di quattrini.$B$BCoccodrilli del cielo, li chiamo io! Il mio apprendista non riuscirebbe mai a procurarmele — ma per te direi che è pane per i tuoi denti!$B$BI cuccioli di drago li trovi molto più a est, lungo la Green Belt. Ma sta' $Gattento:attenta;, su quelle colline ci sono brutti orchi!",
  obj = "Raccogli 8 Pristine Crimson Scales e portale a James Halloran a Menethil Harbor.",
  progress = "Ah, $N! Ce le hai quelle scaglie?",
  reward = "Sei proprio un talento naturale! Senti, se un giorno decidi di prenderti una pausa dalla vita d'avventura, torna pure dal tuo amico James. Ti metto subito al lavoro!$B$BCerto, a quel punto sarai ancora più $Gvecchio:vecchia;, immagino. Pazienza!",
}
T[98093] = {
  title = "Un Campo da Sgombrare",
  desc = "Per fortuna mi hai vista!$B$BStamattina era una giornata bellissima, così sono scesa a piedi da Camp Taurajo per la strada dorata. Ma quando è stato il momento di tornare non ci sono riuscita — un branco di iene ha cominciato a girarmi intorno e le lucertole Stormhide mi hanno sbarrato l'unica via di fuga.$B$BSono salita in fretta su quest'albero, e adesso, a quest'ora, ci sono troppi nemici in giro per tornare a casa di corsa attraverso i campi.$B$BTi dispiacerebbe sgominare queste Stormhide e le Hecklefang Stalkers?",
  obj = "Sulhasa, nelle Barrens meridionali, vuole che tu elimini 7 lucertole Stormhide e 7 Hecklefang Stalkers nella zona, così che possa scendere dall'albero senza pericolo.",
  progress = "Magari fra poco riuscirò a scendere senza farmi notare...",
  reward = "Grazie dell'aiuto, $N. A Camp Taurajo farò sapere che sei $Griuscito:riuscita; a salvarmi. Che fortuna che tu sia $Gintervenuto:intervenuta;, o sarei potuta restare bloccata lassù tutto il giorno!$B$BÈ tutto quello che posso darti, ma spero che ti torni utile.$B$BScenderò dall'albero con cautela, poi me ne andrò.",
}
T[98094] = {
  title = "Supporto agli Esploratori",
  desc = "Ora che possiamo affidarti informazioni cruciali da consegnare alle nostre spie in avanscoperta, ho un altro compito per te.$B$BPorta questo a Deathstalker Masoj, quasi esattamente a sud di qui. Consegnaglielo, e avrà altro da farti fare. È appostato su un'altura a nord del vigneto marcio che chiamano Nethander Stead.$B$BIl nostro piano per prendere il controllo di queste terre va avanti senza sosta.",
  obj = "High Executor Darthalia vuole che tu consegni gli ordini aggiornati a Deathstalker Masoj, a sud di Tarren Mill, fuori da Dun Garok.",
  progress = "Il tempismo è tutto...",
  reward = "Che carino. Una faccia nuova per il lavoro sul campo.$B$BBene, allora vediamo cos'hai.",
}
T[98095] = {
  title = "Postazioni Preziose",
  desc = "Il nostro alto comando sbarca truppe strategiche servendosi dei cavalcatori di pipistrelli. In alcuni punti chiave delle colline, però, i fari di segnalazione non ci sono più.$B$BPrendi queste fiale e stappale in tre luoghi: sulle colline al confine con Dun Garok, sull'altopiano che domina il Dunholde Keep e, l'ultima, sulla cresta dell'Headland sopra la città di Hillsbrad. Per i sensi dei pipistrelli, i vapori che ne usciranno saranno come un potente diapason, e li richiameranno di nuovo ai punti di sbarco stabiliti.$B$BCerca le empty vials andate in frantumi e rinnova i nostri segnali.",
  obj = "Il Deathstalker Masoj ha bisogno che tu metta le tre Apothecary Vials sulle cime attorno a Hillsbrad Foothills e che torni da lui.",
  reward = "Ottimo lavoro. Andiamo avanti con i piani.$B$BI Deathstalkers osano.$B$BChe lo scopo guidi i tuoi colpi, $N.",
}
T[98155] = {
  title = "Pristine Pesterhide Pelts",
  desc = "Le iene Pesterhide di Thousand Needles hanno i manti più splendidi che ci siano. In tutti i miei viaggi non ho mai visto un pelo di un colore così brillante!$B$BVorrei mandare qualche pelliccia alle mie sorelle a Stormwind, perché so che ci farebbero qualcosa di incredibile.$B$BDi combattimento non ne so niente, quindi ti sarei molto grata se potessi raccogliere tu per me qualche pelliccia di iena Pesterhide.",
  obj = "Porta 5 Pristine Pesterhide Pelts a Kristy Grant.",
  progress = "Sei $Griuscito:riuscita; a raccogliere le pellicce? Rendow mi ha promesso una mano a pulirle e conciarle, così potrò spedirle a casa! Le mie sorelle saranno entusiaste, lo so.",
  reward = "Grazie, $N! Queste pelli sono in perfette condizioni. Non dev'essere stato facile procurarne così tante: ti sono davvero grata per il lavoro che hai fatto.",
}
T[98156] = {
  title = "Pellicce Intatte Impacchettate",
  desc = "$N, mi sei $Gstato:stata; tanto d'aiuto che mi dispiace doverti chiedere un altro favore. Ci vorrà un po' prima che io possa tornare a casa, a Stormwind: ti andrebbe di consegnare queste pellicce alle mie sorelle al posto mio?$B$BCon ogni probabilità ci tornerai prima di me. Per favore, portale alle mie sorelle Kelly e Kimberly, a Stormwind: di solito stanno a The Park.",
  obj = "Porta il Package of Pristine Pelts a Kimberly Grant.$B$BOggetto fornito:",
  reward = "Questo viene da nostra sorella? Era da un po' che non sapevamo niente di lei. Spero che stia bene.$B$BPerbacco, che colore bellissimo hanno queste pellicce! Kelly e io ne faremo senz'altro buon uso.$B$BGrazie di aver fatto tutta questa strada. È bello sapere che Kristy sta ancora bene e che pensa a noi.",
}
T[98189] = {
  title = "Riporta la Statuetta",
  desc = "Santo cielo, è — è bellissima!$B$BLa Blind Princess doveva consegnarla a Menethil Harbor, prima che succedesse la tragedia. Ci mancava così poco!$B$BSe non sbaglio, a firmare per la consegna doveva essere Captain Stoutfist, nella Menethil Keep, proprio qui dietro. Che ne dici di avere tu l'onore di portare a termine il lavoro?",
  obj = "Porta la Menethil Statuette a Captain Stoutfist a Menethil Keep.",
  progress = "Che cos'hai lì? Fammi un po' vedere.",
  reward = "Sei $Griuscito:riuscita; a strapparla a quei mostri! Ormai del defunto re sono rimasti pochi cimeli.",
}
T[98190] = {
  title = "Un Amico di Famiglia",
  desc = "Ti conviene portarla subito a Stormwind. Sarò anche fiero che questa fortezza e il porto prendano il nome da King Terenas Menethil II, ma siamo un porto tranquillo in mezzo a una bruttissima tempesta di nemici. Qui non è sicuro, tutto qui.$B$BI Dragonmaw, soprattutto, sacrificherebbero molto pur di razziare una cosa del genere... e mi vengono i brividi a pensare a cosa ne farebbero.$B$BStavolta lascia perdere la catena di comando, $Gragazzo:ragazza;: va' dritto dal Gran Signore Fordragon. Lui saprà dove custodirla al meglio.",
  obj = "Porta la Menethil Statuette a Highlord Bolvar Fordragon a Stormwind Keep.",
  progress = "Parliamo, $C. Sento che hai con te qualcosa della Luce.",
  reward = "Ti ringrazio di averla recuperata. È un sollievo sapere che non è finita nelle mani sbagliate.",
}
T[98191] = {
  title = "Un Amico di Famiglia",
  desc = "King Terenas era un brav'uomo, un uomo devoto, amato dal suo popolo. Se questa Alleanza esiste, il merito è davvero suo.$B$BPer ironia, era umile — detestava le commemorazioni di questo genere, e così ne esistono ben poche. E di quelle, poche sono sopravvissute alla caduta di Lordaeron.$B$BSembra che la Luce si sia raccolta in questa statuetta. Il posto migliore per custodirla sarebbe la Cattedrale della Luce, nella Cathedral Square, al centro della città. Portala a Lord Grayson Shadowbreaker, perché la tenga al sicuro.",
  obj = "Porta la Menethil Statuette a Lord Grayson Shadowbreaker alla Cathedral of Light.",
  progress = "Che la Luce sia con te, $C. Si vede che non sei qui per fare due chiacchiere — di che si tratta?",
  reward = "Per la Luce... somiglia proprio a suo figlio...$B$B<Lord Grayson Shadowbreaker si interrompe per un istante.>$B$BQuesta statuetta è stata davvero benedetta. Il legame con Terenas, il fatto che sia sopravvissuta a ciò che quel mostro gli ha fatto... racchiude un grande potere, per chi crede nella sua forza.$B$BPer ora è meglio custodirla qui, sotto la protezione dell'ordine dei paladini. Continueremo a meditarci sopra per scoprire di più sui suoi doni, e forse potrà aiutarci nei tempi bui che ci aspettano.$B$BGrazie, $C. Che la Luce ti benedica.",
}
T[98192] = {
  title = "Scuoia Attento, Scuoia Affilato",
  desc = "Tu $Gpiccolo:piccola;! Tu aiuta Krak: spacca i morsicosi rossi e prende pelle a scaglie!$B$BKrak spacca morsicosi rossi per pelle a scaglie, però Krak ha mani troppo grosse. Krak taglia sempre pelli, pelli tutte piene di buchi.$B$BMa tu $Gpiccolo:piccola;! Tu va a sud in Dragonmurk, prende pelli da morsicosi rossi. Loro cattivi, loro veloci. Tu $Gpiccolo:piccola;, tu può finire $Gmangiato:mangiata;.",
  obj = "Porta 8 Intact Raptor Hides a Krak in Brackenwall Village.",
}
T[98197] = {
  title = "Bottino di Guerra",
  desc = "Questo porto, all'inizio, l'ha costruito l'Old Horde: le serviva come base per invadere Hillsbrad dal mare. Così ha aggirato del tutto le difese di Lordaeron!$B$BQuante vite perdute...$B$BE la cosa peggiore è che per costruire quella flotta hanno usato proprio le risorse rubate a Khaz Modan!$B$BQuando Admiral Proudmoore ha messo in fuga quei bruti e ha costruito questo posto per l'Alleanza, nel porto ne sono rimaste un sacco. Ci serviranno per rafforzare le difese della città, adesso che i Dragonmaw sono in marcia.",
  obj = "Recupera 6 Khaz Modan Timber e 30 Khaz Modan Iron da Menethil Harbor per Valstag Ironjaw.",
  progress = "Sotto le onde sta' all'erta. Laggiù è pieno di bestiacce!",
  reward = "Ah! È un po' bagnato, ma con qualche giorno al sole si sistemerà.$B$BGrazie, $C. Una volta tanto, che bello non dover contare solo sui carichi di Theramore o di Auberdine!",
}
T[98208] = {
  title = "Fiore dei Cieli",
  desc = "Vengo da Auberdine, dal grande albero Teldrassil, e sono arrivata fin qui a Menethil Harbor per recuperare un fiore molto importante per la mia gente.$B$BMolte lune fa la nostra nave, la Flying Osprey, è naufragata qui insieme alla Kul Tiran Third Fleet. Fra il carico c'era il fiore noto come Nord'el — Fiore dei Cieli nella tua lingua — sbocciato sotto la luna piena in cima al Mount Hyjal, la nostra antica dimora.$B$BTi prego, aiutami a riprenderlo! Il relitto è poco a sud della città, ma è abitato da feroci murloc raiders!",
  obj = "Recupera il Nord'el per Sylessa Duskwhisper a Menethil Harbor.",
  progress = "Sei $Gstato:stata; al relitto? Uno spettacolo davvero cupo.",
  reward = "È sopravvissuto! Oh, sia lodata Elune!$B$BGrazie mille, $N. E se sei $Gdisposto:disposta;, avrei un altro favore da chiederti...",
}
T[98209] = {
  title = "Fiore dei Cieli",
  desc = "Potresti portare il Nord'el all'anziano Thundris Windweaver, ad Auberdine?$B$BCon la barca che parte da qui dovresti arrivarci in fretta.$B$BScusami se te lo chiedo, davvero. Sono ancora stanca per il viaggio fin qui — e per la fuga da quei diavoli di murloc, la prima volta che ho provato a recuperare il fiore sacro!",
  obj = "Porta il Nord'el a Thundris Windweaver ad Auberdine, in Darkshore.$B$BRicordi che Sylessa ha parlato di una barca a Menethil Harbor che può portarti lì.",
  progress = "Ti do il benvenuto ad Auberdine, $C. In che modo possiamo aiutarti nei tuoi viaggi?",
  reward = "Il Nord'el è sopravvissuto? Non è possibile... dopo tutti questi anni!$B$BQuant'è meravigliosa la nostra dea!$B$BTi ringrazio di averlo portato qui. Nei tempi bui che abbiamo attraversato di recente è una luce rara, e un simbolo non solo della grazia di Elune, ma anche della tenace volontà del nostro popolo di andare avanti senza l'immortalità.$B$BLo farò trasportare al sicuro a Darnassus, perché possa essere coltivato come si deve.",
}
T[98216] = {
  title = "Comprendere il Nostro Presente",
  desc = "Old Gods?! Non può proprio essere una buona notizia!$B$BHo decifrato un altro pezzo della pietra, e parla di una specie di guardiano. Qualunque cosa sia, dev'essere legato alla pietra!$B$BPortala con te e guarda se nello scavo trovi un qualche grosso costrutto dei Titani. Leggi questo passaggio qui, l'ultimo della pietra, e vedi cosa succede!$B$BSe ho ragione, quell'affare lo attiverai. In quel caso abbattilo, ma cerca di salvare tutto quello che c'è di interessante! Dobbiamo assolutamente saperne di più!",
  obj = "Usa la Goaz Stone vicino al Goaz Warder e riporta la sua Titanic Keystone a Prospector Whelgar.",
  progress = "La pietra ha fatto qualcosa?!",
  reward = "Guarda lì — vedi come la Goaz Stone comincia a brillare vicino alla chiave di volta? Riesco quasi a distinguerci altre parole...$B$BSu questo Goaz dobbiamo scoprire ancora di più. Ho la sensazione che sia solo la punta dell'iceberg di qualcosa di enorme!",
}
T[98219] = {
  title = "Il Tenente Disonorato",
  desc = "Grazie ancora per aver consegnato sana e salva la statuetta, $N.$B$BMi farebbe comodo il tuo aiuto anche per un'altra cosa. Un membro della guardia cittadina è stato trasferito a Southshore, nelle Hillsbrad Foothills.$B$BSuo padre era mio amico e, anche se non nego che una lezione gli farebbe bene... vorrei comunque vederlo farcela. Avere qualcuno come te ad aiutarlo gli sarebbe davvero utile.$B$BSe ripassi da Menethil Harbor, da lì parte una nave che può portarti da quelle parti.",
  obj = "Parla con Lieutenant Farren Orinelle a Southshore, in Hillsbrad Foothills.",
  reward = "Ah, ma certo. $GUn altro:Un'altra; dei migliori di Stormwind, $Gvenuto:venuta; qui a controllarmi. Come il mese scorso!",
}
T[98221] = {
  title = "Dalle Ceneri",
  desc = "Durante la Second War i Dragonmaw hanno costruito una flotta proprio qui, dove siamo adesso, per conquistare Hillsbrad. E ce l'hanno quasi fatta!$B$BI draghi rossi li hanno messi in rotta, e di loro sono rimasti pochi sbandati nel cuore delle montagne. Eppure all'improvviso nel loro accampamento a nord-est di Menethil c'è molto più movimento.$B$BDun Algaz è la prova che vogliono tornare in guerra e riprendersi questa terra. Trova i loro piani d'attacco, annota ogni informazione cruciale e poi distruggili. Dobbiamo sapere dove colpiranno la prossima volta!",
  obj = "Captain Stoutfist a Menethil Keep vuole che tu distrugga le 4 serie di Piani d'Attacco in Angerfang Encampment.",
  progress = "Le guerre si vincono — e si perdono — con le informazioni. Ti conviene ricordartelo.",
  reward = "Anche Ironforge? Nek'rosh l'ambizione di suo padre ce l'ha di sicuro!$B$BQuello che gli manca, naturalmente, è l'esercito di draghi rossi ridotti in schiavitù che in guerra si è rivelato tanto devastante. Ha fatto un azzardo, non c'è dubbio — e lo pagherà caro.",
}
T[98223] = {
  title = "Vecchie Abitudini",
  desc = "Questo libro è stato bruciato quasi del tutto — forse dal fuoco dei draghi che ha distrutto gran parte del clan Dragonmaw.$B$BDa quel poco che si legge, sembra parlare dei rituali per usare l'Anima del Demone, con cui il clan aveva controllato i draghi.$B$BNe resta troppo poco perché serva davvero a qualcosa, ma dalle pagine di pelle animale aggiunte alla buona sembra che Nek'rosh abbia cercato di recuperarlo. Un inchiostro asciugato da poco parla di un \"Shadow Council.\"$B$BCaptain Stoutfist, a Menethil Harbor, vorrebbe saperlo.",
  obj = "Porta il Tattered Spellbook a Captain Stoutfist a Menethil Harbor.",
  progress = "Quasi le sento da qui, le grida dei Dragonmaw! Si meritano tutto quel che gli è successo, e anche di più.",
  reward = "Meglio distruggerlo. Utile o no, con quegli orchi schifosi non possiamo correre rischi.$B$BCi mancano solo i cavalcadraghi alle porte!$B$BE questa storia dello Shadow Council... mi preoccupa molto. Avvertirò subito i miei superiori.",
}
T[98230] = {
  title = "Questa Terra Era la Loro Terra",
  desc = "Dopo la War of the Three Hammers, che fece a pezzi la vita dei nani così come la conoscevamo, i Granmartello si stabilirono qui e fondarono la fortezza di montagna di Grim Batol.$B$BEra un posto meraviglioso. Ovunque guardassi c'erano grifoni in volo, che piombavano sulle paludi ad afferrare un pesce.$B$BPurtroppo durò poco.$B$BHowin Kindfeather è tra i primi Granmartello tornati dopo tanto tempo. Se ne sta per conto suo, lontano dal villaggio. Segui la strada verso est — prima o poi lo troverai. Una mano gli farebbe di sicuro comodo.",
  obj = "Trova Howin Kindfeather a est di Menethil Harbor, lungo la strada.",
  reward = "Se sei qui per dare una mano, non ti dico di no. Di 'sti tempi trovare aiuto è proprio dura.",
}
T[98240] = {
  title = "Consegna della Crimson Crate",
  desc = "Ormai è ufficiale, $N: la voce su quei cuccioli di drago si è sparsa. Abbiamo già un ordine!$B$BTe li impacchetto per bene, e tu porti tutto al cliente. Lo so, lo so; è solo un ultimo favore, te lo prometto!$B$BQuesti sono per un certo \"Howin Kindfeather\". Figurati che ha mandato in città il suo grifone con una lettera per l'ordine! Dice che sta appena fuori dalla strada a est, poco oltre i Whelgar's Excavation Site, se li conosci.",
  obj = "Porta la Crimson Crate a Howin Kindfeather, appena fuori dalla strada a est di Menethil Harbor.",
  progress = "Di passaggio, $C?",
  reward = "Sono perfetti. Grazie di essere $Gvenuto:venuta; fin qui.",
}
T[98245] = {
  title = "Punzecchiando i Razormaw",
  desc = "Non so chi odio di più: quei maledetti Dark Irons, i Dragonmaw o i draghi che cavalcavano.$B$B<Howin sputa.>$B$BHo intenzione di sistemare le cose, ma ci servirà un po' di materiale.$B$BQueste scaglie di cucciolo di drago riparano parecchio dal fuoco dei draghi, ma intrecciarle è una rottura di palle.$B$BI raptors Razormaw, su alla Cresta dei Raptor a nord-est e nella Saltspray Glen a nord-ovest, devono il nome ai loro dentoni aguzzi — e quelli le scaglie dovrebbero riuscire a bucarle.$B$BPortami una manciata di quegli incisivi.",
  obj = "Raccogli 10 Razormaw Incisors per Howin Kindfeather.",
  progress = "Sei $Griuscito:riuscita; a strappare quei denti? Mi servono interi, così sulle scaglie non si spezzano subito.",
  reward = "Ci verrà fuori una bella serie di punteruoli. Grazie.",
}
T[98246] = {
  title = "Tempi Duri",
  desc = "Se voglio che il mio piano funzioni, mi servono delle uova. Bassbeak deve avere la pancia bella piena — non sono il tipo che salta in groppa a un grifone scorbutico.$B$BE devono essere perfette — niente crepe o roba del genere.$B$BVai a prenderle dai raptors Razormaw — son famosi per i tuorli grossi come la zucca di uno gnomo. Ne trovi a Raptor Ridge, a nord-est, e nella Saltspray Glen, a nord-ovest.$B$BFacciamo una bella dozzina tonda, per sicurezza.",
  obj = "Raccogli 12 Razormaw Eggs Perfette per Howin Kindfeather.",
  progress = "I Razormaw non la prenderanno per niente bene se gli porti via le uova, quindi tieniti $Gpronto:pronta; a una zuffa.",
  reward = "Non servono al mio piano — sono per sfamare Bassbeak. Credimi, quando ha fame non serve a niente. E se le girano le scatole, potrebbe essere più pericolosa degli orchi!$B$BDi questi tempi, da queste parti, non è facile trovare cibo che non sia contaminato...",
}
T[98247] = {
  title = "Etichetta di Spedizione",
  desc = "<Sul fianco della cassa, ora piena, c'è un'etichetta di spedizione strappata. Il nome del destinatario è finito nella parte mancante, ma le indicazioni sulla provenienza si leggono ancora.$B$B\"Proprietà dell'Autorità Commerciale di Azeroth. Si prega di restituire le casse vuote o le spedizioni non consegnate al nostro polo commerciale locale, all'incrocio di Three Corners, nelle Redridge Mountains. I corrieri saranno ricompensati per il tempo e il viaggio.\"$B$BAccanto al testo c'è una mappa, disegnata alla buona, dei dintorni della destinazione indicata.>",
  obj = "Consegna l'Etichetta di Spedizione a qualcuno al polo commerciale dell'Autorità Commerciale di Azeroth, a Redridge Mountains.",
  progress = "Ah, salve! Come posso esserti utile?",
  reward = "Sei $Garrivato:arrivata; nel posto giusto! Sarò felice di registrarti come $Gun nostro affiliato:una nostra affiliata;. Nessun contratto da firmare e nessun impegno che ti pesi sulle spalle. Ti chiediamo soltanto di aiutarci con diligenza a completare o a restituire qualunque nostra spedizione troverai durante i viaggi.$B$BQuando lo farai, riceverai in compenso il Favore del Mercante, con cui potrai acquistare i beni e i servizi che offriamo qui. Anzi, eccotene un po' per cominciare.$B$BE ora, hai per caso la cassa da cui viene questa etichetta?",
}
T[98248] = {
  title = "Etichetta di Spedizione",
  desc = "<Sul fianco della cassa, che ora è piena, c'è un'etichetta di spedizione strappata. Lo strappo si è portato via il destinatario, ma da dove viene la spedizione si legge ancora.$B$B\"Restituite le spedizioni danneggiate o le casse vuote all'avamposto commerciale della Durotar Supply and Logistics, che ora si trova in una comoda posizione esattamente a ovest del Crossroads, nelle Barrens. Il vostro tempo è prezioso e vi ricompenseremo per il disturbo!\"$B$BAccanto alla scritta c'è una mappa disegnata alla buona dei dintorni della destinazione indicata.>",
  obj = "Consegna l'Etichetta di Spedizione a qualcuno presso lo snodo commerciale della Durotar Supply and Logistics, vicino al Crossroads, in Barrens.",
  progress = "Buongiorno, $Gviaggiatore:viaggiatrice;. Cosa posso fare per te?",
  reward = "Hai trovato il posto giusto e stai parlando con la persona giusta! Posso segnarti come $Guno:una; dei nostri nuovi soci. Da parte tua non serve nessuna scartoffia, e io non ho proprio voglia di vederne altre.$B$BTi chiediamo solo di darci una mano con le consegne compromesse che trovi per strada. Così guadagnerai Favore del Mercante, che potrai spendere qui per comprare merci e servizi. Ecco qualcosa per cominciare!$B$BPer caso hai la cassa su cui era attaccata questa etichetta?",
}
T[98251] = {
  title = "Non Tornerò Mai Più",
  desc = "Gaaah! Sono così $Garrabbiato:arrabbiata;. Dicevano che ad Ashenvale era facile orientarsi. Facile per chi? Per le bestie? Per gli uccelli? Un attimo prima raccoglievo un'erba, un attimo dopo eccomi $Gintrappolato:intrappolata; in questo burrone. E adesso dovrei girare mezza foresta per tornare dov'ero pochi istanti fa? Quando sono in questo stato, gli incantesimi diventano instabili e si comportano... in un altro modo. Potresti sfoltire la fauna qui intorno? Mi danno sui nervi persino quei loro stupidi zoccoli. Detesto questa foresta maledetta.",
  obj = "Uccidi 6 Shadowhorn Stag e 6 Ashenvale Bear e torna da Va'xug Firefure a nordovest del Fallen Sky Lake.",
  progress = "Appena sarò $Guscito:uscita; da qui, non ci rimetterò mai più piede.",
  reward = "Ah! Ben vi sta, bestie! Grazie. A quanto pare è già servito.",
}
T[98252] = {
  title = "Un Sentiero nel Vuoto",
  desc = "Guida il mio Eye of Kilrogg fuori da questo burrone, fino alla strada di Ashenvale. Fallo muovere senza fermarti: quando vedrò un passaggio libero, lo seguirò. Io resto qui — almeno uno di noi deve sapere dove si trova. Se ti perdi, attraverso l'occhio posso riportarti indietro: non voglio che finiamo a vagare tutti e due alla cieca in questa foresta maligna. Riesco a mantenere la canalizzazione per quattro minuti, non di più. Raggiungi la strada prima che la visione svanisca, oppure torna da me e ci riproviamo.",
  obj = "Mostra a Eye of Kilrogg di Va'xug la via per tornare sulla strada principale di Ashenvale.",
  reward = "<Dall'interno dell'occhio fluttuante senti riecheggiare la voce di Va'xug.>\"Bastava così poco? Poco importa. Quando richiamerò quell'indisciplinato del mio Voidwalker, questa visione mi aiuterà a tenerlo in riga sul sentiero giusto. Grazie, $Gviaggiatore:viaggiatrice;. Attraversa questa foresta con passo sicuro.\"<Eye of Kilrogg comincia a dissolversi.>",
}
T[98282] = {
  title = "Pericoli Alchemici",
  desc = "Per certe ricette alchemiche servono ingredienti che si trovano in posti, beh, molto pericolosi. E spesso parliamo solo delle erbe di base! Il resto è anche peggio!$B$BPrima di ripartire devo preparare altro antiveleno. Giuro, in questa palude è tutto velenoso. Sembra che il veleno scorra nella terra stessa!$B$BMi daresti una mano? Mi servirà una ghiandola del veleno dei ragni che stanno al Thelgen Rock, all'estremo sud-est. Però dev'essere intatta, altrimenti perderà troppo veleno prima che tu riesca ad arrivare qui. Scusami!",
  obj = "Raccogli un'Unruptured Stalker Gland da Thelgen Rock per Caitlin Grassman a Menethil Harbor.",
  progress = "Allora, avuto fortuna? Lo so che è una seccatura chiedertelo, ma mi serve proprio una ghiandola intera!",
  reward = "Oh, perfetto! È proprio quello che mi serve. Sai, sei $Gun vero eroe:una vera eroina;.$B$BTi prego, accetta una parte dei frutti delle tue fatiche: se non li dividessi con te, mancherei al mio dovere. E fa' attenzione là fuori!",
}
T[98283] = {
  title = "Carnage",
  desc = "L'ordine naturale di questa terra si sta spezzando. Un tempo erano i raptors Razormaw a impedire alla vegetazione di crescere troppo. Ora hanno paura del loro capobranco, che deve il nome soltanto alla carneficina che si lascia alle spalle.$B$BTemo che la bestia sia impazzita per il morbo che non siamo ancora riusciti a estirpare del tutto.$B$BA nord-est, sotto la Cresta dei Raptor, ci sono degli orsi malati: la loro carne maligna lo attirerà. Lascia le interiora nella caverna che gli fa da tana.$B$BCarnage arriverà. Portami la sua testa.",
  obj = "Porta la Carnage's Head a Rethiel the Greenwarden in The Green Belt.",
  progress = "Ormai impazziti, i Rotclaw sono scesi dalle loro case a Loch Modan.$B$BChe spreco del dono della vita.",
  reward = "Con la morte di Carnage il suo branco ritroverà l'equilibrio. Forse basterà a far guadagnare tempo all'ecosistema più vasto che sostengono.$B$BVedremo, ma ti ringrazio comunque per l'impegno.",
}
T[98284] = {
  title = "Campeggio 101: Incantamento",
  desc = "Gli incantatori rendono migliore qualunque cosa, e in un accampamento nelle terre selvagge sono sempre i benvenuti.$B$BMi sa che conosco qualcuno che può insegnarti a creare un Enchanted Lute per il tuo accampamento. Quando ci si ferma a riposare, distrarsi un po' è importantissimo, e questo pizzico di magia può aiutarti a essere $Gpronto:pronta; ad affrontare sfide di ogni tipo quando ti rimetterai in viaggio.",
  obj = "Parla con Nasalanna Windsinger a Shen'dar Village per imparare a creare un oggetto da campeggio per la tua professione, dopo aver dimostrato di essere $Gbravo:brava; nella tua abilità.",
  reward = "Ecco fatto: ora puoi creare un Enchanted Lute tutto tuo. Alla gente, di solito, non piace granché che ci si accampi in mezzo alla città, quindi per provarlo dovrai andare nelle terre selvagge.$B$BAh, e ricordati che un accampamento non è completo senza un fuoco da campo: prima di sistemarti te ne servirà uno. Quasi tutti i cuochi possono insegnarti ad accenderlo. Se non l'hai già fatto, potresti andare da chi insegna le arti culinarie e imparare le basi.",
}
T[98285] = {
  title = "Campeggio 101: Ingegneria",
  desc = "Un ingegnere se la cava sempre, e quando sei $Gsolo:sola; nelle terre selvagge ti conviene poter mettere a frutto il tuo mestiere. Senza qualche costrutto utile, nessun buon accampamento è completo!$B$BSì, torna da me quando avrai un po' di esperienza come ingegnere, e ti farò vedere come costruire qualcosa di speciale!",
  obj = "Parla con lo Strange Hermit a Shadowgale Forest per imparare a creare un oggetto da campeggio per la tua professione, dopo aver dimostrato di essere $Gbravo:brava; nella tua abilità.",
  reward = "Ecco fatto: ora puoi creare un Reagent Bot tutto tuo. Alla gente, di solito, non piace granché che ci si accampi in mezzo alla città, quindi per provarlo dovrai andare nelle terre selvagge.$B$BAh, e ricordati che un accampamento non è completo senza un fuoco da campo: prima di sistemarti te ne servirà uno. Quasi tutti i cuochi possono insegnarti ad accenderlo. Se non l'hai già fatto, potresti andare da chi insegna le arti culinarie e imparare le basi.",
}
T[98286] = {
  title = "Campeggio 101: Incantamento",
  desc = "Gli incantatori rendono migliore ogni cosa, e in qualsiasi accampamento delle terre selvagge sono sempre i benvenuti.$B$BMi sa che conosco qualcuno che può insegnarti a creare un Enchanted Lute per il tuo accampamento. Nei momenti di riposo è così importante trovare un po' di svago, e questo pizzico di magia può aiutarti a essere $Gpronto:pronta; ad affrontare ogni genere di sfida quando ti rimetterai in viaggio.",
  obj = "Parla con Nasalanna Windsinger a Shen'dar Village per imparare a creare un oggetto da campeggio della tua professione, una volta che avrai dimostrato la tua bravura.",
  progress = "Sì, posso insegnarti.",
  reward = "Ecco fatto: ora puoi creare un Enchanted Lute tutto tuo. Di solito alla gente non va molto a genio vedere accampamenti montati in mezzo al paese, quindi se vuoi provarlo dovrai andare nelle terre selvagge. Ah, e ricorda: un accampamento non è completo senza un fuoco da campo, e prima di accamparti te ne servirà uno. Quasi tutti i cuochi possono insegnarti ad accenderlo. Se non l'hai ancora fatto, potresti passare da qualcuno che ti addestri nell'arte culinaria e imparare le basi.",
}
T[98287] = {
  title = "Campeggio 101: Ingegneria",
  desc = "Gli ingegneri come te sanno inventarsi aggeggi, robot e bombe di ogni sorta, per divertimento e per profitto.$B$BCredo di sapere chi può insegnarti a costruire un Reagent Bot per il tuo accampamento. È un automa utile, che può aiutarti a restare sempre $Gben rifornito:ben rifornita;: così a te e ai tuoi alleati non mancheranno mai i materiali per alimentare gli incantesimi.",
  obj = "Parla con Sprite Jumpsprocket a Stormwind per imparare a costruire un oggetto da campeggio per la tua professione, una volta che avrai dimostrato di padroneggiarla.",
}
T[98291] = {
  title = "Morte ai Dragonmaw",
  desc = "Ho intenzione di tornare a Grim Batol e riprendermela per i Wildhammer, $N. O come minimo scoprire qualcosa.$B$BE non guardarmi così, eh. I rischi li conosco. Non ci entrerò mica a martello spianato, sai.$B$BComunque, prima ho bisogno del tuo aiuto. Gli orchi Dragonmaw si sono già messi in marcia e sono dappertutto, su e giù per il Dragonmaw Retreat, dove un tempo i draghi rossi li hanno sbaragliati.$B$BDevi sfoltirgli le file, altrimenti non avrò nessuna speranza di avvicinarmi. Prendi la strada verso est e li troverai di sicuro.",
  obj = "Uccidi 8 Reclaimers Dragonmaw, 5 Vincolanime Dragonmaw e 3 Infiltratori Dragonmaw nel Dragonmaw Retreat per Howin Kindfeather.",
  reward = "Non sarò certo io a piangere per gente della loro risma. Hanno fatto la fine che si meritavano.",
}
T[98293] = {
  title = "Disarmo Forzato",
  desc = "I Dragonmaw stanno ammassando armi di ogni tipo, e sarebbe saggio portargliele via prima che ci armino altri soldati.$B$BCaptain Stoutfist, alla Menethil Keep, ne sarebbe di certo interessato.",
  obj = "Raccogli 30 Dragonmaw Armaments nel Dragonmaw Retreat, poi portali a Captain Stoutfist alla Menethil Keep.",
  progress = "Che cos'hai lì, $C?",
  reward = "Ben fatto! Davvero ben fatto!$B$BDi sicuro possiamo usarli per rifornire i nostri uomini. Del resto, metà erano dei nostri soldati.$B$BMeno armi in mano al nemico e più nelle nostre: è questa la matematica che piace a me, $C.",
}
T[98297] = {
  title = "Spezzare il Ciclo",
  desc = "Mentre eri via ho fatto un breve volo di prova. La buona notizia è che l'armatura che mi hai aiutato a forgiare per Bassbeak funziona a meraviglia!$B$BLa pessima è che ho visto un gruppo di quei Dragonmaw intenti a ridurre in schiavitù un red dragonspawn.$B$BAssolutamente no. Non un'altra volta.$B$BDevi eliminarlo, e di sicuro ti serviranno degli amici. Prima uccidi gli stregoni che lo tengono sottomesso — dovrebbe bastare per liberarlo. Poi metti fine alle sue sofferenze.$B$BNessuno di loro sbarrerà la strada ai Wildhammer.",
  obj = "Uccidi il Subdued Dragonspawn al Dragonmaw Gates per Howin Kindfeather.",
  reward = "Non so come ringraziarti, $N. Davvero, per quello che hai fatto oggi non potrò mai ripagarti abbastanza. Prima che Grim Batol possa sentire di nuovo le risate dei piccoli nani echeggiare nelle sue sale c'è ancora molto da fare, ma questo è un bel passo avanti. Per tutti i nani perduti in quei giorni bui, forse potremo ancora riprenderci ciò che era nostro. O almeno, speriamo.",
}
T[98298] = {
  title = "La Follia di Arugal",
  desc = "Ah, adesso è tutto così chiaro che è quasi imbarazzante! Di magia Arugal ne aveva ben poca, figuriamoci abbastanza da creare i worgen. 'Maledizione di Arugal.' Bah! Dura a malapena qualche secondo.$B$BQueste manette dimostrano che sa vincolare le bestie, non crearle. Evidentemente i worgen diffondono la loro maledizione in un altro modo. Vorrei sapere quale.$B$BVai al Greymane Wall, a sud. A quanto pare i worgen si stanno propagando fra gli umani della zona. Fai a pezzi le bestie e portami tutto ciò che trovi. Qui serve un approccio più diretto.",
  obj = "Porta 6 Worgen Bits a Dalar Dawnweaver, a The Sepulcher.",
  progress = "Zanne, artigli, ventrigli. Per me non fa differenza. Il modo più semplice per studiare qualcosa è vederne le budella con i propri occhi.",
  reward = "A quanto pare rido io per ultimo, dopotutto, ahah! Arugal era davvero uno sciocco. E io, Dalar Dawnweaver, l'ho smascherato: è un impostore.$B$BQuesti pezzi bastano a provarlo: la maledizione non ha niente a che vedere con quell'idiota farneticante.$B$BPurtroppo significa che anche il suo rimedio non vale nulla. Pare che dovremo continuare a cercare una soluzione alla maledizione dei worgen.",
}
T[98299] = {
  title = "Fermare la Diffusione",
  desc = "Una cosa la sappiamo: dietro i worgen di Silverpine c'è Arugal, che siano macchinazioni sue o no. Quello che non sappiamo è come si diffonde.$B$BIo cerco un modo per fermare la maledizione, ma intanto la priorità è contenerla. Pare che questo morbo non possa contagiare i forsaken come noi, però un folto gruppo di umani si è radunato presso il Greymane Wall.$B$BVa' al muro ed elimina quei rifugiati prima che possano diventare servi di Arugal.",
  obj = "Uccidi 5 Sickly Refugees e 5 Haggard Refugees per Dalar Dawnweaver a The Sepulcher.",
  progress = "Un esercito di sickly refugees non è certo un problema, ma una nuova ondata di bestie worgen è tutt'altra faccenda. Va' a sfoltirli prima che ci travolgano.",
  reward = "A quanto pare i Gilneans non hanno molta voglia di lasciar passare nessuno oltre il loro muro. Credo sia una fortuna: probabilmente vuol dire che la maledizione dei worgen non ha modo di diffondersi nella loro città.$B$BRiesci a immaginare la depravazione, se si infettasse un intero regno?",
}
T[98300] = {
  title = "Notizie per Ironforge",
  desc = "Qui il mio lavoro è tutt'altro che finito, $N. E poi devo mandar notizie a mia moglie Claira ad Aerie Peak — e aggiornare pure Falstad.$B$BMa son affari miei. Affari dei Wildhammer.$B$BDetto questo, faresti bene a raccontare tutto anche a King Magni Bronzebeard a Ironforge. Le Wetlands sono a un tiro di schioppo dalle sue terre, e quel che succede qui non è roba da avere alle porte di casa. Questa lettera dovrebbe bastare.$B$BPer arrivare a Ironforge puoi tornare passando da Dun Algaz, oppure prendere il volo da Menethil Harbor.",
  obj = "Consegna l'Howin's Missive a King Magni Bronzebeard a Ironforge.",
  progress = "$GBenvenuto:Benvenuta; a Ironforge, $C. Io sono King Magni Bronzebeard, sovrano di queste terre.",
  reward = "Ah, i Wildhammer. Sì, li conosco bene. Non mi chiameranno sovrano, ma ultimamente i nostri rapporti sono migliorati molto — il Thandol Span lo dimostra.$B$BSe quel che riferisce questo Howin è vero, dobbiamo prepararci ad agire di nuovo sui nostri confini a nord. Grim Batol ha una storia lunga e sanguinosa, e so bene quanto conti sul piano strategico.$B$BHai la mia gratitudine per esserti $Gimpegnato:impegnata; ad aiutare i Wildhammer nelle Wetlands, e anche l'Alleanza a Menethil Harbor.",
}
T[98310] = {
  title = "Intravedere il Nostro Futuro",
  desc = "Per le Wetlands ci sono sparsi altri golem, più grandi. Hanno addosso delle iscrizioni che li indicano come Ados, Modr, Golm e Neru — proprio come i pezzi mancanti della Goaz Stone che hai trovato!$B$BCi scommetterei: se riusciamo a portare qui anche dei pezzi di quelli, scopriremo un'altra parte della Goaz Stone!$B$BAdos lo trovi al Dragonmaw Gates, a est, vicino a Grim Batol. Modr sta appena fuori da Dun Modr, a nord. Golm è sotto Grim Batol, a est di Dun Algaz. Neru è dietro il Direforge Hill, a nord-est.",
  obj = "Usa la Goaz Stone vicino ad Ados, Modr, Golm e Neru e riporta i loro cuori a Prospector Whelgar.",
  progress = "Fa' attenzione là fuori. Ho il sospetto che questi costrutti saranno più duri del custode.",
  reward = "Per la barba di Magni, sono bellissimi! Aspetta un attimo, lo vedi?! Avvicina un momento i cuori alla Goaz Stone...$B$B<Sulla pietra compare un nuovo testo, in una debole luce scintillante.>$B$BMmh, si legge a fatica. \"Maledizione della Carne... falliranno.\" Che cosa vorrà dire?!$B$BDobbiamo portarla in un posto sicuro, così potremo studiarla meglio!",
}
T[98313] = {
  title = "Per Ulteriori Studi",
  desc = "Qualunque cosa sia, $N, è roba epica, poco ma sicuro.$B$BTi impacchetto tutto per bene e tu lo porti a Historian Karnik, nell'Hall of Explorers a Ironforge. Di solito sta in fondo, col naso affondato in qualche tomo della biblioteca.$B$BPer venire a capo di questa faccenda ci vorrà un vero e proprio esercito, ma da quello che abbiamo visto finora ne varrà davvero la pena!",
  obj = "Porta il Whelgar Relic Package a Historian Karnik a Ironforge.",
  progress = "Chiedo scusa, ma sono terribilmente, terribilmente impegnato. Ti serviva qualcosa?",
  reward = "Ma guarda un po'...$B$BC'è un sacco di roba da esaminare! Ma è molto emozionante. MOLTO emozionante!$B$BGià solo per mettere insieme un piano mi ci vorrà del tempo. Torna un'altra volta e ti aggiornerò. Intanto, accetta i ringraziamenti dell'Explorers' League.",
}
T[98326] = {
  title = "Frosthowl",
  desc = "Lo sai quanto è difficile pescare su un lago ghiacciato? Quel pover'uomo di mio marito, Paxton, è là in mezzo da giorni, e siamo riusciti a riempire a malapena un sacco.$B$BBeh, un sacco ce l'AVEVAMO. Poi quello stramaledetto wendigo mi ha aggredita e se l'è filata col nostro pescato. Ci vorranno settimane per ripescare tutto! Sempre che quello sbraitone di Frosthowl non abbia fatto scappare tutti i pesci.$B$BFacci un favore e riportacelo, eh? Quel bruto sbavante si nasconde da qualche parte in fondo alla Grizzled Den, a sudest.",
  obj = "Uccidi Frosthowl e recupera il Sack of Fish per Gretta Ganter a Brewnall Village.",
  progress = "Prima si scioglie la neve di Dun Morogh che io vada a dire a Paxton che mi sono fatta fregare tutta la sua scorta da un wendigo.",
  reward = "Mi hai proprio salvato la vita, $N!$B$BMio marito ci avrebbe riso sopra e basta, ma non avrei avuto il cuore di dirgli che doveva passare un'altra notte sul lago. Magari adesso possiamo goderci un vero banchetto.",
}
T[98340] = {
  title = "Il Great Cat Spirit",
  desc = "Sembra che tu sia $Gpronto:pronta; per il prossimo passo del tuo viaggio, giovane $C. Dendrite Starblaze ti ha mandato a chiamare: desidera che tu torni a cercarlo a Moonglade.$B$BHai già imparato a invocare la magia che ti porta a Moonglade, quindi, se lo desideri, dovresti poter partire subito. Se vuoi continuare l'addestramento druidico, ti consiglierei di metterti presto in cammino.",
  obj = "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.",
  reward = "E così continua, Father Cenarius.$B$B<Dendrite traccia nell'aria sopra di sé un gesto rapido e invisibile, e una lieve aura di potere scende su di lui.>$B$BTi saluto di nuovo, $N. È tempo che tu impari la prossima prospettiva della natura: il felino. Ti metterò sul sentiero per comprendere questo aspetto della vita druidica ma, proprio come per l'orso, sta a te abbracciare questo insegnamento e diffonderlo.",
}
T[98341] = {
  title = "Il Grande Spirito Felino Portato dal Vento",
  desc = "Da poco è comparso qui uno spirito della tua terra natia, e mi ha chiesto di guidarti da lui. È uno spirito felino portato dal vento, venuto a istruirti e a farti da mentore, perché tu possa assumere la forma felina che ha su Zephras.$B$BPrima o poi ogni druido va in cerca di questa saggezza, anche se dalle tue parti, a quanto pare, la forma è un po' diversa da quella della nostra tradizione. Se desideri assumere la forma felina di questo spirito, dovrai affrontare la nostra prova.$B$BLo troverai a sud dei ponti gemelli, nella parte meridionale di Moonglade.",
  obj = "Cerca l'Avatar of Saeyleenan nella parte meridionale di Moonglade e scopri cosa ha da insegnarti sulla natura del felino portato dal vento.",
  reward = "Saluti, giovane shen'dorei. Sono $Gvenuto:venuta; da te perché sento che sei $Gpronto:pronta; ad affrontare la prova, quella che stabilirà se comprendi o no la mia natura spirituale.$B$BTi sottoporrò alla prova del Great Cat Spirit di Azeroth, ma tu vieni da Zephras, e i tuoi progressi ho voluto seguirli di persona. Dopotutto è la mia forma che assumeresti, non quella di uno spirito felino di Azeroth.$B$BCominciamo.",
}
T[98342] = {
  title = "Il Great Cat Spirit",
  desc = "Per attingere al mio spirito non ti basteranno poche parole. Se vuoi comprendere e rispettare la mia forma, devi dimostrare di saper incarnare l'astuzia, la furtività e, se dovessi trovarti $Gmesso:messa; alle strette, la ferocia.$B$BAppena a est di qui, nelle Barrow Dens, ci sono tre reliquie del mio favore che devi recuperare. Le sorvegliano potenti spiriti infuriati, pronti ad attaccarti appena ti vedono. All'ingresso c'è una statua: ti benedirà e ti renderà $Gfurtivo:furtiva; per un po', così potrai superarli.$B$BRiportami queste reliquie, e vedremo se sei $Gpronto:pronta; a prendere la mia forma.",
  obj = "Recupera la Relic of the Fang, la Relic of the Claw e la Relic of the Silent Shadow dalla Tana dei Tumuli di Stormrage, e riportale al Great Cat Spirit.",
  progress = "Ah, sei $Gtornato:tornata;. Le reliquie le hai portate, spero?",
  reward = "Eccellente. Hai dimostrato di comprendere la vera natura del felino e di saperne incarnare l'astuzia, la furtività e la ferocia: quel che serve per prendere la mia forma.$B$BOra ti ritengo $Gdegno:degna; della mia benedizione, giovane $C.",
}
T[98362] = {
  title = "Verso Thunder Bluff",
  desc = "È giunto il momento di separarci ancora una volta, giovane: per mettere in pratica quanto hai imparato devi tornare da chi ti ha mandato da me. Pare che il tuo maestro, Turak Runetotem, abbia trovato in te $Gun allievo meritevole:un'allieva meritevole;. Anch'io vedo il potenziale. Segui i suoi insegnamenti e presto potrai attingere al Great Cat Spirit per assumerne la forma.$B$BOra riprendi la strada da cui sei $Gvenuto:venuta;. Quando sarà il momento, ci rivedremo.",
  obj = "Torna a Thunder Bluff e parla con Turak Runetotem a Elder Rise.",
  reward = "$GBentornato:Bentornata;, $N. Sento che hai incontrato il Great Cat Spirit e hai superato la prova. Tutti i druidi devono affrontarla, anche se cambia di generazione in generazione. Sono fiero che tu l'abbia superata seguendo la saggezza del Great Cat Spirit. È uno spirito antico, tanto letale quanto giocoso, ma sento che ne comprendi già la natura.$B$BOra ti insegnerò ad assumere la forma felina.",
}
T[98372] = {
  title = "Una Fine Sfortunata",
  reward = "Night Watchman che giace morto davanti a te è coperto di tagli e squarci profondi. Si vede bene che a sbranarlo è stata una qualche grossa belva.$B$BIn mano al cadavere noti un'unlit torch. Ti chini e gliela strappi dalle dita irrigidite. Nei tuoi viaggi per Duskwood e oltre potrebbe tornarti utile, per svelare quello che l'oscurità nasconde.",
}
T[98386] = {
  title = "Alther's Mill",
  desc = "Orchi, gnolls, murlocs. Sembra che tutto si metta in mezzo per non farmi finire in tempo questo ponte. E adesso ci dicono pure che la segheria è infestata di tarantole!$B$BSe te la senti di guadagnare qualche moneta in più, potresti andare all'Alther's Mill, qui a est, e ripulirla dai ragni? Finché non posso mandarci gli operai a ritirare i carichi senza rischi, quel posto per me non serve quasi a niente.$B$BAh, e se vedi il vecchio Alther, digli che è in debito con me, perché il pasticcio gliel'ho sistemato io.",
  obj = "Uccidi 12 Greater Tarantulas e distruggi 6 Uova di Tarantula nell'Alther's Mill per Foreman Oslow a Redridge.",
  progress = "Basta il morso di una di queste tarantole per lasciare un operaio a letto con la febbre per una settimana. Preferirei che non succedesse, almeno non finché ci sono io.",
  reward = "La segheria è messa così male? È peggio di quanto pensassi.$B$BNon mi impressiono facilmente, ma il lavoro è già duro così, senza ragni che mi portano via gli operai. Grazie dell'aiuto, $N!",
}
T[98387] = {
  title = "Blocco Blackrock",
  desc = "Una guerra non si combatte senza armi.$B$BGli orchi Blackrock hanno invaso queste terre, ma per quanto siano sfrontati hanno anche loro i loro punti deboli.$B$BVai a sud-est, sotto lo Stonewatch Keep: trova i loro accampamenti e prendi di mira armi e provviste.$B$BVedremo quanto saranno pericolosi senza i loro strumenti di guerra.",
  obj = "Porta 8 Stolen Weapons e 10 Blackrock Supplies a Marshal Marris a Lakeshire.",
  progress = "Tanto, gran parte di quello che troverai sarà roba razziata a Lakeshire. E mi farà piacere sapere che la nostra gente prospererà mentre gli orchi deperiscono.",
  reward = "Ottimo lavoro, $N. Ora gli orchi Blackrock sono tagliati fuori dagli alleati nelle Burning Steppes, e senza provviste adeguate non avranno speranza di mantenere la posizione qui.",
}
T[98389] = {
  title = "Una Luce nelle Tenebre",
  desc = "Saluti, $C. Sì, sono un paladino. Nemmeno la morte può fermare la Luce.$B$BIn questo, quelli come me sono uguali a tutti i Forsaken — abbiamo superato quella che per i vivi è la fine. Eppure perfino alcuni dei nostri ci temono; sospettano che li abbatteremo come se fossero mostri.$B$BIn verità, il nostro rapporto con la non morte è complesso, ma non sono qui per fare del male alla nostra gente. Aiutami a dimostrarlo agli altri. Avventurati fino alla Night's Web Hollow, a nord-ovest, e libera gli sciocchi appena risorti che i ragni hanno intrappolato laggiù.",
  obj = "Libera 6 Webbed Victims a Night's Web Hollow per Aramis Hammerhand a Deathknell.",
  progress = "Hai liberato quelle povere anime sventurate intrappolate nella grotta?",
  reward = "Mi auguro che questo aiuti Executor Arren e tanti altri a vedere la nostra vera natura. Proprio come quando eravamo vivi, esistiamo per servire il nostro popolo — per proteggerlo con i doni che la Luce ci concede.$B$BCol tempo capiranno che per i piani della Dama Oscura valiamo quanto chiunque altro.$B$BChe la Luce sia con te.",
}
T[98391] = {
  title = "La Sorellanza di Elune",
  desc = "Benedizioni a te, $C. Da migliaia di anni la Sorellanza di Elune è un pilastro della società kaldorei.$B$BPrima della Great Sundering, prima della War of the Ancients, durante la Long Vigil, abbiamo guidato e curato il nostro popolo nelle tenebre. È questo il nostro compito, ed è questo che esige l'impareggiabile Madre Luna.$B$BOra ci serve il tuo aiuto in una questione di grande importanza. Sister Aquinne ti attende a Darnassus.",
  obj = "Parla con Sister Aquinne a Darnassus.",
  reward = "Sono lieta che tu sia $Garrivato:arrivata; così in fretta: la Sorellanza ha bisogno del tuo aiuto.",
}
T[98392] = {
  title = "Oscurità nella Radura",
  desc = "Queste cinture... guarda bene il cuoio, $N. Vedi la contaminazione che scorre fra le fibre?$B$BSospetto da dove venga, ma per esserne $Gsicuri:sicure; ci serviranno altre prove.$B$BTorna ai nidi delle arpie, a ovest, ed elimina i loro capi. Se nelle loro collane c'è la stessa oscurità di queste cinture, avremo la risposta.",
  obj = "Raccogli l'Hatescreech's Amulet, il Windmistress Gaedress' Amulet e il Witchmother Arysa's Amulet per Sentinel Arynia Cloudsbreak nell'Oracle Glade.",
  progress = "Hai strappato gli amuleti ai capi delle arpie?",
  reward = "<Arynia esamina gli amuleti.>$B$BVedi quegli immondi vortici verdi dentro le gemme? È proprio la corruzione del fel moss all'opera.$B$BDa Shadowglen e da altri luoghi tra i rami mi sono arrivate notizie simili: questa sostanza sta rivoltando contro di noi il nostro stesso mondo.$B$BInformerò subito i miei superiori.",
}
T[98393] = {
  title = "Il Great Cat Spirit",
  desc = "Sembra che tu sia $Gpronto:pronta; per il prossimo passo del tuo cammino, giovane $C. Dendrite Starblaze ti ha mandato a chiamare e ti chiede di raggiungerlo ancora una volta a Moonglade.$B$BHai già imparato a invocare la magia che ti conduce a Moonglade, perciò potrai metterti in viaggio subito, se lo desideri. Ti consiglierei di non tardare, se vuoi proseguire il tuo addestramento druidico.",
  obj = "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.",
  reward = "E così si continua, Father Cenarius.$B$B<Dendrite compie un gesto rapido e impercettibile nell'aria sopra di sé. Una lieve aura di potere lo avvolge.>$B$B$GBen ritrovato:Ben ritrovata;, $N. È giunto il momento di apprendere un nuovo modo di guardare la natura: quello del felino. Ti mostrerò la via per comprendere questo aspetto della vita druidica ma, proprio come è stato per l'orso, spetta a te far tuo l'insegnamento e diffonderlo.",
}
T[98394] = {
  title = "Il Great Cat Spirit",
  desc = "Nella parte meridionale di Moonglade, su una collina che domina il ponte, vive un essere saggio e astuto: lo chiamiamo Great Cat Spirit.$B$BCome il Great Bear Spirit, anche questo spirito ha fatto da maestro e da guida ai druidi che desiderano prendere la forma felina. Prima o poi ogni druido va in cerca della sua saggezza, e se vuoi prendere la forma di un felino, la cercherai anche tu.$B$BVa' a incontrare il Great Cat Spirit e scopri cosa ha da insegnarti.",
  obj = "Cerca il Great Cat Spirit nella parte meridionale di Moonglade e scopri cosa ha da insegnarti sulla natura del felino.",
  reward = "Sei $Gvenuto:venuta; a imparare come si attinge al mio spirito, vedo. Bene. Vediamo allora se sei $Gpronto:pronta; a prendere la mia forma.",
}
T[98396] = {
  title = "Il Great Cat Spirit",
  desc = "Per attingere al mio spirito non ti basteranno poche parole. Se vuoi comprendere e rispettare la mia forma, devi dimostrare di saper incarnare l'astuzia, la furtività e, se dovessi trovarti $Gmesso:messa; alle strette, la ferocia.$B$BAppena a est di qui, nelle Barrow Dens, ci sono tre reliquie del mio favore che devi recuperare. Le sorvegliano potenti spiriti infuriati, pronti ad attaccarti appena ti vedono. All'ingresso c'è una statua: ti benedirà e ti renderà $Gfurtivo:furtiva; per un po', così potrai superarli.$B$BRiportami queste reliquie, e vedremo se sei $Gpronto:pronta; a prendere la mia forma.",
  obj = "Recupera la Relic of the Fang, la Relic of the Claw e la Relic of the Silent Shadow dalla Tana dei Tumuli di Stormrage, e riportale al Great Cat Spirit.",
  progress = "Ah, sei $Gtornato:tornata;. Le reliquie le hai portate, spero?",
  reward = "Eccellente. Hai dimostrato di comprendere la vera natura del felino e di saperne incarnare l'astuzia, la furtività e la ferocia: quel che serve per prendere la mia forma.$B$BOra ti ritengo $Gdegno:degna; della mia benedizione, giovane $C.",
}
T[98397] = {
  title = "A Darnassus",
  desc = "È giunto il momento di separarci ancora una volta, giovane: per mettere in pratica ciò che hai imparato devi tornare da chi ti ha mandato qui. A quanto pare il tuo maestro, Mathrengyl Bearwalker, ha trovato in te $Gun allievo degno:un'allieva degna;. Anch'io credo di vederne $Guno:una;. Segui i suoi insegnamenti e presto potrai invocare il Great Cat Spirit per assumerne la forma.$B$BTorna da dove sei $Gvenuto:venuta;. Quando sarà il momento, ci incontreremo di nuovo.",
  obj = "Torna a Darnassus e parla con Mathrengyl Bearwalker in Cenarion Enclave.",
  reward = "$GBentornato:Bentornata;, $N. Percepisco che hai incontrato il Great Cat Spirit e hai superato la prova. Ogni druido deve superarne una imposta da questo spirito, anche se non è la stessa per ogni generazione. Sono fiero che tu ce l'abbia fatta e che abbia dato ascolto alla saggezza del Great Cat Spirit. È antico, tanto letale quanto giocoso, ma sento che ne comprendi già la natura.$B$BOra ti insegnerò ad assumere la forma felina.",
}
T[98398] = {
  title = "L'Oracle Tree",
  desc = "Sono colpita da quanto hai fatto qui in così poco tempo, $N. Se solo potessi chiederti di restare ad aiutarmi nel mio incarico... ma in cuor mio so che ti attendono imprese più grandi.$B$BHo notato che l'Oracle Tree ha appena perso un pezzo di corteccia. Di sicuro c'è un compito che vuole veder portato a termine. Dovresti parlargli.",
  obj = "Trova l'Oracle Tree Bark qui vicino per ricevere il suo messaggio.",
  reward = "Mentre esamini la corteccia caduta, ti entra nella mente una voce. Calma e rassicurante, ti avvolge come una brezza leggera tra le foglie.",
}
T[98403] = {
  title = "Odio Distorto",
  desc = "Lord Melenas non ha agito da solo; obbediva agli ordini di un altro. Colui che cerchi è Xethorr the Wicked. A quanto pare, ha corrotto i ragni che abitano Teldrassil, perché intende usarne il veleno per qualche piano turpe.$B$BSi è stabilito nel cuore della foresta, a nord-ovest di qui, in quella che chiamano la Cleft. Sii prudente e fatti accompagnare da qualche alleato, perché Xethorr non è un avversario da prendere alla leggera.$B$BStermina la sua progenie, e portami qualsiasi cosa possa dirci di più sulle trame del satiro in questi luoghi.",
  obj = "Uccidi 8 Befouled Webwoods e porta il Mature Fel Moss di Xethorr the Wicked a Tallonkai Swiftroot a Dolanaar.",
  progress = "<Tallonkai abbassa la voce.>$B$BXethorr è ancora a piede libero?",
  reward = "Avrei dovuto immaginare che fosse questo a corrompere i ragni della nostra terra.$B$BHo sentito sussurrare che questa sostanza sia l'origine di gran parte della corruzione che ci affligge. Non è l'originale, ma è un campione più vecchio e potrebbe fornirci più informazioni di quante ne abbiamo ottenute finora.$B$BDi norma ti chiederei di spedirlo a Darnassus perché venga studiato più a fondo. Tuttavia, per il momento è meglio non farne parola, o Dolanaar non ritroverà mai il suo buon nome.$B$BConfido che anche tu farai lo stesso.",
}
T[98404] = {
  title = "Il Grande Spirito Felino del Vento",
  desc = "Per attingere al mio spirito dovrai affrontare una prova. Se vuoi comprendere e rispettare la mia forma, devi dimostrare di saper incarnare l'astuzia, la furtività e, se dovessi essere $Gmesso:messa; alle strette, la ferocia.$B$BPoco a est di qui, nelle Barrow Dens, ci sono tre reliquie che devi recuperare. Le sorvegliano spiriti potenti e infuriati, pronti ad attaccarti appena ti vedono. All'ingresso c'è una statua che ti benedirà e per un po' ti renderà $Gfurtivo:furtiva;: così potrai superarli.$B$BRiportami le reliquie e supererai la prova druidica di queste terre.",
  obj = "Recupera la Relic of the Fang, la Relic of the Claw e la Relic of the Silent Shadow dalla Stormrage Barrow Den e riportale all'Avatar of Saeyleenan.",
  progress = "Ah, sei $Gtornato:tornata;. Le reliquie le hai portate, spero?",
  reward = "Eccellente. Hai dimostrato di comprendere la vera natura del felino: sai incarnare l'astuzia, la furtività e la ferocia che servono per assumere la mia forma.$B$BOra ti ritengo $Gdegno:degna; della mia benedizione, giovane $C.",
}
T[98405] = {
  title = "Il Great Cat Spirit",
  desc = "Su una collina nella parte meridionale di Moonglade, da cui si domina il ponte, vive un essere saggio e astuto: noi lo chiamiamo Great Cat Spirit.$B$BCome il Great Bear Spirit, anche questo spirito ha fatto da maestro e da guida ai druidi che vogliono assumere la forma felina. Tutti i druidi, prima o poi, vanno a cercare la sua saggezza, e se vuoi assumere la forma di un gatto ci andrai anche tu.$B$BVa' a trovare il Great Cat Spirit e impara quello che ti insegnerà.",
  obj = "Cerca il Great Cat Spirit nella parte meridionale di Moonglade e impara ciò che ha da dirti sulla natura del gatto.",
  reward = "Vedo che sei $Gvenuto:venuta; per imparare ad attingere al mio spirito. Bene. Vediamo se sei $Gpronto:pronta; ad assumere la mia forma.",
}
T[98407] = {
  title = "Dimostrazione di Forza",
  desc = "Se gli gnoll si stanno facendo così audaci da accamparsi tanto vicino agli umani, chissà fin dove potrebbero spingersi. Dobbiamo scoraggiarli.$B$BQuelle bestie sono tutt'altro che organizzate, ma sembrano rispettare la forza sopra ogni cosa. Se riusciamo a uccidere i peggiori, magari prendendo qualche trofeo, potremo ricordare a questi gnoll perché dovrebbero restarsene al loro posto, sulle colline.$B$BSe vedi qualcuno dei loro flagellatori, portami i collari. Dovrebbe bastare a rimettergli addosso la paura dell'Alleanza.",
  obj = "Raccogli 5 Spiked Collars dai Redridge Thrashers per Deputy Feldon vicino a Lakeshire.",
  progress = "Non si può valutare a fondo la minaccia degli gnoll senza affrontare i peggiori della loro specie. Abbatti quei flagellatori!",
  reward = "Hai proprio le braccia piene.$B$BQuesto non risolve il nostro problema qui fuori, ma almeno posso stare tranquillo: li abbiamo dissuasi dallo spingersi oltre. Ottimo lavoro, $N.",
}
T[98417] = {
  title = "Pista Vendicativa",
  desc = "La tragedia si è abbattuta sui nostri villaggi proprio quando i nostri destini ci rendevano più vulnerabili. I satiri hanno profanato i nostri templi, hanno macchiato i rami sacri con il loro tocco empio e hanno massacrato gli innocenti senza pietà.$B$BL'ira ha consumato Kurothel. I druidi danno battaglia ai satiri, e lui li ha seguiti.$B$BIl nostro legame resiste: sento mio marito a ovest, in questi boschi. Ti prego, torna a darmi notizie della sua sorte.",
  obj = "Maseara Autumnmoon vuole che tu cerchi a ovest di Forest Song, fra i demoni di Satyrnaar. Al tuo ritorno, riferisci qualsiasi segno di suo marito Kurothel.",
  progress = "Cos'hai trovato fra le colline della nostra foresta?",
  reward = "Oh no... queste parole non mi danno conforto. A quanto pare, Kurothel non vive soltanto nella natura: notte dopo notte, vive sempre più come una bestia selvaggia.$B$BTemo che i sussurri dicano il vero.",
}
T[98418] = {
  title = "Furia Condivisa",
  desc = "Kurothel ha parlato di presunti uomini-lupo avvistati in giro: sono quelli del branco, e ora si aggirano per la nostra foresta sempre più numerosi. L'ultima volta che abbiamo parlato, i druidi cercavano di comunicare con quelli dal cuore di bestia capaci di dominare con misura gli istinti animali.$B$BNei suoi scritti, però, si legge di una lotta più oscura. Se possiamo fare qualcosa per rivedere LUI, sedare la minaccia demoniaca che lo spinge verso questa trasformazione ardente aiuterà di certo la sua anima tormentata.$B$BUccidi gli Xavian, $N.",
  obj = "Uccidi 5 Xavian Rogues, 5 Felsworn, 5 Traditori e 5 Hellcallers.$BPoi torna da Maseara Autumnmoon a Forest Song.",
  reward = "Ho sentito sgorgare... la luce di Elune dentro di me e tutt'intorno. Sento che Kurothel ti ha visto combattere in questa guerra che infuria nella nostra terra e nei nostri cuori.$B$BSpero che col tempo, con i loro sforzi, le nostre Sentinelle e i nostri druidi smarriti eliminino una volta per tutte la minaccia demoniaca. Forse allora, e solo allora, la sete selvaggia di vendetta smetterà di ardere nell'eredità della nostra stirpe.$B$BGrazie, $N. Sei $Gun alleato:un'alleata; della foresta e $Gun amico:un'amica; dei Kaldorei.",
}
T[98423] = {
  title = "Il Treaty of Understanding",
  desc = "Nel caveau trovi una tavoletta con i termini di un trattato di pace fra i clan nanici Bronzebeard e Wildhammer. Sembra risalire a subito dopo la War of the Three Hammers, e con ogni probabilità è un pezzo importante della storia dei nani. Il re di Ironforge sarebbe di certo interessato a questo manufatto.",
  obj = "Consegna il Treaty of Understanding a Magni Bronzebeard a Ironforge.",
  progress = "Che cosa hai portato dalle profondità, $C.",
  reward = "Ah sì, Madoran, mio antenato, è stato il primo re Bronzebeard di Ironforge dopo la grande guerra civile fra i clan Wildhammer, Bronzebeard e Dark Iron. Questo trattato è stato scritto dopo che i Bronzebeards hanno conquistato la montagna, per sancire la fine delle ostilità e le condizioni della pace.$B$BCome vedi, i Wildhammer e i Bronzebeards l'hanno firmato... i Dark Irons no.$B$BGrazie di averlo recuperato e di avermelo portato, $C.",
}
T[98424] = {
  title = "Gli Appunti di Fizsprocket",
  desc = "Alcuni fogli particolarmente consunti sono tenuti a parte, piegati nel taschino interno della giacca di Fizsprocket.$B$BSembrano contenere informazioni importanti, da usare contro la Venture Co. e le sue attività nella regione. Sarebbe prudente cercarne altri prima di tornare da Morin Cloudstalker.",
  obj = "Raccogli il resto delle pagine di Supervisor Fizsprocket in The Venture Co. Mine e portale a Morin Cloudstalker vicino a Bloodhoof Village.",
  progress = "Che cosa mi porti, $C?",
  reward = "Ah, sono informazioni davvero preziose. Ti ringrazio per l'impegno.$B$B<Morin esamina gli appunti.>$B$BLa nostra prossima mossa sembra chiara.",
}
T[98427] = {
  title = "Stop alle Operazioni",
  desc = "La trinciatrice di cui parla una delle pagine — ne ho già viste nei miei viaggi. Possono decimare una foresta molto più in fretta di quanto farebbero mani e asce.$B$BIntere radure — dimore dei figli della Madre Terra da millenni — cancellate in pochi giorni.$B$BNon permetteremo che accada a casa nostra, a un tiro di schioppo da dove i nostri piccoli muovono i primi passi.$B$B$N, devo chiederti di radunare altri compagni, tornare nella miniera a nord-est e fare in modo che la trinciatrice non abbatta più un solo albero.",
  obj = "Porta la Clearcutter Key a Morin Cloudstalker fuori da Bloodhoof Village.",
  progress = "Hai fermato la trinciatrice, $N?",
  reward = "Oggi tutto Bloodhoof Village è in debito con te. Che la grazia della Madre Terra ti accompagni sempre.",
}
T[98430] = {
  title = "I Longwalkers",
  desc = "Salute, $C. Cosa ti porta nel cuore di un luogo così oscuro e violento?$B$BHigh Chieftain Cairne Bloodhoof mi ha mandato a tentare di comunicare con gli gnolls che si sono stabiliti qui. Il resto della mia missione deve restare segreto, come tutto ciò che riguarda i Longwalkers, gli esploratori fidati del nostro capotribù.$B$BTi basta sapere che alla nostra diplomazia hanno risposto con la violenza, e se non mi aiuti a fuggire temo che stanotte potrei finire in pasto agli gnolls.$B$BSei all'altezza del compito?",
  obj = "Aiuta Perith Stormhoof a fuggire da Palemane Rock e riferisci a Cairne Bloodhoof a Thunder Bluff che è al sicuro.",
  reward = "Sono sollevato di sapere che il Longwalker Stormhoof sta bene. È il mio esploratore più fidato, e la sua missione è della massima importanza.$B$BHai messo a rischio la tua vita pur di salvare la sua: ti prego, accetta i miei ringraziamenti e la mia ospitalità. Hai reso al nostro popolo un servizio più grande di quanto tu sappia.$B$BFinché sei qui, ti invito a esplorare la nostra grande città. È un luogo sicuro, e sulle sue alture troverai molti che potranno aiutarti nei tuoi viaggi.$B$BIsh-ne-alo por-ah.",
}
T[98435] = {
  title = "Thunderhorn's Report",
  desc = "I nostri anziani di Thunder Bluff devono sapere quali progressi abbiamo fatto qui grazie al tuo aiuto.$B$BTi prego, porta questo ad Arch Druid Hamuul Runetotem a Thunder Bluff. Lo troverai sull'Elder Rise, nella parte orientale della città. Per arrivarci dovrai prendere gli ascensori fino al centro e poi attraversare i ponti.",
  obj = "Porta il Thunderhorn's Report ad Arch Druid Hamuul Runetotem a Thunder Bluff.",
  reward = "Ah, non c'è da stupirsi che scorra tanta gioia nei ruscelli di Mulgore. Oggi hai reso un grande servigio. I pozzi danno molto non solo al nostro popolo, ma anche agli animali su cui contiamo per il cibo, le vesti e la compagnia.$B$BSono lieto e onorato di esaudire la richiesta di Mull. Ti prego, accetta questo pegno di gratitudine.",
}
T[98447] = {
  title = "La Famiglia Valor",
  desc = "Anche se hai abbattuto i fantasmi della famiglia Valor, le segnalazioni di attacchi non sono cessate. Era una buona scommessa, ma forse, dopotutto, non abbiamo chiuso le loro questioni in sospeso.$B$BDalle mie ricerche sembra che la famiglia sia scomparsa tutta nello stesso momento. Qualunque trauma abbia incatenato i loro spiriti a questo mondo, deve essere successo in un istante solo.$B$BL'unico indizio che abbiamo è il posto dove hai trovato il libro. Torna a Raven Hill e guarda cosa riesci a scoprire. Forse, se porti le loro armi, scatterà qualcosa.",
  obj = "Trova la causa dei fantasmi della famiglia Valor a Raven Hill per Sirra Von'Indi a Darkshire.",
}
T[98459] = {
  title = "Una Mancanza di Virtù",
  desc = "Bart Tidewater è un taccagno buono a nulla, te lo dico io!$B$BSi fa chiamare \"Capitano della Maiden's Virtue\". Quella nave ha navigato quanto un sasso a Tanaris! Altro che capitano: è un attore che ha vinto abbastanza mani di poker da comprarsi la Virtue!$B$BSe mai passi da Menethil Harbor, laggiù nelle Wetlands, dagli questo e digli che glielo manda il vecchio Mezzopesce.$B$BA proposito, da qui parte una barca che può portarti dritto al porto. È la seconda fermata!$B$BE bara a poker!",
  obj = "Consegna il Tom's Gift a Bart Tidewater a Menethil Harbor, nelle Wetlands.",
  progress = "Datevi da fare! Si salpa al mio ordine!$B$BOh? Cos'hai lì, $Gviaggiatore:viaggiatrice;?",
  reward = "<Bart scarta il regalo.>$B$BMa quel buono a nulla, figlio di un —$B$BTi ha almeno detto che quello che bara a poker è LUI?! Sono riuscito a vincere abbastanza da comprarmi la Maiden's Virtue solo dopo che l'abbiamo cacciato dal nostro giro di poker!$B$BGiuro, la prossima volta che vedo quel totale spreco d'acqua di mare —$B$BScusa, scusa. Non dovrei prendermela con il messaggero. A nome dell'equipaggio della Maiden's Virtue — la nave migliore del Great Sea — $Gbenvenuto:benvenuta; a Menethil Harbor!",
}
T[98461] = {
  title = "Amore Non Corrisposto",
  desc = "Se stai per lasciare Auberdine, mi farebbe comodo il tuo aiuto!$B$BIl mio caro amico Tarrel e io eravamo compagni di scuola. Oh, quando si trattava di scavi era un vero asso! Dopo il diploma le nostre strade si sono divise — lui nelle Wetlands, io qui a Darkshore.$B$B<Hollee sospira, poi aggrotta leggermente la fronte.>$B$BScusa, e sua moglie... Merrin.$B$BNon importa. Se vai nelle Wetlands, potresti assicurarti che stia bene? E magari dargli questo? Dovrebbe essere dalle parti di Menethil Harbor. C'è una nave che ci va dritta.",
  obj = "Consegna l'Hollee's Note a Tarrel Rockweaver, vicino a Menethil Harbor, in Wetlands.",
  progress = "Di che si tratta?",
  reward = "<Tarrel legge il biglietto.>$B$BOh... oh, cielo. Povera Hollee.$B$BHa sempre avuto un debole per me. E, a dire il vero, c'è stato un tempo in cui l'avrei ricambiata. Ma sono sposato. Felicemente sposato!$B$BCredo che la cosa migliore sia non rispondere. Non so come dirle di no senza ferirla, e qui ho problemi ben più urgenti di cui preoccuparmi! Mia moglie è scomparsa!",
}
T[98463] = {
  title = "Sulla Bocca di Tutti",
  desc = "Senti, mi fa piacere averti nel mio bar, ed è proprio per questo che te lo dico.$B$BLa vera festa? È alla Salty Sailor Tavern a Booty Bay. Sì, nella Stranglethorn Vale — proprio quella Booty Bay.$B$BNon guardarmi così. Lo so che la gestiscono i goblin. I baristi parlano, e i clienti dei bar parlano MOLTO. Dico solo che, se vuoi vedere gente che si scatena davvero, devi fare un salto là.$B$BCi penserà Nixxrax Fillamug a tenerti il boccale sempre pieno, non preoccuparti.",
  obj = "Visita Nixxrax Fillamug alla Salty Sailor Tavern a Booty Bay, a Stranglethorn.",
  reward = "Ho quello che ti serve, $Gamico:amica;! Fermati un po', spendi parte dell'oro che ti appesantisce le tasche e divertiti. $GBenvenuto:Benvenuta; alla Salty Sailor Tavern!",
}
T[98471] = {
  title = "Message from the Supreme Magister",
  desc = "Saluti, $N.$B$BHo un incarico per te, e ha la massima priorità. Raggiungimi sulle montagne che chiamano Alterac, a nordovest del villaggio che chiamano Strahnbrad. Ti aspetterò sulla rupe che dà sulla valle di Uplands.$B$BVieni $Gsolo:sola; e non dirlo a nessuno.",
  obj = "Incontra Elaadrin Evengale sulle rupi che si affacciano su The Uplands, nelle Alterac Mountains.",
}
T[98512] = {
  title = "Assassini Al'Aketh",
  desc = "Ehi, tu, $Gstraniero:straniera;. Abbassati e non fare rumore. Non siamo soli, qui.$B$BEro di pattuglia vicino al confine e ho visto diversi Al'Aketh aggirarsi furtivi intorno alla casa poco più su, sulla collina a nord. Non so cosa ci facciano qui, ma di buono non può essere niente.$B$BSe vuoi renderti utile, entra e falli fuori. Io resto qui a guardarti le spalle.",
  obj = "Uccidi 10 Assassini Al'Aketh negli Shen'dar Highlands.",
  progress = "Chissà cosa cercano?",
  reward = "Sono contento che tu sia $Gtornato:tornata;. Quegli Al'Aketh avevano tutta l'aria di assassini a sangue freddo.$B$BGrazie dell'aiuto: quando sarò di nuovo a Valanaar lo citerò nel rapporto.",
}
T[98517] = {
  title = "Il Richiamo del Fuoco",
  desc = "Saluti, $Ggiovane:giovane; Skyborne. Gli spiriti mi hanno parlato di te: dicono che sei $Gpronto:pronta; a rispondere al richiamo del fuoco. Non sarò io, però, ad avviarti su quel Cammino. Torna a casa, nel piano elementale, e cerca lì i tuoi mentori: saranno loro a dirti cosa va fatto.",
  obj = "Presentati a Sessaria Skystride o ad Aarnor Galestrike su Zephras Isle per continuare il tuo addestramento da $GSciamano:Sciamana;.$B$BPuoi tornare a Zephras con la nave volante che attracca a Mulgore, presso lo Skywatcher Plateau, a nordovest di Thunder Bluff.",
}
T[98545] = {
  title = "La Lettera di Leonid",
  desc = "Visto che sei qui, vorrei che consegnassi questa lettera a un mio vecchio amico a Undercity. La porterei io stesso, ma con la Dama Oscura ho un passato piuttosto movimentato, ed è meglio che se ne occupi qualcuno di esterno e neutrale.$B$BCerca un goblin di nome Glix Xizzix nella zona del Trade Quarter di Undercity. Sono sicuro che sarà felice di ricompensarti per il disturbo.$B$B<Leonid si lascia sfuggire una risatina sommessa mentre ti porge la lettera.>",
  obj = "Consegna la Lettera Sigillata a Glix Xizzix, a Undercity.",
  progress = "Come? Dici che ti manda Leonid? Accidenti, non vedo quel vecchio soldato burbero da quando Naxxramas ci scatenava l'inferno sulla testa.",
  reward = "Grazie per avermela portata, $Gamico:amica;.$B$BAspetta... ha detto che ti avrei dato una mancia? Io non ho mai detto di sì! $B$BE va bene. Scegli quello che vuoi fra queste cianfrusaglie: sono tutti oggetti smarriti. Ti stupiresti di quanti Forsaken si dimenticano la roba in giro dopo essersi fatti tagliare i capelli. Ci sarebbe da fare una battuta sul fatto che non hanno cervello, ma sospetto che in molti casi sia proprio vero.",
}
T[98574] = {
  title = "Hallowed Memorandum",
  desc = "Mentre mi davi una mano, mi hanno consegnato questo promemoria da passare a te. Leggilo con calma quando puoi. Secondo me viene dall'istruttore dei sacerdoti, Branstock. Dagli un'occhiata e poi, appena hai un momento, vai a cercarlo dentro Anvilmar.",
  obj = "Leggi l'Hallowed Memorandum e parla con Branstock Khalder ad Anvilmar.",
  progress = "Ah, $Gun altro gnomo:un'altra gnoma; che viene a conoscere la Luce! Scoprirai che, per approfondire il legame con la Luce, servono curiosità e intelligenza, qualità che molti gnomi hanno in abbondanza. La via della Luce non è una disciplina tecnica: è un enigma, e ti offre sia lezioni di vita che benedizioni concrete.",
  reward = "Con il tempo e la pratica scoprirai nuovi aspetti della Luce. In un certo senso, si tratta di mettere d'accordo ciò che pensi e ciò che provi. Man mano che il legame con la Luce si farà più profondo, potrai tornare da me a raccontarmi quello che hai imparato. Sarò felice di insegnarti ad attingere a quella forza per guarire, o per punire i malvagi. In cambio di una piccola offerta, s'intende!",
}
T[98575] = {
  title = "Tainted Tablet",
  desc = "Ah, mentre non c'eri è arrivata una tavoletta per te, $N.$B$BDi solito, se posso, con gli stregoni preferisco non averci a che fare, ma credo che dovresti leggerla quando hai un momento. Se non sbaglio te la manda Nartok, il tuo nuovo istruttore: vuole parlarti quando sarai $Gpronto:pronta;.",
  obj = "Leggi la Tainted Tablet e parla con Nartok dentro The Den, in Valley of Trials.",
  progress = "Ah, hai ricevuto il mio messaggio. Eccellente. Fra noi orchi e le entità del Nether la storia è lunga e turbolenta, ma adesso la strada ce la apriamo da soli, padroni del nostro destino. Anche tu puoi conquistare il potere di plasmare il futuro della tua gente: dove i nostri capi vacillano, noi siamo pronti ad andare avanti e a prenderci il posto che ci spetta. Fra i troll avrai un ruolo di rilievo.",
  reward = "Hai appena intravisto il potere che può essere tuo. I deboli e gli stolti fra noi hanno paura della via che percorriamo, ma con audacia e astuzia il nostro destino possiamo deciderlo noi.$B$BCustodisci con cura i tuoi poteri: chi ha paura si scaglia contro ciò che non capisce.$B$BOra sei $Guno:una; di noi. Se devi imparare degli incantesimi, torna da me.",
}
T[98576] = {
  title = "Glyphic Parchment",
  desc = "Ah, mentre eri via è arrivata una cartapecora per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, te la manda l'istruttrice dei maghi Mai'ah: vuole parlarti quando sarai $Gpronto:pronta;.",
  obj = "Leggi la Glyphic Parchment e parla con Mai'ah vicino all'ingresso di The Den in Valley of Trials.",
  progress = "Sei $Gvenuto:venuta; da Mai'ah $Gpronto:pronta; a imparare. Questo è bene. Hai il potere di toccare i fili del cosmo, ma anche la saggezza di sapere che ti serve una guida. Posso insegnarti i primi passi per usarlo.",
  reward = "La magia che ti scorre dentro è il potere più grande dell'universo, ma devi avere pazienza. Aspetta il momento perfetto per colpire, scegli la risposta giusta al problema che hai davanti. Se sei intelligente e osservi con attenzione, non c'è niente che non puoi fare. Quando pensi di essere $Gpronto:pronta; per l'addestramento, torna da Mai'ah: lei ti insegna quello che sei $Gpronto:pronta; a imparare, nessun problema.",
}
T[98581] = {
  title = "Archaic Rune",
  desc = "Mentre mi davi una mano, mi hanno consegnato questa runa da passare a te. Leggila con calma quando puoi. A giudicare dallo stile Wildhammer di queste iscrizioni, direi che viene da Teo Hammerstorm, l'istruttore di chi è $C. Dalle un'occhiata e poi, appena hai un momento, vai a cercarlo dentro Anvilmar.",
  obj = "Leggi l'Archaic Rune e parla con Teo Hammerstorm ad Anvilmar.",
  progress = "Ah, sei $Griuscito:riuscita; a leggere la runa? È intrisa del potere degli elementi e scritta in uno dei nostri alfabeti più antichi. Vuol dire che hai la stoffa $Gdi un:di una; $C.",
  reward = "Le arti sciamaniche le ha custodite per anni il clan Wildhammer, e ora sono passate anche nelle mani dei nani Bronzebeard. Sono qui per aiutare a diffondere questi insegnamenti e per guidare i nuovi sciamani che imparano le vie degli elementi. Vieni da me se hai bisogno di addestrarti ancora negli incantesimi di terra, aria, fuoco e acqua.",
}
T[98601] = {
  title = "Un Cammino Difficile",
  desc = "Mentre eri via a occuparti dello Scourge senza mente, è arrivata per te questa pergamena. Puzza di luce, quindi immagino sia importante per $Gun:una; $C come te.$B$BLeggila prima di ripartire. Però, ti prego — fallo lontano da me. I paladini mi mettono parecchio a disagio.",
  obj = "Leggi la Consecrated Scroll e parla con Aramis Hammerhand nella chiesa di Deathknell.",
  progress = "Dal dolore nasce la determinazione.",
  reward = "Ora il tuo addestramento può cominciare sul serio, $C. Vedo in te grandi potenzialità, ma bada di non voltare le spalle alla luce, nemmeno per un istante. Accogli la sofferenza che ti causerà. Quel dolore è un crogiolo, e ne uscirai più forte di quanto tu sia mai $Gstato:stata; nella tua vita precedente.",
}
T[98731] = {
  title = "Benedizioni del Great Cat Spirit",
  desc = "Hai ricevuto la mia benedizione: ora torna da Dendrite, che ti darà altre istruzioni. Spero che un giorno ci rivedremo.$B$BChe le ombre ti nascondano per sempre e che i tuoi nemici cadano facilmente preda dei tuoi artigli, giovane.",
  obj = "Parla con Dendrite.",
  reward = "<Mentre ti avvicini, Dendrite traccia un altro gesto invisibile nell'aria sopra di sé. Lo avvolge un'altra aura di potere, e accenna un sorriso.>$B$BSento in te l'astuzia e la ferocia del felino, che non avevi quando ti ho mandato a incontrare il Great Cat Spirit. Te lo leggo negli occhi: ora comprendi la furtività e la velocità che servono per adottare questa natura.$B$BOra puoi imparare a concentrare la tua astuzia, ad adottare la vera natura del felino e a invocarne lo spirito.",
}
T[98738] = {
  title = "Benedizioni del Grande Spirito Felino del Vento",
  desc = "Hai ricevuto la mia benedizione: ora torna da Dendrite, che ti darà altre istruzioni.$B$BPer il momento, purtroppo, ho poco altro da insegnarti. Spero davvero che un giorno tu torni a trovarmi a Zephras: sento del potenziale in te, giovane shen'dorei.$B$BChe le ombre ti nascondano per sempre, che i tuoi nemici cadano facili prede dei tuoi artigli e che i venti guidino i tuoi passi.",
  obj = "Parla con Dendrite.",
  reward = "<Mentre ti avvicini, Dendrite traccia un altro gesto invisibile nell'aria sopra di sé. Lo avvolge un'altra aura di potere, e sul suo viso compare un sorriso appena accennato.>$B$BPercepisco in te l'astuzia e la ferocia del felino, che non c'erano quando ti ho mandato a incontrare il Great Cat Spirit. Nei tuoi occhi leggo che ora comprendi la furtività e la velocità che servono per assumere questa natura.$B$BAdesso puoi imparare a concentrare l'astuzia, ad assumere la vera natura del felino e a invocarne lo spirito.",
}
T[98739] = {
  title = "Benedizioni del Great Cat Spirit",
  desc = "Hai ricevuto la mia benedizione: ora torna da Dendrite, che ti darà altre istruzioni. Spero che un giorno ci rivedremo.$B$BChe le ombre ti nascondano per sempre e che i tuoi nemici cadano facilmente preda dei tuoi artigli, giovane.",
  obj = "Parla con Dendrite.",
  reward = "<Mentre ti avvicini, Dendrite traccia un altro gesto invisibile nell'aria sopra di sé. Lo avvolge un'altra aura di potere, e accenna un sorriso.>$B$BSento in te l'astuzia e la ferocia del felino, che non avevi quando ti ho mandato a incontrare il Great Cat Spirit. Te lo leggo negli occhi: ora comprendi la furtività e la velocità che servono per adottare questa natura.$B$BOra puoi imparare a concentrare la tua astuzia, ad adottare la vera natura del felino e a invocarne lo spirito.",
}
T[98815] = {
  title = "Pelli degli Altipiani",
  desc = "Negli Altipiani ci sono rovine di qualche tipo, segreti che adesso una spedizione sta esplorando. Una cosa la so: hanno una fauna tutta loro, e in quella palude di montagna ci sono bestie in agguato. Che ne dici di andarci a fare una puntata con qualche amico ben equipaggiato? Poi ci scambiamo qualcosa.$B$BChe si nascondano pure, io voglio la loro pelle! Portami le pelli di quattro Thicket Raptors e ti preparerò uno scambio che ne varrà la pena.",
  obj = "Riporta 4 Thicket Raptor Hides a James Halloran, il conciatore, a Menethil Harbor.",
  progress = "$GBentornato:Bentornata;, $C. Ti serve un po' d'olio per il cuoio dell'attrezzatura?",
  reward = "Sono fra le pelli più notevoli che abbia mai avuto fra le mani: ne ricaverò dettagli spettacolari per tutte le mie rifiniture pregiate. Grazie, $N.$B$BProvali e prenditi quello che preferisci in cambio.",
}
T[98823] = {
  title = "Eco Earthen",
  desc = "Davvero affascinante, questo oggetto.$B$BCi sono segni che sia molto più di un semplice intaglio o di una scultura.$B$BAi nostri anziani potrebbe interessare osservare questo manufatto, ma quando si tratta delle nostre rovine sepolte e delle terre dimenticate nessuno è più saggio dell'Earthen Ring. Rivolgiti direttamente a Muln Earthfury, come si addice alla gravità di ciò che porti.$B$BLo troverai con altri anziani del consiglio dell'Earthen Ring allo Skywatcher Plateau, nel nord-ovest di Mulgore.",
  obj = "Porta la Titan Relic a Muln Earthfury allo Skywatcher Plateau, nel nord-ovest di Mulgore.",
  progress = "Vieni. Cerca e ricevi.",
  reward = "Ah... questo frammento vibra della voce stessa del mondo. La luce che ha dentro è un ricordo del passato, e brilla di lampi di storia. Questa macchina dei titani deve aver atteso per intere vite che qualcuno la comprendesse.$B$BHai agito con saggezza a portarla da noi. The Earthen Ring la custodirà, la studierà e, quando saremo in grado di riceverne i messaggi, condividerà le verità che racchiude.$B$BOggi onori gli elementi, viandante.",
}
T[98824] = {
  title = "Prisma Preistorico",
  desc = "Ha sulle facce iscrizioni simili a quelle dei titani: il posto giusto per portarlo non può che essere l'Hall of Explorers di Ironforge.$B$BMi piace pensare che per questo sarai $Gricordato:ricordata; nella storia, nel catalogo — \"Recuperato da $N! Autenticato da Prospector Whelgar...\" Ah, mi sto lasciando prendere la mano.$B$BTi riceverà High Explorer Magellas, e visto il pregio di quello che porti, se lo donerai al museo saprà di certo ricompensarti con grande generosità.$B$BBella scoperta!",
  obj = "Porta la Titan Relic a High Explorer Magellas in Hall of Explorers di Ironforge.",
  progress = "Guarda pure la nostra galleria, ma per favore non toccare i manufatti, a meno che non sia quello che sei $Gvenuto:venuta; a donare alla biblioteca.",
  reward = "Cos'hai lì...$B$BWow! Guarda che meraviglia! La luce ci danza dentro come non vedevo dal mio primo scavo nella vecchia Uldaman. E i segni dei custodi non lasciano dubbi.$B$BRiportandolo a casa hai reso un gran servizio alla Lega. Una scoperta così spinge più in là i confini stessi della sapienza del mondo.$B$BRegistreremo senz'altro i dettagli del tuo contributo! Davvero un ottimo lavoro, $Gavventuriero:avventuriera;.",
}
T[98887] = {
  title = "Scontro alle Darkspear Islands",
  desc = "La Theramore Expeditionary Force è tenace e continua a mandare rinforzi per consolidare la sua posizione sulle Darkspear Islands.$B$BVai, mostra loro la potenza dell'Orda! Portami le prove della tua vittoria su questo campo di battaglia decisivo e sarai $Gricompensato:ricompensata; a dovere.",
  obj = "Porta 3 Darkspear Islands Marks of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Notizie dalle Darkspear Islands, $N?",
  reward = "Le sabbie delle Darkspear Islands sono intrise del sangue dell'Alleanza che hai ucciso. Ben fatto, $N.$B$BPer l'Orda!",
}
T[98888] = {
  title = "Conflitto nelle Darkspear Islands",
  progress = "Nelle Darkspear Islands la lotta non si ferma mai, $N. Insieme distruggeremo quei cani dell'Alleanza della Theramore Expeditionary Force!",
  reward = "Ben fatto, $C! Hai aiutato l'Orda a prendere il controllo delle Darkspear Islands!",
}
T[98889] = {
  title = "Conflitto alle Darkspear Islands",
  desc = "La Theramore Expeditionary Force non molla: continua a mandare rinforzi per rafforzare la sua posizione sulle Darkspear Islands.$B$BVai e mostra loro la potenza dell'Orda! Portami le prove che hai vinto su questo campo di battaglia cruciale e sarai $Gricompensato:ricompensata; come si deve.",
  obj = "Porta 3 Darkspear Islands Marks of Honor a un Horde Warbringer fuori dai campi di battaglia.",
}
T[98891] = {
  title = "Conflitto alle Darkspear Islands",
  desc = "La Theramore Expeditionary Force non molla: continua a mandare rinforzi per rafforzare la sua posizione sulle Darkspear Islands.$B$BVai e mostra loro la potenza dell'Orda! Portami le prove che hai vinto su questo campo di battaglia cruciale e sarai $Gricompensato:ricompensata; come si deve.",
  obj = "Porta 3 Darkspear Islands Marks of Honor a un Horde Warbringer fuori dai campi di battaglia.",
}
T[98893] = {
  title = "Conflitto alle Darkspear Islands",
  desc = "La Theramore Expeditionary Force non molla: continua a mandare rinforzi per rafforzare la sua posizione sulle Darkspear Islands.$B$BVai e mostra loro la potenza dell'Orda! Portami le prove che hai vinto su questo campo di battaglia cruciale e sarai $Gricompensato:ricompensata; come si deve.",
  obj = "Porta 3 Darkspear Islands Marks of Honor a un Horde Warbringer fuori dai campi di battaglia.",
}
T[98895] = {
  title = "Scontro alle Darkspear Islands",
  desc = "Contro i Darkspear Raiders la battaglia si sta facendo accesa, e se non arrivano aiuti in fretta perderemo le Darkspear Islands.$B$BCome $Gorgoglioso:orgogliosa; membro dell'Alleanza, hai il dovere di impedirlo. Portami le prove di quello che hai fatto in prima linea e sarai $Gvenerato:venerata; come $Gun eroe:un'eroina; dell'Alleanza!",
  obj = "Porta 3 Darkspear Islands Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Come va la tua campagna nelle Darkspear Islands, $N?",
  reward = "Nelle Darkspear Islands ti sei $Gdistinto:distinta; in battaglia con onore, e i tuoi sforzi non sono passati inosservati.$B$BMa ci sono sempre altre battaglie da combattere. Continua a dimostrare quanto vali sul campo e di certo ne raccoglierai i frutti.",
}
T[98896] = {
  title = "Scontro alle Darkspear Islands",
  progress = "Nelle Darkspear Islands si combatte ancora, $N. Raduna le forze e schiaccia i Darkspear Raiders!",
  reward = "Ottimo lavoro, $C! Ogni colpo inferto ai Darkspear Raiders ci porta un passo più vicini alla vittoria totale.$B$BPer l'Alleanza!",
}
T[98897] = {
  title = "Scontro alle Darkspear Islands",
  desc = "La battaglia contro i Darkspear Raiders si fa sempre più accesa, e se non arrivano subito aiuti perderemo le Darkspear Islands.$B$BCome $Gorgoglioso:orgogliosa; membro dell'Alleanza, è tuo dovere impedirlo. Portami le prove di quello che hai fatto in prima linea e sarai $Griverito:riverita; come $Gun eroe:un'eroina; dell'Alleanza!",
  obj = "Porta 3 Darkspear Islands Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
}
T[98899] = {
  title = "Scontro alle Darkspear Islands",
  desc = "Lo scontro con i Darkspear Raiders è sempre più acceso, e se gli aiuti non arrivano presto perderemo le Darkspear Islands.$B$BDa $Gorgoglioso:orgogliosa; membro dell'Alleanza, hai il dovere di impedirlo. Portami le prove di quanto hai fatto in prima linea e sarai $Gvenerato:venerata; come $Gun eroe:un'eroina; dell'Alleanza!",
  obj = "Porta 3 Darkspear Islands Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
}
T[98901] = {
  title = "Scontro alle Darkspear Islands",
  desc = "Lo scontro con i Darkspear Raiders è sempre più acceso, e se gli aiuti non arrivano presto perderemo le Darkspear Islands.$B$BDa $Gorgoglioso:orgogliosa; membro dell'Alleanza, hai il dovere di impedirlo. Portami le prove di quanto hai fatto in prima linea e sarai $Gvenerato:venerata; come $Gun eroe:un'eroina; dell'Alleanza!",
  obj = "Porta 3 Darkspear Islands Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
}
T[98903] = {
  title = "La Battaglia per le Darkspear Islands!",
  desc = "Va' a combattere alle Darkspear Islands in nome della Theramore Expeditionary Force, $N! Vinci e mostra a questi cani dell'Orda quanto è potente l'Alleanza!",
  obj = "Vinci sul campo di battaglia delle Darkspear Islands e torna da Brelinda McFarry a Northwatch Hold.",
  reward = "La Theramore Expeditionary Force ti è grata, $N, per la dedizione e il valore che hai dimostrato nella battaglia per le Darkspear Islands.$B$BPer l'Alleanza!",
}
