T[98906] = {
  title = "La Battaglia per le Darkspear Islands!",
  desc = "Alle Darkspear Islands la battaglia è in stallo, $C. Fai vedere a quegli sciocchi dell'Alleanza chi è il più forte.$B$BServi i Darkspear a testa alta e vinci in battaglia. I Loa ti benediranno di sicuro, $C!",
  obj = "Ottieni una vittoria nel campo di battaglia delle Darkspear Islands e torna da Nizook Boof a The Merchant Coast.",
  reward = "Alle Darkspear Islands hai mostrato forza e dedizione! Il tuo valore in battaglia è da ammirare, mon!",
}
T[98907] = {
  title = "La Battaglia per le Darkspear Islands!",
  desc = "Alle Darkspear Islands la battaglia è in stallo, $C. Fai vedere a quegli sciocchi dell'Alleanza chi è il più forte. Servi i Darkspear a testa alta e vinci in battaglia. I Loa ti benediranno di sicuro, $C!",
  obj = "Ottieni una vittoria nel campo di battaglia delle Darkspear Islands e torna da Nizook Boof a The Merchant Coast.",
}
T[98908] = {
  title = "La Battaglia per le Darkspear Islands!",
  desc = "Alle Darkspear Islands la battaglia è in stallo, $C. Fai vedere a quegli sciocchi dell'Alleanza chi è il più forte.$B$BServi i Darkspear a testa alta e vinci in battaglia. I Loa ti benediranno di sicuro, $C!",
  obj = "Ottieni una vittoria nel campo di battaglia delle Darkspear Islands e torna da Nizook Boof a The Merchant Coast.",
}
T[99046] = {
  title = "La Staffetta Scomparsa",
  desc = "Tempo fa il Consiglio della Foresta ha inviato un piccolo gruppo di sentinelle all'Oracle Tree. L'albero manda messaggi ai nostri anziani, e spetta a noi portarli fino a Darnassus senza che vadano perduti.$B$BHo saputo che la nostra ultima staffetta non è ancora arrivata. I messaggi dell'Oracolo non giungono con regolarità, ma stavolta l'attesa è stata insolitamente lunga.$B$BTi prego, segui la strada verso ovest fino all'Oracle Glade e accertati che la nostra sentinella stia bene. Toccava a Eralya Leafshadow, che è ancora in addestramento. Che Elune ti guidi.",
  obj = "Cerca Sentinel Eralya Leafshadow lungo la strada che porta a Oracle Glade.",
  reward = "La grazia di Elune... Non morirò... da sola...",
}
T[99047] = {
  title = "Non Ancora Morta",
  desc = "Le mie sorelle e io... siamo state mandate... Oracle Tree...$B$BAlbero... messaggio. Io... arpie... ovunque...$B$B<Eralya tossisce sangue, il volto contratto dal dolore.>$B$BForse non mi resta molto... non arriva nessuno. Ti prego... Byancie... a Dolanaar...",
  obj = "Chiedi a Byancie, a Dolanaar, di soccorrere Sentinel Eralya Leafshadow.",
  reward = "Le arpie sono state contagiate dalla stessa corruzione che sta comparendo in tutta la foresta. Sono certa che sia anche ciò che affligge la Sentinella Eralya.$B$BDobbiamo sbrigarci. Tra non molto soccomberà alle ferite.",
}
T[99048] = {
  title = "Una Mano Scomparsa",
  desc = "Un membro della Mano Frantumata, un gruppo di combattenti più... discreti, sorvegliava da lontano il Tiragarde Keep. All'improvviso i suoi rapporti hanno smesso di arrivare.$B$BDubito che gli umani siano riusciti a catturarla, quindi temo che ci sia di mezzo qualcosa di più pericoloso. Vedi se riesci a trovarla. Speriamo che i messaggi siano solo in ritardo.",
  obj = "Trova Heglan Shadeeye a nord del Tiragarde Keep.",
  reward = "Il corpo di Heglan giace freddo tra i resti della capanna.$B$BQualunque cosa l'abbia uccisa non sembra umana. Nei dintorni potrebbero esserci tracce dell'accaduto.",
}
T[99049] = {
  title = "Minaccia dal Basso",
  desc = "La zona qui intorno è devastata e mostra chiari segni di uno scontro. Qualunque cosa abbia teso l'imboscata a Heglan non ne è uscita indenne. Probabilmente nei paraggi restano tracce di quanto è accaduto.$B$BÈ facile che Orgnil voglia vedere ogni prova lasciata dagli aggressori.",
  obj = "Trova tracce di ciò che ha attaccato Heglan Shadeeye.",
  progress = "L'hai trovata?",
  reward = "Questo stendardo e questo frammento di lama appartengono ai naga! Devono essere scesi lungo la costa da nord.$B$BNon possiamo permettere che si stabiliscano qui. Stretta da entrambi i lati, Razor Hill non reggerebbe.",
}
T[99050] = {
  title = "Il Great Tree Provvede",
  desc = "Mi serve il tuo aiuto per procurarmi gli ingredienti con cui tenere a bada il male finché Eralya non potrà tornare qui per altre cure.$B$BPer fortuna, la nostra casa vivente è ancora generosa e provvederà a noi nel momento del bisogno.$B$BL'ingrediente principale sono le fronde rugiadose di sferzatore. Le troverai intorno al Lake Al'Ameth, proprio a sud di qui, oppure al Wellspring Lake e lungo il suo fiume, a nord-ovest.$B$BInoltre, mi serviranno un'empty vial e un po' d'acqua di sorgente. Puoi comprarle entrambe qui in città, oppure ottenerle con uno scambio.",
  obj = "Raccogli 6 Dewy Lasher Fronds, un'Empty Vial e una Refreshing Spring Water per Byancie a Dolanaar.",
  progress = "Hai gli ingredienti? Temo che a Eralya resti poco tempo.",
  reward = "Ti ringrazio per l'aiuto. Ti prego, prendi questo: ti aiuterà a coprire le spese per la fiala e l'acqua.$B$BOra preparo l'unguento. Ci vorrà solo un momento.",
}
T[99051] = {
  title = "Minaccia dal Basso",
  desc = "Non sarebbe la prima volta che quei serpenti ci danno fastidio. Bisogna fargli capire che qui non li tolleriamo.$B$BScopri dove si stanno accampando i loro esploratori e massacrali. Portami le loro pinne come prova. Dobbiamo agire in fretta, perché il messaggio arrivi forte e chiaro.",
  obj = "Raccogli 9 Naga Spinefins.",
  progress = "Quella feccia di serpenti non ti sta dando problemi, spero?",
  reward = "Spero che questo basti a rispedirli a nord. Metterò qualche grunt a tenere d'occhio eventuali ritardatari o movimenti strani.",
}
T[99052] = {
  title = "Minaccia dal Profondo",
  desc = "Uno dei miei esploratori ha riferito che un sea giant ha seguito quei naga fin quaggiù. Non so se se lo siano portato dietro apposta o cosa, ma in ogni caso è pericoloso.$B$BÈ giovane, ma se cogliesse un orco alla sprovvista potrebbe comunque squarciarlo in due in un battito di ciglia. Voglio che sparisca. Però ti consiglio di trovare qualcuno che ti aiuti ad affrontarlo.",
  obj = "Uccidi il sea giant lungo la costa settentrionale di Durotar e riporta una prova dell'impresa.",
  progress = "Fagli vedere sangue e tuono!",
  reward = "Ah! Ho sentito il suo corpo crollare fin da qui!$B$BVa' $Gfiero:fiera; dell'uccisione di oggi: non sono in molti a poter dire di essere sopravvissuti a uno scontro con un sea giant.",
}
T[99053] = {
  title = "Fuga da Ban'ethil",
  desc = "Le mie preghiere sono state esaudite! Ti sei $Gfatto:fatta; strada combattendo fin quaggiù, e te ne sono grata.$B$BL'Oracle Tree mi ha mandata qui con un messaggio per i druidi addormentati, ma il posto l'ho trovato invaso da cima a fondo dai furbolg! Prima che potessi tornare indietro mi hanno teso un'imboscata e mi hanno portata qui sotto — e temo di diventare il loro prossimo pasto.$B$BNon so tu, ma io questo posto lo detesto. Il sottosuolo non è fatto per i kaldorei.",
  obj = "Aiuta Sentinel Lynessa Duskblossom a fuggire dal Ban'ethil Barrow Den e riferisci che è salva a Sentinel Kyra Starsong a Dolanaar.",
  reward = "Sia ringraziata Elune: per fortuna c'eri tu ad aiutare Lynessa a sfuggire a un oscuro destino per mano degli Gnarlpine. È una delle nostre migliori, e anche un'amica mia.$B$BTi prego, accetta questo in segno di gratitudine, e che ti sia utile per proteggere i kaldorei.",
}
T[99073] = {
  title = "Lenire la Sofferenza",
  desc = "L'unguento è pronto. Portalo subito a Eralya.$B$BNon so se riuscirà davvero a guarirla. The rot peggiora in fretta, e più si diffonde più diventa forte.$B$BSe non altro, le allevierà la sofferenza. E già per questo vale la pena sbrigarsi.",
  obj = "Porta il Lashwater Salve a Sentinel Eralya Leafshadow sulla strada per Oracle Tree.",
  progress = "<Eralya ha smesso di rispondere a parole. Solo un debole respiro gorgogliante conferma che è ancora viva.>",
  reward = "<Il respiro di Eralya si calma in fretta mentre la aiuti a mandar giù l'unguento. Potrebbe non sopravvivere, ma ha trovato un po' di pace.>",
}
T[99079] = {
  title = "Viandante Malah",
  desc = "I Viandanti sono gli esploratori di cui il nostro popolo si fida di più. Anche se sono fedeli soltanto al Gran Capotribù, a volte il giovane Baine chiede il loro aiuto.$B$BQuesta è una di quelle volte. Tre giorni fa la Viandante Malah è stata mandata vicino ai nostri confini orientali, e ieri sera non è tornata. In questi casi è nostro dovere accertarci che i Viandanti siano sani e salvi.$B$BIo devo garantire la sicurezza del villaggio. Dimostra il tuo valore e va' a cercare Malah. La riconoscerai dalla fascia sulla fronte e dal bastone piumato, simboli dei Viandanti.",
  obj = "Trova la Viandante Malah Longwind a est di Bloodhoof Village, vicino al confine di Mulgore.",
  reward = "È chiaro che Malah non è morta di morte naturale. Ha la schiena piena di frecce, e il terreno lì intorno ne è disseminato.",
}
T[99080] = {
  title = "Cacciali Via",
  desc = "Ascolta bene le mie parole: non cederemo ai centauri neppure un filo d'erba.$B$BVa' subito al loro accampamento, prima che riprendano fiato e arrivino al galoppo fino al nostro villaggio. Massacrali tutti. Fa' in modo che nessuno fugga nelle Barrens a cercare rinforzi.$B$BSe trovi il capo di questi aspiranti predoni, portami la testa: servirà da monito per chiunque osi calpestare la terra dei nostri antenati.",
  obj = "Uccidi 6 Galak Centaurs e 4 Galak Outrunners, e porta la testa di Herak the Pillager a Baine Bloodhoof.",
  progress = "L'impresa è compiuta?",
  reward = "Sei $Gcoperto:coperta; di sangue di centauro. Ricorda questa sensazione. Tra la nostra gente non c'è onore più grande.$B$BHo sentito il momento in cui è caduto l'ultimo, quando il tuono dei loro zoccoli ha smesso di echeggiare. Ben fatto!$B$BOggi il villaggio ha conquistato una grande vittoria, che dà ai nostri piccoli il senso di sicurezza di cui hanno più che mai bisogno. Ti sono profondamente grato, giovane $C.",
}
T[99081] = {
  title = "Notizie Funeste",
  desc = "Nella direzione da cui devono essere partite le frecce conficcate nella schiena di Malah si intravede quello che sembra un nuovo accampamento di centauri. C'è un gran fermento, segno che un piccolo gruppo di predoni si è spinto fino a Mulgore.$B$BLa Viandante stringe ancora in mano un rapporto. Brave Wildrunner vorrà sapere che fine ha fatto Malah — e chi l'ha uccisa.",
  obj = "Porta il Rapporto della Viandante Malah a Brave Wildrunner a Bloodhoof Village.",
  reward = "Sono notizie davvero gravi. Dobbiamo avvertire subito Baine!",
}
T[99082] = {
  title = "Il Gran Capotribù",
  desc = "Il coraggio con cui hai difeso la tua gente merita un riconoscimento. Recati a nord-ovest, a Thunder Bluff, la nostra possente città che nei mesi più caldi ci dona la sua ombra, e chiedi udienza a mio padre.$B$BÈ stato lui a guidare la carica insieme al giovane Warchief Thrall per riconquistare queste pianure e scacciare per sempre i centauri. Da Gran Capotribù qual è, ti ricompenserà generosamente per aver fatto la tua parte nel difendere ciò che lui ha conquistato con tanto coraggio.$B$BSiede sull'altura centrale: per raggiungerlo dovrai prendere un ascensore.",
  obj = "Chiedi udienza al Gran Capotribù Cairne Bloodhoof a Thunder Bluff.",
  reward = "I centauri Galak osano mostrarsi a Mulgore?!$B$BScacciandoli hai reso orgogliosi i tuoi antenati. Forse così ricorderanno il dolore che li attende, se mai dovessero riprovarci!$B$BTi prego, accetta questo dono in onore della tua impresa. Che ti sia utile mentre ti avventuri nel regno della Madre Terra, fino agli angoli più remoti del mondo.",
}
T[99101] = {
  title = "Il Nostro Antico Nemico",
  desc = "Baine Bloodhoof guida il nostro villaggio. Deve sapere subito di questa incursione.$B$BPortagli il rapporto della Viandante Malah. Lo troverai al centro del paese.$B$BFa' presto. Non c'è tempo da perdere!",
  obj = "Porta il Rapporto della Viandante Malah a Baine Bloodhoof.",
  progress = "Cosa mi porti, $C?",
  reward = "<Baine legge il rapporto, e il suo sguardo si incupisce.>$B$BNon lo tollererò. Grazie per avermelo consegnato, $N.",
}
T[99108] = {
  title = "Incontro di Allenamento",
  desc = "Salute, giovane $C. Non sei $Gun guerriero:una guerriera; e su quella via non posso guidarti, ma questo non vuol dire che i miei insegnamenti non possano esserti utili.$B$BL'arena è davanti a te. Là dentro non conta chi chiami madre, né se impugni la spada o l'arco. Tutti sono uguali, e tutti imparano ad affilare le corna nello scontro diretto.$B$BVuoi entrare nel nostro spazio e conoscere di persona le nostre usanze? Puoi affrontare uno qualunque di questi novizi, o chiunque altro sia disposto a battersi. Quale, poco m'importa.",
  obj = "Sconfiggi 3 altri giocatori in duello o Novice Warriors per Tang Stonehoof.",
  progress = "Nessun maestro insegna meglio della punta di un'arma avversaria rivolta al cuore.",
  reward = "Mi fai onore con le tue capacità, $C. Forse c'è ancora speranza per la nuova generazione.$B$BPrendi questi e curati le ferite, perché in questo duro mondo ti attendono molte altre battaglie.",
}
T[99123] = {
  title = "Persa nelle Ombre",
  desc = "Ho deciso di fare un po' di ricognizione sulla rupe da sola. Purtroppo la magia mi si è esaurita proprio nel momento sbagliato, e da allora sono bloccata qui, costretta a nascondermi.$B$BSe potessi aiutarmi a fuggire, te ne sarei grata.",
  obj = "Aiuta Pal'juh a fuggire da Kolkar Crag e porta la notizia del tuo successo a Master Vornal a Sen'jin Village.",
  reward = "Ah, Pal'juh si è cacciata di nuovo nei guai, eh?$B$BSperiamo che stavolta abbia imparato la lezione e non vada più in giro da sola. Grazie per averla aiutata. È una cacciatrice promettente, solo che tende a comportarsi più come un raptor che come una tigre.",
}
T[99127] = {
  title = "Un Disastro di Rete",
  desc = "Oggi i pesci proprio non abboccano, e c'è qualcosa in loro che non va. Non sono solo gli ami vuoti: non ho visto neanche un pesciolino affiorare.$B$BStanotte Lee, qui presente, ha piazzato delle trappole. Va' a controllare se almeno lì c'è un po' di pesce. Se trovi qualcosa di strano, fammelo vedere.",
  obj = "Controlla le trappole da pesca a Crystal Lake.",
  progress = "Preso niente?",
  reward = "Sono tutte così, le trappole? Pare che quei seccatori dei nostri nuovi vicini stiano facendo più danni di quanto pensassimo. Se non facciamo qualcosa, finirò sul lastrico.",
}
T[99128] = {
  title = "Minaccia Viscida",
  desc = "Può essere solo opera di quei murlocs dall'altra parte del lago. Sono bestiole disgustose, con un caratteraccio feroce e dei denti che non sono da meno. $B$BSe lasciamo correre, in tutto il lago non resterà più un pesce. Se potessi sfoltirli un po', mi daresti un aiuto enorme.",
  obj = "Uccidi 7 Murlocs e 4 Murloc Streamrunner a Crystal Lake, poi torna da Jason Mathers.",
  progress = "Sono morti?",
  reward = "Sento i loro gorgoglii fin da qui — me li sognerò la notte. Be', questo dovrebbe rallentarli — anche se non ho dubbi che rimpiazzeranno presto le perdite.",
}
T[99129] = {
  title = "Parlare con un Tale di un Murloc",
  desc = "L'altro giorno Remy ha nominato i murlocs... sono quasi sicuro che odia quelle bestiacce quanto me. $B$BPotrebbe avere qualche idea su come tenerle lontane dai miei pesci in futuro. Ti chiederei di andare a fare due chiacchiere con lui e vedere se gli viene in mente qualcosa.",
  obj = "Parla con Remy \"Two Times\" dei problemi di Jason con i murlocs.",
  reward = "Continuo ad avvisare le guardie riguardo ai murlocs, ma non mi danno retta.$B$BHo in mente qualcosa per fargliela pagare, a quelle bestiacce. Però mi servirà il tuo aiuto per procurarmi l'occorrente.",
}
T[99130] = {
  title = "Un'Offerta Allettante",
  desc = "Per i murlocs ho in mente qualche idea. E una di queste dà una mano anche a qualcun altro.$B$BNelle fattorie qui intorno si trova spesso un'erbaccia, l'erba del crepuscolo, e i suoi petali, in grandi quantità, sono tossici per quasi tutti gli animali. Se ci prepariamo un'esca per murlocs, magari quelle creature imparano a stare alla larga.$B$BE intanto qualche contadino si ritrova i campi ripuliti. Ci guadagnano tutti... ci guadagnano tutti.",
  obj = "Raccogli 6 Vials of Animal Blood e 18 Petali di Erba del Crepuscolo per l'esca per murlocs, poi torna da Remy \"Two Times\" a Goldshire.",
  progress = "Trovato tutto?",
  reward = "Dammi solo un minuto...$B$BL'esca è piuttosto semplice, e finché nessun animale domestico ci mette il muso non dovrebbe essere pericolosa. Tu di' solo a Jason di non mangiarne neanche un po'.",
}
T[99131] = {
  title = "Un'Esca per il Successo",
  desc = "Di' a Mathers che più tardi, in giornata, può passare a prendere l'esca: gli spiegherò io come usarla per bene.$B$BSpero che presto possa tornare a vendere il suo pesce. E che al mondo ci siano meno murlocs.",
  obj = "Torna da Jason Mathers.",
  reward = "Un'esca avvelenata? Basta che non se la mangino i pesci, e dovrebbe funzionare. Più tardi passo da Remy a prenderla.",
}
T[99134] = {
  title = "Disciplina",
  desc = "Non fai parte della Deathguard, e quindi non mi hai ancora deluso.$B$BCome premio per esserti $Gdimostrato:dimostrata; non troppo incompetente, punirai chi invece ha dato fin troppa prova di simili talenti.$B$BOra sbrigati — $N, giusto? — o aggiungerò il tuo nome al mio registro, e sarai tu il premio di qualcun altro.",
  obj = "Punisci 5 Guardiamorte per Executor Zygand.",
  progress = "Sarà meglio che ne valga la pena.",
  reward = "Nella morte ci sono concesse ben poche gioie. Per fortuna, il dolore è la prima fra queste.$B$BOggi mi hai compiaciuto, e dunque hai compiaciuto la Dama Oscura. Forse potrai esserci ancora utile.",
}
T[99141] = {
  title = "Pazienza",
  desc = "Sia chiaro, $C — la Dama Oscura esige che la sua volontà venga eseguita alla perfezione. In quanto Esecutore, è mio dovere assicurarmi che accada.$B$BDiversi dei miei Guardiamorte sono in ritardo con i rapporti. Inutile dire che la mia pazienza è finita. Raccogli i loro resoconti e portameli in nome della Dama Oscura.$B$BTroverai Deathguard Dillinger poco a ovest di qui, vicino al cimitero. Deathguard Kristof è di stanza alla stazione di posta a est. E va' a controllare l'abomination Gordo; vaga a ovest, vicino allo Stillwater Pond.",
  obj = "Ottieni i rapporti di Deathguard Dillinger, di Deathguard Kristof e di Gordo per Executor Zygand.",
  progress = "Faresti meglio ad avere quei rapporti in mano, o a levarti dalla mia vista.",
  reward = "Avrei dovuto immaginarlo che un abomination non sapesse scrivere nulla di utile. Che questo mio errore di giudizio resti fra noi.$B$BMi hai compiaciuto, e dunque hai compiaciuto la Dama Oscura. Forse c'è speranza anche per te.",
}
T[99142] = {
  title = "Tomb Weed",
  desc = "Se sei $Gdiretto:diretta; a est, verso la Balnir Farmstead, avrei altro da farti fare. Di questi tempi trovare buoni aiutanti è davvero difficile, e il tuo scontro con Gordo lo dimostra fin troppo bene.$B$BMan mano che mi procuro la doom weed, la ritocco con qualche piccola modifica alchemica e la ripianto in quella fattoria: è così che coltivo la mia creazione definitiva. La chiamo erba delle tombe, e sarà l'araldo del mio glorioso destino.$B$BMentre sei lì, tieni d'occhio lo Scourge della zona. Sembra... attratto... dall'erba. Curioso.",
  obj = "Raccogli 5 Tomb Weed e riportale a Junior Apothecary Holland.",
  progress = "Ancora interruzioni! Aspetta, sei tu. Sei $Griuscito:riuscita; a recuperare l'erba delle tombe?",
  reward = "Davvero gloriosissimo!$B$B<Junior Apothecary Holland esamina le erbe.>$B$BMmm, speravo che maturassero con un po' più di violenza. Ma un progresso è sempre un progresso!$B$BMoltissimi moriranno per quello che hai fatto oggi. Dovresti andarne $Gfiero:fiera;.",
}
T[99143] = {
  title = "Bottiglie e Ninnoli",
  desc = "Quegli uomini pesce penseranno proprio come i pesci veri, no? Quindi quello che piace a loro piacerà anche ai pesci!$B$BSe frughi un po' tra le loro cianfrusaglie e mi riporti qualcosa che possa fare da buona esca, ti ricompenserò.",
  obj = "Raccogli 6 pezzi di cianfrusaglie luccicanti dall'accampamento Murloc qui vicino.",
  progress = "Cos'hai trovato? Qualcosa di interessante?",
  reward = "Una raccolta interessante. Dovrebbero funzionare abbastanza bene!$B$BEcco un po' della mia vecchia attrezzatura. Sarà utile a chiunque voglia muovere i primi passi nella pesca.",
}
T[99144] = {
  title = "In Cerca di Rifugio",
  desc = "Che la Luce ti benedica per avermi trovato. Venivo da Bandarion Keep con un messaggio per Shari Stilwell, a Brill, quando questi mostri mi hanno catturato. Brandiscono la Luce con l'odio nel cuore, e quel che resta del mio sangue ribolle a vederlo. È contro tutto ciò in cui crediamo!$B$B<Bareth Dawnstone ritrova l'equilibrio.>$B$BSiamo rimasti in pochi. Se mi aiutassi a fuggire da qui, te ne sarei grato per sempre.",
  obj = "Aiuta Bareth Dawnstone a fuggire dal Crusader's Outpost e riferisci a Shari Stilwell a Brill che è in salvo.",
  reward = "Che tu sia $Gbenedetto:benedetta; per aver aiutato Dawnstone. Qui il nostro ordine sta ancora mettendo radici, e perdere così presto uno tanto promettente sarebbe devastante.$B$BAccetta questo, ti prego, in segno della nostra gratitudine. Se un giorno le nostre vie ti interessassero, il nostro monastero, Bandarion Keep, si trova sulle rupi a nord-ovest della Solliden Farmstead. Accogliamo chiunque cerchi la guida della Luce.",
}
T[99152] = {
  title = "Come in Alto, Così in Basso",
  desc = "I Contaminati di Shadowvale, a sud-ovest, sono senz'altro un problema, ma non possiamo lasciare che il marciume delle cantine sotto il paese degeneri in una vera e propria rivolta dello Scourge a Bandarion Keep.$B$BDevo preparare a dovere queste reclute, nel caso succeda. Tu, invece, riceverai quello che mi piace chiamare un corso accelerato.$B$BScendi sotto Shadowvale e recupera un po' delle loro ossa schifose, così potremo studiarle meglio. Mi servono quelle che conservano ancora parte della magia di rianimazione originaria — cioè quelle che brillano.",
  obj = "Raccogli 6 Faintly Glowing Bones per Hilda the Breaker.",
  progress = "Faresti meglio a non tornare a mani vuote. O mi porti le ossa che ti ho chiesto, o il tuo corpo su una barella, a conferma che almeno ce l'hai messa tutta per procurartele.",
  reward = "Ben fatto, $C. Con queste ossa forse riusciremo a capire meglio come una minaccia simile sia potuta passare inosservata così a lungo.",
}
T[99153] = {
  title = "Quello Che È Scappato",
  desc = "Ehi, tu! Tra le nostre fila le voci girano in fretta. Ho saputo del lavoro che hai fatto con i cultisti intorno ai resti della battaglia contro Naxxramas.$B$BIl problema è che uno di quelli se l'è svignata con un pezzo del cristallo focalizzatore. Pare che abbia ancora un po' di carica. Molto probabilmente è da qualche parte sotto Shadowvale. O li sta rianimando o li sta rendendo più forti, e nessuna delle due cose ti farebbe piacere.$B$BTrova quel cristallo prima che la situazione sfugga di mano.",
  obj = "Trova il Frammento di Cristallo Nascosto sotto Shadowvale per Ephram Barbaro.",
  progress = "Hai trovato quel dannato affare?",
  reward = "Ben fatto — e pure in fretta! Ora passiamo alla parte che preferisco...",
}
T[99156] = {
  title = "Pattuglia della Retroguardia",
  desc = "Maledizione! Mentre eri di pattuglia è arrivato un nuovo rapporto. Qualcuno ha avvistato un abomination fuori controllo che vaga nella parte orientale delle Tirisfal Glades, vicino alla Venomweb Vale.$B$BQualcosa non va. Un abomination non passa mica oltre il Bulwark senza che nessuno se ne accorga.$B$BLa faccenda deve restare strettamente riservata. Ma una creatura simile non si abbatte facilmente; ti serviranno alleati, se non vuoi finire come suo prossimo pasto.$B$BCompleta l'incarico e sarai $Gricompensato:ricompensata; come si deve. Portami il suo cuore come prova dell'impresa.",
  obj = "Porta il Riptear's Heart a Deathguard Linnea.",
  progress = "Hai sistemato il nostro piccolo problema?",
  reward = "Dimostri l'astuzia e il coordinamento propri di tutti i Forsaken — doti che lo Scourge senza cervello non avrà mai.$B$BCome promesso, accetta questo in segno di gratitudine per quanto hai fatto.",
}
T[99158] = {
  title = "Alba fra le Montagne",
  desc = "Là fuori, fra le montagne, c'è un sacerdote che fa parte di un'organizzazione chiamata Argent Dawn: un gruppo sacro che si dedica a scovare e distruggere ciò che è empio e innaturale.$B$BFather Gavin, però, più che prendere le armi cerca di aiutare e curare tutti. Ha rimesso a posto un vecchio edificio per farne un posto dove i viaggiatori possano riposare, e l'ha chiamato Misty Pine Refuge. Devo fargli avere una spedizione di holy candles. Se passi da quelle parti, potresti portargliele?",
  obj = "Porta la crate of candles a Father Gavin al Misty Pine Refuge.",
  progress = "Per quale motivo la Luce ti ha guidato qui, oggi?",
  reward = "Ah. Candele da Ironforge.$B$BNel mio eremo basto quasi del tutto a me stesso, ma alcune cose essenziali le ricevo volentieri dalla città e dai devoti.",
}
T[99159] = {
  title = "Trovare Calore",
  desc = "Il mio focolare è aperto a qualunque anima abbia bisogno di scaldarsi, ma, se puoi, vorrei chiederti di darmi una mano.$B$BMi serve soltanto altra legna da ardere. Di solito ci penso io, ma altre faccende mi hanno tenuto occupato.",
  obj = "Raccogli 14 pezzi di legna da ardere.",
  progress = "La Luce ti guidi in quello che devi fare.",
  reward = "Ah, perfetto. Vanno bene — quelli ancora troppo bagnati li metterò ad asciugare.$B$BE adesso, se te la senti, avrei altre cose da fare in cui mi servirebbe una mano.",
}
T[99160] = {
  title = "L'Ira della Brina",
  desc = "Forse hai visto gli elementali qui intorno. Qualche giorno fa una lastra di roccia e ghiaccio è venuta giù dalle vette e li ha agitati.$B$BPer un nano o un umano qualunque queste montagne gelate sono già insidiose così, anche senza elementi che prendono forma. Io non sono più tipo da combattere — perciò ogni spirito che riuscirai a uccidere aiuterà a rendere più sicura la strada.",
  obj = "Distruggi 10 elementali del ghiaccio minori.",
  progress = "Di che cosa hai bisogno?",
  reward = "Magari avessimo potuto placarli e basta. Purtroppo non ne sapevo abbastanza, e lasciarli liberi era troppo pericoloso.",
}
T[99161] = {
  title = "L'Ira della Brina",
  desc = "Il primo elementale comparso dopo la frana, l'ho notato, era più grande degli altri. E da quel che ho capito è lui che ogni tanto fa cambiare il tempo e scatena altre piccole frane.$B$BIo lo chiamo 'Avala'. Se riesci a ucciderlo e a portarmi il suo nucleo come prova, avrai una ricompensa.",
  obj = "Uccidi Avala e recuperane il nucleo.",
  progress = "Guardati dall'inverno, $Gamico:amica;.",
  reward = "La Luce ti benedica, $C. Grazie a quello che hai fatto questa zona è molto più sicura e, spero, si eviteranno morti inutili.",
}
T[99162] = {
  title = "Freddo Insidioso",
  desc = "Persino i montanari di Ironforge devono stare all'erta quando attraversano le vette di Dun Morogh. La neve e il ghiaccio che vengono giù spesso costano la vita ai meno esperti.$B$BDi solito, dopo una frana, vado in cerca di segni di sopravvissuti o di vittime — e prego la Luce di non trovare niente. Ma con gli elementi così agitati ho preferito non allontanarmi troppo. Se tu andassi a cercare i montanari dispersi e mi portassi i loro fucili, li riporterei io a Ironforge.",
  obj = "Raccogli i fucili dei montanari caduti.",
  progress = "Di che cosa hai bisogno?",
  reward = "I montanari incidono il proprio nome sul calcio del fucile, così si possono riconoscere se dovesse succedere qualcosa. Li rimanderò a Ironforge — lì qualcuno li farà avere alle famiglie.",
}
T[99191] = {
  title = "Una Donazione di Lana",
  progress = "Per ora l'High Order accetta donazioni di wool cloth.$B$BCon una donazione di sessanta pezzi di wool cloth avrai il pieno riconoscimento dell'High Order per la tua generosità. Per il momento, all'High Order sessanta pezzi di lana dovrebbero bastare per le sue necessità.$B$BSe hai con te i sessanta pezzi di wool cloth e sei $Gpronto:pronta; a donarli, li prendo anche subito.",
  reward = "Magnifico! Ti ringraziamo della generosa donazione, $N!",
}
T[99196] = {
  title = "Una Donazione di Lana",
  progress = "In questo momento i Windshapers accettano donazioni di wool cloth.$B$BSe donerai sessanta pezze di wool cloth, i Windshapers riconosceranno appieno la tua generosità.$B$BSe hai con te le sessanta pezze di wool cloth e sei $Gpronto:pronta; a donarle, le prendo subito.",
  reward = "Ti ringraziamo della generosa donazione!$B$BChe i venti siano con te, $Gamico:amica;.",
}
T[99197] = {
  title = "Una Donazione di Seta",
  progress = "In questo momento a noi Windshapers serve silk cloth. Se potessi cedercene sessanta pezzi, con l'aiuto degli altri dovremmo farcela a raggiungere l'obiettivo.$B$BUn bel dono come la seta ti farebbe guadagnare di certo onore e stima fra i Windshapers!$B$BSe hai con te i sessanta pezzi di silk cloth e sei $Gpronto:pronta; a donarli, posso prenderli anche adesso.",
}
T[99260] = {
  title = "La Missione di Fillion",
  desc = "Dovevo recuperare dalle Overlook Standing Stones dati importanti sul flusso di energia elementale. Sono fondamentali per il nostro progetto di viaggiare in sicurezza fra Skywall e Azeroth: senza quei dati a sostenere i calcoli, non riusciremo a guidare le navi fendicielo attraverso il piano elementale.$B$BOrmai saranno andati perduti, e non sono in condizione di riprovare a raccoglierli. Ho raccontato al Magistro Supremo che mi hai salvato, e desidera parlarti di nuovo.",
  obj = "Parla con Elaadrin Evengale a Valanaar.",
  reward = "Grazie per aver salvato Fillion, $N. Ti avrà certo detto quanto siano fondamentali i dati che doveva recuperare.$B$BSenza di essi, la possibilità di aprire rotte sicure verso Azeroth è in serio pericolo. Le nostre spie riferiscono che i Windshapers si sono procurati i mezzi per attraversare i piani, e di sicuro vogliono custodire gelosamente il segreto.$B$BCome sempre, la loro arroganza dogmatica viene prima del bene del nostro popolo. Non sono molto meglio degli Al'Aketh.",
}
T[99267] = {
  title = "Una Brutta Fine",
  reward = "Night Watchman che giace morto davanti a te è coperto di tagli e di squarci profondi: è chiaro che l'ha dilaniato una qualche grossa bestia.$B$BNoti che il cadavere stringe ancora in mano un'unlit torch. A quanto pare, prima non l'avevi presa.$B$BTi chini e gliela strappi dalle dita rigide. Nei viaggi attraverso Duskwood e oltre potrebbe esserti utile, per rivelare ciò che l'oscurità nasconde.",
}
T[99411] = {
  title = "Kyle È Scomparso!",
  desc = "Aiuto, $N! Kyle, il mio prezioso cucciolo, è scappato! Me lo sento: sta girando per Bloodhoof Village, sperduto e affamato.$B$BMe lo trovi e gli dai da mangiare? Una volta mangiato si calmerà e tornerà a casa.$B$BPer sfamarlo dovrai procurarti del cibo. Il suo pasto preferito è la tender strider meat: se vai verso est dovresti trovare un sacco di zampalunga. Cacciane uno e porta a Kyle la sua carne succulenta. Quando vedi Kyle in paese, posa la carne a terra: di sicuro verrà da te.",
  obj = "Ahab Wheathoof, a Bloodhoof Village, in Mulgore, vuole che tu dia da mangiare al suo prezioso cucciolo, Kyle the Frenzied.$B$BDai la Tender Strider Meat a Kyle e torna da Ahab Wheathoof.",
  progress = "Kyle l'hai trovato?",
  reward = "Ottimo lavoro, $N! Appena ha mangiato, Kyle è tornato a casa ed è andato dritto a dormire. Grazie dell'aiuto.",
}

-- Saluti dei PNG di QuestIT. Le classi e le razze inglesi servono a calcolare l'impronta.
QuestTraduttoreQuestITNames = { classes = { "Paladin", "Warlock", "Warrior", "Hunter", "Priest", "Shaman", "Druid", "Rogue", "Mage" }, races = { "High Order Skyborne", "Windshaper Skyborne", "Night Elf", "Skyborne", "Tauren", "Undead", "Dwarf", "Gnome", "Human", "Troll", "Orc" } }
QuestTraduttoreQuestITGossip = QuestTraduttoreQuestITGossip or {}
local S = QuestTraduttoreQuestITGossip
S["000004bf"] = "Mago"
S["00009497"] = "$N!"
S["00009520"] = "Tauren."
S["000187fc"] = "Eh?"
S["000197e9"] = "Locanda"
S["0001aa80"] = "No!"
S["0004c1da"] = "Voi troppo spaventati! Io trova voi!"
S["000580a8"] = "Quando hai vissuto quanto me, capita di scordarti dell'amore per anni. Fa sempre piacere che qualcuno te lo ricordi."
S["0006e9e0"] = "$N, cosa aspetti? Trova il Primo Maresciallo nel Field of Strife e dagli gli ordini d'assalto. Appena li riceverà, lui e le sue truppe caricheranno l'Orda senza fare prigionieri!"
S["000ceea0"] = "Sembra che Skarr abbia trovato $Gil suo prossimo sfidante:la sua prossima sfidante;! Non vorrei essere nei panni di $Gquel povero sciocco:quella povera sciocca;!"
S["000e4f4a"] = "Miserabili sacchi di carne di verme, potete fare di meglio, ora dimostratelo!"
S["0017be8f"] = "Sei $Garrivato:arrivata; troppo tardi. Il rituale è compiuto!"
S["0020e03b"] = "Per i nostri Padroni!"
S["0029f609"] = "Io non sono qui a fare da maestro ai poppanti appena usciti dalla culla, e tu l'abilità che pretendo dai miei allievi non ce l'hai neanche lontanamente. Anzi, sei $Gun:una; $Gragazzo:ragazza; che fa pena, e mi faresti un favore a non startene lì a blaterarmi addosso."
S["002a21e0"] = "È passato troppo tempo. Dovremo riprovare più tardi."
S["002db9c7"] = "BIRRA!"
S["002e063c"] = "Banca"
S["002f0ba1"] = "MUORI!"
S["002f2284"] = "Doh!"
S["0032d6bc"] = "Di nuovo a casa, di nuovo a casa."
S["0033395f"] = "MOD!"
S["003596f6"] = "Correte!"
S["0035cc62"] = "sdsd"
S["0035dee3"] = "Signore?"
S["00364492"] = "TEST"
S["0036bed8"] = "Ugh."
S["00372346"] = "Mia carissima Torta, sono $Gstato:stata; via così a lungo. Finalmente siamo $Griuniti:riunite;. Dopo tanto tempo il nostro amore può sbocciare di nuovo."
S["0037c762"] = "Wow!"
S["0037c76f"] = "Caspita."
S["00387bd0"] = "Evviva!"
S["0038880a"] = "Sì?"
S["003889ca"] = "Già."
S["00388a38"] = "Sì?"
S["003cc135"] = "Addio, cittadini di Darkshire. Alla prossima..."
S["003ccba6"] = "Sono $Gpronto:pronta; ad ascoltare la tua storia, Baristolth."
S["00464e51"] = "Eh? Che cosa vuoi?"
S["004b991b"] = "Tutti hanno un punto debole, si tratta solo di trovarlo."
S["004d661a"] = "Dietro la fucina di Goldshire, Brother Wilhelm si allena spesso con Lyria Du Lac. Da lui probabilmente potresti imparare un paio di cose sul mestiere di paladino."
S["0051b5e0"] = "Salve. Sono $Gun istruttore:un'istruttrice; di $C $R, e tu sei $Gun:una; $C."
S["0052e92a"] = "Coraggio! Il dolore passa e gli uomini amano le donne con le cicatrici!"
S["0060a8a8"] = "Saluti, $N. $GBenvenuto:Benvenuta; nel regno di Dalaran.$B$BCi sono delle restrizioni finché la città resta in costruzione. Se hai questioni importanti da presentare ai Kirin Tor, puoi parlare con Arcanist Ginsberg nel belvedere a est."
S["00615a00"] = "L'unica cosa che Metzen farà per questo Winter Veil è arrostire allo spiedo!"
S["0065a71e"] = "Di questi tempi Tirth non è più lui, e l'assistente nemmeno."
S["0067c8b1"] = "Icy Scale Bracers."
S["0068a7de"] = "Cominciamo, con la benedizione della Madre Terra."
S["006b94b8"] = "Inginocchiati davanti a me, mortale! Inginocchiati davanti a Zod!"
S["0078dce9"] = "%s cammina avanti e indietro in attesa della battaglia."
S["0079e40f"] = "Se cerchi il miglior lavoro artigianale di questo continente o di qualunque altro al mondo, sei $Gcapitato:capitata; nel posto giusto!$B$BGrimand Elmore, al tuo servizio!"
S["007bb1d8"] = "Dall'alto ci hanno ordinato di distruggere Rajaxx. In termini tecnici: eliminazione con estremo pregiudizio."
S["00822102"] = "%s sbuffa profondamente mentre si ferma."
S["00830aef"] = "Saluti. Il mio compito è dare accesso alle informazioni sulla sintesi degli Earthen che i Creatori hanno operato sul mondo designato come Azeroth e, quando mi è consentito, fornire chiarimenti. Sono pronto a condividerle con te ora, se lo desideri."
S["00867af2"] = "Prima che ti insegni a pilotare un Meccanostruzzo, $C, devi essere $Gosannato:osannata; presso gli gnomi degli Gnomeregan Exiles."
S["0093f24d"] = "Fuggite, prima che sia troppo tardi!"
S["0097d1b6"] = "<Il cavallo da guerra raspa il terreno, e al movimento tremolano le fiamme empie che gli avvolgono lo zoccolo scheggiato.>"
S["00a927b0"] = "<Mentre ti avvicini, questo raptor fa schioccare le fauci verso di te e ti mostra denti lunghi e affilatissimi. Poi ti ringhia contro, con un lampo di sfida negli occhi intelligenti. Sembra compiaciuto che tu non ti volti subito a scappare.$B$BTi fissa con i grandi occhi dorati, e hai l'impressione che ti stia valutando. Il raptor batte sul terreno i lunghi artigli a falce, con uno strano ritmo. Con uno sbuffo, il raptor abbassa la testa verso di te e fa ticchettare i denti.$B$BLa tua ferocia sembra aver fatto colpo su questo raptor, che ti accetterà sia come $Gamico:amica; sia come $Gcavaliere:cavallerizza;.>"
S["00c0626b"] = "Athrikus venne da noi. Ci disse che poteva salvarci. Lanciò su di noi un incantesimo per proteggerci dal male."
S["00c5ac97"] = "Correte, piccoli. Correte a dire ai vostri padroni che Eranikus è venuto a radere al suolo il loro mondo."
S["00c80e9c"] = "Sembri $Gsmarrito:smarrita;. Posso aiutarti."
S["00c97fdb"] = "Figli della Notte, rispondete al richiamo della vostra Regina!"
S["00d3fe63"] = "$GBenvenuto:Benvenuta; alla Lion's Pride Inn. Fai come se fossi a casa tua!"
S["00dcae7e"] = "Sì, Alta Sacerdotessa!"
S["00dffbef"] = "Tutto il materiale necessario per il contributo dell'Alleanza allo sforzo bellico è stato raccolto, $C. Attendiamo che i lavori dell'Orda siano ultimati, e poi passeremo al trasporto del materiale bellico a Silithus."
S["00e811c3"] = "E se faccio così?!"
S["00ed440d"] = "Beh, qualunque cosa sia, funziona benissimo!"
S["00fd8e1c"] = "È ora di affrontare la vostra ultima prova, giovani guerrieri! Preparatevi al combattimento più duro finora."
S["00fe32a9"] = "Se desideri apprendere l'arte dell'Erboristeria, devi andare a Thunder Bluff. Da Bloodhoof Village segui la strada verso nord e prendi l'ascensore fino in cima all'altura. Lassù potrai chiedere altro aiuto a un Bluffwatcher."
S["01092fd5"] = "Queste gare sono una grande occasione per mettere in mostra il nostro ingegno!"
S["011255e5"] = "Mentre gli spargi addosso la polvere, gli occhi di Metzen si illuminano di una gioia da renna. Scuote le corna verso di te e tira un profondo sospiro, a quanto pare di sollievo.$B$BIntorno a te l'energia magica comincia a salire. Pare che stia per succedere qualcosa!"
S["01153a36"] = "Sfoglia il mio catalogo, $N."
S["0118b153"] = "Molto interessante!"
S["0123206e"] = "%s torna da $N."
S["0128696d"] = "Stai indietro e... trattieni il fiato. Era un po' che non lo facevo."
S["012bd24e"] = "Le stalle sono di nuovo piene! Presto la nostra cavalleria sarà in sella!"
S["0136182e"] = "Se ti interessa cucire il cuoio, sei $Gcapitato:capitata; proprio nel posto giusto: Faldron e Telonis sono veri artisti, e spero di imparare molto da loro."
S["0138ec36"] = "AIUTO! SONO ARRIVATI DEGLI ASSASSINI PER UCCIDERMI!"
S["0153c329"] = "Un'abilità preziosa il First Aid è. Come si fa te lo può mostrare la nostra istruttrice, Nissa Firestone: cercala presso l'Ironforge Physician, sul lato sud di The Great Forge."
S["0155ec16"] = "Io, Arynia Cloudsbreak, ho ricevuto l'incarico di proteggere la sacralità dell'Oracle Grove."
S["0157f0f1"] = "Salute, $N! Hai fatto bene a venire da me. Siamo pronti a lanciare un assalto via terra attraverso il Field of Strife! Appena il Warmaster Garrick riceverà i suoi ordini, lui e i suoi predoni si apriranno un varco nell'Alleanza!$B$BVuoi consegnare tu quegli ordini, $N? Garrick aspetta nel Field of Strife..."
S["01582c6d"] = "Salve. Sono Chronos — Colui Che Non Dimentica Mai. La mia memoria non ha difetti, è esatta fin nel minimo dettaglio.$B$BFidati."
S["015b733f"] = "È bello avere di nuovo una casa, dopo tanti anni di battaglie e di schiavitù."
S["015fb858"] = "L'Alleanza ha preso la segheria!"
S["0163b748"] = "A quanto pare l'amore l'hai già trovato. Un love token puoi anche darmelo, ma da me non avrai niente di carino: aspetto qualcuno di speciale."
S["01655c8f"] = "%s ascolta il rapporto di $N..."
S["016b1329"] = "I mortali sono caduti! La nuova era della legione Blackrock è vicina!"
S["01760926"] = "Dolce, dolce abbraccio... prendimi..."
S["0177c735"] = "Davvero glorioso, Maltrake. Sembra che il mio piano abbia funzionato alla perfezione. Non trovi, mortale?"
S["017be4a1"] = "Picchiare un martello su un'incudine non fa di te un fabbro. Dammi quello e lascia che ti insegni qualcosa prima che ci faccia fare brutta figura a tutti."
S["018b49d3"] = "Hai bisogno di aiuto?"
S["018c8298"] = "Mi dispiace, $C, ma per entrare nelle Darkspear Islands non sei ancora abbastanza $Gesperto:esperta;."
S["018db999"] = "Tremate di paura, cani! Sono qui!"
S["018dd46e"] = "Iuuu, si parte! Tutti hanno raccolto tutto, e proprio ora viene trasportato in zeppelin a Silithus. L'ultimo carico dovrebbe arrivare lì in meno di un giorno. Una volta arrivato tutto e ricomposto lo scettro, la guerra contro quegli sporchi insetti potrà cominciare. Come si dice: \"Spediscilo!\""
S["018e9847"] = "BORGOSCURO... HO FAME!!"
S["019701cb"] = "Buonanotte, amici miei. A domani."
S["0197f0cb"] = "Se vuoi sapere come la penso, Grif passa un po' troppo tempo con gli animali. Ma la via del cacciatore non la conosce nessuno come lui. Cercalo fuori dalla fucina di Kharanos."
S["019c633b"] = "E allora il tauren disse: '33 CENTIMETRI!'"
S["019ce6eb"] = "%s sussurra freneticamente qualcosa a Shakes O'Breen."
S["01a17e13"] = "Avete combattuto duramente per invadere il regno del falciatore."
S["01a6cc60"] = "Burp! Tesoro, era davvero buono. Non solo sai pescare un pesce, ma sai proprio come cucinarlo."
S["01a8110b"] = "È come si dice: tale padre, tale figlio. Hai la volontà debole quanto Tirion... forse di più. Posso solo sperare che i miei assassini abbiano finalmente posto fine alla sua vita miserabile."
S["01aa08e4"] = "%s studia il cerchio di pietre, in cerca di segni di cedimento."
S["01aa1f94"] = "La tua sfida è fallita!"
S["01ba2062"] = "Le tempeste maledicano questi fanatici dell'Al'Aketh!"
S["01ba504c"] = "Hai sentito quella dell'ogre, del goblin e del $R?"
S["01c1ddad"] = "Nel tempo prima del tempo, quando il mondo era ancora nella sua infanzia, una battaglia fra un Titano e un essere di malvagità e potere inimmaginabili infuriò proprio su questo suolo. La profezia non è chiara sul fatto che il Titano sia stato sconfitto o meno in questa battaglia, ma mostra che un Titano cadde. Anche un Old God era caduto — o almeno così si credeva."
S["01d70d16"] = "Ehi mon, che posso fare per te?"
S["01e1a8db"] = "Cercate rifugio a Hearthglen! È la nostra unica speranza!"
S["01e527e3"] = "Farò una fortuna con queste corna, $N. Grazie!"
S["02081ee5"] = "Prima Westfall, poi tutta Stormwind!"
S["020b7468"] = "Un'oscurità mi era calata sugli occhi, ma tu mi hai strappato al mio sogno empio. Mi hai salvato, $N.$B$BE ora ti supplico... di perdonarmi."
S["020ce643"] = "Per cercare le erbe servono sia conoscenza sia istinto."
S["020e36c2"] = "Sono stato evocato! Venite alla mia tenda, intrusi, e affrontate la morte!"
S["02100c6e"] = "Sta' $Gattento:attenta;, $C. Qui intorno ci sono dei cultisti."
S["0210faee"] = "Mmm... quello che devi imparare è un po' troppo per me. Parla con Sellandus alla Larson's Clothiers, poco più su lungo il sentiero, sulla destra. È lui che mi ha insegnato tutto quello che so!"
S["021369bf"] = "No... non ti puoi sedere in braccio a me."
S["0213b5db"] = "Non ci cascherò mai, sciocco! Se vuoi una battaglia, sarà alle mie condizioni e nella mia tana."
S["0213c776"] = "<Demitrian ride.>$B$BCome ricompensa avrai una morte rapida e dolorosa, $Gsciocco:sciocca;!"
S["021b7c57"] = "Innkeeper Renee la trovi nella Gallows' End Tavern, all'estremità sud-est della strada che attraversa il paese."
S["021d02f4"] = "Le tue conoscenze sono insufficienti. Torna da me quando la tua abilità nella fusione sarà cresciuta!"
S["02206d93"] = "Certo che posso aiutarti con l'addestramento. Non sono ancora un maestro, ma qualcosa da insegnarti ce l'ho di sicuro."
S["02242038"] = "Ehi, calma, $C, Pele'keiki pensare che tu non sapere che tutta quella roba essere in viaggio verso Silithus. A Pele'keiki avere detto che l'ultima parte arrivare là fra pochi giorni, e dopo qualche sciocco sconsiderato suonare il gong fuori dai cancelli di Ahn'Qiraj per aprirli e cominciare la guerra."
S["022654d6"] = "Ma cosa vuol dire allergico? E cosa c'entra con i miei gattini?"
S["022d34a9"] = "Drek'Thar è il capo militare e spirituale del Frostwolf Clan ad Alterac, e guida i suoi fratelli dalla Frostwolf Keep.$B$BSe verrà sconfitto, le forze dell'Orda ad Alterac crolleranno.$B$BDrek'Thar è stato ucciso."
S["023617dd"] = "A me sembra morto. Così non ci serve a molto. Faresti meglio a tornare indietro e a dire a Krog cos'è successo."
S["023c75dd"] = "Staffron..."
S["023ef101"] = "Presto, giovani. Presto arriveranno gli eserciti dell'Orda. Marceremo. Marceremo fino ai cancelli maledetti e schiacceremo chiunque ci sbarri la strada. Che sentano la potenza di Kalimdor!"
S["024e9e01"] = "La volontà del padrone è compiuta."
S["02634721"] = "Quando sono risalito dalla tomba scavando con le unghie, pensavo che la mia famiglia mi avrebbe accolto a braccia aperte. E invece mi hanno cacciato dal villaggio, urlando in una lingua che non riuscivo più a capire."
S["026597d0"] = "Il nostro oscuro padrone ha notato i tuoi giochetti, e mi manda a portarti un messaggio... di sventura!"
S["0269dfb3"] = "La West Frostwolf Tower è stata distrutta dall'Alleanza!"
S["0271284e"] = "L'entrata ai Whelgar's Excavation Site si trova nella valle meridionale delle Wetlands. Una caverna lungo la cresta montuosa occidentale segna il passaggio."
S["0275cb98"] = "%s emerge dall'oscurità, $Gattirato:attirata; fuori dal divination scryer!"
S["0278bb6b"] = "Aiuto! Io e la mia banda siamo stati catturati dai troll, e ci vogliono sacrificare!$B$BTiraci fuori di qui e ti darò tutto quello che vuoi."
S["02936c5d"] = "Il padrone mi vendicherà!!"
S["029526bb"] = "Voglio un attacco chirurgico, Slidore. Tappezza la strada di fuoco!"
S["02962885"] = "Anello centrale. Tu vai!"
S["029c5fcf"] = "Sempre un'abilità utile da avere, la Sopravvivenza è.$B$BÈ Kaerbrus che stai cercando. Di solito si trova vicino al pozzo lunare, in The Park."
S["02a17e0a"] = "Il buon dottore salva la situazione! URRÀ!"
S["02a40f17"] = "Master Nesingwary ha davanti una grande caccia. Aiutarlo a prepararsi per una giornata nella giungla mi rilassa molto più che prepararlo a combattere. Anche se di quei momenti gloriosi sul campo di battaglia, qualcuno mi manca."
S["02a5c4c0"] = "Il Maestro è molto interessato alla tana di Nefarian. Se solo qualcuno sconfiggesse il drago e i suoi servitori, e poi andasse a raccontare la storia al Principe. Scommetto che allora gli si scioglierebbe la lingua. Si potrebbe ritrovare The Ashbringer!"
S["02ac4cee"] = "Gli ippogrifi di Vesprystus ti porteranno in fretta dove devi andare. Cercalo a Rut'theran Village, oltre il portale nella parte occidentale di Darnassus."
S["02ac8b35"] = "Cosa non darei per trovarmi nelle vaste pianure, in una giornata come questa... ma il dovere mi trattiene."
S["02b786d7"] = "Ahimè, ho chiacchierato abbastanza. Se capiti dalle parti del porto di Valanaar, cerca la mia apprendista Ayessa Dawnsinger. Il canto lo sente ancora — anche se solo debolmente. Io sono vecchia, e gran parte del mio potere mi ha abbandonata. Ayessa è il futuro del nostro popolo e la via che ora dobbiamo percorrere per sopravvivere. Tocca a lei e ai giovani skyborne come te portare avanti le speranze della nostra gente."
S["02bbce39"] = "Addio, vecchio amico... Addio..."
S["02c922bf"] = "Silenzio! Di questa lezione non posso permettermi di perdere nemmeno un istante!"
S["02cefab9"] = "No! I faerie dragons non ce la fanno, $N! Devo tornare da Jer'kai per assicurarmi che non l'abbiano trovata. Che Elune sia con te."
S["02d68759"] = "È caduto un difensore!"
S["02e19529"] = "%s si volta verso di te."
S["02e82e64"] = "Non bastano un braccio grosso e uno sguardo cattivo per essere $Gun:una; $C. Ti servono anche la mente lucida e l'occhio acuto, se vuoi restare $Gvivo:viva;.$B$BE neanche l'alito cattivo guasta."
S["02f2bd14"] = "Saluti, $N. Io sono Myolor Sunderfury, il custode della Great Forge."
S["02f94d89"] = "Molto bene, allora. Il tempo non gioca a nostro favore, quindi dobbiamo prepararci. Grazie a tutti per l'aiuto. Zephras è in debito con voi."
S["030b3d7a"] = "Sì, $Gfratello:sorella;, come posso aiutarti?"
S["030dc47b"] = "Awa pawene tihikea shte shte balo!"
S["031bd060"] = "Elder Rumblerock passa gli anni in una grotta in cima al Dreadmaul Rock, nelle Burning Steppes."
S["031dd5e1"] = "Mi pare che Simone ti cercasse poco fa, $N. Le hai già parlato?"
S["03289dff"] = "L'Irondeep Mine si trova in territorio dell'Alleanza, a nord dello Stormpike Graveyard.$B$BÈ controllata dall'Orda."
S["032c6fb3"] = "%s si inchina."
S["03354ba8"] = "Ehi, $C! Pare che l'Orda abbia raccolto l'ultima parte della sua roba, e ora la loro e la nostra vengono spedite a Silithus proprio mentre parliamo. Mi dicono che arriverà lì in meno di un giorno, e poi qualcuno potrà suonare quel grande gong vicino alle porte di Ahn'Qiraj per far cominciare la guerra."
S["033b0082"] = "Brother Wilhelm di solito lo trovi nel retro della fucina, che si scambia storie con Lyria. Con i compagni paladini è sempre pronto a insegnare nuove abilità."
S["034108b4"] = "Lo Stonehearth Bunker è stato distrutto dall'Orda!"
S["0341ac37"] = "Salute, ragazzo. Io sono Grelin Whitebeard. Mi trovo qui per valutare la minaccia dei troll, che nella Coldridge Valley si fanno sempre più numerosi. E cosa ho scoperto? C'è un po' da preoccuparsi..."
S["0343a554"] = "Ora sono io quello che si sente grezzo: sinceramente non credo di avere più niente da insegnarti. Ma sai chi può farlo? Bengus Deepforge a Ironforge, quello sì che è un nano che conosce l'acciaio. Vai a cercarlo a The Great Forge di Ironforge e vedi se ha voglia di prendere un nuovo allievo."
S["0344a9e0"] = "Cho'Rush morire! ORA TU MORIRE!"
S["0345a0e9"] = "%s muore."
S["03473790"] = "Da me trovi le carni più pregiate di Orgrimmar."
S["034c5384"] = "Fantastico! Ma che $Ggran lavoratore:gran lavoratrice;, eh? Su, che ne dici, cominciamo?"
S["03566660"] = "Sarei lietissimo di assisterti nei primi passi del tuo percorso! Prendo la trottola e partiamo..."
S["035a88ec"] = "Hai visto cosa ho fatto? Se non sei $Gsicuro:sicura; della tecnica per eseguire il /salute, esercitati con me. Se esegui correttamente il /Salute Infranto, ti darò la risposta corretta."
S["035e8709"] = "Cieco io posso essere, ma visione io ho.$B$BCon cacciatori e ladri io tratto, più che con altri, $R."
S["03710033"] = "Grazie per questo rapporto, $N. Ora è chiaro che dobbiamo intensificare le pattuglie vicino a Theramore."
S["037e372f"] = "%s fa centro!"
S["037f99b7"] = "Troveremo l'origine dell'Incubo grazie ai frammenti che hai raccolto, $N. Da lì trascineremo Eranikus attraverso un varco nel Sogno. Preparati, $C. Stiamo invitando l'incarnazione dell'Incubo nel nostro mondo."
S["0385666f"] = "Era volere di Ragnaros che Obsidion fosse costruito. Obsidion distruggerà gli orchi di Roccianera in Blackrock Spire e ci riunirà ai nostri fratelli nelle profondità di fuoco."
S["03857bd6"] = "Ehilà, $Gamico:amica;! Ti darei volentieri un riding ram, ma prima dovresti addestrarti con Ultham, laggiù. Queste robuste bellezze non si lasciano cavalcare facilmente, ma una volta che avrai imparato a cavalcarne una, non troverai compagno migliore."
S["03873137"] = "Sei $Gnuovo:nuova; da queste parti? Be', allora dimmi cosa stai cercando."
S["038c8f77"] = "Una meravigliosa Feast of Winter Veil a te! E per cominciarla col piede giusto, ci sono le leccornie di Smokywood Pastures!"
S["038d8e4f"] = "È giunto il momento che Orda e Alleanza guardino a nord e all'invasione dello Scourge. Negli ultimi giorni, territori in tutta Kalimdor e negli Eastern Kingdoms sono stati attaccati. Prenderai le armi per salvare la tua terra dalla distruzione per mano loro?"
S["039bfc0f"] = "Segnalata attività dei Defias all'orizzonte sulla costa. Tutto tranquillo a Sentinel Hill."
S["039c290a"] = "Disperate, mortali! La vostra fine è giunta!"
S["03a19e25"] = "Fu il vostro comando a manipolare un figlio in lutto perché cercasse di recuperare la spada. Un figlio diventato un uomo con nient'altro che vendetta e odio nel cuore! E per cosa? Non siete più vicini alla spada adesso di quanto lo foste cinque anni fa."
S["03a92b89"] = "Ahh sì, ora ricordo, era la tua prima notte di nozze, vero?"
S["03b614a1"] = "Pane fresco, sfornato stamattina."
S["03b980ab"] = "Muoviamoci. La mia roba dovrebbe essere nel magazzino, da questa parte..."
S["03bed4d6"] = "La Tower Point è stata presa dall'Orda!"
S["03ca266d"] = "I ficcanaso pagheranno per la loro intromissione. Ritiratevi nelle ombre!"
S["03d381b5"] = "Sarai un sacrificio perfetto!"
S["03d381c2"] = "Sarai un sacrificio degno."
S["03d5426c"] = "%s annuisce."
S["03db0850"] = "Chi controlla l'Iceblood Tower?"
S["03de61da"] = "Narain Soothfancy, al tuo servizio! Ingegnere in pensione e maestro indovino! So predirti il futuro prima ancora che succeda!"
S["03e188c0"] = "Non ce la farò... andate... andate avanti senza di me..."
S["03e914f6"] = "Non dare ascolto ai cuori del mondo — la risposta è dentro di te. La verità la conosci."
S["03ec05d3"] = "Hai trovato una chiave? Beh, è LA chiave? Voglio dire, è la chiave che apre queste catene? Beh, $Gsignore:signora;, c'è un solo modo per scoprirlo!"
S["03ed302c"] = "Saluti, sono l'Arcimago Alvareaux e mi occupo dei rifornimenti e della logistica del Kirin Tor.$B$BPurtroppo, per ora abbiamo piuttosto pochi oggetti utili da distribuire ad amici e alleati.$B$BTi consiglio di ripassare spesso: di tanto in tanto le scorte possono cambiare."
S["03f8074e"] = "Questo è un posto pericoloso, $N. Fai attenzione qui intorno."
S["03f96568"] = "Ho montato un dispositivo nuovo nel regolometro di matrice della nostra auto. Il quoziente di velocità dovrebbe salire di un fattore di almeno quindici!"
S["03fe04b3"] = "%s si attiva!"
S["04060e43"] = "%s prende la mira con più attenzione..."
S["040780e8"] = "Eh? Cosa essere?"
S["0408cdf4"] = "Antichi, guidate la mia mano... Svegliatevi dal vostro sonno! SVEGLIATEVI E SIGILLATE QUESTO LUOGO MALEDETTO!"
S["040fcc81"] = "Oh cielo, sono pericolosamente a corto di scorte! Ma quanto ci mette quel dannato goblin?"
S["041135e0"] = "Come posso aiutarti, $Gsignore:signora;?"
S["0411ef02"] = "Betsy! Ridammi Betsy!"
S["041360ae"] = "Hai fatto tutto quello che ti ho chiesto, $N, e qui per te non c'è più niente. Se vuoi continuare la tua carriera da agente della Thorium Brotherhood, va' a parlare con Lokhtos Darkbargainer al Grim Guzzler, nei Blackrock Depths.$B$BAddio!"
S["041e9180"] = "Se desideri una banca, il tuo viaggio ti porterà nel cuore di Darnassus. Là troverai un luogo dove custodire i tuoi tesori."
S["042e141c"] = "Incredibile! Mi sento... rinato. La forza mi ritorna!"
S["043a248f"] = "%s striscia nervosamente fuori dalla cassa."
S["04413010"] = "<Lady Sylvanas Windrunner ti osserva in silenzio.>"
S["04502dd2"] = "Perché scappi da me, Fluffy?"
S["046241ca"] = "Re O far tiras tiras vil aldonoth. Wirsh lon dana vil algos vrum hir ko far re vil ewiddan."
S["0468be06"] = "Oh oh! Io me la squaglio!"
S["0469d054"] = "<Omarion borbotta qualcosa sottovoce.>$B$BMa certo che posso aiutarti, $Gcaro ragazzo:cara ragazza;. È il mio ultimo desiderio... la mia volontà finale. Ti prego, prendi questo manuale. Le informazioni nelle sue pagine sono una raccolta di tutto ciò che so e che ho imparato negli ultimi 30 e passa anni della mia misera vita. Consegna il manuale a quel buono a nulla del mio apprendista, che probabilmente se ne sta seduto sul suo grasso sedere alla Cappella della Speranza della Luce."
S["0473a85c"] = "Elder Stonefort si è spostato nelle segrete di Blackrock Spire."
S["047e2946"] = "Troppo poco, troppo tardi. La diga è crollata. Nella migliore delle ipotesi siamo un intoppo sulla strada."
S["04829f13"] = "Se cerchi un cacciatore, ti conviene andare da Dazalar: di solito sta appena fuori dalla Locanda di Dolanaar."
S["0487b646"] = "È un onore conoscerti, $N, ma con le pozioni sei più abile di me. Va' nell'Apothecarium of the Undercity da Doctor Herbert Halsey, un non morto: d'ora in poi potrà aiutarti lui."
S["048d7772"] = "Secondo te ci sono pesci qui dentro?"
S["048df07d"] = "Nell'Arathi Basin abbiamo bisogno di aiuto più di quanto si possa immaginare, $N, ma in un momento come questo lì si possono conquistare altrettanto onore e reputazione. Ti supplico: cerca in città il maestro di battaglia dell'Arathi Basin."
S["049a77cc"] = "Ecco il sentiero per uscire da Un'Goro! Ce l'abbiamo fatta! Ora dobbiamo preoccuparci solo del deserto di Tanaris."
S["049f55b3"] = "Uccideteli, fratelli miei! Per lo Scourge!"
S["04a0adf5"] = "'Giorno, amici miei."
S["04a781de"] = "Sono felice che tu me l'abbia chiesto! Siamo molto più di un semplice servizio di consegne, $N. Assumiamo artigiani di ogni specialità e mestiere, o li prendiamo a contratto, e teniamo le orecchie ben aperte per cogliere ogni nuova occasione per dar loro lavoro e far circolare le merci. Non possiamo certo prevedere i bisogni che di volta in volta avranno i potenziali clienti, perciò dipendiamo dagli ordini di lavorazione che ci mandano.$B$BCome puoi immaginare, questo sistema è... meno efficace di quanto speravamo. Invitiamo tutti gli artigiani a soddisfare queste richieste e a consegnare la merce direttamente ai clienti, ovunque si trovino. Non preoccuparti, sarai $Gricompensato:ricompensata; equamente per il disturbo e ti guadagnerai il rispetto della nostra organizzazione."
S["04ae6cec"] = "Il pesce e tutto il resto sono in viaggio verso Silithus, e dovrebbero arrivare lì in pochi giorni. Dopodiché qualcuno dovrà suonare quel gong con lo Scepter of the Shifting Sands per dare inizio alla guerra."
S["04b97759"] = "<Dei paroloni tecnici di questa pergamena non riesci a capire niente.>"
S["04bc5729"] = "Ah! Buongiorno, buongiorno, $GMastro:Madonna; $C! Vieni, siediti a bere qualcosa. Hai uno sguardo intraprendente, e credo che scambiare due parole con me ti converrà..."
S["04bcc36b"] = "Hai distrutto troppo del mio lavoro! Preparati a raggiungerli nella Distorsione Fatua!"
S["04c08683"] = "Vivranno, se non altro per vedere i frutti del loro lavoro: la distruzione e il caos che di certo seguiranno quando la legione di Roccianera invaderà la gola."
S["04c7e901"] = "<Sei $Gesperto:esperta; di come è costruito questo robot e di come funziona.>"
S["04c7ecf3"] = "Sono $Gpronto:pronta;, Remulos."
S["04c9e42f"] = "Carote tutti i giorni per un anno se ti fermi!"
S["04cf4255"] = "Alla carica!!! Infilzateli!"
S["04d2fabd"] = "Ti aspetto."
S["04d6ad34"] = "Salute a te, $N. Desideri che ti aiuti a raggiungere la Warsong Gulch?"
S["04e38976"] = "Con un rigoroso riaddestramento ho dovuto far dimenticare a molti allievi tutto quello che avevano imparato, per poterli istruire da capo. Ogni volta che offro questo servizio diventa più difficile, e per questo ogni riaddestramento costa più del precedente. Vuoi che ti faccia dimenticare i talenti che hai imparato?"
S["04e40481"] = "Questo luogo è sotto la mia protezione. I misteri dell'arcano resteranno inviolati."
S["04ec858b"] = "Non sei ancora abbastanza potente, $C. Circola."
S["04ee406c"] = "A Kharanos i Thunderbrews hanno un'ottima Locanda che porta il loro nome. Fai un salto lì per una pinta e un po' di riposo."
S["04f3f18d"] = "Shì, è vero, shono cieco come una talpa! E ubriaco come un... ehm, ubriaco come qualcosa che shi ubriaca.$B$BTe lo dico io, $R: è il bere che mi tiene i shenshi affilati. Lo shanno tutti che quando perdi un shenso, gli altri diventano più attenti. E di questi tempi il mio shenso da ubriaco è incredibile."
S["04f928c3"] = "La tua anima è mia, $Grammollito:rammollita;."
S["04fa0ae1"] = "Segnalata molta attività di gnoll nella Gold Coast Quarry e nella Jangolode Mine."
S["0510b938"] = "I barili sono pieni di birra forte! Bevi e festeggia, $Gamico:amica;!"
S["051ccbd1"] = "Lascia in pace un vecchio spirito, ti prego."
S["051fc79d"] = "La gara de The Drag comincerà fra 1 minuto!"
S["0523a092"] = "Mostro! Affronta la potenza di Cenario!"
S["05263193"] = "Non posso farlo. Lo sai che fine fanno i disertori. Posa il fucile e vieni con le buone... oppure no. Sulla taglia c'è scritto \"vivo o morto\", e con te ho ancora un conto in sospeso per Ratchet."
S["05290565"] = "%s balza fuori per difendere il suo alveare!"
S["052f832e"] = "Sono stato meglio. Ivar the Foul ha avuto la meglio su di me..."
S["053487ac"] = "Lo Syndicate è un branco di dilettanti — disorganizzati, incapaci e pigri..."
S["053602fa"] = "Dall'aria, sei il tipo con cui è meglio tenere d'occhio il borsellino. Ti serve qualcosa?"
S["0542b207"] = "Questi attacchi incessanti dello Scourge non finiranno mai?"
S["0548f5ef"] = "State indietro, vili creature!"
S["054aecd7"] = "Avanti, miei servitori! Avanti! Che nessuno ci sbarri la strada!"
S["054b030b"] = "Ehi là, $Gviaggiatore:viaggiatrice;! Sei $Gnuovo:nuova; in città? Be', quando ti sarai $Gsistemato:sistemata;, passa da me se ti serve un lavoro. Sto facendo gli straordinari per preparare la Festival of Winds, e per tenere piene le dispense ogni aiuto è ben accetto!"
S["0553f2f2"] = "Salute a te, $C!"
S["057b0d41"] = "Ho sentito dire che tra poco il nuovo Henweigh 6000 uscirà dalla catena di montaggio. Non sto più nella pelle!"
S["057f11f5"] = "%s ruggisce verso Terenthis per attirare la sua attenzione."
S["0586600e"] = "Kar Aman, $N. Hai l'aria di $Gun:una; $C forte — ma da queste parti ti conviene stare $Gattento:attenta;. Chi tocca cose di cui non sa nulla o manca di rispetto ai più anziani si merita una giusta punizione.$B$BPuoi anche non rispettare me o i miei compagni, ma se sarai tanto $Gsciocco:sciocca;, il nostro potere imparerai a rispettarlo.$B$BOra, basta con i convenevoli: posso fare qualcosa per te?"
S["058c387c"] = "Oh, allora cerchi Springspindle Fizzlegear. Ah, quel piccolo gnomo con i suoi aggeggi... Dammi retta: se vai nel suo negozio a Tinker Town, tieni le mani a posto e non accarezzare nessuna delle sue pecore meccaniche!$B$BPecore esplosive... ma a chi verrebbe in mente di costruire una cosa del genere!?"
S["058c498f"] = "Argh!"
S["058fb3cf"] = "Hai dimenticato la divisa da studente? Per te la moda conta più del dominio dello Scourge?"
S["059a6df6"] = "Forza, fila a Orgrimmar, $N!"
S["059df2f1"] = "Prima che io possa aiutarti devi imparare alcune cose fondamentali. Parla con il mio apprendista, Vhan: è gentile e paziente, e ti insegnerà quello che ti serve sapere."
S["059e36cf"] = "Nella più buia delle notti, confida che la luce ti protegga. Certo, anche una bella mazza robusta non guasta."
S["059f37e1"] = "Lodata sia la Madre Terra per questo dono."
S["05a28a3b"] = "Noi dell'Orda abbiamo fatto tutto il possibile per prepararci alla guerra imminente ad Ahn'Qiraj. Ora aspettiamo, $C, che l'Alleanza faccia lo stesso. Quando avranno finito, trasporteremo tutti il nostro materiale bellico alla Cenarion Hold, in Silithus."
S["05a68778"] = "Sei qui a combattere per noi nella Warsong Gulch? Lok'tar Ogar, $C!"
S["05a6d676"] = "Tiratelo fuori di lì!"
S["05ab10a9"] = "Sei oltre il mio livello di competenza. Georgio Bolero, il maestro dei Duncan's Textiles dietro l'angolo, potrebbe aiutarti a migliorare."
S["05b0e374"] = "Io non scappare da $Gun:una; $C come te!"
S["05b16182"] = "Ehilà, $C, non lo sai? L'Orda ha finito di raccogliere tutto. Stiamo solo completando gli ultimi preparativi, mentre aspettiamo che l'Alleanza finisca la sua raccolta. Poi sarà ora di spedire tutto in Silithus per la guerra."
S["05b1f264"] = "Hai un'abilità eccezionale nella forgiatura, $N. Ora è il momento di decidere. Davanti a te ci sono due vie: quella del forgiatore di armi o l'arte del forgiatore di armature.$B$BTi avverto: una volta scelta la via a cui dedicarti, non potrai più tornare indietro. Ognuna richiede una disciplina che non lascia spazio agli ibridi."
S["05b21c21"] = "$GBenvenuto:Benvenuta; a Booty Bay, socio. Spero che il soggiorno nella mia città sia piacevole e tranquillo — soprattutto tranquillo. Se hai sete, da bere ce n'è in abbondanza; se sei $Gagitato:agitata;, ci sono buttafuori in abbondanza.$B$BAllora... cosa può fare per te questo umile servitore dello Steamwheedle Cartel? O meglio ancora — cosa puoi fare tu per me, eh?"
S["05b292e3"] = "Ding!"
S["05b54cdf"] = "FATTO!"
S["05b9338d"] = "Atten-ti! Tutto il materiale bellico per Ahn'Qiraj è stato registrato ed è in viaggio verso la Cenarion Hold, $Gsignore:signora;! Mi dicono che l'ultimo carico dovrebbe arrivare a giorni. Una volta fatto questo, e quando qualcuno avrà suonato quel gong laggiù per aprire i cancelli, vi garantisco che daremo a quegli insetti una battaglia con i fiocchi!"
S["05c2ee8b"] = "Bene, adesso firmo i mandati. Portateli qui davanti, vermi."
S["05c758db"] = "%s bacia il suo amato."
S["05c96799"] = "L'eroe in erba è tornato! È bello rivederti, $N. Nel nostro villaggio sei sempre $Gil benvenuto:la benvenuta;."
S["05cadbd9"] = "Ahah! La vendetta è mia!"
S["05caddbe"] = "Ho finito le armi, $N."
S["05cb1806"] = "Cadete!"
S["05cb8961"] = "Non posso immagazzinare altre provviste. Ne ho quante ne posso gestire!"
S["05cd70ce"] = "Lo Staghelm piagnucolerà e implorerà per la sua vita, proprio come il suo cucciolo di figlio! Mille anni di ingiustizia finiranno oggi!"
S["05d09148"] = "Mi sembri $Gun druido:una druida; a cui farebbero comodo un bicchiere e un orecchio pronto ad ascoltare."
S["05d3193e"] = "Porterò le tue interiora come collana."
S["05d833a7"] = "In una fredda giornata a Dun Morogh non c'è niente di meglio di un po' di infuso mattutino bollente per cominciare col piede giusto!"
S["05d9cfcc"] = "Ve lo dico io, la Great War non mi manca per niente. Mi ricordo quando abbiamo combattuto a Darrowmere: tutta la notte sdraiati in una trincea piena di fango, in mezzo alla nebbia."
S["05deaf2f"] = "Prendi questo! I Baffosecco vinceranno!"
S["05e31f37"] = "[Dopo la tua domanda c'è una pausa evidente.]$B$BLe informazioni che richiedi non sono al momento disponibili nel ciclo dei dati di questo archivio. Mi scuso sinceramente per questa omissione.$B$BRipeti la richiesta quando il ciclo dei dati di questo archivio di informazioni sarà stato aggiornato. Puoi anche rivolgerla a un altro archivio di informazioni che si trova su Azeroth."
S["05e5907b"] = "Di questi tempi, grazie ai montanari, Menethil Harbor si gode un po' di pace. Ma non possiamo mai abbassare la guardia contro le nuove minacce dei nostri nemici."
S["05e7480d"] = "Alt."
S["05e91900"] = "Aiuto!"
S["05ebcb49"] = "Hm..."
S["05ed1a3b"] = "Ti prego, non disturbarmi... Quelli come te sono tutti uguali..."
S["05fc43cc"] = "Attenzione! Attenzione! Allarme intrusi! Allarme intrusi!"
S["06049470"] = "Bene, squadra. Mettetevi al lavoro e installate queste ossa."
S["06153083"] = "Uccidi!"
S["06178576"] = "Mi fa sempre piacere quando qualcuno ha voglia di parlare con me. Come ti va, $C?"
S["0618887e"] = "Per servire la Dama Oscura e Varimathras dobbiamo spingere avanti il fronte contro l'Human Infestation."
S["0620c2c5"] = "A Dolanaar ci farebbe proprio comodo un altro cuoco. Bada bene, non che la cucina di Zarrin lasci a desiderare. Perché non vai a vedere cosa può insegnarti?"
S["06226d78"] = "Presto lo Scourge dominerà il mondo!"
S["06231f73"] = "Bugiardo!"
S["062f9aa1"] = "Miao!"
S["06343e70"] = "Muoviti!"
S["06395278"] = "Buon Hallow's End! Che ne dici della mia maschera? Fa tanta paura!"
S["063a8f44"] = "Ci condanneresti tutti..."
S["064642ca"] = "Ascolta le storie di un anziano, $N. Ne ho tante da raccontare..."
S["0648a507"] = "Me ancora capo di ogres. Ah!"
S["0648f4c0"] = "Capitano! Il Tenente Martelsaldo richiede la vostra presenza! Il nemico si avvicina, signore!"
S["064c200f"] = "Ofgut"
S["064c9939"] = "Remulos, vecchio amico. È bello rivederti. Sapevo che il messaggio ti avrebbe raggiunto, in un modo o nell'altro."
S["064d8712"] = "Va bene..."
S["064f7a9c"] = "Colpisce $N in pieno volto con un manrovescio."
S["0650589e"] = "Ops!"
S["065f77cf"] = "Non avete idea degli orrori che vi attendono. Non avete visto nulla! Il cuore gelido di Naxxramas vi aspetta!"
S["0661918f"] = "Ah, dev'essere lui... no? Bah!"
S["06623489"] = "Malton, zuccone!"
S["0664fbde"] = "Artefatto sacro appartiene a Blackrock! Noi riprendere!"
S["0667696f"] = "Datti da fare, prima che sostituisca quel target dummy con te e cominci un riscaldamento tutto mio!"
S["06688cd4"] = "Faccio in modo che a Sen'jin non manchino i materiali delle bestie della zona. È un compito che fa onore."
S["06709fc7"] = "Buona giornata anche a te, $Gcoraggioso:coraggiosa; $C. Lo so che cerchi una bella cavalcatura, e non c'è niente di meglio che tenere le redini di un raptor, te lo dico io, mon! Dai un'occhiata a quelli che ho da offrire — vengono dalla razza più feroce che ci sia."
S["06740439"] = "Se cerchi dei conciatori ti conviene andare a Ironforge. Se la memoria non m'inganna, vicino a The Great Forge c'è una bottega che dovrebbe fare al caso tuo."
S["067cb954"] = "Sul lato est di Bloodhoof Village c'è una grande tenda: lì ti aspetta Narm Skychaser."
S["067cd5a9"] = "%s avvolge la torre di guardia. La torre è in fiamme!"
S["067d3977"] = "Non ne posso più!"
S["06866f58"] = "Ti ricordi quando Danath radunò tutti i mercenari di Stormwind e marciammo a combattere a Nethergarde?"
S["068dbac8"] = "Per favore, addestrami."
S["068e3118"] = "Saluti, $C. Vuoi unirti al combattimento nella Warsong Gulch?"
S["069e8838"] = "Questo è il mezzo di trasporto più bello e moderno che il denaro possa costruire. Cosa? Il Deeprun Tram? Gli gnomi? Senti, $Gamico:amica;, se credi a queste stupidaggini, ho una statua giù a Stranglethorn da venderti. Allora, te la fai a piedi fino a Grom'Gol o viaggi con stile su questa splendida macchina volante? A te la scelta."
S["069ed6ed"] = "Perché proprio ora, $R? Non me lo spiego. C'è così tanto lavoro da fare..."
S["06a11f7c"] = "Uggel"
S["06a1ee61"] = "Da queste parti c'è un solo cacciatore da cui ti manderei a parlare: Grif Wildheart. Sta proprio fuori dalla fucina di Kharanos."
S["06a41ac8"] = "Ecco, Relara. Bevi questo..."
S["06a64334"] = "$N, guarda con molta attenzione quello che faccio e segui le mie istruzioni alla lettera. Se ignori le mie parole, firmi la tua condanna a morte, perché Taskmaster Fizzule conosce MOLTO bene le arti del guerriero e dell'assassino."
S["06a758ed"] = "Stupida neve... Ehi, tu sei $N, vero? Ho appena ricevuto un messaggio per te."
S["06a7cf36"] = "Voglio quegli stivali! Nessuno tocchi quel cadavere!"
S["06a8edc0"] = "Fratello mio, no!"
S["06bdadfb"] = "Cosa?"
S["06be8404"] = "Tu?$B$B<Lorax ride.>$B$BNe dubito.$B$BMe ne sto qui fra queste rovine a sognare. Sogno il giorno in cui acciufferò quel miserabile ladro di Goraluk Anvilcrack.$B$BIo e lui avevamo un patto. Un patto che lui ha infranto. Tradito."
S["06c11104"] = "EVVAI!"
S["06cbe41b"] = "Oh! Salute, $Gamico:amica;. Guarda pure la mia merce."
S["06d19fb2"] = "%s è di nuovo in pace."
S["06d5f73c"] = "Ish nu! Basta così!"
S["06d7972a"] = "L'altro giorno, nell'Hall of Arms, ho sentito per caso Regnus Thundergranite che si vantava di un nuovo trofeo per la sua tana. Se vuoi un cacciatore esperto che ti addestri, rivolgiti a Regnus."
S["06d8b965"] = "Sì!?"
S["06deb941"] = "Indietro! State lontani! All'infernale serve spazio!"
S["06eb838c"] = "La vita non ha senso. È nella morte che veniamo davvero messi alla prova."
S["06f4a0ac"] = "Non ho tempo per farmi interrompere."
S["06f9f50f"] = "La foresta brulica di worgen e ghouls. Bisogna fare qualcosa!"
S["06fd7309"] = "Chi è questo insetto che si presenta davanti ai signori del Consiglio? Un insetto che vuole farsi schiacciare, senza dubbio!"
S["06ff2f2f"] = "Qui a Dun Morogh non troverai nessuno scuoiatore, $Gragazzo:ragazza;. Se vuoi farti addestrare, per lo più li trovi a Ironforge."
S["0703c9d4"] = "Ma guarda, ciao di nuovo, $N! Non so quanto andrò avanti a provare ad aprire un negozio in mezzo al nulla. Comunque, visto che in passato mi hai aiutato, ti mostro un po' di roba che potrebbe interessarti!"
S["070834a6"] = "Se hai sentito dire che tutte le raccolte dell'Orda e dell'Alleanza sono state completate, hai sentito bene, $C. Tutti i beni per la guerra che abbiamo raccolto e preparato vengono mandati alla Cenarion Hold a Silithus, e manca meno di un giorno prima che arrivi l'ultimo carico. Dopo di che, suppongo, dovremo solo aspettare di vedere chi ricomporrà quello scettro con cui suonare il gong, che aprirà le porte di Ahn'Qiraj e annuncerà la guerra."
S["070c9d12"] = "In realtà è piuttosto semplice, $N. La Veiled Blade, la mia vecchia compagnia di mercenari, ha accettato la missione sbagliata nel momento sbagliato.$B$BA ingaggiarci è stato un contrabbandiere goblin di Booty Bay, un certo Gremnik Rizzlesprang, che bramava il libro degli incantesimi di Lord Valthalak. O forse di mezzo c'era qualche vecchia rivalità? Ormai, immagino, non lo sapremo mai: Gremnik è stato ucciso non molto tempo fa da un gruppo di spectral assassins di Valthalak. Quando si radunano in tanti, possono essere davvero letali.$B$BDov'ero $Grimasto:rimasta;?"
S["070fb1fd"] = "Il verme va sull'amo, l'amo va nell'acqua. Il pesce sta nell'acqua, il nostro pesce."
S["0719f7f9"] = "Assassini! Guardie! Guardie!"
S["07276eef"] = "%s prepara la sua siringa."
S["07390558"] = "Parlami delle torri."
S["07396be5"] = "Preparatevi al ritorno degli antichi!"
S["073c7905"] = "Una gigantesca creatura simile a un verme è appena sbucata dalla terra vicino a Hive'Ashi!"
S["074c4740"] = "Alla seconda curva passa $N!"
S["07590e4c"] = "Ah! Se incontri un sopravvissuto di Darrowshire, ti prego, digli che sono $Glibero:libera;!"
S["075a990b"] = "Come fa l'Ironforge Steam Brigade a pretendere che tenga in campo i suoi carri armati, se i rifornimenti me li manda in ritardo?!? Qui sto rattoppando queste macchine a vapore a forza di grinta e sudore!$B$BEhi! Forse puoi darmi una mano..."
S["07662711"] = "Stregoni, non dovreste giocare con una magia che non capite. Visto cosa succede?"
S["0769b184"] = "Per gli gnomi lebbrosi saltellanti! Sono rimasto bloccato là dentro per mesi. Grazie, ragazzi."
S["0777e1c9"] = "Cerchi un ladro? Credo che Jannok faccia al caso tuo. Perché non vai a parlargli alla Locanda di Dolanaar?"
S["077abba6"] = "L'istruttore di cucina lo trovi in una casetta all'estremità nord della città."
S["077b2258"] = "%s esala l'ultimo respiro."
S["077c9b65"] = "Sappi una cosa, Jackson — non sono in vena dei commenti che tu trovi carini o spiritosi. Sono qui per controllare che le ricerche dell'Arcidruido vadano avanti come previsto, e ho l'ordine di estirpare tutte le mezze calzette che non hanno la stoffa per servire nel mio amato Cenarion Circle."
S["07833f15"] = "Cassetta della Posta in mezzo a città, Trade Quarter, anello superiore... vicino a locanda."
S["07845785"] = "Nessuna canaglia di $C si prenderà il nostro bottino di Winter Veil! Prendeteli!"
S["078b7e16"] = "Conosco una druida che vive in cima alla collina sopra le Wailing Caverns, $N. Forse potrà dirti di più su questo frammento che hai trovato."
S["078fd51e"] = "Atten...TI!"
S["0790d0ed"] = "Da dove comincio? La nostra casa sta cedendo. Le protezioni sono cadute, e le tre province hanno cominciato ad allontanarsi alla deriva. Fino a poco tempo fa, dalla torre di guardia occidentale si vedevano le guglie di Shen'dramar. Ora non più. I piloni d'ancoraggio si stanno indebolendo, e se alla fine le catene si spezzano..."
S["0792750d"] = "Sono finalmente $Garrivato:arrivata; a Lakeshire — venite, venite tutti, e approfittate delle meravigliose offerte di Antonio Perelli."
S["07930a7e"] = "Vil, \"Endirvis Danavandar se vil Danagarde se Sturume.\" Nandige."
S["0795750a"] = "Ah, il buon vecchio Brandur Ironhammer. Di sicuro saprà darti i consigli che cerchi, $Gragazzo:ragazza;. Lo trovi nell'Hall of Mysteries, a nord dei cancelli di Ironforge."
S["07ac6b2e"] = "Dov'è l'acqua, Emma? Prendi l'acqua, Emma? Se non fosse per me, quelli non saprebbero nemmeno com'è fatta l'acqua."
S["07acd213"] = "Bisogna fare qualcosa per la tribù Blackwood."
S["07b33c82"] = "Goditi il resto del tuo soggiorno a Menethil. Non durerà ancora a lungo."
S["07b50342"] = "Sveglia, $Gsoldato:soldatessa;! L'Intelligence Stormpike ha riferito che un maestro ingegnere goblin è stato fatto prigioniero dai troll Winterax. I cani Frostwolf stanno cercando in tutti i modi di liberarlo, per usare i suoi congegni e distruggerci! Non permettere che accada."
S["07bb2cd9"] = "Il \"Expert Cookbook\" puoi comprarlo da Wulan, in Shadowprey Village. Se vuoi migliorare, ti servirà."
S["07bd0e5e"] = "Ah, forse vuoi cambiare i tuoi segni, o prepararti per una caccia? Non c'è posto migliore.$B$BTroverai il barbiere nella Tradesman's Terrace, vicino alla casa d'aste."
S["07bda821"] = "Esplosioni! ALTRE esplosioni! Mi ci vogliono altre esplosioni!"
S["07ceda7c"] = "Spiedini di Ratto! Venite a prendere i vostri gustosi Spiedini di Ratto! Prendeteli finché ci sono!"
S["07d5ffcc"] = "First Aid"
S["07e0a195"] = "Prima devi dimostrarmi il tuo valore, poi ti addestrerò."
S["07e1468a"] = "Be', così proprio non va. La creatura è troppo piccola. Vediamo cosa farà il terzo lotto di Keever."
S["07e8e25f"] = "%s è $Gcosparso:cosparsa; di ossa rotte e briciole di cracker."
S["07e94f27"] = "Non potete fermare la grande opera di Lorthuna! La volontà del signore del vento è compiuta!"
S["07ef87f9"] = "Sabbie del deserto, alzatevi e oscurate il sole!"
S["07f521a2"] = "%s comincia a frugare nel suo zaino..."
S["07f5708e"] = "Con sfrontatezza avete ignorato poteri che vanno oltre la vostra comprensione."
S["07ffe5e2"] = "Chi osa?! Ti distruggerò!"
S["08074c70"] = "Non ho ancora capito bene cosa sia, ma c'è qualcosa di strano nelle sorgenti termali..."
S["0808e6f6"] = "Appena trecento anni fa, un nano sconsiderato di nome Thaurissan evocò il padrone dal suo regno di fuoco. Il suo ritorno in questo misero mondo devastò le terre intorno e creò questo Nucleo vulcanico. Da allora il potente Ragnaros dorme sotto questa montagna."
S["080b5625"] = "%s si prepara al Saluto Spezzato! *FAI ATTENZIONE!*"
S["081261e1"] = "Dov'è lo Stormpike Quartermaster?"
S["0814fd1c"] = "La lezione è cominciata!"
S["08191f67"] = "Anche i demoni possono provare paura..."
S["081a117d"] = "Proprio così, ehm, ragazza, il materiale bellico sta andando tutto a Silithus, e l'ultimo carico dovrebbe arrivare a giorni. Dopo non ci resterà che aspettare e vedere quale eroina si farà avanti a ricomporre lo Scepter of the Shifting Sands e a suonare il gong sulla Scarab Dais. Solo allora la guerra comincerà ad aprire le porte di Ahn'Qiraj."
S["0825dd52"] = "La guerra è ormai vicina, $C! L'Orda e l'Alleanza hanno finito i preparativi, e proprio in questo momento tutto il nostro materiale bellico sta partendo per Silithus. Conto che arrivi tutto nei prossimi giorni. Quando sarà tutto radunato là, chi sarà riuscito nell'arduo compito di ricomporre lo Scepter of the Shifting Sands lo batterà contro The Scarab Gong e aprirà le porte di Ahn'Qiraj. E allora comincerà una battaglia come non se ne vedevano da secoli!$B$BLok'tar Ogar!"
S["082a1638"] = "Guarda caso... mi è appena arrivato un aggiornamento proprio su questo. Finora l'Alleanza ha raccolto una parte del light leather, del medium leather e delle pelli di thick leather che servono."
S["08300f63"] = "Mmh, il tuo lavoro non è male, ma è ben lontano dalla qualità che cerco in un allievo. Vai a parlare con Smith Argus a Goldshire: sono sicuro che può insegnarti le basi. Quando avrai finito, torna da me e ti farò una piccola prova per assicurarmi che tu sia pront$Go:a;."
S["08366f8f"] = "Che preda facile."
S["08423c06"] = "Questa lordura oscura fa proprio male agli affari."
S["08468687"] = "Quando sarà il momento, mia signora. Tutto sarà chiaro quando sarà il momento. Il padrone si sta già risvegliando. Guardate il cielo, perché la Brood of Nozdormu è tornata."
S["084ac8c9"] = "Aspiri a unirti un giorno alle nostre file? Sark Ragetotem può aiutarti nel cammino: lo trovi nell'Hunter's Hall."
S["085106a4"] = "Venendo da me per l'addestramento hai sprecato il tuo tempo e il mio, $N. Le basi non ho tempo di insegnarle: qui stiamo combattendo una guerra, e questa è una delle prime linee. Torna da me solo quando sarai più $Gpreparato:preparata;."
S["0854b6d0"] = "Se avessi un odore migliore, ti parlerei. Che ne dici di un'acqua di colonia? O magari di un profumo?"
S["085705a6"] = "Fatti avanti, vieni a sentire tutto sullo spettacolo più straordinario di tutta Azeroth — la Darkmoon Faire! Urrà!"
S["085fe46c"] = "Mi gira... la testa. Fa così caldo... qui... dentro..."
S["0865570c"] = "Quello dev'essere $Gil:la; $N più $Ggrosso:grossa; che abbia mai visto... e sta venendo dritto verso di noi!"
S["0876590e"] = "Dicono che a volte si trasformi in un corvo."
S["0887cc14"] = "Credi davvero di poter vincere contro gli eserciti di Kel'Thuzad? Nessun esercito dei vivi, nessun potere che tu possa schierare può distruggere le nostre file!"
S["0889269e"] = "Distruggete i registri prima che il bastione cada!"
S["088a26a2"] = "Stai facendo bei progressi. Presto avrai una bottega del cuoio tutta tua. E un aiuto mi farà piacere, $N: più veloci di così le mie mani non vanno, sai? C'è così tanto lavoro da fare!"
S["088e1121"] = "Burning Steppes — Tablet of the Seven"
S["088e43cb"] = "$GBenvenuto:Benvenuta; nella nostra umile dimora! Un volto amico fa sempre piacere. E che braccia forti che hai. Io e mio marito cerchiamo sempre qualcuno che ci dia una mano alla fattoria. Ora che la brava gente se n'è andata quasi tutta, è difficile trovare chi abbia la forza di aiutarci."
S["088ec889"] = "Non lo permetteremo mai... L'abbiamo già bandito dal nostro mondo e lo bandiremo di nuovo."
S["08906610"] = "Durante l'Elemental Sundering, il Firelord, Ragnaros, ha cercato di divorare il mio Signore, Thunderaan, Principe dell'Aria.$B$B<Demitrian china il capo, il volto contratto dalla rabbia.>$B$BSe pronunci il suo nome, decorerò questo accampamento devastato con le tue viscere. Taci e ascolta."
S["0891e648"] = "Scommetto che Josetta ti insegnerebbe volentieri qualche incantesimo nuovo. Sarà di sopra, nella sua stanza alla Lion's Pride Inn."
S["089f3bd7"] = "Narain, se hai abbastanza materiali, mi servirebbe un'altra arcanite buoy."
S["089f7e4b"] = "Gra... zie..."
S["08a36163"] = "La casa dei Barov mi tiene parecchio occupato: ne viene sempre fuori qualche rifiuto."
S["08a483ef"] = "A Caer Darrow è vietato bighellonare, chiedere l'elemosina, imprecare, fare a botte e qualsiasi altra cosa ti stia passando per la testa."
S["08ada43e"] = "Ehehe, come va, amico? Pele'keiki pensare che tu aiutare lui un sacco. Noi avere bisogno di una quantità esagerata di erba firebloom per prepararci bene alla Guerra di Ahn'Qiraj. L'Orda, loro dire: 'Pele'keiki, tu portare a noi i petali di fuoco, e svelto'.$B$BPele'keiki ora dire a te che lui avere solo un po' di firebloom, ma tu presto aggiungerne altra, vero amico?"
S["08b36f26"] = "Arathi Basin essere posto dove prendere da umani molli. Sir Malory Wheeler mandare te là."
S["08b6eb92"] = "È una notizia cupa, e temo sia legata agli affari che $N ha avuto con l'Imbalsamatore."
S["08b87338"] = "Alla lunga ricarica ci si deve abituare, ma non c'è niente di meglio per cominciare uno scontro."
S["08bcd683"] = "%s è immobilizzato."
S["08c3e83c"] = "Dacci dentro, ragazzo. Lavoro duro e determinazione — così si fa! E lascia perdere chi ti dice che basta studiare sui libri."
S["08cd2082"] = "Sì, l'ho fatto, Comandante."
S["08d1adcb"] = "$GBenvenuto:Benvenuta; a Shen'dar Village: da questo lato della catena montuosa, è uno dei posti migliori per pescare. Se vuoi imparare a prendere i pesci, posso insegnartelo io, dietro compenso."
S["08d5160b"] = "Bene, sembra che abbiamo raccolto tutto ciò di cui l'Alleanza avrà bisogno; ora aspettiamo solo l'Orda. Credo che tra poco andrò a vedere se qui vicino c'è del gelato di Tigule & Foror."
S["08e28961"] = "Mio fratello, Drazial, analizza la natura più fisica delle bestie delle terre devastate; io invece tendo a concentrarmi sugli aspetti più cerebrali e spirituali della fauna.$B$BÈ vero, queste bestie hanno una forza, un'agilità e una resistenza davvero fuori dal comune, ma alcune possiedono anche una grande intelligenza e capacità di rigenerarsi che non dipendono dal corpo.$B$BForse ti interesserebbe aiutarmi a portare avanti la mia ricerca, $R?"
S["08ea7496"] = "Grazie per la domanda, $C, ma come vedi ho già tutte le bende di lino che l'Alleanza ritiene necessarie in preparazione della guerra di Ahn'Qiraj. Però non lasciare che questo ti impedisca di aiutare con le altre raccolte in corso qui."
S["08ed42c0"] = "Siamo aperti! La macchina goblin ha un gran bell'aspetto e vincerà di sicuro! Piazzate le vostre scommesse prima che inizi la corsa!"
S["08f165d0"] = "Va' nella città degli Orchi, Orgrimmar, e cercalo nella Valley of Honor, in una bottega chiamata Arms of Legend."
S["0901ff89"] = "L'Horde Flag è stata riportata alla sua base da $N!"
S["09081d95"] = "Marshal Marris aspetta la riserva da Stormwind da un momento all'altro..."
S["0911e42e"] = "Certo che parlo da sola. È l'unico modo per fare una conversazione decente in questa città."
S["09204418"] = "Una voce tonante rimbomba dalla pietra...$B$BSaluti, comandante. Che notizie porti da Silithus ai Signori del Consiglio?"
S["0922e5a3"] = "Bene, sei $Garrivato:arrivata;. Il tempo stringe. Sei $Gpronto:pronta;?"
S["0927f2b2"] = "%s luccica, lampeggia... e non c'è più!"
S["092a1f00"] = "Ahhh, giusto in tempo! Lo stomaco mi brontolava forte."
S["092be700"] = "La nostra covata di draghi più vecchia è ancora lontana dalla maturità, ma con pazienza e studio siamo certi che lo stormo sarà presto pronto."
S["092c795e"] = "%s va su tutte le furie dopo aver visto $N cadere in battaglia!"
S["092d07c1"] = "Ecco. È fatta."
S["0938b84b"] = "%s si riduce in polvere."
S["093aeeee"] = "Sono $Gun maestro conciatore:una maestra conciatrice;, Omarion."
S["093b717e"] = "RAAAAAAAR!"
S["094b0b22"] = "Ti presento il rabid thistle bear, Tharnariun."
S["0956002d"] = "Finalmente! Naralex può essere risvegliato! Coraggiosi avventurieri, venite ad aiutarmi!"
S["09625c31"] = "Sono dell'Explorers' League e cerco manufatti da queste parti. Dicono che Winterspring custodisca oggetti molto magici... Quasi tutti, però, sono ben sorvegliati."
S["096633a6"] = "Cerchi Grol'dar e la Darkfire Enclave? Stanno nella caverna sotterranea chiamata Cleft of Shadow. Ci si scende da due gallerie: una appena a sud di Valley of Wisdom, l'altra da The Drag."
S["096859bd"] = "Non è il mio cuore, ma questo non vuol dire che non possa spezzarsi."
S["09691577"] = "Gimlok, non andare a sporcarti tutti i vestiti."
S["0973b3a3"] = "%s Fa un Respiro Profondo"
S["097fa2a5"] = "D'ah! Ora mi state facendo arrabbiare!"
S["0980487c"] = "<Il cavallo da guerra non morto protende il collo verso di te e ti fissa con due occhi lattiginosi, senza mai battere le palpebre.>"
S["098943a0"] = "Perché tu scappare? Noi fare tuo cadavere nello Scourge."
S["098c9b89"] = "Il Custode del Sapere è un essere antico. Ha servito la nostra gloriosa Regina!"
S["0994c759"] = "Abbiamo difficoltà a capire lo stato della pestilenza nella zona; ripassa tra poco e forse ne sapremo di più."
S["099b82f9"] = "Il Dun Baldar South Bunker protegge i fianchi sud ed est di Dun Baldar.$B$BNon è controllato da nessuna delle due parti."
S["099e89f7"] = "Hai approfittato troppo della mia ospitalità!"
S["09a0cefa"] = "Non possiamo dormire ancora un po'?"
S["09b1fc6c"] = "{Quel $R} sembra $Gbuono:buona; da mangiare!"
S["09b9b416"] = "Questa pianta spicca in mezzo alla flora normale di Teldrassil, con uno strano bagliore violaceo."
S["09ba1f00"] = "Più vicino adesso. Bocconcini gustosi. Sono stata troppo a lungo senza cibo, senza sangue da bere."
S["09c0709a"] = "Non vincerebbero mai una gara, se non avessero quella maledetta fortuna da gnomi!"
S["09c9b1ca"] = "<L'ariete sbuffa, e il suo fiato gelido si vede nell'aria fredda di Dun Morogh.>"
S["09cb45f2"] = "Throm'ka, $C. Tutto il materiale bellico è nella preparazione finale e viene mandato a Silithus. L'ultimo carico dovrebbe arrivare in meno di un giorno. Con l'equipaggiamento pronto e le nostre forze schierate, aspetteremo solo che qualcuno suoni il gong sulla Scarab Dais, che dovrebbe aprire le porte di Ahn'Qiraj e far cominciare la guerra.$B$BLok'tar Ogar!"
S["09cdc481"] = "Forza e resistenza; pazienza e saggezza, ricorda sempre queste cose, $N."
S["09db6a44"] = "<Angela annuisce.>$B$BDopo le morti, i Sei hanno deciso che la cosa migliore era chiudere il bastone dietro barriere magiche impenetrabili e nominare un sorvegliante: un guardiano del bastone... E quella sarei stata io."
S["09e00f8f"] = "Forse rinsaviranno... e scapperanno più veloci che possono."
S["09f4931a"] = "Le nostre unità non sono migliorate, e non ho abbastanza rifornimenti per migliorarle."
S["09f4f4dc"] = "Cercavi questi???? Non li avrai mai!"
S["09f691b2"] = "...Nove... Dieci... Pronti o no, arrivo!"
S["09f7db77"] = "Le cure sono per chi non sa sopportare il dolore. Ma se proprio non ne puoi fare a meno, cerca la Spirit Lodge, sul lago della Valley of Spirits, in alto sopra la Valley of Strength, verso ovest."
S["0a00768e"] = "%s lancia di nuovo l'incantesimo di purificazione."
S["0a08bea4"] = "È un onore per me occuparmi delle forniture e dell'approvvigionamento per l'Earthen Ring. $B$BLe mie scorte sono limitate al momento, ma torna a controllare spesso: potrei avere nuove attrezzature e forniture disponibili per l'acquisto."
S["0a0e2b4e"] = "Aiuuuuuuuuuuuuuuuutoooooooooooooooooooooo!!!"
S["0a0e770e"] = "Qualcosa di diverso!!!"
S["0a1f5110"] = "Le mance sono sempre ben accette, $Gamico:amica;."
S["0a1fc385"] = "Polvere alla polvere."
S["0a29a951"] = "Ecco la mia lista, Keldric. La solita roba."
S["0a29b7a9"] = "Il tuo destino è segnato, Deliana! Pagherai per i tuoi torti contro il Lord Valthalak!"
S["0a2dc0f6"] = "Non è stata la notte in cui abbiamo dovuto raccogliere il mio pollice e portarlo nella tua borsa del tabacco?"
S["0a2e174a"] = "Ecco un esempio di cosa non evocare. Guardate, è fragile e friabile. Basta un bel colpo di mazza per far volare schegge d'osso ovunque."
S["0a2f0e87"] = "Come posso aiutarti?"
S["0a4897e5"] = "%s è ridotto in macerie, ma continua a combattere"
S["0a5c769f"] = "Avverto un pericolo nel profondo del boschetto..."
S["0a63a26c"] = "Un tempo questi boschi erano bellissimi, ma ora li affligge una terribile maledizione! Forze corruttrici deformano tutto ciò che vive qui, fino a farne ombre di ciò che era. Se non sei $Gun agente:un'agente; di questa corruzione, forse puoi aiutarmi a riconquistare il Felwood!"
S["0a6c4863"] = "%s mette le spore nei suoi strumenti alchemici..."
S["0a6f5d29"] = "Sei $Gvenuto:venuta; a trovare la famiglia? Muori, $Gstolto:stolta;!"
S["0a74655a"] = "Che cosa c'è?"
S["0a78e913"] = "Qui sugli altipiani sta' in guardia, $Gcittadino:cittadina;. Di pericoli ce ne sono tanti: le bestie che si aggirano per le terre selvagge, i banditi assassini e la minaccia incombente degli Al'Aketh."
S["0a7a7461"] = "Non puoi sconfiggere il clan Frostwolf!"
S["0a7ab740"] = "Vele all'orizzonte, a est. Invasori, senza dubbio! Fuoco!"
S["0a7b0d08"] = "Saluti, $C. Vuoi dare il tuo aiuto alle Silverwing Sentinels nella battaglia di Warsong Gulch?"
S["0a7d774f"] = "Sì, Remulos. Prepara le razze mortali."
S["0a813ad6"] = "Lysta, fai entrare... l'abominio!"
S["0a90cf35"] = "30 secondi all'inizio della battaglia per l'Alterac Valley."
S["0a9a4add"] = "Salve, salve! $GBenvenuto:Benvenuta; nella mia cucina, signore! Qui si preparano tutte le prelibatezze migliori della Scarlet Raven Tavern. Ah, senti che profumo meraviglioso!"
S["0a9fcf5a"] = "%s toglie i semi dal Glowing Fruit..."
S["0aa0449f"] = "È molto gentile da parte tua chiedere di cosa abbiamo bisogno, $C. Sembra però che abbiamo raccolto tutte le bende di runecloth che pensiamo ci serviranno per la guerra. Posso chiederti di informarti presso gli altri raccoglitori e di dare loro una mano, se serve? Che gli Antenati veglino su di te."
S["0ab532ba"] = "Che provino l'ira del Volo Blu! Che Malygos mi protegga!"
S["0ab7b74c"] = "Che bella giornata! Mi fa venire l'ispirazione per un nuovo modello."
S["0abab995"] = "Potresti pensare che, solo perché viviamo su un'isola volante, qui i minatori come me non servano. Eppure, dopo tante migliaia di anni, riusciamo ancora a portare alla luce un sacco di cose interessanti.$B$BSembra quasi che una forza invisibile continui a creare, ogni tanto, nuovi giacimenti di minerali. Ma la magia è fatta così, no?$B$BComunque, se ti serve un addestramento da $Gminatore:minatrice;, la shen'dorei che fa per te sono io."
S["0abce8e6"] = "Chi osa invadere il Blackrock Clan? Morte a $Gquesto:questa; $R!"
S["0ac86087"] = "Dammi gli ordini! Li consegnerò a Teravaine nel Field of Strife!"
S["0ad88af7"] = "Perché nun ce riprovate senza i vostri trucchetti da quattro soldi, femminucce! O siete troppo fifoni???"
S["0ada97f8"] = "Bel tempo, qui, non trovi?"
S["0ae32343"] = "Sono qui per aiutare il Capitano."
S["0ae46aba"] = "Che la morte di questa prigioniera serva da monito. Nessuno sfida il Flagello e sopravvive!"
S["0ae6727f"] = "I troggs stanno riconquistando l'Irondeep Mine!"
S["0ae6c488"] = "Sono contento che tu sia qui! Perché ho bisogno del tuo aiuto!!"
S["0ae96a71"] = "A un rapido esame, i resti scheletrici mostrano che la carne è stata bruciata via. Uno spettacolo davvero raccapricciante."
S["0af2ea0f"] = "All'improvviso erano dappertutto."
S["0af621cb"] = "Chi controlla lo Snowfall Graveyard?"
S["0b0459ee"] = "Per quello che ti serve, c'è Innkeeper Kauth. Lo trovi in una delle case lunghe, sul lato ovest del villaggio."
S["0b0ebec4"] = "Non mi è mai servito granché un arco, ma questi fucili che fanno i goblin sono molto comodi quando si va a caccia. Però non riesco ancora ad abituarmi all'odore."
S["0b1e34cb"] = "Allontanati da lì!"
S["0b1f4abf"] = "Che Cenarius ti guidi, $C.$B$BSono venuto con le mie sorelle in questa terra corrotta per una missione di grande importanza per il Circolo Cenariano. Ma chiedo che di simili questioni mi parli solo chi è abbastanza potente — mandare un essere inferiore sarebbe una follia."
S["0b23a168"] = "Che bello essere fuori da quella maledetta trincea. Anche se quassù non è molto meglio!"
S["0b2ff672"] = "Vorrei dare un'occhiata alla tua merce."
S["0b31bf30"] = "Vincoli? A questo mondo ci sono cose che vincolano molto più delle sbarre e delle catene, $Ggiovane signore:giovane signora;. Eravamo circondati dai non morti, che ci tormentavano senza sosta con orribili atti di depravazione.$B$BAlla fine è arrivato lui. Si è presentato come Doctor Theolen Krastinov, ma noi abbiamo finito per chiamarlo 'Il Macellaio'."
S["0b3a5ef5"] = "Shelby Stoneflint tiene un bel po' di famigli per i cacciatori del posto. Se ti serve qualcuno che badi a uno dei tuoi, la trovi vicino alla Thunderbrew Distillery."
S["0b565eaa"] = "Salve, $C — se cerchi articoli di cuoio e forniture per la conciatura, sei $Gvenuto:venuta; dal Paladino semi-pensionato giusto."
S["0b56d377"] = "Si dice che Kel'Thuzad stia cercando il leggendario Atiesh, il granbastone del Guardiano.$B$BSì, proprio il bastone che un tempo impugnava Medivh."
S["0b59585d"] = "Parla con Ironus, $N. Sarà lui ad addestrarti nell'arte del fabbro d'armi."
S["0b5abfcb"] = "%s comincia a incanalare la sua energia, concentrandosi sulla pietra."
S["0b6e9ca8"] = "Per ora, spargi la voce fra la nostra gente. Bisogna stare in guardia con i Windshapers. Non siamo stati noi a cominciare questa lotta, ma una volta sistemato il culto saremo pronti a porvi fine."
S["0b795493"] = "Sarò con te fino al mio ultimo respiro."
S["0b7a8b1e"] = "Mio fratello ha detto che con questa rotta commerciale avremmo fatto un sacco di soldi, ma non mi ha detto che a vivere da questa parte toccava a me. Se ripassi di qua con lo Zeppelin, mi porteresti qualcosa da mangiare? A Orgrimmar vendono una carne tra le migliori in circolazione, e mi farebbe proprio comodo qualcosa che non sia morto settimane prima di smettere di muoversi."
S["0b7b7727"] = "Supporto aereo in arrivo a Dun Baldar! Stormpike, inchinatevi!"
S["0b80b422"] = "Sì, credo che tu abbia del potenziale. Forse un paio di cose posso insegnartele."
S["0b83e10b"] = "Credo che farei meglio a fare qualcosa al riguardo!"
S["0b92ee39"] = "Predoni da nord-ovest! Fuoco!"
S["0b9b71ad"] = "Avremo pure patito la siccità, ma la carne di sicuro non manca! Ti va di dare un'occhiata alla mia merce?"
S["0b9fb812"] = "Chi sarebbe tanto stolto da entrare nella torre del Gran Caposquadra?"
S["0ba02df9"] = "Ah, The Gilded Rose... i morbidi letti di piuma, i bagni caldi... solo a pensare a quella Locanda mi viene voglia di... ::sbadiglio:: $GBeato:Beata; te, se ci stai andando... è sul lato ovest del Trade District. ...bei cuscini morbidi, coperte calde. ::sbadiglio::"
S["0ba0c49a"] = "Sono pronto quando vuoi, $N. Fai strada!"
S["0ba1c46a"] = "Fai in fretta: dobbiamo andarcene presto."
S["0ba3abae"] = "È stato raccolto tutto e lo stiamo spedendo a Silithus, $C. Dovrebbe arrivare entro pochi giorni. Posso solo sperare che, dopo che il gong sarà suonato e le porte saranno aperte, i nostri sforzi qui facciano la differenza e salvino molte vite."
S["0ba3d303"] = "Che non ti becchi a rubare qualcosa! Cerca Shenthul e la sua Shadowswift Brotherhood nella Cleft of Shadow, sottoterra. Il tunnel per scendere è a sud di Valley of Wisdom."
S["0bb30a24"] = "Mmmmm, una birra davanti al fuoco ci sta proprio bene. Certo, vengo con te, Jern."
S["0bb5a16d"] = "Och! Sta' $Gattento:attenta; a cosa ti fai incantare, $Gragazzo:ragazza;. Io mi son fatto incantare il boccale perché non versasse una goccia, e adesso non ci posso bere! Che tragedia.$B$BQuando vai da Gimble, da' retta al mio consiglio. Ha la bottega proprio accanto al Maestro dei Grifoni, a The Great Forge."
S["0bc29cd1"] = "Questa pelle non è ancora pronta da lavorare. Vorrei che per fare il cuoio non servisse tanto tempo. Dev'esserci un modo per accorciare tutta quest'attesa: non può far bene alla salute, sai?"
S["0bc45d88"] = "Per ora c'è bisogno di me altrove, e questa non è che una pedina sulla scacchiera. Non deludermi, Aanders."
S["0bc758fc"] = "Continua pure con le tue faccende. Il mio incarico non richiede la tua attenzione."
S["0bc92628"] = "O skilde noth a aesire goibon gol nevren algos novas. Vil waldir vil ras O valesh."
S["0bcebfc9"] = "Hmmm, quella buona idea. Forse noi andare là per farci cambiare qualche punto di sutura? Lui cucire bene. Tu trovare Josef Gregorian in cerchio interno di Magic Quarter."
S["0bd124f7"] = "Credo che la collana mi sia caduta nel lago. Me l'ha comprata papà, e adesso si arrabbierà."
S["0bde1680"] = "Annalise... Hai ragione. N-non posso farlo. Devo trovare un'altra strada."
S["0be5450f"] = "Io fare mojo con te!"
S["0bebcf67"] = "%s è attirato fuori dal dolce profumo del cibo purificato."
S["0bebfc31"] = "Quelle bestie schifose sono dappertutto.$B$BSe ti piace di più cacciare all'aperto, la maggior parte la trovi intorno a Plaguewood e a Terrordale, e parecchi nella galleria di Terrorweb. Probabilmente spuntano anche in quasi tutti gli accampamenti dello Scourge nelle Eastern Plaguelands.$B$BSe sei $Gun accanito esploratore:un'accanita esploratrice; di segrete, ne trovi un bel po' a Stratholme, e a Scholomance qualche necrofiend."
S["0bf06d61"] = "%s nutre lo squirrel con un po' del liquido viscoso."
S["0bf42b28"] = "Gnomeregan, a Dun Morogh, è stata per generazioni la capitale degli gnomi, ma di recente l'hanno infestata i troggs mutanti. In un disperato tentativo di reagire, High Tinker Mekkatorque ha fatto svuotare d'urgenza i serbatoi di scorie radioattive della città. I troggs sono stati irradiati, ma l'assedio è andato avanti senza sosta, e gli gnomi hanno dovuto rifugiarsi nella città nanica di Ironforge: è lì che ora il Gran Meccanista arruola anime coraggiose per aiutare il suo popolo a riprendersi l'amata città."
S["0bf5c385"] = "Avvicinati, giovane. Ai miei tempi riuscivo a sentire il fremito del cuore di una preda. Ora, se vuoi che ti senta, devi parlare forte."
S["0bf79415"] = "Qui le faccende non finiscono mai."
S["0c08ccba"] = "Perché non ci occupiamo di te adesso, Hendel? Lady Proudmoore ti parlerà quando sarai di ritorno alla torre."
S["0c11faca"] = "La tua vita è un sacrificio adatto al mio padrone, $C."
S["0c14ed02"] = "Potrete anche pensare di aver vinto, vermi, ma contro la potenza dello Scourge non c'è vittoria per i vivi! Non è l'ultima volta che ci vedete!"
S["0c2dca78"] = "Come desideri..."
S["0c2eb98a"] = "La nostra evocazione è completa! Il cristallo Ash'ari è stato ripristinato!"
S["0c49d6f2"] = "<Elaadrin ti guarda con un odio a stento trattenuto.>$B$BOseresti mettere piede nel nostro santuario dopo aver versato il sangue dell'High Order? Sei molto $Gcoraggioso:coraggiosa;, o molto $Gstupido:stupida;. L'High Order non perdona, né dimentica.$B$BUn giorno pagherai i tuoi crimini con il sangue."
S["0c4c5447"] = "Mio padre dice che è solo una storia."
S["0c4c73fc"] = "Ci vorrà ben più di una marmaglia come voi per buttarmi giù!"
S["0c4d6e19"] = "Il tuo coraggio vacillerà."
S["0c545921"] = "Bah! Non riconosceresti un grande motore a vapore nemmeno se ti colpisse in testa!"
S["0c5690c7"] = "Prova questi lanciafuochi d'artificio. Sono una bomba!"
S["0c5af865"] = "Che il Torneo di Pesca ABBIA INIZIO!"
S["0c6ceed6"] = "Ehi, tu! Vuoi guadagnarti il rispetto dei Darkspear? Puoi cominciare donando risorse preziose a chi ne ha bisogno! Tessuti e bende mica crescono sugli alberi, sai.$B$BLe pezze di stoffa che trovi durante le tue avventure non venderle: donale! Così ti guadagnerai la stima dei Darkspear!"
S["0c722ee7"] = "\"Regen Landowar\", ru. \"Regen Eloderung\", ru. Vil dana an se \"Regen Eloderung\"."
S["0c76c460"] = "<Novice Warrior deglutisce.>$B$BPosso farcela."
S["0c7aaa01"] = "Azshara è sotto attacco in questo momento?"
S["0c85f4fd"] = "La banca più vicina è The Vault di Ironforge, ragazza."
S["0c873168"] = "Ma come fanno i goblin a legare i carichi su queste bestie? I kodo sono dieci volte più grandi!"
S["0c87fb93"] = "Guardate là! Qualcuno sta combattendo contro Mushgog!"
S["0c8e86a1"] = "Che maledetto spreco!"
S["0c8fa46e"] = "Oh... $Guno:una; skyborne. Che ci fai nella nostra gloriosa città? Fra queste rovine brulica già abbastanza feccia disumana."
S["0c907f25"] = "Grazie agli sforzi di tutti ora abbiamo tutti i lingotti di ferro che ci servono. Chiedi a uno degli altri se c'è qualcos'altro che dovresti andare a raccogliere per lo sforzo bellico. Io vado a vedere se riesco a uscire un po' prima per giocare a carte."
S["0c915736"] = "La grazia con cui combatto non posso insegnartela, ma a usare varie armi sì."
S["0c964fd1"] = "La prima fase è finita. Big Will... fatti avanti!"
S["0c98e819"] = "Durante la War of the Ancients, il semidio Agamaggan scese in campo contro la Burning Legion. Il colossale cinghiale fu sconfitto e col tempo, dove era caduto il suo sangue, spuntarono enormi rampicanti irti di spine. I quilboar finirono per occupare queste regioni e per considerarle sacre, e il cuore di queste immense colonie di spine è la Razorfen. Razorfen Kraul è caduto nelle mani della megera Charlga Razorflank, che secondo alcuni tratterebbe con agenti dello Scourge per qualche scopo insidioso."
S["0c9f4e17"] = "C'è chi non sopporta il caldo della Great Forge, ma per me è proprio quello giusto. E non c'è posto migliore per fare come si deve un lavoro da fabbro."
S["0ca0c7db"] = "Ahah! Era divertente! Umano di legno divertente!"
S["0ca80ddb"] = "Che buono. Adoro lo zampalunga arrosto."
S["0cace5ba"] = "Ti serve una mano a trovare qualcosa?"
S["0caea8a1"] = "%s aggiunge la nebbia ai germogli di Bloodpetal."
S["0cb322ee"] = "La mia forza svanisce, mortale. Ho fatto come promesso, la via è libera. Ora ritorno là da dove sono $Gvenuto:venuta;."
S["0cb3606e"] = "$N conquista il cimitero di Snowfall! Se nessuno lo contrasta, l'Orda ne prenderà il controllo!"
S["0cb4b105"] = "Forse dovremmo andare a pescare sul ponte."
S["0cc50793"] = "%s scorre le pagine del libro."
S["0ccfaffc"] = "Cosa volere da Raze??"
S["0cd46e22"] = "[PH] Questa è un'azione provvisoria finché non potrò interrompere la canalizzazione del mio incantesimo."
S["0cd5cada"] = "Saluti dei venti, $Gamico:amica;. Posso fare qualcosa per te?"
S["0ce7495f"] = "$GEsploratore:Esploratrice; a rapporto!....Eccellente!"
S["0cecc77a"] = "%s scompare in una nuvola di polvere."
S["0cef52eb"] = "A cosa servono quelle casse?"
S["0cfef936"] = "La Shattered Hand è riuscita a piazzare spie in tutta la cittadella superiore di Blackrock. Raccogliere informazioni è stato lento, ma abbiamo scoperto cose che non si possono ignorare."
S["0d030a1d"] = "Suvvia, Zeliek, non scacciarli. Non prima che ci siamo divertiti!"
S["0d060a32"] = "Astuti, mortali, ma non mi farò attirare così facilmente lontano dal mio santuario!"
S["0d090312"] = "Aha! Eccolo."
S["0d0b9650"] = "Noi troll Zandalarian siamo giunti qui da isole lontane perché non possiamo ignorare la minaccia che ora incombe sul nostro mondo.$B$BMolthor, il capo della nostra spedizione, ci ha guidati fino a Yojamba Isle, lungo le coste settentrionali di Stranglethorn, e proprio adesso sta reclutando eroi coraggiosi pronti ad avventurarsi nell'antica città dei troll... Zul'Gurub."
S["0d0c1479"] = "... ops."
S["0d0ddf51"] = "Quanto manca ancora?"
S["0d1efdb2"] = "Nell'arte della sartoria conosco una sola persona più esperta di me. Le ultime notizie che ho avuto di lui lo davano sulla Theramore Isle. È lui che devi cercare."
S["0d1f0893"] = "Un compito urgente mi preme, ma non ho il tempo di occuparmene di persona. Posso affidarlo a te?"
S["0d209cab"] = "Me la pagherai..."
S["0d21b246"] = "Hai caldo? Vieni alla Pig and Whistle a prendere qualcosa per rinfrescarti!"
S["0d3d56bc"] = "Io sto cercando qualcuno, $C. Lasciami stare, per favore... è importante che lo trovo."
S["0d3daaf0"] = "È tutto quello che sapete fare? Pensate davvero di poter sconfiggere qualcuno di straordinario come me?"
S["0d5207b3"] = "Vuoi diventare fabbro? Forgiare lame che sbudellino il nemico? Martelli che gli spacchino il cranio? Sì, posso aiutarti, e lo faccio pure volentieri, se c'è sangue da versare."
S["0d5a34ea"] = "$GBenvenuto:Benvenuta; a Tanaris, $N. Cosa posso fare per te oggi? Non hai l'aria di $Gun fabbro:una fabbra;, ma lo so bene che l'apparenza può ingannare."
S["0d5a72fd"] = "$C, il nostro maestro Malfurion è ancora perduto nel Sogno. La sua luce è un faro che ci mostra la via, e dobbiamo fare tutto quanto è in nostro potere per custodirla."
S["0d652702"] = "Coraggio! Il dolore passa e le donne adorano gli uomini con le cicatrici!"
S["0d662883"] = "Santo cielo! Che cos'è? Aiuto!"
S["0d6c2e28"] = "Mmm... se vuoi confondere le menti, $N, il segreto degli zombi di Zanzil potrebbe proprio fare al caso tuo!"
S["0d740ce8"] = "<Kharan sospira.>$B$BImmagino... immagino che tu abbia ragione.$B$BGor'shak mi ha detto che il tuo Capoguerra ha grandi progetti, progetti che potrebbero cambiare i rapporti fra l'Alleanza e l'Orda. Che cosa ne sai?"
S["0d7b11d1"] = "La forma corporea di Ragnaros va distrutta. Dai resti emergerà la sua essenza, e così indebolito Ragnaros allenta la presa sulla prigione di Thunderaan. Sarà l'essenza stessa a fare da chiave..."
S["0d7c00e2"] = "Sono un orco della medicina, $R. Se sei $Gvenuto:venuta; per imparare, farò del mio meglio per insegnarti."
S["0d818fdc"] = "Oh oh! I miei attrezzi sono finiti. Dovremo ricominciare da capo..."
S["0d89ad77"] = "Pane caldo e genuino!"
S["0d89d51b"] = "Me, o ealdor Veldbarad. Bor nud faergas me thor se o daegil aldonoth? Majis Y gol nuff nud o algos se ash?"
S["0d8b6be5"] = "Ben fatto! Con le pozioni stai facendo bei progressi."
S["0d8cde26"] = "Ma non può essere giusto. Dove ho messo quell'altro libro?"
S["0d8cfba8"] = "%s comincia a lavorare..."
S["0d94d800"] = "Che partenza, $C, te lo dico io. Arraffavamo tutto quello che non era inchiodato o che si staccava in fretta, ed è per questo che siamo un po' a corto di provviste."
S["0d950a4a"] = "Se una mosca non ha le ali, si chiama camminata?"
S["0db2fb09"] = "Finalmente sono libero dalla corruzione che un tempo mi legava a questo luogo..."
S["0db4e0e5"] = "Non sono bellissimi, questi modelli? Ognuno parla con una voce tutta sua."
S["0dbad3e4"] = "Tutti ai posti di combattimento! Arrivano i naga!"
S["0dbb3ac3"] = "Sento puzza di ladro."
S["0dbc2aff"] = "Ti prego, aiutami, sorella...$B$BPresto lascerò questo mondo. Ora soffro, ma so che quando me ne sarò andato non soffrirò più. La fauna, però, sorella mia... soffre anche lei, e non conosce liberazione. Con gli ultimi respiri che mi restano, ti chiedo aiuto."
S["0dbcaacc"] = "Te lo dico io! In tutti gli Eastern Kingdoms non trovi grifoni più veloci di quelli che abbiamo qui a Thelsamar!"
S["0dbdbdd1"] = "Sai chi è intelligente davvero? Nogg! Persino più di me. Va' da Nogg e digli che ti manda Thund! Lo trovi laggiù, vicino al pannello di controllo."
S["0dbdc97f"] = "Ah, ecco l'occasione per usare questa lama appena affilata."
S["0dc56737"] = "Stai scherzando, vero? Sarà l'ALTRO piccoletto che cerchi, Thonys Pillarstone. Sta al piano di sotto. E ora smamma!"
S["0dc75868"] = "Magari... potresti portarmi in braccio?"
S["0dced534"] = "Non aspetteremo più dietro porte sbarrate e mura di pietra! La nostra vendetta non sarà più negata! Gli stessi draghi tremeranno davanti alla nostra ira!"
S["0dd070d3"] = "UUUUUuuuuurrrgh!!"
S["0ddfaa40"] = "Prima che arrivasse la piaga, del cuoio non sapevo niente. Adesso ne so abbastanza da insegnarlo agli altri. La morte mi ha lasciato un sacco di tempo libero."
S["0de247a1"] = "Prendi una birra gratis alla Pig and Whistle!"
S["0de89bb7"] = "In tutti questi millenni Ilyenia Moonfire ha imparato a padroneggiare molte armi, e ora si offre di insegnarne l'uso ad altri. Se vuoi addestrarti, la trovi alla Terrazza del Guerriero."
S["0deef508"] = "Vestire la tribù è un lavoro importante come qualunque altro. Dovresti cercare Tepa nei Thunder Bluff Armorers: con l'ago ha un talento naturale."
S["0df02b11"] = "Che felicità, Jubjub è tornata! Spero solo che la birra Dark Iron non finisca presto, sennò ho paura che la mia rana scappi di nuovo!"
S["0dfccd06"] = "Cos'è un Horde Commendation Signet?"
S["0dfcd50c"] = "Anthion, sembra che io abbia smarrito lo stendardo che hai creato per me."
S["0e018bb8"] = "Dovrei parlare a Dewey di un sistema di catalogazione per tenere questi libri più in ordine."
S["0e024b3a"] = "Sono Augustus, e i miei prezzi sono DA PAZZI!"
S["0e057850"] = "La rabbia di %s esplode mentre si abbandona a una furia frenetica!"
S["0e0b2048"] = "La... testa... ohh, che male! Cosa... chi sei? Perché... mi stai trasportando?"
S["0e0f3179"] = "Soldati Marcus, Tremane, Osgood, Lampret..."
S["0e12a5a6"] = "La vendetta sarà mia."
S["0e166b97"] = "Se cadrò nell'abisso, vi porterò tutti con me, mortali!"
S["0e1856cd"] = "C'è chi si chiede cosa ci facciamo qui nel deserto. Beh... se te lo dicessi, ti fermeresti qui a provare a guadagnare al posto nostro!"
S["0e1d184d"] = "Il genio è spesso frainteso, $R. Ma veniamo al frammento dello scettro... Se lo vuoi e non hai voglia di passare i prossimi diecimila anni a cercarlo, dovrai ascoltarmi con molta attenzione."
S["0e21454b"] = "Direi che è tutto. Abbiamo tutte le Arthas' Tears che servono. Potresti provare a chiedere in giro. Qualcuno degli altri avrà di sicuro ancora qualcosa da far raccogliere per lo sforzo bellico."
S["0e26beab"] = "Grandi pericoli si nascondono oltre quelle mura, $N. Torna indietro finché non sarai più $Gesperto:esperta; nell'arte del combattimento."
S["0e26e19d"] = "Chi osa turbare la santità di Eldre'Thalas? Affrontatemi, codardi!"
S["0e2e5762"] = "Mmm, per impararlo credo che dovrai salire a Thunder Bluff. Segui verso nord la strada che esce da Bloodhoof Village: ti porterà ai piedi di Thunder Bluff. Prendi l'ascensore fino in cima e lì dovresti poter chiedere altro aiuto a uno qualsiasi dei Bluffwatchers."
S["0e2ef32e"] = "Facciamola finita, $Glurido:lurida; $R.$B$B<Kharan abbassa la testa e scopre il collo tozzo.>"
S["0e33a26b"] = "Ah, senti che buona quest'aria salmastra! Tornare a casa, al porto di Booty Bay, è sempre bello."
S["0e3422b7"] = "$N, come posso farti progredire nell'addestramento agli occhi della Madre Terra?"
S["0e3f1feb"] = "Ti pare che io abbia il tempo o le forze per coccolare ogni turista che mi entra dalla porta? Dimmi cosa ti serve, e alla svelta."
S["0e44b3c6"] = "Ho troppo da fare e troppo poco tempo, $R! Togliti di mezzo, per favore."
S["0e6b80f4"] = "Ora troviamo un'arpia che non se l'aspetta!"
S["0e6e938d"] = "Più aspetti, meno futuro ti resta da farti predire."
S["0e722112"] = "<Sul cartellino del meccanostrider c'è scritto:$B$BNitro-Green-Hyperlighter 2000, ora con lampadine due volte più luminose e fotosensori dinamici!>"
S["0e758e26"] = "Qualcuno di voi vorrebbe privarsi di una simile morte? Di un simile onore?"
S["0e7689ea"] = "La Madre Terra ha molti sentieri. Ovunque tu decida di andare, possa lei vegliare su di te."
S["0e76e889"] = "Le professioni si dividono in due categorie principali: primarie e secondarie.$B$BDi professioni primarie puoi averne al massimo due alla volta. Puoi abbandonarne una in qualsiasi momento, ma perderai tutte le conoscenze che hai accumulato: se poi decidi di tornarci, dovrai ripartire dalle basi e cercare di nuovo le ricette che avevi già imparato, per riprenderci la mano.$B$BPer le professioni secondarie questo limite non c'è. Servono più che altro a provvedere da $Gsolo:sola; ai bisogni di base per sopravvivere. Puoi impararne quante ne vuoi, anche tutte, ma le occasioni di guadagnarci potrebbero essere meno."
S["0e7b90ae"] = "Chi è $Gquesto:questa; $C che si presenta davanti alla Corte di Lakshire, nel Kingdom of Stormwind? Di' cosa ti porta in questo borgo, $R. Gli orchi sono una minaccia troppo grande per il Regno, e non c'è tempo da perdere in chiacchiere."
S["0e7ddd64"] = "Sei qui per cacciare draghi? Fai pure. Dove le mando, poi, le condoglianze?"
S["0e81834f"] = "La sartoria, dici? Mmm. Ah sì, certo. Dovrai andare a nord, a Thunder Bluff. Prendi il sentiero che esce dal villaggio e, quando sei ai piedi delle rupi, sali con l'ascensore fino in cima all'altura e parla con uno dei Bluffwatchers."
S["0e82f216"] = "PER KHAZ'MODAN!"
S["0e86c024"] = "La fiamma purificatrice della luce mi attende!"
S["0e897b7c"] = "Il Frostwolf Graveyard è stato conquistato dall'Alleanza!"
S["0e8d6ce8"] = "%s marcia avanti e indietro, ruggendo e facendo baccano."
S["0e921c0e"] = "Dei lupi vengono da questa parte, come se fuggissero da... qualcosa."
S["0e945ba3"] = "Non mi serve l'aiuto della luce. Vattene, $C."
S["0e9b3324"] = "Vorrei addestrarmi."
S["0e9e6a1c"] = "Per una volta sono d'accordo con te... feccia."
S["0e9f5194"] = "La quota di legname richiesta non l'abbiamo ancora raggiunta. Adesso tornate al lavoro."
S["0ea0ea5e"] = "Non ho mai detto che fossi qui per redimerti, $Gsacerdote:sacerdotessa;. Sei qui per redimere me e gli innocenti assassinati mentre cercavano di fuggire da Stratholme.$B$BIl mio spirito e quello di chi è morto sono legati a questo luogo, condannati a rivivere senza fine le nostre tragiche morti."
S["0ea887ad"] = "Sembra che i venti ti abbiano portato da me! Sarò felice di insegnarti l'arte della cucina, se hai voglia di imparare."
S["0eabd969"] = "Ma così non vorrebbe dire incrociare i flussi? Non sarebbe molto grave?"
S["0ec56787"] = "Nemmeno io immaginavo così il nostro primo incontro, Muln."
S["0ed04563"] = "Dunque... così vuoi diventare $Gun sarto:una sarta;? Molto bene: vediamo se hai la stoffa."
S["0ed15c44"] = "Feralas — Screecher Spirit — Saluto predefinito con quest in corso"
S["0edacc31"] = "Saluti, $N, e $Gbenvenuto:benvenuta; al Camp Narache. La notizia del tuo arrivo ha fatto in fretta il giro della tribù."
S["0edcdb9f"] = "Unità esperte stanno entrando in battaglia!"
S["0ee2e4b9"] = "Ecco, $N. Ora puoi parlare con il capo degli Scalporosso e il suo stregone."
S["0eea074c"] = "Molthor vede tutto, $R."
S["0ef49187"] = "$GBen trovato:Ben trovata;, $N. Fa piacere vedere che i ladri come te fanno la loro parte per proteggere i boschetti."
S["0f0241b3"] = "Il culto degli Al'Aketh continua a intensificare la sua violenza, e le ingerenze magiche dell'High Order potrebbero affrettare la nostra rovina, se nessuno le ferma."
S["0f044391"] = "Qualcosa la so, ma non sono un esperto. Per tua fortuna Magar lo è: sta in fondo alla bottega. Vedi se può aiutarti, ma stai $Gattento:attenta; a non farlo arrabbiare, perché a volte è irritabile."
S["0f0f63db"] = "<È chiaro che la montanara ha combattuto con coraggio prima di trovare la morte sotto le armi dei troggs.>"
S["0f12012a"] = "Adesso io metto mia roba nel braciere. Tu parla solo con spiriti quando loro appaiono."
S["0f14f8d1"] = "È ora di portare fuori la spazzatura!"
S["0f2774fc"] = "Ci crederesti che ho fallito proprio nella mia ora più buia, all'apice del mio essere.$B$BFuggivo dalla distruzione sfrenata delle forze che ci avevano travolti, e gli unici suoni che riuscivo a sentire erano le urla dei miei soldati e il battito rapido del cuore.$B$BPoco dopo sono tornato nelle Blasted Lands, sperando di salvare i miei uomini e di riscattare l'onore, e invece mi hanno catturato e picchiato a morte.$B$BNell'interrogatorio e nella tortura che sono seguiti ho scoperto cose orribili."
S["0f2bb55a"] = "$N conquista la miniera! Se nessuno la contesta, l'Orda ne prenderà il controllo tra 1 minuto!"
S["0f2c7659"] = "Assaggiate il cinghiale! È la mia nuova ricetta!"
S["0f2d7a3f"] = "$GBenvenuto:Benvenuta; nel mio negozio, $C. In cosa possono servirti i fratelli Goodstitch?"
S["0f3ab6f6"] = "Clicca qui per riparare il tuo equipaggiamento"
S["0f42232b"] = "Cavalieri dei Montoni, IN FORMAZIONE!"
S["0f480586"] = "Dal campione di tossina che ci hai dato, pensiamo che ti servirà questo: un arcane quickener, sei osseous agitators e quattro pezzi di runecloth. Gli agitatori procurateli dai non morti scheletrici qui nelle Plaguelands, portando con te il vitreous focuser!$B$BCon questi oggetti dovresti riuscire a caricare l'agente neutralizzante in quel calderone."
S["0f5555e2"] = "$GCoraggioso cacciatore:Coraggiosa cacciatrice;, grazie per avermi salvato! Sono certo che Marshal Marris ricompenserà la tua buona azione, $N."
S["0f61c689"] = "I resti sono ricoperti di mosche e maggots."
S["0f631ea3"] = "La gente pensa che mi piacciano i würstel impanati, ma in realtà mi fanno venire l'indigestione!!!"
S["0f652f78"] = "Impari in fretta, e non è un male. Basta che tu faccia il lavoro come si deve, per tutto il tempo che serve. Ora temo di doverti mandare da Snarl per imparare altro. Impara quello che può insegnarti, ma non badare alle sue parole rabbiose. Diventa così quando le figlie di Saru ridono di lui."
S["0f655552"] = "Dobbiamo stare all'erta per estirpare questa piaga!"
S["0f693354"] = "Proprio quello che pensavo."
S["0f6afc8f"] = "Bah! Cassette della posta... di questi tempi mi arriva solo posta spazzatura!$B$BIngrandisci questo... rimpicciolisci quello... agisci subito e avrai gratis la tua Spada Ammazzadraghi. Mi tocca cambiare il numero della cassetta un mese sì e uno no!$B$BBeh, non puoi dire che non t'ho avvertito. Se cerchi la cassetta della posta, è appena fuori da Stonefire Tavern."
S["0f735475"] = "Subito, Rokar."
S["0f7b3640"] = "Grazie, $Gstraniero:straniera;. Non mi sarei mai aspettato che $Gun paladino:una paladina; facesse una cosa simile per me. Sono in debito con te."
S["0f8c36a4"] = "Ho bisogno di aiuto."
S["0f90c8a1"] = "Ma certo, non c'è nessun pericolo che tutto prenda fuoco e salti in aria come un'enorme bomba all'elio. Questa bellezza ti porta a Undercity più in fretta e più al sicuro di qualsiasi nave, e la vista ti toglie davvero il fiato. A proposito di fiato, a bordo dello zeppelin è vietato fumare"
S["0f91984a"] = "Cerca l'assoluzione, Eranikus. Tutto sarà perdonato..."
S["0f97c702"] = "Resta lì tranquillo mentre te lo preparo!"
S["0f9c544b"] = "<I due cultisti qui vicino stanno parlando. Se ti nascondi dietro questo armadio e origli, forse riesci a scoprire qualcosa.>"
S["0f9fe7af"] = "Sono $Gun maestro fabbro:una maestra fabbro;, Omarion."
S["0fa8be36"] = "La guerra contro l'Orda è entrata nel vivo, $N. Adesso l'Alleanza ha un gran bisogno di aiuto, e ognuno di noi deve fare la sua parte."
S["0fa8d8b7"] = "%s ti guarda con sospetto."
S["0fb7c304"] = "Ssssplendido... Allora guardiamo i miei figli fare a pezzi questi mortali."
S["0fb9267a"] = "No, Gargal. Semplicemente no."
S["0fbaf6d9"] = "A quanto pare hanno con sé Vrang. Questi bastardi..."
S["0fbcb029"] = "Mi sono stancato di questi giochi. Proseguite, e bandirò le vostre anime nell'oblio!"
S["0fc3b20e"] = "Oh, che bel fiore laggiù..."
S["0fc73044"] = "Torta, amore mio! Finalmente sono $Gtornato:tornata;."
S["0fcfe201"] = "Morire in battaglia è glorioso! Però con quello che io ti insegno forse tu non muori tanto presto, eh?"
S["0fd70739"] = "Sai, potrei trafiggere un orco o fare a fette un troll. Potrei perfino incidere le mie iniziali sul fianco di un ogre, ma scuoiare un animale proprio non lo sopporto. Vai a capire, eh.$B$BBeh, se hai lo stomaco per farlo, vai da Maris Granger alla Protective Hide nell'Old Town."
S["0fd88a56"] = "Sia noto a tutti che $N, $C dell'Orda, si è $Gguadagnato:guadagnata; il rispetto eterno del Capoguerra. Ha condotto grandi trattative con Timbermaw Hold e compiuto per loro imprese valorose a nome nostro. È $Gandato:andata; ben oltre il proprio dovere. Tre urrà per $N, $Gun vero eroe:una vera eroina; dell'Orda!"
S["0fda17fe"] = "Ah, volare con i grandi uccelli del cielo. Cerca Tal in cima al Winder Rider Roost: ti dirà lui dove andare."
S["0fdb6f1a"] = "<Tarsis geme.>$B$BForse c'è ancora tempo... Ascolta bene, mortale.$B$BHo cercato attraverso il tempo e il Nether. Ho stretto patti con una schiera di malvagità e scelleratezze così ignobili...$B$B<Tarsis tossisce sangue nelle mani.>$B$BCi... ci crederesti che perfino Elune mi ha voltato le spalle, $R? Morire qui, così, ora..."
S["0fdebaa3"] = "In questa guerra non possiamo permetterci di cedere di un passo. Giorno e notte forgio armature nuove e rattoppo tutto ciò che si può salvare di quelle vecchie. Non ho tempo per altri compiti. Potresti occuparti di una cosa per me?"
S["0fe7a4cf"] = "%s si ritrae per il dolore mentre il Judgement of Wisdom lo avvolge!"
S["0feddfaf"] = "Ah! Non ce l'hai la stoffa... per ora! Torna da me quando avrai imparato un paio di cose!"
S["0ff0209c"] = "Sono Zanza, un Loa di Zandalar. Sono giunto da Zandalar in questa forma eterea per aiutare il mio popolo, e Hakkar non ha alcun dominio sulla mia anima.$B$BChi ha aiutato il popolo Zandalarian avrà il mio aiuto."
S["100e7f9f"] = "Assicurati di leggere con attenzione gli appunti nel mio diario, $N. Ti saranno preziosissimi per superare le difese della torre."
S["100f26bb"] = "Anche tu servirai!"
S["10177f0a"] = "Su questo punto molti non sono d'accordo. Io credo che la chiave sia semplicemente comunicare. Quando gli spiriti erano ancora qui, i canti del vento ci arrivavano così chiari. Da quando se ne sono andati è sceso il silenzio, e il nostro potere di windshapers si è indebolito.$B$BEppure alcuni di noi riescono ancora a sentire qualcosa. Un tono sommesso. Frammenti di una melodia. Chi riesce ancora a sentire e a vedere nei piani elementali deve diventare più forte. È lì, credo, la chiave della nostra salvezza."
S["1029db66"] = "Per la barba di Thaurissan! Uccideteli!"
S["102ac792"] = "Avanti! E stavolta stai in guardia! Non ho intenzione di reggere altri combattimenti da solo."
S["10386725"] = "Sto proprio per chiudere..."
S["1039422a"] = "Animali da accudire? Basta che poi quello che sporcano lo pulisci tu! Cerca Shoja'my davanti alla locanda."
S["1043114f"] = "Muori, infedele!"
S["104b9fc7"] = "Fiori, semi e cose così? Allora è il campo di Reyna Stonebranch. La trovi all'Ironforge Physician, sul lato sud di The Great Forge, a curare le sue piante."
S["104d09c3"] = "Il culto Al'Aketh dice che Al'Akir, il \"Signore del Vento\", ci salverà dalle disgrazie che ci affliggono qui su Zephras. Ma se Al'Akir esiste ed è davvero il sovrano di Skywall, perché gli spiriti del vento per tanto tempo si sono rifiutati di parlare di lui?$B$BO non esiste, oppure, peggio ancora, esiste e non è benevolo come dice il culto. Comunque sia, niente di quello che il culto sta facendo è un bene per noi gente comune."
S["105e2011"] = "Quel fannullone di Leland... se ne sta tutto il giorno seduto sul molo fuori dal Trade District a pescare, e nient'altro. Con tutto il tempo che ci passa, spero proprio che sia bravo. Se vuoi imparare, perché non vai a parlarci?"
S["1063c8fd"] = "Nella casa vicino al Crystal Lake vive un'ottima scuoiatrice. Le basi del mestiere te le può insegnare di sicuro."
S["1064ace1"] = "Grazie mille!"
S["1067c35b"] = "Prendilo! Questo affare porta probabilmente più guai di quanto valga."
S["106ba3c7"] = "Grazie a te, $Gragazzo:ragazza;. Grazie davvero."
S["107046c0"] = "Ti serve l'aiuto di un Druido? Allora ti conviene andare da Kal, al Moonwell appena a sud della Locanda di Dolanaar."
S["1073106f"] = "Ci attaccano! Fermi tutti, lavaponti! Respingete gli invasori!"
S["10736517"] = "Se vuoi imparare a scuoiare, Mooranta può aiutarti. La trovi sull'altura di mezzo, appena fuori dai Thunder Bluff Armorers."
S["107d5a0d"] = "Ehm, quello che potrei insegnarti lo sai già tutto. Forse è il momento di rivolgerti a qualcun altro. Prova con l'elfa della notte Ainethil, nella Craftsmen's Terrace of Darnassus. Ha davvero talento!"
S["108cc9b3"] = "Impari così in fretta, ragazza, che non ti sto più dietro. Se vuoi andare avanti con l'addestramento, ti consiglio di passare dal mio maestro: si chiama Rotgath, Rotgath Stonebeard, e lo trovi a Ironforge, a The Great Forge."
S["108eb6f9"] = "Ti strapperò i segreti dalla carne!"
S["10944c0b"] = "Una meravigliosa Winter's Veil a te... ehm... bambino. I bambini buoni hanno diritto a speciali, ehm, sconti presso qualsiasi venditore di Smokywood Pastures qui in zona. Gnam."
S["109e1773"] = "Ormai ci hai preso la mano. Io non ho altro da insegnarti, ma va' a parlare con Arthur Moore, un Forsaken che lavora nel Rogues' Quarter of the Undercity. Digli che ti mando io."
S["109f38f1"] = "Devi essere in rapporti amichevoli con gli elfi della notte di Darnassus prima che ti insegni un'abilità di equitazione, $C."
S["10a3f844"] = "Perché non provi alla Lion's Pride Inn? Il cuoco potrebbe insegnarti qualche buona ricetta."
S["10a9e0f8"] = "Preparati ad affrontare la tua fine!"
S["10aa0f25"] = "È un tentativo di salvataggio! Che nessuno fugga!"
S["10aa4546"] = "Se non hai un guaritore che ti curi le ferite, saper prestare il First Aid può salvarti la vita. Per imparare, io mi rivolgerei a Dannelor, alla Craftsmen's Terrace."
S["10b40b6b"] = "Non posso insegnarti quello che non so! Se solo ci fosse qualcun altro che ne sa più di me... ma aspetta, c'è! Va' da Buzzek Bracketswing, a Gadgetzan!"
S["10b4d51f"] = "Grazie! Grazie, $Gsacerdote:sacerdotessa;. Ora posso affrontare quegli umani con il tuo potere a sostenermi!"
S["10bc1f9b"] = "Ehi, eccone uno!"
S["10c92525"] = "Forse il mio lavoro è bastato..."
S["10c983b0"] = "Il Profanatore... devo avvertire Thrall..."
S["10d2a46a"] = "Se l'ho dimenticato? Certo che sì... Ho dimenticato l'amore, la felicità... la vita stessa."
S["10d2bea1"] = "I nostri ippogrifi fanno avanti e indietro senza sosta fra Rut'theran Village e la Darkshore, così teniamo il collegamento con il continente."
S["10d41634"] = "Il Dun Baldar North Bunker è sotto attacco! Se nessuno la ferma, l'Orda lo distruggerà!"
S["10d66856"] = "Hegnar Rumbleshot, al tuo servizio!"
S["10e900a1"] = "Ti sei $Gmesso:messa; in testa di diventare $Gun:una; tassidermista? Non mi piace chi crede di potermi impagliare ed esporre solo perché pensa che io sia $Gmorto:morta;. No? Bene! Allora cerca Rand Rhobart in un accampamento a sud-est del paese: prendi la strada che da Brill va verso sud-est e all'incrocio gira a sinistra."
S["10eda44a"] = "SCEGLI ME!!!!!"
S["110d7a46"] = "Chi è $Gquesto:questa; $C debole che sfida la mia potenza? Muori, $Gstolto:stolta;!"
S["111052dd"] = "In posizione!"
S["111ad27a"] = "Il tuo capo risiede alle porte di Naxxramas. Credi che non senta la pressione?"
S["111c0a46"] = "Sei $Gpronto:pronta; a fare il riporto, $Gbello:bella;?"
S["111e706a"] = "Sveglia!"
S["112060d0"] = "<Eitrigg ride.>$B$BGiovane, il mondo non è sempre stato nel caos come adesso. C'è stato un tempo prima che lo Scourge devastasse le terre, prima che quelle zone di Lordaeron prendessero il nome di Plaguelands.$B$BÈ lì che Thrall mi ha salvato dalla morte, e allora sono entrato nella nuova Orda... ma sto divagando. Questa storia è per un'altra volta. Sì, un'altra volta... Forse..."
S["11207ffa"] = "Che posso fare per te? No, aspetta! Che puoi fare tu per me?"
S["1128ce77"] = "Dimmi la frase che apre la cassetta di sicurezza di Tirth."
S["112b8006"] = "Esattamente."
S["11363253"] = "Assassini... salvate... il... Magistraaa..."
S["11420786"] = "Ho seguito le tracce dei vari frammenti del bastone in tutto questo mondo, e così ho scoperto che Kel'Thuzad ha in piano di ricomporre il bastone. Diversi frammenti del bastone li ha già raccolti, e li custodiscono i suoi luogotenenti più fidati.$B$BNon lo ripeterò mai abbastanza: è fondamentale che il grande bastone del Guardiano resti fuori dalla portata di Kel'Thuzad. Francamente, non so cosa potrebbe venirne fuori, se non una catastrofe di proporzioni epiche."
S["114b753c"] = "Il tuo futuro è offuscato. Concentrati e chiedi ancora."
S["1151e841"] = "Sei $Guno sciocco:una sciocca;, dovresti ascoltare i miei avvertimenti: nessuno è invulnerabile. Tieni a mente il mio consiglio, ti conviene."
S["115a2a41"] = "Salve, $C."
S["115a2b96"] = "Saluti, $N."
S["115a2c12"] = "Saluti, $R."
S["115c31f3"] = "Sì, l'ho vista, la sciamana che cerchi. L'ultima volta era a ovest di qui: si nasconde sulle colline sopra la tribù dei Razormane. Se sei $Gfurbo:furba;, troverai un sentiero che sale fino alla sua capanna, poco più a nord. Seguilo e dovresti raggiungerla senza dover combattere contro i quilboar."
S["11607cad"] = "Affondate i denti in una mela fresca e matura."
S["11611f95"] = "La maledizione è finalmente spezzata. Grazie, $Geroe:eroina;."
S["1164429f"] = "Quindi vuoi imparare di nuovo quello che hai dimenticato, eh? O magari imparare quello che nessuno ti ha mai insegnato? Ho proprio quello che fa per te, $N. Vicino al porto Steamwheedle, a est, nella capanna di Narain troverai un libro magico che si chiama \"Divinazione per Negati\". Dagli una letta.$B$B<Nixx fa l'occhiolino.>$B$BTroverai tutto quello che ti serve sapere, e anche di più..."
S["117b8873"] = "In tutti questi anni di pratica Nadyia è diventata una gran conciatrice. Prendi la strada verso ovest, per Darnassus, e va' a trovarla: forse potrà insegnarti un po' di quello che sa."
S["117c4cf6"] = "Non posso addestrare $Gun:una; $C come te."
S["117de5e0"] = "Non è un pollo, e no, non puoi accarezzarlo. Ora riprendi la tua strada, prima che ti faccia vedere il suo becco più da vicino."
S["1180f3cc"] = "Arthur Moore è uno che insegnare conciatura, in anello interno di Rogues' Quarter."
S["1185fe90"] = "Non siete che vermi sotto i miei piedi. Osate sfidarmi?"
S["11862fba"] = "Dunque, desideri saperne di più sulle nostre armi elfiche? Che la tua prima lezione abbia inizio."
S["11883b0c"] = "E una volta, al campo, ho preso un pesce più grosso di me!!"
S["118f5861"] = "C'è una certa simmetria nel farsi proteggere dalla pelle del proprio nemico. Se vuoi migliorare nella conciatura, cerca Una dentro i Thunder Bluff Armorers, sull'altura di mezzo."
S["11982958"] = "Ah, l'Alterac Valley, quanti bei ricordi, te lo dico io. <sospira> Be', con te non posso venire, ma fammi onore lo stesso! Per arrivarci devi parlare con Glordrum Steelbeard, nell'Hall of Arms, qui a Ironforge."
S["119a5fcd"] = "In posizione, ragazzi! Le bestiacce ci sono addosso. Aspettate il mio segnale!"
S["119b43dd"] = "Che nessuno passi!"
S["11a54a23"] = "Grrr..."
S["11a65196"] = "Grrrrr!"
S["11ad03f3"] = "I guerrieri di solito stanno alla Pig and Whistle Tavern o alla Caserma, nell'Old Town. Ma te lo dico io: probabilmente ti conviene cercarli alla taverna."
S["11b389c6"] = "Fermi! Sento una presenza malvagia... Non morti!"
S["11b5e54b"] = "Vi condanno a morte!"
S["11c0a6e9"] = "%s esulta!"
S["11c18305"] = "Un piacere, $N. Cosa posso fare per te?"
S["11c51b38"] = "Warg, sei quasi pronto per mangiare? Io intanto comincio."
S["11d2c4aa"] = "Avremo le vostre teste!"
S["11d8b569"] = "Il Techbot è sensibile e quelle parole gli fanno male alle orecchie. :[ Per favore, sii gentile con me.$BVoglio solo aiutare."
S["11db980f"] = "Stanotte è l'ultima del Festival Lunare. Che la fortuna ti accompagni!"
S["11dc3e1c"] = "Ho circa metà delle provviste necessarie per passare alle unità veterane."
S["11ffed29"] = "Frazier va giù! Frazier va giù! Frazier va... eh? Quello non era Frazier?"
S["1200087a"] = "Questa frase è per lo più un riempitivo..."
S["1201efc6"] = "Cercate di attirarmi lontano dalla mia covata? Pagherete per la vostra insolenza!"
S["120a7e47"] = "Sembri $Gvenuto:venuta; da molto lontano, $R."
S["1212f371"] = "$N conquista la miniera! Se nessuno la contesta, l'Alleanza ne prenderà il controllo tra 1 minuto!"
S["12163062"] = "Ansirem! Non immaginavo così il nostro primo incontro, ma sono contento che tu ce l'abbia fatta!"
S["122147f6"] = "Gli Earthen sono una razza sintetizzata, progettata dai Creatori: una delle razze seme della popolazione iniziale del mondo designato come Azeroth. Sono stati creati per aiutare i Creatori a plasmare le regioni profonde di questo mondo.$B$BSono una modifica della matrice standard degli esseri sotterranei, usata su altri mondi seminati dai Creatori. Costruire questa razza prototipo ha generato varie anomalie, osservate dopo la sintesi iniziale."
S["1233cb10"] = "Se ti sei $Gmesso:messa; in testa di darti all'incantamento, dovresti fare un salto a Ironforge. L'ultima volta che son $Gsalito:salita; lassù mi pare d'aver visto una bottega dalle parti del maestro dei grifoni."
S["12378a33"] = "Questo è il prezzo della curiosità."
S["1240990e"] = "%s prende un respiro profondo..."
S["1243bae3"] = "Questo sarà il mio esperimento migliore!"
S["1253887e"] = "Sii forte, Fizzule!"
S["1253d3b2"] = "Ora torna a casa tua!"
S["12574ff7"] = "Dun Baldar è il punto in cui il potere dell'Alleanza è più forte nell'Alterac Valley. Annidata nelle terre settentrionali della valle, Dun Baldar è la base di partenza per tutte le avanzate verso sud.$B$BDun Baldar è intatta."
S["125a0e06"] = "Gira la chiave per avviare la macchina."
S["125c6d77"] = "Scopriamo tutta la storia. Servirà un po' di magia..."
S["125e01e7"] = "Tanto tempo fa, in uno dei miei viaggi, ho incontrato un uomo che mi ha detto: \"Impara a usarlo bene e potrai avere questo.\"$B$BChe vorrà dire, secondo te? Allora non lo sapevo, e a dire il vero non lo so nemmeno adesso..."
S["12705644"] = "A dire il vero sono solo uno studente anch'io. L'esperta è Rhiannon. La trovi vicino alle casse, laggiù. Da lei puoi imparare molto."
S["127be33a"] = "Gloria al padrone!"
S["1280d966"] = "È Komak... Meglio togliersi dalla sua strada."
S["1281e6cf"] = "%s prende di nuovo la mira..."
S["128723b7"] = "La School for Necromancy, quella che chiamano Scholomance, sta sull'isola in rovina di Caer Darrow, nelle Western Plaguelands."
S["1291153d"] = "L'arte degli elfi della notte non si ferma ai boschi e a chi li abita. Conosciamo bene la terra sotto i nostri piedi e i metalli che racchiude."
S["1297bf12"] = "Salve, $C. Sono $Gil Custode:la Custode; della Fiamma: durante la Midsummer Fire Festival il mio dovere è tenere ben acceso questo fuoco accanto a me. Essere $Gscelto:scelta; per un compito simile è un onore, e lo svolgo con piacere.$B$BCome posso aiutarti?"
S["129aadd1"] = "Se è così, ho ancora molte ricerche da fare."
S["129b1d67"] = "Nessuno BUSSA più???!"
S["129b1fb8"] = "Grazie ancora, $N. Io e Rocknot andiamo proprio d'accordo!"
S["12a46065"] = "Ah sì, ne ho sentito parlare."
S["12a883c0"] = "Subito, $Gsignore:signora;."
S["12a8abf5"] = "Il Dun Baldar South Bunker è sotto attacco! Se nessuno lo ferma, l'Alleanza lo distruggerà!"
S["12b199f1"] = "<Lo skyborne davanti a te barcolla: si vede che è parecchio ubriaco.>$B$BSai che una volta facevo il marinaio? Prima che cominciassero i guai. Le navi del cielo facevano la spola fra un'isola e l'altra. Adesso dicono che non è sicuro, o roba del genere.$B$BVedo che l'High Order e i Windshapers hanno rimesso in servizio le loro navi del cielo, ma io me ne sto bloccato qui, a terra!$B$BCos'è che non ci stanno dicendo!$B$B<Si gira verso il locandiere e urla forte.>$B$BCOS'È CHE NON CI STANNO DICENDO, DONAAL!?"
S["12b1eec9"] = "Mai come ora c'è stato bisogno dei cacciatori e dei ranger di Zephras. I venti soffiano sempre più violenti e la magia che sostiene la nostra isola sta svanendo. Le terre selvagge non sono mai state così selvagge, e per proteggere il nostro popolo serve gente come me.$B$BSe hai le doti giuste da $Gcacciatore:cacciatrice;, posso darti gli strumenti per sopravvivere nelle terre selvagge."
S["12b28d53"] = "È ora, $Gstraniero:straniera;. In un modo o nell'altro, chiudiamo questa storia."
S["12b44401"] = "È ora di tornare in bottega..."
S["12b611b0"] = "Se trovi il modo di migliorare il congegno, fammelo sapere!"
S["12b62493"] = "$GBenvenuto:Benvenuta; al Misty Pine, $C. Se sei $Gstanco:stanca; dai viaggi, entra pure a riposarti e a scaldarti. E se hai un po' di tempo libero, magari potresti darmi una mano con alcune faccende."
S["12b6e157"] = "Vedo che quegli idioti dell'Abbazia ci hanno mandato un po' di carne fresca."
S["12c2e183"] = "Solo uno sciocco resterebbe in questa battaglia. Addio, $Gcodardo:codarda;."
S["12c323e5"] = "Ti porterà l'idromele, ti porterà la birra..."
S["12c54505"] = "A zu Moth-tur gor Loch. Gar dum, , hor scyld ta rugosh kaelsag rune hoga dum gar thon."
S["12c56295"] = "Va bene, va bene! Tocca a te!"
S["12cbeb3d"] = "%s si porta il fucile alla spalla, prende la mira con cura e poi spara un colpo al bersaglio."
S["12cbfeab"] = "Hai davvero bisogno di chiederlo? Non lo senti? L'onnipotente King Rastakhan ha mandato qui il suo Servitore e la sua Mano in missione diplomatica?"
S["12cdba3a"] = "Ma aspetta..."
S["12dd428d"] = "La mia mente. . .la mia carne. . .sto. . .marcendo. . . .!"
S["12e322bb"] = "Accidenti, guarda che zanne ha questo qui!"
S["12e6dab2"] = "Qui! Dentro la stanza. Hai trovato la chiave delle mie catene? Le ha l'umano Borhuin."
S["12f123e2"] = "Ah, $Gun collega Pescatore:una collega Pescatrice;. Cerchi un po' di addestramento, forse? Magari posso insegnarti un paio di cose?"
S["12fcc7a3"] = "Una piccola tortura rituale fa miracoli."
S["1313d70d"] = "Su questo punto molti non sono d'accordo. Io credo che la chiave sia semplicemente comunicare. Quando gli spiriti erano ancora qui, i canti del vento ci arrivavano così chiari. Da quando se ne sono andati è sceso il silenzio, e il nostro potere di windshapers si è indebolito.$B$BEppure alcuni di noi riescono ancora a sentire qualcosa. Un tono sommesso. Frammenti di una melodia. Chi riesce ancora a sentire e a vedere nei piani elementali deve diventare più forte. È lì, credo, la chiave della nostra salvezza."
S["13163ec9"] = "Lo Snowfall Graveyard è stato preso dall'Orda!"
S["131a2f57"] = "L'Alleanza ci ha abbandonati!"
S["131c48c8"] = "Desidero lasciare il mio famiglio nella stalla, Maestro di Stalla."
S["132aa1c1"] = "Quando sei a Kharanos, probabilmente senti Tognus martellare sull'incudine. Ma se non ti sei $Gpulito:pulita; le orecchie dalla cera di recente, perché non dai un'occhiata nella fucina."
S["1336cc61"] = "Hai visto i befouled water elementals nel nostro lago, $N? È uno spettacolo triste, ma non so da dove vengano.$B$BHo già sentito parlare di te: forse potresti aiutarmi a risolvere questo problema.$B$BPer prima cosa dobbiamo scoprire chi controlla questi elementali."
S["133afbc8"] = "Sbalorditivo. Sei $Griuscito:riuscita; a dominarla, eppure conserva la coscienza di sé e le sue funzioni. Come hai fatto?"
S["1340c7af"] = "Sporcizia! Sporcizia ovunque! Le foreste devono essere purificate!"
S["1345cdd9"] = "Inchinatevi alla potenza del Gran Signore!"
S["135cf5e1"] = "Il battito d'ali di un hawk, il respiro di un ariete nella neve, il passo di un orso nella foresta... Questa è la vita del cacciatore."
S["13669a31"] = "Madre Terra, concedimi il potere di cancellare questo spargimento di sangue!"
S["13704187"] = "Morendo, gli animali del mondo ci donano vita e protezione. Se senti di poter rispettare come si deve il loro sacrificio, forse la professione di scuoiatore fa per te. Per saperne di più, parla con Eladriel nella Craftsmen's Terrace, nel nord di Darnassus."
S["13721584"] = "Oh, no! Abbiamo finito il tempo."
S["1381665a"] = "La Stormpike Aid Station è stata conquistata dall'Orda!"
S["1386532a"] = "Ehi! Ti piace il sugo? Il sugo è buono, no?"
S["1389f9e2"] = "%s è libero e ora è legato a te, $N."
S["1390b6b6"] = "Stolti, pensate di potermi sconfiggere così facilmente? Affrontate la vera potenza dei Nathrezim!"
S["1393f509"] = "Quanto ai cibi cotti, pare che siamo riusciti a raccogliere e conservare una parte della rainbow fin albacore richiesta. In ghiacciaia, poi, per ora abbiamo anche una parte del roast raptor e dello spotted yellowtail richiesti."
S["13968614"] = "Non te l'avevo detto che la mia nuova tecnica avrebbe funzionato?"
S["139e0582"] = "Sì, sì, ti addestrerò. Non c'è bisogno di alzare la voce."
S["13a3f79f"] = "Avrei dovuto prendere una spada più grande."
S["13ad9459"] = "Ora che abbiamo aperto una breccia nei calderoni, possiamo diffondere l'antidoto nell'ambiente. Così il Flagello dovrebbe essere ripagato con la sua stessa moneta, per così dire!$B$BPer sapere quali reagenti usare nei calderoni, chiedi ad Alchemist Arbington. Io penserò a tutti i rapporti sull'andamento generale dei nostri sforzi per rivolgere la piaga contro lo Scourge!"
S["13b4dfd0"] = "Andiamo, $N. Sono $Gpronto:pronta; a raggiungere il Whitereach Post."
S["13ba0a7e"] = "$GBentornato:Bentornata;, $N. Contro Ragnaros ti sei $Gdimostrato:dimostrata; $Gun valido alleato:una valida alleata;, e qui fra noi la tua presenza è sempre gradita."
S["13bbdd82"] = "È il maestro dei grifoni a occuparsi dei voli da Stormwind: se ti serve un passaggio, devi andare da lui."
S["13bf7875"] = "Truppe fresche si riversano all'Iceblood Garrison! Captain Galvangar arriverà presto, e presto inizierà una nuova battaglia!"
S["13c2b104"] = "Con questo strano trucco uccidi i nemici e fai svenire d'amore gli amanti.$B$BSe segui la via del $C, posso insegnarti... a pagamento, s'intende."
S["13c37ccb"] = "Interrompendomi mi fai perdere tempo prezioso, quindi sarà meglio che ne valga la pena."
S["13c7a8cf"] = "Il mio nome ti dice qualcosa? Magari ci conoscevamo tanto tempo fa...$B$BCredo di portare il nome di qualcuno di importante..."
S["13c9054d"] = "Grazie per il formaggio!"
S["13ca0714"] = "La modernizzazione è la chiave. Con una manovella e una leva puoi far fuoco con questo gioiellino con la forza di un ogre che tende un arco normale."
S["13cf2d71"] = "%s cade a terra. Il suo spirito si libera con l'ultimo respiro."
S["13cf9cd8"] = "È l'ultima volta che ostacoli i nostri piani, $Gsciocco:sciocca; $C!"
S["13d4977b"] = "Bende, antiveleni e cose del genere: chi vive nelle pianure non può farne a meno. Questo sapere te lo può insegnare Vira Younghoof: la trovi nella casa lunga sul lato ovest di Bloodhoof Village."
S["13d7b65d"] = "<Il corpo sembra incompleto, come in attesa di una testa.>"
S["13dc44f6"] = "<Sulla targhetta del meccanostrider c'è scritto:$B$BH4z4rd Flashdasher 3X 4000. Ora con nuovi sensori di radiazioni e nebulizzatori di decontaminazione!>"
S["13df6718"] = "Non osare parlarmi come se fossi $Gmio pari:mia pari;, $C. La mia regina è Sylvanas, e farò quello che comanda.$B$BSe non mi mostrerai il dovuto rispetto, ti assicuro che nella Distorsione Fatua possiamo trovarti un posto più che adatto.$B$BMa se desideri aiutare la Dama Oscura, nulla ci impedisce di parlare..."
S["13e5eea0"] = "Ormai di pozioni ne sai più di me, ma hai ancora tanto da imparare. Sali le scale a sud-est e va' da Doctor Marsh: ti insegnerà la vera soffere — ehm. È un Forsaken, e sarà lui a continuare il tuo addestramento."
S["13e89bf5"] = "Le forze Stormpike ottengono il Grido di Guerra del Generale."
S["13eb0cbe"] = "Ci stiamo preparando alla guerra, $C: dai Silithid e dai loro padroni ad Ahn'Qiraj ne abbiamo sopportate abbastanza. Per questo raccogliamo materiali di ogni tipo, e io mi occupo delle Arthas' Tears. A cosa ci servano, però, non lo so bene. Io, per conto mio, con quel pazzo non voglio avere niente a che fare, anche se è solo un fiore che porta il suo nome.$B$BComunque sono la figlia di mio padre, e un soldato: faccio quello che mi dicono. Per ora abbiamo una parte di quelle che ci servono in tutto."
S["1401c917"] = "Nome, grado e numero di matricola, soldato."
S["1402ec07"] = "Mi piace come ragioni! Filiamocela da qui!"
S["1405f2f5"] = "Gli spiriti della natura sono forze da rispettare. A chi ne è degno danno un grande aiuto, agli stolti una morte rapida."
S["14081e14"] = "In queste lande desolate il passato è vivo, $C. Dobbiamo stare attenti a non risvegliarlo."
S["140c187f"] = "I fili che tengono insieme gli abominations di Stratholme sono molto ricercati dagli artigiani: estremamente resistenti — quasi indistruttibili."
S["140eb38a"] = "Ti prego, parla con Sentinel Onaeya a Maestra's Post, ad Ashenvale: farà in modo che tu sia $Gricompensato:ricompensata; come si deve per il tuo coraggio di oggi."
S["1419117e"] = "La bestia torna da dove è venuta. L'ira di Neptulon si è placata."
S["142723d6"] = "Salute, $C — sono $Gun Ufficiale:un'Ufficiale; degli Encomi e agisco per conto di Ironforge. Il mio compito è aiutare gli avventurieri che hanno ricevuto degli Alliance Commendation Signets.$B$BAccetto anelli in quantità diverse, ma per te lo scambio più vantaggioso è consegnarmene dieci alla volta. Quando me li porterai, registrerò le tue gesta nei nostri archivi, e così Ironforge riconoscerà il tuo impegno e i tuoi servigi."
S["143542b8"] = "Troppo tardi, amici! La corruzione di Nefarius ha preso il sopravvento... Non riesco... a controllarmi."
S["1437ce82"] = "Agli ordini!"
S["1439f116"] = "Porca vacca! Quello laggiù in The Maul è Mushgog."
S["143ef438"] = "$GBen trovato:Ben trovata;, $C. Spero che tu sia qui per saperne di più sullo sforzo bellico per Ahn'Qiraj, perché ci servirà moltissimo aiuto.$B$BLo sforzo bellico è un'impresa comune dell'Alleanza e dell'Orda per prepararsi alla guerra ormai vicina contro i Silithid e i loro padroni ad Ahn'Qiraj. Nel Military Ward of Ironforge raccogliamo beni di ogni genere per produrre il materiale bellico, ed è proprio per queste raccolte che abbiamo bisogno di te.$B$BRiesco a convincerti a parlare con il nostro comandante per darci una mano?"
S["14408da8"] = "Cosa?! Come osi!"
S["144b2931"] = "Per $Gun artigiano:un'artigiana; del mio calibro è un procedimento semplice.$B$BQuando si lavorano pelli e carapaci di bestie, la parte più difficile è procurarseli. Ora, se potessi portarmi una pristine hide di questa bestia, dalla sua carne potrei ricavare diversi oggetti potenti."
S["1454af6e"] = "Meglio essere pronti che essere morti."
S["1460cc4b"] = "Ho un bel ripetergli che la banca non è ancora aperta, continuano lo stesso ad aspettare e a lamentarsi. Sembra quasi che siano venuti apposta."
S["1462ab29"] = "Ti stai divertendo?"
S["14661388"] = "Stavolta abbiamo perso, ma non abbatterti. Concentrati sui tuoi attacchi speciali. Tieni lo scudo alto e vicino. Fai così e la prossima volta la vittoria sarà nostra!"
S["14682d7e"] = "Ti sei battuto bene, Edward. Vediamo se Kahil riesce a batterli."
S["14708507"] = "Tu... La struttura! Come? Non devi... Esso... il Destroyer..."
S["1470b9b7"] = "Chi sei, e perché vieni a disturbarmi? Ah, giusto — $Gstudente:studentessa; di pozioni. Giusto. Cosa posso fare per te?"
S["1475e0eb"] = "$N conquista la segheria! Se nessuno interviene, l'Alleanza ne avrà il controllo tra 1 minuto!"
S["1479b7cd"] = "Vorrei comprare qualcosa da te."
S["1480e840"] = "Mio! Mio! Mio! Il Gizlock è il padrone di questo dominio! Non rivelerete mai la mia presenza!"
S["148142eb"] = "$GUn paladino:Una paladina;! $GUcciderlo:Ucciderla; farebbe piacere al padrone. All'attacco!"
S["14827a00"] = "Era dannatamente ora che arrivasse qualcuno. Perché ci hai messo tanto? Ah, lascia perdere. Coprimi, soldato. Devo tornare alla base!"
S["148cb517"] = "%s scruta $Gil visitatore:la visitatrice; dell'accampamento."
S["149312e2"] = "%s sembra perso nei suoi pensieri."
S["1498e3d9"] = "Nessuno vive per sempre..."
S["149a5fa8"] = "Mi spiace, $Gamico:amica;, qui a Brill non ne abbiamo: per quello ti tocca andare a Undercity. The Undercity sta sotto le Ruins of Lordaeron, a sud di Brill. Prendi l'ascensore sul retro delle rovine, scendi e chiedi la strada a uno degli Undercity Guardians."
S["149c5dbf"] = "La settimana scorsa ne ho preso uno grosso, aveva tre occhi!"
S["14a0b26a"] = "Non ti nascondo niente, verme: l'oscurità chiusa in questi oggetti potrebbe benissimo distruggerci tutti e due. Per questo il prezzo è così alto. Se devo morire, morirò da uomo ricco.$B$BE di come muori tu non me ne frega uno sputo di gnoll: mi importa solo che tu faccia quello che ti chiedo. Portami quello che mi serve e ci guadagneremo tutti e due — oppure moriremo, ma questo te l'ho già spiegato..."
S["14a7f13e"] = "Certo, ti dico la frase. Basta che non debba avvicinarmi neanche un po' a Tirth!"
S["14b2c787"] = "$GBenvenuto:Benvenuta; alla Bank of Stormwind. Qui trovi conti e cassette di sicurezza per i tuoi oggetti di valore. Hai già un conto da noi, signore?"
S["14b72466"] = "Chi osa entrare nel mio dominio! Venite! Venite, e sarete divorati!"
S["14b81e18"] = "Meno male che qui qualcuno sa seguire le tracce! Cerca Shim'la nell'Hunter's Hall, nella Valley of Honor."
S["14bfe227"] = "Ora è il momento di attaccare! Per l'Orda!"
S["14c72ae5"] = "L'Iceblood Graveyard è stato preso dall'Alleanza!"
S["14cc8153"] = "Grazie per aver liberato me e mia sorella, grazie a tutti voi! Finalmente ora possiamo riposare in pace."
S["14d92d77"] = "Qualcuno deve averli aiutati."
S["14dbf036"] = "Temo di non essere più né mite né umile. Gli anni e mille battaglie mi hanno indurito la pelle e l'anima. Forse è per questo che Cairne mi ha mandato al Sun Rock Retreat... i venti leggeri e il sole caldo leniscono il dolore."
S["14e27121"] = "Sapevo che saresti venut$Go:a;, $N. È bello rivederti, $Gamico:amica;."
S["14e272b9"] = "È ora di unirti a noi, $C."
S["14e2740e"] = "È ora che ti unisca a noi, $N."
S["14edb29d"] = "Pattuglierò il passo che sale alla Frostwolf Keep. Basta un vostro cenno e prenderò il volo, Comandante."
S["14f19d46"] = "Compagnia... ALT! ... In RIGA!"
S["14f1c9e3"] = "Abbiamo vinto $2219W battaglie contro lo Scourge. Coraggio, $N. Anche se ci attendono molte battaglie, eroi di ogni reame si sono levati per combatterle."
S["14f2a66b"] = "C'è qualcosa là fuori. Sparate un colpo di avvertimento!"
S["150e3ad4"] = "Faresti meglio ad andartene per la tua strada, $Gragazzo:ragazza;. La mia bestiola qui ha fame, e il tuo odore gli piace."
S["150e5f91"] = "Ah, quindi andiamo dritti al punto?"
S["151164d7"] = "Sono maledetto! Prima affonda la mia nave, e ora... ho finito l'idromele!"
S["151e0c99"] = "Indietro e tenete la linea! Non possiamo fallire o tutto sarà perduto!"
S["151e0eb4"] = "Muovetevi! Continuate ad ammucchiare."
S["152fb1f3"] = "Abbiamo fallito, $N!!"
S["153603f7"] = "Appena fuori dalla Locanda c'è una cassetta della posta, vicino alla strada che esce dalla città verso nord."
S["154576d6"] = "Evvai! Si fa festa!"
S["15459b55"] = "Eppure pensi che recuperare l'Ashbringer possa in qualche modo cambiare le sorti della battaglia? Lascia che ti sveli un piccolo segreto, Comandante: Il potere di The Ashbringer veniva dall'uomo che l'avrebbe impugnata... Io c'ero, Comandante. L'ho visto bruciare legioni di non morti nel fuoco della giustizia prima ancora di sguainare la lama. Ahimè, la tua conoscenza della storia è ... carente."
S["1546a3a4"] = "Finalmente! Tappati le orecchie con le dita: il cervello potrebbe esserti appena cresciuto di cinque taglie, e ho paura che ti coli fuori.$B$BAllora: i Dark Irons gli hanno risparmiato la vita e l'hanno fatto prigioniero. Il loro capo, un tizio arrogante e pieno di sé che si chiama Thauris-qualcosa, si è preso Ironfoe. Ed è l'ultima volta che ho visto il vecchio Windsor... *hic* 'scusa."
S["1546abc5"] = "Mi sa che Plugger ha riempito troppo uno dei suoi barili. Pare che stia per scoppiare!"
S["1549d983"] = "Morendo, gli animali del mondo ci donano vita e protezione. Se senti di poter rispettare come si deve il loro sacrificio, forse la professione di scuoiatore fa per te. Per saperne di più, parla con Eladriel nella Craftsman's Terrace, nel nord di Darnassus."
S["154d889a"] = "Mi hai aiutato, e allora ti dirò quello che so di questa terra e delle cose che ci sono da vedere. Non so molto, ma forse posso indicarti qualcosa che potrebbe interessare a qualcuno come te."
S["1554cc37"] = "Ciao, $N! Hai mai pensato di imparare un mestiere?$B$BRispondo volentieri a tutte le tue domande, oppure posso indicarti gli istruttori della zona.$B$BSe ti sembra tutto troppo, non preoccuparti! Quando vuoi puoi sempre tornare qui, o andare dagli istruttori delle capitali, per cominciare il tuo percorso da artigiano."
S["15550ca8"] = "Difendi Nighthaven, $Geroe:eroina;..."
S["155cd7f9"] = "Oh, evviva, un'altra cosa da fare mentre aspetto! Sei la mia salvezza, $N!"
S["155f204a"] = "Ecco la tua predizione, $N. Che ti possa essere utile."
S["155fcee4"] = "$N, eh? Ehi! $GCittadino:Cittadina; $N, vieni qua! Highlord Bolvar Fordragon ha chiesto che tutti gli eroi dell'Alleanza in grado di combattere si presentino da lui a Stormwind Keep. Sei stat$Go:a; appena arruolat$Go:a;, $Gamico:amica;! Datti una mossa!"
S["156754bf"] = "Ah ah, $N! Non dimenticherò mai la faccia di Daryl quando gli hai mostrato quella testa!"
S["1567c594"] = "Non allarmarti... i miei grifoni non sono del tutto interi, ma ti porteranno lo stesso fedelmente a destinazione. Dimmi... che torre cerchi?"
S["1567e67a"] = "$C, mi servono altri copper bars! Si prepara una guerra ai Gates of Ahn'Qiraj e ci vogliono rifornimenti! L'Alleanza ne ha già raccolti un po', ma non basta per arrivare al totale. Se non mi arrivano quei copper bars, finisco con la testa su un piatto!"
S["156b7110"] = "Figli della Follia, vi scateno su questo mondo!"
S["15720b5c"] = "Director Riddlevox mi ha messo a capo del programma di sviluppo dei trituratori dell'Unione, e in pochi mesi sono già nei guai! Mi farebbe comodo una mano, $N!"
S["1585c90f"] = "In queste feste non dimenticare di fare scorta di carta da regalo! Per augurare un \"Meraviglioso Winter Veil\" ad amici e parenti, non c'è niente di meglio di armature e armi impacchettate."
S["1586bc1a"] = "Siete ancora qui? La vostra stupidità è divertente! La sgualdrina di The Argent Dawn non deve soffrire invano. Andatevene subito e sarà risparmiata!"
S["158e413a"] = "L'Orda ha preso le stalle!"
S["159106b8"] = "%s comincia a combinare cristalli di colori diversi."
S["15916fe2"] = "Mi dispiace, $N, ma coi principianti non ho tempo da perdere. Ti ci vuole qualcuno più vicino al tuo livello. Prova dall'elfa della notte Milla Fairancora, nella Craftsmen's Terrace of Darnassus."
S["15918ff8"] = "$GBenvenuto:Benvenuta; nella mia Locanda, $Gviaggiatore stanco:viaggiatrice stanca;. Come posso esserti utile?"
S["1592d114"] = "Credo di potertelo insegnare. Probabilmente qui potrai trovare solo l'ogre tannin, ma le altre cose le trovi quasi ovunque!"
S["1596c8a8"] = "Se ti serve aiuto per sopravvivere nei boschi, faresti meglio a non allontanarti troppo dalle mura della città. Se però hai intenzione di allontanarti, allora faresti meglio a parlare con Malygen nella Cenarion Enclave, così potrai imparare ad accendere un fuoco da campo come si deve."
S["1597f180"] = "La Syndicate tiene molte casse di provviste chiuse a Durnholde Keep, a Hillsbrad."
S["1599626d"] = "Cosa? Una cosina così piccola e fragile osa chiamarmi? Questo non resterà impunito!"
S["15998864"] = "Vuoi imparare a ricavare il cuoio dalle bestie che abbatti? O ti servono attrezzi nuovi?"
S["159c8915"] = "Cosa? Una cosina così piccola e fragile osa chiamarmi? Aggiungerò le tue ossa al mio trono, $R!!"
S["15a86462"] = "La mia fede guida le mie azioni, $R. So che Ivus verrà."
S["15b5c3a8"] = "Touché..."
S["15cba224"] = "Hai un talento eccezionale! Sei davvero $Gispirato:ispirata;. Se vuoi continuare a studiare, parla con Georgio Bolero a Stormwind: è molto stimato e potrà portare avanti il tuo addestramento."
S["15d51524"] = "Sono $Gcerto:certa; al 100% di voler imparare le vie dell'ingegneria gnomesca."
S["15d51773"] = "Guardie!"
S["15de785d"] = "Pare che l'influenza del Black Dragonflight fosse arrivata oltre i confini delle Burning Steppes, fino al regno stesso di Stormwind! Poi l'usurpatore è stato smascherato e cacciato."
S["15e08f35"] = "$GBenvenuto:Benvenuta; nella mia bottega, è bello vedere $Gun altro Incantatore:un'altra Incantatrice; qui a Stormwind. Sei qui per una lezione, forse?"
S["15fec04f"] = "Questo molo? Be', da qui parte la nave per quel posto degli Elfi della Notte. Com'è che si chiama? Uhh, Auberdine, mi pare. Mica lo so di sicuro, io carico e scarico roba e basta."
S["160217a1"] = "Pace e pazienza siano con te, Hozé. Resta sempre forte."
S["160915d8"] = "I nani Dark Iron della Slag Pit nella Searing Gorge hanno un gran numero di casse chiuse."
S["16142087"] = "Lunga vita a $N!"
S["161788f7"] = "Imparerai a conoscere il rifugio che solo la morte può offrire..."
S["161ca593"] = "Come ti ho detto, la creatura che ci ha attaccati è scappata quando le ho bruciacchiato il didietro con un fulmine, ma prima ha fatto in tempo a mordere Banon. Mentre tornavamo in città, gli gnolls ci hanno circondati e fatti prigionieri.$B$BE solo quando hanno cominciato a tirarci giù dalla barca, sulla Fenris Isle... è iniziata la trasformazione."
S["162d834b"] = "Che interessante... la Pietra ha un grande potenziale magico, ma in forma del tutto grezza..."
S["162ece80"] = "Non farò che rallentarti, ma nessun umano dalla pelle rosa mi impedirà di tornare libero!"
S["1630d792"] = "Salute, $N! $GBenvenuto:Benvenuta; nel mio umile giardino. Ultimamente il tempo è stato perfetto: speriamo che duri, così il raccolto maturerà bene."
S["1631b88b"] = "Mmm... da queste parti gli unici incantatori che conosco lavorano a Stormwind. Perché non chiedi a una guardia, su a Stormwind?"
S["163663ee"] = "%s quasi si frantuma!"
S["16372fdd"] = "Ce l'abbiamo fatta!"
S["16414984"] = "%s viene disarcionato dal suo draco!"
S["16427333"] = "Vuoi addestrarti? Con me? Fantastico! Meglio che assemblare proiettili e congegni esplosivi c'è solo una cosa: condividere quello che so con qualcun altro! Cominciamo!"
S["164353db"] = "Grrrr! Idioti!"
S["1648fd01"] = "L'East Frostwolf Tower è sotto attacco! Se non viene fermata, l'Orda la distruggerà!"
S["164eda08"] = "Temevo di morire qui. Concedimi un momento per curarmi le ferite."
S["164f74b4"] = "Il vuoto oscuro vi attende!"
S["1652c302"] = "Troppi sono caduti, sacerdotessa. Devi concentrarti!"
S["166769f9"] = "Doctor Herbert Halsey stare in The Apothecarium, dove noi essere nato. Lui potere ricucire te tutto meglio come noi."
S["16727ff7"] = "%s punta gli occhi su $N!"
S["1675427d"] = "Porto con me entrambe le parti dello scettro."
S["16780e93"] = "Il Pilone Orientale accetta cristalli blu, gialli e verdi.$B$BConcentra l'energia che si ottiene usando come fonte principale di potere i cristalli blu. Gli effetti possibili sono due: uno aumenta lo spirito, l'altro crea uno scudo che infligge danni.$B$BPer la Crystal Force servono cristalli blu e verdi: ti aumenterà lo spirito.$B$BPer la Crystal Spire servono cristalli blu e gialli: creerà uno scudo che danneggia chi ti attacca."
S["167b10aa"] = "Ti pare che io abbia tempo da perdere in chiacchiere?"
S["167c7f47"] = "Non ne sono degno, $Gsignore:signora;."
S["1686d498"] = "I nemici hanno raggiunto la porta! Avanti! Dobbiamo resistere!"
S["16896a9c"] = "Soldati Stormpike, aiutateci e proteggeteci! Il Forest Lord ci ha concesso la sua protezione. Ora il portale deve essere aperto!"
S["168f06f1"] = "Sono già $Gnervoso:nervosa; di mio... e la gente si ostina a spaventarmi... Ma la prossima volta sarò $Gpronto:pronta;!"
S["1695925b"] = "Mi piace costruire roba. Ma farla saltare in aria mi piace ancora di più!"
S["169f709a"] = "Sembra un compito degno del nuovo re!"
S["16a6c131"] = "Altri prigionieri!"
S["16a911ba"] = "%s va in sovraccarico!"
S["16a9a77a"] = "Un goccio di tè, capo?"
S["16aaa11a"] = "Non abbiamo molti materiali per la ricostruzione. Ce ne vorranno molti di più prima che Dun Baldar sia riparata."
S["16ac3fe0"] = "è completamente $Gcongelato:congelata;!"
S["16ba8d15"] = "L'Alleanza ha conquistato il fabbro!"
S["16c07dce"] = "La tua testardaggine condannerà Zephras!"
S["16c7dde0"] = "È merito tuo, $N, se adesso possiamo svelare i segreti dei cristalli e dei misteriosi piloni. Se ti servono altre informazioni, torna pure a trovarmi quando vuoi!"
S["16c834d5"] = "Allora... dove ho messo ago e filo? Ah! Eccoli..."
S["16d63f14"] = "NON POTETE SCONFIGGERE LA FIAMMA VIVENTE! VENITE, SERVITORI DEL FUOCO! VENITE, CREATURE DELL'ODIO! IL VOSTRO PADRONE VI CHIAMA!"
S["16d74b88"] = "Il Culto? Sono fanatici e assassini. Credono che siamo puniti per un qualche peccato mai precisato. In verità i loro capi sono degli opportunisti, quel che resta di un ordine discutibile di cosiddetti \"Sacerdoti\" di Al'Akir, il Signore del Vento.$B$BOra possono servirsi della paura del nostro popolo come di un'arma per consolidare il proprio potere... e non hanno perso tempo."
S["16d94a1d"] = "Questi atti eroici non significano nulla, $C. Il tuo futuro è segnato e la tua anima è condannata alla schiavitù!"
S["16ef3a02"] = "Ah, $N, non piangere. Per tua fortuna, l'ultima volta che mi hai dato l'amuleto, mi sono $Glegato:legata; a esso. Lo richiamerò semplicemente da dovunque tu l'abbia lasciato cadere.$B$BProva a guardare nelle tue borse ora."
S["16f84ce4"] = "La Bandiera dell'Alleanza è tornata alla sua base!"
S["16fb2df6"] = "Di questi tempi quelli come noi sono pochi, ma fra gli Shen'dorei c'è ancora chi sogna nello smeraldo."
S["16fc0a3b"] = "Bene, sembra tutto in ordine. Diamo il via alle danze."
S["1704d84c"] = "Brutto cattivone! Chi ti ha messo in testa di farlo?"
S["1707e9c7"] = "Aaahhh... Un'altra gloriosa vittoria per l'Orda!"
S["170c5a98"] = "Hai l'aria di chi avrebbe bisogno di qualche incantamento. Sei nel posto giusto!"
S["17137eec"] = "Ma perché dobbiamo imparare questa roba?"
S["171d4ad5"] = "Forse riuscirai a battermi, ma i Defias SI RIPRENDERANNO Stormwind!"
S["17248d6f"] = "Mai come ora i seguaci delle antiche usanze degli Highborne hanno avuto tanta fame di conoscenza e tanta voglia di riprenderci ciò che abbiamo perduto. Se hai le doti per impugnare il potere dell'arcano e lo desideri, posso aiutarti a muovere i prossimi passi."
S["172b40c3"] = "Nefarian aveva ordinato di distruggere subito i soggetti inadatti, ma queste bestie spregevoli non lo facevano senza prima infliggere una dose 'abbondante' di torture.$B$BQuando eravamo del tutto 'spezzati', raccoglievano quel che restava e ci gettavano a questi bruti. I nostri corpi diventavano strumenti del loro gioco malato: scagliati nella lava o peggio; fra le braccia spalancate della legione assetata di sangue che aspettava là sotto."
S["172d23b0"] = "%s inizia a evocare un Blackhand Veteran!"
S["172edd07"] = "Cos'è stato?!"
S["172edd25"] = "Cos'è stato?"
S["17424c5d"] = "$N, spero che tu sia qui per andare nell'Alterac Valley: ci serve tutto l'aiuto che riusciamo a trovare."
S["17505efb"] = "%s si china per esaminare il suo tiro."
S["17542d5a"] = "La temperatura è... non abbastanza calda!"
S["175445f8"] = "E di onore ne avrai molto, ne sono $Gsicuro:sicura;. Parla con Martin Lindsey alle Pools of Vision. È una grotta che si trova sul fianco dell'Altura degli Spiriti."
S["1755778e"] = "I servi di sul banchetteranno con i tuoi resti."
S["17596465"] = "Fiori? In questa landa desolata? Se qualcuno può insegnarti a trovarli, è Mishiki, giù a sud, a Sen'jin Village."
S["175c0a2b"] = "Mi sono perso nel Sogno. Sento la sua forza vitale, ma i miei poteri non sono ancora abbastanza forti per stabilire un contatto."
S["175c5963"] = "Evocherò Eranikus quando mi verrà dato il segnale."
S["175efbc8"] = "ALIMENTAZIONE RIPRISTINATA. PRONTO A RIPRENDERE LA FUNZIONE."
S["1764a305"] = "Ci siamo quasi. Muoviamoci."
S["176d8bf5"] = "Fammi vedere i tuoi piatti della festa."
S["1770a932"] = "Il Generale Stormpike è morto!"
S["1772916d"] = "La mia spada Archeus mi ha servito bene in vita, ma ora che finalmente il mio spirito può lasciare questa esistenza infelice, non ne ho più bisogno."
S["1773bd62"] = "Come sarebbe a dire che cosa voglio dire? È uscita di testa! Quella ragazza ci è saltata addosso come una pazza. Ora, di solito le ragazze non le picchio, ma quando mi sono ripreso dallo svenimento ero dannatamente arrabbiato. Brann, Rutgar, io e la scimmia con lei siamo diventati dei veri orchi! È un miracolo se siamo riusciti a tenerla a bada. Sembrava quasi posseduta!"
S["177c3394"] = "Salve, io sono Petra. Alla mia destra c'è il mio kodo, Dadanga. Siamo con la Marshal Expeditions — ormai da qualche anno, da quando Dadanga era una cucciola.$B$BSe hai torce accese o fiamme libere, ti chiederei di metterle via, se puoi. A Dadanga il fumo non piace."
S["1780f905"] = "Proteggete lo stormo! Questi intrusi muoiono ora!"
S["1784e606"] = "Che avventura!"
S["1794be83"] = "Dobbiamo uccidere altri troll! Uccidine abbastanza e farò saltare la porta del capo dei troll!"
S["1794ed08"] = "Gli occhi di %s brillano di rosso per un istante."
S["1794f873"] = "Allora, se aggiungo quelli gialli..."
S["179a74b5"] = "Adele Fielder si è fatta un nome come conciatrice dalle parti di Elwynn. La trovi al lavoro in casa sua, su vicino al Crystal Lake."
S["179d8625"] = "<Sull'etichetta del robodestriero c'è scritto:$B$BEco-destriero Mecha-Titanio 9000! Ora con scudi alari allungati e silenziatori di scarico ecologici.>"
S["179f0589"] = "Ok, $N. Seguimi fino alla grotta, dove cercherò di imbrigliare il potere della pietra runica in questi occhiali."
S["17a700e9"] = "Omen dorme nelle profondità del Lake Elune'ara, ma lo si può evocare sulle rive a sud-est, vicino agli Stormrage Barrow Dens. Lì troverai dei cluster launchers speciali...$B$BMetti i razzi nei mortai e arriveranno i servitori di Omen. Spara altri razzi, quasi tre dozzine, oppure lancia contro i suoi servitori le candele di Elune, e presto si risveglierà."
S["17a903f1"] = "Salute, $R! Io sono Lieutenant Haggerdin, l'ufficiale che si occupa del reclutamento per la Stormpike Guard.$B$BMan mano che ti fai prestigio e fama fra gli Stormpike, torna a trovarmi e vedrò di migliorarti l'insegna. E se mai dovessi perderla, posso dartene una nuova."
S["17ae40f3"] = "Ehi amico, tu stai qui per portare a me mithril bars, di sicuro. C'è grosso guaio che bolle nel deserto di Silithus, ad Ahn'Qiraj. Noi e l'Alleanza ci mettiamo tutto stavolta per fermare quegli insetti, ed è per questo che tu vedi tutti qui.$B$BL'Orda chiede a me di raccogliere lingotti per lo sforzo di guerra, ma io ancora non ne ho abbastanza. Allora tu mi aiuti, o cosa?"
S["17b05bce"] = "Dateci dentro, vermi! La luce non si muoverà da sola!"
S["17b16068"] = "Stolto impudente! Ti ucciderò io stesso!"
S["17b3a476"] = "Non farebbe disfare la trama, se non fosse ancorata bene prima di cominciare il lancio?"
S["17bf25ba"] = "*Riesci a distinguere le parole* Resta... sorveglia... ombra..."
S["17c16723"] = "Oh, grazie! Era da così tanto tempo che ero $Gintrappolato:intrappolata; in questo incubo..."
S["17da5d89"] = "Bravo! Ora rimettilo sul mucchio di ossa."
S["17db6fc1"] = "Agli ordini!"
S["17e390ba"] = "A quanto pare vuoi parlare con Maginor Dumas! Di solito sta nel Wizard's Sanctum, in Mage Quarter. Certo, con quei maghi non si sa mai quando o dove spariranno in un portale."
S["17e80e5e"] = "Hmph! Che giornataccia sarà per pescare. Be', meglio una brutta giornata a pescare che una bella giornata a lavorare."
S["17eca539"] = "Non mi serve una casa per sapere che in questo mondo un posto ce l'ho ancora, $C. Le tribù vedranno... tutte quante. Si combattono fra loro, e per cosa? Per gli avanzi degli avvoltoi... per terre infestate dalla Legione... bah!$B$BI centauri dovrebbero andare fieri della loro stirpe — è nobile quanto quella di qualsiasi elfo della Notte o orco — ed è ora che cominciamo a comportarci di conseguenza!"
S["18026acb"] = "Le gilde dell'Orda hanno unito le forze e hanno già portato a termine questo compito, $C. Abbiamo tutte le singed corestones che servono per il nostro materiale bellico. Renditi utile e chiedi agli altri raccoglitori qui se hanno bisogno del tuo aiuto."
S["18074753"] = "<Bibbly annusa l'aria>$B$BLo senti? Questo è odore di Goblin di successo.$B$B<Bibbly torna ad annusare l'aria>$B$BO sono queste vecchie ossa?"
S["180bab7e"] = "Molto bene, $N. Troverai Grizzle Halfmane nel Royal Quarter dell'Undercity. Che tu possa trovare grande onore nell'Alterac Valley."
S["180fa5d6"] = "Grazie ancora, $N. Ora userò questo indurio per truccare la mia macchina!"
S["18188ecb"] = "Piazzato il fuoco da campo, ci puoi sistemare intorno ogni genere di attrezzatura da accampamento."
S["1823f1ad"] = "Da qui ce la faccio. Grazie, $N! E parla con il mio datore di lavoro per la ricompensa!"
S["182f9f6e"] = "La battaglia per la Warsong Gulch inizia tra 30 secondi. Preparatevi!"
S["18319ee5"] = "Studiando e capendo il Colossus avremo sui Qiraji il vantaggio che ci serve."
S["1835a4f8"] = "Raggiungi l'Hall of the Brave, nella Valley of Honor, e parla con Grezz Ragefist. Di' loro che, finito il turno qui, tornerò a fare rapporto."
S["1836ae03"] = "Io essere messaggero dagli Eastern Kingdoms, $N. Mi hanno mandato qui per assicurarmi che i sacerdoti che arrivano qui ricevano le giuste indicazioni."
S["183a04ea"] = "Chi controlla la Stormpike Aid Station?"
S["183bba9b"] = "Tuo teschio decorare nostri altari rituali!"
S["183e4b82"] = "Salute, $N. Vuoi prendere parte a una battaglia nelle Darkspear Islands?"
S["184b9b59"] = "La mia redenzione? Sei audace, piccola. La mia redenzione arriva per volere del mio dio."
S["18576e77"] = "Una piastrella scivolosa ti fa perdere l'equilibrio."
S["186a3ab8"] = "Dubito fortemente che avrà qualcosa da dire, straniero..."
S["186d0a53"] = "Sei $Gil migliore:la migliore;, $N — grazie di essere $Gandato:andata; a fare dolcetto o scherzetto al posto mio!"
S["186f6935"] = "Non mostrate debolezza! Schiacciate queste creature immonde!"
S["18713bb9"] = "A quanto pare ti sei fatto subito degli amici fedeli, Walt. Questa feccia di orco si è rifiutata di consegnarti. Se solo sapesse quanto poco ti importa della lealtà."
S["1878dbfa"] = "Beccati questo! Oh... devo aver premuto il pulsante sbagliato... Aspetta, prova questo!"
S["1879d575"] = "The Deadmines stanno sotto Moonbrook, nel sud di Westfall."
S["187b4eca"] = "Combattete! Combattete per le vostre famiglie!"
S["187b7bb3"] = "%s tende la mano verso il Capitano Beltis mentre cade."
S["187bbccb"] = "Ok, adesso credo di averci preso la mano. Seguimi, $N!"
S["188ade7c"] = "Ramstein avere fame di carne!"
S["188f6572"] = "Ecco la classifica finale!$B$BThrall$B$BCairne$B$BSylvanas$B$BTotale Orda$B$B$BBolvar$B$BMagni$B$BTyrande$B$BTotale Alleanza$B$BL'Orda e l'Alleanza hanno pareggiato nel totale dei voti!"
S["18975a09"] = "Vek'lor, sento il tuo dolore!"
S["1898107d"] = "Ho troppo da fare per mettermi a giocare a 'indovina l'odore' con te, $R. Dimmi cosa vuoi o sparisci dalla mia vista!"
S["18986000"] = "Carne di $R... devo mangiare!"
S["18b47605"] = "Seguimi, per favore."
S["18b7d963"] = "Non deluderci!"
S["18be1ed9"] = "Ti farò da spalla!"
S["18cb43ca"] = "Oh, sia lode! La tua vigilanza tiene Myzrael sepolta nelle profondità della terra!"
S["18d29af9"] = "Cittadini e alleati di Stormwind, oggi si è fatta la storia. $N ha distrutto colei che aveva tentato di usurpare il governo del regno. Radunatevi e unitevi a me per onorare i nostri eroi."
S["18e52ba9"] = "Prenditi un attimo. Per ora mi sa che siamo al sicuro."
S["18e8958c"] = "Padroni, vi offro questo nano!"
S["18e9be25"] = "È una delle matrici di sintesi che i Creatori usano per seminare un mondo, e ognuna serve agli obiettivi dei Creatori. Per Azeroth hanno modificato una matrice per esseri sotterranei, così da creare un essere più resistente, portato a modellare le regioni profonde: da questa modifica sono nati gli Earthen.$B$BDopo che gli Earthen sono stati messi al servizio dei Creatori, si è scoperto che anomalie impreviste, dovute agli ambienti ad alto stress, colpivano la loro matrice di sintesi."
S["18ec55b9"] = "Pezzi del Costrutto?! Dici sul serio? Sai cosa farebbero gli Al'Aketh se ci trovassero entrambi qui insieme? Vattene, ora. Mi sottoporrò al tuo giudizio più tardi. Non è sicuro..."
S["18f5fe38"] = "Gli spiriti mi hanno detto che saresti $Gvenuto:venuta; a cercarmi per un motivo che forse nemmeno tu conosci. Allora, sai perché sei qui?"
S["18f7557b"] = "Senza il Grim Guzzler, il tempo libero probabilmente lo passerei a strappare le ali ai dragon whelps."
S["18fc6dd5"] = "Siamo salvi! I contadini sono sfuggiti allo Scourge!"
S["18fe384e"] = "%s getta l'arma e accende un candelotto di dinamite!"
S["19113117"] = "Con l'Alleanza magari non siamo in guerra aperta, ma fra noi il sangue scorre ancora."
S["19160cd9"] = "Gli spiriti ti hanno guidato fino a me. Come posso esserti utile?"
S["191d9b0e"] = "Uff! Che bello essere tornati da quella grotta inquietante."
S["192d2ac5"] = "Abbi cura di te! Io me la filo da qui."
S["1930af5a"] = "L'Irondeep Mine si trova in territorio dell'Alleanza, a nord dello Stormpike Graveyard.$B$BÈ controllata dall'Alleanza."
S["1932a39d"] = "Ti prego, un momento, $N. Kindal è giù nell'accampamento dei Grimtotem e sta cercando di liberare i draghi fatati prigionieri. Siamo stati fortunati che sia arrivato aiuto proprio in quel momento. Chissà cosa avrebbero fatto loro quei tauren immondi."
S["19495dee"] = "E se posso aggiungere, quel vestito è delizioso! Devi dirmi dove l'hai preso."
S["194e1aa4"] = "Subito, Servitore."
S["1954f619"] = "Sull'altura inferiore, nell'edificio subito a sud della Thunder Bluff Bank, cerca Innkeeper Pala."
S["195586c6"] = "Riprova!"
S["19579725"] = "Mi allenerò e diventerò $Gun guerriero:una guerriera; come mio padre!"
S["1958e25f"] = "Non sei $Gun guerriero:una guerriera;... Ma va', col mio addestramento non dureresti neanche un giorno!$B$BUn $C che si crede un guerriero. Ah!"
S["1969c85f"] = "<Il trampoliere si liscia le piume e ti guarda con aria interrogativa.>"
S["196cf7e7"] = "Stai in guardia, $N!"
S["196d9a51"] = "Buona come ti avevo detto, no?"
S["1973139c"] = "Hai l'aria di una donna in cerca di sapere. Forse sono gli insegnamenti della forgia e del martello che cerchi, e forse posso guidarti lungo quel sentiero. Ma solo dopo che avrai accettato gli spiriti e ascoltato il loro richiamo."
S["197dbd35"] = "Sei qui per addestrarti, eh? Io ho appena cominciato, ma quel che posso te lo insegno volentieri."
S["19854c19"] = "Ehi, $Gamico:amica;, mi daresti una mano con una cosa? Sono nei guai fino al collo..."
S["19887552"] = "Polar Gloves."
S["198e575e"] = "Osate disturbare i nostri lavori qui?! Il padrone non ne sarà contento. Approfittate di questo tempo per prepararvi... quando torneremo, ci lasceremo dietro solo morte e distruzione!"
S["1993d09b"] = "Maledetti mortali! Tutti i miei piani di vendetta, tutto il mio odio... tutto ridotto in cenere..."
S["19953b6e"] = "Stolti, avete disperso troppo le vostre forze. Siate liberi, miei servitori!"
S["1996e596"] = "%s indica le pile di libri."
S["199d3aed"] = "Anche se potrai provare a farla funzionare, alla fine le vostre strade si divideranno."
S["19a103ad"] = "Ehi, ma che bel completo che hai addosso."
S["19a509df"] = "Le nostre forze sono pronte e impazienti. Presto Balinda Stonehearth entrerà nel suo avamposto e la battaglia ricomincerà!"
S["19ae2c24"] = "<Field Marshal Chambers ringhia.>$B$BAllora sei tu la marmaglia che ha aiutato Didier a portare fin qui le provviste intatte? E gli altri dove sono? Dovete essere di più, lo so. I conigli come te di solito girano in branchi enormi.$B$BBah, dammi quel dannato mandato e te lo firmo."
S["19b36cd7"] = "Ti posso insegnare a cucinare!"
S["19b773d7"] = "La mia morte non significa nulla.... la luce... prevarrà!"
S["19c03932"] = "La fine dei giorni è giunta! Che la terra abbracci la mia carne e le mie ossa."
S["19c48650"] = "Chi osa disturbarmi? Muori, $N!"
S["19c6a33f"] = "C'è dell'altro."
S["19d3a180"] = "Ho... fallito..."
S["19d3ff93"] = "Smettetela di piagnucolare!"
S["19d81637"] = "Su, fila verso l'Undercity, $N! E cerca di non prenderti la peste..."
S["19db04b7"] = "Se sei qui per mangiare, allora $Gbenvenuto:benvenuta;! In tutta Stormwind non troverai una cucina più raffinata... o in tutta Azeroth!$B$BSe invece sei qui per altre faccende, ti prego di fare in fretta: ho una dozzina di piatti sul fuoco e li devo seguire tutti."
S["19dd5540"] = "Già, pare proprio che tu abbia imparato parecchio, sono $Gcolpito:colpita;. Ma lo sai quanti ce n'ho che vogliono diventare miei apprendisti? Senti un po', fammi un lavoretto e ti prendo con me."
S["19e5a0bb"] = "Finalmente la mia anima può riposare... Oh, mio carissimo Cerellean..."
S["19ee6ebf"] = "Niente più gioco?"
S["19fb991b"] = "Ho abbastanza rifornimenti per far diventare veterane le nostre truppe."
S["1a10ca87"] = "No, qui no..."
S["1a1ff185"] = "Caro amico, tu li onori con la tua guardia vigile. Sei saldo nella tua lealtà. Non dubito nemmeno per un istante che daresti per il tuo popolo un sacrificio grande quanto quello degli eroi sotto cui stai."
S["1a257c1d"] = "Proprio così. Alla fine l'oggetto è stato distrutto, e il potere unito e rinnovato dei quattro Aspetti rimasti ha quasi ucciso Deathwing. Nessuno sa dove sia adesso Deathwing. Sappiamo però che uno dei suoi figli, Nefarian, governa questa cittadella e vuole riprendere da dove il padre si era fermato."
S["1a39cda3"] = "Anche se $Gesiliato:esiliata; come $Geretico:eretica;, le mie convinzioni suonano ancora vere — solo questo mi spinge avanti. Ma perché il mio destino si compia, mi serve l'aiuto di un estraneo... qualcuno che non appartenga a nessuna tribù di centauri.$B$BIl compito richiede che qualcuno entri nelle sacre sale di Maraudon — un tempio che il mio popolo protegge, e in cui solo i più devoti hanno il permesso di entrare.$B$BSe accetti di aiutarmi, ti basta un cenno del capo. Ti passerò una pergamena con le mie istruzioni. Leggila con attenzione e rifletti sulle mie parole."
S["1a48e51c"] = "Non voltare le spalle alla Luce, $C: un giorno potrebbe essere l'unica cosa a salvarti."
S["1a4f7346"] = "Hai solo distrutto un'immagine, $Gsciocco:sciocca;. Ti darò la caccia fino alla fine dei giorni."
S["1a6cfa9b"] = "Sono in molti a servire la Madre Terra, ognuno a modo suo. The Earthen Ring e il Cenarion Circle hanno molto in comune e spesso condividono gli obiettivi, anche se metodi e usanze sono diversi."
S["1a70f13e"] = "Cerca Faruza. L'ultima volta l'ho vista qui davanti, tra le stalle e la casa in fondo al paese, a nord-ovest."
S["1a71a5bc"] = "Oh, ma che meraviglia!"
S["1a755e01"] = "Ben detto!"
S["1a75af07"] = "Questo sforzo inutile mi annoia. Vi incenerirò tutti dall'alto!"
S["1a80c21c"] = "Soldati di Kalimdor! Eroi di Silithus! Uno di voi ha inferto un colpo feroce ai nostri nemici mortali! $N e i suoi alleati hanno liberato le Ruins of Ahn'Qiraj dal loro spietato capo! Ossirian the Unscarred, flagello di Silithus, è stato finalmente distrutto e i suoi eserciti completamente smantellati!"
S["1a87ea3c"] = "$N! L'ACCESSO A QUEST'AREA È VIETATO!"
S["1a8a531e"] = "Chissà se i maiali hanno fame..."
S["1a9bab47"] = "Dobbiamo sbrigarci."
S["1aa507de"] = "$GBen trovato:Ben trovata;, $Gamico:amica;. Sono Officer Garush e vado fiero di far parte di un'organizzazione che opera in tutto il mondo, conosciuta come l'Argent Dawn. La nostra causa è colpire in fretta e senza pietà ogni forma di male che si mostri su Azeroth. Non siamo un organismo politico, e non vorremo mai esserlo. Abbiamo una causa sola, ed è per questo che per noi l'Orda e l'Alleanza sono amiche — amiche nella lotta per schiacciare il male!$B$BPer la Dawn, $Gfratello mio:sorella mia;!"
S["1aa9a0b1"] = "%s guaisce."
S["1ab04dd1"] = "Sembra che siamo nei guai. Svegli, arrivano!"
S["1ab3bfd2"] = "Io cercherei nella Cathedral of Light, in Cathedral Square."
S["1ab849d8"] = "Per migliorare le tue abilità dovrai studiare un manuale: lo vende Balai Lok'Wein di Brackenwall Village, nella Dustwallow Marsh!"
S["1abd3e94"] = "Qui siamo piuttosto lontani da qualsiasi cosa io chiamerei civiltà, almeno finché l'Orda non potrà mandarci altri rinforzi. Ti deve proprio piacere lavorare il cuoio."
S["1ac29787"] = "A Elwynn ci sono parecchi istruttori. Quale cerchi?"
S["1ac9a6b9"] = "Cosa ha detto Gryphe a capo?? Gryphe non mentiva! Eccola là, che cerca di rubare piani di battaglia!"
S["1aca70f1"] = "Va' dai Kodohide Leatherworkers, in The Drag, e chiedi di Kamari."
S["1acf638f"] = "Smidollati Stormpike, affrontatemi nella mia fortezza — se ne avete il coraggio!"
S["1ad0d55c"] = "Sulle pagine del libro cominciano a prendere forma centinaia di diagrammi e schemi. Alcuni li riconosci, altri restano estranei ma familiari."
S["1ad734e5"] = "Hai visto? L'ultimo fuoco d'artificio per poco non incendiava la camicia a quel nano! Ah!"
S["1ad8f73a"] = "Forse, ma se mi colpisse in testa saprei esattamente quale cannone usare per farlo saltare in mille pezzi!"
S["1adda8a5"] = "Non farti ingannare dagli occhietti e dalla barba folta. Vosur è un apprendista di talento e un buon amico, anche se a parlarci mi viene il torcicollo."
S["1aee7b14"] = "Saluti, $C — $Gbenvenuto:benvenuta; in prima linea, nella nostra conquista di Ashenvale! Cerchi qualcosa da fare? Allora sei $Gvenuto:venuta; nel posto giusto. Mi serve sempre gente in forze che aiuti a portare gloria all'Orda!"
S["1af100d5"] = "Salve, $Gamico:amica;! Ti interessa qualche condensatore ectoplasmatico? O magari un bell'assimilatore spettrale omnidirezionale?"
S["1af14f07"] = "Che conflitto inutile, ma se gli elfi della Silverwing Hold non vogliono parlare in pace con noi, che altra scelta ci lasciano? Per raggiungere la Warsong Gulch rivolgiti a Kergul Bloodaxe, sull'Hunter Rise."
S["1af63c8f"] = "Le mura sono state sfondate!"
S["1af79a32"] = "Grazie, Terenthis. Resterò qui più a lungo che posso."
S["1afa699b"] = "Ma sei $Gtonto:tonta;? Quella non è un'arma, è un coltello da tavola. I dilettanti non li addestro."
S["1b008bdb"] = "%s comincia a riprendere forza!"
S["1b018274"] = "Pulite questo posto! Non vivremo in una simile sporcizia."
S["1b04a0b3"] = "I miei occhi! Brucia... brucia..."
S["1b05ad08"] = "$GBenvenuto:Benvenuta; in prima linea, $C. Il Kingdom of Stormwind, con l'aiuto dei suoi alleati, mi ha mandato qui a contrastare la minaccia crescente dello Scourge. Qui a Chillwind Point ogni giorno combattiamo per sopravvivere.$B$BSe sei $Gvenuto:venuta; a cercare l'occasione di dimostrarti $Gun eroe:un'eroina;, ne troverai quante ne vuoi... soprattutto ora che avanziamo verso Andorhal e verso qualunque forza maligna controlli lo Scourge laggiù."
S["1b0f7dd1"] = "E alla fine è stato Ragnaros a darmi un nome quando sono rinato come accolito del fuoco: Lathoric... Lathoric the Black."
S["1b19c652"] = "Non so che cosa ci mettano in quei barili, ma scende giù come il miele!"
S["1b2f3f05"] = "Tanti scaffali, così poco tempo..."
S["1b2f483d"] = "Bene, allora vado. Stammi bene, Harlan."
S["1b321115"] = "Che sfortuna; pare che abbiamo raccolto tutte le bende di telamagica necessarie. Forse puoi andare a venderle alla casa d'aste? Ma prima di andare, fa' $Gil bravo ragazzo:la brava ragazza; e chiedi agli altri raccoglitori presenti. Potrebbero avere una commissione per te."
S["1b3f0225"] = "Ah! $GQuesto:Questa; tauren vuole un bacio!"
S["1b420e60"] = "Dov'è l'Auction House? Beh, sta proprio accanto ai cancelli di Ironforge, appena entri nella nostra bella città. La trovi di fronte a The Vault."
S["1b4711f2"] = "Intrusi! Bene, cominciavo ad annoiarmi..."
S["1b4a95f2"] = "Dobbiamo riunirci agli altri Discepoli. Prima di poter tentare ancora di risanare le Barrens, c'è molto lavoro da fare. Addio, anime coraggiose!"
S["1b4f93fa"] = "Secondo l'ultimo conteggio abbiamo tutti i lingotti di rame che ci serviranno per la guerra. Se fossi in te chiederei ad alcuni degli altri raccoglitori qui se hanno bisogno del tuo aiuto."
S["1b55fa8a"] = "%s piange in modo pietoso."
S["1b5743da"] = "Grazie per il tuo aiuto, $N. Ti auguro il meglio nelle tue avventure."
S["1b5d108c"] = "Grazie di quello che hai fatto, $N.$B$BCustodisci lo scettro; che ti aiuti a combattere i mali che hanno invaso questo luogo..."
S["1b609ecc"] = "Sì, hai sentito bene, $C: tutte le nostre raccolte sono complete e l'ultimo materiale bellico dovrebbe arrivare a Silithus entro un giorno. Mi dicono che, una volta radunato tutto lì e pronte le nostre truppe, qualcuno tra voi eroi suonerà il gong fuori da Ahn'Qiraj, dopo aver ricomposto lo Scepter of the Shifting Sands con cui farlo. Spero che non dovremo aspettare troppo."
S["1b64967f"] = "Ah sì, mi ha detto che presto a Stormwind sarebbe $Garrivato:arrivata; $Gun agente:un'agente; dell'High Order, e mi ha chiesto di prepararti delle istruzioni.$B$B<Randal ti porge una nota sigillata con cura.>$B$BQui dentro dovresti trovare tutto quello che ti serve sapere. Ti aspetta un bel viaggio, $N: buona fortuna, a nome di Stormwind e dell'Alleanza."
S["1b6b26c4"] = "Cenario combatte al mio fianco. Illidan siede sul suo trono in Outland, a rimuginare. Temo che la sconfitta contro Arthas sia stata il suo punto di rottura. La follia lo ha avvolto, Remulos. Rivive quegli eventi nella sua mente mille volte al giorno, ma nella sua mente è lui il vincitore e Arthas è completamente sconfitto. È ormai perduto, vecchio amico. Temo che presto verrà il momento in cui il nostro legame sarà messo alla prova, e non sarà come al Pozzo di Zin-Azshari."
S["1b6d1a08"] = "Insegnarti le vie dell'ingegneria gnomesca? Non se ne parla! Non $Gquesto gnomo:questa gnoma;, almeno. Hai addosso una certa puzza, $N. Forse è la pietà a parlare, ma ti darò un consiglio.$B$BNel deserto di Tanaris troverai una capanna che appartiene a Narain Soothfancy. In quella capanna c'è un libro magico noto per aver fatto cose prodigiose. Trova quel libro e forse potrai ancora imparare la via gnomesca."
S["1b777295"] = "Temo che nell'Alterac Valley non dureresti molto, $C. Torna a trovarci quando avrai qualche stagione in più sulle spalle."
S["1b79a910"] = "Salve, $C. Per alcuni il cacciatore è uno stile di vita, un mestiere che si sceglie. Per altri è una specie di passatempo, un simbolo di coraggio o un rito di passaggio, a seconda della tribù.$B$BPer me razza e mestiere non contano nulla — quello che rispetto è la prova del tuo spirito e della tua mente. Il vero segno dell'onore è affrontare le forze della natura e mettere alla prova tutte le proprie abilità.$B$BSe vuoi metterti alla prova e guadagnarti il mio rispetto, parlami ancora."
S["1b7c4449"] = "Non dirlo in giro, ma nemmeno io so tutto! Se vuoi imparare ancora, dovresti parlare con il proprietario del negozio, Springspindle Fizzlegear."
S["1b7eb9df"] = "Ho ancora le cicatrici di quella notte."
S["1b82b645"] = "Belgrom ci ha mandati qui da Orgrimmar per aiutarlo in un'alleanza poco saggia, ma se la sua scommessa andrà a buon fine, ne trarrà grande vantaggio tutta l'Orda.$B$BTroppi orchi sono già morti per il suo desiderio di compiacere le donne, ma è ancora lui a comandarci, e il nostro onore ci impone di fare del nostro meglio in questa situazione."
S["1b86bce8"] = "Buongiorno a te, ragazzo. Posso fare qualcosa per te?"
S["1b887529"] = "Mi sta uccidendo la schiena."
S["1ba3d58c"] = "Cosa sacrificherei?"
S["1bac518c"] = "Ah ah! Ho preso Betsy!"
S["1baebb96"] = "Ora sto meglio. Torniamo a Ratchet. Vieni, $N."
S["1bb0fad0"] = "Scordatelo!"
S["1bc422db"] = "Già, non voglio essere qui se Myzrael si sveglia. Dicono che abbia un caratteraccio..."
S["1bc44665"] = "SCAPPA! SCAPPA SU COLLINE!"
S["1bc468f6"] = "La temperatura è di 12 gradi Kraklenheit. Che emozione."
S["1bc774c0"] = "Ahh... benvenuti nel mio salotto."
S["1bce0634"] = "Sono un professionista, non ho tempo per le chiacchiere inutili!"
S["1bd3f6b7"] = "Hai intenzione di farmi del male, $R?"
S["1bdb18ae"] = "Ehm... credo tu sia un po' troppo grande per cavalcare un Mechano-strider, signora. Finiresti per schiacciarne i servo-bilanciatori di precisione!"
S["1be326c9"] = "Raccontami ancora delle miniere..."
S["1beccd78"] = "L'erba è morbida e rigogliosa, l'aria fresca e piena di luce e di canti. Da tutto quello che ho visto, Teldrassil sembra un sogno diventato realtà. E allora perché ho il cuore pieno di brutti presentimenti?"
S["1becfd5f"] = "$N, la mia forma è cambiata! La vera forza del mio spirito sta tornando... La presa maledetta della foresta mi sta lasciando."
S["1bf03f7c"] = "Sei un agente del loro dio malvagio, stolto. Ti vedrò distrutto!"
S["1bf651e3"] = "Vek'nilash e Vek'lor, noti come gli Imperatori Gemelli di Ahn'Qiraj, osservavano la guerra dal riparo del loro tempio. I due astuti fratelli idearono un piano per demoralizzare e dividere le forze dello Staghelm."
S["1bf70b80"] = "Elder Bladeswift se ne va in giro per i sentieri di Darnassus, in cima a Teldrassil."
S["1bf7af07"] = "Sento l'OMBRA nei vostri cuori. Non c'è pace per i malvagi!"
S["1bf92e6c"] = "Cuccioli molesti. Vi insegnerò io a immischiarvi!"
S["1bfe19c4"] = "Lok'tar Ogar!"
S["1c01618b"] = "Sono sicuro che troverò un uso per questa miscela..."
S["1c099833"] = "Sento anche un solo commento sugli uccelli acquatici e mangerai con la cannuccia."
S["1c13170b"] = "Vai alla Great Forge, proprio al centro di Ironforge. Lavora lì, accanto agli altri Maestri della nostra gente."
S["1c1fbd02"] = "Facciamo così. Visto che ti credi un eroe, se riesci ad attraversare le Badlands fino alla Searing Gorge e a riportarmi una prova delle tue imprese, vedrò cosa posso fare per procurarti una chiave.$B$BNell'estremo angolo sud-est della Searing Gorge c'è una signora dura quasi quanto me, Margol the Rager. Forse ti conviene darci un'occhiata."
S["1c262c32"] = "Non mi sarei mai aspettato di trovare qualcosa in condizioni così perfette."
S["1c295408"] = "Ehm... non ti conosco poi così bene, scusa. Voglio dire, come venditore autorizzato di Mechano-strider, posso vendere le mie cavalcature solo a chi è considerato amico degli gnomi. Se mai sarai $Griconosciuto:riconosciuta; come $Gamico:amica; di Gnomeregan, sarò felice di mostrarti cosa ho da offrire."
S["1c326de3"] = "Sì, tu cerca Christopher Drakul in Trade Quarter. Lui sta su piattaforma orientale."
S["1c439878"] = "Hai imparato le basi della preparazione delle pozioni, ma per approfondire lo studio serve un impegno maggiore. Dimostra la tua dedizione svolgendo un compito per me."
S["1c43b61b"] = "Mmm... credo di aver bisogno di un'esca migliore. Guarderò nel carro di mio padre."
S["1c43eafd"] = "%s nitrisce."
S["1c4a4b47"] = "Sei appena in tempo, $C. Senti la terra tremare sotto di te?$B$BQualcosa si avvicina dall'alveare. Prendi posto vicino alle reclute, $N. Conto su di te!"
S["1c55437d"] = "Lo senti, Mulv? Il bisogno? Devi volerlo, prima che io possa darti l'ordine. Ma chi voglio prendere in giro. Vai là fuori!"
S["1c58078e"] = "Ashenvale è una foresta rigogliosa, traboccante di vita, e percorrerne i sentieri segreti in cerca di erbe è un piacere. Ma bisogna stare attenti: i pericoli non mancano."
S["1c613ff0"] = "Krathok, un tempo ero $Gun forgiatore:una forgiatrice; d'armi e vorrei riprendere in mano il martello! Insegnami la via del forgiatore d'armi."
S["1c6a52a2"] = "Ba-a-asta! Fate che smetta!!"
S["1c6b41b4"] = "Se voi mortali siete tutti così vigliacchi, sarà più facile del previsto!"
S["1c719866"] = "Vicino al Crystal Lake abita una signora, Adele Fielder, che fa toppe per le guardie della zona con il cuoio avanzato che le passa la scuoiatrice del posto, Helene. Se ti interessa imparare il mestiere, probabilmente è lei che devi cercare."
S["1c821e60"] = "Salute a te, $C. Tutti i Forsaken devono fare ciò che possono per il bene dei loro fratelli e delle loro sorelle. Il tuo aiuto è necessario e anche apprezzato."
S["1c8486b2"] = "La prossima covata si schiuderà presto, sire. Saremo pronti a lanciare gli attacchi entro la fine della settimana."
S["1c8a34fd"] = "Hai fatto un buon lavoro, $Gviaggiatore:viaggiatrice;. Sono fiera di poterti chiamare $Gmio allievo:mia allieva;!"
S["1c8b490d"] = "|cffffff00La Plaguewood Tower è stata conquistata dall'Alleanza!|r"
S["1c8fbcd2"] = "%s inizia a intonare un canto in una lingua antica, evocando qualcosa di natura malvagia."
S["1c907294"] = "C'è mancato poco, $N! Be', rimettiamoci in marcia, c'è ancora un bel pezzo di strada fino a Ratchet!"
S["1c92e1eb"] = "Fai pure /lay dove ti pare, $N. Te lo prometto, non ti farà neanche un po' male!"
S["1c9813db"] = "In tempi antichi Eldre'Thalas era un fulcro di potere magico, e chi abitava nelle sue sale consacrate ne aveva a disposizione in misura immensa. Fra loro c'era l'elfa della notte Millicent Serene — una naturalista che infondeva il potere stesso della natura nei potenti manufatti che forgiava.$B$BIl suo capolavoro fu il Frutto della Fertilità... in un pozzo lunare preparato apposta fece crescere una pianta rampicante esotica e rigogliosa, intrisa di un'aura di protezione e di crescita. Grazie a quel rampicante prosperò tutta Eldre'Thalas."
S["1c9e6214"] = "Salute, $Gcittadino:cittadina;."
S["1c9ef8b7"] = "%s spreme l'ultimo briciolo di vita da $N e ne inghiotte l'anima."
S["1c9fc2fe"] = "Adoro il Festival Lunare! È il posto giusto per alzare un po' di polvere con gli zoccoli!"
S["1ca1aeaf"] = "Posso insegnarti a trasformare la carne che trovi sulle bestie in un banchetto?"
S["1ca617bb"] = "Giù le mani dalla posta!"
S["1ca9c6fa"] = "Aprila. Dobbiamo sbrigarci. Sento l'odore dei Dark Irons da un chilometro, e ti dico una cosa: STANNO ARRIVANDO!"
S["1cacc06a"] = "Studia sodo e un giorno potresti riuscire a evocarne una da $Gsolo:sola;, ma per ora passiamo al Vilsegugio."
S["1cb11afd"] = "Anche se è vero che l'Alleanza ha completato tutti i suoi compiti per lo sforzo bellico, non lasciarti scoraggiare, $R. Il tempo stringe, ma preferiremmo di gran lunga che tu aiutassi nelle raccolte dell'Orda con cura e attenzione. Mi sembra meglio che commettere un errore che potrebbe costare la vita a qualcuno quando questa guerra comincerà davvero. Non sei d'accordo, $C?"
S["1cb51bbe"] = "Vivo solo per servire il padrone."
S["1cb5fa2b"] = "Siamo stati traditi!"
S["1cb9cf92"] = "Se pensi che io sia brava, dovresti vedere combattere mio marito."
S["1cb9f951"] = "Direi che è quasi tutto finito, vero, $N? Mi mancherai... ci si sentirà piuttosto soli quassù senza qualcuno con cui parlare.$B$BMa questo non vuol dire che non puoi tornare a trovarmi in futuro!"
S["1cbaa9c6"] = "Grazie, $Gpiccolo:piccola; $R!"
S["1cbd2939"] = "Ma cosa..."
S["1cc01d4d"] = "%s sibila."
S["1cc2fe9b"] = "L'Orgrimmar Auction House sta nella Valley of Strength. La trovi sul lato est, accanto alle Boomstick Imports."
S["1ccf2685"] = "L'infestazione dello Scourge cresce nelle Eastern Plaguelands. Serve ogni guerriero abile per arginare la loro invasione.$B$BNecropoli rimaste: $2282W"
S["1ccf2cec"] = "Ti va di comprare uno scarafaggio?"
S["1cd2f281"] = "La mia missione è compiuta. Se ti serve, forse ho qualche provvista in più."
S["1cd3b2b8"] = "La mia saggezza e la mia conoscenza sono tue. Cosa posso fare per te, $N?"
S["1cd787d2"] = "Martin Lindsey lo trovi dentro le Pools of Vision, sotto la Spirit Rise. Ti aiuterà a raggiungere l'Arathi Basin."
S["1cd9c855"] = "(Sniff, sniff) Lo senti? L'odore del grasso... non lo ADORI anche tu?"
S["1cdeb43c"] = "Forse hai la stoffa, forse no. Se ce l'hai, ti prenderò con me e ti insegnerò ciò che desideri sapere. Se non ce l'hai... be', mi fermo qui."
S["1ce4a7de"] = "Se non sapessi come stanno le cose, mortale, penserei che ti stia prendendo gioco di me; ma sì, più o meno è così. Puoi restare completamente $Gvestito:vestita;."
S["1ce4c835"] = "Che Elune cammini con te, $C. Il Tempio della Luna è venuto in aiuto dei cittadini di Auberdine in difficoltà."
S["1ce5ac93"] = "Signorina, se non sapessi come stanno le cose, ti prenderei per una di quelle persone \"speciali\". Noi li chiamiamo Troggs.$B$BWindsor coi Dark Irons non ce l'aveva mica: dopotutto il miglior amico del suo bis-bis-nonnino era un Dark Iron. E probabilmente è anche per questo che quell'esercito di Dark Irons non l'ha ammazzato a vista."
S["1ce9277b"] = "Sciocco $N, ora servi me!"
S["1cf36767"] = "No! Anaya... Anaya! Non lasciarmi! Ti prego..."
S["1cfce733"] = "Mia arma essere assetata!"
S["1cfea3a7"] = "Informazioni sulle Brilliant Chromatic Scales."
S["1d0dd269"] = "%s va in frantumi, liberando l'anima che conteneva."
S["1d116eae"] = "Promozione Upperdeck — Landro predefinito"
S["1d160b38"] = "Ah, la dolce aria salmastra di Ratchet."
S["1d18ac85"] = "Mette the rock nel buco!"
S["1d1f6798"] = "Non conosci ancora le basi, viandante. Hai parlato con la mia assistente, Lalina Summermoon? Forse dovresti farlo."
S["1d207635"] = "Ti serve una mano in qualcosa, $N? Se no, ho un carico a cui badare."
S["1d24e92e"] = "Ce li hai dei tesori nuovi da mettere al sicuro? Allora ti conviene depositarli a The Vault, dagli Stonemantles.$B$BThe Vault è a un tiro di martello dall'ingresso di Ironforge, verso nord-est."
S["1d389ba3"] = "Questo è leggermente meglio del precedente. Tuttavia soffre della stessa ossatura fragile degli altri. Se ne evocate uno così, siete sulla strada giusta."
S["1d49f840"] = "La lettura è di 8536 gradi Kraklenheit... Ti sei già $Gstufato:stufata; di me?"
S["1d4b990d"] = "Ho bisogno di aiuto!"
S["1d51a65d"] = "Puoi dirlo forte! E la cosa è ancora più strana, visto che fra Brann, Rutgar, me e la scimmia conosciamo 38 lingue diverse, compreso un pizzico di Titanico — sia Vanir che Aesir.$B$BComunque, qualunque cosa stesse ticchettando, di sicuro non parlava con nessuno dei \"presenti\". Poi ha annuito ed è partita all'attacco! Ci ha aggrediti senza pensarci due volte!"
S["1d565b89"] = "Gli Stormpike hanno portato alla luce antichi manufatti nell'Alterac Valley, ma gli orchi Frostwolf non vedono di buon occhio gli esploratori. Se i nani devono combattere per conoscere i loro antenati, e così sia!$B$BPer vincere questa battaglia, sconfiggi l'orco, Drek'Thar, nella Frostwolf Keep. Che la fortuna sia con te, $C!"
S["1d5a05ec"] = "$GBenvenuto:Benvenuta; nel Cenarion Circle, $C."
S["1d640021"] = "$GMio signore:Mia signora;, vi prego, permettetemi di vivere abbastanza da vedervi purgare questo mondo dagli infedeli."
S["1d6cef87"] = "Questo è di certo un servitore dell'incubo di Naralex!"
S["1d6d806e"] = "Lo giuro... se Quint prova ancora a infilarmi addosso un'altra larva da pesca, gli abbatto l'albero con la spada, che poi tanto arrugginita non è."
S["1d710b7b"] = "I Creatori conoscono bene la portata delle informazioni custodite in questo archivio. Per questo, quando sarai $Gsintonizzato:sintonizzata; con The Discs of Norgannon, avrai a disposizione una copia portatile dei dati qui conservati.$B$BPuoi considerare completati i requisiti preliminari per assimilare questa conoscenza. Quando preferisci, accedi a The Discs of Norgannon per avviare la sintesi dei tuoi dischi."
S["1d7db2ee"] = "Molto bene. Allora tornerò."
S["1d803f26"] = "Mi serve un'altra pietra scintillante."
S["1d819765"] = "Possiamo renderlo migliore, più forte, più veloce. Abbiamo la tecnologia. Abbiamo la magia."
S["1d82074b"] = "Ce li hai dei tesori nuovi da mettere al sicuro? Ti conviene depositarli a The Vault, dagli Stonemantles. The Vault è a un tiro di martello dall'ingresso di Ironforge, verso nord-est."
S["1d844237"] = "Tutto è stato raccolto, $C. Tutto viene trasportato a Silithus per i preparativi finali e dovrebbe arrivare entro qualche giorno. Tutte le nostre forze riunite attendono l'eroe che completerà la riunificazione dello Scepter of the Shifting Sands, suonerà il gong e darà inizio alla Guerra di Ahn'Qiraj."
S["1d867ec0"] = "Voi non appartenete a questo luogo! Antichi, sollevatevi contro questi intrusi!"
S["1d8f7357"] = "È stato semplice, una volta spezzato il suo spirito."
S["1d915006"] = "Allenati sodo, e fallo ogni giorno. Quando avrai perfezionato le tue abilità, torna da me."
S["1d9558b9"] = "Ormai non riesco mai a scaldarmi..."
S["1d9a8ed6"] = "Se Hydraxis trova altre reclute per la sua guerra, potrebbe cambiare l'equilibrio delle forze..."
S["1da207d8"] = "Grazie ancora, $N! Sono proprio contenta di quello che abbiamo trovato.$B$BBuona fortuna!"
S["1da3d5dd"] = "Ai pesci viene mai sete?"
S["1da804f5"] = "Mm, curioso... Qui finisce all'improvviso. A Tanaris i Qiraji raccontano di aver affrontato un drago bronzeo. Manca molto... Bisogna trovare altre informazioni! Di sicuro stanno progettando di invadere di nuovo Kalimdor!"
S["1db15245"] = "Vuoi rafforzare i tuoi demoni? Ti costerà, ma sei $Gvenuto:venuta; nel posto giusto."
S["1db272d8"] = "Cinque biglietti o duecentocinquanta, non importa $Gamico:amica;, vincono tutti!"
S["1db70d7a"] = "Ho finito. La pergamena è pronta. Ora torna da Gorzeeki..."
S["1dba7488"] = "IL CONTADINO OLTREPASSA LA LINEA."
S["1dbb22c8"] = "Fiuu! È stato un bel lavoraccio, $R. Lo Scourge così aggressivo non lo vedevo dai tempi di...$B$B<Guard Didier deglutisce a fatica.>$B$BDai tempi dell'ultima guerra..."
S["1dca5855"] = "La tua capacità di apprendere ha superato la mia: per altri insegnamenti dovrai rivolgerti a Bena Winterhoof, laggiù. Ma ti prego, non rubarle troppo tempo. Ha bisogno di riposare."
S["1dce3e07"] = "Elder Proudhorn è lassù a Thunder Bluff, a godersi il panorama di Mulgore."
S["1dd3db34"] = "Evvai! Ora ci stanno dando dentro!"
S["1dd4b8ad"] = "La voce sommessa di %s svanisce nella nebbia: \"Sappi che ti amerò per sempre...\""
S["1dd6f477"] = "Il progetto della verga è semplice. Dartol non ha usato le sue conoscenze arcane per crearla... ha una natura più druidica."
S["1dd8a7b1"] = "Ti prego, fa' come ti dico, $N."
S["1dd989ef"] = "%s continua a crescere!"
S["1de0b585"] = "Accidenti! Due personalità focose. Litigherete spesso, ma il vostro amore brucerà altrettanto forte!"
S["1de29d31"] = "Va' nella Valley of Strength e cerca la Bank of Orgrimmar: è a sud della Sky Tower."
S["1de4dab8"] = "Sporchi codardi Frostwolf! Se volete combattere, dovrete venire da me!"
S["1dee002f"] = "Mille anni fa, gli elfi immortali, i semidei della foresta e i draghi combatterono contro la Legione sulle pendici dell'Hyjal."
S["1dfe3b7e"] = "%s è $Gsfinito:sfinita;!"
S["1e1086d4"] = "Sempre di corsa, quella ragazza."
S["1e152403"] = "Che ti serve dal vecchio Mazu'kon, $C?"
S["1e293489"] = "Quindi vi divertite a giocare con le creazioni di The Lich King? Ramstein, assicurati di dare agli intrusi un'accoglienza come si deve."
S["1e2d8d58"] = "Anche chi non è di stirpe draconica può ottenere il Sigillo Adornato dell'Ascensione e attraversare la barriera protetta. Possedere un oggetto simile mi distruggerebbe di sicuro, ma forse tu potresti usarlo per abbassarla."
S["1e411fd0"] = "Per ora ho tutte le provviste che mi servono."
S["1e472313"] = "Devi ascoltare, giovane $C. Ascolta i sussurri nell'oscurità, perché in questi tempi travagliati sono una guida."
S["1e48421f"] = "Il cartellino di questo regalo dice: \"Dai 20 anni in su.\""
S["1e4a7636"] = "No, non un altro! Avrò le vostre teste per questa atrocità!"
S["1e559df2"] = "Avremo bisogno di esploratori e avventurieri di ogni genere. Pensaci, e quando verrà il momento spero che valuterai l'idea di unirti a noi. Fino ad allora, buona fortuna."
S["1e609c0a"] = "Mi servono un paio di buoni gregari che mi portino fuori di qui al sicuro e mi riportino alla base."
S["1e625332"] = "Il pesce è squisito, Jessica."
S["1e628d8c"] = "Accidenti! Ce l'abbiamo fatta... non so perché pensavamo di aver bisogno di gente come te. Comunque, parla con Smeed Torcivite: ti darà il tuo compenso!"
S["1e635644"] = "Il Bunker Iceblood è sotto attacco! Se nessuno la ferma, l'Orda lo distruggerà!"
S["1e6440f8"] = "Hai la stoffa per diventare $Gun abile cacciatore:un'abile cacciatrice;? Be', $Gragazzo:ragazza;, lo dirà il tempo. Però niente tiri alle mele sulla testa della gente finché non avrai parlato con Regnus, laggiù nell'Hall of Arms."
S["1e691c4f"] = "Il tuo nome sarà ricordato nei secoli, $N. Cerca Taim Ragetotem sull'Hunter Rise e ti aiuterà nel tuo cammino verso l'Alterac Valley."
S["1e6b714f"] = "Insegnarti mi piacerebbe tantissimo! Così mia sorella vede che non è l'unica a intendersi di ingegneria..."
S["1e75a46a"] = "Hai dei mithril casings?"
S["1e75c72a"] = "Oh, ciao! Sono Sarah. Posso fare qualcosa per te?"
S["1e78c29d"] = "<Alessandro sospira, frustrato, e si stringe la radice del naso fra le dita ossute.>$B$BE va bene. Sì, dammela pure. Almeno la fiala di vetro la posso riutilizzare."
S["1e9397b9"] = "Aiuto! Guardie! Sta per calpestarmi!"
S["1e979539"] = "Saluti, $Gviaggiatore:viaggiatrice;."
S["1e9bd28b"] = "Sei qui per aiutare con l'heavy leather per lo sforzo bellico di Ahn'Qiraj, vero, $C? Bene, bene. Come vedi, ne ho già raccolto un po', ma in tutto ce ne servirà molto di più. C'è un bel po' da scuoiare, $Gamico mio:amica mia;, quindi spero che il tuo coltello sia affilato. Il cuoio servirà a ogni genere di scopo per produrre il nostro materiale bellico e garantire il nostro successo."
S["1e9d8947"] = "Non ne ho mai visto uno così grande! Non vedo l'ora di spedirlo indietro per le ricerche..."
S["1ea77f57"] = "Ho torta di ciliegie fresca in vendita, così invitante che ti scapperà una lacrima."
S["1eb70a71"] = "Questo mi sembra familiare. Se continuiamo verso est, credo che potremo... Ahh! Una viverna all'attacco!"
S["1eb78b8a"] = "E così comincia..."
S["1ec0990a"] = "Il posto migliore per imparare il First Aid è la Cathedral of Light, sotto l'occhio attento di Shaina Fuller.$B$BPer arrivarci basta cercare i tetti gialli o l'altissima guglia della Cattedrale: si vede da quasi ogni punto della città."
S["1ec7061b"] = "È tutta colpa loro, di quello stupido esercito dell'Alleanza. Le torri dovevano costruirle proprio dietro la mia fattoria."
S["1ed969ad"] = "Devi essere in rapporti amichevoli con i Forsaken of the Undercity prima che io ti insegni un'abilità di cavalcatura, $C."
S["1edb75fe"] = "Karu, mi aiuti a togliermi di dosso queste api? Pungono!"
S["1edc4bcf"] = "Sosteniamo gli artigiani mistici offrendo una scelta limitata di materiali arcani per le professioni. Cerchi qualcosa in particolare?"
S["1ede27fa"] = "Sogno, $N... oh sì, sogno. E nei miei sogni muoio mille volte, in mille modi diversi. C'è chi chiamerebbe incubi i sogni come i miei. IO NO! In sogno muoio nel pieno della battaglia, e per ogni mia morte diecimila nemici dell'Orda cadono davanti a me. È glorioso!"
S["1ee22dfa"] = "Hai completato la quest!"
S["1ee30184"] = "Scommetto che al mio amico Gruk piacerebbe questa pietra per la lancia che sta facendo! È molto affilata... spero che gli piaccia."
S["1ee9cc27"] = "Bene, $Gragazzo:ragazza;, sembra che l'Alleanza abbia già raccolto tutto quello che ci serve per la nostra parte della guerra. So che i fabbri, gli ingegneri e tutti gli altri sono impegnati con gli ultimi preparativi, e non appena l'Orda avrà radunato tutti i suoi beni, verrà tutto mandato a Silithus per la guerra."
S["1eea2ed1"] = "Sono $Gun istruttore:un'istruttrice; di sartoria troll, e questo è il mio saluto predefinito."
S["1eeb162d"] = "Ciao di nuovo, $N. Pensavi che ti avrei $Gdimenticato:dimenticata;?$B$BSapevo che non l'avresti pensato. Sei $Gun:una; $C intelligente, che riconosce una persona dalla memoria perfetta quando la vede."
S["1ef76fd8"] = "E adesso, spuntino..."
S["1efa7691"] = "Lo Scourge ti chiama, stolto $R."
S["1efc4649"] = "Per favore, lancia un incantesimo di DEBUFF ad alta priorità su tutti i bersagli vicini."
S["1f003e6d"] = "Nemico in vista! Fuoco!"
S["1f0770cc"] = "Uoh... Uoh... Aaaaahhh!"
S["1f108968"] = "Mostrami cosa posso imparare."
S["1f158126"] = "Va', che la benedizione di Al'Akir ti accompagni. Ma sta' $Gattento:attenta;; chi si avvicina con l'inganno ai fedeli del Signore del Vento subirà presto la Sua ira."
S["1f171bee"] = "Ah! Finalmente aria fresca! Non pensavo che avrei mai rivisto questo giorno..."
S["1f19291a"] = "Ehi, Knot — sono $Gun Conciatore:una Conciatrice;. Pensi di potermi insegnare a fare il costume da ogre?"
S["1f19b112"] = "Devo andare. Il male si risveglia. Muori con onore, Omarion."
S["1f1bd6da"] = "Byancie ha prestato spesso i suoi servigi alle sentinelle che pattugliano le terre selvagge qui intorno. Se desideri imparare il First Aid, dovresti parlare con lei."
S["1f212119"] = "Esala l'ultimo respiro!"
S["1f30a97e"] = "Sì, mio signore."
S["1f31f4d0"] = "Sbrigati! Il Kirin Tor non ignorerà le fogne a lungo."
S["1f33d2fd"] = "<Le orbite, vuote e profonde, sembrano trapassarti.>"
S["1f372ee8"] = "Conciatura"
S["1f3cbde0"] = "%s è $Gcresciuto:cresciuta; del tutto!"
S["1f3f5e23"] = "Noh deh $J skam yu ju duti."
S["1f4daa7a"] = "Bevi questo: ti aiuterà."
S["1f56c422"] = "Ayessa... un tempo eri mia sorella. Quanto sei caduta in basso, per ritrovarti in compagnia di questa feccia dell'High Order."
S["1f5baf95"] = "%s comincia a tradurre..."
S["1f6ac967"] = "I piani sono lì dentro!"
S["1f6f00e8"] = "Andiamo, tesoro."
S["1f71a10b"] = "Non mescolare la pozione così, contadino imbranato! No, non smettere nemmeno di mescolarla! Lascia perdere — dammi quel mestolo prima di appiccare un incendio. Salverò quel che posso. Ora, fai attenzione."
S["1f767be0"] = "Qui a Brill un Istruttore di Ingegneria non c'è, ma ce n'è uno giù a Undercity. Per arrivarci va' sul retro delle Ruins of Lordaeron, a sud del paese, e scendi con l'ascensore. Lì chiedi a un Undercity Guardian indicazioni più precise."
S["1f782965"] = "Non ti deluderò!"
S["1f874942"] = "È bene che tu mi serva così fedelmente. Presto tutti serviranno The Lich King... e alla fine sarai $Gricompensato:ricompensata; — purché tu non vacilli."
S["1f8ca20d"] = "Non è il tuo posto, questi giardini. Il tuo corpo nutrirà le nostre splendide creazioni!"
S["1f930703"] = "Non farti ingannare da quei grandi occhi innocenti. Tally è un'esperta, eccome: ogni giorno imparo qualcosa di nuovo. Perché credi che stia qui a Tinker Town? Ti sembro un ingegnere? Eh già, lo immaginavo."
S["1f933105"] = "Non ho mai dubitato di te, $N, nemmeno per un secondo.$B$BEcco i tuoi ordini, $N. So che non mi deluderai."
S["1f9f9960"] = "Credo che, con un buon diversivo al santuario, un piccolo contingente di Peacekeepers, Windshapers e High Order possa aggirare le difese sul fianco e fare irruzione fin nelle sale più interne. Da lì elimineremo l'Alta Sacerdotessa in persona e taglieremo la testa al serpente."
S["1fa106c6"] = "Ehi, $C! Sembra che abbiamo tutti i pinnagialla maculati che ci servono per quella guerra. Forse tu vai da qualcuno degli altri raccoglitori qui intorno e chiedi se hanno bisogno del tuo aiuto?"
S["1fa3558d"] = "Maraudon è uno dei luoghi più sacri di Desolace. In questo grande tempio/caverna è sepolto Zaetar, uno dei due figli immortali nati dal semidio Cenarius. Secondo la leggenda, Zaetar e la principessa earth elemental, Theradras, hanno generato la razza bastarda dei centauri. Si dice che i barbari centauri, appena venuti al mondo, si siano rivoltati contro il padre e l'abbiano ucciso. Alcuni credono che Theradras, per il dolore, abbia imprigionato lo spirito di Zaetar nella tortuosa caverna — e che ne abbia usato le energie per qualche scopo maligno."
S["1fa5ae75"] = "Prima che il rituale del risveglio abbia inizio devo preparare tutto quello che serve. Devi proteggermi!"
S["1fb17964"] = "Incredibile! Conosco colui che ha forgiato questi incantamenti..."
S["1fb8072e"] = "Una banca? Be', da queste parti la banca più vicina è la Stormwind Counting House. La trovi poco più su lungo la strada, a Stormwind, non lontano dai cancelli."
S["1fc8179d"] = "Un ladro? Mmm... be', ho sentito dire che Keryn Sylvius frequenta quei tipi loschi. Magari ti conviene parlare con lei e vedere cosa puoi imparare."
S["1fc83371"] = "Indietro! Stai lontano! Ho lo zaino pieno di polvere esplosiva e non ho paura di usarla! Ci faccio saltare tutti in aria!$B$BOh, lascia stare. Pensavo fossi qualcun altro...."
S["1fd4aced"] = "Ho preso un pesce, se hai fame..."
S["1fe29ad1"] = "comincia a rallentare!"
S["1ff04036"] = "Brzt... clic... zzzz..."
S["1ff3a019"] = "Ho sentito dire che Hydraxis, un nobile fra i water elementals, è in guerra con i servitori del fuoco. Speriamo che perda!"
S["1ff73b0a"] = "Non capisci. Quella forgia sta avvelenando le fattorie di Westfall! Se non la si distrugge, qui non crescerà più niente per generazioni. Rischi una grave carestia!"
S["1ff87475"] = "Fai $Gil conciatore:la conciatrice; di mestiere, vero? Quel leggero odore di pelli conciate lo riconoscerei ovunque.$B$BMio padre parlava sempre di un famoso artigiano che secoli fa viveva in Southwind Village. Peccato che ormai quel luogo sia in rovina."
S["2002b174"] = "Gli occhi di %s si illuminano di rosso mentre accende la dinamite e comincia a sghignazzare come un pazzo!"
S["20070ffb"] = "$GBenvenuto:Benvenuta; da Blue Moon Odds and Ends, $C. Per qualsiasi domanda, chiedi pure."
S["2008db18"] = "Delizioso!"
S["200d28aa"] = "Quelli della nostra specie sono rari di questi tempi, ma tra gli shen'dorei c'è ancora chi sogna in smeraldo.$B$BTieni gli occhi aperti nella foresta. La luce giusta può rivelare ciò che è nascosto, protetto dal vento del nord."
S["2019ff0e"] = "Arriva la Fiera!"
S["201c8068"] = "All'attacco!!"
S["201d02cb"] = "Valstann, ansioso di compiacere il padre, convinse Fandral a lasciargli portare un piccolo battaglione in difesa di Southwind Village. Con le sorti della battaglia a loro favore, di certo nessun male poteva capitare al suo amato figlio. La trappola non fu vista. Valstann fu catturato dai Qiraji nascosti e Southwind Village fu annientato. Rajaxx in persona portò il prigioniero Valstann in prima linea dove, davanti allo Staghelm e alle forze degli elfi della notte, giustiziò brutalmente il giovane elfo."
S["201dc3ce"] = "Scuoiare? L'unica cosa che sembri capace di scuoiare è il tuo ginocchio! Ah! Su, perché non vai da Balthus Stoneflayer? Ti insegnerà lui a scuoiare per bene qualche animale. Lo trovi nella Finespindle's Leather Goods, sul lato nord di The Great Forge."
S["20288156"] = "Dal molo settentrionale puoi imbarcarti su una nave per Rut'theran Village e per Darnassus. Da quello meridionale puoi attraversare il Great Sea fino a Menethil Harbor, a Khaz Modan. Buon viaggio!"
S["2032dab4"] = "%s carica!"
S["203487d8"] = "Guarda il cielo, $C. Da mille anni gli Stormi dei Draghi non si facevano vedere da queste parti! Quei Qiraji tramano qualcosa, me lo sento!"
S["2038e611"] = "Usa la barra delle azioni del tonk, sopra la tua barra delle azioni standard, per attaccare gli altri tonk."
S["203a945f"] = "Spiriti della foresta, c'è bisogno di voi! Affrettatevi verso la Charred Vale!"
S["203bd634"] = "%s segue $N."
S["2042025d"] = "Borgosh! $N è $Gpronto:pronta; per essere $Gaddestrato:addestrata;."
S["204434f6"] = "Insetti!"
S["204f2ac1"] = "A questo punto i miei insegnamenti sarebbero troppo avanzati per te. Se vuoi saperne di più sulle pozioni, parla piuttosto con Tel'Athir, che trovi qui."
S["2054f571"] = "%s lascia il blocco che teneva sulla porta e guarda verso l'esca."
S["20585a7d"] = "Uldaman è all'estremità settentrionale delle Badlands."
S["205a6311"] = "Ah, temo che per ora io e te non abbiamo affari da fare.$B$BSe porterai a termine qualche contratto con l'autorità commerciale, forse più avanti avremo qualcosa di cui parlare."
S["205a998b"] = "La Might of Kalimdor ha vinto! Le ultime forze Qiraji sono state sconfitte e si ritirano nell'antica città-fortezza di Ahn'Qiraj. I Cristalli Risonanti Qiraji sparsi per Kalimdor svaniscono rapidi come sono apparsi, lasciandosi dietro solo terra squarciata."
S["205d93cb"] = "Che succede qui? Lascia stare quella polvere!"
S["206eb298"] = "Un vero professionista sa riconoscere i propri limiti, e non mi vergogno ad ammetterlo: le tue abilità superano le mie. Vorrei che andassi a trovare Kitta Firewind alla Tower of Azora. Ha un'ottima fama, e se la merita tutta."
S["20740e96"] = "Santo Krakle! La temperatura è di 428.000 gradi Kraklenheit!"
S["207a439c"] = "Lanciami!"
S["20808e88"] = "Klaven non mi paga abbastanza per avere a che fare con zombi, droni o come diavolo li chiama."
S["2083fcf0"] = "%s scaglia lo Scepter of the Shifting Sands contro la barriera, mandandolo in frantumi."
S["20921f89"] = "Eccoti un altro carico!"
S["209a65ef"] = "Non lasciarti fregare dagli umani del Bazaar, $Gragazzo:ragazza;: con la metropolitana che hanno costruito quegli gnomi, far arrivare merci da Ironforge è più facile di quanto credi. E se provano ad appiopparti tasse d'importazione, digli che la roba la compri da me."
S["20a9d3e0"] = "Sissignore!"
S["20b37ace"] = "Come il vento sulle pianure, qui sei sempre $Gil benvenuto:la benvenuta;."
S["20b3c9cd"] = "Per assimilare questi dati è fondamentale comprendere che i Creatori intendevano sintetizzare una razza destinata a restare a lungo, dopo la loro partenza, parte integrante del ciclo di sviluppo di questo mondo. Tale razza sarebbe stata determinante per conseguire gli obiettivi di sviluppo a lungo termine che i Creatori avevano per Azeroth.$B$BNota accessoria: sulla base della composizione degli Earthen, i Creatori hanno ritenuto appropriata per la nuova razza la nomenclatura \"Earthen\"."
S["20b8761e"] = "La chiave di questo aggeggio infernale ce l'ha uno degli umani. Mi pare che lo chiamassero Eston."
S["20ba8025"] = "Il Soulflayer arriva!"
S["20c5ee03"] = "Ti preeeego.... HNNGGHH!!"
S["20d9ff75"] = "Restate sulle strade. La foresta è infestata di non morti."
S["20df983f"] = "Figurati se la scheggia ce l'ho io. Sarebbe da idioti. Giro in mezzo ai selvaggi, in questa terra maledetta! Non faccio cinque passi senza che un orco o un umano impazzito provi a piantarmi un bastone appuntito nella pelle. Da un momento all'altro potresti ritrovarti a parlare con il mio fantasma.$B$BComunque... l'ho nascosta.$B$BAvanti... chiedimi dove."
S["20ed0a57"] = "Distruggete subito l'invasore dello Scourge, prima che sia troppo tardi!"
S["20ed766a"] = "La prossima tappa della Darkmoon Faire non è ancora stata decisa, ma quando lo sarà, tu e io saremo i primi a saperlo!"
S["21131857"] = "Queste pianure si tingeranno di sangue tauren!"
S["2114d94d"] = "Salve, giovane Signore. Sono Eva Sarkhoff, e questo è mio marito, Lucien. Piacere di conoscerti."
S["2115a901"] = "Guardati le spalle, $Gstraniero:straniera;."
S["21276942"] = "Siamo i discendenti dei nobili e non ci lasceremo fermare!"
S["2131f4cd"] = "Salve, Charys. Ho la mia lista, potresti procurarmi tutto? Soprattutto l'ultimo ingrediente."
S["21392197"] = "Grazie per avermi liberato, $Gfratello mio:sorella mia;, e grazie a tutti voi! Ora possiamo finalmente riposare in pace."
S["213b2bc4"] = "Sono pezzi pregiati, $N. Comincio subito con la tua veste."
S["214c3049"] = "Tower Point sorveglia il passo fra il Field of Strife e i territori dell'Orda a sud.$B$BÈ controllata dall'Alleanza."
S["21518d82"] = "Da questa parte della valle nessuno vende abiti di stoffa e di cuoio migliori dei miei!"
S["21530f65"] = "Stai in guardia!"
S["2155c807"] = "Abbiamo una grande scorta di rifornimenti per ricostruire la Frostwolf Keep. Ancora un po' e ne avremo abbastanza per fare le riparazioni e tornare in battaglia!"
S["215b58da"] = "%s tracanna il suo drink."
S["2167458b"] = "Che vuoi, pecorone? Sparisci dalla mia vista, prima di scoprire perché mi chiamano l'Incantatore dell'Ira."
S["2169df78"] = "Stavo cercando materiali per costruire la mia ultima e più grande invenzione, il trituratore portatile telecomandato, quando questi troll mi hanno preso a randellate e mi hanno trascinato nelle profondità della loro caverna.$B$BRiportami al sicuro e darò il mio aiuto alla tua causa, $R."
S["217049ea"] = "Sembra proprio che dovrò intervenire e occuparmi di te di persona."
S["2174dadc"] = "Non sappiamo molto sulla storia dell'Excavation Site delle Wetlands, ma sappiamo che una squadra di minatori di pericolosa arroganza tentò di aprire con l'esplosivo un passaggio nelle montagne meridionali che sovrastano Dun Morogh. Una palude dimenticata si trovava all'ombra di un guardiano titanico perduto. Molti sono stati mandati a scoprire che fine abbiano fatto i minatori scomparsi."
S["2179debd"] = "Io do te in pasto al padrone!"
S["2180340e"] = "Vanndar è qui. Forza, piccoli dell'Orda! Fatemi vedere cosa sapete fare!"
S["2189e9fa"] = "$GBenvenuto:Benvenuta; alla Fiera, giovane! Abbiamo raccolto meraviglie da ogni parte del mondo, e sono tutte qui perché tu possa ammirarle. Ah, e se riesci a mettere insieme un mazzo delle carte minori di Darkmoon fammelo sapere, perché il padrone... cioè, a me interesserebbero molto."
S["219807f2"] = "Da qui posso viaggiare più in fretta da $Gsolo:sola;, $N. Raggiungi Jessir Moonbow vicino ad Ashenvale. Dovrebbe essere con i druidi dell'Emerald Circle. Ti dirà lei cosa fare. Grazie mille per il tuo aiuto!"
S["219858e7"] = "Un'altra bella giornata nella giungla! Me lo sento: sarà una gran battuta di caccia. Appena Barnil finisce di pulire i fucili, porto la compagnia nel cuore delle liane intricate. Mica male come pensione, per un vecchio veterano di guerra, eh?"
S["21ac3d8e"] = "Questa settimana potrebbe essere un occhio di tritone, o magari una mappa del tesoro. Non lo saprai mai se non guardi. Cosa avrà Antonio?"
S["21add332"] = "Guidare uno Steam Tank non è cosa da tutti. Servono una presa di ferro e nervi d'acciaio... e per fortuna io ce li ho tutti e due! E tu? Di che tempra sei? Vuoi dimostrarmelo?"
S["21b1a8a2"] = "%s sussurra a $N il segreto per aprire il suo forziere."
S["21b2e7eb"] = "Lo Stonehearth Graveyard è stato conquistato dall'Alleanza!"
S["21b68354"] = "Cosa ti porta all'Earthen Ring?"
S["21cb5d3a"] = "%s ride guardando i parassiti che scappano."
S["21cc3bdb"] = "Ce l'abbiamo fatta! Grazie, $N. Senza di te non sarei mai $Garrivato:arrivata; fin qui."
S["21cf054a"] = "Devi essere in rapporti amichevoli con gli gnomi degli Gnomeregan Exiles prima che io ti insegni a guidare un Mechanostrider, $C."
S["21dfd65d"] = "È nel Trade District, $Gcittadino:cittadina;. Dall'ingresso di Stormwind ci arrivi andando quasi sempre dritto."
S["21ede8f2"] = "Dovrai dimostrare di esserne $Gdegno:degna; prima che io vada a regalare i miei segreti! Ho proprio la prova che fa per te..."
S["21f83532"] = "Salve, $Gsoldato:soldatessa;. L'intelligence ha riferito che i troll Winterax a ovest hanno fatto prigioniero un maestro ingegnere goblin. Forse dovresti indagare?"
S["21feaec4"] = "Sei davvero $Gdiventato uno dei migliori sarti:diventata una delle migliori sarte; del mestiere! Congratulazioni, sono $Gorgoglioso:orgogliosa; di essere $Gstato il tuo istruttore:stata la tua istruttrice;!"
S["2206e9f1"] = "Se riesci a completare un mazzo di carte dei signori della guerra, avrai in premio una carta superiore dell'eroismo di Lunacupa: ogni tanto ti curerà mentre combatti in mischia."
S["220ce803"] = "È bello vederti, $N. La nostra guerra contro gli altri signori elementali infuria ancora, ma i tuoi sforzi ci aiutano a garantirci la vittoria."
S["22109d52"] = "%s posa a terra la cassa dei pezzi."
S["2211087d"] = "Aiutami a scegliere con saggezza."
S["22133b4c"] = "E poi il coniglio gli ha staccato la testa con un morso... lo giuro."
S["221d955d"] = "Ora cerchiamo l'erba."
S["221f9228"] = "Elder Moonwarden tiene d'occhio il Crossroads nella Barrens."
S["222eb24b"] = "È davvero un'ottima arma, $N. Guidi gli spiriti come pochi altri che io abbia mai conosciuto. Ascoltali, e loro guideranno te come tu hai guidato loro. Va', cerca l'Orco conosciuto come Kelgruk Bloodaxe. Non parla con gli spiriti, ma li ascolta, e le sue armi sono le migliori su cui io abbia mai posato gli occhi."
S["2236cd21"] = "Persino i Windshapers ti direbbero che gli spiriti non hanno mai parlato con rispetto di un essere supremo fra loro. Ammettevano che esistesse un essere chiamato Al'Akir, ma evitavano di pronunciarne il nome, quasi lo temessero.$B$BE anche se questo Al'Akir fosse un \"Signore del Vento\" onnipotente, sovrano degli elementali dell'aria, è stato proprio l'affidarci agli elementali a cacciarci in questo guaio. Ora dobbiamo tirarcene fuori da soli."
S["223e598e"] = "$N, me ne vado prima che una di queste bestie mi prenda in simpatia!"
S["224299cf"] = "Usa bastone, dire a Raze cosa fare! Mostra a Raze bracconiere! Raze spacca!"
S["22482411"] = "L'altare risplende! Ce l'abbiamo fatta!"
S["224d6358"] = "%s emette un lungo, profondo sospiro."
S["224f6dc0"] = "Persino qui, nelle terre selvagge, cerchi di imparare. La tua sete di conoscenza è una dote ammirevole."
S["2258f594"] = "Quando vuoi, puoi ringraziarmi per averti reso la vita più interessante."
S["225b310a"] = "Bada a come ti comporti al cospetto del Capoguerra, $C. I Kor'kron non tollereranno insolenze né offese, qui."
S["225f61be"] = "Sento un pericolo più avanti."
S["2263b023"] = "$GBenvenuto:Benvenuta; alla Great Forge, $Gragazzo:ragazza;. Fuori farà pure freddo, ma quaggiù lo teniamo bello caldo. Prendi un martello, batti su quell'incudine e fammi vedere che hai la stoffa per essere $Gun:una; Fabbro della Great Forge!"
S["226eb199"] = "Bella fattura, $N. Scommetto un boccale pieno all'Angolo di Bruuk che è altrettanto solida all'uso. Sai, forse dovresti parlare con Myolor Sunderfury. Ti metterà sulla strada giusta."
S["22789c5f"] = "Niente male, per $Gun principiante:una principiante;! Credo che mostrarti un paio di cose non sia un problema..."
S["2280205a"] = "%s raggiunge di corsa gli altri operai del ponte, ansimando."
S["22814cd6"] = "EVVIVA! SONO SALVO!"
S["2287cbbf"] = "È tutto raccolto, $C. Viene tutto trasportato a Silithus per i preparativi finali e dovrebbe arrivare entro un giorno. Tutte le nostre forze unite aspettano $Gl'eroe:l'eroina; che completerà la riunificazione dello Scepter of the Shifting Sands, suonerà il gong e darà inizio alla guerra di Ahn'Qiraj."
S["229cb10a"] = "Ah, ehm, sì, $Gsignore:signora;. Pare che abbiamo raccolto tutto il cuoio medio che l'Alleanza ritiene necessario per la guerra. Mi dicono però che qui potrebbero esserci altri che hanno ancora bisogno del tuo aiuto con le loro raccolte."
S["229ddb7c"] = "%s si gratta la gola."
S["22a190ac"] = "Il tuo spietato disprezzo per la potenza sovrana del Gurubashi Empire è stato notato. Gli abitanti di Zul'Gurub sono stati avvertiti della tua presenza."
S["22a393b9"] = "Non farmi arrabbiare! Non ti piacerei quando sono $Garrabbiato:arrabbiata;!"
S["22b3a22d"] = "Verranno evocati gli abitanti delle terre del fuoco. Quando compariranno, $Gattento:attenta; a non fare movimenti bruschi."
S["22b7426a"] = "Devi parlare con Innkeeper Norman, sull'anello superiore del Trade Quarter."
S["22bcdafe"] = "Ti porgo un cordiale saluto, $R. Ti sei $Gspinto:spinta; ben lontano dai sentieri battuti solo per parlare con uno che dimora in una grotta. Questa tua visita è strana, eppure non imprevista: confido che abbia una ragione. Sì?"
S["22c5bf67"] = "Finalmente! Naralex si sta risvegliando dall'incubo."
S["22d52dff"] = "Questa pianta di fiordivento spicca come un faro nel buio del Felwood. Dalla pianta pendono bacche grosse e succose, pronte da cogliere."
S["22d580e9"] = "MESSAGGIO DI PROVA INCANTESIMO FITTIZIO"
S["22d697e2"] = "Le bevande migliori di Stormwind!"
S["22e1391f"] = "Il padrone è caduto! Vendicatelo, fratelli miei!"
S["22e5fa2d"] = "L'Istruttrice dei Ladri si chiama Marion Call: la trovi al piano di sopra, nella sala di lettura della Gallows' End Tavern, all'estremità sudorientale della città."
S["22ea54bc"] = "<Valennia sussulta di dolore mentre si muove per guardarti.>$B$BNon guardarmi così. Starò bene. Nonostante i migliori sforzi degli ansiosi guaritori del Sommo Anziano, sarò di nuovo in piedi e pronta a combattere in un batter d'occhio.$B$BOra vattene... non lasciare che questa vecchia soldatessa ti trattenga. I venti ti porteranno fortuna nel tuo viaggio, lo so."
S["22fc3020"] = "Grazie per la pazienza, $N."
S["22fd187d"] = "Bello qui, non pensi? Ci è voluto del tempo, ma ci siamo fatti una bella casa."
S["23054cef"] = "Ne esistono altri mille come lui. Diecimila. Se uno cade, un altro si alzerà a prendere il suo posto al potere."
S["23062a40"] = "*sospira* È ora di ricontrollare il cimitero — torno fra qualche minuto."
S["230be9d3"] = "Il momento che C'Thun aveva atteso con tanta pazienza era finalmente arrivato. I suoi figli avevano passato migliaia di anni a costruire un esercito capace di vendicarsi su tutta Kalimdor, e ora il premio era a portata di mano."
S["230fd5ea"] = "La nostra scorta di equipaggiamento cresce!"
S["23229d9e"] = "%s sputa per terra."
S["23235f4a"] = "L'ultimo santuario di fanatici impazziti. È lì che fanno le loro uniformi scarlatte, infuse di magia dall'enchanted scarlet thread!$B$BA Stratholme, $Gavventuriero:avventuriera;!"
S["2332689d"] = "Beh, fai passi da gigante! Quello che posso insegnarti lo sai già, ma Springspindle Fizzlegear di sicuro ha ancora qualcosa da insegnarti! Springspindle lo trovi a Ironforge. Buona fortuna!"
S["2336e690"] = "Mmm, mmm, mmm. Senti che profumo?! Questa sì che è roba buona da mangiare, $C. La Rainbow Fin Albacore non delude mai. Sono Slicky Gastronome, gran conoscitore di tutto ciò che è commestibile, pesce soprattutto. Con la Guerra di Ahn'Qiraj alle porte, l'Alleanza ha pensato bene di chiamare un esperto per lo sforzo bellico, ed eccomi qui, grande, grosso e al comando.$B$BPare che di questo pesce ce ne servirà un tot, e per ora ne abbiamo messo da parte un mucchio."
S["2337e7e4"] = "Parlami della promozione della confezione regalo iCoke."
S["23384677"] = "Fatti un bicchiere, $C. Potrebbe essere l'ultimo!"
S["234b39a5"] = "Chi osa intromettersi negli affari della Defias Brotherhood? Muori, $C!"
S["234dca0a"] = "È Shelene Rhobart. Esci da Brill con la strada verso sud-est e all'incrocio gira a est. Sta in un accampamento a bordo strada."
S["234f4914"] = "Chiudo tra poco, quindi compra finché puoi!"
S["23529933"] = "Dovevate restare a casa."
S["2357d5c2"] = "Oh, tanto dolore..."
S["2358763d"] = "L'Orda ha raccolto risorse ed è vicina alla vittoria!"
S["235a691f"] = "%s salmodia in una lingua sconosciuta."
S["23681099"] = "Lorthuna! Ferma questa follia. Non sai cosa succederà se abbatti le protezioni che custodiscono Zephras. Potresti condannarci tutti!"
S["2368e70c"] = "Ehi, attento con quel kodo! Faresti meglio a esaminare quella bestia prima che ti dia il merito!"
S["2369ef99"] = "EHI! Non vale!"
S["236b98cb"] = "È fatta..."
S["2370dafe"] = "Al momento giusto dovrai immergere la torcia nella fiamma eterna e catturarla."
S["2376ec63"] = "Davvero... un vestito delizioso, Jessica."
S["23859d64"] = "Oh cielo! Guarda qui... tutte queste candele. Di sicuro servono per qualche rituale orribile o un'evocazione oscura. Meglio sbrigarci!"
S["2397ec74"] = "Tutto il pesce e il resto sono in viaggio verso Silithus e dovrebbero arrivare lì in meno di un giorno. Dopo di che qualcuno dovrà suonare quel gong con lo Scepter of the Shifting Sands per far cominciare la guerra."
S["2399f5b5"] = "Buon acciaio, $N. Prendi un martello e vieni qui: lascia che ti mostri il segreto per forgiare un'arma leggendaria."
S["239b2382"] = "La mia gente è a pezzi, come la reliquia che cerchi di riparare."
S["239e47fe"] = "Se sei qui, significa che sei $Gpronto:pronta; a cominciare lo studio dell'evocazione di servitori demoniaci che eseguano i tuoi ordini. Inizieremo dalle creature più umili che sarai in grado di richiamare e poi proseguiremo. Cominciamo."
S["23a196f3"] = "Che vuoi?"
S["23a202f0"] = "Usa questo Staff of Command su Raze quando sei vicino agli Shadowsilk Poachers, e lui farà loro rimpiangere il giorno in cui hanno deciso di cacciare di frodo in queste terre."
S["23a46150"] = "L'Alleanza vince!"
S["23ac9ec5"] = "Raze dovere andare casa adesso. Ciao ciao, $R."
S["23af9c8c"] = "Salve, $Gamico:amica;. C'è qualcosa fra le mie forniture per artigiani che ti interessa?"
S["23bad3a3"] = "Non ho tempo da perdere, $C; c'è una guerra da preparare ad Ahn'Qiraj. Se vuoi aiutare, stiamo raccogliendo singed corestones dal Molten Core. Devo raggiungere il totale stabilito, e per ora non ci siamo ancora."
S["23bdf1fa"] = "Imbarcati qui per raggiungere la Dalaran City, adagiata fra le Alterac Mountains."
S["23be76bc"] = "Io sono il fuoco eterno. Rinasco per sempre e sarò la luce che ti guiderà quando farà più freddo."
S["23c4931d"] = "Tutto è stato raccolto, $C. Tutto viene trasportato a Silithus per i preparativi finali e dovrebbe arrivare entro pochi giorni. Tutte le nostre forze unite attendono l'eroina che completerà la riunificazione dello Scepter of the Shifting Sands, suonerà il gong e darà inizio alla Guerra di Ahn'Qiraj."
S["23ca174a"] = "Ce l'hai un po' di talento nel forgiare armi, $Gragazzo:ragazza;, davvero notevole. Ora prendi un martello e vediamo se sai forgiare una vera arma."
S["23d56812"] = "Miranda, potresti dirmi quante insegne costano gli oggetti che offri agli avventurieri con reputazione onorata?"
S["23d68c06"] = "Ah, il buon vecchio Brandur Ironhammer. Di sicuro ti darà i consigli che cerchi, $Gragazzo:ragazza;. Lo trovi nell'Hall of Mysteries, a nord delle porte di Ironforge."
S["23e08747"] = "Sento... qualcosa di strano..."
S["23e6e258"] = "Credevo che dovessi proteggermi tu!"
S["23f22be1"] = "$GAttento:Attenta; a dove metti i piedi, soldato. Gli Stormpike hanno disseminato di mine il terreno intorno alle loro basi. Parla con il nostro esperto di esplosivi nella torre di guardia a est se vuoi sapere come disinnescare i loro campi minati."
S["23f53403"] = "Secondo Thrall la minaccia principale da affrontare è la Burning Blade — membri dell'Orda che hanno giurato fedeltà ai demoni. Vogliono praticare la magia oscura, e di come Thrall vede il futuro dell'Orda qui a Kalimdor gli importa poco."
S["24064a31"] = "Io no, ma tanti altri cercano l'amore. Dovresti comprare i miei love tokens, metterti un po' di colonia o di profumo e andarli a distribuire in giro!"
S["240b9b1d"] = "Credo che Elder Splitrock sia andato a Mauradon, nella Desolace."
S["2410d2a7"] = "Qui dentro $Gattento:attenta; a dove metti i piedi, $Gragazzo:ragazza;. Il maestro vede tutto..."
S["2411c12d"] = "Lo sentite, creature patetiche? La coltre su questa terra è solo un presagio. Presto i vostri preziosi possedimenti saranno nelle nostre mani! Cadrete davanti alla potenza dello Scourge!"
S["241792b6"] = "Che hai da guardare, ragazzo?"
S["241e9c96"] = "Che hai da guardare, ragazza?"
S["2421e174"] = "Sei $Gcongedato:congedata;, Externí."
S["24230908"] = "Eh, beh, fin qui ci sei $Garrivato:arrivata;... va' da Lavinia Crowe, là vicino all'altra libreria. Se con lei non combini pasticci, forse impari qualcos'altro."
S["2428d651"] = "I silithid non sono all'altezza dei figli e delle figlie di Orgrimmar. Presto di loro non resteranno che zampe e ali schiacciate sotto i nostri piedi, $N."
S["243058ea"] = "Oh, queste cose? Le ho costruite io, con l'aiuto dei miei piccoli amici. Non ho una gran memoria, però, ehm, so che un tempo costruivo un sacco di cose. Cose grandi! Ma poi, come ho detto... ero qui. Adesso quello che costruisco non è più così grande e impressionante. Però mi rende ancora f-felice, eh.$B$BM-ma... se vuoi, posso insegnare anche a te a costruire cose!"
S["2433649f"] = "Non abbiamo tempo da perdere. La strada è davvero lunga! Coprimi!"
S["2439b2a1"] = "Dai un pesce a un toro e lo sfamerai per un giorno. Insegnagli a pescare e lo sfamerai per tutta la vita. A pescare può insegnarti Uthan Stillwater. Cerca la sua saggezza a ovest di Bloodhoof Village, sulle rive dello Stonebull Lake."
S["243b2b5d"] = "Sei $Gconsiderato:considerata; una minaccia!"
S["243c07f1"] = "Padrone, la tua saggezza è pari solo alla tua enormità!"
S["243f789c"] = "Mancano 10 secondi all'esplosione! Indietro!!!"
S["24421dd4"] = "Buongiorno, $Gcittadino:cittadina;. Sei $Gvenuto:venuta; ad aiutarci contro lo Scourge?"
S["2447e279"] = "$N, bisogna schiacciare le Silverwing Sentinels! Sei $Gpronto:pronta; per la Warsong Gulch?"
S["24482ffb"] = "Sì? Certo che sono un fabbro. Che c'è, credi che solo i Nani valgano tante incudini quanto pesano? Va bene, fa' come ti pare. Va' a farti aiutare da un nano!"
S["2448b0a7"] = "Mi hai mostrato il tuo desiderio e hai pagato con una pietra preziosa. Ti insegnerò..."
S["244ce0bd"] = "Sono... sono $Gferito:ferita; gravemente..."
S["244f494e"] = "The Scarlet Crusade della Tyr's Hand, nelle Eastern Plaguelands, ha molte casse chiuse che metteranno alla prova la tua abilità."
S["2452c296"] = "Hai l'aria da Fabbro, tu: fuliggine sotto le unghie e acciaio nelle ossa. Eh già, hai proprio sangue da Fabbro nelle vene. Quindi sei $Gvenuto:venuta; da me per imparare un paio di cose. Be', $Gragazzo:ragazza;, prendi un martello e vediamo cosa posso insegnarti."
S["2459cde2"] = "Noi, l'Alleanza, prevarremo!"
S["245b043b"] = "Ti ringrazio, $N. I miei soci, che faranno grandi cose con questi..."
S["245ff1a5"] = "Ti invidio, davvero: tu combatti in nome dell'Orda, in prima linea nel conflitto. Il mio compito invece è comandare.$B$BCerto, da giovane ho vissuto i sogni che rendono sopportabile la vecchiaia. Ora la gloria della vittoria e il sapore amaro della sconfitta me li godo — tutto attraverso i soldati che comando."
S["246e6702"] = "La Frostwolf Keep si trova nell'angolo meridionale dell'Alterac Valley e protegge il Frostwolf Village, casa del clan di orchi che porta lo stesso nome. Tutti i territori dell'Orda nell'Alterac Valley nascono da questo unico luogo di potere.$B$BLa Frostwolf Keep è stata rasa al suolo ed è in ricostruzione."
S["247c71b2"] = "Ho sentito che Deneb Walker, che se ne sta rintanato a Stromgarde, ha un libro che ti aiuterà di sicuro a migliorare le tecniche di First Aid."
S["2480133a"] = "Diventa il mentore di uno dei nostri orfani durante la Settimana dei Guardiani! Urrà!"
S["248ad0f0"] = "<Riaani sembra tutto preso dal lavoro sul costrutto del vento.>"
S["248c5ed4"] = "Che gli spiriti siano con te."
S["249561a5"] = "Dopo questa, faremo nuove tacche sulle nostre asce."
S["24a99e5c"] = "Ti ho dato tutto ciò che so, $N. Che la fortuna ti accompagni."
S["24b41f9c"] = "Osi sfidare il compito del Blue Dragonflight? MUORI, verme."
S["24bbdbd5"] = "Ti spaccherò il cranio!"
S["24c17519"] = "Ricordare la mia bellezza rende insopportabile averla perduta!"
S["24c56e1a"] = "In base al campione di tossina che ci hai portato, crediamo che ti servirà questo: un arcane quickener, quattro ectoplasmic resonators e quattro pezzi di runecloth. Porta con te il vitreous focuser e prendi i risonatori dagli spettri e dai non morti fantasma qui nelle Plaguelands!$B$BQuando avrai tutto, dovresti riuscire a caricare l'antidoto in quel calderone."
S["24dad038"] = "$N ha assaltato le stalle!"
S["24dcc528"] = "Dove posso mandarti oggi, $C?"
S["24dd0567"] = "<Lo Skyborne disteso davanti a te è privo di sensi.>"
S["24e0efb9"] = "Master Woo Ping padroneggia quasi ogni arma conosciuta dall'uomo, e con le sue tecniche di spada è particolarmente letale. Se ti serve un po' di addestramento, lo trovi spesso al Weller's Arsenal, in attesa di nuovi carichi di armi."
S["24ea83c0"] = "Sento la presenza del male che se ne va..."
S["24ea8d93"] = "Questo chiaro di luna ti porterà a Thunder Bluff. Usalo quando vorrai andartene dal festival."
S["24eae207"] = "Forse un giorno avrai fatto per l'Alleanza quanto gli eroi che hai visto oggi. Rendi loro onore, $N."
S["24ee863a"] = "Su terrazza bassa di Thunder Bluff sta Ansekhwa, il maestro d'armi tauren. Lui insegnare mazze a una e due mani, bastoni e fucili.$B$BNel War Quarter dell'Undercity c'è Archibald, il maestro d'armi non morto: lui insegnare bene balestre, pugnali, spade a una e due mani e armi ad asta.$B$BQui c'è Sayoc, quel brutto orco: lui può insegnarti archi, pugnali, armi da pugno, asce a una e due mani e armi da lancio, mon."
S["250750ec"] = "Guse si unisce alla battaglia! È ora di far fuori quella feccia degli Stormpike!"
S["2508116f"] = "La gara comincia fra 1 minuto!"
S["250cea26"] = "Finalmente! Non vedo l'ora di andarmene da questo posto."
S["251ee292"] = "Ahi. Piccante."
S["253be7e0"] = "...e i Windshapers. Siamo pronti ad appoggiare un assalto al Santuario, Valennia."
S["2541526d"] = "Su, fila a Orgrimmar, $N. Salutami Thrall!"
S["25473511"] = "Ah, $Gamico:amica;, io aiuto solo i cacciatori e i loro animali."
S["25482802"] = "%s sarà innescata tra 5 secondi!"
S["25519e52"] = "Quell'istruttore lo trovi nella Crafter's Hall, sul lato ovest di Valanaar."
S["2562da47"] = "Ehm... Capo, io dispiace che io attacca te. Per favore tu non uccide me, OK!? Adesso tu $Gil re:la regina;, e io aiuta fare migliore tuo tributo!"
S["256328f0"] = "PE' IL RE! Ricacciateli indietro, soldati!"
S["256442ca"] = "Questo atto di sfida non resterà impunito. Tu e il tuo mondo morirete!"
S["256b776e"] = "Libera il Rabid Thistle Bear per Tharnariun."
S["2573ca0e"] = "Elder Bloodhoof lo trovi a Bloodhoof Village, nel Mulgore."
S["2574e515"] = "Ciao, cosa prendi?"
S["25786f2c"] = "Hai ucciso Ghost Howl. Sei $Gun grande:una grande;!"
S["2583270c"] = "Un giorno sarò un bambino vero."
S["258444ba"] = "Mandare assalti di terra richiede enormi quantità di rifornimenti!"
S["259f8de9"] = "Che devastazione... che disastro orribile..."
S["25a19bd7"] = "Noi entrare in gilda? No? Ok, tu trovare Maestro di Gilda su piattaforma est di Trade Quarter."
S["25a1c892"] = "Guardando meglio il pilone, trovi un piccolo tavolo con sopra dei cristalli blu, gialli e verdi, disposti in quella che sembra una formazione precisa.$B$BAccanto a un grande cerchio di cristalli blu c'è, da un lato, un cerchio più piccolo di cristalli gialli e, dall'altro, uno di cristalli verdi.$B$BTi annoti con cura i colori dei cristalli, perché sai che a J.D. interesserà molto sentire cosa hai trovato."
S["25a1edf6"] = "State fermi!"
S["25a5c400"] = "%s indica con disinvoltura il bersaglio a forma di orco..."
S["25b909ad"] = "|cffffff00La Guard Tower della Corona è stata conquistata dall'Alleanza!|r"
S["25c2f5b9"] = "$GBen trovato:Ben trovata;, $C. Vuoi un consiglio? Fai amicizia con un mago! Qualche asso nella manica ce l'abbiamo, eccome..."
S["25caa0db"] = "Salve, $C $R. Sono Commander Stronghammer e qui faccio da ambasciatore per l'Alleanza. Se vuoi sapere a che punto sono le raccolte dell'Alleanza per la guerra di Ahn'Qiraj, ragazza, chiedi pure senza problemi."
S["25cf47ff"] = "Non stai solo facendo perdere tempo ai tuoi compagni di studio, stai facendo perdere tempo anche a me."
S["25d1bceb"] = "Che piacere rivederti, $N. Grazie al tuo aiuto, le nostre linee di rifornimento sono molto più sicure. Spero che tu capisca quanto conti la logistica in grandi operazioni militari come questa."
S["25d90b60"] = "Shadowgale Forest!$B$BÈ infestata! Infestata, quant'è vero che il cielo è blu! Spiriti della foresta spaventosi, uccelli del terrore con artigli grossi come il tuo braccio! È... un incubo!$B$B<Swimmers si gira verso Donaal e fa un rutto rumoroso.>$B$BNON SONO DISCORSI DA PAZZI, DONAAL!"
S["25dae66d"] = "Il culto Al'Aketh sta diventando un problema serio, e contro di loro le peacekeepers sembrano impotenti. Possiamo solo sperare che i Windshapers e l'High Order la smettano di bisticciare e collaborino con le peacekeepers per proteggerci.$B$BIo in un culto non ci voglio entrare di sicuro!"
S["25e1192b"] = "L'armatura della Redenzione la indossavano i nostri cavalieri più devoti — un'armatura degna del Portatore di Luce in persona!$B$BNell'ultima guerra ne sono caduti a migliaia; le loro vesti, strappate dai cadaveri, sono state portate nella temibile cittadella di Naxxramas.$B$BSi dice che i cavalieri della morte di Naxxramas corrompano la corazza di piastre della Redenzione per servirsene.$B$BChe tragedia..."
S["25ea4a68"] = "Cosa posso fare per te?"
S["25eb49c4"] = "Speravamo in più rinforzi, ma dovremo accontentarci. Avanti!"
S["25eea723"] = "Lo avete deluso, mortaliii... Addio!"
S["25f49564"] = "Tutti abbiamo visto tragedie terribili, ma non dobbiamo lasciarci trascinare nella disperazione.$B$BPiuttosto, quei ricordi tienili stretti, perché un giorno possiamo avere la nostra resa dei conti."
S["25f776e2"] = "Cosa posso fare per te, $Gcompagno:compagna; windshaper?"
S["25ff8bd3"] = "Vorfalk"
S["26000f22"] = "%s inizia a lanciare un controincantesimo..."
S["260d3d01"] = "Mi hai già reso un grande servigio, $N, e per questo ti ringrazio.$B$BIl minimo che possa fare adesso è raccontarti cosa mi ha portata qui. Il mio vecchio amico Trey Lightforge e io eravamo venuti a Jaedenar per indagare sullo Shadow Council, quando ci hanno colti alla sprovvista. Hanno portato Trey più in profondità nello Shadow Hold e, dopo averci preso tutto l'equipaggiamento, mi hanno rinchiusa qui... Sento ancora le sue urla da laggiù, $N. Erano... disumane. Non so cosa gli abbiano fatto, ma la pagheranno."
S["26138633"] = "*Dimitri si asciuga il sudore dalla fronte e posa gli attrezzi*"
S["261d5486"] = "I pagani saranno costretti a reagire. Orchi, uomini-toro..."
S["26211071"] = "Beh, forse \"pagare\" non è la parola giusta. Vedi, mentre ero $Gbloccato:bloccata; nella pancia di quella cosa, mi sono $Gmesso:messa; a pensare:$B$BQuesta creatura vive nel magma rovente, infuocato, eppure il fuoco non le fa nemmeno un graffio!$B$BSe solo riuscissi a trovare una pristine hide di una di queste bestie, potrei portarla al mio caro amico Malyfous Darkhammer, a Everlook. Se c'è qualcuno capace di tirar fuori qualcosa dalla pelle di una bestia così, è proprio lui."
S["2623a9b2"] = "%s lancia un ruggito profondo, allerta gli alleati vicini e va su tutte le furie!"
S["2625bd81"] = "%s ride istericamente."
S["26286174"] = "PROMETTO CHE STAVOLTA NON TI AMMAZZO L'EQUIPAGGIO. AH! MA MIO FRATELLO POTREBBE MANGIARSELO!"
S["262fe008"] = "punto di conquista Contested1"
S["262fe009"] = "punto di conquista Contested2"
S["26304496"] = "$GBenvenuto:Benvenuta; nella mia bottega. Cosa posso fare per te?"
S["26476a69"] = "Ce l'abbiamo fatta ad arrivare a Nethergarde!"
S["264cbbc0"] = "La Bandiera dell'Alleanza è stata riportata alla sua base da $N!"
S["264d972d"] = "Aspetta, sì... questo cristallo! Valennia, è forse..."
S["264f883e"] = "Stiamo facendo la strada panoramica?"
S["26509dbe"] = "L'offerta è stata accettata. Ora, $N, avvicina la torcia alla fiamma!"
S["265fffe2"] = "Spero che tu sia $Gpronto:pronta;, $N. Seguimi."
S["26679230"] = "Piegati al volere del signore del vento e implora il suo perdono!"
S["2670cbab"] = "Lo Scourge è all'ingresso del Royal Quarter! Uccideteli!!"
S["26732f25"] = "Fai un buon lavoro, ma è ancora un po' grezzo. Non preoccuparti, migliorerà con la pratica. A proposito, che ne dici di vedere a cosa hai lavorato?"
S["267554e7"] = "Non lasceremo impunito questo atto di follia!"
S["26793f7e"] = "Ne hanno aperto uno sulla Tradesman's Terrace. Se dalla banca prendi il sentiero che va a sud-est, dovresti trovarlo facilmente."
S["267cbc7b"] = "Ogni ritaglio che usiamo ci rende meno spreconi e ci porta più vicino alla Madre Terra. Mooranta può mostrarti la via: la trovi appena fuori dai Thunder Bluff Armorers, sull'altura di mezzo."
S["2681cfb0"] = "Un istruttore di professione"
S["2686eac6"] = "La furia di Ishamuhale scorre in te, $N."
S["2688e663"] = "Venite, fratelli."
S["26986694"] = "I Cavalieri di Jeztor sono pronti! Soldati dell'Orda, presentatevi in servizio!"
S["26b05311"] = "Dirge Quikcleave di Gadgetzan è un maestro dell'arte culinaria: se vuoi migliorare, dovrai andare a cercarlo."
S["26be082a"] = "Hai preso la decisione giusta, $C. Troverai il nostro maestro delle battaglie, Glordrum Steelbeard, nell'Hall of Arms. Buona fortuna, $N!"
S["26bf1a59"] = "Adesso tu capo, eh? Lunga vita a $Gnuovo re:nuova regina;!$B$BKreeg fa vedere a te grappa Gordok. Grappa di Ogre meglio di tutte grappe, e grappa Gordok meglio di tutte grappe di ogre! Tu forse compra un po' da me, eh capo?!"
S["26c14851"] = "I Gordunni Ogres stanno invadendo le nostre terre. Mandiamo fra le rovine profanate di Feralas chiunque sia disposto ad affrontarli."
S["26cc0865"] = "Shhh... finirà tutto presto."
S["26d38aa5"] = "Che dolce ironia: le forze di Stormwind, abbattute in difesa della loro città, si rialzano per combattere al fianco della Fratellanza come strumenti di distruzione."
S["26dba4c1"] = "Nell'Elwynn Forest l'unico che chiamerei un sarto è Eldrin. Se ti interessa imparare il mestiere, lo trovi all'Eastvale Lumber Camp."
S["26e2845a"] = "La battaglia è finita e gli abitanti di Darrowshire sono salvi.$B$BE se sono salvi, $N, è grazie a te. Sei $Gun vero eroe:una vera eroina; di Darrowshire."
S["26e72de7"] = "Sono a Dalaran su invito, per conto del Cenarion Circle. Lo trovo un posto tanto meraviglioso... quanto inquietante.$B$BQuanto a te, giovane $C — se non l'hai già fatto, cerca Sheldras Moontree a Stormwind. Ti insegnerà come arrivare all'enclave del Cenarion Circle a Moonglade."
S["26eb805a"] = "Non puoi usare una cavalcatura in quella forma."
S["26ecafcf"] = "Parlami della Frostwolf Keep."
S["26f5a146"] = "Le mie wind riders sono addestrate per volare veloci nell'aria calda delle Barrens."
S["26f5c899"] = "Zenn nagas za kamil Kirasath za azgala, archim. Lok lek adare lok aman raka za kamil za soran re lok faralos rethul? Enkilzar rakkas..."
S["26f768a8"] = "Ecco! La Taverna Azzurra dà un banchetto in suo onore!"
S["26f7f1ba"] = "Oh... mi sento svenire..."
S["26f877d9"] = "Quando usiamo le pelli degli animali che dobbiamo abbattere per nutrirci o per proteggerci, onoriamo la Madre Terra e rispettiamo l'animale. Queste cose può insegnartele Chaw Stronghide: lo troverai nella grande tenda nell'angolo nord-occidentale di Bloodhoof Village."
S["26fae441"] = "Che c'è adesso, $C, non ho tutto il giorno? L'Orda ha completato le sue raccolte e ora aspetta solo che l'Alleanza si organizzi e faccia lo stesso. Forse dovresti essere là fuori a cercare i pezzi dello Scepter of the Shifting Sands, così da poter suonare il gong alla Scarab Dais, aprire i cancelli di Ahn'Qiraj e dare così inizio alla guerra?"
S["26fee00f"] = "Senti grande voodoo cattivo!"
S["270aa0e3"] = "L'Hall of Spirits è la casa dei nostri sciamani: la trovi sulla Spirit Rise. Che i tuoi antenati veglino su di te."
S["270b38ba"] = "<Il cavallo nitrisce piano quando ti avvicini.>"
S["270dacda"] = "<Sul cartellino del meccanostrider c'è scritto:$B$BCrimson-Blastdasher XL 300. Ora con più aderenza sul terreno e un nuovo, elegante colore!>"
S["2712aed7"] = "Unisciti a me, fratello, c'è sangue da versare!"
S["2723e47e"] = "Ti avverto: persino i tuoi creatori sono fallibili."
S["272d36f7"] = "Su, mettiti a sedere vicino al fuoco, così possiamo cominciare."
S["27309766"] = "Questo è vuoto!!"
S["2741e746"] = "%s va in frenesia!"
S["274dc252"] = "La mia famiglia lavorava a Northridge Lumber Mill, in quelle che oggi sono le Western Plaguelands. Erano fedeli alla famiglia Dumah, e ora la Scarlet Crusade l'ha occupata, insieme a tutta Hearthglen!$B$BNon avrò pace finché quei fanatici non saranno spazzati via da Azeroth."
S["27637e40"] = "$GSignore:Signora;, se non sapessi come stanno le cose, direi che sei $Guno:una; di 'sti tipi \"speciali\". Noi li chiamiamo Troggs.$B$BWindsor mica ce l'aveva coi Dark Irons: dopotutto, il migliore amico del suo bis-bis-nonnetto era un Dark Iron. Ed è pure il motivo, probabile, per cui quell'esercito di Dark Irons non l'ha ammazzato a vista."
S["27660fc7"] = "Come un gatto trascinato al riparo dalla pioggia, graffi e artigli, e poi di nuovo tutto da capo... Tornerò a prenderne ancora...$B$BOh, non ti avevo visto entrare, $N! Cosa posso fare per te?"
S["276ca5fb"] = "La prossima volta porta più amici!"
S["2771d5ee"] = "Se non lascerai l'Alterac Valley da $Gsolo:sola;, i Frostwolf ti cacceranno con la forza!"
S["2779c775"] = "Daz melar archim gul revos re gul ante?"
S["277fd54b"] = "Quando arriverà, saremo pronti."
S["278ca4b8"] = "Schiaccio deboli come te tutti i giorni! Fatti sotto!"
S["2797afb6"] = "%s è $Gstordito:stordita;"
S["2799f89b"] = "Ma dai, non è vero."
S["27a4ed3b"] = "E l'ha trovata eccome. Ras è salito in fretta nei ranghi del Culto, e The Lich King in persona gli ha concesso l'immortalità. È così che è nato il lich Ras Frostwhisper.$B$BOra capisci?"
S["27afc30b"] = "Tu impugni la lama di mio padre, $N. I miei soldati sono ai tuoi ordini, $Gmio signore:mia signora;. Prendili... Guidali... Gli impuri vanno epurati. Devono essere purificati dalla loro corruzione."
S["27b7a41d"] = "Che cosa patetica. Sono intriso del potere del Soulflayer. Non temo nulla se non l'ira dell'onnipotente Hakkar. Non servo nessuno se non il mio padrone, Jin."
S["27bb6fc7"] = "$GBenvenuto:Benvenuta;! Avanti, fatti sotto, non essere $Gtimido:timida;. Ecco il mio orgoglio... il Blastenheimer 5000 Ultra Cannon! Non è una bellezza? Sei un po' $Glargo:larga; di girovita, ma secondo me ci entri. Volare è divertentissimo: vuoi imparare come si fa?"
S["27bf1db2"] = "Attenzione, eccone altri!"
S["27c19185"] = "Tragico. Il vecchio Fordring è ancora vivo... Sei arrivato troppo tardi, vecchio. Torna nella tua caverna, eremita, a meno che tu non voglia raggiungere tuo figlio nel Twisting Nether."
S["27c9f722"] = "The Thorium Brotherhood non ha tempo da perdere con le formiche. Sparisci!"
S["27cdfb07"] = "Haldir, algaz dum zu gar eft loch kaelsag gar havar."
S["27ce6064"] = "Ora la tua anima è legata a me!"
S["27d5dbf7"] = "$GAttento:Attenta; a dove metti i piedi, $Gstraniero:straniera;. In città i malfattori non li tolleriamo."
S["27de2698"] = "Tu forse pensa ke questo è mio bastone da passeggio, amico. Ma è proprio quello ke io voglio ke tu pensa."
S["27e012ac"] = "Non solo io ho tutti i mithril bars ke mi servono, ma ora tutte le raccolte dell'Orda sono finite, amico. Sembra ke noi aspetta solo l'Alleanza e poi andiamo in guerra!"
S["27e53379"] = "Come una mosca nella ragnatela."
S["27e586f2"] = "I Titani avevano lasciato questo mondo da tempo. Solo gli elfi della notte che un tempo abitavano questa zona erano qui a difenderla. Oh cielo! Il passo successivo è affascinante!"
S["27e7f968"] = "È ora di prendere la situazione in mano. Venite. Entrate nel mio dominio e sfidate la potenza dello Scourge!"
S["27eb3aae"] = "Fai da mentore a uno dei nostri orfani durante la Settimana dei Custodi! Per l'Orda!"
S["27f211a3"] = "Purtroppo non siamo ancora in funzione. Ripassa più tardi, per favore!"
S["28021b61"] = "Ecco... così dovrebbe andare meglio. Ora dimmi cos'è successo, il Grimclaw."
S["2812d2cb"] = "Ciao, $N! Vieni a comprare qualcosa? O magari a vendere?$B$BPrezzi migliori non li trovi da nessuna parte, o non mi chiamo Augustus the Touched!"
S["2820185e"] = "Verme, come osi chiedermi di addestrarti? Che cosa speravi, $Gzoticone:zoticona; a bocca aperta, una lezione su come si usa per bene la fogliargento? Fuori! Sei $Gfortunato:fortunata; che non ti stordisco di botte per il tempo che mi hai fatto perdere."
S["28287a8f"] = "Sidney è in ritardo. Pensavo che ormai fosse a casa."
S["28313b04"] = "Ciao! Io sono Jenna! E tu come ti chiami?"
S["2833e651"] = "Addio, Cerellean, finché non saremo di nuovo uniti..."
S["283447fd"] = "Oh, noi due andremo d'amore e d'accordo, $N."
S["283ca01d"] = "Sembra che le ultime merci che abbiamo raccolto partiranno per Silithus nei prossimi giorni. E quando sarà fatto, qualcuno dovrà andare a suonare il gong sulla Scarab Dais, fuori da Ahn'Qiraj, per aprire i cancelli. Sarà allora che le nostre bende torneranno utili."
S["28509dae"] = "Che cosa vuoi, $C? Sono in ritardo, e al mio datore di lavoro i ritardi non piacciono."
S["2854b46b"] = "Io me ne vado!"
S["28576125"] = "HO LA TUA CINTURINA LEGATA AL DITO, SMOTTS. NON LA RIVUOI?"
S["285820ec"] = "James Van Brunt in War Quarter, su anello interno."
S["2867262c"] = "Il pranzo è servito, figli miei bellissimi. Fateli a pezzi!"
S["286f2475"] = "Qualcun altro è pronto a provare l'ira della Defias Brotherhood?"
S["2873c7ef"] = "Ah! Ben ti sta, lurido trogg!!"
S["2873cead"] = "Hip hip... arrrrr..."
S["287e2218"] = "Sul pesce che gli è scappato Grimnur Stonebrand ti racconterà certe frottole grosse così, ma da 'ste parti resta uno dei migliori pescatori. Ha messo su bottega in The Forlorn Cavern: si chiama il Traveling Fisherman."
S["287e4ce2"] = "Non sei $Guno stregone:una stregona; e per te non ho tempo. Sparisci!"
S["2880f1ac"] = "Allora, dov'ero $Grimasto:rimasta;? Ah, sì: gli orchi si sono lanciati contro Windsor, e Windsor, beh, non si è spostato di un centimetro. Stava lì in piedi, a testa alta, mentre lo caricavano dieci alla volta. Io vedevo solo il bagliore di Ironfoe e un sacco di sangue. È andata avanti per ore, forse per giorni, non ricordo. Comunque, FINALMENTE, è finita."
S["288425fd"] = "La covata di Onyxia!"
S["2885a647"] = "%s è pieno di ratti neri morti. Mmmmm...."
S["288c6d02"] = "Quella in cui ti stai imbarcando non è un'impresa da poco, $N. Per raggiungere la Warsong Gulch dovrai parlare con Aethalas, la Maestra di Battaglia delle Silverwing Sentinels: sarà lei a guidarti. Le benedizioni della Dea siano con te!"
S["288f00af"] = "Bevo la tua sofferenza, mortale. Che la tua essenza si congeli con Lokholar!"
S["288fc582"] = "Chi l'avrebbe mai detto che lo scavo avrebbe portato alla luce simili scoperte!"
S["28943a70"] = "Chi controlla lo Stonehearth Graveyard?"
S["28a019ba"] = "Tre urrà per Ван! Questa terra tornerà nostra!"
S["28a15689"] = "Ottima scelta. Ti ho segnato il posto sulla mappa."
S["28a1e911"] = "Ora inchinatevi a me."
S["28a282cb"] = "Oh no... Mist... cos'è successo...?"
S["28a52faa"] = "%s e Raider Kerr si lanciano in battaglia..."
S["28a99e7d"] = "Sì! Be'. Più o meno.$B$BL'oro è la vera moneta universale, ma tra di noi usiamo un nostro sistema di scambio, chiamato Merchant's Favor. Ci libera dalla volatilità del valore dell'oro e dell'argento e garantisce scambi giusti ed equi tra i membri dell'organizzazione. Non si può convertire in oro, a meno che tu non sia $Gcoinvolto:coinvolta; in qualche traffico losco, immagino.$B$BUsiamo ancora l'oro per le normali necessità quotidiane, come i materiali per i lavori di artigianato più comuni, ma per qualsiasi tipo di commercio interno ci affidiamo al Merchant's Favor.$B$BSe ci aiuti a recuperare le casse intercettate lungo la strada e a evadere in fretta i Craftsman's Writs, ne guadagnerai in abbondanza!"
S["28a9e89a"] = "Davvero? Hanno sempre fatto così. Per Kel'Thuzad e per l'esercito sempre più grande dello Scourge cosa vale di più: un seguace fanatico e vivo, capace di infiltrarsi in una società e poi scatenare una pestilenza che uccide migliaia di persone, o un singolo soldato non morto? Non sarai certo così $Gottuso:ottusa;.$B$BSì, $R, vivono, lavorano e tramano in mezzo a voi."
S["28aa7fae"] = "Non così in fretta, $Gamico:amica;... Non consegnerò le redini di un possente ariete da cavalcatura a chi non si è $Gdimostrato:dimostrata; $Gun alleato:un'alleata; dei nani di Ironforge. Quando sarai $Griconosciuto:riconosciuta; come $Gamico:amica; di Ironforge, ti mostrerò volentieri quali razze di arieti ho in vendita."
S["28ae34f9"] = "$GBenvenuto:Benvenuta; a Shen'dar Village: da questo lato della catena montuosa, è uno dei posti migliori per pescare. Se vuoi imparare a prendere i pesci, posso insegnartelo io, dietro compenso."
S["28b325fd"] = "Veld goibon odes ewiddan. Gol lo wirsh vil algos ras."
S["28b7159c"] = "Spiriti del vento... perdonatemi..."
S["28b96409"] = "Sono $Glusingato:lusingata;, ma davvero non mi interessa... Come? Vuoi sapere dove si impara l'incantamento? Oh, che imbarazzo! Beh, dovresti... Sono $Gsicuro:sicura; che potresti... andare da, ehm... Taladan! Sì, vai da Taladan alla Craftsmen's Terrace!"
S["28c674da"] = "Cra! No!! Non può...cra...essere! Mi hai raggirato con...cra...il tuo losco inganno! Cra!"
S["28c78aa9"] = "Mi ha chiesto di venire qui Warchief Thrall in persona. Obbedire è stato un onore, non un sacrificio. Un incarico migliore di Stonard non avrei potuto chiederlo: qui nel fango cresce quasi ogni erba che mi possa servire."
S["28cd91e4"] = "Da quando ci siamo stabiliti nel cratere, a Dadanga piacciono tanto i grossi germogli di bloodpetal che crescono dappertutto qui.$B$BSono $Gsicuro:sicura; che uno spuntino lo gradirebbe, se ti va di portargliene un po'..."
S["28cf8f12"] = "Pagherai per questo oltraggio! Guardie!"
S["28df2d39"] = "Sei $Gnuovo:nuova; qui? Alle reclute imberbi non ho niente da dire, se non che faresti bene a sublimare l'ardore giovanile in suppliche e preghiere."
S["28e502e3"] = "Keever è molto soddisfatto."
S["28f413ba"] = "Thorfin Stoneshield è venuto fin da Ironforge per offrirci la sua esperienza di caccia. Se non ti dà fastidio respirare l'aria piena di fumo del Dwarven District, lo trovi a casa sua, nella parte nord-est del distretto."
S["28f8fa40"] = "Sii prudente, Antonio."
S["28fcf3a9"] = "%s torna in vita con un sussulto!"
S["28fdd0d5"] = "Faergas wos wirsh eynes se tiras. Wirsh lon dana waldir bor. Ruftos uden landowar, wos tiras goth agol O far re."
S["2905656c"] = "Och... un paladino? Beh, $Gragazzo:ragazza;, sei $Gfortunato:fortunata;! Azar Stronghammer è tornato dall'addestramento e adesso sta alla Thunderbrew Distillery, a Kharanos."
S["2908decf"] = "Non preoccuparti, il barbiere sta poco a nord-ovest dell'ingresso di Ironforge.$B$BIn un batter d'occhio ti rimettono a lucido!"
S["29104959"] = "Ne sai già più di quanto io possa insegnarti. Mettiti in viaggio verso l'Aerie Peak, nell'Hinterlands, e parla con il nano Drakk Stonehand: fa un lavoro magnifico, molto migliore del mio."
S["2910e62b"] = "Il Waterlord Hydraxis se ne sta nascosto su un'isola nella Bay of Storms, ad Azshara. Da lì, che razza di minaccia può mettere insieme quello sciocco?"
S["29177852"] = "Niente può cambiare il passato, ma il tempo guarisce ogni ferita. Grazie per avermi mostrato che è possibile, $N. Ti auguro ogni bene."
S["291e4cfd"] = "Credo che siano gli ultimi. Per fortuna sei $Garrivato:arrivata; proprio in quel momento... Non sapevo per quanto ancora avrei potuto restare $Gnascosto:nascosta;."
S["29251671"] = "Hai imparato molto, più di quanto io possa insegnarti. Vai da James Van Brunt, ti insegnerà ciò che io non posso."
S["292861b3"] = "%s si siede."
S["29292144"] = "Banca in torre centrale di Trade Quarter. Tu non poter sbagliare."
S["2935a20f"] = "Io e mio fratello ci siamo votati a Sylvanas: quando i tempi erano più bui, è stata il nostro faro di luce. Giorno dopo giorno ci sacrifichiamo perché la nostra gente vinca il destino che ci ha scelti.$B$BNon resteremo deboli. Ci prenderemo ciò che ci spetta, e il dolore che ci hanno inflitto lo restituiremo dieci volte tanto. Con il sorriso sulle labbra."
S["294de220"] = "$GBen trovato:Ben trovata;, $Gamico:amica;. Sono Officer Garush e vado fiero di far parte di un'organizzazione che opera in tutto il mondo, conosciuta come l'Argent Dawn. La nostra causa è colpire in fretta e senza pietà ogni forma di male che si mostri su Azeroth. Non siamo un organismo politico, e non vorremo mai esserlo. Abbiamo una causa sola, ed è per questo che per noi l'Orda e l'Alleanza sono amiche — amiche nella lotta per schiacciare il male!$B$BPer la Dawn, $Gfratello mio:sorella mia;!"
S["2952c69f"] = "Ho percorso queste pianure per molte, molte stagioni, e ho cacciato grandi bestie. Non ero mai stato sconfitto... finché non ho affrontato Ghost Howl.$B$BMolto tempo fa quell'enorme lupo era un alleato dei tauren, e ha combattuto con coraggio contro la Burning Legion. Ma un demone l'ha ferito con ferocia, e lo squarcio nella carne non si è mai rimarginato. Alla fine... ha fatto impazzire Ghost Howl.$B$BOra vaga per le pianure in agonia, cercando di mettere fine al dolore. E quando ci siamo battuti, con mia vergogna, non ho avuto la forza di ucciderlo..."
S["2954434c"] = "Appena fuori dalla Thunder Bluff Bank, sulla terrazza più bassa, trovi una cassetta della posta."
S["29571a7e"] = "Non posso aiutarti: di pozioni ne sai più tu di me. E poi ho delle pentole da guardare. Parla con Yelmak, laggiù: lui ne sa un sacco."
S["295a3ab0"] = "Mi sa che mi fermo un attimo a riprendere fiato prima di tornare a Ratchet. Grazie di tutto l'aiuto!"
S["295d8c53"] = "Sarete giudicati per aver profanato questo suolo sacro! Le leggi degli Antichi non si sfidano! Gli intrusi saranno annientati!"
S["295fc4cc"] = "Noi volere felhound come animale domestico. Noi dare lui da mangiare, trattare lui bene e insegnare lui a riportare. Tu trovare Stregoni in Magic Quarter, su anello esterno di città."
S["297187f9"] = "Queste lanterne le hanno messe fuori per festeggiare la chiusura del Festival Lunare."
S["297c5df7"] = "No, no! Lorthuna, non capisci. Questo plasmavento sta solo passando di qui. Non è venuto con me!"
S["297f62ac"] = "%s dà al toad un po' dello strano liquido."
S["298327e4"] = "Cuccioli impudenti! Vi siete gettati a capofitto verso la morte! Guardate, il padrone si risveglia!"
S["2984580f"] = "Calma, gente. Presto andremo all'assalto."
S["29879247"] = "Credo... credo che stia funzionando!"
S["2988f502"] = "A Dolanaar vive una sacerdotessa che si chiama Laurna Morninglight. Dovresti trovarla poco a nord della Locanda."
S["298df0d2"] = "Piccoli coltivatori di mele! Ferauu è qui a riscuotere il dovuto!"
S["298f3931"] = "Purtroppo Zephras è in declino. Gli spiriti elementali del vento, che tante migliaia di anni fa ci condussero qui a Skywall, sono svaniti, e così abbiamo perso gran parte della magia da cui dipendiamo da millenni.$B$BAnche l'isola è pericolosamente instabile, e abbiamo perso perfino i contatti con le altre province insulari degli shen'dorei. I pochi Windshapers che hanno ancora il dono della vista celeste hanno provato a raggiungere i nostri fratelli e le nostre sorelle sulle altre isole, ma non ci ha risposto nessuno.$B$BMolti di noi temono che gli shen'dorei qui su Zephras siano tutto ciò che resta del nostro popolo."
S["29903c23"] = "Intrusi! Uccideteli!"
S["29937f87"] = "Attenzione, i Grimtotem ci sono addosso!"
S["299a210a"] = "Una corruzione contamina la nostra foresta sacra."
S["29a23951"] = "Le mie forze non possono superare le difese Qiraji. Non riusciremo ad avvicinarci abbastanza da piazzare la tua preziosa barriera, drago."
S["29a828a0"] = "Preparati a morire, feccia di un paladino!"
S["29d11cdf"] = "Yaw Sharpmane ti aspetta al margine nord del villaggio, e può insegnarti l'arte del Cacciatore."
S["29d4a884"] = "Mi dispiace, $N, ma ai principianti non insegno. Va' piuttosto a parlare con Milla Fairancora, nella Craftsmen's Terrace of Darnassus: può aiutarti a recuperare il tempo perduto."
S["29da43ce"] = "Tutto il cibo e il materiale bellico che abbiamo raccolto è in viaggio verso Silithus. Dovrebbe arrivare lì in meno di un giorno. Qualcuno mi ha detto che, quando sarà tutto radunato vicino alla Cenarion Hold, qualcuno dovrà andare a suonare il gong sulla Scarab Dais per aprire le porte di Ahn'Qiraj e far cominciare la guerra."
S["29e03123"] = "Ora manca un solo passo per liberarci dalla minaccia del Soulflayer..."
S["29e4f8d5"] = "Non dovete evocare il nostro dio!"
S["29fec0e1"] = "Forze oscure premono ai nostri confini, antiche corruzioni riaffiorano e nuovi mali si levano per rovesciare il delicato equilibrio della terra. In tempi così bui dobbiamo restare tutti vigili."
S["2a01ed97"] = "Aspetterò."
S["2a084131"] = "Il Capoguerra farà presto a sistemarvi, mortali. Preparatevi!"
S["2a0f0ae5"] = "Oh, avessi almeno un ramo d'albero da tenermi davanti. Le guardie non mi vedrebbero mai."
S["2a13b1d1"] = "Alle scale e difendetele!"
S["2a140b31"] = "Ahhhh!!! Cos'è quella cosa?!"
S["2a19b817"] = "Sarai una preda facile, $C."
S["2a19b96c"] = "Sarai una preda facile, $N."
S["2a1bac29"] = "Te la faccio facile, strega. Fermati subito e ti darò una morte rapida. È l'offerta migliore che riceverai dall'High Order, e sarà anche l'ultima."
S["2a1ca88b"] = "%s perde energia e si spegne!"
S["2a1f9acd"] = "Ti serve un'arma, $Gviaggiatore:viaggiatrice;? Una lama migliore non la trovi da nessuna parte, te lo assicuro."
S["2a2a3cec"] = "Questa marmaglia di non morti, e la loro regina elfa morta, cadranno!"
S["2a2d9009"] = "Stavo pensando la stessa cosa."
S["2a2e36c6"] = "TROPPO PRESTO! MI HAI RISVEGLIATO TROPPO PRESTO, EXECUTUS! COSA SIGNIFICA QUESTA INTRUSIONE???"
S["2a379c94"] = "Sei $Gcongedato:congedata;, $N."
S["2a39781f"] = "Lo chiamiamo Smiling Jim..."
S["2a440f77"] = "Ancora nessuna traccia dell'ultimo carico di esplosivi."
S["2a478756"] = "Ringrazio la Luce per questa benedizione. Che sia usata per la giustizia e per difendere tutte le creature buone."
S["2a495e9f"] = "Prendi il tuo regalo dal mucchio."
S["2a4b9c15"] = "Tessere è il modo migliore per liberare la mente."
S["2a4dcc6f"] = "ARRRRRGGGHHH!"
S["2a4e979f"] = "Sono Rutherford Twing, il fornitore principale dei Defilers di stanza qui nell'Arathi Basin. Man mano che la tua reputazione presso di noi crescerà, ti metterò a disposizione un'ottima scelta di merci che potrebbero tornarti utili. E se devi far riparare i tuoi oggetti, mi occupo anche di questo."
S["2a4ec50d"] = "Iniziamo una nuova battaglia e stavolta battiamo l'Alleanza!"
S["2a4f7048"] = "Lo spirito di Echeyakee scorre in te, $N."
S["2a517dae"] = "Un giorno sarò una guardia!"
S["2a58d0d7"] = "Credi tu che il padrone sia intimorito dai tuoi giochi? Non cadremo mai per mano tua!"
S["2a6c6232"] = "Frutta fresca direttamente dalle rigogliose foreste di Elwynn: prendetela qui."
S["2a76d247"] = "Fatevi sotto!"
S["2a836d94"] = "Ce l'abbiamo fatta! Vittoria all'Alleanza!"
S["2a867ce7"] = "Cosa??  La Burning Blade si sta diffondendo!  Dobbiamo indagare!"
S["2a883600"] = "Finché quei nani se ne stanno laggiù, non avremo problemi. Dove sei $Gdiretto:diretta;, $N?"
S["2a956107"] = "Quanti lingotti di metallo, dici? Ecco quello che so dalle ultime notizie. L'Orda ha raccolto una parte dei copper bars che servono e una parte dei tin bars richiesti, e dei mithril bars che si cercano ne ha messi insieme alcuni."
S["2aa96e37"] = "Il cinghiale è eccellente!"
S["2aac2268"] = "State pronti!"
S["2aad617d"] = "%s lancia un ruggito possente per chiamare aiuto!"
S["2ab6d11f"] = "La grande opera è quasi compiuta, Skypriest Aanders. Il tuo successo, in questo caso, è vitale."
S["2ab79082"] = "Le locande sono luoghi dove puoi riposare dopo le tue avventure. Se non soggiorni in una locanda come questa, non sarai del tutto $Griposato:riposata; quando ti avventurerai di nuovo nelle terre selvagge.$B$BIn qualsiasi locanda puoi anche ottenere un'hearthstone, e più tardi, quando sarai $Gpronto:pronta; a riposare, potrai usare questa hearthstone per tornare alla locanda in cui l'hai ottenuta."
S["2ab9e9d0"] = "Ah, sei tu $Gquello:quella; che ha trovato la lettera. Grazie per le... notizie, immagino, sulla mia famiglia di un tempo. Serviti pure di quel poco da mangiare e da bere che posso offrirti."
S["2abd4de8"] = "La battaglia per Warsong Gulch non possiamo perderla. Combattiamo per il nostro onore, combattiamo per la nostra terra, e nessun orco o alleato fuorviato ce li porterà via!"
S["2ac9811c"] = "È un congegno pericoloso, $N. Sono contento che tu me l'abbia fatto notare."
S["2acab7a4"] = "Il Dun Baldar North Bunker è stato preso dall'Alleanza!"
S["2acb7d37"] = "%s si teletrasporta e comincia a incanalare un incantesimo!"
S["2acb8423"] = "Lo eri. L'Occhio non sbaglia mai.$B$BDopotutto sei una sacerdotessa. E anche potente, se l'Occhio ti ha mostrato questo orribile ricordo.$B$BSei $Gvenuto:venuta; a cercare redenzione, eppure non te ne rendi conto nemmeno tu... Vero?"
S["2aceb084"] = "Il ponte sta venendo benissimo. Se teniamo questo ritmo, sarà finito in tempo per le prime forze di espansione dirette a nord."
S["2ad96264"] = "Dunque il tuo viaggio ti porta a nord, fino a Thunder Bluff, $Gamico:amica;. Quando ci arrivi, chiedi consiglio a uno dei Bluffwatchers: saprà dirti con precisione dove trovare chi cerchi."
S["2adafc3c"] = "Non so chi sia più pericoloso, gli Al'Aketh o quei Windshapers maledetti dal cielo! E sia. Se lei non è disposta a risolvere la cosa in modo civile, appena superata questa crisi non esiteremo."
S["2ade6fa4"] = "Gryfe fa suo lavoro! Gryfe va ora!!!"
S["2ae362b3"] = "Appena ti avvicini, liquidi e miscele ribollono e sussultano. Accanto all'attrezzatura c'è un grosso paio di pinze, che sembrano adatte a immergere campioni di melma.$B$BC'è anche dell'equipaggiamento di sicurezza, ma sembra impolverato e del tutto trascurato.$B$BNon ti sembra saggio toccare niente."
S["2ae783b6"] = "Ur daz revos ul melar revos za gul maev melar daz revos!"
S["2af09ef7"] = "$N, assicurati che qualsiasi alleato con te sia $Gpronto:pronta; a combattere, e parla con me quando sei $Gpronto:pronta; ad affrontare Lorthuna."
S["2af1fecc"] = "Loro insegna me a muovere furtivo bene. Tu trova loro in Rogues' Quarter, su anello esterno di Undercity."
S["2af75f86"] = "Tra un'ora attacco il turno, ma intanto... alla salute!"
S["2afd77ff"] = "Il mio padrone, Plugger Spazzring, è un buon capo, e di soldi ne fa un sacco. Ha le tasche che scoppiano!"
S["2afe58fc"] = "Potrai giocare ancora domani. Adesso vieni dentro."
S["2aff67a0"] = "Fate una pausa, uomini! Mezz'ora e poi di nuovo al lavoro."
S["2b0b0170"] = "Ho... fallito."
S["2b0da624"] = "Adoro le mattine! È una bella giornata, vero? Senti che aria?"
S["2b0eda95"] = "Quando dico campione puro, intendo uno che nessuna influenza involontaria abbia corrotto. Le creature dobbiamo trovarle nell'ambiente più semplice e normale possibile.$B$BVale a dire un posto senza civiltà, dove non arrivano gli effetti delle razze dominanti di Azeroth. Un posto... incontaminato."
S["2b1a5815"] = "Intorno a Dolanaar troverai molti istruttori, che hanno secoli di esperienza da trasmetterti. Da quale di loro vuoi che ti indirizzi?"
S["2b1e55dc"] = "1 minuto all'inizio della battaglia per l'Alterac Valley."
S["2b1eac53"] = "È bello che tu voglia aiutare, $C. Purtroppo ho raccolto tutto il peacebloom che riteniamo ci servirà per lo sforzo bellico. Forse potresti chiedere in giro; sono sicuro che qui ci sono probabilmente altri che hanno ancora bisogno del tuo aiuto per raccogliere altre cose."
S["2b2f2b0f"] = "Io e i miei colleghi stiamo raccogliendo le sostanze più letali che conosciamo, e ne proviamo gli effetti sui nostri nemici. Quando avrò tutto quello che mi serve, preparerò pestilenze che questo mondo non ha mai visto."
S["2b308de1"] = "La tua Orda non è niente per i Kolkar!"
S["2b32cd95"] = "Non so che cosa mi sia preso. Sento il cuore rovente come acciaio appena forgiato."
S["2b3ca3bb"] = "Warg scruta l'acqua, chiedendosi quanto sarà fortunato oggi."
S["2b3fd9c7"] = "\"Diario Mistico di Khadgar, Volume 8.\" Credo che sia quello che volevo."
S["2b41617f"] = "Deludente."
S["2b44fcc5"] = "Sì, sì. Ti vedo.$B$BVa' per la tua strada. Forse ti sei $Gguadagnato:guadagnata; la fiducia di qualcuno, ma per convincere me ci vuole di più!"
S["2b455e93"] = "Sapevo da tempo che saresti $Gvenuto:venuta; a cercarmi, $N.$B$BOgni essere senziente di questo mondo è guidato dalle scelte che compie. Da una scelta nascono altre scelte, e sono queste a fare di ognuno ciò che è. La tua sorte viene da qui — da chi sei e dalle scelte che fai.$B$BSei $Gpronto:pronta; a scoprire qual è la tua sorte?"
S["2b496629"] = "Preparati!"
S["2b496636"] = "Preparati."
S["2b502db4"] = "Scatola stupida. Lumurk assonnato."
S["2b51877d"] = "La vostra prigione è nostra!"
S["2b5212d7"] = "Per colpa dei Timberlings, intorno a Dolanaar i pescatori fanno ormai troppa fatica a prendere qualcosa. Ti conviene cercare qualcuno che ti addestri a Darnassus."
S["2b56c30a"] = "Le guardie del Re dovrebbero arrivare a breve a prendere il Memoriale. Nel frattempo, raggiungimi di sopra e finiamo la nostra chiacchierata, $N."
S["2b631305"] = "Conosci i nostri ordini. Finché non sapremo con certezza, questo è il modo migliore per mantenere la calma in città."
S["2b6893a6"] = "Dun Baldar è ridotta molto male, e abbiamo pochissime scorte per ricostruirla. L'Alleanza ha bisogno del tuo aiuto per raccogliere rifornimenti!"
S["2b6af586"] = "Cagnolini, tutti quanti!"
S["2b6e82ee"] = "Brzzzzt!$B$B$GBenvenuto:Benvenuta; nel Matrix Punchograph 3005 barra B, terminale con livello di sicurezza beta.$B$BYellow punch card rilevata. Accesso Consentito.$B$B01001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001"
S["2b72a657"] = "Mi occupo io del reclutamento per il Frostwolf Clan. Come $Gsoldato:soldatessa; dei Frostwolf, ogni volta che sali di grado nel clan hai il dovere di presentarti da me.$B$BSu questo campo gelido l'onore e il rispetto si guadagnano."
S["2b72e1c5"] = "Maledizione... Ogres. Mi ero dimenticato di questi buffoni. Non c'è un modo facile per aggirarli, quindi preparati a combattere parecchio. Occhi aperti!"
S["2b7cdd1b"] = "%s perde il collegamento!"
S["2b81dccf"] = "$GProfanatore:Profanatrice;... sarai $Gpunito:punita; per questa incursione. <Un simbolo di fiamma s'irradia dalla reliquia prima che si sgretoli al suolo.>"
S["2b82c4ef"] = "La corruzione del vile non ha risparmiato nessuna delle creature di Felwood, $N. Ti prego, stai in guardia."
S["2b874658"] = "Da queste parti non c'è granché da pescare, ma puoi starne $Gcerto:certa;: quel poco che c'è è tutto di Paxton. Lo trovi sull'Iceflow Lake, con la canna in mano."
S["2b8efa05"] = "Niente di quello che dici mi farà mai entrare nell'arena contro quella mostruosità di macchina che chiami carro a vapore!"
S["2b96d383"] = "Ehehe! Le cose fanno bum!"
S["2b9ce93f"] = "Salute, $C. È la Festa del Raccolto — tempo di grande abbondanza e di ricordo. Ai banchetti celebriamo tutto ciò per cui dobbiamo essere grati, e ricordiamo i nostri antenati e gli eroi del passato, per ringraziarli dell'eredità che ci hanno lasciato.$B$BUnisciti pure al banchetto che trovi qui. Ho anche dei fuochi d'artificio per festeggiare questo gioioso periodo dell'anno."
S["2ba09015"] = "Salve, $C. Mi chiamo Jessir Moonbow e vengo da Darnassus: cerco due amici che erano venuti nel Felwood in cerca di tracce dello Shadow Council.$B$BA quanto pare quelle creature spregevoli, che si dicono responsabili di gran parte delle sofferenze della razza degli orchi, stanno cercando di riprendersi parte del loro potere.$B$BI miei amici sono andati a indagare a Jaedenar, per scoprire con certezza cosa stesse succedendo.$B$BContavo di trovarli qui al mio arrivo, ma ormai sono in ritardo di giorni."
S["2ba56d2f"] = "Lo Snowfall Graveyard si trova in cima a una collina nel Field of Strife, a est del Winterax Hold.$B$BNessuna delle due fazioni lo controlla."
S["2bae2737"] = "Che emozione essere qui a Darnassus, circondata da persone di talento! La mia famiglia sarà orgogliosa di me, ne sono sicura. E se avrò davvero fortuna, magari le Sentinelle mi chiederanno di unirmi alle loro forze al fronte!"
S["2bb6d88b"] = "Deeprun Tram"
S["2bced55e"] = "Isaac decise di percorrere i mari e tornare a casa come un uomo capace di dare alla sua amata tutto ciò che meritava."
S["2bd14ddc"] = "Quando non ti senti più le dita, bisogna stare attenti ad accendere i fuochi d'artificio..."
S["2bd513f2"] = "%s sviene e cade a terra."
S["2bd62da6"] = "Come posso aiutarti?"
S["2bda605d"] = "Non ho tempo per te, $R. Prosegui per la tua strada."
S["2bdc2190"] = "Armand Cromwell sempre su molo in Magic Quarter. Pesce in melma verde sapore extra buono. Tu prova."
S["2bdd741b"] = "Hai vinto, $N. Hai vinto!"
S["2bde329f"] = "È il secondo edificio a destra nella Valley of Strength, a nord dell'ingresso principale della città. Parla con Innkeeper Gryshka."
S["2bdeb425"] = "Ah, la gentile Seriadne. Ogni animale che le viene affidato è al sicuro. La trovi appena fuori dalla Locanda di Dolanaar."
S["2be1e43f"] = "Gloria a The Lich King!"
S["2bea2993"] = "Yiieeeee! Me scappare!"
S["2bf06f4c"] = "Hai portato le provviste del nemico! Ah! Ben fatto, $N!"
S["2bfec23d"] = "Questo raggio di luce lunare porta a Undercity. Avviati quando sei $Gpronto:pronta;."
S["2bff47a5"] = "Salute, $C. The Ironforge Brigade è di stanza qui per sorvegliare Hive'Zora. I druidi del Cenarion Circle seguono i movimenti dei silithid e si aspettano qualcosa di grosso da queste parti."
S["2c0f7100"] = "$GBenvenuto:Benvenuta; nella mia bottega da barbiere! Offriamo tagli, tinte e molto altro.$B$BPossiamo sistemarti barba e baffi, fare piercing, rimodellare zanne e corna, e perfino ritoccare i tratti da non morto!$B$BAccomodati, che ci mettiamo al lavoro."
S["2c11b70a"] = "Chi vuole un mio lavoro deve chiedermelo di persona. Orwin mi chiede spesso di ripensarci, ma quello che conta per me è qui. Guardati intorno: tanti di questi combattenti contano su di me per le armature."
S["2c1afafa"] = "Nessuna contadina può tenere testa ai Defias!"
S["2c1c8fc4"] = "Non mi farò attirare via da questo posto."
S["2c2a1a07"] = "Per la forza della terra, il potere delle tempeste e..."
S["2c307855"] = "Il libro racconta di draghi che si alleano contro un altro drago, più potente, di nome Deathwing. Da quel che riesci a capire, lo stormo dei draghi cromatici era stato quasi scatenato sul mondo. Gli Aspetti erano pronti."
S["2c312712"] = "Soldati di Kalimdor, difendete la base!"
S["2c388b62"] = "$N, il segreto di questi collari è al di là delle mie conoscenze..."
S["2c402708"] = "Passa alle unità campione!"
S["2c4521a5"] = "%s saluta tutti con la mano."
S["2c45617a"] = "Cosa? Qualcuno ha detto birra? Non cominciate a versare le pinte senza il vecchio Torren!"
S["2c4c22fe"] = "Il tuo tradimento affretta solo la tua fine. Questo mondo cadrà nell'oscurità!"
S["2c4e8c36"] = "Battaglia! Sento l'odore della tua paura, $C!"
S["2c50539b"] = "Ahimè, $C, Darnassus e gli elfi della notte di Teldrassil non ti considerano $Gosannato:osannata;. Metterò le mie cavalcature a tua disposizione, perché tu possa scegliere, solo quando ci avrai dimostrato il tuo valore con i fatti — non con semplici parole."
S["2c5acbaf"] = "Ah, sei tu $Gquello:quella; che ha trovato la lettera. Grazie delle... notizie, suppongo, sulla mia famiglia. Prendi pure quello che posso offrirti da mangiare e da bere."
S["2c612a8d"] = "Se mai sarò chiamato, mi spetterà un sacrificio, mortale..."
S["2c624ac2"] = "Pare che tu abbia la stoffa di un gran fabbro. Ma prima che t'insegni qualcosa, devo sapere se hai quel che ci vuole."
S["2c6925a0"] = "È stata una bella faticata, ma ora posso fare scorta di provviste per il viaggio di ritorno nel Cratere. Dovrei riuscire anche a sbarazzarmi di un po' di questo carico esotico."
S["2c743baa"] = "Minuscoli mortali, io QUI! Voi incontra rovina!"
S["2c7f87ec"] = "Salute, viandante, hai la mia gratitudine eterna per esserti sbarazzat$Go:a; di quelle orribili creature! Cominciavo a pensare di dovermi nascondere per sempre!"
S["2c832069"] = "Basta! Tornate ai vostri angoli! Ben combattuto, tutti e due."
S["2c8971f6"] = "Chi fa il mio mestiere studia ed esalta la capacità sovrannaturale del crypt fiend di cacciare e uccidere il nemico. Io stesso ho ucciso migliaia di queste bestie, nella mia crociata per liberare questo mondo dallo Scourge.$B$BDetesto il crypt fiend per la sua natura spietata, ma le sue capacità vanno ammirate. Ha un compito e lo svolge — molto bene."
S["2c954fce"] = "Cos'è questo rumore?"
S["2c9687ff"] = "Quando mi sono imbattuto nelle pietre di Suntara agli Scavi di Golasporca, il potere di Ragnaros mi ha travolto. È stato Ragnaros a darmi uno scopo."
S["2c9fd383"] = "Usa il soffio congelante, imbecille!"
S["2ca112d5"] = "$GAvventuriero:Avventuriera;! I combattenti dell'High Order e dei Windshapers hanno appena preso il ponte del vento per passare dall'altra parte!"
S["2ca3bf71"] = "Già. Ora la Guglia è governata da Nefarian, progenie di Deathwing, e Rend prende ordini dal drago.$B$BSe solo tu riuscissi in qualche modo a superare le Halls of Ascension.$B$B<Eitrigg sospira.>$B$BAhimè, il privilegio di ascendere spetta solo a chi lo stormo nero ritiene degno."
S["2ca54cfd"] = "Se hai l'attitudine giusta, posso insegnarti a creare armature di cuoio pregiato."
S["2ca78d14"] = "Ho molto da insegnarti, $C. Devi imparare a cacciare con onore."
S["2caa865f"] = "Ciao! Gli spiriti dicono che tu qui per aiutare il mio capo. E lo dicono forte, loro."
S["2cabaaf7"] = "Ah, cerchi Lucan Cordell. Ha un negozio ai margini del Magic Quarter, sulla strada per la Stockade."
S["2cb3d362"] = "Alzatevi, servitori dell'Incubo! Alzatevi e distruggete questo mondo! Che non ci siano sopravvissuti..."
S["2cb4dd5b"] = "Vuoi imparare a maneggiare un'arma nuova, eh? Be', allora dovresti parlare con Bixi o Buliwyf, $Gragazzo:ragazza;, al negozio d'armi Timberline Arms. Di armi se ne intendono, dalle asce agli... ehm... zweihanders."
S["2cb8eb80"] = "Basta chiacchiere, voi due! Cominciate a combattere!"
S["2cbff3db"] = "Un arco è 'na gran cosa, $Gamico mio:amica mia;. Tu devi solo prenderti cura di lui, e lui prende cura di te."
S["2cc34abd"] = "Mi hanno raccontato che un tempo le fattorie di Westfall rifornivano Stormwind di raccolti abbondanti. Ora però il terreno è sterile, e la maggior parte dei contadini è fuggita.$B$BA nome di Darnassus vorrei dare il mio contributo per far rinascere questa terra. Mi aiuterai?"
S["2cc40443"] = "Odio questa parte del mio lavoro. Oh Duskwood, sii gentile con il povero Antonio."
S["2cc95547"] = "%s segue $N obbediente."
S["2ccef587"] = "Ecco un telegramma cantato per $N: le rose sono rosse, le viole sono blu, ucciderò ogni Umano che vedo, e il prossimo sei tu!"
S["2cd377ee"] = "La corruzione di un titano caduto. La corruzione del Destroyer. Del resto, il bastone è stato forgiato dal seme dell'odio. Ed è proprio questo, naturalmente, che mi ha portato qui..."
S["2ce1a180"] = "Sì, Fandral, ricorda queste parole: non lasciare che il dolore guidi la tua fede. Questi pensieri che hai... in posti oscuri vai, elfo della notte. L'assoluzione non si ottiene con una vendetta sbagliata."
S["2cebbe6d"] = "E borne hir ash nuff garde re ruff vassild lon thorniss, far E regen E majis barad ras aetwinter lo ruftos ergin."
S["2cfd0aa2"] = "Questo è lo spirito! Prendi ago e filo e diamoci dentro!"
S["2d0bca67"] = "Ah! Questo dovrebbe funzionare a meraviglia!"
S["2d115603"] = "Eccellente. Portatene altri."
S["2d120b77"] = "In parole semplici, è corretto.$B$BFisicamente, gli Earthen hanno le caratteristiche di un umanoide di bassa statura, ma sono fatti dei vari composti del nucleo di pietra di Azeroth. Il loro progetto massimizza forza e tempra senza sacrificare la capacità di elaborazione cognitiva. Pelle e muscolatura sono quasi immuni ai danni fisici e, con modifiche minime, gli Earthen resistono notevolmente alle forze magiche indesiderate."
S["2d120de2"] = "Sento dei piccoli cuori che battono. Sì... ora battono più in fretta... presto smetteranno di battere."
S["2d1a5510"] = "Forse potremo tentare più tardi. Ti prego, parlami di nuovo se vorrai farlo."
S["2d1f2328"] = "Questa birra scura ha proprio un odore forte!"
S["2d202615"] = "Le nostre difese stanno cedendo! Per la luce, dobbiamo vincere!"
S["2d29d5e9"] = "Tutto tranquillo a Sentinel Hill, Lord Mantoforte. Però si segnalano forti movimenti dei Defias a Moonbrook."
S["2d2cde1b"] = "Credo di aver smarrito lo stendardo che mi avevi incantato, Falrin."
S["2d2dcabc"] = "Grazie! Grazie, $Gsacerdote:sacerdotessa;. Ora posso affrontare quegli umani con il tuo potere a sostenermi!"
S["2d30565e"] = "Che c'è? Non vedi che sono occupato?"
S["2d3a54cd"] = "Cani del Cenarion Circle. Uccideteli tutti!"
S["2d3c5cc1"] = "Vediamo come crescono questi semi nel terriccio che ho preparato..."
S["2d3d3588"] = "Serge, ho perso la cura per il Tocco di Zanzil! AIUTO!"
S["2d42b249"] = "Mi pare di sentirlo arrivare! Guarda a ovest!"
S["2d443113"] = "Me la pagherai!"
S["2d48098e"] = "Posso insegnarti sia la finezza di una lama corta sia la potenza dei fendenti spaccaossa di un colosso a due mani. Oppure possiamo fare una pazzia e te le insegno tutte e due, potrebbe tornarti utile quando la situazione ti cambia sotto il naso."
S["2d58ff87"] = "A nome della Royal Apothecary Society, sono lieto di offrirti i migliori destrieri a disposizione dei Forsaken. Come tutti noi, queste bestie hanno patito prove e tribolazioni, e ora anche loro ne sono uscite più forti e resistenti di quanto la semplice carne mortale avrebbe mai permesso! Prego, esaminale di persona e vedrai."
S["2d618b3b"] = "È una specie di scherzo?"
S["2d677368"] = "Saluti! Posso insegnarti a trasformare le pelli delle bestie in armature?"
S["2d708c40"] = "Comincia a correre!"
S["2d7877d2"] = "Saluti, $C. Sei qui per imparare le arti occulte?"
S["2d787ef6"] = "Grazie, Signora Chambers."
S["2d8954c0"] = "Cercavo un po' d'aiuto. Visto che hai le capacità, credo che andrai bene, sempre che tu abbia anche il fegato."
S["2d9ed466"] = "Defias? Non va bene. Non va bene per niente. Continua, per favore."
S["2da42d33"] = "Non dovrebbe volerci molto..."
S["2da9d034"] = "I colossi si sollevano! Sono almeno 10! ARRIVANO DA SUD!"
S["2dab940d"] = "È ora di morire, $GMago:Maga;."
S["2db60151"] = "Grazie per avermi salvato!"
S["2db6296e"] = "Su quale campo di battaglia cerchi la gloria?"
S["2dc1b4fb"] = "Tanaris è sotto attacco in questo momento?"
S["2dcbc5eb"] = "$GBenvenuto:Benvenuta; alla promozione estiva iCoke-WOW.$B$B$GCaro:Cara; $N, l'aureola della dea della fortuna risplende su di te. Obbedisci all'ordine del dio; riceverai un regalo speciale e misterioso. Ora la porta di Azeroth è aperta per te. Presto comincerà una grande avventura. Sei $Gpronto:pronta;?$B$BChe l'onore sia con te!"
S["2dd28410"] = "Perché mai vorresti parlare con Kaplak? Lascia perdere. Lo trovi in cima alla tana, nell'angolo sud-occidentale di Razor Hill. Ma tieni le mani nelle tue tasche, mi raccomando!"
S["2dd83b1f"] = "Grazie a te, $N."
S["2dddd17e"] = "Non sono in grado di addestrarti oltre. Parla con Telonis, nella Craftsmen's Terrace of Darnassus: aiuta sempre volentieri gli allievi di talento."
S["2de4db26"] = "Molti dei materiali che servono agli artigiani si trovano in giro per il mondo. Per gli altri, ne offro una piccola scelta a un prezzo onesto."
S["2deb6bc8"] = "Presto, $N! Dobbiamo trovare un riparo!"
S["2decaee7"] = "Una che non si affidi all'intervento divino di forze esterne. Per la prima volta da quando siamo arrivati a Skywall, vogliamo essere padroni del nostro destino."
S["2dedf154"] = "Come osi conferire con un Duca del Consiglio, verme!"
S["2df6c1de"] = "Se vuoi una cosa fatta bene, fattela da te!"
S["2df89dbf"] = "%s legge la lettera di Sully pagina per pagina."
S["2dffd4e8"] = "Mi fa piacere vedere che te la cavi così bene, Harlan. E spero di rivederti presto..."
S["2e02fa46"] = "Se scavi troppo a fondo nel tuo passato, potresti porre bruscamente fine al tuo futuro."
S["2e036611"] = "SENTO IL SAPORE DEL SANGUE DELLA VITA!"
S["2e0bdfa9"] = "Preparati a essere $GSPEZZATO:SPEZZATA;, miscredente!"
S["2e0e6524"] = "Tessera di sicurezza gialla inserita con successo. Erogazione dell'unità di livello di sicurezza chi.$B$B01010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001"
S["2e11aaab"] = "Ci vediamo, Corbett, e salutami la signora!"
S["2e1a144d"] = "Molti ti direbbero che il Trampoliere è un animale ridicolo. Ma la sua intelligenza e la sua fedeltà ne fanno una creatura difficile da eguagliare in molte situazioni. Se questa razza ti interessa, forse posso insegnare a te e al tuo animale alcuni talenti che ho imparato negli anni."
S["2e1ab96e"] = "Non c'è niente di meglio che sentirsi strusciare addosso qualcosa di morto. Per trovare Shelene Rhobart, esci dalla città per la strada che va a sud-est e all'incrocio gira a est: è in un piccolo accampamento poco più avanti."
S["2e1bd7d7"] = "Se vuoi la chiave, dovrai prendermi!"
S["2e1d3a29"] = "È con Father Cobb che devi parlare. Lo trovi nella grotta delle Pools of Vision, sotto la Spirit Rise."
S["2e1f430c"] = "Parlo correntemente più di 4 lingue."
S["2e21796d"] = "Uffa, mamma! Non è nemmeno buio! Possiamo giocare ancora un po', per favore?"
S["2e238142"] = "Nei dintorni di Dolanaar conoscono bene Dazalar per la sua abilità nella caccia. Perché non vai a parlargli e a scoprire cosa può insegnarti?"
S["2e3d9584"] = "Come faccio a combinare qualcosa con lo Scourge che scorrazza qui dentro?!"
S["2e4114a9"] = "Ti schiaccerò!"
S["2e463151"] = "Sildinair ha addestrato molte delle Sentinelle che proteggono la nostra amata città, e sono $Gcerto:certa; che saprà fare $Gun guerriero:una guerriera; persino di $Guno:una; come te. La trovi alla Terrazza del Guerriero, vicino all'ingresso."
S["2e485d6a"] = "Va' pure a dire a Stoutmantle che la Defias Gang si è rintanata qui, $N."
S["2e54eeb8"] = "Desideri plasmare le ossa della Madre Terra e farne strumenti al servizio dell'Orda. Bene, bene. Lascia Bloodhoof Village e prendi il sentiero verso nord, fino all'ascensore che sale in cima a Thunder Bluff. Lassù un Bluffwatcher potrà aiutarti ancora."
S["2e5946dc"] = "Bronk di viti ne ha strette tante, e secondo me alcune delle sue si sono allentate, se capisci cosa intendo. Però per inventare gli aggeggi più strampalati ha ancora una gran testa. Dovresti fare un salto a trovarlo allo Steelgrill's Depot."
S["2e6ac49a"] = "SE dicono... SE! Non ci sono se che tengano su Ironforge! Eh? Che c'è adesso?"
S["2e78fa86"] = "Un altro cade!"
S["2e81a04a"] = "Liberate i segugi!"
S["2e957996"] = "Straordinario! Come sei riuscito a ottenere una dominazione permanente?"
S["2eb9aa3a"] = "Cosa cerchi, $C?"
S["2ebfbd5d"] = "Ascolto e ascolto, ma gli spiriti di cui parla Karn io non li sento."
S["2ec234af"] = "Non torturarmi più! Liberami, mortale! La Swamp of Sorrows... mortale... ti prego..."
S["2ecd1b89"] = "%s ride come un folle."
S["2ece123e"] = "Sacerdoti! Se continuate a curare così, tanto vale rendere le cose un po' più interessanti!"
S["2ece7d3d"] = "Un tempo capitale dei nani Dark Iron, oggi questo labirinto vulcanico è la sede del potere di Ragnaros the Firelord. Ragnaros ha scoperto il segreto per dare la vita alla pietra e vuole costruire un esercito di golem inarrestabili con cui conquistare l'intero Blackrock Mountain. Ossessionato dall'idea di sconfiggere Nefarian e i suoi servitori draconici, Ragnaros è disposto a tutto pur di arrivare alla vittoria finale."
S["2ed342b9"] = "%s esplode in una poltiglia velenosa!"
S["2ed46e89"] = "Pane fresco in vendita!"
S["2ed74fd8"] = "%s si teletrasporta nella mischia!"
S["2ee6a184"] = "Non badare a Skuerto, $N. Non lo fa per scortesia, è solo occupatissimo. Mentre aspettiamo che termini la sua ricognizione, perché non ci mettiamo a lavorare su qualcosa di più produttivo?"
S["2eeaea9c"] = "Erano centinaia imprigionati dal suo incantesimo. Ora nelle loro prigioni ne restano solo pochi. A volte ci parlava."
S["2eee8844"] = "Ah, che bella giornata per far saltare qualcosa in aria!"
S["2ef7ffde"] = "Non troverete pace nella morte."
S["2ef80d04"] = "Daz rakkas ul re amir ruk arakal? Gul karkun. Melar ruk daz ashj ze maev."
S["2ef9ffbb"] = "Lord Vyletongue non conosceva gli incantesimi per unire le due parti, e così non è riuscito a usare lo scettro. Ma ora che sono $Glibero:libera; dalla maledizione della corruzione di Vyletongue, potrò aiutarti io, se vorrai portarmi le due parti — la testa e l'asta dello scettro."
S["2f061e07"] = "Beh, da quel che ho sentito, la nuova pestilenza ha TUTTO il sapore della vecchia pestilenza, ma senza le calorie e i carboidrati!"
S["2f0ab7a8"] = "Vuoi qualcos'altro da mangiare, $Gsignore:signora;?"
S["2f0d89ad"] = "%s pianta i semi del frutto."
S["2f0f54b4"] = "Assolutamente."
S["2f10f036"] = "Non arrendetevi! Versate il vostro sangue per Darrowshire!"
S["2f15cd76"] = "Per il Rosso!"
S["2f204dcf"] = "Ah, Braenna Flintcrag. Quella sì che ha le mani magiche. Per le faccende Sacerdotali è da Braenna che devi andare.$B$BDai cancelli di Ironforge vai a nord fino all'Hall of Mysteries. La trovi lì."
S["2f204ddc"] = "La nostra unica speranza è tirare fuori qualcosa di buono da una situazione già brutta."
S["2f234c12"] = "Avete riconquistato qualche misero territorio. Patetico. Presto saranno di nuovo nostri!"
S["2f290a43"] = "Grazie per gli armor scraps, $N!"
S["2f2c4965"] = "Il minatore migliore tiene ben saldo il piccone, ha un cuore forte nel petto e i capelli coperti da uno spesso strato di polvere nera."
S["2f2dd78b"] = "Nessun traditore da quattro soldi impedirà alla polvere di arrivare a Ironband!"
S["2f304319"] = "Presto tutti gli Shen'dorei vedranno la verità... e chi rifiuterà verrà spazzato via dalla tempesta che sta per arrivare!"
S["2f3cd205"] = "Posso aiutarti a trovare qualcosa?"
S["2f55750f"] = "Non è la prima volta che devo rimproverarti! Questo cuore nuovo dà impulsi elettrici decisamente troppo forti. Ha bruciato quasi tutta la carne e i legamenti del costrutto!"
S["2f6a44c3"] = "%s usa l'offerta di $N in un rituale..."
S["2f6da756"] = "Elune-adore, sorella mia. Qui sei la benvenuta. Parla, e farò quanto posso per aiutarti."
S["2f6ebfe8"] = "Stolti... Uccidete quello col vestito!"
S["2f84a318"] = "Finalmente avrò la mia vendetta!"
S["2f8b0a30"] = "Fra i demoni che una strega può sperare di avere al fianco in battaglia, l'infernal è uno dei più potenti. È forte, ben corazzato e sferra colpi devastanti contro qualsiasi nemico. Se scegliessi di infondere nella tua arma lo spirito di un infernal, ne otterresti alcuni vantaggi — più salute, rigenerazione e simili.$B$BSe vuoi saperne di più sui felhounds, dovresti parlare con Wytula, qui di fronte a me."
S["2f9685a7"] = "Ehi! Quassù!"
S["2f9772cb"] = "Ehi! Via dal nostro tesoro!"
S["2fa43079"] = "Alt! Ora di Omosh!"
S["2fa85ea7"] = "%s risponde al richiamo di Shy-Rotam."
S["2fa8931a"] = "Sai molto, $Gviaggiatore:viaggiatrice;, e devi imparare da qualcuno più saggio di me. Della saggezza di Josef Gregorian si raccontano molte storie: lo trovi a Undercity."
S["2fb41dbd"] = "Pericolo. Pericolo! $N cerca fare male A-Me."
S["2fb4c915"] = "No!!! Maledizione a voi, intrusi! Gli eserciti di The Lich King vi daranno la caccia. Non sfuggirete al vostro destino..."
S["2fbb16ee"] = "Saluti, $Gviaggiatore:viaggiatrice;. Fu qui, quasi 1.000 anni fa, che i Qiraji cominciarono la loro marcia di distruzione attraverso Kalimdor.$B$BNella guerra andarono perdute migliaia di vite, gran parte in questo deserto maledetto, durante la prima invasione.$B$BSono una delle poche rimaste, incatenata tanto al passato quanto al presente. Non so perché io debba restare qui al mio posto, ma so che devo."
S["2fbc05ea"] = "La Battaglia per l'Arathi Basin inizierà tra 30 secondi."
S["2fbce113"] = "Giornata pesante? Una bella birra scioglierà subito quelle preoccupazioni."
S["2fbede3a"] = "Michael Garrett, sull'anello superiore del Trade Quarter."
S["2fc4cd09"] = "Cosa posso fare per te?"
S["2fc990b0"] = "Che tutti noi ardiamo nel fuoco purificatore della luce!"
S["2fce51bf"] = "Abbiamo sparso per il mondo le Carte di Darkmoon, per vedere se qualcuno che lo merita riesce a completare la serie di uno dei quattro semi. Se raccoglierai tutte e otto le carte di un seme, ti daremo in premio una delle carte di Darkmoon Superiori: un potente monile e, insieme, un collegamento con la Darkmoon Faire."
S["2fe215cb"] = "$GBenvenuto:Benvenuta; alla Scarlet Raven. Di questi tempi è meglio restare al chiuso."
S["2fe80ef2"] = "Un'altra splendida giornata di pesca mi aspetta, Khara. Sarà meglio che mi dia una mossa."
S["2fe8a9da"] = "Non posso più nemmeno visitare in pace la tomba di mio padre."
S["2feee7a1"] = "Bah! Qui comanda il mio potere!"
S["2ff61cd4"] = "$N! Temevo di non rivederti mai più! Sto bene, sì, non stare in pensiero per me. Devi riposare e riprendere le forze."
S["2ff7cd36"] = "Sì, Lord Sindaco."
S["2ff7cd82"] = "%s va su tutte le furie dopo aver visto Misha cadere in battaglia!"
S["2ff988e9"] = "Se vogliamo proteggere la natura, dobbiamo abbracciarne la forza. E mostrarla a chi vorrebbe fare del male alla terra."
S["2ffaf6fe"] = "Per la Scuoiatura devi cercare Balthus Stoneflayer. Se una cosa si può scuoiare, lui ti insegna a farlo. Fatti una camminata fino alla Finespindle's Leather Goods, sul lato nord di The Great Forge."
S["300165d6"] = "Un tempo seguivo le vie del Twilight's Hammer. Ero ossessionato dall'idea di risvegliare gli Old Gods, e così mi sono spinto in fondo a questa tana, a cercare di trarre potere dalla bestia maledetta, Aku'mai!$B$BPoi ho visto sacrificare innumerevoli innocenti, e sono tornato in me.$B$BEro intrappolato, ma adesso sono libero! Ma così lontano dalla mia patria, Khaz Modan!$B$B$GCoraggioso avventuriero:Coraggiosa avventuriera;, se ucciderai Aku'mai ti offrirò un passaggio per una terra molto speciale. Se vuoi, posso teletrasportarti nella città di Darnassus."
S["3012bbf6"] = "$N, giusto? Hai lì proprio un gran bel lavoro. Ti prendo con me e t'insegno a fare armature degne di King Magni in persona."
S["30177268"] = "Ce l'abbiamo fatta! Grazie ancora! Io corro avanti!"
S["301ac09e"] = "Saluti, $C. In qualità di consigliera di Demar, sarò felice di rispondere a qualsiasi domanda tu abbia su Farholde Keep."
S["301cd935"] = "Devi trovare il modo di dimostrare che state combattendo dalla stessa parte. Anche se ora i Timbermaw potrebbero attaccarti, se sarai diligente troverai un modo.$B$BRicorda che qualsiasi attacco diretto ai furbolg Timbermaw ridurrà di molto le tue possibilità di farteli alleati.$B$BUn buon punto di partenza sarebbero i furbolg Deadwood, che si trovano in molte parti del Felwood. Questi furbolg sono nemici della tribù Timbermaw, e ucciderli migliorerebbe molto la tua reputazione presso i Timbermaw."
S["301eca97"] = "Domani cominceremo l'addestramento dei draghi più promettenti, quindi non dimenticate i giochini da masticare."
S["301f9194"] = "Non posso aiutarti, $N: addestro solo i ladri."
S["30236c96"] = "Saluti, $N. $GBenvenuto:Benvenuta; nel regno di Dalaran. Ci sono delle restrizioni finché la città resta in costruzione. Se hai questioni importanti da presentare ai Kirin Tor, puoi parlare con Arcanist Ginsberg nel belvedere a est."
S["302c7898"] = "Posso esserti d'aiuto?"
S["302d4eb5"] = "Sono fortunato a essere vivo!"
S["3033723e"] = "Prima che il tuo apprendimento possa cominciare, devo chiederti un favore..."
S["30377197"] = "È ORA DI DARCI DENTRO! Vieni a prenderle! <sostituisci questo>"
S["303b92d9"] = "Che strada dovresti prendere? Be', l'unico consiglio che posso darti è di prendere la strada che vuoi!$B$BNon mi ricordo niente!"
S["30431936"] = "Porterò quel faro al cratere sano e salvo, Guse. Puoi contare su di me!"
S["3047462a"] = "Ehi, signorina. Mi sembri $Gun:una; $C dai gusti raffinati in fatto di vino. Devo chiederti un favore, e credo di poterti fare un'offerta che non potrai rifiutare... che te lo dico a fare!"
S["30475499"] = "Prima di poterci aiutare nell'Alterac Valley, $C, devi diventare più forte."
S["30519a2f"] = "Sto studiando un modo per portare il petrolio sottoterra da una grande città all'altra, ma tutti mi dicono che il progetto fa acqua da tutte le parti."
S["3059c801"] = "Awak Awak!"
S["305fcd08"] = "Ma guarda che spettacolo edificante. Pare che i piccoli elfi abbiano amici nei... bassifondi."
S["30711426"] = "Salve, $C. Se sei $Gun amico:un'amica; di Colonel Kurzen, ti farò abbattere sul posto! Ma se sei $Gvenuto:venuta; ad aiutarci, allora ascoltami..."
S["3071ff71"] = "Noi esuli di Gnomeregan siamo messi ancora peggio: le nostre riserve di stoffa stanno finendo! Magari puoi darci una mano, eh?!$B$BPortami le pezze di stoffa che ti avanzano, così rifaremo le scorte. Donandole ti guadagnerai il rispetto e la fiducia degli gnomi di tutto il mondo, e quella è una cosa che il denaro non può comprare! Be', con la stoffa sì, direi, ma non è questo il punto..."
S["307811ff"] = "Forse ce l'hai, forse no. Credo di avere un modo per scoprirlo..."
S["30793a1a"] = "Per noi del Cenarion Circle, qui a Moonglade, Shrine of Remulos è un luogo sacro... quindi, per favore, comportati come si conviene a $Gun visitatore:una visitatrice;.$B$B$GUn visitatore:Una visitatrice; che non vuole ritrovarsi la mia scimitarra piantata in corpo, s'intende."
S["3079fbae"] = "Ok, ok! Non c'è bisogno di diventare violenti. Parlerò. Parlerò!"
S["30806dc6"] = "Muln Earthfury dell'Earthen Ring — i Windshapers saranno lieti di averti come ospite."
S["3083bfb0"] = "%s si dissolve nell'etere, ma i suoi venti ululanti ti risuonano ancora nelle orecchie."
S["308c0cf1"] = "Ricavato dagli stessi rampicanti di Razorfen Kraul, Razorfen Downs è la capitale tradizionale della razza quilboar. Nell'immenso labirinto irto di spine vive un vero e proprio esercito di quilboar fedeli, insieme ai loro sommi sacerdoti — la tribù Death's Head. Ma di recente un'ombra minacciosa è calata sulla rozza tana. Agenti dello Scourge non morto — guidati dal lich Amnennar the Coldbringer — hanno preso il controllo della razza quilboar e fatto del labirinto di spine un bastione della potenza non morta."
S["308cae2a"] = "Ok, sono qui. Vieni a comprare le mie merci mentre puoi ancora approfittarne. Insomma, ti sto dando la prima occasione su questi oggetti."
S["30934269"] = "Ho quello che ti serve, $C."
S["3095198b"] = "$GBenvenuto:Benvenuta; all'ufficio di registrazione delle gilde di Valanaar. In cosa posso aiutarti?"
S["309b8ad4"] = "Che piacere rivederti, $GDottor:Dottoressa; $N. Ho seguito i tuoi progressi e oserei dire che è arrivato il momento di imparare qualche tecnica di bendaggio più avanzata.$B$BTorna da me ogni tanto, man mano che migliori, e ti insegnerò tutto quello che so."
S["30a345c4"] = "Posso insegnarti a usare una canna da pesca per prendere i pesci."
S["30a64c20"] = "Del 2° Battaglione di Stormwind ancora nessuna traccia. Arrivano notizie di Shadowhide in movimento a Nordest."
S["30a8ef5b"] = "Spero che tu non sia $Gvenuto:venuta; fin qui alla Great Forge solo per scaldarti. Su, parla, $Gragazzo:ragazza;: cosa posso fare per te?"
S["30aefd40"] = "A cucire puoi imparare a Orgrimmar, che è a nord. Magari uno degli Orgrimmar Grunts può aiutarti."
S["30b2a3ca"] = "Una corruzione immonda si è insinuata in Westfall. Mentre io facevo il mio dovere sui campi di battaglia di Lordaeron, queste oneste fattorie sono state invase, e ora sono covi di delinquenti e assassini. The People's Militia ha bisogno del tuo aiuto."
S["30b3bdac"] = "L'Icewing Bunker è stato preso dall'Alleanza!"
S["30bb27d0"] = "Va bene, va bene. Voi due potete andare a giocare, ma restate in città. Niente scappatelle di nascosto per andare a dare fastidio a Warg e Khara giù vicino all'acqua."
S["30c124e4"] = "Icebane Breastplate."
S["30dcc982"] = "Non ti metterai sulla via del progresso!"
S["30e31efe"] = "Piacere di conoscerti! Se ti piace armeggiare con gli ingranaggi, sei nel posto giusto!"
S["30f02ecf"] = "%s comincia a emettere strani grugniti. La Tear of the Moons cade a terra e va in frantumi."
S["30f0f5a6"] = "Benvenuti al grande spettacolo, amici. Fatevi avanti a morire!"
S["31009727"] = "Senti, Terry, prendi questi uomini e vattene. Di' a Benedict, o a chi ti ha mandato, che sono morto. E lascia perdere."
S["310a39f2"] = "Hanno ucciso la bestia! Tutto bene a Darkshire!"
S["31116b64"] = "%s si guarda intorno nervosamente."
S["31120fbd"] = "MmmmmMmmmm... Enorme cracker alterato chimicamente...."
S["312684fe"] = "TEST — riavvia campo di battaglia."
S["312af9ea"] = "$GBenvenuto:Benvenuta; alla Cappella della Speranza di Luce, $Gstraniero:straniera;."
S["31331c4a"] = "Si sa che quell'eremita di Mallory ogni tanto prepara qualche pozione per la gente del posto. Ha una casetta sulle colline tra Stormwind e Northshire."
S["31397b0f"] = "Le forze dei Frostwolf ottengono il Grido di Guerra del Generale."
S["313d310a"] = "Hakkar dominerà il mondo!"
S["31413780"] = "Gli aggressori sono fuggiti! Forza e onore all'Orda!"
S["31476f94"] = "Di solito noi orchi siamo un popolo riservato, ma ultimamente nessuno tiene nascosto quello che prova."
S["31573b4f"] = "Arriviamo a oggi: la formula ottenuta funziona e permette di creare schiavi più controllabili, ma il difetto è che il composto inattivo è estremamente instabile.$B$BGallywix, tutti quelli dentro questa torre e tutti quelli fuori sono infettati dal veleno. Ci sta colpendo la mente e il corpo. I nostri organi interni sono diventati molli ed estremamente fragili. Questa è la tua occasione, $N. Non ho la forza di andare avanti e sento che presto diventerò uno di 'loro'."
S["315efdd2"] = "Lasciameli, $N! Basta una tua parola e salto in sella per attaccare il loro ponte!"
S["31668409"] = "Ho appena scoccato una freccia."
S["31689703"] = "%s studia con attenzione il biglietto di Sara Balloo ed emette un lungo, solenne sospiro."
S["316fcf80"] = "La Luce ha parlato!"
S["3177c723"] = "L'arte tessile degli Shen'dorei imita con armonia le correnti fluide e spensierate dei venti. Gli spiriti ci hanno lasciati, e non so dire quando potrò rivederli danzare... eppure la mia arte mi dà grande conforto, anche solo perché mi distrae.$B$BVorresti che insegnassi anche a te a lavorare la stoffa?"
S["3179718c"] = "\"I Flussi Magici e Come Influenzano il Mondo\", di Maginor Dumas. È proprio quello che cercavo."
S["317d3a90"] = "Oh, beh, sono $Gsicuro:sicura; che si farà vedere più tardi."
S["318788b4"] = "Cassetta della posta"
S["318a54da"] = "Abbiamo ordini diretti da Cairne, $R. Non interferire con il compito del Comandante."
S["318b709f"] = "Sulle colline fra Northshire e Stormwind vive un alchimista che potrebbe darti una mano. Perché non vai a trovarlo?"
S["318bfc8c"] = "Mi serve proprio un sistema migliore per sistemare questi libri. Ahh, ecco quello che volevo."
S["318d7930"] = "In Mage Quarter c'è un negozietto nascosto che si chiama Alchemy Needs. Attraversando Mage Quarter vedrai negozi strani di ogni genere, ma se ti tieni sul bordo esterno lo troverai di sicuro."
S["31942b06"] = "Fammi provare! Tu troppo $Gstupido:stupida;!"
S["3197187a"] = "È da anni che Helene Peltskinner scuoia animali per Adele Fielder, che ne ricava oggetti di cuoio. Helene la trovi a casa sua, vicino al Crystal Lake."
S["31979c60"] = "Ti prego, aiutami ad attraversare questa foresta maledetta, $R."
S["319826f7"] = "Grunt! All'attacco!"
S["319f8eae"] = "Sei $Glibero:libera; dal Suo controllo. E anche se sarai $Ggiudicato:giudicata; da esseri inferiori, almeno hai possibilità che lo Scourge non ha!"
S["31ad38e7"] = "Oh, mi dispiace, ma ormai sul cuoio ne sai più tu di me. Se vuoi saperne di più, parla con Faldron, laggiù."
S["31b3907d"] = "Smidollati miserabili! Annegherete in fiumi di sangue!"
S["31bd20b6"] = "Flagello nel Trade Quarter! Distruggete!"
S["31c11e4d"] = "Ora mettiamo questa Rare Earth nella fioriera..."
S["31c3a45f"] = "I miei poteri si sono rinnovati!"
S["31c83601"] = "Come altro poteva succedere? Qualcuno deve aver avvisato i Dark Irons.$B$B<Kharan ti agita il pugno contro.>$B$BLo giuro: se mai uscirò di qui, passerò il resto dei miei giorni a cercare il traditore."
S["31ca3459"] = "La macchina si gira verso di te.$B$BSul retro della macchina c'è una fessura vuota, dalla forma stranamente storta, con un'incisione che dice: \"Propietà de' Cap'n Gelkak Gyromast\""
S["31ce63d3"] = "Salve, $Gavventuriero:avventuriera;. Io sono Rin'wosho, mercante di Zuldazar. Vengo dai South Seas e dalla mia terra natale porto tante merci e oggetti esotici.$B$BSe dimostrerai il tuo valore alla mia tribù, forse farò affari con te. E se hai qualche Gettone d'Onore della mia tribù, forse ne faremo anche di più."
S["31d1895e"] = "Per il Capoguerra!"
S["31d57b78"] = "Sulle ali della morte, io cavalco."
S["31d9893b"] = "Hai appena cominciato a vedere il potere dell'Occhio, $C. Se vuoi favorire le capacità dell'Occhio, c'è un compito che devi portare a termine."
S["31dcdb5f"] = "Non ho più niente da insegnarti. Se vuoi migliorare nella conciatura, parla con Karolek."
S["31e16cee"] = "La creatura più facile da evocare è l'imp. Dovresti già essere in grado di richiamare questo servitore, ma per completezza comincerò da lui."
S["31e56de1"] = "Be'... mi hai quasi impressionato. Suppongo di poter trovare il tempo per qualche lezione..."
S["31f29e2d"] = "$GUn altro:Un'altra; Alchimista, mmh. Dubito che tu sia abile quanto me, quindi forse posso insegnarti qualche tecnica come si deve."
S["31fcd7e6"] = "Gli invasori sono qui!"
S["32018225"] = "Se contro i Qiraji continuiamo a guadagnare terreno, lo dobbiamo agli aiuti più diversi che ci sono arrivati da quasi ogni angolo di Kalimdor.$B$BUna guerra non si combatte solo con i soldati, $N. Tra gli eroi dimenticati di questo conflitto ci sono molti mercanti e artigiani, che riforniscono le nostre forze delle risorse di cui hanno bisogno."
S["32023aa9"] = "Stormpike Commander e Stormpike Lieutenant."
S["3214540c"] = "Ucciderti essere facile."
S["3224dea1"] = "Impari così in fretta, ragazzo, che non ti sto più dietro. Se vuoi andare avanti con l'addestramento, ti consiglio di passare dal mio maestro: si chiama Rotgath, Rotgath Stonebeard, e lo trovi a Ironforge, a The Great Forge."
S["322a43ef"] = "Li vedo ancora con armi? Perché tu lascia loro tenere armi?!"
S["322e09a2"] = "Notte, notte."
S["323114cf"] = "Proprio così, ehm, ragazzo, il materiale bellico sta andando tutto a Silithus, e l'ultimo carico dovrebbe arrivare a giorni. Dopo non ci resterà che aspettare e vedere quale eroe si farà avanti a ricomporre lo Scepter of the Shifting Sands e a suonare il gong sulla Scarab Dais. Solo allora la guerra comincerà ad aprire le porte di Ahn'Qiraj."
S["323a9dce"] = "%s fissa $Gaffamato:affamata; un Deeprun Rat."
S["323cb6db"] = "%s mette via la clava e comincia a menare colpi all'impazzata!"
S["324f9714"] = "Quando la matrice di sintesi dell'Earthen si destabilizza, gli esiti possibili sono due. Avvio rappresentazione di supporto visivo numero uno.$B$BLa prima matrice variante è un prodotto degenerativo della sintesi, designato qui con la nomenclatura comune di \"Trogg\". Questa variante conserva forza e resistenza paragonabili a quelle dell'Earthen, ma la sua capacità di elaborazione cognitiva è stata quasi del tutto compromessa. Nella psiche del trogg gli unici fattori trainanti sono la forza di volontà e una spiccata astuzia."
S["32509970"] = "$GBenvenuto:Benvenuta; a Valanaar, $C."
S["3255954e"] = "Credi davvero di cavartela bene? Ah! Il nostro numero è senza limiti!"
S["32561313"] = "Vuoi dire che non lo sai? La spada che porti sulla schiena — la conoscono come Ashbringer, dal nome del suo primo proprietario."
S["325b6f60"] = "L'Irondeep Mine appartiene all'Alleanza."
S["325b9ea6"] = "Beh, $N, per come la vedo io abbiamo due modi per uscire da questa grotta.$B$BPossiamo muoverci di nascosto — io uso il mantello che mi hai dato e tu dovrai cavartela da $Gsolo:sola;, oppure, ed è forse la scelta più difficile, con le ferite che ho, ci facciamo strada combattendo schiena contro schiena.$B$BDecidi tu: i tuoi punti di forza li conosci meglio di me."
S["3266374a"] = "Questa torta di ciliegie è talmente buona da far piangere uno gnomo adulto."
S["32695292"] = "$GUn altro studente:Un'altra studentessa;. Magnifico. Ecco perché Lydon fa parte della Royal Society of Snobs e può fare ricerca, mentre a me tocca fare l'istruttore. Se vinco un altro premio per l'insegnamento, non la finiranno più di prendermi in giro!"
S["326c2bfa"] = "FINALMENTE SONO SVEGLIO!"
S["3274d671"] = "Non dimenticare di prendere la mia campana dal forziere qui. E ricorda, se mi capita di allontanarmi, suonala e ti ritroverò."
S["327564ea"] = "Ora la tua abilità può migliorarla solo il celebre Doctor Gregory Victor. Lo trovi a Hammerfall, negli Arathi Highlands."
S["327644e9"] = "Non fare $Gil timido:la timida;, offri un giro a tutti!"
S["328738e4"] = "%s vede il suo cucciolo sotto attacco ed è presa da una furia frenetica!"
S["32978f2a"] = "Se ti insegnassi a pilotare un Meccanostruzzo, $C, sprecherei il tuo oro e il mio tempo. Sei troppo $Ggrosso:grossa;!"
S["32a2d785"] = "Sono Ulysses Rackmore, capitano della Gallant, e questo è il diario degli ultimi giorni della mia sventurata nave.$B$BEravamo diretti alla Feathermoon Stronghold con un carico di provviste quando i naga hanno assaltato le fiancate della Gallant. Li abbiamo respinti, ma sapevamo che sarebbero tornati. Per paura di perdere i miei beni più preziosi, ho portato la Gallant verso un'isola al largo della costa di Desolace, dove sorgono antiche rovine degli elfi della notte. È lì che ho lasciato la mia cassa del tesoro."
S["32a2e67b"] = "Fatevi da parte! Non vedete che tra noi camminano degli eroi?"
S["32a8eaa3"] = "Venite da me, veri credenti, e scoprite cosa vi riserva il futuro!"
S["32afd6e0"] = "L'Alta Sacerdotessa banchetterà con le tue ossa!"
S["32b0b959"] = "%s cerca di lanciare Patto di Morte sui suoi servitori!"
S["32b2d634"] = "Rin'ji dire te segreto adesso... $N dovere andare alle Overlook Cliffs. Rin'ji nascosto qualcosa su isola là."
S["32b520a6"] = "Mi spiace, ragazza, per imparare da me non sei ancora all'altezza. Va' da mio figlio Groum: una nuova apprendista gli svolterebbe la giornata."
S["32b908a5"] = "Marketing — Saluto per il riscatto iCoke (S.H.E. non quest)"
S["32c5ff5c"] = "Bah! Così non c'è gusto!"
S["32c6ac77"] = "Cerca la Red Canyon Mining, a nord-est del lago nella Valley of Honor, e parla con Makaru."
S["32c71be4"] = "MORIRE?! Tu fai piangere Pusillin!"
S["32d40bab"] = "La mia anima non è un ninnolo! Mortale, devi liberarmi da queste catene!"
S["32d5c1fe"] = "Attraverso la gemma, Elune trasmetteva la sua infinita saggezza..."
S["32d66639"] = "Qui nella Moonglade le feste le sanno organizzare. Chi l'avrebbe mai detto?"
S["32db0a55"] = "Abbiamo abbastanza rifornimenti per lanciare un assalto via terra. Se vuoi dare l'ordine e pensi di avere i requisiti, parla con Sergeant Yazra Bloodsnarl."
S["32dd6d83"] = "Salve, salve, Amy. È bello essere di nuovo a Lakeshire e rivederti, mia signora."
S["32e153f8"] = "Portami fuori di qui!"
S["32e7e635"] = "Dovresti parlare con Gelman Stonehand. Mi pare che abbia casa nel Dwarven District, ma non me lo ricordo bene. Io darei un'occhiata lì."
S["32ebe285"] = "Non perdete la speranza, Darrowshire! Non cadremo!"
S["32edb612"] = "Il mondo patirà crudeltà smisurate sotto il mio regno."
S["32ef514c"] = "Ti fa onore la cura che hai per il benessere dei tuoi compagni animali. Bulrug può aiutarti: cercalo sull'altura inferiore, fra la banca e la locanda."
S["32f64a67"] = "WOOT! Ce l'ho fatta!"
S["32f82abe"] = "Non dovresti essere in giro a salvare il mondo?"
S["32faa68c"] = "Immagino sia così. Io e i miei soldati scelti facevamo parte di un ordine chiamato Empyrean Blades: eravamo la guardia personale del nostro vecchio capo, lo Shal'nan.$B$BIn tempi incerti come questi facciamo il possibile per aiutare a guidare la milizia cittadina dei peacekeepers, perché siamo quanto di più vicino a dei soldati di professione sia rimasto su Zephras."
S["32fbd77e"] = "Evviva! La mia bambola!"
S["32fff677"] = "Se vuoi tornare in volo a Rut'theran Village, ti conviene parlare con la mia collega elfa della notte, Silva Fil'naveth."
S["33022384"] = "Cerchi un addestramento, eh? Nessuno a Stormwind ti addestrerebbe meglio di me, ma la guardia me lo proibisce. Mi sa che dovrai accontentarti di una di quelle vecchie glorie che bazzicano la Caserma o la Pig and Whistle Tavern nell'Old Town."
S["330be380"] = "Scansione forme di vita.... bersaglio non trovato"
S["330d2804"] = "Ci siamo, $N. La mia roba dovrebbe essere in quella stanza. Coprimi, io entro!"
S["330f5d15"] = "Assassini di quel culto che hai trovato... Muoviamoci prima che qualcun altro ci scopra qui fuori."
S["33132146"] = "Nel Felwood ci sono piante che si possono salvare dalla corruzione con l'unguento Cenarion per piante. So prepararlo con diversi tipi di oggetti: a seconda delle tue abilità, potresti scoprire di avere più di un modo per aiutarmi.$B$BPer lavorare qui ti servirà anche un faro Cenarion, un congegno che ti fa vedere la contaminazione e la corruzione della natura che a occhio nudo ti sfuggono."
S["33270345"] = "Davil Lightfire è morto per le ferite!"
S["33284141"] = "Anche a me ci vorrebbero un bicchiere e un po' di riposo. La trovi nell'angolo nord-ovest di Razor Hill. Salutami Innkeeper Grosk."
S["332c2652"] = "Il vessel of rebirth va rinforzato con l'elementium, e di questo minerale conosco una sola fonte: i piani elementali, nel cuore del nostro mondo.$B$BC'è qualcuno, un Plasmaterra, che su come procurarsi cose del genere forse ne sa più di me. Devi trovare questo Plasmaterra!"
S["33303e4e"] = "$GBenvenuto:Benvenuta; nella nostra casa, $N. Radnaal e io abbiamo poco da offrire, ma quella poca ospitalità che possiamo offrirti è tutta per te."
S["334f9189"] = "$GAmico:Amica; — Stormwind ha bisogno del tuo aiuto e della tua generosità!$B$BUn tempo le nostre scorte di tessuti erano abbondanti, ma ormai sono pericolosamente scarse: Stormwind si sta impegnando su più fronti per ricostituirle e produrre tessuti e bende! Se donassi un po' di stoffa, daresti un aiuto immenso a Stormwind e ti guadagneresti il rispetto dei cittadini!"
S["3350dde8"] = "Attendi mentre cerco di unire i frammenti perché tornino interi."
S["33512dfc"] = "%s implora che qualcuno ponga fine alle sue sofferenze."
S["335d2a0a"] = "Ti prego, torna a Zoram'gar e riferisci il nostro successo a Warsong Runner."
S["3365bbdd"] = "The Razza ha appena fatto altro fertilizzante per Mushgog!"
S["33687eaf"] = "Quando è finita, ero sconvolta. Sapeva cosa sarebbe successo, eppure si è gettato davanti a quella creatura per proteggermi.$B$BNoi windshapers i debiti li paghiamo sempre, e con lui ne ho uno. La sua morte l'abbiamo già vendicata, ma possiamo ancora vendicare ciò che quel mostro gli ha fatto, se sei sempre $Gdisposto:disposta; ad aiutarmi."
S["337af206"] = "Falgran Hastil a rapporto, signore. Scoprirò dove portano le impronte di zoccoli e tornerò a riferire."
S["337dd174"] = "%s divora la carcassa!"
S["3385099c"] = "Ah, ragazzo, sei pronto a partire per l'Alterac Valley e a far assaggiare all'Orda quel che si va cercando?"
S["3385b325"] = "Lascia che ti addestri nelle vie del cacciatore."
S["33893de9"] = "Senz'altro. Dammi un segnale luminoso, Ryson."
S["3390ed87"] = "%s ruggisce furioso."
S["339d9884"] = "Applica la pittura di guerra Gordok!"
S["33a7bd7a"] = "A ovest di qui, in un luogo chiamato Feralas, gli ippogrifi, vecchi compagni degli elfi della notte, sono in pericolo.$B$BMi serve che tu salvi un uovo dalle rovine di Isildien, laggiù a sud. Il Super Egg-O-Matic è in grado di analizzare qualsiasi uovo gli si porti e di stabilire se probabilmente si schiuderà. Poi mando le uova ai druidi, dove sono al sicuro dalle magie oscure degli ogres Gordunni.$B$BTieni presente però, $N, che alcune delle uova salvate sono bad eggs: quelle non si schiuderanno mai."
S["33b2fa8d"] = "L'abbiamo portata dal Comandante nella speranza che i druidi del Cerchio la rimettessero in sesto, e in effetti sono riusciti a svegliarla. Credevamo di aver chiuso con il Cerchio e di poterci rimettere al lavoro.$B$BPer alcune settimane è andato tutto bene. Brann allora era ancora da queste parti, e un minimo di organizzazione c'era. Poi un giorno, all'improvviso, è ricomparsa al nostro accampamento."
S["33c126d0"] = "Viaggiatori e avventurieri, correte alla piazza del paese e approfittate degli splendidi prezzi di Antonio! Venite, venite tutti!"
S["33cdcef3"] = "%s si stiracchia e fa un grande sbadiglio."
S["33e51ff1"] = "A quanto pare devo esercitarmi ancora!"
S["33e831c1"] = "Dovrai aprire il Felhound Tracker Kit e leggere il manuale d'istruzioni. Evoca la bestia quando sei vicino alla penisola dei giganti delle scogliere, a sud di qui."
S["33e83380"] = "Quando la Darkmoon Faire aprirà, la troverai nell'Elwynn Forest. Pianteremo le tende appena a sud di Goldshire!"
S["33ff1e8b"] = "Ehi, e tu ti definisci una guardia del corpo? Mettiti al lavoro e proteggici..."
S["34096c29"] = "Sei debole."
S["3411a1e8"] = "Quando la Darkmoon Faire arriva in città, non lasciarti sfuggire nessuna delle sue straordinarie attrazioni e meraviglie!"
S["3424aee5"] = "Nathanos, ho perso la rotten apple. Me ne serve un'altra."
S["342e01aa"] = "Sei tornat$Go:a; per imparare ancora, $N? Vieni qui e dimostrami che sei pront$Go:a;."
S["342e1d56"] = "Non ora. Hai qualche incarico per me?"
S["3432a970"] = "$GUn altro materialista:Un'altra materialista;, eh? Beh, se sei $Gossessionato:ossessionata; dai tuoi preziosi oggetti, immagino che vorrai depositarli alla Darnassus Bank, nel centro della nostra città."
S["3432d126"] = "Che c'è, $C? L'Orda ha finito tutte le raccolte, e si stanno facendo gli ultimi preparativi mentre l'Alleanza si sforza di recuperare. Ti serve altro?"
S["343b4b07"] = "Ponete fine alla nostra sofferenza!"
S["344440a3"] = "Ehi, tu! Vuoi guadagnarti il rispetto dei nani di Ironforge? Puoi cominciare donando risorse preziose! Ironforge è rimasta a corto di pezze di stoffa, e tessuti e bende non crescono mica sugli alberi, sai!$B$BLe pezze di stoffa che trovi durante le tue avventure non venderle: donale! Così ti guadagnerai la stima del popolo nanico di Ironforge!"
S["34449feb"] = "Non mi piace conversare."
S["34478b15"] = "La tua armatura è pronta, $N."
S["3448b56c"] = "Ah, per andare da uno di loro devi salire sulle grandi alture di Thunder Bluff. Prendi il sentiero che esce a nord da Bloodhoof Village: ai piedi delle rupi troverai un ascensore che ti porta in cima. Lassù chiedi altre indicazioni a uno dei Bluffwatchers."
S["344a9701"] = "Un momento che ricorderò per sempre."
S["344d2e22"] = "Non farmi perdere tempo, $C."
S["344ddba2"] = "$GIntruso:Intrusa;!"
S["3456fc0d"] = "Possibile che un gyrochronatom non si trovi mai quando serve?"
S["3457e9c8"] = "Buon Hallow's End! Ti piace la mia maschera? Fa tanta paura!"
S["3458d228"] = "Oh oh..."
S["3466a9b8"] = "Miranda, potresti dirmi per favore quanto costano in insegne gli oggetti che offri agli avventurieri di reputazione reverita?"
S["346beadd"] = "Si è preso l'unforged rune covered breastplate, quello che serve a fabbricare il demon forged breastplate, ed è scappato senza pagare. Ma non sono $Gsciocco:sciocca;... senza le conoscenze necessarie, o la ricetta per metterle in pratica, il pettorale grezzo non serve a niente.$B$BChissà... se ne starà al sicuro nella sua città, a Blackrock Spire, a cercare di ricavare l'oggetto dalla materia prima? Che non osi andarsene, questo lo so!"
S["34761e68"] = "A metà strada..."
S["347d6efa"] = "Sta' $Gattento:attenta;, $C. Rispetta le nostre usanze, o una maledizione cadrà su di te e sui tuoi."
S["3484f9d9"] = "La Sartoria può tornare molto utile. Una volta mi è toccato ricucirmi un braccio."
S["3485ce0e"] = "Dai retta a me: non sederti vicino alle ombre."
S["348c4d14"] = "Buliwyf, il maestro d'armi nanico delle Timberline Arms di Ironforge, insegna a usare le armi da pugno e da fuoco, le asce e le mazze, sia a una sia a due mani.$B$BBixi Wobblebonk, la maestra d'armi gnoma delle Timberline Arms di Ironforge, insegna a usare la balestra, i pugnali e le armi da lancio.$B$BIlyenia Moonfire, la maestra d'armi elfa della notte, sta alla Terrazza del Guerriero di Darnassus e insegna a usare l'arco, i pugnali, le armi da pugno, il bastone e le armi da lancio."
S["348efd76"] = "Non avrei saputo dirlo meglio."
S["348f2da2"] = "%s recita una preghiera."
S["3496259c"] = "Polar Bracers."
S["349c4163"] = "Il piccoletto se ne sta nascosto in una di 'ste casse, compare. Buona fortuna!"
S["349f99ac"] = "È vero, giovane $R, noi e l'Alleanza abbiamo raccolto e preparato tutto ciò che ci servirà per questo conflitto imminente ad Ahn'Qiraj. Proprio ora queste cose vengono mandate alla Cenarion Hold, e l'ultima dovrebbe arrivare entro un giorno. Quando sarà tutto al suo posto, qualcuno dovrà suonare il gong sulla Scarab Dais per aprire le porte e far cominciare la guerra."
S["34a81b15"] = "Quella volta che io guardato male te, prima che tu $Gdiventato:diventata; nuovo re... ehm... io solo scherzava.$B$BSì!"
S["34bfe84d"] = "Ci sarà dolore..."
S["34c0e59f"] = "E RESTA $Gmorto:morta;!"
S["34c5c521"] = "E resta a terra!"
S["34c71bc0"] = "Arrivano altri gnolls. Tieni duro!"
S["34c828fc"] = "Pensi di poterti avvicinare e che io cominci subito a insegnarti? Ha! Devi fare la gavetta come tutti gli altri!"
S["34c91534"] = "A quel tempo ero un giovane tauren, appena entrato nell'adolescenza, ma sapevo che chi avrebbe affrontato le battaglie per la nostra libertà era ben protetto dalle vesti di colui di cui porto il nome."
S["34d17e06"] = "Assaggia la lama, bastardo!"
S["34d299d0"] = "Bevete! Ce n'è ancora tanta!"
S["34d6f03a"] = "È facile perdersi in questa foresta! Fai attenzione, là fuori."
S["34df8f87"] = "Non resterai $Gdeluso:delusa;, $Gviaggiatore:viaggiatrice;. La Sartoria è un mestiere pieno di gioia."
S["34e10421"] = "Ah, molto gentile. Mentre sbrigo questa piccola faccenda, ti lascio in biblioteca."
S["34e7f9b2"] = "Farò del mio meglio."
S["34f156f0"] = "Le nostre unità campione stanno lasciando il campo. Ci servono altri rifornimenti!"
S["34f21f06"] = "Basta salire in groppa a un wind rider per capire che la sua fama di forza e velocità è ben meritata."
S["35014a4d"] = "Beh... mi costa ammetterlo, ma per continuare l'addestramento devi parlare con mia sorella. Ne sa più di me... per ora! La trovi là, vicino all'auto a razzo."
S["3509a980"] = "Ho il sospetto che gli imps stiano rubando il sapere."
S["350bda48"] = "Ancora un po' $Gdebole, sbilanciato, insicuro:debole, sbilanciata, insicura;. Non il tuo lavoro, $Ggiovincello:giovincella;, sto parlando di te! Allora, sei $Gpronto:pronta; a farti forgiare per diventare $Gun vero fabbro:una vera fabbra; o no?"
S["35130160"] = "Non so perché ti servirebbe un'abilità del genere? Solo la gente disonesta vorrebbe imparare a scassinare le serrature.$B$BSe proprio volessi imparare, immagino che il posto migliore dove cercare sarebbe nell'Old Town. Probabilmente in uno di quei vicoli secondari."
S["351488fa"] = "Quando i nostri rifornimenti sono abbondanti, Field Marshal Teravaine è di stanza nel Field of Strife, presso la nostra postazione di baliste più a sud."
S["3514da35"] = "Non è finita qui, stolti! Tutto sarà consumato alla fine!"
S["351605d3"] = "Non abbiamo nascosto questa roba solo perché tu potessi rubarla!"
S["3517930c"] = "Mi dispiace, Huldar... Ma sembra che ti abbia fuorviato."
S["351eda68"] = "Muori, $R! Queste terre appartengono alla Tribù Stonesplinter!"
S["352aca06"] = "Ho finito di esaminare i teschi, $N, e sono sollevato. Yenniku non è tra loro..."
S["3530c72c"] = "Sollevate i vostri spiriti! Stringetevi attorno al vostro campione, godete della sua gloria! Esultate al grido di battaglia dell'uccisore di draghi!"
S["35339e02"] = "Ma guarda un po', è la Settimana dei Bambini! Cosa posso fare per aiutare?"
S["353d5521"] = "%s fa l'occhiolino a $N con aria d'intesa."
S["35431241"] = "Il guerriero che batte ciglio è un guerriero morto. Vuoi guardare la morte in faccia da $Gguerriero:guerriera;? Allora ti insegnerò a non battere ciglio."
S["3547165f"] = "Toccherà ricominciare da capo, ancora una volta. Quel gigantesco cuore elettrico, almeno, potremmo recuperarlo per il prossimo abomination."
S["3551beaf"] = "Saluti, $N. Sono Doctor Gustaf VanHowzen, chirurgo traumatologo capo della Traumatologia dell'Alleanza."
S["3552abf4"] = "Salve, cittadino. Hai l'aria di un uomo che sa dove va — hai qualche faccenda da sbrigare con la Stormwind Army?"
S["3552b805"] = "Mi stai prendendo in giro? Mi starai prendendo in giro! O è così, o mi prendi per un pagliaccio che sta qui a farti divertire. È questo che pensi? Che sono un pagliaccio? Eh, è così o no! Mi prendi per un pagliaccio, vero!"
S["3553e746"] = "Il diario di Jandice Barov è pieno di sproloqui e deliri sui non morti. Verso la fine c'è quello che sembra uno schema di sartoria per creare una borsa di felcloth, che gli stregoni usano per conservare i soul shards. Vuoi copiare lo schema nel tuo diario?"
S["355a3836"] = "Noi Corridori abbiamo il compito di proteggere chi viaggia per le pianure di Mulgore. Chi minaccia la patria dei tauren rischia di essere punito per mano nostra."
S["355ed63b"] = "Vai all'Hall of the Brave: lì troverai la Profanatrice, Deze Snowbane, che ti aiuterà a raggiungere l'Arathi Basin."
S["355f3721"] = "Il portale si sposterà leggermente: a quel punto, se lanci un incantesimo di vincolo, lo blocchi sul posto."
S["3564aeec"] = "Se il Capitano lo scopre, per me è finita."
S["35653287"] = "Il Pool of Tears nella Swamp of Sorrows custodisce antiche casse chiuse perdute in un'altra epoca."
S["35684e55"] = "Rapido e sicuro. Recidi un tendine qui, taglia un'arteria là. Posso insegnarti a trasformare qualsiasi coltello in una perfetta macchina per uccidere."
S["356ca207"] = "Queste grandi bestie conoscono sentieri che a piedi non troveresti: ti ci porteranno in fretta, e magari strada facendo ti faranno vedere qualcosa di nuovo."
S["357161e5"] = "Padrone, salvami!!"
S["3576658a"] = "Tu che fare, a girare qua intorno? Quei pesci piccoli perché non in catene?!"
S["3577bbde"] = "$GBenvenuto:Benvenuta; nel mio negozio, è bello vedere $Gun altro:un'altra; $GSarto:Sarta; qui a Stormwind. Sei qui per una lezione, forse?"
S["3584e705"] = "Son proprio contento che sei tornata, Shay. Ti prego, non scappare più così! Cosa direi ai tuoi genitori se ti perdessi?"
S["358617d2"] = "Dovremo cancellare i Maraudine dalla nostra lista. È troppo difficile lavorarci insieme..."
S["35873b5c"] = "Questi alberi sono davvero magnifici, non trovi?"
S["3588c9b4"] = "E sia. Ti chiedo solo una cosa: se scopri qualcosa che può aiutarci nelle ricerche sul Twilight's Hammer, fammelo sapere.$B$BChe gli Elementi siano con te, $C."
S["358b5d41"] = "Vrum ko vil forthis regen."
S["358ea532"] = "Noi siamo i suoi servitori giurati: eseguiamo i suoi ordini e imponiamo il suo dominio di ferro. Tagliato fuori dalle energie del suo regno infuocato, Ragnaros è solo l'ombra di ciò che è davvero, ma gli resta forza più che sufficiente per ucciderti."
S["3595cadb"] = "Se hai altro cuoio spesso, mi dispiace ma sei arrivat$Go:a; troppo tardi. Abbiamo tutto quello che ci serve, ma prima di andare puoi chiedere agli altri qui? Probabilmente c'è qualcuno che ha ancora bisogno del tuo aiuto con la sua raccolta."
S["35a03afe"] = "Sono contento che Gazlowe mi abbia dato l'occasione di stare qui, per carità, ma questo posto è più pericoloso di quanto pensassi. E poi fa proprio caldo. E c'è polvere dappertutto. E c'è pure un odore un po' strano. Vabbè! Speriamo che faccia bene agli affari."
S["35a200e8"] = "In edificio di War Quarter, su anello esterno di città."
S["35a3bb33"] = "Se hai abbastanza oro per pagare la lezione, posso insegnarti i segreti per Cavalcare Raptor!"
S["35aecfee"] = "Chi controlla la Tower Point?"
S["35b0d8ea"] = "Mi stai davvero chiedendo dov'è il Fabbro? Non hai mai sentito parlare di The Great Forge!? È lì che si radunano tutti i nostri migliori fabbri per creare armi e armature!$B$BSta proprio nel bel mezzo di Ironforge, e lì troverai uno dei nostri più geniali, Bengus Deepforge."
S["35b2c05c"] = "La carne mi piace ben croccante!"
S["35bf5a94"] = "Non prevedo complicazioni a questo — Aspetta! Che cos'è questo?"
S["35c4782e"] = "PER L'ONORE!"
S["35ef04e3"] = "Lo spirito ti guarda con una pienezza e una consapevolezza che prima non aveva.$B$B\"Mi sento come se mi avessero tolto un grande peso dall'anima. Presto riposerò in pace, per sempre: ora lo so, e aspetto quel momento con pazienza.$B$BGrazie, $Gstraniero:straniera;.\""
S["35f5f782"] = "Nessuno dei due generali è comparso."
S["35ffe408"] = "Non fate rumore durante il rituale. Un solo passo falso potrebbe essere la nostra rovina..."
S["360baf33"] = "Salve, $Gragazzo:ragazza;, se cerchi i migliori affari fuori da Ironforge, sei nel posto giusto."
S["3612a26d"] = "Quest'anno il raccolto è scarso e non possiamo sperare di dargli quello che si aspettano. Nel migliore dei casi ci uccideranno in fretta. È più probabile che si prendano tutto quello che abbiamo e ci lascino morire di fame."
S["3615126b"] = "Le stelle di questo tempo, fari di speranza e di forza per le ere a venire, sono decise a percorrere sentieri nuovi."
S["361d3b2f"] = "La magia può quasi tutto, ma nelle migliaia di anni passati da quando abbiamo lasciato Kalimdor la stagnazione e l'inerzia ci hanno fatto perdere molto di ciò che eravamo. L'High Order cerca di riprendersi l'eredità degli Highborne che ci siamo lasciati alle spalle, e di renderci di nuovo padroni del nostro destino.$B$BPer i Windshapers siamo solo sconsiderati e arroganti. Ipocrisia allo stato puro, a mio parere. Su questa crisi i Windshapers non prendono in considerazione nessuna idea che non sia la loro. E allora chi è davvero arrogante, mi chiedo?"
S["361f402f"] = "$GCattivo:Cattiva;, $N. $N, $Gcattivo:cattiva;!"
S["36215e21"] = "Stavolta vi finisco per sempre!"
S["36223ea0"] = "Sei $Garrivato:arrivata; giusto mentre stavano per gettarmi in pasto ai mostri qui sotto — e per questo ti ringrazio. Forse io — anzi — noi, dello stormo blu, possiamo aiutarti ancora?$B$BHai fatto tanta strada, $R, e hai rischiato molto. Vuoi spingerti ancora più avanti e combattere Nefarian e la sua legione di Blackrock?"
S["3623fbd6"] = "Chiedo scusa, signora. La banca non ha ancora aperto. Se non ti dispiace, ripassa più tardi."
S["3626c25c"] = "Spero che tu sia $Gpronto:pronta; a darti da fare."
S["363afc82"] = "Saluti, $C. $GBenvenuto:Benvenuta; a Nighthaven e in tutta la Moonglade. Il Cenarion Circle accoglie ogni essere che rispetti l'autorità e il comando della natura.$B$BFinché resti qui, abbi cura di preservare l'equilibrio in ogni cosa. I disordini non sono graditi: i nostri guardiani sono addestrati a porre fine a ogni ostilità senza esitare."
S["3640deb8"] = "Che posso fa' per te, mon?"
S["3647a793"] = "Dea, concedimi il potere di sconfiggere i miei nemici! Ascoltami, ti prego, il mio bisogno è disperato e la mia causa è giusta!"
S["364edccf"] = "[PH] Ok, io me la filo... ci vediamo nella Tana di Ragnaros... a dp"
S["36561a7a"] = "La luce purificherà entrambi!"
S["3656c825"] = "Hic!"
S["3658c88e"] = "Se sei $Gdisposto:disposta; a rischiare la pelle per la Luce, puoi andare da Shari Stilwell, vicino alle stalle: saprà assecondare la tua follia."
S["3658f6a8"] = "Io... ho fallito, $N. Il Signore di Rocc... Il Signore di Roccianera è troppo potente. Ha consumato la mia energia con... con facilità. Mi trasformo... io... uccidimi... devi... devi uccidermi."
S["365e9165"] = "Fammi vedere cosa vendi."
S["365ee5e7"] = "Vuoi diventare $Gun forgiatore:una forgiatrice; di spade? Basta chiedere."
S["366010c3"] = "Le difese della torre ora sono al punto più debole. Pattuglie, sentinelle, vedette e perfino lo stesso Gallywix sono tutti infetti e molto vulnerabili alle tue abilità e ai tuoi attacchi speciali.$B$BVoglio vederti entrare in quella torre e, quando ne uscirai, voglio vederti coperto del sangue dei tuoi nemici, con la testa di Grand Foreman Puzik Gallywix tra le mani e l'ultima dose di quel veleno nello zaino. Porta ciò che recuperi a Shenthul. Lui saprà cosa fare... spero."
S["36623831"] = "Shadra, fai di me il tuo avatar!"
S["36663137"] = "La Stormpike Guard va distrutta! Sei $Gpronto:pronta; per l'Alterac Valley, $C?"
S["3667434e"] = "Lo Snowfall Graveyard è sotto attacco! Se nessuno lo ferma, l'Orda lo conquisterà!"
S["3667a2e1"] = "Andiamo, prima che scoprano che sono libera!"
S["366f71b9"] = "Hai bisogno delle mie capacità di alchimista, sì?"
S["3677bf46"] = "Zando'zan of the Shattered Hand. Come può aiutarti Zando'zan? Non può! Non vuole!"
S["367d07ee"] = "Ciao! Se sei all'altezza della sfida, ho una proposta per $Gun cercatore:una cercatrice; di avventure come te!$B$BOltre a lavorare alla mia invenzione, il Super Egg-O-Matic, sto aiutando i druidi nella loro campagna per salvare gli ippogrifi. Quegli uccelli risentono degli effetti malvagi degli ogres Gordunni che abitano le rovine di Feralas, e ne restano sempre meno.$B$BRaccolgo uova di tanti tipi diversi. Mi aiuterai a trovarne qualcuna?"
S["3683b054"] = "Sì, sono riuscito a sigillare di nuovo la reliquia, $N."
S["3686b2f7"] = "Plucky? Ho sentito che il maestro di gara Kronkrider, su in cima alla torre, sa dov'è."
S["368a3eca"] = "C'Thun riconquisterà questo mondo!"
S["368de0bb"] = "2ª catena, prima risposta. PWNED~"
S["3691ace5"] = "Almeno non saremmo più qui a dover pulire."
S["369b3e59"] = "Il villaggio di Dolanaar, in cima a Teldrassil, è dove vive Elder Bladeleaf."
S["369d8b21"] = "Per ora le grandi guerre saranno anche finite, ma in allenamento dobbiamo restarci lo stesso!"
S["36a57b3b"] = "Kelstrum è un chiacchierone e uno spaccone... e per giunta è uno dei guerrieri più abili che incontrerai mai!$B$BTe lo dico io: se vuoi essere $Gaddestrato:addestrata; nell'arte del guerriero, è con lui che devi parlare. Lo trovi di sicuro nell'Hall of Arms, a est dei Gates of Ironforge."
S["36a9fc4f"] = "Cosa NON c'è da fare, vorrai dire!$B$BI locandieri di tutto il mondo distribuiscono leccornie per dolcetto o scherzetto, e molte città sono addobbate per l'occasione! E poi a Southshore Sergeant Hartman ha bisogno di una mano contro i Forsaken e il loro Wickerman Festival.$B$BUn'altra cosa — ho sentito che all'orfanotrofio di Stormwind c'è un bambino malato in cerca di qualcuno che lo aiuti a raccogliere dolcetti per la festa."
S["36b8988b"] = "Hai <sbuffo> aiutato Mangletooth più di quanto avrei mai sognato, $R.$B$BGrazie.$B$BFinché resto prigioniero qui, puoi portarmi i blood shards dei quilboar Bristleback, e io ti benedirò con il potere di Agamaggan."
S["36bf735f"] = "Riesci a vedermi? Sai quanto mi ignorano quassù, solo perché nessuno può vedermi? Finalmente qualcuno con cui parlare, che bello!$B$BAllora, ti avrà $Gmandato:mandata; qualcuno della mia vecchia compagnia di mercenari ancora in vita, giusto? Ma certo!$B$BBasta chiacchiere, però: c'è un sacco di lavoro per te e per me, se vuoi rimettere le cose a posto e restituire a Lord Valthalak il suo spirito!"
S["36c4c07d"] = "Eh? Cosa abbiamo qui?"
S["36ccf5de"] = "<Goretooth sputa.>$B$BSono un guerriero dell'Orda, $N, e mi riempie di rabbia sapere che i nostri nemici se ne stanno in una fortezza a tramare contro di noi, a meno di un giorno di cavalcata da Kargath.$B$BQuanto vorrei liberarmi dai vincoli del dovere e distruggerli tutti in nome del Capoguerra.$B$BAhimè, ognuno di noi ha i suoi ruoli da svolgere."
S["36d1e24a"] = "Cosa NON c'è da fare, vorrai dire!$B$BI locandieri di tutto il mondo distribuiscono leccornie per dolcetto o scherzetto, e molte città sono addobbate per l'occasione! E la sera, appena fuori dall'Undercity, c'è il Wickerman Festival.$B$BUn'altra cosa — ho sentito che qui a Orgrimmar, all'orfanotrofio, c'è una bambina malata in cerca di qualcuno che la aiuti a raccogliere dolcetti per la festa... magari potresti darle una mano tu?"
S["36d8ff37"] = "Ciao! Sono appena tornata dalle Ruins of Kel'Theril, a sud-ovest, dove sono stata a esplorare. Adesso ho deciso di studiare i Wildkin che vivono qui sopra, sul crinale, nell'Owl Wing Thicket.$B$BHai parlato con Erelas Ambersky a Rut'theran Village? Mi ha chiesto lui di venire qui, e forse ha un compito anche per te."
S["36dcc87d"] = "Mi sembra di vedere qualcosa."
S["36df8a0d"] = "Andiamo a giocare! No, raccontami una storia, Papà! No... andiamo a raccogliere i fiori! E giochiamo all'ora del tè! Ho trovato la mia bambolina, te l'ho detto?"
S["36e453d4"] = "A quanto pare l'amore aleggia nell'aria. Spero di non restarne $Gescluso:esclusa;."
S["36f30b40"] = "Avresti qualche moneta da darmi?"
S["370fca8a"] = "Salute, $C. Non ti ho visto da poco a un raduno esclusivo? Hai un'aria familiare, ma del resto questa città è piena di gente.$B$BSe eri a quel convegno, di sicuro ti hanno dato un codice segreto. Dimmelo e in cambio avrai da me un premio speciale."
S["3724961c"] = "Eunice Burch vendere pezzi avanzati. La trovi in Trade Quarter."
S["3725b9bd"] = "L'Iceblood Graveyard si trova sul lato sud del Field of Strife, a est dell'Iceblood Tower.$B$BAl momento nessuna delle due parti lo controlla."
S["37274ee8"] = "Vuoi aiutare The Defilers a combattere The League of Arathor nell'Arathi Basin? Molto bene, allora dovresti rivolgerti a Martin Lindsey. Lo trovi nelle Pools of Vision."
S["373184a5"] = "Pare che gli ultimi beni raccolti partiranno per Silithus entro il prossimo giorno. E una volta fatto, qualcuno dovrà venire a suonare il gong sulla Scarab Dais, fuori da Ahn'Qiraj, per aprire le porte. È allora che le nostre bende torneranno utili."
S["3739ec29"] = "AVANTI! VERSO AHN'QIRAJ!"
S["3740b26a"] = "È dentro questo cerchio di fuoco che devo lanciare l'incantesimo per scacciare gli spiriti dei Signori delle Zanne uccisi."
S["374a8773"] = "La guerra ha un prezzo, $C... un prezzo a cui spesso nessuno pensa. Sono gli orfani — bambini che hanno perso i genitori nei troppi conflitti che infuriano su Azeroth. Chi non ha nessun altro a cui rivolgersi spesso viene a vivere qui, finché non è abbastanza grande da cavarsela da solo.$B$BOgni anno, per una settimana in Primavera, l'Orda si dedica a restituire qualcosa a questi innocenti. Si chiama Settimana dei Bambini."
S["375169ea"] = "Non troverai raccolta di sapere più grande di quella della Royal Library of Stormwind!"
S["37646151"] = "Il culto Al'Aketh si fa sempre più violento, e i Windshapers si ostinano a non riconoscere l'inerzia che ci ha portati a questo punto."
S["376cf4e8"] = "Ah, aspetta, questa è la tenda di Hollee... ed è vuota."
S["376f2c01"] = "Tutto quello che ti serve per cucinare ce l'ho io, mon!"
S["3770d193"] = "Nessun riposo... per i morti furiosi!"
S["377c3cc5"] = "Grazie ancora per avermi riportato il metro portafortuna, $N. Ti giuro che mi aiuta a prendere pesci più grossi!"
S["3781c569"] = "Attaccami pure, ma non mi impedirai di tornare da Quae."
S["3789b2d3"] = "Grazie per il pasto squisito, tesoro, ma devo tornare di là, davanti."
S["379229b9"] = "Le pagine del diario sembrano piene di informazioni su scambi, acquirenti e affari di ogni genere."
S["37937789"] = "$GSciocco:Sciocca; $C! Non puoi niente contro i servitori di Ragnaros!"
S["3796f25f"] = "In tempi lontani vivevamo per la caccia, e cacciavamo per la gloria, per l'onore...$B$BAdesso è tanto diverso?"
S["379887e4"] = "La tua interferenza non sarà tollerata!"
S["3799a176"] = "%s esce dal tugurio di tronchi e ti sorprende a manomettere le scorte di grano!"
S["379d30f0"] = "%s e il Raider Kerr fanno riposare e bere un po' i loro lupi..."
S["379fa7e9"] = "Certo, Paige. Ma fai piano."
S["37a20048"] = "Le tue capacità non bastano per imparare ciò che insegno. Parla piuttosto con Mak, laggiù: potrà aiutarti finché non sarai $Gpronto:pronta; per lezioni più avanzate."
S["37b0f2aa"] = "Ciò che è accaduto qui, in questo tempio maledetto, lo sapranno tutti, $Geroe:eroina;. Sarà scritto nei libri di storia — e la sua leggenda si racconterà da Azeroth fino ai confini più remoti del Nether!"
S["37b4386f"] = "Qualcosa si muove vicino a Southwind Village! È... è una di quelle creature sandworm! Attenzione!"
S["37b85720"] = "Vincono i goblin! Vincono i goblin!"
S["37ba4b59"] = "Colpo quasi perfetto! È un po' storto, ma ci sta che Grumlar sbagli così. Non centrerebbe nemmeno la parete di un fienile."
S["37bfb375"] = "Sai, questo ponte è un po' troppo grande perché lo costruiamo solo noi 6. Uno penserebbe che avrebbero assunto più gente."
S["37c76476"] = "Stavo solo pensando. Fa paura stare qui fuori di questi tempi, sai? Da un momento all'altro questo pezzo d'isola potrebbe staccarsi sotto i miei piedi, e io finirei a precipitare... da qualche parte? Dimmi, tu lo sai almeno cosa succede agli skyborne che cadono dall'isola?"
S["37cc94c0"] = "Quel poco che restava dell'essenza di Thunderaan è stato racchiuso in un talismano di vincolo elementale. Poi Ragnaros l'ha spezzato in due pezzi perfetti. Sono stati affidati ai suoi Luogotenenti..."
S["37d87a55"] = "$GBenvenuto:Benvenuta; in Stormwind Keep, $Gcittadino:cittadina;."
S["37e30b14"] = "Se la rivuoi, devi supplicarmi!"
S["37e584a5"] = "Voi $R volete solo la mia erba."
S["37f00d93"] = "Salute e ben $Gtrovato:trovata;, $N! Arrivi al momento giusto: noi della compagnia Durotar Supply and Logistics cerchiamo sempre nuovi appaltatori.$B$BSe hai talento per raccogliere materiali utili, o le capacità per creare qualcosa da zero, qui un posto per te c'è.$B$BSe hai qualche domanda, fammi sapere."
S["37f34a47"] = "Posso mostrarti quello che desideri sapere, ma devi avere pazienza. Lavora l'acciaio con calma e senti come prende forma sotto il martello. Quando diventerai tutt'uno con l'acciaio, allora capirai."
S["37f6ce3e"] = "Pare che gli spiriti preferiscano te a me. Io il loro richiamo non l'ho ancora sentito, tu invece sembri aver fatto tesoro dei loro insegnamenti. Va' a parlare con Karn, sarà entusiasta di trovare qualcuno che li sente come lui."
S["37f6d032"] = "Tieni a bada i nemici e intanto li riduci a cotolette. L'unico problema è che l'asta lunga mi impedisce di sporcarmi le mani di sangue."
S["37f9fe5b"] = "Porti su di te la corruzione dello Scourge. Preparati a entrare nella Twisting Nether."
S["37fc33ab"] = "Ti do il benvenuto a Theramore, $N.$B$BPerdonami se sono sbrigativa e non ho molto tempo per i convenevoli, ma la mia città viene prima di tutto. Sono troppe le cose che minacciano il nostro modo di vivere e la sacralità dell'Alleanza, e se voglio che il mio popolo resti al sicuro e felice devo vigilare senza sosta contro forze che sfuggono al nostro controllo.$B$BForse in seguito avremo più tempo per parlare."
S["37fe4aa0"] = "Il mio scopo è regolare l'accesso al complesso di Uldum per conto dei Creatori. Consento di entrare nella struttura solo quando il richiedente presenta i dischi di sequenza appropriati.$B$BAl momento nel tuo set di dischi mancano le Piastre di Uldum, requisito primario per l'ingresso. Senza le Piastre di Uldum l'accesso non è concesso."
S["38088f50"] = "$N! $GTraditore:Traditrice; di Ragnaros!"
S["380cfcf7"] = "Non avrei mai pensato che un giorno avrei lasciato la mia terra natale, Westfall. . . ."
S["380efb65"] = "<Jim'bek ti fissa negli occhi mentre fa un lungo tiro dal suo narghilè.>$B$B'Ao, mon. Ti serve un tappeto? Una coperta? O solo un po' di stoffa per il tuo prossimo lavoro? Ci penso io."
S["382a4110"] = "Un'altra interruzione. Come dovrei combinare qualcosa, così? Non rispondere: credi che mi importi quello che hai da dire? Perché invece non vai a seccare il Signor Puzza-Sotto-il-Naso?"
S["3831efe5"] = "Mettiti $Gcomodo:comoda; e ascolterai una sto... *hic* una stor... *hic* una storiaaa *hic* Dannazione!"
S["3838b4ab"] = "Come la maggior parte della mia banda. Siamo sfollati perché la terra ci è crollata sotto i piedi, e qualcuno arriva perfino da altre isole. Io sono della città di Shen'dramar, sulla grande isola. Be', su quella che una volta era la grande isola, direi.$B$BIo e la mia famiglia siamo riusciti a salire su uno degli ultimi velieri del cielo, prima che l'isola intera andasse in pezzi. Credevamo che Zephras ci avrebbe salvati. Be', non è andata così. Sono morti tutti da un pezzo, e adesso eccomi qui, ad aspettare l'esecuzione."
S["383b9c42"] = "Tutto quello che vendo me lo sono procurato da sola. Che sia autentico, te lo garantisco di persona."
S["383e11a2"] = "The Lich King ci ha portato la guerra dal nord ghiacciato, e a sbarrargli la strada ci siamo solo noi dell'Argent Dawn."
S["384137cf"] = "Abbiamo deciso di rinunciare alla protezione e alle comodità dei Sotterranei per sfruttare... ehm, cioè... hmm, sì, esatto, per ESPLORARE il mondo."
S["384776f6"] = "Oh, ciao! Scusa, non ti avevo notato. Sono un'allieva di Mastro Worth, e voglio diventare la sarta migliore che il mondo abbia mai visto!$B$BCon i miei studi, credo di essere vicina a qualcosa di rivoluzionario. La mia ipotesi è che la stoffa, sottoposta a magie oscure abbastanza potenti, possa trasformarsi in qualcosa di straordinario, da usare davvero contro le forze del male!$B$BPer ora è solo un'ipotesi, ma spero di riuscire a dimostrarla, prima o poi! Non sarebbe forte?"
S["3849d7cc"] = "Senza il Grim Guzzler, il tempo libero lo passerei a strappare le ali ai dragon whelps."
S["386574d7"] = "Con i componenti giusti, Zanza può creare gli antichi incantamenti troll. È una magia che ti aiuterà a sconfiggere Hakkar e i suoi servitori.$B$BTi chiedo solo di portarmi due oggetti."
S["3867527a"] = "Temo che il tuo quoziente di oscurità sia troppo basso perché io mi prenda la briga di parlarti ancora. Circola, per favore."
S["3870ceff"] = "Molto bene, Danitha. Abbiate solo cura di voi. Molti Forsaken non riescono a lasciarsi alle spalle il dolore che hanno sofferto per mano dei vivi che brandiscono la luce. La loro diffidenza verso i paladini è profonda."
S["38795d72"] = "Perché mi doveva capitare questa scusa ripugnante e debole di stregone?"
S["387c685a"] = "Se preferisci cacciare all'aperto, i treants di Felwood e gli sferzatori di Un'Goro sono un'ottima fonte di fronde.$B$BSe invece sei più $Gpropenso:propensa; al rischio, nelle ali est e ovest di Dire Maul troverai una scorta quasi illimitata di savage fronds."
S["38802446"] = "Be', salve, $Gcittadino:cittadina;. Mi chiamo Bluntnose, Magistrate Bluntnose per la precisione. Il mio compito è vegliare sul benessere di Thelsamar, e credimi, qui un altro paio di braccia forti fa sempre comodo!"
S["38830313"] = "La volontà di %s vacilla."
S["3888dc8d"] = "Ragnaros? Brutte notizie davvero..."
S["388ef0f0"] = "Al tuo fianco, mia signora!"
S["38911f96"] = "Lo Scourge non prevarrà!"
S["3898cd90"] = "Quando Lolo non vuole rovesciare manco una goccia della sua preziosa birra né sporcarsi il vestitino, chiamano me. Già. Ol' Hansel è il nano che usano quando c'è da dispensare un pochino di giustizia e un bel po' di dolore."
S["38a46a89"] = "Senti la furia delle sabbie!"
S["38a72e5a"] = "La corruzione del Felwood ha intrappolato qui il mio spirito... Forse non troverò mai riposo..."
S["38aa9a2e"] = "Salve, $C, e $Gbenvenuto:benvenuta; alla Darkmoon Faire. Qui alla fiera le cose da fare sono così tante che chi viene per la prima volta può sentirsi un po' frastornato. Per questo ci sono io, ad aiutarti. Hai qualche domanda?"
S["38ae04b4"] = "Tuttavia, questo viaggio sarà pericoloso. Abbiamo bisogno di giovani shen'dorei forti e capaci che si uniscano a noi nell'esplorazione di questo vasto nuovo mondo. Proprio come te, in effetti."
S["38c1439a"] = "Cucina"
S["38c5fa84"] = "Forse prima o poi qualcuno ne renderà conto. Nel frattempo, spero che sia i Windshapers sia l'High Order riconoscano che gli Al'Aketh sono la minaccia più grave per Zephras e mettano da parte tutto il resto."
S["38c95031"] = "Cammino da solo su questa strada: cerco come difendere il mio onore e liberare questa terra dai nostri nemici.$B$BCosa posso fare per te, $N?"
S["38d2d282"] = "<Valennia distoglie lo sguardo per un istante, poi torna a guardarti, esitante.>$B$BLo Shal'nan era il migliore fra noi. Quasi diecimila anni fa, a Eldre'Thalas, fu lui a difendere il nostro popolo dalla follia e dall'oppressione. Fu lo Shal'nan a guidarci attraverso il mare inesplorato, per sfuggire alla vendetta assassina dei nostri antichi nemici.$B$BFu lo Shal'nan a stringere con gli spiriti del vento il patto di amicizia che ci permise di salire a Skywall... e di sopravvivere.$B$BAnche dopo aver rinunciato al potere ed essersi ritirato, restò sempre un capo al servizio del suo popolo."
S["38d8deaf"] = "No! $N... $N! Non lasciarmi! Ti prego..."
S["38d9b82a"] = "Un'ombra avvolge le nostre terre, giovane $C. Prenderai le armi per affrontare questa morte volante?"
S["38da273b"] = "Sbrigatevi! Quando è finita, è finita! Prendete qui le vostre armi, subito!"
S["38db7dbd"] = "Sì, beh... andiamo al monumento dedicato agli eroi delle due Great Wars, la Valley of Heroes. Seguitemi."
S["38e2bcab"] = "MMmmMMmmm. Ha un profumo delizioso, Khara."
S["38e603a5"] = "La battaglia procede bene. Le forze dello Scourge sembrano indebolite, e credo che cacciarle dalle nostre coste sia solo questione di tempo. Con le mie magie ti aiuterò in questa lotta."
S["38ebbaba"] = "Dobbiamo muoverci in fretta. Auberdine non è troppo lontana, ma nella foresta si nascondono molti nemici."
S["38eeeeab"] = "Razorfen Kraul è all'estremità meridionale delle Barrens, sul lato ovest della strada."
S["38f0a52a"] = "In teoria funziona così: ovunque tu sia, ti distruggiamo del tutto con un'esplosione enorme, spediamo le particelle attraverso uno squarcio dimensionale e poi ti ricomponiamo qui, alla macchina, con un'implosione. Trasporto Istantaneo! Magari non funzionerà SEMPRE, ma che razza di ingegnere goblin sei! Se pensassi prima di tutto a sopravvivere, non potresti mai essere un vero Goblin Engineer!$BEcco lo schema che ti serve per costruire lo Squarciatore Dimensionale e provarlo!"
S["38fadd18"] = "La risata di %s si spegne..."
S["38fbaf1a"] = "Che tu sia $Gmaledetto:maledetta;, mortale."
S["39025570"] = "Oh, adesso mi hai fatto arrabbiare! È ora di vedere la vera forza della Pietra delle Maree!"
S["3902a2f3"] = "<Mathredis fissa intensamente il libram.>$B$BSei qui per una fusione? Hai fatto come diceva il libram?"
S["390382ad"] = "Corrono tempi pericolosi, $R. Sta risorgendo un male antico, e a lui non importa se sei dell'Orda o dell'Alleanza."
S["390e1aa9"] = "Se vuoi imparare a conciare il cuoio e a lavorare le pelli, va' a nord, a Orgrimmar: uno degli Orgrimmar Grunts ti saprà indicare la strada per l'Istruttore di Conciatura."
S["3911c2b8"] = "Ecco! Ora va solo ricaricata..."
S["39165c30"] = "<Omarion borbotta qualcosa sottovoce.>$B$BMa certo che posso aiutarti, $Gcaro ragazzo:cara ragazza;. È il mio ultimo desiderio... la mia volontà finale. Ti prego, prendi questo manuale. Le informazioni nelle sue pagine raccolgono tutto ciò che so e che ho imparato negli ultimi 30 e passa anni della mia misera vita. Da' il manuale a quel buono a nulla del mio apprendista, che probabilmente se ne sta seduto sul suo grosso sedere alla Cappella della Speranza della Luce."
S["391d71a8"] = "La giornata se ne va. Mettiamoci in cammino."
S["395117b8"] = "In cosa posso esserti utile?"
S["395a9055"] = "%s si ricompone."
S["395c8958"] = "L'addestramento da apprendista non lo do io. Cerca il tauren Waldor nelle Wailing Caverns, qui nelle Barrens: potrà aiutarti in tutto quello che ti serve."
S["395dc7cd"] = "$GUn altro:Un'altra; Erborista, mmh. Dubito che tu sia abile quanto me, quindi forse posso insegnarti qualche tecnica come si deve."
S["3963fd50"] = "Torno... al mio... riposo."
S["3968d2bf"] = "Il dolore è insopportabile!"
S["397660a2"] = "Per me l'erba fresca che ricopre Teldrassil è un letto buono come un altro, ma a chi ha un debole per il lusso i letti che Saelienne tiene alla Locanda della Craftsman's Terrace vanno più che bene."
S["397c95ff"] = "Hai sentito? $N, qui, dice che il disertore umano Reethe potrebbe essere stato quello che ha dato fuoco alla locanda!"
S["398661eb"] = "La Royal Apothecary Society risponderà all'appello della Dama Oscura: scoprirà la Nuova Piaga e scaccerà dal mondo, una volta per tutte, Arthas e il suo empio Esercito dello Scourge."
S["39867097"] = "%s sbriciola la lacrima in una ciotola di stufato."
S["3986b5a4"] = "È difficile immaginare tanta morte e tanta disperazione racchiuse in un'area così piccola; eppure, oltre la palude, c'è una terra afflitta dal caos e dalla distruzione.$B$B$GAttento:Attenta; a dove metti i piedi, $Gavventuriero:avventuriera;. Le Blasted Lands sono l'ultima dimora di esseri di gran lunga più grandi di te."
S["398fe234"] = "$GSciocco:Sciocca; $C! Non puoi niente contro la mia potenza!"
S["39ac9cbb"] = "Che cosa ti porta in questa parte del mondo, $N?"
S["39ad23ae"] = "Laggiù! Possibile?"
S["39b46d1b"] = "Mi sei mancato tantissimo, Papà!"
S["39c2f192"] = "Ho sentito dire che a Undercity c'è un Istruttore di Estrazione. Arrivarci è facile: esci dal paese verso sud e va' sul retro delle Ruins of Lordaeron. Lì prendi l'ascensore che scende a Undercity e chiedi altre indicazioni a un Undercity Guardian."
S["39c3f49f"] = "Hai idea di quanto tempo sto aspettando qui? E la cena dov'è? Tutto quel tempo andato e niente in mano?"
S["39c500df"] = "Se Gnoarn lo scopre, mi fa la pelle!"
S["39c7a14b"] = "No, che io sappia. Dipende soprattutto dalla regione, a quanto pare: alcune razze le chiamano fanghiglie, altre melme. Sembra più che altro una questione di gusti.$B$BTutte le volte che ho incontrato la melma, lo sludge o la fanghiglia, si trattava in sostanza delle stesse creature. Le differenze sembrano venire dall'ambiente in cui vivono, ed ecco perché ci serve un campione puro."
S["39c8c33c"] = "Nel Trade District c'è una cassetta della posta in un punto comodo, proprio fra la Stormwind Bank e la Locanda The Gilded Rose."
S["39cbe35d"] = "In che cosa posso aiutarti, $Gsignore:signora;?"
S["39cc15f1"] = "Il maestro dei wind rider"
S["39ccd1e3"] = "Se non fossi $Glegato:legata; dal dovere verso Master Ravenholdt, ti seguirei fino ai confini del mondo, $GMaestro:Maestra; $N. Sei la grazia e l'astuzia in persona."
S["39cdde3b"] = "Ti servon delle indicazioni, $Gragazzo:ragazza;?"
S["39ce545f"] = "La terra di Feralas ne ha passate tante, $R. Il suolo, gli alberi, le creature: tutto sta cambiando ciò che Feralas è e sarà.$B$BMa qualunque cosa sia accaduta qui, The Twin Colossals sopra di noi restano una costante..."
S["39d60c48"] = "\"...\"$B$BIl corpo del druido tauren giace immobile. Pare che sia finalmente passato da questo mondo al grande aldilà che gli era stato promesso."
S["39d894ad"] = "Ora possiamo ricostruire! Per l'Orda!"
S["39dc9d00"] = "L'E'ko è la forma sfocata del potere soprannaturale, e il Juju è l'essenza concentrata. Usando un incantesimo potente, io posso trasformare l'E'ko in Juju. Quando diventa Juju, tu poi puoi usare la Cache of Mau'ari per riflettere i poteri su di te."
S["39e0ebad"] = "Chi è amico degli animali è amico mio. Quella che cerchi è l'Hunter's Hall, in cima all'Hunter Rise."
S["39e28bee"] = "È un tentativo di salvataggio! Uccideteli tutti!"
S["39ea0174"] = "Non sfuggirai al tuo destino, Onyxia. È stato profetizzato, una visione risuonata dalle grandi sale di Karazhan. Finisce adesso..."
S["39f2caf4"] = "Bene bene! Per imparare l'Estrazione sei nel posto giusto, $Gragazzo:ragazza;! Alla Deepmountain Mining Guild c'è Geofram Bouldertoe in persona: un istruttore migliore non lo trovi."
S["39fceee9"] = "Devi parlare con Therum Deepforge, il nano. Se vuoi il mio parere, è uno dei migliori fabbri in circolazione. Lo trovi nel cuore del Dwarven District."
S["39ffef87"] = "%s si volta verso sudest e guaisce, poi torna a guardarti."
S["3a002267"] = "Arriva la Darkmoon Faire! Divertimento per bambini di TUTTE le età! Venite, venite tutti!"
S["3a03376a"] = "Ehi, dolcezza, ti serve un passaggio per Grom'gol? Dicono che laggiù, in quelle giungle, le cose si fanno belle bollenti, magari potrei venire con te per una breve vacanza e farti vedere una vera gatta della giungla."
S["3a07f08d"] = "Se il tuo bicchiere è pieno, che lo sia ancora!"
S["3a1a02bc"] = "$GBenvenuto:Benvenuta; nella mia barberia! Offriamo tagli, colorazioni e molto altro.$B$BPossiamo curare la barba, fare piercing, tatuaggi stile elfo notturno, qualsiasi cosa ti serva.$B$BAccomodati e ci mettiamo al lavoro."
S["3a1e2d00"] = "Quanti Ufficiali degli Stormpike sono ancora vivi, Drek'Thar?"
S["3a26dca4"] = "$GPatetico stolto:Patetica stolta;! Ora ti insegnerò il significato del dolore!"
S["3a31fc7b"] = "Morirai."
S["3a32d3a7"] = "Se qualcuno ha rimesso insieme lo scettro magico delle sabbie, allora la guerra contro gli insetti sarà presto. Non vedo l'ora, $C! Le ultime nostre provviste di guerra sono in viaggio verso Silithus e dovrebbero arrivare fra pochi giorni. Va' e porta onore all'Orda!"
S["3a348c93"] = "Farò del mio meglio per tradurre e descrivere ciò che vedo."
S["3a3c03c0"] = "Non....HnnGGhhnn... gius-giusto..."
S["3a3f37c2"] = "Che la Light of Elune splenda su di te, $N! Troverai Aethalas, la nostra maestra di battaglia, sulla Terrazza del Guerriero. Ti aiuterà nel tuo cammino verso la Warsong Gulch."
S["3a4578bf"] = "Benvenuto, fratello mio. Se sei qui per imparare, sarò lieto di addestrarti.$B$BCorrono voci di discordie nel Cenarion Circle, ma non dovresti dare retta a queste chiacchiere. Il nostro Arcidruido, Fandral Staghelm, guida noi e tutta Teldrassil verso la gloria!"
S["3a4d881a"] = "Lo Stonehearth Bunker protegge il fianco orientale del Field of Strife.$B$BNon è controllato da nessuna delle due parti."
S["3a535ee1"] = "All'inizio il Whitereach Post era solo un piccolo campo di caccia... Adesso vogliono tutti aprire bottega e stabilirsi qui.$B$B<Motega scrolla le spalle>"
S["3a53f3a2"] = "Sarà anche vero che i nani Wildhammer hanno destrieri veloci, ma quei grifoni di Aerie Peak lo reggono il calore di The Great Forge? Non credo proprio!"
S["3a54dea3"] = "Verso casa! Stammi vicino, qualunque cosa accada! Lì ho il fucile e le munizioni!"
S["3a6af026"] = "Come va? Io adoro l'odore del cuoio, e tu?"
S["3a6f1dce"] = "Che freddo... e che fame.$B$BPovero amico mio, spero che tu abbia trovato la pace. Non sopporto di pensare a cosa potrebbero averti fatto.$B$BTu! Tu, laggiù! Ti prego, devi aiutarmi a scappare. Uno di loro ha una chiave, riusciresti a trovarla? So che ce l'hanno. Se la prendi, puoi farmi uscire di qui. Probabilmente Trey è già morto, ma c'è ancora tempo! Ti prego, mi aiuti?"
S["3a74557b"] = "Continua a leggere..."
S["3a7b4d5d"] = "Mi fa bene all'anima vedere le mura di Stormwind ergersi forti e alte.$B$BSe vuoi andare a Stratholme, temo di non poterti aiutare al momento. Le torri vicino alla città in fiamme sono ancora contese, e per questo i miei poteri sono troppo deboli per aiutarti. Torna da me quando sarai $Gvittorioso:vittoriosa; laggiù."
S["3a873529"] = "$N ha superato The Gauntlet! Hip hip urrà per $N!"
S["3a87bb98"] = "In Durotar c'è parecchio di buono da scavare, o almeno così ho sentito dire. Tanto che abbiamo un Istruttore di Estrazione proprio qui a Razor Hill: troverai Krunn accanto alla forgia accesa, nell'angolo nord-ovest del villaggio."
S["3a89ccec"] = "L'Orda ha catturato il fabbro!"
S["3a8b6455"] = "Questo lo prometto... Questo lo giuro..."
S["3a909284"] = "Accetta i miei ringraziamenti, $N. Il diario di Yagyin sarà tuo."
S["3a91f617"] = "Mi onori con la tua presenza, $R. Ahimè, per me è troppo tardi. Presto lascerò questo mondo, ma... so così tanto. C'è così tanto in questa mia testa. Così tanto che potrebbe aiutare questo mondo a respingere le bestie di questa cittadella di depravazione.$B$BForse, se sei $Gun maestro:una maestra; in un mestiere... Sì, forse prenderesti il sapere che custodisco e lo useresti per salvare questo mondo."
S["3a99d1f9"] = "È come se l'altare fosse vivo: sembra che ti chiami."
S["3a9b7591"] = "Per raggiungere The Crossroads, $N, segui la strada verso est e poi verso nord."
S["3ab43025"] = "Vattene, immondo flagello!"
S["3aba5c00"] = "Nell'Old Town, alla Pig and Whistle Tavern, lavora un gran cuoco. L'ho visto maneggiare un coltello mentre cucina e, detto fra noi, non credo che sia sempre stato ai fornelli. Non fraintendermi... se vuoi ancora imparare, è il migliore che abbiamo."
S["3abbd288"] = "Questa creatura soffre per gli effetti del vil... Dobbiamo porre fine alle sue sofferenze."
S["3ac04b13"] = "Salute, $C — sono $Gun Ufficiale:un'Ufficiale; degli Encomi e agisco per conto di Undercity. Il mio compito è aiutare gli avventurieri che hanno ricevuto degli Horde Commendation Signets.$B$BAccetto anelli in quantità diverse, ma per te lo scambio più vantaggioso è consegnarmene dieci alla volta. Quando me li porterai, registrerò le tue gesta nei nostri archivi, e così Undercity riconoscerà il tuo impegno e i tuoi servigi."
S["3aca0b2b"] = "Sento l'odore della tua paura, $R."
S["3acb819c"] = "La tua conoscenza del cuoio è più profonda della mia. Forse dovresti far visita ad Aayndia Floralwind nel villaggio di Astranaar, nell'Ashenvale Forest. Ha molto sapere da offrire a $Gun allievo:un'allieva; con le tue capacità."
S["3acee4b4"] = "Muoio... Vedo la luce... gloriossa..."
S["3ad149ea"] = "Reginald Windsor non deve essere toccato! Passerà indisturbato!"
S["3ad88edf"] = "Sono Belanaa Windveil, agente dell'High Order qui su Azeroth. Se vuoi fare una donazione di stoffa alla nostra organizzazione, ti saremo molto grati."
S["3ad9345a"] = "Salve, $N. Qui addestro i giovani ippogrifi e me ne prendo cura. Guardati pure intorno."
S["3aecb883"] = "Grazie per avermi aiutato. Da qui conosco la strada."
S["3af0c76b"] = "Va bene, va bene... adesso dammi un minuto per riprendermi. Me le hai proprio suonate per bene."
S["3b018615"] = "Come va la guardia ai barili...?"
S["3b01e5d8"] = "Va', Reginald. Che la luce guidi la tua mano."
S["3b036393"] = "Ho meno di un terzo delle provviste che servono per passare alle unità veterane."
S["3b0c0772"] = "Sì? Cosa c'è?"
S["3b1122cd"] = "Se vuoi imparare la scuoiatura, ti conviene fare un salto nell'Old Town e passare alla Protective Hide."
S["3b142a0f"] = "Salve, $N. Sono Duke Nicholas Zverenhoff, dell'Argent Dawn."
S["3b14964c"] = "Riposo, $R. Non è il momento delle formalità. Con le forze dell'Alleanza sotto attacco, la protezione dei territori Nanici diventa ancora più cruciale. La recente rivolta dei Trogg è una terribile minaccia per la terra del Re."
S["3b2551f8"] = "Che bello rivederti, Amy. Stai attenta, tesoro. Ora vado a Goldshire."
S["3b25defe"] = "È il momento dell'evento principale! Skarr the Unbreakable è in The Maul!"
S["3b26cdc6"] = "%s si apre. Il contenuto ti assale i sensi con un odore davvero ripugnante. All'interno vedi quelli che sembrano enormi escrementi di uccello e un sacco di sangue."
S["3b28d1f4"] = "Be', sì, una rara ricetta alchemica la conosco. Lascia che te la insegni!"
S["3b2b5825"] = "Hai l'audacia di venire da me per farti addestrare, e la cosa non mi diverte. Passa sotto l'arco, scendi la rampa a sud-est e parla con Doctor Martin Felben: è un Forsaken che può insegnarti le basi."
S["3b2ba700"] = "Smettila di fare il bambino, il Razal'blade. È ora di comportarti come uno dei reparti scelti del Capoguerra. Non vorrai finire come Gargal, vero?"
S["3b2bb3b1"] = "Quindi è per questo che sei venuto? Per cercare di prenderti ciò che è la ragione dell'esistenza dell'Alba e la rovina della Crociata? Con le tue parole riapri vecchie ferite, Comandante!"
S["3b312b25"] = "Cosa abbiamo qui? $N $Gil:la; $C? All'attacco!"
S["3b3b12d2"] = "Dei tuoi beni terreni puoi liberarti alla Thunder Bluff Bank, sull'altura più bassa."
S["3b3bd40d"] = "MI AVVICINO A QUESTO MONDO!"
S["3b3fb0aa"] = "Aspiranti intrusi, temo."
S["3b4348aa"] = "Ahah, ragazzo! L'Alleanza ha raccolto tutto quello che ci serve per far cominciare 'sta guerra qua! Magari l'Orda ci raggiungerà presto?"
S["3b5c7b38"] = "Dov'ero $Grimasto:rimasta;? Ah, sì, dunque: ci hanno catturati. Hanno giustiziato sul posto le mie guardie scelte, hanno risparmiato me e si sono portati via la principessa a dorso di ariete. Mi hanno condotto nelle sale di detenzione della Slag Pit e da lì trasferito in questa prigione.$B$BSe sono ancora $Gvivo:viva;, posso solo supporre che sia perché vogliono un riscatto per la mia misera vita. O forse lo fanno per crudeltà, per farmi rivivere per sempre nella mente quello che è successo. Il rimpianto è il più crudele dei carcerieri, $R."
S["3b5d2335"] = "L'Icewing Bunker è sotto attacco! Se nessuno la ferma, l'Alleanza lo distruggerà!"
S["3b68afa0"] = "...qualunque altra cosa ci sia là fuori, a Skywall. Che gli spiriti ci salvino... è questo il suo piano. Abbattere le protezioni e far entrare il suo 'Signore del Vento'!"
S["3b732ade"] = "Cerca la Zeppelin Landing Tower fuori città, a sud-est."
S["3b815ebe"] = "Uccidete gli intrusi!"
S["3b88c734"] = "Sembra che vi serva un'altra lezione, mortali!"
S["3b951711"] = "Ho notato un fuoco su quell'isola laggiù. E anche un umano. Andiamo a dare un'occhiata, $N."
S["3b962b4a"] = "Cos'era quel rumore? Sembrava un ruggito."
S["3b985c54"] = "Mi fa piacere che tu me lo chieda!$B$BLe professioni sono abilità legate all'artigianato, alla raccolta e, in generale, alla sopravvivenza. Ce ne sono tante fra cui scegliere, e ognuna ha i suoi vantaggi e le sue occasioni di guadagno. Che tu cerchi la ricchezza o un modo per riempire di oggetti utili il magazzino della tua gilda, o che ti piaccia semplicemente indossare un equipaggiamento fatto con le tue mani, c'è una professione che fa per te.$B$BLe ricette da artigiano si imparano dagli istruttori, come quelli che trovi qui intorno, e da tante altre fonti in tutta Azeroth. Una volta imparata una ricetta, puoi creare quell'oggetto quante volte vuoi, sempre che tu riesca a procurarti i materiali necessari."
S["3b9951fb"] = "Lo scudo è giù! Alzatevi, Atal'ai! Alzatevi!"
S["3b9de326"] = "Dev'essere nell'ultima cella. A meno che... non l'abbiano ucciso."
S["3ba74f98"] = "L'abilità con l'arco è una grande risorsa per chiunque, non solo per il cacciatore. Puoi colpire in fretta, in silenzio, e prima che la tua preda possa battere ciglio... è morta."
S["3ba7b742"] = "Fammi vedere di cosa sei capace! Te lo prometto, non te ne pentirai!"
S["3bbad4be"] = "Kazzak è supremo!"
S["3bc179bd"] = "Vorrei inserire il mio codice e-coupon per vincere l'oggetto virtuale."
S["3bcafb93"] = "$N, no fare male A-Me. A-Me, buona."
S["3bcc50cc"] = "Sono davvero in pochi a venirmi a cercare... Che posso fare per te?"
S["3bcf351f"] = "In tutta Stormwind siamo $Ggli unici:le uniche; a vendere fiori sani, e ne abbiamo di splendidi per ogni occasione."
S["3bd1133c"] = "<Narain si appoggia alla fronte una busta ancora chiusa.>$B$BCos'è... Mmmm... Velluto!$B$BCi ho preso?"
S["3bd5de84"] = "General Rajaxx è stato asfaltato. Segniamo un'altra vittoria per Andorov."
S["3be1654b"] = "Grrrr... carne fresca!"
S["3be9c2d3"] = "Oh, Jornah dovrebbe essere in giro per l'accampamento. Se hai qualche domanda, sarà felice di risponderti."
S["3bf111a1"] = "Dove si è cacciato adesso quel ragazzo?"
S["3bfe6e45"] = "La tua presenza ci tempra i nervi, Signora $N."
S["3c019d5c"] = "Ciao, Corbett! Ecco a te! Spero che gli affari nella tua sartoria vadano bene...?"
S["3c028a5a"] = "Cittadini dell'Alleanza, il Signore di Roccianera è morto! Nefarian è stato sconfitto dalla forza unita di $N e dei suoi alleati!"
S["3c0498ce"] = "Quasi fatto! Ancora un pochino!"
S["3c061177"] = "Mi unisco a voi per celebrare la più venerata delle notti — la notte in cui noi Forsaken spezzammo il giogo oppressivo dello Scourge!"
S["3c0e2a18"] = "Oh, io non ho niente da insegnarti, $N. Va' a fare due chiacchiere con Tally Berryfizz, laggiù. Arriva a malapena ai tavoli, ma quando si mette a preparare una pozione, occhio!"
S["3c159af9"] = "Beh, il dovere chiama, no? Prima la campana... per darti vigore!"
S["3c2058cd"] = "Scendi subito da lì! Non voglio che ti arrampichi su quel coso. Non è sicuro."
S["3c245cbb"] = "Ci vogliono braccia forti e cuori coraggiosi per tenere al sicuro la città di Menethil!"
S["3c2c72b0"] = "Me la godrò proprio ad ammazzà 'sti narcisi a bocca spalancata!"
S["3c2ca40c"] = "Me l'aveva detto, mio padre, che sarebbero venuti giorni come questo, con $Guno sconosciuto:una sconosciuta; che mi rivolge la parola e io che devo trattenermi dall'$Gucciderlo:ucciderla;."
S["3c2cb275"] = "Me l'aveva detto, mio padre, che sarebbero venuti giorni come questo, con $Guno sconosciuto:una sconosciuta; che mi rivolge la parola e io che devo trattenermi dall'$Gucciderlo:ucciderla;."
S["3c4106bf"] = "Colpiscimi pure. Rinascerò... Ancora più potente..."
S["3c46d180"] = "Perché non vediamo di cosa sei capace? Se porti a termine il compito, sarò felice di continuare ad addestrarti!"
S["3c4abd5e"] = "Pirati. Li odio. Anzi, non li odio e basta: li disprezzo con ogni fibra del mio essere. Con tutti quei «ARRRRR!» e «YARRR!» e quegli uccellacci orrendi che si tengono come animali da compagnia — come si fa a sopportare i pirati, figuriamoci a essere un pirata?"
S["3c4e37ab"] = "Molto bene. Sei congedato, soldato. Riposati, ma non metterti troppo comodo. Kurzen non ci lascerà in pace per sempre..."
S["3c4fc47a"] = "Mi spiace, ragazzo, per imparare da me non sei ancora all'altezza. Va' da mio figlio Groum: un nuovo apprendista gli svolterebbe la giornata."
S["3c5e1179"] = "%s spezza i suoi legami spettrali con un tremendo fragore di tuono!"
S["3c5f9b1a"] = "Ce l'hai, un po' di abilità: quanto basta per impararti qualche cosa, scommetto. Vediamo cosa posso insegnarti, eh?"
S["3c617bb5"] = "Pazienza..."
S["3c6365fe"] = "%s porta le faville di indurio alla sua forgia."
S["3c6723dc"] = "Ora l'hai fatta grossa. Pensavo fossi meglio della gente di Southshore. Loro avrebbero comprato tutta la mia merce!"
S["3c6e02d7"] = "Che cos'è questa storia? Vuoi rovinare la mia reputazione? Io non insegno ai principianti, signora. Va' a parlare con Milla Fairancora nella Craftsmen's Terrace of Darnassus."
S["3c724689"] = "Non era mia intenzione coinvolgerti in questa faccenda, $N. Da quando ho aiutato un vecchio amico in un'audace incursione a Blackrock Spire, passo ogni ora da $Gsveglio:sveglia; a guardarmi alle spalle."
S["3c828155"] = "Oh, che sfortuna! Le mie abilità non sono abbastanza buone da esserti utili. Pazienza. Parla con Fimble Finespindle, là vicino al telaio. Lavora il cuoio da più tempo di me."
S["3c838974"] = "Abbiate pazienza, vi chiameremo per nome quando sarà il vostro turno. Aiutiamo le persone nell'ordine in cui compaiono sul nostro schermo."
S["3c864150"] = "Adoro le belle sfide; e tu? Ah, ma certo che sì. Ed è proprio per questo che adesso farai esattamente quello che ti dico."
S["3c8917fa"] = "I seguaci della Dama Oscura sono ciechi se pensano di poter resistere alla nostra potenza."
S["3c8e6e3e"] = "Ti devo delle scuse: non sono $Gstato:stata; del tutto $Gsincero:sincera; con te su chi sono davvero. Dovevo essere $Gcerto:certa; di potermi fidare — poche persone avrebbero aiutato senza interesse un vecchio eremita dimenticato.$B$BHai dimostrato di essere una di loro: una persona integra e d'onore."
S["3c9e599e"] = "Ricordate questo giorno, perché grandi eroi dell'Alleanza hanno ucciso Rend Blackhand, il crudele capoguerra dell'Orda Oscura dei Blackrock!"
S["3ca63781"] = "%s corre verso la sua fioriera."
S["3ca67243"] = "Amir maez ante aman arakal amanalar!"
S["3ca7946c"] = "A dire il vero, io preferisco le medicine di una volta... sanguisughe, larve, seghe per ossa... cose così. Be', i gusti son gusti. La nostra Istruttrice di Erboristeria è Faruza: la trovi fuori, vicino alle stalle di Brill."
S["3caabcd8"] = "Padre, lei aveva la coppa di frutta, giusto?"
S["3cb01743"] = "Ragno non prendere libro!"
S["3cb545c4"] = "%s sarà armato tra 3 secondi!"
S["3cbd3f09"] = "Se, o ealdor Gothalgos. Y borne va vohl ru eynes nud aldonoth vrum borne gol odes methrine."
S["3cbe1fcd"] = "Qui è Rigger Gizelton, cerco aiuto per scortare la mia carovana oltre la Mannoroc Coven. Sono sulla strada a est di Predombra."
S["3cc53c54"] = "Ah, lo strato protettivo è quasi sparito. Lo sentite, eroi? Quello... quello è il suono dell'inevitabile. Delle vostre speranze e dei vostri sogni schiacciati sotto il peso del mio essere."
S["3ccc8654"] = "Eranikus è qui! Cercate riparo! Mettetevi al sicuro!"
S["3cceb39b"] = "%s comincia un rito di creazione..."
S["3cd43276"] = "Un essere di grande potere si è risvegliato."
S["3cea48ea"] = "Giornata storta? Assaggia un po' di torta di ciliegie."
S["3cf7a944"] = "Che faccio adesso?"
S["3d021a65"] = "I bambini saltano su e giù pieni di energia giovanile. (PH emote)"
S["3d06d8ab"] = "Lo riporterai in questo mondo, $Gcampione:campionessa;."
S["3d097568"] = "Grazie! Grazie, $Gsacerdote:sacerdotessa;. Ora posso affrontare quegli alberiani corrotti con il potere di Elune dalla mia parte!"
S["3d0b4247"] = "Questi tizi dell'Ordine del Mithril sono tutte femminucce."
S["3d11c5db"] = "Forza, ragazzi, dobbiamo ricostruire questo ponte."
S["3d1644f3"] = "Dove vorresti andare, ragazza? Bastano poche monete, e i miei Grifoni ti ci portano più in fretta persino del cavallo più veloce."
S["3d17c5df"] = "La Stormpike Aid Station è sotto attacco! Se nessuno la ferma, l'Orda la conquisterà!"
S["3d22934a"] = "Ah — aspettavo una vera sfida!"
S["3d27dd8e"] = "Il trasporto dei Windshapers per Azeroth è al molo più a ovest, sul lato sud di Valanaar."
S["3d2d0cac"] = "Parla con Pephredo al Darkbriar Lodge, nella Valley of Spirits: è più in alto della Valley of Strength, verso ovest."
S["3d2f56d5"] = "Co... dove sono? Così... debole.."
S["3d341525"] = "Ah, se vuoi imparare la professione di Incantatore, credo che faccia al caso tuo Gimble Thistlefuzz. Gimble sta nel suo negozio, la Thistlefuzz Arcanery, proprio accanto al Maestro dei Grifoni a The Great Forge."
S["3d398b68"] = "Ho una bella scelta di pozioni e pergamene esotiche. Ma non sono per i deboli di cuore!"
S["3d3d3ceb"] = "Cos'era quel rumore?"
S["3d3d6763"] = "Gimlok! Gimlok! Vieni qui all'istante!"
S["3d42e22e"] = "Haha, tu stare prendendo me in giro, amico. Pele'keiki sapere che tu sapere che noi dell'Orda già avere tutta la roba da guerra che a noi serve. Ora noi solo aspettare che quella Alleanza prende tutta la sua e poi noi cominciare la guerra."
S["3d4e1e29"] = "Fai in fretta, $C. Devo osservare e guidare la crescita di Teldrassil, e mi resta poco tempo da sprecare in chiacchiere oziose."
S["3d55d180"] = "Fate largo! Fate largo!"
S["3d5a3a01"] = "Tutti presenti, SIGNORE!"
S["3d60f784"] = "Ben fatto, $Gsoldato:soldatessa;. Ancora qualche altro e le stalle traboccheranno di cavalcature per portare in battaglia la nostra cavalleria!"
S["3d668aa6"] = "No, Longears non è il mio vero nome. E qual è non ho intenzione di dirtelo, quindi non chiedermelo."
S["3d68d279"] = "Sai già troppo, da me non imparerai niente di nuovo. Se vuoi altro addestramento, parla con la tauren Una, nelle botteghe a nord-ovest dell'altopiano centrale di Thunder Bluff. E salutamela, eh?"
S["3d702cc4"] = "Stupefacente, padrone. La tua incapacità è stupefacente."
S["3d7194ad"] = "Che ti serve, skyborne?"
S["3d71b011"] = "I Sarkhoff... a volte i Sarkhoff vengono a trovarmi. Sono brave persone."
S["3d772002"] = "Molto bene. La nostra scorta di provviste cresce..."
S["3d7f43f0"] = "Finora sono stato clemente con voi, ma ora mi annoiate. Contemplate la magnificenza del mio potere, e disperate!"
S["3d7f5eab"] = "Ah, proprio quello che ci voleva!"
S["3d7f9722"] = "Per quanto mi riguarda, ogni occasione per combattere contro l'Orda, e soprattutto contro gli orchi, è un bel divertimento. Nella Warsong Gulch di battaglia ne troverai in abbondanza, eccome se ne troverai. Vai all'Hall of Arms e parla con Lylandris: ti indicherà la strada."
S["3d83382c"] = "Quando combattevo quella banda del Twilight Hammer nella Palude, mi venivano in mente posti migliori per fare una guerra."
S["3d85522b"] = "Questi documenti sono sorvegliati. Parla con Zamek per creare un diversivo!"
S["3d85a936"] = "Sono stanco di correre, ma queste api non mi lasciano in pace!"
S["3d8604fb"] = "Devo tornare al mio compito. Temo di dover proseguire da solo — tale è la segretezza dei Lunghi Viandanti."
S["3d8889b0"] = "È ora che t'imparo le buone maniere, $Gragazzo:ragazza;."
S["3d9084a3"] = "Se i miei calcoli tornano, la ruota avrà presto fatto il suo tempo!"
S["3d93eae9"] = "Non dare retta a quel vecchio scemo, $Gragazzo:ragazza;. Fa così con tutti. Però ti ho $Gosservato:osservata;; hai davvero talento. Vieni a fare due chiacchiere con me."
S["3da05f67"] = "Distruggere!"
S["3da1c51a"] = "%s scompare nella neve."
S["3db31639"] = "Maggiordomo Attivato."
S["3db789ef"] = "Se vogliamo prenderci queste nuove terre, ci servono posti dove far riposare i corpi provati dai combattimenti. Posa l'ascia accanto al fuoco e racconta le tue grandi battaglie."
S["3dbcce1e"] = "È giunto il momento di offrire di nuovo la mia merce a tutti quelli che passano vicino al Sentinel Hill! Venite, venite tutti!"
S["3dcd6ea8"] = "I tuoi occhi diventeranno dei bei ninnoli!"
S["3dd02335"] = "Dall'interno della pietra giunge un debole sussurro...$B$BSalve, $Gpiccolo:piccola;. Porti notizie per il Templare?"
S["3ddad48b"] = "La Banca"
S["3ddd9c05"] = "Teschi darai e teschi prenderò."
S["3dea8339"] = "Ti conviene imparare da Zamja. Vai al Borstan's Firepit, al piano di sopra de The Drag: quando entri dalla Valley of Strength, prendi le scale a sinistra."
S["3debe651"] = "Warsong Gulch, dici? Allora è con la bella Lylandris che devi parlare, laggiù nell'Hall of Arms."
S["3dec789d"] = "Bene, bene... guarda un po' chi si vede... e cosa posso fare per te, $C?"
S["3df96bc2"] = "Niente birra adesso! La corsa sta per cominciare."
S["3dfc2a81"] = "Bel tiro... ma non perfetto. Forse un po' più a sinistra."
S["3e03554e"] = "Qui a Bloodhoof Village, purtroppo, nessuno insegna Sartoria, ma un istruttore lo trovi a Thunder Bluff. Esci dal villaggio seguendo il sentiero verso nord, finché non incontri degli ascensori. Prendine uno, sali fino in cima all'altura e lassù chiedi indicazioni a uno dei Bluffwatchers."
S["3e04fdd6"] = "Questo non sembra... normale. Guarda quanto è alieno il deserto! Passare di qui potrebbe essere un terribile errore."
S["3e075bbb"] = "Un minatore? Qui non c'è da chiedersi se, $Gragazzo:ragazza;, ma dove! Ti serve Yarr, e credo che lo troverai rintanato laggiù allo Steelgrill's Depot."
S["3e0b8948"] = "Non sopporto più tutti questi sghignazzi e risate diaboliche. Ancora un 'muhahaha' di Lydon e ci faccio saltare tutti in aria."
S["3e0bcaf5"] = "Alcuni di voi non hanno mai combattuto in battaglia. La pace è stata con noi per molti anni. Per molti anni siamo rimasti inattivi, ma per molti anni abbiamo combattuto."
S["3e12e109"] = "Aonda è una brava donna e una vera servitrice di Zephras Isle. Spero che tu riesca a guadagnarti presto la sua fiducia e ad aiutarla a proteggere Shen'dar Village. Che i venti ti guidino, $N."
S["3e1e2e97"] = "Ce ne andremo di qui appena avrò aggiustato questo carro..."
S["3e27798f"] = "$N, farò sapere a tutti i miei amici del Cartello che oggi mi hai salvato la vita. Ecco: dovrò viaggiare leggero, quindi serviti pure della mia scorta di materiali da sartoria e da conciatura! Grazie ancora, ci vediamo!"
S["3e340e06"] = "Oh, va bene. S-sarò qui, se un'altra volta vorrai imparare. G-grazie di aver parlato con me!"
S["3e3d6d51"] = "Certo, certo. Parla con Deze Snowbane nell'Hall of the Brave, nella Valley of Honor di questa città, $C."
S["3e53f782"] = "Ehi Hornizz! Sono tornato! E dietro di me ci sono delle persone che mi hanno tirato fuori dai guai."
S["3e61f961"] = "Ah, molto bene. Sono convinto che tu sia $Gun allievo degno:un'allieva degna;. Ora possiamo cominciare il tuo addestramento..."
S["3e621667"] = "Degli intrusi sono entrati nella covata! Date l'allarme! Proteggete le uova a ogni costo!"
S["3e71db06"] = "Quello è il nostro tesoro, marinaio d'acqua dolce!"
S["3e725b2a"] = "È questo il posto. Accendiamolo."
S["3e74f2b1"] = "Il Cult of the Damned è cresciuto molto. Nascosti fra la gente, ormai, ci sono membri del Culto in quasi ogni città dell'Orda e dell'Alleanza, dalle capitali ai piccoli villaggi fino ai tuguri.$B$BNon fare quella faccia stupita. Il Culto si mette l'uniforme solo per i riti e le cerimonie. Può darsi benissimo che nelle tue avventure tu abbia avuto a che fare con uno di loro senza nemmeno saperlo."
S["3e75329d"] = "Mi scuso per averci messo tanto ad arrivare. Volevo che fosse presente anche Lady Proudmoore."
S["3e76047c"] = "Cosa posso fare per te?"
S["3e7ad4ab"] = "%s scambia qualche parola sottovoce con $N e $Ggli:le; consegna un piccolo oggetto."
S["3e895f35"] = "%s prepara la sua tossina..."
S["3e8b1341"] = "Chi controlla il Frostwolf Graveyard?"
S["3e8e48d9"] = "Alexstrasza, la Protettrice della Vita. Una creatura magnifica."
S["3e8f3c79"] = "<L'ariete ti osserva con calma mentre ti avvicini.>"
S["3e963fc9"] = "Forse un giorno Saru Steelfury ti insegnerà a fare un'ascia buona quanto la mia. Lo trovi a The Burning Anvil, nella Valley of Honor: passata la Red Canyon Mining, scendi per il sentiero a destra."
S["3e9b0cee"] = "Il Principe ha raccontato la storia di The Ashbringer? Fra tutte quelle che racconta, è in assoluto la nostra preferita. Lui invece preferisce il seguito di The Ashbringer. Naturalmente, nessuno è mai riuscito a farselo raccontare."
S["3ea202b0"] = "Una volta ho sentito il vecchio Grimnur dire che aveva pescato una spada. O era un pesce spada? Accidenti a quel Grimnur, ne ha raccontate così tante, di storie da pescatore, che ormai le confondo. Beh, perché non vai a trovarlo laggiù in The Forlorn Cavern e non ti fai dire cos'era?"
S["3eac7a8e"] = "Un Cristallo Ash'ari è stato abbattuto! Ripristinate lo ziggurat prima che la Necropoli sia vulnerabile!"
S["3eacdf1c"] = "Iiik! I demoni sembrano affamati di kodo!"
S["3eae355c"] = "%s ti prosciuga il mana e si trasforma in pietra."
S["3ebdc4b9"] = "Aber? Sei tu...? Oh... ho tanta fame, Aber! TANTA FAME!!"
S["3ec2efee"] = "Cosa cerchi, $Gcittadino:cittadina;?"
S["3eccf218"] = "Il sangue dei nostri nemici sarà versato sul campo di battaglia. I grandi elementali risponderanno al nostro richiamo e schiacceranno tutti quelli che si metteranno sulla nostra strada."
S["3ed2a9c6"] = "A tempo debito le stagioni passano per tutti, ma la tua vita è ancora in primavera. Torna da noi più avanti, $C, quando avrai più esperienza, ti prego."
S["3ed4a2a7"] = "\"Gothalgos Endirvis Koshvel, Rothas A.\" O nagan thor lo vil ras O valesh."
S["3ed85c22"] = "L'Icewing Bunker presidia il passo tra il territorio dell'Alleanza e il Field of Strife.$B$BÈ controllato dall'Orda."
S["3edba29b"] = "La Bank of Orgrimmar sta nella Valley of Strength. Cercala a nord dell'ingresso principale della città."
S["3ee41a75"] = "Allora... la verga. Vediamo di ripararla, che dici?"
S["3ee6ec28"] = "Athrikus ti indica mentre urla parole che ti raschiano l'interno delle orecchie. Sono l'ultima cosa che senti."
S["3eec37ba"] = "Io scendo qui, polli!"
S["3eeef9b5"] = "Affascinante, questo coincide con le teorie secondo cui Un'Goro era la casa dei Titani quando abitavano Kalimdor. Forse era Aman'Thul in persona a vegliare sulle 'Terre degli Dei'."
S["3ef0b2b5"] = "$N, cosa aspetti? Trova Field Marshal Teravaine nel Field of Strife e dagli gli ordini d'assalto. Appena li riceverà, lui e le sue truppe caricheranno l'Orda senza fare prigionieri!"
S["3ef50918"] = "Hai sbagliato orco. Io i principianti non li addestro. Parla con il giovane Whuut, laggiù... e usa parole semplici."
S["3ef6ca09"] = "Aiutatemi a schiacciare questi mingherlini!"
S["3ef7c424"] = "Ma certo, è vicino al letto. Eh, scusa!"
S["3efb51aa"] = "Ahh, eccolo."
S["3efda9b9"] = "Salve, $C. Posso fare qualcosa per te?"
S["3effb28f"] = "Cos'è il Juju?"
S["3f00b440"] = "Le parole sono come frecce. Una volta scoccate, non puoi più tornare indietro."
S["3f0550cf"] = "Venite, piccoli."
S["3f12d04e"] = "Ho qui gli ordini per un attacco alle forze dell'alleanza nei campi centrali. Mi serve qualcuno che li porti al comandante dell'assalto."
S["3f175814"] = "%s comincia a incrinarsi e ad aprirsi..."
S["3f1ac2ab"] = "Fuggite, se volete, codardi! Non vi servirà a niente!"
S["3f2287f6"] = "Spiriti dell'Acqua, io vi lodo e vi chiedo un favore. Avete sentito le suppliche di $N, e confido che le sue intenzioni siano nobili. Vi prego, ci aiuterete?"
S["3f2414d2"] = "Ora siete miei, bambini. Crescerete e diventerete una parte forte dell'Orda!"
S["3f360087"] = "Sono $Gsicuro:sicura; che sia solo incompetenza o distrazione di qualche operaio."
S["3f40c4b4"] = "Ehi, $N.$B$BCome capo, Lotwil non è il più attento che abbia avuto. Anzi, il lavoro lo prende al punto che a volte i suoi servitori restano senza mangiare, o senza paga.$B$B<Lucien guarda Lotwil con aria accigliata.>$B$BMa non per questo devi soffrire."
S["3f40e59d"] = "Sono $Gvenuto:venuta; per imparare, Daio."
S["3f423651"] = "La pace è solo un sogno fugace! Che regni l'INCUBO!"
S["3f43d77b"] = "Dimmi cosa ti serve, e fai in fretta."
S["3f4c43c8"] = "È l'ora della mia meditazione, lasciami solo."
S["3f547f8b"] = "La nostra sorte è la condanna di chiunque affronti il Great Fire."
S["3f6bffb1"] = "Infedeli!"
S["3f75cdf6"] = "\"Sturume Gloin wos Lon Nuff Skilde vil Garde\", ru Faergas Ergin. Waldir vil ras O far kaelsig gol."
S["3f7e7efa"] = "Ho quasi abbastanza rifornimenti per passare alle unità campione."
S["3f8de11e"] = "Puoi star $Gcerto:certa; che Alassin si prenderà buona cura di tutti i tuoi famigli. Abita nella Cenarion Enclave, dove si ritrovano i cacciatori."
S["3f90c45b"] = "La luce sembra averci forsaken."
S["3f90dbb2"] = "Invulnerabile?"
S["3f979d1f"] = "La West Frostwolf Tower protegge il portone tra il Frostwolf Village e la Frostwolf Keep.$B$BNon è controllata da nessuna delle due parti."
S["3f985f95"] = "Cos'è questo? Una scheggiatura nel frammento? Finalmente si vede un punto debole... Non ci vorrà molto."
S["3fa06f4a"] = "$GUn:Una; semplice $C mi sfida? Preparati all'aldilà!"
S["3fa347ba"] = "$GTornato:Tornata; da un lungo viaggio? Riposati e rilassati alla Pig and Whistle!"
S["3fa9f6ff"] = "E a che ti servirebbe uno di quei tipi? Ci dà già abbastanza guai quel ladro di Hulfdan Blackbeard, laggiù in The Forlorn Cavern, e devo forse tenere d'occhio anche te?"
S["3faaf784"] = "Questa terra ora è della Defias Brotherhood!"
S["3fab20b3"] = "Rinascerò, mortali! Incendius mi farà risorgere da queste ceneri!"
S["3fb91544"] = "Mogg, entra in casa. Là fuori non è sicuro finché tuo padre non c'è."
S["3fbc2eb0"] = "Cerchi un istruttore di Alchimia, eh? Io vengo proprio da lì. La signora Berryfizz la trovi a Tinker Town, dove si radunano gli gnomi.$B$B::sospiro:: ...perché, oh perché non ho preso la pozione blu."
S["3fcc9def"] = "Se vogliamo vincere questa guerra, non possiamo starcene con le mani in mano e farci travolgere dalle maree. Dobbiamo colpire forte e in fretta, o Arathi non sarà mai più nostra."
S["3fcf0edd"] = "Adesso basta! Ora te la vedi con me!"
S["3fd200f4"] = "Renataki, of the Thousand Blades.$B$BIl dolore è la sua linfa vitale, la paura la sua alleata. Possa tornare un giorno, portando con sé un gioioso spargimento di sangue.$B$BOra Renataki dimora vicino all'orlo della follia."
S["3fd8982d"] = "Vedo che conosci il segreto dell'acciaio più di me. È un bene, perché è fatto per essere preso. Ora devi viaggiare nella giungla a sud delle terre degli umani, fino alla città goblin della Booty Bay. Lì troverai un goblin di nome Brikk Keencraft. I goblin non mi piacciono, ma la sua conoscenza del segreto dell'acciaio non ha eguali tra quelli che conosco."
S["3fe134e3"] = "Il tuo destino è segnato, Mokvar! Pagherai per i tuoi torti contro il Lord Valthalak!"
S["3fe172c1"] = "Ti melka... A barad lon re bor ti bur..."
S["3fea4d0b"] = "Fa' sapere a Marshal Windsor che sono $Gpronto:pronta;."
S["3fec83ef"] = "Dove mi conduce ora il mio cammino, Jorn?"
S["3ffb3cf7"] = "Salute, $C — sono $Gun Ufficiale:un'Ufficiale; degli Encomi e agisco per conto della tribù Darkspear. Il mio compito è aiutare gli avventurieri che hanno ricevuto degli Horde Commendation Signets.$B$BAccetto anelli in quantità diverse, ma per te lo scambio più vantaggioso è consegnarmene dieci alla volta. Quando me li porterai, registrerò le tue gesta nei nostri archivi, e così la tribù Darkspear riconoscerà il tuo impegno e i tuoi servigi."
S["3ffc2006"] = "Vorrei comprare altri semi di Tharlendris."
S["40210680"] = "$N, ho di nuovo bisogno del tuo aiuto."
S["4021a74d"] = "Non preoccuparti, Old Blanchy, presto ti troveremo qualcosa da mangiare..."
S["4027b292"] = "Una mano a un povero diavolo?"
S["402cb437"] = "Eccellente, $N! Troverai Brogun Stoneshield sulla Terrazza del Guerriero. Può aiutarti a raggiungere l'Alterac Valley."
S["403209d2"] = "Aiuto! Aiuto! Non lasciate che mi mangino!"
S["4034d89c"] = "Icy Scale Breastplate."
S["40376d51"] = "Avessi solo più allievi come te. Sono pochi quelli che si spingono così a fondo in territorio nemico. Rendo omaggio al tuo coraggio."
S["403b158a"] = "Il maestro dei grifoni più vicino sta su a Ironforge, vicino a The Great Forge. Se vuoi viaggiare in grifone, a Ironforge ci devi andare per forza."
S["404298bd"] = "Il momento della guerra è quasi arrivato, $C! Sia l'Orda sia l'Alleanza hanno finito i loro preparativi. Tutto il nostro materiale bellico viene spedito a Silithus proprio mentre parliamo. Mi aspetto che l'ultimo carico arrivi entro un giorno. Quando sarà tutto radunato lì, chi avrà portato a termine l'arduo compito di ricomporre lo Scepter of the Shifting Sands lo batterà contro il Gong degli Scarabei e aprirà le porte di Ahn'Qiraj. Allora comincerà una battaglia come non se ne vedono da secoli!$B$BLok'tar Ogar!"
S["40525bc2"] = "Sull'Hunter Rise trovi Kergul Bloodaxe, pronto ad aiutarti a raggiungere la Warsong Gulch."
S["40564c75"] = "La tua prossima scelta ti attende.$B$BIl tuo signore ti ha mandato in missione diplomatica presso un paese crudele, oggi in guerra con il tuo. Entrambe le parti hanno pagato cara la guerra, e il tuo compito è ottenere una pace che sia onorevole per tutti e due i popoli.$B$BA una cena diplomatica senti per caso il sovrano nemico insultare ferocemente il tuo benevolo signore. Sei abbastanza $Gsicuro:sicura; che non volesse farsi sentire da te, ma l'onore del tuo signore l'ha infangato comunque.$B$BFai la tua scelta."
S["405ecc50"] = "Che cosa sto facendo? Ti manca la visione, forse? Sono $Gun sognatore:una sognatrice;, $Gbuon signore:buona signora;, e sogno un futuro migliore per tutti noi. È chiaro: sono $Gun visionario:una visionaria;.$B$BMa c'è chi vuole tenerci impantanati nella banalità. Ad Arch Druid Staghelm ho detto che ero $Gun sognatore:una sognatrice;, e lui mi ha risposto: \"Beh, al mondo servono anche quelli che scavano i fossi.\"$B$BFinché le catene della banalità non ci verranno strappate di dosso, aiuterò il Cenarion Circle spostando questi mucchi di terra."
S["40601a29"] = "$GBenvenuto:Benvenuta; al Blue Recluse, dove chi ama la magia si ritrova per scaricare la pressione. Non alla lettera, s'intende. Che cosa ti servo, $Gsignore:signora;?"
S["40697df4"] = "Davvero?"
S["407037ce"] = "Salve, $R. È un piacere fare la tua conoscenza."
S["40744d8d"] = "La Coldtooth Mine appartiene ai Kobolds."
S["4074d70f"] = "L'hai sentito, $Gviaggiatore:viaggiatrice;. Parlami di nuovo quando sei $Gpronto:pronta; a parlare con Belgrum."
S["407d3114"] = "Il metallo, come ogni cosa, va usato in equilibrio con la natura. Karn Stonehoof ha allestito una fucina sull'altura inferiore, vicino allo stagno: chiedi consiglio alla sua saggezza."
S["4082f8a6"] = "La sicurezza di questa banca la garantisco col mio stesso sangue, ti basta?"
S["408d5981"] = "Lo SPACCHIAMO CON UN MARTELLO!"
S["40966063"] = "Terrai lontane le persone cattive, vero?"
S["409b7b61"] = "È qui che le cose si fanno interessanti. Il mio piano è seguire la parete della montagna, tenendola alla nostra sinistra. Così non ci perderemo nella giungla e incontreremo meno nemici. Sei $Gpronto:pronta;?"
S["409e157c"] = "Huuup...Huuup...Bleeeeehh!"
S["409f4981"] = "Ciao! Sono Kwee Q. Peddlefeet, e sono qui per scoprire chi è il più popolare fra tutti gli eroi di Azeroth!$B$BMi scalda il cuore vedere tanti fan adoranti che salutano i loro capi, ma... sai cosa me lo scalderebbe ancora di più?$B$BUn bacio!"
S["40a3b142"] = "Il tuo travestimento non mi inganna, tentatrice. È giunta la tua ora di morire."
S["40a7a42a"] = "Una giornata a pescare al Crystal Lake: non c'è niente di meglio. Mi ha insegnato Arnold Leland. Di solito lo trovi sul molo nel Canal District, che pesca dalla mattina alla sera.$B$BOh, e non credere alle storie che ti racconta sui mostri nei canali."
S["40ae7dfc"] = "Come desideri, $Gsignore:signora;."
S["40b5af51"] = "Mi spiace, ma non sono $Gdisposto:disposta; a vendere cavalli a chi non è considerato almeno osannato dal Kingdom of Stormwind. Questi destrieri sono i migliori che troverai in giro, e non vorremmo proprio che finissero in mano ai nostri nemici.$B$BNon che tu sia $Gun nemico:una nemica;, sia chiaro... guadagnati la fiducia di Stormwind e poi potremo fare affari."
S["40b98481"] = "%s spara d'anca alle bottiglie..."
S["40c10b15"] = "The League of Arathor cerca di strappare ai Forsaken i suoi possedimenti ancestrali nell'Arathi Basin. Se vuoi aiutarli, $N, parla con Donal Osgood nell'Hall of Arms."
S["40ca7424"] = "$GBentornato:Bentornata;, $N. Ti ho già detto quanto è bello avere qualcuno con cui parlare?$B$BBene, allora, mettiamoci al lavoro. Qual è la prossima cosa che dobbiamo fare?"
S["40ce5d6c"] = "Tu dovere andare in The Apothecarium, su anello interno. Lì Martha Alliestar insegnare a te come raccogliere fiori."
S["40df1017"] = "Sei proprio una benedizione, $N. Grazie."
S["40e14be2"] = "%s è visibilmente indebolito. La Maledizione Vile funziona!"
S["40e182d9"] = "Ce l'hai fatta, $N! <La voce stranamente familiare sembra provenire dalla fiala!> Torna in fretta! Le scorie resteranno stabili solo per trenta minuti."
S["40e46092"] = "Raaaaaaaaaaaaarrrr!"
S["40fa3bd4"] = "Io sente puzza di vivi!"
S["41025517"] = "Ehm... credo tu sia un po' troppo grande per cavalcare un Mechano-strider, signore. Finiresti per schiacciarne i servo-bilanciatori di precisione!"
S["412e9de7"] = "Il nostro capitano è caduto!"
S["413075bc"] = "Sei $Gvenuto:venuta; da me per essere $Gistruito:istruita;, e in cambio ho un favore da chiederti. Portalo a termine e sarai $Gricompensato:ricompensata;."
S["4136be6f"] = "%s comincia a sprigionare fumo e prende fuoco! Hai la sensazione che dovresti SCAPPARE!"
S["413d18dd"] = "Tu non diventa $Gil re:la regina; se non parla con Mizzle! Parla con Mizzle l'Astuto!"
S["4147a4a3"] = "Dobbiamo concentrare i nostri pensieri sul Cerchio del Richiamo, se vogliamo che il Forest Lord arrivi! Dobbiamo sbrigarci! Concentrate le vostre energie!"
S["414d6b42"] = "Buongiorno, $C."
S["415c8d89"] = "Gli invasori Kolkar battono in ritirata!"
S["41617dea"] = "Non profanerete questi misteri!"
S["4169ce1a"] = "Il Flagello attacca il Magic Quarter!"
S["416baa1b"] = "Sì! Ce l'hanno fatta! Gli sprite darters catturati ce l'hanno fatta!"
S["4177d7d3"] = "I documenti necessari può dartili Lysheana, che risiede nella Craftsmen's Terrace, nel nord-est di Darnassus. Possa la tua compagnia portare gloria agli Elfi della Notte!"
S["4178643d"] = "Le tue lettere d'amore puoi ritirarle fuori dalla banca, al centro della Valley of Strength."
S["417f67c6"] = "Certo, $N.$B$BGli avventurieri riveriti presso l'Alba devono consegnare 14 insegne in tutto per accedere agli oggetti superiori. Per quelli ancora più potenti, ne servono 90 in totale.$B$BA chi è riverito dall'Alba il prezzo degli oggetti superiori sembrerà piuttosto ragionevole! Quello degli oggetti più potenti, invece, resta comunque alto."
S["418231a0"] = "Mmh... sì, ho una ricetta che potrebbe tornarti utile. Lascia che te la insegni!"
S["41848f05"] = "IN RIGA, VERMI!"
S["4184d253"] = "La stoffa va bene. Io, però, preferisco lavorare la pelle umana."
S["418b363f"] = "Qui a Dun Morogh di scuoiatori non ne troverai, $Gragazzo:ragazza;: se cerchi qualcuno che ti addestri, stanno quasi tutti a Ironforge."
S["418c48ab"] = "%s è $Gstato ingabbiato:stata ingabbiata;."
S["418c7419"] = "Khara canticchia una vecchia melodia nanica mentre cucina."
S["4197449d"] = "Vedi, il nuovo trituratore della Venture Company è meglio del mio ultimo modello, dalle mani intercambiabili alle impugnature di comando! Il capo mi ha dato una scadenza piuttosto rigida, ma né io né i miei ragazzi abbiamo avuto un'idea.$B$BVisto che non funzionava niente, abbiamo deciso di \"prendere in prestito\" uno dei loro prototipi. Ho mandato Wizzlecrank a rubarne uno alla Sludge Fen, ma non è ancora tornato!"
S["41a53815"] = "L'ULTIMA VOLTA SEI STATO COSÌ SPORTIVO... VIENI FUORI!"
S["41a5c39a"] = "Se sono occupato? Che vorresti dire? Credi che passi la giornata qui a girarmi i pollici? Se vuoi comprare qualcosa, parla con Handor."
S["41a9500d"] = "Osserva il nemico, $R. Guarda in che stato la forza dell'Orda riduce persino il più potente dei draghi! Chi ci si oppone farà la stessa fine!"
S["41c27cac"] = "Elune-adore, fratello mio. Qui sei il benvenuto. Parla, e farò quanto posso per aiutarti."
S["41c6a539"] = "Hai già liberato Drull? Non so dove lo tengano prigioniero."
S["41d4d98d"] = "Pensate di aver già vinto? Forse vi serve un'altra lezione di dolore!"
S["41dc42d7"] = "Dal fuoco più ardente nasce l'acciaio più forte."
S["41e6edd8"] = "Nemmeno un saluto per il tuo vecchio amico Narain? Chi ti aspettavi???"
S["41e7565e"] = "Ma insomma, non serve implorare! Tanto ho quasi finito la storia.$B$BAllora, tutta la compagnia sta in mezzo a quell'enorme sala a contendersi quest'amuleto, e sai come rimbomba là dentro! Alla fine è stato spezzato in tre parti: abbiamo tirato i dadi e sono andate a persone o gruppi diversi.$B$BIl resto però è un po' confuso, perché è stato più o meno allora che lo spirito del vecchio Valthalak ha deciso di fare il suo ingresso e di mettersi a evocare tutti questi spectral assassins."
S["41e775d8"] = "Sull'altura, da Mountaintop Bait & Tackle, Kah Mistrunner ti mostrerà come trovare pace interiore e serenità mentre peschi il tuo prossimo pasto."
S["420947d6"] = "I cancelli interni di Ahn'Qiraj si spalancano con fragore."
S["420da310"] = "Devo concentrare le mie energie su questo coltello. Così dovrei cogliere alcune delle impronte psichiche più forti legate a lui."
S["4213ef61"] = "Prendete nota di quanto è delicata la dieta del drago appestato. Basterà solo carne terrorizzata."
S["4215d455"] = "Bene! Si vede che i miei sforzi non andranno sprecati!"
S["42199387"] = "Vedi, il nuovo trituratore della Venture Company è migliore del mio ultimo modello, dalle mani intercambiabili alle impugnature di comando!$B$BIl mio capo mi ha dato una scadenza piuttosto rigida, ma io e i miei ragazzi non siamo riusciti a inventarci niente. Non funzionava nulla, così abbiamo deciso di \"prendere in prestito\" uno dei loro prototipi. Ho mandato Wizzlecrank alla Sludge Fen a rubarne uno, ma non è ancora tornato!"
S["4219c36c"] = "Ne sai più di me, poco ma sicuro. Però facciamo così: va' a parlare con mio pa'. Vorrà che gli dimostri quanto vali, ma come maestro è davvero ottimo. Si chiama Rotgath, e lo trovi vicino alle incudini che lavora l'acciaio per il vecchio Bengus."
S["42268325"] = "È la stagione dei grandi affari! Fah la la la la!"
S["4226c1e2"] = "Va' a parlare con i capi dei Windshapers e dell'High Order. Non vanno d'accordo, ma credo che possano capire che la minaccia più grande sono gli Al'Aketh. Convincili ad accettare il piano e poi torna qui."
S["422d296d"] = "Questa terra appartiene ai Dark Iron Dwarves. Preparati a vedere l'aldilà, $C!"
S["422f84bd"] = "Io so parlare la lingua dei gattini, e l'Effsee ha detto grazie."
S["42351c72"] = "Dalla tua abilità si vede che la nostra arte ti sta a cuore da tempo, ma vorrei altre prove del tuo impegno. Ti affiderò un compito. Portalo a termine e sarò soddisfatta."
S["42358418"] = "Quei tipi da ufficio stanno tutti a Ironforge. Se ti servono i documenti per fondare una gilda, dovrai passare dall'Ironforge Visitor's Center."
S["42449a06"] = "La fine è su di voi!"
S["42449a13"] = "La fine è su di voi."
S["42459186"] = "Certo. Vi attende nella biblioteca."
S["42489cf9"] = "Sì, mi aspettavo che saresti $Gtornato:tornata;. Poco fa ho mandato fuori Korra, che ha trovato la Verga di Dartol abbandonata nella foresta.$B$BCi è costata tanta fatica recuperarla, $N. Per favore, in futuro cerca di non trattarla con tanta leggerezza."
S["424948a9"] = "Quante altre provviste servono per lanciare gli assalti di terra?"
S["42494b9e"] = "|cffffff00La Plaguewood Tower è stata conquistata dall'Orda!|r"
S["424d68dd"] = "%s svanisce nella nebbia..."
S["4251636c"] = "Il mondo ha un debito con te e con i tuoi alleati, $N."
S["4253d19e"] = "Anya Maulray sta alla locanda, sull'anello superiore del Trade Quarter."
S["4266220a"] = "Noh deh Siame skam yu ju duti."
S["4266608e"] = "Un istruttore di classe"
S["426d7707"] = "Gli spiriti guidano i nostri passi mentre seguiamo i nostri sentieri nella vita, come posso guidare i tuoi?"
S["4271c15c"] = "Plucky non vuole far sapere a Tirth che è ancora nello Shimmering Flats, e così si è trasformato in un pollo!$B$BSe lo trovi, fagli cenno di venire da te: magari salta fuori dal nascondiglio."
S["4283c7ca"] = "Mmrrhmm... cosa... cosa sta succedendo? Cos'è... questo?"
S["42860bcb"] = "Immergetevi nel mio potere! Bevete la mia forza! Combattete per la gloria dell'Orda!"
S["42886ca5"] = "Ora dobbiamo proseguire."
S["428f6f94"] = "Ti serve un addestramento? Be', Azar Stronghammer è sempre pronto a insegnare un paio di cose ai paladini più giovani. Va' a trovarlo nella Thunderbrew Distillery."
S["4290362d"] = "Non si tratta di lealtà, ma di onore. E di onore quell'orco ne sa più di quanto ne abbia mai saputo il Lord Ammiraglio. Per questo me ne sono andato."
S["4291880b"] = "Nel nord di Darkshore scorre il Cliffspring River, che scende dalle terre oggi chiamate Felwood. Da dove il fiume sfocia nella Mist's Edge, dirigiti a nord fin dove comincia l'oceano più profondo. Ciò che cerchi potresti trovarlo presso una formazione rocciosa che alcuni, per la sua forma, chiamano Stone Claw.$B$BTi avverto — gli squali volpe si radunano attorno allo Stone Claw e attaccano chiunque sconfini nel loro territorio."
S["4291e752"] = "Signora insegna tu fare oggetti magici. Lei stare in anello interno di The Apothecarium."
S["429771a2"] = "Buono, buono, amico mio. Un momento..."
S["429a9dc9"] = "Questi ordini devono arrivare a High General Abbendis!"
S["429bcf4a"] = "Giustizia è fatta!"
S["42a66ac7"] = "Me ne vado da qui!"
S["42aa6b47"] = "Hai finito il compito di ieri? Se l'hai finito, siediti vicino a me!"
S["42ad531a"] = "È molto triste pensare a quello che è successo a quelle povere anime non morte. Archmage Shymm lo trovi a riflettere vicino alle Pools of Vision, sotto la Spirit Rise."
S["42b92a63"] = "Ehehe... ho fatto una battuta, vero? Druidica per natura... quanto sono spiritoso."
S["42c4799e"] = "Ti giuro il mio amore per sempre. La morte non può cancellarlo, così come sono certa che tu ricordi ancora il tuo amore per me."
S["42d02a29"] = "Il nostro padrone ti vuole!"
S["42d2a2a4"] = "AH, UN BANCHETTO! CHI HA LASCIATO QUESTO QUI...?"
S["42d9f262"] = "Grazie per la domanda, $C, ma abbiamo tutto il pinnagialla maculato necessario. Qui però ci sono altri che potrebbero ancora raccogliere materiale per la guerra imminente. Cercali, e che la dea risplenda su di te."
S["42e2d3a3"] = "Andrà tutto bene."
S["42e89b42"] = "Il maestro delle stalle, Morganus, sta davanti alle stalle, pensa un po'."
S["42eca302"] = "Cerchi Hogral? Be', hai provato alla taverna? Och! Se cerchi un ladro, e per giunta un nano, devi cominciare dalla Locanda! Va' a dare un'occhiata, su."
S["42ecf519"] = "Adoro la torta."
S["42f1b8ee"] = "Uff! Credo di aver mangiato troppo. Devo allargare la cintura di qualche buco."
S["43068ae8"] = "$N, ti prego, guarda il campione di Liana Vilstelo che ho preso dalle caverne, così saprai cosa cercare..."
S["43082ae3"] = "Anathera e Latherion combatterono schiena contro schiena dove la battaglia era più feroce. Due amanti decisi a sopravvivere insieme alla guerra."
S["43148294"] = "Ah ah! Ora che il Magistrato è caduto, Alterac e Hillsbrad torneranno sotto il nostro legittimo dominio. Ritirata!"
S["4318c15b"] = "Salute, $C! $GBenvenuto:Benvenuta; alla festa!"
S["4319c898"] = "Dicono che questa nightsaber sia docile con gli elfi della notte e con i loro alleati, e questo ne fa un'avversaria ancora più degna. Quando va a caccia, Shadumbra segue un percorso che dal Raynewood Retreat, a ovest di qui, arriva fino alle terre ancora più a ovest. Ha il pelo color pece, e non sottovalutare la sua velocità."
S["431e4f09"] = "Saluti! Sono un guardiano dell'accesso. Per favore, usa i dischi corretti per accedere a Uldum."
S["43240606"] = "Hai la mente distratta. Mi nascondi qualcosa?"
S["4333279f"] = "Sta' $Gattento:attenta; nel deserto, $C."
S["43337a12"] = "Morte agli uomini del Custode!"
S["4333eb42"] = "Lysta, fai entrare i prigionieri non morti."
S["433a37b6"] = "Mau'ari lo sa perché la cerchi...$B$BL'E'ko che trovi nel mondo portalo a me, e io te lo posso trasformare."
S["43405750"] = "Il Capitano è morto."
S["43505e71"] = "Sì, sì. Mmh, sembra che rimandi a un altro volume. Mi sa che dovrò trovare anche quello."
S["43512fbe"] = "Temo che la lama che stringi fra le mani non si possa più salvare: l'odio è troppo profondo. Ma non perdere la speranza, $C. Quando un capitolo si chiude, se ne apre uno nuovo.$B$BTrova suo figlio — forse non incontrerai mai un uomo più devoto e pio. Si dice che sappia forgiare di nuovo The Ashbringer, senza bisogno della vecchia lama corrotta."
S["4359320e"] = "Somministro pugni furiosi a $N!"
S["435bf010"] = "Va bene, ci vado! Smettila di urlare!"
S["435c80c9"] = "%s si riscuote dal delirio."
S["4360fd8d"] = "Il grande disegno della Somma Sacerdotessa è in moto! Non c'è niente che tu possa fare per fermarlo!"
S["43615a6a"] = "Ora che hai avuto modo di studiare l'imp, passiamo al servitore successivo che potrai evocare, l'Ombra del Vuoto."
S["436f4ad7"] = "Ora lo sento, $N. Ashenvale si trova in fondo a questo sentiero."
S["437a47c3"] = "Muori, intruso!"
S["4386a7c6"] = "Guardie! Guardie!"
S["4387e119"] = "Abbassa la voce, $Gstraniero:straniera;. Non vorrai disturbare il Maestro mentre medita."
S["438dc10d"] = "$GAllievo:Allieva; lavorerà più duro, maestro!"
S["4390ded7"] = "Il Dun Baldar South Bunker protegge i fianchi meridionale e orientale di Dun Baldar.$B$BÈ controllato dall'Alleanza."
S["43930836"] = "Cosa, cosa?!? Tutti dobbiamo fare profitti... e con le mani in mano non ci si riesce."
S["43989ca8"] = "Gli antenati ci insegnano che ognuno deve essere forte, ma che insieme si è più al sicuro. Vuoi fondare una gilda per difendere l'onore di Thunder Bluff?"
S["43a2461e"] = "Abbiamo avuto dei problemi: in giro per Azeroth sono sparite delle spedizioni. Se ne trovi qualcuna, ti sarei grata se me la riportassi."
S["43a5664e"] = "Sta scappando!"
S["43a5f0b6"] = "Portami abbastanza vicino alla nostra base e potrò canalizzare un teletrasporto!"
S["43a660b0"] = "Mi dispiace, Leonid, ma devo rifiutare. Molto è cambiato, ma i Forsaken sono ancora il popolo che abbiamo giurato di proteggere."
S["43a84b0a"] = "C'è solo una persona più abile di me, e tu sei $Gpronto:pronta; a ricevere il suo sapere. Si chiama Annora, e la troverai... a Uldaman."
S["43ad49b1"] = "Mi hanno detto che a Thunder Bluff, a nord, c'è un Istruttore di Estrazione. Segui la strada che esce dal villaggio e, una volta $Garrivato:arrivata;, prendi l'ascensore fino in cima all'altura. Lassù uno qualsiasi dei Bluffwatchers dovrebbe saperti aiutare."
S["43b4545c"] = "Per qualunque cosa ti serva in fatto di magia, quella maghetta laggiù nell'Hall of Mysteries, Bink, dovrebbe saperti dare una mano.$B$BL'Hall of Mysteries è subito a nord dei cancelli di Ironforge."
S["43bc6dba"] = "Sai abbastanza da essere $Gpericoloso:pericolosa;, ma secondo me hai ancora bisogno di addestramento, $N."
S["43c609ff"] = "I recipienti muisek ora sono pronti, $N."
S["43c678c4"] = "Difendete i bunker!"
S["43ce2ef4"] = "Non capisco come facciano queste bestiacce a vivere qui... accidenti, che puzza!"
S["43ce846f"] = "The Argent Dawn ti saluta, $C. Sono Hasana — una dei pochi quartiermastri che hanno il permesso di occuparsi dell'equipaggiamento e dei materiali della Dawn.$B$BMentre combatti il male per conto nostro — e intanto ti guadagni il nostro rispetto e la nostra fiducia — riceverai da Officer Garush dei gettoni del valore. Puoi usarli in due modi: spenderli per salire di posizione nei nostri ranghi, oppure come moneta per comprare oggetti speciali.$B$BPiù la tua posizione presso la Dawn migliorerà, più oggetti scoprirai di avere a disposizione."
S["43d03894"] = "%s ricambia il gesto maleducato di $N."
S["43dd1ccb"] = "Il Kirin Tor ha ignorato i miei avvertimenti! L'Alleanza è una farsa. Arugal è uno stolto sconsiderato."
S["43e319db"] = "Le nostre unità sono passate a Veterano, ma non ho abbastanza rifornimenti per portarle a Campione."
S["43e48620"] = "%s lancia uno strillo per chiamare aiuto!"
S["43eaad86"] = "Sono molto $Gsorpreso:sorpresa; che $Guno:una; così $Gsbadato:sbadata; sia $Garrivato:arrivata; fin qua...$B$BSì, tu puoi avere un altro amuleto, ma Mau'ari è molto scontenta di quello che hai fatto!$B$BOra vai."
S["43efd100"] = "Ahah! Scommetto che pensavate di aver finito!"
S["43f1440a"] = "Se ora riusciamo a tenerli a bada, sono sicuro che ne saremo fuori."
S["43fcca7d"] = "Fai un salto al Blue Recluse. Un luogo dove tutti conoscono il tuo nome!"
S["440537e0"] = "Gli spiriti di Stonetalon sono ancora furiosi, $N."
S["44055d4d"] = "Da molto tempo sento che stai arrivando, $N. Era scritto nel disegno delle stelle."
S["44101144"] = "Venite, Sognatori, e reclamate la vostra vendetta!"
S["4411daef"] = "Ehi, $C, come butta?"
S["4415f4e6"] = "Se hai voglia di imparare, posso insegnarti a usare il martello da fabbro."
S["4423bf4a"] = "Buona fortuna là fuori, $N."
S["442c5a4e"] = "Capisco. Sembra estremamente pericoloso, ma a quanto pare la situazione richiede di correre qualche rischio.$B$BMolto bene, l'High Order darà il suo aiuto. Ti prego, fa' sapere a Valennia che in questa battaglia può contare su di noi."
S["442c9f24"] = "La Scholomance si trova nelle cripte sotto la rocca di Caer Darrow. Un tempo la rocca apparteneva alla nobile famiglia Barov, ma dopo la Second War è caduta in rovina. Quando il mago Kel'Thuzad reclutava seguaci per il suo Cult of the Damned, prometteva spesso l'immortalità a chi avrebbe servito il suo Re dei Lich. I Barov hanno ceduto alla sua influenza e gli hanno donato la rocca, ma i cultisti hanno ucciso la famiglia e hanno fatto delle cripte una scuola di negromanzia. Kel'Thuzad non abita più lì, ma cultisti e insegnanti ci sono ancora."
S["442f2a64"] = "Ora i segreti nascosti nei Piloni dell'Un'Goro Crater sono tuoi. Va' ai Piloni quando vuoi: potrai attingere al loro potere e procurarti risorse utili."
S["44320050"] = "NO!!! Mette il tannino nel cesto, o si prende di nuovo la mazza!"
S["4435ff9e"] = "Tu, soldato, torna subito a fare rapporto a Kargath!"
S["4453889a"] = "Finalmente... la morte! Maledetto Hakkar! Maledetto!"
S["4459a247"] = "Dovrei assumere qualcuno che mi aiuti; stare seduta qui tutto il giorno a vendere roba per la pesca non mi piace. Preferirei di gran lunga andare a pescare, e la roba venderla dopo."
S["44617ee6"] = "Dai segreti del potere del Colossus potrebbero nascere innovazioni scientifiche di ogni tipo!"
S["44692613"] = "Quegli umani hanno avuto quello che meritavano.$B$B<Vrang sputa per terra.>"
S["446b6a17"] = "Le tue attuali capacità superano le mie competenze didattiche. Per approfondire, dovresti rivolgerti a Trixie Quickswitch, Gnomo come me, a Ironforge!"
S["446d4a67"] = "Da questa fonte raccoglierò le acque sacre a cui unirò il sangue dei druidi caduti."
S["446dbd7b"] = "Per le stelle! Qualcuno ha evocato uno spirito!"
S["44790914"] = "Sporche bestie! Eccole che arrivano!"
S["44796338"] = "Forse faresti meglio a parlare dentro questi dispositivi amplificatori di suono attaccati ai miei PUGNI DELLA FURIA."
S["447a6f02"] = "Sono proprio quello che devi distruggere per liberare il reggimento! Te l'avevo detto: Kirith aveva un piano.$B$BOgni servitore ha un punto debole. Infierisci sui loro corpi vicino alle pietre, finché non staranno per disgregarsi: è allora, e solo allora, che puoi attaccare le pietre del vincolo. Però sbrigati a distruggerle, perché quando gli schiavi si saranno ripresi torneranno immuni a qualsiasi danno."
S["44823533"] = "Forza, miserabili sacchi d'ossa. Vediamo cosa sapete fare. Colpite l'avversario e non fermatevi finché non lo dico io."
S["4492f78f"] = "Blu più rosso... prevedo..."
S["4499046b"] = "I coboldi stanno riconquistando la Coldtooth Mine!"
S["449ca118"] = "Vieni, giovane, siediti con me."
S["44ab2db9"] = "Vuoi imparare a lavorare con l'incudine e il martello, eh? Te lo può insegnare Karn Stonehoof, che ha allestito una fucina vicino allo stagno, sull'altura inferiore."
S["44ab7212"] = "Non un pesce qualsiasi, mortale. Questo pesce era un pesciolino. Un pesciolino molto speciale."
S["44b31936"] = "Allunga qualche moneta al capo e vedi cosa ci guadagni. Il mio lavoro lo adoro. Però, se trovassi il modo di far trasferire in questo porto quella piccola peperina di Snurk.... beh, non potrei immaginare niente di meglio. Ma scommetto che non sei qui per sentire come lavoro. Cerchi lo Zeppelin per Undercity, dico bene? Beh, ottimo, perché attracca proprio qui dietro di me. Ah, e senti, se vedi Snurk, metti una buona parola per me, eh?"
S["44b696af"] = "Ascoltatemi, abitanti del Cratere! Vengo a purgare col fuoco questa terra dalle sue impurità!"
S["44bf1fd5"] = "Qualcosa affligge questa torre. Mi sono $Gammalato:ammalata; e anche gli altri dipendenti della Venture Co. che lavorano vicino alla torre o al suo interno si sono ammalati. Proprio la settimana scorsa, due dei nostri uomini di pattuglia sono morti, solo per tornare subito in vita come automi senza cervello! La forza vitale sta abbandonando il mio corpo. Sento che sto perdendo il controllo. Impulsi che prendono il sopravvento... Impulsi malvagi... Non ancora... Ascolta... Ricopro una posizione di potere. Questa posizione mi dà accesso ad alcune informazioni riservate."
S["44d3a141"] = "Spero che tu abbia una buona ragione per interrompermi: ero nel bel mezzo di un lavoro importante."
S["44ef17ee"] = "Arrendetevi e vi si lascia vivere, pagani! Mettete giù l'armi e marciate!"
S["44f1540f"] = "Mica fanno niente, solo un po' di caccia e di raccolta. Che male c'è??"
S["44f4fbe7"] = "Salve, $C. Sono brutti tempi, $Gamico mio:amica mia;, perché la nostra città è sotto assedio! Dallo Stonewatch Keep attaccano i Blackrock Orcs, sulla Tower of Ilgalar incombono gli Shadowhide e il Branco Gnoll di Redridge sta raccogliendo le forze. Spero che tu non sia qui in vacanza..."
S["44f5ecd8"] = "Un orco — un vero orc warrior — desidera una cosa sola: Morire nella gloria della battaglia contro un nemico odiato."
S["44fa9471"] = "Se solo fossi un metro e mezzo più alto, farei vedere io a questi demoni blasfemi! Aiuto!"
S["44ff1fe8"] = "Ascoltatemi! Vi porto notizie da oltre i nostri confini!"
S["450067d1"] = "Questo è il mio dialogo di prova."
S["4500a397"] = "Abbiamo superato il passo! Ora ci aspetta la palude..."
S["450a5b83"] = "In cosa può esserti utile $Gquesto insignificante servitore:questa insignificante serva;, $N? Cerchi addestramento, forse?"
S["450fd97d"] = "%s poi prende la mira verso le bottiglie..."
S["4510e444"] = "Fratello d'armi, è giunto il momento di riprenderci la notte dallo Scourge!"
S["45165a5a"] = "Panino? Cosa? Mi stai facendo un panino, pa'?"
S["4519be7d"] = "Ricorda che, per quanto questo luogo sia la nostra casa da millenni, qui saremo sempre in qualche modo degli estranei. Non siamo nel mondo terrestre che ha dato vita al nostro popolo, ma nel regno di Skywall, il piano elementale dell'aria.$B$BGiungemmo qui come ospiti di spiriti a cui, in epoche passate, scoprimmo di essere legati. Ora che noi shen'dorei siamo rimasti senza la loro presenza — e forse — senza la loro protezione, chissà come ci vedranno gli altri abitanti di questo piano."
S["452189c8"] = "Salve a te, $N, $C. Di solito sarei in giro di ronda a badare alla gente di Stormwind, ma molte delle guardie di Stormwind stanno combattendo in altre terre. E così eccomi qui, nominato vice e a offrire taglie, quando preferirei essere di pattuglia..."
S["452233ee"] = "%s rosicchia l'esca con voracità."
S["4535e41c"] = "Hydraxis, il nostro signore, parla molto bene di te. La mia acqua è la tua acqua, $Gamico:amica;."
S["453f20b7"] = "Gli eretici avrebbero dovuto processarmi per i miei crimini — il solo fatto di esistere, suppongo."
S["45458c04"] = "Wow, ci sono 3 gradi Kraklenheit. Continua a cercare."
S["45481f57"] = "Le armi migliori delle Barrens sono qui!"
S["45489da0"] = "Preparati, $N. Vado ad aprire lo squarcio..."
S["454a9feb"] = "Lo Snowfall Graveyard è sotto attacco! Se nessuno lo ferma, l'Alleanza lo conquisterà!"
S["454b072f"] = "Elder Ironband vive nella Blackchar Cave, nella Searing Gorge."
S["454cf078"] = "Nessuno passa e minaccia il re! Ungh, prendi questo!!"
S["4564805f"] = "E su quale campo di battaglia desideri andare?"
S["4564f0b9"] = "Kroshius vivo? Kroshius schiaccia!"
S["456e65ae"] = "%s tracanna la birra!"
S["456ede8f"] = "Mentre sali sulla cresta, guarda dove metti i piedi. Può essere piuttosto insidiosa."
S["4574cf07"] = "$N sta arrivando di corsa! È l'ora della vendetta!"
S["45778972"] = "COCCODÈ! I sensori rilevano un'anomalia spaziale — pericolo imminente! COCCODÈ!"
S["45810024"] = "Consideralo fatto, Jeztor. Dammi un segnalatore."
S["45823024"] = "Il Ravenholdt Manor non ti riconosce, $C."
S["458b4a12"] = "$C, nella guerra che ci attende ad Ahn'Qiraj persino i nostri guerrieri e i nostri esploratori più robusti avranno bisogno delle arti curative. E quando non potranno contare su guarigioni magiche, dovranno contare sul lavoro che facciamo qui.$B$BFinora ho raccolto una parte delle bende di runecloth che ci servono. Se sei $Gdisposto:disposta;, dovremmo riparlare di come puoi fare la tua parte."
S["459531e7"] = "Non sentiamo nulla. Le nostre anime restano qui, nel limbo, e non potremo andarcene finché i nostri resti non saranno ritrovati e i nostri spiriti non riposeranno in pace."
S["459e49a8"] = "Se hai intenzione di andare a Gnomeregan, vieni a fare due chiacchiere con me, $N!"
S["45a3164f"] = "La tua prossima scelta ti attende.$B$BTuo fratello vuole entrare nei ranghi del prestigioso ordine militare di cui fai già parte. Del suo impegno e della sua lealtà sei $Gsicuro:sicura;, ma dubiti del suo talento e della sua capacità di reggere i duri compiti dell'ordine. Non sei $Gcerto:certa; che saprà esserne all'altezza — e se fallisse metterebbe in pericolo te e gli altri — ma sei $Gcerto:certa; che basterebbe la tua parola per farlo entrare o per tenerlo fuori.$B$BFai la tua scelta."
S["45a39662"] = "Intrusi al Corno! Non lasciateli scappare!!"
S["45ad5b14"] = "Oggi non si mette bene. Il sole è già alto e forte di prima mattina, e sull'acqua non si muove niente."
S["45b6b679"] = "La tua volontà non è abbastanza forte per manipolare le forze che controlliamo, $C."
S["45be81ff"] = "$N, mai come ora la Stormpike Guard ha avuto bisogno del tuo aiuto nella battaglia contro il Frostwolf Clan nell'Alterac Valley. E non ci sono mai state occasioni così grandi di guadagnare onore e fama! Ti unirai alla battaglia?"
S["45c44972"] = "L'Emerald Circle si dedica a guarire la terra ferita di Felwood. Porta proprio il nome di ciò che l'ha corrotta, ma speriamo di riuscire, un giorno, a estirparne la corruzione."
S["45c942bb"] = "Bruciamo il fantoccio dell'Uomo di Vimini come simbolo della nostra lotta contro chi ci si oppone. Portiamo le ceneri dell'Uomo di Vimini come simbolo della nostra battaglia senza fine contro chi vorrebbe renderci schiavi."
S["45cbae17"] = "Non basta! Difensori, raccoglietevi al centro della città. Insieme resisteremo contro il mostro non morto!"
S["45e94e5f"] = "Vieni, $N. Il lago è subito dopo la curva."
S["45ea9fd0"] = "Ecco perché è così importante che restiamo."
S["45eaa151"] = "Salve, $Gviaggiatore:viaggiatrice;. Pochi vengono a trovarmi da queste parti.$B$BIl mio nome è Rivern, e addestro le Winterspring Frostsabers perché diventino cavalcature.$B$BDi tutte le tigri, questi felini sono i più selvaggi e i più difficili da domare: solo i più fidati e osannati possono tentare di cavalcarne una.$B$BNon venderò una cavalcatura simile a chiunque. No: devi lavorare per ottenerla, e farti accettare non solo da me, ma anche dalle tigri stesse."
S["45fc29ae"] = "Salve, giovane $Gladro:ladra;. Che cosa cerchi?"
S["4618a5be"] = "Distruggo questi strumenti del male! Per l'Orda!"
S["461ce393"] = "La tua prossima scelta ti attende.$B$BDa $Gsolo:sola; hai sconfitto una bestia terribile che devastava le campagne, e come trofeo ne hai preso l'orecchio. Poi vieni a sapere che il tuo signore aveva offerto una ricompensa per la sua morte, e che a sostenere di averla uccisa è un cavaliere gentile ma in miseria che, come sai, cerca di mantenere una famiglia con pochi mezzi. Del denaro tu non hai un vero bisogno, ma sai che il cavaliere sta mentendo per il proprio tornaconto.$B$BFai la tua scelta."
S["461d3d53"] = "Il totem è pronto, $N."
S["4623c384"] = "Fuoco di soppressione tattico, Vipore. Vacci pesante."
S["46296937"] = "Non tutti i Forsaken si muovono per volontà di Sylvanas, $N. Alcuni di noi li muove il vero potere — un potere che ci guadagniamo da soli."
S["462fb816"] = "Redpath! La tua vita finisce qui e ora!"
S["4638e4a9"] = "Una stessa causa ci unisce, $R. Un male antico minaccia di spegnere ogni vita su Kalimdor e di divorare il mondo con la sua depravazione... Il suo odio per tutto ciò che è nato dai grandi Plasmatori: gli eterni Titani.$B$BSiamo la prima e l'ultima linea di difesa contro gli eserciti di C'Thun. Se non insorgiamo per colpire il nemico, sarà di sicuro lui a distruggere noi.$B$BLo sforzo bellico ha bisogno di te!"
S["463ad092"] = "Il Principe ha tramato per imprigionare un demone di immenso potere dietro un grande campo di forza, che i piloni avrebbero tenuto attivo convogliandovi energie latenti.$B$BUna volta imprigionato, Immol'thar avrebbe fatto da fonte di energia per la popolazione di Eldre'Thalas."
S["4643e703"] = "Lord Supremo Fordring, state bene?"
S["46448353"] = "Mi vergogno, vecchio amico. Non so più cosa faccio. Non sei tu a osare disonorare gli eroi leggendari: sono io. Io e il resto di questi politici corrotti. Riempiono le nostre vite di promesse vuote e bugie infinite."
S["4649756d"] = "Mostra forza al tuo nemico e trionferemo!"
S["464aea9b"] = "Noi visto pallone lassù, a nord di rovine. Lui porta te in posti lontani."
S["4651d1f0"] = "Grazie dell'interessamento, $Gelfo:elfa;, ma adesso è una questione interna di Stormwind. Per il momento il tuo aiuto non ci serve più."
S["4657ea18"] = "Un racconto davvero avvincente. Ora capisco perché su quel libro c'era tanta polvere."
S["4659fced"] = "Raccogliere e conoscere le erbe è la specialità di Firodren Mooncaller. Lo trovi nei Temple Gardens, nella zona sud-occidentale di Darnassus."
S["46629ed8"] = "Se aspetti a venire da me, potrebbe non restare più niente!"
S["4662d9f7"] = "Una parte dei copper bars che ci serviranno l'abbiamo già, e lo stesso vale per il tin bar. Per la causa è stata fusa anche una parte dei mithril bars necessari."
S["4666e4f3"] = "Se sei $Gun:una; $Gvero:vera; $Geroe:eroina; dell'Orda, voglio vederti combattere contro un drago! Sì!"
S["46698852"] = "Non fraintendermi, preferirei non passare giorno dopo giorno in un tunnel pieno di silithid, ma se restare nascosta qui a osservare come si muovono queste creature ci aiuterà a vincere la guerra, lo farò per tutto il tempo che serve."
S["46743ee2"] = "$GAttento:Attenta; a dove metti i piedi, $C, che ho già pronto per te un incantesimo di polymorph..."
S["46772e3f"] = "Ahimè... Mi dispiace, ma ora non posso predirti la sorte: te l'ho letta da poco.$B$BTorna da me qualche ora dopo la prima lettura. Le forze del Fato si saranno ricalibrate a dovere e potrò vedere nel tuo futuro."
S["468696fe"] = "Salve, $N. $GBenvenuto:Benvenuta; a Refuge Pointe."
S["468ce8df"] = "L'Iceblood Graveyard è sotto attacco! Se nessuno lo ferma, l'Orda lo conquisterà!"
S["469665dc"] = "Ho quasi abbastanza provviste per passare alle unità veterane."
S["469c5a90"] = "Coprimi, soldato! Devo tornare alla nostra base e preparare la flotta per un assalto aereo!"
S["46ac6d73"] = "Presto! $N attacca!"
S["46b07e24"] = "I cannoni devono essere finiti presto."
S["46b32e13"] = "La nostra Alchimista è Carolai Anise. La trovi in una casa all'estremità nord-ovest di Brill."
S["46b7fd44"] = "Il tempo è stato crudele con te e con me, amore mio, ma sta' certo: sono io, e finalmente siamo di nuovo insieme."
S["46bc898e"] = "Ehm, salve! Se sei qui a riscuotere tariffe e/o per una citazione in tribunale, mi avrai scambiato per qualcun altro. Mi dispiace tantissimo!"
S["46c3aea9"] = "Ma... è molto gentile da parte tua. Immagino che tu stia dedicando del tempo alla Settimana dei Bambini, vero, $C? Beh, sei da lodare. È fondamentale ricordarsi dei meno fortunati, soprattutto dei bambini.$B$BSarò felice di firmarti un autografo. Ecco a te."
S["46c9bc38"] = "Una saggezza simile è avvolta in un mistero che si trova soltanto nella grande Thunder Bluff. Esci da Bloodhoof Village e segui il sentiero verso nord, finché non arrivi a un ascensore ai piedi delle alture. Sali fino in cima e chiedi altro aiuto a uno dei Bluffwatchers."
S["46ecb648"] = "Nasconditi nell'ombra. Abbiamo affari di cui discutere, quando avrò finito di mostrare a queste bestie perché mi chiamano la Mano del Caos."
S["46ed03fc"] = "Sospettiamo che i Barov, pur di conservare la loro fortuna e il dominio sulla terra — ben oltre la durata della loro vita — abbiano stretto un patto con un potente mago umano, un certo Kel'Thuzad.$B$B<Eva rabbrividisce.>$B$BDa quel patto è nata la scuola di negromanzia: il luogo che ha dato vita al Cult of the Damned e che ne sarebbe diventato la capitale.$B$BSettimana dopo settimana, la casa Barov è andata sempre più in rovina...$B$BEsseri oscuri hanno cominciato a insediarsi nelle varie ali. Tenerla in ordine è diventato impossibile... e disgustoso."
S["46ed096f"] = "Alla fine è intervenuto Grand Foreman Puzik Gallywix, che ha portato le scorte di veleno nella sua torre, qui alla Sludge Fen, per studiare la natura instabile delle tossine. Alla fine si è deciso di condividere il segreto del veleno con la Defias Brotherhood in cambio di una grossa fornitura di un veleno stabile e utilizzabile.$B$BKlaven Mortwake della Defias Brotherhood ha avuto il compito di modificare le proprietà chimiche della mistura di Zanzil."
S["46ef74a1"] = "Bethekk, la tua sacerdotessa invoca la tua forza!"
S["46f269de"] = "Ah, essere di nuovo giovani e scoprire le pozioni per la prima volta. Grazie di avermi rinfrescato la memoria, $N. Ora va' da Milla Fairancora, laggiù, a condividere con lei questo entusiasmo giovanile."
S["46f9a184"] = "Buona gente di Goldshire, venite ad approfittare dei miei incredibili prezzi su merci rare. Non tornerò per un bel po'!"
S["4709a09e"] = "Arrr, Ciurma Mia! C'ho un po' di Tesoro d'avanzo che regalo alla Gurubashi Arena! Per pigliarvelo non avete che da aprire lo scrigno che vi lascio sul terreno dell'arena!"
S["4709b1d9"] = "I miei occhi non m'ingannano mai, $R. Vedo in te un grande potere: forse abbastanza da far avanzare la nostra causa. Trovami in cima alla torre."
S["47168ad8"] = "Il Generale dei Frostwolf è morto!"
S["471c9491"] = "%s si gira verso il bersaglio di carta..."
S["47217105"] = "Elder Primestone ha trascorso molti anni nella Crystal Vale, in Silithus."
S["47226631"] = "Non una parola...."
S["472579ad"] = "Grazie, Vrang."
S["472cbc39"] = "Se desideri fondare una compagnia, devi rivolgerti alla maestra della gilda, Lysheana. La troverai nella Craftsmen's Terrace, nella parte nord-est di Darnassus."
S["4732c802"] = "<Dal portamento si vede che il cavallo ha un'indole calma ed equilibrata.>"
S["4739c7eb"] = "E dovrei condividere i miei segreti con $Gun:una; principiante? Prova a parlare prima con Victor Ward."
S["473b8c09"] = "Resta un solo dovere..."
S["473c7b7f"] = "I silvagufi sono magici per natura: questo potere fu donato loro dalla dea."
S["47433f75"] = "%s ringhia verso di te, poi si prende il tempo di annusarti."
S["4743a6dc"] = "Fammi prendere un focus magico da dentro casa e poi cominciamo!"
S["47442398"] = "Noi ha gancio per scuoiare, preso da Killian Hagey. Lui insegna noi come scuoiare prede. Tu hai bella pelle. Tu trova lui su anello interno di Rogues' Quarter."
S["4746604c"] = "Cra cra."
S["474e67fa"] = "Le bandiere ora sono state piazzate nelle loro basi."
S["4753d802"] = "Le unità veterane stanno entrando in battaglia!"
S["4758d88e"] = "Perché mi evocano adesso... mi sembra troppo presto."
S["475da1ff"] = "Ho qualcosa per te, $N. Ha l'aria di essere importante."
S["475e90c6"] = "%s versa l'acqua corrotta sul gatto."
S["4767c8ec"] = "Abbandonati alla Luce, $N. Oggi come posso aiutarti a servire?"
S["4767f9a4"] = "Dana lo thor? Ver Goibon mod gol a algos? Goibon valesh a nevren se nagan borne wos ash ko bor far thor algos. Goibon lo odes waldirskilde."
S["476b57fb"] = "Krathok, un tempo ero $Gun forgiatore:una forgiatrice; d'armi e ora vorrei invece imparare le vie del forgiatore di corazze. Mi addestrerai?"
S["476c435d"] = "Quei goblin dovrebbero vergognarsi di sé stessi. Bah!"
S["476cdf94"] = "Con sfrontatezza siete venuti a strappare i segreti della Living Flame! Vi pentirete presto della vostra impresa sconsiderata."
S["4779367e"] = "Pattuglierò la zona ancora per un po' per assicurarmi che sia davvero sicura."
S["4789f6a6"] = "|cffffff00La Torre del Muro Est è stata conquistata dall'Alleanza!|r"
S["478aa5b3"] = "Se credi di avere la forza di battere il buon metallo e ricavarne armi e armature per l'Orda, cerca Dwukk vicino alla forgia ardente, nell'angolo nord-ovest di Razor Hill."
S["4790a420"] = "Non potevo far altro che fingermi morto, mentre i cadaveri dello Scourge mi si ammucchiavano addosso. Intorno solo buio, e sopra di me i rumori soffocati della battaglia. Il cozzare del ferro, il digrignare, lo stridere... suoni raccapriccianti, terribili. Poi è sceso il silenzio. Mi ha chiamato! \"Fairbanks! Fairbanks, dove sei? Parlami, Fairbanks!\" E poi è arrivato il suono dell'incredulità. Il morso del tradimento, $R..."
S["47aa2de2"] = "Tutti noi, lavorando insieme, abbiamo compiuto una grande impresa. Ora ce ne attende una ancora più grande. Aspettiamo solo che l'Orda completi la sua raccolta, e poi affronteremo tutti insieme i Silithid e i loro padroni."
S["47afbf29"] = "Quello che ho fatto... cose così orribili...$B$B<Tarsis si mette a singhiozzare.>"
S["47bd02f2"] = "Kirin Tor! Giù le armi! Ci servirà tutto l'aiuto possibile."
S["47bd9167"] = "Sei $Gvenuto:venuta; a imparare, eh? Be', può darsi che abbia proprio del lavoro per te, $Gpivello:pivella;."
S["47be55d5"] = "Oh, $Gun sacerdote:una sacerdotessa;, eh? Be', se ti serve un po' d'addestramento, il buon vecchio Maxan lo trovi di sicuro alla Thunderbrew Distillery, a farsi un bicchiere."
S["47cf90ae"] = "Vi prego... vi prego... signorina Marefiero. Non volevo..."
S["47d9490c"] = "Mi piace tanto starmene seduta qui fuori ad ascoltare il rumore del Great Sea. Oh, come? Sì, c'è una nave che ti porterà a Menethil Harbor. Ogni tanto attracca qui."
S["47dae1f3"] = "C'è un'aria gelida."
S["47dd8886"] = "<Gli occhi di Tarsis si illuminano.>$B$BL'ho tenuto, una volta... L'ho tenuto a dispetto degli avvertimenti del Kirin Tor. L'ho tenuto, mortale... Un potere senza fine. Il potere di fare quello che volevo, come lo volevo. E con la stessa rapidità mi è stato tolto. Ma ne avevo avuto un assaggio... e quell'assaggio è bastato."
S["47e08929"] = "Grazie! Grazie, $Gsacerdote:sacerdotessa;. Ora posso affrontare quei wendigo con la Luce dalla mia parte!"
S["47e65a8e"] = "Finalmente arrivano i soccorsi..."
S["47e67147"] = "Abbiamo molte provviste in eccesso, ma ce ne servono ancora prima di poter mandare un assalto nel Field of Strife."
S["47e98e5c"] = "Allora, in quale di questi l'ho messo..."
S["47eeed8c"] = "Saluti, Astarii. Ho bisogno di addestramento."
S["47fbe17c"] = "Devi uscire dal bar!"
S["47fc4595"] = "Non è stata colpa mia, Master Mazen!"
S["47fdccbb"] = "%s punzecchia il piccolo squirrel peloso con evidente delusione."
S["48040204"] = "Fate largo!"
S["480c8e6c"] = "Elder Skygleam sta vicino al Ravencrest Monument, in Azshara."
S["480f2275"] = "Non ho molto tempo per sedermi a fare chiacchiere inutili con te. Se vuoi uno dei miei destrieri, cerca Velma, laggiù: ti insegnerà a cavalcare uno skeletal steed.$B$BNon vorrei che, per ignoranza, facessi del male a uno dei miei splendidi cavalli."
S["481035be"] = "Le Stockades sono un complesso carcerario di massima sicurezza, nascosto sotto il quartiere dei canali della città di Stormwind. Nelle Stockades, dirette da Warden Thelwater, sono rinchiusi piccoli truffatori, ribelli politici, assassini e una ventina dei criminali più pericolosi del regno. Poco tempo fa i prigionieri hanno scatenato una rivolta che ha gettato nel pandemonio le Stockades — le guardie sono state cacciate e i detenuti girano liberi."
S["4811a7a1"] = "Sul cartellino di questo regalo c'è scritto: \"Dai 40 anni in su.\""
S["48180864"] = "|cffffff00La Northpass Tower è stata presa dall'Orda!|r"
S["4818a99b"] = "È un mango, questo? Stupendo!"
S["481ab0f8"] = "$GPronto:Pronta; per l'addestramento? Allora cerca di starmi dietro, $N: abbiamo molta strada da fare."
S["482f34ae"] = "Krumn è il toro che cerchi. Lo trovi alle Thunder Bluff Civic Information, sul ripiano più basso."
S["4837d073"] = "Al Maniero non si parla d'altro che del tuo arrivo, Signora $N. Siamo tutti onorati e lusingati dalla tua presenza."
S["4844fc57"] = "Dunque mi hai trovato. Suppongo che tu sia venut$Go:a; a imparare la soppressione e il controllo.$B$BTi insegnerò molto di più... imparerai anche il sacrificio.$B$B<Daio sogghigna.>"
S["4846e424"] = "Delle tradizioni degli elfi della notte so poco, ma si dice che tanto tempo fa — quando il loro popolo considerava ancora sacra l'arte degli incantesimi arcani — Azshara fosse la più grande fra loro. Era una donna bellissima, e la fecero regina. Purtroppo, un giorno, fu proprio la sua dipendenza dall'arcano a scatenare gli eventi più devastanti della storia di questo mondo."
S["484917c2"] = "Che meraviglia trovare un'altra persona in questa regione sperduta del mondo. Vieni, cammina con me, e che i nostri corpi si scaldino a vicenda."
S["48498012"] = "Hai una certa abilità, è vero, ma ogni momento che passo a istruirti è un momento in più che i non morti passeranno nel tormento. Dimostrami che vali il mio tempo."
S["485412b2"] = "La famiglia Carevin combatte per vincere sotto la Luce, e il mio dovere sotto la Luce è dare la vita nella loro battaglia contro i non morti. Master Carevin mi ha affidato il compito di sterminare i vili worgen a Duskwood. Mi aiuteresti?"
S["48579e05"] = "Siamo spacciati!"
S["485a9ae1"] = "SMOTTS! EHI, SMOTTS!! VIENI FUORI A GIOCARE!"
S["485efb05"] = "Le mie macchine sono il futuro! Vi distruggeranno tutti!"
S["485f4eb5"] = "Il ponte è instabile e continua a interrompersi. Aspetta qui con me finché non ritorna."
S["48638e4a"] = "Reginald, sai che non posso lasciarti passare."
S["486d7cb3"] = "Ah, fammi pensare. Sì, ormai saranno quasi un centinaio di volte, ci scommetterei!"
S["4870dfdd"] = "Se cerchi armature di piastre o di maglia, o scudi, ho i migliori di tutta Undercity. Quasi tutti questi pezzi sono fatti e riparati qui sul posto, anche se qualcuno è di recupero.$B$BDai pure un'occhiata."
S["4876ce92"] = "Renditi utile, dammi una mano qui!"
S["487fbe79"] = "È Brandur Ironhammer che fa per te. Lo trovi nell'Hall of Mysteries, a nord dei cancelli di Ironforge."
S["488ce977"] = "Alvarion? Oh, è ancora sulle colline con i Peacekeepers, a fare piazza pulita del resto dei tuoi tirapiedi. Sono sicura che arriveranno da un momento all'altro, e saranno ben felici di vederti."
S["488d614d"] = "Ora dobbiamo solo liberare Tobias e poi possiamo andarcene. Da questa parte!"
S["4895ef17"] = "Chi osa rubare la mia preziosa cavalcatura? Pagherai per la tua insolenza, mortale!"
S["4898a757"] = "Sei $Garrivato:arrivata; giusto in tempo! Prima abbiamo avuto qualche guaio, poi qualche problema, e poi ci sono capitati pure diversi incidenti!$B$BCaitlin sarà preoccupatissima.$B$BLa squadra di scavo è a pezzi, ma con il tuo aiuto adesso abbiamo una possibilità di uscirne vivi!"
S["489df8c1"] = "La morte è solo una porta verso la rinascita. La covata risorgerà."
S["48a5fc74"] = "FIAMME! MORTE! DISTRUZIONE! Tremate, mortali, davanti all'ira di Sire... NO, DEVO combatterlo! Alexstrasza aiutami, DEVO combatterlo!"
S["48abfd92"] = "Vai nella Valley of Honor e cerca Xon'cha, vicino alle stalle."
S["48b414d7"] = "%s chiama la sua cavalcatura."
S["48b9164f"] = "In te vedo del potenziale, $N. Adesso prendi un martello e un po' di quei rottami, che di pratica te ne serve un sacco."
S["48baf055"] = "Chi sei? Che cosa vuoi da me?"
S["48c15de6"] = "Cos'è successo, Madre Terra? Perché l'incantesimo è fallito?"
S["48c190a2"] = "%s fugge per salvarsi la vita!"
S["48c5c77d"] = "Siamo sotto attacco!"
S["48ca9001"] = "Arrivano altre bestie!"
S["48da4ac7"] = "Ah sì, certo, basta che andiamo nell'arena subito dopo!"
S["48e7c4da"] = "Il Magistrato è caduto! Fuggite, fratelli miei."
S["48f14c8e"] = "Hm... è un bene che tu me l'abbia portato, Съедобная."
S["48f86cd5"] = "Volano sulle ali più oscure. Preparati a incontrare la tua fine!"
S["4901afe5"] = "Ehi, cosa ti serve?"
S["491439dc"] = "Quando mi hanno offerto il titolo di Magistrato di Southshore, ero felicissimo di essermi guadagnato un incarico del genere così presto nella carriera.$B$BMa ora che sono qui, mi chiedo se non avrei fatto meglio a smistare scartoffie a Stormwind."
S["492343fd"] = "Attenzione! $GUn:Una; $N ci è addosso!"
S["4923764d"] = "Venite! Venite incontro alla morte, se ne avete il coraggio!"
S["4927a294"] = "$N reclama la fattoria! Se nessuno si oppone, l'Alleanza ne prenderà il controllo fra 1 minuto!"
S["49286bb0"] = "Ahimè, $C, non sei $Gconsiderato:considerata; $Gun vero amico:una vera amica; di Darnassus e degli elfi della notte di Teldrassil. Solo quando ti sarai $Gdimostrato:dimostrata; amichevole verso di noi con i fatti — non con semplici parole — metterò a tua disposizione la mia scelta di cavalcature, perché tu possa esaminarla."
S["492883be"] = "Questa raccolta di pergamene contiene varie informazioni logistiche e strategiche, oltre a corrispondenza cifrata."
S["492d3412"] = "Ecco che arrivano le bestie!"
S["493093d7"] = "Tower Point è stata distrutta dall'Alleanza!"
S["4936e073"] = "Fate la guardia — gli intrusi sono vicini."
S["4938fd5f"] = "Davvero un'altra bella giornata."
S["493ba11f"] = "Ogni giorno che passa diventa più grasso e più corrotto. Si sente la puzza che gli esce dal corpo. È sporco, e non solo nel senso che avrebbe bisogno di una lavata.$B$BMa basta con le chiacchiere di Hulfdan. Da dove vieni, $C, e come posso aiutarti?"
S["4943fecb"] = "Ti andrebbe un bel gelato super gelato?"
S["494781da"] = "Non allarmarti, $R. Ho lasciato questo mondo tanto tempo fa, ma non voglio fare del male alla tua gente: ai miei tempi ho visto troppe morti. Ora desidero soltanto la pace. Forse puoi dare una mano alla mia causa."
S["49495e2e"] = "Ti... spezzo!!"
S["494a9af6"] = "Eh? Hai affari da fare con Nimboya?"
S["494e030a"] = "%s attacca un nuovo bersaglio!"
S["495391a2"] = "I water elementals sono in guerra con quelli del fuoco, e questo vuol dire, più o meno, che sono in guerra con noi. Hydraxis, uno dei loro capi, sta radunando agenti per la sua causa..."
S["495c9c70"] = "I capitani dell'Orda e dell'Alleanza sono scesi in campo. Il nostro Captain Galvangar guida i Frostwolf dall'Iceblood Garrison, e la sua rivale, Captain Balinda Stonehearth, si nasconde nel suo Stonehearth Outpost.$B$BLa battaglia è cominciata!"
S["49602ffb"] = "Fatti sotto!"
S["49623d93"] = "Argh! Che cos'era? Non dovrebbe funzionare così!"
S["49694338"] = "Torna da me con un lavoro così patetico e ti rimando a casa in una piccola scatola di ferro che ho temprato nell'urina di capra. Adesso va' da quell'idiota di Ug'thok, che fa più al caso tuo."
S["497404e0"] = "Con il culto che spadroneggia impunito su quasi tutta l'isola, Lorthuna penserà di certo che siamo in difficoltà. Possiamo ritorcerle contro la sua eccessiva sicurezza."
S["497dddf8"] = "Ero $Gun giovane elfo:una giovane elfa; della notte, a Darkshore, quando la mia strada ha incrociato quella di un gruppo di individui poco raccomandabili, conosciuti come il Twilight's Hammer. Alcuni di loro mi hanno offerto la loro amicizia e, con mia vergogna, ho finito per rinnegare la fede in Elune e abbracciare il veleno del Twilight's Hammer.$B$BDal torpore in cui ero $Gcaduto:caduta; come seguace degli antichi dèi mi sono $Grisvegliato:risvegliata; solo quando Elune mi ha mandato una visione.$B$BPer penitenza ho cominciato a comporre la mia preghiera a Elune."
S["4980186b"] = "Panini, brioche e pane, appena sfornati!"
S["4981226b"] = "Ti strapperò le budella!"
S["4983bedd"] = "Che Cenarius vegli su di te, $Gfratello:sorella;.$B$BSono Tajarri, una protettrice giurata di questo santuario. È un onore per me servire Keeper Remulos come guardiana di questa terra sacra."
S["498df348"] = "Se cerchi una combriccola cupa e tenebrosa, non c'è posto migliore della parte buia di Ironforge, che non a caso si chiama The Forlorn Cavern. Thistleheart è di sicuro lì, e probabilmente sta evocando qualche creatura immonda che obbedisca ai suoi ordini."
S["49962f61"] = "Io rappresento la forza che ti sostiene come $Ggiovane druido:giovane druida;. Sono la forza del corpo e la forza del cuore. Hai già imparato a conoscerla durante il tuo addestramento, e la richiami quando assumi l'aspetto dell'orso.$B$BContinua a mantenere l'equilibrio in ogni cosa, giovane, e mantieni il tuo sguardo chiaro e sincero. Quando avrai bisogno di me... io ci sarò per te."
S["49971ef3"] = "Le professioni si dividono in due categorie principali: primarie e secondarie.$B$BDi professioni primarie puoi averne al massimo due alla volta. Puoi abbandonarne una in qualsiasi momento; però perderai tutte le conoscenze che hai accumulato. Se poi decidi di tornarci, dovrai ripartire dalle basi e cercare di nuovo le ricette che avevi già imparato, per riprenderci la mano.$B$BPer le professioni secondarie questo limite non c'è. Servono più che altro a provvedere da $Gsolo:sola; ai bisogni di base per sopravvivere. Puoi impararne quante ne vuoi, anche tutte, ma le occasioni di guadagnarci potrebbero essere meno."
S["49a1db2b"] = "Oooh, una Locanda, eh? Be', non c'è niente di meglio della Thunderbrew Distillery. Riposati, se proprio devi, ma già che ci sei vedi di farti una birra o due."
S["49c0e223"] = "Per rispondere adeguatamente a questa domanda, occorre prima fornirti ulteriori informazioni di base sugli Earthen.$B$BElaborazione.$B$BPer comprendere le anomalie degli Earthen è importante, prima di tutto, stabilire cosa rappresentino gli Earthen secondo il loro intento progettuale. Gli Earthen rappresentano il tentativo dei Creatori di migliorare il paradigma di sopravvivenza della matrice standard dell'essere sotterraneo. Ciò è stato realizzato incorporando in tale matrice una resistente base costruttiva propria del mondo."
S["49c1230d"] = "Buona giornata a te."
S["49c1dbf6"] = "Parlami della Glowing Shard."
S["49c3efd4"] = "Hai trovato ciò di cui abbiamo bisogno?"
S["49c4f8f1"] = "Poi metterò la ruota... per proteggerti dal male."
S["49cd1e45"] = "C'è ancora molto lavoro da fare, $N! Continua ad abbattere i nostri nemici!"
S["49cda1fb"] = "$GBenvenuto:Benvenuta; alla Darkmoon Faire, $C!$B$BMi chiamo Kerri Hicks e ti stringerei la mano, ma temo che te la romperei, perché sono la donna più forte del mondo!"
S["49d0e839"] = "Soldati di Kalimdor! Eroi di Silithus! Uno di voi ha inferto un colpo feroce ai nostri nemici mortali! $N e i suoi alleati hanno liberato le Ruins of Ahn'Qiraj dal loro spietato capo! Ossirian the Unscarred, flagello di Silithus, è stato finalmente distrutto e i suoi eserciti completamente smantellati!"
S["49da2cce"] = "Ecco il tomo mistico che stavo cercando."
S["49df4163"] = "Salve, gentile signora. Siediti pure e mangia qualcosa, se hai fame. Se ti sembro presa dal ricamo, non preoccuparti — ti sto ascoltando..."
S["49e1b4c2"] = "Torna qui!"
S["49f2d310"] = "Perché mi chiamano \"La Spezzatrice\"?$B$BFidati, non vuoi saperlo."
S["49fe8de4"] = "Grurk aprire presto. Poi noi dividere tesoro."
S["49ff169a"] = "Così dovrebbe andare! Hic!"
S["4a0518bf"] = "Chiedetemi come bere gratis al Blue Recluse!"
S["4a06480b"] = "Già, hai proprio l'aria di chi è nato per comandare. Sei qui per fondare una gilda che combatta per l'Alleanza?"
S["4a081772"] = "Viene... da un po' più lontano. Ti spiegheremo strada facendo."
S["4a159e1f"] = "Sembra proprio una di quelle giornate."
S["4a18de04"] = "Lascia le tue battaglie o le tue commissioni, e dai un'occhiata alle mie incredibili merci! A Darkshire solo per poco tempo... sia lodata la Luce per questo."
S["4a1cd8ed"] = "Buona fortuna, $N. E non dimenticare... prendi quel copione prima di cercare Gazin."
S["4a2bf8d1"] = "Kibler è sotto indagine da parte della G.E.T.A."
S["4a303255"] = "Salute, sorella... Vorrei parlarti un momento, se posso.$B$BPer fondare la nostra patria, noi tauren abbiamo sopportato molte prove e tribolazioni, e ora la stoffa ci manca gravemente. Se hai dei materiali in più, ti chiedo di donarli. Aiutandoci, ti guadagneresti di certo la gratitudine dei tauren di tutto il mondo!"
S["4a30a70a"] = "Ahah! $N, sei $Gun compagno:una compagna; niente male!"
S["4a30fee0"] = "Salute a te, $Gfigliolo:figliola;. Sono Illaya Amberwind, l'Anziana Windshaper qui su Zephras Isle. Fa sempre piacere incontrare volti giovani e nuovi che scendono dal boschetto.$B$BNon lasciarti trattenere da questa vecchia sciamana: di avventure da affrontare ne avrai senz'altro molte. Se ti va, passa pure a trovarmi più tardi."
S["4a34d59c"] = "Libertà! Sì."
S["4a38c9b5"] = "Vattene, rozza feccia! L'Alleanza trionferà nell'Alterac Valley!"
S["4a3efbab"] = "Ok capo, quando tu pronto per tributo di tuoi scagnozzi, tu fa' sapere a me!"
S["4a428975"] = "Le carovane partono tipo due volte al giorno, ma che io sia dannato se lo Scourge non s'è messo d'impegno per impedire a Didier e ai suoi muli di portare i carichi al fronte. Mai vista una cosa più assurda. Se solo avessimo qualche avventuriero eroico che ci desse una mano a proteggere la merce..."
S["4a481840"] = "NON PUÒ ESSERE!!! Rend, occupati di questi insetti."
S["4a49cc2d"] = "La tua battaglia qui non è che il più piccolo granello di un'invasione che si estende al mondo intero, $Gmoccioso:mocciosa;! È ora che tu conosca i poteri che hai di fronte!"
S["4a4d85b4"] = "Con martello e incudine te la cavi, ma non basta. Va' a parlare con Dane Lindgren: ti darà le fondamenta per imparare quello che ho da insegnarti."
S["4a4e453d"] = "L'uomo dei pipistrelli lo trovi al piano di sopra del Trade Quarter."
S["4a4eb506"] = "OK Fengus, dove sei?! Vieni a chiamarmi amico degli gnoll, così io ti do martellata in testa!"
S["4a531f7c"] = "Puah! È terribile!"
S["4a53d274"] = "Siamo aperti!"
S["4a5616b9"] = "È tutto quello che sai fare?"
S["4a5bd29a"] = "La battaglia è vinta! Guardateli fuggire al sicuro nel loro prezioso tempio. Presto tutto sarà raso al suolo... I loro capi distrutti!"
S["4a5c27be"] = "Makaru lo trovi giorno e notte alla Red Canyon Mining, nella Valley of Honor, proprio accanto al lago."
S["4a5fad97"] = "È proprio una bella giornata per esser vivi, eh? Lavoro duro e buon cibo — potremmo fare di peggio in una giornata così bella."
S["4a6211ad"] = "Gli stregoni... non mi piace quella gente. Prendi quel Grimrizz, che ha messo su bottega fuori dalla Thunderbrew Distillery: per colpa sua, lì la birra probabilmente si sgaserà! Stregoni... bah!"
S["4a696887"] = "Devi imparare da qualcuno che ne sa più di me: va' a parlare con Josef Gregorian a Undercity. Allora, che ci fai ancora qui?"
S["4a6a6c49"] = "Non ho mai visto niente del genere. Nessuna concentrazione né perdita di coscienza mentre il soggetto è dominato. Cosa le hai fatto?"
S["4a6df21c"] = "%s prende di nuovo la mira verso le bottiglie..."
S["4a770aaa"] = "%s mugola obbedientemente."
S["4a7732c3"] = "La cassetta di sicurezza del SI:7 si apre cigolando. Si sente una voce forte e rimbombante. Riesci a distinguere le parole: 'Va'... cerca... ombre...'"
S["4a77e182"] = "Notte a tutti. Io resto $Gsveglio:sveglia; ancora un po'. Magari passa Darcy."
S["4a7b411f"] = "Noi è liberi! Grazie, piccoli gracili."
S["4a7ef7c9"] = "Si sentono ruggiti e ringhi orrendi provenire da quella vecchia capanna dell'eremita!"
S["4a7f10aa"] = "Se hai parlato con Rathiril e ti ha mandato da me, sarai senz'altro al corrente del pericolo in cui ci troviamo."
S["4a83f782"] = "%s annusa l'elisir e poi ci si butta con avidità!"
S["4a86c20f"] = "Magari le vie della Luce non le segui come un Cavaliere della Silver Hand, ma a noi puoi sempre chiedere aiuto."
S["4a8b6f81"] = "Ti sembro forse $Gun:una; $C? Adesso fila, prima che mi venga il bisogno di oliare la lama... nel tuo sangue."
S["4a8edca0"] = "%s divora tutti gli zombi nei dintorni!"
S["4ab49428"] = "Forza, Forsaken! Evviva noi!"
S["4abd3768"] = "Be', da così vicino è difficile mancare il colpo."
S["4ac3c19a"] = "Korrak è arrivato, deboli! Snowfall appartiene ai Winterax!"
S["4ac514a3"] = "Ah, eccoti. Mi avevano detto di aspettarmi aiuto, quindi ascolta bene. La situazione è questa: mi è stato affidato il compito di raccogliere una certa quantità di purple lotus in vista della guerra imminente ad Ahn'Qiraj. Finora ne abbiamo raccolto solo una parte.$B$BAndare sul campo a raccogliere i fiori toccherà a te e a quelli come te. Io servo qui, per assicurarmi che vengano conservati a dovere e per trovare modi nuovi e creativi di usarli contro i silithid e qualunque altra cosa ci aspetti laggiù."
S["4ac76913"] = "L'unico posto di Stormwind dove magia e spiriti si mescolano: venite al Blue Recluse!"
S["4ad5211e"] = "Una risposta interessante alla mia domanda... e sbagliata."
S["4ade54d6"] = "Ah, $C, sei $Garrivato:arrivata; proprio al momento giusto. Te ne sono grato."
S["4aeb3e81"] = "Ci sono ancora lezioni che devi imparare da altri prima che io possa condividere con te il mio sapere. Sii diligente e non perdere la speranza."
S["4af02e70"] = "Detonazione fra 5 secondi!!!!!"
S["4af8102a"] = "Posso insegnarti i segreti del Pilotaggio di Meccanostruzzi, basta che tu abbia l'oro per pagare la lezione!"
S["4af9a35e"] = "$GUno:Una; che impara in fretta, ecco cosa sei, e per giunta $Gun bravo fabbro:una brava fabbra;. Il tuo lavoro lo approverei a occhi chiusi, ma sento che hai ancora un po' da apprendere. Va' a parlare con Bengus Deepforge: è un maestro severo, ma anche uno dei migliori."
S["4b01feb3"] = "Cara ragazza, sei arrivata proprio al momento giusto per dare una mano alla Kargath Expeditionary Force."
S["4b023910"] = "Il tuo misero corpo, $N, lo faranno a brandelli i miei artigli."
S["4b02398c"] = "I miei artigli ridurranno a brandelli quel tuo corpo gracile, $R."
S["4b02ad6f"] = "Sei proprio $Glontanissimo:lontanissima; da casa, $R."
S["4b102182"] = "Sei $Gvenuto:venuta; a imparare, mon?"
S["4b117562"] = "La prossima volta Executor Arren si arrangerà da solo!"
S["4b12da1f"] = "Mi scuso, ma non sono in grado di elaborare il tuo riferimento cronologico in rapporto alla registrazione di questi dati.$B$BIl nano conserva gran parte della sintonia mentale dell'Earthen con la composizione rocciosa di Azeroth, ma la regressione a biomassa vivente resta la principale degenerazione della matrice: i nani si nutrono e procreano come le altre biomasse standard.$B$BI Creatori considerano il nano una variante accettabile, degna di una genesi a sé stante."
S["4b18db06"] = "Non vedi che qui sto lavorando?"
S["4b1938d6"] = "%s cerca di fuggire terrorizzato!"
S["4b1a20c3"] = "Non lo sa nessuno. Perché chi è caduto non è mai tornato. Quando le navi fendicielo facevano la spola tra Valanaar e New Eldranaar o Shen'dramar, a volte capitava che qualcuno finisse fuori bordo, per un incidente o per qualche altra disgrazia. E quando succedeva, la nave non rallentava neanche. Non serviva.$B$BPer quel che ne sappiamo, chi è caduto è ancora là fuori... e precipita senza fine, per sempre."
S["4b25b1e9"] = "Spiriti degli Highborne! Ora potete riposare! La maledizione del cristallo vi libera!"
S["4b261269"] = "Salve, salve! $GBenvenuto:Benvenuta; nella mia cucina, mia signora! Qui si preparano tutte le prelibatezze migliori della Scarlet Raven Tavern. Ah, senti che profumo meraviglioso!"
S["4b3877cf"] = "Il Dun Baldar North Bunker protegge l'ingresso orientale di Dun Baldar.$B$BNon è controllato da nessuna delle due parti."
S["4b3a71bc"] = "Grazie alla luce sei qui! A questo punto accetterei aiuto persino da un ogre a due teste.$B$BLa città è stata invasa dai troggs! I tentativi di sterminarli hanno provocato una contaminazione di massa. Ma c'è ancora speranza.$B$BI nostri scienziati, evacuati a Ironforge, stanno lavorando a una cura per la malattia da radiazioni. Nel frattempo, se riesci ad aiutarmi a fermare l'invasione dei troggs, forse la città potrà essere riconquistata."
S["4b3adbd7"] = "Mi chiedo, eroi, cosa farete quando riuscirò a distruggere questo frammento? Il mondo sarà ormai perduto?"
S["4b3ff746"] = "Affrontate la Might of Kalimdor!"
S["4b440455"] = "Il cibo: ecco un argomento in cui posso affondare le zanne! Mi dicono che teniamo sotto ghiaccio una scorta di lean wolf steaks, di spotted yellowtail e di baked salmon."
S["4b4720eb"] = "Che cos'è questo... sto svanendo..."
S["4b4af416"] = "Radnaal fornisce a Nadyia una buona scorta di pelle ricavata dagli animali che scuoia. Ti consiglio di parlare con lui se vuoi imparare la professione."
S["4b5a9922"] = "Ecco! Spalancata. Buona fortuna con ciò che si trova oltre. Devo tornare subito a fare rapporto al Kirin Tor!"
S["4b6972ba"] = "L'ingegneria è semplicissima, una volta capite le basi."
S["4b6b4635"] = "Non ho nulla di personale contro i membri dell'High Order come te, ma questo non mi obbliga a conversare con te. Va' in pace, $C, ma ti esorto vivamente a non immischiarti negli affari dei Windshaper durante le tue avventure su Zephras Isle.$B$BSe lo facessi, finiresti male. I Windshapers non perdonano facilmente chi offende ciò che riteniamo sacro."
S["4b771d7a"] = "Kor'ghan ti aspetta nella Cleft of Shadow, e ha forbici più affilate della spada di una guardia."
S["4b7abd3a"] = "Ottima domanda! Qui alla fiera abbiamo tante cose in vendita. Per cibo e bevande, passa allo stand di Stamp e Sylannia: la mia preferita è la Darkmoon Special Reserve.$B$BSe invece cerchi qualcosa di più esotico, Lhara potrebbe avere proprio quello che fa per te: è specializzata in rarità da ogni parte del mondo.$B$BE poi c'è Flik, che scorrazza qui intorno, da qualche parte. Se riesci ad acchiapparlo, vende palle da lanciare e rane da compagnia."
S["4b89ec63"] = "Sei un moscerino per i Selvalercia! Muori!"
S["4b8a7878"] = "Scheda di sicurezza bianca inserita correttamente...$B$BErogazione unità di livello di sicurezza beta.$B$B01010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 01100001 01111001 01101001 01101110 01100111 00100000 01100111 01100001 01101101 01100101"
S["4b927186"] = "Ok, ci siamo. Ci vorranno circa cinque minuti per spegnere questo coso con il rituale. Una volta cominciato, tenete lontani quei parassiti o sarà la fine per tutti noi!"
S["4b96d4bb"] = "È potere, imbecille.$B$B<Gli occhi di Mataus si incupiscono.>$B$BQuesti sciocchi mandano idioti come te a Naxxramas a recuperare l'armatura profanata: vogliono purificarla e riportarne i pezzi all'antico splendore.$B$B<Mataus sputa.>$B$BSolo a pensare a tanta stupidità mi sale la bile in gola.$B$BAnch'io cerco quell'armatura, ma nella sua forma più immonda e profanata."
S["4baedcd7"] = "C'è un cartello appena fuori dalla porta principale della città: ti indicherà la torre degli zeppelin. In cima alla torre parla con Zeppelin Master Frezza."
S["4bb319c6"] = "Tempi duri, eh, $N? Ti giri e c'è sempre qualcuno che ha bisogno d'aiuto, e io e mia moglie non facciamo eccezione."
S["4bb48f88"] = "<Lo strider ti scruta impaziente; sembra quasi saltellare per l'eccitazione.>"
S["4bb4d9fa"] = "Brzzzzt!$B$B$GBenvenuto:Benvenuta; nel Matrix Punchograph 3005 barra B, terminale con livello di sicurezza beta.$B$BPer accedere alle sue funzioni devi possedere una yellow punch card.$B$B01000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001"
S["4bb4ecf7"] = "Il totem è fatto, Кайдар."
S["4bba1eb7"] = "Tracciamento"
S["4bbde696"] = "Relara... sei sveglia?"
S["4bc16137"] = "Ecco, Relara. Prendi questo..."
S["4bc24745"] = "Enormi cristalli risonanti Qiraji sfondano la crosta earthen di Kalimdor. Creature colossali fatte di pietra d'ossidiana irrompono dalla terra appena squarciata."
S["4bc38c5e"] = "Ho un messaggio speciale per $N. E dice che devi morire!"
S["4bcc7d7e"] = "Buongiorno, $C. Cosa desideri?"
S["4bdbd3a8"] = "Altro pane, ragazzo!"
S["4be0a985"] = "La vita è una lotta, e non è sempre vero il detto che ciò che non ti uccide ti rende più forte. A volte le ferite agiscono lentamente, ed è per questo che abbiamo le bende. Pand Stonebinder of the Spirit Rise può insegnarti l'arte del First Aid."
S["4bfd5108"] = "Non ostacolare il nostro cammino, Plasmavento!"
S["4c09c2d8"] = "%s accetta le reliquie da $N."
S["4c0ab9c0"] = "Mmm... Dov'è il mio amo? Ah, eccolo."
S["4c12b812"] = "Tutti gente arriva..."
S["4c167e38"] = "Non avvicinarlo di più, mortale. Sento già da qui il male che scorre nel sigillo.$B$BDammi un momento per esaminare l'oggetto — e tienilo ben saldo."
S["4c1ea1e9"] = "Sayoc, il maestro d'armi orco, si trova nell'Orgrimmar's Valley of Honor. Insegna a usare archi, pugnali, armi da pugno, asce a una e a due mani e armi da lancio.$B$BHanashi, il maestro d'armi troll della Valley of Honor di Orgrimmar, può insegnarti a usare archi, asce a una e a due mani, bastoni e armi da lancio.$B$BNel War Quarter of the Undercity c'è invece Archibald, il maestro d'armi non morto, che può addestrarti all'uso di balestre, pugnali, spade a una e a due mani e armi ad asta."
S["4c215a56"] = "Saluti, amici, e benvenuti al più grande spettacolo di Azeroth!$B$BPrego, avvicinatevi e godetevi tutto quello che abbiamo da offrirvi. Salite sulle giostre e ammirate le attrazioni! Restate a bocca aperta davanti alle meraviglie che la Darkmoon Faire ha scoperto in questo mondo vasto e misterioso! Non abbiamo badato a spese per portarvi emozioni che faranno la gioia dei bambini di tutte le età!"
S["4c324a81"] = "Lavori/Oggetti smarriti/Ricercati:"
S["4c3a2142"] = "Sento campane nuziali nel tuo futuro."
S["4c50a033"] = "Eburi ash, Ibagî. Ala mush ri ash."
S["4c5c6b35"] = "Ah, il vero segno del cacciatore! Braccare la propria preda nell'interminabile gioco della vita. Rivolgiti a Drayl sull'Hunter Rise per le tue risposte."
S["4c5e3120"] = "Ecco come si fa, classe! Fareste meglio a stare attenti!"
S["4c645195"] = "Credo che Aldwin Laughlin sia ancora il Maestro di Gilda di Stormwind. La sua casa è sulla sinistra, appena passata la porta interna di Stormwind."
S["4c695f5d"] = "Statemi vicini..."
S["4c6d98e4"] = "Venite, eroi... Per volere di The Lich King, sarete distrutti."
S["4c6e0db0"] = "Non riesco a credere che a Stormwind i funzionari mandino all'estero il grosso del nostro esercito... proprio adesso che qui in patria siamo così sotto pressione!$B$BCon i ladri che arrivano da Westfall e gli gnolls che avanzano da est e da ovest, c'è da stupirsi che Stormwind stessa non sia sotto assedio."
S["4c859c42"] = "Il Pilone Settentrionale accetta cristalli gialli, rossi e verdi.$B$BIl focus è l'energia che si ottiene usando i cristalli gialli come fonte principale di potere. Gli effetti possibili sono due: uno infligge danni, l'altro li annulla.$B$BLa Crystal Charge richiede cristalli rossi e gialli e produce una grande esplosione che stordisce i nemici.$B$BLa Crystal Restore richiede cristalli gialli e verdi e ti dà un'aura curativa."
S["4c85fcd2"] = "Non abbiamo affatto bisogno di attirare altra attenzione su di noi, straniero. Torna da chi ti ha mandato a cercare il maestro scomparso e digli che non hai trovato nulla. Quando l'avrai fatto, e io lo saprò, torna e ti rivelerò i segreti del defunto."
S["4c91c365"] = "Mi serve un passaggio, Dungar! Devo consegnare delle provviste importanti!"
S["4c9f1a90"] = "Rin'ji è libero!"
S["4ca1b7f2"] = "Tanto tempo fa io e le mie sorelle driadi siamo entrate in queste grotte per liberare lo spirito tormentato di mio zio, Zaetar. Ma la corruzione, che si era già diffusa nelle caverne, ci ha presto sopraffatte, e siamo cadute anche noi.$B$BEravamo destinate a vagare per questi passaggi; le tossine ci avvelenavano la mente...$B$BOra il mio spirito può riposare, ma so di aver fallito nella mia missione. È un grande dolore, e devo sopportarlo..."
S["4ca77388"] = "Pescare è proprio facile. Basta prendere una canna con la lenza, magari metterci un po' d'esca, e buttarla in acqua. Vedrai che quei pesci cominciano ad abboccare."
S["4ca77900"] = "Cosa? Questo non Naxxramas! Noi non piace questo posto... distruggere!"
S["4ca92616"] = "Guarda un po' chi si vede. Cosa ti porto, $N?"
S["4cab6d63"] = "Nell'Alterac Valley infuriano le battaglie e l'equipaggiamento scarseggia."
S["4cc8038a"] = "Scatenate la furia e che sia fatta!"
S["4cca8cfd"] = "Ahhh, cerchi Dungar Longdrink. Ha alcuni dei grifoni più veloci di qua da Khaz Modan! Lo trovi in cima ai bastioni, nel Trade District."
S["4ccf07de"] = "Voi due siete di sicuro amanti sfortunati che si sono ritrovati. Nel vostro futuro c'è tanta felicità."
S["4ccfa9df"] = "A pensarci bene, quasi tutti quelli coinvolti sono morti. Capirò se non vorrai essere $Gcoinvolto:coinvolta; in tutto questo, $N."
S["4ccff525"] = "%s rigurgita una disgustosa Bile Slime!"
S["4cd6ba41"] = "Che la lama ti purifichi, feccia!"
S["4cd884eb"] = "Il tuo cammino è saldo, $N, perché la determinazione di Washte Pawne è con te."
S["4cde2e7d"] = "Lo Stonehearth Graveyard si trova a est dello Stonehearth Outpost nel Field of Strife.$B$BAl momento nessuna delle due fazioni lo controlla."
S["4ce43a78"] = "Allora, che ne pensi del mio nuovo giocattolo?"
S["4ce7776b"] = "Hai raggiunto nuove vette sulla strada della maestria. Vediamo se riusciamo a portarti ancora più in là..."
S["4ce9a4de"] = "Qui ci vorrà un mucchio d'oro. E non esce mica dalla mia tasca."
S["4cedfe44"] = "Assaggiamone solo un goccio..."
S["4cf3325d"] = "Questo sì che è un Urto di Guerra! Ottimo lavoro!"
S["4cf44a4d"] = "opzione mercante"
S["4cfac5f8"] = "Sono di nuovo fuori dall'edificio. Ora vado avanti di un altro punto di passaggio..."
S["4cfc00f1"] = "Possa io crogiolarmi nella tua ombra per sempre!"
S["4d0aedff"] = "Con le piante della foresta si possono creare cose sorprendenti, non trovi? Elune ci ha davvero benedetti con la sua generosità."
S["4d1b54bd"] = "Un tempo era una grande città degli elfi della notte, dove regnavano gli Highborne, che praticavano magie arcane grandi e potenti. Ora sono maledetti e infestano quelle terre, e la loro città in rovina è caduta preda dei naga Spitelash. Mi risulta che i naga frughino fra le rovine in cerca di potenti manufatti degli Highborne."
S["4d275be2"] = "Mi serve un altro Relic Bundle!"
S["4d39aae3"] = "Le maree della guerra sono tornate. Dal gelido nord, le necropoli di The Lich King hanno messo sotto assedio le nostre terre. Lui e il suo maledetto generale, Kel'Thuzad, inviano necropoli volanti a invadere il mondo intero."
S["4d3bde24"] = "Bende? Perché, conti di sopravvivere tanto da averne bisogno? Har! E va bene, $R, te lo dico. Delle bende di lana che servono, una parte l'abbiamo raccolta. E finora ci è arrivata anche parte delle mageweave bandages e delle bende di runecloth richieste."
S["4d44aeb1"] = "Saluti, $Gamico mio:amica mia;. Che l'Alba ti protegga in questi tempi difficili."
S["4d5f2c63"] = "È l'avidità che ti ha riportato da me.$B$B<Mathredis ride.>$B$BUn saggio Draenei una volta mi disse che essa — l'avidità — è l'unica qualità che tutte le razze di questo mondo hanno in comune. Non posso che essere d'accordo.$B$BHai raccolto i componenti elencati nel libram?"
S["4d6039c5"] = "Invasori in arrivo da sud!"
S["4d62d260"] = "Goaz non rilevato. Attenzione. Attenzione."
S["4d6796ce"] = "Captain Balinda Stonehearth guida le forze dell'Alleanza in prima linea. È di stanza nello Stonehearth Outpost, nella parte settentrionale del Field of Strife.$B$BAl momento Balinda si trova nello Stonehearth Outpost."
S["4d6a0f66"] = "Che lo spirito di Isha Awak ti dia forza, $N."
S["4d6ea94a"] = "L'Alleanza ha conquistato la Coldtooth Mine!"
S["4d6f3ee0"] = "È arrivato il tempo dell'anno nuovo e della luna splendente.$B$BÈ il nostro tempo... quello in cui gli antichi si risvegliano."
S["4d753b55"] = "Ti prego, continua."
S["4d7e823a"] = "Ok, ok! Basta combattere. Nessun altro deve farsi male."
S["4d84d893"] = "%s esamina attentamente la Pietra del Flagello."
S["4d84f3dd"] = "Siamo sopravvissuti!"
S["4d882f6a"] = "Le Silverwing Sentinels non le chiamerei certo avversari onorevoli. Ma se sei $Gdeciso:decisa; a massacrarle, $C, cerca Brakgul Deathbringer nell'Hall of the Brave."
S["4d88e557"] = "Gli assassini sono qui! Presto, prima che arrivino dal Magistrato!"
S["4d9666e9"] = "Gran parte del mio addestramento con le armi l'ho avuto da Ilyenia Moonfire, nella Terrazza dei Guerrieri. Se vuoi imparare a usare una nuova arma, faresti bene a cercarla."
S["4d988a97"] = "Sì, subito, mamma!"
S["4da7b9cd"] = "Oggi incontrerai i tuoi antenati!"
S["4db829ec"] = "EHI! EHI, TU! $R! Tirami fuori di qui!"
S["4dbef2c4"] = "Sei $Gsicuro:sicura; di essere $Gpronto:pronta;? Se un gruppo di tuoi alleati non ci aiuta, falliremo di certo."
S["4dc0d87d"] = "A vedere gli abiti che confeziona Me'Lynn, verrebbe da pensare che Elune in persona le abbia benedetto l'ago. Se il tuo non è altrettanto benedetto, faresti meglio a passare da lei e ascoltare i suoi insegnamenti. La trovi nella Craftsmen's Terrace, nella parte nord-orientale di Darnassus."
S["4dc274c3"] = "Chi va là?"
S["4dc9f7a9"] = "Il mio volo è pronto! Soldati, venite in mio aiuto!"
S["4dd3c20f"] = "%s erutta una disgustosa Bile Sludge!"
S["4ddd7f09"] = "L'High Order cerca una soluzione saggia e pragmatica alla crisi che stiamo vivendo."
S["4de222d1"] = "Captain Balinda Stonehearth è morta! Sconfiggete Vanndar e la battaglia sarà nostra!"
S["4de5d694"] = "Oh, stai $Gzitto:zitta;."
S["4de654b9"] = "Avete qualche minuto per svegliarvi, ma cominciamo presto."
S["4df18bcc"] = "Udite! Udite! *anf anf* State in guardia, cittadini di Southshore: degli assassini stanno arrivando nella nostra bella città!"
S["4dfc0a5d"] = "%s viene fatto a pezzi mentre è bandito da questo mondo."
S["4e011bad"] = "Ormai hanno la mente corrotta, $R. Sì, anche più di prima. Vivono solo per servire e proteggere Razelikh. I frammenti dell'amuleto che ognuno di loro custodisce sono la chiave per evocare il signore dei demoni. Quello che non capisci è che nessuno di loro si può ferire con mezzi normali."
S["4e042a8f"] = "Sarebbe già un'impresa uscire di qui senza una lama nella schiena o del veleno nelle vene."
S["4e06957d"] = "Non sei $Griuscito:riuscita; a proteggermi dalle scimmie!"
S["4e082cec"] = "Hai accettato la mia resa."
S["4e10c28b"] = "$GUn sarto:Una sarta;, eh? Molto bene. Cosa vorresti imparare, $Gsarto:sarta;?"
S["4e12afb0"] = "Sai, ho sempre voluto fare il Cercatore, ma per i numeri ero portato dalla nascita, e la Gilda ha deciso che ero più adatto a tenere i registri! A studiare, a studiare, ogni giorno della mia giovinezza..."
S["4e1b1776"] = "Salute, $C — sono $Gun Ufficiale:un'Ufficiale; degli Encomi e agisco per conto degli Gnomeregan Exiles. Il mio compito è aiutare gli avventurieri che hanno ricevuto degli Alliance Commendation Signets.$B$BAccetto anelli in quantità diverse, ma per te lo scambio più vantaggioso è consegnarmene dieci alla volta. Quando me li porterai, registrerò le tue gesta nei nostri archivi, e così gli Gnomeregan Exiles riconosceranno il tuo impegno e i tuoi servigi."
S["4e267f87"] = "Le Cliffspring Falls sono lungo le montagne, a est e a nord."
S["4e276245"] = "Io il Grimlok, re!"
S["4e2be207"] = "Ottimo lavoro, $Gsoldato:soldatessa;. Puoi andare!"
S["4e2c5e25"] = "Prima che arrivasse lo Scourge facevo grandi affari: compravo e vendevo di tutto. Di tutto!$B$BE i miei prezzi erano DA PAZZI!$B$BChiedi pure a chiunque. A chiunque non sia morto."
S["4e2e9994"] = "È gentile da parte tua chiedere, $C, ma abbiamo già tutto il salmone impanato che ci servirà per la guerra. Forse saresti così gentile da chiedere agli altri raccoglitori qui; avranno di sicuro qualcosa per cui gli servirebbe il tuo aiuto."
S["4e2f73b9"] = "Spiriti dell'Acqua, io vi lodo e vi chiedo un favore. Avete sentito le suppliche di $N, e confido che le sue intenzioni siano nobili. Vi prego, ci aiuterete?"
S["4e32ebe2"] = "Scatenate la cavalleria!"
S["4e3738e3"] = "Non c'è un segugio migliore di Drayl in queste terre. Lo puoi trovare sull'Hunter Rise."
S["4e38862a"] = "<Mentre ti avvicini, la nube ribollente di living lightning che hai davanti sembra crepitare minacciosa. Forse conviene andarsene. In fretta.>"
S["4e5f980a"] = "Woo Ping ha una resistenza sbalorditiva. L'ho visto esercitarsi nelle tecniche d'arma per ore e ore, e alla fine mi è dispiaciuto per il practice dummy. Per addestrarti nel combattimento armato non mi viene in mente nessuno più adatto."
S["4e612ee5"] = "Smettila di guardarmi così. Non sarò un avventuriero come te, ma un po' di muscoli posso averli anch'io. A forza di mescolare, le braccia si fanno forti."
S["4e632068"] = "%s sente la voce del suo padrone!"
S["4e7b373a"] = "Bisognerebbe celebrare e condividere l'alfabetizzazione."
S["4e7b39f8"] = "Hmm? Oh, sì, posso insegnarti qualcosa, se lo desideri. Ma stai alla larga da Sumi e Tumi, non sono per quelli come te. Saru lascia avvicinare alle sue figlie solo chi è molto abile."
S["4e80bada"] = "Li eseguirò con piacere, $N!"
S["4e8d64a9"] = "Deponete le armi, le vostre faide non hanno posto qui!"
S["4e97e611"] = "<Andorov ti guarda cupo.>$B$BSe sanguina, possiamo ucciderlo."
S["4e9b3f67"] = "Lui morto."
S["4e9d4506"] = "La lama e Mograine erano una cosa sola. Capisci? Quell'atto ha corrotto la lama e, con lei, lo stesso Mograine, che è diventato cavaliere della morte di Kel'Thuzad. Ho giurato che, se fossi $Gsopravvissuto:sopravvissuta;, avrei smascherato chi aveva commesso questo crimine atroce. Per due giorni sono $Grimasto:rimasta; fra il marciume e il contagio dello Scourge — a raccogliere tutte le forze che potevo per fuggire dalla città rasa al suolo."
S["4e9ef216"] = "%s si demoralizza e fugge!"
S["4e9fe583"] = "SQUAWK!!!"
S["4ea2c94b"] = "Martens, Reblock, Adinay, Nikeson..."
S["4ea3415f"] = "Un Alliance Commendation Signet va a $Gun eroe:un'eroina; che fa per l'Alleanza ben più del proprio dovere. In tutte le città principali trovi gli Ufficiali d'Encomio delle varie fazioni dell'Alleanza; parla con quello della fazione presso cui vuoi aumentare la reputazione e consegnagli quanti anelli ti chiede!$B$BA proposito, finché qui dura lo sforzo bellico, se per i tuoi anelli preferisci una ricompensa materiale invece della reputazione, cerca Field Marshal Snowfall."
S["4ea466e5"] = "Gremlock in cucina non ha sempre molta fortuna, ma conosce qualche ricetta gustosa che vale la pena imparare. Fatti due chiacchiere con lui nella Thunderbrew Distillery e vedi cosa ti insegna."
S["4ea6836f"] = "Che c'è? Ti serve qualcosa?"
S["4eab6095"] = "$GBenvenuto:Benvenuta;, $N! Ti interessa addestrarti in sartoria?"
S["4eb2a52b"] = "<Davanti a te giace uno skyborne: il corpo è straziato e coperto di lividi, ma lo si riconosce ancora. Di certo ha fatto una fine orribile mentre cercava di fuggire.$B$BSembra avere ancora addosso tutti gli averi, e lì accanto c'è una cassa mezza piena, rovesciata a terra.>"
S["4eb8847e"] = "Ti distruggeremo prima di bruciare!"
S["4ebffd43"] = "Buongiorno a te, Nogg! Ho bisogno di addestramento."
S["4ec4f30d"] = "Co... cosa succede?"
S["4ec8eb54"] = "L'ultima volta che ne ho sentito parlare, Elder Stonespire era a Everlook, in Winterspring."
S["4ecde46d"] = "Ops!"
S["4ef33c3a"] = "Niente... più... Feugen."
S["4ef8a147"] = "Insieme, le due parti torneranno a essere una sola."
S["4f001059"] = "Ah, eccola!"
S["4f03e130"] = "Io punto sui goblin! E se hai un po' di sale in zucca, farai lo stesso!"
S["4f183d5f"] = "Stai in guardia... Arnak ha uno strano potere sui Grimtotem... non saranno contenti di vedermi fuggire."
S["4f1acf49"] = "A est ci sono branchi di lupi, e chiunque vivesse al Malden's Orchard se n'è andato."
S["4f268be7"] = "Ssserenità... finalmente!"
S["4f2cbf88"] = "Beh, guarda chi si rivede: $N! Che piacere vederti! Non so davvero come ringraziarti per tutto l'aiuto che finora hai dato a me e alle mie invenzioni.$B$BCosa posso fare per te oggi?"
S["4f313c77"] = "Neanche a ovest c'è traccia dell'ultimo carico di esplosivi. Dove si sono cacciati quei perdigiorno?"
S["4f355008"] = "Grazie dell'offerta, $C. Purtroppo non sei ancora $Gesperto:esperta; abbastanza da affrontare i pericoli dell'Arathi Basin."
S["4f4a1efd"] = "Grazie, $N. Ora il mio spirito troverà finalmente la pace."
S["4f4b139d"] = "Bene, ci è appena giunta voce che una carovana sta partendo da Thelsamar. È ora di muoversi! Via, via, via!"
S["4f4e4ed3"] = "Ahhh, il calore di An'she è davvero gradito. Grazie per avermi aiutato."
S["4f5396c1"] = "Ehi, tu! Va' a vedere che cos'è quel rumore."
S["4f662f25"] = "%s si arrende."
S["4f672aa2"] = "Allora va' alla Bena's Alchemy, sull'altura di mezzo, e parla con Bena in persona: potrà aiutarti a padroneggiare l'arte di preparare pozioni."
S["4f6af44c"] = "Li uccidiamo per l'impertinenza di aver disturbato il nostro sonno?"
S["4f6b66c8"] = "Dove posso andare per migliorare a scassinare le serrature?"
S["4f6c08f1"] = "Oh, mi sono allontanata di nuovo. Scusa."
S["4f7438a3"] = "L'unica anomalia nella sintesi dell'Earthen è che la matrice tende a destabilizzarsi quando viene impiegata in ambienti ad alto stress.$B$BAddendum: la scultura della terra profonda era per natura adatta al nuovo modello di matrice, e per questo non ha mai soddisfatto i requisiti per riprodurre un ambiente ad alto stress.$B$BLa destabilizzazione è emersa solo quando il ciclo di servizio primario dell'Earthen per i Creatori era già molto avanzato. I Creatori hanno cominciato a lavorare a una modifica post-sintesi, invece che a un richiamo e a una nuova sintesi."
S["4f74568c"] = "%s comincia a muovere la Stone of Relu sopra i due fossili."
S["4f7919e3"] = "Non ho niente di personale contro i Windshapers come te, ma questo non mi obbliga a fare conversazione con te. Va' pure per la tua strada, però ti consiglio vivamente di stare alla larga dall'High Order e dai nostri agenti mentre viaggi per Zephras Isle.$B$BL'High Order non cerca lo scontro... ma se sarà lo scontro a trovare noi, lo chiuderemo con decisione. Non intralciarci, Windshaper."
S["4f7ec892"] = "Brutto piccolo...!"
S["4f899e78"] = "Che liberazione!"
S["4f8a3d27"] = "Le creature di Winterspring so' un buon posto da dove comincia'.$B$BPerò, ci potrebbero esse' pure altri posti dove cerca'..."
S["4f8cb551"] = "Molto bene, Gerard. Fra un po' li farai anche riprodurre."
S["4f8ea8fb"] = "Ora vive al fianco di Emperor Thaurissan. La tiene sotto una specie di potente incantesimo che le altera i pensieri... e io me ne sto qui, senza poter fare niente."
S["4f8f6ed2"] = "Non dimenticate gli orfani di Stormwind!"
S["4f91e5be"] = "Gli ordini sono stati dati! Morte agli Stormpike! Caricate il nemico!"
S["4f98e699"] = "Se hai bisogno di riposare e di rimetterti in forze, il posto migliore è la Locanda di Dolanaar. Innkeeper Keldamyr avrà cura che tu sia ben $Gaccudito:accudita;."
S["4f9946c9"] = "Svegli, ragazzi! Il nemico è in vista! Formate i ranghi subito!"
S["4fa0fc5b"] = "Per favore, accendilo mentre incanalo."
S["4fa171d3"] = "L'Iceblood Tower è sotto attacco! Se nessuno la ferma, l'Alleanza la distruggerà!"
S["4fa9233f"] = "Sì... SÌ! È VIVO!!"
S["4fad042e"] = "Bravo! Bravo! Bello spettacolo. Cosa? Pensavi che fossi morto?"
S["4fb0e4ad"] = "Feccia come voi non vale nemmeno il mio tempo. Distruggeteli, branco mio!"
S["4fc1f8db"] = "Va' alla spelonca delle ombre e cerca la Tessitrice di Incantesimi Mon'ye: sta vicino al centro del quartiere."
S["4fc65599"] = "Il Consiglio di Duskwood deve agire. Il male aleggia nell'aria."
S["4fc7e5a5"] = "Sono qui! E l'Irondeep Mine è... MIA!"
S["4fcafd5f"] = "Devi essere in rapporti amichevoli con i nani di Ironforge prima che io ti insegni un'abilità di cavalcatura, $C."
S["4fcc3c12"] = "Prima dell'esilio, Deathwing cercava di creare una progenie impura. Ibridi immuni non solo ai poteri e alle capacità innate dei loro Aspetti, ma anche del tutto sotto il controllo di Deathwing.$B$BPare che, dove suo padre ha fallito, Nefarian possa essere riuscito — almeno in parte.$B$BÈ stata Ysera, l'Aspetto dei Sogni, a vedere quegli abomini e a costringerci ad agire. Se questi draconidi 'Cromatici' esistono, vanno distrutti."
S["4fde2157"] = "Con l'ago quel Jormund Stonebrow ci sa fare, eccome se ci sa fare. Se ti serve un po' di addestramento, lo trovi alla Stonebrow's Clothier, sul lato nord di The Great Forge."
S["50015a48"] = "È Reethe, senza dubbio. Andiamo a sentire cos'ha da dire, eh?"
S["500279fb"] = "$GBenvenuto:Benvenuta; a Camp Mojache, $Gcoraggioso:coraggiosa; $C. Come posso aiutarti, quest'oggi?"
S["5009e3d8"] = "Qualcuno ha visto qualcosa? Che cosa è successo?"
S["500a6d5d"] = "Lo Snowfall Graveyard è dell'Orda."
S["500b8c45"] = "Cedi la tua anima, mortale."
S["50146612"] = "Che nessuno sopravviva!"
S["50213b92"] = "Fai attenzione, $N. A quei lupi piace nascondersi tra gli alberi."
S["50293ab5"] = "Me lo chiedi sul serio? Davvero non lo sai?$B$BSe sei il tipo codardo, che ha paura di sporcarsi troppo le mani, i rottami Dark Iron li trovi addosso alle creature delle Burning Steppes e della Searing Gorge.$B$BSe invece sei più il tipo avventuriero assetato di sangue, nei dungeon di Blackrock Spire e dei Blackrock Depths c'è una bella scorta di rottami."
S["502f89b9"] = "Ragazzi e ragazze. Oggi può essere il vostro giorno più grande, perché oggi combattete per la gloria di Stormpike! Cavalcate verso il campo e non concedete pietà ai vostri nemici! Abbattete quei selvaggi e che sia il loro Capoguerra a sistemarli!"
S["503224b9"] = "Hai fatto bene, $N. Continua la tua ricerca della conoscenza e ricorda la storia che hai imparato."
S["5032cbeb"] = "%s e le sue forze d'invasione compaiono in mezzo a un tumultuoso incendio a nordovest di Silithus."
S["5032e6cf"] = "Fra il passaggio arancione e quello viola, vicino alle porte di Maraudon, troverai un terzo sentiero.$B$BLa chiave è lo scettro che hai in mano."
S["5036f745"] = "Marshal Windsor ti stava aspettando, $N. Purtroppo, al momento è indisposto. Dovrebbe tornare a breve."
S["50371bd7"] = "Una lama nascosta nella manica può fare la differenza tra te $Gdisteso:distesa; senza vita nel vicolo e il tuo avversario disteso a faccia in giù nel suo stesso sangue."
S["503ac08e"] = "$N ha difeso la segheria!"
S["5040cbde"] = "Perché andiamo di qua?"
S["50501038"] = "Noma dovrebbe avere la cena pronta a breve. Tanto vale entrare."
S["505811fd"] = "Il tempo della nostra vendetta è giunto! Che l'oscurità regni nel cuore dei nostri nemici!"
S["505c38e2"] = "Come, niente pegno per me? Non mi vuoi bene?"
S["505df8d5"] = "$N! Ti tengo d'occhio!"
S["505f2033"] = "CHI OSA?! Sarai distrutt$Go:a;!"
S["505fc7d2"] = "Sono lieto di dire che i tuoi talenti hanno superato i miei. Ora vattene. Ehm, prova con la tauren Una nelle botteghe a nord-ovest dell'altopiano centrale del Thunder Bluff. È molto abile, te lo assicuro."
S["5062ab12"] = "Danzeremo sulle tue ossa!"
S["5063972b"] = "Ne sono seguiti eventi tragici, uno dopo l'altro, e ogni mago del Kirin Tor entrato in contatto con Atiesh ci ha lasciato la vita.$B$BVedi, era un artefatto con una coscienza. Una coscienza che gli aveva dato Sargeras..."
S["5074e2e0"] = "Continua, ti prego, questa storia è intrigante."
S["5083bbcf"] = "Cerchi Plucky? Be', io non ti ho detto niente, ma... prova a chiedere a Kronkrider, su nella torre, magari te lo dice..."
S["5084b065"] = "L'Iceblood Tower protegge l'Iceblood Garrison da sud-est.$B$BÈ controllata dall'Alleanza."
S["508f1118"] = "Non la senti, l'angoscia della Madre Terra per i suoi figli perduti, i non morti? Parla in fretta, $N. Ogni secondo mi costa caro. Dobbiamo aiutarli a ritrovare la strada che li riporta da lei!"
S["50928837"] = "Grazie a un po' di tecnologia recuperata da gnomi audaci che si sono avventurati a Gnomeregan, sono riuscito a costruire la mia invenzione più grande: il Trasportatore di Materia! Adesso mi manca solo un Ingegnere Gnomesco esperto che costruisca un faro potente, sintonizzato con il trasportatore."
S["5092a6eb"] = "Hakkar vivrà di nuovo!"
S["5093cdbe"] = "Impotente... senza poteri... ripristinare... devo ripristinare... Zevrim controlla... mettere fine a questo tormento..."
S["50995e0f"] = "$GBenvenuto:Benvenuta; nell'Explorer's League. Se ti servono informazioni che si trovano in un libro, forse posso darti una mano."
S["50a0d6e6"] = "Ringo! Stai bene!"
S["50ae9522"] = "Muori in nome della Defias Brotherhood!"
S["50b6d115"] = "$C, eh? Io sono Krazek, il segretario di Baron Revilgaz, e di quello che succede in questa giungla, e anche più in là, so tutto. Magari ti interessa sapere quanto costa oggi il petrolio a Ratchet? No? Allora cerchi lavoro, magari? Per quello posso darti una mano."
S["50c3f47a"] = "Bah, i ladri ci hanno solo complicato il lavoro qui a Stormwind. Vorrei tanto trascinare Osborne e Mathias fuori dall'Old Town, dritti nella Stockade."
S["50c4cbcc"] = "Il Ragefire Chasm sta sotto la Shadow Cleft, al centro di Orgrimmar."
S["50ca6ca6"] = "Vediamo se stavolta riesco a fare centro."
S["50ccaa6b"] = "Sono nel bel mezzo di un lavoro molto importante. Faccende da cercatore. Se non hai da dirmi qualcosa di altrettanto importante, e ne dubito, dovrai scusarmi."
S["50cd90a2"] = "Sei $Gscrupoloso:scrupolosa; a informarti, $C, ma tutte le raccolte dell'Orda sono state completate. Ora aspettiamo che l'egemonia dell'Alleanza finisca le sue, e poi tutto sarà trasportato a Silithus, nei pressi di Cenarion Hold."
S["50d96eb2"] = "Un po' di tutto. Più che altro prendo i molli e i deboli e li faccio tornare combattenti temprati.$B$BIl mondo là fuori è duro, e perfino la nostra gente non si fida di noi. Se vogliamo trovare posto in questa \"Orda\" insieme al resto del nostro popolo, dobbiamo essere forti e cavarcela da soli."
S["50df5257"] = "L'Incubo è finalmente finito! Darrowshire, perdonami!"
S["50ef8cb9"] = "La migliore birra di Stormwind, Langston. Grazie."
S["50f74aae"] = "Solo uno sciocco oserebbe disturbarmi nella mia tana."
S["50fbefba"] = "Purtroppo, $C, non sei ancora abbastanza forte per sopravvivere a Warsong Gulch."
S["50fc6ba2"] = "Che posso fare per te, $N? Spicciati, non ho tutto il giorno!"
S["51013f33"] = "NOOOOOOOOOOOO!"
S["5101b94e"] = "Non è bastato.$B$B<Fairbanks accenna un sorrisetto, perso in un ricordo.>$B$BNe sono arrivati mille, e mille sono morti. Per la Luce! Per la potenza di Mograine! Li abbatteva uno dopo l'altro, appena arrivavano. In mezzo al caos ho visto che il Mograine minore era ancora lì, in lontananza, e l'ho chiamato: \"Aiutaci, Renault! Aiuta tuo padre, ragazzo!\""
S["5104af1e"] = "Guardati intorno, $N. Forse troverai qualcosa che mi è sfuggito."
S["5104f0d3"] = "Ho un'idea abbastanza precisa di cosa farà il vecchio Greatfather Winter finito questo turno: qui in borsa ho una bottiglia di allegria di Winter Veil, e ho tutta l'intenzione di andarci fino in fondo."
S["510bc3e1"] = "Fa piacere vedere $Gun ingegnere:un'ingegnera; con il coraggio di costruire il congegno. Noi ingegneri goblin al pericolo ridiamo in faccia!"
S["51198fb1"] = "La vera maestria va guadagnata! Ora sta a te guadagnartela..."
S["51261d0e"] = "Oh, giusto! Da questa parte adesso..."
S["513666ce"] = "Doom'rel, il nostro capo, presta orecchio alla sfida."
S["5137cb53"] = "Ti sei $Garreso:arresa;. Ho vinto io."
S["513c491e"] = "Possiamo restare solo pochi istanti prima di tornare alla torre. Se vuoi parlarci ancora, ci troverai lì."
S["513d2139"] = "Siamo qui per guadagnare. E se ci rubano la merce, di certo non guadagniamo."
S["51407a44"] = "Io avrei buttato un po' di Evershine nel serbatoio e sarei già stato a casa prima che si accorgessero che me n'ero andato!"
S["5144c9c7"] = "Lascia questo luogo sacro o perisci!"
S["5145f965"] = "Ecco, tutto finito. Il diario è stato tradotto per te."
S["5147e831"] = "Il mio grande martello, Ironfel, è finito al nuovo capo architetto, Fineous Darkvire: un uomo dalle intenzioni spregevoli e di poco talento.$B$BÈ qui che entri in gioco tu, $N: voglio che tu lo fermi. È troppo inetto per sfruttare il vero potere di Ironfel, ma se dopo di lui arrivasse qualcuno capace di usare Ironfel al massimo, con le sue creazioni potrebbe causare una distruzione disastrosa per questo mondo."
S["51522e52"] = "$N, i miei compiti sono finiti e ora me ne vado. Buona fortuna, $Gamico mio:mia signora;, e ricorda di tenere in funzione la Campana, la Ruota e la Candela!"
S["515970f3"] = "Hai il corpo provato e lo spirito stanco. Riposa sotto il nostro tetto, e lascia che Elune guidi i tuoi sogni."
S["515a0a99"] = "La cassetta di sicurezza del SI:7 si spalanca di colpo. In lontananza si sentono grugniti e voci."
S["516307d6"] = "Senza quella fortuna sfacciata e inconcepibile che hanno, i goblin si schianterebbero con l'auto a ogni gara!"
S["516488e9"] = "Och, mi piace 'na bella scazzottata, ma a volte il tuo nemico c'ha un cranio più spesso di uno scudo termico di Torio. In casi così ti ci vuole un tantino d'aiuto."
S["516b27de"] = "Catene? A questo mondo ci sono cose che incatenano molto più di sbarre e ceppi, giovane $Gsignore:signora;. Eravamo circondati dai non morti, che ci tormentavano di continuo con atti di orrenda depravazione.$B$BAlla fine è arrivato lui. Si è presentato come Doctor Theolen Krastinov, ma per noi è diventato 'Il Macellaio'."
S["516b3cd5"] = "La Frostwolf Keep si trova nell'angolo meridionale dell'Alterac Valley e protegge il Frostwolf Village, dimora del clan di orchi che porta lo stesso nome. Tutti i territori dell'Orda nell'Alterac Valley hanno origine da questo unico luogo di potere.$B$BLa Frostwolf Keep è intatta."
S["517f6de2"] = "Cerca nell'Old Town, alla Caserma o alla Pig and Whistle Tavern. Se passi dalla taverna, assaggia senz'altro qualcuna delle sue birre: sono ottime e fanno sfigurare quelle dei nani, te lo dico io."
S["5181a2cd"] = "Stiamo perdendo tempo, io e te! Se vuoi cominciare l'addestramento, va' da Graham Van Talen! È laggiù, alla mia sinistra."
S["518415c9"] = "Ora senti dolore..."
S["518d4fc8"] = "Mi deludi, Taelan. Avevo dei piani per te... grandi piani. Ahimè, era solo questione di tempo prima che la tua sporca stirpe venisse fuori."
S["51970f80"] = "Il tuo sangue sarà il catalizzatore che riporterà gli Old Gods!"
S["519af9e6"] = "Ti manca il tatto, Comandante. Non mi sorprende. Però hai ragione: l'Orda sarà costretta ad agire. E non solo l'Orda. Stanno già arrivando eroi da tutto il mondo."
S["51a23117"] = "Questo raggio di luce lunare superiore ti porterà a Darnassus."
S["51ab07e7"] = "La tua fiducia nelle mie capacità mi lusinga, ma insegnarti va oltre le mie competenze. Devi andare alla Craftsmen's Terrace di Darnassus e parlare con l'elfa della notte Ainethil: lei può aiutarti."
S["51b2e776"] = "Vuoi il mio aiuto? Ce l'hai. Cosa ti serve?"
S["51b5a14c"] = "Non fallirò più."
S["51b82ce7"] = "$N ha difeso le stalle!"
S["51bac2fc"] = "Cosa posso fare per te, oggi?"
S["51c16297"] = "Maledizione rilevata. Rimozione in corso."
S["51c1ad84"] = "Ascolta, drago. Che la verità risuoni in queste sale."
S["51c77d3c"] = "%s comincia a sbattere le ali all'impazzata e a starnazzare forte. Hai la sensazione che stai per diventare il suo prossimo pasto."
S["51cba837"] = "Oh, eccoti!"
S["51d35937"] = "Accidenti, mi dispiace, ma non ho niente di nuovo da insegnarti. Perché non passi da Simon Tanner, nell'Old Town di Stormwind? È un umano con dei muscoli enormi e dei capelli rossi da sogno."
S["51dccf3f"] = "Dopo la caduta di Karazhan, il Kirin Tor ha mandato un gruppo di maghi a perlustrare la torre e a sequestrare tutti gli oggetti importanti... per motivi di \"ricerca\". Durante quella missione hanno trovato il leggendario bastone e l'hanno riportato a Dalaran."
S["51e40594"] = "%s si schiarisce la gola."
S["51e6e53b"] = "Per quello devi andare a Orgrimmar. Prendi la strada che da Razor Hill va a nord attraverso il canyon e ci arrivi. Lì chiedi altre indicazioni a uno dei loro grunt."
S["51e866d9"] = "Ok, muoviamoci!"
S["51f2d6d2"] = "No! Lasciateci! Non dobbiamo fallire il nostro compito!"
S["5202b851"] = "Di recente un druido elfo della notte di nome Naralex ha scoperto una rete di caverne sotterranee nel cuore delle Barrens. Convinto che con le sorgenti delle caverne avrebbe potuto far tornare rigogliose le Barrens, il druido ha cominciato ad attingere alle energie del leggendario Sogno di Smeraldo. Ma chissà come la sua visione si è trasformata in un incubo, e in poco tempo le Wailing Caverns sono diventate un covo di predatori feroci e letali. Si dice che Naralex sia ancora da qualche parte nel labirinto, intrappolato oltre i confini di The Emerald Dream."
S["520ffc54"] = "Adesso mi serve solo un lazo d'oro."
S["5210299b"] = "Che istruttore di classe stai cercando?"
S["5212c4a0"] = "$GBen trovato:Ben trovata;, $C. Se non devi trattare direttamente con la mia signora Magatha, puoi parlare con me.$B$BSono io a sbrigare quasi tutte le sue faccende, così lei può dedicarsi alle questioni più importanti. Forse c'è qualcosa di cui potremmo discutere, prima che tu le chieda udienza?"
S["5214be94"] = "Questo molo? Be', puoi prendere la nave che va a Southshore e che poi si ferma in quel posto degli elfi della notte. Come si chiama? Ehm... Auberdine, mi pare.$B$BNon lo so mica di preciso, io carico e scarico la roba e basta."
S["5225143b"] = "Non trovo più la mia rana, Jubjub. Adora la Birra Dark Iron, non beve altro, ma trovarla è così difficile! Adesso l'ho finita... e Jubjub sarà scappata a cercarne ancora!$B$BVorrei tanto che tornasse..."
S["52259385"] = "%s è $Gvuoto:vuota;."
S["52274b8e"] = "Sei $Gvenuto:venuta; a imparare l'arte della guerra, $R? Sei $Gvenuto:venuta; nel posto sbagliato."
S["5235e630"] = "Maledizione... Devono essere stati i goblin... Vediamo quanto è grave il danno."
S["523e50da"] = "Ti immagini?"
S["5242f4dc"] = "Degli animali che cacciamo non sprechiamo nulla."
S["52432ee8"] = "Quando dai dei love tokens agli abitanti, in cambio ricevi regali diversi. Alcuni vorrai tenerli per usarli, altri invece puoi metterli insieme e regalarli al tuo eroe preferito! Per consegnarli, va' da Kwee Q. Peddlefeet.$B$BKwee lo trovi vicino a Bolvar, Magni o Tyrande."
S["52471886"] = "Nuff Nagan odes bor far veld lon vrum vrum!"
S["5248c4ba"] = "L'Iceblood Graveyard è sotto attacco! Se nessuno interviene, l'Alleanza lo conquisterà!"
S["5254ef38"] = "Subito, signore."
S["5259e30c"] = "Throm'ka, $C dell'Orda, a testa alta! Sono Warlord Gorchuk, comandante dello sforzo bellico dell'Orda. Ci aspettano tempi difficili, ma trionferemo, come sempre.$B$BSe hai domande, chiedi pure."
S["525cd281"] = "Mmh, capisco. Bene, allora, $C: i Windshapers vi aiuteranno. Ti prego di dire a Valennia che in questa battaglia può contare su di noi.$B$B<Ayessa abbassa la voce, minacciosa.> $B$BNon scambiare il nostro aiuto per una qualche forma di perdono. Con i Windshapers hai un debito di sangue, e un giorno verremo a riscuoterlo."
S["525faa7e"] = "Tartufi!"
S["5260d62e"] = "Voglio che tutti e due mostriate agli allievi più giovani le tecniche che vi ho insegnato. Pronti... via!"
S["526bd372"] = "Basta con questi discorsi. Voglio parlare dei bei tempi. Garek l'avrebbe voluto per noi."
S["5270bce0"] = "La vostra sfacciata arroganza!"
S["52712069"] = "Il maestro di battaglia"
S["52783b3b"] = "Ma per cosa ti pago? I kodo sono quasi morti!"
S["5278e502"] = "Ecco un faro per te, $N. Devi tenerlo con te se vuoi trovare gli oggetti corrotti che ci serviranno."
S["5284300a"] = "Ah, $Gun visitatore:una visitatrice;! Quaggiù di turisti non ne vengono molti, sarai $Gun avventuriero:un'avventuriera;. Prendi una sedia, prenditi qualcosa da bere e mettiti $Gcomodo:comoda;. Di', mi sembri $Gbello robusto:bella robusta;. Hai intenzione di partecipare agli incontri in gabbia?"
S["52891636"] = "Chiedo scusa, signore. La banca non ha ancora aperto. Se non ti dispiace, ripassa più tardi."
S["52979365"] = "Proteggimi da $Gquesto:questa; $N! Devo tornare dalla mia covata."
S["52997536"] = "Nel pieno della Grande Scissione, Ameth'Aran era in balia del terrore che attanagliava la terra. C'erano poche speranze di sopravvivere."
S["52a1351f"] = "SEI TU $GIL:LA; PERDENTE. BUU."
S["52a14ca1"] = "Sono $Gun:una; Highborne, $R, anche se ormai non significa più nulla. Eppure ci fu un tempo in cui erano gli Highborne a governare questo mondo. Diecimila anni fa..."
S["52a7de19"] = "Ah, bene. Queste spore sono lavorate come si deve. Grazie, $N."
S["52b17556"] = "Addestro i giovani cacciatori e li guido nelle tradizioni che si tramandano da molte generazioni."
S["52b1e1fe"] = "Forgiatura"
S["52b4e5d0"] = "Disperazione? Fame? Non lo faccio mica perché mi piace rapinare e ammazzare. Ho perso la casa e non avevo dove andare, e radermi la testa per adorare qualche dio del vento immaginario non mi va granché. Così sono diventato un bandito. Il resto viene da sé."
S["52bc9043"] = "Siamo $Gstati:state; $Gmandati:mandate; qui da Darnassus per aiutare gli Stormpike nel loro momento del bisogno."
S["52be2bfe"] = "Uldum è una struttura di ricerca dove i Creatori portano avanti la loro opera per migliorare la biosfera di Azeroth. Le informazioni specifiche su quello che fanno a Uldum sono riservate a chi ha le Tavole di Uldum nei propri set di dischi.$B$BNel complesso di Uldum gli archivi di dati sono stati programmati per trattare esperimenti e raccolte di dati specifici; consultali per informazioni dettagliate."
S["52c1942c"] = "Gli atti di proprietà sono miei, fratello! Presto ti toglierò di mezzo per sempre!"
S["52c2add6"] = "Grazie per le spore, $N. Adesso sono pronte per essere trasportate."
S["52c7066c"] = "Il Dun Baldar South Bunker è stato conquistato dall'Alleanza!"
S["52c7a843"] = "Magistro Supremo... ho... fallito."
S["52d2bd13"] = "Sono $Gun mago:una maga; di grande potere, ho passato i miei giorni a studiare la mente e la memoria in relazione all'apprendimento e alla conservazione delle abilità apprese. Starei perfezionando i miei studi anche adesso, se non fosse per le grandi voci che sono venute da me nella notte, informandomi che i miei servigi erano richiesti. Resterò qui solo per poco tempo, offrendo gratuitamente la mia capacità di azzerare i tuoi talenti. Presto ripartirò, e sarai di nuovo $Gbloccato:bloccata; con qualunque scelta farai."
S["52d892f2"] = "Fengus fare te feroce! $GPazzo:Pazza;! RAR!"
S["52db4602"] = "$GBenvenuto:Benvenuta; nella città di Darkshire. Clerk Daltry, al tuo servizio. Posso aiutarti?"
S["52dbacda"] = "$N, vorrei scambiare due parole con te."
S["52ddd69b"] = "Quando ne hai bisogno, Seikwa può prendersi cura dei tuoi amici animali. Cercala davanti alla locanda."
S["52e17b53"] = "Che cos'è questo? Vuoi rovinarmi la reputazione? Io non insegno ai principianti, $Gamico:amica;. Prova a parlare con l'orco Whuut nel Drag of Orgrimmar. È molto più vicino al tuo livello di abilità. E di cervello."
S["52e25c6c"] = "Cosa ti porta al Cenarion Circle, $N?"
S["52e31804"] = "Ricevo poche visite. Cerchi qualcosa in particolare, vero?"
S["52f1e6eb"] = "Ma salve, signore. Avete sentito della nuova pestilenza?"
S["52f27c75"] = "Se non fossi $Gvincolato:vincolata; dal dovere verso Master Ravenholdt, ti seguirei fino ai confini del mondo, Signora $N. Sei la grazia e l'astuzia fatte persona."
S["52f51128"] = "%s chiama le sue guardie."
S["52f5dc20"] = "Un posto sgradevole, questa \"Undercity\". Non è affatto come la Lordaeron di un tempo. Quanto mi manca...$B$BSe vuoi andare a Stratholme, temo di non poterti aiutare al momento. Le torri vicino alla città in fiamme sono ancora contese, e per questo i miei poteri sono troppo deboli per aiutarti. Torna da me quando sarai $Gvittorioso:vittoriosa; là."
S["52fd54ce"] = "Ammirate la potenza dell'Alleanza! La terribile dama, Onyxia, pende dagli archi! Che il grido di battaglia dell'uccisore di draghi sollevi i vostri spiriti!"
S["5309d02d"] = "Strillavi come una ragazzina, la cosa più buffa che abbia mai visto."
S["5316413d"] = "Al di là di questo corridoio, Naralex giace in un sonno agitato. Andiamo a risvegliarlo, prima che sia troppo tardi."
S["532058ca"] = "Unisciti a me, insieme intrecceremo gli spiriti della forgia e troveremo la vera forma che il metallo cerca."
S["5323fa28"] = "Sono qui! Il tuo dominio su questa terra è finito!"
S["5329c681"] = "Vieni a dare un'occhiata alla merce finché sei in tempo. Restiamo qui per tutta la settimana, poi ripartiamo verso qualche terra lontana."
S["5348530b"] = "Avete visto? C'è uno dello Scourge laggiù!"
S["534a7c5f"] = "Sì, certo, dai, di' pure al vecchio Greatfather Winter cosa vorresti per questa Winter's Veil.$B$BOh oh oh, muoviti."
S["535518ff"] = "Su queste terre domina l'influenza della Shattered Hand. Siamo il velo che copre Kalimdor: protettori, polizia, giudici, giuria e, alla fine, boia. Vediamo tutto, sappiamo tutto.$B$BDa quando servi la Mano sei $Gcresciuto:cresciuta; molto, $N. È arrivato il momento di mandarti sul campo.$B$BSei $Gpronto:pronta; per la prossima missione?"
S["535ca4e7"] = "Per preservare la vita immortale e i poteri quasi illimitati del Principe, il popolo è stato distrutto. Il potere che un tempo era diviso fra migliaia ora confluisce nel Principe e negli zeloti Shen'dralar. I pochi sopravvissuti alimentano direttamente i piloni per tenere Immol'thar imprigionato.$B$BSe il demone si liberasse dalle catene, distruggerebbe di certo quel poco che resta di questo bastione delle arti arcane, un tempo grandioso."
S["536c86a7"] = "%s crea un nuovo totem..."
S["536df5b8"] = "No! Ora i Defias si prenderanno di sicuro la fattoria!"
S["53726b68"] = "Oh sì. Noi ce l'ha proprio qui."
S["5384bf04"] = "Siete morti, non sepolti. Adesso fatemi vedere il vostro meglio!"
S["538a2a22"] = "Muori nel nome di Edwin VanCleef!"
S["5397d5c1"] = "Nebbia! Temevo di non rivederti mai più! Sì, sto bene, non preoccuparti per me. Devi riposare e rimetterti in forze."
S["539afbd1"] = "Come, amore mio? Come troverò la forza di affrontare le ere del mondo senza averti al mio fianco..."
S["53a2eee4"] = "Non si può permettere a questo male di entrare nel mondo! Venite, figli miei!"
S["53a864a2"] = "Vogliamo solo sapere perché i silvagufi sorvegliano questa zona..."
S["53b6365b"] = "Vuoi dire che da qui non lo senti, l'odore del fumo delle fucine dei Nani? Beh, se vuoi imparare l'arte del fabbro, cerca Therum Deepforge: lo trovi nel Dwarven District, appena a nord della Cathedral Square."
S["53b77849"] = "Su questo punto molti non sono d'accordo. I Windshapers vorrebbero farti credere che basti prendersi per mano e limitarsi a sperare che gli spiriti tornino. Ma il potere del loro ordine si è indebolito, e la loro strada ci ricondurrebbe a quel ciclo di dipendenza che ci ha portati fin qui. L'High Order, invece... noi crediamo in un approccio più diretto."
S["53b8945c"] = "Questi frammenti scintillano di una lucentezza innaturale. È chiaro che nascondono dentro di sé un potere profondo."
S["53be1a72"] = "Captain Galvangar è stato ucciso! Onora il nostro capitano caduto e scatenati di nuovo contro l'Alleanza!"
S["53ce3b27"] = "%s scruta il mulino"
S["53d7bb1b"] = "L'Iceblood Graveyard si trova sul lato sud del Field of Strife, a est dell'Iceblood Tower.$B$BAl momento lo controlla l'Alleanza."
S["53e8b2c0"] = "Se sei qui a implorare il privilegio di lavorare per me, la tua compagnia è ben gradita. Altrimenti, dubito che tu possa essermi utile."
S["53f81007"] = "Sì, mi piacerebbe proprio insegnarti un paio di cose sul mestiere del fabbro. Prendi grembiule e martello e vediamo cosa riusciamo a combinare, eh?"
S["53f8c7e3"] = "%s è stato trovato!"
S["540287bb"] = "Dov'è il Warmaster Garrick?"
S["5403ebc2"] = "Continuate a portarne! Ci servono altre provviste per ricostruire..."
S["54089e60"] = "Sì, va bene, capo. Nessun problema."
S["5413524f"] = "Sono lieto di essere venuto a vedere ciò che hai costruito qui. Garek ne sarebbe fiero. Ma questa non era una visita di cortesia, Danitha. Lo sai di certo..."
S["541d2dae"] = "Omarion, non sono $Gun artigiano:un'artigiana;. Puoi aiutarmi lo stesso?"
S["541fb428"] = "Ora si comincia a ragionare. Costrutto, puoi dirmi chi ha rimosso i tuoi componenti?"
S["5421ba9b"] = "$GBenvenuto:Benvenuta; alla Calmbreeze Inn, $Gviaggiatore:viaggiatrice;. Vuoi qualcosa per rinfrescarti?"
S["5423efe4"] = "Impossibile! Alzatevi, miei servitori! Servite ancora una volta il vostro padrone!"
S["54259047"] = "Mi sento molto meglio, grazie."
S["5428dc90"] = "Tanto erano solo d'intralcio."
S["5431e688"] = "È piccolo, ma fa il suo lavoro se sai quello che fai. Lascia che ti mostri i punti giusti dove colpire."
S["54327bfc"] = "Il mastro degli zeppelin"
S["543315c5"] = "Ora me schiacciare te personalmente!"
S["543bf3a1"] = "Preparatevi. L'Avamposto dei Silverwing è subito dopo la curva."
S["5444bac8"] = "Finalmente! $GLibero:Libera; dalla Northwatch Hold! Ho bisogno di un momento per riprendere fiato...."
S["54492583"] = "La Locanda? Ah, hai voglia di buttar giù qualcuna delle migliori birre di Ironforge? Il posto che fa per te è The Stonefire Tavern.$B$BLa trovi subito a sinistra dell'ingresso di Ironforge quando entri, o a destra quando esci."
S["544e909e"] = "È giunta la tua ora, $N. Master Kang ti aspetta..."
S["5453363a"] = "Ah! Ora la tua morte è certa!"
S["5454ae80"] = "Perché non possiamo semplicemente spostare la matrice per compensare la variazione del flusso?"
S["54628637"] = "Glacial Wrists."
S["547ac3d7"] = "Creare Teldrassil è stata una grande impresa, ma ora il mondo deve cambiare per ritrovare l'equilibrio."
S["547ed49c"] = "Soccombete al sogno senza fine, piccoli. Lasciate che vi divori!"
S["548b679c"] = "Dolce Elune, grazie per avermi tirato fuori da quella... cosa!"
S["548c4f59"] = "Stiamo dominando lo Scourge — la pestilenza alterata continuerà a colpirli per almeno un altro giorno intero! Ma non dobbiamo mollare la presa, quindi appena puoi sabota un calderone."
S["5493b5a9"] = "Althea, ci sono notizie di strani avvenimenti al cimitero. Ello crede che sia il presagio di un attacco a Darkshire."
S["54a268ba"] = "Quello che so ha i suoi limiti, anche se continuo a imparare. È ora che tu vada avanti, viandante: cerca Josef Gregorian a Undercity e digli che sei $Gpronto:pronta;."
S["54a26f07"] = "Salve, $C $R. Sono Commander Stronghammer e qui faccio da ambasciatore per l'Alleanza. Se vuoi sapere a che punto sono le raccolte dell'Alleanza per la guerra di Ahn'Qiraj, ragazzo, chiedi pure senza problemi."
S["54a4bfd1"] = "Vieni a imparare le vie del cacciatore. Orgoglio, onore e tradizione."
S["54a60722"] = "$N, sono venuto a scoprire fin dove si siano diffusi gli effetti del Fel Moss in tutta la Darkshore. I druidi del Circolo Cenariano e tutti gli Elfi della Notte sono molto preoccupati per la corruzione di Teldrassil e delle terre intorno a noi.$B$BVoglio scoprire perché sia successo, e porvi fine."
S["54aa0b30"] = "<Il cavallo da guerra non morto ti osserva con la testa piegata di lato, mordendo le briglie.>"
S["54aed978"] = "Lo stalliere"
S["54b32382"] = "Sei $Gun cacciatore:una cacciatrice;? Beh, in ogni caso Thotar lo trovi nella tana all'angolo sud-ovest della città, al riparo dal sole."
S["54d1b9d7"] = "%s ha raggiunto la sua piena grandezza!"
S["54d8fd6a"] = "E... pensi di sconfiggere gli Dei Primordiali?"
S["54dd2a03"] = "Finora sono soddisfatto dei tuoi progressi. Di certo la Madre Terra ha ispirato le tue mani."
S["54e1a627"] = "Come?? Beh, è una storia lunga."
S["54e4167d"] = "Ora è il momento di scuotere il mondo fin nelle fondamenta! ORA è il momento di ricordare a chi vorrebbe renderci schiavi che non ci piegheremo mai!"
S["54e48cc4"] = "%s si porta il boccale all'occhio e aggrotta la fronte."
S["54e51d5f"] = "Elder Darkcore lo trovi a Undercity."
S["54f7e29d"] = "Kichalo! Kichalo! Ishte rah tihikea wa."
S["54fa60e4"] = "Non è sempre una questione di soldi, bello! Anche se riceviamo donazioni generose, alcune davvero consistenti, la nostra compagnia itinerante di artisti è spinta creativamente dal bisogno di rallegrare questo mondo devastato dalla guerra. Non preoccuparti per noi, lascia piuttosto che siamo noi a preoccuparci di come divertirti al meglio."
S["54fe34aa"] = "Si prega di lanciare un incantesimo di BUFF ad alta priorità su tutti i bersagli vicini."
S["5504f008"] = "Maka kek magan gi kek Osh'kazil Tago!"
S["5509e99a"] = "Che Elune vegli su di me. Ero certa che sarei morta quaggiù. Lascia che medichi questa ferita prima di partire."
S["5509ebe7"] = "E se non è così, allora sono davvero perduta."
S["55104767"] = "Un Alliance Commendation Signet si conferisce a un eroe che per l'Alleanza va ben oltre il proprio dovere. In tutte le città principali trovi vari Ufficiali d'Encomio delle fazioni dell'Alleanza: parla con quello della fazione con cui vuoi aumentare la reputazione e consegnagli quanti anelli ti chiede!$B$BA proposito, finché qui dura lo sforzo bellico, se per gli anelli preferisci una ricompensa materiale alla reputazione, cerca Field Marshal Snowfall."
S["5524cb73"] = "Il ragazzo aveva raccolto The Ashbringer e l'aveva conficcata nel cuore del padre, mentre lui gli dava le spalle. Le sue ultime parole mi perseguiteranno per sempre: \"Che cos'hai fatto, Renault? Perché mai una cosa simile?\""
S["55306725"] = "Le tue misure di sicurezza hanno fallito. Occupati subito di questa interruzione!"
S["553460fb"] = "Geniale, lo so... Nessuno lo troverà mai; e comunque, nel caso, al pesciolino ho dato dei poteri speciali."
S["5537d97c"] = "Ehi, signore. Mi sembri $Gun:una; $C dai gusti raffinati in fatto di vino. Devo chiederti un favore, e credo di poterti fare un'offerta che non potrai rifiutare... che te lo dico a fare!"
S["553a5928"] = "Lumurk apre questa scatola facile!"
S["553d69f9"] = "Baristolth, ho perso il mio distintivo e mi occorre un sostituto."
S["553e3be4"] = "Dove credevi che stesse il Maestro delle Wind Rider? Sali in cima a The Sky Tower, nella Valley of Strength!"
S["554c946d"] = "%s viene schizzato dal sangue e diventa radioattivo!"
S["5559468e"] = "Oh, magnifico."
S["556537c4"] = "Fuori di qui!"
S["556da2ad"] = "Intrusi!"
S["556e6fa5"] = "La foresta trema e sussulta! I venti ululano! Si sta avvicinando il Forest Lord?"
S["556f3321"] = "18 gradi Kraklenheit. A dire il vero, fa un po' freddo..."
S["557836dc"] = "Per cacciare una bestia bisogna conoscerla. Bisogna impararne le abitudini e rispettarle.$B$BChi fa altrimenti non caccia. Chi fa altrimenti uccide e basta."
S["5579cd93"] = "Qui fra le rovine stiamo attraversando un periodo fiacco e si va avanti a fatica, ma sono sicuro che non durerà a lungo. Intanto, però, qualcuno come te mi farebbe comodo. Ti andrebbe di dare una mano alla Dwarven Explorers' Guild?"
S["558128fb"] = "Ah, finalmente ci siamo! Sarà un sollievo liberarsi di questi barili."
S["5582cd10"] = "Cosa? No, le armature non le riparo. Everlook è un miglio circa a nord, fratello.$B$BE adesso compra qualcosa, o sparisci prima che evochi il mio stregone a occuparsi di te!"
S["5585f5a0"] = "%s esamina l'antica pietra coperta di muschio."
S["558a2599"] = "Riservato ai membri, pivello!"
S["558d5d45"] = "Presto il mondo tremerà."
S["55936dfc"] = "Salute! Hai un'aria familiare... ci siamo già incontrati?$B$BBe', se ci siamo incontrati, allora... di sicuro ti hanno dato un codice segreto. Dimmi il tuo codice e ti farò un regalo!"
S["559a428d"] = "La Darkmoon Faire in questo momento è nelle pianure dorate di Mulgore, appena a sud-ovest di Thunder Bluff. Non perdertela!"
S["559c3fe6"] = "Oh, è orribile, $Gsignore:signora;. Un tempo la casata Barov era piena di vita... di splendore. Il maniero era la residenza principale dei Barov in tutto il loro vasto impero.$B$BGiorno dopo giorno, io e Lucien vedevamo i Barov sempre più depressi. Sconsolati. Il padrone e la padrona erano spesso in preda alla paranoia e alla rabbia, e di notte li sentivamo litigare nelle loro stanze. Da quel che abbiamo capito, la loro avidità aveva \"rotto la diga\", per così dire."
S["559e69b5"] = "Hor gor angor ta Grum-mana!"
S["559ebc46"] = "...un cristallo della memoria! Di sicuro serviva a registrare un momento importante."
S["55ab9f97"] = "Non dobbiamo lasciare che l'Alleanza estenda il suo potere ad Arathi! Anche la loro minuscola Refuge Pointe un giorno potrebbe crescere tanto da minacciarci."
S["55b404f5"] = "Grazie ancora, Terenthis. Tornerò di nuovo se servirà altro aiuto. Fino ad allora, ti prego, manda altri avventurieri ad Ashenvale"
S["55b7f003"] = "Stabilizzazione completata. Misure difensive riattivate."
S["55c2f19f"] = "A $Gun:una; Tauren non posso insegnare a cavalcare una Skeletal Mount. Mi dispiace, ma non c'è niente che io possa fare per te."
S["55c5bda6"] = "Dov'è il vostro salvatore? Per quanto resisterete ai miei attacchi?"
S["55c86b90"] = "si sta congelando!"
S["55d670b6"] = "Che questa aura malvagia sia bandita da questo manufatto!"
S["55dba3c6"] = "Devi volare da qualche parte? Allora ti tocca andare a Undercity! Esci dal paese per la strada a sud, poi prosegui a sud-ovest fino alle Ruins of Lordaeron. Sul retro delle rovine c'è l'ascensore che scende a Undercity: lì chiedi a un Undercity Guardian indicazioni più precise."
S["55ebd637"] = "Le nostre unità veterane stanno lasciando il campo. Ci servono altri rifornimenti!"
S["55f14ae3"] = "Con ogni probabilità Elder Stormbrow è nel villaggio di Goldshire, nell'Elwynn Forest."
S["55f6d12a"] = "Vendesi gattino, cerca una bella casa."
S["55f9d606"] = "$GBenvenuto:Benvenuta; all'Undercity Guild Registry. Cosa vuoi?"
S["55fd6700"] = "Throm-ka! $GStraniero:Straniera;, cosa tu cerchi?"
S["55fd8800"] = "Calder! Di nuovo?!"
S["55ff3d38"] = "Ok, mollalo laggiù e poi ci penso io."
S["55ffc20d"] = "È un gran piacere conoscerti."
S["560b9c19"] = "Perché ... non vuoi ... semplicemente moriiiire?"
S["560c222b"] = "Sia lodata Elune! Sono molti anni che non ricevo visite."
S["560c6801"] = "Ma certo che ti amo, Staffron. E mi addolora vederti soffrire così."
S["560db644"] = "Del cuoio ne sai più di me. Forse faresti bene ad andare dal tauren Krulmoo Fullmoon, a Camp Taurajo, nelle Barrens. Ha molto da insegnare a $Gun allievo:un'allieva; del tuo talento."
S["560eb5c5"] = "Costruito il congegno, basta attivarlo e ci si ritrova nella splendida Gadgetzan! Quasi tutti quelli che l'hanno usato sono arrivati qui sulla piattaforma con lo stesso aspetto che avevano alla partenza!$B$BCi hanno segnalato qualche caso di viaggiatori sostituiti dalla loro versione malvagia di un universo alternativo, ma sono $Gsicuro:sicura; che risolveremo presto il problema..."
S["561121db"] = "Ce l'abbiamo fatta! Ci vediamo da Jer'kai, sopra l'accampamento dei Totem Truce."
S["5611357e"] = "Perdonami, $N! La tua morte non fa che aggiungersi al mio fallimento!"
S["56164cf5"] = "No, no, prima di essere $Gpronto:pronta; a imparare da me ti servirà MOLTO più addestramento! Va' a parlare con quel dilettante ingessato di Malcomb Wynn, quello sepolto tra i libri laggiù."
S["56223e14"] = "Lavoriamo per preservare l'equilibrio, come insegna Cenarius, $C. La sua luce è quella di un faro che ci mostra la via, e dobbiamo fare tutto quello che possiamo per custodirla."
S["5629ec01"] = "Le tue abilità in alchimia non bastano ancora per trarre vantaggio dai miei insegnamenti. Forse se torni a parlarmi più avanti..."
S["562e03d6"] = "Disperazione? Fame? Non lo faccio mica perché mi piace rapinare e ammazzare. Ho perso la casa e non avevo dove andare, e radermi la testa per adorare qualche dio del vento immaginario non mi va granché. Così sono diventato un bandito. Il resto viene da sé."
S["5634225a"] = "Sei $Guno studente:una studentessa; di scienze mediche?"
S["563a1cc1"] = "Niente da fare, temo di non poterti aiutare. Ormai sei più abile di me! Se vuoi imparare ancora, va' a parlare con l'elfo della notte Telonis, sulla Craftsmen's Terrace of Darnassus. È straordinario!"
S["563cbd61"] = "%s implora il perdono di Impsy."
S["564104c9"] = "Dev'essere importante, il tuo incarico, $C, per spingerti così a fondo nella palude..."
S["5645f141"] = "Come osi?!"
S["565252fd"] = "$N attacca! Aiuto!"
S["5653add9"] = "In questa zona vivono molte creature considerate alleate degli elfi della notte. Gli elfi hanno potuto attingere al potere racchiuso in ognuna di loro: è ora che anche all'orda venga concessa la stessa soddisfazione. Ho escogitato un modo per catturare questo potere e usarlo a nostro vantaggio.$B$BNon dubitare delle mie parole, $N. Aiutami, e vedrai che dico il vero."
S["56592f59"] = "Sono anni ormai che skycutter e traghetti non viaggiano più, e per quanto ne sappiamo non sono rimaste altre isole da cui importare merci. Eppure io sono qui... non si sa mai."
S["5660df54"] = "Molto ingegnoso, $N, il modo in cui sei $Gentrato:entrata; qui.$B$BCosa? Ti stupisce che sappia come ti chiami? Sono un demone: è il nostro mestiere. E conosco anche il tuo vero nome, perciò ti conviene comprare qualcosa di costoso."
S["56653d56"] = "Dov'è? Va' nella porta accanto, alle Arms of Legend. Lì forgia armi speciali per i grandi eroi. Rendigli onore e forse ti mostrerà come creare roba da leggenda."
S["566ca314"] = "Abbiamo fame di vendetta."
S["566dec2a"] = "Ce l'abbiamo fatta, YOUR_GENDER(amico mio;amica mia). Ricorda di trovare Terenthis e dirgli che siamo salvi. Grazie ancora."
S["56702b3b"] = "Serve una mano ferma per staccare il cuoio da una bestia uccisa."
S["56769f30"] = "Y garde bor hir uden algos me nuff nostyec lon aldonoth, far Y nagan Y borne eynes nud danagarde lo rothas melka."
S["568147b2"] = "%s solleva in alto gli oggetti che $N gli ha dato..."
S["56914528"] = "Hai portato i libri di testo? Mi fai leggere con te?"
S["569e1e85"] = "HAI FINITO LE NAVI DA MANDARE? DOV'È IL TUO CORAGGIO?"
S["56a8365e"] = "Qui nelle Badlands può fare davvero caldo. Ma almeno è un caldo secco."
S["56a90e73"] = "I druidi, sempre vigili a protezione del mondo naturale, sono guidati da Arch Druid Fandral Staghelm, che risiede nella Cenarion Enclave. Lui e gli altri istruttori dei Druidi li troverai nella parte settentrionale di Darnassus."
S["56a934b0"] = "Ultimamente i Dark Irons si fanno vedere in superficie sempre più spesso. Hanno costruito fortezze nelle Badlands e hanno mandato enormi spedizioni nelle profondità di Uldaman, in cerca di sapere antico. Hanno persino invaso la nostra patria, attaccando la nostra diga vicino al lago."
S["56ad0912"] = "Proteggi il Magistrato a ogni costo. Potrebbero arrivare da qualsiasi direzione!"
S["56add82a"] = "Ricorda, se svengo di nuovo, l'acqua che ti ha dato Spraggle mi rianimerà."
S["56b03f0f"] = "Fabbro? No, l'ultimo che avevamo è tornato a essere uno di quei senza cervello dello Scourge. Però ce n'è uno a Undercity, a sud del paese. Undercity sta sotto le Ruins of Lordaeron: furbo come nome, eh? Basta scendere con gli ascensori in fondo alle rovine e parlare con uno degli Undercity Guardians. Dovrebbero saperti indicare la strada."
S["56b58b04"] = "$GPiccolo:Piccola; $R vuole combattere contro Overlord Mok'Morokk? Io battere te! Io capo qui!"
S["56c17306"] = "Oh oh..."
S["56c9f72a"] = "Una birra Thunderbrew e un po' della cucina di Gremlock: questo sì che è un pasto come si deve. Se vuoi diventare $Gun cuoco:una cuoca;, dovresti proprio farti dare qualche lezione da lui."
S["56ca2c00"] = "Rin'wosho, ho bisogno di riparazioni."
S["56d34175"] = "Non puoi sfuggire a un guerriero dell'Orda! Prendi questo! E questo!"
S["56d5d1ef"] = "%s entra in trance..."
S["56d80dcb"] = "Grazie, gentile $Gstraniero:straniera;. Che il tuo eroismo non venga mai dimenticato."
S["56d86420"] = "Cavalieri dei lupi, al Frost Dagger Pass!"
S["56d899e5"] = "Non succederà MAI. Siamo legione. Siamo uniti. Dove sono i vostri eroi? Vol'jin siede al sicuro al fianco del giovane Capoguerra, ignaro. Zul'jin è scomparso, probabilmente morto."
S["56daa320"] = "Per quanto letali sembrino i silithid, in confronto ai loro signori Qiraji non sono che creature docili."
S["56e003c4"] = "Captain Redpath è stato ucciso!"
S["56e147dd"] = "Ascolta bene quello che ti dicono, e non avere troppa fretta né di fidarti né di diffidare: anche gli amici hanno i loro fini, $C.$B$BIl nostro grande Capoguerra lo sa. Per dimostrare che nell'Orda ci sono stregoni che non vogliono né distruggerla dall'interno né prenderne il controllo, mi sono offerto di aiutare il nostro giovane capo in tutti i modi possibili."
S["56e17f14"] = "Io... credo di aver visto abbastanza... è così estenuante..."
S["56e4976c"] = "Non è stupendo, bambini? Chiunque entri in città deve passare sotto lo sguardo vigile dei più grandi eroi delle nostre terre."
S["56e74c9c"] = "Dimmi... dimmi tutto!"
S["571168f8"] = "Onore a $N, $Guccisore:ucciditrice; di Hakkar ed $Geroe:eroina; di Azeroth!"
S["571f2e2a"] = "Comincio subito, $N."
S["57235d4a"] = "Krang Stonehoof lo trovi al centro del suo cerchio di addestramento, nell'angolo sud-est del villaggio."
S["5726c392"] = "$GBentornato:Bentornata; al più grande spettacolo di Azeroth, $Gamico mio:amica mia;! È davvero un piacere rivederti.$B$BPrego, fatti avanti e goditi ancora una volta tutto ciò che abbiamo da offrire. Guardati bene intorno, perché aggiungiamo sempre cose nuove ed emozionanti alla Darkmoon Faire! Lasciati stupire dalle meraviglie vecchie e nuove che abbiamo scoperto! Continuiamo a non badare a spese per portarti emozioni che faranno la gioia dei bambini di ogni età!"
S["5726ea30"] = "Questo è il campo di battaglia dell'Alterac Valley. Al momento le due fazioni sono in conflitto."
S["57275e2b"] = "$GStraniero:Straniera;, non ho tempo da perdere. Dimmi cosa vuoi o vattene!"
S["57326699"] = "%s fruga nel suo zaino e tira fuori le tavolette cifrate."
S["573867cc"] = "Ancora con noi, Reethe?"
S["5743da6e"] = "Guarda questo campo devastato, $R, e comprendi il potere degli elementi."
S["574afa2d"] = "Mojo dei Troll essere mojo più forte!"
S["574c9d3c"] = "Oh no! Stanno arrivando!"
S["575abe1c"] = "$GAttento:Attenta;, $N! Guarda a ovest!"
S["575f275f"] = "Non posso insegnarti la conciatura tribale, $N. Devi andare a Tanaris e trovare la casa di Narain Soothfancy. Una volta lì, consulta il libro \"Divinazione per Negati\"."
S["575fe593"] = "Sequenza di autodistruzione attivata."
S["576231f3"] = "Ciao, $N. Senza rancore, ok?"
S["57633c99"] = "Credi di aver vinto? Così facilmente? La legione ha appena iniziato la sua marcia. Gli eserciti di C'Thun raderanno al suolo questo mondo."
S["57677585"] = "Giustizia elettrica!"
S["57681a92"] = "Shirvallah, riempimi della tua FURIA!"
S["5769c601"] = "Qui dentro nessuno ha mai rubato niente. Mai, in tutta la storia di... in tutta la storia!"
S["57712b43"] = "Attenti a Marduk! Attenti, o la vostra forza appassirà."
S["57719402"] = "Ehi! Sei qui per una commissione di Tirth? Se fossi in te, gli starei il più lontano possibile! Ha il cervello in salamoia per il troppo bere, ma la sua magia è potente come sempre!"
S["57787361"] = "L'Orda ha preso la segheria!"
S["57796bde"] = "La risposta non si può vedere attraverso la distorsione fatua."
S["57883ff3"] = "Anche se in qualche modo fossi $Griuscito:riuscita; a liberarci senza sconfiggere C'Thun, useremmo tutti i nostri poteri per ricacciare la bestia nell'inferno da cui è venuta — A QUALUNQUE COSTO."
S["578a4f32"] = "Dal molo settentrionale puoi imbarcarti su una nave per Rut'theran Village e per Darnassus. Da quello meridionale puoi attraversare il Great Sea fino a Menethil Harbor, a Khaz Modan, e poi proseguire fino a Southshore, nelle Hillsbrad Foothills. Al molo occidentale trovi la nave per Stormwind.$B$BBuon viaggio!"
S["57957fc8"] = "Maestro, quando andiamo a vedere la Torre dei Maghi tutta luccicante?"
S["57a59355"] = "Non ce la faccio... la morte arriva..."
S["57ad77e6"] = "Più morbido di un elfo, più forte di un orco! Non c'è bevanda migliore in tutta Stormwind!"
S["57b063b8"] = "Cos'è questo potere che scorre dentro di me? È il potere dello sciamanesimo di cui parlava Tor'gan...?"
S["57b1cc85"] = "Le rovine di Zul'Farrak sono nell'angolo nord-occidentale del Tanaris Desert."
S["57b568a9"] = "Ah, libertà! Anche se breve, è così dolce..."
S["57b5d0a1"] = "Oh, il tram, il tram... tutti vogliono salire sul tram. Dove sono finiti i bei vecchi tempi, quando si volava su in alto nel cielo in groppa a un grifone, aggrappati disperatamente alla sella?$B$BBah! E allora vai a prendere il tram... è laggiù a Tinker Town, insieme al resto degli aggeggi gnomeschi."
S["57b6b044"] = "Grazie! Grazie, $Gsacerdote:sacerdotessa;. Ora posso affrontare quegli gnolls con il tuo potere a sostenermi!"
S["57ba1e1f"] = "E adesso come faccio a cacciare quegli sgorbi meccanici dai miei campi?"
S["57c97d6a"] = "Aiutateci, vi prego! Il Principe è impazzito!"
S["57cac875"] = "Non è che siamo maleducati, $Gstraniero:straniera;: è che qui sono tutti di corsa perché sia tutto perfetto per l'arrivo di Uther. Il Portatore di Luce non viene in città tutti i giorni."
S["57cf5870"] = "Osate interferire con la prova di questo essere? La battaglia va combattuta da soli! Soffrirete tutti per questa indiscrezione."
S["57d67146"] = "Siamo gli ultimi della razza furbolg... La tribù Timbermaw non è stata corrotta, eppure dagli estranei riceviamo la stessa ostilità; i più non credono che sia possibile... che ci siano davvero furbolgs sfuggiti alla corruzione...$B$BI miei fratelli ce l'hanno con chi si fa nemici troppo in fretta, e ora attaccano chiunque si avvicini; non si fidano di nessuno.$B$BMa se ti sforzi di mostrarti $Gpacifico:pacifica; con loro, forse potrebbero vederti come $Gun alleato:un'alleata;."
S["57e0cde5"] = "Cosa?! Come hai fatto a sfuggire al mio carcer... ehm, al servitore là fuori? Be', meglio così, direi. Ultimamente le vendite vanno un po' a rilento.$B$BAllora, quali esigenze infernali posso soddisfare, $C?"
S["57e39700"] = "Alcuni argomenti con cui posso aiutarti sono: | driver | comandi | lag | bot....zzzzzzzzttt!!"
S["57ecd5d3"] = "Perché mai le creature piccole, come i goblin, si lasciano sempre affascinare da quelle più grandi?"
S["57f5aa81"] = "Che la Luce ti purifichi dall'infezione, $Gcoraggioso:coraggiosa; $N."
S["57f6d01f"] = "Potrei schiacciarti con un solo gesto. Non farmi arrabbiare."
S["5808a829"] = "Se vuoi andare avanti, dobbiamo prima creare una prigione per contenere la bestia."
S["580ebea0"] = "Come $Gmago:maga; fai parte della ristretta cerchia di chi può evocare un portale per tornare proprio qui. Se sei $Gpronto:pronta;, posso insegnarti come."
S["580f1df2"] = "I funghi crescono sempre dove è umido: è per questo che sembrano ombrelli."
S["5810ca35"] = "Chol'aruk!"
S["582851d9"] = "Grazie per le provviste, $N!"
S["582b730e"] = "Per ora reggono. Alziamo il calore..."
S["5838eb6f"] = "Le Silverwing Sentinels saranno in debito con te, $C. Troverai Elfarran, la nostra maestra di battaglia, in Stormwind Keep, dove assiste all'udienza del re bambino. Che la Dea vegli su di te!"
S["583ad3a6"] = "Grazie a te, $N, Hendel ora è sotto la nostra custodia.$B$BL'interrogatorio va a rilento, ma ti assicuro che ci dirà tutto quello che sa.$B$BPer ora ti chiedo di avere pazienza. Se avremo bisogno del tuo aiuto, ti contatterò subito.$B$BNel frattempo goditi Theramore, ti prego: come $Gamico:amica; dell'Alleanza, ti invito a restare fra le mura della nostra città quanto vorrai."
S["58401ace"] = "Ecco fatto, $N. La Pergamena è riparata! Evviva!"
S["5846b314"] = "Intrusi!!"
S["5847f4d5"] = "Molto bene, $N. Userò l'oggetto dell'Incubo per evocare Eranikus."
S["5849fd5c"] = "Soldati di Frostwolf, venite in mio aiuto! È giunto il momento di scatenare su di loro la furia degli elementi!"
S["5852ef45"] = "Finalmente!! Posso andarmene da questa topaia."
S["58541824"] = "Ora vado a evocare il signore di questa dimora. Se cercherete udienza da lui, le vostre misere vite saranno di certo perdute! Comunque, cercate pure la sua tana, se ne avete il coraggio!"
S["5858ee76"] = "%s indica verso ovest."
S["585bf196"] = "Non mi hai deluso, questo è certo! Ora che ci siamo tolti il pensiero, puoi cominciare l'addestramento!"
S["585ef673"] = "Il cancello centrale si apre!"
S["5868aa9b"] = "Ai vostri posti! Che nessun invasore raggiunga Southshore!"
S["586b0381"] = "Quando lavori da tanto con le macchine, a volte i cuori veri te li dimentichi."
S["586c0969"] = "Che bel BOOM fanno questi fuochi d'artificio, non trovi?"
S["586f00b8"] = "Muori nel nome di Ragnaros!"
S["5870e22c"] = "Potere! Glorioso potere!"
S["58754425"] = "Il collare è davvero intriso di potere demoniaco, $N. Per il nostro popolo è un cattivo presagio."
S["588701d4"] = "Chiave... prendi la chiave... Gerstahn ha... la chiave."
S["58911d11"] = "Trova Shim'la all'ingresso sud dell'Hunter's Hall nella Valley of Honor."
S["5896bc26"] = "Lo Scourge ha fatto irruzione nel Bastione! Raddoppiate gli sforzi! Non dobbiamo fallire!"
S["58980482"] = "Hai sentito la bella notizia, $C? L'Alleanza ha completato tutte le raccolte per lo sforzo bellico! Ora aspettiamo solo che l'Orda finisca le sue. Quando avranno finito, cominceremo a spedire tutto il materiale bellico a Silithus, e da lì non dovrebbe mancare molto all'inizio della guerra di Ahn'Qiraj."
S["589d9733"] = "Certamente, $N.$B$BPer accedere agli oggetti superiori, gli avventurieri considerati osannati dall'Alba devono consegnare 12 insegne in tutto. Per quelli ancora più potenti ne servono 54 in tutto.$B$BGli sconti maggiori vanno a chi è osannato agli occhi dell'Alba."
S["58a38dc4"] = "<Il kodo emette un grugnito felice mentre ti avvicini.>"
S["58b33036"] = "Non farti prendere!"
S["58ba292f"] = "Vieni, $N! Andiamo laggiù a raccoglierlo!"
S["58bbd95a"] = "Ah, cerchi Dark Cleric Beryl. Sta al piano di sopra, nella sala di lettura della Gallows' End Tavern. Legge, prega, chissà cosa combina, e chi oserebbe chiederglielo?"
S["58bc9574"] = "Che buio..."
S["58cb2720"] = "Barattiamo, Rin'wosho. Mostrami quali merci sono disponibili!"
S["58d6318e"] = "Pamela? Ci sei, tesoro?"
S["58eb44df"] = "Ah! Passami una bella birra gelata, Belm!"
S["58f21c9c"] = "Niente prigionieri! Cacciate questi infedeli dalle nostre terre!"
S["5901e487"] = "Un'altra ondata, tenete la linea!"
S["5902c4bb"] = "Tarshaw Jaggedscar lo trovi nella caserma, sul lato est della città."
S["590dc853"] = "Yeee hawww! La flotta di Mulverick è pronta a spaccare tutto. Tutti i soldati dell'Orda abili devono chiedere un segnalatore e fare del loro dannato meglio per piantarlo, così i miei War Riders potranno puntarci sopra per l'assalto aereo."
S["590f6d50"] = "Guai. Ecco cos'era. Eh eh... scusa."
S["59119f9b"] = "Non sono qui per l'onore, $N, ma per l'orgoglio di un orco.$B$BSe non avessi respinto le avance di Belgrom, sono sicura che starei ancora a Orgrimmar, a occuparmi di faccende serie.$B$BMolte guerriere di Durotar sanno bene quanto gli piacciono le donne, ma questo non gli impedisce di fare il seduttore come al solito.$B$BCon me, però, è stato fortunato a non insistere oltre — gli sarebbero mancate ben più delle dita delle mani."
S["5913a716"] = "Davil Lightfire è stato sconfitto! Darrowshire è perduta!"
S["5919935c"] = "Comunque, sarà meglio che torni al lavoro. E a proposito, ce l'hai un po' di cibo o qualcosa di valore da farti sgraffignare? Qualche windstones, magari? Le windstones fanno sempre comodo, no?"
S["591a182e"] = "Non so ancora cosa ci sarà dentro. Prima ne devono parlare Pat Nagle e Michael Backus..."
S["59217121"] = "Il bastione sta cadendo! Bruciate le prove!"
S["59218ac7"] = "Dobbiamo colpire noi per primi. Non possiamo permetterci di ripetere gli errori del passato..."
S["59251f69"] = "Ci vorrà un po' perché si scaldi, quindi è ora di bere qualcosa! Che ne dici, Tongus?"
S["59255a58"] = "Ehi, signore... avresti un po' di tempo per darci una mano? Per favore?"
S["5925e99b"] = "Pensavano che fossi debole. Haha!!"
S["592b88f8"] = "Seguimi e ti aprirò la porta del cortile."
S["59412efa"] = "Il peso di un'ascia, il grido di battaglia degli alleati, il sangue che ti schizza in faccia. Ecco cosa brama un guerriero, $N. Con la spada conquisterò The Barrens, in nome dell'Orda."
S["594f501a"] = "Ops! Un po' fuori. Non ho neanche preso il bersaglio!"
S["595047c2"] = "Oh, l'eterna ossessione per le ricchezze materiali. Be', la fortuna ti sorride, perché la casa d'aste è nella Tradesman's Terrace."
S["59513af7"] = "Ah, beh, hai l'aria di $Gun tipo robusto:una tipa robusta;, eh? Forse mi puoi dare una mano con un paio di cose. Qui di aiuto ce n'è poco: giusto qualche apprendista alle prime armi, e quelli hanno altro per la testa."
S["59555380"] = "Violenza! Danni alla proprietà! Nessuno passa!!"
S["5955f237"] = "Guardie! Aiutatemi!"
S["59589ac1"] = "Non c'è mestiere che non abbia qualcosa da dare al tuo accampamento, perfino i pescatori!"
S["595e18cb"] = "I Tauren amano la caccia; è una passione che ha radici profonde nella nostra gente."
S["596a049e"] = "Non c'è niente di meglio di un bel fuoco scoppiettante in una notte fresca, con dei buoni amici e della birra nanica."
S["59705ccf"] = "%s ringhia e si guarda intorno con aria aggressiva"
S["5974a400"] = "La morte è vicina..."
S["597af5dc"] = "È fatta. $N, la tua armatura è pronta."
S["598cc2fc"] = "Wushoolay, the Storm Witch.$B$BA lei appartiene il potere del cielo, della pioggia e della terra spezzata. Possa ella regnare di nuovo come madre dei Gurubashi.$B$BOra Wushoolay dimora lontano da qui. Un giorno potrebbe tornare..."
S["598ebdc2"] = "Combattete fino all'ultimo respiro, fratelli e sorelle!"
S["5993f2d9"] = "Il futuro è incerto per il nostro popolo, ma c'è speranza, e abbiamo un piano..."
S["59948e56"] = "Da dove vengo io, chi apre la cella di un altro detenuto si becca una coltellata!"
S["5995e4fa"] = "Mod! Dana lo veld danagarde wirsh andovis ras danieb ko lo? Lon mod se me novas rogesh O uden dana lo agol se uden thor. Wos uden thor agol wos."
S["599793c5"] = "Il futuro è incerto, ma potrebbe trasformarsi in un'opportunità. Ritroveremo l'autosufficienza che ci guidava prima di giungere in questo luogo."
S["5998b914"] = "Sarai imprigionato e processato per tradimento, Windsor. Guarderò con gioia mentre ti dichiarano colpevole e ti condannano a morte per impiccagione..."
S["59abf3a7"] = "Beh, non so quanto riuscirò ad andare avanti in questo stato... Mi sento un po' debole..."
S["59b979ba"] = "Ma che squawk??? Squawk squawk, squawk? SQUAWK!"
S["59c2ad63"] = "Non posso permetterti di entrare nel Tempio! Devo distruggerti per il tuo bene!"
S["59c85f02"] = "Si dice che esista un'unica, leggendaria lama di Quel'Serrar, forgiata per un'entità sconosciuta dalla forza unita dei cinque Aspetti. Prima che le abominazioni di Nefarian e Deathwing si abbattessero sul nostro mondo, questi incontri degli Aspetti venivano indicati con il termine 'Prismatico'. Posso solo immaginare che la Lama Prismatica di Quel'Serrar fosse una creazione davvero gloriosa."
S["59cb8167"] = "Spero, un giorno, di forgiare armi e armature con le ossa dei miei nemici."
S["59d108be"] = "Patetico i Forsaken rammollito. Vuoi vedere il mio padrone? E sia."
S["59d29425"] = "E c'è anche la Shindigger! Sia lodata la Luce! Morivo di sete!"
S["59d94cc9"] = "Stormwind dovrebbe rappresentarci meglio. Le nostre case cadono in mano ai non morti."
S["59d9dea9"] = "Se sei $Gpronto:pronta;, allora io e Dadanga siamo pronte. Andiamo!"
S["59dcfff4"] = "Berte! Evalyn! Si sta facendo buio. Venite dentro."
S["59de7b69"] = "Ragers, riportate!"
S["59ee9ab1"] = "Blackrock Mountain sta fra la Searing Gorge, a nord, e le Burning Steppes, a sud."
S["5a06e739"] = "Voglio restare qui a riflettere su ciò che abbiamo visto. Ti prego, va' da Erelas e digli cosa abbiamo scoperto."
S["5a11b865"] = "Reginald... Io... mi dispiace."
S["5a13fdd6"] = "Interessante, molto interessante. L'hai trovato in Durotar, $N?"
S["5a181f7a"] = "Ai vostri ordini!"
S["5a2372b1"] = "%s comincia a battere più in fretta le sue enormi ali. Si prepara a spiccare il volo."
S["5a24280d"] = "INCHINATEVI ALL'ONNIPOTENTE! INCHINATEVI DAVANTI AL MIO INFERNALE DISTRU... pollo?"
S["5a281332"] = "%s prende la mira un'ultima volta..."
S["5a406d23"] = "Statistiche luccicanti!"
S["5a488dad"] = "Oh, lo farò, $Gamico mio:amica mia;. Lo farò davvero. Anche tu, stai $Gattento:attenta;."
S["5a4b3d6d"] = "Salute, $Gcittadino:cittadina;. Ti servono indicazioni?"
S["5a4c9eff"] = "Le offerte migliori di tutta Stormwind, $Gamico mio:amica mia;: di meglio non ne troverai. Allora, cosa posso fare per te?"
S["5a52d2f8"] = "Quest'anno la festa lunare è davvero magnifica!"
S["5a5394b3"] = "Capitano, eccoli! Stanno arrivando i naga!"
S["5a53bd41"] = "Cariche piazzate. Allontanati prima che esplodano!"
S["5a5492ca"] = "(Continua.)"
S["5a5a6eca"] = "Esplosione fra 10 secondi!"
S["5a638ea1"] = "Forte nel corpo e nello spirito: non c'è combinazione più potente! Trova il tuo destino con Sark Ragetotem, nell'Hunter's Hall."
S["5a662b97"] = "Fatto con maestria! Ora andiamo avanti con la tua formazione..."
S["5a6a3817"] = "Grazie ancora, $N. Questa Rare Earth sarà molto utile per i miei esperimenti."
S["5a6aad7f"] = "punto di conquista Win1"
S["5a6aad80"] = "punto di conquista Win2"
S["5a7be76c"] = "Questo posto... è maledetto.$B$BSono fuggita per un pelo, e non riesco nemmeno a pensare di tornare giù nei tunnel.$B$BMio fratello e le mie sorelle, però... Loro non hanno avuto la stessa fortuna. Sono intrappolati là dentro, in preda alla febbre per la foschia corrotta che si spande dal giardino malvagio cresciuto laggiù.$B$BTi prego, devi aiutarci."
S["5a7c2a2b"] = "Shhh! Farai scoprire il mio nascondiglio!"
S["5a7d3115"] = "Alzo la birra sperando di togliermi di torno quelli come te! Salute, $Gmascalzone buono a nulla:mascalzona buona a nulla;, $N!"
S["5a7f0e74"] = "Ben $Gtrovato:trovata;, $C. Se sei qui per affari, prendi una birra e facciamo due chiacchiere."
S["5ab38293"] = "$GUn altro:Un'altra; Segugio, mmh. Dubito che la tua abilità sia grande quanto la mia, quindi forse posso insegnarti qualche tecnica come si deve."
S["5ab5eb14"] = "Non parlarmi nella tua lingua volgare! Solo Hydraxis riesce a sopportarla."
S["5ab85b53"] = "Horgus è stato ucciso! Coraggio, difensori di Darrowshire!"
S["5abe1bf2"] = "Fatti sotto e combatti, $Gpiccolo babbeo:piccola babbea;!"
S["5abed577"] = "%s beve la cura portata da $N."
S["5ac4cd0d"] = "Quando è scoppiata la guerra sono venuto, come tanti altri, ad aiutare i miei compagni druidi.$B$BOra che i Gates of Ahn'Qiraj sono aperti, mi sono reso conto che resta ancora molto lavoro da fare. Così ho deciso di rimanere a Silithus e di fare del mio meglio per aiutare la causa, $N."
S["5ac88d3c"] = "Invasori! Invasori! Ci attaccano, ragazzi! Prendeteli!"
S["5ac98c00"] = "Schiacciateli!!!"
S["5accf6e4"] = "Col tempo potrai imparare da me... ma non adesso! Perché non cominci da Sprite Jumpsprocket, qui alla mia destra? Torna da me quando ti sarai $Gfatto:fatta; le ossa!"
S["5acd4319"] = "Desidero acquistare un'altra Elune's Candle."
S["5ad3ad18"] = "Le unità campione stanno entrando in battaglia!"
S["5ad40081"] = "Fa piacere rivederti, $N."
S["5ad53526"] = "Qui si cambiano i biglietti! Trasformali in premi! Fatti avanti!"
S["5ada9a57"] = "In questi ultimi anni ho visto succedere cose terribili ai furbolg — sono stati vittime su più fronti. Ma che fine abbia fatto questa tribù non mi è chiaro. Li ha corrotti la stessa piaga che ha colpito il Felwood? O forse sono solo arrabbiati per quello che è successo al loro popolo, un tempo pacifico, e adesso cercano di difendersi. Comunque sia, quasi tutti sembrano ostili verso chi entra nella zona."
S["5adbc954"] = "Basta con le chiacchiere. Sto morendo di fame! Ora, porta quel tuo guscio polveroso in quell'oceano e procura alla mamma qualcosa da mettere sotto i denti."
S["5adcab98"] = "$GImpostore:Impostora;! È un disonore senza pari essere $Gevocato:evocata; da $Gun moccioso:una mocciosa; come te! MUORI!"
S["5add02c6"] = "Questa è una pietra luccicante, la metto nel secchiello. Ok, me ne servono solo poche altre..."
S["5ade686f"] = "I Wind Spirits ci hanno lasciati.$B$BOra non restano che echi privi di coscienza. Ma sii $Gcauto:cauta;: questi venti non sono né buoni né gentili."
S["5ae1161e"] = "Ok, mettiamoci al lavoro!"
S["5ae39393"] = "Non manca molto. La strada principale è poco più avanti."
S["5aeacb76"] = "Tutti coloro che tradiscono Ragnaros devono morire!"
S["5af12d8a"] = "Lady Hoteshem la trovi nella sala delle udienze del Re. Può farti arrivare all'Arathi Basin, dove The League of Arathor ha bisogno di aiuto contro The Defilers."
S["5b0a00ff"] = "Un alchimista? Nessun problema, $C. A forza di lavoro e fatica, Ainethil è diventata l'alchimista più abile della Craftsmen's Terrace. Fossi in te, ci andrei di corsa. Di corsa! E ora fila!"
S["5b0e5377"] = "Il maestro d'armi"
S["5b15895a"] = "L'Iceblood Graveyard è stato preso dall'Orda!"
S["5b1797ec"] = "Ratti dappertutto. Dappertutto vedo ratti. Sempre lì a guardarmi con quei loro occhietti lucidi. Gliela farò vedere io. Gliela farò vedere a tutti!"
S["5b19a5f6"] = "NIENTE SERVIZIO!!"
S["5b21e2cd"] = "Ahimè, ho chiacchierato abbastanza. Se capiti dalle parti del porto di Valanaar, cerca la mia apprendista Ayessa Dawnsinger. Il canto lo sente ancora — anche se solo debolmente. Io sono vecchia, e gran parte del mio potere mi ha abbandonata. Ayessa è il futuro del nostro popolo e la via che ora dobbiamo percorrere per sopravvivere. Tocca a lei e ai giovani skyborne come te portare avanti le speranze della nostra gente."
S["5b238132"] = "Zug zug! Felice di aiutare!"
S["5b2ae0f4"] = "%s sputa sul cadavere del fanatico caduto."
S["5b2e43aa"] = "Sei qui per la bacchetta? O fai solo scorta di rune?$B$BUn momento! Vuoi rifilarmi un mucchio di cianfrusaglie?! Maledetta la mia infinita smania di comprare, comprare, comprare!"
S["5b3889b8"] = "Mare in tempesta là fuori. Gli spiriti del mare devono essere inquieti... hic!"
S["5b3e99a9"] = "$N reclama la fucina! Se nessuno lo contrasta, l'Orda ne prenderà il controllo in 1 minuto!"
S["5b40b3e1"] = "Oh no! È fuori controllo! Scappate!"
S["5b416664"] = "Segugio all'orizzonte, si muove a trenta piedi al secondo. L'unica domanda è se l'occhio destro o il sinistro. Proprio così, $Gragazzo:ragazza;, sono $Gbravo:brava; fino a questo punto."
S["5b461423"] = "Basta! Così le stacchi la testa!"
S["5b4ac57e"] = "Mozzafiato. Bambini, quando torneremo a scuola, ognuno di voi farà un'interrogazione orale su uno di questi personaggi leggendari."
S["5b4b5bc1"] = "Con le energie sottratte si sarebbe alimentata la magia degli Highborne, e chi stava fra le mura di Eldre'Thalas avrebbe potuto placare la sua fame di magia, infinita e sempre più grande.$B$BPassarono migliaia di anni, e il potere che serviva a tenere prigioniero Immol'thar e a mantenere la vita dentro Eldre'Thalas cominciò a cambiare. Tenere in catene Immol'thar finì per costare più dell'energia che si riusciva a sottrarre e distribuire. Quello che un tempo era un guadagno divenne una perdita."
S["5b54f859"] = "Ti sembro $Guno:una; che lancia incantesimi? Be', ho sentito dire che Cain Firesong se ne stava sul pianerottolo del piano di sopra della Gallows' End Tavern, all'estremità sud-orientale della città. Strano, starsene così fuori dalla stanza di Gretchen."
S["5b55ef9a"] = "NO! Che cosa ti hanno fatto!?"
S["5b584051"] = "I Blackfathom Deeps, lungo la Zoram Strand di Ashenvale, un tempo erano un tempio glorioso dedicato a Elune, la dea della luna degli elfi della notte. Ma la grande Frattura ha distrutto il tempio — e l'ha fatto sprofondare sotto le onde del Veiled Sea. Lì è rimasto intatto — finché, attratti dal suo antico potere — i naga e i satiri non sono emersi per scoprirne i segreti. Secondo le leggende, fra le sue rovine si è stabilita l'antica bestia, Aku'mai."
S["5b635d6a"] = "Ah. $GBenvenuto:Benvenuta;, $Gsignore:signora;!"
S["5b678711"] = "Il felhound... che creatura feroce. Fisicamente non è forte quanto un infernal, ma $Guno stregone saggio:una strega saggia; sa che la forza bruta non è sempre la risposta — se lo fosse, avresti scelto la via del guerriero, non è vero?$B$BIl felhound attinge al mana dei nemici e lo unisce alla sua rapidità per sopraffarli. La sua forza viene dall'arcano e da come lo usa per i propri scopi.$B$BSe vuoi saperne di più sugli infernals, dovresti parlare con Magaz, qui di fronte a me."
S["5b728868"] = "Sbrigati! Ti pre-e-ego, sbrigati!!"
S["5b743c96"] = "Scassinare"
S["5b743e21"] = "Quel giorno Windsor era particolarmente scontroso — e credimi, per uno come Windsor è un'impresa colossale. Continuava a ripetermi che 'qualcosa non quadra.' Be', non scherzava!$B$BEravamo nel bel mezzo di Blackrock Mountain quando ci hanno attaccati quegli animali schifosi. Gli orchi, ovvio. Mi stai a sentire, eh? Mentre ci piombavano addosso si sentivano solo grugniti e clangore d'acciaio."
S["5b75aa06"] = "Ora che questo regno meraviglioso non è più nascosto ai nostri occhi, ti divertirai a conoscere i VERI figli di Skywall..."
S["5b7720ce"] = "Per te sono la 'Gran Veggente del Cielo', $C. Ora vattene. Torna di corsa dal tuo padrone, prima che perda davvero la pazienza."
S["5b82dfdf"] = "Che istruttore cerchi?"
S["5b831027"] = "Dove sono le tue buone maniere, fratello? Diamo ai nostri ospiti il benvenuto che meritano."
S["5b84dab1"] = "$GBenvenuto:Benvenuta; al Grim Guzzler!"
S["5b8c1218"] = "Quarantadue... quarantadue... quarantadue cosa? Potrebbe essere qualsiasi cosa! Quarantadue... mmm..."
S["5b8cce52"] = "Ma certo, non c'è nessun pericolo che tutto prenda fuoco e salti in aria come un'enorme bomba all'elio. Questa bellezza ti porta a Undercity più in fretta e più al sicuro di qualsiasi nave, e la vista ti toglie davvero il fiato. A proposito di fiato, a bordo dello zeppelin è vietato fumare, e durante il viaggio è proibito lanciare incantesimi di fuoco."
S["5b8ce52a"] = "Mi ci vorrà un po' d'aiuto con questo, $N!"
S["5b9515be"] = "Tragicamente, è stata la saggezza di Thrall a suggellare, alla fine, il legame fra il signore dei demoni e i suoi servitori. E a fare da catalizzatore, unendo il signore dei demoni, le sette votate all'ombra e gli ogres, è stato il reggimento di Trebor. Il richiamo di un potere quasi illimitato e il dono di truppe d'assalto immortali a ogni capo hanno siglato il patto col sangue."
S["5b9aa6eb"] = "%s comincia a incrinarsi e a sgretolarsi."
S["5b9f5337"] = "Con le mie sorelle sono scesa dalle Stonetalon Mountains per dare pace a una tragedia di epoche passate. Purtroppo da sole non siamo abbastanza potenti per riuscirci, e ora cerchiamo mortali come te che ci aiutino.$B$BSe tu lo sei, $C, allora abbiamo molto di cui parlare. Se non lo sei, per la tua sicurezza non entrerò nei dettagli della mia missione."
S["5ba0119f"] = "Chissà se la tua bambolina sa nuotare!"
S["5ba39be0"] = "Ce l'hai fatta! Splendido! Marshal Windsor ti stava aspettando. Vuoi che gli faccia segno adesso?"
S["5ba923e4"] = "Niente ti scalda le ossa come una piccola festa Lunare!"
S["5ba965ce"] = "Questa pianta di radice sferzante è sana: l'esatto contrario della corruzione malsana che domina Felwood. Dalle radici, tenere e vigorose, nascono tuberi deliziosi, che restano a terra accanto alla pianta."
S["5bac009f"] = "Hai la mia approvazione, $N: forgi lame meglio di chiunque abbia addestrato da anni. Ma se vuoi creare una vera arma, devi parlare con Myolor Sunderfury. Quel nano ti metterà sulla strada giusta."
S["5bb092a3"] = "Su questo continente per ora abbiamo solo un piccolo punto d'appoggio, ma gli umani non potranno respingerci per sempre. E allora la pagheranno per averci fatto schiavi: per il loro tradimento, gli taglieremo quelle lingue bugiarde."
S["5bb6ab1e"] = "Eccomi. E sono pronto a riunirmi..."
S["5bb88629"] = "A Stormwind l'istruttore di ingegneria è un geniale gnomo di nome Lilliam Sparkspindle. Lo trovi in fondo al Dwarven District."
S["5bc3871e"] = "$GSignore:Signora;, sì, $Gsignore:signora;! Private Porter a rapporto, pronto a darti una mano nella raccolta di medium leather. La Guerra di Ahn'Qiraj è vicina e dobbiamo farci trovare il più preparati possibile.$B$BCome vedi, abbiamo messo insieme un certo numero di pezzi di medium leather: il mio compito è arrivare al totale stabilito."
S["5bd42275"] = "Grazie! La battaglia per Darrowshire mi ha condannato, ma tu mi hai liberato!"
S["5be95b8b"] = "Ne sai più di me, però ho sentito dire che Old Man Heming a Booty Bay ha delle copie di \"Il Persico e Tu\". Di sicuro ti aiuterà a migliorare."
S["5bebd2b0"] = "%s esamina minuziosamente il grande vaso."
S["5beea8a2"] = "Una piega interessante degli eventi."
S["5bf662ae"] = "AAAAAAAAAAAAAAAARGH!"
S["5bfc73d6"] = "Dove sono i tuoi dei adesso? DOVE, SERVITORE?"
S["5c003707"] = "Sono proprio curioso di vedere cosa farà questo campione d'acqua!"
S["5c035a41"] = "Anche il più debole, Valley of Trials lo temprerà fino a farne un guerriero degno di unirsi all'Orda. Chi non supererà le sue prove verrà lasciato a cuocere sotto il sole cocente del deserto."
S["5c0d18aa"] = "Come puoi amarmi, Annalise? Guardami. Non sono più l'uomo che conoscevi."
S["5c0fdaa1"] = "Circolare, $Gcittadino:cittadina;. Qui non c'è niente da vedere."
S["5c1248c6"] = "Oggetti durevoli e ben fatti in vendita vicino alla Collina! Accorrete, accorrete tutti! Il tempo stringe, quindi sbrigatevi."
S["5c16639a"] = "Dimmi quando sarai $Gpronto:pronta; ad ascoltare la storia."
S["5c1d4115"] = "I non morti strisciano ovunque. Dov'è la Stormwind Army?"
S["5c210b5b"] = "Sento che qualcosa di malvagio sta per accadere..."
S["5c243085"] = "Eccoli, arrivano! Difendetevi!"
S["5c24ecaa"] = "Allora sei $Gtornato:tornata; ad aiutare Kum'isha, $R? Non preoccuparti, la fitta che senti alla bocca dello stomaco è solo la tua forza di volontà che crolla.$B$BPer fortuna, per questa raccolta non ti servirà la forza di volontà. Sono $Gcerto:certa; che apprezzerai i ninnoli che ti farò trovare quando tornerai con l'oggetto."
S["5c323e01"] = "Che sfortuna; pare che abbiamo raccolto tutte le bende di telamagica necessarie. Forse puoi andare a venderle alla casa d'aste? Ma prima di andare, fa' $Gil bravo ragazzo:la brava ragazza; e chiedi agli altri raccoglitori presenti. Potrebbero avere una commissione per te."
S["5c348877"] = "TENETE LA LINEA! NON FATE PASSARE NIENTE!"
S["5c3b4ac0"] = "Sii guarita, sacerdotessa."
S["5c41aa2d"] = "Ok, voglio un bel combattimento leale. Ricordatevi di tenere la spada alta e lo scudo pronto."
S["5c4c2752"] = "Sei $Gappena uscito:appena uscita; da un dungeon? E a me hai portato qualcosa?"
S["5c56180b"] = "Nel cristallo vedi riflettersi grandi gallerie e corridoi cavernosi. Riconosci il posto: è il Molten Core."
S["5c56527f"] = "N nei dath ni ash dieb su ash nor, $N. BELORE!"
S["5c5819ee"] = "%s russa rumorosamente e si accoccola accanto ad A-Me 01."
S["5c5884a2"] = "Buongiorno, signore. Ti stringerei la mano, ma come vedi ho da fare. Posso aiutarti?"
S["5c5e19d9"] = "Il potere di Elune te lo impone! Il potere di Elune te lo impone!$B$BOra va'! Cerca Jandria nella sala centrale del Tempio della Luna, nella parte sud di Darnassus!"
S["5c6407e0"] = "Grazie, $N. Mobiliterò subito la mia gente!"
S["5c64d04a"] = "L'Eternal Flame è tornata ad ardere. Ben fatto, $N."
S["5c680ecf"] = "Laurena è l'Alta Sacerdotessa di Stormwind: la trovi nella Catheral of Light, in Cathedral Square."
S["5c6f9e96"] = "È giunto il momento, fratelli. Non dobbiamo permettere al nemico di avanzare attraverso il Frost Dagger Pass. Alcuni di noi periranno di certo, ma qualcuno di voi si tirerebbe indietro davanti a questo dovere? A questo onore? Avanti! Per l'Orda!"
S["5c701d80"] = "Io sono Balgaras the Foul. E tu, $N, stai per diventare nient'altro che cenere e polvere."
S["5c7e9312"] = "Da quando mio marito è partito per il fronte, la mia forza è stata Helene, qui presente. Con il suo cuore gentile e la sua spada affilata mi ha aiutata a superare tanti momenti difficili. Non so cosa avrei fatto senza di lei."
S["5c87a603"] = "Sono qui!"
S["5c8b790f"] = "Tu andare Royal Quarter, tu vedere Sir Malory Wheeler. Lui fare paura."
S["5c9629b2"] = "La mia famiglia vanta la più bella collezione di gioielli e oggetti d'arte di tutta la nobiltà di Stormwind!$B$BE vogliamo sempre arricchirla..."
S["5c970a3a"] = "Questo deserto essere mio!"
S["5c9ca73b"] = "Se cerchi un altro addestramento, sopravvaluti le mie capacità. Parla con Telonis, laggiù: può aiutarti."
S["5ca646e0"] = "Il primo è un pegno primordiale, da prendere ai luogotenenti Hakkari più potenti: Jin'do e il Signore del Sangue.$B$BIl secondo è una punctured voodoo doll. Le trovi nei cumuli di rifiuti sparsi per questo posto immondo: cerca dentro i mucchi Hoodoo stregati.$B$BPortami queste cose e creerò per te un potente incantamento!"
S["5cb5d782"] = "Temo che stia arrivando qualcosa di oscuro."
S["5cb7e9a4"] = "Parla con Grezz Ragefist nell'Hall of the Brave, nella Valley of Honor, e metti una buona parola per me!"
S["5cb8998b"] = "Fai come vuoi, vuol dire che non hai poi così fame. La prossima volta il cibo te lo prepari da $Gsolo:sola;!"
S["5cc25142"] = "Buongiorno, $Gragazzo:ragazza;! Magari potresti darmi una mano con qualche faccenda da sbrigare."
S["5cc68dd1"] = "Oltre ad addestrarti, se lo desideri, ho il potere di cancellare dalla tua mente la conoscenza dei tuoi talenti. Sappi però che ogni volta che ti sottoponi a questa procedura, eseguirla diventa più difficile, e quindi più costoso."
S["5cca1b5c"] = "Sei $Gvenuto:venuta; ad addestrarti, per poi insegnare ai tuoi animali quello che impari?"
S["5cdadfd1"] = "Ora sono abbastanza $Glontano:lontana;... così non posso vedere il barile. Avvelena pure!"
S["5cdba0d2"] = "La Dama Oscura ha detto che in questa guerra la nostra arma più potente sarà la conoscenza."
S["5cde9e1f"] = "I capitani dell'Orda e dell'Alleanza sono scesi in campo. Il nostro Captain Balinda Stonehearth guida le forze degli Stormpike dallo Stonehearth Outpost, e il nemico, Captain Galvangar, abbaia ordini dall'interno dell'Iceblood Garrison.$B$BAlla battaglia!"
S["5ce339c4"] = "Ce n'è uno fuori dalla Bank of Orgrimmar, al centro della Valley of Strength."
S["5ce6112a"] = "La costa di Darkshore sarà anche più pericolosa di quella di Teldrassil, ma per molti pescatori qui c'è da guadagnare."
S["5ce69462"] = "Throm-Ka, $C. Oggi sono di cattivo umore: se non puoi aiutarmi, preferirei restare da sola."
S["5ce9b579"] = "Elfi in Warsong Gulch fare rumore croccante: tu schiacciare loro bene. Parla con Kurden Bloodclaw in Royal Quarter."
S["5cf2c249"] = "Le ricerche a Theramore sono un lavoro interessante, ma in questa città trovare un letto morbido è proprio difficile!"
S["5cf70a59"] = "Siamo arrivati?"
S["5cf7c929"] = "Proteggere la raccolta di legname dell'Orda qui ad Ashenvale non è un compito facile, ma davanti a una battaglia non ci siamo mai tirati indietro! Gli elfi della notte e i loro alleati cadranno!"
S["5cf920cd"] = "Non dimenticherrrò quello che hai fatto...$B$BTi prego, lasssciamiii..."
S["5cfa21ee"] = "Io sono Dran Droffers, e questo qui è quel tonto di mio figlio Malton. Cerchi roba di recupero, o ne hai da vendere? Allora è con noi che devi parlare!"
S["5cfb8b6d"] = "Rend, figlio di Blackhand: Impotente capotribù del clan Blackrock. Non c'è bastardo più testardo di lui.$B$BAlla fine della seconda Guerra, Rend e il fratello Maim sono fuggiti a cercare rifugio nella fortezza montana di Blackrock Spire, e proprio lì Rend si è proclamato Capoguerra dell'indebolito clan Blackrock."
S["5cff236b"] = "Unità allarme-bomba 2600 guasta. Forzatura autodistruzione [ATTIVA]. Raffreddamento [ATTIVO]."
S["5d0138b0"] = "Hai ancora delle lezioni da imparare prima che io possa iniziare il tuo addestramento. Nel frattempo, forse Vhan, a Thunder Bluff, può aiutarti."
S["5d06f1ff"] = "Non te lo direi nemmeno se lo sapessi! Perché appena lo so, me ne vado lontano da questi cristalli..."
S["5d09c9a3"] = "Per me una pinta di birra Dark Iron. Oh, non sei la cameriera?"
S["5d0b23b3"] = "Abbiamo metà della silitite che ci serve. Possiamo farcela!"
S["5d0b7e92"] = "So molte cose, $Gstraniero:straniera;, ma tu ne sai quanto me. Si sa che gli incantatori che vogliono affinare ancora le proprie abilità vanno alla Tower of Azora, dove vive un'artigiana di nome Kitta Firewind."
S["5d21b762"] = "Sono $Gliberato:liberata; grazie a te! Vendicami!"
S["5d298f25"] = "Non ho più niente da insegnarti. Va', e che la Madre Terra ti benedica. Nelle botteghe sul lato nord-occidentale dell'altopiano centrale di Thunder Bluff troverai il tauren Tarn: cercalo. Lascia che sia la sua saggezza a guidarti."
S["5d3ae092"] = "Vincono i blu! Preparatevi per il prossimo round."
S["5d3b2bc8"] = "Ben trovati, viaggiatori di Duskwood! Le mie incredibili merci sono in vendita per poco tempo a Darkshire. Affrettatevi!"
S["5d421c8f"] = "Ora che la via è libera..."
S["5d46b6d4"] = "Le Eastern Plaguelands sono sotto attacco in questo momento?"
S["5d4ce424"] = "Non è quello che Keever sperava. Keever potrebbe aver aggiunto troppa earthroot. Vediamo se il secondo siero farà quello che mi serve."
S["5d5794b8"] = "Niente storie, $N. Nella Searing Gorge non ti faccio entrare, non c'è verso. Impossibile. Non se ne parla. Quante volte te lo devo ripetere — non posso farti entrare! Non la parli la lingua comune? Sei $Gun orco travestito:un'orchessa travestita;? N-O. NO!$B$BSe faccio entrare te, poi devo far entrare tutti. In un attimo vorranno entrare i tuoi amici più stretti, poi i loro parenti lontani, poi gli amici di quelli, e via così. L'ultima volta che è successo... beh, meglio non parlarne."
S["5d5cb3e0"] = "L'odio di Nefarius mi ha reso più forte che mai! Dovevate fuggire finché potevate, mortali! La furia di Roccianera mi scorre nelle vene!"
S["5d6227a1"] = "Winterhoof? Mi hanno detto che se la spassa a Booty Bay."
S["5d6829af"] = "Non mi pagano abbastanza per queste stupidaggini!"
S["5d768026"] = "Noi di Refuge Pointe teniamo uno dei pochi lembi di territorio di Stromgarde rimasti negli Arathi Highlands. E stiamo perdendo terreno...$B$BSe hai notizie per me, spero che siano buone."
S["5d7b3a76"] = "La fine si avvicina! Proprio mentre parliamo gli ultimi rifornimenti vengono spediti a Silithus e dovrebbero arrivare entro un giorno. Una volta lì sono sicuro che verrà tutto radunato in fretta, e poi aspetteremo che si suoni il gong alle porte di Ahn'Qiraj per cominciare la guerra. Non vedo l'ora di analizzare se i nostri preparativi faranno la differenza."
S["5d7f3fe1"] = "Chi controlla l'Icewing Bunker?"
S["5d854cb6"] = "Prendi questo, bestia!"
S["5d8d7153"] = "Un'auto più veloce di quel rottame goblin sgangherato saprebbe progettarla mio figlio!"
S["5dba3867"] = "Ehi, che vuoi?"
S["5dba92b0"] = "Ecco fatto. Tutto finito!"
S["5dbb9f41"] = "Le vostre magie meschine non sono una sfida per la potenza dello Scourge!"
S["5dceec2b"] = "Cyndra non è frizzante come le sue pozioni, ma ha modi gentili, quelli giusti per insegnare il mestiere. La trovi subito a est della Locanda di Dolanaar."
S["5dd8d7e6"] = "Sì, puoi, Okla. Ma non allontanarti troppo da casa."
S["5dd9e547"] = "In quali altri posti stiamo combattendo lo Scourge?"
S["5de01821"] = "Sangue e ossa!"
S["5de73c9f"] = "Se qualcuno ha rimesso insieme lo scettro magico delle sabbie, allora la guerra con gli insetti ci sarà presto. Non vedo l'ora, $C! Gli ultimi beni di guerra sono in viaggio verso Silithus e dovrebbero arrivare entro un giorno. Va' e porta onore all'Orda!"
S["5de7b668"] = "È ora che cominci a imparare cose che vanno oltre quello che so io! Vai da Lilliam Sparkspindle, è lì davanti alla tenda: ti metterà sulla strada giusta!"
S["5deb1555"] = "Sulla superficie della sfera c'è impressa una grande impronta di mano umanoide. Sembra che la maneggino e la tocchino di continuo, eppure la sfera resta intatta."
S["5ded4a49"] = "Proprio così. The Scarlet Crusade è un'aberrazione dell'Order of the Silver Hand.$B$BDevi credermi, $R: Taelan è un brav'uomo. Ha bisogno di una guida, ha bisogno di ricordare... ricordare cosa vuol dire essere nobile e onorevole. Lo so che in cuor suo sa di sbagliare. Lo aiuterai? Lo aiuterai a ricordare?"
S["5ded9dac"] = "%s grida aiuto."
S["5defbc27"] = "Usurpatori! Gnomeregan è mia!"
S["5df2bb12"] = "Questa è un'attrezzatura speciale! Non maneggiarla alla leggera, e ovviamente non provare a farla funzionare se hai bevuto troppo di quel volatile rum che, a quanto sento, ti piace tanto...$B$BA proposito... non è che per caso ne hai un po', di quella robaccia?"
S["5df4123d"] = "Il Kel'thuzad fa del Patchwerk il suo avatar di guerra!"
S["5df9b91b"] = "Soldati Fontane, MacDugal, Wilcott..."
S["5e02b0bf"] = "Tu cerca in The Apothecarium. Lì dove esercitano Doctor Herbert Halsey e Doctor Marsh."
S["5e03108a"] = "Ah, $N! Sei proprio la persona che speravo di vedere! Abbiamo abbastanza provviste per lanciare un assalto via terra contro l'Orda! Field Marshal Teravaine aspetta ordini nel Field of Strife...$B$BSei $Gun veterano coraggioso che ha dimostrato:una veterana coraggiosa che ha dimostrato; il suo valore più e più volte. Vuoi consegnare tu gli ordini a Teravaine?"
S["5e1a03ce"] = "Ti serve un vero maestro che ti insegni! Va' da Daryl Stack a Tarren Mill e abbraccia il tuo destino!"
S["5e1b1848"] = "Nessuno sfida i nomadi Wastewander — nemmeno i polli robot! ALL'ATTACCO!"
S["5e2e2d58"] = "Bene, bene. Ora inchinatevi l'uno all'altro."
S["5e2ecf7b"] = "Ehi, Harlan. Ecco un carico di stoffa lavorata a maglia per te."
S["5e31f43e"] = "Quanto al tuo avvertimento — non preoccuparti. Le nostre truppe conoscono tutte la catena di comando. Combattiamo uniti. Speriamo che anche le tue truppe se lo ricordino..."
S["5e335e82"] = "Benvenuti, tutti quanti, al più grande spettacolo di tutta Azeroth... la Darkmoon Faire! Vi aspettano avventure ed emozioni, non siate timidi! Qui ci sono misteri e premi per grandi e piccini, basta prenderli. E non dimenticate di parlare con il professore delle Carte di Darkmoon che avete trovato durante i vostri viaggi!"
S["5e39f9c2"] = "Ah, come dice il titolo, sono $Gun assassino:un'assassina; della Scarlet Crusade. Di giorno stermino bersagli ad alta priorità, di notte sto nella discoteca di Gadgetzan. Ballare è la mia vera vocazione. Assassinare mi serve solo a pagare le bollette."
S["5e3ab436"] = "Cerco delle guardie del corpo disposte a proteggere la Carovana Gizelton. Siamo fermi sulla strada a est del Kormek's Hut, a nord del Villaggio dei Kolkar Centaur."
S["5e470166"] = "Basta così. Addio, Belathaan e... chiunque tu sia."
S["5e470d4b"] = "L'attacco dello Scourge contro la mia corte è stato respinto. Potete tornare alle vostre faccende."
S["5e5344f7"] = "%s emette una risata sinistra."
S["5e56d227"] = "Fate come vi ho insegnato!"
S["5e69cef5"] = "Ah, il vischio..."
S["5e6a7f15"] = "Cosa state facendo laggiù?"
S["5e6b560c"] = "Godetevi la vostra piccola vittoria finché potete, mortali. Non fermerà il nostro trionfo finale su questa terra!"
S["5e70841e"] = "Facciamo un tentativo..."
S["5e73e146"] = "Tu presto essere $Gmorto:morta;!"
S["5e7504e0"] = "Miserabile patetico!"
S["5e7c295a"] = "Lee ne ha pescate di cose strane, su al Crystal Lake. Mi ha raccontato di una maschera bizzarra che ha tirato su qualche mese fa. Se vuoi sapere come la penso, quella sera aveva solo bevuto un bicchiere di troppo al Lion's Pride."
S["5e7d5658"] = "Scusaci per il ritardo, Ayessa."
S["5e8420b5"] = "Ti sei $Gfatto:fatta; strada... ora è il momento di vedere il capo. Va' da Josef e digli che sei $Gpronto:pronta;."
S["5e896600"] = "Scatena la tua rabbia!"
S["5e91e23f"] = "Il mio odio è forte <sbuffo>, ma questo è il momento giusto per raccontarti una storia, skyborne.$B$BTanto tempo fa c'è stata una battaglia fra dèi. Sconfitto nella War of the Ancients, Agamaggan, il nostro grande dio cinghiale, è caduto sulla terra: il suo sangue è piovuto giù e le sue ossa sono state fatte a pezzi. <sbuffo>$B$BDove il suo sangue ha toccato il suolo sono spuntate dalla terra enormi spine, e il suo teschio adorna una delle caverne a sud."
S["5e95f53c"] = "Quello che è successo è colpa quasi tutta dei Windshapers. Col loro rifiuto di cambiare, ci hanno reso più difficile metterci in salvo dal pericolo che corriamo. Parlano per assoluti e prendono per fatti supposizioni e speranze superstiziose.$B$BSai chi altro ragiona solo per assoluti? Gli Al'Aketh.$B$BQuanto a me, non intendo permettere che un'adesione cieca a credenze pericolose condanni il nostro popolo. Se non fosse per la minaccia del culto, farei marciare i nostri maghi dall'altra parte di Valanaar e spazzerei via i Windshapers."
S["5e97dc51"] = "Ora ripuliamo il resto della spazzatura, uomini!"
S["5e9db671"] = "Abbiamo vinto $2219W battaglie contro lo Scourge. Preparati, $N, perché questa guerra è lontana dall'essere finita."
S["5ea34977"] = "Sono $Gcerto:certa; che a Darnassus ci sia un Sarto che potrebbe addestrarti. Quando arrivi, chiedi a una delle Sentinelle di Darnassus dove trovare un Sarto."
S["5ea88603"] = "Se vuoi trovare Grumnus, la prima cosa da fare è andare a Ironforge. Vai proprio al centro della città e cerca la Great Forge: dovresti trovarlo lì."
S["5ea97ee2"] = "Questa terra gelata basterà per cominciare. Venite da me, mortali, e vi darò una morte rapida e dolorosa."
S["5eadd11d"] = "Muln Earthfury mi ha raccontato molto dei Windshapers e sono orgoglioso di aprire le terre, e i cieli, di Mulgore al tuo popolo.$B$BI tauren e gli Skyborne sono entrambi figli di questa terra. Kalimdor. $B$BSpero che il tuo popolo possa trovare ciò che sta cercando qui e che tu possa salvare la tua patria. Nel frattempo, spero che tu possa imparare di più sulla terra che i tuoi antenati chiamavano casa.$B$BPer favore, fai come se fossi a casa qui a Thunder Bluff, e che la Madre Terra benedica il tuo viaggio."
S["5eb033b4"] = "Lo Shadowfang Keep è nel sud della Silverpine, appena a nord di Pyrewood Village."
S["5eb430d4"] = "L'Iceblood Tower protegge l'Iceblood Garrison da sud-est.$B$BÈ controllata dall'Orda."
S["5ebadb7b"] = "Le erbe costano così tanto! Un piccolo extra mi fa sempre comodo, se capisci cosa intendo. Dai una mano a un goblin?"
S["5ec0a820"] = "Saluti, $C.$B$BLe Sentinelle laggiù mi hanno lasciato dividere il loro accampamento, a patto che promettessi di non portare guai — di sicuro capisci quanto serva la diplomazia, qui, vero?$B$BSono qui per indagare sui turbamenti della terra e, visto che ne guadagna anche la loro causa, hanno convenuto che la mia presenza non potrebbe che giovare alla fragile alleanza fra tutte le razze di Azeroth. Se vuoi aiutarmi te ne sarei grato, ma in ogni caso cerca di non creare problemi."
S["5ec19deb"] = "%s si inginocchia per raccogliere i frammenti dello scettro in frantumi."
S["5ec3f69a"] = "Wow! Questi barili sono pieni di roba forte! Mi fa volare!"
S["5ec686af"] = "Mi è arrivato un aggiornamento giusto un attimo fa. A quanto pare, una parte del light leather che ci serve ce l'abbiamo già. Per il resto, il rapporto dice che abbiamo raccolto una parte del medium leather richiesto e della nostra quota di thick leather."
S["5ec73638"] = "La guerra ha un prezzo, $C... un prezzo a cui spesso nessuno pensa. Sono gli orfani — bambini che hanno perso i genitori nei troppi conflitti che infuriano su Azeroth. Chi non ha nessun altro a cui rivolgersi spesso viene a vivere qui, finché non è abbastanza grande da cavarsela da solo.$B$BOgni anno, per una settimana in Primavera, l'Alleanza si dedica a restituire qualcosa a questi innocenti. Si chiama Settimana dei Bambini."
S["5eca3ad6"] = "Hai buone ragioni per sentirti $Gsicuro:sicura; di te, $Gviaggiatore:viaggiatrice;. Ora la tua vera formazione può cominciare!"
S["5eca5a3e"] = "Senti il potere dei Blackrock Orcs!"
S["5ed07acf"] = "Mi sembra di fare cento volte al giorno tutta la strada fino al pozzo per prendere altra acqua. Nessun rispetto per gli anziani, ve lo dico io."
S["5edc8dfe"] = "Ora possediamo la saggezza dei Winterax, $N. Questo potere può essere tuo per un breve periodo, se lo desideri."
S["5ee28034"] = "Michelle Belle ha un modo straordinario di trattare i pazienti! Quello forse non te lo può insegnare, ma il First Aid come si deve te lo insegna di sicuro. Per ora alloggia alla Lion's Pride Inn."
S["5ee6872b"] = "Ai suoi tempi Jocaste era la più grande fra i Cacciatori. Oggi la trovi alla Cenarion Enclave, dove insegna a chi muove i primi passi sulla via del Cacciatore."
S["5ee71278"] = "Dammene un altro, Langston."
S["5eec027d"] = "Me Thor Aetwinter wirsh thor ko wos."
S["5eee79af"] = "Sei uno stolto che presto perderà la vita. No?"
S["5ef0ff4b"] = "Il Signore del Ghiaccio divorerà l'intero esercito Stormpike!"
S["5ef6116a"] = "Un Guardian of Icecrown entra nello scontro!"
S["5efb099a"] = "L'Orda ha preso la fattoria!"
S["5efcdc33"] = "Sembra che ormai siamo fuori pericolo, eh? Chissà a cosa serve questo..."
S["5efeb066"] = "%s sente il richiamo della battaglia e si alza per servire il suo padrone."
S["5f03c533"] = "Vuoi imparare a usare un'arma nuova, eh? Be', allora dovresti parlare con Bixi o Buliwyf, laggiù all'armeria Timberline Arms, $Gragazzo:ragazza;. Quei due di armi se ne intendono, dalle asce agli... ehm... zweihanders."
S["5f063a87"] = "All'estremità nord-occidentale del paese troverai Carolai Anise che cerca di far saltare in aria casa sua. Perché non vai a vedere se puoi darle una mano?"
S["5f0c0855"] = "Che il salasso abbia inizio!"
S["5f18b68d"] = "BASTA — è finita adesso! Voi stolti andrete ad aggiungervi alla mia collezione di ossa!"
S["5f1f94dc"] = "Eccellente, ti sei $Gdimostrato:dimostrata; $Gdegno:degna;! E adesso avanti con la prossima fase della tua istruzione..."
S["5f227a1b"] = "$GAttento:Attenta; a dove metti i piedi. Questa bestiolina ne ha già passate abbastanza.$B$BL'avranno anche abbandonata credendola morta, ma presto comincerà l'addestramento. Quando sarà domata e temprata dagli scontri, la cavalcherò in battaglia: saremo una cosa sola e semineremo il terrore tra i nostri nemici."
S["5f2c4547"] = "%s si ritrae per il dolore mentre il Judgement of Righteousness lo investe!"
S["5f301e81"] = "Perché cucinare, se in bocca ti sa tutto di cenere? Sempre che una bocca tu ce l'abbia ancora. E va bene: vai a Undercity, a sud di Brill, e chiedi a un Undercity Guardian altre indicazioni per trovare il loro Istruttore di Cucina. Per arrivarci puoi prendere gli ascensori che scendono dal retro delle Ruins of Lordaeron."
S["5f31170e"] = "Qualche anno fa tutte le isole skyborne sono diventate instabili e hanno preso ad allontanarsi l'una dall'altra. Come se non bastasse, ora cominciano a staccarsi grossi pezzi di Zephras. È difficile immaginare la propria casa che cade nel cielo, eppure ora questa è la mia realtà."
S["5f36ed21"] = "%s brontola."
S["5f374738"] = "Ne tu awak."
S["5f424729"] = "Tu vuoi quale campo di battaglia?"
S["5f43b84c"] = "Le guardie di Theramore sono i soldati migliori che l'Alleanza abbia di stanza a Kalimdor. Anche così lontano da casa, il nostro dovere è far rispettare le leggi dell'Alleanza."
S["5f499ea2"] = "Belathaan... pensavo avessimo concordato di incontrarci da soli? Mi spiacerebbe pensare che tu intendessi tendermi un'imboscata qui, all'ombra del mio santuario."
S["5f502639"] = "Il Southshore Crier si porta la mano alla nuca e spalanca gli occhi."
S["5f50b738"] = "Va bene, ragazzi. Indietro. Avete fatto abbastanza. Ci vediamo dopo."
S["5f5181d5"] = "I grifoni sono pronti a colpire, $N! Devi prendere questo segnale e piantarlo nel cratere occidentale del campo di battaglia centrale.$B$BFallo e la battaglia sarà nostra!"
S["5f52a558"] = "Addestrarti, io? Ma dai — lo sappiamo tutti e due che non posso. È colpa di tutto questo insegnamento, capisci: le mie capacità ne risentono. Se vuoi un addestramento, va' da Doctor Herbert Halsey, un Forsaken nell'Apothecarium of the Undercity."
S["5f55ddb6"] = "%s è molto più vulnerabile ai tuoi attacchi. La Maledizione Vile funziona!"
S["5f5e0525"] = "Il corpo di %s cade a terra, un mucchio senza vita."
S["5f61411d"] = "L'Orda ha preso la miniera!"
S["5f635d3a"] = "Combattete, e oggi vinceremo!"
S["5f77c4c6"] = "Cenere alla cenere!"
S["5f78db82"] = "Kel'Thuzad si è dato un gran da fare per rimettere insieme il bastone. Un tempo i pezzi erano sparsi per il mondo intero, da Kalimdor ai South Seas. A un certo punto ne avevo venti io $Gstesso:stessa; — finché i tirapiedi di Kel'Thuzad non me li hanno rubati. Per questo sono qui."
S["5f79fca4"] = "Dunque, i fragili membri dei vivi hanno qualche dente, dopotutto. Prendetevi pure questo posto, per ora. Torneremo, forti il doppio, e le vostre misere forze cadranno!"
S["5f7a0566"] = "$GBenvenuto:Benvenuta; nella Bank of Valanaar. Se lo desideri, qui possiamo custodire i tuoi averi e i tuoi oggetti di valore. Vuoi accedere alla tua cassetta di sicurezza?"
S["5f8099f1"] = "Sei $Gpronto:pronta; a cominciare?"
S["5f8164aa"] = "Aspetta, $N! Creare una ricompensa di qualità così squisita richiede tempo."
S["5f91166c"] = "Se non servirai il mio Padrone con la tua spada e con ciò che sai dei suoi nemici..."
S["5f97d32c"] = "%s chiama aiuto!"
S["5fa83031"] = "Sono $Gun venditore:una venditrice; di stoffe, e questo è il mio saluto predefinito."
S["5fadec97"] = "Il mio esilio è finito! Che il sangue scorra!"
S["5fb017c2"] = "I pezzi di ricambio sono difficili da trovare di questi tempi, visto quanti pochi costrutti intatti ci restano sull'isola."
S["5fb34950"] = "Mi dispiace, ma hai già imparato tutto quello che so. Però l'elfo della notte Faldron potrebbe offrirti un ulteriore addestramento. Cercalo nella Craftsmen's Terrace of Darnassus."
S["5fb93400"] = "Dubito che tu abbia avuto molte occasioni di vedere una creatura simile. Questi destrieri demoniaci renderanno i tuoi viaggi molto più rapidi facendoti da cavalcatura, finché riuscirai a controllarli. Però sono difficili da domare, quindi assicurati di essere pronto prima di provarci."
S["5fc91f17"] = "Bene, adesso andiamocene da qui!"
S["5fca3ce1"] = "Come mai sei $Gvenuto:venuta; qui, $C?"
S["5fcbb5c0"] = "Signore Hir'eek, concedimi ali di vendetta!"
S["5fd88fba"] = "Quasi fatto..."
S["5fdf6078"] = "Frantuma l'artiglio morto e contorto."
S["5feff415"] = "L'Iceblood Tower è stata conquistata dall'Orda!"
S["5ff255ae"] = "Proteggere padrone!"
S["5ff3e0cf"] = "Bene, torno al lavoro. Però che bella pausetta, e bere Thunder Ale è sempre un piacere!"
S["5ff40a82"] = "La città in rovina di Stratholme sta nelle Eastern Plaguelands, a nord della Plaguewood."
S["5ff56340"] = "Sei qui per aiutare con la consegna? Miran è quasi pronto."
S["5ff73379"] = "Se tu essere qui per questo, io fare quel che posso per addestrare te nelle vie dei sacerdoti."
S["5ff89622"] = "I War Riders sono pronti! Soldati dell'Orda, ho bisogno del vostro aiuto."
S["600f7806"] = "Anaya...? Mi ingannano gli occhi? Sei davvero tu?"
S["60148cb2"] = "Ehilà, $Gsignore:signorina;. Io farei attenzione a dove metti i piedi da queste parti, ho perso una bomba travestita da mouse e non riesco proprio a trovarla."
S["601bb4ad"] = "Gloria e sangue per gli Old Gods!"
S["601f171e"] = "Abbiamo molte provviste, ma ce ne servono ancora parecchie per mandare un assalto via terra nel Field of Strife."
S["6020d13f"] = "La tua sorte è gettata, $C. Nelle prossime ore sentirai lo spirito in sintonia con la tua vera natura. Ma fa' attenzione: la sorte — e il destino — non sono mai chiari come potresti pensare.$B$BSe vuoi un piccolo assaggio di qualcosa su cui riflettere per il futuro, dimmelo pure. Sarò felice di metterti la sorte per iscritto, purché tu abbia spazio nell'inventario: viene dall'intuito che hai mostrato rispondendo alle mie domande."
S["6023ab99"] = "L'Abyssal Council non tollera l'inganno! Senti la nostra ira, piccolo $R!"
S["6027892c"] = "Minacce vane, Elaadrin. Qualunque cosa mi accada ora, la mia grande opera è compiuta. Considerati fortunato a trovarti qui, nell'occhio del ciclone, a vedere i frutti del nostro lavoro."
S["60285b96"] = "Proprio così. Muori come il cane che sei."
S["60353267"] = "%s abbassa la voce fino a un sussurro."
S["60380c7f"] = "Ci siamo appena liberati della Burning Legion e tu sei già di nuovo qui a trafficare con i demoni? Cerca la Darkfire Enclave nella caverna sotterranea che chiamano Cleft of Shadow. Troverai un tunnel che ci scende da The Drag."
S["60385779"] = "Non ti avrà mandato da me Mot? Sa bene che non sei ancora in grado di capire quello che ti insegnerei. Va' da mio figlio Mot, qui fuori, e finisci l'addestramento con lui."
S["60404a92"] = "La Luce sia con te, $C. Cosa posso fare per te?"
S["6044e3df"] = "Ehi Ehi Ehi! Sono qui a promuovere un favoloso torneo di pesca a Stranglethorn, ma devi essere $Gtosto:tosta; abbastanza da sopravvivere laggiù, e saper pescare bene quanto quelle acque richiedono.$B$B Ripassa più tardi, quando sarai più $Gqualificato:qualificata;!"
S["604501ca"] = "Allora cerchi Bowen Brisboise. Lo troverai a casa sua, al Cold Hearth Manor, appena passato il ponte, a sud-ovest di Brill."
S["6046e8c0"] = "%s sembra non riuscire più a lanciare incantesimi. La Maledizione Vile funziona!"
S["6052a123"] = "Dov'è la Mia Pancetta?"
S["606971dd"] = "$GBenvenuto:Benvenuta;! $GBenvenuto:Benvenuta; al Yebb Neblegear's Darkmoon Zoo Bizarre — uno Scrigno di Leggende Viventi e Stranezze Mitiche! Goditi la visita, $Gamico:amica;!$B$BMa $Gattento:attenta; a cosa tocchi! Qui sono in mostra manufatti e bestie, tanto terribili quanto divine! Potrebbero bruciare la mano indiscreta allo spettatore troppo curioso..."
S["606a5bd3"] = "I miei poteri ritornano!"
S["60790135"] = "Andrà meglio la prossima volta, $N."
S["607bed92"] = "Andiamo avanti!"
S["60919def"] = "Stanotte le stelle saranno perfette!"
S["609d4647"] = "Puoi togliermi di dosso $Gquesto:questa; $N?"
S["609dbfb3"] = "Oh, di sicuro parli della Stormwind Counting House. Appena entri a Stormwind, è poco lontano dai cancelli."
S["60a33e6d"] = "Questo frutteto è ora sterile e senza vita come il mio guscio in putrefazione. Un tempo questi alberi fiorivano di frutti, ora c'è solo marciume."
S["60a3e32c"] = "Phalanx, credo che tu debba dare una lezione a questa persona."
S["60a4bf06"] = "Sono in grande debito con te, $C. Forse posso aiutare la tua causa."
S["60a53f34"] = "Le nostre raccolte sono tutte completate, $C. Quello che abbiamo radunato è in viaggio verso Cenarion Hold, in Silithus, e il resto non dovrebbe metterci più di qualche giorno ad arrivare. A quel punto la Guerra di Ahn'Qiraj potrà cominciare, appena qualcuno di coraggioso e folle suonerà il gong proprio fuori dai cancelli, laggiù."
S["60a990b5"] = "Lo Shaman Commander non va preso alla leggera, $R."
S["60a9f570"] = "Saluti, sono Baros Alexston, Architetto Cittadino di Stormwind."
S["60ad4348"] = "Resta anche dopo i fuochi d'artificio. Prendi un calice e brinda ai tuoi amici tosti!"
S["60b235fe"] = "Ora prova tu."
S["60b41887"] = "Ecco, l'ho preso!"
S["60b6302d"] = "$GZitto:Zitta;! Non lo vedi che il maestro sta parlando?"
S["60bb8fc7"] = "Dammi qua l'hippogryph hatchling!"
S["60bb97c5"] = "MUORI, INSETTO!"
S["60c21864"] = "Mi sembri $Gsicuro:sicura; di te. Non ti dispiacerà mettere alla prova le tue abilità, no?"
S["60c29634"] = "Il tuo cuore esploderà."
S["60c44c73"] = "La mamma ha detto di non arrampicarsi più lassù. Adesso lo dico!"
S["60c9bc74"] = "Alanna passa gran parte della giornata all'Oracle Glade, a esercitare il suo mestiere. Se vuoi imparare la professione di Incantatore, è lì che devi andare a cercarla."
S["60d3fd96"] = "ALT! Ci sono stati... segnalazioni... di un... disordine."
S["60d5138f"] = "Hai fatto bene a venire. La mia saggezza sarà tua."
S["60dbdaae"] = "%s sniffa la dream dust."
S["60dd9d5d"] = "Che la tua anima bruci nell'angoscia, Isillien! Luce, dammi la forza di combattere questo mostro."
S["60e2a938"] = "%s alza le spalle."
S["60ed9b9d"] = "Il peggio deve ancora venire, $R."
S["60ef4803"] = "Se ti serve una Locanda, il posto giusto è la Stonefire Inn. La trovi subito a sinistra dell'ingresso di Ironforge quando arrivi, o a destra quando te ne vai.$B$BOh, e se passi da quelle parti, digli di tenermi pronto un boccale."
S["60f60e4e"] = "Credo che voi bambini siate il nostro futuro..."
S["610166d4"] = "SANGUE E OSSAAAAA! CHOL'ARUK HA FAME!"
S["61055f4e"] = "Cerca Austil de Mon nella sala da pranzo principale della Gallows' End Tavern, che sta sul margine sud-est di Brill."
S["61065dc1"] = "Ma cosa state colpendo?! Non ho mai visto un branco di carne marcia più penoso di voi!"
S["6117f333"] = "Non posso, Vaelastrasz! Ci sarà pure un modo per guarirti!"
S["611850bf"] = "Tra i colori, un sentiero.$B$BAttraversa in un lampo, nella luce.$B$BDall'acqua, emergi."
S["61224146"] = "Mojka, coprimi tu! Ho delle faccende da sbrigare."
S["61293a4c"] = "%s fissa l'arcanite sulla bardatura a colpi di martello."
S["61310ee1"] = "Ehi, Stone, hai sentito del motore a vapore nuovo che usa il vecchio Tonkrend?"
S["61314953"] = "Forse avrei fatto meglio a comprarne un po' da Faruza?"
S["61358ccb"] = "Squadra blu, Vincitrice!"
S["613cc7ad"] = "Stressati dagli studi di magia? Venite a rilassarvi al Blue Recluse!"
S["61490fd5"] = "Attenzione! Mi attaccano!"
S["614c0d6b"] = "Puoi andare $Gfiero:fiera;, $C, del fatto che l'Alleanza ha portato a termine tutti i compiti di raccolta che le erano stati assegnati. I prodotti finiti sono stati immagazzinati e conservati, e i nostri artigiani sono al lavoro per trasformare quelle materie prime in materiale bellico, che verrà spedito a Silithus non appena l'Orda avrà finito la sua raccolta."
S["6166b4fb"] = "La Stonewrought Dam sarà distrutta! Lunga vita a Ragnaros!"
S["617505f8"] = "Credevi davvero di potermi sconfiggere? I tuoi amici ti raggiungeranno presto, Taelan."
S["617ad7c6"] = "Ehi, $C. Ho parlato con tutti qui intorno, e pare che abbiamo tutta la roba che l'Alleanza vuole per la guerra. Però quell'antipatico ambasciatore orco ha detto che l'Orda sta ancora raccogliendo, quindi abbiamo un po' di tempo prima di dover spedire tutta questa roba a Silithus."
S["61837dc0"] = "Ti stavo aspettando, $N. Contento che tu ce l'abbia fatta. Hai il carico?"
S["61859a1c"] = "La prima uccisione è mia! Qualcuno vuole scommettere?"
S["6186b757"] = "*coff* chi va là? *coff*"
S["6189b12e"] = "Da quel che ho capito, $Gcaro:cara;, è stato raccolto tutto e l'ultimo materiale viene preparato e spedito a Cenarion Hold. Le ultime spedizioni dovrebbero arrivare entro pochi giorni. Quando il nostro equipaggiamento e le nostre forze saranno tutti lì, chi porta lo Scepter of the Shifting Sands potrà suonare il gong vicino ad Ahn'Qiraj per aprire i cancelli. Allora comincerà la guerra."
S["61900469"] = "Antichi, sorgete!"
S["619236b5"] = "Chi devo uccidere? Indicami solo da che parte andare, Comandante."
S["61962308"] = "Altro?"
S["619ace1c"] = "Grazie a tutti. Farò ritorno tra circa una settimana."
S["619c79cd"] = "Grazie! E quando preparo le mie bevande... non dire a nessuno di cosa sono fatte!"
S["61a98971"] = "È una battaglia fredda e sanguinosa quella che combattiamo nell'Alterac Valley. È perfetta."
S["61b4260f"] = "Pretendo che tutti i miei studenti dimostrino la loro dedizione. Ora tocca a te..."
S["61ba39c0"] = "E ora, per la prossima gara, la macchina sarà ancora più VELOCE di prima!"
S["61bcab29"] = "Faresti meglio a trattenermi, o $N assaggerà un po' di botte da galera."
S["61c27f7e"] = "La Tower Point East controlla il passo tra il Field of Strife e i territori dell'Orda a sud.$B$BÈ controllata dall'Orda. L'East Frostwolf Tower protegge la porta tra il Frostwolf Village e la Frostwolf Keep.$B$BÈ controllata dall'Orda."
S["61d06cb3"] = "%s sembra essere stato ostacolato. Si prende qualche istante per riprendersi dalle ferite."
S["61d6a9d1"] = "%s lancia un grido acuto."
S["61e65919"] = "Finché non avrai imparato le basi, le mie tecniche non puoi studiarle. Se ti interessa l'addestramento, parla con Kamari."
S["61ec3581"] = "Un tempo gioiello del nord di Lordaeron, la città di Stratholme è il luogo in cui Prince Arthas si è rivoltato contro il suo mentore, Uther Lightbringer, e ha massacrato centinaia dei suoi stessi sudditi che si credeva avessero contratto la piaga della non morte. Poco dopo Arthas si è arreso a The Lich King. Oggi fra le rovine della città vivono lo Scourge non morto — guidato dal potente lich Kel'Thuzad — e un contingente di Scarlet Crusaders agli ordini di Grand Crusader Dathrohan. Le due fazioni si combattono senza sosta e con violenza."
S["61ef7618"] = "Cos'è quello all'orizzonte? Una nave nemica, senza dubbio! Fuoco!"
S["61eff1cc"] = "Se è mio destino cadere, allora il mio ultimo respiro servirà a trascinarti con me!"
S["61f0e49b"] = "La prossima volta che vedo uno di voi che non lavora, gli faccio tagliare la testa da Buzzer!"
S["61f3c91a"] = "Bel tentativo, ma prima di addestrarti con me ti serve un po' più di esperienza! Torna in trincea!"
S["61fa42e5"] = "Uno di questi giorni lo affogo in quella tunica blu. E pure tutte le sue scope."
S["62013f65"] = "%s lancia un ruggito tremendo, allertando i nemici vicini!"
S["620c4eb1"] = "Ma se lo stabilizziamo con un filo d'ancoraggio nel giusto nodo d'energia, dovrebbe funzionare."
S["620d0222"] = "Tu, in armonia con la natura, e solo le tue abilità per sopravvivere. È così che la Madre Terra voleva che fosse. Dovrai cercare Bale sull'Hunter Rise."
S["620eed28"] = "Cerchi Kardris Dreamseeker. La trovi con gli altri sciamani nella sala d'ingresso della Thrall's Fortress, in Valley of Wisdom."
S["6223e405"] = "La cassetta della posta"
S["622e06ef"] = "Siamo il braccio della Sua volontà. E ridurremo i Suoi nemici in polvere!"
S["62340c34"] = "Parla con me, $N — se sei $Gdisposto:disposta;, il Cenarion Circle accetterebbe con entusiasmo la tua generosa offerta di aiuto. La minaccia della Felvine di Eldre'Thalas è davvero terribile."
S["623ef5e1"] = "Mmm... dopo aver consegnato questo, penso che farò un salto in quel negozio di formaggi per uno spuntino."
S["623f53ba"] = "Ecco, così dovrebbe andare..."
S["6241717c"] = "Darkmoon Dogs appena tolti dalla griglia. Vieni a prenderli finché sono caldi!"
S["624628f7"] = "Se dovessi cadere, prendi la mia borsa. Assicurati che arrivi all'Alto Generale."
S["624abb5c"] = "Cosa? No, le armature non le riparo. Everlook è un miglio circa a nord, sorella.$B$BE adesso compra qualcosa, o sparisci prima che evochi il mio stregone a occuparsi di te!"
S["62525c57"] = "Risorgo dalla tomba per prendermi la mia vendetta!"
S["6253c07e"] = "Non si fermerà davanti a nulla pur di raggiungere la forma fisica di Malfurion. Non deve succedere... Dobbiamo tenere occupata la bestia abbastanza a lungo da permettere a Tyrande di arrivare."
S["625a9947"] = "Sei $Garrivato:arrivata; troppo tardi, $Gsciamano:sciamana;. La tempesta cresce e non puoi fare niente per fermarla!"
S["626297a3"] = "Venite, miseri mortali. Venite ad affrontare la vostra fine. I segreti di Ahn'Qiraj moriranno con Roman'khan!"
S["626ccebf"] = "Pele'keiki sa, sembra impossibile anche a lui, ma noi abbiamo tutto il firebloom che l'Orda vuole per la guerra. Se tu non ti senti troppo pigr$Go:a;, Pele'keiki pensa che tu puoi aiutare gli altri qui. Loro di sicuro hanno tante cose che vogliono che tu prenda per loro."
S["626ff988"] = "Destatevi, o servi! Difendete i Dischi!"
S["6270b8b1"] = "Mi dispiace, ma adesso sono un po' preso: sto facendo dei ferri di cavallo per Verner Osgood a Lakeshire."
S["6275a280"] = "%s consegna lo Scepter of the Shifting Sands a Fandral Staghelm."
S["627b65da"] = "Lo sfidante è a terra!"
S["627c9ce7"] = "Così siamo $Gun figlio:una figlia; della natura, eh? Allora non cercare oltre: il pozzo lunare è a The Park."
S["6286f0a7"] = "$GBenvenuto:Benvenuta; allo Steelgrill's Depot!"
S["628703fb"] = "Shenthul, ho perso il mio fischietto e non ho più razzi di segnalazione. Aiutami, ti prego!"
S["628935fc"] = "In questa trincea c'è del Blueleaf Tuber! È come una vena d'oro che aspetta solo di essere scavata, te lo dico io!"
S["628d6343"] = "Dalle ceneri dell'uomo di vimini in fiamme si sprigiona un potere magico. Te le sei già passate sul viso."
S["628dbbfd"] = "Ora sì che facciamo progressi!"
S["628eace1"] = "Credo che hai sbagliato lavoro, iniziato. A Kel'Thuzad non gli servono fioraie..."
S["628fac4a"] = "%s lancia un ruggito di sfida!"
S["6294efab"] = "Dobbiamo fermare questi malvagi!"
S["62a832ab"] = "%s si fa scrocchiare le nocche."
S["62aaf5d5"] = "Il Crossroads sembrerà anche il centro di ogni attività in The Barrens, ma io preferisco la quiete di Camp Taurajo. Dove devo mandarti?"
S["62c98297"] = "Sono $Gun artigiano:un'artigiana; di una certa fama, $C. Se ho i materiali giusti, posso creare un'armatura chiamata Dreamwalker. I druidi — e persino alcuni sciamani — la cercano per le sue proprietà magiche. Ti interessa?"
S["62cc8028"] = "Tutti voi avete combattuto con forza e valore. Mi rende $Gorgoglioso:orgogliosa; vedere i guerrieri che siete diventati."
S["62d1d21a"] = "Ti sei $Gguadagnato:guadagnata; un po' di fiducia fra i Nightclaw, $C. Come ricompensa non abbiamo molto da offrirti, ma dalle rovine di Ban'aethal siamo riusciti a recuperare alcuni progetti di creazione.$B$BIn molti ritenevano i magifabbri di Ban'aethal i migliori artigiani di tutte le Skyborne Isles. I Nightclaw però sono naturalisti, non artigiani, e a noi questi documenti servono a poco.$B$BContinua a dimostrarti $Gun alleato prezioso:un'alleata preziosa; e metterò questi segreti a tua disposizione."
S["62d8a168"] = "La tua bestiola è meravigliosa, Gerard, ma secondo me le serve un collare col campanello."
S["62de9048"] = "È stato raccolto tutto e viene mandato a Silithus, $C. L'ultimo carico dovrebbe arrivare lì entro un giorno. Posso solo sperare che, dopo che il gong sarà suonato e le porte aperte, i nostri sforzi qui faranno la differenza e salveranno molte vite."
S["62e1a13c"] = "Sei $Gvenuto:venuta; a farti addestrare nelle arti del combattimento armato?"
S["62e1c46f"] = "E questa è Corma Villard. Due settimane sposata, sua moglie è stata rapita dalla sicurezza di Menethil Harbor."
S["62e27c9b"] = "Le nostre pillas! Qualcuno ha rubato le nostre pillas!"
S["62e3481e"] = "Già, e che campo di battaglia cerchi?"
S["62edc0fd"] = "La città di Lakeshire è laggiù, oltre il ponte. Ma la pace, lì, non la troverai. Se sei qui in cerca d'avventura, $Gragazzo:ragazza;, dammi retta — l'hai trovata!"
S["62f404ef"] = "C'è un potere incredibile negli spiriti, o \"muisek\", delle creature che combattiamo.$B$BGuarda dentro di te; impara a usare il potere del tuo spirito e diventerai più forte di quanto tu abbia mai immaginato."
S["62fe0588"] = "Signorsì, signora! Mi è stato ordinato di riferire che l'Alleanza ha raccolto tutto il materiale bellico necessario. Mi è stato comunicato che stiamo solo aspettando che l'Orda finisca la sua parte, e poi tutto verrà spedito a Silithus. Grazie, signora!"
S["630ee340"] = "Saluti. Desideri apprendere l'arte della guerra?"
S["6315e850"] = "Noi diventiamo più forti, mentre i nostri nemici sono circondati da nemici e indeboliti da attacchi continui."
S["633cdf95"] = "Non fare male a Betsy, $Gcattivone:cattivona;!"
S["63442423"] = "Io non sono qui a fare da maestro ai poppanti appena usciti dalla culla, e tu l'abilità che pretendo dai miei allievi non ce l'hai neanche lontanamente. Anzi, sei $Gun:una; $Gragazzo:ragazza; che fa pena, e mi faresti un favore a non startene lì a blaterarmi addosso."
S["634b8a71"] = "Sono $Gstanco:stanca; di queste sciocchezze! Preparati a morire, $R!"
S["635672c2"] = "Oggi la Luce è con noi!"
S["63567acb"] = "Hamhock in guai! Hamhock avere bisogno aiuto!"
S["63662b37"] = "La vendetta sarà nostra!"
S["636ef1ce"] = "Arrivo, Frostwolf, e stavolta le fiamme le sentirete eccome!"
S["63716fbc"] = "Troggs! Giuro che gli dei li hanno messi su questa terra solo per tormentarmi! Si scende di quattro pollici nelle miniere e poi si torna indietro di due piedi per colpa dei troggs!"
S["6377e6cf"] = "Sono qui! Venite a prendermi, femminucce dell'alleanza!"
S["637b4b7a"] = "Gli spiriti di Silithus ci chiamano, $N. La terra piange: ha una storia triste da raccontare..."
S["637bbba0"] = "Questo ponte non lo finiranno mai, vero?"
S["637f63a9"] = "Combattiamo al fianco dell'Alleanza, $R. Un male tanto antico che il mondo se n'è dimenticato vuole inghiottirci tutti; prima a Kalimdor, poi nel resto di Azeroth. Lo muove l'odio per tutto ciò che è nato dai grandi Plasmatori: Gli eterni Titani.$B$BSolo noi sbarriamo la strada agli eserciti di C'Thun. Colpiremo per primi e abbatteremo le forze di Ahn'Qiraj. Che tutta Azeroth tremi davanti alla potenza unita dell'Orda e dell'Alleanza.$B$BLa guerra ha bisogno di te!"
S["638b16cb"] = "Sarà sommerso di lavoro al Monastero. Però dovrebbe essere già tornato."
S["638ff174"] = "Che Elune sia con te, $C."
S["6390f81e"] = "Be', nell'Hall of Mysteries, a nord dei cancelli di Ironforge, troverai di sicuro chi ti addestri nelle arti magiche. Juli Stormkettle è sempre lì, china su un libro."
S["63945104"] = "Tu ci terrai al sicuro dalla padrona malvagia, sì!"
S["6395d166"] = "Il Capitano è occupato al momento. Sta studiando le mappe degli alveari sotterranei dei silithid che abbiamo ottenuto di recente. Resta con noi se vuoi dare una mano, uscirà da un momento all'altro."
S["63975007"] = "Soldati Horus, Tilling, Rockwell..."
S["6397ad78"] = "I furbolg Winterfall che vivono qui a Winterspring erano nostri alleati, un tempo... Ma un giorno è cambiato tutto.$B$BSpinti dalle strane richieste del loro gran capo, si sono messi ad attaccare chiunque incontrassero, anche la nostra tribù. Ora se ne stanno per conto loro..."
S["639a107a"] = "Mh mh. Empi stare in War Quarter, attorno a edificio principale, su anello esterno di città."
S["63a3a2ae"] = "Cos'è la Brotherhood of the Light? Be'... In fondo siamo tutti membri dell'Argent Dawn — membri dell'Argent Dawn, però, senza i freni della morale, del senso di colpa e delle inutili emozioni umane. Siamo come la Scarlet Crusade, ma senza la stupidità, senza la mancanza di guida e senza il fanatismo cieco.$B$BSe Scarlet Commander ti dice il contrario, non dargli retta.$B$BE non far sapere a Tyrosus che l'ho detto... Se scoppiasse una rissa e dovessi mutilarlo brutalmente, sarebbe proprio un peccato."
S["63ae0db8"] = "Vince il rosso! Preparatevi per il prossimo round."
S["63b483c0"] = "Lo Stonehearth Graveyard è sotto attacco! Se nessuno interviene, l'Alleanza lo conquisterà!"
S["63b958e1"] = "I segni su questa tavoletta mostrano antichi diagrammi e contengono terribili parole di potere.$B$BCredi che sia una ricetta alchemica, ma va oltre le tue capacità..."
S["63c17b77"] = "Davvero straordinario, Gerard. Come ci sei riuscito?"
S["63c2a56c"] = "C'erano ladri dappertutto!$B$BÈ stato orribile. La grotta ci è venuta giù addosso. Credo che siano morti tutti quelli della compagnia mineraria, anche mio fratello, il Caposquadra."
S["63c766a0"] = "Glyx e io abbiamo un accordo: lui mi rifornisce e io lo faccio ricco. Sul serio! Quello che quel pirata mi chiede per un misero sacchetto di kingsblood sgualcito... roba da far piangere un goblin adulto."
S["63cf0ceb"] = "Quando ho cominciato a preparare pozioni avrò rotto centinaia di fiale. Nelle mie mani goffe il vetro era così fragile. Spero che tu sia più $Gcauto:cauta; di quanto non fossi io."
S["63d4f8e2"] = "C-ciao. Scusami, è che di solito quelli come te scappano da me."
S["63df1bb1"] = "Incredibile: le tue pozioni rivelano una conoscenza pari alla mia. Io non posso addestrarti oltre, ma va' a parlare con l'orco Rogvar of Stonard, nella Swamp of Sorrows: è noto per i suoi esperimenti all'avanguardia."
S["63e40a1f"] = "Edward. Tyler. Preparatevi alla vostra prima prova."
S["63e929e4"] = "Morte ai Frostwolf!"
S["64015be9"] = "In attesa di ordini, $Gsignore:signora;. Al vostro comando, scatenerò l'inferno su di loro!"
S["64076287"] = "Esatto, ehm, $Gragazzo:ragazza;, tutto il materiale bellico viene trasportato a Silithus e l'ultimo carico dovrebbe arrivare entro un giorno. Dopo di che dovremo solo aspettare di vedere chi manderà avanti $Gun eroe:un'eroina; a ricomporre lo Scepter of the Shifting Sands e a suonare il gong sulla Scarab Dais. Solo allora comincerà la guerra, con l'apertura delle porte di Ahn'Qiraj."
S["641ea994"] = "Ce l'abbiamo fatta, $Gragazzo:ragazza;! L'Alleanza e l'Orda hanno finito di raccogliere tutto quello che, secondo noi, ci servirà per la Guerra di Ahn'Qiraj. Gli ultimi rifornimenti stanno viaggiando proprio ora verso Cenarion Hold, in Silithus, e fra qualche giorno sarà arrivato tutto. Poi $Gqualche eroe coraggioso:qualche eroina coraggiosa; dovrà suonare The Scarab Gong con lo Scepter of the Shifting Sands per aprire le porte di Ahn'Qiraj. E quando si apriranno, comincerà la guerra!"
S["6426e547"] = "Se ti interessa la sartoria, da Vizzklick trovi di sicuro tutto il materiale che ti serve. Guardati intorno, $N, e se vuoi comprare qualcosa fammelo sapere!"
S["642a467e"] = "Lieto di conoscerti. Posso fare qualcosa per te?"
S["6432531d"] = "Maestro dei Grifoni"
S["64391b07"] = "Spero che fosse un pesce!"
S["643a1c98"] = "%s piange."
S["6443f6f4"] = "Finito lo spettacolo pirotecnico tireranno fuori dei calici, e potremo fare un brindisi!"
S["6444507a"] = "Yip! Io uccidere!"
S["6446bb05"] = "Prima che ti insegni un'abilità di equitazione, $C, devi essere $Gosannato:osannata; presso i Forsaken of the Undercity."
S["64482693"] = "Rimetti a posto tutte le statue di questa stanza."
S["644aed8f"] = "Ottimo lavoro, $Gsoldato:soldatessa;. Ora accendiamo i fuochi e sfidiamo la loro ira!"
S["6455f261"] = "Hai visto Petra o Dadanga da queste parti?"
S["64597ec6"] = "Grazie! Grazie, $Gsacerdote:sacerdotessa;. Ora posso affrontare quei wendigo con la Luce dalla mia parte!"
S["645d2b12"] = "Questo non promette niente di buono. Mandate degli esploratori a raccogliere altre informazioni e restate all'erta."
S["645ed15f"] = "Benvenuta, sorella mia. Se sei qui per addestrarti, lo farò con piacere.$B$BCome ci ha insegnato Cenarius, siamo i custodi dell'equilibrio, ora e per sempre. Non dimenticarlo mai."
S["645ff47f"] = "Questa è la primissima cosa che dico al giocatore. Urrà!"
S["646265ad"] = "Se non sei qui per una faccenda delle O.L.V., temo di non avere molto tempo per chiacchierare. Però, se vuoi dare una mano in città, ti metto al lavoro.$B$BOh, cosa vuol dire O.L.V.? Village Live Operations, naturalmente. Nemmeno i paesi di frontiera come questo si gestiscono da soli. Fra incidenti gravi, interruzioni impreviste dell'energia eolica e infestazioni di insetti, mandare avanti questo posto non è uno scherzo."
S["6464fed0"] = "<Sulla targhetta del meccanostrider c'è scritto:$B$BHyper-lite Veridian Fuseblazer 800, ora più veloce e più furiosissimo, con fotosensori dinamici!>"
S["646a13d1"] = "%s continua a cercare e mette altri teschi nella sua cassa."
S["64715daf"] = "Mostrate il vostro coraggio, uomini e donne di Azeroth! Respingete gli invasori Qiraji!"
S["647d885f"] = "Grazie, Omarion. In questo giorno hai incassato un colpo fatale per la squadra."
S["647e7c2d"] = "%s percepisce la tua presenza e apre un portale fatuo!"
S["647f2a2e"] = "%s getta la spada nella pozza poco profonda."
S["647ff980"] = "Certo che posso mostrarti dov'è Myolor. Proprio lì, vicino all'incudine della Great Forge: è lì che lavora. Ascolta bene le sue parole, $Gragazzo:ragazza;: Myolor è tra i più abili che ci siano."
S["64810c6c"] = "Non disturbarmi, che sto facendo festa..."
S["64846b69"] = "Bleah... neanche se fossi l'ultimo orco di Kalimdor, Lunk."
S["64866c87"] = "Avevo tutto! Avevo tutto e poi l'ho perso. Perso... tutto sparito... come... la mia testa. La mia testa è come... il formaggio. Mi piace il formaggio."
S["648f25ec"] = "Mi spiace, $Gamico:amica;, ma non venderò i miei raptors a chi non ha dimostrato di essere amichevole con la tribù Darkspear. Quando prenderai posizione e ti mostrerai almeno amichevole con noi, allora i miei raptors saranno a tua disposizione."
S["649f658c"] = "Io sono Vol'jin, dei Darkspear. Sei $Gamico:amica;, o $Gnemico:nemica;?"
S["64a53ce9"] = "Non provare a teletrasportarti in una città dei tuoi nemici, non funzionerà — qui saremo pure tutti amici, ma a casa i vecchi rancori restano..."
S["64c4e3bb"] = "Al tuo tocco, la macchina prende vita."
S["64c4e436"] = "Sì? Ho parecchio da fare."
S["64c86cd2"] = "Saluti! Se vuoi consultare gli schemi di ingegneria gnomesca, prepara la gnome engineer membership card per la verifica."
S["64d19b58"] = "Per un Sulfuron Ingot sono $Gautorizzato:autorizzata; a darti una copia dei progetti per forgiare un martello Sulfuron.$B$BOra, $Gun avventuriero:un'avventuriera; come te probabilmente starà pensando: «E che me ne faccio di un martello così, se quello che ho già è di gran lunga superiore?»$B$BBeh, lascia che te lo dica, $Gragazzino:signorinella;: non c'è niente di più superiore di quello che può diventare il martello Sulfuron!"
S["64d27c45"] = "Dicono che Cairne in persona viva qui. Appena avrò finito di creare un dono degno di lui, andrò a cercarlo: forse avrà qualche parola di saggezza per me."
S["64d3209d"] = "Giri il corpo e vedi sull'orchessa defunta i segni di lame e incantesimi — l'armatura quasi del tutto distrutta, i capelli incollati al viso.$B$BPer come te l'ha descritta Mankrik, non hai dubbi: era sua moglie.$B$BLa notizia lo addolorerà, ma sei $Gsicuro:sicura; che la verità debba saperla."
S["64dc698a"] = "No! Non puoi essere più forte dei Selvalercia! No!!"
S["64e3967a"] = "La mia programmazione mi impedisce di abbassare il prezzo di qualsiasi articolo."
S["64e9d928"] = "Frugate tra queste macerie."
S["64ec647d"] = "I vivi sono qui!"
S["64edd023"] = "Donate agli enti di beneficenza che aiutano le vittime di questi tempi difficili! Per favore."
S["64f22de5"] = "La Stormpike Aid Station è stata conquistata dall'Alleanza!"
S["65062218"] = "Belm dice di pagare il conto, o ti spacca la faccia."
S["650e91d9"] = "Questa terra è contaminata. Bisogna invocare Ivus!"
S["65171e89"] = "Venite! Venite tutti! Gli elisir di Perelli vi abbaglieranno!"
S["651b6bf0"] = "Qualcuno vuole fare una pausa? Be', peccato! Al lavoro, zucconi!"
S["6521d97d"] = "È fatta. Ho la tua arma, $N."
S["652254eb"] = "Non si possono insegnare trucchi nuovi a un cane vecchio: almeno, così mi ha detto qualcuno una volta. Per tua fortuna, ho scoperto che non è vero.$B$BPerò gli animali tendono a diventare resistenti alla tecnica, e per tenerli contenti ogni volta mi serve più cibo. Vuol dire che più volte disaddestro lo stesso animale, più soldi mi dovrai.$B$BAllora, vuoi che cominci a disaddestrarlo?"
S["65270200"] = "Anche fra fredde mura di pietra come quelle che proteggono questa città si possono trovare pace e tranquillità. Anzi, puoi trovarle ovunque tu sia... basta che cerchi questo equilibrio dentro di te."
S["652c994c"] = "Solo carne e ossa. I mortali sono prede così facili..."
S["65397a36"] = "Da qui in poi se ne occuperà l'SI:7. La forgia e la nave da guerra che hai strappato ai Defias hanno un valore strategico, e ne prendiamo noi il controllo."
S["65484fed"] = "Fra la luce e il buio c'è l'ombra... e le ombre hanno poteri che ancora non hai visto."
S["654ee91a"] = "Abbi cura di te, Antonio. Ci vediamo fra un'altra settimana."
S["6554c6a3"] = "Lascia che prenda un po' d'acqua per il reagente d'inchiostro."
S["65606eda"] = "Preso uno! Vediamo se qualche guardia ha fame. Vieni, Zanna!"
S["656f8889"] = "Maginor dice che intrecciare flussi alternati di energia positiva crea in realtà un flusso molto più stabile."
S["65732425"] = "Bene, bene. Pare che abbiamo un po' di concorrenza. Prendeteli, ragazzi!"
S["65798479"] = "Salute, $C. Hai già parlato con Fahrad?"
S["6579de74"] = "Icebane Gauntlets."
S["657d6d01"] = "Ti aspettavo, $N. Sei $Gpronto:pronta; ad aiutarci ad Arathi Basin?"
S["657e64ba"] = "Ecco del cibo per te, Trok! Trok? Perché corri in giro come un umano spaventato?"
S["658c75e1"] = "Non così in fretta, $Gsignore:signora;... Non darò le redini di un possente destriero ariete a qualcuno che non abbia dimostrato di essere alleato dei nani di Ironforge. Quando sarai $Griconosciuto:riconosciuta; come $Gamico:amica; di Ironforge, ti mostrerò volentieri le varietà di arieti che ho in vendita."
S["6591c145"] = "La Madre Terra custodisce molti segreti, e Brek Stonehoof può aiutarti a scoprirne qualcuno. Lo trovi sul rialzo più basso, alla Stonehoof Geology."
S["65944409"] = "Sono tornato!"
S["659e86a4"] = "Il mio scettro tornerà di nuovo intero!"
S["65a105f9"] = "Nella nostra cultura niente deve andare sprecato. Quando siamo costretti a uccidere una creatura, ne prendiamo quello che possiamo, perché il suo sacrificio non sia stato vano.$B$BSe vuoi imparare a scuoiare come si deve una bestia uccisa, cerca Eladriel nella Craftsmen's Terrace."
S["65a5ae68"] = "Ah! Non potete nemmeno immaginare quanto siano inutili i vostri sforzi."
S["65b2ddfc"] = "È opera dei migliori artigiani di tutta Teldrassil, ed è stato portato a mano da Kalimdor ad Azeroth, segno dell'alleanza che cresce fra il popolo del Great Tree e gli umani di questa terra. Se ti serve qualcosa, non hai che da chiedere."
S["65b4ba85"] = "Bagnatevi nel potere del Capoguerra! Abbeveratevi della sua potenza! Combattete per la gloria dell'Orda!"
S["65b8cf13"] = "Ingegneria"
S["65bc8de2"] = "Ora si collauda il mio progetto!"
S["65c25f28"] = "Da queste parti in pochi sanno usare una lama come Lyria Du Lac. Cercala dietro la fucina e senti se le va di insegnarti qualcosa di nuovo."
S["65c4e4a9"] = "Ti aspettavo, $N."
S["65cf8994"] = "Io resto qui a sorvegliare il rottame. Sbrigati! Speriamo che nessuno noti il fumo..."
S["65d0a2a0"] = "Troppo facile."
S["65d4a06a"] = "Cosa serve adesso a Brother Paxton?"
S["65d78356"] = "Le sabbie del tempo si fermeranno, ma solo per un istante! Ora evocherò la barriera."
S["65dfebd5"] = "Saluti, $C! Il mio unico scopo è catalogare e registrare tutto quello che si sa sulla storia di Duskwood e di Darkshire. Mi aiuteresti in questa impresa?"
S["65e4cc31"] = "%s chiama in aiuto un Blackhand Dreadweaver!"
S["65e52885"] = "Direi di sì!"
S["65e6074b"] = "Ben fatto! Senza di te non sarei mai riuscita a fermare quell'ondata di troggs."
S["65e8611e"] = "Hai visto quante meraviglie ci sono qui nell'Ungoro Crater, $N? È semplicemente fantastico. Certo, non quanto certe cose che riesco a costruire con la mia abilità in ingegneria, ma per essere tutta roba naturale... non è poi così male.$B$BMio zio Remtravel adora le cose antiche come questo posto. In un certo senso seguo le sue orme — anch'io voglio scoprire cose nuove delle culture perdute!"
S["65f0ca56"] = "Finalmente è finita...."
S["65f6671d"] = "Ehi, in effetti non è poi così male. Va benone, allora. Che ne dici di sbrigare una commissione per me?"
S["65fbd1e0"] = "Anche nella morte... persisterò."
S["660ca7d7"] = "Parlami della promozione iCoke."
S["6615e825"] = "%s strappa con violenza la Gloom Weed dal terreno."
S["6621226e"] = "O questo è un kodo bone di prima scelta, o è ora che mi prenda gli occhiali!"
S["66306fde"] = "Verserò il sangue di mille soldati dell'Alleanza... Nessuno potrà resistere alla potenza del Signore del Ghiaccio!"
S["6634b47d"] = "Bah! Ora cucciolo mangia te!"
S["66356f2a"] = "Quando avremo tempo dovremo parlare a lungo. Abbiamo parecchie cose di cui discutere."
S["663a81b7"] = "Se provi a fallire e ci riesci, cos'hai appena fatto?"
S["66465a0e"] = "%s sarà innescata tra 10 secondi!"
S["66529162"] = "Salve, $C! $GBenvenuto:Benvenuta; alle corse dello Shimmering Flats!"
S["6652c6ae"] = "PE' IL RE!"
S["665479c3"] = "$GAttento:Attenta; a entrare in territorio Frostwolf, $Gsoldato:soldatessa;. Quel dannato posto è pieno di trappole! Mine a bizzeffe! Parla con il nostro esperto di esplosivi nella prima torre in prima linea per saperne di più. Sono $Gcerto:certa; che potrebbe insegnarti a disinnescare la situazione."
S["66598e57"] = "<Gli occhi di Cyrus brillano intensamente>$B$BTi divoro in un boccone o ti lascio vivere?$B$BMagari potresti ancora tornarmi utile...$B$BAffronta il mio servitore, $R. Sopravvivi, e riportami la prova della tua vittoria."
S["66611bba"] = "Saluti! Posso insegnarti a trasformare la stoffa che trovi in armature di stoffa?"
S["6662ae94"] = "Sembra che resti solo un giorno da pescare prima che tutto questo materiale bellico venga spedito nel deserto di Silithus, amico. Poi prepareranno tutto, e qualcuno dovrà suonare quel gong giù a sud della Cenarion Hold per aprire le porte e far cominciare la guerra."
S["666af2cc"] = "Salve, Erion, ho bisogno di addestramento!"
S["666c969a"] = "Ecco qua, ragazzo, la tua birra preferita."
S["6675fa89"] = "Va' a sud, in Sen'jin Village, e parla con Un'Thuwa."
S["668a9cd1"] = "$GBenvenuto:Benvenuta; a Bandarion Keep, $C."
S["66918221"] = "$GBen trovato:Ben trovata;, $Gmaestro:maestra; di Canna e Mulinello! Se te la senti di misurarti con i migliori pescatori di queste terre, allora sta' a sentire! Proprio questa domenica a Stranglethorn c'è una gara per scegliere il maestro pescatore!"
S["6694b747"] = "Mancano tre minuti, sento l'energia che comincia ad accumularsi! Continuate a difendere bene!"
S["669913b5"] = "Ho ripreso il controllo! Tutti ai vostri posti!"
S["669facdf"] = "Mi chiedevo quando sarebbe venuto qualcuno a farmi compagnia."
S["66a055b7"] = "Era destino, Windsor? Se era la morte che cercavi, allora la profezia si è compiuta. Che la tua coscienza marcisca nella Twisting Nether. Finite il resto di questi insetti impiccioni, figli miei. Bolvar, sei stato un piacevole burattino."
S["66a5d36a"] = "Osate mettere piede sul suolo sacro degli Hakkari? Servitori di Hakkar, distruggete gli infedeli!"
S["66aa7d99"] = "Molto bene, allora...$B$BIl tuo signore ti ha $Gincaricato:incaricata; di proteggere i suoi campi di mais da bracconieri e ladri. Una notte, mentre fai la ronda, ti imbatti in un uomo smunto, con i vestiti logori, che sta rubando il mais dal campo. Lo affronti subito e lui ti implora all'istante di risparmiargli la vita: sostiene di rubare per sfamare la famiglia, perché il signore di queste terre — il tuo signore — pretende troppe tasse. E in effetti il tuo signore è noto in tutto il paese per le tasse pesanti che impone.$B$BFai la tua scelta."
S["66acda0c"] = "Da questa parte. Fate attenzione, amici. Sento che Naralex si agita nel suo sonno inquieto...."
S["66b2bf7c"] = "Calma, gente. Non vogliamo rivelare la nostra posizione."
S["66b30b0b"] = "Clicca qui per rimuovere gli effetti della resurrezione e riparare tutto l'equipaggiamento"
S["66b9c5a5"] = "Quello che cerchi è Rupert Boch. Lui e il suo seguito hanno una stanza al piano di sopra della Gallows' End Tavern, all'estremità sud-orientale di Brill."
S["66b9d52c"] = "La terra ti chiama, $N. Va' da lei, e sappi che i tuoi fratelli sono fieri di te e di ciò che compirai."
S["66baa5c6"] = "Forse con un altro po' di grasso funzionerà."
S["66c23392"] = "Basta parlare. $GStraniero:Straniera;, grazie di tutto..."
S["66c4d4d6"] = "Vi vedete? È il modo più ridicolo di maneggiare una spada che abbia mai visto!"
S["66c59129"] = "Dicono che questi fuochi d'artificio sfruttino il potere della luna!"
S["66c5b530"] = "Sei già $Gtornato:tornata;! Che posso fare per te, adesso?"
S["66d301ea"] = "C'è sempre... Brandicenere."
S["66e1d558"] = "Ottimo lavoro! Ci siamo quasi, $N. Da questa parte."
S["66ec79f1"] = "La tua avventatezza ci condannerà tutti!"
S["66f03d78"] = "Fatemi sapere se vi serve altro!"
S["66f3b099"] = "Notevole, molto notevole. Sa fare dei giochetti?"
S["66f6afc8"] = "%s solleva la sua enorme ascia sopra Grark."
S["6701c030"] = "Sì, consegnerò gli ordini al Warmaster Garrick!"
S["6706cf86"] = "Richiesta? Vuoi dire la sua minaccia malamente velata? Torna da Elaadrin e digli che se ha qualcosa da dire, può venire a parlarmi di persona."
S["67137343"] = "The Barrens non sono un posto per i deboli, e nemmeno per chi parla troppo. Io non ti farò sprecare tempo in parole inutili.$B$BE da te mi aspetto lo stesso."
S["67142797"] = "Che questa oscurità vi serva da monito: l'ombra dello Scourge avvolge ogni cosa! Non c'è scampo!"
S["6714be26"] = "Cerca Sayoc e Hanashi dentro Arms of Legend, nella Valley of Honor. Bada a come gli parli, o Sayoc potrebbe decidere di dare un pezzo di te a Grinning Dog come spuntino."
S["671e6bd1"] = "In questo mondo, dove il tempo è vostro nemico, per me è il più grande alleato. Questo grande gioco della vita che credete di giocare in realtà gioca con voi. E a questo io dico..."
S["67301f31"] = "L'ORGOGLIO ANNUNCIA LA FINE DEL VOSTRO MONDO. VENITE, MORTALI! AFFRONTATE L'IRA DELLO SCORTICA ANIME!"
S["67310ea7"] = "Due parole: Arcanite buoy."
S["6733189c"] = "Sì. Hai preso in considerazione l'offerta di Lord Tyrosus? The Argent Dawn è pronta ad accogliere te e la tua gente a braccia aperte."
S["673446b0"] = "I fantasmi degli Highborne che vedi vagare per il cortile e per le sale di Eldre'Thalas non li hanno uccisi gli ogres Gordok invasori, e nemmeno i satiri: è stato il Principe in persona!"
S["673cb73f"] = "Salute a te, $Gonorato:onorata;. Turak Runetotem e gli altri druidi ti aspettano all'Hall of Elders, sull'Elder Rise."
S["6743d903"] = "Agghhhh! Non... gioire! La tua è una vittoria vuota, perché tornerò con poteri che vanno oltre ogni tua immaginazione!"
S["67474999"] = "Cerchi un istruttore di Cucina, eh? Be', allora fila dritto al Bronze Kettle, sul lato nord-orientale di The Great Forge. Daryl Riknussun t'insegnerà a preparare un piatto proprio coi fiocchi, e vedrai che ti rimette al mondo!"
S["67488752"] = "Capisco. So rispettare un uomo che tiene all'onore e non scende a compromessi sulle proprie convinzioni."
S["674b47b4"] = "Cosa, non riesci a teletrasportarti lì? Vai al Darkbriar Lodge, vicino al lago nella Valley of Spirits, che sta più in alto della Valley of Strength, verso ovest."
S["675c0c44"] = "Tre urrà per 鐵馬冰河! Questa terra tornerà a essere nostra!"
S["67682080"] = "Stavolta c'è mancato poco. Credo che ci siamo quasi."
S["676915ea"] = "L'Alleanza ha conquistato l'Irondeep Mine!"
S["6770dcab"] = "Ah, finalmente aria fresca! Ho bisogno di un momento per riposare, Большой."
S["677380dd"] = "È bello avere $Gveterani:veterane; come te nell'Alterac Valley, $N. Le nostre provviste sono troppo scarse per lanciare un assalto via terra attraverso l'Alterac Valley... parla con il nostro furiere — ti dirà come aumentare le nostre scorte."
S["67787c1b"] = "Non condivido il tuo ricorso all'alchimia per risolvere alcuni problemi, ma i risultati sì. Ottimo lavoro."
S["67820272"] = "La Tower Point è sotto attacco! Se nessuno la difende, l'Alleanza la distruggerà!"
S["67834617"] = "Io... sento... sento di nuovo il tocco di Elune su di me... Mi sorride... Sì... Io..."
S["67836511"] = "La Frostwolf Relief Hut è stata conquistata dall'Alleanza!"
S["678cf2dd"] = "Io non posso aiutarti! Sei $Gpronto:pronta; per andare da qualcuno che fa questo mestiere da più tempo di me! Vediamo... sei $Gun tipo:una tipa; dell'Alleanza, quindi ti tocca parlare con Lilliam Sparkspindle a Stormwind."
S["67905698"] = "L'ultima volta che ho visto Elder Meadowrun era alla Weeping Cave, nelle Western Plaguelands."
S["67991cfe"] = "Non puoi nasconderti da noi, $Gpiccolo paladino:piccola paladina;!"
S["679cd1fc"] = "Mmmmm... Quello l'ha preso di striscio alla spalla. Grumlar aveva ragione, i mirini sono leggermente storti. Però per me è abbastanza facile sistemarli."
S["679e006b"] = "Per arrivare al Rut'theran Ferry dovrai andare a Darnassus e da lì prendere il portale per Rut'theran Village, ai piedi di Teldrassil."
S["679f56c3"] = "Dove vorresti andare, ragazzo? Bastano poche monete, e i miei Grifoni ti ci portano più in fretta persino del cavallo più veloce."
S["67a1f7e3"] = "C'è silenzio... Troppo silenzio..."
S["67c46316"] = "Credi di avere fegato? Be', allora ho qualcosa per te..."
S["67c465d7"] = "Fermarli — no. Rallentarli — forse.$B$BÈ soprattutto nella Scholomance che si addestrano e studiano. Da lì i membri del Culto si sparpagliano e alla fine si infiltrano nelle nostre società.$B$BPer questo dobbiamo colpire alla fonte. Dritti al cuore del Cult of the Damned!"
S["67c7f5bb"] = "Non di nuovo..."
S["67ca742c"] = "Awak shte ishne'alo zhi, i."
S["67caa0ea"] = "Chi osa cercarmi?!"
S["67cd9830"] = "$C, ti prego, ascolta quello che ho da dirti. L'Alleanza e l'Orda si preparano alla guerra contro i Silithid e i loro padroni ad Ahn'Qiraj, e ogni aiuto che potrai dare sarà molto apprezzato. Come vedi, qui raccolgo thorium bars per lo sforzo bellico. Ce ne servono parecchi, e per ora ne abbiamo una parte."
S["67d2d67c"] = "Non ti dispiace se mi fermo qui un momento, vero?"
S["67d90905"] = "Stregoni, eh. Be', io non ti ho detto niente, ma si dice in giro che quella gente si ritrovi in un bar chiamato Slaughtered Lamb, in Mage Quarter."
S["67f326e2"] = "Questo taglianuvole ti porterà direttamente alle meravigliose pianure aperte di Mulgore."
S["67f45632"] = "Come se avessi tutta l'eternità."
S["67f645d3"] = "Per ora, della famiglia Valor non so molto più di quello che dice il libro che mi hai portato.$B$BForse ci darà qualche indizio su dove cercare."
S["67fa9657"] = "Dobbiamo agire in fretta, o tutto sarà perduto!"
S["67fd6ecb"] = "Un bel segno del tuo valore. Ora la tua istruzione può continuare."
S["6806ac9a"] = "Al diavolo questi kobold. Con loro che corrono avanti e indietro e mi stanno tra i piedi non combino niente. Be', tanto non ho niente di meglio da fare, ti va di imparare qualche tecnica di estrazione mineraria? O forse ti servono solo degli attrezzi nuovi?"
S["6808218b"] = "A eft a Eft Havar hine. Gosh dun kost-guma A scyld rand ta dum mitta. Grum!"
S["680fc9aa"] = "Vorresti imparare qualcosa, allora? Ti do volentieri una mano a cominciare!"
S["68158f10"] = "Elder Dawnstrider la trovi a Flame Crest, nelle Burning Steppes."
S["6819c077"] = "Abbiamo i nostri doveri, $C. Doveri verso l'Orda."
S["681b4c90"] = "First Aid? Be', a me mica mi sembri $Gferito:ferita;. Se vuoi imparare sul serio il First Aid, devi andare da Nissa Firestone. La trovi nella sua bottega, l'Ironforge Physician, vicino a The Great Forge."
S["68204934"] = "Ecco gli ordini, $N. Portali in fretta al Warmaster Garrick!"
S["6821708d"] = "Dopotutto vali qualcosa. Lysta, evoca una sorpresa per le nostre giovani reclute."
S["68217df5"] = "Libero! Finalmente libero dai miei legami!"
S["683568e0"] = "Cosa desidera, $Gsignore:signorina;?"
S["68375085"] = "Non sei $Gadatto:adatta; ad addestrarti con me, $Gstraniero:straniera;. Passa un po' di tempo laggiù con il mio assistente, Jhag."
S["6839751f"] = "Ah, $Guno:una; dei nostri. Che bello vedere che cresciamo così in fretta: ormai non riesco più a ricordarmi tutti i volti.$B$BQuello sciocco di Thrall crede che io mi stia dando da fare per ripulire il nome degli stregoni e dimostrare che siamo suoi servitori. Idiota! La Burning Legion prosciugherà questo mondo fino in fondo, e poi lo ridurrà tutto in cenere."
S["6845895a"] = "Wos, ne novas vrum Goibon wirsh a ver ewiddan. Lo veld goth Aetwinter borne vandar Methrine methrine, Goibon vil nuff ko nuff a dana agol gol."
S["684ad972"] = "Ho quasi finito, $N. Solo qualche altra regolazione!"
S["68594a70"] = "Dimmi di più sulla Forgiatura delle Armature."
S["685c4501"] = "Che la vostra morte serva da esempio!"
S["685e088e"] = "%s è MOLTO $GAFFAMATO:AFFAMATA;!"
S["6861e1b4"] = "...troppo tranquillo."
S["6863c6c0"] = "Saluti, $C. Mentre vai a est, verso The Bulwark, stai all'erta. Gli ultimi rapporti di sorveglianza dicono che da quelle parti lo Scourge è sempre più attivo, quindi procedi con cautela."
S["68646640"] = "Mi sei $Gstato:stata; di un aiuto incredibilmente grande! Queste ossa sveleranno tantissime nuove informazioni e mi aiuteranno a portare avanti la mia ricerca."
S["686586e0"] = "Va' con grazia, e che la magia della Signora ti protegga."
S["686705a8"] = "Salute, Cittadini! Forse presto la marea girerà a nostro favore e la pestilenza finirà."
S["686a15f0"] = "Presto libereremo Azeroth dall'abominevole presenza dei silithid. Possono distruggere molto più di quanto tu abbia visto con i tuoi occhi, $N, e dietro quello che fanno ci sono poteri più grandi e più oscuri."
S["686d5ed4"] = "Quindi, finché non lo fanno... ciao ciao!"
S["6875980c"] = "Evviva Jais! Questa terra tornerà a essere nostra!"
S["6875bf4b"] = "Nell'Undercity c'è un Bat Handler. Esci da Brill prendendo la strada a sud e all'incrocio a T gira a ovest. Avrai le Ruins of Lordaeron sulla sinistra. Entra e scendi nell'Undercity: lì potrai chiedere altro aiuto a un Undercity Guardian."
S["68788198"] = "Temo che non riusciremo mai a placarli..."
S["68792ccf"] = "Sono $Gpronto:pronta;!"
S["687b7159"] = "Al lavoro, cani! Dateci dentro!"
S["6888b23e"] = "$GBenvenuto:Benvenuta;, e sentiti $Glibero:libera; di esaminare la mia merce. A parte l'odore di muffa, è in perfette condizioni."
S["688bc8fa"] = "Ah, e $Glo sciocco:la sciocca; che mi ha liberato sarà tra i primi a placare la mia fame immensa."
S["689cca5f"] = "Le vostre vecchie vite, i vostri desideri mortali non significano nulla... ora siete accoliti del padrone, e servirete la causa senza fare domande! La gloria più grande è morire al servizio del padrone!"
S["689d6e30"] = "Dai un'occhiata a questo, Malyfous."
S["68aa84f5"] = "%s viene $Gtrascinato:trascinata; di nuovo su Xoroth!"
S["68b13f3c"] = "Vuoi un'arma che sia un'estensione del tuo stesso pugno? Sì, credo di poterti mostrare qualcosa."
S["68b18c94"] = "Noi venire distruggere mingherlini!"
S["68b315ca"] = "Cominciate il rituale, miei servitori. Dobbiamo bandire il cuore di Hakkar nel vuoto!"
S["68bbbbf1"] = "Ho da fare, $N. Qualunque cosa sia, di' a Whuut di pensarci lui. Quel pivello non ha fatto altro che rimuginare tutto il giorno, e se va avanti così ancora a lungo finirà per combinare guai."
S["68bbf3a2"] = "Tutte le risorse sono state raccolte. Evviva!"
S["68bea81c"] = "Vuoi volare in grifone, eh? Allora devi andare da Gryth Thurden.$B$BLo trovi sul lato est di The Great Forge, al centro di Ironforge."
S["68c1cd7a"] = "Ciao, $N. $GBenvenuto:Benvenuta; a Thelsamar, e già che sei qui non dimenticarti di fare un salto alla nostra birreria!"
S["68c3eafe"] = "Proseguiamo."
S["68c9b71b"] = "Libera, finalmente libera... Ora devo andare, e grazie per avermi aiutata a fuggire. Posso tornare da sola a Freewind Post."
S["68cac364"] = "TRAFIGGETELI, FRATELLI!"
S["68cacb59"] = "Ehi, signora... avresti un po' di tempo per darci una mano? Per favore?"
S["68d226f7"] = "Come sai, il nostro stile di vita è in grave pericolo. Da quando gli elementali sono svaniti, il nostro popolo è in costante declino."
S["68d2b0ce"] = "La Darkmoon Faire è l'evento più grande di tutta Azeroth!"
S["68d66268"] = "Sono $Gpronto:pronta;."
S["68daeef9"] = "Dammi un momento; qui ci sono un sacco di numeri da ricordare. A quanto pare abbiamo raccolto una parte delle pelli di heavy leather che ci servono. Abbiamo anche una parte del thick leather, e del rugged leather che serve ne abbiamo messo da parte un po'."
S["68e31dd9"] = "Domanda 2, Catena 1?"
S["68e3e23b"] = "Hai cominciato bene, ma ti resta ancora molto da imparare, $N."
S["68e7f1f1"] = "%s sorride."
S["68eac2b1"] = "%s sogghigna."
S["68ecf317"] = "Dalla tua aura capisco che sei di stirpe Highborne, vero? Chi si dice membro dell'High Order ha ben poco in comune con quelli del mio ordine, i Windshapers. Fuori dalla relativa armonia di Thendal Grove potresti scoprire che queste divisioni sono molto profonde, al punto da alimentare discordie e perfino violenza.$B$BTienilo a mente mentre ti muovi per Zephras Isle. Ti do solo questo avvertimento... non metterti contro i Windshapers."
S["68f00d0e"] = "Se può consolarti, lascerò aperta la porta della cella. Come uscirai è un problema tuo. Addio, Kharan."
S["68f1e003"] = "Le tue azioni non saranno tollerate!"
S["6901ad49"] = "Allora, cos'è questa storia della nuova pestilenza?"
S["6905b81e"] = "%s fugge nel vuoto!"
S["6918fae9"] = "Prima di morire facevo il bibliotecario: guerre e pestilenze non mi riguardavano. Non ho mai chiesto di diventare così. Però, ora che la mente è di nuovo mia, non ho intenzione di arrendermi senza combattere."
S["691b02e2"] = "Cerca Turak Runetotem nell'Hall of Elders, sull'Elder Rise."
S["692bc43d"] = "Mmm... Quella pietra è bella, ma troppo piccola."
S["693ab6dc"] = "Ok... e così vuoi fare $Gil sarto:la sarta;. Che ne dici di dimostrarlo?"
S["6940374e"] = "Arnok fa delle buone bende. Lo trovi nella capanna Survival of the Fittest, in riva al lago vicino alla Spirit Lodge, nella Valley of Spirits. È più in alto e a ovest rispetto alla Valley of Strength."
S["694b57bc"] = "È... è tutto annebbiato, $N. Non vedo niente! Aspetta... aspetta un attimo. Vedo... vedo il nascondiglio di Doctor Weavil. È... SÌ! Mi sa che ha un capitolo del libro!$B$BVediamo se riesco ad allargare l'inquadratura di questo coso, così ci vedo meglio.$B$B<Narain sembra diventare strabico.>$B$BAlcaz Island! È sull'Alcaz Island, quel bastardo subdolo!"
S["6957ff28"] = "Hai sentito?"
S["6963426a"] = "Sentimi bene, frittella: ci aspetta la battaglia della nostra vita contro gli insetti di Ahn'Qiraj, e dobbiamo prepararci. Io qui raccolgo iron bars. Per ora l'Alleanza ne ha solo una parte, degli iron bars che secondo le stime serviranno in tutto per lo sforzo bellico."
S["6965c685"] = "%s viene $Gattirato:attirata; dalla magia!"
S["6966b4af"] = "Ho scoperto che certe parti del cervello, se tolte o stimolate, rendono un soggetto molto più docile."
S["696bac0e"] = "Nessuna possibilità!"
S["696bdc5f"] = "%s si contorce dal dolore."
S["697f497f"] = "Per imparare il mestiere della conciatura ti toccherà spingerti fino a Ironforge. Mi hanno detto che vicino alla Great Forge c'è una bella bottega dove te lo insegnano."
S["69876438"] = "Un modo c'è..."
S["6987ac53"] = "Cerchi il corriere? Se n'è appena volato via come un uccellino.$B$BPovero diavolo, non posso dargli torto: questi wendigos sono una brutta faccenda."
S["69897ba5"] = "Un Cristallo Ash'ari è caduto! Restate fedeli a The Lich King, fratelli miei, e cercate di evocarlo di nuovo."
S["698f0aaf"] = "%s sussulta mentre la sua pelle scintilla."
S["698fcb91"] = "Forse vedo una via d'uscita da questo enorme groviglio di rovi."
S["69902fdb"] = "Lo Stonehearth Graveyard si trova a est dello Stonehearth Outpost, nel Field of Strife.$B$BAl momento è sotto il controllo dell'Alleanza."
S["69970e18"] = "Ora sei $Gpronto:pronta; a imparare i segreti più fini della concia delle pelli di kodo. Cominciamo..."
S["699f79df"] = "Mangia questo, figlia mia. Ti farà sentire meglio."
S["69a6a6e0"] = "Mio figlio, Taelan, era solo un bambino quando sono $Gstato:stata; $Ggiudicato:giudicata; colpevole di tradimento e $Gbandito:bandita; dall'Alleanza, in esilio. Ho scelto di restare qui per vegliare su di lui e assicurarmi, in un modo o nell'altro, che crescesse da uomo d'onore.$B$BCome speravo, ha preso il mio posto di signore di Mardenholde; ma, per un crudele scherzo del destino, è entrato nelle file della Scarlet Crusade, e ora ne è il Gran Signore, $R."
S["69ab528a"] = "Al villaggio un posto così non ce l'abbiamo, ma sulle alte vette di Thunder Bluff sì. Prendi la strada che esce da Bloodhoof Village e vai verso nord, fino ai piedi delle rupi. Lì sali con l'ascensore fino in cima e parla con un Bluffwatcher. Che i tuoi antenati veglino su di te."
S["69abe288"] = "%s si decompone in polvere."
S["69ad38aa"] = "Qualcuno darebbe per favore una bella casa al mio gattino?"
S["69b5a256"] = "Eranikus, Tyrant of the Dream è entrato nel nostro mondo."
S["69ba73ef"] = "Sì, era riuscito a fare quello che si credeva impossibile. Dalla fenditura è balzato fuori un agente di Therazane!$B$BDa dove mi trovavo vedevo il goblin parlare con l'agente dell'Old God. Quello che è successo dopo è stato terribile..."
S["69c1e936"] = "Quanti altri rifornimenti servono per ricostruire la nostra base?"
S["69c71f87"] = "Dissolvimento dell'immagine fra sessanta secondi."
S["69c94a06"] = "Captain Galvangar è il fidato aiutante di Drek'Thar. Guida le forze dell'Orda dall'Iceblood Garrison, nella parte meridionale del Field of Strife.$B$BCaptain Galvangar è stato ucciso."
S["69ca3a7d"] = "Salve, $C. In tanti anni ho visto molti tauren ansiosi di mostrare alla tribù quanto valgono. Non va dimenticato che l'entusiasmo non può prendere il posto della saggezza e dell'esperienza."
S["69d58e1c"] = "Usare i frutti della Madre Terra per preparare pozioni che ci aiutino nella nostra eterna lotta è un'impresa onorevole. Per imparare quest'arte devi andare a nord, fino alla nostra grande casa, Thunder Bluff. Una volta in cima, chiedi a uno dei Bluffwatchers di darti indicazioni più precise."
S["69fa2f23"] = "$GBenvenuto:Benvenuta; al quartier generale del SI:7, $N."
S["69fca131"] = "Temo che ormai tu sia fuori dalla mia portata, $Gamico:amica;! Dovresti andare da Nogg a Orgrimmar: lui ti porterà al livello successivo!"
S["69ff3478"] = "Sono $Gsalvo:salva;."
S["6a005d61"] = "Mi duole informarla che non ha superato l'esame, dottore."
S["6a084d73"] = "Il Soulflayer è stato sconfitto! Il nostro capo, Molthor, ora richiama altri suoi servitori..."
S["6a0cb947"] = "Il rogo dell'Uomo di Vimini comincerà tra trenta minuti! Venite alla festa, appena a ovest di Undercity, e celebrate Hallow's End e la nostra liberazione dallo Scourge!"
S["6a0d0724"] = "Immagino che a qualcuno tocchi bendare noi guerrieri dopo i combattimenti. Cerca Arnok alla capanna Survival of the Fittest, accanto alla Spirit Lodge nella Valley of Spirits. Guarda in alto, a ovest della Valley of Strength, e troverai un lago. È lì."
S["6a0d2177"] = "La resa dei conti è arrivata, smidollato!"
S["6a163449"] = "Là dove vagano i Troggs e i Leper Gnomes sorge la nostra casa — Gnomeregan.$B$BLe nostre famiglie, perdute, cacciate dalle nostre case. Disperse.$B$BOh, quanto mi manca la vita spensierata di Gnomeregan, ma quei giorni sono finiti. Dobbiamo resistere! Dobbiamo salvare Gnomeregan!"
S["6a176904"] = "Le tue abilità superano le mie: è tempo che tu affronti nuove sfide. A prepararti ti aiuterà Taladan, che trovi laggiù, accanto al tavolo."
S["6a1ea7c3"] = "Ormai ne sai più di quanto possa insegnarti io, $N. Va' a seccare Tally Berryfizz, una gnoma che vive a Tinker Town, a Ironforge. Ah, e già che sali, salutami tanto Kali."
S["6a22a484"] = "%s sussulta."
S["6a25b0a0"] = "Ok, cominciamo."
S["6a2bafde"] = "Certo, certo. Qui in città abbiamo un Istruttore di Estrazione. Cerca Krunn nell'angolo a nord-ovest, vicino alla locanda."
S["6a2e18e9"] = "Ora mi sento un po' meglio, grazie."
S["6a2ea8a3"] = "Ciao, Antonio. È bello vedere che sei arrivato di nuovo qui sano e salvo. Fammi sapere se ti serve qualcosa."
S["6a34b970"] = "Questa storia ti piacerà da morire, $R. Ecco come stanno le cose. Appena Malygos mi ha affidato la protezione del frammento dello scettro, ho capito che mi aspettava un'eternità di mal di testa e sofferenze.$B$BIo voglio solo studiare queste coste piene di magia e scoprire quali manufatti potrebbero essere rimasti dalla Separazione. Sai, un tempo qui fioriva una civiltà degli Highborne! Non serve che me lo dica tu: qui intorno ci saranno oggetti magici di tutto rispetto, $R. Li fiuto!"
S["6a3642a6"] = "Quel Lumak... sempre a pescare invece che a combattere. Lo trovi sul suo pontile, al lago della Valley of Honor. Già che ci sei, salutami Shankys."
S["6a3a1302"] = "Rallenta! Ci stavo arrivando!$B$BInsomma, lui se ne stava lì, ritto in piedi, con sangue e budella che gli colavano addosso, e indovina chi si presenta?$B$BI Dark Irons! Ma non hai sentito una parola di quello che ho detto??$B$BBe', i Dark Irons sono un po' più furbi di quegli orchi Blackrock. Erano preparati. E per preparati intendo che erano tipo 300... *hic* 'scusa."
S["6a3cf65f"] = "Qui a Thunder Bluff conosco qualcuno che può aiutarti nel viaggio fino all'Alterac Valley: cerca Taim Ragetotem sull'Hunter Rise. Che tu possa trovare ciò che cerchi, $N."
S["6a4ad452"] = "Il potere dell'Occhio è indiscutibile, Ryson, ma cos'altro può fare?"
S["6a62d1a8"] = "Sono $Gstato:stata; $Gucciso:uccisa; cento volte, e mi risveglio sempre qui, $Gvivo:viva;. C'è chi dice che sono $Gmaledetto:maledetta;, e chi..."
S["6a6c8131"] = "Avventure da terre vicine e lontane $BIncontri con genti bizzarre e strane $BMa se una domanda mi vuoi fare $BUn compito semplice devi prima completare!"
S["6a719deb"] = "Ehehe, mollaccione."
S["6a7447ce"] = "|cff33ccffTutte e quattro le torri sono ora sotto il controllo dell'Alleanza!|r"
S["6a84fae1"] = "Buona fortuna con Arugal. Ora devo tornare di corsa da Hadrec."
S["6a90a1b4"] = "Dammi un paio di minuti, $N. Poco fa qui dentro c'è stato un po' di trambusto, e voglio solo assicurarmi che le cose si siano calmate. Ti parlerò tra poco."
S["6a93cd55"] = "Stanno arrivando. Cerca di non farti ammazzare, giovane."
S["6a96cc8e"] = "Tu grande capo adesso! Tu $Gre:regina;! Gloria a $GRe:Regina; $N, $GRe:Regina; dei Gordok!$B$BOra tu capo, e tutti scagnozzi danno tributo a te! Tu lasciato qualcuno vivo, sì capo?"
S["6a98e475"] = "Me spacca! Tu muore!"
S["6aa260bb"] = "Eccellente! Rientri nei parametri e nelle specifiche richiesti. Cosa posso fare per te?"
S["6aa58173"] = "Vi prego, sacerdotesse, perdonate la nostra intrusione. Non vogliamo fare alcun male qui."
S["6aa663e9"] = "E ora sai perché vivo in un cratere."
S["6ab9170c"] = "La culla del nostro popolo fa ora parte di un mondo ancora più vasto conosciuto come \"Azeroth\". Ci sono persone su Azeroth che possiedono una vista celeste tanto forte da poter trafiggere i cieli stessi per vedere oltre."
S["6ac32b1e"] = "Nessun fossile misterioso qui... Ah, ma c'è la mia copia delle Green Hills of Stranglethorn. Che bel libro!"
S["6acb6390"] = "Aha! Ecco!"
S["6acd31c5"] = "Ah, bella domanda.$B$BSe ti piace cacciare all'aria aperta, di elementali ne trovi qui nelle Plaguelands, ad Azshara, nelle Burning Steppes, a Felwood, a Silithus, a Winterspring e persino nell'Un'Goro Crater.$B$BSe sei il tipo che ride in faccia al pericolo, forse ti conviene fare un salto a Dire Maul: ho sentito dire che fra le sue mura le aberrazioni elementali non si contano. E faresti bene a cercare anche gli elementali al servizio dei nani Dark Iron dei Blackrock Depths."
S["6acfd07c"] = "Ecco la classifica finale!$B$BThrall:$BCairne:$BSylvanas:$BTotale Orda:$B$BBolvar:$BMagni:$BTyrande:$BTotale Alleanza:$B$BL'Orda ha l'eroe più popolare!"
S["6ad8e4a1"] = "Una compagnia di spiriti affini può essere una forza potente, e Krumn ti aiuterà a crearne una. Lo troverai al centro Thunder Bluff Civic Information, sull'altura più bassa, vicino agli ascensori."
S["6ae4d303"] = "ARRRRRGH! Mi ha preso!"
S["6ae706aa"] = "Siete arrivati troppo lontano per fallire. State indietro, mortali."
S["6ae7ab0f"] = "Dov'è Field Marshal Teravaine?"
S["6ae85985"] = "Attenta a dove metti quel piede, signora. Mica abbiamo tutti la fortuna di essere alti quanto una $R."
S["6ae8ea89"] = "Grazie ancora, $N. Ora aspetterò qui finché non sarà sicuro andarmene."
S["6af0bbca"] = "Un maestro dei grifoni, $Gragazzo:ragazza;, a Dun Morogh non lo trovi mica a ogni angolo. Se vuoi volare da qualche parte in grifone, ti tocca andare ad Ironforge."
S["6af1187f"] = "Così vicino alla benedetta Lakeshire. Per la Luce, che le mie gambe mi portino ancora un po' più avanti!"
S["6af37265"] = "Devi aspettare un momento, $C: i naga ci stanno attaccando proprio adesso. Ti parlo appena l'attacco è finito!"
S["6af44a1f"] = "%s sbuffa."
S["6afba882"] = "Benvenuta, sorella mia. Se sei qui per addestrarti, ti istruirò con piacere.$B$BRiaffermare il proprio posto in quello che mi piace chiamare il Grande Equilibrio non fa mai male. Noi che di questo equilibrio siamo i custodi dobbiamo sforzarci di tenere sempre la mente lucida e il cuore forte, e l'addestramento ci aiuta a farlo."
S["6aff28a4"] = "Vai nella caserma sul lato est di Razor Hill e cerca Tarshaw Jaggedscar. E porta orgoglio e onore all'Orda, giovane!"
S["6aff8ebe"] = "Il cancello è in vista! Ce la faremo! Ma prima devo tirare il fiato."
S["6b04fe0a"] = "Oh, davvero succulento. Molte grazie, signora Chambers."
S["6b097d1b"] = "Chi controlla lo Stormpike Graveyard?"
S["6b0f4edc"] = "Vedo che hai trovato l'occhio.$B$B<Master Ryson sogghigna.>$B$BBe', dammelo!"
S["6b0fa6da"] = "Noi tanto più puliti di ogres in Tanaris. Per tutto deserto, fin dove arriva occhio — cacca di ogre. Qui no, no signora!"
S["6b1238ea"] = "L'arcano corrompe solo i deboli. Anche se la via dello stregone non è la tua, faresti bene a ricordartelo."
S["6b1399fc"] = "Se dobbiamo trovare il nostro posto in questo mondo, ci riusciremo con lo studio e con la volontà di ignorare gli istinti umani che a poco a poco si spengono in noi."
S["6b215b70"] = "Forse mi racconterai le tue gesta, $N. Ne sarei $Gonorato:onorata;."
S["6b2e2a3e"] = "Benvenuta, sorella mia. Se cerchi addestramento, ti istruirò con piacere.$B$BPresto il richiamo di The Emerald Dream si impadronirà di te: cadrai in letargo per molti anni e camminerai tra le forme più pure. Sarà lì, in quel tempo, che riceverai il tuo addestramento definitivo."
S["6b365d76"] = "Hai la mia più profonda gratitudine, $N. Ti ringrazio."
S["6b37c703"] = "A Silithus non abbiamo un nemico solo, $N.$B$BTutti pensano ai silithid, ma io e mio fratello maggiore teniamo ben d'occhio quei pazzi del Twilight's Hammer."
S["6b391f5a"] = "Kel'Thuzad? Se quel nome ti dice qualcosa, allora forse il libro che ti ho mandato a prendere l'hai letto davvero.$B$BPurtroppo, la tua risposta è sbagliata."
S["6b3caacc"] = "Anch'io ho sentito la tua mancanza, tesoro. E finalmente sono a casa..."
S["6b3efe61"] = "%s inizia il conto alla rovescia."
S["6b45d75a"] = "10.000 anni di sapere scritto finiscono per attirare all'Athenaeum la gente sbagliata. Ogni giorno c'è qualche libro rubato, recuperato e poi rubato di nuovo."
S["6b4eda43"] = "Preparati a essere Malownato!"
S["6b550578"] = "%s va su tutte le furie vedendo cadere in battaglia il suo raptor!"
S["6b5e6c82"] = "DING! 428.000 gradi Kraklenheit, esatti! Beh, circa. Più o meno. Da quelle parti..."
S["6b660139"] = "Ce l'hai fatta?! Mi sorprende che Kinelory non ti abbia rallentato più di così. Kin, ecco i tuoi calzini. Dammi quello che hai trovato den"
S["6b6a6472"] = "Adoro l'odore di Ironforge al mattino! Eh? E tu di cosa avresti bisogno, $C?"
S["6b76856b"] = "I generali ci dicono che abbiamo raccolto tutto ciò che ci serve per l'imminente Guerra di Ahn'Qiraj. Ora aspettiamo solo che l'Orda finisca di fare scorte, e poi potrà cominciare il trasporto del materiale bellico."
S["6b77ad97"] = "La tua presenza tempra i nostri nervi, $GMaestro:Maestra; $N."
S["6b8159a0"] = "La tua eredità ti precede, $C. Se vuoi, ti permetto di riscriverla e di farne qualcosa di nuovo."
S["6b8491bf"] = "Io non scappare da $N come te!"
S["6b8802b6"] = "Ai miei occhi, $N, tutti i membri dell'Orda sono uguali. Abbiamo sopportato tutti molti fardelli, e senza la saggezza e l'onore non saremmo migliori dello Scourge, o del mio popolo ai tempi in cui il demone Mannoroth ci aveva corrotto il sangue.$B$BIl tuo dovere è aiutare l'Orda e difendere il nostro modo di vivere. Ma è tuo dovere anche sapere quando concedere pietà e compassione, agli amici come ai nemici.$B$BChe ti sia ben chiaro. Questa è la nuova Orda, non un esercito generato dai demoni e senza libero arbitrio."
S["6bab4c88"] = "Non posso addestrarti, $C."
S["6babc0e1"] = "Bah... I giovani!"
S["6bbe754c"] = "Sorella d'armi, è giunto il momento di riprenderci la notte dallo Scourge!"
S["6bc840e9"] = "Incantamento"
S["6be0ddcc"] = "Avelina si dedicò interamente al suo mestiere, cercando di dimostrarsi un'artigiana di indiscutibile abilità."
S["6be1f635"] = "Ogni giorno è una prova, e oggi non fa eccezione. Superala e ti insegnerò un po' di quello che so..."
S["6beab53e"] = "Pensi di poter venire qui a derubarci, eh!?"
S["6bef0500"] = "Il Signore dei Blackrock pende dagli archi!"
S["6bf22ca5"] = "%s sfoglia freneticamente le pagine di un grosso tomo."
S["6bfa110a"] = "Aldwin Laughlin lo trovi allo Stormwind Vistor's Center, nel Trade District."
S["6c0b535d"] = "Ci guiderò attraverso Heartghlen fino al limitare della foresta. Da lì, mi porterai da mio padre."
S["6c1523a9"] = "%s scompare nella nebbia."
S["6c19780f"] = "Valstann lo Staghelm era il braccio destro di Fandral. Guerriero fiero e nobile, la sua dedizione e il suo amore per il padre erano incrollabili... e gli Imperatori Gemelli videro in questo una debolezza. Una debolezza da sfruttare."
S["6c32a2e6"] = "Si presume che esista. Solo un grande draconide cromatico o un drago potrebbe avere un carapace simile."
S["6c3cc77a"] = "Com'è il filo del tuo acciaio? Abbastanza buono da squarciare il ventre del tuo nemico? Lascia che ti mostri qualcosa per renderlo ancora più affilato."
S["6c3f892d"] = "Dov'è \"Garona: Uno Studio su Furtività e Tradimento!\" Questi testi devono essere restituiti!"
S["6c423d4f"] = "Birra scura di Southshore, quanto ti amo? Lascia che conti i modi..."
S["6c48fc53"] = "È bello rivederti, Erland. Qual è il tuo rapporto?"
S["6c4edd65"] = "Elder Ragetotem passa le sue giornate nella Valley of the Watchers, nel Tanaris Desert."
S["6c500222"] = "Tiene il vischio sopra la sua testa"
S["6c50c536"] = "È... come dev'essere."
S["6c5471ba"] = "Che cosa hai fatto? $GSTOLTO:STOLTA;! L'hai portato... NO!"
S["6c6242c3"] = "Chiedimelo con gentilezza e ti insegnerò l'arte del forgiatore di martelli."
S["6c6d38c0"] = "HnnhhnNNHHnnggg!"
S["6c7167c2"] = "Con l'alchimia puoi trasformare le erbe che trovi in pozioni curative e di altro tipo."
S["6c71ec44"] = "Quante altre provviste servono per il prossimo potenziamento?"
S["6c832c7c"] = "Ho fallito di nuovo..."
S["6c8d33a4"] = "Il tuo spirito è puro, $N."
S["6c8d398d"] = "Che peccato, e io scommetto che avevi affilato il coltello apposta pensando di tagliarmi qualche pelle. Purtroppo abbiamo già raccolto tutto il cuoio robusto necessario, $C. Renditi utile, però, e chiedi agli altri qui se hanno altri compiti di raccolta per te."
S["6ca24542"] = "Mancano solo pochi minuti di shopping a Natale! Ma aspetta, è già Natale? Beh, allora restano solo pochi minuti per fare festa! TEST TEST DO NOT LOCALIZE"
S["6caec9f9"] = "Il Ricombobulatore sta venendo proprio bene. Mancano solo un paio di ritocchi!"
S["6cb1bb36"] = "Svegliatevi e alle armi, cittadini di Darkshire! Un abominio non morto si avvicina lungo la strada!"
S["6cb66e7b"] = "Non mi tirerete mai fuori dal mi' bunker, pagani!"
S["6cb8d929"] = "Sei stato MALOWNATO!"
S["6cc167cf"] = "Qui mi servirebbe una mano!"
S["6cc441df"] = "Niente paura, ci pensa Bodley! Vediamo un po', ah sì... eccolo. Lascia solo che lo evochi... e, voilà!$B$BCerca di non perderlo di nuovo, $N."
S["6cc7da98"] = "Aiutate i bambini di Stormwind... vittime della guerra e della pestilenza!"
S["6ccd3f8d"] = "In questo mestiere sei più $Gbravo:brava; di me! Ti serve qualcuno ancora più esperto di me: Ainethil, una signora elfa della notte che vive nella Craftsmen's Terrace of Darnassus."
S["6cd03df6"] = "Devi essere in rapporti amichevoli con i troll della tribù Darkspear prima che io ti insegni a cavalcare, $C."
S["6cd0ad48"] = "Risposta sbagliata, $N. Vattene."
S["6ce7d791"] = "Almeno ci guadagneremo la morte!"
S["6cef34c3"] = "Ti ha $Gmandato:mandata; Umi, vero?! Mi aveva detto di aspettarmi una sorpresa, ma non avrei mai pensato che intendesse questo!"
S["6cf0c04e"] = "Unisciti alla lotta contro il male! Accetta oggi stesso un incarico presso l'Argent Dawn!"
S["6cf4f234"] = "Vi state divertendo tutti finora? Fantastico! Benvenuti alla Darkmoon Faire, il più grande spettacolo di tutta Azeroth! Non dimenticate di parlare con Yebb e i suoi amici qui, mentre visitate il Darkmoon Zoo Bizarre di Neblegear."
S["6cf71b7b"] = "Venite a prendervi il pane fresco!"
S["6cfd27d7"] = "Kyra Windblade è molto abile con la lama, e dovrebbe poterti addestrare un po'. La troverai alla Locanda di Dolanaar."
S["6cfd37a8"] = "Nella grande dimora di Thunder Bluff, lontano a nord, c'è chi può insegnarti l'Erboristeria. Per arrivarci segui la strada che esce dal villaggio e, ai piedi della rupe, prendi l'ascensore che sale fino in cima all'altura. Lassù ci sono molti Bluffwatchers che possono darti altre indicazioni."
S["6d077f10"] = "Lady Sylvanas ha ordinato di indagare su alcuni fenomeni naturali di Azeroth. Crede che dal suo passato pieno di segreti ci sia qualcosa di grande da imparare.$B$BNon so come l'abbia scoperto, ma mi fido di lei del tutto, quindi farò del mio meglio.$B$BPer ora studio melme, fanghi e cose del genere. Sembrano tutte simili nella composizione, ma risentono parecchio dell'ambiente in cui vivono.$B$BMi farebbe comodo il tuo aiuto per raccoglierne qualche campione."
S["6d081324"] = "Da quando abbiamo lasciato le nostre case su Kalimdor, il mondo si è fatto più grande. Ora lo chiamano \"Azeroth\", ed è un mondo immenso e pieno di vita."
S["6d0903ea"] = "Raaah! Urok è morto!! Ahahah!!"
S["6d0f5cbb"] = "Come se non avessimo già abbastanza problemi, tu vai a crearne altri!"
S["6d1f41a8"] = "Mi interessa l'addestramento da sarto."
S["6d23edaf"] = "Quei due non mi sono mai piaciuti. Muoviamoci."
S["6d25ed03"] = "Ricacciateli nella loro base! Che non resti in vita un solo soldato dell'Alleanza su questo campo di battaglia!"
S["6d27f449"] = "Sia lodata Elune! Non so se sarei sopravvissuta a questa giornata senza di te, $Gamico:amica;."
S["6d2968cd"] = "Ergin ve me daegil far lon. Vil Forthis gloin andovis ras bor algos vil eloderung wirsh."
S["6d2db892"] = "%s comincia a esaminare le insegne dei difensori caduti di Stromgarde..."
S["6d2f845b"] = "Non costringermi a usare le maniere forti."
S["6d30a068"] = "Quello che potrei insegnarti ti farebbe diventare il cervello gelatina! Torna quando ne saprai abbastanza!"
S["6d398d07"] = "Capendo che la gemma doveva essere protetta, ci rivolgemmo alla dea stessa."
S["6d3db313"] = "Di solito gli scuoiatori portano tutte le pelli a seccare a Ironforge. Perché non fai un salto lì e vedi se ne trovi uno che ti addestri?"
S["6d3ed6b9"] = "I druidi sono molto sensibili alle sofferenze di ogni creatura del mondo. Quando si è scoperto che questi uccelli erano in pericolo, abbiamo organizzato un modo per salvarli dalla corruzione di Feralas.$B$BA guidare l'impresa è una gnoma, Curgle Cranklehop: raccoglie le uova e le fa spedire qui, dove me ne prendo cura.$B$BUn aiuto in più per la nostra causa ci fa sempre comodo, $N. Forse dovresti andare a Gadgetzan a cercare Curgle."
S["6d456362"] = "Silenzio, servitore! La vendetta sarà mia! Morte a Stormwind! Morte per pollo!"
S["6d4c2e0f"] = "Fai in fretta."
S["6d4d91f3"] = "Se non ne hai mai vista una, è uno spettacolo da non perdere. Una creatura davvero notevole, sia dentro che fuori dal campo di battaglia. Adesso diamo un'occhiata a ciò che sono sicuro tutti voi studenti maschi stavate aspettando. La succube."
S["6d5196c9"] = "Attento! $N attacca!"
S["6d55a9e4"] = "Sembri aver bisogno di una mano, come posso aiutarti?"
S["6d5b3956"] = "Ahimè, ho chiacchierato anche troppo. Se passi dal porto di Valanaar, cerca Elaadrin Evengale. Un tempo Elaadrin era mio allievo; oggi è il Magistro Capo dell'High Order. È testardo e capace, e ora tocca a lui e ai giovani Skyborne come te portare avanti le speranze del nostro popolo."
S["6d62fc53"] = "Sono $Gun venditore non morto:una venditrice non morta; di stoffe, e questo è il mio testo di saluto."
S["6d66298b"] = "Siete stati condannati a morte per crimini contro la nazione dei Dark Iron!"
S["6d687894"] = "Tornerò in fretta da Vahlarriel. Finisci quelli che puoi — da qui in poi dovrei cavarmela da $Gsolo:sola;."
S["6d7db7ce"] = "Cosa... cos'è questo? Può essere la risposta alle mie preghiere? Elune mi ha concesso un'arma, questa falce, per sconfiggere i demoni."
S["6d80d4e6"] = "%s cade su un ginocchio."
S["6d846c96"] = "La fortezza di Nethergarde ha sempre bisogno di nuove provviste — per aiutare i nostri maghi nelle ricerche e per tenere i nostri difensori in perfetta forma per combattere."
S["6d85e792"] = "Il totem della purificazione ce l'ho, $N."
S["6d8cf196"] = "In Rogues' Quarter, sull'anello interno, trovi Killian Hagey: insegna a scuoiare."
S["6d8d8da2"] = "Niente di cui avé paura. Vieni."
S["6d93af0d"] = "Ben fatto!"
S["6d96ee1f"] = "Chiunque sia sospetto va abbattuto subito. Raggiungete le vostre postazioni il prima possibile!"
S["6d981d99"] = "Devo ammetterlo, te la stai cavando molto bene nell'arte della sartoria. Ora vediamo quanto sei $Gbravo:brava; DAVVERO..."
S["6d9ce011"] = "DEBUG GENERAZIONE SERVITORI DEL COVO"
S["6da2e8e3"] = "L'auto ha preso una batosta! Prepariamola per la prossima gara."
S["6da93925"] = "Lakota'mani tuona dentro di te, $N."
S["6dacb355"] = "Ci servono altri lupi! Venite alle stalle ad aiutare!"
S["6db2c3cb"] = "Sole cocente e abitanti ostili: The Barrens sono il posto perfetto per mettere alla prova la tua forza e la tua tempra."
S["6db756a3"] = "Quante altre provviste servono per mandare un assalto via terra?"
S["6dc05d48"] = "Ah. Vi do il benvenuto, mia signora!"
S["6dc0c07e"] = "Attivazione del protocollo di protezione Goaz."
S["6dd3f202"] = "Sì, è vero. Dietro le mura della Cattedrale, paladini e sacerdoti affinano le loro abilità e studiano grandi verità."
S["6dd50e07"] = "Nurse Neela accoglie tutti i suoi futuri clienti appena mettono piede nella Gallows' End Tavern, all'estremità sud-est della città."
S["6dda51b7"] = "%s saluta $N con la mano."
S["6ddb5a73"] = "Ti vedo..."
S["6ddd8a2d"] = "Ho vagato così a lungo nella mia forma maledetta. Mi hai liberato... Il tuo duro lavoro sarà ripagato."
S["6de4efc6"] = "Guardando meglio il pilone, scopri un piccolo tavolo con sopra dei cristalli rossi, blu e verdi, sistemati in quello che sembra un ordine preciso.$B$BA un grande cerchio di cristalli rossi stanno accanto, da un lato, un cerchio più piccolo di cristalli blu e, dall'altro, uno di cristalli verdi.$B$BPrendi nota con cura dei colori dei cristalli: sai che a J.D. interesserebbe molto sapere cosa hai trovato."
S["6de5bd37"] = "Ho abbastanza rifornimenti per portare le nostre truppe al grado di esperte."
S["6de67077"] = "Se hai perso un pezzo della tua armatura Zandalarian, forse posso aiutarti."
S["6dee2a9d"] = "Che c'è, adesso? Non vedi che sono piuttosto occupato?"
S["6df5ac69"] = "Voi non dovreste essere qui! Uccideteli!"
S["6dffeb46"] = "Non così in fretta, amico... Le redini di un possente ariete da sella non le affido a chi non si è dimostrato alleato dei nani di Ironforge. Quando sarai $Griconosciuto:riconosciuta; come $Gosannato:osannata; da Ironforge, ti farò vedere volentieri le razze di arieti che ho in vendita."
S["6e004ba1"] = "Vorrei lasciare il mio famiglio nella stalla."
S["6e07d3df"] = "%s individua uno zombi da divorare!"
S["6e0c0def"] = "Portate via quei corpi dalla sala. Non gli piace aspettare."
S["6e20b889"] = "Attaccate, sorelle mie! Il troll non deve fuggire!"
S["6e265e9d"] = "Spazzagli la gamba... Hai qualche problema?"
S["6e27c2b5"] = "John, tesoro, dove sei?"
S["6e33e569"] = "Insegno solo agli allievi che padroneggiano già le basi. Devi cercare l'elfa della notte Darianna, nella Craftsmen's Terrace of Darnassus: le sue abilità completeranno alla perfezione le tue."
S["6e3429e3"] = "Alle armi, ragazzi!"
S["6e45c561"] = "$GBenvenuto:Benvenuta; nella nostra tenda. Posso fare qualcosa per te?"
S["6e5e22df"] = "Ormai sono troppo ferito per alzarmi da questo letto. Ti supplico, $Gstraniero:straniera;. Va' al mio frutteto. Racconta ad Aamelia cos'è successo e trova il modo di aiutarla a sopravvivere. Ti prego, $Gstraniero:straniera;... aiutaci."
S["6e5e6d15"] = "Carneficina! Che io possa versare sangue nel Suo nome!"
S["6e640360"] = "Tu impugni la lama di mio padre, $N. I miei soldati sono ai tuoi ordini, $Gmio signore:mia signora;. Prendili... Guidali... Gli impuri vanno epurati. Devono essere purificati dalla loro corruzione."
S["6e655332"] = "Ora sei $Gpronto:pronta; a seguire il sentiero che unisce la tua vita alla mia, anche se solo per poco tempo. Tuttavia dobbiamo assicurarci che tu comprenda le cose di cui parlano gli spiriti."
S["6e77d979"] = "La flora e la fauna di Shadowglen sono la prova del nostro talento nel lavorare a stretto contatto con la natura. È un onore assistere alla nostra grande impresa."
S["6e7d1dfe"] = "Tomas non sarà il cuoco migliore della zona, ma certi piatti gli vengono proprio bene. Se vuoi imparare il mestiere, adesso lavora alla Lion's Pride Inn."
S["6e7f1a29"] = "<Valennia è gravemente ferita e riesce a stento a restare cosciente.>"
S["6e81380a"] = "Senza dubbio sei $Gun altro sempliciotto inetto:un'altra sempliciotta inetta; che la Dama Oscura ha mandato a farsi addestrare dal suo campione.$B$B<Nathanos sospira.>$B$BVi ho rimandati tutti da lei a pezzi, e non vedo perché stavolta dovrebbe andare diversamente.$B$BMa il mio compito non è chiedermi il perché: è fare ciò che la Dama Oscura comanda."
S["6e81c034"] = "Iniziamo una nuova battaglia, e stavolta sconfiggiamo l'Orda!"
S["6e83f392"] = "Cacciarmi, loro!? Farò vedere io a quei cervelloni impettiti di Stormwind il vero potere di Niby! AMMIRATE!"
S["6e8694ce"] = "Ha! Io ho più paura che quei vecchi buchi e squarci facciano scoppiare quell'affare e mi riempiano di schegge!"
S["6e8a7b02"] = "Un Horde Commendation Signet viene assegnato a $Gun eroe:un'eroina; che va oltre il proprio dovere per l'Orda. Diversi Ufficiali dell'Encomio delle fazioni dell'Orda si trovano in tutte le città principali: parla con quello della fazione presso cui vuoi aumentare la tua reputazione e consegnagli il numero di anelli che ti chiede!$B$BA proposito, durante lo sforzo bellico qui, se per i tuoi anelli preferisci ricevere una ricompensa materiale invece della reputazione, cerca Warlord Gorchuk."
S["6e98e3bb"] = "Sono $Gpronto:pronta; a piazzare il faro, Mulv. Dammi un faro."
S["6e9ccfba"] = "Se mi tocchi ancora sarà l'ultima cosa che tocchi!"
S["6e9d4907"] = "Qui a Desolace ho un sacco di cose da fare, $N. Roetten vuole che raccogliamo dei reagenti per uno dei nostri clienti, e che recuperiamo pure alcuni di questi oggetti perduti.$B$BVisto che sei qui per dare una mano, che ne dici di cominciare?"
S["6eab63ad"] = "Vance Undergloom sta al piano di sopra della Gallows' End Tavern, sul lato sud-est di Brill: lo trovi in una delle stanze."
S["6eac3376"] = "L'Horde Flag è stata lasciata cadere da $N!"
S["6eaef54b"] = "Confido che la Luce sia con te, $N. Posso fare qualcosa per te?"
S["6eb01ee5"] = "Ecco qua, $N. Meno male che i miei poteri di divinazione ed evocazione funzionano ancora in questo stato spettrale, eh?"
S["6ebbe6bf"] = "Comincio a estrarre energia dalla pietra. Il tuo compito, $N, è difendermi. Questo posto è maledetto... fidati."
S["6ec1422e"] = "Lo sai che nei Canali ci sono i crocolischi? Li hanno portati dalla palude come animali da compagnia, ma poi li hanno buttati nei canali."
S["6ec33097"] = "Elune ha fatto molti doni agli elfi della notte. In cambio, sta a noi proteggere queste foreste dalla corruzione demoniaca che l'Orda porta sempre con sé."
S["6ec999ad"] = "Sì, lo vedo. Non posso dirmi contento che l'ennesima delle mie brillanti miscele sia andata sprecata."
S["6ed5e910"] = "Articoli e merci mistiche, $Gstraniero:straniera;: questo è il mio mestiere."
S["6edabb22"] = "Un fabbro molto più bravo di me, poco ma sicuro. Però, se vai in giro a raccontare che l'ho detto io, negherò tutto. Dovresti andare a parlare con Therum Deepforge. Se c'è qualcuno che può insegnarti di più, è lui."
S["6ee65601"] = "Nel creare armature, l'abilità di Telonis non ha eguali, e dovresti essergli $Ggrato:grata; perché per il sapere che trasmette agli altri non chiede di più. Ora va' a cercarlo nella Craftsmen's Terrace, nella parte nord-orientale di Darnassus."
S["6eea0cf8"] = "Ciao, $N! Cosa posso fare per te?"
S["6eec226e"] = "Stupida scatola! Stupida, stupida scatola! APRITI! GRURK DICE TU APRI!"
S["6eec6dc0"] = "Non c'è speranza!"
S["6ef2aa33"] = "Non lo accetterò! Io servo la luce!"
S["6ef4bffd"] = "Winterspring è sotto attacco in questo momento?"
S["6ef53fbb"] = "È meraviglioso, Rimblat! Nemmeno questa terra immonda e spaccata è impossibile da guarire."
S["6efea0fe"] = "Appena ho sentito che dal cielo cascava letteralmente uno stormo intero di elfi nuovi, mi son detto \"È LÌ che devo stare\". Una società tutta nuova di polli creduloni ed entusiasti... ehm — clienti!"
S["6eff8804"] = "Proprio una bella presa! Porti onore all'Orda, ragazzo, ti ringraziamo!"
S["6f07f071"] = "Quando l'operatore parla con te, comincia ogni riga col tuo nome. Se non vedi il tuo nome, non sta ancora parlando con te."
S["6f0b4310"] = "Salve! Che ti porta a Winterspring? Queste terre sono fredde e sconfinate, e possono sembrare tetre, ma qui di segreti se ne nascondono molti..."
S["6f0d1085"] = "Mi presento a rapporto, $Gsignore:signora;."
S["6f0da64d"] = "E ora la guerra, lei sta per arrivare. Resta solo da spedire tutte 'ste merci e armi alla Cenarion Hold a Silithus, e sarà fatto entro pochi giorni. Poi qualche anima coraggiosa dovrà suonare il gong vicino a quei cancelli di Ahn'Qiraj per aprirli e far cominciare la guerra."
S["6f13d886"] = "Ci sono avventurieri convinti che l'incantamento non funzioni. Ma ho notato che, quando li sfido a combattere, cambiano musica!"
S["6f13ee95"] = "Lo giuro, non vi ho rubato niente! Ecco, prendete un po' delle mie provviste, ma andatevene!"
S["6f1643f0"] = "Ok, chi mi ha spinto? Sei $Gstato:stata; tu, $N? Qualcuno riaccenda le luci. Hic!"
S["6f1a8fe6"] = "A scuoiare le prede te lo insegnerà Thuwd. Lo trovi dai Kodohide Leatherworkers, a The Drag."
S["6f218cda"] = "%s comincia a divorare avidamente il cibo."
S["6f23b885"] = "Adesso date un'altra bella occhiata prima di dirigerci verso il Distretto Sacro e la grande Cathedral of Light."
S["6f2ca996"] = "Avete provato la Birra dei Dark Iron? È la migliore!"
S["6f2df573"] = "Che bello rivederti, $N! Non so come ringraziarti per aver portato quel messaggio al mio caro piccolo gnomo.$B$BVuoi sentire una canzone? Con quella, navigare nei mari agitati sarà molto più facile!"
S["6f2f2951"] = "Rilevate forme di vita sconosciute.... valutazione in corso..."
S["6f31c57e"] = "Tremate davanti alla nostra potenza! Fuggite! Non ci sarà vittoria per i vivi!"
S["6f34d1ae"] = "Non dovrei nemmeno dirtelo, ma se riesci a passare in mezzo a tutte le bestiole e le bestiacce delle Badlands, forse arriverai alla Searing Gorge.$B$BSì, le Badlands. Vicino a Kargath c'è una specie di strada secondaria che hanno lastricato gli orchi. Già questo ti fa capire con che razza di sciocchi abbiamo a che fare! Un'entrata di servizio per l'inferno? Ma cosa gli passava per la testa?"
S["6f392f0f"] = "Uso sempre gli stessi ingredienti, eppure ogni volta che preparo questa pozione sembra curare meno ferite. Può voler dire una cosa sola: le piante stanno cambiando. Perché, e in cosa, non so dirlo."
S["6f41ce54"] = "Potenzia a unità veterane!"
S["6f46f48c"] = "Opzione banchiere"
S["6f471e02"] = "Infili la linguetta A nella fessura B ed è ovvio che fa BUM! Ecco, ti faccio vedere cos'ho, poi puoi farti spiegare da Lilliam come montarlo senza farlo esplodere."
S["6f4c5bf2"] = "Insegnarti l'ingegneria gnomesca? Non ho tempo per queste sciocchezze. Con Oglethorpe hai una sola possibilità e te la sei giocata, vero?$B$BDovrai andare a Tanaris e trovare la capanna di Narain Soothfancy. In quella capanna c'è un libro magico che forse riuscirà a dare una scossa a quel che resta del tuo cervello e a farti recuperare quello che hai perso.$B$BOra sparisci!"
S["6f4c6920"] = "Sono stato via a lungo... è meglio che torni."
S["6f4f8fd2"] = "Non farmi chiamare il mio papà per prenderti! Gli piace prendere i coniglietti col fucile!"
S["6f52ebc6"] = "Ciao, $N! Io sono Scooty, il maestro ingegnere."
S["6f567355"] = "Grazie, $N. E buona fortuna."
S["6f6c8a38"] = "Siamo sotto assedio! Alle armi! Uccidete $Gquesto:questa; $N!"
S["6f6e93ff"] = "The Thorium Brotherhood sa come creare le sacre armi e armature del Fire Lord, ma ci mancano le braccia per procurarci i materiali da lavorare.$B$BIo, Lokhtos Darkbargainer, ho avuto dalla Brotherhood il permesso di scambiare le prestigiose ricette con i materiali raccolti nel Molten Core.$B$BFammi la tua offerta, $R."
S["6f76b01f"] = "Grazie, Keldric. A dopo."
S["6f7cf99c"] = "Guardia, porta qui il prigioniero. Mettilo nel Circle of Binding."
S["6f83b68b"] = "Proprio così. Mi mostro a te in una forma che puoi comprendere, mortale. Trovarti al cospetto del drago noto come Vaelastrasz, di certo, non lo sopporteresti.$B$B<Vaelan ride.>$B$BDevo continuare?"
S["6f840348"] = "Libero, finalmente, da questa cella miserabile! Ti accompagno al cortile...."
S["6f85ee7b"] = "I tauren hanno combattuto nell'ultima guerra. Gli sciamani sono stati mandati a difendere questo mondo dall'invasione dello Scourge, e la maggior parte è morta. Molti altri sono stati fatti a pezzi, e in quella cittadella maledetta i pezzi dei loro corpi sono finiti in esperimenti immondi. Piango la loro scomparsa, ma il loro coraggio mi gonfia il cuore d'orgoglio."
S["6f8c6526"] = "Che la Luce ti protegga, $C."
S["6f8f3735"] = "A volte stupisco perfino me stesso!"
S["6f9a308b"] = "Se volete scusarmi, devo congedarmi. Buona giornata, signore."
S["6f9dcb62"] = "Interessante... Questo è più di quanto mi aspettassi. Delizioso..."
S["6fa06594"] = "Non mostrate pietà a questi selvaggi, soldati! Loro non ne avranno per voi!"
S["6fa43fd5"] = "Che promozioni avete?"
S["6faeab86"] = "Finalmente! Non vedo l'ora di dormire un po' stanotte."
S["6fb2b291"] = "Il torio incantato è un metallo molto ricercato. Se vuoi trovarne, ti conviene parlare con un fabbro artigiano o con un minatore."
S["6fb2c262"] = "Mentre cadete in battaglia, noi diventiamo sempre più forti. C'è un solo esito inevitabile. Preparatevi alla vostra fine!"
S["6fb69f58"] = "So che lo farai, $N.$B$BSono una sacerdotessa anch'io, ma a differenza di te ho lasciato questo mondo da molto tempo. Il mio spirito, però, è ancora qui, come quelli delle migliaia di persone che il folle Principe, Arthas Menethil, e la sua legione di non morti hanno massacrato brutalmente."
S["6fb7046f"] = "Non è stata colpa sua, $N. Diglielo..."
S["6fba6fbc"] = "Se resti $Gfermo:ferma; a riposare ancora qualche istante vicino alla tenda che ho montato qui dietro, ne avrai un beneficio."
S["6fbe73d0"] = "Ho quasi abbastanza provviste per potenziare le nostre truppe."
S["6fca1327"] = "Guarda, laggiù! Per Hive'Regal! Quello è... un sandworm?!"
S["6fcec9c7"] = "Gli umani hanno bisogno del tuo aiuto nella lotta contro i Forsaken nell'Arathi Basin. Vai all'Hall of Arms e parla con il loro rappresentante, Donal Osgood."
S["6fd18479"] = "Non preoccuparti per me, per ora starò bene. Quando avrò compiuto dei rituali di purificazione in questa stanza, troverò il modo di uscire da qui. Una magia immonda contamina questo luogo, $N."
S["6fd7a6cf"] = "Cerchi un istruttore di alchimia? Beh, proprio così, ci sono appena $Gstato:stata;. La signora Berryfizz la trovi a Tinker Town, dove si ritrovano gli gnomi."
S["6fdb05a9"] = "Throm tago gul'rok raznos kek gezzno."
S["6fdc3830"] = "Non evocarmi più a meno che tu non abbia una vera domanda da farmi, ok?"
S["6fe0a26f"] = "Salute, $C. Io sono Rexxar: campione dell'Orda, servitore di Thrall, padrone delle bestie delle terre selvagge."
S["6fe35fca"] = "Possa questo combattimento insegnare qualcosa a entrambi."
S["6fe9213b"] = "Tempesta di sabbia in arrivo da sud, al ripa...Quella non è una tempesta di sabbia! ARRIVA L'ESERCITO QIRAJI!"
S["6fea754a"] = "Di qua, $Gbuono:buona; a nulla...! Se vuoi renderti utile, stammi a sentire, presto!"
S["6ff7410f"] = "Tenaron e Corithras non mi deluderanno più. Quanto a te, $Gmessaggero:messaggera;, ti concedo un'ultima possibilità solo perché è la prima volta che mi intralci!"
S["6ff8b179"] = "%s sembra sul punto di vomitare!"
S["6ffb7932"] = "Le tue intromissioni negli affari demoniaci finiscono ORA, mortale! Affronta il grande corruttore — Xandivious!"
S["6ffde6e3"] = "Non è il momento, $N.$B$BSei $Gpazzo:pazza;?!"
S["70027772"] = "Intrusi! Invasori! L'Occhio che Tutto Vede è stato rubato! Quel cane miserabile, $N, ce l'ha in suo possesso!"
S["700c36c5"] = "Con i materiali che trovo da queste parti posso creare cose straordinarie. Per la barba di Muradin, su queste colline ci sono creature fantastiche! Va' a dargli una bella botta, $N, e torna a raccontarmi qualche storia da non crederci."
S["700ff41f"] = "Benvenuto, fratello mio. Se sei qui per addestrarti, ti istruirò con piacere.$B$BMentre Malfurion giace nel Sogno, siamo noi i custodi dell'equilibrio, ora e per sempre. Non scordarlo mai."
S["701050f5"] = "Ciao, $N. Se ti interessa imparare qualcosa di cucina, vieni da me quando vuoi."
S["70140cd9"] = "Non vedi che sto pescando!"
S["701bc713"] = "Invasori, smettete subito questa folle impresa! Tornate indietro finché potete!"
S["701c7378"] = "%s aspetta che le guardie si allontanino."
S["701eaa83"] = "Servi bene la Luce, $C."
S["70248228"] = "Salve, Quinn. Come stai?"
S["702e14de"] = "Vuoi diventare $Gun sarto:una sarta;? Mmm... All'Eastvale Logging Camp, credo, c'è qualcuno del mestiere che potrebbe darti una mano a cominciare."
S["7036e7de"] = "Allora devi andare a Orgrimmar. La strada che esce a nord da Razor Hill ti ci porta dritto. Là parla con uno dei grunt: ti darà altre indicazioni."
S["703a8882"] = "Come osi profanare questo luogo antico!"
S["703ddfe3"] = "Mi hai fatto arrabbiare per l'ultima volta, $N!"
S["7040d8bd"] = "Il mio papà dice che nell'oceano ci sono pesci così grossi che potrebbero inghiottire una nave intera."
S["70440972"] = "Il Capitano Ballinda Stonehearth arriverà presto alla sua guarnigione. Presto si combatterà una nuova battaglia!"
S["70481305"] = "<Deathguard Billmuth si agita distratto e si guarda intorno, nervoso. Si vede che stare qui lo mette molto a disagio.>"
S["704b4f50"] = "Per un po' ho vissuto a Dire Maul. Mi sono divertito. Davvero."
S["704db7a7"] = "Bleah... quello non è un pesce!"
S["705deff1"] = "Con pazienza e determinazione si possono svelare molti segreti. Ora, cominciamo..."
S["7066a885"] = "NEFARIAN È STATO UCCISO! Popolo di Orgrimmar, inchinatevi davanti alla potenza di $N e dei suoi alleati, perché hanno inferto al Black Dragonflight un colpo che di certo scuoterà gli Aspetti dal loro torpore! Il padre del Black Flight sentirà di certo questa sconfitta: Deathwing in questo giorno si contorce nel dolore e nell'angoscia!"
S["70692a15"] = "Dov'è finita la mia trottola? Ce l'avevo qui un attimo fa, da qualche parte..."
S["707a1750"] = "Ho poco tempo per le chiacchiere, $N. Questo ponte va ricostruito prima che arrivino le piogge. Tutti i miei lavori li ho finiti nei tempi e senza sforare il budget, e non ho intenzione di cominciare a sgarrare proprio adesso."
S["707e2811"] = "Giovane $C."
S["70818f29"] = "Sarà fatto, Eranikus. Sta' bene, antico."
S["70999cb6"] = "La corruzione dell'House of Nobles ti scorre nelle vene. Lascia che te la tolga con la mia lama!"
S["709b951a"] = "Osi profanare questo suolo sacro?"
S["70a1eaa0"] = "Il mio signore andrà su tutte le furie quando saprà di questo agguato. Speriamo che la tua morte lo plachi."
S["70a2e0c2"] = "Ah... gli eroi. Siete ostinati, eh? Il vostro alleato qui ha cercato di misurare il suo potere con il mio, e ne ha pagato il prezzo. Ora servirà me... massacrandovi."
S["70a35a2a"] = "Prendi questo, bevilo tutto."
S["70b4ca7a"] = "So chi sei, $N. Il fato, e forze che vanno oltre, ti hanno condotto da me per una ragione, e non mi fa alcun piacere farne parte. Nei tempi a venire prenderai molte decisioni: spero che tu sia abbastanza $Gsaggio:saggia; da prendere quelle giuste.$B$BCredimi, $R — le scelte giuste esistono."
S["70b6a3b5"] = "Cos'hai fatto, Isillien? Un tempo combattevi con onore, per il bene del nostro popolo... e ora... hai ucciso il mio ragazzo..."
S["70cc3670"] = "Io... credo di vedere il Blu..."
S["70d2e36c"] = "Qualche spicciolo per un povero cieco? ...Come, non sono cieco? ...NON SONO CIECO! CI VEDO!! È un miracolo!"
S["70d5d6bd"] = "Non volevo trascinarti in questa storia, $N. Da quando abbiamo accettato il lavoro di rubare il libro degli incantesimi di Lord Valthalak, tutti quelli coinvolti sono finiti morti o scomparsi."
S["70db5f86"] = "Ah, tu! Ho dei compiti da affidarti, e non c'è bisogno che perda tempo a spiegarti quanto siano cruciali. Ascolta bene."
S["70dfe200"] = "$GBenvenuto:Benvenuta; a Dalaran, $C.$B$BNon badare ai lavori ancora in corso, ti prego. Ah, se dovessi trovarti davanti un'anomalia arcana fuori controllo, un demone o un'altra entità maligna, non esitare a chiedere aiuto al membro del Kirin Tor più vicino prima di fuggire — ehm... procedere — con ordine verso l'uscita più vicina!$B$B<Arcanist Laurain ride nervosamente.>$B$BGrazie della visita!"
S["70f31640"] = "Aspetta qui, $N. Spybot farà uscire Lescovar il prima possibile. Tieniti $Gpronto:pronta;! Attacca solo dopo aver ascoltato la loro conversazione."
S["70f6f51e"] = "Per le nostre creazioni usiamo tante pellicce e pelli di animali."
S["70f8ae6f"] = "Ti piacerebbe fare $Gil cuoco:la cuoca;? Per addestrarti devi andare a Undercity, a sud della città. In fondo alle Ruins of Lordaeron ci sono gli ascensori che scendono; una volta $Garrivato:arrivata;, chiedi altre indicazioni a uno di quei goffi Undercity Guardians."
S["70fd33cd"] = "Parla piano e fai molta attenzione: da queste parti, per una parola sbagliata potresti ritrovarti con la gola tagliata. Allora, cosa ti serve?"
S["7100ea56"] = "La battaglia per Warsong Gulch comincia fra 1 minuto."
S["71043e40"] = "Ultimamente il flusso della magia è caotico e imprevedibile. Quale ne sarà la causa, mi chiedo?"
S["71084b3b"] = "Un momento."
S["710f1522"] = "Che le spire dell'odio si srotolino!"
S["711f9ea5"] = "All'inizio mi ero sistemato nel Magic Quarter, ma lì c'era parecchio rumore. Questo è decisamente un miglioramento, a parte qualche allievo ostinato che riesce ancora a scovarmi, nonostante mi sia trasferito."
S["7120f5a4"] = "Mi scuso: non sono in grado di elaborare il tuo riferimento cronologico rispetto alla registrazione di questi dati.$B$BIn parte il trogg conserva la composizione dei vari composti del nucleo di pietra di Azeroth, ma per i Creatori la perdita delle capacità cognitive rende questa variante inaccettabile.$B$BIl trogg si riproduce come una biomassa standard. Per impostazione predefinita si nutre di pietra e di qualsiasi altra cosa riesca a procurarsi, compresi altri troggs. I Creatori considerano il cannibalismo inaccettabile."
S["7121d7b5"] = "Sulla Stonetalon Mountain le grotte pericolose sono tante, sparse per tutta la regione. A chi è disposto a rischiare la vita per la gloria, esplorarle può riservare un'avventura dopo l'altra.$B$BForse, $C, cerchi ricchezze che si ottengono solo seguendo il cuore e l'anima."
S["71226ea9"] = "Usato dalla famiglia Barov della Scholomance come specchio sulle anime che non possiede più. Un ricordo prezioso."
S["71231a73"] = "Conosco la strada, insetto. Non c'è bisogno di pungolarmi come se fossi bestiame."
S["712f8d3e"] = "Che la Luce sia con voi, signore."
S["713290ef"] = "Sei sempre stato il piantagrane della famiglia, Noggle. Sempre!"
S["7134ba76"] = "%s comincia a evocare dei guardiani!"
S["7138fc5e"] = "%s lancia un'occhiata ai suoi compagni."
S["713ca21f"] = "I Defias possono prendersi questo posto senza pericolo! Chiama gli altri."
S["713e5877"] = "Shai, Merok! Al mio fianco!"
S["715dc031"] = "In questo momento la Darkmoon Faire è nell'Elwynn Forest, appena a sud di Goldshire. Non perdertela!"
S["715e8d7f"] = "Non sapevo che alle api non piacesse il fuoco!"
S["7161b33d"] = "Aiutatemi, mia covata!"
S["71656bf3"] = "Fluffy! Fluffy, smettila di scappare!"
S["716dbdc2"] = "Dum zu eft gar havar eft grum ta goten haldir, dun rune gar hor gosh farode grum gar A zu rugosh Dum kost hrim um helm."
S["71746001"] = "Parla con Regthar. È saggio e può aiutarti a trovare ciò che cerchi."
S["7176812c"] = "Non combattete con armi e armature rotte! Riparazioni esperte di armi e armature, qui — mentre aspettate!"
S["717aca6d"] = "Eh? Hai affari da fare con Nimboya?"
S["717b86da"] = "Agli Elfi della Notte piace stare su una gamba sola mentre lanciano incantesimi. Colpite quella gamba, così..."
S["71823efa"] = "E questo è Comar Villard. Sposato da due settimane, sua moglie fu portata via dalla sicurezza di Menethil Harbor."
S["719d2cdd"] = "I non morti banchetteranno con la tua anima, $N."
S["71a31573"] = "Ora è il momento di porre fine al suo regno, Marcus. Fatti da parte, amico."
S["71a654e0"] = "Cercalo in alto, sul lato ovest della Valley of Strength. Ti fanno entrare solo se sei $Gun ufficiale:un'ufficiale;! Sennò parla con Sergeant Ba'sha, lì fuori."
S["71a87eca"] = "A-Me, casa. A-Me andare casa! $N, no fermare A-Me."
S["71b27f08"] = "%s sembra molto più calmo ora che ha mangiato i resti di $N."
S["71b8373e"] = "Un potente Qiraji noto come General Rajaxx avrebbe guidato la prima incursione a Silithus. Solo uno si sarebbe messo sulla sua strada: un elfo della notte noto come lo Staghelm. Lo chiamano Khar'sis, cioè 'mano della terra' nella lingua dei Qiraji."
S["71ccb9d5"] = "%s si passa l'indice sulla gola, mimando un taglio."
S["71d6af83"] = "Oh, cielo! Guarda in che stato sono questi libri! Chi li ha rimessi a posto senza metterli in ordine alfabetico??"
S["71d9e1b9"] = "Se cerchi dei ladri, devi andare nell'Old Town. Sta nell'angolo nord-est di Stormwind."
S["71e7bf31"] = "Basta! Parlerò. Mettete via le armi, non è con me che ce l'avete."
S["71ed5f3b"] = "Remulos, vengo richiamato indietro... Tyrande... dille che la amo... Dille che sono al sicuro. Dille... dille che tornerò... Addio..."
S["71f4939c"] = "Qui alla loggia dei Farstrider l'abilità nella caccia conta più di ogni altra cosa. Vuoi la mia approvazione? Te la dovrai guadagnare.$B$BMi sembri all'altezza della sfida, $Gragazzo:ragazza;!"
S["71fec2c0"] = "Ehi, $Gsignore:signora;, mi daresti una mano con una cosa? Sono nei guai fino al collo..."
S["720ad7ab"] = "Le fattorie vanno liberate. Stormwind avrà anche abbandonato questa gente, ma io no, che mi venga un colpo."
S["720ba1ac"] = "Finalmente. Quel bastardo ha avuto ciò che si meritava."
S["720d49ca"] = "Lo rivoglio, mortale. Atiesh... Con esso ricreerei gli Highborne. Rivorrei tutto. Persino la Regina..."
S["720ee4b1"] = "Proprio mentre parliamo, $C, tutto il materiale bellico viene trasportato a Silithus. A quanto pare l'ultimo carico dovrebbe arrivare in meno di un giorno. Dopo di che $Gun eroe:un'eroina; dovrà venire a suonare il gong sulla Scarab Dais. Allora la guerra comincerà sul serio."
S["7210c78a"] = "Come mi sento? Piuttosto fradicio, grazie."
S["721139b1"] = "Seguimi, $N. Ti porto al nascondiglio dei Defias, ma vedi di proteggermi, o sono un uomo morto."
S["72259293"] = "<L'ariete allunga il collo verso di te, in cerca di grattatine.>"
S["7234e4fb"] = "Naralex dorme di nuovo!$B$BTanto tempo fa Naralex è venuto in questa caverna con un nobile scopo: entrare in The Emerald Dream e far rinascere le Barrens come una foresta rigogliosa. Ma la sua concentrazione ha vacillato, e visioni di serpenti gli hanno corrotto i pensieri.$B$BOra dai suoi sogni filtrano sulla terra bestie rettili. Bisogna risvegliarlo dall'incubo, o sarà perduto per sempre e si scatenerà un grande male.$B$BIl rituale del risveglio potrò celebrarlo solo quando saranno stati uccisi i suoi servitori corrotti, i Signori delle Zanne."
S["72361143"] = "Zug zug, $Gvaloroso:valorosa; $C! Ho da mostrarti dei lupi da cavalcatura della razza più pregiata. Da nessuna parte troverai un altro animale con la resistenza e l'istinto di sopravvivenza del lupo! Prego, guardali con i tuoi occhi."
S["7243771e"] = "Vedo che ti senti meglio."
S["72492a40"] = "Dalla cima del Sentinel Hill, Elder Skychaser osserva Westfall."
S["7251ba8e"] = "Dammi la tabarda #1!"
S["7251baad"] = "Dammi la tabarda #2!"
S["7251bacc"] = "Dammi la tabarda #3!"
S["7254649f"] = "$GPrendetelo:Prendetela;!"
S["7254aac6"] = "Portatemi con voi, $Gsignore:signora;."
S["726e09fe"] = "È l'edificio grande di Razor Hill, quello che non è la caserma. Lì dentro parla con Innkeeper Grosk. Capito?"
S["727275f4"] = "Cervello sfondato... mortaio... frac... assato... cola... muo... io..."
S["7272eef1"] = "Paladini stare in War Quarter, su anello esterno. Loro tu trovi dentro edificio principale."
S["72742e6a"] = "Engoth Nagan waldir! Far Gothalgos!"
S["7277333e"] = "C'è ancora luce, quindi vediamo quella tua ascia tagliare altra legna."
S["7278fa63"] = "Certamente, $Gsignore:signora;. Un tempo eravamo servitori della casa Barov, quella che oggi tutti conoscono come la Scholomance.$B$BIo ero la capocameriera, Lucien il maggiordomo del Padron Barov.$B$BAvevamo servito i Barov per decenni, finché...$B$B<Eva piange.>"
S["72790348"] = "Allora sei tu Klinfran the Crazed? Peccato, mi aspettavo una vera sfida. Osi affrontarmi nella tua vera forma?"
S["727a88ea"] = "Unisciti a noi, o cadi per sempre!"
S["729f98af"] = "Vieni. Dobbiamo andare avanti. C'è molto da fare prima di strappare Naralex all'incubo."
S["72a33c7b"] = "Drek'Thar, vengo a prenderti!"
S["72a3d3ca"] = "Voglio vedere la Torre dei Maghi."
S["72babb4f"] = "I miei studi mi dicono che sconfiggere l'avatar del dio Hakkar lo ha indebolito. Ma il grosso della sua forza è ancora lì, in agguato all'estremità più lontana del Nether.$B$BIl suo avatar l'hai già sconfitto una volta, $N. Se lo batti di nuovo, forse indebolirai ancora il dio, e un giorno potremo affrontarlo nella sua vera forma.$B$BCon l'incantesimo che ho preparato puoi evocare di nuovo un avatar di Hakkar nel Sanctum of the Fallen God. Vuoi affrontarlo un'altra volta?"
S["72be4891"] = "No! Non dovete farlo!"
S["72bfdc8f"] = "Dhugru Gorelust lo trovi dietro la caserma, sul lato est di Razor Hill."
S["72c1bf9e"] = "%s tira fuori una bottiglia piena di uno strano liquido verde e ne butta giù un gran sorso."
S["72d7e0c0"] = "PER MAGNI!"
S["72dcb4f5"] = "Mi preparo a salire sul crinale, $N. Mi farebbe comodo un aiuto — ti va di venire con me?"
S["72e0b72f"] = "Ascolta bene, $N: ho molto da insegnarti."
S["72e56a0f"] = "Ok, basta! Mi arrendo!"
S["72e5f09d"] = "Salute, $Gviaggiatore:viaggiatrice;! Hai voglia di addentrarti nei misteri dell'arcano? Mh?"
S["72e9043d"] = "Abbiamo raccolto molti rifornimenti per la ricostruzione, ma ce ne servono ancora molti di più per riparare Dun Baldar. Continua a portarmi rifornimenti!"
S["72ee3915"] = "Hai portato a termine la missione di Teronis, $N, e ti sono grata per tutto quello che hai fatto."
S["72eeb4ab"] = "Erbalismo"
S["72efd729"] = "Il Sunken Temple sta in mezzo a un grande lago, nella parte orientale della Swamp of Sorrows."
S["72f08102"] = "%s cammina avanti e indietro, nervosamente."
S["72f204d5"] = "Esatto!"
S["72f6cbe0"] = "Ecco Stormwind Keep. È stato costruito sulle rovine dello Stormwind Castle, distrutto dall'Orda durante la prima Great War."
S["72fc5630"] = "Non voglio avere niente a che fare con Silithus, con i Qiraji e men che meno con dei maledetti draghi!"
S["72ff01f7"] = "Per il Dark Strand!"
S["73010c0b"] = "L'Alleanza ha completato i suoi compiti di raccolta, $C. Ora, mentre imballiamo e prepariamo tutto, aspettiamo che le raccolte dell'Orda siano completate. Poi trasporteremo tutti il nostro materiale bellico a Silithus."
S["7303b893"] = "Tremate, mortali! L'era dell'oscurità è vicina."
S["731899ca"] = "Se vuoi migliorare ancora, dovrai cercare Nat Pagle nella Dustwallow Marsh."
S["73329e52"] = "Durante l'escursione di ieri, Marduk ci ha mostrato che i draghi tollerano la carne di umanoidi uccisi di recente, ma solo se sono morti lentamente e dolorosamente."
S["73354567"] = "Dalla pietra si leva una voce limpida...$B$BTi presenti a noi con un titolo, e per questo ti ascolteremo; ma non mettere alla prova la nostra pazienza, $C. Il consiglio non ha tempo per le chiacchiere inutili di $Guno:una; come te."
S["7347e27d"] = "Un minatore? Non è questione di se, $Gragazzo:ragazza;, ma di dove! Quello che cerchi è Yarr, e credo che lo troverai rintanato laggiù allo Steelgrill's Depot."
S["734cfc83"] = "Sbrigati, $Gforestiero:forestiera;."
S["7354f0aa"] = "Com'è potuto succedere?"
S["735775ee"] = "%s afferra il suo pugnale avvelenato!"
S["735a3298"] = "Lo Scourge sta allestendo piccoli punti di raccolta nei luoghi sotto attacco, dove riceve comunicazioni e altri aiuti dalle necropoli che volano sopra di essi. Da quel che possiamo capire, l'unico modo per stanarli è uccidere le forze di terra che circondano quei punti."
S["7364dd9f"] = "Ecco, è fatta. Il libro è stato potenziato..."
S["73675af2"] = "Ehilà, $Gsignore:signora;. Io farei attenzione a dove metti i piedi da queste parti, ho perso una bomba travestita da mouse e non riesco a trovarla."
S["7367beee"] = "Il successo è nostro! Il Cristallo Ash'ari è stato ripristinato!"
S["736ede6a"] = "Al lavoro, feccia!"
S["73721fd7"] = "Questo è il campo di battaglia dell'Alterac Valley. Entrambe le parti stanno ancora combattendo."
S["73822a51"] = "Bada a dove metti i piedi da queste parti, ragazza. Non sarai dei nostri, ma questo non vuol dire che non ti prenderò a bastonate se non righi dritto!"
S["7385c8b2"] = "Vil borne aldonoth ras bor goibon lars.  Gol lon odes mod!"
S["73920adb"] = "I Signori delle Zanne sono morti! Non tutto è perduto!$B$BMa il rituale del risveglio è piuttosto complicato, e da soli non si può compiere.$B$BAi preparativi penserò io, ma tu dovrai proteggermi. Gli incubi evocati dal viaggio di Naralex in The Emerald Dream si stanno rivelando davvero temibili: senza il tuo aiuto, questa missione è destinata a fallire.$B$BQuando sarai $Gpronto:pronta; a difendermi, dimmelo e ti porterò fino alla stanza di Naralex."
S["73971d48"] = "Dovrei avanzare qualche moneta da questa vendita. Magari mi compro il pranzo..."
S["739c8b3b"] = "Il Cenarion Circle è saggio e si è addentrato in molti segreti della terra. Gli artigiani farebbero bene ad ascoltare le parole dei suoi druidi."
S["739ead25"] = "La leggenda dice che nei luoghi di conflitti estremi, in quelle che oggi sono chiamate Plaguelands, dal terreno possono sgorgare sorgenti pure e sacre. L'acqua di quelle sorgenti è stata chiamata 'Sangue degli Eroi' da artigiani e gente comune, in onore di chi è caduto nella guerra contro lo Scourge."
S["73a3b3b8"] = "<Eris annuisce.>$B$BL'Occhio ha visto così tanti orrori e così tante meraviglie.$B$BA chi ci guarda dentro mostra ciò che sente più adatto a lui."
S["73aa598b"] = "<Lady Prestor ti fulmina con lo sguardo.>"
S["73b5930a"] = "Invasori dall'entroterra! Fuoco!"
S["73b8757f"] = "Grazie ancora, $C. Da qui credo di farcela a tornare al sepolcro. Raggiungimi lì e riprendiamo il discorso."
S["73ba51a4"] = "<High Inquisitor Fairbanks scuote la testa.>$B$BNo, $R: è morto solo uno dei suoi figli. L'altro è vivo...$B$B<High Inquisitor Fairbanks indica il cielo.>$B$BL'Outland... Trovalo lì..."
S["73c861f2"] = "Bada a dove metti i piedi da queste parti, figliolo. Non sarai dei nostri, ma questo non vuol dire che non ti prenderò a bastonate se non righi dritto!"
S["73d0ace1"] = "Riposiamoci solo un momento."
S["73d25431"] = "Se invertiamo i flussi di Essenza, forse possiamo cambiare la polarità."
S["73d499b1"] = "L'Alleanza ha preso le stalle!"
S["73d8e8bd"] = "Senti, nella tua voce avverto una certa incredulità — ma sì, è andata proprio così."
S["73df492b"] = "Ehi Stone, facciamo una gara qualche volta? Potremmo correre qualche giro e vedere chi vince?"
S["73dfd19d"] = "Maestro Vectus, percepisco qualcosa di strano in questo contenitore..."
S["73e4bdfe"] = "Urrà, urrà! $N! È fatta!"
S["73e5a626"] = "Combattenti pronti... COMBATTETE!"
S["73f78167"] = "I ravasaur qui a Un'Goro sembrano parenti dei raptors delle savane — molto intelligenti, imprevedibili, e con un senso, o un codice, di condotta. Il più grande che abbia incontrato è Lar'korwi, una delle bestie più pericolose che abbia mai visto. In taurahe, Lar'korwi vuol dire \"artiglio affilato\", ma è un nome che non gli rende giustizia.$B$BSe mai deciderai di dargli la caccia, non sottovalutare Lar'korwi; in quel caso, però, ti aiuterò in ogni modo possibile."
S["74127b87"] = "Cosa ci fai qui? Vattene subito, in fretta. Rovinerai tutto!"
S["741b2fd8"] = "Il Popolo di Westfall rende onore a Healé, coraggioso e valoroso difensore della libertà."
S["74239508"] = "Ehi! Che succede?"
S["742616b0"] = "Inseguimi se ne hai il coraggio! Io corro spensierato!"
S["742b5e5a"] = "Ho finito, $Gfratello:sorella;. Il resto fallo tu. Io me ne torno a riposa' sulla roccia."
S["742fa5e1"] = "Grazie! Grazie, $Gsacerdote:sacerdotessa;. Ora posso affrontare quegli gnolls con il tuo potere a sostenermi!"
S["7442e3f8"] = "Lo Stonehearth Bunker protegge il fianco orientale del Field of Strife.$B$BÈ controllato dall'Alleanza."
S["74436653"] = "Sei Tenenti controllano le difese della prima linea. Vanno distrutti per primi, e in fretta! Non possiamo rischiare che uno dei loro sacerdoti riporti in vita i Tenenti caduti.$B$BSe tutti i Tenenti verranno uccisi uno dopo l'altro, il morale della prima linea vacillerà! Andrà in frantumi! Le loro truppe fuggiranno terrorizzate, lasciando i soldati rimasti senza rinforzi."
S["744c6cbb"] = "Inconcepibile!"
S["744d1cb0"] = "%s punzecchia il piccolo toad."
S["74579ed0"] = "Da come stai in piedi si vede subito che non sei $Gun guerriero:una guerriera;.$B$BPerché non vai a fare qualcosa di sicuro, come leggere un libro."
S["745d2551"] = "%s contrattacca con una rappresaglia."
S["745ed185"] = "Hakkar non mi vincola più! Finalmente la pace!"
S["74668229"] = "Hai delle corna da affilare, eh? Nella parte più bassa della rupe centrale troverai un goblin che può aiutarti."
S["746cedc9"] = "Grazie mille... Da qui trovo la strada per il Whitereach Post. Assicurati di parlare con Motega Cresta Ardente: magari riesci a convincerlo a non rimandarmi a casa."
S["74780d8e"] = "Una notte il maestro artigiano Omarion è sparito. Come un peto nel vento... Puf! Svanito! Bah, e adesso a fabbricare la roba per i ragazzi al fronte sono rimasto solo io."
S["747bd458"] = "$N, assicurati che i tuoi alleati siano preparati e, quando sarai $Gpronto:pronta; ad affrontare Lorthuna, vieni a parlarmi."
S["747ea247"] = "Abbiamo raccolto abbastanza pelli dai lupi. Presto la cavalleria sarà pronta a cavalcare! Parlami di nuovo quando avremo messo nelle stalle abbastanza arieti."
S["7489bfdf"] = "Bah, è roba da goblin! Comunque, qui a Razor Hill c'è un orco che te le insegnerà. Cerca Mukdrak, laggiù vicino alla forgia."
S["749208bc"] = "Il mio potere è devastantemente sconquassante! È ridicolo che questi mortali provino anche solo a entrare nel mio regno!"
S["749344bd"] = "Mi godrò questo momento, $C."
S["7495acd4"] = "Temevo di non rivedere mai più i rami di Teldrassil."
S["7495fb1a"] = "I costrutti ci aiutavano a pescare a strascico nel Windsong Lake e, quando i piloni hanno cominciato a cedere, molti sono finiti negli abissi. Sul fondale del lago potrebbero esserci dei pezzi ancora utilizzabili, se te la senti di fare una nuotata."
S["749bde53"] = "Saluti, $C. Sono Leoren, il maestro delle scuderie di Cenarion Hold."
S["74b2b839"] = "Be', ecco cosa mi merito per aver dormito troppo!"
S["74b31c71"] = "Lo spirito di Stonetalon piange. Piange dalle vette dei monti ai fiumi, fino agli alberi abbattuti e morenti."
S["74b51b96"] = "I nostri cammini nella vita si incrociano solo per poco, e ora è tempo che si separino. Mi considero benedetto per aver trascorso questo tempo a insegnarti, e ora ti mando a unire il tuo cammino a quello del tuo prossimo mentore. Cerca Saru Steelfury a Orgrimmar, ti insegnerà ciò che devi imparare."
S["74bbc2fe"] = "Che bello vedere una faccia amica. Con Apothecary Johaan non scambio molte chiacchiere, a meno che non gli serva qualcosa. È fuori dalla tomba da troppo tempo, e dicono che un giorno diventerò così anch'io. Inquietante. Magari per allora non me ne importerà."
S["74be890a"] = "Addio, e che i nostri antenati siano sempre con te!"
S["74c063a3"] = "La Battaglia per l'Arathi Basin inizierà fra 1 minuto."
S["74cd4bb5"] = "$GBentornato:Bentornata; nella luce, $Gamico:amica;. Ti serve addestramento?"
S["74d019e0"] = "%s si ferma e osserva il mare di soldati che stanno nervosi davanti a lui."
S["74ec7276"] = "Bene, qui dobbiamo davvero stare all'erta. Tieniti $Gpronto:pronta;!"
S["74ee71b1"] = "Vanndar Stormpike è il generale dell'esercito dell'Alleanza ad Alterac e guida le sue forze da Dun Baldar.$B$BSe verrà sconfitto, l'Alleanza perderà di certo la battaglia per Alterac.$B$BVanndar al momento non si trova nell'Alterac Valley."
S["74f000bc"] = "Mmh... be', per ora non posso aiutarti! Prima devi imparare le basi: perché non vai a trovare Sprite Jumpsprocket a Stormwind!"
S["74f4d380"] = "Bravo, Gerard, ti sei superato ancora una volta."
S["750469e1"] = "Freshly baked bread in vendita!"
S["75083174"] = "Grazie, $N! Sei $Gl'eroe:l'eroina; dell'Un'Goro Crater!"
S["750d995f"] = "Hai sentito parlare del Tram, eh? Che viaggio, quell'affare! Lo trovi in fondo al Dwarven District. Ah, e quando è in movimento, mi raccomando, tieni braccia e gambe dentro il tram."
S["75131715"] = "Allora, che ne dici di recapitare un messaggio per conto mio?"
S["7514a2ab"] = "Ascolta chi ha più esperienza di te, $N. Con una volontà forte, se sei $Gdeterminato:determinata;, non c'è potere che tu non possa controllare."
S["7518c120"] = "HA! Un bluff patetico! Ferauu ha occhi e orecchie ovunque. So che ci siete solo tu e $Gquesto straniero mingherlino:questa straniera mingherlina;. Ti sei divertita a far fuori qualcuna delle mie reclute più deboli, ma ora c'è il Randello, e la festa è finita. È ora di pagare, con gli interessi."
S["75206fab"] = "Spero proprio che restino vivi abbastanza a lungo perché possa... presentarmi."
S["7527232e"] = "Li vedi, mortale? No... Immaginavo di no. Tu vedi, eppure sei $Gcieco:cieca; — questo è il tuo dono e la tua maledizione."
S["75281316"] = "Terrore, oscurità, potere? I Forsaken non bramano queste cose; i Forsaken SONO queste cose."
S["7529fee7"] = "Maestro delle Stalle"
S["752a7140"] = "Che professione?"
S["753d8a50"] = "Dai, Fluffy! Voglio solo farti il bagno!"
S["7542625a"] = "Un goblin che si rispetti ha un solo obiettivo: cercare la ricchezza.$B$BBeh, forse la ricchezza... e una morte grossa e rumorosa!"
S["7549da1e"] = "Non fidarti di chi va in giro con una tunica grigia e la testa rasata. Si fanno chiamare Al'Aketh, e sono una minaccia.$B$BHo sentito perfino che armeggiano con i piloni di ancoraggio intorno all'isola.$B$BA dar retta ai Windshapers, quei piloni sono l'unica cosa che tiene Zephras sospesa qui nel piano elementale. Manometterli sarebbe una follia!"
S["754ab777"] = "Non addestro quelli come te, $C. Va' a cercarti il tuo istruttore, prima che mi arrabbi."
S["754c77fb"] = "Ti interessa esplorare uno di questi dungeon?"
S["755c25a1"] = "L'Orda ha preso la Coldtooth Mine!"
S["756fe2b8"] = "Ora sei $Gmio:mia;."
S["75777af2"] = "%s sente la richiesta d'aiuto e si prepara alla battaglia!"
S["7577fdab"] = "Lo Stormpike Graveyard è sotto attacco! Se nessuno lo difende, l'Alleanza lo conquisterà!"
S["757f9d15"] = "Ripassiamo i risultati trovati su quel pilone, nel caso avessimo tralasciato qualcosa."
S["7590213d"] = "Hai la mia parola che troverò un uso per il tuo corpo, dopo averti ucciso, $R."
S["75903754"] = "La casa d'aste è sulla guglia centrale di Thunder Bluff: cercala vicino alla base della Windrider's Tower. Che i tuoi antenati veglino su di te."
S["7596ff6c"] = "Arriva la morte! Gioite!"
S["759ec542"] = "Ho scoperto come usare il carapace del crypt fiend e le varie parti del suo corpo. Unendo i frammenti ad alcune delle armature magiche profanate perdute a Naxxramas, posso realizzare un'armatura leggerissima e davvero letale."
S["75a50de1"] = "Tenevo da parte questo posto per qualcosa di speciale. Non credo esista niente di più speciale di questo, $N."
S["75bdf3be"] = "Un tempo accoglievo l'oscurità, perché era la sorella della notte. Ora è buio sempre, anche di giorno, e le foreste implorano nutrimento. Se non agiamo presto, questo morbo che si sta diffondendo coprirà il mondo."
S["75c18e44"] = "Divertiti a Booty Bay, $N!"
S["75c273ae"] = "Sembra che i Southsea Freebooters siano ben trincerati sulla costa. Potrebbe mettersi male."
S["75c5e4e1"] = "Sono $Gsano:sana; di mente quanto chiunque altro, $Gamico:amica;. Credi pure quello che vuoi, ma quest'armatura SONO in grado di realizzarla. Se ti interessa, forse possiamo fare un affare: prima chiudo con il mestiere di assassino, meglio è."
S["75d68630"] = "Il Comandante è stato ucciso! Caricate le loro linee! Morite con onore!"
S["75d82207"] = "Sarà la vostra rovina!"
S["75e40cad"] = "Algaz hor gor dun haldir ta gar?"
S["75fd3e58"] = "Benvenut$Go:a; nella mia forgia, fabbro. Lascia che ti confidi un piccolo segreto. Di nessuno, di nessuno al mondo puoi fidarti. Non degli uomini, non delle donne, non delle bestie... di questo puoi fidarti: l'acciaio."
S["75fe60d4"] = "Finalmente libero dalla sua morsa maledetta. Padre, sto arrivando..."
S["75fffd89"] = "Grazie, $Gbuon:buona; $C."
S["76017246"] = "Nemmeno mio padre avrebbe potuto pianificare una tragedia simile... un caos simile. Non ce la farete mai! Il tempo sta per scadere!"
S["760c8797"] = "La tua prossima scelta ti attende.$B$BSei $Gil boia giurato:la boia giurata; del tuo signore. Ti hanno consegnato un uomo da giustiziare come traditore del sovrano e del tuo popolo. Per te è un amico intimo e virtuoso, sparito misteriosamente un giorno. Sai anche che i crimini per cui l'hanno condannato avrebbero fatto morire molti civili innocenti. Appena ti vede, ti implora di risparmiargli la vita e sostiene di essere stato incastrato da un'autorità superiore.$B$BFai la tua scelta."
S["760e85f7"] = "Una meravigliosa Winter's Veil a te... ehm... bambina. I bambini buoni hanno diritto a speciali, ehm, sconti presso qualsiasi venditore di Smokywood Pastures qui in zona. Gnam."
S["7618d0a0"] = "Ce l'abbiamo fatta, $N!"
S["762b0418"] = "Se ti serve addestramento in alchimia, a Stormwind c'è un solo posto dove andare... Alchemy Needs. È in Mage Quarter, nella fila esterna di negozi."
S["7636332d"] = "C'è chi mi chiama... Impsy?"
S["763bf42a"] = "I Kolkar sono i più forti!"
S["763e2bc1"] = "Io così intelligente! I-N-T-E-L-I-G-G-E-N-T-E!"
S["763f744d"] = "Ecco, lei aveva il piatto di pesce, Comandante. Buon appetito!"
S["7643b78c"] = "Servito!"
S["76481487"] = "Prego, buona giornata."
S["764e83f0"] = "Prova superata, ben fatto! Ora possiamo andare avanti con l'addestramento."
S["7659731e"] = "Sia noto a tutti che $N, $C dell'Alleanza, si è $Gguadagnato:guadagnata; il rispetto eterno di Ironforge e di tutta l'Alleanza. Ha condotto grandi trattative con Timbermaw Hold e compiuto per loro imprese valorose a nome nostro. È $Gandato:andata; ben oltre il proprio dovere. Tre urrà per $N, $Gun vero eroe:una vera eroina; dell'Alleanza!"
S["765b9f5e"] = "Sì, sono io il famoso mercante che durante la recente guerra contro lo Scourge ha generosamente sfamato gli, ehm, affamati... bambini...? ...di Undercity. Sì, sono io il goblin d'affari visionario, il genio della logistica che da solo ha armato la resistenza e ha permesso alla nostra Dama Oscura di fondare la sua nazione di cadaveri puzzolenti... ehm, volevo dire, \"Forsaken\".$B$BGià, sono io in persona. Glix Xizzix. Un autografo te lo firmo volentieri. Per un piccolo compenso, s'intende.$B$BChe ci faccio qui con una bottega da barbiere, mi chiedi? Beh, amico, mi basta una parola sola — diversificazione. Le fonti di guadagno bisogna sempre diversificarle!"
S["765d31a2"] = "La natura ci dà tutto ciò che ci serve. Parla con Komin Winterhoof all'Holistic Herbalism, sull'altura di mezzo."
S["765f4df5"] = "Non posso più addestrarti: nel lavorare il cuoio ormai sei abile quanto me. Dovresti parlare con Una, laggiù. Se serve, garantirò io per le tue capacità."
S["76612b8f"] = "L'infestazione dei Blackrock è fitta da queste parti. Farò del mio meglio per tenere il passo, Большой. Andiamo!"
S["76633f8d"] = "Un mio ex allievo, un certo Krixix, ha passato una vita intera a cercare un contatto con gli Dei incatenati del mondo sotterraneo. Inseguiva ciò che sarebbe sorto dalla terra devastata... Ciò che sarebbe nato soltanto dallo scontro degli elementi in un conflitto titanico.$B$BElementium, come l'avrebbero chiamato i mortali.$B$BUn giorno, quasi dieci anni fa, la ricerca di Krixix ha aperto una fessura proprio in questa gola."
S["766b805b"] = "L'hanno chiamata Bandarion Keep. Chissà che ne penserebbe Garek?"
S["766e3efd"] = "Mi spiace, sorella, ma non vendo i miei raptors a chi non ha dimostrato di essere amichevole con la tribù Darkspear. Quando ti farai valere e mostrerai di essere almeno amichevole con noi, allora ti darò i miei raptors."
S["7673f911"] = "Esatto, siamo $Gstupidi:stupide;. $GStupidi:Stupide; come una Volpe!"
S["76763507"] = "Ti insegnerò un'abilità di equitazione solo quando sarai $Gosannato:osannata; presso i nani di Ironforge, $C."
S["767bdc5e"] = "Vorrà le nostre teste se ci scoprono!"
S["76864a4e"] = "%s annusa l'aria con fame, sentendo l'odore di lion meat fresca..."
S["769179ed"] = "Beh, se devi volare da qualche parte, su a Stormwind c'è un maestro dei grifoni. Mentre attraversi la Valley of Heroes, dovresti vederli atterrare alla tua destra."
S["76976bfe"] = "Affretti la nostra... distruzione..."
S["7697fc42"] = "Il mio altare ti risucchierà la vita!"
S["769e9d39"] = "%s va su tutte le furie!"
S["76ad4be4"] = "Prendi questo, arpia rognosa! Hyaa!"
S["76afb6fd"] = "Ah, $N. Che piacere vederti. Con tutto l'aiuto che ci hai dato, nelle nostre sale sei $Gun ospite gradito:un'ospite gradita;.$B$BTi prego, sentiti a casa tua: Dalaran ti deve almeno questo."
S["76b99535"] = "Hip hip urrà per $N! Questa terra tornerà nostra!"
S["76be5705"] = "Su una tavoletta d'oro puro era incisa l'incarnazione del mio rimorso, della mia vergogna, del mio pentimento e del mio dolore. Purtroppo il Twilight's Hammer l'ha trovata e mi ha bollato come $Gblasfemo:blasfema;. Sono $Gstato:stata; $Ggiustiziato:giustiziata; sommariamente, senza poter finire la preghiera a Elune. Ora sono $Glegato:legata; a questo mondo come spirito, incapace di ascendere al Nether, e $Gtenuto:tenuta; in questa gabbia come monito per chiunque tradisca la fede del Twilight's Hammer."
S["76bf94ff"] = "No! Amico mio... cos'è successo? È tutta colpa mia..."
S["76c2f13e"] = "Captain Galvangar dell'Orda è stato ucciso. Sconfiggete Drek'Thar e la vittoria sarà nostra!"
S["76c3491d"] = "Per favore, non toccare le fiale se non hai intenzione di comprarne una.$B$BLe impronte ne rovinano il valore, capisci."
S["76ce5ff5"] = "Dimmi cosa ti serve, e sbrigati."
S["76dd03f7"] = "The Loch ora appartiene alla Tribù Stonesplinter, $N! Adesso muori!"
S["76e633a6"] = "Il Capoguerra porta un cambiamento che darà la vittoria all'Orda! Cerca Swart nella caserma, sul lato est della città."
S["76f07507"] = "Dov'è il Frostwolf Quartermaster?"
S["76f176a6"] = "Prendeteli, bellezze mie... e anche i loro cagnolini!"
S["76f1ec76"] = "A Charog piace spendere le sue monete al Busted Drum. Andiamo a fargli visita, $N."
S["76f39457"] = "Ahh, ecco fatto. Ora Keever deve provare questa fiala e vedere se funziona."
S["76f5cfc1"] = "Sei $Gun incantatore:un'incantatrice; eccezionale, e temo che le mie capacità di maestro non ti bastino più. Cerca Kitta Firewind alla Tower of Azora: ormai solo lei può farti da insegnante."
S["76fb7bcb"] = "Ti serve un'illusione?$B$BSe durante la missione l'illusione dovesse svanire, torna da me e ti ridarò il travestimento.$B$BE se fallissi nelle tue imprese, non arrenderti! Torna da me: ti aiuterò finché non avrai completato gli obiettivi."
S["76fbb37c"] = "Sai chi può davvero mostrarti qualcosa? Nogg! Vai a cercarlo a Orgrimmar."
S["76fdd57d"] = "Prendeteli, ragazzi. Dategli una lezione! Nessuno si mette contro Slim."
S["7702b16a"] = "Non sono $Gdegno:degna;, padrone!"
S["7702d61a"] = "Una risorsa fondamentale della Thorium Brotherhood.$B$BI cristalli di arcanite si raccolgono dai ricchi filoni di torio, e con la loro abilità potenti alchimisti ne ricavano gli arcanite bars.$B$BSe non sei $Gun minatore:una minatrice;, cercane uno... e trova un bravo alchimista! Ti serviranno tutti e due."
S["770dcc8f"] = "E l'Alleanza, Rend?"
S["770e53e2"] = "Ho scoperto che quando getto qualcosa in quest'acqua, quando lo ripesco è migliorato incredibilmente."
S["770f371f"] = "%s scompare nella palude."
S["7710817a"] = "Con tutti questi lavori non c'è verso di far quadrare i conti! Di questo passo non apriremo mai."
S["7714ed22"] = "Eh? La banca la trovi a Orgrimmar. Per arrivarci prendi la strada verso nord, poi parla con uno dei loro grunt."
S["7715c973"] = "<Sveglia Tarsis.>"
S["771a0a96"] = "Cosa posso fare per te, $Gamico:amica;?"
S["7740eecd"] = "Da queste parti la maggior parte della gente non vede di buon occhio chi scassina le serrature. Come piccola cortesia professionale, lascia che ti mostri qualche trucco che ho imparato."
S["77418314"] = "Siediti e ascolta la mia storia, $R."
S["774722b1"] = "Orsù, veniamo alle mani, come gente civile."
S["775d4938"] = "Non vedo in te lo spirito del guerriero, $Gfigliolo:figliola;. A $Gun:una; $C come te non ho nulla di utile da insegnare."
S["775f23e8"] = "Buongiorno, $Gcittadino:cittadina;. Come posso aiutarti?"
S["77622e6e"] = "I druidi dicono che prima o poi la natura stessa scaccerà l'Orda da Kalimdor. Eppure la corruzione continua a diffondersi nelle nostre terre, perfino qui su Teldrassil."
S["77664dd6"] = "Ragazzo, tu non sapresti fare nemmeno un panino senza qualcuno che ti dice come si fa."
S["776c0841"] = "Non sfidare la mia pazienza, mortale."
S["776cf288"] = "Questa statuetta deve avere uno scomparto nascosto..."
S["7771b86a"] = "Tu... ti conviene aiutare i Forsaken in questi tempi terribili. Ascolta bene, perché non mi piace ripetermi.$B$BAl momento la stoffa ci manca gravemente. Bende e semplici tessuti scarseggiano, e accettiamo donazioni per rimpinguare le scorte, che stanno calando. Non riceverai un compenso in denaro — è questo che vuol dire donare — ma il tuo aiuto non passerà inosservato."
S["7772759d"] = "Oggi avete distrutto ciò che mi è costato anni di lavoro! Per questo morirete tutti per mano mia!"
S["777eeb84"] = "Parlami di Captain Balinda Stonehearth."
S["77815e77"] = "Ciao, $N. Ti interessa la sopravvivenza all'aria aperta? Nutrirsi della flora e della fauna di queste terre!$B$BPotresti imparare un paio di cose da me, cioè, se ti interessa."
S["77845733"] = "Per la Legione! Per Kil'Jaeden!"
S["778534cd"] = "Ho perso un pezzo del Lord Valthalak's Amulet!"
S["77862473"] = "Aiuto! Aspetta! È come se questo coso avesse una volontà propria!"
S["77963a3d"] = "Nessuno gnomo verrà lasciato indietro."
S["77968abf"] = "E ora anche quelle nazioni che avresti chiamato alleate si sono ritratte e hanno unito le forze con noi... Sì, vecchio, non fare quella faccia sorpresa."
S["7796be34"] = "Vediamo, vediamo. Avevo i numeri qui da qualche parte. Ah sì, eccoli! Finora l'Alleanza ha raccolto una parte della stranglekelp che serve. E qui c'è scritto che abbiamo anche una parte del purple lotus e delle arthas' tears necessari."
S["779732b1"] = "Psst. Ci è appena arrivato del Torcibudella..."
S["77983651"] = "$C, divorerò la tua luce!"
S["779a2b47"] = "Chi osa evocarmi?"
S["77ad1926"] = "Scoprire di più su ciò che trama il culto è di vitale importanza, ma ora che il traditore è morto, le informazioni potrebbero essere andate perdute insieme a lui..."
S["77b40a16"] = "<Nazgrel grugnisce mentre ti valuta.>$B$BAlti elfi, qui a Orgrimmar. Non ci avrei mai puntato un soldo che accadesse nella mia vita, ma a questo punto niente mi sorprende più.$B$BSì, il Signore della Guerra mi ha ordinato di redigere istruzioni per te. Prendi questa lettera e segui le istruzioni al suo interno. Comportati con onore e mostra la dovuta deferenza quando incontrerai i nostri capi, elfo.$B$BUna volta terminato il tuo viaggio, torna dal Signore della Guerra."
S["77b42e86"] = "Frostwolf Commander e Frostwolf Lieutenant, soldato."
S["77b78913"] = "Ok, $Gfratello:sorella;, adesso pe' 'l sapta... statti vicino a me."
S["77b90950"] = "Abbiamo $Gun vincitore:una vincitrice;! $N è $Gil:la; $GMaestro Pescatore:Maestra Pescatrice;!"
S["77c0b322"] = "Allo Stormwind Harbor ci arrivi dai Canali, tra il Cathedral District e The Park.$B$BCerchi un posto in particolare?"
S["77c1d74a"] = "Saluti a te, $Gcompagno:compagna; $Giniziato:iniziata; dell'High Order."
S["77d19b0b"] = "Continua, per favore."
S["77d4e66f"] = "Questo ponte dovrebbe essere già stato distrutto. Quanto ci mettono quei fannulloni ad arrivare qui dagli Altopiani!"
S["77da1fd0"] = "Non c'è di che! Devo rimettermi in cammino... state attenti, tutti quanti."
S["77e2107b"] = "Pensate di poter evocare noi? Siamo noi che evochiamo, non voi! Noi vi pestiamo per bene per questo e vi succhiamo il midollo dalle ossa!"
S["77f6965e"] = "Throm'ka, $C. Sei qui per aiutarmi con i tin bars? Mi dicono che me ne serviranno tanti perché possano fabbricare armi e armature per l'imminente Guerra di Ahn'Qiraj, ma per ora ne ho solo una parte. Me ne porterai altri!"
S["77fdacd0"] = "Attività dei Dark Iron. Pare persino che alcune spedizioni siano state dirottate —"
S["78121cba"] = "Parlami delle miniere."
S["7818e0fd"] = "A proposito, grazie per avermi coperto le spalle."
S["781a2d2d"] = "Che storia è questa? Vuoi rovinarmi la reputazione? Io non insegno ai principianti, $Gamico:amica;. Va' a parlare con Milla Fairancora nella Craftsmen's Terrace of Darnassus."
S["781b2b51"] = "Grazie ancora per il tuo aiuto. Che il vento ti sia sempre alle spalle durante i tuoi viaggi."
S["781c0ccb"] = "%s afferra il suo pugnale avvelenato!"
S["781c9489"] = "OH NO! Il re è morto! Ehm... lunga vita al nuovo re! Sì!"
S["782bacb1"] = "C'è chi dice che forza e coraggio siano ciò che serve di più perché un esercito abbia successo. Ed è vero! Ma un esercito ha bisogno anche di rifornimenti per restare in buona forma, e il mio lavoro è assicurarmi che abbiano ciò che gli serve."
S["78335eae"] = "La Frostwolf Relief Hut è stata presa dall'Orda!"
S["783f15d0"] = "Ci diffonderemo in questa terra desolata!"
S["7851787b"] = "Ora scaldiamo queste faville..."
S["7852d76f"] = "Ho sentito che tutti i coboldi che stavano laggiù sono morti."
S["7854c095"] = "Fai un equipaggiamento molto buono, davvero molto buono. Vai a Orgrimmar, la casa degli orchi, e cerca un fabbro di nome Saru Steelfury. Una cosa agli orchi bisogna riconoscerla: fanno bellissimi strumenti di morte."
S["785cd65c"] = "Nessun'altra razza di Azeroth ha sofferto quanto il nostro popolo, $C. Ridere in faccia alla morte, ormai, è diventato una seconda natura per tutti noi."
S["785d1053"] = "La Guerra di Ahn'Qiraj è all'orizzonte, $C, e per prepararsi l'Alleanza ha chiesto alla mia famiglia di raccogliere parecchio light leather per lo sforzo bellico. Per ora ne abbiamo una parte. Mi sembri il tipo che può dare una mano."
S["786200f3"] = "%s scatena un attacco devastante."
S["78649e7e"] = "Il capo della gilda"
S["78655944"] = "Noi dovere vedere se nostro Spacca... Spacca... Spaccacervelli venduto all'asta. Tu trovare cassetta della posta vicino a locanda, su anello superiore di Trade Quarter."
S["78692b4d"] = "Prendi la chiave e apri queste catene! La tiene Hitah'ya the Keeper... in fondo alla grotta..."
S["7870245a"] = "Niente preoccupare, noi trovare te."
S["7870bc51"] = "Ah, eccone uno."
S["787226d8"] = "Ce l'hai la stoffa per diventare $Gun abile cacciatore:un'abile cacciatrice;? Beh, $Gragazzo mio:ragazza mia;, solo il tempo lo dirà. Ma niente tiri alle mele sulla testa della gente finché non hai parlato con Regnus, laggiù nell'Hall of Arms."
S["78729d2a"] = "%s intona: \"Aiutalo in ogni modo che gli serve. Non fallire in questo compito.\""
S["7878386d"] = "Interessante... Non l'avevo notato prima..."
S["787c0e3d"] = "Una taverna calda e una birra fredda. Cosa potremmo chiedere di più?"
S["787dca0e"] = "%s va su tutte le furie alla vista delle sue truppe cadute."
S["788bc8f8"] = "Stamattina dei messaggeri di Ravenholdt mi hanno consegnato questa lettera. È per te, $N."
S["788fc80a"] = "Stai scherzando, vero? Ok, ok, niente panico. Per fortuna, mentre lo infondevo con il componente che hai recuperato, mi sono $Gsintonizzato:sintonizzata; anch'io con esso. Dovrei riuscire a localizzarlo e a evocarlo da dovunque tu l'abbia lasciato.$B$BSei $Gsicuro:sicura; di averlo perso? Hai guardato in tutte le tue borse e in banca?"
S["7895c718"] = "Ah! Daryl, avresti dovuto vedere la tua faccia! Per poco non sei saltato fuori dalla pelle!"
S["789b5631"] = "Cosa posso fare?"
S["789fbc5a"] = "%s crolla vedendo morire il suo padrone!"
S["78a707ac"] = "The Argent Dawn ti saluta, $C! Mi chiamo Lightspark, e sono un quartiermastro con il permesso di occuparmi dell'equipaggiamento e dei materiali della Dawn.$B$BMentre combatti il male per conto nostro — e intanto ti guadagni il nostro rispetto e la nostra fiducia — riceverai da Officer Pureheart dei gettoni del valore. Puoi usarli in due modi: spenderli per salire di posizione nei nostri ranghi, oppure come moneta per comprare oggetti speciali.$B$BPiù la tua posizione presso la Dawn migliorerà, più oggetti scoprirai di avere a disposizione."
S["78a9f1a2"] = "L'A-Me a casa! L'A-Me, buona! Buona l'A-Me. Casa. Casa. Casa."
S["78ab649c"] = "Salve, $N. Vedo che per te risulta già completata la quest per accedere a Naxxramas. Ricordati di parlare con Commander Eligor Dawnbringer alla Cappella della Speranza di Luce, nelle Eastern Plaguelands: ti darà la quest \"Echi di Guerra\", che devi completare prima di poter accedere alle quest del set di armatura di Tier 3.$B$BPosso teletrasportarti direttamente a Naxxramas, oppure puoi usare il portale nella Plaguewood, a ovest."
S["78b8eeaf"] = "Padre? Sei fiero di me, adesso? HAHAH!"
S["78b9e34f"] = "È ora di preparare un Cocktail di Kalimdor! Hic!"
S["78bee54b"] = "Questo costrutto vale quanto un fermacarte. Qualcuno gli ha rubato alcuni dei suoi componenti più importanti."
S["78c27914"] = "Ti prego, informa la Sentinella Starsong che presto mi presenterò a Dolanaar. Ande'thoras-ethil."
S["78cd2a1c"] = "Il mio popolo non ti conosce. Il kodo è una cavalcatura possente, frutto dell'amore e delle cure della mia gente, e non lo si concede agli stranieri. Non posso venderti un kodo finché gli anziani di Thunder Bluff non ti considereranno $Gosannato:osannata;."
S["78cf7580"] = "Grark Lorkrub, sei stato accusato e giudicato colpevole di tradimento contro l'Orda. Come ti dichiari non ha importanza. High Executioner Nuzrak, fatti avanti."
S["78d4c351"] = "Tutti pronti?"
S["78d7ce94"] = "Salute, $C! Bella giornata per andare a caccia, eh? Coi cinghiali mi sta andando piuttosto bene. Ti va di provare anche tu?"
S["78e51718"] = "Beh, esco a controllare. C'è qualcosa che non va."
S["78ee7398"] = "Ciao, $N!$B$BDevo lavorare ai miei congegni, ma prima o poi... avrò bisogno di qualcuno che mi procuri delle uova di drago!"
S["78ee9f0a"] = "Jin'rokh, ho bisogno di aiuto per recuperare un pezzo del mio Equipaggiamento da Battaglia del Vendicatore."
S["78f271ea"] = "L'elfa della notte è immobile: ha molte ferite e sulla pelle le chiazze tipiche di un avvelenamento."
S["78f6f3bb"] = "Radunatevi attorno ai vostri Luogotenenti e Comandanti! Proteggete le nostre basi!"
S["78fbae24"] = "Le storie delle tue imprese girano, $N: il tuo nome non ci è sconosciuto."
S["78fe7720"] = "Alt! La città è in isolamento finché non sarà ristabilito l'ordine."
S["78feb1d3"] = "Ormai ci manca pochissimo per completare la Nuova Piaga, che la nostra Dama Oscura desidera con tanto fervore."
S["7906b092"] = "Quell'istruttore sta all'estremità sud-est della città, vicino al molo dell'High Order."
S["7906fb58"] = "Calma, $R. Quello che devi uccidere è già morto. Ucciderlo di nuovo non servirà a niente. Di modi per distruggere davvero un lich ce ne sono pochissimi, e nessuno è alla nostra portata. Ecco perché ho un piano. Un piano che avrà sul Culto un effetto molto evidente e concreto."
S["790a9014"] = "A Stormwind tutte le pratiche di guarigione fanno capo alla Cathedral of Light. È lì che trovi Shaina Fuller, che ti aiuterà a imparare quest'arte."
S["7910c1dd"] = "Correndo verso la gloria, hai dato per scontato che il ritmo del gioco girasse attorno a quello che fai tu. Riesci almeno a immaginare quanto suoni assurdo a un essere come me? Uno che, se volesse, potrebbe far schiacciare dai tuoi stessi insignificanti pensieri quella massa di materia grigia grande quanto una nocciolina che ti galleggia nel cranio."
S["79150a9b"] = "Sono Kilram, maestro dell'ascia."
S["79165ea2"] = "Se vuoi catturare Gahz'ranka ti serve una Mudskunk lure speciale: le faccio io!$B$BPerò l'esca da sola non basta, ti servono anche dei mudskunk... vanno messi nell'esca, così prende un bel tanfo rancido!$B$BAppena hai i mudskunk, lancia l'esca dalla Pagle's Point a Zul'Gurub... poi prenditi da bere e aspetta... ma non troppo, perché di sicuro Gahz'ranka arriverà a passi pesanti!"
S["791dacac"] = "Di certo non sei tuo padre, insetto. Se mi interessasse, ti schiaccerei con un solo colpo d'artiglio. Consegnami Shan'do Grantempesta e la tua misera vita sarà risparmiata, insieme a quella del tuo popolo."
S["79295d4e"] = "Fermi... devo riprendere... fiato."
S["79335b1e"] = "Vuoi sapere della pietra? Seguimi."
S["7936d10f"] = "Hoha! La sfida del vecchio pancia molle la accetterei volentieri!"
S["793ebfb5"] = "Mi duole dover combattere contro $Gquesto:questa; $N."
S["794185cd"] = "Salve, $C. Scusami, sto parlando con Rimblat. Crede che si possa ancora salvare persino questa terra."
S["79443bf5"] = "Avete rinchiuso il Maresciallo sbagliato, $N. Preparatevi a essere distrutti!"
S["79458d2a"] = "Non ci sono parole per quello che è successo. Banon si è contorto, si è piegato in modo orribile: sembrava che gli si spezzassero tutte le ossa. La bocca gli si è riempita di rasoi e le mani sono diventate artigli letali. Ci sono voluti venti gnolls per abbatterlo, e prima della fine ne ha uccisi la metà."
S["7946794f"] = "Sì, venite. Il mio padrone e io vi aspetteremo."
S["794c5a14"] = "Lo Stonehearth Graveyard è stato conquistato dall'Orda!"
S["79547dfd"] = "Captain Galvangar è l'aiutante di fiducia di Drek'Thar. Guida le forze dell'Orda dall'Iceblood Garrison, nella parte meridionale del Field of Strife.$B$BAl momento Captain Galvangar si trova nell'Iceblood Garrison."
S["7965148c"] = "Preferisci le armi da fuoco o gli archi?"
S["7966cd61"] = "Mmm, credo di poter prendere $Gun altro allievo:un'altra allieva;. Be', non startene lì $Gimpalato:impalata;. Dimmi cosa vuoi imparare."
S["7969d85b"] = "Proprio mentre parliamo, $C, tutto il materiale bellico viene trasportato a Silithus. A quanto pare l'ultimo carico dovrebbe arrivare in meno di un giorno. Dopo di che $Gun eroe:un'eroina; dovrà venire a suonare il gong sulla Scarab Dais. Allora la guerra comincerà sul serio."
S["7975848a"] = "Chi è $Gquesto:questa; $R così debole? $GUn lurido intruso:Una lurida intrusa;, dico io. Muori, $Gsciocco:sciocca;!"
S["797588d3"] = "Dobbiamo riempire questo carro entro fine giornata, quindi tornate al lavoro. Svelti, svelti!"
S["797acb72"] = "Ecco qui una pila di wrapped gifts."
S["797b81b6"] = "Ho sentito che alla prossima gara volevano far saltare in aria l'auto degli gnomi! Sarà vero o no, ma io dai loro box starei alla larga."
S["79811d91"] = "Vuoi farti addestrare nelle tattiche e nelle strategie della caccia? Allora sei $Gvenuto:venuta; nel posto giusto!"
S["7983f135"] = "Le Dead Mines, che un tempo davano più oro di qualunque altro posto delle terre umane, ora ospitano la Defias Brotherhood, che ha fatto delle buie gallerie il suo santuario privato. Si dice che i ladri abbiano costretto gli astuti goblin ad aiutarli a costruire qualcosa di terribile in fondo alle miniere — ma cosa sia, ancora non è chiaro. Pare che per arrivare alle Deadmines si passi dal tranquillo e modesto villaggio di Moonbrook."
S["798c6151"] = "Su questo punto molti non sono d'accordo. I Windshapers vorrebbero farti credere che basti prendersi per mano e limitarsi a sperare che gli spiriti tornino. Ma il potere del loro ordine si è indebolito, e la loro strada ci ricondurrebbe a quel ciclo di dipendenza che ci ha portati fin qui. L'High Order, invece... noi crediamo in un approccio più diretto."
S["798cf8fd"] = "La West Frostwolf Tower protegge la porta tra il Frostwolf Village e la Frostwolf Keep.$B$BÈ controllata dall'Alleanza."
S["7990a8c5"] = "Ti ho dato una pietra del giuramento del Ysera's Dragonflight, $N. Quando sarai $Gpronto:pronta; e in grado di aiutarci, usala, e allora potremo cominciare."
S["79a29ec1"] = "Sta finendo il tempo, per me... per tutti noi..."
S["79a9e244"] = "Ragnaros regnerà incontrastato!"
S["79a9f46c"] = "È fatta, entrambe le parti hanno raccolto tutto. Ora viene tutto trasportato a Silithus e dovrebbe arrivare lì in meno di un giorno. Una volta fatto, quando qualcuno suonerà il gong sulla Scarab Dais con lo Scepter of the Shifting Sands, la guerra comincerà!"
S["79ae7958"] = "Non ho tempo per farti da balia! Va' a parlare col mio assistente, Uthrar!"
S["79b08832"] = "La battaglia infuria, e sia il nostro capitano sia il capitano del nemico sono caduti!$B$BDrek'Thar ora ci guida dalla Frostwolf Keep, e il nano Vanndar Stormpike si nasconde nel cuore di Dun Baldar. Sconfiggi Vanndar e conquista la vittoria per l'Orda!"
S["79b248f7"] = "Quelli di The Argent Dawn saranno pure degli idealisti impotenti, ma quell'illuso del loro capo sa che sono in inferiorità. Mi hanno mandata qui come emissaria della Scarlet Crusade. Un'ambasciatrice, per così dire... Dubito che riusciremmo anche solo a scalfire gli eserciti di Kel'Thuzad — uniti o no — ma forse potremmo trattenerli abbastanza a lungo perché accada una sorta di miracolo.$B$BE io? Io morirò in battaglia...$B$B<Marjhan scrolla le spalle.>"
S["79b2b270"] = "Pane qui! Le vostre pagnotte preferite! Belle fresche!"
S["79b341be"] = "Ho tante cose da fare... tante, prima che arrivi la pestilenza..."
S["79b9d9a2"] = "Ho bisogno di addestramento."
S["79c2b82d"] = "Non spingermi, o ti infilzo con le corna!"
S["79c2ef94"] = "Nella mia vita precedente abitavo qui vicino, e ogni tanto vago ancora per i campi della fattoria dove sono cresciuto. Vedere quelli che conoscevo e amavo trascinarsi in giro come schiavi senza mente mi riempie di tristezza. Mi fa soffrire, ma è proprio quel dolore a darmi forza e uno scopo."
S["79c9e555"] = "I morti camminano fra noi!"
S["79ce2ecb"] = "Molta carne. Molta forza!"
S["79d140e4"] = "Siete così ansiosi di morire? Sarò felice di accontentarvi..."
S["79d4f23f"] = "Credo che tu abbia ragione."
S["79d81d75"] = "Possa il tuo spirito ardere luminoso, $N."
S["79d9db69"] = "Se sopravvivo a questo, farò dell'annientamento di Arthas l'unico scopo della mia vita..."
S["79df2473"] = "Guardate sopra di voi; thara dormil dorah..."
S["79e467ca"] = "Cosa... succedere a—"
S["79e79c4b"] = "Se ti si congela il moccio nel naso, che succede?"
S["79eb856c"] = "No uccidi me! No uccidi me!"
S["79f1a15c"] = "Uku halo tu awak. Uku porah tu shne."
S["79f1c7fb"] = "Dammene un po'!"
S["79f23c33"] = "Te lo farò sapere. Se sei $Gdiventato:diventata; luogotenente così in fretta, vuol dire che nei nostri ranghi stai già dimostrando quanto vali. Magari più tardi potrai tornare da me, e avrò dei compiti per te. Il consiglio adora chi è esperto nelle arti arcane, ma i servitori di ogni genere sono sempre ben accetti, qualunque mestiere facciano."
S["79f5b063"] = "The Scarlet Crusade sta invadendo la nostra patria. Quegli sciocchi fanatici non capiscono che a farla finita con loro ci penseranno i leali servitori della Dama Oscura."
S["79f937f3"] = "Hai forse delle carte della Darkmoon Faire? Vieni a parlare con me per saperne di più, se ne hai il coraggio!"
S["79fbf07e"] = "Hai dovuto insegnarle a non sporcare in casa, Gerard?"
S["7a0eb380"] = "Se avessi un odore migliore, ti parlerei. Un po' di colonia non guasterebbe."
S["7a103ae9"] = "C'è Algernon a rifornirmi, così posso fare tutto il lavoro qui senza andare a cercare nemmeno un'erba. E se non dovrò mai più vedere le meraviglie della natura, di certo non ne sentirò la mancanza."
S["7a121db1"] = "Forse è il caso che ti dica perché sono qui.$B$BHai mai sentito parlare di Deathwing, l'Aspetto? O della sua progenie, Nefarian e Onyxia?"
S["7a152643"] = "Spero tu abbia un buon motivo per interrompermi. Stavo facendo un lavoro importante."
S["7a17d738"] = "Cerca Yelmak's Alchemy and Potions: sta al centro de The Drag, a ovest dell'albero enorme."
S["7a195e22"] = "%s si ritrae per il dolore mentre il Judgement of Light lo investe!"
S["7a2b5f99"] = "Buone feste, $Gamico:amica;!"
S["7a315ee8"] = "Ben fatto! Hai quella scintilla negli occhi... La conosco bene: io avevo la stessa quando ero solo un cucciolo! Adesso vediamo se riesco a insegnarti qualcosa."
S["7a3d107c"] = "Oh!!! Porta via quella cosa da me!"
S["7a4189bf"] = "Preparati a prenderle di brutto."
S["7a44de19"] = "Tu non prendere candela!"
S["7a46d2ae"] = "Le rune di protezione sono state distrutte! Date la caccia agli infedeli, fratelli miei!"
S["7a4d9c91"] = "Lasciamo Nighthaven, $Geroe:eroina;. Cercami al boschetto."
S["7a5240c2"] = "Ti piace il tappeto? La bestia l'ho uccisa e scuoiata con le mie mani. Possano tutti i centauri cadere con la stessa facilità."
S["7a59c81a"] = "Il numero dei miei compagni diminuisce, dea, e presto il mio potere non basterà più a trattenere i demoni di Felwood."
S["7a61359b"] = "Cosa succede? Guarda!"
S["7a71ab9c"] = "Mi hanno detto che il vecchio Marshal McBride t'avrebbe mandato da me."
S["7a71f145"] = "Alla Tenuta non si fa che parlare del tuo arrivo, $GSignor:Signora; $N. Siamo tutti onorati e lusingati dalla tua presenza."
S["7a72cfca"] = "La paura si annida nel tuo cuore, $N. Quando sarai $Gpronto:pronta; davvero ad affrontare Vorsha the Lasher, vieni a parlare con me."
S["7a78d2d6"] = "Come vuole la Dama Oscura."
S["7a7c4902"] = "Sai usare le parole, Signore Supremo Saurfang."
S["7a7ec3b7"] = "Mi sto spostando all'interno dell'edificio"
S["7a86e148"] = "Ti sconvolgerà, forse, ma ultimamente gli affari non vanno poi così bene..."
S["7a8e4c48"] = "Hai un vero talento e una passione per la preparazione delle pozioni. C'è però una piccola faccenda di cui vorrei che ti occupassi."
S["7a923710"] = "Il tuo dolore finirà presto!"
S["7a9cfdb0"] = "Pulisciti prima di toccare i nostri tomi, per favore."
S["7aad4b7d"] = "Onore a $N, $C di valore!"
S["7abc710f"] = "$GBenvenuto:Benvenuta; a Stormwind! Sono uno dei funzionari della città e aiuto i cittadini dall'ufficio del censimento: se devi trovare qualcuno in particolare, potrei darti una mano. Con metodi arcani e una mente affinata dalla disciplina, sono in grado di consultare questi registri.$B$BSe hai affari da sbrigare con me, fa' pure!"
S["7ad4ff3a"] = "Brucia nella fiamma della giustizia, vile mostro!"
S["7addd2e1"] = "Il medaglione di %s va in frantumi."
S["7addd90a"] = "Ayessa Dawnsinger. Il Magistro Supremo dell'High Order attende la tua risposta alla sua richiesta."
S["7ade6c12"] = "Soccombete allo sguardo, mortali!"
S["7ae8f502"] = "Perché mi insegui, Mechanical Yeti?! PERCHÉ?!"
S["7aebcc3c"] = "SILENZIO, STOLTO!"
S["7aebf571"] = "Il banchetto delle anime comincia ora..."
S["7aecfbbf"] = "Puoi aiutarmi con qualche indicazione?"
S["7af5eaef"] = "Venite, spiriti — servite il vostro padrone!"
S["7b101ae0"] = "E per di più $Gmodesto:modesta;... Allora forse è arrivato il tuo momento, $N.$B$BSei $Gpronto:pronta; a entrare nella fortezza degli orchi Blackrock? A seminare distruzione? A squarciare le fondamenta della cittadella della montagna?"
S["7b127acf"] = "%s agita il pugno per la frustrazione."
S["7b13b487"] = "%s comincia a lanciare Grande Cura!"
S["7b16ae4f"] = "Ah, di nuovo vuoto!"
S["7b19a528"] = "Ma non è proprio quello che ha causato i primi problemi con le formule magiche dell'Adepta Syleria?"
S["7b1e3743"] = "Capiamo. Si dà il caso che io ed Elaadrin ne abbiamo parlato. Abbiamo preso accordi per chiedere... un aiuto esterno. Non sappiamo se faranno in tempo a darci una mano, o se arriveranno mai..."
S["7b24e33d"] = "Non interrompere Niby, $Gstolto:stolta;! Ti strapperò la carne dalle ossa e del tuo scheletro farò un attaccapanni. Allora, dov'ero $Grimasto:rimasta;? Ah, sì: Kroshius è durato quasi dieci volte più di un qualunque infernal comune. Il perché non lo so, ma sono $Gcerto:certa; che, studiando abbastanza, potrei scoprirlo.$B$BMi serve che tu recuperi il Kroshius' Infernal Core."
S["7b2890e2"] = "Il Culto? Fanatici e assassini. Sono convinti che veniamo puniti per qualche peccato imprecisato. In realtà li guidano degli opportunisti, quel che resta di un discutibile ordine di cosiddetti \"Sacerdoti\" di Al'Akir, il Signore del Vento.$B$BOra possono trasformare la paura del nostro popolo in un'arma per consolidare il proprio potere... e non hanno perso tempo."
S["7b2ebe8d"] = "Sembra che abbiamo scovato questo $N. Ora aiutami ad ucciderlo!"
S["7b396b03"] = "Fatevi cuore!$B$BIl Soulflayer è stato sconfitto e il suo miserabile cuore è stato scagliato nel vuoto!"
S["7b40d68c"] = "Solo dopo la sua controversa morte i cavalieri e i guerrieri di Lordaeron presero a indossare armature di foggia simile, in onore del loro eroe caduto. Per Kel'Thuzad la morte di Mograine fu una grande vittoria, ma il martirio che ne seguì si sarebbe fatto sentire fino al termine della guerra.$B$BDove uno cadde, molti si sarebbero levati..."
S["7b44dde1"] = "Qui c'è abbastanza lavoro per un esercito di orchi, e la maggior parte posso farla solo io. Comunque, c'è un lavoro per cui mi servirebbe una mano."
S["7b494090"] = "Fino ad allora, prendo congedo..."
S["7b5578f9"] = "Icebane Bracers."
S["7b5657df"] = "Basta lingotti di stagno! Mi fanno male persino le braccia a impilarli. Abbiamo tutto quello che ci serve, quindi vai a chiedere a uno degli altri se ha bisogno che tu raccolga qualcosa."
S["7b5a4e3f"] = "Oh, sì, di sopra, in fondo alla taverna, c'è una visitatrice venuta da Aerie Peak che probabilmente può aiutarti con la guida spirituale o quel che fanno gli sciamani. Ingol? Ir... Ingrid! Ecco, si chiama Ingrid."
S["7b5a667a"] = "Scommetto che Quae penserà che questo è importante. Se ne intende parecchio di queste cose: non è un'esperta, ma se ne intende."
S["7b5e771b"] = "Non sono $Gdegno:degna;, $Gsignore:signora;."
S["7b61ac85"] = "Siate benedetti, mortali, per questa liberazione... Hakkar non mi controlla più!"
S["7b66d07a"] = "Ecco fatto. Devo tornare al lavoro prima che Rokar mi rifili un altro ceffone perché sono $Gpigro:pigra;."
S["7b68213e"] = "Non posso insegnarti la conciatura elementale, $N. Devi andare a Tanaris e trovare la casa di Narain Soothfancy. Una volta lì, consulta il libro \"Divinazione for Dummies.\""
S["7b68e600"] = "Il deserto di Tanaris è disseminato di ossa gigantesche proprio come questo alla mia destra. Non mi sarebbe piaciuto per niente imbattermi in quella cosa."
S["7b6e0840"] = "La Signora Pomeroy raccoglie erbe per un Alchimista che abita sulle colline fra Northshire e Stormwind. Va' a cercarla da lui, nella sua casetta, e vedi se ti insegna la professione."
S["7b6edded"] = "Salve, come ti senti oggi, $C? Bene, spero. Ti starai chiedendo che succede qui. Ad Ahn'Qiraj si prepara una guerra, e noi e l'Orda ci stiamo attrezzando come meglio possiamo.$B$BPer questo l'Alleanza mi ha chiesto di occuparmi qui della raccolta di silk bandages. Finora siamo riusciti a metterne insieme una parte di quelle che servono. Pensi di darci una mano?"
S["7b704581"] = "Mi fanno male i piedi..."
S["7b748a6c"] = "L'Avamposto dei Silverwing è nostro!"
S["7b7e9899"] = "La famiglia Barov ha dato a Kel'Thuzad il terreno su cui è sorta la Scholomance. In cambio di quella terra — un luogo dove il Cult of the Damned potesse apprendere le magie immonde dello Scourge — Kel'Thuzad ha concesso ai Barov l'immortalità della non morte.$B$BNella Shadow Vault troverai sia la skin of shadow sia la sua proprietaria, Lady Illucia Barov.$B$BNon c'è mai stato uno specchio migliore per i vanitosi e per i morti."
S["7b7fa807"] = "Darò in pasto le vostre anime a Hakkar in persona!"
S["7b86ceec"] = "Sono in missione. Una missione! Una missione in cerca di nuove leghe e metalli più duri, per la più grande invenzione di tutte!!"
S["7b8868c8"] = "Io preferisco il cibo crudo, ma se a te piace cotto, Denni'ka può insegnarti ad accendere un fuoco. La trovi a Survival of the Fittest, una capanna sulla riva del lago accanto alla Spirit Lodge. Cercala più in alto, a ovest della Valley of Strength."
S["7b90a784"] = "Mmmh... SENTO ODORE DI CIBO!"
S["7b978ac4"] = "No, $N, non l'hai fatto. Però non te ne faccio una colpa, perché la tua mente somiglia molto alla mia di quando ero giovane: impetuosa, ribelle e spesso senza un solo pensiero coerente! Tratti che ormai non posso più permettermi di mostrare.$B$BBasta lamentarsi. $R, ho un compito per te; potresti non uscirne $Gvivo:viva;."
S["7b98f053"] = "Mia nonna, che vive giù a Redridge, picchia i manichini più forte di te, $Gpivello:pivella;!"
S["7b9bef39"] = "Dov'è la Silver Hand? Ci serve il loro aiuto!"
S["7ba2c06e"] = "Qui rispetterai le nostre regole, canaglia!"
S["7ba43b1c"] = "Ah, la mia dolce Brandy, quanto mi manca!"
S["7bacbd8e"] = "Lo Stormpike Graveyard è sotto attacco! Se nessuno lo ferma, l'Orda lo conquisterà!"
S["7bb3cb96"] = "** SERVOMOTORI DISTRUTTI. PUNTAMENTO DELL'UNITÀ CORROTTO. SPEGNIMENTO IMMINENTE. **"
S["7bb9f083"] = "Ascolta, giovane $C. Senti il richiamo dell'acqua?"
S["7bba8977"] = "Ti spacco quella brutta testa a calci!"
S["7bbc9d53"] = "Uff! Ecco un altro carico di merce, Harlan. Deve vendersi in fretta!"
S["7bc6d5bc"] = "I troll Zandalarian sono venuti da lontano e hanno patito molto per arrivare fin qui, ma non fare nulla... vuol dire andare incontro alla nostra rovina..."
S["7bd44a74"] = "Niente come una brezza leggera e buona compagnia per la pesca."
S["7bdf6304"] = "Sì, ma io la conosco con il suo vero nome — Eldre'Thalas. Molti, molti anni fa era un bastione di potere magico degli elfi della notte.$B$BConosci Eldre'Thalas, giovane? Si potrebbe parlare di coincidenza, vista la disgrazia in cui mi trovo... ma io non sono tipo da credere alle coincidenze."
S["7be4a590"] = "Elder Goldwell di solito sta nel villaggio di Kharanos, a Dun Morogh."
S["7bfb2fa5"] = "L'East Frostwolf Tower è stata distrutta dall'Alleanza!"
S["7c06393f"] = "Sei $Gsicuro:sicura; che nessuno ti abbia seguito? All'improvviso ho un pessimo presentimento..."
S["7c066322"] = "Istruttore dei Sacerdoti? Tu vai all'anello esterno del War Quarter e li cerchi lì."
S["7c10fc6b"] = "Inchinati al mio cospetto, insetto! Il potere che ho su di te lo senti di certo."
S["7c133d55"] = "Hai sentito qualcosa?"
S["7c1a6332"] = "Morte a $N! Lunga vita al Blackrock Clan!"
S["7c2f19db"] = "Accidenti! Pare che abbiamo già raccolto tutto il cuoio spesso che pensano ci servirà. È andata proprio veloce. Sai, qui intorno ci sono probabilmente altri a cui farebbe comodo il tuo aiuto, se vuoi dargli una mano."
S["7c2f3e8c"] = "Che posso fare per te, $N?"
S["7c3c6c02"] = "Alzati, mio campione!"
S["7c3d76a2"] = "Il mio lavoro qui è finito. Farò sapere a Mar'alith e agli altri di Cenarion Hold che mi hai dato una mano. Stai $Gattento:attenta; qui dentro, da questo punto in poi non ci sono più io a tenerti per mano."
S["7c416550"] = "Aku'mai ha bisogno di altri innocenti per essere saziato."
S["7c43aba3"] = "$GUn altro studente:Un'altra studentessa;, eh? E va bene, vediamo cosa posso fare per aiutarti."
S["7c5865b7"] = "Finché tu resta qui con noi, tu è re. Se tu va via, qualche altro ogre prende tuo posto. Questa è legge dei Gordok!"
S["7c62e589"] = "$GUn altro sciocco:Un'altra sciocca; cade nella trappola!"
S["7c63c1b2"] = "Si dice che un esercito marci con lo stomaco, ed è la verità. Perché un'offensiva riesca, le truppe devono essere ben nutrite e ben rifornite."
S["7c686c85"] = "Questo raggio di luna ti porterà a Orgrimmar. Quando vuoi partire, usa l'invito."
S["7c6cdf0b"] = "Pescare mi sembra una buona idea."
S["7c774baf"] = "Le Plaguelands sono un ottimo posto per colpire lo Scourge!"
S["7c7bddd2"] = "Bol... Bolvar... il medaglione... usa..."
S["7c897c86"] = "Sia lodata The Banshee Queen, da queste parti viene a trovarmi poca gente."
S["7c89c75a"] = "PER LA POTENZA DI KALIMDOR!"
S["7c90d77c"] = "Se sei qui per farmi perdere tempo, lo stai facendo perdere a tutto il Cenarion Circle. Per il tuo bene, speriamo che tu non sia $Gsciocco:sciocca; al punto da farlo davvero."
S["7ca29ba7"] = "Non badare a me, né al mio odore... perché io di certo non ci bado!"
S["7ca715d9"] = "Seguimi, $Gbuon paladino:buona paladina;. Finirò la tua bardatura più in fretta di quanto riesca a scolarmi una birra scura dei nani. Mmmm... birra scura."
S["7cbd640e"] = "La vita è come un arazzo tessuto con cura."
S["7cd02aa4"] = "%s si fa una lunga sorsata di birra."
S["7cd52a57"] = "Dammi la mia bambolina!!"
S["7cda9c46"] = "Dicono che Vance Undergloom abbia preso una stanza fissa al piano di sopra della Gallows' End Tavern, all'estremità sud-orientale della città. Credo che sia proprio accanto alla sala di lettura."
S["7cdb7cc4"] = "Festività — Invasione dello Scourge, mistico — quanto dura, Livello 0"
S["7cdb7cc5"] = "Festività — Invasione dello Scourge, mistico — quanto dura, Livello 1"
S["7cdb7cc6"] = "Festività — Invasione dello Scourge, mistico — quanto dura, Livello 2"
S["7cdbf36c"] = "Maestro d'Armi"
S["7cdfc0e9"] = "Sentinelle, venite in mia difesa!"
S["7ce5a849"] = "I complotti sono ovunque, dico io. Certa gente non ha la lungimiranza per capire quello che faccio e vorrebbe tenermi incatenato nell'anonimato!$B$BNon calpestare la terra."
S["7cf31d58"] = "$N, sei $Gpronto:pronta; a unirti alla grande battaglia nell'Alterac Valley?"
S["7cf4ac7a"] = "Le mie ossa sono deboli, i miei occhi vedono solo oscurità e il mio corpo sente solo dolore; ma queste cose sono buone, perché la mia volontà è mia."
S["7d017bae"] = "Scappa finché puoi!"
S["7d04658c"] = "*Sigh* Probabilmente hai ragione, Raven. Torno di pattuglia...."
S["7d0d0c5b"] = "Ora vi lascio, mortali. Vivi e con questi ninnoli. Maltrake! Consegna loro i ninnoli!"
S["7d128fa3"] = "Il clan Stormpike non si inchina a nessuno, tantomeno all'Orda!"
S["7d12f909"] = "Lo Stormpike Graveyard è stato preso dall'Orda!"
S["7d1a67bc"] = "Si può sapere che ci fai qui? Mettiti la tenuta da $Gstudente:studentessa; e studia!"
S["7d1c60ee"] = "Nelle giornate limpide da qui si vede perfino Blackrock Mountain. È bello e terrificante insieme."
S["7d25a27e"] = "Pagherai il prezzo più alto per questa insolenza, piccolo verme. La tua anima è mia!"
S["7d2d10b1"] = "Glacial Cloak."
S["7d2ee16c"] = "Grazie, $N. Se non fossi arrivat$Go:a; tu, saremmo stati spacciati di sicuro! Ora l'unica cosa tra noi e il capo dei troll è quella porta laggiù..."
S["7d38d4d9"] = "%s è attratto dal magnete per fantasmi..."
S["7d3ef124"] = "Mmh, a quanto pare a Keever serve una nuova cavia. Se quello sciocco di Abernathy continua a prendersi le cavie di Keever, Keever dovrà forse scambiare due parole con lui."
S["7d3f3f14"] = "Non che io dubiti delle tue capacità, ma vorrei che svolgessi un compito per me. Consideralo una prova di buona fede..."
S["7d4f7ee5"] = "FINISCI L'INCANTESIMO, ELMOCERVO! NON RIESCO A TENERE FERMI ANCORA A LUNGO I GLIFI DI PROTEZIONE! RICHIAMA LE RADICI!"
S["7d576f93"] = "Non farmi perdere tempo: ho progetti di ricerca più vecchi di te. Va' a parlare con Doctor Martin Felben nell'Apothecarium of the Undercity. È un Forsaken, e probabilmente riuscirà a insegnarti le basi."
S["7d58ae27"] = "Cos'è stato?! Trey? TREY!?"
S["7d69700e"] = "Cosa posso fare per te?"
S["7d69708a"] = "Cosa posso fare per te?"
S["7d6a6b99"] = "I Windshapers possiedono il dono della vista celeste, e stiamo lavorando senza sosta per ritrovare i nostri benefattori elementali perduti, perché possano guidarci di nuovo."
S["7d705a96"] = "E se facessimo il giro, invece? Questo posto non è COSÌ grande."
S["7d781959"] = "%s scompare nei boschi."
S["7d7bf7c4"] = "Sì, sorella, come posso aiutarti?"
S["7d7f0529"] = "Non è servito a molto. Fammi controllare l'altro."
S["7d819c8f"] = "Hai delle domande, ma son troppo grosse per me, $N. Devi andar a fare due chiacchiere con l'orco Yelmak nel Drag of Orgrimmar. Lui ti darà una mano."
S["7d883fba"] = "<Un bandito solitario siede sull'orlo del precipizio, evidentemente perso nei suoi pensieri. Se si accorge di te, non sembra avere voglia di attaccarti.>"
S["7d92004a"] = "%s esplode e illumina il cielo con uno splendido spettacolo di fuochi d'artificio! Sembra chiamare proprio te, $Gladro:ladra;."
S["7d9f22a3"] = "$GBenvenuto:Benvenuta; negli uffici dello Stormwind Guild Registry. In cosa posso esserti utile?"
S["7daa21de"] = "Vai a Orgrimmar: troverai lei e la sua famiglia nella Valley of Honor."
S["7dac8526"] = "Dammi la riding turtle!"
S["7db148ed"] = "Se solo riuscissi a trovare \"La Magia e le Vie del Potere\". Ahh, eccolo, che ci faceva qui?"
S["7db3723f"] = "Va' al Silverwind Refuge e cerca Shandrina. Può venderti il \"Expert Cookbook\"."
S["7db564ed"] = "Dove diavolo sono finite quelle spedizioni? Mi fanno aspettare da giorni!"
S["7dc89eb1"] = "CHI OSA EVOCARE LOKHOLAR?"
S["7dd3db2d"] = "Ci è voluta un po' di fatica per convincere l'Arcimago Rhonin ad aiutarmi ad aprire quel portale dimensionale..."
S["7dd71ee4"] = "Queste terre saranno purificate!"
S["7ddcf259"] = "Mmh, capisco. Molto bene, allora, $C. L'High Order aiuterà le Peacekeepers. Per favore, informa Valennia che può contare su di noi in questa battaglia.$B$B<Elaadrin abbassa la voce con fare minaccioso.>$B$BNon scambiare la nostra spontanea collaborazione per una qualche forma di clemenza. Devi del sangue all'High Order, e noi riscuotiamo sempre i nostri crediti."
S["7ddf5cc9"] = "%s si protegge con la magia."
S["7de28754"] = "Ti serve Zamja, al Borstan's Firepit, al livello superiore de The Drag. Quando arrivi a The Drag dalla Valley of Strength, sali le scale a sinistra."
S["7de516b1"] = "Questa lascerà il segno!"
S["7de68425"] = "Posso aiutarti a trovare qualcosa, $Gcittadino:cittadina;?"
S["7de757ce"] = "Da un po' di tempo il Comandante non è più lui. La sua amante è scomparsa durante uno scavo archeologico nel deserto meridionale — svanita nel nulla! Davvero strano.$B$BCerchi lavoro, immagino? O te lo devo far capire a bastonate?"
S["7df93217"] = "%s arriva!"
S["7e01ad8c"] = "Com'è stato facile manipolarvi per farvi recuperare l'ultima pietra di Suntara da quegli imbecilli del Twilight's Hammer."
S["7e0e2641"] = "Muratori... ehm... Defias, state in guardia: stanotte l'ancora arrugginita affonda."
S["7e13cc9f"] = "La lama stessa doveva essere forgiata in una cerimonia insieme ai figli degli Aspetti. Un evento davvero raro... Perché un drago non solo doveva scaldare e plasmare di sua volontà il metallo incantato con il proprio soffio, ma doveva anche contenere la furia del proprio incantamento usando il proprio sangue per la tempra."
S["7e14034c"] = "percepisce la tua paura."
S["7e1e92a9"] = "Niente di meglio che entrare in comunione con la natura... o almeno così mi dicono gli elfi della notte. Parlare con fiori e alberi non fa per me, ma sono $Gsicuro:sicura; che Tannysa può darti una mano. La trovi in Mage Quarter, fuori dalle Alchemy Needs."
S["7e257262"] = "Coprimi le spalle, qui potrebbe mettersi davvero male."
S["7e269862"] = "Atten-ti! Tutto il materiale bellico per Ahn'Qiraj è registrato e in corso di trasporto alla Cenarion Hold, $Gsignore:signora;! Mi dicono che l'ultimo carico dovrebbe arrivare in meno di un giorno. Una volta fatto, e quando qualcuno suonerà quel gong laggiù per aprire le porte, garantisco che daremo a quegli insetti una battaglia coi fiocchi!"
S["7e28f721"] = "Io paura! Io scappa adesso!"
S["7e2aaf01"] = "Uuuuuuggggghhhhh...."
S["7e3847ed"] = "$GBenvenuto:Benvenuta; a Bonegrip's Runes and Dooms, $C. Guardare puoi, ma non toccare.$B$BNon tutto il sapere che c'è qui è fatto per i...non iniziati."
S["7e4115f0"] = "Dodicimila anni fa una setta segreta di stregoni elfi della notte costruì l'antica città di Eldre'Thalas per proteggere i segreti arcani più preziosi di Queen Azshara. La Great Sundering del mondo la devastò, ma gran parte della meravigliosa città è ancora in piedi: è l'imponente Dire Maul. I tre distretti delle rovine, ben distinti fra loro, sono stati invasi da creature di ogni genere — soprattutto gli spettrali alti nati, gli immondi satiri e i brutali ogres."
S["7e495a5d"] = "%s si mette in ginocchio."
S["7e4fa2e6"] = "Abbiamo abbastanza rifornimenti! Il nostro capitano ha ripreso posizione nel Field of Strife!"
S["7e505f4d"] = "Ora tocca a noi mettere in salamoia i tuoi piedi!"
S["7e578fe8"] = "L'incantamento è l'arte di migliorare gli oggetti con la magia."
S["7e6494e1"] = "Borgus lavorava alla Great Forge, ma ho sentito che si è trasferito a Stormwind quando hanno finito la ricostruzione. Si dice che abbia aperto una bottega nel Dwarven District insieme a un uomo di nome Kathrum Axehand."
S["7e6ce385"] = "Presto faremo tornare gli antichi dèi."
S["7e6e6db7"] = "Preparati, $N, perché il demone in questa sfera è una bestia vile."
S["7e6f473d"] = "Ah, ora ricordo! Il fossile misterioso l'ho dato a Hollee! Chiedi a lei."
S["7e6f6dbb"] = "Parlami dell'Alterac Valley."
S["7e73f47b"] = "TRADITORE!"
S["7e7861b8"] = "Bale può insegnarti l'arte della sopravvivenza. Cercalo sull'Hunter Rise."
S["7e7a2c4e"] = "Secondo il mio Almanacotron Gizmotico, dovremmo battere i goblin con venti secondi di vantaggio in più dell'ultima volta!"
S["7e7a46cf"] = "L'insieme di immagini, forme e simboli si ricompone davanti ai tuoi occhi. Il libro sembra conoscere la tua abilità nella lavorazione del cuoio e ti offre una scelta — ma attenzione — puoi sceglierne solo una e, una volta fatto, non potrai cambiare idea!:"
S["7e7be1ce"] = "Morte ai profanatori del High Order!"
S["7e7cc897"] = "Il Tempio della Luna è la dimora dei sacerdoti di Elune: lì troverai Jandria e Lariia, che ti daranno altri consigli sulla via del sacerdozio."
S["7e85de5e"] = "Ho bisogno di aiuto per recuperare un pezzo della mia Tenuta dell'Illusionista, Al'tabim."
S["7e864f85"] = "Se tu sia $Gpronto:pronta;, giovane, resta da vedere. Nemmeno i druidi più saggi e anziani sono mai davvero pronti, quando arriva per loro il momento della prova suprema.$B$BHai ascoltato le mie parole, e ora devi proseguire. Fa' tesoro di ciò che ti ho insegnato. Verrà il momento in cui la tua forza sarà messa alla prova. Il nemico devi affrontarlo come farebbe l'orso — con la forza del corpo e con quella del cuore. Impara dalla lotta, giovane. Va'... con la mia benedizione."
S["7e8bc468"] = "Le vie tortuose di Orgrimmar sono fatte apposta per ostacolare gli invasori. Te lo immagini uno di quegli gnomi rachitici, quanto ci metterebbe a perdersi qui dentro? Ah! Se gli andasse bene, lo scoverei e me lo terrei come animale da compagnia."
S["7e8de039"] = "Grazie ancora per aver aiutato Hilary, signore! Da grande voglio diventare un eroe proprio come te!"
S["7e91366a"] = "<Schiocca piano il becco verso di te.>"
S["7e9bce4d"] = "%s è $Gstordito:stordita; dall'Elune's Candle!"
S["7e9c64f2"] = "È vero, perfino la stranglekelp può tornare molto utile per mettere insieme quello che ci serve per la guerra che sta per scoppiare ad Ahn'Qiraj! Si usa in tantissimi modi: ci si fa il gelato per le giornate calde sotto il sole di Silithus, un unguento contro gli effetti di certe piante schifose, e serve a respirare sott'acqua, a indurire la pelle, a renderti veloce, a recuperare il potere magico; tante di quelle cose che non riesco a ricordarle tutte! Ho già detto che ci si fa il gelato?$B$BInsommuccia, un po' ne ho già qui, ma me ne serve ancora per arrivare al totale!"
S["7e9d4345"] = "Il vento sussurra a chi ascolta...$B$BLo senti?"
S["7ea48900"] = "Voglio altra birra! Datemi altra birra!"
S["7ea76ac2"] = "Come osi!"
S["7ea7adce"] = "NOOOO!!"
S["7eaaf5b2"] = "$N rivendica le stalle! Se nessuno interviene, l'Alleanza ne prenderà il controllo tra 1 minuto!"
S["7ebf9bf2"] = "LA MIA PAZIENZA SI STA ESAURENDO! VENITE INCONTRO ALLA MORTE, MOSCERINI!"
S["7ec94e64"] = "Chi sei? Dove mi trovo? Mi sento... così debole..."
S["7ece7117"] = "Sono l'uomo che fa per te, Ich. Dammi un faro!"
S["7ed3a62a"] = "La covata non cadrà!"
S["7edd7310"] = "Ora che il cristallo è qui..."
S["7edfef6f"] = "I lingotti sono solo in esposizione!"
S["7ee1da87"] = "Vuoi volare fino a Rut'theran Village? È una gentile concessione del Cenarion Circle."
S["7ee27458"] = "Sono il re serpente! Posso fare qualsiasi cosa!"
S["7ee59539"] = "%s cerca di chiamare aiuto!"
S["7eedee07"] = "Snivvle è qui! Snivvle reclama la Miniera di Dentefreddo!"
S["7f011bb1"] = "$GStraniero:Straniera;... ti prego... mettimi giù... sul giaciglio vicino a quell'albero laggiù..."
S["7f07f584"] = "%s sospira."
S["7f09aed1"] = "Ah, $Gun collega stregone:una collega stregona; che ha dimostrato almeno in parte il suo valore.$B$BLieta di conoscerti. Mi chiamo Menara Voidrender... e non per niente.$B$BMi sembri abbastanza $Gpotente e istruito:potente e istruita; perché altri strumenti... strumenti più potenti... siano bene accetti nelle tue mani e non affidati a sproposito. Se è così, parliamone. Altrimenti, beh, la strada per tornare al molo e prendere il largo la conosci."
S["7f09f179"] = "Ti aiutiamo a trovarli."
S["7f26f6e0"] = "$N, sento che la grande bestia si avvicina..."
S["7f274723"] = "L'abomination è arrivato! Avanti!"
S["7f31e677"] = "Cerchi Urtrun Clanbringer nell'Horde Embassy, sul lato ovest della Valley of Strength."
S["7f32bfa3"] = "Avrò pure novantanove problemi, ma ballare non è mica uno di quelli! Buon Hallow's End, $N!"
S["7f363587"] = "A Teldrassil i posti da visitare sono tanti. Dimmi cosa stai cercando."
S["7f3db783"] = "Grazie alla Luce sei qui! Sfodera la spada, ho un centauro alle calcagna!"
S["7f40aab9"] = "Come funzionino questi fuochi d'artificio non lo so, ma sono proprio belli!"
S["7f467479"] = "Tesoro, è pronto da mangiare. Vieni a lavarti e mangia."
S["7f49adc4"] = "Chi osa sfidarmi nel mio dominio?!"
S["7f4df96e"] = "Ben fatto, Edward e Tyler. State progredendo molto bene nel vostro addestramento. Metteremo presto di nuovo alla prova il vostro valore."
S["7f5bfabb"] = "Hai l'aria di chi cerca un passaggio per attraversare il Great Sea. Be', sei $Gcapitato:capitata; nel posto giusto: questo è l'ormeggio del Maiden's Fancy, la migliore nave passeggeri di queste acque. Appena arriva, sali a bordo, e prima ancora di accorgertene ti starai crogiolando al sole sulle spiagge sabbiose di Stranglethorn."
S["7f7a9748"] = "Devo smettere di fumare! Dammi un minuto per riprendere fiato."
S["7f7cd3a2"] = "La Royal Apothecary Society ha poca pazienza con gli sciocchi, e io pure. Forse la prossima volta che parleremo dei miei destrieri sarai $Gconsiderato:considerata; $Gun amico:un'amica; dell'Undercity. Fino ad allora..."
S["7f7dfb0e"] = "Tentar non nuoce!"
S["7f7f2fb6"] = "È fatta, drago. Fai strada."
S["7fa1e7ef"] = "Il First Aid non varrà le cure di un sacerdote, ma quando serve torna utile. Ti consiglio di passare da Thamner, nella Thunderbrew Distillery, e imparare quello che puoi."
S["7fa22fa6"] = "Dai solo un'occhiata alla merce, o c'è qualcosa in particolare che oggi posso aiutarti a trovare?"
S["7fa50a42"] = "%s ti indica l'Apparato Gizmotronico."
S["7fa6b90f"] = "%s si ferma."
S["7fa7ec93"] = "La luce è un faro che risplende per tutti. Che posso fare per te, $C?"
S["7fa960e2"] = "Spiriti degli Alti Nobili! Trovate la pace! Il Crystal of Zin-Malor è di nuovo intero!"
S["7faa21dd"] = "Se riesci a completare un mazzo di carte delle bestie, avrai in premio una carta lunacupa superiore del drago blu. Per ripristinare le energie magiche è molto utile."
S["7fb8b6d6"] = "Ho sofferto, ma ora sento che la sofferenza mi abbandona lentamente. Mi sento... libero."
S["7fc28ae6"] = "Lo studente non vale niente, maestro! Lo studente chiede scusa per la sua incapacità!"
S["7fc84416"] = "Mi serve una seconda testa come mi serve perdere la prima."
S["7fcf2744"] = "La guerra continuò, ma la volontà del grande condottiero era stata fiaccata. Ben presto l'intera Silithus fu sommersa dai silithid e dalle loro schiere Qiraji."
S["7fd077b1"] = "Scuoiatura"
S["7fd3719d"] = "Così, tutto d'un tratto, sei $Gun:una; 'Difensore dell'Alleanza', eh?! Beh, immagino che adesso vorrai andare alla Champions' Hall. È nell'Old Town, ma se non sei $Gun ufficiale:un'ufficiale; non ti fanno entrare, quindi forse dovrai accontentarti di parlare con Officer Areyn, lì fuori. Su, circolare."
S["7fdca038"] = "Molto bene, $N."
S["7fe81cf2"] = "Sì, Highlord Mograine: tra i fondatori dell'ordine originario della Scarlet Crusade. Un cavaliere dalla fede e dalla purezza incrollabili; Mograine è stato tradito dal figlio e ucciso dalle forze di Kel'Thuzad dentro Stratholme. Ed è così che sono $Gfinito:finita; qui..."
S["7fe8ba31"] = "%s dispone davanti a sé il Mind's Eye e i Cristalli Risonanti..."
S["7fefa871"] = "In tutti gli anni in cui abbiamo avuto rapporti con gli spiriti del vento, non hanno parlato neppure una volta del Signore del Vento come di una figura da venerare. Riconoscevano che esisteva un essere chiamato Al'Akir, ma evitavano di invocarne il nome, quasi lo temessero.$B$BAnche se questo Al'Akir fosse un \"Signore del Vento\" onnipotente o il sovrano degli elementali del vento, i miei secoli di comunione con gli spiriti mi hanno convinta che, quanto meno, fra gli abitanti di Skywall non tutti lo amano. Temo che cercare di trattare con Al'Akir possa solo affrettare la nostra rovina."
S["7ff1e0c5"] = "Farete un bel banchetto con la mia lama, per 'sto Winter Veil! Yeargh!"
S["7ff4827e"] = "Cosa? Come osi dirmi una cosa del genere?!?"
S["7ff6b023"] = "Forza, Dadanga! Marcia, ragazza, marcia!"
S["7ff98fb7"] = "Dovremmo proprio sistemare presto questo recinto."
S["7ffa5d4c"] = "Perché le guardie di Stormwind non sono venute?"
S["800f39af"] = "Lame di luce!"
S["80134e01"] = "Siamo andati avanti così per circa sei mesi, e in quel tempo abbiamo visto la casa cambiare in modo spaventoso. Mostri immondi giravano liberi per la villa, e cultisti oscuri ne riempivano ogni angolo di oggetti di ogni genere, legati a rituali e sacrifici. Sapevamo di non poterci nascondere ancora a lungo.$B$BCome ci aspettavamo, ci hanno scoperti e catturati. Ci hanno tolto tutti i vestiti e ci hanno stesi dentro un cerchio di sangue, e lì siamo rimasti per giorni, nudi e terrorizzati."
S["8013a870"] = "Ho ucciso una peacekeeper e ho rubato alcune windstones."
S["802609b0"] = "Ci vuole un po' di pratica per stare così vicino ai silithid senza farsi notare. Se puoi evitarlo, non te lo consiglio."
S["802bdaf7"] = "Rifornire gli avventurieri è un onore per me: sono gli eroi di domani."
S["802e2512"] = "I segreti di Suntara non lasceranno queste terre."
S["802fc340"] = "Vediamo quanto sei capace, d'accordo? Se farai questo lavoro come piace a me, il tempo per insegnarti lo troverò!"
S["803d925a"] = "È ora che t'imparo le buone maniere, $Gfigliolo:figliola;."
S["80487c94"] = "$GBenvenuto:Benvenuta; a Revantusk Village, $Gstraniero:straniera;. Sono Primal Torntusk e guido i troll Revantusk."
S["804908b4"] = "Ottimo lavoro, tutti quanti! Lo Scourge al castello è stato sconfitto."
S["804a4d3a"] = "E se uno muore, due si rialzeranno!"
S["805a15be"] = "In arrivo, 5 su 5!"
S["80675360"] = "Pietra rilevata. Accesso non autorizzato alla conoscenza. Eliminare."
S["8067d16f"] = "%s corre via in fretta dall'Umi's Mechanical Yeti."
S["806a0506"] = "Grazie per le provviste, $N."
S["806e782c"] = "%s iniziano a spingersi avanti e indietro."
S["8075807a"] = "Oh sì, che meraviglia! Aspettavo $Gun emissario:un'emissaria; del tuo popolo, e sono proprio felice di conoscerti.$B$BMi piacerebbe tanto riceverti a Gnomeregan, la nostra città natale, ma per il nostro popolo sono cominciati da poco tempi duri e per ora la nostra patria è perduta.$B$BPerò King Bronzebeard è sempre stato amico di noi gnomi, e in questo momento difficile ha avuto la gentilezza di aprirci la sua città.$B$BTi auguro ogni fortuna nelle tue avventure su Azeroth, e non vedo l'ora di avere altre occasioni per conoscere meglio la tua gente.$B$BArrivederci, $N."
S["8076d870"] = "Devo fare pipì."
S["80815166"] = "Nella conoscenza dell'incantamento ti sei davvero $Gdistinto:distinta;. Se sei $Gdisposto:disposta;, c'è ancora molto da imparare: parla con Taladan nella Craftsmen's Terrace, a Darnassus."
S["808234f6"] = "È in aria e.... è dentro!"
S["808e9340"] = "La tua vittoria qui affretta solo la tua fine!"
S["809322fe"] = "Cos'era? Un Sea giant? Meglio prevenire che curare. Fuoco!"
S["80951b04"] = "sembra sul punto di andare in frantumi!"
S["80961971"] = "Governo questo regno da 10.000 anni, e in tutto questo tempo ho ascoltato molti racconti affascinanti da coloro che hanno camminato sul sacro suolo dell'House of Shen'dralar.$B$BSono legato a questo luogo, perciò scambio spesso storie con i visitatori. Hai una storia per me, o vorresti forse ascoltarne una?"
S["8099c804"] = "Sì, Vrang, è vero. Quando Daelin Proudmoore ha preso il controllo di Theramore, ha fatto cose terribili. Cose disonorevoli, e io non potevo averci niente a che fare."
S["80b54277"] = "I nostri nuovi alleati ci vendicheranno!"
S["80b6e5fa"] = "Con l'esperienza che hai, temo di non avere niente da insegnarti. Ma non sei ancora $Garrivato:arrivata; in fondo alla strada: parla con Lucan Cordell, là dietro il bancone. Ti guiderà nella prossima tappa del viaggio."
S["80c279b3"] = "Le bottiglie sono impolverate, ma il liquore scende liscio!"
S["80cc8946"] = "Lo sciamanesimo? Qui da noi non lo pratichiamo. Prova a Ironforge."
S["80cd7a89"] = "Theramore è rinomata per l'addestramento eccezionale che dà ai guerrieri, ma temo di non poterti aiutare."
S["80d406ce"] = "Non contaminare queste rovine, mortale. <Vieni $Gavvolto:avvolta; da un accecante lampo di luce. Una creatura fatta interamente di fiamme è l'unica cosa che ricordi di aver visto.>"
S["80d7e346"] = "Se vuoi tornare in volo a Thunder Bluff, dovresti rivolgerti al mio collega tauren, Bunthen Plainswind."
S["80e260cf"] = "Feralas: A History... Hmmmm... Fammelo esaminare un momento."
S["80e87f3c"] = "Vorrei addestrarmi."
S["80ec5d72"] = "Divise in due per formarne una. Le lame gemelle sono legate a Zul'Farrak.$B$BQuando le gemelle saranno ritrovate, Sul'thraze rinascerà."
S["80edb2f1"] = "Ti servono materiali per l'alchimia, eh? O hai altri affari da sbrigare con me?"
S["80ee6da2"] = "Se il nostro popolo vuole sopravvivere, dobbiamo studiare le vie della natura e scoprirne i segreti."
S["80fa6bc4"] = "Ti do il benvenuto, $C. Di rado riceviamo visitatori fin quaggiù, a questi livelli de Apothecarium... a meno che, s'intende, qualcuno non voglia qualcosa... o non ne abbia bisogno.$B$B<$GIl Chimico:La Chimica; Coely ride.>$B$BCome posso aiutarti oggi, mmh?"
S["80fa8dbe"] = "Piacere di conoscerti, $C. Sono Roetten e guido la Reclaimers Incorporated.$B$BIo e la mia gilda siamo specializzati nel recuperare beni perduti. Di solito ingaggiamo avventurieri coraggiosi e li mandiamo a sbrigare incarichi per chi non è in grado di farlo da sé, o non ne ha il tempo."
S["80ffeabd"] = "Gorzeeki mi dice che gli hai portato tutto ciò che gli serve per la Campana di Dethmoora, la Ruota della Marcia Nera e la Candela del Giorno del Giudizio.$B$BBen fatto, $N! Sei $Gquasi pronto:quasi pronta; per compiere il tuo rituale e vincolare un destriero del terrore!"
S["810477e6"] = "%s ruggisce ancora verso Terenthis, ma questa volta il druido sembra capire l'orso."
S["8105298b"] = "\"Un'abilità per chi desidera superare gli ostacoli.\" Credo che sia così che Faelyssa descrive le sue competenze.$B$BSe la pensi come lei, raggiungi la Cenarion Enclave, nella parte settentrionale di Darnassus, dove tiene le sue lezioni."
S["8110ad89"] = "Non credo che sia abbastanza forte."
S["81127208"] = "L'Iceblood Graveyard si trova sul lato sud del Field of Strife, a est dell'Iceblood Tower.$B$BAl momento è controllato dall'Orda."
S["81178c46"] = "Mmmmh..."
S["811aff1c"] = "%s indica la pergamena a terra."
S["812e6ea2"] = "%s rovista tra i libri."
S["8135541a"] = "Più o meno è tutto qui. Quando il riposo vicino al fuoco ti avrà dato il suo vantaggio, torna a parlarmi."
S["81369cb5"] = "%s comincia a frugare tra le cose dello speziale."
S["81407fc9"] = "VIENI A CAPO JANEIRO. TI ASPETTO, SMOTTS..."
S["8143aac3"] = "Quanta tristezzza... Il passsato non si può cancellare..."
S["8144e98a"] = "Energia d'emergenza attivata! Avvio del motore di deambulazione! COCCODÈ!"
S["814a8080"] = "Ti spolvero via dalla faccia della terra!"
S["81717559"] = "Razorfen Downs è all'estremo sud delle Barrens, sul lato est della strada."
S["81746b42"] = "Il cucchiaio non esiste."
S["81824eb7"] = "È giunto il momento, Davil. È giunto il momento della tua morte!"
S["819818a5"] = "Grrr, cosa vuoi, $R? Oh, sarai qui per le lean wolf steaks per l'imminente Guerra di Ahn'Qiraj. Sì, hai sentito bene, le sto raccogliendo io, e allora? Ne hai una pila fresca per me? Me ne serve solo una certa quantità, e a quanto pare per ora non ci siamo ancora arrivati."
S["819f5bcd"] = "È un vero piacere incontrare finalmente qualcuno del tuo popolo. Ho sentito dire molto degli shen'dorei e della vostra lunga storia, e sono lieta di vedere i nostri cugini tornare a casa, su Kalimdor, dopo tanto tempo.$B$BNon ti nascondo che fra il nostro popolo e gli alti nati il rapporto è... complicato. Alcuni elfi della notte diffidano subito di chiunque discenda da loro, come quelli del vostro High Order. Ma hai la mia parola: finché resterai ospite nella nostra città, sarai $Gtrattato:trattata; con il massimo rispetto.$B$BTi prego, sentiti a casa tua. Ti invito a esplorare e a conoscere la nostra cultura: dopotutto, in un certo senso, è anche la tua."
S["81a2c549"] = "%s borbotta parole incoerenti."
S["81a6059d"] = "%s lancia della dinamite in aria, che atterra lì vicino."
S["81b63e55"] = "Non posso credere che a quei goblin avidi sia permesso di vendere la loro merce rovinando lo spirito di questa festività."
S["81b9ac4a"] = "La Tower Point East controlla il passo tra il Field of Strife e i territori dell'Orda a sud.$B$BNon è controllata da nessuna delle due fazioni. L'East Frostwolf Tower protegge il cancello tra il Frostwolf Village e la Frostwolf Keep.$B$BNon è controllata da nessuna delle due fazioni."
S["81bfb221"] = "Un po' di cibo adesso ci starebbe proprio bene."
S["81c85f38"] = "Avranno anche cacciato tutti gli altri contadini, ma i Saldean non lasceranno mai Westfall."
S["81da3760"] = "Saluti, $C. Sono $Gl'istruttore:l'istruttrice; di conciatura di Darnassus. In cosa posso esserti utile?"
S["81e1e837"] = "$N! Le nostre provviste si stanno esaurendo, e finché non ne avremo altre non potremo lanciare grandi assalti via terra nel Field of Strife!$B$BParla con lo Stormpike Quartermaster. Ti dirà cosa puoi fare per rifornire le nostre forze d'assalto."
S["81e23d47"] = "Cacciatori e le vostre fastidiose cerbottane!"
S["81e32d45"] = "Le Piastre di Uldum sono dischi sintetizzati dai Creatori: aprono l'accesso al complesso di Uldum e custodiscono dati precisi su ciò che i Creatori facevano qui.$B$BQuanto all'aspetto, la loro circonferenza è quasi identica a quella della serie di dischi che hai adesso. I segni, però, parlano di Uldum, non del complesso di Uldaman."
S["81e69acb"] = "La specifica della tua classe risulta incompatibile: non sono in grado di aiutarti a rettificare alcuna situazione di carenza di abilità."
S["81e8f5e0"] = "Il medico della città sta nella torre all'estremità nord-est."
S["81e9e9cf"] = "Per un rame ti lucido l'armatura."
S["81f28a6c"] = "FUNZIONE ESEGUITA. RITORNO IN MODALITÀ RIPOSO."
S["81f2da67"] = "Indicazioni per dove?"
S["82331a0b"] = "Hrmmm..."
S["82360b9e"] = "Questo te lo prometto: la Valle sarà nostra."
S["8256e507"] = "Beh, $Gamico mio:amica mia;, hai più abilità di me. Perché non vai a trovare il mio vecchio amico Rotgath Stonebeard? È rimasto a Ironforge quando me ne sono andato per unirmi all'esercito di Jaina. Sono sicuro che potrà insegnarti qualcosa, o almeno conoscerà qualcuno che può farlo. Se è ancora in giro, di sicuro sarà a The Great Forge."
S["8265fec8"] = "Guarda! Sta arrivando qualcosa!"
S["8269f5ff"] = "Ti prego, $Gcampione:campionessa;, proteggi il nostro popolo."
S["826f1e14"] = "Di questo passo avrei fatto prima a raccoglierle da me!"
S["82705bca"] = "Informazioni sul Carapace Cromatico."
S["82737c8e"] = "La Luce deve prevalere!"
S["827a5850"] = "Salute, $Gcittadino:cittadina;. Se non hai nulla da chiedermi, ti prego di proseguire per la tua strada."
S["827b5a6a"] = "Nel tempo prima del tempo, in quella che gli usurpatori avrebbero poi chiamato la First Age of Creation, su questo mondo regnavano il mio padrone e i suoi fratelli. Furono loro, gli Old Gods, a creare ogni cosa.$B$BE furono sempre loro, alla fine, a venire rovesciati da coloro che si sarebbero fatti chiamare Plasmatori."
S["827d8680"] = "Allora, cosa vuoi fare oggi?"
S["827f371c"] = "Oh, eccoti qui, Rockbiter! Scusa, lo so che non dovrei allontanarmi."
S["828a1f5c"] = "Uden wos lo firalaine, Danieb."
S["82934161"] = "Intrusi! Attaccateli!"
S["8298b9f4"] = "È ammirevole quello che The League of Arathor cerca di fare ad Arathi Basin. Peccato che quegli abomini non morti e i loro amici dell'Orda ci si mettano di mezzo. Va' a Stormwind Keep. Lady Hoteshem ti aspetta nella sala delle udienze del Re e può aiutarti a raggiungere Arathi Basin."
S["8299ec37"] = "Non posso addestrarti, giovane."
S["82b6ac26"] = "Dadanga! All'attacco!"
S["82b7fbc2"] = "Quindi sei qui per le asce dei Warsong. Beh, era ora, $N. Quella cassa se ne sta lì fuori da giorni, ormai.$B$BPortala pure via quando sei $Gpronto:pronta;."
S["82b94da7"] = "Non sapete quello che fate! Dobbiamo distruggervi per il vostro bene."
S["82c257f0"] = "Salve, $Gcittadino:cittadina;. Cosa posso fare per te oggi?"
S["82c55040"] = "Alla banca di Darnassus, nel cuore della nostra meravigliosa città, puoi custodire i tuoi beni terreni."
S["82d5eb5c"] = "Grazie, siete un pubblico fantastico! Sarò qui tutta la settimana!"
S["82e12ec1"] = "Ehi! Smettila!"
S["82ec8b29"] = "Una carica non basterà, credo. Tienili ancora a bada!"
S["82ece3e8"] = "La spada non deve farti paura, $Gpivello:pivella;. È il montone che ti frega!"
S["83065465"] = "Salve, Selarin. Temo di non poterti aiutare al momento, ma forse qualcuno degli avventurieri qui ad Auberdine può farlo..."
S["830decea"] = "Con la teoria Suriana sì, ma con l'approccio Y'seriano no."
S["831a77b3"] = "Mograine è caduto? Pagherete per questo tradimento!"
S["831a9ad0"] = "Non sarà la fine della Scarlet Crusade! Non spezzerete la nostra linea!"
S["831be3e6"] = "Finalmente l'agonia finisce. Ho deluso voi, mia Regina. Ho deluso tutti noi..."
S["8323d863"] = "Sì, nessun problema, $N! Scusa... credevo avessi già finito."
S["832889f9"] = "Re, y ealdor Regenthor. Hir ras novaedi re uden va y vandar thorniss? Melka E gol ruff ras y garde va vil?"
S["832ad434"] = "Grazie degli elmetti, $N. Le spese mediche scenderanno di parecchio..."
S["832b7880"] = "Non ci credo che quel forsaken di carro si è rotto. Da 'ste parti la fortuna non si vede mai. . . ."
S["832ba238"] = "Di' a Lexlort che se vuole le informazioni, deve solo pagare! Purtroppo, questo significa che non può uccidermi se vuole le informazioni — visto che ho bruciato i piani di battaglia e tutto il resto..."
S["832bd668"] = "Anche un piccolo ritocco agli ingredienti può trasformare del tutto una pozione. Pazienza e precisione, giovane: ti serviranno in ogni campo della vita."
S["8338d57a"] = "%s fugge per mettersi al sicuro vicino a un'altra tigre."
S["83435dce"] = "Difficilmente l'High Order sarà comprensivo, che sia stato un incidente o no. Ci sarà una resa dei conti. Posso solo sperare che le teste fredde abbiano la meglio fra la tua fazione e l'High Order... almeno finché la crisi con l'Al'Aketh non sarà risolta."
S["83444a36"] = "Cerchiamo avventurieri disposti ad aiutarci, $N. Ci darai una mano?"
S["83488e99"] = "La prossima volta che vai nel Molten Core, uccidimi un Firelord, d'accordo?"
S["834f9cab"] = "Ormai non resta che piangere. Tutto il materiale bellico viene trasportato alla Cenarion Hold a Silithus, e l'ultimo carico arriverà lì in meno di un giorno. Non dovrebbe mancare molto prima che lo scettro sia ricomposto e la guerra cominci finalmente."
S["83501aad"] = "Distogliete lo sguardo, bambini. La furia sanguinaria ha preso il sopravvento..."
S["8359f959"] = "La prima volta che ho visto i non morti ho pianto, perché non riuscivo a immaginare il loro orrore e la loro solitudine. Allora la Madre Terra mi ha parlato; mi ha cantato nel sangue. E mi ha detto: \"Salvali.\""
S["835a9903"] = "Onore e lode saranno tuoi, basterà prenderli, $C! Cerca Kurden Bloodclaw nel Royal Quarter di questa città."
S["83763cb7"] = "opzione taxi"
S["83764a78"] = "Salve, $C. Qui raccolgo linen bandages per lo sforzo bellico di Ahn'Qiraj: ci metterà tutti alla prova, ma ci renderà più forti per la guerra che verrà. Tutte le bende che vorrai donare, te lo assicuro, aiuteranno a salvare la vita dei nostri soldati, quando sarà il momento. Me ne serve un certo numero, e finora sono $Griuscito:riuscita; a raccoglierne una parte. Ci aiuterai?"
S["837ee8c0"] = "È vero, $N. Le ruote della rovina ora girano, inesorabili, verso il vero ritorno di Hakkar!"
S["838e7ab5"] = "Aiuto!! Te l'avevo detto che questo posto era maledetto!"
S["839a1375"] = "La legione di Roccianera arriva, nanetti! Bruceremo la terra e daremo fuoco ai cieli. Nessuno sopravviverà..."
S["839feb7f"] = "Sono buone le lame che fai, $N. Tagliano una pietra e restano abbastanza affilate da tagliare una gola. Ma ne ho viste di migliori: le fa un orco di nome Kelgrum Asciarossa. Vai a imparare tutto quello che può insegnarti."
S["83a8dc90"] = "Mostra il tuo apprezzamento per l'arte e lascia cadere qualche moneta nel mio cappello!"
S["83a95e4a"] = "Te lo stai inventando."
S["83b6e14d"] = "Continua così, $N, e ti insegno l'educazione a suon di botte."
S["83ba7f0d"] = "Sei sulla buona strada, $N. Ma hai ancora molto da imparare. Forse la tua prossima lezione si trova nelle Barrens meridionali."
S["83bea204"] = "Non lasciare che il tintinnio dei campanelli si porti via quello che ti tintinna in tasca! Per le feste di Winter Veil, compra le leccornie di Smokywood Pastures!"
S["83cb1b34"] = "I Kolkar regneranno!"
S["83d91ce7"] = "Non dimenticare di prendere un po' di Flame in a Bottle dalla cassa qui. Ti servirà per distruggere la loro tenda di comando."
S["83d9facd"] = "Vrok ha detto che il mirino del fucile di Grumlar è starato. Immagino che dovrei controllarlo."
S["83e22ff9"] = "Siamo del tutto al sicuro dalla vostra misera banda!"
S["83ec6848"] = "Non... è... il momento... migliore, $N. Devo concen... trarmi."
S["83f06186"] = "Se intendi liberare Myzrael, te ne pentirai!"
S["83f1ea21"] = "Sei tu, mio caro Tobias???"
S["83f4e242"] = "Allora dobbiamo porre fine ad Athrikus Narassin. Dimmi, spirito, dove possiamo trovare le altre gemme dell'anima per annullare la sua magia?"
S["83f914e5"] = "Anche il \"The Arcanist's Cookbook\" è sparito! È un disastro!"
S["84018b9f"] = "Adesso tu $Gquello:quella; forte! Evviva nuovo re dei Gordok!"
S["8417f933"] = "I Figli di Thaurissan vi guarderanno morire nel Ring of the Law!"
S["84273453"] = "Le tue abilità hanno superato le mie, giovane. Va' da Una, che ha una bottega sull'altopiano centrale di Thunder Bluff. Saprà istruirti negli insegnamenti che cerchi."
S["842b0682"] = "$N, evocami di nuovo quando dovrai eseguire ancora il rituale."
S["84307aca"] = "Trattenermi qui non è la decisione giusta, Marcus."
S["8431c7e0"] = "Ebbene, $Gamico mio:amica mia;, hai raggiunto vette che certi possono solo sognare. Complimenti! E ora, senza altre cerimonie, è il momento della tua ultima lezione!"
S["84324aa6"] = "Quel Granis Swiftaxe riuscirebbe a stendere persino un pesce a forza di bevute, eppure con l'ascia va ancora a segno. Però, se cerchi un addestramento, ti conviene beccarlo finché riesci a capire quello che dice."
S["843269da"] = "Quell'istruttore sta in una casa vicino al molo dell'High Order, all'estremità sud-est della città."
S["84399b51"] = "Mai come ora i seguaci delle antiche usanze degli Highborne hanno avuto tanta fame di conoscenza e tanta voglia di riprenderci ciò che abbiamo perduto. Se hai le doti per impugnare il potere dell'arcano e lo desideri, posso aiutarti a muovere i prossimi passi."
S["844546b4"] = "No... no. Lordaeron sarà libera dai non morti. Vedrai."
S["844549a4"] = "Abbiamo chiesto ai Peacekeepers di venire ad aiutarci a scacciare i banditi, ma solo con il culto hanno già troppo da fare e non hanno potuto mandare nessuno."
S["844e0683"] = "Intrusi! Uccideteli! Non fateli entrare nella stanza!"
S["845bf2e7"] = "Buona idea!"
S["845c8cd1"] = "Macché, qui fuori nessuno può insegnarti l'erboristeria. A Ironforge, però, credo che avrai più fortuna."
S["846325db"] = "Con piacere, signore."
S["84635606"] = "Buon Hallow's End, $C!"
S["8465af93"] = "Sire lo Staghelm, dove vai? Spezzeresti il nostro legame per orgoglio?"
S["8468bebe"] = "Quale saggezza posso trasmetterti?"
S["84737b07"] = "Ha preteso che tornassimo subito a Hive'Regal! Brann non voleva saperne di quella sfrontatezza, e le ha detto che in quegli alveari non saremmo mai tornati senza un esercito alle spalle. Era diventato fin troppo pericoloso: quegli insetti puzzolenti sembravano triplicati dalla prima volta che ci eravamo entrati.$B$BÈ stato allora che Natalia ha perso le staffe!"
S["84746f22"] = "Ho finito le frecce! Temo che se ne arrivano altri dovrai affrontarli da $Gsolo, amico mio:sola, amica mia;."
S["8484a73e"] = "Cosa chiedi al Blue Flight?"
S["8488d12f"] = "Muori, straniero!"
S["848d1099"] = "Gli gnomi possono essere difficili da colpire per via della loro statura. Però hanno il vizio di ballare in giro dimenando i fianchi. Quando lo fanno, colpiscili così..."
S["84956b5f"] = "%s taglia e modella i tronchi, ricavandone assi di legno lisce."
S["84961fd9"] = "Déjà vu. Per un momento ho creduto di essere tornata a casa... prima della piaga..."
S["84996543"] = "Accidenti! Questa sì che è un'arte che vale la pena di conoscere. Tognus picchia sull'incudine con una furia che si vede di rado. Perché non vai a scambiarci due chiacchiere e a vedere cosa può insegnarti?"
S["849e2c0f"] = "Devi essere in rapporti amichevoli con gli orchi di Orgrimmar prima che io ti insegni a cavalcare, $C."
S["84a17514"] = "Narain, mi serve un altro kit speciale."
S["84a6729b"] = "Lastricherò le strade con le tue budella, $R."
S["84ad6cf8"] = "Sei $Gdiventato:diventata; $Gun cacciatore:una cacciatrice; coi fiocchi, $N! Non hai solo dimostrato quello che sai fare: hai battuto pure Daryl, e per me questo vale qualche punto in più!$B$BQui sei sempre $Gil benvenuto:la benvenuta;."
S["84b8b9b7"] = "Chi osa risvegliare Aquementas?"
S["84d54cce"] = "Mmm, buona roba. Di nuovo al lavoro."
S["84e23fa5"] = "<Lydros fruga nella sua veste e ti porge una lama elfica piatta e opaca.>$B$BIn tempi remoti, ben prima ancora della War of the Ancients, esisteva questa lama."
S["84e4ec35"] = "In qualità di Sorvegliante facente funzione di questo complesso qui, ho il dovere di assicurarmi che ogni forma di affari, lavoro, riposo e svago che ci si possa svolgere abbia un certo livello di noia.$B$BSe ti chiedono di fare qualcosa che ti sembra troppo facile e senza seccature, vieni subito a fare rapporto a me."
S["84ec1b7b"] = "Mi manca tantissimo il mio cane!"
S["84f6097a"] = "Via da quei barili!"
S["84faa94e"] = "Abbiamo metà della silitite che ci serve. Non fermarti ora!"
S["850f2068"] = "L'incubo di Ursal è finito! Siamo liberi!"
S["851195c9"] = "La guerra è una prova sanguinosa e sporca, piena di dolore, sofferenza e morte. Ma chi sopravvive torna con un nuovo rispetto per la vita. Per non parlare di una raccolta di storie da raccontare al bancone, piene di valore e coraggio. Allora dimmi, $Gragazzo:ragazza;, sei qui per creare qualche storia? O solo per sentire qualcuna delle mie?"
S["85164338"] = "Hai una volontà forte e un intento chiaro.$B$BForse sei $Gdegno:degna;..."
S["851dde21"] = "Lo Stonehearth Bunker protegge il fianco orientale del Field of Strife.$B$BÈ controllato dall'Orda."
S["852cb125"] = "Wow! Guarda che centro!"
S["852dd3ad"] = "Il Dun Baldar North Bunker protegge l'ingresso orientale di Dun Baldar.$B$BÈ controllato dall'Alleanza."
S["852ee81c"] = "Finalmente, Redridge. Un piacevole cambiamento rispetto alla nebbia fredda e scura di Duskwood."
S["8533be13"] = "Mi resta poco tempo in questo mondo, ma se la Luce vorrà, basterà per compiere il mio destino. Quando affronterai Baron Rivendare, io sarò con te."
S["855c1449"] = "Venite, miei accoliti. Prendete le verghe della canalizzazione e create il cerchio d'evocazione superiore."
S["85607342"] = "Non fidarti di chi va in giro con una tunica grigia e la testa rasata. Al'Aketh, si fanno chiamare, e sono una minaccia.$B$BHo sentito perfino che armeggiano con i piloni di ancoraggio intorno all'isola.$B$BA dar retta ai Windshapers, quei piloni sono l'unica cosa che tiene Zephras sospesa qui nel piano elementale. Manometterli sarebbe una follia!"
S["8561d7a9"] = "%s esplode e libera diverse Bile Slimes!"
S["8566a72a"] = "Elder Nightwind passa le giornate al santuario di Jaedenar, nel Felwood."
S["856d7186"] = "Chi controlla la Frostwolf Relief Hut?"
S["8587578e"] = "Buona... buona, l'A-Me. L'A-Me buona. Casa. Trova casa."
S["85983bc9"] = "Lo eri. L'Occhio non sbaglia mai.$B$BDopotutto sei $Gun sacerdote:una sacerdotessa;, e $Gun sacerdote potente:una sacerdotessa potente;, se l'Occhio ti ha mostrato questo ricordo orribile.$B$BSei $Gvenuto:venuta; a cercare redenzione e non te ne rendi nemmeno conto... Vero?"
S["859fe1f3"] = "Och! Quel Daryl Riknussun è un cuoco geniale! Fa un chili così piccante che ci potresti temprare l'acciaio! La ricetta non credo che te la insegnerà, ma di sicuro ti aiuterà a diventare $Gun buon cuoco:una brava cuoca;. Lo trovi al Bronze Kettle, laggiù sul lato nord-orientale di The Great Forge."
S["85b34b55"] = "Ehi là, $Gviaggiatore:viaggiatrice;! Sei $Gnuovo:nuova; in città? Be', quando ti sarai $Gsistemato:sistemata;, passa da me se ti serve un lavoro. Sto facendo gli straordinari per preparare la Festival of Winds, e per tenere piene le dispense ogni aiuto è ben accetto!"
S["85b37ec2"] = "Ben fatto! Lo sapevo che avevo ragione su di te, qualunque cosa dicessero gli altri. Ah ah! Scherzo! Bene, avanti con le lezioni..."
S["85b95ab3"] = "Soldati Theoric, Kitrin, Blythe, Agmond..."
S["85c05806"] = "Parlami di Drek'Thar."
S["85d0273c"] = "Oh, $N, aspetta un momento! C'è un'altra cosa! Torna qui!"
S["85e48c73"] = "Ci sono due miniere ad Alterac: l'Irondeep, nel territorio dell'Alleanza, e la miniera Coldtooth, nel territorio dell'Orda. Entrambe le miniere sono una ricca fonte di minerali e in passato venivano usate per conservare le provviste in eccesso.$B$BOra queste miniere sono continuamente contese fra l'Orda, l'Alleanza e gli abitanti del posto."
S["85e495fe"] = "Remulos, vedi come cadono facilmente davanti a me? Puoi fermare tutto questo, stolto. Consegnami il druido e sarà tutto finito..."
S["85e78a23"] = "Bene, bene, guarda un po', scintilla, ce l'abbiamo fatta. È tutto raccolto e pronto a partire. Adesso aspettiamo solo quei buzzurri dell'Orda, e appena si danno una regolata si parte in quarta per Ahn'Qiraj!"
S["85f095da"] = "Questo porcile non è proprio comodo, ma ha la sua storia, e allora Stonard dev'essere importante per qualcuno. Ci scommetterei che restiamo qui per questo. Non certo per il panorama — manco somiglia a casa."
S["85f5183d"] = "Servirò il padrone... nella morte!"
S["860478f8"] = "Beh, pare che abbiamo tutta l'alborella cotta che possiamo salare e conservare come si deve per la prossima guerra di Ahn'Qiraj. Grazie per aver chiesto, però, $C. Se ti va, chiedi in giro agli altri raccoglitori. Scommetto che c'è qualcun altro qui a cui servirebbe il tuo aiuto per raccogliere quello che gli serve."
S["86086e6d"] = "La tua formazione è quasi completa. Solo un'ultima prova ti separa dal coronamento di tutti i tuoi sforzi..."
S["86130d26"] = "Ugh... la malattia è potente. E attacca la mente..."
S["8619bbd4"] = "Dai l'ordine, Comandante. Farò a pezzi la metà inferiore della loro base."
S["861d138d"] = "Pozioni e oli: è questo che Yelmak ti insegnerà, se ne sarai $Gdegno:degna;. Cerca la sua bottega al centro de The Drag."
S["86265bb0"] = "Preda misera."
S["8627ca0d"] = "Recita le tue preghiere!"
S["86360956"] = "Lo so che stavolta funzionerà... I miei ultimi 13 tentativi erano solo prove!"
S["863ab3d4"] = "Forse... E adesso che faccio?"
S["863eaa80"] = "Imparare a essere tutt'uno con la Natura agli occhi della Madre Terra è motivo d'orgoglio. Se desideri apprendere le vie del Cacciatore, devi cercare Yaw Sharpmane all'estremità nord di Bloodhoof Village."
S["863ebd6c"] = "Sai chi sono io, fanatico?"
S["864479ba"] = "Sono qui! Sono proprio qui! Aiutatemi!"
S["865178b0"] = "Ti servono provviste?"
S["86527636"] = "%s trasforma gli oggetti in un totem."
S["865f9f8a"] = "L'invenzione, $Gmio caro:mia cara; $C, è due percento ispirazione in bottiglia, quattro percento esposizione al sole, sei percento probabilità di temporali in attenuazione entro metà pomeriggio e novantatré percento Rumplesnicker.$B$BAspetta, fa cento? Gli appunti ce li ho qui da qualche parte."
S["86608ade"] = "Soldato, chiama subito Captain Blackanvil!"
S["866c1564"] = "Nulla deve insozzare i giardini! Devi essere $Gdistrutto:distrutta;!"
S["866cea24"] = "%s si nasconde tra i cespugli."
S["866e8cf8"] = "Se te la prendi con Silas, te la prendi con me. Buona giornata."
S["8673ee7e"] = "Sia noto a tutti che $N, $C dell'Alleanza, si è $Gguadagnato:guadagnata; il rispetto eterno di Ironforge e di tutta l'Alleanza. Ha condotto grandi trattative con Timbermaw Hold e compiuto per loro imprese valorose a nome nostro. È $Gandato:andata; ben oltre il proprio dovere. Tre urrà per $N, $Gun vero eroe:una vera eroina; dell'Alleanza!"
S["86784a5d"] = "Rovina profonda"
S["867ed21c"] = "Quale che sia la causa, dobbiamo trovare presto una soluzione prima di distruggerci a vicenda. Dimmi, cosa sai di Kalimdor?"
S["867ff309"] = "L'equilibrio della natura è delicato: basta poco a romperlo. Sei $Gcoraggioso:coraggiosa; abbastanza da rimettere le cose a posto?"
S["86807eae"] = "Ah... allora l'hai trovato.$B$B<Mathredis indica il libro che porti con te.>$B$BHai raccolto i componenti che servono?$B$BLe manifestazioni elencate nel compendio, imbecille!"
S["868fc76d"] = "La tua vita è perduta!"
S["869b1aa1"] = "Preparatevi, perché presto lanceremo un assalto contro coloro che si facevano chiamare \"I Forsaken.\""
S["869fe9fc"] = "Benone, allora! Dunque, ero giù alle pozze di lava del Molten Span a collaudare la mia tuta anti-lava, e andava tutto alla grande: riuscivo persino a nuotare in quella roba senza la minima ferita!$B$BE così eccomi lì, a farmi gli affari miei e a fare qualche bracciata a dorso, quando all'improvviso questa cosa mi inghiotte $Gintero:intera;! Senza la mia tuta anti-lava e il distributore di pastiglie di cibo incorporato, sarei $Gstato:stata; $Gspacciato:spacciata;!"
S["86a761ca"] = "Mentre Greta concentra le sue energie sul recupero di Jaedenar e su coloro che ritiene i principali responsabili della corruzione qui a Felwood. Io passo il mio tempo a studiare gli effetti che la corruzione ha avuto sulla terra.$B$BIn che modo ha colpito le creature di questa terra? Cosa bisogna fare per porre fine al dolore della loro sofferenza?$B$BPurtroppo la corruzione è così profonda che il sonno eterno è troppo spesso la risposta."
S["86a865e8"] = "L'Iceblood Tower protegge l'Iceblood Garrison da sud-est.$B$Bnon è controllata da nessuna delle due fazioni."
S["86ad876e"] = "Fammi sapere quando è il momento migliore per cavalcare. Devi essere i nostri occhi e le nostre orecchie al fronte."
S["86b00ecf"] = "Se mi dimostri di essere $Gun vero alleato:una vera alleata;, potrei pensare di addestrarti..."
S["86b3b548"] = "Bene, così dovrebbe andare. Su, torniamo al negozio a concludere i nostri affari!"
S["86bb7841"] = "Se nessuno ferma presto il culto Al'Aketh, finiremo tutti arruolati a forza fra quei fanatici. E io con la testa rasata NON starò bene."
S["86bc1c1d"] = "%s è indebolito!"
S["86c07394"] = "Faccio in modo che non ci manchino le provviste e che le poche risorse che abbiamo siano divise come si deve.$B$BSe fossimo un vero ordine, sarei una specie di quartiermastro. Ma per come siamo messi, faccio solo del mio meglio perché siamo almeno un po' equipaggiati contro i pericoli che abbiamo intorno."
S["86c21d7d"] = "Saluti, $C. Anche se il tempo e il bere mi hanno offuscato i sensi esterni, gli occhi interiori restano acuti."
S["86c25062"] = "Merok! Shai! Al mio fianco!"
S["86c31e43"] = "Non farmi perdere tempo."
S["86c4c24b"] = "Brzzzzt!$B$B$GBenvenuto:Benvenuta; nel Matrix Punchograph 3005 barra C, un terminale con livello di sicurezza chi.$B$BPer accedere alle sue funzioni ti serve una blue punch card.$B$B01010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000"
S["86d5ce4b"] = "Ha funzionato! Incredibile! A quanto pare non ho perso il tocco..."
S["86dc2e9e"] = "Nessuno può fermare Death's Head! Spazzeremo via questa terra e apriremo la strada all'unico vero padrone!"
S["86e07628"] = "Private Thorsen di ritorno dalla pattuglia. Niente di nuovo da segnalare, là fuori è piuttosto tranquillo..."
S["86e1231f"] = "Se hai intenzione di avventurarti nei Blackrock Depths, vieni a parlare con me. Potrei avere del lavoro per te."
S["86e53a7c"] = "Ora dobbiamo aspettare, $N. Non passerà molto prima che i naga capiscano cosa abbiamo fatto."
S["86efa0a8"] = "Ciuff! Oggi siamo caldissimi, ragazzi."
S["86efe487"] = "Ho sentito la storia di un pesce d'oro: se lo prendi, ti dà tre desideri!"
S["86f3198a"] = "La Tower Point East presidia il passo tra il Field of Strife e i territori dell'Orda a sud.$B$BÈ controllata dall'Alleanza. L'East Frostwolf Tower protegge la porta tra il Frostwolf Village e la Frostwolf Keep.$B$BÈ controllata dall'Alleanza."
S["86f79211"] = "Stoltamente hai cercato la tua stessa rovina. Sfacciatamente hai ignorato poteri che vanno oltre la tua comprensione. Hai combattuto duramente per invadere il regno del mietitore. Ora c'è una sola via d'uscita — percorrere il sentiero solitario dei dannati."
S["8701508e"] = "Ehi, ehi, ferma, ragazza Dadanga."
S["87020b44"] = "Ora che i calderoni sono violati, possiamo immettere il controagente nell'ambiente: così il flagello dovrebbe assaggiare la sua stessa medicina, per così dire!$B$BPer sapere quali reagenti usare nei calderoni, chiedi ad Apothecary Dithers. Io mi occupo di tutti i rapporti su come stiamo riuscendo, nel complesso, a rivolgere la piaga contro lo Scourge!"
S["8709c790"] = "Gli spiriti di questo luogo sono rivolti contro quelli della tua razza, $R. Forse, se conquisterai questa torre in carne e ossa, potrò aiutarti."
S["8709e5f9"] = "Addestro i cacciatori secondo gli usi e le tradizioni dei nostri antenati."
S["870dd7ef"] = "%s piagnucola."
S["87104316"] = "Ti insegnerò... presto. Prima, però, esigo una prova della tua lealtà."
S["8714c540"] = "Sì, $Gfiglio mio:figlia mia;? Cosa posso fare per te?"
S["87162ca7"] = "Seguimi."
S["8719d0ee"] = "Attenzione! Attenzione! Una minaccia si aggira nelle terre selvagge! Guardia Notturna, state all'erta!"
S["8726a8ed"] = "Se riuscissi a prendere un pesce grande quanto la tua bocca, non avremmo più fame."
S["8727a918"] = "Astor? Ci hai messo un dannato secolo ad arrivare, quindi non perdiamo altro tempo, d'accordo?"
S["8728a9c1"] = "Ehm, tu uccidi re, sì? Allora tu prendi suo posto. Così tu diventa nuovo capo! Lunga vita a re!"
S["872c7772"] = "$N, sei $Gpronto:pronta; per il compito supremo. Le rune infuocate incise sul pavimento di the molten core sono condotti che portano al reame del fuoco: per noi sono un affronto, e per i Firelords una fonte di potere. Vanno spente!$B$BPer spegnere una runa prendi una fiala di aqual quintessence e versala sulla runa: la sua fiamma si spegnerà, non servirà più a nulla e il nostro nemico ne uscirà indebolito!"
S["873a5503"] = "Ti interessa il cuoio, eh? Allora dovresti parlare con Simon Tanner, nell'Old Town: ha un negozio lì, si chiama Protective Hide."
S["873f03c2"] = "Finirà mai questo incubo?! Non riesco a svegliarmi!"
S["8742b86f"] = "Ora va', $N. Trova Volcor... e ricorda, le magie che ti proteggono svaniranno se interagisci con qualcuno, a parte parlare."
S["8755f320"] = "Chi l'ha detto che gli orchi non sono intelligenti? Per fare l'ingegnere ci vuole un sacco di cervello!"
S["8757d812"] = "Ci onorate con la vostra presenza, mio signore."
S["87597421"] = "Ishnu-alah, sorella. Rechi nuove da terre lontane? Il mio cuore brama notizie di Teldrassil."
S["87671ff3"] = "Sono là fuori! Di notte li sento ridere. Oh, la pagheranno! La... pagheranno... cara!!"
S["8772802f"] = "Oh, sono così felice che tu sia $Gtornato:tornata;, $N.$B$BOra lo spirito di mio fratello è stato liberato dalla corruzione, ma io scelgo di restare qui, nel mio lutto.$B$BGrazie infinite per il tuo aiuto, $N."
S["8774ad42"] = "Servitori, schiavi, soldati del gelido buio! Obbedite al richiamo di Kel'Thuzad!"
S["877a9b1d"] = "Dovresti andare a cercare Bronk allo Steelgrill's Depot. Se non sta armeggiando con qualche strano congegno, di solito è lì a chiacchierare con i piloti dei loro steam tanks."
S["877aae45"] = "L'Icewing Bunker è stato distrutto dall'Orda!"
S["877d8c61"] = "Comincia a fare freschino qua fuori. Mi sa che vado a scaldarmi davanti al fuoco e a farmi una pinta o dodici."
S["877f8e96"] = "L'aeronave per Zephras Isle è appena arrivata. Si prega di fare attenzione ai gradini durante l'imbarco!"
S["8785ecdc"] = "Molte delle cose che vedi in negozio sono opera mia. Che ne pensi? Pensaci bene prima di rispondere: potrebbe dipenderne la tua vita."
S["878b3d70"] = "Chiudi gli occhi. Dormi."
S["879274ab"] = "Ti seguirò fino all'accampamento. Se parli con il mio assistente, Hornizz, avrà il tuo compenso."
S["8797f612"] = "Sono $Grimasto:rimasta; qui abbastanza, $N. Sono $Gsicuro:sicura; che ci rivedremo. Buona fortuna!"
S["879e7d87"] = "Cammina con cautela, $Gamico:amica;: queste rovine brulicano di feccia non morta."
S["87a0a088"] = "In attesa di ordini!"
S["87bd1f2a"] = "Zamja può aiutarti, $R?"
S["87bded80"] = "Negli Eastern Kingdoms non sarà di certo, questo è sicuro.$B$BDev'essere da qualche parte su Kalimdor, ma abbastanza lontano dall'Orda e dalle altre razze. Un posto che la Frattura non ha toccato — e quindi lontano anche dalla civiltà degli elfi della Notte.$B$BDirei che sarà anche un posto protetto... una valle, magari, o un cratere. Non lo so. Ormai tiro solo a indovinare. Mi spiace non averti potuto aiutare di più."
S["87c527d7"] = "Ottimo lavoro, voi due. Ora andate a sedervi."
S["87c60616"] = "Ehilà Ehilà Ehilà! Se vuoi mettere alla prova quanto sai pescare, ho proprio il posto che fa per te! Questa domenica a Stranglethorn c'è un torneo di pesca!"
S["87df7361"] = "Che dolore delizioso."
S["87e6a2e2"] = "Non male. Vai a parlare con Snarl, si è appena trasferito a Orgrimmar per studiare con Saru. Cercalo nel quartiere dei guerrieri, vicino alla fucina di Saru. Ah, e ti metterà alla prova, quindi faresti meglio a essere pront$Go:a; quanto credi di esserlo."
S["87f93f45"] = "Vedo l'uscita! Presto, presto!"
S["87fb748c"] = "Il frammento dello scettro non c'è più! La vostra amata Kalimdor sarà presto una landa desolata. E io, naturalmente, trasformerò gli Eastern Kingdoms in un vuoto di cenere senza vita..."
S["87ff6339"] = "Ricorda che, per quanto questo luogo sia la nostra casa da millenni, qui saremo sempre in qualche modo degli estranei. Non siamo nel mondo terrestre che ha dato vita al nostro popolo, ma nel regno di Skywall, il piano elementale dell'aria.$B$BGiungemmo qui come ospiti di spiriti a cui, in epoche passate, scoprimmo di essere legati. Ora che noi Shen'dorei siamo rimasti senza la loro presenza — e forse — senza la loro protezione, chissà come ci vedranno gli altri abitanti di questo piano."
S["880512f4"] = "Quale messaggio?"
S["88080ef9"] = "%s si gratta la gola."
S["880cf62f"] = "La Somma Sacerdotessa non ha potuto allontanarsi da Darnassus. Quanto a Fandral, è di pessimo umore."
S["8813f982"] = "Capisci cosa intendo? Entra subito."
S["8817256b"] = "%s pianta il Moss-twined Heart..."
S["8821d4e3"] = "Da queste parti non ci sono molti posti dove pescare qualcosa. Paxton li conosce tutti, e probabilmente pure qualcuno di cui non ti parlerà. Perché non vai all'Iceflow Lake a sentire cosa ha da dirti."
S["8827f88c"] = "Dove dovrei cercare E'ko?"
S["8834752d"] = "Io... grazie, $C."
S["883fe301"] = "La Luce arde luminosa in te, Davil. Mi divertirò a spegnerla!"
S["8844e8c8"] = "Straordinario! Quindi la chiave è l'indurio!"
S["8849d18c"] = "Sono stato abbattuto da quell'idiota sconsiderato di Mulverick. Temo che, se non riesco a tornare alla base, sarà tutto perduto! Mulverick e la sua squadra di War Riders vanno fermati!"
S["885d70e7"] = "Uh... Papà...? Ci sei? Ho fame... posso avere un po' di stufato?"
S["885e52dc"] = "Nossignore."
S["886ee8d6"] = "Lo Stormpike Graveyard è stato conquistato dall'Alleanza!"
S["8877eb83"] = "Devi fare i punti più piccoli, $N: così ti scivoleranno fuori meno oggetti da faretre e borse per munizioni. E poi una tunica bitorzoluta non piace a nessuno."
S["887991ef"] = "Buona fortuna, $N!"
S["887b3b9d"] = "Och! Ora sì che si ragiona! Scommetto che Granis Swiftaxe potrebbe insegnarti un paio di cose su come si maneggia l'acciaio. Adesso lo trovi nella Thunderbrew Distillery, a Kharanos."
S["887b8271"] = "Ora tutti i preparativi sono completi, $C. Aspettiamo che l'ultimo carico di materiale venga mandato a Silithus, e dovrebbe arrivare tra pochi giorni. Poi, quando lì sarà tutto organizzato, qualcuno dovrà farsi avanti e suonare il gong sulla Scarab Dais con lo Scepter of the Shifting Sands. È allora che comincerà la Guerra di Ahn'Qiraj. Che la Madre Terra vegli allora su tutti noi."
S["88965214"] = "Vil wirsh ne lo."
S["88968b78"] = "Devo tornare al mio mezzo. Ricerca e distruzione imminente! Coprimi! Guardami le spalle! VAI VAI VAI!"
S["88a070ef"] = "La Coldtooth Mine si trova nel territorio dell'Orda, sulle montagne a nord del Frostwolf Graveyard.$B$BÈ controllata dai Kobolds."
S["88a0997c"] = "Sì, $N. Gli elementi si stanno risvegliando. Presto scateneremo la loro potenza sui nostri nemici. Barcolleranno sotto i colpi!"
S["88a247a7"] = "La gamba va molto meglio, il rimedio deve funzionare. Se permetti, devo andare a riferire ai miei superiori cos'è successo qui."
S["88b433fc"] = "Oh, è semplice! Si usa come qualsiasi altra cosa che puoi attivare. E non preoccuparti, alla miccia ci penso io. Una volta in aria ti sembrerà di \"galleggiare\", ma non durerà per sempre. Devi puntare a un bersaglio sul lago, laggiù in fondo. Bada a sganciare le \"ali\" al momento giusto per cominciare la discesa e atterrare in acqua, altrimenti, be', io non vendo assicurazioni sulla vita."
S["88bb0101"] = "%s emette un gemito di dolore."
S["88bce2b3"] = "Non così in fretta, signora... Le redini di un possente ariete da sella non le affido a chi non si è dimostrato alleato dei nani di Ironforge. Quando sarai $Griconosciuto:riconosciuta; come $Gosannato:osannata; da Ironforge, ti farò vedere volentieri le razze di arieti che ho in vendita."
S["88bd8c58"] = "$GIl dottore:La dottoressa; è in studio!"
S["88bef1de"] = "Morto? Sei $Gsvitato:svitata;, $N? Mi scusi, $Gsignorino:signorina; $N! Windsor non ci sarebbe mica morto, per cinquanta orchi. Com'è vero che il blood sausage di Thelsamar è il cibo più gustoso che il mondo conoscerà mai, lui era lì, in piedi, coperto di pezzi d'orco dalla testa ai piedi e inzuppato in circa diciotto strati del loro sangue, ma decisamente vivo... e davvero, davvero arrabbiato."
S["88c4b1ba"] = "L'attività dello Scourge nelle Plaguelands è decuplicata. Riceviamo rapporti di attacchi dello Scourge persino da Kalimdor! Come pensi che sia successo? Come hanno fatto quei miserabili non morti a fare ciò che si credeva impossibile? Non c'è più un posto sicuro?"
S["88c5925b"] = "Relara è salva, $N. Grazie."
S["88c5c620"] = "Ciao, questo è il mio testo."
S["88c69ff6"] = "Non c'è via d'uscita."
S["88c9cc68"] = "%s punzecchia il coniglio pauroso."
S["88cca56c"] = "Pare che abbiamo tutti i controfiletti di lupo che l'Orda vuole. Mi hanno detto di impacchettare quello che abbiamo qui e prepararlo per la spedizione alla Cenarion Hold a Silithus. Ma sembra che alcuni degli altri qui stiano ancora raccogliendo quello di cui si occupano. Vai a scocciare uno di loro."
S["88d00fe9"] = "Quei bastardi ci sono piombati addosso di notte, quando ci eravamo già fatti qualche bicchiere. Se no li avremmo sistemati, puoi contarci.$B$BOra sono morti tutti... tranne alcuni di noi."
S["88d360b0"] = "Progenie di Aegwynn, colui che sarebbe stato l'ultimo Guardiano di Tirisfal... Medivh."
S["88dba9ac"] = "%s sbadiglia."
S["88dc6df0"] = "Direi che avevate fame! Trok doveva darvi da mangiare prima... Cosa ha combinato per tutto questo tempo?"
S["88dde86b"] = "Da queste parti il maestro della pesca al persico è Clyde Kellen. Il suo posto preferito è il Brightwater Lake, appena a est di Brill."
S["88e1a1bf"] = "Ecco fatto! È tutto finito, $N."
S["88eb76b2"] = "Anche in tempo di pace la guerra non si ferma, e molti clan combattono ancora sotto lo stendardo del Capoguerra. Sei qui per unire il tuo clan a quelli che lottano per Orgrimmar?"
S["88f2c1db"] = "Non posso addestrarti."
S["88f3817e"] = "Non puoi nasconderti da me, $C. Sento l'odore della tua paura."
S["88f5325a"] = "Ti sei $Gperso:persa;?"
S["88f74938"] = "Arriva $N, occhi aperti, amici!"
S["88f7c365"] = "Nei secoli passati a pescare, Astaia ne ha tirati su di tesori strani. Perché non vai a trovarla sulla terrazza dei Mercanti e non te ne fai mostrare qualcuno."
S["88ff1118"] = "È un onore per me condividere con te il mio sapere, $N. Bada di farne buon uso."
S["88ffca3f"] = "Hai qualcosa di rotto? Slagtree te lo aggiusta!"
S["8901d29d"] = "Denni'ka può insegnarti a tenerti al caldo. Cercala alla Survival of the Fittest, una capanna sulla riva del lago accanto alla Spirit Lodge. Sali più in alto, a ovest della Valley of Strength."
S["89072f59"] = "Tu non sfida me, pivelli! Io re adesso, e io resta re PER SEMPRE!!!"
S["890c499c"] = "Spero che questa fronda attecchisca..."
S["890e1602"] = "Ti faccio a fette!"
S["8915dca8"] = "Ho sentito dire che a Stormwind c'è un nano che si è fatto un bel nome come cacciatore. Forse dovresti andare a vedere se può darti una mano."
S["8916833c"] = "Ti posso insegnare le tecniche di First Aid."
S["8919e175"] = "Era quello che volevo sapere. Ora devo solo trovare dove si parla della variazione del flusso."
S["891a39c1"] = "Ciao Jubjub. Mi sei mancato!"
S["89237ed6"] = "Conquista la base. Noi la assedieremo da terra."
S["8923a77e"] = "Anche tu sei qui per dimostrare quanto vali?"
S["892d02b6"] = "Mio signore. Da parte di Father Lankester."
S["892e0aae"] = "Ora devi andare a Darnassus e parlare con Me'lynn. Da qui in avanti ti guiderà lei."
S["8931cd4f"] = "Non posso insegnarti niente che tu non sappia già. Mio padre, però, ne sa molto più di me: entra e parla con lui. Buona fortuna!"
S["8932753f"] = "È questo il posto, $R: il Calderone! Segnalo su una mappa o fai qualcosa per non dimenticartelo. Se mai mi succedesse qualcosa, la mia squadra resterebbe bloccata in quella miniera per sempre."
S["8938381d"] = "Ehi, tu! $GAttento:Attenta;! I tuoi sacri doni shen'dorei non sono fatti per divertirti!"
S["893a0e37"] = "Sentire brutto vicino. Me sentire te brutto."
S["893cd6bf"] = "%s fugge dopo aver visto cadere Kel'Thuzad!"
S["893dfea6"] = "Sii $Gpronto:pronta;! Se devo firmare quei documenti, dovrai..."
S["894768ee"] = "Nel villaggio vive un saggio che si fa chiamare Narm Skychaser. Con lui puoi andare avanti nello studio del sentiero dello Sciamano."
S["89483382"] = "Ho visto contadini armati di bastone tenere testa a soldati addestrati. Non sottovalutare mai la forza e l'abilità che servono per usarne uno come si deve."
S["894e0a6d"] = "Il compito del guerriero è proteggere. Come difendiamo i compagni in battaglia, così dobbiamo difendere anche gli interessi dei Forsaken."
S["8951b09a"] = "%s emette una risata da rettile... almeno, credi che sia una risata."
S["8959ce8a"] = "E per le signore, cinghialetto arrosto. Buon appetito!"
S["895d2667"] = "Te lo porto subito, tesoro..."
S["895e4646"] = "Lo Scourge ha sfondato in tutte le ali! Che la luce sconfigga queste creature immonde! Combatteremo fino all'ultimo!"
S["89638f5e"] = "Il biglietto su questo regalo dice: \"Dai 10 anni in su.\""
S["897520c4"] = "I Windshapers e l'High Order stanno tramando qualcosa. Si dice che tutti e due vogliano rimettere in funzione i fendicielo per lasciare la Skywall. LASCIARE SKYWALL? Che assurdità. E poi per andare dove?"
S["89825eae"] = "Non c'è verso che tu esca di qui $Gvivo:viva;!"
S["898584f9"] = "La nonna diceva sempre che al mondo non c'era niente di più bello di una fetta di torta di ciliegie fresca, fatta in casa, calda e fragrante."
S["89874370"] = "La tua testa farà un bel trofeo, $N."
S["898743ec"] = "La tua testa sarà un bel trofeo, $R."
S["8989c2c0"] = "Sì, Clyde Kellen lo trovi sempre a pescare sulla riva del Brightwater Lake, appena a est di Brill. Ma quando sei là fuori, fa' attenzione agli psicopatici con la maschera. L'anno scorso ci è toccato chiudere il campo estivo dei ragazzi."
S["898afc44"] = "Devo solo controllare una cosa..."
S["89920aec"] = "Un alleato vicino resuscita %s!"
S["899495be"] = "Padrone, dove sono finiti tutti gli alberi?"
S["8998fa80"] = "Nessuno usa le armi con l'abilità di Ansekhwa. Si dice che lo guidino gli spiriti dei migliori guerrieri dei nostri onorati antenati. Cercalo sull'altura inferiore: ti insegnerà ciò che vuoi sapere."
S["899c1c4f"] = "Ben fatto. Ora hai ottenuto il più alto onore della sartoria. Va', e compi cose terribili con questo sapere!"
S["899fcf47"] = "Con piacere..."
S["89a1f8e3"] = "Qui si mette male!"
S["89a330a2"] = "Maestro, ci sono elfi della notte a Stormwind? Non ho mai visto un elfo della notte."
S["89a59ac2"] = "Vai a Orgrimmar, nella Valley of Honor. Vive lì con suo marito e le loro due figlie. Sono tutti fabbri di grande abilità, ma gli spiriti mi dicono che sarà lei a guidarti meglio."
S["89aa1894"] = "Servitori di Hakkar, ascoltate il vostro Dio. La santità di questo tempio è stata violata. Gli invasori calpestano il suolo sacro! L'Altare del Sangue va protetto. Uccideteli tutti!"
S["89b14ab0"] = "Vuoi fondare una gilda, eh? Buona fortuna, allora!$B$BVa' a parlare con Aldwin Laughlin allo Stormwind Vistor's Center. Sta nel Trade District, subito dopo l'ingresso dalla Valley of Heroes."
S["89b7b1c2"] = "Kahil, è stato un grande sforzo. Torna indietro e riposati. Ci penserà Narrisha a ripulire qui."
S["89b9ee4f"] = "Come te la passi, mon!"
S["89bd77b3"] = "MINACCIA RILEVATA. MODALITA' SOPPRESSIONE IN CORSO."
S["89c8ad15"] = "Ciao, $N! Quello che non vedi nel mio negozio, molto probabilmente te lo posso procurare!"
S["89caa1a5"] = "Mi occupo di procurare ai Paladins of Bandarion Keep armi e armature come si deve. Non è granché, ma è un lavoro onesto.$B$BSe ti serve dell'equipaggiamento, ho anche qualcosa da vendere."
S["89dcaadc"] = "Ishnu-alah, $Gviaggiatore:viaggiatrice;, e $Gbenvenuto:benvenuta; a Nighthaven.$B$BVuoi vedere la mia scelta di abiti raffinati?"
S["89ea8de7"] = "Ho sentito che ci sono pesci enormi che camminano sulla terra per cacciare, e mangiano le persone!"
S["89ef5ee0"] = "La Shattered Hand riporterà l'Orda all'antica gloria, e non si farà frenare dalla timidezza del Capoguerra."
S["89f14fd5"] = "Per cucire serve una mano ferma. E pazienza... soprattutto, pazienza."
S["89f3c873"] = "Ah. Il villaggio, lo vedo. Da qui dovrei essere al sicuro. Grazie."
S["89fa67a8"] = "Mamma? Posso accarezzare Fizzles?"
S["89fd550f"] = "Il cristallo della memoria è molto danneggiato. La registrazione potrebbe risultare incompleta, quindi dobbiamo ascoltare con attenzione."
S["8a0066ce"] = "C'è qualcuno? Tirion, vecchio amico mio, sei tu? Sei venuto a salvarci?"
S["8a095d5d"] = "Ci siamo, gente. Guardatevi le spalle..."
S["8a172a58"] = "Che non viva nessuno che porti l'immonda contaminazione della pestilenza!"
S["8a20afaa"] = "Che cosa vuoi, Komak?"
S["8a2aa4fe"] = "Non c'è leccornia migliore della Barbecued Buzzard Wing."
S["8a2c7986"] = "Cosa? $N, mi hai servito bene, ma..."
S["8a2d3d8b"] = "Siate testimoni del potere innegabile del vostro Capoguerra! Lasciatevi sollevare dal grido di battaglia dei vostri uccisori di draghi!"
S["8a390caf"] = "Throm'ka, $C. Il tempo per parlare è poco, il lavoro da fare è tanto."
S["8a395aef"] = "%s si frantuma e perde forza!"
S["8a3fdad1"] = "MORITE, MORTALI!"
S["8a48a2b3"] = "Senti, $Gfigliolo:figliola;, quella cosa che ci ha attaccati non era nessuna sacerdotessa, sappilo! Le brillavano gli occhi di qualcosa di malvagio e aveva la bava alla bocca, proprio così! È entrata, ha cacciato una specie di urlo folle che ci ha fatti scappare ognuno da una parte, e poi ha cominciato a scorticarci la mente uno alla volta. Mi sentivo parole oscure dentro la testa, e ogni tanto vedevo qualcuno degli altri svenire, qua e là. Una follia! Se non era per quella dannata scimmia, eravamo spacciati."
S["8a4bcb03"] = "Mi fa piacere che tu me lo chieda!$B$BLe professioni sono abilità legate all'artigianato, alla raccolta e, in generale, alla sopravvivenza. Ce ne sono tante fra cui scegliere, e ognuna ha i suoi vantaggi e le sue occasioni di guadagno. Che tu cerchi la ricchezza o un modo per riempire di oggetti utili il magazzino della tua gilda, o che ti piaccia semplicemente indossare un equipaggiamento fatto con le tue mani, c'è una professione che fa per te.$B$BLe ricette da artigiano si imparano dagli istruttori, come quelli che trovi qui intorno, e da tante altre fonti in tutta Azeroth. Una volta imparata una ricetta, puoi creare quell'oggetto quante volte vuoi, sempre che tu riesca a procurarti i materiali necessari."
S["8a4cc9b7"] = "Un altro giorno se n'è andato..."
S["8a4e9905"] = "Ben $Gtrovato:trovata;, $Gamico:amica;!"
S["8a501a40"] = "È meglio dei disegni nei tomi di storia."
S["8a50c69d"] = "L'Hammertoe, sei sveglio quanto eri testardo in vita, e pure da morto. Cosa mi puoi dire, vecchio amico?"
S["8a50d88d"] = "Molti sono entrati in questo santuario, pochi ne sono usciti."
S["8a5950b4"] = "State all'erta! Gli orchi e i loro alleati sono vicini!"
S["8a5e50b1"] = "Saluti, giovane $C. In vista della guerra contro i Silithid ad Ahn'Qiraj, l'Alleanza mi ha chiesto di guidare la raccolta del purple lotus. Di questo fiore conosco molti usi, perciò ho accettato di aiutarli a metterne insieme quanto serve. Finora ne abbiamo raccolto una parte."
S["8a6a0af2"] = "I nostri destini ci attendono..."
S["8a74441f"] = "Il Dio del Sangue, il Soulflayer, è stato sconfitto! Non siamo più in pericolo!"
S["8a7a6e38"] = "In ginocchio davanti a me, verme!"
S["8a7a9fcf"] = "Arriva il direttore delle poste!"
S["8a7ced8c"] = "Eh, bombe, noi piace bombe. Graham Van Talen fa vedere te come fare. Lui sta in anello esterno di Rogues' Quarter."
S["8a845fa7"] = "Noi conosce lei bene. Lei Mary Edras, in anello interno di Rogues' Quarter."
S["8a8ebb48"] = "I cimiteri dell'Alterac Valley sono il luogo dove le anime dei defunti trovano riposo e conforto. Se muori, il tuo spirito andrà alla deriva fino al cimitero più vicino controllato dalla nostra parte."
S["8a92b437"] = "$N! Aiuto!"
S["8a940499"] = "Chi controlla la Coldtooth Mine?"
S["8a95b977"] = "Va' nella Valley of Honor e parla con Saru Steelfury a The Burning Anvil. È in fondo al sentiero a destra della Red Canyon Mining."
S["8a97b776"] = "I mortali sono..."
S["8a995dda"] = "Dammi un hamburger oggi, e martedì te lo pago volentieri."
S["8aa04bee"] = "Per così tanto tempo sono stato perduto... La corruzione dell'Incubo mi aveva divorato... E ora voi... tutti voi... mi avete salvato. Mi avete liberato dalla sua morsa."
S["8aa17258"] = "Ti copro le spalle, Slidore, ma a dirla tutta, puzzi davvero. Fatti una doccia, amico."
S["8aa4961d"] = "Ebbene, ragazza, sembra che l'Alleanza abbia già raccolto tutto quello che ci serve per la nostra parte della guerra. So che i fabbri, gli ingegneri e tutti gli altri sono occupati con gli ultimi preparativi, e appena l'Orda avrà raccolto tutte le sue merci, sarà tutto mandato a Silithus per la guerra."
S["8aaaeae4"] = "Ci siamo..."
S["8aae6547"] = "Venite, venite tutti! Le merci di Antonio sono in vendita. Potrei non tornare per parecchio tempo, quindi venite, venite tutti."
S["8abb27a4"] = "Di tutti i luoghi meravigliosi di Darnassus, verso quale vorresti che ti indicassi la strada?"
S["8abc5c7a"] = "Immagino che potrebbe funzionare, se avessimo venti persone per lanciarlo."
S["8ac4fa04"] = "Non sono molti i cuochi che vengono qui a farsi addestrare, ma se sei $Gpronto:pronta;, credo di avere qualcosa da insegnarti."
S["8ac631db"] = "La vista mi si è oscurata, ma ci sono molti modi di vedere..."
S["8acae7d9"] = "Sono assolutamente $Gsicuro:sicura; di voler imparare la conciatura delle scaglie di drago."
S["8ad77024"] = "Dammi i perpetual purple firework!"
S["8ad88ee0"] = "Sì, signora, gli affari vanno a gonfie vele!"
S["8ae7c187"] = "Veggente del Cielo, devo ricordarti che è stato versato sangue dell'High Order? Vogliamo che i responsabili rispondano di questo crimine."
S["8af80260"] = "Ehi! Sarà meglio per te che tu non sia $Gandato:andata; troppo lontano!"
S["8b01c30d"] = "In Magic Quarter, Armand Cromwell tu non sbaglia. Lui sta su molo."
S["8b094e33"] = "Maledetta Brewers' League! Loro possono avere tutti gli ingredienti migliori, e noi siamo bloccati qui a racimolare grano e luppolo!$B$BGliela servirei proprio volentieri, una giustizia dal sapore amaro..."
S["8b09d146"] = "Mortale sconsiderato!"
S["8b0ef906"] = "Molto bene. Visto che non mi hai comprato tutta la merce, sono $Gcostretto:costretta; a guadagnarmi da vivere nella città dei tuoi nemici."
S["8b10fa42"] = "Grazie al Capoguerra resta un po' di speranza anche qui, fra le rovine della nostra vecchia prigione, e l'Orda risorge."
S["8b1998ba"] = "%s guarda il suo sangue che comincia ad agitarsi, mentre l'astuzia del raptor lo pervade."
S["8b1fe3b1"] = "Ancora un momento prima di proseguire."
S["8b21104d"] = "Ce l'avete fatta... avete ucciso Baron Rivendare! The Argent Dawn saprà delle vostre imprese valorose!"
S["8b341c8d"] = "Ce l'abbiamo fatta! Abbiamo vinto!"
S["8b3f1e9e"] = "Ottimo, cominciamo... ah! Ci sei cascat$Go:a;! Non penserai che sia così semplice. Dovrai dimostrare il tuo valore come tutti gli altri!"
S["8b43f969"] = "Sono Augustus! Lo vuoi? Ce l'ho! Lo vuoi vendere? Allora lo voglio io!"
S["8b45402c"] = "Impossibile!"
S["8b49400a"] = "La risata di %s echeggia nelle sale dell'Ala Nera."
S["8b4a9464"] = "Il mestiere dell'inventore fa per te, eh? Allora vorrai di sicuro andare da Springspindle Fizzlegear a Tinker Town.$B$BDai cancelli di Ironforge basta andare verso est, oppure seguire il rumore delle esplosioni."
S["8b4d746b"] = "Il regno di Dalaran si trova a ovest delle Alterac Mountains. Trova gli Hillsbrad Fields e viaggia a nord; vedrai senz'altro le guglie incombenti dei Kirin Tor."
S["8b4dc2bc"] = "Adesso rispondimi, $N:$BQuale creatura è diventata The Lich King, prima di spargere la pestilenza per tutta Lordaeron?"
S["8b5609d7"] = "<Da sotto le piastre metalliche dell'armatura del costrutto arriva un debole ronzio. Il vento che alimenta questa macchina c'è, ma è fiacco e si muove appena. Non serve saperne molto di costrutti dell'aria per capire che questa unità è malridotta.>"
S["8b574286"] = "Da casa sua!"
S["8b594efb"] = "Sei $Garrivato:arrivata; dalle Burning Steppes? Ce le hai, le mie uova di drago nero?"
S["8b5b070f"] = "Lunga è la via, e dura, la strada che hai percorso. Pochi raggiungono un tale rango tra le nostre file. Sei $Gun grande amico:una grande amica; dell'impero Zandalar, $N.$B$B$GLeggendario:Leggendaria; forse... Sì... Forse."
S["8b5cc7e1"] = "Per la gloria del signore del vento!"
S["8b6519bf"] = "Benvenuto, fratello mio. Se sei qui per addestrarti, lo farò con piacere.$B$BCome ci ha insegnato Cenarius, siamo i custodi dell'equilibrio, ora e per sempre. Non dimenticarlo mai."
S["8b684eb5"] = "Saluti, sono Elaadrin Evengale, attuale Magister Supremo dell'High Order. In cosa posso esserti utile?"
S["8b690d7a"] = "%s si inchina davanti a Krang Stonehoof"
S["8b6ade42"] = "Ti prometto un'eternità di turni a pulire lo sterco per quel fallimento!"
S["8b6b18ee"] = "Stolti, sapevo che giocando sulle deboli emozioni di mio fratello avrebbe mandato dei 'soccorritori'."
S["8b7e2115"] = "I Dark Irons credevano che queste tavolette fossero cifrate. Non è nessun codice: è la lingua dei draghi antichi."
S["8b7fdb57"] = "Se desideri tanto la via del Guerriero, devi cercare Krang Stonehoof. Lo troverai nell'angolo sud-est del villaggio, presso il suo cerchio di addestramento: spesso è lì che istruisce gli altri allievi."
S["8b834e4f"] = "Capo, io fa vedere quanto io intelligente! Adesso tu essere extra intelligente con potente magia mojo!$B$BUm... forse Slip'kik usare magia su $Gse stesso:se stessa;. Quello essere buona idea..."
S["8b852c23"] = "%s ti guarda, in attesa."
S["8ba0d3ed"] = "$GBenvenuto:Benvenuta; alla Great Forge, $Gragazzo:ragazza;. Fuori farà pure freddo, ma qua sotto la teniamo bella calda. Prendi un martello, batti su quell'incudine e fammi vedere che hai la stoffa per essere $Gun Fabbro:una Fabbra; della Great Forge!"
S["8bad4855"] = "Fai la faccia feroce! Sei Kolkar, quindi comportati come tale!"
S["8bb8cb8f"] = "Ce l'abbiamo fatta, siamo fuori dalla fortezza. Ormai siamo quasi liberi!"
S["8bbaec66"] = "Thorium Brotherhood o no, se uno di quei Dark Iron mi viene vicino, assaggerà il mio piccone sulla tempia! Allora, ragazzo, dove ti spedisco?"
S["8bc557d5"] = "$GBen trovato:Ben trovata;, $N. Dobbiamo essere brevi, c'è molto da fare."
S["8bc690d5"] = "Hai servito la nostra causa con grande lealtà, $N. Lascia che ti faccia dono di una fonte inesauribile della nostra quintessenza elementale."
S["8bd0bbf7"] = "Forte."
S["8bd110c4"] = "Devi imparare le basi. Trianna è qui vicino: parla con lei, poi torna da me."
S["8bd2745a"] = "%s sbriciola la pietra di luna in una tazza di tè."
S["8bd58d60"] = "La Tribù Stonesplinter segnerà la tua fine!"
S["8bd7ffe6"] = "Questo monumento è dedicato a tutti coloro che sono caduti in difesa di Stormwind. Il nostro popolo ha superato difficoltà incredibili per conservare le sue libertà e decidere da sé del proprio destino. Qui ricordiamo ogni sacrificio che i nostri cittadini hanno compiuto durante la prima guerra che ha martoriato la nostra gente."
S["8be1c201"] = "%s guarda $N e poi piange di gioia."
S["8bec5d9e"] = "%s tira un sospiro di sollievo."
S["8bed93e7"] = "Sì, ho controllato, mi manca il pezzo sinistro!"
S["8bee28be"] = "Ad Arathi Basin si combatte per le risorse. Legname, minerale, cibo... per condurre una buona guerra serve tutto questo.$B$BPrivare i nemici dei rifornimenti è come ucciderli sul campo di battaglia."
S["8bfd91c4"] = "La Water of the Seers è pronta da bere, $N."
S["8c058e08"] = "Non respirerai più!"
S["8c0c9205"] = "Mi rincresce, gentile signora, ma non posso aiutarti finché non avrai imparato di più sulla lavorazione del cuoio. Rivolgiti piuttosto a Faldron o a Darianna, qui: loro possono insegnarti l'abilità che ti serve."
S["8c0e3457"] = "Allora conviene che ti sieda, perché la storia sarà lunga.$B$BAppena siamo arrivati a Silithus, Mistress Mar'alith è stata la prima degli elfi della notte di Cenarion Hold a unirsi alla spedizione. Facevamo le solite cose, niente di straordinario: si formava un gruppo, ci si avventurava nei vari alveari e si cercavano manufatti perduti."
S["8c11747c"] = "Cosa? Perché?"
S["8c1477f7"] = "Spregevoli goblin... farebbero di tutto per una moneta d'oro."
S["8c2adf48"] = "La raccolta è finita, e la merce viene spedita a Silithus man mano che è pronta. Sembra che manchino pochi giorni prima che sia arrivata tutta. Dopo, ci servirà solo qualcuno che suoni quel gong e apra i cancelli di Ahn'Qiraj. Allora sì che comincerà il vero divertimento."
S["8c3e8d95"] = "Dove sei $Gdiretto:diretta;? Beh, se ci vuoi arrivare in fretta, sei nel posto giusto!"
S["8c47f0eb"] = "%s scruta i moli da un capo all'altro."
S["8c585e93"] = "Decenni fa — al tempo di guerre e conflitti ormai antichi — la nostra stirpe è stata spinta sull'orlo dell'estinzione. Molto abbiamo sopportato, $R.$B$BL'assalto della Burning Legion. L'Anima del Demone. Gli Aspetti divisi. L'ascesa di Deathwing. La nostra Regina, Alexstrasza, resa schiava dai Dragonmaw.$B$BMalgrado tutto, siamo stati la volontà incrollabile dei draghi — la forza indomita che ha combattuto per rappresentare in questo mondo la nostra esistenza ormai al tramonto."
S["8c5cf587"] = "Sì, qualcosa te lo insegno. Vediamo come te la cavi: magari mi sorprendi!"
S["8c631c9f"] = "Questo è il braciere, $N. Spegnilo. Vorsha è una bestia che non merita la lode di nessuno!"
S["8c691960"] = "Cerca di renderti utile, $R. TIRAMI FUORI DI QUI! La chiave ce l'ha l'Alto Interrogatore."
S["8c6aaa23"] = "Aiutaci, $Gstraniero:straniera;. <La reliquia si sbriciola in polvere. Ti riempie la mente la visione di otto nani Dark Iron intenti a compiere una sorta di rituale.>"
S["8c6c8873"] = "No! NO! Maledizione!"
S["8c7b348f"] = "%s, troppo ferito, rinuncia all'inseguimento."
S["8c7f62bd"] = "Sono $Gindegno:indegna; di questa conversazione, Maestro."
S["8c86dad0"] = "Ok, andiamo!"
S["8c8a4795"] = "Ottimo lavoro, $N. Troviamo l'uscita. Credo di sapere la strada. Seguimi!"
S["8c8feddf"] = "%s sussurra all'orecchio di $N."
S["8c90f690"] = "Lunga vita al potente Blackrock Clan!"
S["8c9661f6"] = "%s è stordito..."
S["8cb001c6"] = "Paval Reethe! Finalmente ti ho trovato. E adesso te la fai con gli ogre? Niente paura, anche ai disertori e ai traditori si concede un po' di pietà."
S["8cb23c85"] = "Ti sembro $Guno sciocco:una sciocca;, mortale? Perché solo uno sciocco resterebbe qui a combattere contro di te e tutti i tuoi alleati. Forse un'altra volta... Se mai troverai il coraggio di dare seguito alle tue provocazioni."
S["8cb44b37"] = "Grazie per avermi salvato! La voce della tua impresa non passerà inosservata."
S["8cbf5319"] = "Benvenuti a tutti alla Darkmoon Faire, l'evento più grande del mondo! Abbiamo di tutto... cibo delizioso, bevande forti, manufatti esotici, lettura del futuro, premi straordinari ed emozioni senza fine! Non dimenticate di consegnare i vostri Biglietti Premio della Darkmoon Faire a Gelvas Grimegate! Ne bastano cinque o più e siete sulla strada per i premi più meravigliosi di tutta Azeroth. Vincono tutti!"
S["8cc0fd97"] = "Una tartaruga senza guscio è senza casa o è nuda?"
S["8cc5534e"] = "Certo che no, $Gcaro ragazzo:cara ragazza;. Voi tipi da 'avventuriero' finite spesso vittime delle circostanze; in balia dei drammi politici che di solito si consumano fra cittadini e reali.$B$BPerciò ti consiglio di cercare qualcos'altro, e più precisamente: una nuova carriera.$B$BQuesto mondo di eroi ne ha abbastanza."
S["8cdd1b73"] = "%s salta nel pozzo lunare e va sott'acqua..."
S["8ce2a61f"] = "$N ha difeso il fabbro!"
S["8ce41d64"] = "I goblin vincono la gara di accelerazione! Andrà meglio la prossima volta, squadra degli gnomi."
S["8cfd0a4e"] = "So cosa stai pensando, ma non preoccuparti, teniamo separati gli ingredienti per la cucina e quelli per l'alchimia!$B$BCome posso aiutarti?"
S["8cfd7636"] = "Ormai hai superato le mie modeste capacità. Cerca l'elfa della notte Ainethil alla Craftsmen's Terrace of Darnassus: lei può insegnarti di più. Se solo potessi venire con te."
S["8d0885ce"] = "È stato Crest a mandarti?"
S["8d12cfb8"] = "Fila a Grom'Gol, $N!"
S["8d143d25"] = "Ancora? Fa' in fretta, Komak, ne ho fin sopra i capelli."
S["8d213178"] = "Allora, vediamo... Se ho ragione, allora... Mmm..."
S["8d25b369"] = "La banca e la casa d'aste sono sul lato ovest di Valanaar, vicino al molo delle aeronavi dei Windshapers."
S["8d25eb3c"] = "Ci sono diversi campi di battaglia fra cui scegliere. Da quale maestro di battaglia ti mando?"
S["8d2bb507"] = "Vuoi essere $Gaddestrato:addestrata; a usare un'arma, eh? Be', non startene lì a bocca aperta: parla, ragazzo!"
S["8d31fd3a"] = "Chi controlla la West Frostwolf Tower?"
S["8d33e6f5"] = "Ehi ragazzi, proviamo dall'altro lato."
S["8d398d16"] = "Ne ho piene le tasche de' tuoi piagnistei! Chiudi quell'acchiappamosche prima che te lo chiudo io!"
S["8d3fc1fd"] = "Da grande voglio fare il re di Stormwind!"
S["8d509939"] = "Ti insegnerò un'abilità di equitazione solo quando sarai $Gosannato:osannata; presso gli umani di Stormwind, $C."
S["8d517cc3"] = "È Dwukk. Lo trovi vicino alla forgia rovente, nell'angolo nord-ovest della città."
S["8d5a25de"] = "Benvenuto, fratello mio. Se cerchi addestramento, ti istruirò con piacere.$B$BPresto il richiamo di The Emerald Dream si impadronirà di te: cadrai in letargo per molti anni e camminerai tra le forme più pure. Sarà lì, in quel tempo, che riceverai il tuo addestramento definitivo."
S["8d5a9ef6"] = "Sulla tavoletta ci sono segni che mostrano antichi diagrammi e terribili parole di potere, ma non riesci a capire cosa significhino."
S["8d5ab35c"] = "Ah sì, ho sentito parlare dei Windshapers. Essere bello incontrarti, ora.$B$BSai, il mio popolo combatte gli elfi da migliaia di anni. Se tu essere feroce anche solo la metà dei tuoi cugini di Darnassus o di Quel'Thalas, i Darkspear sarebbero lieti di chiamarti $Gamico:amica;.$B$BIo augurare a te ogni bene nei tuoi viaggi, $C. Noi Darkspear sappiamo fin troppo bene cosa vuol dire non avere una casa, perciò spero che tu trovare ciò che serve al tuo popolo per salvare la vostra."
S["8d5d37a3"] = "Ah sì, $Gun altro:un'altra; che alimenterà i fuochi e forgerà le armi di guerra. Ma certo che ti insegnerò il mestiere."
S["8d60cd77"] = "A questo punto evocherò qualcuno che esamini il ciondolo e trovi uno scomparto nascosto..."
S["8d6c7a7a"] = "%s cade su un ginocchio. Sembra sfinito."
S["8d706725"] = "Si ricomincia da capo."
S["8d76b211"] = "Trovatemi qualcosa di buono, cani!"
S["8d83cf75"] = "Resta a terra, Miserabile!"
S["8d898b93"] = "Padrona!! Vogliono distruggere la tua opera!!"
S["8d8c462d"] = "Signora ricuce e fascia noi quando noi colpiti. Tu trova lei in anello interno di Rogues' Quarter."
S["8d8ed4d5"] = "Abbiamo un quarto della silitite necessaria! Continuate così!"
S["8d9c2202"] = "Questa spedizione è un terribile salasso per le scorte militari."
S["8d9d4c4e"] = "Saluti dal vento, $Gamico:amica;. Ho il permesso di offrire agli altri Skyborne un passaggio rapido fino alla città di Stormwind. Il portale è a tua disposizione quando preferisci."
S["8da20fa7"] = "Sciamani, mostratemi cosa sanno fare i vostri totem!"
S["8da73a0d"] = "%s inizia a brillare e a fumare!"
S["8dab8591"] = "$N ci ha portato da bere! Facciamo festa!"
S["8dad5cf5"] = "Sangue e anime per Hakkar! AHAHAHAH!"
S["8db5fdab"] = "Così dovrebbe funzionare."
S["8db8b863"] = "Ti ha mandato quaggiù da me la mia dolce ragazza Kali? È la pupilla dei miei occhi, lei."
S["8dbc0b4b"] = "%s unisce il runecloth, le erbe e l'acqua santa alla bardatura."
S["8dcbbc43"] = "%s comincia ad armeggiare con gli occhiali davanti alla pietra."
S["8dd16ad1"] = "Questo raggio di luce lunare porta a Stormwind. Quando sei $Gpronto:pronta;, usa l'invito."
S["8df34c90"] = "È vero, ho delle abilità da insegnare a chi ne è degno. E tu, lo sei?"
S["8df7989a"] = "Non dire a Tirth che sono ancora qui. Se scopre che non ho lasciato le Shimmering Flats, mi toccherà sbrigare le sue commissioni e lavare i suoi panni sporchi per sempre!"
S["8dfdee38"] = "Biglietti! Riscattate qui i vostri Biglietti Premio della Darkmoon Faire! Premi meravigliosi ed esotici vi aspettano!"
S["8e005805"] = "%s consegna gli occhialoni luminosi a Doctor Draxlegauge."
S["8e05e727"] = "Vuoi essere $Gaddestrato:addestrata; a usare un'arma, eh? Be', non startene lì a bocca aperta: parla, ragazza!"
S["8e0f74a5"] = "Oh, ciao, $C. Immagino che l'Alleanza mi abbia chiesto di venire qui per tenere il conto di tutta la carne cotta che la gente sta raccogliendo, vista la catastrofe che incombe ad Ahn'Qiraj. Uno spasso, non trovi?$B$BComunque, suppongo che tu voglia sapere quanta ne abbiamo. L'ultima volta che ho contato, rispetto al totale di roast raptor che serve eravamo a questo punto."
S["8e19bfbf"] = "I sacerdoti di Stormwind stanno nella Cathedral of Light, in Cathedral Square. È lì che troverai High Priestess Laurena."
S["8e1b098e"] = "Credo di aver abusato dell'ospitalità. Andiamocene."
S["8e224a68"] = "$GSissignore:Sissignora;! Mi è stato ordinato di riferire che l'Alleanza ha raccolto tutto il materiale bellico necessario. Mi è stato comunicato che stiamo solo aspettando che l'Orda finisca la sua parte, e poi tutto verrà spedito a Silithus. Grazie, $Gsignore:signora;!"
S["8e25b3c9"] = "Ancora qualche altro e le stalle traboccheranno di cavalcature. Lascialo a me, $Gsoldato:soldatessa;. Da qui in poi ci penso io."
S["8e2c7686"] = "Lo Scourge ha portato solo piccole forze contro ciascuna delle capitali di Azeroth, mentre le sue forze principali attaccano periodicamente queste terre:$B$BAzshara, le Blasted Lands, le Burning Steppes, il Tanaris Desert, le Eastern Plaguelands e Winterspring."
S["8e30b834"] = "Hai l'aria di un uomo in cerca di sapere. Forse sono gli insegnamenti della forgia e del martello che cerchi, e forse posso guidarti lungo quel sentiero. Ma solo dopo che avrai accettato gli spiriti e ascoltato il loro richiamo."
S["8e40707f"] = "Ti servon indicazioni, $Gragazzo:ragazza;?"
S["8e4f20e2"] = "Benvenuto, fratello mio. Se sei qui per addestrarti, ti istruirò con piacere.$B$BRiaffermare il proprio posto in quello che mi piace chiamare il Grande Equilibrio non fa mai male. Noi che di questo equilibrio siamo i custodi dobbiamo sforzarci di tenere sempre la mente lucida e il cuore forte, e l'addestramento ci aiuta a farlo."
S["8e52d58c"] = "Il Wickerman Festival ha inizio ora! Potere ai Forsaken!"
S["8e580c91"] = "$C, grazie agli sforzi di molti siamo riusciti a raccogliere tutte le bende di runecloth di cui l'Alleanza ritiene di aver bisogno per il conflitto imminente. Se fossi in te, chiederei ad alcuni degli altri qui presenti se hanno ancora degli incarichi di raccolta da portare a termine."
S["8e5e3235"] = "Non puoi nasconderti da me!"
S["8e5e5da0"] = "Tutto fatto!"
S["8e6330fb"] = "Un buon martello fra le mani fa sembrare il mondo più sicuro. Come se potessi affrontare anche il più potente dei nemici con un bel pezzo di metallo massiccio stretto nei pugni."
S["8e7300eb"] = "Era avvolto negli incubi, Malfurion. Cosa sta succedendo nel Sogno? Cosa può causare simili atrocità?"
S["8e762505"] = "Aiuuutooo... co... costoleee... rot... rotte."
S["8e7f73ef"] = "Quanto ci vorrà mai per raccogliere una manciata di erbacce?"
S["8e8d85e3"] = "La via del Druido è sorella di quella dello Sciamano, e Gennia Runetotem è intrisa di questo sapere. Cercala nella grande tenda sul lato est di Bloodhoof Village."
S["8e8e017d"] = "%s si infuria e attacca!"
S["8e93a14d"] = "Rimpiangerai il giorno in cui ti sei $Gmesso:messa; contro di me, $N."
S["8e9b0f97"] = "Da un po' di tempo spariscono dei libri. Il Custode del Sapere e i suoi assistenti sono in preda alla frenesia. Sospettano che dentro Eldre'Thalas stia succedendo qualcosa di losco."
S["8e9d040b"] = "Hm... Questa spia rossa che lampeggia non mi sembra un buon segno..."
S["8e9d6278"] = "Dove... Dove sono?"
S["8e9ee229"] = "Purificato dal dolore!"
S["8ea7695f"] = "$GUn altro appassionato:Un'altra appassionata;, eh? Be', aspetta e vedrai, faremo di te $Gun fanatico:una fanatica; della meccanica in un attimo!"
S["8ea8359e"] = "Ciao di nuovo, Antonio. Grazie ancora per il cappello per mia moglie. L'ha adorato."
S["8eaa4af0"] = "Morto? Sei $Gsuonato:suonata;, $N? Ma scusami tanto, $GSignor:Signora; $N! Per ammazzare Windsor non bastano mica cinquanta orchi qualunque. Com'è vero che il blood sausage di Thelsamar è il cibo più gustoso che il mondo conoscerà mai, eccolo lì, ritto: coperto da capo a piedi di pezzi d'orco, zuppo di circa diciotto strati del loro sangue, ma vivo di sicuro... e molto, molto arrabbiato."
S["8ebaca71"] = "Raggiungiamo gli altri, e teniamo d'occhio quei lupi là fuori..."
S["8ec1cf6f"] = "Portatene un altro; il tempo stringe."
S["8ed358ae"] = "Elder Graveborn passa le giornate dalle parti di Brill, nelle Tirisfal Glades."
S["8edf4c27"] = "Dopo tutti questi anni di lotte, adesso si innamorano tutti!"
S["8ee1ca16"] = "Sarai perdonato, Eranikus. Elune ti amerà sempre. Liberati dalle catene che ti comandano!"
S["8eea5ae0"] = "Uccidete $Gil:la; $Glurido:lurida; $R!"
S["8eeeb54c"] = "Non ti aspetterai che ti sveli tutti i miei segreti, vero?"
S["8f0f788a"] = "Il mio popolo non ti conosce. Un kodo è un possente destriero, frutto dell'amore e delle cure del mio popolo; non lo si dà agli stranieri. Finché gli anziani di Thunder Bluff non ti considereranno $Gun amico:un'amica;, non posso venderti un kodo."
S["8f133818"] = "Non c'è creatura nella foresta che possa sfuggire a Corand, tanto è abile a seguire le tracce. Faresti bene ad ascoltare i suoi insegnamenti, se vuoi avere anche solo la metà del suo successo.$B$BTi risparmierò la fatica di seguire le sue tracce e segnerò la sua posizione sulla tua mappa, lì nella Cenarion Enclave."
S["8f14a355"] = "Sento odore di $Gun:una; $R."
S["8f164f38"] = "Vuoi aiutare i Forsaken a combattere gli umani nell'Arathi Basin? Allora va' all'Hall of the Brave e parla con Deze Snowbane."
S["8f3856d3"] = "\"Un'abilità per chi desidera superare gli ostacoli.\" Credo che sia così che Faelyssa descrive le sue abilità.$B$BSe la pensi come lei, raggiungi la Cenarion Enclave nella parte settentrionale di Darnassus, dove tiene le sue lezioni."
S["8f3cd60d"] = "Non so come facciano... quelle cassette della posta saranno portali magici, o qualcosa del genere. Pensa che tutto il giorno vedo gente radunata attorno alla cassetta della posta vicino alla banca, che tira fuori spade, scudi e armature di ogni tipo da quella piccola scatola!"
S["8f41f5ec"] = "La maledizione è finita!"
S["8f442e93"] = "Grazie, $N. Il mio tormento è finito."
S["8f47786c"] = "Bene, bene. Continua così e questo ponte sarà finito in un attimo."
S["8f48610c"] = "La Coldtooth Mine si trova nel territorio dell'Orda, tra le montagne a nord del Frostwolf Graveyard.$B$BÈ controllata dall'Alleanza."
S["8f5256e8"] = "Questo cuoio blu dà nell'occhio, lo so. Ma vedi, qui in giro corrono un sacco di reclute zelanti, che cacciano e uccidono con più entusiasmo che saggezza, e qualche precauzione bisogna prenderla."
S["8f579cfe"] = "%s indica la brocca d'acqua appoggiata sul bordo del pozzo."
S["8f5e027d"] = "Sono risorto!"
S["8f6274e4"] = "Non vediamo di buon occhio i malfattori, $R."
S["8f6ef4f9"] = "Ripulire il mondo dalla feccia impura non è un lavoro facile, Nancy. Qualcuno deve pur farlo."
S["8f70c394"] = "Rin'ji è attaccato!"
S["8f7115d3"] = "Lo Scourge è su di noi! Scappate! Scappate per salvarvi!"
S["8f879c15"] = "Controlla quella cella, $N. Se c'è qualcuno vivo lì dentro, dobbiamo tirarlo fuori."
S["8f8a8c93"] = "Non si rendono conto di essere morti, $R. Sono condannati a rivivere l'ultimo ricordo che avevano, quello di prima che la città venisse divorata viva da dentro. Almeno, la maggior parte. Ad alcuni è andata peggio.$B$BPensavi che fosse stato lo Scourge? Lo Scourge allora non esisteva ancora, e se ci fosse stato avremmo almeno opposto una dannata resistenza.$B$BNo, a devastare la città è stata una pestilenza uscita da Scholomance. Orribile, straziante. Non si è salvato nessuno.$B$BOra lasciami al mio dolore."
S["8f8c65bb"] = "Aiuto! Ho una mano sola per difendermi."
S["8f8e62f6"] = "Da quanto ho capito, car$Go:a;, è stato raccolto tutto e il materiale finale viene preparato e spedito alla Cenarion Hold. L'ultimo carico dovrebbe arrivare in meno di un giorno. Una volta che il nostro equipaggiamento e le nostre forze saranno tutti lì, chi porta lo Scepter of the Shifting Sands potrà suonare il gong vicino ad Ahn'Qiraj per aprire le porte. Allora la guerra comincerà."
S["8f9d59ce"] = "Parlami di nuovo dei cimiteri..."
S["8f9ea105"] = "Adesso basta, bambini! Dico sul serio!"
S["8fa51da5"] = "A volte i nani si girano su se stessi e lasciano la schiena scoperta agli attacchi. Cogli l'occasione per colpire così..."
S["8fb9da9e"] = "Respingo quest'idea. Questo è ciò che siamo ora, e faremo vedere ai Forsaken che non siamo ciò che pensano. Possiamo essere di nuovo al servizio di Lordaeron."
S["8fbea441"] = "Dal campione di tossina che ci hai portato, pensiamo che ti serviranno: un arcane quickener, cinque somatic intensifiers e quattro pezzi di runecloth. Tieni con te il vitreous focuser e procurati gli intensificatori dai non morti, zombi o ghoul, qui nelle Plaguelands!$B$BQuando li avrai, dovresti riuscire a caricare l'agente neutralizzante in quel calderone."
S["8fc3a390"] = "Erbe... devi parlare con Jandi, nel suo arboreto a The Drag. Dietro l'Asoran's Market, in Valley of Wisdom, ci sono dei gradini di legno. Salili fino al livello superiore di The Drag e la troverai."
S["8fc5ff1f"] = "Non hai stomaco per il volo in grifone, eh. Beh, per tua fortuna abbiamo un'alternativa che ti lascia con i piedi per terra... più o meno. È il trasporta-persone gnomesco, il Deeprun Tram, e lo trovi comodamente in fondo al Dwarven District."
S["8fcc975e"] = "Dove andiamo?"
S["8fcd1a78"] = "Sparpagliatevi! Scoprite chi è stato. Lo licenzieranno di sicuro!"
S["8fd15d07"] = "C'è un Istruttore di Scuoiatura a Orgrimmar. Per arrivarci esci da Razor Hill e segui la strada verso nord. Una volta lì, chiedi indicazioni a un Orgrimmar Grunt."
S["8fd696af"] = "Colpite!"
S["8fd8e1a1"] = "Non ti biasimo se ti sei $Gdato:data; alla pesca. Alcuni dei posti migliori del Southern Kalimdor per pescare sono a Mulgore, e su all'altura, da Mountaintop Bait & Tackle, trovi tutta l'attrezzatura che ti serve per approfittarne.$B$BDi' a Kah Mistrunner che ti mando io!"
S["8fe4a625"] = "Ora dove ho messo quel rocchetto d'argento..."
S["8ff0429c"] = "Salute, $Gsoldato:soldatessa;. Vieni a dare una mano alla causa?"
S["8ff45545"] = "Ti va di fare un gioco, $Gpuzzone:puzzona;?"
S["8ff9e6c2"] = "Sì! Sì! È per mia volontà che la via per Zephras ti è stata aperta! Portami al cospetto del tuo Signore del Vento, perché sappia chi è stato l'araldo della sua gloria!"
S["9004a304"] = "Dove sono quei rinforzi da Stormwind? A est è stata segnalata una forte attività dei Roccianera."
S["90144b5f"] = "Ha! Eterna non-morte ai maledetti Agamand!"
S["901bc9b1"] = "Ah, la bellezza della Shadowglen non finisce mai di deliziarmi i sensi!"
S["901efe1f"] = "Finalmente, uno di voi è degno della mia conoscenza. Non temere, ho sondato i tuoi pensieri: non ti sarà fatto alcun male."
S["90269b0b"] = "Le pareti della sala tremano. Sta succedendo qualcosa..."
S["9036ae57"] = "Preparatevi!"
S["90421e70"] = "<Il raptor ti mostra i denti.>"
S["9043c0bb"] = "Il nostro Signore ci ordina di prepararci alla guerra!"
S["9043d251"] = "E così l'insieme di magie si propagherebbe in una reazione a catena di energie a carica positiva."
S["90685e9b"] = "Salute, $C. Sono Miranda Breechlock — una dei pochi intendenti autorizzati a gestire l'equipaggiamento e il materiale dell'Alba.$B$BMentre combatti il male per noi — e intanto ti guadagni il nostro rispetto e la nostra fiducia — il Duca Zverenhoff ti darà dei gettoni del valore. Servono a due cose: puoi usarli per salire nei nostri ranghi, oppure spenderli come moneta per comprare oggetti speciali.$B$BPiù crescerà la tua reputazione presso l'Alba, più oggetti troverai a disposizione."
S["9069af49"] = "%s sembra non accorgersi dei commenti intorno a sé."
S["9072a2f5"] = "L'Irondeep Mine è controllata dai Troggs."
S["907e6d47"] = "State all'erta, muli fannulloni!"
S["90953109"] = "Nella professione di Incantamento si vede il ciclo di distruzione e creazione che sta al centro della natura. Te la insegnerà Teg, presso i Dawnstrider Enchanters, sull'altura di mezzo."
S["909848b6"] = "Bevande gustose in vendita! Togliti la sete con le birre migliori della Darkmoon Faire!"
S["9099678e"] = "Qui a Dun Morogh un maestro dei grifoni non lo trovi mica dappertutto, $Gragazzo:ragazza;. Se ti serve un grifone per andare da qualche parte, ti tocca passare da Ironforge."
S["909dc0e1"] = "Credevi davvero di avere una possibilità?"
S["90a793c5"] = "Smettila di strapparle i capelli!"
S["90a81685"] = "Continuate a lavorare; non c'è tempo per fermarsi."
S["90b41365"] = "Brucia nel fuoco dei giusti!"
S["90ba49f4"] = "NO! Shhhh! Stai zitto e basta. Arriva il Goretooth!"
S["90bd227a"] = "Un altro sorso della vecchia acquavite e sarò pronto a parlare. Hic! Salute!"
S["90da079f"] = "Ehi, $Gcittadino:cittadina;! Hai l'aria di $Gun tipo tosto:una tipa tosta;. Noi guardie, qui fuori, siamo un po' a corto di uomini, e il tuo aiuto mi farebbe comodo..."
S["90ddf65c"] = "%s raccoglie i materiali e si mette al lavoro."
S["90e296f4"] = "Il titolo di questo libro è scritto a mano, con uno svolazzo: Diario di Maureen Dalson."
S["90e983a0"] = "No! Non puoi sconfiggermi!"
S["90f570e1"] = "Comandante, è giunto il momento che i cavalcalupi carichino le linee nemiche. Manda l'ordine."
S["910520b9"] = "Fatevi avanti e bagnatevi il becco."
S["91057038"] = "...in fretta. Con le nostre forze.....saranno esposti.....il mio rituale non deve...."
S["9106117f"] = "Dicono che Duriel sia un feroce elfo della notte. Sarà un bel combattimento!"
S["9107520d"] = "Ora taci e ricorda dove ti trovi, se non vuoi che informi Lord Fordring e i suoi cavalieri che non sei più qui in veste amichevole. Sono certo che proverebbe un gran piacere a occuparsi della tua 'espiazione'."
S["91118c81"] = "Sono $Glibero:libera;! Quel congegno non mi tormenterà mai più!"
S["911e64bc"] = "Gli umani hanno proprio bisogno di tutto il nostro aiuto nell'Arathi Basin. Devi parlare con Keras Wolfheart: lo trovi sulla Terrazza del Guerriero, pronto ad aiutarti."
S["91223370"] = "%s si infila su per il naso un pizzico di polvere dei sogni..."
S["912d68a8"] = "Ah, per curare i malanni non c'è niente di meglio di un sacerdote. Certo, anche una bella pinta abbondante ne guarisce parecchi, ma non credo che Braenna Flintcrag insegni a fare la birra. Mi sa che dovrai accontentarti di un po' di addestramento da sacerdote nell'Hall of Mysteries."
S["913472fc"] = "Al porto può lavorare chiunque, ma alla tua incolumità ci pensi tu."
S["9135b381"] = "Dev'essere il tuo giorno fortunato. Va bene, parlerò. Ma lasciatemi in pace. Senti, non mi crederai, ma è sta... oh, Luce, pare che la ragazza sapesse tirare..."
S["913cb1dd"] = "Va' a riferire che l'avamposto è preso. Noi restiamo qui."
S["913f3c41"] = "Salute, fratello... Vorrei parlarti un momento, se posso.$B$BPer fondare la nostra patria, noi tauren abbiamo sopportato molte prove e tribolazioni, e ora la stoffa ci manca gravemente. Se hai dei materiali in più, ti chiedo di donarli. Aiutandoci, ti guadagneresti di certo la gratitudine dei tauren di tutto il mondo!"
S["91465642"] = "Vieni, $N. Guarda cosa porta l'Incubo..."
S["914e37cb"] = "Io ti evoco, Sha'ni Proudtusk!"
S["915cf22b"] = "Grazie! Grazie, $Gsacerdote:sacerdotessa;. Ora posso affrontare quegli alberiani corrotti con il potere di Elune dalla mia parte!"
S["91648976"] = "Chi è il prossimo?"
S["91691eae"] = "Allora, se fossi Innkeeper Renee, dove sarei? Mmm? Oh, magari dentro la Gallows' End Tavern. Sì, è proprio lì, ne sono $Gsicuro:sicura;. Prova all'estremità sud-est di Brill... credi di riuscire a trovarla?"
S["917142f6"] = "Sia noto a tutti che $N, $C dell'Orda, si è $Gguadagnato:guadagnata; il rispetto eterno del Capoguerra. Ha condotto grandi trattative con Timbermaw Hold e compiuto per loro imprese valorose a nome nostro. È $Gandato:andata; ben oltre il proprio dovere. Tre urrà per $N, $Gun vero eroe:una vera eroina; dell'Orda!"
S["917bc059"] = "Mi dispiace, $Gragazzo:ragazza;, ma ti mancano proprio le basi per imparare quello che insegno io. Non preoccuparti, però: va' dal mio allievo Rotgath, ti darà una mano lui."
S["917dae6b"] = "Ritieniti $Gfortunato:fortunata;, mortale. Almeno il tuo cadavere è ancora abbastanza presentabile."
S["917f2b15"] = "Certamente, $N.$B$BPer accedere agli oggetti superiori, gli avventurieri che l'Alba considera amichevoli devono consegnare 60 insegne in tutto; per quelli ancora più potenti, 220.$B$BDevo ammettere che per gli avventurieri che non godono del favore dell'Alba il prezzo è piuttosto alto."
S["9185e1ed"] = "Vittoria! Per Agamaggan!"
S["91897539"] = "Desidero vedere i miei nemici, Ryson. Mostrameli."
S["9189f222"] = "Fermati qui per il prossimo spettacolo pirotecnico! Dalle 6PM in poi ce n'è uno a ogni ora in punto!"
S["9192f5e7"] = "Snarl mi dà del sempliciotto perché sono troppo lento. Io voglio solo fare il lavoro come si deve, e ci vuole tempo."
S["9193cd37"] = "Tutto fresco, dalla nostra fattoria alla tua tavola — questa è la genuina bontà di Smokywood Pastures!"
S["919d657d"] = "Questa luce lunare ti porterà a Ironforge. Ma chi mai vorrebbe andarsene da questa festa?"
S["91a66869"] = "Muori nel nome della Dama Oscura, $N."
S["91b6f494"] = "Devo dire che il miglior Clam Chowder dei South Seas lo trovi a Booty Bay. Oh, la cucina non ti interessa, eh? Be', allora lascia che sia io il primo a darti il benvenuto all'ormeggio del Maiden's Fancy, la migliore nave passeggeri che faccia la spola fra gli Eastern Kingdoms e Kalimdor. Dovrebbe tornare presto per un altro viaggio verso Ratchet: mettiti $Gcomodo:comoda; e aspettala."
S["91b7da22"] = "Perché sta succedendo? In parole povere, gli spiriti del vento sono semplicemente... scomparsi. Un giorno c'erano e il giorno dopo non più. Non so descrivere bene cosa abbiamo provato noi windshapers in quel momento. Era come se su tutti noi fosse calato un grande silenzio, e poi... un'assenza profonda.$B$BI miseri spettri che avrai incontrato là fuori sono solo ombre della gloria dei veri spiriti del vento. Privi di coscienza, senza meta, e ben lontani dagli spiriti gentili accanto ai quali abbiamo vissuto in armonia per migliaia di anni."
S["91bca9c5"] = "Finalmente! Qualcuno che mi tiri fuori da questa cella!$B$BHigh Executor Hadrec ci ha mandati a raccogliere informazioni sulla Rocca, così da poter preparare un piano per rovesciare Arugal una volta per tutte.$B$BMa il vecchio mago ha molti assi nella manica, e una protezione magica ci ha scoperti. Io sono stato gettato in questa prigione, e a Vincent è andata peggio.$B$BDevo tornare subito da Hadrec a fargli rapporto. Prima, però, ti scassino la serratura della porta del cortile. Forse potrai tentare la sorte contro i nemici nascosti al di là."
S["91bea76b"] = "Come dicevo, quel frammento di scettro l'ho tenuto per ben cinquecento anni e mi ha dato solo guai. Attirava attenzioni di ogni tipo — quelle sbagliate. Io voglio essere $Glasciato:lasciata; in pace a studiare, non fare da balia al lasciapassare per la gloria di qualche aspirante eroe. Così... l'ho dato ai pesci."
S["91c24ddd"] = "Salve, $C. Confido che tu porti buone notizie sui preparativi per la Guerra di Ahn'Qiraj. A me $Gstesso:stessa; è stata affidata la raccolta di tutto il rugged leather per l'Orda, un compito per cui mi sento $Gqualificato:qualificata; come nessun altro. Mai sottovalutare l'utilità di un coltello ben affilato.$B$BQuanto al rugged leather, ecco quanto ne abbiamo finora rispetto a quanto ne serve."
S["91e5687f"] = "Se cerchi un'attività che dia davvero soddisfazione, una vita dedicata all'incantamento fa per te!"
S["91e97901"] = "Affrontami, codardo. Affronta la fede e la forza che un tempo incarnavi."
S["91e97c1a"] = "Ne sono certo. Forse un giorno potresti portare un messaggio a un mio vecchio amico: ho sentito che vaga ancora per quei boschi.$B$B<Eitrigg china il capo per un momento, come se pregasse.>$B$BDunque, Rend, sì... Rend e suo fratello Maim governavano la Guglia ed erano sempre in lotta con i nani Dark Iron. Sono riusciti a cacciarli dalla parte alta della città, ma solo dopo che sono arrivati i draghi e Maim è morto."
S["91ecf7e0"] = "Salute, ragazza. Io sono Grelin Whitebeard. Mi trovo qui per valutare la minaccia dei troll, che nella Coldridge Valley si fanno sempre più numerosi. E cosa ho scoperto? C'è un po' da preoccuparsi..."
S["92044ae2"] = "$N, ce l'hai un'idea di cosa ci aspetta nell'Alterac Valley? Sei $Gpronto:pronta; a combattere contro il Frostwolf Clan?"
S["92124192"] = "Dun Baldar è il punto più forte del potere dell'Alleanza nell'Alterac Valley. Situata nelle zone settentrionali della valle, Dun Baldar è la base di partenza per tutte le avanzate verso sud.$B$BDun Baldar è stata rasa al suolo ed è in ricostruzione."
S["92208f8e"] = "In mezzo al mare di corruzione che è Felwood, questa pianta di fiorcanto spicca come uno scoglio. Il profumo intenso dei petali ti risolleva lo spirito e rafforza la determinazione."
S["9221cac5"] = "Quando aprirà, la Darkmoon Faire si troverà a Mulgore. Pianteremo le tende appena a sud-ovest di Thunder Bluff!"
S["9227442a"] = "Saluti, $C. Ho pietà della tua gente, perché i segreti della vera magia sono fuori dalla tua portata..."
S["92314177"] = "Hanno fatto irruzione nella Sala delle Luci! Dobbiamo fermare gli intrusi!"
S["9245e3a8"] = "E così i cavalieri si piantarono davanti all'Orda alla carica e tennero la posizione mentre mille orchi furiosi attraversavano la valle."
S["924a37e6"] = "Dobbiamo eliminare da Warsong Gulch gli elfi e la loro codarda Alleanza. Se hai la stoffa per aiutare l'Orda, va' all'Hall of the Brave, nella Valley of Honor, e parla con Brakgul Deathbringer."
S["924b12d0"] = "Da quando le ombre si sono prese Duskwood non riesco più a dormire. La brezza porta urla spettrali che mi tengono sveglia. Sembrano quasi agnelli che gridano, e non smettono mai."
S["924b4869"] = "Ce n'è una a Orgrimmar. Lassù un grunt ti darà le indicazioni giuste. Segui questa strada verso nord e non puoi sbagliarti."
S["924eecfc"] = "Sì, devo andare avanti."
S["9257651a"] = "Non ho altro da insegnarti: ormai le tue capacità superano le mie. Va' dalla tauren Una, nelle botteghe a nord-ovest dell'altopiano centrale di Thunder Bluff: lei offre un addestramento più avanzato."
S["92577f2c"] = "Grazie ancora, $N. Ora mi dirigerò verso la strada. Quando puoi, trova Terenthis e digli che siamo scappati."
S["925debb0"] = "La tua armatura fa paura. E tu, fai paura anche tu?"
S["925ee8c2"] = "Squadra rossa, vincitrice!"
S["9266f749"] = "La legione di Blackhand indosserà la vostra pelle come accessorio di moda!"
S["92690d9b"] = "A nord-est di questo accampamento c'è un potente infernal di nome Kroshius, ed è per lui che Niby è qui. Kroshius è un infernal superiore — un infernal che è durato più del previsto. Vedi, $Gpivello:pivella;, un infernal si schianta al suolo con grande intensità per servire il padrone, ma è un'intensità che svanisce in fretta. Quando le fiamme ardenti si spengono, l'infernal si sbriciola."
S["926cb64a"] = "<L'uomo sdraiato davanti a te si muove a disagio. Sta guarendo da ferite molto brutte.>"
S["92735fd0"] = "Perdonatemi."
S["92740a01"] = "È ora di incornare..."
S["927b15bd"] = "Spendere monete NON è il senso della Feast of Winter Veil!"
S["927d1d20"] = "$N! Come te la sei passata, $Gragazzo:ragazza;? Fammi vedere cos'hai imparato dall'ultima volta che ti ho visto, e vediamo se c'è qualcosa di nuovo che posso insegnarti."
S["9281591b"] = "Osi versare sangue su un terreno neutrale? FUORI! FUORI, HO DETTO!"
S["9283da5a"] = "Di solito gli umani sono vulnerabili sul fianco sinistro, tra la 4ª e la 5ª costola. Esercitiamoci a colpire questo punto, così..."
S["928f5b01"] = "Un momento... cos'è questo posto? Come può esistere un luogo simile nel regno del Signore del Vento?"
S["929232d6"] = "Dabu! Starò attenta, papà!"
S["929b3205"] = "GOR'TESH MORTO?!?!"
S["929d54ae"] = "Non ci faremo distogliere dalla nostra missione!"
S["92a052f6"] = "Prendete posto, gente! La corsa parte fra 2 minuti!"
S["92a12643"] = "Arriva subito!"
S["92aa09ab"] = "Vattene! Tengo consiglio con i Dreadlords, e quello di cui parliamo non ti riguarda!"
S["92aa27c0"] = "Salve! Vuoi accedere agli schemi di ingegneria goblin? Allora tieni pronta per la verifica la tessera di socio ingegnere goblin."
S["92b20187"] = "Ora che il generale Stormpike è stato sconfitto, possiamo distaccare qualche soldato a guardia del Winterax Hold. Ma dobbiamo restare sempre vigili, $C, perché l'Alleanza tornerà.$B$BQuando li trovi ad aggirarsi di nascosto, dagli un'altra lezione!"
S["92b571dd"] = "Sissignora!"
S["92ba5453"] = "Esatto. Mi hai ascoltato! Questo pesciolino è davvero una creatura terribile, e l'ho creata io. Quando mi rilasso mi piace pensare agli sfortunati pescatori che l'hanno incontrato e sono stati divorati in un boccone. Scommetto che sono rimasti piuttosto sorpresi!$B$B<Azuregos ride.>"
S["92bdd21e"] = "Se cerchi gli addestratori di druidi, il posto giusto è The Park. Di solito Theridan e Maldryn stanno vicino al pozzo lunare, al centro del quartiere."
S["92c2c041"] = "Guardie ai vostri posti! Devono avercela di nuovo col Magistrato. Va protetto! Potrebbero arrivare da qualsiasi direzione!"
S["92caeb72"] = "Wing Commander Vipore Senior, in decollo. Prega per una morte rapida, Frostwolf."
S["92ccb2cc"] = "Ah, vedo che ti affanni intorno a reliquie del passato."
S["92cd4bd7"] = "Se Reethe ha qualcosa a che fare con l'incendio della Shady Rest Inn, dovrai trovarlo e strappargli qualche risposta.$B$BHo mandato Ogron sulle sue tracce: era diretto a sud-est. Raggiungi Ogron e poi va' a cercare Reethe."
S["92d30ebb"] = "Raccontami ancora dell'Alterac Valley..."
S["92def08a"] = "Sono $Gpronto:pronta; a spaccare tutto, Vipore! Dammi un segnalatore."
S["92f53369"] = "Abbiamo un occhio solo e ci vediamo meglio di te! Banca in centro di Undercity!"
S["92f67ecc"] = "Abbiamo una discreta scorta di materiali per la ricostruzione, ma ce ne servono ancora molti prima che la Frostwolf Keep possa essere riparata del tutto."
S["92f8fc41"] = "<Sul cartellino del meccanostrider c'è scritto:$B$BIl Chromo-Classic Mechanostrider! Ora con stabilizzatori idraulici dell'equilibrio e silenziatori di scarico in mithril.>"
S["930a2e92"] = "Che la Luce sia con te, $N."
S["931226b0"] = "Allora, $Gragazzo:ragazza;, credi di avere la stoffa per difendere l'Alleanza dall'Orda nell'Alterac Valley? Molto bene: dovrai parlare con il nostro Glordrum Steelbeard, qui a Ironforge. Lo troverai nell'Hall of Arms, chino sul tavolo di guerra a studiare strategie."
S["93125b27"] = "Liladris mi sta aspettando a Maestra's Post. Ti seguo, $N. Dove ho messo quella borsa..."
S["931c0645"] = "Buongiorno a entrambi. Vorrei parlare con Ser Lescovar."
S["932057c2"] = "È fatta! Il Signore del Ghiaccio è arrivato! Inchinatevi alla potenza dell'Orda, sciocchi!"
S["932d1051"] = "Pronto quando vuoi, $C."
S["93361e71"] = "Ho perso il Brazier of Beckoning!"
S["933be83c"] = "Hai l'aria di chi cerca un passaggio per attraversare il Great Sea. Be', sei $Gcapitato:capitata; nel posto giusto: questo è l'ormeggio del Maiden's Fancy, la migliore nave passeggeri di queste acque. Appena arriva, sali a bordo, e prima ancora di accorgertene ti starai crogiolando al sole sulle spiagge sabbiose di Stranglethorn, o ti scolerai un bicchiere a Booty Bay."
S["9344b7f8"] = "Sia lodata Elune! Cerchi il nostro Warsong Gulch Battlemaster? Si chiama Aethalas e ti aspetta vicino agli istruttori dei guerrieri, pronta ad accoglierti."
S["934db5e5"] = "Lorthuna, sii ragionevole. Elaadrin mi ha mandato per discutere una via verso la pace e..."
S["93620f8c"] = "Quasi, ma non ci siamo ancora! Temo che prima dovrai parlare con mia sorella, Jemma. Quando ti avrà spiegato le basi, passa da me e ti farò vedere il bello!"
S["93698a71"] = "Zul'Farrak — Sergeant Bly — Saluto predefinito."
S["936eb433"] = "Ed è così che Lothar uccise trentasei orchi a mani nude!"
S["9372d266"] = "È affascinante... Ho sentito gli orchi dire che l'odore degli umani è nauseante, e ho sentito gli umani dire che quello degli orchi è ripugnante; eppure, per me, tutte le razze di queste terre emanano lo stesso odore: Il fetore stordente dell'avidità.$B$BDubiti di ciò che affermo? Non vedi che le cose che reggono la tua vita sono solo il residuo dell'avidità che detta ogni tua decisione?$B$BCosì sia. Come è stata l'avidità a portarmi via da casa, sarà l'avidità a riportarmici."
S["937738ee"] = "$GBenvenuto:Benvenuta; nella Tower of Azora, giovane $C. Sono Theocritus.$B$BHai qualche affare da sbrigare con me? O... forse sono io ad averne uno con te?"
S["9377789c"] = "Viviamo su un'isola volante, quindi potresti pensare che qui non ci sia bisogno di minatori come me. Eppure, dopo tante migliaia di anni, riusciamo ancora a tirarne fuori un sacco di cose interessanti.$B$BSembra quasi che una forza invisibile continui a creare ogni tanto nuovi giacimenti di minerali. Ma la magia funziona così, giusto?$B$BComunque, se ti serve un addestramento da $Gminatore:minatrice;, sono $Gil tuo:la tua; shen'dorei."
S["93781b0f"] = "Giovane $C."
S["93781fc7"] = "Rimandate soltanto l'inevitabile!"
S["9379c7a4"] = "Grazie per la motivazione."
S["9384cb7a"] = "Sembra proprio che sia passato un sacco di tempo dall'ultima volta che qualcuno mi ha dato il cambio."
S["93875b18"] = "%s crolla e comincia a fumare."
S["938989d9"] = "Se ho lettere indirizzate a $N? Ma no! Pare proprio che sia ora che tu muoia!"
S["9389e48d"] = "Mi spiace, ma non sono $Gdisposto:disposta; a vendere cavalli a chi non sia almeno in rapporti amichevoli con il Kingdom of Stormwind. Questi destrieri sono i migliori che troverai in giro, e di certo non vorremmo vederli nelle mani dei nostri nemici.$B$BNon sto dicendo che tu sia un nemico, sia chiaro... guadagnati la fiducia di Stormwind e poi potremo fare affari."
S["938c6ed0"] = "Vi spaccherò il cranio con tutta la potenza dei Roccianera."
S["93926606"] = "La guerra è arrivata, $N. È ora che ogni membro dell'Orda risponda alla chiamata e scenda in campo contro la codarda Alleanza."
S["939fc6b4"] = "Viviamo tempi volubili come il vento, $C. È importante ricordare ciò che in questo mondo è vero e duraturo, e custodirlo. Tutto il resto è uno spreco."
S["93a84b16"] = "Muahahahaha! Cos'è questo spettacolo penoso che vedo davanti a me? Be', cosa aspettate? Ho fame, e avete l'aria di un antipasto passabile!"
S["93af2dd4"] = "Le nostre unità campione sono equipaggiate! Attenta, alleanza!"
S["93b38307"] = "Non lascerai mai questo posto da vivo."
S["93b68354"] = "Va bene. È fatto!"
S["93b6c2c2"] = "Perché dovrei prendermi la briga di riparare la trappola? Perché non eliminare la guardia alla vecchia maniera?"
S["93b92788"] = "Sono $Gpronto:pronta;, signore! Basta un vostro cenno e farò piovere fuoco infernale sulla loro base!"
S["93b9ad80"] = "Se posso andare, vorrei vedere come sta Quinn..."
S["93baaca7"] = "Allora... hai fatto fuori il Re, eh? Lo sapevo che questi babbei ti avrebbero fatto $Gil nuovo re:la nuova regina;, lo sapevo e basta! È l'unica cosa che questi babbei capiscono: la forza.$B$BA quanto pare, più tirapiedi lasci in vita, più alto sarà il tuo tributo. Niente male: direi che è una sfida interessante. Se te ne vai, non aspettarti di restare $Gre:regina;. Di sicuro uno di questi zoticoni si farà avanti e prenderà il tuo posto.$B$BUn'ultima cosa... per caso non hai trovato la mia chiave, vero?"
S["93c004ed"] = "Tornate dal vostro Re dei Lich, creature immonde!"
S["93c975f0"] = "Bene, $N. Qualunque cosa sia, vai a farla vedere a Vosur, laggiù. Saprà rispondere a ogni tua domanda."
S["93ccb25d"] = "Guarda! Guarda! Ho preso qualcosa! Uffa... è solo un vecchio stivale puzzolente."
S["93d55fc5"] = "Le storie delle tue gesta si raccontano in tutto il Ravenholdt Manor, $GMaestro:Maestra; $N."
S["93d99b6e"] = "Aaahh... Molto bene. Ora smamma!"
S["93dd2558"] = "Hai un grande potenziale, ma prima devi raggiungere la comprensione: devi accettare gli spiriti e ascoltare il loro richiamo. Solo allora sarai pront$Go:a; per il cammino che devi seguire. Vai a parlare con Thrag, credo che forse potrete imparare molto l'uno dall'altro."
S["93e1dc7b"] = "%s ha sparato un buff!"
S["93e6ba92"] = "Chiunque sia diretto a Mulgore deve partire da qui."
S["93e81e51"] = "Il nemico è su di noi, state pronti!"
S["93fb522a"] = "Finalmente fuori da questa cella! Sono di nuovo libero!$B$BIl Kirin Tor mi ha mandato da Dalaran a indagare sui progressi di Arugal con i non morti, qui nella Silverpine Forest. Non immaginavamo che il mago avesse perso il senno.$B$BDevo riferire subito di questo disastro! Prima di andarmene, però, lascia che apra la serratura magica della porta del cortile.$B$BHai sconfitto Rethilgore: forse sopravvivrai a quello che si trova oltre..."
S["94044b60"] = "Saluti, $C. Mentre vai a est, verso The Bulwark, stai all'erta. Gli ultimi rapporti di sorveglianza dicono che da quelle parti lo Scourge è sempre più attivo, quindi procedi con cautela."
S["94045519"] = "Che le benedizioni della notte siano con te, $Gamico:amica;! Sono Illiyana Moonblaze, la fornitrice principale delle Silverwing Sentinels qui ad Ashenvale. Man mano che la tua reputazione presso le Sentinelle crescerà, ti metterò a disposizione una bella scelta di merci da usare dentro Warsong Gulch. E se hai bisogno di riparare l'equipaggiamento, posso occuparmene io."
S["9416953f"] = "Ti invidio, $N, davvero. Il tuo è un lavoro straordinario."
S["941b548a"] = "Pagherete per avermi costretto a farlo!"
S["941e2406"] = "Forse tu fai meglio di vecchio capo a riprendere prezioso cimelio Gordok da principe inquietante degli Highborne!"
S["942083f1"] = "Quando un fabbro lavora con la tua maestria, gli offro una scelta.$B$BNon sei $Gobbligato:obbligata; a scegliere, ma te lo consiglio — dopotutto, vuoi restare $Gun:una; neofita per sempre? Sono gli artigiani che forgiano armature e armi a rifornire i nostri eserciti, a vincere le nostre guerre e a guadagnarsi la gloria!$B$BTi avverto, $N. Una volta fatta la scelta e portati a termine i compiti richiesti — non si torna indietro. La via da percorrere è una sola."
S["943a737c"] = "Sei $Gcapitato:capitata; nel posto giusto, $Gragazzo:ragazza;! Da tutto 'l mondo la gente viene qui a imparare il mestiere del fabbro. Nel cuore della nostra bella città, proprio accanto a The Great Forge, troverai Bengus Deepforge che martella su un'incudine."
S["943d0e71"] = "$C, l'Orda ha raccolto tutto ciò che le serve per la Guerra di Ahn'Qiraj! Ora aspettiamo che quella misera Alleanza si metta al passo. Quando lo farà, cominceremo a trasportare tutto a Silithus. Una volta completati i preparativi laggiù, la guerra non dovrebbe tardare a cominciare!"
S["94464af5"] = "Oh, no! Gli sprite darters catturati non ce l'hanno fatta. Cosa facciamo adesso?"
S["9448f8fd"] = "Prendo qualsiasi cosa c'hai sul fuoco! E aggiungici una bottiglia per mandarla giù!"
S["944b6973"] = "L'oscurità che circonda le nostre terre ti metterà alla prova molte volte, $N. Ma perché tu sia sempre $Gpreparato:preparata;, ti affideremo spesso dei compiti, così da tenerti al massimo del tuo potere.$B$BVa' con la Luce, e resta $Gvirtuoso:virtuosa;."
S["94560caa"] = "Ne ho appena avuto notizia. Ecco a che punto sono le richieste di peacebloom, di firebloom e di erbe di purple lotus."
S["9458e547"] = "Bambini, se volete seguirmi, adesso andiamo a vedere il forte dove siede sul trono lo stesso Re Anduin Wrynn."
S["945d86ea"] = "Abbraccia la fine!"
S["9463215c"] = "Ehi, a proposito, devo far riparare gli stivali a razzo. Da' retta a me, $Gamico mio:amica mia;: stivali a razzo e grifoni non vanno d'accordo.$B$BOh, ma a te servono indicazioni... Vai pure al Dwarven District: Lilliam Sparkspindle lo trovi verso il fondo."
S["9466fa49"] = "$N, che piacere vedere sul campo veterani come te! Purtroppo devo dirti che al momento abbiamo scorte troppo scarse per lanciare grandi assalti di terra contro l'Orda.$B$BVa' a parlare con il nostro furiere: ha delle missioni di rifornimento da affidare."
S["946bafd3"] = "Elder Hammershout è dentro le mura di Stormwind."
S["9475534a"] = "Cosa? Mi stai dicendo che questo non riesci a ucciderlo da $Gsolo:sola;?"
S["94779003"] = "L'abomination ha travolto l'accampamento della Night Watch! Presto, dobbiamo intercettarlo prima che raggiunga il villaggio!"
S["947d7fd7"] = "Questa luce blu... È strana, $N. Cosa credi che significhi?"
S["9481cdd2"] = "Hai fatto molta strada, viandante. C'è ancora un compito per te..."
S["94902393"] = "Guardati intorno. Quanta bellezza c'è qui. Il vento in faccia, il cielo azzurro sopra la testa. È tutto così luminoso, così vivo, ma sì, è anche piuttosto cupo. Sembra una prigione. Una prigione da cui le guardie se ne sono andate tutte, e i prigionieri sono rimasti nelle celle a cavarsela da soli."
S["9492994a"] = "$GBenvenuto:Benvenuta; alle Fairweather Stables! Ti darei volentieri uno dei nostri splendidi galestriders, ma a quanto pare non hai ancora abbastanza esperienza per cavalcarne uno.$B$BA volte sono capricciosi e, se non li si gestisce nel modo giusto, tendono a disarcionare i cavalieri alle prime armi. Quando sarai $Gun avventuriero più navigato:un'avventuriera più navigata; e avrai abbastanza monete, sarò ben felice di addestrarti!"
S["949d5391"] = "Grazie per avermi liberato. Parla con mia sorella a Splintertree. Io... devo trovare un posto dove riposare..."
S["94aa6d9d"] = "PER KALIMDOR!"
S["94ae7d9e"] = "Non mi sento molto bene..."
S["94afa515"] = "Grazie a te, $Gragazzo:ragazza;. Grazie mille."
S["94b6b0dd"] = "Sento la contaminazione della corruzione su $Gquesto:questa; $N. Aiutami a distruggerla!"
S["94b77ac6"] = "Radnaal lo trovi fuori casa, sulla strada per Darnassus, che lavora al suo mestiere. Faresti bene a passare a vedere cosa può insegnarti."
S["94b80c3b"] = "Ma sei $Gtonto:tonta;? Venendo qui non hai visto le CREATURE SCHELETRICHE E OSSUTE che infestano la regione?$B$B<Rohan sospira.>$B$BSe sei un tipo da aria aperta, di creature scheletriche ne trovi dappertutto, nelle Western come nelle Eastern Plaguelands. Fidati, non puoi non vederle — e di certo loro non si lasceranno sfuggire te, se ne avranno l'occasione.$B$BSe invece sei un tipo da dungeon, per i bone fragments il posto giusto sono senza dubbio Stratholme e Scholomance."
S["94c53be3"] = "Ecco che passa $Gun eroe:un'eroina;."
S["94c8cd69"] = "Chi controlla il Dun Baldar North Bunker?"
S["94cd8c54"] = "%s afferra un pezzo e se lo mette in tasca..."
S["94d79651"] = "Bena lavora come un'ossessa. L'ho vista china su queste pozioni giorno e notte, spesso senza dormire né mangiare. Lo so, i nostri alleati non morti hanno bisogno di aiuto, ma comincio a temere che finirà per farsi del male."
S["94db8ad0"] = "Sono così $Gcontento:contenta; che tu me l'abbia chiesto. Troverai Sir Malory Wheeler nel Royal Quarter, al cospetto della nostra Dama Oscura."
S["94e167e1"] = "Fin qui può bastare! Ci rivediamo alla base!"
S["94f2138d"] = "Ho molto lavoro da sbrigare. Sei qui per darmi una mano con le ricerche?"
S["95184164"] = "Hai un certo talento nel forgiare armi, $Gragazzo:ragazza;, davvero notevole. Ora prendi un martello e vediamo se sai forgiare un'arma vera."
S["951a288e"] = "La Nogg's Machine Shop la trovi nella Valley of Honor, a nord-est della Red Canyon Mining."
S["9527a9ea"] = "Eccellente... sembra che gli insetti impiccioni siano arrivati giusto in tempo per sfamare la mia legione. Benvenuti, mortali!"
S["952a92ae"] = "Ho bisogno di un passaggio per andarmene da qui, Martin."
S["9531b2e5"] = "Dun Baldar ha preso una bella batosta nell'ultimo attacco dell'Orda! Ci servono altre provviste per ricostruire e fare le riparazioni!"
S["954257d1"] = "Questo andrà benissimo. Ora al lavoro!"
S["955d2e87"] = "Cerchi il frammento dello scettro affidato in custodia al Blue Flight?$B$B<Azuregos sembra sorridere.>"
S["955d9288"] = "Ho finito, $Gfratello:sorella;. Il resto fallo tu. Io me ne torno a riposa' sulla roccia."
S["955f3fb9"] = "Eraka no Kimbul$BDio delle Tigri, Signore delle Bestie, Re dei Gatti, la Rovina della Preda$B$BUeetay no Mueh'zala$BDio della Morte, Padre del Sonno, Figlio del Tempo, l'Amico della Notte."
S["9566b134"] = "Come va, $Gcompagno Dalaraniano:compagna Dalaraniana;? Che baccano oggi, eh?"
S["957061bd"] = "Sai preparare pozioni meglio di me. Cerca il non morto Doctor Herbert Halsey nell'Apothecarium of the Undercity. Lui può portare avanti il tuo addestramento, e vedrai con i tuoi occhi la sventura del suo popolo."
S["95822c00"] = "Bah, non è qui. Dove avrò messo l'ultima volta quel dannato coso?"
S["958f5338"] = "Buone lame, asce solide. Non ho più nulla da insegnarti sulla forgiatura delle armi, $N. Porta il tuo orgoglio e il tuo coraggio davanti a Kelgruk Bloodaxe, lui li forgerà nelle abilità che ti serviranno."
S["95960872"] = "Prova riuscita! $N, questo indurio è una roba straordinaria."
S["959ade6a"] = "Vedi di non combinare guai, $N!"
S["959cf138"] = "Sta' $Glontano:lontana; da Sumi e Tumi. Sono... già impegnate."
S["959e0c6b"] = "Se ti va di imparare a forgiarti armi e armature, ti aiuto volentieri."
S["95ab105c"] = "Siete venut$Go:a; a salvare questo mondo? A purificarlo?"
S["95b26dc8"] = "Ah... $Gun cliente:una cliente;! Parla pure con la mia più grande invenzione, il Vendor-Tron 1000. Ha tutto quello che ti serve... alcuni degli oggetti più rari che troverai mai sul mercato in tutto Kalimdor... per non parlare del fatto che è programmato per non contrattare, quindi il prezzo che vedi è il prezzo che paghi."
S["95b340c4"] = "Oh, ciao! Sei qui per imparare a maneggiare come si deve una nuova arma?"
S["95b5c313"] = "Hai fatto tanta strada con l'addestramento. Ormai solo un istruttore può portarti più avanti. Va' a cercare Buzzek Bracketswing a Gadgetzan!"
S["95b768f6"] = "$N, è giunto il momento dell'ultimo passo; dobbiamo attivare l'altare."
S["95bdc84e"] = "Fatti indietro, o ti taglio in due."
S["95c2bfcb"] = "Il Frostwolf Quartermaster si trova a sud-ovest di questo bunker. Entra nel bunker e poi esci sulla destra, vedrai il quartiermastro poco più avanti lungo il sentiero."
S["95c3bcdd"] = "Così tanti caduti. E molti altri ne dovremo perdere prima che questa battaglia finisca."
S["95c6644d"] = "Ah, ehm, sì, $Gsignore:signora;. Pare che abbiamo raccolto tutto il cuoio medio che l'Alleanza ritiene necessario per la guerra. Mi dicono però che qui potrebbero esserci altri che hanno ancora bisogno del tuo aiuto con le loro raccolte."
S["95c730b8"] = "Oggetti abbastanza potenti da aiutarti nel viaggio attraverso il Duskwood, la merce di Antonio Perelli ora è in vendita qui a Lakeshire."
S["95cde7ec"] = "Tresa Farmountain ha affrontato parecchio brutto tempo, ma grazie alle sue conoscenze di Sopravvivenza ne è uscita senza perdersi d'animo.$B$BSi trova in Military Ward, a sud dei cancelli di Ironforge, se vuoi parlarle."
S["95ce9dac"] = "Deathwing, un tempo conosciuto come Neltharion, era l'Aspetto che incarnava la forza del mondo — a concedergli un potere quasi illimitato su questo regno mortale era stato il Titano plasmatore noto come Khaz'goroth: Forgiatore del mondo.$B$BCon il tradimento e l'inganno, l'immondo ha convinto gli altri quattro Aspetti a infondere i loro poteri in un oggetto chiamato Anima del Demone, e così li ha indeboliti enormemente e ha seminato la divisione fra gli Aspetti, un tempo tanto grandi."
S["95d2ff77"] = "Salve, $N. Il mio nome è Chronormu, ma puoi chiamarmi Chromie: tanta confidenza non mi dispiace.$B$BOra — mi chiedi come facevo a sapere il tuo nome? Appartengo allo stormo bronzeo, eternamente in sintonia con il flusso e il riflusso del tempo. Si potrebbe dire che ci siamo già $Gincontrati:incontrate;, e allo stesso modo ci incontreremo ancora.$B$BSpero che non ti turbi l'aspetto che ho scelto; avrò pure il compito di fare da sentinella in luoghi di dolore, ma scelgo di non annegare nella tristezza di questo posto."
S["95f055c8"] = "Il nostro maestro di stalla, Ulbrek Firehand, lo trovi nell'Hall of Arms. Penserà lui a tenere i tuoi animali ben nutriti e curati come si deve."
S["95f22fca"] = "Sono qui per addestrarmi."
S["95f32dc4"] = "Dopo la ferocia che il mio popolo ha visto e subito, ti aspetti che accetti un altro fardello, drago? Devi essere pazzo."
S["95f6413a"] = "Andrà tutto bene, bambini. Ci penserà la Luce!"
S["95fed903"] = "$N ci sta venendo addosso!"
S["9602a5f1"] = "*Wrrr* *CLANK*$B$BIstruzioni ricevute: accettare pesci rari di alta qualità e dare in cambio preziosi accessori da pesca di Nat Pagle. Pesce richiesto.$B$B*THUMP* *Bzzz*"
S["9605bb04"] = "Saluti, $C. Ti prego, di' in breve in che modo il Kirin Tor può esserti utile."
S["9610cf4b"] = "Gol Me Thor."
S["961203a7"] = "Marketing — Saluto per il riscatto iCoke (S.H.E.)"
S["9618b383"] = "Non statemi addosso, gente!"
S["961a2c37"] = "Non ci sconfiggerete mai!"
S["9625ed55"] = "Basta! Mi sono stancato di queste distrazioni!"
S["9627ed5b"] = "Avanti, Crociati! Dobbiamo riprendere Corin's Crossing!"
S["962a5dee"] = "<High Inquisitor Fairbanks alza la tabarda e scopre diverse cicatrici raccapriccianti.>$B$BPerché io c'ero... Del Gran Signore ero il consigliere più fidato. Avrei dovuto capirlo... Me lo sentivo che qualcosa non andava, eppure l'ho lasciato accadere. Ci crederesti che le creature dello Scourge erano mille, se non di più?"
S["962bcc5b"] = "Ho passato tutta la vita a curare questi alberi. A potarli e a nutrirli... è giusto che mi abbiano seguito nella morte."
S["963b7af6"] = "Sì, correte! Così il sangue pompa più veloce!"
S["963d1e69"] = "L'ingresso delle Wailing Caverns si trova presso la Lushwater Oasis, a sud-ovest del Crossroads, nelle Barrens."
S["96433d80"] = "Chi è il prevedibile, bestia? Credevi davvero che ti avremmo evocato proprio sopra Malfurion? La tua redenzione è arrivata, Eranikus. Sarai purificato da questa follia, da questa corruzione."
S["9643ce4b"] = "Serviamo Thrall con grande orgoglio. Andremo lontano quanto serve per sconfiggere il nemico."
S["96462e00"] = "Evviva! Finalmente usciamo di qui. Però non sarà una passeggiata. Tieni gli occhi bene aperti."
S["9646e85e"] = "$GStupido:Stupida; $R! Il Blackrock Clan danzerà sulla tua tomba!"
S["964ba037"] = "%s è $Ginfuriato:infuriata;!"
S["964d78a1"] = "Dov'è l'assistente di Tirth?"
S["964d86b7"] = "Finalmente sono libero! Torno presto a casa, mia cara!"
S["9650bcb4"] = "E per i nostri dei?"
S["9651affa"] = "Ahhhhh!!!"
S["96543c6b"] = "Preparatevi! Evocare un essere così potente dà di rado buoni risultati."
S["965570ff"] = "Avanza con cautela, mortale. Dove cammini adesso, esseri più potenti hanno trovato la fine."
S["9658a367"] = "$N! Sei $Gtornato:tornata; solo per parlare con me? Che gentile! E con quella tenuta fai pure un figurone!$B$BNon sai che piacere mi fa vederti. Quassù ci si può sentire parecchio soli, visto che quasi nessuno di questi zoticoni riesce a vedermi. Per tutti noi hai fatto una gran cosa, e non lo dimenticherò mai!$B$BGrazie di essere $Gpassato:passata; a salutare, e fatti vedere più spesso."
S["965da1e2"] = "Nostri occhi dice che tu sembri $Gperso:persa;."
S["966822aa"] = "Va' all'Hunter's Hall, nella Valley of Honor, a ovest del Coliseum, e lì parla con Ormak Grimshot."
S["966f2ed8"] = "Non tutto è perduto! Combattete queste bestie senza paura. Le vostre ferite io guarirò, le ossa io risanerò. Siate rinnovati, eroi!"
S["9671f032"] = "Vuoi abbassare le nostre difese globali per far contento un magistrato paranoico e un accampamento di gentaglia che con ogni probabilità si è preso un colpo di calore."
S["9689c86c"] = "Tu non sei $Gun guerriero:una guerriera;... Ma col mio programma d'addestramento non dureresti neanche un giorno!$B$BUna $C che si crede una guerriera. Ah!"
S["968f3753"] = "MARTELFATO, GUIDA LA MIA MANO!"
S["96a26ac4"] = "Salute, $C. Le strade della nostra bella foresta non sono del tutto prive di pericoli. Cammina con cautela."
S["96a3bea3"] = "Mettiti un po' di pane in pancia."
S["96a48fc0"] = "Non lasciatevi attirare nella trappola dei mortali. Immergetevi nel mio potere! Rinnovatevi e distruggete gli eretici!"
S["96a6e54e"] = "Ci dev'essere un posto su Azeroth dove trovare melme non corrotte dallo Scourge o da qualsiasi altra cosa. Ma dove?!"
S["96b71f3d"] = "Amici tuoi?"
S["96b888dc"] = "Salve, $Gpiccolo:piccola;. Hai affari da sbrigare con i Signori dell'Acqua?"
S["96b9aeb1"] = "Fu quel giorno che i silvagufi ci furono donati. Guardiani feroci: la dea affidò ai silvagufi la protezione di tutti i suoi luoghi sacri."
S["96c6389b"] = "Da Curls and Furls, qui nel distretto commerciale, trovi le forbici più affilate e le mani più delicate. Se hai un po' di tempo libero e ti va di darti una spuntatina, fai un salto."
S["96c88e26"] = "TRAFIGGETELI, SOLDATI!"
S["96d409d0"] = "Mettiamoci al lavoro, $N!"
S["96e7d3b3"] = "%s scuote la testa, deluso."
S["96ec6caf"] = "$N, ho l'informazione che cerchi..."
S["96ecd898"] = "Tu cerchi quale istruttore?"
S["97023c7f"] = "Tiene del vischio sopra la testa"
S["970e6c2d"] = "Saluti, $C. Cosa può fare oggi per te questo umile servitore della Feathermoon Stronghold?"
S["970ec36a"] = "Sì, e anche voi, Arcimago Runeweaver. L'High Order è ansioso di saperne di più sul Kirin Tor."
S["971513fe"] = "Successo! Urrà! La fonte d'energia ha ripristinato la collana!"
S["9717a098"] = "Lo Skycutter diretto a Mulgore è arrivato! Tutti a bordo per Mulgore!"
S["97225b36"] = "Metti la testa di Rend sul palo."
S["97225d84"] = "Portare questi barili fino al sito di scavo è un lavoro duro, ma in tanti contano su di noi per far arrivare là la polvere esplosiva.$B$BContro i Dark Irons dobbiamo fare il possibile!"
S["972bc877"] = "Lo senti, $Gstraniero:straniera;? Il ronzio si fa più forte di giorno in giorno. Dev'essere colpa di questi cristalli se gli insetti impazziscono."
S["972bf377"] = "Evoca la Torch of Retribution, Kalaran."
S["972cd83f"] = "La Mischia è finita!"
S["973a8bf5"] = "Quest'orso si aggira lungo un percorso vicino al Talondeep Path, proprio a ovest del Mystral Lake e del Silverwind Refuge, l'avamposto dell'Alleanza. Delle tre creature che affronterai nella Caccia di Ashenvale è la più facile, ma non va presa alla leggera. È una minaccia costante per chi viaggia tra Ashenvale e le Stonetalon Mountains."
S["973e204b"] = "La terra, l'acqua e il cielo sono una cosa sola. Se li vedi separati, sono i tuoi occhi a ingannarti. La Madre Terra è tutto questo, e altro ancora."
S["9743fd66"] = "Vaelastrasz, no!!!"
S["974afe59"] = "Non che io sia sicuro che si possa mai avere abbastanza stranglekelp, nemmeno in un fantastiliardo di anni, con tutto il gelato che serve, ma pare che ne abbiamo abbastanza. O almeno così mi dicono. Sembra che ad alcuni degli altri qui serva aiuto con quello che stanno raccogliendo. Comprensibile, a dire il vero, se pensi che la loro raccolta non potrà mai essere divertente quanto raccogliere lo stranglekelp."
S["9755c214"] = "È molto gentile da parte tua chiedere, ma pare che abbiamo raccolto tutte le bende di seta che ci serviranno. Però potresti chiedere in giro e vedere se qualcun altro ha bisogno di aiuto con le sue raccolte."
S["975656c7"] = "I cadaveri me li portano, e io li butto nella fossa."
S["975fefef"] = "Mi serve aiuto per recuperare un pezzo delle mie Vesti del Demoniaco, Al'tabim."
S["9760fa64"] = "Chi osa disturbare il mio riposo eterno? Le vostre morti saranno lente e dolorose!"
S["976e3bb4"] = "Desidero combattere!"
S["9774d3ab"] = "Ti aiuterò. Dammi le istruzioni."
S["97758e83"] = "Non sarai qui per parlare della mia adorabile Kali, immagino. E va bene: pozioni, allora. Nessuno ti ha mai detto che hai un chiodo fisso?"
S["97772013"] = "Falthir, mi serve aiuto per recuperare un pezzo della mia Tenuta del Folle."
S["9779c774"] = "Avete commesso un errore terribile e costoso. Non è la mia ora, mortali."
S["977d6225"] = "Se vuoi, risali quel sentiero fino a Bandarion Keep. Lì sono di stanza altri come me."
S["97822251"] = "Non ci credo che papà non mi lascia tenere tua sorella."
S["978f635c"] = "No! Stai lontano da me! Aiuto!!"
S["97941e2f"] = "Devo fare molta attenzione con questo... Molto delicato."
S["979cd20d"] = "Bene, allora cominciamo. Più restiamo qui, più danni i non morti potrebbero fare laggiù a Hillsbrad."
S["979f3c5c"] = "Come faccio a combinare qualcosa con lo Scourge che scorrazza da queste parti?!"
S["97a29d64"] = "Gli affari devono andare bene giù al mercato. Gli porto subito altra merce!"
S["97a9cbc2"] = "Noi volere tanti animali. Anya Maulray aiutare te curare loro. Tu trovare lei a locanda, anello superiore di Trade Quarter."
S["97aa4a20"] = "$N conquista la segheria! Se nessuno la contesta, l'Orda ne prenderà il controllo tra 1 minuto!"
S["97ac791f"] = "Salve, giovane Signora. Sono Eva Sarkhoff, e questo è mio marito, Lucien. Piacere di conoscerti."
S["97bcfe99"] = "I vostri dischi sono pronti! Attivate di nuovo i Dischi di Norgannon per riprenderli!"
S["97bf9c91"] = "Attento a te. L'High Order non tollererà ostilità nella nostra loggia."
S["97c00c8c"] = "Era un'impresa troppo grande per me!"
S["97c2380e"] = "Usiamo gli archi da prima ancora dei tempi di mio padre. Sono solidi e sicuri e abbattono in fretta i nostri nemici. Non vedo motivo di usare i fucili che piacciono tanto ai goblin e ai tauren."
S["97caa1c8"] = "La tua stessa forza mi nutre, $N!"
S["97caee49"] = "Ti ringrazio, Ewök. E mio fratello ti ringrazia."
S["97cd33ce"] = "Non posso insegnarti la lavorazione del cuoio a scaglie di drago, $N. Devi andare a Tanaris e trovare la casa di Narain Soothfancy. Una volta lì, consulta il libro \"Divinazione per Negati\"."
S["97ceb6be"] = "Salute, $C. Non ho molto tempo per chiacchierare — mi sono accampata a Chillwind giusto per riposarmi un po' prima di partire per Hearthglen. Ho sentito dire che, prima di impazzire, la Scarlet Crusade aveva al suo servizio un mago che cercava di creare archi e fucili potenti per i soldati. Se ci sia riuscito o no, non lo so... la Crociata l'ha ucciso prima che venisse fuori anche uno solo dei suoi lavori finiti. Forse l'hanno fatto per tenere il segreto... o forse diffidano dell'arcano fino a questo punto."
S["97d109bb"] = "Certo che do lezioni ad altri Incantatori, purché tu sia $Gpronto:pronta;."
S["97d33897"] = "Combattete! Combattete per Darrowshire!"
S["97da25e6"] = "Oh, sono così stanco..."
S["97de5337"] = "L'Addestratore di Cacciatori si chiama Thotar. Cercalo dentro la tana, nell'angolo sud-ovest di Razor Hill."
S["97e18a66"] = "Io non dà nessun problema a te, capo."
S["97eba61b"] = "Speriamo bene..."
S["97ebf20a"] = "Cane! Ora intrappolerò la tua anima in un frammento e ti darò al mio imp come giocattolo!"
S["97f287ca"] = "Puoi lasciarmi qui — voglio restare $Gsolo:sola; nei miei ultimi istanti."
S["9806124c"] = "%s emette un potente ululato."
S["98098f47"] = "Ah, non c'è niente come volare in groppa a un grifone, eh? Gli elfi della notte se li tengano pure, i loro ippogrifi: a me date un grifone e il vento nei capelli!$B$BBene, non ti trattengo oltre: va' da Gryth Thurden, sul lato est di The Great Forge, e ti farà partire lui."
S["98127904"] = "La magia sciamanica che conosciamo è notevolmente diminuita da quando gli spiriti sono svaniti, ma siamo risoluti nella nostra missione di riportarli di nuovo a casa."
S["9813c440"] = "Lo Staghelm e i suoi eserciti erano chiaramente sopraffatti dal flusso infinito di truppe di Rajaxx che si riversava su Silithus. Sembra però che lo Staghelm fosse più di un semplice fastidio per i Qiraji. Sotto lo Staghelm, tutti gli eserciti degli elfi della notte si erano uniti per difendere Kalimdor, rallentando molto le forze Qiraji."
S["9815f43a"] = "$C, ti unirai a noi nella battaglia di Arathi Basin?"
S["98189235"] = "Che sia The Razza quello laggiù in The Maul? Sarà emozionante!"
S["981bfad2"] = "Chi controlla lo Stonehearth Bunker?"
S["981f90a1"] = "Ho aspettato abbastanza. Ora affronterete il falciatore di anime."
S["9822f456"] = "%s comincia a salmodiare mentre mescola le pietre del pozzo e l'ambercorn davanti al Tribal Fire."
S["982f014e"] = "C'è lo Scourge fuori dal Trade Quarter!"
S["98413b7b"] = "In questo luogo dimora un orrore indicibile, mortale. C'Thun e i suoi adoratori non sono soltanto un affronto alla natura: la loro esistenza preannuncia la distruzione di Azeroth così come la conosciamo.$B$BMille anni fa Merithra si sacrificò insieme a Caelestrasz e ad Arygos, perché anche loro lo sapevano. Siamo qui per mantenere il giuramento di tornare a prenderli, ma anche perché C'Thun va fermato!"
S["98470a80"] = "Sono $Guno:una; dei Sette, ed è nostra condanna montare la guardia. Per sempre."
S["984d7b7b"] = "State in guardia! Si parla di un verme gigantesco vicino a Hive'Zora!"
S["984d8d0e"] = "A quanto pare, $Gcaro:cara;, l'Alleanza è riuscita a raccogliere tutto il necessario per lo sforzo bellico. Ora aspettiamo solo che quelle povere creature dell'Orda finiscano la loro parte."
S["984fcd7c"] = "È vero che i paladini si addestrano qui?"
S["98502834"] = "Certo che posso mostrarti dov'è Myolor. Proprio lì, vicino all'incudine della Great Forge: è lì che lavora. Ascolta bene le sue parole, $Gragazzo:ragazza;: Myolor è tra i più abili che ci siano."
S["98503d5a"] = "In questo mestiere sei più $Gbravo:brava; di me! Ti serve qualcuno ancora più esperto di me: Doctor Herbert Halsey, un non morto che lavora nell'Apothecarium of the Undercity."
S["98516023"] = "$GBenvenuto:Benvenuta; a Ironforge, $C."
S["98559ed4"] = "Mmm, questo starebbe meglio appeso come scacciapensieri. Prendete appunti, classe... NON è questo che volete evocare nel pieno della battaglia."
S["985a85e5"] = "Presenta i monili, Maltrake."
S["985d19a3"] = "Dannazione! Nemmeno qui i pesci abboccano. Torno al mio vecchio posto di pesca!"
S["9860298d"] = "Solo per un periodo limitato, la crunchy frog la trovi in esclusiva qui alla Darkmoon Faire."
S["98664126"] = "Viviamo solo per servire l'antico. MUORI, INTRUSO!"
S["986f343f"] = "La forma fisica di %s si indebolisce. Noti che la Stone of Binding vicino alla creatura brilla! Colpisci ora!"
S["987080a5"] = "The Scepter of the Shifting Sands è di nuovo intero, $N.$B$BSei tu che devi guidare i tuoi eserciti nella maledetta città fortezza di Ahn'Qiraj e fare giustizia dei suoi abitanti.$B$BRecati a Silithus e presenta lo Scepter of the Shifting Sands a Jonathan the Revelator."
S["987159d4"] = "A tutti gli animali da queste parti ci pensa Erma. Se devi parlarle, la trovi proprio fuori dalla Lion's Pride Inn."
S["9883190f"] = "Come posso dimostrare il mio valore ai furbolg Timbermaw?"
S["98843953"] = "Vedo nei tuoi occhi che non sei $Gestraneo:estranea; alla tragedia che si consuma a Stratholme. Se vuoi porre fine alla misera esistenza delle povere anime intrappolate là dentro, entra nel cerchio. Porta direttamente alle porte della città in fiamme."
S["9885e70d"] = "Venite, venite tutti! Benvenuti alla Darkmoon Faire! Non siate timidi. Fatevi avanti da Lhara e compratevi un manufatto esotico da terre lontane. Se siete tra i pochi fortunati che hanno trovato le Carte di Darkmoon, scambiate due parole con il Professor Paleo. Avete fame? Sete? Siete fortunati! Qui ci sono rinfreschi per tutti, da Sylannia e Stamp. Vi consiglio la Darkmoon Special Reserve per mandare giù delle Red Hot Wings. E se è il futuro che cercate, allora correte, non camminate, a parlare con Sayge."
S["9896f526"] = "Sire, lasciatemi unire alla mischia! Strapperò loro la spina dorsale a mani nude!"
S["9897a32c"] = "Senza un soffitto di granito bello solido sopra la testa proprio non riesco a stare tranquillo. Tutte queste stelle lassù: roba da far venire i brividi."
S["98a4ba07"] = "Scommetto che adesso te ne penti, vero, $N!?!"
S["98a4f501"] = "Assicurati di passare dall'Apparato Gizmotronico per prendere un grimaldello e un E.C.A.C. Ti serviranno di sicuro entrambi per completare la missione!"
S["98b1610a"] = "Capisco, Madre Terra."
S["98b50cb9"] = "Il tempo della conquista si avvicina in fretta."
S["98bdf52e"] = "$N ha aggredito il fabbro!"
S["98c15067"] = "Tu $Gil migliore:la migliore; adesso, socio!"
S["98d2ee26"] = "Sono $Gpronto:pronta;, Anachronos. Ti prego, concedimi lo Scepter of the Shifting Sands."
S["98dc4a50"] = "Tilloa, sei tu? Ma no! È solo $Gun:una; $R $Gsudicio:sudicia;!"
S["98e05c47"] = "Se sei $Gvenuto:venuta; a cercare il dono di spostarti veloce e sicuro, sei $Gcapitato:capitata; nel posto giusto! È appena arrivato il modello di quest'anno dei nuovi Mechano-striders, e sono pronta a mostrarti tutto quello che ha da offrire!"
S["98e34bec"] = "Ancora una volta si può sentire la risata di %s nelle sale di Blackwing."
S["98e3db22"] = "Salve, $C. Se sei qui, saprai già che la Silverpine pullula di nostri nemici. I Forsaken devono respingerli, se vogliono sopravvivere!"
S["98e4c135"] = "Andiamo, goblin!"
S["98e819b9"] = "Vattene subito, $Gstraniero:straniera;! Con te non ho niente a che spartire."
S["98ea8ac3"] = "%s si infuria vedendo morire un cucciolo!"
S["98ebefb7"] = "Sss! Mi spaventi i pesci."
S["98f2b267"] = "Grazie, $N."
S["98f35c1e"] = "La chiave di Gelkak scivola nella fessura vuota."
S["98f67f19"] = "Lo so, lo so, sono qui in mezzo al nulla!$B$BVeramente casa mia è a Ratchet, ma dopo che mi sono schiantato qui con lo zeppelin ho pensato: tanto vale cominciare le ricerche per cui ero venuto!"
S["98f76b47"] = "Waldir dana O valesh ko odes. Ras O ruff noth ko veld ergin vil thor cynegold lo gothalgos."
S["990d2da8"] = "È sempre un piacere vederti, $N."
S["9914dc63"] = "Sei qui a fare rapporto, $C? Tutto il materiale bellico dell'Orda e dell'Alleanza è pronto e viene spedito a Silithus proprio ora. Dovrebbe arrivare tutto in meno di un giorno. Spero che qualcuno abbia trovato i vari pezzi dello Scepter of the Shifting Sands e li abbia rimessi insieme."
S["9919ba5b"] = "Ci siamo quasi!"
S["991bac8a"] = "Metto a tua disposizione tutto l'aiuto che posso offrire."
S["991f5124"] = "iCoke - Descrizione (S.H.E., confezione regalo)"
S["9920329f"] = "Non tutti i Tauren disprezzano la tua gente, $R. Ahimè, mi è proibito offrirti i miei servigi."
S["993053ec"] = "Accidenti, tutto questo per un filtro d'amore. Spero che ne valga la pena."
S["99345d3c"] = "Quando torna papà dai combattimenti dei Warsong? È passato così tanto..."
S["9935c82b"] = "Prendetelo finché è bello fresco! Pagnotte qui!"
S["99367246"] = "Gli shen'dorei saranno sempre in debito con gli spiriti per il loro aiuto, e i Windshapers hanno giurato di saldare quel debito e di riportare le cose com'erano prima. Purtroppo, senza gli spiriti a guidarci, siamo pericolosamente ciechi a quello che succede intorno a noi dentro Skywall.$B$BL'High Order è miope e arrogante, proprio come i suoi antenati Highborne, e cerca di dominare e controllare la magia di questo luogo. È proprio la strada che a suo tempo ci ha costretti a fuggire da Kalimdor e a stabilirci qui. Temo che, come per i nostri avi, la sua sicurezza abbia superato di gran lunga la sua competenza, e il risultato potrebbe essere disastroso."
S["9939eedb"] = "I clan dei centauri dominano le lande desolate di Desolace. Se fossero uniti, sarebbero una forza terribile. Per fortuna non lo sono, e litigano e si fanno la guerra fra loro."
S["993c733c"] = "Da soli non possiamo affrontare tutte le minacce di questa zona. Un'altra mano per combattere ci farebbe comodo, $N."
S["995fcb60"] = "Aiuto! Mi attaccano!"
S["9963e949"] = "Le c-c-catene... non... devono..."
S["996589dd"] = "Ricorda che tutte le cose sono legate. Se le bestie scomparissero dalla terra, la nostra gente morirebbe di una grande solitudine dello spirito, perché quello che accade alle bestie accade anche ai Tauren. Ciò che colpisce Azeroth colpisce chiunque la abiti."
S["996692b2"] = "Johnson? Credo sia qui da qualche parte..."
S["996ff258"] = "La tua intromissione finisce qui, $N! Lord Valthalak avrà la sua vendetta!"
S["99734496"] = "Se hai perso un pezzo della tua armatura Zandalarian, forse posso aiutarti."
S["9975660a"] = "Si sono presi di nuovo quasi tutto il raccolto, ma stavolta il capo dei banditi — Ferauu, detto \"il Randello\" — ci ha avvisato che sarebbero tornati ogni stagione e si sarebbero presi il doppio dell'anno prima."
S["99759e94"] = "Intrusi nella Manifattura? I miei costrutti vi distruggeranno!"
S["997616d9"] = "Ai tempi della guerra, Razelikh the Defiler era il più temibile fra i luogotenenti di Lord Kazzak. Quando la Legione fu sconfitta e Kazzak venne ricacciato in Tainted Scar, Razelikh ricevette dal suo padrone il compito di prendere il controllo delle Blasted Lands.$B$BMentre l'Alleanza combatteva futili battaglie contro l'Orda per i territori al di fuori delle Blasted Lands, Razelikh riuniva le varie sette dello Shadow Council e i brutali ogres Dreadmaul della regione."
S["9976a10a"] = "Spaccalo!"
S["9977d2cf"] = "Oh, fratelli miei! Che possiate trovare pace nelle vostre tombe d'acqua!"
S["9977eaa0"] = "Questa è la risposta alla prima domanda della prima catena."
S["997df8f6"] = "Oh, adesso si fa sul serio! Scommetto che pensavi che anch'io sarei stato da solo, eh?!"
S["9983eaa1"] = "No, Walt, sono ancora vivo. Quella volta a Ratchet il tuo colpo mi ha mancato il cuore di un soffio."
S["9983f8ea"] = "$N arriva di corsa! Preparatevi a combattere!"
S["9984f7e6"] = "L'età mi ha storpiato, e mi hanno accecato cose di cui preferirei non parlare. Di certo un vecchio orco come me non ha niente a che spartire con te, $C."
S["998aaec6"] = "%s lascia andare la Sfera di Draenetista Perfetta, che resta sospesa davanti a lui."
S["99923352"] = "$GSfrontato:Sfrontata;. A Master Ravenholdt la sfrontatezza non piace."
S["999588db"] = "Allontanati dagli effetti personali del Tenente!"
S["9995bf15"] = "$N, la traduzione è finita!"
S["99a32b70"] = "Presto, fratelli! Dovete andare adesso! Non so per quanto ancora il varco resterà aperto!"
S["99a8c43d"] = "Dammi il faro, Slidore! E poi puzzi ancora!"
S["99afbd80"] = "Senti un po', se non mi dici del fuoco..."
S["99ba4a57"] = "Sono Muln Earthfury dell'Earthen Ring. Cosa ti porta davanti a me, oggi?"
S["99c757df"] = "%s ruggisce eccitato mentre corre verso Volcor. Quando raggiunge il suo padrone, Grimclaw gli lecca la faccia."
S["99d12eec"] = "Non posso aiutarti; il tuo lavoro supera il mio. Parla con Arthur Moore, là vicino alle bare. Potrà addestrarti ancora."
S["99d1b97a"] = "%s evoca un messaggero..."
S["99d787d8"] = "Stalagg uccide!"
S["99da9b79"] = "Avanti... MARSC!"
S["99db7b5d"] = "Io contro cinquanta orchi? Mica sono $Gscemo:scema;, $N. Il mio vecchio me lo diceva sempre: 'La discredizione è la parte migliore del biscotto', o una cosa così, e io lo capivo cosa voleva dire."
S["99ece911"] = "Lo sai bene che è così, mortale; qui sto mettendo da parte molte finzioni, e ti consiglio di fare altrettanto.$B$BSei $Gvenuto:venuta; qui, è chiaro, perché sai che quello che possiedi, ottenuto con le tue azioni nel Sunken Temple of the Atal'al, ti ha condotto da me per uno scopo. Si tratta di dare pace al mio compagno... a mio fratello. È prigioniero di un incubo dentro il Sogno stesso. Da solo non può liberarsi."
S["99f83af8"] = "Venite per la birra, restate per l'atmosfera!"
S["99fd2d75"] = "Qui non ci sono i draghi blu in persona, ma i seguaci di Malygos sì. Non so il perché, però una cosa posso dirtela: dove ci sono i draghi blu, aspettati la magia arcana. Non mi stupirei se i draconidi fossero qui a fare la guardia a qualcosa... magari a qualcosa che hanno lasciato gli Highborne."
S["9a02ab29"] = "Abbiamo tutti i lingotti di rame che ci servono. Grazie per l'aiuto, $C. Forse vorrai dare una mano con gli altri materiali che si raccolgono qui."
S["9a06ff70"] = "Finalmente ti ho raggiunto, Nefarian. Non avrai davvero pensato di sfuggire alla potenza degli altri Aspetti?"
S["9a085749"] = "Sei sveglia?? La tua cura deve aver funzionato! Grazie, $N."
S["9a0f9f2c"] = "Devi continuare! La loro determinazione sta vacillando. Bevi dal mio potere e sii $Grinnovato:rinnovata; ancora una volta!"
S["9a12b6a3"] = "Ma... Malfurion, Cenario, Ysera... combattono ancora. Hanno bisogno di me. Devo tornare subito nel Sogno."
S["9a192e82"] = "E infine la candela... per bruciare chi vorrebbe ostacolarti!"
S["9a1f68d8"] = "Il Grimclaw?! Calma, amico mio... dov'è il tuo padrone Volcor?"
S["9a23b289"] = "Salve e saluti a te, $Gbuon:buona; $R. Magari ti va di bere un goccio con me, per scacciare il freddo del vento? Vieni, ne ho più che a sufficienza da dividere."
S["9a2ed23e"] = "Le fanguzzole sono una razza di pesci particolarmente puzzolente che ama le acque tropicali. La Zulian Mudskunk — la più puzzolente di tutte, si trova solo nelle acque afose di Zul'Gurub.$B$BCredo che siano state le Zulian Mudskunks ad attirare Gahz'ranka in quel posto, anche se i troll probabilmente ti diranno che è uno dei loro dei...$B$BCredi a quello che vuoi, ma dammi retta — riempi una delle mie esche con le Zulian Mudskunks e quel vecchio arriverà di sicuro!"
S["9a30e53a"] = "Per me è finita, $N, ma tu potresti ancora riuscire a fermare questi mostri!"
S["9a388c60"] = "Un Horde Commendation Signet viene assegnato a un eroe che va ben oltre il proprio dovere verso l'Orda. Nelle principali città si trovano diversi Ufficiali d'Encomio delle fazioni dell'Orda: parla con quello presso cui vuoi aumentare la tua reputazione, e dagli il numero di anelli che ti chiede!$B$BA proposito, durante lo sforzo bellico qui, se preferisci ricevere una ricompensa materiale per i tuoi anelli invece della reputazione, cerca Warlord Gorchuk."
S["9a3f32b3"] = "L'Orda ha preso l'Irondeep Mine!"
S["9a4272b0"] = "Per me, prima di tutto viene la sicurezza di Grom'Gol."
S["9a4466fa"] = "Mi spiace, ma più di così non posso insegnarti. Se vuoi imparare ancora, va' da Telonis nella Craftsmen's Terrace of Darnassus. Dicono che sia piuttosto bravo."
S["9a458215"] = "Una volta ho visto un Sea Giant. Non è una cosa che mi piacerebbe rivedere. Burp!"
S["9a4efbcd"] = "Aha! Visto! Secondo me questa chiave automatica nuova è proprio quel che ci vuole per il collettore di afflusso, il mio ultimo progetto."
S["9a54ae09"] = "A Razor Hill c'è un Istruttore di Ingegneria. Si chiama Mukdrak, e di solito lo trovi vicino alla forgia."
S["9a57f09e"] = "La banca è nella serena città di Darnassus. Se vuoi depositare i tuoi averi, devi andare lì."
S["9a582abe"] = "Miranda, potresti dirmi quante insegne costano gli oggetti che offri agli avventurieri con reputazione osannato?"
S["9a5ab56d"] = "In questo calderone ribollono bolle verdi e dense. Teschi, ossa e organi di creature sconosciute nuotano nel brodo vischioso...$B$BE a galla, pigramente, affiorano i teschi di due troll un tempo potenti:$B$BGan'zulah e Nezzliok."
S["9a63d823"] = "Il Frostwolf Graveyard è stato preso dall'Orda!"
S["9a663c95"] = "È tutto raccolto, $C. Viene tutto trasportato a Silithus per i preparativi finali e dovrebbe arrivare entro un giorno. Tutte le nostre forze unite aspettano $Gl'eroe:l'eroina; che completerà la riunificazione dello Scepter of the Shifting Sands, suonerà il gong e darà inizio alla guerra di Ahn'Qiraj."
S["9a6d0c80"] = "Cercate questo: [Red Scepter Shard]? Venite a prenderlo..."
S["9a9ced09"] = "Ti prenderò volentieri sotto la mia ala. Cominciamo."
S["9a9f4952"] = "Ehi Nag, che ne dici di tagliarmi una fetta di quel..."
S["9a9f5b6e"] = "È così triste per voi, poveri bambini."
S["9aaf913b"] = "Bada a dove metti i piedi, $R. Quando si tratta di punire chi vuole fare del male a questo mondo, noi della Brotherhood of the Light non siamo indulgenti come i nostri confratelli.$B$BGuai a chi fa infuriare Korfax.$B$BOra, se non hai affari da sbrigare con me o con gli altri membri della Fratellanza, ti prego di andartene e di lasciarci continuare la riunione."
S["9ab76d26"] = "Le giornate si fanno più lunghe, e dei conflitti di queste terre ancora non si vede la fine. Non ci vuole un incantatore per capirlo. Finché puoi, impugna una lama, $C. La guerra può bussare alle nostre porte da un momento all'altro e, se non sbaglio, hai l'aria di $Guno:una; che ne gode."
S["9ac83a08"] = "Questo kodo è tutta un'altra cosa rispetto alla bestia che avevo attirato all'inizio! Chissà se il kombobulatore funzionerebbe anche su di me."
S["9ace028d"] = "%s osserva il terreno e annuisce soddisfatto."
S["9ad0feec"] = "Ehilà! Sono Gregan. Cosa posso fare per te?"
S["9ad57746"] = "Abbiamo provviste in eccesso, ma non molte. Ce ne serviranno parecchie di più prima di poter mandare un assalto via terra nel Field of Strife."
S["9ad6821b"] = "Estranei! Ammazzateli tutti!"
S["9ad68aa8"] = "Oh, accidenti..."
S["9ae1df69"] = "Per quanto si stia bene a Gadgetzan rispetto a Un'Goro, ci sono delle brave persone che contano su di noi per avere un po' di provviste. Se sei $Gpronto:pronta; a partire, allora lo siamo anche Dadanga e io. In sella!"
S["9ae1eb91"] = "$GAttento:Attenta;, $C. I Windshapers non tollereranno ostilità da parte del High Order."
S["9ae49531"] = "Cerchi Mishiki. Ha una capanna a sud, in Sen'jin Village."
S["9aea4415"] = "E adesso la guerra, lei arriva presto. Resta solo da mandare tutti questi beni e armi alla Cenarion Hold a Silithus, e sarà fatto entro un giorno. Poi qualche anima coraggiosa dovrà suonare il gong vicino a quelle porte di Ahn'Qiraj per aprirle e far cominciare la guerra."
S["9aeeb2a4"] = "Quando si imbatté nei profughi al Greymane Wall, sentì che era suo dovere soccorrerli, e mandò la sua donna avanti fino a Hillsbrad."
S["9aeee014"] = "Grazie, $N. Ora andiamocene di qui!"
S["9af19059"] = "Salve, ragazza... mi chiamo Oglethorpe, e se hai uno di quegli straordinari congegni gnomeschi, magari l'ho fatto proprio io! Se è esploso, non sono stato io; ma se ti ha resa ricca, possiamo parlare di percentuali!$B$BAh, e se vieni da Gnomeregan, puoi prendere due angoli di novanta gradi, sbatterli insieme e metterti in marcia: non ho niente da dirti."
S["9afbb502"] = "È giunto il momento di dimostrare quanto vali come $Ggregario:gregaria;, $N. Prendi questo segnalatore e piantalo proprio al centro del cimitero di Snowfall. Difendilo finché non arriva la mia flotta.$B$B<Mulverick fa il saluto militare.>"
S["9b01779c"] = "Vestiti!? Contro del buon acciaio non ti serviranno a niente! Bah, se sei $Gsicuro:sicura; di voler diventare $Gsarto:sarta;, va' da Magar's Cloth Goods in The Drag."
S["9b01b471"] = "Attenzione! Sembra che ne arrivino altri!"
S["9b0744a5"] = "James Van Brunt lavorare in anello interno di War Quarter. Lui fare buona maglia per noi."
S["9b0ae08d"] = "%s rende un ultimo servizio a Ragnaros..."
S["9b129f12"] = "Aspetta, $N!!! Sembra che qui ci servirà un po' d'aiuto..."
S["9b21d76e"] = "Sei finito, Mulv!"
S["9b2347fd"] = "Pagherai per ciò che hai fatto a Trey, $R!"
S["9b279874"] = "Ah, $R... Io so molte cose del mondo, e so come si creano amuleti di grande potere."
S["9b297afe"] = "Ehi! Grazie per avermi salvato la pelle! Credo che starò sdraiato un po', finché non mi tornano le forze."
S["9b2a0e05"] = "Ancora un minuto! Resistete, il rituale sta per fare effetto!"
S["9b2b95eb"] = "%s ascolta la supplica di $N."
S["9b2e0823"] = "Ma che... cosa sono quelle cose che strisciano verso di noi? Ci... ci stanno attaccando!"
S["9b39bb24"] = "Fai largo, cane rognoso! Revilgaz mi ha risparmiato la forca, ma la punizione potrebbe essere brutta quasi altrettanto."
S["9b3dde58"] = "Quanto vorrei combattere al tuo fianco in una gloriosa battaglia, e invece me ne sto $Gbloccato:bloccata; qui di guardia. Va' all'Hall of the Brave nell'Orgrimmar's Valley of Honor e parla con Kartra Bloodsnarl. Ti aiuterà a raggiungere l'Alterac Valley. Facci onore, $N!"
S["9b3f401c"] = "Pagherete tutti a caro prezzo quando tornerò dagli abissi!"
S["9b3febb2"] = "Sarai un degno sacrificio per Ragnaros."
S["9b42891c"] = "Oh Umi, ti prego, insegnami di nuovo a creare uno Yeti Tranquillo. Mi manca tanto."
S["9b461216"] = "C'è un odore strano."
S["9b59b8c0"] = "La tua corsa finisce qui, tu che non mi sei $Gamico:amica;!"
S["9b6ea4ad"] = "Possiamo fare una pausa? Mi fanno male i piedi e quelle... quelle cose là sotto mi mettono i brividi."
S["9b750e60"] = "Sarà veloce, ma non indolore!"
S["9b75240d"] = "CRAAA! Polly vuole sgranocchiarti!"
S["9b7836f7"] = "I figli di Sul proteggeranno il loro padrone. Risorgi ancora una volta, Sul'lithuz!"
S["9b7e0659"] = "Spostatevi! Lasciateli passare!"
S["9b830db5"] = "Niente male... Direi che potrei anche addestrarti. Bene! Cominciamo..."
S["9b8cf4ce"] = "Hai disturbato il mio riposo, $C. Ora affronta la mia ira!"
S["9b93f46b"] = "Le erbe selvatiche, unite al rispetto, possono essere un potente alleato. Se vuoi proseguire l'addestramento, ti conviene cercare Bena nella sua bottega di alchimia, sulla terrazza di mezzo."
S["9b972521"] = "$GUn:Una; $N $Gvivo:viva;... che presto sarà $Gmorto:morta; come me."
S["9ba3ea38"] = "%s comincia a lanciare un incantesimo mentre gli prendi il mantello."
S["9bb19c8c"] = "È il materiale di base usato nella sintesi delle razze. Per sintetizzare gli Earthen si è presa come fondamento una sezione della crosta di Azeroth, al posto della solita base costruttiva in biomassa dei Creatori.$B$BStudiando la composizione del mondo, i Creatori sono arrivati a teorizzare che si potesse sintetizzare un essere potenziato che incarnasse la resistenza dell'essenza di questo mondo. Ci sono riusciti partendo da una miscela dei vari composti minerali del nucleo di Azeroth."
S["9bb40d51"] = "Ecco la classifica finale!$B$BThrall:$BCairne:$BSylvanas:$BTotale Orda:$B$BBolvar:$BMagni:$BTyrande:$BTotale Alleanza:$B$BL'Alleanza ha l'eroe più popolare!"
S["9bb86b54"] = "Grazie agli sforzi congiunti delle gilde di avventurieri dell'Alleanza, siamo riusciti a raccogliere tutte le singed corestones che pensiamo ci serviranno. Tuttavia, potresti chiedere in giro agli altri raccoglitori qui, per vedere se hanno ancora bisogno di aiuto per raccogliere risorse vitali."
S["9bc0c203"] = "Calma, mon. Io addestro solo guerrieri."
S["9bd46bb4"] = "Ahh! Aiuto! Uno gnomo impazzito vuole uccidermi!"
S["9bd47bc6"] = "Presto saprete il prezzo della vostra intromissione, mortali... Il padrone è quasi intero... E quando si alzerà, il vostro mondo cesserà di esistere."
S["9bd50abd"] = "Non sembri granché, eppure qualcosa mi dice che hai ragione. Credo che resterò seduto qui ancora un po'. Grazie della chiacchierata, $Gstraniero:straniera;."
S["9bd70a78"] = "Mi dispiace, $N... Ma sembra che ti abbia fuorviato."
S["9bd9ad4d"] = "Chi osa disturbare la mia meditazione?"
S["9bda7b66"] = "Non tollereremo nessun servo dei demoni nelle nostre terre!"
S["9bdd69f6"] = "Bene, bene... sei $Gpronto:pronta; a combattere per l'Orda nelle Darkspear Islands?"
S["9bdf39e3"] = "L'ombra dello Scourge resta ancora su questa terra, stolti! Non prevarrete mai!"
S["9be2491d"] = "Un tempo, mortale, il Firelord e i suoi fratelli regnavano su tutto questo mondo. Al servizio degli Old Gods, ha combattuto contro i Titani per dominare il pianeta. Vinta la guerra, i Titani hanno esiliato il mio padrone e i suoi fratelli nell'Elemental Plane — dove resteranno imprigionati fino alla fine dei tempi."
S["9be91e21"] = "La Locanda? Ah, hai voglia di buttar giù qualche boccale delle migliori birre di Ironforge? Il posto che fa per te è The Stonefire Tavern.$B$BLa trovi subito a sinistra dell'ingresso di Ironforge se entri, a destra se esci."
S["9bf6912d"] = "Sono $Glibero:libera;! Ora lavoriamo insieme per salvare mio fratello, Sothos!"
S["9bf71ea0"] = "Non perdere la speranza, $Gfiglio mio:figlia mia;. Con la fede, marceremo attraverso questa oscurità e vedremo di nuovo l'alba."
S["9bf735e8"] = "Ah! Sono giorni che Tirth lo cerca, ma quello non vuole farsi trovare. È un fifone!"
S["9bf92eff"] = "Mille anni fa, alla fine della War of the Shifting Sands, tre dei nostri consanguinei si sacrificarono trattenendo i Qiraji dentro queste sale, mentre Anachronos e Staghelm sigillavano Ahn'Qiraj.$B$BOgnuno di noi giurò che, se lo Scarab Wall fosse mai caduto, avrebbe cercato Merithra, Arygos e Caelestrasz.$B$BEd è caduto davvero... perciò siamo venuti."
S["9bfb3cda"] = "%s studia la pergamena del Tomo del Twilight..."
S["9bfb692a"] = "Proteggetemi, anime coraggiose, mentre entro in The Emerald Dream a salvare Naralex e a porre fine a questa corruzione!"
S["9bfc6852"] = "Awa paw ba wa."
S["9c05e96f"] = "Keever non è contento. Forse se Keever provasse una dose più grande, il problema si risolverebbe."
S["9c076788"] = "Percepisco un turbamento che ti si annida intorno..."
S["9c0ca76a"] = "Ti serve l'aiuto di Bulrug. Lo troverai all'aperto sull'altura inferiore, tra la locanda e la Thunder Bluff Bank."
S["9c131751"] = "Qui sei sempre $Gil benvenuto:la benvenuta;, $N. Grazie per le risate, e non preoccuparti per Daryl: se l'è cercata!"
S["9c225c46"] = "C'è chi prova a seguire la via del Ladro, ma solo gli elfi della notte sono accolti davvero nell'abbraccio della notte. Se vuoi percorrere il sentiero dell'ombra, cerca Syurna nella Cenarion Enclave."
S["9c2388d1"] = "Modoss rand eft havar. Gor eft thorneb hoga ta khazrega....hor!"
S["9c278d5e"] = "La Night Watch da sola non può proteggerci per sempre. Ci serve l'appoggio della Stormwind Army."
S["9c34b36f"] = "Guardate cosa hanno fatto al mio ragazzo."
S["9c3a4522"] = "Sforzati di mantenere l'equilibrio in ogni cosa, $C: è lì che risiede la vera armonia."
S["9c3e818f"] = "La tua abilità non è trascurabile. Dato che sembri avere esperienza a sufficienza, c'è una questione per cui richiedo il tuo aiuto."
S["9c42bdf1"] = "Vattene, infedele! Che il potere dell'Abisso ti abbatta!"
S["9c465581"] = "Guardali scappare!"
S["9c478265"] = "Non dimenticare che, per quanto questo regno sia la nostra casa da millenni, qui saremo sempre un po' degli estranei. Non siamo nel mondo terrestre che ha dato vita al nostro popolo, ma nel regno di Skywall, una parte del piano elementale.$B$BArrivammo qui come ospiti di spiriti con cui, in epoche passate, facemmo causa comune. Ora che noi Shen'dorei siamo rimasti senza la loro presenza — e forse — senza la loro protezione, non c'è modo di sapere come ci vedranno gli altri abitanti di questo piano."
S["9c4ac9ce"] = "Cerca Innkeeper Grishka nella Valley of Strength: la sua locanda è sul lato est, a nord delle porte principali della città."
S["9c5405fe"] = "Salute, $Gavventuriero:avventuriera;."
S["9c7d80df"] = "Continui a sfogliare il diario in cerca di qualunque informazione che possa aiutarti a trovare il forziere rubato.$B$BVerso le ultime pagine del libro, a matita rossa, noti un appunto di James a margine della pagina. Dice: \"Vecchia casa vicino allo Stone Cairn Lake... gli gnolls andranno benissimo come guardie del corpo.\"$B$BNiente fa pensare che il forziere sia lì, ma non sembrano esserci altri indizi."
S["9c817a90"] = "Incursione Trogg! Difendimi mentre chiudo il buco con l'esplosivo!"
S["9c8c0d84"] = "Mi chiedo se il mio signore renderà schiavo il tuo popolo... o se si limiterà a divorarlo per divertimento. Io.... aspetta, cos'è questo?"
S["9c8cb0d7"] = "Che il mio colpo vada a segno!"
S["9c8e51d0"] = "Salve e ben $Gtrovato:trovata;, $Geroe:eroina;! Ho da sottoporti le ultime notizie dai due continenti, e da luoghi ancora più lontani."
S["9c90294f"] = "Molte delle forniture che servono ai sarti passano per Darnassus, quindi non c'è da stupirsi se si sono trasferiti tutti lì a lavorare. Se vuoi diventare $Gsarto:sarta;, ti conviene andare a Darnassus."
S["9c907975"] = "A quanto pare dovrai andare avanti tu fino a Ratchet e dire allo Sputtervalve che ho distrutto il segatronchi."
S["9c91d855"] = "Con piacere, zuccherino. Torno presto..."
S["9c9565e1"] = "Devi essere in rapporti amichevoli con gli umani di Stormwind prima che io ti insegni a cavalcare, $C."
S["9c9dda13"] = "Mi serve aiuto per recuperare un pezzo mancante della mia Tenuta dell'Aruspice, Maywiki."
S["9cb1e92c"] = "Il bolide goblin è bello potente, ma gli gnomi nella loro macchina hanno nascosto un paio di trucchi..."
S["9cb3b3f4"] = "Certo che posso insegnarti la sottile arte di maneggiare un'arma ad asta, ma ti costerà."
S["9cbdb2c2"] = "La Venture Company, di base attorno alla Windshear Crag a Stonetalon, tiene le provviste in casse chiuse."
S["9cbebeb5"] = "$N, i miei compiti sono finiti e ora me ne vado. Buona fortuna, $Gamico mio:mia signora;, e ricorda di tenere in funzione la Campana, la Ruota e la Candela!"
S["9cc0164d"] = "Elder Snowcrown lo trovi alla Cappella della Speranza di Luce, nelle Eastern Plaguelands."
S["9cd2b738"] = "Mio caro Staffron, hai dimenticato cosa significa amare? L'amore che un tempo abbiamo condiviso?"
S["9cd30e21"] = "Ja mon, io sto raccogliendo i pesciolini-pesciolini per l'Orda. Loro si preparano per grande guerra nel deserto di Ahn'Qiraj, e chiedono a me di portargli un bel po' di spotted yellowtail. Ma adesso noi avere solo un pochino. Tu sei qui per aiutare?"
S["9cd9625d"] = "Fatto! Le modifiche dovrebbero darci un po' di velocità in più, ma non credo che la piccola reggerà a troppi urti."
S["9ce975bd"] = "Ehilà, $Gviaggiatore:viaggiatrice;!"
S["9ceb4b7c"] = "<Il trampoliere smette di agitarsi e ti fissa con gli occhi dorati.>"
S["9cec2d94"] = "Di sicuro è questo che il traditore sperava di offrirci in cambio della nostra protezione."
S["9ced616b"] = "%s si ritrae per il dolore mentre il Judgement of Justice lo investe!"
S["9cf07a83"] = "Altri troggs! Tienimeli lontani mentre preparo gli esplosivi!"
S["9cff8d02"] = "%s si accovaccia per leggere il Yagyin's Digest..."
S["9d15b980"] = "Sayoc, il maestro d'armi orco, sta nell'Orgrimmar's Valley of Honor. Può addestrarti a usare archi, pugnali, armi da pugno, asce a una e a due mani e armi da lancio.$B$BHanashi, il maestro d'armi troll della Valley of Honor di Orgrimmar, può insegnarti a usare archi, asce a una e a due mani, bastoni e tutte le armi da lancio.$B$BAnsekhwa, il maestro d'armi tauren, lo trovi sulla terrazza inferiore di Thunder Bluff. Insegna a usare mazze a una e a due mani, bastoni e armi da fuoco."
S["9d167669"] = "Ewiddan majis veld engoth! Thor!"
S["9d17c793"] = "Desolace non è poi così male, se non ti danno fastidio i centauri che attaccano di continuo."
S["9d1dd535"] = "Non dimenticare di dire a Greatfather Winter che sorpresa segreta vorresti ricevere per questo Winter Veil!"
S["9d232201"] = "Mi sembri $Guno:una; che ha bisogno di lavoro, $Gamico:amica;. Dovresti salire sul tram e andare da mio fratello, Monty, alla stazione del Deeprun Tram di Ironforge. Sono $Gsicuro:sicura; che ha qualcosa da farti fare."
S["9d2bc29f"] = "Ritira le tue truppe, fratello, e ti prometto una rapida seconda morte!"
S["9d329534"] = "Proprio qui da Timberline Arms trovi Buliwyf, il maestro d'armi nanico: insegna a usare armi da pugno, armi da fuoco, asce e mazze, sia a una sia a due mani.$B$BAl Weller's Arsenal, a Stormwind, c'è invece Woo Ping, il maestro d'armi umano, che insegna balestra, pugnali, spade a una e a due mani, armi in asta e bastone.$B$BIlyenia Moonfire, la maestra d'armi elfa della notte, la trovi alla Terrazza del Guerriero a Darnassus: lì insegna arco, pugnali, armi da pugno, bastone e armi da lancio."
S["9d5a770d"] = "Ho bisogno di aiuto per recuperare un pezzo della mia Veste del Confessore, Al'tabim."
S["9d5e38d9"] = "Non te l'avevo detto che le mie nuove tecniche di dominazione avrebbero funzionato?"
S["9d60a623"] = "La trama di cui è intessuto il nostro mondo è assai delicata. Basta un po' di conoscenza, e saperla mettere in pratica, per strapparla. È così che nascono gli squarci."
S["9d62c998"] = "Hai l'aria da Fabbro, tu: fuliggine sotto le unghie e acciaio nelle ossa. Eh già, hai proprio sangue da Fabbro nelle vene. Quindi sei $Gvenuto:venuta; da me per imparare un paio di cose. Be', $Gragazzo:ragazza;, prendi un martello e vediamo cosa posso insegnarti."
S["9d749a33"] = "Uoh!...Uoh!...Ahh! C'è mancato poco. Ops!...Oh, che dolore, $Gragazzo mio:ragazza mia;, che dolore!"
S["9d870821"] = "Se insegnassi ai principianti, verrebbero a trovarmi molti più allievi, e ci sarebbe un gran baccano. Vai a parlare con Dan Golthas, là. È un po' intenso, ma ha buone intenzioni ed è un insegnante decente."
S["9d90f15d"] = "È troppo tardi per tornare indietro."
S["9d998663"] = "Ora, dove ho messo quel documento di accompagnamento?"
S["9d9ee28c"] = "Brill è da questa parte. Andiamo avanti."
S["9db0ad4d"] = "Eh eh! Questo sarà un ottimo nascondiglio."
S["9db3ab2e"] = "Pazienta, $N. La torcia è quasi pronta."
S["9dbb53fd"] = "La Thunder Bluff Bank è sull'altura più bassa."
S["9dbd511f"] = "Zul'Farrak — Weegli Blastfuse — Saluto predefinito."
S["9dbf7863"] = "%s si guarda da una parte all'altra..."
S["9dc196b4"] = "Nella nostra famiglia l'Incantamento si tramanda da generazioni. Io l'ho imparato da piccolo, come sta facendo adesso mio figlio."
S["9dc2c95f"] = "%s si dissolve davanti ai tuoi occhi."
S["9dc3e0b4"] = "Scappate pure, sciocchi! Il vostro destino è comunque segnato!"
S["9dc5571a"] = "Nessuno può rubare i segreti dei Creatori!"
S["9dc9b6c1"] = "Grifoni, eh? Quelle bestie non mi sono mai piaciute granché, ma ognuno ha i suoi gusti.$B$BDungar Longdrink lo trovi sul bastione, nel Trade District."
S["9dcdc39a"] = "Eccola — Gadgetzan! Ormai siamo in dirittura d'arrivo!"
S["9dd87f80"] = "Mmh, che domanda strana? Non a molto, credo. Mia madre la usava come talco per i neonati, contro gli arrossamenti da pannolino, ma a parte questo non le conosco altri buoni usi.$B$BPerché me lo chiedi?"
S["9dd89e6c"] = "L'animale sembra confuso."
S["9ddc316c"] = "Se vuoi diventare $Gun potente paladino:una potente paladina;, non c'è maestro migliore di Lord Grayson Shadowbreaker. Sta nella Cathedral of Light, in Cathedral Square."
S["9ddfe3cc"] = "Stiamo... indagando."
S["9de2e4ce"] = "Guerrieri della notte... Radunatevi!"
S["9de61dee"] = "Ce l'abbiamo fatta, $Gragazzo:ragazza;! L'Alleanza e l'Orda hanno finito di raccogliere tutto quello che, secondo noi, ci servirà per la Guerra di Ahn'Qiraj. Gli ultimi rifornimenti stanno viaggiando proprio ora verso Cenarion Hold, in Silithus, e fra qualche giorno sarà arrivato tutto. Poi $Gqualche eroe coraggioso:qualche eroina coraggiosa; dovrà suonare The Scarab Gong con lo Scepter of the Shifting Sands per aprire le porte di Ahn'Qiraj. E quando si apriranno, comincerà la guerra!"
S["9dece1d2"] = "Devi trovare Swart. Lo trovi nella caserma, sul lato est di Razor Hill."
S["9df0a9c3"] = "Che state facendo? Intrusi!!"
S["9df2d966"] = "$GBenvenuto:Benvenuta; al Blue Recluse, dove chi ama la magia si ritrova per scaricare la pressione. Non alla lettera, s'intende. Che cosa ti servo, $Gsignore:signora;?"
S["9dff7f87"] = "Mostratemi cosa sapete fare!"
S["9e0474a6"] = "%s ringhia in segno d'intesa, poi si raddrizza e si allontana nella foresta."
S["9e05e26b"] = "Anu'dorini Talah. Ru shallora enudoril."
S["9e062fba"] = "Dopo l'attacco dei makrura abbiamo capito che la Gallant non sarebbe sopravvissuta a un altro, e io e i pochi marinai rimasti abbiamo abbandonato la mia nave.$B$BOra siamo a terra e presto ci metteremo in cammino verso il villaggio di Nijel's Point, ma fra noi e la salvezza ci sono molti pericoli, e temo che Desolace ci divorerà.$B$BScrivo queste righe sperando che qualcuno venga a sapere che fine abbiamo fatto e un giorno ci vendichi sui mostri delle acque che sono stati la nostra rovina."
S["9e0db880"] = "Vediamo... quattordici più sette, riporto due... oh, dimmi?"
S["9e0e55d0"] = "Va bene, capo. Ma sei $Gsicuro:sicura;? Mi sembra solo uno spreco di un buon allenamento."
S["9e14ce1d"] = "$GStolto:Stolta; $C! Spezzerò le ossa di $Gquesto:questa; $R debole!"
S["9e21a167"] = "L'Old God creò dai silithid degli avatar a sua immagine. Questi avatar sarebbero stati conosciuti come Qiraji. Senzienti e dotati di uno scopo, i Qiraji diedero un nome al loro creatore: era nato C'Thun... Per molte migliaia di anni i Qiraji lavorarono febbrilmente per costruire un esercito capace di devastare il mondo che avrebbe tradito il loro dio. La grande città fortezza di Ahn'Qiraj fu creata per ospitare i loro eserciti sempre più numerosi e prepararsi alla venuta di C'Thun."
S["9e347ed2"] = "Il palo è coperto dai resti di coloro che sono stati tanto sciocchi da far infuriare il Capoguerra."
S["9e3ca0d1"] = "Salve, $C. Mi sono accampato qui al Bulwark per prepararmi al viaggio nelle Plaguelands. Ho sentito dire che non molto tempo fa un grande mago umano si è stabilito a Hearthglen: la Scarlet Crusade gli aveva ordinato nuovi archi e fucili per i suoi guerrieri e cacciatori. Si dice che avesse finito un'arma straordinaria prima che la Crociata lo uccidesse.$B$BPenso che ormai diffidino dell'arcano più di prima."
S["9e3f4ec6"] = "Liladris mi aspetta a Maestra's Post, quindi dovremmo sbrigarci, $N."
S["9e3fcba0"] = "Udite, udite, abitanti di Tanaris! Si sappia che $N è un membro $Gosannato:osannata; di The Mithril Order. Un fabbro d'onore, di dedizione e di infinita pazienza. Tre urrà per $N!"
S["9e406b98"] = "Se lo trovi, o se trovi... qualunque cosa, fammelo sapere, ti prego."
S["9e433f74"] = "Gli Dei Primordiali? Impossibile!"
S["9e45b020"] = "Sì, ma ti darà più soddisfazione se te ne intendi di erboristeria! Avrai dei semi speciali da curare e coltivare. Con l'Evergreen Pouch che riceverai riesce a far crescere qualcosa perfino un principiante, ma chi mostra un po' di talento in erboristeria avrà raccolti più abbondanti."
S["9e4e5dbe"] = "Non lo sappiamo.$B$BI Dark Irons sopravvissuti si sono spinti dentro la montagna e lì hanno cominciato a ricostruire la città.$B$BPoi, dalle ceneri di Thaurissan, sono sorti Blackrock Spire e la nuova nazione Dark Iron, e altre fortificazioni sono state costruite nella Searing Gorge, nella zona conosciuta come il Calderone.$B$BHanno cominciato a girare storie di un antico male che controllava il regno dei Dark Irons."
S["9e64bdc0"] = "Be', va bene allora, $N. Vedo che hai riconosciuto i tuoi errori e sei $Gtornato:tornata; all'ovile dell'ingegneria.$B$BDivertiti con il tuo yeti!!!"
S["9e6bf7c6"] = "%s attacca il Karang's Banner!"
S["9e6c33d2"] = "CHI UCCIDE GOR'TESH!?!? CHI FA QUESTO?!"
S["9e6db41c"] = "Gli oggetti che hai offerto erano puri, $N, e questo nuovo totem della purificazione è potente."
S["9e6e9229"] = "E sono partiti!"
S["9e7de56f"] = "Ti credi abbastanza intelligente? Pensi di avere la stoffa? Vediamo!"
S["9e95e3eb"] = "Ah, di questi tempi Stonebrow da Ironforge esce poco: se vuoi imparare la professione di sarto, dovrai andarlo a trovare lassù, a Ironforge."
S["9e96d0b8"] = "Più di mille anni fa un gruppo di sacerdoti troll, gli Atal'ai, tentò di riportare in vita un antico dio del sangue chiamato Hakkar the Soulflayer. Ne seguì una guerra civile, dopo la quale i sacerdoti furono sconfitti ed esiliati nella Swamp of Sorrows. Lì eressero un tempio a Hakkar, per prepararne l'arrivo nel mondo fisico. La dragonessa Aspect Ysera scoprì presto i piani degli Atal'ai e fece sprofondare il tempio sotto le paludi, e ancora oggi i possenti draghi verdi ne sorvegliano le rovine."
S["9e99ad40"] = "Il Cannone Ultra 5000 Blastenheimer è un dispositivo per proiettili umani monoposto all'avanguardia. Capace di consegnare il suo carico quasi alla velocità di un drago, il cannone è l'orgoglio e la gioia della famiglia Blastenheimer, famosa in tutto il mondo per le sue imprese aeronautiche e combustibili!$B$BSe vuoi essere $Glanciato:lanciata; nei cieli per volare $Glibero:libera; come un uccello, cerca Maxima Blastenheimer all'estremità orientale della fiera. Ho sentito che ha piazzato un anello bersaglio laggiù, sul Crystal Lake, a cui mirare mentre veleggi nell'aria!"
S["9ea50e3e"] = "Il generale dell'orda è stato sconfitto!$B$BL'Alleanza è vittoriosa, e ora l'Orda si affanna a ricostruire le sue forze indebolite."
S["9eb062a4"] = "Quel goblin e il suo negozio di giocattoli li trovi nella Valley of Honor."
S["9ebb8054"] = "Beh, $Gragazzo:ragazza;, trovi Shelby Stoneflint proprio fuori dalla Thunderbrew Distillery, a Kharanos. Se hai degli animali, se ne prenderà cura come si deve."
S["9ebd5b6b"] = "Salve, $C, è gentile da parte tua farti vedere. Permettimi di essere breve: stiamo raccogliendo provviste per lo sforzo bellico di Ahn'Qiraj. Non vorremmo avere più vittime del necessario, giusto? Ho il compito di coordinare la raccolta delle mageweave bandages. Finora ne abbiamo raccolta una parte. Ti va di dare una mano?"
S["9ebe4310"] = "La terra custodisce molti segreti, $C; è nostro dovere far sì che rimangano nascosti quelli che, per il bene di tutti, devono restarlo."
S["9ec88f58"] = "Babba booey...."
S["9ecaddb2"] = "Conosco queste foreste come se fossero una parte di me... eppure sappi che hanno ancora molto da insegnare, e tanti pericoli che restano nascosti."
S["9ecb151a"] = "I Love tokens sono piccoli messaggi d'affetto da dare agli abitanti innamorati di paesi e città, che in cambio ti faranno un dono d'adorazione.$B$BOppure, se sei già $Gadorato:adorata; da qualcun altro, ti daranno almeno un dono d'amicizia."
S["9ecdc2d8"] = "Contromisure anti-fuga attivate. Autodistruzione a T meno 20 secondi...."
S["9ed57574"] = "Sì, ragazzi! Le cose stanno per mettersi davvero male."
S["9ed6bed3"] = "Dopo la caduta di Dalaran ho lasciato il Kirin Tor. Avevo passato anni a vegliare su Atiesh, e in un colpo solo il mio scopo nel Kirin Tor mi è stato strappato. Avrei ritrovato il bastone, dovesse volerci una vita intera. Così mi sono $Gunito:unita; all'Argent Dawn, ed è per questo che ora sono qui."
S["9ef30f0e"] = "Randal è un po' un damerino, ma ci si può contare, cosa che non posso dire di molti degli allievi che prendo con me. Comunque credo di non poterli biasimare se cercano un po' d'avventura."
S["9ef3bdfd"] = "Feccia Stormpike! Nel mio forte?! Uccideteli tutti!"
S["9ef715d7"] = "Prezzi migliori non li troverete da nessuna parte!"
S["9ef8890a"] = "I capitani dell'Orda e dell'Alleanza sono caduti entrambi! Sconfiggete Drek'Thar prima che sia troppo tardi!"
S["9f04a4cc"] = "Sono pronta."
S["9f083d65"] = "Prendi questo segnalatore e avanza verso la base nemica. Raggiungi l'esterno della loro roccaforte principale e piazza il segnalatore al centro del cortile. Difendi il segnalatore dagli attaccanti finché l'Occhio non avrà agganciato le sue coordinate.$B$BUna volta fatto, da qui si potrà vedere tutto ciò che accade fuori dalla base nemica.$B$BTe ne occuperai?"
S["9f0d7b67"] = "Salve! Posso insegnarti qualcosa?"
S["9f1256ea"] = "Prima di partire a caccia, è saggio farsi dire da qualcuno cosa stai cercando, prima di metterti a cercarlo."
S["9f1262a0"] = "Vandar nagan re bor far agol sturume! Aziris!"
S["9f22250d"] = "Noi viviamo e moriamo, ma la terra resta, eterna, indifferente al nostro passaggio. Per questo non può essere nostra, $N: siamo noi a essere suoi. E la proteggiamo, perché senza di lei non possiamo sperare di sopravvivere."
S["9f2767c3"] = "Lo spirito di %s è stato liberato..."
S["9f2e0cc0"] = "Muori! Muori!"
S["9f414233"] = "$GQuesto:Questa; $N è $Gimpazzito:impazzita; per la corruzione!"
S["9f4800b8"] = "$GUn altro materialista:Un'altra materialista;, eh? Beh, se sei $Gossessionato:ossessionata; dai tuoi preziosi oggetti, probabilmente vorrai depositarli alla Darnassus Bank, nel centro della nostra città."
S["9f493ea2"] = "Marshal Marris, signore. Corporal Keeshan del 12o Reggimento Sciabola è tornato dalla battaglia e si presenta in servizio!"
S["9f4b5eb2"] = "Trovi Chaw Stronghide nella grande tenda all'angolo nord-ovest del villaggio: ti insegnerà quello che per ora ti serve sapere sulla Conciatura."
S["9f4ce2cf"] = "Ascolta, $R. Ascolta bene...$B$BI cavalieri dei draghi sono arrivati nella notte, in groppa allo stormo nero. Hanno colpito rapidi, con una precisione letale, hanno portato via i cuccioli — come me — e sono fuggiti col favore delle tenebre.$B$BHo visto con orrore i miei fratelli e le mie sorelle usati per i loro esperimenti. Dalla nostra essenza sarebbe nato lo stormo cromatico."
S["9f4f394c"] = "Nella grande città di Thunder Bluff, a nord, c'è un Maestro delle Wind Rider. Ai piedi di Thunder Bluff prendi l'ascensore fino in cima, e lassù chiedi altre istruzioni a uno dei Bluffwatchers."
S["9f596b71"] = "%s ringhia ferocemente."
S["9f5c15f5"] = "Stammi vicino, $N. Ti proteggerò se qualcosa va storto."
S["9f5fa1b8"] = "Sia lodata Elune... Eranikus è redento."
S["9f65fb9f"] = "%s si riaccende grazie al calore di un altro Core Hound!"
S["9f6f189c"] = "Mi hai fatto scappare i pesci! Che vuoi?"
S["9f811f23"] = "È Eunice Burch, nel Trade Quarter."
S["9f82ff59"] = "$N conquista il cimitero di Snowfall! Se nessuno lo contrasta, l'Alleanza ne prenderà il controllo!"
S["9f8b17dd"] = "Per il Sogno, funziona..."
S["9f9114dc"] = "Il Son of Arugal che ha attaccato Lumina lo chiamano Old Fire-Eye. È famoso per la ferocia, ma anche perché si rifiuta ostinatamente di morire. Ho fatto parecchie ricerche, e credo che possiamo forgiare la lama giusta per finirlo una volta per tutte.$B$BTieni, ti ho preparato una lista dei materiali, con le informazioni su come procurarteli. Quando avrai raccolto quello che ci serve, torna da me e cominceremo."
S["9f92f68a"] = "Saluti, $R. Mi chiamo Franclorn Forgewright. Sei qui per sapere della Guglia e del Dark Iron?"
S["9f971b8c"] = "Va bbene *hic*... Ehi, la tua faccia mi è familiare *hic*. Te l'ho mai raccontata quella volta che io e Windsor abbiamo respinto tren, ehm... mille... un milione di orchi?$B$BOh, mettiti $Gcomodo:comoda;, $Gamico:amica;, che questa è bella!"
S["9f99543f"] = "Cosa ti serve? *hic*"
S["9fa887d5"] = "Eccoli che arrivano!"
S["9fa887e2"] = "Eccoli che arrivano."
S["9fb0f2bb"] = "Grazie. Che la Luce sia con voi."
S["9fb20be3"] = "%s si sveglia!"
S["9fb6be24"] = "$GUn:Un'; erborista in erba, eh? Allora dovresti fare un salto da Firodren Mooncaller, là nei Temple Gardens: magari ha qualche trucco del mestiere da insegnarti."
S["9fb72fbd"] = "Spero che tu non sia $Gvenuto:venuta; fin qui alla Great Forge solo per scaldarti. Su, parla, $Gragazzo:ragazza;: cosa posso fare per te?"
S["9fbac6dd"] = "L'Euristometro Tecnologico Punzonografico a Matrice ha rilevato la tua attitudine per l'ingegneria. Ora puoi scegliere tra le opzioni seguenti:$B$B01000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001"
S["9fbb988d"] = "Se desideri visitare l'altura del Profanatore, non hai che da chiedere. Posso trasportare te e i tuoi compagni."
S["9fc39372"] = "Qui non passano molti Scuoiatori a farsi addestrare, ma se sei $Gpronto:pronta;, credo di avere qualcosa da insegnarti."
S["9fc82f20"] = "Eccolo — il deserto di Tanaris. Buffo come un posto inospitale come questo sembri migliore di una giungla rigogliosa, dopo esserci rimasti intrappolati per un'eternità."
S["9fcdaf74"] = "%s annusa il terreno..."
S["9fd03733"] = "Quando queste terre caddero sotto l'Orda orchesca durante la First War, il grosso dell'esercito dell'Alleanza si spostò su altre preoccupazioni. Credevano la terra perduta, e che gli sforzi di guerra fossero meglio spesi sul fronte interno.$B$BSiamo d'accordo. Ma le Radure Fluviali sono la nostra casa, $N. Senza aiuto dal resto dell'esercito, i cavalieri e le amazzoni di Farholde hanno lanciato un'audace campagna per riprendere le nostre terre. Sotto il comando di Demar, sappiamo che un giorno queste terre torneranno ad appartenerci. $B$BQuesta non è solo una battaglia per il controllo, $N. Questa è una guerra per il nostro diritto di nascita."
S["9fd1bb15"] = "Sei $Gvenuto:venuta; a imparare l'arte di preparare pozioni? Se pensavi che ti avrei concesso un simile privilegio senza che te lo meritassi, ti sbagliavi. Va', e non tornare da me finché non sarai più abile."
S["9fdc396b"] = "Non lasciate niente indietro!"
S["9fdcc458"] = "Ti prendi gioco di me, ora che sono legato a questa palla di ferro e non posso difendermi?"
S["9fe5292a"] = "Come posso evocare un demone?"
S["9fe9b8f5"] = "Un momento mentre cucio tutto insieme..."
S["9fea596c"] = "Mi dispiace, ma non posso lasciarti cavalcare i miei grifoni. Dovresti andare a parlare con Gringer, se hai bisogno di un passaggio da qualche parte."
S["9feea90c"] = "Mi si continua a infilare la sabbia tra le dita dei piedi."
S["9ffd5382"] = "Per il momento quella zona è libera dall'influenza dello Scourge. Temo che sia solo questione di tempo prima che ritornino."
S["a0098d75"] = "Ciao, sorella. Cosa abbiamo qui?"
S["a00fefbd"] = "$GBenvenuto:Benvenuta; nella mia bottega; che piacere vedere $Gun altro:un'altra; $GIncantatore:Incantatrice; qui a Valanaar. Sei $Gvenuto:venuta; per una lezione, per caso?"
S["a012111b"] = "Mi serve solo... mi serve solo un altro momento, credo..."
S["a0139fe6"] = "Non morirò un'altra volta! Non per mano di gente come voi!!"
S["a014982e"] = "Incredibili, vero? Tutti questi manufatti, tutti questi resti.$B$BNon so cosa mi colpisca di più, se le loro dimensioni o le storie che si portano dietro. C'è così tanto da studiare, da imparare. E i collegamenti che possiamo fare...$B$BLo sapevi che, a quanto si dice, molte razze hanno le stesse origini degli elfi della Notte?"
S["a015da93"] = "L'istruttore di pesca lo trovi vicino allo stagno ai piedi della cascata, all'estremità est della città."
S["a019d86e"] = "Ci... ciao, $N. Scusa, mi sto riprendendo dalle ferite.$B$BQuei Scarlet Crusaders sono più duri di quanto pensassi. Ci è mancato poco che mi facessero fuori.$B$BAnche tu dovresti stare $Gattento:attenta;: mi dispiacerebbe vederti $Gcolto:colta; alla sprovvista."
S["a0219c66"] = "Sì, parlo una lingua che capisci, $R. Non siamo animali, eppure quasi tutta la tua gente ci tratta ancora come tali! Ma davanti alla tragedia che ha colpito questa terra, le nostre differenze impallidiscono. Ti prego, metti da parte i contrasti con la mia gente e ascolta la supplica di un morente.$B$BSono venuto in questa terra per rimediare a quel che potevo, e ora sarà tutto inutile, se tu non puoi aiutarmi. Con gli ultimi respiri che mi restano, ti chiedo questo aiuto."
S["a0324a54"] = "Subito, Supremo Magister!"
S["a035df58"] = "Da centinaia di anni il nome Earthshatter appartiene alla mia famiglia. Come mio padre e suo padre prima di lui, anch'io ho ereditato il diritto di creare le vesti che portano il mio nome."
S["a04b55e4"] = "%s ti sorprende a manomettere le scorte di frutta dell'accampamento e ti attacca!"
S["a05e9a43"] = "Hai urtato l'ammasso e sei $Gstato intossicato:stata intossicata; dalle spore!"
S["a065729b"] = "Prima di lasciare questo luogo, ti faccio un'ultima offerta, Lord Staghelm. Se dovesse arrivare il momento in cui dovrai entrare in questa fortezza maledetta, usa lo Scepter of the Shifting Sands sul gong sacro. La magia che tiene unita la barriera si dissolverà e gli orrori di Ahn'Qiraj si scateneranno di nuovo sul mondo."
S["a06f6c04"] = "Loro è in Magic Quarter. Tu cercali in edificio con teschio che fa paura."
S["a06ff5b0"] = "Il tuo spirito è debole, e i tuoi colpi sono ancora più deboli!"
S["a07027e3"] = "La pesca è uno sport da vecchi che non sono morti in battaglia! Va' a cercare Lumak sul lago della Valley of Honor."
S["a0714015"] = "NON LASCIARE CHE QUESTA STATUA SIA LA MIA UNICA COMPAGNIA. VIENI FUORI A GIOCARE!"
S["a0855366"] = "Una lama non è mai troppo affilata, né un'armatura troppo robusta: per questo ci sarà sempre bisogno di un incantatore di talento. Taladan è uno di loro, e può insegnarti a intrecciare come si deve gli incantamenti che migliorano armi e armatura. Lo trovi nella Craftsmen's Terrace."
S["a0990b3e"] = "Sopravvivenza"
S["a09ba024"] = "Salute, $C. Sono Field Marshal Snowfall e lo sforzo bellico, qui, lo comando io. Ci aspetta una strada in salita, $Gragazzo:ragazza;: se puoi darci una mano, fallo. E per qualsiasi domanda, chiedi pure."
S["a09df33f"] = "Non ci fermeremo finché non riusciremo a scoprire cosa è andato storto. Troveremo la forza di cui abbiamo bisogno per richiamare a noi gli spiriti."
S["a09fa3ba"] = "Pronti. Partenza. VIA!"
S["a0a5580f"] = "Nessuna pietà!"
S["a0a96d58"] = "Muori! Non libererai Myzrael!"
S["a0a9ce6c"] = "%s accoglie la tua riverenza e poi ti congeda con un gesto sbrigativo della mano."
S["a0abe29f"] = "Ma ora, molti anni dopo, i silvagufi sono diventati più selvatici, e senza la guida della dea sono confusi..."
S["a0ad6953"] = "Ti addestrerei, se potessi, ma ti ci vuole qualcuno un po' più... come si dice? Sveglio! Cerca Trixie Quickswitch a Ironforge e dille che ti manda Bronk!"
S["a0ad6a49"] = "Signora, dite a Plugger che voglio altra della sua birra. Non mi basta mai!"
S["a0ae9de7"] = "La Madre Terra provvede, ma a volte $Gun:una; $C ha bisogno di un piccolo aiuto in più per sopravvivere. Per questo sto raccogliendo tutte le bende di runecloth che riusciamo a trovare, in preparazione della guerra che incombe ad Ahn'Qiraj. Finora ne abbiamo raccolte una parte, sulla strada per arrivare al totale che ci serve."
S["a0bbb354"] = "Bene, $N, il tuo transponder è pronto!"
S["a0c4cd29"] = "Ucciso Ouro, la via per la camera finale è libera. Se vuoi, posso portarti lì."
S["a0c52d30"] = "Far thor A garde ador lon... noth."
S["a0c82f83"] = "Venite da me, figli miei!"
S["a0dac3c9"] = "Salve, $C."
S["a0dac51e"] = "Salve, $N."
S["a0dd64b1"] = "Basta!"
S["a0e88c7e"] = "Oh, grazie, tesoro mio."
S["a0e95cb1"] = "Ah, non c'è tessuto migliore di questo Darnassian!"
S["a0ec0902"] = "%s soffia via il fumo dalla canna del suo fucile."
S["a0f2e79b"] = "E grazie anche a te, $N. Senza il tuo aiuto forse non avrei mai trovato la strada per i Forsaken."
S["a0f8e55d"] = "%s getta le parti di animale nel calderone che ribolle."
S["a0fbec4e"] = "Che campo di battaglia ti interessa?"
S["a108e412"] = "Non hai davvero vissuto finché non hai scavato in profondità nella terra."
S["a121416d"] = "La mia cassa è costruita con ingegno: per aprirla servono due chiavi, una d'oro e una d'argento. La prima, quella d'argento, l'ho affidata al mio primo ufficiale, mentre quella d'oro l'ho tenuta io.$B$BMa era destino che le perdessimo. La mia è sparita durante l'attacco successivo dei naga, quella del mio primo ufficiale il giorno dopo, quando i makrura schioccasecco ci hanno assaliti e l'hanno trascinato negli abissi.$B$BSono $Gsicuro:sicura; che le chiavi ce le hanno i naga e i makrura. E sono $Gcontento:contenta; che siano nemici: così non se le divideranno."
S["a127f18c"] = "Io sono Gath'Ilzogg! E tu sei $Gun:una; $R sull'orlo della morte!"
S["a128a1e1"] = "Un grande male si sta risvegliando, $R. Lo senti?$B$BBah! Certo che no. Dammi armatura e armi, e ridarò loro vigore."
S["a12f1a05"] = "Signora $N! Master Kang ha chiesto di te! Forse è giunto il tuo momento!"
S["a13cdb60"] = "Il mio scettro... Dopo tanti anni... L'hai recuperato! Sarai davvero $Gil salvatore:la salvatrice; di questo luogo...$B$BAscoltami bene, $N, ti prego. Solo alla Pietra di Maraudon si possono riunire la testa e l'asta dello scettro."
S["a141ad8b"] = "Che i giochi abbiano inizio!"
S["a1427891"] = "Bene, soldati, riposo!"
S["a14a46c0"] = "La tua forza è quella della montagna. La tua grazia è quella dei venti!"
S["a150b4ed"] = "Flagello avvistato qui vicino!"
S["a15444c7"] = "Il vincitore della gara di accelerazione è... la squadra degli gnomi! Ottimo lavoro, ragazzi!"
S["a163a379"] = "Ciao! Togli qui i tuoi effetti della resurrezione!"
S["a164b63a"] = "Gli scheletri hanno superato la Sala delle Luci! Distruggeteli!"
S["a16de103"] = "Bah, non è qui. Chissà dove l'ho lasciato l'ultima volta..."
S["a178766a"] = "Mi hanno dato dello stupido, ma gliela faccio vedere io. Guarderò tutte le pentole che ho e dimostrerò che bollono lo stesso. Sì, sto andando alla grande! Chi è lo stupido adesso, eh? Eh!?"
S["a17b30f5"] = "Emperor Thaurissan non desidera essere disturbato! Tornate indietro ora o affrontate la vostra fine, deboli mortali!"
S["a18ac75b"] = "Fermati! $GSciocco:Sciocca; $C, non possiamo lasciarti evocare la creatura Myzrael!"
S["a18af43f"] = "%s viene avvolto completamente dalle fiamme e uno sguardo folle gli compare negli occhi!"
S["a18d740e"] = "Ehi, mon! Sei mai $Gstato:stata; giù in fondo all'oceano a fare immersioni? Ti svelo un piccolo segreto, eh: laggiù ci sono delle fessure piene di bolle che ti fanno respirare anche sott'acqua. Però 'sto segreto resta fra me e te, eh. Io non mi serve nessuna concorrenza da altre parti per le mie trappole per molluschi... se capisci cosa intendo!"
S["a19407ad"] = "L'Orda è pronta, ora che abbiamo finito di raccogliere tutte le nostre risorse. Aspettiamo solo che la lenta Alleanza finisca con le sue, e poi via alla gloriosa battaglia!"
S["a1958de2"] = "<Il trampoliere picchietta gli artigli sul terreno umido.>"
S["a1978329"] = "Un tempo questa gemma permetteva di comunicare direttamente con Elune in persona."
S["a198e724"] = "Questo sì che si chiama puntare lo zoccolo!"
S["a19ff24b"] = "Il Maestro delle Wind Rider lo trovi a Orgrimmar. Prendi la strada verso nord e, per altre indicazioni, chiedi a un Orgrimmar Grunt."
S["a1a07940"] = "ZZzzzz...."
S["a1a44722"] = "Lurido drago! Guardie! Guardie! Prendete questo mostro!"
S["a1a68daf"] = "Ringo? Svegliati! Non preoccuparti, mi prenderò cura di te."
S["a1a95dee"] = "Siete un'ispirazione per tutti noi, signore."
S["a1ae6a27"] = "La stalla è vuota! Dobbiamo fornire alla nostra cavalleria delle cavalcature adatte. Le Scuderie Stormpike richiedono il tuo aiuto!"
S["a1c2d9aa"] = "Beh, $Gragazzo:ragazza;, trovi Shelby Stoneflint proprio fuori dalla Thunderbrew Distillery, a Kharanos. Si prenderà ben cura di qualunque animale tu abbia."
S["a1cbef3c"] = "Il diario di Jandice Barov è pieno di sproloqui e deliri sui non morti, ma verso la fine c'è quello che sembra un modello di sartoria per una borsa di felcloth, quella che gli stregoni usano per conservare i soul shards. Sai già come crearla."
S["a1cc19a9"] = "Vittoria per l'Orda!"
S["a1da3d4e"] = "ORA è il tempo dei Forsaken! Potere ai Forsaken — ORA E PER SEMPRE!!!"
S["a1dd415a"] = "In cambio di un Sulfuron Ingot sono $Gautorizzato:autorizzata; a darti una copia degli schemi per forgiare un martello Sulfuron.$B$BOra, $Gun avventuriero:un'avventuriera; come te starà pensando tra sé e sé: \"Che me ne faccio di un martello del genere, se quello che ho già è di gran lunga superiore?\"$B$BBeh, lascia che ti dica una cosa, $Gcaro mio:cara mia;: non c'è niente di più superiore di quello che può diventare il martello Sulfuron!"
S["a1e124d0"] = "Salve, $N. Portami le pietre necrotiche degli invasori non morti e potrò darti accesso alle scorte dell'Argent Dawn."
S["a1f5a957"] = "%s sembra stanco. Poi sbadiglia e si sdraia accanto ad A-Me 01"
S["a1f7011b"] = "A Elder Mistwalker piace guardare le lotte a The Maul, a Feralas."
S["a1f7fe08"] = "Impara qual è il tuo posto, mortale!"
S["a1fcd75d"] = "Il fendicieli che attracca qui ti porterà dritto alla Dalaran City."
S["a1fdfd9d"] = "ssSSMELME!! Rrraagh..."
S["a1ff18c0"] = "Vorrei che tu potessi semplicemente prendermi in braccio e portarmi, $N."
S["a20e0f6a"] = "Hai sentito che fine ha fatto Ban'aethal? Le peacekeepers avvertono la gente di stare lontana dalle rovine e da tutta la Shadowgale Forest.$B$BAlla locanda ho sentito per caso qualcuno raccontare di aver visto spiriti del vento malevoli che sembravano poco più che sagome indistinte, come se fossero... svuotati, in qualche modo.$B$BSolo a pensarci mi vengono i brividi."
S["a216592b"] = "Mmm, potrebbe essere quel ficcanaso di Shaw. Vedrò cosa riesco a scoprire. Ora vattene. Ti contatterò di nuovo presto."
S["a219ce0a"] = "Mi spiace, mon, ma i miei raptors non li vendo a chi non ha dimostrato di essere osannato presso la tribù Darkspear. Quando ti farai valere e ci farai vedere che sei almeno $Gosannato:osannata; presso di noi, allora i miei raptors saranno a tua disposizione."
S["a21d82ed"] = "Lo thor lo novaedi lars O nuff a hir veld ruftvess ko va."
S["a224ddd4"] = "Finalmente l'agonia finisce...."
S["a229ef76"] = "Salve! Posso insegnarti a trasformare le pelli delle bestie in armature?"
S["a22ef02a"] = "Hai imparato bene, $Gfiglio mio:figlia mia;. Va' a Undercity e cerca un fabbro di nome James Van Brunt. Lui potrà insegnarti molte cose che io non posso. Da quanto so, passa le giornate vicino alla sala d'addestramento dei Guerrieri, a forgiare armi e armature per loro."
S["a23a1932"] = "The Ashbringer è morto e non ce ne sarà mai un altro come lui. Il Mograine minore è ben lontano dall'uomo che era suo padre. Lo sai bene, Comandante! Dopotutto, è stata proprio la tua guida a causare la morte dello Scarlet Highlord Mograine."
S["a23b9a83"] = "Drek'Thar è il capo militare e spirituale del Frostwolf Clan ad Alterac, e guida i suoi fratelli dalla Frostwolf Keep.$B$BSe verrà sconfitto, le forze dell'Orda ad Alterac crolleranno.$B$BDrek'Thar al momento non si trova nell'Alterac Valley."
S["a23c478e"] = "TEST — morte prima dell'attacco $N"
S["a23d70a6"] = "Aiutami con questo, $N!"
S["a244de3c"] = "Notate la debole struttura dei legami di questo. Assicuratevi di completare le formule, o vi ritroverete con questo."
S["a2469cad"] = "Tu hai i soldi, noi il cibo. Che aspetti?!"
S["a24a6f3c"] = "La West Frostwolf Tower protegge il cancello tra il Frostwolf Village e la Frostwolf Keep.$B$BÈ controllata dall'Orda."
S["a250a290"] = "Grazie per essere passat$Go:a; da me, $C. Ora abbiamo tutti i lingotti di torio che ci servono, ma forse vorrai chiedere ad alcuni degli altri qui, che si occupano di altre raccolte."
S["a26ea91c"] = "Credo di poter tornare alla Roccaforte da solo. Ora che mi hai fatto guadagnare un po' di tempo, dovrei riuscire a sgattaiolare fuori di qui senza farmi vedere. Chiunque tu sia... grazie. Che Elune ti benedica sempre!"
S["a2778505"] = "Le notizie da Stormwind non promettono niente di buono..."
S["a2799038"] = "In tutta Thunder Bluff non c'è cuoca migliore di Aska Mistrunner. Mmmmm, sento fin da qui il profumo di quello che sta cucinando. Vai alla sua cucina, sull'altura superiore.$B$BAccidenti... adesso mi è venuta fame."
S["a279ef9a"] = "È già sorto il sole? Le ore della notte non bastano mai! Beh, di te si prenderà cura Saelienne: la trovi nella Craftsmen's Terrace, nella parte nordorientale di Darnassus, che si occupa dei suoi ospiti."
S["a28470bd"] = "Sei $Gsicuro:sicura; di non voler imparare a fare il guerriero? Be', sul campo di battaglia la pelle che rischi è la tua. Se proprio vuoi imparare ad agitare il dito, faresti meglio a parlare con Magis Sparkmantle, alla Thunderbrew Distillery."
S["a28e7631"] = "Aiuto! Aiuto! Assassini sulle colline! All'armi! All'armi!"
S["a2a1e7f4"] = "%s viene evocato attraverso una frattura temporale!"
S["a2a4aa29"] = "La Fratellanza non si farà ostacolare da degli insetti."
S["a2a76b1f"] = "<Mentre ti avvicini all'enorme costrutto ciclonico, da sotto le massicce piastre corazzate ti arriva un debole ronzio. Se tendi l'orecchio, ti sembra che qualche parola prenda forma, ma è troppo distorta per capirla.>"
S["a2aadd2c"] = "Avanti! Le prime linee ci attendono!"
S["a2ac8580"] = "Che ti serve, $C? Spero che in questa terra desolata tu sia $Gvenuto:venuta; per qualcosa di più che fare quattro chiacchiere."
S["a2af2b1c"] = "%s esamina l'antica statuetta."
S["a2bc5bb6"] = "Vieni pure a parlarmi quando vuoi, $N, te ne prego. Hai servito bene Magatha, e sono certo che in futuro si rivolgerà a te."
S["a2c5ee9c"] = "Affrontami, se ne hai il coraggio!"
S["a2c8012d"] = "$GUscito:Uscita; dal Combattimento"
S["a2cc9625"] = "Per la Grande Madre!"
S["a2cd96f3"] = "Allora devi parlare con Taim Ragetotem. Lo trovi sull'Hunter Rise."
S["a2cf0a7b"] = "Che vuol dire \"zug zug\"?"
S["a2d065de"] = "Salute, $C. Mi trovi un po' in difficoltà: sono rimasto quasi senza pelli."
S["a2d3b187"] = "Ok, $Gfratello:sorella;, adesso pe' 'l sapta... statti vicino a me."
S["a2d659a0"] = "I miei carcerieri erano crudeli oltre ogni misura, $N. Torturavano a turno me e Lieutenant Kirith, e intanto l'altro stava a guardare. Un giorno particolarmente brutale, durante una pausa, Kirith mi ha raccontato che fine avevano fatto i miei uomini, e mi ha parlato di un piano che stava preparando per liberarli dai loro padroni.$B$BLa loro sorte è stata di gran lunga peggiore della morte, peggiore persino del dolore che io e Kirith abbiamo sopportato."
S["a2d7737b"] = "%s ruggisce chiamando il suo compagno!"
S["a2dc7db3"] = "Cerca di non dare troppo nell'occhio, sto aspettando che il Re mi riceva in udienza. Non che l'attesa mi pesi: in mezzo a tutte queste guardie nerborute mi sento piuttosto al sicuro."
S["a2e17509"] = "Mi sembri un po' $Gsperduto:sperduta;. Posso aiutarti a trovare qualcosa?"
S["a2efaa5b"] = "Sento un grande potere fra noi, Comandante. L'incantesimo è pronto?"
S["a2f15f84"] = "A non sapere come stanno le cose, direi che a organizzare questa festa sono stati gli orchi!"
S["a2f92ad8"] = "Grim Batol sarà di nuovo nostra!"
S["a3083ef8"] = "Tu! $R! Vieni qui. <sbuffo>$B$BResta poco tempo, e la mia fine <sbuffo> è vicina. Mangletooth vincerà, vedrai. <sbuffo>$B$BLa mia cattura può ancora tornare utile <sbuffo> al mio popolo. La tribù Razormane è più potente dei Bristlebacks!$B$BL'Orda cerca di scoprire chi guida le incursioni contro la sua gente. Tu <sbuffo> aiuterai Mangletooth, e in cambio avrai le informazioni che conosco solo io. Mangletooth può aiutarti! <sbuffo> Ma tu devi aiutare Mangletooth."
S["a3189f53"] = "%s alza la mano e poi la abbassa."
S["a3192f94"] = "La vostra vittoria durerà poco. I giorni dell'Alleanza e dell'Orda stanno per finire! La prossima volta che ci incontreremo sarà l'ultima."
S["a320366b"] = "Hai fatto un ottimo lavoro, Spybot! Sono contento di riaverti qui con me!"
S["a326395d"] = "C'è una cassetta della posta proprio là, vicino a The Stonefire Tavern, appena a nord dei cancelli di Ironforge."
S["a32db07a"] = "Hai combattuto con coraggio, Narrisha. La prossima volta vi battiamo, Squadra Rossa!"
S["a331baab"] = "Personalmente non mi dava fastidio. È stato il Principe a non tollerare un alto elfo nel suo dominio. Ahimè, non sono io a mettere in discussione il Principe. A sua discolpa, non ha incenerito subito Master Winthalus."
S["a339861b"] = "Certamente, $N. Dimmi solo quale reputazione ti interessa conoscere."
S["a34b55c7"] = "Non è un lavoro per deboli di cuore: un mio zio ci ha rimesso una mano! Povero vecchio Stumpy... ma se ti interessa ancora, forse un paio di cose posso mostrartele."
S["a34ff167"] = "Aspetta un attimo, io son solo un assistente. Se vuoi metterti a imparare la roba fina, vai a parlare col vecchio Stonebrew, laggiù."
S["a355a12e"] = "No! No, no, no! Non può essere. Meglio morta che Forsaken! $B$B<La Frightened Paladin alza l'arma, pronta ad attaccare!>"
S["a359184b"] = "In questo luogo, l'oscurità e le ombre sono strumenti da usare e gettare via a piacimento."
S["a35b5ee0"] = "Graham Van Talen, in Rogues' Quarter, sull'anello esterno di Undercity."
S["a367d923"] = "Turno di guardia, odio i turni di guardia."
S["a36e8633"] = "Ehi, che succede laggiù? Signore, sta bene? Signore??"
S["a3703ebb"] = "Temo che tu debba addestrarti ancora, prima che io possa insegnarti quello che so."
S["a372ca28"] = "Non può essere vero. A un Old God non si potrebbe mai permettere di entrare in questo mondo. Le conseguenze sarebbero... Oh, cielo!"
S["a373c31b"] = "Chi controlla l'East Frostwolf Tower?"
S["a376d1d9"] = "La tua morte non sarà stata vana, Taelan. Oggi nasce un nuovo Ordine... un Ordine che si dedicherà a estirpare il male che affligge questo mondo. Un male che non può nascondersi dietro la politica e le buone maniere."
S["a37c5e46"] = "È proprio così, Leonid. Mi è piaciuta la nostra corrispondenza, ma mi fa piacere che tu sia finalmente venuto di persona fino a Bandarion Keep."
S["a3921b44"] = "Poco dopo cominciammo ad avere visioni di una creatura... Una creatura con le piume di un gufo, ma con la volontà e la forza di un orso..."
S["a395b71f"] = "A un Tauren non posso insegnare a cavalcare un Raptor."
S["a39b6c4f"] = "Vorrei inserire il codice segreto per ricevere la mia mascotte Murloc."
S["a39e8aa2"] = "Il dolore di chi si vede strappare l'anima dal corpo, né tu né io potremmo mai immaginarlo. Non sono morti, ma vivi di certo non lo sono: vagano per queste terre, servi di chi li lega a questo mondo.$B$BLord Razelikh, il signore demoniaco di queste terre, li ha resi tutti schiavi. Nove li ha presi per sé e ha messo delle pietre di vincolo vicino al Dark Portal; gli altri nove li ha spartiti fra i suoi sottoposti."
S["a3ac2795"] = "Mi aggrapperò all'amore di mia figlia e spero di trovare perdono nella Luce per i miei peccati."
S["a3b95ea9"] = "L'offerta è pronta. Ora comincia il rituale."
S["a3baccbd"] = "Aiuto! $N sta attaccando!"
S["a3bb9e5e"] = "%s cucina una porzione di ali di poiana piccanti per $N."
S["a3be9925"] = "Eh sì, qualcosina la sai! Per imparare di più, però, devi andare a parlare con Georgio Bolero a Stormwind."
S["a3c4d0d9"] = "%s prepara una pozione per $N."
S["a3c668ac"] = "Ti distruggerò..."
S["a3c90b83"] = "Ah, davvero? <PH>"
S["a3cc77a8"] = "Se decidi di seguirmi, stai in guardia. Gli animali e le bestie della Darkshore non faranno del male a me, ma potrebbero cercare di farne a te, $Gavventuriero:avventuriera;."
S["a3cf19ef"] = "Che succede?"
S["a3d00be5"] = "La colpa è del dio che avevano evocato i troll Atal'ai. Abbiamo distrutto la sua manifestazione fisica e fatto sprofondare il tempio, ma il dio era molto più forte di quanto avessimo previsto persino noi: il seme della sua corruzione aveva messo radici profonde e distorceva tutto quello che incontrava.$B$BEranikus doveva vegliare sul tempio sommerso, perché non risorgessero né i semplici Atal'ai né il loro dio. È caduto vittima di questa corruzione senza saperlo, e lo siamo stati anche noi, che ne abbiamo sottovalutato la forza."
S["a3d02282"] = "I conciatori abbastanza bravi, per esempio, possono piazzare una tenda come questa che ho alle spalle."
S["a3d5a4ad"] = "Sì che sanno far festa, quelli di Nighthaven!"
S["a3de87e1"] = "Ishnu-alah, fratello. Rechi nuove da terre lontane? Il mio cuore brama notizie di Teldrassil."
S["a3e12ede"] = "Noi paladini dobbiamo guadagnarci ogni giorno il nostro posto fra gli altri Forsaken, perché non ci giudichino fanatici come la Scarlet Crusade. La luce non è solo uno strumento in mano ai nostri nemici: è un canale per la nostra giusta furia! È la devozione alla Dama Oscura, insieme all'amore per la nostra casa, a permetterci di incanalare la luce e di fare giustizia degli avversari.$B$BThe Banshee Queen ci tiene d'occhio. E lo faccia pure: vedrà che la nostra determinazione non vacillerà mai. Siamo Forsaken!"
S["a3fd8ec3"] = "Mm, quassù niente."
S["a40a1549"] = "Non voglio guai, Komak."
S["a4116fab"] = "È tutto completato, giovane $C. Proprio ora sia l'Orda sia l'Alleanza stanno trasportando gli ultimi beni per la guerra a Silithus, vicino alla Cenarion Hold: dovrebbe essere tutto finito in meno di un giorno. Dopo di che si potrà suonare il gong vicino alle porte di Ahn'Qiraj, e la guerra comincerà."
S["a419be91"] = "Quelli come te non li addestro, $C."
S["a41b136d"] = "Dall'interno della pietra si può sentire un sussurro...$B$BSaluti, $Gpiccolo:piccola;. Porti notizie per il Templare?"
S["a41f907b"] = "La speranza è una MALATTIA dell'anima! Questa terra appassirà e morirà!"
S["a42eb167"] = "Capo, tu fregato me proprio bene! Come fatto tu a passare davanti a Slip'kik?? Ma io furbo: prossima volta io sta attento! Har har!$B$BNessuno non passa più davanti a Slip'kik. Slip'kik promette!"
S["a42fd83c"] = "Ma una cosa la so: l'amore rende deboli il cuore e il corpo. Si può sfruttare. Senza il tuo amore, ho solo il mio lavoro, Annalise."
S["a435a9ed"] = "Che cosa posso fare per te, $Gfigliolo mio:figliola mia;?"
S["a435cf13"] = "Mi hai tenuto in quella cella troppo a lungo, mostro!"
S["a43731d5"] = "Liberami!"
S["a43f18c8"] = "La minatrice migliore tiene ben saldo il piccone, ha un cuore forte nel petto e i capelli coperti da uno spesso strato di polvere nera."
S["a43f654a"] = "Ogni anno, in questo periodo, vengo a Silithus. Per i miei calli il clima è fenomenale.$B$BDovresti venire a fare una passeggiata con me, $Gamico:amica;, e goderti il panorama e quant'altro."
S["a4413b2f"] = "Non ho quasi più provviste per i potenziamenti."
S["a4436cce"] = "I giorni passati qui ad Azshara non sono fra i migliori e i più gloriosi che abbiamo vissuto, ma siamo ancora giovani e il sangue ci scorre nelle vene — qui vinceremo. È solo questione di tempo."
S["a44e1a7a"] = "È un onore rivederti, $N."
S["a450c440"] = "Bene, adesso basta. A parte l'ovvia distrazione che un servitore del genere provoca negli avversari più virili, è anche capace di infliggere danni notevoli. Però la sua fragile resistenza la rende quasi inutile come scudo."
S["a4531d47"] = "Caro ragazzo, sei arrivato proprio al momento giusto per dare una mano alla Kargath Expeditionary Force."
S["a4542425"] = "Lo giuro, c'è gente che li ha visti davvero. I Pandaren esistono!"
S["a456238b"] = "Libertà!"
S["a45873a6"] = "Di magia ne so poco, ma alla Lion's Pride Inn alloggia un mago che si chiama Zaldimar: probabilmente lui può aiutarti."
S["a45931a0"] = "Il mio tormento è finito e ora posso raggiungere la Dea. Grazie davvero!"
S["a45a9068"] = "State pronti! I naga non aspetteranno a lungo per approfittarne, appena sapranno che siamo vivi."
S["a45cee59"] = "Tu cerca Archibald. Lui fuori negozio di mercante d'armi, su anello interno di War Quarter."
S["a46289a8"] = "Il nostro lavoro è finito. Ora aspettiamo che l'Alleanza finisca il suo prima di spedire tutto a Silithus."
S["a46353e1"] = "Eroi della Stirpe? C'Thun va scacciato! Possiamo aiutarti, mortale!"
S["a466e3fc"] = "Antiche forze si risvegliano — forze che da migliaia di anni nessuno vede né sente. Il mondo piange, $R. Forse si avvicina una nuova frattura. Un morbo nato da dentro...$B$BIl marciume ha cominciato a insinuarsi nelle nostre terre. Dal Sogno arrivano gli incubi. Incubi che ci insozzano anche da svegli..."
S["a46e11ff"] = "Grazie, Jessica."
S["a47a4495"] = "Che le Deadmines siano la tua tomba, $N!"
S["a47cdfdb"] = "Tenete la linea! Proteggete il Re a ogni costo!"
S["a4866f12"] = "Ora dimostra quanto vali!"
S["a49a15bd"] = "Ne hai fatta di strada... ormai mi hai superato! Dovresti andare a parlare con Springspindle Fizzlegear a Ironforge! (Lui? Lei?) ti mostrerà molto più di quanto potrei mai fare io!"
S["a49a8746"] = "Desidero imparare l'alchimia, Serge."
S["a4a15c77"] = "Accidenti! $N, questa polvere dei sogni è roba potente!"
S["a4a1cd28"] = "Perdonami, Lordaeron..."
S["a4a40757"] = "Dicci solo quello che sai della Shady Rest Inn, e non ti spacco il cranio."
S["a4a45c98"] = "Ben fatto, miei servitori. Il coraggio dei mortali comincia a vacillare! Ora vediamo come se la cavano con il vero Signore di Blackrock Spire!!!"
S["a4a899a7"] = "Karnik, amico mio, vorrei poterti rivedere coi miei occhi, ma dobbiamo parlare di Ragnaros. La sua influenza si sta diffondendo."
S["a4d2c752"] = "Grazie per essere la mia prossima vittima!"
S["a4d4bdbd"] = "|cffff0000Tutte e quattro le torri sono ora sotto il controllo dell'Orda!|r"
S["a4dfa6ef"] = "$N, sotto il muschio questo cuore sembra un seme!"
S["a4e9b55c"] = "%s comincia a creare una copia di se stesso!"
S["a4e9b81b"] = "Dentro la scatola, bellezze mie! Ecco, così. Uno alla volta, su."
S["a4ecc739"] = "Salute, nobile $C. Su di te e sui tuoi questa umile serva del Cenarion Circle invoca benedizioni e abbondanza."
S["a4f1f85f"] = "Benvenuta, sorella mia. Se sei qui per imparare, sarò lieto di addestrarti.$B$BCorrono voci di discordie nel Cenarion Circle, ma non dovresti dare retta a queste chiacchiere. Il nostro Arcidruido, Fandral Staghelm, guida noi e tutta Teldrassil verso la gloria!"
S["a502d2d0"] = "Buona parte dei cultisti del Sanctum of Storms sembra uscita per rispondere al nostro attacco. Non mi sarei mai aspettata che andasse così bene. È stato quasi troppo facile...$B$BCredo che l'assalto l'abbiano sferrato i Windshapers e l'High Order, e Valennia dovrebbe essere con loro. Dovresti entrare a cercarla. Noi restiamo qui di guardia mentre Valennia e gli altri finiscono quello per cui sono venuti."
S["a5105666"] = "Ecco la mia domanda, $C:$BQuale degli Aspetti creati dai titani è diventato la creatura malvagia conosciuta come Deathwing?"
S["a511d416"] = "Ehi, di' al tuo amico Tongus che se non salda il conto, mi farò vedere col vecchio Steelhead!"
S["a511f0de"] = "Dammi il cucciolo di tigre!"
S["a51b80f5"] = "Ho visto la via. Dobbiamo tornare a Kalimdor, consultarci con quest'Earthen Ring. Ci aiuteranno a padroneggiare la vista celeste affinché possiamo richiamare a casa i nostri patroni elementali."
S["a523e344"] = "Guse? Jeztor? Sono... in avvitamento?? Mari di Southshore??"
S["a526c347"] = "Questo è un lavoro eccellente. Sei $Gpronto:pronta; a intraprendere una missione per conto mio? Non conosco nessuno più qualificato."
S["a534541e"] = "Di nuovo questi tre?"
S["a53bce40"] = "Cerca Kaplak in cima alla tana, nella parte sudoccidentale della città."
S["a53c190d"] = "Hai visto Watcher Backus? Che coraggio che ha...$B$BPer me, in tutta la Night Watch non c'è nessuno più tosto di lui. Chissà se almeno si accorge che ci sono...."
S["a53d7091"] = "Chi osa risvegliare Archaedas? Chi osa sfidare l'ira dei Creatori?"
S["a53e154f"] = "Silas, perché quasi tutto alla fiera è gratis? Come fate a guadagnarci?"
S["a542ec11"] = "Guardami le spalle! Vedo cosa riesco a trovare in tutta questa robaccia..."
S["a5442f7e"] = "Sì, dev'essere Austil de Mon. Se ne sta sempre nella taverna in fondo alla città, verso sud-est: la Gallows' End Tavern. Non puoi sbagliarti."
S["a548187b"] = "Gli arieti nativi di Alterac sono indispensabili per far funzionare la nostra cavalleria!"
S["a54fb259"] = "%s fa un cenno con la testa verso $N e sospira pensieroso."
S["a55583ad"] = "Grazie, $Gragazzo:ragazza;. Grazie infinite."
S["a55837fc"] = "Elder Moonstrike la trovi nella Scholomance, nelle Western Plaguelands."
S["a559eaa8"] = "Tira, segna!"
S["a56a7724"] = "L'Horde Embassy è nella Valley of Strength, sul lato ovest."
S["a57e44ec"] = "$GUn altro imprenditore:Un'altra imprenditrice;, eh? Be', l'Auction House è nel Trade District. Non lontano dalla banca."
S["a5879ebe"] = "Buona fortuna, $N. E ricorda, trova Muiredon quando avrai portato a termine il compito."
S["a589067b"] = "Nella mia goffa ricerca attraverso i piani in cerca di segni dei nostri benefattori elementali, mi sono imbattuto in loro..."
S["a58b59d1"] = "Chi va là?"
S["a590b33b"] = "La banca più vicina che trovi è The Vault, a Ironforge, $Gragazzo:ragazza;."
S["a5931285"] = "Lok'tar, $C! Ci servono i tuoi servigi nell'Alterac Valley. Vuoi che ti iscriva?"
S["a59cb95d"] = "Arrivare fin qui non è stato facile, lo so. Ma quanto sarebbe noiosa la vita senza sfide, non credi? Bene, perché ho una sfida per te..."
S["a5a55ce8"] = "%s si libera dal suo sonno di pietra!"
S["a5a70a15"] = "Stanno arrivando altri Grimtotem da questa parte!"
S["a5a73906"] = "Ecco, lascia che ti mostri come fasciare quelle ferite..."
S["a5a89449"] = "Salve di nuovo, $N. Sento che forze davvero potenti minacciano ancora il flusso del tempo. Lo stormo bronzeo apprezza sempre il tuo aiuto costante.$B$BIl passato è immutabile, ma il futuro cambia di continuo, e le decisioni che prendi qui e ora aiutano a guidare quel cambiamento."
S["a5b7a0d4"] = "Da questo molo puoi imbarcarti per Theramore. Dammi retta: per la gente dell'Alleanza quelle terre sono di rado sicure. Bada a dove metti i piedi e guardati le spalle."
S["a5b9e0ca"] = "Offro ali a chi ne ha bisogno, per scendere in sicurezza."
S["a5bb4fdb"] = "Così funzionerà — continua ad avanzare attraverso questo varco. Il sentiero per Un'Goro è dritto a ovest da qui, una volta aggirati questi insetti infernali."
S["a5bc5827"] = "The Scarlet Crusade sta invadendo la nostra patria. Quegli sciocchi fanatici non capiscono che a farla finita con loro ci penseranno i leali servitori della Dama Oscura."
S["a5bfde05"] = "Atten-ti! Tutto il materiale bellico per Ahn'Qiraj è registrato e in corso di trasporto alla Cenarion Hold, $Gsignore:signora;! Mi dicono che l'ultimo carico dovrebbe arrivare in meno di un giorno. Una volta fatto, e quando qualcuno suonerà quel gong laggiù per aprire le porte, garantisco che daremo a quegli insetti una battaglia coi fiocchi!"
S["a5c0dd2e"] = "Aiuto!$B$BSe mi tiri fuori di qui, posso far saltare la porta che porta al capo di Zul'Farrak!"
S["a5c453f8"] = "I tempi sono cambiati. Le giovani razze si uniranno a noi. Non ci riuscirete mai."
S["a5d6a97e"] = "%s ha una visione orribile. Qualcosa si muove sotto le acque torbide."
S["a5e1a6ac"] = "Boh. Tu cosa vuoi fare?"
S["a5eb3191"] = "Vediamo se i pesci abboccano."
S["a5edc669"] = "Scappa su colline! Aspetta! Noi già su colline!"
S["a5f5a5f1"] = "La cassetta di sicurezza del SI:7 si apre, facendo scattare un allarme ben udibile."
S["a5f73d51"] = "Quanti dei nostri Comandanti sono vivi, Vanndar?"
S["a5fea50e"] = "Hai l'aria di esserti $Gperso:persa;."
S["a5ffdaa0"] = "Cercare di saperne di più sulla mia situazione è stato quasi impossibile. Il contrabbandiere che ci ha ingaggiati è scomparso e Anthion Harmon, il capo della nostra compagnia di mercenari, è morto."
S["a60f96f0"] = "Non abbocca niente..."
S["a61b2cf9"] = "Finalmente sono libera dal Soulflayer!"
S["a6200607"] = "The Scarlet Crusade non fallirà la missione!"
S["a62376c4"] = "Che vengano pure! Non ho paura di quattro bestiacce rinsecchite!"
S["a62e927e"] = "%s inizia a frugare nelle sue borse in cerca del componente giusto per l'incantesimo."
S["a6373073"] = "Starai cercando Smith Argus. Se ti serve addestramento, di solito sorveglia la forgia di Goldshire."
S["a658ef82"] = "Vanno tutti ai Bastioni, ma nessuno torna mai... proprio come Bijou."
S["a6604c37"] = "Prima o poi parlerai. Tanto vale che lo sputi fuori adesso."
S["a660bbc4"] = "Se ti serve lasciare in custodia il tuo famiglio mentre ne addestri un altro, ti conviene parlare con Jenova Stoneshield, laggiù nel Dwarven District."
S["a66276b6"] = "%s viene $Gattirato:attirata; allo scoperto!"
S["a662ef05"] = "Ecco! Ha funzionato!"
S["a66c88e4"] = "...in padella, fritto e saltato..."
S["a6725cae"] = "Ah, $Gun collega stregone:una collega stregona; che ha dimostrato almeno in parte il suo valore.$B$BLieta di conoscerti. Mi chiamo Menara Voidrender... e non per niente.$B$BMi sembri abbastanza $Gpotente e istruito:potente e istruita; perché altri strumenti... strumenti più potenti... siano bene accetti nelle tue mani e non affidati a sproposito. Se è così, parliamone. Altrimenti, beh, la strada per tornare al molo e prendere il largo la conosci."
S["a673654f"] = "Sì, è da un po' che mando avanti questo negozio. Ultimamente gli affari vanno piuttosto bene. Passano tanti avventurieri nuovi..."
S["a675cbdc"] = "%s prende la mira verso le bottiglie..."
S["a69eba36"] = "Vedo ladri ovunque guardi. Noi della Milizia del Popolo dobbiamo restituire questa terra ai contadini."
S["a6a0619d"] = "Mmh, non ho rivestimenti di mithril. Li ho finiti. È tutto quello che ti serve per riparare A-Me? Oh, sarebbe fantastico!$B$BGli involucri di mithril non sono troppo difficili da trovare, nella civiltà. Basta chiedere a un ingegnere esperto di fartene uno. Credo servano un paio di lingotti di mithril, ma se riesci ad aiutarmi, farò in modo che tu venga ricompensat$Go:a; bene!"
S["a6a2d21f"] = "Pieno zeppo di ratti! Dai una mano a un pirata, compare!"
S["a6a75359"] = "Ah! Vediamo l'umano di legno salutare!"
S["a6b02480"] = "Non dobbiamo far adirare il Maestro. La sua ira è crudele oltre ogni misura."
S["a6c369c9"] = "Che le esecuzioni abbiano inizio!"
S["a6d0eeda"] = "Scacceremo i nostri nemici da Silverpine, poi porteremo le maree della guerra fin dentro la loro capitale!"
S["a6d50452"] = "Ooo, quanto sei forte! Buon Hallow's End, $N!"
S["a6d56836"] = "Ehi! Sei qui per una partita a ossicini?"
S["a6db8933"] = "Gli umani avevano costruito una locanda ai margini delle Barrens e la chiamavano Shady Rest. Qualche settimana fa è stata data alle fiamme.$B$BIl Capoguerra ci aveva detto di lasciare in pace gli umani finché non avessero varcato i nostri confini, ma a quanto pare qualcuno ha agito contro la sua volontà.$B$BHa affidato a me il compito di andare fino in fondo alla faccenda. Se vuoi darmi una mano, va' a quel che resta della Shady Rest Inn e portami ogni indizio che trovi."
S["a6dc58bb"] = "Vuoi sapere chi è l'eroe più popolare del regno? Beh, ecco la classifica di adesso!$B$BThrall:$BCairne:$BSylvanas:$BTotale Orda:$B$BBolvar:$BMagni:$BTyrande:$BTotale Alleanza:$B$BSe vuoi votare, non dimenticarti di consegnare le raccolte di regali!"
S["a6e9ff34"] = "Ciao, fratello."
S["a6ed678b"] = "Le statue tornano tutte nelle loro posizioni originali.$B$BOra la sequenza va ricominciata, dall'inizio."
S["a708965b"] = "Credi davvero di fare progressi? Non potrai mai sconfiggere lo Scourge! Queste piccole vittorie non sono altro che un trucco per renderti troppo $Gsicuro:sicura; di te!"
S["a709e350"] = "La soluzione è pronta nel mio calderone. Resta solo da trattare sia la chiave non finita sia lo scarabeo."
S["a716d4a9"] = "Basta così per oggi, uomini!"
S["a71834d8"] = "Ishnu-dal-dieb, $N. Sei $Gvenuto:venuta; qui in cerca di conoscenza?"
S["a71ca8c5"] = "Salve, giovane $C. Sono Rathiril Sunlance, Magistro anziano dell'High Order qui su Zephras Isle. Fa sempre piacere vedere giovani shen'dorei pieni di entusiasmo, pronti a fare il loro dovere al servizio della patria.$B$BMa non lasciarti trattenere da questo vecchio mago impolverato: di sicuro ti aspettano molte avventure. Ripassa pure più tardi, se ti va di parlare ancora."
S["a71d031c"] = "Lucan Cordell ha una piccola bottega sul canale, vicino alla Stockade. Sono $Gsicuro:sicura; che saprà insegnarti l'arte dell'incantamento."
S["a71f4739"] = "Mai come ora c'è stato bisogno dei cacciatori e dei ranger di Zephras. I venti soffiano sempre più violenti e la magia che sostiene la nostra isola sta svanendo. Le terre selvagge non sono mai state così selvagge, e per proteggere il nostro popolo serve gente come me.$B$BSe hai le doti giuste da $Gcacciatore:cacciatrice;, posso darti gli strumenti per sopravvivere nelle terre selvagge."
S["a723b3e5"] = "A quanto ho sentito, l'Orda ha messo da parte peacebloom, firebloom e purple lotuses."
S["a72f17bd"] = "Grazie, $N. E buona fortuna!"
S["a733ea7f"] = "Ahh, capisco... ospiti non invitati. E vedo che ficcano il naso nei nostri affari."
S["a734482c"] = "Hai intrapreso un sentiero d'onore, $N. I miei antenati rispettano la tua buona volontà, ma la mia approvazione non l'avrai finché non avrai portato a termine i miei compiti.$B$BSai cosa devi fare, se vuoi dimostrare di essere $Gun cacciatore:una cacciatrice; nello spirito."
S["a738f94a"] = "%s cinguetta un saluto a $N."
S["a73baa33"] = "Bene, allora... Devi costruire un'arcanite buoy e metterla nell'oceano. Le emanazioni magiche richiameranno il mio pesciolino, e quando si avvicinerà alla boa — BLAMO! Questa esploderà in un glorioso impulso di energia arcana che rivelerà la vera forma del pesciolino. In più potresti attirarti l'ira di Neptulon, oppure no. Direi un 50/50."
S["a73c6e5e"] = "$N UCCIDE! $GLui:Lei; uccide voi adesso! SCAPPA! SCAPPA!"
S["a73feb44"] = "Signor guardia del corpo, ti guadagni la paga o no?"
S["a750f563"] = "Straniero, trova il principe caduto Menethil e poni fine al suo regno di terrore."
S["a759aae4"] = "Alexstrasza, concedimi la determinazione per ricacciare i nostri nemici!"
S["a76aa667"] = "Ok, diamo un'occhiata a questo affare..."
S["a76beb09"] = "L'Orda sta facendo scorta di bende in gran quantità. Finora ha raccolto wool bandages, ha preparato mageweave bandages e ha messo insieme bende di runecloth."
S["a76c38bc"] = "Saluti, $C. Io sono Exzhal, Servitore di Rastakhan."
S["a76fc2fc"] = "Non ho più niente da insegnarti — ora fuori! E non pensare nemmeno di avvicinarti a Saru, perché il sangue di $Gun indegno:un'indegna; come te lo userà per temprare l'acciaio."
S["a776fd3b"] = "Theresa, porta questo a Father Lankester."
S["a77db4b9"] = "$GAttento:Attenta;, soldato! Devi portare questo segnalatore al cimitero di Snowfall e piantarlo nel terreno! Proteggilo abbastanza a lungo da permettere al mio grifone di agganciarlo.$B$BSe il mio grifone ottiene un punto d'attacco sicuro, Mulv e la sua banda verranno umiliati!"
S["a792dab6"] = "Cyndra ha conoscenze un po' limitate di alchimia, ma sono $Gsicuro:sicura; che ti basteranno per cominciare. Esercita il mestiere appena a est della Locanda di Dolanaar."
S["a79abe79"] = "L'Icewing Bunker presidia il passo tra il territorio dell'Alleanza e il Field of Strife.$B$BNon è controllato da nessuna delle due parti."
S["a7a89aa4"] = "È incredibile come certi fiorellini resistano al freddo di Dun Morogh... ma qui fuori di erboristi non ne troverai. Per imparare quella professione dovrai andare a Ironforge."
S["a7abf532"] = "Tieniti $Gpronto:pronta;, $N. Sento che il consiglio sta tornando. Preparati all'imboscata!"
S["a7c1a8e3"] = "Vengono a prenderti, stolto!"
S["a7c51195"] = "%s trova un tartufo."
S["a7c5aa93"] = "Ascolta, signorina, sappi che quella cosa che ci ha attaccati non era una sacerdotessa di un bel niente! Le brillavano gli occhi di qualcosa di malvagio e aveva proprio la bava alla bocca! È entrata, ha cacciato una specie di urlo da matti che ci ha fatti scappare tutti chi da una parte chi dall'altra, e poi si è messa a straziarci la mente uno alla volta. Sentivo parole oscure dentro la testa, e ogni tanto vedevo gli altri perdere i sensi qua e là. Una follia! Se non c'era quella dannata scimmia, eravamo spacciati."
S["a7c72095"] = "Anathera!"
S["a7c7a35b"] = "Ugh... Hallan, non pensavo ne fossi capace..."
S["a7caa024"] = "Le radici e le felci parlano bene di te, $Gpiccolo:piccola;. Ho molti nomi, ma rispondo a pochi: tu puoi chiamarmi Rethiel.$B$BE devi ascoltarmi... queste terre piangono per ferite purulente, e vorrei affidare a te il compito di guarirle."
S["a7d05f0a"] = "Spero che tu sia qui per aiutarci a riprendere l'Arathi Basin a The Defilers. Allora, $N, che ne dici?"
S["a7d07d85"] = "Il Dun Baldar South Bunker è stato distrutto dall'Orda!"
S["a7d676d4"] = "Ciao ciao, $Gpiccolo piccolo:piccola piccola; $R. Raze va adesso."
S["a7de1324"] = "Madre, oh madre. Avresti dovuto darmi ascolto..."
S["a7f4d423"] = "Senti la potenza dei Dark Iron Dwarves!"
S["a7f63a1b"] = "Capito. Tornerò presto."
S["a800bd2a"] = "Captain Galvangar è il fidato aiutante di Drek'Thar. Guida le forze dell'Orda dall'Iceblood Garrison, nella parte meridionale del Field of Strife.$B$BCaptain Galvangar non è ancora entrato in battaglia."
S["a806f1ce"] = "Quel tipo di magia porta solo guai, te lo dico io. Non so perché abbiano lasciato che quel Grimrizz si sistemasse proprio fuori dalla Thunderbrew Distillery! Stagli alla larga, hai capito!"
S["a80d630e"] = "Saluti. Sono un guardiano dell'ingresso. Se le Placche di Uldum non sono già integrate nel tuo set di dischi, non ti consentirò di entrare nel complesso di Uldum."
S["a817a551"] = "Mi porto dentro un sacco di rabbia e di ostilità repressa. Dammi un pretesto, $Gstraccione:stracciona;."
S["a81f0cce"] = "Che razza di combattimento era quello? Dovrei cacciarvi a calci dalla squadra e dalla guardia, buoni a nulla che non siete altro!"
S["a82593cf"] = "<Bodley ti guarda con aria dubbiosa, ma prosegue...>$B$BEccoci lì, col libro degli incantesimi in mano, quando a Kormok, il nostro negromante ogre a due teste, viene uno sguardo strano in tutti e quattro gli occhi. Metteva davvero i brividi, perché il secondo paio d'occhi sembrava sempre un po' morto, come quelli di una mucca, capisci? E all'improvviso allunga la mano e strappa via l'amuleto che Valthalak portava addosso.$B$BIl resto della compagnia è andato fuori di testa: c'era chi diceva agli altri di lasciarlo stare e chi lo voleva per sé."
S["a82ca596"] = "$GPronto:Pronta; per un'altra lezione? E va bene. Prima di tutto rilassati: per mescolare una pozione come si deve devi stare $Gsciolto:sciolta;."
S["a82ecd1c"] = "VENITE, MIEI SERVITORI! DIFENDETE IL VOSTRO PADRONE!"
S["a8304e44"] = "Nella parte nord-orientale delle Barrens c'è una pozza d'acqua ammorbata dall'inquinamento, che la gente del posto chiama Sludge Fen: la Venture Company ha trasformato le sue acque, un tempo azzurre e cristalline, in un pantano di scarti e rifiuti industriali. Ciò che cerchi si trova nel cuore di questo acquitrino, $N.$B$BTi avverto — la Venture Company non tollera gli intrusi, e considera tale chiunque non lavori per lei. Sarai un bersaglio soprattutto perché sei $Gprotettore:protettrice; della natura, e a questo si oppone con tutte le forze."
S["a83553f4"] = "SMOTTS, HO LA TUA CINTURINA... VIENI A PRENDERTELA."
S["a8399015"] = "Finalmente... Libero dalla sua presa maledetta!"
S["a83d22b3"] = "Poco tempo fa ho avuto un brutto incontro con alcuni dei Defias da queste parti, ma Michelle Belle mi ha rimesso in sesto piuttosto bene. Vai a trovarla alla Lion's Pride Inn e chiedile se ti insegna."
S["a84a4257"] = "La conoscenza che cerchi non la possiedo."
S["a84fa744"] = "$GBenvenuto:Benvenuta; alla Bank of Stormwind. Qui trovi conti e cassette di sicurezza per i tuoi oggetti di valore. Hai già un conto da noi, signora?"
S["a8508866"] = "Stolti! Vi credete trionfanti? Avete solo fatto un passo in più verso l'abisso!"
S["a85435aa"] = "Ottimo lavoro, $Gsoldato:soldatessa;. Devo tornare al campo base! Mi copri?"
S["a8548210"] = "Il First Aid è un'abilità che fa sempre comodo: in battaglia mi ha salvato la pelle tante volte. Vai da Spiritual Healing, sulla Spirit Rise. Pand Stonebinder può insegnarti tutto quello che serve per salvarti la pelle anche tu."
S["a85f8e44"] = "Muovetevi! Ne servono altri!"
S["a867b39e"] = "Tutti scagnozzi di capo — Stomper Kreeg, tutte e tre le Guardie, Captain Kromcrush e l'Osservatore — danno tributo a nuovo capo. Tu uccidi uno scagnozzo, quello scagnozzo non può dare tributo! Ogni scagnozzo che tieni vivo, più tributo per te. Tieni vivi tutti e tu prendi il tributo GROSSO!$B$BSì!"
S["a86896be"] = "Ti prego, ti prego, ti prego, dimmi che sei qui per liberarmi da queste catene. Da qualche parte dev'esserci una chiave...$B$BPer lo meno, magari puoi far fuori Guard Slip'kik. Credo di poterti aiutare!$B$BVedi quella trappola rotta laggiù? Gli ogre sono troppo stupidi per capire come aggiustarla. Chiaramente le servono un congegno di torio e un po' di olio del gelo. Se la ripari, scommetto che potresti attirarci dentro Slip'kik e BAM: guardia ogre in trappola!"
S["a86c9661"] = "L'equilibrio è stato ristabilito!"
S["a871c7ec"] = "Eoni di battaglia ne avevano indebolito le forme materiali, ed erano imprigionati sotto il mondo — quel mondo che loro stessi avevano creato —, così la corruzione dei Titan Shapers sarebbe filtrata attraverso la superficie, contaminando gli Old Gods.$B$BFu proprio allora che i fratelli si rivoltarono. Per cinque millenni, nel cuore di questo mondo, si combatté una battaglia."
S["a89a7050"] = "Captain Balinda Stonehearth è caduta!$B$BAttaccate l'Orda! Vendicate il Capitano Stonehearth!"
S["a8a793e8"] = "Devi cercare nelle acque di Westfall, esattamente a ovest-nordovest del punto dove la Gold Coast Quarry arriva alla riva. Un'ancora segna il punto dove, più al largo, una barca è affondata giù nel profondo. Qui la pressione sott'acqua è terribile; anche il nuotatore più forte, se si spinge troppo in là, finirà schiacciato dalla fatica.$B$BCerca una formazione naturale che ti aiuti, $N — qui vicino c'è una fenditura piena di bolle, dove chi nuota in acque profonde può riprendere fiato."
S["a8aaf174"] = "Dove caddero i due amanti sarebbe fiorito un albero. Gli elfi lo chiamano heartswood. Di certo servirà ai tuoi scopi."
S["a8b220c9"] = "Con il benestare di Lord Varimathras, i Deathstalkers sono sempre di più. Altre lame pronte a colpire i nostri nemici quando meno se lo aspettano."
S["a8b5d8bb"] = "Ooh, è proprio bello! Fammelo solo dissotterrare..."
S["a8bb0c03"] = "Hai fatto bene a cercarmi. Vorrei chiederti un piccolo favore. In cambio, posso insegnarti molte cose."
S["a8bb5afd"] = "Il Pilone Occidentale accetta cristalli rossi, verdi e blu.$B$BIl Pilone concentra l'energia che si può creare usando come fonte principale di potere i cristalli rossi. Gli effetti possibili sono due: uno aumenta la tua protezione dai danni, l'altro indebolisce le difese di un nemico.$B$BLa Crystal Ward richiede cristalli rossi e verdi, e ti aumenterà l'armatura.$B$BLa Crystal Yield richiede cristalli blu e rossi, e può ridurre l'armatura di un bersaglio specifico."
S["a8bcac92"] = "Non dimenticare i sacrifici fatti oggi, elfo della notte. Abbiamo tutti sofferto immensamente per mano di queste bestie."
S["a8bfa44a"] = "Osi toccarmi?!"
S["a8bfffb9"] = "I Wind Spirits ci hanno lasciati.$B$BOra non restano che echi privi di coscienza. Ma sii $Gcauto:cauta;: questi venti non sono né buoni né gentili."
S["a8c3bd0d"] = "Io rappresento la forza che ti sostiene come giovane $Gdruido:druida;. Sei $Gvenuto:venuta; da me per imparare questa forza, giovane, e io te la insegnerò: ti insegnerò tutto dello spirito dell'orso, purché tu sappia ascoltare e capire.$B$BPer sapere cosa vuol dire attingere al mio spirito, devi capire quanto conta la forza del corpo, oltre a quella del cuore."
S["a8c4067d"] = "Prendi 'sta lama così, poi tira. Basta girà 'l polso, amico, un giro e ti sei fatto 'l pranzo."
S["a8c65fb3"] = "È un esemplare di flora esotica, come non se ne vedono in nessun'altra parte di Teldrassil."
S["a8c74061"] = "La cara vecchia Erma si prende cura degli animali del posto da anni, ormai. Di quelli che vorrai lasciarle, sono $Gsicuro:sicura; che sarà felice di occuparsene. La trovi appena fuori dalla Lion's Pride Inn."
S["a8c9b468"] = "Mi attaccano! Aiutatemi a togliermi di dosso $Gquesto:questa; $N!"
S["a8cab2a7"] = "L'Orda vince!"
S["a8cebb59"] = "Oh, quante storie e quanto dramma, il giovane Maestro. A sentirlo, pareva che il destino del mondo poggiasse tutto sulle sue spalle. Solo dei mortali potrebbero vedere il nostro mondo in modo così distorto.$B$BAhimè, mi ha lasciato i suoi miseri segreti magici... Libram o qualche sciocchezza del genere. Io non so che farmene di queste magie da quattro soldi, ma i loro incantamenti forse potrebbero interessare a te."
S["a8d15f3c"] = "Cerchi una conoscenza più alta. Tepa l'ha ricevuta in dono. Dovrebbe essere qui vicino..."
S["a8d222ba"] = "Ma loro ti temono e ti odiano, Danitha. Lo sai di certo, no? Nell'Argent Dawn il tuo legame con la luce sarebbe una risorsa. Saresti molto apprezzata!"
S["a8d92d62"] = "Vi troverò, mortali! Pagherete per aver distrutto i Cristalli Ash'ari!"
S["a8ddcc85"] = "Per secoli la possente fortezza scavata nelle viscere infuocate di Blackrock Mountain rimase in mano ai sinistri nani Dark Iron, finché Nefarian — l'astuto figlio del drago Deathwing — non prese il controllo della parte alta della Guglia e mosse guerra ai possedimenti dei nani, giù nelle profondità vulcaniche della montagna. Quando capì che a guidare i nani era il potente elementale del fuoco Ragnaros, Nefarian giurò di schiacciare i nemici e di prendersi tutta la montagna Blackrock."
S["a8e88307"] = "The Scepter of the Shifting Sands è di nuovo intero, $N.$B$BDevi essere tu a usare lo scettro. Devi essere tu ad annunciare la nuova era del tuo popolo.$B$BQuando sarai $Gpronto:pronta; a suonare il Gong dello Scarabeo e ad aprire ancora una volta i cancelli di Ahn'Qiraj, ti darò lo Scettro. Non devi far altro che chiedere."
S["a8e89f4e"] = "Certo, Alta Sacerdotessa. Siamo gli strumenti della vostra volontà. Vorrei solo che foste qui a vedere con i vostri occhi il nostro trionfo."
S["a8e92ac4"] = "La Bandiera dell'Alleanza è stata presa da $N!"
S["a8ea8ed2"] = "Elder Morndeep passa le sue giornate al Ring of Law, nei Blackrock Depths."
S["a8f3b672"] = "Non sfuggirete alla morte!"
S["a900f1a6"] = "Guarda sul rialzo più basso di fronte ai banditori d'asta se vuoi farti tagliare la criniera."
S["a90da830"] = "Vattene da qui, $C, se non vuoi che mettano in catene anche te."
S["a90f653d"] = "Pagami e parlerò...$B$BOh, ehi, sei tu, $N! Lascia stare..."
S["a9119600"] = "Sei $Gvenuto:venuta; nel posto giusto, $Gragazzo:ragazza;! Qui viene gente da tutto il mondo a imparare il mestiere del fabbro. Bengus Deepforge lo troverai a martellare su un'incudine in mezzo alla nostra bella città, proprio accanto a The Great Forge."
S["a928bb59"] = "Sei $Gpronto:pronta; per cose più grandi! Va' da Franklin Lloyd, alla mia destra: d'ora in poi sarà lui a guidarti."
S["a93a2257"] = "Quando le nostre scorte sono abbondanti, il Warmaster Garrick è di stanza nel Field of Strife presso una catapulta, a nord dell'Iceblood Garrison."
S["a93cea97"] = "Questa entità demoniaca è nota come Ombra del Vuoto. Ha forza e resistenza notevoli, ideali per la difesa. Mandala ad attaccare il nemico, poi usala come scudo mentre con incantesimi e abilità prosciughi la vita del tuo avversario."
S["a9407e12"] = "Addio, e che la Luce sia sempre con te."
S["a9409718"] = "L'opera è compiuta. Il totem è fatto."
S["a945582d"] = "Il demone è libero! Presto, dobbiamo trattenerlo!"
S["a94a79f0"] = "Mmmm... sembri proprio $Gbuono:buona; da mangiare."
S["a95a4671"] = "Se vuoi davvero imparare questa professione, ti direi di andare da Ainethil, un'abile alchimista che sta sulla Craftsmen's Terrace, nella parte nord di Darnassus."
S["a96036a2"] = "Ecco fatto, $N. La tossina è pronta."
S["a960bcd2"] = "In quanto membro dell'High Order degli shen'dorei, qui nella nostra città sei $Gil benvenuto:la benvenuta;, $C.$B$BIn questi ultimi mesi io e il tuo capo, Elaadrin Evengale, ci siamo scritti spesso. Credo che il Kirin Tor e l'High Order siano fatti della stessa pasta: sempre in cerca di risposte ai più grandi misteri del mondo. E oggi più che mai cercarle è vitale per la sopravvivenza di tutti noi.$B$BTu su Zephras hai visto interrompersi il tuo modo di vivere, e allo stesso modo anche su Azeroth il flusso della magia è stato caotico. Turbato, in qualche modo... come se una pietra fosse caduta nell'acqua ferma e ne avesse increspato la superficie.$B$BAh, ma di questi problemi possiamo parlare un'altra volta. Per ora, $Gbenvenuto:benvenuta; su Azeroth."
S["a96b2e61"] = "Dhugru Gorelust se ne sta nascosto dietro la caserma, sul lato est della città. E se vengo a sapere che sei in combutta con la Burning Legion, guai a te!"
S["a96cc172"] = "Il diritto di addestrarti con me non te lo sei ancora $Gguadagnato:guadagnata;. Prima va' da Thund, vicino al tavolo. Torna quando ti dirà che sei $Gpronto:pronta;!"
S["a970d822"] = "Ok, vado!"
S["a973ff7a"] = "La fine si avvicina rapidamente! Arrendetevi a Eranikus e vi sarà risparmiata la sofferenza eterna!"
S["a97f8235"] = "È incoraggiante sapere che Elaadrin e i suoi maghi sono finalmente con noi. Con l'High Order e i Windshapers al nostro fianco contro la minaccia più grande, abbiamo molte più possibilità di fermare gli Al'Aketh e qualunque cosa abbiano in mente per Valanaar."
S["a981846c"] = "Ho trovato entrambe le parti del tuo scettro."
S["a983bca7"] = "E cerca di non perderti, stavolta...."
S["a984e90e"] = "Lo spirito del Destriero del Terrore pulsa di rabbia."
S["a98951e3"] = "Desidero disimparare i miei talenti."
S["a989c97e"] = "Lascia questo luogo, $Gstraniero:straniera;, prima che consumi anche te, come tutto ciò che ha toccato."
S["a989e2dd"] = "Quegli altri ogres era stupidi ad attaccare te, capo! Io invece intelligente e cose così: per questo ancora vivo!"
S["a989f95f"] = "Morditi la lingua, $R, o te la strappo dalla scatola cranica e ci faccio uno scaldacorna."
S["a9907fd4"] = "I nostri veterani stanno lasciando il campo. Ci servono altri rifornimenti!"
S["a9985cef"] = "%s esplode in pezzi di melma acida!"
S["a999ba8f"] = "Passa a unità esperte!"
S["a999e1d6"] = "Saluti, $C. Posso insegnarti abilità e tecniche."
S["a99e48fc"] = "E ora sai tutto ciò che c'è da sapere, mortale..."
S["a9a04ed0"] = "L'antico regno di Lordaeron è pericoloso, e a chiunque osi avventurarsi nelle terre ormai in rovina delle Tirisfal Glades raccomandiamo prudenza. Se proprio devi, trova l'Undercity: è ai cortili superiori che devi arrivare."
S["a9a3aca3"] = "Posso insegnarti a pescare."
S["a9c09dc4"] = "VanCleef paga tanto per vostre teste!"
S["a9c6dbf9"] = "Sento puzza di $R"
S["a9c9a600"] = "Halo, halo. Awa paw ba mani ishte."
S["a9cb91f5"] = "Ragnaros vede tutto, mortale."
S["a9cc8bd3"] = "Se riesci a completare un mazzo di carte dei portali, avrai in premio una carta di lunacupa superiore della distorsione fatua. Ogni tanto, quando muori, questa carta riporterà lo spirito nel tuo corpo e ti rianimerà."
S["a9cffefa"] = "Carte della Darkmoon Faire? Per quelle rivolgiti al Professore qui presente. Se invece sei $Gun mercante:una mercante; di antichità e manufatti difficili da trovare, vieni da me."
S["a9d140a0"] = "%s chiama altri alleati fuori dall'ombra."
S["a9d17f9a"] = "Lo avevo intuito, Malfurion. Ci attendono giorni bui."
S["a9d36d46"] = "Più facile del previsto... il Sigillo di Thoradin è di nuovo intero."
S["a9d71bf0"] = "Se intendi seguire la via del ladro, devi cercare Syurna. Vive nella Cenarion Enclave, in fondo al sentiero che gira a spirale dentro l'albero più a occidente."
S["a9d72ddb"] = "Successo, il varco è aperto!! Fratelli miei, alzatevi e tornate a casa! Outland vi attendono!"
S["a9e9476a"] = "Una banda di briganti e ladri non mi farà lasciare la mia terra!"
S["a9ed684f"] = "Non sono $Gdegno:degna; di questa conversazione, Padrona."
S["a9fc9a3e"] = "Hai una bella abilità, $N. Le lame e i martelli che forgi superano perfino i miei, per quanto mi costi ammetterlo. L'unico che abbia mai incontrato con un'abilità ancora più grande è Borgus Steelhand: scommetto che potrebbe insegnarti un paio di cose."
S["a9fee26b"] = "Temo che il cristallo sia troppo danneggiato per riprodurre altro."
S["aa034978"] = "Basta! Sono $Gstanco:stanca; di darti una mano. È ora di regolare i conti sul campo di battaglia!"
S["aa04545c"] = "Mia signora, non sono degno della tua preghiera. Sei davvero un angelo di luce. Ti prego, aiutami a tornare all'eremo, così potrò tornare nel Sogno. Anch'io, come Malfurion, ho un amore che mi aspetta... Devo tornare da lei... per proteggerla..."
S["aa062458"] = "Il Forest Lord sa della distruzione in questa valle, $N. Presto dovremo andare al Cerchio dell'Invocazione. Preparati!"
S["aa08cbc7"] = "Che Cenarius vegli su di te, $Gfratello:sorella;.$B$BIo sono Tajarri, e sono una protettrice giurata di questo santuario. È un onore per me servire Keeper Remulos come guardiana di questa terra sacra."
S["aa0a9648"] = "Oh, santo cielo, di nuovo no... Siediti, $Gfigliolo:figliola;.$B$BRutgar ti ha già raccontato un pezzo di questa storia, ne sono $Gsicuro:sicura;, quindi lascio perdere i dettagli noiosi e vengo dritto al sodo."
S["aa0d0c87"] = "PERCHÉ? Perché è successo... proprio a me? Dov'eri, Tyrande? Dov'eri quando ho perso la grazia di Elune?"
S["aa16a023"] = "Sei davvero $Gsorpreso:sorpresa;? È così difficile credere che il potere di un Old God possa arrivare persino dentro il Sogno? È vero — Eranikus, Tyrant of the Dream combatte una battaglia contro tutti noi. L'Incubo segue la sua scia di distruzione."
S["aa172e0c"] = "Guarda, fratello, sangue fresco!"
S["aa1b06c0"] = "L'arcano corrompe solo i deboli. Non trascurare l'addestramento, o rischi di fare una fine simile."
S["aa1d8e03"] = "Ah, prima che tu salga alla Shadowgale Forest, un avvertimento. Lassù è pericolosissimo. C'è perfino chi dice che sia infestata dagli spettri. Se hai intenzione di affrontare il viaggio, assicurati di essere $Gpronto:pronta; e ben $Gequipaggiato:equipaggiata;."
S["aa216f41"] = "No, Leonid. Il nostro posto è qui. Il nostro giovane ordine deve trovare la propria identità tra i nostri simili. So cosa pensi dei Forsaken... che la nostra \"condizione\" sia qualcosa da curare."
S["aa227a81"] = "Sono l'ultima incarnazione dei venditori automatici... e un giorno il mondo lo domineremo noi... tu però non dire al mio capo che faccio la cresta sulla sua merce..."
S["aa2493d1"] = "La Dea mi ha concesso la saggezza, $Gstraniero:straniera;, e se tale è la sua volontà te la trasmetterò."
S["aa2c7431"] = "Una parte sempre più grande di Kalimdor si sta trasformando nel paesaggio distorto alla nostra sinistra, e le bestiole che ci vivono NON sono amichevoli. $GAttento:Attenta; a dove metti i piedi."
S["aa320cab"] = "Davanti a te c'è uno strano marchingegno, con una semplice targa che ne annuncia il nome: \"The Sparklematic 5200\". La macchina sembra fatta per far tornare gli oggetti lucidi e nuovi."
S["aa322396"] = "I Gordunni, una grande tribù di ogre, controllano vaste zone delle foreste di Feralas. La loro magia oscura penetra negli elementi intorno a loro e fa danni sia all'ambiente sia alle creature che ci vivono.$B$BSe decidi di andare a Feralas, fai attenzione a questi ogres — sono piuttosto cattivi, e molti di loro sanno usare una potente magia oscura."
S["aa32a263"] = "%s posa le assi di legno raffinato."
S["aa3349cd"] = "Offro le mie cavalcature solo a chi è considerato amico di Orgrimmar e della razza degli Orchi. Vai a dimostrarci il tuo valore, e metterò i miei possenti lupi a tua disposizione perché tu possa esaminarli."
S["aa37ed1b"] = "Sì, Bonescythe. Vedi, a mettermi su questa strada è stato il nostro tenore, un tipo scorbutico noto come Don Julio. Viaggiando per Lordaeron, Don Julio ha acquisito molte abilità interessanti, fra cui quella di prendere le ossa dei caduti dello Scourge e ricavarne un completo di armatura di cuoio letale — perfetto per un assassino."
S["aa38c5eb"] = "Non ho mai visto niente del genere! Guarda quanto è lunga la mascella..."
S["aa3912eb"] = "Oh, e per te in particolare, $C. I nostri esploratori hanno saputo del tuo coinvolgimento in quello che è successo al magistro, Belathaan Brightwish. Se lo sappiamo noi, di sicuro lo sa anche l'High Order."
S["aa4aac15"] = "In tante occasioni l'abilità di Byancie nel First Aid si è rivelata utile. Se vuoi imparare da lei, la trovi appena a nord della Locanda di Dolanaar."
S["aa4c87a9"] = "%s emette uno strano rumore."
S["aa507638"] = "Grazie. Speriamo che non ce ne siano altri."
S["aa56f4b3"] = "Sono $Gsopravvissuto:sopravvissuta; ai veleni dei Forsaken, $N, e ora so cosa va fatto."
S["aa57b89c"] = "Non posso addestrarti."
S["aa588caa"] = "Faresti meglio a toglierti di torno, $Gragazzo:ragazza;. Il mio cucciolo qui ha fame, e il tuo odore gli piace."
S["aa59e34c"] = "Addio, amico mio."
S["aa618421"] = "Sarok, perché non parliamo d'affari?"
S["aa68ca1e"] = "NON PUÒ ESSERE!!"
S["aa6925c7"] = "Urrà per chi lascia la mancia! Avanti, avanti, le vostre bevande fresche e deliziose sono proprio qui!"
S["aa7068d0"] = "Sono $Gpronto:pronta; a cominciare."
S["aa7aa763"] = "Credo che come primo esercizio dovrai scavarti la strada fino a Undercity. Eh, l'hai capita? Scavare... lascia perdere. Per arrivare a Undercity vai dietro le Ruins of Lordaeron, a sud di Brill, e prendi l'ascensore che scende. Se ti serve altro aiuto, chiedi a uno degli Undercity Guardians che trovi lì."
S["aa7ca9ef"] = "La mia anima è libera, finalmente!"
S["aa87159d"] = "Hai mai sentito parlare degli Highborne? Degli Shen'dralar?"
S["aa9ae46c"] = "Il Dun Baldar South Bunker è sotto attacco! Se nessuno la ferma, l'Orda lo distruggerà!"
S["aa9ca117"] = "$GMaestro:Maestra; $N! Master Kang ha chiesto di te! Forse è giunto il tuo momento!"
S["aa9d8388"] = "Scommetto che Keryn Sylvius conosce il genere di gente che cerchi: le compagnie di Keryn non sono delle più onorevoli. Di solito se ne sta alla Lion's Pride Inn."
S["aa9df451"] = "Mi serve un passaggio, presto! Devo consegnare un messaggio importante!"
S["aa9f9970"] = "Myolor, un tempo ero $Gun:una; fabbro d'armature e desidero riprendere in mano il martello ancora una volta! Insegnami la via del fabbro d'armature."
S["aaa0da13"] = "*Unità Primo Ufficiale Threshwackonator pronta a seguire*"
S["aaa25c0c"] = "Non manderei mai via nessuno che sia pronto ad allenarsi con me. Ma tu, purtroppo, non lo sei! Hai ancora molta strada da fare, $Gragazzo:ragazza;!"
S["aaa3a67b"] = "Ladri in edificio su anello esterno di Rogues' Quarter."
S["aaacfe2f"] = "Le tue abilità superano le mie, $Gstraniero:straniera;. Parla con Hgarth al Sun Rock Retreat, nelle Stonetalon Mountains: ti insegnerà più di quanto possa fare io."
S["aaae1800"] = "È in buca! È in buca!"
S["aaaed6d3"] = "Hai liberato Kirith dalla sua sofferenza? Inconcepibile — e ora Trebor ti ha mandato qui per imparare qualcosa sui demoni e sui loro servitori?$B$B<Loramus ride.>$B$BSii $Ggrato:grata; che le fitte arcane si siano finalmente dissolte, $R."
S["aab3f9e6"] = "$N, che bello rivederti! Ti diverti alla Fiera?$B$BTi va di fare a braccio di ferro? No, certo che no... il braccio vuoi tenertelo!"
S["aab43f9f"] = "Le Burning Steppes sono sotto attacco in questo momento?"
S["aabc8dc5"] = "Posto sbagliato, tu $Gvenuto:venuta;. Là c'è Godan, lui esperto: parla con lui, tu impari di più."
S["aabccae3"] = "Ahi! Va bene, torno al lavoro, $N!"
S["aac65d1b"] = "Adesso proviamolo..."
S["aaca3ba7"] = "Non so se devo attribuirlo alla sua natura solitaria, ma non mi pare di avere niente su Ira Valor.$B$BHo chiesto in giro in città, ma non ho sentito granché su misteriosi salvataggi nella foresta. Un mercante credeva di aver visto una donna nella foresta, a un certo punto, ma è decisamente troppo vago per usarlo come prova."
S["aacae4bc"] = "Lo spirito fluttua sopra il suo corpo senza vita. Ti trapassa con gli occhi spettrali, lo sguardo rivolto oltre..."
S["aacf508b"] = "Ed ecco $N che affronta la prima curva!"
S["aad1d3a2"] = "NEFARIAN È STATO UCCISO! Popolo di Orgrimmar, inchinatevi davanti alla potenza di $N e dei suoi alleati, perché hanno inferto al Black Dragonflight un colpo che di certo scuoterà gli Aspetti dal loro torpore! Il padre del Black Flight sentirà di certo questa sconfitta: oggi Deathwing barcolla nel dolore e nell'angoscia!"
S["aad350ef"] = "Studialo, $N: Il Catalogo dei Traviati."
S["aad81255"] = "La prossima volta porta degli amici."
S["aad8771b"] = "Fiuu... Ho bisogno di una fumata e del tocco di una bella gnoma — non per forza in quest'ordine!$B$BSono rimasto chiuso per mesi nella pancia di quel coso! Ma che giorno è, poi? Ah, lascia stare. L'importante è che finalmente ne sono uscito.$B$BIUUU HUUU!"
S["aadb6975"] = "Vai a Mage Quarter e cerca Fyrenz Stargazer: sta appena a nord-ovest della torre dei maghi."
S["aade6439"] = "Doctor Draxlegauge ti darà altre istruzioni, $N. Grazie mille per l'aiuto!"
S["aae85804"] = "Ti sembro forse il Gran Mogol degli incantatori? Per quello che sai fare ti serve la guida di un Artigiano! Va' a cercare Kitta Firewind alla Tower of Azora."
S["aae87783"] = "In fondo è semplice. Lascia che te lo riassuma..."
S["aae9e19e"] = "Sei $Gsicuro:sicura; di non voler fare il Fabbro? Be', se la Conciatura ti sta tanto a cuore, ti conviene parlare con Fimble Finespindle: ha la bottega sul lato nordovest di The Great Forge."
S["aaecc4a5"] = "Molte casse di provviste chiuse sono andate perdute quando i naga hanno invaso la Zoram Strand ad Ashenvale."
S["aaed9c5d"] = "Luce, dammi forza!"
S["aafa6636"] = "$GBenvenuto:Benvenuta; nella mia bottega; fa piacere vedere $Gun altro Sarto:un'altra Sarta; qui a Valanaar. Sei $Gvenuto:venuta; per una lezione, per caso?"
S["aafb5c0b"] = "La paura è per il nemico! Paura e morte!"
S["aaff5255"] = "Buongiorno, Elling! Salve, Elaine! Datemi una forma di formaggio erborinato, eh?"
S["aaffda33"] = "La Frostwolf Relief Hut è sotto attacco! Se nessuno interviene, l'Orda la conquisterà!"
S["ab0067c6"] = "Tu cerchi Martha Alliestar. Lei su anello interno di The Apothecarium."
S["ab092fd3"] = "Bah! Saresti già $Gridotto:ridotta; in macerie prima di arrivare a tiro del vecchio Trollplow!"
S["ab0b0e68"] = "Manca ancora molto, $N?"
S["ab0be337"] = "Grazie, $N. Hai stemperato la gelida rabbia che avevo nel cuore."
S["ab113d63"] = "Tornate indietro! Non svegliate il dormiente!"
S["ab2159c4"] = "Abbiamo pochissime provviste. Se vogliamo mandare un assalto via terra nel Field of Strife, ce ne serviranno molte di più!"
S["ab22d57f"] = "%s banchetta!"
S["ab2a1ffb"] = "ETCIÙ!"
S["ab3acc86"] = "Il regno un tempo florido e fiero di Dalaran incontrò un destino crudele quando arrivò la Burning Legion. I potenti Kirin Tor non esitarono a riportare la città dei maghi al suo antico splendore. Le sue guglie incombenti gettano un'ombra anche sulla montagna più alta di Alterac. $B$BLa barriera arcana che proteggeva la città e i suoi abitanti ha svolto il suo compito e, sebbene la città non abbia ancora aperto i suoi confini a tutti gli alleati, sta tendendo una mano d'accoglienza a chiunque sia disposto ad aiutare a far rifiorire di nuovo la sua magnificenza."
S["ab3ddd89"] = "Era la terza o la quarta volta che per poco non mi facevi sbudellare con una delle tue trovate da matti?"
S["ab3e63b9"] = "Monto questi Gyromechanic Gears e Restabilization Cogs, poi accendiamo il Ricombobulatore."
S["ab4565e1"] = "I furfanti bazzicano tutti in The Forlorn Cavern, a nord dei cancelli di Ironforge. Scommetto che lì ci trovi Fenthwick, di sicuro intento a contare le monete di qualche altro borseggiatore. Uno di questi giorni lo acchiappo!$B$BIntanto tengo d'occhio anche te, $Gragazzo:ragazza;."
S["ab472241"] = "Ecco il tuo pane, $Gsignore:signora;."
S["ab473b50"] = "Sì, dvvr! <PH>"
S["ab500364"] = "Lo Scourge è sconfitto! Darrowshire è salva!"
S["ab54423b"] = "Da queste parti, la banca più vicina che troverai è The Vault di Ironforge."
S["ab54af60"] = "Malvagi, malvagi, mortali! La foresta piange. Gli elementi si ritraggono davanti alla distruzione. Ivus deve spazzarvi via da questo mondo!"
S["ab5debd3"] = "Non voglio diventare il pasto di un ogre! Ti prego, salvami!"
S["ab5ff95b"] = "Non un passo di più, ogre!"
S["ab60463b"] = "Ti saluto, $R."
S["ab60c7c5"] = "Saluti, giovane $C. $GBenvenuto:Benvenuta; nella sala della Gilda dei Mercanti. Su Zephras le risorse per ora scarseggiano, ma qui dovresti trovare un po' di tutto, fra materiali e merci, per restare in perfetta forma durante le tue avventure.$B$BSe hai qualche domanda, chiedi pure."
S["ab61ae3b"] = "Se speri di imparare a fare $Gil sarto:la sarta;, devi cercare Me'Lynn, alla Craftsmen's Terrace, nella parte nordorientale di Darnassus."
S["ab671bfd"] = "Cosa cerchi alla mia forgia? L'addestramento? I segreti dell'acciaio, forse? I misteri della forgia? Parla, Grunt!"
S["ab73778f"] = "Ti dirò di più, Karnik, a tempo debito. Ma prima manda questo viaggiatore dal Consigliere Belgrum: c'è dell'altro da sbrigare."
S["ab76308e"] = "Più che altro, il solito. Attacchi di murlocs, qualche scaramuccia con la Scarlet Crusade. Ci sono perfino paladini che proprio non riescono ad abituarsi alla vita da Forsaken, e fin troppo spesso tocca a noi abbattere chi rivolge le lame contro i fratelli.$B$BIl peggio in assoluto è quando qualche schiavo senza mente si avvicina troppo. I murlocs posso ucciderli tutto il giorno, ma fra quelli del flagello che ho dovuto distruggere c'erano vecchi amici miei. Alcuni erano perfino miei familiari.$B$BMeglio che li abbatta io che un avventuriero qualunque, ma fa male lo stesso."
S["ab7adff3"] = "Per proseguire l'addestramento puoi rivolgerti allo stimato Doctor Gustaf VanHowzen. Lo trovi nella caserma di Theramore, a curare i feriti."
S["ab7fee80"] = "Oh cielo, che sorpresa! Un altro fallimento!? Ma come, o grande maestro??"
S["aba1d0cc"] = "Portami dei totem dei clan di Desolace e sono disposto a fare uno scambio."
S["abc0dac4"] = "Ho sete."
S["abc4bcee"] = "Voi così piccoli e gracili... voi non buoni servi per Kormok!"
S["abc4caa4"] = "Il cammino di $Gun:una; $C è fatto di determinazione, $Gfratello:sorella;. Puoi trovarla nella forza bellica, ma a farla durare è la tua Force of Will."
S["abc7ba11"] = "Alle forze Qiraji fu ordinato di ritirarsi e di nascondere il grosso dei loro numeri sotto le sabbie del deserto. Fu ordinato un piccolo attacco su Southwind Village mentre le prime linee dell'esercito dello Staghelm erano tenute impegnate."
S["abc8cd22"] = "Posso averne un altro?"
S["abcdfa06"] = "Che hai da guardare?"
S["abd1439e"] = "Tutta la potenza della Natura è al mio servizio, gracili mortali. Vediamo quale delle mie tante forme porrà fine alla vostra sofferenza!"
S["abd8bf5d"] = "Parla con me per una birra gratis alla Pig and Whistle!"
S["abdc9925"] = "Cosa ti incuriosisce?"
S["abe00bd0"] = "Aspetta... ne arrivano altri!"
S["abe21f30"] = "Sì, sono io. E a te che te ne importa?"
S["abe706e7"] = "%s ride come un folle."
S["abe7c492"] = "%s manca di nuovo..."
S["abecab93"] = "Fra i demoni che uno stregone può sperare di avere al fianco in battaglia, l'infernal è uno dei più potenti. È forte, ben corazzato e sferra colpi devastanti contro qualsiasi nemico. Se scegliessi di infondere nella tua arma lo spirito di un infernal, ne otterresti alcuni vantaggi — più salute, rigenerazione e simili.$B$BSe vuoi saperne di più sui felhounds, dovresti parlare con Wytula, qui di fronte a me."
S["abedb67a"] = "Quello che cerchi è Vesprystus, che sorveglia gli ippogrifi in arrivo e in partenza dalla base di Teldrassil. Per trovarlo, attraversa il portale nella parte occidentale di Darnassus: ti porterà a Rut'theran Village."
S["abf2afe1"] = "Già, e grazie di avermi lasciato riportare la mia mano ai sacerdoti, quella notte."
S["abf3b724"] = "Godetevi il tempo che vi resta da \"ospiti\" nel regno del mio signore, finché non giungerà, inevitabile, il suo giudizio. Non saprete quando, ma arriverà."
S["abf7b1c3"] = "Molto bene, che il tuo cammino nella sartoria cominci."
S["abf8db25"] = "Credevi che il tuo tradimento sarebbe stato dimenticato? Perso nell'insabbiamento accurato della mia morte? Sangue del mio sangue, la lama ha sentito la tua crudeltà a lungo dopo che il mio cuore aveva smesso di battere. E nella morte ho saputo cosa avevi fatto. Ma ora le catene di Kel'Thuzad non mi trattengono più. Vengo a fare giustizia. IO SONO BRANDICENERE."
S["ac040d13"] = "Vieni a parlare con me, e ciò che un tempo era nebuloso diverrà chiaro come il cristallo."
S["ac0d0e85"] = "Io sono Al'tabim the All-Seeing — inviato di King Rastakhan.$B$BFaccio affari con sacerdoti, maghi e stregoni."
S["ac12b6df"] = "Noo... o..."
S["ac1d89ef"] = "$N! Che ci fai qui a parlare con me? Dovresti essere là fuori a combattere l'Orda!$B$BHo degli ordini d'attacco per uno dei nostri marescialli di campo nel Field of Strife, ma mi serve qualcuno su cui poter contare.$B$BForse, se la tua reputazione presso la milizia Stormpike fosse più alta, potrei contare su di te..."
S["ac1f751c"] = "Attendiamo una partita di uova di drago nero dalle Burning Steppes. Crediamo che, studiandole, faremo avanzare enormemente le nostre conoscenze."
S["ac218960"] = "Mai mettersi contro un Nano!"
S["ac2f4082"] = "L'ultimo l'hai tirato tu, idiota. Tocca a me."
S["ac2fc4e0"] = "Non costringetemi, figli miei! Userò le vostre pelli per foderarmi gli stivali."
S["ac3672b9"] = "Grazie! Grazie, $C. Ora posso affrontare quei murloc con la Luce dalla mia parte!"
S["ac3f9a38"] = "Posso aiutarti?"
S["ac434d62"] = "Salute, $R. Il materiale bellico è in viaggio e dovrebbe arrivare alla Cenarion Hold entro un giorno. Possiamo solo sperare che, una volta lì, qualcuno che abbia ricomposto lo Scepter of the Shifting Sands si faccia avanti a suonare il gong e aprire le porte."
S["ac45b590"] = "Se usiamo la sequenza giusta, dovrebbe andare tutto bene. Solo che prima di cominciare ci vorrà parecchio studio."
S["ac56c4de"] = "Be', sei ancora qui. Direi che è una cosa per cui vale la pena bere."
S["ac5b894d"] = "Unisciti a noi!"
S["ac625710"] = "Obsidion, sorgi e servi il tuo padrone!"
S["ac728f8a"] = "Come se la cavano i miei uomini?"
S["ac75fa0d"] = "Vediamo se ti piace un assaggio di questo!"
S["ac7a2435"] = "La nostra ultima attrazione, e per te è gratis, aggiungerei: questi carri armati in miniatura, o Tonk, come li abbiamo astutamente chiamati, si comandano da una qualsiasi delle Console di Controllo dei Tonk sparse per la fiera.$B$BBasta attivare una console di controllo libera. Ogni tonk ha in dotazione i congegni standard e un potere speciale casuale da scatenare sul nemico!$B$BCombatti battaglie epiche con gli amici, fatti un giro o semina il caos più sfrenato... scegli tu!"
S["ac7e553e"] = "Non lo ammetto a cuor leggero, ma sei un fabbro molto migliore di me. Se vuoi imparare più dei miei miseri insegnamenti, ti consiglio di cercare un nano di nome Therum Deepforge a Stormwind. Lo troverai nel Dwarven District."
S["ac814026"] = "Sono Hydraxis, Duca dei Signori dell'Acqua. Tu non sei un elementale e la nostra lotta non puoi capirla, ma forse possiamo stringere un accordo che convenga a entrambi..."
S["ac886c39"] = "Salve, $R. Sono Tharnariun Treetender."
S["ac987fec"] = "Mulgore appartiene ai Galak!"
S["ac9f6e47"] = "BRUCIATE! Miserabili! BRUCIATE!"
S["aca20c75"] = "Ahah, ragazzina! L'Alleanza ha raccolto tutto quel che ci serve per far cominciare 'sta guerra! Magari l'Orda ci raggiungerà presto?"
S["aca31f37"] = "Mi dispiace, $C, ma prima che io possa lasciarti entrare ad Arathi Basin devi diventare più potente."
S["aca34af8"] = "Certo! A quale professione vuoi che ti indirizzi?$B$BTi segno sulla mappa dove trovare l'istruttore della zona che preferisci. Ricorda che dagli istruttori delle capitali puoi avere un addestramento più completo."
S["aca53dc6"] = "Minaccia analizzata! Attivazione del piano di combattimento beta! COCCODÈ!"
S["aca81250"] = "Ciao, $C. Da quel che mi hanno detto, è stato raccolto tutto, e proprio in questo momento tutto il materiale bellico viene spedito a Silithus. Dovrebbe arrivare tutto lì in pochi giorni. Una volta fatto, e una volta suonato il gong con lo Scepter of the Shifting Sands, la guerra comincerà davvero."
S["acb437fc"] = "Non posso addestrarti: devi rivolgerti all'istruttore della tua classe."
S["acb67ab1"] = "Ahh... sì! Qualcuno ha risposto alla chiamata. Accogli la tua fine con gioia!"
S["acbd5f24"] = "L'High Order custodisce le tradizioni degli Alti Nobili: domineremo la magia che tiene ancorata quest'isola e la piegheremo al nostro volere."
S["acbf0600"] = "Questa è terra consacrata, infedele."
S["acc042c9"] = "Sappi una cosa, Principessa — non sono in vena dei commenti che tu trovi carini o spiritosi. Sono qui per controllare che le ricerche dell'Arcidruido vadano avanti come previsto, e ho l'ordine di estirpare tutte le mezze calzette che non hanno la stoffa per servire nel mio amato Cenarion Circle."
S["acc2c4c0"] = "Popolo dell'Orda, cittadini di Orgrimmar, venite, radunatevi e celebrate $Gun eroe:un'eroina; dell'Orda. In questo giorno, $N, sotto gli auspici del nostro glorioso Capoguerra, ha inferto un colpo mortale al Black Dragonflight. La madre della covata, Onyxia, è stata uccisa!"
S["ace35d91"] = "Istruttore di Professioni"
S["ace5404d"] = "Dai la caccia a Deathclasp, $N? Però, mi hai colpito. Per colpa sua, solo questa settimana ho perso due dei miei uomini. Speriamo che a te vada meglio che a loro."
S["ace962bc"] = "Salute, $Gviaggiatore:viaggiatrice;! Che cosa ti porta da me?"
S["aceaa2d3"] = "Eseguo gli ordini del Capoguerra senza fare domande. Io sono Orda."
S["acf19f6c"] = "Le tue abilità si stanno facendo davvero straordinarie. Ora andiamo avanti con l'addestramento..."
S["ad0080dd"] = "Bethek"
S["ad0275cc"] = "Questo dovrebbe bastare! Almeno, sarà meglio che basti!"
S["ad03b090"] = "Dalle 6 di sera ci saranno i fuochi d'artificio dalla rupe più alta!"
S["ad0cd168"] = "Devo portare questo a Ratchet e niente mi fermerà!"
S["ad10822b"] = "Vi prego, ricordate ciò che vi abbiamo mostrato..."
S["ad19e720"] = "Teletrasporto di nuovo al centro"
S["ad20dba6"] = "In cambio della sua anima gli avrei insegnato a forgiare con l'arte dei demoni. L'anima di un orco Blackrock vale ben poco, ma in tempi duri come questi un'anima, qualunque anima, è meglio di niente."
S["ad236ab4"] = "%s comincia a ribollire!"
S["ad23f4d3"] = "Sono \"Plucky\" Johnson, e questo è il mio saluto predefinito."
S["ad253887"] = "Ahia! Ok, torno a lavorare, Åp!"
S["ad2b4020"] = "Perché tu lo sappia — siano pure veloci quanto vogliono, questi delinquenti, il mio primo colpo è per te."
S["ad425b19"] = "Ciao! Andrà meglio la prossima volta!"
S["ad54ac20"] = "%s sembra molto assonnato..."
S["ad56b81d"] = "Ecco il trituratore rubato! Fermatelo, o Lugwizzle ci spellerà vivi!"
S["ad5817ad"] = "È passato tanto di quel tempo da quando ero una principiante che non credo di essere la maestra migliore per te. Prova a parlare con Tarn o con Mak, qui vicino: uno dei due dovrebbe saper rispondere alle tue domande."
S["ad5851ac"] = "Sì, l'ho fatto. Sono $Gtornato:tornata; allo Scarlet Monastery, con grande sgomento del Mograine minore. Ho gridato, ho urlato, ho raccontato la storia a chiunque volesse ascoltarla. E per questo sarei $Gstato:stata; $Gassassinato:assassinata; a sangue freddo e $Gtrascinato:trascinata; in questa stanza — l'oscuro segreto dell'ordine. Ma qualcuno ha ascoltato... qualcuno ha udito le mie parole. Così è nata l'Argent Dawn..."
S["ad5b9574"] = "Cerco altro addestramento nelle vie sacerdotali."
S["ad6cdaf0"] = "<Il Sergente Stormpike fa il saluto militare.>$B$BNome, grado e numero di matricola, $Gsoldato:soldatessa;! A quei luridi cani Frostwolf non darai nient'altro!"
S["ad70060e"] = "Lomani towa zhi paw! Shtumani shtumani!"
S["ad70e2e1"] = "Vecchio re è morto? Inpossibile!"
S["ad77b22a"] = "Con l'Ingegneria avrai le abilità e le conoscenze per smontare gli avversari! Lascia che ti mostri come..."
S["ad79f725"] = "La morte è l'unica via di fuga!"
S["ad7a0346"] = "Sindaco Ello! I nostri esploratori del cimitero tornano con notizie sinistre..."
S["ad83af2e"] = "Ora c'è una sola via d'uscita — percorrere il sentiero solitario dei dannati."
S["ad8503bd"] = "Se c'è da scuoiare pipistrelli vili e simili, Rand Rhobart se la cava piuttosto bene. Sta in un accampamento lungo la strada a sud-est di Brill: esci dalla città per la strada di sud-est e all'incrocio prendi a est."
S["ad9b5d6d"] = "Compio un ultimo servizio. Spero che basti..."
S["adb347f8"] = "Parlami di Vanndar Stormpike."
S["adb9549c"] = "Coraggio, amici. Il rettile si dimenerà come una furia. È un gesto disperato. Quando siete pronti, datemi il via."
S["adbe0a6b"] = "In tanti anni ho imparato molto sulle pozioni, $N, e quello che so è a tua disposizione. Non devi far altro che chiedere."
S["add17d8e"] = "%s segue felice $N come suo nuovo germoglio."
S["add88627"] = "Certo che mi ricordo quella notte. Due dita più a sinistra e adesso berresti con quell'elfo, Morris. Ed era pure la mia camicia migliore."
S["ade1184d"] = "Ma..."
S["adf53183"] = "Sei $Garrivato:arrivata; più lontano di molti, $N. Rispetta gli elementi che hai intorno, e te la caverai molto meglio della maggior parte della gente."
S["adf54931"] = "Ciao! Sei proprio la persona che cercavo. Siediti e ascolta, perché ho un piano che ci farà ricchi tutti e due!"
S["adf58f3b"] = "Ho finito il tuo elmo, $N."
S["adf68fe4"] = "Mi chiedi dei Sons of Cenarius, Remulos e Zaetar.$B$BMio padre, Remulos, era forte e bello; mio zio, Zaetar, molto astuto e minuto di corporatura. Erano rispettati più o meno allo stesso modo, eppure Zaetar sentiva sempre che non avrebbe mai eguagliato la gloria e le attenzioni che, secondo lui, aveva Remulos.$B$BDopo che io e le mie sorelle siamo $Gnati:nate;, Zaetar, accecato dalla gelosia, si è messo in testa di superare il fratello... ed è stato l'artefice della propria fine. Nemmeno col passare del tempo la tristezza che mi provoca si è mai attenuata..."
S["adf77d63"] = "Ottimo, $C! Il nostro maestro di battaglia, Thelman Slatefist, si trova nelle sale delle udienze del Re, all'interno di Stormwind Keep. Ti aiuterà a raggiungere l'Alterac Valley."
S["adfa3b7e"] = "%s è $Gindebolito:indebolita; dal globo!"
S["ae05234e"] = "Prima che ti insegni un'abilità di cavalcatura, devi essere $Gosannato:osannata; presso i troll della tribù Darkspear, $C."
S["ae06ac23"] = "Ah, $Guno:una; dei miei clienti preferiti. Hai l'aria di $Guno stregone:una strega; di un certo potere, $N. Piacere di conoscerti. Se posso fare qualcosa per te, chiedi pure, ti prego.$B$BIo e mio fratello crediamo che saranno quelli come te a guidarci nella prossima grande era. Con un potere così... un controllo così... è solo questione di tempo prima che persino la Legione si pieghi alla tua volontà.$B$BTi invidio solo un po'."
S["ae11a9ed"] = "Ecco a te, $N."
S["ae174637"] = "Ciao, $N. Avresti un po' di tempo per due chiacchiere?"
S["ae1a1332"] = "%s arrossisce."
S["ae269a64"] = "Lo Stormpike Graveyard è scavato nelle montagne, oltre il ponte a est di Dun Baldar.$B$BAl momento nessuna delle due fazioni lo controlla."
S["ae299705"] = "È semplicemente orribile. I nostri tre assi migliori sono stati abbattuti sul territorio dell'Alleanza durante un assalto aereo. Nessuno sa se siano morti o vivi!$B$BÈ un duro colpo per le nostre capacità di attacco aereo."
S["ae2c49e0"] = "Allora è con grande orgoglio che ti dico che Brakgul Deathbringer è pronto nell'Hall of Arms ad aiutarti nel tuo viaggio verso la Warsong Gulch. Cercalo nella Valley of Honor."
S["ae2c67e1"] = "%s non è impressionato."
S["ae36126e"] = "La Frostwolf Keep è stata rasa al suolo! Ci servono rifornimenti per riparare e ricostruire!"
S["ae4a62e6"] = "La Frostwolf Relief Hut è sotto attacco! Se nessuno interviene, l'Alleanza la conquisterà!"
S["ae4c3b51"] = "Avete sfidato i Sette, e ora morirete!"
S["ae4d7009"] = "Ora, guarda..."
S["ae54111a"] = "Maestro di Battaglia"
S["ae5796d9"] = "Così lontano da Ironforge non se ne vedono molti, di Fabbri. Cosa posso fare per te?"
S["ae5843b7"] = "Cosa? Oh no, non mi interessa quello che hai da dire. Mi piace solo infliggere dolore."
S["ae5dcd27"] = "I campioni di sangue vanno protetti! Distruggete gli intrusi!"
S["ae5fad44"] = "I Figli di Arugal si solleveranno contro chiunque sfidi il potere dei Moonrage!"
S["ae636973"] = "Si è superato il limite. Come osa lo Scourge attaccare Stormwind! Distruggetelo prima che ne arrivino altri!"
S["ae67f793"] = "Sì, anch'io ho un po' di roba da consegnare. Lo trovi andando a nord lungo la strada per Orgrimmar: lì chiedi a uno dei grunt."
S["ae7172fc"] = "Mai mettersi contro un Dark Iron, $C."
S["ae717451"] = "Mai metterti contro un Dark Iron, $N."
S["ae7d0cb4"] = "Torna regolarmente a trovarci qui all'High Order. Ogni tanto potremmo avere qualche incarico da affidarti. Nel frattempo, buona fortuna per le tue avventure!"
S["ae8244b7"] = "Va' a cercare Zando'zan nella Cleft of Shadow. Ci sono un paio di gallerie che scendono in quella caverna: una appena a sud di Valley of Wisdom e l'altra in The Drag."
S["ae842b4a"] = "Niente libera lo spirito come librarsi nel cielo. Un posto così c'è nel nostro grande centro tribale, Thunder Bluff: ti ci porta la strada che esce a nord da Bloodhoof Village. Una volta $Gsalito:salita; in cima con l'ascensore, parla con uno dei Bluffwatchers, che potrà darti altre indicazioni."
S["ae8e3bba"] = "Le vostre morti nutrono la mia forza!"
S["ae8f3f90"] = "Ehh? Per fare affari con me mi sembri un po' troppo $Ginesperto:inesperta;.$B$BTorna quando avrai capito un po' meglio come girano le cose da queste parti. Fidati."
S["aeaf2bd4"] = "Sono tutti... morti?"
S["aeafd8c7"] = "C'è un compito che vorrei che svolgessi prima di andare avanti..."
S["aec69e84"] = "Ah, guarda che ora! Devo tornare al mio posto... lassù."
S["aec99ac1"] = "Ora lo mescolo con cura... ops! ...Beh, ne ho versato un po', ma è pronto!"
S["aecdc409"] = "Cerchi Shenthul of the Shadowswift Brotherhood, eh? In The Drag, di fronte a Recuperi Droffers e Figlio, cerca un tunnel che scende nella Cleft of Shadow."
S["aecef5d6"] = "%s rompe il sigillo della lettera di Anton e comincia a leggerla."
S["aed3a9b5"] = "L'Un'Goro Crater essere molto a sud di Kalimdor, oltre Thousand Needles, in Tanaris. Cerca le grandi pietre sospese nell'aria... segnano l'ingresso del Cratere. Ma fai attenzione... la strada non è facile. I raptors stanno poco lontano dall'ingresso."
S["aed7b226"] = "Ah, dunque i miei servitori delle Burning Steppes hanno portato i draghi..."
S["aede8638"] = "Che piacere pescare, mon. Capisci? Se ho trovato la beatitudine lo devo al mio maestro, il più grande pescatore del mondo intero — Nat Pagle. Ne hai mai sentito parlare, mon?$B$BSe cerchi l'illuminazione, è Nat Pagle che ti mostrerà la via."
S["aee28e8f"] = "I troggs... non finiscono mai di arrivare. Muori, trogg! Muori!"
S["aee30dec"] = "Per un accampamento tutto tuo basta un semplice fuoco da campo. Di solito sono i cuochi che possono insegnarti a farlo."
S["aee9f792"] = "L'A-Me buona. Buona, l'A-Me. Segui... segui l'A-Me. Casa. L'A-Me va a casa."
S["aeed5ea4"] = "%s riporta in vita un servitore non morto!"
S["aef9d623"] = "Allora vieni, eremita!"
S["af035482"] = "Le nostre unità veterane stanno lasciando il campo. Ci servono altri rifornimenti!"
S["af03827f"] = "Salve, $Gstraniero:straniera;, e $Gbenvenuto:benvenuta; nel maestoso e indomito Un'Goro Crater!$B$BIo sono Williden Marshal. Con mia sorella e i nostri compagni formiamo la Marshal Expeditions — scienziati ed esploratori del vasto e selvaggio ignoto di Azeroth.$B$BQui abbiamo incontrato qualche intoppo, e ci servirebbe aiuto, se hai tempo!"
S["af03c002"] = "%s si sta innescando. T meno 60 secondi."
S["af0caff4"] = "Sei proprio $Gun allievo determinato:un'allieva determinata;. Sarò felice di istruirti!"
S["af16be13"] = "Vai dritto nella parte nord-occidentale della Valley of Honor: lì troverai l'Hunter's Hall."
S["af17811c"] = "Testo Generico2"
S["af215c3a"] = "Me ne sto chiusa in questa casetta e sogno di unirmi alle battaglie che infuriano fuori dalle mura della città. Eppure il dovere mi impone di condividere il mio sapere con chi combatte al posto mio... per ora."
S["af221d06"] = "Che ci viene a fare $Gun:una; giovane $C come te da un vecchio contadino come me?"
S["af22320c"] = "Hai qualche spicciolo?"
S["af35facb"] = "Quei progetti si pagano in ossa: le TUE OSSA!"
S["af3f01b8"] = "$GL'unico:L'unica; $R $Gbuono:buona; è {un $R} $Gmorto:morta;!"
S["af40cb16"] = "Lo Snowfall Graveyard è stato conquistato dall'Alleanza!"
S["af4a055e"] = "Dite al Custode che adesso questa prigione è nostra!"
S["af546c63"] = "Ho abbastanza rifornimenti per promuovere le nostre truppe a campioni."
S["af5b96e6"] = "$GBenvenuto:Benvenuta; al rifugio, $N. C'è chi viene qui con uno scopo e chi ci è capitato per caso... Ma pare che ognuno abbia una storia tutta sua da raccontare."
S["af6705b1"] = "%s fa esplodere uno dei suoi servitori Firesworn!"
S["af6a2b57"] = "Cra!"
S["af6a43ba"] = "La Locanda"
S["af6d28c6"] = "Schiacciare!"
S["af73a888"] = "Grazie mille, $N!"
S["af7d1d85"] = "Sono Krathok e sorveglio questi artigiani."
S["af7fe2b2"] = "Ce l'abbiamo fatta! Ce l'abbiamo fatta! Li abbiamo scacciati!"
S["af82711e"] = "Va bene! Va bene! Ci arrendiamo... Mettete giù le armi, collaborerò!"
S["af8797d0"] = "La tua non-morte non è la fine della tua vita, ma l'inizio. Ora sta a te decidere dove si trova il tuo destino."
S["af96b754"] = "Nessuno passerà!"
S["af9c4dc1"] = "Grazie per aver tolto di mezzo quegli stupidi senatori. Ora preparati ad affrontare la tua fine per mano del più potente servitore di Ragnaros."
S["af9c8f73"] = "Lon odes veld vastrungen. Lon nagan ko vrum regen ko gol."
S["afa01877"] = "Siamo vicini alla fine, non fermatevi."
S["afa689b3"] = "Alla prossima, $Gvaloroso:valorosa;."
S["afaabe1e"] = "Gli Shen'dralar erano gli arcanisti più venerati di Queen Azshara. Proprio fra queste mura si sbrigavano le richieste più importanti della Regina — spesso in segreto.$B$BDopo la distruzione del Pozzo e il torpore che poi ha colto gli Highborne e le sette minori degli elfi della notte, Tortheldrin, il Principe di Eldre'Thalas, ha cominciato a costruire i piloni che vedi sparsi per le sale dell'ala ovest."
S["afb4e0ba"] = "Me ne sono andato. Non sarei rimasto con i Blackrock. No, i miei figli non sarebbero morti invano. Non avrei servito sotto un maniaco inetto e assetato di potere come Rend.$B$BHo trovato rifugio nei boschi di Lordaeron e ho vissuto da eremita vicino a Hearthglen."
S["afb94268"] = "%s barcolla all'indietro mentre la freccia gli si pianta a fondo nel petto."
S["afc4bb46"] = "Scusate, so' in ritardo."
S["afca6d6a"] = "C'è perfino un terribile spettro della foresta! Tutto vestito di nero e... con un'aria malvagia! Ve lo dico io, è un posto maledetto! *hic*"
S["afda1a42"] = "Da, adore an!"
S["afe7aa66"] = "Larion, voglio aiutarti a combattere questi parassiti!"
S["afea8d09"] = "Salve, $Gmago:maga;! $GPronto:Pronta; per un po' di addestramento?"
S["aff5c48f"] = "Alla fine è andato tutto bene."
S["b00048ff"] = "Allora, ho trovato questa shackle key..."
S["b014fa5c"] = "Lui stare in anello interno di Rogues' Quarter."
S["b015f0c5"] = "La Luce condanna tutti coloro che danno rifugio al male. Ora morirai!"
S["b01839eb"] = "Beh, allora, per fondare una gilda ti servono dei documenti, e Jondor Steelbrow può aiutarti ad avviare la pratica. Quando sei $Gpronto:pronta; a cominciare, lo trovi all'Ironforge Visitor's Center."
S["b0192b71"] = "Molte volte le mie lame hanno abbattuto il bersaglio prima ancora che si avvicinasse. Il segreto sta nel colpo di polso."
S["b01ff77d"] = "Le foreste sono invase da strane bestie e una corruzione immonda riempie l'aria."
S["b02445e9"] = "Sono tantissime le persone che l'Alchimia può aiutare! È la passione della mia vita."
S["b02a8145"] = "Papà!"
S["b036a619"] = "Uccidi, UCCIDI! Riprendi manufatto! Porta a Kartak!"
S["b03b120b"] = "Come osi! Inaudito! Ti maledico, $C. Ti maledico con... la morte!"
S["b04088e7"] = "Proprio come Teldrassil, anche Dolanaar abbraccia chi abbraccia la terra."
S["b0439258"] = "Il tuo compito è concluso. Preparati ad andare incontro alla tua fine."
S["b04a0a28"] = "C'è un vento furioso in arrivo — me lo dice il dolore al ginocchio scoperto. Spero solo che non ci finiamo in mezzo."
S["b04b5016"] = "Tutto il cibo e il materiale bellico che abbiamo raccolto è in viaggio verso Silithus. Dovrebbe arrivare fra pochi giorni. Qualcuno mi ha detto che, una volta radunato tutto nei pressi di Cenarion Hold, qualcuno dovrà andare a suonare il gong alla Scarab Dais per aprire le porte di Ahn'Qiraj e dare inizio alla guerra."
S["b04ca397"] = "Myolor, un tempo ero $Gun forgiatore di armature:una forgiatrice di armature; e vorrei invece imparare la via del forgiatore d'armi. Mi insegnerai?"
S["b04d9ab2"] = "Merci in vendita! Merci in vendita! Venite a dare un'occhiata alla merce di Antonio prima che debba andarmene, cittadini di Goldshire."
S["b04fcbb0"] = "Anche il guerriero più coraggioso deve essere ben rifornito, se vuole affrontare i suoi nemici con forza!"
S["b0509ab3"] = "Che istruttore di professioni stai cercando?"
S["b05489e2"] = "$N! Finalmente!$B$BDevi prendere questo segnalatore e piantarlo nel cratere orientale dei campi di battaglia centrali. Il mio stormo attaccherà quando il segnalatore trasmetterà le sue coordinate!"
S["b054f5df"] = "Ammirate Ragnaros, il Firelord! Colui che era antico quando questo mondo era giovane! Inchinatevi davanti a lui, mortali! Inchinatevi davanti alla vostra fine!"
S["b0557265"] = "Mia Royal Dreadguard, ve ne occuperete come si addice al vostro rango. O così, o vi pentirete di non averlo fatto."
S["b057a18f"] = "Che cosa sta succedendo? Quale forza mi attira verso l'Altare delle Maree!"
S["b05a0010"] = "Necessiti di una guida per raggiungere la tua destinazione?"
S["b05c21db"] = "Per l'Orda!"
S["b063aabb"] = "Il taglianuvole in partenza per Dalaran è appena arrivato. Tutti a bordo per Dalaran!"
S["b069003b"] = "Uthrok fare bel tiro"
S["b06acf45"] = "Elder Morningdew si è messa a osservare il trambusto alla Mirage Raceway di Thousand Needles."
S["b06b65bf"] = "I progetti della mia siringa per arrosti alta venti piedi sono quasi pronti! Adesso mi manca solo un tacchino alto venti piedi..."
S["b06e5000"] = "Feugen fa padrone felice."
S["b073e1fa"] = "Un segugio all'orizzonte che corre a trenta piedi al secondo. Resta solo una domanda, occhio destro o sinistro. Proprio così, $Gragazzo:ragazza;, sono così $Gbravo:brava;."
S["b0792abb"] = "Ho sentito che gli ultimi preparativi vengono spediti a Silithus e dovrebbero arrivare in meno di un giorno. Non voglio vedere uno di quegli insetti scavarsi la strada fino alla mia miniera, quindi spero che qualcuno si stia prendendo il tempo di ricomporre quello Scepter of the Shifting Sands, così si potrà suonare il gong, aprire le porte e cominciare finalmente la guerra."
S["b079ae24"] = "Sono davvero colpito, Gerard. Pensavo che fossero solo chiacchiere, ma vedo che mi sbagliavo."
S["b084e56b"] = "Golganar, . Gar moth-tur, a thorneb angor dagum dun thon ta dun dun!"
S["b090d95d"] = "Lo Stonehearth Bunker è stato conquistato dall'Alleanza!"
S["b09429ff"] = "%s punzecchia ripetutamente la pecora lanosa."
S["b094d175"] = "Osi profanare il Frostmane Hold, $R. Preparati a morire!"
S["b094e2ac"] = "Ladri? Smettetela di nascondervi e affrontatemi!"
S["b09b4d02"] = "L'istruttore dei maghi lo trovi nella dimora dell'High Order, al margine sudorientale del villaggio."
S["b09b7860"] = "Maialini, avete fame? Ho del cibo per voi..."
S["b0a54e33"] = "Ce li hanno rubati, $R! Tre dei nostri volumi più preziosi. Se riporti i tomi, una ricompensa è assicurata."
S["b0a6e8b9"] = "Senti il potere della Brotherhood!"
S["b0aa56f1"] = "Qualcuno può dare una casa al mio adorabile gattino in più?"
S["b0aad8f2"] = "Salve, $N. Siamo venuti da Moonglade per portare ovunque lo spirito del Festival Lunare.$B$BPerché non ti unisci ai nostri festeggiamenti?"
S["b0ad0cdf"] = "Eranikus, Tyrant of the Dream viene completamente consumato dalla Light of Elune. La tranquillità scende sulla Moonglade."
S["b0af51ca"] = "Questa guerra ci ha presi talmente che alcuni di noi si sono dimenticati di trovare tempo per l'amore."
S["b0afd7db"] = "Che esplosione fantastica! Hai visto quanto era grande?"
S["b0b15557"] = "Il tuo lavoro non lo loderei mai abbastanza: con martello e incudine fai cose davvero straordinarie. Ora, non andare a dire in giro che ti ho consigliato di cercarti un goblin come maestro, ma è proprio quello che farò. Si chiama Brikk Keencraft, e l'ultima volta che ho sentito parlare di lui mandava avanti una bottega giù a Booty Bay."
S["b0c25357"] = "Dove sono finiti tutti?"
S["b0d6f78e"] = "Allora, facciamo finta che tu porti a termine il lungo e arduo compito di creare il flagello che serve a infrangere le protezioni demoniache poste sulla triade. E poi che mosse faresti? Andresti ad affrontare il Profanatore nella sua tana?$B$B<Loramus ride.>"
S["b0da4b9c"] = "%s emerge per proteggere la Fathom Stone!"
S["b0e5da29"] = "Sì, giovane, non serve che tu mi convinca di queste cose: io e il Capoguerra abbiamo un lungo passato in comune. Ma la tua dedizione non passa inosservata.$B$BCome dicevo, Rend aveva trovato una nuova casa per il suo popolo, e io ero fra quelli che, stanchi, lo avrebbero seguito.$B$BDa un conflitto ne sono nati altri... innumerevoli altri. In quelle battaglie per Blackrock Spire, fra il clan Blackrock e i nani Dark Iron, mi hanno ucciso tutti e due i figli. È stato allora che ho capito che il mio tempo nel clan Blackrock era finito."
S["b0f08e8c"] = "%s sghignazza."
S["b0f52aae"] = "Ciao. No, Marvon non è qui di sicuro, e per un bel po' non tornerà. A dirla tutta, comincio a essere un po' preoccupata per lui...$B$BSpero che torni presto. Gli è arrivata una grossa cassa, ma è troppo pesante e non riesco a trascinarla qui dentro! Ho dovuto lasciarla fuori, vicino alla porta..."
S["b0f6010a"] = "Ho un'altra domanda."
S["b10839ea"] = "Bene, io vado dai Gelkis. Non sono stupidi come i Maraudine, ma sono più ragionevoli."
S["b10e5c05"] = "Mi dispiace, $C, ma non sei ancora abbastanza $Gesperto:esperta; per entrare a Warsong Gulch."
S["b112396c"] = "La fine si avvicina! Proprio mentre parliamo, le nostre provviste vengono spedite verso Silithus e dovrebbero arrivare fra pochi giorni. Una volta lì, sono $Gsicuro:sicura; che tutto verrà radunato in fretta, e poi aspetteremo che il gong suoni alle porte di Ahn'Qiraj per dare inizio alla guerra. Non vedo l'ora di analizzare se i nostri sforzi di preparazione faranno la differenza."
S["b1143033"] = "%s svanisce."
S["b11ca56e"] = "OZZIE!!!! OH NO!"
S["b120636a"] = "Che fortuna. Di solito devo lasciare la mia tana per nutrirmi."
S["b1227b01"] = "Finalmente siamo arrivati, grazie a te, $N! Senza il tuo aiuto saremmo diventati il pranzo di qualche lucertola troppo cresciuta!"
S["b128cacb"] = "Quando la terra smise di tremare, si rivelarono le sue vere intenzioni. Eravamo intrappolati, e lui prosciugava lentamente i nostri poteri."
S["b12c8a82"] = "Oh, amore mio! No! Non lasciarmi morire senza di te..."
S["b1328db2"] = "Addio."
S["b139c351"] = "Che succede? Gli orchi si avvicinano già?"
S["b141118a"] = "%s fa un profondo sospiro."
S["b149211b"] = "Hai qualche ragno o scarabeo, $C? Zampettano svelti, ma se sei più $Grapido:rapida; tu, scoprirai che sono una vera delizia!"
S["b154e970"] = "Coprimi, provo a scappare!"
S["b156bf2e"] = "Il Wind Rider Roost sta in cima alla scalinata del totem, al centro della città."
S["b158f1a6"] = "Scappate! Stanno arrivando!"
S["b1608b73"] = "Mi è sembrato di sentire qualcosa."
S["b1632c9e"] = "Quando ti rimetteremo in piedi, cominceremo a lavorare su quel fucile da tasca! Gliela faremo vedere!"
S["b166cd3d"] = "La Dama Oscura ha lanciato la sfida: tocca a noi raccoglierla."
S["b16d1bc9"] = "%s inizia a evocare una Creatura di Lava!"
S["b177d7ee"] = "La forza del corpo è potenza e rapidità d'azione. Devi tenerti sempre in forma, nel fisico come nella mente. La mole dell'orso ne fa risaltare la forza, perché in combattimento è un nemico feroce. Ma dietro quella mole si nascondono un'agilità sciolta e una mente acuta: sorprese che userai a tuo vantaggio.$B$BPer padroneggiare la via dell'Artiglio devi affidarti alla forza del corpo dell'orso."
S["b17ac652"] = "Porta i miei saluti al Comandante Trebor, $R."
S["b17ff42c"] = "Quando mi agitano per bene, senti come grido..."
S["b187f6c9"] = "Sono $Gpronto:pronta; a trovare lo squirrel, Monty."
S["b1951e05"] = "Da qualche tempo il flusso e il riflusso della magia sono turbati. Dicono che perfino i maghi di Dalaran ne siano perplessi. Da dove viene questa perturbazione: dalle forze arcane, o sono gli elementi stessi a essere in subbuglio?"
S["b198a79e"] = "Per evocare un Destriero del Terrore, devi prima creare un Cerchio della Grande Evocazione. Un portale per Xoroth si può creare solo dall'interno di un cerchio simile.$B$BIl Cerchio della Grande Evocazione richiede tre potenti strumenti: una Campana di Dethmoora, una Ruota della Marcia Nera e una Candela del Giorno del Giudizio."
S["b1a0b19b"] = "Mi fa piacere la compagnia, ma diciamocelo: con le pozioni hai più esperienza di me. Se vuoi addestrarti, parla piuttosto con Doctor Marsh: è un Forsaken e sta nell'Apothecarium of the Undercity."
S["b1a4b80c"] = "%s trasforma gli oggetti che $N gli ha dato in un totem di purificazione..."
S["b1b0adc9"] = "Le pagine di questo tomo sembrano cambiare contenuto di continuo. Hai la sensazione che il libro ti prosciughi i pensieri dalla mente e li consumi."
S["b1b42af4"] = "Sei $Gvenuto:venuta;. Lo ammetto, sono $Gsorpreso:sorpresa;."
S["b1b49071"] = "Ah, davvero? Non mi pare proprio quello che avevo chiesto.$B$BÈ chiaro che questa pozione è inerte: non provocherà più nessuna reazione. Per i miei studi, quindi, non serve a niente.$B$BRiportala ad Alessandro. Forse la prossima volta che mi manda una pozione troverà qualcuno più svelto.$B$B<Il Dottor Felben fa un gesto di sufficienza con la mano.>"
S["b1b64a8e"] = "Kodo beasts, $Gamico mio:amica mia;! Addestrati fin da piccoli e cresciuti nelle Golden Plains of Mulgore, sono ottimi animali che diventeranno cavalcature ancora migliori! Prego, dai pure un'occhiata a quello che ho da offrirti, e scopri con i tuoi occhi perché noi tauren ci affidiamo a queste magnifiche creature!"
S["b1b76acb"] = "$N UCCIDE! $GLui:Lei; uccide voi adesso! SCAPPA! SCAPPA!"
S["b1b7a219"] = "Prova a cercare a Stormwind: credo che lì avrai più fortuna. Lassù chiedi a una guardia e ti indicherà la strada."
S["b1c16034"] = "Che le fiamme del caos vi divorino!"
S["b1c5f430"] = "Gli elementali che ci hanno portati qui non ci sono più. I prodigi con cui mantenevano le nostre case si possono tentare con la magia degli alti nobili, ma a Skywall i nostri poteri si sono indeboliti."
S["b1ce778a"] = "Alegorn è un cuoco straordinario, e ha avuto secoli per perfezionare la sua cucina. Dovresti considerarti $Gbenedetto:benedetta; se decidesse di insegnarti. Lo trovi nella Craftsmen's Terrace, se credi di esserne $Gdegno:degna;."
S["b1d37892"] = "Ehilà, mon. Per imparare a usare arma nuova, tu $Gvenuto:venuta; in posto giusto."
S["b1dafadf"] = "Tieni la porta chiusa, $C. Non si sa mai quando ripasseranno di qui i Dark Riders."
S["b1dd17ab"] = "Ce l'ho fatta! Ho imbrigliato il potere della pietra negli occhiali! Andiamocene di qui!"
S["b1dd58ba"] = "Ho salvato la pelle, combatterò un'altra volta!"
S["b1e91f62"] = "Le Siege engines sono l'orgoglio di ogni pilota!"
S["b1f3b939"] = "Maraudon si trova nella Valley of Spears, a metà della costa occidentale di Desolace."
S["b1fbd78f"] = "Mio signore, è arrivato il vostro ospite. Vi sta aspettando."
S["b21682a9"] = "Faresti meglio a non fare la spia su di me!"
S["b21d0bbe"] = "Sì, $Gamico:amica;, tu stare cercando il Jandi's Arboretum. L'ho detto davvero? Glok'tar, devo essere $Gstanco:stanca;! Dietro l'Asoran's Market, in Valley of Wisdom, sali le scale di legno che portano su verso The Drag: quello di Jandi è lassù, al livello superiore."
S["b2245c32"] = "Guardate il sangue che penetra nella neve, figli miei. L'elementale sarà legato a noi!"
S["b22a4d90"] = "%s, chiaramente $Gsconfitto:sconfitta;, cerca di fuggire."
S["b22ba265"] = "In momenti come questi divento $Gtutto:tutta; sentimentale..."
S["b234e6b1"] = "Enu thora'serador. Questo è un luogo sacro."
S["b235e45f"] = "Ah sì, ora mi è familiare. Tu va' avanti e di' a Liladris che arriverò presto, d'accordo?"
S["b24382a6"] = "Avanti!"
S["b249a154"] = "Sono io che li tengo a pancia piena, $Gragazzo:ragazza;. Già, Daryl Riknussun, al tuo servizio."
S["b2633c80"] = "Se ti serve addestramento, dovresti parlare con Lyria. Di solito la trovi dietro la fucina, ad aspettare che sia pronta qualche armatura o arma."
S["b26b1b69"] = "Lunga vita ai Dragonmaw! Muori, inutile troll!"
S["b27bbd79"] = "Grazie, $N. Ti ringrazia anche mio fratello."
S["b27e0c22"] = "Saluti! Sono qui per promuovere un torneo a Stranglethorn che metterà alla prova quanto sai pescare. Per partecipare devi essere abbastanza forte da sopravvivere laggiù e pescare abbastanza bene da convincere i pesci a uscire dall'acqua.$B$BTorna più tardi, quando sarai più $Gqualificato:qualificata;!"
S["b2851d46"] = "SEI TU $GIL VINCITORE:LA VINCITRICE;!"
S["b2898e1a"] = "Ciuf-ciuf, tuu-tuu! Buona Hallow's End, $N!"
S["b2899bf7"] = "%s ha disattivato la regione fantasma."
S["b2a42426"] = "È vero? Nei canali ci sono davvero i crocolischi?"
S["b2a76ad5"] = "LIBERTÀÀÀÀÀÀÀÀÀÀ!"
S["b2c081c0"] = "È ora che la Carovana di Lentecurva riparta! Torneremo presto, ma se non puoi aspettare, vai a nord verso il Kormek's Hut. Apriamo bottega tra circa un'ora."
S["b2c5e001"] = "Per il Blu!"
S["b2c7a686"] = "Sono $Guscito:uscita; dalla pancia di questa bestia da nemmeno due minuti e c'è già chi mi fa domande sulle mie abitudini in bagno??? Signorinella, per una domanda del genere ti avrei presa a sberle, se non fossi stata tu a salvarmi!$B$BComunque! Ti sono $Ggrato:grata; per l'aiuto. Forse posso sdebitarmi?"
S["b2c9f9ff"] = "Hmmmm, solo un po' di attività in superficie, ma il sole è nel posto giusto. Potrebbe rivelarsi una bella giornata."
S["b2cae5e2"] = "Per dare luce, bisogna bruciare."
S["b2cbb52c"] = "L'Icewing Bunker è sotto attacco! Se nessuno la ferma, l'Orda lo distruggerà!"
S["b2d047ba"] = "Throm'ka, $C. Tutto il materiale bellico è in fase di preparazione finale e sta per essere spedito a Silithus. Dovrebbe arrivare nei prossimi giorni. Con l'equipaggiamento pronto e le nostre forze schierate, non dovremo far altro che aspettare che qualcuno suoni il gong sulla Scarab Dais: questo dovrebbe aprire i cancelli di Ahn'Qiraj e dare inizio alla guerra.$B$BLok'tar Ogar!"
S["b2d072ba"] = "Eh, eh... $GSei un bel curiosone:Sei una bella curiosona;, eh, $N? Be', ecco cosa devi fare.$B$BA nord di qui, fra le vecchie rovine, vive uno gnoll molto scorbutico che si chiama Miblon Snarltooth. Sorveglia l'unica Evoroot che io conosca e non la perde d'occhio né di notte né di giorno! Pare che non dorma neanche!$B$BPuoi corromperlo. Ti vendo un'esca che gli piacerà — posala vicino a lui e lo distrarrà quanto basta per prendere l'Evoroot. Buona fortuna!"
S["b2e0fb9a"] = "Che la luce guidi il tuo cammino e ti assista nei viaggi. Se mentre dai un'occhiata ti serve aiuto, sono qui."
S["b2e1aa5b"] = "Nelle acque della parte settentrionale della Sar'theris Strand a Desolace o nell'Angor Fortress nelle Badlands ci sono scrigni chiusi a chiave che si possono scassinare."
S["b2e27cd9"] = "Un Cacciatore, eh? Be', allora devi parlare con Thorfin Stoneshield, nel Dwarven District.$B$BOh, e non dimenticare di dirgli che, se pesto un'altra volta i bisogni del suo famiglio, gli altri cacciatori li addestrerà da dietro le sbarre della Stockade!"
S["b2e2f51c"] = "Bah! Fallito di nuovo!"
S["b2ec3404"] = "%s crolla, ma il corpo spezzato si rialza!"
S["b2ece1e2"] = "Ci sono molti ostacoli da superare sulla via dell'eccellenza. La tua via non fa eccezione..."
S["b2ef3c3e"] = "Morte agli Stormpike!"
S["b2f17fcf"] = "Fregata in vista! È una nave degli Orchi, non c'è dubbio! Fuoco!"
S["b2fadf7b"] = "Mi sa che ti farebbe comodo un po' di lavoro, $Gragazzo:signora;. Dovresti salire sul tram e andare a trovare mio fratello, Monty, al deposito del Deeprun Tram di Ironforge. Sono $Gsicuro:sicura; che ha qualcosa da farti fare."
S["b2fe08ff"] = "Ho un pezzo di ferro nella schiena che mi ricorderà quella notte per il resto dei miei giorni."
S["b302e0ff"] = "Gli antenati veglino su di noi."
S["b304ddf6"] = "Kalaran, per favore, incanta la torcia."
S["b3119f4a"] = "È con soddisfazione che ti comunico che abbiamo raccolto tutti i fiori di loto purpurei che riteniamo necessari. Grazie per il tuo contributo, $C. Se ti va, molto probabilmente qui ci sono ancora diverse persone che raccolgono altre risorse per la lotta."
S["b3216651"] = "Ti prego, aiutami, fratello...$B$BPresto lascerò questo mondo. Ora soffro, ma so che quando me ne sarò andato non soffrirò più. La fauna, però, fratello mio... soffre anche lei, e non conosce liberazione. Con gli ultimi respiri che mi restano, ti chiedo aiuto."
S["b32494b1"] = "Da bere gratis al Blue Recluse!"
S["b325c0d0"] = "Credi che mi metta a tremare davanti alla possente legione di $N?$B$BPer me non sei niente. Meno di niente. Se avessi voluto la tua testa, me l'avrebbero portata su una picca.$B$BHai fatto lo stesso errore di tutti i mortali.$B$B<Lord Victor Nefarius sospira.>$B$BIl tempo fa strani scherzi a chi lo usa come moneta."
S["b3331d98"] = "Come posso aiutarti nel tuo viaggio?"
S["b3380465"] = "Ah, $Gsacerdote:sacerdotessa;, sei arrivat$Go:a; proprio al momento giusto. Te ne sono grato."
S["b33eb256"] = "Un'altra mandria radunata con successo!"
S["b33ee472"] = "Mi pare di sentire le sue forze che arrivano! Guarda a ovest! Uccidile, così stanerai Krom'zar."
S["b3433c64"] = "Per il Re!"
S["b34f304c"] = "Guarda, proprio sul pelo dell'acqua!"
S["b354be49"] = "Sì, Torta. Tutto ciò che il tuo cuore desidera..."
S["b360d626"] = "I tuoi resti in putrefazione serviranno A ME come prova di ciò che succede a chi è tanto stolto da violare il mio dominio!"
S["b361dc96"] = "Mi hanno $Gvisto:vista;! Arriva $N! Aiuto!"
S["b3663daa"] = "Questioni così ufficiali si trattano solo a Darnassus: per avviare la procedura di creazione della tua gilda devi andare là."
S["b36c2a42"] = "Credimi quando te lo dico: rimpiangerai di essere $Gnato:nata;, femminuccia!"
S["b36fd94a"] = "Elder Starweave si trova ad Auberdine, il villaggio sulla costa della Darkshore."
S["b37cf5a4"] = "Da $Gsolo:sola; con questo non ce la faccio! Aiuto!"
S["b38048f4"] = "Morte a The Warden!"
S["b388c0d3"] = "Sei proprio $Gdiventato:diventata; più $Gastuto:astuta;, $N."
S["b38cab14"] = "Qualcuno ha visto la mia arma?"
S["b38fc71a"] = "Unità esperte scendono in campo!"
S["b391116c"] = "%s annusa l'esca."
S["b3917074"] = "Direi che non c'è altro da fare. Accidenti!"
S["b39596ef"] = "%s inizia a lanciare un potente incantesimo."
S["b39746ec"] = "Per vagare in queste Badlands devi essere $Gmesso:messa; male, $C. $GMesso:Messa; male come me.$B$BO forse sei qui perché sei $Gpazzo:pazza;. $GPazzo:Pazza;, come me."
S["b397b40e"] = "Così sei $Gvenuto:venuta; da Niby a imparare i segreti per evocare un infernal servant dal Nether.$B$BSilenzio! Niby sa tutto!$B$BUn sapere così Niby non lo cede tanto facilmente. Prima devi aiutare Niby in un compito molto importante."
S["b39c1363"] = "I Defilers!"
S["b39f4ae3"] = "Kaelsig Veldbarad, ras. Y wirsh odes barad me ko tiras ko lo ash se faergas Y gol majis nud me o mod engoth aelgestron."
S["b3a40214"] = "Non sarai $Gun paladino:una paladina;, ma se la cercherai potresti comunque trovare conforto nella luce."
S["b3afbe5e"] = "Anche i maghi? Dovreste stare più attenti quando giocate con la magia..."
S["b3b471e8"] = "Saluti, $N. Sei $Gpronto:pronta; per l'addestramento?"
S["b3be50f9"] = "Torniamo al boschetto, mortale."
S["b3d7d2c0"] = "La flotta è pronta, $N. Devi prendere questo segnalatore e piazzarlo nel cratere occidentale della zona di battaglia centrale. Difendi il segnalatore dagli attacchi finché la flotta non riuscirà ad agganciarne le coordinate!"
S["b3dcb983"] = "Rogues' Quarter è attaccato dallo Scourge! Aiuto!"
S["b3dea6f8"] = "Proprio non poteva farci niente..."
S["b3e57fb1"] = "Pelle, gloriosa pelle. È lei che ti tiene le interiora... dentro. La mia, l'avrai notato, non se la passa tanto bene. E pensare che un tempo mi preoccupavo dei pori. Adesso me n'è rimasta ben poca di cui preoccuparmi. In un certo senso è davvero liberatorio."
S["b3e742ed"] = "*GRRRR* *RUFF* *RUFF*"
S["b3edfa09"] = "Questi abomini non morti saranno annientati!"
S["b3ee618f"] = "Prima che ti insegni a cavalcare, $C, devi essere $Gosannato:osannata; presso i tauren di Thunder Bluff."
S["b3f4ec9e"] = "La terra è stata generosa con il nostro popolo, $C, e di questa buona sorte dobbiamo essere grati."
S["b3f5c4c8"] = "L'East Frostwolf Tower è stata presa dall'Orda!"
S["b3f8e71b"] = "Mi spiace, sorella, ma i miei raptors non li vendo a chi non ha dimostrato di essere osannato presso la tribù Darkspear. Quando ti farai valere e ci farai vedere che sei almeno $Gosannato:osannata; presso di noi, allora i miei raptors saranno a tua disposizione."
S["b4014041"] = "Ma cosa... nessuno purifica un Mezzorso nel MIO accampamento! Affronta l'ira di Xabraxxis!"
S["b4065a11"] = "Combattete!"
S["b4083f71"] = "Mmmm, era buono. Comunque, è ora di tornare al lavoro!"
S["b40bf2f9"] = "C'è tanto da fare, tanto da fare! L'Unione ci ha dato delle scadenze che non conviene mancare!"
S["b40d3be5"] = "La temperatura è di 122 gradi Kraklenheit."
S["b41fa4a4"] = "Innkeeper Pala ti aiuterà a far riposare corpo e spirito. La trovi nell'edificio subito a sud della banca, al livello più basso."
S["b41fc517"] = "Oh, basta con questi discorsi folli, nuotatori. Con le vostre storie di fantasmi ubriachi farete scappare quei pochi clienti che abbiamo!"
S["b423a9f9"] = "Mi sento benedetto: sono stati gli spiriti a portarti da me."
S["b42af751"] = "Ti consiglio proprio di andare a farti predire la sorte da Sayge. Lo so, lo so... è uno gnoll. Ma è uno gnoll molto speciale, che ha il potere di prevedere il tuo futuro!$B$BE alla fiera aggiungiamo di continuo nuove attrazioni di ogni sorta!"
S["b43b2dec"] = "Be', allora a quanto pare cerchiamo tutti e due Hogral Bakkan. È un nano, poco ma sicuro, quindi prima o poi passerà dalla Thunderbrew Distillery a farsi una birra — magari è già lì."
S["b4431e29"] = "Chi osa disturbare il nostro padrone?"
S["b4480a5b"] = "Onorare i tuoi anziani vuol dire onorare la tua cultura e il tuo popolo, $C. Ed è per questo che le Coins of Ancestry sono un riconoscimento tangibile per chi sceglie di percorrere il venerabile cammino del rispetto.$B$BIn questo Festival Lunare forse avrai l'occasione di onorare molti anziani, e così otterrai le Coins of Ancestry. Portami queste monete e ricompenserò il tuo impegno con una scelta di oggetti unici."
S["b45e9901"] = "Stolti."
S["b460a689"] = "Non combattete più per voi stessi, vermi! Adesso combattete per la Regina, quindi mostratemi qualcosa che sia degno di lei!"
S["b474453e"] = "Hai fatto un lavoro eccezionale, $Gsoldato:soldatessa;! La cavalleria è pronta a partire al tuo comando."
S["b4848d44"] = "Tu cerchi Josef Gregorian. Lui in Magic Quarter, su lato anello interno di canale verde."
S["b485e6b1"] = "Combattiamo così tanto che è ovvio che a Razor Hill ci sia un Istruttore di First Aid. Cerca Rawrk dentro la caserma, sul lato est della città."
S["b4884114"] = "Ce ne dev'essere uno qui da qualche parte..."
S["b48d554f"] = "Non male... per $Gun dilettante:una dilettante;! Comunque, ne sai su per giù quanto me. Per imparare di più devi andare a parlare con Josef Gregorian a Undercity."
S["b496f57f"] = "Perché facciamo sempre lo stesso tragitto?"
S["b4974deb"] = "Aku'mai esige altri sacrifici, e ora tocca a te morire!"
S["b4a32c9f"] = "$N arriva di corsa! Alle armi!"
S["b4a52918"] = "La mia vita per i miei padroni. Gioite!"
S["b4a84fe1"] = "$GBen trovato:Ben trovata;, $Gamico:amica;. Sono Officer Pureheart e vado fiera di far parte di un'organizzazione che opera in tutto il mondo, conosciuta come l'Argent Dawn. La nostra causa è semplice — colpire in fretta e senza pietà ogni forma di male che si mostri su Azeroth. Non siamo un organismo politico, e non vorremo mai esserlo. Per questo l'Alleanza e l'Orda sono per noi amiche — amiche nella lotta per schiacciare il male!$B$BPer la Dawn, $Gfratello mio:sorella mia;!"
S["b4a9e249"] = "Per un assalto diretto al santuario, i Peacekeepers non possono sperare di radunare abbastanza uomini. Se i Windshapers e l'High Order non vengono a rinforzare le nostre fila, non abbiamo alcuna possibilità. Entrambi ci hanno promesso il loro aiuto nel momento del bisogno. E quel momento è arrivato.$B$BPurtroppo, alcuni fatti recenti hanno fatto scorrere sangue vero fra le due fazioni, e la tensione è alta.$B$BChe ne dici di un po' di diplomazia?"
S["b4b782f4"] = "Dovrei tornare prima che Rema cominci a preoccuparsi..."
S["b4b7a623"] = "Ehi, Roccianodo!"
S["b4bbd9ba"] = "Proprio quello che mi serviva."
S["b4cd9f98"] = "Non arrendetevi! Combattete fino alla morte!"
S["b4dcedf0"] = "Ho appena finito un nuovo imploditore dimensionale che mi renderà più ricco dei miei sogni goblin più sfrenati! Mi manca solo un Goblin Engineer esperto che costruisca uno squarciatore dimensionale da collegarci e lo metta alla prova!"
S["b4e10b31"] = "Vengo a prenderti, misera Alleanza!"
S["b4e141e0"] = "Lee Brown se ne sta tutto il giorno a pescare vicino al Crystal Lake. Avrà qualche storia da raccontare e qualche trucco da insegnarti."
S["b4e21236"] = "Mentre esamini la gabbia e l'elfa della notte al suo interno, hai una strana sensazione di déjà vu. Per qualche motivo lei non ti guarda negli occhi: è quasi come se per lei tu non ci fossi."
S["b4e512d1"] = "Va' dal Maestro delle Wind Rider, in cima a The Sky Tower nella Valley of Strength. Ci penserà Doras a farti trovare la strada per la battaglia che cerchi."
S["b4ef99b3"] = "Salve, signorina. Sono Nyrill, apprendista del Maestro Xylem. Se c'è qualcosa che ti preoccupa, parlane pure con il maestro.$B$BQuando sarai $Gpronto:pronta; a ridiscendere ai piedi della montagna, sarò qui al tuo servizio."
S["b4efd0d2"] = "È ora che tu passi a un maestro più esperto: l'elfa della notte Kylanna Windwhisper, che vive nella Feathermoon Stronghold di Feralas. È una mente brillante, e di certo saprà portare avanti il tuo addestramento."
S["b4f83ad6"] = "Il generale Stormpike è caduto! La battaglia è vinta!$B$BOra ridete, mentre l'Alleanza si affanna a recuperare i possedimenti perduti."
S["b4fcd968"] = "Il potere della Tear of the Moons è mio! Mio, ho detto!"
S["b4fd3993"] = "Ora comincerò la veste..."
S["b4fda2c7"] = "Incredibile! Straordinario! Non so nemmeno cosa voglia dire!"
S["b4fde5c5"] = "Mmh, una mano lava l'altra. Fa' quello che ti chiedo, e fallo bene, e forse potremo parlare del tuo addestramento."
S["b4feefd2"] = "Ne sono state concesse tre all'arcimago Allistarj degli Shadowsworn, e altrettante a Lady Sevine, strega degli Shadowsworn. Le ultime tre sono andate a Grol the Destroyer, signore degli ogres Dreadmaul di queste terre devastate.$B$BVedi, $N, senza un'anima il corpo non può essere ucciso. Quel che resta dei miei uomini ora sono unità combattenti indistruttibili. Per fortuna le pietre del vincolo non li lasciano allontanare troppo."
S["b4ff2287"] = "Proprio così. Con illusioni e inganni, la madre della covata del Black Dragonflight si era travestita da membro della corte reale. E peggio ancora, aveva preso il controllo dell'attuale Gran Signore di Stormwind, Bolvar Fordragon.$B$BNon c'è da stupirsi se erano state prese decisioni militari tanto sciocche. Negli ultimi tempi i movimenti delle forze dell'Alleanza ci avevano lasciati perplessi. Ora capiamo che il Black Flight cercava di dividere l'impero — di distruggerlo dall'interno."
S["b50013d1"] = "Di recente abbiamo scoperto un modo per usare la nostra magia e incidere una sorta di \"buco della serratura\" attraverso cui scrutare i piani e apprendere molto di più su Azeroth."
S["b500439d"] = "Scorgi la sagoma indistinta di una figura umanoide dentro il baccello; ora sai che è proprio questo il luogo dove devi essere. Anche se pensi che prima o poi riuscirai ad aprirlo, il baccello resta ben chiuso anche ai tuoi tentativi più energici."
S["b50114be"] = "$GSignore, sissignore:Signora, sissignora;! Private Porter a rapporto, pronto ad aiutarti a raccogliere il medium leather. La Guerra di Ahn'Qiraj si avvicina e dobbiamo prepararci il più possibile.$B$BCome vedi, ecco i pezzi di medium leather raccolti finora, e a me hanno affidato il compito di arrivare al totale stabilito."
S["b50273a0"] = "Ottimo! Speravo in $Gun nuovo allievo:una nuova allieva;. Be', allora mettiamoci subito al lavoro!"
S["b514eaab"] = "Sei qui per prendere servizio, $C? Il materiale bellico, sia dell'Orda sia dell'Alleanza, è tutto completo, e proprio in questo momento lo stanno spedendo in Silithus. Dovrebbe arrivare tutto nel giro di pochi giorni. Spero che qualcuno abbia trovato i vari pezzi dello Scepter of the Shifting Sands e li abbia rimessi insieme."
S["b516c2ff"] = "Servo fino all'ultimo!"
S["b516ecb6"] = "Se abbiamo istruttori di Estrazione qui? Ma dove credi d'essere!?$B$BBe', uno dei migliori minatori di tutto Dun Morogh lo trovi alla Deepmountain Mining Guild, sul lato nord di The Great Forge. Lì Geofram Bouldertoe ti mostrerà la vera arte dell'estrazione."
S["b519d2f2"] = "Opus vuole un po' di Cuergo's Gold... col verme."
S["b51ea895"] = "Questa malattia mi annebbia la vista, ma so che devi essere un trogg. Muori, sporco invasore!"
S["b5245683"] = "Salve! Ho le pelli migliori che si trovino da qui a Stormwind. Ti interessano?"
S["b525e402"] = "Non importa. Sei $Gstato uno stolto:stata una stolta; ad aiutarmi, e ora pagherai!"
S["b533e3f6"] = "Mi arrivano di continuo rapporti sulle tue imprese contro l'Abyssal Council, $N. Stai facendo grandi cose là fuori!$B$BContinua così, e faremo in modo che ne valga la pena!"
S["b537f7d3"] = "%s irrompe dal terreno!"
S["b53d8a50"] = "Addio, e che Elune sia sempre con te."
S["b541165a"] = "$N? Dove sei, $N? Oh no! Dove sei $Gfinito:finita; stavolta!"
S["b557cda8"] = "Siamo quasi in salvo. Da qui si corre. Cerca di non restare troppo indietro! VIA!"
S["b55b24b4"] = "Infedeli! Devono essere purificati!"
S["b55bbba8"] = "%s fa scendere a forza il liquido nella gola dell'uomo sfinito."
S["b560b2ae"] = "Non valevi l'energia spesa. <Nathanos sputa.>"
S["b56873ec"] = "Una volta ho sentito parlare di un altro come te... Il suo nome era Vol'jin. Sei un esemplare raro, $Gamico mio:amica mia;."
S["b576c419"] = "Ah, che bello non essere più legato! Hai già liberato Tog'thar? Gli umani ci hanno separati dopo averci catturati."
S["b57a2973"] = "Corrono tempi pericolosi, $Gavventuriero:avventuriera;. Muoviti con cautela."
S["b585ae0a"] = "Ho sentito parlare di voi. Windshapers. Figli ribelli dell'antica Eldre'Thalas.$B$BUn tempo vi avrei chiamati parenti — anche se parenti lontani. Ora non ho con la stirpe degli elfi più cose in comune di quante ne abbia con qualsiasi altra razza vivente. Di ogni creatura che respira, mi importa soltanto quanto possa servire gli scopi dei Forsaken. Renditi utile al mio popolo e sarai $Gbenvenuto:benvenuta; nelle nostre terre.$B$BVa'. Esplora l'Undercity come preferisci e goditi le sue comodità, per quel che valgono. Ricorda soltanto che nulla sfugge alla mia attenzione nel mio dominio."
S["b58a967e"] = "Maestro, lui continua a punzecchiarmi!"
S["b593e464"] = "** PIAZZATO. CONFERMA AGGANCIO Su WAR RIDER. RESTARE IN ATTESA. T-MENO 60 SECONDI. **"
S["b594b208"] = "Ashjrakamas... Maz veni ul maez orah A azgalada. Zilthuras..."
S["b598f1a3"] = "Molto bene. Guerrieri delle distese gelate, alzatevi! Vi ordino di combattere, uccidere e morire per il vostro padrone! Che nessuno sopravviva!"
S["b59ca8f6"] = "Mai visto nessuno muoversi così in fretta in tutta la mia vita."
S["b5a4bb82"] = "Ho la tua bambolina! Gne gne!"
S["b5a64677"] = "Oooh, questo sembra promettente..."
S["b5ad92e9"] = "I guaiolanti tendono ad accumulare oggetti lucenti nelle loro tane, quindi è possibile che alcune parti del costrutto siano finite nella caverna dei guaiolanti appena a ovest di Valanaar."
S["b5adcd5a"] = "Attenzione, arrivano!"
S["b5bae964"] = "Vuoi volare a Thunder Bluff? Il volo lo offre il Cenarion Circle."
S["b5be3452"] = "Un intero ordine di visionari proprio come i Windshapers, chiamato The Earthen Ring. Uno dei loro capi, uno sciamano di nome Muln Earthfury, mi ha mostrato molto."
S["b5cad2ae"] = "Da una collina vicino al centro, Elder Highpeak veglia sulle Hinterlands."
S["b5cf9398"] = "Forza, branco di fannulloni, è ora di alzarsi e mettersi al lavoro. Quel ponte non si costruisce da solo."
S["b5de0c5c"] = "Siete arrivati troppo tardi!! Io... devo... obbedire!!"
S["b5e13889"] = "Ma la vostra vera punizione deve ancora arrivare."
S["b5e202af"] = "Già, è morto stecchito. Quindi il nuovo re sei tu... anzi, tutti voi! Ora Gordok è vostro, capo! Devi parlare con me per imparare tutto quello che c'è da sapere sull'essere re! Io ero... sono il suo assistente! Sì, è per questo che mi chiamano l'Astuto!"
S["b5f295ec"] = "$N, $Gcittadino:cittadina;. Sembri $Gun uomo:una donna; con uno scopo — hai affari con la Stormwind Army?"
S["b5f800f6"] = "Miei signori! Vengo da voi!"
S["b5f900e5"] = "Se un fulmine cade nell'oceano, perché i pesci non muoiono tutti?"
S["b5fbe66a"] = "Chi osa provocare il messaggero di Edwin Van Cleef? Muori, Nano!"
S["b5fddb6f"] = "Ma pensi mai a qualcosa che non sia combattere? Sul circuito potrei doppiarti!"
S["b5fe0e16"] = "Ciò che ti offro ora è una di queste lame: mai passata nel fuoco, mai scaldata, mai trattata — nella sua forma più grezza ed essenziale.$B$BOra devi solo trovare un drago disposto a incantare la lama.$B$BSe avessi l'eternità davanti a te, potrebbe essere una possibilità; ma dato che sei mortale e potresti benissimo cessare di esistere da un momento all'altro, posso consigliarti di provare a convincere uno dei draghi minori a eseguire i tuoi ordini."
S["b6054bd3"] = "Tesoran! Mi serve qualcuno, meglio se Falgran Hastil, che segua la pista di $N sulle impronte vicino alla Shady Rest Inn."
S["b607a2fb"] = "Grazie. Torno a Deathknell."
S["b6093f3f"] = "È la forza del cuore che ti dà la determinazione per agire... e per un agire che affonda le radici in intenti puri e sinceri. Mantenere l'equilibrio non significa adagiarsi, né essere banali.$B$BPer ciò in cui credi devi mostrare determinazione, ed essere $Gdisposto:disposta; a combattere. L'orsa madre difende i suoi piccoli con una convinzione infinita, così come il vecchio orso protegge la tana. Se vuoi padroneggiare la via dell'Artiglio, devi imparare a conoscere questa determinazione, questa forza del cuore."
S["b60bb549"] = "Saluti, $C, sono $Gl'istruttore:l'istruttrice; di conciatura di Thunder Bluff. In cosa posso aiutarti?"
S["b60e250d"] = "Sei stato via troppo a lungo, Malfurion. La pace tra i figli di Azeroth è fragile, nel migliore dei casi. E mio padre? E tuo fratello? Hai notizie?"
S["b60f4900"] = "Mi avevano detto che eri $Gmorto:morta;... be', dopo questo non sarà facile farti $Gmorto:morta;!"
S["b6184163"] = "Vira Younghoof esercita il suo mestiere nella casa lunga, sul lato ovest del villaggio."
S["b61eecc8"] = "Poi ti basta sederti vicino al fuoco e goderti il momento: dopo qualche minuto di riposo avrai vari vantaggi che ti torneranno utili in viaggio."
S["b6208ca5"] = "La bimba vuole la sua bambolina!"
S["b62a71c3"] = "Myolor, un tempo ero $Gun forgiatore:una forgiatrice; d'armi e vorrei invece imparare la via del forgiatore d'armature. Mi insegnerai?"
S["b6374bb9"] = "L'Irondeep Mine è in mano all'Orda."
S["b63778ec"] = "Congratulazioni!"
S["b63af21b"] = "Era ora che qualcuno ammazzasse quel miserabile."
S["b63cda13"] = "Venite, venite tutti! Benvenuti alla Darkmoon Faire! Bramate l'avventura? Cercate tesori esotici e misteriosi? Allora non cercate oltre! Tu, $Gamico mio:amica mia;, sei $Gvenuto:venuta; nel posto giusto! Buttatevi e partecipate a tutto ciò che la Fiera ha da offrire! Resteremo qui tutta la settimana, quindi non dimenticate di dirlo ai vostri amici e ai vostri cari!"
S["b647fb9b"] = "Questi marinai d'acqua dolce sono qui per le renne! Fategli assaggiare il coltello!"
S["b6506027"] = "Salute, $N. Vedo che sei $Gvenuto:venuta; da Orgrimmar per aiutarci. Ne sono felice. Voglio andarmene da questa forsaken foresta il prima possibile. Preferirei di gran lunga passare il mio tempo a Orgrimmar con una buona birra.$B$BAnche se non vedo l'ora di sapere come ha fatto Belgrom a convincerti a venire fin qui."
S["b653482e"] = "Proprio così, $Gamico:amica;! La Darkmoon Faire si terrà qui, appena avrò scaricato quei carri enormi, montato tutte le tende, allestito lo zoo e versato da bere. Torna, mi raccomando!"
S["b655561f"] = "Guidi gli spiriti nell'acciaio a proteggere e difendere con molta più abilità di quanto potrei mai fare io. L'allievo ha superato il maestro, e ora devo mandarti dove la tua istruzione possa continuare. $N, devi cercare Shayis Steelfury a Orgrimmar. È la migliore forgiatrice di armature che abbia mai conosciuto, e può insegnarti molto."
S["b65982c0"] = "%s tira fuori un telecomando e getta a terra un modellino di siege engine!"
S["b65f1b4b"] = "Se riesci a completare un mazzo di carte degli elementali, avrai in premio una carta darkmoon superiore del maelstrom. Di tanto in tanto, questa carta colpirà il nemico che stai combattendo e gli infliggerà ingenti danni."
S["b66235d7"] = "Il rogo dell'Uomo di Vimini comincerà tra cinque minuti! Venite alla festa, appena a ovest di Undercity, e celebrate Hallow's End e la nostra liberazione dallo Scourge!"
S["b66cb746"] = "Non temere. La Night Watch libererà ben presto la terra da questa immonda corruzione."
S["b66e841f"] = "Informazioni sul Blood of Heroes."
S["b66f1884"] = "Bisogna fare attenzione a non danneggiare l'esemplare..."
S["b66f850d"] = "$N ha difeso la fattoria!"
S["b6769d7a"] = "Quanti dei nostri Luogotenenti sono vivi, Vanndar?"
S["b68389c4"] = "Fantastico allora! Ripariamo questa cosa per te."
S["b6868061"] = "MORITE, CANI DEMONIACI!"
S["b6895816"] = "Direi di no, non ho nessuna voglia di saltare in aria un'altra volta."
S["b68b2102"] = "Io sono $Gsolo:sola;.....questo compito....il Signore del Vento.......le nostre voci.....verrà.....non dobbiamo fallire!"
S["b694a2ec"] = "Ecco la Cathedral of Light, il centro dell'illuminazione spirituale qui a Stormwind."
S["b6980c08"] = "Ah, lo sento — la vittoria è tua! Credo di poterti trasportare a Stratholme senza pericolo, ora, purché tu abbia prima fatto visita al mio collega laggiù. Entra nel cerchio e sii paziente..."
S["b69f8db5"] = "La purezza la troviamo solo nella Natura."
S["b6b8ca98"] = "Argh! Sei un caso perso!"
S["b6bfb707"] = "Oh, è terribile, terribile, orribile! Morirai quando la vedrai, Vivian."
S["b6c83a53"] = "Bisogna scoprire cosa danno da mangiare i Qiraji a quei mostri! Guarda come sono grossi!"
S["b6ce9b95"] = "Salute, $C. Sono Tyrande Whisperwind, Somma Priestess of Elune."
S["b6d22764"] = "La tribù Blackwood sta sconvolgendo le nostre terre sacre."
S["b6d2ae61"] = "e Ossa."
S["b6d5bc90"] = "$N ha difeso la miniera!"
S["b6d67525"] = "Elder Starsong, che io sappia, era nel Sunken Temple of the Swamp of Sorrows."
S["b6da4103"] = "Alla salute! Non troverete birra migliore da nessuna parte!"
S["b6e10b4a"] = "Spero che tu stia bene, tutto considerato.$B$BSiediti un momento e ascolta la mia storia. È una tragedia, naturalmente, ma spero che finisca con una vendetta!"
S["b6e8175a"] = "Cos'è stato? Hai sentito qualcosa?"
S["b6ea3511"] = "Se pescassi come parli, nell'oceano non resterebbe più un pesce."
S["b6eb058a"] = "Con piacere... fammi assaporare questo momento ancora per un minuto."
S["b6f7a932"] = "Андрюха, il tuo invisibility liquor è pronto."
S["b6fe3762"] = "Lithtos Re! oDes ti Mod mandos me barad! Thor!"
S["b6ff7480"] = "Siamo solo polvere sotto i vostri piedi, signore."
S["b6ffa7eb"] = "Ahah!"
S["b70002cf"] = "%s prende la mira..."
S["b71402ec"] = "Morire oggi, su questo campo di battaglia, è morire da orco. Morire oggi è morire per i nostri piccoli. I nostri anziani. I nostri... cari."
S["b71436c4"] = "Per l'Alleanza!"
S["b72262cf"] = "Lasciami. Ho ferite gravi, e temo che avranno la meglio su di me. Grazie, $N. Morirò qui, ma grazie a te... morirò in pace."
S["b724156a"] = "Raaaaaaaaaaaaaaaaaaaaaaaaaaaaaar!!! Io spaccare $N!"
S["b72415e6"] = "Raaaaaaaaaaaaaaaaaaaaaaaaaaaaaar!!! Io spacca $R!"
S["b72e12f3"] = "Chi osa chiamare il Signore del Vento dell'Est?"
S["b73a01ad"] = "C'è qualcuno?"
S["b73b6dd0"] = "Aspetta! Ma cosa mi salta in mente! Con questa roba abbiamo un lavoro da fare."
S["b7400c7c"] = "Come desideri, $Gsignore:signora;."
S["b740574f"] = "Niby, sei un idiota."
S["b7451ef8"] = "Mostrate ai nostri nemici la vostra determinazione, soldati! Schiacciateli sotto i piedi! Sotto l'acciaio!"
S["b74d213e"] = "Al livello inferiore di Thunder Bluff c'è Ansekhwa, il maestro d'armi tauren. Ti può insegnare a usare mazze a una e a due mani, bastoni e fucili.$B$BQui accanto a me c'è Hanashi, che può istruirti nell'uso di archi, asce a una e a due mani, bastoni e ogni tipo di armi da lancio.$B$BNel War Quarter of the Undercity troverai Archibald, il maestro d'armi non morto. Da lui puoi imparare a usare balestre, pugnali, spade a una e a due mani e armi ad asta."
S["b76633bd"] = "Pare che restano solo pochi giorni pe' pescare prima che tutto 'sto materiale da guerra viene spedito laggiù nel deserto di Silithus, amico. Poi lo prepareranno tutto quanto, e qualcuno dovrà suonare quel gong giù a sud di Cenarion Hold pe' aprire i cancelli e cominciare la guerra."
S["b7753890"] = "Guardati intorno, $C. Sei in rara compagnia, questo è certo, eppure credo che tu debba ancora dimostrare quanto vali. Mmm, forse ti lascerò aiutare la nostra causa ad Arathi Basin. Ti piacerebbe?"
S["b77f7722"] = "Grom zugas maza kazum kazum ka dogg, $N!"
S["b784f38e"] = "%s posa la pergamena sul tavolo e legge..."
S["b7863128"] = "È un'abilità che richiede tempo, ma dà soddisfazione. Parla con Astaia nella Tradesman's Terrace e forse imparerai qualcosa di utile."
S["b786e1f2"] = "Fermi! Infedeli!"
S["b7880841"] = "Alassin accudisce da molte centinaia di anni gli animali che i nostri cacciatori si fanno amici, e le sue cure sono molto richieste da chi va a caccia da queste parti. Se lo cerchi anche tu, è nella Cenarion Enclave."
S["b78ed8ec"] = "No, mi sa che mi pianto qui e mi faccio un giardino...$B$B<Alza la voce.>$B$BTu cosa pensavi che facessi? Certo che da qui in poi andrò sul sicuro!"
S["b79b7120"] = "Mi fai perdere tempo, vai a parlare con il mio allievo Basil."
S["b7a80372"] = "Dimostri una saggezza superiore alla tua età, $C. Grazie. Troverai la nostra maestra di battaglia, Lylandris, al tavolo di guerra nell'Hall of Arms. Può aiutarti a raggiungere Warsong Gulch."
S["b7aa4166"] = "Mmm..."
S["b7afbbd0"] = "Vuoi fare l'ingegnere, eh? Be', per Muradin, sei $Gcapitato:capitata; nel posto giusto!"
S["b7b639d0"] = "Quella notte mi sono rotto tutte e due le gambe. Come potrei dimenticarlo?"
S["b7b783e5"] = "Myolor, un tempo ero $Gun:una; fabbro d'armi e voglio riprendere in mano il martello ancora una volta! Insegnami la via del fabbro d'armi!"
S["b7b87353"] = "Parlami di Captain Galvangar."
S["b7bb9184"] = "Credo sia ora di lasciare questo luogo. Aprirò un portale per Valanaar."
S["b7bd97b3"] = "Come vanno i tuoi viaggi, $N? YOUR_GENDER(Sumi e Tumi hanno sentito la tua mancanza, dovresti salutarle dopo la lezione;Ho sentito i racconti delle tue avventure, a quanto pare sei stata molto impegnata). Ora vediamo cosa hai imparato mentre eri via."
S["b7bfe175"] = "La mia vita non significa nulla! Il nostro sacro compito è tutto!"
S["b7c266e5"] = "Come desideri, $C."
S["b7d3eb70"] = "E towa zhi towa ba lakota'mani uku ishamuhale E shne washte zhi rah uku pikialo ki uku kichalo towateke awak. Tanka... kashu!"
S["b7e7c65e"] = "La chiamiamo Barrens, eppure, per chi sa dove guardare, questa terra brulica di vita."
S["b7e83282"] = "Con un po' d'acqua di colonia o di profumo addosso vedrai chi è in vena d'amore: sono quelli che accettano i love tokens... e in cambio ti offrono un dono.$B$BMa ricorda: per dare un love token a qualcuno devi avere l'odore giusto! Agli uomini piace il profumo, le donne invece preferiscono l'acqua di colonia."
S["b7e93bb1"] = "Sono contento che qui intorno il trambusto si sia un po' calmato. Ci mancherebbe solo un'altra rissa."
S["b7ea6024"] = "Proteggete Foreman Bonds a ogni costo!"
S["b7ea6747"] = "Che la morte mi prenda! Non posso andare avanti! Non mi resta niente..."
S["b7ee82d8"] = "Le nostre unità sono passate al grado Esperto, ma non ho abbastanza rifornimenti per portarle a Veterano."
S["b7f08f43"] = "Io... Beh, forse ho preso una cosetta o due dalla locanda... ma cosa importa a un ogre?"
S["b7f4dd1d"] = "Il mio papà pesca più pesci del tuo papà!"
S["b80cc010"] = "Ah, sentite la magia che penetra nella grotta, miei piccoli elfi... muhahaha."
S["b810a9a0"] = "Tu controlla davanti!"
S["b810dffb"] = "Salve, $C. Spero che tu sia $Gvenuto:venuta; a rinforzare le nostre file: bestie e ladri si riversano nella nostra amata Elwynn, e abbiamo a malapena gli uomini per tenere sicure le strade!$B$BSe non l'hai ancora fatto, leggi quell'avviso su Hogger. È una bestia dei boschi laggiù, e bisogna occuparsene."
S["b8110cd9"] = "Forse posso aggiustarlo io, pa'. Fammi dare un'occhiata."
S["b812a5fc"] = "%s si spalanca di colpo!"
S["b8280af1"] = "La Cache of Mau'ari nasconde grandi segreti... I frammenti usati pe' farla riflettono, e con la sua superficie lucida puoi assorbire potere da altre robe e poi rifletterlo su di te.$B$BSe tieni il talismano nell'inventario, raccogli l'e'ko, il potere spirituale delle bestie che combatti. E quando l'e'ko lo trovi, lo porti a Mau'ari."
S["b843df27"] = "La mascherata è finita, il Lady Prestor. O dovrei chiamarti col tuo vero nome... Onyxia..."
S["b84e4bf4"] = "Vi ordino di far piovere fuoco su questi invasori!"
S["b8543ca5"] = "Eccone uno dello Scourge, proprio laggiù!"
S["b857cced"] = "Sta' all'erta! I furbolgs Blackwood sono numerosi in questa zona..."
S["b858ee07"] = "Hai dedicato il tuo tempo a studiare le basi. Ora è il momento di alzare la posta."
S["b85b9c05"] = "Salve, $N. Se dovessi aver bisogno di aiuto per portare a termine la tua missione, non devi far altro che chiedere. Il mio guardiano, Raze, può aiutarti a sconfiggere gli shadowsilk poachers. Usa questo Staff of Command per comandare Raze in battaglia. È addestrato ad attaccare SOLO gli shadowsilk poachers."
S["b85d117c"] = "Stolti! Queste uova sono più preziose di quanto immaginiate!"
S["b861ef85"] = "Confessa e ti lasceremo andare."
S["b8660dd4"] = "$GAvventuriero:Avventuriera;! Il ponte di vento verso l'altra guglia è instabile. Forse dovrai aspettare qui con me che torni."
S["b8679480"] = "Mi dispiace se ti hanno malmenato, Vrang. Se avessi saputo che ti avevano preso, sarei corso da te."
S["b86d15e3"] = "È giunto il momento, Guse. Volerai di nuovo!"
S["b86f92fd"] = "Ma tu guarda! È $Gun nuovo studente:una nuova studentessa;! Ti insegnerò volentieri tutto quello che so, appena avrai un po' più di abilità. Perché non vai a parlare con Gretta Finespindle, laggiù? Ti metterà al passo in un attimo."
S["b8761561"] = "Solo se non seguissimo le procedure di avvio corrette."
S["b8779057"] = "Se il tempo mi ha insegnato qualcosa, è che non esistono incarichi noiosi. Fare la guardia al Thandol Span doveva essere un lavoro facile. Ma con il grosso dell'esercito a combattere al fianco dell'alleanza, qui ci hanno sopraffatti, e Dun Modr è caduta."
S["b87c5b92"] = "Mmh... gli occhi non mi pesano più così tanto, papà. Possiamo uscire a giocare?"
S["b87d66a8"] = "Sia lodata la Luce, finalmente qualcuno ha risposto alla chiamata."
S["b88163e4"] = "Per l'erboristeria ci vuole un tocco delicato, che sanno insegnare in pochi, come Malorne. Cercalo a est della Locanda di Dolanaar."
S["b886c008"] = "I maghi si riuniscono nel Wizard's Sanctum, in Mage Quarter, dove hanno proprio una bella torre. Al confronto, le nostre caserme sembrano tuguri da contadini."
S["b88c2c86"] = "Vivere qui nel deserto è dura! A stare fuori con questo caldo mi viene una sete tremenda."
S["b899d028"] = "Ti istruirò al momento giusto... e quel momento non è adesso. Prima devi imparare ancora molto!"
S["b8a469ad"] = "<Emberstrife prende atto della tua presenza.>"
S["b8a59f11"] = "Ah, aspetta! Dovrei cercare quel fossile misterioso!"
S["b8ab65ad"] = "<PH> Maghi in Arrivo <PH>"
S["b8b243b1"] = "Per favore, continua."
S["b8bb0199"] = "Non ne sono degno, $Gsignore:signora;."
S["b8c5302f"] = "Non mettiamoci nemmeno a confrontare le cicatrici di battaglia, $Gamico mio:amica mia;."
S["b8c74adf"] = "Che cosa ti porta davanti al Court of Lakeshire e a Honorable Magistrate Solomon?"
S["b8cc16f5"] = "Altre ossa da rosicchiare..."
S["b8d4b072"] = "Attenzione! $Gil:la; $R $N ci attacca al Winterax Hold!"
S["b8e89831"] = "Quindi... è così che finisce, amore mio..."
S["b8f34d8b"] = "Salve, $N. Sono Johnny McWeaksauce. Gli sviluppatori mi usano come strumento per svolgere funzioni specifiche a scopo di test, e per questa fase sono impostato per fare due cose precise:$B$B(1) Segnare che hai completato la quest di accesso a Naxxramas, così potrai accettare da Commander Eligor Dawnbringer la quest successiva, \"Echi di Guerra\". Devi completare quella prima di poter accedere alle quest del set di armatura di Tier 3.$B$B(2) Teletrasportarti a Naxxramas.$B$BCosa ti serve?"
S["b8f3a1d4"] = "Sono spacciato! Evocate Verog!"
S["b8fb242d"] = "Fai sparire quel broncio e sorridi!"
S["b8fbb970"] = "Ci hanno attirati qui ragioni diverse, $C.$B$B<Rayne sorride.>$B$BIo sono venuta a incontrare Rimblat of the Earthen Ring, che ha delle teorie interessanti su come purificare queste terre."
S["b902be5f"] = "Va', presto... <coff coff> Trova... <coff> Ryedol..."
S["b903b37d"] = "Se ti ha mandato Therzok, digli di no, non tornerò a lavorare per lui, per quante volte me lo chieda."
S["b9057762"] = "Fra la nostra gente, forse sono l'unica shen'dorei ancora in vita ad aver scambiato con lui più di qualche parola.$B$BPer quasi nove secoli l'ho servito come capitano delle sue Empyrean Blades, finché... non ci ha lasciati.$B$BEppure non posso dire di averlo davvero \"conosciuto\". Fu sempre un uomo riservato e solitario. Passava gran parte del tempo da solo, o in comunione con gli spiriti, nelle alte guglie sopra lo Shrine of the Four Winds... il luogo che ora il culto chiama 'Santuario di Akir'."
S["b906b56e"] = "I vostri sforzi si riveleranno inutili. Nessuno si metterà sulla nostra strada!"
S["b9090b95"] = "È... è finita, Sire lo Staghelm. Abbiamo vinto. Anche se il prezzo di questa vittoria è stato alto."
S["b90ff4b8"] = "Ti spedisco nell'aldilà, debole $C!"
S["b91457ca"] = "Nostyec vil endirvis vrum O far kaelsig gol."
S["b91987cc"] = "Non ci sarà scampo!"
S["b919a4f7"] = "Che io sappia, qui fuori a Dun Morogh incantatori non ce ne sono. Se vuoi imparare quella professione, dovrai andare a Ironforge."
S["b91bd8e0"] = "<High Inquisitor Fairbanks scuote la testa.>$B$BNo... Se n'è stato in disparte a guardare la legione di non morti che si riversava su di noi. Poco dopo i miei poteri si sono esauriti e sono stato il primo a cadere... Mentre giacevo lì privo di sensi mi avrebbero fatto a pezzi di sicuro, e invece mi hanno ignorato del tutto, per badare soltanto all'Alto Signore."
S["b91d2d76"] = "Brzzzzt!$B$B$GBenvenuto:Benvenuta; nel Matrix Punchograph 3005 barra A, terminale di livello di sicurezza alfa.$B$BWhite punch card rilevata. Accesso Consentito.$B$B01010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 01110100 01101111 00100000 01110000 01101100 01100001 01111001 00100000 01010111 01101111 01010111"
S["b92462e7"] = "Trema! La fine è giunta per te."
S["b92b1ea7"] = "<Kharan si schiarisce la voce.>$B$BPassato il tunnel della Searing Gorge, siamo entrati nella landa devastata che forma la gola. A ripensarci, c'era una calma inquietante. Gli unici pericoli che abbiamo incontrato sono stati gli animali selvatici della regione: creature che i miei uomini hanno fatto fuori senza fatica.$B$BAbbiamo raggiunto Blackrock Mountain con relativa facilità e attraversato la costruzione di pietra senza il minimo intoppo."
S["b92e52c0"] = "Sì, $C? Vieni a fare rapporto?"
S["b9367648"] = "Sento puzza di intrusi..."
S["b94257a8"] = "Ora lasciami in pace. Devo riposare."
S["b942e50b"] = "Ha! Io preferirei il suono di un Cannone Cratere XT che spara un proiettile, altro che quello!"
S["b94768f1"] = "Lucius è un vecchio e fidato amico del Ravenholdt Manor — io e lui abbiamo molto di cui discutere. Cercami ai moli di Lakeshire se dovessi avere bisogno del mio aiuto o dei miei consigli."
S["b9494f39"] = "Cerchi qualcuno che si occupi degli animali? Allora va' da Seriadne, fuori dalla Locanda di Dolanaar: è lei che cerchi."
S["b94bf4fb"] = "Bwahah! Dovevi vedere che facce quando il cannone del vecchio Trollplow si è girato verso di loro! Con quelle seghe non sono riusciti nemmeno a sfiorarmi!"
S["b94ca226"] = "I Cristalli Ash'ari sono stati distrutti! Il Mattatoio è vulnerabile!"
S["b94f2b00"] = "L'ultima volta che hanno attaccato, c'è stato un solo attacco. Non mi sorprenderei se stavolta ce ne fossero di più."
S["b9588af7"] = "Per i Dragonmaw!"
S["b95a0bbc"] = "Malygos, eh?"
S["b964ef8d"] = "Algos novas engoth! Thor!"
S["b9666a27"] = "Saluti, $C. $GBenvenuto:Benvenuta; a Cenarion Hold. Da qui colpiremo i silithid là dove sono più forti. Spero che tu sia $Gvenuto:venuta; a darci una mano."
S["b96bf64d"] = "Questa pietra, scolpita in un materiale sconosciuto con mezzi misteriosi, porta ben in vista il simbolo dell'elemento acqua."
S["b9780426"] = "Oooh... Questa pietra è bella e colorata. Vediamo se ne trovo altre così..."
S["b9796a41"] = "Sarà meglio che ne valga la pena...."
S["b97c4560"] = "%s è $Gvuoto:vuota;, a parte qualche briciola e una gigantesca piuma verde."
S["b9873bd2"] = "Da qui posso farcela da solo, $N. GRAZIE!"
S["b9875501"] = "Istruttori di guerrieri, loro combattono bene. Tu trovi loro in War Quarter, su anello esterno di Undercity."
S["b98a8d85"] = "Miei servitori..."
S["b98b7737"] = "Sì sì sì! Sei proprio $Gil:la; $R che cercavo!$B$BSiediti! Abbiamo tanto di cui parlare!!"
S["b98c2505"] = "Era ora che mi mostrassi dei risultati! Adesso i risultati te li mostro io!"
S["b98f9e1e"] = "Se dimostro il mio valore a Saru, dovrà per forza lasciarmi combattere per una delle sue figlie. Allora vedremo chi sogghigna."
S["b98fe74e"] = "Oh sì, giusto.$B$BDunque, ci stavamo spingendo in fondo alle parti più alte di Blackrock Spire, contro il loro signore e capo; parlo di prima di Drakkisath. Non molto furbo, se vuoi sapere come la penso, ma il nostro capo, Anthion Harmon, che hai conosciuto, era uno che le sfide le aveva sempre amate.$B$BA sorpresa, è andato tutto secondo i piani, finché non abbiamo cominciato a strappare il libro degli incantesimi di Valthalak dalle sue dita rigide. Lì le cose si sono messe male.$B$BVado avanti? Mi sembri un po' assente."
S["b9906c24"] = "Non abbiamo nulla contro di te, Signore del Vento dell'Est. Lasciaci in pace."
S["b9955f62"] = "Allora, $Gragazzo:ragazza;, credi di avere quello che serve per difendere l'Alleanza contro l'Orda nell'Alterac Valley? Bene, allora devi parlare con il nostro Glordrum Steelbeard, qui a Ironforge. Lo trovi nell'Hall of Arms, che studia strategie al tavolo della guerra."
S["b99bd7e0"] = "Sì, mi è bastato guardarti per capirlo, $N. Mi ricordi tanto me stesso quando ero un giovane guerriero dell'Orda.$B$BAndrai lontano nella vita, non c'è dubbio, e ancora più lontano nella morte.$B$B<Goretooth fa il saluto.>"
S["b99e1a5b"] = "Riempi il boccale e prenditi una sedia. Abbiamo storie da raccontare e barili da svuotare."
S["b99e8482"] = "Aggeggi... fatto. Coseggiatori... fatto. Frullini... fatto."
S["b9a82194"] = "E vorrei poter venire con te, $N. Va' a Stormwind Keep: nella sala delle udienze del Re troverai Thelman Slatefist, che ti aiuterà a raggiungere l'Alterac Valley."
S["b9af2c39"] = "Fra Bixi e Buliwyf, di armi con cui non hanno avuto il piacere di affettare o spiaccicare un orco non ce ne sono mica tante. Se ti serve un po' di addestramento, li trovi che bazzicano il negozio Timberline Arms."
S["b9b4e46d"] = "Grazie per avermi trovato la collana, signore! Sei il migliore!"
S["b9ba454c"] = "%s viene $Grisucchiato:risucchiata; nel forziere!"
S["b9be1b22"] = "Allora... non è che per caso hai un forziere da queste parti che contiene, diciamo, un guanto d'arme che gli ogres Gordok considerano un manufatto inestimabile?"
S["b9c8a4ae"] = "%s corre in aiuto di Feugen!"
S["b9ce11c0"] = "Combattete per le vostre famiglie! Non arrendetevi!"
S["b9d48437"] = "Sissì, posso insegnarti a pescare."
S["b9d5931c"] = "Muori, $N! $GL'unico:L'unica; $Gbuon:buona; $C è $Gun:una; $C $Gmorto:morta;."
S["b9da728a"] = "Aziris! Aziris!"
S["b9e2f2eb"] = "Non mi sembri $Guno studente:una studentessa;..."
S["b9e89a33"] = "%s salta dalla prima catapulta alla seconda!"
S["b9e8c96f"] = "Chi ha la macchina più veloce? Chi lo sa?!?"
S["b9f02a2b"] = "Ricordate: se molestate l'operatore o intasate il canale, il vostro account potrebbe essere espulso, bannato o peggio."
S["b9f0cc98"] = "Abbiamo a malapena qualche rifornimento per costruire la Frostwolf Keep. Ce ne serviranno molti, molti di più prima di poter riparare la nostra base e tornare in battaglia."
S["b9f9a44e"] = "I tuoi dischi ti saranno restituiti quando userai il piedistallo."
S["ba02b4cf"] = "Ho sentito qualcosa, laggiù."
S["ba031679"] = "Eccoti. Che notizie da Westfall?"
S["ba03c2ff"] = "Qui sono sparsi un mucchio di fogli e di schemi."
S["ba09e763"] = "Preparati al glorioso impatto, Impsy!"
S["ba0b5178"] = "starnutisce violentemente!"
S["ba0babcb"] = "QUESTO EVENTO FUNZIONA."
S["ba0ca2bb"] = "<Il Brazier of Eternal Flame aspetta la tua offerta.>"
S["ba0da355"] = "Da queste parti non riceviamo molte visite. Posso proporti qualcosa?"
S["ba155793"] = "Mai troverai le lame gemelle di Sul."
S["ba1aa3a7"] = "Maledetto $N! Un giorno avrò la mia vendetta!"
S["ba2688e0"] = "Nessuno della vostra specie dovrebbe essere qui! Avete condannato solo voi stessi!"
S["ba2989c7"] = "Negli ultimi mesi abbiamo ampliato rapidamente la nostra attività, ma stiamo ancora sviluppando i mezzi per garantire comunicazioni rapide fra i clienti in ogni angolo del mondo. Per questo dobbiamo tenere gli occhi aperti per trovare occasioni che tengano occupate le mani dei nostri artigiani. Contiamo su corrieri o altre anime coraggiose per farci arrivare direttamente le commissioni di lavoro.$B$BPuoi immaginare che questo modello di affari porti con sé delle difficoltà. Nel frattempo, incoraggiamo vivamente i nostri artigiani a soddisfare queste commissioni e a consegnare la merce di persona direttamente ai clienti, ovunque si trovino in quel momento. Non preoccuparti, $Gamico:amica;, sarai $Gricompensato:ricompensata; equamente per il disturbo e ti guadagnerai il nostro rispetto!"
S["ba32f221"] = "Prova 1"
S["ba32f222"] = "Prova 2"
S["ba32f223"] = "Prova 3"
S["ba37c773"] = "Spero che la Luce ti accompagni, $N. Posso esserti utile oggi?"
S["ba38d5c0"] = "Mostrami solo la via, Franclorn."
S["ba437c65"] = "Io e mia moglie gestiamo il frutteto di mele tempestose in pianura, poco a ovest di Valanaar."
S["ba46865c"] = "L'aria freme di energia, Arcidruido. Quali sono le condizioni del Forest Lord?"
S["ba46e3fa"] = "Riunisci questi due amanti abbandonati, se vuoi."
S["ba50dd5f"] = "Vattene, mortale. Non sei $Gdegno:degna; della mia conoscenza."
S["ba564c52"] = "RARRRRRR!"
S["ba584eda"] = "L'oscurità non ti abbraccia, $C. Basta con le chiacchiere, togliti dalla mia vista! Vattene!"
S["ba5bad8f"] = "Sono $Gringiovanito:ringiovanita;!"
S["ba61a155"] = "Bah! $N, questo piede non si muove!"
S["ba693b7e"] = "Lo spirito della forza non è sempre una questione di forza fisica. Prendere la mia forma vuol dire affrontare le avversità, quelle dentro di sé e quelle fuori."
S["ba6ab14a"] = "Throm'ka, $C! Sei $Gpronto:pronta; a combattere per l'Orda nella Warsong Gulch?"
S["ba702924"] = "Cos'è successo ai nostri maiali?"
S["ba73e39c"] = "Va bene, va bene. Insomma, diciamo che mi sono $Ginfilato:infilata; nell'ombra.$B$BA Windsor la cosa non è andata molto giù, visto che era già parecchio di cattivo umore. Be', si è messo a far roteare il vecchio Ironfoe urlando contro gli orchi come un pazzo."
S["ba77083c"] = "Ora che la guerra è nel vivo, di combattenti validi non ne sono mancati, né dall'Orda né dall'Alleanza.$B$BSe solo riuscissimo a impedire che si saltino alla gola tra loro..."
S["ba785813"] = "Speriamo che i rinforzi da Stormwind arrivino presto. . . ."
S["ba839a64"] = "Ah, cerchi la saggezza di Ansekhwa. Lo trovi da Thunder Bluff Weapons, sull'altura inferiore."
S["ba8bf4b1"] = "Segui la strada verso nord fino a Orgrimmar. Lì puoi chiedere a uno dei grunt dove si trova l'Istruttore di Cucina."
S["ba926ccf"] = "Salute, $Gamico mio:amica mia;, e $Gbenvenuto:benvenuta; al più grande spettacolo di Azeroth!$B$BPrego, fatti avanti e goditi tutto quello che abbiamo da offrirti. Lasciati stupire dalle meraviglie che la Darkmoon Faire ha scoperto in questo mondo vasto e misterioso! Non abbiamo badato a spese per regalarti emozioni che faranno la gioia di grandi e piccini!"
S["ba986842"] = "Entra, entra. Solo non sederti troppo vicino alla stufa. Oggi ancora non è esplosa, ma per sicurezza è meglio se ti metti da un'altra parte."
S["ba9e88f9"] = "Atiesh, Greatstaff of the Guardian. Il bastone che per secoli è stato tramandato a ciascuno de The Guardians of Tirisfal. Il bastone che Sargeras ha corrotto. Il bastone dell'ultimo Guardiano. Il bastone di Medivh."
S["baa42e29"] = "In questo negozio gira Bixi Wobblebonk, la maestra d'armi gnoma: può insegnarti a usare la balestra, i pugnali e le armi da lancio.$B$BWoo Ping, il maestro d'armi umano del Weller's Arsenal a Stormwind, insegna a usare la balestra, i pugnali, le spade a una e a due mani, le armi in asta e il bastone.$B$BIlyenia Moonfire, la maestra d'armi elfa della notte, sta alla Terrazza del Guerriero a Darnassus, e lì insegna a usare l'arco, i pugnali, le armi da pugno, il bastone e le armi da lancio."
S["baa42e71"] = "Ho pianto come un bambino quando ho saputo delle tue imprese eroiche. Master Ravenholdt farebbe bene ad avere $Gun apprendista:un'apprendista; come te."
S["baa67409"] = "%s muove i baffi verso $N."
S["bab34ef8"] = "Immagino che non ti aspettassi di trovarmi in questa caverna, vero?$B$BMi chiamo J.D. Su come sono arrivata qui non posso dirti molto, ma una cosa te la posso dire: adesso questa caverna è casa mia!$B$BPasso il tempo a studiare gli strani cristalli sparsi per tutto il cratere."
S["baba5014"] = "Sì, $C, hai sentito bene: le nostre raccolte sono tutte complete e l'ultimo carico di materiale bellico dovrebbe arrivare a Silithus nei prossimi giorni. Mi dicono che, una volta radunato tutto là e preparate le nostre truppe, qualcuno tra le fila di voi eroi suonerà il gong fuori da Ahn'Qiraj, dopo aver già ricomposto lo Scepter of the Shifting Sands con cui farlo. Spero che non dovremo aspettare troppo perché succeda."
S["babd2682"] = "Sono $Gpronto:pronta; a volare, Comandante. Basta un vostro ordine e piomberò sulla loro base come un trogg sulla roccia."
S["bac06b57"] = "Bene, hai del fegato! Mi piace. E allora diamoci da fare!"
S["bacd0e9c"] = "Saluti. Sono $Gun istruttore:un'istruttrice; di stregoni, ma tu non sei $Gun stregone:una stregona;!"
S["bacf76d8"] = "Ecco fatto. La nostra lezione sull'evocazione è terminata. A breve comincerà una nuova lezione, quindi se vuoi ripassare, resta pure."
S["bad89865"] = "E a tagliare il traguardo è la macchina degli gnomi! Vincono gli gnomi!"
S["badff4b4"] = "Nessuno può sfidare la Fratellanza!"
S["bae235ca"] = "Magar's Cloth Goods sta ne The Drag: lo trovi a sud di quell'albero enorme accanto alla Kodohide Leatherworks."
S["baedbcf3"] = "Salve, ragazzo... mi chiamo Oglethorpe, e se hai uno di quegli straordinari congegni gnomeschi, magari l'ho fatto proprio io! Se è esploso, non sono stato io; ma se ti ha reso ricco, possiamo parlare di percentuali!$B$BAh, e se vieni da Gnomeregan, puoi prendere due angoli di novanta gradi, sbatterli insieme e metterti in marcia: non ho niente da dirti."
S["baf37230"] = "Salute, giovane $C. È qui che il tuo Capoguerra sfidò Orgrim Doomhammer! Anche se sono passati tanti anni, è un'immagine ancora viva nella mia mente."
S["baf7a2c6"] = "Il tuo acciaio è forte, la tua abilità ancora di più. Porta il tuo acciaio e la tua forza alla mia compagna Shayis Steelfury, la sua abilità nel forgiare armature non ha eguali, nemmeno io sono al suo livello."
S["bafc7b2d"] = "Darrowshire! Siete condannati!"
S["bafe34a8"] = "Non me l'aspettavo che foste tutti capaci di una simile organizzazione. Sia l'Alleanza sia l'Orda hanno completato i preparativi per la guerra di Ahn'Qiraj. Proprio mentre parliamo il materiale viene spedito a Silithus e dovrebbe arrivare tutto entro un giorno. Poi toccherà a chi ricomporrà lo Scepter of the Shifting Sands suonare il gong sulla Scarab Dais e aprire le porte di Ahn'Qiraj. Sarà allora che la guerra comincerà davvero!"
S["bb0002d4"] = "Cos'è stato? Hai lasciato acceso quel razzo di segnalazione?!"
S["bb0332fa"] = "Il Cimitero di Frostwolf è controllato dall'Alleanza."
S["bb046337"] = "Kil kek Ruk'ka'ha!"
S["bb06b708"] = "Infine, si sa che i briganti di strada, comuni nei Gustberry Lowlands, accumulano ogni genere di cianfrusaglie nei loro accampamenti. È probabile che fra quel bottino si trovino dei pezzi di costrutti."
S["bb22ba74"] = "Hulfnar! Thontek! In piedi e rispondete."
S["bb31a8f7"] = "Fimble Finespindle ha bottega sul lato nord-occidentale di The Great Forge. Ci scommetto che potrebbe insegnarti a fare delle belle armature."
S["bb3cc877"] = "$GQuesto:Questa; $C si intromette nel nostro lavoro! Muori, $Gsciocco:sciocca;!"
S["bb3e315b"] = "Ciao di nuovo, $N! Che bello rivederti! La nostra Darkmoon Faire è proprio uno spettacolo, non trovi?$B$BC'è davvero tanto da vedere! Quindi guarda! Guarda e forse, un giorno, ti verrà rivelato anche di più..."
S["bb4355a1"] = "The Lich King cerca di far sentire la sua presenza nel nostro mondo. Non dobbiamo permetterlo."
S["bb46690d"] = "Informazioni sui Frayed Abomination Stitchings."
S["bb48b880"] = "Raze segue $N! Raze SPACCA bracconieri! SPACCA SPACCA SPACCA! Di' a Raze di SPACCARE giocando con bastone! SPACCA!"
S["bb55e91f"] = "$N. Questi gusci mi dicono molto, ma temo che ora sollevino molte altre domande..."
S["bb5ed0ed"] = "Non ho mai detto che tu fossi qui per redimerti, sacerdotessa. Sei qui per redimere me, e con me gli innocenti assassinati mentre cercavano di fuggire da Stratholme.$B$BIl mio spirito e quelli dei caduti sono legati a questo luogo: siamo maledetti, costretti a rivivere senza fine le nostre tragiche morti."
S["bb5ff9cd"] = "Anche se ce l'avessi, $Gsciocco:sciocca;, credi davvero che te lo lascerei prendere così? L'unico modo per averlo — se davvero lo avessi — sarebbe strapparlo dalle mie fredde dita morte.$B$BE questo, $Gpiccolo amico:piccola amica;, non succederà tanto presto."
S["bb61830a"] = "Devi fare ciò che ritieni giusto, Marcus. Abbiamo servito insieme sotto Turalyon. Lui ci ha resi gli uomini che siamo oggi. Con me ha sbagliato? Credi davvero che io voglia danneggiare la nostra alleanza? Che voglia disonorare i nostri eroi?"
S["bb68e0e0"] = "Vuoi pescare? Allora ti serve l'attrezzatura giusta."
S["bb694416"] = "Un libro di un goblin sulle vittorie militari degli gnomi... e tutte le pagine sono bianche. Tipico."
S["bb7ec9d3"] = "Meglio muoverci, prima che ne arrivino altri."
S["bb80f92e"] = "Un altro a terra!"
S["bb857e00"] = "Va' avanti senza di me! Raggiungerò Tarren Mill da solo."
S["bb88df3a"] = "Non sapevo che si sposasse! Non sapevo nemmeno che uscisse con qualcuno! È terribile! Non potrà più lavorare di notte!"
S["bb92ac21"] = "Salute, $C. Confido che tu mi porti buone notizie sull'evento Worldwide Invitational. Se è così, allora di sicuro ti hanno dato un codice segreto da dirmi. In cambio del tuo codice ti regalerò uno dei cuccioli di panda di cui mi prendo cura.$B$BSussurramelo all'orecchio quando sei $Gpronto:pronta;."
S["bb98146a"] = "Gul'dan. Un nome che non molti hanno sentito su Azeroth.$B$BPurtroppo, non è la risposta giusta."
S["bb9b9bc5"] = "Esatto, ehm, $Gragazzo:ragazza;, tutto il materiale bellico viene trasportato a Silithus e l'ultimo carico dovrebbe arrivare entro un giorno. Dopo di che dovremo solo aspettare di vedere chi manderà avanti $Gun eroe:un'eroina; a ricomporre lo Scepter of the Shifting Sands e a suonare il gong sulla Scarab Dais. Solo allora comincerà la guerra, con l'apertura delle porte di Ahn'Qiraj."
S["bba75d65"] = "Il grido di morte di %s ha risvegliato l'alveare silithid qui vicino!"
S["bbaa6d88"] = "Ciao! Sono Luis! Che ne pensi di me finora...?"
S["bbabd162"] = "Prendi quella testa e di sicuro Daryl si prenderà un bello spavento. Non che non se lo meriti, quel maledetto arrogante. Ah! Non vedo l'ora di vedere la sua faccia quando gliela mostrerai."
S["bbafce43"] = "Basta così! Niente più birra finché non si sistema questo casino!"
S["bbb50def"] = "Non profanerete la nostra terra sacra!"
S["bbb9b4af"] = "L'Occhio vede tutto ciò che è nella sua sfera d'influenza, $C. Che cosa desideri vedere?"
S["bbbc7898"] = "Di' ciao al mio piccolo amico."
S["bbc24c90"] = "Hai barato!"
S["bbc5dc29"] = "Se degli animali che devi uccidere non sprechi nulla, ne onori gli spiriti. Aska Mistrunner ti mostrerà come fare: ha una cucina sull'altura superiore."
S["bbc94d1c"] = "Al lavoro, marmaglia. La nave dev'essere finita presto."
S["bbcca4de"] = "Bene, la pausa pranzo è finita, ragazzi. Torniamo al lavoro. Se il resto della giornata va così bene, magari staccheremo prima."
S["bbd095c5"] = "Rompere questa pietra dell'anima è un gioco da ragazzi!"
S["bbd2a2e4"] = "Saluta i miei piccoli amici!"
S["bbd4e762"] = "Okothos ti addestrerà, $N."
S["bbd541a9"] = "Shhh... non senti un odore?"
S["bbd830a1"] = "Stammi lontano, mostro!"
S["bbda061e"] = "Mi dispiace, ma non posso istruire altri apprendisti. Cerca Mak a Thunder Bluff. Lui potrà insegnarti le basi."
S["bbe026c6"] = "Finito! E i risultati sono straordinari. Devo proprio riferirli ai miei soci Grimand, Mathiel e Klockmort!"
S["bbf204b7"] = "The Scepter of the Shifting Sands è di nuovo intero, $N.$B$BDevi essere tu a usare lo scettro. Devi essere tu ad annunciare la nuova era del tuo popolo.$B$BDevi aspettare che gli eserciti dell'Orda e dell'Alleanza arrivino a Silithus prima di poter suonare il Gong dello Scarabeo. L'ora della guerra è vicina."
S["bbf4c7ba"] = "La Stormpike Aid Station è sotto attacco! Se nessuno lo ferma, l'Alleanza la conquisterà!"
S["bbf788e5"] = "Non ne posso più di queste tasse! Il fisco mi tartassa? Io tartasso il fisco!"
S["bbf82e0e"] = "%s scava fuori dalla sabbia per proteggere le sue uova."
S["bc02d703"] = "Mi dispiace, $C, ma non ho niente da insegnarti. Sto ancora imparando anch'io!"
S["bc09795b"] = "Rigogliosa com'è, questa pianta di drago notturno è in netto contrasto con la contaminazione demoniaca che lacera il Felwood. La pianta è carica di frutti rari e succosi che ne pendono pesanti: li chiamano Night Dragon's Breath."
S["bc0c5508"] = "Saluti, $C. Sei $Gvenuto:venuta; a cercare le benedizioni del Signore del Vento?"
S["bc0d9e2e"] = "Il vostro mondo subirà una fine spietata. L'Incubo viene a prendervi!"
S["bc10f6f3"] = "<Mentre ti avvicini, questo raptor ti segue con gli occhi dorati, dove passa un lampo malizioso. Dilata le narici e brontola.$B$BSenza il minimo preavviso, sferza con la grande coda il raptor che ha accanto: l'altra creatura ruggisce contrariata e fa schioccare i denti. Mentre gli addestratori rimproverano il vicino, il raptor che hai davanti sembra proprio divertirsi. Con quella natura ribelle, è chiaro che questo raptor avrà bisogno di una mano ferma e di un cavaliere sicuro di sé.$B$BSembra contento che il suo carattere dispettoso non ti abbia fatto tirare indietro subito. China la testa verso di te, segno che ti porterà volentieri in groppa sia come $Gamico:amica; sia come $Gcavaliere:cavallerizza;.>"
S["bc202de7"] = "Sparite, creature immonde! La vostra specie non ha posto in questo mondo."
S["bc2d22fb"] = "Mi hanno cresciuto ed educato per il servizio pubblico. Un rappresentante del popolo. Il mio talento non stava nelle armi o nei mestieri, ma nelle parole e nella persuasione."
S["bc408a4b"] = "Ora, se girate a pagina 34 del vostro testo, vedete l'illustrazione di un nano sottoposto a dissezione..."
S["bc420e5f"] = "Non puoi nulla contro i Blackrock Orcs!"
S["bc4c273b"] = "È ora che mi faccio il mio giro."
S["bc4f3132"] = "Elder Obsidian si aggira dalle parti del Sepulcher, nella Silverpine Forest."
S["bc563472"] = "I nani non si ubriacano, signorina. Sono solo un po' $Gbrillo:brilla;.$B$BComunque, Windsor? Mi sa che sta da qualche parte nei Blackrock Depths. È la città dei Dark Iron, per voi gente ignorantata."
S["bc584b70"] = "%s armato. Aerie Gryphon in arrivo."
S["bc5a2414"] = "Horgus, il tuo incubo finisce! Ora!"
S["bc5baf1d"] = "Annalise? Annalise! No, non lasciarmi!"
S["bc623af9"] = "<Tarsis è ferito gravemente.>"
S["bc647a6a"] = "$N, sei $Gtornato:tornata;! Gli spiriti del mio ultimo pasto mi hanno detto che saresti $Gvenuto:venuta; a trovarmi e che avremmo parlato d'affari.$B$BAvevano ragione?"
S["bc6f596e"] = "Lo stormo cromatico si occuperà di questi intrusi. Parliamo di questioni più urgenti."
S["bc74deba"] = "Sbrigati, $N. Il mio destino è nelle tue mani."
S["bc779a26"] = "Prendete una corda!"
S["bc794215"] = "Aspetta... tu non sei mio marito. Ma deve averti mandato lui. E tu... sembri... squisit$Go:a;!"
S["bc7d9b4d"] = "Sì, puoi, $N. Ma non allontanarti troppo da casa."
S["bc956e3a"] = "Troviamo il prossimo, $N."
S["bcadd6f9"] = "Be', ho visto di meglio, ma non nego che hai del potenziale. Fa' attenzione e forse qualcosa imparerai!"
S["bcb345ef"] = "Ho proprio il posto giusto per questo corno!"
S["bcb3f23a"] = "Salve, $C. Io sono High Tinker Mekkatorque, degli esuli di Gnomeregan."
S["bcb8b772"] = "Avvio rappresentazione di supporto visivo numero due.$B$BRispetto alla matrice sotterranea standard, la seconda varianza risultante della matrice Earthen conserva molti degli elementi desiderati. Nella nomenclatura comune, questa variante è detta \"Nano\".$B$BLa variante conserva la forza e la resistenza intrinseche degli Earthen, e in alcuni casi il nano supera persino le capacità cognitive della matrice degli Earthen. Tuttavia, non conserva nulla della composizione fisica dei vari composti del nucleo di pietra di Azeroth."
S["bcb9ef01"] = "Fa piacere vedere qualcun altro combattere lo Scourge a Stratholme, perché è proprio qui che è più forte.$B$BSalve, sono Aurius. Un tempo ero un paladino della Silver Hand, ma come altri a cui ha vacillato la fede... sono caduto in disgrazia. Lo Scourge mi ha sedotto, e per poco non ha fatto di me un cavaliere della morte!$B$BQuando finalmente mi sono accorto del pericolo, sono fuggito in questa cappella. È un luogo sacro: qui il primo paladino, Uther the Lightbringer, è stato consacrato nell'ordine della Silver Hand."
S["bcc46b8f"] = "C'è un tempo e un luogo per ogni cosa, anche per rilassarsi. Sul lato occidentale di Bloodhoof Village, Innkeeper Kauth gestisce una casa lunga per chi cerca riposo: lo troverai lì."
S["bcd877e1"] = "Oh, adesso mi hai fatto arrabbiare!"
S["bce062ca"] = "È arrivata in città la Darkmoon Faire! Non perderti lo spettacolo più emozionante della tua vita!"
S["bce062e8"] = "È arrivata in città la Darkmoon Faire! Non perderti lo spettacolo più emozionante che vedrai mai!"
S["bce5d49f"] = "$N, ho creato il totem purificatore."
S["bce5fb65"] = "Grazie."
S["bceb192f"] = "Ah, mantenere l'ordine qui è già difficile senza tutti questi guai nuovi che saltano fuori! Spero che tu abbia buone notizie, $N..."
S["bcf37be9"] = "Sono assolutamente $Gcerto:certa; di voler imparare la conciatura elementale."
S["bcf6ab55"] = "Fuoco!"
S["bcfac41e"] = "Sei $Gvenuto:venuta; a sentir parlare delle battaglie vinte e perse su questo campo? Qui non c'è nessun vincitore..."
S["bcfdae24"] = "Il Capoguerra mi ha incaricato di studiare armi e armature di ogni tipo. Mi ha mandato qui, nel cuore della cultura tauren e di quella orchesca delle Barrens, a incontrare più viaggiatori che posso e a conoscere le culture delle Barrens.$B$BSecondo lui c'è qualcosa da imparare anche dalle culture più miserabili... come quella dei quilboar o dei centauri."
S["bd08cd58"] = "Sto per morire, me lo sento!"
S["bd09cd15"] = "Sei quasi all'apice dell'addestramento. Per diventare $Gil miglior incantatore:la miglior incantatrice; possibile ti resta da cercare un'ultima istruttrice: si chiama Annora e la trovi a Uldaman."
S["bd0b0916"] = "Già. Mai sentito parlare di Ironfoe? Il leggendario martello ammazza-orchi? Già, già, era il martello del vecchio Windsor. Mi ha raccontato che l'aveva forgiato Franclorn Forgewright in persona per il suo bis, bisnonnetto. THE Franclorn Forgewright: il Dark Iron responsabile dell'archimettura in pietra lavorata... roba da costruzioni, insomma. Ha detto pure che il martello aveva un gemello, e che Franclorn se l'è tenuto per sé. Mi pare che lo chiamasse Ironfel o qualcosa del genere."
S["bd0bcac3"] = "È un po' danneggiato, ma dovrei comunque riuscire a ricavarne qualche buona informazione."
S["bd0e7552"] = "Dove stiamo combattendo lo Scourge?"
S["bd0f3d6a"] = "I Nelghor-shomash domineranno questo mondo!"
S["bd10bc08"] = "Sei gentile a chiedere, $C, ma abbiamo tutto il cuoio leggero che ci serve. Magari a uno degli altri incaricati della raccolta qui serve il tuo aiuto, però?"
S["bd235337"] = "Fermi! Voi vermi questo lo chiamate combattere? È penoso! Adesso metteteci il cuore, tanto non vi serve più!"
S["bd2cdd6b"] = "Se sei $Gvenuto:venuta; a salvare il mondo, sei nel posto giusto. Il senza volto — il Dio del Sangue, Hakkar — l'hanno riportato nel nostro mondo!"
S["bd2ecd41"] = "Elisir miracolosi di Antonio Perelli in vendita!"
S["bd316ae4"] = "Niby, sei stupido."
S["bd360240"] = "Una volta ho avuto il piacere di vedere Kyra Windblade combattere, e dopo quello che ho visto sono $Gcerto:certa; che ti addestrerà bene. Cercala alla Locanda di Dolanaar."
S["bd377210"] = "Halo ich zhi paw. Awa ta shne a shte."
S["bd393efe"] = "Salute, $C! $GBenvenuto:Benvenuta; nella Cathedral of Light!"
S["bd3e2d2d"] = "Cosa? Ma come? No! Non è possibile! Sono $Gstato:stata; così $Gattento:attenta;... lui non poteva saperlo!$B$BMenti! Menti, e adesso morirai per il tuo inganno!"
S["bd46bf67"] = "$GUn altro:Un'altra; $Gesperto:esperta; di sopravvivenza, mmh. Dubito che la tua abilità sia pari alla mia, quindi forse posso insegnarti qualche tecnica come si deve."
S["bd50103c"] = "%s annusa l'aria..."
S["bd5c5725"] = "%s corre in aiuto di Stalagg!"
S["bd5d44d2"] = "Disonoriamo i nostri antenati. Disonoriamo quelli che abbiamo perso... perdonami, Reginald."
S["bd6298b0"] = "Qui il pericolo potrebbe nascondersi dietro ogni angolo."
S["bd666639"] = "Degli intrusi hanno attaccato il covo. State in guardia!"
S["bd679717"] = "I furfanti bazzicano tutti in The Forlorn Cavern, a nord dei cancelli di Ironforge. Scommetto che ci troverai Fenthwick, intento di sicuro a contare le monete di qualche altro tagliaborse. Prima o poi lo acchiappo!$B$BE intanto tengo d'occhio anche te, ragazza."
S["bd6ba1c1"] = "Io... Non so bene come ci sono arrivato, qui...$B$BMi pare di ricordare un viaggio... una zattera..."
S["bd74cde9"] = "Non dobbiamo arrenderci!"
S["bd81b548"] = "Gli intrusi sconsiderati, i Nightclaw non li vedono di buon occhio. Finché sei a Shadowgale, muoviti con cautela, $C."
S["bd914f99"] = "Morte a te, $N. Come osi avvicinarti a un tiro d'arco da me!"
S["bd929ed1"] = "%s fuggono mentre il potere di controllo del globo si esaurisce."
S["bd9a2bc3"] = "Forse, dopotutto, questo non era il posto migliore per un negozio..."
S["bd9fbd3b"] = "Dicono che io sia $Gbenedetto:benedetta;: un araldo chiamato ad annunciare una nuova era."
S["bda22bac"] = "Per questo vivrai per sempre nel tormento, patetico stregone."
S["bdabf827"] = "Tessera di sicurezza blu inserita correttamente. Erogazione dell'unità di livello di sicurezza delta.$B$B01010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111"
S["bdad0cbd"] = "Salute. Sono Ayessa Dawnsinger, l'attuale Gran Veggente del Cielo dei Windshapers. Che cosa posso fare per te?"
S["bdaf2910"] = "%s butta giù la sua bottiglia di veleno per la disperazione!"
S["bdb291b9"] = "Io, a differenza di quasi tutti gli ogres, lo so a cosa serve una latrina — a ficcarci dentro la tua testa e tirare lo sciacquone. Ora sparisci."
S["bdb53e39"] = "T'ho visto combatte' meglio de così, Lana! La prossima volta li becchi! Tark, va' là dentro e fagli vede' l'inferno!"
S["bdc2490e"] = "Mmm... adoro la mia deliziosa birra scura di Southshore."
S["bdc4a4fd"] = "Credo che tu sia all'altezza di questo compito... accetterai la sfida?"
S["bdc6abfa"] = "Se vuoi diventare $Gmio allievo:mia allieva;, dovrai portare a termine un incarico per me. Dimostrati $Gdegno:degna; e potrei perfino pensare di ricompensarti."
S["bdc97166"] = "Lasciatevi sollevare dall'impresa di $N! Esultate al suo grido di battaglia!"
S["bdde9eb6"] = "Josetta è stata una benedizione per questa città: ha dato una mano alle guardie del posto. Se la cerchi per farti addestrare come $Gsacerdote:sacerdotessa;, la trovi nella Lion's Pride Inn."
S["bde41595"] = "È bene che tu voglia onorare le tue prede usandone i corpi. Cerca Thuwd dentro la Kodohide Leatherworks, al centro de The Drag."
S["bde57a33"] = "La battaglia per l'Alterac Valley è cominciata!"
S["bde8a1f6"] = "Le nostre antiche terre si trovano nel nord-est dell'Eastern Kingdom. Il regno prende il nome da Lordain in persona, e un tempo era fiero e potente. Ha una storia ricca, che ha molto da insegnare a nobili e re arrivisti, e fra i suoi momenti decisivi c'è l'aver contribuito a fondare l'Alleanza che oggi conosciamo.$B$BPurtroppo è anche una storia oscura, e chi oggi ci vive ne profana le terre giorno dopo giorno. Nelle rovine che ora si trovano sopra l'Undercity c'è ancora molto di importante, ma tentare quel viaggio contando di tornarne vivi è una follia."
S["bdeafb46"] = "Oh sì, vecchio, Hakkar è tornato. Presto il mondo crollerà sotto la sua potenza. Divorato. Ridotto in rovina..."
S["bdedbe5f"] = "Il Frostwolf Graveyard è in mano all'Orda."
S["bdf03680"] = "Och... un paladino? Be', ragazzo, ti va bene! Azar Stronghammer è tornato dall'addestramento e per ora alloggia alla Thunderbrew Distillery a Kharanos."
S["bdf59a7f"] = "Stiamo facendo progressi! Porta altre provviste per riparare Dun Baldar!"
S["bdfee1b5"] = "Cosa? Perché mi disturbi? Scommetto che non sai fare nemmeno una veste di alta qualità! Va' a parlare con Snang e torna quando sarai $Gdegno:degna; del mio talento!"
S["be0ffc82"] = "Verserò il tuo sangue, $C!"
S["be1ef321"] = "Morte e Lode a The Lich King!"
S["be413123"] = "Bella domanda, $R. Da giovane ero $Glibero:libera; e $Gspensierato:spensierata;, senza preoccupazioni. A quei tempi cantavo in un quartetto barbershop di Stormwind, i Four Dons. È lì che ho imparato a creare la tenuta Bonescythe."
S["be493d8d"] = "$C, non ci vergogniamo ad ammetterlo: nella nostra lotta a Warsong Gulch ci serve tutto l'aiuto possibile. Ma se deciderai di metterci a disposizione le tue capacità, oggi c'è più onore da conquistare che mai. E di certo le Silverwing Sentinels guarderanno con più favore quello che fai per noi. Ti unirai alla battaglia?"
S["be501289"] = "No, qui fuori a Dun Morogh alchimisti non ce ne sono. Faresti meglio a cercarli a Ironforge... prova dagli gnomi, a Tinker Town."
S["be538e9f"] = "La tua arma vile è pronta, $N."
S["be550295"] = "%s è stato distrutto. L'attacco aereo non può confermare il punto d'impatto. Missione annullata."
S["be62eb6d"] = "Mi manca la birra dei nani che prendevamo in quella locanda di Lordaeron. Ti ricordi la rissa che ci abbiamo scatenato?"
S["be670d28"] = "Credo che i rumori venissero da qui. Faremmo meglio a controllare."
S["be6a8be4"] = "Mi serve uno Scrying Scope per guardare nel Globo della Chiaroveggenza, Ryson."
S["be79b46b"] = "Sì, $Gsignore:signora;."
S["be7b39d7"] = "Trovi Brek Stonehoof alla Stonehoof Geology, sull'altura più bassa. Ti può insegnare come si estraggono nel modo giusto i minerali e le gemme preziose."
S["be7f9eeb"] = "Il segreto del coltello è tenerlo nascosto fino al momento in cui colpisci."
S["be8262e7"] = "Basta! Il tempo dei giochi è finito!"
S["be83d5d5"] = "Non voglio farti del male. Sto spiando i quilboar e annoto quello che fanno. La mia gente ha avvertito qualcosa di strano venire da questa zona — un'emanazione o un'oscurità. Sono venuta a indagare, e quello che ho scoperto è molto inquietante.$B$BPare che ci sia un diplomatico non morto, potente nelle arti arcane. Non credo che sia uno dei Forsaken... Penso che sia qualcosa di peggio."
S["be989a1f"] = "Credo che i Forsaken stiano ingannando gli alleati dell'Orda.... aspetta... mi gira così... la testa..."
S["be9b8217"] = "Krug si ferma all'improvviso, lo sguardo attirato da un movimento giù nell'Alveare."
S["bea21e4c"] = "Gri'lek, del Sangue di Ferro$B$BIl viandante. Che la sua forza e la sua brama di battaglia attraversino le ere.$B$BOra Gri'lek dimora lontano da qui. Forse, un giorno, farà ritorno..."
S["bea774c5"] = "Vuoi rifare la gara? Il migliore su tre!"
S["beab6034"] = "Bah! Torno al lavoro! Grazie di cuore, Belm."
S["beac6f96"] = "scatena uno sciame!"
S["bead9279"] = "Il mio dolore è la mia forza."
S["beae4ef1"] = "Sì, mon, sono l'assistente di Gadrin. Questo lavoro da volontario è il mio modo per finire la Scuola per Stregoni. Tu aiuti lui, e allora io aiuto te gratis. Cosa c'è da aggiustare?"
S["beb4f1c0"] = "Non c'è tempo da perdere, $Gsoldato:soldatessa;. Devo tornare alla base immediatamente! Coprimi!"
S["beb51518"] = "Difenditi!"
S["beb70024"] = "Ho fallito... Ho mancato al mio dovere... ho tradito il mio popolo... I worgen dilagano, e la Falce della mia dea è perduta."
S["beb70681"] = "E sono deciso a scoprirne di più... Quindi se ti serve di nuovo il mio aiuto, sai dove trovarmi."
S["bebbe696"] = "Se hai abbastanza oro per pagare la lezione, posso insegnarti i segreti del Cavalcare Tigri!"
S["bed2b52d"] = "La stretta degli Old Gods non cede. È consumato dai loro pensieri oscuri... Io... non riesco... non riesco a incanalare ancora per molto... Elune, aiutami..."
S["bed335f6"] = "Alzatevi, miei soldati! Alzatevi e combattete ancora!"
S["bed6a5fe"] = "Lok'tar Ogar!"
S["bed94d5c"] = "La vostra base è perduta, mortali! Dalle sue ceneri sorgerà la vita!"
S["bed9b85a"] = "Papà! Sei tornato!"
S["bee0cf06"] = "Quel che è. La lurida, disgustosa feccia dell'Orda..."
S["beed7ed5"] = "È fatta! Il Magistrato è morto — nell'ombra, fratelli miei."
S["beee7c46"] = "Se cadiamo, Darrowshire è perduta!"
S["bef83c26"] = "Sono... $Gliberato:liberata;... forse non è troppo tardi per — No! Mi serve... altro... tempo..."
S["befa8e51"] = "Sei $Gpazzo:pazza;? Lo sai che razza di bestie ci vivono, lì? Nella peggiore delle ipotesi, ci tocca raccogliere i tuoi resti con una pala. Per colpa di quei mostri orribili abbiamo perso dei bravi nani.$B$BQuindi la risposta è no. Se sei $Gdeciso:decisa; ad arrivare alla Searing Gorge, dovrai trovare un'altra strada."
S["befc0ee5"] = "Sì, $C?"
S["befec28f"] = "%s comincia a lavorare..."
S["bf01c790"] = "Lunga vita al re, bello!"
S["bf053831"] = "Ehi, Fizzer, ti ho mai raccontato di quella volta che stavo attraversando i canali e dei goblin in tuta trituratrice hanno provato a tendermi un'imboscata?"
S["bf0d6fd9"] = "Subito, padrone!"
S["bf1715ac"] = "Ah! Grazie infinite, $N! Sono $Glibero:libera;! Finalmente!"
S["bf172e97"] = "Purtroppo la difesa degli elfi della notte era insostenibile, e Rajaxx sapeva che non avrebbero resistito ancora a lungo. La loro tenacia però causava una grande frustrazione a Rajaxx, e ancora di più al suo re. Un momento, re? Incredibile..."
S["bf19709e"] = "Sei $Geliminato:eliminata;."
S["bf1aaeab"] = "Qualcosa non va... dov'è finita l'esplosione?"
S["bf1b071b"] = "Ma se lo spostamento di frequenza che ne risulta rimandasse un contraccolpo magico su per i flussi?"
S["bf1fd304"] = "Saluti, $R. Una giornata meravigliosa per essere vivi, non è vero?"
S["bf2112f7"] = "Stupidità! Sono circondato dalla stupidità!"
S["bf222b71"] = "Drek'Thar è stato sconfitto! L'Alleanza è vittoriosa... per ora.$B$BParla con il nostro intendente e aiutaci nella ricostruzione."
S["bf22944b"] = "Per l'High Order!"
S["bf25e5e0"] = "Saremo in debito con te, $C. Cerca Donal Osgood nell'Hall of Arms. Sarà più che felice di aiutarti nel tuo viaggio verso l'Arathi Basin."
S["bf3297d5"] = "Da queste parti non ne conosco. Ti conviene andare a nord, a Orgrimmar, e parlare con uno dei loro grunt."
S["bf358d36"] = "Per quello che ti interessa, la persona più adatta è Sir Alodan. Sta vicino alle Pools of Vision, con gli altri membri di Undercity."
S["bf396e2d"] = "Regali per tutti! Padre Inverno ha messo doni sotto l'albero per tutti."
S["bf3c2916"] = "Arrivederci, Goldshire. Tornerò abbastanza presto — forse fra una settimana."
S["bf43ca57"] = "Arrivi proprio al momento perfetto, $C.$B$BSono Lotwil Veriatus, membro fondatore dell'Enlightened Assembly of Arcanology, Alchimia e Scienze dell'Ingegneria: vogliamo fondere le scienze intelligenti di Azeroth in un'unica scuola completa."
S["bf4b5087"] = "Ho un sasso nel naso."
S["bf5207d8"] = "Il Flagello prevarrà!"
S["bf5c56c4"] = "Nessuno sa davvero chi abbia creato le Carte di Lunacupa, né a cosa servano in realtà, ma posso dirti che le hanno trovate in tutta Azeroth, di solito in mano a qualche malfattore che cercava di svelarne i misteri.$B$BLe Carte di Lunacupa sono di quattro tipi; Bestie, Elementali, Portali e Signori della Guerra, e ogni seme ha otto carte, dall'Asso all'Otto. Se raccogli tutte e otto le carte di un seme, puoi farne un mazzo e darlo al nostro Professor Thaddeus Paleo in cambio di un potente monile."
S["bf624fcc"] = "Sì, li uccidiamo!"
S["bf6b8d48"] = "%s si divide in due nuove Lava Spawns!"
S["bf6c0b02"] = "Salute, $Gviaggiatore:viaggiatrice;. Avrò anche la vista debole, ma i passi di $Gun:una; $C li sento a un miglio di distanza. Per anni ho difeso Stormwind con orgoglio, finché gli occhi non mi hanno tradito e sono stato costretto a ritirarmi."
S["bf762416"] = "%s fruga tra i teschi..."
S["bf7a95db"] = "%s inizia un incantesimo di evocazione..."
S["bf7c3548"] = "Lo Stonehearth Graveyard si trova a est dello Stonehearth Outpost, nel Field of Strife.$B$BAl momento è controllato dall'Orda."
S["bf7c9e85"] = "Sono $Gtornato:tornata; al punto di partenza."
S["bf7cd81c"] = "Sorgete e difendete il vostro padrone!"
S["bf7d2f1c"] = "La Battaglia per l'Arathi Basin è cominciata!"
S["bf7e6aa8"] = "HO DETTO BUONA GIORNATA!"
S["bf803a67"] = "Le stelle mi parlano. Sussurrano degli orrori che attendono nella notte."
S["bf84a234"] = "%s scambia qualche parola sottovoce con $N e $Ggli:le; consegna un piccolo oggetto."
S["bf88e00d"] = "Oh, hai ancora un sacco di cose da imparare. Se potessi ti insegnerei tutto, ma sto ancora imparando anch'io! Perché non vai a parlare con Trixie Quickswitch, a Ironforge? Ti aiuterà ad andare avanti con la formazione!"
S["bf8e1085"] = "Mi manca un pezzo dei miei Paramenti dell'Augure e mi serve un ricambio."
S["bfa377cf"] = "Ti avverto, mortale: fra i clan minori di questa cittadella, è estremamente raro che qualcuno possieda un oggetto del genere. Potresti cercarlo per decenni. Ti consiglio di distruggere queste bestie impunemente."
S["bfa92028"] = "Saluti, $Gmago:maga;. Vuoi che ti aiuti a conoscere meglio il mondo della magia?"
S["bfaa3e0f"] = "Pover'uomo, questo spiega molte cose."
S["bfc9535f"] = "$N ha assaltato la segheria!"
S["bfd3b076"] = "Sta nella parte più bassa di Thunder Bluff. Cerca vicino alla banca: non è lontano da lì."
S["bfd7c258"] = "Saluti. Se cerchi articoli di cuoio, vedrai che la mia merce è lavorata bene."
S["bfdb0dfe"] = "Sono rimasto a guardare mentre la corruzione di Ragnaros si insinuava nei cuori e nelle menti della nazione Dark Iron. Una razza un tempo onorevole, spinta alla follia... al male.$B$BQuando la Guglia è stata completata, mi è venuta meno la volontà di vivere fra la mia gente. Sono morto da eroe della nuova nazione Dark Iron. Questa tomba l'hanno posta qui — all'ingresso della città che ho progettato e costruito — per onorare i miei sforzi."
S["bfdd0cdf"] = "Il cristallo è coperto di glifi e rune intricati, e non riesci a capirci nulla."
S["bfdf4357"] = "L'Anachronos, questo diversivo darà a te e al giovane druido abbastanza tempo per sigillare il cancello. Non vacillare. Ora vediamo come se la cavano con la magia del caos."
S["bffb7850"] = "Estrazione"
S["bffecf35"] = "<In cima al teschio, le orecchie carnose ruotano appena, mosse da muscoli atrofizzati.>"
S["bffee19d"] = "Parla con me per sentire la mia storia."
S["c005a04a"] = "ROOKERY MINION death DEBUG"
S["c00cdda8"] = "Ho alcuni appunti del lavoro a casa mia. Vado a prenderli e ci vediamo alla locanda."
S["c010d5a4"] = "I miei alberi... sono avvizziti e morti, proprio come me."
S["c02030f3"] = "Se non mi credete, andate a vedere con i vostri occhi! Spettri terribili portati dal vento *hic*... spiriti della foresta che vi rosicchiano le caviglie!"
S["c02f784e"] = "Tannysa la trovi fuori dalle Alchemy Needs, in Mage Quarter."
S["c034ab9e"] = "Sentinella, informa Althea che una terribile minaccia si sta radunando contro la nostra città. Dobbiamo prepararci!"
S["c04260d1"] = "La vecchia Assembly of Thanes è una sala sotto la grande città di Ironforge, la dimora ancestrale del clan Bronzebeard. Arriva giù fino al cuore più profondo di Khaz Modan, e dicono che sia coronata da geodi immense."
S["c046a7c1"] = "Se è questo che vuoi, $C, dovrai parlare con Keras Wolfheart sulla Terrazza del Guerriero. Rappresenta The League of Arathor e può aiutarti ad arrivare all'Arathi Basin."
S["c049776f"] = "Chi osa attaccare il Silverwing Outpost?!?"
S["c04e2f29"] = "Mettiti in viaggio verso Orgrimmar e cercalo nella Valley of Honor. Lavora in un negozio chiamato Arms of Legend."
S["c04fa10a"] = "Mamma!"
S["c05580de"] = "Quid pro quo! Ti insegnerò quello che so, ma prima voglio che tu svolga un piccolo compito..."
S["c05961bf"] = "Cosa possono fare per te queste vecchie ossa, $C? Ti va di sentire una leggenda troll?"
S["c05b1dc3"] = "Crogiolatevi nella gloria del vostro Re e portate la sua benedizione a chiunque minacci la splendente città di Stormwind!"
S["c06635df"] = "Che giornata meravigliosa per essere vivi! Guarda la bellezza che ti circonda, $Gamico:amica;. Goditi ciò che la vita ha da dare!"
S["c06dfbab"] = "Minaccia fisica rilevata! Manovra evasiva! COCCODÈ!"
S["c070140d"] = "Con un po' di fortuna, oggi ci guadagneremo qualche bella cicatrice."
S["c076ebd1"] = "Cheap beer! La vostra cheap beer è proprio qui!"
S["c07a3998"] = "Salve, $C. Da quello che mi dicono è stato raccolto tutto, e proprio ora il materiale bellico viene spedito a Silithus. Dovrebbe arrivare tutto lì in meno di un giorno. Una volta fatto, e suonato il gong con lo Scepter of the Shifting Sands, la guerra comincerà davvero."
S["c07c00db"] = "Il Blastenheimer 5000 Ultra Cannon è un dispositivo di lancio per una sola persona, all'avanguardia. Il cannone può sparare il carico quasi alla velocità di un drago ed è il vanto della famiglia Blastenheimer, famosa in tutto il mondo per le sue imprese aeronautiche e combustibili!$B$BSe vuoi essere $Glanciato:lanciata; nei cieli e volare $Glibero:libera; come un uccello, cerca Maxima Blastenheimer sul bordo sud dell'Hunter Rise di Thunder Bluff: ti punterà verso il bersaglio, lontano a sud, sullo Stonebull Lake!"
S["c07f152a"] = "%s lancia uno stridio acuto per chiamare aiuto!"
S["c07f1537"] = "%s lancia uno strillo acuto, chiedendo aiuto."
S["c0831f35"] = "Edward, ci apri tu la strada. Fila là dentro."
S["c08a08d1"] = "Stai facendo buoni progressi nella tua formazione, e dovresti esserne $Gfiero:fiera;."
S["c08a6ee2"] = "Quanti Ufficiali Frostwolf sono ancora vivi, Vanndar?"
S["c097f271"] = "Lo Scourge è all'ingresso del castello! Per Stormwind! Per King Anduin!"
S["c0a33fd8"] = "Gli orchi sono più svegli di quei corrieri! Dove accidenti sono finiti?"
S["c0abd937"] = "Brock. Torren. Vado dentro a bermi una birra e a scaldarmi accanto al fuoco."
S["c0af6196"] = "Maledetti centauri stupidi! Sigh... beh, sembra che tu abbia rispettato il patto. Più avanti sulla strada troverai Smeed Scrabblescrew, ha i tuoi soldi."
S["c0b5c165"] = "E ora una rapida occhiata a queste gemme."
S["c0bb18a4"] = "Ecco fatto, entrambe le parti hanno raccolto tutto. Ora viene tutto trasportato a Silithus e dovrebbe arrivare entro pochi giorni. Una volta fatto, quando qualcuno suonerà il gong sulla Scarab Dais con lo Scepter of the Shifting Sands, la guerra comincerà!"
S["c0bb343b"] = "Salute a te, $Gcampione:campionessa;. Le tue gesta saranno raccontate per secoli. Forse un giorno una tua statua si ergerà fra gli eroi di Stormwind."
S["c0cb71d7"] = "Va', $Gmio servo:mia serva;. Porta notizie di Stonetalon ad Apothecary Zamah."
S["c0cd2eb4"] = "All'attacco! Per l'Orda!"
S["c0cdbcbb"] = "The Barrens sono piene di sostanze che a noi speziali di Lordaeron potrebbero tornare utili."
S["c0de17c3"] = "Andiamocene da questo posto."
S["c0e60782"] = "Dannazione, Terry..."
S["c0ee061e"] = "Che la tua abilità nel fondere il ferroscuro ti sia utile, $N. Ma non lasciare che il sapere ti corrompa... come ha corrotto noi."
S["c0f4432a"] = "Indegni."
S["c0f5e1e9"] = "Rin'ji ora vede la strada, $N. Rin'ji conosce la via di casa."
S["c10219a1"] = "Non ci posso credere! Mi hai distrutto il branco... Adesso affronta la mia ira!"
S["c107a6d1"] = "È... un'ottima domanda. Faccio fatica a ricordare, ma qualcosa mi è rimasto... \"Ingegnere\", forse? Credo fosse quello che ero, o chi ero.$B$BA parte questo, mi sembra di ricordare solo che volavo alto nel cielo, poi ho visto il lampo di un fulmine e tutto si è messo a sobbalzare. E poi... uno schianto.$B$BPerò è passato... tanto tempo. Tantissimo tempo."
S["c10874b0"] = "Se vai nell'Alterac Valley, parla con Kartra Bloodsnarl. La trovi dentro l'Hall of the Brave, nella Valley of Honor."
S["c10d0737"] = "Osi sfidarmi? Preparati a un'eternità di terrore."
S["c10d47b7"] = "Sono Samuel Hawke, il fornitore principale della League of Arathor di stanza qui nell'Arathi Basin. Man mano che la tua reputazione presso di noi crescerà, ti metterò a disposizione un'ottima scelta di merci che potrebbero tornarti utili. E se devi far riparare i tuoi oggetti, mi occupo anche di questo."
S["c10d9d57"] = "Se hai abbastanza oro per pagare la lezione, posso insegnarti i segreti del Cavalcare Arieti!"
S["c10fe521"] = "Non sei all'altezza della forza dell'Orda!"
S["c1102eeb"] = "Grazie mille, $N. Senza di te non ce l'avremmo fatta. Ah, e se prima avevo detto qualcosa sul ricompensarti per averci salvati, beh... te lo puoi scordare!"
S["c1160bf2"] = "Ti frantumerò le ossa a calci, $R!"
S["c1188807"] = "Le Silverwing Sentinels hanno bisogno di tutto l'aiuto possibile nella lotta contro i Warsong Outriders. Se vuoi aiutarle, $N, va' a Stormwind Keep e parla con Elfarran."
S["c11b7800"] = "$GPatetico:Patetica;..."
S["c11dfc2d"] = "Il segnale è stato mandato. Dovrebbe arrivare a breve."
S["c12c2ecf"] = "Aiuto! Toglietemi di dosso questo $N!"
S["c132635f"] = "Le urla dei moribondi riempiranno l'aria. Una sinfonia del terrore sta per cominciare!"
S["c13a6b33"] = "Se hai abbastanza oro per pagarmi la lezione, ti insegno le finezze della Monta di Skeletal Horse!"
S["c13abeb8"] = "Non fermerai mai i Forsaken, $R. La Dama Oscura ti farà soffrire."
S["c141bb8a"] = "Salute, $C. Ti serve qualche arma?$B$BSono stato allievo di Antarion di Ban'aethal, che mi ha insegnato i segreti tramandati dagli antichi maestri fabbri-maghi di Kalimdor.$B$BSu Zephras Isle armi migliori delle mie non le troverai."
S["c143e19f"] = "La Dama Oscura ha lanciato la sfida. Ora tocca alla Royal Apothecary Society mettere a punto una nuova piaga. Metteremo in ginocchio Arthas e il suo miserabile esercito."
S["c156ca18"] = "Thrall è stato molto gentile a darmi rifugio nel suo dominio. Ma non voglio approfittare della sua ospitalità: portare guai al nostro capo sarebbe un grande disonore."
S["c15d75e6"] = "Parla con Lawrence Shneider ai Duncan's Textiles, dietro l'angolo a sinistra. È bravo con i principianti."
S["c160cbf3"] = "Pazienza... Magari la prossima volta."
S["c1623be9"] = "Non interrompermi."
S["c1629385"] = "Lon algos vil wirsh an vil sturume. Forthis re novas vil ruftvess waldir."
S["c16e4ccd"] = "Circa cinque mesi fa, la divisione di Stranglethorn della Venture Co. ha messo le mani su un veleno speciale, comprato da un losco mercante della Booty Bay di nome Crank Fizzlebub. A quanto pare Fizzlebub aveva rubato il veleno a Zanzil!$B$BSì, Zanzil the Outcast, il troll esiliato dalla sua stessa tribù per la natura dei suoi 'esperimenti' di negromanzia.$B$BOvviamente, una volta avuto il veleno, lo hanno provato gli uni sugli altri. I risultati sono stati disastrosi."
S["c16f12f7"] = "I fili della VITA sono stati recisi! I Sognatori devono essere vendicati!"
S["c170e412"] = "Un paladino della Luce ha davanti molte prove, $N. Stanne $Gcerto:certa;: se resterai $Gappassionato:appassionata; e fedele alle virtù che lodiamo, in futuro le nostre strade si incroceranno molte volte."
S["c1712336"] = "comincia a creparsi!"
S["c1768f0e"] = "Forse Ograbisi userà tua testa come cappellino quando io finito con te."
S["c178ba9f"] = "Buongiorno, Corbett. Ecco il tuo formaggio, fresco di stamattina! Come vanno le cose in negozio?"
S["c17ce5b4"] = "%s comincia a rispondere a tutti gli attacchi contro di lui!"
S["c17f2f1f"] = "Buonanotte, signori. Dormite bene."
S["c187cc26"] = "Il martello e la forgia non sono l'unico modo per rinforzare l'acciaio, giovane viandante. Vuoi saperne di più?"
S["c18ed139"] = "Saluti, $N. Sei $Gvenuto:venuta; a conoscere la storia di Ironforge?"
S["c197e775"] = "Gli Old Gods risorgeranno. Non ti permetteremo di interferire!"
S["c19a3feb"] = "La robusta cassa è al centro della segheria, in mezzo ai detriti e circondata da seguaci molto zelanti della Scarlet Crusade."
S["c19e2bce"] = "Frutta succosa in vendita!"
S["c19e3451"] = "Scatenerò la cavalleria al tuo comando, $Gsignore:signora;!"
S["c1a27c7a"] = "Portatemi con voi, $Gsignore:signora;."
S["c1a349ea"] = "%s emette un ringhio gutturale mentre il suo corpo si accascia. Un ululato spaventoso echeggia per le sale di Blackrock Spire. Qualcosa è molto, molto arrabbiato."
S["c1ab5175"] = "Un giorno Zul'jin tornerà, $R, ricorda le mie parole. Nell'attesa teniamo tutti la posizione e facciamo il possibile perché la popolazione dei troll della foresta resti intatta.$B$BDetto questo, da capocacciatore di Revantusk Village tocca a me fare in modo che il mondo intorno a noi sia un posto sicuro in cui vivere.$B$BLe bestie di questa zona vanno tenute sotto controllo.$B$BCerchi lavoro?"
S["c1ada456"] = "Sistemi di occultamento attivi! COCCODÈ! Occultamento inserito per il trasporto a Booty Bay!"
S["c1b1eee3"] = "Tu trovi, tu tieni! Non dire a nessuno che Rin'ji ha parlato con te!"
S["c1b33d09"] = "Una banda di predoni laggiù! Fuoco!"
S["c1b572f7"] = "Che il sangue versato qui oggi sia una lezione per tutti coloro che osano invadere il territorio del Blackrock Clan!"
S["c1b6abae"] = "Pregate per la vostra salvezza!"
S["c1b7f76a"] = "%s comincia a salmodiare..."
S["c1becebe"] = "A revos ruk amir veni gul!"
S["c1c2c7a9"] = "Ti schiaccerò il cranio sotto lo stivale!"
S["c1c84675"] = "Ormai tutte quelle faccende ufficiali si sbrigano su a Stormwind. Se vuoi fondare una gilda, potresti passare dallo Stormwind Visitor's Center."
S["c1d3c41d"] = "Per vincere nell'Alterac Valley le nostre forze hanno bisogno di saggezza, $C, e tu hai l'aria di $Gquello:quella; che può guidarle."
S["c1d83de0"] = "Vaelastrasz, quando questo mondo apparterrà allo stormo nero, il tuo stormo conoscerà la sua fine."
S["c1e55753"] = "Sono anni che non penso col cuore, ma adesso mi sta tornando tutto in mente come un fiume in piena."
S["c1e7168a"] = "I Defias trionferanno! Nessun avventuriero da strapazzo ci fermerà!"
S["c1eb5b70"] = "La Tower Point presidia il passo tra il Field of Strife e i territori dell'Orda a sud.$B$BÈ controllata dall'Orda."
S["c1ede775"] = "Forse questa volta sei $Griuscito:riuscita; a fermarci, ma torneremo — te lo assicuriamo!"
S["c1f1a763"] = "Och! Vuoi addestrarti nella via del guerriero, eh? Kelstrum Stonebreaker ti metterà alla prova come si deve! Ti basta marciare fino all'Hall of Arms, a est dei cancelli di Ironforge."
S["c1f8b974"] = "Ci chiamavano la Thrall's Grasp: venti fra i soldati più abili e onorati di Thrall.$B$BAvevo ordinato al reggimento di piantare un accampamento qui, al confine delle Blasted Lands, in attesa degli ordini da Orgrimmar. Sono passate settimane senza notizie dal capoguerra, e gli uomini si facevano irrequieti.$B$BLa decisione toccava a me, $N. Ero giovane e $Gambizioso:ambiziosa;, non avevo paura di niente. Sotto il mio comando, il battaglione si sarebbe addentrato nelle Blasted Lands.$B$BUna decisione di cui mi sarei poi $Gpentito:pentita;."
S["c200dc02"] = "Un'altra domanda della prima catena ha avuto RISPOSTA!"
S["c2032ca0"] = "Shaha lor'ma. Che Elune sia con te."
S["c20f9cc9"] = "Non lo vedi che ci stiamo preparando alla visita di Uther? E ora levati di mezzo, ho un mucchio di lavoro da fare!"
S["c2149a6a"] = "Lo dico alla Mamma!"
S["c214cd70"] = "Anathera... Non posso sopportare di affrontare il resto dell'eternità senza di te al mio fianco... Se mi sarai portata via, che questo sia anche il giorno in cui io torno alla terra..."
S["c22185ad"] = "Sì, lo so, sembra che abbiamo già tutti i lingotti di mithril che ci servono per la guerra. Ma sai, qui intorno c'è ancora un sacco di gente a cui probabilmente servirebbe il tuo aiuto proprio adesso. Grazie, amico."
S["c2283a03"] = "Allora devi parlare con Komin Winterhoof, da Holistic Herbalism. Lo trovi sull'altura centrale."
S["c228f8ec"] = "%s scatena una burrasca che spazza la terra, e da nordovest giunge il suono della sua furia insensata."
S["c2319ba3"] = "E non so niente di questo vostro fuoco..."
S["c23266b2"] = "Alle mie spalle c'è l'Altar of Zanza, un luogo sacro per noi Zandalar. Veniamo a pregare qui per rafforzare la nostra determinazione in vista della guerra contro il Dio del Sangue, Hakkar.$B$BSe vuoi dimostrare il tuo valore alla tribù, usa l'altare per distruggere tutti i Bijous Hakkari che potresti trovare dentro Zul'Gurub. E per le serie di monete che potresti trovare a Zul'Gurub ti darò in cambio i Gettoni d'Onore che usa la nostra tribù. Portami le monete che cerco e sarai $Gricompensato:ricompensata;!"
S["c2365b13"] = "Guarda, druido. La terra respira ancora. Desidera essere purificata."
S["c23b21ce"] = "Noi sentire e obbedire."
S["c23ee78b"] = "E cosa pensi che potrei insegnarti? Roxxik se la caverebbe molto meglio. Lo trovi a Orgrimmar. E ora vattene!"
S["c2438761"] = "FUOCO ALLE POLVERI!"
S["c24cb1de"] = "Fa' la tua parte pe' tener pulito il Deeprun Tram!"
S["c25b60b1"] = "Infermiera."
S["c261b2c5"] = "Aiuto, aiuto! Mi reprimono!"
S["c26943fd"] = "Sei $Gcieco:cieca;, $Gragazzino:ragazzina;? Shayis è proprio qui fuori."
S["c274c207"] = "Prendi una cassa di scrigni di contenimento e un canto della manifestazione, $N. Ti serviranno per la tua missione."
S["c27685ac"] = "Aku'mai è morto! Finalmente posso lasciare questo posto maledetto."
S["c27773e0"] = "Abbiamo sentito le vostre richieste e siamo d'accordo... le intenzioni sono nobili. Purificheremo le vostre acque. Va' con la nostra benedizione, sciamano."
S["c27a879e"] = "I segreti di Elune sono molti, ma non vanno svelati a chiunque."
S["c285cf9e"] = "Non spetta a noi giudicare queste atrocità. Ivus emetterà il suo giudizio quando arriverà."
S["c2865e40"] = "A nord, nella nostra grande casa, Thunder Bluff, c'è un Istruttore di Forgiatura. Se è questo il sapere che cerchi, vai lì e chiedi indicazioni a uno dei Bluffwatchers."
S["c291052c"] = "Ogni speranza è perduta!"
S["c292fe02"] = "Noi shen'dorei abbiamo bisogno di stoffa aggiuntiva per rifornire le nostre scorte. Ogni donazione che farai sarà messa a buon uso, e sicuramente aumenterà la tua stima presso i Windshapers."
S["c2a0e7c6"] = "Che succede qui? Piznik! Lo sapevo che non dovevamo lasciarti restare!"
S["c2ae14d0"] = "I tuoi amici ti abbandoneranno."
S["c2ae190f"] = "Allora perché sei qui? Cosa dobbiamo fare se non c'è speranza?"
S["c2bfefa9"] = "Elder Bronzebeard si trova a Ironforge, la dimora ancestrale dei Bronzebeards."
S["c2c2c667"] = "Sono venuto in città per assoldare dei combattenti che li scacciassero. Ho trovato un guerriero che ha accettato di aiutarmi, ma appena usciti dalla città mi ha derubato e mi ha quasi ammazzato di botte."
S["c2c3b5d9"] = "Prima si uccide, poi si fanno domande... Arrivano!"
S["c2c54ddb"] = "Sei $Glicenziato:licenziata;! <Coff... Cork si schiarisce la gola.> Volevo dire, aiuto!"
S["c2cc4a8e"] = "Voglio vedere lo scheletro del drago nella grande biblioteca."
S["c2ccc39e"] = "Vuoi imparare l'antica arte? Fondere il ferro nero?$B$BPlacami, $R. Mostrami un sacrificio e ci penserò!"
S["c2d3f6f8"] = "Non posso, in coscienza, passare il tempo ad addestrare novizi mentre i non morti, nostri alleati, soffrono in modo così terribile. Ti prego, rivolgiti invece a Kray, laggiù; per ora ti aiuterà lui."
S["c2d944d3"] = "Ce n'è uno nella caserma, sul lato est di Razor Hill. Cerca Rawrk."
S["c2eead97"] = "Quello che vedi davanti a te è un Vilsegugio. Tra i talenti naturali di questa creatura ci sono il Blocco degli Incantesimi e altre abilità che la rendono impareggiabile contro un avversario esperto di magia."
S["c2f318c8"] = "Stai esagerando, $N."
S["c2f34484"] = "Salute, $C. Sono Field Marshal Snowfall e lo sforzo bellico, qui, lo comando io. Ci aspetta una strada in salita, $Gragazzo:ragazza;: se puoi darci una mano, fallo. E per qualsiasi domanda, chiedi pure."
S["c2f5be85"] = "Guarda questi campioni! Cosa vuol dire? Cosa vuol dire? Mi ci vorrà tempo, tempo per esaminare tutte queste informazioni. E me ne serviranno altre. Informazioni che non posso avere... dannazione! Pensa, Laris, pensa!$B$BCosa farai? Cosa?!$B$BUna soluzione ci dev'essere!"
S["c2fa93ef"] = "Muoviti, Dadanga! Forza, ragazza! Prima passiamo di qui, più saremo contenti tutti e due."
S["c2ff8874"] = "%s è preso da una furia berserker!"
S["c3016d29"] = "Non addestro chiunque! Prima dovrai svolgere un compito!"
S["c302dbdf"] = "Adesso ti faccio due conti: \"goblin\" più \"ingegneria\" fa SAPER FARE, $Gbello:bella;. Chi ti dice il contrario non sa fare le somme."
S["c3067738"] = "In realtà è semplice. Togli al lich, Ras Frostwhisper, i suoi poteri, riportalo alla forma mortale e poi uccidilo, una volta per tutte."
S["c3075a95"] = "Forse non lo sai, ma Jormund non è solo un abile sarto: è anche un ammazzagiganti! Beh, quando si è messo a gridare di averne uccisi sette in un colpo solo, deve aver sentito qualcuno di noi che si scambiava storie!$B$BDovresti fare un salto al suo negozio, sul lato nord di The Great Forge, e vedere se ti racconta com'è andata!"
S["c319669c"] = "Vendo soltanto il miglior equipaggiamento arcano, fatto qui a Stormwind da artigiani e maghi."
S["c319c0bf"] = "Quegli elementali ladri sono su per il sentiero, da questa parte. Buona fortuna, $N."
S["c31da494"] = "Niente riposo per cattivi, ma noi pensa tu ok. Tu cerca Innkeeper Norman su anello alto di Trade Quarter."
S["c32106ee"] = "Macellaio, dici? Oh, Istruttore di First Aid! È la stessa cosa. Nurse Neela la trovi appena entri nella Gallows' End Tavern, sul lato sud-est della città: quando la vedrai, capirai perché."
S["c323cb07"] = "Molto bene, mortali. Per ora godetevi la tregua. Non vedo proprio l'ora di raccontare al Signore del Vento tutto quello che è successo qui. Mi rivedrete... molto presto."
S["c3245446"] = "Quel bigotto schifoso ha finalmente avuto ciò che si meritava. Che liberazione!"
S["c32baab2"] = "The League of Arathor ha giurato di riconquistare Arathi per gli umani di Stromgarde e per l'Alleanza. La battaglia è dura, ma vale la pena combatterla."
S["c3332e37"] = "Devi essere in rapporti amichevoli con i tauren di Thunder Bluff prima che io ti insegni a cavalcare, $C."
S["c334e644"] = "In attesa di ordini dai miei superiori!"
S["c334e651"] = "In attesa di ordini dai miei superiori."
S["c3359ee0"] = "Mi dispiace davvero, $C, ma poiché il tuo spirito non ha mai conosciuto gli orrori che si nascondono tra le rovine in fiamme di Stratholme, la nostra magia non può portarti nella città."
S["c34042b3"] = "World of Warcraft e Coca-Cola (R) si sono unite per offrirti la iCoke-World of Warcraft Summer Promotion. Cerca i codici sotto i tappi delle bottiglie di Coca-Cola con il contrassegno speciale. Poi torna qui e inserisci il codice per vincere un oggetto virtuale."
S["c34e58d0"] = "Mi spiace, ma io addestro solo i ladri."
S["c354c83a"] = "Che la Madre Terra vegli su di noi; al riparo della notte come di giorno. Che questo fuoco illumini i nostri corpi e i nostri spiriti e ci ricordi i nostri honored ancestors, che sono sempre presenti e guidano il nostro cammino."
S["c35d914c"] = "Cos'hai lì, $N?$B$B<Malyfous indica i Guanti Lunghi a Piastre Compatte che spuntano dal tuo zaino.>"
S["c35f20dc"] = "Ho un sacco di ricette ottime da farti vedere, e pure a prezzi scontati!"
S["c371cab9"] = "Abbiamo quasi tutto il silithyst che ci serve! Non fermatevi adesso!"
S["c3803f37"] = "Renault..."
S["c383ccdb"] = "Grazie per avermi trovato la collana, signorina! Sei la migliore!"
S["c38e0dab"] = "Prima Kormok spezza tue ossa! Poi Kormok brucia tua anima!"
S["c3932f2c"] = "%s tende la mano verso il Capitano Beltis mentre lei cade."
S["c3b84cf3"] = "Le storie delle tue imprese si sentono in tutto il Ravenholdt Manor, Signora $N."
S["c3bba00e"] = "Vendo solo l'equipaggiamento migliore, collaudato e affidabile. E i prezzi sono fissi: se vuoi contrattare, vatti a cercare un Goblin."
S["c3be95dc"] = "Non puoi salvarlo!"
S["c3c7ea7a"] = "No! Non possiamo permettervi di evocare Hakkar!"
S["c3cbf436"] = "Gli ordini sono stati dati! In marcia, e fategli vedere di che pasta siamo fatti!"
S["c3d01ef0"] = "%s depone un uovo!"
S["c3d22a01"] = "Ci sono 428.000 gradi Kraklenheit... Come va, bollente!?"
S["c3d46044"] = "Salve di nuovo, $N. Pensavi che mi sarei dimenticata di te?$B$BSapevo che non l'avresti pensato. Sei $Gun:una; $C $Gsveglio:sveglia;, che riconosce una persona dalla memoria perfetta quando la vede."
S["c3d54cb2"] = "Sono Bolvar Fordragon, Gran Signore di Stormwind."
S["c3d552e9"] = "The Lion's Pride Inn di Goldshire non ha niente da invidiare a nessun'altra da queste parti. Fai un salto e lascia che sia Innkeeper Farley a farti sentire a casa."
S["c3e751ca"] = "Quando qualcuno farà qualcosa contro i non morti?"
S["c3e8e3e4"] = "Temo il peggio, vecchio amico. Nel Sogno combattiamo un nuovo nemico, nato da un male antico. La nobile stirpe di Ysera è caduta vittima degli antichi sussurri. Sembra che l'Incubo abbia sfondato il reame e cerchi un nuovo ospite su Azeroth."
S["c3eb6d58"] = "Cavalchiamo ai tuoi ordini!"
S["c3ec07ea"] = "Ho le budella di verme sulle scarpe."
S["c3ecd7d0"] = "Awa pawene a Chi Kashu! Halo ich!"
S["c406436f"] = "Vorrei inserire il codice segreto per ricevere la mia mascotte Zergling."
S["c4066a69"] = "Merideth, potrei avere dell'altra manna-enriched horse feed, per favore?"
S["c4077419"] = "Qui non c'è nessuna vittoria per te! Quel poco terreno che hai conquistato sarà inghiottito dall'esercito dello Scourge a tempo debito!"
S["c40a9bcd"] = "Sei perdonato..."
S["c40f3c9a"] = "Buongiorno a te, ragazza. Posso fare qualcosa per te?"
S["c4176b7d"] = "Brzzzzt!$B$B$GBenvenuto:Benvenuta; nel Matrix Punchograph 3005 barra D, terminale con livello di sicurezza delta.$B$BRed punch card rilevata. Accesso Consentito.$B$B01001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111"
S["c41e68bf"] = "Renderemo schiavi i quilboar!"
S["c420fba6"] = "Se hai la stoffa, ti mostrerò volentieri la strada."
S["c42d06b3"] = "La West Frostwolf Tower è sotto attacco! Se nessuno la ferma, l'Orda la distruggerà!"
S["c42d7e70"] = "$GUn:Una; $C... qui? Com'è possibile?"
S["c43a5cec"] = "Uno dei migliori sarti di Stormwind, Georgio Bolero, lavora da Duncan's Textiles. Il negozio lo trovi in Mage Quarter."
S["c43bca56"] = "Lui in Royal Quarter, penso. Kurden Bloodclaw è piccolo orco."
S["c43d6177"] = "Fucili, dinamite, bombe, pecore esplosive... come si fa a non amarli? Se vuoi imparare a costruire questi e tanti altri entusiasmanti attrezzi del mestiere, va' a Undercity, sotto le Ruins of Lordaeron, a sud di Brill. Scendi con gli ascensori in fondo alle rovine e, una volta $Garrivato:arrivata;, chiedi a uno degli Undercity Guardians dove si trova di preciso l'istruttore."
S["c43dcc33"] = "Vieni con me se vuoi vivere."
S["c451f2ae"] = "Altri tirapiedi del Custode!"
S["c452965f"] = "Hai superato le mie capacità: devi scegliere un maestro più esperto. Ti consiglio di parlare con Lilyssia Nightbreeze, che è qui e ha molto da insegnare."
S["c454f5ca"] = "Ho davanti un miracolo! In mille anni di prigionia non ho mai visto entrare in queste sale un solo essere VIVO — a parte quegli immondi Qiraji e silithid."
S["c45685da"] = "Buongiorno a te, Syurna. Ho bisogno di addestramento."
S["c45d1b0b"] = "I miei... I miei poteri sono diminuiti... Pagherai per questa insolenza!"
S["c45f6517"] = "Il tocco della pietra mi è negato per sempre. La gloria del ferro lavorato non la conoscerò mai più..."
S["c4639492"] = "Ho sentito le loro risate di scherno mentre il mio grifone precipitava in fiamme, $C.$B$B\"Slidore, fai schifo!\" gridavano.$B$BNessuno parla così a Slidore! Aiutami a uscire di qui, così potrò mostrare loro chi è quello che fa davvero schifo!"
S["c470bef2"] = "Oh, questa è bella, piccolo mago. E i Windshapers che il tuo agente ha ucciso sugli altopiani? Chi ne risponderà?"
S["c472d73d"] = "Un'altra bella giornata sulla nostra splendida isola."
S["c482087a"] = "Elune, ascolta le mie preghiere. Concedici la serenità! Veglia sui nostri caduti..."
S["c487daf2"] = "Il mio sogno è servire un giorno sotto il tuo comando, Signora $N. Sempre che tu mi ritenga mai $Gdegno:degna; di cose simili..."
S["c49562c3"] = "Recupera il frammento dello scettro, $N. Non si deve permettere a Nefarius di distr... distruggere il frammento."
S["c496779f"] = "Argh, mi serve aiuto qui!"
S["c49a972d"] = "Il disturbo è solo peggiorato, Silva. Se i cittadini non ne vengono a conoscenza..."
S["c49acfda"] = "Voi due avrete molti alti e bassi, ma se riuscite a tenervi forte, la corsa ne varrà la pena."
S["c49e34be"] = "Sono $Gun maestro sarto:una maestra sarta;, Omarion."
S["c4a24831"] = "Salve, $C. Sono $Gcerto:certa; di non doverti spiegare la gravità della nostra situazione qui. Dobbiamo raccogliere molte merci e, nella maggior parte dei casi, assemblarle in materiale bellico da trasportare a Cenarion Hold, in Silithus. Non è un'impresa da poco.$B$BDi recente, nel Molten Core, abbiamo scoperto una cosa chiamata singed corestone. I nostri fabbri e ingegneri dicono di poterne fare buon uso, perciò qui sono io a sovrintendere alla raccolta. Per ora ne abbiamo raccolta una parte di quelle che servono."
S["c4aa81b8"] = "Brucia nell'odio, $R."
S["c4afe61b"] = "Hai davvero un grande potere, $N. Vieni da me se cerchi altro lavoro."
S["c4b819d8"] = "Ho stabilito il contatto, $N. È Lokholar the Ice Lord. Ha giudicato degna la nostra causa, e sufficiente il nostro sacrificio terreno. Arriverà presto... preparati."
S["c4b8b982"] = "Corbett, ci sei? Harlan ha bisogno di un altro carico di capi a maglia. Puoi portarglielo?"
S["c4c85d9e"] = "$GPiccolo:Piccola; $C! Non sei all'altezza del Blackrock Clan!"
S["c4c85fcd"] = "Ah, salve. Hai l'aria di chi deve chiedermi qualcosa."
S["c4da60e6"] = "Cerca Miao'zan a sud, in Sen'jin Village."
S["c4e0eb2c"] = "Pelver"
S["c4e94902"] = "La Frostwolf Relief Hut si trova nella Frostwolf Keep, a sud delle Frostwolf Towers.$B$BAl momento nessuna delle due parti la controlla."
S["c4ec18b5"] = "Molti animali hanno perso la vita per darci questi materiali. Non prendere alla leggera il loro sacrificio, $N. Tratta il cuoio con il rispetto che merita."
S["c4ed4a5f"] = "Con la puzza che hai attirerai tutti i draghi per miglia e miglia. Dimmi cosa vuoi, e $Gsvelto:svelta;."
S["c4ef246f"] = "Alla mia età, come se non avessi niente di meglio da fare che portare secchi d'acqua."
S["c4f4b2b6"] = "Salute, $C — sono $Gun Ufficiale:un'Ufficiale; degli Encomi e agisco per conto di Darnassus. Il mio compito è aiutare gli avventurieri che hanno ricevuto degli Alliance Commendation Signets.$B$BAccetto anelli in quantità diverse, ma per te lo scambio più vantaggioso è consegnarmene dieci alla volta. Quando me li porterai, registrerò le tue gesta nei nostri archivi, e così Darnassus riconoscerà il tuo impegno e i tuoi servigi."
S["c4f4d270"] = "Dai, non piantarmi in asso proprio adesso!"
S["c5029f03"] = "Non ho tempo da perdere con quelli come te, $C."
S["c507404c"] = "I tauren sono figli e figlie della Madre Terra, e rispettiamo ogni suo figlio. Ci sono care anche le bestie che uccidiamo, perché i loro corpi ci nutrono e le loro pelli ci scaldano."
S["c50a8b88"] = "<La colonna di vento che ti turbina davanti sembra ronzare di contentezza. Chiaramente non può parlare, ma percepisci con chiarezza le sensazioni che prova. Sembra... felice di darti la benedizione dei venti.>"
S["c50f6fda"] = "Guarda quante increspature. C'è un gran movimento nell'acqua, quindi oggi dovrei prendere un sacco di pesci."
S["c51224ca"] = "Proprio come pensavo: le gemme e la collana non contano. Conta solo la fonte d'energia."
S["c51e685e"] = "%s condivide i suoi poteri con i suoi fratelli."
S["c52338fd"] = "Quante vite perdute fra i Wildhammer... famiglie intere cancellate..."
S["c5255e0c"] = "%s si ferma e comincia a liberare nell'aria l'agente neutralizzante."
S["c52653e4"] = "Ah, sì. Ho sentito tutto su quei nuovi aggeggi flangiati. Per alleggerirli hanno tolto la corazza dall'involucro. Bargh! Sciocchezze!"
S["c528ecfd"] = "Sparisci dalla mia vista, mortale. La tua sola presenza basta a spingermi alla violenza."
S["c52df67e"] = "Sono $Glegato:legata; a questo mondo maledetto per l'eternità. Che cosa desideri, mortale?"
S["c5322ce4"] = "Oh, è una cosa orribile, $Gsignore:signorina;. Un tempo la casata Barov era piena di vita... piena di splendore. Il maniero era la residenza principale dei Barov, nel cuore del loro vasto impero.$B$BCon il passare dei giorni, Lucien e io vedevamo i Barov sempre più depressi. Abbattuti. Il padrone e la signora erano spesso in preda alla paranoia e alla rabbia, e di notte li sentivamo litigare nelle loro stanze. Da quanto abbiamo capito, la loro avidità aveva 'rotto la diga', per così dire."
S["c53c75e2"] = "Rivolgiti a Hydraxis."
S["c543ef2b"] = "Mentre le tossine annidate in Maraudon si insinuavano nella mia mente, ho cominciato a perdere il contatto con la realtà. Le mie sorelle driadi temevano che lo scettro venisse usato per il male: me l'hanno sottratto in segreto, l'hanno spezzato in due e hanno nascosto le due parti nelle caverne.$B$BPresto anche loro sono cadute vittime della follia, e le parti dello scettro, rimaste senza nessuno a custodirle, sono finite nelle mani di Vyletongue in persona. Il satiro ne ha affidata una a Noxxion, un elementale malvagio, e l'altra la tiene ancora oggi."
S["c547879e"] = "Il Kirin Tor ha gentilmente accettato di ospitarci, e se vogliamo riuscire nel nostro intento avremo bisogno del suo aiuto."
S["c551a283"] = "Quello che fa per te è Kodohide Leatherworkers: lo trovi in mezzo a The Drag."
S["c55321fa"] = "Il Frostwolf Graveyard si trova a lato della strada, poco a nord del Frostwolf Village.$B$BAl momento lo controlla l'Alleanza."
S["c553df1d"] = "Allora non dobbiamo perdere altro tempo. Lo stormo cromatico è pronto?"
S["c5553662"] = "Avete saccheggiato i nostri tesori troppo a lungo. Preparatevi a una tomba d'acqua!"
S["c55a4696"] = "Sono venuto a radere al suolo le vostre basi, clan Lupi Bianchi. Ivus vi punisce per il vostro tradimento!"
S["c55ba2e5"] = "È deciso. Comando io la Might of Kalimdor. Assicurati che i tuoi soldati lo capiscano e lo accettino come un dato di fatto. Di sangue ne è già stato versato in abbondanza. Che non ne scorra tra le nostre fazioni."
S["c55d738f"] = "%s si pavoneggia con passo pesante."
S["c5675686"] = "Jubjub? Dove sei, Jubjub? Oh no! Dove te ne sei andato stavolta!"
S["c57734fa"] = "Sono salvo! Grazie, dottore!"
S["c5821419"] = "Pazienza."
S["c58cd9f3"] = "Markhor, vorrei lasciare il mio famiglio nella stalla."
S["c592fe5e"] = "In tempi difficili come questi, basta una semplice donazione di stoffa per aiutare molto chi è meno fortunato di noi. La stoffa è preziosa per fare vestiti e bende — due cose importanti per lo sforzo di guerra!$B$BSe vuoi donare pezze di stoffa agli orchi di Orgrimmar, le prenderò volentieri e farò in modo che tu riceva il giusto riconoscimento.$B$BPer l'Orda!"
S["c5969279"] = "Vermi affamati banchetteranno con la tua carne marcia."
S["c5bef186"] = "Alla sala sicura, maestà."
S["c5c9eda5"] = "Ottimo lavoro! Sei davvero $Gdegno:degna; del sapere che ti trasmetterò!"
S["c5ca2c93"] = "Qualcosa di grosso sta uscendo dall'alveare, signora. Viene dritto verso di noi."
S["c5d0dcf4"] = "Ehm... scusa, ma non ti conosco poi così bene. Voglio dire, come rivenditrice autorizzata di Mechano-strider posso vendere le mie cavalcature solo a chi gli gnomi considerano osannato. Se un giorno sarai $Griconosciuto:riconosciuta; come $Gosannato:osannata; presso Gnomeregan, sarò felice di mostrarti cosa ho da offrire."
S["c5d1005f"] = "Così impari a lasciar perdere l'erba, $R."
S["c5d2dcfb"] = "Attivalo, Valennia. Dobbiamo scoprire il più possibile su ciò che contiene."
S["c5e82e7b"] = "Allora vai da Una, ai Thunder Bluff Armorers, sull'altura centrale."
S["c5e98cb9"] = "Questa guerra non è finita, è appena cominciata! Giorno e notte, $N, uomini e donne coraggiosi combattono il nemico dentro Ahn'Qiraj. Presto la città Qiraji cadrà."
S["c5ea672a"] = "Me l'aspettavo che prima o poi Flagongut avrebbe mandato qualcuno a prendere quel fossile."
S["c5ec7007"] = "ORA, ELMOCERVO! ANDIAMO ADESSO! Prepara la tua magia!"
S["c5eda913"] = "Cosa ci fai nelle Echo Isles, $C?"
S["c6081025"] = "Accidenti! Qui la cosa è molto più grossa di quanto avessi messo in conto, te la sbrighi da solo, Slim!"
S["c60b08db"] = "Salve, gentile signore. Siediti pure e mangia qualcosa, se hai fame. Se ti sembro presa dal ricamo, non preoccuparti — ti sto ascoltando..."
S["c60bdba7"] = "Ulbrek Firehand prende molto sul serio la cura degli animali. Se vuoi che si occupi di un famiglio o due, di solito lo trovi con i cacciatori all'Hall of Arms."
S["c60f1280"] = "Io... non riesco nemmeno a immaginarlo, $N. So solo che non lo permetterò. Verrà distrutto — se non per continuare a proteggerci dalla corruzione demoniaca, almeno in memoria di Millicent Serene... Milli...$B$BÈ qui, $Gamico mio:amica mia;, è qui che spero entrerai in gioco tu."
S["c612f799"] = "Lo Stonehearth Graveyard è sotto attacco! Se nessuno la ferma, l'Orda lo conquisterà!"
S["c614e69c"] = "Tu va in anello interno di The Apothecarium. Lì è Lavinia Crowe."
S["c61547c6"] = "Osi tanto! Ora assaggia la mia ira, $R."
S["c615ff3a"] = "Portate quei pezzi giù alla nave!"
S["c61b30f8"] = "Fuggi finché puoi, mortale!"
S["c61c2528"] = "Sarà fatto."
S["c61de2e4"] = "Sono arrivati tempi bui, $C... Presto, fin troppo presto, perderemo tutto... Quando la Luce abbandonerà tutti, tranne chi cammina davvero nella Luce."
S["c6200502"] = "Questo male che ho scatenato... In quali mani si trova ora il potere che la mia dea mi aveva concesso... Da chi è guidato?"
S["c621df68"] = "Guarda la saggezza e la conoscenza della bestia, e ci vedrai $Gte stesso:te stessa;. Osserva come il gufo, impara l'astuzia dal felino dai denti a sciabola, incarna il possente spirito del lupo."
S["c62d50a1"] = "Guarda questo drago abbattuto, $R. Nessuno può mettere in dubbio la potenza dell'Orda!"
S["c63d554e"] = "ROARRRRR!!"
S["c63dbcd9"] = "Vieni un po' più vicino. Io e te abbiamo da parlare di cose importanti.$B$BE certe non vogliamo che le sentano tutti..."
S["c641f328"] = "Nelle caverne qui sotto si trovano pelli strane e meravigliose, ma se ti avventuri laggiù, nelle loro profondità, fai attenzione, $N. Ricorda che la tua pelle vale molto di più."
S["c642811e"] = "Sono $Glibero:libera;! Ora lavoriamo insieme per salvare mia sorella, Jarien!"
S["c64452a4"] = "Sei qui per essere $Gaddestrato:addestrata; a usare una nuova arma, immagino? Sbrigati, sono molto occupato!"
S["c64711d3"] = "Ora ti sto corrompendo..."
S["c64da94c"] = "Salute. I nostri pipistrelli sono addestrati e nutriti a dovere: non ne troverai di più veloci."
S["c65a8595"] = "%s afferra il coniglio e gli versa il liquido in gola, poi lo rimette nella gabbia."
S["c667353b"] = "$N! Sei $Gtornato:tornata;! E giusto in tempo!"
S["c66eccfc"] = "Preparatevi alla battaglia, mie creature."
S["c66f2cf0"] = "Un diario dalle pagine ingiallite è aperto all'ultima annotazione:$B$B\"Non so cosa succederà ora che Harold si è trasformato. Ho dovuto usare tutte le forze che avevo per trascinarlo nell'unico posto che ho trovato dove rinchiuderlo per bene, senza che possa scappare. La chiave l'ho nascosta addosso, e prego che funzioni...$B$BSpero di riuscire ad andarmene da qui, ma mi servono soldi. Credo che la nostra roba sia tutta nell'armadietto... e adesso che ci penso, la chiave non ce l'ha addosso Harold?$B$BCi dormirò su, ora sono $Gstanco morto:stanca morta;.\""
S["c6731309"] = "Il che spiegherebbe perché te ne stai seduto in una cella in fondo a una montagna, vero, nano?"
S["c686fc9e"] = "Ah, ora sono troppo impegnato per bere, $Gragazzo:ragazza;."
S["c688d46d"] = "È in questa notte che i nostri nemici ci temono di più. È in QUESTA notte che mostriamo ai nostri nemici cosa significa opporsi ai Forsaken!"
S["c68d9e31"] = "Le forze di The Lich King si stanno ammassando. È fondamentale che i nostri tempi seguano i suoi piani."
S["c68e5ad9"] = "Per ora ti ho insegnato tutto quello che potevo, $GDottor:Dottoressa; $N. Quando avrai fatto più pratica, torna da me e ti istruirò nelle arti mediche più avanzate."
S["c69dda03"] = "Hai imparato molto, ma sento che gli spiriti hanno ancora altro da insegnarti. Posso mettere il tuo piede sul sentiero, ma non posso guidare i tuoi passi. Vai a cercare Saru Steelfury a Orgrimmar: la prossima tappa del tuo viaggio comincia lì."
S["c69f3fc5"] = "Venire da me senza l'addestramento adatto: hai più fegato che cervello. Va' a parlare con qualcuno più vicino al tuo livello, come l'orchessa Kamari, che vive nel Drag of Orgrimmar."
S["c69faf87"] = "No-o-o-o!!"
S["c6a1735b"] = "Secondo Alanna Raveneye, parte del suo talento nell'incantamento viene dalla comunione con gli spiriti nell'Oracle Glade. Adesso dovresti trovarla lì."
S["c6aa2c00"] = "Aspetta... hai sentito? Qualcosa si avvicina da ovest!"
S["c6b7560c"] = "Pace e pazienza a te, $N. Resta sempre forte."
S["c6c134a6"] = "Voglio iniziare l'enigma delle statue."
S["c6c38eee"] = "Ben fatto. Affidami l'orso, così potrò lanciare l'incantesimo di guarigione."
S["c6c8747c"] = "A me, miei servi!"
S["c6c9de2f"] = "Solo uno sciocco entra in un covo di ladri senza sapere dove si trova. E quello sciocco raramente ne esce..."
S["c6cc811d"] = "Falthir, mi serve aiuto per sostituire un pezzo della mia Armatura del Predatore."
S["c6cfb8d2"] = "Ti prego, fa' in modo che la legga subito: temo che i guai con lo Scourge siano appena cominciati.$B$BTorna da me a tempo debito. Credo di essere vicino a scoprire qualcosa per cui mi farebbe comodo l'aiuto di un combattente volenteroso."
S["c6d88159"] = "Ma cosa ci mette tanto?"
S["c6da5d87"] = "Il futuro è nebuloso per voi due. Se lavorerete sulla vostra relazione, sono $Gcerto:certa; che riuscirete a trovare un po' di felicità."
S["c6e77049"] = "Ok, prepariamo questo globo..."
S["c6ea0b19"] = "I nostri preparativi procedono secondo i piani, padrone."
S["c704281c"] = "Prendilo, allora. A quanto pare Zygand è troppo occupato per farsi lo straziante viaggio fin qui e venire a prenderselo di persona."
S["c704a5c3"] = "Farò ritorno a tempo debito..."
S["c706bbbe"] = "È un lavoro discreto, lo ammetto. Ma sarei più $Gimpressionato:impressionata; se ti occupassi di una cosa per me."
S["c707abed"] = "<Raspa il terreno con uno zoccolo scheggiato.>"
S["c70ae90c"] = "Adesso muori!"
S["c7275070"] = "I simboli della tavoletta vengono trascritti con cura..."
S["c72b92dc"] = "Abbiamo un quarto del silithyst che ci serve! Continuate così!"
S["c72cfb34"] = "Ancora $Gvivo:viva;? Mi sorprendi. Guardami fuggire!"
S["c739078c"] = "Se le salopette stanno su con i bottoni automatici in alto, allora perché hanno i passanti per la cintura?"
S["c7414a3c"] = "%s viene posto sulla Flame of Uzel."
S["c741cd3c"] = "%s irrompe nell'incubatoio non appena applichi l'esca al cristallo!"
S["c74910d6"] = "La velocità di Owatanka è con te, $N."
S["c74d3f90"] = "Amakkar, dove pensi che ci manderà Warlord Goretooth? Non credo di reggere un altro giro nelle Steppe."
S["c74dfb2c"] = "Oh, santo cielo, mi hai colta di sorpresa! Sono lieta di vederti, $N, l'Azeroth Commerce Authority ha sempre bisogno di nuovi collaboratori.$B$BSe sei il tipo a cui piace fare una passeggiata nella foresta raccogliendo materiali utili o se hai le capacità per creare qualcosa da zero, beh, qui sei proprio a casa tua!$B$BFammi sapere se hai qualche domanda."
S["c75464e9"] = "Non avresti aiutato la legione di Roccianera se ti avessimo semplicemente chiesto aiuto, vero?"
S["c764d763"] = "I tuoi preparativi sono completi. Ora davanti a te e al tuo destriero del terrore restano solo il rituale per il Cerchio dell'Evocazione Superiore e il vincolo dello spirito del destriero del terrore..."
S["c769f6ea"] = "Il vostro regno del terrore finisce ora! Affrontate la vostra fine, mortali!"
S["c76b904e"] = "La West Frostwolf Tower è sotto attacco! Se nessuno la ferma, l'Alleanza la distruggerà!"
S["c76c2253"] = "Credi di avere la stoffa per distruggere The League of Arathor, $C? Lo spero. Cosa vuoi? O sei qui solo a farmi perdere tempo?"
S["c77340c2"] = "Buongiorno, $Gragazzo:ragazza;! Magari potresti darmi una mano con qualche faccenda da sbrigare."
S["c774cdaf"] = "Il vincitore è Rosso! Congratulazioni, Rosso!"
S["c77947c9"] = "Ti strapperò gli arti e li userò per prenderti a botte finché non ti arrendi!"
S["c780dc6e"] = "Solo un assaggino..."
S["c78e2ece"] = "Niente ci fermerà! Morirete!"
S["c78f20d2"] = "Presto Lokholar sorgerà... Presto... Molto, molto presto..."
S["c797bc24"] = "Ho finito. La tua armatura è pronta, $N."
S["c79db37e"] = "Lascia che ti aiuti con quelle."
S["c7a8f954"] = "La tua veste è pronta, $N."
S["c7b198e7"] = "I Maneweaver praticano i loro mestieri in casa, lungo la strada per Darnassus. Nadyia è un'ottima maestra di Conciatura: dovresti passare da lei a sentire cosa può insegnarti."
S["c7b38b0b"] = "Ehi Nagmara! Che ne dici di un boccale di Birra dei Dark Iron?"
S["c7b5fac0"] = "Va' alla Shady Rest Inn e segui le tracce. Guarda dove portano e torna a riferirmi."
S["c7b79323"] = "Ehi-ho, ehi-ho, e tutto il resto... diamoci una mossa."
S["c7b8854b"] = "Preparatevi a un'eternità di angoscia e tortura: la vendetta sarà mia..."
S["c7b9a183"] = "Vil Ewiddan Forthis gloin novas vil goibon far regen lars odes nagan gloin!"
S["c7c6ddda"] = "Commercio! Lo bramo!"
S["c7cb72c1"] = "Nagmara! È rimasto un po' di montone?"
S["c7cddb51"] = "Vuoi imparare a trasformare il minerale che trovi in armi e armature di metallo?"
S["c7d30d3f"] = "Questa era The Ashbringer, $Gsciocco:sciocca;! Lo Scourge cominciava a prendere forma intorno a noi, e la lama di Mograine si è messa a brillare... a ronzare... il giovane Mograine l'avrebbe preso come il segnale per scappare. Ci si sono gettati addosso con una fame mai vista. Eppure..."
S["c7d47ded"] = "I nostri nemici cadranno!"
S["c7d65c05"] = "Informazioni... Grazie ai nostri esploratori e ai nostri agenti, a Lordaeron il flusso delle informazioni lo controlliamo noi. I movimenti del Flagello, i suoi possedimenti: tutto sotto i nostri occhi vigili..."
S["c7df5cf6"] = "L'infestazione dei Blackrock è fitta da queste parti. Farò del mio meglio per tenere il passo, $N. Andiamo!"
S["c7e3ce4e"] = "Dai, proviamo da un'altra parte."
S["c7e43bcd"] = "Aiutatemi! $N si avvicina!"
S["c7e6ba9f"] = "Una scoperta rara, davvero.$B$B<Mathredis annuisce.>$B$BSe vuoi continuare, mi serviranno i componenti."
S["c7e85414"] = "Fandral! È giunta la tua ora! Va' a nasconderti in The Emerald Dream e prega che non ti troviamo mai!"
S["c7e9bc33"] = "Già, ho sentito dire in giro che prima o poi ti avrei visto da queste parti. Ma io non prendo chiunque: prima devo assicurarmi che tu abbia la stoffa. Sei $Gdisposto:disposta; a fare la mia piccola prova per scoprirlo?"
S["c7eb21fd"] = "Non così sicuri di voi senza The Purifier, eh?"
S["c7ef79b4"] = "Raaarrrrggghhh! Veniamo a prenderti!"
S["c7f4813a"] = "Attento a dove metti quel piede, signore. Mica abbiamo tutti la fortuna di essere alti quanto un $R."
S["c7f492f4"] = "Prendilo! Torna da me se il potere dell'Occhio dovesse vacillare."
S["c7f54846"] = "Sì, ma ti darà più soddisfazione se sei $Gbravo:brava; in erboristeria! Dovrai curare e coltivare semi speciali — non menare colpi d'ascia alla cieca o sbracciarti all'impazzata contro le ombre che passano. Con l'Evergreen Pouch che riceverai, anche il bruto più ottuso riesce a far crescere qualcosa, ma chi ha un po' di talento avrà raccolti più abbondanti."
S["c7f5f41e"] = "Ti credevo morto, Terry."
S["c7f93a16"] = "Salute, $C — sono $Gun Ufficiale:un'Ufficiale; degli Encomi e agisco per conto di Stormwind. Il mio compito è aiutare gli avventurieri che hanno ricevuto degli Alliance Commendation Signets.$B$BAccetto anelli in quantità diverse, ma per te lo scambio più vantaggioso è consegnarmene dieci alla volta. Quando me li porterai, registrerò le tue gesta nei nostri archivi, e così Stormwind riconoscerà il tuo impegno e i tuoi servigi."
S["c7fc3326"] = "Ogg lok ha golar kil kek Osh'kazil Tago!"
S["c7fe5d0c"] = "Capisco, amico mio. Troverò qualcuno che aiuti il tuo padrone. Ora torna da lui, o almeno restagli vicino."
S["c7ffca84"] = "Troppo a lungo sono rimasto inerte, prigioniero di questa nebbia... di questo malessere, a rimpiangere ciò che poteva essere... ciò che doveva essere."
S["c80320e8"] = "Saluti, $N. Come procedono le tue indagini sul demoniaco e sull'arcano? Hai scoperto qualche oscuro segreto di recente?"
S["c80bd60b"] = "Secondo Karn dobbiamo ascoltare gli spiriti della forgia e dell'acciaio, perché saranno loro a guidarci. Io, a parte un fischio nelle orecchie, non sento niente. Ecco, prendi un martello e proviamo a sentirli insieme."
S["c80e917f"] = "%s rivolge la sua attenzione verso di te."
S["c80ef4ef"] = "Dubito che sarai così $Gfortunato:fortunata; la prossima volta che incontrerai i miei fratelli."
S["c811c776"] = "Iuhuu, ci siamo! Tutti hanno raccolto tutto, e proprio in questo momento ogni cosa viene trasportata in zeppelin a Silithus. L'ultimo carico dovrebbe arrivare nel giro di pochi giorni. Quando sarà tutto là e lo scettro sarà stato assemblato, potrà cominciare la guerra contro quegli sporchi insetti. Come si dice: 'Spedite!'"
S["c81ceb4b"] = "Ah sì, la muta: non perderla. Nelle Burning Steppes ci sono alcuni della mia stirpe che fabbricano oggetti che solo la muta dello stormo nero può rinforzare."
S["c8249a3b"] = "Ti voglio bene anch'io :)."
S["c826f91b"] = "Ah! Questo sì che è divertente. Mi chiedo, piccoli elfi... quanto pensate di poter resistere? Gli eserciti di Al'Akir sono infiniti in questo luogo!"
S["c827e1bf"] = "Pare che l'esercito dello Scourge sia arrivato a Tanaris. Un gran numero di necropoli e di altre forze è stato mandato laggiù.$B$BNecropoli rimaste: $2283W"
S["c82b998d"] = "La Coldtooth Mine si trova nel territorio dell'Orda, tra le montagne a nord del Frostwolf Graveyard.$B$BÈ controllata dall'Orda."
S["c82c44c4"] = "Marion Call è su, nella sala di lettura della Gallows' End Tavern, a far compagnia a Dark Cleric Beryl; la taverna è all'estremità sud-orientale di Brill. Muoio dalla voglia di vedere chi la spunterà in quella gara di sguardi."
S["c82d51db"] = "Ora di menare!"
S["c82f4cbc"] = "Erbe, erbe, mmm, vediamo un po'. Ah sì, trovato. Ecco quanto abbiamo messo da parte finora degli stranglekelp, dei purple lotuses e delle arthas' tears che ci servono."
S["c8305304"] = "Sì, padrone!"
S["c864d918"] = "%s sembra parlare con lo scoiattolo e con la statua. Ogni tanto indica verso di te."
S["c86c8989"] = "Il mio unico desiderio è servirti, o grande, finché non morirò sotto il tuo piede!"
S["c8776c69"] = "Una leggenda vivente..."
S["c881748e"] = "Veniamo dal profondo! Non riuscirete mai a fermarci!"
S["c882e4de"] = "Ben fatto, soldati! Riposo!"
S["c8883202"] = "Raggiungimi all'accampamento di Maxwell. Lì discuteremo le prossime fasi del piano e troveremo un modo per decifrare le mie tavolette senza l'anello di decifrazione."
S["c88b9cba"] = "Oooooo, scotta scotta scotta! Se questo non ti mette le ali ai piedi, non so che altro potrebbe!"
S["c88e4db6"] = "Io. . .io. . .non. . .mi sento. . .bene. . ."
S["c88ed574"] = "Fordring non vedrà mai suo figlio."
S["c896635a"] = "La mia famiglia mi odia. Idioti spaventati, tutti quanti!"
S["c89a68c8"] = "I nostri veterani stanno scendendo in campo!"
S["c89c97f6"] = "Southshore pagherà col sangue!"
S["c89e9e98"] = "Che la conoscenza ci faccia trovare la salvezza."
S["c89f6727"] = "Era ora. Avevo fame già un'ora fa."
S["c8a2821e"] = "Le stai facendo male!"
S["c8a6b533"] = "Maxan Anvol lo troverai di sicuro alla Thunderbrew Distillery, a scolarsene qualcuno. Perché non vai a farti una pinta e vedi se ti insegna qualcosa di nuovo."
S["c8ac3bca"] = "Alcuni di noi dovranno lasciare questo piano di esistenza. Dobbiamo recarci ad Azeroth per ritrovare ciò che abbiamo perduto, e riportare qui quel sapere necessario per salvare la nostra casa."
S["c8ad85da"] = "Non potete nascondervi da noi. Preparatevi a bruciare!"
S["c8af6856"] = "Grazie! Grazie, $Gsacerdote:sacerdotessa;. Ora posso affrontare quei murloc con la Luce dalla mia parte!"
S["c8c37d14"] = "Beh, se cerchi un sarto, qui fuori non avrai molta fortuna. A Ironforge invece ce ne sono parecchi, e di talento. Perché non vai a chiedere a una guardia laggiù."
S["c8c47149"] = "Bene bene! Se vuoi imparare l'Estrazione sei nel posto giusto, ragazzina! Alla Deepmountain Mining Guild c'è Geofram Bouldertoe in persona: un istruttore migliore non potresti trovarlo."
S["c8ca9137"] = "La Darkmoon Faire resta aperta ancora per poco, poi si chiude il sipario. Non mancare, vieni a visitarla oggi stesso!"
S["c8cc29da"] = "Lo Scarlet Monastery è sulle colline a nord-est delle Tirisfal Glades."
S["c8d78e35"] = "Non esploderà niente. Il detonatore che ti ho dato era fatto apposta per non funzionare."
S["c8eb8be5"] = "Elortha no Shadra$BDea dei Ragni, Madre del Veleno, Danzatrice della Seta, Amante della Morte."
S["c9110e11"] = "$GBenvenuto:Benvenuta; nello Stomwind Keep, $Gcittadino:cittadina;."
S["c9168e3f"] = "Gloria a $N! $GDifensore:Difensora; del Popolo!"
S["c9226d3b"] = "%s esce dalla pianta, permettendole di guarire."
S["c924d911"] = "Cervelli..."
S["c92bbd01"] = "Alchimia"
S["c92c32a4"] = "Per come la vedo io, non c'è mestiere migliore del minatore. E per come la vedo io, non c'è minatore migliore di un nano!"
S["c9327f9b"] = "Aprila, e stavolta fai attenzione!"
S["c9334e90"] = "Hanno liberato l'umano, Windsor, sire. Non passerà molto prima che Onyxia venga smascherata."
S["c93847fd"] = "Saremo di nuovo insieme, amore mio..."
S["c93c77fd"] = "Attenzione! Attaccano i Kolkar!"
S["c93d4e2e"] = "Che tu sia maledetto, Halyndor! Ci hai portati alla rovina!"
S["c949c229"] = "Perché sta succedendo? In poche parole, gli spiriti del vento sono semplicemente... svaniti.$B$BI folletti insignificanti e gli elementali minori che avrai incontrato là fuori sono una pallida imitazione dei veri spiriti del vento: privi di coscienza, senza meta, ben lontani da quegli spiriti benevoli accanto ai quali abbiamo vissuto in armonia per migliaia di anni."
S["c94a0ad4"] = "Tu. Puoi prendere quello che c'è nel mio calderone. Doveva essere la seconda fase del mio piano: abiti amorosi."
S["c94ca8d5"] = "Dopo tutto quello che abbiamo passato? Beh, tanto non mi piacevi neanche!!"
S["c9502d5f"] = "Il totem è pronto. Ora si può purificare il pozzo."
S["c954948c"] = "Sì, $Gfiglio mio:figlia mia;? Cosa posso fare per te?"
S["c96068ab"] = "Timer di inizio partita disattivato."
S["c961b228"] = "Non perderti la nostra Birra Dark Iron: ho sentito dire che i nani da queste parti non ne hanno mai abbastanza."
S["c9631221"] = "Tutto qui?"
S["c9719d34"] = "Se pensi di fondare una gilda, devi passare da Jondor Steelbrow, laggiù all'Ironforge Visitor's Center. Dalle porte di Ironforge prendi verso sud-est e lo trovi."
S["c974c5e6"] = "Questa guerra ha prosciugato enormemente il nostro popolo e le nostre risorse. Persino qui su Teldrassil non possiamo sfuggire alle sue conseguenze. Perdonami se te lo chiedo, ma svolgeresti un compito per me?"
S["c97683da"] = "I cittadini segnalano attacchi di spettri in tutta la foresta. Di solito ignorerei storie di fantasmi del genere, ma non a Darkshire. Qualunque cosa fosse la famiglia Valor in vita, da morti sono diventati pericolosi come qualsiasi altro mostro di questi boschi.$B$BQualcosa ha corrotto queste anime. Dobbiamo dar loro pace."
S["c97a30a0"] = "I Blackfathom Deeps sono all'estremità settentrionale della Zoram Strand, sulla costa di Ashenvale."
S["c981f70a"] = "I pugni di un Orco sono già un'arma potente, quindi perché non aggiungerci lame o borchie di solido acciaio. Ora i pugni che uso per domare i lupi delle pianure posso usarli anche per frantumare l'armatura dei miei nemici."
S["c98647e1"] = "Ben detto! Ben detto! Ci brindo!"
S["c98d8eca"] = "Sì, sì, tutto il materiale bellico dell'Orda e dell'Alleanza viene spedito a Silithus e dovrebbe essere lì entro un giorno. Sai cosa succede dopo, $C? Ci sbrighiamo per poi aspettare. Speriamo che qualcuno stia raccogliendo i pezzi dello Scepter of the Shifting Sands, perché per aprire le porte di Ahn'Qiraj bisogna batterlo contro il gong sulla Scarab Dais."
S["c99160f0"] = "Non mi aspettavo che sapeste organizzarvi così bene, tutti quanti. L'Alleanza e l'Orda hanno finito i preparativi per la Guerra di Ahn'Qiraj: in questo momento stanno spedendo il materiale a Silithus, e dovrebbe arrivare tutto nei prossimi giorni. Poi chi rimetterà insieme lo Scepter of the Shifting Sands dovrà battere il gong sulla Scarab Dais e aprire i cancelli di Ahn'Qiraj. Allora sì che la guerra comincerà davvero!"
S["c99edb29"] = "Mettere dodici centri di concentrazione potrebbe permettere alle energie magiche di formarsi in modo più solido, dando la stabilità necessaria."
S["c9a088f3"] = "Raggiungimi giù al frutteto, devo solo mettere via il fucile."
S["c9a348de"] = "Salute e ben $Gtrovato:trovata;, $Gviaggiatore:viaggiatrice;.$B$BMi piacerebbe che il mio arrivo portasse buone notizie, ma il regno di Dalaran ha bisogno dell'aiuto dei regni dell'Alleanza."
S["c9abdadf"] = "%s si inchina profondamente davanti a te."
S["c9b15d9f"] = "$GBenvenuto:Benvenuta; in prima linea, $C. I politici potranno anche tramare e complottare fra loro, ma qui un lusso del genere non se lo possono permettere. Questo è il Bulwark, e ogni giorno combattiamo per sopravvivere.$B$BSe sei $Gvenuto:venuta; a cercare l'occasione di dimostrarti $Gun eroe:un'eroina;, ne troverai quante ne vuoi... soprattutto ora che avanziamo verso Andorhal e verso qualunque forza maligna controlli lo Scourge laggiù."
S["c9b1c41b"] = "Lo Stonehearth Bunker è sotto attacco! Se nessuno la ferma, l'Orda lo distruggerà!"
S["c9ba3190"] = "%s sembra $Gsollevato:sollevata;."
S["c9beaf66"] = "Ah, un tempo eri $Gun veterano esperto:una veterana esperta;, e Kilram può farti tornare com'eri. Lo so che ne sei capace: basta che tu me lo chieda e ti insegnerò l'arte del forgiatore d'asce."
S["c9c2159f"] = "Questi boschi mi fanno prudere le zanne..."
S["c9cc8dca"] = "%s distrugge la picca!"
S["c9d313d6"] = "I fuochi d'artificio andranno avanti tutta la notte. Dalle 6 di sera all'alba, il cielo di Booty Bay sarà in fiamme!"
S["c9d76c60"] = "Il consiglio che cerchi è quello di Gennia Runetotem. La troverai nella grande tenda sul lato est del villaggio."
S["c9d85cdc"] = "Dopo essermi schiantato qui, mentre vagavo per il cratere, mi è tornata in mente una cosa che mi avevano detto una volta... \"Sali, sali sulla montagna davanti a te\", diceva la voce nella mia testa.$B$BIo le ho dato retta, ed eccomi qui, $N!"
S["c9d90585"] = "Avelina e Isaac sono nati entrambi nella città agricola di Hillsbrad. Man mano che crescevano, il loro affetto è fiorito."
S["c9e4c47d"] = "Con un po' di questo unguento dovresti stare meglio."
S["c9ea49e4"] = "Gli Dèi Primordiali servono Hakkar. Torna indietro adesso, non hai speranze."
S["c9eb1636"] = "Sei proprio $Gun incantatore:un'incantatrice; coi fiocchi! Adesso è tempo di andare avanti: voglio che parli con Gimble Thistlefuzz, qui di sopra. È un tipo un po' strambo, ma d'ora in poi sarà lui a indirizzarti sulla strada giusta!"
S["c9ef3a80"] = "I Crystal Pylons of Un'Goro restano un mistero per tutti. I pochi che vivono da queste parti ci raccontano sopra leggende, e sul loro scopo le congetture non si contano."
S["ca139e74"] = "Ecco... Dovrebbero bastare per fare una collana. Comunque è meglio che torni a casa."
S["ca2603a2"] = "Grurk stupido? Tu prova aprire scatola! Forse tu $Gfurbo:furba; come gnomo???"
S["ca28cd23"] = "Ecco fatto!"
S["ca334434"] = "Ma certo, $N. Eccotene un altro."
S["ca346044"] = "Si comincia! $N, ti presento i miei pugni. Pugni, salutate $N."
S["ca56a1b2"] = "Salve, amici miei. È bello rivedervi. Vedo che tenete ancora libere le nostre frontiere. Antonio apprezza il vostro duro lavoro."
S["ca599ace"] = "Quando l'Orda fu sconfitta, gli uomini tornarono qui e iniziarono a ricostruire la città un tempo grandiosa, a testimonianza della nostra sopravvivenza."
S["ca5edfbb"] = "È tuo marito, donna. Come faccio a sapere dov'è?"
S["ca62c53b"] = "La Stormpike Aid Station si trova a Dun Baldar, proprio fuori dalla caserma di Dun Baldar.$B$BAl momento è controllata dall'Orda."
S["ca64bef1"] = "Ti piace il mio animaletto?"
S["ca679617"] = "Sono un funzionario della città e mi occupo del censimento di Undercity. Da quando ci siamo liberati dallo Scourge cerchiamo di tenere un conto preciso della nostra popolazione. Con metodi arcani e una mente affinata dalla disciplina, sono in grado di consultare questi registri. Se hai affari da sbrigare con me, fa' pure. Se li hai, comunque, dovresti saperlo."
S["ca6d0962"] = "Dovevano essere proprio dei ragni..."
S["ca779962"] = "Allora ascolta bene, $C.$B$BSenti il potere che irradio? Il tuo morale non si gonfia? Sì, e lo stesso vale per l'altra parte. Scompaginare le loro difese e sfoltire le loro truppe non sarà facile, ma va fatto! La vittoria sarà nostra!"
S["ca7910b8"] = "Se hai abbastanza oro per pagare la lezione, posso insegnarti i segreti del Cavalcare Cavalli!"
S["ca7afb32"] = "Salve, giovane $C. Sei qui per portarmi una partita di peacebloom? Li stiamo raccogliendo per preparare pozioni ed elisir per lo sforzo bellico di Ahn'Qiraj. Per quanto sia tragico essere costretti a questa guerra, le conseguenze saranno ancora più terribili se non ci prepariamo come si deve.$B$BL'Orda mi ha incaricato di raccogliere una certa quantità di peacebloom, e finora ne abbiamo messi insieme solo una parte. Se ne sei in grado, raccogline quanti più puoi e riportali a me, qui."
S["ca83569b"] = "Sulla tavoletta i segni riportano antichi schemi e terribili parole di potere, quelli usati per creare il Gurubashi Mojo Madness..."
S["ca855e67"] = "Hai già parlato con uno dei miei accoliti nella torre, $N? Finché non avrai svolto uno dei loro compiti, il tuo globo non possiamo completarlo. Se sei $Gpronto:pronta;, va' a parlare con loro adesso."
S["ca8b7482"] = "Intrusi! Il Martello si abbatterà su di voi."
S["ca974995"] = "%s è quasi al pieno delle forze!"
S["caa9981e"] = "Alla fine abbiamo scoperto da dove venivano quelle urla. Il Macellaio ci ha fatto provare un dolore che non immaginavamo potesse esistere, e ci ha usato per innumerevoli esperimenti, cercando di creare una pestilenza.$B$BI giorni sono diventati settimane. Saremmo $Gmorti:morte; già il primo giorno, se quel bastardo crudele non ci avesse tenuto in vita con la magia."
S["caaa8433"] = "Appena arrivata... un'altra partita di Darkmoon Special Reserve. Vieni a prenderti la tua prima che finisca!"
S["caacaecb"] = "Komak! Giuro che avrò i soldi! Dammi solo un altro po' di tempo!"
S["cab3f25c"] = "$GBenvenuto:Benvenuta; alla Bank of Darnassus. Da noi trovi conti e cassette di sicurezza per gli oggetti di valore. Hai già un conto, $Gsignore:signora;?"
S["cab6928a"] = "Possiamo sconfiggere queste creature immonde!"
S["cab744f0"] = "Devi ascoltare la mia storia prima di proseguire, $N. Ti sarà molto utile in futuro."
S["cabad603"] = "C'è chi pensa che la palude non valga niente... non vale niente, dicono."
S["cabe2d30"] = "Grazie, $N. Venderò quelle bevande in men che non si dica!"
S["cabfe690"] = "\"Malanni Magici\", no. \"Matrici Magiche\", no. Ahh, ecco qua, \"Misteri Magici\"."
S["cac3a17b"] = "Devi capire che aver potuto catalogare 10.000 anni di esistenza mi ha dato un modo piuttosto particolare di vedere la vita. Le tue pene e i tuoi affanni di oggi non significano nulla."
S["cac63bea"] = "Muori, $N. Elune non ti permetterà più di fare del male alle sue creature!"
S["cac6b249"] = "Se cerchi altro lavoro, sono sicura che in città c'è qualcun altro che ha bisogno di una mano per questo o per quello. Chiedi in giro, qualcosa troverai di certo."
S["cac95527"] = "Anime così erranti e sventurate..."
S["cacb01e6"] = "Non riesco a crederci... Stavo facendo una normale missione di ricognizione sopra la zona demilitarizzata centrale quando è scoppiato l'inferno. Ho visto l'Horde Wing Commander, Mulverick, abbattere sia Ichman che Slidore! La rabbia ha preso il sopravvento, ho lasciato il mio gregario e ho abbattuto quel bastardo di Mulverick. Purtroppo, prima di schiantarsi ha colpito il mio grifone, costringendo a terra anche me. Alla fine sono $Gstato catturato:stata catturata; da questi selvaggi.$B$BDevo tornare alla base! Aiuto!"
S["cad133fa"] = "Addio. Ci parleremo ancora, ne sono sicuro."
S["cad1c848"] = "%s annuisce con aria d'intesa."
S["cad89bc2"] = "Lo Stormpike Graveyard è scavato nelle montagne, oltre il ponte a est di Dun Baldar.$B$BAttualmente è controllato dall'Alleanza."
S["cadb70c6"] = "\"Ottimo lavoro a raccogliere risorse per la guerra\", mi hanno detto. \"Ti spetta una promozione\", mi hanno detto. Quello che volevano dire davvero era: \"Sei di stanza fuori da un alveare di insetti a Silithus con un branco di nani sudati, Carnes!\"$B$BGrazie per la promozione, Capitano!"
S["cade86ed"] = "Ehi, tu! Sì, proprio tu! Hai l'aria $Gassetato:assetata;. Vieni qui, ho proprio quello che ti serve!"
S["cae09bff"] = "Seguimi, 베라더믹스. Ti porterò al nascondiglio dei Defias. Ma faresti meglio a proteggermi, o sono un uomo morto."
S["cae4916a"] = "Tu fare perfetto cappellino, $R!"
S["cae7c48c"] = "Sì, sì, lo so che a Dadanga il fumo non piace. Però, a sentire l'odore, pare che a Dadanga non piaccia nemmeno lavarsi."
S["caef0f8a"] = "Uccisi gli Imperatori, la protezione magica che impedisce di teletrasportarsi nel tempio è molto più debole. Se vuoi, posso trasferirti nel covo degli Imperatori."
S["caf63877"] = "Ma, Veggente del Cielo, questo è..."
S["caf99afa"] = "$GBenvenuto:Benvenuta; al Crossroads, $C. Mi chiamo Thork — in nome del Capoguerra, guido le difese di questo posto.$B$BTi prego, fai come se fossi a casa tua: finché ti fai gli affari tuoi, nessuno dovrebbe avere niente da ridire se ti prendi un po' di spazio.$B$BQui sono tanti i pericoli che minacciano la nostra sicurezza. Se conosci già la zona, parla con gli altri: forse hanno qualche compito per te."
S["cafcca20"] = "Salve, $N. Che la saggezza di Elune guidi la tua mano e il tuo cuore. Come posso aiutarti oggi?"
S["cb05fbfa"] = "No, il fossile non l'ho lasciato qui dietro!"
S["cb0bf6ab"] = "Mm, stavolta ti sono capitate delle ossa niente male, Pozzik."
S["cb0c87e0"] = "Io sono Jin'rokh the Breaker, emissario di Mugamba: Pugno di Rastakhan!$B$BGuerrieri e pagani trattano con me."
S["cb12a2e4"] = "%s assorbe l'energia della benedizione della saggezza e la rilancia sotto forma di un impulso antimagia."
S["cb13f9e3"] = "Il miglior conservante per la carne che l'uomo e lo Scourge conoscano — il liquido per imbalsamare di Frostwhisper. Un avventuriero potrebbe trovarlo in un posto solo, e verrebbe da pensare che il lich da cui il liquido prende il nome non veda di buon occhio chi ci mette piede.$B$BMa... se il liquido vuoi trovare, la Scholomance devi infestare..."
S["cb2fc399"] = "Ben fatto, Orda! Abbiamo abbastanza Lupi del Gelo nelle nostre stalle per dare una cavalcatura a tutti i nostri cavalieri di lupi!"
S["cb335c1b"] = "Gli spiriti sono inquieti!"
S["cb3c368d"] = "Un altro $Gsciocco:sciocca; cade per mano della Defias Brotherhood."
S["cb3cef0d"] = "Non avrei mai creduto di vedere $Gun paladino:una paladina; fare qualcosa che non fosse cercare di distruggermi."
S["cb4d9c51"] = "%s comincia ad allontanarsi."
S["cb4f80e8"] = "Marlgen... Uno dei carcerieri. La chiave delle mie catene ce l'ha lui."
S["cb5ecdfe"] = "%s batte le mani emozionata."
S["cb620b68"] = "Ohè, $N! Non è un bello spettacolo, eh?$B$BL'Horizon Scout è in fondo al mare, la mia ciurma allo sbando, e carico e passeggeri sparpagliati come detriti: sembra uno dei canali di Stormwind dopo una festa.$B$BE i guai non finiscono qui..."
S["cb621c00"] = "Non sembra proprio una prova. Vediamo come ve la cavate con la seconda. Lysta, porta qui i servitori di The Lich King."
S["cb654072"] = "Ah, eccoci qui! Bene, mettiamoci al lavoro, che dici...?"
S["cb6c6b89"] = "Studio gli elementi del nostro mondo, quelli noti e quelli ignoti."
S["cb6da845"] = "Och, fu un giorno triste quando mi resi conto della mia ossessione. Mi svegliai e mi ritrovai a conciare pelli prima ancora del mio primo boccale di birra. Neanche un dopo sbornia come si deve! Lo capii allora — eh sì, lo capii! — come sarebbe andata a finire."
S["cb6f8a3d"] = "Muori, inutile $N!"
S["cb71e103"] = "Vieni con me. Ti concederò un accesso temporaneo."
S["cb76abd6"] = "Per la gloria di Ironforge!"
S["cb7a8c52"] = "La renna porta al collo una targhetta con il logo delle Smokywood Pastures e un nome — \"Metzen\".$B$BMetzen ti fissa con occhi tristi e sconsolati. Sembra quasi che una forza invisibile tenga la renna inchiodata sul posto."
S["cb8367c1"] = "In quanto membri dell'Orda, dobbiamo contribuire alla nostra comunità perché continui a prosperare. Per questo sono $Gcerto:certa; che ci aiuterai volentieri, occupandoti di un piccolo compito che ho per te."
S["cb84e659"] = "Quale razza di feccia osa entrare nelle mie stanze!?"
S["cb85a27d"] = "Ti stavo aspet...$B$B<Rimblat tossisce.>$B$BScusami, è una vecchia abitudine. Sono Rimblat of the Earthen Ring."
S["cb878266"] = "<High Inquisitor Fairbanks annuisce.>$B$BSì, il Mograine minore, quello che chiamano Scarlet Commander, per via — almeno così sospetto — delle manovre del Gran Crociato. Ha portato suo padre nell'imboscata come un agnello al macello."
S["cb9321a1"] = "Lascia che ti vada a prendere un set di attrezzi, $N."
S["cb973ecb"] = "... Un messaggio da Banehollow? E cosa dice? Ha bisogno del suo grande consigliere e servitore, Ulathek? Vuole che vada da lui?"
S["cb9b7472"] = "Urlate il vostro ultimo respiro!"
S["cb9fec27"] = "Vuoi imparare ad accendere un fuoco da campo? Allora faresti meglio a parlare con Malygen nella Cenarion Enclave, prima di dare fuoco a Teldrassil stesso."
S["cbac23dd"] = "$N ha difeso la fattoria meridionale!"
S["cbacf6ef"] = "Zug zug, $Gamico mio:amica mia;! Sono Kelm Hargunth, il fornitore principale dei Warsong Outriders. Man mano che la tua reputazione presso gli Outriders crescerà, ti metterò a disposizione una bella scelta di merci da usare dentro Warsong Gulch. E se hai bisogno di riparare l'equipaggiamento, posso occuparmene io."
S["cbae67e9"] = "Gli elementi ci parlano, $C. Ci affidano conoscenze da imparare e segreti da custodire."
S["cbaffd94"] = "Mi interessa l'addestramento in alchimia."
S["cbb519da"] = "Torna qui, Fluffy!"
S["cbb76959"] = "Aspettate! Sembra che la nostra vedetta abbia avvistato qualcosa."
S["cbb889a0"] = "Siamo tornati e meglio che mai! È la Darkmoon Faire, $Gamico:amica;, ed è il tuo giorno fortunato! Senza badare a spese, abbiamo raccolto meraviglie e leccornie da tutto il mondo per la tua gioia. Che tu sia giovane o vecchio, ricco o povero, la Darkmoon Faire ha di tutto! Non dimenticare di consegnare i tuoi Biglietti Premio della Darkmoon Faire a Gelvas Grimegate e di scegliere tra diversi premi esotici e meravigliosi!"
S["cbbbdc30"] = "Fategli vedere di che pasta siete fatti! All'attacco!"
S["cbbf082b"] = "The Argent Dawn non respingerà nessuno che sia pronto a sacrificarsi per la nostra causa."
S["cbc507d7"] = "Frustrato perché i maghi di Dalaran non facevano progressi contro i non morti durante la Third War, l'Archmage Arugal decise di evocare da un'altra dimensione i worgen, per rinforzare le file sempre più sottili della sua fazione. Gli uomini lupo fecero strage dello Scourge, poi si rivoltarono subito contro i maghi e assediarono la rocca del nobile Baron Silverlaine. Ben presto il forte cadde nell'ombra e nella rovina. Impazzito dal senso di colpa, Arugal adottò i worgen come figli e si ritirò in quello che venne ribattezzato 'Forte di Zannaombra'."
S["cbcfa1d5"] = "Grazie mille, $N. Queste corna mi faranno fare una fortuna!"
S["cbe9b9a5"] = "Renataki, of the Thousand Blades.$B$BIl dolore è la sua linfa vitale. La paura, la sua alleata. Possa egli tornare un giorno, e portare con sé un gioioso spargimento di sangue.$B$BOra Renataki dimora lontano da qui. Un giorno, potrebbe tornare..."
S["cbea3ed9"] = "Armature come quelle che fai tu fermerebbero anche l'ascia più affilata. Sono colpito, $N, e non succede spesso. Cerca un'orchessa di nome Shayis Steelfury: fa le armature migliori che si trovino fuori da quella maledetta roccaforte dei nani."
S["cbed005d"] = "TIMMY!"
S["cbf868c5"] = "Rimpianto. Ormai non mi resta altro. Una sola decisione sbagliata, e ne sono venute diverse conseguenze orribili. Se solo avessi aspettato quegli ordini. Magari parlavano degli orrori che ci aspettavano in quelle terre maledette! O forse dovevano mandarci a un altro incarico? Alla fine, è stata colpa mia. È stata tutta colpa mia."
S["cbfd27c4"] = "Eh?! Accidenti, è ora di pranzo! Ho dormito troppo!"
S["cc033a1b"] = "I nani non si ubriacano, $Gsignore:signora;. Sono solo un po' $Gimpacciato:impacciata;.$B$BComunque, Windsor? Credo che stia da qualche parte nei Blackrock Depths. È la città dei Dark Iron, per voi genti inistruttite."
S["cc059bb6"] = "Non penserai davvero di passarla liscia con questa incursione. Verranno a prendermi e pagherai per la tua insolenza."
S["cc07b92c"] = "Da Rut'theran Village, ai piedi di Teldrassil, parte un Rut'theran Ferry per Auberdine. Per arrivare a Rut'theran in sicurezza puoi prendere il portale di Darnassus."
S["cc10f211"] = "Noh deh Caang skam yu ju duti."
S["cc123f9c"] = "Mi ha trovato Mathias, nelle Barrens: la Venture Co. mi aveva lasciato lì per morto. Senza di lui sarei finito in pasto ai predatori."
S["cc1cb8ae"] = "Ho proprio l'incantesimo giusto per aprire questa porta. Peccato che le porte delle celle non fossero chiuse in modo così approssimativo."
S["cc201a4a"] = "Alle armi, marmaglia! Abbiamo compagnia!"
S["cc21428d"] = "I ribelli di Lordaeron sono pochi e deboli, e non conoscono la gioia di servire il nostro Re dei Lich."
S["cc22e540"] = "%s ruggisce, in cima a Blackrock Spire..."
S["cc28180e"] = "A un occhio inesperto cucinare su Zephras può sembrare difficile, ma a me piace preparare ogni piatto. Alla nostra casa, che si fa sempre più piccola, mancano molti degli ingredienti tradizionali kaldorei, eppure è stato divertente inventare nuove varianti delle ricette dei nostri antenati.$B$BOvunque ti portino i venti, spero che queste ricette ti ricordino casa."
S["cc297f09"] = "Non c'è scampo, nemmeno nella morte."
S["cc2c8057"] = "Ehi! Tu non dovresti essere qui! Forza, ragazzi!"
S["cc3032d2"] = "Che cosa succede a tutti? Ho... freddo..."
S["cc31ebfd"] = "Pyall Silentstride lo trovi nella grande tenda, nell'angolo nord-ovest del villaggio. Può insegnarti quello che tanto desideri."
S["cc460005"] = "Ahah! Perfetto!"
S["cc4fedb8"] = "Per la grazia di Elune, ho il piacere di offrirti il destriero migliore che si possa trovare in tutta Teldrassil, e forse nel mondo intero: il nightsaber. Sono anni che il Sentinel Army si affida al valore di questi compagni.$B$BPrenditi il tempo che ti serve, $Gamico:amica;, ed esaminali uno a uno finché non sarai $Gsoddisfatto:soddisfatta;. Sono certa che non resterai $Gdeluso:delusa;."
S["cc5dca85"] = "Questi frammenti mi mettono i brividi. Ehi, Greeby, hai trovato altri granelli?"
S["cc5f74db"] = "Vi congelerò il sangue nelle vene!"
S["cc6d9a86"] = "Soldato, mostra un po' di pietà al Tenente Reethe."
S["cc6f2204"] = "Per chi ha la volontà di usarla, la conoscenza è insieme strumento e arma."
S["cc7fb5d1"] = "Se non fossi bloccata qui un giorno dopo l'altro, avrei raggiunto la maestria che serve per addestrare quelli come te! Purtroppo non è così. Va' a parlare con Hgarth al Sun Rock Retreat, nelle Stonetalon Mountains."
S["cc810dba"] = "Kagoro, richiedo la tua presenza!"
S["cc8330d3"] = "Pesce tanto buono. Tu venire imparare pesce? Mangiare pesce? Mmmmm..."
S["cc985a3d"] = "Ora te le do di santa ragione, $N!"
S["cc9ac5d1"] = "Quando avrai attirato la sua attenzione — e, se ti vede vicino alla torre, puoi stare $Gcerto:certa; che ne avrai fin troppa — mettiti di fronte a lui ed esegui il /Salute Infranto. Ti faccio vedere...."
S["cc9e2242"] = "Qui alla loggia dei Farstrider l'abilità nella caccia conta più di ogni altra cosa. Vuoi la mia approvazione? Te la dovrai guadagnare.$B$BMi sembri all'altezza della sfida, $Gragazzo:ragazza;!"
S["cc9fa282"] = "La Rocca può attraversarla senza timore di essere attaccato solo chi ha dimostrato di non essere ostile ai Timbermaw. E tu, $Gstraniero:straniera;, ti sei $Gdato:data; da fare per guadagnarti la nostra fiducia?"
S["ccb4a039"] = "Hai la voce rauca a furia di urlare, eh? Va' a cercare l'Orgrimmar Auction House, nella Valley of Strength."
S["ccb73e0f"] = "Sollevate i vostri spiriti! Stringetevi attorno al vostro campione, godete della sua gloria! Esultate al grido di battaglia dell'uccisore di draghi!"
S["ccb86a9b"] = "L'Horde Flag è stata presa da $N!"
S["ccba92b2"] = "Via, creature immonde! Tornate nel vuoto da cui vi ha plasmato il vostro padrone!"
S["ccbee791"] = "Oh, cielo, dov'è il \"Codex of Defense?\" Lydros sarà di certo molto scontento."
S["ccbfb9e5"] = "Voi marinai d'acqua dolce siete più duri di quanto pensassi! Dovrò improvvisare!"
S["ccc9b451"] = "...non indugiate. Radunate le nostre armate perché marcino subito. I piloni sono la chiave e...le protezioni...cadranno. Questo è..."
S["ccd778f0"] = "Odes bornevalesh. Bur lo waldir vil uden lars me skilde lo barad. O ador ruftos vil algos cynegold ko lon dana O ealdor."
S["cce437a4"] = "Difensori di Darrowshire! A raccolta! Dobbiamo vincere!"
S["cceb7c21"] = "È vero, giovane $R, noi e l'Alleanza abbiamo raccolto e preparato tutto ciò che ci servirà per l'imminente conflitto ad Ahn'Qiraj. Proprio ora queste cose vengono inviate a Cenarion Hold, e dovrebbero arrivare tutte entro pochi giorni. Quando tutto sarà pronto, qualcuno dovrà suonare il gong sulla Scarab Dais per aprire i cancelli e dare inizio alla guerra."
S["ccf0e05b"] = "Non c'è scampo!"
S["ccf352ef"] = "%s legge il testo antico che $N gli ha portato..."
S["ccfdec10"] = "Una luce brillante compare dall'altra parte della sala, poi scompare. Poi noti un altro raggio... e poi un altro ancora.$B$BSembra che ti stiano mostrando uno schema."
S["cd0b5672"] = "I miei complimenti al cuoco!"
S["cd152f87"] = "In effetti, alla Silverwing Hold serve il tuo aiuto. Parla con Elfarran, nella sala delle udienze di Stormwind Keep."
S["cd189bbc"] = "Trok, hai fame? Sto preparando qualcosa da mangiare per noi!"
S["cd22f218"] = "Saluti, $N. Sono Doctor Gregory Victor, chirurgo traumatologo capo della Traumatologia dell'Orda."
S["cd238260"] = "Abbiamo quasi tutto il silithyst che ci serve! Per l'Orda!"
S["cd2d2a9d"] = "E ora... l'ultimo passo!"
S["cd31b049"] = "Ora sono $Gcorrotto:corrotta;."
S["cd37290b"] = "I tuoi attacchi sono deboli! Va' ad allenarti su qualche coniglio e torna quando sarai più forte."
S["cd3b846e"] = "Pattugliate la prima linea, soldati!"
S["cd3e8694"] = "Spero che funzioni!"
S["cd3fa3a8"] = "Concedimi la saggezza dei Winterax!"
S["cd4683f9"] = "Una cassetta della posta? Devi spedire una lettera, o forse te n'è arrivata una? Spero che sia qualcosa di bello! C'è una cassetta della posta proprio fuori dalla Banca, nel centro di Darnassus."
S["cd47b0fc"] = "Noi Timbermaw possiamo lasciarti attraversare la rocca senza pericolo, ma devi dimostrarti $Gdegno:degna; del nostro aiuto."
S["cd4a7db1"] = "Non sei $Gun druido:una druida;!"
S["cd4f21ec"] = "Vuoi imparare a cucinare? Ho qualche trucco e qualche consiglio da passarti! Ah ah! Mettiti un grembiule e cominciamo!"
S["cd520cdc"] = "Vieni a parlare con me se sei $Gun fornitore:una fornitrice; dell'insolito, o se hai delle Carte della Darkmoon Faire."
S["cd5c3aa2"] = "Ti stai godendo la festa, $C?$B$BIl Custode della Fiamma si prende cura dei fuochi del presente; io invece sono più che altro uno storico, e custodisco il ricordo delle feste passate. Naturalmente tengo nota anche dei festeggiamenti di quest'anno: finora sta andando tutto bene, non trovi?$B$BSai, $N, in tutti i fuochi della festa che ardono per l'intera ricorrenza c'è un potere. Noi badiamo al nostro, ma sono certo che nel cuore delle città dei nostri nemici bruciano fiamme sacre..."
S["cd5dcc6a"] = "Quassù ci si può annoiare, sai. Dare fastidio a quel disgraziato ingessato di Halaan va bene, ma fino a un certo punto: poi stanca anche quello."
S["cd688b6c"] = "$GBenvenuto:Benvenuta; a Farstrider Lodge, $N!"
S["cd6b1c52"] = "%s armeggia con la serratura arrugginita della porta del cortile."
S["cd6de28a"] = "Pesca"
S["cd70cd2c"] = "Ti insegnerò ciò che posso, e ogni lezione è un dono della Dea in persona. Usa con saggezza i suoi doni e non vacillerai."
S["cd73c07d"] = "Ho vestito dei re. Con l'addestramento giusto, potrai farlo anche tu."
S["cd7b7719"] = "Se vuoi cacciare i naga, ti servirà tutto l'aiuto possibile. Giù nel profondo ci sono delle fessure che gorgogliano e fanno abbastanza bolle d'aria da farti respirare sott'acqua. Per usarle, avvicinati a nuoto."
S["cd8402cd"] = "Spero di riuscire a mandare qualcuno di valido ad aiutare Ashenvale e le Sentinelle."
S["cd89a991"] = "Abbi cura di te, e porta i nostri saluti alla tua famiglia."
S["cd9514d2"] = "Non capisco perché tu voglia lasciare queste coste assolate e queste acque azzurre e cristalline: quaggiù sembra il paradiso. Ma non dirlo a mio fratello Zapetta, che è già abbastanza amareggiato di starsene bloccato lassù a Tirisfal tutto il giorno. Questo Zeppelin va a Orgrimmar, quindi non dovresti rischiare di sentirlo piagnucolare. Ma se passi da Tirisfal a breve, dammi retta: non dargli corda."
S["cd9fb9a7"] = "Hai fatto una scoperta straordinaria. Mi piacerebbe tanto poter vedere tutti gli esperimenti falliti."
S["cda57606"] = "Avrai sentito dire che Dalaran è colpita da un'epidemia magica, e che i nostri maghi sono tutti troppo occupati a mantenere le protezioni della città per riuscire a contenerla.$B$BPer proteggere la mia città farei qualunque cosa, $R. Persino trattare con quelli come te."
S["cdae9bd1"] = "%s segue felice $N come il suo nuovo germoglio."
S["cdb50ec9"] = "Non so, Jill. Se Klaven scende mentre battiamo la fiacca, potremmo finire come una di quelle cose!"
S["cdc31d40"] = "Mph! Non ho nemmeno colpito quel dannato bersaglio! Quel nano dalla testa dura probabilmente usava di nuovo il fucile come una mazza."
S["cdc621b6"] = "Dove vorresti volare?"
S["cdc6c230"] = "TU SEI IL PERDE!"
S["cdc800a7"] = "Certo, ci mette di più a ricaricare, ma questo gioiellino ti apre un buco grande come il mio pugno in qualsiasi armatura."
S["cdd22e3d"] = "$GUn seguace:Una seguace; dell'arcano, eh? Hmph! Molto bene, allora... li trovi intorno alle Pools of Vision, sotto la Spirit Rise."
S["cdd38810"] = "Dopo gli ultimi attacchi intorno al Lake Al'Ameth, i pescatori si sono trasferiti tutti a Darnassus. È lì che dovresti cercare qualcuno che ti addestri."
S["cddb3e1e"] = "Anche se me ne vado in pace, avete la mia eterna gratitudine. Grazie per avermi liberato dalla maledizione della mia follia e della mia avidità."
S["cddbaf59"] = "Che questo non turbi il tuo cuore, amato mio. Mi hai liberata dalla schiavitù, e per questo ti amo ancora di più."
S["cde04f66"] = "%s raccoglie l'erba da terra."
S["cde06966"] = "Ah, eccone uno!"
S["cde6fa7f"] = "%s implora che qualcuno ponga fine alle sue sofferenze."
S["cdee096a"] = "Allora, ora che sono il re... cos'hai per me?!"
S["cdf3803c"] = "Cosa cerchi?"
S["cdf6722e"] = "Sta... sta funzionando!"
S["cdf8cc63"] = "Ti ringrazio, $N. Hai preso a cuore la mia supplica e hai dato pace allo spirito della mia sposa perduta, e per questo non potrò mai ripagarti abbastanza.$B$BNon posso dire che smetterò mai di odiare i quilboar, ma per ora il mio odio si è placato.$B$BAdesso devo cominciare a ricostruirmi una vita."
S["cdfbf351"] = "<Quando ti avvicini, questo raptor si gira a guardarti. Sembra più giovane degli altri due: a differenza dei compagni, non ha cicatrici né scaglie graffiate. Sta un po' più dritto, forse per sembrare più temibile.$B$BDondola avanti e indietro: si vede che trabocca di energia ed è pronto a essere lasciato libero nel mondo. L'idea di avere un compagno dallo spirito avventuroso sembra entusiasmarlo.$B$BIl tuo spirito avventuroso sembra aver fatto colpo su questo raptor, che ti accetterà sia come $Gamico:amica; sia come $Gcavaliere:cavallerizza;.>"
S["ce0226c2"] = "%s si spacca in due!"
S["ce0699eb"] = "%s inizia a eseguire il rituale del risveglio su Naralex."
S["ce0c12ba"] = "Se hai abbastanza oro per pagare la lezione, posso insegnarti i segreti di Cavalcare Kodo!"
S["ce11b6fa"] = "Bene, mettiamoci in marcia!"
S["ce15757b"] = "Porterò i miei segreti con me nella tomba!"
S["ce17e6f6"] = "%s comincia a lanciare un incantesimo sul Grimclaw."
S["ce19679a"] = "Molti sono i sentieri della Madre Terra. Che i tuoi antenati veglino su di te, $C."
S["ce19e22f"] = "Rischi di distruggerci tutti, $R! Devi essere $Geliminato:eliminata;!"
S["ce224871"] = "Ho creato il totem. Tu, $N, devi purificare il pozzo."
S["ce240fbc"] = "Cerchi di far uscire il Generale della legione Frostwolf dalla sua fortezza? ASSURDO!"
S["ce28e7b0"] = "Ricordati di comprare rinfreschi e souvenir!"
S["ce2bb0a3"] = "Su questa tavola di legno sono appesi avvisi di taglia fatti alla buona."
S["ce30887d"] = "Credo che tu sia più che $Gqualificato:qualificata; per questo piccolo incarico... vediamo se ho ragione!"
S["ce337964"] = "Date col cuore e con la borsa! Date per i bambini di Stormwind rimasti senza genitori."
S["ce34e8e9"] = "Ah, molto gentile, Corbett. Li mettiamo subito sugli scaffali."
S["ce45d350"] = "Ti insegno io ad abbattere i tuoi nemici come alberelli nella foresta."
S["ce4f0198"] = "A te e ai tuoi, auguri di buoni risparmi!"
S["ce517d5f"] = "Non mi impedirai di fuggire da qui, $R!"
S["ce524816"] = "Ah, Private Hendel. Un piacere conoscere uno degli uomini che tradirebbero il proprio regno per orgoglio."
S["ce575916"] = "La tossina è pronta, $N."
S["ce708e16"] = "Senti il richiamo della caccia, $C? Devi ascoltare con attenzione, ma quel richiamo viene dal profondo di te. Dal profondo di tutti noi."
S["ce71af45"] = "Ecco, $N.  Prendi un Chest of Containment Coffers e un Cantation of Manifestation.  Ti serviranno per la missione."
S["ce729498"] = "Buon viaggio fino a Ratchet, $N!"
S["ce79691f"] = "Nuove dai venti. Cosa posso fare per te?"
S["ce82cc68"] = "Se vogliamo generare il nostro stormo di draghi, dobbiamo concentrarci!"
S["ce8baaa5"] = "Thok tago kek Ruk'ka'ha! Kil ogg gesh'nuka $N!"
S["ce8d38c8"] = "Centinaia di anni fa, là dove oggi si stendono le Burning Steppes in rovina, la grande città di Thaurissan sorgeva fiera in mezzo a una distesa rigogliosa.$B$BThaurissan era la patria della nazione dei nani Dark Iron, e a quel tempo si trovava nel pieno di una guerra civile che coinvolgeva tutti i nani.$B$BVedi, un tempo quella parte del mondo apparteneva alle Redridge Mountains — finché un giorno Thaurissan non fu inghiottita da un'esplosione gigantesca. La città giaceva in rovina, e le terre intorno erano ridotte a una landa di cenere."
S["ce97b8d5"] = "UN MOMENTO, PER FAVORE. RICONOSCIMENTO. SHEN'DOREI. MAGISTRO DELL'ALTO ORDINE."
S["cea67440"] = "Ho sentito che i preparativi vengono spediti in Silithus e dovrebbero arrivare tutti nel giro di pochi giorni. Non voglio vedere uno di quegli insetti scavarsi un passaggio fino alla mia miniera, quindi spero che qualcuno si stia prendendo il tempo di assemblare lo Scepter of the Shifting Sands, così che il gong possa essere suonato, i cancelli aperti e la guerra finalmente cominciata."
S["cea6b2ff"] = "Schiacciateli tutti!"
S["ceb7bb34"] = "Qui intorno ci sono solo guai. Ho provato a dire a quello sciocco di Saldean di andarsene finché poteva, ma non vuole sentire ragioni. Io però mica sono uno sciocco. Appena aggiustiamo questo carro, io e Verna togliamo le tende."
S["cebd36bf"] = "Eccellente! Renderai un grande servizio alla League of Arathor liberando l'Arathi Basin da The Defilers e dai loro sgherri dell'Orda. Cerca la Lady Hoteshem nella sala delle udienze reali di Stormwind Keep. Ti sta aspettando, $N."
S["cebed14d"] = "Vai a prenderlo!!"
S["cec70605"] = "Ah... il meraviglioso suono dei kodo. Adoro come fanno tremare la terra... esamina la bestia per me."
S["ced6e418"] = "Col favore delle tenebre."
S["ced7130a"] = "Se i frayed abomination stitchings vuoi trovare, a Stratholme dovrai andare.$B$BEra la città natale del Portatore di Luce in persona, e ora è invasa dai servitori di Kel'Thuzad.$B$BSfida i pericoli della città in fiamme e abbatti i carnosi abominations! Il tuo premio lo prendi da loro: Frayed abomination stitchings!"
S["ceda17de"] = "Ah, ci voleva proprio! Quasi quasi me ne faccio un altro paio... mi tieni d'occhio questi barili, $N?"
S["cedb45cd"] = "%s va su tutte le furie!"
S["cee58b6d"] = "È fatta, $N, e credo che i risultati ti soddisferanno."
S["cee87378"] = "Pare che tu sia arrivat$Go:a; tardi, $C. Abbiamo tutti i raptor arrosto che ci servono: uccisi, cucinati e salati. Comunque, sembra che ad alcuni degli altri qui farebbe comodo un aiuto. Dovresti andare a chiedere a loro. Io vado a vedere se mi lasciano andare a casa."
S["cef1dc21"] = "Ah, e per te in particolare, $C. Ho saputo dello scontro che hai avuto con i Windshapers vicino alle pietre erette..."
S["ceffbed7"] = "Restituisci l'amuleto! Restituiscimi ciò che è stato rubato!!"
S["cf04a41a"] = "Ma ciao, $N, cosa ti porto oggi?"
S["cf0eee21"] = "I clan dei centauri dominano le lande di Desolace. Se fossero uniti, sarebbero una forza terribile. È un bene, quindi, che non lo siano, e che anzi litighino e si facciano guerra tra loro."
S["cf1d46d1"] = "Maestà, fuggite finché potete. Non è ciò che credete..."
S["cf1da8f6"] = "Ti serve un passaggio? I nostri grifoni sono sempre pronti a solcare i cieli."
S["cf2274d4"] = "Ok, ok... Sono $Gsveglio:sveglia;."
S["cf30ab8a"] = "Sono curioso di sentire cos'ha da dire un orco così arrabbiato..."
S["cf35284f"] = "Mmm, capisco. Molto bene, allora, $C. I Windshapers daranno il loro aiuto. Per favore, informa Valennia che può contare su di noi in questa battaglia."
S["cf3c2312"] = "Non starmi troppo vicino, $N. Se perdo la presa, potrei spaccarti il cranio con la testa del martello."
S["cf3e180f"] = "Mi dispiace. Al momento non posso aiutarti."
S["cf4df68d"] = "Così dovrebbe anda' bene..."
S["cf5377f0"] = "Non mi sembri granché, ma chissà: magari da qualche parte, lì dentro, si nasconde un incantatore!"
S["cf64240f"] = "Dove sono finiti gli altri?"
S["cf680c1a"] = "Scommetto che l'ho lasciato nella tenda!"
S["cf7a7007"] = "Abbiamo una scorta molto piccola di rifornimenti per ricostruire la Frostwolf Keep. Ce ne vorranno molti di più prima di poter riparare e tornare in battaglia."
S["cf7cdbfa"] = "Gli spiriti ti proteggano, mon."
S["cf7cf2ae"] = "%s torna al lavoro, ignaro di tutto ciò che lo circonda."
S["cf802734"] = "Alla Thunderbrew Distillery c'è un mago che potrebbe insegnarti qualche incantesimo nuovo. Si chiama Magis Sparkmantle, mi pare."
S["cf8fb1c1"] = "Rifornimenti dai nostri nemici! Ben fatto, $N!"
S["cf902075"] = "Fieramorte! Vengo a prenderti!"
S["cf94035f"] = "Aiuto! Mi insegue uno sciame di api!"
S["cf97a8dd"] = "Sono a capo delle operazioni di Shen'dar Village, e qui di cose da tenere d'occhio ce ne sono un sacco. Fra banditi, cultisti e altri incidenti che saltano fuori a caso, tenerlo a galla è una bella fatica."
S["cf9ad134"] = "Fra i miserabili della parte bassa di questa cittadella devi trovarne uno che abbia ottenuto un Unadorned Seal of Ascension. Per uno degli esseri inferiori riceverlo è un grande onore: è il primo passo per accedere alla parte alta della cittadella e diventare una delle guardie scelte di Nefarian — la legione Blackhand. Trova un oggetto del genere e riportamelo, così potrò esaminarne le proprietà. Quando avrò finito di studiare il sigillo, saprò come procedere."
S["cfaf5113"] = "Catalogo d'Autunno di The Thorium Brotherhood:$B$BDentro troverai le offerte migliori per tutto quello che ti serve nelle tue avventure! Ti mostreremo persino dove procurarti quei componenti e quelle provviste che sono così difficili da trovare."
S["cfb39a7d"] = "$GBen trovato:Ben trovata;, $Gamico:amica;. Sono Officer Pureheart e vado fiera di far parte di un'organizzazione che opera in tutto il mondo, conosciuta come l'Argent Dawn. La nostra causa è semplice — colpire in fretta e senza pietà ogni forma di male che si mostri su Azeroth. Non siamo un organismo politico, e non vorremo mai esserlo. Per questo l'Alleanza e l'Orda sono per noi amiche — amiche nella lotta per schiacciare il male!$B$BPer la Dawn, $Gfratello mio:sorella mia;!"
S["cfb4a62c"] = "Zannafiera!"
S["cfb6b05f"] = "Assaggia questa torta di ciliegie e ti spunterà in faccia un sorriso largo dieci miglia."
S["cfc3eb93"] = "Per Lothar, voi feccia dei Defias la pagherete!"
S["cfc6ba2a"] = "Ehi, seguimi!"
S["cfcca687"] = "<Ti fissa a lungo senza distogliere lo sguardo, con uno sbuffo di sfida.>"
S["cfce77b0"] = "La tua esistenza è riconosciuta. <La reliquia si riduce in polvere. La testa ti pulsa di una saggezza appena acquisita. Qualcosa di malvagio si annida nel cuore della montagna.>"
S["cfd3ce5a"] = "Il rituale è già cominciato!"
S["cfd3e9c5"] = "Per la Luce! Questa spia maledetta era proprio brava! Sono contento che sia morta."
S["cfd78721"] = "Un ladro? Di solito non mando la gente da quei tipi, ma credo che tu stia cercando Jannok. Lo trovi alla Locanda di Dolanaar."
S["cfe51f26"] = "A proposito, presto dovrò trovare qualcosa da mangiare. Quanto ai preparativi dell'Alleanza, mi dicono che una parte della rainbow fin albacore richiesta è già imballata. E anche una parte del roast raptor e dello spotted yellowtail richiesti è pronta: ora è in cella frigorifera e aspetta di essere spedita a Cenarion Hold, in Silithus."
S["cfe7da44"] = "Che legame potrebbe esserci fra l'altare e le statue?"
S["cff25bb4"] = "Hai assaggiato il nostro pane? Baker Masterson dev'essere il cuoco più bravo di tutti i tempi!"
S["cff6a3ba"] = "Se riesco a mettere le mani sugli ingredienti giusti, possiamo fabbricare degli esplosivi: mi serviranno per danneggiare le attività della Venture Co., e in più faranno da diversivo.$B$BLo so, sei $Gimpressionato:impressionata;, ma il bello deve ancora venire... Presto ti dirò il resto."
S["cffe9d8d"] = "...BELATHAAN BRIGHTWISH"
S["cffef178"] = "Torna da me quando avrai fatto più pratica. Può aiutarti Randal Worth, laggiù."
S["d000126d"] = "Probabilmente Zaldimar può insegnarti qualche incantesimo nuovo. Ultimamente ha preso gusto a stare alla Lion's Pride Inn: potresti dare un'occhiata nelle stanze e vedere se c'è."
S["d000b10b"] = "No, $C, non è tutto. Le forze d'élite del nemico sono guidate dai quattro Comandanti della base. Se riuscirai a colpire i loro Comandanti con un colpo rapido e mortale, la linea d'élite vacillerà. I loro numeri si ridurranno a nulla!$B$BMa stai $Gattento:attenta;, $Gsoldato:soldatessa;: i Comandanti e i Luogotenenti non vanno presi alla leggera né sottovalutati. Quei gradi se li sono guadagnati..."
S["d00de6cd"] = "Dell'incendio della Shady Rest Inn sappiamo poco, se non che la moglie e il figlio di James Hyal non sono riusciti a fuggire.$B$BJames siamo riusciti a trascinarlo fuori, ma da allora non è più lo stesso.$B$BDi piste ne abbiamo tante, di prove poche. Speriamo che, con gli sforzi della guardia e l'aiuto attento della gente di Theramore, si riesca a far luce su questo terribile crimine.$B$BSe vuoi dare una mano alle indagini, quel che resta della locanda è al confine con le Barrens."
S["d00fe8bc"] = "Abbiamo abbastanza rifornimenti per lanciare un assalto via terra. Se vuoi consegnare quegli ordini e pensi di avere i requisiti, parla con Corporal Noreg Stormpike."
S["d01e7c2f"] = "Mi sembra una delle storie di pesca di Billy."
S["d021af1a"] = "%s si scaglia contro la tua fiala di raccolta. Il bagliore verde ti avvolge. Non hai una bella cera, $Gamico:amica;."
S["d02e7255"] = "Sì, sì, calmati, $C, non c'è niente di cui preoccuparsi. Per fortuna, quando mi hai dato il pezzo sinistro la prima volta, mi sono $Gsintonizzato:sintonizzata; con esso, quindi richiamarlo da dovunque tu l'abbia 'smarrito' non è affatto un problema.$B$BEcco, e stavolta cerca di averne più cura."
S["d02eaf75"] = "Il Thandol Span è caduto per mano di Ragnaros. Così cadrà la Stonewrought Dam!"
S["d02ff3d3"] = "Lascia questo luogo!"
S["d0353471"] = "Allora ascolta bene, $R.$B$BDiversi mesi fa il Magistrato di Lakeshire ha mandato degli emissari a Ironforge a supplicare il Re di aiutarli contro le incursioni dei Blackrock, che arrivavano da Redridge e dalle Burning Steppes.$B$BPrincess Moira si è offerta volontaria per aiutarli, nonostante le mie preghiere. A me hanno assegnato venti guardie scelte per proteggere la Principessa durante il pericoloso viaggio dal Loch a Lakeshire."
S["d035e8bf"] = "Ultima carica piazzata. Stai indietro!"
S["d0371bc2"] = "Sì, sì, tutto il materiale bellico dell'Orda e dell'Alleanza viene spedito a Silithus e dovrebbe arrivare entro qualche giorno. Sai cosa succede poi, $C? Ci sbrighiamo per poi aspettare. Speriamo che qualcuno stia raccogliendo i pezzi dello Scepter of the Shifting Sands, perché per aprire le porte di Ahn'Qiraj bisogna farlo risuonare contro il gong sulla Scarab Dais."
S["d038dc0c"] = "Nel boschetto della natura si insinua la corruzione. La foresta va protetta a ogni costo."
S["d03e6ae1"] = "Ci vorrà solo un momento, $N."
S["d0426fc8"] = "Grazie! Mi hai liberato!"
S["d042f34d"] = "Il Dun Baldar North Bunker è stato distrutto dall'Orda!"
S["d047133c"] = "<Il galestrider gorgheggia piano mentre ti avvicini.>"
S["d049688e"] = "La miscela è pronta, $N. Ora dobbiamo salvare la bambina."
S["d05904c2"] = "Molte boxes of supplies chiuse a chiave sono state affondate dagli orchi nel Lake Everstill, a Redridge."
S["d0618a6a"] = "%s ascolta $N che gli racconta le sue avventure nelle Badlands."
S["d062eab4"] = "Questa resistenza continua e fastidiosa è inutile, vermi! Alla fine non ci sarà altro che morte!"
S["d066be5e"] = "%s pronuncia parole di potere..."
S["d0699e89"] = "Ecco qua..."
S["d06d1497"] = "Sono sano di mente quanto chiunque altro, $Gsignore:signora;. Credi pure quello che vuoi, ma questa armatura SONO capace di farla. Se ti interessa, forse possiamo trovare un accordo. Prima mi lascio alle spalle il mestiere di assassino, meglio è."
S["d070b166"] = "Che giornata per pescare. Oggi abboccano di sicuro!"
S["d075e646"] = "Chi mangerò per primo? È così difficile scegliere. Hanno tutti un profumo così delizioso..."
S["d07a5d28"] = "Lava? Non badare a tutto questo, $Gamico:amica;. Guardati intorno. Goditi le gioie che la natura ha da offrire."
S["d082b472"] = "Captain Brightsun, $N mi ha liberato! $N, sono certo che il Capitano ricompenserà il tuo coraggio."
S["d0844dd9"] = "Incredibile! Ha funzionato! $N, ho la tua armatura."
S["d085bcac"] = "Processo di archiviazione sospeso. Avvio del protocollo di stabilizzazione."
S["d0868391"] = "Druidi e i vostri stupidi cambi di forma. Vediamoli all'opera!"
S["d0871b5f"] = "Ora torno da dove sono venuta, solo per ritrovarmi qui ancora una volta a rivivere la stessa grande tragedia."
S["d0895b2b"] = "Riposo, $C. Se stai solo passando, ti consiglio di non lasciare le strade e di viaggiare soltanto di giorno. Se invece hai affari qui a Darkshire, pensa a mettere le tue capacità al servizio della Night Watch. Nessuno mette in dubbio la nostra abilità, ma siamo pochi."
S["d0896f30"] = "Elder Riversong per ora vive ad Ashenvale, nel villaggio di Astranaar."
S["d08b76e8"] = "Salve, giovane, e $Gbenvenuto:benvenuta; a Thunder Bluff. Qui troverai un rifugio sicuro dai pesi del mondo: tutti gli abitanti dell'Orda sono i benvenuti.$B$BIn questo luogo sacro, $Gamico mio:amica mia;, prendono vita gli spiriti del presente e del passato. Onorali, e onorerai te $Gstesso:stessa;."
S["d0951a35"] = "Sono $Gpronto:pronta;, $N. Troviamo la mia attrezzatura e andiamocene da qui. Credo di sapere dov'è."
S["d098123e"] = "Gri'lek, del Sangue di Ferro$B$BIl viandante. Che la sua forza e la sua sete di battaglia trafiggano le ere.$B$BOra Gri'lek indugia sull'orlo della follia..."
S["d09c9cf6"] = "Fandu'talah Balah dath ishnu ash banthalos ri ash dieb ala falla."
S["d0a16ff1"] = "Muori! Quelli come te non hanno posto nell'Alterac Valley!"
S["d0a6ca6e"] = "<Volcor non ti guarda nemmeno mentre ti avvicini. Sembra tutto intento a non far cadere le bende. Dopo un momento alza gli occhi su di te, un po' sorpreso.>$B$BOh, scusa, $C. Non è il momento. Spero che tu capisca."
S["d0b65dc8"] = "Va bene, va bene! Credo di riuscire a capire come si manovra questo affare..."
S["d0c2bdf6"] = "Tepa è famosa per i lavori in stoffa: la trovi dai Thunder Bluff Armorers, sull'altura di mezzo."
S["d0c9c1e9"] = "Ci vorrà più di un cadavere in decomposizione per fermarci!"
S["d0cc0d1b"] = "È una storia leggendaria, e non ho né il tempo né la voglia di raccontarla un'altra volta. Ti basti sapere che Medivh fu l'ultimo dei Guardiani, e che il grande bastone di Atiesh era il fulcro del suo potere e della corruzione."
S["d0d4c701"] = "AIUTO!!!!"
S["d0d72eea"] = "Salve, Zando'zan, vorrei imparare a scassinare le serrature."
S["d0da1be0"] = "Salute. Sii breve, che abbiamo tutti e due molto da fare."
S["d0dad27b"] = "Temeva che il suo potere si indebolisse, e che presto anche noi, le ultime delle sue preziose gemme dell'anima, saremmo svaniti e morti."
S["d0dbd0f9"] = "Ecco, $N: il tuo invisibility liquor è pronto."
S["d0e0b046"] = "Un attimo, $N, che calibro il transponder sulle tue specifiche di altezza e peso."
S["d0e4c901"] = "Evviva, $N!"
S["d0f3d96e"] = "C'è un po' di spiffero, qui... ma che m'importa? Sono morto."
S["d0f42a97"] = "Mettiamoci al lavoro!"
S["d0f49044"] = "Con me non hai affari da sbrigare, $Gpiccolo:piccola;."
S["d0f80e02"] = "Cosa!?"
S["d0fb0449"] = "Stanno bene, signore. Dovrebbero guarire tutti completamente."
S["d101f1a6"] = "Perché..."
S["d1079966"] = "$GSoldato:Soldatessa;."
S["d111d439"] = "Shoja'my è laggiù, davanti alla locanda. E adesso circola, sono $Goccupato:occupata;."
S["d12965ba"] = "Preferiresti lasciare i tuoi beni nelle mani di un goblin?"
S["d12e6ce9"] = "Flotta nemica laggiù! Fuoco!"
S["d13d2403"] = "Elder Windtotem se ne sta coi goblin di Ratchet, sulla costa della Barrens."
S["d1456f15"] = "%s stringe il corpo inerte di Taelan Fordring e singhiozza piano."
S["d145fbe4"] = "Che i venti ti benedicano, $C."
S["d149ed41"] = "Sei $Gvenuto:venuta; a proseguire l'addestramento? Allora scuotiti di dosso la polvere della strada e mettiamoci al lavoro."
S["d14ac07d"] = "%s abbaia impaziente."
S["d14cee8a"] = "Fuori ci sono i Grunt, e poi ci siamo io e i miei fratelli, che abbiamo combattuto nella battaglia di Hyjal. Chi prova a derubare la banca dovrà prima vedersela con noi."
S["d14f0fe2"] = "Uccideteli tutti!"
S["d150de10"] = "%s getta la sua enorme ombra sull'intero Silithus."
S["d15d181f"] = "La mia veglia è eterna, mortale."
S["d167c666"] = "Ascolta bene, perché il signore di Roccianera ti distruggerà di sicuro, se non sarai preparato."
S["d170f0c6"] = "La raccolta delle bende va avanti nei tempi previsti. Quanto alle linen bandages, ne abbiamo raccolto una parte di quelle che servono; delle Silk bandages ne abbiamo contata una parte, e di bende di runecloth abbiamo una parte di quelle necessarie."
S["d17af6f6"] = "Mancano solo due minuti! Siamo a metà strada, ma non abbassate la guardia!"
S["d17f95d0"] = "Argus è il fabbro di Goldshire: sono $Gsicuro:sicura; che potrebbe insegnarti la professione di Fabbro."
S["d1839f49"] = "Mi sembri un po' $Gsperduto:sperduta;, eh. Posso aiutarti a trovare qualcosa?"
S["d183ba8b"] = "Li hai visti? I fendicielo sono di nuovo in funzione! Però ho sentito che con le altre isole shen'dorei non abbiamo ancora nessun contatto.$B$BSpero che presto riusciremo a rimetterci in contatto con Shen'dramar ed Eldranaar... sempre che siano ancora là fuori."
S["d1939eca"] = "Sono stato divorato da Horgus! Sento ancora i suoi denti su di me!"
S["d198aae0"] = "Cerchi Lau'Tiki. Lo troverai più a sud, sulla Darkspear Strand, oltre Sen'jin Village."
S["d19b30f9"] = "Ti piacciono le caramelle? A me sì."
S["d19ca0aa"] = "Nah, qui nell'Elwynn Forest non credo ci siano Incantatori. Però su a Stormwind c'è un tizio di nome Lucan che ha una bottega: potresti chiedergli se è disposto ad addestrarti."
S["d1a08e90"] = "E dove saremmo andati? Era tutto quello che conoscevamo; tutto ciò che avevamo conosciuto e che avremmo mai conosciuto.$B$BCol tempo abbiamo perso i contatti con i Barov e alla fine siamo rimasti tagliati fuori dal resto della casa. Degli altri servitori non sapevamo nulla, solo che c'erano state delle urla. Urla di tortura.$B$BNon avevamo un posto dove andare, così Lucien e io siamo stati costretti a nasconderci nei nostri alloggi. Di giorno, quando la scuola era abbastanza tranquilla, Lucien sgattaiolava fuori a racimolare qualcosa da mangiare e da bere."
S["d1a4b4e9"] = "Grazie di cuore!"
S["d1a4ec98"] = "Certo che no, $Gcaro ragazzo:cara ragazza;. Voi 'avventurieri' siete spesso vittime delle circostanze; finite in mezzo ai drammi politici che di solito si consumano fra cittadini e sovrani.$B$BQuindi ti consiglio di cercarti qualcos'altro, o meglio: Una nuova carriera.$B$BDi eroi questo mondo ne ha abbastanza."
S["d1a7b5aa"] = "La Stormpike Aid Station si trova a Dun Baldar, proprio fuori dalla caserma di Dun Baldar.$B$BAl momento nessuna delle due fazioni la controlla."
S["d1b027e4"] = "Abbiamo vinto $2219W battaglie contro lo Scourge. Tieni duro, $N! Dobbiamo perseverare!"
S["d1b92a1b"] = "Le Burning Steppes sono un posto pericoloso, ma gli studiosi come me farebbero quasi di tutto pur di far progredire le loro conoscenze."
S["d1ba05cc"] = "Lascia che ti dia i miei saluti per Greatfather Winter, feccia..."
S["d1bb50ce"] = "Fornisco alla Hold reliquie di vario tipo che servono a lanciare incantesimi, e anche altri reagenti alchemici."
S["d1bf34c6"] = "In quegli anni — quando i conflitti riempivano la terra mentre la Legione e lo Scourge saccheggiavano le nostre case, uccidevano le nostre famiglie — questi insetti vivevano sotto di noi. Sotto le nostre case — in attesa."
S["d1c41359"] = "Di sicuro la cosa migliore è stata la faccia di Perenolde quando il nostro esercito gli è arrivato in marcia dritto fino alla porta di casa. Che battaglia!"
S["d1ca7f36"] = "Se vuoi provare a trovare i componenti di cui abbiamo bisogno, non ti fermerò, ma potrebbe richiedere più di un po' di recupero."
S["d1ccd3fd"] = "Banchetterò con le tue ossa!"
S["d1d7eb68"] = "Sono faccende da troll. Va' a cercare Un'Thuwa in Sen'jin Village, giù a sud."
S["d1d81974"] = "Abbiamo vissuto in fuga così a lungo che i tempi di pace sono un ricordo sempre più lontano."
S["d1db5c23"] = "Concentrate gli attacchi sul guaritore!"
S["d1db6758"] = "Ultimamente vedo sempre più spesso i fendicielo solcare il cielo. È bello sapere che funzionano di nuovo. Se solo gli anziani ci dicessero cosa succede. Non fanno che ripetere che non è cambiato nulla e che con le altre isole non abbiamo ancora nessun contatto.$B$BNon posso fare a meno di chiedermi cosa voglia dire..."
S["d1e231ac"] = "SIATE PURIFICATI DAL FUOCO!"
S["d1f0182e"] = "La Coldtooth Mine appartiene all'Alleanza."
S["d1f2d2c1"] = "%s accetta l'offerta di $N e comincia a salmodiare..."
S["d1f615a2"] = "Gliel'abbiamo fatta vedere!"
S["d1f817be"] = "Drek'Thar è il capo militare e spirituale del Frostwolf Clan in Alterac e guida i suoi fratelli dalla Frostwolf Keep.$B$BSe venisse sconfitto, le forze dell'Orda in Alterac crollerebbero."
S["d1fdccd4"] = "La Bluegill Marsh, a nord di Menethil Harbor nelle Wetlands, custodisce molte casse chiuse arrivate a riva dai relitti al largo."
S["d20e9a24"] = "La mia furia è scatenata!"
S["d216ff64"] = "$GFermo:Ferma;, $N! Questi barili li sorveglio io, quindi... si guarda, ma non si tocca!"
S["d21f4892"] = "Bene, ora parto per Ratchet! Buona fortuna a te!"
S["d2252f5d"] = "Elder Darkhorn la trovi fra le rocce rosse di Orgrimmar."
S["d22a418a"] = "Che vuoi? Adesso starei molto più contento lassù nei cieli che quaggiù a chiacchierare con $Gun:una; $R.$B$BMa mi sa che non tutti possiamo avere quello che vogliamo."
S["d22f5a48"] = "Gloria a nuovo re!"
S["d22f88ae"] = "Ma guarda, sembri $Gun:una; $Gmonello:monella; di strada qualunque!"
S["d230da93"] = "Annalise? Sei tu?"
S["d236e4b0"] = "%s cade su un ginocchio, sfinito."
S["d24267a3"] = "È tutto completato, giovane $C. Proprio mentre parliamo, sia l'Orda sia l'Alleanza stanno trasportando in Silithus, vicino alla Cenarion Hold, gli ultimi rifornimenti per la guerra, e il trasporto dovrebbe concludersi entro pochi giorni. Dopodiché si potrà suonare il gong vicino ai cancelli di Ahn'Qiraj, e la guerra avrà inizio."
S["d242b61a"] = "%s freme di energia."
S["d24bd2f1"] = "Soldati di Stormpike, venite in mio aiuto! Il segnale deve essere piantato."
S["d24f3c01"] = "Mi fanno male i piedi."
S["d254dab1"] = "Aaaaahhh! Per poco non scappavo."
S["d256d1f8"] = "%s fugge dal combattimento per cercare aiuto!"
S["d2571d15"] = "Uccidetela! Prendete la fattoria!"
S["d25b86e8"] = "Giù di morale? Fate un salto al Blue Recluse e divertitevi un po'!"
S["d25b9fda"] = "Ti ringrazio dell'aiuto. Fa' in modo che mio marito sappia che la fattoria è al sicuro."
S["d25e71c5"] = "Troverai Lotheluum Starbreeze su una scogliera che si affaccia sulla cascata, al margine orientale del villaggio."
S["d267b1ad"] = "Allora, $N, sono pronto a raccontarti cos'è successo nella Swamp of Sorrows. Hic!"
S["d276ddcf"] = "Hazza'rah, the Dreamweaver.$B$BIl potere degli incubi è suo, e che i suoi nemici possano dormire per sempre.$B$BOra Hazza'rah dimora lontano da qui. Forse, un giorno, farà ritorno..."
S["d277db5e"] = "Che rinfresco. Ora ci sono informazioni che vanno dette..."
S["d27a0393"] = "Svegli, cani! Qui abbiamo un'operazione da mandare avanti!"
S["d2842ed2"] = "%s manca il colpo..."
S["d28d3a27"] = "Salute, $Gamico:amica;! Ho una buona scorta di cuoio e di pelli, e conosco qualche tecnica che forse sarei disposta a condividere. Ti va di fare affari?"
S["d29326a7"] = "Non sbucare dalle ombre in quel modo. La prossima volta avvisa prima una ragazza."
S["d29c3b2c"] = "Lo so che stavolta funzionerà..."
S["d29f644e"] = "In guardia, $Gamico:amica;. La dama drago non si arrenderà senza combattere."
S["d2a67cb9"] = "Qui è pericoloso, padrone. Ma ti aiuterò a fare la guardia."
S["d2b4d6d7"] = "Se sei stato silenziato, o hai domande sulla procedura di silenziamento, visita...zzzzttt!!"
S["d2b759e2"] = "Giura fedeltà a Hakkar e il dolore che patirai sarà minimo."
S["d2bef252"] = "Ecco! Lavoro finito."
S["d2c57147"] = "Tocca a me, testa vuota! Ora lancio io."
S["d2c62b28"] = "Ah, ragazza, sei pronta a partire per l'Alterac Valley e a far assaggiare all'Orda quel che si va cercando?"
S["d2d4778f"] = "Non hai scampo. La Crociata distruggerà tutti coloro che portano la corruzione dello Scourge."
S["d2db8408"] = "Tessera di sicurezza rossa inserita correttamente. Erogazione in corso della tessera dati di sicurezza di livello delta.$B$B00111100 01101001 01101110 01110011 01100101 01110010 01110100 00100000 01100110 01110101 01101110 01101110 01111001 00100000 01101101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01101000 01100101 01110010 01100101 00111110"
S["d2dbbaea"] = "In ginocchio, pagano."
S["d2e37bc4"] = "Il Gran Crociato mi ha incaricato di distruggere te e i tuoi nuovi amici, Taelan, ma sappi questo: lo faccio per piacere, non per obbligo o dovere."
S["d2e449ee"] = "Il male in queste pietre è forte, ma è stato dissipato."
S["d2f45e3f"] = "Ci è stato riferito che lo Syndicate sta ficcando il naso in una grotta sull'altopiano orientale. Scopri cosa stanno tramando, soldato! $GAttento:Attenta; all'attività dei Frostwolf!"
S["d2fc62d1"] = "Ah, è da un po' che non vediamo avventurieri girare per queste sale. $GBenvenuto:Benvenuta; a Farholde Keep. Goditi queste comodità finché puoi. Sono sicuro che hai visto le condizioni in cui siamo costretti a vivere.$B$BSembra che ogni giorno perdiamo un altro pezzo della nostra casa per l'infestazione sempre più grande dei bastardi dell'Orda e dei cultisti del Twilight's Hammer, forsaken dalla Luce. Con quei codardi di Stormwind nascosti dietro le loro mura, siamo costretti a riportare l'ordine fra queste bestie da soli.$B$BForse ti andrebbe di mettere a frutto un po' di quei tuoi talenti da druido?"
S["d30addcc"] = "Devi fare quello che io non ho potuto fare: Salva i contadini abbattuti mentre fuggivano da Stratholme.$B$BCammineranno verso la luce, e tu dovrai fare in modo che sopravvivano. Se ne cadranno troppi, la nostra esistenza maledetta andrà avanti — e avrai fallito.$B$BOgni capacità, ogni preghiera e ogni incantesimo che hai imparato sarà messo alla prova. Che la Luce ti protegga, $N."
S["d30b03ec"] = "È il corpo di una guerriera orchessa.$B$BÈ chiaro che è morta in battaglia, probabilmente contro i quilboar della zona."
S["d30b27ce"] = "Supremo Magister, la Gran Veggente del Cielo non ha voluto saperne della nostra protesta e, anzi, ci ha ribadito la minaccia."
S["d3114f16"] = "La tua insolenza è inaudita, $Gsciocco:sciocca;! Banchetterò con la tua anima!"
S["d3138cb3"] = "Che la Luce ci aiuti... lo Scourge è in The Park!"
S["d313d4ca"] = "%s squittisce chiedendo aiuto..."
S["d3214827"] = "Soldato."
S["d3229495"] = "Salve, $C! La Guerra di Ahn'Qiraj si avvicina, e qui i preparativi sono in pieno corso. Io sono $Gincaricato:incaricata; di raccogliere il thick leather. Che bella giornata per raccogliere thick leather, non ti pare? Le pile le tengo qui, e sto contando quanto ne abbiamo messo da parte finora. C'è anche un numero magico da raggiungere. Vuoi darci una mano?"
S["d324ca98"] = "I pesci al largo delle coste di Teldrassil sono piuttosto grandi e robusti. Dicono che dipenda dalla rapida crescita del nostro nuovo albero del mondo."
S["d32b0469"] = "Ho scorto il cammino che devi percorrere. Sei $Gpronto:pronta;?"
S["d32de8ba"] = "La Madre Terra chiama, e tu rispondi. L'Hall of Spirits la trovi sulla Spirit Rise."
S["d32f7cc6"] = "La battaglia è finita, e la gente di Darrowshire è salva."
S["d337fd5e"] = "Ahh, i gemelli Glustewelt!"
S["d346b2d6"] = "In tempi bestiali un druido può essere un amico prezioso per chi gli sta intorno. Chiedilo pure a uno qualsiasi dei druidi della Cenarion Enclave, e ti dirà la stessa cosa."
S["d35a6de9"] = "Cinque e cinque anni, e lei la cerca ancora, anche se non era una bellezza, e c'erano molte dame che avrebbero preso il suo posto."
S["d361a078"] = "Chol'aruk banchetterà!"
S["d3646808"] = "Mi spiace lasciare un cliente, ma abbiamo posti dove andare e gente da imbrogliare. Torneremo più tardi in giornata. Arrivederci!"
S["d364bf1f"] = "%s ruggisce mentre la sua forma cambia, e corre via."
S["d368a817"] = "Lottiamo senza sosta contro lo Scourge per essere liberi, eppure non è l'unico nemico che abbiamo. Per sopravvivere ci servono una politica accorta, la ricerca e lo sfruttamento brutale delle debolezze dell'avversario.$B$BSe sei $Gpronto:pronta;, parliamo."
S["d36b9778"] = "Già, tutti vogliono salire sul tram, che è uno spasso unico. Beh, se lo cerchi, lo trovi a Tinker Town, appena a est dei cancelli di Ironforge."
S["d36f8785"] = "Nel creare pozioni sei più abile di me. Sei $Gpronto:pronta; per parlare con Ainethil, che è proprio là: capirà che puoi ricevere altri insegnamenti."
S["d36fb920"] = "Al mio fianco, fratelli! Per i Creatori!"
S["d370b076"] = "Captain Balinda Stonehearth guida le forze dell'Alleanza in prima linea. Si trova nello Stonehearth Outpost, nella parte settentrionale del Field of Strife.$B$BBalinda non è ancora tornata in battaglia."
S["d37a8e0e"] = "Sei $Gfortunato:fortunata; a essere $Gvenuto:venuta; a Darnassus: fra i nostri istruttori c'è una Cacciatrice esperta come Jocaste. Ti consiglio di andarla a trovare nella Cenarion Enclave e di chiederle di farti da maestra."
S["d37aaf89"] = "Le ali di %s tuonano in lontananza."
S["d37f32df"] = "Bende, dici? Sì, beh, se ricordo bene quel che mi hanno detto l'ultima volta, pare che l'Alleanza abbia prodotto una parte delle linen bandages, delle silk bandages e delle bende di runecloth che erano state richieste."
S["d381d6c2"] = "Il Frostwolf Graveyard si trova lungo la strada, poco a nord del Frostwolf Village.$B$BNessuna delle due parti lo controlla."
S["d385f42b"] = "Glacial Vest."
S["d388f580"] = "L'abbiamo trovato, $N."
S["d38d6278"] = "La nostra è la via della gloria, $R! La misera Alleanza sta ancora cercando di racimolare le sue provviste di guerra, mentre noi abbiamo raccolto tutte le nostre e siamo pronti a mandarle a Silithus."
S["d39fd82e"] = "<Sul cartellino del meccanostrider c'è scritto:$B$BElectric Blue Mecha-turbo Runner 5000, ora con rilevamento del movimento migliorato e ammortizzatori da terreno, per correre senza scossoni!>"
S["d3a2ac26"] = "$GUn altro:Un'altra; $GIngegnere:Ingegnera;! Ehi, è un'ottima occasione per sfoggiare qualche nuovo aggeggio che ho costruito!"
S["d3a5ecfe"] = "Spiriti maledetti! Lasciate andare il passato! Il Crystal of Zin-Malor non vi vincola più!"
S["d3aaa9ae"] = "Ma quale Jack e Jill, e il mio sedere rugoso! Qui l'acqua la porto tutta io."
S["d3be27cc"] = "Gli elfi della notte, che si dicono guardiani di questa terra, lasciano vagare liberamente Sharptalon, la più possente fra tutte le bestie della Caccia di Ashenvale. Sharptalon pattuglia le terre a sud di qui in cerca di prede, e si diverte a fare a pezzi il viaggiatore ignaro e distratto.$B$BUna bestia così, se abbattuta, sarebbe la più grande delle prede, $N. Ti auguro buona fortuna nella caccia a questa creatura!"
S["d3c1335d"] = "Chi osa evocare il potere del vuoto?"
S["d3c45e91"] = "Qui a Brill una banca non ce l'abbiamo: per quella dovrai andare a Undercity. In fondo alle Ruins of Lordaeron, a sud, ci sono gli ascensori che ti porteranno giù a Undercity. Lì, per indicazioni più precise, chiedi a uno degli Undercity Guardians."
S["d3c50562"] = "Stolto mortale, ti squarcerò l'anima in due quando sarò libero!"
S["d3ca874e"] = "Vuoi diventare $Gun gran cuoco:una gran cuoca;? Allora fai un salto alla Pig and Whistle Tavern nell'Old Town e parla con Stephen Ryback. Le costine come le cucina lui non le cucina nessuno.$B$BAccidenti... adesso mi hai fatto venire fame delle sue famose costine. Ma quella ricetta non contare che te la insegni!"
S["d3d1f2f6"] = "Rivendare deve essere distrutto!"
S["d3d3fe15"] = "<Fa schioccare i denti e morde il freno.>"
S["d3d51baa"] = "I tuoi dei non possono salvarti ora, $C."
S["d3d7962b"] = "Guardate cosa ci ha portato $N! Beviamo!"
S["d3d7cb61"] = "Si è superato il limite. Come osa lo Scourge attaccare Undercity! Distruggetelo prima che ne arrivino altri!"
S["d3dc66b9"] = "Osa minacciarci, dopo che i suoi tirapiedi hanno massacrato la nostra gente sugli altipiani?"
S["d3e9b837"] = "Bene, bene, stiamo facendo carriera, eh? Cerchi la Champions' Hall, e la trovi all'estremità sud-orientale di Old Town. Se sei $Gun ufficiale:un'ufficiale; puoi entrare, altrimenti puoi sempre parlare con Officer Areyn, che sta lì fuori. Buona fortuna!"
S["d3f45b03"] = "Un po' di tortura, un pizzico di magia e una bella dose di chirurgia invasiva. Era cosciente, naturalmente."
S["d3f9cc27"] = "Di stile ne so già molto: ora mi resta solo da padroneggiare le tecniche per lavorare il cuoio. Per fortuna Simon è uno che si presta volentieri ad aiutarmi a impararle."
S["d3fa1f44"] = "Ti do il benvenuto, $N, e con me te lo dà l'Emerald Circle.$B$BSpero che insieme riusciremo ad aiutare questa foresta, un tempo possente, a rinascere, e a proteggerla. Sono molte le forze che cercano di distruggerla dall'esterno... e dall'interno.$B$BNon lasciarti tentare dal potere che trovi qui — non farà altro che corromperti, come ha corrotto tutta questa terra."
S["d3fb9c77"] = "Devi andare al Godan's Runeworks: è in fondo a ovest di The Drag, proprio accanto a Valley of Wisdom."
S["d3fe6b18"] = "Domanda 1, Catena 1?"
S["d402e435"] = "Per poco non mandavano mio fratello Loksey a questo raduno. Non sa badare nemmeno ai suoi segugi, figuriamoci rappresentare come si deve la Scarlet Crusade."
S["d408cfeb"] = "Abbiate pazienza, vi chiameremo per nome quando sarà il vostro turno. Aiutiamo le persone nell'ordine in cui compaiono sul nostro schermo. $N!"
S["d4093072"] = "Yawww!"
S["d40e90bc"] = "Indosserò la tua pelle come giacca da camera! I sigari? Dovrai strapparmeli dalle mie fredde mani morte... ehm... RAWR!!!!"
S["d412c115"] = "Che non resti nemmeno una goccia del loro sangue sul pavimento dell'arena, figli miei. Banchettate con le loro anime!"
S["d418cda8"] = "Non preoccuparti, ti troverò una bella casa."
S["d41974dd"] = "Il tempo dell'allenamento è finito! Mostrami cosa hai imparato!"
S["d419ebec"] = "Non mi hai ascoltato? No, se Kel'Thuzad avesse ricomposto il bastone, dubito proprio che saremmo qui a parlarne. Kel'Thuzad ha la testa, i suoi sottoposti hanno quaranta schegge di Atiesh. L'ultimo pezzo — la base — l'ha ritrovato Brann Bronzebeard, che è stato visto l'ultima volta nel deserto di Silithus; di sicuro fa di tutto per stare il più lontano possibile dagli implacabili cercatori che Kel'Thuzad ha mandato per il mondo."
S["d41c8659"] = "Hai fatto di tutto, $Gstraniero:straniera;, e hai la mia gratitudine. Ti ho promesso di proseguire il tuo addestramento, e ora manterrò quella promessa."
S["d41ee2a3"] = "Il cultista è immerso in una trance profonda..."
S["d4209aaf"] = "Non posso farci niente, davvero. È solo che questo posto è così bello."
S["d420cced"] = "$GBen trovato:Ben trovata;, $C. Ti do un consiglio: quando viaggi per il mondo, diffida della magia, perché brucia chi non è addestrato."
S["d422d3b9"] = "Ti serve qualcosa?"
S["d428459b"] = "C'è un solo modo in cui un eroe può morire, $R: con una tragedia. Il Gran Crociato ha stretto un patto con Kel'Thuzad in persona! Sarebbe stata organizzata un'imboscata, e Mograine ci avrebbe trovato la morte. Un tradimento come possono farlo solo i compagni più fidati e più amati."
S["d43e64d7"] = "Dobbiamo essere vicini, Comandante. Sento gli elementi agitarsi."
S["d440c38f"] = "Arrrgh!"
S["d4478f2f"] = "Maestro di Gilda"
S["d4486927"] = "Alegorn sforna piatti buoni da morire, ed è sempre alla Craftsman's Terrace a preparare nuove prelibatezze. Se ce l'ha ancora, non perderti la sua ricetta del Verde Cenarion.$B$BOra, se non ti dispiace, devo indagare su questa serie di sparizioni di cervi."
S["d449494f"] = "Eccomi, alleanza! Abbattetemi... se ci riuscite!"
S["d44985e6"] = "Sono $Garrivato:arrivata; all'ultimo punto di passaggio. Evviva!"
S["d449e95f"] = "%s sta diventando davvero $Gaffamato:affamata;!"
S["d44a830f"] = "PE' IRONFORGE!"
S["d4705157"] = "Questo non lo chiamerei 'adatto a una scorta'. Troverò un modo per aggirare queste cose. Andiamo a sud, verso quella roccia. Forse riusciamo a infilarci in mezzo ed evitare comunque gli ogres."
S["d4836352"] = "Quanto lavoro! Non ero così impegnato da quando mio cugino ha vaporizzato per sbaglio tutta la stoffa e tutto il cuoio di Gnomeregan. Perbacco, che spifferi, per un po'! Ah, $N, quelli sì che erano bei tempi..."
S["d484c2e5"] = "Aiuto! Ci attaccano! Dark Irons!"
S["d4921d21"] = "Ze gul revos alar maez amir gulamir zenn!"
S["d496563e"] = "Vedo che imparerai in fretta. Per me è un bene, perché in questi giorni sono sempre $Goccupato:occupata;. Anzi, questo mi ricorda una cosa: potresti sbrigare una piccola commissione per me?"
S["d49dd271"] = "Da questa parte di Aerie Peak non trovi grifoni più veloci. Ti va di fare un giro?"
S["d4a5e024"] = "%s respira in modo irregolare."
S["d4ae954e"] = "Ben fatto. Un duro colpo per Arugal, senza dubbio!"
S["d4af951b"] = "Ora dove ho messo le formule della Venture Company?"
S["d4b63d02"] = "$GSciocco ingenuo:Sciocca ingenua;. La Burning Blade È lo Shadow Council! Il Consiglio tiene sotto di sé molti culti e organizzazioni, ma sono solo estensioni della sua volontà. Sarò pure io a guidare la Burning Blade, ma per il Consiglio sono una pedina, tanto quanto tu lo sei per me!$B$BGuarda la Searing Blade — quasi tutti credono di essere la nuova leva di potenti stregoni che prenderà il posto dello Shadow Council."
S["d4b86061"] = "Proprio mentre parliamo, $C, tutto il materiale bellico viene trasportato a Silithus. A quanto pare, dovrebbe arrivare tutto entro pochi giorni. Dopodiché, servirà un'eroina che si faccia avanti e suoni il gong alla Scarab Dais. Allora la guerra comincerà sul serio."
S["d4bbc275"] = "Neltharion, mmh? Una risposta valida come un'altra, no?"
S["d4c7ec5b"] = "Ah ah! Sì, tutti quanti, tranne i loro capi — il satiro, Bazzalan, e lo stregone Jergosh. Per questo continuo a mandare contro di loro gli adoratori di Thrall: così Thrall ha l'impressione che io stia estirpando il male dalle viscere della sua grande città. In realtà ci guadagno due volte: uccido i fedeli di Thrall e intanto metto alla prova la forza di quelli della Searing Blade, per vedere se sono davvero degni di unirsi a me."
S["d4d98f92"] = "Ehm, Ozzie... non sembra molto sicuro."
S["d4da7c5e"] = "%s abbassa le spalle e scopre il collo."
S["d4dfa17f"] = "Perché dovrei negarlo? La conestabile ha già emesso la sentenza: mentire non servirebbe a niente."
S["d4e00f0e"] = "Debole $C! Non sei all'altezza della Tribù Stonesplinter!"
S["d4e643e5"] = "%s si schiude!"
S["d4eadd53"] = "Pane di tutti i tipi! Fatto fresco oggi. Prendetelo finché dura!"
S["d4f4906f"] = "Ho freddo, mio signore. Quando manterrete la vostra promessa?"
S["d4f94c8b"] = "*sigh* ...113 gradi Kraklenheit. Non sai fare di meglio?"
S["d4fb8319"] = "%s mette la testa di Marg nel calderone."
S["d50bc76d"] = "Padrone, mi serve aiuto!"
S["d50ca1bc"] = "Buliwyf, il maestro d'armi nanico delle Timberline Arms a Ironforge, insegna a usare le armi da pugno, i fucili, le asce e le mazze, a una e a due mani.$B$BBixi Wobblebonk, la maestra d'armi gnoma delle Timberline Arms a Ironforge, insegna a usare la balestra, i pugnali e le armi da lancio.$B$BWoo Ping, il maestro d'armi umano del Weller's Arsenal a Stormwind, insegna a usare la balestra, i pugnali, le spade a una e a due mani, le armi in asta e il bastone."
S["d50fd714"] = "La tua ricerca è quasi finita. Va' a cercare la tua verità nella sala d'ingresso della Thrall's Fortress, in Valley of Wisdom."
S["d516113d"] = "Per millenni questo essere rimase dormiente sotto il mondo, in attesa. Dalla sua prigione aspettava il momento esatto per colpire chi voleva vederlo sconfitto."
S["d52b7265"] = "Mmh... beh, mi sembri abbastanza capace. Se hai davvero voglia di imparare, niente ti sbarrerà la strada! Ti guiderò nei primi passi di quello che spero sarà un sentiero lungo e appagante."
S["d52f634a"] = "I Dark Iron Dwarves si riprenderanno le terre che spettano loro di diritto!"
S["d537773a"] = "Da queste parti di sporcaccioni ce ne sono proprio tanti."
S["d539e546"] = "Uff... questi parassiti mi fanno sgobbare giorno e notte! Non li hai visti?$B$BMagari potessi buttarmi giù per un tubo e scappare da loro..."
S["d56f8449"] = "Polar Tunic."
S["d57c68c4"] = "$GBen trovato:Ben trovata;, $N. Fa piacere vedere che chi è $Gun:una; $C come te fa la sua parte per proteggere i boschetti."
S["d57c851f"] = "Salve, $Gamico:amica;. Posso fare qualcosa per te?"
S["d57ca6a6"] = "Se cerchi la compagnia dei tuoi confratelli paladini, sei $Gvenuto:venuta; nel posto giusto.$B$B$GBentornato:Bentornata; a casa."
S["d57f01bb"] = "Che splendida tempesta!"
S["d5808aa3"] = "Ehi, tu! Sembri $Grobusto:robusta;... ci serve una mano per difendere Southshore!$B$BQuei maledetti Forsaken sono tutti agitati perché è Hallow's End, e con la loro \"festa\" ce li ritroveremo di sicuro dritti sotto casa. Se hai tempo, il tuo aiuto ci farebbe comodo!"
S["d58b1fe3"] = "UCCIDI!!!"
S["d58b5250"] = "Uccidi..."
S["d5a56efc"] = "Stolti! La nostra causa è giusta!"
S["d5adab7e"] = "%s è ridotto al silenzio dal pungiglione velenoso."
S["d5cc0a04"] = "Coraggio, Alleanza! Cacciate queste canaglie dall'Alterac Valley!"
S["d5cfa0c3"] = "%s esamina i gusci degli snapjaw..."
S["d5d0fe4e"] = "Spero sia una cosa importante!"
S["d5dfbe6d"] = "Hazza'rah, the Dreamweaver.$B$BSuo è il potere degli incubi, e possano i suoi nemici dormire in eterno.$B$BOra Hazza'rah sogna sull'orlo della follia."
S["d5dfca40"] = "Avete sentito il Signore della Guerra, vermi! MARCIATE!"
S["d5f6f299"] = "Grazie per avermi salvato!$B$BSono cuoco e alchimista, vengo da Stormwind. Cercavo erbe e ricette del posto per mio zio Angus quando mi hanno catturato questi quilboar. Se non fossi $Garrivato:arrivata; tu, sono sicuro che sarei finito nella loro pentola!"
S["d5fd7f66"] = "Non aver paura: siamo qui per aiutarti. Ti siamo grati per la difesa che ci hai offerto nella nostra vecchia casa, e in segno di ringraziamento siamo venuti ad aiutarti a tornare in fretta nelle Plaguelands, se ne avessi bisogno. Il mio compagno può spiegarti meglio come funziona; lo troverai nel punto della città dove le energie arcane sono più forti."
S["d601a6d0"] = "La raccolta è finita e i beni pronti vengono spediti a Silithus man mano che vengono completati. Pare che manchi meno di un giorno prima che sia tutto lì. Dopo di che ci serve solo qualcuno che suoni quel gong e apra le porte di Ahn'Qiraj. Allora comincia il vero divertimento."
S["d602959c"] = "%s si prepara a pungere la sua vittima in un ultimo gesto disperato!"
S["d603112f"] = "Grazie, $Gpaladino:paladina;. Mettiamoci in marcia."
S["d60d3acf"] = "Prendi una Candle of Beckoning da questa cassa, $N."
S["d6161e19"] = "I colori prescritti sono il nero, il grigio e il viola scuro. Bada a non sgarrare in fatto di moda, $Gamico:amica;: Bowen Brisboise può aiutarti a evitarlo. Lo troverai nel Cold Hearth Manor, dall'altra parte del ponte, a sud-ovest del paese."
S["d61b65e9"] = "Se lo sapessi, credo che qui su Zephras la vita sarebbe molto, molto più facile. Gran parte delle nostre lotte e dei nostri conflitti ruota proprio attorno a questo mistero.$B$BApprezzo la tua curiosità, ma per oggi temo di non avere altro da dirti in proposito."
S["d620d6d1"] = "Conserva il sapere e la parola, e perfino l'autonomia per svolgere compiti per te. Cosa le hai fatto, di preciso?"
S["d622f395"] = "È andato perduto quando è caduta la Violet Citadel... frantumato in quarantadue pezzi."
S["d6253e03"] = "Sì, ho controllato, mi manca il pezzo di sopra!"
S["d6280bbf"] = "Benvenuta, sorella mia. Se sei qui per addestrarti, ti istruirò con piacere.$B$BMentre Malfurion giace nel Sogno, siamo noi i custodi dell'equilibrio, ora e per sempre. Non scordarlo mai."
S["d6298648"] = "Cerca di avere più cura di te, Quinn. Stavolta ti è andata bene."
S["d62a2357"] = "Cerchi Uthan Stillwater. È a pescare allo Stonebull Lake, a ovest del villaggio: lo troverai lì."
S["d62a24bb"] = "Zimrel"
S["d62a358a"] = "Protezioni... cos'è questa storia delle protezioni, Valennia?"
S["d62c580e"] = "I Creatori sono... i Creatori.$B$BSono gli esseri che hanno seminato questo mondo e l'hanno plasmato secondo il loro disegno. È per loro che esistono questo mondo e molti altri: sono la fonte da cui sgorga Azeroth."
S["d62c906a"] = "Salute. Io sono $Gun istruttore gnomo:un'istruttrice gnoma; di magia, e tu sei $Gun mago:una maga;."
S["d63003a9"] = "Ehi, $Gamico:amica;! Un riding raptor te lo offrirei volentieri, ma prima dovresti andare ad addestrarti da Xar'Ti.$B$BSono creature senza paura e non si fanno cavalcare tanto facilmente, ma quando impari a guidarne una, non troverai compagno migliore. $GAttento:Attenta; agli artigli, però: basta una zampata sola per abbattere un kodo adulto."
S["d63397f7"] = "La nostra punizione è anche la nostra benedizione."
S["d63f031f"] = "Elder Bellowrage è su un crinale nelle Blasted Lands, da dove sorveglia il Dark Portal."
S["d642695b"] = "Ho mentito..."
S["d647e12e"] = "Da questa parte di Khaz Modan non troverai uno spiedino di ratto migliore!"
S["d6512377"] = "Se hai abbastanza oro per pagare la lezione, posso insegnarti i segreti del Cavalcare Lupi!"
S["d652f6a3"] = "Che la battaglia per Warsong Gulch abbia inizio!"
S["d667b25f"] = "Gli spiriti mi sussurrano all'orecchio. Sono inquieti e pieni d'angoscia."
S["d66a58fa"] = "Ahh, allora devi andare all'Hunter's Hall: lì, sull'Hunter Rise, troverai diversi grandi cacciatori, come Holt Thunderhorn."
S["d670ae17"] = "Lok'tar, $R. Sono General Zog, ambasciatore dell'Orda, e mi trovo qui per tenerti $Ginformato:informata; su come procedono i preparativi della possente Orda per la Guerra di Ahn'Qiraj. Cosa vuoi sapere?"
S["d670cd44"] = "Te l'avevo detto che avevi il sangue di un fabbro, e avevo ragione. Vai a Ironforge, a The Great Forge, e trova un fabbro nano di nome Bengus Deepforge. Il mio maestro, e uno dei più grandi fabbri che abbia mai conosciuto."
S["d672b1a4"] = "Nel cielo notturno agisce qualcosa di più grande della magia. Un giorno mi daranno ascolto..."
S["d6738f20"] = "Argh, che dolore. Mi lascerà mai?"
S["d67499f2"] = "Imbecille! Non hai ancora imparato il Sistema Decimale Dewey? Sono passati 3.000 anni da quando hai cominciato a lavorare per noi! Buffone incompetente."
S["d679c824"] = "Jeztor vive! È ora di illuminare il cielo della Valle, Comandante."
S["d6808f35"] = "Eh?!? Ah. Non hai l'aria di $Gun ladro:una ladra; dei Defias... e neanche di un membro della Night Watch. Abbi pietà di un poveraccio, eh?"
S["d680b38a"] = "Bene, bene, non vedevo lame così belle da quando ho lasciato Lordaeron con Proudmore e la sua gente. A quanto pare non posso insegnarti molto di più, ma se trovassi Borgus Steelhand scommetto che potrebbe mostrarti qualcosa. È il miglior fabbro d'armi che abbia mai conosciuto."
S["d68b16bd"] = "Ciao! E $Gbenvenuto:benvenuta;! Mi spiace, ma la bancarella è chiusa... c'è un sacco da riparare...$B$BMa un giuramento di sangue mi obbliga lo stesso a strapparti un sorriso. Quindi sorridi, ti prego, o dovrò tagliarmi la mano e non mangiare carne viva finché non ricresce..."
S["d68e2ca7"] = "%s dà l'allarme!"
S["d68f00a5"] = "Liberami e basta! Non ne posso più!"
S["d691fdbe"] = "Anu therador mali $C. Dove posso guidarti?"
S["d694c0a3"] = "VanCleef manda a dire che i piani procedono. Ma ha sentito voci di qualcuno che ficca il naso in giro."
S["d69856dd"] = "Cittadini dell'Alleanza, il Signore di Roccianera è morto! Nefarian è stato sconfitto dalla forza unita di $N e dei suoi alleati!"
S["d6a982eb"] = "Cosa pensi di ottenere, stolto? Proprio ora gli eserciti di Roccianera si preparano a distruggere il tuo mondo."
S["d6aad402"] = "Così arrabbiato, Sarok? Non dovresti bere così tanto... Dicci solo quello che sai di Mosarn."
S["d6b6faa8"] = "Il Frostwolf Graveyard è sotto attacco! Se nessuno interviene, l'Orda lo conquisterà!"
S["d6bf5b44"] = "Le pietre di questo luogo sono state scolpite da mani antiche e plasmate da venti eterni."
S["d6c36f9c"] = "A questo punto tu sai quanto me, amico. Forse vai da Magar a Orgrimmar. Lui non essere il sarto più allegro in giro, ma ti aiuta lo stesso."
S["d6c8b654"] = "La gente di Westfall non perdonerà mai l'abbandono di Stormwind."
S["d6d17e50"] = "Il nostro Comandante è caduto! È giunta l'ora della vendetta! Cavalieri degli arieti, alla carica!!!!!!"
S["d6d8b3b2"] = "La tua abilità ha i suoi meriti, ma devo sottoporti a un'ultima prova prima di prenderti con me."
S["d6dc2bad"] = "%s si batte il petto, chiamando aiuto!"
S["d6ddebf5"] = "Bene, $N, al lavoro su quei calderoni! Per raccogliere i componenti che ci servono, prendi da me un vitreous focuser: dovrai portarlo con te per riconoscere sullo Scourge le risorse che serviranno a convertirli.$B$BPer i calderoni ti serve anche una dose di arcane quickener. Non costa poco, e non è nemmeno stabile: una volta preso, hai solo trenta minuti per usarlo prima che scada. Compralo con giudizio."
S["d6e90b9a"] = "Sarò felice di istruirti quando sarai $Gpronto:pronta;, ma quel momento non è ancora arrivato! Sono $Gsicuro:sicura; che Lalina Summermoon ti guiderà fino ad allora. La trovi nella Craftsmen's Terrace a Darnassus."
S["d6e97abe"] = "Uccideteli tutti. Lasciate i loro gusci vuoti al padrone, perché li divori..."
S["d6edd13c"] = "Bene. Prima di mettere in atto il mio piano dobbiamo creare una pietra della vita. Sei $Gpronto:pronta; ad agire?"
S["d6f14a5a"] = "Si direbbe che qualcuno ti abbia spezzato il cuore. Torna quando non sarai così triste."
S["d6f95d38"] = "La torre di Northpass ha bisogno del nostro aiuto! Ancora una volta, alla carica, e rendiamo onore al nostro signore!"
S["d6fa8665"] = "Dammi il travestimento viola da ogre!"
S["d6fbf14e"] = "Le mie lame non luccicano, non scintillano, non brillano, e quando non ci sarò più nessuno dedicherà canzoni epiche alle mie creazioni.$B$BPerò di una cosa puoi stare $Gsicuro:sicura;: le mie armi abbatteranno tutti i cavalieri di Stormwind prima di perdere il filo."
S["d6fe06a2"] = "Sono $Gsicuro:sicura; al 100% di voler imparare le vie dell'ingegneria goblin."
S["d7007c79"] = "La lama lenta penetra lo scudo."
S["d712fa75"] = "Ecco fatto, ce l'abbiamo fatta! Il rituale è avviato e i fuochi degli idoli stanno per spegnersi per sempre! Siete davvero gli eroi che pensavo!"
S["d72122b7"] = "Una voce tonante rimbomba dalla pietra...$B$BE questo cos'è? Sento zampettare qua e là $Gun piccolo cultista:una piccola cultista;! Smamma, verme, se non vuoi subire l'ira dei signori del Consiglio!"
S["d727c2b9"] = "$N rivendica le stalle! Se nessuno interviene, l'Orda ne prenderà il controllo tra 1 minuto!"
S["d72941da"] = "Lizzarik ha lame. Lizzarik ha mazze. Lizzarik ha qui tutte le armi che ti servono!"
S["d7330c52"] = "%s esamina il Searing Collar..."
S["d73dd048"] = "Ah! Le mie ferite sono troppo gravi. Difensori, continuate a combattere senza di me!"
S["d744f028"] = "La battaglia è vinta. Per ora abbiamo respinto la minaccia dello Scourge. Possiamo dedicare le nostre risorse ad aiutarti, per ringraziarti e per prepararci al futuro."
S["d74a5276"] = "I loro spiriti sono rinvigoriti! I grifoni sono pronti a colpire! Venite, soldati! Venite al mio fianco!"
S["d74bb987"] = "Un vero mistero del passato! Ma anche una chiave per il nostro futuro!"
S["d74ddaad"] = "Questi infedeli mortali, mio signore! Hanno invaso il vostro santuario e cercano di rubare i vostri segreti!"
S["d750e69b"] = "Chi ha disturbato l'altare della dea?"
S["d753eb75"] = "Gli spiriti siano forti con te, mon. Che può fare 'sta troll per te?"
S["d7566de9"] = "Alla tribù Blackwood non deve essere permesso di intralciare il corso della natura."
S["d75aea1f"] = "Ma certo, $N. Hai l'aria di una persona di cui ci si può fidare... Affidabile! Lo capisco lontano un miglio...$B$BComunque, dicevo. Per fare il Videre Elixir ci vuole una pianta di Evoroot. Gli altri ingredienti sono roba da poco, a dire il vero, ma l'Evoroot, be', quella può essere un po' difficile da trovare."
S["d75c8258"] = "<Guarda dentro la lacrima cristallina.>"
S["d7602a9b"] = "Intrusi al Cancello di Servizio! Bisogna avvisare Baron Rivendare!"
S["d76247bf"] = "Gli umani e quella loro cosiddetta League of Arathor pensano di cacciarci da Arathi Basin. Non credo proprio, $C! Sei $Gpronto:pronta; a farti mandare lì per dimostrare che presto se ne andranno loro, e non The Defilers?"
S["d763ca71"] = "Vieni a fare un viaggio nelle meravigliose, splendide giungle tropicali di Stranglethorn. Proprio così, anche tu puoi passare il tempo a prendere il sole in riva ad acque azzurre e cristalline, mentre io me ne sto qui con questo caldo insopportabile e per tutto il giorno non ho altro da guardare che mio fratello Frezza! Buon viaggio!"
S["d7686b06"] = "Pochi ne ho visti, di trogg così schifosi. Muori!"
S["d76ba21a"] = "Sì? Ho una corazza da finire, perciò spero per te che sia una cosa importante."
S["d7722b2a"] = "%s è colpito dalla magia scatenata!"
S["d772abd5"] = "Guerrieri, so che potete colpire più forte di così! Fatemi vedere!"
S["d7731444"] = "Vivo solo per servire il nostro Re."
S["d7739259"] = "Troverai Sildinair alla Terrazza del Guerriero, fra le guardie: scruta la foresta con occhi acuti, in cerca di nemici che osino entrare nella nostra bella città."
S["d77e803a"] = "punto di conquista Progress1"
S["d77e803b"] = "punto di conquista Progress2"
S["d7812405"] = "Ragazzi, l'avete vista? Io non ho visto Darcy. Chissà dov'è stasera."
S["d785ac22"] = "Tutti i liquidi e le miscele ribollono e sussultano quando ti avvicini. Accanto all'attrezzatura c'è un grosso paio di pinze che sembrano adatte per immergere campioni di melma.$B$BC'è dell'equipaggiamento di protezione, ma sembra impolverato e lasciato lì da tempo.$B$BMetti alcuni dei tuoi campioni nei becher?"
S["d7902aac"] = "Ciao! Sono contento che tu sia $Gtornato:tornata;, $N. Dimmi, hai portato a termine la prima missione che ti ho affidato? Se sì, potrei averne una seconda per te..."
S["d797d1ab"] = "Il buon vecchio Thamner mi ha fasciato proprio l'altro giorno, quando mi sono scontrato con un trogg rognoso. Sono come nuovo, te lo dico io! Di sicuro Thamner sarà felice di insegnarti a fare una buona benda."
S["d79d8c4b"] = "Elder Wildmane vive a Zul'Farrak, nel Tanaris Desert."
S["d7a15699"] = "Dammi l'arcano e creerò l'amalgama, mortale."
S["d7a39501"] = "<Davanti a te giace il cadavere di Jorel Windsinger.$B$BHa le gambe squarciate da profonde lacerazioni e la pelliccia bruciata dai fulmini.$B$BÈ chiaro che ha lottato, prima di morire per le ferite.>"
S["d7b85acc"] = "%s comincia a trarre energia dalla terra"
S["d7ba9552"] = "Quando abbiamo guardato attraverso quel buco della serratura, qualcuno ha ricambiato lo sguardo — i membri di un ordine magico molto simile al nostro, chiamato Kirin Tor. Abbiamo imparato molto da loro."
S["d7bbe19c"] = "Sono Bilgewhizzle, l'ingegnere capo della Gadgetzan Water Company. Come posso aiutarti?"
S["d7bedad9"] = "All'attacco!"
S["d7c25056"] = "La gente di Darkshire si aspetta di più dal Consiglio. Non possiamo lasciarla soffrire per questa ira empia che ci perseguita."
S["d7c6839a"] = "Non lasciate sopravvissuti!"
S["d7cd443e"] = "Ecco gli ordini, $N. Ora portali subito a Field Marshal Teravaine!"
S["d7d118b3"] = "So molte cose, $R: ascoltami e lasciati istruire."
S["d7d14a94"] = "Sciamani, proprio come me, ma di un ordine di grandezza più potenti. Questo potere e la loro conoscenza dei piani elementali sono la chiave della nostra sopravvivenza."
S["d7dd7618"] = "Fanti, in riga!"
S["d7e734ae"] = "La vendetta è mia!"
S["d7edd6c4"] = "Sì, comandante!"
S["d7f12941"] = "La piaga dello Scourge regna ancora sulla zona, e prima di riuscire a modificarla abbastanza da colpirli c'è molta strada da fare. Raccogli le risorse che servono e dai il tuo contributo allo sforzo bellico!"
S["d7fe68a9"] = "Capitani, fate avanzare i vostri primi combattenti."
S["d7fff2e6"] = "<Davanti a te giace un cadavere, coperto di bruciacchiature e ustioni. Pare che stringa qualcosa in mano.>"
S["d8060471"] = "%s emette uno strillo assordante!"
S["d80f9a46"] = "Ehi Reese, porta un altro giro a me e a Christoph."
S["d810bf04"] = "Non potete distruggermi! Per volere di Ragnaros, rinascerò!"
S["d8274623"] = "%s fruga tra i rifiuti."
S["d82b696b"] = "Yarrr... vedi di non farmi perdere tempo, compare!"
S["d83470af"] = "Un tempo il monastero era un luogo di studio e di illuminazione. Con l'ascesa dello Scourge dei non morti durante la Third War, il pacifico Monastero è diventato una roccaforte della fanatica Scarlet Crusade. I Crociati non tollerano nessuna razza che non sia umana, di qualunque alleanza o affiliazione. Per loro ogni estraneo, nessuno escluso, può portare la piaga dei non morti — e va distrutto."
S["d834d192"] = "Presto, $Gbambino:bambina;... molto presto."
S["d8369d24"] = "La Cucina è un impegno che dura tutta la vita, e vedo che abbiamo la stessa passione!"
S["d83e81cd"] = "Grazie, $Gragazzo:ragazza;. Grazie infinite."
S["d842a395"] = "Un soldato ben nutrito resta in vita molto dopo che le ferite del campo di battaglia avrebbero dovuto finirlo, $C. Se vogliamo resistere nella Guerra di Ahn'Qiraj che ci aspetta, ci serviranno tutte le provviste che riusciamo a trasportare. Qui raccolgo lo spotted yellowtail prima che venga spedito.$B$BUna parte l'abbiamo già messa insieme, ma per sfamare tutti dobbiamo arrivare al totale richiesto."
S["d84cd16a"] = "%s si agita a disagio."
S["d858226c"] = "Carne, pelle, ossa... un buon cacciatore non butta via niente. Anche un ritaglio di cuoio può tornare utile, magari per rinforzare l'armatura di un alleato. Così ognuno di noi è forte da solo, ma insieme diventiamo invincibili."
S["d8603553"] = "Ti sembro una guida? E va bene, di cosa hai bisogno?"
S["d8667b83"] = "Lo spirito ti fissa intensamente negli occhi e ti afferra la mano. Un calore ti attraversa il corpo, così forte da farti quasi cadere in ginocchio.$B$BQuando svanisce, senti dentro di te la lieve presenza di uno spirito d'orso... che rafforza la tua determinazione."
S["d884fafc"] = "Nel mio piano d'affari non c'erano kodo giganti da ospitare... forse era meglio buttarmi nel commercio di cesti intrecciati sott'acqua."
S["d893304e"] = "<Questo ariete ti osserva con interesse prima di abbassare la testa.>"
S["d89d1b73"] = "Proviamo a piantarlo in un po' del mio terreno speciale, preparato apposta..."
S["d8a1d1c2"] = "Bene. Dimostri di avere la stoffa per entrare nei ranghi dell'élite. Ora, altro allenamento."
S["d8a328b2"] = "Se vuoi mettere le mani su dei moduli per fondare una gilda, ti tocca salire fino a Ironforge e passare dall'Ironforge Visitor's Center."
S["d8acc2b9"] = "L'anima di mio figlio non troverà conforto in questa vittoria vuota, drago. Lo riavrò indietro. Dovessero volerci mille anni, RIAVRÒ mio figlio!"
S["d8af2bcb"] = "%s legge dalle tavolette. Suoni ignoti, mai uditi, fluiscono nella tua coscienza."
S["d8b31aa1"] = "Solo il sangue di un innocente può placare la fame di Aku'mai."
S["d8b89fb8"] = "L'Iceblood Tower è stata distrutta dall'Alleanza!"
S["d8c9e732"] = "Ti tengo d'occhio, $R."
S["d8d8e4a9"] = "L'Arcidruido crede che Ivus the Forest Lord verrà, una volta che saprà delle forze distruttive in questa valle."
S["d8de517c"] = "Inginocchiati, Grark."
S["d8e607a4"] = "Il rogo dell'Uomo di Vimini comincerà tra quindici minuti! Venite alla festa, appena a ovest di Undercity, e celebrate Hallow's End e la nostra liberazione dallo Scourge!"
S["d8eaae9a"] = "La Brotherhood non lascerà correre quello che fai."
S["d8ebbd3e"] = "Eppure la loro ammirazione reciproca era così profonda che nessuno dei due si sentiva degno dell'amore dell'altro. Non si confessarono mai nulla."
S["d8ed0da1"] = "Alta Sacerdotessa, siamo pronti a compiere la vostra volontà. Io marcerò sulla torre di guardia occidentale e Commander Cyclas guiderà l'attacco a Shen'dar Village. Entro domani saranno entrambi nostri."
S["d8eeb466"] = "Benvenut$Go:a; nel paese del gusto!"
S["d8f2bb4e"] = "Tyrande manda le sue preghiere. Madre Luna benedice tutti noi."
S["d901d0a9"] = "Oh, da qui vedo Liladris... Dille che sono qui, per favore."
S["d9123f9e"] = "$GBenvenuto:Benvenuta; alla gara di pesca di Booty Bay, dove ogni settimana chi pesca meglio lo proclamiamo Gran Pescatore!$B$BFra le 2 e le 4 del pomeriggio, lungo tutta la costa di Stranglethorn compariranno banchi di tastyfish. Se il galleggiante ti finisce in uno di quei banchi di tastyfish, invece del solito pescato di Stranglethorn tirerai su qualcosa da lì."
S["d912db2f"] = "La tua vita è mia!"
S["d918c31a"] = "Ce l'abbiamo fatta, $Gragazzo:ragazza;! L'Alleanza e l'Orda hanno finito di raccogliere tutto ciò che pensiamo servirà per la guerra di Ahn'Qiraj. Proprio ora gli ultimi beni vengono portati alla Cenarion Hold a Silithus e l'ultimo carico arriverà entro un giorno. Dopo di che $Gun coraggioso eroe:una coraggiosa eroina; dovrà suonare il Gong degli Scarabei con lo Scepter of the Shifting Sands per aprire le porte di Ahn'Qiraj. Quando quelle porte si apriranno, la guerra comincerà!"
S["d91fc776"] = "Mi stanno uscendo le budella! AIUTO!"
S["d9231bf9"] = "Ora dobbiamo solo capire come far funzionare di nuovo questo aggeggio."
S["d9300bcd"] = "Dipenderà dalla scelta del demone che vuoi evocare e soggiogare. Noi brandiamo poteri oscuri, e paghiamo a caro prezzo il loro uso."
S["d9300d15"] = "Grazie, Charys. Vieni, Paige, tesoro."
S["d930e9df"] = "La Bandiera dell'Alleanza è stata lasciata cadere da $N!"
S["d934d1f5"] = "Avvicinatevi! La migliore scelta di armi da questa parte di Ashenvale!"
S["d939dc46"] = "Fammi vedere che roba da bere hai da vendere, Kreeg."
S["d93d9c87"] = "Quello là, Malagan. $GLo:La; conosco. $GAffidabile, coraggioso e degno di fiducia:Affidabile, coraggiosa e degna di fiducia;. Si chiama $N."
S["d93e8fcf"] = "Va bene, beh... non montarti la testa! Però hai dimostrato di saperci fare, quindi ora possiamo cominciare!"
S["d942e72a"] = "Hai scelto con saggezza, $N. Cerca Kergul Bloodaxe sull'Hunter Rise. Ti aiuterà nel tuo viaggio verso la Warsong Gulch."
S["d946a2bd"] = "Come mio fratello, onoro chi onora i propri antenati, ed è per me una grande gioia condividere i miei segreti di artigianato con i seguaci del Festival Lunare!"
S["d9498009"] = "Darrowshire, alle armi! Lo Scourge si avvicina!"
S["d94c0f27"] = "Salute, $C. Immagino che tu sia qui per sapere dello sforzo bellico di Ahn'Qiraj. Ci servirà moltissimo aiuto.$B$BLo sforzo bellico è un'impresa che l'Orda e l'Alleanza portano avanti insieme per prepararsi alla guerra ormai vicina contro i Silithid e i loro padroni ad Ahn'Qiraj. Nell'Orgrimmar's Valley of Spirits stiamo raccogliendo un'enorme quantità di merci da trasformare in materiale bellico, ed è proprio per queste raccolte che ci serve il tuo aiuto.$B$BPosso convincerti a parlare con il nostro comandante di come dare una mano?"
S["d94c1ef5"] = "Desidero parlare con gli spiriti, Tiev."
S["d94d0124"] = "Lieto di conoscerti. Posso fare qualcosa per te?"
S["d95738ae"] = "Ti insegno quello che posso."
S["d95ad942"] = "Mi hai portato davvero la pelle della bestia? Beh... Lascia che ti mostri..."
S["d95b265d"] = "Il mio trampoliere ha bisogno di addestramento."
S["d95bd7e2"] = "Odes, veld lo ruff far tiras. Vil lordaere lo lon ver borne. Gol me lon dana Methrine regen wirsh dana va."
S["d95f1788"] = "Adesso farai saltare in aria quella porta?"
S["d9671b71"] = "Guarite, miei cuccioli!"
S["d975178f"] = "Non può essere! Qui comando io! Voi mortali non siete nulla per quelli della mia specie! Mi sentite? Nulla!"
S["d97a5c07"] = "Voi bipedi non siete niente! Vi potrebbero battere i miei figli!"
S["d98228c8"] = "%s vede i suoi tifosi esultare e ha uno scatto di velocità!"
S["d9832df5"] = "Ciao, sono qui per l'addestramento."
S["d98ac314"] = "SONO QUI!"
S["d9940767"] = "Dalle ceneri dell'uomo di vimini in fiamme si sprigiona potere magico."
S["d995cb83"] = "$GUn:Una; $R inutile come te, $N, non ha il diritto di camminare su queste terre!"
S["d99b44d3"] = "Abbattere le protezioni? Sono a terra da giorni, stolti. No, sto soltanto accendendo un faro... perché i veri servitori di Al'Akir possano seguirlo."
S["d9a6a91b"] = "Ishnu... Oshalan thara dormil... Anu'dorin..."
S["d9b312c5"] = "Certo che commerciamo in oro! Dopotutto è una moneta universale.$B$BTuttavia, per gli scambi fra di noi abbiamo un nostro sistema. Si chiama Favore del Mercante, e in pratica mette da parte il valore sempre variabile dell'oro e dell'argento. Questo garantisce un commercio costante, giusto ed equo fra i membri dell'Azeroth Commerce Authority. E prima che tu lo chieda, no, non si può convertire in oro.$B$BUsiamo ancora l'oro per gli scambi semplici, come i fili di base o le fiale per l'alchimia, sai — i lavori di tutti i giorni. Per il resto contiamo sul Favore del Mercante.$B$BPiù ci aiuterai con le spedizioni perdute e con la marea di commissioni di lavoro, più Favore guadagnerai!"
S["d9b502e2"] = "Ecco. Ho finito la tua veste, $N."
S["d9c207b9"] = "Non abbiamo tempo per chiacchierare! Dobbiamo pensare a quei troll!"
S["d9c4c0ca"] = "Sei $Gvenuto:venuta; ad addestrarti con la guardia di Theramore, eh?"
S["d9c74d8b"] = "Io sono Saurfang. Fratello di Broxigar."
S["d9da2b96"] = "La Settimana dei Custodi non è ancora finita... posso avere un altro Fischietto dell'Orfano?"
S["d9df11dc"] = "SONO VICINO!"
S["d9e551a3"] = "La temperatura è di 564 gradi Kraklenheit."
S["d9ea5d40"] = "Torta sarà così in pensiero."
S["d9f2b275"] = "Sono quel che si dice un capitalista, $R."
S["d9fd35e6"] = "Lo spirito ucciso di Lunaclaw ti fissa con insistenza, come se volesse qualcosa da te."
S["d9fe63c5"] = "%s si rotola a terra dalle risate."
S["da089865"] = "Molto bene, Zannafiera, puoi iniziare la marcia. Procedete!"
S["da0ea257"] = "Perdonami, padre! Ti prego..."
S["da0f6ff7"] = "La forza di %s cala mentre si staccano pezzi di roccia"
S["da110ba7"] = "Ben fatto, $Gservo:serva;. Per così tanto tempo sono $Gstato:stata; $Gtenuto:tenuta; $Gprigioniero:prigioniera; nella prigione del Firelord. Sono di nuovo $Glibero:libera; di banchettare con il mondo esterno! La terra sarà di nuovo devastata dalla forza del Wind Seeker!"
S["da162ca5"] = "|cffffff00La Torre del Muro Orientale è stata conquistata dall'Orda!|r"
S["da18ee73"] = "Le benedizioni di Cenarius siano con te, $C. Il nostro capo, Arch Druid Staghelm, conduce noi e tutta Teldrassil verso una vita rinnovata!"
S["da24da42"] = "Basta chiacchiere. Lasciateli venire. Ridurremo le loro ossa in polvere."
S["da2a5129"] = "Per decorare le nostre sale!"
S["da3a649f"] = "Forza e Onore!"
S["da3ecb99"] = "Oggetti antichi, armi da guerra, armature rare. Chissà cosa avrà Antonio questa settimana, se non vieni a dare un'occhiata."
S["da40d957"] = "%s saluta $N con la mano"
S["da41d6a1"] = "Perché mi hai $Gucciso:uccisa;, $N?"
S["da4716a5"] = "Ottimo lavoro, $N! Parla con me per completare la prova. Finché non lo farai, il tempo continuerà a scorrere!"
S["da4a1699"] = "La palude era orribile! Avevo così... così... paura!"
S["da561550"] = "Guarda nel calderone, $N. Marg vuole parlare..."
S["da5682d1"] = "Guerrieri, Capitani, continuate a combattere!"
S["da684b73"] = "Sempre così pessimista. Le probabilità che succeda vanno da zero a nessuna."
S["da6a1b45"] = "Temo di no, $N. Ora prova la vergogna che ti sei $Gattirato:attirata; addosso."
S["da72433f"] = "C-cosa volete? Lasciatemi in pace..."
S["da842045"] = "Ahh, \"Evocazioni Mistiche degli Arcimaghi di Dalaran\". Perfetto."
S["da846c21"] = "Degli intrusi stanno distruggendo le nostre uova! Fermi!!"
S["da87126e"] = "Sta arrivando in città la Darkmoon Faire! Non perdertela!"
S["da8da3ae"] = "Le barriere non terranno a lungo"
S["da8e53a1"] = "Il tuo messaggio ci è arrivato, Comandante, ma il nostro intervento qui non è affatto approvato dal Gran Crociato."
S["da8f8b02"] = "$GBenvenuto:Benvenuta; alla Thunderbrew Distillery! L'ha fondata il mio caro vecchio papà, Arkilus Thunderbrew, e la baracca la mando avanti io da quando mio fratello maggiore, Grimbooze, è sparito qualche raccolto fa in preda ai fumi dell'alcol."
S["da9d90cc"] = "Che i tuoi anziani ti benedicano, $N, e ti portino fortuna nell'anno che viene."
S["daa91546"] = "Ecco la parete orientale della montagna! Ora taglio verso sud; cerca di starmi dietro. Non siamo ancora fuori pericolo!"
S["daab5168"] = "Di che indicazioni hai bisogno?"
S["daabbbfe"] = "Aiutami a uccidere $N!"
S["daae7d40"] = "Frignona! Frignona!"
S["daaf6d7b"] = "Non posso scendere. Ho paura."
S["dab698ac"] = "Sì. $N. Ho trovato il Forest Lord. Dobbiamo raddoppiare gli sforzi! Servono altri cristalli!"
S["dabacf52"] = "$GUn cliente:Una cliente; fin qui? Che fortuna! Qui c'era una miniera di bottiglie vuote da alchimia, cosa un po' strana.$B$BNon ti preoccupare, le ho sciacquate."
S["dabbd42a"] = "I miei esploratori riferiscono che lo Syndicate si è stabilito in una grotta nascosta sull'altopiano orientale. Siate prudenti quando vi avventurate in quella zona."
S["dad3d0be"] = "Lo spirito dell'orso ti osserva con occhi calmi e sereni. Senti una voce rivolgersi a te come se venisse dall'orso, ma la creatura non dà alcun segno di parlare.$B$B\"Salve, $Gmio giovane amico:mia giovane amica;. Se sei $Gvenuto:venuta; a chiedermi una guida, forse posso aiutarti a trovare ciò che cerchi.\""
S["dad923f1"] = "Guarda! Laggiù, sulla parete della galleria!"
S["dada2bdf"] = "La prima armatura Dreadnaught è stata forgiata solo per lo Scarlet Highlord Mograine. Quando la indossava completa, il Gran Signore sembrava un demone uscito dalle profondità del Nether.$B$BSì, era davvero uno spettacolo vedere Mograine lanciarsi in mezzo a cento non morti dello Scourge, Ashbringer levata in alto, e uscirne dall'altra parte in una nuvola di polvere e fiamme — con i nemici ridotti in cenere ai suoi piedi."
S["dae22e88"] = "Un'elemosina per i poveri?"
S["dae6747a"] = "Conosciuti in tutte le terre, i prodotti di Antonio Perelli ora in vendita vicino al Sentinel Hill! Devo ripartire presto, quindi sbrigatevi."
S["daed3206"] = "Curioso. Un Servitore di Rastakhan che non sa che gli Hakkari non conversano nell'antica lingua?"
S["daf1c6ff"] = "Sono la mano di The Lich King!"
S["daf2e872"] = "Cercate la morte?"
S["dafce4af"] = "Il Furiere degli Stormpike tiene le sue provviste sotto una tettoia, proprio a ovest di qui."
S["dafef280"] = "Dimmi di più."
S["db001e33"] = "Thunderaan non sapeva nulla delle mosse del Firelord. Il mio Signore non ha fatto in tempo a reagire: Sulfuras, il leggendario martello di Ragnaros, ha sferrato un colpo spietato, e Thunderaan è caduto, sconfitto del tutto.$B$BIl Firelord ha banchettato con l'essenza del mio Signore, ma non è riuscito a consumarlo per intero."
S["db016c83"] = "UAAAHHH!!!"
S["db028c51"] = "$GUno stregone:Una strega;, eh... Be', se da queste parti hai in mente di fare 'ste cose, faresti meglio a tenere i demoni al guinzaglio, $Gragazzino:ragazzina;. Non mi piacciono, i demoni, però piantarci l'ascia lo adoro. Ci siamo capiti?$B$BE adesso lasciami in pace e vatti a perdere in The Forlorn Cavern. Quello stregone, Thistleheart, lo troverai lì."
S["db0a1733"] = "Ne sono caduti troppi, sacerdote. Devi concentrarti!"
S["db0e01ef"] = "%s consegna il suo zaino a Quae."
S["db0ef2f1"] = "Non sarebbe glorioso se riusciste a sconfiggermi, ma non prima che io distrugga l'unica speranza che Kalimdor possa avere? Non sto più nella pelle. Presto... Presto sarà polvere."
S["db105872"] = "Messaggio di debug, Thelrin è stato evocato."
S["db1134a6"] = "Di sicuro questo lavoro non vale sedici e cinque all'anno."
S["db2024bb"] = "Uno dopo l'altro, quasi tutti quelli coinvolti in questa faccenda sono caduti preda di questi spettri. Capirò se deciderai di tirarti indietro, $N."
S["db2e79ad"] = "È saggio da parte tua umiliarti davanti a me, $N, visto che desideri accrescere le tue conoscenze di stregone."
S["db380035"] = "Gli spiriti della foresta sono inquieti..."
S["db3d9594"] = "La casa d'aste"
S["db41070d"] = "Mamma, Jesse si è arrampicato di nuovo sulla torre del vento."
S["db5554f8"] = "Vuoi imparare a usare un'arma nuova? Cerca Sayoc e Hanashi da Arms of Legend, nella Valley of Honor."
S["db579fb2"] = "<Il cultista è morto. A guardarlo da vicino, noti che sembra stringere qualcosa al petto, come per proteggerlo.>"
S["db5aeff9"] = "Uccideteli nel nome del padrone!"
S["db5d5dbd"] = "GOOOOOOOOOOOOOLLLLLLLLLLL!"
S["db739fb4"] = "Pattugliate il Frost Dagger Pass. Non fate passare nessuno! Morite con onore..."
S["db8a85cd"] = "Zephras corre un grave pericolo. Molte migliaia di anni fa gli spiriti elementali del vento ci portarono qui, a Skywall; ora ci hanno abbandonato, e in questo regno instabile siamo vulnerabili. Un tempo la nostra società era solida e si estendeva su diversi santuari insulari nel nostro angolo di Skywall; adesso non sappiamo nemmeno se fuori da questa piccola isola siano rimasti altri shen'dorei.$B$BLa situazione è critica, ma l'High Order è deciso ad affrontare questa sfida."
S["db8cd074"] = "Stammi vicino, $N. Per evadere da qui mi servirà tutto l'aiuto possibile. Andiamo!"
S["db9287d3"] = "Dubito che tu abbia l'acume per comprendere la natura della magia dei portali."
S["dba7b6b6"] = "$GMio signore:Mia signora;, vi prego, permettetemi di vivere abbastanza da vedervi purgare questo mondo dagli infedeli."
S["dba9dcc3"] = "Ci aiuterai nell'Arathi Basin, ora che ne abbiamo tanto bisogno, $C? Non c'è mai stata un'occasione più grande per accrescere onore e prestigio, e il tuo aiuto servirà di sicuro a ribaltare le sorti contro The Defilers. Possiamo contare su di te?"
S["dbab953c"] = "Accidenti, quella Birra Scura Graffionero picchia forte!"
S["dbc8d90a"] = "Sevine, Allistarj e Grol non si sono resi conto che anche loro sarebbero rimasti legati alla terra, proprio come i loro servitori... Vedi, l'immortalità aveva un prezzo, e comprendeva anche la prigionia e la servitù eterna agli ordini di Razelikh. Ancora una volta, la crudele astuzia di Razelikh aveva vinto."
S["dbd87cd5"] = "Uccidete $N!"
S["dbd98094"] = "Uccidetelo!"
S["dbe0c6ff"] = "$GBenvenuto:Benvenuta; alla Stockade!"
S["dbe4e5ff"] = "Ho perso il Lord Valthalak's Amulet!"
S["dbe5ddcd"] = "Da questo cristallo emana un grande dolore."
S["dbe8547c"] = "Lo Snowfall Graveyard si trova in cima a una collina nel Field of Strife, a est del Winterax Hold.$B$BAl momento è controllato dall'Orda."
S["dbe923c3"] = "Ok, andiamocene di qui, svelti svelti! Cerca di starmi dietro. Io me la do a gambe."
S["dbeca34e"] = "Finalmente il siero è pronto, $N. Ora avvicinati. Dobbiamo parlare."
S["dbf116f6"] = "%s si abbevera della sofferenza dei caduti."
S["dbf4c406"] = "Spraggle! Non pensavo che sarei tornato!"
S["dbf7aac9"] = "Diamo un'occhiata alla tua attrezzatura da pesca."
S["dbfd355f"] = "Cairne ci ha portati in una terra piena di possibilità per il futuro. Siamo stati fortunati, e così, a nostra volta, dividiamo la buona sorte con gli altri. Per questo ho cominciato a insegnare, $N."
S["dc01c215"] = "$GLIBERO:LIBERA;!!!"
S["dc01cca4"] = "Ah, finalmente aria fresca! Ho bisogno di un momento per riposare, $N."
S["dc030e1d"] = "Le sabbie di Durotar sono aspre e aride, rispetto alle terre tropicali e rigogliose da dove veniamo, ma noi Darkspear teniamo duro. Il capo Vol'jin lo seguiremo ovunque ci guidi."
S["dc05dced"] = "Thurman, fratello mio, chi ride adesso? Ah!"
S["dc079a04"] = "%s colpisce in un lampo il bersaglio centrale, proprio nel mezzo..."
S["dc0cbabe"] = "Mi viene l'acquolina in bocca solo a pensarci. Il miglior cuoco di Bloodhoof Village è Pyall Silentstride. Lo troverai nella grande tenda all'angolo nord-ovest del villaggio."
S["dc14d9f4"] = "Mortali sconsiderati! Nessuno può sfidare i Figli della Fiamma Vivente!"
S["dc21b5da"] = "Allora, dove ho messo quel fossile misterioso? Ah, forse lassù..."
S["dc2efa50"] = "Non preoccuparti, ci metteremo poco! Proprio qui c'è un sentiero che scende dalla collina. Tu devi solo tenerlo libero."
S["dc34aa9c"] = "Se ti serve qualcosa in fatto di magia, qualunque cosa sia, probabilmente può darti una mano quella maghetta laggiù nell'Hall of Mysteries, Bink.$B$BL'Hall of Mysteries è appena a nord delle porte di Ironforge."
S["dc3b6fa4"] = "Dovresti andare a parlare con Winstone. Ho sentito che cerca ladri abili come te."
S["dc60c7cc"] = "Ho sentito dire che a Ironforge c'è un negozio di alchimia gestito dagli gnomi. Faresti bene ad andarci a dare un'occhiata."
S["dc63f2f9"] = "Anch'io ho i miei limiti! Se vuoi andare avanti con l'addestramento, va' a parlare con Lavinia Crowe a Undercity."
S["dc6962d5"] = "Hai uno scrigno del tesoro? Fammi vedere! Bene, trova Zando'zan nella Cleft of Shadow. Per arrivarci, cerca il tunnel che scende in The Drag."
S["dc6d30cb"] = "Mica avrai pensato di trovare un villaggio senza il suo minatore, eh? Yarr di solito sta allo Steelgrill's Depot, appena fuori da Kharanos."
S["dc6e2d07"] = "Udite, udite! Mi fermerò a vendere la mia merce qui a Lakeshire solo per poco tempo. Venite al municipio, presto!"
S["dc6e35e4"] = "Bene, credo di potercela fare da $Gsolo:sola; da qui. Non so chi tu sia... ma ti devo un favore. Grazie!"
S["dc7383e8"] = "Grazie, Divná. Anche da parte di mio fratello."
S["dc7854cb"] = "L'hai assaggiata la Thunderbrew Lager? Roba buona!"
S["dc788bca"] = "Ah, un futuro guerriero, non c'è dubbio! Immagino che tu stia partecipando alla Settimana dei Bambini, vero? Queste ossa stanche si scaldano a sapere che dai un esempio che gli altri seguiranno di sicuro.$B$BSarei $Glieto:lieta; di aiutare te e il ragazzino. Hrmm... che consiglio potrei dargli? Di ascoltare gli spiriti, sì... e magari anche due parole sul mangiare tutte le verdure..."
S["dc84670f"] = "Tower Point è sotto attacco! Se nessuno la ferma, l'Orda la distruggerà!"
S["dc87572b"] = "La fenditura si è chiusa e Krixix è sparito! Inghiottito tutto intero!$B$BTi avverto, $R, quello che desideri potrebbe benissimo diventare quello che non vuoi. Stai giocando con esseri e arcani più antichi del tempo stesso!$B$BSe Krixix fosse vivo e avesse le informazioni che cerchi, puoi stare $Gcerto:certa; che non te le darebbe. Ha affrontato orrori ben peggiori di quelli che potresti mai sognarti di infliggergli."
S["dc8978c2"] = "$N conquista la fucina! Se nessuno lo contrasta, l'Alleanza ne prenderà il controllo tra 1 minuto!"
S["dc97598f"] = "Lok'tar, $C. Ti darei volentieri l'occasione di legarti a un lupo, ma prima dovresti addestrarti con Kildar, laggiù.$B$BQueste creature sono estremamente intelligenti e non accettano chiunque. Imparare a cavalcarne uno è il primo passo, ma una volta completato l'addestramento non troverai compagno più fedele."
S["dcb1db2d"] = "Comandante, è giunto il momento di caricare quella feccia dei Frostwolf! Trafiggeteli!"
S["dcbc6236"] = "Darrowshire cadrà!"
S["dcc4ca69"] = "Che Elune sia con noi! Affrettiamoci a lasciare questa fortezza malvagia."
S["dcc50174"] = "Fai riposare un po' le ossa stanche."
S["dccae39c"] = "Aiuto! Salvatemi!"
S["dcd3a4d3"] = "I documenti come i moduli per fondare una gilda puoi averli dal Maestro di Gilda, nella città di Darnassus."
S["dcd3d7e3"] = "È buonissima questa torta, ne vuoi un po'?"
S["dcd66768"] = "Lok'tar! Sembra che tu abbia bisogno di aiuto."
S["dce0aa44"] = "%s sospira..."
S["dcf30932"] = "Elder Starglade lo troverai fuori dalle porte di Zul'Gurub, nella Stranglethorn Vale."
S["dcf3aeba"] = "Ho circa metà delle provviste necessarie per passare alle unità campioni."
S["dd011110"] = "Dicono che un punto dato in tempo ne salva... quanti, undici? Ah, non me lo ricordo. Tanto è un detto stupido."
S["dd01e73c"] = "Ci metto solo un'etichetta per riferimento, poi lo dissotterro."
S["dd047fdf"] = "Non mi pagano abbastanza per questo!"
S["dd075835"] = "Potrei avere una copia di \"The Feast of Winter Veil\" da leggere?"
S["dd0f0cbe"] = "Mangiare bene tiene in vita un soldato molto dopo che le ferite della battaglia avrebbero dovuto finirlo, $C. Se vogliamo resistere nella Guerra di Ahn'Qiraj che ci aspetta, ci serviranno tutte le provviste che riusciamo a trasportare. Io raccolgo qui lo spotted yellowtail, prima che lo spediscano.$B$BFinora ne abbiamo messo insieme una parte, ma per sfamare tutti dobbiamo arrivare al totale che ci serve."
S["dd1a1e55"] = "Se avessi delle castagne, puoi giurarci che finirebbero ad arrostire su un fuoco vivo. Mmmm!"
S["dd29682e"] = "Ora sei $Gpronto:pronta; a cercare una persona che ne sa più di me. Va' al Sun Rock Retreat, nelle Stonetalon Mountains, trova Hgarth e prosegui l'addestramento."
S["dd2e544b"] = "Alleanza! Venite presto! Abbiamo bisogno di aiuto nella Violet Citadel."
S["dd2e7d9c"] = "Sono $Gtornato:tornata; nella mia vecchia casa perché il mio sapere possa essere tramandato. A differenza di ogni mindless undead che mi circonda, ho scelto questa non vita per ragioni mie.$B$BI silithid sono avversari temibili, $N. Ho imparato a rispettarli tanto quanto li disprezzo.$B$BGran parte della loro letalità viene dalla robustezza e dalla leggerezza della loro chitina, che ho imparato a lavorare per farne armature. Visto che a quanto pare abbiamo un nemico comune, ti insegnerò il mio mestiere."
S["dd32208c"] = "Le rovine di Dire Maul sono al centro di Ferelas."
S["dd331637"] = "Apri la mente, viandante, e cominciamo."
S["dd46942b"] = "Procurarsi la Crystal Restore non è facile.$B$BCredo che venga dall'Un'Goro Crater, quindi ti conviene andare lì."
S["dd47a088"] = "Non guardare mai il Comandante dritto negli occhi."
S["dd521060"] = "Sono passati molti anni..."
S["dd533a67"] = "Ciao, $C! Sono andato in giro a chiedere, e sembra che tutti noi qui abbiamo raccolto tutto quello che serve all'Alleanza per prepararsi alla Guerra di Ahn'Qiraj. Ora dobbiamo solo spronare l'Orda a fare lo stesso, e poi potremo spedire tutto a Cenarion Hold, in Silithus."
S["dd59fc7f"] = "Dov'è finito quel cane?"
S["dd614056"] = "L'Ippogrifo è una bestia nobile, fiera e veloce. Addestrarli è un onore, e in poco tempo possono portare il cavaliere molto lontano."
S["dd6b0904"] = "Allora vai da Myolor, eh? È proprio lì... dietro di te! Ehm, forse davanti a te! Vicino alla Great Anvil!"
S["dd80bc52"] = "Certamente!"
S["dd8aa607"] = "Vieni giù al santuario con Tiev. Là metteremo all'opera la magia del sapta."
S["dd8c5608"] = "Domanda 1, Catena 2"
S["dd8e98a1"] = "Allora devi parlare con Osborne: a Stormwind non c'è un maestro delle arti furtive migliore di lui. Cercalo nell'Old Town."
S["dd90518b"] = "Maestro, devo fare pipì!"
S["dd9103cc"] = "Hai sentito? Credo che si stiano avvicinando..."
S["dd97c0d2"] = "Lo tengo qui finché non ci servirà..."
S["dd9db0c4"] = "Salve, $N! $GNuovo Campione:Nuova Campionessa; della Mischia!"
S["dda68fa9"] = "Lasciatevi sollevare dall'impresa di $N! Esultate al suo grido di battaglia!"
S["ddb7a86b"] = "Salve, $C! Le nostre scorte sono abbondanti e siamo pronti a lanciare un assalto di terra attraverso il Field of Strife. Forse, se la tua fama fosse più grande, ti affiderei la consegna degli ordini d'assalto.$B$BQuindi va' là fuori e combatti l'Alleanza! Dimostrami che sei un membro fidato e capace dell'Orda!"
S["ddc2e21b"] = "Non c'è speranza. Se ne abbatti uno, ne spuntano altri due."
S["dddadd80"] = "Seguimi, $N. Tra poco comincerò l'evocazione..."
S["dddbb4eb"] = "Affrontate il mio campione, mortali!"
S["ddddda0e"] = "Ma guarda un po' chi abbiamo qui! $GUn:Una; giovane $C scalpitante, di certo $Gattirato:attirata; dai racconti delle mie gesta sui campi di battaglia!$B$BMa adesso non c'è tempo per le storie: ci sono imprese grandi e importanti da compiere! Perciò, se cerchi gloria, oggi la fortuna ti sorride..."
S["dddfaf00"] = "Se fai tacere il baccano che hai nel cuore quel tanto che basta per sentirle, la pietra e la terra dicon il vero più di qualsiasi lingua.$B$BSe hai la stoffa di $Gun:una; $C, t'insegnerò io."
S["ddf8e19e"] = "%s prova ad aprire il Maury's Clubbed Foot..."
S["ddf92181"] = "Leggi questo tomo che ho messo davanti a te e pronuncia le parole ad alta voce."
S["ddfd4bcb"] = "Fai bei progressi, $N. Di te ho sentito parlare bene..."
S["ddff99e0"] = "Monty è 'l mio nome, e i ratti è 'l mio mestiere."
S["de0e0855"] = "Un sarto, eh? Beh, se resti qui abbastanza, prima o poi sentirai parlare di Georgio Bolero: sono mesi ormai che la moda la detta lui. Se vuoi che ti insegni, lo trovi in Mage Quarter, sull'anello esterno."
S["de15f2bf"] = "Allora! La Signora era tornata per un secondo assalto agli alveari, ma Brann di quelle sciocchezze non voleva saperne! Prima che cominciasse la mischia, lei si è messa a parlare con qualcosa, o con qualcuno. E, cosa ancora più folle, ha attaccato a cantilenare in una lingua che nessuno di noi aveva mai sentito."
S["de2262ae"] = "$GBenvenuto:Benvenuta; da Kibler's Exotic Pets! Come puoi aiutarmi, oggi??"
S["de255c83"] = "L'Alleanza ha preso la fattoria!"
S["de375fae"] = "SISSIGNORE!"
S["de41e3ed"] = "%s mescola i Bathran's Hair..."
S["de480d3c"] = "Li ricacceremo indietro, Anachronos. Questo io giuro. Tieni fede alla tua parte di questo compito. Che le tue mani non vacillino mentre sigilli i nostri destini dietro la barriera."
S["de4d5b30"] = "Il mio compito è finito!"
S["de4de577"] = "Puoi incantarmi l'ascia? La voglio con un incantamento permanente. Magari più tardi, allora. Il Godan's Runeworks è all'estremità ovest di The Drag, vicino a Valley of Wisdom: cercalo lì."
S["de5cf971"] = "$GBentornato:Bentornata; alla Great Forge, $N. Sei $Gvenuto:venuta; a trovare un vecchio Nano, o pensi di essere $Gpronto:pronta; per il prossimo passo dell'addestramento?"
S["de5e92a7"] = "Gli studi mi portano lontano da Sepulcria, ma per imparare davvero bisogna restare vicino alla fonte del sapere."
S["de617fe6"] = "Da dove cominciare? La nostra casa sta cedendo. Le protezioni sono cadute e le tre province hanno preso ad allontanarsi l'una dall'altra. Fino a poco tempo fa, dalla torre di guardia occidentale si vedevano le guglie di Shen'dramar; ora non più. E giorno dopo giorno si indeboliscono i piloni del vento che ancorano la nostra casa a questo piano..."
S["de631b35"] = "Chi osa avvicinarsi a questo calderone? Assaggia la mia lama oscura!"
S["de67fc46"] = "Non hai ancora l'abilità che serve per studiare con me. Parla con Doctor Martin Felben, laggiù, oppure sali la rampa a sud-est e va' da Doctor Marsh: sono Forsaken, e possono darti l'addestramento di cui hai bisogno."
S["de6c97ad"] = "%s continua le sue meditazioni..."
S["de6cf492"] = "Mi odi, amore mio? Sono stato costretto a distruggere la tua forma vivente, perché il tuo spirito fosse liberato da un'infelice prigionia."
S["de6cfd4f"] = "Sai che sono $Gil Comandante Supremo:la Comandante Suprema; della Might of Kalimdor."
S["de789121"] = "L'Istruttore dei Maghi, Cain Firesong, sta al piano di sopra della Gallows' End Tavern, all'estremità sud-est di Brill: lo troverai sul pianerottolo. Sarà arrivato troppo tardi per avere una stanza."
S["de7a5102"] = "Brzzzzt!$B$B$GBenvenuto:Benvenuta; nel Matrix Punchograph 3005 barra C, terminale di livello di sicurezza chi.$B$BBlue punch card rilevata. Accesso Consentito.$B$B01000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 00100001"
S["de7a8146"] = "Dacci dentro, ragazza. Lavoro duro e determinazione — così si fa! E lascia perdere chi ti dice che basta studiare sui libri."
S["de7c7b09"] = "Non conosco questo Eye of the Tiger di cui parlano alcuni, ma posso mostrarti come usare gli artigli della tigre."
S["de8178bb"] = "Sei qui per imparare? Va bene. Se ti addestro, suppongo che ai nostri alleati non potrai fare molto male. Basta che tu riesca davvero a farne ai nostri nemici."
S["de8b9406"] = "L'Alleanza ha preso la miniera!"
S["de957dd4"] = "Stormwind è il pilastro della razza umana: a reggerlo sono la forza di volontà e il filo di una lama robusta."
S["de9631f8"] = "Quindi Hakkar è tornato?"
S["de9c0966"] = "Vedo sofferenza infinita. Vedo tormento. Vedo rabbia. Vedo tutto..."
S["de9f172e"] = "Gnomeregan si trova nella parte ovest di Dun Morogh."
S["dea0c95c"] = "%s comincia a ballare."
S["dea243cf"] = "%s consegna il messaggio ad Apothecary Zamah."
S["deb277b9"] = "Forse avremo un momento per riposare. Ma non mi arrenderò finché non avremo affrontato Vorsha!"
S["deb3f563"] = "Qualche anno fa i banditi hanno attaccato la nostra fattoria. Si sono presi tutto quello che avevamo e mi hanno lasciato pesto e sanguinante. La stagione dopo, più o meno nello stesso periodo, sono tornati."
S["deb6a741"] = "Uno dei Cristalli Ash'ari è stato distrutto! Uccidete gli intrusi!"
S["debf436b"] = "Ottimo! Continuate a portare quei rifornimenti, gente!"
S["dec7279d"] = "Grazie per il barile di alcol, $N. Credo che aprirò subito una bottiglia!"
S["dec9dfba"] = "Ti serve addestramento nelle vie della luce?"
S["ded1a7fb"] = "Nessuno ti salverà adesso, $Gumano:umana;!"
S["ded44e82"] = "Piccolo forsaken conosce tutte armi. Lui Archibald. Tu trovi lui su anello interno di War Quarter."
S["ded90d27"] = "Gli agenti del Cenarion Circle hanno scoperto informazioni inquietanti su quello che sta succedendo ora a Eldre'Thalas. Sono a un punto morto e non so cosa fare: di sicuro presto cercherò l'aiuto di esseri forti e capaci di cavarsela in combattimento.$B$BMa per agire come si deve a Eldre'Thalas bisogna conoscere la storia di un oggetto noto come il Frutto della Fertilità."
S["dedf6246"] = "$N ha catturato l'Horde Flag!"
S["dedfc389"] = "Lok-tar, Walton."
S["dee508d4"] = "Noi pensa che tu serve aiuto."
S["deed6ee9"] = "Le Stormwind Stockades le trovi a Stormwind, vicino al quartiere dei maghi."
S["def438c9"] = "Continua, per favore."
S["df0d892d"] = "%s comincia a scavare..."
S["df12fbe0"] = "Non lo vedi che sono $Goccupato:occupata;? Va' a nord per la strada fino a Orgrimmar e chiedi a uno dei grunt di lì. Non puoi sbagliarti."
S["df15647e"] = "Tark, cos'è successo là dentro? Tu lo sai che sei meglio di così! Squadra blu, presto avrete quel che vi spetta, eh!"
S["df17241d"] = "Noi tanto più puliti di ogres in Tanaris. Per tutto deserto, fin dove arriva occhio — cacca di ogre. Qui no, no signore!"
S["df18d2d3"] = "Datti una calmata!$B$B<Bodley borbotta sottovoce qualcosa sull'impazienza dei vivi>$B$BDicevo: lo spirito di Lord Valthalak e gli spectral assassins che aveva evocato dilettandosi di negromanzia hanno cominciato ad assalirci. Te lo dico io, a quel punto non eravamo in condizione di reagire, e siamo scappati. Mi ricordo ancora di Mor Grayhoof, uno dei nostri druidi, che a un certo punto è scivolato ed è caduto giù, nella parte più bassa della guglia.$B$BIl resto, come si dice, è storia."
S["df1c99d6"] = "Harroc, prendi una cassetta degli attrezzi per $N."
S["df20fa31"] = "Bene, Razziatori! Sono arrivati gli ordini! In battaglia!"
S["df22d91b"] = "Prima di tagliare il cuoio, ricontrolla sempre le misure: non possiamo permetterci di sprecare materiali."
S["df235e06"] = "Non preoccupatevi per me! Uccidete questa bestia orribile e purificate il mondo dalla sua lordura!"
S["df2591bd"] = "A volte penso che lassù in cielo ci sia una grossa nuvola grigia che ci fa piovere addosso solo sfortuna. Prima ci hanno cacciati dalla nostra terra, e adesso non riusciamo neanche ad andarcene da Westfall. È un disastro. Bisogna fare qualcosa."
S["df27fae2"] = "Ilifar, il tuo padrone ti chiama!"
S["df282e2b"] = "Ti ringrazio per avermi portato le rassicurazioni di Ayessa. Con l'High Order e i Windshapers che lavorano con noi contro la minaccia più grande, abbiamo molte più possibilità di fermare gli Al'Aketh e qualunque cosa abbiano in mente per Zephras."
S["df33a9ef"] = "Il resto della strada posso farlo da solo. Fa' sapere a Shari Stilwell che sono al sicuro. Prima, però, ho una piccola faccenda da sbrigare."
S["df428fe6"] = "Quindi avevo ragione sulle energie. Vediamo cosa dice l'altro tomo in proposito."
S["df456adb"] = "Ti stai godendo la festa, $C? La mia merce può dare una marcia in più alla tua giornata. Non c'è niente di meglio di cibo caldo e bevande calde!$B$BE se non l'hai ancora fatto, chiama un amico o due e festeggia intorno al palo dei nastri: ti tirerà su il morale di sicuro!"
S["df5c8369"] = "$GBenvenuto:Benvenuta; al Cenarion Circle, $C. Cosa posso fare per te?"
S["df5d0ce4"] = "Arriva un momento in cui la vita che conosciamo non ci basta più. Siamo in trappola, cerchiamo risposte, e nei luoghi oscuri troviamo la speranza che arde.$B$BSolo allora, $N, muoviamo i primi passi verso la libertà."
S["df5f1487"] = "Uno stregone? Be', se fossi $Guno stregone:una stregona;, probabilmente me ne starei nel posto più buio da queste parti... cioè la cantina della Lion's Pride Inn. Dovresti cominciare a cercare da lì."
S["df65e701"] = "La figura spettrale ti guarda con sospetto e resta in silenzio."
S["df6cdd83"] = "Hai rovinato le tue terre, non rovinerai le mie."
S["df72b9bd"] = "Flagello nelle fogne! Ci serve aiuto!"
S["df72e9ab"] = "E pensare che un giorno potresti essere proprio tu $Gquello:quella; di cui parlano le leggende!"
S["df737436"] = "Grazie, $N. Ti ricorderò per sempre. Troverai il mio forziere nel mio accampamento, a nord di Stonard."
S["df77dc16"] = "Ysida è viva grazie al tuo coraggio, $N. Ti sono profondamente $Gdebitore:debitrice; e ti aiuterò per quanto è in mio potere."
S["df7b285a"] = "%s nota le tue vigliacche tattiche di battaglia e fugge dallo scontro."
S["df805d71"] = "%s resta $Gammutolito:ammutolita; davanti alla Soul Gem!"
S["df81f7c1"] = "Elune ha ritenuto giusto donarmi abilità ed esperienza. Ora io le tramanderò a te."
S["df86eb61"] = "Clemens, Bartholemew, Enderman, Wyles..."
S["df87f6fd"] = "Questo sembra il posto perfetto per un pisolino..."
S["df8a3805"] = "Mi servono molti altri rifornimenti per migliorare le nostre unità."
S["df8ef8c8"] = "La cassetta di sicurezza del SI:7 comincia a vibrare e a ronzare. Si sente un forte fruscio provenire da nord."
S["df9ee7c1"] = "Ecco fatto! Il Re dovrebbe esserne molto soddisfatto, se posso dirlo."
S["dfc3e7bb"] = "Bella canzone, vero?"
S["dfcfe1dc"] = "%s fissa verso nordovest ed emette un lungo, lento ululato."
S["dfd86f9b"] = "Pelli di cuoio? Sì, mi sono appena arrivate notizie in proposito. Pare che l'Orda abbia raccolto una parte dell'heavy leather che serve, e anche una parte del thick leather e del rugged leather richiesti."
S["dfe9e4ba"] = "<Su questa pergamena c'è disegnato lo schema di un robot per le riparazioni sul campo.>"
S["dfea518b"] = "Ecco! La Taverna Azzurra dà un banchetto in suo onore!"
S["dfefcd34"] = "Siete tornati a finire il lavoro? <Lathoric ride.> Obsidion, sorgi e annientali!"
S["dff52943"] = "Porta questo registro a Tanaris, a un mio vecchio conoscente. Si chiama Narain Soothfancy — come sensitivo è pessimo, davvero pessimo, ma come ingegnere è straordinario! Dovrebbe riuscire a venirne a capo.$B$BNon serve che mi ringrazi, $N. È il minimo che potessi fare.$B$BBuona giornata!"
S["dff9337b"] = "Non sveglierete mai il sognatore!"
S["dffbb68b"] = "Ciao. Mi chiamo Gubber Blump."
S["e00879ca"] = "Fuori... da Zephras? Dalle altre province? Non abbiamo contatti con le altre isole da anni...?"
S["e0126ca9"] = "Il vincitore della gara ce l'abbiamo già, ma Jang è disposta a comprarti tutti i Tastyfish che hai pescato!$B$BLa tua abilità nella Pesca potrai sempre mostrarla domenica prossima!"
S["e01770b6"] = "Se devo insegnarti i segreti per evocare un infernal servant, prima devi distruggere Kroshius e portarmi il nucleo infernale preso dai suoi resti ardenti. Ma non è facile come sembra: Kroshius si è quasi spento del tutto. Devi riaccendergli il cadavere e farlo risorgere dalle macerie, e per riuscirci dovrai raccogliere alcuni componenti da altre entità demoniache.$B$BIl mio imp, Impsy, ti indicherà la strada."
S["e01bbd75"] = "Oh oh... qui si mette male."
S["e01c83a2"] = "Dovete salvarlo!"
S["e0299a8e"] = "Ah, Ysera the Dreamer."
S["e02c08d7"] = "Le giovani razze? I bambini? Umani? Orchi? Nani? Pensi di sconfiggere gli Hakkari? Di distruggere un DIO?"
S["e030b47f"] = "<Gli schemi sono troppo complicati per le tue scarse doti di ingegneria.>"
S["e03ca603"] = "Purtroppo, anche questo istante durerà solo un battito di ciglia... I legami che mi trattengono in questo mondo si indeboliscono e mi trascinano via..."
S["e044554f"] = "Chi osa intralciare i Sons of Arugal?"
S["e0569c77"] = "Fase 3! <PH>"
S["e05c0962"] = "Là fuori, nel buio, si nascondono molte cose, e ora più che mai c'è bisogno di luce. Se solo queste povere anime capissero che il nostro mondo è cambiato, sì, ma non per questo dobbiamo essere i mostri che i vivi vedono in noi."
S["e05eca12"] = "Come vanno i tuoi viaggi, $N? YOUR_GENDER(Sumi e Tumi hanno sentito la tua mancanza, dovresti salutarle dopo la lezione;Ho sentito i racconti delle tue avventure, a quanto pare sei stata molto impegnata). Ora vediamo cosa hai imparato mentre eri via."
S["e06b8a8e"] = "Mi rincresce, nobile signore, ma non posso aiutarti finché non avrai imparato di più sulla lavorazione del cuoio. Rivolgiti piuttosto a Faldron o a Darianna, qui: loro possono insegnarti l'abilità che ti serve."
S["e06cd898"] = "Dimmi di più sulla Forgiatura di Armi."
S["e06d36f7"] = "La Locanda è sul lato est della strada che esce dalla città verso nord."
S["e06f0560"] = "Grazie, vecchio amico. Hai fatto la cosa giusta."
S["e0768e96"] = "Yonn Deepcut è dentro la grande tenda, nell'angolo nord-ovest di Bloodhoof Village."
S["e07b0b5c"] = "$N ha assaltato la fattoria!"
S["e07b4623"] = "Krathok, un tempo ero $Gun forgiatore:una forgiatrice; di armature e ora vorrei invece imparare la via del forgiatore di armi. Mi addestrerai?"
S["e07d086f"] = "Malorne, chissà come, riesce a raccogliere le erbe più delicate senza rovinarle. Di sicuro è da lui che dovresti imparare. Abita appena a est della Locanda di Dolanaar."
S["e080c98a"] = "Ci siamo, Impsy. Lo sento! È la volta buona!"
S["e08ee9b7"] = "Il diario di Jandice Barov è pieno di sproloqui e farneticazioni sui non morti. Verso la fine c'è quello che sembra uno schema di sartoria per creare una specie di borsa, ma di sartoria non ne sai abbastanza per decifrarlo."
S["e092f9b8"] = "Nessuno può resistere ai Signori dei Serpenti!"
S["e0935c24"] = "Non dirmelo! Shhh! Sei qui per The Ashbringer?!? Sì... Sì... No! Ho sbagliato.$B$BCosa posso fare per te, $R?"
S["e098c2b9"] = "Saluti, giovane $C."
S["e09e0743"] = "Si vede che il tuo guardaroba ha un disperato bisogno di cure."
S["e0a56173"] = "Questo non me l'aspettavo. Conosco l'essere che ha incantato questo oggetto..."
S["e0aa8ac3"] = "Elder Windrun abita nella Crown Guard Tower, nelle Eastern Plaguelands."
S["e0ac0159"] = "Ah, mantenere l'ordine qui è già difficile senza tutti questi guai nuovi che saltano fuori! Spero che tu abbia buone notizie, $N..."
S["e0afa2bc"] = "Lassù vive Charlga Razorflank. Maledetta vecchia megera."
S["e0b1d150"] = "Voi stranieri pagherete per aver invaso la nostra terra!"
S["e0b33917"] = "Le mie cavalcature le metto a disposizione solo di chi Orgrimmar e la razza degli orchi considerano osannato. Va' a dimostrarci quanto vali, e ti lascerò esaminare i miei possenti lupi."
S["e0b345cd"] = "Grazie, mio signore. Farò buon uso del tempo."
S["e0c9f636"] = "È stato un semplice errore. Ho sbagliato strada, te lo giuro!"
S["e0d02976"] = "Che istruttore di classe cerchi?"
S["e0d5d2af"] = "Non sei male, ma lascia che ti mostri qualche trucco che potrebbe farti comodo."
S["e0db7ee7"] = "Non sbaglio mai un colpo..."
S["e0e10554"] = "Noi elfi abbiamo alle spalle una lunga storia. Speriamo che non torni a perseguitarci."
S["e0e142df"] = "$N ha assaltato la miniera!"
S["e0e517b4"] = "Sei il re dei Gordok! Il numero uno sei tu!"
S["e0e8618e"] = "Parlami dei cimiteri."
S["e0eb183b"] = "Ce l'avevo... quasi... fatta."
S["e0f17ebd"] = "Sono un BOT. Ho tantissime informazioni. Per sapere cosa so, mandami un sussurro."
S["e0f52107"] = "L'Alleanza ha raccolto risorse ed è vicina alla vittoria!"
S["e0fa3ddf"] = "%s tiene la Rune of Escape davanti a sé."
S["e105d71d"] = "Venite in aiuto del Trono!"
S["e107cd28"] = "L'ago è piccolo, ma il filo è robusto e i punti sono fini. Il nostro patto con Thrall e gli altri reggerà, e nessuno caccerà l'Orda da queste terre."
S["e10b40be"] = "Ci serve un gran numero di copper bars, $C. La guerra che sta per scoppiare ad Ahn'Qiraj consumerà un sacco di metallo per armi, armature e via dicendo. Mi dicono che solo l'Orda deve raccogliere una montagna di copper bars. Per ora ne abbiamo solo una parte."
S["e11809a4"] = "Sii $Gsaldo:salda;, $Gcampione:campionessa;. So perché sei qui e so cosa cerchi. Eranikus non cederà il frammento di sua volontà. È stato corrotto... corrotto dalla stessa forza che cerchi di distruggere."
S["e123205c"] = "Secondo me c'è una probabilità su un milione di ottenere un pezzo così! Una pelle che capita una volta nella vita! Anche gli artigiani più disciplinati del mestiere, nello scuoiare la bestia, fallirebbero di sicuro centinaia di volte prima di ricavarne un esemplare intatto."
S["e124e328"] = "Quando ti troverai nel porto di Valanaar, cerca Ayessa Cantalba. Lei potrà dirti di più."
S["e1269dad"] = "Oh, che orrore! Che tragedia! Siamo a un passo da una scoperta, eppure rischiamo di perdere tutto."
S["e12a4bf3"] = "Quante altre provviste ci servono?"
S["e12f159b"] = "Mi sento $Gstanco:stanca;...$B$BDa qui si vedono le cascate, $N... Con lo scettro puoi arrivare fin qui, se mai volessi rientrare dai cancelli principali di Maraudon.$B$BVicino all'ingresso di Maraudon c'è un passaggio che scende sotto le caverne. Usa lo scettro nell'antico luogo del rituale per aprire un portale, e ti ritroverai qui ancora una volta."
S["e1340b98"] = "%s attacca il luccio!"
S["e13c1dd2"] = "Ben fatto! Da qui dovrei cavarmela da solo. Ricorda di parlare con Delgren quando torni a Maestra's Post, ad Ashenvale."
S["e13cffcf"] = "Il porta-che? Ah, BRANDICENERE? Mai sentito... Cosa? Smettila di seccarmi!"
S["e14ab28f"] = "Vuoi imparare la conciatura, eh? Potrebbe insegnartela Simon Tanner, che trovi nell'Old Town, alla Protective Hide."
S["e14f3f65"] = "%s comincia a salmodiare uno strano incantesimo..."
S["e1539e18"] = "Sei qui per imparare qualcosa sulle pozioni? Ho molto da insegnarti. Sarò anche morta, ma il cervello non l'ho perso. Non ancora."
S["e16b2e4f"] = "Ve lo dico io, gente, quella foresta è infestata! Ho VISTO *hic* QUELLO CHE HO VISTO!"
S["e16e13d6"] = "Mi fa piacere che tu me lo chieda. Con i Biglietti Premio della Darkmoon Faire ti diamo modo di dare una mano alla fiera, e in cambio puoi consegnarli per avere premi speciali!$B$BPer cominciare, parla con Chronos, Kerri Hicks, Ringling e Yebb Nebblegear e scopri a chi puoi essere più utile. Hanno sempre qualcosa da fare per migliorare e ampliare le nostre attrazioni.$B$BPoi, quando avrai abbastanza biglietti, va' da Gelvas Grimegate: ti darà un elenco di premi fra cui scegliere."
S["e17117d8"] = "Ho visto un troll, un certo Lau'Tiki, che pescava giù a sud, sulla Darkspear Strand. È appena fuori da Sen'jin Village."
S["e178e31d"] = "Si chiama Rupert Boch. Mi hanno detto che sta al piano di sopra della Gallows' End Tavern, all'estremità sud-est della città, in una delle stanze."
S["e1799894"] = "Schiena dritta! La tua debolezza mi disgusta!"
S["e17aeefe"] = "Perché dovrei andarci piano, se funziona?"
S["e18595b5"] = "%s è $Gcircondato:circondata; da una barriera antimagia."
S["e18f7b35"] = "Non abbiamo quasi nessun rifornimento in più. Ci vorrà molto altro lavoro prima di essere pronti a lanciare un altro assalto di terra nel Field of Strife."
S["e1901a57"] = "L'Icewing Bunker presidia il passo tra il territorio dell'Alleanza e il Field of Strife.$B$BÈ controllato dall'Alleanza."
S["e19b4a60"] = "La Frostwolf Relief Hut si trova nella Frostwolf Keep, a sud delle Frostwolf Towers.$B$BAl momento è controllata dall'Alleanza."
S["e1a10219"] = "Soffrirai in questa sconfitta, Nefarian!"
S["e1a10e82"] = "Mi hai disturbato per questo? Piuttosto che indossare quella schifezza, faresti meglio a legarti un coniglio morto sulla schiena e correre nella tana di un Troll."
S["e1aa3bf9"] = "I Paragoni del Potere sono quel che resta dell'antico Gurubashi Empire. Noi Zandalar li cerchiamo — non solo per noi valgono tantissimo come pezzi da collezione, ma crediamo pure che racchiudano il mojo più potente che usava il vecchio Impero.$B$BA Zul'Gurub puoi aspettarti di trovare tre tipi di Paragoni: monete, bijous e oggetti primordiali. Portaceli nelle quantità che vogliamo e sarai $Gricompensato:ricompensata; con alcuni degli oggetti migliori mai creati da noi Zandalar.$B$BContaci, mon!"
S["e1ab996f"] = "L'Irondeep Mine si trova nel territorio dell'Alleanza, a nord dello Stormpike Graveyard.$B$BÈ controllata dai Troggs."
S["e1bab19b"] = "%s ruggisce una sfida a $N!"
S["e1c042bb"] = "Lo sai perché gli occhi degli orchi brillano di rosso? Perché bevono sangue!"
S["e1c2869f"] = "Se dentro di te c'è la capacità di imparare, sarei onorato di addestrarti all'uso delle armi che padroneggio."
S["e1c72f8a"] = "Ah, Ner'zhul. Non è un nome da pronunciare alla leggera, ma ti avevo chiesto una risposta.$B$BE Ner'zhul è quella giusta."
S["e1c993f9"] = "Prendi uno sgabello e bevi qualcosa!"
S["e1cb123d"] = "Elementium? Sono decenni che non sento questa parola uscire dalla bocca di un mortale."
S["e1cb67ea"] = "Dov'è la chiave di questa serratura?"
S["e1cfe039"] = "La raccolta dell'Orda è completata, $C. Ora aspettiamo il momento giusto con altri preparativi, mentre l'Alleanza finisce le sue raccolte per la guerra."
S["e1d097a1"] = "Avete sconfitto i miei servitori? Allora affrontate me, mortali!"
S["e1d3d210"] = "Salute, $C. Come forse sai, abbiamo completato tutte le raccolte necessarie per il ruolo dell'Alleanza nella guerra imminente. Ora tocca all'Orda finire le sue, e poi partiremo per Silithus."
S["e1d4158d"] = "Aprila."
S["e1e06118"] = "%s macina le perle che $N gli ha dato..."
S["e1e3430f"] = "...Sampson, Yorick, Chamley..."
S["e1e67ab7"] = "Vuoi lo scontro? E scontro avrai!"
S["e1ecc54d"] = "C'è qualcosa che non va nel Gran Signore. Fate qualcosa!"
S["e1f2ebd9"] = "Il Ragefire Chasm è una rete di caverne vulcaniche sotto Orgrimmar, la nuova capitale degli orchi. Ultimamente si dice in giro che un culto fedele al demoniaco Shadow Council si sia insediato nelle profondità infuocate della Chasm. Questo culto, conosciuto come Burning Blade, minaccia la sovranità stessa di Durotar. Molti credono che l'orco Warchief Thrall sappia della Blade e abbia scelto di non distruggerla, sperando che siano proprio i suoi membri a portarlo dritto allo Shadow Council."
S["e1f47251"] = "Il Frostwolf Graveyard è sotto attacco! Se nessuno lo ferma, l'Alleanza lo conquisterà!"
S["e1fb00cc"] = "L'infestazione dello Scourge cresce nelle Blasted Lands. Serve ogni guerriero abile per arginare la loro invasione.$B$BNecropoli rimaste: $2280W"
S["e209eeb2"] = "OH NOOO!! TORNO SUBITO COME DRAGO! <PH>"
S["e20ad1e1"] = "Quello là, Malagan. $GLo:La; conosco. $GAffidabile, coraggioso e degno di fiducia:Affidabile, coraggiosa e degna di fiducia;. Si chiama $N."
S["e20afd74"] = "Il suo luogotenente, Ilkrud Magthrull, possiede un tomo che potrebbe indicare dove si trovano le gemme dell'anima rimaste."
S["e20b8640"] = "Il viaggio a volte può essere movimentato, è consigliabile tenersi saldi a qualcosa quando si viaggia tra i piani d'esistenza."
S["e20ca4e6"] = "$GAttento:Attenta; a dove metti i piedi..."
S["e2118dde"] = "Tu... sei $Gil prossimo:la prossima;."
S["e225e180"] = "Ci sono 40 gradi Kraklenheit. Senti il caldo? No? Neanch'io, in effetti."
S["e22707f1"] = "Mi deludete, allievi!"
S["e234fbca"] = "Ahimè, a quanto pare è sempre così. Io — come il resto del Cenarion Circle — davo per scontato che la creazione di Milli fosse andata distrutta durante la War of the Ancients. E invece ho scoperto che le cose stanno ben diversamente.$B$BIl Frutto della Fertilità è sopravvissuto... anche se oggi lo chiamano Vite Vile. Lo sta corrompendo il signore demoniaco di quella parte di Eldre'Thalas, Alzzin the Wildshaper."
S["e2357d11"] = "%s va su tutte le furie dopo aver visto cadere in battaglia un compagno!"
S["e245c8bf"] = "Il Blu è il Vincitore! Congratulazioni, Blu!"
S["e24b7456"] = "Ora che il generale dei Frostwolf è stato sconfitto, possiamo distogliere alcune truppe per sorvegliare l'ingresso del Winterax Hold.$B$BMa state all'erta! Dobbiamo sempre stare in guardia contro gli intrusi dell'Orda."
S["e24f7896"] = "%s lancia un grido di battaglia!"
S["e2514075"] = "Però così si sbilancia il focus magico, e si crea una vibrazione inversa nell'etere."
S["e25749be"] = "Dall'interno della pietra si leva una voce chiara...$B$BDov'è il tuo Medaglione di Rango, $Gpiccolo:piccola;? Senza una prova del tuo titolo non puoi parlare con un Duca..."
S["e257bc78"] = "Sono venuto al Crossroads dal sud a cercare aiuto, $C, e trovo solo codardi che mi voltano le spalle — persino il potente Thork mi insulta così. È un buon capo, ma a respingere la mia supplica non fa che farmi infuriare ancora di più.$B$BDice che la rabbia mi rende avventato — che mi annebbia il giudizio — ma non mi darò pace finché non avrò vendetta!"
S["e25ab7c1"] = "Ah! Ecco la mia chiave a cricchetto! Ora riattacchiamo questi frammenti di pergamena."
S["e25ab7d9"] = "Vedi questo? Questo è il mio bastone che fa bum! Il top della gamma dei nani. Proprio così, questo gioiellino è stato fatto a Ironforge, Khaz Modan. Al dettaglio costa circa centonove monete d'oro e novantacinque di rame. Ha il calcio in noce, l'acciaio al torio e lo scatto a pelo."
S["e25f8f3a"] = "Ahh... cibo. Era ora."
S["e26624b4"] = "L'infestazione dello Scourge cresce ad Azshara. Serve ogni guerriero abile per arginare la loro invasione.$B$BNecropoli rimaste: $2279W"
S["e269118a"] = "Cerco di tenere Sentinel Hill ben rifornita, e con tutti gli scontri che ci sono non è facile."
S["e2708376"] = "Per Darrowshire!"
S["e274d281"] = "Se dai i love tokens agli abitanti della città, in cambio ricevi doni diversi. Alcuni vorrai tenerli per usarli, altri invece puoi metterli insieme e regalarli al tuo eroe preferito! Per consegnarli, vai da Kwee Q. Peddlefeet.$B$BKwee sta vicino a Cairne, Sylvanas e Thrall."
S["e277e7ea"] = "Ti prego, $N, lascia questo luogo. Di ciò che ci affligge non sai nulla..."
S["e287982f"] = "Ecco cos'è successo: dopo, ci siamo separati. Troppo rancore, credo... cresceva da un po'. E la faccenda dell'amuleto è stata la goccia che ha fatto traboccare il vaso.$B$BDa allora i servitori di Valthalak ci fanno fuori uno dopo l'altro. Quasi tutti quelli che avevano un pezzo dell'amuleto sono morti, con l'anima corrotta dalla parte dello spirito di Valthalak chiusa al suo interno.$B$BPer questo sono $Gcontento:contenta; che tu sia qui, $N. Con il tuo aiuto potremo ricomporre l'amuleto e restituirlo a Lord Valthalak!"
S["e28a9dff"] = "Lysta, fai entrare i prigionieri."
S["e28ab84b"] = "Quando impareranno?"
S["e290fb0a"] = "Non vale la pena rispondere."
S["e293d462"] = "Per lo più, sì. Quello che ci accomuna tutti è che non abbiamo nessun altro posto dove andare, e che piuttosto che farci schiavi di qualche culto di pazzi preferiamo rubare."
S["e295863a"] = "E va bene! Mi avete battuto con la logica, voi maestri di Ingegneria! Mettete la porta dove volete!"
S["e2981e99"] = "Potrete anche avere successo sul campo di battaglia per un po'... ma non potete sperare di vincere contro lo Scourge!"
S["e29c20d1"] = "Vuoi imparare il mestiere di conciatore?"
S["e29f8f1e"] = "Jeztor sta venendo a prendervi, Stormpike!"
S["e2a1cab0"] = "Vado a mettere al sicuro il piano di sotto."
S["e2a56c97"] = "La Might of Kalimdor fermerà le loro avanzate!"
S["e2ae744f"] = "Ho deluso la Dama Oscura. Ma non accadrà più."
S["e2b0d724"] = "La Royal Apothecary Society ha poca pazienza con gli sciocchi, e io lo stesso. Forse, la prossima volta che parleremo dei miei destrieri, Undercity ti considererà $Gosannato:osannata;. Fino ad allora..."
S["e2b170d9"] = "$GBenvenuto:Benvenuta; alla Bank of Darnassus. Da noi trovi conti e cassette di sicurezza per gli oggetti di valore. Hai già un conto, $Gsignore:signora;?"
S["e2c384ee"] = "Ne so parecchio, ma esperto non sono. Sai chi dovresti sentire? Rhiannon! Non sta lontano: chiedi di lei in giro per Undercity"
S["e2c90b2a"] = "%s ride."
S["e2cac2ae"] = "Avventurieri da ogni dove vendono merce ad Antonio — venite a vedere con i vostri occhi quali piccoli tesori ha per voi questa settimana."
S["e2d12427"] = "Il grande santuario l'hanno costruito molti anni fa gli elfi della notte che un tempo vivevano in questa terra.$B$BQuali segreti custodirà?"
S["e2d9097f"] = "UAAH! Ehm, fila in prima linea!"
S["e2ea984f"] = "Fa così male... Itharius, mio vecchio amico... ti prego, aiutami..."
S["e2f6441e"] = "Ce l'abbiamo fatta! Quae, ce l'abbiamo fatta!"
S["e2fe1151"] = "Mio padre l'ha ucciso la feccia che abita il calderone. Ho chiesto aiuto al magistrato di Stormwind, ma le mie richieste sono cadute nel vuoto. Anzi, lì non vogliono nemmeno ammettere che questa parte del mondo esista, figuriamoci mandare qui il loro prezioso esercito a fare giustizia.$B$BCerco vendetta, $R, né più né meno. Esiste in questo mondo una causa più appassionata?"
S["e2fe26b0"] = "E i Tastyfish se ne sono andati per questa settimana! Resterò ancora un'ora per permetterti di consegnare i tuoi pesci!"
S["e3003c90"] = "È tutta colpa loro, di quegli stupidi orchi. Dovevano proprio radere al suolo la mia fattoria."
S["e302dca6"] = "SQUAAK!! *coff* *coff* Devo smettere di fumare!"
S["e3047daa"] = "Non sei un po' $Gbasso:bassa; per la tua specie?"
S["e3105f84"] = "A forza di litigare non andremo da nessuna parte. Bisogna agire."
S["e314f987"] = "A Stormwind ci sarà senz'altro uno gnomo in grado di insegnarti la professione. Sono $Gsicuro:sicura; che una delle Stormwind Guards potrà indicarti la strada giusta."
S["e31d3ee8"] = "Ultimamente gli ordini persi sono aumentati di colpo. Facciamo di tutto perché ogni consegna arrivi in modo efficiente e sicuro, ma ora che banditi, creature turbolente e quei dannati dell'Alleanza sono sempre di più, è inevitabile che qualche consegna non vada come previsto.$B$BSe trovi queste spedizioni, guarda l'etichetta per vedere cosa dovrebbero contenere. Rimediare ai nostri errori non tocca a te, ma se completi la spedizione sarai $Gricompensato:ricompensata; a dovere.$B$BDokimi, laggiù vicino al carro, può pensare alla logistica e al tuo compenso. Da lì in poi ce ne occupiamo noi."
S["e31ebe5a"] = "La Gallows' End Tavern è all'estremità sud-est della città. Vai lì e sali al piano di sopra: nella sala di lettura troverai Dark Cleric Beryl."
S["e327410f"] = "$N! Preparati ad affrontare il tuo destino!"
S["e33f4084"] = "Impossibile! Fermate l'attacco, mortali... Mi arrendo! Mi arrendo!"
S["e33f77c5"] = "Arrrgh! Qui qualcosa non va!"
S["e3429e37"] = "La Stormwind Counting House è vicino ai cancelli d'ingresso, nel Trade District of Stormwind. E quando ti sarai $Gstancato:stancata; di contare i soldi, passa alla Gilded Rose a bere qualcosa."
S["e346166b"] = "Le spire della morte vi stritoleranno!"
S["e34bdf29"] = "Wushoolay, the Storm Witch.$B$BIl suo è il potere del cielo, della pioggia e della terra frantumata. Possa regnare di nuovo come madre dei Gurubashi.$B$BOra Wushoolay infuria sull'orlo della follia."
S["e3512ef7"] = "Questo è Dalin Forgewright. Fuggì da Lordaeron quando colpì la pestilenza, portando con sé la sua amata."
S["e35c4a75"] = "Fuoco. FUOCO! BRUUUCIA!"
S["e360231a"] = "Io... sono... disfatto."
S["e3664ffd"] = "Och! Sta' $Gattento:attenta; a cosa ti fai incantare, $Gragazzo:ragazza;. Ho fatto incantare il boccale perché non ne cadesse una goccia, e adesso non riesco a berci! Che tragedia.$B$BE mi raccomando, quando vai da Gimble ricordati il mio consiglio. Lo trovi nella sua bottega, proprio accanto al Maestro dei Grifoni di The Great Forge."
S["e367005e"] = "Assaggiate il mio potere!"
S["e369122e"] = "Forse posso insegnarti qualcosa..."
S["e3717433"] = "I nostri esploratori hanno riferito che è probabile che molto presto i Silithid tentino di spazzare via questo avamposto."
S["e3839966"] = "Soffrirai in eterno, $R."
S["e38516de"] = "Lo Stormwind Harbor, dove sta la nostra possente flotta, si trova tra il Cathedral District e The Park.$B$BCercavi un posto in particolare?"
S["e3931e25"] = "%s emerge dal terreno!"
S["e39b1e59"] = "Quante battaglie abbiamo vinto?"
S["e39f36ad"] = "<Mivin indica la sua merce e poi torna a guardarti con un sorriso, ma non dice nulla.>"
S["e3a9b6a0"] = "Pare che Zarrin conosca bene il mestiere della cucina. Perché non vai a vedere se ti mostra qualche ricetta? Di solito sta ai fornelli vicino alla Locanda di Dolanaar."
S["e3ae2912"] = "Osate interrompere la nostra preghiera? Giustiziateli!"
S["e3b3483e"] = "Dovrai portare un po' di pazienza con me, $N. Là dentro c'è il mio Spybot che lavora a una faccenda molto delicata. Tra un attimo sono da te.$B$BAh, e fammi un favore, cerca di non farti vedere da Lescovar... gli stiamo per tendere un'imboscata."
S["e3b3cb6c"] = "Tradirai i tuoi amici."
S["e3b3e5a2"] = "Molti ritengono il bastone un'arma inferiore. Sfido chiunque la pensi così a mettere alla prova la propria forza contro il mio bastone."
S["e3b70f8f"] = "Ah, il bel Menethil Harbor, col miglior idromele da questa parte di Ironforge."
S["e3c9ccdb"] = "Sono legato a questo posto dal mio giuramento. Cosa ti porta in questo luogo forsaken dalla luce?"
S["e3cf6a77"] = "Noi è $Goccupati:occupate; con cose importanti!"
S["e3d3d317"] = "Durtham Greldon, laggiù in The Forlorn Cavern, può insegnarti per filo e per segno come si entra e si esce scassinando serrature. Basta che non ti metti a entrare e uscire così qui a Ironforge, se capisci cosa voglio dire."
S["e3d4bc59"] = "Per favore, mostrami la Pietra di Maraudon."
S["e3d81654"] = "Stringi il male fra le mani, $Gsciocco:sciocca;! PENTITI!"
S["e3dc0f69"] = "Qui dentro $Gattento:attenta; a dove metti i piedi, $Gragazzo:ragazza;. Il maestro vede tutto..."
S["e3e3238f"] = "Mi pare di aver visto arrivare un nuovo carico di posta non molto tempo fa. La cassetta della posta la trovi proprio fuori dalla Thunder Bluff Bank, sull'altura inferiore."
S["e3e99383"] = "Sei $Gvolenteroso:volenterosa;, ed è un bene. Ma non sei ancora $Gpronto:pronta; per addestrarti con una come me."
S["e3f0b969"] = "Sì, ti prego, richiamalo!"
S["e3f0c834"] = "Ah! Ah! Ah! Grazie per avermi liberato, stolti. Ora lasciate che vi ripaghi bruciandovi la carne fino alle ossa."
S["e3f4a4f6"] = "Non rovinerete le mie terre, feccia!"
S["e3ff54fd"] = "Sono io a custodire il recipiente della sua rinascita. Se sei $Gpronto:pronta; a prenderti questo compito, dovrai rafforzare il recipiente e alla fine spezzare il dominio di Ragnaros in persona!"
S["e4055661"] = "Draghi che comandano gli orchi!? SQUAAK!"
S["e414c8cb"] = "Dai un'occhiata alle mie carni, $Gamico:amica;. Non vorrai partire per le Barrens senza una buona scorta di provviste."
S["e41d342b"] = "Non farti infastidire dal caldo. Nelle Badlands è l'ultima delle tue preoccupazioni."
S["e421119a"] = "Va' in anello interno del War Quarter. Brom Killian lì."
S["e424d413"] = "Un Cristallo Ash'ari è stato ripristinato!"
S["e4396a79"] = "Oh... uno di quei tipi. Be', qui intorno l'unico che se ne intende di arti oscure è Maximillian. Probabilmente lo trovi al buio, nella cantina della Lion's Pride Inn."
S["e43efbff"] = "%s si infuria!"
S["e4416767"] = "%s viene divorato!"
S["e44747f8"] = "Misurando in Kraklenheit, ci sono 428.000 gradi! Che Krakle!"
S["e44ab0ca"] = "Anohe ishnelo!"
S["e44adf10"] = "Abbiamo qualche provvista, ma non molte. Ce ne serviranno parecchie di più per mandare un assalto via terra nel Field of Strife."
S["e451a34d"] = "Hai fatto tuoi i nostri nemici: con te dividerò volentieri le acque."
S["e452cc7c"] = "Onorate i vostri eroi! Oggi hanno inferto un duro colpo a uno dei nostri nemici più odiati! Il falso Capoguerra, Rend il Blackhand, è caduto!"
S["e45d88de"] = "L'entrata è nascosta qui a Moonbrook. Occhio ai ladri: mi vogliono morto."
S["e4625898"] = "Pur vivendo per servire la Madre Terra e l'Orda, non posso fare a meno di sentirmi un po' $Gnervoso:nervosa; ora che abbiamo raccolto tutto ciò che ci serve. Almeno abbiamo un po' di tempo prima che l'Alleanza finisca la sua raccolta. Dopo, tutto verrà spedito a Cenarion Hold in Silithus, e probabilmente la guerra arriverà poco dopo."
S["e465c3c9"] = "La Frostwolf Relief Hut si trova nella Frostwolf Keep, a sud delle Frostwolf Towers.$B$BÈ controllata dall'Orda."
S["e476b0e0"] = "Sarà uno scontro duro, $N. Seguimi da vicino!"
S["e48ec3f1"] = "Mi hai evocato, stolto! Ora MUORI!"
S["e48f72ed"] = "Il dono dell'acqua è l'equilibrio. Rinfresca ciò che brucia, ammorbidisce ciò che s'è indurito, calma gli spiriti agitati. Quando saprai guidare quell'equilibrio negli altri... saprai d'essere sulla vera strada."
S["e490eb74"] = "Ragazzi e ragazze — bambini di tutte le età — è arrivata la Darkmoon Faire! Urrà!"
S["e493021a"] = "È storia... Una storia di Silithus... di Ahn'Qiraj... di Titani e Old Gods... Leggo dalla profezia di C'Thun, così come l'ha scritta il Profeta Qiraji Skerram. Una profezia che preannuncia un cataclisma..."
S["e495adca"] = "Denti affilati, muscoli come cavi e una mente come una trappola d'acciaio. Questo tipo è uno dei migliori animali che abbia mai visto. Se ti interessa, potrei mostrarti un paio di cose per trasformare anche il più debole dei Raptors in una forza da non sottovalutare."
S["e4ac0a76"] = "I Paragoni del Potere sono ciò che resta dell'antico Gurubashi Empire. Noi Zandalar li cerchiamo — non solo per noi valgono moltissimo come pezzi da collezione, ma crediamo anche che conservino tracce latenti della magia che usava il vecchio Impero.$B$BA Zul'Gurub troverai con ogni probabilità tre tipi di Paragoni: monete, bijous e oggetti primordiali. Portaceli nelle quantità che cerchiamo e sarai $Gricompensato:ricompensata; con alcuni degli oggetti più pregiati mai creati da noi Zandalar."
S["e4b7d1b4"] = "Chi dorme nei letti che Innkeeper Keldamyr tiene alla Locanda di Dolanaar trova di sicuro un sonno ristoratore."
S["e4c44efe"] = "|cffffff00La Torre della Guardia della Corona è stata conquistata dall'Orda!|r"
S["e4c6cfcf"] = "Qui a Bloodhoof Village un Istruttore di Alchimia non ce l'abbiamo, ma ce n'è uno a nord, a Thunder Bluff. Segui la strada fin lì e, una volta in cima, chiedi indicazioni a uno dei Bluffwatchers."
S["e4c8d38d"] = "Senti il potere, $N??? È ora di SPACCARE!"
S["e4c9af2e"] = "Io spaccare te!"
S["e4e0f46b"] = "%s comincia a evocare spettri dall'aria gelida!"
S["e4eda5be"] = "Preparatevi ad abbracciare l'oblio!"
S["e4f26ea9"] = "La mia ascia ha visto molte battaglie, e mi piace tenerla a portata di mano. Già diverse volte le forze nemiche si sono aperte la strada fin dentro la nostra capitale, ma non temere: le abbiamo sempre respinte."
S["e4f68def"] = "È chiuso a chiave! NO!!"
S["e4f9922a"] = "<Demitrian cade in ginocchio.>$B$BHai recuperato la prigione eterna del mio Padrone!$B$BOh, quanto ho atteso questo giorno, e finalmente è arrivato.$B$BBisogna liberarlo!"
S["e4fe6fa4"] = "Ne ho qualcuno in più con me; se mi ridai quello che li ho pagati, puoi prenderne uno. Ho anche delle esche."
S["e50c0f1c"] = "Da nessun'altra parte troverai un equipaggiamento migliore!"
S["e518adb0"] = "Ehi, $C, Pele'keiki pensa che tu non sai che tutta quella roba è in viaggio verso Silithus. A Pele'keiki hanno detto che l'ultima parte arriva lì in meno di un giorno, e dopo qualche pazzo sconsiderato suonerà il gong fuori dalle porte di Ahn'Qiraj per aprirle e far cominciare la guerra."
S["e51ace26"] = "Non temete! Ogni destino può essere svelato da chi conosce la via."
S["e51f14ea"] = "Non è ancora la tua ora. Ti aiuterò a tornare nel regno dei vivi... a un prezzo."
S["e52b9431"] = "Lui nome è Grizzle Halfmane. Lui in Royal Quarter con Regina Banshee e Signore del Terrore."
S["e52df4e5"] = "%s inizia a evocare un Blackhand Dreadweaver!"
S["e5319075"] = "Prendi ogni parola che dico e imprimila nella memoria. Finché i nostri nemici non saranno sterminati, non dobbiamo mai sottrarci all'occasione di accrescere il nostro sapere. Rinforza la tua armatura, e non abbassare mai la guardia."
S["e532ca8e"] = "Osi darmi ordini, mortale? No, non credo proprio. Sparisci, elfo insignificante!"
S["e5359cb9"] = "Ti prego, quando potrai, fa' sapere a Cairne che sono al sicuro. Lo troverai a Thunder Bluff."
S["e542cb04"] = "Resistete e combattete!"
S["e54f9b21"] = "Patetico. Voi due non meritate l'addestramento che ricevete qui, se quello era il meglio che sapete fare."
S["e552cb99"] = "Daz maz A maev ze shi melar rikk veni zilthuras, thorje azgala maz a toralar?"
S["e55c5f91"] = "Salute, $Gviaggiatore:viaggiatrice;! Sono Creeg Bothunk, il fornitore principale dei Darkspear Raiders. Man mano che salirai di reputazione presso i Darkspear Raiders, potrò venderti merci di vario tipo da usare nelle Darkspear Islands. E se hai qualcosa da far riparare, ci penso io."
S["e55d637c"] = "Ladri! Fonderò i vostri resti!"
S["e56b1117"] = "$N rivendica la fattoria! Se nessuno $Glo:la; sfida, l'Orda la controllerà fra 1 minuto!"
S["e56c8597"] = "Lascia questo luogo. <La reliquia emette un arco di fiamma incandescente. Hai ottenuto un ricordo: un nano Dark Iron solitario, circondato da sette cadaveri, inginocchiato davanti a un monolite di fiamme.>"
S["e56fa624"] = "Ho sentito dire che dopo i fuochi d'artificio porteranno dei calici ai tavoli. Grandi brindisi leveremo!"
S["e57399bb"] = "Qui c'è stata una grande battaglia. Anzi, molte grandi battaglie."
S["e57bfce0"] = "Oh, vuoi imparare a raccogliere margherite, eh? Ah! Ti sto solo prendendo in giro, $Gragazzo:ragazza;.$B$BÈ un bel mestiere, e Reyna Stonebranch può farti vedere come si fa. Lavora all'Ironforge Physician, sul lato sud di The Great Forge."
S["e5853b90"] = "Io sono colui che sorveglia essi. Io sono il pugno del castigo, ciò che doma i recalcitranti. Osi sfidare il Capoguerra? Osi affrontare il mio giudizio spietato?"
S["e5988d62"] = "Sono partiti per Gadgetzan un po' di tempo fa, per riportarci delle provviste. A dire il vero, avrei dato almeno quattro delle mie dita per avere l'occasione di infilarmi in uno degli zaini di Dadanga e andarmene da questo forsaken posto."
S["e5993089"] = "È un mestiere pericoloso, questo!$B$BMiran è appena partito con una consegna. Dovrebbe tornare tra qualche minuto."
S["e5acef02"] = "Ehi, mon, devi anda' dall'addestratore di $C."
S["e5b475a2"] = "%s si asciuga la fronte."
S["e5b4b7fb"] = "Corbett, caro. Harlan ha bisogno di un carico di camicie e pantaloni a maglia il prima possibile."
S["e5b665fd"] = "Tu non ti riunisci a nessuno, Thorsen..."
S["e5c173be"] = "Un lingotto di Sulfuron?!??! Impossibile! Devo averlo! Devo! Devo!$B$B$R, sono autorizzato a offrirti un grande affare in cambio di quel lingotto. Ti interesserebbe conoscere i segreti della Mano di Ragnaros, magari? Sulfuras, idiota! Il leggendario martello del Firelord."
S["e5c76f23"] = "Il nostro popolo ha commesso un errore gravissimo affidando il proprio destino a volubili spiriti elementali. Ora tocca a noi porvi rimedio."
S["e5c775e6"] = "Chiamo il tuo vero nome, Azrethoc. Mostrami il tuo volto!"
S["e5cba804"] = "Gul'rok. Kek rath'is ogg zaga no throm'ka."
S["e5cdf21a"] = "Addio, e che l'ombra ti protegga sempre!"
S["e5d179f4"] = "Di cucina ne sai un po' troppo poco. Magari, con la pratica, potrò insegnarti quello che so."
S["e5db60a4"] = "Elder Grimtotem lo trovi al Lariss Pavilion, a Feralas."
S["e5e076fc"] = "È ancora in costruzione e si trova a pochi passi lungo la strada a nordest. Le montagne di Alterac hanno attirato l'attenzione indesiderata di alcune creature selvagge, e il nostro recente interesse per la Silverpine Forest ha tenuto parecchio impegnate le nostre pattuglie.$B$BSi è persino sparsa qualche voce su un giovane drake che volteggia sopra le montagne con occhio attento."
S["e5e78096"] = "Non lo vedi che ho da fare? Spero per te che sia una cosa importante."
S["e5ec8f64"] = "<Thrall ride.>$B$BHai ancora tanto da imparare, $R.$B$BSei troppo giovane per ricordare le guerre e i massacri delle ere passate. Troppo giovane per ricordare il peso della maledizione che il nostro popolo si è portato addosso.$B$BOra i rapporti con l'Alleanza sono fragili. Qualche scaramuccia e qualche battaglia minore ci sono, certo, ma c'è la pace — una cosa che il nostro popolo non conosce da millenni. E tu rinunceresti a tutto questo per ributtarci nelle fauci del caos, ma questa volta contro un nuovo nemico? Uno che non si fermerà finché non saremo tutti distrutti?"
S["e5ed20f8"] = "%s comincia il rituale."
S["e5f34202"] = "Vorrei sussurrarti il mio codice segreto per ricevere la mia mascotte Panda Cub."
S["e5fca46f"] = "Intrusi! Invasori! L'Occhio che Tutto Vede è stato rubato! $GQuel miserabile cane:Quella miserabile cagna;, $N, ce l'ha in mano!"
S["e6085e21"] = "Sembri un po' $Gsperduto:sperduta;. Chi stai cercando?"
S["e60ca4c4"] = "Malfurion!"
S["e60de8bf"] = "Vuoi vedere cosa vendo?"
S["e620e5f6"] = "Ho preso degli ottimi campioni, Hornizz. Ora mi ci metto al lavoro. Puoi occuparti tu del resto?"
S["e62144c6"] = "Che vuoi dire? Quando Arthas ci ha traditi, chi di noi era ancora fedele alla Corona ha preso le armi per respingere il suo empio flagello.$B$BIl nostro glorioso comandante si è alleato con The Banshee Queen, Sylvanas, per ripulire la patria dalla feccia non morta. Da allora non so più niente di lui, e ne attendo con devozione il ritorno."
S["e623ffd3"] = "Il Macellaio parlava del 'blood of innocents' e del suo oscuro padrone, 'Kirtonos', e di come dovesse placarlo.$B$BAlla fine la bestia ha concluso i suoi esperimenti. Ci aveva prosciugati di ogni vita, e gli spiriti erano a pezzi. Il dolce abbraccio della morte ci stava avvolgendo, e l'abbiamo accolto a braccia aperte. Ma il Macellaio, nella sua infinita crudeltà, ci ha strappati alla soglia della morte.$B$BVoleva tenerci in vita per gettarci in pasto ai suoi ghouls famelici, e rideva guardando quei mostri divorarci la carne."
S["e62be0e6"] = "Gran bel combattere! Hai reso fiero un vecchio. Continua così e stasera la birra la offro io."
S["e63429ff"] = "È bello rivederti, Danitha. Sono passati solo pochi anni, ma sembra che sia trascorso un oceano di tempo."
S["e63c4bad"] = "$N attacca!"
S["e63f55b6"] = "Nostyec, uden thor ko Aesire Firalaine."
S["e6408f89"] = "Il Frostwolf Graveyard si trova lungo la strada, non lontano a nord del Frostwolf Village.$B$BAl momento è controllato dall'Orda."
S["e6409038"] = "Acquisire scheda dati di alto livello."
S["e642128c"] = "Marketing - Saluto per il riscatto iCoke (S.H.E., confezione regalo)"
S["e64c000a"] = "Questo sì che è un pezzo d'acciaio che vale la pena indossare. Forma e funzione, $Gragazzo:ragazza;: sono colpito. Uno all'altezza l'ho visto una volta sola, da un Maestro della Great Forge di nome Grumnus Steelshaper. Scommetto che nel frattempo ha imparato qualcosa, e probabilmente potrebbe insegnartene un po'."
S["e65058b1"] = "Ti copro io, Guse."
S["e6510f94"] = "$N, abbiamo abbastanza provviste per lanciare assalti via terra nel Field of Strife. Se vuoi dare gli ordini, e il tuo grado è abbastanza alto, parla con Sergeant Yazra Bloodsnarl nel Frostwolf Village."
S["e6563346"] = "Addio, mondo crudele... Oggi ti lascio... addio... addio... addio..."
S["e65ac26d"] = "Eh? Salve, giovane $C. Con tutte quelle creature in giro, sei $Gstato coraggioso:stata coraggiosa; a trovare la strada fin qui!$B$BBeh, visto che sei qui, forse puoi dare una mano a un vecchio eremita..."
S["e660655e"] = "Allora credi di essere $Gbravo:brava; abbastanza da imparare da me? Dal grande Snarl? Sei solo un misero verme sotto il mio stivale. Però avere un sottoposto potrebbe rendermi più attraente agli occhi di Sumi e Tumi. Vediamo queste tue scarse capacità."
S["e66d4dfb"] = "Torno al Covatoio, Tinkee. Mi serve un Uovosciloscopio!"
S["e66ee3be"] = "Altri agenti dello Syndicate, scommetto! Non vi riprenderete mai Alterac... né Southshore!"
S["e673d0ff"] = "Benvenut$Go:a;!"
S["e67e6ebd"] = "So bene di chi parli, $C. Cerca Brogun Stoneshield sulla Terrazza del Guerriero."
S["e68d5758"] = "Quanto altro sangue serve, Comandante?"
S["e6a48a3b"] = "Coccodè, coccodè, coccodè! Buona Hallow's End, $N!"
S["e6ace453"] = "Ti istruirò, ma prima devi dimostrare quanto vali..."
S["e6af2a92"] = "Non è la creaturina più straordinaria che ci sia?"
S["e6b21a0c"] = "Incanala le tue energie nell'Altare!"
S["e6bad9cb"] = "È fatto."
S["e6bae960"] = "Ecco! Era questo che aspettavate! UCCIDETELI!"
S["e6bba1cd"] = "Abbiamo cominciato a ritorcere contro di loro la peste dello Scourge, ma la presa è a dir poco precaria! Aiuta la causa e prendi il controllo dei loro calderoni!"
S["e6bf32dd"] = "Brom Killian insegnare te come scavare roba luccicante per me. Lui stare su anello interno di War Quarter."
S["e6c18846"] = "Perirai qui. <La tua mente si riempie di visioni di caos e distruzione.>"
S["e6cebb8a"] = "$GBen trovato:Ben trovata;"
S["e6d41912"] = "Gli umani si sono presi gran parte della Dustwallow Marsh, ma con il nostro aiuto il clan Stonemaul è riuscito a respingerli."
S["e6df650c"] = "Va, y ealdor Gloinador. E majis ko dana ne barad ras thorniss lars majis gol ador endirvis."
S["e6dfe61d"] = "Ehm, a pensarci bene, quel dirupo è parecchio ripido. Immagina se scivolassi e mi rompessi una caviglia! Non potrei chiederti di portarmi in braccio."
S["e6e253f6"] = "Va bene, ti insegnerò, ma voglio che tu faccia una cosa per me. È importante, quindi presta molta attenzione."
S["e6e2a636"] = "Che posso fare per te, $C?"
S["e6e83893"] = "Stratholme non esiste più! La città giace in rovina. Il Principe consumato dall'odio... dalla follia..."
S["e6e88276"] = "Credi di avere quello che ci vuole per estrarre il minerale?"
S["e6f427e2"] = "Brontolo, brontolo..."
S["e6fef8d6"] = "Desidero fare un acquisto, Nipsy."
S["e6ff4662"] = "<Thrall ride.>$B$BNe prendo nota... Ora ascoltami bene, $N. Onyxia, la madre della covata del Black Dragonflight, è stata stanata dalla posizione di potere che aveva a Stormwind, ed è fuggita a rifugiarsi nella sua tana, nella Dustwallow Marsh.$B$BNon possiamo lasciarla vivere così vicino alle nostre capitali. Dobbiamo colpire prima di essere colpiti!$B$BLa voglio distrutta, $N."
S["e70ad844"] = "Ehi, $Gamico:amica;. Mi chiamo Remy. Sono di Redridge, a est, e sono venuto qui a cercare affari, a cercare affari. Ne hai qualcuno... ne hai qualcuno??"
S["e7101b5d"] = "Io mangia voi tutti!"
S["e713d1be"] = "Prendi una pietra dal tavolo, $N. Ti servirà per la missione."
S["e713d878"] = "Bleah! Cosa gli salta in mente a quel furfante di mandarmi i suoi parassiti? Sparisci dalla mia vista prima che mi prenda quel che resta della tua vita. E portati via questo."
S["e72094a8"] = "Sì, fallo pure, ti prego."
S["e7221022"] = "Non mi farò attirare via!"
S["e72ceb86"] = "Davvero? Allora lo sai quanto era debole e patetica la versione degli alti elfi della magia dei troll?$B$BGli alti elfi non si spiegavano come un popolo così portato per la magia non riuscisse a stare al passo con i poteri del voodoo dei troll. Quei visi pallidi non riuscivano nemmeno a concepirlo. Così si sono rassegnati a usare una versione imbastardita degli incantamenti dei troll. Credo che li chiamassero 'Arcanum'."
S["e7317f1a"] = "%s sceglie il bersaglio a forma di orco..."
S["e73938cf"] = "%s si scheggia e va in frantumi!"
S["e73d62db"] = "Il potere della Luce è davvero grande e misericordioso."
S["e750e726"] = "Solo i giusti saranno salvati da ciò che sta per arrivare! Morte ai miscredenti!"
S["e754b5e5"] = "Passo di corsa!"
S["e755ede4"] = "Uahahah! Ti porto giù con me!"
S["e756211e"] = "Che cosa ti serve da me, $Gfiglio:figlia; di Zephras?"
S["e756d46b"] = "La Tower Point controlla il passo tra il Field of Strife e i territori dell'Orda a sud.$B$BNon è controllata da nessuna delle due parti."
S["e75f4402"] = "Sergra cade in trance per un momento, poi guarda verso il cielo."
S["e766573d"] = "Se cerchi informazioni che il Cenarion Circle potrebbe aver archiviato da qualche parte, è con me che devi parlare. Prima che possa aiutarti, però, devi sapere cosa stai cercando.$B$BVisto come funziona? Geniale!"
S["e768fe82"] = "Stoltamente avete cercato la vostra fine."
S["e7711f29"] = "Non smetterai mai di darmi la caccia, vero? E va bene, ma non mi abbatterai senza combattere!"
S["e773a89a"] = "Ho sentito dire che a Sen'jin Village i troll hanno un pozionista, un certo Miao'zan. Va' a cercarlo lì."
S["e773d5b3"] = "Parlami di Dun Baldar."
S["e77a1da0"] = "Salute. Io istruisco i maghi, e tu sei $Gun mago:una maga;."
S["e77c3492"] = "Per quanto si impari, c'è sempre altro da sapere."
S["e77d03a9"] = "<Da poco lontano, la testa di Othmar ti guarda.>$B$BCosa... Tu... Vuoi...$B$B$GLurido:Lurida;... Skyborne..."
S["e78254aa"] = "Strano. Molto strano..."
S["e78aee58"] = "Saluti e $Gbenvenuto:benvenuta;. Sorridere non è il mio forte, ma fidati: sono felice di servirti."
S["e78c47ed"] = "E mentre il tuo corpo inerte penzolerà dalle travi, mi godrò il sapere che un pazzo è stato messo a morte. Dopotutto, che prove hai? Pensavi di entrare qui, puntare il dito contro la nobiltà e uscirne indenne?"
S["e793d3e7"] = "%s guarda nervosamente verso Lotwil."
S["e7bec1af"] = "Eh? Non ho tempo per le chiacchiere, mio pa' vuole che gli finisca questa commissione."
S["e7bfa700"] = "Salve, $C. Hai un'aria familiare... ci conosciamo?$B$BBe', se ci conosciamo, allora... di sicuro ti è stato dato un codice segreto. Dimmi il tuo codice e ti farò un regalo!"
S["e7c049d5"] = "Non ho altra scelta che obbedire!"
S["e7c1eb45"] = "Brandicenere..."
S["e7d341d1"] = "Caldi saluti da me, $C, e anche dalla Shattered Hand.$B$BNon fare quella faccia sorpresa, $N. Pure nei posti più alti di Orgrimmar ci sono ombre — e là qualcosa deve nascondersi. Quel ruolo la Shattered Hand se lo prende volentieri. Thrall, pure col suo cuore buono, riconoscere che la Hand essere necessaria per tenere al sicuro orchi e troll.$B$BMa tu mica qui per parlare dei miei affari: tu qui per qualcos'altro."
S["e7d3a5f9"] = "Come sarebbe a dire che non sai usare un'ascia?"
S["e7d8d8e7"] = "La fede... C'è chi l'ha persa e chi l'ha trovata. Non la si può né distruggere né creare.$B$BO parli forse dei paramenti della Fede? L'armatura che i nostri sacerdoti e i guerrieri più devoti portavano in battaglia contro lo Scourge, nell'ultima guerra.$B$BSì, è andata perduta in gran parte... L'hanno rubata i mostri di Naxxramas."
S["e7e5be73"] = "Non affannarti per le cose del passato, $N!"
S["e7e91219"] = "Desidero imparare la mia specializzazione di conciatura."
S["e7efc681"] = "Puoi indicarmi la strada?"
S["e7fe1f46"] = "Finché non prendi le redini di un pregiato ariete di montagna di Barak Tor'ol, non sai cos'è una vera cavalcatura, $Gamico mio:amica mia;. Avanti, guarda pure questi compagni: sono ottimi per qualsiasi avventuriero. Credimi, ti serviranno bene."
S["e81735ad"] = "Andiamocene da qui, $N. Ora sono $Gpronto:pronta;!"
S["e82663fe"] = "Il Divoratore consumerà il mondo!"
S["e82e1eb4"] = "Baciami."
S["e82edbf3"] = "La polvere delle Barrens mi secca la gola ogni giorno di più, $N. Ma se serve all'Orda e al capoguerra, restare qui è un sacrificio che vale la pena fare."
S["e8310957"] = "Posso mostrarti qualche trucco... se non ti dispiace fare prima una piccola cosa, s'intende."
S["e83586e0"] = "Ah, essere strappato a quel terribile incubo! Grazie a te, $Gmio fedele Discepolo:mia fedele Discepola;, e ai tuoi coraggiosi compagni."
S["e835ad9b"] = "Meglio che mi rimetta in cammino. Khara mi aspetterà a momenti. Ci vediamo domani, X."
S["e837e748"] = "ASSAGGIATE LE FIAMME DI SULFURON!"
S["e83ba136"] = "Ehilà, Belm! Un boccale di Thunder Ale per me, e uno per $Gil mio buon amico:la mia buona amica; $N."
S["e83e5969"] = "Se non hai mai guardato il mondo dall'alto, dalla groppa di un wind rider, non puoi dire di aver vissuto."
S["e8405205"] = "Большой, le mie ferite sono gravi. Perdona la mia lentezza, ma le ferite non mi permettono di camminare più in fretta."
S["e84131e0"] = "Povero Dorius. Se mai metto le mani su quei Dark Irons, giuro che..."
S["e84870ad"] = "Io al posto tuo comprerei un buono scommessa sui goblin. Tifare per l'altra squadra è tempo perso."
S["e84b3247"] = "Ho fallito il mio compito di vegliare sul tempio... la mia anima corrotta non conosce pace..."
S["e84f5cce"] = "NON LASCIATELA SCAPPARE!"
S["e84fc455"] = "Il caldo... non ce la faccio..."
S["e855a173"] = "Salvami..."
S["e85b8dea"] = "%s si lancia in una frenesia omicida!"
S["e85df9f0"] = "Accesso ai dati consentito. Buona giornata!$B$B01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011"
S["e861eb8e"] = "Ho appena visto uno dello Scourge! Uccidetelo!"
S["e8705802"] = "Questo dovrebbe alleviare il dolore."
S["e8827108"] = "La cena è arrivata!"
S["e8832c94"] = "OH NO, NON L'HAI FATTO! ADESSO SI FA SUL SERIO! <PH>"
S["e8837034"] = "Daz ante maez amanare me amanare maz veni, theramas toralar."
S["e88885a1"] = "Per $Guno sconosciuto:una sconosciuta; il tempo lo trovo sempre! Quasi sempre, almeno..."
S["e88eb3d9"] = "Magari fosse vero, $N, ma tu da $Gsolo:sola; non basterai a sconfiggere le forze di Razelikh e dei suoi sottoposti.$B$BRiunisci un gruppo di avventurieri e aspiranti eroi all'altezza e libera i miei uomini dalla tortura eterna! Le pietre da frantumare sono diciotto.$B$BCombatti con tutte le tue forze e muori con onore, $N."
S["e896bd06"] = "$C, a Warsong Gulch ci serve il tuo aiuto contro le Silverwing Sentinels, e ci serve tanto. E c'è pure più onore da guadagnare, e più reputazione presso i Warsong Outriders! Hai il coraggio di scendere in battaglia?"
S["e89fcc89"] = "Ehi, qualcuno mi aiuti ad acchiappare questa cosa!"
S["e8a90729"] = "Povero piccolo asino. Era solo un piccoletto."
S["e8af1747"] = "Mettiti in riga! Combattere al fianco dell'Orgrimmar Legion non è un compito facile. Le reclute che questi elfi del Cenarion Circle continuano a mandarci non durano mai a lungo."
S["e8af4a9f"] = "Qui si dice che abbiamo raccolto tutto ciò che ci serve. Ora tutto dipende da quando l'Orda avrà raccolto la sua roba. Allora potremo spedire tutti i nostri beni a Silithus e la guerra potrà cominciare."
S["e8bba02b"] = "Proprio così, le colline di Winterspring stanno cercando di resistere a un nuovo assalto dello Scourge. Il tuo aiuto sarebbe per loro prezioso.$B$BNecropoli rimaste: $2284W"
S["e8c29ad2"] = "Qualcosa affligge questa torre. Mi sono ammalato, e anche gli altri dipendenti della Venture Co. che lavorano dentro o vicino alla torre si sono ammalati.$B$BGiusto la settimana scorsa, due dei nostri pattugliatori sono morti, solo per tornare subito in vita come automi senza mente!$B$BLa forza vitale sta abbandonando il mio corpo. Sento che sto perdendo il controllo. Impulsi che prendono il sopravvento... Impulsi cattivi... *Fizzule si dà uno schiaffo in faccia* Non ancora... Ascolta... La mia è una posizione di potere. Questa posizione mi dà accesso ad alcune informazioni riservate."
S["e8c6c187"] = "'E poi cosa', te lo dico io. Si è messa a correre dritta verso l'alveare. E la cosa più folle sai qual è? Nemmeno un dannato insetto le si è parato davanti o ha provato a fermarla. È passata in mezzo a tutti quanti come se fosse la loro migliore amica da secoli."
S["e8c9fc2b"] = "È vero — hai abbandonato i tuoi fratelli d'armi?"
S["e8cb5b9a"] = "Ti serve l'Hall of Legends. È in alto, sopra la Valley of Strength, sul lato ovest. Se non sei $Gun:un'; ufficiale non puoi entrare, ma puoi sempre parlare con Sergeant Ba'sha, lì fuori."
S["e8e74661"] = "Come lo chiamate quello? Se quello è combattere, allora io sono Lothar in persona!"
S["e8ec9709"] = "%s bacia Mistress Nagmara"
S["e8ee8ade"] = "Il nostro capitano ci salverà!"
S["e8f38b9a"] = "<Ayessa Dawnsinger ti squadra, trattenendo a stento la furia.> $B$BPer mettere piede con tanta sfacciataggine nel nostro dominio, dopo aver versato sangue Windshaper, devi essere molto audace o molto $Gstupido:stupida;. Noi perdoniamo a fatica, e non dimentichiamo mai. $B$BTi conviene andartene subito. Se non fossimo nel cuore di Zephras, saresti già $Gmorto:morta;."
S["e90046a5"] = "<Constable Aonda ha un'espressione intensa ed è chiaramente immersa nei suoi pensieri.>"
S["e906619b"] = "Sssì... Guardie, venite in aiuto del vostro signore!"
S["e90c432d"] = "Per me il bello della pesca è che va piano. Hai il tempo di pensare, di ripensare al passato e di fare progetti per il futuro.$B$BOh, ed è anche un'ottima scusa per bere. Parecchio."
S["e90d1652"] = "Non arriverai al limitare della foresta, Fordring."
S["e9127cb4"] = "Interessante, interessante... $N, so che in cima alla collina sopra le Wailing Caverns vive una druida. Forse potrà dirti di più su questa scheggia che hai trovato.$B$BOra devo rimettermi al lavoro!"
S["e9139043"] = "Ah, mi sa che sto correndo troppo. Ras Frostwhisper è il sovrintendente di questa scuola, l'essere incaricato di addestrare tutti i suoi Maestri Oscuri: luogotenente e allievo prediletto di Kel'Thuzad. Un tempo era un mago autodidatta di Stromgarde, un cane sciolto che da Dalaran non ha mai ricevuto un addestramento formale.$B$BQuando Kel'Thuzad ha fondato il Culto, Ras è stato tra i primi a entrare nelle sue file. Sapeva che con la magia oscura avrebbe trovato l'immortalità."
S["e914b2c3"] = "Grazie per questi distintivi, $N. Manderò notizia alle famiglie dei defunti."
S["e91932cf"] = "Buone feste, e pace a te!"
S["e91f955d"] = "L'Alto Signore era il perno della Crociata. Sì, Mograine lo chiamavano The Ashbringer, per le sue imprese contro gli eserciti di The Lich King. Armato solo della spada e della fede, Mograine avanzava in mezzo a interi battaglioni di non morti e ne usciva illeso — e del suo passaggio restavano soltanto le ceneri dei nemici. Non capisci? Lo temeva il volto stesso della morte! Tremava davanti a lui!"
S["e93a7c20"] = "Nel corso di 8.000 anni, sono state forgiate solo poche di queste lame — ognuna unica sia per potere che per aspetto. Le lame di Quel'Serrar assumevano le caratteristiche del loro creatore."
S["e940eae9"] = "Eccellente, è arrivato sangue fresco."
S["e9503c3f"] = "Sappi questo: Eranikus non desidera altro che essere portato dal Sogno ad Azeroth. Una volta fuori, non si fermerà davanti a nulla pur di distruggere la mia forma fisica. Questo però è l'unico modo per recuperare il frammento dello scettro."
S["e955ed2a"] = "Grazie, $N. Che la Luce ti benedica, $Gfratello:sorella;, e guidi il tuo cammino."
S["e95989fa"] = "Ehi, Bly! Bilgewizzle rivuole la sua divino-matic rod!"
S["e95afe56"] = "L'Occhio Onniveggente deve essere recuperato!"
S["e9627019"] = "I piloni che tengono la nostra isola ancorata al piano elementale di Skywall stanno cedendo. Zephras Isle — la nostra casa — è in grave pericolo."
S["e96aaacd"] = "Proverò un gran piacere a togliere la vita a questa poveretta! Non è troppo tardi, non deve soffrire invano. Tornate indietro e la sua morte sarà misericordiosa!"
S["e9776299"] = "Le Blasted Lands sono sotto attacco in questo momento?"
S["e97953eb"] = "Puoi contare su di me, Jeztor."
S["e983ccea"] = "Ehi, mon. Va' a parlare col mio Master Gadrin, è proprio là. Tu sistema quel pazzo di Zalazane per lui, e io ti rimetto a posto!"
S["e99aa5d4"] = "Il Windfield Orchard ha conosciuto tempi migliori..."
S["e99cce0b"] = "Istruttori di stregoni in Magic Quarter, in edificio su anello esterno, con Maghi."
S["e99d70c2"] = "$N, hai disturbato il mio riposo!"
S["e9a13896"] = "Vediamo se riusciamo a capire da dove saltano fuori questi Troggs... e a fermare l'invasione!"
S["e9a7740f"] = "%s punta $N"
S["e9a7bb30"] = "Ora riposa, figlia mia."
S["e9ae0771"] = "$GQuel:Quella; $N mi vuole $Gmorto:morta;! Aiuto!"
S["e9b036d1"] = "Mm... hai fatto bene a portarmelo, $N."
S["e9b482fc"] = "Forse. Ora va', giovane, e chiedi udienza al Capoguerra. Vorrà di certo sapere della tua scoperta."
S["e9b5810c"] = "%s è bruciato dalla magia scatenata!"
S["e9b6deda"] = "Be', tu di certo non lo farai mai più, insetto. Ah!"
S["e9b7b9a4"] = "Be', stando qui $Gfermi:ferme; non ci avviciniamo di certo. Forza, Dadanga! Hia!"
S["e9bcbb15"] = "Anni di ottime tecniche di allevamento e tante cure mi danno il privilegio di mostrarti questi cavalli! Prenditi pure tutto il tempo che ti serve per sceglierne uno da cavalcare. Un cavallo è un compagno per la vita, $Gamico:amica;. Non accontentarti di poco — il tuo destriero prendilo qui, oggi stesso!"
S["e9bdf8a1"] = "Le loro menti ora sono corrotte, $R. Sì, ancora più di prima. Vivono solo per servire e proteggere Razelikh. I frammenti di amuleto che ciascuno di loro custodisce sono la chiave per evocare il signore dei demoni. Quello che non capisci è che nessuno di loro può essere ferito con alcun mezzo convenzionale"
S["e9c8de05"] = "Secondo te mi servono altre spillette?"
S["e9d18d6d"] = "Secondo me in questi canali non ci sono pesci."
S["e9d22d1f"] = "Non cercare di imporre la tua volontà al cuoio. Lascia che siano le sue tendenze naturali a decidere che forma e che funzione prenderà. Non è una battaglia da vincere: lavora con il cuoio, non contro."
S["e9d2d200"] = "Il Kirin Tor ha ignorato i miei avvertimenti! L'Alleanza è una farsa. Arugal è uno stolto sconsiderato."
S["e9d30240"] = "Patetico."
S["e9e21ea1"] = "Col tempo sarai $Gpronto:pronta; per quello che ho da insegnarti, $N. Fino ad allora, fatti aiutare da Darianna, laggiù, nell'addestramento."
S["e9eb1702"] = "PER L'ORDA! PER CAIRNE! PER THUNDER BLUFF!"
S["e9efce4d"] = "Purtroppo, con l'esperienza che hai, posso insegnarti ben poco, $Gamico mio:amica mia;. Cerca l'elfa della notte Sylvanna Forestmoon, che vive nella Craftsmen's Terrace of Darnassus."
S["e9f98458"] = "Ahh... I miei esperimenti non riescono mai come dovrebbero. Forse dovrei tornare giù lungo il fiume."
S["e9fefb3d"] = "Allora... Pensavi di potermi ingannare, eh? Il più grande genio del crimine che Azeroth abbia mai conosciuto???"
S["e9ff6f8e"] = "$N sta arrivando in fretta da questa parte! Preparatevi all'attacco!"
S["ea024144"] = "$C, alla Warsong Gulch abbiamo bisogno del tuo aiuto. Combatterai al nostro fianco contro i Warsong Outriders?"
S["ea02eb42"] = "Il fondale dell'oceano, per me, è un posto molto tranquillo."
S["ea0a7e04"] = "Ho cambiato idea, fedeli servitori, non c'è bisogno di portare il prigioniero fino al mio studio: me ne occuperò qui e ora."
S["ea0b1861"] = "Salve, $Gragazzo:ragazza;, se cerchi i migliori affari fuori da Ironforge, sei nel posto giusto."
S["ea10b0e7"] = "$N! Ho finito!"
S["ea1e629f"] = "Non resta molto da dire. Archimonde ha distrutto quasi del tutto Dalaran, e il bastone è andato perduto: con ogni probabilità l'hanno frantumato i meccanismi di sicurezza della barriera.$B$BC'è chi crede che dietro la rappresaglia di Archimonde ci sia il bastone."
S["ea20075d"] = "%s salta per lo spavento!"
S["ea24d6a8"] = "Questo non è un gioco con cui divertirsi, pivello! Vai, parla con Snarl qui fuori. Sarà anche una serpe nella mia tana, ma con l'incudine ci sa fare."
S["ea2b69d3"] = "Ti ho già insegnato tutto quello che potevo, $N. Se vuoi continuare a studiare, parla con l'elfa della notte Lilyssia Nightbreeze in Mage Quarter of Stormwind. Ho sentito dire che è una brava insegnante."
S["ea323703"] = "Le ultime notizie dicono che Elder Runetotem era in viaggio verso Razor Hill, in Durotar."
S["ea340786"] = "Pochi arrivano fin qui, e ancora meno vanno oltre. Vedi di non diventare una statistica, $N."
S["ea351eee"] = "Se hai sentito dire che tutte le raccolte dell'Orda e dell'Alleanza sono state completate, hai sentito bene, $C. I beni per la guerra che abbiamo raccolto e preparato stanno viaggiando tutti verso Cenarion Hold, in Silithus, e fra pochi giorni arriverà l'ultimo carico. Dopo, immagino, non ci resterà che stare a vedere chi metterà insieme lo scettro con cui suonare il gong, che aprirà i cancelli di Ahn'Qiraj e annuncerà la guerra."
S["ea36ebab"] = "Mi dispiace, $Gragazzo:ragazza;, ma ti mancano proprio le basi per imparare quello che insegno io. Non preoccuparti, però: va' dal mio allievo Rotgath, ti darà una mano lui."
S["ea3a6211"] = "Ricorda, mi serve il tuo aiuto per incanalare come si deve. Ti chiederò di aiutarmi più volte lungo il cammino, quindi ti prego, sii $Gpronto:pronta;."
S["ea3b5819"] = "Sono fuori dalla pancia di questa bestia da nemmeno due minuti e già qualcuno mi chiede delle mie abitudini in bagno??? $GSignore:Signora;, per una domanda del genere ti avrei preso a sberle fino a farti girare la testa, se non fossi $Gstato:stata; tu a salvarmi!$B$BComunque! Ti sono $Ggrato:grata; per l'aiuto. Magari posso sdebitarmi?"
S["ea4f5acd"] = "Di solito queste cose le lascio agli gnomi. Se vuoi imparare la professione, sono $Gsicuro:sicura; che in giro per Stormwind troveresti qualche gnomo disposto ad addestrarti."
S["ea5524a8"] = "%s si lancia di nuovo all'attacco!"
S["ea5a92d8"] = "Ahmen ne te!"
S["ea79fa69"] = "Che cos'è questa storia? Vuoi rovinarmi la reputazione? Io non insegno ai novellini, signora. Prova a parlare con l'orco Whuut nel Drag of Orgrimmar. È molto più vicino al tuo livello di abilità. E di cervello."
S["ea88c4dd"] = "Captain Redpath! Come avete potuto abbandonarci!"
S["ea8a51ca"] = "Le nostre unità sono state potenziate a Campioni, ma posso ancora raccogliere altre provviste."
S["ea8afcc3"] = "Una faccia che sorride da un orecchio all'altro..."
S["ea9340b3"] = "Ma non doveva andare così. Mentre i nemici incalzavano, l'armatura di Anathera fu trafitta dalla lama corrotta di un demone. Nel pieno della battaglia, nulla avrebbe potuto salvarla."
S["ea981cac"] = "%s lascia cadere la sua arma."
S["eaa00aba"] = "%s si addormenta all'improvviso."
S["eaa01fc7"] = "La magia arcana è un affronto agli spiriti del vento!"
S["eaa6bde2"] = "Magnifico. Semplicemente magnifico. Sei d'ispirazione per tutti noi, $N."
S["eaa7ac2f"] = "Questo sì che è un investimento sbagliato!$B$BAl mercato nero, il libro oscuro di incantesimi di Lord Valthalak ha fruttato un bel gruzzolo. Peccato che a lui non sia piaciuto granché vedersi rubare la roba. Quel fetente ce l'ha fatta pagare, e sì che era morto da mesi!"
S["eab3fdda"] = "Incredibile! Credo di averlo trovato, $N!"
S["eab61148"] = "%s attacca!"
S["eab81c63"] = "Non importa. Penso che farò semplicemente uccidere entrambi dai miei animali e rimandare la tua lingua a Elaadrin come avvertimento a tenere i suoi piccoli maghi a Valanaar, dove appartengono."
S["eab9b0f5"] = "Spero che Ogron trovi quel pelle rosa e gli spezzi le gambe. Vediamo come sopravvive nella palude così!"
S["eab9c85d"] = "Elder Silvervein è vicino a Thelsamar, a Loch Modan."
S["eac1f077"] = "Intrusi! Altre pedine dell'Argent Dawn, senza dubbio. Tra i miei prigionieri ne conto già una. Ritiratevi dal mio dominio prima che venga giustiziata!"
S["eac2bfd0"] = "$N, $GCampione:Campionessa; dello Stormo Bronzeo, ha suonato il Gong dello Scarabeo. Le antiche porte di Ahn'Qiraj si aprono, rivelando gli orrori di una guerra dimenticata..."
S["eac43f0e"] = "borbotta borbotta..."
S["eac6fd3f"] = "Eh sì, oggi fa freddo, ma mai troppo per non offrirti la mia bella mercanzia!"
S["eacab8ba"] = "%s mette via gli oggetti che $N gli ha dato."
S["ead3c2c7"] = "Inginocchiati! Inginocchiati davanti a The Ashbringer!"
S["ead77984"] = "Io brindo a qualsiasi cosa!"
S["ead98faa"] = "Hai mai sentito parlare della madre della covata del Black Flight? Credo che si chiami Onyxia..."
S["eae1fc60"] = "La spada non è un attrezzo, è un prolungamento di voi. Mi aspetto di meglio!"
S["eae9a365"] = "In che direzione posso indirizzarti?"
S["eaefe5be"] = "Hip hip, urrà!"
S["eaf07383"] = "%s ride della tua sciocca richiesta."
S["eaf94f92"] = "%s colpisce solo il lato della cassa!"
S["eafec329"] = "%s raccoglie il potere attorno a sé..."
S["eb04d57e"] = "Grazie, $N! Sono libero!!!"
S["eb083a0b"] = "Faresti bene ad andare all'Hall of Arms, sul lato nord di Valanaar."
S["eb0892af"] = "Elder Dreamseer vive a Gadgetzan, nel Tanaris Desert."
S["eb0c5522"] = "Non abbiamo molto tempo; raddoppiate gli sforzi."
S["eb1456be"] = "Inchinatevi! Inginocchiatevi davanti a The Ashbringer! Una nuova alba si avvicina, fratelli e sorelle! Il nostro messaggio sarà portato alla feccia di questo mondo attraverso il prescelto!"
S["eb158e4e"] = "Isillien!"
S["eb16e467"] = "Sarà meglio che sia l'ultimo!"
S["eb1b9978"] = "Lungo è il cammino di chi intraprende una professione, e ricco di soddisfazioni. Quale via scegli di percorrere?"
S["eb204e09"] = "Scoprire di più su queste creature non è stato facile. Si teme da tempo che il mio amico e la persona che ha assoldato i suoi mercenari per rubare il libro degli incantesimi di Lord Valthalak siano morti entrambi."
S["eb2293a6"] = "$N, abbiamo abbastanza provviste per lanciare assalti via terra. Se la tua reputazione presso la Stormpike Guard è abbastanza alta, parla con Corporal Noreg Stormpike."
S["eb2b6208"] = "L'e'ko è il potere che ogni creatura si porta dentro. Col talismano che t'ho fatto lo puoi catturare in forma fisica.$B$BConosco un incantesimo capace di trasformare in juju l'e'ko che trovi.$B$BPoi prendi la Cache of Mau'ari e con quella rifletti su di te il potere del juju.$B$BDai, provaci. Porta l'e'ko a Mau'ari e ci divertiamo un po'."
S["eb38d8ab"] = "Brzzzzt!$B$B$GBenvenuto:Benvenuta; nel Matrix Punchograph 3005 barra D, terminale con livello di sicurezza delta.$B$BPer accedere alle sue funzioni devi possedere una red punch card.$B$B01010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100"
S["eb398350"] = "Ah, sei $Gun curioso:una curiosa;, eh? Ottimo! Ascolta bene, perché quando le cose si mettono male potrebbe salvarti la pelle!"
S["eb3e57c4"] = "L'Incubo non può essere fermato!"
S["eb5e62a1"] = "%s lancia un grido acuto."
S["eb621097"] = "Quanto durerà l'invasione?"
S["eb653948"] = "NESSUNA PAURA, SOLDATI! OGGI MORIAMO PER KALIMDOR!"
S["eb674f40"] = "L'East Frostwolf Tower è sotto attacco! Se nessuno la ferma, l'Alleanza la distruggerà!"
S["eb6a3b58"] = "Buona giornata anche a te, $Gcoraggioso:coraggiosa; $C. Lo so che cerchi una bella cavalcatura, e non c'è niente di meglio che tenere le redini di un raptor, te lo dico io, sorella! Dai un'occhiata a quelli che ho da offrire — vengono dalla razza più feroce che ci sia."
S["eb76b453"] = "BANG! BANG! BANG! Sto rinforzando la macchina!!!"
S["eb77415d"] = "Oh, $Gun collega Medico:una collega Medica;. Ti insegnerei volentieri tutto quello che potrebbe tornarti utile in viaggio."
S["eb77be40"] = "Che c'è da chiedere? È una scimmia, razza di $Gpazzo:pazza;. Comunque sì, quando ha visto il vecchio Brann stramazzare a faccia in giù nella sabbia, la scimmia è andata su tutte le furie. Qualsiasi cosa facesse l'elfa della notte, non c'era verso di impedire al qui presente Glibb di picchiarla sulla zucca."
S["eb7a136c"] = "Ben fatto, giovane $Gladro:ladra;. Ben fatto davvero...."
S["eb7a8950"] = "Ho finito i tuoi gambali, $N."
S["eb7bfd60"] = "La lotta contro lo Scourge è cominciata bene. Qualche successo l'abbiamo ottenuto, e spero che con il mio aiuto tu ne possa conquistare altri in battaglia."
S["eb81fb64"] = "Dovevo prendere la pillola trasparente."
S["eb886ab7"] = "Per la Luce, oggi ho fame. Avete visto Darcy oggi? Stava benissimo."
S["eb8f6fdf"] = "Spero di aprire presto un negozio tutto mio! Intanto, ti va di comprare qualcosa?$B$BPer finanziare il mio sogno, ogni soldo conta!"
S["eb906a24"] = "Eccola! La Darkmoon Faire ha aperto i battenti! Non perderti lo spettacolo più emozionante di tutta Azeroth!"
S["eb975f8c"] = "Tanto da fare, tanto da fare! Dove se ne va il tempo?"
S["eb997b4a"] = "Abbiamo un sacco di provviste per la ricostruzione. Ancora un po' e ne avremo abbastanza per riparare Dun Baldar e tornare in battaglia!"
S["eba2df34"] = "Thorium Brotherhood o no, se uno di quei Dark Iron mi viene vicino, assaggerà il mio piccone sulla tempia! Allora, ragazza, dove ti spedisco?"
S["eba49908"] = "Non ho altre conoscenze da trasmetterti. Passa sotto l'arco, scendi la rampa a sud-est e parla con Doctor Herbert Halsey: è un Forsaken che può insegnarti tecniche più avanzate."
S["ebb1265a"] = "Chi controlla l'Iceblood Graveyard?"
S["ebd1e3f2"] = "Stalagg schiaccia te!"
S["ebd858a3"] = "Noi eravamo meno di cento, e gli orchi più di mille. Solo una manciata di noi è riuscita a tornare a casa da quella."
S["ebdf86c5"] = "Bel lavoro! Faccio brillare le cariche, così in superficie non arriveranno altri troggs."
S["ebe08388"] = "L'orso ti osserva calmo e paziente, senza dire nulla."
S["ebe4df3c"] = "Ah sì, devi trovare Seikwa. L'ultima volta credo di averla vista davanti alla locanda."
S["ebea3304"] = "È mio..."
S["ebec37f7"] = "È passato tanto tempo, Bethor, amico mio."
S["ebf49029"] = "Non ho niente da insegnarti, se non forse un occhio più attento ai colori e ai dettagli. Parla con Simon Tanner, laggiù: conosce molte tecniche avanzate per lavorare il cuoio."
S["ebfb384d"] = "La Bank of Stormwind è nel Trade District, poco a nord-ovest delle porte della città. Ecco, te la faccio vedere sulla mappa."
S["ebfb4f4f"] = "Chiedi a Kibler del tesoro! SQUAAK!"
S["ec00cc51"] = "Laurna Morninglight cura chi vive nei dintorni di Dolanaar. Forse potrebbe insegnarti le vie del sacerdote."
S["ec031f0e"] = "Bah! Muori!"
S["ec08d19e"] = "Non sei $Gpronto:pronta;. Parla con Betty Quinn, la trovi vicino alle scale laggiù. Torna da me quando avrai raggiunto un'illuminazione più alta."
S["ec08e522"] = "%s cerca un'anima da inghiottire!"
S["ec0dc7a2"] = "Allora fai un salto dai Dawnstrider Enchanters, sull'altura di mezzo: Teg sarà ben lieto di darti una mano come può."
S["ec113b2b"] = "Oh, salve! Io sono Hol'anyee, capo scienziata e biologa della Marshal Expeditions. Con mio fratello e i nostri compagni giriamo Azeroth alla scoperta della sua maestosità selvaggia e indomita. È emozionante... ma, ehm... stavolta credo che di emozioni ce ne siamo procurate un po' troppe!"
S["ec1746f2"] = "Be', ma guarda che $Gsapientone:sapientona;! Ne sai più di me, te lo dico io! Non montarti la testa, eh, ma se vuoi continuare a imparare, va' a fare due chiacchiere con Georgio Bolero a Stormwind. Dicono che di sartoria se ne intenda!"
S["ec19f850"] = "Uccidere te e i tuoi compagni, $C, mi divertirà. Farò in fretta."
S["ec1b4fae"] = "In vita ho dedicato le mie energie a guarire gli altri. Vediamo in morte quanto dolore posso causare!"
S["ec1c42fd"] = "Questa volta ti sei davvero superata, Signora Chambers. Non si trova nemmeno una macchia di muffa!"
S["ec2c355a"] = "Ah, giusto in tempo per la tua purificazione, $R. Strapperò con la ceretta le impurità dalla tua anima."
S["ec2d0a4a"] = "Saluti, $C. È bello vederti $Ginteressato:interessata; ad aiutare lo sforzo bellico. I raccoglitori qui stanno organizzando la raccolta di varie scorte di merci, così saremo pronti quando verrà il momento.$B$BSono $Gincaricato:incaricata; di procurare il baked salmon da mettere da parte per chi combatte ad Ahn'Qiraj. L'ultima volta che ho contato, ne avevamo raccolto una parte."
S["ec2ded14"] = "%s ora è innescata!"
S["ec354ef0"] = "Ce n'è uno a Orgrimmar: vai a nord e parla con uno dei loro grunt."
S["ec3dd41b"] = "Dove sono i cosiddetti eroi di questo mondo? Troppo spaventati per uscire a giocare?"
S["ec458a81"] = "Bene bene, salve. Hai l'aria di chi non disdegnerebbe di fare un po' di soldi, eh? Te lo leggo negli occhi. Sono Mogul Kebok, supervisore delle operazioni ad Azeroth, e se cerchi ricchezze, forse posso combinare qualcosa."
S["ec4ce146"] = "Prima di cominciare qualsiasi lavoro, pulisciti le mani. Una macchia di sangue o di sporcizia sul cuoio toglierebbe qualcosa alla sua bellezza naturale."
S["ec561fc4"] = "Avanzi di verrospino! Questi dovrebbero funzionare. I pesci adorano i verrospini."
S["ec5d6e4d"] = "A Ironforge ci sono già stato. C'è un odore strano, lì."
S["ec5d7ee7"] = "Non puoi passare. Non sei della nostra stirpe e non hai lanciato la sfida."
S["ec5dfe55"] = "Agol ne wirsh ver ne vandar novaedi veld algos nevren? Va se ras uden vrum bor garde?"
S["ec62323a"] = "Ti presenti a noi con un titolo, quindi ti ascolteremo; ma non mettere alla prova la nostra pazienza, $C. Il consiglio non ha tempo per le chiacchiere vane di $Gun:una; come te."
S["ec643874"] = "Ok, $N, andiamo a cercare dove ho lasciato quel fossile misterioso. Seguimi!"
S["ec6515af"] = "A tradire il mio Signore sono stati Geddon e Garr, i Luogotenenti di Ragnaros. Thunderaan è stato colto alla sprovvista."
S["ec6be628"] = "Oh, santo cielo, di nuovo no... Siediti, signorinella.$B$B$GSicuro:Sicura; che Rutgar ti ha già raccontato una parte di questa storia, perciò ti risparmio i dettagli noiosi e vengo dritto al sodo."
S["ec6e967d"] = "Hai stabilito un contatto con Ivus, Arcidruido?"
S["ec70c52d"] = "Il Dun Baldar North Bunker è sotto attacco! Se nessuno la ferma, l'Alleanza lo distruggerà!"
S["ec734e5c"] = "Le vostre anime malvagie nutriranno il mio potere!"
S["ec779b2e"] = "Non vali il mio tempo, $N!"
S["ec781b4f"] = "Anch'io sono felice di vederti, Grim! A quanto pare non tutti gli sconosciuti sono da temere, dopotutto, eh, Grim? Terenthis ricompenserà bene $Gquesto avventuriero:questa avventuriera;."
S["ec7ba57c"] = "Tutti i compiti dello sforzo bellico dell'Orda sono stati completati, giovane $C. Ora non resta che attendere che anche l'Alleanza finisca i suoi, e tutto sarà pronto per la Guerra di Ahn'Qiraj. A parte, forse, la raccolta e la riunificazione dei pezzi dello Scepter of the Shifting Sands?"
S["ec81eb78"] = "AHIA! Così non va!"
S["ec8dda66"] = "Sia lode a Egan!"
S["ec989a60"] = "%s si trova davanti alla Might of Kalimdor."
S["ec9e94b5"] = "Ehm... scusa, ma non ti conosco poi così bene. Voglio dire, come rivenditrice autorizzata di Meccanostruzzi posso vendere le mie cavalcature solo a chi gli gnomi considerano osannato. Se un giorno sarai $Griconosciuto:riconosciuta; come $Gosannato:osannata; presso Gnomeregan, sarò felice di mostrarti cosa ho da offrire."
S["ec9f34d2"] = "Nella Silverpine Forest, ai margini della North Tide's Run, c'è una barca abbandonata, arenata sulla riva. Quello che cerchi è al largo, verso ovest; ma se nuoti troppo lontano, l'oceano ti schiaccerà con la stanchezza. Giace sul fondale, chiuso in uno scrigno, e aspetta che tu venga a reclamarlo.$B$BSenza aiuto sarà dura sopravvivere a un'immersione così profonda, perciò fatti coraggio: una fenditura piena di bolle ridà respiro a chi si immerge per cercare questa metà del ciondolo. Usala con saggezza."
S["ecb72a37"] = "Ti porta l'idromele$BTi porta la birra$BSorridendo da orecchio a orecchio$BServe tutti noi, anno dopo anno$BLo chiamiamo Smiling Jim."
S["ecb88287"] = "Davvero? Invocali, Servitore."
S["ecba5b6d"] = "L'Horde Flag è tornata alla sua base!"
S["ecbcabe3"] = "Se te la senti di ascoltare storie che ti faranno tremare il fasciame e inzuppare le mutande, prenditi da bere e siediti un po'..."
S["ecbce011"] = "Non lasciateli scappare!"
S["ecbee2bb"] = "È inutile che provi a imparare il Draconico, mortale. E poi perché mai vorresti parlare l'antica lingua? Incomprensibile, davvero..."
S["ecdc3b3c"] = "Avvistato un Gruppo da Guerra Qiraji!"
S["ecdf566a"] = "Quando è morta la nostra carne, sono nati il nostro spirito e il nostro sacro compito."
S["ecdfb9d6"] = "Testo Generico"
S["ece24b94"] = "BRUCIA! IL DOLORE... ARDENTE..."
S["ece322f2"] = "Zayus e i suoi sacerdoti stanno nella Spirit Lodge, che è nella Valley of Spirits. Cercala sul lago, più in alto, a ovest della Valley of Strength."
S["ece54ca2"] = "Chi lo sa? In ogni caso, è stata l'ultima volta che l'ho vista. Forse Frankal potrà dirti di più.$B$BNon voglio divagare, e sono $Gsicuro:sicura; che il lavoro che fai per il Comandante sia importante, ma qui abbiamo per le mani una cosa enorme. ENORME! Finora abbiamo chiesto un esercito a Ironforge, ma le nostre richieste sono cadute nel vuoto. Pare che le nostre forze siano troppo sparpagliate a difendere il regno, o qualche sciocchezza del genere. Quando avrai portato il rapporto al Comandante, torna quaggiù con qualche amico. Ci serve il tuo aiuto!"
S["ecfc0a96"] = "Vorrei che la neve si sciogliesse del tutto. Mi bagna sempre la veste e mi manda all'aria ogni cosa!"
S["ed013dbc"] = "Non ha lasciato nemmeno gli stivali..."
S["ed066883"] = "Chi ti ha mandato qui? Non sei ancora $Gpronto:pronta; per le mie lezioni! Quando sarai $Gpronto:pronta;, te lo diranno."
S["ed086ba1"] = "Che ti serve?"
S["ed0c5fcd"] = "Tratta bene il wind rider mentre ti porta a destinazione. Che i tuoi antenati veglino su di te, $N."
S["ed0ee66d"] = "Scansione in corso per rilevare la corruzione."
S["ed33009e"] = "Il futuro riserva molta morte e incertezza, non diversamente dal passato."
S["ed38faa3"] = "Ti sei $Gguadagnato:guadagnata; il privilegio di addestrarti con un istruttore di livello più alto. Va' laggiù, dal mio amico Roxxik."
S["ed407e2b"] = "Non lasciarti fregare dagli umani del Bazaar, $Gragazzo:ragazza;: con la metropolitana che hanno costruito quegli gnomi, far arrivare merci da Ironforge è più facile di quanto credi. E se provano ad appiopparti tasse d'importazione, digli che la roba la compri da me."
S["ed4c4cb3"] = "Si fa a modo mio, o si prende la Gold Road. Chiaro?"
S["ed4d8b9d"] = "Salute, $C — sono $Gun Ufficiale:un'Ufficiale; degli Encomi e agisco per conto di Thunder Bluff. Il mio compito è aiutare gli avventurieri che hanno ricevuto degli Horde Commendation Signets.$B$BAccetto anelli in quantità diverse, ma per te lo scambio più vantaggioso è consegnarmene dieci alla volta. Quando me li porterai, registrerò le tue gesta nei nostri archivi, e così Thunder Bluff riconoscerà il tuo impegno e i tuoi servigi."
S["ed55329c"] = "Le bottiglie su questo tavolo sono tutte pozioni che ho preparato oggi. E dicono che pentola guardata non bolle mai. Ha!"
S["ed571bab"] = "Se cerchi di essere amichevole, risparmiati il fiato. Anzi, smetti proprio di respirare."
S["ed599bdb"] = "<Il ranger davanti a te tiene lo sguardo fisso sull'enorme pilone d'ancoraggio, in lontananza.>"
S["ed68856d"] = "Le razze del mondo periranno. È solo questione di tempo."
S["ed698026"] = "Guardiani! Difendete Sen'jin!"
S["ed6b13dd"] = "Pochi hanno l'ambizione di cercare il vero potere, e ancora meno la determinazione di fare ciò che serve per prenderselo. Il potere è di chi è disposto a pagarne il prezzo, $C."
S["ed71c7f0"] = "Le fatiche dei vivi non smettono mai di stupire. Il vostro numero è limitato, e a ogni battaglia si riduce ancora. Non vivrete abbastanza da vedere la fine!"
S["ed7d06a1"] = "Billy dice che Fizzles una volta era un grande mago. Ma è stato trasformato in coniglio quando uno dei suoi incantesimi è andato storto."
S["ed7d670e"] = "Dimostri una saggezza superiore alla tua età, $C. Grazie. Troverai la nostra maestra delle battaglie, Lylandris, accanto al tavolo di guerra nell'Hall of Arms. Può aiutarti a raggiungere la Warsong Gulch."
S["ed7f303b"] = "Sii purificato!"
S["ed8310b7"] = "Chi controlla l'Irondeep Mine?"
S["ed8be101"] = "Torniamo alla tua base!"
S["ed961de9"] = "Sto scomparendo da $N."
S["ed9d0e50"] = "Qualcosa mi dice che anche questo $N vuole il mysterious fossil. Aiuto!"
S["eda326b3"] = "$GBentornato:Bentornata;, $N."
S["eda8cd78"] = "Affascinante, Custode del Sapere. Continua, per favore."
S["eda8d13a"] = "È gentile da parte tua cercarmi, ma sei più abile di me. Parla con Sylvanna Forestmoon, che è proprio là: sta cercando $Gun altro allievo:un'altra allieva;."
S["edaf162d"] = "The Hall of Thanes è sigillata. Per avventurarsi nelle profondità della vecchia Ironforge, chi non ha udienza da King Magni Bronzebeard deve prima guadagnarsene la fiducia e l'approvazione."
S["edb3e262"] = "Raccoglietevi intorno ai vostri Tenenti e Comandanti, soldati! Tenete a bada i selvaggi!"
S["edb5ed6f"] = "Ah, Zaetar... <Celebras distoglie lo sguardo.>$B$BMio padre, Remulos, ha provato a fermarlo...$B$BZaetar era testardo. Quando si è innamorato di una principessa elementale earthen, mio padre ha capito che quell'unione era maledetta, ma lui non ha voluto sentire ragioni.$B$BI centauri sono il frutto del suo errore. Sono nati deformi e pieni d'odio; mio zio Zaetar è stato ucciso dalla sua stessa progenie...$B$BTheradras, la malvagia principessa, custodisce ancora i suoi resti qui, nelle caverne di cristallo."
S["edbbbae0"] = "Ho scoperto questa grotta il primo giorno che siamo arrivati. Credo che l'energia della pietra possa tornarci utile."
S["edc8350a"] = "Che giornata fantastica per le corse! Oh, ma chi voglio prendere in giro? Per le corse ogni giorno è una giornata fantastica!"
S["edce3794"] = "Sono qui! Vieni ad affrontarmi, se ne hai il coraggio!"
S["edd753c6"] = "Uno stregone, eh... Be', se pensi di fare quel genere di cose da queste parti, faresti meglio a tenere i tuoi demoni al guinzaglio, $Gragazzo:ragazza;. I demoni non mi piacciono, ma piantargli l'ascia addosso lo adoro. Ci siamo capiti?$B$BOra lasciami in pace e vai a perderti in The Forlorn Cavern. Quello stregone, Thistleheart, lo trovi lì."
S["edd95d0a"] = "Fai come se fosse la robaccia migliore che io abbia mai visto. Certo, non è male, ma di roba 'non male' ne vedo tutti i giorni. Facciamo così: trova il modo di stupirmi e ti insegnerò cose che fanno sorridere i nani nel sonno."
S["eddde2a6"] = "È tutto perduto!"
S["ede1fca5"] = "La banca? Oh, vuoi dire The Vault! Per i tuoi oggetti di valore non c'è posto più sicuro di The Vault. Lo trovi subito a nord-est dell'ingresso di Ironforge."
S["edf007b3"] = "È tutto perduto..."
S["edf45e23"] = "Non avevo scelta, o almeno così credevo. Avrei sopportato la distruzione di Thaurissan e sarei $Grimasto:rimasta; al fianco del mio re e della sua gente.$B$BSotto il controllo di Ragnaros, King Dagran Thaurissan ha strappato il cuore a questa montagna e ha innalzato Blackrock Spire. Abbiamo lavorato senza sosta per costruire una città nanica più possente di ogni città o fortezza venuta prima... o che sarebbe venuta dopo."
S["edff02ee"] = "Tu! $N! Cosa ci fai a girovagare per il villaggio così? Ci sono nemici dell'Alleanza ad Alterac! Dobbiamo cacciarli!$B$BLe nostre provviste sono troppo scarse per lanciare un grande assalto via terra, quindi parla col nostro quartiermastro. Ti dirà come puoi aumentare le nostre scorte."
S["ee0d803e"] = "$N, le mie ferite sono gravi. Perdona la mia lentezza, ma non riesco a camminare più in fretta."
S["ee102664"] = "Cosa?! Voi non può battere me! Io tornerà!"
S["ee162e41"] = "Senza uno scopo vagano... Ma molti ritrovano la strada verso i luoghi sacri che un tempo avevano giurato di proteggere."
S["ee1df769"] = "Buona Winter's Vale, $Gamico:amica;!"
S["ee21e864"] = "Oh, vuoi imparare a raccogliere margherite, eh? Ah! Ti prendo solo in giro, $Gragazzo:ragazza;.$B$BÈ un bel mestiere, e Reyna Stonebranch può mostrarti come si fa. Lavora all'Ironforge Physician, sul lato sud di The Great Forge."
S["ee22b19c"] = "Questa non è una giostra, $Gbifolco:bifolca;. Sparisci."
S["ee23c121"] = "Accidenti, pensavo proprio di essere morto. Ugh... mi gira ancora la testa..."
S["ee25e795"] = "Bene, ci stiamo avvicinando al sito di scavo, quindi dobbiamo procedere con cautela. Attivare l'apparato di respirazione subacquea..."
S["ee2c0e38"] = "%s si contorce in agonia. Il Discepolo sembra sul punto di liberarsi."
S["ee2dea65"] = "Devo... RESISTERE!"
S["ee2f23ca"] = "I miei poteri sono tornati e avete sprecato la vostra occasione, sciocchi mortali. Alla prossima volta."
S["ee313662"] = "Aiuto! $GQuesto:Questa; $N non mi si leva di dosso!"
S["ee337fdc"] = "Ti prego, salvami!"
S["ee3e2c9a"] = "%s percepisce la tua paura."
S["ee3e4cda"] = "Non allontanarti troppo. Sono $Gsicuro:sicura; che là fuori ce ne sono altri."
S["ee40bff5"] = "Terenthis, Raene mi ha mandato a cercarti. Le Sentinelle hanno bisogno di aiuto ad Ashenvale."
S["ee4b7b83"] = "Oggi è proprio il tuo giorno fortunato: ho appena finito la manutenzione di Super-Seller 680, e ha un sacco di roba in vendita a prezzi bassi-bassissimi. Avanti, guarda tu $Gstesso:stessa;... mio fratello Cork è convinto che il suo Vendor-Tron 1000 venderà più del mio robot."
S["ee4cc166"] = "Mi chiamo Burninate e il mio mestiere è forgiare... e, ehm... per arrotondare vendo anche un po' di cibo e acqua. Ti va della carne?"
S["ee4e17cb"] = "Salute, $R. Il materiale bellico viene spedito un po' alla volta e dovrebbe arrivare a Cenarion Hold fra pochi giorni. Possiamo solo sperare che, una volta arrivato lì, qualcuno assembli lo Scepter of the Shifting Sands e si faccia avanti per suonare il gong e aprire i cancelli."
S["ee4f605d"] = "Sappiate che, ovunque li troviate nel mondo, stanno proteggendo qualcosa di importante, come fu loro affidato tanto tempo fa."
S["ee50e5bb"] = "Sei qui per addestrarti? O vuoi solo far perdere tempo a $Gun:una; $C?"
S["ee50eabf"] = "Saluti e omaggi dal maniero di Ravenholdt, $Gavventuriero:avventuriera;."
S["ee5711cd"] = "Ti copro io, Vipore. Muoversi!"
S["ee59b708"] = "La Stormpike Aid Station si trova a Dun Baldar, proprio fuori dalla caserma di Dun Baldar.$B$BAl momento è controllata dall'Alleanza."
S["ee6c4b50"] = "Non posso addestrarti io. Ti conviene cercare un istruttore per $Gun:una; $C."
S["ee6d3eb0"] = "Il livello delle MUCCHE non esiste... davvero! Ripeto: il livello delle MUCCHE non esiste. Be', forse sì..."
S["ee705cfe"] = "Uff! Stare in piedi tutto il giorno non è un modo di guadagnarsi da vivere. Avrei dovuto fare $Gil sarto:la sarta;."
S["ee71e7e2"] = "Ti ringrazio per la domanda, ma ho già tutte le bende di lana necessarie per lo sforzo bellico. Ti suggerisco però di chiedere in giro; qui ce ne sono molti a cui probabilmente servirebbe ancora il tuo aiuto."
S["ee722108"] = "Perché sei qui, $N? Hai del piombo negli stivali?$B$BHai tu gli ordini d'attacco — il Warmaster Garrick ne ha bisogno nel Field of Strife prima di poter lanciare l'assalto! Vai!"
S["ee74ba16"] = "Devi salvarci!"
S["ee751d10"] = "%s è colpito da un veleno virulento."
S["ee7bd911"] = "Difendete la barricata!"
S["ee80d5d1"] = "Sì, appena ti scaldiamo starai bene!"
S["ee868a53"] = "Dannazione! Non osare morirmi qui, umano!"
S["ee898788"] = "Guarda dietro di te, $R. L'alveare si agita, e intorno a noi la terra trema e sussulta.$B$BÈ giunta per me l'ora di mantenere una promessa fatta mille anni fa. Ancora una volta le sabbie si muovono, e i Qiraji si preparano alla guerra."
S["ee8da7f0"] = "Ehi, $N. Vieni qui, voglio parlarti."
S["ee9be24d"] = "$GBenvenuto:Benvenuta; al Recinto Amberstill. Se sei $Ginteressato:interessata; a comprare una cavalcatura, mio marito Veron ti aiuterà ben volentieri a scegliere la bestia giusta. Se invece cerchi avventure, be', qui un aiuto ci farebbe proprio comodo..."
S["ee9d1746"] = "Buona fortuna. Mi dispiace di non poterti portare con me!"
S["ee9ff8bd"] = "King Magni Bronzebeard è uno sciocco e un ciarlatano!"
S["eeb67ebb"] = "Casa d'aste noi ha in anello centrale."
S["eeb7fedb"] = "I piloni d'ancoraggio ci tengono sospesi in questo reame, ma fanno anche da barriere protettive! Gli Shal'nan ne hanno parlato, un tempo. Ci tengono al riparo da..."
S["eeb9a0c6"] = "Ormai i giochi son fatti. Tutto il materiale bellico viene trasportato a Cenarion Hold, in Silithus, e arriverà lì fra pochi giorni. Non dovrebbe mancare molto prima che lo scettro venga assemblato e la guerra cominci finalmente."
S["eebb3cde"] = "Fila nell'Undercity, $N!"
S["eebf8584"] = "L'Alleanza ha molti interessi a Desolace, e qui la nostra posizione è precaria.$B$BCi aiuterai?"
S["eec2b98a"] = "Questo completo fa proprio risaltare l'azzurro dei miei occhi, non trovi? Che di abilità ne ho da vendere dovrebbe essere ovvio, quindi posso permettermi di svelare qualche trucco del mestiere. Ascolta bene, d'accordo?"
S["eec364c1"] = "Vuoi addestrarti con Borgus? Sì, posso dirti dove trovarlo. Attraversa la piazza a nord-ovest della mia forgia, poi prendi la strada a ovest. Lo troverai nel secondo edificio sulla destra."
S["eec98cde"] = "Sul'thraze... Avevo più o meno la tua età quando ho sentito pronunciare quella parola per la prima volta. Allora non mi diceva niente, come a te oggi. Ho capito solo quando una banda di guerrieri troll venuta da Zul'Farrak ha devastato la regione... e ho avuto paura.$B$BIn tanti ti diranno che la Lama Spaccata della Sofferenza non esiste. Che è un mito; una diceria messa in giro per spaventare i bambini e farli rigare \"dritto\". Ma credimi, $R, esiste.$B$B<Trenton perde il filo e si passa la mano sulla cicatrice frastagliata che gli segna il volto.>"
S["eec9a235"] = "Un bicchiere per l'amico Sarok e un altro per me."
S["eecc5ad7"] = "Se vuoi imparare a estrarre minerali, faresti meglio ad andare a Stormwind, nel Dwarven District. Di sicuro uno dei nani che stanno lì può insegnarti la professione."
S["eed93e42"] = "Me uccidere te morto!"
S["eed947c4"] = "Kel'Thuzad dire di dirti... MUORI!"
S["eedaaac1"] = "Lo Stormpike Graveyard è scavato nelle montagne, oltre il ponte a est di Dun Baldar.$B$BAl momento lo controlla l'Orda."
S["eedc0102"] = "Onore alla tua casata e ai tuoi antenati, $C! Troverai Kartra Bloodsnarl dentro l'Hall of the Brave, nella Valley of Honor."
S["eeddf890"] = "Alla faccia del potere della natura... muhahahaha."
S["eede2b5d"] = "Scalporosso, Sabbiafurente, Fendicranio, i Vilebranch e Scorzasecca. Tutti giurano fedeltà a Jin, e le loro anime a Hakkar. Hai perso."
S["eee74e03"] = "Questa non è la tua battaglia, straniero. Proteggiti dagli attacchi del Crimson Elite. Io combatterò il Gran Inquisitore."
S["eeeb126c"] = "Nessuno? Lo pensavo. Torna da Elaadrin e digli che l'unica cosa che mi impedisce di marciare con i miei sciamani e gettare voi ciarlatani da quest'isola è la crisi attuale."
S["eeefa080"] = "Ripensandoci... credo che lascerò perdere."
S["eef128fa"] = "Hai intenzione di lasciare che un nano ferito faccia tutto il lavoro al posto tuo?"
S["eef8aa18"] = "Che battaglia. Prendiamo fiato per un po'."
S["ef02beab"] = "Pawene ich awak awak tanka! Zhi sho'wa no lomani tawaporah!"
S["ef05ac4a"] = "Sconosciuto"
S["ef0b68da"] = "Togliti il travestimento, se non vuoi assaggiare la mia lama quando la furia avrà preso il sopravvento."
S["ef188d4b"] = "Per me i goblin hanno la vittoria in tasca. Gli attrezzi ce li abbiamo, e il talento pure!"
S["ef1a2baa"] = "Fuochino... 7039 gradi Kraklenheit!"
S["ef1a3c29"] = "Sei $Gvenuto:venuta; per il sapere di Hgarth?"
S["ef223de8"] = "Oggi la schiena mi sta ammazzando."
S["ef2490d7"] = "Aamelia, mia cara. Dov'è Alvarion? Ha troppa paura di venire ad affrontare Ferauu, così ha mandato te?"
S["ef2a7555"] = "Mi piaceresti di più con un po' di profumo addosso."
S["ef2b42d2"] = "Attento a dove metti quel piede, signore. Mica abbiamo tutti la fortuna di essere alti quanto un $R."
S["ef37202c"] = "Icy Scale Gauntlets."
S["ef3a4625"] = "$GUno:Una; skyborne $Gvivo:viva;... presto $Gun morto:una morta; come me."
S["ef551db2"] = "Fuori dalla Banca, al centro di Darnassus, trovi una cassetta della posta."
S["ef5fc5c9"] = "Esplosione tra 5 secondi. Fuori dalla galleria! Stai indietro!"
S["ef65127e"] = "La fortuna è mia, Alexi! La tua fine è vicina!"
S["ef8027d9"] = "Mi fido di pochi della tua specie, $N. Ma vedo che sei $Gun amico:un'amica;."
S["ef826663"] = "Durante le tue battaglie contro lo Scourge a Naxxramas, se trovi merlature profanate e pezzi di piastra logorati dalla guerra, riportameli e ti realizzerò un pezzo di questa armatura indossata dagli eroi."
S["ef8303dc"] = "Di tutta Azeroth, la torta di ciliegie è il mio cibo preferitissimo."
S["ef863bc7"] = "Le tue azioni ci disonorano tutti, $C. Mi fa male dentro, mentre ti pesto fino a farti perdere i sensi."
S["ef8b9d30"] = "Le vie di Jaedenar sono oscure e infide. Qui sta' $Gattento:attenta; a come ti muovi, $C, o i tuoi rivali ti soggiogheranno l'anima..."
S["ef927b1b"] = "Ignorando la battaglia che infuriava intorno a lui, Latherion abbassò la guardia per stringere la sua amata negli ultimi istanti. Ma i demoni non ebbero pietà e lo abbatterono in fretta."
S["ef981fa7"] = "Ehi! Via di lì!"
S["efa05afb"] = "%s è visibilmente $Gscosso:scossa; dalla morte di Emperor Thaurissan."
S["efa9298e"] = "Mi serve un altro set di attrezzi."
S["efabbf00"] = "Questa piccola bestia immonda è l'imp. È piccolo e debole, quindi quasi inutile come scudo di carne, e i suoi danni sono mediocri nel migliore dei casi. Questa creatura dà il meglio come supporto in un gruppo più numeroso."
S["efb52ab0"] = "Maledizione a te!"
S["efb8a2f7"] = "Su, su, $N, non preoccuparti! Quale pezzo dell'amuleto hai perso?$B$BHai controllato tutte le tue borse e la banca?"
S["efbfda6f"] = "Non dobbiamo cedere al male che ha oscurato la nostra terra. La Night Watch deve prevalere!"
S["efbfeafc"] = "Mi sa che sto cominciando a scavare un solco nel selciato."
S["efc53627"] = "Sulle colline a est di Stormwind vive un erborista, insieme al nostro alchimista. Proprio una coppia comoda, non trovi?"
S["efc7aa85"] = "Ho vinto!!"
S["efcac314"] = "Ciao, Sovik, vorrei dare un'occhiata alla tua merce."
S["efd27c90"] = "Eccone una! Per l'Orda!"
S["efd50c02"] = "Ciao, $Gamico:amica;."
S["efdb6cac"] = "Perché mi hai evocato così presto? Non ho ancora raggiunto tutto il mio potere!"
S["efec66a5"] = "Al lavoro, fannulloni!"
S["efef65b2"] = "Krathok, un tempo ero $Gun forgiatore:una forgiatrice; di armature e desidero riprendere in mano il martello ancora una volta! Insegnami la via del forgiatore di armature."
S["eff42141"] = "Salute, $C.$B$BSe vuoi, posso mostrarti come intessere la magia intorno a te e cambiare l'aspetto del tuo equipaggiamento. Vuoi avvalerti dei miei servizi?"
S["effa44ac"] = "Saluti. Sono un'istruttrice di magia, e tu sei $Gun mago:una maga;."
S["f003533d"] = "Il Flagello nel Trade District! All'attacco!"
S["f00758a7"] = "Lassù Lorthuna sta compiendo una specie di rituale. Forse sta cercando di abbattere le protezioni!$B$BL'aiuto che abbiamo chiesto non è ancora arrivato, ma dovremo arrangiarci con quello che abbiamo. Quando sei $Gpronto:pronta;, dimmelo e andremo ad affrontarla."
S["f00e1223"] = "$GBenvenuto:Benvenuta; nella nostra umile casa. Se hai bisogno di asciugarti, riposati accanto al fuoco."
S["f00e3faf"] = "Levatemi di dosso $Gquesto:questa; $N!"
S["f016eb90"] = "Portateli fuori dalle sale; non vogliamo curiosi che ficcano il naso."
S["f01b7f53"] = "So un paio di cose. Vuoi che te le mostri?"
S["f02e89b4"] = "Non lasciarmi morire!"
S["f02f9dbf"] = "Il maestro dei grifoni sta sul bastione a nord-est, quello che si affaccia sulla Valley of Heroes."
S["f032bdef"] = "L'Alterac Valley è la casa del Frostwolf Clan da anni; non permetteremo ai nani e alla loro Alleanza di invadere le nostre terre! E così combattiamo!$B$BPer riconquistare Alterac, sconfiggi il loro generale, Vanndar Stormpike, a Dun Baldar.$B$BPer l'Orda!"
S["f036f2ee"] = "Ehi, Raven..."
S["f03d1f66"] = "Ehilà! No, l'officina non è mia! Ma un giorno, finito l'addestramento, diventerò un'inventrice, proprio come il mio eroe, Marvon Rivetseeker.$B$BNon l'hai mai sentito nominare? Be', si dà il caso che sia partito parecchio tempo fa per studiare certe antiche rovine troll di cui parlava sempre. Se n'è andato con uno zeppelin... dove, di preciso, non ne sono proprio sicura...$B$BTanarasin? Tenkeris? Taneranisany?$B$B<Liv scuote la testa.>$B$BNo, non è quello..."
S["f03f03e2"] = "Elder Farwhisper lo trovi a vagare per le strade di Stratholme."
S["f04d51cc"] = "L'istruttore degli sciamani lo trovi vicino alle pietre erette del Windshaper, al margine occidentale del villaggio."
S["f04f02ad"] = "Iiik! $N viene dritto verso di noi!"
S["f05455d1"] = "Come osi provare a zergarmi, $Gsmidollato:smidollata;!"
S["f06ae3db"] = "Mi metto subito al lavoro, $N!"
S["f07a375e"] = "Fatti avanti! Le red hot wings sono qui!"
S["f07b0b1d"] = "Qui va bene. Da qui in poi me la cavo da solo. Adesso che mi sono sgranchito per bene, vado spedito. Ehi, di' a Wharfmaster Lozgil che mi hai salvato. Sarà felicissimo di sapere che sono ancora vivo, ne sono sicuro!"
S["f0932ca8"] = "La tua perspicace affermazione trova effettivamente riscontro nei dati conservati in questo archivio.$B$BIl nano conserva un'affinità con la composizione rocciosa di Azeroth; a causa dell'anomalia ambientale ad alto stress all'interno della matrice di sintesi dell'Earthen, però, regredisce a una composizione di biomassa predefinita, come si osserva nella matrice sotterranea standard.$B$BErgo, come hai dedotto con la tua interrogazione, la variante nanica deriva effettivamente per sintesi dalla degenerazione della matrice di creazione dell'Earthen."
S["f0933318"] = "Parlami ancora delle torri..."
S["f09c52e7"] = "%s comincia a strofinare la Tear of the Moons."
S["f0a0a7ab"] = "Uldaman è un antico caveau dei Titani, rimasto sepolto sotto terra fin dalla creazione del mondo. Scavando nella città, i nani hanno di recente liberato le prime creazioni fallite dei Titani: i troggs. Narrano le leggende che i Titani, dopo aver giudicato un fallimento l'esperimento dei trogg, ci riprovarono, e da qui nacque la razza dei nani. Questi segreti sono registrati sui leggendari Dischi di Norgannon — enormi artefatti che giacciono in fondo all'antica città, sorvegliati da giganteschi costrutti di pietra vivente."
S["f0af59a5"] = "I vostri sforzi sono del tutto inutili, stolti! Non riuscirete mai a sconfiggermi!"
S["f0b4325f"] = "Tanto tempo fa, prima dell'ultima grande guerra, mio padre mandava avanti Northridge Lumber Mill. Era tutta la sua vita, e ci metteva l'anima. Poi è arrivata la guerra e, per quanto gli costasse, siamo dovuti fuggire a Stormwind.$B$BIn quei giorni abbiamo perso diversi amici e parenti, e mi fa male sapere che la Scarlet Crusade si è presa la segheria per i suoi scopi.$B$BPer questo sono tornato."
S["f0b8218a"] = "Ho visto la corruzione colpire quattro diversi tipi di piante: il fiore canoro, il fiore del vento, la radice frustante e la pianta del drago notturno. Il fiore canoro e il fiore del vento sono comuni a Felwood; la radice frustante e il drago notturno, invece, si vedono più di rado. Per l'ecosistema di Felwood sono tutte fondamentali."
S["f0c67ac2"] = "Guardo nell'occhio..."
S["f0c801cd"] = "Hai voglia di farti un giro in grifone, eh? Dungar i suoi uccelli li tiene sul bastione nel Trade District. Solo, ricordati di tenerti forte!"
S["f0cd5ca5"] = "Oh, parli di Johnson? Ho sentito che si è nascosto."
S["f0d13f8b"] = "Accidenti, qui i pesci non abboccano proprio. Forse dovrei andare a tentare la fortuna al Crystal Lake!"
S["f0d47e81"] = "Ti prego, dimmi che non hai appena fatto quello che penso. Ti prego, dimmi che non dovrò farti del male..."
S["f0d71485"] = "Le bestie di queste terre devastate mostrano attributi preternaturali che finora non si erano mai visti in natura.$B$BAbbiamo ipotizzato che l'energia sprigionata all'apertura del Dark Portal sia penetrata nei loro corpi, costringendo le creature a evolversi fino alle forme che hanno oggi.$B$BNon c'è dubbio, sono bestie temibili, ma crediamo anche che potrebbero rivelarsi assai utili per i nostri studi.$B$BForse ti interesserebbe aiutarci a studiarle, $N?"
S["f0d88160"] = "I Paragoni del Potere sono mojo potente. Mojo del Gurubashi Empire. Noi Zandalar dobbiamo prendere mojo. La tribù prenderà mojo per noi. Il Dio del Sangue non ci distruggerà.$B$BA Zul'Gurub ci sono tre tipi di Paragoni. Cerca monete. Cerca bijous. Cerca oggetti primordiali. Questi sono i Paragoni.$B$BOra vai a Zul'Gurub. Uccidi. Prendi i Paragoni del Potere. Portali alla tribù. Guadagna il nostro rispetto. Guadagna il nostro equipaggiamento da battaglia. Guadagna potere vero."
S["f0d95107"] = "Il Patchwerk vuole giocare!"
S["f0ef45c5"] = "Ograbisi vuole cappello nuovo!"
S["f0f06109"] = "Sono qui per l'oro."
S["f0f6eb18"] = "A Nighthaven! Tieni vicino il tuo esercito, $Gcampione:campionessa;."
S["f0f96b61"] = "Hai idea di cosa mi tocca passare per portare fin qui, in vendita, questi oggetti preziosi senza pari? Vieni a vederli tutti con i tuoi occhi!"
S["f0f9b650"] = "È Proudmoore! Via di qui!"
S["f0fdd70f"] = "Predoni a nord! Fuoco!"
S["f1028924"] = "Har! Hai paura che danneggi il tuo piccolo elegante bolide da corsa?"
S["f104d69a"] = "$GBenvenuto:Benvenuta; alla Pig and Whistle! Prenditi da bere e accomodati, $Gamico mio:amica mia;: più siamo, meglio è!"
S["f10cca74"] = "Seguitemi, amici. A Stormwind Keep!"
S["f10fd23e"] = "Non vedevo un'armatura così ben fatta da molti anni, $N. Non da quando mi addestravo con Grumnus Steelshaper alla Great Forge. Scommetto che potrebbe insegnarti sulle armature cose che ti accenderebbero l'interesse."
S["f1186b6e"] = "$N, stamattina è arrivato questo per te."
S["f118f2d0"] = "HAKKAR VIVE!"
S["f11d90e4"] = "Aziris vrum lo vil vassild? Algos goth me barad! Thor!"
S["f127f735"] = "Beh, da quello che ho capito mentre aspettavo di essere mangiato da questi bifolchi... potrebbe non essere necessario uccidere tutti gli ogre che trovi qui.$B$BL'altro giorno gli ogre non la finivano più di raccontare come King Gordok è salito al potere: in pratica ha ucciso il re precedente e ne ha preso il posto. E gli scagnozzi del re, quelli che Gordok ha risparmiato, hanno subito giurato fedeltà al nuovo re.$B$BChissà: l'ogre che risparmi potrebbe diventare il tuo... in senso figurato, s'intende!"
S["f12ee56f"] = "Là freddo! Tu va in Royal Quarter e parla con Grizzle Halfmane."
S["f133ed2b"] = "Il titolo inganna. In realtà, una volta che mi conosci, sono una persona molto simpatica."
S["f140b293"] = "Nemico avvistato! Fuoco!"
S["f145827c"] = "Lo stato del mondo salvato è:"
S["f149bb57"] = "Darianna promette bene, ma è così piena di energia che fatica a stare ferma ad ascoltare. Forte e agile com'è, temo che presto verrà chiamata a combattere. Dobbiamo istruirla in fretta."
S["f14d5ba2"] = "Noi piantiamo le verdure, e il coniglio se le mangia. Il lupo divora il coniglio, e noi uccidiamo il lupo. Dal suo cadavere prendiamo la carne e la pelle. È quel Magico Cerchio della vita, o come lo chiamate voi.$B$BOra va' da Telonis nella Cenarion Enclave per cominciare, e lasciami tornare ai miei compiti."
S["f15c3746"] = "Rane e palle di cuoio in vendita!"
S["f163666b"] = "%s emerge dalle ombre per difendere il calderone!"
S["f164a117"] = "La Dama Oscura ha lanciato la sfida. Ora tocca alla Royal Apothecary Society mettere a punto una nuova piaga. Metteremo in ginocchio Arthas e il suo miserabile esercito."
S["f16f8ce0"] = "Certo, $N.$B$BPer accedere agli oggetti superiori, gli avventurieri che l'Alba considera onorati devono consegnare 40 insegne in tutto. Per quelli ancora più potenti, il totale sale a 150.$B$BLo ammetto, è un prezzo alto anche per chi è onorato presso l'Alba."
S["f178b90d"] = "Algos nandige! Thor!"
S["f1798335"] = "%s riempie un contenitore con la tossina."
S["f1802eb6"] = "Troverai Fineous Darkvire oltre il Ring of Law, nell'Hall of Crafting. Uccidi quel miserabile cane e recupera Ironfel.$B$BPorta Ironfel allo Shrine of Thaurissan e metti il martello al suo giusto posto: Nelle mani della statua eretta in mio onore.$B$BQuando sarà fatto, si aprirà lo scomparto in cui ho riposto la chiave maestra. Ma soprattutto, Ironfel resterà per sempre nella mia stretta. Se tentassero di rimuovere il martello; sia la statua che il martello andrebbero in frantumi, perduti per sempre."
S["f189e2db"] = "<Tarsis ti afferra debolmente per il colletto. Pur in punto di morte, nei suoi occhi vedi un potere inimmaginabile.>$B$BDavvero? Allora ascolta bene, perché mi stanno per uscire di bocca altre sciocchezze. In questa cittadella troverai l'opera della mia vita: la posizione esatta di ogni frammento del bastone spezzato."
S["f191d0d7"] = "Sii guarito, sacerdote."
S["f1977781"] = "Silenzio! Pensi che i nostri draghi appestati nascano e si addestrino da soli?"
S["f19f5663"] = "Stavolta faresti meglio a darmi man forte!"
S["f1a3f60e"] = "Jin'rokh, mi serve aiuto per recuperare un pezzo della mia Armatura del Libero Pensatore."
S["f1a41fed"] = "Ti ringrazio. A essere sincera, però, rischia di essere un tentativo azzardato e potremmo non farcela. Devi capire che potrebbe essere un viaggio di sola andata."
S["f1a4bbec"] = "Non posso lasciare il mio posto, $N, ma c'è un compito di cui bisogna occuparsi. Posso contare su di te per portarlo a termine?"
S["f1a9474a"] = "Druidi? Qui intorno non ne ho visti. A Stormwind, però, c'è un distretto che gli elfi della notte hanno fatto loro."
S["f1afa4d4"] = "Sono un uomo semplice e di sartoria qualcosa ne so, ma a te serve più aiuto di quello che posso darti io. Ho sentito parlare di un Elfo della Notte, un sarto davvero abile, che vive a Stormwind, nel Magic District."
S["f1b547af"] = "Forza, gente, sveglia!"
S["f1c5da1f"] = "Io da qui non mi muovo finché non prendo una Cernia da 68 Libbre! Tu invece vuoi volare da qualche parte, vero?"
S["f1c6d45f"] = "Porto notizie del nostro conflitto con $Gil:la; $R Ribelle."
S["f1c8d2a4"] = "Kobolds buoni a nulla!"
S["f1c8e535"] = "Io e mio fratello abbiamo una missione della massima importanza, ma ce ne stiamo rintanati in questa fattoria. Ai Deathstalkers serve il tuo aiuto."
S["f1cd0e87"] = "|cffffff00La Torre di Passo Nord è stata conquistata dall'Alleanza!|r"
S["f1dacc24"] = "Darrowshire è sconfitta! Presto tutta Lordaeron cadrà!"
S["f1df3ac7"] = "Paladini... ho sentito dire che avete molte vite. Mostratemele."
S["f1e30c05"] = "Giusto una piccola regolazione... ah, ecco fatto!"
S["f1ec9606"] = "Cosa ti porta alla Torre?"
S["f1efb427"] = "Ho bisogno di indicazioni."
S["f1f96eec"] = "Quanti dei nostri Luogotenenti sono ancora vivi, Drek'Thar?"
S["f2038a44"] = "Io non addestro fabbri senza talento. Torna quando avrai qualcosa di decente da farmi vedere."
S["f207a7cf"] = "Devo allenarmi di più."
S["f208975f"] = "Orsi??"
S["f20a9c67"] = "Ah, $C, che piacere vederti. Ci serve aiuto per raccogliere provviste in preparazione della guerra imminente ad Ahn'Qiraj. Mi hanno chiesto di preparare un gran numero di kit da campo di pronto soccorso, e il componente principale che mi serve sono le wool bandages. Ne ho già un po', ma devo raccoglierne ancora."
S["f21097c7"] = "$N ha conquistato la Bandiera dell'Alleanza!"
S["f2116e3f"] = "Dover combattere contro la mia stessa specie mi rattrista profondamente."
S["f212797a"] = "Vai al Freewind Post, a Thousand Needles: lì troverai Elder Skyseer."
S["f21b51c2"] = "Quando prepari il pasto del drago, assicurati di torturare il prigioniero sotto gli occhi del drago. Gradisce molto un po' di intrattenimento prima del pasto."
S["f21cff03"] = "Mi prenderò i tuoi soldi e anche la tua vita!"
S["f22117ea"] = "Kil'jaeden è la mia risposta."
S["f222d257"] = "Gli shen'dorei saranno sempre in debito con gli spiriti per il loro aiuto, e i Windshapers hanno giurato di saldare quel debito e di riportare le cose com'erano prima. Purtroppo, senza gli spiriti a guidarci, siamo pericolosamente ciechi a quello che succede intorno a noi dentro Skywall.$B$BL'High Order è miope e arrogante, proprio come i suoi antenati alti nobili, e cerca di dominare e controllare la magia di questo luogo. È proprio la strada che a suo tempo ci ha costretti a fuggire da Kalimdor e a stabilirci qui. Temo che, come per i nostri avi, la sua sicurezza abbia superato di gran lunga la sua competenza, e il risultato potrebbe essere disastroso."
S["f2333511"] = "Accidenti! $N mi è addosso!"
S["f235ef10"] = "Mamma! Possiamo andare a giocare, ti prego ti prego ti prego? Possiamo, eh? Possiamo?"
S["f2361ab6"] = "Noi sa dove stanno! In Magic Quarter, su anello esterno di città: edificio con teschio."
S["f236dcde"] = "Ciao $N! Grazie per tutto l'aiuto che mi hai dato! Per ora non mi serve niente, ma chi sa cosa ci riserverà il futuro?$B$BDivertiti, e ricordati di parlare ai tuoi amici della Darkmoon Faire!"
S["f238e8d5"] = "E voi, eroi... Custodisco ciò che cercate. Possa vedere ancora una volta il male dissolversi. Remulos, provvedi affinché il nostro $Gcampione:campionessa; riceva il frammento del Green Flight."
S["f243ada4"] = "Fishmaster Bassbait ha fatto popolare queste acque di Tastyfish di alta qualità per tenere il suo torneo.$B$BQuando avrà il vincitore, per ogni cinque Tastyfish che mi porterai ti darò dell'argento!"
S["f24fc727"] = "Premi! Venite a prendere qui i vostri premi! Venite qui e consegnate i vostri Biglietti Premio della Darkmoon Faire in cambio di premi preziosi!"
S["f267098b"] = "Toglimelo di dosso, $N!"
S["f26a1e8c"] = "Sono assolutamente $Gsicuro:sicura; di voler imparare la conciatura tribale."
S["f27128c4"] = "$GBenvenuto:Benvenuta; al Wickerman Festival, $C!$B$BPer festeggiare l'Hallow's End, la più venerata delle ricorrenze, i Forsaken bruciano in suo onore un fantoccio di vimini. Proprio in questo giorno The Banshee Queen in persona ci ha strappati alle grinfie di The Lich King e dello Scourge, e da allora siamo rimasti liberi. E chi avrebbe voluto vederci cadere riceve quel che gli spetta... la vendetta!$B$BIl rogo del Wickerman comincia alle 8:00 PM!"
S["f271ba2b"] = "Le nostre forze sono pronte alla battaglia e non vedono l'ora di versare il sangue dell'Alleanza. Presto il nostro capitano entrerà nell'Iceblood Garrison e la guerra ricomincerà!"
S["f2767dc1"] = "Contro un incantatore di qualsiasi tipo, questa bestia feroce sarà la tua migliore amica. Ora vediamo qualcosa di un po' diverso. La prossima creatura ti aiuterà negli spostamenti e renderà molto più facili i tuoi viaggi futuri. Diamo un'occhiata a un Vildestriero."
S["f276842a"] = "Oggi saltano fuori da tutte le parti. Continuiamo a muoverci, o troveremo altre cose che mi vogliono morto."
S["f2797978"] = "Ahhh, allora cerchi lo Stormwind Visitor's Center. Se arrivi dalla Valley of Heroes, appena passati i cancelli principali è il primo edificio sulla sinistra."
S["f2824afd"] = "L'enorme bulbo oculare fluttuante al centro della sala volge lo sguardo su di te. Sei al cospetto di un dio."
S["f2883edb"] = "Beh, 'sti pesci non abboccano più, quindi tanto vale che mi metto a sventrare e pulire quel che ho preso oggi."
S["f295ee12"] = "$GBenvenuto:Benvenuta; a Stormwind. Per ricostruirla ci è voluto tanto tempo, ma ne è proprio valsa la pena. Allora, sei qui in visita o per affari?"
S["f2983c83"] = "$N, ecco! Finalmente ci sono arrivato!"
S["f29c7348"] = "Non si rubano le merci!"
S["f29d9225"] = "Sei $Gsicuro:sicura; che sia la strada giusta? Forse dovremmo andare da questa parte..."
S["f2a2eafa"] = "Si va a Darkshire, allora, suppongo."
S["f2a2f42a"] = "Ti proteggerò!"
S["f2b46f44"] = "Tu! Entra nella mischia!"
S["f2c73f7b"] = "Non stai cercando di uccidere l'incudine con il martello, stai cercando di creare un'arma con cui uccidere i tuoi nemici. Lascia che ti mostri cosa sbagli."
S["f2c8ca3b"] = "Pesciolino, pesciolino... vieni dal papà."
S["f2cb5009"] = "Il male mi fa venire così tanto sonno..."
S["f2cc06cd"] = "Ingegnere? E che cosa sarebbe, in nome di Skywall?$B$BOra che me lo dici... mi sembra di aver sentito quell'ubriaco di Sirrocas, alla locanda, raccontare di una specie di spirito della foresta che diceva di aver incontrato e che si faceva chiamare \"ingegnere\".$B$BNon avevo mai sentito parlare di una cosa del genere.$B$BMi pare abbia detto che lo spirito sta da qualche parte nella Shadowgale Forest, ma in quel posto maledetto non ti consiglio di andarci!"
S["f2d80a90"] = "Ehi, $N! Non scordarti di prendere una cassa, un manuale e una bacchetta di comando!"
S["f2e4653e"] = "Battete le mani, tutti quanti, e tutti quanti battete le mani!"
S["f2e6fc3a"] = "%s è in preda a una furia da ubriaco!"
S["f2e848c5"] = "%s si rifiuta di morire finché il suo padrone è in pericolo!"
S["f2f33b3c"] = "Lo Snowfall Graveyard appartiene all'Alleanza."
S["f2f8002e"] = "sembra avere molto sonno..."
S["f304f44f"] = "Sono perduti, $R. Compendi scritti dai maestri elfici e dispersi per il mondo quando su Quel'Thalas è stato scatenato lo Scourge.$B$BOra li cerchiamo, per scoprire i segreti che custodiscono — e riavere il potere di un tempo.$B$BIo cerco i dieci scritti da Master Kariel Winthalus. Se trovi un compendio, lascia che ne assorba le proprietà magiche e creerò per te un amalgama di potere... naturalmente, ogni cosa ha il suo prezzo. Scoprirai che il mio è alto; ma pagare dovrai."
S["f3056d6a"] = "STOLTO! HAI PERMESSO A QUESTI INSETTI DI SCORRAZZARE PER IL NUCLEO SACRO? E ORA LI PORTI FIN NELLA MIA TANA? MI HAI DELUSO, EXECUTUS! GIUSTIZIA SARÀ FATTA, ECCOME!"
S["f3072605"] = "Cosa ne facciamo di loro, padrone? Non ci servono più a niente."
S["f3091157"] = "%s comincia a lanciare un incantesimo sui cuori e sulle lingue."
S["f30c75dd"] = "CIAO MONDO!"
S["f3147df8"] = "Il Grande ti schiaccerà!"
S["f3195066"] = "Non può essere sconfitto. <La reliquia brucia fino a sparire. I ricordi che custodiva ora sono tuoi. Questa città è stata distrutta da un essere che non è di questo mondo.>"
S["f31a84b8"] = "Se mi aiuti, posso esaminare queste gallerie."
S["f31faa87"] = "È il momento di salvare tutta la razza gnomesca. Vada come vada!"
S["f328e051"] = "Fai meno chiasso e ascolta di più."
S["f332c29f"] = "Anche i miei talenti hanno un limite, e tu l'hai raggiunto. Congratulazioni, $N. La tua prossima tappa dovrebbe essere Camp Mojache a Feralas, dove vive la tauren Hahrana Ironhide, famosa per la sua abilità."
S["f3360a40"] = "Ancora un pochino, ci sono quasi!"
S["f338e80e"] = "L'unica arma che io conosca che non serve ad altro che a uccidere qualcuno. Non qualcosa, ma qualcuno. Queste lame sono state inventate per porre fine alla vita degli uomini. Belle, vero?"
S["f33c7e48"] = "Se l'High Order si preoccupasse almeno un po' di risolvere davvero i problemi che abbiamo davanti e passasse meno tempo ossessionato dalla magia antica, come popolo saremmo in una situazione molto migliore. Tanto per cominciare, è stata la magia degli altonati a causare la rovina dei kaldorei. Quegli sciocchi pieni di sé vogliono ripetere quegli errori!$B$BGià il fatto che abbiano cercato di fare pace con il culto è abbastanza grave, ma versare sangue Windshaper è davvero imperdonabile. Se non fosse per la minaccia imminente del culto, radunerei le nostre forze e andrei a farla finita con Elaadrin e l'High Order una volta per tutte."
S["f34c07c3"] = "Sono Tinkmaster Overspark, e nel mondo di oggi sono io il capo architetto dei principi moderni dell'ingegneria gnomesca. Il mio compito è fare in modo che il potere dell'invenzione continui a splendere dalle nostre arclight spanners più intenso che da qualsiasi altra parte!$B$BE poi, se ti capita di conoscere un buono schema per eliminare le radiazioni, guarda caso ne cerchiamo proprio uno in questo momento..."
S["f34faf54"] = "Ehi, ehi, ehi, aspetta, cos'è stato?"
S["f3554382"] = "Vanndar Stormpike è il generale dell'esercito dell'Alleanza ad Alterac, e guida le sue forze da Dun Baldar.$B$BSe verrà sconfitto, l'Alleanza perderà di sicuro la battaglia per Alterac."
S["f35b767f"] = "Sto per darle di santa ragione a $N."
S["f36024e7"] = "Grazie ancora per aver aiutato Hilary, signorina! Da grande voglio diventare un eroe proprio come te!"
S["f3667030"] = "Non ho altro da insegnarti. Ho sentito parlare però di un'elfa della notte che forse ci riesce. Si chiama Ainethil e vive nella Craftsmen's Terrace of Darnassus."
S["f3696593"] = "%s spolvera la base del manufatto."
S["f36b9b50"] = "Curate le ferite dei feriti, sorelle!"
S["f36decbc"] = "$N! Come te la sei passata, $Gragazzo:ragazza;? Fammi vedere cos'hai imparato da quando t'ho visto l'ultima volta, così vediamo se c'è qualcosa di nuovo che posso insegnarti."
S["f37ab265"] = "Cos'è questo? Keever ha forse chiesto una pecora? Keever voleva un'arma di grande potere e tutto quello che ha avuto è questa pecora. Keever è molto deluso."
S["f37b8aed"] = "Cerchi Tai'jin. La trovi nella caserma, sul lato est della città."
S["f38b32b7"] = "Il capo vuole tutti in massima allerta. Stanotte l'ancora arrugginita affonda."
S["f38d8572"] = "Che ti aspetti, mon?$B$BMaywiki fa affari solo con druidi e sciamani."
S["f38e4b05"] = "Attorno alla tua carcassa nascerà un nuovo mestiere, $N. Lo chiameremo 'lavorazione della carne'."
S["f38e6bca"] = "Ho appena finito di girovagare."
S["f3967c59"] = "Così vuoi diventare un Fabbro, eh? Allora prendi grembiule e martello, $Gragazzo:ragazza;, e vediamo cosa sai fare."
S["f398abf5"] = "Sei già $Gmorto:morta;."
S["f399de8a"] = "Prendetelo! Prendete quel criminale da quattro soldi e i suoi alleati!"
S["f39e2434"] = "Ho sentito dire che là sotto ci sono ancora degli orchi sepolti."
S["f39e77cd"] = "Adesso ci vorrebbe proprio un bacio. Sai dove potrei trovarne uno?"
S["f3a0f801"] = "Ad alcuni è stata risparmiata l'angoscia che i ricordi si portano dietro."
S["f3a3ccb9"] = "Quello che faccio sempre, ovviamente. Rimugino. Mi struggo. Odio. Tramo. Finito il giro, si torna a rimuginare. Che vuoi da me? Ho molto a cui pensare."
S["f3af6fd9"] = "$GBenvenuto:Benvenuta; alle corse! Goditi il soggiorno, e non puntare tutti i soldi su una macchina sola!"
S["f3b1223d"] = "Come fu predetto una vita fa a Karazhan, mostro, io vengo, e con me porto la giustizia."
S["f3bc0707"] = "{Un $C} di nome $N? Sarai un'ottima colazione!"
S["f3c0e550"] = "Non è la razza a fare l'onore, $R. Finché starai nella mia fattoria, ti chiedo di ricordare e rispettare questo credo.$B$BHo conosciuto orchi onorevoli quanto il più nobile dei cavalieri, e umani spregevoli quanto il più spietato dello Scourge.$B$BMa non voglio annoiarti con le storie di quando ero giovane! Qui c'è molto lavoro da fare — se è questo che desideri."
S["f3c4fb62"] = "Un applauso per $N!"
S["f3c8bd32"] = "I segni sulla sfera sono gli stessi del marchio che hai sulla mano."
S["f3ce82b0"] = "All'armi! Flagello avvistato nella Cathedral of Light!"
S["f3d0b647"] = "Mi prendi per $Gstupido:stupida;, $R? Tanto varrebbe firmare io $Gstesso:stessa; la sua condanna a morte! Perché dovrei fidarmi di te?"
S["f3d1fe2e"] = "Ero lì, proprio accanto a te, imbecille. So cosa cerchi."
S["f3d35427"] = "Lo Snowfall Graveyard si trova in cima a una collina nel Field of Strife, a est del Winterax Hold.$B$BAl momento è controllato dall'Alleanza."
S["f3e0a806"] = "Il drago si nasconde dietro una facciata regale. Le tavolette la mostreranno per quello che è davvero... Se quello che ho visto si avvererà, non sopravvivrò a questa battaglia, amico. Sei tu che devi finire quello che ho iniziato. Le tue forze sono pronte? Tu sei $Gpronto:pronta;? Cominceremo al tuo comando."
S["f3e26aa3"] = "Cerchi Jenova Stoneshield: la trovi laggiù, nel Dwarven District. Bada ai famigli dei cacciatori mentre loro si addestrano con suo padre."
S["f3ed61e5"] = "Alzati, piccolo drago rosso... e distruggili!"
S["f3edcef4"] = "Tocca la pietra Suntara ed evoca Lathoric the Black e il suo guardiano, Obsidion."
S["f3eff04c"] = "Informazioni sulla Skin of Shadow."
S["f3fbbdaf"] = "Inutile $N! I tuoi amici ti raggiungeranno presto!"
S["f3fef4ca"] = "Mi dispiace, $C, ma non sei ancora abbastanza $Gesperto:esperta; per sopravvivere nell'Alterac Valley."
S["f40b1f9b"] = "Quel kodo è proprio una bellezza. Un momento, dove sono i miei occhiali da lettura? Forse dovresti esaminare la bestia per me."
S["f40e5f32"] = "Il Tracciamento, eh? Allora è Denmul Farmountain quello da cui devi andare. Ti insegnerà i trucchi del mestiere come nessun altro. $B$BDalle porte di Ironforge vai a sud fino al Distretto Militare e lo troverai."
S["f4151f46"] = "Forse non ti sei accorto di essere in inferiorità numerica."
S["f425aa9b"] = "%s assorbe l'energia del totem e la rilascia sotto forma di un impulso antimagia."
S["f4297aab"] = "Proprio mentre parliamo, $C, tutto il materiale bellico viene trasportato a Silithus. A quanto pare, dovrebbe arrivare tutto entro pochi giorni. Dopodiché, servirà un eroe che venga a suonare il gong presso la Scarab Dais. Allora la guerra comincerà davvero."
S["f4341b25"] = "È terribile quello che è successo a 'sti muli... Metz mi farà la pelle per un fallimento del genere."
S["f443972a"] = "Stanotte il tuo sangue scorrerà rosso sulle pietre dei nostri altari."
S["f44b7f65"] = "Grumnus è quello che fa per te, $N. Ti insegnerà l'arte del forgiatore di armature."
S["f44ce746"] = "Vedi, devi solo forgiare il martello di Sulfuron e trovarti l'Eye of Sulfuras. Metti insieme l'Eye of Sulfuras e il martello di Sulfuron, ed ecco che diventa Sulfuras! Ora, non ti appesantirò con i dettagli tecnici: dove, come o quando procurarti un Eye of Sulfuras lo capirai da te, ne sono $Gsicuro:sicura;. Ti basta firmare questo contratto: così il nostro accordo diventa vincolante e l'affare è concluso."
S["f450eeb5"] = "Se scappi adesso, forse vivrai."
S["f4575553"] = "Dove andare? Cosa fare? Tante scelte che finiscono tutte nel dolore, nella morte."
S["f45bbe1c"] = "Al diavolo questi kobold. Con loro che corrono avanti e indietro e mi stanno tra i piedi non combino niente. Be', tanto non ho niente di meglio da fare. Ti va di imparare qualche tecnica di estrazione mineraria? O forse ti servono solo degli attrezzi nuovi?"
S["f45ffdc9"] = "Per me una pinta di birra Dark Iron. Oh, non sei il cameriere?"
S["f4607fa9"] = "Per Gnomeregan!"
S["f4732360"] = "Noi difendiamo. Noi resistiamo. Noi mostriamo che come uno. Uniti. Noi distruggiamo. Il loro dio cadrà."
S["f4809369"] = "Se potessi ti addestrerei, ma sei troppo avanti per me. Facciamo così: va' a parlare con la tauren Una, nelle botteghe a nord-ovest dell'altopiano centrale di Thunder Bluff. Lei sì che ha talento."
S["f4877429"] = "Certo, $Gsignore:signorina;. Un tempo eravamo al servizio della casata Barov, quella che oggi è nota come la Scholomance.$B$BIo ero la capocameriera, e Lucien il maggiordomo del Padrone Barov.$B$BPer decenni avevamo lavorato per i Barov, finché...$B$B<Eva piange.>"
S["f488a252"] = "%s lancia un grido di trionfo."
S["f48a483e"] = "Sei $Gvenuto:venuta; a giocare? Allora giochiamo!"
S["f4917028"] = "Siamo tutti pezzi di un puzzle molto più grande, $N. Tu guidi un pezzo al suo posto, e allo stesso modo un altro guida noi.$B$BE forse anche chi guida noi è guidato, a sua volta, da una forza ancora più grande."
S["f4960ce3"] = "Cosa? Non conosco nessun istruttore di stregoni a Stormwind.$B$BAnche se... dalle parti de The Slaughtered Lamb, in Mage Quarter, hanno notato delle attività demoniache. Potresti dare un'occhiata lì, immagino."
S["f49bcea0"] = "Sei mio, destriero del terrore! Il tuo spirito ora è legato a me!"
S["f4a5c5c2"] = "YARRR! Mozzo, che hai combinato?! È impazzito! Chiudete i boccaporti! Issate l'albero! ARRRR! Si salvi chi può!"
S["f4a9d820"] = "Come vedi, sono un uomo solo, e il mio scudiero è un bestione goffo. Da solo, la potenza dei nani Dark Iron e delle bestie in pugno a Ragnaros mi sopraffarebbe di certo, ma ho la massima fiducia che per $Gun:un'; $Gavventuriero:avventuriera; così $Gcoraggioso:coraggiosa; e $Gambizioso:ambiziosa; come te occuparsi degli abitanti del calderone non sia affatto un problema. Se deciderai di aiutarmi, ti ricompenserò con ricchezze e tesori che non osi nemmeno sognare."
S["f4b4976b"] = "Chi è questo semplice $R che si immischia in ciò che è passato? Che la leggenda di Stalvan muoia insieme a te!"
S["f4b9ad97"] = "Che le sabbie vi divorino!"
S["f4c1d555"] = "Le torri e i bunker nell'Alterac Valley sono punti strategici fondamentali. Se controlliamo una torre, le nostre truppe possono colpire da lì a grandi distanze."
S["f4c258d5"] = "Ma com'è potuto succedere, $N? Ti sembra che un oggetto come lo Scepter of Celebras sia una cosa da poco?$B$BStavolta posso aiutarti, ma la prossima non essere $Gsbadato:sbadata; con un oggetto così prezioso..."
S["f4c6effd"] = "Iuuuh! Grazie, Mamma!"
S["f4c853c0"] = "Assaggia la corruzione del tuo mondo!"
S["f4d0f6e0"] = "È vero, un tempo ero umano. Ma quello che altrimenti sarebbe un difetto, $N, torna a nostro vantaggio: le debolezze umane le conosco a fondo."
S["f4d1e3db"] = "La fine è adesso, Fordring."
S["f4d27f49"] = "La guerra è un calvario sanguinoso e caotico, pieno di dolore, sofferenza e morte. Ma chi sopravvive torna con un nuovo rispetto per la vita. Per non parlare di una raccolta di storie da raccontare al bancone, piene di audacia e coraggio. Allora dimmi, ragazza, sei qui per creare qualche storia? O solo per sentire qualcuna delle mie?"
S["f4da9cc2"] = "Niente da fare con il disertore del Twilight's Hammer? Controlla bene le montagne a sud-est. Girano molte voci su un misterioso eremita che vive lì."
S["f4deb2a1"] = "Forse gli spiriti del vento ci hanno lasciati, ma il potere degli elementi non è del tutto fuori portata per chi ha la pazienza di cercarli.$B$BSe sei $Giniziato:iniziata; alle vie dello sciamano, posso aiutarti a comprenderli."
S["f4e2a953"] = "Non smetti mai di sorprendermi con quello a cui una persona riesce a sopravvivere."
S["f4f45124"] = "Devi seguire un po' meglio la guida degli spiriti, giovane. Il tuo cammino è con un altro, Thrag Stonehoof al Thunder Bluff. Forse potrete imparare qualcosa l'uno dall'altro."
S["f4fa9915"] = "Non mi piacciono queste città umane di pietra e acciaio. Preferirei le foreste di Ashenvale, a seguire le tracce di grandi bestie. Ma il mio caro fratello, Kaerbrus, ha ritenuto che sarebbe stato utile addestrare gli umani alle nostre usanze. Perciò, anche se lo onoro e offro i miei servigi, non è detto che debba piacermi."
S["f4fd0a77"] = "Così vuoi diventare un Fabbro, eh? Allora prendi grembiule e martello, $Gragazzo:ragazza;, e vediamo cosa sai fare."
S["f4fe0b34"] = "Le caverne sono purificate. Andiamo, alla camera di Naralex!"
S["f510c72e"] = "Curioso... Windsor, in questa visione tu sopravvivevi? Lo chiedo solo perché una cosa posso garantirla, e lo farò: la tua morte. Qui e ora."
S["f527e0b4"] = "Ehi, Knot — sono $Gun:una; $GSarto:Sarta;. Pensi di potermi insegnare a fare il costume da ogre?"
S["f53a3a48"] = "Come faccio a catturare le moffette del fango per la tua esca?"
S["f53e9d68"] = "The Scarlet Crusade setaccerà queste terre!"
S["f54679ef"] = "E pensare che il posto dove il Capoguerra è nato e cresciuto è così vicino."
S["f54786ff"] = "Insegnare non è uno scambio a senso unico, $N: mentre insegno a te imparo anch'io, e la mia comprensione cresce."
S["f54bba88"] = "Non credo che ti interessi imparare quello che posso insegnarti. Forse è meglio che cerchi un istruttore di $C che ti dia una mano."
S["f550d2ad"] = "Questo molo collega Stormwind alle terre dei kaldorei via Auberdine, la città portuale di Darkshore. Se desideri viaggiare lì, la barca arriva frequentemente."
S["f552e354"] = "Tormil, Gamlor, Shefferd, Cowry..."
S["f55c638a"] = "Non siamo che oscurità e ombre. $GEterni:Eterne;. Invisibili."
S["f55d0610"] = "Oh, va bene! Ecco qui, $N. È il minimo che possa fare per tutto l'aiuto che mi hai dato."
S["f5626ec4"] = "Tenete duro, fratelli. E non preoccupatevi! La stazza è dalla nostra parte!"
S["f563dc5e"] = "<Testo ScriptDev2 mancante!>"
S["f56a0a7e"] = "Saluti. Desideri apprendere l'arte della guerra?"
S["f56e3786"] = "Soldati di Stormpike, il vostro Generale è sotto attacco! Mi serve aiuto! Venite! Venite! Uccidete questi rognosi cani Frostwolf."
S["f56fc259"] = "Niente batte il suono di un motore a vapore a doppio carburatore e anello a forcella che va a firestone pura!"
S["f57041d5"] = "L'unico limite è la fantasia, $Gamico mio:amica mia;: se riesci a capire come forgiarlo, allora puoi farlo, inscatolarlo e spedirlo ai negozi di tutto il mondo. Certo, poi c'è da occuparsi del marketing. Facciamo così: per ora limitiamoci alla parte della forgiatura, ok?"
S["f5749f66"] = "Guardando il pilone più da vicino, trovi un piccolo tavolo con sopra dei cristalli gialli, rossi e verdi, disposti in quella che sembra una formazione precisa.$B$BAccanto a un grande cerchio di cristalli gialli ce n'è uno più piccolo di cristalli rossi da un lato, e uno di cristalli verdi dall'altro.$B$BPrendi bene nota dei colori dei cristalli: a J.D. interesserà molto sapere cosa hai trovato."
S["f57be0fa"] = "Uccidete le guardie, prendete The Warden vivo!"
S["f5809b8b"] = "Grazie, grande spirito. Grazie!"
S["f580b108"] = "Ce l'abbiamo fatta, $Gragazzo:ragazza;! L'Alleanza e l'Orda hanno finito di raccogliere tutto ciò che pensiamo servirà per la guerra di Ahn'Qiraj. Proprio ora gli ultimi beni vengono portati alla Cenarion Hold a Silithus e l'ultimo carico arriverà entro un giorno. Dopo di che $Gun coraggioso eroe:una coraggiosa eroina; dovrà suonare il Gong degli Scarabei con lo Scepter of the Shifting Sands per aprire le porte di Ahn'Qiraj. Quando quelle porte si apriranno, la guerra comincerà!"
S["f582fa02"] = "Aiuto! Ti prego, devi aiutarmi!"
S["f589c5d8"] = "%s lancia un verso minaccioso."
S["f59d6d36"] = "Prendi la tua roba, $N! Mi ha appena avvisato Nilith Lokrav, dalla Searing Gorge: The Undermarket ha messo su bottega nel cuore del Calderone. Va' a cercare Nilith Lokrav nella Searing Gorge e fatti dare tutte le dritte!"
S["f59e5d88"] = "Ora si rilassa, l'Alleanza essere molto indietro, mon. Noi finito di raccogliere qui, e le ultime lucidate stanno andando sulle cose proprio adesso. Quando loro finiscono, là nella loro Ironforge, allora noi pensare a portare tutta questa roba a Silithus. Fino ad allora, state tranquilli e magari fate un po' di pesca."
S["f5a0929e"] = "Per la Luce! Non va affatto bene. C'è qualcosa che non capisci, $N."
S["f5a85a46"] = "%s si autodistrugge!"
S["f5a9342f"] = "Bella domanda, $C. Stando alle ultime notizie, siamo riusciti a mettere insieme una parte dei copper bars che servono. Mi dicono anche che una parte degli iron bars e dei thorium bars richiesti ce l'abbiamo."
S["f5af70d5"] = "%s vede morire il Sorvegliante e fugge terrorizzato!"
S["f5b6fd3e"] = "Un'altra vittoria per la Defias Brotherhood!"
S["f5b83311"] = "Tre urrà per $N, Ammiraglio della Flotta dei Bucanieri Bloodsail!"
S["f5bc085b"] = "Quanto è crudele il destino, a concederci soltanto un istante dopo mille anni di separazione..."
S["f5ca3c17"] = "Ti ha convocato Lago Blackwrench, maestro degli stregoni di Ironforge. Faresti bene a presentarti da lui subito. Lo troverai nel quartiere della Forlorn Cavern, in città."
S["f5d297a1"] = "Vincitore! Noi avere un vincitore qui!"
S["f5ea05ab"] = "La Coldtooth Mine appartiene all'Orda."
S["f5f60364"] = "Eccome! Quegli alveari brulicavano di silithid di ogni tipo, e nessuno era per niente contento di vederci.$B$BFilava tutto liscio finché, in Hive'Regal, non ci siamo imbattuti in un cristallo coperto di glifi. Ne è stata attratta come una falena dalla fiamma! Ha appoggiato la graziosa guancetta al cristallo ed è caduta subito in una specie di trance. La mia ciurma, naturalmente, si è preoccupata. L'abbiamo tirata su e portata via di lì in un lampo!"
S["f5fbcf38"] = "Dunque le voci erano vere. I miei fratelli ribelli hanno fatto bene a nascondere questo luogo allo sguardo di Al'Akir."
S["f602bb85"] = "Tutto tranquillo, qui...."
S["f603b3c8"] = "%s mette un impiastro sulla fronte di Relara."
S["f606c750"] = "Il druido Kal passa molto tempo al pozzo lunare di Dolanaar: sono $Gcerto:certa; che potrà darti l'addestramento che ti serve."
S["f60a099f"] = "Thrall ci ha pagati bene, me e i miei ragazzi, per avergli dato una mano a tirare su Orgrimmar, e così ho deciso di aprire un porto qui. Quasi tutti gli affari li facciamo tramite Booty Bay e Baron Revilgaz."
S["f60eaa6b"] = "Sono $Gfiero:fiera;. Sei davvero $Gun allievo dotato:un'allieva dotata;. E ora, per la tua ultima lezione..."
S["f6114137"] = "Kildrath drammatizza sempre un po' troppo. Pensa che \"Garona: A Study on Stealth and Treachery\" è stato rubato più di 400 volte.$B$BIl marchio dell'Athenaeum protegge i tomi: nessuno può leggerli senza autorizzazione."
S["f620c332"] = "La flotta è pronta, $N. Devi prendere questo segnalatore e piazzarlo nel cratere orientale della zona di battaglia centrale. Difendi il segnalatore dagli attacchi finché la flotta non riuscirà ad agganciarne le coordinate!"
S["f621e33d"] = "A Stormwind di posti dove bere qualcosa ce ne sono tanti, ma solo uno ti lascerà passarci la notte. Vai alla Gilded Rose, nel Trade District: ho sentito dire che le stanze hanno un prezzo ragionevole e le lenzuola sono pulite."
S["f62507ff"] = "Non riesco a capire perché, ma Elder Thunderhorn è andato allo Slithering Scar, nell'Un'Goro Crater."
S["f6261d71"] = "$GStanco:Stanca; di tutti quei drink da mammolette per incantatori? Prova qualcosa di più forte alla Pig and Whistle!"
S["f63348cf"] = "Eccomi! Ora, vermiciattoli, pagherete per la vostra intrusione!"
S["f6383dd6"] = "%s barcolla."
S["f63ef855"] = "Non riesco a credere che gli Al'Aketh ci abbiano colti di sorpresa. Mai ci erano stati ostili, eppure con la loro imboscata hanno ferito molti della mia gente. Giuro che vendicherò i druidi della mia tana, i caduti e i feriti. Ricordatelo: la pagheranno."
S["f64081cf"] = "Quasi di ritorno a Ratchet! Manteniamo il passo..."
S["f6422d1f"] = "Vi taglieremo le gole e vi dissangueremo!"
S["f648823c"] = "La Stonewrought Dam è salva! Hip hip urrà per $N!"
S["f649ebd2"] = "La Mischia è cominciata. $N, preparati a combattere!"
S["f64b4130"] = "Hai trovato una chiave? Beh, è LA chiave? Voglio dire, è la chiave che apre queste catene? Beh, $Gsignore:signora;, c'è un solo modo per scoprirlo!"
S["f64d280b"] = "L'incantesimo di guarigione è fallito. Purtroppo, l'introduzione del siero nel sangue di questa bestia porrà presto fine alla sua vita."
S["f655c29a"] = "I Creatori hanno sintetizzato diversi set delle Piastre di Uldum a proprio uso esclusivo, e sono loro a controllare la distribuzione di questi dischi in tutti i complessi di questo mondo. Per questo la visita ad Azeroth è stata riprogrammata, e in quel momento potrebbero entrare in circolazione nuovi dischi.$B$BI dischi esistenti sono stati distribuiti per intero alle parti in possesso di un adeguato nulla osta di sicurezza."
S["f65c6a68"] = "Ho per le mani delicate questioni di spionaggio dell'Orda. Per tutti e due sarebbe meglio che non mi disturbassi."
S["f6675696"] = "Lady Jaina, questa potrebbe sembrare una richiesta strana... ma ho un giovane pupillo che è piuttosto timido. Per lui sei un'eroina, e mi ha chiesto di procurargli il tuo autografo."
S["f66f60aa"] = "Tutte le nostre raccolte sono completate, $C. Ciò che abbiamo radunato viene trasportato alla Cenarion Hold a Silithus, e l'ultimo carico non dovrebbe metterci più di un giorno ad arrivare. Poi la guerra di Ahn'Qiraj potrà cominciare, quando qualcuno, coraggioso e sciocco, suonerà il gong proprio fuori dalle porte laggiù."
S["f6785e19"] = "Sono io il capo della famiglia. Io. IO!!!"
S["f67c5cda"] = "Perdere la vita era un pericolo che avevo accettato. Perdere Ysida è qualcosa che non posso sopportare, nemmeno dopo la mia morte."
S["f67cfcb1"] = "E se mettessimo tre focalizzatori a schema Tyreano? Il problema dovrebbe risolversi."
S["f67e608e"] = "Che la Luce ti protegga, oggi."
S["f68ef4b9"] = "Mortali patetici e prevedibili... Non sapete cosa avete fatto! La volontà del Padrone è compiuta. La Moonglade sarà distrutta, e Malfurion con essa!"
S["f68f4862"] = "Il trasporto dell'High Order per Azeroth è all'ultimo molo, al margine sudorientale di Valanaar."
S["f68fc3f2"] = "D'accordo, allora... Conosco la strada per andare e tornare da Gadgetzan. Quello che ti chiedo è di tenere lontane le bestie. Ho insegnato a Dadanga a difendersi piuttosto bene, ma non possiamo reggere a lungo quella follia rigogliosa là fuori. Fammi sapere quando sei $Gpronto:pronta; a partire, $N."
S["f695626e"] = "Dieci anni sono passati, e ancora la cerca, anche se non era una bellezza e molte dame avrebbero preso il suo posto."
S["f69f6407"] = "Salve!"
S["f69f6414"] = "Saluti."
S["f6b476e2"] = "Più di quanto vorrei, temo. Un gruppo di banditi accampati in una grotta a nord ci tormenta, e da poco il culto di Al'Aketh si è impadronito di Falaath Village, a sud di qui. Mi fido di ogni peacekeeper e di ogni cittadino, ma siamo davvero troppo pochi per tenere al sicuro il villaggio.$B$BSe il culto decide di allargarsi ancora fin qui, potremo fare ben poco per fermarlo."
S["f6b68b8d"] = "Sono venuto da Ironforge a dare una mano qui con la ricostruzione. Se riesco a insegnare il mestiere a un bel po' di voi, magari vi lascio tutto in mano e me ne torno a casa."
S["f6bc658c"] = "Posso andare a raccogliere altre pietre per la mia collana, papà?"
S["f6bf6596"] = "Il vostro destino è segnato!"
S["f6cc8616"] = "ORA A VOI, INSETTI! AVETE CERCATO CON AUDACIA IL POTERE DI RAGNAROS. ORA LO VEDRETE CON I VOSTRI OCCHI!"
S["f6dc5fcd"] = "%s comincia a crescere!"
S["f6df59b9"] = "Dimmi, ti senti pront$Go:a; ad affrontare la prova che ti ho preparato? Gli spiriti mi dicono che la supererai, ma hai fiducia in loro o in te stess$Go:a;?"
S["f6e9a34c"] = "Non tutte le commissioni vanno come previsto. Anche se ci impegniamo perché ogni consegna arrivi intatta e in modo efficiente, il recente aumento degli attacchi di bestie, banditi e perfino dell'Orda purtroppo causa delle inevitabili perdite di merce.$B$BSe dovessi trovare delle spedizioni perdute e ti sentissi particolarmente disponibile, puoi dare un'occhiata all'etichetta e scoprire cosa dovrebbero contenere. Naturalmente non tocca a te rimediare alle nostre mancanze, ma se completi la spedizione sarai $Gricompensato:ricompensata; di conseguenza.$B$BLa signora Baker, vicino alle casse, si occuperà del tuo compenso, e da lì penseremo noi alla logistica."
S["f6ea9346"] = "Salute a te, $C. Nell'Alterac Valley, in questo momento, il bisogno è grande, e c'è ancora più onore e fama da conquistare. Ti unirai alla nostra lotta contro la Stormpike Guard?"
S["f6ec9937"] = "Salve, signore. Sono Nyrill, apprendista del Maestro Xylem. Se c'è qualcosa che ti preoccupa, parlane pure con il maestro.$B$BQuando sarai $Gpronto:pronta; a ridiscendere ai piedi della montagna, sarò qui al tuo servizio."
S["f6ef7e80"] = "Grazie per il tuo aiuto, $N. Grazie a te, un altro carico è arrivato sano e salvo allo scavo."
S["f6f514ba"] = "%s geme."
S["f6f79d04"] = "...nervi di torio."
S["f6ff0d62"] = "%s ringhia."
S["f7014cd4"] = "Aku'mai evocherà di certo gli antichi dèi per noi. Se solo riuscissimo a fornire abbastanza innocenti da saziare la sua fame."
S["f7092199"] = "Se hai provato a entrare a Dalaran, avrai incontrato le guardie del Kirin Tor: hanno l'ordine tassativo di non far passare estranei in città finché dilaga questa perturbazione. Il consiglio ha decretato che salvare le apparenze conta più che evitare una catastrofe.$B$BIo non mi faccio illusioni del genere."
S["f70b951b"] = "Arr! Non c'è niente che mi piace di più che vedere gente che si batte all'ultimo sangue nell'arena. Se sei qui al momento giusto, magari puoi essere $Guno:una; di loro!"
S["f70e2cbb"] = "Il nostro generale, Vanndar Stormpike, è caduto in battaglia! La battaglia è persa!$B$BParla con il nostro furiere e aiutaci a ricostruire le nostre forze."
S["f714bd74"] = "Chi ha evocato Aman?"
S["f7194e18"] = "La rabbia che arde dentro di te troverà presto di che alimentarsi nei nostri nemici."
S["f71ddf67"] = "Mi sembra di sentire qualcosa! Dev'essere Chambers che arriva. Fate largo! Fate largo!"
S["f723843f"] = "Ah sì, la Scuoiatura. Con uno skinning knife in mano non c'è nessuno più bravo di Yonn Deepcut. Lo trovi nella grande tenda nell'angolo nord-ovest del villaggio."
S["f72560cf"] = "Salute, $Gamico:amica; — concedimi un momento, se posso...$B$BPer fondare Teldrassil abbiamo sopportato molte prove e tribolazioni. E come se le lotte continue di questi tempi non bastassero, ora la stoffa ci manca gravemente. Se hai dei materiali in più, ti chiedo di donarli. Aiutandoci, ti guadagneresti di certo la gratitudine degli elfi della notte di tutto il mondo!"
S["f728f7e3"] = "\"Taurahe?\"$B$BLa druida tauren ti guarda e aspetta, ma è chiaro che a parole non riesci a comunicare con lei. Per nulla scoraggiata, indica se stessa e sorride; poi indica te e sorride di nuovo. Infine fa cenno più volte lungo il sentiero, verso sud.$B$BForse vuole dirti che più avanti lungo la strada c'è un druido con cui puoi parlare?"
S["f72d3864"] = "Non divorate ancora tutto il cadavere, figli miei! Lasciate spazio per il dolce!"
S["f73b8a3b"] = "Ma per ora, la tua morte dovrà bastare..."
S["f745c7d7"] = "Attenzione! Siamo sotto attacco da parte di $N!"
S["f74cd237"] = "Non sei molto $Gsveglio:sveglia;, eh? Mmm, se fossi un maestro di stalla, magari starei dalle parti della... che so, della stalla? Cerca Morganus, è laggiù."
S["f752c0e7"] = "In nome di tutto ciò che è sacro e caro, ti prego, dimmi che sei $Gvenuto:venuta; a liberarci da questa terra forsaken. Sarò pure con la Marshal Expeditions, ma ti darei i denti d'oro che ho in bocca pur di infilarmi nel tuo zaino e andarmene da questo posto."
S["f754b436"] = "Ve lo mostreremo..."
S["f75c68ee"] = "Attenzione a $N!"
S["f75dc4ae"] = "Io leggerò le parole incise nella pietra, e tu devi trovare il modo di accenderlo."
S["f7689977"] = "Venite, piccoletti. Affrontatemi!"
S["f76bce40"] = "Il varco si aprirà lì, sopra il Lago Elun'ara. Preparati, $N. L'arrivo di Eranikus nel nostro mondo porterà caos e conflitti."
S["f773101b"] = "Vi supplico, mortali, FUGGITE! Fuggite prima che perda ogni controllo! Il fuoco nero infuria nel mio cuore! DEVO... liberarlo!"
S["f77a6529"] = "Premi misteriosi attendono gli avventurosi. Avvicinatevi, avvicinatevi!"
S["f77c0ace"] = "Il felhunter si avvicina! State in guardia!"
S["f77cb60f"] = "Una voce tonante rimbomba dalla pietra...$B$BPercepisco il tuo Medaglione del Rango, cultista, ma un anello del comando non ce l'hai? Sei davvero $Gun:una; comandante del Twilight's Hammer o ti limiti a fare commissioni per i tuoi superiori?"
S["f7857b0c"] = "La nostra causa cade nel vuoto oltre le spesse mura di pietra di Stormwind."
S["f78a3a8b"] = "Salve, $Gamico:amica;! Ti offrirei volentieri un felino da sella, ma prima dovresti farti addestrare da Jartsam, laggiù. Sono creature impavide e non si lasciano montare facilmente, ma quando avrai imparato a cavalcarne una non troverai compagno migliore."
S["f7923415"] = "Ricordi, Rajaxx, quando ti ho detto che ti avrei ucciso per ultimo?"
S["f7949471"] = "Molto interessante. Ma se è così, allora la mia teoria è sbagliata. Devo rileggere le altre sezioni per vedere cosa mi è sfuggito."
S["f797b399"] = "Lard tenere pace qui. Lard vendere anche pesce. Volere pesce?"
S["f79ec1c1"] = "A cosa mai potrebbe servirti una banca? E va bene: dovrai attraversare le Ruins of Lordaeron, a sud di Brill, e in fondo troverai degli ascensori che scendono a Undercity. Lì ferma uno di quei goffi Abominations che amano chiamare Undercity Guardian e fatti dare indicazioni migliori."
S["f7b62272"] = "Mi hai convinto delle tue intenzioni, $N, e ti ringrazio per essere $Gdisposto:disposta; ad aiutare i membri della mia ex compagnia di mercenari, La Veiled Blade.$B$BAllora vediamo, qual è la prossima cosa sulla nostra lista delle cose da fare?"
S["f7b879b7"] = "Allora, dov'era quel libro sulle usanze degli Elfi della Notte che stavo cercando..."
S["f7bb004b"] = "Quanti dei nostri Comandanti sono ancora vivi, Drek'Thar?"
S["f7c28e16"] = "%s allenta la presa sul diario che stringeva."
S["f7c5c89f"] = "%s posa il carico di legna con un tonfo pesante."
S["f7cbb699"] = "Se hai tempo, il Grimclaw e il suo padrone Volcor avrebbero bisogno del tuo aiuto. Se ti interessa, parlami ancora..."
S["f7cda287"] = "Come probabilmente sai, i piloni del vento donati a noi dagli spiriti fungono da ancoraggio al piano elementale di Skywall. Stanno fallendo, e la nostra casa è in pericolo."
S["f7cfc058"] = "Morte a chi ha fatto torto agli Stonemasons!"
S["f7d5a63b"] = "Banchettate con $N, miei tesori!"
S["f7d9a03e"] = "Agamand Mills è in mano allo Scourge, $C. Unisciti a noi!"
S["f7dbec56"] = "Per Orgrim! Questo indurio resiste a un calore enorme!"
S["f7e51791"] = "Non è nostra usanza, né sarebbe possibile. Nefarian è protetto da antichi sigilli, vecchi quanto gli Aspetti stessi, ed è per questo che non posso entrare nel santuario interno di questa cittadella. La magia oscura non lascia entrare nessun altro membro dello stormo che non sia stato consacrato... a meno che."
S["f7ec38be"] = "Che un giorno Kel'Thuzad possa provare la nostra vendetta."
S["f7f547a9"] = "Sei davvero $Gcoraggioso:coraggiosa; a voler sfidare gli orrori oltre questa porta."
S["f7f8c4e5"] = "Tu... muori adesso!!"
S["f807f05c"] = "Sei $Garrivato:arrivata; più lontano di tanti, $N. Rispetta gli elementi che hai intorno e te la caverai molto meglio della maggior parte."
S["f80b58e1"] = "Stai solo rimandando l'inevitabile, $R. Arrenditi. Lei libererà la tua anima smarrita."
S["f812d89d"] = "Sono così $Gstanco:stanca; *anf anf*"
S["f813628f"] = "L'antico Altar of Hakkar si erge silenzioso vicino all'ingresso della stanza.$B$BGuardando le balconate che lo sovrastano, noti che su ognuna poggia una grande statua a forma di serpente, molto simile a quelle sull'altare davanti a te. In qualche modo devono essere collegate..."
S["f819ad7f"] = "Signor Sindaco! I nostri esploratori riferiscono strane attività a ovest."
S["f819b7b0"] = "Ah, agnelli al macello!"
S["f8260675"] = "Hmm... qualche dote ce l'hai, te lo concedo. E va bene, dov'eravamo rimasti?"
S["f839ae85"] = "Strapperò il frammento dal suo cadavere dilaniato."
S["f83e015b"] = "Non vengono molti Conciatori qui a cercare addestramento, ma credo di poterti insegnare qualcosa, se sei $Gpronto:pronta;."
S["f8403eb9"] = "D'accordo, guardami le spalle mentre ti procuro un po' di questo minerale."
S["f841520f"] = "Brzzzzt!$B$B$GBenvenuto:Benvenuta; nel Matrix Punchograph 3005 barra A, terminale di livello di sicurezza alfa.$B$BPer accedere alle funzioni del terminale devi possedere una white punch card.$B$B01000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001"
S["f841f6f6"] = "Il tuo sangue si versa per il bene dell'umanità, infedele!"
S["f84b2720"] = "Trattenete la vostra ira. Domate la vostra furia. Presto avrete tutti modo di sfogare le vostre frustrazioni."
S["f84b8f5b"] = "Si trova di solito nello stormo cromatico minore: cuccioli, piccoli di drago, draconidi minori."
S["f84d22c6"] = "Piccolo goblin sopra edificio a nord di Ruins of Lordaeron. Tu esci da Undercity e vai là."
S["f84ff42a"] = "Attenti! Tutto il materiale bellico per Ahn'Qiraj è stato registrato ed è in viaggio verso Cenarion Hold, $Gsignore:signora;! Mi dicono che l'ultimo carico dovrebbe arrivare tra pochi giorni. Una volta fatto questo, e quando qualcuno avrà suonato quel gong laggiù per aprire i cancelli, ti garantisco che daremo a quegli insetti una battaglia coi fiocchi!"
S["f854c7f0"] = "Ehi, $C! Sembra che l'Orda abbia raccolto le ultime cose, e proprio adesso la loro roba e la nostra stanno venendo spedite a Silithus. Mi dicono che arriveranno là tra pochi giorni, e poi qualcuno potrà suonare quel grande gong vicino ai cancelli di Ahn'Qiraj per dare inizio alla guerra."
S["f8581134"] = "Finalmente hanno pietà! Ci hanno dato qualcosa da bere!"
S["f858dd76"] = "Così avete conquistato un piccolo pezzo di terra. Una battuta d'arresto da poco! Qui regna ancora lo Scourge!"
S["f864af73"] = "Se sei $Gportato:portata; per le arti druidiche, posso addestrarti."
S["f8693cbe"] = "Qui, fra gli artigiani di Darnassus, un millennio di sapere è al servizio del mestiere che hai scelto. Dimmi, ora: quale trovi più interessante?"
S["f8769ff3"] = "Salve. Che cosa vuoi dalla famiglia Carevin? Sei qui per aiutare i Carevins a combattere i non morti?"
S["f87ec85d"] = "Se non si fosse capito, non sono qui a fare il servizio clienti."
S["f881f25d"] = "Di qualifica sono Specialista della Gestione dei Rifiuti."
S["f88cb82c"] = "Questo è il meglio che sono riusciti a fare?$B$B<Omarion raccoglie le forze per ridere.>$B$BNon hai la determinazione per affrontare un mostro come Kel'Thuzad. Crollerai davanti ai suoi servitori, proprio come quelli che sono venuti prima di te...$B$BLasciami qui a morire. Mi rifiuto di tornare in un mondo che ha per campioni quelli come te."
S["f88f5897"] = "Anch'io, come Kel'Thuzad, un tempo ero $Gun mago:una maga; del Kirin Tor, e come Kel'Thuzad cerco il leggendario Atiesh, il gran bastone del Guardiano. Ecco perché i nostri destini sono intrecciati, $C."
S["f890448c"] = "Che istruttore di professione cerchi?"
S["f893562e"] = "Il medico del villaggio sta nella torre al margine nordorientale di Valanaar."
S["f899c67f"] = "Questo mi risparmierà di sicuro un po' di lavoro."
S["f89ad1d1"] = "Non proseguite! Tornate indietro, tornate indietro finché siete in tempo!"
S["f89ae9e5"] = "Se vuoi sapere quali carovane e quali mercanti arrivano e partono qui allo Splintertree Post, per tua fortuna sono proprio l'orco che cerchi. Per tua sfortuna, però, la gente non mi piace.$B$BSe ti serve qualcosa, sbrigati."
S["f89c25ef"] = "Come previsto, l'Orda ha completato tutti i suoi preparativi con largo anticipo su di te e sulla tua cosiddetta Alleanza. Ci state trattenendo tutti, perché non possiamo prendere le ultime misure per cominciare la guerra finché non avrete adempiuto alle responsabilità promesse.$B$BOra va' e fai la tua parte, $R."
S["f8a4d14a"] = "Risse ogni sera e bevute grandiose! Trovate tutto alla Pig and Whistle!"
S["f8a68563"] = "Grazie, mortale. Prima di tornare al Sogno posso renderti un solo servigio.$B$BLa porta che conduce ad Alzzin, il padrone di Zevrim, ti sbarra la strada. Sarò il tuo strumento di distruzione: aspetto soltanto un tuo comando, e la porta si aprirà."
S["f8a80c23"] = "** BERSAGLIO AGGANCIATO: CONFERMATO. UNITÀ WAR RIDER IN ARRIVO. ASSALTO AEREO IMMINENTE. **"
S["f8a8f3c8"] = "Siamo corsi qui appena ci hanno detto cosa stava succedendo. L'High Order è qui al servizio di Zephras."
S["f8ac927a"] = "Si chiama Tai'jin e la troverai nella caserma sul lato est di Razor Hill. Lei ti insegnerà a rispettare gli dei, e tu bada a portare anche a lei il rispetto che le è dovuto!"
S["f8aed8ba"] = "Lasciate riposare la leggenda di Stalvan!"
S["f8b17c10"] = "Andrei a fare piazza pulita di quegli gnolls, ma questa gamba ha visto giorni migliori e temo che finirei solo ammazzato."
S["f8b2b9de"] = "Sei $Gvenuto:venuta; a imparare dal maestro, eh?"
S["f8b832f8"] = "$GUn amico:Un'amica; degli Zandalari! Ti sei $Gspinto:spinta; nel profondo della tana del Dio del Sangue, $C. Faresti bene ad ascoltare quello che ho da dirti.$B$BMolte migliaia di anni fa, mentre i troll nativi dell'impero di Zul'Aman combattevano contro gli infedeli elfi alti invasori, una grande magia fu rubata a Zanza. Gli elfi alti usarono questa magia per incantare le loro armi e armature, per aiutarsi a conquistare i troll della regione."
S["f8bfba14"] = "Ottima domanda, $C. Dalle ultime notizie che ho avuto, l'Alleanza era riuscita a fondere una parte dei copper bars, degli iron bars e dei thorium bars che servono allo sforzo bellico."
S["f8c12b87"] = "La Darkmoon Faire apre a breve. Ripassa più tardi a vedere se abbiamo finito."
S["f8c12b8d"] = "La battaglia finale per Kalimdor è giunta. Il comandante supremo della Might of Kalimdor ordina alle sue truppe di marciare su Ahn'Qiraj e di distruggere tutto ciò che incontrano sul loro cammino."
S["f8c2b3e9"] = "Sei piuttosto $Gcurioso:curiosa;, anche se tanta curiosità tradisce che, in generale, capisci poco. Te lo dico perché, se fossi qui con uno scopo preciso, la tua domanda sembrerebbe inutile.$B$BDetto ciò, ti auguro una buona giornata."
S["f8c5f43f"] = "Sì? Mi hai interrotto, quindi sarà meglio che tu abbia un motivo dannatamente buono."
S["f8c6536c"] = "Ora ho ciò che serve. Proseguiamo."
S["f8c84571"] = "TEST — morte dopo l'attacco $N"
S["f8cc9b7a"] = "Non ho ancora finito la mia formazione, e ne sai più di me. Per imparare di più devi parlare con Me'lynn. Sarà lei a guidarti."
S["f8ccf8f4"] = "Questa città arsa dal sole è la dimora dei troll Sandfury, noti per la loro particolare spietatezza e per il loro oscuro misticismo. Nelle leggende dei troll si parla di una potente spada chiamata Sul'thraze the Lasher, un'arma capace di instillare paura e debolezza anche nei nemici più temibili. Molto tempo fa fu spezzata in due, ma si dice che le due metà si possano trovare da qualche parte fra le mura di Zul'Farrak."
S["f8d22663"] = "Parlami di qualcos'altro..."
S["f8d7d009"] = "Ehi, mi hanno svuotato le tasche!"
S["f8e233c0"] = "Non ho più niente da insegnarti! Almeno, non a $Guno:una; che ne sa quanto te! Voi dell'Orda dovete parlare con Nogg a Orgrimmar!"
S["f8e5f5a2"] = "La forza della tua determinazione risplende, $N. Continui a dimostrare di essere una risorsa per la nostra gente. Un giorno il mondo si renderà conto della grandezza delle tue imprese."
S["f8ea03ed"] = "L'ultima a ridere sarò io... vedranno! Oh, ciao $C, non ti avevo visto."
S["f8eb5666"] = "Se C'Thun fosse sopravvissuto, la nostra libertà non sarebbe valsa nulla. Sei davvero $Gun campione:una campionessa; della profezia."
S["f8f47dc6"] = "La vita del fabbro non è facile, ma ti mette l'acciaio nelle ossa e il fuoco nel cuore. Mio pa' faceva il fabbro, e prima di lui mio nonno, nelle fucine sotto Grim Batol. E adesso mio figlio segue le nostre orme: sono orgoglioso di quel ragazzo."
S["f8fc1ae9"] = "Da molto tempo il mio spirito e le mie spoglie sono tenuti prigionieri qui, a Maraudon, giovane $C. Il tempo mi ha dato soltanto molte occasioni per riflettere sui miei errori e capire che la mia gelosia verso Remulos era stupida. Lui ha cercato di avvertirmi e di convincermi che il mio legame con Theradras non avrebbe portato niente di puro — che dal caos sarebbe venuta solo distruzione. Mio fratello aveva ragione.$B$BMa anche se mi hai liberato, non vuol dire che io sia $Glibero:libera; dalla penitenza."
S["f909c7f5"] = "Il Sigillo del Caos appartiene a Ravenholdt, bestia! Non ne avrai mai il potere! (SEGNAPOSTO — DA SPOSTARE/MODIFICARE)"
S["f913b9e8"] = "Interazione primaria completata. Dissipazione dell'immagine tra dieci minuti."
S["f9173bf3"] = "Vuoi sapere delle raccolte di razioni? D'accordo. Dalle ultime notizie che mi hanno dato, l'Orda aveva preparato una parte delle lean wolf steaks richieste, e abbiamo messo da parte anche un po' dello spotted yellowtail e del baked salmon che servono."
S["f923b654"] = "Padre... Ma... Come?"
S["f92ead9e"] = "Sull'attenti, $Gsoldato:soldatessa;!$B$BWINKY! FATTI SENTIRE!"
S["f941c1b0"] = "Donne..."
S["f944eb32"] = "Uh. Beh, è stato... inaspettato. Direi che ora sappiamo a cosa serve quel bestione. Torniamo a casa, $Gstraniero:straniera;."
S["f9585296"] = "Segreti birichini!"
S["f958b4f8"] = "Oh, racconta! Basta la suspense a far urlare una ragazza!"
S["f95c0dd3"] = "Signore, lo studente chiede che lo picchiate per la sua mancanza di comprensione!"
S["f9676574"] = "Pensaci tu, $N! Io devo prepararmi a risvegliare Naralex!"
S["f96838a3"] = "Come osate entrare nel mio santuario!"
S["f96bfacb"] = "Se solo la giornata avesse qualche ora in più..."
S["f96efb86"] = "Guardia del Terrore, tenete la linea. Fermate l'avanzata dello Scourge!"
S["f97048a6"] = "Salve, mortali! Sono stato attivato dai Dischi di Norgannon per assistervi!"
S["f9767286"] = "Qui al porto ne vedo andare e venire, di personaggi interessanti. Guardati le spalle, $N: con tutti i traffici loschi che girano da queste parti, non si sa mai di chi fidarsi..."
S["f97b4202"] = "Che la luce guidi il tuo cammino e ti assista nei viaggi. Se mentre dai un'occhiata ti serve aiuto, sono qui."
S["f97d8baf"] = "Angor havas a Modor!"
S["f97dc49b"] = "Spiriti della foresta, venite e rispondete al richiamo della natura!"
S["f97dd0c4"] = "Adesso che ho visto questi luoghi e ho udito il suono della terra, credo di essere contento di essermi messo in viaggio.$B$BAh, perdonami, pensavo ad alta voce. Mi chiamano Stonetorch. Sono venuto fin qui in cerca di notizie su una pietra bianca e splendente: si dice che sia caduta dal cielo e si sia fermata su quelle colline laggiù. Alcuni del mio popolo credono che sia una lacrima versata da An'she, l'occhio della Madre Terra in persona.$B$BIo non so se crederci, ma voglio vedere questo fenomeno con i miei occhi e farmene un'opinione mia."
S["f97f07ab"] = "La foresta mi ha parlato della tua presenza, ma non del motivo per cui sei qui. Parla, dunque, e illuminami."
S["f980f9e6"] = "Lo Stonehearth Bunker è sotto attacco! Se nessuno la ferma, l'Alleanza lo distruggerà!"
S["f9852c97"] = "Haha! Il vecchio e robusto Aratroll ha solo qualche piccola cicatrice di battaglia!"
S["f98c14df"] = "%s ruggisce a Terenthis in segno d'intesa."
S["f98ee4de"] = "Ho appena assegnato l'uccisione a $N."
S["f9906344"] = "Ah, eccolo qui."
S["f9a57b8f"] = "Stammi bene, $N. E ricorda, un guerriero non volta mai le spalle al nemico!"
S["f9a69baf"] = "Accesso in corso...$B$BVoid — ingegnere <#skill_level == n3wb>$B $B01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010$B$BACCESSO NEGATO!"
S["f9a9a64c"] = "Rin'ji ha bisogno di aiuto!"
S["f9bdfb13"] = "Salute, $Gviaggiatore:viaggiatrice;. Finché resterai entro le mura della Cenarion Hold, non correrai alcun pericolo.$B$BQuando lasci la protezione della Hold, però, fa' attenzione: ultimamente i silithid sciamano in gran numero."
S["f9c019ce"] = "Mangio... le tue... ossa..."
S["f9c377b7"] = "Hai il coraggio di mettere piede nel Ravenholdt Manor, verme?"
S["f9cdc348"] = "Cos'è questo?! Come osate!"
S["f9dc74fc"] = "Gli Undead, nonostante la loro tragedia, hanno fatto tutta questa strada per aiutarci, e spero solo che noi sapremo essere altrettanto utili. Father Cobb lo trovi vicino alle Pools of Vision, sotto la Spirit Rise."
S["f9de7965"] = "Mi serve un altro set di thieves' tools."
S["f9ebc80b"] = "%s si libera dal suo bozzolo sotto Hive'Ashi."
S["f9ecbe5a"] = "Il mio signore Abernathy vi manda questo."
S["f9ed09fa"] = "Le statue sono tutte al loro posto, e puoi iniziare l'enigma."
S["f9efeb30"] = "A quel punto le protezioni magiche dovrebbero essere sostenute abbastanza dal flusso di energia da contenere l'entità."
S["f9f5084f"] = "Magnifico! Grazie al tuo aiuto il mio popolo ha una possibilità di riprendersi la nostra amata città. Tre urrà per te!"
S["f9fafd2e"] = "Assaggia la magia dei Frostmane."
S["f9fb5a87"] = "Già il fatto che tu sia qui è un primo passo... una scelta giusta, se vogliamo, per aiutare il Ysera's Dragonflight.$B$BForse ti ha portato qui solo il richiamo del guadagno personale, o forse ti senti moralmente $Gobbligato:obbligata;. Nessuna delle due ragioni conta di per sé, ma tutte e due sono fondamentali a questo scopo: è l'agonia che Eranikus sopporta ad avermi risvegliato dal mio Sogno, e ora tocca a me fare in modo che il suo tormento finisca. Ti chiedo di aiutarmi in questa impresa."
S["f9fe993b"] = "Salve, giovane $C. Sono Rathiril Sunlance, un anziano Magister dell'High Order qui su Zephras Isle. È sempre un piacere vedere giovani shen'dorei dagli occhi vivaci, pronti a fare il loro dovere al servizio della patria.$B$BMa non lasciarti trattenere da questo vecchio mago impolverato: di certo hai molte avventure da affrontare. Se vuoi parlare ancora, passa pure più tardi."
S["fa01c929"] = "Se vuoi rubarmi del tempo, faresti meglio a dimostrare che ne vali la pena. Dopotutto, da questo accordo dovrei pur guadagnarci qualcosa."
S["fa04a1af"] = "Di cosa hai bisogno?"
S["fa054489"] = "Ci saranno fuochi d'artificio tutta la notte. Dalle 6 di sera fino all'alba il cielo fiammeggerà sopra Elune'ara!"
S["fa06dba3"] = "Peccato non poter scuoiare gli umani e i loro alleati. Tutta quella pelle va sprecata. Però, chi vorrebbe indossare il cuoio fragile che ne verrebbe fuori?"
S["fa0e848a"] = "Sei qui per imparare a maneggiare una nuova arma, o vuoi solo farmi perdere tempo?"
S["fa165c99"] = "Ti insegnerò un'abilità di equitazione solo quando sarai $Gosannato:osannata; presso gli elfi della notte di Darnassus, $C."
S["fa250c98"] = "Ho detto IN GINOCCHIO!"
S["fa2f6f52"] = "Morire per l'Abyssal Council è mio dovere e mio onore!"
S["fa31897c"] = "Che... freddo..."
S["fa3d13e8"] = "%s comincia a lamentarsi e ruggire verso Terenthis, battendo le zampe a terra."
S["fa4e4dfe"] = "Ti copro io, Ichman. VAI VAI VAI!"
S["fa68dfb8"] = "Dopo la caduta di Dalaran e la distruzione di Quel'Thalas, merci come queste si trovano a fatica. Però Lucan Cordell e alcuni altri dei nostri Mercanti fanno un ottimo lavoro ed evadono gli ordini con merce di qualità."
S["fa6999f0"] = "Il Magistrato è troppo ben protetto. Ritirata!"
S["fa754a85"] = "Elder Brightspear si aggira tra le rovine di Kel'Theril, a Winterspring."
S["fa7f1457"] = "$GBenvenuto:Benvenuta; a Thelsamar, la tua seconda casa a Loch Modan!$B$BThelsamar è un bel posto, ma per chi risponde alla chiamata del dovere non c'è solo birra e carne salata! Se sei $Gdisposto:disposta; ad affrontare il pericolo in nome dell'Alleanza, dai un'occhiata all'avviso fuori dalla sede dell'Explorers' League qui a Thelsamar."
S["fa81c775"] = "Che vuoi?"
S["fa85c8f1"] = "$GBenvenuto:Benvenuta; a Caer Darrow, $Gstraniero:straniera;."
S["fa89ea0d"] = "Istruttore di Classe"
S["fa9396a2"] = "Noi, i troll Zandalarian, siamo venuti fin qui da isole lontane, perché non possiamo ignorare la minaccia che ora incombe sul nostro mondo."
S["fa954284"] = "I tuoi attacchi sono rallentati dal freddo, mi sa!"
S["faa3c383"] = "The Scarlet Crusade colpirà i malvagi e scaccerà il male da queste terre!"
S["faadd35c"] = "%s comincia a lavorare..."
S["faae1657"] = "La Fratellanza prevarrà!"
S["fab0c5e9"] = "Ora la fiamma eterna è nelle tue mani. Presto, portala al Brazier of Eternal Flame a Valanaar e completa il rituale."
S["fab402a3"] = "Salute, che vuoi?"
S["fac83c8a"] = "La terra dell'eterna luce stellare, Kalimdor, era una madre premurosa per tutte le sue creature. La magia del Well of Eternity permeava la terra e dava forza alle innumerevoli specie di flora e fauna che avrebbero fatto del mondo la loro casa. Da questo etere magico nacquero i silithid. Fu attraverso i silithid che il cupo Old God avrebbe tentato di raggiungere e spezzare il mondo che un tempo stringeva nella sua morsa spietata."
S["fac91a97"] = "Siamo pieni di fiori di loto purpurei, $C. Vai a chiedere a uno degli altri se hanno bisogno del tuo aiuto, e lasciami ai miei studi. Non c'è tempo da perdere!"
S["facffe03"] = "Chi se ne intende punta sugli gnomi per la prossima gara! Piazzate le vostre scommesse finché siete in tempo!"
S["fada0b88"] = "Oh, cerchi un po' di illuminazione arcana, eh? Allora non c'è posto migliore del Wizard's Sanctum, in Mage Quarter."
S["fade2578"] = "Oh! Quasi dimenticavo! Ti ho passato di nascosto degli strumenti dei ladri. Ti serviranno dove stai andando."
S["fae267dd"] = "Perché continui a dire che è morto? Chi te l'ha detto, che è morto? Io non ho mai detto che è morto.$B$BÈ sparito e basta.$B$BVedi, a quanto pare eravamo capitati nel bel mezzo di una grande battaglia fra orchi e nani Dark Iron. Gli orchi, luridi, miserabili cani bastardi come sono, erano usciti presto a piazzare trappole e altre cose diaboliche che probabilmente non capiresti."
S["fae55526"] = "Circolare, $Gzoticone:zoticona;."
S["fae582aa"] = "Allora è con Thelman Slatefist che vuoi parlare. Sta al cospetto del Re, in Stormwind Keep."
S["fae5cca3"] = "Che tristezza! È Hallow's End e io sono $Gmalato:malata;. Non posso uscire, e mi perderò dolcetto o scherzetto!"
S["fae992d2"] = "Non è giusto! Il mio carissimo Sully! Torna da me! No, $N! Perché mi hai portato una notizia simile!"
S["faf48c22"] = "%s scompare di nuovo nella palude."
S["fafbe186"] = "Non cercare altro: a Goldshire c'è la Lion's Pride Inn. Tante birre fra cui scegliere e morbidi letti di piuma: per riposare non troverai posto migliore."
S["fb00a391"] = "%s è tutto stordito!"
S["fb08bf8a"] = "Il siero sarà pronto in pochi minuti, $N."
S["fb0f6d6e"] = "Fucili e fiamme, va tutto bene finché qualcuno non perde e ci muore."
S["fb108ed5"] = "%s colpisce in un lampo il fantoccio a forma di orco..."
S["fb16f99e"] = "Chi osa violare la santità del mio dominio? Siete avvisati: chiunque entri qui è condannato!"
S["fb17ad64"] = "Vengo dalla terra agli antipodi... dove le donne portano la peste e gli uomini fanno a pezzi."
S["fb18f4f4"] = "Ecco fatto. Una nuova infornata di flash bombs!"
S["fb1bf1a8"] = "Mi aiuteresti a ritrovare il mio cane?"
S["fb1d3926"] = "Cosa desidera, $Gsignore:signorina;?"
S["fb254e02"] = "I Sabbiafurente regnano supremi!"
S["fb2797e0"] = "Le tue azioni ci disonorano tutti, $C. Mi addolora pestarti fino a farti perdere i sensi!"
S["fb2bafea"] = "Accidenti che lotta c'hai messo, Jarad. La prossima volta 'sto scudo devi tenerlo più su. Lana! Tocca a te!"
S["fb2e86b8"] = "Forse hai la stoffa giusta. Scopriamolo!"
S["fb301b47"] = "Avanti, avanti! Hai dei biglietti della Darkmoon Faire da riscattare? Basta dirlo! I biglietti di vario taglio li cambi con premi meravigliosi e fantastici. Non esitare, vieni a provare!"
S["fb49220b"] = "Il tuo talento supera il mio, $Gamico:amica;. Va' a parlare con Tarn, qui vicino: conosce il cuoio molto meglio di me, e sono certo che accoglierebbe volentieri $Gun altro allievo:un'altra allieva;."
S["fb4ccfe3"] = "È una specie di scherzo?"
S["fb4f121d"] = "Troverai la cittadina di Lakeshire laggiù, oltre il ponte. Ma non la troverai un posto tranquillo. Se sei qui in cerca di avventura, $Gragazzo:ragazza;, allora dammi retta — l'hai trovata!"
S["fb4f95fe"] = "Qui a Darnassus troverai istruttori abili, che in ere di addestramento e dedizione hanno perfezionato le arti della classe scelta. Indicami la via che hai scelto, e ti guiderò da chi potrà diventare il tuo mentore."
S["fb656474"] = "Grazie per aver trovato i miei reagenti! *sbadiglio* Quel veleno mi ha reso... un po' stanco..."
S["fb67128c"] = "Il Dun Baldar North Bunker protegge l'ingresso orientale di Dun Baldar.$B$BÈ controllato dall'Orda."
S["fb69618e"] = "Un'altra faccia nuova! $GBenvenuto:Benvenuta; ad Azeroth, $Gamico:amica;. Se ti serve una mano per partire col piede giusto, torna a trovarmi.$B$BPorta soldi."
S["fb6f0530"] = "D'accordo, ragazzi! È ora di alzarsi"
S["fb79a2cd"] = "Be', ora che me lo dici, sì, ieri pomeriggio ho visto una cosa che mi è parsa un po' strana!$B$BCorrevo vicino a delle vecchie rovine troll a sud-est di qui; be', correre proprio no, più che altro saltellavo... La sabbia scotta così tanto!$B$BComunque, saltellavo vicino alle rovine quando ho notato che lì c'era un accampamento. Strano posto per accamparsi, se vuoi saperlo... Avrei curiosato ancora un po', ma uno di quegli avvoltoi grossi da non credere mi ha $Gcacciato:cacciata; via."
S["fb86517d"] = "Una morte... onorevole."
S["fb88de94"] = "Grazie, $N. La Luce ti benedica, $Gfratello:sorella;, e guidi il tuo cammino."
S["fb8b5f61"] = "%s esamina il Moss-twined Heart..."
S["fb8e484e"] = "Bene, statemi vicini. Questi mostri vi salteranno addosso dall'ombra se abbassate la guardia."
S["fb9257cc"] = "Salve, cittadina. Hai l'aria di una donna che sa dove va — hai qualche faccenda da sbrigare con la Stormwind Army?"
S["fb93cfcd"] = "Salve, clan Trias! Una mozzarella affumicata delle vostre, per cortesia!"
S["fb9962d0"] = "Bersaglio perso.... ripresa schema di ricerca Delta"
S["fba1e7a2"] = "Il Dun Baldar South Bunker protegge i fianchi sud ed est di Dun Baldar.$B$BÈ controllato dall'Orda."
S["fbb247ac"] = "\"Darnassae?\"$B$BLa druida elfa della notte ti guarda in attesa, ma è chiaro che a parole con lei non puoi comunicare. Per niente scoraggiata, indica se stessa e sorride; poi indica te e sorride di nuovo. Infine fa cenno più volte lungo il sentiero, verso nord.$B$BForse vuole dirti che più avanti, lungo la strada, c'è un druido con cui puoi parlare?"
S["fbb2526c"] = "Elder High Mountain lo trovi a Camp Taurajo, nelle Barrens."
S["fbb8bb03"] = "Auction House"
S["fbb93cdc"] = "Questo no è un gioco, $Gamico:amica;. Tu vuoi usare l'ascia, tu devi dire la battuta. Dilla con me... \"Saluta il mio piccolo amico.\""
S["fbc33588"] = "Ok! Cominciamo!"
S["fbc4d806"] = "Questo accampamento deve sopravvivere a ogni costo, $C! Ai nemici niente pietà, perché loro di certo non ne avrebbero per noi, se ne avessimo bisogno."
S["fbcdec0b"] = "Sei $Gtonto:tonta;? Di chi altro dovrei parlare? Sì, la ragazza — Mistress Mar'alith. Comunque, era tornata, e di cattivo umore. È da lì che le pretese hanno cominciato a fioccare."
S["fbce3706"] = "%s chiama in aiuto un Blackhand Veteran!"
S["fbce9cf3"] = "È ora di fare la tua ultima resistenza, insetto."
S["fbd57514"] = "Anthion, a quanto pare non trovo più lo stendardo che hai creato per me."
S["fbe3f3db"] = "Tutto qui? Pensavo che mi avresti sfidato."
S["fbe862bb"] = "Questi mucchi di legno e paglia avranno pure pietà, ma The Lich King no!"
S["fbe8b4e2"] = "Anche se odio ammetterlo, l'orso ha avuto la meglio su di me. Accidenti, che orsone enorme!$B$BComunque, se riesci ad abbatterlo, sarebbe un'impresa di cui andare fieri! Ha dato del filo da torcere a più di uno dei nostri migliori cacciatori.$B$B<Ti dà una pacca sulla spalla.>$B$BSconfiggi l'orso e ti accetteremo come membro effettivo di Farstrider Lodge."
S["fbff79f2"] = "La novità di quest'anno è il PX-238 Winter Wondervolt. Fatti avanti, non essere $Gtimido:timida;!$B$BE prima di provarlo firma questi moduli, che a questo affare stiamo ancora sistemando qualche difetto..."
S["fc037839"] = "Non ho tempo per le chiacchiere, $Gcittadino:cittadina;, ma se sei $Gdisposto:disposta; a darci una mano contro gli orchi, un modo per impiegarti lo troverò."
S["fc058d82"] = "%s comincia a chiamare rinforzi!"
S["fc05a421"] = "Spero che tu sia qui per lavorare, $C. C'è molto da fare, e l'Orda, lo Syndicate e gli Ogres non ci daranno una mano."
S["fc060631"] = "Chi controlla il Dun Baldar South Bunker?"
S["fc0fef25"] = "Zoom, zing e BAM! Avrà anche avuto un'enorme mannaia a due mani ricavata da un'ancora di nave, ma dopo qualche fendente ben assestato con il mio coltello da tavola, è stato lui a fare crash!"
S["fc177041"] = "Glacial Gloves."
S["fc26f496"] = "Non sono $Gstato:stata; io! Lo giuro!"
S["fc2ae58b"] = "Sì, signora."
S["fc2b814e"] = "Il re è morto! OH NO! Chiamate Mizzle l'Astuto! Lui sa cosa fare dopo!"
S["fc2d863e"] = "Grazie, $N! Troverai Keras Wolfheart sulla Terrazza del Guerriero, vicino agli istruttori. Ti guiderà fino all'Arathi Basin. Buona fortuna, e grande onore sia su di te."
S["fc4a699b"] = "Sciocchi! Continuate pure a combattere, se è questo che volete! A ogni battaglia ne cadono altri di voi, e le file dei non morti si ingrossano!"
S["fc4aaf02"] = "Per Broxigar!"
S["fc5023f7"] = "Ho ordinato dalla città qualche carico di profumi e acque di colonia nuovi. Quando li avrò spacchettati, ripassa e li avrò in vendita."
S["fc59030f"] = "Come da tua richiesta, Corporal Splithoof è arrivato, $N."
S["fc5c2ac9"] = "Vedo oltre il tuo travestimento, $R. Number Two! Number Two, uccidi!"
S["fc5f98cf"] = "Sartoria"
S["fc641d67"] = "%s ascolta $N che gli racconta le sue avventure nelle Badlands."
S["fc66892d"] = "Overlord Mok'Morokk capo. Tu fai quello che io dico."
S["fc6a46d2"] = "Farò in modo che nessuno ti segua. Qualunque cosa ci sia da fare, hai dalla tua il Kirin Tor."
S["fc6ab2a2"] = "Non posso aiutarti finché non avrai imparato di più sulle basi. Torna da me quando sarai pront$Go:a;."
S["fc6ae8cd"] = "Sarebbe saggio che ti spiegassi fin dove i nostri nemici sono disposti a spingersi per nascondersi sotto il nostro naso.$B$BPrima di tutto, sappi questo: il nostro nemico è lo Shadow Council. Qualunque compito ti affidi, chiunque ti chieda di affrontare, ricorda questo semplice fatto.$B$BDentro il Council ci sono molti culti, ma esistono solo per nascondere agli sciocchi quello che fa.$B$BGruppi come la Burning Blade, l'Argus Wake e la Searing Blade sono tutti strumenti del Council. Considerali una cosa sola."
S["fc73d923"] = "La temperatura è di 9280 gradi Kraklenheit! Che CALDO!"
S["fc790da4"] = "Mmm, be', vedo che nel preparare pozioni hai un po' di abilità. Resta da capire, però, se tu sia $Gdegno:degna; di essere $Gmio allievo:mia allieva;. Ho un lavoro per te. Impressionami."
S["fc7c229f"] = "Ho troppo da fare e troppo poco tempo, $R! Togliti di mezzo, per favore.$B$BSe però sei $Ginfettato:infettata; dalla bava di maggot o dal marciume da ghoul, forse posso aiutarti."
S["fc870921"] = "Accidenti, questo è proprio inutile. Fatemi riprovare."
S["fc8b0e7c"] = "Maestro... perdonami."
S["fc978b1c"] = "Elder Bladesing la trovi a Cenarion Hold, in Silithus."
S["fc98a1f8"] = "Via dal mio kodo, scherzo della natura!"
S["fc9d83b2"] = "Vincent! Tu e i tuoi patetici simili non avrete più successo nel cacciare me e i miei figli di quanto ne abbiano avuto quei miserabili resti del Kirin Tor."
S["fcaac845"] = "Buongiorno, signora. Ti stringerei la mano, ma come vedi ho da fare. Posso aiutarti?"
S["fcab4f93"] = "Se vuoi saperne di più, parla pure con Elaine Compton, qui vicino. Risponderà volentieri alle tue domande."
S["fcae1202"] = "Marduk, prendi la scatola e mettila davanti a me!"
S["fcb19e77"] = "Lascia stare quel pover'uomo, $Gcittadino:cittadina;, non ne vale la pena."
S["fcb30d5b"] = "Ogni cosa ha uno spirito, e se impari ad ascoltarlo puoi fargli prendere qualsiasi forma tu voglia. La forgiatura non vuol dire battere il metallo, costringerlo a piegarsi alla tua volontà. Vuol dire ascoltare lo spirito che c'è dentro l'acciaio e guidarlo verso la forma che sai che vuole prendere."
S["fcb7a44b"] = "Saluti... Windshaper.$B$BCome di certo saprai, quelli che si fanno chiamare Windshapers hanno ben pochi interessi in comune con la maggior parte dei membri dell'High Order. Fuori dalla relativa armonia di Thendal Grove potresti scoprire che queste divisioni sono davvero profonde, e che a volte la rivalità può sfociare in aperta violenza.$B$BNon dirò altro: una volta lasciato il boschetto, ti conviene farti gli affari tuoi e non intralciare gli obiettivi dell'High Order. Probabilmente è l'unico avvertimento che riceverai."
S["fcb8f16b"] = "HhuuuNNNngh!"
S["fcbe5567"] = "Ti insegnerò un'abilità di equitazione solo quando sarai $Gosannato:osannata; presso gli orchi di Orgrimmar, $C."
S["fcc8e8d4"] = "Ahahah, vostre guardie niente contro lo Scourge!"
S["fccd879f"] = "Aaaaahhhhhmmm..."
S["fcd1fc90"] = "Non fermerai la nostra ombra che si fa sempre più fitta, $C. Ora... unisciti a noi! Unisciti ai ranghi dei Prescelti!"
S["fcd60ec1"] = "Fuggite finché ne avete la possibilità, mortali. Implorerete una morte rapida, se dovessi entrare nell'arena."
S["fce6a7eb"] = "È ora del mio giro di pattuglia. Torno presto."
S["fcec0bee"] = "Esigerò una prova della tua determinazione prima di condividere con te i miei doni..."
S["fcec840c"] = "Shal myrinan ishnu daldorah..."
S["fcee30d3"] = "Saluti... Windshaper.$B$BCome di certo saprai, quelli che si fanno chiamare Windshapers hanno ben pochi interessi in comune con la maggior parte dei membri dell'High Order. Fuori dalla relativa armonia di Thendal Grove potresti scoprire che queste divisioni sono davvero profonde, e che a volte la rivalità può sfociare in aperta violenza.$B$BNon dirò altro: una volta lasciato il boschetto, ti conviene farti gli affari tuoi e non intralciare gli obiettivi dell'High Order. Probabilmente è l'unico avvertimento che riceverai."
S["fcf2026f"] = "Possibile? Qualcuno che attraversa queste sale con uno scopo? Sì, un fuoco giusto ti arde nel ventre, $R.$B$BLa mia vita forse finirà presto, ma il sapere che custodisco va condiviso con il mondo. Dopotutto, è per questo che ora sono qui.$B$BSei $Gun maestro:una maestra; in qualche mestiere?"
S["fcf700e9"] = "Mi sto appena scaldando!"
S["fcf93178"] = "Ah, $R, sei $Gtornato:tornata;!"
S["fd040608"] = "Sono uno spirit healer di prova."
S["fd04a248"] = "Mmmmm, cibo. Non è troppo lontano, ma devi andare a nord, a Orgrimmar, e chiedere a uno dei grunt."
S["fd0500d1"] = "Attenzione! Ci attaccano!"
S["fd0b8ab6"] = "%s, $Gubriaco:ubriaca;, sbaglia a lanciare uno shadow bolt!"
S["fd0d0d73"] = "No! Non può essere..."
S["fd0eb0c1"] = "Che animale magnifico hai, Gerard."
S["fd10e3df"] = "Che cosa mi chiedi?"
S["fd181f87"] = "Bene bene, niente male. Magari qualcosa te lo POSSO insegnare..."
S["fd277c16"] = "Ah, sei gentile, amico, ma abbiamo già tutto il cuoio pesante che ci serve. E io che ero sicuro che il tuo coltello fosse ancora affilato. Forse puoi usarlo per aiutare gli altri con le loro raccolte, no? Buona giornata!"
S["fd2bebde"] = "%s cerca una fonte di energia arcana."
S["fd314c36"] = "%s ti guarda perplesso. Forse dovresti esaminarlo?"
S["fd3f16a3"] = "Molto bene. Taglia un altro pezzo di carne da uno di questi esemplari: mettiamo alla prova quello che hai imparato finora, e da lì potremo andare avanti."
S["fd416c2b"] = "Spero che apriremo presto. La città ha bisogno di noi!"
S["fd41f4df"] = "Hai qualcosa di cui vuoi parlare, $C... vieni a sederti accanto a me."
S["fd4208b7"] = "%s comincia ad appisolarsi..."
S["fd4657af"] = "%s esamina il sangue nella bottiglia."
S["fd47f147"] = "Yudo a siame fu Or'manley icense."
S["fd4b95b3"] = "Vedo che hai perso quel capitolo che ti è costato tanta fatica mettere insieme, $N. Be', l'hai lasciato proprio qui!"
S["fd4caeb7"] = "Ho creato la Soul Gem di Yenniku, $N..."
S["fd4e6771"] = "%s si rigira agitato in un sonno inquieto."
S["fd5054c8"] = "Bene, andiamo."
S["fd5221b6"] = "Grrr..."
S["fd5b11e1"] = "Ho trovato qualcosa... credo."
S["fd610c69"] = "L'Order of the Shattered Hand esisteva prima di Thrall ed esisterà dopo Thrall."
S["fd6c061e"] = "Conosco un po' di gente qui intorno che pratica una professione o due. Quale hai in mente?"
S["fd6fbf24"] = "Non devi accettare subito. Quando verrà il momento, però, ti prego di considerare di unirti a noi nella nostra spedizione. Fino a quando ci rivedremo... che i venti guidino il tuo cammino."
S["fd70a741"] = "Sono $Gpronto:pronta;, e lo sono anche le mie forze. Mettiamo fine a questa mascherata!"
S["fd7471dd"] = "%s riacquista il suo potere e si libera dalle catene!"
S["fd767663"] = "Salute, $C — sono $Gun Ufficiale:un'Ufficiale; degli Encomi e agisco per conto di Orgrimmar. Il mio compito è aiutare gli avventurieri che hanno ricevuto degli Horde Commendation Signets.$B$BAccetto anelli in quantità diverse, ma per te lo scambio più vantaggioso è consegnarmene dieci alla volta. Quando me li porterai, registrerò le tue gesta nei nostri archivi, e così Orgrimmar riconoscerà il tuo impegno e i tuoi servigi."
S["fd868093"] = "La Crociata l'hanno fondata High General Abbendis, High Inquisitor Isillien e Highlord Mograine. All'inizio era un nobile ordine, e la follia e il fanatismo delirante che vedi oggi non esistevano. Gli ingranaggi della corruzione si sono messi in moto solo quando è comparso colui che è conosciuto come il Gran Crociato."
S["fd8806be"] = "Zhi lo! Pawene lomani!"
S["fd8c71f4"] = "Il Popolo di Westfall saluta $N, $Gun:una; $Gcoraggioso:coraggiosa; e $Gvaloroso:valorosa; $Gdifensore:difensora; della libertà."
S["fd8f3987"] = "%s balza fuori dall'ombra!"
S["fd9ae87a"] = "La West Frostwolf Tower è stata presa dall'Orda!"
S["fda3c999"] = "Ehi, chi Fengus chiama amico degli gnoll?! Porta prigionieri dal re; tu furbo a portarli con loro armi e mostrare al re che sono pericolosi. Io vado a vedere se Fengus fa ancora lo sbruffone quando gliele suono! HAR!"
S["fda59521"] = "Stavolta ho preso il bersaglio per un pelo. Mmm... forse devo correggere di nuovo verso destra."
S["fda60bc8"] = "La Stormpike Guard ha bisogno del tuo aiuto per combattere il Frostwolf Clan, $N. Parla con Brogun Stoneshield sulla Terrazza del Guerriero: ti aiuterà a trovare la strada per l'Alterac Valley. Sia lodata Elune!"
S["fdafa4a3"] = "Cosa si può fare in una locanda?$B$BBeh, quando ti fermi in una locanda ti riposi in tutta comodità, e così diventerai \"ben $Griposato:riposata;\" molto più in fretta che nelle terre selvagge. E quando sei ben $Griposato:riposata;, dall'esperienza impari di più.$B$BPuoi anche chiedere un'hearthstone a qualsiasi locandiere: più avanti, con l'hearthstone, potrai tornare in fretta a quella locanda."
S["fdbc1883"] = "La tua anima è dannata!"
S["fdc28912"] = "Quando forze esterne o interne alterano le dinamiche della matrice associata ai mondi seminati, i Creatori ricorrono alla visitazione per ristabilirne il controllo. Se sono i Creatori a metterle in atto, tattiche simili non vanno prese alla leggera.$B$BPer ulteriori informazioni sulla visitazione programmata di questo mondo, si prega di consultare l'apposito archivio dati, che gestisce tutte le questioni di programmazione relative ai Creatori."
S["fdc6cf74"] = "Sì, offro addestramento. Ma non costa poco."
S["fddb0bbf"] = "Bronzebeard è sparito un'altra volta! Quel nano, il buon senso del fratello, non l'ha preso di sicuro."
S["fdde4655"] = "La mia morte conta poco... il Martello si abbatterà comunque!"
S["fde14f2d"] = "Hai fallito!"
S["fde1dfc5"] = "Pane fresco! Pane appena sfornato!"
S["fde3b9a6"] = "Là! Laggiù!"
S["fdf356bf"] = "Sia la Lost Rigger Cove a Tanaris sia la Bay of Storms ad Azshara hanno casse che si possono scassinare per migliorare la tua abilità."
S["fdf8da46"] = "Ci ha serviti tutti, anno dopo anno..."
S["fdffa729"] = "Non preoccuparti, ti resteranno tutte le dita, delle mani e dei piedi."
S["fe09c863"] = "Jarad, tocca a te per primo."
S["fe1cb4c0"] = "Salve, $C. Di solito sarei in giro di ronda a badare alla gente di Stormwind, ma molte guardie di Stormwind sono a combattere in altre terre. E così eccomi qui, nominato vicesceriffo, a offrire taglie quando preferirei essere di pattuglia..."
S["fe26ab40"] = "Oh, cielo, qui si fa la storia. Una scoperta monumentale. Ma queste bestiacce! Merrin, a quanto pare, se la cava piuttosto bene. Ora, se solo riuscissi a mettere insieme i pezzi di questo rompicapo così complicato. . . ."
S["fe2fc60e"] = "I famigli in più te li terrà nella stalla Xon'cha. Lo trovi nella Valley of Honor, alle stalle fra l'arena e l'Hunter's Hall. Ora vattene!"
S["fe317233"] = "Alterac Valley — Opzione di Saluto Predefinita del Quartiermastro dell'Alleanza"
S["fe33064c"] = "Se non verranno presto mandati rinforzi nelle Burning Steppes, temo che lo Scourge vi stabilirà una base operativa. Se puoi, dovresti andare là ad aiutare i difensori.$B$BNecropoli rimaste: $2281W"
S["fe330879"] = "Stavamo attraversando le Burning Steppes quando ci hanno teso un'imboscata. Dovevano essere un centinaio... nani Dark Iron! Sbucavano dalle pareti, dalle rocce delle Steppes; da ogni crepa, angolo e anfratto in vista. Ci sono sciamati addosso e hanno sopraffatto le guardie e i pochi eroi coraggiosi che avevano accettato di aiutarci in questa missione.$B$BUna cosa era chiara: l'imboscata era organizzata nei minimi dettagli. Era come se conoscessero ogni nostra mossa prima ancora che la facessimo..."
S["fe3a2f1a"] = "Morte a qualunque $R si metta sulla mia strada!"
S["fe479f8f"] = "L'esercito degli elfi della notte fu respinto attraverso Un'Goro, fino ai confini del deserto di Tanaris. Qualcosa a Un'Goro impedì ai Qiraji di conquistare quella terra. Non capisco bene questa parola, ma credo significhi 'Terre degli Dei'. È scritto che non poterono 'prendere le Terre degli Dei'."
S["fe4e6274"] = "Continua così. Questo flagello sarà purificato!"
S["fe4e6822"] = "Mi serve un po' d'aiuto qui. $GQuel:Quella; $N mi ha visto."
S["fe4e9ebc"] = "Ah, dunque l'hai fatto. Sei proprio $Gil benvenuto:la benvenuta; a Ironforge, $C.$B$BQui ha sede il Bronzebeard Clan. Siamo un popolo antico e fiero, e non c'è artigiano che valga i nostri: in metallo o in pietra, non troverai niente di più bello di un lavoro fatto dai nani.$B$BE fra gli esploratori di Azeroth siamo anche tra i più audaci. Se ti piace l'avventura, fra la nostra gente sarai in buona compagnia.$B$BTi ringrazio di aver parlato con me, $N. E ora va', con la benedizione del Bronzebeard Clan.$B$BAuguro ogni bene a te e al tuo popolo."
S["fe520afe"] = "È un segreto per tutti... anche per me!$B$BSono contento che tu mi abbia trovato — meno male che non mi sto nascondendo in un cespuglio o sotto una roccia, no?"
S["fe5415ee"] = "Solo un bastone? Vuoi che ti mostri cosa sa fare 'solo un bastone'?"
S["fe5806db"] = "Però le energie che ne risultano potrebbero collassare e provocare un flusso di energia da farti venire l'emicrania per settimane."
S["fe5e0993"] = "Bijou perso! SQUAAK! *coff*"
S["fe5fee6f"] = "Non approvo i tuoi esperimenti, Gerard, ma devo ammettere che i risultati sono notevoli. Cosa le hai fatto esattamente?"
S["fe60c055"] = "Le pelli più resistenti vengono dai kodo che si sono distesi in questa terra desolata per l'ultimo riposo."
S["fe65657d"] = "%s ha fame..."
S["fe65f3b2"] = "Qual è questo compito?"
S["fe663508"] = "Ho bisogno di addestramento, Nissa."
S["fe728bc4"] = "Il sangue di %s schizza in aria!"
S["fe7e4215"] = "Le energie allineate positivamente, quando si scontrano con quelle a carica negativa, non si annullano a vicenda."
S["fe8c885f"] = "Cerchi le benedizioni del Signore del Vento?"
S["fe902647"] = "Finiscilo..."
S["fe90f2d4"] = "Sì! Sono guarito! Sono guar... ooh, mi sono alzato troppo in fretta!"
S["fe927670"] = "Mmh... Posso collegare qui questo filo e alimentare l'ingranaggio fizzletan, ma poi all'idroflangia servirà una fonte di energia alternativa... Forse potrei... Oh, ciao! Ehi, vuoi aiutarmi a provare una nuova invenzione?"
S["fe92ae47"] = "Ah sì, e consegnati puntuali. Come sempre, è un piacere fare affari con te, Corbett."
S["fe9d6820"] = "Si dice che a nord viva un potente mago umano; veglia sulla regione, per qualche motivo che non si conosce. Io non ci sono $Gstato:stata; di persona, ma pare che i visitatori siano ben accolti e che possano perfino guadagnarsi il suo favore, se sono disposti a sbrigargli qualche commissione."
S["fe9dac3b"] = "Non credo. Rimblat ha già dimostrato che dalla terra squarciata può nascere nuova vita. Adesso dobbiamo trovare il modo di ripetere quella crescita e, soprattutto, di farla durare.$B$BFinché resto qui, offro i miei servigi anche agli avventurieri che entrano a Naxxramas."
S["fea22367"] = "Combatteremo insieme questi mostri! Anche i Difensori di Nighthaven sono con noi. Combatteranno fino alla morte, se glielo si chiede. Ora, presto, dobbiamo ricacciare queste aberrazioni nell'Incubo. Distruggeteli tutti!"
S["feadf8c1"] = "Di nuovo la campana, che suono dolce."
S["feb2a864"] = "So che sei lì, ladro. Lascia la mia casa o raggiungi gli altri ai piedi dell'albero del mondo."
S["feb2bca2"] = "$N, che la tua morte sia d'esempio per tutti coloro che sfidano la Defias Brotherhood!"
S["feb3495a"] = "La vostra base è perduta, miseri mortali!"
S["febb90ec"] = "Be', ora o mai più, suppongo. Ricorda, una volta arrivati sani e salvi alla strada, torna da Terenthis per fargli sapere che siamo fuggiti."
S["febed518"] = "La pestilenza dello Scourge è quasi alla svolta; ancora qualche calderone sabotato e ce la faremo! Non mancare di fare la tua parte!"
S["fec9d358"] = "Ho la chiave di terre senza catene! Inseguimi e vedrai bene!"
S["fed2b8ca"] = "Hai dimostrato abilità nell'imparare il nostro mestiere. Hai anche la determinazione per portare a termine una missione per conto mio?"
S["fed7c591"] = "Dov'è il tuo Medaglione di Rango, $Gpiccolo:piccola;? Senza una prova del titolo non puoi parlare con un Duca..."
S["fee11dbd"] = "%s getta sul tavolo la lettera di Anton."
S["fee2aeb2"] = "Aiuto!!! Toglietemi di dosso queste cose, così posso finire il lavoro!"
S["fee53fc5"] = "Ancora... Ancora anime!"
S["feed5e9c"] = "STOLTO! Pretendi di avere anche solo un decimo del potere che avevi durante la Rivolta? Le nazioni erano unite, eppure furono quasi divorate da un'ombra di Hakkar. Non hai alcuna speranza."
S["fef09e3b"] = "Può sembrare semplice, un grosso bastone con un enorme peso in cima. Ma quando dietro c'è la forza di un tauren, questo bastone può sfondare muri di pietra."
S["fef9fa89"] = "Ladri! Furfanti! Canaglie! Venite ad affrontare i miei cuscinoni giganti!"
S["fefa08ee"] = "Perché mai vorresti farmi del male!? Vieni. Amici possiamo essere!"
S["fefdf8d6"] = "Se un guanto è troppo grande, ti calza ancora come un guanto?"
S["fefecd0f"] = "State indietro! I bambini non dovrebbero stare qui! Via, bambino!"
S["feff98b0"] = "È stata Umi, vero?! Mi fa sempre degli scherzi, e adesso ha coinvolto anche te!"
S["ff01b325"] = "Captain Balinda Stonehearth guida le forze di prima linea dell'Alleanza. Si trova nello Stonehearth Outpost, nella parte settentrionale del Field of Strife.$B$BBalinda è stata uccisa."
S["ff052274"] = "Grazie, Signora Brightbeard!"
S["ff0fc2d2"] = "Fammi dare un'occhiata alla tua merce."
S["ff153cb5"] = "Un tempo queste caverne erano un tempio, una promessa di rinascita nelle Barrens. Ora sono le sale degli incubi."
S["ff1e0f37"] = "Bene, a quanto pare abbiamo un po' di tempo libero. L'Orda ha completato la raccolta, e si sta preparando tutto per la spedizione finale verso Silithus. Aspettiamo solo che l'Alleanza finisca la sua. Dovresti andare a chiedere a quel loro piccolo, sciocco ambasciatore a che punto sono."
S["ff39a332"] = "Stavolta ti hanno proprio fregato, $Gragazzo:ragazza;!"
S["ff46c515"] = "Se avessi una moneta di rame per ogni tua grande impresa, sarei $Gun coboldo ricco:una coboldo ricca;!"
S["ff4a7d21"] = "Fuggire non vi servirà a niente, mortali!"
S["ff4d1844"] = "Carne fresca!"
S["ff4f4146"] = "Be', trovi Theridan o Maldryn vicino al pozzo lunare, ne The Park. Ti basta andare nella parte occidentale di Stormwind, a nord del Mage District ma a ovest di Cathedral Square."
S["ff50d26a"] = "Solo i nani potevano mandare da Ironforge uno specialista dell'estrazione mineraria a spiegarci come si scava in miniera. Che ci vorrà mai a prendere un piccone e scalfire un po' di roccia? Be', visto che è qui, probabilmente è comunque da lui che dovresti andare. Si chiama Gelman e sta laggiù nel Dwarven District."
S["ff55bff4"] = "Bijou sa dove sono nascosti i tesori."
S["ff56272d"] = "Tre settimane dopo mi sono svegliato in un letto a Northshire, e non mi ricordo un accidente."
S["ff57da32"] = "Che le benedizioni della Madre Terra siano su di te."
S["ff6374dc"] = "Aspettano di schiacciare la vita dei nostri piccoli. Di uccidere chiunque si trovi sul loro cammino. Questo fanno per il loro dio."
S["ff642427"] = "Ho dovuto andare a requisire un Abominio... un Abominio!"
S["ff64414b"] = "Tu pezzi di ricambio! Noi fare più Scourge in necropoli."
S["ff6da805"] = "Presto, la tua sete di distruzione sarà saziata."
S["ff7c247e"] = "Fammi vedere cosa sai fare, $Gpivello:pivella;!"
S["ff7ce954"] = "Oh, Darrowshire! Darei mille vite per te!"
S["ff7edf04"] = "Il mio sogno è servire un giorno sotto il tuo comando, $GMaestro:Maestra; $N. Sempre che tu mi ritenga mai $Gdegno:degna; di tali cose..."
S["ffa10620"] = "Gli Al'Aketh ne sono un sintomo. Per molti versi sono uno specchio oscuro del cuore dei Windshapers. Molti di noi credono che la colpa sia nostra se gli spiriti ci stanno abbandonando."
S["ffae07e1"] = "Mmm, chissà cosa c'è da questa parte?"
S["ffb5bbfb"] = "No! Mai, non oserei mai!"
S["ffba0091"] = "Ah, $Gbravo:brava; $N. Ora vediamo quale storia raccontano queste teste..."
S["ffbdb0e6"] = "AttentYOUR_GENDER(o;a) a dove metti i piedi là fuori. Molti cercatori di avventure non sono più tornati dalla palude. Hic!"
S["ffc198e8"] = "Ora i preparativi sono completi, $C. Aspettiamo che l'ultimo materiale venga mandato a Silithus, cosa che dovrebbe avvenire in meno di un giorno. Poi, finita l'organizzazione lì, qualcuno dovrà farsi avanti e suonare il gong sulla Scarab Dais con lo Scepter of the Shifting Sands. È allora che comincerà la guerra di Ahn'Qiraj. Che la Madre Terra vegli allora su tutti noi."
S["ffc1aa6e"] = "Raddoppierò gli sforzi."
S["ffcd1c4b"] = "Un tempo l'Arathi Basin era casa nostra, e con il tuo aiuto lo sarà di nuovo! Ci darai una mano, $C?"
S["ffd28b03"] = "Prima di diventare $Guno dei miei allievi:una delle mie allieve;, devi migliorare nel preparare pozioni. Intanto forse possono aiutarti Sylvanna Forestmoon o Milla Fairancora, lì vicino."
S["ffd4ad7a"] = "Lok'tar, $C, ho informazioni importanti! Sta per scoppiare una guerra ad Ahn'Qiraj e dobbiamo prepararci. Sono qui per raccogliere tutto il thick leather su cui riesco a mettere le mani. Per ora ne abbiamo una parte, ma il Capoguerra mi ha affidato il compito di raccoglierne molto di più. Come vedi, sono un po' a corto."
S["ffe366e1"] = "Centro! Quel maledetto nano non sa di cosa parla. L'unica cosa che non va nel fucile di Grumlar è la mira di Grumlar."
S["ffe8f6d2"] = "Cosa sto facendo? Ti manca la visione, forse? Sono $Gun sognatore:una sognatrice;, $Gmio buon signore:mia buona signora;, e sogno un futuro migliore per tutti noi. $GUn visionario:Una visionaria;, ecco cosa sono, è chiaro.$B$BMa c'è chi prova a tenerci impantanati nella banalità. Quando ho detto ad Arch Druid Staghelm che ero $Gun sognatore:una sognatrice;, mi ha risposto: \"Beh, il mondo ha bisogno anche di chi scava i fossi.\"$B$BFinché le catene della banalità non ci verranno strappate di dosso, darò una mano al Cenarion Circle spostando di qua e di là questi mucchi di terra."
S["fffd5049"] = "Hai l'aria di $Guno:una; che cerca avventure. Io ne avevo avute abbastanza quando noi troll siamo arrivati qui. Ora vivo alla giornata e insegno ad altra gente ad affrontarle al posto mio."
